            CREATE TABLE IF NOT EXISTS `translations` (
                `translation` VARCHAR(255) PRIMARY KEY,
                `title` VARCHAR(255),
                `license` TEXT
            );
            

            VALUES ('NorSMB', '# NorSMB: Studentmållagsbibelen frå 1921', 'Public Domain')
            ON DUPLICATE KEY UPDATE
                `title` = VALUES(`title`),
                `license` = VALUES(`license`);
            

            CREATE TABLE `NorSMB_books` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `name` VARCHAR(255)
            );
            

            CREATE TABLE `NorSMB_verses` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `book_id` INT,
                `chapter` INT,
                `verse` INT,
                `text` TEXT,
                FOREIGN KEY (book_id) REFERENCES `NorSMB_books`(id)
