INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'I upphavet skapte Gud himmelen og jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Og jordi var aud og øydi, og myrker låg yver djupet; men Guds ande sveiv yver vatni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Då sagde Gud: «Det verte ljos!» So vart det ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Og Gud såg at ljoset var godt. Og Gud skilde ljoset frå myrkret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Og Gud kalla ljoset dag, og myrkret kalla han natt. Og det vart kveld, og det vart morgon, fyrste dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Då sagde Gud: «Det verte ein vid kvelv midt i vatni: han skal skilja vatn ifrå vatn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'So gjorde Gud kvelven, og skilde vatnet som er nedunder kvelven, frå det vatnet som er uppyver kvelven. Og det vart so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Og Gud kalla kvelven himmel. Og det vart kveld, og det vart morgon, andre dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Då sagde Gud: «Vatni under himmelen samle seg på ein stad, so det turre landet kjem fram!» So vart det so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Og Gud kalla det turre landet jord, og vatni som hadde samla seg, kalla han hav. Og Gud såg det var godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Då sagde Gud: «Jordi bere fram gras og grode, urter som sår seg, og frukttre, som ber frukt med deira frø i, utyver jordi, kvart etter sitt slag!» Og so vart det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Og jordi bar fram gras og grode, urter som sår seg, kvar etter sitt slag, og tre som ber frukt med frø i, kvart etter sitt slag. Og Gud såg det var godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Og det vart kveld, og det vart morgon, tridje dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Då sagde Gud: «Det verte skinande ljos på himmelkvelven: dei skal skilja dagen frå natti. Og dei skal vera til merke, og skipa tider og dagar og år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Og dei skal vera til ljos på himmelkvelven, og lysa utyver jordi.» Og so vart det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Og Gud gjorde dei tvo store ljosi, det større ljoset til å råda um dagen, og det mindre ljoset til å råda um natti, og so stjernorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Og Gud sette deim på himmelkvelven til å lysa utyver jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'og til å styra dagen og natti, og skilja ljoset frå myrkret. Og Gud såg det var godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Og det vart kveld, og det vart morgon, fjorde dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Då sagde Gud: «Det skal yrja og aula med liv i vatnet, og fuglar skal fljuga yver jordi, uppunder himmelkvelven.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'So skapte Gud dei store sjødyri, og alt livande som det yr og kryr av i vatnet, kvart etter sitt slag, og alle fljugande fuglar, kvart etter sitt slag. Og Gud såg det var godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Og Gud velsigna deim og sagde: «De skal veksa og aukast og fylla vatnet i havi, og fuglarne skal aukast på jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Og det vart kveld, og det vart morgon, femte dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Då sagde Gud: «Jordi gjeve utor seg kvikjende av kvart slag, bufe og krek og villdyr, kvart etter sitt slag.» Og so vart det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Og Gud gjorde dei ville dyri, kvart etter sitt slag, og bufe av kvart eit slag, og alle dei dyr som krek på marki, kvart etter sitt slag. Og Gud såg det var godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Då sagde Gud: «Lat oss skapa menneskje i vår likning, so dei vert bilætet vårt! Dei skal råda yver fiskarne i havet og yver fuglarne under himmelen og yver feet og yver all jordi og yver alt liv som leikar på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'So skapte Gud menneskjet i si likning, i Guds likning skapte han det, til kar og kvinna skapte han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Og Gud velsigna deim, og Gud sagde til deim: «De skal veksa og aukast og fylla jordi og leggja henne under dykk, og råda yver fiskarne i havet og yver fuglarne under himmelen og yver kvart dyr som røyver seg på jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Og Gud sagde: «Sjå, eg gjev dykk alle urter som sår seg, alle som finst på jordi, og alle tre med alde som sår seg: for dykk skal det vera til føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Og alle dyri på jordi og alle fuglarne under himmelen og alt det som yrer på jordi, alt som hev ande og liv, gjev eg alt det grøne graset til føda.» Og so vart det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Og Gud skoda alt han hadde gjort, og sjå: det var ovleg godt. Og det vart kveld, og det vart morgon, sette dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'So vart himmelen og jordi fullferda, med heile sin her.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Og den sjuande dagen fullferda Gud det verket han gjorde, og kvilde, den sjuande dagen, etter alt verket han hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Og Gud velsigna den sjuande dagen, og gjorde honom heilag; for den dagen kvilde han etter alt sitt verk, det som Gud gjorde då han skapte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dette er soga um himmelen og jordi, då dei vart skapte. Den tid Herren Gud gjorde jord og himmel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'då fanst det endå ikkje ei grøn buska på jordi, og endå hadde ikkje eit grasstrå runne. For Herren Gud hadde ikkje late det regna på jordi, og der var ingen mann til å dyrka marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Då steig det upp eim or jordi, og dogga all marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Og Herren Gud skapte mannen av mold or marki, og bles livsens ande i nosi hans, og mannen fekk ånd og liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Og Herren Gud gjorde ein hage i Eden, langt aust, og der sette han mannen som han hadde skapt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Og Herren Gud let alle slag tre veksa upp av jordi, gilde å sjå til og gode å eta av, og midt i hagen livsens tre og det treet som gjev vit på godt og vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Og det gjeng ei elv ut ifrå Eden. Ho vatnar hagen, og sidan kløyver ho seg i fire greiner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Den fyrste heiter Pison. Det er den som renn kringum heile Havilalandet, der som det er gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Og gullet i det landet er godt. Der er det dei finn bedolahkvåda og sjohamsteinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Og den andre elvi heitte Gihon; det er den som renn kringum heile Kusjland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Og den tridje elvi heiter Hiddekel; det er den som gjeng framanfor Assur. Og den fjorde elvi, det er Frat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Og Herren Gud tok mannen og sette honom i Eden til å dyrka og varna hagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Og Herren Gud sagde mannen fyre og baud: «Du må gjerne eta av alle trei i hagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Men det treet som gjev vit på godt og vondt, det må du ikkje eta av; for den dag du et av det, skal du døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Og Herren Gud sagde: «Det er ikkje godt at mannen er einsleg. Eg vil gjeva honom ei hjelp som høver for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Og Herren Gud tok av jordi og skapte alle dyri på marki og alle fuglarne i lufti, og han leidde deim fram til mannen og vilde sjå kva han kalla deim; og som mannen kalla kvart kvikjende, so skulde det heita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Og mannen gav alt bufeet namn, og fuglarne i lufti og alle villdyri, men for ein mann fann han ingi hjelp som var høveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Då let Herren Gud ein tung svevn koma på mannen, og medan han sov, tok han eit av sidebeini hans, og fyllte atter med kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Og Herren Gud bygde ei kvinna av det sidebeinet han tok av mannen, og leidde henne fram til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Då sagde mannen: «Dette er då bein av mine bein og kjøt av mitt kjøt. Ho skal kallast kjerring; for ho er teki av ein kar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Difor skal mannen skiljast med far sin og mor si og halda seg hjå kona si, og dei skal verta eitt kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Og dei var nakne, både mannen og kona hans, og blygdest ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Men ormen var sløgaste av alle villdyri, som Herren Gud hadde gjort, og han sagde med kona: «Kann det vera råd at Gud hev sagt, at de ikkje må eta av alle trei i hagen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Og kona sagde med ormen: «Me kann eta av frukterne på trei i hagen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'men frukti på det treet som er midt i hagen - «den,» sagde Gud, «må de ikkje eta av og ikkje røra; for då skal de døy.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Då sagde ormen med kona: «De skal ikkje døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Men Gud veit vel at den dag de et av frukti, skal augo dykkar opnast, og de skal verta liksom Gud og skyna godt og vondt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Og kona såg at treet var godt å eta av, og tykte det var ein hugnad for augo, og eit gildt tre, med di det kunde gjera ein klok. So tok ho av frukti og åt, og gav mannen sin og med seg, og han åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Då fekk dei augo upp båe tvo, og gådde at dei var nakne. Og dei nesta i hop lauv av fiketreet og sveipte kring livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Og dei høyrde Herren Gud som gjekk i hagen, då det leid imot kvelden og tok til å svalna. Og mannen og kona hans løynde seg for Guds augo millom trei i hagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Då ropa Herren Gud på mannen og sagde til honom: «Kvar er du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Og han svara: «Eg høyrde deg i hagen. Då vart eg rædd, av di eg var naken, og so løynde eg meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Då sagde han: «Kven sagde deg det, at du er naken? Hev du ete av det treet som eg sagde deg at du ikkje måtte eta av?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Og mannen sagde: «Kona som du gav meg til å vera saman med, ho gav meg av treet, og eg åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Då sagde Herren Gud til kona: «Kva er det du hev gjort!» Og kona sagde: «Ormen lokka meg, og eg åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Då sagde Herren Gud til ormen: «For di du gjorde det, skal du vera forbanna millom alt bufeet og millom alle villdyri. På buken skal du skrida, og mold skal du eta, alle dine livedagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Og hat vil eg setja millom deg og kvinna, og millom di ætt og hennar ætt. Dei skal krasa ditt hovud, og du skal hogga deim i hælen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Og til kona sagde han: «Stor vil eg gjera di møda, so tidt du er umhender. Med verk og vande skal du eiga born, og etter mannen din skal du stunda, og han skal hava velde yver deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Og til mannen sagde han: «For di du lydde kona di, og åt av det treet som eg forbaud deg å eta av, so skal jordi vera forbanna for di skuld. Med møda skal du næra deg av henne alle dine livedagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Torn og tistel skal ho bera deg, og du skal eta urterne på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Med sveiten i andlitet skal du eta ditt brød, til dess du fer i jordi att; for av henne er du teken. For mold er du, og til moldi skal du attende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Og mannen kalla kona si Eva; for ho vart mor åt alle dei livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Og Herren Gud gjorde skinnkjolar til mannen og kona hans og klædde deim med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Og Herren Gud sagde: «Sjå, mannen hev vorte som ein av oss til å skyna godt og vondt. Berre han no ikkje retter ut handi, og tek av livsens tre og, og et, og liver i all æva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Og Herren Gud viste honom ut or Edens hage, og sette honom til å dyrka jordi, som han var teken utav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Og han dreiv mannen burt, og framfyre Edens hage sette han kerubarne med logande sverd, som dei let brå att og fram: dei skulde vakta vegen til livsens tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Og Adam budde saman med Eva, kona si, og ho vart med barn, og åtte Kain. Då sagde ho: «Ein son hev eg fenge av Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Sidan åtte ho Abel, bror hans. Og Abel vart sauehyrding, og Kain var jorddyrkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Og det hende, då det leid av ei tid, at Kain bar fram åt Herren ei gåva av grøda på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Og Abel bar og fram ei gåva, og han gav av frumselambi or fenaden sin og feittet deira. Og Herren såg blidt til Abel og gåva hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'men ansa ikkje Kain og hans gåva. Då vart Kain brennande harm, og stirde nedfyre seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Og Herren sagde til Kain: «Kvi er du harm, og kvi stend du og stirer nedfyre deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Hev du godt i tankar, kann du ikkje då lyfta upp augo? Og hev du ikkje godt i tankar, so ligg syndi framfyre døri og lurer. Ho trår etter deg, men du lyt halda henne i age.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Og Kain sagde det med Abel, bror sin. Og det gjekk so til, medan dei var utpå marki, at Kain rauk på Abel, bror sin, og slo honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Då sagde Herren til Kain: «Kvar er Abel, bror din?» Og han svara: «Eg veit ikkje. Skal eg gjæta bror min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Då sagde han: «Kva hev du gjort! Høyr, blodet åt bror din ropar til meg frå jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Og no skal du vera bannlyst frå den jordi som let upp munnen og tok imot blodet åt bror din av di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Når du dyrkar marki, skal ho ikkje meir gjeva deg sin avle. Heimlaus og fredlaus skal du vera på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Då sagde Kain til Herren: «Skuldi mi er større enn eg kann bera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Sjå, du driv meg i dag ut or landet, og eg lyt løyna meg for dine augo og vera heimlaus og fredlaus på jordi, og kven som finn meg, kjem til å slå meg i hel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Då sagde Herren til honom: «Nei! for drep nokon Kain, so skal det hemnast sju gonger.» Og Herren gav Kain eit merke, so dei ikkje skulde slå honom i hel, kven som fann honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'So hadde Kain seg utor Herrens augo, og busette seg i eit land som heiter Nod, austanfor Eden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Og Kain budde saman med kona si, og ho vart med barn, og åtte Hanok. Sidan tok han seg til å byggja ein by, og kalla byen Hanok, etter son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Og Hanok vart far til Irad; og Irad fekk sonen Mehujael, og Mehujael fekk sonen Metusael, og Metusael fekk sonen Lamek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Og Lamek tok seg tvo konor. Den eine heitte Ada, og den andre heitte Silla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Og Ada åtte sonen Jabal. Frå honom er dei ætta dei som bur i tjeldbuder og held buskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Og bror hans heitte Jubal. Frå honom er dei ætta all dei som spelar på harpa og fløyta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Og Silla åtte og ein son. Han vart kalla Tubalkain; og han smidde alle slag bitjarn, både av jarn og av kopar. Og syster åt Tubalkain heitte Na’ama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Og Lamek kvad til konorne sine: «Ada og Silla, høyr mine ord, Lameks konor, lyd på mi røyst! Ein mann drep eg for kvart sår, og ein svein for kvar skråma eg fær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'For Kain skal sju gonger hemnast, men Lamek sju-ti og sju.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Og Adam budde med kona si som han fyrr hadde gjort, og ho åtte ein son, og kalla honom Set. «For Gud hev sett meg ein annan son i staden hans Abel,» sagde ho, «for di Kain slo honom i hel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Og Set fekk og ein son, og kalla honom Enos. Då tok dei til å kalla på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dette er boki um Adams-ætti: Den dagen då Gud skapte menneskjet, skapte han det i Guds likning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Til kar og kvinna skapte han deim. Og han velsigna deim, og kalla deim menneskje den dagen då dei vart skapte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Då Adam var hundrad og tretti år gamall, fekk han ein son som var so lik honom som det skulde vore hans eige bilæte, og han kalla honom Set.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Og etter han hadde fenge Set, livde han endå åtte hundrad år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Og alle livedagarne hans Adam vart ni hundrad og tretti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Då Set var hundrad og fem år gamall, fekk han sonen Enos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Og etter han hadde fenge Enos, livde han endå åtte hundrad og sju år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Og alle dagarne hans Set vart ni hundrad og tolv år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Då Enos var nitti år gamall, fekk han sonen Kenan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Og etter han hadde fenge Kenan, livde han endå åtte hundrad og femtan år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Og alle dagarne hans Enos vart ni hundrad og fem år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Då Kenan var sytti år gamall, fekk han sonen Mahalalel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Og etter han hadde fenge Mahalalel, livde han endå åtte hundrad og fyrti år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Og alle dagarne hans Kenan vart ni hundrad og ti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Då Mahalalel var fem og seksti år gamall, fekk han sonen Jared.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Og etter han hadde fenge Jared, livde han endå åtte hundrad og tretti år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Og alle dagarne hans Mahalalel vart åtte hundrad og fem og nitti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Då Jared var hundrad og tvo og seksti år gamall, fekk han sonen Enok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Og etter han hadde fenge Enok, livde han endå åtte hundrad år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Og alle dagarne hans Jared vart ni hundrad og tvo og seksti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Då Enok var fem og seksti år gamall, fekk han sonen Metusalah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Og etter han hadde fenge Metusalah, gjekk han på Guds veg i tri hundrad år, og han fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Og alle dagarne hans Enok vart tri hundrad og fem og seksti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Enok gjekk på Guds veg, og brått vart han burte; for Gud tok honom til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Då Metusalah var hundrad og sju og åtteti år gamall, fekk han sonen Lamek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Og etter han hadde fenge Lamek, livde han endå sju hundrad og tvo og åtteti år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Og alle dagarne hans Metusalah vart ni hundrad og ni og seksti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Då Lamek var hundrad og tvo og åtteti år gamall, fekk han ein son,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'og kalla honom Noah, og sagde: «Han skal hugga oss i arbeidet vårt, og i alt vårt slit og slæp på den jordi som Herren hev forbanna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Og etter han hadde fenge Noah, livde han endå fem hundrad og fem og nitti år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Og alle dagarne hans Lamek vart sju hundrad og sju og sytti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Då Noah hadde fyllt fem hundrad år, fekk han sønerne Sem og Kham og Jafet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Og det hende, då manneætti tok til å aukast på jordi, og dei fekk døtter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'då såg gudssønerne at mannedøtterne var væne, og tok til konor deim som dei kåra seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Då sagde Herren: «Ikkje skal min ande bu æveleg i mannen, for di um dei hev forset seg. Han er kjøt, og dagarne hans skal vera hundrad og tjuge år.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'I den tidi var det risar på jordi, og seinare og, av di gudssønerne jamleg gav seg i lag med mannedøtterne, og fekk søner med deim; det var kjemporne, dei namngjetne, som var til fyrr i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Og Herren såg at vondskapen var stor hjå manneætti på jordi, og at alt dei tenkte og emna på i hjarto sine, det var berre vondt all dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Då angra Herren at han hadde skapt mannen på jordi, og han var full av sorg i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Og Herren sagde: «Eg vil tyna menneskja som eg hev skapt, og rydja henne ut av jordi, både menneskje og dyr og krek og fuglarne i lufti; for eg angrar at eg hev skapt deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Men Noah fann nåde hjå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dette er soga um Noah og ætti hans: Noah var ein rettvis og ulastande mann millom sine samtidingar; Noah gjekk på Guds veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Og Noah fekk tri søner, Sem og Kham og Jafet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Men jordi vart verre og verre i Guds augo, og jordi vart full av urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Og Gud skoda jordi, og sjå: ho var utskjemd; for alt kjøt hadde skjemt seg ut med si åtferd på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Då sagde Gud til Noah: «Eg hev sett meg fyre at eg vil gjera ende på alt kjøt. For dei hev fyllt upp jordi med urett. Og no vil eg øydeleggja både deim og jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Gjer deg ei ark av gofertre. Med kovar og kot skal du innreida arki, og bræda henne med bik både innan og utan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Soleis skal du gjera henne: Tri hundrad alner lang skal arki vera, og femti alner breid, og tretti alner høg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Øvst på arki skal du gjera ein glugg, som når ei aln ned på veggen. Og døri skal du setja på den eine sida. Du skal gjera arki trihøg, med mange rom i kvar høgd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Og eg vil lata storflodi koma med vatn yver jordi, og tyna alt kjøt under himmelen som det er livsande i. Alt som er på jordi, skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Men med deg vil eg gjera ei pakt, og du skal ganga inn i arki, du og sønerne dine og kona di og konorne åt sønerne dine med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Og av alt som liver, alt kjøt, skal du taka tvo av kvart slag med inn i arki, so du held deim i live med deg. Han og ho skal dei vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Av alle slag fuglar og av alle slag dyr og av alt kreket på marki skal par og par koma inn til deg, so dei kann halda liv i seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Og du skal sanka av all den mat som etande er, og samla det til deg: for deg og for deim skal det vera til føda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Og Noah gjorde so; han gjorde i alle måtar so som Gud sagde honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'So sagde Herren til Noah: «Gakk inn i arki, du og heile ditt hus! For deg hev eg røynt for ein rettvis millom deim som no liver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Av alle reine dyr skal du taka deg ut sju par, han og ho, og av dei dyri som ikkje er reine, eitt par, han og ho;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'like eins av fuglarne i lufti sju par, han og ho, so elde kann haldast i live utyver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'For um sju dagar vil eg lata det regna på jordi i fyrti jamdøger, og rydja ut av verdi kvart liv eg hev skapt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Og Noah gjorde i alle måtar so som Herren sagde honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noah var seks hundrad år gamall, då storflodi kom med vatn yver jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Då gjekk Noah og sønerne hans og kona hans og konorne åt sønerne hans med honom inn i arki, og berga seg for flaumen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Og av dei reine dyri, og av dei dyri som ikkje er reine, og av fuglarne, og av alt det som krelar på marki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'kom par og par, han og ho, inn i arki til Noah, so som Gud hadde sagt Noah fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Og det hende, då dei sju dagarne var lidne, då kom vatnet fløymande yver jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Den syttande dagen i den andre månaden i det året då Noah fyllte seks hundrad år, den dagen brast alle brunnar i stordjupet, og himmellukorne let seg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Og regnet fossa ned på jordi i fyrti dagar og fyrti næter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Denne same dagen gjekk Noah, og Sem og Kham og Jafet, sønerne hans Noah, og kona hans Noah, og dei tri sonekonorne hans med deim inn i arki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'dei og alle villdyr, kvart etter sitt slag, og alt bufe, kvart etter sitt slag, og alt krek som krelar på jordi, kvart etter sitt slag, og alle fuglar, kvar etter sitt slag: alt som kvitrar, alt som hev vengjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Og dei kom inn i arki til Noah, tvo og tvo av alt kjøt som det er livsande i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Og dei som kom inn, var han og ho av alt kjøt, so som Gud hadde sagt honom fyre. Og Herren let att etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'So kom flodi veltande yver jordi i fyrti dagar, og vatnet auka, og lyfte arki, so ho flaut upp ifrå jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Og vatnet voks og auka uhorveleg utyver jordi, og arki dreiv burtyver vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Og vatnet steig høgre og høgre yver jordi, so alle dei høge fjelli under heile himmelen vart gøymde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Femtan alner yver jordi steig vatnet, og fjelli vart gøymde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Då døydde alt kjøt som røyvde seg på jordi, både fuglar og bufe og villdyr og alt det som urde og krydde på jordi, og alt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alt som hadde livsandedrag i si nos, alt som var på det turre landet, laut døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'So rudde han ut kvart liv som på jordi fanst, både folk og fe og krek og fuglarne i lufti. Dei vart utrudde av verdi, og att vart berre Noah og det som var med honom i arki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Og vatnet flødde yver jordi i hundrad og femti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Då kom Gud i hug Noah og alle villdyri og alt bufeet som var med honom i arki, og Gud let ein vind fara yver jordi, og vatnet fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Og brunnarne i djupet og lukorne på himmelen stengdest, og regnet frå himmelen stogga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Og vatnet drog seg etter kvart attende frå jordi, og vatnet minka, då hundrad og femti dagar var lidne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Og den syttande dagen i den sjuande månaden tok arki grunn og stana på Araratfjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Og vatnet minka meir og meir, alt til den tiande månaden: Den fyrste dagen i den tiande månaden synte fjelltindarne seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Og det hende, då fyrti dagar var lidne, at Noah let upp vindauga på arki, som han hadde gjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'og slepte ut ein ramn, og den flaug til og frå, til vatnet hadde torna burt av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'So sende han ei duva ut ifrå seg, og vilde sjå um vatnet hadde sige undan frå marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Men duva fann ingen kvilestad for foten sin, og kom attende til honom i arki; for det stod vatn yver all jordi. Då rette han ut handi, og tok henne, og hadde henne inn til seg i arki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'So bia han endå sju dagar, og sende so duva ut att or arki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Og då det leid til kvelds, kom duva heim til honom, og sjå: då hadde ho eit grønt oljetrelauv i nebben. Då skyna Noah at vatnet hadde sige undan frå jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Men han drygde endå sju dagar til. So let han ut duva, og då kom ho ikkje att til honom meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Og det bar so til, at den fyrste dagen i den fyrste månaden i det seks hundrad og fyrste året, då hadde vatnet torna burt av jordi. Og Noah tok taket av arki, og såg utyver, og sjå, marki var turr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Og den sju og tjugande dagen i den andre månaden var jordi heiltupp turr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Då tala Gud til Noah og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '«Gakk ut or arki, du og kona di og sønerne dine og konorne åt sønerne dine med deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Og alle dei dyr som er hjå deg, alt kjøt, både fuglarne og feet og alt kreket som krelar på jordi, skal du hava med deg ut, og dei skal yrja på jordi, og alast og aukast utyver jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'So gjekk Noah ut, og sønerne hans og kona hans og konorne åt sønerne hans med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Og alle dyri og alt kreket og alle fuglarne, alt som røyver seg på jordi, gjekk ut or arki, kvart etter sitt slag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Og Noah bygde Herren eit altar, og tok utav alt det reine feet og utav alle dei reine fuglarne, og ofra brennoffer på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Og Herren kjende den gode gimen, og Herren sagde i sitt hjarta: «Eg vil aldri meir forbanna jordi for menneskja skuld; for mannehjarta emnar berre på vondt, alt ifrå ungdomen. Og eg vil aldri meir drepa alt liv, so som eg no gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Heretter skal sånad og skurd, og kulde og hite, og sumar og vinter, og dag og natt aldri trjota, so lenge som jordi stend.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Og Gud velsigna Noah og sønerne hans og sagde til deim: «De skal veksa og aukast og fylla jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Age og otte skal dei bera for dykk alle dyri på jordi og alle fuglarne under himmelen, alt som krelar på marki og alle fiskarne i havet: i dykkar hender er dei gjevne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alt som røyver seg og liver, for dykk skal det vera til føda. Som eg gav dykk dei grøne urterne, so gjev eg dykk alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Men kjøt med liv, med blodet i, det må de ikkje eta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Og berre dykkar eige blod vil eg hemna: eg vil krevja det att av kvart dyr, og av menneskjet og; kvar manns liv vil eg krevja att av hans bror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Den som tek manns blod, hans blod skal menner taka; for i Guds likning skapte han mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Men de skal veksa og aukast; de skal yrja på jordi og auka dykk på henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Og Gud sagde til Noah og sønerne hans, som var med honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '«Sjå, eg vil gjera ei pakt med dykk og med etterkomarane dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'og med kvart eit livande liv som hjå dykk er, både fuglar og fe og alle dei ville dyr som er hjå dykk, alle som gjekk ut or arki, alt som liver på jordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ei pakt vil eg gjera med dykk, og aldri meir skal alt livande tynast i flaumen, og aldri meir skal det koma ei flod som legg jordi i øyde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Og Gud sagde: «Dette er merket på pakti eg set millom meg og dykk og kvart livande liv som hjå dykk er, til æveleg tid:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Bogen min set eg i skyi: han skal vera eit merke på pakti millom meg og jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Og so tidt eg let skyer skyggja yver jordi, og bogen ter seg i skyi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'då skal eg koma i hug den pakti som er millom meg og dykk og kvart livande liv av alt kjøt, og vatnet skal aldri meir verta ei flod som tyner alt kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'So skal bogen standa i skyi, og eg sjå honom og minnast ævordomspakti millom Gud og kvart livande liv av alt kjøt som til er på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dette,» sagde Gud til Noah, «er merket på den pakt eg hev sett millom meg og alt kjøt som til er på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Og Noahs-sønerne, som gjekk ut or arki, det var Sem og Kham og Jafet. Og Kham var far åt Kana’an.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Desse tri var sønerne hans Noah, og frå deim hev alle folk på jordi greina seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Og Noah var jorddyrkar, og han var den fyrste som gjorde ein vinhage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Og han drakk av vinen, og vart drukken, og so klædde han seg naken midt inni tjeldbudi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Og då Kham, far åt Kana’an, såg far sin liggja naken, gjekk han ut og sagde det med båe brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Då tok Sem og Jafet ei kåpa og lagde på herdarne sine, og gjekk inn baklengs, og breidde kåpa yver far sin; og dei vende augo burt, so dei såg ikkje blygsli åt far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Då so Noah vakna av ruset, fekk han vita kva den yngste sonen hans hadde gjort imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Då sagde han: «Forbanna skal Kana’an vera! Den lågaste av alle trælar skal han vera for sine brøder.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'So sagde han: «Lova vere Herren, Sems Gud, og Kana’an vera hans træl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Gud gjere det romt for Jafet! Under tjeldi hans Sem skal han bu, og Kana’an vere hans træl.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Etter storflodi livde Noah endå tri hundrad og femti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Og alle dagarne hans Noah vart ni hundrad og femti år. So døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Dette er dei ætterne som hev kome frå sønerne hans Noah, Sem og Kham og Jafet; dei fekk søner, etter storflodi hadde vore:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Sønerne hans Jafet var Gomer og Magog og Madaj og Javan og Tubal og Mesek og Tiras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Og sønerne hans Gomer var Askenas og Rifat og Togarma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Og sønerne hans Javan var Elisa og Tarsis, og Kittim og Dodanim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Frå deim hev folki på heidninge-øyarne greina seg ut i landi sine, kvart med sitt tungemål, etter sine ætter, i sine rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Og sønerne hans Kham var Kusj og Misrajim og Put og Kana’an.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Og sønerne hans Kusj var Seba og Havila og Sabta og Raema og Sabteka, og sønerne hans Raema var Sjeba og Dedan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Og Kusj hadde endå ein son, som heitte Nimrod. Han var den fyrste som fekk stort velde på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Han var ein gjæv veidemann i Herrens augo. Difor vert det sagt: «Ein gjæv veidemann i Herrens augo, som Nimrod.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Fyrst rådde han yver Babel og Erek og Akkad og Kalne i Sinearlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Frå det landet for han til Assur, og bygde Nineve og Rehobot-Ir og Kalah');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'og Resen millom Nineve og Kalah; dette er Storstaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Og Misrajim vart far til ludarane og anamarane og lehabarane og naftuharane');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'og patrusarane og kasluharane, dei som filistarane hev kome frå, og kaftorarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Og Kana’an vart far til Sidon - det var den fyrste sonen hans - og til Het');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'og til jebusitarne og amoritarne og girgasitarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'og hevitarne og arkitarne og sinitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'og arvaditarne og semaritarne og hamatitarne. Sidan breidde kananitarfolki seg vidare ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Og landskilet åt kananitarne gjekk frå Sidon til Gaza, når du tek leidi burtimot Gerar, og til Lesa, når du tek leidi burtimot Sodoma og Gomorra og Adma og Sebojim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Dette er Khams-sønerne, med sine ætter og tungemål, i sine land og rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Og Sem, eldste bror hans Jafet, han fekk og born; han er det som alle Ebers-sønerne er ætta frå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Og sønerne hans Sem var Elam og Assur og Arpaksad og Lud og Aram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Og sønerne hans Aram var Us og Hul og Geter og Mas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Og Arpaksad fekk sonen Salah, og Salah fekk sonen Eber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Og Eber fekk tvo søner. Den eine heitte Peleg; for i hans dagar vart jordi utbytt millom folki. Og bror hans heitte Joktan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Og Joktan vart far til Almodad og Salef og Hasarmavet og Jarah');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'og Hadoram og Uzal og Dikla');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'og Obal og Abimael og Sjeba');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'og Ofir og Havila og Jobab; alle desse var sønerne hans Joktan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Og dei budde i Austfjellet, frå Mesa og burtimot Sefar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dette er sønerne hans Sem, med sine ætter og tungemål, i sine land og med sine rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Dette var dei folki som hev kome frå sønerne hans Noah, etter sine ættgreiner, i sine rike. Og frå deim hev alle folkeslag greina seg ut yver jordi etter storflodi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Og heile verdi hadde eitt tungemål og same ordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Og det bar so til, då dei for austigjenom, at dei fann ei slette i Sinearlandet, og der slo dei seg ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Og dei sagde seg imillom: «Kom, lat oss gjera tigl og brenna det vel!» Og so bruka dei tiglet til murstein, og i staden for kalk bruka dei jordbik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'So sagde dei: «Kom, lat oss byggja oss ein by, med eit tårn som når upp i himmelen, og gjera oss namngjetne, so me ikkje vert spreidde utyver all jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Då steig Herren ned og vilde sjå byen og tårnet som manneborni bygde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Og Herren sagde: «Sjå dei er eitt folk, og alle hev dei eit tungemål, og dette er det fyrste dei tek seg fyre! No vert ikkje noko umogelegt for deim, kva dei so finn på å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Lat oss då stiga ned der og vildra målet deira, so den eine ikkje skynar kva den andre segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'So spreidde Herren deim derifrå ut yver heile jordi, og dei heldt upp å byggja på byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Difor kallar dei den byen Babel; for der vildra Herren målet for heile verdi, og derifrå spreidde Herren deim ut yver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dette er soga um Sems-ætti: Då Sem var hundrad år gamall, fekk han sonen Arpaksad, tvo år etter storflodi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Og etter han hadde fenge Arpaksad, livde han endå i fem hundrad år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Då Arpaksad var fem og tretti år gamall, fekk han sonen Salah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Og etter han hadde fenge Salah, livde han endå fire hundrad og tri år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Då Salah var tretti år gamall, fekk han sonen Eber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Og etter han hadde fenge Eber, livde han endå fire hundrad og tri år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Då Eber var fire og tretti år gamall, fekk han sonen Peleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Og etter han hadde fenge Peleg, livde han endå fire hundrad og tretti år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Då Peleg var tretti år gamall, fekk han sonen Re’u.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Og etter han hadde fenge Re’u, livde han endå tvo hundrad og ni år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Då Re’u var tvo og tretti år gamall, fekk han sonen Serug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Og etter han hadde fenge Serug, livde han endå tvo hundrad og sju år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Då Serug var tretti år gamall, fekk han sonen Nahor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Og etter han hadde fenge Nahor, livde han endå tvo hundrad år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Då Nahor var ni og tjuge år gamall, fekk han sonen Tarah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Og etter han hadde fenge Tarah, livde han endå hundrad og nittan år, og fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Då Tarah hadde fyllt sytti år, fekk han sønerne Abram og Nahor og Haran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Dette er soga um Tarah og ætti hans: Tarah fekk sønerne Abram og Nahor og Haran. Og Haran fekk sonen Lot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Og Haran døydde for augo åt Tarah, far sin, i fødesheimen sin, i Ur i Kaldæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Og Abram og Nahor tok seg konor. Kona hans Abram heitte Saraj, og kona hans Nahor heitte Milka, og var dotter åt Haran, far åt Milka og Jiska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Men Saraj var barnlaus; ho hadde aldri ått barn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Og Tarah tok med seg Abram, son sin, og Lot Haransson, soneson sin, og Saraj, sonekona si, kona hans Abram, og dei tok ut saman frå Ur i Kaldæa, og vilde fara til Kana’ans-land. Og dei kom til Kharan, og vart buande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Og dagarne hans Tarah vart tvo hundrad og fem år. So døydde Tarah i Kharan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Då sagde Herren til Abram: «Far no du ut or landet ditt, burt ifrå folket og farshuset ditt, og til det landet som eg vil syna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Og eg vil gjera deg til eit stort folk, og velsigna deg, og gjera namnet ditt stort. Du skal verta ei velsigning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Og eg vil velsigna deim som velsignar deg, og den som bannar deg, vil eg forbanna; og i deg skal alle folk på jordi velsignast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'So tok Abram ut, som Herren hadde sagt honom fyre, og Lot var med honom. Og Abram var fem og sytti år gamall, då han flutte frå Kharan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Og Abram tok med seg Saraj, kona si, og Lot, brorson sin, og alt godset dei hadde vunne, og det folket dei hadde fenge i Kharan, og dei tok ut og vilde fara til Kana’ans-land, og dei kom til Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Og Abram for framigjenom landet, alt til Sikemsbygdi, til Spåmannseiki. Og kananitarne budde då der i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Då synte Herren seg for Abram og sagde: «Dette landet vil eg gjeva ætti di!» Og Abram bygde der eit altar for Herren, som hadde synt seg for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Derifrå flutte han til fjelli austanfor Betel, og sette upp tjeldbudi si so han hadde Betel i vest og Aj i aust. Og der bygde han Herren eit altar, og kalla på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Sidan muna Abram seg etter kvart framigjenom til sudlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'So vart det uår i landet. Då for Abram ned til Egyptarland, og vilde halda til der; for naudi var stor i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Då det leid so langt at dei mest var komne til Egyptarland, sagde han til Saraj, kona si: «Høyr no her du! Eg veit at du er ei fager kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Og det kjem til å ganga so, at når egyptarane fær sjå deg, so segjer dei: «Dette er kona hans,» og so slær dei meg i hel, men deg let dei liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Kjære deg, seg du er syster mi, so det kann ganga meg vel for di skuld, og eg ikkje skal missa livet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Då so Abram kom fram til Egyptarland, såg egyptarane kona, og tykte ho var ovfager.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Og hovdingarne åt Farao såg henne, og rosa henne for Farao. So vart kona henta til huset åt Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Og Abram gjorde han vel imot for hennar skuld, og han fekk både sauer og naut og asen og drengjer og gjentor og asenfyljor og kamelar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Men Herren søkte Farao og huset hans med svære plågor for Saraj skuld, kona hans Abram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Og Farao kalla Abram til seg og sagde: «Kva er det du hev gjort imot meg! Kvi let du meg ikkje vita at ho var kona di?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Kvi sagde du at ho var syster di, so eg tok henne og vilde havt henne til kona? Sjå der hev du kona di! Tak henne og far din veg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Og Farao sette nokre menner til å fylgja honom ut or landet med kona hans og alt det han åtte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'So for Abram frå Egyptarland upp til Sudlandet med kona si og alt det han åtte, og Lot var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Og Abram var ovleg rik, både på bufe og på sylv og på gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Sidan for han frå Sudlandet, dagsleid etter dagsleid, til dess han kom til Betel, til den staden som han fyrr hadde havt tjeldbudi si, millom Betel og Aj,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'der det altaret stod som han hadde bygt fyrste gongen han var der. Og der kalla Abram på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Men Lot, som fylgdest med Abram, hadde og sauer og naut og tjeldbuder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Og landet kunde ikkje føda deim, når dei budde i hop; dei hadde so mykje fe at dei kunde ikkje bu saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'So vart det trætta millom deim som gjætte for Abram og deim som gjætte for Lot. Og kananitarne og perizitarne budde då der i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Då sagde Abram med Lot: «Kjære deg, lat det ikkje vera trætta millom meg og deg, og millom mine hyrdingar og dine. Me er då brør!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Hev du ikkje heile landet fyre deg? Skil då heller lag med meg! Tek du til vinstre, so skal eg taka til høgre, og tek du til høgre, so skal eg taka til vinstre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Då skoda Lot ikring seg, og såg at heile Jordan-kverven, alt burtåt Soar, var rik på vatn yver alt, som Herrens hage, som Egyptarlandet - fyrr Herren lagde Sodoma og Gomorra i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Og Lot valde seg ut heile Jordan-kverven. So tok Lot austigjenom, og dei skildest frå einannan:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram vart buande i Kana’ans-land, og Lot budde i byarne i Jordan-kverven, og lægra alt burtåt Sodoma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Men mennerne i Sodoma var vonde, og synda groveleg mot Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Og Herren sagde til Abram, etter Lot hadde skilt lag med honom: «Lat upp augo dine og sjå ikring deg frå den staden du stend, nordetter og sudetter og austetter og vestetter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'For alt det landet du ser, vil eg gjeva deg og di ætt til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Og eg vil lata ætti di verta som dusti på jordi: kann nokon telja dusti på jordi, so kann dei og telja di ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Upp, og far landet igjenom, so langt og so breidt som det er! For deg vil eg gjeva det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'So flutte Abram tjeldbuderne, og kom til eikelunden åt Mamre i Hebron. Der vart han buande, og bygde Herren eit altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'I den tidi då Amrafel var konge i Sinear, og Arjok konge i Ellasar, og Kedorlaomer konge i Elam, og Tideal konge yver heidningarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'då hende det at det vart ufred millom dei kongarne og Bera, kongen i Sodoma, og Birsa, kongen i Gomorra, og Sineab, kongen i Adma, og Semeber, kongen i Sebojim, og kongen i Bela, som no heiter Soar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Alle desse slo seg i hop og lagde vegen til Siddimdalen, der som Saltsjøen er no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Tolv år hadde dei tent Kedorlaomer, men det trettande året fall dei frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Og det fjortande året kom Kedorlaomer og dei kongarne som var med honom, og slo under seg refa’itarne i Asterot-Karnajim og zuzitarne i Ham og emitarne på Kirjatajimsletta');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'og horitarne på fjelli deira, Se’irfjelli, alt til Paranlunden, som er utmed øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'So snudde dei um, og kom til Domskjelda, der som Kades ligg, og lagde under seg alt Amalekitarlandet og amoritarne med, dei som budde i Haseson-Tamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Og kongen i Sodoma og kongen i Gomorra og kongen i Adma og kongen i Sebojim og kongen i Bela, som no heiter Soar, dei tok ut, og fylkte heren sin imot deim i Siddimdalen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'mot Kedorlaomer, kongen i Elam, og Tideal, kongen yver heidningarne, og Amrafel, kongen i Sinear, og Arjok, kongen i Ellasar, fire kongar mot fem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Men i Siddimdalen var det fullt av jordbikgrover. Og kongarne i Sodoma og Gomorra laut røma, og då stupte dei ned i groverne; og dei som att var, rømde til fjells.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Og hine tok alt godset i Sodoma og Gomorra og all maten deira, og drog burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Og dei tok Lot, brorson hans Abram, og godset hans og drog av med; for han budde i Sodoma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Men ein av deim som hadde kome seg undan, bar bod um alt dette til Abram, hebræaren, som budde i eikelunden åt Mamre, amoriten. Og Mamre, han var bror åt Eskol og Aner, og dei var alle i samlag med Abram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Då no Abram høyrde at brorson hans var fanga, tok han ut med alle sine fullrøynde sveinar, som var fødde og fostra i huset hans, tri hundrad og attan i talet, og sette etter deim alt til Dan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Der bytte han sund flokken sin, og tok på deim um natti med sveinarne sine, og han vann yver deim, og elte deim radt til Hoba, som ligg nordanfor Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'So tok han att alt godset, og Lot, brorson sin, og hans gods tok han og att, og kvendi og hitt folket med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Då han so var på heimvegen og hadde vunne yver Kedorlaomer og dei kongarne som var med honom, kom kongen i Sodoma imot honom til Flatedal, der som no heiter Kongsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Og Melkisedek, kongen i Salem, kom ut med brød og vin. Han var prest åt Gud den Høgste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Og han velsigna honom og sagde: «Gud den Høgste, han som eiger Jord og himmel, signe Abram!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Gud den Høgste vere lova! I di hand gav han din fiend.» Og Abram gav honom tiend av alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Og kongen i Sodoma sagde med Abram: «Gjev meg folket, og tak du godset!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Då sagde Abram med kongen i Sodoma: «Eg retter upp handi til Herren, Gud den Høgste, han som eig himmel og jord:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Ikkje so mykje som ein tråd eller ei skoreim tek eg imot av det som ditt er. Du skal ikkje hava det å segja: «Eg gjorde Abram rik.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Eg vil ingen ting hava, anna enn den maten som sveinarne hev ete, og den luten som fell på dei mennerne som var med meg, Aner og Eskol og Mamre; lat deim få sin lut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Ei tid etter dette hadde hendt, kom Herrens ord til Abram i eit syn, og det lydde so: «Ver ikkje ottefull, Abram! Eg skal vera din skjold! Løni di skal vera ovleg stor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Då sagde Abram: «Herre, min Gud, kva vil du gjeva meg? Barnlaus fer eg min veg, og den som vert eigande huset mitt, er Elieser frå Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Sjå, meg hev du ikkje gjeve noko barn,» sagde Abram, «og rådsdrengen min kjem til å erva meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Men sjå: då kom Herrens ord til honom, og det lydde so: «Nei, han skal ikkje erva deg, men ein som er komen av ditt eige blod, skal erva deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Og han leidde honom utanfor, og sagde: «Kjære deg, sjå upp til himmelen og tel stjernorne, um du er god til. So tallaus,» sagde han til honom, «skal ætti di verta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Og Abram trudde Herren, og det rekna han honom til rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Og han sagde til honom: «Eg er Herren, som leidde deg ut frå Ur i Kaldæa, og eg vil gjeva deg dette landet til eiga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Og Abram sagde: «Herre, min Gud, kva vissa skal eg hava på det, at eg skal få det til eiga?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Då sagde Herren til honom: «Henta meg ei triæringskviga og ei triæringsgeit og ein triæringsver og ei turtelduva og ein duveunge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'So henta Abram alt dette åt honom, og skar dyri midt i tvo, og lagde den eine luten av kvart dyr beint imot den andre. Men fuglarne skar han ikkje sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Og ræfuglar kom dalande ned på kjøtet, men Abram jaga deim burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Då det so leid til at soli vilde glada, kom det ein tung svevn på Abram, og gruv, stort myrker, kom yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Og han sagde til Abram: «Det skal du vita, at ætti di skal halda til i eit land som ikkje er deira, og dei skal tena folket der og tola mykje vondt av deim i fire hundrad år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Men det folket som dei lyt tena, vil eg og døma, og sidan skal dei draga ut med mykje gods.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Og du skal fara i fred til federne dine; du skal ganga i gravi i høg alder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Og i den fjorde mannsalderen skal dei koma hit att; for endå vantar det noko på syndeskuldi åt amoritarne, fyrr målet er fullt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'No var soli gladd, og det var stumende myrkt. Då fekk han sjå ein rjukande omn og ein eldsloge, som for fram millom kjøtstykki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Den dagen gjorde Herren ei pakt med Abram og sagde: «Di ætt gjev eg dette landet, frå Egyptarlands-elvi alt til den store elvi, til Fratelvi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'landet åt kenitarne og kenizitarne og kadmonitarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'og hetitarne og perizitarne og refa’itarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'og amoritarne og kananitarne og girgasitarne og jebusitarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Saraj, kona hans Abram, fekk ikkje born. Men ho hadde ei terna som var frå Egyptarland og heitte Hagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Og Saraj sagde med Abram: «Du ser, Herren hev meinka meg born. Kjære deg, gakk inn til terna mi! Kann henda ho fær ein son åt meg.» Og Abram lydde rådi hennar Saraj.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'So tok Saraj, kona hans Abram, og let Abram, mannen sin, få Hagar frå Egyptarland, som var terna hennar, til kona. Då var det ti år sidan Abram hadde slege seg ned i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Og han gjekk inn til Hagar, og ho vart med barn. Men då ho såg at ho var med barn, vanvyrde ho matmor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Då sagde Saraj med Abram: «Du skal svara for den urett eg lid. Eg bad deg sjølv taka terna mi i fang, men no ho ser at ho er med barn, vanvyrder ho meg. Herren skal døma millom meg og deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Då sagde Abram med Saraj: «Terna di råder du sjølv yver. Gjer med henne som du synest!» Sidan var Saraj hard med henne, og ho rømde sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Men Herrens engel fann henne innmed ei vatskjelda i øydemarki, den kjelda som er frammed vegen til Sur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Og han sagde: «Du Hagar, terna hennar Saraj, kvar kjem du frå, og kvar etlar du deg?» Og ho sagde: «Eg laut røma frå Saraj, matmor mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Då sagde Herrens engel til henne: «Gakk heim att til matmor di, og bøyg deg under handi hennar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Og Herrens engel sagde til henne: «Eg vil gjeva deg ei ætt som er endelaus: reint uteljande skal ho vera!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Og Herrens engel sagde til henne: «Sjå, du er med barn, og du skal eiga ein son. Honom skal du kalla Ismael, av di Herren høyrde deg i naudi di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Det vert eit villasen til kar. Hans hand skal vera lyft mot alle, og alle hender mot honom. Og midt for augo på alle brørne sine skal han slå seg ned.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Og ho nemnde Herren, som hadde tala med henne, og sagde: «Du er Gud, den som ser alt!» Og ho sagde: «Kann det vera råd at eg her hev set skimten av den som all tid ser meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Difor kallar dei den kjelda «Kjelda åt den som liver, og ser meg»; ho er millom Kades og Bered.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Og Hagar fekk ein son, og Abram kalla son sin, som Hagar hadde fenge, Ismael.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram var seks og åtteti år gamall, då han fekk Ismael med Hagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Då Abram var ni og nitti år gamall, synte Herren seg for honom, og sagde til honom: «Eg er Gud den Allvelduge. Far du fram for mi åsyn, og haldt deg ulastande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'so eg kann fremja mi pakt med deg og auka ætti di endelaust.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Då kasta Abram seg å gruve, og Gud tala med honom, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '«Sjå, eg er i pakt med deg, og du skal verta far åt ein fjølde med tjoder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Dei skal ikkje lenger kalla deg Abram, men du skal heita Abraham: til far åt ei mengd med folkeslag vil eg gjera deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Og eg vil lata deg veksa og aukast, so du vert til mange tjoder, kongar skal ættast frå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Og eg vil stadfesta mi pakt med deg og med ætti di etter deg, frå alder til alder, ei æveleg pakt, og vera din Gud og Gud åt ætti di etter deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Og eg vil gjeva deg og ætti di etter deg det landet som du held til i, heile Kana’ans-landet, til eiga i all æva, og eg vil vera deira Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Og Gud sagde til Abraham: «Og du skal halda pakti mi, både du og ætti di etter deg, frå alder til alder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Dette er pakti, som de skal halda, millom meg og dykk og ætti di etter deg: Alt karfolk hjå dykk skal umskjerast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'De skal skjera av holdet på huva dykkar: det skal vera merket på pakti millom meg og dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Kvart sveinbarn hjå dykk skal umskjerast, fyrst det er åtte dagar gamall, alder etter alder, både dei som er fødde i huset, og dei som er kjøpte for pengar: alle dei som er frå framande land, og ikkje er av di ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Umskjerast skal både dei som er fødde i huset ditt, og dei som er kjøpte for pengarne dine! So skal pakti mi te seg på holdet dykkar, ei æveleg pakt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Men den som ikkje er umskoren, den som huveholdet ikkje er avskore på, den mannen skal verta utrudd or folket sitt; han hev brote mi pakt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Og Gud sagde til Abraham: «Saraj, kona di, skal du ikkje lenger kalla Saraj: Sara skal ho heita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Og eg vil velsigna henne og gjeva deg ein son med henne og; velsigna vil eg henne, og ho skal verta til mange tjoder; kongar yver store rike skal ættast frå henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Då kasta Abraham seg å gruve, og log. Og han sagde med seg sjølv: «Kann ein mann som er hundrad år gamall, få barn? Og Sara, som er nitti år, kann ho verta mor?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Og Abraham sagde til Gud: «Gjev Ismael måtte få liva og tekkjast deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Då sagde Gud: «Som eg hev sagt: Sara, kona di, skal eiga ein son, og du skal kalla honom Isak, og eg vil stadfesta pakti mi med honom, ei æveleg pakt, med hans ætt etter honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Og um Ismael, so hev eg og høyrt bøni di: Sjå, eg vil velsigna honom og lata honom veksa og aukast alt meir og meir. Tolv hovdingar skal han verta far til, og eg vil gjera honom til eit stort folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Men pakti mi vil eg stadfesta med Isak, som Sara skal eiga eit anna år dette bil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'So sagde han ikkje meir til honom då. Og Gud for upp att frå Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Og same dagen tok Abraham son sin, Ismael, og alle som var fødde i huset hans, og alle som var kjøpte for pengarne hans, alt karfolket i huset hans Abraham, og skar av holdet på huva deira, som Gud hadde sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham var ni og nitti år gamall, då huveholdet vart avskore på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Og Ismael, son hans, var trettan år gamall, då huveholdet vart avskore på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Denne same dagen vart dei umskorne, både Abraham og Ismael, son hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Og alle karar i huset hans, både dei som var fødde i huset, og dei framande, som var kjøpte for pengar, dei vart umskorne med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Sidan synte Herren seg for honom i Mamrelunden, medan han sat i døri til tjeldbudi si, midt på heitaste dagen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Som han såg upp og skoda utyver, fekk han sjå tri menner som stod framfyre honom. Med same han vart var deim, sprang han imot deim frå buddøri, og bøygde seg nedåt jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'og sagde: «Herre, hev du noko godvilje for meg, so gjer vel og sjå innum åt tenaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Lat oss få henta noko vatn, so de kann två føterne og kvila dykk her under treet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'So skal eg finna ein bite mat, som de kann styrkja dykk med, fyrr de fer lenger, sidan det høver seg so at de legg vegen um tenaren dykkar.» Og dei sagde: «Ja, gjer som du segjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Då skunda Abraham seg inn i budi til Sara og sagde: «Nøyt deg og tak tri settung fint mjøl, og knoda det, og baka kakor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Og burt til buskapen sprang han, og tok ut ein uksekalv som var fin og god; den let han drengen få, og han nøytte seg og laga honom til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'So tok han rjome og mjølk og kalven som drengen hadde laga til, og sette det fram åt deim, og sjølv stod han hjå deim under treet, medan dei åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Då sagde dei til honom: «Kvar er Sara, kona di?» «Sjå der inni tjeldbudi er ho,» sagde Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Då sagde han: «Når det lid ut i årsmotet, kjem eg hit til deg att, og då hev Sara, kona di, fenge ein son.» Og Sara høyrde det i buddøri; for den var attanfor honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Men Abraham og Sara var gamle og ut i åri komne; Sara hadde det ikkje lenger so som kvendi plar hava det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Difor log Sara med seg sjølv, og tenkte: «Skulde eg få hug, endå so gamall og skrukkut som eg er? Og mannen min er og til års!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Då sagde Herren til Abraham: «Kvi log Sara og tenkte: «Kann dette vera sant, at eg skal eiga barn, eg som er so gamall?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Er det noko som er umogelegt for Herren? Til års dette bil kjem eg hit til deg att, og då hev Sara ein son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Men Sara neitta og sagde: «Eg log ikkje.» For ho var rædd. Då sagde han: «Jau, du log.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'So gjorde mennerne seg ferdige og gjekk, og dei tok leidi burtimot Sodoma; og Abraham gjekk med deim; han vilde fylgja deim på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Då sagde Herren: «Kvi skulde eg dylja for Abraham det som eg tenkjer å gjera,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham som skal verta far til eit stort og sterkt folk? Alle folkeslag på jordi skal velsignast i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'For eg kjenner honom for den mann, at han vil segja til borni sine og til huset sitt etter seg, at dei skal halda seg etter Herrens veg og gjera rett og skil, so Herren kann lata det ganga fram som han hev lova Abraham.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Og Herren sagde: «Klageropet yver Sodoma og Gomorra det er øgjelegt, og synderne deira dei er ovleg svære.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'No vil eg ned og sjå um dei hev fare so ille åt som det lydest av det ropet som hev stige upp til meg; og hev dei ikkje det, so fær eg vita det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'So snudde mennerne seg og gjekk, og dei tok vegen til Sodoma. Men Abraham stod endå framfor Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Og Abraham gjekk innåt og sagde: «Vil du då riva burt dei rettvise saman med dei gudlause?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Um det no var femti rettvise menner i byen? Vil du då riva deim burt, og ikkje spara byen for deira skuld?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Det er ikkje di vis å fara so åt, drepa den som rettvis er, saman med den som er gudlause, so det gjeng dei rettvise like eins som dei gudlause. So er ikkje di vis! Den som byter rett all jordi yver, skulde ikkje han gjera rett!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Då sagde Herren: «Finn eg i Sodoma by femti rettvise menner, so skal eg spara heile byen for deira skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Og Abraham tok til ords att og sagde: «Sjå, eg hev våga meg til å tala til Herren min, endå eg er mold og oska!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Um det no skulde vanta fem på dei femti rettvise mennerne? Vil du då leggja heile byen i øyde for desse fem skuld?» og han svara: «Finn eg fem og fyrti, so skal eg ikkje øydeleggja honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Og Abraham heldt på og tala til honom, og sagde: «Um det no finst fyrti -?» og han svara: «Eg skal ikkje gjera det, for dei fyrti skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Då sagde Abraham: «Herren må ikkje verta vreid, um eg talar! Um det no finst tretti -?» Og han svara: «Eg skal ikkje gjera det, so sant eg finn tretti.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Då sagde Abraham: «Sjå, eg hev våga meg til å tala til Herren min! Um det finst no tjuge -?» Og han svara: «Eg skal ikkje øydeleggja byen, for dei tjuge skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Då sagde Abraham: «Herren må ikkje verta vreid, um eg talar berre denne eine gongen til! Um det finst no ti -?» Og han svara: «Eg skal ikkje øydeleggja honom, for dei ti skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'So gjekk Herren burt, då han hadde tala til endes med Abraham. Og Abraham gjekk heim att til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Og dei tvo englarne kom til Sodoma um kvelden, medan Lot sat i byporten. Då Lot fekk sjå deim, reiste han seg og gjekk imot deim, og bøygde seg nedåt jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'og sagde: «Gode herrar, gjer so vel og ver med tenaren dykkar heim, og gjev dykk til hjå meg i natt, og två føterne dykkar. So kann de vera tidleg uppe i morgon og taka på vegen att.» Og dei sagde: «Nei, me vil vera ute på torget i natt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Men han nøydde deim so lenge til dei fylgde honom heim, og var med honom inn. Og han gjorde eit gjestebod åt deim, og baka søtebrød, og so åt dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Dei hadde endå ikkje lagt seg, so kom byfolket, mennerne i Sodoma, både unge og gamle, heile lyden, frå alle kantar, og slo ring um huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Og dei ropa til Lot og sagde med honom: «Kvar er dei mennerne som kom heim til deg i kveld? Lat deim koma ut til oss, so me kann få vår vilje med deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Då gjekk Lot ut i døri til deim, og let hurdi att etter seg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'og sagde: «Kjære brør, gjer då ikkje slik ei ugjerning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Sjå, eg hev tvo døtter, som ingen kar hev vore nær. Lat meg senda deim ut til dykk, so kann de gjera med deim som de synest. Men desse mennerne her, deim må de ikkje gjera noko, etter di dei hev kome inn under skuggen av taket mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Men dei sagde: «Or vegen med deg! Her kjem denne framandkaren og fær bu her,» sagde dei, «og so gjev han seg til å døma jamt og samt! No skal me fara verre med deg enn med deim!» Og dei gjekk hardt inn på mannen, på Lot, og styrmde innåt og vilde brjota sund hurdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Då rette mennerne ut handi, og tok Lot inn i huset til seg, og stengde att hurdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Og dei vildra syni på dei kararne som var utfyre husdøri, både små og store, so dei fann ikkje døri, kor mykje dei stræva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Og mennerne sagde med Lot: «Hev du elles nokon her som er skyld deg? nokon måg? Både søner og døtter og alt ditt folk her i byen lyt du få med deg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'For no skal me leggja denne byen i øyde, av di eit øgjelegt klagerop yver deim hev nått upp til Herren, og Herren hev sendt oss på den måten at me skal øydeleggja byen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Då gjekk Lot ut og tala til mågarne sine, deim som skulde hava døtterne hans, og sagde: «Upp, og kom dykk burt frå denne staden! For no vil Herren øydeleggja byen.» Men mågarne hans tenkte at han berre vilde narra deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Det fyrste det tok til å dagast, skunda englarne på Lot og sagde: «Upp! Tak kona di og dei tvo døtterne dine som er her, so du ikkje skal missa livet for alt det vonde skuld som er gjort her i byen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Men han tøvra. Då greip mennerne honom i handi, både honom og kona og døtterne hans, av di Herren vilde spara honom, og dei leidde honom ut, og slepte honom ikkje, fyrr dei var utanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Då dei no var utum byen komne, sagde han: «Vil du berga livet, so røm! Sjå deg ikkje attende, og stana ikkje i heile kverven! Røm upp på fjellet! elles ryk du med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Då sagde Lot til deim: «Å nei, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Sjå, tenaren din hev funne nåde hjå deg, og stor er den miskunn du hev gjort meg, med di du hev berga livet mitt. Men upp på fjellet kann eg ikkje nå. Ulukka kunde koma yver meg, so eg laut døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Sjå, denne byen der er snar å røma til, og han er so liten! Er han ikkje liten? Kjære væne, lat meg få berga meg dit, so eg vert verande i live!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Då sagde han til honom: «Ja, eg vil gjera deg til viljes i dette og, og ikkje søkkja ned den byen du talar um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Skunda deg og røm dit, for eg kann ingen ting gjera, fyrr du er komen der.» Difor kallar dei den byen Soar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Soli hadde runne på fjell, då Lot kom til Soar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Då let Herren det regna svåvel og eld, frå Herren, frå himmelen, nedyver Sodoma og Gomorra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'og søkkte i kav båe dei byarne og heile kverven, med alle som i byarne budde, og alt som på vollarne voks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Og kona hans Lot såg attum seg. Då vart ho til ein saltstein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Um morgonen tidleg gjekk Abraham til den staden han var, då han stod framfor Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'og han skoda utyver Sodoma og Gomorra og utyver alt landet i kverven, og då såg han - såg røyken valt upp av jordi, som røyken av ein masomn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'So gjekk det til, at då Gud øydelagde byarne på Jordan-kverven, då kom Gud i hug Abraham, og leidde Lot midt utor øydeleggjingi, den gongen han søkkte ned dei byarne som Lot hadde butt i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Og Lot for frå Soar upp i fjellet, og gav seg til der, og båe døtterne hans med honom; for han torde ikkje bu i Soar. Og han budde i ein heller, både han og døtterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Då sagde den eldste dotteri til den yngste: «Far vår er gamall, og det finst ikkje menner i landet, so dei kunde ganga til oss, som visi er i all verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Kom, lat oss gjeva far vår vin å drikka og leggja oss hjå honom, so me held uppe ætti åt far vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'So skjenkte dei far sin vin same kvelden, og den eldste gjekk inn og lagde seg hjå far sin. Og han hådde ikkje då ho lagde seg, og heller ikkje då ho reis upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Og dagen etter sagde den eldste dotteri med den yngste: «Høyr her! I natt låg eg med far min. Lat oss gjeva honom vin å drikka i kveld og, og gakk du inn og legg deg hjå honom, so held me uppe ætti åt far vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'So skjenkte dei far sin vin den kvelden og. Og den yngste kom og lagde seg hjå honom. Og han hådde ikkje at ho lagde seg, og heller ikkje at ho reis upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Og båe døtterne hans Lot vart umhender med far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Og den eldste fekk ein son, og kalla honom Moab. Frå honom er Moab-folket ætta, alt til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Og den yngste fekk og ein son, og kalla honom Ben-Ammi. Frå honom er Ammons-sønerne ætta, alt til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'So flutte Abraham derifrå til Sudlandet og sette seg ned millom Kades og Sur, og sidan heldt han til i Gerar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Og Abraham sagde um Sara, kona si: «Ho er syster mi.» Og Abimelek, kongen i Gerar, sende folk ut, og tok Sara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Då kom Gud um natti til Abimelek i draume, og sagde til honom: «No lyt du døy, for di du hev teke denne kvinna; for ho er ei gift kona.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Men Abimelek hadde ikkje vore nær henne. Og han sagde: «Herre, vil du då drepa rettvise folk og?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Sagde han ikkje sjølv med meg: «Ho er syster mi»? Og ho, ho sagde og: «Han er bror min.» Med skuldlaust hjarta og reine hender gjorde eg dette.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Då sagde Gud til honom i draume: «Ja, eg veit at du gjorde det med skuldlaust hjarta, og det var eg sjølv som heldt deg ifrå å synda mot meg, med di eg ikkje let deg få røra henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Lat no du mannen få att kona si; for han er ein gudsmann - so bed han for deg, og då fær du liva. Men gjev du henne ikkje ifrå deg, so må du vita at du skal døy, både du og alle dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Um morgonen tidleg reis Abimelek upp og kalla kring seg alle mennerne sine og sagde alt dette med deim, og kararne vart ovleg rædde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Og Abimelek kalla til seg Abraham, og sagde med honom: «Kvi gjorde du dette mot oss? Kva vondt hadde eg gjort deg, sidan du vilde leggja so stor ei synd på meg og riket mitt? Du hev fare åt imot meg som ingen skulde fara åt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Kva meinte du med det at du gjorde dette?» sagde Abimelek med Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Då sagde Abraham: «Eg tenkte det: «Dei hev visst ingen age for Gud i dette landet; dei kjem til å drepa meg for kona skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Og so er ho og i røyndi syster mi, dotter åt far min, men ikkje dotter åt mor mi. Og ho vart kona mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Og då Gud let meg fara frå heimen min ut i vide verdi, då sagde eg med henne: «Dette lyt du gjera for mi skuld: kvar me kjem helst, so seg um meg: «Han er bror min.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'So tok Abimelek både sauer og naut og drengjer og gjentor og gav Abraham, og let honom få att Sara, kona si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Og Abimelek sagde: «Sjå, her hev du landet mitt fyre deg; bu der du helst vil!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Og med Sara sagde han: «Sjå, her gjev eg bror din tusund sylvdalar. Det skal vera ei ærebot for deg hjå alle som er med deg, so kvar og ein kann sjå du er saklaus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'So bad Abraham til Gud for deim, og Gud lækte Abimelek og kona hans og ternorne hans, so dei fekk born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'For Herren hadde heiltupp stengt kvart morsliv i huset åt Abimelek for Sara skuld, kona hans Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Og Herren såg til Sara, som han hadde sagt, og Herren gjorde for Sara det som han hadde lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Og Sara vart med barn, og fekk ein son med Abraham på hans gamle dagar, den tid som Gud hadde nemnt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Og Abraham kalla son sin, den som Sara hadde fenge, Isak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Og Abraham umskar Isak, son sin, då han var åtte dagar gamall, som Gud hadde sagt honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham var hundrad år gamall, då Isak, son hans, kom til verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Og Sara sagde: «Gud hev laga det, so eg lyt læ; og alle som høyrer det, kjem til å læ åt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Kven skulde vel tenkt seg og sagt det med Abraham, at Sara skulde leggja eit barn til brjostet?» sagde ho, «og no på hans gamle dagar hev eg fenge ein son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Og sveinen voks upp, og ho vande honom av, og Abraham gjorde eit stort gjestebod den dagen Isak vart avvand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Og Sara såg at son åt Hagar frå Egyptarland, han som ho hadde fenge med Abraham, ståka og log.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Då sagde ho med Abraham: «Du skal jaga den terna der og son hennar! For ikkje skal son åt denne terna erva i hop med min son, med Isak.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dei ordi gjorde Abraham hjarteleg ilt for sonen skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Men Gud sagde til Abraham: «Du skal ikkje hava hugilt for sveinen skuld eller terna skuld! Lyd du Sara i alt ho segjer til deg. For etter Isak skal ætti di heita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Og sonen åt terna vil eg og gjera til eit heilt folk, etter di han er ditt barn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Morgonen etter reis Abraham tidleg upp, og tok fram brød og ei hit med vatn; det gav han Hagar, og lagde det på herdarne hennar; og han let henne få sveinen, og bad henne fara. So gjekk ho sin veg, og vingla umkring i Be’erseba-heidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Og vatnet traut i hiti. Då lagde ho sveinen ned under ein runne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'og sjølv gjekk ho eit stykke burt, som eit bogeskot på lag, og sette seg der. «Eg vil ikkje sjå på at sveinen døyr,» tenkte ho; difor sette ho seg eit stykke ifrå, og ho brast i og gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Men Gud høyrde sveinen øya seg, og Guds engel ropa frå himmelen til Hagar og sagde til henne: «Kva vantar deg, Hagar? Du tarv ikkje ottast! For Gud høyrde sveinen øya seg der han er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Reis deg, lyft sveinen upp, og haldt honom fast i handi; eg vil gjera honom til eit stort folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Og Gud opna augo hennar, so ho såg ein brunn; so gjekk ho dit, og fyllte hiti med vatn, og gav sveinen drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Og Gud var med sveinen, og han voks upp, og budde i øydemarki, og då han tok til å mannast, vart han bogeskyttar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Han slo seg ned i Paranheidi, og mor hans fann ei kona åt honom frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'I same tidi hende det at Abimelek og Pikol, som var hovding yver heren hans, kom og sagde med Abraham: «Gud er med deg i alt det du gjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'So sver meg no her ved Gud, at du ikkje vil fara med svik mot meg eller mot borni og barneborni mine: liksom eg hev gjort vel imot deg, so skal du gjera vel imot meg og mot det landet du hev fenge tilhald i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Og Abraham sagde: «Ja, det skal eg sverja på!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Og Abraham kjærde seg for Abimelek yver den brunnen som drengjerne hans Abimelek hadde rana til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Då sagde Abimelek: «Eg veit ikkje kven som hev gjort dette. Ikkje hev du sagt meg det, og ikkje hev eg høyrt det heller fyrr no i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'So tok Abraham både sauer og naut og gav Abimelek, og dei gjorde ei semja seg imillom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Og Abraham sette sju gimberlamb av fenaden for seg sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Då sagde Abimelek med Abraham: «Kva tyder det at du hev sett desse sju lambi for seg sjølve?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, '«Desse sju lambi skal du hava av meg,» svara han; «det skal vera til vitnemål for meg, at eg hev grave denne brunnen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Difor kalla dei den staden Be’erseba. For der gjorde dei båe eiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'So gjorde dei då ei semja i Be’erseba. Og Abimelek og Pikol, hovdingen yver heren hans, tok ut og for heim att til Filistarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Og Abraham sette ei tamariska i Be’erseba, og der kalla han på Herren, ævordoms Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Og Abraham heldt lenge til i Filistarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Ei tid etter dette hadde gjenge fyre seg, hende det at Gud vilde røyna Abraham. Og han sagde til honom: «Abraham!» Og Abraham svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Då sagde han: «Tak no son din, din einberningsson, honom som du held so av, Isak, og far til Morialand; der skal du gjera eit brennoffer og ofra honom på eit av fjelli, som eg skal segja deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Morgonen etter reis Abraham tidleg upp, og klyvja asnet sitt, og tok med seg tvo av drengjerne sine og Isak, son sin. Og då han hadde kløyvt ved til brennofferet, gav han seg på vegen, og gjekk til den staden som Gud hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Tridje dagen då Abraham skoda kring seg, såg han staden han skulde til, langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Då sagde Abraham til drengjerne sine: «Ver no de her hjå asnet. Eg og sveinen, me vil ganga dit burt og beda, og so kjem me hit til dykk att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'So tok Abraham offerveden og lagde på Isak, son sin, og sjølv tok han elden og kniven i handi, og so gjekk dei tvo eine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Då sagde Isak med Abraham, far sin: «Du far!» sagde han. Og han sagde: «Ja, barnet mitt!» «Sjå, her er elden og veden,» sagde Isak, «men kvar er lambet som me skal ofra?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Og Abraham sagde: «Gud veit nok råd til eit offerlamb, barnet mitt.» Og so gjekk dei tvo eine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Då dei so kom til den staden som Gud hadde sagt, då bygde Abraham eit altar og lagde veden til rettes. So batt han Isak, son sin, og lagde honom på altaret, ovanpå veden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Og Abraham rette ut handi og tok kniven, og vilde ofra son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Då ropa Herrens engel til honom frå himmelen og sagde: «Abraham, Abraham!» Og han svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Då sagde han: «Legg ikkje hand på sveinen, og gjer honom ikkje noko! For no veit eg at du hev age for Gud, sidan du ikkje ein gong sparde din einberningsson for mi skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Då Abraham skoda kring seg, fekk han auga på ein ver, som hekk fast etter horni i kjørri attanfor honom. So gjekk Abraham dit og tok veren, og ofra honom i staden for son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Og Abraham kalla den staden: «Herren veit råd». Difor segjer dei den dag i dag: «På Herrens fjell veit dei råd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Og Herrens engel ropa endå ein gong frå himmelen til Abraham');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'og sagde: «Ved meg sjølv sver eg,» segjer Herren: «for di du gjorde dette, og ikkje ein gong sparde din einberningsson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'so skal eg storom velsigna deg og auka ætti di endelaust, som stjernorne på himmelen og sanden på havsens strand. Di ætt skal taka borgerne frå sine fiendar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'og i di ætt skal alle folk på jordi velsignast, for di du lydde etter ordi mine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'So gjekk Abraham attende til drengjerne sine, og dei tok på heimvegen, og fylgdest åt til Be’erseba. Og Abraham vart buande i Be’erseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Ei tid etter dette hadde hendt, kom det ein og sagde med Abraham: «Nahor, bror din, og Milka hev og fenge born:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Us, som er eldst, og Buz, bror hans, og Kemuel, far til Aram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'og Kesed og Haso og Pildas og Jidlaf og Betuel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Og Betuel var far åt Rebekka. Desse åtte sønerne fekk Nahor, bror åt Abraham, med Milka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Og med fylgjekona si, ho heitte Re’uma, fekk han og born; det var Tebah og Gaham og Tahas og Ma’aka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Alderen hennar Sara vart hundrad og sju og tjuge år; det var liveåri hennar Sara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Og Sara døydde i Arbabyen, som no heiter Hebron, i Kana’ans-land. Og Abraham gjekk heim og øya og gret yver Sara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Sidan reis Abraham upp, og gjekk burt ifrå liket, og han tala til Hets-sønerne og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '«Ein framand er eg imillom dykk, ein utlending. Lat meg få ein gravstad til eiga hjå dykk, so eg kann få gøyma henne som eg hev mist.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Då svara Hets-sønerne Abraham og sagde med honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '«Høyr her, gode herre! Ein gjæv hovding er du imillom oss. I den beste av graverne våre kann du jorda henne som du hev mist. Ingen av oss skal meinka deg gravi si til å jorda henne i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Då reiste Abraham seg, og bøygde seg for landslyden, for Hets-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'og so tala han til deim og sagde: «Samtykkjer de det, at eg gøymer henne som eg hev mist, so gjer vel og tel for Efron, son åt Sohar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'at han let meg få Makpelahelleren, som han eig, og som ligg i utkanten av gjordet hans. Han skal få gode pengar for honom, er so han vil selja meg honom, her midt imillom dykk, til eigande gravstad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Men Efron sat midt imillom Hets-sønerne, og Efron, hetiten, svara Abraham, so dei høyrde på det, Hets-sønerne, alle dei som sokna til tingstaden hans, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '«Nei, høyr her, gode herre! Det gjordet gjev eg deg, og helleren som er der, den gjev eg deg og, for augo åt landsmennerne mine gjev eg deg honom. Jorda du henne som du hev mist!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Då bøygde Abraham seg for landslyden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'og han tala til Efron, so landslyden høyrde på det, og sagde: «Gjev du vilde høyra på meg! Eg legg det som gjordet er verdt. Tak imot det av meg, so eg der kann få jorda henne som eg hev mist!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Og Efron svara Abraham og sagde med honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '«Høyr her, gode herre! Eit jordstykke, som er verdt fire hundrad sylvdalar, kva er det millom meg og deg? Jorda du henne som du hev mist!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Og Abraham merkte seg ordi hans Efron, og Abraham vog upp åt Efron det sylvet han hadde tala um medan Hets-sønerne høyrde på det, fire hundrad sylvdalar, av deim som gjekk og galdt millom kjøpmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Og gjordet hans Efron i Makpela, som ligg austanfor Mamre, både gjordet og helleren som der var, og alle dei tre som på gjordet voks, so vidt det rokk rundt ikring, vart skøytt');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'til Abraham, so dei såg på det, Hets-sønerne, alle dei som sokna til tingstaden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Sidan jorda Abraham Sara, kona si, i helleren på Makpelagjordet, austanfor Mamre, der Hebron no ligg, i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Og gjordet med helleren som var der, kom frå Hets-sønerne yver på Abrahams hender, so han fekk det til eigande gravstad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham var gamall og langt uti åri. Men Herren hadde velsigna honom i eitt og alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Og Abraham sagde med tenaren sin, han som var den eldste i huset og rådde yver alt det han åtte: «Kjære deg, legg handi di i fanget mitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'so vil eg taka ein eid av deg ved Herren, som er Gud i himmelen og Gud på jordi, at du ikkje skal lata son min gifta seg med nokor av døtterne åt Kana’ans-folket, som eg bur i lag med;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'men til heimlandet mitt og til mitt eige folk skal du fara og festa ei kona åt Isak, son min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Då sagde tenaren med honom: «Men um no ikkje ho vil fylgja meg hit til dette landet, skal eg då taka son din attende til det landet som du er komen ifrå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Og Abraham svara: «Vara deg, so du ikkje fer dit att med son min!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Herren, Gud i himmelen, som tok meg ut or farshuset mitt og fødesheimen min, og som tala til meg, og svor meg til og sagde: «Di ætt vil eg gjeva dette landet» - han skal senda sin engel fyre deg, so du der finn ei kona åt son min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Men vil ikkje ho fylgja deg, so skal du vera løyst ifrå eiden, berre far ikkje dit att med son min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Då lagde tenaren handi si i fanget åt Abraham, husbonden sin, og svor honom eiden på dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'So tok tenaren ti kamelar, av deim som husbonden hans åtte, og for av garde, og med seg hadde han alle slag gilde ting, som høyrde husbonden hans til; og han tok ut, og for til Mesopotamia, til byen hans Nahor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Og han let kamelarne leggja seg ned utanfor byen, innmed vatsbrunnen; det var i kveldingi, det bilet då kvendi plar koma ut og henta vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Og han sagde: «Herre, du som er Gud åt Abraham, husbonden min, å, lat det laga seg godt for meg i dag, og gjer vel imot Abraham, husbonden min!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Sjå, no stend eg her innmed vatskjelda, medan døtterne åt bymennerne kjem ut etter vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Lat det då vera so, at den møyi som eg segjer dette med: «Kjære væne, halla på krukka di, og lat meg få drikka!» og som svarar: «Drikk du, og kamelarne dine skal eg og gjeva drikka!» - at ho er den du hev etla åt Isak, tenaren din, og på det skal eg skyna at du vil gjera vel mot husbonden min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Og sjå: fyrr han hadde tala til endes, bar det so til at Rebekka, dotter hans Betuel, son åt Milka og Nahor, bror hans Abraham, kom ut, med krukka si på oksli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Det var ei ovvæn gjenta, ei ungmøy, som ingen kar hadde vore nær. Ho gjekk ned til kjelda, og fyllte krukka si, og kom upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Då sprang tenaren imot henne og sagde: «Kjære væne, lat meg få drikka litt vatn av krukka di!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Og ho sagde: «Drikk, gode herre!» og ho skunda seg og tok krukka si ned i handi og gav honom drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Og då han hadde drukke seg utyrst, sagde ho: «No skal eg henta vatn åt kamelarne dine og, til dei fær nøgdi si.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'So nøytte ho seg og tømde krukka i troi, og sprang so burt til brunnen att etter vatn, og ho brynnte alle kamelarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Og mannen stirde på henne og tagde; han vilde sjå, um Herren let ferdi hans lukkast, eller ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Då so kamelarne hadde drukke, tok mannen fram ein gullring, som vog ein halvt lodd, og tvo gullband, som ho skulde hava kring armarne; dei vog ti lodd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Og han sagde: «Kven er du dotter åt? Kjære deg, seg meg det! Hev far din rom til å hysa oss i natt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Og ho svara: «Eg er dotter hans Betuel, son åt Nahor og Milka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Me hev fullt upp både av halm og for,» sagde ho til honom, «og husrom for dykk hev me og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Då lagde mannen seg på kne, og takka Herren og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, '«Lova vere Herren, Gud åt Abraham, husbonden min! Han hev ikkje gløymt sin nåde og truskap mot husbonden min. Herren hev leidt meg rette vegen fram til brorfolket åt husbonden min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Men møyi sprang heim til mor si og fortalde alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebekka hadde ein bror som heitte Laban. Og Laban sprang ut til kjelda, til mannen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'då han fekk sjå ringen og gullbandi som syster hans hadde kring armarne, og då han høyrde Rebekka, syster hans, sagde: «Det og det sagde mannen med meg,» so gjekk han og vilde finna mannen, og sjå: der stod han hjå kamelarne attmed kjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Då sagde han: «Kom inn, du som Herren hev velsigna so rikleg! Kvi stend du her ute? Og eg hev skipa i huset og stelt til rom åt kamelarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'So gjekk mannen inn i huset, og klyvja av kamelarne; og hin kom med halm og for åt kamelarne, og med vatn åt honom og deim som var med honom, til å två føterne i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Og dei sette fram mat åt honom; men han sagde: «Eg vil ikkje eta fyrr eg hev bore upp målemnet mitt.» «Seg fram!» sagde hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Då sagde han: «Eg er tenaren hans Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Herren hev storleg velsigna husbonden min, so han hev vorte rik; han hev gjeve honom sauer og naut, og sylv og gull, og drengjer og gjentor, og kamelar og asen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Og Sara, kona åt husbonden min, åtte ein son på sine gamle dagar; honom hev han gjeve alt det han eig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Og husbonden min tok ein eid av meg og sagde: «Du skal ikkje lata son min gifta seg med nokor av døtterne åt Kana’ans-folket, som eg bur i lag med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Men til farshuset mitt skal du fara, og til mi eigi ætt, og festa ei kona åt son min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Då sagde eg til husbonden min: «Men um no ikkje ho vil fylgja meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Og han sagde med meg: «For Herrens åsyn hev eg ferdast; han skal senda sin engel med deg og lata ferdi di lukkast, so du finn ei kona åt son min av mi eigi ætt og i farshuset mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Då skal du vera løyst ifrå eiden, når du kjem til mi eigi ætt; og vil dei ikkje gjeva deg henne, so er du og løyst ifrå eiden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'So kom eg då i dag til kjelda, og eg sagde: «Herre, du som er Gud åt Abraham, husbonden min! Å vilde du lata ferdi mi lukkast for meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Sjå no stend eg her innmed vatskjelda; lat det då vera so: når det kjem ei møy ut etter vatn, og eg segjer med henne: «Kjære væne, lat meg få drikka litt vatn av krukka di,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'og ho då segjer med meg: «Drikk du, og til kamelarne dine skal eg og henta vatn,» so er ho det vivet som Herren hev etla åt son til husbonden min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Fyrr eg fekk sagt alt det eg hadde på hjarta, sjå, då kom Rebekka ut, med krukka si på oksli, og ho gjekk ned til kjelda og auste upp vatn. Og eg sagde med henne: «Kjære væne, lat meg få drikka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Då skunda ho seg og tok krukka si ned av oksli, og sagde: «Drikk du, og kamelarne dine skal eg og gjeva drikka.» So drakk eg, og kamelarne gav ho og vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Og eg spurde henne: «Kven er du dotter åt?» «Dotter hans Betuel, son åt Nahor og Milka,» sagde ho. Då sette eg ringen i nosi hennar, og gullbandi på armarne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Og eg lagde meg på kne og takka Herren, og eg lova Herren, Gud åt Abraham, husbonden min, for di han hadde styrt meg på rette vegen til å finna brordotter åt husbonden min for son hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Vil de no vera snilde og trugne mot husbonden min, so seg meg det, og vil de ikkje, so seg meg det, so eg kann venda meg på ei onnor leid!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Då svara Laban og Betuel og sagde: «Dette kjem frå Herren! Me kann ingen ting segja deg, korkje vondt eller godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Sjå her hev du Rebekka! Tak henne og far heim att, og lat son åt husbonden din få henne til kona, som Herren hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Då tenaren hans Abraham høyrde dei ordi, lagde han seg å gruve og takka Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Og tenaren tok fram sylvty og gullty og væne klæde og gav Rebekka, og mor hennar og bror hennar gav han og gode gåvor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'So åt dei og drakk, han og dei mennerne som var med honom, og dei var der um natti. Men då dei reis upp um morgonen, sagde han: «Lat meg få fara heim att til husbonden min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Då sagde bror hennar og mor hennar: «Lat møyi få drygja eit bil hjå oss, ei åtte ti dagar; sidan kann du fara!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Men han sagde med deim: «Heft meg ikkje, no Herren hev late ferdi mi lukkast! Lat meg få taka i vegen og fara heim att til husbonden min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Då sagde dei: «Me skal ropa på møyi og spyrja henne sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'So ropa dei på Rebekka og sagde med henne: «Vil du fara med denne mannen?» «Ja, det vil eg,» sagde ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'So bad dei vel fara med Rebekka, syster si, og fostermor hennar, og med tenaren hans Abraham og mennerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Og dei velsigna Rebekka og sagde med henne: «Du syster vår, måtte du verta til tusund gonger titusund. Og måtte ætti di borgern’ ifrå sine uvener taka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Og Rebekka og møyarne hennar ferda seg til, og steig på kamelarne, og fylgde mannen. Og tenaren tok Rebekka med seg og for av garde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isak var nyst heimkomen: han hadde vore burt til «Kjelda åt den som liver, og ser meg»; for han budde i Sudlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Og Isak gjekk ute på marki og lengta, medan det for til å kvelda. Og då han såg upp og skoda kring seg, sjå, då kom der kamelar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Og Rebekka såg upp, og gådde Isak. Då sprang ho ned av kamelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'og sagde til tenaren: «Kven er denne mannen som kjem imot oss på marki?» «Det er husbonden min,» sagde tenaren. Då tok ho sløret og hadde attfor andlitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'So fortalde tenaren Isak alt det han hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Og Isak leidde henne inn i den tjeldbudi som Sara, mor hans, hadde havt, og tok Rebekka heim til seg, og ho vart kona hans, og han heldt henne kjær. So fekk Isak trøyst i sorgi yver mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Og Abraham tok seg ei kona att; ho heitte Ketura.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Med henne fekk han Simran og Joksan og Medan og Midjan og Jisbak og Suah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Og Joksan var far til Sjeba og Dedan. Og sønerne hans Dedan var Assurar og Letusar og Leummar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Og sønerne hans Midjan var Efa og Efer og Hanok og Abida og Elda’a. Alle desse var borni hennar Ketura.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraham gav Isak alt det han åtte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Men sønerne åt fylgjekonorne sine gav Abraham gåvor og let deim flytja burt frå Isak, son sin, og taka austetter, til Austerland, medan han endå livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Og dette er dagarne hans Abraham og den alderen han nådde: hundrad og fem og sytti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Og Abraham sålast og døydde etter ein god alderdom, gamall og mett av dagar, og kom til federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Og Isak og Ismael, sønerne hans, jorda honom i Makpelahelleren, på gjordet hans Efron, son åt Sohar, hetiten, austanfor Mamre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'det gjordet som Abraham hadde kjøpt av Hets-sønerne. Der vart Abraham og Sara, kona hans, jorda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Men då Abraham var slokna, gav Gud velsigningi si til Isak, son hans. Og Isak, han budde attmed «Kjelda åt den som liver, og ser meg».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dette er ættartalet åt Ismael, son hans Abraham, han som Abraham fekk med Hagar frå Egyptarland, terna hennar Sara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Og dette er namni på sønerne hans Ismael, dei namni som er i ættarsoga deira: Nebajot, det var eldste son hans Ismael, og Kedar og Adbe’el og Mibsam');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'og Misma og Duma og Massa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'og Hadar og Tema og Jetur og Nafis og Kedma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dette var sønerne hans Ismael, og dette var namni deira, med grenderne og lægri deira, tolv ættarhovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Og dette er liveåri hans Ismael: hundrad og sju og tretti år. Og han sålast og døydde, og kom til federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Og dei budde frå Havila til Sur, som ligg midt for Egyptarland, når du tek leidi mot Assur. Midt for augo åt alle brørne sine slo han seg ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dette er ættarsoga hans Isak, son åt Abraham:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Abraham var far åt Isak. Og Isak var fyrti år gamall, då han gifte seg med Rebekka, dotter åt Betuel, aramæaren frå Mesopotamia, syster åt Laban, aramæaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Og Isak bad til Herren for Rebekka, kona si, av di ho var barnlaus. Og Herren høyrde bøni hans, og Rebekka, kona hans, vart umhender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Men borni drogst i livet hennar. Då sagde ho: «Er det so, kvi skal eg då vera til?» Og ho gjekk av stad og spurde Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Og Herren sagde til henne: «I livet ditt er lydar tvo, Tvo folk skal frå ditt fang seg greina; Eitt folk er sterkare enn hitt. Den eldre skal den yngre tena!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Då so tidi hennar kom, at ho skulde eiga barn, sjå, då var det tvillingar i livet hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Og den som kom fyrst, var raud, og loden yver allan, som ein feld; so kalla dei honom Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Og då bror hans kom, heldt han med handi i hælen på Esau. So kalla dei honom Jakob. Då dei kom til verdi, var Isak seksti år gamall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Og sveinarne voks upp, og Esau vart ein glup veidemann, og heldt til i skog og mark; men Jakob var ein mild og fredsam kar, og heldt seg heime, attmed tjeldbuderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Og Isak tykte gildast um Esau, for han åt gjerne vilt; men Rebekka tykte gildast um Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Ein gong koka Jakob ein velling; då kom Esau heim av skogen, og var trøytt og mod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Og Esau sagde med Jakob: «Å lat meg få gløypa i meg noko av det raude, dette raude der; eg er reint kvitt!» Difor kallar dei honom Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Då sagde Jakob: «Sel meg fyrst odelen din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Og Esau sagde: «Du ser, eg er åt og skal døy; kva skal eg då med odelen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, '«Gjer fyrst eiden på det!» sagde Jakob. So gjorde Esau eiden på det, og selde odelen sin til Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Og Jakob gav Esau brød og linsevelling, og han åt, og drakk, og reis upp, og gjekk sin veg. So lite vyrde Esau odelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Og det kom eit uår, so det vart stor naud i landet, liksom fyrre gongen, medan Abraham livde. Då for Isak til Gerar, til Abimelek, filistarkongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Og Herren synte seg for honom og sagde: «Far ikkje ned til Egyptarland! Bu i det landet som eg segjer deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Hald til i dette landet! Eg skal vera med deg og velsigna deg; for deg og ætti di vil eg gjeva alle desse landi; eg vil halda den eiden eg svor Abraham, far din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Og eg vil lata ætti di aukast, so ho vert som stjernorne på himmelen, og eg vil gjeva ætti di alle desse landi, og i di ætt skal alle folk på jordi velsignast,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'for di Abraham lydde meg, og heldt alt det eg vilde han skulde halda, bodi og fyresegnerne og loverne mine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'So vart Isak buande i Gerar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Og mennerne der i bygdi spurde honom ut um kona hans. Då sagde han: «Ho er syster mi.» For han torde ikkje segja at ho var kona hans; han var rædd mennerne i bygdi kunde slå honom i hel for Rebekka skuld, av di ho var so væn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Men då han hadde vore der eit bil, bar det so til, at Abimelek, filistarkongen, skvatta ut igjenom vindauga og fekk sjå at Isak heldt gaman med Rebekka, kona si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Og Abimelek kalla Isak til seg og sagde: «No ser me ho er kona di! Kvi sagde du då at ho var syster di?» «Eg tenkte eg kunde koma til å missa livet for hennar skuld,» svara Isak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Då sagde Abimelek: «Kva er det du hev gjort imot oss! Kor lett kunde ikkje det ha hendt, at einkvar av folket hadde lege med kona di, og då hadde du lagt ei stor synd på oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Sidan tala Abimelek til alt folket og lyste ut dei ordi: «Den som rører denne mannen eller kona hans, han skal lata livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isak sådde der i landet, og det året fekk han hundrad foll; for Herren velsigna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Og mannen tok til å verta rik, og vart rikare og rikare, til han var ovrik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Han hadde mykje bufe, både smått og stort, og mange drengjer, og filistarane vart ovundsjuke på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Og alle dei brunnar som drengjerne åt far hans hadde grave medan Abraham, far hans, livde, deim kasta filistarane att, og fyllte deim med jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Og Abimelek sagde med Isak: «Flyt burt ifrå oss! du hev vorte for stor for oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'So flutte Isak burt, og lægra i Gerardalen, og der vart han buande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Og Isak grov upp att dei brunnarne som dei hadde grave medan Abraham, far hans, livde, og som filistarane hadde fyllt att då Abraham var burte, og han kalla deim det same som far hans hadde kalla deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Og drengjerne hans Isak grov der i dalen, og fann ei vatsådr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Då tok hyrdingarne frå Gerar til å trætta med hyrdingarne hans Isak, og sagde: «Det er vårt vatn.» Og Isak kalla den brunnen Esek, av di dei hadde dregest med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Sidan grov dei ein annan brunn. Den trætta dei og um, og han kalla honom Sitna');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'So flutte han burt derifrå, og grov ein ny brunn. Den trætta dei ikkje um, og han kalla honom Rehobot, og sagde: «No hev Herren gjort det romt for oss, so me kann veksa i landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Sidan for han derifrå upp til Be’erseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Og same natti synte Herren seg for honom, og sagde: «Eg er Gud åt Abraham, far din. Ver ikkje rædd, eg er med deg; eg skal velsigna deg og lata ætti di aukast for Abraham skuld, han som var tenaren min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'So bygde han eit altar der, og kalla på Gud. Og der sette han upp tjeldbudi si, og drengjerne hans grov ein brunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Sidan kom Abimelek til honom frå Gerar med Ahusat, venen sin, og Pikol, herhovdingen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Då sagde Isak med deim: «Kvi kjem de hit til meg, de som hev hata meg og jaga meg burt ifrå dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Og dei svara: «Me ser det grant at Herren er med deg, og no segjer me: «Kom, lat oss sverja ein eid oss imillom, me og du, og lat oss få gjera ei semja med deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'at du ikkje skal gjera oss noko vondt, liksom heller ikkje me rørde deg, men berre gjorde vel imot deg, og let deg fara i fred.» No er du den som Herren hev velsigna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'So gjorde han eit gjestebod for deim, og dei åt og drakk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Og tidleg um morgonen reis dei upp, og gjorde eiden åt kvarandre. Sidan bad Isak farvel med deim, og dei for burt ifrå honom i fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Same dagen hende det at drengjerne hans Isak kom og sagde frå um den brunnen dei hadde grave. «No hev me funne vatn!» sagde dei med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Og han kalla brunnen Sjib’a. Difor heiter byen Be’erseba den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Då Esau var fyrti år gamall, gifte han seg med Jehudit, dotter åt ein hetit som heitte Be’eri, og med Basmat, dotter åt ein annan hetit, som heitte Elon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Og det vart ei hjartesorg for Isak og Rebekka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Då Isak var gamall vorten, og tok til å dimmast på syni, so han ikkje kunde skilja, då kalla han til seg Esau, eldste son sin, og sagde: «Du son min!» Og Esau svara: «Ja, her er eg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Då sagde han: «No er eg gamall vorten og veit ikkje kva dag eg kann døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Tak no du veidegogni di, pilehuset og bogen, og gakk ut i marki, og veid meg noko vilt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'og laga ein god rett åt meg, soleis som du veit eg likar det, og kom so inn til meg med det; då vil eg eta, so sjæli mi kann få velsigna deg, innan eg døyr.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Og Rebekka lydde på at Isak tala til Esau, son sin. So gjekk Esau ut i marki og vilde veida noko vilt og hava med seg heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Då sagde Rebekka med Jakob, son sin: «Høyr her!» sagde ho, «eg lydde på at far din tala til Esau, bror din, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '«Kom heim med noko vilt, og laga ein god rett åt meg, so eg fær eta; då vil eg velsigna deg for Herrens åsyn, innan eg døyr.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Lyd no du meg, son min, og gjer som eg segjer deg fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gakk burt i buflokken, og tak tvo gode kidungar, so skal eg laga ein god rett av deim åt far din, soleis som eg veit han likar det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'og du skal ganga inn til far din med det, so han fær eta og kann velsigna deg, fyrr han døyr!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Då sagde Jakob med Rebekka, mor si: «Du veit Esau, bror min, er loden, og eg er snaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Kann henda far min trivlar på meg. Då trur han eg vil hava honom til narr, og eg fær ei våbøn yver meg og ingi velsigning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, '«Den våbøni skal eg taka på meg, son min,» sagde mor hans. «Berre lyd du meg, og gakk og henta meg kidi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Då gjekk han og henta deim, og kom til mor si med deim, og mor hans laga ein god rett, soleis som ho visste far hans vilde lika det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'So tok Rebekka dei beste klædi åt Esau, eldste son sin - dei låg inni huset hjå henne - og hadde deim på Jakob, yngste son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Og skinni av kidungarne hadde ho på henderne hans og på halsen hans der han var snaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'So let ho Jakob, son sin, få den gode retten og brødet som ho hadde stelt til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'og han gjekk inn til far sin, og sagde: «Far!» Og han sagde: «Ja, her er eg. Kven er du, guten min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Då sagde Jakob med far sin: «Eg er Esau, eldste son din. Eg hev gjort som du bad meg. Ris no upp, og set deg og et av det eg hev veidt, so sjæli di kann velsigna meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Og Isak sagde med son sin: «So snøgg som du var til å finna det, son min!» Og han sagde: «Herren, din Gud, sende det imot meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Då sagde Isak med Jakob: «Kom då hit, guten min, og lat meg få kjenna på deg um du er Esau, son min, eller ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'So gjekk Jakob innåt Isak, far sin, og han trivla på honom og sagde: «Det er målet hans Jakob, men henderne hans Esau.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Og han kjende honom ikkje; for henderne hans var lodne som henderne åt Esau, bror hans; og han velsigna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, '«Er du Esau, son min?» sagde han. Og han svara: «Ja, det er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, '«Set no fram åt meg då,» sagde Isak, «og lat meg få eta av det som son min hev veidt, so sjæli mi kann velsigna deg!» Då sette han fram åt honom, og han åt, og han kom med vin til honom, og han drakk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'So sagde Isak, far hans, med honom: «Kom no hit, og kyss meg, son min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Då gjekk han burt til honom og kysste honom, og han kjende angen av klædi hans, og velsigna honom og sagde: «Sjå, som angen av ei eng som Herren signa, so angar det av sonen min!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'So gjeve Gud deg dogg frå himlen høge, og engjar av dei feitaste på jordi, og nøgdi utav korn og druvesaft!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Deg tjoder tena skal, og folkeslag skal falla deg til fota. Ver herre yver brørne dine! Borni åt mor di bøygje seg for deg! Forbanna vere dei som deg forbannar! Velsigna vere dei som deg velsignar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Med same Isak hadde velsigna Jakob - det var ikkje meir enn so vidt at Jakob var komen ut att frå Isak, far sin - då kom Esau, bror hans, heim att or veideskog.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Han og laga ein god rett og bar inn til far sin. So sagde han med far sin: «Vil ikkje far risa upp og eta av det som son hans hev veidt, so sjæli di kann velsigna meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Og Isak, far hans, spurde honom: «Kven er du?» Og han svara: «Eg er Esau, eldste son din.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Då vart Isak so forfærd at han skalv, og han sagde: «Kven var det då som veide vilt og kom til meg med? Eg åt av alt saman, og velsigna honom, fyrr du kom, og no lyt han vera velsigna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Då Esau høyrde dei ordi av far sin, sette han i eit skrik so høgt og sårt, at det var ilt å høyra. So sagde han med far sin: «Velsigna meg, velsigna meg og, far!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Men han svara: «Bror din kom med velor og tok velsigningi di.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, '«Heiter han då ikkje med rette Jakob?» sagde Esau. «Meg hev han no svike tvo gonger. Fyrst tok han odelen min, og sjå no hev han teke velsigningi mi.» So sagde han: «Hev du ikkje att ei velsigning til meg og?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Og Isak svara Esau og sagde: «Sjå, no hev eg sett honom til herre yver deg, og alle brørne hans hev eg gjort til hans tenarar, og med korn og druvesaft hev eg styrkt honom! Kva kann eg so gjera for deg, son min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Og Esau sagde med far sin: «Hev du då berre denne eine velsigningi, far? Velsigna meg, velsigna meg og, far!» Og Esau gret høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Då tok Isak, far hans, til ords att, og sagde til honom: «Sjå, langt burte frå dei feite bøarne din bustad vera skal, og utan himmeldoggi ovantil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Av sverdet ditt du liva skal, og tena lyt du broder din, men ein gong kjem den tid du riv deg laus, og rister oket hans av halsen din.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Men Esau hata Jakob for den velsigningi som far hans hadde lyst yver honom, og Esau sagde med seg sjølv: «Snart kjem den tidi då me lyt syrgja yver far min; då skal eg drepa Jakob, bror min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Og Rebekka fekk vita kva Esau, eldste son hennar, hadde sagt. Då sende ho bod etter Jakob, yngste son sin, og sagde med honom: «Høyr her! Esau, bror din, vil hemna seg på deg og drepa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Lyd no meg, son min: tak ut og røm til Kharan, til Laban, bror min,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Og ver hjå honom eit bil, til harmen hev gjenge av bror din,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'til vreiden hans hev gjeve seg, og han hev gløymt det du hev gjort imot honom! Då skal eg senda bod og henta deg heim att. Kvi skulde eg missa dykk båe tvo på ein dag?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'So sagde Rebekka med Isak: «Eg er so leid av livet for desse Hets-døtterne skuld! Skulde no Jakob og taka seg ei kona utav Hets-døtterne, slik ei som desse, ei her ifrå landet, kva hadde eg då liva etter?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Og Isak kalla Jakob inn til seg og velsigna honom, og talde for honom og sagde med honom: «Du skal ikkje taka noko Kana’ans-kvende til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Gjer deg reidug og far til Mesopotamia, til huset åt Betuel, morfar din: få deg der ei kona, ei av døtterne hans Laban, morbror din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Og Gud den Allvelduge velsigne deg, og late ætti di veksa og aukast, so du vert til ein heil flokk med tjoder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Han gjeve deg velsigningi åt Abraham, både deg og ætti di med deg, so du kjem til å eiga det landet du no held til i, det som Gud gav Abraham!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'So bad Isak farvel med Jakob, og han for til Mesopotamia, til Laban Betuelsson, aramæaren, som var bror hennar Rebekka, mor åt Jakob og Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Då Esau såg at Isak hadde velsigna Jakob og sendt honom til Mesopotamia, av di han vilde at han skulde få seg ei kona derifrå, at han hadde velsigna honom, og talt for honom og sagt: «Du skal ikkje taka noko Kana’ans-kvende til kona!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'og at Jakob hadde lydt foreldri sine, og fare til Mesopotamia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'og då Esau såg at Isak, far hans, mislika Kana’ans-kvendi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'so gjekk han til Ismael, og tok Mahalat, dotter åt Ismael, son hans Abraham, syster åt Nebajot, til kona, attåt dei andre konorne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Og Jakob tok ut frå Be’erseba, og gav seg på vegen til Kharan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'So kom han til ein stad som han laut gjeva seg til um natti; for soli var gladd. Og han tok ein av steinarne som låg der, og hadde til hovudgjerd, og lagde seg so til å sova på den staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Då drøymde han, og såg ein stige, som stod på jordi og rakk med øvste enden upp i himmelen, og han såg at Guds englar kleiv upp og ned etter stigen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Og sjå: Herren stod uppyver honom og sagde: «Eg er Herren, Gud åt Abraham, godfar din, og Gud åt Isak. Dette landet som du no ligg i, det vil eg gjeva deg og ætti di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Og ætti di skal verta som dusti på jordi, og du skal greina deg ut i vest og i aust og i nord og i sud, og i deg og di ætt skal alle folk på jordi velsignast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Og sjå, eg skal vera med deg og vara deg kvar du so fer, og leida deg attende til dette landet: eg skal ikkje sleppa deg utor augo, fyrr eg hev gjort det eg hev lova deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Då Jakob vakna or svevnen, sagde han: «Ja sanneleg er Herren på denne staden, og eg som ikkje visste det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'So kom det ein otte yver honom, og han sagde: «Kor ageleg han er, denne staden! Dette må vera Guds hus, og her er porten til himmelen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Um morgonen tidleg reis Jakob upp, og tok den steinen han hadde havt til hovudgjerd, og reiste honom upp til eit merke, og slo olje uppå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Og han kalla den staden Betel. Men fyrr heitte byen Luz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Og Jakob gjorde ein lovnad og sagde: «Er Gud med meg og varar meg på den vegen eg ferdast etter, og gjev meg mat å eta og klæde å klæda meg med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'og eg kjem vel heim att til huset åt far min, so skal Herren vera min Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'og denne steinen, som eg hev reist upp til eit merke, han skal verta eit gudshus, og av alt du gjev meg, skal eg svara deg tiend.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'So tok Jakob i vegen att, og gjekk til han kom til Austmannalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Og då han skoda kring seg, såg han ein brunn på marki og tri saueflokkar som låg der innmed; for av den brunnen vatna dei buskapen. Men steinen som låg yver brunnen, var stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Og når alle buflokkarne hadde samla seg der, velte dei steinen av brunnen, og vatna feet, og so lagde dei steinen på staden sin att, yver brunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Og Jakob spurde deim: «Kvar er de frå, brørne mine?» Då sagde dei: «Me er frå Kharan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'So spurde Jakob: «Kjenner de Laban, son åt Nahor?» Og dei svara: «Ja, me kjenner honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, '«Liver han vel?» spurte Jakob. «Ja, det gjer han,» sagde dei, «og sjå der kjem Rakel, dotter hans, med sauerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Då sagde han: «Sjå, soli stend endå høgt; det er ikkje tidi å sanka buskapen endå. Lat sauerne få drikka, og gakk av og gjæt att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, '«Det kann me ikkje, fyrr alle buflokkarne hev kome i hop,» sagde dei. «Då velter me steinen av brunnen, og vatnar feet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Medan han stod og tala med deim, kom Rakel med buskapen åt far sin; for det var ho som gjætte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Og då Jakob såg Rakel, dotter åt Laban, morbror sin, og såg buskapen hans, so gjekk han innåt, og velte steinen av brunnen, og vatna feet åt Laban, morbror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Og Jakob kysste Rakel, og gråten tok honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Og Jakob sagde det med Rakel at han var skyld far hennar, og at han var son åt Rebekka. Då sprang ho heim, og sagde det med far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Med same Laban fekk høyra um Jakob, systerson sin, sprang han imot honom, og slo armarne kring honom, og kysste honom mange gonger, og bad honom med seg heim. So fortalde han Laban alt det som hendt hadde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Og Laban sagde med honom: «Ja menn er me same folket!» So var han hjå honom ein månads tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Då sagde Laban med Jakob: «Skulde du tena hjå meg for inkje, for di um du er systerson min? Seg ifrå kva du vil hava i løn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'No hadde Laban tvo døtter; den eldste heitte Lea, og den yngste heitte Rakel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Og Lea var daudøygd, men Rakel var både velvaksi og væn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Og Jakob hadde huglagt Rakel, og sagde: «Eg skal tena hjå deg i sju år, fær eg Rakel, den yngste dotteri di.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Og Laban svara: «Det er betre eg gjev deg henne, enn at eg gjev henne til ein framand mann. Ver du hjå meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'So tente Jakob i sju år for Rakel, og dei åri tykte han var som nokre få dagar, av di han var so sæl utav henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Sidan sagde Jakob med Laban: «Lat meg no få kona mi! for tidi mi er ute, og eg vil taka henne heim til meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Då bad Laban i hop alt folket der i grendi, og gjorde eit gjestebod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Og um kvelden tok han Lea, dotter si, og leidde henne inn til honom, og han sov hjå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Og Laban let henne få Zilpa, tenestgjenta si: ho skulde tena hjå Lea, dotter hans, no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Men um morgonen - sjå, då var det Lea! Då sagde han til Laban: «Kvi hev du fare soleis åt imot meg! Var det ikkje for Rakel eg tente! Kvi hev du svike meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, '«Me hev ikkje det for vis her i landet,» svara Laban, «å gifta burt den som yngre er fyre den som er eldre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Ver no hjå denne til brudlaupsvika er ute, so skal me gjeva deg den andre og, er so at du vil tena hjå meg i sju år til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Og Jakob gjorde so, og var hjå henne til brudlaupsdagarne var ende. Då gav Laban honom Rakel, dotter si, til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Og han let Rakel, dotter si, få Bilha, tenestgjenta si: no skulde ho tena hjå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Og Jakob tok Rakel og heim til seg, og han heldt meir av Rakel enn av Lea. Sidan tente han endå sju år til hjå Laban.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Då Herren såg at Lea var vanvyrd, let han henne få born, men Rakel fekk ingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Og Lea vart med barn, og åtte ein son, og kalla honom Ruben. «Herren hev set kor vondt eg hev det,» sagde ho, «no kjem mannen min til å halda av meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Og ho vart med barn ein gong til, og åtte ein son, og sagde: «Herren hev høyrt at eg var vanvyrd; difor gav han meg denne og.» So kalla ho honom Simeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Og ho vart med barn endå ein gong, og åtte ein son, og sagde: «No lyt fulla mannen min halda seg til meg, sidan han hev fenge tri søner med meg.» Difor kalla dei honom Levi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Og ho vart med barn fjorde gongen, og åtte ein son, og sagde: «No vil eg lova Herren.» Difor kalla ho honom Juda. So fekk ho ikkje fleire born då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Då Rakel såg at ho og Jakob ikkje fekk born, vart ho ovundsjuk på syster si, og sagde med Jakob: «Lat meg få born, elles so døyr eg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Då vart Jakob harm på Rakel og sagde: «Er eg i staden åt Gud, som hev meinka deg born?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Då sagde ho: «Sjå her er Bilha, terna mi. Gakk inn til henne, so ho kann føda på fanget mitt og hjelpa meg og til ein son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'So gav ho honom Bilha, terna si, til kona, og Jakob gjekk inn til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Og Bilha vart med barn, og fekk ein son med Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Då sagde Rakel: «Gud hev dømt i mi sak: han høyrde bøni mi, og gav meg ein son.» So kalla ho honom Dan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Og Bilha, terna hennar Rakel, vart med barn att, og fekk ein son til med Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Då sagde Rakel: «Harde otor hev eg stade med syster mi, og no hev eg vunne.» So kalla ho honom Naftali.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Då Lea såg at ho ikkje fekk fleire born, tok ho Zilpa, terna si, og gav Jakob til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Og Zilpa, terna hennar Lea, fekk ein son med Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Då sagde Lea: «No hadde eg lukka med meg!» So kalla ho honom Gad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Og Zilpa, terna hennar Lea, fekk ein son til med Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Då sagde Lea: «Å sæle meg! Droserne kjem til å sælka meg!» So kalla ho honom Asser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ein dag i skurdonni gjekk Ruben av og fann rune-eple på marki, og bar deim heim til Lea, mor si. Då sagde Rakel med Lea: «Kjære væne, gjev meg nokre av dei rune-epli som son din hev funne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Men ho svara henne: «Er det ikkje nok at du hev teke mannen min? Vil du no taka rune-epli åt son min og?» Då sagde Rakel: «Det er det same, fær eg rune-epli åt son din, so kann mannen få sova hjå deg i natt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Um kvelden, då Jakob kom heim frå marki, gjekk Lea til møtes med honom og sagde: «Det er hjå meg du skal vera i natt; eg hev tinga deg for rune-epli åt son min.» So sov han hjå henne den natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Og Gud høyrde Lea, og ho vart med barn, og åtte den femte sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Då sagde Lea: «No hev Gud gjeve meg mi løn, for di eg let mannen få terna mi.» So kalla ho honom Issakar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Og Lea vart med barn att, og åtte den sette sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Då sagde Lea: «Gud hev gjeve meg ei god gåva. No kjem mannen min til å bu hjå meg, sidan han hev fenge seks søner med meg.» So kalla ho honom Sebulon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Sidan åtte ho ei dotter, og kalla henne Dina.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Då kom Gud i hug Rakel, og Gud høyrde bønerne hennar, og gjorde henne barnkjømd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'So vart ho då umhender, og åtte ein son. Då sagde ho: «Gud hev teke burt skammi mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Og ho kalla honom Josef og sagde: «Gjev Herren vilde lata meg få ein son til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Då no Rakel hadde fenge Josef, sagde Jakob med Laban: «Slepp meg or tenesta, so eg kann fara heim til mitt eige land!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Lat meg få konorne og borni mine, som eg hev tent for, so vil eg fara! For du veit sjølv kor lenge eg hev tent hjå deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Då sagde Laban med honom: «Hadde du berre noko godvilje for meg! Eg hev fenge ei vitring um at det er for di skuld Herren hev velsigna meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Set berre på kva du vil hava i løn,» sagde han, «so skal eg gjeva deg det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Og Jakob sagde med honom: «Du veit sjølv kor vel eg hev tent deg, og korleis bufeet ditt hev muna, medan eg hev stelt med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'For det var lite du hadde, fyrr eg kom hit, og no hev det auka mengdevis, og Herren hev velsigna deg for kvart fet eg gjekk. Men når skal no eg få syta for mitt eige hus?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, '«Kva skal eg gjeva deg?» sagde hin. «Du tarv ikkje gjeva meg noko,» sagde Jakob. «Vil du gjera som eg no segjer, so skal eg gjæta buskapen din og sjå etter honom, som eg hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'I dag vil eg ganga gjenom heile buskapen din og skilja ut alt som er droplut eller spreklut, både det som er svart i saueflokken, og det som er spreklut eller droplut i geiteflokken, og det skal vera løni mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Og mi truheit skal svara for meg, når du heretter kjem og ser yver løni mi: Finst det hjå meg nokor geit som ikkje er droplut eller spreklut, eller nokon sau som ikkje er svart, so er dei stolne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Då sagde Laban: «Ja ja, lat det vera som du segjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Og same dagen skilde han ut dei bukkarne som var salute og spreklute, og alle dei geiterne som var droplute og spreklute, alt som det var noko kvitt på, og alt som var svart i saueflokken, og let sønerne sine taka vare på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Og han lagde tri dagsleider millom seg og Jakob. Og Jakob laut gjæta det som att var av fenaden hans Laban.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Men Jakob fann seg grøne stavar av poppel og mandeltre og løn, og randa deim, so den kvite veden synte millom borkerenderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Og stavarne, som han hadde randa, sette han upp i trørne i vatskuporne, der småfeet kom og skulde drikka, midt for augo på småfeet; for det var jamt dei flaug, når dei kom og skulde drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'So para småfeet seg innmed stavarne, og fekk ungar som var salute og droplute og spreklute.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Men lambi skilde Jakob ifrå og let småfeet venda augo mot det som var droplut, og mot alt som var svart i buskapen hans Laban. Soleis fekk han seg flokkar for seg sjølv, og hadde deim ikkje i hop med buskapen hans Laban.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Og kvar gong det var trivelegt småfe som flaug, so sette Jakob randestavarne i trørne, midt for augo på deim, so dei skulde para seg innmed stavarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Men var det slikt som ikkje vilde trivast, so sette han ikkje stavarne der. Soleis fekk Laban det feet som ikkje vilde trivast, og Jakob det som var trivelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Og mannen vart rikare og rikare, og fekk mykje bufe, og gjentor og drengjer, og kamelar og asen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'So fekk han høyra at sønerne hans Laban hadde sagt: «Jakob hev teke alt det som far vår åtte, og av det som far vår åtte, hev han lagt seg til all denne rikdomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Og Jakob såg på andlitet hans Laban at han var ikkje den same mot honom som han hadde vore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Og Herren sagde til Jakob: «Far attende til landet åt federne dine og til ditt eige folk, og eg skal vera med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Då sende Jakob bod etter Rakel og Lea og bad deim koma ut på marki, til buskapen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Og han sagde med deim: «Eg ser på andlitet åt far dykkar at han er ikkje den same mot meg som fyrr. Men Gud åt far min hev vore med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Og de veit at eg hev tent far dykkar det beste eg vann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Og far dykkar hev svike meg og brigda um att løni mi dei ti gongerne. Men Gud let honom ikkje få lov til å gjera meg nokon skade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Når han sagde so: «Dei droplute skal vera løni di,» so fekk alt småfeet droplute ungar; og når han sagde so: «Dei salute skal vera løni di,» so fekk alt småfeet salute ungar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Soleis tok Gud feet frå far dykkar og gav meg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Og ved det leitet då småfeet flaug, drøymde eg at eg let upp augo og såg ikring meg, og sjå, då var bukkarne som sprang på småfeet, salute og droplute og skjengjute.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Og Guds engel sagde til meg i draume: «Jakob!» og eg svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Då sagde han: «Lat upp augo, so skal du få sjå at alle bukkarne som spring på småfeet, er salute og droplute og skjengjute. For eg hev set korleis Laban fer åt mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Eg er din Gud frå Betel, der som du salva steinen, der som du gjorde meg ein lovnad. Gjer deg no reidug og far ut or dette landet og attende til fødesheimen din!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Då svara Rakel og Lea og sagde med honom: «Hev då me endå nokon lut og arv i huset åt far vår?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Hev ikkje han rekna oss for framande? Han hev selt oss, og longe øydt upp det han fekk for oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'All rikdomen som Gud hev teke frå far vår, høyrer oss og borni våre til. Gjer no berre du alt det som Gud hev sagt til deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'So budde Jakob seg til ferdi, og sette borni og konorne sine på kamelarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Og han tok med seg alt bufeet sitt og alt godset som han hadde samla seg, det feet som han åtte og hadde ale seg til i Mesopotamia, og vilde fara til Isak, far sin, i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban hadde gjenge av og skulde klyppa sauerne sine. Då stal Rakel med seg husgudarne som far hennar hadde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Og Jakob stal seg burt ifrå Laban, aramæaren, og gat ikkje noko um at han vilde fara sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Han tok ut med alt det han åtte, og gav seg på vegen, og sette yver elvi, og tok leidi mot Gileadfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Tridje dagen etter fekk Laban vita at Jakob hadde stroke sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Då tok han med seg skyldfolki sine, og sette etter honom sju dagsleider, og nådde honom att på Gileadfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Men Gud kom til Laban, aramæaren, i draume um natti, og sagde til honom: «Vara deg no og seg ikkje eit ord til Jakob!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Då Laban nådde att Jakob, hadde Jakob sett upp tjeldbudi si på fjellet; og Laban og skyldfolki hans sette og upp budi si på Gileadfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Og Laban sagde med Jakob: «Kva tyder det at du hev stole deg burt ifrå meg og drege døtterne mine av garde, som dei var hertekne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Kvi løynde du deg av, og stal deg burt ifrå meg? Kvi sagde du det ikkje med meg, so eg kunde fylgt deg på vegen med glederop og song og trummor og harpor?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Du let meg ikkje ein gong få kyssa borni og døtterne mine. Dette var uvisleg gjort av deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Eg hev det i mi magt å gjera dykk ilt. Men Gud åt far dykkar sagde til meg i natt: «Vara deg no og seg ikkje eit ord til Jakob!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Men var det no so at du laut taka ut, av di du lengta so sårt etter fødesheimen din, kvi stal du då gudarne mine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Då svara Jakob og sagde med Laban: «Eg var rædd; eg tenkte du kunde taka døtterne dine frå meg med hardom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Men den som du finn gudarne dine hjå, han skal ikkje liva. Sjå no etter, og lat skyldfolki våre vera vitne, um du kannast med noko av det eg hev med meg, og tak det so til deg!» Men Jakob visste ikkje at Rakel hadde teke deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Og Laban gjekk inn i budi hans Jakob og i budi hennar Lea og i budi åt båe ternorne, men fann ikkje noko. So gjekk han ut or budi hennar Lea, og inn i budi hennar Rakel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Men Rakel hadde teke husgudarne, og lagt deim under klyvsalen, og sett seg på deim. Og Laban rannsaka heile budi, men fann ikkje noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Og ho sagde med far sin: «Far må ikkje vera vond, for di eg ikkje kann reisa meg upp for honom! For det er so med meg no som stundom plar vera med kvendi.» Og han leita både høgt og lågt, men fann ikkje husgudarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Då vart Jakob harm, og skjemde på Laban. Og Jakob tok til ords og sagde med Laban: «Kva hev eg forbrote? kva vondt hev eg gjort, sidan du elter meg so?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Då du rannsaka alt det eg hev, kva fann du då som høyrer huset ditt til? Legg det fram her og lat mine og dine skyldfolk få sjå det, so dei kann døma millom oss tvo!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'No hev eg vore hjå deg i tjuge år: Søyorne og geiterne dine hev aldri kasta, og verarne i fenaden din hev eg ikkje ete upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Det som var ihelrive, kom eg ikkje heim til deg med. Sjølv bøtte eg skaden. Av meg kravde du det, anten det var stole um dagen eller um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Um dagen vilde hiten tyna meg, og kulden um natti, og eg fekk ikkje svevn på augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Tjuge år er det no eg hev vore hjå deg; fjortan år hev eg tent for båe døtterne dine, og seks år for fenaden din; men du brigda um att løni mi dei ti gongerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Hadde ikkje Gud åt far min, han som var Gud åt Abraham, og som Isak ber age for, hadde ikkje han vore med meg, so hadde du visst no sendt meg burt med tvo hender tome. Men Gud såg mi møda og alt mitt slæp, og han jamna det for meg i natt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Då svara Laban og sagde med Jakob: «Det er mine døtter, og mine born, og min buskap, og mitt alt du ser. Kva skulde eg då no gjera desse døtterne mine eller borni deira, som dei hev født til verdi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'So kom no og lat oss gjera ei semja, eg og du, og den skal vera til vitnemål millom meg og deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'So tok Jakob ein stein og reiste honom upp til eit merke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Og Jakob sagde med skyldfolki sine: «Sanka i hop stein!» So fann dei seg steinar, og bygde ein varde, og sette seg og åt der, innmed varden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Og Laban kalla varden Jegar Sahaduta, og Jakob kalla honom Gal’ed.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Og Laban sagde: «No er denne varden vitne millom meg og deg.» Difor kalla dei honom Gal’ed,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'og Mispa, «av di,» sagde han, «Herren skal halde vakt millom meg og deg, når me hev kome einannan or syne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Fer du ille med døtterne mine, eller tek du deg andre konor attåt døtterne mine, då er det fulla ingen mann innmed oss, men kom i hug det: Gud er vitne millom meg og deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Og Laban sagde med Jakob: «Sjå, denne varden og denne merkesteinen, som eg hev reist millom meg og deg -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'vitne skal dei vera, både varden og merkesteinen, at ikkje skal eg fara framum denne varden, burt til deg, og ikkje skal du fara hitum denne varden og denne merkesteinen, heim til meg, på det som vondt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Gud åt Abraham og Gud åt Nahor døme millom oss, han som var Gud åt far deira!» So svor Jakob ved honom som Isak, far hans, bar age for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Og Jakob ofra eit slagtoffer på fjellet, og bad skyldfolki sine eta med seg. Og dei åt med honom, og var på fjellet um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Um morgonen tidleg reis Laban upp, og kysste barneborni og døtterne sine, og velsigna deim. So tok Laban ut, og for heim att til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Og Jakob for sin veg framigjenom, og Guds englar møtte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Då Jakob såg deim, sagde han: «Dette er Guds herlæger,» og han kalla den staden Mahanajim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Og Jakob sende folk fyre seg til Se’irlandet, til Edomsmarki, med bod til Esau, bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Og han sagde deim fyre: «So skal de segja med herren min, Esau: «So segjer Jakob, tenaren din: «Eg hev halde til hjå Laban, og trøytt der til no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Og eg hev fenge meg uksar og asen og småfe og drengjer og gjentor, og no var eg huga til å senda deg bod um dette, herre bror, um eg kunde gjera deg blid på meg.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Og dei kom attende til Jakob og sagde: «Me råka Esau, bror din, og rett no kjem han sjølv til møtes med deg, og fire hundrad mann med honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Då vart Jakob ovleg rædd, og det var so bringa hans vilde snøra seg i hop. Og han bytte folket som var med honom, og sauerne og nauti og kamelarne, i tvo hopar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'og sagde: «Um Esau kjem yver den eine hopen og slær honom ned, so kann den hopen som att er, få berga seg undan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Og Jakob sagde: «Du Gud åt Abraham, godfar min, du Gud åt Isak, far min, du Herre, som sagde til meg: «Far attende til landet ditt og fødesheimen din, og eg skal gjera vel imot deg» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'eg er ikkje verd all den miskunn og all den truskap du hev vist imot tenaren din; for med stav i hand gjekk eg yver denne Jordanelvi, og no er eg vorten til tvo store hopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Å, berga meg for Esau, bror min; for eg er so rædd honom; eg ottast han kann koma og slå i hel meg og mine, både mor og born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Du hev då sjølv sagt: «Eg skal allstødt gjera vel imot deg og lata ætti di verta som havsens sand, som det ikkje er tal på.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'So var han der um natti, og av alt det han åtte, tok han ut ei gåva til Esau, bror sin:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'tvo hundrad geiter og tjuge bukkar, tvo hundrad søyor og tjuge verar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'tretti mjølkekamelar med fyli deira, fyrti kvigor og ti vetrungsuksar, tjuge asenfyljur og ti asenfolar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Og han let drengjerne sine fara i vegen med dette, kvar drift for seg, og sagde med deim: «Far de fyre meg, og lat det vera eit godt stykke millom kvar drift!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'So sagde han med den fyrste av deim: «Når Esau, bror min, møter deg, og han talar til deg og spør: «Kven høyrer du til, og kvar skal du av, og kven eig den bølingen, som du driv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'då skal du segja: «Jakob, tenaren din; det er ei gåva han sender Esau, herren min, og snart kjem han sjølv etter.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Sameleis tala han til den andre og den tridje og til alle drivarane, og sagde: «De som eg no hev sagt, skal de segja med Esau, når de møter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Og dette skal de og segja: «Snart kjem Jakob, tenaren din, etter.»» For han tenkte: «Eg vil blidka honom med denne gåva, som eg sender fyre meg, og sidan vil eg sjå honom i andlitet; kann henda han då tek vel imot meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'So for dei fyre med gåva, og sjølv var han i lægret den natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Same natti reis han upp, og tok båe konorne og båe ternorne sine og alle dei elleve sønerne sine og gjekk yver Jabbokvadet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Han tok og flutte deim yver åi, og alt han åtte, førde han yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'So var Jakob att åleine. Då kom det ein mann og drogst med honom radt til i dagingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Og då han såg at han ikkje kunde råda med honom, snart han mjødmeskåli hans, og mjødmi gjekk or led på Jakob, medan dei drogst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Og han sagde: «Slepp meg, for no er det dagen.» Men Jakob sagde: «Eg slepper deg ikkje, utan du velsignar meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, '«Kva heiter du?» spurde mannen. «Jakob,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Då sagde mannen: «Du skal ikkje lenger heita Jakob, men Israel. For du hev stridt med Gud og med menner, og vunne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Og Jakob spurde honom og sagde: «Kjære deg, seg meg namnet ditt!» Men han svara: «Kvi spør du etter namnet mitt?» Og han velsigna honom der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Og Jakob kalla den staden Peniel; «for eg hev set Gud, andlit mot andlit,» sagde han, «og endå berga livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Og med same han var komen framum Penuel, rann soli. Og han var halt i mjødmi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Difor er det so den dag i dag, at Israels-sønerne aldri et den store seni som er på mjødmeskåli, av di han snart mjødmeskåli hans Jakob på den store seni der er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Og Jakob skoda framyver, og sjå, der kom Esau og fire hundrad mann med honom. Då skifte han borni millom Lea og Rakel og båe ternorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'og sette ternorne og borni deira fremst, og Lea og borni hennar attanfor, og Rakel og Josef attarst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Og sjølv gjekk han fram fyre deim, og bøygde seg nedåt jordi sju gonger, til dess han kom tett innåt bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Men Esau sprang imot honom, og tok honom i fanget, og lagde armarne um halsen hans, og kysste honom, og dei gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Då han såg upp, vart han var konorne og borni; då sagde han: «Kva er dette for folk du hev med deg?» «Det er dei borni som Gud hev unnt tenaren din,» sagde Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'So gjekk ternorne fram med borni sine og bøygde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Og Lea og borni hennar gjekk og fram og bøygde seg. Sidan gjekk Josef og Rakel fram og bøygde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Då sagde han: «Kva vilde du med heile denne buskapen som eg møtte?» «Eg vilde gjera deg blid på meg, herre bror,» sagde hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Då sagde Esau: «Eg hev nok, bror. Hav du sjølv det som ditt er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, '«Å nei, kjære væne!» sagde Jakob. «Hev du noko godvilje for meg, so tak imot gåva mi! For då eg såg deg i andlitet, var det som eg såg Guds andlit, med di du var so blid imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Kjære deg, tak imot gåva eg sende deg! For Gud hev vore god mot meg, og eg hev nok av alle slag.» Og han nøydde honom, til han tok imot det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'So sagde Esau: «Lat oss taka ut og koma i vegen, so skal eg fara jamte med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Men Jakob sagde: «Du veit, herre bror, at borni ikkje toler mykje, og eg hev lambsøyor og nybære kyr å taka vare på. Driv ein deim for hardt, um det berre er ein dag, so døyr heile buskapen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Vil ikkje du gjera vel og fara fyre meg, herre bror! So kann eg rusla so smått, etter som drifterne og borni orkar til, til dess eg kjem til deg i Se’ir.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, '«So vil eg lata nokre av dei mennerne eg hev med, vera att hjå deg,» sagde Esau. «Kvi då?» sagde hin; «berre du vil vera blid på meg, herre bror!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'So snudde Esau um same dagen, og for sin veg heim att til Se’ir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Og Jakob tok vegen til Sukkot, og bygde seg eit hus, og til buskapen sin gjorde han skålar. Difor kallar dei den staden Sukkot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Og Jakob kom seg vel fram til Sikemsbyen i Kana’ans-land, den gongen han for frå Mesopotamia, og han fann seg eit læger framanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Og det jordstykket som han hadde sett upp tjeldbudi si på, kjøpte han av sønerne hans Hemor, far åt Sikem, for hundrad gullpengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Og han bygde eit altar der, og kalla det: «Gud er Gud åt Israel».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina, dotter åt Jakob og Lea, gjekk ein gong ut og vilde sjå på droserne i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Og Sikem, son åt Hemor, heviten, som var hovding i landet, såg henne, og han tok henne, og låg med henne, og tok æra hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Og hugen hans stod til Dina, dotter åt Jakob; for han hadde fenge henne kjær. Og han tala blidt til gjenta og hugga henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Sidan tala Sikem til Hemor, far sin, og sagde: «Lat meg få den møyi til kona!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Og Jakob fekk høyra at han hadde skjemt ut Dina, dotter hans. Men sønerne hans var med buskapen utpå marki, og Jakob tagde med det, til dei kom heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Men Hemor, far hans Sikem, gjekk ut til Jakob og vilde tala med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Sønerne hans Jakob kom heim frå marki, då dei fekk høyra dette. Og det gjorde kararne ilt, og dei var ovleg harme. For han hadde fare skamleg åt mot Israel, med di han hadde lege hjå dotter hans Jakob; slikt skulde aldri henda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Då tala Hemor med deim og sagde: «Sikem, son min, hev huglagt dotter dykkar; kjære væne, lat honom få henne til kona!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Lat oss gifta borni våre i hop: gjev oss døtterne dykkar, og tak de våre døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Og gjev dykk so til hjå oss. De hev heile landet fyre dykk. De kann få bu her, og fara fritt kring i landet og få dykk eigedomar her.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Og Sikem sagde med far hennar og brørne hennar: «Kunde eg berre få gjort dykk blide på meg! Det de krev av meg, skal de få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Krev so mykje de vil av meg i festarfe og i benkjargåva! Eg skal gjeva det de vil hava, berre eg fær møyi til kona!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Men sønerne hans Jakob svara Sikem og Hemor, far hans, med svikfulle ord, for di han hadde skjemt ut Dina, syster deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, '«Me kann ikkje gjera det,» sagde dei, «og gjeva syster vår til ein mann som hev huvehold; det vilde vera ei vanæra for oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Berre på det vilkåret kann me laga oss etter dykk, at de vert liksom me, og alle karar hjå dykk vert umskorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Då skal me gjeva dykk døtterne våre, og taka dykkar døtter til konor, og bu hjå dykk, so me vert eitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Men vil de ikkje lyda oss og lata dykk umskjera, so tek me syster vår, og fer burt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Og dei tykte vel um ordi deira, både Hemor og Sikem, son hans Hemor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Og sveinen drygde ikkje, men gjorde dette. For han heldt av dotter hans Jakob, og han var den gjævaste i heile ætti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'So møtte Hemor og Sikem, son hans, til tings i byen sin, og dei tala til bymennerne og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '«Desse mennerne vil gjerne vera vener med oss. Dei vil gjeva seg til her og fara kring i landet, og de veit at landet er vidt nok åt deim til alle kantar. Me skal taka døtterne deira til konor, og gjeva deim våre døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Men berre på eitt vilkår vil dei laga seg etter oss og bu hjå oss, so me vert eitt folk, og det er at alle karar hjå oss vert umskorne, som dei er sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Buskapen deira og godset deira og klyvdyri deira, vert ikkje alt det vårt, når me berre lagar oss etter deim, so dei gjev seg til hjå oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Og dei lydde Hemor og Sikem, son hans, alle som åtte heime der i byen; og alle karar, dei som åtte heime der i byen, vart umskorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'So hende det den tridje dagen, då dei var sjuke av verken, at tvo av sønerne hans Jakob, Simeon og Levi, sambrørne hennar Dina, tok sverdi sine, og storma inn i byen, medan folki var trygge, og drap alle karar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Og dei hogg ned Hemor og Sikem, son hans, med kvasse sverd, og tok Dina ut or huset hans Sikem, og drog burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Sønerne hans Jakob kom yver deim som falne var, og herja byen, for di dei hadde skjemt ut syster deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Dei tok sauerne og nauti deira og asni deira, både det som var i byen og det som var på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Og alt godset deira og alle borni og kvendi deira rana dei og drog av med, og alt som i husi var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Då sagde Jakob med Simeon og Levi: «De hev gjort meg ei stor sorg! De veld at eg fær eit uord på meg hjå landslyden, kananitarne og perizitarne. Me er då berre ein liten flokk, og samlar dei seg imot meg, so kjem dei til å slå meg i hel, og tyna både meg og mitt hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, '«Skulde han fara åt med syster vår som med ei skjøkja?» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Og Gud sagde til Jakob: «Gjer deg reidug, og far upp til Betel, og gjev deg til der, og bygg eit altar åt Gud, han som synte seg for deg, då du rømde for Esau, bror din.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Då sagde Jakob med husfolket sitt og alle deim som var med honom: «Få burt dei framande gudarne, som er hjå dykk, og fjelga dykk, og byt klæde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Og lat oss so taka ut og fara upp til Betel! Der vil eg byggja eit altar åt Gud, han som høyrde bøni mi den dagen eg var i fåre, og som var med meg på den vegen eg for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Då let dei Jakob få alle dei framande gudarne som dei hadde hjå seg, og ringarne som dei hadde i øyro; og Jakob grov det ned under den eiki som stend innmed Sikem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'So tok dei ut, og ein otte frå Gud kom yver byarne rundt ikring deim, so dei sette ikkje etter Jakobs-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Og Jakob kom til Luz, som ligg i Kana’ans-land - no heiter det Betel - både han og alt folket som var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Der bygde han eit altar, og kalla den staden «Gud i Betel»; for der hadde Gud synt seg for honom den gongen han rømde for bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Då døydde Debora, fostermor hennar Rebekka, og ho vart jorda nedanfor Betel, attunder ei eik; den kallar dei Gråtareiki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Gud synte seg endå ein gong for Jakob, den tid han kom frå heim Mesopotamia, og velsigna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Og Gud sagde til honom: «Du heiter Jakob! heretter skal du ikkje heita Jakob; Israel skal du heita!» Sidan kalla dei honom Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Og Gud sagde til honom: «Eg er Gud, den Allvelduge. Du skal veksa og aukast! Eit folk, ei mengd med folkeslag skal ættast frå deg, og undan deg skal kongar alast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Og det landet som eg gav Abraham og Isak, det vil eg gjeva deg; ætti di etter deg vil eg gjeva det landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'So for Gud upp ifrå honom på den staden han var då han tala med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Då reiste Jakob upp ein stein på den staden han var då han tala med honom, ein minnestein, og auste drykkoffer på honom, og slo olje utyver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Og Jakob kalla den staden han var då Gud tala med honom, Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'So tok dei ut att frå Betel, og då dei hadde att som eit augneleite til Efrat, fekk Rakel barnilt, og ho vart strengt sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Og medan ho låg i hardaste riderne, sagde ljosmori med henne: «Syt ikkje no! Her hev du ein son att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Og i det same ho sålast - for ho laut døy - kalla ho honom Benoni; men far hans kalla honom Benjamin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Då Rakel var slokna, vart ho jorda frammed vegen til Efrat, som no heiter Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Og Jakob reiste upp ein minnestein på gravi hennar. Det er gravsteinen hennar Rakel; han stend der den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'So tok Israel ut att, og sette upp tjeldbudi si burtanfor Bølingstårnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Medan Israel budde der i landet, hende det at Ruben gjekk av og låg hjå Bilha, fylgjekona åt far hans. Og Israel fekk vita det. Sønerne hans Jakob var tolv i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Sønerne hennar Lea var Ruben, eldste son hans Jakob, og Simeon og Levi og Juda og Issakar og Sebulon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Og sønerne hennar Rakel var Josef og Benjamin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Og sønerne åt Bilha, terna hennar Rakel, var Dan og Naftali.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Og sønerne åt Zilpa, terna hennar Lea, var Gad og Asser. Dette var sønerne hans Jakob, som han hadde fenge i Mesopotamia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Og Jakob kom til Isak, far sin, i Mamre, tett innmed Arbabyen, som no heiter Hebron, der som Abraham og Isak hadde halde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Og dagarne hans Isak vart hundrad og åtteti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Då sålast Isak og døydde, og kom saman med federne sine, gamall og mett av dagar. Og Esau og Jakob, sønerne hans, fylgde honom til gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Dette er ætti hans Esau eller Edom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau tok seg konor av Kana’ans-folket: Ada, dotter åt Elon, hetiten, og Åhålibama, dotter åt Ana, sonedotter åt Sibeon, heviten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'og Basmat, dotter åt Ismael, syster åt Nebajot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Og Esau fekk med Ada sonen Elifaz, og med Basmat sonen Re’uel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Og med Åhålibama fekk han sønerne Je’us og Jalam og Korah. Dette var sønerne hans Esau, som han fekk i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Og Esau tok konorne sine og sønerne og døtterne sine og heile huslyden sin og buskapen sin og alle klyvdyri sine og alt godset sitt, som han hadde sanka i Kana’ans-land, og flutte burt frå Jakob, bror sin, og av til eit anna land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'For dei åtte so mykje fe, at dei kunde ikkje bu saman; landet som dei heldt til i, kunde ikkje føda deim, so stor var buskapen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'So sette Esau seg ned i Se’irfjelli; Esau, det er den same som Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Og dette er ætti hans Esau, far åt Edom-folket i Se’irfjelli:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dette er namni på sønerne hans Esau: Elifaz, son åt Ada, kona hans Esau, og Re’uel, son åt Basmat, kona hans Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Og sønerne hans Elifaz var Teman og Omar og Sefo og Gatam og Kenaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Og Elifaz, son hans Esau, hadde ei fylgjekona som heitte Timna. Med henne fekk Elifaz sonen Amalek. Dette var sønerne hennar Ada, kona hans Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Og dette er sønerne hans Re’uel: Nahat og Zerah, Samma og Mizza. Dette var sønerne åt Basmat, kona hans Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Og dette er sønerne åt Åhålibama, dotter hans Ana, sonedotter hans Sibeon, kona hans Esau: med henne fekk Esau sønerne Je’us og Jalam og Korah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dette er jarlarne åt Esau-folket: Sønerne åt Elifaz, eldste son hans Esau, var Teman-jarlen, Omar-jarlen, Sefo-jarlen, Kenaz-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Korah-jarlen, Gatam-jarlen, Amalek-jarlen. Det var dei jarlarne som var ætta frå Elifaz i Edomlandet. Dette var sønerne åt Ada.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Og dette er sønerne hans Re’uel, son åt Esau: Nahat-jarlen, Zerah-jarlen, Samma-jarlen, Mizza-jarlen. Det var dei jarlarne som var ætta frå Re’uel i Edomlandet. Dette var sønerne åt Basmat, kona hans Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Og dette er sønerne åt Åhålibama, kona hans Esau: Je’us-jarlen, Jalam-jarlen, Korah-jarlen. Det var dei jarlarne som var ætta frå Åhålibama Anasdotter, kona hans Esau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Dette var Esaus-sønerne, og dette var jarlarne deira. Dette var Edom-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Dette er sønerne åt Se’ir, horiten, som hadde bygt landet: Lotan og Sobal og Sibeon og Ana');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'og Dison og Eser og Disan. Det var jarlarne åt horitarne, Se’ir-folket i Edomlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Og sønerne hans Lotan var Hori og Hemam, og syster hans Lotan var Timna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Og dette er sønerne hans Sobal: Alvan og Manahat og Ebal, Sefo og Onam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Og dette er sønerne hans Sibeon: Aja og Ana. Ana var det som fann dei heite kjeldorne i øydemarki, medan han gjætte asni åt Sibeon, far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Og dette er borni hans Ana: Dison og Åhålibama Anasdotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Og dette er sønerne hans Dison: Hemdan og Esban og Jitran og Keran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dette er sønerne hans Eser: Bilhan og Za’avan og Akan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dette er sønerne hans Dison: Us og Aran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dette er jarlarne åt horitarne: Lotan-jarlen, Sobal-jarlen, Sibeon-jarlen, Ana-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Dison-jarlen, Eser-jarlen, Disan-jarlen. Det var jarlarne åt horitarne, fylkeshovdingarne deira, i Se’irlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Og dette er dei kongarne som rådde yver Edomlandet, fyrr det rådde nokon konge yver Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, son åt Beor, var konge i Edom, og byen han sat i heitte Dinhaba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Og Bela døydde, og Jobab, son åt Zerah, frå Bosra, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Og Jobab døydde, og Husam frå Temanitarlandet vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Og Husam døydde, og Hadad, son åt Bedad, vart konge i staden hans; han var det som vann yver midjanitarne på Moabmoen. Og byen hans heitte Avit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Og Hadad døydde, og Samla frå Masreka vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Og Samla døydde, og Saul frå Rehobot uppmed åi vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Og Saul døydde, og Ba’al-Hanan, son åt Akbor, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Og Ba’al-Hanan, son åt Akbor, døydde, og Hadar vart konge i staden hans, og hans by heitte Pa’u; og kona hans heitte Mehetabel, dotter åt Matred, som var dotter åt Mezahab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Og dette er jarlarne av Esau-ætti, etter sine ætter, i sine bustader, med sine namn: Timna-jarlen, Alva-jarlen, Jetet-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Åhålibama-jarlen, Ela-jarlen, Pinon-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Kenaz-jarlen, Teman-jarlen, Mibsar-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Magdiel-jarlen, Iram-jarlen. Det var jarlarne i Edom, etter bustaderne sine i det landet dei åtte. Dette var ætti hans Esau, far åt Edom-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob vart buande i Kana’ans-landet, der som far hans hadde halde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Dette er soga um Jakobs-ætti: Då Josef var syttan år gamall, gjætte han fenaden i lag med brørne sine; han var busvein hjå sønerne til Bilha og Zilpa, konorne åt far hans, og alt det vonde som vart sagt um deim, gjekk Josef til far deira med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Men Israel heldt Josef kjærast av alle borni sine, for han hadde fenge honom på sine gamle dagar; og han gjorde ein sid ermekjole åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Og då brørne hans såg at far deira heldt meir av honom enn av alle brørne hans, vart dei hatige på honom, og kunde ikkje tala eit godt ord til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Ein gong hadde Josef ein draum, som han fortalde brørne sine, og då vart dei endå meir hatige på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, '«No skal de høyra kva eg hev drøymt,» sagde han til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, '«Eg tykte me var utpå åkeren og skar. Best det var, reiste mitt kornband seg upp og stod, og dykkar kornband stod rundt ikring og bøygde seg for mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Då sagde brørne hans med honom: «Skal du, kann henda, verta kongen vår og råda yver oss?» Og sidan hata dei honom endå meir for draumarne og rødorne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'So hadde han ein draum att, og den fortalde han og brørne sine. «Veit de kva eg no hev drøymt?» sagde han: «Eg tykte soli og månen og elleve stjernor lagde seg å gruve for meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Men då han sagde det med far sin og brørne sine, skjemde far hans på honom og sagde med honom: «Kva er det no du hev drøymt att! Skulde eg og mor di og brørne dine koma og leggja oss å gruve for deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Og brørne hans var ovundsjuke på honom, men far hans lagde seg dette på minne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'So var det ein gong brørne hans var av og gjætte buskapen åt far sin burtmed Sikem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Då sagde Israel med Josef: «Gjæter ikkje brørne dine burtmed Sikem? Kom, eg vil senda deg til deim!» Og han svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Då sagde Israel med honom: «Kjære deg, gakk av og sjå korleis det stend til med brørne dine og korleis det er med buskapen, og kom so heim att og seg meg det!» Dermed so sende han Josef av stad frå Hebrondalen, og so kom han til Sikem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Medan han no vanka umkring i marki, møtte han ein mann, og mannen tala til honom og spurde: «Kva leitar du etter?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, '«Eg leitar etter brørne mine,» svara han. «Kjære deg, seg meg kvar dei gjæter!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, '«Dei hev teke ut herifrå,» sagde mannen: «Eg høyrde dei sagde: «No vil me til Dotan.»» So gjekk Josef til Dotan, og der fann han brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Dei såg honom langt burte, og fyrr han kom innåt deim, samråddest dei um å drepa honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'og dei sagde seg imillom: «Sjå, der kjem denne stordrøymaren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Kom og lat oss slå honom i hel og kasta honom ned i ein av desse brunnarne her, og so segja at eit udyr hev ete honom upp! Då skal me sjå kva det vert av draumarne hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Då Ruben høyrde det, vilde han berga honom utor henderne deira og sagde: «Lat oss ikkje taka livet hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Og Ruben sagde med deim: «Lat det ikkje renna blod! Kasta honom heller ned i denne brunnen, som er i øydemarki, men legg ikkje hand på honom!» Dette sagde han av di han vilde berga honom utor henderne deira og få honom heim att til far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Då no Josef var komen innåt brørne sine, hadde dei av honom kjolen hans, den side ermekjolen han gjekk i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'og tok og kasta honom ned i brunnen; men brunnen var tom; det var ikkje vatn i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'So sette dei seg ned, og vilde få seg mat. Men då dei såg upp og skoda kring seg, vart dei vare eit ferdafylgje: det var ismaelitar, som kom frå Gilead, og førde kryddor og balsam og rosekvåda på kamelarne sine; det var dei på veg til Egyptarland med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Då sagde Juda med brørne sine: «Kva bate hev me av det at me slær bror vår i hel og dyl dråpet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kom, og lat oss selja honom til ismaelitarne, og ikkje leggja hand på honom; han er då bror vår, vårt eige kjøt og blod!» Og brørne hans lydde honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'og då kjøpmennerne - dei var frå Midjan - for framum, drog dei Josef upp or brunnen, og so selde dei Josef for tjuge sylvdalar til ismaelitarne; og dei tok Josef med seg til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'So kom Ruben attende til brunnen, men då han skulde sjå, var ikkje Josef i brunnen. Då reiv han sund klædi sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'og han gjekk attende til brørne sine, og sagde: «Sveinen er der ikkje! Og eg, kvar skal eg no gjera av meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'So tok dei kjolen åt Josef, og slagta ein bukk, og duppa kjolen i blodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Og dei sende ermekjolen heim til far sin og sagde: «Denne hev me funne. Sjå etter um det ikkje er kjolen åt son din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Og han kjende honom att, og sagde: «Jau, det er kjolen åt son min. Eit udyr hev ete honom upp. Josef er ihelriven!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Og Jakob reiv sund klædi sine, og sveipte ein sekk um mjødmarne, og syrgde yver son sin i lang, lang tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Og alle sønerne og døtterne hans kom og vilde trøysta honom, men han let seg ikkje trøysta; «Med sorg og sut lyt eg fara ned til son min i nåheimen!» sagde han. Og far hans gret yver honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'men midjanitarne selde honom i Egyptarland, til Potifar, som var hirdmann hjå Farao og hovding yver livvakti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'I same tidi bar det so til at Juda for nedyver frå brørne sine, og gav seg til hjå ein mann i Adullam som heitte Hira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Der såg Juda dotter åt ein kananitisk mann som heitte Sua, og han tok henne til kona, og budde i hop med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Og ho vart med barn, og åtte ein son; honom kalla han Er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'So vart ho med barn ein gong til, og åtte ein son, og ho kalla honom Onan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Sidan åtte ho endå ein son, og kalla honom Sela; då ho fekk honom, var Juda i Kezib.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Og Juda feste ei kone åt Er, eldste son sin; ho heitte Tamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Men Herren tykte ille um Er, eldste son åt Juda, og Herren laga det so at han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Då sagde Juda med Onan: «Tak brorkona di heim til deg, og gift deg med henne, so du held uppe ætti åt bror din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Men Onan visste at borni ikkje skulde vera hans; og når han låg med enkja etter bror sin, let han det spillast på jordi, so han ikkje skulde gjeva bror sin avkjøme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Og Herren tykte ille um det han gjorde, og laga det so at han og døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Då sagde Juda til Tamar, sonekona si: «No lyt du sitja enkja i huset åt far din, til Sela, son min, er vaksen!» For han tenkte: «Elles kjem han og til å døy, som brørne hans.» So for Tamar heim att, og budde hjå far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Då det leid frametter ei tid, døydde dotter åt Sua, kona hans Juda. Og då syrgjetidi var ute, gjekk Juda upp til Timna, til deim som klypte sauerne hans, både han og venen hans, Hira frå Adullam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Og Tamar fekk spurt det; for det kom ein og sagde med henne: «Sjå, verfar din er på veg upp til Timna og vil klyppa sauerne sine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Då lagde ho av seg enkjebunaden sin, og kasta på seg ei kåpa og sveipte henne vel kring seg, og so sette ho seg frammed ledet utfor Enajim, på vegen til Timna. For ho såg at Sela var vaksen, og at ho ikkje fekk honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Då Juda såg henne, tenkte han det var ei skjøkja, av di ho heldt kåpa attfor andlitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'So tok han av vegen, og gjekk innåt henne og sagde: «Kom og lat meg få liggja med deg!» For han visste ikkje at det var sonekona hans. Då sagde ho: «Kva gjev du meg, er so du fær liggja med meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, '«Eg skal senda deg eit kid av buskapen min,» sagde han. «Gjev meg so noko i vissa då, til du sender meg det!» sagde ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, '«Kva vissa skal eg gjeva deg?» sagde han. «Seglringen din og lekkjet ditt og staven som du hev i handi,» sagde ho. Det gav han henne, og so fekk han liggja med henne, og ho vart fremmeleg med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Og ho stod upp og gjekk sin veg, og lagde av seg kåpa og hadde på seg enkjebunaden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Og Juda sende kidet med venen sin, han frå Adullam, og bad honom få att vissa av kvinna; men han fann henne ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Og han spurde folki i grendi hennar og sagde: «Kvar er skjøkja, ho i Enajim, frammed vegen?» Men dei sagde: «Det hev ikkje vore nokor skjøkje her.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'So kom han attende til Juda og sagde: «Eg fann henne ikkje, og folki der i grendi sagde endå det: «Det hev ikkje vore nokor skjøkja her.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Då sagde Juda: «Lat henne hava det, so me ikkje fær skam av dette! Kidet veit du no eg hev sendt, men du fann henne ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'So var det på lag tri månader etter, då kom dei og sagde med Juda: «Tamar, sonekona di, hev lagt seg burt, so ho jamvel hev vorte med barn.» Då sagde Juda: «Leid henne ut! Ho skal brennast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Då dei so leide henne ut, sende ho bod til verfar sin og sagde: «Det er med den mannen som eig dette, at eg hev vorte med barn. Du skulde vel ikkje vita kven som eig denne seglringen og lekki og staven?» sagde ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Og Juda kjendest med det, og sagde: «Ho er i sin gode rett imot meg; for eg let henne ikkje få Sela, son min.» Og han låg ikkje med henne meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Då det so leid til at ho skulde eiga barn, sjå, då var det tvillingar i livet hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Og i det same ho fødde, rette den eine handi fram. Då tok ljosmori og batt ein raud tråd kring handi hans, og sagde: «Denne kom fyrst.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Men so drog han handi attende, og då kom bror hans fram! Då sagde ho: «Korleis er det du bryt deg fram!» Og dei kalla honom Peres.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'So kom bror hans, han som hadde den raude tråden kring handi. Honom kalla dei Zerah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Og Josef, han vart førd ned til Egyptarland, og Potifar, ein egyptar, som var hirdmann hjå Farao og hovding yver livvakti, kjøpte honom av ismaelitarne, som hadde ført honom dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Men Herren var med Josef, so han vart ein mann som alt gjekk vel for. Han vart verande hjå husbonden sin, egyptaren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'og då husbonden hans såg at Herren var med honom og let alt han gjorde, lukkast for honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'so vart Josef både gjæv og gild i hans augo, og laut ganga honom til handa; og han sette honom til å styra huset sitt, og alt han åtte, lagde han i hans hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Og alt ifrå den tid han hadde sett honom yver huset sitt og yver alt det han åtte, so velsigna Herren huset åt egyptaren for Josef skuld; det fylgde ei Herrens velsigning med alt det han åtte, både i hus og på mark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'So let han då Josef råda yver alt det han åtte, og såg ikkje etter med honom i nokon ting, anna berre åt og drakk. Josef var både velvaksen og væn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Og det hende, då det leid um ei tid, at kona åt husbonden hans kasta augo på Josef og sagde: «Kom og ligg med meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Men han bar seg undan, og sagde med kona åt husbonden sin: «Sjå, husbonden min ser ikkje etter med meg i nokon ting i heile huset; alt han eig, hev han lagt i mine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Han hev ikkje meir å segja i dette huset enn eg, og hev ikkje meinka meg nokon ting utan deg, etter di du er kona hans. Korleis kunde eg då gjera so stygg ei gjerning, og so synda mot Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Som ho no tala til Josef dag etter dag, og han ikkje vilde lyda etter henne og liggja innmed henne eller vera i hop med henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'so hende det ein gong at han kom inn i huset og skulde gjera arbeidet sitt, og det var ingen av husens folk inne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Då greip ho honom i kjolen og sagde: «Kom og ligg med meg!» Men han rømde ut og let kjolen etter seg i henderne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Då ho såg at han hadde rømt ut, og at kjolen hans var att i henderne hennar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'so ropa ho på husfolket sitt, og sagde med deim: «Sjå, her hev han drege innpå oss ein hebraisk mann, som fer og vil gantast med oss. Han kom inn til meg og vilde liggja med meg. Då ropa eg so høgt eg kunde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'og då han høyrde eg sette i og ropa, rømde han brått ut, og kjolen hans vart liggjande att hjå meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'So let ho kjolen hans liggja hjå seg til husbonden hans kom heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Då sagde ho det same med honom: «Den hebraiske tenaren,» sagde ho, «som du hev drege inn i huset åt oss, kom inn til meg og tok til å gantast med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Men då eg sette i og ropa, brårømde han ut, og kjolen hans vart liggjande att hjå meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Då no husbonden hans høyrde rødorne åt kona si, korleis ho lagde ut og sagde: «So og so for tenaren din åt mot meg,» so vart han brennande harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Og husbonden hans Josef tok honom og sette honom i fangetårnet, der dei sat dei som kongen heldt fengsla, og han vart verande der i fangetårnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Men Herren var med Josef, og vende alle hjarto til honom, og laga det so at styresmannen i fangetårnet fekk godvilje for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Og styresmannen i fangetårnet sette Josef til å sjå etter alle fangarne som var i tårnet, og alt som der skulde gjerast, det laut han gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Styresmannen i fangetårnet såg ikkje etter nokon verdeleg ting som Josef hadde under hender. For Herren var med honom; og kva han so gjorde, so lagde Herren lukka til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Ei tid etter dette hadde gjenge fyre seg, hende det at skjenkjaren og bakaren åt kongen i Egyptarland forsåg seg mot herren sin, kongen i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Og Farao vart harm på båe hirdmennerne sine, skjenkjarmeisteren og bakarmeisteren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'og sette deim faste hjå hovdingen yver livvakti, i tårnet, der Josef sat fanga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Og hovdingen yver livvakti sette Josef til å sjå til deim, og han gjekk deim til handa. Og dei vart sitjande ei tid i fangehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Ein gong hadde dei kvar sin draum, båe tvo, skjenkaren og bakaren åt kongen i Egyptarland, dei som sat fanga i tårnet; i ei og same natti hadde dei kvar sin draum, og draumarne deira hadde kvar si meining.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Og då Josef kom inn til deim um morgonen, såg han det på deim at dei var i ulag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Då tala han til hirdmennerne åt Farao, deim som sat fengsla med honom hjå husbonden hans, og spurde: «Kvi er de so sturne av dykk i dag?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, '«Me hev drøymt,» svara dei, «og det er ingen som kann tyda draumarne våre.» Då sagde Josef med deim: «Er det ikkje Gud som råder for uttydingi! Seg de meg kva de hev drøymt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'So fortalde skjenkjarmeisteren Josef draumen sin og sagde med honom: «Eg tykte so skilleg det stod eit vintre framfyre meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'og på det vintreet var det tri greiner. Og det syntest skjota knuppar, blomarne spratt, kartarne mogna til druvor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Og staupet åt Farao heldt eg i handi, og druvorne tok eg og kreista utor deim upp i staupet åt Farao, og so rette eg staupet til Farao.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Og Josef sagde med honom: «Dette er so å tyda: Dei tri greinerne, det er tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Når det lid um tri dagar, skal Farao retta upp hovudet ditt og setja deg inn att i romet ditt, og du skal retta staupet til Farao, som du fyrr var van med å gjera, den tid du var skjenkjaren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Men kom no i hug meg, når du hev fenge det godt! Kjære væne, gjer vel og tala um meg til Farao, so eg kann koma ut or dette huset!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'For eg er stolen frå Hebræarlandet, og her hev eg ikkje heller gjort noko som dei skulde setja meg i fangeholet for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Då bakarmeisteren såg at han hadde gjeve so god ei uttyding, sagde han med Josef: «Eg tykte so skilleg eg bar tri korger med kveitebrød uppå hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Og i den øvste korgi var allslags kakor, som var baka åt Farao, og fuglarne åt deim upp utor korgi på hovudet mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Og Josef tok til ords og sagde: «Dette er so å tyda: Dei tri korgerne, det er tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Når det lid um tri dagar, skal Farao retta upp hovudet ditt og hogge det av deg; so skal han hengja deg i eit tre, og fuglarne skal eta kjøtet av deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'So hende det den tridje dagen - det var årmålsdagen åt Farao - då gjorde han eit gjestebod for alle mennerne sine; og han rette upp hovudet åt skjenkjarmeisteren og bakarmeisteren imillom mennerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Han sette skjenkjarmeisteren inn att i embættet hans, so han fekk retta staupet til Farao,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'og bakarmeisteren hengde han, so som Josef hadde spått deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Men skjenkjarmeisteren kom ikkje i hug Josef; han gløymde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'So hende det ei tvo års tid etter, at Farao drøymde han stod nedmed elvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Og sjå, upp or elvi kom det sju kyr, væne å sjå til og holduge, og dei gjekk og beitte i storren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Og etter deim kom det sju andre kyr upp or elvi, stygge å sjå til og turrvorne, og dei stod på elvbakken, hjå dei fyrste kyrne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Og dei stygge og turrvorne kyrne åt upp dei sju væne og holduge kyrne. Då vakna Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'So sovna han att, og hadde ein draum til. Han tykte han såg sju aks som skaut upp på eitt strå, og var tjukke og væne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Og etter deim rann det upp sju aks som var tome og svidne av austanvinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Og dei tome aksi gløypte dei sju tjukke og fulle aksi. Då vakna Farao, og skyna at han hadde drøymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Men um morgonen hadde han slik uro i seg. So sende han bod og kalla til seg alle runemeistrar i Egyptarland, og alle dei vise menner der var. Og Farao fortalde deim draumarne sine; men det var ingen som kunde tyda deim for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Då tala skjenkjarmeisteren til Farao og sagde: «Mine eigne synder lyt eg minna um i dag:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao vart ein gong harm på tenarane sine, og sette meg fast hjå hovdingen yver livvakti, både meg og bakarmeisteren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Då hadde me kvar sin draum same natti, eg og han, og draumarne våre hadde kvar si meining.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Og det var ein hebraisk gut med oss der; han var tenar hjå hovdingen yver livvakti. Honom fortalde me det, og han tydde draumarne for oss; etter som kvar av oss hadde drøymt til, tydde han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Og so som han spådde oss, so gjekk det: eg vart sett inn att i romet mitt, og hin vart hengd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'So sende Farao bod etter Josef. Då skunda dei seg og slepte honom ut or fengslet; og han raka seg og bytte klæde, og so gjekk han fram for Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Og Farao sagde til Josef: «Eg hev havt ein draum, og det er ingen som er god til å tyda honom. Men eg hev høyrt sagt um deg, at berre du høyrer ein draum, so tyder du honom med same.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Og Josef svara Farao og sagde: «Eg råder ikkje for det. Gud vil visst gjeva eit svar som spår lukke for Farao.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'So sagde Farao til Josef: «Eg drøymde eg stod på elvbakken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Og sjå, upp or elvi det sju kyr, feite på hold og væne på skapnad, og dei beitte i storren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Og etter deim kom det upp sju andre kyr, skrinne og ovleg stygge på skapnad og turre på hold; eg hev aldri set so ljote kyr i heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Og dei skrinne og stygge kyrne åt upp dei sju fyrste, holduge kyrne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Dei sokk i skrovet deira; men det synte ikkje at dei hadde fenge deim i seg; dei var stygge å sjå til, som dei hadde vore. Då vakna eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Sidan drøymde eg at eg såg sju aks som skaut upp på eitt strå, og var fulle og væne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Og etter deim rann det upp sju aks som var turre og tome og svidne av austanvinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Og dei tome aksi gløypte dei sju gode aksi. Eg sagde det med runemeistrarne, men ingen kunde greida det for meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Då sagde Josef med Farao: «Alt det Farao hev drøymt, er ein draum. Det Gud vil gjera, hev han gjort kunnigt for Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Dei sju væne kyrne, det er sju år, og dei sju gode aksi, det er og sju år; det er ein og same draumen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Og dei sju skrinne og stygge kyrne, som kom upp etterpå hine, det er sju år, og dei sju aksi som var tome og svidne av austanvinden; det er sju uår, som skal koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Det er som eg sagde med Farao: Det Gud vil gjera, det hev han synt Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Sjå, no kjem det sju år med ovnøgd og rikdom i heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Men etter deim skal det koma sju uår, so all ovnøgdi vert gløymd i Egyptarland, og uåri skal arma ut landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Og ingen skal minnast ovnøgdi som var i landet, for den naudi som kjem etterpå; for den vert ovleg hard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Og det at draumen kom fyre Farao tvo vendor, det kjem seg av di at Gud er fastrådd på dette, og at han vil gjera det snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'No skulde Farao sjå seg ut ein vitug og vis mann, og setja honom yver Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Det skulde Farao gjera, og so skulde han setja inn futar utyver landet, som skal krevja inn femte luten av grøda i Egyptarland i dei sju ovnøgdaråri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Og dei skal samla alle slag mat i desse gode åri som kjem, og dunga upp matkorn i byarne, og taka vare på det for Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Og maten skal vera til ei berging for landet i dei sju uåri som kjem i Egyptarland, so landet ikkje skal øydast av svolt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Dei ordi tykte dei godt um, både Farao og alle mennerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Og Farao sagde med mennerne sine: «Skal tru me finn maken til honom? - ein mann som er full av Guds ande!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'So sagde Farao med Josef: «Etter di Gud hev late deg vita alt dette, so er ingen so vitug og vis som du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du skal standa fyre huset mitt, og etter ditt ord skal heile folket mitt retta seg. Berre kongsstolen vil eg hava framum deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Sjå, eg set deg yver heile Egyptarlandet,» sagde Farao med Josef.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Og Farao tok seglringen av handi si og sette på handi hans Josef, og klædde honom i kvite linklæde, og hengde eit gullekkje kring halsen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Og han let honom køyra i den vogni som var næst etter hans eigi vogn, og dei ropa framfyre honom: «Abrek!» Og han sette honom yver heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Og Farao sagde med Josef: «Eg er Farao! Ingen skal røyva hand eller fot i heile Egyptarlandet, utan at du vil det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Og Farao kalla Josef Safnat-Paneah, og gav honom Asnat til kona; ho var dotter åt Potifera, presten i On. So tok Josef til å ferdast kring i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Josef var tretti år gamall, då han stod framfor Farao, kongen i Egyptarland. Og Josef bad vel liva med Farao, og for heile Egyptarlandet igjenom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Og jordi bar inn i haugevis i dei sju ovåri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Og han samla allslags grøda av sju årsavlingar, som dei fekk i Egyptarland, og lagde upp mat i byarne. I kvar by lagde han upp grøda av åkrarne som låg ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Og Josef hauga upp korn som havsens sand, uhorveleg mykje, til dei heldt upp å telja; for det var ikkje tal på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Fyrr det fyrste uåret kom, fekk Josef tvo søner med Asnat, dotter åt Potifera, presten i On.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Og Josef kalla den fyrste Manasse - «av di,» sagde han, «Gud let meg gløyma all mi møda og heile mi ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Og den andre kalla han Efraim - «av di,» sagde han, «Gud let meg veksa i det landet som eg leid vondt i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'So leid dei til endes dei sju åri då det var slik ovnøgd i Egyptarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'og dei sju uåri tok til å koma, som Josef hadde sagt; då vart det naud og svolt i alle land, men i heile Egyptarlandet, der var brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Og heile Egyptarland svalt, og folket ropa til Farao etter brød. Då sagde Farao med alle egyptarane: «Gakk til Josef! Det han segjer til dykk, skal de gjera!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Og naudi breidde seg yver heile jordi. Men Josef let upp alle kornbuderne og selde til egyptarane; for naudi var hard i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Og frå heile verdi kom dei til Egyptarland og vilde kjøpa korn hjå Josef; for naudi var stor all verdi yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Då Jakob høyrde at det var korn i Egyptarland, sagde han med sønerne sine: «Kvi sit de og stirer på kvarandre?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Eg hev fenge spurt,» sagde han, «at dei hev korn i Egyptarland. Far no der ned og kjøp korn åt oss, so me kann halda livet og ikkje døy burt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Og brørne hans Josef tok nedigjenom, ti i talet, og vilde kjøpa korn i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Men Benjamin, rettebror åt Josef, sende Jakob ikkje av stad med brørne hans; han var rædd det kunde henda honom ei ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'So kom då Israels-sønerne og vilde kjøpa korn, millom alle dei andre som kom; for det var uår i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Men Josef var den som rådde i landet. Han var det som selde korn til all landslyden. Og brørne hans Josef kom og lagde seg å gruve for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Då Josef såg brørne sine, kjende han deim att, men lest ikkje ved vera; han tala strengt til deim og spurde: «Kvar er de frå?» «Frå Kana’ans-land,» sagde dei. «Me kjem og vil kjøpa grjon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Josef kjende att brørne sine, men dei kjende ikkje honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Og Josef laut minnast det som han hadde drøymt um deim, og sagde med deim: «De er njosnarar, de kjem og vil sjå kvar landet er lettast å taka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, '«Nei, gode herre,» sagde dei; «tenarane dine vil berre kjøpa grjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Me er alle søner åt ein mann. Me er ærlege folk: tenarane dine hev aldri vore njosnarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, '«Jau,» sagde han, «de kjem og vil sjå kvar landet er lettast å taka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Då sagde dei: «Tenarane dine er tolv brør og søner åt ein mann i Kana’ans-landet. Og den yngste av oss er no heime hjå far vår, men ein er ikkje til lenger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Då sagde Josef med deim: «Det er som eg hev sagt: De er njosnarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Men no vil eg røyna dykk: So visst som Farao liver, de slepp ikkje herifrå, fyrr yngste bror dykkar kjem hit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Ein av dykk skal fara i vegen og henta bror dykkar, og dei andre vil eg halda fengsla, so det kann røynast um det er sant, det de segjer; og er det ikkje det, so er de njosnarar, so visst som Farao liver!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'So heldt han deim alle saman fengsla i tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Og tridje dagen sagde Josef med deim: «Gjer no som eg segjer, so skal de få liva! Eg hev age for Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Er de ærlege folk, so skal ein av dykk brør vera att i fangehuset, men de andre kann fara i vegen og hava med dykk korn til livberging for deim som heime er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Og den yngste bror dykkar skal de koma hit til meg med, so ordi dykkar kann sannast, og de ikkje skal missa livet.» Og dei so gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Og dei sagde seg imillom: «Å ja, ja, kor vel me er verde dette, for det me gjorde mot bror vår! Me såg kor hjarterædd han var, då han bad so vænt for seg, og endå høyrde me ikkje på honom. Difor er me no komne i slik naud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Då tok Ruben til ords og sagde: «Var det ikkje det eg sagde dykk, at de ikkje skulde fara so stygt med guten? Men de vilde ikkje høyra. Og sjå, no kjem hemnen for blodet hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Men dei visste ikkje at Josef skyna det; for han bruka tolk, når han tala med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Og han snudde seg frå deim og gret. So kom han innåt deim att, og tala til deim, og han tok Simeon ifrå deim, og batt honom, so dei såg på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Sidan sagde Josef frå, at dei skulde fylla sekkjerne deira med korn og leggja pengarne åt kvar av deim att i sekken hans, og gjeva deim nista med på vegen. Og so vart gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'So klyvja dei kornet på asni sine, og for sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Men då ein av deim løyste upp klyvi si og vilde gjeva asnet for på kvilestaden, fekk han sjå pengarne sine: dei låg ovanpå i sekken hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Og han sagde med brørne sine: «Pengarne mine hev kome att! Sjå, her ligg dei i sekken min.» Då vart dei reint ille ved; dei såg på kvarandre og skalv, og sagde: «Kva er det Gud hev gjort mot oss her?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'So kom dei heim til Jakob, far sin, i Kana’ans-landet, og dei fortalde honom alt det som hadde hendt deim, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '«Mannen som råder der i landet, tala strengt til oss, og tok oss for folk som vilde njosna ut landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Då sagde me med honom: «Me er ærlege folk; me hev aldri vore njosnarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Me er tolv brør, alle sønerne åt far vår. Ein av oss er ikkje til lenger, og den yngste er endå heime hjå far vår i Kana’ans-landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Og mannen som råder der i landet, sagde med oss: «Dette vil eg hava til merke på at de er ærlege folk: Ein av dykk brør skal vera att hjå meg, og de andre kann taka med dykk det de treng til livberging for deim som heime er, og fara i vegen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'og so lyt de koma til meg att med yngste bror dykkar, so eg fær sjå at de ikkje er njosnarar, men ærlege folk. Då skal de få att bror dykkar, og de kann fara fritt kringum i landet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Då dei so tømde sekkjerne sine, då fann kvar sitt pengeknyte i sekken sin; dei såg det både dei og far deira, at det var deira eigne pengeknyte, og vart fælne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Og Jakob, far deira, sagde med deim: «De gjer meg reint barnlaus; Josef er burte, og Simeon er burte, og no vil de taka Benjamin og ifrå meg; det kjem yver meg, alt dette.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Då sagde Ruben med far sin: «Båe sønerne mine kann du drepa, kjem eg ikkje heim til deg att med honom! Gjev honom berre i mine hender! Eg skal hava honom heim att til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Men han svara: «Son min skal ikkje fara med dykk der ned. For bror hans er burte, og han er att åleine, og hender det honom nokor ulukka på den vegen de ferdast etter, so kjem de til å senda dei grå håri mine med sorg ned i nåheimen.» Men svolten var hard i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Og då det traut det kornet dei hadde havt heim frå Egyptarland, sagde far deira med deim: «Far i vegen att og kjøp oss noko grjon!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Då sagde Juda med honom: «Denne mannen lyste so strenge ord og sagde: «De skal ikkje koma for augo mine, utan yngste bror dykkar er med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Vil du no lata bror vår få vera med oss, so skal me fara ned og kjøpa grjon åt deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Men sender du honom ikkje med, so vil me ikkje fara. For mannen sagde: «De skal ikkje koma for augo mine, utan bror dykkar er med.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Då sagde Israel: «Kvi gjorde de meg so ille imot og sagde det med mannen at de hadde endå ein bror?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Og dei svara: «Mannen spurde oss ut både um oss og ætti vår, og sagde: «Liver far dykkar endå? Hev de nokon bror?» So svara me, som han spurde til. Kor kunde då me tenkja at han skulde segja: «Kom hit med bror dykkar!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Og Juda sagde med Israel, far sin: «Send du sveinen med meg, so vil me oss reiduge og fara, so me kann halda livet og ikkje døy burt, både me og du og småborni våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Eg skal svara for honom. Av meg kann du krevja honom att. Kjem eg ikkje heim til deg att med honom og set honom framfyre deg, so skal eg bera skuldi for det all min dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'For hadde me ikkje drygt so lenge, so kunde me no vore heim att tvo vendor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Då sagde Israel, far deira, med deim: «Er det ikkje onnor råd, so gjer som eg segjer: Tak med dykk i sekkjerne dykkar av alt det gjævaste som finst i landet, noko balsam og noko honning, kryddor og rosekvåda, pistacie-neter og mandlar! Det skal vera ei gåva til mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Og tak ein gong til so mange pengar med dykk! For dei pengarne som kom att og låg ovanpå i sekkjerne dykkar, fær de hava med attende; kann henda det berre var eit mistak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Tak so bror dykkar med, og gjer dykk reiduge, og far attende til mannen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Og Gud den Allvelduge late dykk møta godvilje hjå mannen, so han sender Benjamin og den andre bror dykkar med dykk heim att. Og eg - skal eg vera barnlaus, so fær eg vera barnlaus!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'So tok dei gåva, og ein gong til so mange pengar tok dei med seg, og so Benjamin. Og dei gav seg på vegen, og for ned til Egyptarland, og gjekk fram for Josef.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Då Josef såg at Benjamin var med deim, sagde han med den som stod fyre huset hans: «Bed desse mennerne inn, og slagta eit naut og laga det til; for dei skal eta til middags med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Og mannen gjorde som Josef sagde, og bad deim inn i huset åt Josef.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Men då dei skulde inn i huset åt Josef, vart dei rædde, og sagde: «Det er nok for dei pengarne skuld som låg att i sekkjerne våre fyrre gongen, at me skal her inn. Dei kjem til å velta seg inn på oss, og kasta seg yver oss, og taka oss til trælar, med asni våre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'So gjekk dei burt til mannen som stod fyre huset hans Josef, og tala til honom i husdøri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'og sagde: «Høyr her, gode herre! Du veit me hev vore her ein gong fyrr og kjøpt grjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Men då me kom til kvilestaden, og løyste upp klyvjarne våre, då fann kvar sine pengar ovanpå i sekken sin; det var våre eigne pengar, med si fulle vegt, og no hev me deim med oss hit att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Og andre pengar hev me og med oss, til å kjøpa grjon for. Me veit ikkje kven som hev lagt pengarne i sekkjerne våre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Då sagde han: «Ver de hugheile! Hav ingen otte på dykk! Dykkar Gud og Gud åt far dykkar hev lagt ei gåva til dykk i sekkjerne. Pengarne dykkar hev eg fenge.» So henta han Simeon ut til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Sidan fylgde mannen deim inn i huset hans Josef, og gav deim vatn, so dei fekk två føterne sine, og gav deim for til asni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'So lagde dei gåvorne til reide, til Josef skulde koma heim til middags; for dei hadde høyrt at dei skulde eta der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Då so Josef kom heim, bar dei inn til honom gåvorne som dei hadde med seg, og lagde seg å gruve for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Og han spurde korleis dei livde, og sagde: «Stend det vel til med den gamle far dykkar, som de tala um? Liver han endå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, '«Ja,» svara dei, «det stend vel til med far vår, tenaren din. Han liver endå.» Og dei bøygde seg og kasta seg å gruve for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Då han fekk auga på Benjamin, bror sin, son åt hans eigi mor, sagde han: «Er dette den yngste bror dykkar, som de tala til meg um? - Gud signe deg, guten min!» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Og Josef skunda seg burt. For hjarta hans kløktest, då han såg bror sin, so han laut få gråta. Og han gjekk inn i koven og gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'So tvo han seg i andlitet, og gjekk ut att, og han gjorde seg hard, og sagde: «Set maten fram!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Då sette dei fram, for honom i ser, og for deim i ser, og for egyptarane i ser, deim som åt hjå honom; for egyptarane torer ikkje eta i lag med hebræarane; dei held det for å vare ufjelgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Dei vart sessa midt fyre honom etter alderen, frå den eldste til den yngste, og dei såg på kvarandre og undrast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Og det vart sendt um til deim av dei retterne som han sjølv åt av, og Benjamin fekk fem gonger so mykje som dei andre. Og dei drakk med honom, og vart fjåge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Sidan sagde han med den som stod fyre huset hans: «Fyll sekkjerne åt desse mennerne med grjon, so mykje som dei kann føra, og legg pengarne åt kvar av deim ovanpå i sekken hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Og staupet mitt, sylvstaupet, det skal du leggja øvst i sekken åt den yngste av deim, i hop med kornpengarne hans.» Og han gjorde som Josef sagde honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Um morgonen, med same det ljosna, let dei mennerne fara av stad med asni sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Dei var ikkje langt utum byen komne, då Josef sagde med den som stod fyre huset hans: «Upp, og set etter mennerne, og fyrst du når deim att, so seg ned deim: «Kvi løner de godt med ilt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Er ikkje dette det staupet som husbonden min drikk av, og som han plar spå i? Dette var ille gjort av dykk!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Og han tok deim att, og sagde dette med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Då sagde dei med honom: «Kvi talar du soleis, herre? Gud frie tenarane dine frå å gjera slikte ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Sjå no, dei pengarne som me fann øvst i sekkjerne våre, deim hadde me med hit til deg att frå Kana’ans-landet. Kvi skulde me då stela sylv eller gull utor huset åt husbonden din?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Den av tenarane dine som det vert funne hjå, han skal døy, og me andre skal vera trælarne dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, '«Ja,» sagde han, «lat det vera so som de segjer! Den som det vert funne hjå, skal vera trælen min, men dei andre skal vera saklause.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'So skunda dei seg, og lyfte klyvjarne ned på marki, og løyste upp kvar si klyv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Og han rannsaka; han tok til hjå den eldste, og enda hjå den yngste. Og staupet vart funne i sekken hans Benjamin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Då reiv dei sund klædi sine, og klyvja på asni att, og for attende til byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Og Juda og brørne hans gjekk inn til huset åt Josef, for han var der endå, og dei kasta seg å gruve for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Og Josef sagde med deim: «Kva er det de hev gjort no? Veit de ikkje at ein mann som eg kann finna ut det som er dult?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Då sagde Juda: «Kva skal me segja til deg, herre? Korleis skal me taka til ords? Kva skal me orsaka oss med? Gud hev funne brotet åt tenarane dine. Sjå, me vil vera trælarne dine, både me og han som staupet vart funne hjå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Men han sagde: «Gud frie meg frå å gjera slikt! Den som staupet vart funnen hjå, han skal vera trælen min. Men de andre kann fara i fred heim til far dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Då steig Juda fram for honom og sagde: «Høyr meg, herre! Lat tenaren din få tala eit ord til deg, herre, og lat ikkje vreiden din loga upp mot tenaren din! For du er som Farao sjølv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Du spurde oss, herre, og sagde: «Hev de nokon far eller bror?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Då sagde me til deg: «Ja, me hev ein gamall far, og han hev ein liten son, som han fekk på sine gamle dagar, bror åt denne sveinen er burte, og han er att åleine etter mor si, og far hans held honom so kjær.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Og du sagde til oss: «Kom hit til meg med honom, so eg fær sjå honom med mine eigne augo!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Då sagde me til deg: «Sveinen må ikkje skiljast frå far sin; skilst han ifrå honom, so døyr faren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Og du sagde til oss: «Kjem ikkje yngste bror dykkar hit med dykk, so skal de ikkje oftare koma for augo mine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Då me so kom heim att til far vår, tenaren din, fortalde me honom kva du hadde sagt, herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Og far vår sagde: «Far i vegen att og kjøp noko grjon åt oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Då sagde me: «Me torer ikkje koma der att. Men er yngste bror vår med oss, so skal me fara der ned. For me fær ikkje koma mannen for augo utan yngste bror vår er med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Og far vår sagde med oss: «De veit at eg fekk tvo søner med kona mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Og den eine vart burte for meg, og eg sagde: «Han er visst ihelriven;» for eg hev aldri set honom sidan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Tek de no denne og ifrå meg, og vert han fyre ei uheppa, so kjem de til å senda dei grå håri mine med sut og harm ned i nåheimen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Skal eg no koma heim til far min, og me hev ikkje med oss sveinen, som hjarta hans heng so fast ved,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'då vert det dauden hans, med same han ser at sveinen ikkje er med, og me lyt senda dei grå håri åt far vår med sut og sorg ned i nåheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'For eg tok på meg å svara for sveinen hjå far min, og sagde: «Kjem eg ikkje heim til deg att med honom, so skal eg vera saka i det for far min alle mine dagar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Lat difor meg få vera att i staden for sveinen, og vera trælen din, og lat sveinen få fara heim att med brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'For korleis kunde eg koma heim att til far min, når sveinen ikkje var med? Eg tolde ikkje sjå på den sorg som då kom yver far min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Då kunde ikkje Josef dylja tårorne lenger for alle deim som stod ikring honom. Han ropa: «Lat alle ganga ut ifrå meg!» Og det var ingen inne, då Josef opendaga seg for brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Og han brast i og gret so høgt at egyptarane høyrde det, og dei høyrde det i huset åt Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Og Josef sagde med brørne sine: «Eg er Josef. Liver far min endå?» Men brørne hans kunde ikkje svara; dei stod der som dei var klumsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Då sagde Josef med brørne sine: «Kjære væne, kom hit til meg!» So gjekk dei burt til honom. Då sagde han: «Eg er Josef, bror dykkar, som de selde til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Men no skal de ikkje syta eller harmast, for di de selde meg hit! Til livberging for mange hev Gud sendt meg fyre dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'For no er det andre året her er svolt i landet, og endå kjem her fem år til som det korkje vert pløgt eller hausta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Men Gud sende meg fyre, av di han vilde leiva ætt etter dykk på jordi, og av di han vilde berga liv for dykk, so det vart ei stor frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'So er det då ikkje de, som hev sendt meg hit, men Gud, og han hev gjort meg til far for Farao og til herre yver alt hans hus og til styrar i heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Skunda dykk og far heim til far min, og seg med honom: «So segjer Josef, son din: «Gud hev sett meg til herre yver heile Egyptarland. Kom no ned til meg! Dryg ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du skal få bu i Gosenlandet og vera innmed meg, både du og borni og barneborni dine, med bufeet ditt, både smått og stort, og med alt det du hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Og eg skal syta for deg der - for endå kjem det fem uår - so det ikkje skal vanta deg noko, korkje deg eller huslyden din eller nokon av dine.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'No ser de det med dykkar eigne augo, og Benjamin, bror min, ser det og, at det er eg som talar til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Ber då bod til far min um all mi æra og magt i Egyptarland og um alt de hev set, og skunda dykk og kom hit att med far min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'So lagde han armarne um halsen på Benjamin, bror sin, og gret, og Benjamin gret og innmed barmen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Og han kysste alle brørne sine og gret, medan han heldt deim i fanget. Og sidan rødde brørne hans med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Og det spurdest i huset åt Farao, at brørne hans Josef var komne, og Farao og mennerne hans vart fegne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Og Farao sagde med Josef: «Seg du med brørne dine: «So skal de gjera: de skal klyvja på dyri dykkar og fara, til de kjem heim til Kana’ans-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Då skal de taka far dykkar og huslydarne dykkar og koma hit til meg, so skal eg gjeva dykk det beste i Egyptarlandet, og de skal få eta av landsens feita.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Seg du deim frå meg: «So skal de gjera: de skal taka med dykk vogner frå Egyptarlandet til borni og konorne dykkar og henta far dykkar og koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Og de skal ikkje kvida dykk, um de må fara ifrå husbunaden dykkar; for det beste i heile Egyptarland skal de få.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Og Israels-sønerne gjorde so. Og Josef gav deim vogner, som Farao hadde sagt, og gav deim nista med på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Og han gav deim alle kvar sin klædnad, men Benjamin gav han tri hundrad sylvdalar og fem klædnader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Og sameleis sende han far sin ti asen, som bar av alt det beste som fanst i Egyptarland, og ti asenfyljor, som bar korn og brød og mat til far hans på ferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'So bad han farvel med brørne sine, og dei for av stad, og han sagde med deim: «De må ikkje verta usams på vegen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'So tok dei ut frå Egyptarland, og kom heim att til Jakob, far sin, i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Og dei bar fram bodet til honom og sagde: «Josef er endå i live, og han er jamvel styrar yver heile Egyptarland.» Men han var like kald i hjarta; for han trudde deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'So sagde dei honom alt det Josef hadde sagt med deim, og han såg vognerne som Josef hadde sendt til å henta honom i. Då kvikna far deira i hugen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, '«Å du store syn!» sagde Israel, «Josef, son min, er endå i live! Eg vil av og sjå honom, fyrr eg døyr.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Og Israel tok ut med alt det han hadde, og då han kom til Be’erseba, ofra han slagtoffer til honom som var Gud åt Isak, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Då tala Gud til Israel i syner um natti, og sagde: «Jakob, Jakob!» Og han svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Då sagde han: «Eg er Gud, Gud åt far din. Ver ikkje rædd å fara ned til Egyptarland; for der vil eg gjera deg til eit stort folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Eg skal fara med deg ned til Egyptarland, og eg skal fylgja deg upp att og; det kann du lita på! Og Josef skal leggja att augo dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'So tok Jakob ut frå Be’erseba, og Israels-sønerne køyrde Jakob, far sin, og borni og konorne sine i dei vognerne som Farao hadde sendt til å henta honom i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Og dei tok med seg bufeet sitt og godset sitt, som dei hadde lagt seg til i Kana’ans-land. So kom dei til Egyptarland, Jakob og all hans ætt med honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Sønerne og sonesønerne sine, døtterne og sonedøtterne sine, heile si ætt, hadde han med seg til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Og dette er namni på Israels-sønerne som kom til Egyptarland, Jakob og sønerne hans: Ruben, eldste son åt Jakob,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'og sønerne åt Ruben: Hanok og Pallu og Hesron og Karmi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'og sønerne åt Simeon: Jemuel og Jamin og Ohad og Jakin og Sohar og Saul, son åt kananitarkvinna;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'og sønerne åt Levi: Gerson og Kahat og Merari;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'og sønerne åt Juda: Er og Onan og Sela og Peres og Zerah; men Er og Onan døydde i Kana’ans-land - og sønerne åt Peres: Hesron og Hamul;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'og sønerne åt Issakar: Tola og Puva og Job og Simron;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'og sønerne åt Sebulon: Sered og Elon og Jahle’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Dette var sønerne åt Lea; ho fekk deim med Jakob i Mesopotamia, og so Dina, dotter hans. Alle desse sønerne og døtterne hans var tri og tretti i tallet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Og sønerne åt Gad: Sifjon og Haggi, Suni og Esbon, Eri og Arodi og Areli;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Og sønerne åt Asser: Jimna og Jisva og Jisvi og Bria, og so Serah, syster deira; og sønerne åt Bria: Heber og Malkiel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Dette var sønerne åt Zilpa, som Laban gav Lea, dotter si; ho fekk deim med Jakob, dei var sekstan i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Og sønerne åt Rakel, kona hans Jakob: Josef og Benjamin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Og Josef fekk born i Egyptarland; han fekk deim med Asnat, dotter åt Potifera, presten i On: dei heitte Manasse og Efraim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Og sønerne åt Benjamin: Bela og Beker og Asbel, Gera og Na’aman, Ehi og Ros, Muppim og Huppim og Ard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Dette var dei borni som Jakob fekk med Rakel; dei var i alt fjortan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Og sønerne åt Dan: Husim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'og sønerne åt Naftali: Jahse’el og Guni og Jeser og Sillem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Dette var sønerne åt Bilha, som Laban gav Rakel, dotter si; ho fekk deim med Jakob, dei var i alt sju.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alle dei som kom med Jakob til Egyptarland, og som var ætta ifrå honom, umfram konorne åt sønerne hans, var alt i alt seks og seksti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Og sønerne åt Josef, som han fekk i Egyptarland, var tvo. Alle som kom til Egyptarland av Jakobs-ætti, var sytti i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Og han sende Juda fyre seg til Josef, og bad at han vilde syna deim vegen til Gosen. Og so kom dei til Gosenlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Og Josef let setja fyre vogni si, og for upp til Gosen, til møtes med Israel, far sin; og med same han fekk sjå honom, kasta han seg um halsen på honom, og gret lenge, med armarne um halsen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Då sagde Israel med Josef: «No vil eg gjerne døy, sidan eg hev set deg i andlitet, og veit at du endå er i live.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Og Josef sagde med brørne sine og med farsfolket sitt: «No vil eg upp til Farao og bera fram bod um dette og segja: «Brørne mine og farsfolket mitt, som var i Kana’ans-land, hev kome hit til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Og desse mennerne er sauehyrdingar; dei hev stødt drive med å ala fe, og sauerne og nauti sine og alt det dei eig, hev dei havt med seg hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Når so Farao kallar dykk til seg og spør: «Kva hev de til liveveg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'so skal de svara: «Fehyrdingar hev tenarane dine vore alt ifrå ungdomen og til no, både me og federne våre» - so de kann få bu i Gosenlandet; for egyptarane hev ein stygg til alle sauehyrdingar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'So kom Josef med bod um dette til Farao og sagde: «Far min og brørne mine hev kome hit frå Kana’ans-land med bufeet sitt, både smått og stort, og med alt det dei eig; og no er dei i Gosenland.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Og av alle brørne sine tok han ut fem mann, og leidde deim fram for Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Og Farao spurde brørne hans: «Kva hev de til liveveg?» Då sagde dei med Farao: «Tenarane dine er fehyrdingar, og det same var federne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Me vilde gjerne halda til her i landet,» sagde dei til Farao; «for det finst ikkje beite for buskapen vår, av di det er eit svært uår i Kana’ans-land. Lat difor tenarane dine få bu i Gosenlandet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Då sagde Farao med Josef: «Far din og brørne dine hev kome hit til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Du hev heile Egyptarland fyre deg! Lat far din og brørne dine få bu i den beste luten av landet! Dei kann få bu i Gosenlandet. Og veit du um at det er dugande karar imillom deim, so set deim til rådsmenner yver bufeet mitt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Og Josef henta Jakob, far sin, og leidde honom fram for Farao. Og Jakob helsa Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Og Farao spurde Jakob: «Kor mange er dine livedagar og år?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Då sagde Jakob med Farao: «Dei dagar og år eg hev ferdast på jordi, er hundrad og tretti år. Få og låke hev dei vore, mine livedagar og år, og ikkje hev dei nått so høgt som livedagarne og åri åt federne mine i den tidi dei ferdast på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Og Jakob velsigna Farao, og so bad han vel liva med Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Og Josef let far sin og brørne sine få seg bustader, og gav deim jord i Egyptarland, i den beste bygdi i landet, Ramseslandet, so som Farao hadde sagt honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Og Josef sytte for brød åt far sin og brørne sine og alt farsfolket sitt, og gav deim etter som dei hadde mange born til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Og det fanst ikkje brød på heile jordi. For naudi var ovleg stor, og både Egyptarlandet og Kana’ans-landet var reint avmagta av svolten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Og Josef samla alle dei pengar som fanst i Egyptarland og i Kana’ans-land; han fekk deim for kornet han selde. Og Josef gøymde pengarne i huset åt Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'So traut pengarne både i Egyptarland og i Kana’ans-land. Då kom alle egyptarane til Josef og sagde: «Gjev oss brød! Skal me døy for augo dine, berre av di me ikkje hev fleire pengar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Og Josef sagde: «Kom med bufeet dykkar, so skal eg gjeva dykk brød for bufeet, um de ikkje hev fleire pengar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'So kom dei til Josef med bufeet sitt, og Josef gav deim brød for hestarne og for sauerne og nauti som dei hadde, og for asni; og han heldt deim med brød det året for alt bufeet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'So leid det året, og året etter kom dei til honom og sagde med honom: «Me vil ikkje dylja for deg, herre, at pengarne hev trote, og buskapen vår hev du fenge. Me hev ikkje anna att å bjoda deg enn kroppen og jordi vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Kvi skal me tynast for augo dine, både me og jordi vår? Kjøp du oss og gardarne våre for brød, so skal me med gardarne våre vera trælar under Farao. Lat oss berre få såkorn, so me kann halda livet og ikkje døy burt, og so gardarne ikkje skal øydast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'So kjøpte Josef all jord i Egyptarland til Farao; for egyptarane selde mannjamt jordvegarne sine, av di svolten tvinga deim; og Farao vart eigande all jord i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Og han let folket byta bustad grend for grend i heile Egyptarland, frå ende til annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Berre prestegardarne kjøpte han ikkje. For prestarne hadde ei viss innkoma av Farao og livde av det som Farao hadde etla deim. Difor selde dei ikkje gardarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Og Josef sagde til folket: «Sjå no hev eg kjøpt både dykk og jordi dykkar til Farao. Her hev de såkorn: så no åkrarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Men av det de haustar, skal de gjeva femteparten til Farao, og dei fire partarne skal de hava til å så åkrarne med, og til mat for dykk sjølve og deim som er i husi hjå dykk, og til mat for borni dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Då sagde dei: «Du hev berga livet vårt. Vil berre du vera god mot oss, so vil me gjerne vera trælar under Farao.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'So sette Josef ei lov, som er gjeldande den dag i dag, at all jord i Egyptarland skulde svara femteparten av avlen i skatt til Farao. Berre prestejordi kom ikkje under Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Israel vart buande i Egyptarland, i Gosenlandet, og dei fekk seg eigedomar der, og voks og auka seg uhorveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Og Jakob livde syttan år i Egyptarland, og dagarne hans Jakob, liveåri hans, vart hundrad og sju og fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Då det leid med Israel, og han venta på enden, sende han bod etter Josef, son sin, og sagde med honom: «Kjære deg, held du aldri so lite av meg, so legg handi di i fanget mitt, og lova meg at du vil vera snild og trugen med meg og ikkje jorda meg i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Lat meg få kvila hjå federne mine! Før meg burt frå Egyptarland, og jorda meg i gravi deira!» Og han svara: «Eg skal gjera som du segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Då sagde Israel: «Gjer eiden på det!» So gjorde han eiden på det. Og Israel lutte seg ned yver hovudgjerdi og bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Ei tid etter dette hadde hendt, kom dei og sagde med Josef: «Far din er sjuk.» Då tok han med seg båe sønerne sine, Manasse og Efraim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Og det kom ein med bod um dette til Jakob og sagde: «Josef, son din, kjem til deg!» Då gjorde Israel seg sterk, og reiste seg upp i sengi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Og Jakob sagde med Josef: «Gud den Allvelduge synte seg for meg i Luz i Kana’ans-land og velsigna meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'og sagde til meg: «Sjå, eg vil lata deg veksa og aukast og gjera deg til ein flokk med folkeslag; og eg vil gjeva ætti di etter deg dette landet til eiga i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Dei tvo sønerne dine som du fekk i Egyptarlandet, fyrr eg kom hit til deg, dei skal no vera mine: Efraim og Manasse skal høyra meg til, liksom Ruben og Simeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Men dei borni som du sidan hev fenge, dei skal vera dine eigne; etter brørne sine skal dei heita i det landet dei kjem til å erva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'For då eg kom frå Mesopotamia, døydde Rakel frå meg på vegen, i Kana’ans-land, då me hadde att so mykje som eit augneleite til Efrat. Og eg jorda henne der, innmed vegen til Efrat, det som no heiter Betlehem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Då Jakob såg sønerne hans Josef, spurde han: «Kven er det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Og Josef sagde med far sin: «Det er sønerne mine, som Gud hev gjeve meg her.» Då sagde Jakob: «Kjære væne, kom hit til meg med deim, so eg kann få velsigna deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Men augo hans Israel var dimme av alder; han skilde ikkje klårt. So leidde Josef deim burt til honom, og han kysste deim og tok deim i fanget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Og Israel sagde med Josef: «Eg tenkte aldri eg skulde få sjå deg meir, og sjå no hev Gud endå til late meg få sjå borni dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'So tok Josef deim ned av fanget hans, og bøygde seg nedåt jordi for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Sidan tok Josef deim båe, Efraim i høgre handi, midt for vinstre handi hans Israel, og Manasse i vinstre handi, midt for høgre handi hans Jakob, og leidde deim innåt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Og Jakob rette ut høgre handi, og lagde henne på hovudet hans Efraim, endå han var den yngste av deim, og vinstre handi lagde han på hovudet hans Manasse. Med vilje lagde han henderne so; for Manasse var eldst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Og han velsigna Josef og sagde: «Den Gud som federne mine, Abraham og Isak, hadde for augo medan dei ferdast på jordi, den Gud som vara meg frå di eg vart til og til den dag i dag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'den engelen som løyste meg ut frå alt vondt, han velsigne sveinarne, so dei kann pryda namnet mitt og namnet åt federne mine, Abraham og Isak, og aukast til ei uhorveleg mengd på jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Då Josef såg at far hans hadde lagt høgre handi på hovudet hans Efraim, mislika han det; han fata handi åt far sin og vilde flytja henne frå hovudet hans Efraim burt på hovudet hans Manasse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'og han sagde med far sin: «Ikkje so, far! For denne er eldst; legg høgre handi på hans hovud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Men det vilde ikkje far hans, og han sagde: «Eg veit det, son min, eg veit det. Han og skal verta eit folk, han og skal verta stor, men bror hans som yngre er, han skal verta større; hans ætt skal verta ein fjølde med tjoder.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'So velsigna han deim same dagen, og sagde: «Ved deg skal Israel velsigna og segja so: «Gud gjere deg som Efraim og som Manasse!»» - han nemnde Efraim fyre Manasse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Sidan sagde Israel med Josef: «No lyt eg døy, men Gud skal vera med dykk og fylgja dykk attende til landet åt federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Og eg gjev deg ein bergås framum brørne dine; den tok eg frå amoriten med sverdet og bogen min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Og Jakob kalla kring seg sønerne sine og sagde: «Samla dykk saman, so skal eg varsla korleis det skal ganga dykk langt fram i tiderne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kom i hop og høyr, de søner åt Jakob, kom og høyr på Israel, dykkar far!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, min eldste er du, blom av mi magt og min manndom, høgst i vyrdnad og størst i velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Sjodande vilt som vatnet, dkal du ingen fyremun få; for i kvila åt far din du for! Kor vanærlegt! Han låg i mi lega.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Sambrøder er Simeon og Levi, valdsvåpen er deira verja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Søk ei deira samråd, mi sål, sky deira sellskap, mitt hjarta! For i harm slo dei menner i hel, og sjølvvilje skamskar dei uksar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Forbanna ein ofse so strid, ei illska som deira so arg! Eg skal sprengja deim sund kring i Jakob, eg skal spreida deim utyver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, deg lovar lydt dine brøder, handi di fatar din fiend i nakken, søkern’ åt far din fell deg til fota.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Ein løveunge er Juda! Frå herjing kjem sonen min heim: Som ei løvemor legg han seg ned, kven vågar av kvildi han vekkja?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ikkje skal kongespir kverva frå Juda ell’ styrarstaven ifrå han stol, fyrr Fredsdrotten kjem, han som folki mun fylgja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'I vingarden bind han sin gangar, sin fole i soldruvegrein; i vin sin klædnad han vaskar, i druveblod tvær han sin kjol’,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'med augo døkke av vin, med tenner kvite av mjølk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon utmed sjøstrandi bur, utmed strandi, der skutorne lender. Og Sidon hev han med sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issakar, det sterkbygde asnet, på kvii ligg han og kviler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Og han tykte kvildi var god, og at landet var fagert og fint, so bøygde han rygg under byrdi, og vart slik ein trugen træl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan, han skal døma sitt folk som dei andre Israels ætter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan verte ein hoggorm på vegen, ein eiterorm innmed stigen, som hesten i hælarne høgg, so ridaren ryk på rygg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'På hjelpi di biar eg, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'På Gad mun ransmenner renna, men han renner etter deim radt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Feit er føda hans Asser, forkunnmat sender han kongar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali er ei spelande hind, og ordi hans leikar so linne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Josef er eit aldetre ungt, eit aldetre ungt innmed kjelda; yver muren skyt greinerne upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Med pileskot dei han eggjar og søkjer, dei skyttararn’ mange;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Men han stend med sin boge so stødt, og røyver armarne raust: Hjelp fær han hjå kjempa åt Jakob, der! - hjå hyrdingen, Israels berg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Hjå Gud åt far din, han vare deg! Hjå den Velduge, han velsigne deg med velsigning or himmelen høge, med velsigning or djupet som ligg under jordi, med velsigning i brjost og i liv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Far din’s velsigning rakk yver dei eld’-gamle ovgilde fjelli, til ævordoms herlege høgder: På Josefs hovud ho kome, ho kome på kruna åt han, som er hovdingen for sine brøder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin er ein ulv som riv sund; um morgonen et han upp ranet, til kvelds han skifter ut herfang.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Dette var alle Israels-ætterne, tolv i talet, og soleis var det far deira tala til deim: Han velsigna deim, og kvar av deim fekk si eigi velsigning, som høvde åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Og han bad deim og sagde til deim: «No gjeng eg til folket mitt! Jorda meg då hjå federne mine, i den helleren som er på gjordet åt Efron, hetiten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'i den helleren som er på Makpelagjordet, austanfor Mamre i Kana’ans-landet, det gjordet som Abraham kjøpte av Efron, hetiten, til eigande gravstad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Der jorda dei Abraham og Sara, kona hans, og der jorda dei Isak og Rebekka, kona hans, og der jorda eg Lea,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'på det gjordet og i den helleren der, som var kjøpt av Hets-sønerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Då Jakob var ferdig med dei fyresegnerne han hadde å gjeva sønerne sine, drog han føterne upp i sengi. Og han sålast og kom til federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Og Josef lutte seg ned yver andlitet åt far sin, og gret uppyver honom og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Og Josef bad lækjarane som han hadde i si tenesta, at dei skulde salva liket åt far hans. So salva dei liket åt Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Og det gjekk fyrti dagar med til det; for so lang tid tek det å salva eit lik. Og egyptarane gret yver honom i sytti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Då syrgjedagarne etter honom var utlidne, tala Josef til hirdi åt Farao og sagde: «Hev de aldri so lite godvilje for meg, so gjer vel og ber fram desse ordi mine til Farao og seg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, '«Far min tok ein eid av meg og sagde: «No lyt eg døy! I grefti mi, som eg let grava åt meg i Kana’ans-landet, der skal du jorda meg!» Lat meg difor fara upp og jorda far min og so koma hit att!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Og Farao sagde: «Far du upp, og jorda far din, som du hev lova honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'So for Josef upp og skulde jorda far sin, og med honom for alle mennerne åt Farao, dei høgste i hirdi hans og alle dei øvste i Egyptarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'og heile huset hans Josef, og brørne hans og husfolket åt far hans. Berre småborni sine og sauerne og nauti sine let dei vera att i Gosenlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Og det fylgde honom både vogner og hestfolk, so det vart ei drusteleg ferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Då dei kom til Goren-Ha’atad, som er på hi sida åt Jordan, heldt dei ei stor og ovende vyrdeleg syrgjehøgtid, og han gjorde likferd etter far sin i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Og då kananitarne, som budde der i landet, såg likferdi i Goren-Ha’atad, sagde dei: «Det er ei drusteleg likferd egyptarane held der!» Difor kallar dei den staden Egyptarvollen. Han er på hi sida åt Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'So gjorde sønerne hans so med honom som han hadde sagt deim fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Og dei førde honom til Kana’ans-landet, og jorda honom i helleren på Makpelagjordet, det gjordet som Abraham hadde kjøpt av Hets-sønerne til eigande gravstad, austanfor Mamre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Og då Josef hadde jorda far sin, for han attende til Egyptarland, både han og brørne hans og alle dei som hadde vore med honom upp og jorda far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Då brørne åt Josef såg at far deira var burte, sagde dei: «Berre ikkje Josef kjem til å sitja etter oss gjera oss like for alt det vonde me gjorde mot honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'So sende dei bod til Josef og sagde: «Far din bad oss, fyrr han døydde, at me skulde bera fram dette bodet til deg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '«So skal de segja med Josef,» sagde han: «Å kjære, gode deg, gløym det brotet og den syndi brørne dine gjorde, då dei for so stygt med deg!» So gløym no brotet vårt; me tener då og same Gud som far din!» Og Josef gret, då dei tala so til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'So kom brørne hans sjølve og kasta seg å gruve for honom og sagde: «Sjå her kjem me og vil vera tenarane dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Då sagde Josef: «Ver ikkje rædde! Er då eg i staden åt Guds?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'De tenkte å gjera meg vondt, men Gud tenkte det til det gode, av di han vilde gjera som han no hev gjort, og berga livet åt mykje folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'So ver no ikkje rædde! Eg skal syta for dykk og for borni dykkar.» Og han hugga deim og tala blidt til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Josef vart buande i Egyptarland, både han og farsfolket hans. Og Josef livde hundrad og ti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Og Josef fekk sjå barneborn åt Efraim, og borni åt Makir, son hans Manasse, fekk han og taka i fanget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Og Josef sagde med brørne sine: «No lyt eg døy. Men Gud skal lydast til dykk og fylgja dykk upp or dette landet til det landet som han hev lova Abraham og Isak og Jakob.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Og Josef tok ein eid av Israels-sønerne, og sagde: «Når Gud kjem og hentar dykk, då skal de taka beini mine med her ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Og Josef døydde, då han var hundrad og ti år gamall, og dei salva liket hans, og lagde det i kista i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'No skal de få høyra namni på Israels-sønerne som kom til Egyptarland; med Jakob kom dei, kvar med sin huslyd:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben og Simeon og Levi og Juda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issakar og Sebulon og Benjamin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Naftali, Gad og Asser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Med alle i hop var det sytti mann som var ætta frå Jakob; Josef han var no alt i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Og Josef døydde, og alle brørne hans, og heile den ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Men Israels-folket muna og voks og auka og vart uhorveleg mannsterke, so dei fyllte heile landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Då kom det ein ny konge i Egyptarland, som ikkje visste noko um Josef.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Og han sagde med folki sine: «Sjå, Israels-lyden er større og sterkare enn me.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Lat oss no fara klokt fram, so dei ikkje skal aukast so mykje! For kjem det ufred, so kunde dei gjerne slå seg i hop med uvenerne våre, og strida mot oss, og fara or landet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'So sette dei futar yver deim, som skulde plåga deim med tungarbeid, og dei laut byggja tvo byar med varehus for Farao; det var Pitom og Ramses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Men di meir dei plåga deim, di meir auka dei, og di meir breidde dei seg ut, og egyptarane tok til å fæla for Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Soleis nøydde dei no Israels-folket til å træla for seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'og gjorde livet surt for deim med hardt arbeid i leirtaki og tiglverki og med allslags jordarbeid: alt arbeidet dei vilde ha gjort, det truga dei deim til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Og kongen i Egyptarland sagde til dei hebraiske ljosmøderne - den eine av dei heitte Sifra og den andre Pua -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, '«Kvar gong de hjelper ei hebraisk barnsengkona,» sagde han, «so skal de sjå i fødestolen: Er det son ho hev fenge, so drep honom! er det dotter, so må ho liva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Men ljosmøderne hadde age for Gud, og gjorde ikkje som kongen i Egyptarland sagde, men let småsveinarne liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Då kalla kongen ljosmøderne fyre seg, og sagde med deim: «Kvi gjer de dette og let sveinborni liva?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, '«Dei hebraiske konorne er ikkje som dei egyptiske,» svara ljosmøderne; «dei er sterkare; innan ljosmori kjem, hev dei fenge barnet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Då gjorde Gud vel imot ljosmøderne; og folket auka, og vart ovleg mangment.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Og for di ljosmøderne hadde age for Gud, so gav han deim ætt og avkjøme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Men Farao sende bod utyver til heile folket sitt og sagde: «Kvar son som kjem til verdi, skal de kasta i elvi; berre døtterne skal de lata liva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'So var det ein mann av Levi-ætti som gjekk av og tok seg ei kona, og ho var og av Levi-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Og kvinna vart umhender, og åtte ein son. Ho tykte det var so vent eit barn, og løynde honom i tri månader;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'då kunde ho ikkje få løynt honom lenger. So fann ho ei røyrkista til honom; den brædde ho med jordbik og tjøra, og so lagde ho sveinen upp i, og sette kista i sevet attmed elvebarden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'og syster hans stod eit stykke undan, og skulde sjå korleis det gjekk med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Då kom dotter åt Farao ned åt elvi, og vilde lauga seg, medan møyarne hennar gjekk att og fram på elvbakken. Ho gådde kista i sevet, og sende terna si etter henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'So hadde ho upp loket, og såg barnet; «nei sjå!» sagde ho, «ein liten svein som ligg og græt!» Og ho tykte synd i honom og sagde: «Det er eit av hebræarborni:»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Då sagde syster hans med dotter åt Farao: «Skal eg ganga og finna deg ei hebræarkona som gjev brjost, so ho kann fostra upp barnet for deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, '«Gjer so!» svara kongsdotteri. So gjekk gjenta og henta mor åt barnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Og kongsdotteri sagde til henne: «Tak denne sveinen og fostra honom upp for meg! Eg skal løna deg for det.» So tok kona sveinen, og fostra honom upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Og då han vart stor, gjekk ho til kongsdotteri med honom, og han vart som son hennar. Ho kalla han Moses; «for eg hev teke honom upp or vatnet,» sagde ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'So leid tidi fram til Moses var vaksen. Då var det ein gong han gjekk ut til landsmennerne sine, og såg korleis dei laut slita og slæpa, og so fekk han sjå ein egyptar som slo ein hebræar, ein av landsmennerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Då såg han vel ikring seg, men vart ikkje var nokon, og so slo han egyptaren i hel, og grov honom ned i sanden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Den andre dagen gjekk han ut att, og såg tvo hebræarar som heldt på og slost. Då sagde han med den som hadde skuldi: «Kvi slær du landsmannen din?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, '«Kven hev sett deg til hovding og domar yver oss?» svara han; «tenkjer du på å drepa meg, som du drap egyptaren?» Då vart Moses rædd, og sagde med seg sjølv: «Hev det alt kome upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Då Farao fekk spurt det, freista han å få drepe Moses. Men Moses rømde for Farao, og stana ikkje fyrr han var i Midjanlandet; der sette han seg ned attmed ein brunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Presten i Midjan hadde sju døtter; og dei kom og auste upp vatn, og fyllte trørne, og vilde brynna småfeet åt far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Men so kom det nokre hyrdingar og jaga deim ifrå. Då reis Moses upp og hjelpte deim, og brynnte buskapen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Då dei kom heim att til Re’uel, far sin, sagde han: «Korleis hev det seg at de kjem so tidleg i dag?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, '«Ein egyptar kom og hjelpte oss mot hyrdingarne,» svara dei; «og so auste han upp vatn for oss, og brynnte buskapen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Då sagde Re’uel med døtterne sine: «Kvar er han so? Kvi let de då mannen vera att ute? Bed honom inn, so han kann få seg mat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Moses vart huga til å vera hjå mannen, og han let Moses få Sippora, dotter si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Ho åtte ein son, og Moses kalla honom Gersom; «for eg hev fenge heimvist i eit framandt land,» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Som no dagarne leid og tidi skreid, so døydde kongen i Egyptarland. Men Israels-folket sukka for trældomen og let ille, og naudropi deira steig upp til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Og Gud høyrde korleis dei sukka og stunde, og Gud mintest sambandet sitt med Abraham og Isak og Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'For Gud hadde auga med Israels-borni, og Gud visste korleis til stod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Moses han gjætte no buskapen åt Jetro, verfar sin, presten i Midjan. So var det ein gong han for langt atti heidi med fenaden, då kom han til Gudsfjellet, til Horeb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Der synte Herrens engel seg for honom i ein eldsloge, som slo beint upp or ein klungerrunne; han såg at runnen stod i ljos loge, men klungeren brann ikkje upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Då tenkte Moses med seg: «Eg vil ganga innåt og sjå dette store underet, kvifor klungeren ikkje brenn upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Då Herren såg at han kom innåt og vilde sjå, so ropa Gud til honom utor klungerrunnen: «Moses, Moses!» Og han svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Då sagde han: «Kom ikkje næmare! Hav av deg skorne! For staden du stend på, er heilag jord.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Og han sagde: «Eg er far din’s Gud, Abrahams Gud og Isaks Gud og Jakobs Gud.» Då løynde Moses andlitet sitt, for han torde ikkje sjå på Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Og Herren sagde: «Eg hev set kor vondt folket mitt hev det i Egyptarland, og høyrt klageropi deira yver futarne; eg veit kva dei lid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Og no hev eg stige ned, og vil fria deim ut frå egyptarane og føra deim ut or dette landet, til eit godt og vidt land, til eit land som fløymer med mjølk og honning, der som kananitarne er og hetitarne og amoritarne og perizitarne og hevitarne og jebusitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'For no hev naudropet frå Israels-borni nått upp til meg, og eg hev og set korleis egyptarane trugar og plågar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Gakk no du til Farao med bod frå meg, og før folket mitt, Israels-borni, ut or Egyptarland!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Då sagde Moses til Gud: «Er eg den mann, at eg kann ganga til Farao, og kann eg føra Israels-borni ut or Egyptarland?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Og han sagde: «Ja, for eg skal vera med deg! Og det skal du hava til merke på at det er eg som hev sendt deg: Når du hev ført folket ut or Egyptarland, so skal de halda gudstenesta på dette fjellet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Då sagde Moses til Gud: «Men når eg no kjem til Israels-borni og segjer med deim: «Fedreguden dykkar hev sendt meg til dykk,» og dei so spør: «Kva er namnet hans?» kva skal eg då svara deim?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Og Gud sagde til Moses: «Eg er den eg er! So skal du svara Israels-borni,» sagde han: «Han som heiter «Eg er», hev sendt meg til dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Og endå sagde Gud det til Moses: «So skal du segja til Israels-borni: «Herren, fedreguden dykkar, Abrahams Gud og Isaks Gud og Jakobs Gud, hev sendt meg til dykk. Det skal vera namnet mitt i all æva, og so skal dei kalla meg ætt etter ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Gakk no du, og samla i hop dei øvste i Israel, og seg med deim: «Herren, fedreguden dykkar, Abrahams Gud og Isaks Gud og Jakobs Gud, hev synt seg for meg og sagt: Eg hev havt auga med dykk og veit korleis dei fer åt med dykk i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Og eg sagde: «Eg vil fria dykk ut or alt det vonde de lid i Egyptarland, og fylgja dykk fram til landet åt kananitarne og hetitarne og amoritarne og perizitarne og jebusitarne, eit land som fløymer med mjølk og honning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Og dei skal gjeva gaum etter ordi dine, og so skal du ganga fram for kongen i Egyptarland, du og dei øvste i Israel, og de skal segja med honom: «Herren, Hebræarguden, hev møtt oss! Gode, gjev oss lov til å fara tri dagsleider ut i øydemarki og ofra til Herren, vår Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Men eg veit at kongen i Egyptarland ikkje gjev dykk lov til å fara, ikkje um han so fær kjenna ei sterk hand yver seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'So vil eg då lyfta handi mi, og slå egyptarane med alle underi mine, som eg vil gjera midt imillom deim, og då skal dei sleppa dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Og eg vil gjera det so at egyptarane fær godvilje for dette folket, so de ikkje skal fara tomhendte, når de fer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'men kvar kona skal beda grannekona si, eller den ho bur i hus med, um sylv og gull og helgeklæde, og det skal de lata sønerne og døtterne dykkar hava på seg; det skal vera herfanget de tek av egyptarane.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Då svara Moses og tok so til ords: «Dei vil visst ikkje tru meg og ikkje lyda på meg, men berre segja at Herren ikkje hev synt seg for meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, '«Kva er det du hev i handi?» spurde Herren. «Ein stav», svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, '«Kasta honom på jordi!» sagde Herren. So kasta Moses staven på jordi; då vart han til ein orm, og Moses rømde for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, '«Rett ut handi og grip han i sporden!» sagde Herren. So rette han ut handi, og treiv ormen, og då vart han til ein stav att i handi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '«No lyt dei vel tru, at Herren, fedreguden deira, hev synt seg for deg, Abrahams Gud og Isaks Gud og Jakobs Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Og endå sagde Herren til honom: «Stikk handi di i barmen!» So stakk han handi i barmen, og drog henne ut att, og då han skulde sjå til, so var handi hans spilt og kvit som snø.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Då sagde Herren: «Stikk handi di i barmen endå ein gong!» So stakk han handi i barmen, og då han drog henne ut or barmen, då var ho like god att, og hadde same liten som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '«Um dei no ikkje trur deg, og ikkje agtar på det fyrste teiknet, so trur dei då visst på det andre teiknet,» sagde Herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, '«men trur dei ikkje på noko av desse tvo teikni, og vil dei ikkje lyda på deg, so skal du taka vatn or elvi og ausa upp på turre marki; og vatnet som du tek or elvi, det skal verta til blod, med det same det kjem på marki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Men Moses sagde til Herren: «Orsaka meg, Herre! Eg hev aldri vore nokon munnfør mann, korkje fyrr, eller sidan du tok til å tala med tenaren din; eg er både tungmælt, og eg er taugmælt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Då sagde Herren til honom: «Kven er det som gjev menneskja munnen? Og kven er det som gjer mållaus eller dauv eller klårsynt eller blind? Er ikkje det eg, Herren?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Gakk no berre, og eg skal vera med munnen din og lære deg kva du skal tala.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, '«Å Herre, eg bed for meg!» svara Moses, «send heller ein annan med det bodet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Då vart Herren harm på Moses, og sagde: «Er ikkje Aron av Levi-ætti, bror din? Han, veit eg, kann tala. Og rett no kjem han og møter deg, og når han ser deg, so vert han hjarteleg glad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Honom skal du tala til og leggja ordet i munnen hans, og eg skal signa både din munn og hans munn, og læra dykk kva de skal gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Han skal tala til folket for deg, og vera liksom munnen din, og du skal vera som ein Gud for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Og denne staven skal du hava i handi; den er det du skal gjera underi med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'So gjekk Moses, og då han kom heim att til Jetro, verfar sin, sagde han med honom: «Kjære deg, lat meg fara attende til skyldfolket mitt i Egyptarland, og sjå um dei liver endå.» Og Jetro svara: «Far i fred!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'I Midjan sagde Herren til Moses: «Tak no i veg, og far attende til Egyptarland! For no er dei burte alle dei som leita etter deg og vilde taka livet ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'So tok Moses kona si og sønerne sine og sette deim på asnet, og for attende til Egyptarlandet; og gudsstaven hadde han i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Og Herren sagde til Moses: «Når du kjem attende til Egyptarland, so kom i hug at du gjer alle dei underi som eg hev lagt i henderne dine, so Farao ser på det. Men eg vil gjera honom strid i hugen, so han ikkje let folket fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Då skal du segja med Farao: «So segjer Herren: «Israel er son min, den eldste av sønerne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Og eg sagde til deg: «Lat son min fara, so han kann tena meg!» Men du vilde ikkje lata honom fara. Sjå difor vil eg no slå i hel din son, den eldste av sønerne dine.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Då dei var no på vegen komne, og hadde roa seg til natti, kom Herren yver honom og lest vilde drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Då tok Sippora ein kvass stein, og skar av huveholdet på son sin, og kasta det framfor føterne hans Moses, og sagde: «Du er meg ein blodbrudgom, du!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'So let han honom vera. Det var umskjeringi ho tenkte på, då ho sagde «blodbrudgom».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Og Herren sagde til Aron: «Gakk ut i øydemarki, so møter du Moses!» So gjekk han, og råka Moses innmed Gudsfjellet, og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Og Moses sagde med Aron kva ærend og ord Herren hadde sendt honom med, og kva teikn han hadde sett honom til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'So gjekk Moses og Aron, og samla i hop alle dei øvste av Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Og Aron bar fram alle dei ordi som Herren hadde tala til Moses, og gjorde teikni, so folket såg på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Og folket trudde; og då dei høyrde at Herren var komen og vilde lydast til Israels-borni, og at han hadde set kva vande dei var i, so lagde dei seg på kne og bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Sidan gjekk Moses og Aron fram for Farao og sagde: «So segjer Herren, Israels Gud: «Lat folket mitt fara, so dei kann halda høgtid for meg i øydemarki!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Då sagde Farao: «Kva er det for ein «Herre» som eg skal lyda, og lata Israel fara? Eg kjenner ikkje den «Herren», og eg vil ikkje lata Israel fara heller.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, '«Hebræarguden hev møtt oss!» svara dei. «Gode, gjev oss lov å fara tri dagsleider ut i øydemarki og ofra til Herren, vår Gud, so han ikkje skal koma yver oss med sott eller sverd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Då sagde egyptarkongen til deim: «Moses og Aron, kvi hefter de folket burt frå det dei hev å gjera? Gakk til arbeidet dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'De ser kor mykje folk her er i landet no,» sagde Farao, «og so vil de lokka deim til å leggja ned arbeidet sitt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Og same dagen sagde Farao det til futarne og formennerne for arbeidsfolket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '«Heretter skal de ikkje gjeva folket halm til mursteinen, som de fyrr hev gjort. Dei skal sjølve ganga og sanka seg halm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Men like mykje murstein skal de krevja av deim no som fyrr; de skal ikkje slå av på talet. For dei er late; difor skrik dei og segjer: «Me vil av og ofra til Guden vår.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Legg tyngre arbeid på kararne, so dei hev nok å gjera, og ikkje fer etter lygjerødor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'So gjekk futarne og arbeidsformennerne ut, og sagde til folket: «So segjer Farao: «Eg gjev dykk ikkje halm lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Gakk sjølve og finn dykk halm kvar de kann! Men i arbeidet dykkar fær de ikkje noko avslag.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Då spreidde folket seg utyver heile Egyptarland, og sanka helma til å bruka i staden for halmen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Men futarne dreiv på og sagde: «Gjer arbeidet dykkar ferdigt, fullt dagsverk til kvar dag, som då de hadde halm for hand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Og arbeidsformennerne som futarne åt Farao hadde sett yver Israels-folket, fekk hogg, og futarne sagde: «Kvi hev de ikkje gjort ifrå dykk ålaget dykkar anten i går eller i dag, som de fyrr gjorde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Då gjekk arbeidsformennerne til Farao, og kjærde seg for honom og sagde: «Kvi fer du soleis med tenarane dine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Halm fær me ikkje, og like vel segjer dei til oss: «Gjer murstein!» Og so fær me hogg, endå det er dine folk som hev skuldi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Men han sagde: «Late er de, late! Difor segjer de: «Me vil av og ofra til Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Gakk no av og arbeid! Og halm fær de ikkje, men mursteinen skal de greida, talet fullt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Arbeidsformennerne vart ille ved, då dei fekk høyra dei ordi: «De fær ikkje noko avslag på mursteinen dykkar, fullt dagsverk til kvar dag!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Då dei kom ut att frå Farao, møtte dei Moses og Aron, som stod og venta på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Då sagde dei med deim: «Herren setje augo på dykk, og late dykk få like for di de hev gjort Farao og mennerne hans hatige på oss, og gjeve deim sverdet i handi til å drepa oss med!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Og Moses vende seg atter til Herren og sagde: «Herre, kvi fer du so ille med dette folket? Kvi hev du då sendt meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'For alt ifrå den stund eg gjekk fram for Farao og tala i ditt namn, hev han ikkje gjort anna enn vondt mot dette folket, og du hev ikkje hjelpt folket ditt ein grand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Då sagde Herren til Moses: «No skal du sjå, kva eg vil gjera med Farao: Ei sterk hand skal nøyda honom til å sleppa deim, og for den same sterke handi skuld skal han jamvel driva deim ut or landet sitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Og Gud tala endå meir til Moses, og sagde med honom: «Eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Eg synte meg for Abraham, og for Isak, og for Jakob, og nemnde meg Gud den Allvelduge, men dette namnet mitt, Herren, gjorde eg ikkje kunnigt for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Og eg gjorde eit samband med deim: eg lova å gjeva deim Kana’ans-landet, det landet dei heldt til i, då dei ferdast på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Og no hev eg høyrt, korleis Israels-borni sukkar og styn, av di egyptarane held deim i trældom, og eg minnest kva eg hev lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Seg no med Israels-borni: «Eg er Herren; eg vil taka av dykk dei tunge byrderne de ber for egyptarfolket, og løysa dykk or trældomen dei held dykk i, og fria dykk ut med fast arm og strenge domar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'eg vil gjera dykk til mitt folk, og vera dykkar Gud, og de skal sanna at eg er Herren, dykkar Gud, som tek av dykk dei tunge byrderne de ber for egyptarfolket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Og eg vil føra dykk til det landet som eg rette handi i veret på at eg vil gjeva Abraham og Isak og Jakob, og det vil eg gjeva dykk til eiga, eg, Herren.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Og Moses sagde det med Israels-borni, men dei høyrde ikkje på honom, av di dei var modlause og laut træla so hardt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Då tala Herren til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '«Gakk fram for Farao, egyptarkongen, og seg med honom, at han skal lata Israels-borni fara ut or landet sitt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Og Moses svara og tok so til ords, der han stod fram for augo åt Herren: «Du ser Israels-borni vil ikkje høyra på meg; er det då ventande at Farao skulde lyda etter det eg segjer, eg som er so valen på munnen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Soleis tala Herren til Moses og Aron, og sende deim til Israels-mennerne og til Farao, egyptarkongen, med det bodet at dei skulde fylgja Israels-folket ut or Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'No skal de høyra kva ættefederne deira heitte: Sønerne åt Ruben, eldste son åt Israel, det var Hanok og Pallu, Hesron og Karmi. Frå deim er Rubens-ætterne komne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Sønerne åt Simeon var Jemuel og Jamin og Ohad og Jakin og Sohar og Saul, som var son åt ei Kana’ans-kvende. Frå deim er Simeons-ætterne komne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'So er namni på sønerne åt Levi med ættgreinerne deira: Gerson og Kahat og Merari. Og livedagarne åt Levi vart hundrad og sju og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Sønerne åt Gerson var Libni og Sime’i med ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Sønerne åt Kahat var Amram og Jishar og Hebron og Uzziel. Og livedagarne åt Kahat vart hundrad og tri og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Sønerne åt Merari var Mahli og Musi. Dette var federne åt Levi-ætterne etter ættartalet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram tok Jokebed, farsyster si, til kona, og dei fekk sønerne Aron og Moses. Og livedagarne åt Amram vart hundrad og sju og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Sønerne åt Jishar var Korah og Nefeg og Zikri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Sønerne åt Uzziel var Misael og Elsafan og Sitri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aron tok Eliseba til kona; ho var dotter åt Amminadab og syster åt Nahson; og dei fekk sønerne Nadab og Abihu, Eleazar og Itamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Sønerne åt Korah var Assir og Elkana og Abiasaf. Frå deim er Korah-ætterne komne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleazar, son åt Aron, tok ei dotter åt Putiel til kona, og dei fekk sonen Pinehas. Dette var gamlefederne åt Levi-folket med ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Desse mennerne, Aron og Moses, var det Herren sagde det til: «Før Israels-folket ut or Egyptarland, fylking etter fylking!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Dei var det som tala med Farao, kongen i Egyptarland, og sagde dei skulde fylgja Israels-folket ut or Egyptarland, desse tvo mennerne, Moses og Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Og det gjekk so til at den gongen Herren tala til Moses i Egyptarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'då tok Herren soleis til ords: «Eg er Herren! Seg no med Farao, egyptarkongen, alt det eg segjer til deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Og Moses svara, der han stod for Guds augo: «Du veit eg er munnvalen; er det då ventande at Farao vil høyra på meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Då sagde Herren til Moses: «Sjå no vil eg laga det so at du vert som ein Gud for Farao, og Aron, bror din, skal vera målsmannen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du skal tala alt det eg segjer deg fyre, men Aron, bror din, skal orda det ut for Farao, so han let Israels-folket fara ut or landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Men eg vil herda hugen åt Farao, og sidan vil eg gjera mange teikn og under i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Farao kjem ikkje til å høyra på dykk, og då vil eg leggja mi hand på Egyptarland med harde refsingar, og føra herarne mine, folket mitt eige, Israels-borni, ut or Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Og egyptarane skal ljota sanna at eg er Herren, når eg rettar handi mi utyver landet, og tek Israels-borni beint ifrå deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Og Moses og Aron gjorde dette; som Herren hadde sagt deim fyre, so gjorde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moses var åtteti og Aron tri og åtteti år gamall, då dei tala med Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Og Herren sagde det til Moses og Aron:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '«Når Farao talar til dykk og segjer: «Lat meg få sjå eit under av dykk!» då skal du segja med Aron: «Tak staven din, og kasta honom ned framfor augo åt Farao, so skal han verta til ein stor orm.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'So gjekk Moses og Aron fram for Farao, og gjorde som Herren hadde sagt: Aron kasta ned staven sin framfor augo åt Farao og mennerne hans, og staven vart til ein diger orm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Då sende Farao bod etter vismennerne og trollkararne, runemeistrarne, som dei hadde i Egyptarland, og dei bruka trollkunsterne sine og gjorde det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Dei kasta kvar sin stav, og dei vart til store ormar, men staven hans Aron gløypte stavarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Og det gjekk som Herren sagde: Farao var strid i hugen og vilde ikkje høyra på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Då sagde Herren til Moses: «Farao er tråssug; han vil ikkje lata folket fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gakk til honom i morgon tidleg - då kjem han ned åt elvi - og statt på elvbakken, so han møter deg, og staven som vart skapt um til ein orm, skal du hava i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Og so skal du segja med honom: «Herren, Hebræarguden, sende meg til deg og sagde: «Lat folket mitt fara, so dei kann tena meg i øydemarki!» Men det hev’kje du vilja lydt på endå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Og Herren segjer so: «Dette skal du hava til merke på at eg er Herren: Sjå no vil eg slå i elvevatnet med denne staven, som eg hev i handi mi, og so skal det verta til blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Og fisken i elvi skal døy, og ein illtev stiga frå elvi, so egyptarane ikkje er god til å drikka vatnet i henne.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Sidan sagde Herren til Moses: «Seg med Aron: «Tak staven og rett handi di ut yver Egyptarlands-vatni, yver åerne og elvarne og tjørnerne deira og yver kvar vatsdam der er, so skal dei verta til blod, og blod skal det vera utyver heile Egyptarlandet, jamvel i koppar og kjer.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Og Moses og Aron gjorde som Herren sagde: Aron lyfte staven, og slo i elvevatnet, so dei såg på det både Farao og mennerne hans, og alt vatnet i elvi vart blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Då døydde all fisken i elvi, og det stod ein ond tev av elvi, so egyptarane ikkje kunde drikka vatnet, og i heile Egyptarland var det blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Men runemeistrarne deira bruka trollkunsterne sine, og gjorde det same. Og det gjekk som Herren sagde: Farao var stridhuga og høyrde ikkje på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Og Farao snudde seg og gjekk inn i huset sitt, og brydde seg ikkje um dette heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Men alle egyptarane grov kringum elvi etter drikkevatn; for dei kunde ikkje drikka elvevatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'So leid det sju dagar etter Herren hadde gjort elvi til blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Då sagde Herren til Moses: «Gakk fram for Farao og seg med honom: «So segjer Herren: «Lat folket mitt fara, so dei kann tena meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Meinkar du deim å fara, so skal eg plåga heile ditt land og rike med frosk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'det skal yra med frosk i elvi, og dei skal krabba upp på land, og koma inn i husi dine og sengkoven din og upp i lega di, og inn i husi åt mennerne dine og på folket ditt, og i bakaromnarne og knodetrogi dine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'og deg og huslyden din og alle mennerne dine skal froskarne krabba uppetter.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Og Herren sagde til Moses: «Seg til Aron: «Lyft handi, og rett staven ut yver åerne og elvarne og tjørnerne, og lat froskarne aula innyver Egyptarlandet!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'So rette Aron handi si ut yver Egyptarlands-vatni, og då kom det upp med so fullt med frosk at dei hulde heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Men runemeistrarne bruka trollkunsterne sine og gjorde det same: dei og fekk froskarne til å aula innyver Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'So sende Farao bod etter Moses og Aron og sagde: «Bed til Herren at han vil taka froskarne burt frå meg og landslyden! Då skal eg lata folket fara, so dei kann ofra til Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Då sagde Moses med Farao: «Sjølv må du hava æra og segja kva tid eg skal beda for deg og mennerne dine og folket ditt, at han vil rydja froskarne burt frå deg og husi dine, so dei ikkje finst meir utan i elvi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, '«I morgon,» svara han. «Lat det vera som du segjer!» sagde Moses, «so skal du sanna at det er ingen som Herren, vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Froskarne skal kverva burt frå deg og husi dine og frå mennerne dine og heile landslyden; berre i elvi skal dei finnast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'So gjekk Moses og Aron ut att frå Farao, og Moses ropa til Herren for froskarne skuld, som han hadde ført yver Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Og Herren gjorde som Moses bad, og froskarne låg daude i hus og i tun og på bøarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Dei samla deim i dungevis, og teven kjendest yver heile landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Men det gjekk som Herren sagde: Då Farao såg at han hadde fenge ein lette, slo han seg rang, og vilde ikkje høyra på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Då sagde Herren til Moses: «Seg med Aron: «Rett ut staven din, og slå i dusti på jordi, so skal ho verta til my i heile Egyptarlandet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Og dei so gjorde: Aron lyfte handi, og rette ut staven sin, og slo i dusti på jordi. Då kom myet, og sette seg både på folk og fe; all dusti på jordi vart til my i heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Runemeistrarne freista og å få fram my med trollkunsterne sine, men dei var ikkje god til. Og myet vart sitjande på folk og på fe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Då sagde runemeistrarne med Farao: «Dette er Guds finger!» Men det gjekk som Herren sagde: Farao var like strid, og høyrde ikkje på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Då sagde Herren til Moses: «Ris tidleg upp i morgon, og stig beint fram for Farao, når han gjeng nedåt elvi, og seg med honom: So segjer Herren: «Lat folket mitt fara, so dei kann tena meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'For let du ikkje folket mitt fara, so sender eg allslags avåt yver deg og mennerne dine og folket ditt og inn i husi dine; husi åt egyptarane skal verta fulle av avåt, og jamvel jordi dei gjeng på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Men same dagen vil eg taka undan Gosenlandet, som folket mitt bur i, so der ikkje kjem noko avåt; då skal du verta var, at eg, Herren, er der i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'For eg vil løysa ut folket mitt og skilja det frå ditt folk. I morgon skal dette underet henda.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Og Herren gjorde som han hadde sagt, og det kom svære yrjor med avåt i husi åt Farao og mennerne hans og yver heile Egyptarland; det var so avåtet reint skjemde ut landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Då sende Farao bod etter Moses og Aron, og sagde: «Gakk av og ofra til Guden dykkar her i landet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, '«Det er ikkje rådlegt å gjera det so,» svara Moses; «for det me ofrar til Herren, vår Gud, det er ein styggedom for egyptarane. Ofra me no midt for augo på deim slikt som dei hev ein stygg til, vilde dei ikkje då steina oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Tri dagsleider ut i øydemarki vil me fara, og so ofra til Herren, vår Gud, soleis som han segjer oss fyre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Då sagde Farao: «Eg fær lata dykk fara då, so de kann ofra til Herren, Guden dykkar, i øydemarki, men de må’kje fara langt! Bed for meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, '«Ja, no gjeng eg ut, og vil beda til Herren,» svara Moses, «og i morgon skal avåtet kverva burt frå Farao og frå mennerne og folket hans. Berre no Farao ikkje vil svika oss meir, men lata folket fara, so dei kann ofra til Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'So gjekk Moses ut frå Farao att, og bad til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Og Herren gjorde som Moses bad, og let avåtet kverva burt både frå Farao og mennerne og folket hans; det fanst ikkje att eit einaste fly.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Men Farao slo seg rang denne gongen og, og slepte ikkje folket av stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Og Herren sagde til Moses: «Gakk fram for Farao og seg med honom: «So segjer Herren, Hebræarguden: «Lat folket mitt fara, so dei kann tena meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'For meinkar du deim å fara, og held du deim att endå lenger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'so skal Herren leggja si hand på feet ditt, som beiter på bøen, både hestar og asen og kamelar og naut og sauer, og søkja deim med ei øgjeleg drepsott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Men Herren skal gjera skil på israelsfeet og egyptarfeet, og det skal ikkje døy noko av det som høyrer Israel til.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Og Herren sette tidi og sagde: «I morgon vil Herren lata dette henda i landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Dagen etter gjorde Herren som han hadde sagt, og alt egyptarfeet døydde, men av feet åt Israels-folket døydde ikkje eit liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Og Farao sende bod, og då hadde det ikkje døytt eit einaste liv av israelsfeet. Men Farao sette hardt imot hardt, og meinka folket å fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Då sagde Herren til Moses og Aron: «Tak henderne fulle med omnsoska, og Moses skal kasta henne upp i veret, so Farao ser på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Då skal ho verta til dumba og fjuka utyver heile Egyptarland, og av dumba skal det koma ei sott som bryt ut med kaunar på folk og fe i alt Egyptarlandet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'So tok dei oska or masomnen, og steig fram for Farao, og Moses kasta henne upp i veret; då kom det ei kaunsott som braut ut på folk og på fe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Og runemeistrarne orka ikkje å standa framfor Moses for verken skuld; for kaunarne hadde sett seg på runemeistrarne som på alle egyptarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Men Herren gjorde Farao strid i hugen; og det gjekk som han hadde sagt med Moses: Farao høyrde ikkje på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Då sagde Herren til Moses: «Ris tidleg upp i morgon, og stig beint fram for Farao, og seg med honom: «So segjer Herren, Hebræarguden: «Lat folket mitt fara, so dei kann tena meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'For denne gongen vil eg senda alle mine plågor yver deg sjølv og mennerne dine og folket ditt, so du skal sanna at ingen er som eg på heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'No hadde eg alt lyft handi mi, og vilde slege deg og folket ditt med drepsott, og då hadde du vorte utrudd av verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Men eg sparde deg, av di eg vilde syna deg magti mi og gjera namnet mitt kunnigt yver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Endå legg du deg i vegen for folket mitt, og vil ikkje lata deim fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Sjå, difor vil eg i morgon dette bil senda eit øgjeleg haglver, som det aldri hev vore maken til i Egyptarlandet, frå den dag det vart grunna og til no.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Send no bod, og berga buskapen din og alt de du hev på marki! Alt som er ute og ikkje kjem seg i hus, anten det er folk eller fe, skal haglet koma yver, og dei skal døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Dei av kongsmennerne som hadde age for ordi åt Herren, dei berga då tenarane og buskapen sin i hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Men dei som ikkje agta på Herrens ord, let både tenarane og buskapen vera ute.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Då sagde Herren til Moses: «Rett handi di upp imot himmelen, so skal haglet koma sturtande yver heile Egyptarland, på folk og på fe og på kvart strå som på marki veks i Egyptarlandet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'So rette Moses staven sin upp imot himmelen. Då sende Herren torever og hagl, og eldingarne for ned til jordi, medan Herren let det hagla yver Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Haglet kom drusande, og midt i haglflodi gjekk det ljon i ljon. Aldri hadde det vore slikt uver i Egyptarlandet, frå den tid det vart bygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Og haglet slo ned alt som ute var i heile Egyptarland, både folk og fe, og all grøda på marki slo haglet ned, og kvart tre braut det sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Men i Gosenlandet, der Israels-folket budde, der gjekk ikkje haglflodi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Då sende Farao bod etter Moses og Aron, og sagde med deim: «Denne gongen hev eg synda. Herren er den som hev rett, og eg og folket mitt me hev urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Bed til Herren at det må hava ein ende med toreslåtten og haglet, so skal eg lata dykk fara, og de tarv ikkje bia lenger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, '«Med same eg kjem ut or byen, skal eg lyfta henderne og beda til Herren,» svara Moses. «Då skal tora halda upp, og haglet driva av, so du skal sanna at jordi høyrer Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Men det veit eg vel at du og mennerne dine endå ikkje hev age for Herren Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Både lin og bygg var nedslege; for bygget stod med aks, og linet med blom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Men kveiten og rugen var ikkje nedslege; for dei årar seinare.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Og Moses gjekk burt frå Farao og ut or byen, og lyfte henderne til Herren. Då heldt tora og haglveret upp, og regnet hylja ikkje meir ned på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Men då Farao såg at regnet og haglet og tora hadde stogga, so heldt han på og synda, og herde seg til, både han og mennerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Det gjekk som Herren hadde havt Moses til å segja: Farao var hard som stein, og vilde ikkje lata Israels-folket fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Og Herren sagde til Moses: «Gakk fram for Farao! For det er eg som hev gjort honom so hard, både honom og mennerne hans, so eg kunde fremja desse teikni mine imillom deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'og so du skal fortelja son din og soneson din korleis eg hev fare åt med egyptarane, og kva teikn eg hev gjort hjå deim - so de skal sanna at eg er Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'So gjekk Moses og Aron fram for Farao og sagde med honom: «So segjer Herren, Hebræarguden: «Kor lenge skal det vara fyrr du vil bøygja deg for meg? Lat folket mitt fara, so dei kann tena meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'For trassar du og ikkje let folket mitt fara, so skal eg i morgon senda grashoppar inn i riket ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Dei skal breida seg ut yver åker og eng, so tett at ein ikkje kann sjå marki, og eta upp kvar einaste grand som de hev att etter haglet, og snøyda kvart eit tre som veks i hagarne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Og dei skal fylla upp husi for deg og mennerne dine og alle egyptarane, so ikkje federne dine og ikkje federne åt federne dine skal ha set slik syn, frå den dag dei vart til på jordi og til den dag i dag.»» Dermed snudde han seg, og gjekk burt ifrå Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Då sagde hirdmennerne med Farao: «Kor lenge skal denne mannen vera ei snara for oss? Lat no folki fara, so dei kann tena Herren, Guden sin! Ser du ikkje endå at Egyptarlandet vert øydelagt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'So kalla dei Moses og Aron attende til Farao, og han sagde med deim: «Gakk so av stad då, og ten Herren, Guden dykkar! Kor mange er det no som skal fara?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, '«Me lyt fara alle, både unge og gamle,» svara Moses; «både sønerne og døtterne våre lyt vera med oss, både småfeet og storfeet vårt; for me skal halda ei stor høgtid for Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Då sagde han til deim: «Herren vere med dykk, so visst som eg let dykk fara burt med borni dykkar! Sjå der um de ikkje tenkjer på vondt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nei, dette vert ikkje noko av! De mennerne kann fara og tena Herren; for det var det de bad um!» Dermed jaga dei deim burt frå augo åt Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Då sagde Herren til Moses: «Rett handi di ut yver Egyptarland, so skal grashopparne koma drivande innyver landet og eta upp all grøda på marki, alt som haglet hev spart.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'So rette Moses staven sin ut yver Egyptarland, og Herren sende ein austanvind som stod innyver landet heile den dagen og heile natti; um morgonen kom austanvinden med grashopparne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Og grashopparne dreiv innyver heile Egyptarlandet, og slo seg ned i heile riket, ein uhorveleg brote: aldri fyrr hadde det vore so mykje med grashoppar, og aldri meir vil det koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Dei lagde seg utyver landet, so tett at markerne myrkna, og åt upp all grøda på åkrarne og all alda på trei, som haglet hadde leivt, og det fanst ikkje att namnet av grønt, anten på tre eller strå, i heile Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Då skunda Farao seg og sende bod etter Moses og Aron, og sagde: «Eg hev synda mot Herren, dykkar Gud, og mot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Kjære væne, gjev til synda mi denne enaste gongen, og bed til Herren, dykkar Gud, at han berre vil taka denne fæle landøyda burt frå meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'So gjekk Moses ut att frå Farao, og bad til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Då vende Herren vinden, so det vart ein ovsterk vestanvind, og den førde grashopparne burt, og støytte deim ned i Raudehavet; det vart ikkje att ein einaste grashopp i heile Egyptarriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Men Herren gjorde Farao hard i hugen, so han ikkje let Israels-folket fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Og Herren sagde til Moses: «Rett handi di upp imot himmelen, so skal det leggja seg myrker yver Egyptarlandet, eit myrker so tjukt at ein kann taka i det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'So rette Moses handi si upp imot himmelen. Då vart det stumende myrkt i heile Egyptarland i tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Den eine timde ikkje den andre, og i tri dagar var det ingen som torde reisa seg av sessen sin. Men der Israels-folket budde, der var det ljost alle stader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Då sende Farao bod etter Moses, og sagde: «Gakk av og haldt høgtid for Herren! Borni dykkar kann og få vera med; men bufeet, både smått og stort, lyt de setja att her.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, '«Du må då gjeva med oss det me treng til slagtoffer og brennoffer, åt Herren, vår Gud!» svara Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, '«Bufeet vårt lyt me hava med oss - ikkje ei klauv må vera att - for det er det me tek av, når me ofrar til Herren vår Gud; og me veit ikkje kva me skal ofra til honom, fyrr me kjem fram.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Men Herren herde hugen åt Farao, og han vilde ikkje lata deim fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Og Farao sagde til Moses: «Gakk ifrå meg! Vara deg! Kom aldri meir for augo mine! For den dag eg ser deg for augo att, skal du døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, '«Ja no sagde du det sjølv,» svara Moses, «og eg kjem aldri meir for augo dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Då sagde Herren til Moses: «Endå ei ulukke vil eg føra yver Farao og egyptarane, so skal han sleppa dykk av; han skal ikkje berre gjeva dykk lov til å fara, men beint fram driva dykk ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Seg no du med folket at kvar mann skal beda grannen sin, og kvar kona grannekona si, um sylv og gull!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Og Herren gjorde det so at egyptarane fekk godvilje for Israels-folket; og so var og Moses ein ovstor mann i Egyptarlandet, både for kongsmennerne og for hitt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Og Moses sagde: «So segjer Herren: «Når det lid til midnatt, vil eg fara midt igjenom Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Då skal det døy, alt som frumbore er i Egyptarlandet, frå den frumborne sonen åt Farao, som sit i høgsetet sitt, til den frumborne sonen åt trælkjerringi, som sit og dreg handkverni, og alle frumsungarne i buskapen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Og frå heile Egyptarland skal det stiga eit øgjeleg skrik, so ingen skal hava høyrt slikt illskrik anten fyrr eller sidan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Men ikkje ein hund skal gøy på nokon i Israel, korkje på folk eller fe. Då skal de verta vare at Herren gjer skil på egyptarane og Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Og alle desse mennerne dine skal koma til meg, og kasta seg ned for meg og segja: «Far herifrå, både du og heile det folket som fylgjer deg!» Og so skal eg fara.» Og han gjekk burt frå Farao i brennande harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Då Herren sagde til Moses: «Farao skal ikkje høyra på dykk, so eg kann få gjort mange under i Egyptarlandet,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'so gjorde Moses og Aron alle desse underi for augo åt Farao; men Herren hadde lagt so strid ein hug i Farao, og han slepte ikkje Israels-folket or landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Og Herren tala so til Moses og Aron, medan dei var i Egyptarlandet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '«Denne månaden skal vera nyårsmånaden dykkar: den fyrste månaden i året skal han vera for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Tala no de til heile Israels-lyden og seg: «Den tiande dagen i denne månaden skal kvar husbonde taka seg ut eit lamb til huset sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Men er lyden hans for liten til å eta upp eitt lamb, so skal han og næmaste grannen taka seg ut eit i hop, etter som dei hev folk til: de skal’kje rekna fleire folk på kvart lamb enn at alle fær metta seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Eit lytelaust verlamb lyt det vera, og årsgamalt; i staden for eit lamb kann de og taka eit kid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'De skal taka det i vare til den fjortande dagen i denne månaden; då skal heile Israels-lyden slagta det soleglads bil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'So skal dei taka noko av blodet og strjuka på både dørskierne og dørkollen på dei husi som dei et i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Og kjøtet skal dei eta same natti; dei skal steikja det på elden, og eta det med søtt brød og bitre urter attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'De må ikkje eta det rått, og ikkje sjoda det i vatn, men steikja det yver elden, med hovud og føter og innmat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Heller ikkje skal de leiva noko av det til morgons; er det noko att um morgonen, so skal de brenna det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Soleis skal de vera budde, når de et det: med beltet kring livet, med skorne på føterne, med stav i handi; og de skal eta det i hast; det er påskehelgi åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'For den same natti vil eg fara igjenom Egyptarlandet, og slå i hel alt som frumbore er i Egyptarland, både folk og fe; og alle egyptargudarne vil eg døma og refsa, eg, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Og blodet på dei husi som de er i, skal vera til eit merke for meg, når eg ser blodet, skal eg fara framum dykk, og de skal’kje verta fyre noko vondt, når eg slær i hel folk i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Og sidan skal denne dagen vera ein minnedag for dykk: då skal de halda helg og høgtid for Herren; ei æveleg lov skal det vera for dykk og etterkomarane dykkar å halda heilag den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sju dagar skal de eta søtt brød; straks den fyrste dagen skal de hava surdeigen burt or husi dykkar; for kvar den mann som et surbrød millom den fyrste og sjuande dagen, han skal rydjast ut or Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Den fyrste dagen skal de halda ei heilag samling, og den sjuande dagen ei heilag samling. Dei dagarne skal de ikkje hava noko arbeid fyre dykk; berre den maten som kvar mann treng, skal de laga til og elles ingen ting gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'De skal høgtida søtebrødhelgi; for då førde eg herarne dykkar ut or Egyptarlandet. Difor skal de høgtida denne dagen; det skal vera ei æveleg lov for dykk og etterkomarane dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Frå fjortandedags kvelden i den fyrste månaden til ein og tjugandedags kvelden i same månaden skal de eta brød som det ikkje er surt i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'I sju dagar må det ikkje finnast surdeig i husi dykkar: kvar den mann som et surbrød, skal rydjast ut or Israels-lyden, anten han er framand eller fødd og alen i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'De må ikkje smaka den minste grand som er syrt; i alle hus skal de eta usyrt brød!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Då kalla Moses i hop alle dei øvste i Israel, og sagde med deim: «No lyt de av og finna dykk lamb åt husi dykkar, og slagta deim til påskeoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Og so skal de taka ein myntekvost og duppa i blodet som er i troget, og strjuka noko av det blodet på dørkollen og båe dørskierne. Og ingen av dykk må ganga ut or husdøri si fyre morgon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'For Herren vil fara igjenom landet og heimsøkja egyptarane; og når han ser blodet på dørkollen og på dørskierne, då skal han fara framum døri og ikkje lata tynarengelen sleppa inn i husi dykkar og drepa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'So skal de då halda dykk etter dette bodet; det skal vera ei lov for deg og borni dine i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Når de so kjem til det landet Herren vil gjeva dykk, som han hev lova, då skal de halda uppe denne helgeseden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Og når borni dykkar spør: «Kva er dette for ein helgesed de brukar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'då skal de svara: «Det er påskeoffer til Herren, som for utum husi åt Israels-folket i Egyptarland: då han heimsøkte egyptarane, sparde han våre hus.»» Då lagde folket seg på kne og bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Og Israels-mennerne gjekk av og gjorde dette; som Herren hadde sagt til Moses og Aron, so gjorde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'So hende det i midnattsstundi at Herren slo i hel alt som frumbore var i Egyptarlandet, frå den frumborne sonen åt Farao, som sat i høgsetet sitt, til den frumborne sonen åt fangen, som sat i myrkestova, og alle frumsungarne i buskapen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Då for Farao upp um natti, han og alle mennerne hans og alle egyptarane, og det vart eit øgjeleg skrik i Egyptarland; for det fanst ikkje eit hus som det ikkje var lik i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Og Farao sende bod etter Moses og Aron midt på natti og sagde: «Nøyt dykk og far ut or riket mitt, både de og Israels-folket, og gakk av og haldt høgtid for Herren, som de hev tala um!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tak med dykk alt bufeet dykkar, både smått og stort, so som de hev sagt, og far burt, og bed godt for meg og!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Og egyptarane anna på Israels-folket at dei skulde hava seg fort utor landet. «Elles døyr me alle saman!» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'So tok Israels-folket deigen sin, fyrr han vart syrt: dei sveipte deigtrogi inn i kjolarne, og bar deim på ryggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Og dei gjorde som Moses sagde, og bad egyptarane um sylv og gull og helgeklæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Og Herren hadde laga det so at egyptarane vilde Israels-folket vel, so dei var gode å beda. Soleis tok dei herfang av egyptarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'So tok då Israels-folket ut frå Ramses, og lagde vegen til Sukkot; dei var på lag seks hundrad tusund gangføre mann, umfram kvende og born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Og ein stor hop med framande fylgde og med deim, og mykje bufe, både smått og stort, ei ovstor drift.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Av deigen dei hadde med seg frå Egyptarland, baka dei hellekakor; for han var ikkje syrt, etter di dei vart jaga ut or Egyptarland og ikkje torde drygja der lenger; og ikkje hadde dei butt seg til med ferdakost heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Den tidi som Israels-folket hadde havt bustaden sin i Egyptarland, var fire hundrad og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Då dei fire hundrad og tretti åri var på dagen utlidne, då tok alle Herrens herar ut frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Den natti var ei vokenatt for Herren, då han fylgde deim ut or Egyptarlandet; den same natti skal alle Israels-borni halda voka for Herren, ætt etter ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Og Herren sagde til Moses og Aron: «So er fyresegni um påskelambet: Ingen framand må eta av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Hev nokon ein tenestdreng som er kjøpt for pengar, so skal du fyrst umskjera honom; sidan kann han eta av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ingen busete eller leigekar må eta av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'I eitt hus skal det eta av det; du må ikkje hava noko av kjøtet ut or huset, og ikkje brjota noko bein i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'So skal heile Israels-lyden gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Og når ein framand held til hjå dykk, og vil halda påskehøgtid for Herren, då skal alle karfolki hans umskjerast, so kann han få vera med og halda høgtid, og då skal han vera jamgod med deim som er fødde og alne i landet; men ein som ikkje er umskoren, må aldri eta av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Det skal gjelda same lovi for deim som er fødde og alne i landet og for dei framande som held til hjå dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Og alt Israels-folket gjorde dette; som Herren hadde sagt til Moses og Aron, so gjorde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Soleis gjekk det til den dagen då Herren fylgde Israels-folket ut or Egyptarland, fylking etter fylking.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Og Herren tala atter til Moses og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '«Alt frumbore hjå Israels-folket skal du vigja åt meg, alt som kjem fyrst frå morsliv: anten det er folk eller fe, so høyrer det meg til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Og Moses sagde til folket: «Kom i hug den dagen då de slapp ut or Egyptarland, or slavehuset! For det var Herren som med si sterke hand leidde dykk ut. Då skal de ikkje eta surbrød!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'I dag er det de tek ut, i aksmånaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Når då Herren hev fylgt deg til landet åt kananitarne og hetitarne og amoritarne og hevitarne og jebusitarne, det som han lova federne dine å gjeva deg, eit land som fløymer med mjølk og honning, då skal du halda gudstenesta på denne visi i denne same månaden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'sju dagar skal du eta søtt brød, og den sjuande dagen skal det vera høgtid for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Søtt brød skal du eta alle dei sju dagarne; ikkje må det finnast surbrød i ditt eige, og ikkje surdeig, so langt som du råder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Og same dagen skal du gjera dette kunnigt for son din, og segja: «Det er til minne um det som Herren gjorde for meg, då eg for frå Egyptarland.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Og det skal vera som det var rita i handi di, og som det stod skrive framfor augo dine, so Herrens lov kann vera på munnen din. For med sterk hand leidde Herren deg ut or Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'So skal du då gjere etter denne fyresegni år etter år, på den tid som er sett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Og når Herren hev fylgt deg til Kana’ans-landet, som han lova deg og federne dine, og hev gjeve deg det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'då skal du eigna åt Herren alt som kjem fyrst frå morsliv. Alt det fyrste som fell undan det feet du eig, og som er han av slaget, det skal høyra Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Det fyrste følet som fell undan kvart asen, skal du løysa med eit lamb eller kid, og løyser du det ikkje, so skal du brjota nakken på det. Men kvart mannebarn - kvart sveinbarn i ætta di - som er frumbore, skal du løysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Når då son din sidan spør deg: «Kva tyder dette?» so skal du svara: «Med sterk hand leidde Herren oss ut or Egyptarland, or slavehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'For det gjekk slik til at då Farao gjorde seg hard og ikkje vilde lata oss fara, då slo Herren i hel alt som frumbore var i Egyptarland, både av folk og av fe. Difor ofrar eg til Herren alt det som kjem fyrst frå morsliv og er han av slaget, men eg løyser kvart sveinbarn i ætti mi som er frumbore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Og det skal vera som det var rita i handi di og skrive millom augo dine at Herren med si sterke hand leidde oss ut or Egyptarland.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Då Farao hadde gjeve folket lov til å fara, so førde Gud deim ikkje på den vegen som bar til Filistarlandet, endå det var den næmaste. Han tenkte dei kunde koma til å angra seg, når dei møtte ufred, og so fara attende til Egyptarlandet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Difor laga Gud det so, at dei svinga inn på den vegen som gjekk gjenom villmarki, til Raudehavet. So for då Israels-mennerene stridsbudde ut or Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Og Moses tok beini av Josef med seg; for Josef hadde teke eiden av Israels-sønerne og sagt: «Når Gud kjem og hentar dykk, so skal de taka beini mine med dykk herifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'So tok dei ut frå Sukkot, og leira seg i Etam, tett innmed øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Og Herren gjekk fyre deim um dagen i ein skystopul, som leidde deim rette vegen, og um natti i ein eldstopul, som lyste for deim, so dei kunde fara natt og dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Skystopulen kvarv ikkje frå folket um dagen, og eldstopulen ikkje um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Sidan tala Herren til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '«Seg med Israels-folket at dei skal snu um og lægra seg framanfor Pi-Hakhirot, millom Migdol og havet; beint for Ba’al-Sefon, midt imot, skal de lægra dykk utmed havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Då kjem Farao til å segja um Israels-folket: «Dei hev kome på villstig, og finn ikkje ut or heidi att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Og eg vil herda hugen åt Farao, so han set etter deim; då skal eg syna magti mi på Farao og heile heren hans, og egyptarane skal få kjenna at eg er Herren.» So gjorde dei som Herren sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Då kongen i Egyptarland fekk vita at Israels-folket hadde rømt landet, då skifte han hug, både han og mennerne hans, og dei sagde: «Kva hev me gjort, som slepte Israel utor tenesta?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'So beitte han fyre vogni si, og herfolket sitt tok han med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Seks hundrad utvalde vogner tok han, og sidan kvar vogn som fanst i Egyptarland, og kjempor var det på alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'For Herren herde hugen åt Farao, egyptarkongen, so han sette etter Israels-folket. Israels-mennerne tok ut med verja i hand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'men egyptarane sette etter, alle vognhestarne åt Farao og riddarane og hermagti hans, og nådde deim att utmed havet, der dei hadde lægra seg, tett innmed Pi-Hakhirot, midt for Ba’al-Sefon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Farao kom næmare og næmare, og då Israels-folket skulde sjå til, då såg dei egyptarane kom setjande etter deim. Då vart Israels-folket fælande rædde, og ropa til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Og dei sagde med Moses: «Fanst det då ikkje graver i Egyptarland, med di du laut hava oss hit og lata oss døy i villmarki? Kvi gjorde du oss dette og lokka oss burt frå Egyptarland?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Var det ikkje det me sagde med deg i Egyptarland! «Lat oss vera i fred!» sagde me, «me vil tena egyptarane; det er betre for oss, det, enn å døy i ville heidi.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Då sagde Moses til folket: «Ver ikkje rædde! Statt no her og sjå den hjelpi som Herren vil senda dykk i dag; for likso visst som de ser egyptarane i dag, likso visst skal de aldri sjå deim meir i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Herren vil strida for dykk, og de skal halda dykk stille.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Og Herren sagde til Moses: «Kvi kallar du på meg? Seg med Israels-folket at dei skal taka i vegen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Og du skal lyfte staven din, og retta handi ut yver havet og kløyva det, so Israels-folket kann ganga midt igjenom havet på turre botnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Men eg vil herda hugen åt egyptarane, so dei set etter deim. Då skal eg syna magti mi på Farao og heile hans her, på vognerne og riddarane hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Og egyptarane skal få kjenna at eg er Herren, når eg brukar veldet mitt på Farao og vognerne og riddarane hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Og Guds engel, som gjekk fyre Israels-heren, tukka seg og steig attum deim: skystopulen, som var framanfor deim, flutte seg og vart standande attanfor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'so han kom imillom egyptarane og Israels-heren; på den eine sida var han skum og myrk, og på hi sida lyste han upp natti, og herarne kom ikkje innåt kvarandre heile natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Då rette Moses handi si ut yver havet, og Herren sende ei strid austanvind, som bles heile natti, so vatnet dreiv undan: han gjorde havet til turt land, og vatnet kløyvde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Og Israels-folket gjekk tvert gjenom havet på turre grunnen, og vatnet stod som ein mur både på høgre og vinstre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Men egyptarane sette etter, og fylgde til midt ut i havet, alle hestarne åt Farao og vognerne og riddarane hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'So hende det fyrstundes i otta at Herren såg ned på egyptarheren frå eld- og skystopulen og forvilla egyptarheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Han slo hjuli undan vognerne deira, so det gjekk tungt for deim å koma fram. Då sagde egyptarane: «Lat oss røma for Israel! For Herren er med deim og strider mot egyptarane!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Og Herren sagde til Moses: «Rett handi di ut yver havet, so skal vatnet fløyma attende yver egyptarane, yver vognerne og riddarane deira!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'So rette Moses handi ut yver havet, og då det leid imot morgonen, kom havet veltande attende i det gamle romet sitt, men egyptarane rømde beint imot bårorne, og Herren støytte deim midt ut i havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Vatnet flødde i hop att, og gøymde vognerne og riddarane i heile Farao-heren, som hadde fylgt etter deim ut i havet; det vart ikkje att ein einast ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Men Israels-folket gjekk tvert igjenom havet på turre sanden, og vatnet stod som ein mur på både sidorne, både den høgre og den vinstre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Soleis berga Herren den dagen Israel for egyptarane, og Israel skoda egyptarane korleis dei låg daude på havstrandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Og då folket såg Guds allmagt på det han gjorde med egyptarane, då fekk dei age for Herren, og dei trudde på Herren og på Moses, tenaren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Då song Moses og Israels-folket denne lovsongen til Herren: «Eg vil syngja um Herren, for stor er han, stor; hest og ridar i havet han støytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Han er min styrke, um han er mitt kvæde; for han hev meg berga. Han er min Gud, han vil eg lova, Gud åt far min, han vil eg prisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Herren er rette hermannen: Herren heiter han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Vognern’ og heren åt Farao tok han og kasta i sjøen. Gjævaste kjemporn’ i Sevhavet sokk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'der bylgja deim gøymde; som stein for dei ned i djupet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Herre, di hand er prydd med kraft; Herre, di hand krys uvener sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Med ditt høge namn slær du fiendar ned; din harm let du loga, då brenn dei som halm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'For din ande stokk vatni i hop, som haugar sjøarne stod, i havdjupet bårorne storkna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, '«Eg eltar deim, eg tek deim att, eg skiftar feng,» sa’ fienden. «Eg vil metta mitt mod, eg vil svinga mitt sverd, eg vil øyda deim ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Ut sende du din ande, og havet hulde deim; som bly deg sokk til botnar i ville vatnet djupt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kvar er, Herre, dei gudar som med deg kunde kappast? Kven er vel lik som du med heilag æra prydd? Kven er so ageleg og hev so fræge verk og store under gjort?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Då handi upp du hov, då gløypte jordi deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Mild som ein far du fylgjer det folket du hev frelst, du leider deim med handi sterk fram til den heilagdomen der du din heimstad hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Folki fær spurt det, og folnar; fælska tek deim som bur i Filistarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Edom-jarlarne ottast for ilt, Moabs-hovdingarn’ støkk so dei skjelv, alle Kana’an-buarne kolnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Rædsla kjem på deim og rygd; når dei augnar din velduge arm, då tegjer dei stilt som ein stein, medan folket ditt, Herre, fer fram, med det folket fer fram som du vann deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du tek deim inn og set deim ned på eigedomen din, det berget som du, Herre, tok til bustad åt deg sjølv, den heilagdomen du, min Gud, hev grunna med di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'I alder og æva skal han råda, Herren min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'For då hestarne åt Farao med vognerne og riddarane hans for ut i havet, då let Herren bårorne fløda i hop yver deim, medan Israels-folket gjekk turrskodde midt igjenom havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Og Mirjam, vismøyi, syster åt Aron, tok trummeringen sin i handi, og alle kvendi gjekk etter henne med trummeslått og dans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Og Mirjam song fyre og kvad: Syng um Herren, for stor er han, stor! Hest og ridar i havet han støytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Sidan førde Moses folket burt frå Raudehavet, og dei kom ut på Surheidi; der for dei tri dagar i øydemarkerne, og kunde ikkje finna vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'So kom dei til Mara, men dei kunde ikkje drikka vatnet i Mara, av di det var beiskt. Difor kalla dei den staden Mara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Og folket mukka mot Moses og sagde: «Kva skal me drikka?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Då ropa han til Herren, og Herren synte honom eit tre; det kasta han upp i vatnet; då vart vatnet godt. Der sette han deim lov og rett, og der røynde han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Og han sagde: «Høyrer du vel etter ordi åt Herren, din Gud, og gjer det som rett er i hans augo, og lyder du bodi og held alle loverne hans, so skal du sleppa alle dei sjukarne, som eg hev lagt på egyptarane; for eg, Herren, vil vera lækjaren din.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Sidan kom dei til Elim. Der var det tolv kjeldor og sytti palmetre, og dei lægra seg der, frammed vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'So tok dei ut att frå Elim, og femtande dagen i andre månaden etter at dei hadde fare frå Egyptarlandet, kom heile Israels-lyden til Sinheidi, som ligg millom Elim og Sinai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Medan dei var der i øydemarkerne, tok heile Israels-lyden til å mukka mot Moses og Aron,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'og sagde: «Det vøre betre me hadde døytt for Herrens hand i Egyptarlandet, då me sat uppyver kjøtgrytorne og åt oss mette på brød. For no hev de ført oss ut i villmarki, so heile denne mannefjølden lyt døy av svolt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Då sagde Herren til Moses: «Sjå no vil eg lata det regna brød åt dykk frå himmelen, og folket skal ganga ut kvar dag og sanka det dei treng for dagen; soleis vil eg røyna deim, um dei held seg etter lovi mi eller ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Og når dei lagar til det dei kjem heim med sette dagen, då skal det vera ein gong til so mykje som det dei elles sankar um dagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'So sagde Moses og Aron til alt Israels-folket: «I kveld skal de koma til å sanna at det er Herren som hev ført dykk ut or Egyptarlandet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'og i morgon tidleg skal de få sjå kor stor Herren er; for han hev høyrt korleis de mukkar imot honom - kva er vel me? kann det vera verdt å mukka mot oss?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'De skal få sjå det,» sagde Moses, «når han gjev dykk kjøt å eta i kveld og brød i morgon tidleg, so de fær metten dykkar; for Herren hev høyrt korleis de murrar og mukkar imot honom - kva er vel me? det er ikkje oss de mukkar imot, men Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'So Moses sagde med Aron: «Seg til heile Israels-lyden: «Stig fram for Herrens åsyn! For han hev høyrt korleis de mukkar.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Då hende det, medan Aron tala til heile Israels-lyden, og dei vende augo mot øydemarki, at Herrens herlegdom synte seg i skyi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Og Herren tala til Moses og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '«Eg hev høyrt korleis Israels-folket mukkar. Tala du til deim og seg: «I skumingi skal de få kjøt å eta, og i morgon tidleg skal de få metta dykk med brød, og de skal sanna, at eg er Herren, dykkar Gud.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Då det so vart kvelden, kom enghønorne fljugande so tjukt, at dei tekte heile lægret, og um morgonen hadde det lagt seg dalskodd rundt ikring lægret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'og då skoddi letta, fekk dei sjå noko fint, kornut, burtyver heidi; det låg tunt som ei hela på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Då Israels-folket såg det, sagde dei seg imillom: «Kva er dette?» For dei visste ikkje kva det var. Då sagde Moses til deim: Det er det brødet som Herren hev gjeve dykk å eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Høyr no kva Herren hev sagt: «De skal sanka av det so mykje de treng, ei kanna til manns, etter som de hev folk til; kvar skal henta åt deim som høyrer til huset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Og Israels-folket gjorde som han sagde, og sanka, sume mykje og sume lite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Men då dei mælte det i kannemålet, gjekk det inkje av for deim som hadde sanka mykje, og det som mindre hadde sanka, leid ingen skort; kvar hadde sanka det han turvte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Og Moses sagde til deim: Ingen må leiva noko av det til morgons.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Men dei høyrde ikkje på Moses, og sume etla att noko til morgonmålet; då kvikna det makk i det, og det stod ei vond tev av det. Og Moses vart vreid på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Sidan sanka dei det morgon etter morgon, kvar etter som han trong til. Men når soli tok til å hita, so bråna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'So hende det sette dagen at dei fann ein gong til so mykje brød som elles, tvo kannor til manns, og alle dei øvste av lyden kom og sagde det med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Då sagde han til deim: «Det er det Herren hev sagt: «I morgon er det kviledag, helgekvild for Herren.» Baka no det de vil, og koka det de vil! Men alt det som vert att, skal de leggja burt og gøyma til morgons.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'So lagde dei det burt til um morgonen, som Moses sagde, og det stod ingen illtev av det, og kom ikkje makk i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Og Moses sagde: «Et det i dag, for i dag er det kviledag for Herren; i dag finn de ikkje noko på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Seks dagar skal de sanka det; men den sjuande dagen er det helg; då er det ikkje å finna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Likevel var det nokre av folket som gjekk ut den sjuande dagen og vilde sanka, men dei fann inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Då sagde Herren til Moses: «Kor lenge skal det vara fyrr de vil lyda bodi og loverne mine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Kom i hug: Herren hev gjeve dykk kviledagen; difor er det at han sette dagen gjev dykk brød for tvo dagar. Haldt dykk no heime, kvar hjå seg! Ingen gange burt frå bustaden sin sjuande dagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Sidan heldt folket seg i ro den sjuande dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Israels-ætti kalla det brødet manna; det liktest korianderfrø; det var kvitt på liten, og smaka som vaflar med honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Og Moses sagde: «Høyr no kva Herren segjer til dykk: «Ein full kanna med manna skal de gøyma, mann etter mann, so etterkomarane dykkar kann sjå det brødet eg gav dykk å eta i øydemarki, då eg fylgde dykk ut or Egyptarlandet!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'So sagde han til Aron: «Tak ei krukka og hav upp i henne ei full kanna med manna, og set det ned for Herrens åsyn, so det vert gøymt frå mann til mann.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Og Aron gjorde som Herren hadde sagt til Moses, og sette det ned framfor lovtavlorne: der skulde det gøymast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Israels-folket åt manna i fyrti år, til dess dei kom til bygde land; manna åt dei alt til dei kom til utenden av Kana’ans-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ei kanna, det var tiandeparten av ei skjeppa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'So tok heile Israels-lyden ut frå Sinheidi, og for dagsleid etter dagsleid, soleis som Herren sagde deim fyre. Sidan lægra dei seg i Refidim; med der fanst det ikkje vatn so folket kunde få drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Og folket trætta med Moses og sagde: «Gjev oss vatn, so me fær drikka!» Då sagde Moses med deim: «Kvi trættar de med meg? Kvi freistar de Herren?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Men folket tyrsta etter vatn, og dei mukka mot Moses og sagde: «Kvi hev du då ført oss burt frå Egyptarland? Vil du då at me og borni våre og feet vårt skal døy av torste?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Då ropa Moses til Herren og sagde: «Kva skal eg gjera med dette folket? Det er ikkje lenge fyrr dei steinar meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Og Herren sagde til Moses: «Far i veg fyre folket! Få med deg nokre av dei øvste i Israel, og staven din som du slo i elvi med, tak den i handi, og gakk so!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Du skal få sjå meg standa midt for augo dine uppyver ei ufs der burte på Horeb; då skal du slå på ufsi, og det skal koma vatn ut or henne, so folket fær drikka.» Moses gjorde som Herren sagde, so dei øvste i Israel såg på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Den staden kalla han Massa og Meriba, av di at Israels-folket trætta med honom, og av di dei freista Herren og sagde: «Er Herren imillom oss eller ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Sidan kom Amalek-mennerne og gav seg i strid med Israel i Refidim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Då sagde Moses til Josva: «Vel oss ut nokre menner, og tak ut og haldt slag med Amalek-heren, so skal eg i morgon standa øvst på haugen med gudsstaven i handi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Josva gjorde som Moses sagde til honom og slost med Amalek-heren, og Moses og Aron og Hur steig upp på høgste haugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Då gjekk det so at når Moses heldt handi i veret, hadde Israel yvertaket, og når han let handi siga, so vann Amalek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Men so tok Moses til å trøytna i henderne; då tok dei ein stein og lagde til rettes for honom; den sette han seg på, og Aron og Hur studde henderne hans, ein på kvar sida. Då heldt han henderne støde alt til soli var gladd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Josva hogg ned Amalek-kongen og folket hans med kvasse sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Og Herren sagde til Moses: «Skriv dette upp i ei bok, so det ikkje gjeng dykk or minne, og lat Josva feste det i hugen at eg vil rydja ut av jordi alt som ber Amalek-namnet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Då bygde Moses eit altar og kalla det: «Herren er hermerket mitt»,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'og han kvad: «Frå Herrens høgsæte ei hand er lyft! Med ufred søkjer han Amalek, ætt for ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Då Jetro, presten i Midjan, verfar åt Moses, fekk spurt alt det som Gud hadde gjort mot Moses og mot Israel, folket sitt: korleis Herren hadde ført Israel ut or Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'so tok han med seg Sippora, kona åt Moses, som Moses hadde sendt heim for ei tid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'og båe sønerne hennar - den eine kalla dei Gersom, «for eg hev fenge heimvist i eit framandt land,» sagde Moses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'og den andre kalla dei Eliezer, «for,» sagde han, «Far min’s Gud var hjelpi mi, og berga meg for sverdet åt Farao» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'og no kom dei, både Jetro, verfar åt Moses, og sønerne og kona hans, til Moses i øydemarki, der han hadde lægret sitt, innmed Gudsfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Og han sende bod til Moses og sagde: «Eg, Jetro, verfar din, kjem til deg med kona di, og båe sønerne sine hev ho med seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Då gjekk Moses til møtes med verfar sin, og bøygde seg for honom, og kysste honom, og dei spurde einannan korleis til stod. So gjekk dei inn i tjeldbudi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'og Moses fortalde verfar sin um alt det Herren hadde gjort med Farao og egyptarane for Israel skuld, og all den møda dei hadde vore uti på vegen, og korleis Herren hadde hjelpt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Og Jetro vart glad for alt det gode som Herren hadde gjort mot Israel, at han hadde berga deim for egyptarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Og Jetro sagde: «Lova vere Herren, som berga dykk for egyptarane og for Farao, han som fria folket ut or trældomen hjå egyptarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'No veit eg at Herren er større enn alle gudar; for det dei tenkte å fella deim med, det gjorde han til ei fella for deim sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Og Jetro, verfar åt Moses, tok slagtefe, og laga til eit brennoffer og offergilde for Gud. Og Aron og alle dei øvste i Israel kom og heldt måltid for Guds åsyn saman med verfar åt Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Dagen etter sat Moses og skifte rett millom folket, og folket stod ikring honom frå tidleg um morgonen til seint på kvelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Då no verfar hans såg alt det han hadde å gjera for deim, so sagde han: «Kva er dette for eit arbeid du legg på deg for folket? Kvi sit du domar åleine, og let heile ålmugen standa uppyver deg frå morgon til kveld?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Jau for folket kjem til meg og vil få vita Guds vilje,» sagde Moses med verfar sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, '«Når dei hev ei sak med kvarandre, kjem dei til meg, og so dømer eg mann og mann imillom, og lærer deim Guds bod og lover.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Då sagde verfar åt Moses med honom: «Det er ikkje klokt det du der gjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'De trøyter dykk ut, både du og dette folket, som er med deg. For dette er for stridt for deg; du vinn ikkje gjera det åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Men høyr no på meg, eg vil leggja deg ei råd, og so vere Gud med deg! Ver du målsmann for folket hjå Gud, og gakk du til Gud med sakerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Og minn dei um bodi og loverne hans, og syn deim kva veg dei skal ganga og korleis dei skal fara åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Vel deg so ut dugande menner av ålmugen, menner som hev age for Gud, truverdige folk, som hatar låk vinning, og set deim til domsmenner, sume yver tusund og sume yver hundrad og sume yver femti og sume yver ti:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'dei skal skifta rett millom folk til kvar tid: alle store saker skal dei koma til deg med, og alle små saker skal dei døma i sjølve. Då lettar du byrdi for deg sjølv, og dei hjelper deg å bera henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Gjer du det, og er det so Guds vilje, so kann både du halda ut, og alt dette folket koma heim til seg i fred og ro.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Moses lydde verfar sin, og gjorde alt det han hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Han kåra ut dugande menner av heile Israel, og sette deim til hovdingar og domsmenner yver folket, sume yver tusund, og sume yver hundrad, og sume yver femti, og sume yver ti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Dei skifte då til kvar tid rett millom folket; alle vande saker kom dei til Moses med, men i alle småsaker dømde dei sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'So baud Moses farvel med verfar sin, og han for heim att til sitt eige land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Trimånadsdagen etter Israels-folket hadde fare frå Egyptarland, kom dei til Sinaiheidi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Dei tok ut frå Refidim, og kom til Sinaiheidi, og der lægra Israel seg i villmarki midt for fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'So steig Moses upp til Gud, og Herren ropa til honom frå fjellet og sagde: «Dette skal du segja til Jakobs-ætti og gjera kunnigt for Israels-folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '«De hev set kva eg gjorde med egyptarane, og korleis eg lyfte dykk på ørnevengjer og bar dykk hit til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Vil de no lyda vel etter ordi mine og halda sambandet med meg, so skal de vera mitt odelsfolk framum alle andre; for heile jordi er mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Og de skal vera meg eit kongerike av prestar og eit heilagt folk.» Desse ordi skal du tala til Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Då Moses kom att, kalla han i hop dei øvste av folket, og bar fram det bodet som Herren hadde sendt honom med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Då svara folket alle som ein: «Alt det Herren hev sagt, skal me gjera.» Og Moses bar svaret deira attende til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Då sagde Herren til Moses: «Høyr her! Eg skal koma til deg i ei tett sky, so folket kann høyra at eg talar med deg; då skal dei tru på deg i al æva.» Då Moses hadde sagt Herren kva folket svara,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'so sagde Herren til honom: «Gakk til folket, og seg dei skal helga seg idag og i morgen og två klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Tridje dagen skal dei halda seg reiduge; for då vil Herren stiga ned på Sinaifjellet for augo åt alt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Og du skal setja ei stengsla for folket rundt ikring, og segja: «Vara dykk og gakk ikkje upp på fjellet, og kom ikkje innåt det! Kvar den som kjem innåt fjellet, skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ingen må taka si hand i honom! Han skal steinast eller skjotast; anten det er folk eller fe, so skal dei lata livet.» Men når dei høyrer hornet ljomar, då må dei stiga upp på fjellet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'So gjekk Moses ned av fjellet til folket, og sagde dei skulde helga seg. Då tvo dei klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Og han sagde til deim: «Tridje dagen lyt de halda dykk reiduge! Kom ikkje nær kvende!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'So var det tridje dagen, med same det ljosna, då bar det laust med toreslått og ljon; på fjellet låg ei tjukk sky, og dei høyrde ein ovsterk lurljod. Då skalv alt folket som i lægret var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Men Moses førde folket ut or lægret, til møtes med Gud, og dei vart standane innunder fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Og heile Sinai stod i ein røyk, av di at Herren for ned på nuten i eld; røyken steig upp som av ein masomn, og heile fjellet dirra og skalv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Og ljurljoden auka og vart sterkare og sterkare: Moses tala, og Gud svara honom lydt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Då Herren hadde stige ned på Sinai, på øvste tinden, so kalla han Moses upp på nuten til seg. Då gjekk Moses upp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'og Herren sagde til honom: «Gakk ned og vara folket, so dei ikkje bryt seg fram til Herren og vil sjå honom; for då kjem mange av deim til å stupa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Og prestarne, som kjem næmare innåt Herren, lyt og helga seg, so Herren ikkje skal fara inn imillom deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Då sagde Moses til Herren: «Folket kann ikkje koma upp på Sinai. For du hev sjølv vara oss og sagt: «Set eit gjerde kring fjellet, og lys det heilagt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Og Herren sagde til honom: «Gakk no berre ned, og kom so upp att, både du og Aron! Men prestarne og ålmugen må ikkje brjota seg fram og stiga upp til Herren; for då kjem han til å fara inn imillom deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'So gjekk Moses ned til folket og sagde det med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Då tala Gud alle desse ordi, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '«Eg er Herren, din Gud, som henta deg ut or Egyptarlandet, or slavehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du skal ikkje hava nokon annan gud attåt meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du skal ikkje gjera deg noko gudebilæte, eller nokor likning av det som er uppi himmelen, eller det som er nedpå jordi, eller det som er i vatnet, nedunder jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du skal ikkje beda til deim, og ikkje skal du tena deim! For eg, Herren, din Gud, er ein streng Gud, som hemnar broti åt federne på borni og barneborni og barnebarns-borni åt deim som hatar meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'men gjer vel imot tusund etter tusund av deim som elskar meg og held bodi mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du skal ikkje nemna namnet åt Herren, din Gud, utan age! For Herren held ikkje den uskuldig som brukar namnet hans vyrdlaust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Kom i hug at du held kviledagen heilag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Seks dagar må du arbeida og gjera alt det du skal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Men den sjuande dagen skal vera ein kviledag vigd åt Herren, din Gud. Då skal du ikkje gjera noko arbeid, korkje du eller son din eller dotter di eller drengen din eller tenestgjenta di eller feet ditt eller den framande som held seg innan portarne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'For i seks dagar skapte Herren himmelen og jordi og havet og alt som i deim er; men den sjuande dagen kvilde han; difor velsigna Herren kviledagen, og lyste honom heilag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, '\'ra far din og mor di, so du fær liva lenge i det landet som Herren, din Gud, gjev deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du skal ikkje drepa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du skal ikkje vera utru mot maken din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du skal ikkje stela!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du skal ikkje vitna rangt imot grannen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du skal ikkje trå etter huset åt grannen din! Du skal ikkje trå etter kona åt grannen din, eller drengen eller tenestgjenta eller uksen eller asnet hans, eller noko anna som høyrer grannen din til».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Og heile folket såg og høyrde toreslagi og eldingarne og lurljoden og røyken av fjellet; og då dei gådde det, skalv dei, og heldt seg langt undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Og dei sagde til Moses: «Tala du med oss, so skal me høyra, men lat ikkje Gud tala med oss; for då døyr me!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Då sagde Moses til folket: «Ver ikkje rædde! Gud vil røyna dykk; difor er det han kjem - og at agen for honom skal bu i hjarto dykkar, so de ikkje syndar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Men folket vart standande langt burte, medan Moses gjekk innåt myrkeskodda, der Gud var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Og Herren sagde til Moses: «So skal du segja til Israels-folket: «De hev høyrt korleis eg tala til dykk frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'De skal ikkje gjera dykk nokon gud attåt meg! Gudar av sylv eller gull skal de ikkje gjera dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Eit altar av torv skal du gjera meg, og på det skal du ofra brennofferi og takkofferi dine, småfeet og storfeet ditt! Kvar den stad som eg vil hava namnet mitt æra, skal eg koma til deg og velsigna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Men gjer du eit steinaltar åt meg, so skal du ikkje byggja det av hoggen stein; for brukar du bitjarn på steinarne, so vanhelgar du deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Heller ikkje skal du stiga upp til altaret mitt etter ei tropp, so du nækjer blygsli di uppyver det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'So er dei retterne du skal leggja fram for deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Når du kjøper ein hebraisk tenestdreng, so skal han tena seks år; i det sjuande skal han sleppa or tenesta for inkje og vera fri mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Var han einsleg då han kom, so skal han og fara sin veg einsleg; var han gift, so skal kona hans vera med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hev han fenge ei kona av husbonden sin, og fær søner eller døtter med henne, so skal kona og borni høyra husbonden til, og sjølv skal han fara sin veg einsleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Men segjer tenaren so: «Eg held av husbonden min og kona mi og borni mine; eg vil ikkje vera fri og fara min veg,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'då skal husbonden føra honom fram for Gud; og leida honom innåt hurdi eller dørskii, og husbonden skal stinga ein syl gjenom øyra hans; sidan skal han tena honom all si tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Når ein mann hev selt dotter si til tenestgjenta, so kann ikkje ho tena seg fri liksom drengjerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Hev husbonden fest henne åt seg sjølv, og so ikkje likar henne, skal han lata henne få kjøpa seg fri; han skal ikkje hava rett til å selja henne til utlendingar, fyrst han ikkje held det han lova henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Men hevhan fest henne åt son sin, so skal ho njota same retten som døtterne hans eigne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Tek han seg ei onnor attåt henne, so skal han ikkje lata den fyrste vanta kost eller klæde eller hjåsvæve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Dersom han ikkje let henne få sin rett i desse tri stykki, so skal ho sleppa fri for inkje; ho skal’kje leggja pengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Den som slær ein mann so han døyr, han skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Men hev han ikkje lege etter honom, og hev Gud laga det so at hin laut falla for handi hans, so skal eg nemna deg ein fredstad som han kann røma til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Når ein mann er so gudlaus at han drep grannen sin med svik, då skal du taka honom, um det so er innmed altaret mitt: han skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Den som slær far sin eller mor si, skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Den som tek ein mann og sel honom eller held honom fanga, skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Den som bannar far sin eller mor si, skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Når tvo trættar, og den eine slær den andre med ein stein eller med neven, og hin ikkje døyr, men vert sengeliggjande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'og sidan kjem upp att, og gjeng ute med stav, då skal den som slo vera saklaus. Men han skal halda den andre skadelaus for den tidi han var ufør til arbeid, og kosta full lækjedom på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Når ein mann slær drengen eller tenestgjenta si med ein stav, so dei døyr under henderne hans, då skal det hemnast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Men liver dei ein dag eller tvo etterpå, so skal det ikkje hemnast; for dei var hans eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Når folk er i hop og slæst, og dei støyter til ei fremmeleg kvinna, so ho fer ille, men ikkje elles fær noko mein, so skal den som gjorde det gjeva i skadebot so mykje som mannen hennar legg på honom, eller og skal dei gjeva det under menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Men er det nokon som fær mein, so skal du gjeva liv for liv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'auga for auga, tonn for tonn, hand for hand, fot for fot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'og taka brune for brune, sår for sår, flengja for flengja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Når ein mann slær drengen sin, eller tenestgjenta si, i auga, so det vert unytt, so skal han til bot for auga gjeva deim frie.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Slær han ut ei tonn på deim, so skal han gjeva deim frie til bot for tonni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Når ein ukse stangar mann eller kona so dei døyr, då skal uksen steinast, og kjøtet må ikkje etast; eigarmannen er saklaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Men hev uksen fyrr vore olm, og eigaren er vara um det, og endå ikkje agtar honom, og han sidan drep mann eller kona, so skal uksen steinast, og eigaren skal og lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Vil dei taka bøter, so skal han gjeva i løysepening for livet sitt so mykje som dei legg på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Stangar uksen svein eller møy, so gjeld same retten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stangar han dreng eller tenestgjenta, so skal eigaren bøta tretti sylvdalar til husbonden deira, og uksen skal steinast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Når ein mann let ein brunn standa open, eller grev ein brunn og ikkje tekkjer yver, og ukse eller asen dett ned i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'då skal den som eig brunnen, gjera lika for det: han skal gjeva den som åtte dyret pengar att i staden, men den daude skrotten skal vera hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Når uksen åt ein mann stangar i hel ein framand ukse, då skal eigarane selja den uksen som liver, og byta pengarne millom seg, og den daude uksen skal dei og byta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Men er det kunnigt at uksen var olm, og eigaren ikkje hev agta honom, so skal han gjeva ein ukse i staden, og sjølv hava den daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Når ein mann stel eit naut eller ein sau, og slagtar eller sel deim, då skal han gjeva fem naut i staden for nautet, og fire sauer for sauen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Vert tjuven teken, medan han bryt seg inn, og slegen so han døyr, so skal det ikkje reknast for manndråp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Men gjeng det fyre seg etter soli hev runne, so vert det ei dråpssak. Tjuven skal gjeva full bot. Eig han ikkje so mykje, so skal han seljast til bot for det han hev stole.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Vert tjuvegodset funne hjå honom, anten det er naut eller asen eller sau, og det endå er livande, so skal han bøta tvo for eitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Når ein mann beiter bøen eller vingarden sin, og slepper feet sitt utyver, so det gjer skade på annan manns eiga, då skal han gjeva i bot det beste som veks på bøen eller i vingarden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Når det kjem upp lauseld og det fatar i eit klungergjerde, og kornskurv eller uskore korn eller heile åkeren brenn upp, då skal den bøta skaden som kveikte elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Når ein mann hev gjeve grannen sin pengar eller eignaluter til gøymings, og det vert stole utor huset det ligg i, då skal tjuven, so sant han vert funnen, tvibøta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Men vert ikkje tjuven funnen, so skal huseigaren ganga fram for Gud og vitna at han ikkje hev rett ut handi si etter det som grannen hans åtte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Kvar gong det gjeld ei tjuvesak, anten det er eit naut eller eit asen eller ein sau eller klæde eller eitkvart anna som er burtkome, og so ein segjer: «Her er det!» då skal dei båe ganga fram for Gud, og den som Gud dømer skuldig, skal bøta tvifaldt til den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Når ein mann hev sett burt eit asen eller eit naut eller ein sau eller noko anna dyr til grannen sin, og det døyr, eller kjem til skade, eller vert rana vitnelaust,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'då skal eiden skilja millom deim: han skal kalla Herren til vitne på at han ikkje hev rett ut handi etter det som grannen hans åtte; den eiden skal eigaren taka for god, og hin skal ingi bot leggja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Men vert det stole frå honom, so skal han gjera eigaren like for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Vert det ihelrive, so skal han syna det fram til prov; skaden skal han ikkje bøta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Når ein mann låner fe av ein annan, og det kjem til skade eller døyr, og eigaren ikkje er med, skal han gjeva full bot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'men er eigaren med, so skal han ikkje bøta. Er det ein leigekar, so gjeng det av på løni hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Når ein lokkar ei møy som ikkje er trulova, og ligg hjå henne, då skal han gjeva henne festargåvor, og taka henne til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Vil ikkje faren lata honom få henne, so skal hin leggja so mange pengar som møyar er vane å få i festargåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Ei trollkjerring skal du ikkje lata liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Kvar den som blandar seg med fe, skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Den som ofrar til avgudarne og ikkje til Herren åleine, han skal vera bannstøytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Dei framande skal du ikkje plåga eller fara hardt med; for de var sjølve framande i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Enkjor og farlause skal de aldri vera harde mot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Er de harde mot deim, og dei ropar til meg, so skal eg visst og sant høyra ropi deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'og harmen min skal loga upp, og eg skal slå dykk med sverdet, so dykkar konor vert enkjor og borni dykkar farlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Låner du nokon av folket mitt, den fatige grannen din, pengar, so skal du ikkje fara som ein okrar med honom; de skal ikkje krevja renta av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Fær du kjolen åt grannen din i vissa, so lat honom få honom att fyre soleglad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'For den er det einaste han hev til å sveipa kring seg; det er det han skal klæda likamen sin med; kva skal han elles liggja i? Og når han ropar til meg, skal eg høyra det; for eg er hjartemild.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Gud skal du ikkje hæda, og ein hovding i folket ditt skal du ikkje banna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Du skal ikkje drygja med å gjeva meg av det som fyller løda di, og som dryp frå vinpersa di. Den frumborne sonen din skal du gjeva meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Det same skal du gjera med nauti dine og småfeet ditt; sju dagar skal frumsungen fylgja mor si; den åttande dagen skal du lata meg få honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Heilage menner skal de vera meg. Kjøt som de finn ihelrivne på marki, skal de ikkje eta; for hundarne skal de kasta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Far ikkje med ljugardrøs! Slå ikkje lag med den som hev ei rang sak, so du vitnar med honom og hjelper uretten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Fylg ikkje flokken i det som vondt er! Tala ikkje soleis på tinget at du hallar etter hopen og rengjer retten!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Um det so er ein arming, so skal du’kje snilda på saki hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Når du finn ein ukse eller eit asen som hev vildra seg burt, og som uvenen din eig, so skal du hava deim attende til honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Når du ser at asnet åt uvenen din hev sige under kløvi, so må du’kje tenkja på å ganga ifrå honom; du lyt hjelpa honom å løysa kløvi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Reng ikkje retten for fatigfolk på tinget!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Haldt deg burte frå alle lygnarsaker, so du ikkje vert skuld i at ein saklaus og rettferdig mann let livet! For den som er skuldig, dømer ikkje eg fri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Tak ikkje mutor! For mutorne synskverver deim som ser klårt, og rengjer saki for dei som hev rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Far ikkje hardt med dei framande! For de veit korleis det er å kjenna seg framand; de var sjølve framande i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Seks år skal du så til jordi di, og hausta det ho ber;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'men det sjuande skal du lata henne liggja og kvila, so dei fatige i landet kann finna noko å liva av, og det som dei leiver, må villdyri eta; sameleis skal du gjera med vingarden din og oljetrei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Seks dagar lyt du gjera arbeidet ditt; men den sjuande dagen skal du halda heilag, so uksen din og asnet ditt kann hava ro, og tenaren din og den framande mannen fær kvila seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Alt det eg hev sagt ifrå um, lyt de vara dykk for! Nokon annan gud må de ikkje nemna! Slikt må du aldri taka på tunga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Tri gonger um året skal du halda høgtid for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Fyrst er det søtebrødhelgi; då skal du i sju dagar eta søtt brød, soleis som eg hev sagt deg, på den tid eg hev sett, i aksmånaden; for då tok du ut frå Egyptarland. Og ingen må visa seg tomhendt for augo mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'So er det skurdhelgi, når du skjer fyrstegrøda av det du sådde på åkeren, og so hausthelgi, når året er ute, og du samlar i hus det du hev avla på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tri vendor um året skal alle karmennerne dykkar møta for Drotten, for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du skal ikkje bera fram blodet av offerdyri mine i hop med brød som er syrt, og feittet av høgtidsofferet mitt må ikkje verta liggjande natti yver, til morgons.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Det aller fyrste av grøda på marki di skal du bera til huset åt Herren, din Gud. Du skal ikkje sjoda kidet i mjølka åt mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Sjå no sender eg ein engel framfyre deg; han skal vara deg på vegen, og fylgja deg fram til den staden som eg hev etla deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Tak deg i vare for honom, og lyd etter ordi hans! Set dykk ikkje upp imot honom! For han vil ikkje tola broti dykkar; i honom er eg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Men lyder du so sant etter ordi hans og gjer alt det eg segjer, so skal eg hata deim som hatar deg, og trengja deim som trengjer deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'For min engel min skal ganga fyre deg, og fylgja deg fram til amoritarne og hetitarne og perizitarne og kananitarne og hevitarne og jebusitarne, og eg vil øyda deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Du skal ikkje tena og ikkje tilbeda gudarne deira! Du skal ikkje gjera som dei gjer, men du skal riva ned avgudarne og slå sund minnesteinarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'De skal tena Herren, dykkar Gud! Då skal han signa både brødet og vatnet for deg, og sott og sykja skal eg venda frå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Det skal ikkje finnast kvende i landet ditt som fer ille eller ikkje er barnkjømd. Du skal få liva alderen ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Fælska for meg skal eg senda fyre deg; alle dei folki du kjem til, skal eg forvilla; eg skal laga det so at alle fiendarne dine syner deg ryggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Ein kvefsesvarm vil eg senda fyre deg; den skal støkkja burt både hevitar og kananitar og hetitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Eg vil ikkje driva deim ut på eitt år; for då kunde landet øydast, og villdyri verta for mange for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Smått um senn vil eg jaga deim ut for deg, til dess du veks til, og tek landet i eige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Og riket ditt det skal rekka frå Sevsjøen til Filistarhavet, og frå Øydemarki+ til Storelvi.++ So gjev eg no i henderne dykkar deim som bur og byggjer i landet, og du skal driva dei ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Aldri må du gjera noko samband med deim eller gudarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Dei må ikkje bu i landet ditt; for då kunde dei lokka deg til å synda mot meg, og tenar du gudarne deira, so vert det deg til ei snara.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Og til Moses sagde han: «Stig upp til Herren, du og Aron, og Nadab og Abihu, og sytti av dei øvste i Israel. Medan de endå er langt undan, skal de kasta dykk å gruve,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'og Moses åleine skal ganga fram til Herren; men dei hine må ikkje ganga fram, og ålmugen må ikkje stiga med honom upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Då Moses kom og bar upp for folket alle Herrens bod og rettar, då svara heile folket med ein munn: «Alle dei ordi som Herren hev gjeve, vil me halda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'So skreiv Moses upp alle Guds bod, og morgonen etter reis han upp i otta, og bygde eit altar innunder fjellet, og reiste tolv minnesteinar for dei tolv Israels-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Sidan sende han ut nokre unge menner av Israels-folket, som skulde laga til brennoffer og slagtoffer, og dei henta uksar og ofra takkoffer til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Og Moses tok helvti av blodet og hadde i bollarne; og den andre helvti skvette han på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'So tok han sambandsboki og las upp for folket, og dei sagde: «Alt det Herren hev sagt, vil me gjera, og vera lyduge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Då tok Moses blodet og skvette på folket, og sagde: «Sjå dette blodet skal bera vitne um det sambandet som Herren hev gjort med dykk, og som er grunna på alle desse bodi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Sidan gjekk dei upp, Moses og Aron og Nadab og Abihu og sytti av dei øvste i Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'og dei såg Israels Gud; under føterne hans var som ein tram av safirhellor, klåre som himmelen sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Og han lyfte ikkje handi mot dei utvalde av Israel; dei skoda Gud, og sidan åt dei og drakk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Og Herren sagde til Moses: «Kom upp til meg på fjellet, og ver her eit bil, so skal eg gjeva deg steintavlorne og lovi og bodi, som eg hev skrive upp og vil læra deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Då gjekk Moses i veg med Josva, fylgjesveinen sin, og Moses steig upp på Gudsfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Og til dei øvste i Israel sagde han: «Ver no her og bia på oss, til me kjem attende! Her er Aron og Hur; dei skal vera hjå dykk. Er det nokon som hev ei sak, so kann han ganga til deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'So steig Moses upp på fjellet, og skyi sveipte seg tett ikring nuten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Herlegdomen åt Herren heldt seg på Sinai, men skyi gøymde nuten i seks dagar. Den sjuande dagen ropa Herren til Moses utor skyi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Og herlegdomen åt Herren var å sjå til for augo åt Israels-folket som ein logande eld på fjelltinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'So gjekk Moses inn i skyi, og steig upp på nuten. Og Moses var på fjellet i fyrti dagar og fyrti næter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '«Seg med Israels-folket at dei skal koma med ei reida til meg! Kvar skal gjeva etter som han hev hjartelag til, og det dei gjev meg, skal de taka imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Gåvorne som de skal taka imot av deim, det lyt vara gull og sylv og kopar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'og purpur og skarlak og karmesin og kvitt lin og geiteragg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'og raudlita verskinn og markuskinn og akazietre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'olje til ljosestaken, kryddor til salvingsoljen og til den angande røykjelsen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'sjohamsteinar og andre dyre steinar til å setja på messehakelen og bringeduken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Og dei skal gjera meg ein heilagdom, so vil eg bu imillom dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Både huset eg skal bu i og all husbunaden skal de i alle måtar gjera etter det bilætet eg vil syna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Dei skal gjera ei kiste av akazietre, halvtridje aln lang og halvonnor aln breid og halvonnor aln høg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Den skal du klæda med skirt gull, både utan og innan skal du gullklæda henne, og gjera ein gullkrans på henne, rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Du skal støypa fire gullringar, og festa deim i dei fire føterne på kista, tvo på den eine sida og tvo på den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'So skal du gjera stenger av akazietre og klæda deim med gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'og smøygja deim inn i ringarne på sidorne av kista; dei skal vera til å bera henne etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Stengerne skal allstødt sitja i ringarne på kista; dei må aldri takast utor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'I den kista skal du leggja lovtavlorne som eg vil gjeva deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'So skal du gjera eit lok av skirt gull, halvtridje aln lang og halvonnor aln breidt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'På endarne av det skal vera tvo kerubar; deim skal du gjera av drive gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Den eine keruben skal vera ytst på den eine enden og den andre ytst på hin enden; i eitt med loket skal de gjera kerubarne, ein på kvar ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Kerubarne skal halda vengjerne utbreidde og upplyfte, so dei tekkjer yver loket med vengjerne sine, og andliti deira skal snu imot einannan: dei skal vende augo mot loket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'So skal du leggja loket på kista, og inni kista skal du leggja lovtavlorne som eg vil gjeva deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Og sidan vil eg møtast med deg der; frå romet yver loket millom båe kerubarne som er ovanpå lovtavlekista, vil eg tala med deg kvar gong eg sender deg med bod til Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'So skal du gjera eit bord av akazietre, tvo alner langt og ei aln breidt og halvonnor aln høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Du skal klæda det med skirt gull, og gjera ein gullkrans på det, rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Ei løvdebreid list skal du gjera rundt um det, og på listi skal du gjera ein gullkrans, som gjeng heilt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'So skal du gjera fire gullringar, og deim skal du setja i dei fire hyrno på dei fire bordføterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Tett uppmed listi skal ringarne sitja; dei skal vera til å smøygja berestenger inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Stengerne skal du gjera av akazietre, og klæda deim med gull; deim er det bordet skal berast i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Sidan skal du gjera dei fati og skålerne som høyrer til bordet, og kannorne og bollarne som de skal skjenkja drykkoffer av; alt dette skal du gjera av skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'På bordet skal du allstødt setja fram skodebrød for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'So skal du gjera ein ljosestake av skirt gull; drive arbeid skal det vera, både hoven og leggen. På staken skal det vera blomar, knuppar og utsprotne blad, og dei skal vera samgjorde med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Seks armar skal greina seg ut ifrå honom, tri på den eine sida og tri på den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'På den eine armen skal det vera tri utsprotne mandelblomar, med knupp og blad, og på den andre armen skal og vera tri utsprotne mandelblomar, med knupp og blad, og soleis på alle dei seks armarne som greinar seg ut ifrå ljosestaken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'På sjølve staken skal det vera fire utsprotne mandelblomar, med knupp og blad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'ein blomsterknupp under dei fyrste tvo armarne, og ein under dei næste tvo armarne, og ein under det tridje paret av dei seks armarne som greinar seg ut ifrå ljosestaken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Både blomsterknupparne og armarne skal vera samsmidde med staken: alt skal vera eitt heilgjort arbeid av drive skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'So skal du gjera lamporne til ljosestaken, sju i talet, og dei skal setjast upp so ljoset fell på den veggen som er midt imot staken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Sakserne og saksplatorne som høyrer til, skal vera av skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Tri vågar skirt gull skal de bruka til ljosestaken og alle desse gognerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Sjå no til at du fær gjort dette etter det bilætet som vart synt deg på fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Huset skal du gjera av ti åklædevever av kvitt tvinna lingarn og purpur og skarlak og karmesin, og i deim skal du veva inn fagre englebilæte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Kvar vev skal vera åtte og tjuge alner lang og fire alner breid: alle veverne skal halda same målet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Fem av veverne skal skøytast i hop til eitt tæpe, og sameleis dei hine fem veverne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'I jaren på den fyrste veven, ytst på det eine tæpet, skal du gjera lykkjor av purpurgarn, og sameleis i jaren på den ytste veven i det andre tæpet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Femti lykkjor skal du gjera på den fyrste veven, og femti lykkjor i jaren på den som høyrer til det andre tæpet; lykkjorne skal svara mot kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Og femti gullkrokar skal du gjera og hekta åklædetæpi i hop, so det vert eit hus av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'So skal du veva ryor av geiteragg til tekkja yver huset; elleve ryor skal du veva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Kvar vev skal vera tretti alner lang og fire alner breid; alle dei elleve veverne skal halda same målet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fem av ryeveverne skal du skøyta i hop til eit tæpe for seg, og dei hine seks til eit anna tæpe, og den sette veven skal du bretta i hop på framsida av taket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'I jaren på den fyrste veven, den som er ytst i det eine tæpet, skal du gjera femti lykkjor, og i jaren på den andre skøytingsveven femti lykkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Og femti koparkrokar skal du gjera, og hekta deim i lykkjorne, og soleis festa raggetæpi i hop, so det vert eitt tak av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Vil du vita kva du skal gjera med det som gjeng av på raggetæpi, so skal helvti av den veven som gjeng av, hanga ned på baksida av huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'og den eine alni på kvar led som raggetæpi er for lange, skal hengjast ned etter båe sideveggjerne, til livd for huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Yver raggetæpi skal du gjera eit tak av raudlita verskinn, og ovanpå det att eit tak av markuskinn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Veggjerne i huset skal du gjera av akazieplankar. Plankarne skal reisast på ende;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'dei skal vera ti alner lange og halvonnor aln breide,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'og på kvar av deim skal det vera tvo tappar med ei tverlist imillom. So skal du gjera med alle plankarne i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Tjuge av dei plankarne du gjer til huset, skal du reisa på solsida, mot sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Og fyrti sylvstabbar skal du gjera og setja under dei tjuge plankarne, tvo under kvar planke, til å festa båe tapparne i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'På den andre sida av huset, på nordsida, skal det og vera tjuge plankar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'med sine fyrti sylvstabbar, tvo under kvar planke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Til baksida av huset, mot vest, skal du gjera seks plankar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'og til hyrno på den same sida tvo plankar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'dei skal vera tviluta alt nedantil, og båe luterne skal halda fullt mål heilt upp åt taket, til den fyrste ringen; so skal dei vera laga båe tvo; dei skal standa i kvar sitt hyrna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Soleis vert det på baksida åtte plankar med sylvstabbarne sine, tvo under kvar planke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'So skal du gjera tverstokkar av akazietre, fem til den eine langveggen på huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'og fem til den andre langveggen, og fem til tverveggen på baksida av huset, mot vest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Midtstokken, den som er midt på plankeveggen, skal ganga langs etter heile veggen, frå ende til ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Plankarne skal du klæda med gull, og ringarne på deim som tverstokkarne ligg i, skal du gjera heiltupp av gull; tverrstokkarne skal du og gullklæda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Du lyt setja upp huset på rette gjerdi, soleis som det vart synt deg på fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'So skal du gjera eit forheng av purpur og skarlak og karmesin og kvitt tvinna lingarn; væne englebilæte skal vera innvovne i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Du skal festa det til fire gullklædde akaziestolpar, som det er gullhakar på, og som stend på fire sylvstabbar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'og so skal du hengja det upp etter krokarne. Innanfor forhenget skal du setja lovtavlekista; og forhenget skal for dykk vera skilnaden millom det heilage og det heilagste romet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'So skal du leggja loket på lovtavlekista, der ho stend i det heilagste romet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Bordet skal du setja utanfor forhenget, og ljosestaken midt imot bordet, innmed den søre veggen i huset; for bordet skal du setja innåt nordveggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Til døri på tjeldet skal du gjera eit tæpe av purpur og skarlak og karmesin og kvitt tvinna lingarn. Det skal vera utsauma med rosor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Du skal gjera fem akaziestolpar til det, og deim skal du gullklæda; dei skal hava hakar av gull, og du skal støypa fem koparstabbar til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Altaret skal du gjera av akazietre, fem alner langt og fem alner breidt: firkanta skal altaret vera, og tri alner høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'På kvart av dei fire hyrno skal du gjera eit horn, og horni skal vera i eitt med altaret. Heile altaret skal du klæda med kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Sidan skal du gjera dei oskefati som høyrer til, og eldskuflerne og blodbollarne og steikjespiti og glodpannorne; alle desse gognerne skal du gjera av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'So skal du laga ei kopargrind til altaret, på gjerd som eit net. På den grindi skal du gjera fire koparringar, ein i kvart hyrna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'og so skal du setja henne under altarskori, nedantil, so ho rekk midt uppå altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'So skal du gjera stenger til altaret. Dei skal vera av akazietre, og du skal klæda deim med kopar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'dei skal smøygjast inn i ringarne, so dei er på båe sidor av altaret, når det vert bore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Altaret skal du gjera av bord; det skal vera holt. Som det vart synt deg på fjellet, so skal det gjerast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'So skal du gjera eit tun kring huset, og det skal vera innegjerdt. På solsida, mot sud, skal du setja ein gard av kvitt linlereft; han skal vera hundrad alner lang på den sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Stolparne i garden og stabbarne dei stend på, skal vera av kopar og tjuge i talet; men hakarne og teinarne som høyrer til, skal vera av sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Sameleis på den nørdre langsida ein lereftsgard som er hundrad alner langt, med tjuge stolpar og stabbar av kopar og hakar og teinar av sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'På den eine tversida av tunet, mot vest, skal du setja ein lereftsgard på femti alner; i den skal det vera ti stolpar, og under deim ti stabbar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'På den andre tversida, den som snur frametter, mot aust, skal tunet og halda femti alner på breiddi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Femtan alner lereftsgard skal det vera på den eine ledi, med tri stolpar og stabbarne som høyrer til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'og på den andre leidi og femtan alner lereftsgard og tri stolpar med kvar sin stabbe;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'og i tunporten skal det vera eit tæpe av purpur og skarlak og karmesin og kvitt tvinna lingarn, tjuge alner breidt og utsauma med rosor; stolparne som det skal festast til og stabbarne dei stend på, skal vera fire i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle stolparne i garden skal vera bundne i hop med sylvteinar; hakarne på deim skal vera av sylv, og stabbarne under deim av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Lengdi på tunet skal vera hundrad alner, og breiddi på båe sidor femti alner. Garden skal vera av kvitt linlereft, og fem alner høgt. Stabbarne til honom skal vera av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Alle arbeidsgognerne i huset, og alle pålarne både til huset og garden skal vera av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Seg no du til Israels-folket at dei skal gjeva deg skir olje av sundstøytte oljeber til ljosestaken, so lamporne kann setjast upp til kvar tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'I møtetjeldet, utanfor tæpet som heng attfor lovtavlorne, skal Aron og sønerne hans stella lamporne, so dei kann lysa for Herrens åsyn frå kveld til morgon; det skal vera ei fast sed hjå Israels-folket, ætt etter ætt, i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'So skal du kalla Aron, bror din, fram or Israels-lyden, både honom og sønerne hans, og setja deim til prestar for meg, Aron, og Nadab og Abihu, og Eleazar og Itamar, sønerne hans Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Og du skal gjera Aron, bror din, heilage klæde, til æra og til prydnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Du skal tala med alle deim som er hage av seg, og som eg hev fyllt med kunstnarånd, og so skal dei gjera den klædebunaden som Aron skal hava på seg, når han vert vigd til prest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Høyr no kva det er for klæde dei skal gjera: ein bringeduk og ein messehakel og ein prestekjole og ein brogdut underkjole og ei huva og eit belte. Det er den heilage klædebunaden dei skal gjera til Aron, bror din, og sønerne hans, so han kann vera presten min,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'og til det skal dei bruka gull og purpur og skarlak og karmesin og kvitt lingarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Messehakelen skal dei gjera av gull og purpur og skarlak og karmesin og kvitt tvinna lingarn. Han skal vera vænt voven,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'og hava tvo aksleband som er feste innåt honom, eitt på kvar ende; dei skal vera til å hekta honom i hop med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Det skal vera ei livgjord på honom, og den skal vera like eins vovi og av same tyet som messehakelen, gull og purpur og skarlak og karmesin og kvitt tvinna lingarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'So skal du taka tvo av sjohamsteinarne; på deim skal du grava inn namni åt Israels-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'seks på kvar stein, etter alderen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'på same måten som dei skjer ut i stein, eller grev ein seglring, skal du grava inn namni åt Israels-sønerne på desse tvo steinarne, og so skal du fella deim inn i fatingar av tvinna gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Båe steinarne skal du setja på akslebandi åt messehakelen, so dei skal minna um Israels-sønerne; og når Aron stend for Herrens åsyn, skal han bera namni åt Israels-sønerne på båe herdarne sine, til ei minning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Sidan skal du gjera sylgjor av tvinna gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Og tvo lekkjor av skirt gull skal du gjera; dei skal vera slyngde på same måten som dei slyngjer snorer. Desse snorlekkjorne skal du festa i sylgjorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'So skal du gjera ein domsbringeduk. Vænt rosa skal han vera, som messehakelen; av gull og purpur og skarlak og karmesin og kvitt tvinna lingarn skal du gjera honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Han skal vera firkanta og tvilagd, ei spann på lengdi og ei spann på breiddi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'og sett med dyre steinar, som stend i fire rader. I ei rad skal vera ein karneol og ein topas og ein smaragd; det er den fyrste radi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'I den andre radi skal vera ein rubin og ein safir og ein beryll,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'og i den tridje radi ein hyacint og ein agat og ein ametyst,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'og i den fjorde radi ein krysolit og ein sjoham og ein jaspis. Dei skal vera innfelte i fatingar av tvinna gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Steinarne skal vera tolv i talet liksom Israels-sønerne, og på kvar stein skal namnet åt ei av dei tolv ætterne vera inngrave som på ein seglring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'So skal du gjera lekkjor av skirt gull, slyngde som snorer, til bringeduken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Og du skal gjera tvo gullringar til honom; deim skal du setja i kvar sitt hyrna på bringeduken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'og dei tvo gullsnorerne skal du festa i dei tvo ringarne som sit i hyrno på bringeduken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Dei hine tvo endarne av båe snorerne skal du festa i dei tvo sylgjorne, og sylgjorne skal du setja på akslebandi åt messehakelen, på framsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'So skal du gjera tvo andre gullringar og setja i dei hine tvo hyrno på bringeduken, på den sida som vender inn imot messehakelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Og endå tvo gullringar skal du gjera og setja på båe akslebandi åt messehakelen, nedantil på framsida, der som han er hekta i hop, ovanfor livgjordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'So skal dei med ei purpursnor binda ringarne på bringeduken til ringarne på messehakelen, so bringeduken sit ovanfor livgjordi og ikkje kann rikkast frå messehakelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Og når Aron gjeng inn i heilagdomen og stend framfor augo åt Herren, då skal han bera namni åt Israels-sønerne innmed hjarta sitt, på domsbringeduken, so Herren all tid skal koma deim i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Inn i domsbringeduken skal du leggja urim og tummim; dei skal liggja innmed hjarta åt Aron, kvar gong han stig fram for Herrens åsyn, so Aron all tid skal bera domen yver Israels-borni på hjarta sitt framfor Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Prestekjolen, som er til å bera under messehakelen, skal du gjera av purpur all igjenom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Midt på honom skal det vera eit halssmog med ei vovi borda ikring, som halssmoget på ei brynja, so han ikkje skal rivna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Rundt ikring falden skal du setja duskar, på gjerd som granateple, av purpur og skarlak og karmesin, og imillom dei gullbjøllor, alt ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'fyrst ei gullbjølla og ein dusk, so ei gullbjølla og ein dusk att, og soleis rundt um heile falden på kjolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Den kjolen skal Aron hava på seg kvar gong han held gudstenesta, so ljoden av honom kann høyrast, når han gjeng inn i heilagdomen og stig fram for Herren, og når han gjeng ut att, so han ikkje skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'So skal du gjera ei spong av skirt gull, og på den skal du grava inn, som på ein seglring, desse ordi: «Vigd åt Herren».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Du skal festa henne i huva med ei purpursnor: framme på huva skal ho sitja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Uppyver skallen hans Aron skal ho sitja, so Aron kann svara for veilorne i dei heilage offeri som Israels-borni vigjer til Herren - alle dei vigde gåvorne som dei ber fram. Ho skal all tid sitja uppyver skallen hans, so dei skal vera velsedde for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'So skal du gjera ein brogdut underkjole av lin, og ei huva av lin, og eit belte med rosesaum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Og til sønerne hans Aron skal du gjera underkjolar, og du skal gjera deim belte, og hovudplagg skal du gjera deim, til æra og til prydnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Med dette skal du klæda Aron, bror din, og sønerne hans, og so skal du salva deim og setja deim inn i embættet og vigja deim til prestar for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'So skal du gjera deim lereftsbrøker til å gøyma blygsli si med: frå mjødmarne og ned på låri skal brøkene nå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Og Aron og sønerne hans skal hava deim på seg, når dei gjeng inn i møtetjeldet eller stig fram åt altaret og held gudstenesta i heilagdomen, so dei ikkje skal føra skuld yver seg og lata livet. Det skal vera ei lov for honom og ætti hans i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Høyr no kva du skal gjera med deim, når du vigjer deim til prestar: Du skal taka ein ung ukse og tvo verar som ikkje hev lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'og so søtt omnsbrød og hellekakor med olje i og tunnbrødleivar som er smurde med olje. Alt dette skal du laga av fint kveitemjøl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Du skal leggja deim i ei korg, og so skal du bera det fram i korgi, og leida fram uksen og verarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Aron og sønerne hans skal du kalla burt åt døri til møtetjeldet og två deim med vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'So skal du taka den heilage klædebunaden, og klæda Aron med underkjolen og prestekjolen, og hava på honom messehakelen og bringeduken, og binda livgjordi um honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'og setja huva på hovudet hans, og den heilage gullspongi i huva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'og du skal taka salvingsoljen og hella ut yver hovudet hans og salva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'So skal du kalla fram sønerne hans, og klæda deim med kjolar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'og spenna beltet um deim, både um Aron og sønerne, og binda hovudplagg på deim, og sidan skal dei hava retten til prestedømet i all æva. So skal du setja Aron og sønerne hans inn i preste-embættet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Du skal leida uksen fram åt møtetjeldet, og Aron og sønerne hans skal leggja henderne på hovudet åt uksen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Og du skal slagta uksen framfor augo åt Herren, i døri til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'So skal du taka noko av blodet og strjuka på altarhorni med fingeren, og alt hitt blodet skal du hella ut innmed altarfoten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Heila netja og den store livreflaga og båe nyro med talgi som er på deim, skal du taka og brenna på altaret, so røyken stig upp imot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Men kjøtet av uksen og hudi og goret skal du brenna upp utanfor lægret. Dette er eit syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'So skal du taka den eine veren, og Aron og sønerne hans skal leggja henderne på hovudet åt veren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Og du skal slagta veren og taka blodet og skvetta rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Sjølve veren skal du lema sund, og innvolen og føterne skal du två og leggja ovanpå lemerne og hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Og so skal du brenna heile veren på altaret, so røyken stig upp imot himmelen; det er eit brennoffer åt Herren, eit eldoffer er det, som stig upp til Herren med kveikjande ange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'So skal du taka den andre veren, og Aron og sønerne hans skal leggja henderne på hovudet åt veren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Og du skal slagta veren og taka noko av blodet og strjuka på den høgre øyresnippen åt Aron og sønerne hans og på den høgre tumarsfingeren og høgre tumarståi deira, og hitt blodet skal du skvetta rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'So skal du taka noko av det blodet som er på altaret og noko av salvingsoljen og skvetta på Aron og klædi hans, og sameleis på sønerne hans og klædi deira, so vert han og klædi hans vigsla, og like eins sønerne hans og klædi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Sidan skal du taka det feitaste av veren, både spælen og netja og den store livreflaga og båe nyro med talgi som er på deim, og so det høgre låret; for dette er ein vigslever.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Og or søtebrødkorgi som stend framfor augo åt Herren, skal du taka eit kakebrød og ei oljekaka og ein tunnbrødleiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Alt dette skal du leggja i henderne på Aron og sønerne hans, og svinga det att og fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Sidan skal du taka det utor henderne deira, og brenna det på altaret i hop med brennofferet, so det kann anga godt for Herren; det er eit eldoffer til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'So skal du taka bringa av vigsleveren åt Aron og svinga henne att og fram for Herrens åsyn; den skal vera din lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Og svingebringa og lyftelåret, det som vert svinga og det som vert lyft av vigsleveren åt Aron og sønerne hans, det skal du lysa heilagt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'det skal vera retten åt Aron og sønerne hans hjå Israels-folket i all æva; for det er ei reida, ei reida som Israels-folket skal gjeva av takkofferi sine, ei reida frå deim til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Den heilage klædebunaden åt Aron skal sønerne hans erva; den skal dei hava på seg når dei vert salva og innsette i embættet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sju dagar skal den av sønerne som vert prest i staden hans, bera denne bunaden, han som gjeng inn i møtetjeldet og gjer tenesta i heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Du skal taka vigsleveren og sjoda kjøtet på ein heilag stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Og kjøtet av veren og brødet som er i korgi, skal Aron og sønerne hans eta i døri til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Dei skal eta det soningsofferet som vert frambore når dei vert innsette i embættet og vigde til prestar. Men framande folk må ikkje eta av det; for det er heilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Og vert noko av vigsleofferkjøtet eller av brødet liggjande til morgons, so skal du brenna det upp. Det må ikkje etast; for det er heilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Soleis er det du skal gjera med Aron og sønerne hans; du skal i alle måtar gjera som eg segjer deg fyre. Sju dagar skal prestevigsla vara,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'og kvar dag skal du ofra ein ung ukse til syndoffer og soning; du skal reinsa altaret for synd, med di du gjer soning for det, og du skal salva det og vigsla det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sju dagar skal du gjera soning for altaret og vigsla det, og då skal altaret vera høgheilagt; kvar den som kjem nær altaret, skal vera vigd til heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Tvo årsgamle lamb skal du dagstødt ofra på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Det eine lambet skal du ofra um morgonen, og det andre soleglads bil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Tiandeparten av ei skjeppa fint kveitemjøl, blanda med ei halvkanna av den finaste beroljen, skal du hava attåt det fyrste lambet, og til drykkoffer ei halvkanna vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Det andre lambet skal du ofra soleglads bil; med same grjonofferet som um morgonen, og same drykkofferet, skal du bera det fram, til ein kveikjande ange, ein rjukande rett for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Det er det brennofferet som de og etterkomarane dykkar dagstødt skal bera fram for Herrens åsyn i døri til møtetjeldet, der som eg vil møtast med dykk og tala til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Der er det eg vil møtast med Israels-borni, og huset skal helgast av herlegdomen min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Både møtetjeldet og altaret vil eg helga, og Aron og sønerne hans vil eg vigja til prestar for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Eg vil bu midt imillom Israels-folket og vera deira Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'og dei skal sanna at eg er Herren, deira Gud, som leidde deim ut or Egyptarlandet, og vil bu millom deim, eg, Herren, deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'So skal du gjera eit altar til å brenna røykjelse på. Av akazietre skal du gjera det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'ei alen langt og ei alen breidt; firkanta skal det vera og tvo alner høgt, og hava horn som er samgjorde med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Du skal klæda det med skirt gull, både ovanpå og rundt ikring på sidorne og på horni, og gjera ein gullkrans på det heilt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Nedanfor kransen på dei tvo sidorne skal du setja tvo gullringar, tvo på kvar sida, dei skal det smøygjast stenger inn i til å bera altaret etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Stengerne skal du gjera av akazietre, og klæda deim med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Dette altaret skal du setja framanfor forhenget som heng attfor lovtavlekista, beint framfor loket som ligg yver lovtavlorne, der som eg vil møtast med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Og Aron skal brenna angande røykjelse på det: kvar morgon når han steller lamporne, skal han brenna røykjelsen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'og det same skal han gjera, når han set upp lamporne i kveldingi. Dette røykofferet skal de og etterkomarane dykkar dagstødt bera fram for Herrens andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'De må ikkje ofra framand røykjelse på det, og ikkje brennoffer eller grjonoffer; heller ikkje må de hella ut drykkoffer på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Ein gong um året skal Aron strjuka blodet av sonings-syndofferet på alterhorni; mann etter mann skal han og etterkomarane hans ein gong um året gjera soning for altaret; då er det høgheilagt for Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '«Når du held manntal yver Israels-folket, so skal alle dei som kjem med i manntalet, gjeva Herren løysepengar for livet sitt med same dei vert talde, so det ikkje skal koma nokor ulukka yver deim for teljingi skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Ein halv dalar i heilag mynt - etter tjuge gera i dalaren - skal kvar gjeva, som kjem med i manntalet. Denne halve dalaren skal vera ei reida til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Alle dei som vert talde, frå tjugeårsalderen og uppetter, skal leggja denne reida til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Dei rike skal ikkje gjeva meir, og dei fatige ikkje mindre enn ein halv dalar, når de legg denne reida åt Herren til løysepengar for livet dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Og du skal taka imot løysepengarne av Israels-folket og bruka deim til gudstenesta i møtetjeldet, so det kann vera ei minning for Herren um Israels-folket og ein løysepening for livet deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '«Du skal gjera ei tvåttebalja av kopar; foten under henne skal og vera av kopar, og du skal setja henne millom møtetjeldet og altaret, og hava vatn i henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Og Aron og sønerne hans skal taka av vatnet, og två henderne og føterne sine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'kvar gong dei gjeng inn i møtetjeldet, skal dei två seg i vatnet, so dei ikkje skal lata livet, og like eins når dei stig fram åt altaret og skal halda gudstenesta og brenna eldoffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Dei skal två hender og føter; elles lyt dei døy. Det skal vera ei lov for honom og ætti hans, mann etter mann, i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Og Herren tala endå meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '«Få deg angande kryddor av dei gjævaste som er: sjølvrunnen myrra, tretti merker, og egte kanelbork, helvti so mykje eller femtan merker, og krydderøyr, femtan merker,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'og kassia, tretti merker, alt etter heilag vegt, og so ein åttung av den finaste beroljen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Av det skal du laga ein heilag salvingsolje, ei kryddemyrsel, soleis som dokterane lagar salve. Ein heilag salvingsolje skal det vera,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'og med den skal du salva møtetjeldet og lovtavlekista');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'og bordet med alt det som til høyrer, og ljosestaken med det som høyrer til honom, og røykofferaltaret');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'og brennofferaltaret med alt det som til høyrer, og balja med foten ho stend på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Du skal vigsla deim, so dei vert høgheilage; kvar den som kjem nær deim, skal vera vigd åt heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Og Aron og sønerne hans skal du salva og vigja til prestar for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Og du skal tala til Israels-folket og segja: «Denne salvingsoljen skal de og etterkomarane dykkar vigja åt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Han må ikkje koma på likamen på kvar manns likam, og de må ikkje laga annan olje som er soleis blanda som denne. Heilag er han, og heilag skal de halda honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Den som lagar maken til denne kryddesalven, eller brukar honom på framande, han skal rydjast ut or folket sitt.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Og endå sagde Herren det til Moses: «Få deg sterke røykjekryddor: myrrakvåda og angeskjel og galban, desse tri kryddeslagi, og so rein angekvåda, like mykje av kvart!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Det skal du gjera røykjelse av, ei kryddeblanding slik som apotekarane lagar, salta, rein, vigsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Noko av det skal du mylja smått og leggja framfor lovtavlorne i møtetjeldet, der som eg vil møtast med deg; høgheilagt skal de halda det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Røykjelse som er soleis blanda som denne, må de ikkje laga åt dykk sjølve; han skal vera vigd åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Den som lagar slik røykjelse til å anga på, han skal rydjast ut or folket sitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '«Sjå no hev eg kåra og kalla Besalel, son åt Uri Hursson, av Juda-ætti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'og fyllt han med guddomsånd, med kunstgivnad og vit og kunnskap og godt lag til alt handverk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'so han kann skapa kunstverk og smida deim ut både i gull og i sylv og i kopar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'og ferda til glimesteinarne som skal fellast inn, og skjera ut i tre, og greida allslags kunstarbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Og til hjelpesmann hev eg gjeve honom Åhåliab, son åt Akhisamak av Dans-ætti, og i alle hage menner hev eg lagt kunstnargåva, so dei kann laga alt det eg hev sagt deg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'møtetjeldet og kista til lovtavlorne, og loket som skal leggjast på henne, og all husbunaden i tjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'bordet med alt som til det høyrer, og gull-ljosestaken med alt det som høyrer til den, og røykjelsealtaret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'og brennofferaltaret med alt som høyrer attåt, og balja med foten under,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'og embætsskrudet, og den heilage klædebunaden åt Aron, presten, og messeklædi åt sønerne hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'og salvingsoljen og den angande røykjelsen til heilagdomen. Dette skal dei i eitt og alt gjera so som eg hev sagt deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Og Herren tala endå meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '«Tala du til Israels-folket og seg: «Gløym no ikkje å høgtida helgarne mine! For det skal vera eit merke på sambandet vårt i alder og æva, so de skal vita at det er eg, Herren, som helgar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Di skal de høgtida kviledagen; han skal vera dykk heilag. Den som vanhelgar honom, skal visst og sant lata livet; kvar mann som då gjer noko arbeid, han skal rydjast ut or ætti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Seks dagar lyt de arbeida og vera onnuge, men den sjuande dagen skal vera ein heilag kviledag, vigd åt Herren. Kvar den som hev noko arbeid fyre seg på um helgi, skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'So skal då Israels-folket koma i hug kviledagen, og halda honom heilag, ætt etter ætt i all æva;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'det skal vera eit ævelegt merke på sambandet millom meg og Israels-folket. For i seks dagar skapte Herren himmelen og jordi, men den sjuande dagen heldt seg roleg og kvilde.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Då han hadde tala til endes med Moses på Sinaifjellet, gav han honom dei tvo lovtavlorne; det var steintavlor som Gud hadde skrive på med fingeren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Då folket såg at Moses drygde med å koma ned av fjellet, so flokka dei seg um Aron, og sagde med han: «Kom, gjer oss ein gud som kann ganga framfyre oss! For me veit ikkje kvar det hev vorte av denne Moses, som fylgde oss ut or Egyptarland.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Då sagde Aron til deim: «Tak gullringarne som konorne og sønerne og døtterne dykkar hev i øyro, og kom til meg med deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Då reiv alt folket gullringarne or øyro sine, og kom til Aron med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Og Aron tok imot gullet, og støypte det um, og laga det med beitelen, so det vart som ein kalv. Då ropa dei: «Dette er guden din, Israel, han som fylgde deg ut or Egyptarland!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Då Aron såg det, bygde han eit altar for honom, og ropa ut: «I morgon er det høgtid for Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Dagen etter reis folket upp i otta, og ofra brennoffer, og bar fram takkoffer; sidan sette dei seg til å eta og drikka, og stod so upp att og gav seg til å leika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Då sagde Herren til Moses: «Skunda deg og gakk ned att! Folket ditt, som du fylgde ut or Egyptarland, hev fare stygt åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Dei var snøgge til å taka utav den vegen eg sagde dei skulde fylgja. No hev dei støypt seg ein gullkalv; den legg dei seg på kne for og ofrar til honom og ropar: «Dette er guden din, Israel, han som førde deg ut or Egyptarland!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, '«Eg hev havt auga med dette folket,» sagde Herren til Moses, «og set at det er eit hardkyndt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Lat meg no få råda, so vil eg sleppa harmen min laus, og gjera ende på deim, og sidan vil eg gjera deg til eit stort folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Men Moses freista å blidka Herren sin Gud og sagde: «Herre, kvi vil du sleppa harmen din laus imot folket ditt, som du hev henta ut or Egyptarlandet med di store magt og di sterke hand?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Skal då egyptarane få det å segja: «Det var ikkje for det gode han fylgde deim ut or landet; han vilde drepa deim i fjelli og rydja deim or verdi»? Døyv harmen som brenn i deg, og legg ned hemntankarne mot folket ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Kom i hug det du lova Abraham og Isak og Israel, tenarane dine, då du svor ved deg sjølv: «Eg vil auka ætti dykkar, so ho vert som stjernorne på himmelen, og heile dette landet som eg hev tala um, det vil eg gjeva etterkomarane dykkar; og dei skal eiga det i all æva.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Då angra Herren at han hadde lova folket sitt vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'So gjekk Moses ned att av fjellet, og i handi hadde han dei tvo lovtavlorne, tavlor som var fullskrivne på båe sidor; alle stader var det skrive på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Og tavlorne dei var Guds eige arbeid, og skrifti ho var Guds eigi skrift, som var inngravi på tavlorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Då Josva høyrde omen av folket som stima og ståka, so sagde han med Moses: «Eg høyrer stridsljod i lægret.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, '«Dette er ikkje fagnadrop frå folk som vinn, og ikkje vådeskrik frå folk som fell; for meg lydest det som mangrøysta song,» svara Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Då dei kom næmare innåt lægret og fekk sjå gullkalven og dansarflokkarne, då vart Moses so harm, at han kasta tavlorne frå seg nedunder fjellet og slo deim sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Og han tok kalven som dei hadde gjort, og kasta honom på elden og mulde honom i smått, og strådde dusti på vatnet, og det let han Israels-folket drikka av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'So sagde han med Aron: «Kva vondt hev dette folket gjort deg, sidan du laut føra deim upp i so stor ei synd?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, '«Ver ikkje vreid på meg, herre bror!» svara Aron. «Du veit kor gjenomvondt det er, dette folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Dei sagde med meg: «Gjer oss ein gud som kann ganga framfyre oss! For me veit ikkje kvar det hev vorte av denne Moses, han som fylgde oss ut or Egyptarland.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Då sagde eg til deim: «Den som hev noko gull på seg, lyt taka det av seg!» So gav dei meg gullet, og eg kasta det i elden; då kom denne kalven fram.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Då Moses såg at folket var agelaust - for Aron hadde mist agen yver deim, til spott for fiendarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'so gjekk han fram i lægerporten, og ropa: «Hit til meg alle Herrens menner!» Då flokka heile Levi-ætti seg um honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'og han sagde til deim: «So segjer Herren, Israels Gud: «Spenn sverdet på dykk, alle mann! Gakk att og fram i lægret, frå port til port, og hogg ned for fote, både brør og vener og frendar!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Levi-sønerne gjorde som Moses sagde, og den dagen fall det av folket ikring tri tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'For Moses sagde: «I dag lyt de vigja dykk åt Herren, um det so er med blodet av sønerne og brørne dykkar; so skal han i dag gjeva dykk si velsigning!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Dagen etter sagde Moses med folket: «De hev gjort ei stor synd. No vil eg stiga upp til Herren og beda um nåde for dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'So gjekk Moses attende til Herren og sagde: «Ai ei, dette folket hev gjort ei stor synd: dei hev laga seg ein gud av gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Å gjev du kunde gløyma syndi deira! Kann du ikkje, so strjuk meg ut or boki di som du skriv i!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Då sagde Herren til Moses: «Den som syndar mot meg, honom stryk eg ut or boki mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Gakk no du, og fylg folket dit som eg hev sagt deg! Sjå, engelen min skal ganga framfyre deg. Men når min time kjem, vil eg heimsøkja deim for syndi deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Og Herren førde ulukka yver folket for di dei hadde gjort kalven, den som Aron laga åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Sidan sagde Herren til Moses: «Tak ut herifrå, både du og det folket du fylgde ut or Egyptarland, og far til det landet som eg lova Abraham og Isak og Jakob då eg sagde: «Di ætt vil eg gjeva det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'og eg vil senda ein engel framfyre dykk og driva ut kananitarne, både amoritar og hetitar og perizitar, hevitar og jebusitar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Far til det landet som fløymer med mjølk og honning! Men eg vil ikkje vera i fylgje med deg; for de er eit hardkyndt folk! eg kunde koma til å gjera av med dykk på vegen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Då folket høyrde desse harde ordi, vart dei sorgfulle, og ingen tok på seg høgtidsbunaden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'For Herren sagde til Moses: «Seg til Israels-folket: «De er eit hardlyndt folk! fylgdest eg med dykk um det var aldri so lite bil, so laut eg gjera ende på dykk. Men tak no av dykk høgtidsskrudet, so skal eg sjå kva eg kann gjera for dykk!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Då reiv Israels-folket av seg høgtidsskrudet, og bar det ikkje meir etter dei hadde teke ut ifrå Horeb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moses tok jamleg og sette upp tjeldet for honom utanfor lægret, eit godt stykke ifrå; han kalla det møtetjeldet, og alle som vilde finna Herren, gjekk ut til møtetjeldet, som var utanfor lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Og kvar gong Moses gjekk ut til tjeldet, so reiste alt folket seg, og stod, kvar i døri til si tjeldbud, og såg etter Moses, til han var komen åt tjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Og når Moses gjekk inn i tjeldet, då kom skystopulen ned og stod i tjelddøri, og han tala med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Og heile folket såg skystopulen, som stod i døri til møtetjeldet. Då reiste dei seg alle saman, og lagde seg på kne, kvar i døri til si tjeldbud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Og Herren tala med Moses, andlit mot andlit, som ein mann talar med grannen sin. Sidan gjekk Moses attende til lægret; men Josva, Nunssonen, som var fylgjesveinen hans og gjekk honom til handa, heldt seg allstødt inni møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Og Moses sagde til Herren: «Sjå, du segjer det til meg; «Fylg dette folket fram!» men eg fær ikkje vita kven du vil senda med meg, og du hev då sjølv sagt: «Eg kjenner deg vel, og eg hev fenge godvilje for deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Kjære væne, hev du godvilje for meg, so syn meg då vegarne dine, so eg kann læra å kjenna deg, og vera deg til lags! Og kom so i hug at dette er ditt eige folk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Då sagde Herren til honom: «Når eg sjølv gjeng med, kann du då slå deg til tols?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, '«Gjeng du ikkje sjølv med, so lat oss ikkje fara herifrå!» svara Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, '«Kann då nokon vita at du hev godvilje for meg og for folket ditt, utan du gjeng med oss, so eg og folket ditt vert æra framfor alle folkeslag i heile verdi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Då sagde Herren til Moses: «Det du bed um, skal eg nok gjera; for eg likar deg godt, og kjenner deg for den mann du er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, '«Kjære deg, lat meg få sjå herlegdomen din!» sagde Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Og han svara: «Eg skal fara fram midt for andlitet ditt i fagraste hamen min, og ropa Herrens namn med det same eg fer framum deg, og eg skal vera so mild som eg kann, og spara so mange som eg kann;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'men», sagde han, «du kann ikkje få sjå andlitet mitt; for inkje menneskje som ser meg, kann liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Sjå her innmed meg på berget er eit rom,» sagde Herren, «der kann du standa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'og når herlegdomen min fer framum, so skal eg setja deg i denne bergskori, og halda handi mi yver deg, til dess eg hev kome framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Då skal eg taka handi mi burt att; so kann du sjå meg attantil; men andlitet mitt fær ingen sjå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'So sagde Herren til Moses: «Hogg deg ut tvo steintavlor liksom dei fyrste, so skal eg på deim skriva dei same ordi som stod på dei fyrste tavlorne, deim du slo sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Haldt deg so ferdig til i morgon tidleg! Då skal du stiga upp på Sinaifjellet, og venta på meg der, på fjelltinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Ingen må vera med deg upp, og ingen må syna seg på heile fjellet; heller ikkje må naut eller sauer beita uppunder dette fjellet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'So hogg Moses ut tvo steintavlor liksom dei fyrste, og dagen etter reis han upp i otta, og gjekk upp på fjellet, som Herren hadde sagt honom til, og hadde båe steintavlorne i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Då steig Herren ned i skyi, og Moses gjekk innåt, og ropa Herren på namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Då for Herren fram midt for augo hans og ropa: «Det er Herren! Herren er ein mild og kjærleg Gud, tolug og full av nåde og truskap!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Han let si miskunn vara i tusund mannsaldrar; han tilgjev brot og misgjerning og synd; men han vil ikkje at den skuldige skal vera strafflaus: han hemner broti åt federne på borni og barneborni, ja på barnebarns-borni og borni etter deim att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Då kasta Moses seg snøgt å gruve og bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, '«Å Herre,» sagde han, «hev du noko godvilje for meg, so gjer vel og gakk med oss! Um dette er eit hardkyndt folk, so tilgjev broti og synderne våre, og lata oss vera din eigen lyd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Og han svara: «Ja, eg vil gjera eit samband med deg; midt for augo åt heile folket ditt vil eg gjera slike under at det aldri hev vore set maken på heile jordi eller hjå noko folkeslag, og heile det folket du bur imillom, skal sjå Herrens verk, kor ageleg det er, og kor store ting eg skal gjera for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Kom no i hug det eg segjer med deg i dag! Sjå no vil eg jaga amoritarne og kananitarne og hetitarne og perizitarne og hevitarne og jebusitarne: dei skal røma for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Agta deg då so du ikkje gjer noko samband med deim som bur i det landet du kjem til! For bur dei imillom dykk, so kunde dei verta ei snara for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'De skal riva ned altari deira og slå sund minnesteinarne og hogga dei heilage trei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Du skal ikkje beda til nokon annan gud; for Herren heiter den Strenge; han er ein streng Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Aldri må du gjera noko samband med deim som bur der i landet. For når dei held seg med gudarne sine og blotar til deim, so vil dei beda deg til seg, og du vil eta av blotmaten deira;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'du vil gifta sønerne dine med døtterne deira, og dei vil halda seg med gudarne sine og lokka sønerne dine til å gjera det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Gjer deg ikkje støypte gudebilæte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Søtebrødhelgi skal du halda: sju dagar skal du eta søtt brød, so som eg hev sagt deg, på den tid eg hev sett, i aksmånaden; for i aksmånaden tok du ut frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alt som kjem fyrst frå morsliv, skal høyra meg til, alt bufeet ditt som er han av slaget og som fell fyrst undan naut eller sau.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Det fyrste fylet som fell undan eit asen, skal du løysa med eit lamb eller kid, og løyser du det ikkje, so skal du brjota nakken på det. Kvart sveinbarn i ætti di som er frumbore, skal du løysa. Og ingen må lata seg sjå tomhendes for augo mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Seks dagar lyt du arbeida, men den sjuande dagen skal du kvila; um det so er i våronni eller skurdonni, so skal du kvila den sjuande dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Sjuvikehelgi skal du halda når du tek inn fyrstegrøda av kveitehausten, og hausthelgi når året er utrunne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tri gonger um året skal alle karfolki dine møta for Drotten, for Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'For eg vil driva ut heile folkeslag der du fer fram, og vidka ut riket ditt, og ingen skal trå etter landet ditt medan du fer upp og møter for Herren, din Gud - tri vendor um året.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du skal ikkje bera fram blodet av offerdyri mine attåt syrt brød, og ikkje må påskehelgofferet verta liggjande natti yver, til morgondagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Det allerfyrste av grøda på marki di skal du bera til huset åt Herren, din Gud. Du skal ikkje sjoda kidet i mjølki åt mor si.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Og Herren sagde til Moses: «Skriv no du upp desse ordi! For etter desse ordi vil eg gera eit samband med deg og med Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Han var der hjå Herren, fyrti dagar og fyrti næter, og ikkje åt han og ikkje drakk han. Og Herren skreiv sambandslovi, dei ti bodordi, på tavlorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'So gjekk Moses ned av Sinaifjellet med dei tvo lovtavlorne i handi, og då han kom ned, stråla og skein det av andlitet hans, av di at Gud hadde tala med honom, men sjølv visste han det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Og Aron og heile Israels-folket såg at det skein av andlitet hans Moses, og dei torde ikkje ganga innåt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Då ropa Moses på deim, og so kom Aron og alle dei øvste av lyden hit til honom, og Moses tala med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Sidan kom alt Israels-folket burtåt, og han bar fram alle dei bodi som Herren hadde gjeve honom på Sinaifjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Og då Moses hadde sagt deim alt det han skulde, lagde han eit slør for andlitet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Men når han gjekk fram for Herrens åsyn og skulde tala med honom, tok han sløret burt, til han skulde ut att; so kom han ut og tala til Israels-folket det han var fyresagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Då såg Israels-folket korleis det stråla av andlitet hans Moses, og Moses hadde sløret for andlitet att, til dess han skulde inn og tala med Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Og Moses kalla i hop heile Israels lyden, og sagde med deim: «Høyr no kva Herren vil de skal gjera:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Seks dagar lyt de arbeida og vera onnuge, men den sjuande dagen skal de halda heilag; han skal vera ein kviledag, vigd åt Herren. Kvar den som då gjer noko arbeid, skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ingen av dykk må kveikja upp eld i huset sitt på kviledagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Og endå sagde Moses med heile Israels-lyden: «Høyr no kva Herren segjer og vil:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, '«Tak ut ei reide til Herren av det som de eig! Alle som hev hjartelag til å gjeva noko, lyt koma med det, med reida til Herren: gull og sylv og kopar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'og purpur og skarlak og karmesin og kvitt lingarn og geiteragg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'og raudlita verskinn og markuskinn og akazietre');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'og olje til ljosestaken og kryddor til salvingsoljen og til den angande røykjelsen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'og sjohamsteinar og andre dyre steinar til å setja på messehakelen og bringeduken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Og dei av dykk som hev kunstgivnad, skal koma og gjera alt det som Herren hev sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'huset med raggetæpi og taket og krokarne og plankarne og tverstokkarne og stolparne og stabbarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'kista og stengerne som ho skal berast etter, og kisteloket og forhengtæpet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'bordet med berestengerne og alt anna som til høyrer, og skodebrødi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den skinande ljosestaken med det som høyrer til, og lamporne og oljen til ljosestaken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'røykjelsealtaret med berestengerne, som høyrer attåt, og salvingsoljen og den angande røykjelsen, og dørtæpet til husdøri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'brennofferaltaret med kopargrindi og berestengerne og alt anna som høyrer til, balja med foten under,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'lereftsgarden, som skal vera kring tunet, med stolparne som høyrer attåt, og stabbarne som dei skal standa på, og tæpet til tunporten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'pålarne til huset og til lereftsgarden og togi som skal bindast i deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'embætsskrudet til tenesta i heilagdomen, den heilage klædebunaden åt Aron, presten, og presteklædi til sønerne hans.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'So gjekk heile Israels-lyden burt frå Moses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'og sidan kom dei, so mange som hjarta mana og hugen dreiv, og bar fram reidor åt Herren til arbeidet på møtetjeldet og til all tenesta der og til dei heilage klædi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Dei kom både menner og kvende, alle som hjarta dreiv, og hadde med seg allslags gull: spenne og øyreringar og fingerringar og kulelekkjor; og sameleis kom alle dei som vilde vigja eit gulloffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Og alle som hadde purpur eller skarlak eller karmesin eller kvitt lingarn eller geiteragg eller raudlita verskinn eller markuskinn, dei kom med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Alle som vilde gjeva ei sylvreida eller ei koparreida, kom til Herren med reida si, og alle som hadde akazietre til noko av det som skulde arbeidast, dei kom med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Kvar ei kona som skyna seg på sovore arbeid, spann med sine eigne hender, og kom med spunen: purpur og skarlak og karmesin og kvitt lingarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Og alle kvende som hadde hug og dug til det, spann geiteragget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Hovdingarne kom med sjohamsteinar og andre dyre steinar til å setja på messehakelen og bringeduken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'og med kryddor og olje til ljosestaken og til salvingsoljen og den angande røykjelsen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Kvar mann og kona av Israels-folket som hjarta dreiv til å hjelpa til med det store verket som Herren hadde sett Moses til å gjera, dei kom viljugt med ei gåva til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'So sagde Moses til Israels-folket: «Høyr her! Herren hev kåra og kalla Besalel, son åt Uri Hursson, av Juda-ætti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'og fyllt honom med guddomsånd, med kunstgivnad og vit og kunnskap og godt lag til alt handverk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'so han kann emna til fagre ting og smida deim ut i gull og i sylv og i kopar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'og ferda til glimesteinarne som skal setjast på presteskrudet, og skjera ut i tre, og greida allslags kunstarbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Og gåva til å læra frå seg hev han lagt både i honom og Åhåliab, son åt Akhisamak, av Dans-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Han hev fyllt deim med kunstnarånd, so dei kann både smida og snikra, og gjera åklæde med innvovne bilæte og rosor av purpur og skarlak og karmesin og kvitt lingarn, og veva kva dei vil, alt arbeid kann dei greida, og kunstverk kann dei skapa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Og Besalel og Åhåliab og alle dei andre kunstnarane, som Herren hadde gjeve vit og kunnskap, so dei veit korleis kvar ting skal gjerast, dei skal då laga til alt som skal arbeidast åt heilagdomen, etter det som Herren hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'So kalla Moses til seg Besalel og Åhåliab og alle hage menner som hadde fenge kunstnargåva frå Herren, alle som hugen dreiv til å taka fat på verket og fullføra det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Og dei fekk hjå Moses alt tilfanget til det som skulde arbeidast åt heilagdomen, alle dei gåvorne som Israels-borni var kome med. Men folket bar av seg sjølve nye gåvor til honom kvar morgon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Og alle dei meistrarne som stod fyre alt arbeidet på heilagdomen, kom ein for ein til Moses frå arbeidet sitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'og sagde: «Folket kjem med mykje meir enn me treng til det verket som Herren vil ha gjort.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Då let Moses ropa ut yver heile lægret: «Anten det er mann eller kvende, so tarv ingen syta for fleire gåvor til heilagdomen!» So let folket vera å koma med meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Men det vyrket som var frambore var nok, og meir enn nok, til alt arbeidet som skulde gjerast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'So tok då alle dei hagaste handverkararne til å arbeida på gudshuset. Dei gjorde det av ti åklædevever av kvitt tvinna lingarn og purpur og skarlak og karmesin, og i deim var det innvove fagre englebilæte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Kvar vev var åtte og tjuge alner lang og fire alner breid; alle veverne heldt same målet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Fem av veverne skøytte dei i hop til eit tæpe, og like eins dei hine fem veverne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'I jaren på den fyrste veven, ytst på det eine tæpet, gjorde dei lykkjor av purpurgarn, og sameleis i jaren på den ytste veven i det andre tæpet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Femti lykkjor sette dei på den fyrste veven, og femti lykkjor i jaren på den som høyrde til det andre tæpet, soleis at lykkjorne svara mot kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Og femti gullkrokar gjorde dei og hekta åklædetæpi i hop med, so det vart eitt hus av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'So vov dei ryor av geiteragg til tekkja yver huset; elleve ryor vov dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Kvar vev var tretti alner lang og fire alner breid; alle dei elleve veverne heldt same målet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Fem av ryeveverne skøytte dei i hop til eit tæpe for seg, og dei hine seks til eit anna tæpe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'I jaren på den ytste veven i det eine tæpet gjorde dei femti lykkjor, og i jaren på den andre skøytingsveven femti lykkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Og femti koparkrokar gjorde dei til å festa raggetæpi i hop med, so det skulle verta eit tak av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Sidan gjorde dei eit tak av raudlita verskinn til å leggja yver raggetæpi, og eit tak av markuskinn til å leggja ovanpå det att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'So gjorde dei plankarne til husveggjerne. Dei var av akazietre, og vart reist på ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Ti alner lange var dei og halvonnor aln breide,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'og på kvar planke var der tvo tappar med ei tverlist imillom. So gjorde dei med alle plankarne til huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Tjuge av dei plankarne som dei gjorde til huset, var etla åt solsida, sudsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Og fyrti sylvstabbar gjorde dei til å setja under desse tjuge plankarne, tvo stabbar under kvar planke, so båe tapparne kunne festast i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Til den andre sida av huset, nordsida, gjorde dei og tjuge plankar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'med sine sylvstabbar, tvo til kvar planke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Til baksida av huset, vestsida, gjorde dei seks plankar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'og til hyrno på den same sida, tvo plankar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'dei var tviluta alt nedantil, og båe luterne held fullt mål heilt upp åt taket, til den fyrste ringen. So gjorde dei med båe tvo, med båe hyrnoplankarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Soleis kom det på baksida åtte plankar med sine sylvstabbar, sekstan sylvstabbar, tvo til kvar planke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'So gjorde dei tverstokkar av akazietre, fem til den eine langveggen på huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'og fem til den andre langveggen, og fem til tverveggen på baksida av huset, mot vest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Og midstokken laga dei so at ho skulde ganga tvert yver frå ende til ende, midt etter plankeveggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Plankarne klædde dei med gull, og ringarne på deim, som tverstokkarne skulde liggja i, gjorde dei heiltupp av gull. Tverstengerne klædde dei og med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'So gjorde dei forhenget. Det var av purpur og skarlak og karmesin og kvitt tvinna lingarn; væne englebilæte vov dei inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Dei gjorde fire akaziestolpar til å hengja det på, og klædde deim med gull; hakarne på deim var av gull, og dei støypte fire sylvstabbar til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Til tjelddøri gjorde dei eit tæpe av purpur og skarlak og karmesin og kvitt tvinna lingarn. Det var utsauma med rosor;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'dei gjorde fem stolpar til det, med hakarne som høyrde attåt, og klædde stolpehovudi og teinarne med gull; og dei fem stabbarne som høyrde til, gjorde dei av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'So gjorde Besalel kista; ho var av akazietre, halvtridje aln lang og halvonnor aln breid og halvonnor aln høg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Han klædde henne med skirt gull både innan og utan, og gjorde ein gullkrans på henne rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Og han støypte fire gullringar, som han feste i dei fire føterne på kista, tvo på den eine sida og tvo på den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'So gjorde han stenger av akazietre, og klædde deim med gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'og smøygde deim inn i ringarne på sidorne av kista, til å bera henne etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'So gjorde han eit lok av skirt gull, halvtridje aln lang og halvonnor aln breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'På endarne av det gjorde han tvo kerubar; av drive gull gjorde han deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'den eine keruben ytst på den eine enden og den andre ytst på hin enden; i eitt med loket gjorde han kerubarne, ein på kvar ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Kerubarne heldt vengjerne utbreidde og upplyfte, so dei tekte yver loket med vengjerne sine, og andliti deira snudde mot kvarandre; dei vende augo mot loket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'So gjorde han bordet; det var av akazietre, tvo alner langt og ei aln breidt og halvonnor aln høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Han klædde det med skirt gull, og gjorde ein gullkrans på det, rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Ei løvdebreid list gjorde han rundt um det, og på listi sette han og ein gullkrans, som gjekk heilt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'So støypte han fire gullringar og sette i hyrno på dei fire bordføterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Ringarne sat tett uppmed listi; dei var til å smøygja berestenger inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Stengerne gjorde han av akazietre, og klædde deim med gull; deim var det bordet skulde berast etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'So gjorde han dei kjeraldi som skulde setjast på bordet, fati og skålerne som høyrde til, og bollarne og kannorne som skulde skjenkjast drykkoffer av, alt av skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'So gjorde han ljosestaken; den var av skirt gull, og drive arbeid var det, både hoven og leggen. På staken var det blomar, med knuppar og utsprotne blad, og dei var samgjorde med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Seks armar greina seg ut ifrå honom, tri på den eine sida og tri på den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'På den eine armen var det tri utsprotne mandelblomar, med knupp og blad, og på den andre armen var og tri utsprotne mandelblomar, med knupp og blad, og soleis på alle dei seks armarne som greina seg ut ifrå ljosestaken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'På sjølve staken var det fire utsprotne mandelblomar, med knupp og blad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'ein blomsterknupp under dei fyrste tvo armarne, og ein under dei næste tvo armarne, og ein under det tridje paret av dei seks armarne som greina seg ut ifrå ljosestaken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Både blomsterknupparne og armarne var samsmidde med staken; alt var eit heilgjort arbeid av drive, skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Sidan gjorde han lamporne til ljosestaken, sju i talet, og sakserne og saksplatorne som høyrde til, alt av skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Tri vågar skirt gull bruka han til ljosestaken og alle desse gognerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'So gjorde han røykjelsealtaret av akazietre, ei aln langt og ei aln breidt, firkanta, og tvo alner høgt. Horni på det var i eitt med sjølve altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Han klædde det med skirt gull, både ovanpå og rundt ikring på sidorne og på horni, og gjorde ein gullkrans på det, heilt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Nedanfor kransen på dei tvo sidorne sette han tvo gullringar, tvo på kvar sida, til å smøygja stenger inn i som altaret skulde berast etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Stengerne og gjorde han av akazietre, og klædde deim med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'So laga han den heilage salvingsoljen og den reine, angande røykjelsen på same måten som apotekarane gjer det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'So gjorde han brennofferaltaret av akazietre, fem alner langt og fem alner breidt, firkanta, og tri alner høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'På kvart av dei fire hyrno gjorde han eit horn, og horni var i eitt med altaret. Heile altaret klædde det med kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Sidan gjorde han alle gognerne som høyrde til altaret: fati og eldskuflerne og blodbollarne og steikjespiti og glodpannorne; alle desse gognerne gjorde han av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'So laga han ei kopargrind til altaret på gjerd som eit net; den sette han under altarskori, nedantil, so ho rakk midt uppå altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Og han støypte fire ringar og sette i dei fire hyrno på kopargrindi, til å smøygja stenger inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Stengerne gjorde han av akazietre, og klædde deim med kopar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'og so smøygde han deim inn i ringarne på sidorne av altaret, so det kunde berast etter deim. Altaret gjorde han av bord, so det var holt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'So gjorde balja med foten under av kopar. Til det bruka han speglarne åt dei kvendi som gjorde tenesta i døri til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'So emna han til gjerde kring tunet: Til solsida, den sida som snudde mot sud, gjorde han ein gard av kvitt linlereft, hundrad alner lang,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'og til den tjuge stolpar, med tjuge koparstabbar og hakar og teinar av sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Til nordsida gjorde han og ein lereftsgard som var hundrad alner lang, og tjuge stolpar med kvar sin koparstabbe og hakar og teinar av sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Til vestsida gjorde han ein lereftsgard på femti alner med ti stolpar, og til deim ti stabbar og sylvhakar og sylvteinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Til framsida, austsida, som og var femti alner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'gjorde han femtan alner lereftsgard til den eine leidi, med tri stolpar og stabbarne som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'og til den andre leidi, både til den eine og den andre sida åt tunporten, femtan alner lereftsgard og tri stolpar med kvar sin stabbe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Heile garden rundt ikring tunet var av kvitt linlereft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Stabbarne som stolparne skulde standa på, var av kopar, men hakarne og teinarne var av sylv, og like eins ålaget på stolpehovudi. Dei var bundne i hop med sylvteinar, alle gardstolparne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Tæpet til tunporten var utsauma med rosor av purpur og skarlak og karmesin og kvitt tvinna lingarn. Det var tjuge alner langt, og fem alner høgt, etter vevbreiddi, liksom tungarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Stolparne det skulde hanga på, var fire i talet, og sameleis stabbarne som høyrde til. Stabbarne var av kopar. Hakarne var av sylv. Ålaget på stolpehovudi og teinarne var og av sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Alle pålarne til huset og til garden rundt ikring var av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'No skal de høyra kor mykje det gjekk med til huset, til det huset som gøymde Guds lov; for Moses sette Levi-sønerne til å rekna det yver, og Itamar, son åt Aron, presten, stod fyre rekningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Men Besalel, son åt Uri Hursson, av Juda-ætti, var den som gjorde alt det som Herren hadde tala til Moses um,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'og i lag med honom Åhåliab, son åt Akhisamak, av Dans-ætti, ein meister til å smida og snikra og veva åklæde med bilæte og rosor av purpur og skarlak og karmesin og kvitt lingarn -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alt gullet som vart bruka til det som skulde arbeidast åt heilagdomen, heile gullmengdi som vart gjevi i offergåva, var ni og tjuge talentar og fem og fyrti merker og ti lodd, etter heilag vegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Og sylvet som kom inn då dei heldt manntal yver lyden, det var hundrad talent og hundrad og ti merker og femtan lodd etter heilag vegt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'ein beka eller eit halvt lodd etter heilag vegt for kvar mann som kom med i manntalet, frå tjugeårsalderen og uppetter, og det var seks hundrad og tri tusund og fem hundrad og femti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Dei hundrad talenti med sylv vart bruka til å støypa stabbarne til heilagdomen og forhenget, hundrad stabbar av dei hundrad talenti; det gjekk med eitt talent til kvar stabbe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Og dei hundrad og ti merkerne og femtan loddi bruka dei til hakar på stolparne og ålag yver deim og til teinar som skulde binda deim i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Koparen som vart gjeven i offergåva, var sytti talent og hundrad og femti merker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Av den gjorde dei stabbarne til møtetjelddøri, og koparaltaret med kopargrindi som høyrer til, og alle altargognerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'og stabbarne til garden rundt ikring tunet, og stolparne til tunporten, og alle pålarne til huset og garden rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Av purpuret og skarlaket og karmesinet gjorde dei embætsskrud til tenesta i heilagdomen og laga den heilage klædbunaden åt Aron, soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Messehakelen gjorde dei av gull og purpur og skarlak og karmesin og kvitt tvinna lingarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Dei hamra gullet ut i plator og klypte det upp til tråd, so det kunde virkast inn i purpuret og skarlaket og karmesinet og det kvite lingarnet med kunstvevnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'So gjorde dei aksleband til å festa innåt messehakelen; med deim vart han hekta i hop på båe endarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Livgjordi som var på messehakelen og skulde spennast um honom, var like eins vovi og av same tyet - av gull og purpur og skarlak og karmesin og kvitt tvinna lingarn - soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'So ferda dei til sjohamsteinarne, og felte deim inn i fatingar av tvinna gull. Namni åt Israels-sønerne var inngravne på deim som på ein seglring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'og dei vart sette på akslebandi åt messehakelen til minna um Israels-sønerne, soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'So gjorde dei bringeduken. Han var vænt rosa liksom messehakelen, med gull og purpur og skarlak og karmesin og kvitt tvinna lingarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Firkanta gjorde dei bringeduken og tvilagd; ei spann på lengdi og ei spann på breiddi var han, og tvilagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Og fire rader med dyre steinar sette dei på honom: I ei rad var ein karneol og ein topas og ein smaragd; det var den fyrste radi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'I den andre radi var ein rubin og ein safir og ein beryll,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'og i den tridje radi ein hyacint og ein agat og ein ametyst,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'og i den fjorde radi ein krysolit og ein sjoham og ein jaspis. Dei vart innfelte i fatingar av tvinna gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Steinarne var so mange som Israels-sønerne, tolv, so dei svara til talet deira, og på kvar stein var namnet åt ei av dei tolv ætterne inngrave som på ein seglring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'So laga dei lekkjor av skirt gull, slyngde som snorer, til bringeduken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Og dei gjorde tvo gullsylgjor og tvo gullringar, og sette ringarne i kvar sitt hyrna på bringeduken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Dei tvo gullsnorerne feste dei i dei tvo ringarne som sat i hyrno på bringeduken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'og dei hine tvo endarne av båe snorerne feste dei i dei tvo sylgjorne, og sylgjorne sette dei på akslebandi åt messehakelen, på framsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'So gjorde dei tvo andre gullringar og sette i dei hine tvo hyrno på bringeduken, på den sida som vender inn imot messehakelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Og endå tvo gullringar gjorde dei og sette på båe akslebandi åt messehakelen, nedantil på framsida, der som han var hekta i hop, ovanfor livgjordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'og so batt dei med ei purpursnor ringarne på bringeduken i hop med ringarne på messehakelen, so bringeduken sat ovanfor livgjordi og ikkje kunde rikkast frå messehakelen, soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'So gjorde dei prestekjolen, som var til å bera under messehakelen; han var voven og all igjenom av purpur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Midt på honom var det eit halssmog som på ei brynja, og kringum halssmoget ei borda, so han ikkje skulde rivna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'I falden på kjolen sette dei duskar, på gjerd som granateple, av tvinna purpurgarn og skarlak og karmesin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'so gjorde dei bjøllor av skirt gull og sette rundt ikring på kjolefalden, millom duskarne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'fyrst ei bjølla og ein dusk, so ei bjølla og ein dusk att, og soleis rundt heile kjolefalden, til å bruka ved gudstenesta, soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'So gjorde dei vovne underkjolar av fint lin til Aron og sønerne hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'og ei kvit linhuva, og prydelege hovudplagg av kvitt lin, og lereftsbrøker av kvitt tvinna lingarn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'og ei livgjord med rosor av kvitt tvinna lingarn og purpur og skarlak og karmesin, soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'So gjorde dei gullspongi, det heilage hovudgullet, og på den grov dei inn, som i ein seglring: «Vigd åt Herren,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'og dei sette ei purpursnor i henne, og feste henne ovantil på huva, soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'No var det ferdigt alt det som skulde arbeidast åt møtetjeldhuset, og Israels-folket hadde i eitt og alt gjort det soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'So kom dei då til Moses med huset: tjeldet med alt det som høyrde til det: krokarne og plankarne og tverrstokkarne og stolparne og stabbarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'og det raudlita verskinnstaket og markuskinns-taket og forhengtæpet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'lovtavlekista med berestengerne og loket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'bordet med alle dei ting som høyrde til det, og skodebrødi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'gull-ljosestaken med lamporne som var sette i rad og alt anna som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'gullaltaret og salvingsoljen og den angande røykjelsen og tæpet til tjelddøri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'koparaltaret med kopargrindi og berestengerne og alt anna som høyrde attåt, balja og foten ho skulde standa på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'lereftsgarden til tunet med stolparne og stabbarne som høyrde til og tæpet til tunporten og togi og pålarne og alt det som skulde brukast til den heilage tenesta i gudshuset, i møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'embætsskrudet til tenesta i heilagdomen, den heilage klædebunaden til Aron, presten, og messeklædi til sønerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Som Herren hadde sagt Moses fyre, heiltupp soleis hadde Israels-folket gjort alt arbeidet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Og Moses skoda heile verket, og då han såg at det var ferdigt, og at dei i alle måtar hadde gjort det soleis som Herren hadde sagt, so velsigna han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Då tala Herren til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '«Den fyrste dagen i den fyrste månaden skal du reisa møtetjeldhuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Der skal du setja lovtavlekista, og hengja forhenget attfor kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'So skal du setja inn bordet, og på det skal du skipa det som på det skal vera. Og du skal bera inn ljosestaken, og setja upp lamporne på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Det gullklædde røykjelsesaltaret skal du setja framanfor lovtavlekista, og so skal du hengja upp dørtæpet i husdøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Brennofferaltaret skal du setja framanfor døri til møtetjeldhuset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'og balja skal du setja millom møtetjeldet og altaret, og hava vatn upp i henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'og so skal du setja upp garden kring tunet, og hengja upp tæpet i tunporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Sidan skal du taka salvingsoljen, og salva huset og alt som i det er, og vigsla både huset og all bunaden i det, so det vert heilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Og du skal salva brennofferaltaret og alt det som til høyrer, og vigsla altaret, og då skal altaret vera høgheilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Og du skal salva balja og foten ho stend på og vigsla henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'So skal du kalla Aron og sønerne hans burtåt møtetjelddøri, og två deim med vatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'og du skal klæda Aron i den heilage klædebunaden, og salva honom og vigsla honom, og so skal han vera prest for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Og sønerne hans skal du og kalla fram og klæda deim med underkjolar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'og salva deim, liksom du salva far deira, so dei kann vera prestar for meg, og salvingi skal gjeva deim retten til preste-embættet, mann etter mann, i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Og Moses gjorde so: han gjorde i alle måtar som Herren sagde honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Den fyrste månaden av det andre året, den fyrste dagen i månaden, var det at huset vart reist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Då reiste Moses huset: han sette ned stabbarne og reiste upp plankarne, lagde inn tverstokkarne og sette upp stolparne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'so spana han ut tjeldet yver huset, og lagde tjeldtaket ovanpå, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'So tok han og lagde lovtavlorne ned i kista, og sette stengerne i, og sette loket yver kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Og kista sette han inn i gudshuset, og feste upp forhengtæpet, so det hekk attfor lovtavlekista, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'So sette han bordet i møtetjeldet, innåt nørdre husveggen, utanfor forhenget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'og skipa brødi i rader på det for Herrens andlit, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Ljosestaken sette han og i møtetjeldet, midt for bordet, innmed søre husveggen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'og sette upp lamporne for Herrens åsyn, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Gullaltaret og sette han i møtetjeldet, framanfor forhenget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'og brende angande røykjelse på det, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'So hengde han upp dørtæpet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'og sette brennofferaltaret frammed døri til møtetjeldhuset, og ofra brennoffer og grjonoffer på det, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Balja sette han millom møtetjeldet og altaret, og hadde vatn i henne som dei skulde två seg med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'og Moses og Aron og sønerne hans tok av vatnet og tvo hender og føter;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'kvar gong dei gjekk inn i møtetjeldet eller fram åt altaret, so tvo dei seg, alt soleis som Herren hadde sagt Moses fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'So sette han upp garden kringum huset og altaret, og hengde upp tæpet i tunporten, og so var Moses ferdig med verket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Då sveipte skyi seg kringum møtetjeldet, og herlegdomen åt Herren fyllte huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Og Moses kunde ikkje koma inn i møtetjeldet, av di at skyi låg yver tjeldet, og herlegdomen åt Herren fyllte huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Og kvar gong skyi lyfte seg ifrå gudshuset, tok Israels-folket ut; so gjorde dei på alle ferderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Men når skyi ikkje lyfte seg, so tok dei ikkje ut, men drygde til den dagen ho lyfte seg att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'For Herrens sky låg yver huset um dagen, og um natti skein ho som eld for augo åt heile Israels-ætti på alle ferderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Og Herren ropa på Moses, og tala til honom or møtetjeldet og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '«Tala til Israels-folket og seg til deim: «Når nokon av dykk vil koma til Herren med ei offergåva av buskapen, so kann han taka offeret sitt anten av storfeet eller av småfeet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Er det eit brennoffer han vil gjeva, og han tek det av storfeet, so skal det vera ein ukse som ikkje hev lyte. Til døri åt møtetjeldet skal han koma med gåva si, so han vert velsedd for Herrens åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'og han skal leggja handi på hovudet åt offerdyret; då skal gåva hans tekkjast Herren, so han fær nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'So skal han slagta uksen for Herrens åsyn, og Arons-sønerne, prestarne, skal bera fram blodet, og skvetta det rundt ikring på altaret som stend framanfor døri åt møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Og so skal han flå offerdyret og lema det sund;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'og sønerne åt Aron, øvstepresten, skal kveikja upp eld på altaret, og leggja ved på elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Sidan skal Arons-sønerne, prestarne, leggja kjøtet og hovudet og feittet uppå veden som er lagd på altarelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Innvolen og føterne skal tvåast i vatn, og so skal presten brenna alt saman på altaret; so røyken stig upp mot himmelen; då er det eit brennoffer åt Herren, ein offerret som det angar godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Tek han brennofferet sitt av småfeet, av sauerne eller geiterne, so skal det vera ein lytelaus ver eller bukk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Den skal han slagta på nordsida åt altaret, for Herrens åsyn, og Arons-sønerne, prestarne, skal skvetta blodet rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'So skal han luta upp offerdyret, og lata hovudet og feittet fylgja med, og presten skal leggja luterne uppå veden som er lagd på altarelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Innvolen og føterne skal dei två i vatn, og so skal presten bera fram alt saman, og brenna det på altaret, so røyken stig upp mot himmelen; då er det er eit brennoffer åt Herren, ein offerret som gjev god ange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Er det fugl han vil taka til brennoffer åt Herren, so skal offergåva han kjem med, vera ei turtelduva eller ein duveunge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Presten skal bera fuglen fram åt altaret, og vrida hovudet av honom, og brenna det på altaret; og blodet skal kreistast ut mot altarveggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'So skal han taka ut krelen med goret som er i, og kasta det attmed altaret, på austsida, der oska er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'og so flekkja fuglen med vengjerne på; deim må han ikkje skjera av. Sidan skal presten brenna fuglen på altaret, på veden som er lagd på elden, so røyken stig upp mot himmelen; då er det eit brennoffer åt Herren, ein offerret som anger godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Når nokon vil bera fram eit grjonoffer for Herren, so skal offergåva hans vera fint mjøl; det skal han hella olje yver og leggja røykjelse attmed,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'og so skal han koma til Arons-sønerne, til prestarne, med det, og presten skal taka ein neve av mjølet og oljen og so all røykelsen, og brenna det på altaret, so røyken stig upp mot himmelen til ei minning; då er det ein offerret åt Herren, ein som det angar godt av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Det som er att av grjonofferet, skal Aron og sønerne hans hava; det høyrer til det som er høgheilagt av offerrettarne åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Når du vil bera fram eit grjonoffer av noko som er baka i omn, so skal det vera av fint mjøl, anten hellekakor med olje i eller oljesmurde tunnbrødleivar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Vil du gjeva eit grjonoffer som er steikt på takka, so skal det og vera av fint mjøl som er blanda med olje, og usyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Du skal brjota det i bitar, og hella olje yver det, so er det eit rett grjonoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Vil du gjeva eit grjonoffer som er steikt i panna, so skal det med vera tillaga av fint mjøl og olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Når grjonofferet er tillaga på ein av dei måtarne, skal du bera det fram for Herren. Du skal koma til presten med det, og han skal bera det fram åt altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'So skal presten taka av det som skal vera til minningsoffer, og brenna det på altaret, so røyken stig upp mot himmelen; då er det ein offerret åt Herren, ein som det angar godt av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Og det som då er att av offeret, skal Aron og sønerne hans hava. Det høyrer til det som er høgheilagt av Herrens offerrettar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Eit grjonoffer som de ber fram for Herren, må aldri vera syrt; det som det er surdeig eller honning i, må de ikkje brenna til offermat for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Til nygrødeoffer kann de hava det; men på altaret må det ikkje koma, til godange for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Alle grjonoffer som du ber fram, skal du salta; aldri må du lata det vanta på salt i grjonofferet ditt. Saltet høyrer til sambandet med din Gud; di skal du bera fram salt attåt alle offeri dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Vil du gjeva Herren eit grjonoffer av nygrøda, so skal offeret som du ber fram av nygrøda divera aks som er steikte yver elden, eller nyhausta korn som er grøypt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Det skal du hella olje yver og leggja røykjelse attmed; då er det eit rett grjonoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Og presten skal brenna noko av det grøypte kornet og av oljen og all røykjelsen, so røyken stig upp mot himmelen til ei minning; då er det ein god offerrett for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Vil nokon bera fram eit takkoffer, og han tek det av storfeet, so kann det offerdyret han leider fram for Herrens åsyn vera anten ukse eller ku, men lytelaust skal det vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Han skal leggja handi på hovudet åt offerdyret, og slagta det i døri til møtetjeldet, og Arons-sønerne, prestarne, skal skvetta blodet rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'So skal han av takkofferet bera fram ei gåva åt Herren, og det skal vera netja og alt feittet som er på innvolen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'og båe nyro med talgi som er på dei og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'og Arons-sønerne skal brenna det på altaret saman med brennofferet, som ligg på veden dei hev lagt på elden; då er det ein rjukande offerrett åt Herren, ein som gjev god ange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Er det av småfeet han tek det dyret som han vil bera fram for Herren til takkoffer, so kann det vera anten han eller ho, men det skal vera fritt for lyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Vil han ofra ein sau, so skal han leida honom fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Han skal leggja handi på hovudet åt offerdyret, og slagta det framanfor møtetjeldet, og Arons-sønerne skal skvetta blodet rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'So skal han av takkofferet bera fram ei gåva for Herren, og det skal vera alt feittet som er på sauen: spælen heil og halden - den skal han skjera av tett innmed roti - og netja og alt feittet som er på innvolen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'og presten skal brenna det på altaret; so røyken stig upp mot himmelen; det er eit godt offermål for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Er det ei geit han vil ofra, so skal han leida henne fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Han skal leggja handi på hovudet hennar, og slagta henne framanfor møtetjeldet, og Arons-sønerne skal skvetta blodet rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'So skal han av offeret sitt bera fram ein god rett for Herren, og det skal vera netja og alt feittet som er på innvolen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'og presten skal brenna det på altaret, so røyken stig upp mot himmelen; då er det ein offerrett som angar godt. Alt feitt høyrer Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Ei æveleg lov skal det vera for dykk og etterkomarane dykkar i kvar ein heim, at de aldri må eta feitt og blod.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '«Tala til Israels-folket og seg: «Når nokon uviljande syndar mot eit av Herrens bod og gjer noko som han hev forbode å gjera, so høyr:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Er det den salva presten som syndar og fører skuld yver folket, so skal han til bot for den syndi han hev gjort koma til Herren med ein ung ukse som ikkje hev lyte; det skal vera syndofferet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Han skal leida uksen fram for Herrens åsyn, til døri åt møtetjeldet, og han skal leggja handi på hovudet åt uksen, og han skal slagta uksen for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'So skal han, den salva presten, taka noko av ukseblodet og bera det inn i møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Og han, presten, skal duppa fingeren i blodet, og han skal skvetta av blodet sju gonger for Herrens åsyn, framanfor det heilage forhenget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Noko av blodet skal han strjuka på horni åt altaret med den angande røykjelsen, det som stend framfor Herrens åsyn i møtetjeldet, og det som er att av ukseblodet, skal han hella ut tett innmed foten på brennofferaltaret, som stend framanfor døri til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Alt feittet som er på syndofferuksen, skal han taka utor honom, både netja og alt feittet som er på innvolen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'alt dette skal han taka ut, like eins som på takkofferuksen, og so skal han brenna det på brennofferaltaret, so røyken stig upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Men hudi av uksen og alt kjøtet, med hovudet og føterne og innvolen og myki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'heile uksen, skal han føra ut or lægret, til ein rein stad, der dei slær ut oska, og brenna det upp med ved; der som oska vert slegi ut, der skal dei brenna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Hev heile Israels-lyden misfare seg, hev folket seg uvitande gjort noko av det som Herren hev forbode å gjera, og ført skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'og det sidan vert kunnigt kva dei hev synda i, so skal folket koma med ein ung ukse til syndoffer. Den skal dei leida fram åt møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'og dei eldste av lyden skal leggja henderne på hovudet åt uksen for Herrens åsyn, og so skal uksen slagtast for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Den salva presten skal bera noko av ukseblodet inn i møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'og han, presten, skal duppa fingeren i blodet, og skvetta sju gonger for Herrens åsyn, framanfor forhenget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Noko av blodet skal han strjuka på horni åt det altaret som stend framfor Herrens åsyn i møtetjeldet, og det som er att av blodet, skal han hella ut tett innmed foten på brennofferaltaret, som stend framanfor døri til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Alt feittet skal han taka utor uksen, og brenna det på altaret, so røyken stig upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Som han gjorde med hin syndofferuksen, so skal han gjera med denne og. Når presten soleis hev bore fram soningsoffer for deim, skal dei få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Sidan skal dei føra uksen utanfor lægret, og brenna honom, liksom dei brende den fyrste uksen. Dette er syndofferet for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Når ein hovding misfer seg og uviljande gjer noko av det som Herren, hans Gud, hev forbode å gjera, og soleis fører skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'og det vert kunnigt for honom kva han hev synda i, so skal han koma med ei offergåva, og det skal vera ein geitebukk, ein som ikkje hev lyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Han skal leggja handi på hovudet åt bukken, og slagta honom på same staden som dei slagtar brennofferet for Herrens åsyn; då er det eit syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Presten skal taka noko av offerblodet på fingeren, og strjuka det på horni åt brennofferaltaret, og det som er att av blodet, skal han hella ut tett innmed foten på brennofferaltaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Og alt feittet skal han brenna på altaret liksom han gjorde med feittet av takkofferet. Når presten soleis hev bore fram soningsoffer for honom og gjort honom rein for syndi, skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Er det ein ålmugemann som uviljande syndar mot eit av Herrens bod og gjer noko som han ikkje skulde gjera, so han fører skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'og det vert kunnigt for honom kva han hev synda i, so skal han til bot for den syndi han hev gjort, koma med ei offergåva, og det skal vera ei geit, ei som ikkje hev lyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Han skal leggja handi på hovudet åt syndofferdyret, og han skal slagta syndofferdyret på brennofferstaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Og presten skal taka noko av blodet på fingeren, og strjuka det på horni åt brennofferaltaret, og det som er att av blodet, skal han hella ut tett innmed altarfoten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Alt feittet skal han taka utor, liksom dei tek ut feittet på takkofferet, og presten skal leggja det på altaret og brenna det til godange for Herren. Når presten soleis hev gjort soning for honom, skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Vil han heller taka ein sau til syndoffer, so skal han koma med ei søya som ikkje hev lyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Han skal leggja handi på hovudet åt offerdyret, og so skal han slagta det til syndoffer på same staden som dei slagtar brennofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Og presten skal taka noko av syndofferblodet på fingeren, og strjuka det på horni åt brennofferaltaret, og det som er att av blodet, skal han hella ut tett innmed altarfoten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Alt feittet skal han taka utor, liksom dei gjer med takkoffersauen, og presten skal brenna det på altaret saman med offerretterne åt Herren. Når presten soleis hev bore fram soningsoffer for den syndi han hev gjort, skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Når nokon høyrer ei våbøn som vert lyst yver ein brotsmann, og han hev set eller veit noko so han kunde vitna mot honom, men like vel ikkje segjer ifrå, og soleis syndar og fører skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'eller nokon, seg uvitande, kjem innåt noko ureint, anten det er etslet av eit ureint villdyr eller av eit ureint krøter eller av eit ureint krek, og soleis sjølv vert urein og fører skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'eller når han kjem nær noko ureint av folk, kva det so er for ureinska som er på deim, og han ikkje veit av det, men sidan fær vita det og ser at han hev ført skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'eller når nokon sver tankelaust burt i veret at han vil gjera eitt eller anna, slikt som folk kann koma til å sverja på i tankeløysa, og han ikkje håttar det, men sidan vert vis med at han hev ført skuld yver seg med eitkvart sovore,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'so skal den som soleis hev ført skuld yver seg standa til kva han hev synda i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'og til bot for den syndi han hev gjort, skal han koma til Herren med eit syndoffer - det skal vera eit småkrøter av hoslaget, søya eller geit - og presten skal bera fram soningsoffer for honom og gjer honom rein for syndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Hev han ikkje råd til eit småkrøter, so skal han til bot for den syndi han hev gjort bera fram for Herren tvo turtelduvor eller tvo duveungar, den eine til syndoffer og den andre til brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Han skal koma til presten med deim, og presten skal fyrst bera fram den duva som skal vera til syndoffer. Han skal vrida um hovudet på henne tett uppmed nakken, men ikkje skilja det frå bulen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'So skal han skvetta noko av syndofferblodet på altarveggen, og det som er att av blodet, skal kreistast ut so det renn ned innmed altarfoten. Då er det eit rett syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Av den andre duva skal han laga til eit brennoffer, på rette gjerdi. Når presten soleis hev bore fram soningsoffer for den syndi han hev gjort, so skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Hev han ikkje råd til tvo turtelduvor eller tvo duveungar, so skal han til bot for di han hev synda koma med ei kanna fint mjøl; det skal vera syndofferet hans. Han skal ikkje hava olje på det, og ikkje leggja røykjelse attmed; for det er eit syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Til presten skal han koma med det, og presten skal taka ein neve av mjølet og brenna på altaret, saman med offerretterne åt Herren, då er det eit rett syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Når presten soleis hev bore fram soningsoffer for den syndi han på den eine eller den andre måten hev gjort, so skal han få tilgjeving. Dette offeret skal høyra presten til på same vis som grjonofferet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '«Er det nokon som uviljande eignar til seg noko av det som er vigt åt Herren, og soleis vert saka i svik, so skal han til bot for si skuld koma til Herren med ein lytelaus ver av fenaden sin, ein som etter ditt skyn er verd minst tvo sylvdalar i heilag mynt; det skal vera skuldofferet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Det han med urett hev eigna til seg av dei vigde gåvorne, skal han gjeva att, og attåt leggja femteparten av verdet. Han skal gjeva det til presten, og når presten hev ofra skuldofferveren til soning for honom, skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Når nokon syndar og gjer noko av det som Herren hev forbode å gjera, og han ikkje veit av det, men skynar at han hev fare i mist og ført skuld yver seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'so skal han til bot for si skuld koma til presten med ein lytelaus ver av fenaden sin, ein som etter ditt skyn er eit fullgodt offer; og presten skal bera fram soningsoffer for den misgjerdi han hev gjort og ikkje visste av, og då skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Dette er eit skuldoffer; for det var visst at han bar på ei skuld imot Herren.» Og Herren tala atter til Moses, og sagde: «Når nokon syndar og gjer svik imot Herren og dyl burt noko som grannen hev gjeve honom i varveitsla eller sett i vissa hjå honom, eller som han hev teke eller truga til seg av grannen, eller han finn noko som ein annan hev mist og so dyl det, eller når han gjer rang eid um eitt eller anna som han eller andre kann ha synda med, so skal den som soleis hev synda og ført skuld yver seg, gjeva att det han hev teke, eller truga til seg, eller fenge i varveitsla eller funne, og det han hev gjort rang eid um, kva det no kann vera. Han skal gjeva det att med fullt verd, og leggja femteparten attåt; til eigarmannen skal han gjeva det, og det same dagen som han ber fram skuldofferet sitt. Og til bot for si skuld skal han koma til Herren med ein lytelaus ver av fenaden sin, ein som etter ditt skyn er eit fullgodt offer, og gjeva honom til presten; det skal vera skuldofferet hans. So skal presten gjera soning for honom for Herrens åsyn, og då skal han få tilgjeving for alle gjerningar som han kann ha ført skuld yver seg med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '«Seg til Aron og sønerne hans: «So er lovi um brennofferet: Brennofferet det skal liggja på eldstaden sin, på altaret, heile natti, til morgons, og der skal altarelden nørast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Og presten skal klæda seg i linkjolen sin, og ei linbrok skal han hava på seg næst kroppen, og han skal taka burt oska etter brennofferet, som elden hev tært upp på altaret, og leggja henne attmed altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'So skal han hava av seg klædebunaden sin, og taka på seg andre klæde, og bera oska ut or lægret, til ein rein stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Men elden skal haldast vaken på altaret; han må ikkje slokna. Kvar morgon skal presten nøra elden med ved, og leggja brennofferet uppå veden, og saman med det brenna takkofferfeittet, so røyken stig upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Elden skal allstødt brenna på altaret, og må aldri slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'So er lovi um grjonofferet: Ein av Arons-sønerne skal bera det fram for Herren, på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Han skal taka ein neve av det fine mjølet og oljen i grjonofferet, og all røykjelsen som fylgjer med grjonofferet, og brenna det på altaret, so røykjen stig upp mot himmelen; det er eit minningsoffer åt Herren, eit som gjev god ange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Og det som er att av offeret, skal Aron og sønerne hans eta; det skal etast usyrt på ein heilag stad: i tunet åt møtetjeldet skal dei eta det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'med surdeig må det ikkje bakast. Det er den luten eg gjev deim av offerretterne mine; høgheilagt er det, liksom syndofferet og skuldofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Alle menner som er ætta frå Aron, må eta av det; gjenom alle tider og ætter skal det vera dykkar rett av offergåvorne åt Herren; den som rører deim, lyt vera vigd.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '«Den offergåva som Aron og sønerne hans skal bera fram for Herren den dagen dei vert salva, det er ei kanna fint mjøl; det skal vera det dagvisse grjonofferet, helvti um morgonen og helvti um kvelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Med olje skal det lagast til på ei takka; godt knoda skal det vera når du kjem med det; eit grjonoffer som er sundbytt i småstykke, skal du bera fram til godange for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Den av sønerne åt Aron som vert salva til prest i staden hans, skal laga det til. Ei æveleg reidda åt Herren skal det vera, og heile offeret skal brennast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Alle prestegrjonoffer skal vera heiloffer; dei må ikkje etast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '«Tala til Aron og sønerne hans og seg: «So er lovi um syndofferet: På same staden som dei slagtar brennofferet, skal syndofferet og slagtast for Herrens åsyn; høgheilagt er det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Presten som ber fram syndofferet, må eta det; på ein heilag stad skal det etast, i møtetjeldtunet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Den som rører offerkjøtet, lyt vera vigd. Kjem det noko av blodet på klædi, so skal du taka det plagget som blodet hev kome på og två det på ein heilag stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Er det ei leirgryta kjøtet vert koka i, so skal ho slåast sund; men er det ein koparkjel, so skal han skurast og skyljast med vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Alle menner som er prestar, må eta av dette offeret; det er høgheilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Men dei syndofferi som det vert bore blod av inn i møtetjeldet til å sona med i heilagdomen, dei må aldri etast; dei skal brennast i elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'So er lovi um skuldofferet: Det er høgheilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'På same staden som dei slagtar brennofferet, skal dei slagta skuldofferet. Blodet skal dei skvetta rundt ikring på altaret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'og alt feittet skal dei bera fram for Herren, både spælen og netja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal skjerast utor i hop med nyro -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'og presten skal brenna det på altaret til ein offerrett for Herren; då er det eit rett skuldoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alle menner som er prestar, må eta av det; på ein heilag stad skal det etast; det er høgheilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Med skuldofferet er det like eins som med syndofferet - det gjeld same lovi for båe; den presten som gjer soning med det, han skal hava det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Når ein prest ofrar brennoffer for ein mann, so skal den same presten hava hudi av offerdyret som han hev bore fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Og alle grjonoffer som vert baka i omn og alle som er tillaga i panna eller på takka, deim skal den presten hava som ber deim fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Men alle andre grjonoffer, anten dei er blanda med olje eller turre, skal høyra alle Arons-sønerne til, den eine som den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'So er den lovi som gjeld når nokon kjem til Herren med eit takkoffer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Er det til Guds lov og pris han ofrar det, so skal han attåt slagtofferet bera fram hellekakor med olje i, og tunnbrødleivar som er smurde med olje, og fint mjøl som er blanda med olje og knoda til kakor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Det er dei offergåvorne han skal bera fram attåt lov- og takkofferdyret, og umfram det skal han hava med seg syrte kakor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Av offergåvorne skal han gjeva ei av kvart slag i reida åt Herren; det skal presten hava, han som skvetter blodet av takkofferet på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Kjøtet av lov- og takkofferet lyt etast same dagen som det vert frambore; ingen må gøyma noko av det til morgons.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Er det eit slagtoffer som ein hev lova eller gjev i godvilje, so skal det helst etast same dagen som han ber fram offeret sitt. Vert det noko att, so kann det etast dagen etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Men det som er att av offerkjøtet tridje dagen, skal brennast upp i elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Dersom nokon et av takkofferkjøtet tridje dagen, so hev Herren ingen hugnad i offeret, og det vert ikkje rekna den til gode som bar det fram; det skal haldast for utskjemt og ureint, og den som et av det, gjer ei misgjerning som han kjem til å lida for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Kjøt som hev vore innåt noko ureint, må heller ikkje etast; det skal brennast upp i elden. Elles kann alle som er reine eta av kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Men den som et kjøt av Herrens takkoffer medan det er noko ureint på honom, han skal rydjast ut or ætti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Og når ein mann kjem nær noko ureint, anten det er slik ureinska som kann vera på folk, eller det er eit ureint dyr eller noko anna ureint og ufyse, og han so et av takkofferkjøtet åt Herren, so skal den mannen rydjast ut or ætti si.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '«Tala til Israels-borni og seg: «De må aldri eta feitt, anten av ukse eller sau eller geit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Feittet av sjølvdaude dyr og av dyr som er rivne i hel, kann de nytta til ymse ting, men eta det må de ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Er det nokon som et feittet av slikt bufe som dei tek til offer åt Herren, so skal den som gjer det rydjast ut or ætti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Og ikkje i noko hus må de eta blod, anten av fugl eller fe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Den som nokosinne et blod, han skal rydjast ut or ætti si.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '«Tala til Israels-borni og seg: «Den som vil bera fram eit takkeslagtoffer åt Herren, han skal sjølv koma med det han vil gjeva Herren av offeret sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Med sine eigne hender skal han bera fram dei offerretterne som er etla åt Herren. Både bringestykket og feittet skal han bera fram, og bringestykket skal svingast att og fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Og presten skal brenna feittet på altaret, so røyken stig upp mot himmelen; men bringestykket skal Aron og sønerne hans hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Og det høgre låret skal de gjeva presten i reida av takkofferi dykkar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'den av Arons-sønerne som ber fram takkofferblodet og feittet, han skal hava det høgre låret for sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'For svingebringa og lyftelåret av takkeofferi frå Israels-folket tek eg imot av deim, og gjev det åt Aron, presten, og sønerne hans; det skal i all æva vera retten deira av Israels-folket.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'So var den luten Aron og sønerne hans fekk av Herrens offerretter den dagen dei vart kalla til å gjera prestetenesta for Herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'det var det Herren sagde at Israels-borni skulde gjeve deim den dagen dei vart salva, og det skulde vera retten deira ætt etter ætt i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Dette var lovi um brennofferet og um grjonofferet og um syndofferet og um skuldofferet og um vigsleofferet og um takkofferet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'den som Herren kunngjorde for Moses på Sinaifjellet, den gongen han gav Israels-folket det bodet at dei skulde bera fram offergåvorne sine for Herren i øydemarki kring Sinai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '«Henta no Aron og sønerne hans, og tak dei heilage klædi og salvingsoljen og syndofferuksen og båe verarne og korgi med søtebrødet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'og kalla so heile lyden saman framfor døri åt møtetjeldet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Og Moses gjorde som Herren sagde, og lyden samla seg framfor møtetjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Då sagde Moses til deim: «Sjå no kva Herren hev sagt eg skal gjera!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'So kalla han til seg Aron og sønerne hans, og tvo dei med vatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'og han hadde underkjolen på Aron, og spente beltet um honom, og klædde honom i prestekjolen, og hengde messehakelen på honom, og batt um honom livgjordi som høyrde til, og med den snørde han messehakelen fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'So hadde han bringeduken på honom, og i bringeduken lagde han urim og tummim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Og han sette huva på hovudet hans, og framme på huva sette han gullspongi, det heilage hovudgullet, alt soleis som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'So tok Moses salvingsoljen, og salva gudshuset og alt som i det var, og vigsla det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'og han skvette sju vendor på altaret av oljen, og salva altaret og alle dei ting som høyrde til det, og tvåttebalja med foten ho stod på, og vigsla deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Og noko av salvingsoljen helte han yver hovudet på Aron, og salva og vigde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Sidan kalla han til seg sønerne hans Aron, og klædde deim i underkjolar, og spente belte um deim, og batt hovudplagg på deim, alt soleis som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'So leidde han fram syndofferuksen, og Aron og sønerne hans lagde henderne på hovudet åt uksen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Og då dei hadde slagta honom, tok Moses blodet og strauk rundt ikring på altarhorni med fingeren, og gjorde altaret reint for synd, og det som var att av blodet, helte han ut tett innmed altarfoten. Soleis gjorde han soning for altaret og vigsla det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'So tok han alt feittet som var på innvolen, og den store livreflaga og båe nyro med talgi på, og brende det på altaret, so røyken steig upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Men sjølve uksen, både hudi og kjøtet og møki, brende han i elden utanfor lægret, alt soleis som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'So leidde han fram brennofferveren, og Aron og sønerne hans lagde henderne på hovudet åt veren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Og då dei hadde slagta honom, skvette Moses blodet rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Men sjølve veren lema dei sund, og Moses brende hovudet og kjøtet og feittet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'innvolen og føterne tvo dei fyrst i vatn, og so brende Moses heile veren på altaret, so røyken steig upp mot himmelen. Det vart eit brennoffer som anga godt, ein offerrett for Herren var det; alt vart gjort soleis som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'So leidde han fram den andre veren, vigsleveren, og Aron og sønerne hans lagde henderne på hovudet åt veren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Og då dei hadde slagta honom, tok Moses noko av blodet og strauk på den høgre øyresnippen åt Aron og på den høgre tumarsfingeren og den høgre tumarståi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'So kalla han til seg sønerne hans Aron, og strauk noko av blodet på den høgre øyresnippen og på den høgre tumarsfingeren og den høgre tumarståi deira, og det som var att av blodet, skvette han rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Og han tok feittet, både spælen alt feittet som var på innvolen, og den store livreflaga og båe nyro med talgi på, og so det høgre låret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Og or søtebrødkorgi som stod framfor augo åt Herren, tok han ei hellekake og eit oljebrød og ein tunnbrødleiv og lagde uppå på feittet og verlåret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Og so lagde han alt saman i henderne på Aron og sønerne hans og svinga det att og fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Sidan tok han det utor henderne deira, og brende det på altaret saman med brennofferet, so røyken steig upp mot himmelen; det var eit vigsleoffer som gav god ange, ein offerrett for Herren var det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Og Moses tok bringestykket, og svinga det att og fram for Herrens åsyn; det var den luten Moses fekk av vigsleveren, soleis som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'So tok Moses noko av salvingsoljen og noko av blodet som stod på altaret og skvette på Aron og klædi hans og på sønerne hans og klædi deira; og vigsla Aron og klædi hans og sameleis sønerne hans og klædi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Og Moses sagde til Aron og sønerne hans: «De skal sjoda kjøtet i døri åt møtetjeldet og eta det attåt brødet som er i vigsleofferkorgi; for so hev Gud sagt med meg: «Aron og sønerne hans skal eta det,» hev han sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Men det som vert att av kjøt og brød, skal de brenna i elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Og so lyt de i sju dagar halda dykk innmed møtetjelddøri, alt til den dagen då vigsletidi dykkar er ute; for sju dagar skal prestevigsla vara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Som de hev gjort i dag, so skal de gjera dei hine dagarne og, so de kann få nåde, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Og i møtetjelddøri skal de sitja dag og natt i sju jamdøger og halda dykk etter det som Herren hev sagt, so de ikkje skal missa livet; for so hev Herren sagt med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Og Aron og sønerne hans gjorde alt det som Herren hadde late Moses segja til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Då den åttande dagen var komen, kalla Moses til seg Aron og sønerne hans og dei øvste i Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'og han sagde med Aron: «Tak ein uksekalv til syndoffer og ein ver til brennoffer, lytelause båe tvo, og leid deim fram for Herrens åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Og til Israels-folket skal du segja: «Tak ein geitebukk til syndoffer, og ein kalv og eit lamb, årsgamle og lytelause båe tvo, til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'og ein ukse og ein ver til takkoffer - dei skal slagtast for Herrens åsyn - og so eit grjonoffer som er tillaga med olje! For i dag vil Herren syna seg for dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'So henta dei det som Moses hadde sagt, og sette det framanfor møtetjeldet, og heile lyden gjekk innåt, og stod for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Og Moses sagde: «Soleis hev Herren sagt de skal gjera, so skal herlegdomen åt Herren syna seg for dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'So sagde han til Aron: «Kom hit åt altaret, og ofra syndofferet og brennofferet ditt, og gjer soning for deg og for folket, og ber so fram offergåva frå folket og gjer soning for deim, soleis som Herren hev sagt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'So steig Aron fram åt altaret, og slagta uksekalven som skulde vera syndoffer for honom sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Sønerne hans gav honom blodet, og han duppa fingeren i blodet, og strauk det på altaret, og det som var att av blodet, helte han ut tett innmed altarfoten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Feittet og nyro og den store livreflaga av syndofferdyret brende han på altaret, so røyken steig upp mot himmelen, soleis som Herren hadde sagt med Moses;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'men kjøtet og hudi brende han i elden utanfor lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'So slagta han brennofferdyret. Sønerne hans gav honom blodet, og han skvette det rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Sidan rette dei sjølve brennofferet til honom, stykke for stykke, og hovudet, og han brende det på altaret, so røyken steig upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Innvolen og føterne tvo han i vatn, og so brende han det og på altaret i hop med hitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'So bar han fram offergåvorne frå folket. Fyrst tok han bukken som skulde vera syndoffer for folket, og slagta honom, og bar honom fram til syndoffer, liksom det fyrste offerdyret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Sameleis førde han fram brennofferet, og stelte det til på rette gjerdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Sidan bar han fram grjonofferet; av det tok han ein neve og brende på altaret umfram morgon-brennofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'So slagta han uksen og veren, takkofferet frå folket; sønerne hans gav honom blodet, og han skvette det rundt ikring på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Og feittet av uksen, og spælen og netja og nyro og den store livreflaga av veren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'alt feittet, lagde dei uppå bringestykki. Og Aron brende feittet på altaret, so røyken steig upp mot himmelen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'men bringestykki og det høgre låret svinga han att og fram for Herrens åsyn, som Moses hadde sagt til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Og Aron lyfte henderne yver folket og velsigna deim, og so steig han ned, etter han hadde bore fram syndofferet og brennofferet og takkofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Sidan gjekk Moses og Aron inn i møtetjeldet, og då dei kom ut att, velsigna dei folket. Då synte herlegdomen åt Herren seg for heile folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'og det for eld ut frå Herren åsyn og brende upp det som var på altaret, både brennofferet og feittet, og då folket såg det, ropa dei alle høgt av gleda, og kasta seg ned, med andlitet mot jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Men tvo av Arons-sønerne, Nadab og Abihu, tok kvar sitt glodfat og hadde gløder i, og lagde røykjelse på gløderne, og bar framand eld fram for Herrens åsyn, det som han hadde forbode deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Då for det eld ut frå Herren og tynte deim, og dei døydde for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Og Moses sagde med Aron: «Dette var det Herren meinte då han sagde: «Min heilagdom eg syner på deim som er meg næst, og alt folket let eg mitt velde lysa fram.»» Og Aron tagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Men Moses ropa på Misjael og Elsafan, sønerne hans Uzziel, som var farbror åt Aron, og sagde med deim: «Kom hit, og ber frendarne dykkar burt frå heilagdomen og ut or lægret!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'So kom dei, og gjorde som Moses sagde, og bar deim ut or lægret i kjolarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Og Moses sagde til Aron og til Eleazar og Itamar, sønerne hans: «De skal ikkje ganga med uflitt hår og ikkje riva sund klædi dykkar; for då kjem de til å missa livet, og han vert vreid på heile lyden. Men brørne dykkar, heile Israels-ætti, må gråta yver den elden som Herren sende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Og frå møtetjelddøri må de ikkje røyva dykk, so sant de ikkje vil missa livet; for Herrens salvingsolje er på dykk.» Og dei gjorde som Moses sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Og Herren tala til Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '«Vin eller nokon sterk drykk må du og sønerne dine ikkje drikka, når de gjeng inn i møtetjeldet; for då kjem de til å missa livet. Det skal vera ei æveleg lov for deg og etterkomarane dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'so de kann skilja millom heilagt og vanheilagt og millom ureint og reint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'og læra Israels-folket alle dei bodi som Herren hev late Moses kunngjera for deim».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Sidan sagde Moses til Aron og til Eleazar og Itamar, deim av sønerne hans som var i live: «Tak det som er att av dei grjonofferi det hev bore fram for Herren, og et det usyrte frammed altaret; for det er høgheilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'De skal eta det på ein heilag stad; det er det som du og sønerne dine hev rett til av offergåvorne åt Herren; for so hev Herren sagt med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Og svingebringa og lyftelåret skal de og eta på ein rein stad, du og sønerne og døtterne dine med deg; for det er den luten som er gjeven deg og borni dine av takkofferi frå Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Både lyftelåret og svingebringa skal dei bera fram i hop med offerfeittet, og svinga det att og fram for Herrens åsyn; sidan skal det høyra deg og borni dine til, og vera retten dykkar æveleg og alltid, soleis som Herren hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Då Moses tok til å spyrja etter syndofferbukken, fekk han vita at han var uppbrend. Då vart han harm på Eleazar og Itamar, deim som var att av sønerne hans Aron, og han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '«Kvi hev de ikkje ete syndofferet på den heilage staden? De veit då det er høgheilagt, og han hev gjeve dykk det på den måten at de skal taka burt syndeskuldi frå lyden og gjera soning for deim hjå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Blodet vart ikkje bore innar i heilagdomen; difor skulde de ha ete offerkjøtet på den heilage staden, som eg sagde dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Då svara Aron: «Du veit at dei i dag hev bore fram syndofferet og brennofferet sitt for Herrens åsyn, og endå hev slik ei ulukka hendt meg. Um eg no hadde ete syndoffer i dag, trur du då Herren hadde tykt vel um det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Då Moses høyrde det, tykte han det var rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Og Herren tala atter til Moses og Aron, og sagde med deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '«Tala til Israels-folket og seg: «Høyr no kva det er for nokre de må eta av alle dei firføtte dyri som liver på jordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alle dyr som hev klauver og jortar, deim kann de eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Det er berre desse de ikkje må eta av deim som jortar og av dei som hev klauver: kamelen, for han jortar, men hev ikkje klauver; han skal vera urein for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'og bergtassen, for han og jortar, men hev ingi klauver; han skal vera urein for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'og haren, for um han jortar, so hev han ikkje klauver han heller; han skal vera urein for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'og svinet, for det hev klauver, men det jortar ikkje; det skal vera ureint for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Kjøtet deira må de ikkje eta, og er dei daude, so må de ikkje røyva deim; dei skal vera ureine for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Høyr so kva de må eta av det som er i vatnet: Alt som er i vatnet, i havet og i elvarne, og hev uggar og reist, kann de eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Men slikt som ikkje hev uggar og reist av alt det som finst i hav eller å, av alt det som yrer i vatnet, alle kvikjende som held til der, det skal vera ein styggedom for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ein styggedom skal dei vera for dykk; kjøtet deira må de ikkje eta, og er dei daude, so skal de styggjast ved kropparne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alt i vatnet som ikkje hev uggar og reist, skal vera ein styggedom for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Høyr no og kva det er for fuglar de skal hava stygg til og ikkje må eta, av di dei er ufysne: Ørnen og gribben og sjøørnen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'og glenta og heile falkeætti');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'og alle fuglar av ramneætti');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'og strussen og gauken og måsen og alle haukeslag');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'og kattula og kavfuglen og stunulven');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'og kveldknarren og pelikanen og etslegribben');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'og storken og heidloi med alle andre fuglar av same ætti, og herfuglen og skinnvengja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alt krek som hev vengjer og krabbar på marki, skal vera ein styggedom for dykk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Av alt sovore krek må de ikkje eta anna enn det som ovanfor bakføterne hev leggjer til å hoppa på marki med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Av det kann de eta dei slagi som dei kallar fljugaren og slukaren og springaren og sprettaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Men alt anna krek som hev vengjer og krabbar på marki, skal vera ein styggedom for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'No skal eg segja dykk kva det er for dyr de vert ureine av - den som kjem nær kroppen deira etter dei er daude, han er urein alt til kvelds,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'og den som hev bore på slik ein daud kropp, lyt två klædi sine, og er urein alt til kvelds -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Alle dyr som hev høver, og ikkje klauver, og som ikkje jortar, skal vera ureine for dykk; den som kjem nær deim, vert urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Og alle firføtte dyr som gjeng på labbar, skal vera ureine for dykk; den som kjem nær deim når dei er daude, han er urein alt til kvelds,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'og den som hev bore på slikt eit daudt dyr, lyt två klædi sine, og er urein alt til kvelds. Ureine skal dei vera for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Av alle smådyr som røyver seg på jordi er det fyrst og fremst desse som skal vera ureine for dykk: Røysekatten og musi og alle fjorføtleslag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'og bustyvelen og vonden og padda og snigelen og litkvervingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Deim skal de halda for dei ureinaste av alle smådyr; den som kjem nær deim når dei er daude, er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Og alt det som dei dyri dett ned på når dei daudar, vert ureint, både trekoppar og klæde og skinn og sekkjer og kva det elles er som vert nytta i huset; det skal leggjast i vatn, og er ureint alt til kvelds; sidan er det reint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Dett eit av dyri ned i ein leirkopp, so vert alt det som er i koppen ureint, og han skal slåast sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'All mat som folk et, og som vert tillaga med vatn, og alt drikka som folk drikk, vert ureint, kva kjerald det er i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Alt det som slik ein daud kropp dett ned i, vert ureint; er det ein bakaromn eller ei eisa, so skal dei rivast ned; dei er ureine, og skal vera ureine for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Berre kjeldor og brunnar som det renn vatn åt, er like reine; men den som tek i den daude kroppen som ligg der, vert urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Dett dyret ned i korn som skal vera til såfrø, so er kornet like reint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'men hev dei havt vatn på det, og det so dett slikt eit daudt dyr ned i, so skal kornet vera ureint for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Daudar noko av dei dyri som skal vera til føda for dykk, so er den som kjem nær skrotten deira urein alt til kvelds,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'den som hev ete av kjøtet deira, lyt två klædi sine, og er urein alt til kvelds, og den som hev bore på den daude skrotten, lyt og två klædi sine og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Alt kreket som krelar på marki, er ein styggedom, og må ikkje etast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Korkje det som skrid på buken, eller det som gjeng på fire eller fleire føter, må de eta; for det er ufyse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Gjer dykk ikkje sjølve ufysne med noko av det krelande kreket, og sulka dykk ikkje med det, so de vert ureine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Eg, Herren, er dykkar Gud, og de skal helga dykk og vera heilage; for eg er heilag; de skal ikkje sulka dykk sjølve med noko av det kreket som krabbar på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Kom i hug: Eg er Herren, som førde dykk ut or Egyptarlandet og vil vera dykkar Gud, og de skal vera heilage; for eg er heilag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Dette er lovi um dyri og fuglarne og alt det livande som leikar i vatnet, og alle dei kvikjende som yrer på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'so de kann skilja det reine frå det ureine, og dei dyri som kann etast frå deim, som ikkje må etast.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '«Tala til Israels-borni og seg: «Når ei kvende kjem i barnseng og fær ein son, so skal ho vera urein i sju dagar, likso lenge som når ho hev månadstidi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Den åttande dagen skal huveholdet umskjerast på sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Sidan skal ho halda seg heime i tri og tretti dagar, medan blodet gjeng og ho reinskast; ikkje må ho røra noko heilagt, og ikkje må ho koma til heilagdomen fyrr reinskingsdagarne hennar er lidne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Fær ho eit møybarn, so vert ho vera urein i tvo vikor, som når ho hev sine eigne tider, og sidan skal ho halda seg heime i seks og seksti dagar, medan blodet gjeng og ho reinskast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Når reinskingstidi er ute, anten ho hev fenge son eller dotter, so skal ho koma med eit årsgamalt lamb til brennoffer og ein duveunge eller ei turtelduva til syndoffer; det skal ho bera fram åt møtetjelddøri, og gjeva det til presten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'og presten skal ofra det for Herrens åsyn, og gjera soning for henne, so ho vert rein etter blødingi. Denne lovi gjeld for alle kvende som hev fenge barn, anten det er son eller dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Men den sim ikkje hev råd til å ofra eit lamb, skal ho taka tvo turtelduvor eller tvo duveungar, den eine til brennoffer og den andre til syndoffer, og presten skal gjera soning for henne; då vert ho rein att.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Og Herren tala atter til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '«Når nokon fær notror eller utbrot eller ein ljos flekk på hudi, og det synest laga seg til spillsykja på likamen hans, so skal dei koma til Aron, øvstepresten, med honom, eller til ein av dei hine prestarne, Arons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Presten skal skoda dei såre flekkjerne på hudi, og dersom det synest liggja djupare enn skinnet, og håri på dei hev kvitna, so er det spillsykja, og med same presten ser det, skal han segja mannen urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Er det ein kvit sårkeflekk han hev fenge på hudi, og flekken ikkje synest liggja djupare enn skinnet, og håri på honom ikkje hev kvitna, so skal presten halda den sjuke innestengd i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Den sjuande dagen skal han sjå honom yver; tykkjer han då at sårken hev stana og ikkje breidt seg vidare ut yver hudi, so skal han halda mannen innestengd i sju dagar til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Når dei er lidne, skal presten sjå honom yver ein gong til, og dersom den såre flekken hev vorte dim, og ikkje hev ete um seg på hudi, so skal han segja mannen rein; for då er det berre eit meinlaust utbrot; han skal två klædi sine, so er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Men et utbrotet meir og meir um seg på hudi hans etter han synte seg fram for presten og bad at han vilde segja honom rein -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'ser presten, når den sjuke synar seg fram for honom andre venda, at utbrotet på hudi hev auka, so skal han segja honom urein; for då er det spillsykja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Når ein hev fenge spillsykja, so skal dei koma til presten med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Ser då presten kvite notror på hudi, som håri hev kvitna på, og som det gror villkjøt i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'So er det gamall spillsykja i hudi på likamen hans, og då skal presten segja honom urein; han treng ikkje fyrst stengja honom inne; for han er alt urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Bryt spillsykja ut so sterk at ho dekkjer heile hudi, frå hovud til fot, på den som er sjuk, kvar so presten fester augo sine -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'ser presten, når han skodar den sjuke, at spillsykja hev breidt seg ut yver heile likamen hans, so skal han segja honom rein; er han heiltupp kvit vorten, so er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Men so snøgt det syner seg villkjøt på honom, er han urein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'og når presten ser villkjøtet, skal han segja honom urein; for villkjøtet er ureint; det er spillsykja i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Gjeng villkjøtet burt att, og den sjuke vert kvit, so skal han koma til presten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'og når presten hev skoda honom, og set at han hev vorte kvit, so skal han segja honom rein; for då er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Fær nokon ein verk, og den vert lækt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'men det sidan kjem ei kvit notra eller ein bleikraud flekk der verken hev vore, so skal han syna seg fram for presten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Presten skal sjå honom yver, og dersom flekken synest vera lågare enn skinnet, og håri på honom hev kvitna, so skal han segja mannen urein; for då hev det vore spillsykja som braut ut i verken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Men ser presten at det ikkje er kvite hår på flekken, og at han ikkje er lågare enn skinnet, og at han hev vorte dim, so skal han halda mannen innestengt i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Et so flekken vidare og vidare um seg på hudi hans, so skal presten segja honom urein; då er det sjukdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Men held flekken seg på same staden og ikkje et seg utyver, so er det berre æret etter verken, og då skal presten segja honom rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Hev nokon fenge eit brunesår på hudi, og kjøtet som gror i såret ter seg som ein bleikraud eller kvit flekk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'so skal presten skoda såret. Synest då flekken liggja djupare enn skinnet, og hev håri på honom kvitna, so er det spillsykja som hev brote ut i brunesåret, og presten skal segja mannen urein; det er spillsykja, det er’kje til å taka mist av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Men ser presten, når han skodar flekken, at det ikkje er kvite hår på honom, og at han ikkje er lågare enn skinnet, og at han er dim, so skal han stengja mannen inne i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Den sjuande dagen skal han sjå honom yver, og dersom flekken hev ete um seg på skinnet hans, so skal presten segja honom urein; då er det spillsykja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Men er flekken dim og hev halde seg på same staden og ikkje ete seg utyver, so er det merke etter brunesåret, og presten skal segja mannen rein; for dette er berre æret etter brunesåret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Fær mann eller kvende ein sårkeflekk på hovudet eller i skjegget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'so skal presten skoda flekken, og dersom flekken synest liggja djupare enn skinnet, og det er tunne, grågule hår på honom, so skal presten segja det menneskjet ureint; då er det skurv, hår- eller skjeggsjuka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Tykkjer presten som skodar sårkeflekken, at han ikkje ligg djupare enn skinnet, men der ikkje er svarte hår å sjå, so skal han halda den skurvute innestengd i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Den sjuande dagen skal han skoda den såre flekken, og dersom skurvet ikkje hev ete seg utyver, og det ikkje hev kome grågule hår på det, og det ikkje synest liggja djupare enn skinnet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'so skal den skurvute raka seg, men ikkje på skurveflekken, og presten skal halda honom innestengd i sju dagar til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Når då presten den sjuande dagen skodar sårkeflekken endå ein gong, og skurvet ikkje hev ete um seg, og ikkje synest liggja djupare enn skinnet, so skal han segja den sjuke rein; han skal två klædi sine, so er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Er det likt til at skurvet vil eta um seg på hudi, etter den sjuke var sagd rein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'so skal presten sjå på honom, og ser han at skurvet hev breidt seg ut på skinnet hans, so treng han ikkje leita etter dei grågule håri; mannen er urein kor som er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Men synest det for hans augo som skurvet hev stana, og hev det grott svarte hår på skurveflekken, so er sjukdomen lækt; den skurvute er rein att, og presten skal segja honom rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Fær mann eller kvende mange kvite flekkjer på likamen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'so skal presten sjå deim yver. Ser han då dimme, kvite flekker på skinnet deira, so er det bohak, som hev brote ut på deim, og dei er like reine for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Um ein misser håret, og vert snaud i hovudet, so er han like rein for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Fer håret av honom framantil, so han vert fleinskalla, so er han og like rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Men syner det seg bleikraude sårkeflekkjer der han er snaud, anten det er bak eller framme i hovudet, so er det spillsykja som bryt ut i nakken eller skallen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Då skal presten skoda honom, og dersom han i nakken eller skallen hans finn bleikraude sårkenotror som likjest dei notrone ein spillsjuk kann hava på bulen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so hev sjukdomen teke honom; han er urein, og presten skal med ein gong segja honom urein; han hev fenge sjuken i hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Den som spillsykja hev råma, lyt ganga med sundrivne klæde og uflitt hår; han skal sveipa eit plagg kring skjegget og ropa: «Urein, urein!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Alt medan sjukdomen held honom, skal han gjelda for urein; for urein er han. For seg sjølv skal han bu; utanfor lægret skal han hava sitt tilhald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Kjem det åtflekkjer på eit klædeplagg, ullplagg eller linplagg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'eller på ty som er vove eller bunde av lin- eller ullgarn, eller på ler eller noko som er gjort av ler,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'og er flekkjerne som syner seg på klædeplagget eller på leret eller vevnaden eller bundingen, eller på noko som er gjort av ler, ljosgrøne eller raudvorne, so er det spillsykja, og det skal synast for presten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Når presten hev skoda det, skal han halda det som flekkjerne er på, innelæst i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Ser han so den sjuande dagen at flekkjerne på klædeplagget eller vevnaden eller bundingen eller leret, kva det so leret er nytta til, hev ete seg vidare utyver, so er det stygg spillsykja i flekkjerne; det som dei hev synt seg på, er ureint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'og skal brennast upp, anten det er eit klædeplagg eller vevnad eller bunding av ull eller lin, eller noko som er gjort av ler; det fylgjer fårleg sott med det; di skal det brennast upp i elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Ser presten at flekkjerne på klædeplagget eller vevnaden eller bundingen eller leret ikkje hev ete um seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so skal han setja folk til å två det som flekkjerne hev synt seg på, og halda det innelæst sju dagar til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Når han so skodar det etter det er tvege, og flekkjerne ikkje er annleis å sjå til enn fyrr, so er det ureint, endå skaden ikkje hev ete seg vidare utyver; det skal brennast upp i elden; for det er åt i det, på ranga eller på retta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Men ser han at flekkjerne på plagget, eller på leret eller vevnaden eller bundingen, hev bleikna etter tvåtten, so skal han skjera deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Kjem dei att sidan, på klædeplagget eller vevnaden eller bundingen, eller på noko som er gjort av ler, so er det det vonde som bryt ut på nytt lag, og då skal ein brenna upp det som flekkjerne hev synt seg på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Men dei klædi og det vovne og bundne tyet, og det leret som flekkjerne gjeng burt av når ein tvær det, det skal tvåast upp att, so er det reint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Dette er lovi um åtflekkjer på ull- eller linklæde og vevnad og bunding, og allslags ting som er gjorde av ler, so de kann vita når sovore skal haldast for reint, og når det skal haldast for ureint.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '«So er dei fyresegnerne de skal fylgja når ein som hev havt spillsykja, skal reinsast: Han skal førast fram for presten;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'og presten skal ganga utanfor lægret og sjå honom yver, og dersom han er lækt for sjukdomen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'so skal presten segja folk til å henta tvo livande reine fuglar og noko cedertre og karmesin og bergmynta til den som skal reinsast,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'og lata deim slagta den eine fuglen uppyver eit leirfat som er fyllt med kjelde- eller bekkjevatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'So skal han taka den livande fuglen og cedertreet og karmesinen og bergmynta, og duppa alt saman, den levande fuglen med, i blodet av den fuglen som er slagta yver kjeldevatnet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'og skvetta det sju vendor på den som skal reinsast etter spillsykja, og reinsa honom, og den livande fuglen skal han lata fljuga sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'So skal den som vert reinsa två klædi sine, og raka av seg alt håret, og lauga seg, so vert han rein, og sidan kann han få koma inn i lægret; men han skal halda seg utanfor tjeldbudi si i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Den sjuande dagen skal han raka seg att; både hovudhåret og skjegget og augnebrunerne, alt håret sitt, skal han raka av seg; og han skal två klædi sine, og lauga likamen sin i vatn. Då er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Den attande dagen skal han taka tvo verlamb som ikkje hev lyte, og eit årsgamalt lytelaust saulamb, og til grjonoffer tri kannor fint mjøl som er blanda med olje, og so ein halvpott med olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Og presten som stend fyre reinsingi, skal føra den som vert reinsa og alle offergåvorne hans fram for Herrens åsyn i møtetjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'So skal presten taka det eine lambet og den halve potten med olje og bera fram til skuldoffer, og svinga det att og fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Lambet skal dei slagta på same staden som dei slagtar syndofferet og brennofferet, på den heilage staden; for skuldofferet høyrer presten til liksom syndofferet; det er høgheilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'So skal presten taka noko av skuldofferblodet og strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'og han skal taka noko av den halve potten olje og hella ut i den vinstre handi si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'og so duppa den høgre peikefingeren i oljen som han hev i vinstre handi, og skvetta med fingeren av oljen sju gonger for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Noko av den oljen som er att i handi hans, skal han strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans, yver skuldofferblodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Og det som endå er att i handi hans av oljen, skal han strjuka på hovudet åt den som vert reinsa. Soleis skal presten gjera soning for honom for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'So skal presten bera fram syndofferet, so den som vert reinsa kann få soning for det som var ureint ved honom, og sidan skal han slagta brennofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Når då presten hev bore fram brennofferet og grjonofferet på altaret, og fullført soningi for honom, so er han rein att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Men er det ein fatig mann som ikkje hev råd til so mykje, so skal han taka eit lamb til skuldoffer - det skal svingast att og fram til soning for honom - og ei kanna fint mjøl, blanda med olje, til grjonoffer, og ein halv pott med olje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'og so tvo turtelduvor eller duveungar, det som han hev råd til; den eine skal vera syndoffer, og den andre brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Den åttande dagen etter han hev vorte rein, skal han bera offergåvorne fram for Herrens åsyn til møtetjelddøri, og gjeva deim til presten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Og presten skal taka skuldofferlambet og oljen og svinga det att og fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Når skuldofferlambet er slagta, skal presten taka noko av skuldofferblodet og strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'So skal han hella noko av oljen ut i den vinstre handi si');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'og med den høgre peikefingeren skvetta sju vendor for Herrens åsyn av oljen som han hev i vinstre handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Noko av den oljen som presten hev i vinstre handi, skal han strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans, yver skuldofferblodet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'og det som endå er att av oljen som presten hev i handi, skal han strjuka på hovudet åt den som vert reinsa, so han kann finna nåde hjå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'So skal han bera fram turtelduvorne eller duveungarne, det som han hadde råd til å gjeva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'den eine til syndoffer og den andre til brennoffer, og i hop med deim grjonofferet. Soleis skal presten gjera soning framfor Herrens åsyn for den som skal reinsast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Dette er dei fyresegnerne de skal fylgja når ein som hev liti råd, skal reinsast etter spillsykja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '«Når de kjem inn i Kana’ans-landet, som eg gjev dykk til eiga, og eg let det koma spillsykja på noko av husi i landet dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so skal huseigaren koma og segja frå til presten, at det hev synt seg flekkjer som likjest spillsykja på huset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Då skal presten setja deim til å rydja utor huset innan han kjem og skodar skaden, so ikkje alt som er der, skal verta ureint, og so skal han koma og skoda huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Ser han då at flekkjerne på husveggjerne ter seg som grøngule eller raudvorne sukkor, og synest liggja djupare enn veggflata,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so skal han ganga til døri og ut or huset, og halda det læst i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Den sjuande dagen skal presten koma att og sjå etter, og ser han då at skaden hev ete um seg på husveggjerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so skal han setja folk til å brjota ut dei steinarne som flekkjerne hev synt seg på, og kasta deim på ein urein stad utanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Dei skal skrapa huset innantil, rundt ikring, og leiret som dei hev skrapa av, skal dei og føra burt og kasta på ein urein stad utanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Og so skal dei taka andre steinar og setja inn i staden for dei gamle, og nytt leir skal dei taka og klina huset med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Bryt det vonde ut att på huset, etter steinarne er uttekne, og huset er skrapa og klint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so skal presten koma og sjå etter, og ser han då at skaden hev ete um seg, so er det stygg spillsykja på huset; det er ureint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'og dei skal riva det ned, både steinarne og timberet og alt leiret, og føra det ut or byen, til ein urein stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Den som gjeng inn i huset dei dagarne det er attlæst, han vert urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Den som hev lege i huset, skal två klædi sine, og det same skal den som hev ete der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Ser presten, når han kjem og skodar huset, at dei stygge flekkjerne ikkje hev ete um seg etter det vart klint, so skal han segja huset reint; for då er det vonde burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'So skal han til syndoffer for huset taka tvo fuglar og noko cedertre og karmesin og bergmynta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Den eine fuglen skal han slagta yver eit leirfat som er fyllt med kjelde- eller bekkjevatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'og so skal han taka cedertreet og bergmynta og karmesinen og den livande fuglen, og duppa det i blodet av den fuglen som er slagta, og i kjeldevatnet, og skvetta på huset sju vendor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Når han då hev reinsa huset for synd med fugleblodet og kjeldevatnet og den livande fuglen og cedertreet og bergmynta og karmesinen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'so skal han sleppa den livande fuglen ut or byen og lata honom fljuga. Soleis skal han gjera soning for huset, so det vert reint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'So er fyresegnerne um allslags spillsykja, og um skurv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'og um åtflekkjer på klæde og hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'og um notror og utbrot og ljose flekkjer på hudi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'so de kann vita når noko er ureint, og når det er reint.» Dette var lovi um spillsykja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Og Herren tala atter til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '«Tala til Israels-borni og seg til deim: «Når ein mann hev sådflod, so er han urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'So lenge flodi varer, fylgjer det ureinskap med honom, og det anten likamen gjev væta frå seg jamt eller stundom held henne inne; i båe høve er han urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Kvar lega han ligg på og kvar sess han sit på, vert urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Den som kjem nær lega hans, lyt två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Og den som set seg på noko han hev sete på, lyt og två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Like eins den som kjem nær den sjuke sjølv; han lyt två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Kjem den sjuke til å sputta på ein som er rein, so lyt den han hev sputta på två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Kvar sal og kvart vognsæte som den sjuke sit på, vert ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Den som kjem nær noko av det han hev under seg, vert urein alt til kvelds, og den som ber det burt, lyt två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Tek den sjuke burtpå nokon, og ikkje fyrst hev skylt henderne sine i vatn, so lyt den han hev teke burtpå två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Kjem den sjuke nær eit leirfat, so skal det slåast sund; men er det eit trefat, so skal det skyljast i vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Når den sjuke hev kome seg av flodi, skal han telja sju dagar fram frå di han vart god att; då skal han två klædi sine, og lauga likamen sin i kjelde- eller bekkjevatn, so er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Den åttande dagen skal han taka tvo turtelduvor eller tvo duveungar, og ganga fram i møtetjelddøri for Herrens åsyn, og gjeva deim til presten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'og presten skal ofra deim, den eine til syndoffer, og den andre til brennoffer. Soleis skal presten gjera soning for honom for Herrens åsyn, so han vert rein att etter sjukdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Når det gjeng såd frå ein mann i svevne, so skal han lauga heile likamen sin i vatn, og han er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Og alle klæde eller skinnplagg som sådet hev kome på, lyt tvåast vel, og er ureine alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Ligg ein mann hjå eit kvende, og det gjeng såd frå honom, so lyt dei båe lauga seg, og vera ureine alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Når eit kvende hev månadstidi si, og det gjeng blod frå henne, so er ho urein i sju dagar, og den som kjem nær henne, er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Alt ho ligg eller sit på medan ho hev det soleis, vert ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Den som kjem nær lega hennar, lyt två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Og den som kjem nær noko av det ho hev sete på, lyt og två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Ligg det eitkvart i sengi eller i sessen hennar, og nokon kjem nær det, so er han urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Og dersom ein mann ligg med henne, og det kjem blod på honom, so vert han og urein i sju dagar, og alt det han ligg på, vert ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Når det gjeng blod frå eit kvende i mange dagar på ei tid som ho ikkje hev månadssjuken sin, eller når blodet gjeng frå henne lenger enn vanleg i månadstidi, so er ho urein so lenge denne ureine flodi varer, liksom når ho hev månadssjuken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Um alt det ho ligg på medan ho hev blodflod, gjeld det same som er sagt um lega hennar det bil ho hev månadssjuken, og alt ho sit på, vert ureint, som når ho hev månadssjuken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Den som kjem nær det, vert urein; han lyt två klædi sine og lauga seg, og er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Vert ho god att av blodflodi, so skal ho telja sju dagar fram; so er ho rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Og den åttande dagen skal ho taka tvo turtelduvor eller tvo duveungar og bera åt møtetjelddøri, til presten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'og presten skal ofra deim, den eine til syndoffer, og den andre til brennoffer. Soleis skal presten gjera soning for henne for Herrens åsyn, so ho vert rein att etter sjukdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'De skal vara Israels-borni for det som kann gjera deim ureine, so dei ikkje skal sulka bustaden min, som eg hev reist millom deim, og lata livet for ureinska si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Dette er lovi um deim som hev flod: um menner som det gjeng såd frå, so dei vert ureine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'og um kvende som hev månadstidi si, og um folk som er flodsjuke, både menner og kvende, og um menner som ligg med ureine kvende.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Då dei tvo Arons-sønerne var slokna, dei som laut døy for di dei gjekk fram for Herrens åsyn, då tala Herren til Moses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'og sagde til honom: «Seg med Aron, bror din, at han ikkje må ganga inn i heilagdomen, innanfor forhenget og fram åt kista med kerubarne, kva tid han vil; då kunde han missa livet; for uppyver kerubarne syner eg meg i skyi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Soleis lyt Aron vera budd når han skal ganga inn i heilagdomen: Han skal hava med seg ein ung ukse til syndoffer og ein ver til brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Og han skal klæda seg i ein vigd linkjole, og hava ei linbrok på seg næst kroppen, og binda eit linbelte kring livet, og sveipa eit linplagg kring hovudet; vigde klæde lyt det vera, og fyrr han tek deim på seg, skal han lauga likamen sin i vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Og av Israels-lyden skal han få tvo geitebukkar til syndoffer og ein ver til brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'So skal Aron leida fram syndofferuksen sin, og beda for seg og huset sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Og han skal taka båe bukkarne, og leida deim fram for Herrens åsyn i møtetjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Og han skal draga strå um bukkarne, eit for Herren og eit for Azazel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Og den bukken som fell på Herrens lut, skal han leida fram og ofra til syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Men den som fell på Azazels lut, skal leidast livande fram for Herrens åsyn, og dei skal lesa bøner yver honom, og senda honom ut i øydemarki til Azazel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Når Aron hev leidt fram syndofferuksen sin, og bede for seg og huset sitt, so skal han fyrst slagta uksen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'og so skal han fylla glodfatet sitt med gløder frå altaret der elden brenn for Herrens åsyn, og taka tvo nevar med finstøytt, angande røykjelse og bera innanfor forhenget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'og han skal leggja røykjelsen på elden for Herrens åsyn, so røyken gøymer lovtavlekista med kerubarne; elles lyt han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'So skal han taka noko av ukseblodet og skvetta med fingeren fremst på kisteloket mot aust, og framanfor kista skal han skvetta med fingeren av blodet sju gonger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'So skal han slagta den bukken som er etla til syndoffer for folket, og bera blodet innanfor forhenget, og gjera med det som han gjorde med blodet av uksen: skvetta det på kisteloket og framanfor kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Soleis skal han gjera soning for heilagdomen, og reinsa honom for dei broti som Israels-borni hev sulka honom med kvar gong dei hev synda, og det same skal han gjera med heile møtetjeldet, som er reist millom deim, midt i ureinskalpen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Og det må ikkje finnast noko menneskje i møtetjeldet frå Aron gjeng inn og skal halda bøn i heilagdomen, og til han kjem ut att og hev gjort soning for seg og for huset sitt og for heile Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'So skal han ganga ut til altaret, som er reist for Herrens åsyn, og gjera soning for det: Han skal taka noko av ukseblodet og noko av bukkeblodet og strjuka rundt ikring på altarhorni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'og skvetta med fingeren av blodet på altaret sju gonger, og reinsa det for den sauren som Israels-borni hev sulka det med, og helga det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Når Aron hev fullført soningi for heilagdomen og møtetjeldet og altaret, so skal han leida fram den livande bukken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'og leggja henderne på hovudet hans, og skrifta uppyver honom alle dei brot og misgjerningar Israels-folket hev gjort so ofte dei hev synda, og leggja deim på hovudet åt bukken, og so senda honom ut i øydemarki med ein mann som stend reidug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Og bukken skal bera alle broti deira med seg til eit land som ligg langt, langt av leid. Når Aron hev sendt bukken ut i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'skal han ganga inn i møtetjeldet, og taka av seg linklædi som han hadde på seg då han gjekk inn i heilagdomen, og gøyma deim der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'So skal han lauga likamen sin i vatn på ein heilag stad, og klæda seg i den vanlege bunaden sin, og so ganga ut att, og ofra brennofferet sitt og brennofferet for folket, og gjera soning for seg og for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Og feittet av syndofferet skal han brenna på altaret, so røyken stig upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Den som hev leidt bukken burt til Azazel, lyt två klædi sine og lauga likamen sin i vatn; då fyrst kann han få koma inn i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Uksen og bukken som vart slagta til syndoffer, og som dei tok blodet av og bar inn i heilagdomen til soning, skal dei føra ut or lægret, og brenna både skinni og kjøtet og møki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Den som brenner det, lyt två klædi sine og lauga likamen sin i vatn; sidan kann han koma inn i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Og dette skal vera ei æveleg lov hjå dykk: Den tiande dagen i den sjuande månaden skal de fasta og ikkje gjera noko slag arbeid, korkje den som er fødd og boren i landet, eller den framande som held til hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'For den dagen skal dei gjera soning for dykk, og reinsa dykk for alle synderne dykkar, so de vert reine for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ei høgtidshelg skal det vera for dykk, og då skal de fasta; det skal vera ei æveleg lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Den som skal standa for soningi, er presten, han som hev vorte salva og sett til å styra preste-embættet etter far sin. Han skal klæda seg i dei heilage linklædi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'og gjera soning for det høgheilage romet og møtetjeldet og altaret; og prestarne og heila ålmugen skal han og gjera soning for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Det skal vera ei æveleg lov hjå dykk, at dei ein gong um året skal gjera soning for Israels-borni og reinsa deim for alle synderne deira.» Og Aron gjorde som Herren hadde sagt til Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '«Tala til Aron og sønerne hans og til heile Israels-folket, og seg med deim: «Høyr no kva Herren vil de skal gjera:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Er det nokon mann av Israels-ætti som slagtar ein ukse eller ein sau eller ei geit anten i eller utanfor lægret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'og ikkje leider deim fram til møtetjelddøri og ofrar Herren ei gåva framfor bustaden hans, so skal den mannen reknast jamgod med ein dråpsmann; han hev rent ut blod og skal rydjast ut or folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Difor skal Israels-borni koma til Herren med slagtofferi sine som dei er vane å slagta ute på marki, og leida deim fram åt møtetjelddøri, til presten, og slagta deim til takkoffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Og presten skal sprøyta blodet yver Herrens altar som stend framanfor møtetjelddøri, og brenna feittet til godange for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Og dei skal ikkje lenger gjeva offeri sine til dei raggute trolli som dei flyg etter. Dette skal vera ei æveleg lov for deim og etterkomarane deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Og dette skal du segja med deim: «Dersom nokon av Israels-ætti, eller av dei framande som bur millom deim, ber fram eit brennoffer eller slagtoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'og ikkje kjem til møtetjelddøri med det og ofrar det til Herren, so skal den mannen rydjast ut or folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Og dersom nokon av Israels-ætti, eller av dei framande som bur millom deim, et aldri so lite blod, so skal eg kvessa augo imot den mannen, og rydja honom ut or folket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'For livet i likamen ligg i blodet, og eg hev gjeve dykk lov til å hava blod på altaret til soning for livet dykkar. For blodet det sonar av di livet ligg i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Difor segjer eg til Israels-borni: Ingen av dykk må eta blod; dei framande som bur hjå dykk, må heller ikkje gjera det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Og når nokon av Israels-borni, eller av dei framande som bur millom deim, veider villdyr eller fuglar som dei hev lov til å eta, so skal han lata blodet renna ut på marki og hava jord yver det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'For livet i likamen, det er blodet med livet som ligg i det; difor hev eg sagt til Israels-folket: De må ikkje eta blodet av noko kvikjende! For livet i kvart kvikjende, det er blodet som er i det; kven som et det, han skal rydjast ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Hev nokon mann, anten han er fødd i landet eller han er framand, ete av eit dyr som er sjølvdaudt eller ihelrive, so skal han två klædi sine og lauga seg, og er urein alt til kvelds; sidan er han rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Tvær han ikkje klædi sine og ikkje laugar likamen sin, so gjer han ei synd som han lyt lida for.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '«Tala til Israels-folket, og seg med deim: «Eg er Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'De skal ikkje fara etter det som er skikk og sed i Egyptarlandet, der de fyrr budde, eller i Kana’ans-landet, som eg fører dykk til, og ikkje fylgja loverne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Mine bod skal de lyda, og mine lover skal de halda dykk etter og fylgja. Eg er Herren, dykkar Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'de skal halda bodi og loverne mine; held menneskja deim, so skal ho finna livet i deim. Kom i hug: eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ingen av dykk må koma innåt noko nærskyldt kvende og søkja seng med henne; kom i hug: eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Du skal hava age for lega åt far din og mor di. Ho er mor di; du skal ikkje søkja seng med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Du skal ikkje søkja seng med stykmor di; ho er vivet åt far din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Du skal ikkje søkja seng med syster di, som hev same far eller same mor som du; anten ho er fødd i eller utanfor huset, so skal du ikkje søkja seng med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Du skal ikkje søkja seng med sonedotter eller dotterdotter di; for det er ditt eige avkjøme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Du skal ikkje søkja seng med dotter åt stykmor di; ho er dotter åt far din, og ho er syster di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Du skal ikkje søkja seng med farsyster di; det er same blodet som far din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Du skal ikkje søkja seng med morsyster di; det er same blodet som mor di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du skal ikkje skjemma lega åt farbror din og koma kona hans for nær; for ho er farsyster di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Du skal ikkje søkja seng med verdotter di. Ho er vivet åt son din; du skal ikkje søkja seng med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Du skal ikkje søkja seng med brorkona di; ho er vivet åt din eigen bror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Hev du havt samlega med et kvende, so skal du ikkje søkja seng med dotter hennar; heller ikkje skal du ganga i seng med sonedotter eller dotterdotter hennar. Det er blodskam; for dei er same folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du skal ikkje gifta deg med versyster di og søkja seng med henne, medan kona di liver; for då set du hat millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du skal ikkje koma innåt noko kvende og søkja seng med henne, medan ho hev månadssjuken sin og er urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Du skal ikkje liggja hjå kona åt grannen din og på den måten gjera deg urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du skal ikkje gjeva noko av borni dine frå deg til Molok; for då vanhelgar du namnet åt din Gud. Eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du skal ikkje liggja hjå ein kar, som ein ligg med eit kvende; det er ein styggedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Med dyr må du aldri blanda deg; for då vert du urein. Og heller ikkje må kvende gjeva seg i lag med dyr og para seg med deim. Det er skjemdarferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Gjer dykk ikkje ureine med sovori åtferd! For slikt var det dei gjorde seg ureine med, dei folki som eg driv ut for augo dykkar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'då vart landet ureint, og eg heimsøkte det for broti deira, og landet støytte deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Men de skal halda bodi og loverne mine, både de sjølve og dei framande som bur millom dykk; de skal ikkje gjera noko av dei skjemdarverki');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'som dei sulka ut landet med, dei som åtte det fyre dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'for då kjem landet til å støyta dykk ut, for di de sulkar det til, liksom det støytte ut det folket som var der fyre dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'For alle dei som gjer slike skjemdarverk, dei skal rydjast ut or folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'So haldt då dei bodi eg hev gjeve dykk, og tak ikkje etter dei fæle ugjerderne som dei hadde, dei som var fyre dykk; for med det gjer de dykk ureine: Kom i hug: eg er Herren, dykkar Gud!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '«Tala til heile Israels-lyden, og seg til deim: «De skal vera heilage; for eg, Herren, dykkar Gud, er heilag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'De skal hava age for mor og far, og halda helgarne mine. Kom i hug: eg er Herren, dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'De skal ikkje venda dykk til avgudarne, og ikkje gjera dykk støypte gudar! Eg, Herren, er dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Når de ofrar eit takkoffer til Herren, skal de gjera det soleis at han kann hava hugnad av dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'De skal eta kjøtet same dagen som de ofrar, eller og dagen etter; men det som er att tridje dagen, skal de kasta på elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Den tridje dagen skal det haldast for utskjemt og ureint; et nokon av det då, so hev Herren ingen hugnad i offeret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'og den som et av det, gjer ei synd som han lyt lida for: han vanhelgar det som er vigt åt Herren, og han skal rydjast ut or folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Når de haustar kornet av åkrarne dykkar, so skal du ikkje skjera for vel utåt reini, og det som vert liggjande att etter skurden, skal du ikkje plukka upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Heller ikkje skal du sanka dei bæri som er att på trei etter du hev hausta vinhagen din, eller henta upp deim som er neddotne. Deim skal du lata vera att til dei fatige og framande. Kom i hug: eg er Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'De skal ikkje stela, og de skal ikkje dylja burt det som de hev i varveitsla, og de skal ikkje svika kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'De skal ikkje sverja på lygn i namnet mitt; for då vanhelgar de namnet åt dykkar Gud. Kom i hug: eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du skal ikkje gjera urett mot grannen din, og ikkje rana ifrå honom. Det ein dagarbeidar skal hava i løn, må ikkje verta liggjande hjå deg natti yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du skal ikkje banna den som dauv er, og ikkje leggja mein i vegen for den som er blind. Du skal hava age for din Gud; eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'De skal ikkje gjera urett mot nokon på tinget; ikkje skal du halda med ein mann for di han er fatig, og ikkje skal du snilda på saki hans for di han er rik; rettferdigt skal du døma landsmannen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du skal ikkje ganga ikring og baktala folk. Du skal ikkje leggja deg ut um å få grannen din dømd frå livet. Kom i hug: eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du skal ikkje bera hat til bror din i hjarta; men du må vel tala honom til rettes, so du ikkje skal bera synd for hans skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du skal ikkje hemna deg og ikkje bera agg til nokon av landsfolket ditt, men du skal vilja grannen din likso vel som deg sjølv. Kom i hug: eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'De skal halda loverne mine! Du skal ikkje lata tvo dyr av ulikt slag para seg. Du skal ikkje så åkeren din med tvo ulike kornslag. Du skal ikkje ganga med klæde som er vovne av tvo ulike garnslag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Når ei kvinna er i tenesta hjå ei mann som ho er trulova med, men ikkje er utløyst eller frigjevi, og so ein annan mann ligg med henne og skjemmer henne, so skal ein fylgja deim med retten, men dei skal ikkje straffast på livet, etter di ho ikkje var fri kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Han skal til bot for brotet sitt koma til møtetjelddøri med ein ver, som skal vera skuldoffer åt Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'og når presten hev gjort soning for honom hjå Herren med skuldofferveren, skal han få tilgjeving for den syndi han hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Når de kjem åt landet dykkar, og plantar allslags frukttre, so skal de halda den fyrste frukti dei ber for urein; tri år skal trei vera ureine for dykk, og de må ikkje eta frukti deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Det fjorde året skal all frukti vigjast åt Herren med ei takkehøgtid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Fyrst i det femte året må de eta frukti deira, so skal dei bera so mykje meir åt dykk sidan. Kom i hug: eg er Herren, dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'De må ikkje eta noko med blodet i. De skal ikkje fara med spådoms- eller trollkunster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'De skal ikkje rundklyppa håret dykkar, og ikkje stytta skjegget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'De skal ikkje skjera dykk i holdet av sorg yver ein som er avliden, og ikkje brenna inn bokstaver eller bilæte på likamen dykkar. Kom i hug: eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du skal ikkje vanhelga dotter di, og lata henne verta skjøkja, so folket vert usedugt og landet fullt av ulivnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'De skal halda helgarne mine, og hava age for heilagdomen min. Eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Gakk ikkje til deim som manar fram draugar og spåvette! Lat deim ikkje spå dykk; for med de gjer de dykk ureine. Kom i hug: eg er Herren, dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'For dei grå håri skal du reisa deg og æra den som gamall er; du skal hava age for din Gud. Kom i hug: eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Når ein framand bur hjå deg og held til i landet dykkar, so skal de ikkje vera hard med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'han skal vera for dykk som ein av landsmennerne dine, og du skal vilja honom likso vel som deg sjølv; for de var og framande i Egyptarlandet. Kom i hug: eg er Herren, dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'De skal ingen urett gjera, korkje på ting eller torg; rett famn og rett aln,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'rett vegt og rette lodd, rett skjeppa og rett kanna skal de bruka. Eg er Herren, dykkar Gud, som fylgde dykk ut or Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Agta vel på alle loverne og retterne mine, og liv etter deim! Kom i hug: eg er Herren!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '«Seg til Israels-folket: «Hender det at nokon av Israels-mennerne, eller av dei framande som held til i Israel, gjev noko av borni sine frå seg til Molok, so skal han lata livet: landslyden skal steina honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Og eg vil kvessa augo mot den mannen, og rydja honom ut or folket hans, for di han hev gjeve Molok barnet sitt og sulka heilagdomen min og vanhelga mitt heilage namn:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'um landslyden let att augo og ikkje læst sjå at han gjev barnet sitt til Molok, og ikkje drep honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so vil eg kvessa augo mot honom og mot ætti hans, og rydja honom ut or folket hans, både honom og alle deim som fylgjer i fotfaret hans, og held seg med Molok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Gjeng nokon til deim som manar fram draugar og spåvette, og held seg med deim, so vil eg kvessa augo mot honom og rydja honom ut or folket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'De skal helga dykk og vera heilage; for eg, Herren, er dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Agta vel på loverne mine, og liv etter deim! Kom i hug: eg er Herren, som helgar dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Den som bannar far sin og mor si, han skal lata livet. Han hev banna far og mor: blodet hans kjem på honom sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Den som held seg med ei gift kona, med kona åt grannen sin, han skal lata livet, både han og den kona han hev halde seg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Ligg nokon med stykmor si, so skjemmer han æra åt far sin; dei skal båe lata livet, og blodet deira kjem på deim sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Ligg nokon hjå sonekona si, so skal dei båe lata livet. Dei hev gjort eit skjemdarverk, og blodet deira kjem på deim sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Ligg nokon hjå ein kar, som ein ligg hjå eit kvende, so gjer dei båe ei stygg gjerning; dei skal lata livet; blodet deira kjem på deim sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Tek nokon både mor og dotter til kona, so er det blodskam; dei skal brennast på bål, både han og dei; sovori sedløysa må ikkje finnast hjå dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Blandar nokon seg med eit dyr, so skal han lata livet, og dyret skal de drepa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Og held ei kvinna seg innåt eit dyr og parar seg med det, so skal de slå i hel både kvinna og dyret. Dei som gjer slikt, skal lata livet, og blodet deira kjem på deim sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Tek nokon syster si, som hev same far eller same mor som han, og søkjer seng med henne, og ho med honom, so er det blodskam, og dei skal rydjast ut for augo åt landslyden. Han hev søkt seng med syster si: han lyt lida for brotet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Ligg nokon med ei kvinna medan ho hev månadssjuken sin, og nækjer blygsli hennar, tek han dekkjet av kjelda hennar, og ho nækjer blodkjelda si, so skal dei båe rydjast ut or folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Du skal ikkje søkja seng med morsyster eller farsyster di; den som det gjer, skjemmer si eigi ætt: dei lyt lida for brotet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Ligg nokon hjå kona åt farbror sin, so vanærar han farbror sin: dei lyt lida for syndi si, og skal døy barnlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Gifter nokon seg med brorkona si, so er det ei skam; han hev vanæra bror sin: dei skal ikkje få born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'So lyd då alle bodi og alle loverne mine, og liv etter deim, so landet ikkje skal støyta dykk ut att, det landet som eg fører dykk til og vil lata dykk bu i!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Far ikkje etter skikkarne åt det folket som eg jagar ut for dykkar skuld! Dei gjorde alt dette; då fekk eg stygg til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'og eg sagde til dykk: De skal få landet deira, eit land som fløymer med mjølk og honning; eg vil gjeva dykk det til eiga, eg, Herren, dykkar Gud, som hev skilt dykk ut frå alle andre folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Difor skal de skilja millom reine og ureine dyr og reine og ureine fuglar, og ikkje gjera dykk sjølve ufysne med å eta dei dyri eller fuglarne eller noko av det kreket som eg hev skilt ut, og sagt de skal halda for ureine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'De skal vera meg heilage; for eg, Herren, er heilag, og eg hev skilt dykk ut frå alle andre folkeslag, so de skal høyra meg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Er det nokon mann eller noko kvende som fer med å mana fram draugar eller spåvette, so skal dei lata livet: dei skal steinast i hel, og blodet deira kjem på deim sjølve.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Og Herren sagde til Moses: «Tala til prestarne, Arons-sønerne, og seg med deim: «Ein prest må ikkje gjera seg urein for landsmennerne sine med å røra noko lik,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'minder det er ein av hans næmaste skyldfolk, anten mor eller far eller son eller dotter eller bror,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'eller ei syster som var møy og endå høyrde til ætti, med di ho ikkje var burtgift; henne kann han koma nær, um ho ligg lik;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'men ei som var gift kona, må han ikkje røyva; for då gjer han seg urein for landsfolket sitt, og vanhelgar seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Prestane må ikkje raka seg snaude i kruna, og ikkje stytta skjegget sitt, og ikkje skjera seg i holdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Heilage skal dei vera for sin Gud, dei må ikkje vanhelga namnet hans; for det er dei som ber fram eldofferi åt Herren, maten åt deira Gud; di skal dei vera heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ingen av deim må gifta seg med ei skjøkja eller ei kvinna som er utskjemd, heller ikkje med ei som er skild frå mannen sin; heilag skal presten vera for sin Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'og du skal halda honom heilag; for det er han som ber fram maten åt din Gud: heilag skal han vera deg; for eg er heilag, eg, Herren, som helgar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Og dersom ei prestedotter skjemdar seg med ulivnad, so vanhelgar ho far sin: ho skal brennast på bål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Den presten som er yver alle brørne sine, han som fær salvingsoljen på hovudet sitt, og vert vigd til øvsteprest og klædd i den heilage bunaden, han må ikkje ganga med uflitt hår, og ikkje riva sund klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Han må ikkje ganga inn til noko lik; ikkje far eller mor di heller må han koma nær, etter dei hev andast; for då vert han urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Han må ikkje ganga ut or det heilage huset, so han vanhelgar heilagdomen åt sin Gud; for vigsla av Guds salvingsolje er yver honom. Eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Han skal taka ei rein møy til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Ei enkja, eller ei kvinna som er fråskild eller utskjemd, eller ei skjøkja, slik ei må han aldri gifta seg med. Berre ei møy av folket sitt må han egta;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'elles vanhelgar han ætti si millom folket. Kom i hug: det er eg, Herren, som hev helga honom!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '«Tala til Aron og seg: «Er det nokon av ætti di no eller i komande tider, som hev eit lyte, so må han ikkje ganga innåt og bera fram maten åt sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Ingen som det er noko lyte på, må ganga innåt, ingen som er blind eller halt eller haremynt, eller hev ein vanskapt lem');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'eller ein broten fot eller arm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'eller som er krylryggja eller skinnturr, eller som hev ein kvit flekk på augnesteinen, eller hev skabb eller gardorm eller slit i pungarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Ingen etterkomar av Aron, presten, som hev noko lyte, må ganga innåt og bera fram eldofferi åt Herren; det er lyte på honom: han må ikkje ganga innåt og bera fram maten for sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Han må nok eta av retterne åt sin Gud, både dei høgheilage og dei heilage;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'men etter di det er lyte på honom, må han ikkje ganga fram til forhenget, og ikkje koma innåt altaret; for då vanhelgar han heilagdomarne mine. Kom i hug: det er eg, Herren, som hev helga deim.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Og Moses sagde alt dette til Aron og sønerne hans og til heile Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '«Seg til Aron og sønerne hans at dei lyt sjå seg vel fyre med dei heilage gåvorne som Israels-folket vigjer åt meg, so dei ikkje vanhelgar mitt heilage namn. Eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'So skal du segja med deim: «Dersom nokon av ætti dykkar, no eller i framtidi, røyver dei heilage gåvorne som Israels-folket vigjer åt Herren, medan det er noko ureint på honom, so skal han rydjast burt or augnesyni mi. Kom i hug: eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ingen av etterkomarane hans Aron som er spillsjuk eller hev sådflod, må eta av dei vigde gåvorne, fyrr han er rein att. Kjem ein av deim nær nokon som hev vorte urein av eit lik, eller gjeng sådet frå honom um natti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'eller kjem han innåt noko krek som folk vert ureine av, eller noko menneskje som på ein eller annan måte hev vorte ureint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'hev nokon av deim røyvt noko sovore, so er han vera urein alt til kvelds, og må ikkje eta av dei vigde gåvorne, fyrr han hev lauga likamen sin i vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Når soli hev gladt, er han rein att, og sidan kann han eta av dei vigde gåvorne; for det er maten hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Det som er sjølvdaudt eller ihelrive, må han ikkje eta; då vert han urein. Kom i hug: eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Dei skal halda dei bodi eg hev gjeve deim, so dei ikkje ber synd for slike ting og lyt døy for di dei hev vanhelga det som er heilagt. Kom i hug: det er eg, Herren, som hev helga det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ingen framand må eta av det som heilagt er. Ingen som er busete eller leigekar hjå ein prest, må smaka på dei vigde rettarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Men hev presten kjøpt seg ein tenar for pengar, so kann han eta av deim; like eins dei tenarane som er fødd i huset hjå presten: dei kann eta av maten hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Når ei prestedotter er gift med ein framand mann, so må ho ikkje eta av dei heilage offergåvorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Men hev ho vorte enkja, eller er skild frå mannen, og ikkje hev born, og ho so kjem attende til far sin og bur i huset heime hjå honom liksom i ungdomen, so kann ho eta av maten åt far sin; men ingen uskyld må eta av den maten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Hev nokon ete uviljande av dei vigde gåvorne, so skal han gjeva presten lika for det, og leggja attåt femteparten av verdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'De må ikkje vanhelga dei heilage gåvorne frå Israels-folket - det som dei vigjer åt Herren -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'og lata deim føra syndeskuld yver seg med å eta av dei heilage retterne dykkar. Kom i hug: det er eg, Herren, som helgar deim!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '«Tala til Aron og sønerne hans og til heile Israels-folket, og seg til deim: «Når nokon av Israels-ætti eller av dei framande i Israel kjem med ei offergåva, anten det er ei som er utlova, eller ei gåva i godvilje som dei vil bera fram til brennoffer åt Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'då lyt offeret vera so at de kann tekkjast Herren med det: ein lytelaus ukse eller ver eller bukk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Noko som det er lyte på, må de ikkje bera fram; for det tekkjest de ikkje Herren med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Og når nokon ber fram eit takkoffer åt Herren av storfeet eller småfeet, anten det er ein lovnad han vil løysa, eller det er ei gåva i godvilje, so lyt det vera eit lytelaust dyr, dersom offeret skal tekkjast Herren; det må ikkje finnast nokor veila på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Dyr som er blinde eller beinbrotne eller skamførde, eller som hev verksår eller skabb eller gardorm, deim må de ikkje bera fram for Herren og leggja på altaret hans til offermat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Ein ukse eller sau som hev for lange eller for stutte lemer, kann du hava til eit offer i godvilje; men til lovoffer høver dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Gjelde dyr, anten dei er klakka eller kruste eller rivne eller skorne, skal de ikkje bera fram for Herren. Ikkje skal de gjera slikt i dykkar eige land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'og ikkje skal de kjøpa sovorne dyr av framande, og bera dei fram til mat for dykkar Gud; for dei er utskjemde, det er lytedyr: med slike offer vinn de ikkje Guds nåde.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Og Herren tala endå meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '«Når ein kalv eller eit lamb eller eit kid er tilkome, skal dei fylgja mor si sju dagar; men frå den åttande dagen og sidan vil Herren tekkjast med deim, i fall de ber dei fram til offermat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Kui og kalven hennar eller søya og lambet hennar skal de ikkje slagta på ein dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Når de ber fram eit lov- og takkoffer, skal de gjera det so at Herren hev hugnad av dykk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'De skal eta det upp same dagen, og ikkje leiva noko av det til morgons. Kom i hug: eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'So haldt då bodi mine, og liv etter deim! Eg er Herren:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Vanhelga ikkje mitt heilage namn, men lat det helgast hjå Israels-folket! Kom ihug: eg er Herren, som hev helga dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'og som fylgde dykk ut or Egyptarlandet og vil vera dykkar Gud - eg, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '«Tala til Israels-folket, og seg til deim: «No skal eg nemna dykk Herrens høgtider, dei dagarne som de skal kalla folket i hop til eit heilagt møte og halda høgtid for meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Seks dagar lyt de arbeida og vera onnuge; men den sjuande dagen skal vera heil kviledag, med heilagt møte. Då må de ikkje gjera noko arbeid; i alle heimarne dykkar skal det vera ein kviledag, vigd åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Herrens høgtider, dei heilage møti som de skal kalla i hop, kvart på si visse tid, det er desse:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Den fjortande dagen i den fyrste månaden, soleglads bil, tek Herrens påskehelg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Og den femtande dagen i den same månaden skal de halda søtebrødhelgi for Herren. I sju dagar skal de eta usyrt brød;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'den fyrste dagen skal de halda eit heilagt møte, og må ikkje gjera noko utearbeid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'og alle dei sju dagarne skal de bera fram offermat åt Herren; den sjuande dagen skal de og halda eit heilagt møte, og noko utearbeid må de ikkje gjera då heller.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '«Tala til Israels-folket, og seg med deim: «Når de kjem til det landet som eg vil gjeva dykk, og haustar inn kornet der, so skal de koma til presten med det fyrste kornbandet av nygrøda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'og han skal svinga det att og fram for Herrens åsyn, so Herren kann hava hugnad av dykk; dagen etter helgi skal presten svinga kornbandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Og same dagen som de svingar kornbandet, skal de bera fram eit årsgamalt lamb som er lytelaust, til brennoffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Grjonofferet som fylgjer med, skal vera tvo kannor fint mjøl, blanda med olje - då er det ein offerrett åt Herren, som gjev god ange - og drykkofferet ei halv kanne vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Og brød eller steikte aks eller rått korn må de ikkje eta fyre den dagen, ikkje fyrr de hev bore fram den gåva som er etla åt dykkar Gud. Det skal vera ei æveleg lov for dykk og etterkomarane dykkar i kvar ein heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Frå den fyrste dagen etter helgi, frå den dagen de bar fram kornbandet som skulde svingast for Herrens åsyn, skal de telja sju fulle vikor:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'femti dagar skal de telja, til dagen etter den sjuande vika, og då skal de bera fram eit nytt grjonoffer for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Tvo vigslingsbrød skal de koma med frå heimarne dykkar; i deim skal det vera tvo kannor fint mjøl, og dei skal vera syrte; det skal vera nygrødeoffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Og attåt brødet skal de bera fram sju årsgamle lytelause lamb og ein ung ukse og tvo verar til brennoffer åt Herren, og det grjonofferet og dei drykkofferi som fylgjer med: det er ein offerrett for Herren, som det angar godt av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Til syndoffer skal de ofra ein geitebukk, og til takkoffer tvo årsgamle lamb;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'deim skal presten svinga att og fram for Herrens åsyn saman med nygrødebrødet; dei skal vigjast åt Herren, og høyra presten til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Og same dagen skal de kalla folket i hop, og halda eit heilagt møte; de må ikkje gjera noko utearbeid den dagen. Dette skal vera ei æveleg lov for dykk og etterkomarane dykkar i kvar ein heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Og når de haustar kornet av åkrane dykkar, skal du ikkje skjera kornet for vel utåt reini, og dei aksi som ligg att etter skurden, skal du ikkje plukka upp; du skal etla deim att åt dei fatige og framande. Kom i hug: eg er Herren, dykkar Gud!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '«Tala til Israels-folket og seg: «Den fyrste dagen i den sjuande månaden skal de halda helg; då skal luren ljoma og minna dykk, og de skal halda eit heilagt møte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Den dagen må de ikkje gjera noko utearbeid, og de skal bera fram offermat for Herren.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '«So den tiande dagen i den same sjuande månaden er det soningsdag. Det skal vera ein heilag møtedag for dykk, og de skal fasta og bera fram offermat for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Den dagen må de ikkje gjera noko arbeid; for det er soningsdag; då skal dei gjera soning for dykk framfor åsyni åt Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Alle som ikkje fastar den dagen, skal rydjast ut or ætti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Og den som gjer noko arbeid, honom vil eg tyna midt ibland folket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ikkje det minste grand må de gjera den dagen; det skal vera ei æveleg lov for dykk og etterkomarane dykkar i kvar ein heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ein kvile- og helgedag skal det vera for dykk, og de skal fasta; frå niande dags kvelden i den månaden til kvelden etter skal de halda heilagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Og Herren tala endå meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '«Tala til Israels-folket og seg: «Frå den femtande dagen i den same sjuande månaden skal de halda lauvhyttehelg for Herren i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Den fyrste dagen skal de halda eit heilagt møte, og noko utearbeid må de ikkje gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sju dagar skal de bera fram offermat for Herren; og den åttande dagen skal de halda eit heilagt møte, og bera fram offermat for Herren. Då er det stor samlingshøgtid, og de må ikkje gjera noko utearbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Dette er dei høgtiderne då de skal kalla folket i hop til heilagt møte og bera fram offer for Herren: brennoffer og grjonoffer, slagtoffer og drykkoffer, kvart til si tid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'umfram Herrens kviledagsoffer, og umfram gåvorne dykkar og alle dei offeri de hev lova, eller kjem til Herren med av dykk sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Men frå den femtande dagen i den sjuande månaden, når de samlar grøda i hus, skal de høgtida Herrens pilegrimshelg i sju dagar. Den fyrste dagen skal det halda heilag, og den åttande dagen skal det halda heilag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Og den fyrste dagen skal de taka fagre frukter og palmegreiner og lauvrike buskor og seljekvister, og gleda dykk for Guds åsyn i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Soleis skal de kvart år halda pilegrimshelg for Herren i sju dagar; det skal vera ei æveleg lov for dykk og etterkomarane dykkar. I den sjuande månaden skal de halda den helgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Då skal de bu i lauvhyttor i sju dagar; alle som er fødde og borne i Israel, skal bu i lauvhyttor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'so etterkomarane dykkar skal minnast at eg let Israels-sønerne bu i lauvhyttor då eg fylgde deim ut or Egyptarlandet, eg, Herren, deira Gud.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Og Moses kunngjorde Herrens høgtider for Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '«Seg med Israels-folket at dei skal koma med skir olje av sundstøytte oljeber til ljosestaken, so lamporne stødt kann setjast upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Utanfor tæpet som heng attfor lovtavlekista i møtetjeldet, skal Aron stella lamporne so dei kann lysa for Herrens åsyn frå kveld til morgon, stødt og stendigt; det skal vera ein fast sed hjå dykk og etterkomarane dykkar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'på den bjarte gullstaken skal han skipa lamporne for Herrens åsyn seint og tidleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'So skal du taka fint mjøl, og baka tolv kakebrød; i kvart brød skal det vera tvo kannor mjøl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Og deim skal du leggja i tvo rader, seks i kvar rad, på gullbordet, for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Og på kvar rad skal du leggja rein angekvåda; det skal vera eit minningsoffer for brødet, ein offerrett åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Kvar helg skal han leggja det brødet fram for Herrens åsyn, stødt og stendigt; det skal vera ei æveleg sambandsgåva frå Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Og Aron og sønerne hans skal få det og eta det på ein heilag stad; for det høyrer til det som er høgheilagt av Herrens offermat, og prestarne skal hava rett til det i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Ein som var son til ei israelitisk kona, men hadde ein egyptar til far, gjekk ein gong inn millom Israels-folket, og han og ein av Israels-mennerne kom i trætta med kvarandre i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Og son til den israelitiske kona - ho heitte Sjelomit Dibrisdotter, og var av Dans-ætti - tok til å banna Guds namn og spotta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Då førde dei honom burt til Moses, og sette honom fast til dei kunde få ein orskurd av Herrens munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '«Før spottaren ut or lægret, og alle dei som høyrde på det, skal leggja henderne på hovudet hans, og heile lyden skal steina honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Og til Israels-folket skal du segja: «Den som bannar sin Gud, lyt lida for syndi si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'og den som spottar Herrens namn, han skal lata livet; heile lyden skal steina honom i hel; anten han er framand eller fødd og boren i landet, so skal han lata livet, so sant han hev spotta Guds namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Slær nokon ein mann i hel, so skal han lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Den som slær i hel eit krøter, skal gjeva like for det, liv for liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Valdar nokon at grannen hans fær skade på likamen, so skal dei gjera det same med honom som han hev gjort med grannen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'brot for brot, auga for auga, tonn for tonn; det meinet han hev gjort ein annan, skal han sjølv få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Den som slær i hel eit krøter, skal gjeva lika for det; men den som slær i hel eit menneskje, skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Det er same retten for dykk alle, for den framande likso vel som for den som er fødd og boren i landet; for eg, Herren, er dykkar Gud.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Og Moses kunngjorde dette for Israels-folket, og dei førde spottaren ut or lægret, og steina honom i hel: Israels-mennerne gjorde som Herren hadde sagt til Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Og Herren tala atter til Moses på Sinaifjellet, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '«Tala til Israels-folket, og seg til deim: «Når de kjem til det landet som eg vil gjeva dykk, so skal landet halda helg for Herren og kvila:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Seks år skal du så åkeren din, og seks år skal du kylla vintrei dine, og sanka det som jordi gjev av seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'men det sjuande året skal vera ei kviletid for landet, ei helg som er vigd åt Herren: då skal du ikkje så åkeren din, og ikkje kylla vintrei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Det kornet som renn upp av seg sjølv etter fjorgrøda, skal du ikkje skjera, og druvorne på det ukyllte vintreet skal du ikkje sanka: Eit kvileår skal det vera for landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Og det som jordi ber i kviletidi, skal vera til føda for dykk alle: for deg og drengen din og tenestgjenta di og leigekaren og buseten som held til hjå deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'og bufeet ditt og villdyri som er i landet, skal og eta av all den grøda som veks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'So skal du telja fram sju kvileår, sju gonger sju, so tidi som svarar til dei sju kvileåri, vert ni og fyrti år;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'og den tiande dagen i den sjuande månaden skal du blåsa i lur; på soningsdagen skal de lata luren ljoma i heile landet dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Og de skal helga det femtiande året, og lysa ut fridom for alle som i landet bur. Det skal vera eit jubelår for dykk; då skal de koma attende kvar til sin odel og venda heim att kvar til si ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Eit jubelår skal det femtiande året vera for dykk: ikkje skal de så, og ikkje skal de hausta det sjølvsådde kornet, og ikkje skal de sanka druvorne av det ukyllte vintreet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'For det er eit jubelår: det skal vera heilagt for dykk; på marki skal de henta maten etter kvart som de treng honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'I jubelåret skal kvar få att odelsgarden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Når du sel noko til landsmannen din eller kjøper noko av honom, so skal de ikkje gjera urett mot kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Kjøper du jord av honom, so skal du telja dei åri som er lidne frå jubelåret, og han skal rekna etter kor mange åringar det er att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Etter som det då er mange eller få år att, skal prisen auka eller minka; for det er berre eit visst tal med avlingar han sel deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Gjer ikkje urett mot kvarandre; hav age for dykkar Gud! Kom i hug: eg, Herren, er dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Lyd loverne mine, og haldt bodi mine og liv etter deim, so skal de bu trygt i landet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'landet skal gjeva dykk grøda si, og de skal hava nøgdi å liva av, og sitja der trygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Og dersom de spør: «Kva skal me eta i det sjuande året, når me ikkje sår og ikkje samlar inn grøda vår?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'so må de vita at i det sette året vil eg senda dykk mi velsigning, og de skal få so rik ei grøda, at ho rekk til for tri år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Når de sår i det åttande året, skal de endå eta av fyrrårsavlen; alt til grøda kjem det niande året, skal de leva av den gamle avlen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Jordi må de ikkje selja for ollo; for det er eg som eig landet; de er berre framande og leiglendingar hjå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Difor skal det i heile landet dykkar gjelda løysingsrett for jord:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Dersom det gjeng ut for grannen din, og han lyt selja noko av garden sin, so skal næmaste odelsmannen koma og løysa att det som skyldingen hans hev selt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Finst det ingen som kann løysa att jordi for honom, og han sjølv fær so mykje med hand at han kann greida løysingsummen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so skal han rekna frå dei åri som er lidne sidan han selde, og gjeva den han selde til lika for det som att er; då vert eigedomen hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'men er han ikkje god til å greida det han skal ut med, so skal jordi høyra kjøparen til alt til jubelåret; i jubelåret vert ho fri og kjem under den gamle eigaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Når ein sel eit stovehus i ein by med murar ikring, so gjeld løysingsretten berre for ei tid; so lenge som eit år etter huset vart selt, skal han hava rett til å løysa det att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Vert ikkje huset attløyst fyrr eit fullt år er lide, so skal det - so framt det ligg i ein by med murar ikring - falla under den som hev kjøpt det, og høyra honom og etterkomarane hans til for godt, og det vert ikkje fritt i jubelåret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Men husi i småbyar som det ikkje er murar ikring, skal reknast til landet; dei kann løysast att, og i jubelåret vert dei frie.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Er det levitbyarne det gjeld, husi i dei byarne som høyrer Levi-sønerne til, so varer løysingsretten for alle tider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Og um nokon av Levi-sønerne ikkje løyser att eit hus han hev selt, so vert huset fritt i jubelåret, so framt det ligg i fedrebyen hans; for husi i dei byarne som høyrer levitarne til, er deira odel millom Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Heller ikkje må beitemarki kring byarne deira seljast; ho skal høyra deim til for alle tider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Når det gjeng ut for grannen din, og han ikkje kann greida seg lenger, so skal du halda handi yver honom, og han skal liva hjå deg som ein framand eller busete.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du må ikkje taka renta eller yvermål av honom; du skal hava age for din Gud, og lata grannen din liva med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du må ikkje låna honom pengar på den måten at han skal gjeva deg renta, eller mat på den måten at han skal gjeva deg noko attpå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Kom i hug: Eg er Herren, dykkar Gud, som fylgde dykk ut or Egyptarlandet og vil gjeva dykk Kana’ans-landet og vera dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Når grannen din vert utarma og lyt selja seg til deg, so skal du ikkje lata honom gjera slavearbeid for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Han skal vera hjå deg som ein leigekar eller busete, og arbeide hjå deg til jubelåret;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'då skal han flytja frå deg, både han og borni hans, og fara heim att til ætti si og fedregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'For dei er mine tenarar, eg henta deim ut or Egyptarlandet; dei må ikkje seljast som ein sel ein slave.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du må ikkje vera hard med deim; du skal hava age for din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Vil du få deg tenestdrengjer eller tenestgjentor som skal vera din eigedom, so kann du kjøpa både drengjer og gjentor av heidningarne som bur rundt ikring dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'og like eins av borni åt innflytjarane som held til hjå dykk; av deim og etterkomarane deira som bur hjå dykk og er fødde i landet dykkar, kann de kjøpa dykk tenarar som de må eiga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'og kann lata borni dykkar få i arv etter dykk med full eigedomsrett; deim kann de bruka til slavar so lenge de vil; men brørne dine, Israels-borni, må du ikkje gjera deg til herre yver - bror yver bror!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Når ein framand eller innflutt mann hjå deg kjem til velstand hjå dykk, og landsmannen din som bur innmed han, vert utarma, og lyt selja seg til den innflutte framande mannen, eller til ein som er runnen av framand rot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so kann han løysast ut att, etter han hev selt seg. Ein av brørne hans lyt då løysa honom ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'eller farbroren eller son åt farbroren eller ein annan av det næmaste skyldfolket i ætti hans; og fær han utkoma til det, so kann han løysa seg ut sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Når han då gjer upp med den han hev selt seg til, skal dei rekna ut tidi frå det året han selde seg og til jubelåret: kjøpesummen skal bytast med åretalet, og det skal vera som han hadde vore leigekar hjå honom og arbeidt etter dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Er det endå mange år att, so skal han i utløysnad leggja so mykje av kjøpesummen som svarar til dei åri;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'og er det få år att til jubelåret, so skal han gjera upp med honom for deim; han skal i utløysnad gjeva det som svarar til dei åri han er attskuldig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Han skal vera jamgod med ein leigekar som arbeider hjå ein mann år for år; du skal ikkje tola at dei fer hardt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Vert han ikkje utløyst på den måten som nemnt er, so vert han fri i jubelåret, både han og borni hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'For meg høyrer Israels-sønerne til, og er tenarane mine - mine tenarar er dei; eg henta deim ut or Egyptarlandet, eg, Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'De skal ikkje gjera dykk avgudar, og ikkje reisa gudebilæte eller minnestolpar eller setja bilætsteinar i landet dykkar og kasta dykk på kne for deim. Eg, Herren, er dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Helgarne mine skal de halda, og hava age for heilagdomen min. Kom i hug: eg er Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Lyder de no mine lover og agtar på ordi eg tala, og gjer de som eg hev sagt dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so skal eg senda dykk regnet i rette tid, når det treng det, og jordi skal gjeva si grøda, og hagetrei si alda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Treskjartidi skal vera hjå dykk til vinonni byrjar, og vinonni vara til vinteren, og de skal eta dykk mette av maten som de hev avla, og liva trygge i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Fred vil eg gjeva i landet: de skal liggja og kvila, og ingen skal skræma dykk upp; udyri, deim vil eg øyda, so dei kverv burt ifrå landet, og sverd skal’kje herja i riket;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'uvenerne skal de elta, og dei skal stupa framfor dykk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'fem av dykk skal jaga eit hundrad, og hundrad jaga ti tusund, og fiendarne falla for sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Med milda vil eg dykk møta, og lata dykk aukast og veksa og signa sambandet med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Fjorgamalt korn skal de eta, til dess de lyt rydja det undan, so de fær rom åt det nye.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Eg vil bu og byggja ibland dykk, og aldri leidast utav dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Imillom dykk vil eg ferdast, og dykkar Gud vil eg vera, og de skal vera mitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Eg er dykkar Gud, eg, Herren, som henta dykk ut or Egyptarlandet, der som de træla for andre; eg braut sund stengern’ i oket, so de kunde ganga rake.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Men vil de’kje høyra på meg, og gjer de’kje alt det eg baud dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'mismæter de mine rettar og leidest loverne mine, so de ikkje gjer som eg sagde, og bryt de sambandet med meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so gjev eg dykk likt for like: då søkjer eg dykk med fælska, med sott som tærer og brenner, sykja som sløkkjer ut augo og syg magti or livet. Til fånyttes sår de ut kornet; for uvenern’ et det de avlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Eg kvesser augo imot dykk: for fienden skal de rjuka, uvenen skal trakka dykk ned; de skal røma, um ingen er etter dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Og vil de endå’kje lyda, so skal eg refsa dykk meir, sju gonger, for synderne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Eg bryt dykkar ovmod og magt: eg gjer dykkar himmel som jarn, og jordi dykkar som kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Då øyder de nyttelaust krafti; for jordi gjev ingi grøda, og trei gjev ingi alda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Og gjer de meg endå imot, og vil de’kje høyra på meg, so slær eg dykk endå sju gonger, som synderne dykkar er verde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Imot dykk sender eg udyr som ranar borni ifrå dykk, og drep ned bufeet dykkar, og veld at de tynnest i talet, so vegarne dykkar vert aude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Og let de dykk endå’kje tukta, men driv på og gjer meg imot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'so gjer eg og dykk imot, og slær dykk endå sju gonger for alt det som de hev synda;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'eg sender eit sverd yver dykk, som skal hemna pakti de braut; og samlar de dykk i byarn’, so sender eg sott inn ibland dykk, og de skal falla i fiendehand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Eg skal minka soleis på maten, som var dykkar styrk og studnad, at tie konor skal steikja brødet åt dykk i ein omn; dei skal gjeva det att etter vegt, og de skal’kje få eta dykk mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Og høyrer de endå’kje på meg, og herder de på og trassar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so fer eg imot dykk med vreide, og refsar dykk endå sju gonger for alle syndern’ de gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Då skal de nøydast til eta kjøtet av sønerne dykkar og kjøtet av dykkar døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Eg skal øyda høgderne dykkar, og rydja solstolparne ut, og kasta dykkar eigne lik på liki av skarnsgudarne dykkar; for de byd mitt hjarta imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Eg vil leggja byarn’ i røys, og riva templi ned, og vil ikkje ansa angen som stig upp frå offeri dykkar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'eg skal gjera landet so audt, at fiendarne som bur der skal fæla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Og dykk skal eg spreida bland folki; med drege sverd skal eg elta dykk, og landet dykkar skal verta ei audn, og byarne skal verta røysar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Då skal landet få njota si kvild, alt med det lyt liggja i øyde og de er i fiendelandet - ja då skal landet få kvila og halda helgerne sine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'alt med det ligg audt, skal det kvila; då skal det få seg den helgekvildi det ikkje fekk i kvileåri, so lenge de endå budde der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Men dei av dykk som er att, skal eg gjeva slik rædsla i hjarta, med dei held til i fiendelandi, at ljoden av eit fjukande lauv skal skræma deim upp og jaga deim av, som når ein rømer for sverdet; dei skal falla, um ingen er etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Dei skal snåva og detta, ein yver hin, som dei hadde sverdet i hælarn’, endå det er ingen som elter. De skal ikkje stå dykk mot uvenern’ dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'men ganga til grunns millom heidningarne, og fiendelandet skal tæra dykk upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Og dei av dykk som endå er att, skal visna burt i fiendelandi for broti som dei hev gjort, og for broti åt federne sine; dei skal folna burt liksom dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Då skal dei stå til sine brot og broti åt sine feder, at dei fall ifrå meg, og sveik meg, og gjorde meg tvert imot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'so eg og laut stå deim imot, og dreiv deim til fiendelandet - og bøygjer dei så sine hjarto, so harde og stride dei er, og fær dei då kvitta si skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Og so skal eg minnast mitt samband med Jakob og Isak og Abram, og landet skal eg og minnast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Men landet lyt fyrst vera kvitt deim, og njota helgarne sine med det ligg audt etter deim; og dei lyt bøta si skuld, etter di dei vanda mi lov, og bodet mitt baud deim imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Men endå um det er so, og dei er i fiendelandet, vil eg ikkje vanda deim reint eller skjota deim heiltupp ifrå meg: eg vil ikkje rydja deim ut og brjota sambandet med deim; for eg, Herren, er deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Eg vil minnast mi pakt med dei gamle, som eg henta ut or Egyptarland midt for augo på heidningefolki, og var deira Gud, eg, Herren!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dette er dei bodi og rettarne og loverne som Herren sette millom seg og Israels-folket på Sinaifjellet og let Moses kunngjera for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '«Tala til Israels-folket, og seg til deim: «Når ein hev lova å vigja seg sjølv eller eit anna menneskje til Herren, og sidan vil løysa seg frå lovnaden med penger, so skal du verdsetja den som er burtlova:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Verdet på ein mann som er millom tjuge og seksti år, skal vera femti sylvdalar i heilag mynt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'er det eit kvende, so skal du setja verdet til tretti dalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Eit menneskje som er millom fem år og tjuge år, skal du setja i tjuge dalar dersom det er ein kar, og i ti dalar dersom det er eit kvende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Er det eit barn millom ein månad og fem år, so skal verdet på ein gut vera fem sylvdalar, og på ei gjenta tri sylvdalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Deim som er seksti år eller meir, skal du setja i femtan dalar i fall det er menner, og i ti dalar i fall det er kvende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Er nokon so fatig at han ikkje kann greida ut pengarne, so skal dei koma til presten med honom, og presten skal setja verdet etter hans utkoma som gjorde lovnaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Er det eit dyr som er burtlova, eit av deim som folk ber fram til offer for Herren, so skal alt ein gjev Herren av slikt, reknast for heilagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Ein må ikkje byta det um eller gjeva eit anna dyr i staden, korkje eit ringt for eit godt eller eit godt for eit ringt. Byter ein det like vel i eit anna dyr, so skal båe tvo gjelda for heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Men er det eit ureint dyr, eit av deim ein ikkje kann gjeva Herren i offergåva, so skal det leidast fram for presten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'og presten skal verdsetja det, etter som det er til, godt eller ringt; det som presten set det i, det skal vera prisen på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Vil eigaren løysa det att, so lyt han leggja femteparten meir enn det er verdsett til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Når ein hev lova å vigja huset sitt til Herren, so skal presten verdsetja det etter som det er til, godt eller ringt, og det som presten set det i, skal gjelda for rette verdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Vil den som hev lova burt huset løysa det att, so skal han leggja femteparten yver det verdet; då vert det hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Når ein hev lova burt noko av odelsjordi si til Herren, so skal verdet retta seg etter sådmengdi: ein åker på halvtridje tunnesåd bygg skal svara til femti sylvdalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Hev han lova burt jordi alt ifrå jubelåret, so skal det verdet gjelda fullt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Men er det etter jubelåret han hev lova henne burt, so skal presten rekna ut verdet etter dei åri som er att til komande jubelår, og prisen skal setjast ned etter måten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Hev ein lova Herren eit stykke av jordi si, og sidan vil løysa det, skal han leggja femteparten yver verdet, so skal han få det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Løyser han det ikkje, og like vel sel det til ein annan, so kann det ikkje løysast meir;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'når då jubelåret kjem, og jordi vert fri, skal ho høyra Herrens heilagdom til, liksom jord som er vigsla; presten skal hava eigedomsretten til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Når ein hev lova Herren eit stykke jord som han hev kjøpt, og som ikkje er hans odel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so skal presten rekna ut verdet til komande jubelår, og mannen skal greida ut pengarne med det same, og vigja deim åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'I jubelåret fell jordi attende til den han kjøpte av, og som hev odelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'All verdsetjing skal vera i heilag mynt, etter tjuge gera i dalaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Det som er frumbore i buskapen, kann ikkje lovast burt; etter di det er frumbore, er det longe Herrens eigedom; anten det er storfe eller småfe, so høyrer det Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Er det ureine dyr, so kann ein løysa deim att etter verdet, men lyt då leggja attåt femteparten; vert dei ikkje attløyste, so kann dei seljast for verdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Det som ein vigslar åt Herren av eigedomen sin, anten det er folk eller fe eller odelsjord, det kann ikkje seljast og ikkje løysast att; alt som er vigsla, er høgheilagt og høyrer Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ingen mann som er bannstøytt, kann verta attløyst; han lyt lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'All tiend av jordi, av grøda på marki og av alda på trei, høyrer Herren til, og til Herren skal ho vigjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Vil ein løysa att noko av tiendi, skal han leggja femteparten yver verdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Og av alt bufeet, både stort og smått, alt som kjem under hyrdingstaven, skal tiande kvart dyr vigjast til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Ein skal ikkje sjå etter um det er godt eller ringt, og ikkje byta det um. Vert det bytt i eit anna dyr, so skal dei høyra heilagdomen båe, og kann ikkje verta attløyste.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Dette var dei loverne som Herren gav Moses på Sinaifjellet og baud honom kunngjera for Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'So var det den fyrste dagen i den andre månaden året etter dei hadde fare frå Egyptarlandet, då tala Herren til Moses på Sinaiheidi, i møtetjeldet, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '«De skal taka tal på heile Israels-lyden etter ætter og ættgreiner, og skriva upp namni på alle karar, ein for ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'alle våpnføre menner i Israel som er tjuge år gamle eller meir, skal de mynstra, flokk for flokk, du og Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Og med dykk skal det vera ein mann av kvar ætt, den som er hovdingen for alle greinerne i ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'So heiter dei mennerne som skal vera dykk til hjelp: av Rubens-ætti: Elisur, son åt Sede’ur;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'av Simeons-ætti: Selumiel, son åt Surisaddai;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'av Juda-ætti: Nahson, son åt Amminadab;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'av Issakars-ætti: Netanel, son åt Suar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'av Sebulons-ætti; Eliab, son åt Helon;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'av Josefs-sønerne: Elisama, son åt Ammihud, av Efraims-ætti, og Gamliel, son åt Pedasur, av Manasse-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'av Benjamins-ætti: Abidan, son åt Gideoni;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'av Dans-ætti: Ahiezer, son åt Ammisaddai;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'av Assers-ætti: Pagiel, son åt Okran;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'av Gads-ætti: Eljasaf, son åt Re’uel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'av Naftali-ætti: Ahira, son åt Enan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Dette var dei som var kalla til formenner for lyden, dei høgste i fedreætterne sine, hovdingarne yver Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'So henta Moses og Aron dei mennerne som var namngjevne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'og fyrste dagen i andre månaden kalla dei lyden i hop til eit ålmannamøte; og alle som var yver tjuge år, vart innskrivne i manntalet med namn, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'soleis som Herren hadde sagt; og Moses mynstra deim på Sinaiheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Fyrst mynstra han Rubens-sønerne - deim som var ætta frå Ruben, eldste son åt Israel - og då alle våpnføre menner av Rubens-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'so var det seks og fyrti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'So mynstra han Simeons-sønerne og ætterne deira, og då alle våpnføre menner av Simeons-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'so var det ni og femti tusund og tri hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'So mynstra han Gads-sønerne og ætterne deira, og då alle dei våpnføre av Gads-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'so var det fem og fyrti tusund og seks hundrad og femti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'So mynstra han Juda-sønerne og ætterne deira, og då alle dei våpnføre av Juda-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'so var det fire og sytti tusund og seks hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'So mynstra han Issakars-sønerne og ætterne deira, og då alle dei våpnføre av Issakars-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'so var det fire og femti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'So mynstra han Sebulons-sønerne og ætterne deira, og då alle dei våpnføre av Sebulons-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'so var det sju og femti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'So mynstra han Josefs-sønerne og ætterne deira: Då alle dei våpnføre av Efraims-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'so var det fyrti tusund og fem hundrad mann;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'og då alle dei våpnføre av Manasse-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'so var det tvo og tretti tusund og tvo hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'So mynstra han Benjamins-sønerne og ætterne deira, og då alle dei våpnføre av Benjamins-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'so var det fem og tretti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'So mynstra han Dans-sønerne og ætterne deira, og då alle dei våpnføre av Dans-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'so var det tvo og seksti tusund og sju hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'So mynstra han Assers-sønerne og ætterne deira, og då alle dei våpnføre av Assers-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'so var det ein og fyrti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'So mynstra han Naftali-sønerne og ætterne deira, og då alle dei våpnføre av Naftali-folket, frå tjugeårsalderen og uppetter, var innskrivne i manntalet, ein for ein, etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'so var det tri og femti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Dette var dei som vart mynstra, dei som Moses og Aron og Israels hovdingar mynstra; og hovdingarne var tolv i talet, ein for kvar ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Og talet på deim som vart mynstra av Israels-sønerne og ætterne deira, alle dei våpnføre av Israel, frå tjugeårsalderen og uppetter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'var seks hundrad og tri tusund og fem hundrad og femti; so mange var det som vart mynstra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Levitarne og ætterne deira vart ikkje mynstra i hop med dei hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'For Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '«Levi-ætti skal du ikkje mynstra eller taka tal på saman med hitt Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Set levitarne til å stella med huset som lovi er gøymd i, og med all bunaden i det og alt som høyrer til. Dei skal føra huset og all bunaden, og dei skal taka vare på huset, og lægra seg rundt ikring det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Når huset skal flytjast, so skal levitarne taka det ned, og når det skal reisast, skal levitarne setja det upp; kjem nokon framand innåt, lyt han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Israels-sønerne skal lægra seg flokk i flokk, kvar i sitt eige læger og under sitt eige hermerke,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'men levitarne skal lægra seg kringum gudshuset, so det ikkje skal koma vreide yver Israels-lyden; for det er levitarne som skal taka vare på gudshuset.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Og Israels-borni gjorde so; dei gjorde i alle måtar som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Og Herren tala atter til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '«Israels-sønerne skal lægra seg kringum møtetjeldet, eit stykke ifrå, kvar innmed si fana og under sitt ættar-hermerke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'På framsida, mot aust, skal Juda-heren liggja, flokk i flokk, kring fana si. Hovdingen yver Juda-sønerne er Nahson, son åt Amminadab;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'og flokken hans, dei som er mynstra i Juda-ætti, er fire og sytti tusund og seks hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Jamsides med deim skal Issakars-ætti lægra seg. Hovdingen yver Issakars-sønerne er Netanel, son åt Suar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'og flokken hans, dei som er mynstra, er fire og femti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Like eins Sebulons-ætti. Hovdingen yver Sebulons-sønerne er Eliab, son åt Helon;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'og flokken hans, dei som er mynstra, er sju og femti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Heile hermagti som er mynstra i Juda-lægret, er hundrad og seks og åtteti tusund og fire hundrad mann. Dei skal vera fremst i ferdi, når de tek ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Rubens-heren med fana si skal lægra på sudsida, flokk i flokk. Hovdingen yver Rubens-sønerne er Elisur, son åt Sede’ur;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'og flokken hans, dei som er mynstra, er seks og fyrti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Jamsides med dei skal Simeons-ætti liggja. Hovdingen yver Simeons-sønerne er Selumiel, son åt Surisaddai;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'og flokken hans, dei som er mynstra, er ni og femti tusund og tri hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Like eins Gads-ætti. Hovdingen yver Gads-sønerne er Eljasaf, son åt Re’uel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'og flokken hans, dei som er mynstra, er fem og fyrti tusund og seks hundrad og femti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Heile hermagti som er mynstra i Rubens-lægret, er hundrad og ein og femti tusund og fire hundrad og femti mann; dei skal vera i andre fylkingi, når de tek på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Møtetjeldet og Levi-flokken skal vera midt imillom herarne kvar gong de tek ut; som dei lægrar seg, so skal dei fara i veg, kvar på sin stad og under si fana.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Efraims-heren med fana si skal lægra seg på vestsida, flokk i flokk. Hovdingen yver Efraims-sønerne er Elisama, son åt Ammihud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'og flokken hans, dei som er mynstra, er fyrti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Jamsides med deim skal Manasse-ætti liggja. Hovdingen yver Manasse-sønerne er Gamliel, son åt Pedasur;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'og flokken hans, dei som er mynstra, er tvo og tretti tusund og tvo hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Like eins Benjamins-ætti. Hovdingen yver Benjamins-sønerne er Abidan, son åt Gideoni;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'og flokken hans, dei som er mynstra, er fem og tretti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Heile hermagti som er mynstra i Efraims-lægret, er hundrad og åtte tusund og eitt hundrad mann. Dei skal vera i tridje fylkingi, so ofte de fer av stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Dans-heren med fana si skal lægra seg mot nord, flokk i flokk. Hovdingen yver Dans-sønerne er Ahiezer, son åt Ammisaddai;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'og flokken hans, dei som er mynstra, er tvo og seksti tusund og sju hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Jamsides med deim skal Assers-ætti liggja. Hovdingen yver Assers-sønerne er Pagiel, son åt Okran;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'og flokken hans, dei som er mynstra, er ein og fyrti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Like eins Naftali-ætti. Hovdingen yver Naftali-sønerne er Ahira, son åt Enan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'og flokken hans, dei som er mynstra, er tri og femti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Heile hermagti som er mynstra i Dans-lægret, er hundrad og sju og femti tusund og seks hundrad mann. Dei skal vera attarst i ferdi med fanorne sine kvar gong de tek i veg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Dette var dei av Israels-sønerne som vart mynstra, kvar etter si ætt; i alt var det seks hundrad og tri tusund og fem hundrad og femti mann som var mynstra i lægri, flokk etter flokk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Men levitarne vart ikkje mynstra saman med hitt Israels-folket; for det hadde Herren sagt med Moses at han ikkje skulde gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Og Israels-sønerne gjorde i eitt og alt som Herren hadde sagt med Moses; soleis lægra dei seg under fanorne sine, og soleis drog dei fram, kvar etter si ætt og med sine frendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'No skal me nemna ætti åt Aron og Moses som ho var den tid Herren tala til Moses på Sinaifjellet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Sønerne hans Aron heitte Nadab - han var den eldste - og Abihu og Eleazar og Itamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Det var namni på Arons-sønerne, dei som vart salva til prestar og innsette i preste-embættet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Men Nadab og Abihu døydde for Herrens åsyn, då dei bar uvigd eld fram for Herren på Sinaiheidi, og dei hadde ingi søner. Sidan stod Eleazar og Itamar fyre prestetenesta, under Arons, far sin’s, augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '«Lat Levi-ætti koma og ganga fram for Aron, øvstepresten; dei skal vera honom til hjelp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Dei skal syta for det som han og heile lyden treng når dei stend framanfor møtetjeldet, og greida alt arbeidet i gudshuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Og dei skal taka vare på alt det som høyrer til møtetjeldet, og gjera alt som skal gjerast for Israels-folket; for det er dei som skal greida alt arbeidet i gudhuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Du skal gjeva levitarne til Aron og sønerne hans: dei skal vera ei gåva til honom frå Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Og Aron og sønerne hans skal du setja til å styra preste-embættet; kjem nokon annan innåt, so skal han lata livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '«Sjå no hev eg sjølv teke ut levitarne or Israels-lyden i staden for alle dei frumborne, dei som kjem fyrst frå morsliv, hjå Israels-folket: levitarne skal vera mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'For mine er alle dei frumborne. Den dagen eg slo i hel alt som var frumbore i Egyptarlandet, vigde eg åt meg alt som er frumbore hjå Israel, både folk og fe; meg høyrar det til, meg, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Og Herren tala atter til Moses på Sinaiheidi, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '«Du skal mynstra Levi-sønerne etter ætter og ættgreiner, og alle karfolk som er yver ein månad gamle, skal du skriva inn i manntalet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'So mynstra Moses deim etter Herrens ord, so han var fyresagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Sønerne hans Levi heitte Gerson og Kahat og Merari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Og sønerne hans Gerson med ættgreinene deira heitte Libni og Sime’i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Og sønerne hans Kahat med ættgreinene deira, det var Amram og Jishar og Hebron og Uzziel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Og sønerne hans Merari med ættgreinene deira, det var Mahli og Musi. Dette var Levi-ætterne med greinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Frå Gerson er Libni-ætti og Some’i-ætti; det er dei me kallar Gersons-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Då dei var mynstra, og alle karfolk yver ein månad gamle var innskrivne i manntalet, so var det sju tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Gersons-ætterne hadde lægret attanfor gudshuset, i vest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Og hovdingen yver Gersons-greini var Eljasaf, son åt Lael.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Det som Gersons-ætterne skulde hava umsut med i møtetjeldet, det var sjølve tjeldet: åklædetæpi og raggetæpi og tekkjet yver deim, og tæpet til møtetjelddøri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'og lereftsgarden kring tunet, og tæpet i porten til tunet kring gudshuset og altaret, og togi som høyrde til, og alt som skulde gjerast med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Frå Kahat er Amrams-ætti komi, og Jishars-ætti, og Hebrons-ætti, og Uzziels-ætti; det er dei me kallar Kahats-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Då dei var innskrivne i manntalet - alle karfolk yver ein månad gamle - so var dei åtte tusund og tri hundrad mann, som skulde taka vare på dei heilage tingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Kahats-ætterne hadde lægret sitt på sudsida av gudshuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Hovdingen yver Kahats-ætti og greinerne hennar var Elisafan, son åt Uzziel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Og det dei skulde hava umsut med, var lovtavlekista og bordet og ljosestaken og altari og forhenget, og dei heilage gognerne som dei hadde til gudstenesta, og alt som skulde gjerast med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Den høgste hovdingen i Levi-ætti var Eleazar, son åt Aron, øvstepresten. Han hadde tilsynet med deim som gjorde alt som skulde gjerast i heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Frå Merari er Mahli-ætti og Musi-ætti komne; det er dei me kallar Merari-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Då dei var mynstra, og alle karfolk yver ein månad gamle var innskrivne i manntalet, so var det seks tusund og tvo hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Hovdingen yver Merari-ætti og greinerne hennar var Suriel, son åt Abiha’il. Dei hadde lægret sitt på nordsida av gudshuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Det som Merari-sønerne var sette til, det var å hava umsut med plankarne i huset, og tverstokkarne og stolparne og stabbarne, og all reidskapen, og alt som skulde gjerast med det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'og stolparne til tungarden, med stabbarne og pålarne og togi som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Framanfor gudshuset, mot aust, midt framfor møtetjeldet, på solsida, der hadde Moses og Aron og sønerne hans lægret sitt. Dei var det som bar umsut for alt som skulde gjerast i heilagdomen, alt som skulde gjerast for Israels-sønerne; kom nokon annan innåt, so laut han lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Dei som vart talde i Levi-ætti, dei som Moses og Aron talde, ætt for ætt, etter Herrens ord - alle karfolk yver ein månad gamle - var i alt tvo og tjuge tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Og Herren sagde til Moses: «Tel alle frumborne karfolk av Israels-lyden som er yver ein månaden gamle, og skriva deim inn i manntalet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'og lat so meg, Herren, få levitarne i staden for deim, og feet åt levitarne i staden for alt det frumborne feet hjå Israels-folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'So talde Moses alle dei frumborne Israels-sønerne, som Herren hadde sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Og då han hadde skrive upp namni på alle frumborne karfolk som var yver ein månad gamle, og rekna deim i hop, so var talet tvo og tjuge tusund og tvo hundrad og tri og sytti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Då sagde Herren til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '«Tak levitarne i staden for alle dei frumborne Israels-sønerne, og feet åt levitarne i staden for feet deira; og levitarne skal høyra meg til, meg, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Og i utløysnad for dei tvo hundrad og tri og sytti som det er fleire frumborne israelitar enn levitar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'skal du taka fem dalar for kvar; dei skal du taka i heilag mynt, etter tjuge gera i dalaren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'og pengarne skal du gjeva til Aron og sønerne hans i utløysnad for dei frumborne som er yver talet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'So fekk Moses løysepengarne for dei som var att av dei frumborne Israels-sønerne, då dei hine var utløyste med levitarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'av desse same frumborne Israels-borni fekk han pengarne - det var eit tusund og tri hundrad og fem og seksti dalar i heilag mynt -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'og han gav deim til Aron og sønerne hans etter Herrens ord; for so hadde Herren sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Og Herren tala atter til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '[2-3] «I Levi-ætti skal du taka tal på deim av Kahats-sønerne som er millom tretti og femti år, og som er arbeidsføre so dei kann gjera tenesta i møtetjeldet, du skal mynstre deim etter ætter og ættgreiner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, '[-]');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Det som Kahats-sønerne skal stella med i møtetjeldet, det er dei høgheilage tingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Når lægret skal flytjast, so skal Aron og sønerne hans ganga inn, og taka ned forhengtæpet, og breida det yver lovtavlekista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Ovanpå det skal dei leggja ein feld av markuskinn, og breida ein heilvoven purpurduk yver, og so setja berestengerne i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Yver skodebrødsbordet skal dei breida eit purpurklæde, og setja fati og skålerne og bollarne og drykkofferkannorne uppå det, og det dagvisse brødet skal og liggja der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Og yver alt dette skal dei breida ein karmesinraud klædesduk, og sveipa ein feld av markuskinn um det, og setja berestengerne i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'So skal dei taka eit purpurklæde og breida yver den bjarte ljosestaken og lamporne som høyrer til, og sakserne og saksplatorne og alle oljekopparne som dei hev når dei steller lamporne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'og sveipa både staken og alle desse gognerne inn i ein feld av markuskinn, og leggja det på ei berebår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Yver det gullaltaret skal dei og breida eit purpurklæde, og sveipa ein feld av markuskinn um det, og so setja berestengerne i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'So skal dei taka alle dei gognerne som dei hev til gudstenesta i heilagdomen, og leggja deim i eit purpurklæde, og sveipa ein feld av markuskinn um deim, og leggja dei på ei bår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Storaltaret skal dei reinska for oska, og breida eit skarlaksklæde yver det');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'og leggja uppå det alle gognerne som dei hev til altartenesta: glodpannorne og steikjespiti og eldskuflerne og blodbollarne, alle gognerne som høyrer til altaret, og so skal dei breida ein feld av markuskinn yver det og setja berestengene i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Og når Aron og sønerne hans er ferdige og hev sveipt inn dei heilage tingi og alle dei gognerne som høyrer til heilagdomen, og heren skal taka ut, då skal dei hine Kahats-sønerne koma og bera; men dei må ikkje røra dei heilage tingi; gjer dei det, lyt dei døy. Dette er det Kahats-sønerne skal bera av det som høyrer til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleazar, son åt Aron, øvstepresten, skal hava tilsynet med lampeoljen og den angande røykjelsen og det daglege grjonofferet og salvingsoljen, og med heile gudshuset og alt som der finst av heilage ting og gogner som høyrer til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Og Herren tala atter til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '«Lat ikkje Kahats-ætti og greinerne hennar verta utrudd or Levi-folket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Høyr no kva de skal gjera for deim, so dei kann få liva og ikkje tarv døy når dei kjem innåt dei heilage tingi: Aron og sønerne hans skal koma, og setja deim, ein for ein, til det arbeidet dei hev å gjera, og syna deim byrderne dei skal bera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Men dei må ikkje ganga inn, ikkje so mykje som ein augneblink, og skoda det heilage; for då lyt dei døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '«Av Gersons-sønerne skal du og taka tal på deim som er millom tretti og femti år,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'og er arbeidsføre so dei kann gjera det som skal gjerast i møtetjeldet, og du skal mynstra deim etter ætter og ættgreiner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Høyr no kva det er Gersons-ætterne hev å gjera, kva dei skal taka vare på, og kva dei skal føra:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'dei skal føra åklædeveverne som høyrer til gudshuset, og møtetjeldet og taket og markuskinns-tekkjet som ligg ovanpå taket, og tæpet til møtetjelddøri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'og lereftsgarden, og dørtæpet til porten åt tunet kring huset og altaret, og tjeldtogi, og alle arbeidsgreidorne som høyrer til; og alt som er å gjera med det, skal dei greida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Etter det som Aron og sønerne hans segjer, skal Gersons-sønerne retta seg i alle måtar, både med føringi og med alt anna arbeid dei hev, og de lyt setja deim fyre å taka vel vare på alt det dei førar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Dette er det Gersons-ætterne skal stella med i møtetjeldet, og Itamar, son åt Aron, øvstepresten, skal rettleida deim i alt dei hev å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'So skal du telja deim av Merari-sønerne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'som er millom tretti og femti år, og som er arbeidsføre so dei kann gjera det som skal gjerast i møtetjeldet, og du skal mynstre deim etter ætter og ættgreiner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Det dei hev å føra og skal hava umsut med i møtetjeldet, det er plankarne i huset, med tverstokkarne og stolparne og stabbarne som høyrer til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'og stolparne i tungarden, med stabbar og pålar og tog, og all reidskapen som høyrer til, og alt som skal gjerast med det, og de skal nemna for deim kvar ting som de vil hava deim til å taka vare på og føra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Dette er det Merari-ætterne skal gjera, det dei skal stella med i møtetjeldet, og Itamar, son åt Aron, øvstepresten, skal rettleida deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Då no Moses og Aron og formennerne for lyden hadde mynstra Kahats-sønerne, ætt for ætt og ættgrein for ættgrein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'so mange av deim som var millom tretti og femti år gamle, og arbeidsføre so dei kunde gjera tenesta i møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'so var det tvo tusund og sju hundrad og femti mann som var mynstra, kvar etter si ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Det var talet på deim som vart mynstra i Kahats-ætterne, deim som gjorde tenesta i møtetjeldet, og som Moses og Aron mynstra etter det bodet som Herren hadde sendt Moses med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Då Gersons-sønerne var mynstra ætt for ætt og ættgrein for ættgrein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'so mange av deim som var millom tretti og femti år gamle, og arbeidsføre so dei kunde gjera tenesta i møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'so var det tvo tusund og seks hundrad og tretti mann som var mynstra, kvar etter si ætt og ættgrein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Det var talet på deim som vart mynstra i Gersons-ætterne, deim som gjorde tenesta i møtetjeldet, og som Moses og Aron mynstra etter Herrens bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Då Merari-sønerne og ætterne deira var mynstra ætt for ætt og ættgrein for ættgrein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'so mange av dei som var millom tretti og femti år gamle, og arbeidsføre so dei kunde gjera tenesta i møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'so var det tri tusund og tvo hundrad mann som var mynstra, kvar etter si ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Det var talet på deim som vart mynstra i Merari-ætterne, deim som Moses og Aron mynstra etter det bodet som Herren hadde sendt Moses med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Då alle levitar millom tretti og femti år var talde, alle som var føre til å gjera tenesta i møtetjeldet med bering eller anna arbeid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'og Moses og Aron og Israels hovdingar hadde mynstra deim etter ætter og ættgreiner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'so var det åtte tusund og fem hundrad og åtteti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Dei vart no etter Herrens bod sette til å gjera kvar sitt arbeid og bera kvar si byrd og greida kvar si ærend, og Moses rettleide deim, som Herren hadde sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '«Seg til Israels-sønerne at dei skal senda alle spillsjuke ut or lægret, og alle som hev flod, og alle som hev vorte ureine av lik;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'anten det er menner eller kvende, so skal de hava deim burt; ut or lægret skal de senda deim, so dei ikkje skal sulka lægret dykkar, der eg bur midt imillom dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Og Israels-sønerne gjorde so, og sende deim ut or lægret. Som Herren hadde sagt med Moses, so gjorde Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '«Seg til Israels-folket: «Hev ein mann eller ei kvinna gjort ei eller onnor synd, og vore utrue mot Herren, so dei ber på ei skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'so skal dei skrifta den syndi dei hev gjort, og det dei hev kome til med urett, skal dei gjeva att alt saman, og endå leggja attåt femteparten av verdet. Dei skal gjeva det til den dei gjorde urett imot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'liver han ikkje lenger, og finst det ingen kravsmann etter honom, som dei kann greida ut boti til, so skal den boti dei lyt leggja, gjevast åt Herren og høyra presten til, umfram soningsveren, som skal ofrast til soning for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Og alle reidor, alle dei vigde gåvorne som Israels-sønerne kjem til presten med, dei skal vera hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Alt det som folk vigjer, skal han hava; det dei gjev presten skal høyra honom til.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '[12-14] «Tala til Israels-sønerne, og seg til deim: «Kjem det åbryskap yver ein mann, so han mistrur kona si, og kona hev vore utru mot honom og lagt seg burt, men han ikkje veit det visst, og det ikkje kann provast at ho hev skjemt seg ut og lege med ein annan mann, etter di ingen hev kome yver deim og kann vitne imot henne - eller kjem åbryskapen yver honom, so han mistrur kona si, ho ikkje hev skjemt seg ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, '[-]');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, '[-]');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so skal han taka kona med seg til presten, og hava med ei offergåva for henne; det skal vera ei kanna byggmjøl; men han skal ikkje slå olje på mjølet, eller leggja røykjelse attmed; for det er eit åbryskaps-grjonoffer, eit minnings-grjonoffer: som skal minna um eit brot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Presten skal leida kona fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Han skal henta vigslevatn i ei leirskål, og taka noko av dusti som er på golvet i gudshuset og hava uppi vatnet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'og når han hev leidt kona fram for Herrens åsyn, skal han løysa upp håret hennar og gjeva henne minningsofferet i henderne - eit åbryskapsoffer skal det vera - og i si hand skal han halda det vonde vatnet som valdar våde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'So skal han lata kona gjera eiden, og segja til henne: «So sant ingen annan mann hev lege hjå deg, og so sant du ikkje hev vore utru mot mannen din og skjemt deg ut, so skal du inkje mein hava av dette vonde vatnet som valdar våde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Men er det so at du hev vore utru mot mannen din og skjemt deg ut, og at ein annan enn din eigen mann hev lege hjå deg»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '- no skal presten lesa upp våbøn-eiden for kona og segja til henne -: «so skal Herren gjera deg til ei våbøn og ei banna hjå folket ditt; han skal lata mjødmi di minka og buken din bolna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'og dette vatnet som valdar våde, skal siga ned i livet ditt, so buken din bolnar og mjødmi di minkar!» Og kona skal segja: «Ja vel! Ja vel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Presten skal skriva desse våbønerne upp på eit blad, og två deim av i det vonde vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Sidan skal han lata kona drikka det vonde vatnet som valdar våde, og ulukkevatnet skal siga ned i livet hennar og valda verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'So skal presten taka åbryskapsofferet utor handi på kvinna og svinga det att og fram for Herrens åsyn, og bera det fram åt altaret;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'og han skal taka ein neve av mjølet og brenna på altaret, so røyken stig upp imot himmelen til ei minning. Og når han hev gjeve kona vatnet, og ho hev drukke det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'då skal det henda at dersom kona hev skjemt seg ut og vore utru mot mannen sin, so skal ulukkevatnet siga ned i livet hennar og valda verk; buken hennar skal bolna og mjødmi minka; og ho skal verta til ei våbøn hjå folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Men er ho rein, og ikkje hev skjemt seg ut, so skal ho vera uskadd og barnkjømd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Dette de lovi um åbryskap: når ei kona hev vore utru mot mannen sin og skjemt seg ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'eller når det kjem ei åbryskap yver ein mann, so han mistrur kona si, då skal han leida kona fram for Herrens åsyn, og presten skal gjera med henne so som er sagt i denne lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Mannen skal vera fri for skuld, men kona lyt lida for brotet sitt.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '«Tala til Israels-sønerne, og seg til deim: «Når ein mann eller kvinna hev gjort ein heilag lovnad, og vigt seg til Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'so skal dei halda seg ifrå vin og sterke drykkjer; dei må ikkje smaka vinedik eller annan sterk edik; dei må ikkje drikka nokon drykk som er tillaga av druvor, og ikkje eta druvor, korkje friske eller turre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'So lenge vigsla varer, må dei ikkje eta noko som kjem frå vintreet, ikkje ein gong kart eller visar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'So lenge vigslingslovnaden gjeld, må det ikkje koma saks på hovudet åt den som er vigd; alt til den tidi er ute som han hev vigt til Herren, skal han vera helga; han skal lata hovudhåret sitt veksa fritt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'So lenge han er vigd til Herren, må han ikkje koma innåt noko lik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Um far eller mor eller bror eller syster hans døyr, so må han ikkje for deira skuld gjera seg urein; for vigsla åt hans Gud er på hovudet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Alt medan vigsla varer, er han helga åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Brådøyr det nokon innmed honom, og fører ureinskap yver det vigde hovudet hans, so skal han raka hovudet sitt den dagen han vert rein att; den sjuande dagen skal han raka det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'og den åttande dagen skal han koma til presten, til møtetjelddøri, med tvo turtelduvor eller tvo duveungar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'og presten skal ofra deim, den eine til syndoffer og den andre til brennoffer, so han fær soning for den syndi han førde yver seg, då han kom innåt liket. So skal han same dagen helga hovudet sitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'og vigja seg for Herren for den tid han hev lova, og bera fram eit årsgamalt lamb til skuldoffer. Den fyrste vigslingstidi gjeld ikkje meir, etter di vigsla hans vart utskjemd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'So er lovi um den som hev vigt seg til Herren: Når vigslingstidi hans er ute, skal dei leida honom fram åt møtetjelddøri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'og han skal bera fram gåvorne sine for Herren: eit årsgamalt lytelaust verlamb til brennoffer, og eit årsgamalt lytelaust saulamb til syndoffer, og ein lytelaus ver til takkoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'og ei korg med søtt omnsbrød som er baka av fint mjøl, og hellekakor med olje i, og oljesmurde tunnbrødleivar, med grjonoffer og drykkoffer som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Og presten skal bera det fram for Herrens åsyn, og ofra syndofferet og brennofferet hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'og av veren skal han stella til eit takkoffer åt Herren, og bera det fram saman med søtebrødkorgi, og so skal han bera fram grjonofferet og drykkofferet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Den vigde skal raka det vigde hovudet sitt i møtetjelddøri, og taka det vigde hovudhåret sitt, og leggja det på elden som brenn under takkofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Og presten skal taka den eine bogen av veren, kokt, og ei hellekaka av deim som er i korgi, og ein tunnbrødleiv, og leggja det i henderne på den vigde, etter han hev raka av seg det vigde håret sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Desse gåvorne skal presten svinga for Herrens åsyn; dei er heilage, og skal høyra presten til, umfram svingebringa og lyftelåret. Sidan kann den vigde drikka vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Dette krev lovi av den som hev gjort vigslingslovnaden: desse gåvorne skal han bera fram for Herren attpå vigsla si umfram det han elles hev råd til; han skal fara åt som det høver med lovnaden han hev gjort, og fylgja dei fyresegnerne som gjeld for vigsla hans.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '«Tala til Aron og sønerne hans, og seg: «So skal de segja når de velsignar Israels-borni:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, '«Herren velsigne deg og vare deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herren late sit andlit lysa mot deg, og vere deg nådig!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herren lyfte si åsyn på deg, og gjeve deg fred!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Dei skal lysa mitt namn yver Israels-borni, so vil eg velsigna deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Då Moses hadde fenge reist gudshuset og salva og vigsla det, og hadde salva og vigt all husbunaden og altaret med alt som til høyrde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'då kom Israels jarlar, ættehovdingarne og fylkesstyrararne, dei som hadde stade for mynstringi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'og førde offergåvorne sine fram for Herrens åsyn; det var seks husvogner og tolv uksar, ei vogn frå tvo og tvo av hovdingarne og ein ukse frå kvar av deim. Det kom dei til gudshuset med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'og Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '«Tak i mot det av deim! De skal hava det til arbeidet ved møtetjeldet, og du skal gjeva det til levitarne, etter som kvar treng det til arbeidet sitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'So tok Moses imot vognerne og uksarne, og gav deim til levitarne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Gersons-sønerne gav han tvo vogner og fire uksar som dei skulde hava til å greida arbeidet sitt med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Og Merari-sønerne gav han fire vogner og åtte uksar som dei skulde greida sitt arbeid med; og Itamar, son åt Aron, øvstepresten, skulde rettleida deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Kahats-sønerne gav han ikkje noko; for dei skulde taka vare på dei heilage tingi, og bera deim på herdarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Den dagen altaret vart salva, kom hovdingarne med vigslegåvor, og bar deim fram åt altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Då sagde Herren til Moses: «Lat hovdingarne bera fram gåva si til altarvigsla kvar sin dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Den som bar fram gåva si fyrste dagen, var Nahson, son åt Amminadab, av Juda-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Gåva hans var eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ein halv mork, heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Nahson, son åt Amminadab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Andre dagen kom Netanel, son åt Suar, hovdingen yver Issakars-ætti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'og bar fram gåva si: eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Netanel, son åt Suar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Tridje dagen kom hovdingen yver Sebulons-sønerne, Eliab, son åt Helon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'med gåva si, og det var eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'og ei gullskål som vog ti lodd, og var fylt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Eliab, son åt Helon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Fjorde dagen kom hovdingen yver Rubens-sønerne, Elisur, son åt Sede’ur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Gåva han bar fram, var eit sylvfat som åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Elisur, son åt Sede’ur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Femte dagen kom hovdingen yver Simeons-sønerne, Selumiel, son åt Surisaddai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Gåva han hadde med seg, var eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
