INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Sette dagen kom hovdingen yver Gads-sønerne, Eljasaf, son åt Re’uel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Og gåva hans var eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
