INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Sjuande dagen kom hovdingen yver Efraims-sønerne, Elisama, son åt Ammihud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Gåva hans var eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
