INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Åttande dagen kom hovdingen yver Manasse-sønerne, Gamliel, son åt Pedasur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Hans gåva var og eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Gamliel, son åt Pedasur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Niande dagen kom hovdingen yver Benjamins-sønerne, Abidan, son åt Gideoni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Han gav eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Abidan, son åt Gideoni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Tiande dagen kom hovdingen yver Dans-sønerne, Ahiezer, son åt Ammisaddai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Det han gav var eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Ahiezer, son åt Ammisaddai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Ellevte dagen kom hovdingen yver Assers-sønerne, Pagiel, son åt Okran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Han og gav eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'og ei gullskål som vog ti lodd, og var fylt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'og til takkofferet tvo naut og fem verar og fem bukkar og fem årsgamle verlamb. Det var gåva frå Pagiel, son åt Okran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Tolvte dagen kom hovdingen yver Naftali-sønerne, Ahira, son åt Enan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'og han gav og eit sylvfat som vog åtte merker, og ein sylvbolle som vog fire og ei halv mork, etter heilag vegt, båe fyllte med fint mjøl, som var blanda med olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'og ei gullskål som vog ti lodd, og var fyllt med røykjelse,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'og ein ung ukse og ein ver og eit årsgamalt verlamb til brennoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'og til takkofferet tvo naut og fem bukkar og fem årsgamle verlamb. Det var gåva frå Ahira, son åt Enan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Dette var vigslegåvorne frå Israels hovdingar då altaret vart salva: Tolv sylvfat var det og tolv sylvbollar og tolv gullskåler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Kvart sylvfat vog åtte merker, og kvar sylvbolle fire og ei halv mork; alle sylvkopparne i hop vog hundrad og femti merker etter heilag vegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Dei tolv gullskålerne, som var fyllte med røykjelse, vog ti lodd kvar etter heilag vegt; alle gullskålerne i hop vog sju og ei halv mork.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Av brennoffer-fe var det i alt tolv uksar og tolv verar og tolv årsgamle verlamb, med grjonoffer som til høyrde, og tolv geitebukkar til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'og av takkoffer-fe fire og tjuge uksar og seksti verar og seksti bukkar og seksti årsgamle verlamb. Det var vigslegåvorne som vart framborne då altaret var salva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Då so Moses gjekk inn i møtetjeldet og skulde tala med Herren, so høyrde han ei røyst som tala til honom frå romet yver lovtavlekista millom båe kerubarne - der tala Gud til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Og Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '«Tala til Aron, og seg til honom: «Når du set upp lamporne, so skal du laga det so at alle sju lamporne kastar ljoset frametter, på romet framanfor ljosestaken.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Og Aron gjorde so: han sette upp lamporne so ljoset fall frametter, på romet framanfor ljosestaken, som Herren hadde sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Ljosestaken var av drive gull; både leggen og kruna var drive arbeid. Etter det bilætet som Herren synte Moses, hadde dei gjort ljosestaken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '«Du skal taka levitarne fram or Israels-folket og reinsa deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'So skal du fara åt når du reinsar deim: Du skal skvetta skiringsvatn på deim, og dei skal fara yver heile likamen sin med rakekniven, og två klædi sine, so dei er reine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'So skal dei taka ein ung ukse og grjonofferet som høyrer til: fint mjøl blanda med olje, og til syndoffer skal du taka ein annan ung ukse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Du skal segja med levitarne, at dei skal koma hit til møtetjeldet, og so skal du kalla i hop heile Israels-lyden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'og føra levitarne fram for Herrens åsyn. So skal Israels-sønerne leggja henderne på levitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'og Aron skal vigja deim til Herren for Israels-folket på same visi som når han svinger offeret for Herrens åsyn; og sidan skal dei tena Herren; det skal vera deira kall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'So skal levitarne leggja henderne på hovudet åt uksarne, og du skal ofra den eine til syndoffer og den andre til brennoffer åt Herren, og gjera soning for levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'So skal du då føra levitarne fram for Aron og sønerne hans, og vigja deim til Herren på same visi som når offeret vert svinga att og fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Du skal skilja levitarne ut ifrå hitt Israels-folket, og dei skal høyra meg til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'og sidan, når du hev reinsa og vigt deim, skal dei koma og gjera tenesta i møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'For dei er ei gåva til meg, ei gåva frå heile Israels-folket; eg valde meg deim i staden for det som kjem fyrst frå morsliv, alt det som er frumbore hjå Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'For mine er alle dei frumborne hjå Israels-folket, både folk og fe; den gongen eg slo i hel alt frumbore i Egyptarlandet, helga eg deim åt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Men no hev eg teke levitarne i staden for alle dei frumborne Israels-borni;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'eg tok deim fram or Israels-folket, og gav deim til Aron og sønerne hans, på den måten at dei skulde greida tenesta i møtetjeldet for Israels-sønerne og gjera soning for deim, so Israels-sønerne ikkje skal koma innåt heilagdomen og soleis føra ulukka yver seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Moses og Aron og heile Israels-lyden gjorde i alle måtar so med levitarne som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Og levitarne reinsa seg med skiringsvatnet, og tvo klædi sine, og Aron vigde deim for Herrens åsyn på same visi som når eit svingeoffer vert vigt, og gjorde soning for deim, so dei vart reine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'og so kom dei og gjorde arbeidet sitt i møtetjeldet, for augo åt Aron og sønerne hans. Som Herren hadde sagt Moses fyre, so gjorde dei med levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '«Dette er lovi som gjeld for levitarne: Frå dei er fem og tjuge år gamle, skal dei standa i tenesta og gjera alt det arbeidet som trengst i møtetjeldet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'men so snart dei hev fyllt femti år, skal dei gjeva seg utor tenesta, og ikkje arbeida lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Dei kann vera brørne sine til hjelp i møtetjeldet med eitt og anna som er å gjera der, men dei skal ikkje hava fast tenesta. Soleis skal du skipa det med levitarne og tenesta deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Året etter dei hadde fare frå Egyptarlandet, i den fyrste månaden, tala Herren til Moses på Sinaiheidi, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '«Israels-folket skal halda påskehelg på den tid som er sett:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'frå den fjortande dagen i denne månaden, solegladsbil, skal de høgtida påskehelgi si visse tid; alle dei lover og fyresegner som gjeld for påskehelgi, skal de fylgja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Då tala Moses til Israels-sønerne, og sagde dei skulde høgtida påskehelgi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'og so heldt dei påskehelg på Sinaiheidi den fjortande dagen i den fyrste månaden, solegladsbil; Israels-borni gjorde i alle måtar som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Det var nokre menner som hadde vorte ureine av eit lik, og ikkje kunde halda høgtid den dagen; dei gjekk same dagen fram for Moses og Aron');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'og sagde til honom: «Me hev vorte ureine av eit lik. Skal me for den skuld verta attsette, og ikkje få bera fram gåvorne våre for Herren i rett tid saman med hitt Israels-folket?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Då sagde Moses til deim: «Venta eit bil, so eg fer høyra kva Herren segjer um dette!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '«Tala til Israels-sønerne, og seg: «Um nokon av dykk eller etterkomarane dykkar hev vorte ureine av lik, eller er på langferd, so skal dei like fullt halda påskehelg for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Den fjortande dagen i den andre månaden, solegladsbil, skal dei eta påskelambet; attåt søtt brød og bitre urter skal dei eta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Dei må ikkje leiva noko av det til morgonen, og ikkje brjota noko bein i det. Alle dei fyresegnerne som gjeld for påskehelgi, skal dei fylgja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Men den som er rein, og ikkje er ute og ferdast, og som endå let vera å halda påskehelg, han skal rydjast ut or ætti si, for di han ikkje hev bore fram gåvorne til Herren i rette tid; den mannen skal lida for syndi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Og når ein framand som held til hjå dykk, vil halda påskehelg for Herren, so skal han og fylgja dei fyresegnerne og loverne som gjeld for påskehelgi. Det skal gjelda ei lov for dykk alle, for den framande so vel som den som den som er fødd og alen i landet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Den dagen gudshuset vart reist, sveipte skyi seg kringum huset, um tjeldet som gøymde Guds lov; men um kvelden var det som ein eld å sjå yver huset, og den heldt seg der alt til morgonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Og soleis var det stødt: um dagen låg det ei sky yver gudshuset, og um natti ein eldsljoske.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Og kvar gong skyi letta seg upp ifrå tjeldet, tok Israels-sønerne ut, og der som skyi let seg ned, der lægra dei seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'etter Herrens ord tok dei ut, og etter Herrens ord slo dei læger; men so lenge skyi låg yver gudshuset, heldt dei seg i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Låg skyi lenge yver gudshuset, so retta Israels-borni seg etter det som Herren hadde sagt, og tok ikkje ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Stundom låg skyi berre nokre få dagar yver gudshuset; då heldt dei seg i ro so lenge Herren vilde, og tok ut når han vilde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Stundom låg skyi der berre frå kveld til morgon; då tok dei ut um morgonen, med same skyi lyfte seg. Eller ho låg der ein dag og ei natt; når ho då hov seg upp, tok dei ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Eller ho låg der eit par dagar, eller ein månad, eller endå lenger. Når skyi drygde so lenge, og vart liggjande yver gudshuset, heldt Israels-folket seg i lægret og tok ikkje ut; men so snart ho steig til vers, tok dei ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Etter Herrens ord lægra dei seg, og etter Herrens ord tok dei ut. Dei retta seg etter Herrens vilje, soleis som Moses hadde sagt deim frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '«Gjer deg tvo lurar av drive sylv! Deim skal du hava til å kalla lyden i hop med, og til å varsla folket når lægret skal flytjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Blæs de i båe, so skal heile lyden samla seg hjå deg framanfor møtetjelddøri;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'blæs de berre i ein, so skal styresmennerne, hovdingarne yver Israels-ætterne, samla seg hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Blæs de alarm, so skal dei flokkarne fara i veg som hev lægret sitt i aust;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'blæs de alarm andre venda, so skal dei som ligg i sud taka ut. Alarm skal de blåsa kvar gong de bryt upp frå lægret;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'men når du vil kalla folket i hop til ålmannamøte, skal de låta lint i lurarne, og ikkje blåsa alarm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Arons-sønerne, prestarne, er det som skal blåsa i deim. Dette skal vera ei æveleg lov hjå dykk, frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Og når de fær ufred i landet, og fienden bryt på dykk, so skal de blåsa sterkt i lurarne; då skal Herren, dykkar Gud, koma dykk i hug, so de vert berga for uvenerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Og på glededagarne dykkar og høgtiderne og nymånedagarne skal de låta i lurarne til brennofferi og takkofferi dykkar, so det kann minna dykkar Gud um dykk. Eg, Herren, er dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Tjugande dagen i andre månaden i det andre året lyfte skyi seg upp ifrå gudshuset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Då tok Israels-sønerne ut frå Sinaiheidi, flokk for flokk, etter som dei var fylkte; og skyi let seg ned att i Paranheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Dette var fyrste gongen dei braut lægret, og det var etter Herrens bod, som Moses hadde kunngjort for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Fyrst tok Juda-heren ut med fana si, flokk i flokk. Det var Nahson, son åt Amminadab, som stod yver Juda-flokken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'yver Issakars-flokken stod Netanel, son åt Suar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'og yver Sebulons-flokken Eliab, son åt Helon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Kvar gong gudshuset var teke ned, for Gersons-sønerne og Merari-sønerne i veg, dei som førde huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'So tok Rubens-heren ut med fana si, flokk i flokk. Det var Elisur, son åt Sede’ur, som stod yver Rubens-flokken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'yver Simeons-flokken stod Selumiel, son åt Surisaddai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'og yver Gads-flokken Eljasaf, son åt Re’uel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'So tok Kahats-sønerne i veg, dei som bar dei høgheilage tingi, og fyrr dei kom fram, hadde dei hine reist huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'So tok Efraims-heren ut med fana si, flokk i flokk. Det var Elisama, son åt Ammihud, som stod yver Efraims-flokken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'yver Manasse-flokken stod Gamliel, son åt Pedasur,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'og yver Benjamins-flokken Abidan, son åt Gideoni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'So tok Dans-heren ut med fana si, flokk i flokk: Dei var attarst i fylkingi. Det var Ahiezer, son åt Ammisaddai, som stod yver Dans-flokken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'yver Assers-flokken stod Pagiel, son åt Okran,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'og yver Naftali-flokken Ahira, son åt Enan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Soleis var Israels-sønerne fylkte når dei for i veg, herflokk etter herflokk. Då dei skulde taka ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'sagde Moses til Hobab, son åt Re’uel frå Midjan, verfar hans Moses: «No tek me på vegen til det landet som Herren hev sagt han vil gjeva oss. Kom og ver med oss, so skal me gjera vel mot deg; for Herren hev lova Israel mykje godt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, '«Nei,» svara Hobab, «eg vil fara heim til mitt eige land og folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, '«Kjære væne, gakk ikkje frå oss!» sagde Moses. «Du veit best kvar me kann setja læger i øydemarki; du lyt vera auga vårt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Gjeng du med oss, so skal me gjeva deg mykje godt, når me fær alt det gode som Herren vil gjeva oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'So for dei då frå Gudsfjellet tri dagsleider fram, og Herrens sambandskista for fyre deim alle tri dagarne, og leita etter ein kvilestad for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Herrens sky stod yver deim um dagen, når dei for ifrå lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Og kvar gong kista tok i veg, kvad Moses: «Reis deg, Herre, so fienden ryk og uvenern’ dine rømer for deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Og når ho let seg ned, kvad han: «Herre, kom atter til alle dei tusund Israels-ætter!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Det var ein gong folket klaga seg for Herren, liksom dei leid vondt. Då Herren høyrde det, vart han harm, og elden hans slo ned millom deim, og herja i den eine enden av lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Då ropa folket på Moses, og Moses bad til Herren for deim; so slokna elden av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Sidan kalla dei den staden Tabera, av di Herrens eld slo ned millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Men herkemugen, som var med deim, fyste etter annan kost; då for Israels-folket og til å jamra seg att, og sagde: «Gud gjev me hadde kjøt å eta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Me saknar fisken som me fekk kostelaust i Egyptarland, og agurkarne og melonorne og purren og kvitlauken og skarlauken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'her turkar me reint upp; me ser ikkje anna for augo enn manna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Manna var likt korianderfrø og på lit som bedolahkvåda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Folket for utyver og sanka det, og mol det på handkvern eller støytte det sund i mortlar. Sidan saud dei det i gryta, og laga kakor av det; då smaka det som sukkerbrød med olje i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Når dalskoddi seig ned yver lægri um natti, fylgde det manna med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Då Moses høyrde gråt frå kvart einaste hus, og såg at Herren var fælande harm, tykte han det var ilt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'og sagde til Herren: «Kvi hev du fare so hardt med tenaren din? Kvi hev du so lite godhug for meg at du vil leggja på meg slik ei byrd som å syta for heile dette folket?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Hev då eg gjeve deim livet eller sett deim inn i verdi, sidan du segjer med meg at eg skal halda deim på armen, som barnfostren held eit sugebarn, og bera deim fram til det landet du hev lova federne deira?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Kvar skal eg taka kjøt frå til heile dette folket? For dei heng yver meg med gråt, og segjer: «Gjev oss kjøt, so me fær eta!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ikkje kann eg åleine syta for heile dette folket; det er meir enn eg orkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Vil du fara so med meg, so drep meg heller med ein gong, so sant du vil meg vel, og lat meg ikkje sjå mi eigi ulukka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Då sagde Herren til Moses: «Kalla meg i hop sytti av dei gildaste menner i Israel, deim som du veit er dei gjævaste millom folket og formenner for deim! Tak deim so med deg til møtetjeldet og lat deim standa der hjå deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'so vil eg koma ned og tala med deg der, og eg vil lata deim og få av den åndi som er yver deg, so dei kann hjelpa deg og bera all den tyngsla du hev av folket, og du ikkje tarv bera henne åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Og til folket skal du segja: «Helga dykk til i morgon, so skal de få kjøt å eta, etter di de jamra dykk for Herren og sagde: «Gud gjeve me hadde kjøt! Å kor godt me livde i Egyptarland!» No vil Herren gjeva dykk kjøt, som de skal eta av,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'og det ikkje ein dag, eller tvo eller fem eller ti eller tjuge dagar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'men ein heil månad, til de byd dykk imot, so det lyt gjeva det upp att, for di de mismætte Herren som er midt imillom dykk, og jamra dykk for honom, og sagde: «Kvi for me då frå Egyptarland?»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, '«Seks hundrad tusund gangføre menner er det folket som eg fylgjest med,» svara Moses, «og du segjer at du vil gjeva deim kjøt so dei hev mat for ein heil månad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Skal me slagta so mange sauer og naut at det rekk til for deim, eller skal all fisken i havet sankast i hop so dei fær nok?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Då sagde Herren til Moses: «Rekk ikkje Herrens arm so langt som han vil? No skal du få sjå um det ikkje gjeng som eg hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'So gjekk Moses ut, og kunngjorde Herrens ord for folket, og han kalla saman sytti av dei gjævaste mennerne i lyden, og bad deim standa rundt ikring møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Og Herren for ned i skyi, og tala til Moses, og let dei sytti gjæve mennerne få av den åndi som var yver honom. Då hende det at med same åndi let seg ned yver deim, tala dei profetord, men sidan gjorde dei det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Det var tvo menner som hadde vorte att i lægret; den eine heitte Eldad og den andre Medad. På deim let åndi seg og ned; for dei høyrde til deim som var uppskrivne, men dei hadde ikkje gjenge ut til møtetjeldet, og no tala dei profetord i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Og ein svein kom springande med bod til Moses og sagde: «Eldad og Medad talar profetord i lægret.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Då tok Josva frami, han som hadde vore fylgjesveinen åt Moses alt ifrå ungdomen, og sagde: «Herre Moses, forbyd deim dette!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, '«Er du åbru for mi skuld?» svara Moses. «Eg vilde at heile Herrens folk kunde tala profetord, og at Herren sende sin Ande yver deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Då Moses vel var komen attende til lægret saman med Israels hovdingar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'so sende Herren ein vind som førde enghønor inn ifrå havet, og støytte deim ned yver lægret og markerne rundt ikring, so vidt som ei dagsleid i firkant. Dei flaug so lågt at dei ikkje var meir enn eit par alner frå marki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'og folket var ute heile den dagen og heile natti og heile den andre dagen og samla deim inn; ingen sanka mindre enn eit tjug tunnor, og dei breidde deim utyver rundt ikring lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Medan dei endå åt av kjøtet - det var ikkje ende - loga Herrens vreide upp att, og han sende ein øgjeleg manndaude yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Difor kallar dei den staden Kibrot-Hatta’ava; for der vart dei jorda dei som hadde vore so fysne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Frå Kibrot-Hatta’ava for folket til Haserot, og der vart dei verande ei tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Mirjam, og Aron med, tala ille um Moses for den ætiopkvinna skuld, som han hadde teke til kona - for han hadde gift seg med ei ætiopisk kvinna -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'og dei sagde: «Er det då berre Moses Herren hev tala med? Hev han ikkje tala med oss og?» Og Herren høyrde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'No var Moses ein mild og tolug mann, mildare enn alle menneskje på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Men Herren sagde brått til Moses og til Aron og til Mirjam: «Gakk ut til møtetjeldet alle tri!» So gjekk dei dit alle tri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Og Herren for ned i ein skystopul, og stod i tjelddøri og ropa: «Aron og Mirjam!» Då gjekk dei ut båe tvo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Og han sagde: «Lyd no etter ordi mine: Er det ein profet millom dykk, so ter eg, Herren, meg for honom i syner, og talar med honom i draumar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Men so er det ikkje med Moses, tenaren min; honom lit eg so på, at eg hev sett honom yver heile mitt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Munn til munn talar eg med honom, klårt og ikkje i gåtor, og han fær sjå Herren i rette hamen hans skapnad. Korleis kunde de då våga å tala ille um Moses, min tenar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Og Herrens vreide loga upp imot dei, og han for burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Då skyi hadde kvorve burt frå tjeldet, då var Mirjam spillsjuk, og kvit som snø; med same Aron snudde seg mot henne, såg han at ho var spillsjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Då sagde han til Moses: «Gode herre bror! Lat oss ikkje lida for mykje for syndi og dårskapen vår!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Lat henne ikkje verta som eit daudt foster, som er halvrote når det kjem ut or morslivet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Då ropa Moses til Herren og sagde: «Å kjære, kjære Gud, gjer henne god att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Og Herren sagde til Moses: «Hadde far hennar sputta henne i andlitet, laut ho då ikkje sitja med skam i sju dagar? No skal dei stengja henne ute frå lægret i sju dagar, so kann dei taka henne inn att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'So stengde dei Mirjam ute frå lægret i sju dagar, og folket tok ikkje av stad, fyrr dei hadde teke henne inn att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Sidan tok folket ut frå Haserot, og slo læger i Paranheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '«Send ut folk til å forfara Kana’ans-landet, som eg vil gjeva Israels-borni! Ein mann for kvar ætt skal de senda, og alle skal vera av dei fremste mennerne deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'So sende Moses folk ut frå Paranheidi, som Herren hadde sagt, og dei han sende var alle av dei gjævaste mennerne i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Dei heitte: Sammua, son åt Sakkur, av Rubens-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Safat, son åt Hori, av Simeons-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Kaleb, son åt Jefunne, av Juda-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Jigeal, son åt Josef, av Issakars-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Hosea, son åt Nun, av Efraims-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Palti, son åt Rafu, av Benjamins-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Gaddiel, son åt Sodi, av Sebulons-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Gaddi, son åt Susi, av Josefs-ætti, av Manasse-greini;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Ammiel, son åt Gemalli, av Dans-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Setur, son åt Mikael, av Assers-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Nahbi, son åt Vofsi, av Naftali-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Ge’uel, son åt Maki, av Gads-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Det var dei mennerne som Moses sende ut til å rundfara landet; men Hosea, son åt Nun, kalla han Josva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Han sende dei på njosningsferd til Kana’ans-landet, og sagde til deim: «Far upp her, til Sudlandet, og tak upp i fjellet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'og sjå korleis landet er laga, og um folket som bur der er sterkt eller veikt, um dei er få eller mange,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'og um landet deira er godt eller låkt, og kva slag byar dei bur i, um der er læger eller borger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'og um jordi er feit eller skrinn, og um der er tre eller ikkje. Ver trøystuge, og tak med dykk noko av frukti i landet!» Det var då i det bilet druvorne for til å mogna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'So tok dei av stad, og endefor landet, alt ifrå Sinheidi til Rehob, som ligg innmed vegen til Hamat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Dei for upp til Sudlandet og kom til Hebron. Der budde Ahiman og Sesai og Talmai, Anaks-sønerne - Hebron var bygt sju år fyre Soan i Egyptarland. -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'So kom dei til Eskoldalen. Der skar dei ei vintregrein med ein druvekrans, som tvo mann laut bera millom seg på ei stong, og so nokre granateple og fikor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Den staden vart sidan heitande Eskoldalen, etter den druvekransen som Israels-sønerne skar av der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Då det leid av fyrti dagar, kom dei att, og hadde endefare landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Dei fann Moses og Aron og heile Israels-lyden i Paranheidi, i Kades, og gav fråsegn um det dei hadde set, og synte deim frukterne frå Kana’ans-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, '«Me kom til det landet du sende oss til,» sagde dei til Moses, «og det er visst at det landet fløymer med mjølk og honning, og her ser de frukterne som veks der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Men folket som bur der, er sterkt, og byarne store, med svære murar ikring. Anaks-sønerne såg me der og,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'og i Sudlandet bur Amalek-folket, og i fjellbygderne hetitarne og jebusitarne og amoritarne, og utmed havet og langsmed Jordan bur Kananitarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Då tok folket til å murra mot Moses, men Kaleb stagga på deim, og sagde: «Jau, me vil fara dit, og leggja landet under oss; me kann godt taka det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Men dei mennerne som hadde vore med honom, sagde: «Me torer ikkje ganga imot dette folket; dei er oss for sterke.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Og dei lasta burt landet for Israels-folket, og sagde: «Det landet me for igjenom og skoda, er eit land til å øyda ut folk; og alle me såg der, var kjempekarar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'der såg me risarne, Anaks-sønerne, som er av riseætt, og mot deim tyktest me å vera berre som engsprettor, og so tykte dei og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Då skreik alt folket yver seg, og dei gret heile natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Og alle Israels-borni, heile lyden, mukka mot Moses og Aron, og sagde: «Gud gjeve me hadde døytt i Egyptarlandet eller her i øydemarki - å Gud gjeve me hadde døytt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Kvi vil Herren føra oss til dette landet, so me vert nedhogne, og konorne og borni våre vert fangar? Er det ikkje betre for oss å fara attende til Egyptarland?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Og dei sagde seg imillom: «Me vil taka oss ein hovding, og fara attende til Egyptarland!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Då kasta Moses og Aron seg ned på jordi for augo åt heile Israels-lyden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'og Josva, son åt Nun, og Kaleb, son åt Jefunne, som hadde vore med og forfare Kana’ans-landet, reiv sund klædi sine');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'og tala til heile Israels-lyden, og sagde: «Det landet som me hev fare igjenom og skoda, er eit ovgodt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Er Gud oss god, so fører han oss fram til landet, og gjev oss det; det er eit land som fløymer med mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Set dykk berre ikkje upp mot Gud, og ver ikkje rædde folket som bur der i landet! Dei er ikkje annleis enn som eit matmål for oss. Hjelpi deira hev kvorve burt, og Herren er med oss. Ver ikkje rædde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Då vilde heile lyden steina deim; men Herrens herlegdom synte seg i møtetjeldet for heile Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Og Herren sagde til Moses: «Kor lenge vil dette folket hæda og vanvyrda meg? Kor lenge vil dei mistru meg, endå so mange teikn som eg hev gjort millom deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Men no vil eg søkja deim med sott, og rydja deim ut, og so vil eg gjera di ætt til eit større og sterkare folk enn dei er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Då sagde Moses til Herren: «Skal då egyptarane få spyrja slikt? dei som du førde dette folket burt i frå i ditt velde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Skal dei få det å tala um med folk her i landet, som hev høyrt at du, Herre, er midt imillom dette folket, og syner deg for deim, andlit til andlit, du, Herre, og at skyi di held seg yver deim, og at du gjeng fyre deim i ein skystopul um dagen og i ein eldstopul um natti?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Slær du no dette folket i hel, som det var ein mann, so kjem dei folki som hev høyrt ordet um deg til å segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '«Herren magta ikkje å føra dette folket fram til det landet han hadde lova deim, og so drap han deim ned i øydemarki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Men syn deg no i ditt velde, Herre, som du lova då du sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '«Herren er tolug og rik på nåde. Han tilgjev brot og misgjerningar; men han vil ikkje at den skuldige skal vera strafflaus: han hemner broti åt federne på borni og på barnebarns-borni og borni etter deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Tilgjev då av di store nåde broti åt dette folket, liksom du hev havt tolmod med deim heile vegen, frå Egyptarland og hit!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Då sagde Herren: «Eg skal gjeva deim til, som du bed um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Men so vist som eg liver og Herrens herlegdom fyller heile jordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'ingen av deim som hev set herlegdomen min og dei teikni eg gjorde i Egyptarland og i øydemarki, og som like vel hev freista meg gong på gong, og aldri vilde lyda på ordi mine -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'ingen av deim skal sjå det landet eg hev lova federne deira; ingen av deim som hev hædt og vanvyrdt meg, skal få sjå det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Men Kaleb, tenaren min, vil eg fylgja til det landet han hev vore i, og ætti hans skal få det til eiga; for honom er det ein annan hug i, og han hev halde seg trutt etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Amalekitarne og kananitarne bur her i dalen; difor lyt de i morgon venda um, og taka ut i øydemarki, den vegen som ber til Raudehavet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Og Herren tala meir til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '«Kor lenge skal denne vonde lyden halda på å mukka mot meg? Eg hev nok høyrt korleis Israels-sønerne murrar og mukkar imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Seg til deim: «So vist som eg liver,» segjer Herren: «det som eg høyrde de ynskte dykk, det skal de få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Her i øydemarki skal beini dykkar liggja, alle de som vart mynstra, heile flokken, so mange som er yver tjuge år gamle og hev sett seg upp imot meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'ingen av dykk skal koma inn i det landet som eg rette handi i veret på at eg vilde gjeva dykk til bustad - ingen utan Kaleb, son åt Jefunne, og Josva, son åt Nun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Småborni dykkar, som de spådde skulde falla i fiendehand, deim vil eg fylgja dit, og dei skal verta heime i det landet som de hev vanda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Men dykkar bein skal liggja her i øydemarki;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'og sønerne dykkar skal gjæta i heiderne i fyrti år, og lida for utruskapen dykkar, til beini dykkar hev morkna i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Likso mange dagar som de for yver Kana’ans-landet, likso mange år skal de lida for broti dykkar, fyrti år, eit år for kvar dag, og de skal få kjenna korleis det er når eg vender meg frå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Det segjer eg, Herren: So vil eg gjera med heile denne vonde lyden, som hev slege seg i hop mot meg; i denne øydemarki skal dei enda sine dagar, her skal dei døy.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Dei mennerne som Moses hadde sendt ut til å forfara Kana’ans-landet, og som spreidde låke tiender um det då dei kom att, og fekk heile lyden til å setja seg upp imot Moses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'desse mennerne, som hadde lasta burt landet, dei døydde brått for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Av alle deim som hadde fare på njosningsferd til Kana’ans-landet, var det berre Josva, son åt Nun, og Kaleb, son åt Jefunne, som fekk liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Og Moses bar Herrens ord fram for Israels-folket. Då angra dei sårt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'og dagen etter, i otta, tok dei uppetter til høgfjellet, og sagde: «Sjå her er me og vil fara upp til den staden som Herren hev sagt; for me hev synda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Då sagde Moses: «Kvi vil de då gjera imot Herrens ord? Dette kjem ikkje til å lukkast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Far ikkje dit! For Herren er ikkje med dykk. De kjem berre til å rjuka for fienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'For der møter de amalekitarne og kananitarne, og då vert de nedhogne, etter di de hev vike frå Herren, og han ikkje er med dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Like vel var dei so uvyrdne at dei styrmde av stad til høgfjellet. Men Herrens sambandskista og Moses flutte seg ikkje frå lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Og amalekitarne og kananitarne, som budde på det fjellet, kom ned, og slo deim og jaga deim frå einannan, og elte deim alt til Horma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '«Tala til Israels-folket, og seg med deim: «Når de kjem til det landet de skal bu og byggja i, det som eg vil gjeva dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'og de lagar til offermat for Herren - brennoffer eller slagtoffer av storfe eller småfe, til godange for Herren - anten det er ein lovnad de vil løysa, eller ei gåva det gjev i godvilje, eller eit høgtidsoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'so skal det attåt offeret som de ber fram for Herren, koma med eit grjongåva, og det skal vera ei kanna fint mjøl, blanda med ei halvkanna olje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'og til drykkoffer skal du gjeva ei halvkanna vin attåt brenn- eller slagtofferet, dersom det er eit lamb;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'er det ein ver, so skal du til grjonoffer gjeva tvo kannor fint mjøl, blanda med tvo pottar olje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'og til drykkoffer skal du bera fram tvo pottar vin; då er det eit offer som angar godt for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Ofrar de ein ung ukse til brennoffer eller slagtoffer, anten det er ein lovnad de vil løysa, eller eit takkoffer til Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'so skal du attåt uksen bera fram tri kannor fint mjøl, blanda med ei kanna olje, til grjonoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'og til drykkoffer ei kanna vin; då er det ein offerrett som gjev god ange for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Soleis skal de gjera for kvar ukse og ver og for kvart lamb eller kid');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'de ofrar, anten offerdyri er få eller mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Alle som er fødde og borne i landet, skal gjera so som eg no hev sagt, når dei vil bera fram ein offerrett til godange for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Er det nokon framand som held til hjå dykk, eller i framtidi kjem til å bu millom dykk, og vil bera fram ein offerrett til godange for Herren, so skal han gjera like eins som de.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Det gjeld same retten for heile lyden, for dykk sjølve so vel som for dei framande som bur i landet dykkar; det er ei lov som skal gjelda for alle tider at dei framande skal vera som de sjølve for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Ei lov og ein rett skal vera for dykk og for dei framande som bur hjå dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '«Tala til Israels-sønerne, og seg til deim: «Når de kjem til det landet som eg vil føra dykk til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'og et av den maten de avlar der, so skal de koma med ei reida til Herren:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Av det fyrste gropet de mel, skal de bera fram ei kaka til reida for Herren, liksom de ber fram reida frå treskjarstanden -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'av det fyrste malingi skal de all tid gjeva Herren ei reida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Fer de i mist, og gløymer noko av dei bodi som Herren hev gjeve Moses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'og som Moses hev kunngjort for dykk, anten no, med same Herren hev gjeve bodet, eller seinare frametter tidi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'og det er uviljande gjort, og lyden uvitande, so skal heile lyden bera fram ein ung ukse til brennoffer og godange for Herren, med grjonoffer og drykkoffer som til høyrer, soleis som det er fyresagt, og ein geitebukk til syndoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'og presten skal gjera soning for heile Israels-lyden; då skal dei få tilgjeving etter di det var uviljande gjort, og dei hev kome til Herren med offergåva si og bore fram syndofferet sitt til bot for si misferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Både heile Israels-lyden og dei framande som bur millom deim, skal få tilgjeving. For heile folket var saka i misferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Er det ein einskildmann som uviljande hev synda, so skal han bera fram ei årsgamall geit til syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Og presten skal beda til Herren for den som uviljande hev misfare seg og synda, og gjera soning for honom, so skal han få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Dette gjeld både for den som er fødd og boren millom Israels-folket og for den framande som bur millom deim. Det gjeld same retten for dykk alle, når de uviljande gjer noko gale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Men den som med vilje gjer noko vondt, anten det er eit heimemenneskje eller ein framand, han hæder Gud og skal rydjast ut or folket sitt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'for han hev vanvyrdt Herrens ord og brote bodet hans: den mannen skal rydjast ut; han skal lida for brotet sitt.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Då Israels-folket var i øydemarki, råka dei ein gong ein mann som sanka ved ein helgedag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Dei som kom yver honom medan han sanka veden, førde honom fram for Moses og Aron og heile lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Og dei sette honom fast; for det var ikkje gjeve noko serskilt bod um kva som skulde gjerast med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Då sagde Herren til Moses: «Mannen skal lata livet: Heile lyden skal steina honom utanfor lægret.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'So førde heile lyden honom ut til ein stad utanfor lægret, og steina honom i hel, soleis som Herren hadde sagt til Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Og Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '«Tala til Israels-sønerne, og seg til deim, at dei skal gjera seg duskar og hava i snipparne på klædi sine, både dei og etterkomarane deira, og i kvar dusk skal dei setja ei purpursnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Dei duskarne skal de hava til prydnad, og når de ser på deim, skal de minnast alle Herrens bod og halda dykk etter deim, so de ikkje fer hit og dit etter som hjarta og augo segjer dykk til; for dei lokkar dykk jamleg til utruskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Det er so de skal koma i hug å halda alle bodi mine og vera heilage for dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Eg er Herren, dykkar Gud, som førde dykk ut or Egyptarlandet, og vil vera dykkar Gud. Eg, Herren, er dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Korah, son åt Jishar Kahatsson av Levi-ætti, og Datan og Abiram, sønerne hans Eliab, og On Peletsson av Rubens-ætti tok til å yppa seg mot Moses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'og saman med dei tvo hundrad og femti av dei øvste i Israels-lyden, som var kåra til tingmenner, og hadde eit godt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Dei slo seg i hop mot Moses og Aron, og sagde til deim: «No lyt det vera nok! Heile lyden er heilag, alle saman, og Herren er midt imillom deim; kvi vil då de all tid halda dykk gildare enn Herrens lyd?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Då Moses høyrde det, kasta han seg ned på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Og han tala til Korah og heile flokken hans, og sagde: «I morgon vil Herren syna kven som er hans folk, og kven som er heilag og kann koma inn til honom, og dei som han då vel, skal få koma inn til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Gjer no so, du Korah og heile flokken din: Tak i morgon med dykk glodfat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'og hav eld i deim, og legg røykjelse på elden for Herrens åsyn, og den som Herren vel, han skal vera heilag. Lat so det vera nok, de Levi-søner!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Og endå sagde Moses til Korah: «Høyr no, de Levi-søner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Er de ikkje nøgde med at Israels Gud hev skilt dykk ut frå Israels-lyden, so de skulde vera næmare honom og greida arbeidet i Herrens hus, og ganga lyden til handa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Han hev teke deg og alle brørne dine, Levi-sønerne, innåt seg, og no trår de etter preste-embættet og?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Det er mot Herren de hev slege dykk i hop, du og heile flokken din; for kva er Aron? Kann det vera verdt å setja seg upp i mot honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'So sende Moses bod etter Datan og Abiram, sønerne hans Eliab; men dei svara: «Me kjem ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Er det ikkje nok at du lokka oss burt frå eit land som fløymer med mjølk og honning, so me skulde døy i øydemarki? Vil du no attpå råda og rikja yver oss?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Ikkje heller hev du ført oss til eit land som fløymer med mjølk og honning, og gjeve oss åkrar og aldehagar til eiga! Trur du då du kann synkverva desse mennerne? Me kjem ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Då vart Moses brennande harm, og han sagde til Herren: «Ansa ikkje offeret deira! Ikkje so mykje som eit asen hev eg teke frå deim, og ingen av deim hev eg gjort noko til meins.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'So sagde han til Korah: «Møt no fram for Herrens åsyn i morgon, du og heile flokken din! Aron skal og møta fram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'og de skal taka kvar sitt glodfat og leggja røykjelse på deim, og bera deim fram for Herrens åsyn, tvo hundrad og femti glodfat, og du og Aron skal og taka kvar sitt glodfat.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'So tok dei kvar sitt glodfat, og hadde eld i deim, og lagde røykjelse på og stod i møtetjelddøri, og det same gjorde Moses og Aron;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'og Korah samla heile lyden imot dei framanfor møtetjelddøri. Då synte Herrens herlegdom seg for heile lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Og Herren tala til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '«Skil dykk frå denne lyden, so skal eg gjera ende på deim, so fort som ein blunkar med auga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Men dei kasta seg på kne, og sagde: «Allvelduge Gud, du som råder yver alle manneliv, vert du vill på heile lyden, for di ein mann syndar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Og Herren svara Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '«Seg til folket at dei skal hava seg burt frå bustaden åt Korah og Datan og Abiram og frå alt som derikring er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'So reiste Moses seg upp og gjekk burt til Datan og Abiram, og Israels hovdingar fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Og han tala til folket, og sagde: «Gakk burt frå husi åt desse gudlause mennerne, og kom ikkje innåt noko som høyrer deim til; elles kjem de og til å lida for alle synderne deira!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Då flutte dei seg burt frå buderne åt Korah og Datan og Abiram og alt som var ikring um. Men Datan og Abiram kom ut og stod i buddøri med konorne sine og borni, både store og små.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Og Moses sagde: «Dette skal de hava til merke på at Herren hev sendt meg til å gjera alle desse verki, og at det ikkje er av meg sjølv eg gjer det:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'dersom desse døyr på same vis som anna folk, og møter lagnaden som alle andre menneskje, so hev Herren ikkje sendt meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'men dersom Herren let henda noko som aldri fyrr hev hendt, dersom jordi let upp gapet sitt, og gløyper deim og alt som deira er, so dei fer livande ned i helheimen, so veit de at desse mennerne hev spotta Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Ikkje fyrr hadde han sagt dei ordi, so rivna grunnen under føterne deira;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'jordi let upp gapet sitt, og gløypte deim og husi deira og alt folket hans Korah og alt det dei åtte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Dei for livande ned i helheimen med alt som deira var, jordi gøymde deim, og dei kvarv burt or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Og heile Israel, som stod rundt ikring, rømde då dei høyrde skriket deira; dei var rædde jordi skulde gløypa deim med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'So for det eld ut frå Herren, og brende upp dei tvo hundrad og femti mennerne som hadde bore fram røykjelse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Då tala Herren til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '«Seg til Eleazar, son åt Aron, øvstepresten, at han skal taka upp glodfati som ligg att der elden hev fare, og strå glørne vidt utyver! For heilage er dei,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'glodfati åt desse mennerne som laut lata livet for syndi si; de skal hamra dei ut til plator, og klæda altaret med deim. Dei hev vorte framborne for Herrens åsyn; difor er dei heilage, og skal vera eit varsl for Israels-borni.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Og Eleazar, presten, gjorde som Moses hadde sagt honom frå Herren: han tok koparfati som dei hadde bore fram dei mennerne som brann upp, og smedarne hamra plator av deim til å klæda altaret med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'so Israels-borni skulde koma i hug at ingen framand, ingen som ikkje er av Arons ætt, må ganga fram og brenna røykjelse for Herrens åsyn; elles kjem han til å fara same ferdi som Korah og hans flokk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Dagen etter mukka heile Israels-lyden mot Moses og Aron, og sagde: «Det er de som hev drepe Herrens folk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'og ålmugen tok til å samla seg mot deim. Moses og Aron vende seg mot møtetjeldet; då såg dei at skyi låg yver tjeldet, og herlegdomen åt Herren skein fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'So gjekk dei fram for møtetjeldet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '«Sjå til å koma dykk burt frå denne hopen, so skal eg tyna dei i ein augneblink!» Då kasta dei seg på kne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'og Moses sagde til Aron: «Tak glodfatet; legg i gløder frå altaret, og hav røykjelse uppå, og skunda deg so burt til lyden med det, og gjer soning for deim! For Herren hev slept harmen sin laus - sotti er komi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Aron gjorde som Moses sagde, og tok glodfatet og sprang midt inn i flokken; sotti hadde då alt teke til å herja millom folket. So lagde han røykjelsen på gløderne, og bad ei soningsbøn for folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'med han stod der millom daude og livande. Då stana sotti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'men det var fjortan tusund og sju hundrad som døydde i den sotti, umfram deim som miste livet for Korahs skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Då sotti hadde gjeve seg, gjekk Aron attende til Moses, til møtetjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Då tala Herren til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '«Tala til Israels-sønerne, og få tolv stavar av deim, ein for kvar ætt; av kvar ættarhovding skal du få ein stav, og på den skal du rita namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Og Arons namn skal du setja på staven åt Levi-sønerne; for ein av stavarne skal deira ættarhovding hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'So skal du leggja stavarne i møtetjeldet, framfyre kunngjeringskista, der som eg er van å møtast med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Då skal han bløma, staven åt den eg vel ut - so fær eg vel fred for den mukkingi som Israels-borni jamleg plågar dykk med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'So tala Moses til Israels-borni, og hovdingarne gav honom kvar sin stav, ein stav for kvar ætt; det var tolv stavar i alt, og millom deim var staven hans Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Og Moses lagde stavarne ned framfor Herrens åsyn i kunngjeringstjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Då han so andre dagen kom inn i kunngjeringstjeldet, såg han at Arons stav, den som høyrde til Levi-ætti, hadde grønkast, og skote knuppar, og sett blom, og fenge mogne mandlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Då tok han alle stavarne, og bar deim ut or heilagdomen, og synte deim åt alle Israels-borni, og då dei hadde set deim, tok kvar sin stav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Og Herren sagde til Moses: «Ber Arons stav inn att, og legg honom frammed kunngjeringskista! Der skal han gøymast til ei åtvaring for dei ulyduge; for held dei ikkje upp med å mukka imot meg, so skal dei døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Og Moses gjorde so; som Herren hadde sagt med honom, so gjorde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Men Israels-borni sagde til Moses: «Sjå no er det ute med oss; me døyr, me døyr alle saman!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Kjem nokon innåt - innåt Herrens hus - so misser han livet. Er det ikkje då ute med oss alle?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'So sagde Herren til Aron: «Du og sønerne dine og heile farsætti di skal hava ansvaret for heilagdomen. Du og sønerne dine skal svara for preste-embættet dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Og frendarne dine, Levi-sønerne, farsætti di, skal du hava med deg. Dei skal halda seg attmed deg, og ganga deg til handa når du og sønerne dine stend framfyre kunngjeringstjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Og dei skal gjera det som du set deim til å gjera, alt det som skal gjerast i heile tjeldet; berre dei heilage tingi og altaret må dei ikkje koma innåt; for gjer dei det lyt dei døy, både dei og de.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Dei skal halda seg attmed deg, og gjera alt det arbeidet som trengst i møtetjeldet; for ingen framand må koma innåt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Men de lyt gjera alt som skal gjerast i sjølve heilagdomen og innmed altaret, so det ikkje tidare skal koma vreide yver Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'For det er eg som hev kåra ut levitarne, brørne dykkar, av Israels-folket; dei er ei gåva til dykk, og de skal gjeva deim åt Herren, so dei gjer det arbeidet som trengst i møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Men du og sønerne dine skal styra preste-embættet og hava umsut for alt som høyrer til altaret og for det som er innanfor forhenget, og halda gudstenesta. Dykk gjev eg prestedømet i gåva; men kjem ein framand innåt, skal han lata livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Og Herren sagde til Aron: «Sjå, eg gjev deg det som skal gøymast av reidorne mine; alle dei heilage gåvorne frå Israels-folket, deim gjev eg deg og sønerne dine; det skal vera dykkar lut og rett i all framtid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Høyr no kva det er du skal hava av dei høgheilage gåvorne, når det som skal brennast, er teke undan: Alt det dei ber fram av grjonoffer og syndoffer og skuldoffer som dei gjev meg i bot, det er høgheilagt, og skal høyra deg og sønerne dine til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'På den høgheilage staden skal du eta det; alle karar kann eta av det; heilagt skal det vera for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Like eins skal du hava dei gåvorne som dei gjev i reidor; alt det Israels-borni svingar for Herrens åsyn, gjev eg deg og sønerne og døtterne dine; det skal de hava retten til i all framtid; alle i ætti di som er reine, kann eta av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alt det beste av oljen og av druvesafti og kornet, det fyrste dei avlar av det, og gjev Herren, det gjev eg deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Dei fyrste mogna frukterne av alt som veks i landet deira, og som dei kjem til Herren med, skal vera dine; alle i ætti di som er reine, kann eta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Alt som er vigsla i Israel, skal høyra deg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Alt som kjem fyrst frå morsliv, alt livande som dei ber fram for Herren, anten det er folk eller fe, skal vera ditt; men det som er frumbore av folk, skal du lata deim løysa, og det som er frumbore av ureine dyr, kann og løysast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Løysepengarne for borni skal leggjast etter dei hev fyllt ein månad, og svara til det verdet som sett er: fem sylvdalar i heilag mynt, etter tjuge gera i dalaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Frumsungar av kyr eller sauer eller geiter må ikkje løysast; dei er heilage. Blodet deira skal du skvetta på altaret, og feittet skal du brenna; so røyken stig upp mot himmelen; det er ein angande rett for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Kjøtet skal du hava; liksom svingebringa og det høgre låret skal det høyra deg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Alle heilage reidor som Israels-borni kjem til Herren med, gjev eg deg og sønerne og døtterne dine; det skal de hava retten til for alle tider. Dette er ei æveleg og ubrjotande semja med deg og etterkomarane dine for Herrens åsyn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Og Herren sagde til Aron: «Du fær ingen lut i landet deira og ingi jordeign millom deim; eg skal vera din lut og di eiga millom Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Men all tiend i Israel gjev eg Levi-sønerne til eigedom for arbeidet deira, det arbeidet dei gjer i møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Og dei hine Israels-borni skal ikkje meir koma innåt møtetjeldet; for då fører dei synd yver seg, og lyt døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Levi-sønerne åleine skal greida tenesta i møtetjeldet, og hava alt ansvaret; det skal vera ei æveleg lov for dykk og etterkomarane dykkar. Dei skal ingi jordeign hava millom Israels-folket;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'men tiendi som Israels-borni kjem til Herren med, gjev eg levitarne; den skal vera deira eigedom; difor er det eg hev sagt at dei ingi jordeign skal hava millom Israels-folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '«Du skal tala til levitarne, og segja til deim: «Når de tek imot tiendi som eg hev sagt de skal få til eigedom av Israels-folket, so skal de gjeva Herren ei reida av det - tiend av tiendi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Og reida dykkar skal reknast for jamgod med det kornet dei andre ber fram frå låven og den vinen dei kjem med frå persa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'På den måten gjev de og Herren reida av all tiendi de fær hjå Israels-borni, og den reida de hev etla åt Herren, skal de gjeva Aron, øvstepresten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Av alle gåvor de fær, skal de fyrst taka ut alt det de vil gjeva Herren, og det de vigjer honom, lyt all tid vera av det beste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Og du skal segja til deim: «Når de ofrar det beste av det, so skal det reknast likt med det som kjem inn ifrå låven og ifrå vinpersa;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'de kann eta det kvar de vil, både de og folket dykkar; for det er løni de skal hava for arbeidet i møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'De ber ingi synd for det, når det berre gjev frå dykk det beste, og de vanhelgar ikkje dei heilage gåvorne frå Israels-folket, og skal ikkje lata livet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Og Herren tala atter til Moses og Aron, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '«Høyr no eit lovbod som Herren hev gjeve! Han sagde: «Seg til Israels-sønerne at dei skal koma til deg med ei raud kviga, som ikkje hev vank eller veila, og aldri hev vore under åket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Den skal de gjeva til Eleazar, presten, og dei skal leida henne utanfor lægret og slagta henne for augo hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Og han - Eleazar, presten - skal taka noko av blodet hennar på fingeren og skvetta sju gonger burt imot framsida av møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'So skal dei brenna kviga for augo hans; både hudi og kjøtet og blodet, og møki med, skal dei brenna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Og presten skal taka cedertre og bergmynta og karmesin og kasta på elden som kviga brenn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Sidan skal han två klædi sine, og lauga likamen sin i vatn, so kann han koma inn i lægret; men han skal vera urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Den som brende kviga, skal og två klædi sine og lauga likamen sin i vatn, og er urein til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Og ein som er rein, skal samla i hop oska av kviga, og leggja henne på ein rein stad utanfor lægret, so ho kann gøymast åt Israels-lyden til skiringsvatn; ho hev soningskraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Men den som samla oska av kviga, lyt två klædi sine, og er urein til kvelds. Og dette skal vera ei æveleg lov både for Israels-folket og dei framande som bur millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Den som kjem nær ein avliden, kven det so er, er urein sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Den tridje og den sjuande dagen skal han reinsa seg for synd med skiringsvatnet; so vert han rein att; men reinsar han seg ikkje den tridje og den sjuande dagen, so vert han ikkje rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kven som kjem nær ein avliden, eit mannelik, og ikkje reinsar seg, han sulkar Herrens hus, og skal rydjast ut or Israel; han er urein; so lenge det ikkje er skvett skiringsvatn på honom, fylgjer det ureinska med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'So lyder lovi: Når ein døyr i eit hus, so skal alle som er i huset, og alle som kjem inn, vera ureine sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Og alle opne koppar, alle som det ikkje er lok på eller bundne yver, vert ureine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Og den som ute på marki kjem nær ein som er ihelslegen, eller eit anna lik, eller mannebein, eller ei grav, er urein i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Er det ein som soleis hev vorte urein, so skal dei taka noko av oska etter det uppbrende syndofferet og ausa rennande vatn på i eit fat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Og ein som er rein, skal taka bergmynte og duppa i vatnet, og skvetta på huset og på alle dei ting og alle dei folk som er der, og på den som hev kome nær mannebein eller ein mann som er ihelslegen eller eit anna lik eller ei grav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Den tridje og den sjuande dagen skal dei reine skvetta på den som hev vorte urein; og den sjuande dagen skal han segja honom fri for synd; so skal han två klædi sine og lauga seg i vatn, og vert då rein att same kvelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Men den som vert urein, og ikkje reinsar seg for synd, han skal rydjast ut or lyden, for di han hev sulka Herrens heilagdom - det hev ikkje kome skiringsvatn på honom: han er urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Dette skal vera ei æveleg lov hjå deim. Den som skvette skiringsvatnet, skal tvo klædi sine, og den som kjem nær skiringsvatnet, er urein alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Alt det den ureine kjem nær, vert ureint, og alle som kjem innåt honom, er ureine til kvelds.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'I den fyrste månaden kom Israels-sønerne, heile lyden, til Sinheidi, og dei gav seg til i Kades. Der døydde Mirjam, og der vart ho gravlagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Men der var ikkje vatn åt folket, og dei flokka seg i hop mot Moses og Aron,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'og trætta med Moses, og sagde: «Gud gjeve me og hadde roke med då brørne våre let livet for Herrens åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Kvi hev de havt Herrens folk ut i denne øydemarki, so me lyt døy her, både me og feet vårt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Kvi lokka de oss burt frå Egyptarland, og førde oss hit til denne fæle staden, der det ikkje veks anten korn eller fikor eller vintre eller aplar og ikkje finst drikkevatn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Moses og Aron hadde seg undan flokken, og gjekk fram i møtetjelddøri og kasta seg på kne. Då synte Herrens herlegdom seg for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '«Du skal taka staven, og du og Aron, bror din, skal kalla lyden i hop og tala til berget for augo deira, so skal det gjeva vatn utor seg. Lat det koma vatn utor berget for deim, og gjev deim og feet deira drikka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Moses gjorde som Herren sagde: han tok staven som låg framfor Herrens åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'og han og Aron kalla lyden i hop framfyre berget; so sagde han til deim: «Høyr no, stridnakkar! Skal me lata det koma vatn åt dykk ut or dette berget?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'So lyfte han handi, og slo på berget med staven sin tvo gonger; då strøymde det ut mykje vatn, og folket og feet deira fekk drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Men Herren sagde til Moses og Aron: «Sidan de ikkje trudde på meg, og ikkje let Israels-borni sjå mi guddomsmagt, so skal de ikkje få føra denne lyden inn i det landet eg hev gjeve deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Det var denne kjelda som vart kalla Meribavatnet; der var det Israels-sønerne tretta med Herren, og han synte deim si guddomsmagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Frå Kades sende Moses dette bodet til kongen i Edom: «So segjer Israel, bror din: «Du veit kor mykje vondt me hev lide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Federne våre for ned til Egyptarland, og der budde me mange, mange år, og egyptarane var harde med oss og federne våre;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'då ropa me til Herren, og han høyrde bønerne våre, og sende oss ein engel, som førde oss ut or Egyptarland, og sjå no er me i Kadesbygdi, innmed landskilet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Snilde deg, lat oss få fara igjenom landet ditt! Me skal ikkje ganga yver åkrarne eller vinhagarne, og ikkje taka vatn or brunnarne; me skal fara etter kongsvegen og ikkje taka av, korkje til høgre eller vinstre, fyrr me er komne igjenom landet ditt.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Men Edom svara: «Du må’kje fara fram her; gjer du det, so møter eg deg med sverd i hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, '«Eg skal fylgja storvegen,» sagde Israel, «og dersom eg drikk av vatnet ditt, eg eller buskapen min, so skal eg gjeva deg like for det. Det kann då’kje gjera noko um eg gjeng etter vegen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, '«Nei, du slepp ikkje fram her,» svara Edom, og gjekk imot deim med mykje folk og våpn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Edom vilde ikkje gjeva Israel lov til å fara igjenom landet sitt, og Israel laut taka ei onnor leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'So tok dei ut ifrå Kades, heile Israels-lyden, og kom til Horfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Og der, ved Horfjellet, i landskilet åt Edom, sagde Herren til Moses og Aron:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '«No skal Aron fara til federne sine. De var ulyduge mot meg ved Meribabrunnen; difor skal han ikkje koma inn i det landet eg hev gjeve Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Hav Aron og Eleazar, son hans, med deg upp på Horfjellet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'og tak av Aron presteklædi, og hav deim på Eleazar, son hans! So skal Aron døy der, og fara til federne sine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Moses gjorde som Herren sagde, og dei steig upp på Horfjellet for augo åt alt folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'og Moses tok av Aron presteklædi, og hadde deim på Eleazar, son hans. So døydde Aron der uppå fjellet, og då Moses og Eleazar kom ned av fjellet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'og folket såg at Aron var burte, då syrgde alle Israels-ætterne yver honom i tretti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Då den kananitiske kongen som budde i Arad i Sudlandet, høyrde at Israel kom farande etter ålmannvegen, tok han på deim, og fanga nokre av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Då gjorde Israel ein lovnad til Herren, og sagde: «Gjev du dette folket i våre hender, so skal me bannstøyta byarne deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Og Herren høyrde bøni, og gav kananitarne i Israels hender, og Israel bannstøytte deim og byarne deira; sidan kalla dei den staden Horma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Frå Horfjellet tok dei leidi burt imot Raudehavet, og vilde fara ikring Edomlandet. Men på vegen vart folket utoluge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'dei lasta Gud og Moses, og sagde: «Kvi hadde de oss burt frå Egyptarland? No lyt me døy her i øydemarki; for her finst det korkje brød eller vatn, og me er hjarteleide av denne veike maten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Då sende Herren eiterormar, som for inn imillom folket og hogg deim, so mange av deim døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'So kom dei til Moses, og sagde: «Me synda då me lasta Herren og deg. Bed Herren at han vil fria oss frå ormarne!» Då bad Moses for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Og Herren sagde til Moses: «Gjer deg ein eitarorm, og set honom upp på ei stong, so skal kvar ein som er ormhoggen og ser burt på honom få liva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'So gjorde Moses ein koparorm, og sette honom på ei stong, og kvar gong ormarne hadde hogge nokon og han såg burt på koparormen, fekk han liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Sidan tok Israels-sønerne i vegen att, og lægra seg i Obot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'So tok dei ut frå Obot, og lægra seg ved Ijje-ha-Abarim i øydemarki austanfor Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'So for dei derifrå, og slo læger i Zereddalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'So for dei lenger, og slo læger på hi sida av Arnonelvi, der som ho kjem utor Amoritarlandet og renn igjenom øydemarki. Arnon er landskilet åt Moab, og byte millom Moab og amoritarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'difor stend det i boki um Herrens herferder: «Vaheb vann me snøgge som vinden, åern’ alle, ja sjølve Arnon -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'elvelidi som heldt til Arheim og hallar seg uppåt Moabs-eigni.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'So for dei til Be’er. Der er den brunnen som Herren tala um då han sagde til Moses: «Kalla i hop folket, so skal eg gjeva deim vatn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Då song Israel denne songen: «Vell upp, du klåre olla! Ein song me vil deg syngja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Du brunn som jarlar bora, og hovdingarne hola med styrarstavarn’ sine - frå aude grunn ei gåva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Frå Mattana for dei so til Nahaliel, og frå Nahaliel til Bamot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'og frå Bamot til den dalen som ligg i Moabmarki, tett med toppen av Pisgafjellet, og hallar ned imot Øydemoen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Israel sende bod til Sihon, kongen yver amoritarne, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '«Lat meg få fara igjenom landet ditt! Me skal ikkje koma inn på åkrarne eller vingardarne, og ikkje drikka av brunnarne; me skal halda oss etter kongsvegen, til me er komne gjenom landet ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Men Sihon vilde ikkje gjeva Israel lov til å fara gjenom landet; han samla alt herfolket sitt, og for ut i øydemarki mot Israel. Då han kom til Jahas, møtte han deim, og rauk på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Men Israel hogg honom ned med kvasse sverd, og tok landet hans, frå Arnon til Jabbok til Ammonriket; men landskilet åt Ammons-sønerne var tettsett med borger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Og Israel lagde under seg alle byarne åt amoritarne, og vart buande der, i Hesbon og alle dei byarne som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'For Hesbon var hovudstaden åt Sihon, amoritarkongen; han hadde slegest med den fyrre kongen i Moab, og teke frå honom alt landet heilt til Arnon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Difor segjer skalden: «Kom hit, kom hit til Hesbon, bygg upp att Sihons borg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'For eld for ut frå Hesbon, frå Sihons stad ein loge, som øydde Ar i Moab og herja deim som hyste på Arnonhøgdene.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Ai ei, no er det ute med ætti åt Kamos! Han sønern’ sine sender som rømingar or riket, og sine døtter driv han til amoritardrotten Sihon i fangeferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Me skot på skot deim sende; Hesbon vart lagd i grus og heile landet herja med odd og egg, til Dibon. Me øydde alt ikring oss, og kveikte ufredselden alt burt åt Medeba.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Israels-sønerne slo seg ned i Amoritarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'og Moses sende njosnarar til Jazer; siden lagde dei under seg alle bygderne der ikring, og dreiv ut amoritarne som budde der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'So tok dei på ei onnor leid, og for uppetter til Basan; og Og, kongen i Basan, for i mot deim til Edre’i med alt herfolket sitt, og baud ufred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Men Herren sagde til Moses: «Du treng ikkje vera rædd honom! Eg gjev honom i dine hender med alt folket og landet hans, og du kann gjera med honom som du gjorde med Sihon, kongen yver amoritarne, som budde i Hesbon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'So hogg dei honom ned, både honom og sønerne og folket hans, so ingen vart att eller slapp undan, og sidan eigna dei åt seg landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'So tok Israels-sønerne ut att, og lægra seg på Moabmoarne, på hi sida av Jordanelvi der ho renn frammed Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Då Balak, son åt Sippor, fekk spurt kva Israel hadde gjort med amoritarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'då var rædsla stor i Moab. Moabitarne fælte seg for dette folket som var so mannsterkt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'og sagde til hovdingarne i Midjan: «No kjem denne store hopen til å snøyda alt ikring oss, liksom uksarne når dei gneg snaudt på bøen.» Og Balak Sipporson - han var konge i Moab den tid -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'sende menner til Bileam, son åt Beor, som åtte heime i Petor ved Storelvi; dei skulde beda honom koma, og segja honom det frå kongen: «Det hev kome eit folk frå Egyptarland; dei er so mange at dei fyller heile landet, og dei hev slege seg ned midt fyre meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Kjære deg, kom og bed ei våbøn yver det folket for meg; for dei er meg for sterke - då trur eg me skal vinna yver deim, so eg fær drive deim ut or landet; for eg veit at den du signar, er velsigna, og den du bannar, er forbanna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Sendemennerne var av det gjævaste folket i Moab og Midjan; dei hadde spåmannsløn med seg, og då dei kom til Bileam, bar dei fram bodet frå Balak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Då sagde han til deim: «Ver her i natt, so skal eg gjeva dykk svar, etter det som Herren segjer meg fyre.» So gav dei seg til hjå Bileam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Då kom Gud til Bileam, og sagde: «Kva er det for folk som er hjå deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam svara: «Balak, son åt Sippor, Moabs konge, sender bod til meg og segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '«Her hev kome eit folk frå Egyptarland, og dei er so mange at dei fyller alt landet. Kom og les ei våbøn yver deim, so trur eg visst eg skal råda med deim og jaga deim ut.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Då sagde Gud til Bileam: «Gakk ikkje med deim! Du skal ikkje banna det folket; for dei er velsigna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Um morgonen sagde Bileam til hovdingarne som Balak hadde sendt til honom: «Far heim att! Herren vil ikkje gjeva meg lov til å fylgja med dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'So tok Moabs-hovdingarne av stad, og då dei kom heim att til Balak, sagde dei: «Bileam vilde ikkje vera med oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Då sende Balak andre hovdingar, fleire og gjævare enn fyrste gongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Då dei kom til Bileam, sagde dei til honom: «Balak, son åt Sippor, helsar deg, og segjer: «Gode deg, kom! Seg ikkje nei!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Eg skal løna deg vel, og gjera alt det du segjer, berre du vil koma og banna dette folket for meg.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileam svara kongsmennerne so: «Um Balak gjev meg huset fullt med sylv og gull, so kann eg ikkje gjera Herren, min Gud, imot, korkje i smått eller stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Men ver no de og her natti yver, so fær eg høyra kva meir Herren hev å segja meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Då kom Gud um natti til Bileam, og sagde til honom: «Er desse mennerne komne her på den måten at dei vil få deg med seg, so kann du ferda deg til og fylgja deim; men gjer ikkje anna enn som eg segjer til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Um morgonen gjorde Bileam seg reidug, og sala asna si, og for so i veg saman med Moabs-hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Men Gud vart harm for di han tok ut, og Herrens engel kom imot honom, og stod på vegen som ein fiende, då han kom ridande på asna i lag med båe sveinarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Og asna såg Herrens engel, som stod på vegen med drege sverd i handi; då tok ho av vegen, og ut på marki; men Bileam slo henne, so ho skulde halda vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Sidan møtte Herrens engel i ei geil millom vinhagarne. På båe sidor var det steingard,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'og då asna såg Herrens engel, strauk ho seg innåt garden, og klemde foten åt Bileam mot steinarne. Då slo han henne att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'So gjekk Herrens engel framum endå ein gong, og stod i eit trongt klemstre; der var det ikkje råd å vika undan, korkje til høgre eller vinstre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'og med same asna fekk sjå Herrens engel, lagde ho seg ned under Bileam. Då vart han harm, og slo henne med staven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Men Herren gav asna mål, og ho sagde til Bileam: «Kva hev eg gjort deg? No er det tridje gongen du slær meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, '«Du hev havt meg til narr,» svara Bileam. «Hadde eg havt eit sverd i handi, so hadde eg slege deg i hel med det same.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Då sagde asna: «Er’kje eg asna di, som du hev ride på alt du hev vore til? Hev eg då havt for vis å fara soleis med deg?» «Nei,» sagde Bileam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'og i det same opna Herren augo hans, so han såg Herrens engel, som stod på vegen med drege sverd i handi. Då kasta han seg på kne, og bøygde hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Og Herrens engel sagde til honom: «Kvi hev du fare so, og slege asna di tri gonger? Det var eg som møtte deg som ein fiende, av di eg tykte denne ferdi var for brå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Og asna såg meg, og tok av vegen for meg alle tri gongerne. Hadde ikkje ho teke av vegen, so hadde eg no drepe deg, men asna hadde eg spart.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Då sagde Bileam til Herrens engel: «Eg hev synda; men eg visste ikkje at du stod framfyre meg på vegen; er dette deg imot, so skal eg venda heim att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, '«Nei, far no du med mennerne,» svara Herrens engel, «men seg ikkje eit ord anna enn det som eg segjer deg fyre.» So tok Bileam i vegen att med kongsmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Då Balak fekk høyra at Bileam kom, for han til møtes med honom til den byen som låg nørdst i Moabriket, ved Arnon, ytst utmed landskilet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Og han sagde til Bileam: «Sende eg ikkje einkom bod og bad deg til meg? Kvi vilde du ikkje koma? Trur du ikkje eg er god til å løna deg for umaken?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, '«No ser du eg er komen,» svara Bileam. «Men det er vandt um eg kann segja noko; berre dei ordi som Gud legg meg i munnen, kann eg tala.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'So fylgde han med Balak, og dei kom til Kirjat-Husot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Der slagta Balak storfe og småfe, og sende til Bileam og dei hovdingarne som var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Morgonen etter tok kongen Bileam med seg upp på Bamot-Ba’al; derifrå kunde han sjå enden av Israels-lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'So sagde Bileam til Balak: «Bygg sju altar for meg her, og få meg hit sju uksar og sju verar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak gjorde som Bileam sagde, og Balak og Bileam ofra ein ukse og ein ver på kvart altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'So sagde Bileam til Balak: «Statt her innmed brennofferet ditt, med eg gjeng burt eit bil; kann henda Herren kjem til møtes med meg; kva han då let meg sjå, det skal eg segja med deg.» So gjekk han burt på ei treberr høgd;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'der kom Gud til møtes med honom, og Bileam sagde til honom: «No hev eg stelt til sju altar, og ofra ein ukse og ein ver på kvart altar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Då lagde Herren eit ord i munnen på honom, og sagde: «Gakk attende til Balak, og tala so som eg no hev lært deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Då han kom attende, såg han Balak stod ved brennofferet sitt med alle Moabs hovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Då bar han fram spådomsordet sitt, og kvad: «Or Aram Balak hit meg baud, or austerfjelli Moabs drott: «Kom! Yver Jakob våbøn lys, og vreide vond yv’ Israel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Koss kann eg beda vondt yv’ den som Gud vil vel og ikkje vondt, og lysa heitan harm yv’ ein som Herren ikkje harmast på?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Frå høgste nuten ser eg han, frå haugarn’ eg augna kann: Ein lyd som liver for seg sjølv. Med heidningfolk held han’kje lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kven kann upprekna Jakobs ætt, og taka tal på Israel? Det vøre telja sand i strand og gyvet som på jordi fyk. Mått’ eg som desse gode døy, og få ei endelykt som dei!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, '«Kva er det du gjer?» ropa Balak. «Til å banna fiendarne mine fekk eg deg hit, og so velsignar du deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, '«Lyt eg ikkje halda meg etter dei ordi som Herren legg meg i munnen?» svara Bileam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Då sagde Balak: «Kjære, kom og ver med meg til ein annan stad, so du kann sjå deim betre - her ser du berre enden av lægret; heile lægret ser du ikkje - og bed so ei våbøn yver deim der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'So tok han Bileam med seg til vardehaugen på toppen av Pisga; der bygde han sju altar og ofra ein ung ukse og ein ver på kvart altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Og Bileam sagde til honom: «Statt her innmed brennofferet ditt, med eg gjeng der burt til eit møte.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'So kom Herren til møtes med Bileam, og lagde eit ord i munnen hans, og sagde: «So skal du tala når du kjem attende til Balak!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Då han kom attende, stod Balak endå ved brennofferet, og Moabs hovdingar med honom. «Kva sagde Herren?» spurde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Då bar Bileam upp spådomsordet sitt, og kvad: «Kom, Balak, og mitt kvede høyr, lyd på min song, son åt Sippor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Rett aldri munde Gud sitt ord mishalla som eit menneskje ell’ angra som eit mannebarn. Det han hev sagt, set han i verk det han hev lova, held han og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Velsigning send’ han - signar han, so kann eg ikkje venda det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Aldri hjå Jakob naud du såg, ell’ ulukka hjå Israel; Herren, hans Gud, er med han stødt, og kongeluren hjå han læt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gud leidd han or Egyptarland, ein urukse med sterke horn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Jakob treng ingi trolldomskunst, og ingen spådom i Israel; når stundi er der, vert det sagt åt Jakob og åt Israel kva Gud vil gjera til kvar tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Sjå, lyden som ei løva ris, som løva lyfter seg til sprang, og ikkje lyster leggja seg, fyrr ho hev metta seg med rov og drukke blod av deim ho drap.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Då sagde Balak til Bileam: «Um du ikkje vil banna deim, so tarv du då ikkje velsigna deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, '«Hev eg ikkje sagt deg at eg i eitt og alt lyt gjera som Herren segjer med meg?» svara Bileam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, '«Kjære, kom,» sagde kongen, «so skal eg fylgja deg til ein annan stad; kann henda Herren ikkje hev noko imot at du bannar deim der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'So tok han Bileam med seg upp på toppen av Peorfjellet, som skodar ned på Øydemoen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Då sagde Bileam til honom: «Bygg sju altar for meg her, og få meg hit sju unge uksar og sju verar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Og Balak gjorde som Bileam sagde, og på kvart alter ein ukse og ein ver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Men no tyktest Bileam sjå at det var Herrens vilje å velsigna Israel, og han gjekk ikkje burt og søkte teikn, som han fyrr hadde gjort; han vende andlitet mot øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'og såg utyver til han fekk auga på Israels-ætterne, som låg der sida um sida. Då kom Guds ande yver honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'og han kvad: «Segjer Bileam, Beors son, mæler mannen med augo att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'han som høyrer ord i frå Gud, syner frå den Allsterke ser, med opna augo sigen ned:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kor gilde buder Jakob hev, kor gjæv ein bustad Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Som bekkjedalar breider seg, som aldehagar kring ei å, aloetrei Herren ol, og cedrarn’, attmed vatnet veks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Utor hans byttor strøymer vatn, og vel hans åker vatna er. Hans konge yver Agag gjeng, og høgt hans rike hevjar seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gud leid’ han or Egyptarland, ein urokse med sterke horn. Fiendefolki upp han et, og knokarn’ deira knasar han, med sine kolvar sund deim skyt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Som løva legg han seg til ro; kven vågar vel å vekkj’ han upp? Gud signe den som signar deg, og banne den som bannar deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Då vart Balak brennande harm på Bileam; han slo i hop henderne, og sagde til honom: «Eg kalla deg hit so du skulde beda vondt yver uvenerne mine, og no hev du velsigna deim tri gonger!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Far no heim med deg so fort du kann! Eg hadde tenkt å løna deg vel, men Herren hev meinka deg løni.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileam svara: «Sagde eg det ikkje straks åt dei mennerne du sende til meg? -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '«Um Balak gjev meg huset sitt fullt av sylv og gull,» sagde eg, «so kann eg ikkje brjota Herrens bod og gjera noko etter min eigen hug, anten godt eller vondt; berre det Herren vil, kann eg tala.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'No fer eg heim att til folket mitt, men fyrst vil eg varsla deg kva dette folket kjem til å gjera men ditt folk i komande dagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'So bar han upp spådomen sin, og kvad: «Segjer Bileam, Beors son, mæler mannen med augo att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'han som høyrer ord ifrå Gud, vita fær det den Høgste veit, syner frå den Allsterke ser, med opna augo sigen ned:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Eg skodar han, men ikkje no, eg augnar han, men ikkje nær - ei stjerna som or Jakob stig, eit spir som sprett or Israel! - Moabs tunnvangar trør han sund, og øyder ufredsætti ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edom vert eigedomen hans, og Se’ir slær han under seg, det uvenern’ hans åtte fyrr; stort velde vinn seg Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Av Jakob ris den råda skal; han ryd ut or byarn’ ut deim som frå bardagen hev berga seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'So såg han amalekitane. Då kvad han dette verset: «Fyrst utav folk er Amalek, men ein gong gjeng han og til grunns.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Og han såg kenitarne, og kvad: «Din bustad er ei borg so fast, på nuten hev ditt reir du bygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Men endå vert det øydelagt snart fører Assur deg av stad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'So kvad han atter: «Ai, ei, kven vert vel etter då, når Gud let dette ganga fram?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Med skip frå Kittimleidi kjem; dei døyver Assur, døyver deim som burtanfyre elvi bur, so dei og utor heimen kverv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'So gjorde Bileam seg reidug, og for heim att, og Balak tok og på si leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Med Israels-folket heldt til i Sittim, tok folket til å fljuga etter kvinnorne i Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Og Moabs-kvinnorne bad deim til blotveitslorne åt guden sin; so åt dei med deim og bøygde kne for guden deira;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Israel tydde seg til Ba’al-Peor. Då vart Herren brennande harm på Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'og Herren sagde til Moses: «Tak med deg alle Israels hovdingar, og legg desse mennerne på stegl for Guds og alle manns augo, so Herrens brennande vreide kann vendast burt frå Israel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Og Moses sagde til styresmennerne i Israel: «Kvar av dykk skal slå i hel deim av folki sine som hev halde seg til Ba’al-Peor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Best det var, kom ein av Israels-sønerne med ei kvinna frå Midjan, og leidde henne heim til sitt eige folk midt for augo på Moses og heile Israels-lyden, med dei sat og syrgde i møtetjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Då Pinehas, son åt Eleazar og soneson åt Aron, øvstepresten, såg det, steig han fram or lyden, og treiv eit spjot');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'og gjekk etter mannen inn i koven, og rende spjotet gjenom deim båe, mannen og kvinna, so det gjekk inn i livet hennar. Då stanna sotti som herja Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Men talet på deim som døydde i sotti, var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '«Pinehas, son åt Eleazar og soneson åt Aron, øvstepresten, hev vendt vreiden min burt frå Israels-folket; etter di han stod so strengt på min rett, vilde ikkje eg vera so streng at eg gjorde ende på Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Difor skal du segja honom at eg vil gjera samband med honom, so det skal ganga honom vel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'ævelegt prestedøme lovar eg honom og ætti hans etter honom, for di han var so vyrk for æra åt sin Gud og gjorde soning for Israels-folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Den drepne israeliten, han som vart drepen i hop med den midjanitiske kvinna, heitte Zimri Saluson; han var formann for ei grein av Simeons-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Og midjanitkvinna som vart drepi, heitte Kozbi; ho var dotter åt Sur, som var hovding yver ei ættgrein av midjanitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '«De skal søkja åt midjanitarne og slå deim ned;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'for dei sat um dykk og lagde svikråder mot dykk då det hende, dette med Peor og Kozbi, frenka deira, hovdingdotteri frå Midjan, som vart drepi den gongen sotti kom yver dykk for Peors skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Då sotti var yver, tala Herren so til Moses og Eleazar, son åt Aron, øvstepresten:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '«Tak tal på heile Israels-lyden, ættgrein for ættgrein, alle dei våpnføre i Israel som hev fyllt tjuge år!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'So tala Moses og Eleazar, øvstepresten, åt deim på Moabmoarne ved Jordan, midt for Jeriko, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '«Stig fram, alle menner som hev fyllt tjuge år!» - soleis som Herren hadde sagt med Moses. Israels-sønerne som for frå Egyptarland, det var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, '\'tti etter Ruben, eldste son åt Israel. Og Rubens-sønerne det var: Hanokitarne, ætti etter Hanok, pallu’itarne, ætti etter Pallu,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'hesronitarne, ætti etter Hesron, karamitarne, ætti etter Karmi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Dette var Rubens-ætterne, og av deim var det tri og fyrti tusund og sju hundrad og tretti mann som vart innskrivne i manntalet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Son åt Pallu heitte Eliab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Og borni åt Eliab heitte Nemuel og Datan og Abiram. Men Datan og Abiram, det var dei same som var valde til folketinget, og var med og yppa strid mot Moses og Aron den gongen Korah og flokken hans sette seg upp mot Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'og jordi let upp gapet sitt og gløypte både deim og Korah, og elden gjorde ende på dei tvo hundrad og femti mennerne, so heile flokken umkomst og vart til eit varsl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Men sønerne åt Korah miste ikkje livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeons-sønerne, og det var, etter ætterne deira: Nemuelitarne, ætti etter Nemuel, jaminitarne, ætti etter Jamin, jakinitarne, ætti etter Jakin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'zerahitarne, ætti etter Zerah, sa’ulitarne, ætti etter Sa’ul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Dette var Simeons-ætterne, tvo og tjuge tusund og tvo hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gads-sønerne, og det var, etter ætterne deira: Sefonitarne, ætti etter Sefon, haggitarne, ætti etter Haggi, sunitarne, ætti etter Suni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'oznitarne, ætti etter Ozni, eritarne, ætti etter Eri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'aroditarne, ætti etter Arod, arelitarne, ætti etter Areli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Dette var Gads-ætterne; dei var etter manntalet fyrti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Av borni åt Juda døydde tvo i Kana’ans-landet; dei heitte Er og Onan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Dei hine Juda-sønerne det var, etter ætterne deira: Selanitarne, ætti etter Sela, parsitarne, ætti etter Peres, zerahitarne, ætti etter Zerah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Og Peres-sønerne det var, etter ætterne deira: Hesronitarne, ætti etter Hesron, hamulitarne, ætti etter Hamul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Dette var Juda-ætterne. Av deim vart seks og sytti tusund og fem hundrad mann skrivne i rullorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Issakars-sønerne, og det var, etter ætterne deira: Tola’itarne, ætti etter Tola, punitarne, ætti etter Puvva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'jasubitarne, ætti etter Jasub, simronitarne, ætti etter Simron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Dette var Issakars-ætterne. Av deim var det fire og seksti tusund og tri hundrad mann som vart mynstra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sebulons-sønerne, og det var, etter ætterne deira: Sarditarne, ætti etter Sered, elonitarne, ætti etter Elon, jahle’elitarne, ætti etter Jahle’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Dette var Sebulons-ætterne. Av deim vart det mynstra seksti tusund og fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Sønerne åt Josef med ætterne sine var Manasse og Efraim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manasse-sønerne det var: Makiritarne, ætti etter Makir. Makir fekk sonen Gilead; frå honom var gileaditarne ætta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Gileads-sønerne det var: I’ezritarne, ætti etter I’ezer, helkitarne, ætti etter Helek,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'asrielitarne, ætti etter Asriel, sikmitarne, ætti etter Sekem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'semida’itarne, ætti etter Semida, hefritarne, ætti etter Hefer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Men Selofhad, son åt Hefer, hadde ingi søner, berre døtter, og namni på døtterne hans var Mahla og Noa og Hogla og Milka og Tirsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Dette var Manasse-ætterne. Av deim var det tvo og femti tusund og sju hundrad mann som vart innskrivne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Efraims-sønerne det var, etter ætterne deira: Sutalhitarne, ætti etter Sutelah, bakritarne, ætti etter Beker, tahanitarne, ætti etter Tahan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Og Sutelah-sønerne det var: Eranitarne, ætti etter Eran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Dette var Efraims-ætterne; dei var tvo og tretti tusund og fem hundrad mann som vart skrivne. Det var Josefs-sønerne etter ætterne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjamins-sønerne, og det var, etter ætterne deira: Balitarne, ætti etter Bela, asbelitarne, ætti etter Asbel, ahiramitarne, ætti etter Ahiram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'sufamitarne, ætti etter Sefufam, hufamitarne, ætti etter Hufam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Og Bela-sønerne var: Arditarne og na’amanitarne; ætterne etter Ard og Na’aman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Dette var Benjamins-sønerne etter ætterne deira; av deim var det fem og fyrti tusund og seks hundrad mann som stod i manntalet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Dans-sønerne det var, etter ætterne deira: Suhamitarne, ætti etter Suham. Dette var Dans-ætterne etter ættetavla deira;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Suhamit-ætterne var etter manntalet i alt fire og seksti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Assers-sønerne, og det var, etter ætterne deira: Jimnitarne, ætti etter Jimna, jisvitarne, ætti etter Jisvi, beri’itarne, ætti etter Beria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Og Beria-sønerne det var: Hebritarne, ætti etter Heber, malkielitarne, ætti etter Malkiel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Dotter åt Asser heitte Serah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Dette var Assers-ætterne; av deim stod det tri og femti tusund og fire hundrad mann i rullorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naftali-sønerne, og det var, etter ætterne deira: Jahse’elitarne, ætti etter Jahse’el, gunitarne, ætti etter Guni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'jisritarne, ætti etter Jeser, sillemitarne, ætti etter Sillem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Dette var Naftali-ætterne etter ættetalet deira; av deim vart det innskrive fem og fyrti tusund og fire hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'So mange var det som vart mynstra av Israels-sønerne, seks hundrad og eitt tusund og sju hundrad og tretti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Og Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '«Åt desse skal landet skiftast ut til eigedom, etter folketalet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Den som hev mykje folk, skal du gjeva mykje land, og den som hev lite folk mindre; kvar ætt skal få so mykje land som han hev våpnføre menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Landet skal skiftast på den måten at dei dreg strå um bygderne, og alle som hev same ættarnamnet, skal få sin eigedom i same bygdelaget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Kvar skal få det som fell på honom etter strået, men den som hev mykje folk, skal få meir enn den som hev lite; soleis skal landet bytast millom deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Levi-ætterne det var etter manntalet: Gersonitarne, ætti etter Gerson, kahatitarne, ætti etter Kahat, meraritarne, ætti etter Merari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Desse ættgreinerne var det i Levi-ætti: Libnitarne, hebronitarne, mahlitarne, musitarne, korahitarne. Kahat var far åt Amram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Kona åt Amram heitte Jokebed; ho var dotter åt Levi og fødd i Egyptarland. Amram fekk med henne sønerne Aron og Moses, og Mirjam, syster deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Og Aron fekk sønerne Nadab og Abihu, Eleazar og Itamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Men Nadab og Abihu døydde då dei bar uvigd eld fram for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Av levitarne vart tri og tjuge tusund innskrivne i manntalet, alle karfolk som var yver ein månad gamle. Dei vart ikkje talde saman med dei hine Israels-borni, av di dei ikkje fekk nokon odel millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Dette var dei som Moses og Eleazer, øvstepresten, talde då dei mynstra Israels-sønerne på Moabmoarne ved Jordan, midt for Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Millom deim fanst det ingen som Moses og Aron, øvstepresten, hadde skrive inn i manntalet då dei mynstra Israels-sønerne i Sinaiheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'For Herren hadde sagt at dei skulde døy i øydemarki, og no var det ingen annan att enn Kaleb, son åt Jefunne, og Josva, son åt Nun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Men døtterne åt Selofhad - dei heitte Mahla og Noa og Hogla og Milka og Tirsa, og var ætta frå Manasse, Josefs son; for Selofhad, far deira, var son åt Hefer, son åt Gilead, son åt Makir, son åt Manasse -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'dei gjekk fram i møtetjelddøri, og stod framfor Moses og Eleazer, øvstepresten, og alle hovdingarne og heile lyden, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '«Far vår døydde i øydemarki, men han var ikkje med i den flokken som sette seg upp mot Herren - i Korah-flokken - han døydde for si synd skuld, og han hadde ingi søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Skal no namnet åt far vår ganga ut or ætti av di han ingen son hadde? Gjev oss odel tilliks med farbrørne våre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Moses bar saki deira fram for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Og Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '«Det er rett som døtterne åt Selofhad segjer. Du skal gjeva deim odel tilliks med farbrørne deira, og lata farsgarden ganga i arv til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Og til Israels-folket skal du segja: «Når ein mann døyr, og ikkje hev nokon son, so skal de lata garden hans ganga i arv til dotteri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Hev han ingi dotter, so skal de gjeva brørne hans garden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'og hev han ikkje brør, so skal de lata farbrørne hans få garden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'men hadde ikkje faren nokon bror, so skal den næmaste skyldingen i ætti få garden til odel og eiga. Dette skal gjelda for rett hjå Israels-folket, soleis som Herren hev sagt med Moses.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Sidan sagde Herren til Moses: «Stig upp på Abarimfjellet her, og sjå utyver landet som eg hev gjeve Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Og når du hev set det, skal du og fara til federne dine, som Aron, bror din, fyre deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'av di de var ulyduge mot meg i Sinheidi, då lyden trætta, og de ikkje vilde syna deim mi guddomsmagt og lata vatnet strøyma fram for augo deira.» - Av det hev Meribavatnet ved Kades i Sinheidi fenge namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Då tala Moses til Herren og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '«Herre, du som kjenner kvar manns hug, vil ikkje du setja ein mann yver lyden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'som kann ganga fyre deim både heime og burte og fylgja deim både ut og inn, so ikkje lyden din skal vera som ein saueflokk utan hyrding!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Og Herren sagde til Moses: «Tak Josva, son åt Nun! Han er ein heilag mann. Legg handi på hovudet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'og leid honom fram for Eleazar, øvstepresten, og for heile lyden, og set honom inn til styresmann framfor augo deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'og gjev honom noko av den vyrdnaden du hev med deg, so kjem heile Israels-lyden til å høyra på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Og han skal ganga fram for Eleazar, øvstepresten, og Eleazar skal for Herrens åsyn spyrja urim-oraklet for honom, og etter hans ord skal dei retta seg i alt dei tek seg fyre, både Josva og heile Israels-borni og heile lyden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Moses gjorde som Moses sagde; han tok og leidde Josva fram for Eleazar, øvstepresten, og heile lyden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'og Eleazar lagde henderne på honom, og sette honom inn til styresmann, som Herren hadde havt Moses til å segja med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '«So skal du segja til Israels-sønerne: «Offeri mine, maten min, dei angande retterne mine lyt de koma i hug å bera fram for meg på si visse tid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Seg til deim: «So skal dei rettarne vera som de ber fram for Herren: Tvo årsgamle lytelause lamb um dagen, til fast brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Eitt lamb skal du ofra um morgonen, og eitt solegladsbil,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'og til grjonoffer ei kanna fint mjøl, blanda med ei halvkanna av den beste beroljen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Det skal vera det faste brennofferet, so som det vart frambore på Sinaifjellet til ein kveikjande ange, ein rjukande rett for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Og drykkofferet som høyrer til det eine lambet, skal vera ei halvkanna vin; den skal de skjenkja ut i heilagdomen til kryddedrykk for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Det andre lambet skal du ofra solegladsbil; med same grjonofferet som um morgonen, og same drykkofferet, skal du bera det fram, då er det ein god offerrett, som angar søtt for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Um kviledagen skal du ofra tvo årsgamle lamb utan lyte, og til grjonoffer tvo kannor fint mjøl, blanda med olje, og drykkofferet som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Det er kviledags-brennofferet som skal berast fram kvar helg, umfram det daglege brennofferet og drykkofferet som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Den fyrste dagen i kvar månad skal de bera fram eit brennoffer for Herren: tvo unge uksar og ein ver og sju årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'og til grjonoffer tri kannor fint mjøl, blanda med olje, for kvar ukse, og tvo kannor fint mjøl, blanda med olje, for kvar ver,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'og ei kanna fint mjøl, blanda med olje, for kvart lamb; då er det eit rett brennoffer som angar godt, ein god offerrett for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Og drykkofferet skal vera ei kanna vin for kvar ukse, og tvo pottar for kvar ver, og ei halvkanna for kvart lamb. Dette er månads-brennofferet som de skal bera fram kvar nymånedag i året.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Då skal de og ofra ein geitebukk til syndoffer åt Herren, umfram det daglege brennofferet og drykkofferet som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Den fjortande dagen i den fyrste månaden er det påskehelg for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Og den femtande dagen i den same månaden er det pilegrimshelg; då skal de eta usyrt brød sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Den fyrste dagen skal de halda eit heilagt møte, og må ikkje gjera noko utearbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Og de skal bera fram for Herren ein rjukande brennofferrett: tvo unge uksar og ein ver og sju årsgamle lamb - lytelause skal dei vera -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'og til grjonoffer attåt dei fint mjøl, blanda med olje: tri kannor for kvar ukse og tvo kannor attåt veren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'og ei kanna for kvart av dei sju lambi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'og so ein syndofferbukk til soning for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Dette skal de ofra umfram morgon-brennofferet, som høyrer til den daglege offergåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Sovorne gåvor skal de bera fram kvar av dei sju dagarne: det er offermat som angar godt for Herren; attåt det daglege brennofferet skal de bera det fram, med drykkofferet som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Den sjuande dagen skal de halda eit heilagt møte, og noko utearbeid må de ikkje gjera då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Nygrødedagen, når de ber fram eit nytt grjonoffer for Herren, og høgtidar sjuvikehelgi, då skal de halda eit heilagt møte, og må ikkje gjera noko utearbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Og de skal bera fram eit brennoffer til godange for Herren: tvo unge uksar og ein ver og sju årsgamle lamb,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'og til grjonoffer fint mjøl, blanda med olje, tri kannor for kvar ukse, og tvo kannor for kvar ver,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'og ei kanna for kvart av dei sju lambi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'og so ein geitebukk til soning for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Det skal de ofra umfram det daglege brennofferet og grjonofferet som høyrer til. Offeri skal vera lytelause, og dei vanlege drykkofferi skal fylgja med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Den fyrste dagen i den sjuande månaden skal de halda eit heilagt møte, og må ikkje gjera noko utearbeid; den dagen skal lurarne ljoma,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'og de skal bera fram for Herren eit brennoffer som angar godt: ein ung ukse, ein ver, sju årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'og grjonofferet som høyrer til: fint mjøl, blanda med olje, tri kannor attåt uksen, og tvo kannor attåt veren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'og ei kanna for kvart av dei sju lambi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'og so ein syndofferbukk til soning for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'umfram månads-brennofferet og grjonofferet som høyrer til det, og umfram det faste brennofferet med sitt grjonoffer og dei vanlege drykkofferi; då er det ein god offerrett, som angar søtt for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Tiande dagen i den same sjuande månaden skal de halda eit heilagt møte. Då skal de fasta og ikkje gjera noko arbeid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'og de skal bera fram for Herren eit brennoffer som angar godt: ein ung ukse, ein ver, sju årsgamle lamb - lytelause skal dei vera -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'og grjonofferet som høyrer til: fint mjøl, blanda med olje, tri kannor attåt uksen, og tvo kannor attåt veren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'og ei kanna for kvart av dei sju lambi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'og so ein geitebukk til syndoffer, umfram sonings-syndofferet og det daglege brennofferet med grjonofferet og drykkofferi som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Femtande dagen i den sjuande månaden skal de samlast til eit heilagt møte, og må ikkje gjera noko utearbeid; og de skal halda pilegrimshelg for Herren i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Då skal de bera fram for Herren ein brennofferrett, som angar godt for Herren: trettan unge uksar, tvo verar, fjortan årsgamle lamb - lytelause skal dei vera -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'og grjonofferet som høyrer til: fint mjøl, blanda med olje, tri kannor for kvar av dei trettan uksarne, og tvo kannor for kvar av dei tvo verarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'og ei kanna for kvart av dei fjortan lambi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'og so ein geitebukk til syndoffer, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Andre dagen skal de bera fram tolv unge uksar, tvo verar, fjortan årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'og grjonoffer og drykkoffer som vanleg, svarande til uksarne og verarne og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'og ein geitebukk til syndoffer, umfram det daglege brennofferet med sitt grjonoffer og sine drykkoffer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'tridje dagen elleve uksar, tvo verar, fjortan årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'og grjonoffer og drykkoffer som vanleg, svarande til uksarne og verarne og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'og ein syndofferbukk, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'fjorde dagen ti uksar, tvo verar, fjortan årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'med grjonoffer og drykkoffer som vanleg, svarande til uksarne og verarne og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'og ein syndofferbukk, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'femte dagen ni uksar, tvo verar, fjortan årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'med grjonoffer og drykkoffer som vanleg, svarande til uksarne og verarne og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'og ein syndofferbukk, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'sette dagen åtte uksar, tvo verar, fjortan årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'med grjonoffer og drykkoffer som vanleg, svarande til uksarne og verarne og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'og ein syndofferbukk, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'sjuande dagen sju uksar, tvo verar, fjortan årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'med grjonoffer og drykkoffer som vanleg, svarande til uksarne og verarne og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'og ein syndofferbukk, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Åttande dagen skal de halda ei stor samlingshøgtid, og må ikkje gjera noko utearbeid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'og de skal bera fram ein brennofferrett som angar godt: ein ukse, ein ver, sju årsgamle lamb utan lyte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'med grjonoffer og drykkoffer som vanleg, svarande til uksen og veren og lambi etter talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'og ein syndofferbukk, umfram det daglege brennofferet med sitt grjonoffer og drykkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Dette er det de skal ofra Herren på høgtiderne dykkar, umfram det de hev lova eller gjev i godvilje, anten det er brennoffer eller grjonoffer eller drykkoffer eller takkoffer.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Og Moses sagde alt dette med Israels-folket, heiltupp soleis som Herren hadde sagt honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Sidan tala Moses til hovdingarne yver Israels-ætterne, og sagde: «Høyr no eit anna bod som Herren hev gjeve:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Når ein mann hev gjort ein lovnad til Herren, eller svore ein eid, at han vil halda seg ifrå ymse ting, so skal han ikkje brjota ordet sitt; det han hev lova, skal han halda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Når ei ung kvinna, som endå er heime hjå far sin, hev gjort ein lovnad til Herren, og svore at ho vil halda seg ifrå ymse ting,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'og far hennar fær høyra um lovnaden hennar og eiden ho hev bunde seg med, og tegjer til det, so skal det gjelda alt det ho hev lova, og kvar eid ho hev bunde seg med, skal gjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Men dersom far hennar same dagen som han fær høyra um nokon lovnad ho hev gjort, eller nokon eid ho hev bunde seg med, forbyd henne å halda sitt ord, so skal det vera um inkje, og Herren skal gjeva henne til, etter di det var faren som meinka henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Vert ho gift, og hev ein lovnad på seg, eller hev bunde seg med eit tankelaust ord, og sagt at ho vil halda seg ifrå ymse ting,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'og mannen hennar fyrr eller sidan fær vita det, og ikkje segjer noko imot, då skal det gjelda det ho hev lova, og det ordet ho hev bunde seg med, skal gjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Men dersom mannen hennar same dagen som han fær vita det, forbyd henne å halda sitt ord, so gjer han lovnaden ho hev på seg um inkje, og det tankelause ordet ho hev bunde seg med, og Herren skal gjeva henne til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Hev ei enkja eller fråskild kona gjort ein lovnad, og nemnt noko ho vil halda seg ifrå, so skal ho halda ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Når ei kona etter ho er gift hev lova noko, eller bunde seg med eid til å halda seg ifrå eitt eller anna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'og mannen hennar fær vita det, men tegjer og ikkje forbyd henne å halda sitt ord, so skal det gjelda alt det ho hev lova, og kvar eid ho hev bunde seg med, skal gjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Men dersom mannen hennar gjer det um inkje same dagen som han fær høyra um det, so gjeld ikkje noko av dei ordi ho soleis hev slept av munnen, anten det er ein lovnad ho hev gjort, eller det er noko ho hev svore seg ifrå: Mannen hennar hev gjort det um inkje, og Herren skal gjeva henne til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Kvar lovnad ho hev gjort og kvar eid ho hev svore um å halda seg ifrå eitt eller hitt og spekja seg, kann mannen hennar anten stadfesta eller gjera um inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Men tegjer han um det til andre dagen, so hev han stadfest alt det ho hev lova eller bunde seg til; han hev stadfest det med di han tagde då han fekk vita det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Og gjer han det fyrst um inkje ei tid etter han fekk høyra um det, so ber han ansvaret for brotet hennar.» Dette er dei fyresegnerne Herren gav Moses um den retten ein mann hev yver kona si, og ein far yver dotter si, so lenge ho er ung og er heime hjå faren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Og Herren tala til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '«Du skal taka hemn for det som midjanitarne hev gjort Israels-borni; sidan skal du fara til federne dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Då tala Moses til folket, og sagde: «Lat nokre av mannskapet dykkar bu seg til herferd! Dei skal koma yver midjanitarne, og føra Herrens hemn yver Midjan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Tusund mann frå kvar av Israels-ætterne skal de senda ut i herferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Av dei mange tusund i Israel baud dei då ut tusund mann frå kvar ætt, tolv tusund herbudde menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Deim sende Moses ut i herferd, tusund mann frå kvar ætt, og med deim sende han Pinehas, son åt Eleazar, øvstepresten; han hadde med seg dei heilage gognerne og stridslurarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Og dei gjorde ei herferd mot Midjan, so som Herren hadde sagt med Moses, og slo i hel alle karmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Og millom deim som dei drap, var kongarne i Midjan, Evi og Rekem og Sur og Hur og Reba, dei fem Midjans-kongarne; og Bileam, son åt Beor, fall og for sverdet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'So tok dei konorne og borni åt midjanitarne og klyvdyri og bufeet deira og alt det dei åtte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'og alle borgarne i det landet dei hadde slege seg ned i og alle tjeldlægri deira, sette dei eld på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Og alt herfanget og alt folket og feet dei hadde teke,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'førde dei dit som Moses og Eleazar, øvstepresten, og heile Israels-lyden var - til lægret på Moabmoarne ved Jordan, midt for Jeriko - både fangarne og feet og alt det andre herfanget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Og Moses og Eleazar, øvstepresten, og alle dei høgste i lyden gjekk til møtes med deim utanfor lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Men Moses var vond på hovdingarne som kom heim frå stridsferdi, både dei som stod yver tusund og dei som stod yver hundrad mann,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'og han sagde til deim: «Hev de spart alle kvinnorne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Det var då dei som lydde Bileams råd og lokka Israels-sønerne til å svika Herren for Peors skuld, so sotti kom yver Herrens lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Slå no i hel alle sveinborn, og alle kvinnor som hev ått mann eller havt med karfolk å gjera!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Men alle ungmøyar som ikkje hev havt med karfolk å gjera, skal de spara, og dei skal høyra dykk til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Og so lyt de halda dykk utanfor lægret i sju dagar, og alle som hev slege nokon i hel eller kome nær nokon som er i helslegen, lyt reinsa seg for synd den tridje og den sjuande dagen, både dei og fangarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Og alle klæde, og alt som er gjort av ler eller geiteragg, og alle trekjerald lyt de reinsa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Og Eleazar, øvstepresten, sagde til dei mennerne som hadde vore med i herferdi: «Denne fyresegni hev Herren gjeve Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Gull og sylv, kopar og jarn, tin og bly,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'alt som toler eld, skal de hava i elden, so vert det reint; de lyt berre etterpå skira det med vigslevatn; men alt som ikkje toler eld, skal de hava i vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Og den sjuande dagen skal de två klædi dykkar, so vert de reine, og sidan kann de koma inn i lægret.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Og Herren sagde til Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '«Du og Eleazar, øvstepresten, og ættehovdingarne i lyden skal taka tal på alt folket og feet som er fanga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'og skifta det likt millom stridsmennerne som var med i herferdi og alt hitt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Og du skal taka ei avgift av stridsmennerne: eitt liv for kvart femhundrad, både av folk og av storfe og asen og småfe;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'det skal de taka av den helvti som fell på herfolket, og gjeva det til Eleazar, øvstepresten; det skal vera ei reida til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Og av den helvti som fell på dei hine Israels-sønerne, skal du taka ut eit liv for kvart halvhundrad, både av folk og av kyr og asen og sauer - av alt feet - og gjeva deim til levitarne som hev umsut med alt det som skal gjerast i Herrens hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Moses og Eleazar, øvstepresten, gjorde som Herren hadde sagt til Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Og herfanget, det som var att av alt det stridsfolket hadde teke, det var: sauer og geiter: seks hundrad og fem og sytti tusund;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'uksar og kyr: tvo og sytti tusund;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'asen: ein og seksti tusund;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'av folk - kvinnor som ikkje hadde vore nær nokon karmann - var det i alt tvo og tretti tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Helvti av dette, den luten som fall på hermennerne, var då: småfe: tri hundrad og sju og tretti tusund og fem hundrad i talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'so avgifti til Herren av sauerne og geiterne vart seks hundrad og fem og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'uksar og kyr: seks og tretti tusund; av deim var avgifti til Herren tvo og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'asen: tretti tusund og fem hundrad, og avgifti av deim til Herren ein og seksti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'fangar: sekstan tusund, og av deim i avgift til Herren tvo og tretti ungmøyar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Og Moses gav avgifti, det som skulde vera reida åt Herren, til Eleazar, øvstepresten, som Herren hadde sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Den helvti som kom på dei hine Israels-sønerne, og som Moses hadde skift ifrå hermennerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'den helvti som lyden fekk, det var: tri hundrad og sju og tretti tusund og fem hundrad sauer og geiter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'og seks og tretti tusund uksar og kyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'og tretti tusund og fem hundrad asen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'og sekstan tusund fangar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Av denne helvti - den som fall på Israels-sønerne - tok Moses ut eit liv for kvart halvhundrad av både folk og fe, og gav deim til levitarne som greidde det som skulde gjerast i Herrens hus, soleis som Herren hadde sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'So gjekk hovdingarne yver herflokkarne, både dei yver tusund og dei yver hundrad mann, fram for Moses');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'og sagde til honom: «Me hev teke tal på stridsmennerne som me hadde under oss, og det vantar ikkje ein mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Difor kjem me no kvar med det gullet me hev vunne: armringar og armband og fingerringar og øyreringar og kulelekkjor; det skal vera ei gåva til Herren og ein løysepening for livet vårt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Og Moses og Eleazar, øvstepresten, tok imot gullet dei kom med; alt saman var det fint arbeidde ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Gullet som dei vigde åt Herren, var i alt elleve hundrad merker; det var gåva frå hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Men mannskapet hadde og vunne mykje gull, kvar åt seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Då Moses og Eleazar, øvstepresten, hadde teke imot gullet av hovdingarne, bar dei det inn i møtetjeldet og gøymde det der til ei minning for Herren um Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rubens-sønerne og Gads-sønerne hadde mykje bufe - uhorveleg mykje. Då dei no såg dei gode beitemarkerne i landet kring Jazer og i Gileadlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'kom dei og sagde til Moses og Eleazar, øvstepresten, og hovdingarne i lyden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '«Atarot og Dibon og Jazer og Nimra og Hesbon og Elale og Sebam og Nebo og Beon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'dei bygderne som Herren hev vunne for Israels-lyden, det er gode febygder, og me hev mykje fe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, '«Vil du gjera vel mot oss», sagde dei, so lat oss få det landet til odel og eiga, og før oss ikkje yver Jordan!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Då sagde Moses til Gads-sønerne og Rubens-sønerne: «Skal brørne dykkar ganga i striden, og de setja dykk til her?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Vil de då gjera Israels-sønerne uhuga til å fara yver åt det landet som Herren hev gjeve deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Det var det federne dykkar gjorde då eg sende deim ut frå Kades-Barnea til å skoda landet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'dei for upp til Eskoldalen og såg på landet, og so skræmde dei Israels-sønerne, so dei miste hugen til å koma inn i det landet som Herren hadde gjeve deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Den dagen vart Herren brennande harm, og han svor:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '«Ingen av dei mennerne som for upp frå Egyptarland, og er yver tjuge år gamle, skal få sjå det landet eg hev lova Abraham og Isak og Jakob; for dei hev ikkje lydt meg som dei skulde -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'ingen utan Kaleb Jefunneson av Kenaz-ætti og Josva Nunsson; dei hev vore trugne til å fylgja Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Herren vart harm på Israel og let deim flakka ikring i øydemarki i fyrti år, til det var ende på heile den ætti som hadde gjort Herren imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Og no hev de stige i staden åt federne dykkar, eit elde av synduge menner, og aukar endå meir Herrens harm imot Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'For slær de dykk ifrå og ikkje vil fylgja honom, so kjem han til å halda deim endå lenger i øydemarki, og de fører ulukka yver heile dette folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Då gjekk dei fram for Moses og sagde: «Me vil gjera kvier for feet vårt her og byggja borgar for konorne og borni våre;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'og so vil me væpna oss snøggast me vinn og fara fyre dei hine Israels-sønerne, til me hev ført deim dit dei skal; men konorne og borni våre skal sitja att i borgerne, so dei er trygge for folket her i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Me skal ikkje venda heim att, fyrr Israels-borni hev fenge kvar sin eigedom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'for me vil ikkje taka land saman med dei andre på hi sida Jordan og lenger undan, når me fær vårt land på denne sida, austanfor Jordan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, '«Ja, gjer de det,» sagde Moses, «væpnar de dykk til striden for Herrens augo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'og alle stridsmennerne dykkar fer yver Jordan for Herrens augo, til han hev drive fiendarne sine or syne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'og vender de’kje heim att fyrr landet er vunne for Herrens augo, so hev de ingi skuld på dykk, korkje mot Herren eller Israel, og dette landet her skal vera dykkar eigedom med Herrens vilje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Men gjer de det ikkje, då syndar de imot Herren, og skal få kjenna at syndi finn dykk att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bygg borgar for konorne og borni dykkar, og stell til kvier for småfeet, og gjer som de hev lova!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, '«Me vil gjera som du segjer, herre,» svara dei;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, '«borni og konorne våre og feet og alle klyvdyri skal vera her i Gileads-borgerne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'men sjølve vil me ganga yver Jordan for Herrens augo til strid, kvar våpnfør mann, soleis som du hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'So tala Moses um det til Eleazar, øvstepresten, og Josva Nunsson og hovdingarne yver alle Israels-ætterne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'og sagde: «Gjeng Gads-sønerne og Rubens-sønerne, so mange som er våpnføre, med dykk yver Jordan for Herrens augo, og landet vert teke, so skal de gjeva deim Gileadlandet til eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Men gjeng dei ikkje stridsbudde med dykk yver, so skal dei få eigedomen sin i Kana’ans-landet, saman med dykk andre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Og Gads-sønerne og Rubens-sønerne svara: «Det som Herren hev sagt til oss, det vil me gjera:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'me vil fara stridsbudde yver til Kana’ans-landet for Herrens augo, men odelseiga vår skal vera her på denne sida av Jordan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Då gav Moses Gads- og Rubens-ætterne og halve Manasse-ætti dei riki som Sihon, amoritarkongen, og Og, kongen i Basan, hadde ått, heile landet med alle byarne rundt ikring og markerne som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Og Gads-sønerne bygde upp att Dibon og Atarot og Aroer');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'og Atrot-Sofan og Jazer og Jogbeha');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'og Bet-Nimra og Bet-Haran - faste borger og fekvier.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Og Rubens-sønerne bygde upp att Hesbon og Elale og Kirjatajim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'og Nebo og Sibma og Ba’al-Meon, den siste vende dei namnet på; elles let dei borgerne hava dei gamle namni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Sønerne åt Makir, Manasses son, for til Gileadlandet, og tok det, og dreiv ut amoritarne som budde der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Og Moses gav Makirs-ætti Gilead, og dei sette seg ned der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Ja’ir, son åt Manasse, for av stad og tok tjeldbyarne deira, og kalla deim Ja’irsbyarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Og Nobah for av, og tok Kenatborgi og grenderne der ikring og gav borgi sitt eige namn, Nobah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'No skal eg nemna dei staderne der Israels-folket tok læger på ferdi si, då Moses og Aron førde flokkarne deira burt frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'For kvar gong dei tok ut ifrå lægret, skreiv Moses upp kvar dei var, so som Herren hadde sagt med honom, og her er namni på lægerstaderne deira etter som dei for fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Femtande dagen i fyrste månaden tok Israels-sønerne ut frå Ra’amses, påskedagen for dei i veg med tråss i hugen, midt for augo på alle egyptarane;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'egyptarane heldt då på og jorda alle sine frumborne, deim som Herren hadde slege i hel; for Herren hadde halde dom yver gudarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Då Israels-sønerne hadde fare frå Ramses, lægra dei seg fyrst i Sukkot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'So tok dei ut frå Sukkot, og lægra seg i Etam, ytst utmed øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'So tok dei ut frå Etam, men sidan snudde dei um, og tok vegen til Pi-Hakhirot, som ligg midt imot Ba’al-Sefon, og dei lægra seg framanfor Migdol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'So tok dei ut frå Pi-Hakhirot, og for tvert igjenom havet til øydemarki, og då dei hadde fare tri dagar i Etammarki, lægra dei seg i Mara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'So tok dei ut frå Mara, og kom til Elim. I Elim var det tolv vatskjeldor og sytti palmetre, og dei lægra seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'So tok dei ut frå Elim, og lægra seg ved Raudehavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'So tok dei ut frå Raudehavet, og lægra seg i Sinheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'So tok dei ut frå Sinheidi, og lægra seg i Dofka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'So tok dei ut frå Dofka, og lægra seg i Alus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'So tok dei ut frå Alus, og lægra seg i Refidim; men der fanst det ikkje vatn so folket kunde få drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'So tok dei ut frå Refidim, og lægra seg i Sinaiheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'So tok dei ut frå Sinaiheidi, og lægra seg i Kibrot-Hatta’ava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'So tok dei ut frå Kibrot-Hatta’ava, og lægra seg i Haserot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'So tok dei ut frå Haserot, og lægra seg i Ritma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'So tok dei ut frå Ritma, og lægra seg i Rimmon-Peres.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'So tok dei ut frå Rimmon-Peres, og lægra seg i Libna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'So tok dei ut frå Libna, og lægra seg i Rissa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'So tok dei ut frå Rissa, og lægra seg i Kehelata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'So tok dei ut frå Kehelata, og lægra seg innmed Seferfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'So tok dei ut frå Seferfjellet, og lægra seg i Harada.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'So tok dei ut frå Harada, og lægra seg i Makhelot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'So tok dei ut frå Makhelot, og lægra seg i Tahat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'So tok dei ut frå Tahat, og lægra seg i Tarah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'So tok dei ut frå Tarah, og lægra seg i Mitka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'So tok dei ut frå Mitka, og lægra seg i Hasmona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'So tok dei ut frå Hasmona, og lægra seg i Moserot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'So tok dei ut frå Moserot, og lægra seg i Bene-Ja’akan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'So tok dei ut frå Bene-Ja’akan, og lægra seg i Hor-Hagidgad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'So tok dei ut frå Hor-Hagidgad, og lægra seg i Jotbata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'So tok dei ut frå Jotbata, og lægra seg i Abrona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'So tok dei ut frå Abrona, og lægra seg i Esjon-Geber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'So tok dei ut frå Esjon-Geber, og lægra seg i Sinheidi, i Kades.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'So tok dei ut frå Kades, og lægra seg attmed Horfjellet, i landskilet med Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Og Aron, øvstepresten, gjekk upp på Horfjellet, som Herren hadde sagt med honom, og der døydde han i det fyrtiande året etter Israels-sønerne hadde teke ut frå Egyptarlandet, fyrste dagen i femte månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aron var hundrad og tri og tjuge år gamall då han døydde på Horfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Men den kananitiske kongen som budde i Arad, i sørluten av Kana’an, fekk høyra at Israels-sønerne kom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'då tok dei ut frå Horfjellet, og lægra seg i Salmona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'So tok dei ut frå Salmona, og lægra seg i Punon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'So tok dei ut frå Punon, og lægra seg i Obot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'So tok dei ut frå Obot, og lægra seg i Ijje-ha-Abarim i landskilet med Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'So tok dei ut frå Ijjim, og lægra seg i Dibon-Gad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'So tok dei ut frå Dibon-Gad, og lægra seg i Almon-Diblataima.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'So tok dei ut frå Almon-Diblataima, og lægra seg i Abarimfjelli, austanfor Nebo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'So tok dei ut frå Abarimfjelli, og lægra seg på Moabmoarne ved Jordanelvi der ho renn frammed Jeriko;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'lægret deira låg langs med Jordan, og rakk frå Bet-ha-Jesjimot til Abel-hasj-sjittim på Moabmoarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Og Herren tala til Moses på Moabmoarne ved Jordan, midt for Jeriko, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '«Tala til Israels-sønerne, og seg til deim: «Når de fer yver Jordan og kjem til Kana’ans-landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'so skal de driva ut deim som bur der i landet, og knasa alle bilætsteinarne deira, og slå sund alle gudelikjendi dei hev støypt seg, riva ned alle hovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'De skal eigna til dykk landet, og setja dykk ned der; for dykk hev eg gjeve det landet til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'De skal skifta det millom dykk etter ætter, og draga strå um bygderne. Den som hev mykje folk, skal de gjeva mykje jord, og den som hev lite folk mindre. Kvar skal få den eigedomen som strået hans kjem ut med. Etter ætterne de høyrer til skal landet bytast millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Men driv de deim ikkje ut, dei som no bur i landet, so skal dei som de sparer verta tornar i augo og broddar i sidorne dykkar, og dei skal plåga dykk i dykkar eige land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Og det som eg hadde sett meg fyre å gjera med deim, det skal eg då gjera med dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Og Herren tala meir til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '«Seg til Israels-sønerne: «Når de kjem inn i Kana’ans-landet - det er det landet de skal hava og eiga, heile Kana’ans-landet so vidt som det er -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'so skal landeskilet dykkar på sudsida ganga frå Sinheidi langs med Edom, den søre bytestrengen skal i aust ganga ut ifrå enden av Saltsjøen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'og svinga sudum Skorpionskardet, og so taka yver til Sin; so skal han ganga fram sunnanfor Kades-Barnea, til han når Hasar-Addar, og so taka yver til Asmon;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'frå Asmon skal bytet svinga burt til Egyptarlands-bekken, og so ganga i havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'I vest skal landet støyta til Storhavet; det skal vera landskilet dykkar mot vest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'På nordsida skal landskilet ganga soleis. Frå Storhavet skal de draga skiftelina til Horfjellet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'og frå Horfjellet dit som vegen ber til Hamat; der skal bytet ganga ut ved Sedad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'sidan skal det halda fram til Zifron, og so enda ved Hasar-Enan. Dette skal vera landskilet dykkar mot nord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'I aust skal de setja landskilet etter ei lina som gjeng frå Hasar-Enan til Sefam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Frå Sefam skal bytet ganga nedetter til Ha-ribla, i aust for Ajin, og so lenger ned, til det når berghallet austanfor Kinneretsjøen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'so skal det ganga nedåt Jordan, og ut i Saltsjøen. Det skal vera landet dykkar, etter bytemerki sine rundt ikring.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Og Moses sagde til Israels-sønerne: «Dette er det landet som de skal få til odel og eiga; de skal skifta det i luter, og draga strå um luterne; det er det landet som Herren hev sagt skal gjevast åt dei ni ætterne og den eine halve ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'For Rubens-ætti med greinerne sine og Gads-ætti med sine greiner og den halve Manasse-ætti hev fenge dei eigorne dei skal hava;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'desse tvo ætterne og den halve ætti hev fenge sin eigedom på denne sida av Jordanelvi, som renn frammed Jeriko - i aust, der soli kjem upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '«Høyr no kva dei er for menner som skal skifta ut landet millom dykk; Eleazar, øvstepresten, og Josva Nunsson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'og so ein hovding frå kvar ætt, som de skal taka til utskiftingsmann;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'det er av Juda-ætti Kaleb, son åt Jefunne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'og av Simeons-ætti Semuel, son åt Ammihud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'og av Benjamins-ætti Elidad, son åt Kislon;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'so ein hovding av Dans-ætti: Bukki, son åt Jogli;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'og av Josefs-sønerne ein hovding av Manasse-ætti: Hanniel, son åt Efod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'og ein hovding av Efraims-ætti: Kemuel, son åt Siftan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'so ein hovding av Sebulons-ætti: Elisafan, son åt Parnak;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'og ein hovding av Issakars-ætti: Paltiel, son åt Azzan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'og ein hovding av Assers-ætti: Akhihud, son åt Selomi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'og ein hovding av Naftali-ætti: Pedael, son åt Ammihud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Desse mennerne var det som Herren sagde skulde skifta eigedomarne millom Israels-sønerne i Kana’ans-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Og Herren tala atter til Moses på Moabmoarne ved Jordan, midt for Jeriko, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '«Seg til Israels-sønerne: «De skal gjeva levitarne byar til bustad i det landet de kjem til å eiga, og utmarki som ligg ikring, skal de og lata levitarne få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Byarne skal dei hava til å bu i, og utmarki som høyrer til, skal vera til beite for klyvdyri og feet og all buskapen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Utmarki som de gjev levitarne, skal nå tusund alner ut ifrå bymuren rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Utanfor byen skal de mæla upp tvo tusund alner på austsida, og tvo tusund alner på sudsida, og tvo tusund alner på vestsida, og tvo tusund alner på nordsida, og byen skal liggja midt i; det skal vera bymarkerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Dei byarne som de gjev levitarne, skal vera dei seks fredstaderne, som dråpsmenner kann røma til, og attåt deim skal de gjeva tvo og fyrti andre byar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'I alt skal de gjeva levitarne åtte og fyrti byar med beitemarkerne som høyrer til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Og av dei byarne som de gjev deim av eigedomen åt Israels-sønerne, skal dei taka fleire frå den som hev mykje land, og færre frå den som hev lite. Kvar skal gjeva levitarne byar etter som han hev fenge land til.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Og Herren tala atter til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '«Tala til Israels-sønerne og seg til deim: «Når de fer yver Jordan og til Kana’ans-landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'so lyt de velja dykk ut nokre byar som de skal hava til fredstader, so ein dråpsmann som uviljande hev drepe nokon, kann røma dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Dei byarne skal vera dykk til ei trygd mot den som vil hemna dråpet, so dråpsmannen ikkje skal lata livet, fyrr han hev stade til doms for lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Dei byarne som de tek til fredstader, skal vera seks i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tri av deim skal vera på austsida av Jordan og tri i Kana’ans-landet; fredstader skal dei vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Både for Israels-borni og for dei framande og innflutte som bur millom deim, skal desse seks byarne vera til ei livd, so den som uviljande hev drepe nokon, kann søkja dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Den som slær ein med eit jarnhandyvle, so han døyr, han er ein manndråpar, og manndråparen skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Tek nokon ein stein, stor nok til å drepa ein mann, og slær ein med so han døyr, då er han ein manndråpar, og manndråparen skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Tek nokon eit trehandyvle som dei kann drepa folk med, og slær ein med det, so han døyr, då er han ein manndråpar, og manndråparen skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Det er blodhemnaren kann slå manndråparen i hel; so snøgt som han finn honom, skal han slå honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Dersom nokon støyter til ein av hat, eller kastar noko på honom med vilje, so han døyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'eller av fiendskap slær ein med neven, so han døyr, so skal den som gjorde det lata livet; han er ein manndråpar: og blodhemnaren skal slå honom i hel so snøgt han finn honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Men dersom nokon støyter til ein av vanvare, utan fiendskap, eller kastar einkvar tingen på honom mot sin vilje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'eller råmar honom med ein stein, stor nok til å drepa ein mann, og ikkje ser honom, og han døyr av det, men dråpsmannen ikkje var hans uven eller vilde honom vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'då skal lyden døma millom dråpsmannen og blodhemnaren etter desse loverne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Og lyden skal verja dråpsmannen for blodhemnaren, og føra honom attende til fredstaden som han hadde søkt til, og der skal han vera til øvstepresten, han som er salva med den heilage oljen, er avliden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Men kjem han utum fredstaden som han hev tydt til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'og blodhemnaren råkar honom der - utanfor fredstaden - so kann hemnaren slå honom i hel, og det skal ikkje reknast for manndråp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'for dråpsmannen lyt halda seg i fredstaden sin, til øvstepresten er avliden; då fyrst kann han fara heim att til si eigi bygd og sin eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Dette skal gjelda for lov og rett hjå dykk alle tider og alle stader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Hev nokon gjort manndråp, so skal han lata livet, so framt det er meir enn eitt vitne mot honom; etter ein manns vitnemål må ingen dømast frå livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'De må ikkje taka imot løysepengar for ein som er saka i manndråp og dømt til dauden, han skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Og de må ikkje taka imot løysepengar for ein som hev tydt til ein fredstad, og lata honom koma ut att og bu ein annan stad i landet, fyrr øvstepresten er avliden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'De skal ikkje vanhelga det landet de bur i; for blodet vanhelgar landet, og landet fær ikkje soning for blodet som hev runne der utan med blodet av den som rende det ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Difor skal du ikkje sulka det landet de bur i, og som eg hev min bustad i; for eg Herren, hev bustaden min millom Israels-folket.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Husfederne åt Gileads-folket, som var ætta frå Makir, son åt Manasse, og høyrde til Josefs-ætterne, gjekk fram og tala so til Moses og styresmennerne, ættehovdingarne åt Israels-folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, '«Herren sagde, at du skulle byta landet i luter og lata Israels-sønerne draga strå um luterne, og han sagde at du skulde lata døtterne åt Selofhad, frenden vår, få eigedomen etter far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Men vert no dei gifte med menner av dei andre Israels-ætterne, so gjeng eigedomen deira ifrå vår ætt, og jordi åt den ætti dei kjem inn i aukar, men vår ættarjord minkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Og når jubelåret kjem hjå Israels-folket, so vert eigedomen åt desse gjentorne lagd til den ætti som dei hev kome inn i, og teken ifrå vår ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Då tala Moses til Israels-sønerne, so som Herren hadde sagt honom fyre: «Det er rett som Josefs-sønerne segjer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Høyr no kva Herrens vilje er med døtterne åt Selofhad: dei kann gifta seg med kven dei vil, men det lyt vera innan fedreætti deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'For ingen eigedom må hjå Israels-folket ganga yver frå ei ætt til ei onnor. Alle Israels-sønerne skal halda på eigedomen åt fedreætti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Og kvar ei dotter som erver jord i eit av Israelsfylki, lyt gifta seg med ein frå same fylket, so kvar Israelsson kann erva odelsjordi etter federne sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'og ingen eigedom skal ganga yver frå ei ætt til ei onnor, men alle Israels-ætterne halda på eigedomen sin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Og døtterne åt Selofhad gjorde som Herren hadde sagt til Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mahla og Tirsa og Hogla og Milka og Noa, alle døtterne åt Selofhad, gifte seg med frendar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'med menner som var ætta frå Manasse, son åt Josef, gifte dei seg, so odelen deira kom til å fylgja den ætti dei høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Dette var dei bodi og loverne som Herren let Moses kunngjera for Israels-folket på Moabmoarne ved Jordanelvi der ho renn frammed Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Dette er dei ordi Moses tala til heile Israel i øydemarki austanfor Jordan, på Moarne midt for Suf, millom Paran og Tofel og Laban og Haserot og Dizahab -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'elleve dagsleider frå Horeb etter den vegen som ber burt imot Se’irfjelli, til Kades-Barnea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Det var i det fyrtiande året, fyrste dagen i den ellevte månaden, han tala til Israels-sønerne og bar fram bodi frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Då hadde han vunne yver Sihon, amoritarkongen, som budde i Hesbon, og attmed Edre’i yver Og, Basan-kongen, som budde i Astarot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Austanfor Jordan, i Moablandet, var det Moses tok til med å lesa upp desse loverne. Han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Herren vår Gud, tala soleis til oss ved Horeb: «Lenge nok hev de halde dykk innmed dette fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Tak no ut og legg vegen til Amoritarfjelli og alle dei folki som bur der attmed, på Moarne og i fjellbygderne, på sletta og i Sudlandet og på havstrandi, i heile Kana’ans-landet og på Libanon, alt burt til Storelvi, Eufratelvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Sjå, eg hev lagt landet ope for dykk. Far av stad og tak det! Det er det landet eg lova federne dykkar, Abraham og Isak og Jakob, at eg vilde gjeva deim og ætti deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Den gongen sagde eg til dykk: «Eg kann ikkje greida dykk åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Herren, dykkar Gud, hev auka dykk, so de no er mange som stjernorne på himmelen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'og gjev at han, fedreguden, vilde auka dykk endå tusund gonger og velsigna dykk, som han hev lova!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Men korleis kann eg åleine bera alt strevet og møda med dykk og trættorne dykkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Kom med nokre vise og vituge og velrøynde menner frå kvar ætt, so skal eg setja deim til hovdingar yver dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Då svara de meg: «Det er både rett og godt det du tenkjer å gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'So tok eg ættehovdingarne dykkar, vise og velrøynde menner, og sette til styrarar yver dykk - sume yver tusund, og sume yver hundrad, og sume yver femti, og sume yver ti - og gjorde deim til formenner for ætterne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Og til domarane dykkar sagde eg: «Høyr på dei sakerne folk hev med kvarandre, og døm rett millom mann og mann, anten dei båe er landsmenner eller den eine er framand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Gjer ikkje mannemun i retten! Høyr på den ringaste som på den høgste, og ver ikkje rædde nokon mann! For domen høyrer Gud til. Men dei sakerne som er for vande for dykk, lyt de koma til meg med, so skal eg høyra på deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Og same gongen sagde eg dykk fyre um alt anna de skulde gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'So tok me ut frå Horeb, og for gjenom heile den store og øgjelege villmarki som de hev set; me heldt leidi til Amoritarfjelli, soleis som Herren, vår Gud, hadde sagt oss, og kom til Kades-Barnea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Då sagde eg til dykk: «No er de komne til Amoritarfjelli, som Herren, vår Gud, vil gjeva oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Sjå, han hev lagt dette landet ope for deg! Far upp og tak det, som Herren, din fedregud, hev sagt deg! Du skal ikkje ræddast og ikkje fæla!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Då kom de til meg alle saman, og sagde: «Lat oss senda folk fyre, so dei kann gjera seg kjende i landet og gjeva oss greida på kva veg me skal fara og kva byar me kjem til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Det tykte eg var rett, og so valde eg ut tolv mann, ein or kvar ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Dei tok då av stad, og for upp i fjelli, og kom til Eskoldalen. Dei endefor landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'og tok noko av frukterne der var og hadde med seg heim til oss, og sagde frå um alt dei hadde set: «Det landet som Herren, vår Gud, vil gjeva oss, er eit godt land,» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Men de vilde ikkje fara dit; de sette dykk upp mot Herren, dykkar Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'og sat og mukka i tjeldbuderne dykkar: «Herren hatar oss,» sagde de, «difor førde han oss ut or Egyptarlandet, og no vil han gjeva oss i henderne på amoritarne, so dei skal tyna oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Gud betre oss, for eit land me skal fara upp til! Det var so hjarta kolna i oss då brørne våre kom att og sagde: «Det er folk som er større og sterkare enn me, og svære byar, med murar som rekk radt til himmels: og Anaks-sønerne såg me der og.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Då sagde eg til dykk: «De skal ikkje ottast og ikkje vera rædde deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Herren, dykkar Gud, gjeng fyre dykk; han skal strida for dykk, soleis som de såg han gjorde i Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'og i øydemarki, der du veit han bar deg, som ein mann ber barnet sitt, heile vegen de for, til de kom hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Men endå vilde de ikkje lita på Herren, dykkar Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'han som gjekk fyre dykk på ferdi, og såg etter lægerstad for dykk, um natti i ein eld, so de skulde sjå leidi, og um dagen i ei sky.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Då Herren høyrde korleis de ropa og bar dykk, vart han harm, og svor:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '«Ingen av desse mennerne, av denne vonde ætti, skal få sjå det gilde landet eg lova federne deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'ingen utan Kaleb, son åt Jefunne; han skal få sjå det; honom og borni hans vil eg gjeva det landet han var i, for di han hev heldt seg so trutt etter meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Meg og vart Herren harm på for dykkar skuld, og sagde: «Du skal ikkje heller få koma dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josva, son åt Nun, han som gjeng deg til handa, skal koma dit. Honom skal du styrkja! For han er det som skal vinna landet til odel åt Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Og borni dykkar, som de spådde skulde koma i fiendehand, småsveinerne, som endå ikkje kann skilja godt ifrå vondt, dei skal koma dit; deim vil eg gjeva landet, og dei skal få eiga det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Men de lyt venda, og taka ut i øydemarki etter den vegen, som ber til Raudehavet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Då sagde de til meg: «Me hev synda mot Herren! Men no vil me fara upp og strida, og gjera alt som Herren, vår Gud, hev sagt.» So batt de kring dykk sverdi kvar og ein; de tenkte det var ingen vande å fara upp i fjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Men Herren sagde til meg: «Seg med deim at dei ikkje skal fara dit, og ikkje gjeva seg i strid; for eg er ikkje med deim, og dei kjem til å rjuka for fienden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'So tala eg til dykk, men de vilde ikkje høyra; de lydde ikkje Herren og for i ovmod og uvyrdskap upp i fjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Og amoritarne som budde på dei fjelli, tok ut imot dykk og sette etter dykk so kvast som ein biesvarm, og dei jaga dykk ifrå einannan burtyver Se’irfjelli, radt til Horma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Då kom de attende, og klaga dykk for Herren; men Herren høyrde ikkje på dykk, og lydde ikkje på klagorne dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'og de laut vera i Kades heile den lange tidi de veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'So vende me oss åt øydemarki, og tok vegen til Raudehavet, som Herren hadde sagt med meg, og me for lenge og sveiv kringum Se’irfjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Då sagde Herren til meg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '«Lenge nok hev de reika ikring desse fjelli; tak no leidi mot nord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Og til folket skal du segja so: «No kjem de til å fara gjenom riket åt brørne dykkar, Esaus-sønerne, dom bur i Se’ir, og dei vert rædde dykk; men agta dykk vel');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'at de ikkje yppar ufred med deim; eg kann’kje lata dykk få so mykje som ei fotbreidd av landet deira; for Se’irfjelli hev eg gjeve Esau til eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Den maten de treng, lyt de kjøpa av deim, og vatnet de drikk, lyt de og gjeva pengar for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'For Herren, din Gud, hev velsigna deg i alt du hev teke deg fyre; han hev bore umsut for deg på ferdi gjenom denne store øydemarki; i alle desse fyrti åri hev Herren, din Gud, vore med deg, og du hev ingen ting vanta.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'So for me lenger frametter, burt ifrå brorfolket vårt, Esaus-sønerne, som bur i Se’ir; me tok utav den vegen som gjeng frå Eilat og Esjon-Geber gjenom Moarne, og heldt fram etter ein annan veg, som bar til Moabheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Og Herren sagde til meg: «Du skal ikkje trengja deg inn på moabitarne, og ikkje yppa ufred med deim; eg kann ikkje lata deg få noko av landet deira; for Ar hev eg gjeve Lots-sønerne til eigedom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Der budde i gamle dagar emitarne, eit stort og mannsterkt folk; dei var høgvaksne som anakitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'og vart, liksom dei, rekna til kjempefolki, men moabitarne kallar deim emitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'På Se’ir budde fyrr i tidi horitarne; men Esaus-sønerne dreiv deim burt, og øydde deim ut, og sette seg ned i staden deira, liksom Israels-folket gjorde i sitt land, det som Herren gav deim til eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '«Gjer dykk no reiduge,» sagde Herren, «og gakk yver Zeredåi!» So gjekk me yver Zeredåi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Då var det åtte og tretti år sidan me tok ut frå Kades-Barnea, og heile den ætti, alle våpnføre menner i lægret, var burtdøydde, som Herren hadde sagt med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Herrens hand hadde råma deim, og rive deim burt or lægret, so dei alle var farne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Då alle desse stridsmennerne i folket var daude og burte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'då tala Herren til meg og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '«No kjem du til å fara gjenom Moabriket, gjenom Ar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'og so ligg vegen din frammed Ammons-sønerne; men du skal ikkje trengja deg inn på deim, og ikkje yppa ufred med dei; eg kann ikkje lata deg få noko av Ammonitarlandet; for det hev eg gjeve burt til Lots-sønerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Det landet vert og rekna til kjempelandi; fyrr i verdi budde det kjempor der, og ammonitarne kalla deim zamzummitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Dei var eit stort og mannsterkt folk, og høgvaksne som anakitarne; men Herren rudde deim ut for Ammons-sønerne, so dei fekk landet og busette seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Det same gjorde han for Esaus-sønerne, som bur på Se’ir; han rudde ut horitarne, so Esaus-sønerne fekk landet, og sidan hev dei butt der til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Like eins gjekk det med avitarne, som sat på gardarne alt burt til Gaza; kaftorarane kom frå Kaftor, og øydde deim ut, og tok romet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '«Gjer dykk reiduge,» sagde Herren; «far i veg, og set yver Arnonåi! Eg gjev Sihon, amoriten, kongen i Hesbon, og landet hans i dine hender. Tak til med å slå det under deg, og gjev deg i strid med honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Etter denne dag skal det standa otte og rædsla av deg yver heile verdi; alle som høyrer gjete deg, skal bivra og skjelva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Frå Kedemotheidi sende eg menner til Sihon, kongen i Hesbon, med fredleg helsing, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '«Lat meg få fara gjenom landet ditt! Eg skal halda meg på vegen, og ikkje taka utav honom, korkje til høgre eller vinstre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Det eg lyt hava til mat, skal eg kjøpa av deg, og drikkevatnet du gjev meg, skal eg og leggja pengar for. Eg vil berre få fara igjenom på min fot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'liksom Esaus-sønerne på Se’ir og moabitarne i Ar gav meg lov til, so eg kann koma yver Jordan til det landet Herren, vår Gud, vil gjeva oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Men Sihon, kongen i Hesbon, vilde ikkje lata oss fara gjenom landet sitt. For Herren, din Gud, hadde gjort hugen hans strid og hjarta hans hardt, av di han vilde gjeva honom i dine hender, som han longe hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Og Herren sagde til meg: «No gjev eg deg magt yver Sihon og landet hans; tak no du til med å slå det under deg, so det vert ditt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'So for Sihon imot oss, til Jahas, med alt herfolket sitt, og tok på oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Men Herren, vår Gud, gav honom i vårt vald, og me hogg honom ned, både han og sønerne og alt stridsfolket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Den gongen tok me og alle byarne hans; me bannstøytte kvar byen, og drap både menner og kvinnor og born; me let ingen vera att eller sleppa undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Men bufeet eigna me til oss, og herfanget i byarne som me tok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Frå Aroer, som ligg inn med Arnon, og frå byen i dalen til Gilead fanst det ikkje ei borg som var oss for sterk; Herren lagde deim alle opne for oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Men landet åt Ammons-sønerne let du vera i fred, både det som ligg frammed Jabbokåi og fjellbygderne, alt det som Herren, vår Gud, hadde meinka oss å koma inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'So tok me på ei onnor leid, og for uppetter på vegen til Basan, og Og, kongen i Basan, kom imot oss til Edre’i med alt herfolket sitt, og baud ufred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Men Herren sagde til meg: «Du tarv ikkje vera rædd honom. Eg gjev honom i dine hender med alt folket og landet hans, og du kann gjera med honom, som du gjorde med Sihon, kongen yver amoritarne, som budde i Hesbon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'So gav Herren, vår Gud, Basan-kongen Og i våre hender, både honom og alt folket hans, og me hogg deim ned, so ingen vart att eller slapp undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Den gongen tok me alle byarne hans - det fanst ikkje ein by utan me tok honom frå deim - seksti byar, som alle høyrde til Argoblandet, riket åt Og i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Alle desse var faste borger med høge murar og tvihurda portar med slå fyre. Umfram deim tok me og alle landsbyarne, og det var uhorveleg mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Me bannstøytte deim, som me hadde gjort med Sihon, kongen i Hesbon; kvar einaste by bannstøytte me, og drap både menner og kvinnor og born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Men all buskapen og alt herfanget i byarne eigna me til oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Soleis tok me den gongen landet frå båe amoritarkongane austanfor Jordan, alt ifrå Arnonåi til Hermonfjellet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '- det er det som sidonitarne kallar Sirjon, og amoritarne Senir -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'alle byarne på høgsletta og heile Gilead og heile Basan radt til Salka og Edre’i, alle byarne i riket åt Og i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Og, kongen i Basan, var den siste som var att av kjempefolket; kista hans stend, som alle veit, i Rabba, hovudstaden åt Ammons-sønerne; ho er av jarnstein, og er ni alner lang og fire alner breid etter vanleg alnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, '«Dette landet lagde me under oss då. Bygderne nordanfor Aroer, som ligg innmed Arnonåi, og helvti av Gileadfjelli med byarne som der var, let eg rubenitarne og gaditarne få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Og det som var att av Gilead og heile Basan, riket åt Og, heile Argoblandet, gav eg til den halve Manasse-ætti.» Heile dette Basanriket rekna dei til kjempelandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Ja’ir, son åt Manasse, tok heile Argoblandet radt til bytet mot gesuritarne og ma’akatitarne; desse bygderne, Basanbygderne, gav han namn etter seg sjølv, og sidan hev folk kalla deim Ja’irsbygderne alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Gilead let eg Makir få,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'og rubenitarne og gaditarne gav eg landet frå Gilead til Arnonåi, til midt i åi, der som landskilet gjeng, og til Jabbokåi, som er landskilet mot Ammons-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'og Moarne nedunder Pisgaliderne austanfor Jordanåi - for ho er landskilet der - frå Kinneret til Moavatnet, det som dei kallar Saltsjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Den gongen var det eg sagde til dykk: «Dette landet hev Herren, dykkar Gud, gjeve dykk til eigedom. No lyt de fara fram stridsbudde fyre dei andre Israels-sønerne, so mange av dykk som er våpnføre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'og berre konorne og borni dykkar og bufeet - for eg veit de hev mykje bufe - skal vera att i byarne som eg hev gjeve dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'men når Herren hev late brørne dykkar koma til ro liksom de, og dei og hev lagt under seg det landet han gjev deim på hi sida Jordan, då kann de fara heim att til eigedomarne som eg hev gjeve dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Same gongen sagde eg til Josva: «Du såg sjølv kva Herren, dykkar Gud, gjorde med desse tvo kongarne; so vil han gjera med alle dei riki du kjem til der du fer fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'De tarv ikkje ræddast deim; for Herren, dykkar Gud, vil sjølv strida for dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Og same gongen bad eg so vænt til Herren, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '«Herre, min Gud, du hev alt synt meg so mykje av din storleik og di allmagt; for kvar finst det ein gud i himmelen eller på jordi som kann gjera slike storverk og under som du!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Å, lat meg få koma yver og sjå det gilde landet på hi sida åt Jordan, desse væne fjelli og Libanon!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Men Herren var harm på meg for dykkar skuld; han vilde ikkje høyra på meg og sagde: «No lyt det vara nok! Tala ikkje um det til meg meir!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Stig upp på Pisgahøgdi, og vend augo dine mot vest, og mot nord, og mot sud, og mot aust, og sjå vel ikring deg! For denne Jordanåi kjem du aldri yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'So skal du segja Josva fyre, og styrkja og stålsetja honom; for han skal føra dette folket yver og hjelpa deim til å vinna det landet du fær sjå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'So lagde me oss til i dalen, midt for Bet-Peor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '«So høyr no, Israel, dei loverne og bodi eg lærer dykk, og haldt dykk etter deim, so de kann få liva og koma til å eiga det landet som Herren, fedreguden dykkar, vil gjeva dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'De skal ingen ting leggja attåt det som eg segjer dykk fyre, og ingen ting taka ifrå, men lyda Herrens bod, som eg no ber fram for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'De såg sjølve kva Herren gjorde då det hende dette med Ba’al-Peor; alle deim som fylgde Ba’al-Peor, rudde Herren ut or lyden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'men de som heldt fast ved Herren, dykkar Gud, de hev alle fenge liva til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Sjå, no lærar eg dykk lover og bod, soleis som Herren, min Gud, hev sagt til meg, so de skal liva etter deim i det landet de kjem til og fær i eige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'So ber deim i hugen, og liv etter deim! Då fær de ord for visdom og klokskap hjå alle folkeslag; når dei høyrer um alle desse bodi, kjem dei til å segja: «For eit vist og vitugt folk det må vera, dette store folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'For kvar finst det eit folk, um det er aldri so stort, som hev ein gud so nær seg som Herren, vår Gud, er oss, kvar gong me kallar på honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Og kvar finst det eit folk, um det er aldri so stort, som hev so rettvise lover og bod som heile denne lovi eg legg fram for dykk i dag?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Men agta deg, so sant du hev livet ditt kjært, at du ikkje gløymer det du såg for augo dine! Lat det aldri ganga deg ut or hugen so lenge du liver, og gjer det kunnigt for borni og barneborni dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Kom i hug den dagen då du stod framfor Herren, din Gud, innmed Horeb, og Herren sagde til meg: «Kalla folket i hop! Eg vil lata deim høyra bodi mine, so dei kann læra å ottast meg all den tid dei liver på jordi, og læra borni sine det same.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Då kom dei innåt, og stod nedunder fjellet, og fjellet stod i ljos loge til langt upp i himmelen, men rundt ikring var myrker og sky og skodd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Og Herren tala til dykk midt utor elden; de høyrde ljoden av ordi, men nokon skapnad såg de ikkje; de høyrde berre ljoden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Då lyste han lovi si for dykk, og sagde de skulde halda henne, dei ti bodordi, og skreiv deim på tvo steintavlor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Og meg bad Herren same gongen å læra dykk lover og bod som de skal liva etter i det landet de er på vegen til og skal leggja under dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Tak dykk då vel i vare, so sant de hev livet kjært! for de såg ikkje nokon skapnad då Herren tala til dykk på Horeb midt utor elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Gjer ikkje so stor ei synd at de lagar dykk noko gudebilæte, noko kunstverk som likjest mann eller kvende');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'eller noko av dyri som leikar på jordi eller nokon av fuglarne som flyg uppi lufti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'eller noko av kreket som krabbar på marki eller nokon av fiskarne som sym i vatnet utfyre landjordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Og når du lyfter augo dine upp imot himmelen, og skodar soli og månen og stjernorne, heile himmelheren, tak deg då i vare at du ikkje let deg dåra, so du bed til deim og dyrkar deim, deim som Herren, din Gud, hev gjeve åt alle folk under heile himmelen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Men dykk tok Herren og førde ut or jarnomnen, or Egyptarland, so de skulde vera hans eige folk, soleis som de no er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Og Herren vart harm på meg for dykkar skuld, og svor at eg skulde ikkje sleppa yver Jordan, og ikkje koma inn i det gilde landet som han gjev deg til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Eg lyt døy i dette landet, eg slepp ikkje yver Jordan; men de skal koma yver, og få det gilde landet til eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Agta dykk då at de ikkje gløymer pakti Herren hev gjort med dykk, og lagar dykk noko gudebilæte som likjest nokon ting i verdi! for det hev Herren, din Gud, forbode deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Herren, din Gud, er ein øydande eld, ein streng Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Når du fær born og barneborn, og vert gamle i landet, og de då er so gudlause at de lagar dykk likjende av eitt eller anna og hev til gudebilæte, og soleis gjer det som Herren mislikar, og argar honom upp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'so tek eg i dag himmel og jord til vitne på at de snart skal verta utrudde or det landet de fær i eige når de kjem yver Jordan; de skal ikkje få liva der lenge, men verta heiltupp utøydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Herren skal spreida dykk millom folki; berre nokre få av dykk skal vera att i dei heidningriki han fører dykk til;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'og der lyt de tena gudar som mannehender hev laga, stokk og stein, som korkje kann sjå eller høyra eller eta eller lukta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Då skal du søkja Herren, din Gud, og du skal finna honom, so sant du søkjer honom av heile ditt hjarta og heile din hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Når du er i vande, og alt dette kjem yver deg, langt fram i tidi, då skal du venda deg til Herren att, og lyda etter ordi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'For Herren, din Gud, er ein mild Gud; han slepper deg ikkje, og let deg ikkje ganga til grunnar; han gløymer ikkje den pakti han gjorde med federne dine, og det han då lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'For spør deg berre fyre um dei framfarne dagar, som var fyre di tid, alt ifrå den dagen då Gud skapte menneskja på jordi, spør frå den eine enden av verdi til hin, um det hev hendt eller vore spurt noko so stort som dette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'um noko folk hev høyrt Guds røyst midt utor elden, soleis som du hev gjort, og endå fenge liva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'eller um nokon gud hev bode til å vilja henta seg eit folk midt ut or eit anna folk, med plågor og teikn og under og ufred, og med fast hand og strak arm og store rædslor, soleis som du såg Herren, din Gud, gjorde med dykk i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Men alt dette fekk du sjå, so du skulde vita at Herren er Gud, han og ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Frå himmelen let han deg høyra røysti si, av di han vilde rettleida deg, og på jordi synte han deg den store elden sin, og midt utor elden høyrde du ordi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Han hadde lagt hug til federne dine, og kåra ut ætti deira; difor henta han deg sjølv ut or Egyptarland med si store magt');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'og vil for di skuld driva ut folk som er større og sterkare enn du, so han kann føra deg inn i landet deira, og lata deg få det til odel og eige, soleis som du no ser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'So legg deg då i dag på hjarta og minne at Herren er Gud både uppi himmelen og nedpå jordi; det finst ingen annan Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'og haldt loverne og bodi hans, som eg lærer deg no; då skal det ganga deg vel, og borni dine og, og du skal få liva lenge i det landet som Herren, din Gud, gjev deg til æveleg eiga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Den gongen skilde Moses ut tri byar austanfor Jordan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'so ein fredlaus kunde røma dit, når han uviljande hadde drepe nokon, og ikkje bar hat til honom frå fyrr; rømde han til ein av desse byarne, skulde han vera trygg for livet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Det var Beser i øydemarki, på høgsletta, for rubenitarne, og Ramot i Gilead for gaditarne, og Golan i Basan for manassitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Her er då den lovi som Moses lagde fram for Israels-sønerne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'dette er dei bodi og fyresegnerne og rettarne han lyste for deim på ferdi frå Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'austanfor Jordan, i dalen midt for Bet-Peor, i det landet som Sihon, amoritarkongen, hadde ått, han som budde i Hesbon, og som Moses og Israels-sønerne vann yver då dei kom frå Egyptarland;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'då tok dei både hans land og landet åt Og, kongen i Basan, landet åt båe amoritarkongarne som budde austanfor Jordan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'frå Aroer, som ligg innmed Arnonåi, til Sionsfjellet, det som dei kallar Hermon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'og heile Moalandet austanfor Jordan alt til Moavatnet, nedunder Pisgaliderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Og Moses kalla i hop heile Israel og sagde til deim: «Høyr, Israel, dei loverne og bodi som eg lyser for dykk i dag, og lær deim, og ber deim i hugen, so de liver etter deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Herren, vår Gud, gjorde ei pakt med oss på Horeb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ikkje med federne våre gjorde han den pakti, men med oss, alle me her som liver i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Åsyn mot åsyn tala Herren med dykk på fjellet midt utor elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Eg stod millom Herren og dykk den gongen, og bar ordi hans fram for dykk; for de var rædde elden, og våga dykk ikkje upp på fjellet. Han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '«Eg er Herren, din Gud, som førde deg ut or Egyptarlandet, or slavehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du skal ikkje hava nokon annan gud attåt meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du skal ikkje gjera deg noko gudebilæte, nokor likning av det som er uppi himmelen eller det som er nedpå jordi eller det som er i vatnet nedanfor landjordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du skal ikkje bøygja kne for deim, og ikkje beda til deim! For eg, Herren, din Gud, er ein streng Gud; eg hemner broti åt federne på borni og barneborni og barnebarns-borni av deim som hatar meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'men imot deim som elskar meg og held bodi mine, gjer eg vel i tusund ættleder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Namnet åt Herren, din Gud, skal du ikkje taka vyrdlaust på tunga! For Herren held ikkje den uskuldig som nemnar namnet hans vyrdlaust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Du skal koma i hug kviledagen, og halda honom heilag, soleis som Herren, din Gud, hev sagt med deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Seks dagar må du arbeida og gjera alt det du skal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Men den sjuande dagen skal vera kviledag og vigd åt Herren, din Gud. Då skal du ikkje gjera noko arbeid, korkje du eller son din eller dotter di, eller drengen din eller tenestgjenta, eller uksen eller asnet eller noko anna av dyri dine, eller den framande som held til innan portarne dine! For tenarane dine lyt kvila dei som du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Kom i hug at du sjølv var tenar i Egyptarlandet, og Herren, din Gud, henta deg ut derifrå med sterk hand og strak arm; difor hev han sagt deg at du skal halda kviledagen heilag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Du skal æra far din og mor di, som Herren, din Gud, hev sagt med deg; då skal du få liva lenge og vel i det landet som Herren, din Gud, gjev deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du skal ikkje drepa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Og du skal ikkje gjera hor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Og du skal ikkje stela!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Og du skal ikkje vitna rangt imot grannen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Og du skal ikkje trå etter kona åt grannen din! Og du skal ikkje trå etter huset åt grannen din, eller garden hans, eller drengen eller tenestgjenta hans, eller uksen eller asnet hans eller noko anna som høyrer grannen din til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Desse ordi tala Herren på fjellet med høg røyst til heile lyden dykkar, midt utor elden og skyi og myrkret, og meir sagde han ikkje; og han skreiv dei på tvo steintavlor, og gav deim til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Men då de høyrde røysti midt utor myrkret, og såg fjellet stod i ljos loge, då kom de til meg, alle ættehovdingarne og styresmennerne dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'og sagde: «No hev Herren, vår Gud, synt oss sin herlegdom og sitt velde, og me hev høyrt røysti hans midt utor elden; i dag hev me set at ein mann kann liva um Gud hev tala med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Og so lyt me døy like vel! For denne svære elden kjem til å tyna oss. Høyrer me no lenger på røysti åt Herren, vår Gud, so døyr me.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'For kven finst det på jordi som hev høyrt den livande Gud tala midt utor elden, som me, og endå fenge liva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Gakk du innåt, og høyr kva Herren, vår Gud, segjer! So kann du segja med oss alt det han talar til deg, og me skal høyra og lyda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Då Herren høyrde kva de tala med meg um, sagde han til meg: «Eg høyrde kva folket sagde med deg; det er rett alt det dei hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Gjev dei all tid måtte hava den same hugen til å ottast meg og halda alle bodi mine, so det kann ganga deim og borni deira vel i all æva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Gakk burt til deim og seg at dei kann ganga heim att til buderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Men du lyt vera att her hjå meg, so eg kann segja deg alle bodi og loverne og rettarne som du skal læra deim, og som dei skal liva etter i det landet eg gjev deim til eiga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'So kom då i hug å gjera som Herren, dykkar Gud, hev sagt dykk! Tak ikkje or leidi, korkje til høgre eller vinstre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Fylg allstødt den vegen som Herren hev synt dykk! Då skal de trivast og liva både vel og lenge i det landet de fær til eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Dette er dei bodi og loverne og rettarne som Herren, dykkar Gud, sagde eg skulde læra dykk, og som han vil de skal liva etter i det landet de er på vegen til og skal leggja under dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Ottast du Herren, din Gud, og held du heile ditt liv alle bodi og loverne hans, som eg ber fram for deg no, du og son din og soneson din, då skal dagarne dine verta mange på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'So høyr då bodi hans, Israel, og ber deim i hugen, og liv etter deim! Då skal det ganga deg vel, og de skal aukast og trivast i eit land som fløymer med mjølk og honning, soleis som Herren, din fedregud, hev sagt med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Høyr, Israel! Herren er vår Gud, Herren åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Du skal elska Herren, din Gud, av alt ditt hjarta og av all din hug og av all di magt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Og desse ordi som eg lærer deg no, skal du gøyma i hjarta;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'og du skal prenta deim inn i borni dine, og tala um deim når du sit heime, og når du gjeng etter vegen, og når du legg deg, og når du ris upp att;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'og du skal binda deim på handi di til eit merke, og bera deim som eit hovudband yver augo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'og skriva deim på dørskierne i huset ditt og på portarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'No fører Herren din Gud deg inn i det landet som han lova federne dine, Abraham og Isak og Jakob, at han vilde gjeva deg, til store og væne byar som du ikkje hev bygt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'og fulle hus, som du ikkje hev fyllt, til gravne brunnar, som du ikkje hev grave, og hagar med vin- og oljetre, som du ikkje hev sett. Når du då nyt godt av alt dette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'so agta deg at du ikkje gløymer Herren, som henta deg ut or Egyptarlandet, or slavehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Herren, din Gud, skal du ottast, og honom skal du tena, og ved hans namn skal du sverja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Far ikkje etter andre gudar, som folki rundt ikring dykkar fer etter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'For Herren, din Gud, som er midt imillom dykk, han er ein streng Gud; han kunde harmast på dykk, so han rudde dykk ut or verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'De må ikkje freista Herren, dykkar Gud, soleis som de gjorde i Massa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Trutt skal de fylgja dei bodi og loverne og fyresegnerne som Herren, din Gud, hev gjeve deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'og gjera det som er godt og rett i hans augo. Då skal det ganga deg vel; du skal få eiga det gilde landet som Herren lova federne dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'og han skal driva ut alle fiendar for deg, soleis som han hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Når son din sidan spør deg: «Korleis er det med desse loverne og fyresegnerne og bodi som Herren, vår Gud, hev gjeve dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'då skal du segja med honom: «Me var trælar hjå Farao i Egyptarland; men Herren førde oss med fast hand ut or Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Og Herren let store og øgjelege teikn og under henda i Egyptarland, med Farao og heile folket hans, midt for augo våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Men oss førde han burt; han vilde fylgja oss til det landet han hadde lova federne våre, og gjeva oss det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Då sette han oss fyre å halda alle desse bodi, og ottast Herren, vår Gud, so det skulde ganga oss vel alle dagar, og han kunde lata oss liva, som han til dessa hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Og det skal reknast oss til rettferd at me held alle desse bodi og liver etter deim for Herrens augo, soleis som han hev sagt oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Sjå no fører Herren deg inn i det landet du etlar deg til, og vil for di skuld driva ut store folkeslag: hetitarne og girgasitarne og amoritarne og kananitarne og perizitarne og hevitarne og jebusitarne, sju folk som er større og sterkare enn du;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'men når han hev gjeve deim i di magt, og du hev vunne yver deim, då skal du bannstøyta deim; du må ikkje gjera nokor semja med deim, og ikkje gjeva deim grid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'du må ikkje hava nokor hopegifting med deim; ikkje må du gjeva døtterne dine til sønerne deira, og ikkje taka døtterne deira til konor åt sønerne dine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'for dei kunde få sønerne dine til å falla frå Herren og tena andre gudar, og då kom Herren til å harmast på dykk, og rydja dykk ut, og det fort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Høyr no korleis de skal fara med desse folki: Altari deira skal de riva ned, og minnesteinarne skal de slå sund; dei heilage trei deira skal de fella, og avgudsbilæti skal de brenna upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'For du er eit heilagt folk, vigt åt Herren, din Gud; deg valde han ut millom alle folkeslag på jordi, og vilde du skulde vera hans eige folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ikkje av di du var større enn alle dei andre folki, tok Herren deg åt seg og kåra deg ut; for du er det minste av alle folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Men han elska deg, og vilde halda det han hadde lova federne dine; difor førde han deg burt med fast hand og fria deg ut or slavehuset, or henderne på Farao, egyptarkongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'So må du då vita at Herren, din Gud, han er den rette Gud, den trufaste Gud, som held det han lovar. Mot deim som elskar honom og held bodi hans, gjer han vel i tusunde leden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'og deim som hatar honom, gjev han løni på loven, og let deim ganga til grunnar; han held ikkje att løni for deim, men greider henne midt upp i handi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'So kom då i hug dei bodi og fyresegnerne og loverne som eg ber fram for deg i dag, og liv etter deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Lyder du no etter desse bodi, og kjem deim i hug, og held deim, so skal Herren, din Gud, koma i hug den truskap og nåde han lova federne dine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'han skal elska deg, og velsigna deg, og auka ætti di; han skal velsigna både det du avlar og det du el: kornet og druvesafti og oljen, det som fell undan storfeet og det som kjem til i småfenadflokken, på den jordi han lova federne dine å gjeva deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Velsigna skal du vera framum alle folkeslag. Hjå deg skal det aldri finnast eit liv, korkje av folk eller fe, som vantar avkjøme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'All sjukdom skal Herren halda burte frå deg, og alle dei vonde sotterne du kjenner frå Egyptarland, deim skal han ikkje leggja på deg, men på dine fiendar skal han leggja deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Alle dei folki Herren, din Gud, gjev deg magt yver, skal du tyna, og ikkje kvida deg for å drepa deim. Og aldri må du tena gudarne deira; for det vert ulukka di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Men um du tenkjer som so: «Desse folki er sterkare enn eg! korleis kann eg driva deim ut?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'so ver ikkje rædd deim for det! Kom i hug kva Herren, din Gud, gjorde med Farao og alle egyptarane,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'dei store plågorne du såg for augo dine, og teikni og underi som hende då Herren med fast hand og strak arm henta deg ut or Egyptarlandet; det same skal Herren, din Gud, gjera med alle dei folki du ræddast for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Endå kvefsen skal han senda imot dei, til alle dei er burte som var att og hadde løynt seg for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Du skal ikkje fæla deg for deim; for Herren, din Gud, er med deg, ein stor og ageleg Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Smått um senn skal Herren driva desse folki ut for deg; du skal ikkje få øyda deim ut med ein gong; for då kom villdyri til å auka for mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Herren, din Gud, skal gjeva deg magt yver deim; han skal fjetra deim, so dei ikkje veit anten att eller fram, og vert nedhogne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Kongarne deira og skal han gjeva i ditt vald, og du skal rydja ut namni deira or verdi. Ingen skal kunna standa seg mot deg; du skal øyda deim ut for ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Gudebilæti deira skal du kasta på elden, og ikkje bry deg um sylvet og gullet på deim, eller eigna det til deg; det vilde føra deg i ulukka; for det er ein styggedom for Herren, din Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'og slik styggedom skal du ikkje hava inn i huset ditt, so du vert forbanna liksom det; du skal styggjast ved det og sky det; for det er bannstøytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Alle dei bodi eg legg fyre dykk i dag, skal de bera i hugen og liva etter deim; då skal de trivast og aukast og koma til å eiga landet Herren hev lova federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Kom i hug den lange leidi Herren, din Gud, let deg fara i øydemarki i desse fyrti åri! Han vilde gjera deg mjuk og røyna deg og sjå kva som budde i hjarta ditt, um du vilde halda bodi hans eller ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Difor let han deg svelta og lida vondt, og so metta han deg atter med manna, som du ikkje kjende til, og federne dine ikkje heller, so du skulde vita at menneskja liver ikkje berre av brød, men at kvart ord som kjem frå Guds munn, gjev menneskja liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Klædi dine vart ikkje utslitne, og foten din trutna ikkje i desse fyrti åri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'So må du då skyna at Herren, din Gud, vilde tukta og rettleida deg, liksom ein far når han tuktar upp son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Haldt då bodi åt Herren, din Gud! Gakk på hans vegar, og hav age for honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'For Herren, din Gud, fører deg inn i eit godt land, eit land med bekkjer og løkjer og kjeldor, som kjem fram i dal og på fjell,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'eit land med kveite og bygg, med vintre og fiketre og aplar, med oljetre og honning;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'der tarv du ikkje eta brødet ditt i armod; der skal du ingen ting vanta; der er steinarne av jarn, og or fjelli kann du brjota ut kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Når du so nyt godt av alt dette, takka då Herren, din Gud, for det gilde landet han gav deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Agta deg at du ikkje gløymer Herren, din Gud, og bodi og fyresegnerne og loverne hans, som eg legg fyre deg no!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Når du hev nøgdi av mat, og byggjer deg væne hus til å bu i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'og buskapen din økslar seg, både stort og smått, og sylv- og gullhaugen veks, og all din eigedom aukar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'lat ikkje då ovmod få rom i hjarta ditt, so du gløymer Herren, din Gud, han som henta deg ut or Egyptarlandet, or slavehuset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'han som førde deg gjenom den store, øgjelege øydemarki, millom eiterormar og skorpionar og yver vatslaust turrlende, han som let vatnet strøyma ut åt deg or harde berget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'han som i øydemarki fødde deg med manna, som federne dine aldri hadde høyrt gjete; og alt dette gjorde han av di han vilde mykja deg og røyna deg, og so sidan gjera vel imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Seg ikkje med deg sjølv: «Det er mi eigi kraft og mi sterke hand som hev vunne meg denne rikdomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Kom i hug at det var Herren, din Gud, som gav deg kraft til å vinna rikdom, av di han vil halda det han lova federne dine, soleis som han til dessa hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Men gløymer du Herren, og held deg til andre gudar, og tener deim, og bøygjer kne for deim, so er det ute med dykk, det segjer eg dykk for visst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Liksom dei folki Herren no gjer ende på for dykkar skuld, soleis skal de og ganga til grunnar, for di de ikkje lyder Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Høyr, Israel! No gjeng du yver Jordan, og skal leggja under deg folkeslag som er større og sterkare enn du, svære byar med murar som når radt til himmels,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'eit stort kjempefolk, Anaks-sønerne, som du kjenner, og som du hev høyrt det ordet um: «Kven kann standa seg mot Anaks-sønerne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'So kom då i hug at Herren, din Gud, gjeng fyre deg som ein øydande eld; han skal tyna deim, og han skal slå deim ned for deg, so du snart fær drive deim burt og rudt deim ut, soleis som Herren hev sagt deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Men når han støyter deim ned framfyre deg, må du ikkje tenkja som so: «For di eg er god og rettvis, hev Herren ført meg hit og gjeve meg dette landet.» Nei, Herren driv desse folki ut for di dei er gudlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Det er ikkje for di du er god og rettvis, eller for di du er truverdug og ærleg, at du skal koma dit og få landet deira, men for di dei er gudlause, driv Herren deim ut, og av di han vil halda det ordet han gav federne dine, Abraham og Isak og Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'So skal du då vita at det ikkje er for di rettferd skuld Herren, din Gud, gjev deg dette gilde landet til eiga; for du er eit hardkyndt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Kom i hug og gløym ikkje korleis du arga upp Herren, din Gud, i øydemarki! Alt ifrå den dagen de for frå Egyptarlandet og til de kom hit, hev de sett dykk upp imot Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Attmed Horeb arga de og Herren, so han vart harm på dykk og vilde rydja dykk ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Det var den gongen eg gjekk upp på fjellet og skulde taka imot steintavlorne, deim som Herrens pakt med dykk var skrivi på; då var eg på fjellet i fyrti jamdøgar, og gjorde korkje åt eller drakk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Og Herren gav meg dei tvo steintavlorne; dei hadde han sjølv skrive på med fingeren sin, og der stod alle dei ordi som han tala til dykk på fjellet, midt utor elden, samkomedagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Då dei fyrti jamdøgri var lidne, gav Herren meg dei tvo steintavlorne, sambandstavlorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'og sagde til meg: «Skunda deg ned att; for folket ditt, som du fylgde ut or Egyptarland, hev bore seg stygt åt; det var’kje lenge fyrr dei tok utav den leidi eg synte deim; dei hev støypt seg eit gudebilæte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Eg hev halde auga med dette folket,» sagde Herren, «og set at det er eit hardkyndt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Lat no meg råda, so vil eg gjera ende på deim, og rydja namnet deira ut or verdi, og so vil eg gjera deg til eit folk som er større og sterkare enn dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'So snudde eg meg, og gjekk ned av fjellet, og fjellet stod i ljos loge; og dei tvo sambandstavlorne bar eg i henderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Då fekk eg sjå at de hadde synda mot Herren, dykkar Gud, og støypt dykk ein gullkalv; de hadde alt teke utav den leidi Herren synte dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'So tok eg og kasta båe tavlorne or henderne, og slo deim sund for augo dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Og sidan låg eg på kne for Herren, liksom fyrre gongen, i fyrti dagar og fyrti næter, og smaka korkje mat eller drikka, for di de hadde ført so stor ei synd yver dykk, og gjort det som Herren mislika, so han vart harm;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'for eg ottast Herren var vorten so vill og vond på dykk at han vilde rydja dykk ut. Og Herren høyrde bøni mi den gongen og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Aron og var Herren fælande harm på, og vilde tyna honom; og eg laut beda for Aron og den gongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Men syndeverket dykkar, kalven, tok eg og kasta på elden, og kruste honom, og mulde honom sund, so han vart til dust, og dusti kasta eg i bekken som renn ned frå fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'I Tabera og Massa og Kibrot-Hatta’ava harma de og Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Og då han vilde de skulde taka ut frå Kades-Barnea, og sagde: «Far upp og tak det landet som eg hev gjeve dykk!» då var de ulyduge mot Herren, dykkar Gud, og leit ikkje på honom, og høyrde ikkje på det han sagde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'ulyduge mot Herren hev de vore so lenge eg hev kjent dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'So låg eg då på kne for Herren alle dei fyrti dagarne og næterne som de veit; for Herren hadde sagt at han vilde tyna dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Og eg bad til Herren og sagde: «Herre, min Gud, gjer ikkje ende på ditt eige folk, som du hev fria ut med di allmagt, og leidt ut or Egyptarland med di sterke hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Kom i hug tenarane dine, Abraham og Isak og Jakob, og tenk ikkje på kor hardt og gudlaust og syndugt det er, dette folket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Elles kunne dei segja so som i det landet du hev ført oss utor: «Herren var ikkje god til å fylgja deim fram til det landet han hadde lova deim, og han hata deim og; difor førde han deim ut i øydemarki, og let deim døy der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Dei er då din eigen lyd, som du hev leidt ut med di store magt og din sterke arm.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Då var det Herren sagde til meg: «Hogg til tvo steintavlor like eins som dei fyrste, og gjer deg ei trekista, og kom upp på fjellet til meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'so skal eg skriva dei same ordi på dei tavlorne som på dei fyrste, dei du slo sund, og du skal leggja deim ned i kista.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Då gjorde eg ei kista av akazietre, og hogg til tvo steintavlor like eins som dei fyrste, og gjekk upp på fjellet med båe tavlorne i handi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'og Herren skreiv på deim det same som han hadde skrive fyrre gongen: dei ti bodordi som han hadde tala til dykk på fjellet midt utor elden, samkomedagen, og han gav deim til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'So snudde eg meg, og gjekk ned av fjellet, og lagde tavlorne i den kista eg hadde gjort, og der vart dei liggjande, soleis som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Sidan tok Israels-sønerne ut frå Bene-Ja’akan-brunnarne, og kom til Mosera; der døydde Aron, og der vart han gravlagd, og Eleazar, son hans, vart prest etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Derifrå for dei til Gudgoda, og frå Gudgoda til Jotbata, eit land med mange bekkjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'I den tidi skilde Herren ut Levi-ætti so dei skulde bera sambandskista åt Herren, og standa framfor Herrens andlit og tena honom, og lysa velsigning i hans namn, og so hev dei gjort til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Difor fekk ikkje Levi nokon arvlut tilliks med brørne sine; Herren skal vera hans arv, soleis som han sjølv hev sagt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, '«So var eg då på fjellet i fyrti jamdøger, liksom fyrre venda, og Herren høyrde bøni mi den gongen og; han vilde ikkje tyna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'So sagde Herren til meg: «Tak i vegen, og før folket lenger fram, so dei kann koma til det landet eg hev lova federne deira å gjeva deim!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Og no, Israel, kva er det Herren, din Gud, krev av deg, anna enn det at du skal ottast Herren, din Gud, og allstødt ganga på hans vegar, og elska og tena honom av heile ditt hjarta og heile din hug,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'og halda bodi og loverne hans, som eg ber fram for deg no, so det kann ganga deg vel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Sjå, himmelen og alle himlar i himmelen, jordi og alt det som på henne er, høyrer Herren, din Gud, til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Men endå var det berre federne dine han lagde hug til og elska, og sidan kåra han ut dykk, ætti deira, framum alle andre folkeslag, soleis som me ser det i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'So bøyg då den stride hugen dykkar, og ver ikkje lenger so hardnakka!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'For Herren, dykkar Gud, han er Gud yver alle gudar og Herre yver alle herrar, den store, velduge, agelege Gud! Han gjer ikkje mannemun, og tek ikkje mutor;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'han hjelper den farlause og enkja til retten sin, og syter for dei framande so dei fær mat og klæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Difor skal de og vera gode med dei framande; de var sjølve framande i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Herren, din Gud, skal du ottast; honom skal du tena, og honom skal du halda deg til, og ved hans namn skal du sverja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Han skal vera det gildaste du veit; han er din Gud som for di skuld hev gjort alt dette store og agelege som du hev set for augo dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Sytti i talet for federne dine ned til Egyptarland, men no hev Herren, din Gud, auka dykk so de er mange som stjernorne på himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'So elska då Herren, din Gud, og haldt det han vil du skal halda, loverne og rettarne og bodi hans, alle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Kom i hug at det er dykk eg talar til no, og ikkje borni dykkar; for dei kjenner ikkje til og hev ikkje set Herrens rettleiding og tukt, hans store velde, hans sterke hand og strake arm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'dei under og storverk han gjorde i Egyptarland med Farao, egyptarkongen, og heile landet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'og det han gjorde med egyptarheren, med hestarne og vognerne deira, då han let Sevhavs-bylgjorne strøyma i hop yver deim, medan dei sette etter dykk, og gjorde ende på deim, so ingen hev set deim meir,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'og det han gjorde for dykk i øydemarki alt til de kom hit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'og det han gjorde med Datan og Abiram, sønerne åt Eliab, son åt Ruben, då jordi let upp gapet sitt midt i Israels-lægret, og gløypte deim og huslydarne og buderne deira og kvart liv som var med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'De sjølve er det som med eigne augo hev set alle dei storverki Herren hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'So haldt då alle dei bodi eg lærer dykk no, so de kann verta sterke, og eigna til dykk det landet de er på vegen til og skal leggja under dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'og so de kann få liva lenge i det landet Herren lova federne dykkar at han vilde gjeva deim og ætti deira, eit land som fløymer med mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'For det landet du er på vegen til og skal eigna til deg, er ikkje likt Egyptarlandet, som du kjem ifrå. Det laut du vatna som ein kålhage, kvar gong du hadde sått;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'men det landet du no fer yver til og skal taka i eige, det er eit land med fjell og dalar: av himmelregnet drikk det seg utyrst;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'det er eit land som Herren ber umsut for; allstødt vaktar augo hans på det, frå årsens fyrste dag til den siste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, '«Lyder du no dei bodi eg gjev dykk i dag,» segjer Herren, «elskar og tener du Herren, din Gud, av heile ditt hjarta og heile din hug,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'so skal gjeva landet ditt regn i rette tid, både haust og vår, og du skal samla i hus korn og olje og vin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'og gras skal eg lata veksa på marki for buskapen din, og du skal få nøgdi av alt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Men agta deg at ditt hjarta ikkje vert dåra, so du fell ifrå, og tener framande gudar, og legg deg på kne for deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'for då vert Herren din harm, og stengjer himmelen att, so det ikkje kjem noko regn, og jordi ikkje gjev grøda, og vonom snøggare kverv du burt or det ovgilde landet som Herren gjev deg til eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'So legg dykk då desse ordi mine på hjarta og minne! Bind deim på handi til merke, og ber deim som hovudband yver augo!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Lær deim til borni dine, og tala um deim når du sit heime, og når du gjeng etter vegen, og når du legg deg, og når du ris upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Skriv deim på dørskierne i huset og på dine portar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'so du og borni dine kann festa bu i det landet som Herren sjølv hev lova å gjeva federne dine, og liva der likso lenge som soli skin yver jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'For agtar du vel på alle dei bodi eg gjev deg, og liver etter deim, elskar du Herren, din Gud, og allstødt gjeng på hans vegar og held deg til honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'so skal han driva alle desse folki or landet; folk som er større og sterkare enn du er sjølv, skal du jaga;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'kvar flekken du set foten på, skal høyra deg til; frå Øydemarki og Libanon, frå Eufratelvi til Vesterhavet skal riket ditt nå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ingen skal kunna standa seg imot deg; otte for deg og rædsla skal koma yver kvart land du stig på med foten din, soleis som Herren hev sagt deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Sjå i dag legg eg fram for deg velsigning og våbøn:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'velsigning, so sant du lyder bodi åt Herren, din Gud, deim som eg kjem til deg med no,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'og våbøn, so framt du ikkje lyder bodi åt Herren, din Gud, men tek utav den leidi eg segjer deg fyre, og held deg til andre gudar, som du ikkje veit noko um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Når då Herren fører deg inn i det landet du skal taka i eige, so skal du lysa velsigningi på Garizim og våbøni på Ebal;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'det er dei fjelli du veit, som ligg på hi sida Jordan, burtanfor vestervegen, i det landet som kananitarne eig, dei som bur på Moarne midt for Gilgal, tett innmed Spåmannseikerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'For no gjeng du yver Jordan, og skal taka imot det landet som Herren, din Gud, gjev deg; når du so hev eigna det til deg, og bur i det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'sjå då til at du held alle dei loverne og bodi eg legg fyre deg i dag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Dette er dei loverne og bodi de skal halda dykk etter i det landet som Herren, fedreguden dykkar, hev gjeve dykk; lat deim aldri ganga dykk or minne so lenge de liver på jordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Der som dei folki de tek landet frå, hev dyrka gudarne sine, der skal de gjera det audt, på dei høge fjell og på haugar og under sigrøne tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'De skal riva ned altari deira, og slå sund minnesteinarne; dei heilage trei deira skal de brenna, og hogga sund gudebilæti, og rydja ut namni deira der dei hev vore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Når de dyrkar Herren, dykkar Gud, skal de ikkje fara åt som dei folki gjorde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'de skal søkja til den staden som Herren, dykkar Gud, vel seg til bustad i eit av fylki dykkar; dit skal du koma,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'og dit skal de føra brennofferi og slagtofferi dykkar, og tiendi og reidorne dykkar, og gåvorne dykkar, både deim de hev lova, og deim de gjev i godvilje, og frumsungarne av storfeet og småfeet dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Og der skal de halda måltid for Herrens åsyn, de og huslydarne dykkar, og gleda dykk i alt det de hev vunne med arbeidet dykkar, og som Herren, dykkar Gud, hev velsigna dykk med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'De må ikkje gjera so som me gjer her i dag - for no gjer kvar det han sjølv held for rett -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'av di de endå ikkje er komne til den heimen og den odelseigni som Herren vil gjeva dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Men når de hev gjenge yver Jordan, og sett dykk ned i det landet som Herren, dykkar Gud, gjev dykk til odel og eiga, og han hev gjeve dykk ro for alle fiendar rundt ikring, so de bur trygt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'då vil han kåra seg ein bustad millom dykk, og dit skal det koma med alt det eg segjer dykk fyre: brennofferi og slagtofferi dykkar, tiendi og reidorne og alle dei valde gåvorne som de hev lova Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Og de skal gleda dykk for Herrens åsyn, de og sønerne og døtterne dykkar, og drengjerne og tenestgjentorne, og levitarne som bur hjå dykk; for dei hev ikkje fenge nokon arvlut tilliks med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Agta deg at du ikkje ber fram brennofferi dine kvar du kjem på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'På den staden som Herren vel seg ut i eit av fylki dykkar, der skal du ofra brennofferi dine, og der skal du gjera alt anna eg segjer deg fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Men elles kann de slagta, og eta kjøt so mykje du hev hug til, i alle heimarne dykkar, etter som Herren, dykkar Gud, gjev dykk råd til. Både ureine og reine kann eta det, liksom det var gasella eller hjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'so nær som blodet; det må de ikkje eta; de skal slå det ut på marki liksom vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Tiendi av kornet ditt og av vinen og oljen, og frumsungarne av storfeet og småfeet ditt, og loveofferi som du hev vigt, og gåvorne som du gjev i godvilje, og reidorne som du ber fram, det må du ikkje eta heime i di eigi bygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'For Herrens åsyn, på den staden han vel seg ut, skal du eta det, du og son sin og dotter di, og drengen og tenestgjenta, og leviten som bur innan portarne dine, og du skal gleda deg for Herrens åsyn i alt det du hev vunne med arbeidet ditt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'men agta deg at du aldri gløymer leviten so lenge du liver i landet ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Når Herren, din Gud, aukar riket ditt, soleis som han hev lova deg, og du tenkjer som so: «No vil eg eta kjøt,» av di du hev hug på kjøt, so kann du eta kjøt so mykje du vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Hev du lang veg til den staden som Herren, din Gud, hev valt seg til bustad, so må du gjera som eg hev sagt, og slagta noko av storfeet og småfeet som Herren hev gjeve deg, og eta det i bygdi di, so mykje som du hev hug til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Men du må eta det liksom det var gasella eller hjort; både ureine og reine kann eta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Men kom i hug at du ikkje et blodet! For i blodet er livet, og du må ikkje eta livet saman med kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Du må ikkje eta blodet; du skal slå det ut på marki liksom vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Et det ikkje, so skal det ganga deg vel, og borni dine og, for di du gjer det som er rett i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Men vigslegåvorne som du vil gjeva og loveofferi, skal du taka og føra til den staden som Herren hev valt seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Brennofferi dine skal du ofra på Herrens altar, både kjøtet og blodet; av slagtofferi skal blodet hellast ut på altaret; men kjøtet kann du eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Lyd då etter alle desse ordi som eg segjer deg no, og ber deim i hugen, so det kann ganga deg og borni dine vel i all æva, for di du gjer det som er godt og rett i augo åt Herren, din Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Når Herren, din Gud, hev rudt ut for deg dei folki du no fer imot og vil driva burt, og når du hev jaga deim ut og sett deg ned i landet deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'agta deg då at du ikkje vert dåra og fylgjer i fotfaret deira, etter dei hev vorte utøydde for augo dine! Du skal ikkje spyrja etter gudarne deira og segja: «Korleis tente desse folki gudarne sine? Eg vil gjera som dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Far aldri åt som dei gjer, når du dyrkar Herren, din Gud; for alt det som Herren mislikar, og som er ein styggedom hans augo, det gjer dei for gudarne sine; jamvel sønerne og døtterne sine brenner dei til æra for desse gudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Alt det eg segjer dykk fyre, skal de gøyma i hjarta, og liva etter det; de må ingen ting leggja attåt, og ingen ting taka ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Når det stig fram ein profet millom dykk, eller ein som hev draumsyner, og han spår dykk eit teikn eller under,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, '[2-3] og segjer: «Lat oss fylgja andre gudar» - gudar som du ikkje kjenner - «og beda til deim!» so lyd ikkje etter kva slik ein profet eller draumsjåar segjer, um det so horver etter som han spådde; for Herren vil då røyna dykk og sjå um de elskar honom av heile dykkar hjarta og heile dykkar hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, '[-]');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Herren, dykkar Gud, skal de fylgja, og honom skal de ottast; hans bod skal de lyda, og hans ord skal de høyra; honom skal de tena, og honom skal de halda dykk til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Og denne profeten eller draumsjåaren skal lata livet, for di han talde dykk til å falla frå Herren, dykkar Gud, som førde dykk ut or Egyptarlandet, og fria dykk ut or slavehuset, og for di han vilde lokka deg burt frå den vegen som Herren, din Gud, hev sagt du skal ganga. Soleis skal de rydja det vonde ut or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Um bror din, son åt di eigi mor, eller son din, eller dotter di, eller kona di, som du held i fanget, eller venen din, som du hev so kjær som ditt eige liv - um nokon av desse lokkar deg i løynd, og vil få deg til å dyrka ein annan gud, som du ikkje kjenner, og federne dine aldri hev kjent,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'ein av gudarne åt dei folki som bur rundt ikring dykk, tett innmed eller langt undan, frå den eine enden av jordi til hin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'so skal du ikkje fara etter honom, og ikkje høyra på honom; du skal ikkje tykkja synd i honom, og ikkje spara honom, og ikkje dylja brotet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'men du skal drepa honom; sjølv skal du vera den fyrste som lyfter handi mot honom, og sidan skal heile folket gjera det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Du skal steina honom i hel, for di han freista å lokka deg burt frå Herren, din Gud, som førde deg utor Egyptarlandet, or slavehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Og heile Israel skal høyra det og ræddast, so det aldri meir vert gjort so stygg ei synd millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, '[12-13] Høyrer du gjete gudlause menner som hev stige fram millom dykk, i nokon av dei byarne som Herren, din Gud, gjev deg til å bu i, og fenge folket i byen til å dyrka andre gudar, som de ikkje kjenner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, '[-]');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'so skal du lyda etter, og spyrja deg vel fyre, og granska saki vel, og syner det seg då å vera sant, er det visst og vitnefast at det hev vore gjort slikt skjemdarverk hjå dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'so skal du bannstøyta den byen og alt som i honom er, og hogga ned både folk og fe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Alt herfanget du tek der, skal du samla i hop midt på torget, og brenna upp både det og byen til eit heiloffer åt Herren, din Gud, og sidan skal byen i all æva vera ein grushaug, og må aldri byggjast upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Du må ikkje halda att noko av det som er bannstøytt; då skal Herren stagga sin brennande vreide, og gjeva deg nåde, og hava deg kjær, og auka ætti di, som han lova federne dine -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'so sant du lyder Herren, din Gud, og held alle bodi hans, deim som eg ber fram for deg i dag, og gjer det som rett er i hans augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'De er Guds born; de må ikkje skjera dykk i holdet, eller raka dykk snaude frami skallen av di de syrgjer yver ein avliden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'For eit heilagt folk er du, vigt åt Herren, din Gud; deg hev Herren valt til sitt eigande folk framum alle andre folk på heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du må ikkje eta noko som er ufyselegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Dette er dei dyri de må eta: Uksen, sauen og geiti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'hjorten og gasella og antilopen og steinbukken og dådyret og villuksen og villgeiti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Alle firføtte dyr som hev klauver, og som jortar, deim kann de eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Det er berre desse de ikkje må eta av deim som jortar og av deim som hev klauver: Kamelen og haren og bergtassen, for dei jortar, men hev ikkje klauver; dei skal vera ureine for dykk -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'og svinet, for det hev klauver, men jortar ikkje; det skal vera ureint for dykk. Kjøtet av dei dyri må de ikkje eta, og er dei daude, so må de ikkje koma nær deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Høyr so kva de må eta av det som er i vatnet: Alt som hev uggar og reist, kann de eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Men det som ikkje hev uggar og reist, må de ikkje eta; det skal vera ureint for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alle reine fuglar kann de eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Det er berre desse fuglane de ikkje må eta: Ørnen og gribben og sjøørnen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'og glenta og heile falkeætti');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'og alle fuglar av ramneætti');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'og strussen og gauken og måsen og alle haukeslagi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'kattula og stunulven og kveldknarren');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'og hegren og etslegribben og kavfuglen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'og storken og heidloi og alle andre fuglar av same ætti, og herfuglen og skinnvengja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Alt flugjande krek skal vera ureint for dykk; de må ikkje eta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Men alt fljugande som er reint, kann de eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'De må ikkje eta noko som er sjølvdaudt! Du kann gjeva det til dei framande som bur millom dykk, so dei kann eta det, eller og kann du selja det til utlendingar; for du er eit heilagt folk, vigt til Herren, din Gud. Du skal ikkje sjoda eit kid i mjølki åt mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Tiendi av avlingi di, av alt det som veks på marki år etter år, skal du taka med deg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'til den staden som Herren, din Gud, vel seg til bustad; der skal du halda måltid for hans åsyn, og eta tiendi av kornet ditt og av vinen og oljen, og frumsungarne av storfeet og småfeet ditt, so du kann læra å ottast Herren, din Gud, alle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Men er vegen for lang for deg, er den staden som Herren, din Gud, hev valt seg til bustad for langt burte, og hev Herren velsigna deg med so rik ei grøda at du ikkje kann føra tiendi dit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'so skal du gjera det i pengar, og pengarne skal du knyta inn i eit plagg og taka med deg til den staden som Herren, din Gud, hev valt seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'For dei pengarne skal du då kjøpa alt det du hev hug til, uksar og sauer og vin og sterke drykkjer, alt det som hugen din trår etter, og so skal du halda måltid der for Herrens åsyn, og gleda deg, du og huslyden din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Og leviten som bur hjå deg, må du ikkje gløyma; for han hev ikkje fenge nokon arvlut liksom du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Tridje kvart år skal du taka undan heile tiendi av det du hev avla det året, og leggja det upp i byarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'So skal levitarne koma; for dei hev ingen arvlut liksom du; og dei framande og farlause og enkjorne som bur innan portarne dykkar, skal koma, og få det dei treng. Då skal Herren, din Gud, velsigna deg i alt det du gjer og tek deg fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Sjuande kvart år skal vera eit ettergjevingsår;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'med dette hev det seg so: Den som hev eit lån til gode hjå grannen sin, skal gjeva det etter; han skal ikkje krevja ein granne eller landsmann når dei hev lyst ettergjeving i Herrens namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Dei framande kann du krevja, men det du hev hjå landsmannen din, skal du gjeva etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Med retten skulde det no ikkje finnast fatige hjå deg; for Herren, din Gud, vil velsigna deg i det landet han gjev deg til odel og eiga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'so sant du berre lyder honom og held desse bodi, som eg ber fram for deg no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Ja Herren, din Gud, vil velsigna deg, som han hev lova, og du skal låna til mange folk, men sjølv skal du ikkje trenga noko lån, og du skal råda yver mange folk, men dei skal ikkje råda yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Finst det nokon fatig millom landsmennerne dine, i dei byarne som Herren, din Gud, vil gjeva deg, so ver ikkje hardhjarta, og lat ikkje att handi for den fatige bror din,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'men opna handi di for honom, og lån honom det han vantar og treng!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Agta deg att det ikkje kjem upp noko vondt i hjarta ditt, når du tenkjer på at det lid nær innåt det sjuande året, ettergjevingsåret, so du ser med ublide augo på den fatige bror din, og ikkje gjev honom noko; for då kjem han til å klaga deg for Herren, og du fær synd på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Gjev honom med godhug og tregelaust; det er for den skuld Herren, din Gud, velsignar deg i alt du gjer og tek deg fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Fatige kjem det stødt til å finnast i landet; difor segjer eg deg: Opne handi di for bror din, for dei arme og fatige i landet ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Når ein landsmann - ein hebræar, kar eller kvinna - hev selt til deg, so skal han tena hjå deg seks år; i det sjuande året skal du gjeva honom fri, so han kann fara kvar han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Og når du gjev honom fri, skal du ikkje senda honom frå deg tomhendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Du skal reida honom ut vel, både med småfe og med korn og vin; i same mun som Herren, din Gud, hev velsigna deg, skal du gjeva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Kom i hug at du sjølv var træl i Egyptarland, og at Herren, din Gud, fria deg ut; difor gjev eg deg i dag dette bodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Men segjer tenaren at han ikkje vil skiljast ifrå deg, av di han hev det godt hjå deg og held av deg og folket ditt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'so skal du taka ein syl og stinga gjenom øyra hans og inn i hurdi, og sidan skal han tena deg all si tid. Sameleis skal du gjera med tenestgjenta di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Du skal ikkje trega på at du lyt sleppa deim frå deg; for han hev arbeidt for deg i seks år, og leigefolk hadde kosta deg tvo gonger so mykje. Kom i hug dette, so skal Herren, din Gud, velsigna deg i alt du gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Alle frumborne handyr i buskapen din skal du vigja til Herren din Gud. Frumborne uksar må du ikkje hava til arbeids, og frumborne sauer må du ikkje klyppa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'For Herrens åsyn skal du eta deim, år etter år, du og huslyden din, på den staden som Herren hev valt seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Er det nokon lyte på deim, er dei halte eller blinde eller hev noko anna leidt lyte, då skal du ikkje ofra deim til Herren, din Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'men heime hjå dykk sjølve kann de eta deim anten det er reine og ureine, liksom det var gasella eller hjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'so nær som blodet; det må de ikkje eta; du skal slå det ut på marki som vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Kom i hug aksmånaden! Då skal du halda påskehelg for Herren, din Gud; for i aksmånaden førde Herren deg ut or Egyptarland, nattarstider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Og du skal slagta påskeoffer åt Herren, din Gud, storfe og småfe, på den staden som Herren hev valt seg til bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du skal ikkje eta syrt brød attåt offerkjøtet! I sju dagar skal du eta usyrt brød attåt det, naudhjelpsbrød, av di du laut skunda det ut or Egyptarlandet. Soleis skal du heile ditt liv minnast den dagen då du for burt frå Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Desse sju dagarne må det ikkje finnast surdeig i ditt eige, so langt som du råder, og av det du hev slagta fyrste dagen um kvelden, må ingen ting liggja natti yver, til morgons.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du må ikkje slagta påskeofferet heime, i nokon av dei byarne som Herren, din Gud, gjev deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'men berre på den staden som Herren, din Gud, hev valt seg til bustad; der skal du slagta påskelambet, um kvelden, solegladsbil, på same tid som då du for frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'So skal du laga det til, og eta det på den staden som Herren, din Gud, hev valt seg ut; og um morgonen kann du venda heim att til buderne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Seks dagar skal du eta usyrt brød; og den sjuande dagen skal du halda ei stor samlingshøgtid for Herren, din Gud; då må du ikkje gjera noko arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'So skal du rekna sju vikor: frå sigden tek til å sveiga i kornet, skal du telja sju vikor fram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'og når dei er lidne, skal du halda sjuvikehelg for Herren, din Gud. Då skal du bera fram so mykje som du hev hjarta til, i same mun som Herren, din Gud, hev velsigna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Og du skal gleda deg for Herrens åsyn, på den staden han hev valt seg til bustad, både du og son din og dotter di, og drengen og tenestgjenta, og leviten som bur innan portarne dine, og dei framande og farlause og enkjorne de hev hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'De skal koma i hug at i Egyptarland var de trælar, og gøyma desse bodi i hjarta, og liva etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Når du hev samla inn det som kjem frå låven din og frå vinpersa, då skal du halda lauvhyttehelgi i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Og du skal gleda deg so lenge denne høgtidi varer, både du og sønerne og døtterne dine, og drengjerne og gjentorne, og levitarne og dei framande og farlause og enkjorne som bur innan portarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sju dagar skal du halda pilegrimshelg for Herren, din Gud, på den staden han hev valt seg ut; for Herren, din Gud, vil velsigna deg i alt du avlar og alt du tek det fyre, og du skal vera berre glad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Tri vendor um året skal alle karmennerne dykkar møta fram for Herren, din Gud, på den staden han hev valt seg ut: i søtebrødhelgi, og i sjuvikehelgi, og i lauvhyttehelgi. Men tomhendt må ingen syna seg for Herrens åsyn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'kvar skal koma med den gåva han kann, etter som Herren, hans Gud, hev gjeve honom råd til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'I alle dei byarne som Herren, din Gud, gjev deg, skal du setja inn domarar og lagrettemenner, i kvar sine fylke; dei skal døma folket etter lov og rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du skal ikkje rengja retten, og ikkje gjera mannemun, og ikkje taka mutor; for mutorne synkverver vismenner, og spiller ei rettvis sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Berre det som rett er, skal du stræva etter, so du kann få liva, og eiga det landet som Herren, din Gud, vil gjeva deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Du skal ikkje setja noko tre som er vigt til Asjera attmed altaret som du byggjer åt Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Og du skal ikkje reisa nokon minnestein som Herren, din Gud, mislikar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du skal ikkje ofra til Herren, din Gud, ein ukse eller sau som hev noko lyte eller mein; for det er ein styggedom for Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Finst det i nokon av dei byarne som Herren, din Gud, gjev deg, ein mann eller ei kvinna av lyden som gjer det Herren mislikar, og bryt sambandet med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'og, tvert imot det eg hev sagt, gjeng av og tener andre gudar, og bøygjer kne for deim, eller for soli eller månen eller heile himmelheren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'og dette vert sagt deg, so skal du høyra deg fyre, og granska saki vel, og syner det seg då å vera sant, er det visst og vitnefast at slikt skjemdarverk er gjort i Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'då skal den mannen eller kvinna som hev gjort det brotet, førast ut til tingstaden, og steinast i hel, anten det er mann eller kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Etter vitnemål frå tvo eller tri mann lyt den vera dømd som skal lata livet; ingen skal ikkje missa livet etter ein manns vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Vitni skal fyrst lyfta handi til å drepa honom, og sidan heile folket. Soleis skal du rydja det vonde ut or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Er ei sak for vand for deg å døma i, anten det er ei dråpssak, eller ei eigedomstrætta, eller eit søksmål for helseskade, eller kva det elles er for saker som kann koma upp i by eller bygd, so skal du gjera deg reidug, og fara upptil den staden som Herren, din Gud, hev valt seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Der skal du ganga til Levi-prestarne og til den domaren som då er, og spyrja deg fyre, og dei skal segja deg korleis domen retteleg skal vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Og du skal fylgja den fyresegni dei gjev deg frå den staden som Herren hev valt seg ut; du skal i alle måtar gjera soleis som dei hev lært deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Den lovbodi dei lærer deg og den domen dei segjer deg, skal du halda deg etter, og ikkje gjera noko avbrøyte i det dei segjer deg fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Men den mannen som er so vyrdlaus at han ikkje vil høyra på presten, som stend der i Herrens tenesta, eller på domaren, han skal døy. Soleis skal du rydja det vonde ut or Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Og heile folket skal høyre det, og ottast, so dei ikkje fer so vyrdlaust åt meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Når du er komen inn i det landet som Herren, din Gud, vil gjeva deg, og hev lagt det under deg, og fest bu der, og du då kjem på at du vil få deg ein konge, liksom alle folki rundt ikring deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'so skal du taka til konge den som Herren, din Gud, kårar ut. Ein av dine eigne landsmenner skal du taka til konge; du må ikkje taka ein framand, ein som ikkje høyrer til ditt eige folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Men han skal ikkje halda mange hestar, og ikkje senda folket attende til Egyptarland, so han kann få seg mange hestar; for Herren hev sagt dykk: «Den vegen skal de ikkje fara meir!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Og han skal ikkje taka seg mange konor, so hugen hans kjem på avveg. Ikkje heller skal han draga i hop mykje sylv og gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Når han hev stige upp på kongsstolen, skal han få denne lovi hjå Levi-prestarne og skrive henne av åt seg i ei bok;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'og den skal han hava hjå seg og lesa i alle sine livedagar, so han kann læra å ottast Herren, sin Gud, og bera alle desse lovbodi og fyresegnerne i hugen og liva etter deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'og so han ikkje skal ovmoda seg yver brørne sine og koma burt ifrå lovi; då skal han liva lenge i riket sitt i Israel, både han og borni hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Ingen av Levi-prestarne, ingen av deim som høyrer til Levi-ætti, skal få nokon arvlut liksom dei andre Israels-sønerne. Dei skal liva av Herrens offerrettar og alt anna som høyrer honom til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'og ikkje få nokon arv tilliks med brørne sine; Herren skal vera arven deira, soleis som han hev sagt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Høyr no kva prestarne hev rett til å krevja av folket: Dei som ofrar slagtoffer, anten det er ukse eller sau, skal gjeva presten den eine bogen og båe kjakarne og vinstri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Det fyrste av kornet du avlar og av vinen og oljen, og den fyrste ulli av sauerne skal du gjeva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'For honom og sønerne hans hev Herren, din Gud, valt seg ut millom alle ætterne dine, so dei skal standa framfor Herren og gjera tenesta i hans namn alle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Når ein levit som held til i nokon av byarne i Israel, kjem til den staden som Herren hev valt seg ut, so skal han vera velkomen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Han kann gjera tenesta i Herrens namn, liksom dei andre levitarne, brørne hans, som stend der framfor Herrens åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'og han skal få sin lut av offergåvorne tilliks med deim, umfram dei pengarne han fær når han sel det han hev rett til etter federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Når du kjem til det landet som Herren, din Gud, gjev deg, so skal du ikkje taka etter dei folki som bur der, og fara med slik styggedom som dei fer med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Hjå deg må ingen finnast som vigjer barnet sitt i elden, ingen spåmann eller viskall, ingen som fer med å leggja ut teikn, ingen trollmann');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'eller åndemanar, ingen som spør daudingar og hamar, eller søkjer råd hjå dei avlidne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'For dei som gjer sovore, er avstyggjelege i Herrens augo, og for slik styggedom skuld er det Herren driv deim ut for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Trufast og ærleg skal du vera mot Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'For desse folki som du skal driva ut, dei lyder etter runekallar og spåmenner, men deg hev Herren, din Gud, forbode alt slikt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Ein profet som eg, av ditt eige folk, skal Herren reisa upp millom dykk; honom skal de lyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Herren skal gjera det som du bad honom um attmed Horeb, samkomedagen, då du sagde: «Eg torer ikkje høyra på Herrens røyst lenger, og denne store elden toler eg ikkje å sjå på meir; for då lyt eg døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Då sagde Herren til meg: «Det er rett det dei segjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Ein profet vil eg reisa upp for deim av deira eige folk, ein som du, og leggja ordi mine i munnen hans, og han skal tala til deim alt det eg segjer honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Og den som ikkje høyrer på ordi mine, deim som han talar i mitt namn, han skal få svara for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Men vågar ein profet å tala noko i mitt namn, og eg ikkje hev sett honom til det, eller talar han i namnet åt andre gudar, so skal han døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Og um du tenkjer med deg: «Korleis kann me vita um eit ord kjem frå Herren eller ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'so høyr her: Når ein profet talar i Herrens namn, og det han hev sagt ikkje hender og ikkje gjeng fram, so hev det ordet ikkje kome frå Herren; då er det noko profeten hev våga seg til å tala på eigi hand, og du tarv ikkje vera rædd honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Når Herren, din Gud, hev rudt ut alle folk i det landet han gjev deg, og du hev eigna det til deg, og bur i byarne og husi deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'so skal du skifta heile det riket Herren, din Gud, hev gjeve deg, i tri luter, og so skal du skilja ut tri byar i landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'og halda vegen dit godt i stand, so dei fredlause kann få røma dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Det er den som uviljande hev drepe nokon, og ikkje bar hat til honom frå fyrr, som skal få røma dit, og då vera trygg for livet sitt -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'som når ein gjeng med grannen sin ut i skogen og skal hogga timber, og han svingar øksi og vil fella eit tre, men øksi fer av skaftet og råkar grannen so han døyr, då kann han røma til ein av desse byarne og vera trygg for livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'For blodhemnaren kunde i sin heite harm setja etter dråpsmannen, og var vegen lang, kunde han nå honom att og slå honom i hel, endå han ikkje var skuldig til å døy, sidan han ikkje hadde bore hat til den han drap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Difor er det eg segjer med deg at du skal skilja ut tri byar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Og når Herren, din Gud, aukar riket ditt, som han lova federne dine, og gjev deg heile det landet han tala um å gjeva deim -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'so framt du då agtar vel på alle desse bodi og liver etter deim, soleis som eg segjer med deg i dag, so du elskar Herren, din Gud, og alle dagar gjeng på hans vegar - då skal du leggja endå tri byar attåt desse tri;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'for det må ikkje renna uskuldigt blod i det landet Herren, din Gud, gjev deg til odel og eiga, so du fær blodskuld yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Men når ein hev lagt hat til grannen sin, og lurer seg innpå honom, og slær honom til ulivs, og so rømer til ein av desse byarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'då skal styresmennerne i heimbygdi hans senda folk, og henta honom heim att, og gjeva honom i henderne på blodhemnaren, og han skal lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Du skal ikkje spara honom, men reinsa Israel for blodskuldi, so sant du vil det skal ganga deg vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Du skal ikkje flytja merkesteinarne millom deg og grannen din, deim som dei gamle hev sett kring garden du fær til odel og eiga i det landet Herren, din Gud, vil gjeva dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Eitt vitne er ikkje nok til å fella ein mann som er skulda for eit brot eller ei misgjerning, kva det so er for ei misgjerning han kann hava gjort. Tvo eller tri manns vitnemål skal det til fyrr det kann dømast i ei sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Når det kjem fram eit vondkynt vitne og skuldar ein mann for lovbrot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'so skal båe tvo møtast for Herrens åsyn, for dei prestarne og domarane som då er;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'og domarane skal granska saki vel. Syner det seg då at vitnet er ein ljugar og hev vitna rangt mot den andre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'so skal de gjera det same med honom som han hadde tenkt å gjera med hin. Soleis skal de rydja ut det vonde ut or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Og dei andre skal høyra det og ræddast, so det aldri meir vert gjort slik ei ugjerning millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Du skal ingen spara, men krevja liv for liv, auga for auga, tonn for tonn, hand for hand, fot for fot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Når du fer ut i strid mot fienden, og ser hestar og vogner og fleire herfolk enn du hev sjølv, so ver ikkje rædd deim! Herren, din Gud, er med deg, han som førde deg ut or Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Når de bur dykk til strid, skal presten stiga fram og tala til folket');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'og segja til deim: «Høyr, Israel, i dag bur de dykk til strid mot fienden! Tap ikkje modet! Ver ikkje rædde eller hugfalne eller forstøkte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'For Herren, dykkar Gud, gjeng med dykk, og vil strida for dykk mot fienden og hjelpa dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'So skal formennerne tala til folket og segja: «Er her nokon som hev bygt seg nytt hus, men endå ikkje vigsla det, då kann han fara heim att, so han ikkje skal falla i striden og ein annan vigsla huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Og er her nokon som hev stelt seg til ein vinhage, men endå ikkje havt noko gagn av honom, då kann han fara heim att, so han ikkje skal falla i striden og ein annan hausta hagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Og er her nokon som hev fest seg ei brur, men endå ikkje halde brudlaup, då kann han fara heim att, so han ikkje skal falla i striden og ein annan få bruri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Dette skal og formennerne segja til folket: «Er her nokon som er rædd og hugfallen, då kann han fara heim att, so ikkje brørne hans skal missa modet liksom han.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Og når formennerne er ferdige med det dei hev å segja til folket, skal de setja hovdingar yver heren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Når du gjeng fram mot ein by og vil taka honom, skal du fyrst bjoda fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Tek dei då imot tilbodet, og opnar portarne for deg, so skal alt folket i byen vera dine tenarar og arbeida for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Vil dei ikkje gjera fred, men vil stridast med deg, so skal du kringsetja byen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'og når Herren, din Gud, gjev honom i dine hender, skal du hogga ned alle karmenner;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'men kvinnor og born og bufe og alt anna som finst i byen, alt herfanget, kann du eigna til deg; du kann nøyta herfanget du tek frå fiendarne, og som Herren, din Gud, hev gjeve deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Soleis skal du gjera med alle byar som ligg langt burte, og ikkje høyrer desse folki til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Men i dei byarne som høyrer desse folki til, og som Herren, din Gud, gjev deg til odel og eiga, der skal du ikkje spara eit einaste liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Du skal bannstøyta deim og rydja deim ut, både hetitarne og amoritarne og kananitarne og perizitarne og hevitarne og jebusitarne, soleis som Herren, din Gud, hev sagt deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'elles kunde dei læra dykk å gjera alt det stygge dei sjølve gjer til æra for gudarne sine, og då vilde de synda mot Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Når du hev kringsett ein by og lyt liggja der lenge fyrr du fær teke honom, so skal du ikkje skamføra trei som veks der, og setja øks i deim. Du kann eta av deim, men du skal ikkje skadehogga deim. Trei på marki er då ikkje folk, so du tarv stridast med deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Men dei trei som du veit ikkje ber etande frukt, deim kann du øyda og hogga ned, og byggja kringsetjingsverk mot byen du ligg i strid med, til han lyt gjeva seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Finn de ein mann som ligg drepen på marki i det landet Herren, dykkar Gud, gjev dykk til eigedom, og ingen veit kven hev slege honom i hel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'so skal styresmennerne og domarane dykkar ganga ut og mæla kor langt det er frå liket til dei byarne som ligg der ikring;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'og styresmennerne i den byen som er næmast liket, skal taka ei kviga som aldri hev vore bruka til arbeids og aldri havt sele på seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'og leida henne ned i ein bekkjedal som korkje vert pløgd eller sådd, og i den dalen skal dei brjota halsen på kviga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'So skal prestarne koma, Levi-sønerne; for deim hev Herren, din Gud, kåra til å tena seg og til å velsigna i Herrens namn; og etter deira ord skal kvar trætta jamnast og kvar skade bøtast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Og alle styresmennerne i byen, dei som bur næmast der liket vart funne, skal två henderne sine uppyver kviga som dei hev brote halsen på i dalen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'og so skal dei taka soleis til ords: «Våre hender hev ikkje rent ut dette blodet, og våre augo hev ikkje set kven som gjorde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Herre, tak burt skuldi frå Israel, folket ditt, som du hev løyst ut, og lat ikkje Israel, ditt eige folk, lida for dråpet på ein skuldlaus mann!» Då får dei soning for blodskuldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Soleis reinsar du deg for blodskuld, og gjer det som er rett i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Når du tek ut i strid mot fienden, og Herren, din Gud, gjev honom i dine hender, so du tek fangar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'og du millom fangarne fær sjå ei fager kvinna, som du legg hug til og vil hava til kona,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'då skal du leida henne inn i huset ditt; ho skal klyppa håret og skjera neglerne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'og leggja av seg dei klædi ho gjekk med då ho vart teki, og so skal ho vera i huset ditt og syrgja yver far sin og mor si ein heil månad; sidan kann du taka henne til deg og gifta deg med henne, og ho skal vera kona di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Men vert det til det at du ikkje likar henne lenger, so skal du gjeva henne fri, so ho kann fara kvar ho vil; selja henne skal du ikkje og ikkje fara vanvyrdeleg med henne, sidan du hev livt i hop med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Når ein mann hev tvo konor, ei som han elskar og ei som han ikkje bryr seg um, og dei fær kvar sin son, men son åt den han ikkje held av er den eldste,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'og han so, når den tid kjem, vil skifta det han eig millom sønerne sine, då må han ikkje lata sonen åt den kona han elskar verta odelsmannen, til meins for den sonen som er eldst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Han skal kanna den eldste for odelsboren, endå han er son til den kona han ikkje likar, og gjeva honom dobbel lut av alt som finst i hans eige; for han er blomen av manndomen hans, han er det som eig odelsretten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Hev nokon ein son som er stridig og tråssug, og ikkje vil lyda foreldri sine, og ikkje høyra på deim når dei tel for honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'so skal foreldri taka honom med seg på tinget, til styresmennerne der i byen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'og segja til deim: «Denne sonen vår er stridig og tråssug, og vil ikkje lyda oss; han er ein øydar og ein drikkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Då skal alle mennerne i byen steina honom i hel. Soleis skal du rydja det vonde ut or lyden. Og det skal spyrjast yver heile Israel, so alle vert ottefulle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Hev nokon gjort eit brot som det er sett livsstraff for, og han so hev vorte avretta og hengd upp på eit tre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'so må ikkje liket hans verta hangande på treet natti yver, men du skal jorda honom same dagen; for Guds forbanning ligg på den som er upphengd, og du skal ikkje gjera landet ditt ureint, det som Herren, din Gud, hev gjeve deg til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Ser du ein framand ukse eller sau som hev kome på vidåtta, so skal du ikkje slengje deg undan; du skal hava deim attende til den som eig deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'men bur ikkje han tett attmed deg, eller veit du ikkje kven det er, so skal du taka deim heim til deg sjølv, og hava deim der, til eigaren kjem og spør etter deim, so du kann få gjeve honom deim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Det same skal du gjera når du finn eit asen eller eit klædeplagg, eller kva det elles kann vera, som ein annan hev mist, eller som hev kome burt for honom; du må ikkje slengja deg undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Ser du annan manns asen eller ukse liggjande i ålvelta på vegen, so må du ikkje slengja deg undan, men hjelpa mannen å reisa deim upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Eit kvende må ikkje ganga i karmannsbunad, og ein kar må ikkje klæda seg i kvendeklæde; for dei som det gjer, er avstyggjelege for Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Når du fer etter ein veg, og fær sjå eit fuglereir med ungar eller egg i eit tre eller på marki, og mori ligg på reiret, so skal du ikkje taka både mori og ungarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'du skal lata mori fljuga, men ungarne kann du taka. Då skal du få liva både vel og lenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Når du byggjer deg nytt hus, skal du setja eit handriv kring taket; elles kunde einkvar detta ned, og då kom du til å føra blodskuld yver huset ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Du skal ikkje så noko i vinhagen din; gjer du det, so fell heile avlingi under heilagdomen, både av det du hev sått, og av vintrei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du skal ikkje setja ein ukse og eit asen i hop for plogen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du skal ikkje ganga med klæde som er gjorde av tvo slag vyrke, ull og lin i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Du skal gjera deg duskar i alle fire snipparne på kjolen du gjeng med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Når ein mann tek seg ei kona, men fær uhug til henne etter dei hev kome i hop,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'og so kjem med skuldingar mot kona, og set ut eit stygt ord um henne, og segjer: «Eg gifte meg med denne kvinna, men då me kom i hop, skyna eg at ho hadde mist møydomen,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'so skal foreldri åt den unge kona taka møydomsmerki hennar, og fara til tings,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'og faren skal segja so til styresmennerne: «Eg let denne mannen få dotter mi, men no hev han fenge uhug til henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'og so kjem han med skuldingar mot henne, og segjer: «Eg fann ikkje møydom hjå dotter di;» men sjå her er møydomsmerki hennar.» Dermed skal dei breida ut brurelakanet for augo åt styresmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Og styresmennerne skal taka mannen og gjeva honom hogg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'og leggja honom ei bot på hundrad sylvdalar; deim skal dei gjeva til far åt den unge kona. Det skal den mannen hava for di han sette ut eit stygt ord um ei møy i Israel; og ho skal vera kona hans som ho hev vore; han skal aldri hava lov til å skilja seg med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Men er skuldingi sann, hadde ikkje ho møydomen sin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'so skal dei føra henne burt til døri til farshuset hennar, og mennerne der i byen skal steina henne i hel, for di ho hev gjort eit skjemdarverk og fare åt som ei skjøkja i huset åt far sin. Soleis skal du rydja det vonde ut or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Kjem de yver ein mann som ligg hjå ei gift kona, so skal dei døy båe tvo, både mannen og kona han låg hjå; soleis skal du rydja det vonde ut or Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Er ei ungmøy trulova med ein mann, og ein annan mann råkar henne i byen, og ligg hjå henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'so skal de stemna båe tvo for retten, og so steina deim i hel, gjenta for di ho ikkje ropa på hjelp, endå det var i byen dette hende, og mannen for di han hev skjemt ut annan manns festarmøy; soleis skal du rydja det vonde ut or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Men er det ute på marki ein mann råkar ei gjenta som er trulova, og han tek henne med magt, og ligg hjå henne, so skal berre mannen lata livet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'gjenta skal du ikkje gjera noko; ho hev ingi synd gjort som ho skulde missa livet for. For med dette er det som når ein mann ryk på ein annan og slær honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Mannen råka gjenta ute på marki, og ho skreik, men der var ingen til å hjelpa henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Når ein mann råkar på ei ungmøy som ikkje er trulova, og han tek henne og ligg hjå henne, og folk kjem yver deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'so skal mannen gjeva far åt gjenta eit halvt hundrad sylvdalar, og ho skal verta kona hans, for di han hev skjemt henne ut, og han må aldri skilja seg med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Ingen må taka stykmor si til kona, eller søkja seng med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Den som er klakka eller skoren på blygsli, må ikkje vera med i Herrens lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Den som er av urein ætt, må ikkje vera med i Herrens lyd; jamvel etterkomarane hans, radt til tiande leden, skal vera utestengde frå Herrens lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ein ammonit eller moabit må ikkje vera med i Herrens lyd; jamvel etterkomarane deira radt til tiande leden skal allstødt vera utestengde frå Herrens lyd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'for di dei ikkje møtte dykk ikkje på vegen med brød og vatn då de kom frå Egyptarland, og for di dei leigde Bileam, son åt Beor frå Petor i Mesopotamia til å lysa våbøn yver deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'men Herren, din Gud, vilde ikkje høyra på Bileam; han vende våbøni um til velsigning for deg, av di han hadde deg kjær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Aldri i dine livedagar skal du syta for deira velferd og lukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Edomitarne skal du ikkje hava stygg til; for dei er skyldfolket ditt. Egyptarane skal du heller ikkje hava stygg til; for du hev havt tilhald i landet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Etterkomarane deira i tridje leden kann få vera med i Herrens lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Når du tek ut i strid med fienden, og slær læger, so skal du agta deg for alt som er usømelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Er ein av dykk urein etter noko som hev hendt honom um natti, so skal han ganga ut or lægret og må ikkje koma inn att');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'fyrr det lid mot kvelden; då skal han lauga seg, og når soli hev gladt, kann han koma inn i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Utanfor lægret skal du hava ein stad som ligg for seg sjølv; dit skal du ganga dine ærender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Og millom tølorne dine skal du hava ei hakka; med den skal du grava attyver det som kjem ifrå deg når du sit der ute.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'For Herren, din Gud, er med deg i lægret; han vil hjelpa deg, og gjeva fienden i di magt; difor skal lægret ditt vera helga; han må ikkje sjå noko ufyse der; for då vender han ryggen til, og gjeng ifrå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Ein træl som hev rømt frå herren sin, og tydt seg til deg, skal du ikkje senda attende til herren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Lat honom få bu kvar han vil i landet ditt, i ein av byarne dine, der han likar seg best, og ver ikkje hard imot honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Det må ikkje finnast møy eller svein i Israel som vigjer seg til skjøkjelivnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Kom ikkje med skjøkjeløn eller tevepengar inn i huset åt Herren, din Gud, um du so skulle ha lova sovore! For alle slike pengar er ein styggedom for Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du skal ikkje taka renta av ein landsmann, korkje for pengar eller matvaror eller noko anna som dei tek renta for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Ein utlending kann du taka renta av, men av ein landsmann må du ikkje taka renta; då skal Herren, din Gud, velsigna deg i alt du tek deg fyre i det landet du kjem til å eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Når du hev gjort ein lovnad til Herren, din Gud, so må du ikkje drygja med å halda det du hev lova; elles kjem Herren til å krevja deg etter det, og du fær synd på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Um du let vera å gjera nokon lovnad, so hev du ingi synd på deg for det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'men ordet du hev gjeve, det skal du koma i hug, og halda det, soleis som du av fri vilje og med din eigen munn hev lova Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Kjem du inn i annan manns vinhage, so kann du eta druvor, so mykje du vil, til du er nøgd; men du må ikkje henta i kopp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Kjem du inn i annan manns åker, so kann du taka aks med handi; men sigd må du ikkje koma med i annan manns åker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Når ein mann hev teke seg ei kona og ført henne heim, hender det at han ikkje kann lika henne, av di han hev funne noko ufyse hjå henne. Då skriv han kann henda eit skilsmålsbrev og gjev henne i hand, og sender henne or huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Dersom no ho, etter ho hev flutt ifrå honom, gjeng stad og gifter seg med ein annan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'og denne andre og fær uhug til henne, og gjev henne skilsmålsbrev, og sender henne frå seg, eller dersom den andre mannen hennar døyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'so må ikkje den fyrste mannen, som hadde skilt seg med henne, taka henne til kona att, etter ho hev vorte urein; for slikt er avstyggjelegt i Herrens augo, og du skal ikkje føra synd yver det landet som Herren, din Gud, gjev deg til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Ein nygift mann skal ikkje fara ut i strid, og det må ikkje leggjast andre tyngslor på honom heller; han skal vera fri eit heilt år, til gagn for heimen sin og til hyggja for kona som han hev fenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Ingen må taka ei handkvern eller ein kvernstein i vissa; for då tek han livet i vissa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Kjem de yver ein mann som hev rana burt nokon av landsmennerne sine, av Israels-folket, og fer ille med honom eller sel honom, so skal ransmannen døy; soleis skal du rydja det vonde ut or lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Tak dykk i vare for spillsykja! tak dykk vel i vare, og gjer som Levi-prestarne lærer dykk! Soleis som eg hev sagt deim fyre, lyt de leggja dykk vinn um å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Kom i hug kva Herren, din Gud, gjorde med Mirjam då de var på vegen frå Egyptarland!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Når du låner ein noko, må du ikkje ganga inn i huset hans og taka det du skal hava i vissa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Du skal standa utanfor, og den du gjev lånet, skal sjølv koma ut til deg med vissa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Er det ein fatigmann, so må du ikkje hava vissa hans hjå deg um natti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'du skal lata honom få henne att når soli glader, so han kann sova i kjolen sin; då vil han takka og velsigna deg, og Herren, din Gud, vil rekna deg det til rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Du skal ikkje vera hard mot ein arbeidsmann som lid naud og er fatig, anten han høyrer til ditt eige folk, eller det er ein av dei framande som held til hjå dykk, i by eller bygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Du skal gjeva honom løni si på dagen, og fyrr enn soli glader; for han er fatig, og stundar etter løni. Elles kunde han klaga deg for Herren, og du fekk synd på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Foreldre skal ikkje lata livet for det borni hev gjort, og born ikkje for det foreldri hev gjort; ingen skal lata livet for anna enn sine eige brot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du skal ikkje rengja retten for ein framand eller farlaus, og ikkje taka klædi åt ei enkja i vissa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Kom i hug at du var træl i Egyptarland, men Herren, din Gud, fria deg ut derifrå. Difor forbyd eg deg å gjera sovore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Når du køyrer inn lodi og gløymer att eit rauk på åkeren, skal du ikkje ganga attende etter det; du skal lata dei framande og farlause og enkjorne hava det; då skal Herren, din Gud, velsigna deg i alt du tek deg fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Når du hev rist oljetrei, skal du ikkje leita etter frukt som kann ha vorte hangande på greinerne; den lyt dei framande og dei farlause og enkjorne få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Når du hev hausta vinhagen, skal du ikkje henta dei druvorne som att er; dei skal vera åt dei framande og dei farlause og enkjorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Kom i hug at du var træl i Egyptarlandet! Difor er det eg segjer deg at du skal fara so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Når folk som ligg i trætta med kvarandre, møter fram for retten, og fær dom i saki, og domen lyder so, at den eine hev rett og den andre hev urett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'og at den som hev urett, skal hava hogg, so skal dei leggja honom ned, og domaren skal sjå på at dei gjev honom so mange slag som svarar til brotet han hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Fyrti slag kann dei slå honom, ikkje fleire; for gjev dei honom mange fleire slag, vert han ærelaus for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du skal ikkje setja muleband på ein ukse som du treskjer med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Når brør bur i hop, og ein av deim døyr sonlaus, då må ikkje enkja etter den avlidne gifta seg ut or ætti og taka ein framand til mann; men verbror hennar skal festa henne, og taka henne til kona, og bu i hop med henne i staden for bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Og den fyrste sonen ho fær, skal kallast for son åt den avlidne broren, so ikkje namnet hans skal døy ut i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Men hev ikkje verbroren hug til å gifta seg med enkja, so skal ho ganga fram på tinget for styresmennerne og segja: «Verbror min neittar å reisa upp att namnet åt bror sin i Israel; han vil ikkje gifta seg med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Då skal styresmennerne i heimbygdi hans kalla honom fyre seg, og telja for honom; og stend han endå på det at han ikkje vil hava brorkona si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'so skal ho ganga burt til honom so styresmennerne ser på det, og draga skoen av foten hans, og sputta honom i andlitet og segja desse ordi: «So skal ein fara åt med den som ikkje vil byggja upp att huset åt bror sin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Og sidan skal dei i Israel kalla ætti hans «Skolausarne».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Når menner ryk i hop og slæst, og kona åt ein av dei spring burtåt og vil hjelpa mannen sin, og so grip den som slær honom, i blygsli,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'då skal du hogga av henne handi, og ikkje tykkja synd i henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du skal ikkje hava tvo slag vegtlodd i taska di, sume større og sume mindre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Du skal ikkje hava tvo slag skjeppemål i huset ditt, eit større og eit mindre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Rett og gild vegt og rett og gildt mål skal du hava. Då skal du få liva lenge i det landet som Herren, din Gud, gjev deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'For Herren, din Gud hev stygg til alle som gjer sovore, alle som gjer urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Kom i hug korleis amalekitarne for åt med dykk då de var på ferdi frå Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'korleis dei kom yver dykk på vegen, medan de var trøytte og mode, og hogg ned deim som for attarst i heren dykkar, alle deim som var veike og hadde gjeve seg etter; so lite ottast dei Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Og når du er komen til det landet som Herren, din Gud, gjev deg til odel og eiga, og han hev gjeve deg fred for alle fiendar dine rundt ikring, då skal du rydja ut or verdi alt som Amalek heitar; gløym ikkje det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Når du er komen til det landet som Herren, din Gud, gjev deg til odel og eiga, og hev lagt det under deg og fest bu der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'då skal du taka noko av fyrstegrøda av alt som du avlar på der i landet, og leggja i ei korg, og fara til den staden Herren, din Gud, hev valt seg til bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Der skal du ganga fram for den presten som då er, og segja til honom: «Eg vitnar i dag framfor Herren, din Gud, at eg er komen til det landet han lova federne våre å gjeva oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Og presten skal taka imot korgi, og setja henne ned framfor altaret åt Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'So skal du taka soleis til ords for Herrens åsyn: «\'ttefar min var ein heimlaus aramæar; han for ned til Egyptarland, og heldt til der med ein liten flokk, der vart han til eit stort og sterkt og fjølment folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Men egyptarane for ille med oss, og plåga oss, og lagde tungt arbeid på oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Då ropa me til Herren, vår fedregud, og Herren høyrde oss og såg møda og naudi og plåga vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Og Herren henta oss ut or Egyptarland med sterk hand og strak arm, og med store og øgjelege under og teikn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'og han førde oss hit, og gav oss dette landet, eit land som fløymer med mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Og sjå no kjem eg med fyrstegrøda av den jordi du hev gjeve meg, Herre!» So skal du leggja det ned for Herrens åsyn, og kasta deg på kne for Herren, din Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'og du skal gleda deg i alt det gode Herren, din Gud, hev gjeve deg og huset ditt, både du og levitarne og dei framande som bur millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Når du i det tridje året, tiendåret, hev reidt ut heile tiendi av avlingi di, og gjeve levitarne og dei framande og dei farlause og enkjorne som bur millom dykk, so dei hev fenge sitt nøgje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'då skal du tala so framfor Herren, din Gud: «No hev eg bore det heilage ut or huset, og gjeve det til levitarne og dei framande, dei farlause og enkjorne, heiltupp soleis som du hev sagt meg fyre; eg hev ikkje brote noko av bodi dine, og ikkje gløymt noko av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Ikkje hev eg ete noko av tiendi medan eg hadde sorg, og ikkje bore burt noko, medan eg var urein, og ikkje sendt noko til eit gravøl. Eg hev vore lydug mot Herren, min Gud, og i alle måtar gjort soleis som du sagde med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Sjå ned frå den heilage bustaden din i himmelen, og signa Israel, folket ditt, og det landet du hev gjeve oss, soleis som du lova federne våre, det landet som fløymer med mjølk og honning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, '«I dag segjer Herren deg det at du skal halda desse bodi og loverne. So legg deim då på minne, og liv etter deim med heile ditt hjarta og heile din hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Av Herren hev du i dag teke imot den lovnaden at han vil vera din Gud; so vil du ganga på hans vegar, og halda fyresegnerne og bodi og loverne hans og vera honom lydug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Og Herren hev i dag teke imot den lovnaden av deg at du vil vera hans eige folk, soleis som han hev sagt deg; og halda alle bodi hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'og då vil han gjera deg til det høgste av alle folk han hev skapt, til æra og gjetord og pryd, og du skal vera eit heilagt folk, vigt til Herren, din Gud, soleis som han hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Og Moses og styresmennerne i Israel tala til folket og sagde: «Legg dykk på minne alle dei bodi eg lærer dykk i dag;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'og når du hev gjenge yver Jordan, inn i det landet som Herren, din Gud, vil gjeva deg, då skal du reisa upp nokre store steinar og kalka deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'på deim skal du, når du er komen yver, skriva alle bodi i denne lovi, so sant du då vil inn i det landet Herren, din Gud, gjev deg, det landet som fløymer med mjølk og honning, soleis som Herren, din fedregud, hev sagt deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'På Ebalfjellet skal du reisa upp desse steinarne, som eg talar til deg um no, og kvita deim med kalk, og det skal de gjera med same de hev kome yver Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Og du skal byggja eit altar der åt Herren, din Gud, eit steinaltar; men du må ikkje bruka bitjarn på steinarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'av heile steinar skal du byggja altaret, og du skal ofra eit brennoffer på det til Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Og takkoffer skal du ofra, og halda eit høgtidsmål der, og gleda deg for augo åt Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Og so skal du skriva alle bodi i denne lovi på steinarne, klårt og greidt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Og Moses og Levi-prestarne tala til heile Israel, og sagde: «Gjev gaum og høyr Israel! På denne dag hev du vorte folket åt Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'So ver då lydug mot Herren, din Gud, og haldt bodi og loverne hans som eg lærer deg i dag!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Og same dagen sagde Moses til folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '«Når de er komne yver Jordan, då skal Simeon og Levi og Juda og Issakar og Josef og Benjamin stiga upp på Gerizimfjellet, og lysa velsigning yver folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Og Ruben, Gad og Asser og Sebulon, Dan og Naftali skal sdtiga upp på Ebalfjellet, og lysa våbøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Og levitarne skal taka til ords og segja so høgt at kvar mann i Israel høyrer det:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '«Forbanna vere den som hev ein kunstmann til å gjera seg eit gudebilæte, støypt eller utskore, og set det upp i løynd, det som er ein styggedom for Herren!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '«Forbanna vere den som vanvyrder foreldri sine!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '«Forbanna vere den som flyt merkesteinarne millom seg og grannen!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '«Forbanna vere den som fører ein blind på galen veg!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '«Forbanna vere den som rengjer retten for ein framand eller ein farlaus eller ei enkja!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '«Forbanna vere den, som ligg hjå stykmor si! Han sulkar lega åt far sin!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '«Forbanna vere den som blandar seg med fe!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '«Forbanna vere den som ligg hjå syster si, anten det er heilsyster eller halvsyster!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '«Forbanna vere den som ligg hjå vermor si!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '«Forbanna vere den som slær nokon i hel i løynd!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '«Forbanna vere den som tek mutor, og valdar at ein uskuldig let livet!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '«Forbanna vere den som ikkje held alle bodi i denne lovi, og ikkje liver etter deim!» Og heile folket skal segja: «Ja, ja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Høyr du no med åthug på røysti åt Herren, din Gud, hugsar og held du alle dei bodi eg gjev deg i dag, so skal han hevja deg høgt yver alle lydar på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Kvar velsigning eg nemner, skal nå deg og taka deg att, so sant som du vil høyra på røysti åt Herren, din Gud:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Velsigna vere du i by! Velsigna vere du på land!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Velsigna barnet i ditt fang! Velsigna avlen av di jord! Velsigna buskapen du el, Velsigna kalv og lamb og kid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Velsigna hjå deg korg og trog!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Velsigna ver du når du kjem inn! Velsigna ver du når du gjeng ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Når fiendarne reiser seg mot deg, skal Herren fella deim ned for din fot; på ein veg kjem dei farande imot deg, men på sju vegar skal dei ljota fly.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Til lukka skal din Herre senda bod at ho skal bu hjå deg i buderne dine og fylgja deg i all di ferd og gjerd; for Herren vil at du skal liva sæl uti det landet han hev etla deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Ja, til eit heilagt folk vil Herren gjera deg, vigt åt honom sjølv, som han hev lova deg, so framt du held hans bod og ferdast på hans veg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'og alle folk på jordi skal få sjå at du med rette heiter Herrens lyd, og dei skal ræddast deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Nøgdi av alt som godt er skal Herren senda deg, av born og buskap og av alt som marki ber, og du skal bu og byggja i det land han lova federne å gjeva deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Si rike bud i himmelen skal han lata upp for deg, so landet ditt i tidom fær det regn som trengst, og alt vert signa som du tek deg til; og du skal låna burt til mange folk, men aldri skal du turva låna sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Til hovud skal Herren setja deg, og aldri skal du verta hale. Høgre og høgre skal du stiga upp, og aldri meir skal du siga ned, so sant du berre lyder Herrens bod - deim som eg no legg fram for deg, so du skal halda deim og liva etter deim -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'og aldri tek utav den rette leid, og gløymer ordi som eg lærde deg, og fylgjer nokon annan Gud, og bed til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Men vil du ikkje høyra på røysti åt Herren, din Gud, hugsar og held du’kje alle bodi og loverne hans, deim som eg legg fram for deg i dag, skal det ganga deg so at kvar våbøn eg nemner, skal nå deg og taka deg att:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Forbanna vere du i by! Forbanna vere du på land!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Forbanna hjå deg korg og trog!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Forbanna borni som du fær! Forbanna avlen av di jord! Forbanna buskapen du el, forbanna kalv og lamb og kid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Forbanna ver når du kjem inn! Forbanna ver når du gjeng ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Forbanning, støkk og trugsmål sender Herren yver deg, kva du so tek deg til og gjer, til du vert tynt og vonom fyrr kverv burt, for di du jamt hev gjort so mykje vondt og falle frå din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Farangar skal han lata hanga atti deg, til han hev rudt deg ut or landet som du er på vegen til og skal slå under deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Med sott som syg og brenn skal han søkja deg, med hiteflagor og med verk og svull, med turkår og med moldaks og med rust, og dei skal elta deg til du er kvitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Himmelen uppyver deg skal vera som eit kopartak, og jordi under føterne dine som av jarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Regnet i landet ditt skal verta dust og sand, som fell nedyver deg til du vert kjøvd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'For fiendarne skal du rjuka: på ein veg skal du fara imot deim; og på sju vegar skal du fly. Ei skræma vert du for kvart rike jordi rundt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Til mat for fuglarne i lufti vert ditt lik, og for dei ville dyri; ingen jagar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Egyptarsotti sender Herren yver deg, kaunar og skabb og sårke, utan lækjevon;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'vitløysa, hjartestøkk og blindskap sender han;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'då lyt du trivla deg fram midt i dagsens ljos, den blinde lik som all tid gjeng i myrkrer, og aldri når du målet som du stemnar mot. Plåga og plundra vert du dag for dag, og ingen finst det som kann hjelpa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Ein annan mann tek bruri di i fang; i huset du hev bygt, fær du’kje bu; av hagen du hev stelt, fær du’kje frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Slagta vert uksarna dine med du ser på det; men du fær ikkje smaka deira kjøt; asni vert rana frå deg, og kjem aldri att; og fienden tek sauerne - ingen hjelper deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Borni vert gjevne til eit framandt folk, og augo dine skodar det, og græt seg såre etter deim all dagen lang; men det er ingi magt i handi di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Eit folk du ikkje kjenner, et upp det som du hev avla på di fedrejord, og alt som du hev vunne med ditt stræv; trælka og trådd på vert du jamt og samt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Du kjem til å missa vitet av den syn som du lyt sjå for augo dine stødt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Med vonde verker søkjer Herren deg, på kne og legg, frå hovud og til fot, og aldri fær du att helsa meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Deg og den kongen du set yver deg, skal Herren føra langt burt til eit folk som korkje du eller federne hev kjent; der lyt du tena andre gudar, stokk og stein;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'ein spegel, eit ordtøke og ei spott vert du for alle folk som Herren let deg koma til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'På åkrarne sår du ut mykje korn, men lite er det du fær samla inn; for grashopparne gneg brodden av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vinhagar kostar du, og dyrkar deim; men aldri fær du drukke eller lagt vin; for makken et upp både blom og blad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'I heile landet er det oljetre; men endå fær du aldri salva deg; det kastar karten, oljetreet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Born fær du, men du må’kje hava deim; for dei vert hertekne og førde burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Avåtet legg seg tett på alle tre og grøda som veks upp av jordi di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Den framande som bur hjå deg stig upp, høgre og høgre, yver deg, og du sig allstødt djupare og djupare.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Han hev so han kann låna burt til deg, men du hev inkje å låna honom; han vert til hovud, og du vert til hale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Og alle desse våbønerne kjem yver deg og råmar deg, so du vert øydelagd, for di du ikkje lydde Herrens ord, og ikkje heldt hans bod og loverne han gav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Og dei skal verta til eit bisn og teikn, som allstødt fylgjer deg og ætti di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'For di du ikkje tente Herren din med gleda og av hjartans hug den gongen du hadde flust av alt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'so skal du svolten, tyrst og klædelaus og aud for all ting tena fienden som Herren sender mot deg, og eit jarnok skal han leggja på din hals, til du vert kverkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Herren skal bjoda ut mot deg eit folk langt burtantil, frå verdsens ytste land; brått, liksom ørnen slær ned, kjem dei yver deg, og ikkje kann du skyna deira mål -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'eit hardleitt folk, som ingen age hev for den som gamall er, og ingen medynk med den som er ung;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'dei et upp alt du fær av buskapen, og all di avling, til du svelt i hel, av di dei ikkje leiver anten korn eller vin eller olje, anten kalv eller lamb, fyrr dei hev fenge øydt og snøydt deg reint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Dei kringset deg i kvar ein by du hev, til dess dei høge, sterke murarne du lit på, fell i heile riket ditt; dei kringset deg i alle byarne i heile landet Gud hev gjeve deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Då skal du eta eige kjøt og blod, dei borni som din Gud hev gjeve deg, so stor ei trengsla og so hard ei naud kjem fienden til å føra yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Den kjælnaste og vandaste av menn skal sjå med ovundsauga på sin bror, og på si kona, som han held i fang, og på dei siste borni han hev att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'og ikkje nennast gjeva deim ein grand av kjøtet av dei borni som han et, av di han ingen annan ting hev att til å berga seg med i den naud og trong som fiendarne fører yver honom når dei kringset dykk i kvar borg og by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Den kjælnaste og mest forvande dros som aldri baud til å setja fot på jordi for berre blautlæte og kjælenskap, ho ser med ovundsauga på sin mann, han som fekk kvila innmed hennar barm, og på sin eigen son, og dotter si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'og gjev deim ikkje av si etterferd, eller av det vesle barnet som ho fekk, men, snøydd for alt, et ho det sjølv i løynd, til å berga livet i den naud og trong som fiendarne fører henne i når han kringset dykk i kvar by og borg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Held du’kje alle bod i denne lov, deim som stend skrivne her i denne bok, ottast du ikkje det høgheilage og agelege namnet åt din Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'skal Herren senda fæle ulukkor yver deg sjølv og yver ætti di, svære og endelause ulukkor og endelause vonde sjukdomar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Egyptar-sjukarne som du er so rædd, deim skal han føra yver deg på ny, og dei skal alle hanga atti deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Og kvar ei sott og kvar ei ulukka som er unemnd i denne lovboki, skal Herren lata koma yver deg, til du er heiltupp tynt og øydelagd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'og de som fyrr var liksom stjernorne på himmelen i tal, skal minka burt, so de er att berre tvo, tri mann, for di du ikkje lydde Herrens bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Og liksom Herren fyrr hev gledt seg i å gjera vel mot dykk og auka dykk, so skal han sidan gleda seg når han let dykk forkomast fort og øydast ut, og de skal rykkjast upp utor det land de no vil inn i og slå under dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Herren skal spreida dykk bland alle folk, frå heimsens eine ende og til hin; der lyt du tena avgudar, som du og federne dine aldri hev kjent til, gudar av stokk og stein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'og aldri fær du ro hjå desse folki, aldri finn du nokon kvilestad for foten din. Herren skal gjeva deg ei sjæl som skjelv, innsokne augo og ein visna hug;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'då tykkjer du ditt liv heng etter eit hår; du bivrar natt og dag, og aldri er du trygg for livet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Kvar morgon segjer du: «Gjev det var kveld!» og vert det kveld: «Gjev det var morgon att!» Slik rædsla kjenner du i hugen din, og slik ei syn lyt augo dine sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'På skip skal Herren senda dykk attende til Egyptarland, den vegen som eg sagde deg at du aldri meir skulde sjå; der skal de verta bodne ut i mengd åt dykkar fiendar til trælar og til trælkvende, men ingen idest kjøpa dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Dette er ordi i den pakti som Herren let Moses gjera med Israels-sønerne i Moablandet, umfram den pakti han hadde gjort med deim ved Horeb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Moses kalla i hop heile Israel, og sagde til deim: «De såg det for augo dykkar alt det som Herren gjorde i Egyptarland med Farao og alle mennerne og heile landet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'med eigne augo såg de dei svære plågorne, dei store teikni og underi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Men endå hev Herren ikkje fenge gjeva dykk vit til å skyna eller augo til å sjå eller øyro til å høyra med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, '«Eg førde dykk fyrti år i øydemarki,» segjer Herren; «klædi dykkar vart ikkje utslitne, og skoen sleitst ikkje undan foten din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Ikkje hadde de brød å eta, og ikkje vin eller anna sterkt å drikka; for eg vilde de skulde sjå at eg, Herren, er dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'So kom de hit til dette landet, og Sihon, kongen i Hesbon, og Og, kongen i Basan, kom imot dykk og baud ufred, men me slo deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'og tok landet deira, og let rubenitarne og gaditarne og den halve Manasse-ætti få det til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'So kom då i hug å halda dykk etter kvart ord i denne pakti, so de fer visleg åt i alt det de gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Her stend de i dag alle framfor Herrens åsyn, hovdingarne dykkar, ætterne, styresmennerne og formennerne, kvar mann i Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'borni og konorne dykkar, og dei framande i lægret, både vedhoggaren og vatsberaren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'og skal ganga inn i sambandet med Herren, dykkar Gud, og den pakti han gjer med dykk i dag;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'for i dag vil han gjera deg til sitt folk, og sjølv vil han vera din Gud, soleis som han hev sagt deg, og soleis som han hev lova federne dine, Abraham og Isak og Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Og ikkje berre med dykk gjer han dette sambandet og denne pakti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'men både med deim som i dag stend her med oss for Herrens åsyn, og med deim som ikkje er her hjå oss i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'For de minnest vel at me budde i Egyptarlandet, og at me for fram millom alle dei folki de veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Og de såg dei ufysne styggetingi av stokk og stein, av sylv og gull, som dei hadde til gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Lat det då ikkje finnast hjå dykk mann eller kvinna, ætt eller ættgrein som i dag vender hjarta sitt burt frå Herren, vår Gud, og gjeng av og tener gudarne åt desse folki! Lat det’kje finnast nokon som er rot til trollber og malurt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'og som tenkjer med seg, når han høyrer ordi i denne pakti: «Eg er like sæl; det gjeng meg like godt, um eg trassar og fer etter min eigen hug!» For slike kjem til å føra ulukka yver bygd og by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Herren skal aldri gjeva deim til. Herrens vreide og harm skal loga imot deim som ein eld, og alle dei våbøner som er skrivne i denne boki, skal kvila på deim. Herren skal rydja namnet deira ut or verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Herren skal skilja deim ut frå alle Israels ætter, og det skal ganga deim so ille som spått er i alle våbønerne i den pakti som er skrivi i denne lovboki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Og når dei komande ætter, borni som veks upp etter dykk, og den framande som kjem frå eit land langt burte, ser dei ulukkor som hev råma dette landet, og dei sjukdomar som Herren hev heimsøkt det med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'ser heile marki strådd med svåvel og salt, og uppbrend so ho ikkje kann såast og ingen ting gjeva av seg, og det ikkje kann veksa gras på henne - som den gongen Sodoma og Gomorra og Adma og Sebojim vart lagde i øyde, dei byarne som Herren gjorde ende på i sin vreide og harm -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'då kjem dei til å spyrja, alle kjem til å spyrja: «Kvi hev Herren fare soleis åt med dette landet? Kva var det som valda denne svære vreideselden?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Og dei fær til svar: «Det var av di dei braut pakti som Herren, fedreguden deira, gjorde med deim då han henta deim ut or Egyptarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'og av di dei gjekk av og tente andre gudar, og bad til deim, gudar som dei ikkje kjende, og som han ikkje hadde gjeve deim lov til å dyrka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Difor loga Herrens vreide upp imot dette landet, so han let alle dei våbøner koma yver det som er skrivne i denne boki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Han rykte deim upp or landet deira i harm og vreide og græe, og slengde deim burt til eit anna land, og der hev dei lote vera til denne dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Det dulde høyrer Herren, vår Gud, til, men det som er openberra, gjeld for oss og borni våre i all æva; di skal me halda alle bodi i denne lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Når då alt dette kjem yver deg, velsigningi og våbøni som eg no hev lagt fyre deg, og du tek det til hjarta i dei framande landi som Herren, din Gud, hev drive deg burt til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'og du so vender um til Herren, din Gud, og lyder honom av heile ditt hjarta og heile din hug i alt det eg segjer med deg i dag, både du og borni dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'då skal Herren, din Gud, ynkast yver deg og venda lagnaden din, og sanka dykk i hop att or alle dei landi som han hadde spreidt dykk utyver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Um de so var burtstøytte til verdsens ende, so skal Herren, dykkar Gud, samla dykk og henta dykk derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Han skal føra deg heim att til det landet federne dine hev ått, og du skal få eiga det, og han skal gjera vel mot deg, og auka dykk, so de vert endå mannsterkare enn federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Og han skal gjeva deg og ætti di ein ny og skir hug, so du elskar Herren, din Gud, av heile ditt hjarta og heile di sjæl, og då skal du få liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Då skal Herren, din Gud, lata alle desse våbønerne koma yver fiendarne dine og yver deim som hev hata og sete etter deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'og du skal på nytt lag lyda Herren, din Gud, og halda alle bodi hans, som eg lærer deg i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Og Herren, din Gud, skal velsigna deg i alt du tek deg til; du skal hava lukka både med born og buskap og avling, so du vert sæl; for Herren skal då gleda seg yver deg og gjera vel imot deg, liksom han fyrr gledde seg yver federne dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'so sant du lyder Herren, din Gud, og held bodi og fyresegnerne hans, alt det som er skrive denne lovboki, og so sant du vender um til Herren, din Gud, av heile ditt hjarta og heile din hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'For dette bodet, som eg legg fyre deg i dag, det er ikkje for høgt for deg, og ikkje for langt burte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'det er ikkje uppi himmelen, so du lyt segja: «Kven vil fara upp til himmelen og henta det, og lata oss få høyra det, so me kann liva etter det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Og det er ikkje på hi sida av havet, so du lyt segja: «Kven vil fara yver havet og henta det åt oss, so me kann få høyra det og liva etter det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Bodet er deg næmare enn so: det er i din eigen munn og i ditt eige hjarta, so du vel kann liva etter det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Sjå, i dag legg eg fram for deg livet og det gode, og dauden og det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Gjer du som eg segjer med deg i dag, elskar du Herren, din Gud, og gjeng på hans vegar, og held bodi og fyresegnerne og loverne hans, då skal du liva og veksa, og Herren, din Gud, skal velsigna deg i det landet du kjem til å eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Men vender du hugen din burt, og ikkje vil lyda, og let du deg lokka til å dyrka andre gudar og tena deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'so segjer eg dykk i dag beint ut at de skal verta utrudde; de skal ikkje få liva lenge i det landet de no fer yver til og skal leggja under dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Himmel og jord tek eg i dag til vitne på at eg hev lagt fram for deg liv og daude, velsigning og våbøn! Vel då livet, so skal du få liva, både du og ætti di!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Elska Herren, din Gud, og lyd bodi hans, og haldt deg til honom! for då vinn du livet, og når ein høg alder, og fær bu i det landet som Herren lova federne dine, Abraham og Isak og Jakob.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Og Moses gjekk fram, og tala til heile Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'og sagde desse ordi: «No er eg hundrad og tjuge år gamall; eg er ikkje so nøytug som eg hev vore, og Herren hev sagt meg at eg ikkje skal koma yver Jordanåi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Herren, din Gud, vil sjølv ganga fyre deg; han vil rydja ut desse folki for deg, og du skal leggja under deg landet deira; men Josva skal føra deg yver, soleis som Herren hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Og Herren skal gjera med deim som han gjorde med Sihon og Og, amoritarkongarne, då han rudde deim ut, og lagde landet deira i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Han skal gjeva deim i dykkar magt, og de skal fara med deim i eitt og alt soleis som eg hev sagt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Ver sterke og djerve! Ræddast ikkje, og skjelv ikkje for deim! For Herren, din Gud, gjeng sjølv med deg; han vil ikkje sleppa deg, og ikkje slå handi av deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Og Moses kalla Josva åt seg, og sagde til honom, medan heile Israel stod ikring: «Ver sterk og stød! for du skal føra dette folket inn i det landet som Herren hev lova federne deira, og du skal hjelpa deim til å vinna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Og Herren skal sjølv ganga fyre deg; han skal vera med deg. Han skal ikkje sleppa deg, og ikkje slå handi av deg. Du skal ikkje ræddast og ikkje fæla!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'So skreiv Moses upp denne lovi, og gav henne til prestarne, Levi-sønerne, dei som bar Herrens sambandskista, og til alle styresmennerne i Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'og sagde til deim: «Kvart sjuande år, i ettergjevingsåret, når de held lauvhyttehelg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'og heile Israel møter fram for Herrens åsyn på den staden han hev valt seg ut, då skal du lesa upp denne lovi for Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Heile folket skal de kalla i hop, både menner og kvende og born og dei framande som bur innan portane dykkar, so dei fær høyra lovi og kann læra å ottast Herren, dykkar Gud, og koma i hug å halda alle desse bodi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Og borni deira, som ikkje kjenner bodi, lyt og få høyra deim, so dei kann læra å ottast Herren, dykkar Gud, so lenge de liver i det landet de no fer yver til og skal leggja under dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Og Herren sagde til Moses: «No lid det til at du skal fara or verdi; kalla Josva hit, og stig fram åt møtetjeldet, både du og han, so skal eg segja honom fyre kva han skal gjera.» So gjekk Moses og Josva fram åt møtetjeldet, og vart standande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Då synte Herren seg for deim i ein skystopul, og skystopulen stod i tjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Og Herren sagde til Moses: «Når du kviler hjå federne dine, då kjem dette folket til å halda seg med avgudarne i det landet dei skal til; dei kjem til å venda seg ifrå meg, og brjota den pakti eg hev gjort med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Den dagen skal harmen min loga upp; eg skal venda meg frå deim, og løyna andlitet mitt for deim; dei skal tynast burt, og koma i stor naud og ulukka. Då skal dei segja: «Det er visst av di vår Gud ikkje er hjå oss, at desse ulukkorne kjem yver oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Men endå skal eg løyna andlitet mitt, for di dei hev gjort so mykje vondt og vendt seg til andre gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Skriv no upp denne songen! Lat Israels-borni læra honom, og legg honom i munnen deira! Han skal vera meg til eit vitnemål imot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'For no fører eg deim inn i det landet eg lova federne deira, der som mjølki og honningen fløymer; men når dei hev ete seg mette og feite, kjem dei til å venda seg til andre gudar og tena deim, og vanvyrda meg, og brjota sambandet med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Når då mange ulukkor møter deim, og dei kjem i stor vande og naud, då skal denne songen ljoda som eit vitnemål for øyro deira; han skal ikkje vera gløymd hjå deim som etter kjem, og ikkje døy på munnen deira. For eg veit kva tankar dei gjeng med alt no, fyrr eg hev ført deim inn i det landet eg lova deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Same dagen skreiv Moses upp denne songen, og let Israels-sønerne læra honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Og Herren sagde til Josva Nunsson: «Ver sterk og stød! For du skal føra Israels-sønerne inn i det landet eg hev lova deim, og eg skal vera med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Då Moses hadde skrive inn i ei bok alle ordi i denne lovi, heilt til endes,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'so sagde han til levitarne som bar Herrens sambandskista:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '«Tak denne lovboki og legg henne ned innmed sambandskista åt Herren, dykkar Gud; der skal ho liggja og vera eit vitne imot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'For eg veit kor tråssuge og stride de er. Hev de’kje alt no, medan eg liver og er hjå dykk, vore ulyduge mot Herren! Korleis vil det då verta når eg er burte?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Kalla no i hop alle styresmennerne fot ætterne dykkar og alle formennerne, so vil eg kveda desse versi for deim, og taka himmelen og jordi til vitne mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'For eg veit vel at når eg er burte, kjem de til å forsynda dykk storleg, og taka utav den vegen eg hev synt dykk; men ulukka skal koma yver dykk fyrr leidi lyktar, når de gjer det som Herren mislikar og argar honom upp med framferdi dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'So kvad Moses dette kvædet frå ende til annan, for heile Israels-lyden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '«Høyr himmel, på meg, med eg talar, lyd du jord, på ordi frå min munn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Som regnet rislar mitt kvæde, som doggi dryp mine ord, som skurer på grønan grode, som el på urter og gras;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'For Herrens namn vil eg prisa; høgt love de Herren, vår Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Eit fjell er han, stød i si framferd; for rett fylgjer alle hans fet - ein trufast Gud og truverdig; rettferdig og rettvis er han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Men borni hans dei var’kje hans born; dei synda imot ham stygt, seg sjølve til skam og vanæra, ei rang og svikefull ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Er det soleis de løner Herren, du dårlege, fåvise folk! Er’kje han din far og din fostrar? Han laga deg og gav deg liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Hugs etter ævordoms dagar, gransk åri, ætt etter ætt! Spør far din, han gjev deg fråsegn, dine gamle, av deim fær du grein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Då den Høgste skifte ut heimen, og gav folki eiga og arv, då manneborni vart skilde og spreidde til kvar sin stad, då laga han landskili etter talet på Israels lyd;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'For Herrens folk er hans odel, Jakob er hans eiga og arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Han fann han på aude viddi, med det ylte i villande heid; han verna han, og han vakta han vart, som ein augnestein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Som ørnen vekkjer sitt elde, og yver ungarne sviv, so breidd’ han ut flogfjørern’ sine, og bar han uppå sin veng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Det var Herren eine som førd’ han; ingen framand gud fylgde med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Då for du fram yver høgdern’, fekk eta av landsens avl; utor berget tappa du honning, og olje or hardaste stein;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'søtrjomen og sauemjølki saup du; lambe- og verefeitt, kjøt av uksar i Basan alne åt du og ungbukkekjøt, attåt feitaste kveitemergen, og druveblod drakk du, vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Jesjurun vart feit, og slo bakut, feit vart han, foreten og stinn; han skaut ifrå seg sin skapar, mismætte sitt frelsande fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Dei arga han med avgudar, med ufryskje harma dei han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Dei blota til vonde vette, til gudar dei vankjende fyrr, nye og nyst uppkomne, som federne ikkje visst’ um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Du ansa ikkje fjellet, ditt upphav, du gløymde din skapar og Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Og Herren såg det, og støytte deim burt ifrå seg, sine born;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'og i sin harm sagde han dette: «Eg skal løyna mitt andlit for deim; eg undrast korleis det vil ganga, undrast kva ende dei fær; for dei er ei ætt av uvyrdor, born som ein aldri kann tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Dei arga meg upp med u-gudar, eggja meg med sine skrymt; eg skal eggja deim med eit u-folk, ei uvitug heidningeborg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'For ein eld er kveikt av min ande, og logar til djupt under jord; han øyder grunnen og grøda og fatar i fastaste fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Eg skal sanka i hop ulukkor og sleppa nedyver deim; kvar ei pil eg hev i mi eiga skal eg skjota av imot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Når svolt og svidande sotter hev soge mergen or deim, sender eg mot deim udyrtonni og eitr av krjupande orm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Ute herjar den kalde odden, og inne rædsla og støkk, tyner sveinar og tynar møyar, sylvherde og sugarborn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Eg hadde vilja blåse deim burt, so ingen mintest deim meir,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'ottast eg ikkje min eigen harm, når uvenern’ tydde det rangt, når valdsmennern’ sagde: «Stor er vår magt, dette er ikkje Herrens verk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'For dei er eit folk forutan visdom; dei vantar båd’ klokskap og vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Var det vit i deim, vara dei seg; for då visste dei kvar det bar av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Koss kunde ein mann elta tusund, og tvo slå ti tusund på flog, hadd’ ikkje hjelpi gjenge frå deim og Herren gjeve deim upp?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'For deira vern er’kje som vår vern; det vitnar fienden sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'I Sodoma voks deira vintre, skaut upp av Gomorras grunn; druvorn’ dei ber, det er trollber, og beisk er kvar einaste krans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Vinen av deim er orme-eiter og øgjeleg drakefraud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, '«Ligg’kje dette gøymt i mi stova, forsegla i mine skrin?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Eg råder for hemn og for attgjeld når foten deira skrid ut. Alt lid det mot undergangsdagen, og forloga deira kjem fort.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Sine tenarar tykkjer Gud synd um, og tek deira sak i si hand, når han ser det er ende på magti og ute med gamall og ung.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Han spør: «Kvar tru er deira gudar, den hjelpi dei trygde seg til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'som slauk deira slagtofferfeita, og saup deira drykkoffervin? - Bed dei reinsa seg og dykk berga, bed deim vera vervegg for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Ser de no at eg er sjølv eine: Det er ingen Gud utan eg! Eg drep, og eg vekkjer til live, eg helseslær og eg gjer heil; og ingen i vide verdi kann fria dykk or mitt vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Sjå, eg lyfter handi mot himmelen: So visst eg hev ævelegt liv:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Hev eg slipa det ljonande sverdet, og stend med domen i hand, tek eg hemn yver deim som meg hatar, valdsmannen fær det han er verd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Med kjøt vert sverdet mitt metta, mine piler drukne av blod - blodet av falne og fangar, av fiendehovdingen sjølv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Love hans tenarar, lydar! Hemna vil han deira blod; mot valdsmannen vender han våpni, og løyser sitt land og sin lyd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Då Moses hadde kvede alle versi i denne songen for folket, han og Hosea Nunsson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'og hadde tala alle desse ordi til heile Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'so sagde han til deim: «Agta no vel på alle dei ordi eg lysar for dykk i dag, so de kann læra borni dykkar å halda alle bodi i denne lovi og liva etter deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'For dette er ikkje noko tomt ord, som ikkje gjeld for dykk; livet dykkar ligg i dette ordet, og held de dykk etter det, so skal de få liva lenge i det landet de no fer yver til og skal leggja under dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Denne same dagen tala Herren til Moses, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '«Stig upp på Abarimfjellet her, på Nebotinden, som ligg i Moablandet, midt for Jeriko, so skal du få skoda Kana’ans-landet, som eg gjev Israels-borni til eigedom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'og der uppå fjellet skal du døy og fara til federne dine, soleis som Aron, døydde på Horfjellet og for til federne sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'for di de ikkje for ærleg fram mot meg millom Israels-sønerne ved Meribakjelda i Kades i Sinøydemarki, og ikkje synte Israels-sønerne allmagti mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Du skal få sjå landet framfyre deg, men inn skal du ikkje koma i det landet som eg vil gjeva Israels-sønerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Dette er den velsigningi som gudsmannen Moses lyste yver Israels-sønerne fyrr han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Han kvad: «Herren frå Sinai kom, steig upp for oss ifrå Se’ir, skein ifrå Parans heid, gjekk fram or dei heilage herar, og strålar frå handi hans strøymde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ja, han elskar ætterne høgt, og vel sine heilage vardar; dei flokkar seg kring hans fot, dei lyder trutt på hans tale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Moses lærd’ oss ei lov, ein arv for lyden åt Jakob;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'og Jesjurun kåra ein konung, då hovdingarn’ slo seg i hop, og Israels-ætterne eintest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, '«Lat Ruben liva og aldri døy ut, um mennern’ hans ikkje er mange!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Og um Juda kvad han dette: «Høyr, Herre, ropi frå Juda, og før han heim til sitt folk, som han strider veldeleg fyre; ver imot valdsmenn hans hjelp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Og um Levi kvad han: «Ditt «ljos» og «di sanning» gjev lyden åt den som hev vore deg lydug, han som du røynde i Massa, og rengdest med ved Meriba!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Dei segjer um far sin og mor si: «Eg hev ikkje sett desse folki;» dei bryr seg ikkje um brødern’ og kjendest ikkje ved borni, men agtar på ordi dine, og gøymer di pakt i sitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Dei lærer Jakob di lov og Israels lyd dine bod, dei legg røykjelse for ditt andlit, og offerfe på ditt altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Velsigna, herre, hans velde, hav hugnad i alt hans verk! Brjot ryggen på deim som renn på han, so dei aldri vinn reisa seg meir!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Um Benjamin kvad han: Hjartebarnet åt Herren hev seg so trygg ei heim han kviler imillom hans herdar; stødt held Gud si hand yver han.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Og um Josef kvad han: «Med doggi, dyre himmelgåva, velsignar Herren landet hans, med vatn utor det store djupet, som gøymt innunder jordi ligg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Med alt det beste soli el, med frukti månarne driv fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Alt godt ifrå dei gamle fjelli, alt hævt frå ævelege haug,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'alt gjævt og gildt som fyller jordi, hans blida som i klungeren bur, det kome yver Josefs hovud, det kryne kvervelen åt han, som konung er bland sine brøder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Ovgild er hans frumborne ukse! hans horn er som uruksehorn; med deim stangar han alle folki til verdsens ytste endemark. Det er Efraims store herar, det er Manasses sterke hop.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Og um Sebulon kvad han: «Gled deg, Sebulon, i di utferd, og du Issakar, i ditt tjeld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Til fjellet bed dei folki koma - rettuge forner ber dei fram; for utor sjøen syg dei rikdom og skattar gøymd’ i havsens sand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Og um Gad kvad han: «Lova vere han som gav Gad romt land! Der ligg han og lurer som løva og riv sund herdar og hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Han såg seg ut fyrste luten, etla åt den som var førar, so for han fram fyre folket, og saman med Israels-sønern’ gjord’ han alt det Herren sa fyre, alt det som var rett i Guds augo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Og um Dan kvad han: «Dan er ein løveunge lik som ifrå Basan byksar fram.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Og um Naftali kvad han: «Naftali, metta med nåde og nørd med Herrens velsigning, søk landet ditt sud med sjøen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Og um Asser kvad han: «Sælaste sonen vert Asser, bestebarn bland sine brøder; i olje fær han duppa foten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Av kopar og jarn er ditt lås, og di kvild so lang som ditt liv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Det finst ingen som Gud, Jesjurun! Han fer deg til hjelp yver himmelen og ek i si allmagt på skyerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Ei borg er den eld’-gamle Gud; hit ned når hans evige arm. Dine uvener driv han burt, og segjer åt deg: «Øyd ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'So bur då Israel trygt, og Jakobs-ætti åleine, i eit land fullt av druvor og korn, og doggi dryp frå hans himmel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Å, Israel, kor du er sæl! Kven er vel som du? - eit folk som hev Herren til frelsar, din verjande skjold og ditt velduge sverd! Sjå, fiendarne smeikjer for deg, med du yver høgderne deira skrid fram!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'So gjekk Moses frå Moabmoarne upp på Nebo, som er den høgste tinden på Pisgafjellet, og ligg midt for Jeriko, og Herren synte honom heile landet: Gilead alt til Dan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'og heile Naftali og Efraims- og Manasselandet, og heile Judalandet radt til Vesterhavet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'og Sudlandet og Jordan-kverven, dalen kring Jeriko, som dei kallar Palmebyen, alt til Soar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Og Herren sagde til honom: «Dette er det landet eg lova Abraham og Isak og Jakob at eg vilde gjeva ætti deira. No hev du set det for augo dine, men sjølv skal ikkje få koma dit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'So døydde Moses, Herrens tenar, der i Moablandet, som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Han jorda honom i dalen midt for Bet-Peor, i Moablandet, og ingen hev til denne dag visst um gravi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Moses var hundrad og tjuge år gamall då han døydde; men endå hadde han ikkje dimst på syni eller veikna i åndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Israels-sønerne gret yver honom på Moabmoarne i tretti dagar; då fyrst var det ende på syrgjehøgtidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Moses hadde lagt henderne på Josva, son åt Nun, so han og var full av visdomsånd, og Israels-sønerne lydde honom, og gjorde som Herren hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Men aldri sidan steig det fram i Israel ein profet som Moses, som var so vel kjend med Herren at dei talast ved andlit til andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Kom i hug alle dei teikn og under Herren sette honom til å gjera i Egyptarland med Farao og alle mennarne og heile landet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'og kom i hug alle dei store verk og agelege gjerningar han gjorde for augo åt heile Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Då Moses, Herrens tenar, var slokna, då tala Herren soleis til Josva Nunsson, fylgjesveinen hans:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '«Moses, tenaren min, er slokna. Gjer deg no reidug og far med alt dette folket yver Jordanåi til det landet som eg vil gjeva Israels-sønerne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Kvar staden de set foten på, gjev eg dykk, soleis som eg sagde med Moses:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Frå øydemarki og Libanon der nord til Storelvi, Eufrat, yver heile Hetitarlandet, alt til det store havet der soli glader, skal riket dykkar nå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'I alle dine livedagar, skal ingen vera mann til å standa seg mot deg. Eg skal vera med deg, liksom eg var med Moses; aldri skal eg sleppa deg og aldri forlata deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Ver sterk og stød! For du skal hjelpa dette folket til å vinna det landet som eg lova federne deira å gjeva deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Ver du berre retteleg sterk og stød, so du aldri gløymar å halda deg etter heile den lovi som Moses, tenaren min, lærde deg! Vik ikkje av ifrå den, korkje til høgre eller vinstre! Då kjem du til å stella deg visleg i all di ferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Hav allstødt denne lovi på tunga, og grunna på henne natt og dag, so du kjem i hug å liva etter alt det som der stend skrive! Då skal du hava lukka med deg på vegarne dine; for då fer du visleg fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Du veit eg hev sagt deg at du skal vera sterk og stød, ikkje ræddast og ikkje fæla; for Herren, din Gud, er med deg, kvar du fær.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Då tala Josva til formennerne for lyden og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '«Gakk kring i lægret og seg so til folket: «No lyt de laga til ferdakost åt dykk: for um tri dagar skal de fara yver Jordan, so de kann koma inn og eigna til dykk det landet som Herren, dykkar Gud, vil gjeva dykk!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Og til rubenitarne og gaditarne og helvti av Manasse-ætti tala han so:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '«Kom i hug kva Moses, Herrens tenar, sette dykk fyre då han sagde: «Herren, dykkar Gud, vil at de skal koma til ro; difor gjev han dykk dette landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'No skal konorne og borni dykkar og bufeet verta verande i det landet som Moses gav dykk austanfor Jordan; men sjølve lyt de, so mange av dykk som er fullgode stridsmenner, fara herbudde fyre brørne dykkar og hjelpa deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'til dess Herren let deim og koma til ro liksom de, og dei hev eigna til seg det landet som Herren, dykkar Gud, vil gjeva deim; då skal de fara heim att og busetja dykk i dykkar eige land, det som Moses, Herrens tenar, gav dykk her på austsida av Jordan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Då svara dei Josva so: «Alt du hev sagt til oss, skal me gjera, og kvar du sender oss, skal me ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Liksom me lydde Moses i alle ting, soleis vil me og lyda deg, berre Herren, din Gud, er med deg, som han var med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Den som set seg upp imot bodi dine og ikkje lyder deg i alt du segjer han fyre, han skal døy. Ver du berre sterk og stød!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Josva Nunsson sende i løynd tvo spæjarar ut frå Sittim, og sagde til deim: «Tak av stad, og sjå dykk um i landet, helst i Jeriko!» So for dei i veg, og då dei kom fram, gjekk dei inn til ei skjøkja som heitte Rahab, og der fekk dei hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Då vart det sagt kongen i Jeriko at nokre israelitiske menner var komne der um kvelden og vilde spæja ut landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'So sende kongen bod til Rahab, og sagde: «Kom fram med dei mennerne som er komne til deg, og som du hev lånt hus! Dei vil spæja ut heile landet; det er det dei er komne for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Men kvinna tok og løynde båe mennerne, og so sagde ho: «Ja, det er fulla so at det kom nokre menner til meg, men eg visste ikkje kvar dei var ifrå;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'og i skumingi, då porten skulde stengjast, tok dei ut att; eg veit ikkje kvar dei for av. Nøyt dykk og set etter deim, so tek de deim nok att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Dette sagde ho; men ho hadde sjølv fylgt deim upp på taket, og løynt deim under noko lin som ho hadde breidt utyver der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'So tok kongsmennerne ut, og sette etter deim på vegen til Jordan, burtåt vadi; og porten vart stengd med same dei var farne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Fyrr ferdamennerne hadde lagt seg til å sova, kom Rahab upp på taket');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'og sagde til deim: «Eg veit at Herren hev gjeve dykk dette landet. For dykkar skuld hev det kome ein otte yver oss, og alle som bur her i landet, er so rædde dykk at dei skjelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'For me hev fenge spurt at Herren turka ut Sevhavet framfyre dykk då de for frå Egyptarland, og me hev høyrt kva de gjorde med båe amoritarkongarne på hi sida Jordan, Sihon og Og, dei som de bannstøytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Då me høyrde det, kolna me all igjenom, so rædde vart me, og no finst det ingen meir som hev hug til å møta dykk; for Herren, dykkar Gud, han er Gud både uppi himmelen og nedpå jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'So sver meg no ved Herren, at sidan eg hev gjort vel imot dykk, so skal de gjera vel mot folket mitt, og gjev med trygd for');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'at de vil spara foreldri og syskini mine og alt husfolket deira, og berga livet vårt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Då sagde mennerne: «Med vårt eige liv skal me svara for livet dykkar, so sant de ikkje let nokon få vita kva ærend me fer i; og når Herren gjev oss dette landet, so skal me vera trugne og gjera vel mot deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'So fira ho deim med eit reip ned frå vindauga; for ho budde attmed bymuren, og huset hennar gjekk i eitt med muren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Og ho sagde til deim: «Far no til fjells, so de ikkje møter deim som leitar etter dykk, og haldt dykk løynde der i tri dagar, til dei kjem att; sidan kann de fara kvar de vil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Då sagde mennerne til henne: «Gjer du ikkje som me no segjer, so held me oss for løyste frå den eiden du let oss sverja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Når me kjem inn i landet, skal du binda denne raude snori i vindauga som du fira oss ned frå, og so skal du samla foreldri og brørne dine og alt skyldfolket ditt i huset hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Gjeng då nokon ut or husdøri di, so er det hans eigi skuld um han vert drepen, og me er skuldlause; men vert det lagt hand på nokon av deim som er i huset hjå deg, so skal me svara for livet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Og talar du til nokon um ærendi vår, so er me og løyste frå den eiden du tok av oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, '«Det skal vera som de segjer,» svara ho. So bad ho farvel med deim, og dei gjekk. Sidan batt ho den raude snori i vindauga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Dei gjekk til dei kom upp i fjellet; der heldt dei seg i tri dagar, til dei som hadde sett etter deim, var attkomne; dei hadde leita etter heile vegen, men ingen funne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'So tok dei tvo ferdamennerne på heimvegen og gjekk ned frå fjellet, og sette yver elvi, og kom til Josva Nunsson, og sagde frå um alt det som hadde hendt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, '«Herren hev gjeve heile landet i våre hender,» sagde dei til Josva, «og alle som bur der, er so rædde oss at dei skjelv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Morgonen etter reis Josva tidleg upp, og tok ut frå Sittim med alle Israels-folket; og dei kom til Jordan, og var der um natti, fyrr dei gjekk yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'For då tri dagar var lidne, gjekk formennerne kring i lægret');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'og tala soleis til folket: «Når de ser sambandskista åt Herren dykkar Gud, og Levi-prestarne som ber henne, so skal de fara av stad, og fylgja etter henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'so de kann vita kva leid de skal taka; for den vegen hev de ikkje fare fyrr. Men det lyt vera eit godt stykke millom dykk og sambandskista, tvo tusund alner på lag; kom henne ikkje for nær!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'So sagde Josva til folket: «Helga dykk no! for i morgon vil Herren gjera underfulle ting imillom dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Og til prestarne sagde han: «Tak sambandskista og far fram fyre folket!» So tok dei sambandskista og gjekk fyre folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Og Herren sagde til Josva: «I dag vil eg taka til og gjera deg stor framfor augo åt heile Israel, so dei skal sjå at eg er med deg, liksom eg var med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Seg no du so til prestarne som ber sambands: «Når de kjem heilt nedåt Jordan, skal de verta standande der, nedmed åi!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Då sagde Josva til Israels-sønerne: «Kom og høyr ordi frå Herren, dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Dette», sagde Josva, «skal de hava til merke på at den livande Gud er midt imillom dykk, og at han skal driva burt for dykk både kananitarne og hetitarne og hevitarne og perizitarne og girgasitarne og amoritarne og jebusitarne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Sambandskista åt honom som råder yver all jordi, skal fara fyre dykk ut i Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Vel no ut tolv menner av Israels-ætterne, ein for kvar ætt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Og når prestarne som ber sambandskista åt Herren som råder yver all jordi, når dei stig med foten ut i Jordan, då skal Jordanvatnet - det som kjem ovantil - demmast upp, so det stend som ein vegg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'So tok folket ut frå tjeldbuderne sine og skulde ganga yver Jordan, og prestarne som bar sambandskista, gjekk fyre deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'og då desse same prestarne som bar sambandskista, var komne til Jordan og so vidt hadde duppa foten i elvevatnet - men Jordan gjeng heile våren i bakkefylla -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'då stana det vatnet som kom ovantil, og stod som ein vegg alt uppmed Adam, den byen som ligg jamsides med Saretan, og det som rann nedetter til Moavatnet, eller Saltsjøen, vart reint burte. So gjekk folket yver åi midt for Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Men prestarne som bar sambandskista åt Herren, vart standande på turre botnen midt i Jordan, medan alle israelitarne gjekk turrskodde yver åi, til heile folket var kome vel yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Då alt folket var kome vel yver Jordan, då tala Herren soleis til Josva:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '«Vel dykk ut tolv menner av folket, ein or kvar ætt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'og seg til deim at dei skal taka upp tolv steinar av deim som ligg her midt i Jordan, på den staden der prestarne stend stille; desse steinarne skal dei bera med seg yver, og leggja deim ned der som de kjem til å lægra dykk i natt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Då kalla Josva til seg dei tolv mennerne som han hadde kåra ut millom Israels-sønerne, ein or kvar ætt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'og sagde til deim: «Far framfyre sambandskista åt Herren dykkar Gud, til de kjem midt ut i Jordan! Der skal de taka kvar sin stein upp på herdi, etter talet på Israels-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Dei steinarne skal vera til eit minnesmerke hjå dykk. Når borni dykkar ein gong spør: «Kva tyder det at desse steinarne stend her?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'då skal de svara: «Jordanvatnet kvarv burt framfyre sambandskista åt Herren; då ho for ut i Jordan, vart vatnet burte; og desse steinarne skal for Israels-sønerne vera til eit ævelegt minne um dette.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Israels-sønerne gjorde som Josva sagde, og tok midt uti Jordan tolv steinar, etter talet på Israels-ætterne, soleis som Herren hadde sagt til Josva, og bar deim med seg yver til nattlægret og lagde deim ned der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Og midt i Jordan, der dei prestarne som bar sambandskista stod, reiste Josva upp tolv andre steinar; dei hev stade der til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Prestarne som bar sambandskista, vart standande midt i Jordan, til det var gjort alt det som Herren hadde sagt med Josva at han skulde tala til folket um, etter alle dei fyresegnerne som Moses hadde gjeve Josva. Og folket skunda seg yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Då no alt folket var kome vel fram, for Herrens sambandskista og prestarne og yver, og tok att romet sitt framanfor folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Og Rubens-sønerne og Gads-sønerne og helvti av Manasse-ætti for fullvæpna fyre dei andre Israels-sønerne, soleis som Moses hadde sagt til deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'dei var um lag fyrti tusund herbudde menner som for Herrens åsyn drog fram til strid på Jerikomoarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Den dagen gjorde Herren Josva stor framfor augo åt heile Israel, og sidan bar dei age for honom so lenge han livde, liksom dei hadde bore age for Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'So sagde Herren til Josva:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '«Seg til prestarne som ber lovtavlekista at dei skal stiga upp or Jordan!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Og Josva sagde til prestarne: «Stig upp or Jordan!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Og med same prestarne som bar Herrens sambandskista, steig upp or Jordan og so vidt hadde sett foten på turre strandi, då kom åi veltande att i faret sitt, og gjekk i bakkefylla som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Det var tiande dagen i den fyrste månaden at folket steig upp or Jordan. Dei lægra seg attmed Gilgal, lengst aust i Jerikobygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Og der reiste Josva dei tolv steinarne som dei hadde teke med seg frå Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Og han sagde til Israels-sønerne: «Når borni dykkar ein gong spør federne sine: «Kva er dette for steinar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'so skal de segja deim det: «Israels-folket gjekk turrskodde yver Jordan her,» skal de segja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, '«av di Herren, dykkar Gud, turka ut åi framfyre dykk, medan de gjekk yver, liksom han turka ut Sevhavet for oss då me for yver det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'so alle folkeslag på jordi skulde sjå at Herrens hand er sterk, og de alle dagar skulde ottast Herren, dykkar Gud.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Alle amoritarkongarne vestanfor Jordan og alle kananitarkongarne utmed havet vart so rædde at dei reint vilde uvita då det spurdest at Herren hadde turka ut Jordan for Israels-folket medan dei for yver, og dei hadde ingen hug meir til å taka att med Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'I det same bilet sagde Herren til Josva: «Gjer deg steinknivar og umskjer Israels-sønerne att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'So gjorde Josva seg steinknivar og umskar Israels-sønerne på ein haug som sidan vert kalla Huvudhaugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Men at Josva laut umskjera deim, det hadde seg so: Alt folket som for frå Egyptarland, alle karar, alle våpnføre menner, hadde døytt burt i øydemarki på vegen frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'No var alle dei som for frå Egyptarland umskorne, men av deim som vart fødde på ferdi i øydemarki, var ingen umskoren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'For i fyrti år laut Israels-sønerne ferdast i øydemarki, til dess heile folket, alle våpnføre menner som for frå Egyptarland, var daude og burte; dei vilde ikkje lyda Herrens ord, difor svor han deim til at dei ikkje skulde få sjå det landet han hadde lova federne deira å gjeva oss, eit land som fløymer med mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Men i staden for deim let han borni deira veksa upp; deim var det Josva umskar; for dei gjekk endå med huvehold, av di dei ikkje hadde vorte umskorne på ferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Då dette var frå seg gjort, og heile folket var umskore, heldt dei seg i ro i lægret til såri hadde batna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Og Herren sagde til Josva: «I dag hev eg velt av dykk egyptarskammi.» Sidan hev den staden vore kalla Gilgal alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Medan Israels-sønerne låg i læger attmed Gilgal, heldt dei påske på Jerikomoarne den fjortande dagen i månaden, um kvelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Og dagen etter påske åt dei av landsens grøda; usyrt brød og steikte aks åt dei den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Same dagen traut manna; for no åt Israels-folket av landsens grøda, og sidan fekk dei ikkje meir manna, men tok same året til å eta av det som var avla i Kana’ans-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Då Josva var innmed Jeriko, hende det honom noko: Best som han lyfte upp augo, vart han var ein mann som stod beint framfyre honom med eit drege sverd i handi. Då gjekk Josva burt til mannen og sagde: «Er du av våre folk, eller høyrer du til fienden?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, '«Nei», svara han, «eg er hovdingen yver Herrens her. No er eg komen.» Josva fall på kne og bøygde seg til jordi og sagde: «Kva hev herren min å segja tenaren sin?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Då svara hovdingen yver Herrens her: «Drag skoen av foten din! for den staden du stend på, er heilag.» Og Josva gjorde so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'I Jeriko læste dei portarne og stengde seg inne for Israels-sønerne skuld; ingen gjekk ut, og ingen kom inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Men Herren sagde til Josva: «Sjå no gjev eg Jeriko i dine hender, med kongen og kjemporne hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Lat alt herfolket ganga rundt ikring byen ei venda um dagen; so skal du gjera i seks dagar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'og sju prestar skal bera sju stridslurar framfyre sambandskista. Men den sjuande dagen skal de ganga sju vendor kring byen, og prestarne skal blåsa i lurarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Og når stridshornet tek til å ljoma med lange tonar, og de høyrer lurljoden, skal heile heren setja i og ropa so sterkt dei kann; då skal muren ramla ned, so folket kann stiga yver han, beint inn i byen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Då kalla Josva Nunsson på prestarne og sagde til deim: «No skal de taka sambandskista og bera henne, og sju prestar skal bera sju stridslurar framfyre Herrens kista.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Og til folket sagde han: «Tak no i veg og gakk kringum byen! Dei herbudde skal ganga framfyre Herrens kista!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Då Josva hadde sagt dette til folket, gjekk dei i vegen dei sju prestarne som bar dei sju stridslurarne for Herrens åsyn; dei bles i lurarne, og Herrens sambandskista fylgde etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Dei herbudde gjekk fyre prestarne som bles i lurarne, og dei som var attarst i ferdi, gjekk etter sambandskista, og lurarne ljoma i eino.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Men Josva sagde til folket: «De må ikkje ropa, og ikkje lata upp målet! Ikkje eit ord må koma frå munnen dykkar, fyrr den dagen eg segjer til dykk: «Ropa no!» Då skal de ropa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'So for Herrens kista heilt ikring byen ei venda; sidan drog dei inn i lægret og var der um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Morgonen etter var Josva tidleg uppe, og prestarne tok og bar Herrens kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Og dei sju prestarne bar dei sju stridslurarne framfyre Herrens kista og bles alt i eitt i lurarne. Dei herbudde gjekk fyre deim, og dei som attarst var, gjekk etter Herrens kista, medan lurarne ljoma i eino.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Soleis for dei den andre dagen ei venda kring byen og gjekk so attende til lægret. So gjorde dei i seks dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Den sjuande dagen reis dei upp med same det tok til å dagast, og gjekk sju vendor kring byen; dei for like eins åt som fyrr, berre at dei den dagen gjekk sju vendor kring byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Då no prestarne bles i lurarne den sjuande gongen, då sagde Josva til folket: «Ropa no! For Herren hev gjeve dykk byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Og byen med alt det som i honom er, skal vera vigd til Herren og bannstøytt. Berre Rahab, skjøkja, og alle som er i huset hjå henne, skal få liva, for di ho løynde dei mennerne me sende ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Agta no de dykk berre for det som er vigt, so de ikkje fyrst vigjer og sidan tek av det vigde, og soleis fører forbanning og ulukka yver Israels-lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Men alt sylvet og gullet og alle ting som er av kopar eller jarn, skal helgast til Herren og koma i Herrens skattkammer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'So tok folket til å ropa, og dei bles i lurarne; og då folket høyrde lurljoden, sette dei i med eit øgjeleg herskrik; då ramla muren ned, og folket steig beint inn i byen, og då dei hadde teke honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'bannstøytte dei alt som fanst der; både menner og kvinnor, både unge og gamle, både uksar og sauer og asen hogg dei ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Men Josva sagde til dei tvo mennerne som hadde njosna der i landet: «Gakk inn i huset åt skjøkja og få med dykk ut både kvinna sjølv og alt folket hennar, soleis som de hev lova henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'So gjekk dei inn, dei unge mennerne som hadde vore der og njosna, og dei henta Rahab og foreldri og brørne hennar og alle andre som høyrde til ætti: alt skyldfolket hennar henta dei ut og fann deim ein verestad utanfor Israels-lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Byen brende dei upp med alt som i honom var; men sylvet og gullet og alle ting som var av kopar eller jarn, lagde dei ned i skattkammeret i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Josva let Rahab, skjøkja, få liva, og heile huslyden og alt skyldfolket hennar, og sidan hev ho og ætti hennar fenge bu millom Israels-folket alt til denne dag, for di ho løynde dei mennerne som Josva hadde sendt av stad til å njosna i Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Den gongen lyste Josva ei våbøn, og kvad: «Til vå og våde vere vigd den mannen som vågar byggja upp av nyom byen Jeriko! Når han hev tufta, tape han den fyrste sonen, som han fekk! Og når han set inn portarne, misse han yngste sonen sin!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Soleis var Herren med Josva, og det gjekk gjetord um honom yver heile landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Men Israels-sønerne for ikkje ærleg åt med det som var vigt til Herren. Akan, son åt Karmi, som var son åt Zabdi og soneson åt Zerah av Juda-ætti, tok noko av det vigde. Då vart Herren brennande harm på Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Frå Jeriko sende Josva nokre menner til Aj, som ligg tett innmed Bet-Aven, austanfor Betel, og sagde til deim: «Far upp og njosna i landet!» So for mennerne upp og njosna i Aj.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Og då dei kom attende til Josva, sagde dei med honom: «Lat ikkje alt folket fara der upp! Send tvo, tri tusund mann, so tek dei Aj! Du treng ikkje umaka heile heren dit; for dei er ikkje mange.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'So for um lag tri tusund mann av heren der upp; men dei rømde for Aj-mennerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'og Aj-mennerne slo i hel um lag seks og tretti av deim, og sette so etter deim frå porten til steinbrotet, og hogg deim ned i bakkarne. Då kolna Israels-sønerne all igjenom, og vart som dei var numne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Og Josva reiv sund klædi sine og låg på kne framfor Herrens kista alt til kvelds, både han og styresmennerne i Israel, og dei strådde mold på hovudi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Og Josva sagde: «Herre, min Gud, kvi førde du dette folket yver Jordan, når du vilde gjeva oss i henderne på amoritarne, so dei skulde tyna oss? Gjev me heller hadde vorte buande på hi sida Jordan!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Å kjære Herre min, kva skal eg segja no, når Israel hev snutt ryggen til fienden?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Når kananitarne og alle andre som bur her i landet, fær høyra dette, so kjem dei til å kringsetja oss og rydja namnet vårt ut or verdi, og kva vil du då gjera med ditt store namn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Då sagde Herren til Josva: «Statt upp! Kvi ligg du her på kne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hev synda! Dei hev brote det bodet eg lagde på deim, og teke av det som var vigt, og stole det og dult det burt, og gøymt det millom sine eigne ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'No kann dei ikkje Israels-sønerne standa seg mot fienden, men lyt snu ryggen til deim; for dei er sjølve vigde til ulukka. Kvittar de dykk ikkje med det som er vigt, so vil eg ikkje vera med dykk lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Statt no upp! Lat folket helga seg, og seg til deim: «Helga dykk til morgons! For so segjer Herren, Israels Gud: Det er noko vigt hjå deg, Israel! Du kann ikkje standa deg mot fiendarne fyrr de kvittar dykk med det som er vigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Tidleg i morgon skal de stiga fram, ætt for ætt, og den ætti som Herren tek ut, skal stiga fram grein for grein, og den ættgreini Herren tek ut, skal stiga fram, hus for hus, og den huslyden Herren tek ut, skal stiga fram mann for mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Og den som det vigde vert funne hjå, skal brennast med alt sitt, for di han braut Herrens bod, og gjorde eit skjemdarverk i Israel.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Morgonen etter reis Josva tidleg upp, og let Israels-folket stiga fram, ætt for ætt; og Juda-ætti vart utteki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'So let han ættgreinene i Juda stiga fram, og zerahit-greini vart utteki. So let han zerahit-greini stiga fram, mann for mann, og Zabdi vart utteken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'So let han huslyden hans stiga fram mann for mann, og Akan, son åt Karmi, som var son åt Zabdi og soneson åt Zerah av Juda-ætti, vart utteken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Då sagde Josva til Akan: «Min son, gjev Herren, Israels Gud, æra og pris, og seg meg kva du hev gjort! dyl ingen ting for meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, '«Å ja, ja, eg hev synda mot Herren, Israels Gud,» svara Akan; «no skal eg segja kva eg hev gjort:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Eg såg millom herfanget ei ven babylonsk kåpa og tvo hundrad sekel sylv og ei gullstong på femti lodd; dette fekk eg hug på og tok det; det ligg nedgrave under tjeldbudi mi; sylvet ligg underst.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'So sende Josva nokre menner av stad; dei sprang burt til tjeldbudi hans, og der fann dei det; det låg nedgrave i tjeldbudi, og sylvet låg underst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Dei tok det ut or tjeldbudi og bar det med seg til Josva og Israels-lyden og lagde det ned framfor Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Og Josva og heile Israel tok Akan, zerahiten, og sylvet og kåpa og gullstongi, og sønerne og døtterne hans, og ukserne og asni og småfeet og tjeldbudi hans og alt det han åtte, og førde det upp i Akordalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Og Josva sagde til honom: «Kvi førde du slik ulukka yver oss? I dag skal Herren føra ulukka yver deg!» So tok heile Israel og steina honom i hel og brende og steina alt som høyrde honom til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Sidan kasta dei i hop ei stor steinrøys yver honom; den hev lege der alt til denne dag. Då døyvde Herren den brennande harmen sin. Men sidan vart den staden kalla Akordalen, og det namnet hev han den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'So sagde Herren til Josva: «Ottast ikkje og ver ikkje rædd! Tak med deg alt stridsfolket, og gjer deg reidug og far upp mot Aj! For no vil eg gjeva Aj-kongen i dine hender, og folket og byen og landet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'og du skal fara like eins med Aj og kongen der som du for med Jeriko og den kongen; men herfanget og bufeet, det kann de eigna til dykk. Lat nokre av folki dine leggja seg i løynlega attanfor byen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Då gjorde Josva seg reidug til å fara upp mot Aj med heile heren. Han valde ut tretti tusund mann, djerve karar; dei sende han av stad um natti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'og sagde til deim: «Høyr her: no skal de leggja dykk i løynlega attanfor byen, ikkje svært langt ifrå honom, og halda dykk reiduge alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Men eg og alt folket som er med meg, me vil ganga tett innåt byen, og når dei fer ut imot oss, som dei gjorde fyrre gongen, so skal me låst røma for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Då kjem dei til å setja etter oss, til me hev fenge lokka deim burt ifrå byen; for dei tenkjer med seg: «Dei rømer for oss no som fyrr!» Men medan me rømer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'skal de koma fram or løynlega og taka byen; for no vil Herren dykkar Gud gjeva honom i henderne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Og når de hev teke byen, skal de setja eld på honom; de skal gjera etter Herrens ord! No hev de høyrt kva det er de skal gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'So sende Josva dei i veg, og dei gjekk av og fann seg ein løynstad, og der lagde dei seg til; det var millom Betel og Aj, vestanfor Aj. Men sjølv var Josva hjå folket den natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Morgonen etter reis Josva tidleg upp og mynstra heren, og for so saman med styresmennerne i Israel fyre heren upp til Aj;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'og alt stridsfolket som var med honom, tok i vegen, og gjekk fram til dei kom midt for Aj; der lægra dei seg, nordanfor byen, so dalen var millom den og deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'So tok Josva um lag fem tusund mann og let deim leggja seg i løynlega millom Betel og Aj, vestanfor Aj.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Og då dei hadde fylkt heren, både den som lægra nordanfor byen, og den attare flokken, som låg vestanfor, for Josva same natti midt ned i dalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Då kongen i Aj såg det, skunda han seg ut tidleg um morgonen, både han og bymennerne, alt herfolket hans, og vilde møta israelitarne og stridast med deim på den staden dei hadde avtala, framanfor moen; men han visste ikkje at det låg so mykje folk og lurde på honom attanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Og Josva og heile Israel lest tapa for deim og rømde burtimot øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Då vart alt folket i byen utbode til å setja etter deim, og medan dei sette etter Josva, kom dei lenger og lenger burt ifrå byen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'det fanst ikkje ein mann, korkje i Aj eller Betel, utan han drog ut etter israelitarne: dei let byen liggja open, og elte Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Då sagde Herren til Josva: «Rett spjotet som du held i handi, ut imot Aj; for eg vil gjeva byen i dine hender!» So rette Josva spjotet sitt ut imot byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Og med same han rette ut handi, sprang dei fram, dei som låg løynde, og for inn i byen, og tok honom, og dei sette eld på honom det snøggaste dei vann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Best som no Aj-mennerne snudde seg og skoda attende, vart dei vare røyken som steig til vers ifrå byen; då såg dei seg ingi råd til å koma undan, korkje til ei sida eller onnor, av di den heren som hadde rømt åt øydemarki, den vende seg no um imot fienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'For då Josva og israelitarne såg at dei frå løynlega hadde teke byen, og såg røyken stiga upp, då snudde dei um, og sette på Aj-mennerne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'og dei hine for til møtes med dei frå byen, so Aj-mennerne kom midt imillom israelitarne og fekk dei kring seg på alle sidor. Soleis vart dei nedhogne til siste mann; ingen vart att eller slapp undan');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'so nær som kongen; honom tok dei livande, og førde honom til Josva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Då Israel hadde gjort det av med alle dei Aj-buarne som hadde sett etter deim ut i øydemarki, og fiendarne alle som ein var falne for sverdet, so vende dei att til Aj, og hogg ned alle som var der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Den dagen fall det i alt tolv tusund menner og kvinnor, alt folket som åtte heime i Aj.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Josva tok ikkje til seg att handi som han heldt spjotet i, fyrr han hadde bannstøytt alle Aj-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Men bufeet og herfanget som israelitarne tok der i byen, eigna dei til seg, etter det som Herren hadde sagt med Josva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Josva brende upp byen, og gjorde honom for alle tider til ein grushaug og ein øydestad, so som han hev vore til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Kongen hengde han upp på eit tre, og der vart han hangande til kvelds; men då soli gladde, let han deim taka liket ned frå treet; so kasta dei det der, utfor byporten, og hauga i hop ei stor steinrøys yver det; den hev lege der alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Den gongen bygde Josva eit altar for Herren, Israels Gud, på Ebalfjellet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'soleis som Moses, Herrens tenar, hadde sagt Israels-borni fyre, etter det som stend skrive i lovboki åt Moses, eit altar av heile steinar, som det ikkje hadde vore svinga jarn på; der ofra dei brennoffer til Herren og bar fram takkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Og på steinarne sette han ei avskrift av den lovi som Moses hadde skrive for augo åt Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Og heile Israel, både sjølve folket og dei framande, med styresmennerne og formennerne og domarane sine, stod på båe sidor av sambandskista, midt imot Levi-prestarne som bar Herrens kista, den eine helvti uppunder Garizimfjellet og den andre helvti uppunder Ebalfjellet, soleis som Moses, Herrens tenar, hadde sagt at Israels-sønerne skulde standa når dei fekk velsigningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'So las han upp alle ordi i lovi, både velsigningi og våbøni, heiltupp soleis som det stend skrive i lovboki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Det fanst ikkje eit ord av alt det Moses hadde sagt fyre, utan Josva las det upp for heile Israels-lyden med både kvinnor og born, og for dei framande som fylgdest med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Då dette spurdest kom dei i hop alle kongarne som budde vestanfor Jordan, i fjellbygderne og på flatlandet og langsetter heile havstrandi til midt for Libanon - kongarne yver hetitarne og amoritarne og kananitarne og perizitarne og hevitarne og jebusitarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'og dei lova alle med ein munn at dei vilde strida mot Josva og Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Gibeon-buarne fekk og høyra kva Josva hadde gjort med Jeriko og Aj.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Då fann dei på ei sløg råd: dei tok ut på ei ferd og lest vera sendemenner; det dei førde med seg på asni sine, hadde dei i gamle sekkjer og gamle vinhitar, som var rivna og ihopatt-knytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Dei hadde gamle, lappa skor på føterne, og gjekk med slitne klæde; og alt nistebrødet deira var turt og smuldra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Soleis kom dei til Josva i lægret attmed Gilgal, og sagde til honom og Israels-mennerne: «Me kjem frå eit land som ligg langt burte. Vil de ikkje gjera samband med oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Men Israels-mennerne sagde til hevitarne: «De bur vel helst her tett innmed oss; korleis kann me då gjera samband med dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Då sagde dei til Josva: «Me vil vera tenarane dine.» «Kven er de, og kvar kjem de frå?» spurde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, '«Me er komne langt, langt burtantil frå eit anna land for det ordet skuld som gjeng um Herren din Gud», svara dei; «for då me høyrde gjete honom og fekk spurt alt det han hadde gjort i Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'og kva han hadde gjort med båe amoritarkongarne på hi sida Jordan, Sihon, kongen i Hesbon, og Og, Basan-kongen, som budde i Astarot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'då sagde styresmennerne våre og heile landslyden til oss: «Nista dykk ut, og far til møtes med deim, og seg til deim: «Me vil vera tenarane dykkar; vil de ikkje gjera samband med oss?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Her ser de brødet vårt; det var varmt då me tok det med oss heimantil den dagen me for i veg og vilde finna dykk; men sjå no kor turt og smuldra det er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Og her ser de vinhitarne; då me fyllte deim, var dei nye; men no er dei sundsprukne! Og her ser de klædi og skorne våre; dei hev vorte utslitne på denne endelause ferdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Då tok Israels-mennerne og smaka på nista deira, men spurde ikkje Herren til råds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Og Josva gjorde fred og samband med deim, og lova deim livet, og hovdingarne yver lyden gjorde eiden på det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Men tri dagar etter dei hadde gjort samband med Gibeon-folket, fekk dei vita at dei åtte heime i grannelaget og budde tett innmed deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'For då Israels-sønerne tok ut att, kom dei tridje dagen til byarne deira; det var Gibeon og Ketira og Be’erot og Kirjat-Jearim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Men dei gjorde ikkje folket der noko mein, av di hovdingarne hadde svore dei trygd ved Herren, Israels Gud. Då mukka heile lyden mot hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Men hovdingarne tala til lyden, og sagde: «Me hev svore dette folket trygd ved Herren, Israels Gud, og no kann me ikkje leggja hand på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Høyr no kva me vil gjera med deim: Me vil spara livet deira, og ikkje brjota den eiden me svor deim; for då kallar me Guds vreide ned yver oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Dei lyt få liva,» sagde hovdingarne, «men dei skal vera vedhoggarar og vatsberarar for heile lyden.» Og det vart som hovdingarne sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Og Josva kalla Gibeon-buarne fyre seg, og sagde til deim: «Kvi narra de oss og sagde at de åtte heime langt burte, og so bur de tett innmed oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'No skal de vera forbanna! Ingen av dykk skal få sleppa utor trældomen; de skal allstødt hogga ved og bera vatn til huset åt min Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Då svara dei Josva so: «Det vart sagt oss for visst at Herren, din Gud, hadde lova Moses, tenaren sin, å gjeva dykk heile landet og rydja ut for dykk alle som budde der; då vart me so rædde for livet vårt; difor gjorde me dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Men no er me i dine hender; far åt med oss som du tykkjer det er godt og rett!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Då gjorde han det so med deim; Han berga dei for Israels-sønerne, so dei ikkje vart drepne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'men samstundes sette han dei til å hogga ved og bera vatn for lyden og til altaret på den staden Herren valde seg ut, og det hev dei gjort alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Då Adoni-Sedek, kongen i Jerusalem, fekk spurt at Josva hadde teke Aj og bannstøytt byen, og gjort like eins med Aj og kongen der som med Jeriko og den kongen, og at Gibeon-buarne hadde gjort fred med israelitarne og var i hop med deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'då vart han og mennerne hans livande rædde; for Gibeon var ein stor by, som ein kongestad, og større enn Aj, og alle mennerne der var gode herfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'So sende Adoni-Sedek, kongen i Jerusalem, bod til Hoham, kongen i Hebron, og til Piream, kongen i Jarmut, og til Jafia, kongen i Lakis, og til Debir, kongen i Eglon, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '«Kom upp til meg, og hjelp meg, so skal me taka på Gibeon-folket for di dei hev gjort fred med Josva og Israels-sønerne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Då kom dei i hop desse fem amoritarkongarne, kongen i Jerusalem og kongen i Hebron og kongen i Jarmut og kongen i Lakis og kongen i Eglon, og for imot Gibeon med kvar sin her; og dei lægra seg utanfor byen og vilde taka honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Men Gibeon-mennerne sende bod til Josva i Gilgal-lægret, og sagde til honom: «Slå ikkje handi av oss! Kom upp til oss so fort du kann, og berga oss og hjelp oss! For alle amoritarkongarne som bur i fjellbygderne, hev slege seg i hop imot oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'So tok Josva ut frå Gilgal med alt herfolket og alle kjemporne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Og Herren sagde til honom: «Ver ikkje rædd deim! Eg gjev deim i dine hender. Ikkje ein av deim skal vera mann til å standa seg mot deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Josva kom brått yver deim, etter han hadde vore på vegen frå Gilgal heile natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Og Herren sette ein støkk i deim, so dei rauk reint for Israel attmed Gibeon. So sette Josva etter deim på vegen som ber upp til Bet-Horon, og hogg deim ned for fot, alt til Azeka og Makkeda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Som dei no rømde for israelitarne og rett no var komne burt i Bet-Horonkleivi, sende Herren store steinar nedyver deim frå himmelen, so dei stupte daude burtetter heile vegen til Azeka; det var fleire som sette til av haglsteinarne enn som Israels-sønerne felte med sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Den gongen ropa Josva til Herren, då Herren gav amoritarne i Israels vald, og han kvad for heile Israel: «Statt still, du sol, i Gibeon, dryg, måne, i Ajjalons dal!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Og soli stana, og månen stod, med folket tukta fiendarne sine. So veit me det stend skrive i boki åt den rettvise. Soli vart standande midt på himmelen og drygde mest ein heil dag, fyrr ho gjekk ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Og aldri anten fyrr eller sidan hev det vore nokon dag som denne, då Herren lydde eit manneord. For Herren stridde for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'So for Josva med heile Israel attende til Gilgal-lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Dei fem kongarne rømde og løynde seg i helleren attmed Makkeda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Men folk kom og sagde til Josva: «Dei hev funne dei fem kongarne; dei hadde løynt seg i Makkedahelleren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Då sagde Josva: «Velt store steinar attfor hellermunnen, og set nokre menner til å halda vakt der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Men sjølve må de ikkje stana. Set etter fienden og hogg ned deim som er attarst i ferdi! Lat dei ikkje få koma inn i byarne sine! For Herren, dykkar Gud, hev gjeve dei i dykkar hender.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Då no Josva og Israels-sønerne hadde slege fiendarne i søkk og kav og gjort reint ende på deim, so berre nokre få slapp undan og fekk berga seg inn i dei faste byarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'so kom heile heren uskadd attende til Josva i lægret attmed Makkeda, og det fanst ingen som torde knysta mot nokon av Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Då sagde Josva: «Tak burt stengslet frå helleren, og før dei fem kongarne ut til meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'So vart gjort; dei førde dei fem kongarne ut til han or helleren, kongen i Jerusalem og kongen i Hebron og kongen i Jarmut og kongen i Lakis og kongen i Eglon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Og då dei hadde ført desse kongarne ut til Josva, kalla han saman alle Israels menner og sagde til herhovdingarne som hadde fylgt honom i striden: «Stig fram, og set foten på nakken åt desse kongarne!» Då steig dei fram og sette foten på nakken deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Og Josva sagde til deim: «De skal ikkje ottast og ikkje fæla! Ver sterke og djerve! For soleis vil Herren gjera med alle fiendar de kjem i strid med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Då han hadde sagt det, hogg han til kongarne og drap deim, og hengde deim upp i kvart sitt tre, og der vart dei hangande til kvelds;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'men solegladsbil let Josva folki sine taka deim ned frå trei og kasta deim inn i den helleren dei hadde løynt seg i, og det vart lagt store steinar attfor hellermunnen; dei steinarne ligg der den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Same dagen tok Josva Makkeda, og øydde byen med odd og egg, og bannstøytte både kongen og kvart mannsbarn som der fanst; han let ingen vera att eller sleppa undan, og for like eins åt med Makkeda-kongen som han hadde gjort med kongen i Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Frå Makkeda for Josva med heile Israels-heren til Libna. Han tok på Libna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'og Herren gav den byen og i Israels hender, og like eins kongen deira. Josva øydde byen med odd og egg, og tynte kvart liv som fanst der; han let ingen vera att eller sleppa undan, og med kongen for han åt som han hadde gjort med kongen i Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Frå Libna for Josva med heile Israels-heren til Lakis. Han slo læger utanfor byen og søkte på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Og Herren gav Lakis i Israels hender. Andre dagen tok dei byen og øydde honom med odd og egg, og tynte kvart liv som fanst der, heiltupp soleis som dei hadde gjort med Libna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Då kom Horam, kongen i Geser, og vilde hjelpa Lakis-buarne. Men Josva hogg ned både honom og mennerne hans, so ingen vart att eller slapp undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'So for Josva med heile Israels-heren frå Lakis til Eglon. Dei slo læger utanfor byen og søkte på honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'og tok honom same dagen, og øydde honom med odd og egg. Den dagen bannstøytte Josva kvart liv som fanst i Eglon, heiltupp soleis som han hadde gjort med Lakis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Frå Eglon for Josva med heile Israels-heren upp til Hebron. Dei søkte på byen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'og tok honom, og øydde med odd og egg både byen og bygderne ikring, og tynte kongen og kvart liv som fanst der, so ingen vart att eller slapp undan. Josva for i alle måtar like eins åt som han hadde gjort med Eglon, og bannstøytte byen med kvart liv som der var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Sidan vende Josva seg mot Debir med heile Israels-heren. Han søkte på byen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'og tok både den og kongen som budde der, og alle bygderne ikring. Dei øydde alt med odd og egg og bannstøytte kvart liv som fanst der, so ingen vart att eller slapp undan. Josva for like eins åt med Debir og kongen der som han hadde gjort med Hebron og Libna og kongarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Soleis tok Josva heile landet, både fjellbygderne og Sudlandet og låglandet og liderne, og slo i hel alle kongarne som budde der; han let ingen vera att eller sleppa undan, men bannstøytte kvart livande liv, so som Herren, Israels Gud, hadde sagt honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Alt som fanst millom Kades-Barnea og Gaza, og heile Gosenlandet alt til Gibeon, slo han under seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Og alle desse kongarne og riki deira vann han yver med ein gong; for Herren, Israels Gud, stridde for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Sidan for Josva med heile Israel attende til Gilgal-lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Då Jabin, kongen i Hasor, fekk spurt dette, sende han bod til Jobab, kongen i Madon, og til kongen i Simron og kongen i Aksaf');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'og dei andre kongarne der nord, i fjellbygderne og på moarne sunnanfor Kinnerot og på låglandet og på Dorhøgderne utmed havet -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'til kananitarne, både i aust og i vest, og til amoritarne og hetitarne og perizitarne og jebusitarne uppi fjelli, og hevitarne nedunder Hermon, i Mispalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Då tok dei ut med alle herarne sine, ein hop so tett som sanden på havsens strand, med hestar og vogner i haugetal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Alle desse kongarne sette einannan stemna, og for til Meromvatnet; der lægra dei seg alle i hop, og vilde stridast med Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Då sagde Herren til Josva: «Ver ikkje rædd deim! I morgon dette bil legg eg deim alle drepne framfor augo åt Israel. Du skal skjera sund hasarne på hestarne deira og brenna upp vognerne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Josva og heile heren hans kom brått yver deim ved Meromvatnet, og tok på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Og Herren gav deim i Israels hender; Israels-sønerne vann yver deim og sette etter deim alt til Stor-Sidon og Misrefot-Majim og i aust alt til Mispedalen, og hogg deim ned, so ingen vart att eller slapp undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Og Josva for åt med deim som Herren hadde sagt til honom; hestarne deira skar han hasarne sund på, og vognerne brende han upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Med so gjort snudde han um, og tok Hasor og hogg ned kongen som budde der; for Hasor var fyrr i tidi hovudstaden for alle desse riki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Dei bannstøytte byen, og tynte med odd og egg kvart mannsbarn som der fanst; det vart ikkje livande liv att. Josva brende upp Hasor;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'sidan tok han alle dei andre kongebyarne med kongarne deira, og øydde deim med odd og egg; han bannstøytte deim, soleis som Moses, Herrens tenar, hadde sagt honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Men ingen av dei byarne som låg der på høgderne, sette israelitarne eld på; det var berre Hasor Josva brende upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Og alt herfanget og bufeet Israels-sønerne tok i desse byarne, eigna dei til seg; men folki tynte dei med odd og egg, til dei hadde rudt deim ut; dei sparde ikkje eit einaste liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Det som Herren hadde sagt Moses, tenaren, sin fyre, det hadde Moses sagt med Josva, og etter det gjorde Josva; han gløymde ikkje noko av alt det Herren hadde sagt til Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Soleis tok Josva heile dette landet, både fjellbygderne og heile Sudlandet og heile Gosenlandet og låglandet og moarne og fjellbygderne i Israel og flatlandet som ligg nedunder deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'frå svadknausen som ris upp yver Se’ir, til Ba’al-Gad i Libanonsdalen, nedunder Hermonfjellet; og alle kongarne der fanga han, og slo deim i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'I lang tid låg Josva i strid med alle desse kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Det fanst ingen by som gav seg under Israels-sønerne med gode, utan hevitarne i Gibeon; alt hitt tok dei med magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Herren laga det so at dei gjorde seg harde i hugen og møtte Israel i strid, av di han vilde at dei skulde bannstøytast og ingen nåde få, men øydast ut, soleis som han hadde sagt med Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'I den same tidi kom Josva og rudde ut anakitarne i fjellbygderne, i Hebron og Debir og Anab, og på heile Judafjellet og heile Israelsfjellet. Han bannstøytte både deim og byarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Ingen anakit vart att i Israelslandet, berre dei som var i Gasa og Gat og Asdod, fekk liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Josva lagde under seg heile landet, heiltupp soleis som Herren hadde sagt til Moses, og let israelitarne få det til odel og eiga etter sine folkegreiner og ætter, då landet var kome til ro etter ufreden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Dei kongarne austanfor Jordan som Israels-sønerne vann yver og tok landet frå millom Arnonåi og Hermonfjellet, med alle moarne i aust,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'det var fyrst Sihon, amoritarkongen, som budde i Hesbon og rådde yver landet nordanfor Aroer innmed Arnonåi - frå midt i åi - og yver helvti av Gilead til Jabbokåi, som er landskilet mot Ammons-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'og yver moarne på austsida, upp til Kinneretsjøen, og ned til Moavatnet eller Saltsjøen, burt imot Bet-ha-Jesjimot og sud under Pisgaliderne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'so var det riket åt Og, kongen i Basan, ein av deim som var att av kjempefolket; han budde i Astarot og Edre’i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'og rådde yver fjellbygderne kring Hermon, og yver Salka, og yver heile Basan, til landskilet mot gesuritarne og ma’akatitarne, og yver helvti av Gilead, til landskilet mot Sihon, kongen i Hesbon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Det var dei som Moses, Herrens tenar, og Israels-borni hadde vunne yver; og Moses, Herrens tenar, let rubenitarne og gaditarne og den eine helvti av Manasse-ætti få landet deira til eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Og dei kongarne som Josva og Israels-sønerne vann yver i landet vestanfor Jordan, frå Ba’al-Gad i Libanonsdalen til svadknausen som ris upp imot Se’ir - det landet som Josva skifte ut åt Israels-ætterne, grein for grein -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'i fjellbygderne og på låglandet og på moarne og i liderne og i øydemarki og i Sudlandet, kongarne yver hetitarne og amoritarne og kananitarne og perizitarne og hevitarne og jebusitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'det var: Kongen i Jeriko, ein, kongen i Aj, som ligg tett med Betel, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'kongen i Jerusalem, ein, kongen i Hebron, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'kongen i Jarmut, ein, kongen i Lakis, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'kongen i Eglon, ein, kongen i Geser, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'kongen i Debir, ein, kongen i Geder, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'kongen i Horma, ein, kongen i Arad, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'kongen i Libna, ein, kongen i Adullam, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'kongen i Makkeda, ein, kongen i Betel, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'kongen i Tappuah, ein, kongen i Hefer, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'kongen i Afek, ein, kongen i Lassaron, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'kongen i Madon, ein, kongen i Hasor, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'kongen i Simron-Meron, ein, kongen i Aksaf, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'kongen i Ta’anak, ein, kongen i Megiddo, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'kongen i Kedes, ein, kongen i Jokneam innmed Karmel, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'kongen i Dor på Dorhøgderne, ein, kongen yver Gojim attmed Gilgal, ein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'kongen i Tirsa, ein, i alt ein og tretti kongar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'No var Josva gamall vorten og ut i åri komen, og Herren sagde til honom: «No er du gamall og langt fram i åri; men endå er det ovmykje land att å taka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Det som er att er alle filistarkvervarne og heile Gesuritarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'frå den kvisli som renn frammed Egyptarland og Ekronskiftet i nord; skal reknast til Kana’an, både dei fem filistarfyrstarne i Gasa og Asdod og Askalon og Gat og Ekron, og avitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'som bur sunnanfor deim. So er det heile Kana’anitarlandet, frå Meara, som ligg under Sidon, til Afek, til skiftet med amoritarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'og Giblitarlandet, og heile austsida av Libanon, frå Ba’al-Gad nedunder Hermonfjellet til Hamatvegen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'alle dei som bur i fjellbygderne, frå Libanon til Misrefot-Majim, alle sidonarane. Sjølv vil eg driva deim ut for Israel. Men drag no du strå for Israels-sønerne, so dei fær desse bygderne til odel og eiga, soleis som eg hev sagt deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Skift ut dette landet til dei ni ætterne og den eine helvti av Manasse-ætti.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Saman med Manasse-ætti hadde rubenitarne og gaditarne fenge odelslandet sitt, det som Moses gav deim, på austsida av Jordan, soleis som Moses, Herrens tenar, gav deim det:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'alt som låg nordanfor Aroer innmed Arnon og byen i dalen, og heile Medbasletta, radt til Dibon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'og alle byarne åt Sihon, amoritarkongen, han som hadde kongssætet sitt i Hesbon, radt til skiftet med Ammons-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'og Gilead, og Gesuritarlandet og Ma’akatitarlandet og heile Hermonfjellet og heile Basan alt til Salka,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'heile riket åt Og i Basan, han som hadde kongssætet sitt i Astarot og Edre’i; han var den siste av kjempefolket. Moses vann yver desse kongarne, og tok landet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Men Israels-sønerne dreiv ikkje ut gesuritarne og ma’akatitarne; dei hev vorte buande millom Israels-folket alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Det var berre Levi-ætti han ikkje gav noko odelsland; offerretterne åt Herren, Israels Gud, skulde vera deira odel, soleis som han hadde lova deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Fyrst let Moses Rubens-sønerne og ættgreinerne deira få sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Dei fekk landet nordanfor Aroer innmed Arnon og byen i dalen, og heile høgsletta kring Medba,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon og alle byarne som til høyrde og låg på høgsletta: Dibon og Bamot-Ba’al og Bet-Ba’al-Meon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'og Jahsa og Kedemot og Mefa’at');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'og Kirjatajim og Sibma, og so Seret-Hassahar på berget i dalen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'og Bet-Peor og Pisgaliderne og Bet-ha-Jesjimot -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'alle byarne på høgsletta, og heile riket åt Sihon, amoritarkongen, som hadde kongssætet sitt i Hesbon. Det var han som Moses vann yver same gongen som han felte Midjans-hovdingarne, Evi og Rekem og Sur og Hur og Reba, som var jarlarne åt Sihon og hadde bustad der i landet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'og Bileam Beorsson, spåmannen, var og millom dei falne, deim som Israels-sønerne drap med sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Fylkesdeilet åt Rubens-borni fylgde Jordanåi; ho var skifte. Dette var det landet Rubens-sønerne og ættgreinerne deira fekk til odel og eiga med byar og bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'So let Moses Gads-ætti, Gads-sønerne og ættgreinerne deira, få sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Det dei fekk, var Jaser og alle byarne i Gilead og helvti av Ammonitarlandet alt til Aroer, som ligg midt for Rabba,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'so landet deira rakk frå Hesbon til Ramat-Hammispe og Betonim og frå Mahanajim til Debirbygdi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'og i dalen fekk dei Bet-Haram og Bet-Nimra og Sukkot og Safon, det som var att av riket åt Sihon, kongen i Hesbon. Alt dette låg på austsida av Jordan, og fylkesdeilet fylgde Jordan heilt upp til sudenden av Kinneretsjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Dette var det landet Gads-borni og ættgreinerne deira fekk til odel og eiga med byar og bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Sidan gav Moses land åt halve Manasse-ætti, so dei og, den eine helvti av Manasse-sønerne og ættgreinene deira fekk sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Dei fekk landet burtanfor Mahanajim: heile Basan, heile riket åt Og, kongen i Basan, og alle tjeldbyarne åt Ja’ir i Basan, seksti byar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'og helvti av Gilead, og Astarot og Edre’i, kongebyarne åt Og i Basan. Alt dette fekk sønerne åt Makir, son åt Manasse, helvti av Makirs-borni og ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Dette var den odelsjordi Moses luta ut, på Moabmoarne austanfor Jordanåi, som renn frammed Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Men Levi-ætti gav han ikkje noko odelsland. Herren, Israels Gud, er deira odel, soleis som han hadde lova deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'No skal me nemna dei bygderne som Israels-sønerne fekk til odel og eiga i Kana’ans-landet, og som Eleazar, øvstepresten, og Josva Nunsson og hovdingarne yver Israels-ætterne luta ut åt deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'og let deim draga strå um, soleis som Moses hadde sagt deim frå Herren. Det var halvtiande ætt som då fekk land;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'for halvtridje ætt hadde Moses gjeve land på hi sida Jordan, men levitarne hadde han ikkje gjeve noko odelsland millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Josefs-sønerne var tvo ætter, Manasse og Efraim; og levitarne fekk ingen lut i landet, anna enn nokre byar til å bu i, med bumark åt feet og bølingarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Som Herren hadde sagt Moses fyre, so gjorde Israels-sønerne, og skifte landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Då gjekk Juda-sønerne fram for Josva i Gilgal, og Kaleb Jefunneson av Kenaz-ætti sagde til honom: «Du veit kva Herren sagde med Moses, gudsmannen, um meg og deg, då me var i Kades-Barnea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Eg var fyrti år gamall då Moses, Herrens tenar, sende meg ut frå Kades-Barnea til å njosna i landet, og då eg kom attende, sagde eg frå um alt, som eg best skyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Felagerne mine, som hadde vore med meg, skræmde folket so dei vart modlause, men eg heldt meg trutt etter Herren, min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Og same dagen lyste Moses desse ordi: «Det landet du hev vore i, skal sant og visst høyra deg og borni dine til i all æva, for di du heldt deg so trutt etter Herren, min Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Og no ser du at Herren hev gjort som han lova! Han hev late meg liva fem og fyrti år sidan han tala desse ordi til Moses, all den tid som Israel ferdast i øydemarki, og no er eg fem år på femte tjuget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Endå er eg likso sterk som eg var den dagen Moses sende meg ut, og likso før både til strid og til mitt daglege yrke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'So lat meg no få denne fjellbygdi, som Herren tala um den gongen; du høyrde sjølv på det. Der bur anakitarne, og der er store byar med høge murar ikring. Men eg trur visst Herren vil vel vera med meg, so eg fær slege deim under meg, soleis som han hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Då gav Josva Kaleb Jefunneson Hebron til odel og eiga, og ynskte lukka til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Soleis var det Kaleb Jefunneson av Kenaz-ætti fekk Hebron, og sidan hev den eigedomen fylgt ætti hans alt til denne dag, for di han heldt seg so trutt etter Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Hebron heitte fyrr Arbabyen, etter den største mannen millom anakitarne. Då var det ende på ufreden, og landet fekk ro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Juda-sønerne og ættgreinerne deira fekk sin lut burtimot Edomlandet, sudmed Sinheidi, lengst sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Landskilet deira gjekk på sudsida ut frå enden av Saltsjøen, frå den viki som sting lengst i sud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'tøygde seg sud um Skorpionskardet, og tok so yver til Sin og uppetter sunnanfor Kades-Barnea; so gjekk skiftelina yver til Hesron og upp til Addar; der svinga ho burt til Karka,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'tok so burtetter til Asmon, kom fram ved Egyptarlands-bekken, og enda utmed havet. «Dette», sagde Herren, «skal vera landskilet dykkar i sud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'I aust fylgde landskilet Saltsjøstrandi, alt til Jordanosen. På nordsida gjekk fylkesdeilet frå vatsbotnen, frå Jordanosen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'upp til Bet-Hogla og heldt so frametter nordanfor Bet-ha-Araba, upp til Bohan-Rubensson-steinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'So tok skiftelina frå Akordalen, til Debir; der svinga ho nordetter til den steinkrinsen, som ligg beint imot Adummimkleivi, sunnanfor dalen, og gjekk so yver til En-Semeskjelda og fram til En-Rogel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Sidan tok ho upp til Hinnomssonsdalen, til sudsida av Jebusitaråsen, der Jerusalem ligg, og steig upp til toppen av det fjellet som er beint i vest for Hinnomsdalen, ved nordenden av Kjempesletta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Frå den fjelltoppen stemnde skiftelina burtåt Me-Neftoahkjelda, heldt fram til byarne på Efronheidi, og tok so burtetter til Ba’ala, den byen som no heiter Kirjat-Jearim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Frå Ba’ala svinga ho vestetter til Se’irfjellet, tok yver til nordhallet av Jearimfjellet, der Kesalon ligg, og gjekk so ned til Bet-Semes, og fram til Timna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Sidan heldt skiftelina nordetter til Ekronåsen; der svinga ho burt til Sikron, tok so yver til Ba’alafjellet, kom fram ved Jabne’el, og enda utmed havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'I vest var det Storhavet som var grensa. Dette var landskili åt Juda-sønerne og ættgreinerne deira, på alle sidor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kaleb Jefunneson fekk sin lut millom Juda-sønerne, etter det som Herren hadde sagt med Josva. Det var den byen som heitte etter Arba, far åt Anak, og som me no kallar Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Kaleb dreiv ut dei tri anakitarne som budde der, Sesai og Ahiman og Talmai, borni åt Anak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Sidan for Kaleb mot Debir-buarne; Debir heitte fyrr Kirjat-Sefer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Då lova han ut at den som kunde taka Kirjat-Sefer, skulde få Aksa, dotter hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Otniel, son åt Kenaz, bror åt Kaleb, tok byen, og Kaleb gav honom Aksa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Då so ho skulde flytja heim til honom, eggja ho honom til å beda far hennar um ein jordveg, og sjølv hoppa ho ned av asnet. «Kva er det du vil?» spurde Kaleb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, '«Gjev med ei velfargåva!» svara ho. «Du hev gift meg burt til dette turre Sudlandet; gjev meg no vatskjeldor!» So gav han henne Øvregullot og Nedregullot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'No skal me nemna dei eigedomarne som Juda-ætti og greinerne hennar fekk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Byarne i Sudlandet, ytst i Judafylket, burtimot Edomskiftet, det var Kabse’el og Eder og Jagur');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'og Kina og Dimona og Adada');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'og Kedes og Hasor og Jitnan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif og Telem og Bealot');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'og Hasor-Hadatta og Kerijot-Hesron, som no heiter Hasor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam og Sema og Molada');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'og Hasur-Gadda og Hesmon og Bet-Pelet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'og Hasar-Sual og Be’erseba og Bizjotja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Ba’ala og Ijjim og Esem');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'og Eltolad og Kesil og Horma');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'og Siklag og Madmanna og Sansanna');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'og Lebaot og Silhim og Ajin og Rimmon, i alt ni og tjuge byar, med grenderne som låg ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'I låglandet: Estaol og Sora og Asna');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'og Zanoah og En-Gannim, Tappuah og Enam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut og Adullam, Soko og Azeka');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'og Sa’arajim og Aditajim og Gedera med Gederotajim, fjortan byar, med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan og Hadasa og Migdal-Gad');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'og Dilan og Mispe og Jokte’el,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakis og Boskat og Eglon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'og Kabbon og Lahmas og Kitlis');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'og Gederot, Bet-Dagon og Na’ama og Makkeda, sekstan byar med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna og Eter og Asan');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'og Jiftah og Asna og Nesib');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'og Ke’ila og Aksib og Maresa, ni byar med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron med bygder og grender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'og alt som låg millom Ekron og havet på Asdodsida, med grenderne som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod med bygder og grender, Gaza med bygder og grender, radt burt til Egyptarlands-bekken og ut til Storhavet; det var grensa der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'I fjellbygderne: Samir og Jattir og Soko');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'og Danna og Kirjat-Sanna, som no heiter Debir,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'og Anab og Estemo og Anim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'og Gosen og Holon og Gilo, elleve byar, med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab og Duma og Esan');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'og Janim og Bet-Tappuah og Afeka');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'og Humta og Kirjat-Arba, som no heiter Hebron, og Sior, ni byar med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel og Zif og Juta');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'og Jizre’el og Jokdeam og Zanoah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Gibea og Timna, ti byar med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Bet-Sur og Gedor');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'og Ma’arat og Bet-Anot og Eltekon, seks byar med grenderne ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat-Ba’al, som sidan vart kalla Kirjat-Jearim, og Rabba, tvo byar med grenderne ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'I øydemarki: Bet-ha-Araba, Middin og Sekaka');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'og Nibsan og Ir-Hammelah og En-Gedi, seks byar med grenderne ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Men Juda-sønerne vann ikkje driva ut jebusitarne, som budde i Jerusalem; dei hev vorte buande i hop med Juda-sønerne i Jerusalem alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Den landsluten som fall på Josefs-sønerne, tok til aust med Jordanåi, der ho renn frammed Jeriko, og gjekk um Jerikokjelda gjenom øydemarki som stig frå Jeriko uppyver fjellet til Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Frå Betel heldt bytestrengen fram til Luz, og gjekk so burtyver til Arkiteigni, til Atarot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'der tok han vestetter ned til Jafletiteigni, heldt fram til Nedre Bet-Horoneigni og Gezer, og enda utmed havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Dette var det landet som Josefs-borni, Manasse og Efraim, fekk til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Landet åt Efraims-sønerne og ættgreinerne deira låg soleis til: Fylkesdeilet gjekk på austkanten frammed Atrot-Addar, tok burtetter til Øvre Bet-Horon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'og enda utmed havet. På nordsida gjekk fylkesdeilet frammed Mikmetat og vende seg austetter til Ta’anat-Silo; sidan heldt bytestrengen fram i aust til Janoah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'og tok frå Janoah ned til Atarot og Na’ara, snart innåt Jeriko, og gjekk ut i Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Frå Tappuah gjekk fylkesdeilet vestetter til Kanabekken, og enda utmed havet. Dette var odelseiga åt Efraims-sønerne og ættgreinerne deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'og attåt det dei byarne som vart utskilde åt Efraims-sønerne i Manassefylket, både byarne og grenderne som låg ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Men Efraims-sønerne dreiv ikkje ut dei kananitarne som budde i Gezer; Kananitarne vart buande i Efraimsfylket, som dei gjer den dag i dag, men laut gjera trælearbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'So fekk Manasse-ætti sin lut; for Manasse var eldste son åt Josef. Makir, eldste son åt Manasse og far åt Gilead, var ein gjæv stridsmann; difor fekk han Gilead og Basanlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dei andre Manasse-sønerne fekk og land, kvar ættgrein for seg: borni åt Abiezer og sønerne åt Helek og borni åt Asriel og sønerne åt Sekem og sønerne åt Hefer og sønerne åt Semida; det var borni åt Manasse, son åt Josef, og ættgreinerne deira på mannssida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Men Selofhad, son åt Hefer, som var son åt Gilead og soneson åt Makir, son åt Manasse, hadde ingi søner, berre døtter; og døtterne heitte Mahla og Noa og Hogla og Milka og Tirsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Dei gjekk fram for Eleazar, øvstepresten, og Josva Nunsson og hovdingarne, og tala so: «Herren sagde til Moses at han skulde gjeva oss odelsjord tilliks med frendarne våre.» So fekk dei odelsjord tilliks med farbrørne sine, soleis som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Det var ti partar som fall på Manasse, umfram Gilead- og Basanlandet austanfor Jordan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'for døtterne åt Manasse fekk odel tilliks med sønerne hans. Men Gileadlandet hadde dei andre Manasse-ætterne fenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Fylkesdeilet åt Manasse gjekk frå Aser til Mikmetat, som ligg midt for Sikem; so tok bytestrengen til høgre til En-Tappuahgrenderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Manasse fekk Tappuahbygdi; men Efraims-sønerne fekk byen; han låg tett innåt Manasseskiftet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'So gjekk fylkesdeilet ned til Kanabekken, på sudsida av bekken; men byarne der høyrde Efraim til, endå dei låg millom Manassebyarne. Sidan gjekk fylkesdeilet åt Manasse på nordsida av bekken, til det enda utmed havet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Efraim fekk det som var sunnanfor, og Manasse det som var nordanfor. So var havet grensa, og sidan skifte dei med Aser i nord og med Issakar i aust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'I Issakarsfylket og i Asersfylket fekk Manasse Bet-Sean med bygderne ikring, og Jibleam med bygderne ikring, og Dor med grender og bygder, og En-Dor med grender og bygder, og Ta’anak med grender og bygder, og Megiddo med grender og bygder, alt som låg under dei tri høgderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Men Manasse-sønerne vann ikkje taka desse byarne, og kananitarne fekk tak til å halda seg der i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Då Israels-sønerne vart sterkare, nøydde dei kananitarne til å træla for seg, men dreiv deim ut gjorde dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Josefs-sønerne kom til Josva og sagde: «Kvi hev du gjeve oss berre ein lut til odel og eiga? Me er då eit mannsterkt folk, etter di Herren til dessa hev velsigna oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, '«Er de so fjølmente,» sagde Josva, «so gakk upp i skogen, og ryd dykk jord der i Perizit- og Refaitlandet, sidan Efraimsheidi er for trong for dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, '«Heidi rekk ikkje til for oss,» svara Josef-sønerne, «og alle kananitarne som bur i dalbygderne, hev jarnvogner, både dei i Bet-Sean og grenderne der ikring, og dei på Jizre’elsletta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Då sagde Josva til Josefs-ætti, Efraim og Manasse: «Mykje folk hev du, og sterk er du! Du skal få meir enn ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Men det er ei fjellbygd du fær; det er skog der, og den lyt du hogga, og landet skal vera ditt til ytste endarne; for kananitarne skal du driva ut, endå dei hev jarnvogner, og endå dei er sterke.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'So kom heile Israels-lyden saman i Silo, og der sette dei upp møtetjeldet; for no var landet vunne, og låg ope for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Men endå var det att sju av Israels-ætterne som ikkje hadde skift odelsjordi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Då sagde Josva til Israels-sønerne: Kor lenge vil de drygja fyrr de kjem og eignar til dykk det landet som Herren, dykkar fedregud, hev gjeve dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Kom med tri mann av kvar ætt, som eg kann senda i veg, so skal dei stella seg til, og fara kring i landet og skriva upp alt det dei ser, so me kann vita kor mykje der er å skifta; sidan skal dei koma attende til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'So skal de byta landet i sju luter og skifta deim millom dykk! Juda-sønerne skal verta verande i det landet dei hev fenge der sud, og Josefs-ætterne i sitt land her nord;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'men de skal skriva upp alt som er i landet, i sju bolkar, og koma hit til meg med uppskrifti, so skal eg draga strå for dykk her, framfor Herrens, vår Guds, åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'For levitarne fær ingen lut millom dykk; Herrens prestedøme skal vera deira arvlut. Og Gad og Ruben og den eine helvti av Manasse-ætti hev fenge sitt land austanfor Jordan, det landet som Moses, Herrens tenar, gav deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'So gjorde mennerne seg reiduge til å fara, og då dei tok ut, sagde Josva med deim at dei skulde skriva upp alt dei såg i landet. «Tak i vegen,» sagde han, «og far kring i landet, og skriv upp alt, og kom attende til meg, so skal eg draga strå for dykk framfor Herrens åsyn her i Silo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Dermed tok mennerne av stad og for kring i landet, og skreiv upp bygd for bygd i ei bok, i sju bolkar. So kom dei attende til Josva, til Silo-lægret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'og Josva drog strå for deim, framfor Herrens åsyn; der, i Silo, skifte han landet millom Israels-ætterne, etter som dei hadde folk til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Den fyrste luten fall på Benjamins-sønerne og ættgreinerne deira; det landet dei fekk, kom til å liggja millom Juda-sønerne og Josefs-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Fylkesdeilet gjekk på nordsida upp frå Jordan og nordum Jerikoåsen og stemnde so vestetter upp på fjellet og fram til Bet-Avenheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Derifrå tok det burtyver til Luz, sunnanfor Luzåsen, der Betel ligg, og gjekk so ned til Atrot-Addar, og upp på det fjellet som ligg sunnanfor Nedre Bet-Horon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'So gjorde skiftelina ein sving, og vende seg, på vestsida, sudetter frå det fjellet som ligg beint sunnanfor Bet-Horon, til ho enda innmed Kirjat-Ba’al, ein by som høyrde Juda-sønerne til; no heiter han Kirjat-Jearim. Dette var vestsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'På sudsida gjekk fylkesdeilet frå enden av Kirjat-Jearim - der var det skiftelina tok til i vest - og fram til Me-Neftoahkjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'So gjekk skiftelina ned til foten av fjellet som ligg austanfor Hinnomssonsdalen, nordanfor Kjempesletta, tok so ned Hinnomsdalen til sudsida av Jebusitaråsen og ned til En-Rogel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Sidan svinga ho mot nord og gjekk fram til En-Semes og til dei steinkrinsarne som ligg midt for Adummimkleivi, og tok so ned til Bohan-Rubensson-steinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Der tok ho yver til den åsen som ligg rett i nord for Araba, og so ned til Araba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Sidan heldt ho fram til nordsida av Bet-Hoglaåsen, og enda i den nørdste viki av Saltsjøen, attmed Jordanosen. Dette var fylkesdeilet i sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'På austsida var det Jordan som var deile. Dette var odelsjordi åt Benjamins-sønerne og ættgreinerne deira, med fylkesdeilderne rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Byarne som Benjamins-ætti og greinerne hennar var: Jeriko og Bet-Hogla og Emek-Kesis');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'og Bet-ha-Araba og Semarajim og Betel');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'og Avvim og Happara og Ofra');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'og Kefar-ha-Ammoni og Ofni og Geba, tolv byar med grenderne ikring;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon og Rama og Be’erot');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'og Mispe og Kefira og Hammosa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'og Rekem og Jirpe’el og Tarala');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'og Sela, Elef og Jebus, som no heiter Jerusalem, og Gibat og Kirjat, fjortan byar, med grenderne ikring. Dette var landet åt Benjamins-sønerne og ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Den andre luten fall på Simeon, på Simeons-sønerne og ættgreinerne deira. Det landet dei fekk, låg midt i Judafylket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Til Simeonsfylket høyrde Be’erseba og Seba og Molada');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'og Hasar-Sual og Bala og Esem');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'og Eltolad og Betul og Horma');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'og Siklag og Bet-Hammarkabot og Hasar-Susa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'og Bet-Leabot og Saruhen - trettan byar med grenderne som høyrde til;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ajin, Rimmon og Eter og Asan, fire byar, med grenderne som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'og alle bygderne som låg ikring desse byarne, alt til Ba’alat-Be’er, eller Rama, i Sudlandet. Dette var odelsjordi åt Simeons-ætti og greinerne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Dei fekk odelseiga si i det landet som var mælt ut til Juda-sønerne. Den luten som fall på Juda-sønerne, vart for stor åt deim; difor var det at Simeons-sønerne fekk landet sitt midt i deira land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Den tridje luten fall på Sebulons-sønerne og ættgreinerne deira. Det landet dei fekk, rakk til Sarid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Fylkesdeilet gjekk i vest upp til Marala, gjekk frammed Dabbeset og nådde den bekken som renn austanfor Jokneam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'I aust, der soli kjem upp, vende det seg frå Sarid burt imot Kislot-Taborbygdi, heldt fram til Daberat og gjekk upp til Jafia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Derifrå tok det, på solsida, austsida, yver til Gat-Hefer og Et-Kasin, heldt fram til Rimmon og svinga burt til Nea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'So vende deilet seg nordetter til Hannaton og enda i Jiftaheldalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'I Sebulonsfylket låg og Kattat og Nahalal og Simron og Jidala og Betlehem; i alt var der tolv byar med grender ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Dette var det landet Sebulons-sønerne og ættgreinerne deira fekk til odel og eiga med byar og bygdar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Issakar var det som fekk den fjorde luten, Issakars-sønerne og ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'I landet deira låg Jisre’ela og Kesullot og Sunem');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'og Hafarajim og Sion og Anaharat');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'og Rabbit og Kisjon og Ebes');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'og Remet og En-Gannim og En-Hadda og Bet-Passes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Fylkesdeilet snart innåt Tabor og Sahasuma og Bet-Semes, og enda i Jordan. I alt var der sekstan byar med grender ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Dette var det landet som Issakars-ætti og greinerne hennar fekk til odel og eiga, med byar og bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Den femte luten fall på Assers-ætti og greinerne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'I deira land låg Helkat og Hali og Beten og Aksaf');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'og Allammelek og Amad og Misal. Fylkesdeilet nådde i vest til Karmel og Libnatåi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'i aust tok det leidi til Bet-Dagon og gjekk so nordetter frammed Sebulonsfylket og Jiftaheldalen til Bet-ha-Emek og Ne’iel; sidan heldt det fram på vinstre hand til Kabul');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'og Ebron og Rehob og Hammon og Kana, alt burt til Stor-Sidon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'So vende deilet seg mot Rama, og heldt fram til Tyrusborgi; der ifrå tok det leidi til Hos, og gjekk ut i havet ikkje langt frå Akzib.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma og Afek og Rehob låg og i dette fylket. I alt var der tvo og tjuge byar med grender ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Dette var det landet som Assers-ætti og greinerne hennar fekk til odel og eiga, med byar og bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'På Naftali-sønerne fall den sette luten, på Naftali-sønerne og ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Fylkesdeilet deira gjekk frå Helef, frå Besa’annim-eiki, um Adami-Hannekeb og Jabne’el, heldt fram til Lakkum, og gjekk ut i Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'So vende deilet seg vestetter til Aznot-Tabor, og heldt fram til Hukkok. I sud skifte dei med Sebulon, og i vest med Asser; i aust fylgde skiftelina Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Av faste byar var der: Siddim, Ser og Hammat, Rakkat og Kinneret');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'og Adama og Rama og Hasor');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'og Kedes og Edre’i og En-Hasor');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'og Jiron og Migdal-El, Horem og Bet-Anat og Bet-Semes. I alt var der nittan byar med grender ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Dette var det landet Naftali-ætti og greinerne hennar fekk til odel og eiga med byar og bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'På Dans-ætti og greinerne hennar fall den sjuande luten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'I deira fylkesland låg Sora og Estaol og Ir-Semes');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'og Sa’alabbin og Ajjalon og Jitla');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'og Elon og Timnata og Ekron');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'og Elteke og Gibbeton og Ba’alat');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'og Jehud og Bene-Berak og Gat-Rimmon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'og Me-Hajarkon og Rakkon og bygderne burtmed Joppe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Men Danseiga rakk vidare enn so: Dans-sønerne for nordetter, og tok på Lesem-buarne; dei vann landet deira, og øydde det med odd og egg; sidan lagde dei det under seg og vart buande der; og i staden for Lesem kalla dei bygdi Dan etter ættefaren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Dette var det landet Dans-ætti og greinerne hennar fekk til odel og eiga med byar og bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Då Israels-sønerne vel hadde skift ut heile Kana’ans-landet, so vidt som det var, let dei Josva Nunsson få ei odelseiga millom seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'dei gav honom, etter Herrens bod, den byen han bad um, Timnat-Serah på Efraimsfjellet; og han bygde upp byen, og busette seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Dette var dei odelseigorne som Eleazar, øvstepresten, og Josva Nunsson og hovdingarne yver Israels ætter og ættgreiner luta ut i Silo, for Herrens åsyn i møtetjelddøri. Dermed var dei ferdige med å skifta ut landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Og Herren tala til Josva og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '«Seg til Israels-sønerne at dei skal lata upp dei fredstaderne som eg hadde Moses til å tala til dykk um,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'so den som av vanvare og uviljande hev drepe eit menneskje, kann få røma dit, og desse byarne soleis kann vera dykk til ei trygd mot blodhemnaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Dråpsmannen skal røma til ein av deim; han skal stiga fram i byporten og tala si sak for styresmennerne i byen, og dei skal taka vel imot honom og gjeva honom ein bustad hjå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Når so blodhemnaren kjem etter, skal dei ikkje lata honom få tak i dråpsmannen, so sant det er uviljande han hev drepe ein mann, og han ikkje bar hat til honom frå fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Han skal bu der i byen til han hev stade fram for lyden og fenge sin dom, og so til den øvstepresten som då liver, er avliden; då kann dråpsmannen fara heim att til sin eigen by og til huset sitt, til den byen han laut røma ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Då vigde dei desse byarne til fredstader: Kedes i Galilæa på Naftalifjellet og Sikem på Efraimsfjellet og Kirjat-Arba, som no heiter Hebron, på Judafjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Og austanfor Jordan, som renn frammed Jeriko, let dei upp desse: i Rubensfylket: Beser i øydemarki, på høgsletta; i Gadsfylket: Ramot i Gilead; i Manassefylket: Golan i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Dette var dei byarne som vart kåra til fredstader åt alle Israels-sønerne og åt dei framande som heldt til hjå deim, so den som av vanvare drep eit menneskje, kunde røma dit og ikkje skulde døy for hemnarhand, fyrr han hev stade til doms for lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Medan dei var i Silo i Kana’ans-landet, gjekk ættefederne åt levitarne gjekk fram for Eleazar, øvstepresten, og Josva Nunsson og ættefederne åt Israels-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'og tala soleis til deim: «Moses kom med det bodet frå Herren at me skulde få byar til å bu i, med bumark ikring åt feet vårt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Og Israels-sønerne gjorde som Herren hadde sagt, og gav levitarne av sitt eige land dei byarne me snart skal nemna, med bumarki som låg ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Då dei no drog strå, fall den fyrste luten på Kahats-sønerne; dei levitarne som var ætta frå Aron, øvstepresten, fekk trettan byar hjå Juda-ætti og Simeons-ætti og Benjamins-ætti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'og dei andre Kahats-sønerne fekk for sin lut ti byar hjå Efraims ættgreiner og Dans-ætti og den eine helvti av Manasse-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Gersons-sønerne fekk for sin lut trettan byar hjå Issakars ættgreiner og Assers-ætti og Naftali-ætti og den helvti av Manasse-ætti som var i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merari-borni og ættgreinerne deira fekk tolv byar hjå Rubens-ætti og Gads-ætti og Sebulons-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Desse byarne, med bumarki som høyrde til, gav Israels-sønerne åt levitarne, soleis som Moses hadde sagt dei frå Herren, og let dei draga strå um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'I Judafylket og Simeonsfylket gav dei frå seg dei byarne som me no skal nemna ein for ein:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'det var Arons-sønerne av Levi-ætti, Kahat-greini, som fekk dei; for deim fall den fyrste luten på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Dei gav deim den byen på Judafjellet som heitte etter Arba, ættefaren åt anakitarne, og som me no kallar Hebron, med bumarki som låg rundt ikring;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'men åkerlandet og gardarne som høyrde til byen, gav dei Kaleb Jefunneson til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Dei som var ætta frå Aron, øvstepresten, fekk i desse tvo fylki både Hebron, som var fristad for dråpsmenner, og Libna');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'og Jattir og Estemoa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'og Holon og Debir');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'og Ajin og Jutta og Bet-Semes, ni byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'og i Benjaminsfylket Gibeon og Geba');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'og Anatot og Almon, fire byar, med bumarki som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Soleis fekk Arons-sønerne, prestarne, i alt trettan byar med bumark attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'No skal me nemna dei byarne som fall på dei andre Kahats-sønerne, dei levitiske Kahats-ætterne: Dei fekk i Efraimsfylket');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Sikem, som var fristad for dråpsmenner, på Efraimsfjellet, og Gezer');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'og Kibsajim og Bet-Horon, fire byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'og i Dansfylket Elteke og Gibbeton');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'og Ajjalon og Gat-Rimmon, fire byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'og i det eine halve Manassefylket Ta’anak og Gat-Rimmon, tvo byar, med bumarki som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Det var i alt ti byar med bumark attåt som dei hine greinerne av Kahats-ætti fekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Levitarne av Gersons-greini fekk i det andre halve Manassefylket Golan i Basan, ein av fristaderne for dråpsmenner, og Be’estera, tvo byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'og i Issakarsfylket Kisjon og Daberat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut og En-Gannim, fire byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'og i Assersfylket Misal og Abdon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'og Helkat og Rehob, fire byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'og i Naftalifylket Kedes i Galilæa, ein av fristaderne for dråpsmenner, og Hammot-Dor og Kartan, tri byar, med bumarki som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Soleis fekk gersonitarne og ættgreinerne deira i alt trettan byar med bumark attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Dei som var att av levitarne, Merari-sønerne og ættgreinerne deira, fekk i Sebulonsfylket Jokneam og Karta');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'og Dimna og Nahalal, fire byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'og i Rubensfylket Beser og Jahsa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot og Mefa’at, fire byar, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'og i Gadsfylket Ramot i Gilead, ein av fristaderne for dråpsmenner, og Mahanajim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'og Hesbon og Jaser, fire byar, med bumarki som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Det var i alt tolv byar som fall på dei siste Levi-ætterne, Merari-sønerne og ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Alt i alt fekk levitarne i odelslandet åt Israels-sønerne åtte og fyrti byar, med bumark attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Desse byarne hadde kvar si bumark ikring seg; so var det med deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Soleis gav Herren Israel heile det landet som han hadde lova at han vilde gjeva federne deira, og dei eigna det til seg og vart buande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Og Herren let deim hava fred på alle leder, heiltupp soleis som han hadde lova federne deira. Ingen av alle uvenerne deira kunde standa seg imot deim; Herren gav alle fiendar i deira hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ikkje eit einaste av alle dei gode ordi Herren hadde tala til Israels hus, vart um inkje; alt saman gjekk fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Då kalla Josva til seg rubenitarne og gaditarne og helvti av Manasse-ætti');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'og sagde til deim: «De hev gjort alt det Moses, Herrens tenar, sagde med dykk, og meg hev de og lydt i alt eg hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'I heile denne lange tidi hev de ikkje vike frå brørne dykkar; de hev halde dykk trutt etter det som Herren, dykkar Gud, sagde fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Og no hev Herren, dykkar Gud, late brørne dykkar koma til ro, som han hadde lova deim; far no de heim att til tjeldbuderne dykkar, åt dykkar eige land, det som Moses, Herrens tenar, gav dykk på hi sida Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Men kom vel i hug å leva etter dei bodi og den lovi som Moses, Herrens tenar, lærde dykk, at de skal elska Herren, dykkar Gud, og all tid ganga på hans vegar, og halda bodi hans, og vera trugne imot honom, og tena honom av heile dykkar hjarta og all dykkar hug!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'So lyste Josva velsigning yver deim, og bad deim vel liva, og dei for heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Den eine helvti av Manasse-ætti hadde fenge land i Basan av Moses, og den andre helvti hadde Josva gjeve land vestanfor Jordan, saman med brørne deira. Som no Josva gav deim heimlov og velsigna deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'sagde han og til deim: «No fer de heim att med mange eignaluter og ovmykje bufe, med sylv og gull og kopar og jarn og ovmange klæde. Byt no med brørne dykkar det herfanget de hev teke frå fienden!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'So tok dei då på heimvegen, Rubens-sønerne og Gads-sønerne og helvti av Manasse-ætti; dei skildest med dei andre Israels-sønerne og for frå Silo i Kana’ans-landet attende til Gilead, sitt eige land, der dei hadde fenge seg bustad, soleis som Moses hadde lova deim frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Men då dei kom til dei steinkrinsarne som er attmed Jordan, i Kana’ans-landet, sette dei upp eit altar der, attmed Jordan, eit stort og sjålegt altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Då fekk Israels-sønerne høyra at folk sagde: «Sjå, Rubens-sønerne og Gads-sønerne og helvti av Manasse-ætti hev sett upp eit altar burtmed Jordankrinsarne, fremst i Kana’ans-landet, på den sida som høyrer til Israels-sønerne;»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'og då Israels-sønerne høyrde det, samla heile lyden seg i Silo, og vilde fara imot deim med ufred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Men fyrst sende dei Pinehas, son åt Eleazar, øvstepresten, til Gileadlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'og saman med honom ti fyrstar, som var or kvar sitt fylke i Israel og hovdinger yver kvar si grein av Israels-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Då so dei kom til Gileadlandet og fann Rubens-sønerne og Gads-sønerne og helvti av Manasse-ætti, tala dei soleis til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '«So segjer heile Herrens lyd: «Kva er dette for svik de no hev gjort mot Israels Gud, med di de no hev vendt dykk burt ifrå Herren og bygt dykk eit altar? Kvifor hev de no sett dykk upp imot Herren?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Var det’kje nok med det brotet me gjorde då me heldt oss til Peor, so ulukka kom yver Herrens lyd? Det brotet hev me endå ikkje reinsa oss frå,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'og so vender de dykk no burt frå Herren! Men set de dykk i dag upp imot Herren, so fær heile Israel i morgon kjenna hans vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Eller tykkjer de det er ureint det landet de hev fenge til eigedom, so kom berre yver til Herrens eige land, der som Herrens hus stend, og få dykk ein bustad millom oss, men set dykk ikkje upp imot Herren, og set dykk ikkje upp imot oss, med di de byggjer dykk eit altar umfram altaret åt Herren, vår Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'For ikkje Akan Zerahsson og med svik då han tok av det som var vigt! Då råma vreiden heile Israels-lyden, og han var ikkje den einaste som laut døy for det brotet han hadde gjort.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Då tok Rubens-sønerne og Gads-sønerne og halve Manasse-ætti til ords og tala so til hovdingarne yver Israels-ætterne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '«Herren, den allvelduge Gud, veit det, ja Herren, den allvelduge Gud, han veit det, og Israel skal vita det, at det ikkje var i tråss og utruskap mot Herren');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'me bygde oss eit altar, og ikkje på den måten at me vilde venda oss burt frå Herren; var det det, so gjev du ikkje vilde hjelpa oss i dag! Ikkje heller var altaret bygt til å ofra brennoffer eller grjonoffer eller bera fram takkoffer på; var det so, då hemne Herren sjølv seg på oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Men det var ein ting me var rædde, difor gjorde me dette: me tenkte borni dykkar ein gong kunde koma til å segja til våre born: «Kva hev de å gjera med Herren, Israels Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Hev’kje Herren sett eit skilmerke, Jordan, millom oss og dykk, de Rubens-søner og Gads-søner! De eig ikkje med i Herren.» Soleis kunde borni dykkar få våre born til å halda upp med å ottast Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'So kom me på at me vilde byggja dette altaret, ikkje til brennoffer eller slagtoffer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'men det skulde vera eit vitne millom oss og dykk og millom dei ætterne som kjem etter oss, at me vil tena Herren for hans åsyn med brennofferi og slagtofferi og takkofferi våre, so ikkje borni dykkar ein gong skal segja til våre born: «De eig ikkje med i Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Skulde dei nokosinne segja sovore med oss eller etterkomararne våre, tenkte me, so vil me svara: «Sjå på det likjendet av Herrens altar som federne våre hev gjort, ikkje til å ofra brennoffer eller slagtoffer på, men til eit vitne millom oss og dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Aldri kunde det sviva oss i hugen at me no vilde setja oss upp imot Herren og venda oss burt ifrå honom og byggja noko altar til brennoffer eller grjonoffer eller slagtoffer umfram det altaret som stend framfor huset åt Herren, vår Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Då Pinehas, presten, og styresmennerne for lyden, og hovdingarne yver Israels-ætterne, som var med honom, høyrde kva Rubens-sønerne og Gads-sønerne og Manasse-sønerne sagde, lika dei det vel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'og Pinehas, son åt Eleazar, øvstepresten, sagde til Rubens-sønerne og Gads-sønerne og Manasse-sønerne: «No kann me skyna at Herren er midt imillom oss, sidan de ikkje hev gjort dette sviket imot honom; dermed hev de berga Israels-sønerne or Herrens vald.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'So skildest Pinehas Eleazarsson og hovdingarne med Rubens-sønerne og Gads-sønerne, og for frå Gileadlandet heim att til Kana’ans-landet, til Israels-sønerne, og sagde frå kva svar dei hadde fenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Og Israels-sønerne tykte godt um svaret; dei takka Gud og tenkte ikkje lenger på å taka ut i strid mot Rubens-sønerne og Gads-sønerne og øyda landet dei budde i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Men Rubens-sønerne og Gads-sønerne kalla det altaret Vitne: «Eit vitne», sagde dei, «skal det vere imillom at Herren er den sanne Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Då lang tid var lidi, og Herren hadde late Israel få fred for alle fiendar rundt ikring, og Josva var gamall vorten og ut i åri komen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'då kalla Josva i hop heile Israel, styresmennerne og hovdingarne og domarane og formennerne deira, og sagde med deim: No er eg gamall og langt fram i åri;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'og de hev sjølve set alt det Herren hev gjort med alle dei folki som laut røma for dykk; for det var Herren, dykkar Gud, som stridde for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Dei veit eg hev luta ut åt dykk, ætt for ætt, dei riki som endå er att, og like eins alle deim eg hev lagt i øyde, frå Jordan og til Storhavet der soli gjeng ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Herren, dykkar Gud, skal sjølv støyta desse folki ut og driva deim burt for dykk, og de skal få eigna til dykk landet deira, soleis som Herren, dykkar Gud, hev lova dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'So ver no urikkeleg støde til å halda og gjera alt det som er skrive i lovboki åt Moses! Vik aldri av ifrå det, korkje til høgre eller vinstre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Gjev dykk ikkje i lag med desse folki, deim som er att hjå dykk! Tak ikkje namnet åt gudarne deira på tunga, sver ikkje ved deim, ten deim ikkje, og bed ikkje til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'men haldt fast ved Herren dykkar Gud, soleis som de hev gjort til denne dag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Difor dreiv Herren ut for dykk store og sterke folkeslag, og ingen hev til dessa vore god til å standa seg mot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Ein einaste av dykk kunde jaga tusund; for det var Herren, dykkar Gud, som stridde for dykk, soleis som han hadde lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'So agta no vel på dykk sjølve, so sant de hev livet kjært, og elska Herren, dykkar Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'For fell de ifrå, og held lag med dei folki som endå er att hjå dykk, og de gifter born i hop og blandar dykk med kvarandre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'so skal de vita for visst at Herren, dykkar Gud, aldri vil driva desse folki ut for dykk; men dei skal verta til ei snara og ei fella for dykk, og til ei svipa yver ryggen og tornar i augo dykkar, til dess de vert utrudde or dette gilde landet som Herren, dykkar Gud, hev gjeve dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'No fer eg snart den vegen alt her på jordi lyt fara. Kom då i hug, og lat det aldri ganga dykk or minne, at ikkje eit einaste av alle dei gode ordi som Herren, dykkar Gud, hev lyst yver dykk, hev vorte um inkje; alt hev gjenge fram; aldri eit ord hev vorte um inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Men liksom det hev gjenge etter alle dei gode ordi som Herren, dykkar Gud, hev tala til dykk, soleis skal Herren lata alt det vonde han hev truga med koma yver dykk, til han hev rudt dykk ut or dette gilde landet som han hev gjeve dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Bryt de sambandet med Herren, dykkar Gud, det som han hev sagt at det skal halda, og gjeng de av og tener andre gudar og bed til deim, då skal Herrens harm loga imot dykk, og de skal vonom snøggare verta utrudde or det gilde landet han hev gjeve dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'So samla Josva alle Israels-ætterne i Sikem, og kalla til seg styresmennerne i Israel og hovdingarne og domarane og formennerne deira, og dei steig fram for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Då tala Josva soleis til heile lyden: «So segjer Herren, Israels Gud: «På hi sida Storelvi budde i gamle dagar federne dykkar, millom deim Tarah, far åt Abraham og Nahor, og dei tente framande gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Og eg henta Abraham, ættefaren dykkar, frå hi sida åt elvi og førde honom ikring i heile Kana’ans-landet; og eg auka ætti hans, og gav honom Isak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Og Isak gav eg Jakob og Esau: Esau let eg få Se’irfjellet til eigedom, men Jakob og sønerne hans for ned til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Sidan sende eg Moses og Aron, og heimsøkte egyptarane med dei plågorne de veit, og so førde eg dykk ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Då eg no førde federne dykkar ut or Egyptarland, kom de til sjøen; men egyptarane sette etter deim til Sevhavet med vogner og hestfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Då ropa dei til Herren, og han sende eit tett myrker millom dykk og egyptarane, og let havet slå i hop yver deim og grava deim ned. Med eigne augo såg de kva eg gjorde i Egyptarland. Sidan var de lenge i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'So førde eg dykk inn til landet åt amoritarne, som budde austanfor Jordan, og dei stridde mot dykk, men eg gav deim i dykkar hender; de eigna til dykk landet deira, og eg rudde deim ut for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Balak Sipporsson, kongen i Moab, budde seg til strid og tok på Israel; han sende bod på Bileam Beorsson, og bad honom lysa våbøn yver dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'men eg vilde ikkje lyda etter Bileam, og han laut velsigna dykk; soleis berga eg dykk ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'So for de yver Jordan, og kom til Jeriko, og Jeriko-buarne stridde mot dykk, og det same gjorde amoritarne og perizitarne og kananitarne og hetitarne og girgasitarne, hevitarne og jebusitarne; men eg gav deim i dykkar hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Ein kvefsesvarm sende eg fyre dykk, og dei støkte deim burt for dykk, liksom båe amoritarkongarne; det var ikkje med sverdet ditt eller bogen du dreiv deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Eg gav dykk eit land som du ikkje hev havt noko stræv med, og byar som ikkje de hev bygt, og der sette de dykk ned; de et av vinhagar som de ikkje sjølve hev stelt til, og av oljetre som de ikkje hev sett.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'So ber då age for Herren og ten honom ærleg og trufast! Skil dykk av med dei gudarne som federne dykkar dyrka på hi sida Storelvi og i Egyptarland, og ten Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Men hev de ikkje hug til å tena Herren, so vel i dag kven de vil tena, anten dei gudarne som federne dykkar austanfor Storelvi tente, eller gudarne åt amoritarne, som åtte det landet de bur i! Men eg og mitt hus me vil tena Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Då svara folket so: «Å, nei, aldri kunde me koma på slikt som å falla frå Herren og tena andre gudar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'For Herren er vår Gud! Han var det som førde oss og federne våre ut or Egyptarlandet, or slavehuset, og som gjorde desse store teikni for augo våre, og vara oss på heile den vegen me for og millom alle dei folkeslagi me laut framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Herren var det som dreiv burt for oss amoritarne som budde her i landet, og alle dei andre folki. Me og vil tena Herren; for han er vår Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, '«De er ikkje god til å tena Herren,» sagde Josva, «for han er ein heilag Gud; ein streng Gud er han; han vil ikkje hava tol med broti og synderne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Fell de frå Herren og tener framande gudar, då kjem han til å taka ei onnor leid, og lata det ganga dykk ille og gjera ende på dykk, kor mykje godt han fyrr hev gjort dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, '«Jau, me vil tena Herren,» svara folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Då sagde Josva til folket: «So vitnar de då mot dykk sjølve at de hev valt Herren og vil tena honom.» «Ja, det vitnar me,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '«Hav då burt dei framande gudarne som er hjå dykk,» sagde Josva, «og bøyg hjarta dykkar innåt Herren, Israels Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Og folket svara: «Ja, Herren, vår Gud, vil me tena, og hans ord vil me lyda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Den dagen gjorde Josva ei pakt med folket. Der i Sikem sette han deim lov og rett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'og skreiv alt upp i Guds lovbok. So tok han ein stor stein og reiste upp under ei eik som stend frammed heilagdomen åt Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'og tala soleis til heile folket: «Denne steinen skal vera vitne imot oss, han hev høyrt kvart ord som Herren hev tala med oss, og han skal vera vitne mot dykk, so de ikkje gløymer Herren, dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'So bad Josva farvel med folket, og dei for heim att, kvar til sin eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Ei tid etter dette hadde hendt, andast Josva Nunsson, Herrens tenar; han var då hundrad og ti år gamall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Han vart gravlagd på sin eigen gard og grunn, i Timnat-Serah på Efraimsheidi, nordanfor Ga’asfjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Israel tente Herren so lenge Josva var til, og so lenge dei gamle var til som livde etter Josva og kjende til alt det som Herren hadde gjort for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Beini åt Josef, som Israels-sønerne hadde ført med seg frå Egyptarland, gravla dei attmed Sikem, på den marki som Jakob hadde kjøpt av sønerne åt Hemor, far hans Sikem, for hundrad gullpenger, og som Josefs-borni hadde fenge til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Sidan døydde Eleazar, son åt Aron, og vart gravlagd i Gibea på Efraimsheidi, ein by som hadde vorte gjeven åt Pinehas, son hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Då Josva var avliden, spurde Israels-sønerne Herren: «Kven av oss skal taka fyrst ut i striden mot kananitarne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Og Herren svara: «Juda skal taka ut. No gjev eg landet i hans hender!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Då sagde Juda med Simeon, bror sin: «Ver med meg til min lut, og lat oss båe strida mot kananitarne, so skal eg vera med deg til din lut.» Og Simeon vart med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'So tok Juda-sønerne ut, og Herren gav kananitarne og perizitarne i henderne deira; dei slo deim i Bezek og felte ti tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'I Bezek møtte dei Adoni-Bezek, og dei stridde mot honom og slo kananitarne og perizitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Adoni-Bezek rømde; men dei sette etter honom, og tok honom og hogg av honom tumarsfingrarne og stortærne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Då sagde han: «Sytti kongar med avhogne tumarsfingrar og stortær sanka smular under mitt bord. No hev Gud gjeve meg like for det eg gjorde!» So førde dei honom til Jerusalem, og der døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Juda-sønerne kringsette Jerusalem, og tok byen, og øydde honom med odd og egg, og sette eld i husi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Sidan for dei ned og stridde mot dei kananitarne som budde i fjell-landet og i Sudlandet og i låglandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Fyrst gjekk dei mot kananitarne som budde i Hebron - Hebron heitte fyrr i tidi Kirjat-Arba - og dei slo Sesai og Ahiman og Talmai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'So gjekk dei mot Debir-buarne. - Debir heitte fyrr i tidi Kirjat-Sefer -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Då sagde Kaleb: «Den som kann taka Kirjat-Sefer, skal få Aksa, dotter mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Otniel, son åt Kenaz, Kalebs yngre bror, tok byen, og fekk Aksa, dotter hans Kaleb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Då so ho skulde flytja heim til honom, eggja ho honom til å beda far hennar um ein jordveg, og sjølv hoppa ho ned av asnet. «Kva er det du vil?» spurde Kaleb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, '«Lat meg få ei velfargåva!» svara ho. «Du hev gift meg burt til dette turre Sudlandet; gjev meg no vatskjeldor!» So gav han henne Øvregullot og Nedregullot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Etterkomarane etter keniten, verbror åt Moses, for med Juda-sønerne frå Palmestaden upp til Judaheidi som ligg sunnanfor Arad, og vart buande der saman med folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Sidan gjekk Juda med Simeon, bror sin, og dei vann yver kananitarne som budde i Sefat. Dei bannstøytte byen; difor heitar han no Horma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Og Juda-mennerne tok Gaza og Askalon og Ekron med alt landet som låg til dei byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Herren var med Juda-sønerne, og dei lagde under seg fjellbygderne; men dei var ikkje god til å driva ut slettebuararne; for dei hadde jarnvogner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Dei gav Hebron til Kaleb, som Moses hadde sagt, og han dreiv dei tri Anaks-sønerne ut or bygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Benjamins-sønerne dreiv ikkje ut jebusitarne som budde i Jerusalem; jebusitarne vart buande i Jerusalem saman med Benjamins-sønerne og hev butt der til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Josefs-ætti tok og ut i striden; dei gjekk mot Betel, og Herren var med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Då dei låg på vakt kring Betel - den byen heitte fyrr i tidi Luz -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'fekk spæjarane deira sjå ein mann som kom ut or byen. Og dei sagde til honom: «Kjære, syn oss kvar me kann koma inn i byen, so skal me gjera vel mot deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'So synte han dei kvar dei kunde koma inn, og dei øydde byen med odd og egg, men mannen og heile ætti hans let dei fara sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Han for til Hetitarlandet, og bygde ein by; den kalla han Luz, og det namnet hev byen havt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manasse øydde ikkje Bet-Sean og Ta’anak og Dor og Jibleam og Megiddo og bygderne som låg under dei byarne, og kananitarne var god til å halda seg der i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Då Israels-folket vart sterkare, tvinga dei kananitarne til å træla for seg, men dreiv deim ut gjorde dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Efraim dreiv ikkje ut kananitarne som budde i Gezer; kananitarne vart buande millom Efraims-sønerne i Gezer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon dreiv ikkje ut deim som budde i Kitron og i Nahalol; kananitarne vart buande millom Sebulons-sønerne, men laut gjera trælearbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser dreiv ikkje ut dei som budde i Akko og i Sidon, og øydde ikkje Ahlab og Akzib og Helba og Afik og Rehob;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'asseritarne busette seg millom kananitarne som åtte heime i landet, og dreiv deim ikkje ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naftali-sønerne dreiv ikkje ut deim som budde i Bet-Semes og i Bet-Anat; dei busette seg millom kananitarne som åtte heime i landet. Men folket i Bet-Semes og Bet-Anat laut træla for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amoritarne trengde Dans-sønerne upp i fjelli, og let deim ikkje få koma ned på sletta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Sjølve var dei god til å halda seg i Har-Heres og i Ajjalon og Sa’albim, men sidan fekk Josefs-ætti yvertaket, og nøydde deim til å træla for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Landskilet åt amoritarne gjekk frå Skorpionskardet um Knausen og uppetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Herrens engel kom frå Gilgal upp til Bokim og sagde: «Eg henta dykk ut or Egyptarland, og fylgde dykk til det landet eg lova federne dykkar, og eg sagde: «Aldri i verdi skal eg brjota mi pakt med dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'og de skal ikkje gjera samband med deim som bur her i landet; de skal riva ned altari deira!» Men de høyrde ikkje på ordi mine. Kvi gjorde de’kje det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'So segjer eg dykk: Eg vil ikkje driva deim burt for dykk; dei skal vera til broddar i sidorne dykkar, og gudarne deira skal verta ei snara for dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Soleis tala Herrens engel til alle Israels-sønerne. Då gret folket høgt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'difor kalla dei den staden Bokim. Der ofra deim til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Då Josva hadde bede farvel med folket, og Israels-sønerne var farne heim, kvar til sin odel, for å eigna til seg landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'då tente folket Herren so lenge Josva var til, og so lenge dei gamle var til, som livde etter Josva, og hadde set alle dei storverk Herren hadde gjort for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Men då Josva Nunsson, Herrens tenar, var slokna, hundrad og ti år gamall,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'og dei hadde gravlagt honom på hans eigen gard og grunn i Timnat-Heres i Efraimsheidi, nordanfor Ga’asfjell,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'og då heile den ætti var fari til federne sine, og det stod fram ei ny ætt, som ikkje kjende Herren og ikkje visste kva han hadde gjort for Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'då gjorde Israels-sønerne det som var Herrens imot, og dyrka Ba’als-bilæti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'dei vende seg frå Herren, sin fedregud, som hadde ført deim ut or Egyptarlandet, og heldt seg til andre gudar, gudarne åt grannefolki, og låg på kne for deim, og arga Herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'dei vende seg frå Herren og dyrka Ba’al og Astarte-bilæti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Då vart Herren brennande harm på Israel, og gav deim i henderne på røvarar, som herja deim; han slepte deim i henderne på uvenerne deira rundt um, og dei kunde ikkje lenger standa seg mot fiendarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Kvar dei for fram, var Herrens hand imot deim, so det gjekk deim ille, som Herren hadde sagt deim, og som Herren hadde svore, og dei kom i stor naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Då vekte Herren upp domarar, som berga deim frå røvararne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Men dei lydde ikkje domarane sine heller, og heldt seg med andre gudar, og låg på kne for deim; dei tok snart ut av den vegen som federne deira hadde fylgt; for dei lydde Herrens bod, men so gjorde ikkje desse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Og kvar gong Herren let ein domar standa fram millom deim, so var Herren med domaren, og berga deim frå uvenerne deira so lenge domaren livde; for Herren ynkast yver deim når dei sukka og stunde for di dei vart tvinga og trælka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Men ikkje fyrr var domaren burte, fyrr dei fall ifrå att, og for endå verre åt enn federne sine, heldt seg til andre gudar, og dyrka deim, og bad til deim; dei lagde’kje ned noko av det vonde dei hadde fyre seg, eller av si tråssuge framferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Då vart Herren harm på Israel, og han sagde: «For di dette folket hev brote den pakti eg gjorde med federne deira, og ikkje hev lydt mine ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'so vil ikkje eg heller hjelpa deim meir, og ikkje driva ut noko av dei folki som Josva let vera att då han døydde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'med deim skal Israel røynast um dei vilde halda seg etter Herrens vegar og ganga på deim, som federne deira gjorde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Soleis var det Herren let desse folki få vera, og ikkje straks dreiv deim ut, og ikkje gav deim i Josvas hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'No skal me nemna dei folki som Herren let vera att til å røyna Israel med - dei Israels-mennerne som ikkje hadde vore med i nokon av Kana’ans-krigarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'berre av di han vilde dei komande Israels-ætter skulde få vit på å strida, og vilde læra deim det, deim som ikkje kunde det fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Det var dei fem filistarfyrstarne og alle kananitarne og sidonarane og hevitarne som budde på Libanonfjelli, frå Ba’al-Hermonfjellet til Hamatvegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Deim var det Israel skulde røynast med, so det kunde syna seg um dei vilde lyda Herrens bod, som Moses hadde kunngjort federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'So budde no Israels-sønerne midt ibland kananitarne og hetitarne og amoritarne og perizitarne og hevitarne og jebusitarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'dei tok døtterne deira til konor og gav døtterne sine til sønerne deira, og dyrka gudarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Israels-sønerne gjorde det som var Herren imot; dei gløymde Herren, sin Gud, og dyrka Ba’als- og Astarte-bilæti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Då vart Herren brennande harm på Israels-sønerne; han slepte deim i henderne på Kusan-Risatajim, kongen i Aram-Naharajim, og Israel laut tena Kusan-Risatajim i åtte år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Då ropa Israels-sønerne til Herren, og Herren let ein hjelparmann standa fram hjå deim og hjelpa deim; det var Otniel, son åt Kenaz, Kalebs yngre bror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Herrens Ande kom yver honom, og han tok styringi i Israel. So drog han ut i striden, og Herren gav Kusan-Risatajim, Aram-kongen, i henderne hans; han vann yver Kusan-Risatajim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'og sidan hadde landet fred i fyrti år. So døydde Otniel, son åt Kenaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Men Israels-sønerne gjorde på nytt det som var Herren imot, og Herren gav Eglon, Moabs-kongen, magt yver deim, for di dei gjorde det som var Herren imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Eglon fekk med seg Ammons-sønerne og amalekitarne; so drog han ut, og slo Israel, og dei tok Palmestaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Israels-sønerne laut tena Eglon, Moabs-kongen, i attan år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Då ropa dei til Herren, og Herren sende dei ein hjelpar, Ehud Gerason av Benjamins-ætti, ein keivhendt mann. Israels-sønerne sende Ehud med gåvor til Eglon, kongen i Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Då gjorde han seg eit sverd som var tvieggja og ei aln langt, og spente det på seg under klædi sine, på høgre sida;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'so førde han gåvorne fram til Eglon, Moabs-kongen. Eglon var ein ovtjukk mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Då Ehud hadde greidt frå seg gåvorne, let han folki som hadde bore deim fara heim att;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'men sjølv snudde han um ved gudebilæti som stod innmed Gilgal, og for attende og sagde: «Eg hev eit løyndarbod til deg, konge!» «Hyss,» sagde kongen: Då gjekk dei ut alle deim som stod kringom honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Som han no sat åleine i den svale høgstova si, gjekk Ehud fram for honom og sagde: «Eg hev eit bod til deg frå Gud!» Då reiste han seg av stolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Og Ehud rette ut vinstre handi, og greip sverdet han bar ved høgre sida, og rende det i livet på honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'so handtaket for med inn etter bladet; og feittet gjekk i hop att kring bladet; for han drog ikkje sverdet ut att or livet hans. So gjekk han ut i svali.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Då Ehud var komen ut i svalgangen, let han høgelofts-døri att etter seg, og stengde henne vel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'og so gjekk han sin veg. Straks etter kom tenarane, men då dei såg at døri var læst, sagde dei: «Han er visst for seg sjølv i svalkammerset!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Dei venta til dei var reint leide av seg; men han let ikkje upp døri til høgeloftet. So tok dei lykelen, og let upp; då fekk dei sjå at herren deira låg livlaus på golvet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Medan dei tøvra, slapp Ehud undan, og for framum gudebilæti, og nådde Se’ira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Då han kom til Efraimsheidi, bles han i luren; då for Israels-sønerne med han ned av heidi, og han gjekk fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, '«Skunda dykk etter meg!» sagde han: «For Herren hev gjeve fiendarne, moabitarne, i henderne dykkar.» So fylgde dei honom ned til Jordan, og stengde vadi for moabitarne, og let ingen sleppa yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Den gongen felte dei ikring ti tusund moabitar, som alle var sterke og djerve menner; ikkje ein kom seg undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Moab laut den dagen bøygja seg under Israels velde, og sidan hadde landet fred i åtteti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Etter Ehud kom Samgar, son åt Anat. Han felte seks hundrad mann av filistarane, med piggstaven som han dreiv uksarne med; han og berga Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Då Ehud var burte, gjorde Israels-sønerne atter det som var Herren imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Då slepte han deim i henderne på Jabin, kananitarkongen. Jabin hadde kongssætet sitt i Hasor. Hovdingen yver heren hans heitte Sisera; han budde i Haroset-Haggojim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Og Israels-sønerne ropa til Herren; for Sisera hadde ni hundrad jarnvogner, og han trengde Israels-sønerne hardt i tjuge år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'I den tidi var Debora, kona åt Lappidot, domar i Israel. Ho var ei viskona,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'og sat jamleg under eit palmetre millom Rama og Betel på Efraimsheidi - det treet vart heitande Deborapalma - og Israels-sønerne kom upp til henne, so ho skulde skifta rett millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Ho sende bod etter Barak, son åt Abinoam, frå Kedes i Naftalifylket, og sagde med honom: «Høyr no kva Herren, Israels Gud, segjer til deg: «Tak ut, og drag upp på Taborfjellet, og hav med deg ti tusund mann av Naftali- og Sebulons-ætterne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Og eg skal draga Sisera, hovdingen yver Jabins-heren, burtåt deg til Kisonåi med vognerne og heile horgi hans, og gjeva honom i dine hender.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Då svara Barak: «Gjeng du med meg, so skal eg taka ut, men gjeng du ikkje med, so gjeng ikkje eg heller.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, '«Visst skal eg ganga med deg,» sagde Debora, «men då fær ikkje du æra for den ferdi du tek ut på; for Herren skal gjeva Sisera i kvendehand.» So gjorde ho seg reidug og vart med Barak til Kedes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Og Barak stemnde Sebulon og Naftali i hop til Kedes; ti tusund mann fylgde etter honom, og Debora var med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Den gongen hadde Heber, ein av kenitarne, som var ætta frå Hobab, verbror åt Moses, skilt lag med ætti si, og no flutte han med tjeldbuderne sine alt burt til Besa’annim-eiki som stend innmed Kedes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Då Sisera fekk spurt at Barak Abinoamsson var faren upp på Taborfjellet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'baud han ut stridsmagti si, og for med alle vognerne sine, ni hundrad jarnvogner, og alt folket han hadde med seg, frå Haroset-Haggojim til Kisonåi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Då sagde Debora til Barak: «Kom no! For i dag vil Herren gjeva Sisera i dine hender. Veit du’kje at Herren gjeng fyre deg i striden?» So for Barak ned av Taborfjellet, og det fylgde honom ti tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Og Herren sette ein støkk i Sisera og alle vognkjemporne og heile heren hans, so dei ikkje kunde standa seg for Barak og sverdet hans; då steig Sisera ned av vogni, og rømde på sin fot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Men Barak elte vognerne og heren alt til Haroset-Haggojim, og heile Sisera-heren fall for sverdet; det vart’kje att ein einaste mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisera rømde på sin fot til tjeldbudi hennar Jael, kona åt Heber, keniten; for det var fred millom Jabin, Hasor-kongen, og ætti åt Heber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Og Jael gjekk ut imot Sisera, og sagde: «Kom inn, herre, kom inn til meg! Du tarv ikkje vera rædd!» Då gjekk han inn i tjeldbudi til henne, og ho gøymde honom under felden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'So sagde han: «Kjære væne, gjev meg litt vatn! Eg er tyrst.» Då opna ho mjølkeflaska og gav honom drikka og breidde på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Og han sagde til henne: «Statt i budøri, og kjem det einkvar og spør deg um her er nokon, so seg: Nei!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Då var det Jael, kona åt Heber, tok ein tjeldnagle, og gjekk stilt inn til Sisera med hamaren i handi, og med han, trøytt som han var, låg i fastaste svevnen, slo ho naglen gjenom tunnvangen hans, so han gjekk ned i jordi. Soleis døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'I same bilet kom Barak og søkte etter Sisera. Då gjekk Jael ut imot honom og sagde: «Kom, so skal eg syna deg den mannen du leitar etter!» So gjekk han inn til henne, og då fekk han sjå at Sisera låg livlaus på jordi, med naglen gjenom tunnvangen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Den dagen bøygde Gud Jabin i kne for Israel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'og Israels hand låg tyngre og tyngre på Jabin, Kana’ans-kongen, til dei reint gjorde ende på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Den gongen song Debora og Barak Abinoamsson dette kvædet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '«For fyrstarn’ fyrst i striden gjekk, og folket viljugt møtte fram, pris Herren, Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Høyr kongar! Hovdingar, gjev gaum! For Herren eg eit kvæde kved. For Herren, Gud åt Israel, ein song eg syngja vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Då, Herre, du frå Se’ir for, frå Edomsflyerne skreid fram. Då ristest jordi, himlen draup, regnet or skyi raut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'For Herrens åsyn fjelli skalv - sjå Sinaifjellet der, det skalv for han, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'I Samgars, Anats-sonens old. Og Jaels, vegarn’ aude var, og ferdamennern’ fara laut på krokut fjellstig fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Ein førar fattast Israel, ein førar, alt til du steig fram, til du steig fram, Debora, som ei mor i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Gud valde nye styrarar; då stod det strid i portarne: Ein såg’kje skjold og ikkje spjot hjå fyrti tusund hermenn i heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Hjå hovdingarn’ i Israel er hugen min, hjå Herren som friviljug møtte fram til strid! Lov Herren, Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'De som på gulblakk gangar rid, på høgjende i stova sit, og etter jamne vegen gjeng, røyst i, og syng ein song!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Syng høgt som bogeskyttararn’ når dei ved brunnen sit og kved! Der prisar dei Guds vise verk, kor vist han førde Israel. Den gongen Herrens eige folk til portarne for ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Vakn upp, vakn upp, Debora, vakn upp, eit kvæde kved! Statt upp, Barak, før fangarn’ burt, son åt Abinoam!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Då for ein hop til fyrstarn’ ned Med kjemporn’ Herrens folk steig ned:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Av deg, Efraim, dei som fyrst rot feste på Amaleksfjell. Og etter deg kom Benjamins flokk med folki dine fylgje heldt; av Makir styresmenn steig ned, og ifrå Sebulon dei som gjeng fram med førarstav i hand;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'dei fyrstar av Issakar i fylgje med Debora kom, og Barak - i hans fotfar flaug dei i dalen ned. Ved Rubensbekkjerne dei tok i tankar so raust ei råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Kvi vart du sitjande i ro på kvii di og lydde på med hjuringarn’ i fløyta let? - Ved Rubensbekkjerne dei la i tankarn’ lenge råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead, burtum Jordanå gjev han seg roleg til, og Dan kvi drygjer han der skutorn’ ligg? Ved sjøsidi sit Asser still, i hamni held han seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Men Sebulon, det er ein lyd som lite vyrder livet sitt, og like eins Naftali, han som på høge heider bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Då kom kongarn’ og stridde, kananitarkongarn’ stridde i Tana’ak, ved Megiddovatnet; sylv vann dei visst ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Ned frå himlen stjernorn’ stridde frå dei høge skeidi sine imot Sisera dei stridde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Kisonåi burt deim førde. Åi fræg frå forne dagar - Kisonåi! Stig fram, mi ånd, med styrk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Hardt slo hestehovarn’ i marki, med kjemporne køyrde, køyrde av stad i strjukande tan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '«Bann Meroz,» Herrens engel sa, «bann deim som bur der, bann deim burt! Dei kom’kje Herrens her til hjelp. Dei hjelpte ikkje kjemporn’ hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Velsigna ver i kvendeflokk Jael, Hebers, kenitens, viv! Framum kvar kvinna som i buder bur, velsigna vere ho!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Vatn bad han um, mjølk gav ho han; i briki skål baud ho han skyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Med vinstre hand ho naglen triv, med høgre smidjehamaren; i hausen Sisera ho slog, og hamra hovudet hans sund, tunnvangen hans slo ho i knas, og naglen tvert igjenom dreiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'For føtern’ hennar seig han ned, fram stupt’ han, og på jordi låg; for føtern’ hennar seig han ned; der han seig ned der låg han - daud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Gjenom vindauga ser ho, Siseras mor, gjenom glaset glor ho, og kvin: «Kva ventar vogni hans etter? Kvi tøvrar tråvaran’ hans?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Svarar dei klokaste fruorne hennar, og sjølv og gjev ho seg svar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '«Visst finn dei herfang, og skifter: Ei møy, tvo møyar til manns, farga klæde åt Sisera, farga klæde og krota; ein farga kjol, tvo krota tjeld for kvar ei herteki kvinna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Gjev, Herre, at uvenern’ dine må alle so ganga til grunnar, og dei deg elskar må vera som soli stig upp i sitt velde.» Sidan hadde landet fred i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Men Israels-sønerne gjorde det som var Herren imot. Då gav han deim i Midjans hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'I sju år hadde midjanitarne yvermagti yver Israel; det var for deira skuld Israels-sønerne gjorde seg dei løyndeholi som er i åsarne, og hellerarne og fjellborgerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Kvar gong Israel hadde sått, kom Midjan yver deim, og like eins Amalek og austmennerne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'dei lægra seg midt imot deim og øydde grøda i landet radt burtåt Gaza, og leivde ikkje ein matbite i Israel, og ingen sau, eller ukse, eller asen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'For dei kom dragande med buskapen og tjeldbuderne sine, so tett som grashoppar; det var’kje tal på deim og kamelarne deira, og kvar dei for fram, lagde dei landet i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Israel vart reint utarma av herjingarne deira, og Israels-sønerne ropa til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Då Israels-sønerne ropa til Herren for Midjans skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'då sende Herren ein profet til deim, og han sagde: «So segjer Herren, Israels Gud: «Eg førde dykk upp frå Egyptarland, og henta dykk ut or slavehuset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'og fria dykk frå egyptarane og frå alle deim som for ille med dykk; eg jaga deim burt for dykk, og gav dykk landet deira;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'og eg sagde til dykk: «Eg er Herren, dykkar Gud; de skal ikkje ottast gudarne åt amoritarne, som åtte det landet de bur i!» Men de høyrde ikkje på ordi mine.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Og Herrens engel kom og sette seg under den eiki som stend i Ofra, der Joas av Abiezer-ætti rådde. Gideon, son åt Joas, stod då i vinpersa og banka utor noko kveite, so han kunde få berga det for midjanitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Og Herrens engel synte seg for honom, og sagde til honom: «Herren er med deg, du djerve kjempa!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, '«Orsaka, gode herre!» svara Gideon, «ser Herren med oss, kvi hev då alt dette hendt oss, og kvar er no alle undergjerningarne hans, som federne våre fortalde oss um? «Det var Herren som førde dei ut or Egyptarland!» sagde dei. Men no hev Herren skuva oss ifrå seg, og gjeve oss i Midjans vald.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Då snudde Herren seg til honom, og sagde: «Gakk i veg so sterk som du er, so skal du berga Israel or Midjans vald. Det er eg som sender deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, '«Orsaka, Herre!» svara Gideon. «Korleis kann eg berga Israel? \'tti mi er då den veikaste i Manasse, og sjølv er eg den yngste av folket mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, '«Eg skal vera med deg,» sagde Herren, «og du skal slå midjanitarne ned som ein mann.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Då sagde Gideon: «Hev du noko godvilje for meg, so gjev meg eit merke på at det er du som talar med meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'kjære, flyt deg ikkje herifrå fyrr eg kjem ut til deg med gåva mi og legg henne fram for deg!» Og han svara: «Eg skal bia til du kjem att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'So gjekk Gideon inn, og stelte til eit kid, og tok ei skjeppa mjøl og lagde søtebrød av. Kjøtet lagde han i gryta, og sodet hadde han i ei krukka. So bar han det ut til honom under eiki og sette det fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Då sagde Guds engel til honom: «Tak kjøtet og søtebrødet, og legg det på dette berget, og slå sodet utyver!» So gjorde han det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Og Herrens engel rette fram staven som han hadde i handi, og stakk burti kjøtet og søtebrødet. Då slo det eld upp or berget, og øydde kjøtet og brødet, og Herrens engel kvarv burt for augo hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Då Gideon såg at det var Herrens engel, ropa han: «Å Herre min Gud! Korleis skal det ganga meg, som hev set Herrens engel andlit til andlit!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Men Herren sagde til honom: «Ver trygg! Ver ikkje rædd! Du skal ikkje døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Då bygde Gideon der eit altar for Herren, og kalla det: «Herren er mi trygd.» Det altaret stend endå i dag i Ofra, bygdi åt Abiezer-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Um natti sagde Herren til Gideon: «Tak stuten åt far din, den raude, sjuårsgamle stuten, og riv ned Ba’als-altaret åt far din, og fell det heilage treet som stend innmed det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Legg steinarne til rettes, og bygg av deim eit altar for Herren, din Gud, øvst uppå denne borgi! Tak so den raude stuten, og brenn honom til eit offer med veden av det treet som du skal hogga ned!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Då tok Gideon ti av sveinarne sine med seg, og gjorde som Herren hadde sagt til honom; men han torde ikkje gjera det um dagen; han var rædd ætti si og bygdefolket; difor gjorde han det um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Då mennerne i bygdi reis upp um morgonen, fekk dei sjå at Ba’als-altaret var nedrive, og at det heilage treet som stod der, var felt, og at den raude stuten var ofra på det nybygde altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Då sagde dei seg imillom: «Kven kann ha gjort dette?» Og då dei spurde og granska etter, fekk dei vita at det var Gideon Joasson som hadde gjort det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'So sagde dei til Joas: «Send son din ut til oss! Han skal døy, for di han hev rive ned Ba’als-altaret, og for di han hev felt det heilage treet som stod innmed det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Men Joas sagde til alle deim som stod kringum honom: «Vil de tala Ba’als sak? Vil de hjelpa honom? Den som gjer seg til hans talsmann, skal lata livet fyrr det vert morgon. Er han Gud, so lat honom sjølv greida si sak og taka hemn yver den som hev rive ned altaret hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Den dagen fekk Gideon namnet Jerubba’al, av di dei sagde: «Lat Ba’al hemna seg på honom for di han hev rive ned altaret hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'No hadde alle midjanitarne og amalekitarne og austmennerne samla seg i hop, og dei for yver Jordan, og lægra seg på Jizre’elsletta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Då kom Herrens Ande yver Gideon; han bles i luren, og Abiezer-ætti flokka seg um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'So sende han bod ut i heile Manassefylket, og dei samla seg og, og fylgde honom. Og til Asser og Sebulon og Naftali sende han bod; og dei for til møtes med Manasse-mennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Og Gideon sagde til Gud: «Er det so at du vil frelsa Israel ved mi hand, som du hev sagt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'so høyr meg: No legg eg dette sauskinnet på tråkki; kjem det so dogg berre på skinnet, og heile marki er turr, då veit eg at du vil berga Israel ved mi hand, som du hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Og soleis vart det. For då han andre morgonen reis upp og klemde i hop skinnet, vreid han utor det so mykje dogg at det vart ei heil skål full med vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Då sagde Gideon til Gud: «Ver ikkje vond på meg, um eg talar endå ein gong! Eg vilde so gjerne få gjera ei prøve til med skinnet! Kjære, lat skinnet vera turt, med heile marki er dogga!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Og natti etter gjorde Gud som han bad! Skinnet heldt seg turt, men heile marki var dogga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Jerubba’al - det er den same som Gideon - og alt folket som var med honom, tok ut tidleg um morgonen, og lægra seg ved Harodkjelda, og Midjans-heren låg nordanfor, frå Morehaugen og burtetter legdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Då sagde Herren til Gideon: «Du hev for mykje folk med deg! Eg vil’kje gjeva midjanitarne i henderne på so mange; elles kunde Israel kyta for meg og segja: «Det er mi eigi hand som hev berga meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Ropa no ut for folket: «Den som er rædd og fælen, kann snu og fara heim att frå Gileadfjellet!»» Då var det tvo og tjuge tusund mann som snudde heim, og ti tusund vart att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Men Herren sagde til Gideon: «Du hev endå for mykje folk! Lat deim ganga ned til kjelda, so skal eg røyna deim for deg der, og dei som eg segjer skal vera med deg, deim skal du taka med, men alle dei som eg segjer ikkje skal vera med deg, deim skal du ikkje hava med!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'So let han folket ganga ned til kjelda, og Herren sagde til han: «Alle deim som lepjar vatnet i seg med tunga liksom hunden, skal du setja for seg, og sameleis alle deim som legg seg på kne og drikk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Dei som då førde vatnet til munnen med handi og lepja, var tri hundrad i talet; alt hitt folket lagde seg på kne og drakk av vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Og Herren sagde til Gideon: «Med dei tri hundrad mann som drakk av handi, vil eg berga dykk og gjeva Midjan i henderne dine; alt hitt folket kann ganga heim att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'So tok dei til seg ferdakosten åt folket og lurarne deira; og Gideon let alle Israels-menner fara heim so nær som dei tri hundrad; deim hadde han att hjå seg. Midjans-lægret låg nedanfor honom, i lægdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Og då det vart natt, sagde Herren til honom: «Gjer deg reidug og tak på lægret der nede! Eg gjev det i henderne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Er du rædd, so gakk fyrst ned med Pura, sveinen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Då fær du høyra kva dei talar um, og sidan kjem du til å kjenna deg so sterk, at du torer taka på lægret.» So gjekk han og Pura, sveinen hans, ned til forpostarne i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Og midjanitarne og amalekitarne og alle austmennerne låg i dalen, so tett som grashoppar, og det var ikkje tal på kamelarne deira; dei var som sand på havsens strand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Då Gideon kom, var der ein som fortalde felagen sin ein draum: «No skal du høyra kva eg hev drøymt!», sagde han: «Eg tykte eg såg ei byggkaka kom trillande inn i Midjans-lægret, og då ho kom til tjeldet, skuva ho til det, so det rulla i koll, og der låg det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, '«Dette er’kje noko anna enn sverdet åt Gideon Joasson, israeliten,» svara hin; «Gud hev gjeve midjanitarne og heile lægret i henderne hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Då Gideon høyrde draumen og uttydingi, lagde han seg på kne og takka Gud. Han gjekk attende til Israels-lægret og sagde: «Ris upp! Herren hev gjeve Midjans-lægret i henderne dykkar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'So skifte han dei tri hundrad mann i tri flokkar, og gav deim alle lurar og tome krukkor i henderne; men inni krukkorne var det kyndlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Og han sagde til deim: «Sjå etter korleis eg fer åt, og far de like eins! So snart de ser eg er komen tett innåt lægret, skal de gjera som eg gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Når eg blæs i luren, eg og alle deim som er med meg, so skal de og blåsa i lurarne dykkar rundt ikring heile lægret og ropa: «For Herren og for Gideon!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Gideon og hundrad mann som var med honom, kom til utkanten av lægret fyrstundes i midnattsvakti; det var so vidt midjanitarne hadde sett ut vaktpostarne. Då bles dei i lurarne, og slo sund krukkorne, som dei hadde i handi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'og alle tri flokkarne bles i lurarne og slo sund krukkorne; med vinstre handi greip dei kring kyndlarne, og i høgre handi heldt dei lurarne, og bles i deim og ropa: «Drag sverdet for Herren og for Gideon!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'alt med dei vart standande kvar på sin stad rundt ikring lægret. Då tok alt som i lægret var til å renna att og fram og hua og røma,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'og Herren laga det so at då dei høyrde ljomen av dei tri hundrad lurarne, vende dei sverdi sine mot kvarandre. So gjekk det i heile lægret. Og heren rømde til Bet-Hassitta, burtimot Serera, til Abel-Meholastrandi framum Tabbat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Men Israels-mennerne av Naftali og Asser og heile Manasse vart utbodne og sette etter midjanitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Og yver heile Efraimsheidi sende Gideon folk som ropa ut: «Far ned og møt midjanitarne, og steng deim av frå elvi, frå Jordan, alt burt til Bet-Bara!» Då vart alle Efraims-mennerne utbodne og stengde vegen til elvi, til Jordan, alt burtåt Bet-Bara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Dei tok tvo av Midjans-hovdingarne, Oreb og Ze’eb, og drap Oreb på Ramneberget, og Ze’eb ved Ulvepersa. Sidan sette dei etter midjanitarne og kom med hovudi av Oreb og Ze’eb til Gideon på hi sida Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Efraims-mennerne sagde til Gideon: «Korleis er det du hev bore deg imot oss! Kvi sende du’kje bod etter oss då du tok ut i striden mot midjanitare?» Og dei tok kvast på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Då sagde han til deim: «Kva hev eg gjort no som kann liknast med det de hev gjort? Var’kje etterrakstren åt Efraim betre enn avlingi åt Abiezer?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'I dykkar hender gav Gud midjanitar-hovdingarne, Oreb og Ze’eb! Og kva hev eg vunnest gjort, so eg kunde mæla meg med dykk?» Då han tala so, logna dei og var’kje vonde på honom lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Gideon kom til Jordan, og for yver, han og dei tri hundrad mann som var med honom, og dei var trøytte og svoltne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Då sagde han til Sukkot-mennerne: «Kjære, gjev folki som fylgjer meg nokre matbitar! Dei er trøytte, og eg elter Zebah og Salmunna, Midjans-kongarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Men hovdingarne i Sukkot sagde: «Hev du alt fenge kloi i Zebah og Salmunna, sidan me skal gjeva heren din mat?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, '«Godt!» svara Gideon, «når Herren hev gjeve Zebah og Salmunna i henderne mine, so skal eg treskja kropparne dykkar med villtornar og tistlar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'So for han upp til Penuel, og tala like eins der, og Penuels-mennerne svara honom på same vis som Sukkot-buarne hadde svara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Då sagde han til deim og: «Kjem eg vel heim att, so skal eg riva ned denne borgi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebah og Salmunna låg i Karkor med heren sin, um lag femtan tusund mann; det var alt som var att av heile austmannheren, og hundrad og tjuge tusund våpnføre menner var falne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Og Gideon for uppetter driftevegen austanfor Nobah og Jogbea og kom yver fiendeheren, med dei låg ottelause i lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Zebah og Salmunna rømde, men han sette etter deim; han tok båe Midjans-kongarne, Zebah og Salmunna, og støkte heile heren ifrå einannan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Då Gideon Joasson var komen til Solskardet, vende han heim att frå striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Han fekk tak i ein gut som høyrde heime i Sukkot, og spurde honom ut; og guten skreiv upp for honom hovdingarne og styresmennerne i Sukkot, sju og sytti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Då han so kom til Sukkot-buarne, sagde han: «Sjå her er Zebah og Salmunna, dei som de spotta meg med då de sagde: «Hev du alt fenge kloi i Zebah og Salmunna, sidan me skal gjeva mat til dei trøytte mennerne dine?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'So greip han styresmennerne i byen, og han tok villtornar og tistlar, og tukta med deim Sukkot-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Penuelborgi reiv han ned, og slo i hel mennerne i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Sidan sagde han til Zebah og Salmunna: «Korleis såg dei ut, dei mennerne som de slo i hel på Tabor?» «Dei var like eins som du,» svara dei. «Kvar var som ein kongsson på skapnad».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, '«Då var det brørne mine,» sagde han, «sønerne åt mi eigi mor. So sant Herren liver: hadde de spart livet deira, skulde eg ikkje ha drepe dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'So sagde han til Jeter, eldste son sin: «Gakk fram, og slå deim i hel!» Men guten drog ikkje sverdet sitt. Han torde ikkje; han var endå berre ein gut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Då sagde Zebah og Salmunna: «Kom du og hogg oss ned! Det vil manns nerk til å gjera manns verk.» So gjekk Gideon fram, og slo Zebah og Salmunna i hel, og tok sylgjorne som kamelarne deira hadde kring halsen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Og Israels-mennerne sagde til Gideon: «Du skal vera kongen vår, både du og son din og soneson din; for du hev berga oss frå midjanitarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Men Gideon svara: «Ikkje vil eg vera kongen dykkar, og ikkje skal son min vera det; Herren skal vera kongen dykkar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Sidan sagde Gideon til deim: «Eg vil beda dykk um ein ting: at de alle vil gjeva meg dei ringarne de hev vunne i krigen!» For Midjans-mennerne gjekk med gullringar; dei var ismaelitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, '«Det skal du då visst få,» svara dei. So breidde dei ut ei kåpa, og på den kasta alle mann dei ringarne dei hadde vunne i krigen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Då dei so vog gullringane som han hadde bede um, so var det halvonnor vog gull, umfram gullsylgjorne og øyredobborne og purpurklædi som midjanitarkongarne hadde havt på seg, og umfram lekkjorne som kamelarne deira hadde bore kring halsen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Av gullet gjorde Gideon eit gudsbilæte. Det sette han upp i Ofra, heimbygdi si; heile Israel dyrka det der som ein avgud, og det vart til ulukka for Gideon og hans hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Soleis laut Midjan bøygja seg under Israel, og vann ikkje reisa hovudet meir, og sidan hadde landet ro i fyrti år, so lenge som Gideon livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'So for Jerubba’al Joasson heim att til garden sin, og vart buande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Han, Gideon, hadde sytti søner, som var hans eigne born; for han hadde mange konor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Med fylgjekona si i Sikem fekk han ein son, og kalla han Abimelek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideon Joasson døydde i høg alder, og vart nedsett i gravstaden åt Joas, far sin, i Ofra, bygdi åt Abiezer-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Då Gideon var burte, tok Israels-sønerne atter til å halda seg med avgudarne, og gjorde Sambands-Ba’al til guden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Israels-sønerne kom ikkje i hug Herren, sin Gud, som hadde berga deim frå alle fiendar rundt ikring;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'og dei gjorde ikkje vel mot Jerubba’als, Gideons, ætt for alt det gode han hadde gjort Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimelek, son åt Jerubba’al, for til Sikem, til morbrørne sine, og tala med deim og med alt morfolket sitt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '«Kjære dykk,» sagde han, «tala til alle Sikems-mennerne, og seg: «Kva er best for dykk: at sytti mann, alle sønerne åt Jerubba’al, styrer dykk, eller at ein mann styrer dykk?» Og kom so i hug at me er same folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Då tala morbrørne hans um honom for alle borgarane i Sikem, og sagde alt dette; og hugen drog deim til Abimelek. «Han er ein av våre!» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'So gav dei honom sytti lodd sylv av tempelskatten åt Sambands-Ba’al. For deim leigde Abimelek nokre lause uvyrdne karar, og dei fylgde honom kvar han gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'So for han til huset åt far sin i Ofra, og drap brørne sine, sønerne åt Jerubba’al, sytti mann på ein stein; berre Jotam, den yngste sonen åt Jerubba’al, vart att; han hadde fenge løynt seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Då samla dei seg, alle borgarane i Sikem og alt folket i Millo, og dei drog ut og valde Abimelek til konge under Minnesteinseiki ved Sikem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Då Jotam fekk spurt det, steig han upp på toppen av Gerizimfjellet; der stod han, og ropa til deim og sagde: «Høyr på meg, Sikems-menner, so sant de vil at Gud skal høyra på dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Det var ein gong trei vilde kåra seg ein konge. Dei sagde til oljetreet: «Du skal vera kongen vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Men oljetreet svara: «Skulde eg missa oljen min, som gudar og menneskje ærar meg for, og gjeva meg til å svaga att og fram yver skogen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Då sagde dei til fiketreet: «Kom du og ver kongen vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Og Fiketreet svara: «Skulde eg missa søtleiken min og den gode frukti mi, og gjeva meg til å svaga at og fram yver skogen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'So sagde dei til vintreet: «Kom du og ver kongen vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Vintreet svara: «Skulde eg missa safti mi, som gjer gudar og menneskje glade, og gjeva meg til å svaga att og fram yver skogen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Då sagde alle trei til klungeren: «Kom so du og ver kongen vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, '«Er det ålvor at de vil kåra meg til konge,» sagde klungeren, «so kom og svala dykk i skuggen min! Men er det ikkje, so skal det fara eld ut frå klungeren og øyda cedrarne på Libanon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Hev no de fare truge og ærleg fram med di de hev teke Abimelek til konge, og hev de gjort vel mot Jerubba’al og ætti hans, og hev de gjort lika for det han gjorde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'då han, far min, stridde for dykk, og våga livet, og berga dykk frå midjanitarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, '- og endå hev de no reist dykk mot ætti åt far min, og drepe sønerne hans, sytti mann på ein stein, og gjort Abimelek, son åt terna hans, til konge yver Sikems-buarne, for di han er skyld dykk -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'hev de no i dag fare truge og ærleg fram mot Jerubba’al og ætti hans, so gjev de må få gleda av Abimelek, og gjev han må få gleda av dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Men hev de ikkje det, so gjev det må fara eld ut frå Abimelek og tyna Sikems-buarne og Millo-folket, og gjev det må fara eld ut frå Sikems-buarne og Millo-folket, og tyna Abimelek!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'So rømde Jotam, og kom seg undan; sidan for han til Be’er, og der slo han seg ned, so Abimelek, bror hans, ikkje kunde nå i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'I tri år rådde Abimelek i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Då sende Gud ei vond ånd som sette ilt millom Abimelek og Sikems-mennerne, og Sikems-mennerne sveik Abimelek;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'for Gud vilde at valdsverket mot dei sytti sønerne åt Jerubba’al skulde hemnast, og blodet deira koma yver Abimelek, bror deira, som hadde drepe deim, og yver Sikems-mennerne, som hadde gjeve honom magt til å drepa brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Sikems-mennerne sette ut vaktmenner på fjelltindarne, som skulde halda auga med Abimelek, og røva alle som for framum der på vegen, og Abimelek fekk vita det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Ved det leitet kom Ga’al Ebedsson med brørne sine og flutte inn i Sikem, og Sikems-mennerne sette lit til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Dei gjekk ut på marki, og hausta vinhagarne sine og persa druvorne; so heldt dei takkehøgtid, og gjekk inn i templet åt guden sin, og åt og drakk og banna Abimelek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Og Ga’al Ebedsson sagde: «Er Abimelek slik mann, og sikemitarne slike folk, at me skulde vera tenarane hans? Hev’kje son åt Jerubba’al og Zebul, futen hans, tent ætti åt Hemor, den gamle Sikems-kongen? Men kvi skulde me so tena honom mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Gjev eg hadde hand yver dette folket, so skulde eg snart få Abimelek or vegen. Auka heren din, Abimelek, og kom!» kytte han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Då Zebul, byhovdingen, fekk høyra kva Ga’al Ebedsson hadde sagt, vart han harm;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'han sende i løynd bod til Abimelek og sagde: «Ga’al Ebedsson og brørne hans er komne til Sikem, og øser upp byen mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Tak no i vegen nattars tid med det folket du hev hjå deg, og legg deg på lur på marki;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'og når det dagast, og soli sprett, so brjot upp og renn fram imot byen; då fer Ga’al og folket hans ut imot deg, og du kann gjera med honom som du fær høve til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'So tok Abimelek ut um natti med alle dei folki han hadde hjå seg, og dei lagde seg på lur mot Sikem i fire flokkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'No bar det so til at Ga’al Ebedsson kom ut og stod i byporten i same bilet som Abimelek og folki hans braut fram frå løynlega.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Ga’al såg deim, og sagde til Zebul: «Sjå! Det kjem folk ned frå fjelltindarne!» «Det er skuggen av fjelli som du tek for folk,» svara Zebul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Men Ga’al heldt på og tala: «Sjå der kjem det folk ned frå Midhø’i,» sagde han, «og ein flokk kjem etter den vegen som ber til Trollmanneiki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Då sagde Zebul: «Kvar er no dei store ordi dine, du som sagde: «Er Abimelek slik mann at me skulde vera tenarane hans?» Sjå her er dei folki som du vyrde so lite! Drag no ut, og strid imot deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Då drog Ga’al ut med Sikems-mennerne i fylgje, og stridde mot Abimelek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Men Abimelek vann yver honom, og jaga han fyre seg, og det vart eit stort mannefall heilt burtåt byporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Sidan gav Abimelek seg til i Aruma, og Zebul dreiv Ga’al og brørne hans burt; dei måtte ikkje vera i Sikem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Dagen etter skulde Sikems-folket ut på marki. Det fekk Abimelek vita;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'då tok han og bytte mannskapet sitt i tri flokkar, og lagde seg på lur på marki, og då han såg at folket kom ut or byen, sette han på deim og hogg deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Sjølv sprang han fram, og tok støde ved byporten med den flokken som fylgde honom, og dei hine tvo flokkarne rende på alle deim som var ute på marki, og slo deim i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimelek kringsette byen heile den dagen, og tok honom, og drap folket som var der; byen reiv han ned, og strådde tufti med salt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Då folket i Sikemsborgi høyrde det, gjekk dei alle inn i tempelbygningen åt Sambands-Ba’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'So snøgt som Abimelek fekk vita at alt folket i Sikemsborgi hadde flokka seg i hop på ein stad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'gjekk han med alle mennerne sine upp på Salmonfjellet. Han tok øksi si i hand, og hogg greiner av trei, tok deim upp, lagde deim på herdi, og sagde til mennerne sine: «Skunda dykk og gjer like eins som de såg eg gjorde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Då hogg alle mennerne og kvar si byrd med kvist og fylgde etter honom. So lagde dei veden uppetter tempelbygningen, og sette med den eld på bygningen. Soleis umkomst alt folket i Sikemsborgi, um lag tusund menner og kvinnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Sidan gjekk Abimelek mot Tebes; den byen kringsette han og tok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Inni byen var det eit fast tårn; dit rømde alle menner og kvinnor, alt folket i byen, og dei stengde etter seg og gjekk upp på taket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Då Abimelek kom til tårnet, kringsette han det; so gjekk han fram til porten og vilde setja eld på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Då var det ei kvinna som kasta ein kvernstein ned på hovudet hans, so hausen brotna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Abimelek ropa svint på sveinen som bar våpni hans, og sagde: «Drag sverdet ditt, og drep meg, so det ikkje skal segjast at ei kvinna slo meg i hel!» Då stakk sveinen sverdet gjenom honom, og han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Og då Israels-mennerne såg at han var slokna, gjekk kvar heim til sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Soleis hemnde Gud den ugjerningi Abimelek gjorde mot far sin då han drap dei sytti brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Og alt det vonde Sikems-mennerne hadde gjort, let Gud koma attyver deim; den våbøni Jotam Jerubba’alsson hadde lyst, fekk dei sanna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Etter Abimelek stod Tola fram, og berga Israel. Han var son åt Pua Dodoson av Issakars-ætti, og budde i Samir på Efraimsheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Han styrde i Israel i tri og tjuge år. So døydde han og vart gravlagd i Samir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Etter han stod Ja’ir frå Gilead fram, og styrde Israel i tvo og tjuge år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Han hadde tretti søner; dei reid på tretti asenfolar, og åtte tretti tjeldbyar, som endå i dag vert kalla Ja’irsbyarne; dei ligg i Gileadlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Då Ja’ir døydde, vart han gravlagd i Kamon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Men Israels-borni gjorde atter det som var Herren imot, og dyrka Ba’als- og Astarte-bilæti og Arams-gudarne og Sidons-gudarne og Moabs-gudarne og ammonitargudarne og filistargudarne; dei vende seg frå Herren, og dyrka ikkje honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Då vart Herren brennande harm på Israel. Han slepte dei i henderne på filistarane og ammonitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'og dei tok same året til å trengja og trælka Israels-sønerne; i attan år trengde dei alle Israels-sønerne som budde på hi sida Jordan, i Amoritarlandet, i Gilead;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'dei sette jamvel yver Jordan, og stridde mot Juda og Benjamin og mot Efraims-ætti, og Israel kom i stor naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Då ropa Israels-sønerne til Herren og sagde: «Me hev synda mot deg! Me hev vendt oss frå vår Gud og dyrka Ba’als-bilæti!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Og Herren sagde til Israels-sønerne: «Hev eg’kje berga dykk frå egyptarane og frå amoritarne, frå Ammons-sønerne og frå filistarane?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Og då sidonarane og amalekitarne og maonitarne plåga dykk, og de ropa til meg, berga eg dykk frå deim og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Men de vende dykk frå meg, og dyrka andre gudar; difor vil eg ikkje hjelpa dykk meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Gakk burt og kalla på dei gudarne som de hev valt! Lat deim hjelpa dykk no de er i slik naud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Då sagde Israels-sønerne til Herren: «Me hev synda! Gjer med oss som du synest, berre du vil hjelpa oss denne gongen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'So hadde dei frå seg dei framande gudarne og tente Herren; då kunde han ikkje tola å sjå på Israels naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Ammons-sønerne baud ut heren sin, og lægra seg i Gilead. Då samla Israels-sønerne seg og slo læger i Mispa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Og herfolket, Gileads-fyrstarne, sagde seg imillom: «Kvar er den mannen som vil ganga fyrst i striden mot ammonitarne? Han skal vera hovding yver alle Gileads-buarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jefta frå Gilead var ei gjæv kjempa. Han var son åt ei skjøkja, men Gilead var far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Med kona si hadde Gilead og søner; då dei vart vaksne, jaga dei Jefta burt, og sagde til honom: «Du fær ingen lut i arven etter far vår; for du er son åt ei framand kvinna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Då rømde Jefta for brørne sine, og sette seg ned i Tob-land, og det samla seg mange lause karar ikring honom, og var med honom på ferderne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'So leid det av ei tid; då var det ammonitarne gjorde åtak på Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'og då ammonitarne bar våpn mot Israel, tok styresmennerne i Gilead ut, og vilde henta Jefta heim frå Tob-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, '«Kom og ver føraren vår,» sagde dei med honom, «so vil me strida mot ammonitarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, '«Var det’kje de som hata meg, og dreiv meg burt frå heimen min?» svara Jefta; «kvi kjem de då til meg no som de er i naud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, '«Difor er det me no kjem att til deg,» svara styresmennerne: «Gjeng du med oss og strider mot ammonitarne, so skal du vera hovdingen vår og styra alle Gileads-buarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Då sagde Jefta til styresmennerne i Gilead: «Vert eg med dykk heim, og strider mot ammonitarne, og Herren gjev deim i mi magt, skal eg so vera hovdingen dykkar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Og dei svara: «Herren skal vera vårt vitne at me i eit og alt vil gjera som du segjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Då gjekk Jefta med styresmennerne; folket sette honom til sin hovding og førar, og i Mispa tok han upp att alle ordi sine for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'So sende han bod til ammonitarkongen, og sagde: «Hev me noko ubytt, eg og du, sidan du kjem hit og gjer åtak på landet mitt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Då sagde ammonitarkongen til sendemennerne åt Jefta: «Då Israel kom frå Egyptarland, tok dei landet mitt, frå Arnon til Jabbok og til Jordan. Gjev det no att med godo!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Og Jefta sende endå ein gong bod til ammonitarkongen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'med dei ordi: «So segjer Jefta: «Israel hev ikkje teke land frå Moab eller frå Ammon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'På vegen frå Egyptarland for Israel igjenom øydemarki til Sevhavet og kom til Kades.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Då sende dei bod til kongen i Edom, og sagde: «Kjære, lat oss få fara gjenom landet ditt!» Men Edom-kongen høyrde ikkje på dei. Til Moab-kongen sende dei og bod; men han vilde ikkje heller. So gav dei seg til i Kades.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Sidan heldt dei fram gjenom øydemarki. Dei for utanikring Edomitarlandet og Moabitarlandet, til dei kom austanum Moab, og lægra seg på hi sida Arnon; dei kom ikkje inn på Moabs grunn; for Arnon er landskilet åt Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'So sende Israel bod til Sihon, amoritarkongen, kongen i Hesbon, og sagde: «Kjære, lat oss få fara gjenom landet ditt, so me kjem dit me skal!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Men Sihon trudde ikkje Israel so vel at han torde lata dei fara gjenom riket sitt; han samla heile heren sin, og dei lægra seg i Jahsa, og gav seg i strid med Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Og Herren, Israels Gud, gav Sihon og heile heren hans i Israels hender; Israel slo deim, og lagde under seg alle amoritarbygderne der i landet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'heile Amoritarriket lagde dei under seg, frå Arnon til Jabbok, og frå øydemarki til Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'So hev då Herren, Israels Gud, teke landet frå amoritarne og gjeve det til folket sitt, til Israel, og no vil du eigna det til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Er det’kje so at det som Kamos, guden din, let deg vinna, det eignar du til deg, og alt det som Herren, vår Gud, gjer rydigt for oss, det eignar me til oss?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Er då du so mykje betre enn Balak Sipporsson, Moabs-kongen? Trætta han med Israel, eller tok på deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'No er det tri hundrad år sidan Israel busette seg i Hesbon og dei bygderne som ligg umkring, og i Aroer, og bygdarne der umkring og i alle byarne langsmed Arnon; kvi hev de’kje teke deim att i all den tidi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Eg hev ikkje gjort deg noko vondt; men du gjer meg stor urett med di du tek på meg. Herren, som er den øvste domaren, skal i dag døma millom Israel og Ammon.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Men ammonitarkongen vilde ikkje høyra på det bodet Jefta sende honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Då kom Herrens Ande yver Jefta, og han for gjenom Gilead og Manasse; so for han fram til Gileadvarden, og Gileadvarden for han fram imot ammonitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Og Jefta gjorde ein lovnad til Herren, og sagde: «Gjev du ammonitarne i henderne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'då skal den som gjeng ut or husdøri mi og møter meg når eg kjem vel heim att frå ammonitarne, då skal den høyra Herren til; eg skal ofra honom til eit brennoffer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'So for han fram imot ammonitarne, og stridde mot deim, og Herren gav deim i henderne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Han slo deim, og elte deim frå Aroer til burtimot Minnit, og tok tjuge byar ifrå deim; sidan elte han deim alt til Abel-Keramim, det vart eit stort mannefall på deim. Då laut Ammons-sønerne bøygja seg under Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Då Jefta kom heim att til garden sin i Mispa, gjekk dotter hans ut imot honom, og fagna honom med trummor og dans; ho var einaste barnet hans; umfram henne hadde han’kje anten son eller dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Med det same han fekk sjå henne, reiv han sund klædi sine, og ropa: «Gud trøyste oss, mi dotter! for ei sorg du veld meg! for ei ulukke du fører meg i! Eg hev gjort so dyr ein lovnad til Herren, og eg kann ikkje taka att ordet mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Då sagde ho til honom: «Far, hev du gjort so dyr ein lovnad til Herren, so gjer det med meg som du gav ordet ditt på, sidan Herren let deg få hemn yver ammonitarne, uvenerne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Men ein ting vilde eg gjerne skulde gjerast for meg,» sagde ho med far sin: «Lat meg vera fri tvo månader, so vil eg ganga ned på heidarne med venorne mine og gråta yver mitt unge liv, eg som lyt fara burt møy!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, '«Gjer so!» svara han, og sagde ho kunde vera burte tvo månader. So gjekk ho med venorne sine, og gret på heidarne yver sitt unge liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Men då tvo månader var lidne, kom ho att til far sin, og då gjorde han med henne det som han hadde lova; og ho hadde aldri vore nær nokon mann. Sidan vart det sed i Israel');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'at Israels-døtterne år for år gjeng av og syng minnekvede um dotter åt Jefta frå Gilead, fire dagar um året.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Efraimitarne baud ut mannskapet sitt, og for nordetter, og sagde til Jefta: «Kvi sende du’kje bod etter oss då du for av stad og vilde strida mot ammonitarne? No vil me setja eld på husi dine og brenna deg inne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, '«Eg og folket mitt låg i ein hard strid med ammonitarne, svara Jefta; «då ropa eg på dykk, men de hjelpte meg ikkje imot deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'og då eg såg at de ikkje vilde hjelpa, våga eg livet, og for imot ammonitarne, og Herren gav deim i henderne mine. Kvi kjem de so no farande og vil slåst med meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'So samla han alle Gileads-mennerne, og stridde mot Efraim. Og Gileads-mennerne hogg efraimitarne ned, for di dei hadde sagt: De er rømingar frå Efraim! Gilead ligg midt i Efraim, midt i Manasse.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Dei stengde vadi yver Jordan for efraimitarne, og kvar gong det kom ein efraimit som hadde rømt ifrå slaget og vilde sleppa yver, spurde dei: «Er du efraimit?» Han svara: «Nei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, '«Seg: sjibbolet!» sagde dei. Då sagde han: «Sibbolet;» for han kunde ikkje segja det rett. So greip dei honom, og drap honom innmed vadet. Den gongen fall det tvo og fyrti tusund mann av Efraims-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jefta styrde Israel i seks år. So døydde Jefta frå Gilead, og vart gravlagd i ein av Gileads-byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Etter honom var Ibsan frå Betlehem styrar i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Han hadde tretti søner; tretti døtter gifte han burt, og tretti sonekonor henta han heim; han styrde Israel i sju år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'So døydde Ibsan, og vart gravlagd i Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Etter honom var Elon av Sebulons-ætti styrar i Israel. Han styrde Israel i ti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'So døydde Elon av Sebulons-ætti, og vart gravlagd i Ajjalon i Sebulonslandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Etter honom var Abdon Hillelsson frå Piraton styrrar i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Han hadde fyrti søner og tretti sonesøner; dei reid på sytti asenfolar. Han styrde Israel i åtte år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'So døydde Abdon Hillelsson frå Piraton, og vart gravlagd i Piraton i Efraimsland, på Amaleksfjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Men Israels-sønerne gjorde atter det som var Herren imot. Då let han filistarane få magt yver deim i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Det var ein mann av Dans-ætti som heitte Manoah. Han budde i Sora. Kona hans var’kje barnkjømd; ho hadde aldri ått barn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Og Herrens engel synte seg for kona, og sagde: «Kjære, eg veit at du er’kje barnkjømd og aldri hev ått barn, men du skal verta umhender og eiga ein son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Agta deg no, og drikk ikkje vin eller sterk drykk, og et ikkje noko ureint!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'For no vert du umhender, og fær ein son: på hans hovud må det aldri koma saks; for sveinen skal vera vigd til Gud alt ifrå morsliv, og han skal gjera upptaket til å berga Israel frå filistarane.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'So gjekk kona inn, og sagde det med mannen sin: «Det kom ein gudsmann til meg,» sagde ho; «han var å sjå til som Guds engel, fælande ageleg; men eg spurde ikkje kvar han var ifrå, og ikkje sagde han meg namnet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, '«Du skal verta umhender og eiga ein son,» sagde han med meg; «drikk no ikkje vin eller sterk drykk, og et ikkje noko ureint! For sveinen skal vera vigd til Gud frå morsliv og til sin døyande dag.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Då bad Manoah til Herren, og sagde: «Høyr meg, Herre! Lat den gudsmannen som du sende koma hit att og læra oss korleis me skal fara med det barnet som skal koma til verdi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Og Gud høyrde Manoahs bøn, og Guds engel kom att til kona ein gong ho sat utpå marki, og Manoah, mannen hennar, ikkje var med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Då sprang ho svint heim, og sagde det med mannen sin: «No hev han synt seg for meg, den mannen som kom til meg her um dagen», sagde ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoah reiste seg, og fylgde kona si, og då han kom til mannen, spurde han: «Er du den mannen som hev tala til kona mi?» «Ja», svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, '«Når det no gjeng fram det som du sagde, korleis skal me då stella oss med sveinen, og korleis skal me fara med honom?» sagde Manoah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Då svara Herrens engel: «Alt det eg nemnde for kona, lyt ho agta seg for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Ho må ikkje eta noko som kjem av vintreet, og ikkje drikka vin eller sterk drykk, og ikkje eta noko ureint; alt det eg hev sagt til henne, lyt ho halda seg etter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, '«Kann du’kje bia eit bil, so me fær stella til eit kid for deg!» sagde Manoah. For han visste ikkje at det var Herrens engel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, '«Um eg biar, so et eg like vel ikkje av maten din,» svara Herrens engel; «men vil du laga til eit brennoffer åt Herren, so gjer det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Då sagde Manoah til Herrens engel: «Kva er namnet ditt - so me kann få æra deg, når det hender det som du hev sagt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, '«Kvi spør du um namnet mitt?» svara han; «det er eit underleg namn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'So tok Manoah kidet og grjonofferet, og ofra det på berget til Herren. Då hende eit stort under, so Manoah og kona hans såg på det:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Då logen steig upp frå altaret mot himmelen, då for Herrens engel upp i altarlogen. Då Manoah og kona hans såg det, kasta dei seg å gruve på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Herrens engel synte seg ikkje oftare for Manoah og kona hans; då skyna Manoah at det var Herrens engel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'og han sagde til kona si: «No lyt me døy; for me hev set Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Men kona svara: «Hadde Herren havt hug til å drepa oss, so hadde han ikkje teke mot brennoffer og grjonoffer av oss, og me hadde ikkje fenge set alt dette, og ikkje fenge høyrt slikt som det me høyrde no.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Då det leid på, fekk kona ein son, og kalla honom Samson. Guten voks upp, og Herren velsigna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Det var i Dans-lægret millom Sora og Estaol, Herrens ande fyrst tok til å driva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Ein gong bar det so til at Samson gjekk ned til Timna; der fekk han sjå ei filistargjenta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Då han kom heim att, sagde han det med far sin og mor si: «Eg såg ei filistargjenta i Timna; henne lyt de festa til kona åt meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Då sagde foreldri hans til honom: «Finst det då ingi gjenta hjå frendarne dine eller i heile vårt folk, sidan du vil ganga av og få deg ei kona hjå dei u-umskorne filistarane?» Men Samson svara far sin: «Henne lyt du festa åt meg! Ho er den som eg likar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Foreldri hans skyna ikkje at dette kom frå Herren; for han søkte eit høve til å koma innpå filistarane - den gongen rådde filistarane i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'So gjekk Samson og foreldri hans ned til Timna. Då dei kom til vinhagarne utanfor byen, for ei ung løva burande imot honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'då kom Herrens ande yver honom, og han tok løva, og sleit henne sund med berre nevarne, som det skulde vore eit kid; men han sagde’kje med foreldri sine kva han hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'So gjekk han ned og tala med gjenta; og han lika henne framifrå godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Um ei tid for han ned att og vilde gifta seg med henne. So tok han av vegen, vilde sjå løva som han hadde drepe; då fann han eit biebol med honning i skrovet hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Han tok honningen ut, og heldt honom i henderne og åt, med han gjekk frametter, og då han kom til foreldri sine, gav han dei og, og dei åt; men han sagde det ikkje med deim at han hadde funne honningen i løveskrovet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Då far hans kom ned til bruri, gjorde Samson eit gjestebod der, som dei unge mennerne hadde for vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Og so snart dei fekk sjå honom, fann dei honom tretti fylgjesmenner; dei var stødt med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'og ein dag sagde Samson til deim: «No vil eg bjoda dykk ei gåta! Løyser de henne åt meg innan dei sju gjestebodsdagarne er ute, og løyser de henne rett, so skal eg gjeva dykk tretti fine skjortor og tretti festklædningar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'men kann de ikkje løysa henne, skal de gjeva meg tretti fine skjortor og tretti festklædningar.» «Seg fram gåta di, so me fær høyra henne!» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Då sagde han: «Av ein etar kom etand’, av den sterke kom søtt.» So leid det tri dagar, og dei var ikkje god til å løysa gåta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Den sjuande dagen sagde dei til bruri: «Få mannen din til å segja oss løysningi på gåta, elles brenner me upp både deg og folket ditt! Er det for å arma oss ut at de hev bede oss hit?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Då gret bruri framfyre honom, og sagde: «Du held ikkje av meg! Du berre hatar meg! Du hev bode landsmennerne mine ei gåta, men meg hev du ikkje sagt korleis ho skal løysast!» «Eg hev’kje sagt det med far min og mor mi; skulde eg so segja det med deg?» svara Samson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Men ho hekk yver honom og gret alle dei sju dagarne som gjestebodet varde, og den sjuande dagen sagde han det med henne, av di ho plåga honom so. So løyste ho gåta for landsmennerne sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'og fyrr soli gladde den sjuande dagen, kom mennerne i byen og sagde til honom: «Kva er søtar’ enn honning? Kva er sterkar’ enn løva?» Då svara Samson: «Hadde de’kje pløgt med mi kviga, so hadde de’kje løyst mi gåta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Og Herrens ande kom yver honom; han gjekk ned til Askalon, og slo i hel tretti filistarar, tok klædi deira, og let deim som hadde løyst gåta få deim til høgtidsklede; og harm som han var, for han heim att til garden åt far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Men kona hans vart gjevi til den fylgjesmannen, som han hadde valt seg til brursvein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Då det leid um ei tid, og dei hadde teke til med kveiteskurden, kom Samson og vilde lydast til kona si. Han hadde med seg eit kid, og sagde: «Lat meg få koma inn i kammerset til kona mi!» Men far hennar vilde ikkje gjeva honom lov til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, '«Eg tenkte so visst at du ikkje lika henne meir,» sagde faren, «og so gav eg henne til brursveinen din. Kann du’kje taka den yngre systeri i staden? ho er då mykje vænare!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Då sagde Samson: «Denne gongen er eg saklaus, um eg gjer filistarane vondt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Han gjekk av og fanga tri hundrad revar, fann seg tyrespikar, snudde reverovarne i hop mot kvarandre, tvo og tvo, og feste ei spik millom kvart rovepar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'So kveikte han eld i spikarne, og slepte revarne inn på åkrane åt filistarane. Soleis brende han upp alt kornet dei hadde ute, både skore og uskore, og alle vinhagar og oljetre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Då spurde filistarane: «Kven hev gjort dette?» «Samson, mågen åt Timna-mannen,» vart det svara. «Det var for di verfaren hadde teke kona hans og gjeve til brursveinen.» So for filistarane derupp, og brende inne både kona og far hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Då sagde Samson til deim: «Fer de soleis åt, so skal eg visst ikkje kvila fyrr eg fær hemnt meg på dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'So slo han deim so dei stupte i kross og i krok, og det vart eit stort mannefall på deim. Sidan for han ned til Etamdjuvet, og gav seg til der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Då kom filistarane upp i Judafylket, og lægra seg der, og spreidde seg utyver i Lehi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Og Juda-mennerne sagde: «Kvi kjem de hit og tek på oss?» «Me vil binda Samson og gjera like eins mot honom som han hev gjort mot oss,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'So for tri tusund mann av Juda-ætti ned til Etamdjuvet, og sagde til Samson: «Veit du’kje at filistarane råder her i landet? Kvi hev du då gjort oss dette?» «Som dei gjorde mot meg, so hev eg gjort mot deim,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Då sagde dei: «Me er komne hit for å binda deg og gjeva deg i henderne på filistarane.» «Lova meg at ikkje de vil slå meg i hel!» sagde Samson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, '«Nei, me vil berre binda deg og gjeve deg i henderne deira; me vil ikkje drepa deg,» svara dei. So batt dei honom med tvo nye reip, og førde honom upp or djuvet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Då han kom til Lehi, sprang filistarane imot honom med glederop. Då kom Herrens ande yver honom, og reipi på armarne hans vart som brend tråd; bandi datt av henderne hans, som dei var morkna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'So fann han eit friskt kjakebein av eit asen; det greip han og slo i hel tusund mann med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Då kvad han: «Med asenkjaken eg ein hop og tvo, med asenkjaken tusund mann eg slo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Då han hadde kvede dette, kasta han kjakebeinet frå seg, og sidan hev dei kalla den staden Kjakebeinshaugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Men so vart han so brennande tyrst. Då ropa han til Herren og sagde: «Du hev hjelpt tenaren din til å vinna denne store sigeren! Skal eg no døy av torste og falla i henderne på dei u-umskorne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Då opna Gud den hola som er i Lehi, og det rann vatn utor henne, so han fekk drikka; då rådde han atti, og kvikna til. Difor kalla dei den kjelda Roparkjelda; ho er endå i Lehi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Samson styrde Israel i tjuge år; det var i filistartidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Ein gong kom Samson til Gaza; der fekk han sjå ei skjøkja, og gjekk inn til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Då det spurdest bland folket i Gaza at Samson var komen der, ringa dei honom inne, og lurde på honom innmed byporten heile natti, men heldt seg elles rolege med natti var. «Me vil bia til det dagast; då skal me slå honom i hel,» tenkte dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Samson vart liggjande til midt på natti. Midnattsbil reis han upp. Han tok tak i hurderne i byporten og i båe portstolparne, og rykte deim upp i hop med bommen, lagde deim på herdarne, og bar deim upp på toppen av det fjellet som ligg midt for Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Sidan lagde han hug til ei kvinna i Sorekdalen, som heitte Dalila.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Då kom filistarfyrstarne upp til henne og sagde: «Sjå um du kann få lokka honom til å segja deg kvar han hev den store styrken sin frå, og korleis me kann råda med honom og binda honom, so me fær døyvt honom! Då skal me gjeva deg tusund sylvdalar kvar, og meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'So sagde Dalila til Samson: «Kjære, seg meg kvar du hev den store styrken din frå, og korleis du kann bindast, so ein fær døyvt deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, '«Dersom dei bind meg med sju rå senestrengjer, som ikkje hev vorte turre, so veiknar eg og vert som eit anna menneskjebarn,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Då kom filistarfyrstarne upp til henne med sju rå senestrengjer, som ikkje hadde vorte turre; deim batt ho honom med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'og i kammerset hadde ho folk sitjande og lura. So ropa ho: «filistarane er yver deg, Samson!» Då sleit han sund strengjerne, som ein strytråd brest når han kjem innåt elden, og ingen fekk vita kvar han hadde styrken sin frå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'So sagde ho til honom: Du hev narra meg, og loge for meg. Kjære, seg meg no korleis du kann bindast!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, '«Dersom dei bind meg vel med nye reip som aldri hev vore bruka til noko, so veiknar eg og vert som eit anna menneskjebarn,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'So tok Dalila nye reip og batt honom med, og ropa: «Filistarane er yver deg, Samson!» og i kammerset sat det folk og lurde. Men han sleit reipi av armarne sine, som det var tråd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Då sagde Dalila til honom: «Til dessa hev du narra meg og loge for meg! Seg no korleis du kann bindast!» «Dersom du vev dei sju hårflettorne mine inn i veven!» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'So slo ho ått med vevskeidi, og ropa: «Filistarane er yver deg, Samson!» Då vakna han or svevnen, og rykte ut både vevskeidi og varpet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'So sagde ho til honom: «Korleis kann du segja du hev meg kjær, når du ikkje hev tiltru til meg? No hev du narra meg tri gonger og ikkje sagt meg kvar du hev den store styrken din frå!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Som ho no tagg og truga dag etter dag, og aldri let honom få fred, vart han so leid seg at han vilde mest døy,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'og so opna han heile sitt hjarta for henne: «Det hev aldri kome saks på mitt hovud,» sagde han; «for eg hev vore vigd til Gud alt ifrå morsliv. Vert eg raka, so fer styrken min frå meg; eg veiknar og vert som alle andre menneskjeborn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Då skyna Dalila at han hadde sagt henne heile sanningi; ho sende bod etter filistarfyrstarne, og sagde: «Kom her upp! For denne gongen hev han sagt meg heile sanningi.» Då kom filistarfyrstarne upp til henne, og hadde pengarne med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'So svævde ho Samson i fanget sitt, og ropa på ein mann ho hadde sitjande der, og let honom klyppa dei sju hårflettorne hans; då tok han til å veikna, og styrken hans for frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Og Dalila ropa: «Filistarane er yver deg, Samson!» Då vakna han or svevnen, og tenkte: «Eg skal gjera meg fri og rista meg laus, som so mang ein gong fyrr;» for han visste ikkje at Herren hadde vendt seg ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Filistarane tok Samson, og stakk ut augo på honom, og førde han ned til Gaza; der batt dei honom med dubbel koparlekkja, og han laut sveiva handkverni i fangehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Men håret hans tok til å veksa sterkt med same det var klypt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'So kom Filistarfyrstarne i hop, og bar fram eit stort offer for Dagon, guden sin, og heldt fest; «for,» sagde dei, «vår gud hev gjeve Samson, vår uven, i vår magt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, '[Stu21: 25] og då folket såg honom, lova dei guden sin, og kvad: I handi vår gav guden vår uvenen vår, han som øydde landet vårt han som drap ned folket vårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, '[Stu21: 24] Som dei no var komne på godlag, ropa dei: «Henta Samson hit, so han kann leika for oss!» Då henta dei Samson or fangehuset, og han laut leika for deim. Dei sette honom millom stolparne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Då sagde Samson til guten som leidde honom: «Slepp meg, og lat meg få halda i dei stolparne som huset kviler på, og stydja meg innåt deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Men huset var fullt av menner og kvinnor; alle filistarfyrstarne var der, og på taket var det um lag tri tusund menner og kvinnor, som såg på med Samson leika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Og Samson kalla på Herren og sagde: «Herre, min Gud, kom meg i hug, og styrk meg denne eine gongen, min Gud, so eg fær hemnt meg på filistarane for eitt av dei tvo augo mine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'So femnde han kringum båe midstolparne som huset kvilde på, og klemde deim innåt seg, ein med høgre, og ein med vinstre handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, '«Lat meg døy i hop med filistarane!» sagde han, og tok i med all si magt; då ramla huset i hop yver fyrstarne og yver alt folket som var der, og dei som han drap då han døydde, var fleire enn dei han hadde drepe med han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Men brørne hans og alt skyldfolket kom og tok honom, og førde honom heim, og sette honom ned i gravstaden åt Manoah, far hans, millom Sora og Estaol. Då hadde han styrt Israel i tjuge år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Mika heitte ein mann som budde i Efraimsheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Han sagde til mor si: «Dei elleve hundrad sylvdalarne som vart tekne frå deg - du lyste endå for den skuld ei våbøn, som eg høyrde på - dei pengarne er hjå meg; det er eg som hev teke deim; men no skal du få deim att.» «Herren velsigne deg, min son!» svara mori.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'So gav han dei elleve hundrad sylvdalarne att til mor si. Då sagde ho: «Desse pengarne vigjer eg no til Herren, og gjev deim frå meg til bate for deg, min son, so du kann gjera eit gudebilæte med eit støypt fotstykke til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'So tok ho tvo hundrad dalar av pengarne han kom att med, og gav deim til ein gullsmed, og han gjorde for deim eit gudsbilæte med eit støypt fotstykke til; det var sidan på garden hans Mika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Og Mika vart slik mann at han fekk seg eit gudshus, og let gjera ei gullkåpa og husgudar, og sette ein av sønerne sine til å vera prest for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'I dei dagar var det ingen konge i Israel; kvar mann gjorde som han hadde hug til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Det var ein ung mann frå Betlehem i Juda; han var av Levi-ætti, av den greini som åtte heime i Judafylket, og der heldt han til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Den mannen flutte burt frå byen sin, frå Betlehem i Juda, og vilde finna seg ein verestad kvar det kunde høva. På ferdi si kom han til Efraimsheidi og til garden hans Mika,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'og Mika spurde honom: «Kvar kjem du frå?» «Eg er ein levit frå Betlehem i Juda,» svara han, «og no er eg ute og ferdast, og vil finna meg ein verestad kvar det kann høva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, '«Gjev deg til hjå meg!» sagde Mika, «og ver far og prest for meg! Eg skal gjeva deg ti sylvdalar for året, og halda deg med kost og klæde.» So steig leviten innanfor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Han gjekk med på å vera hjå mannen, og vart som ein av sønerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Mika feste den unge leviten til prest for seg, og han vart verande i huset hans Mika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, '«No veit eg at Herren vil gjera vel mot meg,» sagde Mika, «sidan eg hev fenge ein levit til prest.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'I den tidi fanst det ingen konge i Israel. Og i den tidi leita Dans-ætti etter eit odelsland til å busetja seg i; for det hadde ikkje til den dag falle nokon arvlut på deim, som på dei andre Israels-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Dans-sønerne sende ut fem mann av heile si ætt, djerve karar frå Sora og Estaol, som skulde endefara landet og sjå det vel yver. «Far no i veg,» sagde dei til deim, «og sjå dykk vel um i landet!» Mennerne kom til garden hans Mika i Efraimsheidi, og vart der um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'For då dei for frammed husi hans Mika, kjende dei att målet åt den unge leviten, og so tok dei av vegen, og spurde honom: «Kven hev ført deg hit? Kva gjer du her, og korleis hev du det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'So sagde han deim kva Mika hadde gjort for honom, og at han hadde leigt honom til prest for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, '«Kjære deg,» sagde dei då, «spør Gud for oss um den ferdi me hev fyre oss, skal lukkast!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, '«Det kann fara trygt!» svara presten «Herren hev augo med dykk på ferdi dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Då for dei sin veg, dei fem mennerne, og kom til La’is; og dei såg at folket der i bygdi livde sutlaust, på same vis som sidonarane, roleg og sutlaust; det fanst ingen i landet som gjekk deim for nær i nokon ting, ingen einvaldsherre; langt var dei frå sidonarane, og hadde ikkje noko å gjera med anna folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'So kom dei heim att til frendarna sine i Sora og Estaol, og frendarne deira spurde: «Kva tidender kjem de med?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, '«Kom, lat oss fara i veg og taka på La’is-buarne!» svara dei; «me hev skoda landet; det er eit ovgodt land. Og de sit berre og tegjer? Dryg ikkje med å taka på vegen til det landet og eigna det til dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Når de kjem dit, kjem de til eit folk som ikkje kjem i hug nokon fåre, og landet er vidskått. Gud hev gjeve det i henderne dykkar, eit land der det ikkje vantar nokon verdeleg ting!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'So for dei i vegen, seks hundrad fullvæpna mann av Dans-ætti, frå Sora og Estaol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Då dei var komne upp i høgdi, slo dei læger i Kirjat-Jearim i Judafylket; difor hev den staden vore kalla Dans-lægret alt til denne dag; det er vestanfor Kirjat-Jearim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Derifrå for dei yver til Efraimsheidi, og kom til garden hans Mika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Då tok dei til ords, dei fem mennerne som hadde vore til La’isbygdi og spæja, og dei sagde til landsmennerne sine: «Veit de at i desse husi er det ei gullkåpa og husgudar og eit gudebilæte med eit støypt fotstykke til? so veit de vel kva de lyt gjera!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'So tok dei av vegen der, og kom til huset åt den unge leviten på garden hans Mika, og helsa på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Der stod no i portledet seks hundrad fullvæpna mann av Dans-ætti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'og dei fem mennerne som hadde vore der i landet og spæja, gjekk upp på garden og inn i gudshuset, og tok gudsbilætet og gullkåpa og husgudarne og det støypte fotstykket, med presten stod i portledet hjå dei seks hundrad fullvæpna mennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Då no desse kararne hadde vore inn i huset hans Mika og teke gudsbilætet med gullkåpa og husgudarne og det støypte fotstykket, so sagde presten til deim: «Kva er det de gjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, '«Teg deg og agta munnen din!» svara dei. «Kom heller med oss, og ver far og prest for oss! Er det’kje mykje betre for deg å vera prest for ei heil ætt og grein av Israel enn for ein huslyd?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Dette lika presten vel. Han tok gullkåpa og husgudarne og gudsbilætet, og gav seg med flokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'So snudde dei seg, og for av garde, og let kvinnorne og borni og bufeet og eignaluterne sine vera fremst i ferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Dei var alt komne langt ifrå garden fyrr mennerne i grendi hans Mika fekk samla seg og nådde deim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Dei ropa etter Dans-sønerne, og dei vende seg og sagde til Mika: «Kva er tids, med di du hev samla folki dine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, '«De hev teke gudarne som eg hev gjort meg, og presten, og fare av garde med,» svara han; «kva hev eg so att? Og endå spør de meg kva er tids!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Då sagde dei til honom: «Lat oss ikkje høyra eit ord av deg meir! Elles kunde hug-rame karar rjuka på dykk, og då kom du til å missa livet både du og dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'So for dei sin veg, Dans-sønerne, og då Mika såg at dei var honom for sterke, snudde han um, og for heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Då Dans-sønerne hadde teke alle dei ting som Mika hadde kosta seg, og presten som var hjå honom, kom dei brått yver La’is, yver eit folk som livde roleg og ikkje kom i hug nokon fåre; folket øydde dei med odd og egg, og byen brende dei upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Og det var ingen som hjelpte; for dei budde langt ifrå Sidon, og hadde ikkje noko å gjera med anna folk. Byen låg i Bet-Rehobdalen. Dans-sønerne bygde honom upp att og vart buande der;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Dei kalla byen Dan etter ættefar sin, son åt Israel; fyrr heitte han La’is.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Der sette dei upp att gudsbilætet, og Jonatan, son åt Gersom, Moses’ son, var prest for Dans-ætti, og so var etterkomarane hans alt til den dagen då landet vart øydt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Gudsbilætet som Mika hadde gjort seg, vart standande hjå deim so lenge Guds hus var i Silo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'På denne tidi, den gongen då det ikkje fanst nokon konge i Israel, var det ein mann av Levi-ætti som budde lengst burte på Efraimsheidi. Han fekk seg ei fylgjekone frå Betlehem i Judafylket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Men kona var utru mot honom, og for ifrå honom og heim til far sin, til Betlehem i Juda. Der var ho eit bil, fire månader på lag;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'då for mannen hennar etter henne, og vilde tala vel med henne og få henne til å koma att; og han hadde med seg drengen sin og eit par asen. Den unge kona leidde honom inn i huset åt far sin, og då faren såg honom, vart han glad, og tok vel imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Og verfar hans, far åt den unge kona, heldt på honom, so han vart verande der i tri dagar, og dei åt og drakk og var der um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Tidleg den fjorde dagen gjorde mannen seg reidug og vilde fara i veg. Då sagde far åt den unge kona til mågen sin: «Få deg fyrst ein bite mat å kveikja deg på! Sidan kann de fara.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'So sette dei seg ned båe tvo og åt og drakk saman, og far åt den unge kona sagde til mannen: «Kjære, gjer vel og ver til morgons, og kosa deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Og då mannen reiste seg og vilde taka ut, nøydde verfaren honom so lenge til han gav seg og vart der um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Morgonen etter - det var den femte dagen - var han tidleg uppe, og vilde taka av stad. Då sagde far åt den unge kona: «Kjære, få deg fyrst noko å kveikja deg på og bia so til det lid yver middag!» So åt dei i hop, dei tvo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Sidan ferda mannen seg til, og vilde taka i vegen med fylgjekona si og drengen. Då sagde verfar hans, far åt den unge kona: «No lid det alt til kvelds! Kjære, bia til morgons! Sjå korleis dagen hallar! Ver her i natt, og kosa deg! I morgon kann de taka tidleg i vegen, so du kann koma heim att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Men mannen vilde ikkje gjeva seg til der um natti. Han gjorde tok ut, og for frametter til han kom midt for Jebus, det er det same som Jerusalem. Med seg hadde han eit par asen med klyv, og fylgjekona var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Då dei var innmed Jebus, var dagen langt liden, og drengen sagde til husbonden sin: «Kom, lat oss taka inn i jebusitarbyen her og vera der med natti!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, '«Nei, me vil ikkje taka inn i nokon by der det berre bur framande, og ikkje israelitar; me vil halda fram til Gibea,» svara husbonden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, '«Kom, lat oss sjå til å nå ein av dei byarne der burte, og få hus i Gibea eller Rama!» sagde han til drengen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'So heldt dei lenger fram, og då soli gladde, var dei tett ved Gibea i Benjaminsfylket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Der tok dei av vegen, og gjekk inn i byen og vilde få hus um natti. Då han kom inn i byen, sette han seg på torget; men det var ingen som baud seg til å gjeva dei hus for natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Då kom det ut på kvelden ein gamall mann heim frå marki, frå arbeidet sitt; han var frå Efraimsheidi, men heldt til i Gibea. Hitt folket der var benjaminitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Då han såg upp, vart han var ferdamannen på torget, og sagde til honom: «Kvar etlar du deg av, og kvar kjem du ifrå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, '«Me kjem frå Betlehem i Juda», svara hin, «og skal langt burt på Efraimsheidi; der er eg ifrå. Eg hev vore til Betlehem i Juda, og no er eg på vegen til Herrens hus; men her er ingen som vil hysa meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Eg hev både halm og for til asni våre, og brød og vin til meg og kona og drengen som er med oss; det vantar oss ingen ting.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, '«Ver velkomen,» sagde den gamle mannen; «lat berre meg syta for alt det du treng! Men på torget må du ikkje vera i natt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'So fylgde han den framande inn i huset sitt, og gav asni hans for, og då dei hadde tvege føterne sine, sette dei seg til bords.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Best dei sat og kosa seg, kom mennerne i byen, ukjor som dei var, og kringsette huset; dei dundra på døri og ropa til den gamle mannen som åtte huset: «Lat den karen som hev teke inn hjå deg koma ut, so me kann få vår vilje med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Då gjekk huseigaren ut til deim, og sagde: «Far ikkje so, godtfolk! Gjer ikkje vondt! Kom i hug at denne mannen er gjesten min, og gjer ikkje so stygg ei gjerning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Sjå her er dotter mi, som er møy, og fylgjekona hans; deim skal eg senda ut til dykk; so fær de taka deim og gjera med deim som de synest; men denne mannen må de ikkje fara so stygt med!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Men kararne vilde ikkje høyra på honom. Då tok den framande fylgjekona si, og leidde henne ut til deim, og dei låg med henne og skamfor henne heile natti, og slepte henne ikkje fyrr det leid imot morgonen og tok til å ljosna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'I dagrenningi kom kona, og seig i hop framfyre døri til det huset der husbonden hennar var; der vart ho liggjande til det var ljost.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Då husbonden hennar reis upp um morgonen, og let upp husdøri og gjekk ut, vilde fara sin veg, då låg kvinna, fylgjekona hans, framfyre husdøri, med henderne på dørstokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, '«Reis deg upp, og lat oss fara i veg!» sagde han. Men han fekk inkje svar. Då lyfte han henne upp på asnet, og tok ut, og for til si bygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Og då han kom heim, treiv han ein kniv, og tok fylgjekona si, og lema henne sund i tolv luter, og deim sende han kring i heile Israelsriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Og alle som såg det, sagde: «Slikt hev aldri hendt og aldri vore spurt, alt ifrå den dagen då Israels-sønerne for frå Egyptarland og til denne dag. Tenk etter, legg råd, og tala!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Då tok alle Israels-sønerne ut, og heile lyden, frå Dan til Be’erseba og frå Gileadlandet, samla seg alle som ein mann framfor Herren i Mispa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Og dei gjævaste av heile folket, av alle Israels ætter, steig fram der Guds folk heldt møte, fire hundrad tusund i talet, alle gangføre og våpnføre menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Men Benjamins-sønerne fekk spurt at Israels-sønerne var farne upp til Mispa. Då sagde Israels-sønerne: «Seg frå korleis denne ugjerningi hev gjenge til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Og leviten, mannen åt den kona som var drept, tok til ords og sagde: «Eg og fylgjekona mi kom til Gibea i Benjamin, og vilde få hus der med natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Men Gibea-mennerne baud vondt, og kringsette um natti huset eg var i; meg tenkte dei å drepa, og fylgjekona mi valdtok dei, so ho døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Då tok eg fylgjekona mi, og lema henne sund, og sende luterne kring i heile Israels land og rike; for dei hadde gjort eit illverk og ei ugjerning i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'No er de samla her, alle Israels menner! Kom no fram med dykkar meining og råd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Då reiste folket seg, alle som ein mann, og sagde: «Ingen av oss skal draga burt til sitt tjeld, og ingen fara heim til sitt hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Og so vil me gjera med Gibea: Byen skal under lutkast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'No tek me ut ti mann for kvart hundrad av alle Israels ætter, og hundrad for kvart tusund, og tusund for kvart titusund; dei skal henta mat til hermennerne, so dei, når dei kjem til Gibea i Benjamin, kann gjeva folket der like for den store ugjerningi dei hev gjort i Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'So samla dei seg, alle Israels menner, og drog imot byen, sameinte som ein mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Og Israels-ætterne sende bod kring til alle ættgreiner i Benjamin og sagde: «Kva er dette for ei ugjerning som er gjord hjå dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Send ut til oss dei ukjurorne i Gibea, so me kann slå deim i hel og rydja det vonde ut or Israel!» Men Benjamins-sønerne vilde ikkje høyra på Israels-sønerne, brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Dei kom i hop til Gibea frå alle bygderne sine, og vilde draga i strid mot Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Den dagen vart folket i Benjamins-bygderne mynstra: det var seks og tjuge tusund våpnføre mann, umfram Gibea-buarne; dei vart mynstra for seg, og var sju hundrad i talet, alle saman utvalde hermenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Millom alt det folket fanst det sju hundrad utvalde hermenner som var keivhendte; alle desse høvde på eit hår med slyngja; ingen kasta i mist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Benjamin frårekna, mynstra Israels-sønerne fire hundrad tusund våpnføre mann som alle var herfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Dei gjorde seg reiduge, og gjekk upp til Betel, og spurde Gud: «Kven av oss skal taka fyrst ut i striden mot Benjamins-sønerne?» «Juda skal fyrst,» svara Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Um morgonen braut Israels-sønerne upp, og lægra seg midt imot Gibea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'So gjekk dei fram til strid mot Benjamin, og fylkte heren sin imot deim burtåt Gibea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Då braut Benjamins-sønerne fram frå Gibea, og lagde den dagen tvo og tjuge tusund Israels-menner i marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, '[Stu21: 23] Og folket, Israels-mennerne, herde seg til, og fylkte seg atter på same staden som dei hadde fylkt seg fyrste gongen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, '[Stu21: 22] Israels-sønerne gjekk upp, og gret for Herrens åsyn heilt til kvelds, og dei spurde Herren: «Skal me ganga fram att og strida mot Benjamin, bror vår?» «Far imot honom!» svara Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'men då dei dagen etter gjekk fram imot Benjamins-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'for Benjamin andre gongen ut imot deim frå Gibea, og lagde endå attan tusund israelitar i marki, alle saman våpnføre menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Då gjekk alle Israels-sønerne, heile folket, upp til Betel; der sat dei gråtande for Herrens åsyn, og fasta heile den dagen, alt til kvelds; og dei ofra brennoffer og fredsoffer for Herrens åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'og spurde Herren. For den gongen stod Guds sambandskista der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Pinehas, son åt Eleazar og soneson åt Aron, gjorde den tid tenesta framfyr henne, og Israels-sønerne spurde: Skal me endå ein gong draga ut i striden mot Benjamin, bror vår, eller skal me lata vera? «Drag ut! I morgon vil eg gjeva honom i henderne dykkar,» svara Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Då lagde Israel folk i umsåt rundt ikring Gibea,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'og so for dei tridje venda mot Benjamins-sønerne, og fylkte seg burtåt Gibea, liksom dei fyrre gongerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Benjamins-sønerne for ut imot deim, og vart dregne burt ifrå byen; og liksom dei fyrre gongerne felte dei i fyrstningi nokre av folket på ålmannvegarne som ber uppetter, den eine til Betel og den andre yver marki til Gibea; det var um lag tretti Israels-menner dei fekk felt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Då sagde Benjamins-sønerne: «Dei ryk for oss no som fyrr!» Men Israels-sønerne sagde: «Lat oss røma, so me fær drege deim burt frå byen og ut på ålmannvegarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'So tok alle Israels-mennerne ut frå stødet sitt og fylkte seg i Ba’al-Tamar, med umsåtmennerne braut fram frå sitt støde vestanfor Geba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Og ti tusund utbladde stridsmenner av heile Israel gjekk beint mot Gibea. Då vart det ein hard strid; men Benjamins-sønerne visste ikkje at ulukka var tett innpå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Og Herren laga det so at Benjamin rauk for Israel; Israels-sønerne felte den dagen fem og tjuge tusund og eitt hundrad mann av Benjamins-ætti; alle desse var våpnføre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Benjamins-sønerne trudde fyrst at Israels-mennerne var slegne; for dei drog seg undan for Benjamin, men det var berre av di dei leit på umsåti dei hadde sett mot Gibea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Og no brårende umsåtmennerne fram mot Gibea, og trengde seg inn, og øydde heile byen med odd og egg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Israels-sønerne hadde gjort den avtalen med umsåtmennerne at dei skulde lata ein tett røyk stiga upp ifrå byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Då no Israels-sønerne snudde ryggen til i striden, og Benjamins-sønerne i fyrstningi felte nokre av deim - um lag tretti mann - og sagde: «Dei ryk for oss, som i den fyrste ota!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'då tok røyken til å stiga upp frå byen som ein stor stopul, og då benjaminitarne såg attum seg, fekk dei sjå at heile byen stod i ein loge, som slo upp mot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'I det same snudde Israels-mennerne um. Då vart Benjamins-mennerne forfærde; for dei såg at ulukka hadde nått deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Dei vende seg og tok vegen til øydemarki for å koma undan Israels-mennerne; men striden fylgde deim fot og fet, og jamvel midt i byarne vart dei nedhogne, dei som åtte heime der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Israels-mennerne ringa Benjamin inne, elte honom, og trakka honom ned der han kvilde, alt til dei var beint i aust for Gibea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Og det fall attan tusund mann av Benjamins-ætti; alle desse var djerve stridsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'So snudde dei um, og rømde til øydemarki, burtimot Rimmonshøgdi. Og Israels-mennerne felte på ålmannvegarne endå fem tusund mann; sidan sette dei etter deim til Gideon og felte tvo tusund til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'I alt var det fem og tjuge tusund våpnføre mann av Benjamins-ætti som fall den dagen; alle desse var djerve stridsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Då snudde dei um, og rømde ut i øydemarki, til Rimmonshøgdi, seks hundrad mann, og dei vart verande på Rimmonshøgdi i fire månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Men Israels-mennerne for attende til Benjaminslandet, og øydde det med odd og egg; både byarne med sine folk, og bufeet, og alt det dei fann, og alle byarne som fanst der, sette dei eld på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'I Mispa hadde Israels-mennerne svore: «Ingen av oss skal gjeva dotter si til nokon benjaminit!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Men då folket kom til Betel, sat dei der for Guds åsyn alt til det vart kveld, og dei storgret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'og sagde: «Herre, Israels Gud, kvi skulde dette henda i Israel at me i dag lyt sakna ei heil ætt av Israel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Tidleg den andre morgonen bygde folket eit altar der, og bar fram brennoffer og takkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Då sagde Israels-sønerne: «Var det millom heile Israels-folket nokon mann som ikkje kom upp til møtet hjå Herren?» For dei hadde svore sin dyraste eid at den som ikkje kom upp til Herren, til Mispa, han skulde lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Israels-sønerne syrgde yver Benjamin, bror sin, og sagde: «I dag er det hoggi burt ei heil grein av Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Kva skal me gjera for dei som att er, so dei kann få seg konor, når me hev svore ved Herren at me ikkje vil gjeva dei nokor av døtterne våre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'So spurde dei att: «Var det nokon mann av Israels-folket som ikkje kom upp til Herren i Mispa?» Då fekk dei vita at frå Jabes i Gilead var ingen komen til lægret eller til møtet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'folket vart mynstra, og då synte det seg at ingen av Jabes-buarne frå Gilead var der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'So sende lyden tolv tusund stridsmenner dit, og sagde til deim: «Far av stad og hogg ned Jabes-buarne i Gilead med konor og born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Høyr no kva de skal gjera: Kvar karmann, og kvar kvinna som hev vore nær nokon karmann og havt samlega med honom, skal de bannstøyta og rydja ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Då fann dei millom Jabes-buarne i Gilead fire hundrad ungmøyar som aldri hadde vore nær nokon mann og havt samlega med honom, og deim tok dei med seg til lægret i Silo i Kana’ans-land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Og heile lyden sende bod til Benjamins-sønerne som var på Rimmonshøgdi, og lova deim fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Då kom benjaminitarne att med ein gong, og Israels-mennerne let deim få dei kvinnorne som dei hadde spart etter av Jabes-folket i Gilead; men det rakk ikkje til for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Og folket syrgde endå yver Benjamin; for Herren hadde hogge eit skard i Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Og styresmennerne for lyden sagde: «Kva skal me gjera for deim som att er, so dei kann få seg konor, sidan alle kvinnor i Benjamins-ætti er utrudde?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Dei som liver etter av Benjamin, skal få det som ætti hev ått,» sagde dei; «for ei ætt av Israel må ikkje ganga til grunnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Men me kann ikkje gjeva deim nokor av døtterne våre.» For Israels-sønerne hadde lyst ei våbøn, og sagt: «Forbanna vere den som gjev dotter si til ein benjaminit!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, '«Men høyr no!» sagde dei: «År um anna held dei ei høgtid for Herren i Silo, som ligg nordanfor Betel, austanfor storvegen som ber frå Betel upp til Sikem, og sunnanfor Lebona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Far dit», sagde dei til Benjamins-sønerne, «og legg dykk på lur i vinhagarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Når de då ser at Silo-møyarne kjem ut og trør dansen, skal de springa fram or vinhagarne og rana dykk kvar si kona millom Silo-møyarne, og so fara heim til Benjaminslandet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Og når federne eller brørne deira kjem og kjærer seg for oss, so skal me segja til deim: «Unn oss desse møyarne! For me vann ikkje konor åt deim alle i striden. Og det er ikkje de som hev gjeve deim møyarne; elles hadde de no havt skuld på dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Og Benjamins-sønerne gjorde so, og henta seg kvar si kona millom møyarne som dei rana på dansarvollen. So for dei heim att til odelslandet sitt, og bygde upp att byarne og vart buande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'På same tid drog Israels-sønerne og burt derifrå, kvar til si bygd og si ætt; kvar for heim til sin odelsgard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'I dei dagar var det ingen konge i Israel; kvar gjorde som han hadde hug til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'I den tidi då domarane styrde, vart det uår i landet. Då for ein mann frå Betlehem i Juda i veg med kona si og båe sønerne sine og vilde bu i Moablandet ei stund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Mannen heitte Elimelek og kona hans No’omi, og dei tvo sønerne Mahlon og Kiljon; dei var efratitar, frå Betlehem i Juda. No kom dei då til Moablandet og vart veranda der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Og Elimelek, mannen hennar No’omi, døydde; men ho livde att med dei tvo sønerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Sønerne tok seg konor frå Moablandet; den eine heitte Orpa og den andre Rut. Og dei budde der på lag ti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Då døydde både Mahlon og Kiljon, og kvinna livde att etter sønerne sine og mannen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Då budde ho seg til å fara heim att frå Moablandet med sonekonorne sine; for ho hadde høyrt i Moablandet at Herren hadde set um folket sitt og gjeve deim brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'So gav ho seg i veg frå den staden der ho hadde butt, ho og båe sonekonorne hennar. Då dei var komne eit stykke på vegen heim til Judalandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'då sagde No’omi til sonekonorne sine: «Snu no og gakk heim att kvar til si mor! Herren vere miskunnsam mot dykk, so som de hev vore mot båe dei avlidne og mot meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Herren gjeve at de må finna ro, kvar i huset hjå sin mann!» So kysste ho deim; men dei tok til å gråta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'og sagde til henne: «Nei, me vil fylgja med deg attende til folket ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Men No’omi svara: «Snu att, døtterne mine; kvifor skulde de ganga med meg? Kann eg endå få søner i mitt liv som kunde verta menner åt dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Snu, døtterne mine, og gakk heim att! for eg er for gamall til å gifta meg att. Og um so var at eg kunde tenkja: «Eg hev endå von,» ja um eg so alt i natt gav meg åt ein mann, og so vart at eg fødde søner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'skulde so de bia til dei vart fullvaksne? skulde so de stengja dykk inne og liva utan menner? Nei, døtterne mine, eg tykkjer synd i dykk, for meg hev Herrens hand råma.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Då tok dei til å gråta att, og Orpa kysste vermor si til avskil, men Rut vilde ikkje slite seg laus frå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Då sagde ho: Sjå, versyster di hev snutt heim att til folket sitt og til sin gud. Snu no du og, og fylg versyster di!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Men Rut svara: «Ikkje tel meg til å snu att og ganga frå deg! for der du gjeng, vil eg og ganga, og der du stanar, der vil eg og stana. Ditt folk er mitt folk, og din Gud er min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Der du døyr, vil eg og døy, og der vil eg verta jorda. Herren late meg bøta for det no og sidan, um noko anna enn dauden skulde skilja meg frå deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Då ho no såg at ho stod fast på sitt og vilde vera med henne, tala ho ikkje meir med henne um dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'So gjekk dei saman til dei kom til Betlehem. Og då dei kom til Betlehem, kom heile byen i rørsla for deira skuld, og kvinnorne sagde: «Er dette No’omi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Men ho sagde til deim: «Kalla meg ikkje No’omi, men kalla meg Mara, for Den Allmegtige hev late mykje sorg koma yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Rik for eg herifrå, og tomhendt hev Herren late meg koma att. Kvifor kallar de meg No’omi då når Herren hev vitna mot meg, og den Allmegtige hev late det ganga meg so ille?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'So kom då No’omi heim att frå Moabland med sonekona si, moabitkvinna Rut, og dei kom til Betlehem då dei tok til med skurdonni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Det var ein frende åt mannen til No’omi, ein rik mann av ætti hans Elimelek; han heitte Boaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Og moabitkvinna Rut sagde til No’omi: «Lat meg ganga ut på åkeren og plukka aks etter einkvan som syner seg venleg mot meg!» Ho svara: «Ja, gjer det, du dotter mi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'So gjekk ho då av stad og kom til ein åker og plukka aks der etter skurdfolket, og det høvde seg so til at åkerstykket høyrde Boaz til, han som var av ætti hans Elimelek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Og Boaz kom nett då dit frå Betlehem, og han sagde til skurdfolket: «Herren vere med dykk!» Dei svara honom: «Herren velsigne deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Og Boaz spurde den drengen som hadde tilsyn med skurdfolket: «Kven høyrer ho til denne unge kvinna?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Drengen som hadde tilsyn med skurdfolket, svara og sagde: «Det er ei moabitkvinna, ho som fylgde med No’omi hit frå Moablandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Ho spurde um ho kunde få plukka og henta i hop aks millom kornbandi etter skurdfolket, og so kom ho, og hev halde på sidan i dag tidleg alt til no og ikkje kvilt det slag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Då sagde Boaz til Rut: «Høyr, dotter mi! Du skal ikkje ganga stad og plukka aks på nokon annan åker; gakk ikkje her ifrå heller, men haldt deg åt tenestgjentorne mine her!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Ansa etter kvar skurdfolket arbeider på åkeren, og gakk etter deim! Eg hev sagt åt drengjerne at dei ikkje skal gjera deg noko vondt. Og um du vert tyrst, so gakk burt åt kjeri og drikk av det vatnet drengjerne hentar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Då kasta ho seg ned med andlitet mot jordi og sagde til honom: «Kvifor hev eg funne slik nåde for augo dine, at du tek deg av meg som er framand?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boaz svara og sagde til henne: «Dei hev fortalt meg kva du hev gjort mot vermor di, etterat mannen din var avliden, korleis du hev forlate far din og mor di og fedrelandet ditt og fare til eit folk som du fyrr ikkje kjende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Herren løne deg for det du hev gjort, ja måtte du få fullt vederlag av Herren, Israels Gud, han som du hev kome til, for å finna livd under vengjerne hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Ho sagde: «So må eg då finna nåde for augo dine, herre; etter di du hev trøysta meg og tala venleg med tenestgjenta di, endå eg ikkje ein gong er so mykje som ei av tenestgjentorne dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Då det leid til måls, sagde Boaz til henne: «Kom hit og et av brødet, og stikk brødstykket ditt ned i vinen!» Då sette ho seg attmed skurdfolket, og han lagde fram åt henne brunsteikte aks, og ho åt og vart mett, og hadde endå att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Då ho stod upp og skulde plukka aks, sagde Boaz til drengjerne sine: «Lat henne og plukka aks millom kornbandi, og gjer henne ikkje noko til mein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Ja, de kann gjerne draga ut strå or bandi og lata deim liggja, so ho fær plukka deim upp, og ingen skal vera vond på henne for det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'So plukka ho aks på åkeren alt til kvelds. Og då ho banka or det ho hadde plukka, vart det på lag ein skjeppa bygg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Og ho tok byrdi si og gjekk inn i byen, og vermor hennar fekk sjå kva ho hadde plukka. So tok ho fram og gav henne det som vart att då ho hadde ete seg mett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Då sagde vermor hennar til henne: «Kvar hev du plukka aks i dag, og kvar hev du arbeidt? Velsigna vere han som hev hjelpt deg til det!» So fortalde ho vermor si kven ho hadde arbeidt hjå, og sagde: «Den mannen som eg hev arbeidt hjå i dag, heiter Boaz.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Då sagde No’omi til sonekona si: «Herren velsigne honom, for di han gjer miskunn både mot deim som liver og dei avlidne!» Og No’omi sagde til henne: «Denne mannen er av frendarne våre, ein av løysingsmennerne våre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Moabitkvinna Rut sagde: «Han sagde og til meg: Haldt deg åt drengjerne mine til dei hev gjort frå seg all skurden min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Då sagde No’omi til Rut, sonekona si: «Ja, det er best, dotter mi, at du gjeng med tenestgjentorne hans; so dei ikkje skal gjera deg noko vondt på ein annan åker.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'So heldt ho seg åt tenestgjentorne hans Boaz og plukka aks der til dei vart ferdige både med bygg- og kveiteskurden. Men ho budde hjå vermor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Og No’omi, vermor hennar, sagde til henne: «Dotter mi, eg vil sjå til å hjelpa deg, so du kann finna ein kvilestad, der du kann få det godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Høyr no: Boaz, som du hev vore saman med tenestgjentorne åt, han er frenden vår. No i natt kastar han bygg på treskjestaden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Vaska deg no og salva deg; klæd so på deg og gakk ned på plassen. Men lat honom ikkje sjå deg fyrr han hev ete og drukke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Når han legg seg, sjå so etter kvar han legg seg. Gakk dit og lyft upp klædet nedmed føterne hans, og legg deg der! då vil han segja deg sjølv kva du skal gjera!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Ho svara henne: «Alt det du segjer, vil eg gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Og ho gjekk ho ned på treskjarplassen og gjorde alt so som vermor hennar hadde sagt ho skulle gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Då Boaz hadde ete og drukke, var han i godlag og lagde seg attmed kornhaugen; då gjekk ho stilt dit og lyfte upp klædet nedmed føterne hans, og lagde seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Ved midnattsleite vart mannen uppskræmd og bøygde seg framyver, og so fekk han sjå at det låg ei kvinna nedmed føterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, '«Kven er du?» sagde han. Ho svara: «Eg er Rut, trælkvinna di; breid ut vengjerne dine yver trælkvinna di, for du er løysingsmannen min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Då sagde han: «Herren velsigne deg, dotter mi! Du hev no synt større kjærleik enn fyrr, for du hev ikkje rent etter unge menner, korkje fatige eller rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Ver no ikkje rædd, dotter mi! Alt det du segjer, vil eg gjera; for alt folket i byen veit at du er ei dygdefull kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Det er no sant og visst at eg er løysingsmannen din; men det er ein annan løysingsmann som er næmare enn eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Ver no her i natt; vil han då i morgon løysa deg, so lat honom gjera det; men hev han ikkje hug til å løysa deg, so skal eg gjera det, so sant Herren liver! Ligg no her til morgons!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'So låg ho då nedmed føterne hans til morgons; men ho stod upp fyrr den eine kunde skilja den andre greidt; for han tenkte: «Det må ikkje nokon vita at kvinna hev kome hit til treskjarplassen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Og han sagde: Kom med kåpa du hev på deg, og haldt henne fram!» Og ho hene fram. Då mælte han i seks mål bygg og gav henne; dermed gjekk ho inn i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Og då ho kom til vermor si, sagde ho: «Korleis hev det gjenge, dotter mi?» Då fortalde ho henne alt det mannen hadde gjort mot henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Og ho sagde: «Desse seks måli med bygg gav han meg og sagde: «Du skal ikkje koma tomhendt heim til vermor di.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Då svara ho: «Haldt deg no roleg, dotter mi, til du fær sjå korleis det gjeng! for den mannen gjev seg ikkje fyrr han fær avgjort saki i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Og Boaz hadde gjenge upp på tinget og sett seg der. Då høvde det so at den løysingsmannen som Boaz hadde tala um, gjekk framum der. Han tala åt honom og sagde: «Kom hit og set deg her!» Og han kom og sette seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'So tok han burtåt seg ti av styresmennerne i byen og sagde: «Set dykk her!» Og dei sette seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Då sagde han til løysingsmannen: «Det åkerstykket som høyrde Elimelek, bror vår, til, vil No’omi selja, ho som hev kome att frå Moablandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Difor tenkte eg at eg skulde fortelja deg det og segja: Kjøp det du når dei er til stades dei som sit her, og styresmennerne for folket mitt! Vil du taka det etter løysingsretten, so gjer det; vil du ikkje løysa det, då seg meg det, so eg fær vita det; for ingen annan eig løysingsretten enn du, og næst etter deg er det eg sjølv.» Han sagde: «Eg vil løysa det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Då sagde Boaz: «Når du kjøper åkeren av No’omi, so kjøper du honom og av moabitkvinna Rut, kona åt den avlidne, og du skyldar å reisa upp att namnet åt den avlidne, og festa det til arvluten hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Løysingsmannen svara: «Då kann eg ikkje nytta løysingsretten min, for so spiller eg min eigen arvlut. Løys du åt deg det eg skulde ha løyst, for eg kann ikkje gjera det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Det var gamall sed i Israel når ein mann skulde stadfesta ei løysing eller eit avtala byte, då drog han av seg skoen og gav honom til den andre, og dette gjaldt som ein vitnesburd i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Då sagde løysingsmannen til Boaz: «Kjøp det du!» og so drog han av seg skoen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Boaz sagde no til styresmennerne og til alt folket: «De er i dag vitne på at eg hev kjøpt av No’omi alt det som hev høyrt Elimelek til, og alt som hev høyrt Kiljon og Mahlon til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Like eins hev eg kjøpt moabitkvinna Rut, kona hans Mahlon, til kona åt meg, so eg kann reisa namnet åt den avlidne og festa det til arvluten hans, so namnet hans ikkje kjem burt millom brørne hans eller frå porten på heimstaden hans. De er vitne på dette i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Og alt folket som var på tinget og styresmennerne sagde: «Ja, det er me. Herren gjeve at den kvinna som no gjeng inn i huset ditt, må verta som Rakel og Lea, dei tvo som hev bygt upp Israels hus! Og gjev du må koma til velmagt i Efrata og verta namngjeten i Betlehem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Og gjev at dei etterkomarar som Herren vil gjeva deg med denne unge kvinna, må verta ei ætt som ætti hans Peres, han som Tamar fødde åt Juda!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'So tok då Boaz Rut til seg, og ho vart kona hans; han gjekk inn til henne, og Herren gav henne livsfrukt, og ho fødde ein son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Då sagde kvinnorne til No’omi: «Lova vere Herren som hev gjort at du idag ikkje vantar løysingsmann! Han skal verta namngjeten i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Han skal verta ein trøystar åt deg og din alderdoms hjelp; for sonekona di, ho som held av deg, hev født honom; ho som er meir for deg enn sju søner.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Og No’omi tok barnet og lagde det i fanget sitt og vart fostermor åt det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Og grannekvinnorne gav honom namn og sagde: «No’omi hev fenge ein son,» og dei gav honom namnet Obed; Han vart far åt Isai, far åt David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Her er ættartalet hans Peres: Peres var far åt Hesron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hesron var far åt Ram, og Ram var far åt Amminadab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadab var far åt Nahson, og Nahson far åt Salma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon var far åt Boaz, og Boaz far åt Obed.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed var far åt Isai, og Isai far åt David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Elkana heitte ein mann, ein sufit som budde i Rama, på Efraimsheidi. Han var son åt Jeroham, son åt Elihu, son åt Tohu, son åt Suf, ein efraimit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Han hadde tvo konor; Hanna heitte den eine, Peninna heitte hi. Peninna hadde born, men Hanna var barnlaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'År etter år drog denne mannen upp frå byen sin, og tilbad og ofra i Silo til Herren, allhers drott. Der var dei tvo Eli-sønerne Hofni og Pinehas prestar for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Alltid når Elkana ofra, gav han Peninna, kona si, og alle sønerne og døtterne hennar kvar sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Men Hanna gav han ein lut for tvo; for han elska Hanna, endå Herren hadde stengt morslivet hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Og medtevlaren hennar erga og terga henne, og vilde øsa henne upp i egse, for di Herren hadde stengt morslivet hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Soleis gjorde han år etter år, kvar gong ho kom upp til Herrens hus; ho terga henne sameleis. Og då gret ho og vilde ikkje eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Elkana, mannen hennar, sagde til henne: «Hanna, kvifor græt du? og kvifor et du ikkje? Og kvifor er du so hugsjuk? Er ikkje eg meir for deg enn ti søner?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Ein gong dei hadde ete og drukke i Silo, reis Hanna upp - presten Eli sat på ein stol attmed den eine dørstolpen til Herrens heilagdom -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Og i hjartans sut bad ho til Herren og gret sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Og ho gjorde ein lovnad og sagde: «Herre, du allhers drott! vil du venda augo til vesaldomen åt trælkvinna di og tenkja på meg, og ikkje gløyma trælkvinna di, men gjeva trælkvinna di eit gutebarn, so vil eg vigja honom til Herren for alle hans livedagar, og aldri skal det koma saks på hovudet hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Ho heldt lenge på og bad framfor Herren. Og Eli fylgde munnen hennar med augo;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'for Hanna bad ikkje høgt; ho leda berre lipporne, men mælet høyrdest ikkje. So trudde Eli ho var drukki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Difor sagde til henne: «Kor lenge vil du syna deg drukki? Sjå til å få ruset til å siga av deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Men Hanna svara: «Nei, herre! eg er ei sorgtyngd kona. Vin og rusdrykk hev eg ikkje drukke; men eg hev rent ut hjarta mitt for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Haldt ikkje trælkvinna di for ei uvyrda! for det er utav stor sorg og trege eg hev tala heile tida.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eli svara og sagde: «Far i fred! Israels Gud skal gjeva deg det du hev bede honom um!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Då sagde ho: «Å gjev trælkvinna di må finna godvilje hjå deg!» So gjekk ho sin veg, og fekk seg mat, og ho synte ikkje suti si meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Morgonen etter reis dei upp tidleg og heldt bøn framfor Herren. So for dei attende og kom til Rama. Elkana budde saman med Hanna, kona si, og Herren kom henne i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Då det hadde lide ei tid, vart Hanna med barn, og åtte ein son, som ho kalla Samuel; «for», sagde ho, «eg hev bede Herren um honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Elkana drog upp med heile huslyden sin og ofra til Herren det årlege slagtofferet sitt, og offer han hadde lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Men Hanna drog ikkje med. Ho sagde til mannen sin: «Eg vil bia til dess vesleguten er avvand. Då vil eg føra honom med meg og syna honom fram for Herren, so han sidan kann halda til der alle dagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Elkana, mannen hennar, sagde med henne: «Gjer som du tykkjer best. Bia til dess du hev vant honom av. Berre Herren må gjera etter sitt ord!» So var kona att heime og hadde son sin til brjostet, til dess ho vande honom av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Men då han var avvand, tok ho honom med dit upp, og hadde med seg tri uksar, ei skjeppa mjøl og ei vinhit, og ho førde honom inn i Herrens hus i Silo. Men han var berre ein liten gut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Dei slagta uksen, og førde so vesleguten til Eli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Ho sagde: «Høyr, herre! so sant du liver, herre, so er eg den kona som stod her attmed deg og bad til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Um denne guten bad eg, og Herren høyrde bøni mi og gav meg det eg bad um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Difor gjev eg honom att til Herren, so han skal vera ei gåva frå Herren alle sine livedager.» Og dei bad til Herren der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Då bad Hanna og sagde: «Hjarta mitt frygdar seg i Herren, høgreist er hornet mitt i Herren. Med vidopen munn ropar eg mot fiendarne mine, for di eg fegnast for frelsa di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Ingen er heilag som Herren, ingen er til utan du. Det bid inkje berg som vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Slutta med kyt og kaute ord! Slepp ikkje agelause ord or munnen! For Herren er Gud som allting veit, og verki deim veg han vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Brosten vert bogen åt kjemporne, men dei ustøde fær styrkebelte på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Dei som fyrr fekk sin mette, lyt leiga seg burt for mat, men dei som svalt, svelt ikkje meir. Barnlaus kona fær borni sju, barnerik mor folnar og fåst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Herren er den som tek liv og gjev liv, han fører ned til Helheim og upp derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Herren er den som gjer arm og gjer rik. Han dreg ned, men lyfter ogso upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Han reiser den ringe or moldi, og lyfter den låge or søyla, og leider han til sætes millom hovdingar og gjev han eit æresæte. Grunnstolparne åt jordi høyrer Herren til, på deim han bygde manneheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Han held vakt og hegnar vegen åt dei gudlege, men gudlaust folk forferst i myrkret; for aldri mannen vinn med eigi magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Deim som strider imot Herren, skræmer han, i himmelen yver deim dundrar han. Herren dømer jordi frå ende til annan, han aukar krafti hjå kongen sin. Han hevjar hornet høgt åt den han salvar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Elkana for heim att til Rama. Men guten gjorde tenesta for Herren hjå presten Eli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Men sønerne åt Eli var uvyrdor; dei ansa ikkje Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'og ikkje heller kva prestarne med rette kunde krevja av folket. Kvar gong ein mann ofra slagtoffer, kom drengen åt presten medan kjøtet koka, og hadde ein tritinda gaffel i handi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'og stakk honom ned i gryta eller kjeraldet eller kjelen eller krukka; og alt som hekk fast på gaffelen, tok presten. Soleis for dei med alle israelitar som kom dit til Silo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Ja endå fyrr enn feittet var brent, kom prestedrengen og sagde til mannen som ofra: «Hit med steikjekjøt til presten! han vil ikkje hava kokt kjøt hjå deg, berre rått.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Um då mannen sagde: «Fyrst må eg brenna feittet; sidan kann du taka alt det du lyster!» svara han: «Nei, kom straks med det! Elles tek eg det med magt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Den ovstore syndi dei unge prestarne gjorde beint i augo på Herren; vart so mykje større av di dei lærde folket svivyrda offeret til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel gjorde tenesta for Herrens åsyn. Alt medan han var smågut, var han klædd i ein messehakel av lin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Dessutan laga mor hans ein liten kjole kvart år honom og hadde med seg, når ho kom med mannen sin og ofra det årvisse slagtofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Då velsigna Eli Elkana og kona hans og sagde: «Herren gjeve deg fleire born med denne kona, i staden for honom som ho hev bede um i bøn til Herren!» So for dei heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Og Herren kom i hug Hanna, og ho vart med barn og åtte tri søner og tvo døtter. Men guten Samuel voks upp hjå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli var svært gamall. Han høyrde gjete alt det sønerne hans gjorde mot heile Israel, og at dei låg med dei kvinnorne som gjorde tenesta ved inngangen til møtetjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Og han sagde då: «Kvifor fer de soleis åt? Eg høyrer heile folket talar um all den vonde framferdi dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Gjer ikkje so, sønerne mine! det hev ikkje noko godt lov, so som eg høyrer ordet gjeng um dykk frå mann til mann millom Herrens folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Når folk syndar mot einannan, so dømer Gud deim imillom. Men når nokon syndar mot Herren, kven skal då ganga imillom?» Men dei lydde ikkje på ordi åt far sin; for Herren hadde etla deim til å døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Men guten Samuel voks og mannast, og vann godhug både hjå Gud og menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Ein gudsmann kom då til Eli og sagde til honom: «So segjer Herren: «For farsætti di openberra eg meg den tid dei var i Egyptarland og træla for Faraos hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Eg valde henne millom alle Israels ætter til prestenesta mi, til å ofra på altaret mitt og brenna røykjelse og bera messehakel for mi åsyn. Og eg gav farsætti di offerretterne frå Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Kvifor trakkar de då på slagtofferi og grjonofferi mine som eg skipa til i min bustad? Kor kann du æra sønerne dine meir enn meg, so det godnar dykk med det beste av kvar offergåva som Israel, folket mitt, ber fram?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Difor lyder ordet frå Herren, Israels Gud: «Vel hev eg sagt: Di ætt og farsætti di skal få gjera tenesta for mi åsyn alltid og æveleg.» Men no lyder Herrens ord: «Aldri i verdi! deim som ærar meg, deim vil eg æra; dei som vanvyrder meg, skal verta til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Sjå dei dagar kjem då eg høgg av din arm og armen åt farsætti di, so ingen vert gamall i ætti di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Og du skal sjå Guds bustad i naud, endå so mykje godt Herren gjer mot Israel. Og ingen skal nokon sinne verta gamall i ætti di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Berre ein einaste av di ætt vil eg ikkje rydja burt frå altaret mitt, so eg sløkkjer ut augo dine, og syg mergen or beini dine; og alle som veks upp i ditt hus, skal døy i dei beste manndomsåri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Og det skal du hava til merke, det som kjem yver sønerne dine, Hofni og Pinehas: på ein dag skal dei båe døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Eg vil reisa meg upp ein pålitande prest som gjer etter min hug og vilje. Åt honom vil eg byggja eit traust hus, so han allstødt skal gjera tenesta framfor den eg salvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Då vil det henda at alle som vert att i ætti di, kjem og kastar seg å gruve for honom og tiggar um ein skilling eller ein brødleiv, og segjer: «Kjære væne, set meg til medhjelpar i eit av preste-embætti dine, so eg kann få ein bite mat å eta!»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Guten Samuel gjorde tenesta for Herren hjå Eli. Herrens ord var dyrt i dei dagarne, og profetsynerne var sjeldfengde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Då bar det so til med Eli låg i det vanlege kvileromet sitt - han tok til å dimmast på syni, so han ikkje kunde skilja -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'og dei endå ikkje hadde sløkt Guds lampa, og Samuel sov i Herrens heilagdom, der Guds kista stod:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'då ropa Herren på Samuel, og han svara: «Ja, her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Han sprang til Eli og sagde: «Her er eg, du ropa på meg.» Han svara: «Nei, eg ropa ikkje; gakk og legg deg att!» Han gjekk og lagde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Herren ropa ein gong til: «Samuel!» Samuel reis upp og gjekk til Eli og sagde: «Ja, her er eg, du ropa på meg!» Han svara: «Nei, eg ropa ikkje, guten min! gakk og legg deg att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel hadde ikkje endå lært å kjenna Herren; Herrens ord hadde ikkje openberra seg for honom endå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Tridje venda heldt Herren fram og ropa på Samuel. Han reis upp og gjekk til Eli og sagde: «Ja, her er eg, du ropa på meg.» Då skyna Eli det var Herren som ropa på guten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Og Eli sagde til Samuel: «Gakk du og legg deg! Hender det so at einkvan ropar på deg, skal du svara: «Tala, Herre! tenaren din høyrer!»» Samuel gjekk og lagde seg i romet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Då so Herren gjekk innåt og ropa som gongerne fyrr: «Samuel, Samuel!» då svara Samuel: «Tala, Herre! tenaren din høyrer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Då sagde Herren til Samuel: «Eg kjem til å gjera verk i Israel som kjem til å ringja for båe øyro på deim som høyrer det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'På den dagen skal eg lata koma yver Eli alt det eg hev tala um ætti hans, frå fyrst til sist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Eg hev kunngjort for honom at eg vil døma ætti hans til æveleg tid, for den misgjerning som han visste um, at sønerne hans drog forbanning yver seg, og likevel aga han deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Difor hev eg svore Eli-ætti: «Aldri i æva skal syndi i Eli-ætti kunna sonast antan med slagtoffer eller noko anna offer.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel vart liggjande til morgons, då han skulde opna dørerne til Herrens hus. Samuel torde ikkje fortelja Eli um syni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Men Eli ropa på Samuel, og sagde: «Samuel, guten min!» Han svara: «Her er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Han sagde: «Kva var det Gud tala til deg? Kjære, dyl det ikkje for meg! Gud late deg bøta no og sidan, dersom du løynar noko for meg av det han tala til deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'So fortalde Samuel alt saman, og løynde ingen ting for honom. Eli svara: Han er Herren. Han gjere som tekkjest honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel voks til, og Herren, var med honom, og let ikkje eitt av alle sine ord falla til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Heile Israel frå Dan til Be’erseba skyna at Samuel var utvald til profet for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Og Herren heldt fram med å syna seg i Silo. For Herren openberra seg for Samuel i Silo gjenom Herrens ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Og heile Israel høyrde Samuels ord. Israel drog ut til strid mot filistarane og lægra seg ved Eben-Ezer, medan filistarane lægra seg i Afek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Filistarane fylkte heren sin mot Israel, og striden vart drjug. Og Israel tapte for filistarane; dei felte umlag fire tusund mann på vigvollen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Då no folket kom att til lægret, sagde dei øvste i Israel: «Kvifor hev Herren late filistarane slå oss i dag? Lat oss henta Herrens sambandskista frå Silo, so ho kann vera her hjå oss og frelsa oss frå fiendarne våre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Folket sende bod til Silo og tok derifrå sambandskista åt Herren, allhers drott, han som tronar yver kerubarne. Og dei tvo Eli-sønerne, Hofni og Pinehas, fylgde med Guds sambandskista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Då Herrens sambandskista kom til lægret, då losna det so stort eit fagnadrop frå heile Israel, at jordi dunde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Då filistarane høyrde ljoden av fagnadropet, sagde dei: «Kva tyder dette glymjande fagnadropet i hebræarlægret?» Og då dei vart vise med at Herrens kista var komi til lægret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'vart dei forfærde; for dei tenkte: «Gud er komen til lægret.» Og dei sagde: «Usæle me! sovore hev aldri hendt fyrr!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Usæle me! kven skal frelsa oss frå denne velduge Guden? Det var denne Guden som sende alle ulukkorne yver egyptarane i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Men - manna dykk upp! og far fram på kara vis, filistarar, so ikkje de skal verta trælar for hebræarane, liksom dei hev vore trælar for oss! Ver no karar, og gakk på!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Filistarane kasta seg inn i striden; Israels-sønerne vart slegne, og lagde på sprang kvar til sitt, og mannefallet vart øgjelegt stort; av Israel fall tretti tusund mann fotfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Og Guds kista fall i fiendehand, og Hofni og Pinehas, båe Eli-sønerne, let livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Ein mann av Benjamin sprang frå slagmarki og nådde Silo same dagen, med sundrivne klæde og mold på hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Då han kom dit, sat Eli på stolen sin attmed byporten og einstirde utetter vegen; for hjarta hans bivra av otte for Guds kista. Då mannen kom inn i byen med denne tidendi, tok heile byen til å jamra og klaga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Og då Eli høyrde ljoden av klageropet, spurde han: «Kva tyder dette ståket eg høyrer?» Mannen skunda seg burtåt og fortalde det med Eli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Eli var åtte og nitti år gamall og star-blind, so han inkje kunde sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Mannen sagde til Eli: «Det er eg som kjem frå slagmarki, eg hev rømt frå striden i dag.» Han spurde: «Korleis hev det gjenge då, guten min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Bodberaren svara: «Israel rømde for filistarane, det vart stort mannefall på folket, Hofni og Pinehas, sønerne dine, er falne, og Guds kista hev falle i fiendehand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Då han nemnde Guds kista, datt Eli attlenges av stolen attmed byporten og braut halsbeinet. Det vart banen hans; for mannen var gamall og før. Han hadde då vore domar i Israel i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Verdotter hans, kona åt Pinehas, var med barn og gjekk på fallande føter. Då ho høyrde gjete at Guds kista var falli i fiendehand, og at verfaren og mannen hennar hadde late livet, so seig ho i kne og fødde; for føderiderne kom yver henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Då ho var mest inni dauden, sagde kvendi som stod ikring henne: «Ver hugheil! du hev fenge ein son.» Men ho svara inkje, og agta ikkje på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Ho kalla guten I-kabod: «Kvorven er herlegdomen frå Israel,» sagde ho. Ho kom i hug Guds kista som var falli i fiendehand, og so verfaren og mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, '«Kvorven er herlegdomen frå Israel,» sagde ho, «for Guds kista var falli i fiendehand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Filistarane tok Guds kista og førde henne frå Eben-Ezer til Asdod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Der tok filistarane Guds sambandskista og bar henne inn i Dagons tempel og sette henne attmed Dagon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Då Asdod-folki kom dit tidleg morgonen etter, fekk dei sjå Dagon liggja å gruve på golvet framanfor Herrens kista; dei tok då Dagon og sette honom på staden sin att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Men då dei kom tidleg næste morgon, fann dei Dagon liggjande å gruve framfor Herrens kista, og hovudet og båe henderne hans var avbrotne og låg på dørstokken; berre bulen var att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Difor er det so i Asdod den dag i dag, at ingen trøder på Dagons dørstokk, korkje nokon av Dagons-prestarne eller nokon annan som gjeng inn i Dagons tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Herrens hand låg tung på Asdod-folki; og han øyde deim og søkte deim med svullsott både i Asdodbyen og i kverven umkring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Då Asdod-buarne skyna korleis det hekk i hop, sagde dei: «Kista åt Israels Gud må ikkje lenger vera hjå oss; for handi hans ligg tung på oss og på Dagon, guden vår.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Dei sende då bod og stemnde saman til seg alle filistarfyrstarne, og spurde deim kva dei skulde gjera med kista åt Israels Gud. Dei svara: «Me lyt flytja kista åt Israels Gud til Gat.» Og dei so gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Men etter dei hadde flutt henne dit, kom Herrens hand yver byen og fjetra deim reint. Og han søkte byfolket med sott, so det braut ut svullar på både små og store.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Dei sende då Guds kista til Ekron. Men då Guds kista kom dit, skreik Ekron-buarne og sagde: «No hev dei flutt kista åt Israels Gud til meg og vil drepa meg og folket mitt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Dei sende då bod og stemnde alle filistarfyrstarne saman og sagde: «Send burt kista åt Israels Gud, og lat henne koma heim att til rette staden sin, og ikkje tyna meg og folket mitt!» Ein daudsens angest hadde gripe heile byen; for Guds hand låg ovtung på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Dei folki som ikkje døydde, vart søkte med svullsot. Og klageropet frå byen steig upp til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Då Herrens kista hadde vore sju månader i Filistarlandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'kalla filistarane saman prestarne og spåmennerne sine, og spurde: «Kva skal me gjera med Guds kista? Seg oss korleis me skal sende henne heim att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Dei svara: «Vil de senda burt kista åt Israels Gud, må de ikkje senda henne gåvelaus; de lyt bera sonoffer åt honom til vederlag; so vert de lækte, og det vil få vita kvifor handi hans ikkje hev vike frå dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Dei spurde då: «Kva sonoffer skal me gjeva honom?» Dei svara: «Fem svullar av gull og fem myser av gull, like mange som filistarfyrstarne; for de hev alle vore ute for same plåga, fyrstarne dykkar ogso.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'De skal laga likner av svullarne dykkar og likner av mysene som legg landet i øyde, og soleis gjeva Israels Gud æra. Kann henda han då tek burt si tunge handi frå dykk, frå guden dykkar og frå landet dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Kvifor skal de herda dykk til, liksom egyptarane og Farao gjorde? Laut dei ikkje sleppa Israel av stad, etter han hadde fare ille med deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Tak no og gjer ei ny vogn, og tak tvo kyr som gjev suga og som aldri hev bore ok! So skal det setja deim for vogni, men taka frå deim kalvarne og lata deim vera heime.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Tak so Herrens kista og set henne på vogni, og legg gulltyet som de gjev honom til sonoffer i ein kistel ved sida av henne, og send henne av garde soleis!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'So skal de sjå etter: tek ho vegen heim att til Bet-Semes; so er det han som hev valda oss all denne store ulukka. Men gjer ho ikkje det, veit me det er ikkje hans hand som hev slege oss; men ein vanlagnad som me hev vore ute fyre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Folket so gjorde: dei tok tvo kyr som gav suga, og sette deim for vogni, men kalvarne stengde dei inne heime.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Dei sette Herrens kista på vogni, og attmed henne kistelen med myserne av gull og liknerne av svullarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Og kyrne for beine vegen fram heilt til Bet-Semes. Dei heldt seg jamt til ålmannvegen, og gjekk i eitt rautande, og bøygde korkje til høgre eller vinstre. Og filistarfyrstarne fylgde etter, alt til landskilet ved Bet-Semes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Bet-Semes-buarne var ute på kveitehausting i dalen. Då dei såg upp, gådde dei sambandskista; og dei vart fegne då dei såg henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Og då vogni kom inn på åkeren til ein Bet-Semes-bonde, Josva, stogga ho der. Der var ein stor stein. Og dei hogg sund treverket på vogni og ofra kyrne til brennoffer for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Levitarne tok og lyfte ned Herrens kista og kistelen som stod attmed, og som gulltyet var i, og sette deim på den store steinen. Bet-Semes-buarne ofra brennoffer og slagta slagtoffer til Herren den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Då dei fem filistarfyrstarne hadde skoda på dette, snudde dei heim att til Ekron same dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Dette var dei gullsvullarne som filistarane gav i soningsgåva til Herren: ein for Asdod, ein for Gaza, ein for Askalon, ein for Gat, ein for Ekron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Og myserne av gull var likso mange som alle filistarbyarne - både festningsbyar og landsbyar - under dei fem fyrstarne. Den store steinen der dei sette Herrens kista, er vitne um dette til no, på åkeren til Bet-Semes-bonden Josva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Sume av folket i Bet-Semes fekk ogso sott, av di dei hadde skoda på Herrens kista: sytti mann av folket. Folket syrgde, av di Herren hadde gjort so stort mannefall millom folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Og Bet-Semes-buarne sagde: «Kven kann standa seg for Herren, den heilage Gud? og kven vil han no heimsøkja når han dreg upp frå oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Dei sende bod til deim som budde i Kirjat-Jearim, og sagde: «Filistarane hev sendt heim att Herrens kista. Kom hit ned og før henne upp til dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'So kom då folk frå Kirjat-Jearim og henta Herrens kista dit upp og sette henne inn i Abinadabs hus på haugen. Dei helga Eleazar, son hans, til å vakta Herrens kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Frå den dagen då kista kom til Kirjat-Jearim, leid det lang tid: tjuge år. Og heile Israels-ætti sukka etter Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Då tala Samuel til heile Israels-ætti: «Vil de venda um til Herren av heile dykkar hug, so skil dykk med dei framande gudarne og Astarte-bilæti! vend hugen dykkar til Herren, og ten einast honom, so skal han fria dykk frå filistarmagti;»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Då skilde Israels-borni seg bilæti av Ba’al og Astarte og tente einast Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Samuel sagde: «Stemne heile Israel i Mispa, so vil eg beda for dykk til Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Då samla dei seg saman i Mispa, henta vatn og dei auste ut for Herren, og dei fasta heile den dagen og sagde: «Me hev synda mot Herren.» So heldt Samuel dom i Mispa og skilde trættor millom Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Då filistarane frette at Israels-borni hadde samla seg i Mispa, drog filistarfyrstarne dit upp mot Israel. Då Israel høyrde gjete det, vart dei rædde for filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Og Israels-borni sagde til Samuel: «Haldt ved i eino og ropa til Herren, vår Gud, at han må frelsa oss ut or filistarmagti!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Då tok Samuel eit soglamb og ofra det til eit brennoffer, eit heiloffer for Herren. Og Samuel ropa til Herren for Israel. Og Herren høyrde bøni hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Medan Samuel ofra brennofferet, drog filistarane fram til strid mot Israel. Men Herren dundra med eit veldugt torever yver filistarane den dagen og fjetra deim, so dei vart slegne av Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Israels mannskap drog ut frå Mispa og forfylgde filistarane og hogg deim ned på flugti, alt til dei kom nedanfor Bet-Kar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Då tok Samuel ein stein og sette millom Mispa og Sen, og kalla honom Eben-Ezer og sagde: «Til no hev Herren hjelpt oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Soleis laut filistarane bøygja seg, og kom ikkje meir innanfor landskilet åt Israel. Og Herrens hand var mot filistarane so lenge Samuel livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Dei byarne som filistarane hadde teke frå Israel, fekk Israel att, frå Ekron til Gat; og kverven derikring tok Israel ogso att frå filistarane. Og millom Israel og amoritarne vart det fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel var domar i Israel so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Kvart år ferdast han rundt til Betel, Gilgal og Mispa; og han skilde trættor i Israel på alle desse staderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'So for han heim att til Rama; for der åtte han heime, og der skilde han elles trættorne millom israelitarne. Og der bygde han eit altar for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Då Samuel vart gamall, sette han sønerne sine til domarar i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Fyrstefødde son hans heitte Joel, andre son hans Abia; dei heldt dom i Be’erseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Men sønerne fylgde ikkje hans fotefar; dei let seg lokka av låk vinning og tok mutor, og rengde retten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Alle dei øvste i Israel samla seg då og kom til Samuel i Rama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Dei sagde til honom: «Sjå, du hev vorte gamall, og sønerne dine fylgjer ikkje dine fotefar. So set no ein konge yver oss til å skifta rett, liksom alle dei hine folki hev!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Men Samuel mislika dette, at dei sagde: «Gjev oss ein konge til å skilja trættorne våre!» Og Samuel bad til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Men Herren sagde til Samuel: «Lyd folkekravet! Ikkje deg hev dei vanda; meg hev dei vanda, og vil ikkje hava meg til konge lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Liksom dei hev fare åt alle dagar frå den tid eg førde deim upp frå Egyptarland, då dei snudde ryggen til meg og tente andre gudar; soleis fer dei ogso åt mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Lyd kravet deira! Men vara deim ålvorleg, og seg kva rett ein konge tek seg når han rikjer yver deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Og Samuel fortalde til folket som kravde ein konge av honom, alt det Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Han sagde: «Dette tek han seg rett til, den kongen som kjem til å rikja yver dykk: Sønerne dykkar vil han taka og bruka framfor vognerne og hestarne sine, so dei lyt springa framfyre vognerne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'sume vil han setja til førarar og underførarar for herflokkerne sine; sume vil han setja til å pløgja åkerjordi si og til å gjera skurdonni og laga krigsvåpni sine og køyregreidorne sine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'og døtterne dykkar vil han taka til å laga kryddesalve og til å koka og baka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Dei beste åkrarne og vinhagarne og oljeplantingarne dykkar vil han taka og gjeva åt tenarane sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Han vil taka tiend av såjordi og vinhagarne dykkar og gjeva henne åt hirdmennerne og tenarane sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Dessutan vil han taka tenestdrengjerne og tenestgjentorne dykkar og dei likaste unggutarne dykkar, og asni dykkar vil han taka og bruka i si eigi tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Av buskapen dykkar vil han taka tiend, og de lyt sjølve vera trælarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Då vil de ropa til Herren for den kongen skuld som de sjølv hev valt dykk. Men då vil han ikkje svara dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Men folket vilde ikkje lyda Samuel; «Nei,» sagde dei, «so sanneleg vil me hava ein konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Me vil vera jamgode med alle dei hine folki; me vil hava ein konge til domar og til hovding yver heren i krig.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Då Samuel høyrde alt det folket sagde, bar han det fram for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Og Herren sagde til Samuel: «Lyd deim og set ein konge yver deim!» Då sagde Samuel til Israels-sønerne: «Far heim kvar til sin by!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Kis heitt ein mann av Benjamin. Han var son åt Abiel, son åt Seror, son åt Bekorat, son åt Afiah, son åt ein benjaminit. Han var ein velhalden mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Han hadde ein son som heitte Saul: velvaksen og væn; ingen i Israel var vænare enn han; han var hovudet høgre enn alt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'No hadde nokre asnor komne burt for Kis, far åt Saul. Og Kis sagde med Saul, son sin: «Tak med deg ein av drengjerne, og far av stad og leita etter asnorne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Han gjekk yver Efraimsheidi og so gjenom Salisalandet; men han fann deim ikkje. So gjekk dei gjenom Sa’alimslandet; men dei var ikkje der. So gjekk dei gjenom Benjaminslandet, men fann deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Då dei so var komne inn i Suflandet, sagde Saul med drengen han hadde med seg: «Kom, lat oss venda heim att; elles vil far verta illhuga for oss i staden for å tenkja på asnorne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Men han svara honom: «Sjå her i byen er det ein gudsmann som er namngjeten; alt det han segjer, det hender. Lat oss no ganga dit. Kann henda han kunde fortelja oss noko um den ferdi me hev gjeve oss ut på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul sagde til drengen: «Men um me no gjeng dit, kva skal me hava med oss til mannen? Me hev ikkje meir mat i skrepporne våre, og nokor onnor gåva hev me ikkje heller til gudsmannen; eller kva hev me?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Drengen svara Saul andre venda: «Sjå, her hev eg i mitt eige ein kvart dalar i sylv; den vil eg gjeva gudsmannen, so han segjer oss kva leid me bør taka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Fyrr i tidi pla dei segja i Israel når einkvan gjekk av stad og spurde Gud: «Kom, lat oss ganga til sjåaren!» Det dei no kallar profet, kalla dei i gamle dagar sjåar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul sagde til drengen: «Du hev rett! kom, lat oss ganga!» So gjekk dei til byen der gudsmannen budde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Då dei gjekk upp bykleivi, møtte dei nokre gjentor som gjekk ut, skulde henta vatn, og spurde deim: «Er sjåaren her?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Dei svara deim: «Ja, beint her burte. Skunda deg no! han kom nett heim til byen i dag; for i dag hev folket slagtoffer på offerhaugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Når de gjeng inn i byen, so finn de honom fyrr han gjeng upp på offerhaugen til måltidi; folket held ikkje måltid fyrr han kjem; for han skal vigsla offeret fyrr gjesterne tek til å eta. Gakk difor straks! nett no finn de honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Dei gjekk upp til byen. Nett med same dei kom inn i byen, møtte dei Samuel på veg upp til offerhaugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Dagen fyrr Saul kom, hadde Herren opna øyra åt Samuel og sagt til honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '«I morgon dette bil sender eg til deg ein mann frå Benjaminslandet; honom skal du salva til fyrste yver Israel, folket mitt; han skal frelsa folket mitt frå filistarmagti. Eg hev set til folket mitt, etter di naudropet deira hev nått upp til meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Då Samuel fekk sjå Saul, gjorde Herren kunnigt for honom: «Sjå her er mannen som eg tala um til deg; han skal taka herredømet yver folket mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Saul gjekk fram til Samuel midt i porten og sagde: «Ver so snild og seg meg; kvar bur sjåaren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel svara Saul: «Eg er sjåaren. Gakk i fyrevegen upp på offerhaugen! De skal eta med meg i dag. I morgon tidleg, når eg segjer farvel med deg, skal eg gjeva deg greida på alt det du hev på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Asnorne som kom burt i dag tri dagar sidan, tarv du ikkje vera rædd for; dei er attfunne. Kven er det elles som eig alle eignaluter i Israel, anna du og farsætti di?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul svara: «Er ikkje eg benjaminit, av den minste ætti i Israel? og mi ættgrein er den ringaste av alle Benjamins-ætterne. Kvifor talar du soleis med meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel tok då Saul og drengen hans og leidde deim inn i gildesalen og sessa deim øvst millom gjesterne; dei var um lag tretti mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Og Samuel sagde til kokken: «Kom hit med det stykket eg gav deg og bad deg gøyma vel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Kokken bar fram lårstykket og det som høyrde til, og sette framfor Saul. Og han sagde: «Her er det som er gøymt åt deg. Et no! Til denne høgtidsstundi vart det gøymt åt deg då eg sagde: Eg hev bede folket.» Saul heldt då måltid med Samuel den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'So gjekk dei ned frå offerhaugen og inn i byen, og han tala med Saul på taket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Tidleg næste morgon då det lyste av dag, ropa Samuel på Saul uppe på taket: «Ris upp, so vil eg fylgja deg på veg!» Saul reis upp, og dei gjekk båe av stad, han og Samuel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Då dei var komne utanfor byen, sagde Samuel med Saul: «Bed drengen ganga fyre oss!» - han so gjorde - men sjølv må du stogga eit bil, so skal du få høyra det Gud hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'So tok Samuel oljeflaska og slo olje på hovudet hans, kysste honom og sagde: «No hev Herren salva deg til fyrste yver arvluten sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Når du gjeng frå meg, kjem du til å møta tvo menner attmed Rakel-gravi, ved landskilet mot Benjamin ved Selsah. Dei skal segja med deg: «Asnorne du leita etter, er attfunne; far din kjem difor ikkje i hug asnorne meir; men han er illhuga for dykk og segjer: «Kva skal eg gjera for son min?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Når du heldt fram derifrå og kjem til Taboreiki, vil du der møta tri menner som er på veg upp til Gud i Betel; ein med tri kid, ein med tri brødleivar og ein med ei vinhit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Dei helsar deg heil og sæl og gjev deg tvo brød, og du skal taka imot det dei gjev deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Deretter kjem du til Guds Gibea, der som filistarvakti held seg. Og når du kjem inn der i byen, råkar du på ein profetflokk som kjem ned frå offerhaugen i profetisk eldhug med harpa, trumma, fløyta og cither.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Og Herrens ande skal koma yver deg, so du og kjem i profetisk uppgløding liksom dei. Og du skal verta ein annan mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Når du ser desse jarteigner ovra seg, so må du gjera det som fyre fell; for Gud er med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'So må du ganga ned fyre meg til Gilgal; og der skal eg koma ned til deg og ofra brennoffer og takkoffer. Sju dagar skal du drygja, til dess eg kjem og segjer deg kva du skal gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Då han no vende seg og gjekk frå Samuel; let Gud honom få ein annan hug. Og alle desse jartegnerne kom, same dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Då dei kom til Gibea, møtte han ein profetflokk, og Guds ande kom yver honom, so han kom i profetisk eldhug midt imillom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Då no alle som kjende honom frå fyrr, fekk sjå honom i profetisk eldhug liksom profetarne, sagde dei seg imillom: «Kva er det som kjem åt son til Kis? Er Saul og millom profetarne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Ein mann der i grendi svara: «Kven er då deira far?» Av dette kom det ordtaket: «Er Saul og millom profetarne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Då eldhugen seig av honom, gjekk han upp på offerhaugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Då spurde farbror åt Saul honom og drengen hans: «Kvar hev de vore?» Han svara: «På leit etter asnorne. Då me såg dei ingen stad var å finna, kom me til Samuel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Farbroren sagde: «Fortel meg kva Samuel sagde med dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul svara: «Han sagde med oss at asnorne var attfunne.» Men det Samuel hadde sagt um kongedømet, nemnde han ikkje med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Samuel stemnde folket saman til Herren i Mispa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Og han sagde til Israels-borni: «So segjer Herren, Israels Gud: «Eg hev ført Israel upp frå Egyptarland, eg frelste dykk frå egyptarmagti og frå alle dei kongeriki som trengde dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Men no hev de vanda dykkar Gud, som frelste dykk ut or alle ulukkor og trengslor, og det segjer til honom: «Set ein konge yver oss!» So stig då fram for Herren etter dykkar ættar og ættgreiner.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'So let Samuel alle Israels ætter stiga fram. Luten fall på Benjamins-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Då so Benjamins-ætti gjekk fram etter ættgreinerne sine, fall luten på Matri-greini; so fall han på Saul, Kis-sonen. Men då dei leita etter honom, var han ikkje å finna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Dei spurde då Herren ei venda til: «Er det endå ein mann her?» Herren svara: «Han hev løynt seg millom ferdagodset.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Dei sprang dit og henta honom. Og då han steig fram millom folket, var han hovudet høgre enn alle dei hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Samuel sagde til folket: «Her ser de den som Herren hev valt ut; det finst ingen maken hans i heile folket.» Då sette heile folket i med fagnadrop: «Live kongen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Samuel kunngjorde folket kongelovi, og rita henne i ei bok, som han lagde ned framfor Herren. So let Samuel heile folket fara heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Saul gjekk ogso heim til Gibea. Og med honom fylgde ein flokk djerve karar, som var gripne i hjarta av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Men nokre illmenne sagde: «Kva hjelp kann denne mannen gjeva oss?» Dei vanvyrde honom og bar ingi hyllingsgåva til honom. Men han læst som han inkje gådde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Ammoniten Nahas drog upp og kringsette Jabes i Gilead. Då sagde alle Jabes-buarne med Nahas: «Gjer forlik med oss, so skal me tena deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Men ammoniten Nahas svara deim: «Ja, på det vilkåret gjer eg forlik med dykk, at eg sting ut høgre auga på dykk alle, til skjemsla for heile Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Styresmennerne i Jabes sagde til honom: «Gjev oss sju dagar frest, so me fær skikka bod yver heile Israelsriket. Er det so ingen som bergar oss, so skal me gjeva oss yver til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Då sendebodi kom til Sauls Gibea og lagde fram saki fram for folket, brast heile folket i gråt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Saul kom nett heim frå åkeren attum uksarne. Han spør: «Kva hev kome åt folket, etter di dei græt?» Dei fortalde honom det som Jabes-buarne hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Då Saul høyrde dette, kom Guds ande yver honom; harmen loga upp i honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'og han tok tvo uksar, lema deim sund og sende stykki rundt i heile Israelsriket med sendebod som sagde: «Den som ikkje fylgjer Saul og Samuel, hans uksar skal fara soleis.» Ei rædsla frå Herren fall på heile folket. Og ut drog dei, alle som ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Han mynstra heren i Bezek; Israels-sønerne talde tri hundrad tusund, og Juda-folki tretti tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Dei sagde med sendemennerne som var komne: «So skal det segja med Jabes-buarne i Gilead: «I morgon ved høgstedags leite skal de få hjelp!»» Då sendemennerne kom heim og fortalde det til Jabes-buarne, vart dei glade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Og dei sagde til Nahas: «I morgon skal me gjeva oss yver til dykk; då fær de gjera med oss som de tykkjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Morgonen etter skifte Saul folket i tri flokkar. Og dei braut seg inn i lægret fyrstundes i otta, og hogg ned ammonitarne frå morgonen til høgstedags leite. Dei som slapp undan, vart spreidde til alle kantar, so det vart ikkje att tvo i lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Då sagde folket med Samuel: «Kven var det som sagde: «Skal Saul vera konge yver oss?» Lat oss få tak i dei kararne, so vil me drepa deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Men Saul sagde: «Ingen skal drepast i dag. For i dag hev Herren gjeve Israel siger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Og Samuel sagde med folket: «Kom, lat oss ganga til Gilgal og nya upp kongedømet der!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Og heile folket gjekk til Gilgal, og gjorde Saul til konge der framfor Herren i Gilgal, og ofra takkoffer framfor Herren. Og alle Israels-mennerne gledde seg med ovstor fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Samuel sagde til heile Israel: «Sjå, eg hev lydt dykk i alt de hev kravt av meg. Eg hev sett ein konge yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'No heretter vil kongen verta styraren dykkar. Eg er gamall og grå, og sønerne mine er hjå dykk. Frå ungdomsåri til i dag hev eg vore styraren dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Sjå her stend eg! Vitna no mot meg, so Herren og den han salva høyrer på: Hev eg teke ein ukse frå nokon? eller hev eg teke eit asen frå nokon? hev eg trælka nokon? eller trakka på nokon? hev eg teke mutor av nokon, so eg skulde sjå gjenom fingrarne med honom? So vil eg gjeva dykk vederlag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Dei svara: «Ikkje hev du trælka oss, og ikkje trakka på oss, og ingen ting hev du teke frå nokon mann.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Då sagde han til deim: «So er Herren vitne mot dykk, og den han salva er vitne i dag, at de ingen ting hev funne å krevja hjå meg.» Dei svara ja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel sagde til folket: «Herren er vitne, han som vekte upp Moses og Aron, og som førde federne dykkar upp frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Stig no fram! so vil eg gjera upp med dykk framfor Herren for alle Guds vise verk, som han hev gjort mot dykk og mot federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Då Jakob var komen til Egyptarland, ropa federne dykkar til Herren. Og Herren sende Moses og Aron og førde federne dykkar ut or Egyptarland og gav deim bustad her i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Men dei gløymde Herren, sin Gud, og han gav deim i henderne på Sisera, herhovdingen i Hasor, og i henderne på filistarane og på Moab-kongen; og dei gjekk i strid mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'So ropa dei til Herren og sagde: «Me hev synda; for me hev svike Herren og tent Ba’als-bilæti og Astarte-bilæti; men frels oss no frå fiendarne våre, so vil me tena deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'So sende Herren Jerubba’al og Bedan og Jefta og Samuel, og frelste dykk frå fiendarne dykkar på alle kantar, so de fekk bu trygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Men då de såg Nahas, ammonitarkongen, kom yver dykk, so sagde de til meg: «Nei, ein konge vil me hava til styrar yver oss» - endå Herren, dykkar Gud, var kongen dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Og no - her stend kongen som de hev kåra, den det hev kravt. Herren hev sett ein konge yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Berre de no vil bera age for Herren og tena honom og lyda honom, og ikkje setja dykk upp mot Herrens bod, men fylgja Herren, dykkar Gud, både de og kongen som hev vorte styraren dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Lyder de ikkje Herren, men set de dykk upp mot Herrens bod, då vil Herrens hand vera imot dykk liksom mot federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Stig no fram og skoda dette store underet som Herren vil gjera beint framfor augo dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'No er det tidi for kveiteskurden, veit det. Men eg vil ropa til Herren, at han sender tora og regn. Soleis skal de skyna og sjå kor stor ei synd det er i Herrens augo, det de gjorde då de kravde ein konge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Samuel ropa til Herren. Og Herren sende torever og regn den dagen. Då fekk heile folket stor age for Herren og for Samuel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Og heile folket sagde til Samuel: «Bed til Herren for tenarane dine, so me ikkje skal døy, for di me hev auka synderne våre med den misgjerningi at me kravde ein konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel sagde til folket: «Ver ikkje rædde! Visst hev de gjort alt dette vonde. Men fall berre ikkje frå Herren no! men ten Herren av all dykkar hug!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Fall ikkje frå! for då kjem de til å fara etter tome avgudar, som ingen gagnar og ingen fagnar; tome er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Herren skal taka folket sitt til nåde, for sitt store namn skuld, etter di det tektest Herren å gjera dykk til sitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Og eg for meg: aldri i verdi vil eg synda mot Herren med å slutta å beda for dykk. Nei, eg vil læra dykk den gode og rette vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Berre de vil bera age for Herren og ten honom truleg av all dykkar hug! For sjå kor store ting han hev gjort for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Men gjer de det som vondt er, so er det ute både med dykk og kongen dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul hadde vore konge eitt år. Andre året han var konge yver Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'valde han seg ut or Israel tri tusund mann. Av desse hadde Saul hjå seg tvo tusund i Mikmas og i Betelsfjellbygdii, og eitt tusund hadde Jonatan med seg i Gibea i Benjamin. Resten av krigsfolket sende han heim kvar til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Jonatan slo i hel filistarvakti i Gibea, og filistarane høyrde gjete det. Men Saul let blåsa i lur yver heile landet og sagde: «Hebræarane må høyra det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Heile Israel fekk høyra at Saul hadde slege i hel filistarvakti, og at Israel hadde fenge uord på seg hjå filistarane for det same. Folket vart då utbode til å fylgja Saul til Gilgal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Filistarane stemnde saman til krig mot Israel, tri tusund vogner og seks tusund hestfolk, og fotfolk so mange som sanden på havsens strand. Dei drog upp og lægra seg ved Mikmas austanfor Bet-Aven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Då Israels-mennerne såg dei var komne i knipa, av di filistarane trengde på, so for folket av og løynde seg i hellerar, i klungerkjørr, i gil, i kjellarar og brunnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Og hebræararne hadde fare yver Jordan, til Gadslandet og Gileadslandet. Saul var endå i Gilgal, og heile folket fylgde honom skjelvande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Han drygde sju dagar, til den tid Samuel hadde fastsett. Men då Samuel endå ikkje var komen til Gilgal, og då folket tok til å spreida seg og ganga frå honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'sagde Saul: «Kom hit til meg med brennofferet og takkofferet!» Og so bar han fram brennofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Nett med same han det hadde gjort, då kom Samuel. Saul møtte honom og vilde helsa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Men Samuel sagde: «Kva er det du hev gjort?» Saul svara: «Då eg såg folket tok til å spreida seg og ganga frå meg, og du ikkje var komen til fastsett tid, og filistarane hadde samla seg i Mikmas,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'so tenkte eg: «No kjem filistarane yver meg i Gilgal, og eg hev endå ikkje blidka Herren.» So våga eg meg til å bera fram brennofferet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel sagde til Saul: «Du var uvisleg gjort av deg. Hadde du agta på bodet frå Herren, din Gud, som han baud deg, so vilde Herren no ha grunnfest kongedømet ditt til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Men no vil kongedømet ditt ikkje standa seg. Herren hev valt seg ut ein mann etter sin hug; og Herren hev etla honom til fyrste yver folket sitt, av di du ikkje agta på det Herren baud deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Samuel reis upp og for heim frå Gilgal upp til Benjamins Gibea. Saul mynstra krigsfolket som var hjå honom; um lag seks hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul og Jonatan heldt seg i Geba i Benjamin med det folket som var att hjå deim, og filistarane låg i læger i Mikmas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Frå filistarlægret sende dei ut røvarflokkar i tri hopar; eine hopen tok vegen til Ofra i Sualslandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'andre hopen tok vegen til Bet-Horon, og tridje hopen tok vegen til kverven som hallar ned imot Sebojimsdalen, burtimot øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Det fanst ingen smed i heile Israelslandet; for filistarane hadde vore rædde at hebræarane skulde smida sverd eller spjot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Og so laut kvar einast israelit ned til filistarane og få kvest både plogjarn og grev og øksar og ristlar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'so snart eggjarne vart skjemde på plogjarni, eller grevi, eller greiparne, eller øksarne, eller når dei turvte vøla på oksebroddarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Av dette hadde det seg so at då slaget skulde standa, hadde ingen av mennerne åt Saul og Jonatan sverd eller spjot. Einast Saul og Jonatan, son hans hadde våpn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Filistarane sette fram ein utpost i Mikmasskardet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Det bar so til ein dag at Jonatan, Saulssonen, sagde med våpnsveinen sin: «Kom, lat oss ganga yver til filistarutposten der burte på hi sida!» Men han gat det ikkje med far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul heldt seg i utkanten av Gibea under granatapallen i Migron, og folket han hadde med seg, var um lag seks hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Ahia Ahitubsson, bror åt I-kabod, son åt Pinehas Elison, Herrens prest i Silo, han bar no messehakelen. Og folket visste ikkje at Jonatan var gjengen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'I skardet der Jonatan freista ganga yver til filistarutposten, låg ein berghamar på kvar sida; den eine heitte Boses, og den andre Sene.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Den eine hamaren reis upp mot nord, beint imot Mikmas, den andre mot sør, beint imot Geba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Jonatan sagde med våpnsveinen sin: «Kom, lat oss klyva yver til utposten åt desse u-umskorne! kann henda vil Herren hjelpa oss. Det er ingen ting i vegen for at Herren kann gjeva siger anten dei er få eller mange.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Våpnsveinen svara: «Gjer alt det du tykkjer! Berre gakk på! eg fylgjer deg kvar du vil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonatan sagde: «Me kliv yver til dei kararne, og lager det so at dei ser oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Segjer dei då: «Stana der til dess me kjem burt åt dykk!» so stoggar me der me stend, og gjeng ikkje upp til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Men segjer dei: «Kom hit upp til oss!» då gjeng me upp; for då hev Herren hev gjeve deim i våre hender. Det skal me hava til jarteign.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Då no båe filistarutposten fekk sjå dei tvo, sagde dei: «Sjå hebræarane kryp ut or holorne der dei hev løynt seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Og utpostkararne ropa til Jonatan og våpnsveinen hans: «Kom hit upp til oss, so skal de få full greida!» Jonatan sagde med våpnsveinen: «Fylg meg! Herren hev gjeve deim i Israels hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jonatan kleiv uppetter på hender og føter, og våpnsveinen fylgde. Jonatan felte deim, og våpnsveinen fylgde etter og gjorde det av med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'I fyrste åtaket Jonatan og våpnsveinen gjorde, hogg dei ned um lag eit tjug, på ei vidd som ein halv dags plogland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Då vart dei fjetra både i lægret og på marki heile heren; og utpostarne og røvarflokkarne vart og fjetra. Og grunnen skalv, so det kom ein støkk frå Gud yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Vaktpostarne åt Saul i Gibea i Benjamin såg at heile hopen var reint i ørska, so dei vingla i kross og krok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Saul sagde til krigsfolket sitt; «Mynstra heren, og sjå kven som vantar!» Dei mynstra heren, og fekk sjå at Jonatan og våpnsveinen hans vanta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Då sagde Saul til Ahia: «Kom hit med Guds kista!» For Guds kista var den tid millom Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Men medan Saul tala med presten, auka ståket i filistarlægret allstødt. Saul sagde då til presten: «Det kann vera det same.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'So samla dei seg på slagmarki, Saul og alt krigsfolket hans, og fekk sjå fiendarne lyfte sverdi mot kvarandre, og dei var so forstøkte, at dei visste korkje att eller fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Dei hebræarane som frå gamalt hadde vore i filistarmagt, og hadde fylgt med deim upp og var spreidde rundt i lægret, dei og slo lag med Israels-heren under Saul og Jonatan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Og då dei Israels-mennerne som hadde løynt seg i Efraimsfjellbygdi, høyrde gjete at filistarane var på flog, sette alle dei og etter deim og kom med i slaget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Soleis gav Herren Israel siger den dagen. Og bardagen flutte seg heilt framum Bet-Aven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Det røynde hardt på kvar israelit den dagen. Og Saul batt folket med denne eiden: «Forbanna den som et noko mat fyre kvelden, fyrr eg hev teke hemn yver fiendarne mine!» So var det ingen som smaka matbiten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Då dei alle i hop kom inn i skogen, låg det honning på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Men då folket kom upp i skogen og fekk sjå honning strøyma ut, våga ingen føra handi til munnen, av age for eiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonatan hadde ikkje lydt på då far hans tok folket i eid; difor rette han ut staven han hadde i handi og duppa den eine enden i honningen, og førde so handi til munnen; han vart då bjartøygd att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Ein av mennerne tok til ords og sagde: «Far din hev bunde folket med denne eiden: «Forbanna kvar den som et noko mat i dag!» - endå dei var trøytte.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Jonatan svara: «Far fører ulukka yver landet! Sjå, kor augo mine ljosna av di eg smaka noko lite på denne honningen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Kor mykje større mannefall skulde det ikkje vorte millom filistarane um mennerne hadde fenge eta seg mette i dag av herfanget dei vann hjå fiendarne sine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Like vel: dei slo filistarane den dagen og forfylgde deim frå Mikmas til Ajjalon, og folki var svært trøytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'So kasta folket seg yver herfanget, tok sauer og uksar og kalvar, og slagta deim på marki, og åt kjøtet med blodet i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Dei melde det åt Saul og sagde: «Sjå, folket syndar mot Herren og et kjøt med blod i.» Då ropa Saul: «De hev gjort svik! Velt ein stor stein hit til meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Og Saul sagde: «Gakk ut millom folket og seg til deim: «Kvar og ein skal føra hit til meg uksen sin og sauen sin og slagta og eta honom her! Ikkje må de synda mot Herren og eta kjøt med blod i!»» Då førde heile folket fram um natti, kvar med eigi hand, uksarne sine, og slagta deim der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Saul bygde eit altar for Herren. Dette var det fyrste altaret han bygde åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Og Saul sagde: «Lat oss forfylgja filistarane i natt og herja millom deim, alt til det dagast i morgon, so ingen av deim kjem undan!» Dei svara: «Gjer alt det du tykkjer!» Men presten sagde: «Lat oss ganga fram for Guds åsyn her!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Då spurde Saul Gud: «Skal eg forfylgja filistarane? Vil du gjeva deim i Israels hand?» Men han gav deim ikkje svar den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Då sagde Saul: «Kom hit fram alle dei gjævaste av folket! so fær det sjå og gå kva det er for ei syndi som er gjord i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'So sant Herren liver, han som hev gjeve Israel siger, um det so er Jonatan, son min, skal han lata livet!» Ingen av folket svara honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Då sagde han til heile Israel: «Statt de på den eine sida, so vil eg med Jonatan, son min, standa på hi.» Folket svara Saul: «Gjer som du tykkjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Då sagde Saul til Herren, Israels Gud: «Lat sanningi koma for dagen!» Då fall luten på Jonatan og Saul, og folket gjekk fritt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sagde: «Drag strå millom meg og Jonatan, son min!» Då fall luten på Jonatan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Saul sagde til Jonatan: «Seg meg kva du hev gjort!» Då sagde Jonatan det med honom: «Med enden av staven eg hadde i handi, tok eg noko lite honning og smaka lite grand på det. Sjå her er eg, ferdig til å døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Saul svara: «Ja, Gud late meg bøta for det no og sidan! Livet lyt du lata, Jonatan!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Men folket sagde til Saul: «Skulde Jonatan døy? Han som hev vunne denne store sigeren for Israel! Aldri i verdi! So sant Herren liver, ikkje eit hår på hovudet hans skal vert skadt! for med Guds hjelp hev han gjort dette i dag.» Og folket løyste Jonatan ut; han vart ikkje drepen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Saul drog heim, og forfylgde ikkje filistarane meir. Filistarane drog og heim til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Då Saul hadde eigna til seg kongedømet i Israel, førde han krig mot alle fiendarne sine rundt ikring: Moab, ammonitarne, Edom, kongarne i Soba og filistarane. Og kvar helst han vende seg, tukta han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Han vann seg stort velde. Han slo Amalek - og fria soleis Israel frå deim som herja det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Sønerne åt Saul var Jonatan, Jisvi og Malkisua. Av dei tvo døtterne hans heitte den eldste Merab og den yngste Mikal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Kona åt Saul heitte Ahinoam Ahima’asdotter. Hovdingen yver heren hans heitte Abner, son åt Ner, som var farbror åt Saul;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'for Kis, Sauls far, og Ner, Abners far, var søner åt Abiel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Krigen mot filistarane var allstødt hard so lenge Saul livde. Og so tidt Saul såg ei kjempa eller ein dugande kar, tok han honom i si tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel sagde til Saul: «Det var meg Herren sende til å salva deg til konge yver Israel, folket sitt. So lyd no Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'So hev Herren, allhers drott, sagt: «Eg vil hemna det Amalek gjorde mot Israel med di han lagde seg i vegen for deim då dei drog upp frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Gakk no ut og vinn yver amalekitarne! Du skal bannstøytte deim og alt det dei eig. Du skal ikkje tykkja synd i deim, men drepa både kar og kvende, småborn og sogborn, bu og smale, kamelar og asen.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'So baud Saul ut herfolket og mynstra deim i Telajim; tvo hundrad tusund mann fotfolk og dessutan ti tusund mann frå Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Då Saul kom til Amalekbyen, sette han umsåtmenner i dalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Saul sagde til kenitarne: «Kom, skil dykk ut! Far undan frå amalekitarne, so eg ikkje skal gjera ende på dykk samstundes med deim! De synte då godhug mot alle Israels-borni då dei drog upp frå Egyptarlandet.» Då skilde kenitarne seg frå amalekitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Saul vann yver amalekitarne og forfylgde deim frå Havila til fram imot Sur, som ligg austan for Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Han tok Agag, amalekitarkongen, livande til fange; og alt folket bannstøytte han og hogg deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Men Saul og folket sparde Agag og det beste og det næstbeste av smalen og bufeet og lambi, alt som hadde verde; sovore vilde dei ikkje bannstøyta. Men alt skrapfeet og alle skrantne dyr, deim bannstøytte dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Herrens ord kom til Samuel:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '«Eg angrar at eg gjorde Saul til konge! Han hev vendt seg burt frå meg og ikkje gjort det eg sette honom til.» Då harmast Samuel, og han ropa til Herren heile natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Då Samuel reis upp tidleg um morgonen og gjekk til møtes med Saul, fekk han høyre gjete: «Saul hev fare til Karmel og reist seg eit æreminne der; so hev han snutt heim att og fare ned att til Gilgal.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Då Samuel kom til Saul, sagde Saul til honom: «Velsigna vere du av Herren! No hev eg gjort det Herren sette meg til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel svara: «Kva er det for bræking som læt for øyro mine? Kva er det for rauting eg høyrer?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul sagde: «Frå amalekitarne hev dei ført deim hit. Folket sparde det beste av bufe og smale til slagtoffer åt Herren, din Gud. Resten bannstøytte me.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Samuel sagde til Saul: «Teg still! so vil eg kunngjera deg kva Herren hev sagt meg i natt.» Han sagde til honom: «Seg det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sagde: «Du veit du vart hovding yver Israels-ætterne, då du tyktest deg sjølv ring. For Herren salva deg til konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Og Herren sende deg av stad og sagde: «Gakk og bannstøyt desse syndarar amalekitarne! Før krig mot deim, til dess du hev tynt deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Kvifor lydde du ikkje Herren, men kasta deg yver herfanget og gjorde det som Herren mislikar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul svara Samuel: «Eg hev lydt Herren og gjenge vegen Herren sende meg. Eg hev ført Agag, amalekitarkongen, hit, og amalekitarne hev eg bannstøytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Men folket tok av herfanget bufe og smale, det beste av det bannstøytte, til offer for Herren, din Gud, i Gilgal.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Då sagde Samuel: «Meiner du Herren hev hugnad i brennoffer og slagtoffer likso mykje som i lydnad mot Herren? Nei, lydnad er betre enn likaste offeret, ope øyra betre enn feitaste veren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Trass er trollskap, einvisa er som avgudar og husgudar. Av di du vanda Herrens ord, hev han vanda deg, so du vert ikkje kanna konge lenger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Saul sagde til Samuel: «Eg hev synda med di eg hev gjorde tvert imot det Herren baud meg og du tala til meg. Folket var eg rædd og gjorde deim til viljes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Men tilgjev no det eg hev synda! Ver med meg heim, so eg kann bøygja kne for Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sagde til Saul: «Eg vil ikkje vera med deg heim. Av di du hev vanda Herrens ord, hev Herren vanda deg, so du skal ikkje vera konge yver Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Då no Samuel snudde seg og vilde ganga, tok han tak i snippen på kappa hans, og reiv honom av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Då sagde Samuel til honom: «Herren hev i dag rive kongedømet yver Israel frå deg og gjeve det åt ein annan som er betre enn du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Israels heider lyg ikkje og angrar ikkje. For ikkje eit menneskje er han, so han skulde angra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Han svara: «Eg hev synda. Men syn meg no den æra framfor dei øvste i folket mitt og heile Israel, at du er med meg heim, so eg kann bøygja kne for Herren, din Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'So fylgde Samuel med Saul, og Saul bøygde på kne for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Samuel sagde: «Før hit til meg Agag, amalekitarkongen!» Då gjekk Agag fram til honom med lystig hug, med di han sagde: «Visst er det beiske i dauden burte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Men Samuel sagde: «Liksom ditt sverd hev gjort kvinnor barnlause, soleis skal di mor verta barnlaus meir enn andre kvinnor.» Og Samuel gav Agag banehogg framfor Herren i Gilgal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Samuel gjekk til Rama, og Saul for heim att til Sauls Gibea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel vilde ikkje sjå Saul meir so lenge han livde. For Samuel syrgde yver Saul, av di Herren angra han hadde gjort Saul til konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Herren sagde til Samuel: «Kor lenge etlar du å syrgja yver Saul? Eg hev då vanda honom, so han skal ikkje vera konge yver Israel. Fyll hornet ditt med olje og gakk av stad! Eg vil senda deg til Isai i Betlehem. Ein av sønerne hans hev eg etla til konge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel sagde: «Kor kann eg ganga dit? Fær Saul fretta det, drep han meg.» Herren svara: «Tak ei kviga med deg, so kann du segja: «Eg er komen og vil ofra til Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'So skal du beda Isai til offermåltidi, so skal eg lata deg vita det du skal gjera; og du skal salva åt meg den eg segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel gjorde som Herren sagde: Då han kom til Betlehem, kom dei øvste i byen skjelvande imot honom og spurde: «Varslar det godt at du kjem?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Han svara: «Ja, eg kjem og vil ofra til Herren. Det lyt helga dykk, so det kann vera med meg ved offermåltidi!» Og han helga Isai og sønerne hans og bad deim vera med ved offermåltidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Då dei kom, og han fekk sjå Eliab, tenkte han: «Der stend visst framfor Herren den han salvar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Men Herren sagde til Samuel: «Skoda ikkje på kor han ser ut, kor stor og høg han er på vokster; for honom vil eg ikkje hava. Det munar ikkje det menneskja ser; menneskja ser på utsyni, men Herren ser på hjarta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Då kalla Isai på Abinadab og let honom ganga fram for Samuel. Men han sagde: «Heller ikkje denne hev Herren valt seg ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Isai let Samma ganga fram. Men han sagde: «Heller ikkje denne hev Herren valt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Isai sju av sønerne ganga fram for Samuel. Men Samuel sagde til Isai: «Herren hev ikkje valt ut nokon av desse.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, '«Er dette alle gutarne dine?» spurde han Isai. Han svara: «Endå er den yngste att. Men han gjæter smalen.» «Send bod etter honom!» sagde Samuel med Isai; «for me vil ikkje setja oss til bords fyrr han kjem hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Då sende han bod etter honom. Han var raudleitt, hadde bjarte øugo, og var væn å sjå til. Og Herren sagde: «Ris upp og salva honom; han er det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Då tok Samuel oljehornet og salva honom, so brørne hans såg på. Og Herrens Ande kom yver David frå den dagen og sidan. So stod Samuel upp og drog til Rama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Etter Herrens Ande hadde vike frå Saul, kom det ei vond ånd frå Herren yver honom i brårider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Tenarane åt Saul sagde med honom: «Sjå, du fær brårider av ei vond ånd frå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Herre, seg med tenarane dine som stend framfor deg, at dei leitar upp ein som kann leika på harpa! Når so den vonde åndi frå Gud kjem yver deg, kann han spela; då vil du besna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Saul sagde då med tenarane sine: «Sjå dykk ut for meg ein mann som er god til å spela, og få honom hit til meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Ein av sveinarne svara: «Eg veit ein son åt Isai i Betlehem som kann spela, ein gjæv gut, våpndjerv, ordhag og fager. Herren er med honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Saul sende då bod til Isai og bad honom: «Send hit til meg David, son din, han som er med smalen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Isai tok då og klyvja eit asen med mat, ei vinhit og eit kid og sende til Saul med David, son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'So kom David til Saul og vart tenaren hans. Han vart svært glad i honom og gjorde honom til våpnsveinen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Og Saul sende bod til Isai og bad: «Kjære, lat David stogga hjå meg! for eg hev fenge godvilje for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'So tidt åndi frå Gud kom yver Saul, so tok David harpa og leika på henne. Då letna det for Saul. Han besna, og den vonde åndi slepte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Filistarane stemnde saman herarne sine til strid. Dei stemnde til Soko, som høyrer til Juda. Og dei lægra seg millom Soko og Azeka ved Efes-Dammim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul og Israels hermenner hadde og samla seg, og lægra seg i Eikedalen. Dei fylkte seg til slag mot filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Filistarane stod på den eine fjellsida, Israels-mennerne på hi, med dalen midt imillom seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Då steig det fram frå filistarfylkingi ei einvigskjempa. Han var frå Gat, og heitte Goliat, var seks alner og ei spann høg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Han hadde ein koparhjelm på hovudet, og gjekk med ei ringbrynja av kopar på fem tusund lodd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Han hadde koparspenger på føterne, og bar eit koparspjot på ryggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Spjotskaftet var som ein vevbom, og jarnet på spjotodden vog seks hundrad lodd. Og våpnsveinen hans gjekk fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Han steig no fram og ropa til Israels-fylkingi, og sagde til deim: «Kvifor dreg de ut og fylkjer dykk til slag? Er ikkje eg filistar? og de Sauls trælar? Vel dykk ein som kann koma hit ned til meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Magtast han slåst med meg og fella meg, so skal me vera dykkar trælar. Men vinn eg på honom og feller honom, so skal de vera våre trælar og tena oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Filistaren ropa framleides: «No hev eg svivyrdt Israels-fylkingi. Send ein hit til meg, so me kann slåst!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Då Saul og heile Israel høyrde desse ordi av filistaren, skalv dei og vart ovleg rædde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David var son åt denne efratiten Isai som er nemnd, i Betlehem i Juda. Isai hadde åtte søner. På Sauls tid var han gamall og mykje til års komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Dei tri eldste sønerne åt Isai fylgde Saul i krigen. Desse tri sønerne hans som gjekk i krigen heitte: den eldste Eliab, den andre Abinadab, og den tridje Samma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David var den yngste. Det var dei tri eldste som fylgde Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Og David gjekk tidt heim frå Saul og gjætte smalen åt far sin i Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Filistaren kom fram kvar morgon og kvar kveld i fyrti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Isai sagde med David, son sin: «Tak ei skjeppa av desse steikte aksi, og desse ti brødi, og skunda deg med deim til lægret til brørne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Og desse ti osteskivorne skal du gjeva føraren. Du skal sjå um det stend vel til med brørne dine, og få ei kvitting av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'For Saul og dei og heile Israels-heren er i Eikedalen i krig med filistarane.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Tidleg næste morgon reis David upp, let smalen åt ein hyrding, leste på seg og gjekk av stad, som Isai hadde bode honom. Han kom fram åt vognborgi, nett med same heren gjekk fram i fylking og lyfte herrop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Dei stod no slagbudde både Israel og filistarane, fylking mot fylking.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'David let trænvakti taka vare på føringi si, og sprang burt til heren. Han helsa på brørne sine, og spurde kor til stod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Med han stod og tala med deim, fekk han sjå einvigskjempa, filistaren - Goliat heitte han, og var frå Gat - som kom fram or filistarfylkingi, og tok upp att dei vanlege ordi, so David høyrde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Alle Israels-mennerne rømde undan då dei såg honom, og var ovleg rædde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Ein av Israels-mennerne sagde: «Ser de den karen som kjem fram der? Til svivyrding for Israel kjem han. Den som feller honom, vil kongen gjeva rikdom, og dotter si vil han gjeva honom, og ætti hans skal verta fri alle skattar og tyngslor i Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'David spurde deim som stod attmed honom: «Kva fær den som feller denne filistaren og tek ei sovori svivyrding burt frå Israel? for kven er denne u-umskorne filistaren som vågar svivyrda fylkingarne åt den livande Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Folki tok upp att dei same ordi; Det og det vil den få som feller honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Då Eliab, eldste bror hans, høyrde kva han sagde med folki, vart han brennande harm på David. «Kva kjem du her etter?» ropa han. «Kven hev du late den vesle smaleflokken til burte i øydemarki? Eg veit du er ei vyrdløysa, og full av vondska. Du kjem berre og vil sjå på slaget.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David sagde: «Kva hev eg då gjort? Det var då berre ein spurnad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'So vende han seg frå honom mot ein annan og kom med same spursmålet; og han fekk same svaret som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Men dei spurdest, desse ordi David hadde sagt. Og dei kom for øyro åt Saul, og han sende bod etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Og David sagde med Saul: «Ingen må missa modet. Tenaren din vil ganga imot denne filistaren og slåst med honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Men Saul sagde til David: «Du er ikkje før til å ganga i strid mot denne filistaren. Du er berre ungguten, og han er stridsmann alt frå barneåri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'David svara Saul: «Tenaren din hev gjætt smalen til far; kom då ei løva eller ein bjørn og røva ein sau i flokken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'so fylgde eg etter og drap udyret og reiv sauen ut or gapet på det. Um det reis upp på tvo imot meg, tok eg strupetak og gav det bane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Hev no tenaren din felt både løva og bjørn, skal det ganga nett like eins med denne u-umskorne filistaren; for han hev svivyrdt fylkingarne åt den livande Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Og David sagde: «Herren som fria meg ut or klørne åt løva og bjørn, han vil fria meg frå denne filistaren.» Då sagde Saul med David: «Gakk! og Herren vil vera med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Saul klædde på David våpnkjolen sin, sette ein koparhjelm på hovudet hans og gav honom ei brynja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Og David spente sverdet hans ikring seg utanpå våpnkjolen, og freista ganga soleis. Men han var ikkje van med det, og han sagde til Saul: «Eg kann ikkje ganga med dette på meg; eg er ikkje van med det.» Og David lagde det av seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'So tok han staven sin i handi, og fann seg fem av dei hålaste steinarne i bekkjefaret og lagde deim i gjætarskreppa si, som han hadde på seg. Slyngja si tok han i handi. Og so gjekk han fram imot filistaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Filistaren gjekk og fram imot David, og skjoldsveinen hans gjekk fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Då no filistaren gådde David, bles han åt honom; for han var berre ungguten, raudleitt og væn å sjå til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Filistaren ropa til David: «Meinar du eg er ein hund, sidan du kjem imot meg med stavar?» Og han banna David ved guden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, '«Kom hit til meg!» ropa filistaren til David, «so skal eg gjeva kjøtet ditt åt fuglarne under himmelen og åt villdyri i marki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'David svara filistaren: «Du kjem imot meg med sverd og langspjot og kastespjot. Men eg kjem imot deg i namnet åt Herren, allhers drott, han som er Gud for Israels-fylkingarne, deim som du hev svivyrdt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'I dag skal Herren gjeva deg i mitt vald. Eg skal fella deg og hogga hovudet ditt av deg. Dei daude skrottarne til filistarheren skal eg i dag gjeva åt fuglarne under himmelen og åt villdyri i marki, so all jordi skal skyna at Israel hev ein Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'og heile denne lyden skal skyna at det er ikkje med sverd og spjot Herren gjev siger. Striden høyrer Herren til; han gjev dykk i vår hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Då no filistaren budde seg og gjekk til møtes med David, skunda David seg og sprang fram imot filistaren, burtimot filistarfylkingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'David stakk handi i skreppa, tok upp ein stein, kasta, og råka filistaren i panna. Steinen sokk i panna hans, so han datt å gruve til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Soleis vann David på filistaren med ei slyngja si og ein stein, og drap filistaren, endå han hadde ikkje sverd i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'David sprang burtåt filistaren, tok sverdet hans, drog det ut or slira og drap honom og hogg hovudet av honom med det. Då filistarane såg at kjempa deira var daud, rømde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Israels-heren og Juda-heren lagde i veg, lyfte herrop, og forfylgde filistarane dit der vegen tek av til Gai, ja heilt til portarne i Ekron; so det låg falne filistarar på vegen til Sa’arajim, ja heilt til Gat og Ekron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'So snudde Israels-heren attende frå forfylgjingi, og herja filistarlægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David tok hovudet åt filistaren og førde til Jerusalem; men våpni hans tok han heim til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Då Saul såg David ganga imot filistaren, sagde han med Abner, herhovdingen sin: «Abner, kven er den guten son til?» Abner svara: «So visst som du liver, konge! eg veit ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Då sagde kongen: «Få du greide på kven den ungdomen er son til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Og då David kom att, etter han hadde felt filistaren, tok Abner og førde honom fram for Saul; han heldt hovudet åt filistaren i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Og Saul spurde honom: «Kven er du son til, guten min?» David svara: «Son til tenaren din, Isai i Betlehem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Då han hadde tala ut med Saul, lagde Jonatan stor elsk på David, og Jonatan elska honom som seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Saul tok honom til seg den dagen og let honom ikkje venda heim att til far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Jonatan gjorde fostbrorlag med David, av di han elska honom som seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Jonatan tok av seg kappa han bar og gav til David, og våpnkjolen sin, ja jamvel sverdet sitt og bogen sin og beltet sitt gav han honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'David drog i herferd. Kvar helst Saul sende honom, hadde han lukka med seg. Og Saul sette honom yver krigsheren. Han var vel umtykt av heile folket, endå til av tenarane åt Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Då dei kom heim, etter David hadde felt filistaren, gjekk kvendi ut frå alle byar i Israel, med song og dans, til å møta kong Saul med trummor, fagnadrop og triangel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Kvendi trødde dansen og song: «Tusund tynte kong Saul, men David tie tusund.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Då vart Saul brennande harm. Han mislika dei ordi og sagde: «David hev dei gjeve ti tusund; meg hev dei gjeve tusund! No vantar det honom berre kongedømet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Og Saul såg jamleg med skakkauga på David frå den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Dagen etter kom den vonde åndi frå Gud yver Saul. Og han rasa i huset sitt. David spela på harpa, som han kvar dag gjorde. Saul hadde eit spjot i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Saul kasta spjotet og tenkte: «Eg rennar spjotet gjenom David og inn i veggen!» Men David bøygde seg undan, tvo vendor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Saul vart rædd David, av di Herren var med honom, samstundes som han hadde vike frå Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Saul fekk honom då burt frå seg, med di han sette honom til herførar: han førde herfolket både ut og heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'David hadde lukka med seg all stad: Herren var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Då Saul såg at han hadde so stor ei lukka, fekk han rædsla for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Men heile Israel og Juda elska David; for han førde deim både ut og heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Saul sagde med David: «Her er eldste dotter mi, Merab; henne gjev eg deg til kona. Berre te deg som ein dugande kar, og før striden for Herren!» Saul tenkte: «Ikkje for mi hand skal han falla, men for filistarane.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'David svara Saul: «Kven er eg? og kva er ætti mi, farsætti mi i Israel, sidan eg skal verta måg til kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Men då tidi kom at David skulde gifta seg med Merab, dotter åt Saul, gifte han henne med Adriel frå Mehola.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Med Mikal Saulsdotter hadde huglagt David. Saul fekk vita det, og han lika det godt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'for Saul tenkte: «Eg skal gjeva henne åt honom, soleis at ho vert til ei snara for honom, so han fell for filistarhand.» Saul sagde med David: «Andre venda kann du verta mågen min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Og Saul baud folki sine: «Kviskra dette ordet i øyra på David: «Kongen likar deg godt, alle folki hans er glad i deg; no må du verta måg til kongen!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Då folki åt Saul sagde dette med David, svara han: «Tykkjer de det er so lite å vera kongsmåg? eg er då berre ein ring og fatig kar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Tenarane åt Saul fortalde honom det: «So og so sagde David.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul sagde: «Soleis skal de segja med David: «Kongen krev ikkje onnor festargåve enn hundrad huvehold av filistarar; for kongen vil hava hemn yver fiendarne sine.»» Saul vonast fella David med filistarhand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Tenarane hans melde desse ordi til David; og David lika godt å verta kongsmåg. Fyrr tidi var ute,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'reis han upp og gjekk av stad med sveinarne sine og gav tvo hundrad filistarar banehogg. Og David førde huveholdi deira med seg og lagde fullt tal fram for kongen, so han kunde verta kongsmåg. So gav Saul honom Mikal til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Saul såg og skyna at Herren var med David. Mikal Saulsdotter elska honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Men Saul vart stendigt meir og meir rædd David. So vart Saul uvenen åt David for heile livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Men filistarfyrstarne for i herferd. Og so tidt det for ut, hadde David meir lukka med seg enn hermennerne åt Saul. Og namnet hans vart høgvyrdt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul tala med Jonatan, son sin, og med alle tenarane sine um å drepa David. Jonatan Saulsson heldt mykje av David;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'difor nemnde Jonatan dette med David og sagde: «Saul, far min, lurar på å drepa deg. Sjå deg fyre i morgon og haldt deg roleg på eit løynd stad, og gøym deg der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'So vil eg ganga ut med far og standa med honom på marki der du er; eg vil nemna deg med far; og vert eg visare med noko, skal du få vita det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jonatan tala Davids sak hjå Saul, far sin, og sagde: «Kongen må ikkje gjera synd på David, tenaren sin. For han hev ikkje gjort synd mot deg. Tvert um; det han hev gjort, hev vore til stor bate for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Han våga livet og felte filistaren, og Herren gav so Israel ein stor siger. Du såg det sjølv og gledde deg. Kvifor skulde du gjera synd på skuldlaust blod og drepa David utan grunn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Saul lydde Jonatan, son sin. Og Saul svor: «So sant Herren liver: Han skal ikkje lata livet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'So ropa Jonatan på David og fortalde honom alt dette, og førde honom til Saul, og han var hjå honom som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Då krigen tok til att, for David i herferd og stridde mot filistarane, og gjorde stort mannefall millom deim, og dei rømde for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Då kom ei vond ånd frå Herren yver Saul, der han sat heime med spjot i handi, medan David leika på strengjerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Då freista Saul å renna spjotet gjenom David inn i veggen. Men han smatt undan, og spjotet for inn i veggen. Og David rømde og kom seg burt same natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'So sende Saul folk til heimen hans David; dei skulde vakta på honom og drepa honom um morgonen. Men Mikal, kona hans, fortalde honom det og sagde: «Bergar du ikkje livet i natt, so er du feig i morgon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'So fira Mikal David ned gjenom vindauga; og han rømde, og berga seg undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'So tok Mikal husguden og lagde i sengi, sette eit net av geitehår kring hovudet, og breidde åklædet yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Då no Saul sende folk til å henta David, sagde ho: «Han er sjuk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saul sende då Saul folki til å finna David sjølv, og sagde: «Ber honom hit upp til meg i sengi, so me kann drepa honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Då folki kom inn, fekk dei sjå det var husguden som låg i sengi, med geitehårsnetet kring hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Saul spurde Mikal: «Kvi hev du svike meg soleis og late uvenen min koma seg undan?» Mikal svara Saul: «Han sagde til meg: «Hjelp meg burt! elles drep eg deg.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Men David hadde rømt og berga seg undan. Han gjekk til Samuel i Rama, og fortalde honom alt det Saul hadde gjort honom. Og han og Samuel for til Nevajot og heldt seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Saul fekk vita at David var i Nevajot ved Rama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Og Saul sende folk til å henta David. Men då sendemennerne fekk sjå profetlyden i profetisk eldhug og Samuel standa der og vera føraren deira, då kom Gudsåndi yver deim, og dei kom i profetisk eldhug, dei og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Då Saul fekk høyra det, sende han andre folk dit; dei og kom i profetisk eldhug. Og då han tridje venda sende nye folk, gjekk det like eins med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Då gjekk han sjølv til Rama. Då han kom til den store brunnen i Seku, spurde han: «Kvar er Samuel og David?» Dei svara: «I Nevajot ved Rama.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Då han gjekk dit, til Nevajot ved Rama, kom gudsåndi yver honom og, so han gjekk i profetisk eldhug heile vegen, til dess han kom til Nevajot ved Rama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Då reiv han og av seg klædi, med di han og vart teken av profetisk eldhug framfor Samuel. Og han datt i koll og låg der naken heile den dagen og natti med. Difor plar dei segjer: «Er Saul og millom profetarne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David rømde frå Nevajot ved Rama, og kom til Jonatan og sagde: «Kva hev eg gjort? Kva ugjerning og kva synd hev eg gjort far din, etter di han vil taka livet av meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Han svara honom: «Aldri i verdi skal du døy! Sjå far gjer aldri noko, anten smått eller stort, utan han let meg vita det. Kvifor skulde då far løyna dette for meg? Det er ikkje so!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Men David gjorde eid på det: «Far din veit alt for vel at du hev fenge godvilje for meg. Difor tenkjer han: «Lat ikkje Jonatan få greida på dette! elles fær han sorg.» Men so sant Herren liver, og so sant du sjølv liver: det er berre eit stig millom meg og dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Då sagde Jonatan med David: «Kva ynskjer du eg skal gjera for deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'David svara: «I morgon er det nymåne. Eg skulde då sitja til bords med kongen. Lat meg no ganga og løyna meg ute på marki til i yvermorgon kveld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Skulde då far din sakna meg, so seg: «David nidbad meg um løyve til å springa heim til Betlehem, der som heile ætti no ber fram det årlege slagtofferet sitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Segjer han då: «Det er vel!» so kann tenaren din vera trygg. Men kjem sinnet yver honom, so skynar du han er fast meint på eitkvart ilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Syn då godvilje mot tenaren din, sidan du hev late tenaren din gjera fostbrorlag med meg for Herren! Finst det nokor ugjerning eg hev gjort, so drep du meg! Kvifor skulde du føra meg til far din?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Då svara Jonatan: «Aldri i verdi! Skynar eg klårt at far vil deg eitkvart ilt, so skal eg sanneleg segja deg det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Då spurde David: «Kven skal no lata meg vita dette, um far din gjev deg eit hardt svar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan svara: «Kom, lat oss ganga ut på marki!» Og dei gjekk båe ut på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Og Jonatan sagde med David: «Vitne er Herren, Israels Gud: når eg i morgon eller i yvermorgon ved denne tid røynar ut huglaget til far, og finn at det læt godt for David, so skal eg sanneleg senda bod til deg og lata deg vita det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Herren lata Jonatan bøta for det no og sidan: um far kjem på å gjera deg noko ilt, so let eg deg vita deg, og hjelper deg til å koma undan, so du kann fara din veg i fred. Og Herren vere med deg, som han hev vore med far!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Og vil so du, um eg endå liver, vil du so ikkje syna Herrens godvilje mot meg, so eg slepp lata livet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Aldri i æva vil du vel taka godviljen burt frå ætti mi, jamvel når Herren tek alle uvenerne åt David burt frå jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'So gjorde Jonatan ei pakt med Davids hus og sagde: «Herren take hemn yver uvenerne åt David!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Og Jonatan tok David i eid endå ein gong ved sin kjærleik til honom; for han elska honom som han elska si eigi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Jonatan sagde til honom: «I morgon er det nymåne. Då vert du sakna, av di sessen din kjem til å sakna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'I yvermorgon skal du skunda deg ned til løynstaden din, der du løynde deg den dagen det du veit skulde gjerast; og haldt deg attmed Burtferd-steinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Eg vil då vera i nærleiken og skjota til måls med tri piler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'So sender eg sveinen min av stad til å leita upp pilerne. Brukar eg då desse ordi til sveinen: «Sjå pilerne ligg på denne sida, tak deim!» - so kann du koma fram; for då er det ingen fåre for deg og ingen ting i vegen, so sant Herren liver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Men segjer eg til guten: «Sjå pilerne ligg lenger burte!» so far din veg! for då sender Herren deg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Til æveleg tid er Herren vitne til det ordet eg og du hev tala saman.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'So løynde David seg ute på marki. Då nymånedagen kom, sette kongen seg til bords til å eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kongen sat på sin vanlege sess, høgsætet attmed veggen; Jonatan stod upp, og Abner sat ved sida av Saul. Men sessen åt David var tom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul gat ingen ting den dagen; for han tenkte: «Det hev vel hendt honom noko, so han ikkje er rein, av di han endå ikkje hev reinsa seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Men då sessen åt David stod tomt ogso næste dag, dagen etter nymånedagen, spurde Saul Jonatan, son sin: «Kvi hev ikkje Isaisonen kome til bords antan i går eller i dag?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonatan svara Saul: «David nidbad meg um løyve til å fara åt Betlehem;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'han sagde: «Lat meg fara, for me held offerfest heile ætti der i byen, og bror min hev sjølv bode meg koma; held du aldri so lite av meg, so lat meg få lov å fara heim so eg kann vitja brørne mine!» Difor kjem han ikkje til kongsbordet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Då vart Saul brennande harm på Jonatan og sagde til honom: «Du son til ei treisk og rangsnudd kvinna! Visste eg ikkje at du hev huglagt Isaisonen, til skjemsla for deg sjølv, og til skjemsla for blygsli åt mor di!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'So lenge Isaisonen liver, stend både du og kongedømet ditt på utrygg grunn. Send difor bod og henta honom til meg! for han skal vera feig.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonatan svara Saul, far sin: «Kvifor skal han lata livet? Kva hev han gjort?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Då kasta Saul spjotet imot honom, og vilde drepa honom. No skyna Jonatan at far hans var fast meint på å drepa David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Jonatan reis upp frå bordet, harm i hugen, og smaka ikkje matbiten denne andre nymånedagen; for han syrgde sårt yver David, av di far hans hadde svivyrdt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Morgonen etter gjekk Jonatan ut på marki den tid han hadde avtala med David; og ein liten svein var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Han sagde til sveinen: «Spring du og leita etter pilerne som eg skyt!» Medan sveinen sprang av stad, skaut han ut pili framum honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Då sveinen nådde dit pili låg som Jonatan hadde skote, ropa Jonatan etter sveinen: «Pili ligg då lenger burte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Framleides ropa Jonatan etter sveinen: «Nøyt deg! skunda deg! statt ikkje der!» Då sanka sveinen åt Jonatan pilerne og bar til husbonden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Sveinen skyna ingen ting; einast Jonatan og David skyna meiningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Jonatan gav våpni sine til sveinen som var med honom, og sagde: «Far heim til byen med deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Då sveinen var faren, reis David upp på sørsida. Han fall å gruve til jordi, og bøygde seg tri gonger. Dei kysste einannan, og gret med einannan. Og David stridgret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Jonatan sagde til David: «Far i fred! Lat det standa med magt det me batt med ein eid i Herrens namn, då me sagde: «Herren skal vere vitne millom meg og deg, og millom mi ætt og di ætt, til æveleg tid!»» So reis David upp og gjekk sin veg. Og Jonatan gjekk heim att til byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'David kom til presten Ahimelek i Nob. Ahimelek vart forstøkt då han fekk sjå David, og spurde: «Kvifor kjem du eismall og hev inkje folk med deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David svara presten Ahimelek: «Kongen hev gjeve meg ei ærend, og han sagde med meg: «Ingen må vita noko um ærendi eg sender deg i og legg på deg.» Og sveinarne mine hev eg varsla å møta meg der dei veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Gjev meg no det du hev for handi, fem brød, eller kva som finst!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Presten svara David: «Uvigt brød hev eg ikkje for handi; einast heilagt brød er her; berre sveinarne dine hev halde seg burte frå kvinnor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'David svara presten: «Ver trygg! kvinnor hev vore langt burte frå oss alt sidan fyrre dagen. Då eg drog av stad, hadde sveinarne mine helgar-likamar. Um ferdi vår er kvardagsleg, so er ho då helga ved likamen i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'So gav presten honom heilagt brød; det fanst ikkje anna brød enn skodebrødi som hadde lege framfor Herren, og som no var burttekne att, då nytt brød var framlagt same dagen det gamle vart burtteke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Den dagen var det ein av Sauls tenarar der, som heldt seg inne framfor Herren, ein edomit, heitte Doeg, som var Sauls yverhyrding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'David spurde Ahimelek: «Hev du ikkje noko spjot eller sverd her hjå deg? Korkje sverdet mitt eller dei hine våpni tok eg med meg, då kongsærendi kom so brått på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Presten svara: «Jau, det sverdet som filistaren Goliat åtte, han som du felte i Eikedalen; det ligg sveipt i ei kappa attum messehakelen. Vil du hava det, so tak det! Noko anna hev eg ikkje.» «Det finst ikkje maken til det,» sagde David; «gjev meg det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'David drog av og rømde same dagen for Saul, og kom til Akis, kongen i Gat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Tenarane åt Akis sagde: «Er ikkje dette David, kongen i landet? Er det ikkje til æra for honom dei syng so når dei dansar: Tusund tynte Saul, David tie tusund?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'David lagde desse ordi på minne, og vart mykje rædd for Akis, kongen i Gat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Difor lest han som han var galen, og tedde seg som ein dåre, då dei vilde taka fat på honom; han rita på dørarne i porten, og let siklet renna i skjegget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Då sagde Akis med tenarane sine: «De ser då mannen hev mist vitet! Kvi fører de honom til meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Vantar det meg på vitløysor, sidan de førar denne mannen hit, so han skal te seg galen framfor meg? Kva hev han å gjera her i huset?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David drog derifrå, og kom seg undan til Adullam-hola. Då brørne hans og heile farsætti hans høyrde gjete det, kom dei dit ned til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Og til honom flokka seg allslags folk, alle som var i naud, alle som var i skuld, alle som var misnøgde, og han vart hovdingen deira; ei fire hundrad mann slo lag med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Derifrå drog David til Mispe i Moab. Og han sagde til Moabs-kongen: «Lat far min og mor mi få koma hit og vera hjå dykk, til dess eg fær vita kva Gud vil gjera med meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Han førde deim fram for Moabs-kongen, og dei fekk halda seg hjå honom, so lenge David var i borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Men profeten Gad sagde til David: «Du skal ikkje halda deg her i borgi! tak ut herifrå, og far til Judalandet!» Og David drog burt derifrå og kom til Heretskogen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Saul frette at dei hadde fenge greide på David og dei folki som var med honom. Saul sat ein dag i Gibea under tamariska på haugen, med spjot i handi; og alle tenarane hans stod ikring honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Då sagde Saul med tenarane sine, der dei stod ikring honom: «Høyr no, Benjamins born! Meiner de Isaisonen gjev åkrar og vinhagar åt dykk alle, og set dykk alle til herførar for større eller mindre flokkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'For de hev alle samansvore dykk mot meg; og ingen hev fortalt meg at son min hev gjort fostbrorlag med Isaisonen! Ingen hev so mykje medkjensle med meg at han hev fortalt meg det. For son min hev eggja tenaren min til meinråder mot meg, so som det no kjem for dagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Edomiten Doeg, som ogso stod der millom folki åt Saul, tok til ords og sagde: «Eg såg Isaisonen kom til Ahimelek Ahitubsson i Nob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Han spurde Herren for honom, og gav honom nista; og let honom få sverdet åt filistaren Goliat.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Kongen sende då bod etter presten Ahimelek Ahitubsson og heile ætti hans, prestarne i Nob. Dei møtte alle fram for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Saul sagde: «Høyr meg, du Ahitubsson!» Han svara: «Kva vil du meg, herre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Saul sagde til honom: «Kvifor hev de samansvore dykk mot meg, du og Isaisonen, med di du gav honom mat og sverd, og spurde Gud for honom, og han fekk leggja meinråder mot meg, so som det no kjem for dagen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelek svara: «Kven av alle tenarane sine er so trugen som David? og han er kongsmåg og hovding yver livvakti di og høgvyrd i huset ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Er det fyrste gongen eg hev spurd Gud for honom? Aldri i verdi må kongen saka meg og ætti mi for dette. Eg hev ikkje visst det minste um alt dette.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Kongen sagde: «Du skal lata livet, Ahimelek! du og heile ætti di.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Og kongen baud tenarane som stod ikring honom: «Fram og drep Herrens prestar! for dei er og i samråd med David. Endå dei visste han rømde, let dei meg ikkje vita det.» Men kongstenarane torde ikkje rette ut handi og hogga ned Herrens prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Kongen baud då Doeg: «Fram du, og hogg ned prestarne!» Og edomiten Doeg gjekk fram og hogg ned prestarne med eigi hand, og drap den dagen fem og åtteti mann som bar messehakel av lin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Og folket i prestebyen Nob slo han med sverd, karar og kvende, småborn og store born, bufe og smale og asen, alt hogg han ned med sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Berre ein av sønerne hans Ahimelek Ahitubsson berga seg undan. Abjatar heitte han. Han rømde til David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Abjatar fortalde David at Saul hadde hogge ned Herrens prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, '«Eg skyna det alt den gong,» sagde David til Abjatar, «at når edomiten Doeg var der, vilde han melda det til Saul. Eg er upphavet til dråpet på heile di ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Haldt deg hjå meg! ver hugheil! Den som vil taka livet av meg, vil taka livet av deg. Du er no i mi varetekt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Folk melde til David: «Filistarane held på og strider mot Ke’ila, og dei herjar treskjestaderne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Då spurde David Herren: «Skal eg draga av stad og slå desse filistarar?» Herren svara David: «Ja, drag av stad, slå filistarane og fria ut Ke’ila!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Men folki åt David sagde med honom: «Me er alt fyrr rædde um oss her i Juda. Kor skal det då ganga når me fer til Ke’ila mot filistarfylkingi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Då spurde David Herren andre gongen, og Herren svara honom: «Ris upp! drag ned til Ke’ila! Eg gjev filistarane i di hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'So for David med kararne sine til Ke’ila og stridde mot filistarane, førde burt buskapen deira, og gjorde stort mannefald millom deim. Soleis fria David folket i Ke’ila.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Då Abjatar Ahimeleksson rømde til David i Ke’ila, hadde han med seg messehakelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Saul fekk vita at David var komen til Ke’ila. Då sagde Saul: «Gud hev gjeve honom i mi magt, sidan han hev stengt seg inne i ein by med portar og slåer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'So baud Saul ut alt folket til strid. Dei skulde draga ned til Ke’ila og kringsetja David og folket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Då no David fekk vita at Saul lagde meinråder mot honom, sagde han til presten Abjatar: «Ber hit messehakelen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Og David sagde: «Herre, Israels Gud! Tenaren din hev spurt for sant at Saul tenkjer å koma til Ke’ila og øyda byen for mi skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Vil då Ke’ila-buarne gjeva meg i hans hand? Kjem Saul hit, som tenaren din hev spurt? Herre, Israels Gud! Lat tenaren din få vissa for det!» Herren svara: «Ja, han kjem hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'David spurde endå ein gong: «Vil Ke’ila-buarne gjeva meg og kararne mine i Sauls hender?» Herren svara: «Ja, dei vil det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Då reis David upp med kararne sine, um lag seks hundrad mann, og drog ut frå Ke’ila, og ferdast kvar helst det høvde. Då Saul fekk melding at David var rømd frå Ke’ila, let han vera å draga ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'So heldt David seg i øydemarki i fjellborgerne, og heldt seg millom fjelli i øydemarki Zif. Saul leita etter honom allstødt. Men Gud gav honom ikkje hans hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Medan David var i Hores i øydemarki Zif, såg han at Saul hadde fare ut og vilde drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Jonatan Saulsson for av stad og gjekk til David i Hores, og styrkte modet hans i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Han sagde til honom: «Ver hugheil! handi hans Saul, far min, skal ikkje nå deg. Du skal verta konge yver Israel, og eg skal vera den andre etter deg. Det skyner ogso Saul, far min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'So gjorde dei båe ei pakt for Herren. Og David heldt seg i Hores. Men Jonatan for heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Nokre Zif-folk drog upp til Saul i Gibea og sagde: «David held seg løynd hjå oss, i fjellborgerne i Hores, på Hakilahøgdi, sunnanfor øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Tekkjest det deg å draga ned no, konge, so gjer det! Vår sak vert det då å gjeva honom i kongens hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Då sagde Saul: «Velsigna av Herren vere de, at de tykkjer synd i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Far no heim, og få endå meir vissa! finn ut og sjå etter kva stad han ferdast, og kven det er som ser honom der! For dei hev sagt meg at han er ein ful fant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Finn ut og få greida på alle løynstader, der han kann løyna seg! Kom so att til meg, når det hev fenge vissa! so vil eg draga med dykk. Finst han i landet, skal eg vita å leita honom upp, um eg so skal leita millom alle Juda-ætterne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'So tok dei ut og gjekk til Zif fyre Saul. David og kararne hans var i øydemarki Maon, på heidi sunnanfor øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Då no Saul drog av stad med folki sine på leit etter David, fekk David høyra gjete det, og drog då ned på ein hamar, og heldt seg i øydemarki Maon. Då Saul frette det, sette han etter David inn i øydemarki Maon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Saul gjekk på den eine fjellsida, og David og kararne hans på hi. Nett som no David gjekk i angest og vilde sleppa frå Saul, og Saul og folki hans freista ringa David og kararne hans og fanga deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'so kom det bod til Saul: «Skunda deg og kom! filistarane hev falle inn i landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'So heldt Saul upp med å forfølja David, og drog mot filistarane. Derav fekk den staden namnet Sela-Hammahlekot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'David drog upp derifrå, og heldt seg so i fjellborgerne i En-Gedi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Då Saul kom heim att frå herferdi mot filistarane, fekk han tiend at David var i øydemarki En-Gedi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Då tok Saul tri tusund mann, utvalde or heile Israel, og drog av stad på leit etter David og kararne hans austum Steinbukk-hamrarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Han kom til sauegardarne attmed vegen; der var det ein heller; og der inn gjekk Saul for seg sjølv. David og kararne hans sat inst i helleren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Då sagde folki åt David med honom: «No er dagen komen som Herren nemde med deg: «Eg vil gjeva uvenen din i handi di, so du kann gjera med honom etter eige tykkje.»» David reis upp og skar i løyndom ein snipp av kappa åt Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Men so fekk David samvitsagg, av di han hadde skore av kappesnippen for Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Og han sagde med kararne sine: «Aldri i verdi vil Herren at eg skal gjera sovore og leggja hand på herren min som Herren hev salva; for han er den som Herren hev salva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'David truga kararne sine med strenge ord og gav deim ikkje lov til å falla yver Saul. Men då Saul reis upp og gjekk ut or helleren og skulde fara lenger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'då reis David og upp, gjekk ut or helleren og ropa etter Saul: «Herre konge!» Då Saul såg seg attende, kasta David seg å gruve på jordi. Han bøygde seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'og ropa til Saul: «Kvi høyrer du på det folk segjer, at David lurar på eitkvart ilt mot deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Med eigne augo hev du set i dag kor eg sparde deg, endå Herren hadde gjeve deg i mi hand i helleren, og dei rådde meg til å drepa deg. Men eg sparde deg, med di eg tenkte: «Ikkje vil eg leggja hand på herren min; for han er den Herren salva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Sjå sjølv, far! ja sjå her snippen av kappa di i mi hand! Når eg skar av kappesnippen og ikkje drap deg, so må du då skyna og sjå at eg ikkje etlar deg noko ilt eller noko brot, og at eg ikkje hev gjort synd mot deg, endå du sit etter meg og vil taka livet av meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Herren skal døma oss imillom, og Herren skal hemna meg på deg. Men mi hand skal ikkje vera lyft mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Det er som det gamle ordtøket segjer: «Frå dei vonde kjem vondskap.» Men mi hand skal ikkje vera lyft mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Kven er det Israels konge hev drege ut imot? Kven er det du forfylgjer? Ein daud hund! ei einsleg loppa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Herren skal vera domar og døma oss imillom. Han skal sjå til og føra mi sak, ja døma meg fri frå deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Då David hadde tala ut med Saul, ropa Saul til David: «Er det di røyst dette, David, son min?» Og Saul sette i og gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Og han sagde til David: «Retten er på di sida og ikkje på mi. Du hev gjort godt mot meg, medan eg hev gjort ilt mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'I dag hev du synt kor god du er mot meg, med di du ikkje drap meg, endå Herren hadde gjeve meg i di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Når ein råkar uvenen sin, plar ein då lata honom fara i fred? Herren gjeva deg lika for det gode du synte meg i dag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Sjå no skynar eg at du skal verta konge, og at kongedømet yver Israel skal vera fast i di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Men gjer no eid ved Herren at du ikkje vil rydja ut mi ætt etter meg og ikkje strjuka ut namnet mitt or ætti mi!» David gjorde den eiden til Saul. So for Saul heim. David og kararne hans drog upp i fjellborgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Samuel døydde. Heile Israel kom i hop og gret yver honom. Dei gravlagde honom heime i Rama. David braut upp og drog ned til øydemarki Paran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'I Maon var det ein mann som hadde buskapen sin på Karmel. Den mannen var ovleg rik; han åtte tri tusund sauer og tusund geiter. Han heldt på nett då å klyppa sauerne sine på Karmel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Nabal heitte mannen, og kona hans heitte Abiga’il. Kona hans var både vitug og væn; men mannen var hardlyndt og vondlyndt. Han var av Kalebs-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Då no David høyrde gjete i øydemarki at Nabal heldt på å klyppa sauerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'sende han ti av sveinar med den ordsendingi: «Far upp til Karmel! Gakk til Nabal og helsa honom frå meg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, '«Heil og sæl!» skal det segja, «og fred med deg sjølv! fred med ditt hus! og fred med alt det du eig!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Eg hev spurt at du held på med saueklypping. No er det so at hyrdingarne dine hev halde seg i vårt grannelag, og me hev ikkje gjenge deim for nær, og dei hev ikkje sakna noko slag heile den tidi dei hev vore på Karmel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Spør tenarane dine, so vil dei sjølve segja deg det. Syn no godvilje mot sveinarne mine! Du veit me hev kome hit i ei god stund. Gjev tenarane dine og David, son din, det du hev for handi!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Då sveinarne åt David kom dit, tala dei til Nabal i Davids namn og sagde som han hadde bode deim; og so tagde deim og gav tol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nabal svara tenarane åt David: «Kven er David? Kven er Isaisonen? No um dagen stryk det so mange tenarar frå husbondsfolki sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Skulde eg taka min mat og min drykk og slagt, som eg hev etla åt saueklypparane mine, og gjeva åt folk som eg ikkje veit kvar dei høyrer heime?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Sveinarne åt David vende då um og gjekk sin veg. Då dei kom attende, melde dei honom alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Då baud David: «Alle mann spenner sverdet um seg!» Og alle so gjorde. David sjølv spente og sverdet um seg. Um lag fire hundrad mann fylgde David upp; dei hine tvo hundrad mann heldt seg attmed tyet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Men ein av drengjerne hadde meldt det til Abiga’il, kona hans Nabal: «David sende bod hit frå øydemarki og helsa husbond; men han hylja deim yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Men desse kararne hev gjort oss mykje gagn. Ikkje hev dei gjenge oss for nær, og aldri hev me sakna noko heile den tidi me ferdast i lag med deim der ute på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Dei var ein mur ikring oss natt og dag, heile tidi me heldt oss i deira grannelag og gjætte småfeet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Tenk difor yver, og finn på eitkvart! for det heng ei ulukka yver husbond og heile huset hans; han er slik ei uvyrda, at ingen vågar tala til honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Då skunda Abiga’il seg og tok tvo hundrad brød, tvo vinhitar, fem tillaga sauer, ti settungar steikte aks, hundrad rosinkakor og tvo hundrad fikekakor, og klyvja på asni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Og ho sagde til drengjerne: «Far i fyrevegen! Sjå eg kjem etter.» Men med Nabal, mannen sin, gat ho det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Då ho reid på asnet sitt og kom ned i livd av fjellet, fekk ho sjå David og kararne hans koma ned frå hi sida, so ho måtte møta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'David hadde sagt: «Til fåfengs hev eg verna um alt det den mannen åtte i øydemarki, so ingen ting vanta av all eigedomen hans. Og han gjev meg vondt i vederlag for godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'So sant Gud må lata uvenerne åt David bøta no og sidan - av alle deim som høyrer honom til, let ikkje eit einaste karmannsemne liva til dagsprett i morgon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Då no Abiga’il fekk sjå David, steig ho straks ned frå asnet, fall å gruve for David og bøygde seg mot jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Ho fall ned for føterne hans og sagde: «Mi er skuldi, herre! Men lat terna di få tala med deg! og høyr på ordi åt terna di!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Ikkje må du bry deg um Nabal, den uvyrda. Det namnet hans tyder, det er han; dåre heiter han, og dårskap hyser han. Men eg, terna di, eg hev ikkje set dei sveinarne du sende, herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Og no, herre! so sant som Herren liver, og so sant du sjølv liver, og Herren hev meinka deg frå blodskuld og sjølvtekt - gjev det må ganga med uvenerne dine og alle som lurer på å gjera deg mein, like eins som det gjeng med Nabal!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Lat no desse gåvor, som terna di hev ført med til deg, verta utskifte millom dei sveinarne som fylgjer deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Herre, tilgjev terna di det ho hev synda! Herren skal visseleg byggja upp åt deg, herre, eit hus som vert standande. For du herre, fører striden for Herren. Inkje vondt hev dei funne hjå deg heile ditt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Ris det upp nokon og forfylgjer deg og vil taka livet av deg, gjev so ditt liv, herre, må vera bunde i bundelen av dei livande hjå Herren, din Gud! Men livet åt uvenerne dine skal han leggja i slyngja, og slengja burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Når Herren gjer med deg, herre, alt det gode han hev lova deg, og set deg til fyrste yver Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'so skal ikkje dette verta til støytestein eller til samvitsagg for deg, herre, at du hev rent ut skuldlaust blod, og at du, herre, hev teke deg sjølv til rettes. Men når Herren gjer godt med deg, herre, so kom i hug terna di!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Då svara David Abiga’il: «Lova vere Herren, Israels Gud, som i dag hev sendt deg til møtes med meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Velsigna vere vitet ditt! og velsigna vere du sjølv, som i dag meinkar meg i blodskuld og sjølvtekt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Men so sant Herren, Israels Gud, liver, han som hev halde meg frå å gjera deg noko mein - hadde du ikkje straks møtt meg, so vilde ikkje karmannsemne vore att i huset hans Nabal ved solarkoma i morgon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'David tok då imot av henne det ho førde med seg til honom. Og han sagde med henne: «Far heim att i fred! Sjå, eg hev lydt dine ord og gjort som du bad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Då no Abiga’il kom heim til Nabal, heldt han nett gilde heime. Det var som eit kongsgilde. Og Nabal var lystig og fjåg, og han var ovdrukken. Difor gat ho ikkje det minste med honom, fyrr um morgonen ved dagsprett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Men morgonen etter, då Nabal hadde sove ut ruset, fortalde kona hans det som var hendt. Då lamdest hjarta hans i bringa, og han vart som ein stein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Kring ti dagar etter slo Herren Nabal, og han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Då David spurde at Nabal var dåen, sagde han: «Lova vere Herren som hev hemnt på Nabal den svivyrding han synte meg, og som meinka tenaren sin frå å gjera vondt, med di Herren let vondskapen hjå Nabal koma att på hans eige hovud!» David sende bod og bela til Abiga’il og vilde hava henne til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Då tenarane åt David kom til Abiga’il på Karmel, bar dei fram målemnet sitt: «David hev sendt oss for å bela til deg for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Då reis ho upp og å fall å gruve til jordi og sagde: «Sjå, terna di er viljug til å vera ei trælkvinna som tvær føterne åt tenarane til herren min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'So skunda Abiga’il seg, reis upp og sette seg på asnet; like eins dei fem ternorne hennar som var fylgjet hennar. So fylgde ho med sendemennerne til David. Og ho vart kona hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David hadde dessutan teke til kona Ahinoam frå Jizre’el, so båe desse tvo vart konorne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Men Saul hadde gjeve Mikal, dotter si, kona hans David, åt Palti La’isson frå Gallim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Folk frå Zif kom til Saul i Gibea og sagde: «Meiner du ikkje David held seg løynd på Hakilahøgdi, beint imot øydemarki!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Saul tok på veg ned til øydemarki Zif med tri tusund mann, utvalde or Israel, på leit etter David i Zifmarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Saul lægra seg på Hakilahøgdi beint imot øydemarki, attmed vegen. David heldt seg då i øydemarki. Då han skyna at Saul var komen etter honom inn i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'sende han ut njosnarar, og fekk vita for visst at Saul var komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'So braut David upp og drog til den staden der Saul hadde lægra seg. David såg staden der Saul låg saman med herhovdingen, Abner Nersson. Saul låg i vognborgi, og folket hans var lægra rundt ikring honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'David tok til ords og spurde hetiten Ahimelek og Abisai Serujason, bror åt Joab: «Kven vil ganga med meg ned til Saul i lægret?» Abisai svara: «Eg gjeng med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'So kom David og Abisai nattars tid til herfolket der, og såg Saul låg og sov i vognborgi; med spjotet stunge i marki attmed hovudgjerdi. Abner og herfolket låg rundt ikring honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Då sagde Abisai til David: «I dag hev Gud gjeve uvenen din i di hand! Lat meg no få renna spjotet gjenom honom ned i marki! Det gjer eg med ein einaste støyt, eg tarv ikkje gjeva honom fleire.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Men David svara: «Du fær ikkje gjeva honom mein! Kven hev strafflaust lagt hand på den Herren salva?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, '«So sant Herren liver,» sagde David, «Herren lyt sjølv slå honom, eller avferdsdagen hans må koma på vanleg vis, eller han lyt få sin bane i krigen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Aldri i verdi vil Herren at eg skal leggja hand på den Herren hev salva. Tak likevel spjotet attmed hovudgjerdi, og vatskrukka! Lat oss so ganga vår veg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'David tok då spjotet og vatskrukka frå hovudgjerdi åt Saul, og so gjekk dei sin veg. Det var ingen som gådde og ingen som hådde, og ingen som vakna: Dei sov alle i hop. Herren hadde late ein tung svevn falla yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Då David var komen på hi sida, steig han fram på ein fjellknaus langt burte, so det var langt imillom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Og David ropa til herfolket og til Abner Nersson: «Vil du ikkje svara, Abner?» Abner svara: «Kven er du som ropar til kongen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'David ropa til Abner: «Du er då ein makelaus kar! I heile Israel finst ikkje maken! Korleis vaktar du kongen, din herre? Det hev vore einkvan inne og vilja gjera mein på kongen, herren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Det er ikkje vel gjort, det som du hev gjort. So sant Herren liver, de hadde fortent å lata livet, av di de ikkje hev vakt yver herren dykkar, honom som Herren salva. Sjå no etter: kvar er kongens spjot, og vatskrukka som stod attmed hovudgjerdi hans?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Saul kjende att røysti hans David og sagde: «Det er då di røyst dette, David, son min!» David svara: «Ja, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Og han sagde: «Kvifor forfylgjer du, herre, tenaren din soleis? Kva hev eg då gjort? Kva vondt finst hjå meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Gjev du, herre konge, no vil høyra på tenaren din: Er det Herren som hev eggja deg imot meg, so lat honom få kjenna lukti av ei offergåva! Men er det manneborn som hev eggja deg, so vere dei bannstøytte av Herren, av di dei hev jaga meg burt, so eg no ikkje slå lag med Herrens eigen lyd! Det er som dei vil segja: «Far av og ten framande gudar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Og må ikkje no blodet mitt renna ut på marki langt frå Herrens åsyn, når Israels-kongen dreg ut på leit etter ei einsleg loppa, liksom ein veidar rapphøns på heiderne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Då sagde Saul: «Eg hev synda. Kom heim att, David, son min! Eg vil ikkje gjera deg noko ilt, etter du i dag hev halde livet mitt so dyrt. Sjå, eg hev fare uvisleg, eg hev bore meg reint gale åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David svara og sagde: «Sjå her er spjotet, konge! Lat ein av sveinarne dine koma hit og henta det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Og Herren skal løna kvar ein som er ærleg og trufast, soleis som eg var i dag; då Herren gav deg i mi hand og eg vilde ikkje leggja hand på den som Herren hev salva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Difor: liksom eg hev halde ditt liv so høgt i dag, so skal Herren og halda mitt liv høgt, og han skal fria meg ut or all naud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sagde med David: «Velsigna vere du, David, son min! Det du tek deg fyre, skal du ogso sanneleg magtast gjera.» So for David sin veg, og Saul drog heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Men David sagde med seg sjølv: «Ein dag stupar eg for Sauls hand. Eg veit ingen annan utveg enn å røma til Filistarlandet; då lyt Saul slutta å leita etter meg innanfor Israelslandskilet; og so bergar eg meg undan honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'So braut David upp og drog med dei seks hundrad kararne sine yver til Akis Maoksson, kongen i Gat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Og David heldt seg hjå Akis i Gat, han og kararne hans, alle med huslyden sin, David med dei tvo konorne sine; Ahinoam frå Jizre’el og Abiga’il, kona hans Nabal frå Karmel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Då Saul frette at David hadde rømt til Gat, leita han ikkje meir etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'David sagde til Akis: «Hev du aldri so liten godvilje for meg, so lat meg få bu i ein av landsbyarne, so eg kann halda meg der. Kvifor skulde tenaren din bu i hovudstaden hjå deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Akis gav honom Siklag same dagen. Difor høyrer Siklag den dag i dag til Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Den tid David budde i Filistarlandet, var i alt eitt år og fire månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David tok ut med kararne sine og gjorde herjeferder hjå gesuritarne, girzitarne og amalekitarne. For desse folkeætterne budde der i landet frå gamalt, burtimot Sur og heilt til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Og når David herja i landet, sparde han korkje kar eller kvende; han tok bufe og smale og asen og kamelar og klæde. Og dermed snudde han attende til Akis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Når då Akis spurde: «I dag hev de vel ikkje gjort nokor herjeferd?» so svara David: «Jau, sør i Judalandet,» eller: «Sør i Jerahme’eitlandet», eller: «Sør i Kenitarlandet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Ingi livande sjæl sparde David, so dei kunde koma til Gat. For han tenkte: «Dei kunde slarva um oss og segja: «Det og det hev David gjort; soleis hev han fare åt heile tidi han budde i Filistarlandet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Men Akis trudde David, og tenkte: «Han hev fenge uord på seg hjå Israel, folket sitt, og no vil han tena meg alle dager.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'I dei dagarne fylkte filistarane krigsherane sine til strid mot Israel. Og Akis sagde med David: «Det skal du vita for visst, at du og kararne dine lyt fara i herferd med meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David svara Akis: «Ja vel, då skal du ogso røyna kva tenaren din duger til!» Akis sagde med David: «Ja vel, so set eg deg til livvakt hjå meg alle dagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel var dåen. Heile Israel hadde gråte yver honom. Og dei hadde gravlagt honom heime i Rama. Og Saul hadde rudt ut or landet deim som mana fram draugar og spåvette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Filistarane fylgte seg og lagde seg i læger attmed Sunem. Då fylkte ogso Saul heile Israel, og dei lægra seg ved Gilboa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Då Saul såg filistarlægret, vart han so rædd at hjarta hans skalv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Og Saul spurde Herren. Men Herren svara honom ikkje, antan gjenom draumar eller gjenom urim eller gjenom profetar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Då sagde Saul med tenarane sine: «Leita upp for meg ei som manar fram draugar, so gjeng eg åt henne og gjer spursmål til henne.» Tenarane svara: «I En-Dor er ei kona som manar fram draugar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Saul gjorde seg ukjenneleg, tok på seg andre klæde, og gjekk avstad med tvo fylgjesveinar. Dei kom til kona nattars tid. Og han sagde: «Få ein draug til å spå meg! Mana fram åt meg den eg nemner for deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Kona svara: «Du veit då sjølv kva Saul hev gjort, at han hev rudt ut or landet deim som manar fram draugar og spåvette. Kvifor vil du då leggja ut snaror for meg, so eg må lata livet?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Saul svor ein eid til henne ved Herren og sagde: «So sant Herren liver: ingi skuld skal råka deg for denne saki!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Kona spurde: «Kven vil du eg skal mana for deg?» Han svara: «Mana fram åt meg Samuel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Då kona fekk sjå Samuel, sette ho i eit høgt skrik. Og ho sagde med Saul: «Kvifor hev du svike meg? Du er Saul!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Kongen svara: «Ver hugheil! Kva er det du ser?» Kona sagde: «Eg ser ein gud koma upp or jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, '«Korleis ser han ut?» spurde han. Ho svara: «Det er ein gamall mann som kjem upp, sveipt i ei kåpa.» Då skyna Saul det var Samuel, og lutte andlitet mot jordi og bøygde seg for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Og Samuel spurde Saul: «Kvi uroar du meg og manar meg fram?» Saul svara: «Eg er i stor naud. Filistarane fører krig mot meg, og Gud hev vike frå meg og svarar meg ikkje, anten gjenom profetar eller gjenom draumar. Difor kalla eg på deg, so eg fær vita kva eg skal gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel svara: «Kvi spør du meg, når Herren hev vike frå deg og hev vorte uvenen din?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Herren hev no gjort med deg som han sagde gjenom min munn: Herren hev rive riket ut or di hand og gjeve det åt ein annan, åt David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Av di du ikkje lydde Herren og ikkje let den brennande harmen hans råka Amalek, difor hev Herren gjort dette mot deg no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Herren vil gjeva både deg og Israel i filistarmagt. I morgon skal du og sønerne dine vera hjå meg. Og jamvel Israels-lægret vil Herren gjeva i filistarmagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Då datt Saul brått til jordi so lang han var; so forfærd vart han for ordi frå Samuel. Magtløysa tok honom; for han hadde ikkje smaka matbiten eit heilt døger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Kona gjekk fram åt Saul. Og då ho såg kor reint forstøkt han var, sagde ho med honom: «Sjå terna di lydde deg, og eg våga livet og rette meg etter dei ordi du tala åt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'So lyd no du terna di, so vil eg setja fram litevetta mat åt deg, og du må eta, so du kann magtast att fyrr du fer din veg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Han vilde ikkje: «Eg vil ikkje eta», sagde han. Men då både tenarane og kona naubad honom, so let han seg segja, reis upp, og sette seg på sengi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Kona hadde ein gjødkalv heime. Ho skunda seg, fekk slagta honom. So tok ho mjøl, knoda og baka søtebrød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'So bar ho det fram for Saul og tenarane. Og då dei hadde ete, reis dei upp, og gjekk av stad same natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Filistarane fylkte alle herarne sine i Afek. Israel låg i læger attmed kjelda i Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Filistarfyrstarne gjekk fram med sine hundrad mann og sine tusund. Og David og kararne hans kom attarst, i lag med Akis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Filistarfyrstarne spurde: «Kva hev desse hebræarane her å gjera?» Akis svara: «De veit då at David som var hirdmann hjå Saul, Israels-kongen, han hev vore hjå meg år og dag, og eg hev aldri funne nokon ting å segja på honom frå den stund han vart min mann og til i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Men filistarfyrstarne vart forarga på honom, og dei sagde ifrå til honom: «Send den karen heim att! Lat honom halda seg på den staden du hev sett honom yver! Lat honom ikkje fara i strid saman med oss! Midt i slaget kann han venda seg mot oss. Kor kunde han betre vinna att godviljen hjå herren sin, enn med hovudi av hermennerne våre?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Er det ikkje til æra for denne David at dei syng med dei dansar: «Tusund tynte Saul men David tie tusund»?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Då kalla Akis David til seg og sagde: «So sant Herren liver: Du er ein ærleg kar! og eg likar godt å sjå deg ganga ut og inn hjå meg i lægret. For eg hev inkje vondt funne hjå deg frå den stund du kom til meg og heilt til no. Men fyrstarne likar deg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'So far heim att i fred, so du ikkje skal gjera noko som filistarfyrstarne mislikar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David sagde med Akis: «Kva hev eg då gjort? og kva hev du funne å segja på tenaren din frå den dagen eg kom fram for deg og heilt til i dag, etter som du negtar meg å ganga i strid mot uvenerne dine, herre konge?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Akis svara: «Eg veit best sjølv at eg held deg som ein gudsengel! Men filistarfyrstarne stend på sitt: han fær ikkje vera med oss i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Ris no tidleg upp i morgon, du og tenarane åt herren din som er komne med deg; og når det de hev gjort, so far dykkar veg so snart det ljosnar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'David og kararne hans reis då upp tidleg, for sin veg um morgonen, og kom heim att til Filistarlandet. Men filistarane drog upp til Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Då no David og kararne hans kom til Siklag tridje dagen, hadde amalekitarne gjort ei herjeferd i Sudlandet og i Siklag, hadde teke Siklag og sett eld på byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Kvendi der i byen hadde dei rana, både store små, og drege av med deim. Dei hadde ikkje drepe nokon, berre teke deim med seg, og fare sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Då David og kararne hans kom til byen og fekk sjå at han var brend, og fekk høyre at konorne og sønerne og døtterne deira var rana og burtførde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'då sette dei i og gret, både David og folki som var med honom. Dei gret so lenge til dei ikkje orka gråta meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Dei tvo konorne åt David var og rana, Ahinoam frå Jizre’el og Abiga’il, kona åt Nabal frå Karmel, var og hertekne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'David kom i stor knipa; folki hans tala frampå um å steina honom, so beiskeleg innharme var dei alle i hop for tapet av sønerne og døtterne sine. Men David henta styrke hjå Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'David baud presten Abjatar Ahimeleksson: «Kom hit med messehakelen!» Abjatar kom fram til David med messehakelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'David spurde so Herren: «Skal eg setja etter desse ransmennerne? Kann eg nå deim att?» Han fekk til svar: «Gjer det! Nå deim kann du! Berga kann du!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'So lagde David i veg med dei seks hundrad kararne sine. Dei kom til bekken Besor. Der stogga dei som laut vera etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'David heldt fram med fire hundrad mann. Tvo hundrad mann stogga og gjekk ikkje yver Besorbekken; dei var for trøytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Dei fann ein egyptar liggjande ute på marki, og dei henta honom til David. Og då dei hadde gjeve honom mat å eta og vatn å drikka;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'og han fekk eit stykke fikekaka og tvo rosinkakor å eta, livna han til; for han hadde ikkje smaka anten vått eller turt i tri heile døger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David spurde honom: «Kven høyrer du til, og kvar er du frå?» Han svara: «Ein egyptarsvein er eg, træl hjå ein amalekit. Husbond for frå meg i fyrrdags, av di eg var sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Me hadde gjort ei herjeferd i Sudlandet og den luten som høyrer til kretarane og den som høyrer til Juda og den som Kaleb åtte, og Siklag hev me brent.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David spurde: «Vil du syna oss veg til desse ransmennerne?» Han svara: «Gjer eid ved Gud at du ikkje drep meg eller gjev meg i henderne på herren min, so skal eg syna deg vegen til ransmennerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Han synte deim veg, og dei kom yver deim med dei låg utyver marki og åt og drakk og gama seg med det store herfanget dei hadde teke i Filistarlandet og Judalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'David hogg deim ned, og heldt på frå skumingi den eine dagen til kvelden den andre dagen. Og ingi livande sjæl berga seg undan, so nær som fire hundrad unggutar, som sette seg på kamelarne og rømde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'So berga David alt det amalekitarne hadde teke. Dei tvo konorne sine berga han og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Dei sakna ingen anten liten eller stor, søner eller døtter, ikkje noko av herfanget dessmeir eller noko av alt det dei hadde rana med seg; David førde heim att alt i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'David tok alle krøteri, bufe og smale, og førde fyre den andre buskapen og sagde: «Dette er herfanget åt David!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Då David kom til dei tvo hundrad mann som hadde vore for trøytte til å fylgja, og som difor stogga attmed Besorbekken, gjekk dei til møtes med David og fylgjesveinarne hans. Og David gjekk burtåt folki og helsa deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Alle illmenni og uvyrderne millom fylgjesveinarne åt David tok til ords og sagde: «Etter di desse ikkje fylgde oss, fær dei ingen ting av det herfanget me berga. Einast kona og borni kann kvar taka med seg heim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Men David svara: «Far ikkje soleis, brørne mine, med det som Herren gav oss! Han hev verna oss, og let oss vinna yver ransmennerne som kom yver oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kven vil lyda dykk i dette? Dei som fer i striden, og dei som er att og vaktar tyet, skal hava jamstor lut! Luterne skal skiftast likt!».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Soleis stod det ved lag frå den dagen og alle dagar. Han gjorde det til lov og rett i Israel som gjeld den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Då so David kom til Siklag, sende han noko av herfanget til dei øvste i Juda, til venerne sine, med dei ordi: «Her er ei gåva åt dykk av herfanget frå Herrens uvener!» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Til dei øvste i Betel, i Ramot i Sudlandet og i Jattir,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'i Aroer, i Sifmot, i Estemoa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'i Rakal og i jerahme’elit-byarne og kenitarbyarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'i Horma, i Bor-Asan, i Atak,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'i Hebron, og alle dei staderne der David hadde ferdast med kararne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Filistarane gjekk på i striden mot Israel. Israels-mennerne rømde undan for filistarane, og det låg mange falne på Gilboafjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Filistarane sette etter Saul og sønerne hans. Og filistarane felte Jonatan, Abinadab og Malkisua, Sauls-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Saul sjølv kom upp i ein hard strid. Og nokre bogeskyttarar råka innpå honom. Saul vreid seg i rædsla for skyttarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Og han baud våpnsveinen sin: «Drag sverdet ditt, og støyt det gjenom meg, so ikkje desse u-umskorne skal koma og drepa meg, og skamfara meg!» Men våpnsveinen vilde ikkje; han var altfor rædd. Då tok Saul sverdet sjølv og stupte seg på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Då våpnsveinen såg Saul var dåen, stupte han seg ogso på sitt sverd og fylgde honom i dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Den dagen fall dei alle i hop, Saul og dei tri sønerne hans og våpnsveinen, og sameleis alle mennerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Og då Israels-mennerne på hi sida dalen og på hi sida Jordan gådde at Israels-mennerne hadde rømt, og at Saul og sønerne hans var falne, so rømde dei ut or byarne sine; og filistarane kom og busette seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Dagen etter kom filistarane og plundra liki. Dei fann Saul og dei tri sønerne hans liggjande på Gilboafjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Dei hogg hovudet av honom, og rana våpni hans og sende rundt i Filistarlandet, og let forkynna fagnadbodet i templi åt avgudarne sine og millom folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Dei lagde våpni hans i Astarte-templet; og liket hans hengde dei upp på bymuren i Bet-San.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Då folket i Jabes i Gilead høyrde gjete det filistarane hadde gjort med Saul,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'tok dei i veg, alle våpnføre karar, gjekk heile natti, tok ned frå muren i Bet-San Sauls lik og liki av sønerne hans, for so til Jabes og brende liki der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'So tok dei og grov beini deira ned under tamariska i Jabes og heldt fasta i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Saul var dåen, og David var attkomen frå sigeren yver Amalek og hadde halde seg i Siklag tvo dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Då hende det seg tridje dagen at han fekk sjå ein mann kom springande frå Sauls-lægret med sundrivne klæde og mold på hovudet. Då han kom burtåt David, fall han å gruve til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'David spurde honom: «Kvar kjem du ifrå?» Han svara: «Eg hev kome meg undan frå Israels-lægret.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, '«Kor hev det gjenge?» spurde David, «seg meg det!» Han svara: «Folket rømde frå striden, mange av herfolket fall og døydde; Saul og Jonatan, son hans, er døydde og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'David spurde sveinen som kom med tidendi: «Kor veit du at Saul og Jonatan, son hans, er daude?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Då svara tidendsveinen: «Av eit hende høvde eg til å koma upp på Gilboafjellet og fekk sjå Saul studde seg til spjotet sitt, medan stridsvognerne og hestfolket sette inn på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Han vende seg og såg meg, og ropte på meg, og eg svara ja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Han spurde meg kven eg var; eg svara eg var ein amalekit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'So bad han meg: «Kom hit og drep meg! eg hev fenge baneridi, alt med det endå er liv i meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Eg gjekk då fram og gav honom banestyngen. Eg skyna han kunde ikkje liva når han stupte. Eg tok so hovudgullet og ein armring av honom og bar hit til deg, herre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Då tok David og reiv sund klædi sine. Sameleis gjorde alle fylgjesveinarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Dei øya og gret og fasta alt til kvelden, for di Saul og Jonatan, son hans, og Herrens folk og Israels ætt hadde falle for sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'David spurde tiendsveinen: «Kvar er du ifrå?» Han svara: «Framandmanns son, amalekit er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Då sagde David med honom: «Kor våga du leggja hand på den som Herren hev salva, og drepe honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Og David ropa på ein av sveinarne sine og sagde: «Hit, og hogg honom ned!» Og han gav honom banehogg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, '«Ditt blod kome yver ditt hovud,» sagde David; «din eigen munn vitna mot deg då du sagde: «Eg hev drepe honom som Herren hadde salva.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'David kvad eit syrgjekvæde yver Saul og Jonatan, son hans');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'han baud dei skulde læra Juda-borni «Kvædet um bogen», det finst uppskrive i boki åt den rettvise:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Israels prydnad! drepen ligg du på haugarne dine! Ai ei! falne er kjemporne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Gjet det ikkje i Gat! Lat deim ikkje gleda seg i Askalons-gatorne, so ikkje filistardøtter skal frygda seg og døtter av u-umskorne fegnast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Og Gilboafjell! gjev dogg og regn ei må falla på dykk! og ingen åke gro med offergåvor! Der kasta kjemporne skjoldarne frå seg. Skjolden åt Saul - aldri med olje han meir vert smurd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Av bøygde aldri Jonatans boge frå blod åt falne, frå feitta åt kjempor. Og aldri kom sverdet hans Saul kom att med ugjort!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul og Jonatan, elska og ljuvlege, uskiljande både i liv og daude! snøggare var dei enn ørnar, sterkare var dei enn løvor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Israels døtter! Gråt for Saul, han som klædde dykk i yndeleg skarlak, han som prydde med gull dykkar klæde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Ai ei! kjemporne fall i striden! Jonatan, drepen ligg han på haugarne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Sårt eg deg syrgjer, Jonatan, bror min! Utifrå yndeleg var du for meg. Kjærleiken din kjærare var meg enn kvende-elsk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Ai ei! at kjempor fall, og båe strids-sverdi øyddest!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Sidan spurde David Herren: «Skal eg draga upp til ein av byarne i Juda?» Herren svara ja. «Kvar helst?» spurde David. Herren svara: «Til Hebron.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'So drog David dit med båe konorne sine, Ahinoam frå Jizre’el og Abiga’il, kona åt Nabal frå Karmel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'David førde ogso fylgjesveinarne sine dit upp med huslydarne sine; og dei busette seg i byarne kringum Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Då kom Juda-folket dit og salva David til konge yver Juda-ætti. Då David fekk høyra at det var folket i Jabes i Gilead som hadde gravlagt Saul,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'sende han bod til folket i Jabes i Gilead og sagde til deim: «Velsigna av Herren vere de som gjorde denne sælebotstenesta mot Saul, herren dykkar, at det gravlagde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'So vise då Herren dykk kjærleik og truskap! Sjølv vil eg løna dykk vel for de gode de gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Ver då urædde, og dugande karar! Saul, herren dykkar, er dåen; men meg hev Juda-ætti salva til konge yver seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner Nersson, herhovdingen åt Saul, tok Isboset Saulsson og førde honom yver til Mahanajim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'og gjorde honom til konge yver Gilead, yver asuritarne og Jizre’el, yver Efraim, yver Benjamin, og yver heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Isboset Saulsson var fyrti år gamall då han vart konge yver Israel, og han var konge i tvo år. Einast Juda-ætti fylgde David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Og den tidi David var konge i Hebron yver Juda-ætti, var sju år og seks månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Abner Nersson drog ut frå Mahanajim til Gibeon med folket åt Isboset Saulsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Joab Serujason og Davids folk drog ut dei og. Og dei møttest ved Gibeontjørni. Der stogga dei på kvar si sida av tjørni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Abner sagde til Joab: «Lat nokre av sveinarne våre koma fram og halda våpnleik for oss!» «Ja vel,» svara Joab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Dei kom og møtte fram like mange i tal: tolv av Benjamin for Isboset Saulsson, og tolv av Davids folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Dei treiv kvarandre kring hovudet, og rende sverdi i sida på kvarandre, so dei fall alle i hop. Difor heitar den staden Sverdåkeren; han ligg attmed Gibeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Då vart det ein ovhard strid den dagen. Abner og Israels-mennerne vart slegne av Davids folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Tri søner av Seruja var med i striden: Joab, Ahisai og Asael. Asael var lettføtt som ei hind i heidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Og Asael forfylgde Abner, og veik korkje til høgre eller vinstre frå Abner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner vende seg og sagde: «Er du Asael?» Han svara ja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner sagde til honom: «Vend deg ei onnor leid, til høgre eller til vinstre! Tak på ein av sveinarne, og freista taka våpni hans!» Men Asael vilde ikkje slutta å elta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abner heldt endå fram og ropa til Asael: «Lat meg vera! elles lyt eg slå deg til jordi; og korleis skal eg då sjå Joab, bror din, i augo?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Men han vilde ikkje slutta. Og so støytte Abner bakenden av spjotet inn i magen hans, so spjotet gjekk ut gjenom ryggen. Og det vart hans bane. Alle stogga når dei kom dit Asael fall og døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Joab og Abisai forfylgde Abner. Men då soli gladde, var dei komne til Ammahaugen, beint imot Giah, på vegen til Gibeons-øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Då samla dei seg, Benjamins-folki, attum Abner, so dei vart til ein flokk, og fylkte seg på toppen av ein og same haugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Abner ropa til Joab: «Skal då sverdet halda på og øyde i all æva? Skynar du ikkje at dette tek ein beisk ende? Kor lenge vil du drygja fyrr du byd folki dine slutta å elta brørne sine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab svara: «So sant Gud liver: hadde du ikkje tala, so vilde folket ha slutta å elta brørne sine alt frå morgonen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Joab let blåsa i luren. Alle stana, og slutta å elta Israel. Og so heldt dei upp å slåst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner og kararne hans for yver heidi heile natti; dei gjekk yver Jordan og for gjenom heile Bitron, og kom so til Mahanajim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Då Joab hadde slutta å elta Abner, samla han alt folket. Då sakna dei nittan mann av Davids folk, forutan Asael.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'David folk hadde drepe tri hundrad og seksti mann av benjaminitarne og Abner-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Dei tok Asael og gravlagde honom i farsgravi i Betlehem. So gjekk dei heile natti, Joab og mennerne hans, og kom ved dagsprett til Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Men krigen millom Sauls-ætti og Davids-ætti vart langdrjug. David vart stendigt sterkare; men Sauls-ætti minka i magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'David fekk søner i Hebron: Eldste sonen, Amnon, fekk han med Ahinoam frå Jizre’el;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'den andre, Kilab, med Abiga’il, kona åt Nabal frå Karmel; den tridje, Absalom, var son åt Ma’aka, som var dotter åt kong Talmai i Gesur,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'den fjorde, Adonia, var son åt Haggit, den femte, Sefatja, son åt Abital;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'den sette, Jitream, fekk han med Egla, kona si. Desse sønerne fekk David i Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'So lenge no krigen varde millom Sauls-ætti og Davids-ætti, var Abner det trygge festet for Sauls-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Men no hadde Saul havt ei fylgjekona som heitte Rispa Ajadotter. Isboset spurde Abner: «Kvifor hev du halde deg med fylgjekona hans far?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Dei ordi av Isboset gjorde Abner brennande harm: «Er eg ein hundehaus frå Juda?» sagde han; «nett medan eg gjer sælebot mot ætti åt Saul, far din, mot frendarne hans og venerne hans, medan eg vernar deg mot å falla i henderne på David, so kjem du med vondord for eit kvende skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Gud late Abner bøta no og sidan, um eg ikkje heretter fer med David etter den eiden Herren hev svore honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'å taka kongedømet frå Sauls-ætti og reisa upp Davids kongsstol yver både Israel og Juda, frå Dan til Be’erseba.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Isboset orka ikkje svara Abner eit ord, so rædd vart han for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Abner sende straks bod til David med dei ordi: «Kven eig landet?» og han lagde til: «Gjer samband med meg, so skal eg hjelpa deg å få heile Israel yver på di sida.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Han svara: «Det er vel. Eg gjer samband med deg. Men ein ting krev eg av deg: du kjem ikkje fram for meg utan du hev med deg Mikal Saulsdotter når du kjem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'David sende bod til Isboset Saulsson med dei ordi: «Gjev meg Mikal, kona mi, som eg fekk til brur for hundrad huvehold av filistarar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboset sende bod og henta henne frå Paltiel La’isson, mannen hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Han fylgde gråtande etter henne heilt til Bahurim. Då tok Abner og truga honom: «Gakk heim att!» Og han gjekk heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner samrådde seg med dei øvste i Israel, og sagde: «Alt lenge siden hev de ynskt dykk David til konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'So gjer no alvor av det! For Herren hev sagt med David: «Ved handi hans David, tenaren min, vil eg fria Israel, folket mitt, frå filistarane og frå alle uvenerne.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abner talde fyre Benjamins-folket og. So gjekk Abner av stad, og vilde tala med David i Hebron um alt det Israel og Benjamins-ætti hadde funne fyre å svara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Då Abner kom til David i Hebron med tjuge mann i fylgje, gjorde David eit gjestebod for Abner og fylgesveinarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Abner sagde med David: «Lat meg ganga av stad og stemna saman heile Israel ikring deg, herre konge, so dei kann gjera samband med deg, og du kann verta konge yver so mange som du ynskjer!» David sende Abner av stad, og han drog med full trygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Nett då kom Joab med Davids folk heim frå ei herjeferd, og hadde rikt herfang med seg. Abner var ikkje hjå David i Hebron då. David hadde sendt honom av stad med full trygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Då no Joab og heile heren hans kom heim, fekk han den tiendi: «Abner Nersson kom til kongen; og kongen let honom ganga av stad med full trygd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Joab gjekk til kongen og sagde: «Kva er det du hev gjort? Fyrst Abner kjem til deg, let du honom ganga av stad, so han fritt fær fara sin veg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Du kjenner vel Abner Nersson? Han kjem berre og vil lokka eitkvart utor deg, og gjæta på deg når du fær ut og fær heim, og røkja etter alt du tek deg fyre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Då Joab kom ut frå David, sende han bod etter Abner; og sendemennerne førde honom attende frå Bor-Hassira; men David visste det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Då Abner kom att til Hebron, tok Joab honom til sides i porten, og lest vilja tala med honom i einmæle. Der gav han honom banesår med ein styng i livet, til hemn for dråpet på Asael, bror hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Då David sidan spurde dette, sagde han: «Eg og kongedømet mitt er i all æva utan skuld for Herren i blodet hans Abner Nersson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Må det koma yver Joab og heile ætti hans! Gjev det aldri må vanta i ætti åt Joab folk som hev flod eller spillsykja, som styd seg på krykkja eller fell for sverd, eller saknar mat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Joab og Abisai, bror hans, hadde myrdt Abner for dråpet på broren Asael i slaget ved Gibeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Men David baud Joab og heile fylgjet hans: «Riv sund klædi dykkar! Sveip sekkjer um dykk! Og øya og gråt yver Abner!» Og kong David fylgde sjølv etter likbåra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Abner vart gravlagd i Hebron. Og kongen sette i og gret ved gravi hans Abner; og heile folket gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'David kvad eit syrgjekvede yver Abner: «Laut du Abner døy som ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Henderne dine batt dei ikkje, føterne dine fjetra dei ikkje! Nidingsdråp er det, so som du vart drepen!» Då gret alt folket endå meir yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Alt folket kom og talde David til å eta eitkvart fyrr dagen leid. Men David svor og sagde: «Gud late meg bøta både no og sidan, um eg smakar matbiten eller noko som helst fyre soleglad!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Heile folket merkte seg ordi og lika det godt. I det heile lika folket godt alt det kongen gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Heile folket og heile Israel skyna den dagen at kongen ingi skuld hadde i dråpet på Abner Nersson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Kongen sagde med tenararne sine: «Veit de det er ein hovding og stor mann som er fallen i dag i Israel?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Eg er endå veik, endå eg er salva til konge. Og desse kararne, Seruja-sønerne, er sterkare enn eg. Herren løne nidingen etter nidingsverket hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Då Saulssonen spurde at Abner var dåen i Hebron, miste han reint modet, og heile Israel vart forstøkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Saulssonen hadde hjå seg tvo herhovdingar for herjeferderne sine. Ba’ana heitte ein, og Rekab heitte hin, sønerne åt Rimmon frå Be’erot, av Benjamins-ætti; for Be’erot vart og rekna med til Benjamin;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'folket i Be’erot hadde rømt til Gittajim, og budde sidan der som utlendingar, alt til no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Jonatan Saulsson hadde ein son som var lamen på båe føterne. Fem år gamall var han då tidendi frå Jizre’el kom um Saul og Jonatan. Barnfostra tok og rømde med honom. Men i hurten og sturten datt han; og so vart han lamen. Mefiboset heitte han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'No gjekk Rekab og Ba’ana, sønerne åt Rimmon frå Be’erot, av stad og kom høgstedags til huset åt Isboset medan han låg og kvilde middag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Dei lest henta kveite, kom seg soleis inn i huset, og såra honom i livet. Og so kom dei seg undan både Rekab og Ba’ana, bror hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Det var medan han låg i sengi i kammerset at dei kom inn i huset og gav honom banesår. Dei hogg av hovudet hans, og tok det med seg, gjekk yver heidi heile natti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'førde hovudet hans Isboset til David i Hebron, og sagde med kongen: «Her er hovudet åt uvenen din, Isboset Saulsson, han som vilde taka livet ditt. Herren hev i dag gjeve deg, herre konge, hemn yver Saul og ætti hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'David svara Rekab og Ba’ana, bror hans, sønerne åt Rimmon frå Be’erot: «So sant Herren liver som hev frelst meg ut frå all fåre:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'den som kom med tidendi: «Saul er dåen!» og meintest koma med fagnadbod til meg, honom let eg gripa og drepa i Siklag, han som eg skulde gjeve løn for fagnadbod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Men når nidingar myrder ein rettvis mann i heimen hans, i sengi - kor mykje meir må eg ikkje krevja blodet hans av dykkar hender, og rydja dykk burt frå jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'David baud sveinarne sine drepa deim, og hogga av deim hender og føter og hengje deim upp attmed Hebrontjørni. Hovudet hans Isboset tok dei og gravlagde i Abners grav i Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Då kom alle Israels ætter til David i Hebron, og tala soleis: «Du veit me og du er same folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Alt lenge sidan, med Saul var kongen vår, so var du føraren for Israel. Og med deg hev Herren sagt: «Du skal vera hyrding for Israel, folket mitt! du skal vera fyrste yver Israel!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Då alle dei øvste i Israel var komne til Hebron, til kongen, gjorde kong David samband med deim i Hebron for Herrens åsyn. Og dei salva David til konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Tretti år var David då han vart konge. Og han var konge i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'I Hebron var han konge yver Juda i sju år og seks månader. I Jerusalem var han konge i tri og tretti år yver heile Israel og Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Kongen drog upp til Jerusalem med heren sin mot jebusitarne, som budde der i landet. Dei sagde då til David: «Hit inn vinn du ikkje koma! Jamvel blinde og lame folk kann driva deg burt berre med dei ordi: Hit kjem David ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'David tok like vel Sionsborgi. Den borgi vart Davidsbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'David gav den dagsordren: «Kvar ein som slær jebusitarne, lat honom ganga upp til vatsleidingi, og slå desse blinde og lame som ber David imot!» Difor plar dei segja: «Blind og lam kjem ikkje inn i huset.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'David tok bustad der på borgi og kalla henne Davidsbyen. David bygde byen rundt ikring frå Millo og innetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Davids velde auka stødt og stendigt. Og Herren, allhers Gud, var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Kong Hiram i Tyrus sende folk til David med cedertre og timbremenner og steinhoggarar. Dei bygde eit hus for David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Og David skyna at Herren hadde grunnfest kongedømet hans yver Israel, og lyft kongedømet hans upp til æra for Israel, folket sitt, skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'David tok seg endå fleire fylgjekonor og konor frå Jerusalem, etter han var komen dit frå Hebron. Og David fekk endå fleire søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Dei sønerne han fekk i Jerusalem heitte: Sammua, Sobab, Natan, Salomo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibhar, Elisua, Nefeg, Jafia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada og Elifelet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Då filistarane frette at David var salva til konge yver Israel, drog alle filistarane upp og søkte åt honom. Då David spurde det, drog han ned til borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Filistarane kom og spreidde seg utyver i Refa’imsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Då gjorde David det spursmålet til Herren: «Skal eg draga upp mot filistarane? Vil du gjeva deim i mi hand?» Herren svara David: «Drag upp, eg vil gjeva filistarane i di hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'David kom til Ba’al-Perasim. Og der vann David yver deim. Då sagde han: «Herren hev brote igjenom uvenerne mine, liksom vatn bryt igjenom.» Det er difor staden hev fenge namnet Ba’al-Perasim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Dei let etter seg gudebilæti sine, og David og folki hans tok deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Endå ein gong drog filistarane upp og spreidde seg utyver i Refa’imsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Då David spurde Herren, svara han: «Drag ikkje mot deim! Kringset deim attanfrå, so du fell yver deim frå den staden der bakatrei stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'So snart du høyrer ljoden av stig i topparne på bakatrei, so må du springa fram. For då dreg Herren ut framfyre deg og vinn yver filistarheren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David gjorde som Herren baud; og han slo filistarane og forfylgde deim frå Geba heilt fram til Gezer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Endå eingong stemnde David saman alt det utvalde mannskapet i Israel: tretti tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Og David gav seg på veg, og drog ut med alt sitt folk frå Ba’ale-Juda, og førde derifrå Guds kista, som heiter etter Herren, allhers drott, han som tronar på kerubarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Dei sette Guds kista på ei ny vogn og førde henne frå Abinadabs hus på haugen. Og Uzza og Ahjo Abinadabs-søner køyrde den nye vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Soleis førde dei Guds kista burt frå Abinadabs hus på haugen, med di dei fylgde henne, og Ahjo gjekk fyre kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David og heile Israels-ætti leika for Herren, til alle slag spel av cypresstre, til cithrar, harpor, trummor, bjøllor og cymblar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Då dei kom burtimot treskjestaden åt Nakon, tok Uzza tak med henderne i Guds kista og heldt fast i henne, av di uksarne snåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Då loga Herrens harm upp mot Uzza. Og Gud slo honom for det brotet skuld. Og han fekk sin bane der attmed Guds kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'David vart ille ved av di Herren øydelagde Uzza. Og den staden heite Peres-Uzza den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Men David vart so rædd for Herren den dagen, at han sagde: «Kor kann eg våga føra Herrens kista upp til meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Difor vilde ikkje David flytja Herrens kista upp til Davidsbyen, men let deim setja henne inn i huset åt gatiten Obed-Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'So stod Herrens kista der i tri månader. Og Herren velsigna Obed-Edom og heile hans hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Då kong David spurde at Herren velsigna huset åt Obed-Edom og all hans eigedom for Guds kista skuld, drog David av stad og flutta Guds kista derifrå og upp til Davidsbyen med stor fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Då dei som bar Herrens kista, hadde gjenge seks stig, ofra han ein ukse og ein gjødkalv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'David sjølv dansa av all magt framfor Herren i ein messehakel av lin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Soleis henta David og heile Israels-ætti Herrens kista dit upp med fagnadrop og lurljod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Då Herrens kista kom inn i Davidsbyen, stod Mikal Saulsdotter og såg ut igjenom vindauga. Då ho fekk sjå kong David sprang og dansa framfor Herren, då fekk ho vanvyrdnad for honom i sitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Då dei hadde ført Herrens kista upp, sette dei henne på sin stad midt i det tjeldet som David hadde reist åt henne. David ofra brennoffer og takkoffer for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Og då han var ferdig med desse ofringarne, velsigna han folket i namnet åt Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Deretter skifte han ut åt heile folket, åt heile Israels-ålmugen, både åt kar og kvende, ei hellekaka, eit stykke kjøt og ei rosinkaka til manns. So gjekk heile folket heim kvar til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Men då David kom heim og helsa husfolki sine, gjekk Mikal Saulsdotter til møtes med honom og sagde: «Kor måtte ikkje Israels konge kjenna seg høgvyrd i dag, med han i dag hev nækt seg framfor tenestgjentorne åt tenarane sine, soleis som skamlaust folk plar nækja seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'David svara Mikal: «For Herrens åsyn hev eg dansa, han som valde meg ut framfor far din og framfor heile hans ætt, og sette meg til fyrste for Israel, Herrens folk. For Herrens åsyn var det eg dansa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'og småminka meg meir, og verta ring i mine augo. Men hjå dei tenestgjentorne du nemnde, hjå deim skal eg verta høgvyrd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Mikal Saulsdotter vart verande barnlaus alt til sin døyande dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Ein gong kongen sat i huset sitt, og Herren hadde unnt honom fred for alle uvenerne sine rundt ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'so sagde han med profeten Natan: «Sjå her bur eg i eit hus av cedertre; men Guds kista bur i eit tjeld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Natan svara kongen: «Gjer du alt det du finn fyre! For Herren er med deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Men natti etterpå kom Herrens ord til Natan soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '«Gakk av stad og seg med David, tenaren min: «So segjer Herren: Etlar du byggja hus der eg skal bu?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Eg hev då ikkje butt i noko hus heilt frå den tid eg førde Israels-borni upp frå Egyptarland alt til i dag, men hev flutt rundt i eit tjeld og i ei bud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'All den tidi eg flutte rundt med Israels-borni - hev eg noko sinn nemnt eit einaste ord um det med nokon av domarane i Israel som eg bad vakta Israel, folket mitt, og sagt: «Kvifor byggjer de ikkje eit hus av cedertre åt meg?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Og no skal du segja so med David, tenaren min: «So segjer Herren, allhers drott: Eg henta deg frå beitemarki der du fylgde småfeet, og sette deg til fyrste yver Israel, folket mitt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'eg var med deg på alle dine vegar, eg rudde ut alle dine uvener; og eg vil gjeva deg eit namn so stort som dei største på jordi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'og Israel, folket mitt, gjev eg ein bustad; der set eg deim ned, der skal dei få bu og aldri verta uroa meir; og aldri skal nidingar kua deim meir, so som i gamle dagar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'då eg sette domarar yver Israel, folket mitt; eg gjev deg fred for alle dine uvener. Og Herren forkynner deg at Herren vil byggja hus åt deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Når æva di er all, og du fær kvila hjå dine feder, so vil eg reisa upp avkjømet ditt som kjem etter deg og gjeng ut frå deg; hans kongedøme vil eg grunnfesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Han skal byggja hus åt meg, hans kongsstol vil eg grunnfesta til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Eg vil vera far for honom, han skal vera son min: gjer han noko gale, so vil eg refsa honom med manneris, med ulukkar som manneborn kann røyna;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'men mi miskunn skal aldri vika frå honom, so som ho veik frå Saul, då eg let honom vika undan for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Stød skal ætti di standa, traust og trygt ditt kongedøme i all æva for di åsyn; ja stødug skal din kongsstol standa i all æva.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Natan tala alle desse ordi til David og sagde honom heile denne syni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Då gjekk kong David inn og sette seg ned framfor Herrens åsyn og sagde: «Kven er eg, Herre, Herre! og kva er huset mitt, at du hev ført meg hit?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Og endå er det for lite i dine augo, Herre, Herre! Du gjev meg lovnader um huset åt tenaren din langt fram i tidi. På mannevis talar du um dette, Herre, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Kva hev no David meir å mæla med deg? Du kjenner tenaren din, Herre, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'For ditt ord skuld, og etter eigen hug, gjer du alt dette og kunngjer dette underverk for tenaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Difor er du stor, du Herre Gud. Ingen er som du! Forutan deg er det ingen Gud, etter alt me hev høyrt gjete med øyro våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Kvar finst på jordi noko folk maken til folket ditt, til Israel, som Gud sjølv gjekk av og løyste til sin eigen lyd, til eit frægdarnamn åt seg og gjorde so store gjerningar for dykk og agelege verk med landet ditt, for folket ditt, det som du sjølv løyste ut åt deg frå Egyptarland, frå heidningefolk og deira gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Israels-folket hev du grunnfest til ditt folk i all æva. Du, Herre, vart deira Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'So lat no lovnaden din, Herre Gud, um tenaren din og huset hans få standa stødt i alder og i æva! Gjer som du hev sagt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Då skal namnet ditt verta stort i all æva og lyda so: «Herren, allhers drott, er Gud yver Israel.» Og huset åt din tenar David skal standa stødt for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Du, Herre, allhers drott, Israels Gud! Sjølv hev du kunngjort for tenaren din: «Eg byggjar hus åt deg.» Difor hev tenaren din teke seg mod til å bera denne bøni fram for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Og no, Herre, Herre! Du er Gud, og dine ord er sætande, og du hev lova tenaren din alt dette gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'So gjer no vel, velsigna huset mitt so det må standa i all æva for di åsyn! Ja, du hev sagt det, Herre, Herre! Med di velsigning skal huset åt tenaren velsignast til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Ei tid deretter vann David yver filistarane og lagde deim under seg. David fekk dermed teke taumarne yver hovudstaden utor henderne på filistarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'So vann han yver moabitarne; deim mælte han med ei snor, det vil segja: han let deim leggja seg ned på marki, og mælte med tvo snorlengder deim som skulde lata livet, og med ei snorlengd deim som skulde liva. Moabitarne vart David undergjevne og laut leggja skatt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Dessutan vann David yver Soba-kongen Hadadezer Rehobsson, då han for i herferd og vilde tøygja magti si alt til Storelvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'David tok syttan hundrad hestfolk og tjuge tusund fotfolk. Og David let skjera sund hasarne på alle vognhestarne, sparde berre hundrad hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Då Syria-folket frå Damaskus kom Soba-kongen Hadadezer til hjelp, slo David tvo og tjuge tusund Syria-menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'David sette hervakter yver syrarane i Damaskus, og Syria-folket vart David undergjevne og laut leggja skatt. Soleis gav Herren David siger kvar helst han for fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'David tok dei gylte skjoldarne som Hadadezer-folki hadde bore, og førde til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Og frå Hadadezer-byarne Betah og Berotai tok kong David store mengder av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Då Hamat-kongen To’i frette at David hadde vunne yver heile Hadadezer-heren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'sende han Joram, son sin, til kong David til å helsa på honom og ynskja honom til lukka med krigen mot Hadadezer og med sigeren yver honom - for Hadadeser hadde jamt ført krig mot To’i - og han hadde med seg kostnadting av sylv, av gull og av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Kong David vigde deim og til Herren, like eins som han hadde gjort med sylvet og gullet frå folki han hadde lagt under seg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'frå syrarane, moabitarne, ammonitarne, filistarane og amalekitarne; like eins med herfanget frå Soba-kongen Hadadezer Rehobsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Då David kom heim etter sigeren yver syrarane, auka han frægdi si med di han slo attan tusund mann i Saltdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Han sette hervakter yver Edom; i heile Edomlandet sette han vakter; og alle edomitarne vart David undergjevne. Soleis gav Herren David siger kvar helst han drog fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'David var no konge yver heile Israel. Og David skipa lov og rett for heile folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab Serujason var øvste herhovding. Josafat Ahiludsson var kanslar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sadok Ahitubsson og Ahimelek Abjatarsson var prestar. Og Seraja var riksskrivar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja Jojadason var hovding yver livvakti. Sønerne åt David var prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'David spurte: «Finst det endå att nokon av Sauls hus? Eg vil gjera sælebot mot honom for Jonatans skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Sauls hus åtte ein tenar, Siba heitte han; honom kalla dei til David. Kongen spurde honom: «Er du Siba?» Han svara: «Ja, tenaren din er det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Kongen spurde: «Finst det endå att nokon av Sauls hus, som eg kann gjera Guds sælebot mot?» Siba svara kongen: «Det finst endå att ein son åt Jonatan, han er lam på båe føterne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kongen spurde: «Kvar er han?» Siba svara: «Han held seg no hjå Makir Ammielsson i Lo-Debar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Kong David sende då bod og henta honom frå Lo-Debar, frå heimen åt Makir Ammielsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Då Mefiboset, son åt Jonatan Saulsson, kom til David, fall han å gruve og bøygde seg. David sagde: «Mefiboset!» Han svara: «Ja, her er tenaren din.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David trøysta honom: «Ver hugheil; eg vil gjera sælebot mot deg for skuld Jonatan, far din. Eg gjev deg att all jordeigedomen åt Saul, farfar din. Og du skal allstødt eta ved mitt bord.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Då bøygde han seg og sagde: «Kva er eg, tenaren din, at du vendar deg til ein daud hund som meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Kongen kalla på Siba, sveinen åt Saul, og gav honom det bodet: «Alt det Saul og ætti hans åtte, gjev eg åt son til herren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Du og sønerne dine og tenarane dine skal dyrka og hausta eigedomen hans; og det skal vera til kost og tæring levemåte åt son til herren din. Men sjølv skal Mefiboset, son åt herren din, stødt eta ved mitt bord.» Siba hadde femtan søner og tjuge tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Han svara kongen: «Alt det du, herre konge, byd tenaren din, det skal tenaren din gjera.» «Og Mefiboset skal eta ved mitt bord som ein av kongssønerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefiboset hadde ein liten son, Mika heitte han. Alle som budde i huset åt Siba, vart tenarar for Mefiboset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Men sjølv budde Mefiboset i Jerusalem, då han stødt åt ved kongens bord. Han var lam på båe føterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Det hende seg deretter at ammonitarkongen døydde. Og Hanun, son hans, vart konge etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Då sagde David: «Eg vil syna Hanun Nahasson venskap, liksom far hans synte meg venskap.» David sende nokre av tenarane sine til å trøysta honom i sorgi yver faren. Tenarane åt David kom til Ammonitarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Då sagde ammonitarfyrstarne til Hanun, herren sin: «Trur du det er til heider for far din at David hev sendt trøystarar til deg? Å nei, David hev sendt tenarane til deg berre for di han vil granska byen og njosna, og sidan gjera enden på honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'So tok Hanun tenarane hans David og let raka av deim halve skjegget og skjera klædi deira midt yver like upp til seten, og sende deim heim soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Då David frette det, sende han folk til møtes med deim, og kongen let segja med deim: «Stana i Jeriko til dess skjegget hev vakse ut på dykk, so kann de koma heim att!» For mennerne hadde vorte øgjeleg svivyrde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Då no ammonitarne skyna dei hadde gjort David hatig på seg, sende dei bod og leigde tjuge tusund mann fotfolk, syrarar frå Bet-Rehob og syrarar frå Soba, eit tusund mann hjå kong Ma’aka, og tolv tusund av mannskapet åt Tob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Då David høyrde gjete det, sende han Joab med heile heren, det vil segja dei djervaste stridsmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Ammonitarne drog ut og fylkte seg framfor byporten, medan syrarane frå Soba og Rehob og Tob-folket og Ma’aka-folket stod for seg sjølve på opi mark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Då Joab gådde han laut vera budd på åtak både framme og bak, gjorde han eit utval millom dei utvalde Israels-hermennerne, og fylkte deim mot syrarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Resten av folket let han åt Abisai, bror sin, som so fylkte deim beint imot ammonitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Og han sagde: «Um syrarane vinn på meg, so kjem du meg til hjelp. Og um ammonitarne vinn på deg, so skal eg koma og hjelpa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Ver sterk! Lat oss syna oss sterke i striden for folket vårt og for byarne åt vår Gud! So fær Herren gjera det han tykkjer best.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Joab drog fram med mannskapet sitt og stridde mot syrarane, og dei rømde for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Då ammonitarne såg at syrarane rømde, so rømde dei og for Abisai, og sprang inn i byen. Og Joab drog burt frå ammonitarne og kom heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Då syrarane såg at dei var slegne av Israel, samla dei seg i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Hadadezer baud ut dei syrarane som budde på hi sida Storelvi. Og dei kom til Helam, med Sobak, herhovdingen åt Hadadezer, til førar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Då David spurde dette, stemnde han saman heile Israel, gjekk yver Jordan og kom til Helam. Syrarane fylkte seg og gjorde åtak på David og slost med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Men syrarane rømde for Israel, og David hogg ned sju hundrad krigshestar og fyrti tusund hestfolk av syrarheren; og herhovdingen Sobak fekk banehogg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Då alle lydkongarne under Hadadezer såg dei var slegne av Israel, gjorde dei fred med Israel og vart tenarane deira. So våga ikkje syrarane hjelpa ammonitarne meir.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Det hende seg året etter, den tid då kongarne plar fara i herferd, då sende David Joab av stad, og alle herhovdingarne som var under honom og heile Israel, og dei herja Ammonitarlandet og kringsette Rabba. Sjølv heldt David seg heime i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'No bar det so til ein dag ved kveldstid David reis upp frå kvila si og gjekk og dreiv på taket på kongshalli, at han såg frå taket ei kona som lauga seg. Kona var ovleg væn å sjå til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'David let spyrja etter kven kona var. Han fekk til svar: «Det er Batseba Eliamsdotter, kona åt hetiten Uria.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'David sende nokre folk og let henta henne. Ho kom upp, og han låg med henne. Ho hadde nett helga seg etter ho hadde vore urein. Og so for ho heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Kona vart med barn. Ho sende bod og melde David at ho var med barn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'David sende då det bodet til Joab: «Send hit hetiten Uria!» Joab sende Uria til David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Då Uria kom inn til honom, spurde David korleis Joab og heren hadde det, og kor det gjekk i krigen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'So sagde David med Uria: «No kann du ganga heim og lauga føterne dine.» Då Uria gjekk frå kongshalli, fylgde ei kongsgåva etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Men Uria lagde seg ved inngangen til kongshalli saman med alle kongstenarane; han gjekk ikkje heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'David fekk vita at Uria ikkje var gjengen heim. Då sagde David med Uria: «Du kjem då frå ei utferd! Kvifor gjeng du ikkje heim?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Uria svara: «Kista og Israel og Juda bur no i buder; Joab, herren min, og folket hans ligg i læger ute på marki. Og so skulde eg ganga heim og eta og drikka og liggja med kona mi? So sant Herren liver, og so sant du liver: dette gjer eg ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Då sagde David med Uria: «Stana her i dag og! So vil eg i morgon senda deg av stad.» Uria stana i Jerusalem den dagen og næste dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'David bad honom til seg, til å eta og drikka med seg; og han drakk honom drukken. Men um kvelden gjekk han av og lagde seg til kvile med kongstenarane; heim gjekk han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Morgonen etter skreiv David eit brev til Joab og sende det med Uria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'I brevet skreiv han: «Set Uria lengst framme, der som striden er hardast. Røm so undan frå honom, so han fær banehogg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Joab heldt på og kringsette byen. Då sette han Uria på den staden, der han visste han møtte dei djervaste kararne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Byfolket gjorde utfall og slost med Joab. Det fall då nokre av folket, av mannskapet åt David; hetiten Uria fekk og banen sin der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Joab sende melding til David um korleis det hadde gjenge i slaget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Og han gav sendemannen den fyresegni: «Når du er ferdig med å melda kongen alt um striden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'og so harmen kjem upp hjå kongen, og han spør deg: «Kvifor kom de so nær byen i striden? de måtte då vita at dei vilde skjota på dykk ovantil frå muren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kven var det som vart banen hans Abimelek Jerubbesetsson? Ei kona som kasta ein kvernstein i hovudet på honom ovanfrå muren! Det vart banen hans, der i Tebes! Kvifor kom de so nær muren?» - so skal du fortelja: «Tenaren din, hetiten Uria, fekk og banen sin.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Mannen gjekk og melde David alt det Joab hadde bode honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Mannen fortalde for David: «Kararne gjekk hardt på og drog ut mot oss i opi mark. Men me slo deim attende til byporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Då skaut bogeskyttarane på tenarane dine ovanfrå muren, so nokre av kongsmennerne dine fekk sin bane; tenaren din, hetiten Uria, fekk og sin bane der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David svara sendemannen: «So skal du svara Joab: «Gjer deg inkje ilt av dette! sverdet øyder so ein, so hin! Berre gakk på byen med større styrke, og riv honom ned til grunns!» Styrk hugen hans med dei ordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Då kona hans Uria spurde at mannen hennar var fallen, øya og gret ho yver husbonden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Då syrgjetidi var ute, sende David bod og let henta henne heim til seg. Ho vart kona hans, og ho åtte ein son. Men det David hadde gjort, var ilt i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Og Herren sende Natan til David. Då han kom inn til honom, sagde han med honom: «Det var tvo menner i ein by; den eine var rik, og den andre var fatig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Rikmannen åtte bufe og smale i rikleg mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Fatigmannen åtte inkje anna enn eit lite saulamb, som han hadde kjøpt og ale upp, og som voks upp inne hjå honom og sønerne hans, i lag med deim; det åt av brødbiten hans og drakk av staupet hans, og låg i fanget hans og var som ei dotter for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'So kom ein vegfarande mann til rikmannen. Då timdest han ikkje taka av sine eigne sauer eller naut sine og laga til åt ferdamannen som var komen til honom, men tok saulambet åt fatigmannen og laga til åt mannen som var komen til honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Då loga harmen veldug upp i David mot mannen, og han sagde til Natan: «So sant Herren liver: den mannen som det hev gjort, skal lata livet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'og saulambet skal han bøta firfaldt, for di han for soleis fram og var so hjartelaus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Natan svara: «Du er mannen. So segjer Herren, Israels Gud: «Eg salva deg til konge yver Israel; eg frelste deg or Sauls hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Eg gav deg huset åt herren din, og konorne åt herren din lagde eg i ditt fang. Eg sette deg yver Israels hus og Judas hus. Og var det for lite, so hadde eg gjeve deg endå meir både av eitt og hitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Kvifor hev du då vanvyrdt Herrens ord, og gjort det som er ilt i hans augo? Hetiten Uria hev du drepe med sverd, og kona hans hev du teke til kona åt deg sjølv! Honom myrde du med ammonitarsverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Difor skal no sverdet aldri vika frå ditt hus, av di du vanvyrde meg og tok kona åt hetiten Uria til kona åt deg sjølv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'So segjer Herren: «Sjå, eg let ulukke koma yver deg frå ditt eige hus. Konorne dine tek eg burt frå augo dine og gjev deim åt ein annan, so han ligg med konorne dine midt på ljose dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Du let det henda i løyndom; eg let dette henda midt på ljose dagen, so heile Israel er vitne til det.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'David svara Natan: «Synda hev eg mot Herren.» Natan sagde til David: «So hev Herren ogso ettergjeve deg skuldi di; du skal ikkje døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Men av di du hev fenge Herrens fiendar til å spotta honom for denne sak skuld, so skal heller ikkje den sonen du hev fenge vera liv lage.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'So gjekk Natan heim. Men Herren søkte med sott det barnet David hadde fenge med kona hans Uria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'David spurde Gud for barnet. Og David fasta. Og når han kom heim og skulde leggja seg um natti, lagde han seg på golvet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Dei øvste tenarane hans gjekk upp til honom og freista reisa honom upp frå golvet. Men han vilde ikkje. Heller ikkje heldt han måltid i lag med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Sjuande dagen døydde barnet. Då våga ikkje tenarane åt David melda honom at barnet hadde slokna. Dei tenkte: «Tala me til honom med barnet var i live, so lydde han ikkje på oss; kor kann me då melda honom at barnet hev slokna? Han kunde gjera ei ulukka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Men David gådde at tenarane kviskra saman, og han skyna barnet var dåe. David spurde tenarane: «Hev barnet slokna?» Dei svara ja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Då reis David upp frå golvet, vaska seg, salva seg, skifte klæde, gjekk inn i Herrens hus og kasta seg ned for honom. Og då han kom heim, bad han um mat. Dei fram mat åt honom, og han tok til å eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Då spurde tenarane honom: «Korleis heng dette i hop? So lenge barnet var i live, fasta du og gret for det; men når barnet hev slokna, ris du upp og held måltid!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Han svara: «So lenge barnet var i live, fasta eg og gret. Eg tenkte: «Kven veit? kann henda Herren vil miskunna meg og lata barnet liva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Men kvifor skulde eg fasta no det er dåe? Kann eg få det att meir? Eg skal fara til honom. Men han kjem ikkje att til meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'David trøysta Batseba, kona si. Han budde hjå henne og låg med henne. Ho åtte ein son, som han gav namnet Salomo. Honom hadde Herren kjær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Han sende bod med profeten Natan. Og han gav honom namnet Jedidja for Herrens skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joab gjorde åtak på hovudstaden Rabba i Ammonitarlandet, og hertok byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'So sende Joab bod til David og melde: «Eg hev gjort åtak på Rabba og hev teke vats-byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Stemn no i hop resten av folket! Kringset og tak byen, so det ikkje skal heitast at eg hev teke byen, og fær ordet for det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'David stemnde då saman alt herfolket, drog til Rabba, gjorde åtak og tok byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Han tok kongekruna frå hovudet på kongen. Ho var av gull og vog vel tvo vågar og var prydd med ein glimestein. Ho vart no sett på Davids hovud. Eit veldugt herfang førde han heim frå byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Folket i byen slæpte han burt, og sette til arbeid ved sagbruki, med treskjevalsorne av jarn og med jarnøksarne, og let deim træla ved tiglomnarne. Soleis gjorde han med alle ammonitarne. So snudde David med alt folket heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Sidan hende denne tilburden: Absalom Davidsson hadde ei væn syster som heitte Tamar, og Amnon Davidsson lagde hugen til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Ja Ammon pintest so, at han vart heiltupp sjuk av lyst til syster si; for ho var møy; og Ammon øygnde ingen utveg til å gjera henne noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Amnon hadde ein ven, som heitte Jonadab, son til Simea, bror åt David. Jonadab var ein utkropen kar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Han spurde honom: «Kvi magrast du so, du kongsson, frå dag til annan? Fortel meg det?» Amnon svara: «Eg hev huglagt Tamar, syster åt Absalom, bror min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Då sagde Jonadab til honom: «Legg deg sjuk på sengi di! Og når far din kjem og ser til deg, so bed honom: «Kjære, lat Tamar, syster mi, koma og laga maten åt meg! Lat henne laga til mat for augo mine, so eg ser på! Og lat meg eta av hennar hand!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon lagde seg og lest som han var sjuk. Kongen kom og såg til honom. Og Amnon bad kongen: «Kjære, lat Tamar, syster mi, koma og laga tvo kakor åt meg so eg ser på og fær eta av hennar hand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'David sende då bod inn i huset til Tamar og bad henne: «Gakk til huset åt Amnon, bror din, og laga noko mat åt honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Tamar gjekk til huset åt Amnon, bror sin, der han låg til sengs. Ho tok deig og knoda, og laga kakorne so han såg på, og steikte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'So tok ho panna og hadde deim or for honom; men han vilde ikkje eta. So sagde Amnon: «Gakk ut alle mann!» Og dei so gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'So segjer han med Tamar: «Kom med maten her inn i kammerset, so eg fær eta av handi di!» Og Tamar tok kakorne ho hadde laga, og gjekk inn i kammerset til Amnon, bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Men då ho bar deim fram åt honom, so han skulde eta, greip han fat i henne og sagde: «Kom og ligg med meg, syster mi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Ho svara: «Nei, bror min! Du må ikkje skjemma meg! Sovore må ikkje henda i Israel! Gjer ikkje so stygg ei gjerning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Kvar skulde eg gjera av meg med skammi? Og du sjølv vilde seinare heita eit styggeting i Israel. Tala fyrst med kongen! Han vil ikkje negta deg å få meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Men han vilde ikkje lyda henne. Han valdtok henne, skjemde henne, låg med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Etterpå fekk Amnon brått ein øgjeleg illvilje til henne. Illviljen han åtte mot henne no, var endå meir ofseleg enn elsken han hadde havt til henne fyrr. «Ris upp og gakk med deg!» sagde Amnon til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Ho sagde til honom: «Ikkje auka skuldi med å gjera so stor ei ugjerning som å jaga meg! det vil vera endå verre enn det andre du hev gjort med meg.» Men han vilde ikkje høyra på henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'men ropa på drengen, som tente hjå honom: «Få henne der burt frå meg, ut på gata!» ropa han, «og læs døri etter henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Ho gjekk i sid ermekjole; i sovorne kappor var kongsdøtterne klædde med dei var unge gjentor. Tenaren førde henne ut på gata og læste døri etter henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Då tok Tamar oska og hadde på hovudet, reiv sund ermekjolen ho gjekk i, lagde handi på hovudet og gjekk og øya seg i eino.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Absalom, bror hennar, spurde henne: «Hev Amnon, bror din, vore hjå deg? Teg deg no, syster! Han er bror din. Bry deg ikkje um dette!» Tamar heldt seg då heime hjå Absalom, bror sin, einsleg og yvergjevi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Då kong David spurde alt dette, loga harmen upp i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absalom sagde ingen ting med Amnon anten godt eller vondt. Men Absalom hata Amnon, for di han hadde skjemt Tamar, syster hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Tvo år etter hadde Absalom saueklypping i Ba’al-Hasor attmed Efraim; og Absalom bad alle kongssønerne til gjester.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalom gjekk då inn til kongen og sagde: «Tenaren din held saueklypping. Eg bed at kongen og tenarane hans vil vera med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Kongen svara Absalom: «Nei, guten min! Me må ikkje vera med alle; det vert for mykje bry for deg.» Endå han naudbad honom, vilde han ikkje, men bad farvel med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Då sagde Absalom: «So lat då i alle fall bror Amnon vera med!» Kongen spurde: «Kvifor nett han?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Men då Absalom naudbad honom, let han Amnon og alle kongssønerne vera med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalom baud drengjerne: «Sjå etter når Amnon vert lystig av vinen, og eg segjer: «Hogg til Amnon!» So drep honom hugheilt! eg tek ansvaret. Ver hugsterke, og vis de er dugande karar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Absaloms-drengjerne gjorde med Amnon som Absalom hadde bode. Då spratt dei upp alle kongssønerne, steig på muldyri sine og rømde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Med dei endå var på vegen, fekk David høyra ei tiend um at Absalom hadde drepe alle kongssønerne, so ikkje ein einaste var att av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Då reiste kongen seg og reiv sund klædi sine og lagde seg på golvet. Og alle tenarane som stod der, reiv og sund klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Men Jonadab, son åt Simea, bror åt David, tok til ords og sagde: «Herre, du må ikkje tru at dei hev drepe alle dei unge kongssønerne. Det er berre Amnon som er dåen. Eg hev lese ulukka på Absaloms munn alt frå den dagen då Amnon skjemde ut Tamar, syster hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Herre konge! no må du ikkje gjera deg so ilt av det, at du trur alle kongssønerne er daude. Nei, det er berre Amnon som er daud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Men Absalom flydde. Då vaktmannen såg ut, fekk han sjå mykje folk kom vegen ned fjellet attanfor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Då sagde Jonadab til kongen: «Der kjem kongssønerne! Det er som eg sagde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Nett då han hadde tala ut, kom kongssønerne, og dei sette i og gret. Ogso kongen og alle tenarane storgret og stridgret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Men Absalom flydde og for til Talmai Ammihudsson, kongen i Gesur. Og han syrgde yver son sin heile tidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom flydde og for til Gesur, og heldt seg der i tri år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Men kong David let vera å draga ut mot Absalom; han hadde lote trøysta seg i sorgi yver at Amnon var dåen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Joab Serujason skyna at kongen endå var glad i Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Han sende då bod til Tekoa og henta ei sløg kona derifrå og baud henne: «Te deg som du hev sorg! Klæd deg i syrgjebunad! Smyr deg ikkje med olje! Te deg som ei kvinna som hev syrgt på ein avliden i lang tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Gakk so inn til kongen og tala til honom desse ordi!» - Joab lagde henne ordi i munnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Tekoa-kona tala til kongen, fall å gruve ned på jordi og bøygde seg, og ropa: «Hjelp, konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kongen spurde: «Kva er i vegen med deg?» Ho svara: «Å, eg er ei syrgjande enkja; mannen min er dåen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Tenestkvinna di hadde tvo søner. Dei kom i trætta med kvarandre ute på marki; og det var ingen til å skilja deim; den eine gav då bror sin banehogg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'No ris heile ætti upp mot tenestkvinna di og krev: «Hit med brormordaren! Me vil drepa honom til hemn for han myrde bror sin! So fær me rudt ervingen or vegen med same!» Og soleis vil dei sløkkja den siste voni eg hev att i livet, og meinka mannen min både ettermæle og avkjøme her på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Kongen sagde til kona: «Far heim! eg skal greida saki for deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Men Tekoa-kona svara kongen: «Herre konge! På meg og på farsætti mi kvile all skuldi! Men kongen og kongsstolen lyt vera utan skuld!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Då sagde kongen: «Segjer nokon eitkvart med deg, so kom hit med honom! han skal ikkje gjera deg mein ein gong til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Ho sagde: «Kom i hug Herren, din Gud, konge, so blodhemnaren ikkje skal auka ulukka og rydja son min or vegen.» Då sagde han: «So sant Herren liver, ikkje eit hår skal verta skadt på hovudet åt son din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Då tok kona til ords: «Lat tenestkvinna di endå få lov å segja eit ord med deg, herre konge!» Han svara: «Seg det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, '«Kvifor hev du tenkt so vondt mot Guds folk?» sagde kona; «når kongen talar so, då er det som um han hev dømt seg sjølv, med di kongen let ikkje sin burtstøytte son koma heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Vist lyt me alle døy. Men likjest på vatnet som vert utrent på marki, og som ein ikkje kann samla upp att. Men Gud let ingen døy, utan han tenkjer ut alt som tenkjast kann til å berga den burtstøytte so han ikkje vert burtstøytt frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Eg er komi til å tala desse ordi med deg no, herre konge, av di skyldfolket mitt hev skræmt meg. Tenestkvinna di kom i hug: «Eg vil tala med kongen; kann henda kongen vil gjera det eg bed um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Ja, kongen vil lyda på tenestkvinna si, og berga meg frå den som vil rydja or vegen både meg og son min or Guds eige folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Og tenestkvinna di tenkte: «Eit ord frå deg, herre konge, vil gjera meg sutlaus! For du, herre konge, er som Guds engel, med di du høyrer alt både godt og vondt.» So vere Herren, din Gud, med deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Då tok kongen åt ords og sagde til kona: «Svara meg ope og ærleg på det som eg no spør deg!» Ho svara: «Seg det, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kongen spurde: «Hev ikkje Joab si finger med i dette spelet?» Kona svara: «So sant som du liver, herre konge, når du talar, herre konge, kann ingen koma undan anten til høgre eller vinstre. Jau, det er Joab, tenaren din, som hev lagt dette på meg, og lagt tenestkvinna di i munnen alt det eg hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Joab, tenaren din, hev gjort det, av di han vilde få saki til å sjå onnorleis ut. Men du, herre, er vis som Guds engel, so du veit alt som hender på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Kongen sagde då til Joab: «Godt og vel! eg skal so gjera. Far av og før heim den unge mannen, Absalom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Då fall Joab å gruve, bøygde seg til jordi og velsigna kongen. Joab sagde: «I dag skynar tenaren din at du, herre konge, eig godvilje for meg, sidan du, konge, gjer det eg bed um.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Joab reis upp og drog til Gesur, og førde Absalom til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Kongen gav det bodet: «Han lyt ganga heim til seg sjølv. For mine augo skal han ikkje koma.» So gjekk Absalom heim til seg sjølv, og kom ikkje kongen for augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'I heile Israel beid ikkje maken til Absalom so væn, og ingen so namngjeten; det beid ikkje lyte på honom frå kvervel til iljar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Når han klypte håret på hovudet sitt - det gjorde han på slutten av kvart år; for det var so tungt at han laut klyppa det - då vog dei håret hans, og fann at det vog tvo hundrad lodd etter kongens vegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Absalom hadde tri søner og ei dotter; ho heitte Tamar og var fager å sjå til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Då Absalom hadde halde seg tvo år i Jerusalem og ikkje kome kongen for augo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'sende han bod etter Joab, var meint å senda honom til kongen. Men han vilde ikkje koma. Andre gongen sende han bod; han vilde ikkje koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Då sagde han med tenarane sine: «De veit at Joab hev ein åkerteig ved sida av min; og der hev han bygg. Far dit og kveik eld på!» So kveikte drengjerne åt Absalom eld på åkerteigen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Joab for upp og gjekk heim til Absalom: «Kvi hev drengjerne dine kveikt eld på åkerteigen min?» spurde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, '«Eg sende då bod etter deg,» svara Absalom, «og bad deg koma hit, so eg kunde senda deg til kongen med desse ordi: «Kvifor fekk eg koma heim frå Gesur? det vøre betre for meg um eg hadde halde meg der framleides.» No vil eg fram for kongen. Er eg saka i nokor illgjerning, so fær han drepa meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Då gjekk Joab til kongen og melde honom det. Kongen kalla då til seg Absalom; og han kom inn til kongen, kasta seg å gruve for honom og bøygde seg til jordi framfor kongen. Og kongen kysste Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Ei stund etterpå fekk Absalom seg vogn og hestar og femti mann som sprang fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Tidleg um morgonen pla Absalom standa attmed vegen til porten. So tidt nokon var på veg til kongen med eikor saki han vilde hava dom i, ropa Absalom honom til seg og spurde: «Kva by er du frå?» Når han svara: «Frå den og den ætti i Israel er tenaren din,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'so svara Absalom: «Du veit saka di er både god og rett, men hjå kongen finn du inkje ope øyra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Og han lagde til: «Gjev dei gjera meg til domar i landet! Då skulde kvar ein koma til meg med saker og søksmål. Og eg skulde gjeva honom rett.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Gjekk einkvan fram og vilde bøygja seg for honom, retta han ut handi og tok um honom og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Soleis gjorde Absalom med alle i Israel som kom med saker kongen skulde døma i. Og Absalom dåra hugen hjå Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Fire år var lidne, då Absalom ein dag bad kongen: «Lat meg draga til Hebron og halda ein lovnad eg hev gjort åt Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Då tenaren din budde i Gesur i Syria, gjorde eg den lovnaden: «Let Herren meg verkeleg koma heim att til Jerusalem, so vil eg halda ei gudstenesta åt Herren.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Kongen svara: «Far i fred!» Han reis upp og drog til Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Absalom sende so njosnarar til alle ætterne i Israels med dei ordi: «Når de høyrer luren ljoda, då kann det fortelja at Absalom hev vorte konge i Hebron.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Med Absalom fylgde tvo hundrad mann frå Jerusalem, som var innbodne og fylgde med i god tru; dei visste ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Medan Absalom ofra slagtofferi, sende han bod og henta dessutan Ahitofel, rådsmannen åt David, frå Gilo, heimbyen hans. Samansverjingi auka i styrke. Folket heldt på og gjekk yver til Absalom i store mengder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Ein bodberar kom til David og melde: «Israels-mennerne hev vendt hugen sin til Absalom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Då baud David alle tenarane sine, dei som var hjå honom i Jerusalem: «Av stad! Det finst ingi onnor råd for oss til å berga oss undan Absalom. Skunda dykk av stad, so han ikkje kjem brått på oss og fører ulukka yver oss og drep byfolket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Kongstenarane svara: «Tenarene dine er budde til alt det du vil, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Då drog kongen ut; og alle husfolki hans fylgde. Ti av fylgjekonorne let kongen att til å vakta huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Då kongen drog av stad, fylgde alt byfolket. Dei stogga ved Bet-Hammerhak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Alle tenarane gjekk framum honom, like eins heile livvakti. Og alle Gats-folki, seks hundrad mann som hadde fylgt honom frå Gat, gjekk framum kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Kongen sagde med Gats-mannen Ittai: «Kvifor gjeng du og med oss? Far attende, og ver hjå honom som no er konge! Du er då berre utlending, ja ein heimlaus utvandrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Du kom i går! Skulde eg i dag lata deg reika ikring med oss på ferdi vår, no eg ikkje sjølv veit leidi? Far attende, og tak brørne dine med deg! Gjev miskunn og truskap må timast dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Men Ittai svara kongen: «So sant Herren liver, og so sant du liver, herre konge: den staden du er, herre konge, der vil tenaren din ogso vera, anten det ber til liv eller daude!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David sagde då til Ittai: «Ja ja, ver so med!» Gats-mannen Ittai drog då med, fylgd av alle sine menner og heile barneflokken som han hadde med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Heile landet storgret då alt folket drog fram. Og då kongen gjekk yver Kidronsbekken, fylgde alt folket etter og tok vegen åt øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Sjå Sadok og alle levitarne var og med honom. Dei bar Guds sambandskista med seg. Dei sette Guds kista ned - då kom Abjatar og upp - til dess alt folket hadde rokke fram frå byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Kongen sagde då til Sadok: «Før Guds kista attende til byen! Syner Herren meg miskunn, so let han meg koma heim att, so eg fær sjå att honom og bustaden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Men segjer han: «Eg hev ikkje godvilje for deg,» då er eg budd: han gjere med meg som han tykkjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Og kongen sagde med presten Sadok: «Du sjåar. Far heim att i fred! Og båe sønerne dykkar, Ahima’as, son din, og Jonatan Abjatarsson, må fylgja med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Sjå, eg vil drygja attmed ferjestaderne i øydemarki til dess eg fær bod frå dykk med meldingar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'So førde Sadok og Abjatar Guds kista attende til Jerusalem og stana der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David gjekk gråtande upp Oljefjellet med tilsveipt hovud og berrføtt. Og alt folket som fylgde, hadde og sveipt til hovudi sine og gjekk gråtande dit upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Då David fekk høyra at Ahitofel var millom deim som hadde samansvore seg med Absalom, bad David: «Herre, gjer Ahitofels råd til skammar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Då David var komen øvst på fjellet, der dei plar tilbeda Gud, då kom Husai av arkitætti mot honom med sundrivne klæde og mold på hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'David sagde til honom: «Gjeng du med meg, vert du til bry for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Men gjeng du attende til byen og segjer med Absalom: «Din tenar vil eg vera, konge! far din’s tenar var eg fyrr; no er eg din tenar!» - so kann du hjelpa meg å skjepla Ahitofels råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Du veit du hev prestarne Sadok og Abjatar ogso der. Alt du frettar frå kongshuset, må du melda åt prestarne Sadok og Abjatar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Dei hev ogso båe sønerne sine heime: Sadok hev Ahima’as, og Abjatar hev Jonatan. Med deim kann du senda meg bod um alt du fretter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'So gjekk då Husai, venen åt David, inn i byen, samstundes som Absalom drog inn i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Då David var komen eit stykke på hi sida av fjellet, møtte han Siba, drengen åt Mefiboset, med eit par asen kløvja med tvo hundrad brød, hundrad rosinkakor, hundrad sumarfrukter og ei vinhit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Kongen spurde Siba: «Kva er det du hev der?» Siba svara: «Asni skal vera til å rida på for kongens husfolk. Brødet og frukterne skal vera mat åt tenarane; og vinen til svaledrykk for dei trøytte mennerne dine i øydemarki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kongen spurde: «Kvar er son åt husbonden din?» Siba svara: «Han er att i Jerusalem. Han tenkte at no vil Israels hus gjeva honom att kongedømet åt far hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Då sagde kongen til Siba: «Alt det Mefiboset eig, skal vera ditt!» Siba svara: «Eg fell ned for deg. Lat meg eiga godviljen din, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Då kong David so kom til Bahurim, kom ut derifrå ein mann av Sauls-ætti, Sime’i Gerason heitte han. Han gjekk og banna');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'og kasta stein etter David og alle kongstenarane, endå heile heren og det djervaste stridsfolket gjekk på båe sidor av kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Soleis banna Sime’i: «Burt, burt med deg, din blodhund! din niding!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Herren let no alt blodet frå Sauls hus koma att yver deg, du som vart konge i hans stad. Herren gjev no kongedømet til Absalom, son din. Sjå no hev du fenge ulukka etter fortenesta! ein blodhund er du!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Abisai Serujason spurde kongen: «Kvifor skal den daude hunden der hava lov å banna deg, herre konge? Lat meg fara dit og hogga hovudet av honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Men kongen svara: «Kva hev eg med dykk å gjera, Seruja-søner? Bannar han, og er det Herren som hev bode honom å banna David, kven vågar då spyrja: «Kvi gjer du so?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Og David sagde med Abisai og med alle folki sine: «De veit son min vil taka livet av meg - han som er runnen av mi rot. Kor mykje større grunn hev då denne benjaminiten! Lat honom berre banna, når Herren hev bode honom å banna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Kann henda Herren ser til mi naud og gjev meg lukka til vederlag for den forbanningi som kjem yver meg i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'David og mennerne hans gjekk so burtetter vegen, medan Sime’i fylgde honom jamsides uppi lidi, og banna i eino og kasta stein og molda honom ut med mold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Kongen kom med alle folki sine til Ajefim og kvilde seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom var komen til Jerusalem med alle sine folk av Israels-mennerne. Han hadde ogso Ahitofel med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Då arkiten Husai, venen åt David, kom til Absalom, ropa han imot honom: «Live kongen, live kongen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom spurde Husai: «Er det soleis du syner godvilje mot venen din? Kvifor hev du ikkje fylgt venen din?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Husai svara Absalom: «Nei, den som Herren og folket og alle Israels-mennerne hev valt, til honom vil eg høyra, hjå honom vil eg vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Dessutan: kven er det eg tenar? Er det ikkje son hans? Like eins som eg hev tent hjå far din, so vil eg no vera hjå deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Absalom bad Ahitofel: «Kom med ei råd, kva skal me gjera no.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitofel svara: «Ligg med fylgjekonorne åt far din, som han let att til å vakta kongsgarden! Då fær heile Israel høyra gjete at du hev gjort far din hatig på deg. Og so fær dei nytt mod alle som hev fylgt deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'So slo dei upp tjeld åt Absalom uppå taket. Og Absalom låg med fylgjekonorne åt far sin, so heile Israel såg på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'I dei dagarne galdt ei råd som Ahitofel gav, like mykje som svar frå Gud. So mykje galdt alle Ahitofels råder både hjå David og hjå Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Ahitofel sagde med Absalom: «Lat meg velja ut tolv tusund mann, so vil eg leggja i veg og forfylgja David alt i natt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'So kjem eg brått yver honom og skræmer honom medan han er trøytt og veik. Då vil alle folki hans taka til rømings. So drep eg kongen medan han er åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'So skal eg føra alt folket attende til deg; for um det gjeng so med den mannen du søkjer, er det som alle kjem attende; heile folket vil halda fred.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Absalom og alle dei øvste i Israel lika godt den rådi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Like vel sagde Absalom: «Ropa ogso arkiten Husai inn! so fær me ogso høyra kva han råder til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Då Husai kom inn til Absalom, sagde Absalom til honom: «So og so hev Ahitofel sagt. Skal me fylgja hans råd? I anna fall, kva meiner du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Husai svara Absalom: «Den rådi Ahitofel hev gjeve denne gongen, er ikkje god.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Du kjenner far din og folki hans,» sagde Husai, «du veit dei er fullgode stridsfolk. Og hug-rame er dei no som ei binna dei hev teke ungarne frå ute i marki. Far din er krigsmann, veit du: han let ikkje folki leggja seg til kvile um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'No hev han visseleg løynt seg i einkvan helleren eller einkvar annan staden. Skulde då sume av våre folk falla i fyrstningi, so vil det koma ut at det hev vore stort mannefall millom folki som fylgde Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Då vil jamvel den djervaste heiltupp missa modet, um han så hadde mod som ei løva. For heile Israel veit at far din er ei kjempa, og at fylgjesveinarne hans er djerve karar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Difor er det mi råd, at du stemner saman til deg heile Israel frå Dan til Be’erseba, so tallrikt som sanden attmed havet. Og sjølv lyt du draga med i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Når me so finn honom einkvan staden, kvar helst det no er, so fell me yver honom som doggi fell på marki. Då skal det ikkje verta ein einaste att av honom og alle fylgjesveinarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Ja, um han so søkjer inn i ei borg, so vil heile Israel leggja reip ikring henne og draga henne ned i dalen, til dess det bid ikkje minste steinen att i henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Då sagde Absalom og alle Israels-mennerne: «Rådi åt arkiten Husai er betre enn Ahitofels råd.» For Herren laga det so at den gode rådi hans Ahitofel vart um inkjes. For Herren vilde føra ulukke yver Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Husai melde til prestarne Sadok og Abjatar: «Den og den rådi gav Ahitofel åt Absalom og dei øvste i Israel. Men den og den rådi gav eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Skunda dykk og send bod til David med det ordet: «Natta ikkje yver attmed ferjestaderne i øydemarki i natt, men gakk yver Jordan! Elles kann kongen og alle folki hans verta tynte.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonatan og Ahima’as heldt seg attmed En-Rogel. Dit kom jamt ei tenestgjenta med melding til deim; og so bar dei meldingi til David. Dei våga ikkje visa seg i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Men ein unggut gådde deim og melde det til Absalom. Då skunda dei seg burt båe, og kom heim til ein mann i Bahurim. Han hadde ein brunn på garden sin. I den steig dei ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'So tok kona hans og breidde eit tæpe yver brunn-opet, og strådde gryn uppå, so ingen gådde noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Då tenarane åt Absalom kom inn i huset til kona og spurde etter Ahima’as og Jonatan, svara ho: «Dei gjekk yver den vesle bekken der.» Dei leita, men fann inkje, og snudde so heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Då dei hadde fare sin veg, steig dei hine upp or brunnen, og gjekk med meldingi til kong David. Dei sagde til David: «Skunda deg, far yver vatnet! den og den rådi hev Ahitofel gjeve um dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'David braut upp med alle fylgjesveinarne sine; og dei gjekk yver Jordan. Um morgonen då dagen rann, vanta det ikkje ein einaste. Alle var komne yver Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Då Ahitofel såg at dei ikkje fylgde rådi hans, sala han asnet sitt, steig uppå og reid heim til sin by. Og då han hadde skila for seg, hengde han seg. Det var hans bane. Han vart gravlagd i gravi åt far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David var komen til Mahanajim då Absalom med alle Israels-mennerne gjekk yver Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Absalom hadde sett Amasa til øvste herhovding i staden for Joab. Amasa var son åt ein jizre’elit ved namn Jitra, som hadde halde seg med Abigal, dotter til Nahas, syster til Seruja, mor åt Joab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Israel og Absalom lægra seg i Gileadlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Då David kom til Mahanajim, hadde Sobi Nahasson frå Rabba i Ammonitarlandet og Makir Ammielsson frå Lo-Debar, og Barzillai, ein Gileads-mann frå Rogelim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'ført dit sengjer, skåler og kruskjerald. Og kveite, bygg, mjøl, steikte aks, baunor, linsor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'honning, tjukkmjølk, sauer og mjølk-ost hadde dei med seg til mat åt David og folket hans. For dei tenkte: «Folki hev vorte svoltne, trøytte og tyrste i øydemarki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'David mynstra folket sitt og sette førarar og underførar yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'So sende David ut folket; den eine tridjeparten under Joab, den andre tridjeparten under Abisai Serujason, bror åt Joab, og den tridje under Ittai frå Gat. Og kongen sagde til folket: «Eg er fast meint på å draga ut sjølv med dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Men dei svara: «Du fær ikkje draga ut. Um me lyt røma, bryr ingen seg um oss. Um helvti av oss vert drepne, bryr ingen seg um oss. Men du er no jamgod med titusund av oss. Difor er det likare at du er budd på å koma oss til hjelp frå byen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Kongen sagde: «Det de meiner er best, det vil eg gjera.» So tok kongen post attmed porten. Og heile heren drog ut i hundrad og i tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Kongen baud Joab, Abisai og Ittai: «Far no varsamt med den unge mannen, med Absalom!» Heile heren høyrde kva kongen baud herhovdingarne um Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'So drog heren ut i opi marki mot Israel. Og det kom til slag i Efraimsskogen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Der vart Israels-heren slegen av Davids herfolk. Og vart stort mannefall millom deim den dagen: tjuge tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Slaget spreidde seg utyver heile den kanten av landet. Og skogen øydde fleire folk den dagen enn sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Det bar so til at Absalom råka på nokre av folki åt David. Han reid på eit muldyret. Og då muldyret kom inn under dei tette greinerne av ei stor eik, vart hovudet hans klemt fast millom greinerne. Og han vart hangande millom himmel og jord. For muldyret han reid på, sprang sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Ein mann som såg det, melde det til Joab: «Eg fekk sjå Absalom hangande i ei eik der burte.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Joab spurde bodberaren: «Når du såg det, kvifor slo du honom ikkje til marki med same? So skulde eg gjerne ha gjeve deg ti sylvdalar og eit belte for det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mannen svara: «Um eg so skulde fenge ti tusund sylvdalar upp i neven, so ikkje eg leggja hand på kongssonen. Me høyrde då med eigne øyro kor kongen baud deg og Abisai og Ittai: «Tak vare på den unge mannen, på Absalom, for meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Og hadde eg gjort svik mot hans liv - for ingen ting vert løynd for kongen - so vilde du halde deg utanfor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, '«Eg vil ikkje hefta tidi lenger meg deg,» sagde Joab, treiv tri spjot i handi, og deim rende han i bringa på Absalom, som endå hekk livande millom greinerne på eiki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'So kom ti sveinar til, Joabs våpnsveinar, og gav Absalom banehogg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Joab bles i luren. Og herfolket heldt upp med å forfylgja Israel, då Joab baud deim stogga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Dei tok og kasta Absalom i ei stor grop i skogen, og hauga i hop ei veldug steinrøys yver honom. Heile Israel tok til rømings kvar til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom sjølv hadde i livande live teke og reist upp til minne for seg den merkesteinen som stend i Kongsdalen; med di han sagde: «Eg hev ingen son til å halda uppe namnet mitt!» Han kalla merkesteinen etter sitt namn; og han heiter «Absaloms minne» endå den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahima’as Sadoksson sagde: «Lat meg skunda meg og melda kongen fagnadtiendi, at Herren hev hjelpt honom til retten sin mot uvenerne sine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, '«Nei,» sagde Joab, «det vert inkje fagnadbod det du hev å bera i dag. Ein annan dag kann du koma med fagnadtiend. Men i dag vert det ingen fagnadtiend; for det er son åt kongen som er avliden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'So baud Joab ein ætiop: «Gakk og meld kongen det du hev set!» \'tiopen fall ned for Joab og sprang av stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Ahima’as Sadoksson bad Joab andre gongen: «Kome kva kome vil: lat meg springa eg og, etter ætiopen!» Joab svara: «Kvifor vil du det, guten min? Dette er då ikkje nokor fagnadtiend, som du kann venta løn for!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Han sagde: «Koma kva kome vil: eg spring!» «So spring då!» sagde Joab. Og Ahima’as sprang, og tok vegen yver Jordan-kverven og kom fyre ætiopen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David sat inni dubbelporten. Og ein vaktmann steig upp på porttaket innmed muren. Då han skoda ut, fekk han sjå ein koma springande åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Vaktmannen ropa og melde det åt kongen. Då sagde kongen. «Er han åleine, so hev han eit fagnadbod å bera fram. Men medan han kom næmare,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'fekk vaktmannen sjå ein annan kom springande. Då ropa vaktmannen ned til portvakti: «No ser eg ein til kjem springande åleine.» Kongen sagde: «Han kjem og med fagnadbod.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Vaktmannen sagde: Etter måten å springa på, tykkjer eg den fyrste må vera Ahima’as Sadoksson.» Kongen sagde: «Han er ein god mann! han kjem visseleg med fagnadtidend.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahima’as ropa til kongen: «Heil og sæl!» So fall han å gruve til jordi framfor kongen og sagde: «Lova vere Herren, din Gud! Han hev gjeve deg dei mennerne som lyfte handi mot deg, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Kongen spurde: «Stend det vel til med den unge mannen, med Absalom?» Ahima’as svara: «Eg såg ei stor mannemuge då Joab sende den andre kongstenaren og meg. Men eg veit ikkje kva det galdt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kongen sagde: «Gakk til sides, og statt der!» Han so gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Nett då kom ætiopen. Han sagde: «Tak imot fagnadbodet, herre konge, at i dag hev Herren gjeve deg rett mot alle deim som reiste seg mot deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kongen spurde ætiopen: «Stend det vel til med den unge mannen, med Absalom?» \'tiopen svara: «Gjev det må ganga soleis med uvenerne dine, herre konge, og med alle som reiser seg mot deg og vil gjera deg mein, som det gjekk med den unge mannen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Då vart kongen reint ille ved, gjekk upp i taksalen yver porten, og gret. Og alt medan han gjekk, jamra han: «Absalom, son min, Absalom, son min, son min! Gjev eg hadde døytt i staden din! Absalom, son min, son min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Joab spurde at kongen gret og syrgde yver Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Sigeren vart soleis umskift til ei stor folkesorg den dagen. For herfolket høyrde gjete den dagen at kongen bar sorg for son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Folket stal seg inn i byen den dagen, soleis som folk plar gjera når dei skjemmest av di dei hev rømt frå slaget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Kongen hadde sveipt eit plagg kring andlitet sitt, og jamra med høgt mål: «Absalom, son min! Absalom, son min, son min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Då gjekk Joab inn i huset til kongen og sagde: «Du hev i dag fenge alle tenarane dine til å raudna av skam, endå dei i dag hev berga ditt liv og berga livet åt sønerne og døtterne dine, åt konorne og fylgjekonorne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Du elskar då deim som hatar deg, og hatar deim som elskar deg. Du hev kunngjort i dag at hovdingarne og tenarane dine er inkjevetta for deg. Eg skynar det no, at det vilde du ha lika godt: um Absalom hadde vore i live, og alle me andre no vore drepne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Ris upp! gakk ut, og tala venleg med tenarane dine! Det sver eg ved Herren: Gjer du ikkje det, so vil ikkje ein einaste mann natta yver hjå deg i natt. Og det vil verta større ulukka for deg enn alle andre ulukkor som hev kome yver frå din ungdom til no.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Då reis kongen upp og sette seg i porten. Det vart kunngjort for alt herfolket: «Sjå kongen sit no i porten.» Då kom dei alle fram for kongen. Israel hadde rømt kvar til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Og alt folket i alle Israels ætter tok til å tretta med kvarandre og segja: «Kongen var det som fria oss frå fiendarne våre og berga oss frå filistarane. No hev han lote røma landet for Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absalom, som me salva til konge yver oss, han er drepen i krigen. Kvifor drygjer de då med å få kongen attende?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Alt dette vart bore fram for kongen der han heldt seg. David sende bod til prestarne Sadok og Abjatar og bad deim bera fram dette bodet: «Tala so til dei øvste i Juda: «Kvifor vil det vera dei siste til å henta kongen heim att til kongsgarden?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'De er brørne mine! me er då same folket! kvifor vil de då vera dei siste til å henta kongen attende?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Til Amasa bad han deim segja: «Er ikkje me same folket? Gud late meg bøta no og sidan, um ikkje du skal verta herhovdingen min for alle tider i staden hans Joab.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Han vann soleis Juda-mennerne alle som ein, so dei sende dette bodet til kongen: «Kom heim att, du og alle tenarane dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Då snudde kongen på heimvegen og kom til Jordan. Juda-folket møtte kongen i Gilgal og førde honom yver Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Og benjaminiten Sime’i Gerason frå Bahurim skunda seg og drog ned med Juda-folket og møtte kong David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Med honom fylgde tusund mann frå Benjamin. Like eins kom Siba, sveinen åt Sauls-ætti, med femtan søner og tjuge tenarar. Dei kom fram til Jordan fyre kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Dei ferja yver og førde kongslyden yver, og heldt på å ferja so som kongen ynskte. Sime’i Gerason fall å gruve for kongen då han skulde fara yver Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, '«Herre!» sagde han, «du må ikkje rekna på illgjerningi mi, og ikkje koma i hug kor ille tenaren din gjorde den dagen du, herre konge, drog ut frå Jerusalem! Bry deg ikkje um det, konge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Tenaren din skyner eg forsynda meg mot deg den gongen. Difor er eg i dag den fyrste av heile Josefs hus som er komen til å møta deg, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Abisai Serujason tok til ords og sagde: «Skulde ikkje Sime’i lata livet for dette, at han banna den som Herren hev salva?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Men David svara: «Kva hev eg med dykk, Seruja-søner, med di de er motmennerne mine i dag? Ingen mann i Israel skal lata livet i dag. Eg veit: i dag hev eg vorte konge yver Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'So sagde kongen til Sime’i: «Du skal ikkje døy!» Og kongen gjorde eid på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mefiboset, soneson åt Saul, hadde og fare ned og møtt kongen. Han hadde ikkje vølt føterne sine, ikkje greidt skjegget sitt, og heller ikkje vaska klædi sine frå den dagen kongen drog burt, heilt til den dagen han kom att med heilo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Då no kom til Jerusalem og møtte kongen, spurde kongen honom: «Kvifor fylgde du ikkje med meg, Mefiboset?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Han svara: «Herre konge, tenaren min sveik meg. Eg sagde: «Eg vil sala asnet mitt, stiga uppå og rida med kongen; du veit eg er lam.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Men han hev i staden loge på meg for deg, herre konge. Like vel: du, herre konge, er som Guds engel; gjer det du tykkjer best!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Heile farshuset mitt fortente ikkje anna enn daudedom av deg, herre konge! endå sette du meg millom deim som fekk eta ved ditt bord. Kva hev eg då rett å krevja meir? Og kva kann eg meir beda kongen um?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Kongen svara: «Du tarv ikkje tala meir um det! Eg segjer: Du og Siba skal hava kvar sin lut av jordeigedomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Mefiboset svara kongen: «Han må gjerne eiga alt i hop, sidan du, herre konge, no hev kome att til kongsgarden med heilo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Barzillai frå Gilead hadde og fare ned frå Rogelim, og drog so med kongen til Jordan og fylgde honom yver Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barzillai var då ovleg gamall, åtteti år. Han hadde sytt for kongen medan han heldt til i Mahanajim; for han var ein rik mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Kongen baud no Barzillai: «Du skal fylgja meg; so vil eg syta for deg hjå meg i Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Men Barzillai svara: «Kor lang tid hev eg att å liva, so eg skulde fylgja kongen upp til Jerusalem?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Eg er no åtteti år, eg. Kann eg då skilja millom godt og låkt? Eller kann eg smaka kva eg et eller drikk? Eller kann eg njota å lyda på songarar og songmøyar? Kvifor skulde eg då meir vera til bry for deg, herre konge?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Berre eit stykke på veg vilde tenaren din fara med kongen yver Jordan. Kvifor skulde kongen gjeva meg vederlag soleis?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Lat tenaren din fara heim att og døy i heimbyen min, der som far og mor ligg gravlagde! Men her er Kimham, tenaren din! Lat honom fylgja med deg, herre konge, og gjer for honom det du tykkjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Kongen svara: «So skal Kimham fylgja med meg. Og eg vil gjera mot honom det du ynskjer. Og alt du bed meg um, skal eg gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'So gjekk alt folket yver Jordan; og kongen sjølv gjekk yver. Kongen kysste Barzillai og tok farvel med honom. Og so vende han heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Kongen drog til Gilgal. Kimham fylgde med, og alle Juda-mennerne. Saman med helvti av Israels-mennerne førde dei kongen dit yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Då kom alle Israels-mennerne til kongen og sagde: «Kvifor hev brørne våre, Juda-mennerne, stole seg til å få tak i deg og føra kongen og lyden hans og alle Davids-tenarane yver Jordan?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Juda-mennerne svara Israels-mennerne: «Kongen stend då næmare oss. Kvifor er de harme for det? Hev me livt på kongen, eller fenge nokor gåva?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Israels-mennerne svara Juda-mennerne: «Ti gonger større lut enn de hev me i honom som er konge, soleis ogso i David. Kvifor hev de vanvyrdt oss? Var det ikkje me som fyrst tala um å henta kongen vår heim?» Det svaret Juda-mennerne gav, var endå argare enn det Israels-mennerne hadde gjeve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'No var det der ei uvyrda ved namn Seba Bikrison, ein benjaminit. Han bles i luren og ropa: «Me hev ingen lut i David og ingen arvlut i Isaisonen. Heim att kvar til seg, Israels menner!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Alle Israels-mennerne gjekk då frå David og fylgde Seba Bikrison. Men Juda-mennerne heldt fast ved kongen sin, og fylgde honom frå Jordan heilt til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'So kom då David til kongsgarden sin i Jerusalem. Kongen tok då dei ti fylgjekonorne som han hadde late etter seg til å vakta kongsgarden og sette deim under vakt i eit hus for seg sjølve. Han gav deim upphelde; men han heldt seg ikkje med deim. Der budde dei no innestengde til sin døyande dag og livde som enkjor alle sine dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Kongen baud Amasa: «Bjod ut Juda-herfolket åt meg og møt fram med deim innan tri dagar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Amasa gjekk og baud ut Juda. Men han drygde utyver den fresten han hadde fenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Då sagde David til Abisai: «No kjem Seba Bikrison til å gjera oss meir ilt enn Absalom. Tak du tenarane åt herren din! Set etter honom fyrr han fær hertaka nokor borg og gjera oss for mykje sut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Joabs-mennerne drog då av stad etter honom med livvakti og alt stridsfolket. Dei drog ut frå Jerusalem og sette etter Seba Bikrison.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Då dei hadde nått til den store steinen ved Gibeon, møtte dei Amasa med sine hermenner. Joab var klædd i våpnkjole som han var van, med belte um livet og sverd i slira. Då han gjekk fram, datt sverdet ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Joab spurde Amasa: «Kor stend det til med deg, bror?» og tok med høgre handi Amasa i skjegget og vilde kyssa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa vara seg ikkje for sverdet som Joab hadde i hi handi. Dermed gav han honom ein støyt i livet, so innvolarne rann ut på marki. Og han døydde på flekken, berre av det. Joab og Abisai, bror hans, heldt fram og forfylgde Seba Bikrison.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Ein av tenarane åt Joab stod der attmed og ropa: «Alle som likar Joab og held med David, fylgje etter Joab!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Men då mannen såg at alle stogga attmed Amasa, der som han låg midt i vegen kring-velt i sitt eige blod, skuva han liket undan og kasta ei kappa yver; for han såg kor alle stogga når dei kom dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Og då liket var teke or vegen, drog alle framum og fylgde Joab og elte Seba Bikrison.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Han hadde i millomtidi fare igjenom alle ætterne i Israel til Abel og Bet-Ma’aka, og kasta seg inn i byen. Og folki hans stemnde i hop og fylgde honom dit inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Dei hine kom og kringsette honom der i Abel Bet-Ma’aka og kasta upp ein voll mot byen innimot ytremuren. Alt folket åt Joab stræva med å få muren til å falla, og riva honom ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Då ropa ei klok kona frå byen: «Høyr her! Seg Joab han kjem hit, so eg fær tala med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Då han kom fram til kona, spurde ho: «Er du Joab?» Han svara ja. Ho sagde: «Høyr det tenestkvinna di segjer!» Han svara: «Ja vel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Då sagde ho: «Fyrr i tidi pla dei segja: «I Abel skal ein spyrja etter råd;» so kunde ein gjera det ein etla seg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Eg er den fredsamaste og trugnaste i heile Israel. Du freistar øyda ein by som er ei mor i Israel! Kvifor vil du øydeleggja Herrens eige folk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab svara: «Aldri i verdi vil eg øydeleggja og tyna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Det hev seg ikkje so. Men ein mann frå Efraims fjellbygd - Seba Bikrison heiter han - hev reist seg mot kong David. Gjev honom yver til oss, so dreg eg burt frå byen.» Kona svara Joab: «Hovudet hans skal verta utkasta til deg yver muren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Kona kom då til byfolket med si kloke råd. Dei hogg hovudet av Seba Bikrison og kasta det ut til Joab. Då bles han i luren, at herfolket skulde draga burt. Og dei for kvar til seg. Joab snudde heim att til kongen i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab var no øvste herhovding yver heile krigsheren i Israel. Og Benaja Jojadason var hovding yver livvakti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram hadde uppsyn med pliktarbeidet for kongen. Josafat Ahiludsson var kanslar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja var riksskrivar. Sadok og Abjatar var prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Dessutan var Ira av Ja’irs-ætti prest hjå David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'I Davids tid kom tri store uår etter kvarandre. Då gjorde David spursmål til Herren um det. Herren svara: «På Saul og hans hus kvilar blodskuld, av di han drap gibeonitarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Kongen kalla då til seg Gibeon-mennerne og tala med deim. Gibeonitarne var ikkje israelitar, men var ei atterleiva av amoritarne. Endå Israels-borni hadde gjort eiden sin til deim, hadde Saul vore so ihuga for Israels-borni og for Juda, at han freista tyna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'David spurde no gibeonitarne: «Kva kann eg gjera for dykk? Korleis kann eg sona brotet, so de vil velsigna Herrens arvlut?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Gibeonitarne svara: «Ikkje sylv og gull krev me av Saul og hans hus. Og ikkje hev me lov å drepa nokon mann i Israel.» Han spurde: «Kva ynskjer det då eg skal gjera for dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Dei svara kongen: «Den mannen som vilde tyna oss og tenktest rydja oss ut, so me ikkje lenger skulde få halda oss nokon stad innanfor Israels landskil,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'av hans etterkomarar må det gjeva oss sju mann, og me vil leggja deim på stegl for Herrens augo i Sauls Gibea, han som Herren valde ut.» Kongen sagde: «De skal eg gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Kongen sparde Mefiboset Jonatansson, soneson åt Saul, for skuld den eiden ved Herren som David og Jonatan Saulsson hadde svore einannan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Derimot tok kongen dei tvo sønerne Armoni og Mefiboset som Saul hadde fenge med Rispa Ajadotter, og dei fem sønerne som Adriel Barzillaison frå Mehola hadde fenge med Mikal Saulsdotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Deim gav han yver til gibeonitarne. Og dei lagde deim på stegl på fjellet for Herrens augo. Dei fekk sin bane alle sju på ein gong. Det var dei fyrste skurddagarne, då byggskurden tok til, at dei let livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Rispa Ajadotter tok syrgjebunaden sin og breidde ut uppå fjellet frå skurdonni tok til, og til dess det strøymde regn yver deim frå himmelen. Ho let ikkje fuglarne under himmelen slå ned på deim um dagen, heller ikkje villdyri frå marki um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Då David spurde det Rispa Ajadotter, fylgjekona åt Saul, hadde gjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'drog David av stad og let henta beini etter Saul og Jonatan, son hans, hjå borgarne i Jabes i Gilead. Dei hadde i løynd teke liki frå torget i Bet-San, der som filistarane hadde hengt deim upp då dei hadde slege Saul på Gilboa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Då han fekk ført beini etter Saul og Jonatan, son hans, upp derifrå, sanka dei i hop beini etter deim som var lagde på stegl,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'og gravlagde deim saman med beini etter Saul og Jonatan, son hans, i Benjaminslandet, i Sela, i gravi åt Kis, far hans. Dei gjorde alt det kongen baud. Og etterpå det vende Gud sin nåde til landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Det vart krig millom filistarane og Israel att. David drog ned med tenarane sine; og dei slost med filistarane. Men David trøytna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Jisbo-Benob, ein ætting av Rafa - han hadde eit spjot som vog tri hundrad lodd kopar, og han hadde spent um seg eit nytt sverd - han tenktest drepa David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Men Abisai Serujason hjelpte kongen og gav filistaren banehogg. Då svor Davids menner ein eid til honom, og sagde: «Du må aldri meir draga ut med oss i strid. Elles kann Israels lampa slokna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'So hende det sidan at det stod ein bardage med filistarane ved Gob. Då slo husatiten Sibbekai Saf av Rafa-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Då det endå ein gong stod eit slag mot filistarane ved Gob, gav Elhanan, son åt Ja’are-Orgim frå Betlehem, Goliat frå Gat banehogg, han som hadde eit spjotskaft so stort som ein vevbom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Då det vart eit slag att ved Gat, var der ein storvaksen mann som hadde seks fingrar på kvar hand og seks tær på kvar fot, fire og tjuge til saman. Han var ogso utstokken frå Rafa-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Han svivyrde Israels-mennerne. Jonatan, son åt Simea, bror åt David, gav honom difor banehugg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Desse fire var ætta frå Rafa i Gat. Og dei fall for David og mennerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'David kvad dette kvædet åt Herren då Herren hadde frelst honom frå alle uvenerne sine, og frå Saul:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, '«Herren er mitt berg og mi festning og min frelsar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Gud er mitt berg som eg flyr til! Min skjold og mitt frelseshorn Mi høge borg! mi livd! Frelsaren min som friar meg ifrå vald!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Eg kallar på Herren, den høglova: Frå fiendarne mine frelsar han meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Daudens brot og brand kringsette meg. Straumar av vondskap skræmde meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Helheims reip var snørde ikring meg. Daudsens snaror fanga meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Men Herren kalla eg på i mi trengsla, eg ropa til min Gud. Han høyrde frå templet sitt røysti mi, mitt rop rakk fram til øyro hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Jordi skok seg og skalv, himmelens grunnvollar dirra, Dei skok seg, for harmen hans loga upp:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Røyk steig upp frå nasen hans, eld frå munnen hans åt ikring seg, gloande kol loga frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Han lægde himmelen og steig ned, med kolmyrker under føterne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Han for fram på kerub og flaug og sveiv på vengjerne åt vinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Myrkret gjorde han til åklæde kring seg, tjeldet hans var myrke vatn, tjukke skyer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Frå glansen fyre andlitet hans brann gloande kol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Herren tora i himmelen, den Høgste let høyra si røyst:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Pilerne sine skaut han og spreidde deim, eldingar sende han og fortulla deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Djupålarne i havet kom upp i dagen, grunnvollarne i jordi vart berrsynte ved Herrens trugsmål, ved andepusten frå hans nase.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Han rette ut handi frå høgdi og greip meg, han drog meg upp or store vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Han frelste meg frå min megtige fiende, frå uvenern’ mine, dei var meg for sterke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Dei for imot meg på motgangsdagen; men Herren vart studnaden min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Han førde meg ut i vidt rom. Han frelste meg, for han hadde hugnad i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Herren gjorde med meg etter rettferdi mi, han lønte meg etter reinleiken i henderne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'For eg tok vare på Herrens vegar, fall ikkje i vondskap frå min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Nei, alle hans rettar hadde eg for auga, bodordi hans veik eg ikkje ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'So var eg ulastande for honom og tok meg i vare for mi synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Og Herren lønte meg etter mi rettferd, etter reinleiken min for hans augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Mot den godlyndte syner du deg godlyndt, mot ulastande kjempa ulastande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Mot den reine syner du deg rein, mot den rangsnudde syner du deg rang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'For du frelsar arme folk, men augo dine er mot dei ovmodige til å tvinga deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'For du er mi lampa, Herre, og Herren gjer myrkret mitt bjart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Ved deg eg renner mot herflokkar, ved min Gud stormar eg murar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Gud, ulastande er hans veg; Herrens ord er skirt, han er ein skjold for alle deim som flyr til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'For kven er Gud forutan Herren? Kven er eit berg utan vår Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Gud, han som gyrder meg med kraft, og leider den ulastande på hans veg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'som gjev meg føter liksom hindarne, og set meg upp på høgderne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'som lærer henderne mine upp til strid, so armarne spenner koparbogen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Du gav meg frelsa di til skjold, og småminkingi di ho gjorde meg stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Du gjorde rom for stigi mine, og oklo mine vagga ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Eg forfylgde fiendarne mine og tynte deim. Eg vende ikkje um fyrr eg fekk gjort ende på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Eg gjorde ende på deim og slo deim i knas, so dei vann ikkje reisa seg. Dei fall under føterne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Du gyrde meg med kraft til striden. Du bøygde motmennern’ mine under meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Fiendarne mine let du snu ryggen til meg, deim som hatar meg, rudde eg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Dei såg seg um - men ingen frelste - til Herren, men han svara deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Eg smuldra deim som dust på jordi; som søyla på gator krasa eg deim; eg trakka deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Du frelste meg ut or mitt folks ufred, til hovud for heidningar vara du meg; folk som eg ikkje kjende, tente meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Ukjende folk smeikte for meg, ved gjetordet um meg lydde dei meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Ja, framandfolk visna av, gjekk skjelvande ut or borgerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Herren liver! lova vere han, mitt berg! Ja, upphøgd vere Gud, mitt frelse-berg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Gud som gjev meg hemn, legg folkeslag under meg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'og fører meg ut frå fiendarne mine! Ja - du som lyfter meg høgt yver motmennern’ mine og bergar meg undan frå valdsmanns hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Difor, Herre, vil eg prisa deg millom heidningarn’, og lovsyngja ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'For han gjer kongen sin sigersæl, gjer miskunn mot honom han salva, mot David og ætti hans til æveleg tid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Dette er Davids siste ord: «So lyder ordi frå David, Isaisonen, so lyder ordi frå mannen som vart upphøgd, han som Jakobs Gud hev salva, Israels ljuvlege songmeister:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Herrens Ande hev tala i meg, ordi hans er på tunga mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israels Gud hev tala so, Israels berg hev sagt til meg: Den som råder og gjer rett millom menn, den som rikjer i otte for Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'han likjest på dagsprett når soli renn, ein morgon forutan skyer, når graset grønkast i sol etter regn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Er det’kje so med mitt hus hjå Gud? Han gjorde ævelegt samband med meg, feste og trygde meg heilt og fullt. Ja, alt som vert meg til frelsa og gleda, det let han visseleg veksa åt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Men uvyrdor likjest alle på utkasta tornar, ein vil ikkje taka i deim med hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Lyt ein røra deim væpnar ein seg med jarn og med spjotskaft; so set ein eld på deim og brenner deim på flekken.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Dette er namni på dei djervaste stridsmennerne åt David: Joseb-Bassebet, tahkmoniten, den fremste av kjemporne, han som svinga spjotet yver åtte hundrad falne på ein gong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Næst honom kom Eleazar, son åt Dodi, son åt ein ahohit. Han var ein av dei tri stridsmennerne som var med David, då filistarane samla seg til strid og svivyrde deim då Israels-mennerne drog seg attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Men han heldt stand og hogg laust på filistarane, til dess handi hans trøytna, so ho trena i hop kring sverdet. Og Herren gav ein stor siger den dagen. Etterpå hadde folket berre å snu um og fylgja med honom og plundra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Næst honom kom Samma, son åt Age, ein hararit. Ein gong stemnde filistarane i hop og vart til ein heil flokk. Der var ein åkerteig full av linsor. Folket rømde for filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Då tok han post midt på åkerteigen og verna honom, og slo filistarane. Herren gav ein stor siger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Ein gong drog tri av dei tretti fremste kararne ned, og kom i skurdonni til David i Adullams-helleren, medan ein filistarflokk låg i læger i Refa’imsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David var då i fjellborgi, samstundes med at ein filistarpost låg i Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'David fekk slik hug og sagde: «Gjev einkvan vilde gjeva meg vatn å drikka frå brunnen ved byporten i Betlehem!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Då braut dei tri stridsmennerne seg gjenom filistarlægret, auste vatn or brunnen ved byporten i Betlehem og bar det til David. Men han vilde ikkje drikka det, men helte det ut for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'For han sagde: «Aldri i verdi, Herre, vil eg gjera dette! Skulde eg drikka blodet av dei mennerne som gjekk av stad og våga livet sitt?» Og han vilde ikkje drikka det. - Sovore hadde dei tri stridsmennerne gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, bror åt Joab Serujason, var den fremste av tri andre. Ein gong svinga han spjotet sitt yver tri hundrad falne. Han hadde eit stort namn millom dei tri;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'han var visseleg meir vyrd enn nokon annan i dette trimannslaget; og han var hovding yver dei hine. Men upp til dei tri fyrste nådde han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benaja Jojadason var son til ein djerv og dådrik mann frå Kabse’el. Han slo dei tvo Ariel i Moab. Det var han som steig ned ein snøversdag og drap løva i brunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Han drap og den egyptaren som var so sjåleg. Endå egyptaren hadde spjot i hand, gjekk han på honom berre med ein stav. Han reiv spjotet ut or handi på egyptaren og drap honom med hans eige spjot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Sovore hadde Benaja Jojadason gjort. Han hadde eit stort namn millom dei tri stridsmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Han var meir vyrd enn nokon av dei tretti. Men upp til dei tri nådde han ikkje. David sette honom inn i livvakti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Til dei tretti høyrde: Asael, bror åt Joab, Elhanan Dodoson frå Betlehem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma frå Harod, Elika frå Harod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Heles, paltiten, Ira Ikkesson frå Tekoa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer frå Anatot, husatiten Mebunnai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'ahotiten Salmon, netofatiten Maharai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'netofatiten Heleb Ba’anason, Ittai Ribaison frå Gibea i Benjamins-ætti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja, ein piratonit, Hiddai frå Ga’asdalarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'arbatiten Abi-Albon, barhumiten Azmavet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'sa’alboniten Eljahba, Bene-Jasen, Jonatan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'harariten Samma, arariten Ahiam Sararsson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, son åt Ahasbai, son åt ma’akatiten, Eliam Ahitofelsson frå Gilo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hesro frå Karmel, arbiten Pa’arai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal Natansson frå Soba, gaditen Bani,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'ammoniten Selek, be’erotiten Naharai, våpnsveinen åt Joab Serujason,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'jitriten Ir, jitriten Gareb,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'hetiten Uria. I alt var dei sju og tretti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Herrens harm loga upp mot Israel att, so eggja David mot deim og sagde: «Gakk av stad og tel Israel og Juda!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Då baud kongen Joab, herhovdingen som var hjå honom: «Far gjenom alle ættarne i Israel frå Dan alt til Be’erseba og mynstra folket, so eg kann få vita folketalet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab svara kongen: «Gjev Herren, din Gud, må gjera dette folket hundrad gonger so talrikt som det er! Og gjev du, herre konge, må få sjå det med eigne augo! Men kvifor hev du, herre konge, fenge hug på sovore?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Like ved stod kongsbodet fast. Joab og dei hine herhovdingarne laut lyda. Joab og dei hine herhovdingarne drog då ut i kongens ærend og mynstra Israels-folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Dei gjekk yver Jordan og slo lægra seg ved Aroer på høgre sida av byen, i Gadsdalen burtimot Jazer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Derifrå kom dei til Gilead og Tatim-Hodsilandet. So kom dei til Dan-Ja’an, og so rundt ikring til Sidon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Deretter kom dei til festningi i Tyrus og alle hevitarbyarne og kananitarbyarne. Til slutt drog dei til Be’erseba i Juda-sudlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Då dei hadde fare soleis gjenom heile landet, kom dei heim til Jerusalem. Ferdi hadde teke ni månader og tjuge dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Joab gav upp åt kongen heile talet som folketeljingi synte: Israel åtte hundrad tusund fullgode våpnføre stridsmenner, og Juda-folki fem hundrad tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Men David fekk samvitsagg etter han hadde talt folket. Og David sagde til Herren: «Eg hev synda grovt med det eg hev gjort. Men tilgjev no, Herre, illgjerdi åt tenaren din! for det var mykje uvisleg gjort av meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Då David reis upp um morgonen, var Herrens ord kome til profeten Gad, sjåaren åt David. Han hadde sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Gakk og seg med David: «So segjer Herren: Tri ting legg eg fram for deg; vel ein av deim som du vil eg skal gjera med deg!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad gjekk inn til David og forkynte honom dette. Han spurde honom: «Vil du at det skal koma sju store uår i landet ditt? Eller vil du i tri månader ljota røma for uvenerne dine med dei forfylgjer deg? Eller at eg skal søkja landet ditt med drepsott i tri dagar? Tenk no yver det, og sjå til kva svar eg skal gjeva honom som hev sendt meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David svara Gad: «Eg er i stor vande. Men lat oss då falla i Herrens hand! for hans miskunn er stor. I menneskjehand vil eg ikkje falla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'So søkte Herren Israel med drepsott frå morgonen til den fastsette tidi. Sju og sytti tusund mann døydde av folket frå Dan til Be’erseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Men då engelen rette ut handi yver Jerusalem og vilde tyna det, so angra Herren det vonde. Og han sagde til engelen som tynte folket: «Det er nok! Drag no handi di attende!» Og Herrens engel var då ved treskjarvollen åt jebusiten Aravna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Men då David fekk sjå engelen som herja millom folket, tala han so til Herren: «Det er då eg som hev synda, det er eg som hev fare gale! men desse sauerne - kva hev dei gjort? Gjev handi di må venda seg mot meg og farshuset mitt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Og Gad kom til David same dagen og sagde til honom: «Gakk av stad og reis eit altar åt Herren på treskjarvollen åt jebusiten Aravna!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'David gjekk av stad etter Gads ord, so som Herren hadde bode honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Då Aravna skoda ut og fekk sjå kongen og kongstenarane koma til honom, gjekk han ut og fall å gruve til jordi framfor kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Aravna spurde: «Kvifor kjem du, herre konge, til tenaren din?» David svara: «Eg vil kjøpa treskjarvollen av deg og byggja der eit altar åt Herren, so sotti må stana som hev herja folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Då sagde Aravna med David: «Tak du og ofra kva du tykkjer høvlegast, herre konge! Her er fe til brennoffer. Her er treskjarvogni og oket på feet til ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Alt saman, konge, gjev Aravna kongen.» Og Aravna lagde til: «Gjev Herren, din Gud, må hava hugnad i deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Kongen svara Aravna: «Nei, eg vil kjøpa det av deg for full pris. Eg vil ikkje ofra åt Herren, min Gud, brennoffer som ingen ting kostar.» So kjøpte David treskjarvollen og feet for femti sylvdalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'David bygde der eit altar åt Herren, og ofra brennoffer og takkoffer. Då bønhøyrde Herren landet. Og då stana sotti som hadde herja Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Kong David var no gamall og ut i åri komen, og han kunde ikkje halda varmen i seg, endå dei bredde klæde yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Då sagde tenarane hans til honom: «Ein trong finna ei ung kvinna åt min herre kongen, ei ung møy som kunde vera hjå kongen og vyrdsla honom. Fekk ho liggja i fanget ditt, vart min herre kongen varm.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'So leita dei då i heile Israelslandet etter ei fager gjenta, og dei fann Abisag frå Sunem og for til kongen med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Det var ei ovende væn gjenta; ho stelte for kongen og tente honom. Men elles hadde ikkje kongen umgjenge med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Men Adonia, som var son åt Haggit, gjorde seg sjølv høg og sagde: «Eg vil vera konge.» Han fekk seg vogner og hestfolk og femti mann som skulde springa fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Far hans hadde aldri såra honom noko sinn og sagt: «Kvi fer du soleis åt?» Han var attåt født ein ovvæn kar, og mor hans hadde født honom næst etter Absalom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Han gjekk på råd med Joab Serujason og med presten Abjatar, og dei slo lag med Adonia og hjelpte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Presten Sadok og Benaja Jojadason og profeten Natan, Sime’i og Re’i og stridskjemporne åt David heldt derimot ikkje med Adonia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Adonia slagta småfe og uksar og gjødkalvar ved Ormsteinen, som ligg attmed Rogel-kjelda; og han bad til seg dit alle brørne sine, kongssønerne, og alle dei Juda-menner som var i tenesta hjå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Men profeten Natan og Benaja og stridskjemporne og Salomo, bror sin, bad han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Då tala Natan til Batseba, mor åt Salomo, soleis: «Du hev vel høyrt at Adonia, son åt Haggit, er vorten konge utan at vår herre David veit noko det um det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'No vil eg gjeva deg ei råd, so du kann berga livet for deg sjølv og for Salomo, son din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Gakk inn til kong David og seg til honom: «Herre konge, hev du ikkje lova tenestkvinna di med eid at Salomo, son min, skal verta konge etter deg og sitja i din kongsstol? Kvifor hev då Adonia vorte konge?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Og medan du stend der og talar med kongen, skal eg koma inn og sanna det du segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Batseba gjekk då inn i sengromet til kongen. Kongen var mykje gamall no, og Abisag frå Sunem tente honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Batseba bøygde seg og kasta seg ned for kongen. Då spurde kongen: «Kva er det du vil?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Ho svara honom: «Herre, ved Herren, din Gud, hev du lova tenestkvinna di med eid, at Salomo, son min, skal vera konge etter deg; han skal sitja i kongsstolen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Men sjå no er Adonia vorten konge, utan at du, herre konge, veit um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Han hev slagta uksar og gjødkalvar og småfe i mengd og bede til seg alle kongssønerne og presten Abjatar og herføraren Joab; men Salomo, tenaren din, hev han ikkje bede.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Heile Israel vender no augo til deg, herre konge, og ventar at du skal kunngjera kven som skal sitja i kongsstolen etter dine dagar, herre konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Utan kann det henda, at når min herre kongen hev lagt seg til kvile hjå federne sine, so vert eg og Salomo, son min, rekna for brotsmenner.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Medan ho endå stod der og tala med kongen, kom profeten Natan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Og dei vitra kongen um det og sagde: «Profeten Natan er her.» Han steig fram for kongen og kasta seg å gruve på jordi for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'So sagde Natan: «Herre konge, er det so du hev sagt at Adonia skal verta konge etter deg, at han skal sitja i kongsstolen din?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Ja, for i dag hev han fare ned og slagta uksar og gjødkalvar og sauer i mengd og hev bede til seg alle kongssønerne og herførarane og presten Abjatar, og no et dei og drikk dei i lag med honom og ropar: «Live kong Adonia!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Men meg, tenaren din, og presten Sadok og Benaja Jojadason og din tenar Salomo hev han ikkje bede.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Kann dette vera gjort etter din vilje, herre konge, utan at du hev late tenarane dine vita kven som skal sitja i kongsstolen din etter deg, herre konge?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Då svara kong David og sagde: «Ropa Batseba hit til meg!» Ho steig hitåt, og då ho stod der framfor kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'svor kongen og sagde: «So sant Herren liver, han som hev løyst meg or all trengsla:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'liksom eg fyrr hev svore deg til ved Herren, Israels Gud, og sagt at Salomo, son din, skal verta konge etter meg og sitja i kongsstolen i min stad, so gjer eg det og i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Då bøygde Batseba seg med andlitet mot jordi og kasta seg ned for kongen og sagde: «Gjev herren min, kong David, må liva i all æva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Og kong David sagde: «Ropa inn til meg presten Sadok og profeten Natan og Benaja Jojadason!» Då dei kom fram for kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'sagde kongen til deim: «Tak tenarane åt herren dykkar med dykk og set Salomo, son min, på mitt eige muldyr og far med honom ned til Gihon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Der skal Sadok, presten, og Natan, profeten, salva honom til konge yver Israel, og de skal blåsa i lur og ropa: «Live kong Salomo!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'So skal de fylgja honom upp att, og han skal koma og setja seg i kongsstolen min; og han skal vera konge i min stad. For det er honom eg hev sett til hovding yver Israel og Juda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Då svara Benaja Jojadason kongen og sagde: «Amen! Må Herren, din Gud, herre konge, segja det same!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Herren vere Salomo som Herren hev vore med deg, herre konge, og gjere hans kongsstol endå veldugare enn kongsstolen til min herre, kong David!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'So gjekk då presten Sadok og profeten Natan og Benaja Jojadason saman med livvakti av og sette Salomo på muldyret åt kong David og for med honom ned til Gihon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Og presten Sadok tok oljehornet or tjeldet og salva Salomo; so blæs dei i lur, og heile lyden ropa: «Live kong Salomo!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Sidan fylgde heile folkemengdi honom upp att med slik fløyteblåster og stor fagnad at jordi kunde ha rivna av ropi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Men Adonia og alle gjesterne som var hjå honom, høyrde dette nettupp då dei var ferdige med måltidi; og då Joab høyrde lurblåsteren, sagde han: «Kva er dette for glam og ståk i byen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'I same stundi kom Jonatan, son åt presten Abjatar, og Adonia sagde: «Kom hit! du er ein fagnamann, som visst hev eit gledebod å bera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Men Jonatan svara honom: «Å nei då; herren vår, kong David, hev gjort Salomo til konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Kongen sende presten Sadok og profeten Natan og Benaja Jojadason og livvakti i veg med honom, dei hev sett honom på muldyret åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'So hev presten Sadok og profeten Natan salva honom til konge i Gihon, og med fagnad hev dei fare upp att derifrå, og heile byen er komen på føterne. Det er det ståket de hev høyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Salomo hev no alt og sett seg i kongsstolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Og kongsmennerne er komne og hev ynskt vår herre kong David til lukka og sagt: «Gjev no din Gud vil lata namnet åt Salomo verta endå gjævare enn ditt eige, og kongsstolen hans endå veldugare enn din kongsstol!» Og kongen heldt bøn på lega si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Kongen hev og sagt: «Lova vere Herren, Israels Gud, som i dag hev sett ein ettermann i kongsstolen min, so eg kann sjå det med eigne augo!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Då vart alle gjesterne hjå Adonia forstøkte, reis upp og tok ut kvar sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Men Adonia ræddast Salomo, so han reis upp og gjekk av og greip um altarhorni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Og dei vitra Salomo um det og sagde: «Sjå, Adonia ræddast kong Salomo; difor hev han gripe um altarhorni og segjer: «Kong Salomo skal lova meg med eid i dag at han ikkje drep tenaren sin med sverd.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Då sagde Salomo: «Vil han bera seg åt som ein fagnamann, so skal ikkje eit hår av hovudet hans falla til jordi; men syner det seg at han fer med noko vondt, so skal han døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'So sende kong Salomo folk av stad, og dei førde honom ned ifrå altaret; han kom då og kasta seg ned for kong Salomo, og Salomo sagde til honom: «Gakk heim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Då det leid til at David skulde døy, gav han Salomo, son sin, fyresegner og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '«Eg gjeng no den vegen som all verdi må fara. Ver so du sterk, og vert ein mann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Tak vare på alt det som Herren, din Gud, vil du skal taka vare på, so du ferdast på hans vegar og rettar deg etter hans lover og bod og rettar og fyresegner, soleis som det er skrive i Mose lov, so du må fara vist åt i alt det du tek deg fyre, og kvar du vender deg -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'so Herren kann halda den lovnad han gav meg og sagde: «Aldri skal du vanta ein ettermann på Israels kongsstol,» sagde han, «er so sønerne dine agtar på vegen sin, so dei ferdast for mi åsyn i truskap av alt sitt hjarta og heile si sjæl.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Du og veit sjølv kva Joab, son åt Seruja, hev gjort imot meg, korleis han bar seg åt mot dei tvo herførarane i Israel, Abner Nersson og Amasa Jetersson, at han tok livet av deim og rende ut blod i fredstid plent som det hadde vore krig, og bloda ut beltet um livet sitt og skorne på føterne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Stell deg no difor som du hev visdom til, og lat ikkje dei grå håri hans fara i fred ned i helheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Men sønerne åt Barzillai frå Gilead skal du gjera vel imot; dei skal vera millom deim som et ved bordet ditt; for soleis møtte dei meg den gongen eg laut røma for Absalom, bror din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'So hev du hjå deg benjaminiten Sime’i, son åt Gera, frå Bahurim; han lyste ei rysjeleg våbøn yver meg den dagen eg gjekk til Mahanajim; men han kom meg sidan i møte nedmed Jordan, og då svor eg honom til ved Herren at eg ikkje skulde drepa honom med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Men no må du ikkje lata honom vera ustraffa, for du er ein vis mann, og veit korleis du skal fara åt med honom, so du let dei grå håri hans fara blodute ned i helheimen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'So Lagde David seg til kvile hjå federne sine; han vart gravlagd i Davidsbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'I fyrti år hadde David vore konge yver Israel. I Hebron styrde han i sju år, og i Jerusalem styrde han i tri og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Og Salomo sette i kongsstolen åt David, far sin, og kongedømet hans vart ovleg sterkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Men Adonia, son åt Haggit, gjekk inn til Batseba, mor åt Salomo. Ho spurde då: «Kjem du med fred?» Han svara: «Ja, med fred!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'So sagde han: «Eg hev ein ting å tala med deg um.» «Ja, tala ut!» svara ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Då sagde han: «Du veit sjølv at kongedømet høyrde meg til, og at heile Israel vona på meg til konge. Men kongedømet gjekk ifrå meg og til bror min; det vart hans, for di Herren laga det so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'No hev eg ei einaste bøn til deg - vis meg ikkje burt.» Ho sagde til honom: «Tala ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Då sagde han: «Seg du til kong Salomo - for deg viser han ikkje burt - at han skal gjeva meg Abisag frå Sunem til kona!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Batseba svara: «Godt, eg skal tala til kongen um deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'So gjekk Batseba inn til kong Salomo og vilde tala med honom um Adonia. Kongen reis upp, gjekk til møtes med henne og bøygde seg for henne, og han sette seg atter i kongsstolen sin. Dei laga til eit sæte for kongsmori, og ho sette seg attmed honom på høgre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'So sagde ho: «Eg hev ei einaste liti bøn til deg; seg ikkje nei!» Og kongen sagde til henne: «Kom fram med bøni di, mor! Eg skal ikkje visa deg burt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Då sagde ho: «Lat Adonia, bror din, få Abisag frå Sunem til kona!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Men kong Salomo svara og sagde til mor: «Kvi bed du nettupp um Abisag frå Sunem åt Adonia? Bed heller um kongedømet åt honom - for han er då eldste bror min - ja, både åt honom og åt presten Abjatar og åt Joab Serujason.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Og kong Salomo svor ved Herren og sagde: «Herren late meg bøta både no og sidan, um ikkje Adonia skal få bøta med livet sitt, for di han hev tala dette!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'So sant Herren liver, han som hev gjeve meg ein stød sess i kongsstolen åt David, far min, og som etter lovnaden sin hev reist meg eit kongehus, so skal Adonia døy i denne dag!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Og kong Salomo sende i veg Benaja Jojadason. Han slo honom ned, og han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Til presten Abjatar sagde kongen: «Gakk til Anatot, til garden din! for du er ein daudedømd mann! men nettupp i dag vil eg ikkje taka livet ditt, etter di du hev bore Herrens, Herrens kista framfyre David, far min, og etter di du hev lide med i alt som far min laut lida.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'So jaga Salomo Abjatar burt og let honom ikkje lenger vera Herrens prest, so det skulde sannast det som Herren hadde sagt um ætti åt Eli i Silo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Då Joab, som hadde halde lag med Adonia, endå han ikkje hadde gjenge saman med Absalom, frette dette, rømde han inn i Herrens tjeld og fata um altarhorni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Men då kong Salomo fekk vita at Joab hadde rømt til Herrens tjeld, og at han stod innmed altaret, sende Salomo Benaja Jojadason i veg og sagde: «Gakk av stad og slå honom ned!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Då no Benaja kom til Herrens tjeld, sagde han til honom: «So segjer kongen: «Gakk ut!»» Men han svara: «Nei, her vil eg døy.» Og Benaja melde svaret til kongen og sagde: «So hev Joab sagt, og so hev han svara meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Kongen sagde til honom: «Gjer som han hev sagt, slå honom ned og få honom i jordi, og fria soleis meg og farshuset mitt frå det skuldlause blodet som Joab hev rent ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Og Herren skal lata blodet hans koma att yver hans eige hovud, av di han hogg ned tvo menner som var rettferdigare og betre enn han sjølv, og drap deim med sverd utan at David, far min, visste det; det var Abner Nersson, Israels herførar, og Amasa Jetersson, Judas herførar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Ja, blodet deira skal koma att yver hovudet åt Joab og avkjømet hans i all æva. Men David og hans avkjøme og huset og kongsstolen hans skal Herren gjeva fred i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Benaja Jojadason gjekk so upp og slo honom ned og tok livet av honom, og han vart jorda attmed huset sitt i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Og kongen sette Benaja Jojadason i hans stad yver heren, og sette presten Sadok i romet etter Abjatar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Sidan sende kongen bod og kalla til seg Sime’i, og sagde til honom: «Bygg deg eit hus i Jerusalem, og gjev deg til der! Du skal ikkje ganga ut derifrå til nokon annan stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'For det skal du vita, at den dagen du gjeng yver Kidronsbekken, skal du døy. Då skal blodet ditt koma yver hovudet ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Og Sime’i sagde til honom: «Godt; som min herre kongen hev sagt, soleis skal tenaren din gjera.» Og Sime’i budde no i Jerusalem ei tid frametter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'So hende det, då tri år var farne, at tvo av trælarne hjå Sime’i rømde til Akis Ma’akason, kongen i Gat. Og då Sime’i frette at trælarne hans var i Gat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'sala han asnet sitt og for til Gat, til Akis, og vilde leita etter deim; Sime’i tok i veg og fekk trælarne sine med seg heim frå Gat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Då no Salomo fekk tiend um at Sime’i var faren ut or Jerusalem og til Gat og var komen att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'sende kongen bod og kalla til seg Sime’i, og sagde til honom: «Hev eg ikkje teke ein eid av deg ved Herren og åtvara deg og sagt: «Det skal du vita, at den dagen du gjeng ut og fer nokon stad av, skal du døy?» Og du sagde: «Det er godt; eg hev høyrt det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Kvi hev du då ikkje agta på eiden din ved Herren, og den fyresegn eg gav deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Og kongen heldt fram og sagde til Sime’i: «Du veit sjølv alt det vonde du hev gjort David, far min; hjarta ditt kjenner det. Herren skal no lata vondskapen din koma att yver ditt eige hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Men kong Salomo skal verta velsigna, og Davids kongsstol standa fast for Herrens åsyn i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Etter bod frå kongen gjekk so Benaja Jojadason ut og hogg honom ned, og han døydde. Og Salomo heldt kongedømet med endå fastare hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Og Salomo kom i giftarskyldskap med Farao, kongen i Egyptarland, med di han gifte seg med dotter åt Farao, og han flutte inn i Davidsbyen med henne til dess han var ferdig med byggjearbeidet på kongsgarden, på Herrens tempel og murarne rundt um Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Men folket ofra på haugarne; for det var ikkje bygt noko hus for Herrens namn fyre den tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomo elska Herren so han fylgde fyresegnerne åt David, far sin. Men ofra på haugarne og brende røykjelse der, gjorde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Og kongen for til Gibeon og vilde ofra der. For det var gjævaste offerhaugen. Tusund brennoffer ofra Salomo på altaret der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'I Gibeon synte Herren seg for Salomo i ein draum um natti, og Gud sagde: «Bed um kva du vil eg skal gjeva deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo svara: «Stor miskunn hev du vist imot tenaren din, David, far min, etter di han ferdast for di åsyn i truskap og rettvisa og med ærleg hug imot deg; og du hev halde ved lag åt honom denne store miskunn og gjeve honom ein son til ettermann i kongsstolen hans - so som det no sjåande er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Ja, Herre, min Gud, no hev du gjort tenaren din til konge etter David, far min, men eg er berre barnet, og veit ikkje korleis eg skal bera meg åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Og tenaren din liver her millom folket ditt, som du hev valt ut, eit stort folk som ikkje er teljande eller utreknande, so mangment det er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'So gjev då tenaren din eit høyrsamt hjarta, so han kann vera domar for folket sitt og skilja millom godt og vondt! for kven er elles før til å vera domar for dette mangmente folket ditt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Det tektest Herren vel at Salomo bad um dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Og Gud sagde til honom: «Etter di hev bede um dette og ikkje bede um langt liv eller rikdom og ikkje bede um livet av fiendarne, men hev bede um vit til å agta på det som rett er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'so vil eg gjera som du ynskjer: eg gjeva deg so vist og vitugt eit hjarta at det hev ikkje vore din like, og skal ikkje heller verta sidan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Eg vil gjeva deg det du ikkje hev bede um: rikdom og heider, so at ingen av kongerne skal vera din like i all di tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Og vil du fara på mine vegar, so du held loverne og bodi mine, liksom David, far din, gjorde, so skal eg lata livedagarne dine verta mange.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Då vakna Salomo - det var ein draum. Og då han kom til Jerusalem, steig han fram for Herrens sambandskista, ofra brennoffer og bar fram takkoffer, og gjorde eit gjestebod for alle tenarane sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Då kom det tvo skjøkjor til kongen, og steig fram for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Og den eine kvinna sagde: «Høyr meg, herre! Eg og denne kvinna bur i same huset. Og eg fekk eit barn der i huset hjå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Tridje dagen etter at eg hadde fenge barnet, fekk denne kvinna og eit barn; og me var saman; der var ingen framand hjå oss i huset; me tvo eine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Men ei natt døydde guten åt denne kvinna, av di ho hadde lagt seg på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Då reis ho upp midt på natti og tok min gut ifrå sida mi, medan tenestkvinna di sov, og lagde honom i sitt fang, og sin eigen daude gut lagde ho i mitt fang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Då eg so reis upp um morgonen og skulde gjeva guten min suga, då var han daud; men då eg skoda vel på honom um morgonen, vart eg vis med at det var ikkje den gut eg hadde født.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Den andre kvinna sagde: «Det er ikkje so. Min gut er den som liver. Det er din gut som er daud.» Men den fyrste svara: «Nei, den daude er din gut, den livande er min.» Soleis trætta dei framfor kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Då sagde kongen: «Den eine segjer: «Denne som liver, er min gut, og den daude er din.» Og den andre segjer: «Det er ikkje so; din gut er det som er daud, og min gut er den som liver.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Gakk etter eit sverd åt meg!» sagde kongen. Og då dei hadde bore sverdet inn til kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'sagde han: «Hogg det livande barnet i tvo luter, og gjev denne eine helvti til den eine og den andre helvti til den andre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Men då sagde ho til kongen, den kvinna som var mor åt det livande barnet - for hjarta hennar brann for guten -: «Høyr meg, herre,» sagde ho, «lat henne få det barnet som liver, og drep det ikkje!» Men hi sagde: «Lat det vera korkje mitt eller ditt; hogg det i tvo!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Då svara kongen og sagde: «Gjev henne der det livande barnet; drep det ikkje! Ho er mori.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Og då denne domen som kongen hadde sagt, spurdest i heile Israel, fekk dei age for kongen; for dei såg at Guds visdom var i honom, so han kunde døma rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Kong Salomo var no konge yver heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Og dei fremste menner han hadde var dette: Azarja Sadoksson var prest;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoref og Ahia, søner åt Sisa, var riksskrivarar; Josafat Ahiludsson var kanslar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja Jojadason var set yver heren, og Sadok og Abjatar var prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarja Natansson var set yver futarne, Zabud Natansson var prest og ven med kongen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar var drottsete, og Adoniram Abdason hadde tilsyn med pliktarbeidarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Og Salomo hadde tolv bygdefutar yver heile Israel. Dei hadde på seg å forsyna kongen og kongsgarden hans; dei forsynte honom kvar sin månad um året.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Dette er namni deira: Son åt Hur i fjellbygdi i Efraim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'son åt Deker i Mahas og i Sa’albim, Bet-Semes, Elon-Bet-Hanan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'son åt Hesed i Arubbot, som hadde Soko og heile Heferlandet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'son åt Ahinadab, som hadde heile høglandet Dor, og som fekk Tafat, dotter åt Salomo, til kona;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Ba’ana Ahiludsson i Ta’anak og Megiddo og i heile den luten av Bet-Sean som ligg attmed Sartan nedanfor Jizre’el, frå Bet-Sean til Ahel-Mehola og burtum Jokmeam;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'son åt Geber i Ramot i Gilead; han hadde Gileads-byarne åt Ja’ir Manasseson; han hadde Argoblandet, som ligg i Basan, seksti store byar med murar og koparslåer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab Iddoson hadde Mahanajim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahima’as i Naftali; han og hadde teke ei dotter åt Salomo, Basmat, til kona;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Ba’ana Husaison i Asser og Alot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josafat Paruahsson i Issakar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Sime’i Elason i Benjamin;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber Urison i Gileadlandet, det landet som amoritarkongen Sihon og kong Og i Basan hadde havt; og han var den einaste futen i den landsluten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda og Israel var då so mangmente som sanden ved havet; og dei åt og drakk og var glade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Og Salomo rådde yver alle kongeriki frå Storelvi til Filistarlandet og heilt ned til landskilet imot Egyptarland. Dei sende gåvor til Salomo, og lydde honom so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Og dei matvaror Salomo trong for kvar dag, var nitti tunnor fint mjøl og eit hundrad og åtteti tunnor vanlegt mjøl,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'ti gjødde uksar, tjuge utgangsuksar, hundrad sauer, umfram hjortar, gasellor, antilopar og gjødde fuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'For han rådde yver heile landet på andre sida av Storelvi, frå Tifsah og heilt til Gaza, han stod yver alle kongarne på andre sida Storelvi, og han hadde fred rundt ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'so Juda og Israel sat trygt, kvar mann under sit vintre og under sitt fiketre, ifrå Dan radt til Be’erseba, so lenge Salomo livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Og Salomo hadde fyrti tusund par vognhestar og tolv tusund ridehestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Og bygdefutarne forsynte kong Salomo og alle deim som gjekk til bords hjå kong Salomo kvar sin månad; dei let det ikkje skorta på nokon ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Bygg og halm til hestarne og tråvarane sende dei, kvar etter sin tur, til den staden der han heldt til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Og Gud gav Salomo visdom og ovstor kunnskap og eit vit som femnde vidt - liksom sanden ved havet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'so at visdomen åt Salomo var større enn visdomen hjå austmennerne og egyptarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Han var visare enn alle andre menneskje, visare enn ezrehiten Etan, Heman og Kalkol og Darda, sønerne åt Mahol; og det gjekk gjetord av honom hjå alle folki vida ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Han dikta tri tusund ordtøke, og songarne hans var eit tusund og fem i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Han tala um trei, like frå cederen på Libanon til isopen som veks uppetter murveggen; han tala um firfot-dyri og fuglarne, um krypdyri og fiskarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Frå alle land kom dei og vilde høyra på visdomen åt Salomo, frå alle kongarne på jordi som høyrde gjete kor vis han var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Og Hiram, kongen i Tyrus, sende tenarane sine til Salomo, då han no hadde frett at han var salva til konge etter David, far sin; for Hiram hadde alltid vore til vens med David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Og Salomo sende bod til Hiram med den helsingi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '«Du veit at David, far min, ikkje kunde bygja noko hus for namnet åt Herren, hans Gud, av di han fekk ufred med fiendarne på alle kantar, til dess Herren lagde deim under føterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Men no hev Herren, min Gud, late meg få ro til alle sidor; der er ingen motmann og ingen fåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Difor hev eg sett meg fyre at eg vil byggja eit hus for namnet åt Herren, min Gud, etter det Herren sagde til David, far min: «Son din, som eg vil setja i kongsstolen i din stad, han skal byggja huset åt namnet mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Gjev no difor påbod um at dei skal fella ceder åt meg på Libanon! Arbeidsfolket mitt skal vera med arbeidsfolket ditt, og eg skal gjeva deg den løn folket ditt skal hava, plent som du vil. For du veit sjølv at det finst ingen millom oss som skynar seg so godt på skogshogster som sidoniarane.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Då Hiram høyrde denne helsingi frå Salomo, vart han ovleg glad og sagde: «Lova vere Herren i dag, som hev gjeve David ein vis son til hovding yver dette mangmente folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Og Hiram sende bod til Salomo med den helsingi: «Eg hev høyrt den buskapen du hev sendt meg; eg skal gjera alt det du ynskjer med umsyn til cedertrei og cypresstrei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Arbeidsfolket mitt skal få deim ned frå Libanon til havet; so skal eg få deim lagde i hop i flotar på havet, og føra deim til den staden som du gjev meg bod um; der skal eg få deim tekne frå kvarandre, og so fær du henta deim. Men so skal du gjera meg til viljes med å forsyna huset mitt med matvaror.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'So let Hiram Salomo få alt han vilde hava av cedertre og cypresstre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'og Salomo gav Hiram seksti tusund tunnor kveite til hushaldet hans og seksti tunnor olje av sundstøytte oljebær. Dette let Salomo Hiram få kvart år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Og Herren gav Salomo visdom, soleis som han hadde lova honom, og det var fred millom Hiram og Salomo; dei tvo gjorde eit samband med einannan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Kong Salomo tok so ut pliktarbeidarar i heile Israel; og dei var tretti tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Han sende deim til Libanon, ti tusund um månaden etter tur; ein månad var dei på Libanon, tvo månader heime. Og Adoniram hadde tilsynet med pliktarbeidarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Salomo hadde sytti tusund berarar og åtteti tusund steinhoggarar i bergi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'umfram dei tri tusund tri hundrad arbeidsfutar som styrde arbeidet for Salomo og rådde yver folket som gjorde arbeidet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Etter bod frå kongen braut dei ut store steinar, kostesame steinar til grunnmur under huset, firhogne steinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Og bygningsmennerne til Salomo og Hiram og mennerne frå Gebal hogg til og gjorde ferdig trevyrket og steinarne til husbygningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'I det fire hundrad og åttetiande året etter Israels-folket for ut or Egyptarland i månaden siv - det er den andre månaden i det fjorde året etter Salomo hadde vorte konge yver Israel - tok han til å byggja huset for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Huset som kong Salomo bygde for Herren, var seksti alner langt, tjuge alner breidt og tretti alner høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Forhalli framanfor det heilage var tjuge alner lang langs etter breidsida på huset og ti alner breid framanfrå huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Han laga vindaugo på huset med fast traleverk fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Og rundt umkring huset frammed veggen sette han upp ein tilbygnad, umkring både det heilage og det høgheilage, og reide til kovar der rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Den nedste høgdi var fem alner breid, millomhøgdi seks alner breid, og den tridje høgdi var sju alner breid; for han hadde gjort hjellar utantil rundt um på huset, so ikkje bjelkarne skulde ganga inn i husveggjerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Då huset vart reist, vart det bygt av stein som var tilhoggen i steinbrotet; difor høyrde ein korkje hamar eller øks eller noko jarnverkty i huset då det vart bygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Døri til midkoven stod på høgre sida av huset, med ei vindetropp kom ein upp i andre høgdi og frå andre høgdi upp i tridje høgdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Då han hadde bygt huset fullferdigt, tekte han det med bjelkar og cederplankar i rader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Og tilbygnaden frammed heile huset sette han upp i høgder på fem alner; dei var feste til huset med cederbjelkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Og Herrens ord kom til Salomo soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '«Dette huset som du byggjer - dersom du gjeng etter mine fyresegner og held loverne mine og agtar på alle bodordi mine og fylgjer deim, so vil eg stadfesta på deg det ordet som eg tala til David, far din,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'og eg vil bu hjå Israels-borni og ikkje slå handi av Israel, folket mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'So bygde då Salomo huset og gjorde det fullferdigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Han klædde husveggjerne innvendes med cederbord; frå golvet i huset og like upp til loftslistarne klædde han det med bord innvendes, og golvet i huset klædde han yver med cypressplankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Tjuge alner fram ifrå baksida i templet sette han ein vegg av cederbord frå golvet og upp til loftslisterne, og dette reidde han til innvendes kor åt seg, det høgheilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Og huset - det heilage framanfor koret - var fyrti alner langt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Innantil hadde huset cederklædnad med utskorne kolokvintar og blomeband; alt saman der var av cedertre; ingen stein synte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Inst i huset reidde han til ein kor til å setja Herrens sambandskista i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Og framanfor koren, som var tjuge alner lang og tjuge alner breid og tjuge alner høg, og som han klædde med skirt gull, sette han eit altar og klædde det med cedertre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Og Salomo klædde huset innvendes med skirt gull, og han hengde gullkjedor frametter veggen framfor koren og klædde den og med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Heile huset klædde han med gull, til det var gullklædt heilt og halde. Han klædde og med gull heile altaret som høyrde til i koren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Tvo kerubar av oljetre laga han og til i koren; ti alner var deira høgd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Fem alner var den eine kerubvengen fem alner var den andre, ti alner frå vengjesnipp til vengjesnipp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Ti alner var den andre keruben og; båe kerubarne hadde same mål og same skap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Den eine keruben var ti alner høg, og det same var den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Og han sette kerubarne midt i inste romet i huset, og breidde ut vengjerne deira, so den eine keruben nådde burt i veggen med eine vengjen, og den andre keruben nådde veggen på hi sida med eine vengjen; og midt i huset nådde dei tvo andre vengjerne i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Og han klædde kerubarne yver med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Og alle veggjer i huset rundt ikring prydde han med utskorne bilæte av kerubar og palmor og utsprotne blomar både i inste romet og i det ytre romet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Golvet i huset klædde han yver med gull, både i inste romet og i det ytre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'For inngangen til koren sette han vengdører av oljetre. Dørkarmen med stolparne var ein femtepart av veggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Og dei tvo dørerne av oljetre prydde han med utskorne bilæte av kerubar og palmor og utsprotne blomar og klædde deim med gull. Han lagde gullet ut yver kerubarne og palmorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Sameleis sette han dørstolpar av oljetre for inngangen til det heilage, på fjordeparten av veggen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'og tvo vengdører av cypresstre, den eine vengdøri laga av tvo rørlege bordbreider, og den andre vengdøri laga av tvo rørlege bordbreider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Og han fekk skore ut kerubar og palmor og utsprotne blomar og lagde på gull, som vart jamna utyver treskurden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Den indre fyregarden gjerde han inn med tri rader hoggen stein og ei rad cederbjelkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'I det fjorde året, i månaden siv, vart grunnen lagd til Herrens hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'og i det ellevte året, i månaden bul - det er åttande månaden - var huset ferdigt i alle stykke og heilt som det skulde vera. I sju år var det då bygt på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Men på sitt eige hus bygde Salomo i trettan år fyrr han var ferdig med heile huset sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Han bygde Libanonskoghuset, hundrad alner langt og femti alner breidt og tretti alner høgt, på fire rader av cederstolpar og med cederbjelkar uppå stolparne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Og det var tekt med cedertre uppyver loftsromi på stolparne, fem og fyrti i talet, femtan i kvar rad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Der var bjelkelag i tri rader, og sjågluggar sat midt imot kvarandre i tri umgangar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Og alle dørerne og dørstolparne var firkanta av bjelkar; og sjågluggarne sat midt imot kvarandre i tri umgangar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'So sette han upp sulehalli, som var femti alner lang og tretti alner breid; og det var ei sval framfyre henne med stolpar og troppar framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Og han sette upp høgsæte-halli, der han sat og dømde, domshalli, og den var tilja med cederbord frå eine enden av golvet til den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Og huset hans, som han budde i, i det andre tunet, innanfor forhalli, var bygt på same vis. Salomo bygde og eit hus, i likskap med denne forhalli, for Farao-dotteri, som han hadde teke til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Alt dette var av kostesame steinar, tilhogne etter mål, skorne med sag på innsida og utsida, alt, like frå grunnen og til taklisterne: og sameleis alt utanfor like til den store fyregardsmuren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Grunnmuren var lagd med kostesame og store steinar, steinar på ti alner og steinar på åtte alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Og ovanpå der var låg prydelege steinar, hogne til etter mål, og cederbjelkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Den store fyregardsmuren rundt um var uppsett med tri umfar med tilhogne steinar og eitt umfar med cederbjelkar, på same vis som den indre fyregardsmuren til Herrens hus og forhalli i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Og kong Salomo sende bod og henta Hiram frå Tyrus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Han var son åt ei enkja av Naftali-ætti, og far hans var ein mann frå Tyrus, ein koparsmed. Han hadde i fullt mål visdom og vit og kunnskap til å gjera alt slag arbeid i kopar. Han kom då til kong Salomo og gjorde alt arbeidet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Han laga dei tvo koparsulorne; attan alner var høgdi på den eine sula og ein snor på tolv alner rakk rundt um den andre sula.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'So laga han tvo sulehovud, støypte av kopar, til å setja på toppen av sulorne; fem alner var høgdi på det eine sulehovudet og fem alner høgdi på det andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'På sulehovudi, som stod på toppen av sulorne, var der krot, på lag som garnmoskar, kjedor til hengjeprydnad, sju på kvart sulehovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Og han fekk til granateple, tvo rader rundt umkring attmed garnkrotet til å løyna sulehovudi, og soleis gjorde han og med det andre sulehovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Sulehovudi på stolparne inni forhalli var på skap som liljor, fire alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'På båe sulorne var det sulehovud, ovanum og, tett innmed den tjukkare parten på den andre sida av garnkrotet. Og granatepli var tvo hundrad, i rader rundt um på det andre sulehovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Og han reiste upp sulorne ved forhalli til templet; den sula som han reiste på høgre sida, kalla han Jakin, og den vinstre sula han reiste upp, kalla han Boaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'I øvste enden var sulorne som liljor på skap. So vart då arbeidet med stolparne fullført.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Han laga og eit støypt hav. Det var ti alner frå den eine kanten til den andre kanten, heilt rundt og fem alner høgt, og ei snor på tretti alner gjekk rundt um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Under trømen på det rundt ikring var der kolokvintar, ti på kvar aln rundt um havet. Kolokvintarne gjekk i tvo rader, støypte i hop i ei støyping med havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Det stod på tolv uksar; tri snudde mot nord, tri snudde mot vest, tri snudde mot sud, tri snudde mot aust. Havet låg uppå desse, og alle snudde bakkroppen inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Tjukkleiken på det var ei handbreidd, og kanten på det var laga som på eit staup, liksom ein liljeblom. Det tok tvo tusund anker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'So arbeide han dei ti fotstykki, av kopar. Fire alner var lengdi på kvart fotstykki, fire alner var breiddi, og tri alner var høgdi på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Og fotstykki var laga soleis: Dei hadde fyllingar, fyllingar millom hyrnelisterne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'og på fyllingarne - millom hyrnelisterne - var der løvor, uksar og kerubar, og det same på hyrnelisterne uppyver; nedunder løvorne og uksarne var der lauvverk som hekk nedetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Kvart fotstykke hadde fire hjul av kopar og åsar av kopar, og dei fire føterne på det hadde berestykke; berestykki var støypte på under balja; kvart hadde lauvverk på den andre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Opningi på henne var inni krunestykket, som lyfte seg upp ei aln; i det var opningi rund og laga til underlag, halvonnor aln. På kanten der og var det bilæt-utskjeringar, men sidefyllingarne var firkanta, ikkje runde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Dei fire hjuli sat nedunder fyllingarne, og hjultapparne stod fast i fotstykket; kvart hjul var halvonnor aln høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Hjuli var gjorde som vognhjul elles; og tapparne, falli, tralerne og navi, alt saman var støypt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Det var fire berestykke på dei fire hyrno på kvart fotstykke; berestykki gjekk i eitt med fotstykke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Og uppå fotstykket var der eit anna stykke, som var ei halv aln høg og heilt rundt, og øvst på fotstykket sat handtaket og fyllingarne i eitt med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Og på flatsida av handtaki og på fyllingarne skar han ut kerubar, løvor og palmor etter som der var rom til på deim, og lauvverk rundt umkring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Soleis laga han dei ti fotstykki; same støyping, same mål og same skap hadde dei alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Han arbeidde so ti koparbaljor; kvar balja rømde fyrti ankar og var fire alner vid. Det var ei balja på kvart av dei ti fotstykki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Og han sette fem av fotstykki ved sida av huset til høgre, og fem ved sida huset til vinstre. Havet sette han på høgre sida åt huset, imot sudaust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hiram arbeidde og oskefati, og like eins skuflerne og skålarne, og soleis gjorde då Hiram ifrå seg alt det arbeid han ytte kong Salomo til Herrens hus; det var:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Tvo sulor og dei tvo kulorne på sulehovudi på toppen av sulorne, og dei tvo garnkroti til tekkje yver dei tvo kulerunde sulehovudi, som var på toppen av sulorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'og dei fire hundrad granatepli til båe garnkroti, tvo rader granateple til kvart garnkrot til tekkje yver dei kulerunde sulehovudi på sulorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'og dei ti fotstykki med dei ti baljorne uppå fotstykki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'og so havet - berre eitt - med dei tolv uksarne under havet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'dessutan oskefati, skuflerne og skålarne. Alle desse ting som Hiram arbeidde åt kong Salomo til Herrens hus, var av blank kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'I Jordan-kverven var det kongen fekk deim støypte, i den faste jordi millom Sukkot og Sartan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Salomo let alle desse tingi vera uvegne, for di det var slik ei ovmengd. Det vart ikkje utrøynt kor mykje koparen vog.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomo laga og til alle dei andre ting som skulde vera i Herrens hus: gullaltaret og gullbordet, som skodebrødi skulde liggja på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'ljosestakarne, fem på høgre og fem på vinstre sida framfyre koren, av skiraste gull, og blomarne og lamporne og ljosesakserne av gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'og fati, knivarne, skålarne, kannorne og glodpannorne av skiraste gullet, dessutan gullhengslorne til dørerne inst i huset, til det høgheilage romet, og til husdørerne inn til tempelsalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Då det no var undangjort alt det arbeid kong Salomo hadde med Herrens hus, so førde Salomo inn der heilaggåvorne åt David, far sin: sylvet, gullet og gognerne; han lagde det inn i skattkammeri i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Då stemnde Salomo saman styresmennerne i Israel, alle ættarhovdingarne, formennerne for ættgreinerne åt Israels-sønerne, til kongen i Jerusalem; dei skulde henta Herrens sambandskista upp frå Davidsbyen, det er Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Då samla alle Israels-mennerne seg hjå kong Salomo i helgi i månaden etanim, det er sjuande månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Då no alle styresmennerne i Israel kom, tok prestarne upp kista');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'og bar Herrens kista og møtetjeldet dit upp saman med alle dei heilaggognerne som var i tjeldet; det var prestarne og levitarne som bar deim upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Og kong Salomo stod framfor sambandskista i lag med heile Israels-lyden, som hadde samla seg hjå honom. Og dei ofra småfe og storfe i uteljande og ureknande mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Prestarne flutte sambandskista inn i koren, i det høgheilage, inn under vengjerne av kerubane, der ho skulde vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'For kerubarne breidde ut vengjerne yver den staden der kista stod, so at kerubarne tekte yver både kista og stengerne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Stengerne var so lange at ein kunne vel sjå endarne av deim ifrå det heilage framfyre koren, men ikkje lenger ute. Og der vart dei verande til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Det fanst ikkje anna i kista enn dei tvo steintavlorne som Moses hadde lagt i henne der ved Horeb den gongen Herren gjorde samband med Israels-borni, då dei drog ut or Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Då no prestarne gjekk ut or heilagdomen, fyllte skyi Herrens hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'so prestarne for skyi skuld kunde ikkje standa og gjera tenesta, etter di Herrens herlegdom fyllte Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Då sagde Salomo: «Herren hev sagt at han vil bu i dimma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'No hev eg bygt eit hus til bustad åt deg, ein stad der du kann dvelja æveleg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'So snudde kongen seg og velsigna heile Israels-lyden, medan heile Israels-lyden stod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Han sagde: «Lova vere Herren, Israels Gud! Med handi si hev han halde det som han med munnen sin lova David, far min, då han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '«Frå den tidi då eg førde Israel, folket mitt, ut or Egyptarland, hev eg ikkje valt ut nokon by av alle Israels ætter der ein kunde byggja eit hus til bustad for namnet mitt. Men David hev eg valt ut til å råda yver Israel, folket mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Og David, far min, sette seg nok fyre å byggja eit hus for namnet åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Men Herren sagde til David, far min: «Når du hev sett deg fyre å byggja eit hus for namnet mitt, so hev du gjort vel i at du hev fenge sovorne i tankarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Men byggja dette huset skal ikkje du; son din, som gjeng ut av dine lender, skal byggja huset for namnet mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Og Herren hev sett i verk ordet sitt; eg er komen upp i romet etter David, far min, og eg hev sett meg i Israels kongsstol, soleis som Herren lova, og eg hev bygt dette huset for namnet åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Og der hev eg reidt til eit rom for kista som Herrens samband er i, det som han gjorde med federne våre, den gongen han leidde deim ut or Egyptarland.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'So stelte Salomo seg fram for Herrens altar rett imot heile Israels-lyden, rette ut henderne sine imot himmelen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'og sagde: «Herre, Israels Gud! Ingen gud er deg lik, i himmelen der uppe eller på jordi her nede, du som held uppe sambandet og nåden mot tenarane dine når dei ferdast for di åsyn med heile sitt hjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'du som hev halde det du lova tenaren din, David, far min, og som hev fullført med handi det du tala med munnen, som det syner seg i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'So haldt no og, Herre, Israels Gud, det som du lova tenaren din, David, far min, då du sagde: «Aldri skal den tid koma at det ikkje sit ein mann av di ætt på Israels kongsstol for mi åsyn, når berre sønerne dine vaktar sin veg so dei ferdast for mi åsyn soleis som du hev gjort det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Å, Israels Gud, lat det sannast det ordet som du tala til tenaren din, David, far min!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Men kann då Gud i røyndi bu på jordi? Sjå, himlarne, ja himle-himlarne kann ikkje røma deg, kor mykje mindre då dette huset som eg hev bygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Men vend deg likevel til bøni åt tenaren din og hans påkalling, Herre, min Gud, so du høyrer på det ropet og den bøni som tenaren din bed for di åsyn i dag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'og let augo dine vera opne mot dette huset natt og dag, mot den staden som du hev sagt det um at her skal namnet ditt bu, so du høyrer på den bøni som tenaren din vender mot denne staden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Ja, høyr på den påkalling som tenaren din, og Israel, folket ditt, vender mot denne staden; høyr det på den staden du bur i himmelen! Og når du høyrer, so må du tilgjeva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Forsyndar einkvar seg mot næsten sin, og dei legg ein eid på honom, so ein let honom sverja, og han so kjem inn og sver framfyre altaret ditt i dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'so må du høyra det i himmelen, og setja i verk og døma imillom tenarane dine, med di du segjer den skuldig som saka er og let honom lida for si åtferd, men frikjenner den rettferdige og let honom få etter si rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Når Israel, folket ditt, lid usiger mot fienden, for di dei syndar imot deg, men dei so vender um att til deg og vedkjennest ditt namn og bed og tiggar deg um nåde i dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'so vil du høyra det i himmelen og tilgjeva Israel, folket ditt, den syndi dei gjorde, og føra deim heim att til det landet du hev gjeve federne deira!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Når himmelen let seg att, so det ikkje kjem regn, for di dei syndar imot deg, og dei so snur seg mot denne staden med bøn, og dei vedkjennest namnet ditt og vender um ifrå syndi si, av di du audmjuker deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'so må du høyra det i himmelen og tilgjeva tenarane dine og Israel, folket ditt, syndi deira, for du lærer deim den gode vegen dei skal ganga på; og du må gjeva regn yver landet ditt, som du hev gjeve folket ditt til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Når det kjem uår i landet, når det kjem farsott, når det kjem moldaks og rust, eller det kjem engsprettor og åmor, eller fienden trengjer folket i det landet der det hev byarne deira, eller kva for ei plåga eller sjukdom det er -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'kvar gong det då stig upp ei bøn eller ei audmjuk påkalling frå eit menneskje i heile folket ditt, Israel, som kjenner sitt hjarte-mein og rettar ut henderne sine mot dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'so må du høyra det i himmelen der du bur, og du må tilgjeva og setja i verk og gjeva kvar mann lika for all hans ferd, av di du kjenner hjarta hans - for einast du kjenner hjarta hjå alle folk -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'so dei må ottast deg all den tid dei liver på den jordi som du hev gjeve federne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Jamvel den framande, som ikkje høyrer til Israel, folket ditt, men kjem frå eit land langt burte, for namnet ditt skuld');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '- for dei og kjem til å få høyra um ditt store namn, um di sterke hand og um din strake arm - når han kjem og vender bønerne sine mot dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'so må du høyra i himmelen der du bur, og gjera alt som den framande ropar til deg um, so alle folk på jordi må læra å kjenna namnet ditt og ottast deg, liksom Israel, folket ditt, og skyna at dette huset som eg hev bygt, er uppkalla etter ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Når folket ditt fer ut i herferd mot fienden sin på den vegen du sender deim, og dei so bed til Herren med andlitet mot denne byen du hev valt ut og det huset som eg hev bygt åt namnet ditt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'so må du i himmelen høyra bøni og påkallingi deira og hjelpa deim til retten sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Når dei syndar imot deg - for det finst ikkje noko menneskje som ikkje syndar - og du harmast på deim og let fienden få magt yver deim, so han fangar deim og fører deim burt til fiendeland langt av leid eller nær ved,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'og dei då tenkjer seg um i det landet der dei er fangar, og vender um og bed deg um nåde i landet åt deim som held deim i band, og segjer: «Me hev synda og gjort ille, me hev vore ugudlege,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'og dei vender um til deg med heile sitt hjarta og all si sjæl der i fiendeland hjå deim som hev ført deim i trældom, og bed til deg med andlitet imot landet sitt, som du hev gjeve federne deira, imot den byen som du hev valt ut og det huset som eg hev bygt åt namnet ditt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'so må du i himmelen, der du bur, høyra bøni og påkallingi deira og hjelpa deim til retten sin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'og tilgjeva folket ditt det dei hev synda imot deg og all den misgjerd dei hev gjort i mot deg, og lata deim finna miskunn hjå deim som held deim i band, so dei gjer sælebot på deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'for dei er ditt folk og din arv, som du leidde ut or Egyptarland, midt ut or jarnomnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Ja, gjev augo dine må vera opne for påkallingi åt tenaren din og folket ditt, Israel, so du høyrer på deim so tidt som dei ropar til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'For du hev skilt deim ut ifrå alle folk på jordi, so dei skal vera din arv soleis som du hev tala gjenom Moses, tenaren din, då du leidde federne våre ut or Egyptarland, Herre, Herre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Og då Salomo hadde enda heile denne bøn og audmjuke påkalling til Herren, reis han upp frå Herrens altar, der han hadde lege på kne med henderne utbreidde imot himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Og han steig fram og velsigna heile Israels-lyden med høg røyst og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '«Lova vere Herren, som hev gjeve folket sitt, Israel, ro, plent som han hev sagt! Ikkje eitt ord hev vorte um inkje av alt det gode han hev lova ved Moses, tenaren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Måtte Herren, vår Gud, vera med oss, som han hev vore med federne våre, og ikkje venda seg frå oss eller støyta oss burt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'men bøygja hjarta vårt til seg, so me gjeng på alle hans vegar og held hans bod og fyreskrifter og rettar, som han gav federne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Og måtte desse ordi mine, som eg audmjukt hev bede for Herrens åsyn, vera nærverande for Herren, vår Gud, både dag og natt, so han hjelper tenaren sin og Israel, folket sitt, til retten deira etter som det trengst kvar dag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'so at alle folk på jordi må skyna at Herren er Gud og ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Og de må gjeva dykk til Herren, vår Gud, med heile dykkar hjarta, so de ferdast i hans fyreskrifter og held hans bod som de gjer i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Og kongen og heile Israel med honom ofra slagtoffer for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Til det takkofferet som Salomo ytte Herren, tok han tvo og tjuge tusund stykke storfe og eit hundrad og tjuge tusund stykke småfe. Soleis vigde kongen og heile Israels-lyden Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Same dagen helga Salomo den midtre luten av tunet framfyre Herrens hus; for der ofra han brennoffer, grjonoffer og feittstykke av takkofferet, etter di koparaltaret, som stod for Herrens åsyn, var for lite til å røma brennofferet og grjonofferet og feittstykki av takkofferi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'På den tid høgtida Salomo helgi saman med heile Israel - ein stor møtelyd like frå den staden der vegen gjeng til Hamat og til Egyptarlands-bekken - framfor Herren, vår Gud, i sju dagar og endå i sju dagar, fjortan dagar i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Den åttande dagen let han folket fara, og dei bad velliva med kongen og tok heim kvar til seg, glade og velnøgde for alt det gode som Herren hadde gjort imot David, tenaren sin, og mot Israel, folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Då Salomo no hadde gjort ifrå seg byggjearbeidet med Herrens hus og kongshuset og alt det andre som han hadde hug og lyst til å få gjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'synte Herren seg for Salomo andre gongen, liksom han hadde synt seg for honom i Gibeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Og Herren sagde til honom: «Eg hev høyrt bøni di og di audmjuke påkalling som du hev sendt upp til meg; huset du hev bygt, hev eg helga til å bera namnet mitt i all æva, og augo mine og hjarta mitt skal vera der alle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Ferdast du no for mi åsyn liksom David, far din, ferdast, i hjartans reinleik og i ærlegdom, so du gjer alt det som eg hev sagt deg fyre, held loverne og rettarne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'då skal eg halda uppe kongsstolen din i Israel æveleg, soleis som lovnaden min lydde til David, far din: «Aldri skal du vanta ein mann på Israels kongsstol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Men dersom de og borni dykkar snur meg ryggen og ikkje held bodi mine, loverne mine som eg hev lagt fram for dykk, men gjeng av stad og dyrkar andre gudar og bed til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'so vil eg rydja Israel ut or det landet eg hev gjeve deim; det huset eg hev helga for namnet mitt, vil eg føykja ifrå mi åsyn, og Israel skal verta eit ordtøke og ei spott millom alle folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Og um dette huset vert aldri so høgt, so skal kvar mann fæla og spotta når han framum fer; og spør ein: «Kvifor hev Herren fare soleis åt med dette landet og dette huset?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'då skal dei svara: «For di dei vende seg ifrå Herren, sin Gud, han som hadde ført federne deira ut or Egyptarland, og heldt seg til andre gudar, bad til deim og tente deim, difor hev Herren late alt dette vonde koma yver deim.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Då no tjuge år var lidne, og Salomo hadde bygt dei tvo husi, Herrens hus og kongshuset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'og Hiram, kongen i Tyrus, hadde hjelpt Salomo med cedertre og cypresstre og alt det gull han ynskte, so gav kong Salomo Hiram tjuge byar i Galilæa-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Og Hiram tok ut ifrå Tyrus, og vilde sjå på dei byarne som Salomo hadde gjeve honom; men han lika deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Og han sagde: «Kva er dette for byar du hev gjeve meg, bror min?» Og han gav deim namnet Kabulslandet, som dei og hev heitt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Men Hiram sende kongen tri hundrad vågar gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Det hadde seg soleis med det arbeidsfolk som kong Salomo tok ut til byggjearbeidet med Herrens hus og sitt eige hus og Millo og muren kring Jerusalem og Hasor og Megiddo og Geser:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '- Farao, kongen i Egyptarland, hadde sett i veg og teke Gezer, og sett eld på det og drepe kananitarne som budde i byen og so gjeve honom i heimafylgje til dotter si, kona åt Salomo;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'men Salomo bygde upp att Gezer og Nedre Bet-Horon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'og Ba’alat og Tadmor i øydemarki der i landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'bygde og alle dei upplagsbyar Salomo hadde, og vognbyarne og hestbyarne og elles alt som Salomo fekk hug og lyst til å få bygt i Jerusalem og på Libanon og i heile kongeriket sitt -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Alt det folket som fanst att av amoritarne, hetitarne, perizitarne, hevitarne og jebusitarne, folk som ikkje var av Israels ætt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'sønerne deira, som var att etter deim i landet, med di Israels-sønerne ikkje hadde magta å fullføra bannstøyten imot deim, desse tok Salomo ut til pliktarbeid, og soleis hev det vore til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Men av Israels-sønerne gjorde Salomo ingen til træl; for dei var herfolk og tenarar og hovdingar og kjempor hjå honom og hovdingar for stridsvognerne og hestfolket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Talet på yverfutarne, som stod fyre arbeidet til Salomo, var fem hundrad og femti; dei rådde yver folket som gjorde arbeidet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Nettupp på den tid dotter åt Farao hadde flutt upp ifrå Davidsbyen til huset sitt, som han hadde bygt til henne, gav han seg til å byggja Millo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Tri gonger um året ofra Salomo brennoffer og takkoffer på det altaret han hadde bygt til Herren, og brende røykjelse ved alteret der framfor Herrens åsyn, og hadde no huset ferdigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Kong Salomo bygde og skip i Esjon-Geber; det ligg attmed Elot på Raudehavs-strandi i Edomlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Og Hiram sende sjøvant mannskap av sitt folk til skipi i lag med folket åt Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Dei for til Ofir og henta gull derifrå, eit tusund og femti våger, som dei førde til kong Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Då dronningi i Saba fekk høyra gjetordet um Salomo og det han hadde gjort for Herrens namn, kom ho og vilde røyna honom med djupe gåtor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Ho kom til Jerusalem med eit ovstort fylgje, med kamelar som var klyvja med kryddor og gull i store mengder og glimesteinar, og då ho var komi til Salomo, lagde ho fram for honom alt det ho hadde på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Men Salomo gav henne svar på alle spurningarne hennar. For honom var ingenting dult, som han ikkje kunde svara på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Då dronningi frå Saba såg all Salomos visdom og såg huset han hadde bygt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'og retterne på bordet hans, og korleis hirdmennerne hans sat der, og korleis tenarane hans varta upp og var klædde, og skjenkjarsveinarne hans og den uppgangen som han hadde til Herrens hus, då vart ho reint ifrå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Og ho sagde til kongen: «So var det då sant det ordet eg høyrde i landet mitt um deg og um visdomen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Eg kunde ikkje tru det dei sagde fyrr eg sjølv kom og fekk sjå det med mine eigne augo; ikkje helvti hev dei fortalt meg, det ser eg no; i visdom og vyrdnad gjeng du yver det gjetordet eg hev høyrt um deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Sæle er mennerne dine, sæle er desse tenarane dine, som stødt fær standa framfyre deg og høyra visdomen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Lova vere Herren, din Gud, som hadde hugnad i deg og sette deg på Israels kongsstol! For di Herren elskar Israel alle dagar, sette han deg til konge, so du kann skipa rett og rettferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'So gav ho kongen tri hundrad våger gull og kryddor i store mengder og glimesteinar; so stor mengd av kryddor som den dronningi frå Saba gav kong Salomo, hev aldri vorte innførd sidan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Då skipi til Hiram henta gull frå Ofir, tok dei og med almuggim-tre i stor mengd og dyre steinar frå Ofir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Av almuggim-treet fekk kongen tillaga handrid til Herrens hus og til huset åt kongen, og like eins cithrar og harpor til songarane; so mykje almuggim-tre hev aldri vore innført eller set sidan til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Og kong Salomo gav dronningi frå Saba alt det ho hadde hug på, og bad um, umfram det han gav henne i samhøve med Salomos kongelege vyrdnad. So snudde ho heim att til sitt land, ho sjølv og tenarane hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Det gullet som kom inn til Salomo på eit år, vog sekstan hundrad og seks og seksti våger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'og då var ikkje medrekna det som kom inn frå kjøpmennerne og av kræmarhandelen og frå alle kongarne i Arabia og frå jarlarne i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Og kong Salomo let gjera tvo hundrad store skjoldar av uthamra gull - seks hundrad lodd gull gjekk med til kvar skjold -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'og tri hundrad små skjoldar av uthamra gull - eit hundrad og åtteti lodd gull gjekk med til kvar skjold - og kongen sette deim upp i Libanonskoghuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Kongen let og gjera ein stor kongsstol av flisbein og klædde honom med skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Kongsstolen hadde seks stig, og ryggstydi på kongsstolen var avrunda ovantil; på båe sidor av sætet var der armar, og attmed armarne stod tvo løvor;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'og tolv løvor stod det på dei seks stigi, på båe sidor. Maken til dette var ikkje laga i noko kongerike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Alle drykkjestaupi åt kong Salomo var av gull, og alle gognerne i Libanonskoghuset var og av skirt gull; sylv fanst det ikkje; det var ikkje rekna for noko i Salomos dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'For kongen hadde sine Tarsis-skip på havet attåt floten til Hiram. Ein gong tridje kvart år kom Tarsis-skipi heim og hadde med seg gull og sylv, og filsbein og apor og påfuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Kong Salomo vart større enn alle kongar på jordi i rikdom og visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Folk frå alle land vitja Salomo og vilde høyra visdomen hans, som Gud hadde lagt i hjarta hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Og då hadde kvar og ein av desse med seg gåvor: ymse ting av sylv og gull, klæde og våpn, kryddor, hestar og muldyr. Soleis gjekk det år etter år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomo samla stridsvogner og hestfolk, so han hadde fjortan hundrad stridsvogner og tolv tusund hestfolk; og deim gav han læger i vognbyarne og i Jerusalem hjå kongen sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Og kongen gjorde sylvet i Jerusalem so vanleg som stein og cedertre som morberfiketre i låglandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Og hestarne som Salomo fekk seg, førde han inn frå Egyptarland; ein flokk kjøpmenner hjå kongen henta ei viss mengd til ein fastsett pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Kvar vogn som vart henta upp og utførd frå Egyptarland, kosta seks hundrad lodd sylv, og kvar hest eit hundrad og femti. På same vis vart dei, med deira hjelp, utførde til alle kongarne hjå hetitarne og i Syria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Kong Salomo hadde mange utlendske kvinnor som han elska - umfram dotter åt Farao; moabitiske, ammonitiske, edomitiske, sidoniske, hetitiske,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'kvinnor av dei heidningfolki som Herren hadde åtvara Israels-sønerne imot og sagt: «De skal ikkje hava noko med deim, og ikkje dei med dykk; elles kjem dei visseleg til å snu hjarta dykkar til sine gudar.» Salomo heldt seg til desse i elsk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Han hadde sju hundrad konor av fyrsteætt og tri hundrad fylgjekonor, og konorne vende hjarta hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Ja, då Salomo vart gamall, drog dei hjarta hans til andre gudar, so hjarta hans var ikkje heilt med Herren hans Gud, soleis som hjarta åt David, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Og Salomo fylgde Astarte, sidoniarguden, og Milkom, styggedomen åt ammonitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Soleis gjorde Salomo det som var vondt i Herrens augo, og fylgde ikkje Herren i eit og alt som David, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Salomo bygde då ein offerhaug på berget austanfor Jerusalem åt Kamos, styggedomen åt Moab, og for Molek, styggedomen åt Ammons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Og det same gjorde han for alle dei utlendske konorne sine, so dei fekk brenna røykjelse og ofra til gudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Då vart Herren harm på Salomo, for di han hadde vendt hjarta sitt burt ifrå Herren, Israels Gud, som hadde openberra seg for honom tvo gonger');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'og gjeve honom eit serskilt bod um dette, at han ikkje skulde fylgja andre gudar; men han hadde ikkje agta på Herrens bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Difor sagde Herren til Salomo: «Etter di du er komen på dette, og ikkje hev halde pakti mi og loverne mine, som eg hev gjeve deg, vil eg riva riket ifrå deg og gjeva det til tenaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Men for David, far din, skuld vil eg ikkje gjera dette i di tid; eg riv det or handi på son din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Heile riket vil eg like vel ikkje riva ifrå honom. Eitt fylke vil eg gjeva son din for David, far din, skuld og for Jerusalem skuld, som eg hev valt ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Og Herren vekte upp ein motmann imot Salomo; edomiten Hadad; han var av kongsætti i Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Då David var i Edom, og herhovdingen Joab for upp og skulde gravleggja dei falne og med det same slo i hel alt som mann var i Edom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '- for Joab og heile Israel vart verande der i seks månader, til dess han hadde rudt ut alt som mann var i Edom -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'då rømde denne Hadad, han sjølv og nokre edomitiske menner, som hadde vore i tenesta hjå far hans, og tok vegen til Egyptarland. Hadad var den gong ein liten gut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Og dei drog ut frå Midjan og kom til Paran; frå Paran tok dei med seg nokre menner og kom til Egyptarland til Farao, egyptarkongen; han gav honom eit hus og rettleide honom med upphald og let honom få jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad fann stor godvilje hjå Farao, so han gav honom til kona syster åt kona si, syster åt dronning Tahpenes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Og denne syster åt Tahpenes fødde sonen Genubat åt honom; Tahpenes vande honom av i huset åt Farao, og Genubat vart verande i huset der med sønerne åt Farao.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Men då Hadad høyrde i Egyptarland, at David hadde lagt seg til kvile hjå federne sine, og at Joab, stridshovdingen, var avliden, so sagde Hadad til Farao: «Slepp meg no, so eg kann fara heim til landet mitt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Farao sagde til honom: «Kva saknar du her hjå meg, sidan du vil fara heim til landet ditt?» Han svara: «Ingen ting; men du må plent lata meg fara.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Gud vekte upp ein motmann til imot Salomo: Rezon Eljadason; han var rømd ifrå herren sin, Hadadezer, kongen i Soba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Der samla han ein flokk um seg, den gong David slo folket i hel, og vart røvarhovding; dei drog av til Damaskus, slo seg ned der og styrde i Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Han vart ein motmann imot Israel so lenge Salomo livde, og skadde det, både han og Hadad; han hata Israel og vart konge yver Syria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Ein av mennerne åt Salomo heitte Jerobeam; han var son åt Nebat, ein efraimit frå Sereda; mor hans heitte Serua og var enkja. Og han gjorde uppreist mot kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Grunnen til at han lyfte hand imot kongen, var dette: Salomo bygde Millo og sette stengsla for opningi til byen åt David, far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'No var Jerobeam ein dugande kar, og då Salomo såg at han var drivande i arbeidet sitt, sette han honom til tilsynsmann yver alt arbeidet som Josefs hus hadde på seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'So hende det ein gong ved det leitet, at Jerobeam var gjengen ut or Jerusalem, og at profeten Ahia frå Silo råka honom på vegen. Han hadde på seg ei ny kåpa, og dei var tvo-eine på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Då tok Ahia den nye kåpa han hadde på seg, og reiv henne i tolv stykke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Og han sagde til Jerobeam: «Tak deg ti stykke! For so segjer Herren, Israels Gud: «Sjå, eg vil riva riket ut or handi på Salomo og gjeva deg ti av ætterne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'men den eine ætti skal han få hava for David skuld, tenaren min, og for Jerusalem skuld, den byen eg hev valt millom alle Israels fylke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Det skal ganga so, for di dei hev vike ifrå meg og bede til Astarte, sidonarguden, til Kamos, Moabs-guden, og til Milkom, ammonitarguden, og ikkje gjenge mine vegar, ikkje gjort det som rett er i mine augo, eller halde loverne mine og bodi mine, soleis som David, far hans, gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Eg vil like vel ikkje taka noko av riket ifrå honom sjølv, men lata honom vera fyrste so lenge han liver, for David skuld, tenaren min, han som eg valde ut, og som agta på bodi og loverne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Men ifrå son hans vil eg taka riket, og gjeva deg det, dei ti ætterne, meiner eg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'son hans vil eg gjeva ein av ætterne, so tenaren min, David, alle dagar må hava ei lampa framfor mi åsyn i Jerusalem, den byen som eg hev valt meg ut til bustad for namnet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Deg vil eg då kåra, du skal råda yver alt du hev hug til, og vera konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Og lyder du alt som eg byd deg, og gjeng mine vegar og gjer det som rett er i mine augo, so du held loverne mine og bodi mine, soleis som David, tenaren min, gjorde, so vil eg vera med deg og byggja deg eit hus som stend fast, soleis som eg bygde for David, og gjeva deg Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Og Davids ætt vil eg mykja for dette, men like vel ikkje for alltid.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomo freista å taka livet av Jerobeam; men Jerobeam reis upp og rømde undan til Egyptarland til egyptarkongen Sisak, og han vart verande i Egyptarland til Salomo døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Det som elles er å fortelja um Salomo og alt det han gjorde, og um visdomen hans, det er uppskrive i krønikeboki åt Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Den tid Salomo var konge i Jerusalem yver heile Israel, var fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'So lagde Salomo seg til kvile hjå federne sine og vart gravlagd i byen åt David, far sin, og Rehabeam, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Og Rehabeam for til Sikem; for heile Israels var kome til Sikem og vilde taka honom til konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Men då Jerobeam Nebatsson frette det - han var endå i Egyptarland; han hadde rømt dit for kong Salomo, og Jerobeam budde soleis i Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'og dei sende bod dit og bad honom heim att - då kom Jerobeam og heile Israels-lyden og tala med Rehabeam og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '«Far din lagde på oss eit hardt ok; men vil du no letta på harde strævet og det tunge oket som far din lagde på oss, so vil me tena deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Han svara deim: «Gakk burt og bia tri dagar og kom so til meg att!» Og folket gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Då rådførde kong Rehabeam seg med dei gamle, som hadde vore i tenesta hjå Salomo, far hans, medan han livde, og spurde deim: «Kva svar råder de meg til å gjeva dette folket?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Dei svara honom og sagde: «Bøygjer du deg for dette folket i dag og er deim til tenesta og gjev deim gode ord til svar, so vil dei verta tenarane dine alle dagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Men han brydde seg ikkje um den rådi som dei gamle gav honom; men rådførde seg med dei unge, som var uppvaksne upp i lag med honom og no stod i hans tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Han sagde til deim: «Kva råder de meg til å svara dette folket som hev tala til meg og sagt: «Lat det oket som far din hev lagt på oss verta lettare?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Dei unge kararne som var uppvaksne i lag med honom, svara honom då og sagde: «So skal du segja til dette folket som hev tala til deg og sagt: «Far din lagde eit tungt ok på oss, men gjer no du det lettare for oss!» - So skal du segja til deim: Litlefingeren min er tjukkare enn mjødmane åt far min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Hev difor far min lagt eit tungt ok på dykk, so skal eg gjera oket dykkar endå tyngre; hev far min tukta dykk med svipor, so skal eg skal tukta dykk med skorpionar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'So kom Jerobeam og heile folket til Rehabeam tridje dagen, so som kongen hadde sagt: «Kom hit til meg att tridje dagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Då gav kongen folket eit hardt svar; for han brydde seg ikkje um den rådi dei gamle hadde gjeve honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Etter rådi åt dei unge kararne sagde han til deim: «Hev far min lagt eit tungt ok på dykk, so skal eg gjera oket dykkar endå tyngre. Hev far min tukta dykk med svipor, so skal eg tukta dykk med skorpionar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Kongen høyrde soleis ikkje på folket, for di Herren laga det soleis, so det ordet skulde sannast som Herren hadde tala til Jerobeam Nebatsson ved siloniten Ahia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Då no heile Israel såg at kongen ikkje høyrde på deim, gav folket dette svaret: «Kva deil hev me i David? Ingen lut i Isaisonen! Heim til hyttorne, Israel! Sjå no sjølv til huset ditt, David!» So for Israel heim kvar til sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Berre yver dei Israels-borni som budde i byarne i Juda, vart Rehabeam konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Og då kong Rehabeam sende i veg Adoram som hadde øvste tilsynet med pliktarbeidet, so steina heile Israel honom i hel. Då skunda kong Rehabeam seg upp i vogni si og rømde til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'So reiv då Israel seg laus ifrå Davids hus, og soleis hev det vore til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Men då heile Israel frette at Jerobeam var komen att, sende dei bod og bad honom til tings og kåra honom til konge yver heile Israel; det var ingen som heldt fast på Davids hus, so nær som Juda-ætti åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Då Rehabeam kom til Jerusalem, samla han heile Judas hus og Benjamins-ætti, hundrad og åtteti tusund utvalde stridsmenner, og vilde strida imot Israels hus og vinna kongedømet att for Rehabeam Salomoson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Men då kom Guds ord til gudsmannen Semaja soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '«Seg til Rehabeam Salomoson, kongen i Juda, og til heile Judas og Benjamins hus og til resten av folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'So segjer Herren: «De skal ikkje fara upp og strida mot brørne dykkar, Israels-sønerne. Snu heim att, kvar til sitt hus! For det som hev hendt, er kome frå meg.»» Då lydde dei Herrens ord og snudde og gjekk sin veg, som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jerobeam bygde upp Sikem på Efraimsfjellet og busette seg der. Derifrå tok han ut og bygde upp Penuel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Og Jerobeam sagde med seg sjølv: «Riket kann snart ganga attende til Davids hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Dersom dette folket fær fara upp til Herrens hus i Jerusalem og ofra, so kann folkehugen venda attende til hovdingen deira, Rehabeam, kongen i Juda; ja då drep dei gjerne meg og vender attende til Rehabeam, kongen i Juda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Og då kongen hadde tenkt yver dette, laga han tvo gullkalvar, og han sagde til folket: «No lyt de vera nok med ferder upp til Jerusalem. Sjå her er guden din, Israel som førde deg upp or Egyptarlandet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Og han sette upp den eine i Betel, den andre sette han i Dan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Dette vart orsak til synd; folket gjekk radt til Dan og steig fram for den eine av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Og han bygde hus på offerhaugarne og sette til prestar likt og ulikt, folk som ikkje var av Levi-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Og Jerobeam skipa til ei høgtid i den åttande månaden, på den femtande dagen i månaden, i likskap med høgtidi i Juda, og han ofra på altaret. So gjorde han i Betel, med di han ofra til kalvarne som han hadde laga, og dei som han hadde sett til offerhaug-prestar, let han gjera tenesta i Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Og han ofra på det altaret han hadde laga i Betel, den femtande dagen i åttande månaden, den månaden som han hadde valt ut etter sitt eige hovud. Han skipa då til ei høgtid for Israels-borni og steig upp til altaret og vilde kveikja offereld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Men nettupp då Jerobeam stod ved altaret og vilde kveikja offereld, kom det på Herrens bod ein gudsmann frå Juda til Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Og etter Herrens fyresegn ropa han imot altaret og sagde: «Altar, altar! So segjer Herren: «Ein son skal verta fødd åt Davids hus; Josia skal han heita, på deg skal han ofra offerhaug-prestarne som kveikjer offereld på deg; mannebein skal dei då brenna på deg.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Same gongen nemnde han eit teikn og sagde: «Dette er teiknet på at Herren hev tala: Sjå, altaret skal rivna, og oska som er på det, skal renna utyver.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Då kong Jerobeam høyrde det som gudsmannen ropa imot altaret i Betel, rette han ut handi frå altaret og sagde: «Tak honom!» Men handi som han hadde rett ut imot honom visna, og han kunde ikkje taka henne til seg att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Og altaret rivna, og oska rann ut frå altaret; det var teiknet som gudsmannen hadde nemnt, etter Herrens bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Då svara kongen og sagde til gudsmannen: «Vil du naudbeda Herren, din Gud, at eg må kunna taka handi til meg att?» Og gudsmannen naudbad Herren, og kongen kunde då taka handi til seg att, og ho vart som ho hadde vore fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Då sagde kongen til gudsmannen: «Kom heim med meg og styrk deg, og lat meg få gjeva deg ei gåva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Men gudsmannen sagde til kongen: «Um du gav meg helti av huset ditt, vilde eg ikkje ganga inn med deg like vel; her vil eg korkje eta eller drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'For det bodet eg fekk av Herren: «Du skal ikkje eta brød og ikkje drikka vatn, og ikkje skal du fara den same vegen attende som du gjekk av stad.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Og so for han av ei annan veg og vende ikkje heim att den vegen han var komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Men i Betel budde ein gamall profet, og son hans kom og fortalde honom alt det gudsmannen hadde gjort i Betel den dagen, og kva han hadde sagt til kongen. Og då dei hadde fortalt dette til far sin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'sagde far deira til deim: «Kva veg gjekk han?» Sønerne hadde set kva veg gudsmannen hadde fare, han som var komen frå Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Då sagde han til sønerne sine: «Sala asnet åt meg!» Då dei so hadde sala asnet åt honom, sette han seg på det');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'og tok ut etter gudsmannen og fann honom; han under eiki; og han spurde honom: «Er du den gudsmannen som er komen frå Juda?» Han svara: «Ja, det er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Då sagde han til honom: «Fylg meg heim, og et med meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Men han svara: «Eg kann ikkje ganga attende med deg eller stiga innum hjå deg, og eg kann korkje eta eller drikka med deg her;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'for det kom eit ord til meg frå Herren: «Du skal korkje eta eller drikka der; du skal ikkje heller fara attende same vegen som du gjekk dit.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Han sagde til honom: «Eg og er profet liksom du, og ein engel hev tala til meg på Herrens bod og sagt: «Få honom attende med deg og gjev honom mat og drikka!»» Men det laug han for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'So snudde han um att med honom og åt i huset hans og drakk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Men medan dei sat ved bordet, kom Herrens ord til profeten som hadde fenge honom attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Og han ropa til gudsmannen som var komen frå Juda, og sagde: «So segjer Herren: «For di du hev vore motstridig mot Herrens ord og ikkje lydt det bodet som Herren, din Gud, gav deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'men snudde um att og ete og drukke på den staden der han hadde forbode deg å gjera det, so skal liket ditt ikkje koma i fedregravi di.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Då han no hadde ete og drukke, sala han asnet åt honom, åt profeten, som han hadde fenge attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Og han tok i veg, men ei løva råka honom på vegen og drap honom. Sidan låg liket hans slengt på vegen; men asnet gav seg til å standa attmed det, og løva stod like eins attmed liket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Då no folk som gjekk framum der, fekk sjå liket hans slengt på vegen, og løva standande attmed det, gjekk dei inn i byen der den gamle profeten budde, og tala um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Då profeten som hadde fenge honom attende frå vegen, høyrde det, sagde han: «Det er gudsmannen som var motstridig imot Herrens ord; difor hev Herren gjeve honom løva i vald, og ho hev rive honom sund og drepe honom, etter det ord som Herren hadde tala til honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Og han sagde til sønerne sine: «Legg sal på asnet åt meg!» Og dei sala det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'So tok han ut og fann liket liggjande slengt på vegen, og løva og asnet standane attmed liket; løva hadde ikkje ete av liket og ikkje rive sund asnet heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Og profeten tok upp liket av gudsmannen og lagde honom på asnet og tok honom med seg attende; og den gamle profeten gjekk inn i byen sin og vilde halda syrgjehøgtid og gravleggja honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Og han lagde liket hans i si eigi grav, og dei heldt syrgjehøgtid og ropa: «Eie, eie meg, bror min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Då han no hadde gravlagt honom, sagde han til sønerne sine: «Når eg døyr, skal de leggja meg i den gravi som gudsmannen ligg i; legg beini mine attmed hans bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'For det skal sanna seg, det som han, etter Herrens ord, sagde imot altaret i Betel og imot alle offerhaughusi i byarne i Samaria.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Jerobeam vende like vel ikkje um ifrå sin vonde veg etter denne hendingi, men heldt fram med å gjera til prestar ved offerhaugarne både likt og ulikt. Den som berre hadde hug til det, fekk av honom handi fyllt, so dei kunde verta prestar ved haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'På denne vis vart Jerobeam upphavsmann til synd i ætti si og orsak til at huset hans vart utrudt og utstroke av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Ved det bilet vart Abia, son åt Jerobeam, sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Då sagde Jerobeam til kona si: «Tak og klæd deg ut, so ingen vert vis med at du er kona åt Jerobeam, og gakk so til Silo! Der bur profeten Ahia, han som tala um at eg skulde verta konge yver dette folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Tak med deg ti brød og kakor og ei krukka med honning og gakk inn til honom! Han skal vitra deg um korleis det skal ganga med guten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Og kona åt Jerobeam gjorde so; ho tok ut til Silo og kom til huset åt Ahia. Men Ahia kunde ikkje sjå; for augo hans var star-blinde av alderdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Men Herren hadde sagt til Ahia: «Kona åt Jerobeam kjem og vil spyrja deg ut um son sin, for han er sjuk. Det og det skal du segja med henne. Når ho kjem, vil ho bera seg åt liksom ho var framand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Då no Ahia høyrde fotstigi hennar i det same ho kom inn døri, sagde han: «Kom inn, du kona åt Jerobeam! Kvi ber du deg åt liksom du var framand? Eg er send til deg med eit hardt bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Gakk og seg til Jerobeam: «So segjer Herren, Israels Gud: «Eg hev lyft deg upp or folket og sett deg til fyrste yver folket mitt, Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'og rive riket ifrå Davids hus og gav det til deg. Men du hev ikkje stelt deg som tenaren min, David; han heldt bodi mine og fylgde meg av alt sitt hjarta, so han gjorde einast det som rett var i mine augo;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'men du hev gjort meir vondt enn alle som hev vore fyre deg; du hev gjenge av og laga deg andre gudar, støypte bilæte, for å harma meg, og meg hev du kasta attum ryggen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Difor vil eg lata ulukka koma yver Jerobeams hus og rydja ut kvar ein karmann av ætti hans både, både ufri og fri i Israel, og eg skal sopa etter Jerobeams hus plent som ein sopar burt skarn, til dess det ingen ting er att av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Den av Jerobeams hus som døyr i byen, skal hundarne eta upp, og den som døyr utpå marki, skal fuglane under himmelen eta upp. For soleis hev Herren tala.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Gakk no du heim att! Når føterne stig inn i byen, so døyr barnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Og heile Israel skal halda syrgjehøgtid for honom, og dei skal gravleggja honom; for av Jerobeams hus er han den einaste som skal koma i ei grav, etter di han var den einaste i Jerobeams hus som det var noko godt hjå imot Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Men Herren skal setja seg ein konge yver Israel, som skal rydja ut Jerobeams hus. Dette er dagen, og no skal det henda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Herren skal slå Israel som sevet voggar i vatnet, og han skal rykkja Israel upp or dette gode landet, som han gav federne deira, og strøya deim på andre sida åt Storelvi, for di dei hev laga seg asjeror og vekt Herrens harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Og han skal ofra Israel for dei synder skuld som Jerobeam gjorde, og som han fekk Israel til å gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Då reis kona åt Jerobeam upp og gjekk sin veg og kom til Tirsa, og med same ho steig yver dørstokken i huset, døydde guten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Og dei gravlagde honom, og heile Israel heldt syrgjehøgtid for honom, etter det ord som Herren hadde tala ved tenaren sin, profeten Ahia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Det som elles er å fortelja um Jerobeam, um krigerne hans og styringi hans, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Styringstidi åt Jerobeam var tvo og tjuge år. So lagde han seg til kvile hjå federne sine, og Nadab, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Men Rehabeam, son åt Salomo, var konge i Juda; ein og fyrti år var Rehabeam då han vart konge, og syttan år styrde han i Jerusalem, den byen som Herren hadde valt ut av alle Israels ætter til bustad for namnet sitt. Mor hans var ei ammonitkvinna som heitte Na’ama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Og Juda gjorde det som vondt var i Herrens augo; med dei synder dei gjorde, vekte dei brennhugen hans meir enn federne deira hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Dei og bygde seg offerhaugar og laga til stolpar og asjeror på kvar ein høg bakke og under kvart eit grønt tre;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'ja, det var jamvel utukt-sveinar i landet. Dei heldt på med all styggedomen hjå dei folki som Herren hadde jaga undan for Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'I femte styringsåret åt Rehabeam drog egyptarkongen Sisak upp imot Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Og han tok skattarne i Herrens hus og skattarne i kongshuset; alt saman tok han. Han tok alle gullskjoldarne og, som Salomo hadde late gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'I deira stad fekk kong Rehabeam gjort koparskjoldar og gav deim i varveitsla til hovdingarne for livvakti, dei som heldt vakt ved inngangen til kongshuset;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'og kvar gong kongen gjekk til Herrens hus, bar vaktmennerne deim og tok deim so attende til vaktstova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Det som elles er å fortelja um Rehabeam, um alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Millom Rehabeam og Jerobeam var det ufred stødt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Og Rehabeam lagde seg til kvile hjå federne sine, og vart gravlagd hjå federne sine i Davidsbyen. Mor hans heitte Na’ama, ammonitkvinna. Og Abiam, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'I det attande styringsåret åt Jerobeam Nebatsson vart Abiam konge yver Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tri år styrde han i Jerusalem; mor hans heitte Ma’aka Abisalomsdotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Og han fylgde far sin i alle dei syndar som han hadde gjort fyre honom, og hjarta hans var ikkje heilt med Herren, hans Gud, som hjarta åt David, far hans, hadde vore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Men for David skuld gav Herren, hans Gud, honom ei lampa i Jerusalem, med di han lyfta upp son hans etter honom og let Jerusalem få standa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'for di David hadde gjort det som rett var i Herrens augo og ikkje vike ifrå noko av det han hadde bode honom, so lenge han livde, so nær som i saki med hetiten Uria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Millom Rehabeam og Jerobeam var det ufred so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Det som elles er å fortelja um Abiam og um alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne. Abiam og Jerobeam låg i ufred med kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Og Abiam lagde seg til kvila hjå federne sine, og dei gravlagde honom i Davidsbyen; og Asa, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'I tjugande året åt Jerobeam, kongen i Israel, vart Asa konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Han styrde eitt og fyrti år i Jerusalem. Hans mor heitte Ma’aka Abisalomsdotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Og Asa gjorde det som rett var i Herrens augo, liksom David, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Han jaga utukt-sveinarne ut or landet, og fekk burt alle dei skarnsgudarne som far hans hadde laga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Og jamvel mor si, Ma’aka, sette han ifrå hennar dronningrang, for di ho hadde late gjera eit styggjelegt bilæte for Asjera; Asa hogg ned det stygge bilætet hennar og brende det i Kidronsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Men offerhaugarne fekk dei ikkje burt; like vel var hjarta åt Asa heilt med Herren, so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Heilaggåvorne åt far sin og heilaggåvorne sine eigne flutte han inn i Herrens hus, sylv og gull og ymse ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Millom Asa og Basea, kongen i Israel, var det ufred so lenge dei livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Basea, Israels-kongen, drog upp imot Juda og bygde ei borg i Rama, av di han vilde hindra at nokon drog ut eller inn hjå Asa, kongen i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Då tok Asa alt det sylv og gull som var att i skattkammeri i Herrens hus og i skattkammeret i kongsgarden og lagde det i handi åt tenarane sine; so sende han dei til Benhadad, son åt Tabrimmon Hezjonsson, syrarkongen, som budde i Damaskus, med dei ordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '«Det er eit samband millom meg og deg, sameleis som millom far min og far din. Her sender eg deg ei gåva i sylv og gull. Gjer no vel og brjot sambandet ditt med Basea, Israels-kongen, so han lyt draga burt ifrå meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Og Benhadad lydde kong Asa og sende herførarane sine imot byarne i Israel og herja Ijon, Dan, Abel-Bet-Ma’aka og heile Kinnerot umfram heile Naftalilandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Då Basea no høyrde det, slutta han med borgbyggjingi i Rama og heldt seg sidan i ro i Tirsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Men kong Asa baud ut heile Juda - ikkje ein var friteken - og dei tok burt steinar og trevyrke som Basea hadde bruka til byggverket i Rama; og med det gjorde no kong Asa Geba i Benjamin og Mispa til borgbyar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Det som elles er å fortelja um Asa, um alle storverki hans og alt han gjorde, um byarne som han bygde, det er uppskrive i krønikeboki åt Juda-kongarne. Men på sine gamle dagar fekk han ein sjukdom i føterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Og Asa lagde seg til kvile hjå federne sine og vart gravlagd hjå federne sine i byen åt David, far sin. Og Josafat, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab Jerobeamsson vart konge i Israel i det andre styringsåret åt Juda-kongen Asa og rådde yver Israel i tvo år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Han gjorde det som vondt var i Herrens augo og stemnde fram på vegen til far sin og i den synd som han hadde fenge Israel til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Men Basea Ahiason av Issakars hus fekk til ei samansverjing imot honom, og Basea slo honom i hel ved Gibbeton, som høyrde filistarane til; Nadab med heile Israel heldt då på å kringsette Gibbeton.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Basea drap honom i det tridje styringsåret åt Juda-kongen Asa, og han vart so konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Og då han var konge vorten, slo han i hel heile Jerobeams hus; han let det ikkje vera att ei livande sjæl av Jerobeams hus, men gjorde ende på, etter det ord som Herren hadde tala ved tenaren sin, siloniten Ahia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'det var for dei synder skuld som Jerobeam hadde gjort, og som han hadde fenge Israel til å gjera, og for di han soleis hadde harma Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Det som elles er å fortelja um Nadab og um alt det han gjorde, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Millom Asa og Basea, kongen i Israel, var det ufred so lenge dei livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'I det tridje styringsåret åt Juda-kongen Asa vart Basea Ahiason konge yver heile Israel i Tirsa, og det var han i fire og tjuge år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Han gjorde det som vondt var i Herrens augo, og stemnde fram på Jerobeams veg og i den synd som han hadde fenge Israel til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Og Herrens ord kom til Jehu Hananison um Baesa, soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '«Eg hev lyft deg upp or moldi og sett deg til hovding yver Israel, folket mitt. Men du hev fare der Jerobeam for, og fenge Israel, folket mitt, til å synda, so dei hev harma meg med synderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Difor vil eg sopa etter Baesa og huset hans; eg vil gjera med ditt hus som eg gjorde med huset åt Jerobeam Nebatsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Den av huset åt Baesa som døyr i byen, skal hundarne eta upp, og den av huset hans som døyr utpå marki, skal fuglarne under himmelen eta upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Det som elles er å fortelja um Baesa og um det han gjorde, um storverki hans, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Og Baesa lagde seg til kvile hjå federne sine og vart gravlagd i Tirsa, og Ela, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Men gjenom profeten Jehu Hananison var Herrens ord kome til Baesa og huset hans både for alt det han gjorde som Herren mislika, då han harma honom med det som henderne hans gjorde i likskap med Jerobeams hus, og for det at han hadde slege dette i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'I det seks og tjugande året åt Juda-kongen Asa vart Ela Baesason konge yver Israel i Tirsa, og det var han i tvo år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Då fekk ein av tenarane hans, Zimri, hovdingen for helvti av vognerne, til ei samansverjing imot honom, og ein gong han hadde teke seg eit rus i Tirsa, i huset åt Arsa, drottseten i Tirsa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'kom Zimri dit og slo han i hel - det var i sju og tjugande året åt Juda-kongen Asa - og so vart han sjølv konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Og då han hadde vorte konge og var komen på kongsstolen sin, tynte han heile huset åt Baesa; han let det ikkje vera att nokon karmann, men drap jamvel skyldfolk og vener til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'So rudde Zimri ut heile huset åt Baesa, etter det ord som Herren hadde tala til Baesa gjenom profeten Jehu,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'for alle dei synder skuld som Baesa og Ela, son hans, hadde gjort, og som dei hadde fenge Israel til å gjera, so dei harma Herren, Israels Gud, med dei fånyttige avgudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Det som elles er å fortelja um Ela og alt det han gjorde, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'I det sju og tjugande året åt Juda-kongen Asa vart Zimri konge i sju dagar i Tirsa, den gongen folket kringsette Gibbeton, som tilhøyrde filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Då folket som låg i lægret, høyrde at Zimri hadde fenge til ei samansverjing og jamvel slege kongen i hel, gjorde heile Israel den israelitiske herføraren Omri til konge i lægret same dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Og Omri tok upp ifrå Gibbeton og heile Israel med honom, og dei kringsette Tirsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Og då Zimri såg at byen var teken, gjekk han inn i borgi i kongsgarden og sette eld på kongsgarden yver seg og døydde soleis,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'for dei synder han hadde gjort, med di han gjorde det som vondt var i Herrens augo og stemnde fram på Jerobeams veg og i den synd som han hadde gjort og fenge Israel til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Det som elles er å fortelja um Zimri og um den samansverjingi som han fekk til, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'No kløydest Israels-folket seg i tvo flokkar; den eine helvti av folket heldt med Tibni Ginatsson og gjorde honom til konge, men den andre helvti heldt seg til Omri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Og den flokken som heldt med Omri, vart for sterk for deim som heldt med Tibni Ginatsson, og då Tibni døydde, vart Omri konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'I det eitt og trettiande året åt Juda-kongen Asa vart Omri konge i Israel, og det var han i tolv år. I Tirsa styrde han i seks år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Han kjøpte berget Samaria av Semer for fem våger sylv, og han bygde på berget og kalla byen som han bygde der Samaria, etter Semer, som hadde ått berget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Men Omri gjorde det som vondt var i Herrens augo; ja, han bar seg verre åt enn alle som hadde vore fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Han fylgde Jerobeam Nebatsson etter på alle hans vegar og i alle dei synder som han hadde fenge Israel til å gjera, so dei harma Herren, Israels Gud, med sine fånyttige avgudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Det som elles er å fortelja um Omri, um det han gjorde og um storverki hans, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Og Omri lagde seg til kvile hjå federne sine og vart gravlagd i Samaria, og Ahab, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Ahab Omrison vart konge yver Israel i det åtte og trettiande året åt Juda-kongen Asa, og Ahab Omrison styrde Israel tvo og tjuge år i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Ahab Omrison gjorde det som vondt var i Herrens augo, meir enn alle som hadde vore fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Det var ikkje nok for honom at han livde i synderne til Jerobeam Nebatsson, men han tok jamvel og gifte seg med Jezabel, dotter åt sidonarkongen Etba’al, og gjekk so av stad og tente Ba’al og tilbad honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Og han reiste eit altar for Ba’al i det Ba’als-huset som han hadde bygt i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ahab fekk ei Asjera tillaga og gjorde meir til å harma Herren, Israels Gud, enn alle Israels-kongarne som hadde vore fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'I hans tid bygde beteliten Hiel upp att Jeriko. Men det kosta honom eldste son hans, Abiram, å leggja grunnen; og det kosta honom yngste son hans, Segub, å setja upp portarne, etter det ord Herren hadde tala gjenom Josva Nunsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Og Elia frå Tisbe, ein av deim som hadde flutt inn ifrå Gilead, sagde til Ahab: «So sant Herren, Israels Gud, liver, han som eg er i tenesta hjå, so skal det ikkje koma regn eller dogg i desse åri utan eg segjer det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Og Herrens ord kom til honom soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '«Gakk herifrå og tak austetter og gøym deg attmed bekken Kerit på hi sida Jordan!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Av bekken skal du drikka, og føda til deg hev eg bode ramnarne syte for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Då tok han ut og gjorde som Herren hadde sagt; han gjekk av stad og vart verande attmed bekken Kerit, som er austanfor Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Og ramnarne bar brød og kjøt til honom um morgonen og brød og kjøt um kvelden, og av bekken drakk han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Men då ei tid var lidi, torna bekken, for det kom ikkje regn i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Då kom Herrens ord til honom; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '«Set i veg til Sarefat, som høyrer til Sidon, og gjev deg til der! Eg hev bede ei enkja syta for deg med føda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Han tok i veg til Sarefat, og då han kom til byporten, fekk han auga på ei enkja som sanka ved. Og han ropa til: «Henta ein liten grand vatn åt meg i ei skål, so eg fær drikka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Då ho no gjekk og skulde henta det, ropa han etter henne, og sagde: «Tak med deg eit stykke brød åt meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Men ho svara: So sant Herren, din Gud, liver; eg eig ikkje ein brødleiv; ein neve mjøl i krukka og ein grand olje i krusi er det einaste; og no sankar eg saman eit par vedkjeppar og gjeng inn og lagar det til åt meg og son min; so fær me eta det og sidan døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Då sagde Elia til henne: «Ottast ikkje, gakk inn og gjer som du hev sagt! Men laga fyrst ei liti kaka åt meg og ber ut åt meg! Sidan kann du få laga til åt deg sjølv og son din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'For so segjer Herren, Israels Gud: «Mjølkrukka skal ikkje verta tom, og ikkje skal det skorta på olje i krusi, til dess Herren let det regna på jordi.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Då gjekk ho av stad og gjorde som Elia hadde sagt; og dei åt, både han og ho og husfolket hennar, ei heil tid frametter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Mjølkrukka vart ikkje tom, og det skorta ikkje på olje i krusi; det gjekk som Herren hadde tala gjenom Elia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Men ei tid etter desse hendingarne vart son åt kvinna, ho som åtte huset, sjuk; og sjukdomen hans vart ovleg tung, og til slutt andast han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Då sagde ho til Elia: «Kva hev du, gudsmann, å gjera hjå meg? Du er komen til meg for å draga synda mi fram i minnet, so son min måtte døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Men han sagde til henne: «Lat meg få guten din hit.» Og han tok honom or fanget hennar og bar honom upp på salen der han budde, og lagde honom på sengi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Og han ropa til Herren og sagde: «Herre, min Gud! At du kunde senda slik ulukka yver denne enkja som gjev meg herbyrge, og late son hennar døy!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Og han lutte seg burtyver barnet tri gongar og ropa til Herren og sagde: «Herre, min Gud! Lat sjæli til guten koma attende til honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Og Herren høyrde Elia; guten fekk sjæli attende og vart livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Og Elia tok barnet ifrå salen og hadde det nedatt i huset og gav det til mori, og Elia sagde: «Sjå, son din liver!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Då sagde kvinna til Elia: «No veit eg at du er ein gudsmann, og at Herrens ord i din munn er sanning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Ei lang tid deretter, det var tridje året, kom Herrens ord til Elia, soleis: «Gakk av stad og stig fram for Ahab, so skal eg sidan lata det regna yver jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Og Elia tok i veg og vilde stiga fram for Ahab. Men svolten var stor i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Då kalla Ahab til seg Obadja, som var drottsete. Obadja ottast Herren av heil hug;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'den gongen då Jezabel rudde ut Herrens profetar, hadde Obadja teke og gøymt hundrad profetar i tvo hellerar, femti mann i kvar heller, og sytt for deim med brød og vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Ahab sagde då til Obadja: «Far igjenom landet til alle vatskjeldor og bekkjer! Kann henda me kann finna gras, so me kann halda liv i hestar og muldyr og sleppa slagta noko av buskapen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Og dei skifte landet millom seg og for igjenom det; Ahab for ein veg for seg, og Obadja tok ein annan veg for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Då no Obadja var på ferdi, kom Elia til møtes med honom. Og han kjende honom og kasta seg å gruve og sagde: «Er du her, min herre Elia?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Han svara honom: «Ja; gakk og seg til herren din at Elia er her!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Då sagde han: «Kva hev eg forsynda meg med, sidan du vil gjeva tenaren din i handi på Ahab, so han kann taka livet av meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'So sant Herren, din Gud, liver, det finst ikkje det folk eller det rike utan at herren min hev sendt bod til det og leita etter deg; og når dei sagde: «Her er han ikkje,» so let han det riket eller det folket sverja på at dei ikkje kunde finna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Og no segjer du: «Gakk og seg herren din at Elia er her!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Um det no gjeng so, når eg er gjengen ifrå deg, at Herrens Ande tek deg burt til ein stad eg ikkje kjennar, og eg like vel kjem til Ahab med bod um det, so drep han meg, når han ikkje finn deg. Og tenaren din hev då ottast Herren like frå ungdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Hev dei ikkje fortalt deg, herre, kva eg gjorde då Jezabel drap Herrens profetar? Då gøymde eg hundrad mann av Herrens profetar i tvo hellerar, femti mann i kvar heller, og sytte for deim med brød og vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Og no segjer du: «Gakk og seg til herren din: Elia er her» - so at han få livet av meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Då sagde Elia: «So sant Herren, allhers drott, liver, han som hev meg i tenesta, so skal eg i dag stiga fram for kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Obadja gjekk då til møtes med Ahab og fortalde dette med honom, og Ahab gjekk til møtes med Elia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Då Ahab såg Elia, sagde Ahab til honom: «Er du her, du som dreg ulukka yver Israel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Han svara: «Det er ikkje eg som dreg ulukka yver Israel, men du og farshuset ditt, med di de hev vendt dykk frå Herrens bod og fylgt Ba’alarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Men send no bod og lat heile Israel stemna saman til meg på Karmelfjellet, og like eins dei fire hundrad og femti Ba’als-profetarne og dei fire hundrad Asjera-profetarne som gjeng til bords hjå Jezabel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Og Ahab sende bod ikring til alle Israels-sønerne, og samla profetarne på Karmelfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Då steig Elia fram for folkemengdi og sagde: Kor lenge vil de halda på å halta til båe sidor? Er det Herren som er Gud, so ten honom; men er det Ba’al som er Gud, so ten honom!» Folket svara ikkje eit ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Då sagde Elia til folket: «Eg er no den einaste som er att av Herrens profetar; men Ba’als-profetarne er fire hundrad og femtimann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Lat oss no få tvo uksar, og lat deim velja seg ut den eine uksen og hogga honom i stykke og leggja honom på offerveden, men ikkje kveikja eld på, og eg skal laga til den andre uksen og leggja den på offerveden, men ikkje kveikja eld på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'So kann de kalla på namnet åt dykkar gud, og eg skal kalla på Herrens namn. Og lat det då vera so, at den gud som då svarar med eld, han er Gud.» Heile folkemengdi svara: «Det framlegget er godt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Og Elia sagde til Ba’als-profetarne: «Vel dykk ut den eine av uksen og laga til den fyrst, etter di de er dei fleste, og ropa so på guden dykkar, men kveik ikkje eld på!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Då tok dei den uksen som han hadde gjeve deim, og laga honom til og ropa på Ba’al frå morgon til middag og sagde: «Ba’al, svara oss!» Men det kom ingen ljod, og ingen svara. Dei hinka kringum altaret som dei hadde sett upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Ved middagsleite tok Elia på å gjøra narr av deim og sagde: «Ropa med sterkare mål! For han er då Gud, må vita; han sit vel og grundar på eitkvart, eller og er han gjengen til sides eller er ute på ferd; eller kann henda han søv, då vaknar han vel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Og dei ropa med sterkt mål og flengde seg med sverd og spjot som deira vis var, til dess blodet flaut nedetter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Då det leid yver middag, rasa dei til fram imot grjonoffer-tidi; men det kom ingen ljod, og ingen svara, og ingen brydde seg um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Då sagde Elia til folkemengdi: «Kom hit til meg!» Og folkemengdi gjekk burt til honom. Då bygde han upp att Herrens altar, som hadde vorte nedrive.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Elia tok tolv steinar, etter talet på ættarne av Jakobs-sønerne, han som Herren hadde tala til soleis: «Israel skal namnet ditt vera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Og av steinarne bygde han eit altar i Herrens namn, og grov ei veit umkring altaret um lag so stor som til tvo halvskjeppor sæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'So lagde han offerveden til rettes og hogg uksen i stykke og lagde han ovanpå veden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Og han sagde: «Fyll i fire krukkor med vatn, og aus det ut yver brennofferet og veden!» Og han sagde: «Gjer det ein gong til!» Og dei gjorde det andre gongen. Men han sagde: «Gjer det tridje gongen!» Og dei gjorde det tridje gongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Vatnet flaut rundt umkring altaret, og han fyllte veiti med vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Og ved grjonoffer-tidi steig Elia, profeten, fram og sagde: «Herre, Abrahams og Isaks og Israels Gud! Lat det verta ålkjent i dag at du er Gud i Israel, og at eg er tenaren din, og at eg hev gjort alt dette etter bod ifrå deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Svara meg, Herre, svara meg, so dette folket kann få kjenna at du, Herre, er Gud, og vender hugen deira attende til deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Då rann Herrens eld ned og åt upp brennofferet og veden og steinarne og moldi og sleikte upp vatnet som var i veiti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Og folkemengdi såg det, og dei kasta seg å gruve og sagde: «Det er Herren som er Gud! Det er Herren som er Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Då sagde Elia til deim: «Tak Ba’als-profetarne, lat ingen av deim sleppa undan!» Og dei tok dem, og Elia styrde deim ned til Kisonbekken og let deim drepa der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Og Elia sagde til Ahab: «Far no upp att og et og drikk! For eg høyrer sus av regn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Då for Ahab upp og vilde eta og drikka. Men Elia steig upp på toppen av Karmel, lutte seg ned mot jordi og lagde andlitet millom knei sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Og han sagde til drengen sin: «Gakk upp og skoda utåt havet!» Drengen gjekk upp og skoda ut, men sagde: «Eg ser ingenting.» Sju gonger bad han honom ganga upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Då han so kom dit sjuande gongen, sagde han: «No ser eg det stig upp av havet ei liti sky; ho er ikkje større enn neven på ein mann.» Då sagde han: «Gakk upp og seg til Ahab: «Beit fyre og far ned, so ikkje regnet skal hefta deg!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Og i ei handevending myrkna himmelen til med skyer og storm, og snart silregnde det. Men Ahab køyrde av stad og for til Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Og Herrens hand kom yver Elia, so at han sette livgjord ikring seg og sprang fyre Ahab like til Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Ahab fortalde Jezabel alt det som Elia hadde gjort, og korleis han hadde drepe alle profetarne med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Då sende Jezabel eit bod til Elia med dei ordi: «Gudarne late meg bøta både no og sidan, um eg ikkje i morgon ved denne tid skal lata ditt liv få same lagnad som kvar av hine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Og då han fekk den greida, tok han ut og rømde for livet, og han kom til Be’erseba, som høyrer til Juda; der let han drengen sin vera att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Men sjølv gjekk han ei dagsleid ut i øydemarki. Der sette han seg under ein einerunne, og han ynskte at han måtte få døy, og sagde: «No er det nok; Herre, tak no livet mitt, for eg er ikkje betre enn federne mine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'So lagde han seg til å sovna under ein einerunne. Men då tok ein engel i honom og sagde: «Statt upp og et!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Og då han skulde sjå til, so låg det ved hovudgjerdi hans ei kaka steikt på gloande steinar, og det stod ei krukke med vatn; og han åt og drakk og lagde seg att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Då kom Herrens engel att andre gongen og tok i honom og sagde: «Statt upp og et! For elles vert vegen for lang for deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Og han stod upp og åt og drakk, og styrkt av denne maten gjekk han i fyrti dagar og fyrti netter alt til Gudsfjellet Horeb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Der gjekk han inn i ein heller og var der um natti. Då kom Herrens ord til honom; han sagde til honom: «Kva vil du her, Elia?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Og han svara: «Eg hev brunne av brennhug for Herren, allhers Gud; for Israels-borni hev vendt seg burt ifrå sambandet ditt; altari dine hev dei rive ned, og profetarne dine hev dei drepe med sverd; eg er att åleine, og dei stend meg etter livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Då sagde han: «Gakk ut og statt på fjellet for Herrens åsyn!» Og so gjekk Herren framum der. Fyre Herren kom det ein stor og veldug storm, so fjell rivna og klettar klovna; Herren var ikkje i stormen. Etter stormen kom det ein jordskjelv; Herren var ikkje i jordskjelven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Etter jordskjelven kom det eld; men Herren var ikkje i elden. Etter elden høyrdest ei mild susing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'So snart Elia høyrde det, sveipte han andlitet inn i kappa si og gjekk ut og stod ved inngangen til helleren. Då tala ei røyst til honom og sagde: «Kva vil du her, Elia?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Og han svara: «Eg hev brunne av brennhug for Herren, Allhers Gud; for Israels-borni hev vendt seg burt frå sambandet ditt; altari dine hev dei rive ned, og profetarne dine hev dei drepe med sverd; eg er att åleine, og dei stend meg etter livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Herren sagde til honom: «Far no attende og tak vegen til Damaskusheidi, og gakk inn i byen og salva Hazael til konge yver Syria!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Og Jehu Nimsison skal du salva til konge yver Israel, og Elisa Safatsson frå Abel-Mehola, skal du salva til profet i din stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Då skal det ganga so: Den som slepp undan Hazael-sverdet, honom skal Jehu drepa, og den som slepp undan Jehu-sverdet, skal Elisa drepa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Men eg vil lata sju tusund vera att i Israel, alle dei kne som ikkje hev bøygt seg for Ba’al, og kvar munn som ikkje hev gjeve honom hyllingskyss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Då han gjekk derifrå, råka han på Elisa Safatsson, som heldt på og pløgde; tolv par uksar gjekk fyre honom, og sjølv køyrde han det tolvte paret. Og Elia gjekk burt til honom og kasta kappa si på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Då slepte han uksarne og sprang etter Elia og sagde: «Lat meg få kyssa far min og mor mi, so skal eg fylgja deg!» Han sagde til honom: «Snu heim att då! Men kom i hug kva eg hev gjort med deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'So gjekk han ifrå honom att og tok dei tvo uksarne og slagta deim, og med oket åt uksarne koka han kjøtet deira og gav folket, og dei åt. Sidan tok han ut og fylgde Elia og vart tenaren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Benhadad, kongen i Syria, samla heile heren sin, og han hadde med seg tvo og tretti kongar, og hestar og vogner; han drog upp og kringsette Samaria og gjorde åtak på byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Og han sende bod inn i byen til Ahab, Israels-kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'med dei ordi: «So segjer Benhadad: «Sylvet ditt og gullet ditt høyrer meg til, og dei vænaste av konorne og borni dine, høyrer meg til.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Israels-kongen svara og sagde: «Det er som du segjer, herre konge. Eg høyrer deg til med alt som mitt er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Men sendebodi kom att og sagde: «So segjer Benhadad: «Eg sende bod til deg med dei ordi: «Sylvet ditt og gullet ditt og konorne og borni dine skal du gjeva meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'I morgon ved dette bilet sender eg tenarane mine til deg, og dei skal ransaka ditt hus og husi åt tenarane dine, og alt det augo dine hev likar best, skal dei taka med seg og føra burt.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Då kalla Israels-kongen til seg alle styresmennerne i landet og sagde: «De må skyna og sjå at han vil oss vondt. For han sende bod til meg um konorne og borni mine og um sylvet og gullet mitt, og eg neitta ikkje å gjeva honom det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Då sagde alle styresmennerne og alt folket: «Du må ikkje høyra på honom og ikkje gjera honom til viljes.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Då sagde han til sendebodi frå Benhadad: «Seg til min herre kongen: «Eg skal gjera alt det som du fyrste gongen sende bod um til tenaren din; men dette kann eg ikkje gjera.»» So gjekk sendebodi burt og bar svaret fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Då sende Benhadad bod til honom med dei ordi: «Gudarne late meg bøta no og sidan, um gruset i Samaria skal rekka til å fylla nevarne på alt det folket som eg hev med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Men Israels-kongen svara og sagde: «So skal de segja: «Ei rose seg den som bind sverdet um seg, som den som løyser det av seg!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Då Benhadad høyrde det svaret, medan han og kongarne sat og drakk i lauvhyttorne, sagde han til tenarane sine: «Ferdig til åtak!» Og dei gjorde seg ferdige til å setja inn på byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Med same kom det ein profet burt til Ahab, Israels-kongen, og sagde: «So segjer Herren: «Ser du heile denne store hopen? I dag skal du sjå eg gjev honom i di hand, so du skal skyna at eg er Herren.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Men Ahab spurde: «Kven skal vera reidskap?» Han svara: «So segjer Herren: «Jarlesveinarne.»» Og han spurde: «Kven skal taka til med striden?» Og han svara: «Det skal du.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'So mynstra han jarlesveinarne, og dei var tvo hundrad og tvo og tretti, og etter deim mynstra han heile folket, alle Israels-sønerne, sju tusund i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Dei drog ut ved middagsbil, medan Benhadad drakk seg eit rus i lauvhyttorne saman med dei tvo og tretti kongarne som skulde hjelpa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Fyrst drog jarlesveinar ut, og dei bodi Benhadad sende, melde honom at det kom folk ut frå Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Då sagde han: «Hev dei drege ut til fred, so grip deim livande, og hev dei drege ut til strid, so grip deim livande!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Men dei drog ut or byen, jarlesveinarne og heren som fylgde deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'og dei hogg ned kvar sin mann, og syrarane rømde, og Israel sette etter deim, og Benhadad, syrarkongen, slapp undan på ein hest saman med nokre riddarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'So drog Israels-kongen ut og slo hestfolket og vognheren, so syrarane leid stor usiger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Då steig profeten fram for Israels-kongen og sagde til honom: «Gakk og samla krafti di, og tenk vel etter kva du vil gjera! For næste år dreg syrarkongen upp i mot deg att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Men tenarane åt syrarkongen sagde til honom: «Guden deira er ein fjellgud, difor vann dei yver oss, lat oss strida imot deim på sletta, so skal me visseleg vinna yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Og dette skal du gjera: Set kvar og ein av kongarne av frå hans post, og set jarlar i staden deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Få deg so sjølv ein her, likso stor som den du hev mist, og likso mange hestar og vogner, og lat oss so strida imot deim på sletta, då skal me visseleg vinna yver deim.» Han høyrde på det dei sagde, og gjorde so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Året etter mynstra Benhadad syrarane og drog upp til Afek, til strid imot Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Og Israels-sønerne vart mynstra og utnista, og dei drog imot deim; og Israels-sønerne lægra seg midt imot deim som tvo små geiteflokkar, men syrarane fyllte landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Då steig gudsmannen fram og sagde til Israels-kongen: «So segjer Herren: «For di syrarane hev sagt at Herren er ein fjellgud og ikkje ein dalgud, so vil eg gjeva heile denne store hopen i henderne dine, og de skal skyna at eg er Herren.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'So låg dei lægra imot kvarandre i sju dagar; men på den sjuande dagen kom det til strid, og Israels-sønerne hogg ned syrarane, hundrad tusund fotfolk på ein dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Dei som var att, rømde inn i byen Afek, men bymuren ramla ned yver dei sju og tjuge tusund mann som var att. Og Benhadad rømde og kom inn i byen og sprang frå kove til kove.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Då sagde mennerne hans til honom: «Høyr no her!» Me hev frett at kongarne av Israels hus er milde kongar; lat oss binda sekkjety um lenderne og reip um hovudet og ganga ut til Israels-kongen! Kann henda han let deg få liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'So batt dei sekkjety um lenderne og reip um hovudet og gjekk til Israels-kongen, og sagde: «Tenaren din Benhadad segjer: «Lat meg få liva!»» Og han svara: «Er han endå i live? Han er bror min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Og mennerne tok det for eit godt varsel, og dei skunda seg og tok honom på ordet og sagde: «Ja, Benhadad er bror din.» Då sagde han: «Gakk og henta honom!» Og Benhadad kom ut til honom, og han let honom stiga upp på vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Då sagde Benhadad til honom: «Dei byarne som far min tok frå far din, skal eg gjeva deg att, og du kann gjera deg gator i Damaskus, liksom far min gjorde i Samaria.» «Ja vel,» (svara Ahab) «på dei vilkåri skal eg gjeva deg fri». So gjorde han samband med honom og let honom fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Men ein av profetsveinarne sagde til ein annan etter Herrens fyresegn: «Slå meg!» Men mannen vilde ikkje slå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Då sagde han til honom: «Av di du ikkje lydde Herrens røyst, so skal ei løva slå deg når du gjeng burt ifrå meg.» Og då han gjekk ifrå honom, råka ei løva på honom og slo honom ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Sidan råka han ein annan mann og sagde: «Slå meg!» Og mannen slo honom so han fekk ei flengja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'So gjekk profeten og stelte seg på vegen der kongen skulde koma; men han batt eitt plagg for augo, so ingen kunde kjenna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Då kongen so kom framum der, ropa han til kongen: «Tenaren din hadde gjeve seg inn i striden; då kom det ein mann ut or fylkingi og førde til meg ein mann og sagde: «Tak vare på denne mannen! Slepp han burt, skal du svara for honom med ditt liv eller vega ut tvo og ei halv våg sylv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Men medan tenaren din hadde eitt og anna å gjera her og der, so slapp han burt.» Israels-kongen sagde til honom: «So hev du domen som du sjølv hev felt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Då skunda han seg og tok plagget burt frå augo sine, og Israels-kongen kjende honom, at han var ein av profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Han sagde til honom: «So segjer Herren: «Sidan du hev slept or henderne den mannen som eg hev bannstøytt, so skal ditt liv svara for hans liv, og ditt folk for hans folk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Og Israels-kongen for heim, mismodig og harm, og kom til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Sidan hende denne tilburden: Jizre’eliten Nabot, hadde ein vinhage som låg i Jizre’el innåt slottet til Ahab, kongen i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Og Ahab tala med Nabot og sagde: «Lat meg få vinhagen din, so eg kann hava honom til kålhage, for han ligg so nær innåt huset mitt. Eg skal gjeva deg ein betre vingard i staden, eller um du so tykkjer, skal eg greida verdet ut i reide pengar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Men Nabot sagde til Ahab: «Aldri i verdi vil eg gjeva deg fedrearven min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Då gjekk Ahab heim, mismodig og harm for det svaret jisre’eliten Nabot hadde gjeve honom då han sagde: «Eg vil ikkje gjeva deg fedrearven min.» Og han lagde seg i sengi og snudde seg burt og vilde ikkje eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Då kom Jezabel, kona hans, inn til honom og sagde til honom: «Kvi er du so stur i hugen, so du ikkje vil eta?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Han svara henne: «Eg tala med jizre’eliten Nabot og sagde til honom: «Lat meg få vinhagen din for pengar, eller um du so tykkjer, skal eg gjeva deg ein annan vinhage i staden.» Men han svara: «Eg vil ikkje gjeva deg vinhagen min.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Då sagde Jezabel, kona hans, til honom: «Er det du som no hev kongevelde i Israel? Statt upp, et og ver i godlag! Eg skal gjeva deg vinhagen åt jizre’eliten Nabot.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Og ho skreiv eit brev i namnet åt Ahab og sette innsigle under med hans seglring og sende brevet til styresmennerne og storfolket i byen hans Nabot, dei som budde saman med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Ho skreiv soleis i brevet: «Lys til ei fasta, og set so Nabot øvst millom folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'og set tvo uvyrdne karar midt imot honom, og lat deim vitna imot honom og segja: «Du hev banna Gud og kongen!» Før so honom ut og steina honom i hel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Mennerne i byen hans, styresmennerne og storfolket, dei som budde der i byen hans, gjorde etter det bodet som Jezabel hadde sendt deim, so som det var skrive i brevet ho hadde sendt til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Dei lyste til ei fasta og sette Nabot øvst millom folket;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'og dei tvo uvyrdne kararne kom og sette seg midt imot honom, og uvyrdorne vitna imot Nabot for folket og sagde: «Nabot hev banna Gud og kongen.» So førde dei honom utanfor byen og kasta stein på honom til han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Og dei sende bod til Jezabel med dei ordi: «Nabot er steina i hel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Då Jezabel høyrde at Nabot var steina i hel, sagde Jezabel til Ahab: «Statt upp, eigna til deg vinhagen åt jizre’eliten Nabot, den som han ikkje vilde gjeva deg for pengar! For Nabot er ikkje lenger i live, han er dåen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Då Ahab høyrde at Nabot var dåen, stod Ahab upp og gav seg på vegen til vinhagen åt jizre’eliten Nabot og vilde eigna honom til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Men Herrens ord kom til Elia frå Tisbe soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '«Statt upp, og far ned og møt Ahab, Israels-kongen, som bur i Samaria! No er han i vinhagen åt Nabot, han hev gjenge ned og vil eigna til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Du skal tala med honom og segja: «So segjer Herren: Hev du no både drepe og eigna til deg arven?» Og du skal tala med honom og segja: «So segjer Herren: På same staden som hundarne hev slikka blodet åt Nabot, skal hundarne slikka blodet ditt og.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Ahab sagde til Elia: «Hev du funne meg, du fienden min?» Han svara: «Ja, eg hev funne deg. Sidan du hev selt deg til å gjera det som vondt er i Herrens augo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'so fører eg ulukka yver deg, og eg skal sopa etter deg og rydja ut or Ahabs-ætti kvar ein karmann, både ufri og fri i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Og eg skal fara med ditt hus som eg for med huset åt Jerobeam Nebatsson og huset åt Baesa Ahiason, for di du hev harma meg so mykje og forført Israel til synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Um Jezabel og hev Herren tala og sagt: «Hundarne skal eta upp Jezabel attmed Jisre’elsmuren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Den av Ahabs-ætti som døyr i byen, skal hundarne eta upp, og den som døyr ute på marki, skal fuglarne eta upp.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Aldri hev det vore nokon slik som Ahab, som selde seg sjølv til å gjera det som vondt var i Herrens augo, av di Jezabel, kona hans, eggja honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Mykje stygt gjorde han, med di han for etter dei ufyselege avgudarne, plent som amoritarne hadde gjort, dei som Herren dreiv burt for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Men då Ahab høyrde dei ordi, reiv han sund klædi sine og sveipte sekk um kroppen og fasta; og han sov i sekkjetyet og for stilt fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Då kom Herrens ord til Elia frå Tisbe soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '«Hev du set korleis Ahab audmykjer seg for meg? For di han audmykjer seg, skal eg ikkje lata ulukka koma i hans livstid; men i hans sons tid skal eg lata ulukka koma yver huset hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'No heldt dei seg rolege i tri år; det var ingen ufred millom Syria og Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Men i det tridje året bar det so til at Josafat, Juda-kongen, drog ned til Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Då sagde Israels-kongen til mennerne sine: «Veit de ikkje at Ramot i Gilead høyrer oss til? Men me sit rolege og tek ikkje byen ifrå syrarkongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Og han sagde til Josafat: «Vil du draga med meg til strid um Ramot i Gilead?» Og Josafat sagde til Israels-kongen: «Eg som du, mitt folk som ditt folk, mine hestar som dine hestar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Men Josafat sagde til Israels-kongen: «Spør like vel fyrst Herrens ord til råds!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Då stemnde Israels-kongen saman profetarne, kring fire hundrad mann, og spurde dei: «Skal eg draga ut og strida um Ramot i Gilead, eller skal eg lata vera?» Dei svara: «Drag dit upp! Herren vil gjeva byen i henderne på kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Men Josafat spurde: «Er det ikkje endå ein av Herrens profetar her, so me kunde spyrja Herren gjenom honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Israels-kongen svara: «Det er endå ein mann som ein kann spyrja Herren ved, men eg hatar honom, for di han spår meg aldri noko godt, men berre vondt; det er Mika Jimlason.» Josafat sagde: «Soleis må ikkje kongen tala!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Då kalla Israels-kongen på ein hirdmann og sagde: «Henta snøgt Mika Jimlason!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Israels-kongen og Juda-kongen Josafat sat klædde i sine skrud på kvar sin kongsstol, på treskjarvollen ved inngangen til byporten i Samaria, og alle profetarne spådde framfyre deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Sidkia, son åt Kena’ana, gjorde seg horn av jarn og sagde: «So segjer Herren: «Med slike horn skal du stanga syrarane til du tynar deim.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Og alle profetarne spådde på same måten og sagde: «Drag upp til Ramot, so skal du få siger, og Herren vil gjeva byen i henderne på kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Sendemannen som var gjengen og skulde henta Mika, sagde til honom: «Profetarne hev samrøystes lova kongen lukka, lat då ordi dine samstavas med deira, og lova lukka du og!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Men Mika svara: «So sant som Herren liver, vil eg berre tala det som Herren segjer til meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Då han no kom til kongen, sagde kongen til honom: «Mika, skal me draga av stad og strida um Ramot i Gilead, eller skal me lata det vera?» Då sagde han: «Drag upp, so skal du få siger, og Herren vil gjeva byen i henderne på kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Men kongen sagde til honom: «Kor mange gonger skal eg taka deg i eid på at du ikkje vil segja meg anna enn sanningi i Herrens namn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Då sagde han: «Eg såg heile Israel spreidt i fjelli som ein saueflokk utan hyrding; og Herren sagde: «Dei der hev ingen herre, lat deim snu heim att i fred, kvar til sitt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Israels-kongen sagde til Josafat: «Sagde eg deg ikkje, at han aldri varslar meg noko godt, berre vondt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Då sagde han: «So høyr då Herrens ord: Eg såg Herren sitja på sin kongsstol, og heile himmelheren stod der hjå honom på den høgre og den vinstre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Og Herren sagde: «Kven vil dåra Ahab, so han dreg upp og fell ved Ramot i Gilead?» Då sagde ein so og ein annan so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Men då kom anden fram og stelte seg framfor Herren og sagde: «Eg skal lokka honom!» Herren spurde honom: «Korleis?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Han svara: Eg vil ganga ut og vera ei ljugarånd i munnen på alle profetarne hans.» Og han sagde: «Ja, du skal lokka honom, og du skal og greida det. Gakk av stad og gjer so!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Sjå no hev Herren lagt ei ljugarånd i munnen på alle desse profetarne dine, men Herren hev varsla ulukka yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Då kom Sidkia, son åt Kena’ana, fram og slo Mika på kinni og sagde: «Kva veg hev då Herrens ande fare frå meg for å tala med deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Men Mika sagde: «Det skal du få sjå den dagen du rømer frå kove til kove og vil gøyma deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Då sagde Israels-kongen: «Tak Mika og før honom til byhovdingen Amon og kongssonen Joas,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'og seg: «Kongen byd dykk at det skal kasta denne mannen i fangehuset og setja honom på snaud kost til kongen kjem heim att med heilo!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Men Mika sagde: «Kjem du heim att med heilo, då hev ikkje Herren tala gjenom meg!» Og so sagde han: «Høyr de folk, alle saman!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'So drog då Israels-kongen og Josafat, Juda-kongen, upp til Ramot i Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Men Israels-kongen sagde til Josafat: «Eg vil klæda meg ut fyrr eg gjeng inn i striden; men hav du dine klæde på deg!» Og Israels-kongen klædde seg ut og gjekk inn i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Men syrarkongen hadde gjeve det bodet til sine tvo og tretti hovdingar for stidsvognarne, at dei ikkje skulde taka på nokon, korkje liten eller stor, men berre Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Då no hovdingarne for stridsvognerne fekk auga på Josafat, tenkte dei: «Det er visseleg Israels-kongen!» Og dei vende seg til åtak på honom. Då sette Josafat i eit høgt rop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Og då hovdingarne for stridsvognerne merka at det ikkje var Israels-kongen, drog dei seg burt ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Men ein mann som spende bogen og skaut på måfå, råka Israels-kongen millom brynjeskøytingarne og brynja. Då baud han vognstyraren sin: «Snu, og før meg ut or heren; for eg er såra!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Men striden vart hardare og hardare den dagen, og Israels-kongen vart standande i vogni imot syrarane; men um kvelden døydde han. Og blodet frå såret hadde runne ned i vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Ved soleglad gjekk det ropet gjenom heren: «Kvar mann heim til sin by! og kvar mann til sitt land!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'So døydde då kongen og vart førd til Samaria, og dei jorda kongen i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Då dei skylde vogni ved dammen i Samaria, slikka hundarne blodet hans, og skjøkjorne lauga seg i det, etter Herrens ord som han hadde tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Det som elles er å fortelja um Ahab og alt det han gjorde, og um flisbeinhuset han bygde, og um alle dei byarne han bygde, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'So lagde Ahab seg til kvile hjå federne sine, og Ahazja, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Josafat Asason vart konge yver Juda i det fjorde styringsåret åt Ahab, Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Fem og tretti år gamall var Josafat då han vart konge, og fem og tjuge år rådde han i Jerusalem; mor hans heitte Azuba og var dotter åt Silhi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Og han for heilt i same faret som Asa, far sin; han veik ikkje av frå det, med di han gjorde det som rett var i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Men offerhaugarne vart ikkje burttekne, folket heldt ved og ofra slagtoffer og brende røykoffer på haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Og Josafat heldt fred med Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Det som elles er å fortelja um Josafat, og dei storverki han gjorde og dei krigarne han førde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Han rudde ut or landet dei utukt-sveinarne som hadde vorte att den tid Asa, far hans, styrde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Det var ingen konge i Edom; ein jarl var konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Josafat hadde ti Tarsis-skip som skulde fara til Ofir etter gull; men dei kom ikkje av stad, for nokre skip forliste ved Esjon-Geber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Då sagde Ahazja Ahabsson til Josafat: «Lat mine menner fara med dine på skipi!» Men Josafat vilde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Og Josafat lagde seg til kvile hjå federne sine, og vart gravlagd hjå federne sine i byen åt David, far hans, og Joram, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahazja Ahabsson vart konge yver Israel i det syttande styringsåret åt Juda-kongen Josafat, og han rådde yver Israel i tvo år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Og han gjorde det som vondt var i Herrens augo og for fram i fotefari åt far sin og mor si og Jerobeam Nebatsson, han som fekk Israel til å synda. Og han tente Ba’al og bad til honom, og harma Herren, Israels Gud, plent som far hans hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Etter Ahab var dåen, reiv Moab seg laus frå Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Ahazja låg sjuk, av di han hadde dotte ned millom handridet på loftstova si i Samaria. Han gjorde då av stad ei sendeferd og baud deim fara av og spyrja Ekronguden Ba’al-Zebub um han skulde koma seg av denne sjukdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Herrens engel sagde då til Elia frå Tisbe: «Gakk til møtes med sendeferdi frå Samaria og seg med deim: «Finst det ingen Gud i Israel, sidan de fer av og fretter Ekronguden Ba’al-Zebub?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Difor, so segjer Herren: «Or sengi du er lagt i, skal du ikkje koma upp att; du skal døy.»»» Og Elia gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Sendeferdi snudde dermed heim att til kongen. Han spurde: «Kvifor kjem de att?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Dei svara: «Det kom ein mann til møtes med oss. «Snu heim att til kongen som sende dykk,» sagde han, «og meld honom at so segjer Herren: «Finst det ingen Gud i Israel, sidan du sender bod og fretter Ekronguden Ba’al-Zebub? Difor, or sengi du er lagd i, skal du ikkje koma upp att; du skal døy.»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Kongen spurde: «Korleis såg han ut, den mannen som møtte dykk og tale soleis med dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, '«Han gjekk med hårkyrtel,» svara dei, «og hadde lerbelte kring livet.» «Det var Elia frå Tisbe,» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'So sende han ein femtimanns-førar med sine femti mann til honom. Han kom upp til honom der han sat øvst på fjellet, og ropa til honom: «Du gudsmann, kongen byd deg koma ned!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elia svara femtimanns-føraren: «So sant eg er ein gudsmann, so fare eld ned frå himmelen og øyde deg og dine femti mann!» Og det for ned eld frå himmelen og øydde både honom og dei femti han førde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'So sende han til honom ein annan femtimanns-førar med sine femti mann. Han tok til ords og sagde til honom: «Du gudsmann, so segjer kongen: «Kom ned snøggast du kann!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elia svara: «So sant som eg er ein gudsmann, so fare eld ned frå himmelen og øyde deg og dine femti mann!» Det for då ned eld frå himmelen og øydde både honom og dei femti mann han førde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Då sende han ein tridje femtimanns-førar med femti mann til. Denne tridje femtimanns-føraren drog upp og fall på kne for Elia og naudbad honom: «Du gudsmann! lat mitt liv og livet åt desse femti tenarane dine vera dyrt i dine augo!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Du veit at eld for ned frå himmelen og øydde båe dei fyrre førarane og deira femtimanns-tropp. Haldt no mitt liv dyrt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Då sagde Herrens engel til Elia: «Gakk med honom! Ver ikkje rædd for honom!» So stod han upp og gjekk med honom til kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Og sagde til honom: «So segjer Herren: «Av di du gjorde av stad ei sendeferd til å fretta Ekronguden Ba’al-Zebub - nett som det ingen Gud vore i Israel til å spyrja um det - difor skal du ikkje koma upp or sengi du er lagd i; du skal døy!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Og han døydde so som Herren tala ved Elia. Og Joram vart konge etter honom; for han hadde ingen son. Dette hende i andre styringsåret åt Juda-kongen Joram Josafatsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Det som elles er å fortelja um Ahazja, det han gjorde, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Den gongen Herren tok Elia upp til himmelen i ein storm, skulde Elia og Elisa på utferd frå Gilgal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Elia sagde med Elisa: «Ver du her! Herren hev sendt meg til Betel.» Men Elisa svara: «So sant Herren liver, og so sant du liver, eg skil ikkje lag med deg.» So for dei ned til Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Profetsveinarne i Betel møtte Elisa: «Veit du det,» sagde dei, «at i dag tek Herren husbonden din ifrå deg?» «Ja, eg veit det,» svara han; «de tarv ikkje nemna det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Elia sagde med honom: «Elisa, ver du her! Herren hev sendt meg til Jeriko.» Men han svara: «So sant Herren liver, og so sant du liver, eg skil ikkje lag med deg.» So kom dei til Jeriko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Profetsveinarne i Jeriko gjekk fram til Elisa: «Veit du det,» sagde dei, «at i dag tek Herren husbonden din ifrå deg?» «Ja, vel veit eg det,» svara han; «det tarv ikkje nemna det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Elia sagde med honom: «Ver du her! Herren hev sendt meg til Jordan.» Men han svara: «So sant Herren liver, og so sant du liver, eg skil ikkje lag med deg.» So gjekk dei båe tvo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Femti av profetsveinarne fylgde, og stod eit godt stykke undan, medan dei tvo stod attmed Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Elia tok kappa si, sveipte henne i hop og slo på vatnet. Då kløyvde det seg til båe kanter, so dei gjekk båe yver på turre botnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Då dei var komne yver, sagde Elias med Elisa: «Kva ynskjer du eg skal gjera for deg fyrr eg vert teken ifrå deg?» Elisa sagde: «Gjev ein dubbel lut av di ånd må falla på meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, '«Det var eit storfelt ynskje,» svara han; «men fær du sjå meg medan eg vert teken frå deg, skal du få det, elles ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Medan dei so heldt fram og talast ved, skimta det fram ei eldvogn med eldhestar og skilde deim frå einannan. Og so for Elia i stormveret upp til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elisa stod og såg på, og han ropa: «Far! far! du Israels vogner og riddarar!» So såg han ikkje meir til honom. Og han tok i klædi sine og reiv deim midt i tvo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'So tok han upp kappa åt Elia, som hadde falle av honom, snudde so og gjekk ned til elvebarden ved Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Han tok kappa åt Elia, som hadde falle av honom, og slo på vatnet med dei ordi: «Kvar er no Herren, Elias Gud?» Med same han slo på vatnet, kløyvde det seg til båe kanter, og Elisa gjekk yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Då profetsveinarne frå Jeriko såg dette langt undan, sagde dei: «Elias ånd kviler yver Elisa.» Dei kom imot honom og lagde seg å gruve for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'So sagde dei med honom: «Millom tenarane dine finn du femti sterke karar; lat deim ganga ut og leita etter herren din! Kann henda hev Herrens Ande lyft honom upp og slept honom på eitkvart fjellet eller i einkvar dalen.» Han svara: «De skal ingen senda ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Men dei naudbad honom so lenge at han vart leid av det: «Send deim ut då!» sagde han. Dei sende ut femti mann, og dei leita i tri dagar, men fann honom ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Då dei kom att til honom - han heldt seg endå i Jeriko - so sagde han til deim: «Det var det eg sagde med dykk, at de skulde ikkje ganga ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Byfolki og sagde til Elisa: «Denne byen ligg lageleg til, som du herre ser. Men vatnet er vondt, og landet lid av fosterskot.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Han svara deim: «Gjev meg ei ny skål, og legg salt i henne!» Dei so gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Gjekk han so ut til uppkoma og kasta saltet nedi med dei ordi: «So segjer Herren: «Eg gjer dette vatnet friskt, so det aldri meir skal valda daude og fosterskot.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Og vatnet vart friskt, og er det den dag i dag, soleis som Elisa hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Derifrå drog han upp til Betel. På vegen dit upp, kom nokre smågutar ut or byen og tok til å hæda honom og kalla honom: «Upp med deg, du snaudskalle! Upp med deg, du snaudskalle!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Han såg seg ikring. Og då han vart var deim, lyste han våbøn yver deim i Herrens namn. Tvo binnor kom då ut or skogen og reiv sund tvo og fyrti av borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Derifrå gjekk han til Karmelfjellet, og derifrå attende til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram Ahabsson vart konge yver Israel i Samaria i det attande styringsåret åt Juda-kongen Josafat. Han var konge i tolv år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Han gjorde det som vondt var i Herrens augo, men endå ikkje soleis som far og mor hans. Han fekk burt Ba’als-sula som far hans hadde sett upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Men han heldt fast på synderne åt Jerobeam Nebatsson, som han hadde fenge Israel til å gjera, deim gav han ikkje upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Moabs-kongen Mesa åtte so mykje fe. I skatt til Israels-kongen hadde han svara hundrad tusund lamb og ulli av hundrad tusund verar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Men då Ahab døydde, sagde Moabs-kongen seg laus frå Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'På timen drog kong Joram ut or Samaria og mynstra heile Israels-heren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Og so sende han bod til Juda-kongen Josafat med dei ordi: «Moabs-kongen hev sagt seg laus frå meg; vil du fara med meg og føra krig Moab?» «Ja,» svara han, «eg skal fara med, eg som du, mitt folk som ditt folk, mine hestar som dine hestar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Han spurde: «Kva veg skal me fara?» «Yver Edomheidarne,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Gav dei seg so i veg, Israels-kongen og Juda-kongen og Edom-kongen. Men då dei hadde fare sju dagsferder, vanta dei vatn til heren og til dyri som fulgde etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, '«Å du, å du!» sagde Israels-kongen, «no hev Herren stemnt i hop desse tri kongarne til å gjeva deim i henderne på moabitarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, '«Finst det ingen Herrens profet her?» sagde Josafat, «so me kann spyrja Herren gjenom honom!» Ein av tenarane åt Israels-kongen svara: «Jau, Elisa Safatsson er her, han som helte vatn yver henderne åt Elia.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, '«I hans eige er Herrens ord,» sagde Josafat. Gjekk dei so ned til honom, Israels-kongen og Josafat og Edom-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Men Elisa svara Israels-kongen: «Kva vil du meg? Gakk du til profetarne åt far din og profeterne åt mor di!» «Seg ikkje so!» svara Israels-kongen; «du skyner Herren hev stemnt i hop desse tri kongarne til å gjeva deim i henderne på Moab.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Då svara Elisa: «So sant Herren, allhers drott, liver, han som eg tener: hadde det ikkje vore for Juda-kongen Josafat skuld, nei menn um eg vilde anten vyrda eller varast deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Men no kann du henta ein harpespelar åt meg.» Då harpespelaren leika på harpa, kom Herrens Ande yver honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Og han sagde: «So segjer Herren: «Grav grop på grop i denne dalen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'For so segjer Herren: Ikkje ser de vind, og ikkje ser de regn; men denne dalen vert full av vatn; sjølve fær de drikka, og heren dykkar og dyri dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Men dette tykkjest Herren for lite; difor vil han gjeva Moab i dykkar hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Alle faste byar og kvar storby skal de taka; kvart aldetre skal de fella, kvar ei uppkoma skal de kasta att, kvar grøderik åker skal de tyna med stein.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Andre morgonen, den tid dei bar fram grjonofferet, kom det vatn frå Edom-leitet, og landet vart fullt av vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Då alle moabitarne frette at kongarne drog i krig mot deim, baud dei ut alle våpnføre folk og vel so det, og fylkte seg attmed landskilet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Tidleg um morgonen då soli rann og skein på vatnet, tykte moabitarne frå sin synsstad, at vatnet såg ut som blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, '«Det er blod!» ropa dei; «det er tydelegt at kongarne hev tynt kvarandre i strid innbyrdes! No er herfang å få, moabitar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Då dei kom til Israels-lægret, ruste israelitarne på og slo moabitarne, so dei tok til rømings. So fall dei inn i Moabiterlandet og slo deim heilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Byarne braut dei ned, på alle dei grøderike åkrarne kasta dei kvar sin stein og steina deim ned, kvar ei uppkoma kasta dei att, kvart eit aldetre felte dei, til dess ikkje anna var att enn steinmurarne i Kir-Hareset; og det kringsette slyngjekastarane og skaut på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Då Moab-kongen såg at han ikkje kunde standa seg i striden, tok han sju hundrad mann våpnføre mann med seg og vilde slå seg igjenom fram til Edom-kongen. Men det mislukkast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Då tok han fyrstefødde son sin som skulde verta konge i staden hans, og ofra honom på muren til brennoffer. Og ein stor harm råka Israel, so dei laut brjota upp derifrå og snu heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Ei kvinna som var gift med ein profetsvein, ropa til Elisa: «Mannen min, tenaren din er dåen. Du veit sjølv att han har age for Herren. No kjem kravsmannen og vil taka båe sønerne mine til trælar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa svara til henne: «Kva kann eg gjera for deg? Seg meg, kva du hev i huset?» Ho svara: «Ingenting hev tenestkvinna di i huset anna ei krus med olje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Då sagde han: «Gakk ut til alle grannarne dine og få lånt deg kaggar, tome kaggar, di fleire di betre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Gakk so inn, steng døri etter deg og sønerne dine, slå i alle desse kaggarne, og ber deim burt etter kvart dei vert fulle!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Gjekk ho då frå honom, og stengde døri etter seg og sønerne sine; dei bar fram, og ho slo i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Då kaggarne var fyllte, bad ho son sin koma med endå ein. «Her er ikkje fleire,» svara han. Då traut oljen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Ho kom og melde til gudsmannen. «No kann du selja oljen,» sagde han, «og greida skuldi di, og resten kann du og sønerne dine liva av.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Det bar so til ein dag at Elisa kom yver til Sunem. Der var ei velhaldi kona, som endeleg vilde gjeva honom mat; kvar gong han sidan kom den vegen, tok han inn der og fekk seg mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Ein gong sagde ho med mannen sin: «Sjå, eg skynar at han er ein heilag gudsmann, han som jamt kjem hit til oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Å, lat oss mura upp ei liti loftstova og setja inn til honom der seng og bord og stol og ljosestake, so han kann taka inn der når han kjem til oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Ein dag kom han dit og tok inn i loftstova og lagde seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Han sagde til Gehazi, drengen sin: «Ropa på Sunems-kona!» Han so gjorde, og ho kom upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Han hadde sagt til honom: «Seg med henne: «Du hev no havt all denne umsuti for oss; kva kann då me gjera for deg? Hev du nokor sak eg kann tala for kongen eller herføraren?»» «Nei,» svara ho, «eg bur midt millom folket mitt eige.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, '«Kva kann me gjera for henne?» spurde Elisa. «Å jau,» svara Gehazi, «ho hev ingen son, og mannen hennar er gamall.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, '«Ropa på henne!» sagde han. Han so gjorde, og ho kom i døri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Då sagde Elisa: «Næste år dette bil skal du hava ein son på fanget.» Ho svara: «Å nei, gode herre og gudsmann! du må ikkje ljuga for tenestkvinna di.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Men kona vart med barn, og åtte ein son på nyåret nett det bilet som Elisa hadde sagt med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Då guten vart større, hadde han ein dag gjenge ut til far sin millom skurdfolket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Der tok han til å klaga seg for far sin: «Hovudet mitt! Hovudet mitt!» «Ber honom til mori!» sagde faren til drengen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Han tok og bar honom heim til mori. Han sat på fanget hennar til middagsleite; då slokna han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ho gjekk upp og lagde honom på sengi åt gudsmannen, stengde att og gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'So ropa ho på mannen sin: «Send ein av drengjerne med ei av asnorne,» sagde ho, «so vil eg snøggast fara åt gudsmannen og straks koma heim att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, '«Kvifor vil du fara åt honom i dag?» spurde han; «det er korkje nymåne eller kviledag.» «Det er det same,» svara ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'So sala ho asna og baud drengen sin: «Driv på i eino! Heft meg ikkje burt på vegen! eg skal segja til når eg vil stana.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'So gav ho seg i veg og kom til gudsmannen på Karmelfjellet. Då gudsmannen gådde henne eit stykke burte, sagde han med Gehazi, drengen sin: «Sjå der kjem Sunems-kona!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Spring til møtes med henne og spør henne: «Stend det vel til med deg? Stend det vel til med mannen din? Stend det vel til med vesleguten?»» Ho svara: «Ja, det gjer det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Men då ho kom upp på fjellet til gudsmannen, tok ho um føterne hans. Gehazi for fram og vilde skuva henne burt. Men gudsmannen sagde: «Lat henne vera! Ho hev ei stor sorg. Herren hev løynt for meg kva det er, og ikkje kunngjort meg det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Då sagde ho: «Var det eg som bad deg, herre, um ein son? Bad eg deg ikkje di meir, at du ikkje skulde ljuga for meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Han baud då Gehazi: «Gjer deg reidug, tak staven min i handi, og gakk av stad. Um einkvan møter deg, so helsa ikkje på honom! um einkvan helsar på deg, so svara honom ikkje! Og legg so staven på andlitet til vesleguten!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Men mori heldt fram: «So sant Herren liver, og so sant du liver, eg slepper deg ikkje!» So stod han upp og fylgde henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehazi hadde fare i fyrevegen og hadde lagt staven på andlitet til vesleguten; men ingen ljod, inkje teikn til liv! Gjekk han då attende til møtes med Elisa, og fortalde at guten vakna ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Då Elisa kom inn i huset, fekk han sjå guten låg lik på sengi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Han gjekk inn, stengde døri og bad til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'So steig han upp og lagde seg yver guten, med sin munn mot hans munn, med sine augo mot hans augo, og med sine hender mot hans hender. Med han soleis bøygde seg yver honom, vart gutekroppen varm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'So gjekk han endå ein gong att og fram yver golvet, og då han so steig upp og bøygde seg yver honom, so naus guten sju gonger, og slo upp augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Han ropa på Gehazi: «Ropa på Sunems-kona!» sagde han. Han so gjorde. Ho kom upp. «Der skal du få guten din,» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Ho gjekk inn, fall ned for føterne hans og lagde seg å gruve på golvet, tok so guten sin og gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisa kom att til Gilgal medan det var svolt i landet. Med han sit der millom profetsveinarne, segjer han med drengen sin: «Set den store gryta, og koka velling åt profetsveinarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Ein av deim gjekk då ut på marki og sanka urter. Han fann ein vild-vindel og sanka av honom ville agurkar, kappa full. Då han kom inn, skar han deim upp i småskivor uppi gryta, han visste ikkje betre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'So auste dei upp åt kararne, so dei fekk eta. Men då dei tok til og åt av vellingen, skreik dei upp og ropa: «Dauden er i gryta, du gudsmann!» Og dei kunde ikkje eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, '«Kom med mjøl!» sagde han, og då han hadde havt det upp i gryta, baud han deim: «Aus upp åt folket, so dei fær eta!» Og då var det ikkje vondt i gryta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Det kom ein mann frå Ba’al-Salisa med fyrstegrøda åt gudsmannen; tjuge byggbrød og nyhausta korn hadde han i posen sin. «Gjev folki å eta!» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, '«Kor kann eg setja fram dette åt hundrad mann?» spurde tenaren. «Gjev folki å eta!» svara han; «Herren segjer: «Dei skal eta og endå leiva.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Og han sette det fram for deim, og dei åt, og dei leivde endå noko, so som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Na’aman heitte ein herførar hjå syrarkongen. Han hadde mykje å segja hjå herren sin og var høgvyrd av alle; for med han førde syrarane, hadde Herren hadde gjeve deim siger. Mannen var ei stor stridskjempa, men spillsjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Ein gong på herjeferd i Israelslandet hadde syrarane millom krigsfangarne teke ei liti gjenta; og ho kom i teneste hjå kona åt Na’aman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Ho sagde med matmor si: «Å gjev husbonden min var hjå profeten i Samaria! So skulde han nok skilja honom med spillsykja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Han gjekk til kongen og fortalde: «So og so hev gjenta frå Israelslandet sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Syrarkongen svara: «Far du! So skal eg senda brev med deg til Israels-kongen.» So for han og tok med seg ti talent sylv og seks tusund lodd gull og ti festklædningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Han bar brevet fram til Israels-kongen. Der stod det: «- - Og no når du fær dette brevet, skal du vita at eg sender Na’aman, tenaren min, til deg, og du skal skilja honom av med spillsykja hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Då Israels-kongen las brevet, reiv han sund klædi sine og ropa: «Tru eg er Gud, so eg hev magt yver daude og liv, sidan han skriv til meg at eg skal skilja ein mann med spillsykja hans? De kann då skyna og sjå at han vil berre egla seg innpå meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Då gudsmannen Elisa spurde at Israels-kongen hadde rive sund klædi sine, sende han bod til kongen med dei ordi: «Kvifor reiv du sund klædi dine? Lat honom koma til meg, so skal han få vita at det finst ein profet i Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Na’aman kom med hestar og vogni, og stana utanfor husdøri åt Elisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elisa sende bod ut til honom med dei ordi: «Far av og lauga deg sju gonger i Jordan, so skal kroppen din verta like god att, so du vert rein.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Na’aman vart harm, og for sin veg. «Eg tenkte han vilde koma ut til meg sjølv,» sagde han, «og stiga fram og ropa til Herren, sin Gud, og strjuka med handi yver den sjuke staden og soleis skilja meg av med spillsykja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Tru ikkje Damaskus-elvarne Abana og Parpar er likare enn alt vatnet i Israel? Tru eg ikkje likso godt kunde verta rein med å lauga meg i deim?» Og han snudde, og for heim i sinne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Men tenarane hans gjekk fram og tala med honom: «Du far! Hadde profeten lagt på deg ein vanskeleg ting, vilde du då ikkje gjort det? Kor mykje meir når han berre segjer til deg: «Lauga deg, so vert du rein.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Då for han ned og dukka seg i Jordan sju gonger, so som gudsmannen hadde sagt. Kroppen hans vart like god att, frisk som ein liten barnekropp; han vart rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Då snudde han attende til gudsmannen, han og heile fylgjet han. Han kom inn til honom og sagde: «Sjå no hev eg røynt at det er ingen Gud på heile jordi utan i Israel. Tak no imot ei gåva av meg, tenaren din.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Han svara: «So sant Herren liver, han som eg tener: eg tek ikkje imot.» Han naudbad honom å taka imot; men han vilde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Då sagde Na’aman: «Sidan du ikkje vil, so gjev meg so mykje mold som eit par muldyr kann bera; for no vil eg ikkje meir ofra brennoffer eller slagtoffer til andre gudar, men berre til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Men ein ting må Herren tilgjeva meg: Når herren min gjeng inn i Rimmons-templet og bøygjer seg ned og bed der, og eg lyt fylgja honom, og eg og bøygjer meg ned i Rimmons-templet samstundes som han gjer det - må då Herren tilgjeva tenaren din dette!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Han svara: «Far i fred!» Og han for frå honom eit stykke veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Då tenkte Gehazi, drengen åt gudsmannen Elisa: «No hev husbond spart denne syraren Na’aman og ikkje teke imot det han hadde med seg. So sant Herren liver, eg spring etter honom og fær honom til gjeva meg eitkvart.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Gehazi sette etter Na’aman. Då Na’aman ser ein koma springande etter, hoppar han ut or vogni, og gjeng imot honom og ropar: «Er noko på ferd?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, '«Nei,» svarar han, «men husbond sender meg med dette bodet: Nett no kom det til meg tvo unge profetsveinar frå Efraimsheidi. Å, gjev deim eit talent sylv og tvo festklædningar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Na’aman svara: «Gjer vel og tak imot tvo talent.» Han nøydde han, og knytte tvo talent sylv inn i tvo pungar, og tok tvo festklædningar og gav tvo av tenarane sine, og dei bar deim fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Men då dei kom til haugen, tok han det frå deim. Han gøymde det i huset og let kararne ganga sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Då han kom inn til husbonden sin, spurde Elisa honom: «Kvar kjem du ifrå, Gehazi?» Han svara: «Ingen stad hev tenaren din vore.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Då sagde han: «Tru eg ikkje fylgde deg i åndi då ein mann snudde seg frå vogni og møtte deg? Er det no tid å taka imot sylv og få seg klæde og oljetre og vinhagar og sauer og bufe og tenarar og ternor?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Spillsykja hans Na’aman skal koma yver deg og ætti di for alle tider.» Og han gjekk ut frå honom, spillsjuk og kvit som snø.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Profetsveinarne sagde med Elisa: «Romet der me sit for di åsyn, er for lite oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Lat oss då få lov å ganga til Jordan og henta kvar sin timberstokk, so vil me byggja oss rom der me kann sitja.» «Ja, gakk de!» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Ein av deim bad honom: «Å, gjer vel og fylg med tenarane dine!» «Eg skal so,» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Han fylgde deim. Då dei kom til Jordan, tok dei til å hogga ned trei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Med ein holdt på å fella ein stokk, datt øksi i vatnet. Han skreik upp: «Å, herre! Det var lånegods!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, '«Kvar datt ho?» spurde gudsmannen. Dei synte honom staden. Han skar av ei grein og kasta henne dit. Då fekk han øksi til å fljota upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, '«Tak henne!» sagde han. Og han rette ut handi og tok henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Syrarkongen låg den tid i ufred med Israel. Når han samråddest med mennerne sine og lagde yver: «Der og der vil eg lægra meg,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'so sende gudsmannen det bodet til Israels-kongen: «Tak deg i vare for å fara den vegen! for der for syrarane ned.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Når so Israels-kongen sende folk til den staden som gudsmannen hadde peika ut og vara honom for, so tok han seg i vare nett der. Dette hende ikkje berre ein og tvo gonger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Av dette kom syrarkongen radt i egse. Han kalla i hop mennerne sine og spurde deim: «Kann de ikkje segja meg kven det er av våre folk som held med Israels-kongen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Ein av mennerne svara: «Nei, herre konge! Det er profeten Elisa i Israel som segjer Israels-kongen dei ting du talar i sengkammerset ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Då sagde han: «Få greida på kvar han heldt seg, so skal eg senda folk og gripa honom.» Dei melde honom: «Han held seg i Dotan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Dit sende han so hestar og vogner og ein stor herstyrke. Dei kom ved natteti og kringsette byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Då tenaren åt gudsmannen reis upp og gjekk ut tidleg næste morgon, fekk han sjå ein herstyrke med hestar og vogner lægra kring byen. Drengen sagde då til honom: «Ai, ei, herre! Kva skal me gjera?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, '«Ver ikkje rædd!» svara han; «det er fleire med oss enn med deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Og Elisa bad og sagde: «Herre, lat upp augo hans, so han kann sjå!» Herren let upp augo på guten, og han fekk sjå fjellet fullt av eldhestar og eldvogner rundt ikring Elisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Då dei so gjekk ned, bad Elisa til Herren: «Å, slå dette folket med blindskap!» Og Herren slo deim med blindskap, so som Elisa hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elisa sagde då til deim: «Dette er ikkje rette vegen, detter er ikkje rette byen! fylg meg, so skal eg føra dykk til den mannen de leitar etter.» So førde han deim til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Då dei so var komne inn i Samaria, bad Elisa: «Herre, lat upp augo på desse, og lat deim sjå!» Herren let upp augo deira, og dei gådde at dei var midt inni Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Då Israels-kongen såg deim, sagde han til Elisa: «Skal eg hogga ned, hogga ned, far?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, '«Nei,» svara han, «det skal du ikkje; plar du hogga ned deim du fangar med sverd eller boge? Set fram åt deim mat og drikka, lat deim eta og drikka, og lat deim so fara attende til herren sin!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Han kosta på deim eit stort gjestebod; og då dei hadde ete og drukke, let han deim ganga. Og dei for attende til herren sin. Sidan kom det ikkje fleire syriske herjeflokkar inn i Israelslandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'No hende de seg sidan at Benhadad, syrarkongen, stemnde saman heile heren sin og drog upp og kringsette Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Medan dei kringsette byen, vart det so stor hunger i Samaria, at eit asenhovud kosta til sist åtteti sylvdalar, og fjordeparten av ei kanna med duvemøk fem sylvdalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Ein dag Israels-kongen gjekk ikring på muren, var det ei kvinna som ropa på honom: «Hjelp, herre konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Han svara: «Hjelper ikkje Herren deg, kvar skal då eg henta hjelpi di frå? Frå treskjarvollen? eller frå vinpersa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Kva er i vegen med deg?» spurde kongen. Ho svara: «Denne kona her sagde med meg: «Kom med son din, so skal me eta honom i dag, so kann me eta son min i morgon!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'So koka me son min og åt honom upp. Men då eg andre dagen sagde til henne: «Kom med son din, so me kann eta honom!» då løynde ho son sin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Då kongen høyrde det kona sagde, reiv han sund klædi sine, medan han gjekk der på muren; og folk fekk sjå han gjekk med sekkjety innunder næmast kroppen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Og han svor: «Gud late meg bøta no og sidan, um hovudet skal sitja på Elisa Safatsson dagen til endes!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Sende han so ein fyre seg til Elisa, der han sat i heimen saman med dei øvste. Men fyrr bodet kom til honom, sagde han med dei øvste: Skynar de at denne mordarsonen hev sendt ein mann hit til å taka hovudet mitt? Sjå no til og lat att døri, og haldt henne stengd når bodet kjem! Høyrer det ikkje stigi til herren hans bak honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Medan han tala soleis med deim, såg dei bodet koma ned til honom med dei ordi: «Sjå for ei ulukka Herren hev sendt! kvifor skal eg då bia på Herren meir?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Elisa svara: «Høyr Herrens ord! So segjer Herren: «I morgon dette bil skal dei på torget i Samaria få tvo settungar fint mjøl for ein dalar og fire settungar bygg for ein dalar.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Då tok hermannen som kongen studde seg på til ords og svara gudsmannen: «Um so Herren laga lukor på himmelen, so vilde sovore vera ugjerande!» Han svara: «Du skal få sjå det med eigne augo, men du fær eta av det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Utanfor byporten heldt seg fire spillsjuke menner. Dei sagde med kvarandre: «Kvifor skal me sitja her til me døyr?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Tek me den rådi å ganga inn i byen, so er det svolt i byen, og so døyr me der. Og vert me sitjande her, so døyr me og. Kom, lat oss heller ganga ut og gjeva oss yver til syrarlægret; let dei oss liva, so liver me; drep dei oss, so døyr me.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Dei gav seg på veg i skumingi ut til i syrarlægret. Då dei kom til utkanten av lægret, fekk dei sjå det var ingen der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Herren hadde late syrarlægret høyra ljod av vogner og hestar og ein stor her. Dei hadde sagt med kvarandre: «Å, Israels-kongen hev leigt hetitarkongarne og egyptarkongarne til å taka på oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Og dei hadde teke flugti i skumingi og rømt frå tjeldi sine og hestarne og asni sine og frå lægret slik som det stod; dei hadde rømt på harde livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Då desse spillsjuke kom til utkanten av lægret, gjekk dei inn i eit tjeld og åt og drakk, og tok der sylv og gull og klæde, som dei gjekk av og gøymde. Sidan kom dei att og gjekk inn i eitt anna tjeld og tok det som der var og gjekk av gøymde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Men so sagde dei med kvarandre: «Det er ikkje rett soleis som me fer åt. I dag kann me bera fram fagnadbod; me dreg skuld på oss um me tegjer og drygjer til morgons til det dagast. Kom, lat oss fortelja det i kongsgarden!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Dei gjekk då og ropa til portvakti og fortalde: «Me kom ut i syrarlægret; det fanst inkje menneskje å sjå der; og ingi mannsrøyst var å høyra der; men hestarne og asni stod tjora, og tjeldi stod som dei plar standa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Portvakti ropa tidendi ut, og ho vart fortald heilt inn i kongsgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Kongen reis då upp nattetid og sagde med mennerne sine: «Eg skal segja dykk kva syrarane hev i emning mot oss: Dei veit me svelt; so hev dei fare frå lægret og løynt seg uti marki; dei tenkjer me vil ganga ut or byen, so dei fangar oss livande og gjeng inn i byen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Då svara ein av mennerne hans: «Lat oss taka fem av dei hestarne me hev att her inne - det kann ikkje ganga deim verre enn heile hopen av israelitar som er att her, eller verre enn heile hopen av israelitar som alt hev sett livet til - lat oss so senda bod av stad og sjå etter!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'So tok dei tvo vogner med hestar fyre. Kongen sende deim ut etter syrarheren. «Far av stad og sjå!» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Dei for etter deim alt til Jordan, og fekk sjå heile vegen strådd med klæde og våpn som syrarane hadde kasta frå seg i hurten og sturten. Sendebodi kom att og melde det til kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Folket gjekk då ut og plundra syrarlægret. Og soleis kom tvo settungar fint mjøl til å kosta ein dalar, og fire settungar bygg ein dalar, som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Kongen sette den hermannen som han studde seg på, til å halda orden på torget. Men folket tråkka honom ned der på torget, og han døydde, soleis som gudsmannen hadde sagt, som han sagde då kongen kom ned til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Og det gjekk so som gudsmannen hadde sagt med kongen: «Fire settungar bygg skal dei få for ein dalar, og tvo settungar fint mjøl for ein dalar, på torget i Samaria i morgon dette bilet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Det var då hermannen svara gudsmannen: «Um so Herren laga lukor på himmelen, vilde sovore vera ugjerande.» Og han svara: «Du skal få sjå det med eigne augo, men du fær ikkje eta av det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Det gjekk honom so; folket trakka honom ned på torget, og det vart banen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisa sagde med mor åt den guten han hadde gjort livande: «Ferda deg til, og far burt, du og huslyden din, og set bu kvar helst det buande er! for Herren hev sendt bod etter hungersnaudi, ho er alt komi og skal vara sju år.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Kona ferda seg til, og gjorde som gudsmannen sagde. Ho og huslyden hennar for ut, og sette bu i Filistarlandet i sju år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Då dei sju åri var lidne, kom ho attende frå Filistarlandet. Og gav seg i veg til kongen til å beda um å få att heimen og jordeigedomen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Kongen heldt just på å tala med Gehazi, drengen åt gudsmannen, og bad honom fortelja um alle dei storverki Elisa hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Medan han heldt på og fortalde kongen korleis han gjorde den daude guten livande, nett i det same kom mor åt den guten og bad kongen um heimen og jordeigedomen sin. «Herre konge!» sagde Gehazi, «der er kona; og der er son hennar, som Elisa gjorde livande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Kongen spurde kona ut, og ho fortalde. So let kongen henne få ein av hirdmennerne med seg og baud honom: «Hjelp henne til å få att alt som høyrer henne til, og all avlingi av eigedomen frå den dagen ho for frå landet og til no!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Elisa kom til Damaskus, medan syrarkongen Benhadad låg sjuk. Då kongen spurde at gudsmannen var komen dit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'sagde han med Hazael: «Tak med deg gåvor, gakk til møtes med gudsmannen og spør Herren gjenom honom um eg skal koma meg av denne sjukdomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hazael so gjorde, tok med seg gåvor, alt det likaste som i Damaskus var, so mykje som fyrti kamelar kunde bera. Han gjekk fram for Elisa og sagde: «Son din, syrarkongen Benhadad, sender meg til deg og spør um han skal koma seg av denne sjukdomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa svara honom: «Du kann segja med honom at han skal koma seg. Men Herren syner meg at han skal døy.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Medan han stod framfyre honom og nistirde, sette gudsmannen i og gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, '«Kvifor græt du, herre?» spurde Hazael. «For di eg veit kor mykje ilt du vil gjera mot Israels-borni,» svara han; «dei faste byarne set du eld på, unggutarne deira myrder du med sverd, småborni krasar du, og barnkonorne skjer du upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hazael sagde: «Korleis kann vel tenaren din, slik ein hund som eg er, gjera sovorne storverk?» Elisa svara: «Herren hev synt meg at du vert konge yver Syria.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Han gjekk då frå Elisa heim att til herren sin. «Kva sagde Elisa med deg?» spurde han. «Han sagde med meg at du skal verta god att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Men so dagen etter tok han eit åklæde, duppa det i vatn og breidde det yver andlitet hans; det vart banen hans. Og Hazael vart konge etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'I femte styringsåret åt Israels-kongen Joram Ahabssons, medan Josafat var konge i Juda, vart Joram Josafatsson konge i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Tvo og tretti år gamall var han då han vart konge, og åtte år var han konge i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Han for fram liksom Israels-kongarne og Ahabs hus; for han var gift med ei dotter til Ahab. Han gjorde det som vondt var i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Men Herren vilde ikkje tyna Juda for sin tenar David skuld, etter di han hadde lova honom at det alle dagar skulde lysa ei lampa for honom og sønerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'I hans tid reiv edomitarne seg laus frå Juda og kåra seg ein konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Då drog Joram av til Sa’ir med alle stridsvognerne sine. Og han tok um natti og slo edomitarne som kringsette honom, og hovudsmennerne yver vognerne, og herfolket flydde heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'So kom edomitarne seg laus frå Juda, og er frie den dag i dag. Nett samstundes reiv Libna seg og laus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Det som elles er å fortelja um Joram og alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Joram lagde seg til kvile hjå federne sine og vart gravlagd hjå federne sine, i Davidsbyen. Ahazja, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'I det tolvte året åt Israels-kongen Joram Ahabsson vart Ahazja Joramsson konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Tvo og tjuge år gamall var Ahazja då han vart konge; eitt år var han konge i Jerusalem. Mor hans heitte Atalja, dotter åt Israels-kongen Omri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Han gjekk i fotefari åt Ahabs hus, og gjorde det som vondt var i Herrens augo, etter gjerdi åt Ahabs hus; for han stod i skyldskap til Ahabs hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Saman med Joram Ahabsson for han i herferd mot syrarkongen Hazael ved Ramot i Gilead. Men Joram vart såra av syrarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Kong Joram vende då attende til Jizre’el, og vilde få lækt dei såri han hadde fenge av syrarane, i slaget ved Rama mot syrarkongen Hazael. Og Juda-kongen Ahazja Joramsson drog ned og vilde sjå um Joram Ahabsson i Jizre’el, etter di han låg sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Profeten Elisa kalla til seg ein av profetsveinarne: «Bitt ikring deg beltet, tak denne oljeflaska med deg og gakk til Ramot i Gilead!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Når du kjem dit, skal du leita upp Jehu, son åt Josafat Nimsison. Gakk burtåt honom, bed honom risa upp midt millom brørne sine, og før honom inn i det inste kammerset!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'So skal du taka oljeflaska og renna oljen yver hovudet hans med dei ordi: «So segjer Herren: «Eg hev salva deg til konge yver Israel!»» Dermed skal du opna døri og fly på fljugande flekken.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Guten, profetsveinen, gjekk til Ramot i Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Då han kom tid, fann han herførarane samla. «Eg kjem med eit bod til deg, herførar,» sagde han. «Til kven av oss?» spurde Jehu. «Til deg sjølv, herførar,» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Han reis upp og gjekk inn i huset. Der slo han olje yver hovudet hans med dei ordi: «So segjer Herren, Israels Gud: «Eg hev salva deg til konge yver Herrens folk, yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Slå i hel ætti åt Ahab, herren din! Eg vil hemna blodet åt profetarne, tenarane mine, ja, blodet åt alle Herrens tenarar hemnar eg på Jezabel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Øydast skal heile Ahabs hus. Rydja ut vil eg kvart karmannsemne av Ahabs-ætti, ufri og fri, innan Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Eg fer med Ahabs hus som med huset åt Jerobeam Nebatsson og med huset åt Baesa Ahiason.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Hundarne skal eta upp Jezabel på Jizre’els-vangen; ingen skal jorda henne.»» Dermed opna han døri og flydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Då Jehu kom ut att til hermennerne, spurde dei honom: «Er noko på ferd? Kva var det denne skrullingen vilde deg?» Han svara deim: «De kjenner då sjølve den mannen og skravlet hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, '«Din ljugar!» sagde dei, «seg oss det no!» Då sagde han: «So og so tala han til meg med dei ordi: «So segjer Herren: Eg hev salva deg til konge yver Israel.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Straks tok dei kvar si kappa og breidde under honom på sjølve troppestigi. So bles dei i luren og ropa: «Jehu er konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Soleis fekk Jehu, son åt Josafat Nimsison, i stand ei samansverjing mot Joram. Joram og heile Israel skulde verja Ramot i Gilead mot syrarkongen Hazael;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'men sjølv hadde kong Joram fare attende til Jizre’el og vilde få lekt dei såri han hadde fenge av syrarane i slaget mot syrarkongen Hazael. Jehu sagde: «Um det tykkjer som eg, må ikkje ein einaste sleppa ut or byen og bera tiendi til Jizre’el!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Dermed steig Jehu upp i vogni si og køyrde til Jizre’el; der låg Joram sjuk, og Juda-kongen Ahazja var komen dit ned og vilde sjå um Joram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Då vaktmannen uppi tårnet i Jizre’el såg Jehu-skreidi koma, ropa han: «Eg ser ei skreid!» Då baud Joram: «Få tak i ein ridar, og send honom til møtes med deim, til å spyrja deim um dei kjem for det gode.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Ridaren reid til møtes med honom og ropa: «Kongen spør: «Kjem du for det gode?»» «Kva skil det deg?» svara Jehu; «snu um og fylg etter meg!» Vaktmannen melde: «Sendebodet hev nått deim, og kjem ikkje attende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Han sende so ein annan ridande. Då han nådde deim, ropa han: «Kongen spør: «Kjem du for det gode?»» «Kva skil det deg?» svara Jehu; «snu um og fylg etter meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Vaktmannen melde: «Han nådde deim og kjem ikkje attende. Køyrsla svipar på Jehu Nimsison; for han køyrer som ein galning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, '«Beit fyre!» sagde Joram. Dei beit fyre vogni hans. So drog Joram, Israels-kongen, ut, og Ahazja, Juda-kongen, sameleis, kvar på si vogn; dei køyrde ut til møtes med Jehu, og råka honom på odelsjordi hans Nabot frå Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Då no Joram fekk sjå Jehu, ropa han: «Kjem du for det gode, Jehu?» Han svara: «Kor kann eg koma for det gode, so lenge Jezabel, mor di, fær driva horskapen og trollskapen sin?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Då snudde Joram um og rømde, med han ropa til Ahazja: «Svikferd, Ahazja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Men Jehu treiv bogen sin og skaut Joram millom herdarne, so pili gjekk ut gjenom hjarta hans, og han seig ned i vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'So sagde han til Bidkar, hermannen sin: «Tak og kasta honom på odelsmarki åt Nabot frå Jizre’el! Kom i hug den gongen eg og du reid jamsides etter Ahab, far hans, kor Herren bar upp dette domsordet yver honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '«So visst som eg såg Nabots blod og blodet av sønerne hans i går, segjer Herren: sanneleg, nett på denne odelsmarki skal eg gjeva deg likt for like!» Tak då og kasta honom på odelsmarki, etter Herrens ord!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Då Ahazja, kongen i Juda, såg det, rømde han på vegen til Hagehuset. Jehu sette etter honom og ropa: «Han og! skjot honom i vogni!» Dei råka honom, med han køyrde på fjellvegen til Gur, nær attmed Jibleam. Han rakk so langt som til Megiddo; der døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Tenarane hans køyrde honom til Jerusalem, og jorda honom i fedregravi hans i Davidsbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'I det ellevte styringsåret åt Joram Ahabsson var det Ahazja vart konge yver Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Då Jehu kom til Jizre’el, og Jezabel spurde det, sminka ho augo og sette hovud-prydnad på seg og gav seg til å sjå ut gjenom vindauga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Då Jehu køyrde inn gjenom porten, helsa ho: «Gjeng det vel for Zimri, som myrde herren sin?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Han såg upp mot vindauga og ropa: «Kven er med meg? kven?» Då tvo, tri hirdmenner skyngde ned til honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'sagde han: «Kasta henne ned!» Dei kasta henne ned, og blodet hennar spruta utyver veggen og på hestarne; og dei trakka henne ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'So gjekk han inn og åt og drakk. Sidan baud han: «Sjå etter denne forbanna kvinna, og grav henne ned! Ho er då kongsdotter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Då dei skulde til å gravleggja henne, fann dei inkje att av henne anna hausen og føterne og henderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Då dei kom att og melde honom det, sagde han: «So var Herrens ord, som han tala ved tenaren sin, Elia frå Tisbe: «På Jizre’els-vangen skal hundarne eta Jezabels kjøt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'liket åt Jezabel vert til møk på marki på Jizre’els-vangen, so ingen kann segja: Dette er Jezabel!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Ahab hadde sytti søner i Samaria. Jehu skreiv brev og sende til Samaria, til dei øvste i Jizre’el, til styresmennerne og til dei fosterfeder Ahab hadde sett inn, og der sagde han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '«- - Og når de no fær dette brevet, de som hev hjå dykk sønerne åt herren dykkar, de som råder yver vognerne og hestarne, og hev festning og våpn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'so kåra ut den hævaste og likaste av sønerne åt herren dykkar, og set honom upp på kongsstolen åt far hans, og strid so for ætti åt herren dykkar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Men dei vart reint livrædde. «Når ikkje dei tvo kongarne stod seg mot honom,» sagde dei, «kor kann då me?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Drottseten og byhovdingen og dei øvste og fosterfederne sende det svaret til Jehu: «Dine tenarar er me; alt det du byd oss, gjer me; ingen vil me kåra til konge. Gjer du som du tykkjer sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Då skreiv han eit nytt brev til deim: «Er so det held med meg og lyder mine bod, so hogg hovudi av kongssønerne, og kom til meg i morgon dette bil, til Jizrael!» Dei sytti kongssønerne budde hjå stormennerne i byen, dei som fostra deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Då dei fekk brevet, tok dei kongssønerne og drap deim, alle sytti, lagde so hovudi i korger og sende deim til honom i Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Då han fekk bod at dei var komne med hovudi av kongssønerne, sagde han: «Legg dei i tvo dungar attmed byporten til i morgon!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Morgonen etter for han dit ut, steig fram og tala for folket: «De er skuldlause. Det var eg som fekk i stand samansverjingi mot herren min; det var eg som drap honom; men kven hev slege i hel alle desse?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Skyna då at ikkje eitt av Herrens ord hev vorte til inkjes, av det Herren tala mot Ahabs hus. Herren hev gjort so som han tala ved Elia, tenaren sin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Jehu slo i hel alle som var att av Ahabs hus i Jizre’el, like eins alle stormennerne hans og venerne hans og prestarne hans, so ingen vart att eller slapp undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'So tok han ut og for av stad til Samaria. På vegen dit attmed Gjætar-Bet-Eked');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'råka han på brørne til Ahazja, kongen i Juda. «Kven er de?» spurde han. Dei svara: «Brørne til Ahazja er me; me er på veg og vil helsa på kongssønerne og sønerne åt kongsmori.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, '«Fanga deim livande!» ropa han. Dei so gjorde. Og han drap deim og kasta deim i brunnen i Bet-Eked, tvo og fyrti i talet; ikkje ein av deim vart spard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'På vegen derifrå møtte han på Jonadab Rekabsson. Han helsa og spurde: «Er du likso ærleg i hugen mot meg, som eg er mot deg?» «Ja,» svara Jonadab. «Er du det so gjev meg handi!» Han so gjorde, og dermed drog han honom upp til seg i vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, '«Køyr med meg,» sagde han, «so skal du sjå kor brennhuga eg er for Herren!» So fekk han køyra med honom i vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Då han kom til Samaria, slo han i hel alle som var att av Ahabs hus der i byen; han tynte deim alle, soleis som Herren hadde sagt til Elia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'So stemnde Jehu saman alt folket og tala til deim: «Ahab dyrka Ba’al lite, Jehu vil dyrka honom mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Stemn no i hop til meg alle Ba’als-profetarne, alle dyrkarne hans, og alle prestarne hans, ikkje ein må vanta! for eg etlar halda ein stor offerveitsla for Ba’al; og kvar som vantar, skal bøta med livet.» Jehu gjorde det på svik, av di han vilde rydja ut Ba’als-dyrkararne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jehu baud: «Lys ut ei stor samlingshøgtid for Ba’al!» Dei lyste henne ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Jehu sende bod kring i heile Israel, og alle Ba’als-dyrkararne kom; det var ikkje ein som ikkje møtte. Dei gjekk inn i Ba’als-templet, og Ba’als-templet vart fullt frå ende til annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'So baud han tilsynsmannen yver klædebui: «Tak fram bunader åt alle Ba’als-dyrkararne!» Og han tok fram bunader åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'So gjekk Jehu og Jonadab Rekabsson inn i Ba’als-templet. Han bad Ba’als-dyrkararne agta på og sjå etter at det ikkje fanst nokon av Herrens tenarar millom deim, anna einast Ba’als-dyrkarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'So gjekk dei inn og ofra slagtoffer og brennoffer. Jehu hadde sett åtteti mann utanfor og sagt: «Slepp det undan ein einaste av deim eg gjev i dykkar hende, skal de bøta liv for liv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Då han so var ferdig med å ofra brennofferet, baud Jehu livvakti og kjemporne: «Inn og slå deim i hel! Slepp ingen ut!» Dei hogg deim ned, og kasta ut liki. So trengde livvakti og kjemporne seg inn i det inste av Ba’als-templet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'og kasta ut stolparne i Ba’als-templet og brende deim upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Dei reiv ned Ba’als-sula, og dei reiv ned heile Ba’als-templet, og laga det um til naudturftstad, som finst den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'So øydde Jehu Ba’al ut or Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Men han gav ikkje upp synderne hans Jerobeam Nebatsson, som han hadde forført Israel til: gullkalvarne i Betel og Dan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Herren tala til Jehu: «Av di du gjorde til gagns det som eg tykkjer er rett, med di du gjorde alt det eg hadde etla Ahabs-ætti, so skal barnebarns-borni dine sitja på Israels kongsstol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Men Jehu heldt seg ikkje heilt etter Herrens, Israels Guds, lov; han gav ikkje upp synderne hans Jerobeam, som han hadde forført Israel til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Ved denne tid tok Herren til å skjera stykke or Israel. Hazael slo deim langs heile Israels landskil;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'på austsida av Jordan tok han heile Gileadlandet, Gads-ætti, Rubens-ætti, Manasse-ætti, frå Aroer ved Arnonåi, heile Gilead og Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Det som elles er å fortelja um Jehu, um alt det han gjorde og alle hans storverk, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Jehu lagde seg til kvile hjå federne sine og vart gravlagd i Samaria. Joahaz, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Den tidi Jehu var konge yver Israel i Samaria, var åtte og tjuge år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Då Atalja, mor åt Ahazja, fekk vita at son hennar var dåen, tok ho seg fyre å tyna heile kongsætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Men nett med same kongssønerne skulde lata livet, tok Joseba, dotter åt kong Joram, syster åt Ahazja, fekk taka i Joas Ahazjason og berga honom undan saman med fostermor hans, inn i sengkammerset, og soleis løynde dei honom for Atalja, so han ikkje vart drepen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'So var han hjå henne i Herrens hus, burtgøymd, i seks år, medan Atalja styrde landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'I det sjuande året sende Jojada bod og henta hovudsmennerne for livvakti og førde deim inn til seg i Herrens hus. Og han hadde gjort ein avtale med deim og teke deim i eid der i Herrens hus, synte han deim kongssonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'So baud han deim: «Høyr no korleis de skal fara åt: Den eine tridjepart av dykk som tek vakthaldet på kviledagen, skal halda vakt i kongsgarden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'den andre tridjeparten i Sur-porten, tridje tridjeparten i porten bak drabantarne; de skal greida vakti til vern åt huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Båe dei hine vaktskifti, alle dei av dykk som skulde verta avløyste frå vakt på kviledagen, dei skal halda vakt um kongen i Herrens hus;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'de skal gjera manngard rundt ikring kongen, kvar mann med våpn i hand! kjem nokon innpå rekkjorne, so hogg honom ned! Soleis skal de vera med kongen både når han gjeng ut, og når han gjeng inn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Hovudsmennerne gjorde alt soleis som presten Jojada baud; kvar og ein tok sine folk, både dei som skulde taka ved vakti um kviledagen og dei som skulde ganga frå um kviledagen; dei kom til presten Jojada,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'og presten gav hovudsmennerne dei spjoti og dei skjoldarne som kong David hadde ått, og som var i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Livvakti tok post, kvar med våpn i hand, frå sudsida av huset til nordsida av huset, til altaret, og derifrå til huset att, i manngard kring kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'So leidde han kongssonen ut og sette på honom kruna og gav honom lovi. Dei tok honom til konge og salva honom, klappa i henderne og ropa: «Live kongen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Då Atalja høyrde ropet frå livvakti og folket, gjekk ho til Herrens hus, der folket stod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Der fekk ho då sjå kongen standa på den høge tramen, som skikken var, og hovudsmennerne og lurblåsarane attmed kongen, og alt landsens folk som fegnast og bles i lur. Då reiv Atalja sund klædi sine og ropa: «Samansverjing, samansverjing!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Presten Jojada baud hovudsmennerne, herførarne: «Leid henne ut millom rekkjorne!» sagde han til deim, «og er so nokon fylgjer etter henne, so hogg honom ned!» Presten vilde ikkje ho skulde verta drepi i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Dei tok henne då og førde henne inn i kongsgarden gjenom hesteporten; og der let ho livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Jojada gjorde den pakti millom Herren og kongen og folket, at dei skulde vera Herrens folk. Ogso millom kongen og folket gjorde han semja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Alt landsens folk gjekk so av stad burt til Ba’als-huset og reiv det ned, og altari hans og bilæti krasa dei i mol og mask. Mattan, Ba’als-presten, drap dei framfor altari. So sette Jojada vaktmenner ved Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Deretter tok han med seg hovudsmennerne og livvakti og alt landsens folk, og dei førde kongen frå Herrens hus inn i kongsgarden gjenom livvakt-porten. Han sette seg på kongsstolen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'og alt folket fegnast; og byen kom til ro. Men Atalja hadde dei hogge i hel i kongsgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Sju år gamall var Joas då han vart konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'I det sjuande styringsåret åt Jehu vart Joas konge, og fyrti år rådde han i Jerusalem. Mor hans heitte Sibja, frå Be’erseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Joas gjorde alle sine dagar det som rett var for Herren, med di presten Jojada rettleidde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Berre vart offerhaugarne haldne ved lag; folket heldt ved å ofra slagtoffer og røykoffer på haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Joas gav prestarne det bodet: «Alle pengarne som kjem til Herrens hus i heilage gåvor, ålgjengd mynt, og i løysepengar for einkvan, sameleis alle pengar som einkvan sjølvminnt gjev åt Herrens hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'dei skal prestarne taka imot, kvar av sine kjenningar, og nytta det til å setja i stand det som er forfalle i huset, all stad det finn ein brest.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Men i tri og tjugande styringsåret åt kong Joas hadde ikkje prestarne endå bøtt bresterne i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Kong Joas kalla då til seg presten Jojada og dei andre prestarne: «Kvifor hev de ikkje bøtt bresterne i Herrens hus?» spurde han; «heretter fær ikkje de taka imot pengar av kjenningarne dykkar; de skal lata deim frå dykk, til å bøta på huset.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Prestarne gjekk med på det, at dei skulde ikkje taka imot pengar av folket, og ikkje hava noko med å bøta huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Presten Jojada tok ei kista, bora hol i loket og sette henne jamsides altaret på høgre sida av inngangen til Herrens hus. Og der lagde då prestarne som heldt vakt på dørstokken, alle pengar folk hadde med seg til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'So snart dei såg at det var nøgdi av pengar i kista, gjekk kongens skrivar og øvstepresten dit upp, og knytte i hop alle pengarne som fanst i Herrens hus, talde deim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'og vog deim, og flidde deim åt tilsynsmennerne for arbeidarane ved Herrens hus; dei reidde deim ut til timbremennerne og bygningsmeistrarne som arbeidde på Herrens hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'og til murarane og steinhoggarane, like eins til innkjøp av trevyrke og hoggen stein, til å bøta brester i Herrens hus; stutt sagt: til alle utlogor ved hus-bøtingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Derimot laga dei ikkje sylvfat til Herrens hus for dei pengarne som kom inn i huset, ikkje heller ljosesaksar, skålar eller trompetar av sylv, eller onnor tempelgogn av gull eller sylv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'nei, alt vart gjeve til arbeidarane, og dei nytta det til å bøta Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Dei kravde ingen rekneskap av deim som tok imot pengarne og gav deim til arbeidarane; dei fekk gjera det på tru og æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Men pengar som kom inn for skuldoffer og syndoffer, vart ikkje lagde i Herrens hus; dei gjekk til prestarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Den tid drog syrarkongen Hazael upp og hertok Gat. Hazael etla seg jamvel til ei ferd mot Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Joas, Juda-kongen, tok då alle dei heilage gåvorne som Juda-kongarne Josafat, Joram og Ahazja, federne hans, hadde helga åt Herren, og sine eigne heilage gåvor, og alt gullet som fanst i skattkammeret i Herrens hus, og sende det til syrarkongen Hazael. Og då drog han burt frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Det som elles er å fortelja um Joas og alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Hirdmennerne hans gjorde uppreist, samansvor seg og slo i hel Joas i Millo-bygnaden, som rekk ned mot Silla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Det var Jozakar Sim’atsson og Jozabad Somersson, hirdmennerne hans, som slo honom i hel. Han vart gravlagd hjå federne sine i Davidsbyen; og Amasja, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'I det tri og tjugande styringsåret åt Juda-kongen Joas Ahazjason vart Joahaz Jehuson konge yver Israel i Samaria, og han styrde i syttan år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Han gjorde det som vondt var i Herrens augo; han dreiv på med same synderne som Jerobeam Nebatsson, som han hadde forført Israel til; deim gav han ikkje upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Herren vart brennande harm på Israel; han gav deim i henderne på syrarkongen Hazael og Benhadad Hazaelsson, heile hans stryringstid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Joahaz freista å blidka Herren, og Herren bønhøyrde honom, av di han såg den naudi syrarkongen førde Israel upp i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Herren gav då Israel ein frelsar, so dei slapp ut or syrarveldet, og Israels-borni fekk bu i hyttorne sine som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Like vel gav dei ikkje upp dei synderne som Jerobeams hus hadde forført Israel til; dei dreiv på sameleis; jamvel Astarte-bilætet fekk standa i fred i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Hazael hadde ikkje leivt meir folk åt Joahaz enn femti hestfolk, ti vogner, og ti tusund mann fotfolk. So ille hadde syrarkongen øydt deim ut, knasa deim som gov ved treskjingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Det som elles er å fortelja um Joahaz, um alt det han gjorde og um hans storverk, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Joahaz lagde seg til kvile hjå federne sine og vart gravlagd i Samaria. Joas, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'I det sju og trettiande styringsåret åt Joas, kongen i Juda, vart Joas Joahazson konge yver Israel, og han rådde i Samaria i sekstan år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Han gjorde det som vondt var i Herrens augo. Han gav ikkje upp nokor av dei synderne som Jerobeam Nebatsson hadde forført Israel til; han dreiv på sameleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Det som elles er å fortelja um Joas, um alt det han gjorde og um hans storverk, soleis um krigen han førde mot Amasja, kongen i Juda, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Joas lagde seg til kvile hjå federne sine, og Jerobeam steig upp i kongsstolen hans. Joas vart gravlagd i Samaria saman med Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Då Elisa hadde fenge helsotti, gjekk Joas, kongen i Israel, ned til honom. Han bøygde seg yver honom, gret og ropa: «Far, far! du Israels vogner og ridarar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisa sagde med honom: «Henta ein boge og piler!» Han henta deim til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Baud han so Israels-kongen: «Legg handi di på bogen!» Han so gjorde, og Elisa lagde sine hender på kongens hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'So sagde han: «Lat upp vindauga mot aust!» Då han det hadde gjort, sagde Elisa: «Skjot!» Og han skaut. Då sagde han: «Ei sigers-pil frå Herren! ei sigers-pil mot syrarane! Du skal slå syrarane i Afek og tyna deim heilt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'So sagde han: «Tak pilerne!» Då Israels-kongen hadde teke deim, sagde han til honom: «Slå på jordi!» Han slo tri gonger, og so slutta han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Då vart gudsmannen harm på honom. «Du skulde ha slege fem eller seks gonger,» sagde han; «so vilde du ha tynt syrarane heilt; no kjem du til å slå syrarane tri gonger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Elisa døydde og vart gravlagd. Moabitarflokkar gjorde jamt røvarferder i landet ved nyårsbil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'No hende det just som dei skulde jorda ein mann, at dei fekk sjå ein røvarflokk; so kasta dei mannen i Elisas grav. Og då mannen datt ned og kom innpå beini åt Elisa, so vart han livande att og reis upp på føterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Syrarkongen Hazael heldt Israel i trælldom so lenge Joahaz livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Men Herren miskunna deim og ynkast yver deim, og vende seg til deim for den pakt skuld som han hadde gjort med Abraham, Isak og Jakob; han vilde ikkje øyda deim ut og hadde ikkje endå kasta deim burt frå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Syrarkongen Hazael døydde, og Benhadad, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Då tok Joas Joahazson att frå Benhadad Hazaelsson dei byarne som han hadde teke frå Joahaz, far hans. Tri gonger slo Joas deim, og tok soleis att Israels byar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'I det andre styringsåret åt Israels-kongen Joas Joahazson vart Amasja Joasson konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Fem og tjuge år gamall var han då han tok styret, og ni og tjuge år rådde han i Jerusalem. Mor hans heitte Joaddan, frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Han gjorde det som rett var for Herren; um ikkje so heilt som David, ættarfar hans, so liktest han i alt på Joas, far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Offerhaugarne vart like vel haldne ved lag; folket heldt på og ofra slagtoffer og brende røykjelse på haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'So snart han kjende seg trygg på magti, let han drepa dei hirdmennerne som hadde slege i hel kongen, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Men borni åt dråpsmennerne drap han ikkje, etter fyreskrifti i Mose-lovboki, der Herren hev gjeve dette bodet: «Foreldre skal ikkje lata livet for det borni hev gjort; og born ikkje for det foreldri hev gjort; kvar og ein skal døy for si eigi synd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Han slo edomitarne i Saltdalen, ti tusund mann, og hertok Sela, som han kalla Jokte’el, eit namn det ber den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Ved dette leitet sende Amasja bod til Israels-kongen Joas Joahazson, soneson åt Jehu, med dei ordi: «Kom, lat oss røyna kvarandre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Men Joas, kongen i Israel, sende det svaret Amasja, kongen i Juda: «Tistelen på Libanon sende bod til cederen på Libanon: Gjev dotter di til kona åt sonen min!» Men då flaug villdyri på Libanon yver tistelen og trakka honom ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Visst hev du vunne på edomitarne, og dermed vert du kaut i hugen. Men njot no æra di og sit heime! Kvifor vil du leika med ulukka, til fall for deg sjølv og for folket ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Men Amasja vilde ikkje høyra. So drog Israels-kongen Joas upp. Og dei fekk røyna kvarandre, han og Juda-kongen Amasja, ved Bet-Semes i Judalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Juda-folket tapte for Israels-folket og rømde kvar til sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Og Juda-kongen Amasja Joasson, soneson åt Ahazja, vart teken til fange der ved Bet-Semes av Israels-kongen Joas. Då dei kom til Jerusalem, reiv han ned fire hundrad alner av bymuren, frå Efraimsporten til Hyrneporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'So tok han alt gullet og sylvet og alle kjerald som fanst i Herrens hus og i skattkammeret i kongsgarden, og dessutan gislar. Dermed snudde han heim att til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Det som elles er å fortelja um Joas, um det han gjorde og um hans storverk, um krigen han førde mot Juda-kongen Amasja, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Joas lagde seg til kvile hjå federne sine og vart gravlagd i Samaria saman med Israels-kongarne. Og Jerobeam, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Juda-kongen Amasja Joasson livde femtan år etter Israels-kongen Joas Joahazson var dåen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Det som elles er å fortelja um Amasja, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Dei svor seg saman mot honom i Jerusalem, og han rømde til Lakis, men dei sende folk etter honom dit, og dei drap honom der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Dei førde liket på hesteryggen, og gravlagde honom i Jerusalem, i Davidsbyen, saman med federne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'So tok heile Juda-folket Azarja, ein sekstan års gut, til konge i staden for Amasja, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Han var det som bygde upp att Elat og lagde det under Juda att, etter far hans hadde lagt seg til kvile hjå federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'I det femtande styringsåret åt Juda-kongen Amasja Joasson vart Jerobeam Joasson konge yver Israel, og rådde i Samaria i eitt og fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Han gjorde det som vondt var i Herrens augo, og gav ikkje upp dei synderne Jerobeam Nebatsson hadde forført Israel til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Han var det som vann att for Israel landviddi frå Hamatvegen til Øydemark-havet i samhøve med det ordet Herren, Israels Gud, hadde tala ved tenaren sin, profeten Jona Amittaison frå Gat-Hefer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'For Herren hadde set at Israels naud var ovleg beisk; det var ute med både ufri og fri, og det var ingen som hjelpte Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Herren hadde ikkje sagt at han vilde strjuka ut Israels namn under himmelen; difor hjelpte han deim ved Jerobeam Joasson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Det som elles er å fortelja um Jerobeam, um alt det han gjorde og um hans storverk, um krigarne han førde og landevinningi for Israel som han vann att frå Damaskus og Hamat, det som fyrr hadde høyrt til Juda, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Jerobeam lagde seg til kvile hjå federne sine, hjå Israels-kongarne, og Zakarja, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'I det sju og tjugande styringsåret åt Israels-kongen Jerobeam vart Azarja Amasjason konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Sekstan år gamall var han då han vart konge, og tvo og femti år rådde han i Jerusalem. Mor hans heitte Jekolja, frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Han gjorde det som rett var for Herren, plent som Amasja, far hans, hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Like vel vart offerhaugarne halde ved lag; folket held ved å ofra slagtoffer og brenna røykjelse på haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Herren hemsøkte kongen, so han vart spillsjuk til sin døydande dag; og han budde i eit hus for seg sjølv. Jotam, kongssonen, stod fyre kongehuset og styrde landslyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Det som elles er å fortelja um Azarja og alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Azarja lagde seg til kvile hjå federne sine og vart gravlagd hjå federne sine i Davidsbyen. Jotam, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'I det åtte og trettiande styringsåret åt Juda-kongen Azarja vart Zakarja Jerobeamsson konge yver Israel, og rådde i Samaria i seks månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Han gjorde det som vondt var i Herrens augo, liksom federne hans; han gav ikkje upp dei synderne som Jerobeam Nebatsson hadde forført Israel til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Sallum Jabesson fekk i stand ei samansverjing mot honom, og slo honom i hel medan folket såg på; so vart han konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Det som elles er å fortelja um Zakarja, sjå det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Uppfyllt vart soleis det ordet som Herren tala til Jehu: «Sønerne dine i fjorde ættleden skal sitja på Israels kongssæte.» So gjekk det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum frå Jabes vart konge i det ni og trettiande styringsåret åt Uzzia, Juda-kongen, og rådde ein månads tid i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Då drog Menahem Gadison upp frå Tirsa til Samaria, og slo der i hel Sallum Jabesson og vart so konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Det som elles er å fortelja um Sallum, og samansverjingi han fekk i stand, sjå det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Ved den tid herja Menahem Tifsah og alt folket der i heile landviddi deira, frå Tirsa; han herja deim, av di dei ikkje hadde uppna portarne for honom; alle barnkonorne skar han upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'I det ni og trettiande styringsåret åt Azarja, kongen i Juda, vart Menahem Gadison konge yver Israel. Ti år rådde han i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Han gjorde det som vondt var i Herrens augo alle sine dagar, og gav ikkje upp synderne som Jerobeam Nebatsson hadde forført Israel til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Då assyrarkongen Pul fall inn i landet, gav Menahem Pul tvo og eit halvt tusund vågar sylv for at han skulde hjelpa honom og tryggja kongedømet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Dei pengarne Menahem gav assyrarkongen, fekk han inn ved skatt på alle rikmennerne i Israel: femti lodd sylv på kvar og ein. So snudde assyrarkongen att og heldt seg ikkje meir der i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Det som elles er å fortelja um Menahem og alt det han gjorde, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menahem lagde seg til kvile hjå federne sine, og Pekahja, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'I det femtiande styringsåret åt Azarja, kongen i Juda, vart Pekahja Menahemsson konge yver Israel, og rådde tvo år i Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Han gjorde det som vondt var i Herrens augo, og heldt ved med synderne som Jerobeam Nebatsson hadde forført Israel til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Pekah Remaljason, hovudsmannen hans, fekk i stand ei samansverjing mot honom, og drap honom og Argob og Arje i Samaria, i sjølve kongsborgi. Han hadde femti Gileads-menner med seg; og då han hadde drepe honom, vart han konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Det som elles er å fortelja um Pekahja og alt det han gjorde, sjå det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'I det tvo og femtiande styringsåret åt Azarja, kongen i Juda, vart Pekah Remaljason konge yver Israel, og rådde i Samaria i tjuge år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Han gjorde det som vondt var i Herrens augo og heldt ved med synderne åt Jerobeam Nebatsson, som han hadde forført Israel til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'I dei dagarne Pekah var konge i Israel, kom assyrarkongen Tiglat-Pileser og hertok Ijon, Abel-Bet-Ma’aka, Janoah, Kedes, Hasor, Gilead og Galilæa, heile Naftalilandet, og førde folket burt til Assyria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Hosea Elason fekk i stand ei samansverjing mot Pekah Remaljason og slo honom i hel; so vart han konge i staden hans, i det tjugande styringsåret åt Jotam Uzziason.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Det som elles er å fortelja um Pekah og alt det han gjorde, sjå det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'I det andre styringsåret åt Israels-kongen Pekah Remaljason vart Jotam Uzziason konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Fem og tjuge år gamall var han då han vart konge, og sekstan år rådde han i Jerusalem. Mor hans heitte Jerusa Sadoksdotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Han gjorde det som rett var for Herren liktest i all sin ferd på Uzzia, far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Like vel vart offerhaugarne halde ved lag; endå ofra folket slagtoffer og brende røykjelse på haugarne. Han var det som bygde øvre porten i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Det som elles er å fortelja um Jotam og alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Ved den tid tok Herren til å senda syrerkongen Resin og Pekah Remaljason inn i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Jotam lagde seg til kvile hjå federne sine, og vart gravlagd hjå federne sine i byen åt David, far sin. Og Ahaz, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'I det syttande styringsåret åt Pekah Remaljason vart Ahaz Jotamsson konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Tjuge år gamall var Ahaz då han vart konge, og sekstan år rådde han i Jerusalem. Han gjorde ikkje det som rett var for Herren, hans Gud, som David, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Han gjekk i fotefari til Israels-kongarne, ja, han vigde jamvel son sin i elden, likt med dei avstyggjelege skikkarne hjå dei folki Herren hadde rudt ut for Israels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Han ofra slagtoffer, brende røykjelse på haugarne og på bakkarne, og under kvart grønt tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'På den tid drog syrarkongen Resin og Israels-kongen Pekah Remaljason upp og vilde hertaka Jerusalem. Dei kringsette Ahaz, men vann ikkje taka byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Samstundes vann syrarkongen Resin Elat attende til Syria. Då han hadde kasta Juda-folki ut or Elat, kom syrarfolk kom og busette seg der, og der bur dei den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Ahaz sende bod til assyrarkongen Tiglat-Pileser med dei ordi: «Eg er din træl og din son. Kom upp, og frels meg frå syrarkongen og Israels-kongen, som hev teke på meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Ahaz tok det sylvet og gullet som fanst i Herrens hus og skattkammeret i kongsgarden og sende det til gåva åt assyrarkongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Assyrarkongen lydde honom, og assyrarkongen drog upp mot Damaskus, hertok byen og førde folket burt til Kir; og Resin slo han i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Kong Ahaz for til Damaskus til møtes med assyrarkongen Tiglat-Pileser. Då han fekk sjå altaret i Damaskus, sende kong Ahaz bilæte av altaret og eit fullkome mynster av det til presten Uria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Og presten Uria bygde altaret; heilt etter den fyreskrift kong Ahaz hadde sendt frå Damaskus, soleis gjorde presten Uria det ferdigt, til dess kong Ahaz kom heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Då kongen kom heim frå Damaskus og fekk sjå altaret, gjekk han innåt, steig upp på det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'brende brennofferet og grjonofferet sitt, helte ut drykkofferet sitt og skvette blodet av takkofferi sine på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Men koparaltaret som stod framfor Herrens åsyn, flutte han frå staden sin framfyre huset, millom Herrens hus og det nye altaret, og sette det på nordsida av dette altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Kong Ahaz baud presten Uria: «På storaltaret skal du brenna brennofferet um morgonen og grjonofferet um kvelden, kongens brennoffer og grjonoffer, og brennofferet for heile landslyden og grjonofferet deira og drykkofferet deira; alt blod av brennoffer og alt blod av slagtoffer skal du hella ut der. Kva eg vil gjera med koparaltaret, skal eg tenkja næmare etter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Presten Uria gjorde plent som kong Ahaz baud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Kong Ahaz braut laus listerne på fotstykki og tok baljorne ned derifrå; havet lyfte han ned frå koparuksarne som stod under, og sette det på eit steingolv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Kviledags-svalgangen som dei hadde bygt i huset, og den ytre konge-inngangen lagde han inn i Herrens hus for assyrarkongen skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Det som elles er å fortelja um Ahaz, det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Ahaz lagde seg til kvile hjå federne sine og vart gravlagd hjå federne sine i Davidsbyen. Og Hizkia, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'I det tolvte styringsåret åt Ahaz, kongen i Juda, vart Hosea Elason konge yver Israel, og han rådde i ni år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Han gjorde det som vondt var i Herrens augo, då ikkje so ille som Israels-kongarne fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Mot honom drog assyrarkongen Salmanassar upp. Hosea vart lydkonge under honom og laut leggja skatt åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Men då assyrarkongen vart vis med at Hosea for med svik, med di han sende bod til egyptarkongen So, og slutta greida ut den årvisse skatten til assyrarkongen, tok assyrarkongen honom til fange og kasta honom i fengsel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Og assyrarkongen drog upp mot heile landet, og drog upp og kringsette Samaria i tri år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'I niande styringsåret åt Hosea tok han Samaria og førde Israel burt til Assyria og busette deim i Halah, ved Gozanåi Habor, og i byarne i Media.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Soleis gjekk det, av di Israels-borni synda mot Herren, sin Gud, han som hadde ført deim upp frå Egyptarlandet og fria deim ut or handi åt Farao, egyptarkongen; dei ottast andre gudar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'og for etter sed og skikk hjå dei folki Herren hadde drive ut for Israels-borni, og etter dei skikkarne som Israels-kongarne hadde skipa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Ja, Israels-borni gjorde mangt uhøvelegt mot Herren, sin Gud; dei bygde seg offerhaugar i alle byarne sine, frå det minste vakttårn til fastaste borgi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'dei reiste upp minnesteinar og Astarte-stolpar på kvar ein høg haug og under kvart grønt tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'På alle haugarne brende dei røykjelse, liksom dei folki Herren hadde drive burt for deim, og dei harma Herren med si illferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Dei tente steingudarne, det som Herren hadde sagt dei ikkje måtte gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Herren vara både Israel og Juda ved alle profetarne og sjåarane sine: «Vend um frå dei vonde vegarne dykkar og haldt mine bod og mine fyreskrifter etter heile den lovi som eg baud federne dykkar, og som eg sende til dykk ved tenarane mine, profetarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Men dei lydde ikkje. Dei var likso hardnakka som federne sine, som ikkje trudde på Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Dei vanda lovarne hans, brydde seg ikkje um den pakti han hadde skipa med federne deira, og dei fyresegnerne han hadde gjeve deim. Dei gjekk etter fåfengde avgudar og for med det som fåfengt er, liksom grannefolki, endå Herren hadde bode deim at dei skulde ikkje fara soleis åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Dei vende seg frå alle bodi som Herren, deira Gud, hadde gjeve, og laga seg støypte gudebilæte, tvo kalvar. Dei laga Astarte-stolpar, dei bøygde kne for himmelheren og tente Ba’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Attåt dette vigde dei sønerne og døtterne sine i elden, og for med spådomskunster og trollkunster. Dei selde seg til å gjera det som vondt var i Herrens augo, so dei harma honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Difor vart Herren ovleg harm på Israel og støytte deim frå seg. Det vart inkje att einast Juda-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ikkje heller Juda heldt Herrens, sin Guds bod, men for etter Israels skikkar, som dei hadde skipa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Då støytte Herren frå seg heile Israels-ætti, og tukta deim og gav deim i henderne på røvarar, til dess han kasta deim burt frå si åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Han hadde rive Israel laus frå Davids hus; dei tok Jerobeam Nebatsson til konge; og Jeroboam fekk Israel til å falle frå Herren og forførde deim til stor synd;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'og israelitarne dreiv på med alle dei synderne Jerobeam gjorde; dei gav deim ikkje upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'På resten støytte Herren Israel frå seg, som han hadde sagt ved alle tenarane sine, profetarne. Israel laut fara burt frå landet sitt til Assyria. Der er dei den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Assyrarkongen flutte folk frå Babel og Kuta og Avva og Hamat og Sefarvajim, og busette deim i Samaria-byarne i staden for Israels-borni. Dei tok då Samaria i eige og sette bu i byarne der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Og det hende seg, at i fyrstningi dei budde der, hadde dei ingen age for Herren. Herren sende då løvor som herja millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Det vart meldt åt assyrarkongen: «Dei folki som du flutte burt og busette i Samaria-byarne, dei kjenner ikkje rette måten å dyrka landsens gud; difor hev han sendt løvor millom deim; og dei drep folket ned, av di dei ikkje kjenner rette måten å dyrka landsens gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Assyrarkongen gav då det bodet: «Lat ein av dei burtførde prestarne fara dit heim att og busetja seg der og læra folket å dyrka landsens gud på rette måten!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Ein av prestarne som var burtførde frå Samaria, kom då og sette bu i Betel. Han lærde deim korleis dei skulde ottast Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Det var nok so at kvart folk laga seg sin gud og sette upp på haugarne i dei husi som Samaria-folki hadde bygt, kvart folk i sin by, der dei hadde busett seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'folk frå Babel laga seg ein Sukkot-Benot, folk frå Kut ein Nergal, folk frå Hamat ein Asima,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'avvitarne laga seg ein Nibhaz og ein Tartak, og sefarvitarne brende borni sine i eld for Adrammelek og Anammelek, Sefarvajim-gudarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Men dei bar og age for Herren. Dei valde seg ut offerhaug-prestar kvar or sin flokk, og dei ofra for deim i husi på haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Dei bar age for Herren; men dei tente samstundes sine eigne gudar, etter skikken hjå dei folki som dei var burtførde frå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Den dag i dag fer dei etter dei same gamle skikkarne sine; dei ber ikkje age for Herren, so dei fer etter sine fyreskrifter og rettar, og etter den lov og det bod som Herren gav borni åt Jakob, han som fekk namnet Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Herren gjorde ei pakt og gav deim sovore bod: «Andre gudar skal det ikkje hava age for, og ikkje bøygja kne for deim eller tena deim eller ofra til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Men Herren, som førde dykk upp frå Egyptarlandet med stor kraft og med strak arm, honom skal de bera age for, honom skal de bøygja kne for, honom skal de ofra til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Og dei fyreskrifter og rettar, og den lov og det bod som han let skriva for dykk - deim skal de taka vare på og halda alle dagar; men de skal ikkje bera age for andre gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Den pakti eg gjorde med dykk, må de ikkje gløyma. De må ikkje bera age for andre gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Nei, ber age for Herren, dykkar Gud, so skal han fria dykk frå alle dykkar fiendar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Men dei vilde ikkje høyra, men for fram på same vis som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'So bar desse folki age for Herren, men tente samstundes gudebilæti sine. Og borni og barneborni deira gjer den dag i dag so som federne deira gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'I det tridje styringsåret åt Israels-kongen Hosea Elason vart Hizkia Ahasson konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Fem og tjuge år gamall var han då han vart konge, og ni og tjuge år rådde han i Jerusalem. Mor hans heitte Abi Zakarjadotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Han gjorde det som rett var i Herrens augo, heilt so som David, far hans, hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Han fekk burt offerhaugarne, slo sund minnesteinarne, hogg ned Astarte-stolparne, og knasa koparormen som Moses hadde laga; for alt til den tid hadde Israels-borni brent røykjelse for honom, og dei kalla honom Nehustan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'På Herren, Israels Gud, leit han. Millom alle Juda-kongarne fanst ikkje maken hans, korkje fyre eller etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Han heldt seg til Herren, veik ikkje frå honom, men heldt hans bod, som Herren hadde bode Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Og Herren var med honom so han hadde framgang i alt han tok seg fyre. Han fall ifrå assyrarkongen og vilde ikkje vera tenaren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Og so vann han filistarane og tok landet alt til Gaza og bygdi derikring, frå minste vakttårnet til fastaste borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'I fjorde styringsåret åt kong Hizkia - det var sjuande styringsåret åt Israels-kongen Hosea Elason - drog assyrarkongen Salmanassar upp og kringsette Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Dei tok byen då tri år var lidne; i det sette styringsåret åt Hizkia og det niande styringsåret åt Hosea, kongen i Israel, vart Samaria teken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Assyrarkongen førde Israel burt til Assyria og busette deim i Halah og ved Gozanåi Habor, og i byarne i Media.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Det var av di dei ikkje høyrde på Herren, sin Gud, men braut hans pakt, alt det som Moses, Herrens tenar, hadde bode; dei korkje høyrde eller livde etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'I det fjortande styringsåret åt kong Hizkia drog assyrarkongen Sankerib upp og hertok alle faste borger i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Juda-kongen Hizkia sende då bod til Lakis til assyrarkongen med dei ordi: «Eg hev synda; snu um att frå meg! Det du legg på meg, skal eg bera:» Assyrarkongen lagde då på Hizkia, Juda-kongen, åtte hundrad vågar sylv og åtteti vågar gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Hizkia gav ut alt sylvet som fanst i Herrens hus og i skattkammeret i kongsgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Samstundes braut Hizkia laus gullet på dørerne i Herrens tempel og av dørstolparne som Hizkia, Juda-kongen, hadde klædt med gull, og gav det til assyrarkongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Men so sende assyrarkongen Tartan og Rabsaris og Rabsake med ein stor her frå Lakis mot kong Hizkia i Jerusalem, og dei drog upp og kom til Jerusalem. Då dei hadde fare upp og var komne dit, stana dei attmed vatsleidingi frå Øvredammen på allfarvegen til vaskarvollen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Då dei kravde å få tala med kongen, gjekk drottseten Eljakim Hilkiason og riksskrivaren Sebna og kanslaren Joah Asafsson ut til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Rabsake sagde med deim: «Meld til Hizkia: «So segjer storkongen, assyrarkongen: Kva er det for tru som gjer deg so traust?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'du tenkjer at berre eit ord gjer råd og dåd i krig! Kven lit du på, sidan du sette upp imot meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Ja, det er sant: du lit på Egyptarland, den brotna røyrstaven, som sting hol i handi på kvar som styd seg til honom! Soleis er Farao, egyptarkongen, for alle som lit på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Og svarar de meg: «Me lit på Herren, vår Gud!» var det då ikkje hans offerhaugar og hans altar Hizkia fekk burt, då han baud Juda og Jerusalem: «Framfor dette altaret skal de bøygja kne i Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Gjer då eit veddemål med herren min, assyrarkongen: Eg gjev deg tvo tusund hestar, um du kann skaffa folk til å rida på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Korleis vil du slå attende ein einaste jarl, ein av dei ringaste tenarane åt herren min? Og so lit du på egyptarane, på vognerne og ridarane deira!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Trur de det er Herrens uvitande, når eg kjem hit og øydelegg denne staden? Nei, det var Herren som baud meg: «Drag upp til dette landet og legg det i øyde!»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Eljakim Hilkiason og Sebna og Joah sagde då til Rabsake: «Tala syrisk til tenarane dine! me skynar det nok; tala ikkje jødisk til oss! folket på muren høyrer på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, '«Nei,» svara Rabsake; «det er ikkje til herren din og til deg herren min hev sendt meg å tala desse ordi, men nettupp til dei folki som sit på muren og saman med dykk lyt eta sitt eige skarn og drikka sitt eige vatn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'So steig Rabsake fram og ropa høgmælt desse ordi på jødisk mål: «Høyr det storkongen, assyrarkongen, talar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'So segjer kongen: «Lat ikkje Hizkia narra dykk; han er ikkje i stand til å hjelpa dykk ut or mi hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Lat ikkje Hizkia få dykk til å lita på Herren, med di han segjer: «Herren hjelpar oss for visst; han gjev ikkje denne byen i henderne på assyrarkongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Høyr ikkje på Hizkia! So segjer kongen i Assyria: Gjer fred med meg! gjev dykk yver til meg! So skal de få eta kvar av sitt eige vintre og sitt eige fiketre, og drikka vatn kvar or sin eigen brunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'til dess eg kjem og hentar dykk til eit land som er likt dykkar eige, eit land med korn og druvesaft, eit land med brød og vinhagar, eit land med oljetre og honning. So skal de liva og sleppa døy. Høyr ikkje på Hizkia! Han narrar dykk når han segjer: «Herren bergar oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Tru nokon av folke-gudarne berga sitt land for assyrarkongen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kvar er gudarne i Hamat og Arpad? kvar er gudarne åt Sefarvajim og Hena og Ivva, eller hev dei berga Samaria ut or mi hand?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kven av alle gudarne i alle land hev berga sitt land or mi hand? Skulde då Herren berga Jerusalem ut or mi hand?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Folket tagde, svara honom ikkje eit ord: for so var kongens bod: «Ikkje svara honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Eljakim Hilkiason, drottseten, og Sebna, riksskrivaren, og Joah Asafsson, kanslaren, kom då attende til Hizkia med sundrivne klæde, og melde honom ordi hans Rabsake.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Då kong Hizkia høyrde det, reiv han sund klædi sine, sveipte syrgjebunad kring seg og gjekk inn i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Han sende drottseten Eljakim og riksskrivaren Sebna og dei eldste prestarne syrgjeklædde til profeten Jesaja Amosson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'med dei ordi: «So segjer Hizkia: «Dette er ein dag full av naud og straff og skjemsla; fosteri hev nått fødsli, men det finst ikkje kraft til å føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Kann henda høyrer Herren, din Gud, alt det Rabsake hev sagt, han som er send av assyrarkongen, herren sin, til å svivyrda den livande Gud, so han straffar honom for dei ordi som Herren, din Gud, hev høyrt. Ber då fram ei bøn for den leivning som endå er att!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Då hirdmennerne frå Hizkia kom til Jesaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'sagde Jesaja til deim: «So skal de svara herren dykkar: «So segjer Herren: Ver ikkje rædd for dei ordi du høyrde då trælarne åt assyrarkongen spotta meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Eit hugskot skyt eg i hugen hans; han høyrer ei tiend, og heim att snur han; der let eg honom falla for sverd i sitt land.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Då Rabsake for burt att, fann han assyrarkongen i strid mot Libna; for han hadde høyrt at han hadde fare burt frå Lakis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Då han fekk tiend at ætiopkongen Tirhaka hadde drege ut på herferd mot honom, sende han eit nytt bod til Hizkia med dei ordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '«Seg so med Hizkia, Juda-kongen: «Ikkje lat din Gud, som du lit på, narra deg til å tenkja at ikkje Jerusalem skal falla i henderne på assyrarkongen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Du hev nok høyrt gjete sjølv kor assyrarkongarne hev fare åt mot alle landi; at dei bannstøytte deim. Og so skulde du berga deg undan?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Kunde folke-gudarne berga sine folk, som federne mine øydde ut: Gozan, Haran, Resef eller Edens-folki i Telassar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kvar er Hamat-kongen eller Arpad-kongen eller kongen yver Sefarvajimbyen, yver Hena og Ivva?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Hizkia tok brevet frå sendebodi og las det; og so gjekk han upp i Herrens hus, og Hizkia breidde det ut for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Og Hizkia bad for Herrens åsyn, og sagde: «Herre, du Israels Gud! du som sit yver kerubarne! Einast du er Gud yver alle rike på jordi! du hev gjort himmelen og jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Herre, legg øyra til og lyd! Herre, lat augo upp og sjå! Høyr dei ordi Sanherib sende, og svivyrde den livande Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Herre, det er sant: assyrarkongen hev øydt ut folki og deira land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'kasta gudarne deira på elden; for dei er ikkje gudar, berre manneverk utav stokk og stein; difor kunde dei øydast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Men no må du, Herre, vår Gud, frelsa oss frå hans magt, so alle rike på jordi må røyna: du, Herre, einast er Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Då sende Jesaja Amosson bod til Hizkia med dei ordi: «So segjer Herren, Israels Gud: «Bøni di hev eg høyrt um hjelp mot Sanherib, Assur-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'So lyder Herrens ord, som Herren hev tala imot honom: «Ho vanvyrder deg, ho spottar deg, ungmøyi, Sions dotter, ho rister på hovudet åt deg, Jerusalems dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Kven hev du svivyrdt? kven hev du spotta? Kven hev røysti di ropa imot? Augo lyfte du høgt, mot Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Ved sendebodi hædde du Herren og sagde: Med dei mange vognerne mine for eg upp på dei høgste fjelli, ja, langt burti Libanons utmark, der høgg eg ned hennar høge cedrar og dei hæve cypressarne hennar; eg tek meg fram i dei øvste heimar, inn i den tettaste skogen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'eg borar meg brunnar og vatn drikk eg hjå framande folk; med fotsolen min turkar eg ut alle Egyptarlands elvar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Hev du’kje høyrt at eg hev longe laga det so? Frå ævordsleg tid hev eg fyreåt fastsett dette! Og no let eg det koma i verk! Du fekk magt til å øyda sterke borgar til steinrøysar aude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Folki deira vart veike og valne, skalv og stod til skammar. Det gjekk deim som gras på marki og grøne urter, som vokstrar på taket som moldaks i bryddande åker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Eg veit når du sit, og gjeng ut og gjeng inn, kor du slær deg vill imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Av di du er vill imot meg, og eg høyrer kor kaut du er, eg hektar min krok i nosi di, legg min taum i munnen din, og vikjer deg heim att den vegen du kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Og dette skal du hava til merke: I år skal de eta sjølvsått korn, næste år sjølvrunne, men tridje året skal de så og hausta og planta vinhagar og eta frukti av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Og leivningen som er att av Juda hus, skyt djupare røter nedantil og ovantil ber han si frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'For ein leivning kjem frå Jerusalem, og ein rest frå Sionsfjellet. Herrens brennhug skal gjera dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Difor segjer Herren so um assyrarkongen: Ikkje skal han koma inn i denne byen, og ikkje skal han skjota nokor pil der inn. Ikkje skal han storma fram mot han med skjold, og ikkje byggja skansar upp imot han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Den vegen som han kjem, den skal han heim att fara, i denne byen kjem han ikkje inn, so segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Eg vernar denne by og bergar honom, for mi skuld og for Davids skuld, min tenar.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Det hende seg den natti at Herrens engel gjekk ut og slo hundrad og fem og åtteti tusund i assyrarlægret. Tidleg næste morgon fann dei deim alle ligjande lik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Då tok assyrarkongen Sankerib ut og drog burt og snudde heim att, og heldt seg sidan i Nineve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Ein gong han heldt bøn i huset åt Nisrok, guden sin, hogg Adrammelek og Sareser honom ned med sverd; dei kom seg undan til Araratslandet. Og Asarhaddon, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'I dei dagarne lagdest Hizkia i helsott; då kom profeten Jesaja Amosson til honom og sagde med honom: «So segjer Herren; «Skila for deg! for du skal døy; du vert ikkje god att.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Då snudde han seg mot veggen og bad til Herren:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '«Å Herre, kom i hug kor eg hev ferdast ærleg og heilhjarta for di åsyn og gjort det som godt var i dine augo!» Og Hizkia sette i og storgret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Fyrr Jesaja var nådd ut or den indre byen, kom Herrens ord til honom soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '«Gakk inn att, og seg til Hizkia, fyrsten yver folket mitt: «So segjer Herren, Gud åt David, far din: Eg hev høyrt bøni di, og set tårorne dine. Sjå, eg gjer deg god att; i yvermorgon skal du ganga upp til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Eg aukar alderen din med femtan år. Or handi åt assyrarkongen bergar eg deg og denne byen. Ja, denne byen vernar eg for mi skuld og for David skuld, tenaren min.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Då sagde Jesaja: «Henta ei fikekaka!» Dei so gjorde, og lagde henne på verken. Og han friskna til att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Hizkia sagde til Jesaja: «Kva skal eg hava til merke på at Herren gjer meg god att, so eg i yvermorgon kann ganga upp til Herrens hus?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Jesaja svara: «Dette gjev Herren deg til merke på at Herren held det han lovar: Skal skuggen ganga ti strik fram, eller skal han no ganga ti strik attende?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hizkia svara: «Lett er det for skuggen å tøygja seg ti strik fram; nei, lat skuggen ganga attende ti strik!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Profeten Jesaja ropa til Herren, og han let skuggen på solskiva åt Ahaz ganga attlenges dei ti striki som han nett hadde gjenge fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Kring den tid sende Babel-kongen Berodak Baladan Baladansson brev og gåva til Hizkia; for han hadde spurt at Hizkia hadde vore sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Då Hizkia hadde høyrt på deim, synte han deim heile forrådshuset sitt, sylvet og gullet, og angande kryddor og kosteleg olje, og våpnhuset alt som fanst i skattkammeri hans; det fanst ikkje den ting i hans hus og i heile hans rike som ikkje Hizkia synte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Då kom profeten Jesaja til kong Hizkia og spurde honom: «Kva hev desse mennerne sagt, og kvar helst kom dei frå til deg?» Hizkia svara: «Frå eit land langt burte, frå Babel kom dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, '«Kva hev dei set i huset ditt?» spurde han. «Alt som i huset mitt finst, hev dei set,» svara Hizkia; «det fanst ikkje den ting i skattkammeri mine som eg ikkje synte deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Då sagde Jesaja til Hizkia: «Høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Dagar kjem då alt som finst i huset ditt, det federne dine hev samla alt til i dag, det skal verta ført til Babel; aldri ein grand skal verta att, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Og sume av sønerne dine, ætta frå deg, utstokne frå deg, skal takast, og dei skal verta hirdmenner i slottet åt Babel-kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hizkia svara Jesaja: «Godt er Herrens ord som du hev tala.» Han tenkte: «Berre det vert fred og trygd so lenge eg liver!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Det som elles er å fortelja um Hizkia og alle hans storverk, kor han bygde dammen og vatsleidingi, og førde vatnet til byen, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Hizkia lagde seg til kvile hjå federne sine, og Manasse, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Tolv år gamall var Manasse då han vart konge, fem og femti år rådde han i Jerusalem. Mor hans heitte Hefsiba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Han gjorde det som vondt var i Herrens augo, likt med dei avstyggjelege skikkarne hjå dei folki Herren hadde rudt ut for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Han bygde upp att dei offerhaugarne som Hizkia, far hans, hadde lagt i øyde, og reiste altar for Ba’al og laga Astarte-bilæte, liksom Ahab, Israels-kongen, hadde gjort, og kasta seg ned for og tente heile himmelheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Ja, han bygde altar i Herrens hus, der som Herren hadde sagt: «Til Jerusalem vil eg festa namnet mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'I båe tuni kring Herrens hus bygde han altar for heile himmelheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Han vigde son sin i elden og for med spådom og trolldom, og tinga folk til å mana fram draugar og spåvette. Han gjorde mykje som var vondt i Herrens augo, og harma honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Astarte-bilætet som han hadde laga, sette han i det huset som Herren hadde sagt um til David og Salomo, son hans: «Til dette huset og til Jerusalem, som eg hev valt ut millom alle Israels ætter, vil eg festa namnet mitt i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Eg vil ikkje meir lata Israel flakka heimlaus burt frå landet eg gav federne deira. Berre dei gjer og heldt seg etter alle mine bod og etter heile lovi som Moses, tenaren min, gav deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Men dei lydde ikkje. Manasse forførde deim, so dei stelte seg verre enn dei folki Herren hadde øydt ut for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Då tala Herren ved tenarane sine, profetarne, soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '«Av di Manasse, Juda-kongen, hev drive med desse avstyggjelege skikkarne, verre enn alt det amoritarne gjorde fyre hans tid, og forført med sine steingudar ogso Juda til å synda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'so segjer Herren, Israels Gud: «Sjå, eg sendar ulukka yver Jerusalem og Juda, so det skal ringja for båe øyro på alle som høyrer det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Eg spanar same mælesnori yver Jerusalem som yver Samaria, og nyttar same vegtloddet som yver Ahabs hus. Eg turkar burt Jerusalem, liksom ein turkar av eit fat og so snur det upp ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Eg støyter ifrå meg deim som er att av arvluten min, og gjev deim i fiendevald, so dei vert til ran og til herfang for alle sine fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Og det av di dei hev gjort det som vondt er i mine augo, og jamt harma meg frå den dagen federne deira drog ut or Egyptarland og til den dag i dag.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Manasse let og skuldlaust blod renna, i so stor mengd at Jerusalem vart fyllt av det frå ende til annan, umfram den syndi at han forførde Juda til å gjera det som vondt var i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Det som elles er å fortelja um Manasse, um det han gjorde og um hans synd, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Manasse lagde seg til kvile hjå federne sine, og vart gravlagd i slottshagen, i Uzzas hage. Og Amon, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Tvo og tjuge år gamall var Amon då han vart konge; tvo år rådde han i Jerusalem. Mor hans heitte Mesullemet Harusdotter, frå Jotba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Han gjorde det som vondt var i Herrens augo, liksom Manasse, far hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'han fylgde i alt fotefari til far sin, og tente steingudarne som far hans hadde tent, og bad til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Han vende seg frå Herren, sin fedregud, og gjekk ikkje på Herrens veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Amons hirdmenner samansvor seg og drap kongen i huset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Landsfolket slo i hel deim som hadde samansvore seg saman mot Amon, og tok Josia, son hans, til konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Det som elles er å fortelja um Amon, det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Han vart gravlagd i gravi i Uzzias hage. Josia, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Åtte år gamall var Josia då han vart konge; eitt og tretti år rådde i Jerusalem. Mor hans heitte Jedida Adajadotter, frå Boskat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Han gjorde det som rett for Herren, og fylgde i alt fotefari til David, far sin. Han tok ikkje or leidi, anten til høgre eller vinstre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'I attande styringsåret åt kong Josia sende kongen riksskrivaren Safan, son åt Asalja Mesullamsson, upp til Herrens hus og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '«Gakk upp til øvstepresten Hilkia, og bed honom rekna i hop dei pengarne som er innkomne i Herrens hus, som dørstokkvakti hev samla inn hjå folket;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'og fli deim åt tilsynsmennerne for arbeidarane ved Herrens hus, so dei som arbeider i Herrens hus må få deim til å bøta bresterne i huset:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'timbremennerne, byggsmeistrarne og murarane, til innkjøp av trevyrke og hoggen stein til å setja huset i stand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Dei skal ikkje krevja rekneskap av deim for pengarne dei tek imot; dei skal få gjera det på tru og æra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Då sagde øvstepresten Hilkia til riksskrivaren Safan: «Eg hev funne lovboki i Herrens hus.» Og Hilkia gav boki til Safan, og han las henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'So gjekk Safan, riksskrivaren, til kongen og gav kongen melding og sagde: «Tenarane dine hev tømt ut alle pengarne som fanst i huset, og gjeve demi til tilsynmennerne for arbeidet i Herrens hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Og so fortalde riksskrivaren Safan kongen: «Presten Hilkia gav meg ei bok.» Og Safan las henne upp for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Då kongen fekk høyra ordi i lovboki, reiv han sund klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Og kongen baud presten Hilkia og Ahikam Safansson og Akbor Mikajason og riksskrivaren Safan og kongstenaren Asaja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '«Gakk og spør Herren for meg og folket og heile Juda um det som stend i denne boki som er funni! Stor er Herrens harm, som hev loga upp mot oss, av di federne ikkje hev vore lyduge mot ordi i denne boki og ikkje hev gjort etter alt det som er fyreskrive.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'So gjekk presten Hilkia og Ahikam og Akbor og Safan og Asaja og spurde profetkvinna Hukda, kona åt klædevaktaren Sallum, son åt Tikva Harhasson; ho budde i nybyen i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Ho svara deim: «So segjer Herren, Israels Gud: «Seg med honom som sende dykk til meg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'So segjer Herren: Sjå, eg sender ulukka yver denne staden og yver folket her, alt det som stend i boki som Juda-kongen las,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'til straff for at dei hev vendt seg frå meg og brent røykjelse for andre gudar og harma meg med alle sine verk; harmen min logar mot denne staden og sloknar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Men med Juda-kongen, som sende dykk til å spyrja Herren, skal de segja so: So segjer Herren, Israels Gud, um dei ordi du høyrde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Av di hjarta ditt vart mjukt, og du bøygde deg for Herrens åsyn då du høyrde det eg hev tala mot denne staden og folket her, at dei skal verta til rædsla og forbanning, av di du reiv sund klædi dine og gret for mi åsyn, so hev eg og høyrt, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Difor let eg deg samlast til federne dine og koma i fred i gravi di, og augo dine skal sleppa å sjå all den ulukka eg sender yver denne staden.»» Og dei kom att til kongen med dette svaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Då sende kongen bod og stemnde saman til seg alle dei øvste i Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Og kongen gjekk upp til Herrens hus, og alle Juda-mennerne og alt Jerusalems folk fylgde honom, og prestarne, og profetarne og heile folket, unge og gamle. Han las upp for deim alt det som stod i paktboki som dei hadde funne i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Kongen steig fram på tramen og gjorde den pakti for Herrens åsyn, at dei skulde fylgja Herren og halda hans bod og fyresegner og lover av alt sitt hjarta og all sin hug, og setja i verk dei paktordi som var skrivne i denne boki. Heile folket gjekk med på pakti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Sidan baud kongen øvstepresten Hilkia og dei næst-øvste prestarne og dørstokkvakti å få ut or Herrens tempel alle dei gognerne som var laga åt Ba’al og Astarte og heile himmelheren; og dei vart uppbrende utanfor Jerusalem på Kidrons-vollarne, og oska vart bori til Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Avgudsprestarne som Juda-kongarne hadde sett inn, fekk avskil, dei som hadde brent røykjelse på haugarne i Juda-byarne og ikring Jerusalem, og dei som hadde brent røykjelse for Ba’al, for soli og månen og stjernorne i dyreringen og for heile himmelheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Astarte-bilætet fekk han ut or Herrens hus, til Kidronsdalen utanfor Jerusalem, og brende det der i Kidronsdalen, mol det til dust, og dusti kasta han på den ålmenne gravstaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Han reiv ned utukt-husi i Herrens hus, der som kvende vov tjeld til Astarte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Han flutte alle prestarne inn frå byarne i Juda; og frå Geba til Be’erseba vanhelga han offerhaugarne der prestarne hadde brent røykjelse. Han reiv ned offerhaugarne ved portarne, den som var utanfor porten åt byhovdingen Josva, og den som var på vinstre sida når ein gjekk inn byporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Men hauga-prestarne fekk ikkje stiga upp til Herrens altar i Jerusalem; dei fekk berre vera med når brørne deira åt søtebrød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Han vanhelga Tofet i Hinnomssons-dalen, so ingen skulde vigja son eller dotter i elden, til Molok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Han fekk burt dei hestarne som Juda-kongarne hadde sett upp til æra for soli ved inngangen til Herrens hus, ved kammerset til hirdmannen Netan-Melek i Parvarim; og solvognerne brende han upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Altari på taket ved høgeloftet til Ahaz, dei som Juda-kongarne hadde sett upp, og altari som Manasse hadde bygt upp i båe tuni kring Herrens hus, reiv kongen ned, og han smuldra deim og førde deim burt og kasta dusti i Kidronsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Og kongen vanhelga offerhaugarne aust for Jerusalem på sørsida av Tyningsbjerget, og som Salomo, Israels konge, hadde bygt åt Astarte, styggedomen frå Sidon, og åt Kamos, Moabs styggedom, og åt Milkom, den avstyggjelege guden åt ammonitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Han braut og sund minnesteinarne og hogg ned Astarte-bilæti, og fyllte tufti deira med mannebein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Sameleis altaret i Betel, offerhaugen Jerobeam Nebatsson hadde bygt upp, der som han forførde Israel til å synda - ogso det altaret og den haugen reiv han ned; og han brende upp haugen og mol honom til dust, og han brende upp Astarte-bilætet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Då Josia såg seg um og gådde graverne der på fjellet, sende han folk som tok beini ut or graverne, og brende deim upp på altaret, og vanhelga det soleis, etter Herrens ord, som han gudsmannen hadde ropa ut, som ropa at dette skulde henda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, '«Kva er det for ein gravstein eg ser her?» spurde han. Bymennene svara honom: «Det er gravi åt den gudsmannen som kom frå Juda og ropa ut yver altaret i Betel at det skulde henda som du no hev sett i verk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Då sagde han: «Lat honom kvila i fred! Ingen skal røra beini hans.» Soleis berga dei hans bein, og sameleis beini til profeten som kom frå Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Dessutan rudde Josia burt alle hauga-husi i Samaria-byarne, som Israels-kongarne hadde bygt til harm for Herren; og han for med deim i alle måtar sameleis som i Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Og han drap ned alle hauga-prestarne der ved altari, og brende mannebein på deim. So snudde han heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Kongen gav heile folket det bodet: «Haldt påske for Herren, dykkar Gud, etter fyreskrifterne i denne paktboki!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Sovori påskehelg hadde dei ikkje halde frå den tid då domarane styrde Israel, og ut gjenom heile kongetidi i Israel og Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Fyrst i attande styringsåret åt kong Josia heldt dei sovori påskehelg for Herren i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Josia øydde og ut alle som mana draugar og spåvette, og husgudarne og steingudarne og all styggedomen som hadde synt seg i Judalandet og i Jerusalem. Soleis sette han i verk lov-ordi som var skrivne i den boki presten Hilkia fann i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Maken til konge hadde ikkje vore fyre honom; det var ingen som soleis hadde vendt seg til Herren av alt sitt hjarta og all sin hug og all sin styrke etter heile Moselovi; og maken hans kom aldri meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Like vel gav ikkje Herren upp den store brennande harmen som hadde loga upp mot Juda for alle dei harmelege synder Manasse hadde harma honom med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Herren sagde: «Ogso Juda støyter eg burt frå meg, liksom eg støyte Israel burt. Ja, eg vandar denne byen som eg valde ut, Jerusalem og huset som eg sagde um: «Mitt namn skal vera der.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Det som elles er å fortelja um Josia og alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'I hans tid drog egyptarkongen Farao Neko upp til elvi Frat mot assyrarkongen. Kong Josia drog imot honom, men han drap honom ved Megiddo, so snart han fekk sjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Folket hans køyrde liket frå Megiddo til Jerusalem og gravlagde honom i hans eigi grav. Og folket i landet tok Joahaz Josiason og salva honom til konge i staden for faren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Tri og tjuge år gamall var Joahaz då han vart konge, og tri månader rådde han i Jerusalem. Mor hans heitte Hamutal Jeremiadotter, frå Libna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Han gjorde det som vondt var i Herrens augo, plent som federne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Farao Neko fengsla honom i Ribla i Hamatlandet, og gjorde soleis ende på styringi hans i Jerusalem. Han lagde skatt på landet: tvo hundrad og femti våger sylv og tvo og ein halv våg gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Farao Neko gjorde Eljakim Josiason til konge i staden for Josia, far hans, og brigda namnet hans til Jojakim. Men Joahaz tok han med seg til Egyptarland, og der døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Jojakim reidde ut sylvet og gullet til Farao. Men han laut leggja skatt på landet for å reida ut dei pengarne Farao kravde. Etter so som kvar var likna, dreiv han inn sylvet og gullet av landsfolket og reidde det ut til Farao Neko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Fem og tjuge år gamall var Jojakim då han vart konge, og han elleve år rådde han i Jerusalem. Mor hans heitte Zebida Pedajadotter, frå Ruma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Han gjorde det som vondt var i Herrens augo, plent som federne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'I hans tid drog Babel-kongen Nebukadnessar upp, og Jojakim vart lydkongen hans. Men tri år etter fall han ifrå honom att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Herren sende då imot honom kaldæiske, syriske, moabitiske og ammonitiske røvarflokkar. Han sende deim mot Juda til å øyda landet, etter Herrens ord, som han hadde tala ved tenarane sine, profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Ja, på Herrens bod gjekk det so med Juda at dei vart burtstøytte frå hans åsyn, for Manasses synder skuld, for alt det han hadde gjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'soleis og for det skuldlause blodet han let renna, då han fyllte Jerusalem med skuldlaust blod; det vilde Herren ikkje tilgjeva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Det som elles er å fortelja um Jojakim og alt det han gjorde, det er uppskrive i krønikeboki åt Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Jojakim lagde seg til kvile hjå federne sine, og Jojakin, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'No for ikkje egyptarkongen ut frå landet sitt meir; for Babel-kongen hadde teke alt det landet egyptarkongen åtte frå Egyptarlands-bekken til elvi Frat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Attan år gamall var Jojakin då han vart konge, tri månader rådde han i Jerusalem. Mor hans heitte Nehusta Elnatansdotter, frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Han gjorde det som vondt var i Herrens augo, plent som far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'På den tid drog Babel-kongen Nebukadnessars folk upp mot Jerusalem, og byen vart kringsett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Kong Nebukadnessar kom sjølv til byen, medan herfolket hans kringsette honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Juda-kongen Jojakin gav seg då yver til Babel-kongen med mor si og tenarane og hovdingarne og hirdmennerne sine; og Babel-kongen tok honom til fange i åttande styringsår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Han førde burt derifrå alle skattar i Herrens hus og i kongsgarden. Han braut laust gullet av alle gognerne som Salomo, Israels konge, hadde laga åt Herrens tempel, soleis som Herren hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Han førde burt heile Jerusalem, alle hovdingarne og godseigarne, ti tusund fangar, og alle grovsmedar og låssmedar. Det vart ikkje att anna enn fatigfolk i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Han førde Jojakin burt til Babel; og kongsmori og kongskonorne og hirdmennerne hans og storfolket i landet førde han fangar frå Jerusalem til Babel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'og alle godseigarane: sju tusund, grovsmedar og låssmedar: eit tusund, alle i hop djerve hermenner, deim førde Babel-kongen burt til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Og Babel-kongen sette Mattanja, farbror hans, til konge i staden hans, og brigda namnet hans til Sidkia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Eitt og tjuge år gamall var Sidkia då han vart konge; elleve år rådde han i Jerusalem. Mor hans heitte Hamital Jirmejadotter, frå Libna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Han gjorde det som vondt var i Herrens augo, plent som Jojakim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Det var for Herrens harm skuld det gjekk so med Jerusalem og Juda, til dess han støytte deim burt frå si åsyn. Sidkia fall ifrå Babel-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'I det niande styringsåret hans, tiande dagen i tiande månaden, kom Nebukadnessar, Babel-kongen, med heile heren sin til Jerusalem, lægra seg utanfor byen og bygde skansar rundt ikring honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Byen vart kringsett til Sidkias ellevte styringsår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Den niande dagen i månaden røynde svolten hardt på i byen, og landsfolket hadde inkje mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Då vart byen teken. Og alt stridsfolket rømde um natti gjenom porten i dubbelmuren ved kongshagen, medan kaldæarane låg rundt ikring byen. Dei tok leidi til Moarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Men kaldæarheren forfylgde kongen og nådde honom att på Moarne ved Jeriko. Alt herfolket sprang frå honom og spreiddest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Dei fanga då kongen og førde honom upp til Ribla til Babel-kongen. Der fekk han sin dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Sønerne åt Sidkia drap dei medan han såg på det; so stakk han ut augo på Sidkia, batt honom med koparlekkjor og førde honom til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Sjuande dagen i den femte månaden i det nittande styringsåret åt Nebukadnessar, Babel-kongen, kom ein av tenarane åt Babel-kongen, livvakthovdingen Nebuzaradan, til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Han brende upp Herrens hus og kongsgarden. Ja, alle husi i Jerusalem, serleg alle storfolk-hus, sette han eld på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Og murarne ikring Jerusalem vart nedrivne av heile den kaldæarheren som livvakthovdingen hadde med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Resten av folket som var att i byen, og svikararne som hadde gjenge yver til Babel-kongen, og resten av ålmugen, vart burtførd av Nebuzaradan, livvakthovdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Nokre av fatigfolket i landet let han vera att til å arbeida i vinhagarne og på åkrarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Koparsulorne i Herrens hus, fotstykki og koparhavet i Herrens hus, braut kaldæarane sund, og tok koparen med seg til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Og dei tok oskefati og eldskuflerne og ljossakserne og skålerne og alle kopargogner som dei hadde til gudstenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Livvakthovdingen tok og glodpannorne og blodbollarne, og alt som var av skirt gull og av skirt sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Tvo sulor og eit hav og fotstykki som Salomo hadde laga åt Herrens hus - koparen i alle desse gognerne var ikkje vegande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Den eine sula var attan alner høg, og ovanpå den var det eit koparhovud, og hovudet var tri alner høgt; rundt ikring hovudet var det eit net og granateple, alt av kopar; og sameleis var det med netet på den andre sula.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Livvakthovdingen tok øvstepresten Seraja og næst-øvste presten Sefanja og dei tri dørstokkvaktarane,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'og frå byen tok han ein hirdmann som uppsynsmann yver herfolket, og fem som han råka på i byen av næmaste lagsfolket hjå kongen, dessutan skrivaren åt herhovdingen, han som skreiv ut landsfolket til hertenesta, og seksti andre landsfolk han råka på i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Alle desse tok livvakthovdingen Nebuzaradan med seg til Ribla til Babel-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Og Babel-kongen slo deim i hel der i Ribla i Hamatlandet. Soleis vart Juda burtført frå landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Babel-kongen Nebukadnessar sette Gedalja, son åt Ahikam Safansson, til jarl yver det folket som var att i Judalandet, dei som han let vera att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Då alle herhovdingarne og hermennerne deira fekk greida på at Babel-kongen hadde sett inn Gedalja, kom dei til Gedalja i Mispa: Ismael Netanjason, og Johanan Kareahsson og Seraja Tanhumetson frå Netofa og Ja’asanja, son åt ein mann frå Ma’aka, dei og mennerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Gedalja gjorde eid til deim og hermennerne deira, og sagde med deim: «Ver ikkje rædde for kaldæartenarane! Set bu i landet, og gjev dykk under Babel-kongen, so vil det ganga dykk vel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Men i den sjuande månaden kom Ismael, son åt Netanja Elisamason, ein mann av kongsætti, med ti mann og slo i hel Gedalja og dei jødar og kaldæarar som var hjå honom i Mispa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'So tok herhovdingarne og heile folket, unge og gamle, og gav seg på veg ut til Egyptarland; dei var rædde for kaldæarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'I det sju og trettiande året etter Juda-kongen Jojakin var burtførd, sju og tjugande dagen i tolvte månaden, gav Evil-Merodak, Babel-kongen - same året som han vart konge - Jojakin, Juda-kongen, uppreisnad og fria honom or fangehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Han helsa honom venleg med han og gav honom fremste sessen millom dei kongarne som var hjå honom i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Han fekk leggja av seg fangebunaden, og gjekk kvar dag til kongens bord, so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Kost og tæring naut han dagvisst på kongens kostnad, til kvar dag det han trong for dagen, heile si livetid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enos,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jared,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enok, Metusalah, Lamek,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noah, Sem, Kham og Jafet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Sønerne hans Jafet var Gomer og Magog og Madai og Javan og Tubal og Mesek og Tiras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Og sønerne hans Gomer var Askenaz og Difat og Togarma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Og sønerne hans Javan var Elisa og Tarsisa, Kittim og Rodanim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Sønerne hans Kham var Kusj og Misrajim, Put og Kana’an.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Sønerne hans Kusj var Seba og Havila og Sabta og Raema og Sabteka; og sønerne hans Raema var Sjeba og Dedan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Og Kusj fekk ein son som heitte Nimrod. Han var den fyrste som fekk stort velde på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Misrajim vart far til ludarane og anamarane og lehabarane og naftuharane');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'og patrusarane og kastuharane, dei som filistarane hev kome frå, og kaftorarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Og Kana’an vart far til Sidon - det var fyrste sonen hans - og til Het');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'og jebusitarne og amoritarne og girgasitarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'og hevitarne og arkitarne og sinitarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'og arvaditarne og semaritarne og hamatitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Sønerne hans Sem var Elam og Assur og Arpaksad og Lud og Aram og Us og Hul og Geter og Mesek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Og Arpaksad fekk sonen Salah, og Salah fekk sonen Eber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Og Eber fekk tvo søner. Den eine heitte Peleg; for i hans dagar vart jordi utbytt millom folki. Og bror hans heitte Joktan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Og Joktan vart far til Almodad og Salef og Hasarmavet og Jarah');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'og Hadoram og Uzal og Dikla');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'og Ebal og Abimael og Sjeba');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'og Ofir og Havila og Jobab; alle desse var sønerne hans Joktan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpaksad, Salah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Re’u,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nakor, Tarah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, det er Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Sønerne hans Abraham var Isak og Ismael.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Dette er ættetavla deira: Den eldste son hans Ismael var Nebajot, deretter Kedar og Adbe’el og Mibsam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma og Duma, Massa, Hadad og Tema,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafis og Kedma; dette var sønerne hans Ismael.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Og dei sønerne som Ketura, fylgjekona hans Abraham, åtte, var Zimran og Joksan og Medan og Midjan og Jisbak og Suah. Sønerne hans Joksan var Sjeba og Dedan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Og sønerne hans Midjan var Efa og Efer og Hanok og Abida og Elda’a. Alle desse var sønerne hennar Ketura.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Og Abraham var far til Isak. Sønerne hans Isak var Esau og Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Sønerne hans Esau var Elifaz, Re’uel og Je’us og Jaelam og Korah.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Sønerne hans Elifaz var Teman og Omar, Sefi og Gatam, Kenaz og Timna og Amalek.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Sønerne hans Re’uel var Nahat og Serah, Samma og Mizza.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Men sønerne hans Se’ir var Lotan og Sobal og Sibeon og Ana og Dison og Eser og Disan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Og sønerne hans Lotan var Hori og Homam, og syster hans Lotan var Timna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sønerne hans Sobal var Aljan og Manahat og Ebal og Sefi og Onam; og sønerne hans Sibeon var Aja og Ana.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Son hans Ana var Dison, og sønerne hans Dison var Hamran og Esban og Jitran og Keran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Sønerne hans Eser var Bilhan og Za’avan og Ja’akan; og sønerne hans Disan var Us og Aran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Og dette er dei kongarne som rådde yver Edomlandet fyrr det rådde nokon konge yver Israels-folket: Bela, son åt Beor, og byen han sat i, heitte Dinhaba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Og Bela døydde, og Jobab, son åt Zerah frå Bosra, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Og Jobab døydde, og Husam frå Temanitarlandet vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Og Husam døydde, og Hadad, son åt Bedad, vart konge i staden hans; det var han som vann yver midjanitarne på Moabmoen. Og byen hans heitte Avit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Og Hadad døydde, og Samla frå Masreka vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Og Samla døydde, og Saul frå Rehobot uppmed åi vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Og Saul døydde, og Ba’al-Hanan, son åt Akbor, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Og Ba’al-Hanan døydde, og Hadad vart konge i staden hans, og hans by heitte Pa’i; og kona hans heitte Mehetabel, dotter åt Matred, som var dotter åt Mezahab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Og då Hadad var dåen, var desse jarlarne i Edom: Timna-jarlen, Alja-jarlen, Jetet-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Åhålibama-jarlen, Ela-jarlen, Pinon-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Kenaz-jarlen, Teman-jarlen, Mibsar-jarlen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Magdiel-jarlen, Iram-jarlen. Det var jarlarne i Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Dette var sønerne åt Israel: Ruben, Simeon, Levi og Juda, Issakar og Sebulon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Josef og Benjamin, Naftali, Gad og Asser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Sønerne åt Juda var Er og Onan og Sela; desse tri fekk han med dotter åt Sua, kananitarkvinna; men Herren tykte ille um Er, eldste son åt Juda, og han laga det so at han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Med Tamar, sonekona si, fekk Juda sønerne Peres og Zerah, so sønerne åt Juda var fem i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Sønerne åt Peres var Hesron og Hamul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Og sønerne åt Zerah var Zimri og Etan og Heman og Kalkol og Dara; fem i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Og son åt Karmi var Akar, som førde Israel i ulukka, med di han ikkje for ærleg åt med det som var vigt til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Og son hans Etan var Azarja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Og sønerne som Hesron fekk, var Jerahme’el, Ram og Kelubai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Og Ram fekk sonen Amminadab, og Amminadab fekk sonen Nahson, hovdingen for Juda-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Og Nahson fekk sonen Salma, og Salma fekk sonen Boaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Og Boaz fekk sonen Obed, og Obed fekk sonen Isai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai fekk sonen Eliab, det var fyrste sonen hans, og Abinadab var den andre, og Simea den tridje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Netanel den fjorde, Raddai den femte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Osem den sette, David den sjuande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Og systerne deira var Seruja og Abiga’il. Og sønerne åt Seruja var Absai og Joab og Asael, tri i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Og Abiga’il åtte Amasa, og far åt Amasa var Jeter, ismaeliten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Og Kaleb, son åt Hesron, fekk born med Azuba, kona si, og med Jeriot; sønerne hennar var Jeser og Sobab og Ardon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Då Asuba døydde, tok Kaleb seg Efrat til kona, og med henne fekk han sonen Hur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Og Hur fekk sonen Uri, og Uri fekk sonen Besalel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Sidan gjekk Hesron inn til dotter åt Makir, som var far åt Gilead; henne tok han til kona då han var seksti år gamall, og han fekk sonen Segub med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Og Segub fekk sonen Ja’ir; han åtte tri og tjuge byar i Gileadlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Men gerusitarne og aramæarane tok frå deim byarne hans Ja’ir, og dessutan Kenat med seksti byar som låg ikring. Alle desse var søner åt Makir, far åt Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Og Hesron fekk sonen Ashur, far åt Tekoa, med Abia, kona si; ho åtte honom etter Hesron var dåen i Kaleb-Efrata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Og sønerne åt Jerahme’el, eldste son hans Hesron, det var Ram, den eldste, og Buna og Oren og Osem med Ahia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Men Jerahme’el hadde ei onnor kona og, som heitte Atara; ho var mor åt Onam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Sønerne åt Ram, fyrste sonen hans Jerahme’el, det var Ma’as og Jamin og Eker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Og sønerne åt Onam var Sammai og Jada. Og sønerne åt Sammai var Nadab og Abisur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Og kona hans Abisur heitte Abiha’il; med henne fekk han sønerne Ahban og Molid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Sønerne åt Nadab var Seled og Appajim. Seled døydde barnlaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Men sønerne åt Appajim var Jisi; sønerne åt Jisi var Sesan, og sønerne åt Sesan var Ahlai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Og sønerne åt Jadas, bror hans Sammai, var Jeter og Jonatan. Jeter døydde barnlaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Men sønerne hans Jonatan var Pelet og ZaZa. Dette var sønerne åt Jerahme’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Men Sesan hadde ingi søner, anna berre døtter. No hadde Sesan ein egyptisk dreng, som heitte Jarha.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Og Sesan gav Jarha, drengen sin, dotter si til kona, og med henne fekk han sonen Attai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attai fekk sonen Natan, og Natan fekk sonen Zabad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'og Zabad fekk sonen Eflal, og Eflal fekk sonen Obed,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'og Obed fekk sonen Jehu, og Jehu fekk sonen Azarja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'og Azarja fekk sonen Hales, og Hales fekk sonen Elasa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'og Elasa fekk sonen Sismai, og Sismai fekk sonen Sallum,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'og Sallum fekk sonen Jekamja, og Jekamja fekk sonen Elisama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Og sønerne åt Kaleb, bror hans Jerahme’el, var Mesa, som var eldst - han var far åt Zif - og sønerne åt Maresa, far hans Hebron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Og sønerne åt Hebron var Korah og Tappuah og Rekem og Sema.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Sema fekk sonen Raham, far åt Jorkeam, og Rekem fekk sonen Sammai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Son hans Sammai var Maon, og Maon var far åt Betsur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Og Efa, fylgjekona hans Kaleb, åtte sønerne Haran og Mosa og Gazez, og Haran fekk sonen Gazez.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Og sønerne åt Jehdai var Regem og Jotam og Gesan og Pelet og Efa og Sa’af.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Ma’aka, fylgjekona hans Kaleb, åtte sønerne Seber og Tirhana.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Ho åtte og Sa’af, far åt Madmanna, og Seva, far åt Makbena og Gibea. Og dotter hans Kaleb var Aksa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Dette var sønerne hans Kaleb: son åt Hur, som var eldste son åt Efrata, det var Sobal, far åt Kirjat-Jearim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, far åt Betlehem, og Haref, far åt Bet-Gader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Sønerne hans Sobal, far åt Kirjat-Jearim, var Haroe og helvti av Hammenuhot-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Men ættgreinerne frå Kirjat-Jearim var jitritarne, putitarne, sumatitarne og misra’itarne; frå deim hev soratitarne og estaolitarne kome.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Sønerne åt Salma var Betlehem og netofatitarne, Atrot-Bet-Joab og helvti av manahtitarne, soritarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Og ætterne av dei skriftlærde som budde i Jabes, var tiratitar, simatitar og sukatitar. Dette var dei kinitarne som var ætta frå Hammat, far for åt Rekab-huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Dette var sønerne som David fekk då han var i Hebron: Amnon, den fyrste sonen hans, med Ahinoam frå Jizre’el; Daniel, den andre, med Abiga’il frå Karmel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Absalom, den tridje, son åt Ma’aka, som var dotter åt Talmai, konge i Gesur; Adonia, den fjorde, son åt Haggit;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Safatja, den femte, med Abital; Jitream, den sette, med Egla, kona hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Desse seks fekk han i Hebron; der rådde han i sju år og seks månader, og i tri og tretti år rådde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Og desse sønerne han fekk i Jerusalem: Simea og Sobab og Natan og Salomo, i alt fire, med Batsua Ammielsdotter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'og Jibhar og Elisama og Elifelet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'og Nogah og Nefeg og Jafia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama og Eljada og Elifelet, ni i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Dette var alle sønerne hans David umfram sønerne han fekk med fylgjekonorne, og Tamar var syster deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Son åt Salomo var Rehabeam; hans son var Abia; hans son var Asa; hans son var Josafat;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'hans son var Joram; hans son var Ahazja; hans son var Joas;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'hans son var Amasja; hans son var Azarja; hans son var Jotam;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'hans son var Ahaz; hans son var Hizkia; hans son var Manasse;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'hans son var Amon; hans son var Josia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Sønerne åt Josia var Johanan, den fyrste, Jojakim, den andre, Sidkia, den tridje, Sallum, den fjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Sønerne åt Jojakim var: Hans son Jekonja; hans son Sidkia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Sønerne åt den fengsla Jekonja var: Sealtiel, son hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'og Malkiram og Pedaja og Senassar, Jekamja, Hosama og Nedabja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Sønerne åt Pedaja var Zerubbabel og Sime’i; og sønerne hans Zerubbabel var Mesullam og Hananja - og Selomit var syster deira -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'og dertil Hasuba, Ohel og Berekja, Hasadja og Jusab-Hesed, fem i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Sønerne åt Hananja var Pelatja og Jesaja, og dertil sønerne åt Refaja, Arnan, Obadja og Sekanja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Son åt Sekanja var Semaja; og sønerne hans Semaja var Hattus og Jigal og Bariah og Nearja og Safat, seks i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Sønerne hans Nearja var Eljoenai og Hizkia og Azrikam, tri i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Sønerne åt Eljoenai var Hodavja, Eljasib og Pelaja, og Akkub og Johanan og Delaja og Anani, sju i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Sønerne åt Juda var Peres, Hesron og Karmi og Hur og Sobal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Og Reaja, son åt Sobal, vart far til Jahat, og Jahat vart far til Ahumai og Lahad; dette var soratit-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Og dette var sønerne åt Abi-Etam: Jizre’el og Jisma og Jidbas - og syster deira heitte Haslelponi -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'og dessutan Penuel, far åt Gedor, og Ezer, far åt Husa. Desse var søner åt Hur, eldste son hans Efrata, far åt Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Og Ashur, far åt Tekoa, hadde tvo konor, Hela og Na’ara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Med Na’ara fekk han Ahuzzam og Hefer, og Temeni og ahastaritarne; dette var sønerne hennar Na’ara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Og sønerne hennar Hela var Seret og Jishar og Etnan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Og Kos vart far til Anub og Hassobeba, og ætterne hans Aharhel, son åt Harum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Men Jabes var den gjævaste av brørne; mor hans hadde gjeve honom namnet Jabes, med di ho sagde: «Med verk og vande hev eg ått honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Og Jabes kalla på Israels Gud og sagde: «Um du vilde velsigna meg og auka landviddi mi og lata di hand vera med meg, og um du vilde bægja for det som vondt er, so eg slepp å kjenna nokon verk!» Og Gud let det verta soleis som han bad um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Og Kelub, bror hans Suha, fekk sonen Mehir; han var far åt Eston.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Og Eston var far til Bet-Rafa, Paseah og Tehinna, far åt Ir-Nahas. Dette var mennerne frå Reka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Og sønerne hans Kenaz var Otniel og Seraja; og son åt Otniel var Hatat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Og Meonotai fekk sonen Ofra, og Seraja fekk sonen Joab, far til ætti i Timbremannsdalen; for dei var timbremenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Og sønerne hans Kaleb Jefunneson var Iru, Ela og Na’am, og son åt Ela var Kenaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Og sønerne hans Jehallelel var Zif og Zifa, Tirja og Asarel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Og sønerne hans Ezra var Jeter og Mered og Efer og Jalon. Og kvinna vart med barn og åtte Mirjam, Sammai og Jisbah, far åt Estemoa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Og jøde-kona hans åtte Jered, far hans Gedor, og Heber, far åt Soko, og Jekutiel, far åt Zanoah; men dei hine var søner åt Bitja, dotter åt Farao, som Mered hadde teke til kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Og sønerne åt kona hans Hodia, syster hans Naham, var far åt Ke’ila, garmiten, og ma’akatiten Estemoa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Og sønerne hans Simon var Amnon og Rinna, Ben-Hanan og Tulon. Og sønerne hans Jisi var Zohet og son åt Zohet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Og sønerne hans Sela Judason var Er, far åt Leka, og Lada, far åt Maresa, og linarbeidar-ætterne av Asbea-huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'dessutan Jokim og mennerne i Kozeba og Joas og Saraf, som vart herre yver Moab, og dertil Jasubi-Lehem. Men dette høyrer til gamall tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Dette var pottemakarane og folket Netajim og Gedera; dei budde der hjå kongen og var i hans arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Sønerne hans Simeon var Nemuel og Jamin, Jarib, Zerah, Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Son hans var Sallum; hans son var Mibsam; hans son var Misma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Sønerne åt Misma var Hammuel, son hans, Zakkur, hans son, og Sime’i, hans son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Og Sime’i hadde sekstan søner og seks døtter; men brørne hans hadde ikkje mange born. Og heile ætti deira aukast ikkje so mykje som Juda-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Og dei budde i Be’erseba og Molada og Hasar-Sual,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'i Bilha, Esem og i Tolad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'i Betuel, i Horma og Siklag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'i Bet-Markabot, i Hasar-Susim, i Bet-Biri og i Sa’arajim. Dette var byarne deira alt til David vart konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Og i landsbyarne deira var Etam og Ajin, Rimmon, Token og Asan, fem byar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'og dertil alle bygderne deira som låg ikring desse byarne, alt til Ba’al; dette var bustaderne deira, og dei hadde ei ættarlista for seg sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Og Mesobab, Jamlek og Josa, son åt Amasja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'og Joel og Jehu, son åt Josibja, son åt Seraja, son åt Asiel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'og Eljoenai, Ja’akoba, Jesohaja, Asaja, Adiel, Jesimiel og Benaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'og Ziza, son åt Sifi, son åt Allon, son åt Jedaja, son åt Simri, son åt Semaja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Desse som no er nemnde, var hovdingar i ætterne sine, og ættgreinerne deira breidde seg ut og vart mangmente.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Og dei drog fram mot Gedor alt til austsida av dalen og skulde finna beite åt buskapen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Og dei fann feitt og godt beite, og landet var vidt og romt, og det var stilt og fredsamt; for dei som budde der fyreåt, var ætta frå Kham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Men desse som her er uppskrivne med namn, kom då Hizkia var konge i Juda, og øydelagde tjeldbuderne deira og hogg ned dei me’unitarne som der var, og bannstøytte deim, so dei no ikkje meir er til, og dei slo seg ned der i staden deira; for der var det beite for buskapen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Og det var fem hundrad mann av deim, av Simeons-sønerne, som for til Se’irfjelli, og Pelatja og Nearja og Refaja og Uzziel, sønerne hans Jisi, var fyregangsmennerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Og dei drap den siste leivningen amalekitarne; so slo dei seg ned der, og bur der den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Og sønerne hans Ruben, eldste son åt Israel - for han var den eldste; men med di han vanhelga lega åt far sin, vart odelsretten hans gjeven til sønerne hans Josef, son åt Israel, men då ikkje soleis at han skulde skrivast upp i ættelista som den eldste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'For Juda var nok den megtigaste millom brørne sine, og ein av etterkomarane hans vart fyrste; men odelsretten høyrde Josef til -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'sønerne hans Ruben, eldste son åt Israel, var Hanok og Pallu, Hesron og Karmi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Sønerne åt Joel var Semaja, son hans; hans son var Gog; hans son var Sime’i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'hans son var Mika, hans son Reaja, hans son Ba’al,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'hans son Be’era, som Tilgat-Pilneser, kongen i Assyria, førde burt til fange; han var hovding for rubenitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Og då brørne hans med sine ætter vart uppskrivne i ættarlista etter sine ættgreiner, var det desse: Je’iel, hovdingen, og Zakarja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'og Bela, son åt Azaz, son åt Sema, son åt Jo’el; han budde i Aroer, og bustaderne hans nådde radt til Nebo og Ba’al-Meon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Og austetter nådde bustaderne hans alt fram åt øydemarki som rekk frå Eufratelvi; for dei hadde store flokkar med fe i Gileadlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Men i Sauls dagar låg dei i strid med hagarenarne, som då fall for handi deira; so sette dei seg til i tjeldbuderne deira etter heile austsida åt Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Og Gads-sønerne budde midt imot deim i Basanlandet alt til Salka:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel, hovdingen, og di næst Safan, og so Janai og Safat i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Og brørne deira, etter sine ættgreiner, var Mikael og Mesullam og Seba og Jorai, Jakan, Zia og Eber, sju i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Desse var søner åt Abiha’il, son åt Huri, son åt Jaroah, son åt Gilead, son åt Mikael, son åt Jesisai, son åt Jahdo, son åt Buz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, son åt Abdiel, son åt Guni, var ættarhovdingen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Og dei budde i Gilead i Basan og i dei bygderne som låg ikring, og på alle utmarkerne i Saron, so langt som dei rakk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Alle desse vart uppskrivne i ættarlista i den tidi då Jotam var konge i Juda, og då Jeroboam var konge i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Rubens-sønerne og gaditarne og helvti av Manasse-ætti, dei som var stridsføre og bar skjold og sverd og spente boge og var stridskunnige, var fire og fyrti tusund sju hundrad og seksti våpnføre menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Og dei hadde ufred med hagarenarne og Jetur og Nafis og Nodab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Og dei fekk siger i striden, so hagarenarne og alle som var med deim, kom i deira hender; for dei ropa til Gud i striden, og han høyrde bøni deira, av di dei leit på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Og dei førde burt til herfang feet deira, femti tusund kamelar og tvo hundrad og femti tusund sauer og tvo tusund asen, og hundrad tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'For det hadde vore eit stort mannefall, etter di striden var ifrå Gud. Og dei budde i landet deira alt til burtføringi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Sønerne åt helvti av Manasse-ætti budde og der i landet frå Basan alt til Ba’al-Hermon og Senir og Hermonfjellet, og dei var mangmente.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Og desse var ættarhovdingarne deira: Efer og Jisi, Eliel og Azriel, Jirmeja og Hodavja og Jahdiel, stridsføre hermenner, namngjetne menner, hovdingar for ættgreinene sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Men dei var utrue mot fedreguden og heldt seg med gudarne åt det folket der i landet som Gud hadde tynt for augo deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Då øste Israels Gud upp hugen hjå assyrarkongen Pul og assyrarkongen Tilgat-Pilneser, og han førde deim burt, rubenitarne og gaditarne og eine helvti av Manasse-ætti, og flutte deim til Halah og Habor og Hara og Gozanelvi, og der dei er den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Sønerne hans Levi var Gerson, Kehat og Merari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Sønerne hans Kahat var Amram og Jishar og Hebron og Uzziel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Og borni hans Amram var Aron og Moses og Mirjam. Og sønerne åt Aron var Nadab og Abihu, Eleazar og Itamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar fekk sonen Pinehas; Pinehas fekk sonen Abisua,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'og Abisua fekk sonen Bukki, og Bukki fekk sonen Uzzi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'og Uzzi fekk sonen Zerahja, og Zerahja fekk sonen Merajot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajot fekk sonen Amarja, og Amarja fekk sonen Ahitub,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'og Ahitub fekk sonen Sadok, og Sadok fekk sonen Ahima’as,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'og Ahima’as fekk sonen Azarja, og Azarja fekk sonen Johanan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Johanan fekk sonen Azarja; det var han som var prest i det huset Salomo bygde i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Og Azarja fekk sonen Amarja, og Amarja fekk sonen Ahitub,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'og Ahitub fekk sonen Sadok, og Sadok fekk sonen Sallum,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'og Sallum fekk sonen Hilkia, og Hilkia fekk sonen Azarja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'og Azarja fekk sonen Seraja, og Seraja fekk sonen Josadak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Men Josadak laut ganga med då Herren let Nebukadnessar føra Juda og Jerusalem i utlægd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Sønerne åt Levi var Gerson, Kahat og Merari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Og dette var namni på sønerne hans Gersom: Libni og Sime’i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Og sønerne hans Kahat var Amram og Jishar og Hebron og Uzziel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Sønerne hans Merari var Mahli og Musi. Dette var levitætterne etter federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Frå Gersom var Libni, son hans, ætta; hans son var Jahat, hans son Zimma,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'hans son Joah, hans son Iddo, hans son Zerah, hans son Jeatrai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Sønerne åt Kahat var: Amminadab, son hans; hans son var Korah; hans son Assir;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'hans son Elkana, hans son Ebjasaf, hans son Assir;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'hans son Tahat, hans son Uriel, hans son Uzzia, og hans son Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Sønerne hans Elkana var Amasai og Ahimot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkana - hans son var Elkana; hans son var Elkana-Sofai; hans son Nahat;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'hans son Eliab; hans son Jeroham; hans son var Elkana.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Sønerne hans Samuel var Vasni, som var eldst, og Abia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Son hans Merari var Mahli; hans son var Libni; hans son Sime’i; hans son Uzza;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'hans son Simea; hans son Haggia; hans son Asaja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'So var det dei som David sette til å greida med songen i Herrens hus, etter at kista hadde fenge ein kvilestad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Dei gjorde tenesta med song framfor møtetjeldhuset, alt til Salomo bygde Herrens hus i Jerusalem; dei stod der og gjorde sitt arbeid etter dei fyresegner dei hadde fenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Dei som gjorde denne tenesta, og sønerne deira, var desse: Av kahatitsønerne: Heman, songaren, son åt Joel, son åt Samuel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'son åt Elkana, son åt Jeroham, son åt Eliel, son åt Toah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'son åt Sif, son åt Elkana, son åt Mahat, son åt Amasai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'son åt Elkana, son åt Joel, son åt Azarja, son åt Sefanja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'son åt Tahat, son åt Assir, son åt Ebjasaf, son åt Korah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'son åt Jishar, son åt Kahat, son åt Levi, son åt Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Dinæst Asaf, bror hans, som stod på høgre sida hans, Asaf, son åt Berekja, son åt Simea,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'son åt Mikael, son åt Ba’aseja, son åt Malkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'son åt Etni, son åt Zerah, son åt Adaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'son åt Etan, son åt Zimma, son åt Sime’i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'son åt Jahat, son åt Gersom, son åt Levi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Og brørne deira, Merari-sønerne, stod på den vinstre sida: Etan, son åt Kisi, son åt Abdi, son åt Malluk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'son åt Hasabja, son åt Amasja, son åt Hilkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'son åt Amsi, son åt Bani, son åt Semer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'son åt Mahli, son åt Musi, son åt Merari, son åt Levi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Og brørne deira, levitarne, var sette til alt slag tenesta i huset, Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Men Aron og sønerne hans ofra på brennofferaltaret og på røykjelsealtaret og skulde greida alle gjeremål i det høgheilage romet og gjera soning for Israel, i alle måtar so som Moses, Guds tenar, hadde sagt fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Desse var sønerne åt Aron: Eleazar, son hans; son hans var Pinehas; hans son var Abisua;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'hans son var Bukki; hans son var Uzzi; hans son var Zerahja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'hans son var Merajot; hans son var Amarja; hans son var Ahitub;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'hans son var Sadok; hans son var Ahima’as.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Og bustaderne deira, etter tjeldlægri innanfor umkverven deira, var dei som her kjem. Dei gav Arons-sønerne av kahatitætti - som fyrste luten fall på -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Hebron i Judalandet, og utmarki som låg ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Men åkerlandet og gardarne som høyrde til byen, gav dei Kaleb Jefunneson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Arons-sønerne gav dei soleis fredsstaderne Hebron og Libna, og Jattir og Estemoa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'og Hilen og Debir');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'og Asan og Bet-Semes, alle desse byarne med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'og i Benjaminsfylket Geba og Allemet og Anatot med bumarki som høyrde til; det var i alt trettan byar etter ætterne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Og dei andre Kehats-sønerne gav dei ti byar i det eine halve Manassefylket, og let deim draga strå um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Og Gersoms-sønerne og ættgreinene deira fekk trettan byar hjå Issakars-ætti, Assers-ætti, Naftali-ætti, og Manasse-ætti i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Merari-sønerne og ættgreinene deira fekk tolv byar hjå Rubens-ætti og Gads-ætti og Sebulons-ætti, og let deim draga strå um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Dess byarne med bumarki som høyrde til, gav Israels-sønerne åt levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Dei gav deim desse byarne, som dei nemde på namn, i Judafylket, Simeonsfylket og i Benjaminsfylket, og let deim draga strå um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Og nokre av greinerne i Kahats-ætti fekk desse byarne i Efraimsfylket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Fredstaderne Sikem på Efraimsfjellet og Gezer');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'og Jokmeam og Bet-Horon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'og Ajjalon og Gat-Rimmon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'og i det eine halve Manassefylket Aner og Bileam, med bumarki som høyrde kvar by til. Dette fekk dei hine greinerne av Kahats-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Gersoms-sønerne fekk i det andre halve Manassefylket Golan i Basan og Astarot, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'og i Issakarsfylket Kedes og Dobrat');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'og Ramot og Anem, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'og i Assersfylket Masal og Abdon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'og Hukok og Rehob, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'og i Naftalifylket Kedes i Galilæa, og Hammon og Kirjatajim, med bumarki som høyrde kvar by til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Dei hine Merari-sønerne fekk i Sebulonsfylket Rimmono og Tabor, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'og på hi sida Jordan ved Jeriko, austanfor Jordan, fekk dei i Rubensfylket Beser i øydemarki og Jahsa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'og Kedemot og Mefa’at, med bumarki som høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'og i Gadsfylket Ramot i Gilead og Mahanajim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'og Hesbon og Jazer, med bumarki som høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Og sønerne åt Issakar var Tola og Pua, Jasib og Simron, fire i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Sønerne hans Tola var Uzzi og Refaja, Jeriel, Jahmai, Jibsam og Samuel, hovdingar for ættgreinerne sine, som var ætta frå Tola, stridsføre hermenner, uppskrivne etter sine ætter. Talet på deim var i Davids tid tvo og tjuge tusund og seks hundrad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Sønerne åt Uzzi var Jizrahja, og sønerne åt Jisrahja var Mikael og Obadja og Joel og Jissia, ættarhovdingar alle fem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Og med deim fylgde herbudde flokker, seks og tretti tusund mann, etter sine ætter og ættgreiner; for dei hadde mange konor og born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Og frendarne deira i alle Issakars-ætterne var stridsføre hermenner; i alt var dei sju og åtteti tusund mann som var uppskrivne i ættarlista deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Sønerne åt Benjamin var Bela og Beker og Jediael, tri i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Og sønerne hans Bela var Esbon og Uzzi, Uzziel, Jerimot og Iri, fem i talet, ættarhovdingar, stridsføre hermenner, og i ættarlista deira stod det tvo og tjuge tusund og fire og tretti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Sønerne hans Beker var Zemira og Joas, Eliezer og Eljoenai, Omri og Jeremot, Abia og Anatot og Alemet; dei var søner åt Beker alle i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'I ættarlista deira etter ætterne, ættarhovdingarne og stridsføre hermenner, var dei tjuge tusund og tvo hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Sønerne åt Jediael var Bilhan, og sønerne hans Bilhan var Je’is og Benjamin og Ehud, Kena’ana og Zetan, Tarsis og Ahisahar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Alle desse var søner åt Jediael, uppskrivne etter hovdingarne for ættgreinerne sine, stridsføre hermenner, syttan tusund og tvo hundrad våpnføre menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Og Suppim og Huppim var sønerne åt Ir. Men Husim var sønerne åt Aher.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Sønerne åt Naftali var Jahsiel, Guni, Jeser og Sallum, sønerne hennar Bilha.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Sønerne åt Manasse: Asriel som kvinna åtte; den syriske fylgjekona hans åtte Makir, far hans Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Og Makir tok ut kona åt Huppim og Suppim. Syster hans heitte Ma’aka. Og den andre heitte Selofhad. Og Selofhad hadde døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Og Ma’aka, kona hans Makir, åtte ein son og gav honom namnet Peres, og hans bror heitte Seres. Sønerne hans var Ulam og Rekem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Son åt Ulam var Bedan. Desse var søner åt Gilead, son åt Makir, son åt Manasse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Og syster hans var Hammoleket; ho åtte Ishod og Abiezer og Mahla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Og sønerne åt Semida var Ahjan og Sekem og Likhi og Aniam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Og sønerne åt Efraim var Sutelah - hans son var Bered, hans son Tahat, hans son Elada, hans son Tahat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'hans son Zabad, og hans son Sutelah - og so Ezer og Elad. Og menner frå Gat, som var heimefolket der i landet, drap deim, for di dei hadde fare ned og vilde rana feet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Då syrgde Efraim, far deira, i lang tid, og brørne hans kom og vilde trøysta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Og han gjekk inn til kona si, og ho vart med barn og åtte ein son, som han kalla Beria, for di dette hende i ei ulukketid for huset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Dotter hans var Se’era; ho bygde Nedre og Øvre Bet-Horon og Uzzen-Se’era.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Og son hans var Refa, og hans søner var Resef og Telah; hans son var Tahan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'hans son Ladan, hans son Ammihud, hans son Elisama,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'hans son Non, hans son Josva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Og odelslandet og bustaderne deira var Betel med bygderne ikring, og i aust Na’aran, i vest Gezer med bygderne ikring og Sikem med bygderne ikring alt til Gaza med bygderne ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Men Manasse-sønerne hadde Bet-Sean med bygderne ikring, Ta’anak med bygderne ikring, Megiddo med bygderne ikring, Dor med bygderne ikring. I desse budde sønerne åt Josef Israelsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Sønerne åt Asser var Jimna og Jisva, Jisvi og Beria, og Serah var syster deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Sønerne åt Beria var Heber og Malkiel; han var far åt Birzait.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Og Heber fekk sonen til Jaflet, og Somer og Hotam, og Sua, syster deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Og sønerne hans Jaflet var Pasak og Bimhal og Asvat; desse var sønerne åt Jaflet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Sønerne hans Semer var Ahi og Rohga, Jehubba og Aram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Sønerne åt Helem, bror hans, var Sofah og Jimna og Seles og Amal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sønerne åt Sofah var Suah og Harnefer og Sual og Beri og Jimra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser og Hod og Samma og Silsa og Jitran og Be’era.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Sønerne åt Jeter var Jefunne og Pispa og Ara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Sønerne åt Ulla var Arah og Hanniel og Risja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Alle desse var søner åt Asser, hovdingar for ættgreinerne sine, utvalde stridsføre hermenner, dei høgste hovdingarne; og dei som stod i ættarlista og var duglege hermenner, var seks og tjuge tusund i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Og Benjamin fekk sonen Bela, som var eldst; Asbel var den andre og Ahrah den tridje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noha den fjorde, og Rafa den femte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Bela hadde desse sønerne: Addar og Gera og Abihud');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'og Abisua og Na’aman og Ahoah');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'og Gera og Sefufan og Huram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Og desse var sønerne åt Ehud - og dei var ættarhovdingar for Geba-buarne som vart burtførde til Manahat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'dit Na’aman og Ahia og Gera, førde deim -: han fekk sønerne Uzza og Ahihud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Og Saharajim fekk born i Moablandet etter han hadde sendt frå seg Husim og Ba’ara, konorne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Med Hodes, kona si, fekk han sønerne Jobab og Sibja, Mesa og Malkam');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'og Je’us og Sakja og Mirma; desse var sønerne hans, ættarhovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Med Husim hadde han fenge Abitub og Elpa’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Og sønerne hans Elpa’al var Eber og Misam og Semed. Det var han som bygde Ono og Lod og bygderne ikring -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'og Beria og Sema var ættarhovdingarne for Ajjalon-buarne og dreiv burt Gat-buarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'og Ahjo, Sasak og Jeremot');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'og Zebadja og Arad og Eder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mikael og Jispa og Joha var søner åt Beria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Og Zebadja, Mesullam, Hizki, Heber,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jizlia og Jobab var sønerne hans Elpa’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Og Jakim, Zikri, Zabdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai og Silletai og Eliel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja og Simrat var sønerne hans Sime’i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispan, Eber, Eliel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zikri, Hanan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Elam, Antotia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdeja og Penuel var sønerne hans Sasak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Og Samserai, Seharja, Atalja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Ja’aresja, Elia og Zikri var sønerne hans Jeroham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Desse var hovdingar for ættgreiner, hovdingar etter si ætt; dei budde i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'I Gibeon budde far åt Gibeon, og kona hans heitte Ma’aka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Og den fyrste son hans var Abdon; deretter Sur og Kis og Ba’al og Nadab');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'og Gedor, Ahjo og Zeker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Men Miklot fekk sonen Simea. Dei og budde i lag med brørne sine i Jerusalem, midt fyre brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Og Ner fekk sonen Kis, og Kis fekk sonen Saul, og Saul vart far åt Jonatan og Malkisua, Abinadab og Esba’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Son åt Jonatan heitte Meribba’al, og Meribba’al fekk sonen Mika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Sønerne hans Mika var Piton, Melek, Tarea og Ahaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahaz fekk sonen Joadda, og Joadda fekk sønerne Alemet, Azmavet og Zimri, og Zimri var far åt Mosa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Mosa vart far åt Bina. Hans son var Rafa; hans son var Elasa; hans son var Asel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Og Asel hadde seks søner, og namni deira var Azrikam, Bokeru, Ismael, Searja, Obadja og Hanan. Alle desse var søner åt Asel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Og sønerne åt Esek, bror hans, var Ulam, som var eldst, Je’us, den andre, og Elifelet, den tridje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Og sønerne hans Ulam var stridsføre hermenner, som spente boge, og dei hadde mange søner og sonesøner, hundrad og femti i talet. Alle desse var Benjamins-søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Og heile Israel vart innførte i ættarlista, og no er dei uppskrivne i boki åt Israels-kongarne. Og Juda vart førd i utlægd til Babel for sin utruskap skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Men det fyrre landsfolket som budde på eigedomen sin, i byarne sine; var vanlege israelitar, prestar, levitar og tempelsveinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'I Jerusalem budde nokre av Juda-sønerne, av Benjamins-sønerne og av Efraims- og Manasse-sønerne; det var:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utai, son åt Ammihud, son åt Omri, son åt Imri, son åt Bani, av borni åt Peres Judason;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'av silonitarne: Asaja, den eldste, og sønerne hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'og av Zerahs-sønerne: Je’uel og brørne deira, seks hundrad og nitti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'av Benjamins-sønerne: Sallu, son åt Mesullam, son åt Hodavja, son åt Hassenua,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'og Jibneja, son åt Jeroham, og Ela, son åt Uzzi, son åt Mikri, og Mesullam, son åt Sefatja, son åt Re’uel, son åt Jibnija,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'og brørne deira etter ætterne sine, ni hundrad og seks og femti. Alle desse mennerne var hovdingar for ættgreiner, kvar for si ættgrein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Og av prestarne: Jedaja og Jojarib og Jakin');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'og Azarja, son åt Hilkia, son åt Mesullam, son åt Sadok, son åt Merajot, son åt Ahitub, hovdingen i Guds hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'og Adaja, son åt Jeroham, son åt Pashur, son åt Malkia, og Masai, son åt Adiel, son åt Jahzera, son åt Mesullam, son åt Mesillemit, son åt Immer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'og brørne deira, hovdingar for ættgreinerne sine, eitt tusund og sju hundrad og seksti, dugande menner til å gjera tenesta i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Og av levitarne: Semaja, son åt Hassub, son åt Azrikam, son åt Hassabja, av Merari-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'og Bakbakkar, Heres og Galal og Mattanja, son åt Mika, son åt Zikri, son åt Asaf,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'og Obadja, son åt Semaja, son åt Galal, son åt Jedutun, og Berekja, son åt Asa, son åt Elkana, som budde i netofatit-bygderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Og dørvaktarane: Sallum og Akkub og Talmon og Ahiman og brørne deira; Sallum var hovdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Og endå vaktar dei kongeporten, på austsida. Desse var dørvaktarar i levitlægri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Men Sallum, son åt Kore, son åt Ebjasaf, son åt Korah, og brørne hans som var av ættgreini hans, korahitarne, hadde den tenesta å halda vakt ved dørstokken til tjeldet; for federne deira hadde vakta inngangen til Herrens læger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Og Pinhas, son åt Eleazar, var i gamle dagar forstandaren deira; Herren var med honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zakarja, son åt Meselemja, var dørvaktar ved møtetjelddøri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Alle desse var utvalde til dørvaktarar, tvo hundrad og tolv mann. Dei var uppskrivne i ættarlista i bygderne sine. David og sjåaren Samuel hadde sett deim til å tena på tru og æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Dei og sønerne deira stod difor ved dørerne åt Herrens hus, tjeldhuset, og heldt vakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Etter dei fire himmelætterne stod dørvaktarane, mot aust, mot vest, mot nord og mot sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Og brørne deira, som budde i bygderne sine, skulde møta fram hjå deim sjuande kvar dag, og alltid på same timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'For desse fire var på tru og æra sette formenner for dørvaktarane. Dette var no levitarne. Dei hadde og tilsyn med kovarne og buderne i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Og dei heldt til rundt ikring Guds hus um natti; for det låg på deim å halda vakt, og dei skulde lata upp dørerne kvar morgon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Sume av deim såg til med arbeidsgognerne. Dei tok då tal på deim, både når dei bar deim inn, og når dei bar deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Og sume av deim var sette til å hava tilsyn med dei andre gognerne, alle dei andre gognerne i heilagdomen, og med det fine mjølet og vinen og oljen og røykjelsen og kryddorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Men nokre av prestesønerne laga kryddesalven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Og Mattitja, ein av levitarne, eldste son åt korahiten Sallum, hadde på tru og æra tilsynet med brødbakstren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Og nokre av kahatitarne, brørne deira, såg til med skodebrødi og skulde laga deim til for kvar kviledag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Dette var songarane, hovdingar for levitættar; dei slapp å gjera anna arbeid, og heldt til i kovarne; for dei laut halda på med sine eigne gjeremål natt og dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Dette var hovdingar for ættgreinerne av levitarne, hovdingar etter si ætt; dei budde i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'I Gibeon budde Je’uel, far hans Gibeon, og kona hans heitte Ma’aka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Og den fyrste son hans var Abdon; og so Sur, Kis, Ba’al, Ner og Nadab,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor og Ahjo, Zakarja og Miklot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Men Miklot fekk sonen Simeam. Dei og budde i lag med brørne sine i Jerusalem, midt fyre brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Og Ner fekk sonen Kis, og Kis fekk sonen Saul, og Saul fekk sønerne Jonatan og Malkisua, Abinadab og Esba’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Son åt Jonatan var Meribba’al, og Meribba’al fekk sonen Mika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Sønerne hans Mika var Piton og Melek og Tahrea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahaz fekk sonen Jara, og Jara fekk sønerne Alemet, Azmavet og Zimri, og Zimri fekk sonen Mosa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Mosa fekk sonen Bina. Hans son var Refaja; hans son var Elasa; hans son var Asel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Og Asel hadde seks søner, og namni deira var: Azrikam, Bokeru, Ismael, Searja, Obadja og Hanan. Dette var sønerne åt Asel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Og filistarane stridde mot Israel, og Israels-mennerne flydde for filistarane, og det vart liggjande mange falne på Gilboafjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Og filistarane sette etter Saul og sønerne hans, og då felte dei Jonatan og Abinadab og Malkisua, sønerne hans Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Då dei no søkte hardt innåt Saul sjølv, og bogeskyttarane kom yver han, og han fekk ein støkk i seg for skyttarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Og Saul sagde til våpnsveinen sin: «Drag ut sverdet ditt og stikk det igjenom meg, so ikkje desse u-umskorne skal koma og fara ille med meg!» Men våpnsveinen hans vilde ikkje; for han var ovleg rædd. Då tok Saul sjølv sverdet og stupte seg på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Men då våpnsveinen såg at Saul var dåen, stupte han seg og på sitt sverd og døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'So døydde då Saul og dei tri sønerne hans; og dei som høyrde til hans hus, døydde alle i ein gong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Då so alle dei Israels-mennerne som var i dalen, såg at dei hadde flytt, og at Saul og sønerne hans var falne, so for dei frå byarne sine og rømde undan, og so kom filistarane og slo seg ned i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Andre dagen kom filistarane og skulde plundra liki, og dei fann då Saul og sønerne hans liggjande på Gilboafjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Og dei plundra honom, og tok med seg hovudet og våpni hans og sende deim ikring i Filistarlandet, og kunngjorde gledebodet for avgudarne sine og for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Og dei lagde våpni hans i gudshuset sitt; men hausen hans feste dei i Dagons-templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Då heile Jabes i Gilead høyrde alt det som filistarane hadde gjort med Saul,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'drog dei av, alle våpnføre menner, og tok liket åt Saul og liket åt sønerne hans og førde deim til Jabes, og jorda beini deira under eiki i Jabes og heldt fasta i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'So let Saul livet for sin utruskap mot Herren, med di han ikkje hadde fylgt Herrens ord, og like eins for di han hadde spurt ei som mana fram draugar og søkt råd hjå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Han hadde ikkje søkt råd hjå Herren; difor let Herren honom døy, og sidan let han David Isaison få kongedømet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Då kom heile Israel i hop hjå David i Hebron og sagde: «Du veit me og du er same folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Alt longe sidan, då Saul endå var konge, var du den som førde Israel. Og til deg hev Herren din Gud, sagt: «Du skal vera ein hyrding for Israel, folket mitt, ja, du skal vera ein hovding yver mitt folk Israel.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Då so alle styresmennerne i Israel kom til kongen i Hebron, gjorde David eit samband med deim der i Hebron for Herrens åsyn, og sidan salva dei David til konge yver Israel, etter Herrens ord gjenom Samuel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Og David for med heile Israel til Jerusalem, det er Jebus; der var jebusitarne, som endå var att i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Og Jebus-buarne sagde til David: «Du kjem ikkje inn her.» Men David tok like vel Sionsborgi, det er Davidsbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Og David sagde: «Den som fyrst drep ein jebusit, kven det so er, han skal verta hovding og herførar.» Og Joab, son åt Seruja, kom fyrst upp, og vart då hovding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Sidan sette David seg til i borgi; difor kalla dei henne Davidsbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Og han bygde byen rundt umkring, frå Millo og heilt ikring, og Joab bygde upp att det andre av byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Og Davids velde auka Davids velde stødt og stendigt, og Herren, allhers drott, var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Og dette er dei gjævaste kjemporne hans David, som gav honom kraftig hjelp, i lag med heile Israel, til å verta konge, til å gjeva honom kongedømet hans, etter Herrens ord um Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Dette er talet på kjemporne hans David: Jasobam, son til hakmoniføraren for kjemporne; han svinga spjotet sitt yver tri hundrad, som vart drepne i ein gong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Og etter han kom Eleazar, son åt Dodo, ahohiten; han var ein av dei tri kjemporne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Han var med David i Pas-Dammim, då filistarane hadde kome saman til strid, og der var ein åkerlapp fullgrodd med bygg; og folket rømde for filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Då stødte dei seg upp midt på åkerleppen og varde honom og hogg ned filistarane, og Herren gav deim soleis ein stor siger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Ein gong for tri av dei tretti hovdingarne nedetter berget til David ved Adullams-helleren, medan ein flokk med filistar hadde lægra seg i Refa’imsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Men David var den gongen i borgi, og ein av filistarvaktpost var då i Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Då fekk David brått ein sterk hug og sagde: «Å um einkvan vilde gjeva meg vatn å drikka utor brunnen som er attmed porten i Betlehem!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Då slo dei tri seg gjenom filistarlægret og auste vatn utor brunnen ved porten i Betlehem, og tok og bar det åt David. Men David vilde ikkje drikka det, men helte det ut for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'For han sagde: «Gud late det aldri koma i mine tankar at eg skulde gjera slikt! Skulde eg drikka blodet av desse mennerne som hev våga livet? For med livs vågnad hev dei bore det hit.» Han vilde ikkje drikka det. Dette hadde dei tri kjemporne gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Absai, bror hans Joab, var føraren for dei tri; han svinga spjotet sitt yver tri hundrad, som vart drepne. Og han var namngjeten millom dei tri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Han var ein gong til so mykje vyrd som nokon annan i dette tritalet, og han var hovdingen deira; men endå nådde han ikkje upp til dei tri fyrste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, son hans Jojada, som var son åt ein djerv og dådrik mann frå Kabse’el, han drap dei tvo Arielarne i Moab, og det var han som steig ned i brunnen ein snøversdag og slo i hel ei løva der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Han felte og den risestore egyptaren som var fem alner høg. Endå egyptaren hadde eit spjot i handi som liktest stor-riven i ein vev, so gjekk han imot honom, og hadde ikkje anna til verja enn staven sin. Og han rykte spjotet ut or handi på egyptaren og drap honom med hans eige spjot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Dette hadde Benaja Jojadason gjort. Og han var namngjeten millom dei tri kjemporne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Ja, han var meir vyrd enn nokon av dei tretti; men upp til dei tri fyrste nådde han ikkje. Og David sette honom til hovding yver livvakti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Dei djerve herkjemporne var desse: Asael, bror åt Joab, Elhanan, son åt Dodo, frå Betlehem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammot, haroriten. Heles, peloniten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, son åt Ikkes, frå Tekoa, Abiezer frå Anatot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'husatiten Sibbekai, ahohiten Ilai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai frå Netofa, Heled, son åt Ba’ana, frå Netofa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itai, son åt Ribai, frå Gibea i Benjaminsfylket, Benaja frå Piraton,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai frå Ga’asdalarne, Abiel frå Arba,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavet frå Baharum, Eljahba, sa’alboniten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Bene-Hasem, gizoniten, Jonatan, son åt Sage, harariten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam, son åt Sakar, harariten, Elifal, son åt Ur,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefer, mekeratiten, Ahia, peloniten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hesro frå Karmel, Na’arai, son åt Ezbai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, bror åt Natan, Mibhar, son åt Hagri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selek, ammoniten, Nahrai frå Berot, våpnsvein åt Joab Serujason,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira frå Jeter, Gareb frå Jeter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria, hetiten, Zabad, son åt Ahlai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, son åt Siza, rubeniten, ein hovding millom rubenitarne, og umfram honom tretti andre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, son åt Ma’aka, og Josafat, mitniten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzzia frå Astera, Sama og Je’uel, søner åt Hotam, aroeriten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, son åt Simri, og Joha, bror hans, tisiten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Hammahavim og Jeribai og Josavja, søner åt Elna’am, og Jitma, moabiten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed og Ja’asiel Hammesobaja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Og dette er dei som kom til David i Siklag, medan han endå heldt seg undan Saul Kisson; dei var av dei kjemporne som hjelpte han i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Dei var væpna med boge og føre til å slyngja stein og skjota piler frå bogen, både med høgre og vinstre handi. Av ættefrendarne hans Saul, av Benjamins-folket, var desse:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Ahiezer, den hævaste, og Joas, søner åt Sema’a frå Gibea, Jezuel og Pelet, sønerne åt Azmavet, og Beraka, og Jehu frå Anatot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jismaja frå Gibeon, ein av dei tretti kjemporne og hovding for dei tretti, Jirmeja og Jahaziel og Johanan og Josabad frå Gedera,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzai og Jerimot og Bealja og Semarja og Sefatja frå Harif,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana og Jissa og Azarel og Joezer og Jasobam, korahitarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela og Zebadja, søner til Jeroham, frå Gedor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Og av gaditarne var det nokre som fall ifrå og gav seg med David i fjellborgi i øydemarki; det var djerve menner, herføre stridsmenner, væpna med skjold og spjot. Dei hadde ei uppsyn som løvor, og var rappe som gasellor på fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer var den hævaste; Obadja var den andre, Eliab den tridje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismanna den fjorde, Jirmeja den femte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Attai den sette, Eliel den sjuande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Johanan den åttande, Elzabad den niande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jirmeja den tiande, Makbannai den ellevte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Desse var av Gads-sønerne og av dei hævaste i heren; den ringaste av deim var like god åleine som hundrad mann, og den gjævaste jamngod med tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Det var dei som gjekk yver Jordan den fyrste månaden då elvi gjekk yver breidderne, og som jaga av alle dalbuarne mot aust og mot vest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Av Benjamins- og Juda-sønerne kom det nokre menner til David alt til fjellborgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Då gjekk David ut imot deim, og tok til ords og sagde til dei: «I fall de er meinte på fred og vil hjelpa meg, so er hugen min reidug til semja med dykk. Men kjem de og vil gjeva meg yver til fiendarne mine, endå det ingen urett er i mine hender, då sjå fedreguden vår på det og refse det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Men anden greip Amasai, den hævaste av dei tretti, og han sagde: «Deg, David, høyrer me til, og i lag med deg, Isaisonen, vil me standa. Fred, fred vere med deg, og fred vere med hjelpesmennerne dine! For din Gud hev hjelpt deg.» Då tok David imot deim og sette deim til hovdingar yver herflokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Av Manasse var det og nokre som gav seg med David då han drog ut i lag med filistarane til strid mot Saul, endå han sidan ikkje fekk hjelpa deim; for då filisterhovdingarne hadde halde samråd, sende dei honom burt, med di dei sagde: «Det stend um hovudet for oss um han gjeng yver til Saul, herren sin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Då han so for til Siklag, gav desse av Manasse seg med honom: det var Adna, Jozabad, Jediael, Mikael, Jozabad, Elihu og Silletai, hovdingar for dei herflokkarne som høyrde til Manasse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Desse hjelpte David mot røvarflokkarne; for dei var djerve hermenner alle saman, og dei vart hovudsmenner i heren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'For det kom dagstødt folk til David som vilde hjelpa honom, so herlægret hans til slutt vart ovleg stort, som eit Guds herlæger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Dette er talet på dei stridsbudde hermennerne som kom til David i Hebron og vilde gjeve honom Sauls kongedøme i hende etter Herrens bod:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Juda-sønerne som bar skjold og spjot, seks tusund og åtte hundrad herbudde menner;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Simeons-sønerne, stridsføre hermenner, sju tusund og eit hundrad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'av Levi-sønerne fire tusund og seks hundrad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'og dertil Jojada, hovdingen for Arons-ætti, og tri tusund og sju hundrad mann med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'og Sadok, ein våpndjerv ungdom, og ætti hans, tvo og tjuge hovdingar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'av Benjamins-sønerne, ættefrendarne hans Saul, tri tusund; for mengdi av deim heldt seg endå trutt til Sauls hus i den tidi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'av Efraims-sønerne tjuge tusund og åtte hundrad herføre stridsmenner, namngjetne menner i ætterne sine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'av eine helvti av Manasse-ætti attan tusund, som var nemde med namn og kom og skulde gjera David til konge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'av Issakars-sønerne slike menner som hadde skyn på tidartekni, og visste kva Israel burde gjera; det var tvo hundrad hovdingar, og dertil alle ættefrendarne deira, som dei hadde styringi yver;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'av Sebulon femti tusund stridsføre menner, herbudde med alle slag våpn; dei flokka seg samheldige;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'av Naftali eit tusund hovdingar, og med deim sju og tretti tusund mann som var væpna med skjold og spjot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'av danitarne åtte og tjuge tusund og seks hundrad herbudde menner;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'av Asser stridsføre og herbudde menner, fyrti tusund;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'og frå hi sida åt Jordan, av rubenitarne, gaditarne og andre helvti av Manasse-ætti, eit hundrad og tjuge tusund mann med alle slag våpn som er bruklege i strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Alle desse hermennerne skipa seg i fylking og kom med hjartans godhug for David til Hebron og vilde gjera honom til konge yver heile Israel. Men alle hine av Israel var og sameinte i å gjera David til konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Og dei var der hjå David i tri dagar og åt og drakk; for brørne deira hadde laga til åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Dei som budde nær ved, alt upp til Issakar, Sebulon og Naftali, førde og nøgdi med føda til deim, på asen, kamelar, muldyr og uksar; grjonmat, fikekakor, rosinkakor, vin og olje, bufe og sauer; for det var gleda i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Og David samrådde seg med dei øvste herførarane og underførarane, med alle hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Og David sagde til heile Israels-lyden: «I fall de so finn fyre, og um dette er ifrå Herren, vår Gud, so lat oss senda bod til alle kantar åt dei andre brørne våre i alle Israels bygder, og dessutan åt prestarne og levitarne i dei byarne som dei hev bumark ikring, at dei skal koma saman hjå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Og lat oss flytja kista åt vår Gud hit til oss! For i Sauls dagar spurde me ikkje etter henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Og heile lyden svara at dei skulde gjera det; for alt folket lika denne rådi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'So samla då David heile Israel ifrå kvisli frammed Egyptarlandet og alt dit der vegen gjeng til Hamat, at dei skulde føra Guds kista frå Kirjat-Jearim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Og David for med heile Israel upp til Ba’ala, til Kirjat-Jearim, som høyrer til Juda, med den etlingi å føra upp kista åt Gud Herren, han som tronar yver kerubarne, og som ho hev fenge namnet sitt etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Og dei sette Guds kista på ei ny vogn og førde henne burt frå huset hans Abinadab, og Uzza og Ahjo køyrde vogni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Og David og heile Israel leika for Gud av all si magt med song og med cithrar, harpor, trummor, cymblar og trompetar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Men då dei kom til treskjestaden hans Kidon, rette Uzza ut handi og vilde fata i kista; for uksarne snåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Då vart Herren brennande harm på Uzza, og han slo honom for di han hadde rett ut handi si åt kista, so han døydde der for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Men David vart ille ved, av di Herren soleis hadde slege ned Uzza, og han kalla den staden Peres-Uzza, som det heiter den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Og David fekk ei slik rædsla for Gud den dagen, at han sagde: «Kor kann eg våga føra Guds kista til meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Difor flutte ikkje David kista til seg i Davidsbyen, men sette henne inn i huset åt gatiten Obed-Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Guds kista vart då verande ved huset hans Obed-Edom, der ho stod i sitt eige hus i tri månader; men Herren velsigna Obed-Edoms hus og alt det som høyrde honom til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Og Hiram, kongen i Tyrus, sende folk til David med cedertre, og dessutan murarar og timbremenner til å byggja eit hus åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Og David skyna at Herren hadde stadfest honom til konge yver Israel; for han hadde lyft kongedømet høgt for sitt folk Israel skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Og David tok seg endå fleire konor i Jerusalem, og David fekk endå fleire søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Dette er namni på dei sønerne han fekk i Jerusalem: Sammua og Sobab, Natan og Salomo,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar og Elisua og Elpelet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'og Nogah og Nefeg og Jafia');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'og Elisama og Be’eljada og Elifelet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Men då filistarane høyrde at David var salva til konge yver heile Israel, tok dei ut alle saman og skulde leita etter David. Då David fekk høyrde det, for han ut imot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Filistarane kom og spreidde seg utyver i Refa’imsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Då spurde David Gud: «Skal eg draga upp imot filistarane? Vil du då gjeva deim i mi hand?» Herren svara: «Drag upp, eg vil gjeva deim i di hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Og dei tok ut til Ba’al-Perasim, og der vann David yver deim. Då sagde David: «Gud hev brote igjenom fiendarne mine med mi hand, liksom vatn bryt igjenom.» Difor fekk den staden namnet Ba’al-Perasim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Dei let etter seg gudarne sine der, og David sagde at dei skulde brennast upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Men filistarane kom endå ein gong og spreidde seg utyver i dalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Då so David spurde Gud att, svara Gud honom: «Du skal ikkje fara imot deim; kringsett deim attanfrå, so du kjem yver deim ifrå den sida der bakatrei stend!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'So snart som du då høyrer ljoden av stig i toppen på bakatrei, skal du leggja ut i strid; for då fer Gud fyre deg og vil slå filistarheren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Og David gjorde som Gud hadde bode honom, og dei slo filistarheren og sette etter deim alt ifrå Gibeon og til Gezer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Og gjetordet um David gjekk yver alle land, og Herren let det koma rædsla for honom yver alle folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Og han bygde seg hus i Davidsbyen, og sidan laga han til ein stad åt Guds kista og sette upp eit tjeld åt henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Då baud David: «Ingen må bera Guds kista utan levitarne; for deim hev Herren valt ut til å bera Guds kista og til å tena honom» i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Og David samla heile Israel Jerusalem; til å føra Herrens kista upp til den staden han hadde laga til åt henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Og David stemnde i hop Arons-sønerne og levitarne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'av Kehats-sønerne Uriel, hovdingen, og brørne hans, eit hundrad og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'av Merari-sønerne Asaja, hovdingen, og brørne hans, tvo hundrad og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'av Gersoms-sønerne Joel, hovdingen, og brørne hans, eit hundrad og tretti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'av Elisafans-sønerne Semaja, hovdingen, og brørne hans, tvo hundrad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'av Hebrons-sønerne Eliel, hovdingen, og brørne hans, åtteti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'av Uzziels-sønerne Amminadab, hovdingen, og brørne hans, eit hundrad og tolv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Og David kalla åt seg prestarne Sadok og Abjatar og levitarne Uriel, Asaja og Joel, Semaja og Eliel og Amminadab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Og han sagde til deim: «De er hovdingar for ættgreinerne i Levi. Helga dykk, de og brørne dykkar, og før so kista åt Herren, Israels Gud, upp til den staden som eg hev laga til åt henne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Det var for di de ikkje var med fyrre gongen, at Herren, vår Gud, braut ned ein av oss, til straff for at me ikkje søkte honom som rett var.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Då helga dei seg, prestarne og levitarne, so dei kunde føra upp kista åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Og levitsønerne bar Guds kista med stenger som låg på herdarne deira, soleis som Moses hadde sagt deim fyre etter Herrens ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Og David baud levithovdingarne at dei skulde stella brørne sine, songarane, fram med spel, harpor, cithrar og cymblar, som dei skulde låta på medan dei let gledesongen ljoma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Levitarne sette då Heman Joelsson til dette, og av hans brør Asaf Berekjason, og av brørne deira, Merari-sønerne, Etan Kusajason,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'og jamsides med deim brørne deira av andre rangen, Zakarja, Ben, Ja’aziel og Semiramot og Jehiel og Unni, Eliab og Benaja og Ma’aseja og Mattitja, Eliflehu og Mikneja og Obed-Edom og Je’iel, dørvaktarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Songarane Heman, Asaf og Etan skulde slå på koparcymblar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zakarja og Asiel og Semiramot og Jehiel og Unni og Eliab og Ma’aseja og Benaja skulde spela på harpor etter Alamot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Mattitja og Eliflehu og Mikneja og Obed-Edom og Je’iel og Azazja skulde spela på cithrar etter Sjeminit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja, som var førar for levitarne ved beringi; skulde læra deim å bera; for han var kunnig i slikt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekja og Elkana skulde vera dørvaktarar ved kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Sebajna og Josafat og Netanel og Amasai og Zakarja og Benaja og Eliezer, prestarne, skulle blåsa i trompetar framfyre Guds kista. Og Obed-Edom og Jehia skulde vera dørvaktarar ved kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'So gjekk David og dei øvste i Israel og yverhovudsmennerne av stad og skulde føra Herrens sambandskista med fagnad upp or huset åt Obed-Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Og med di Gud verna levitarne som bar Herrens sambandskista, so ofra dei sju uksar og sju verar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Og David gjekk då med ei kappa av fint linan, og like eins alle levitarne som bar kista, og songarane, og Kenanja, føraren for songarane ved beringi. Dessutan bar David ein linhakel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Og heile Israel flutte Herrens sambandskista upp med fagnadrop og lurljom, og dei bles i trompetar og slo på cymblar let harpor og cithrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Då so Herrens sambandskista kom til Davidsbyen, såg Mikal, dotter åt Saul, ut gjenom vindauga, og då ho fekk auga på kong David, som hoppa og leika seg, vanvyrde ho honom i sitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Då dei hadde ført Guds kista inn, sette dei henne i tjeldet som David hadde sett upp åt henne; deretter bar dei fram brennoffer og takkoffer for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Og då David hadde ofra brennofferet og takkofferet, velsigna han folket i Herrens namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Og til kvar og ein av alle israelitarne, både kar og kvinna, skifte han ut ein brødleiv, eit stykke kjøt og ei rosinkaka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Og han sette sume levitar til å gjera tenesta framfor Herrens kista, at dei skulde prisa, takka og lova Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaf var den fremste, og Zakarja næst etter honom, og so Je’iel, Semiramot, Jehiel og Mattitja, Eliab, Benaja, Obed-Edom og Je’iel med harpor og cithrar, og Asaf skulde slå på cymblar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Men prestarne Benaja og Jahaziel skulde standa stendigt med trompetarne sine framfor Guds sambandskista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Den dagen var det at David fyrst fastsette den skipnaden at dei ved Asaf og brørne hans skulde prisa Herren på denne visi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '«Prisa Herren, kalla på hans namn! Forkynn millom folkeslagi hans storverk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Syng for honom, syng honom lov! Tala um alle hans under!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Rosa dykk av hans heilage namn, hjarta glede seg hjå deim som søkjer Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Spør etter Herren og hans magt, søk hans åsyn alltid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Kom i hug hans under som han hev gjort, hans undergjerningar og domsordi frå hans munn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'de etterkomarar av Israel, hans tenar, søner åt Jakob, hans utvalde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Han er Herren, vår Gud; yver all jordi gjeng hans domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Kom æveleg i hug hans pakt, det ord han sette fast for tusund ætter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'den pakt han gjorde med Abraham, og hans eid til Isak!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Han gjorde det til ein rett for Jakob, for Israel til ein æveleg pakt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'med di han sagde: «Deg vil eg gjeva Kana’ans land til arvlut,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'då de var ein liten flokk, få og framande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Og dei vandra frå folk til folk, frå eitt rike til eit anna folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Han let ikkje nokon få gjera valdsverk mot deim, og han refste kongar for deira skuld:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '«Rør ikkje deim eg hev salva, og gjer ikkje vondt med mine profetar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Syng for Herren, all jordi! Forkynn frå dag til dag hans frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Fortel millom heidningar hans æra, millom alle folkeslag hans under!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'For Herren er stor og mykje lovsungen, og skræmeleg er han framfor alle gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'For alle gudar hjå folki er avgudar; men Herren hev gjort himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Høgd og herlegdom er for hans åsyn, styrke og gleda er på hans stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Gjev Herren, de folkeætter, gjev Herren æra og magt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Gjev Herren hans namns æra, tak gåvor med og kom for hans åsyn, tilbed Herren i heilagt skrud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Skjelv for hans åsyn, all jordi! Jordriket stend fast; det let seg ikkje rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Himmelen glede seg, og jordi fagne seg, og dei skal segja millom heidningarne: «Herren er konge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Havet dure og alt som i det er! Marki frygde seg og alt det som på marki er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Då fegnast trei i skogen for Herrens åsyn; for han kjem og skal døma jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Prisa Herren, for han er god, for æveleg varer hans miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Og seg: «Frels oss, du vår Frelse-Gud, og samla oss og fria oss ut frå heidningarne, so me kann prisa ditt heilage namn, rosa oss av ditt lov!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Lova vere Herren, Israels Gud, frå æva og til æva!» Og alt folket sagde amen og lova Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Og der, framfor Herrens sambandskista, gav han Asaf og brørne hans det yrket, at dei stendigt skulde gjera tenesta framfor kista, soleis som det var fastsett for kvar dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Men Obed-Edom og brørne deira var åtte og seksti i tal, og Obed-Edom Jeditunsson og Hosa sette han til dørvaktarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Og pesten Sadok og brørne hans, prestarne, sette han framfor Herrens hus på offerhaugen i Gibeon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'at dei stendigt skulde ofra åt Herren brennoffer på brennofferaltaret, morgon og kveld, og gjera alt det som var fyresagt i Herrens lov, som han hadde sett for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Og i lag med deim var Heman og Jedutun og dei andre utvalde som var nemnde, at dei skulde lova Herren, av di hans miskunn varer æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Og trompetarne og cymblarne åt spelemennerne vart gøymde hjå Heman og Jedutun, og like eins andre spelgogner som høyrde gudstenesta til. Og Jedutuns-sønerne gjorde han til dørvaktarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Deretter gjekk heile lyden heim, kvar til sitt; men David snudde heim att, vilde helsa på husfolket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Ein gong David sat i huset sitt, sagde David til profeten Natan: «Sjå, eg bur i eit hus av cedertre, medan Herrens sambandskista stend under eit tjeld!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Natan sagde til David: «Gjer alt det som du hev i hugen; for Gud er med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Men natti etterpå kom Guds ord til Natan soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '«Gakk og seg til David, tenaren min: «So segjer Herren: Ikkje skal du byggja meg det huset eg skal bu i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'For eg hev då ikkje butt i noko hus, alt frå den dagen då eg førde Israel upp hit, og til denne dag, anna eg hev flutt frå tjeld til tjeld, frå hus til hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'I all den tidi eg hev fare ikring med heile Israel - hev eg då nokosinne tala so til nokon Israels domarar som eg sette til hyrding for folket mitt: «Kvi hev de ikkje bygt meg eit hus av cedertre?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Og no skal du segja so til David, tenaren min: «So segjer Herren, allhers drott: Frå buhagen, der du fylgte sauerne, hev eg teke deg til fyrste yver Israel, folket mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Og eg hev vore med deg på alle dine vegar og rudt ut alle fiendarne dine for deg. Og eg vil gjeva deg eit namn liksom namnet åt dei største menner på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Og eg skal reida ein heimstad åt Israel, folket mitt, og planta det so det kann verta buande der, og ikkje verta uroa meir. Valdsmenner skal ikkje meir øyda det, so som i gamle dagar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'alt ifrå den tidi då eg sette domarar yver mitt folk Israel; og eg skal mykja upp alle fiendarne dine. So gjer eg no det kunnigt for deg, at Herren skal byggja deg eit hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Når di æva er all, og du gjeng til federne dine, då skal eg reisa upp avkjømet ditt etter deg, ein av sønerne dine, og eg skal grunnfesta kongedømet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Han skal byggja eit hus åt meg; og eg skal grunnfesta kongsstolen hans til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Eg skal vera far hans, og han skal vera son min, og mi miskunn skal eg ikkje taka frå honom, liksom eg tok henne frå fyremannen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Og skal halda honom uppe i mitt hus og i mitt rike i all æva, og kongsstolen hans skal vera grunnfest i all æva.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Heilt i samhøve med desse ordi og med denne syni tala då Natan til David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Då gjekk kong David inn og sette seg ned for Herrens åsyn og sagde: «Kven er eg, Herre Gud, og kva er huset mitt, at du hev ført meg hit?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Og endå er det for lite i dine augo, Gud, du hev gjeve lovnader til huset åt tenaren um det som ligg langt fram i tidi. Ja, du hev set til meg på mannevis, so du kunde upphøgja meg, Herre Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Kva skal no David meir segja til deg um den æra du hev gjort tenaren din? Du kjenner då tenaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Herre, for din tenar skuld og etter ditt hjarta hev du gjort alt dette store, og kunngjort alle desse store ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herre, ingen er som du, og det er ingen Gud utan du, etter alt det me hev høyrt med øyro våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Og kvar finst det på jordi eit einaste folk maken til ditt folk Israel, som Gud sjølv gjekk av og løyste til si eigen lyd, til eit stort og øgjelegt namn åt deg, med di du dreiv ut heidningarne for folket ditt, som du hadde fria ut or Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Og du hev gjort ditt folk Israel til eit folk åt deg for all æva, og du, Herre, hev vorte deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'So lat då, Herre, det standa ved lag i all æva, som du hev tala um tenaren din og hans hus; gjer so som du hev sagt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Då skal namnet ditt haldast for traust og verta stort til æveleg tid, so dei skal segja: «Herren, allhers drott, Israels Gud, er Gud yver Israel.» Og då skal huset åt David, tenaren din, standa stødt for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'For du, min Gud, hev openberra for tenaren din at du skal byggja honom eit hus; difor hev tenaren din våga seg til å bera denne bøni fram for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Og no, Herre, du er Gud, og etter di du hev lova tenaren din denne gode ting,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'so lat det no og tekkjast deg å velsigna huset åt tenaren din, so det vart verande æveleg for di åsyn. For det som du, Herre, velsignar, det er velsigna i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Ei tid etter dette vann David yverpå filistarane og lagde deim under seg, og han tok då Gat og dei bygderne som låg ikring or henderne på filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Han vann og yver moabitar, og so vart dei tenarar åt David og lagde skatt til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Like eins vann David på Hadarezer, kongen i Soba, ved Hamat, då han hadde fare av stad og skulde tryggja magti si ved elvi Frat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Og David tok ifrå honom eit tusund vognhestar og sju tusund hestfolk og tjuge tusund mann fotfolk. Og David let skjera av hasarne på alle vognhestarne og sparde berre eit hundrad hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Og då syrarane frå Damaskus kom og skulde hjelpa Hadarezer, kongen i Soba, slo David tvo og tjuge tusund mann av syrarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Og David sette inn hervakter millom syrarane i Damaskus, og syrarane vart tenarar åt David og lagde skatt til honom. Soleis gav Herren David siger kvar helst han drog fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Og David tok dei gullskjoldarne som tenarane hans Hadarezer hadde bore, og førde deim til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Og frå Tibhat og Kun, byarne hans Hadarezer, tok David kopar i stor mengd; av det gjorde Salomo koparhavet, sulorne og koparkjeraldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Då so To’u, kongen i Hamat, høyrde at David hadde slege heile heren hans Hadarezer, kongen i Soba,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'sende han son sin, Hadoram, til kong David, at han skulde helsa på honom og ynskja honom til lukke med krigen mot Hadarezer og med sigeren yver kongen; for Hadarezer hadde jamt havt ufred med To’u. Han sende og alle slag kjerald av gull, sylv og kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Deim og vigde kong David til Herren, sameleis som det med det sylvet og gullet han hadde ført heim frå alle andre folk: frå edomitarne, moabiterne, Ammons-sønerne, filistarane og amalekitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Og Absai Serujason som slo edomitarne i Saltdalen, attan tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'So sette han vakt i Edom, og alle edomitarne vart tenarar åt David. Soleis gav Herren David siger kvar helst han for fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'David var no konge yver heile Israel, og han skipa lov og rett åt heile sitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab Serujason var øvste herhovding, og Josafat Ahiludsson var kanslar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sadok Ahitubsson og Abimelek Abjatarsson var prestar og Savsa riksskrivar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja Jojadason var hovding yver livvakti, men Davids søner var dei fyrste ved sida åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Sidan bar det so til at Nahas, kongen åt Ammons-sønerne, døydde, og son hans vart konge etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Då sagde David: «Eg vil syna Hanun Nahasson venskap, etter di far hans syne meg venskap.» Og David skikka sendemenner til å trøysta honom i hans sorg etter faren. Tenarane hans David kom då til landet åt Ammons-sønerne, til Hanun, og vilde trøysta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Då sagde hovdingarne for Ammons-sønerne til Hanun: «Trur du at David vil æra far din med det at han sender trøystarar til deg? Nei, det er til å gjera seg kjende i landet, til å øydeleggja og spæja det ut, at tenararne hans er komne til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Då tok Hanun tenararne åt David og let raka deim og skjera av klædi deira på midten rett upp åt med sætet, og let deim so fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Og det kom folk til David med tidend um mennerne; då sende han bod imot deim; for mennerne var groveleg svivyrde. Og kongen let segja: «Ver i Jeriko til dess skjegget dykkar er utvakse, og kom so heim att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Då no Ammons-sønerne skyna at dei hadde gjort David hatig på seg, sende Hanun og ammonitarne tvo og eit halvt tusund vågar sylv til å leiga seg vogner og hestfolk for frå Mesopotamia, frå Aram-Ma’aka og frå Soba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Dei leigde seg tvo og tretti tusund vogner og dertil hjelp hjå kongen i Ma’aka og hans folk; dei kom og lægra seg framfor Medba. Ammonitarane samla seg og or byarne sine og tok ut til strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Då David høyrde det, sende han Joab i veg med heile heren, dei djervaste hermennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Og Ammons-sønerne drog ut og fylkte seg framfor byporten; men kongarne som var komne dit, stod for seg sjølve på opi mark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Då Joab såg at han hadde fiendar både frampå og bak, gjorde han eit utval millom det utvalde mannskapet, og so fylkte han deim imot syrarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Men hitt folket han gav han yver til Absai, bror sin, og dei fylkte seg beint imot ammonitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Og han sagde: «I fall syrarane vinn på meg, so skal du koma meg til hjelp; og vinn Ammons-sønerne på deg, skal eg hjelpa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Ver no djerv; ja, lat oss syna manndom i striden for folket vårt og for byarne åt vår Gud! Og so fær Herren gjera det som han tykkjer best.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'So gjekk Joab fram med folket sitt til strid mot syrarane, og dei rømde for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Men då ammonitarne såg at syrarane rømde, so flydde dei og for Absai, bror hans, og drog seg inn i byen. Då for Joab heim til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Då syrarane såg at dei hadde roke for Israel, sende dei bod til syrarane som budde på hi sida åt elvi, at dei skulde taka ut med Sofak til herførar; han var hovudsmann hjå Hadarezer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Då David spurde dette, samla han heile Israel og gjekk yver Jordan, og då han kom fram til deim, fylkte han heren til strid imot syrarane, og so gav dei seg til å strida mot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Men syrarane rømde for Israel, og David hogg ned hermennerne på sju tusund vogner og fyrti tusund mann fotfolk av syrarane; herhovdingen Sofak felte han og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Då tenarane åt Hadarezer såg at dei hadde roke for israelitarne, gjorde dei fred med David og vart tenarane hans. Då vilde ikkje syrarane hjelpa ammonitarne meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Året etter ved det leitet kongarne plar fara i herferd, tok Joab ut med heren og herja landet åt Ammons-sønerne. Og han kom og kringsette Rabba, medan David vart verande i Jerusalem. Og Joab tok Rabba og øydela byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Og David tok kruna av hovudet på kongen deira; og det vart røynt at ho vog vel tvo vågar gull, og ho var prydd med ein dyr stein. Ho vart no sett på hovudet åt David, og han førde nøgdi av herfang burt or byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Og folket i byen førde han ut, og sette deim ved sagerne og treskjevalsarne av jarn og øksarne. Soleis for David åt med alle ammonitbyarne. So snudde David og alt folket heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Sidan vart det ein strid med filistarane ved Gezer; då vann husatiten Sibbekai yver Sippai, ein av Rafa-ætlingarne; so vart dei kua.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Sidan vart det ein ny strid med filistarane på nytt lag; Elhanan Ja’irsson hogg då ned Lahmi, bror åt Goliat frå Gat, som hadde eit spjotskaft som stor-riven på ein vev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'So stod det ein strid ved Gat. Der var det ein risestor mann, som hadde seks fingrar og seks tær, fire og tjuge i alt; han og var ætta frå rafa’itarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Han hædde Israel; men Jonatan, son åt Simea, som var bror åt David, drap honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Desse var ætta frå Rafa i Gat, og dei fall for David og tenarane hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Men Satan stod upp imot Israel og eggja David til å telja Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Då sagde David til Joab og dei andre hovdingarne for folket: «Gakk av stad og tak tal på Israels-folket frå Be’erseba og alt til Dan, og gjev meg so grein, so eg fær vita kor mykje folk det er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab svara: «Gjev Herren vilde auka folket sitt hundrad gonger! Er dei då ikkje, herre konge, tenarar åt herren min alle saman? Kvifor krev du då herren min slikt? Kvifor skal ein på slik måte draga skuld yver Israel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Men kongens bod vart standane ved lag med alt det Joab var imot. So tok då Joab ut, og for um i heile Israel og kom so heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Og Joab sagde David talet som var kome ut ved folketeljingi. I heile Israel var det ein million og hundrad tusund våpnføre mann, og i Juda fire hundrad og sytti tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Men Levi og Benjamin hadde han ikkje mynstra i lag med hine; for kongens ord var ei styggja for Joab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Og Gud mislika dette verket, og han slo Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Då sagde David til Gud: «Eg hev synda storleg med at eg hev gjort dette. Men forlat no tenaren din misgjerningi hans; for eg hev gjort ein stor dårskap.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Men Herren tala til Gad, sjåaren åt David, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '«Gakk av stad og tala til David og seg: «So segjer Herren: Tri ting legg eg fram fyre deg; vel deg ein av deim, som du vil eg skal gjera imot deg!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Då gjekk Gad inn til David og sagde til honom: «So segjer Herren: «Vel kva for eit du vil:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'anten svolt i tri år, eller manneøyding i tri månader, av di fiendarne dine søkjer åt, og du ikkje kann koma undan sverdet deira - eller Herrens sverd og drepsott i landet i tri dagar, med di Herrens engel gjer eit tjon i heile Israels land.» Tenk no etter kva svar eg skal gjeva honom som hev sendt meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David svara Gad: «Eg er stadd i stor våde. Men lat meg då falla i Herrens hand; for hans miskunn er stor; men i mannehand vil eg ikkje falla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Då let Herren det koma ei drepsott i Israel, og det fall sytti tusund mann av Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Og Gud sende ein engel mot Jerusalem til å tyna byen. Men då han heldt på med tyningi, såg Herren på det og han angra det vonde, og han sagde til engelen, tynaren: «No fær det vera nok. Tak no åt deg handi att!» Og Herrens engel stod då attmed treskjevollen hans Ornan, jebusiten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'So såg David upp og vart var Herrens engel, som stod millom jord og himmel med eit drege sverd i handi, og rette det ut yver Jerusalem. David og styresmennerne kasta seg å gruve, sveipte i sekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Og David sagde til Gud: «Det var då eg som baud at folket skulde teljast. Det er eg som hev synda og gjort det som gale er; men desse sauerne, kva hev dei gjort? Herre, min Gud, snu då handi di imot meg og huset åt far min, men ikkje mot folket ditt til heimsøkjing!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Men Herrens engel bad Gad segja til David, at han skulde ganga upp og reisa eit altar åt Herren på treskjarvollen hans Ornan, jebusiten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Og David gjekk upp etter det ordet som Gad hadde tala i Herrens namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Då so Ornan snudde seg ikring, fekk han sjå engelen; og dei fire sønerne hans som var hjå honom, dei gøymde seg. Men Ornan heldt just på og treskte kveite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Og David kom til Ornan, og då Ornan såg upp og vart var honom, gjekk han fram av treskjarvollen og kasta seg å gruve på jordi for David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Og David sagde til Ornan: «Gjev meg få den staden der du hev treskjarvollen, so eg der kann byggja eit altar for Herren. Lat meg få det mot fullt vederlag, so sotti kann stana og ikkje lenger herja folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Då sagde Ornan til David: «Tak vollen, og so gjere min herre kongen det som han tykkjer er best. Sjå her gjev eg deg uksane til brennofferi og treskjesledane til ved og kveiten til grjonofferet; det gjev eg alt i hop.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Men kong David svara Ornan: «Nei, eg vil kjøpa det for fullt vederlag; for eg vil ikkje taka åt Herren det som er ditt, og ofra brennoffer som eg hev fenge for inkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'So greide David åt Ornan seks hundrad lodd gull i god vegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Og David bygde der eit altar for Herren og ofra brennoffer og takkoffer. Og han ropa til Herren, og han svara honom med eld frå himmelen på brennofferaltaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Og Herren baud engelen, og han stakk sverdet sitt i slira att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Då David såg at Herren hadde høyrt bøni hans på treskjarvollen åt jebusiten Ornan, so ofra han der i den tidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Men Herrens hus som Moses hadde late gjera i øydemarki, og brennofferaltaret stod den tidi på offerhaugen i Gibeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Men David våga ikkje å ganga dit og søkja Gud, so forfærd var han for sverdet åt Herrens engel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Og David sagde: «Her skal huset åt Herren Gud standa, og her skal altaret for Israels brennoffer vera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Og David sende bod at dei skulde samla dei framande som var i Israels land, og han sette steinhoggarar til å hogga steinar til byggjevyrke åt Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Og David rådde seg nøgdi av jarn til spikar i portdørerne og til kjengar, og ei slik ovmengd med kopar at han var uvegande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'og cedertre i uteljande mengd; for Sidon- og Tyrus-buarne førde nøgdi av cedertre til David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'For David tenkte: «Salomo, son min, er ung og kløkk; men huset som skal byggjast åt Herren, bør vera ovstort, so det kann verta til gjetord og æra i alle land. Difor vil eg få til vegar vyrke åt honom.» So rådde David seg ei nøgd med vyrke fyrr han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'So kalla han til seg Salomo, son sin, og bad honom byggja eit hus åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Og David sagde til Salomo, son sin: «Eg hadde sjølv tenkt meg til å byggja eit hus for namnet åt Herren, min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Men Herrens ord kom til meg soleis: «Du hev rent ut mykje blod og gjort store herferder; du skal ikkje byggja eit hus åt namnet mitt; for du hev rent ut so mykje blod på jordi for mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Men du skal få ein son; han skal verta ein fredsæl mann; og eg skal lata honom få fred for alle fiendarne sine rundt ikring; for Salomo skal vera namnet hans, og eg skal lata fred og ro liggja yver Israel i hans dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Han skal byggja eit hus åt namnet mitt. Han skal vera son min, og eg skal vera far hans. Og eg skal grunnfesta kongsstolen hans yver Israel i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Herren vere no med deg, son min! Du have lukka med deg, so du fær byggja huset åt Herren din Gud, soleis som han hev tala um deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Berre Herren vil gjeva deg visdom og skyndsemd, når han set deg yver Israel, og hjelpa deg til å halda lovi frå Herren, din Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'so skal du hava lukka med deg, um du kjem i hug å liva etter dei bodi og loverne som Herren hev bode Moses leggja på Israel. Ver sterk og stød; du skal ikkje ræddast og ikkje fæla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Og trass i all mi naud hev eg no fenge fram til Herrens hus eit hundrad tusund talent gull og tusund gonger tusund talent sylv, og dertil meir kopar og jarn enn ein kann vega; so mykje er det; trevyrke og stein hev eg og rådt meg, og meir må du sjølv leggja attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Arbeidsfolk hev du og nøgdi av, håndverkarar, steinhoggarar og timbremenner, og dertil allslags folk som er hage til alt anna arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Gullet, sylvet, koparen og jarnet kann ein ikkje halda rekning på. Upp då og tak fatt på verket, og Herren vere med deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Deretter baud David alle hovdingarne i Israel hjelpa Salomo, son hans, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '«Herren, dykkar Gud, er då med dykk og hev gjeve dykk ro på alle sidor; for han hev gjeve i mi hand deim som fyrr budde i landet, og det er lagt under Herren og hans folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'So vend no dykkar hjarta og hug til å søkja Herren dykkar Gud, og tak til og bygg Herren Guds heilagdom, so de kann få føra Herrens sambandskista og alt det andre som høyrer til Guds heilagdom, inn i det huset som skal byggjast åt Herrens namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Då David var gamall og mett av dagar, gjorde han Salomo, son sin, til konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Og han samla alle hovdingarne i Israel, og prestarne og levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Og levitarne vart talde, ein for ein, dei som var tretti år gamle eller meir, og talet på alle karfolki var åtte og tretti tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '«Av desse,» sagde han, «skal fire og tjuge tusund standa fyre arbeidet i Herrens hus, og seks tusund skal vera formenner og domarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'fire tusund skal vera dørvaktarar, og fire tusund skal lovsyngja Herren til dei spelgognerne som eg hev late gjera til lovsongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Og David skifte deim i skift etter sønerne åt Levi: Gerson, Kehat og Merari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Til gersonitarne høyrde Ladan og Sime’i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Sønerne hans Ladan var Jehiel, hovdingen, Zetam og Joel, tri mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Sønerne hans Sime’i var Selomot og Haziel og Haran, tri; dei var hovdingarne for Ladans-ættgreinerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Og sønerne åt Sime’i var Jahat, Ziza og Je’us og Beria; desse fire var sønerne hans Sime’i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahat var hovdingen, og Ziza var den andre. Men Je’us og Beria hadde ikkje mange born, difor vart dei rekna for ei ættgrein, ein flokk for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Sønerne åt Kahat var Amram, Jishar, Hebron og Uzziel, fire.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Sønerne hans Amram var Aron og Moses. Og Aron vart utskild - han skulde vigjast til å vera høgheilag i all æva, han og sønerne hans, og skulde brenna røykjelse for Herren og tena honom og lysa velsigning i hans namn til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Men sønerne åt Moses, Guds mann, vert rekna til Levi-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Sønerne åt Moses var Gersom og Eliezer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Av Gersoms-sønerne var Sebuel hovding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Og av Eliezer-sønerne var Rehabja hovding. Eliezer hadde ikkje fleire søner; men sønerne hans Rehabja var ovleg mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Av Jishars-sønerne var Selomit hovdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebrons-sønerne var Jerija hovdingen, Amarja, var den andre, Jahaziel, den tridje, og Jekamam, den fjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Av Uzziels-sønerne var Mika hovding, og Jissia den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merari-sønerne var Mahli og Musi. Sønerne hans Mahli var Eleazar og Kis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Då Eleazar døydde, hadde han ingi søner etter seg, men berre døtter; men sønerne åt Kis, frendarne deira, gifte seg med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Musi-sønerne var Mahli og Eder og Jeremot, tri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Dette var Levi-sønerne etter ættgreinene deira, ættarhovdingarne for deim som var mynstra og innskrivne i manntalet, ein for ein, dei som kunde gjera arbeid som høyrde til tenesta i Herrens hus, og var tjuge år gamle og yver det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'For David sagde: «Herren, Israels Gud, hev gjeve folket sitt ro, og hev no bustaden sin i Jerusalem for all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Difor tarv ikkje heller levitarne bera tjeldet meir, og ikkje heller alle arbeidsgognerne som er i huset.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'For etter fråsegni um Davids siste tid vart levitarne rekna frå tjugeårsalderen og uppetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Og dei vart sette med sida åt Arons-sønerne til tenesta i Herrens hus, i det som vedkom tuni og kovarne og rensingi av alt som heilagt var, og arbeidet med tenesta i Guds hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'både skodebrødi og finmjølet til grjonofferet og dei usyrde tunnkakorne og takkorne og det knoda mjølet og med alt rom-mål og lengdemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Og kvar morgon skulde dei standa og lova og prisa Herren, og like eins kvar kveld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Og dei skulde ofra alle brennoffer åt Herren på kviledagar og høgtiderne, so mange som fastsett var, og soleis som det var deim fyresagt, allstødt for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Dei skulde gjera alt arbeidet som trongst ved møtetjeldet, og det som skulde gjerast ved heilagdomen, det som Arons-sønerne, brørne deira, hadde å gjera med gudstenesta i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Og Arons-sønerne var skipa i desse skifti: Sønerne åt Aron var Nadab og Abihu, Eleazar og Itamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Men Nadab og Abihu døydde fyre faren, og dei hadde ingi søner, og berre Eleazar og Itamar vart prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Og David i lag med Sadok av sønerne åt Eleazar og Ahimelek av sønerne åt Itamar, skifte deim etter deira embætte i tenesta deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Dei kom då etter med at det var fleire hovdingar av Eleazars-sønerne enn Itamars-sønerne, og difor skipa dei det so at Eleazars-sønerne fekk sekstan hovdingar for sine ættgreiner, og Itamars-sønerne åtte for sine ættgreiner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Og dei skifte deim med strådraging, båe hovudgreinerne; for heilagdoms-fyrstarne og gudsfyrstarne tok dei både av Eleazars-sønerne og Itamars-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Og Semaja Netanelsson, skrivaren av Levi-ætti, skreiv deim upp medan kongen og hovdingarne og presten Sadok og Ahimelek Abjatarsson og ættarhovdingarne for prestarne og levitarne såg på; dei tok ut ei ættgrein for Eleazar og so til skiftes for Itamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Fyrste luten fall på Jojarib, den andre på Jedaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'den tridje på Harim, den fjorde på Seorim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'den femte på Malkia, den sette på Mijamin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'den sjuande på Hakkos, den åttande på Abia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'den niande på Jesua, den tiande på Sekanja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'den ellevte på Eljasib, den tolvte på Jakim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'den trettande på Huppa, den fjortande på Jesebab,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'den femtande på Bilga, den sekstande på Immer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'den syttande på Hezir, den attande på Happisses,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'den nittande på Petahja, den tjugande på Ezekiel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'den ein og tjugande på Jakin, den tvo og tjugande på Gamul,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'den tri og tjugande på Delaja og den fire og tjugande på Ma’azja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Dette vart den skipnaden som dei skulde gjera tenesta si etter, når dei gjekk inn i Herrens hus, so som det var fyresagt deim gjenom Aron, far deira, etter det som Herren, Israels Gud, hadde sagt honom fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Av dei andre Levi-sønerne høyrde Subael til Amrams-sønerne, og Jehdeja var av Subaels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Av Rehabja-sønerne var Jissia hovdingen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'av jisharitarne var det Selomot, og Jahat av Selomots-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Og benajitar var Jeria, Amarja, den andre, Jahaziel, den tridje, og Jekamam, den fjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Son hans Uzziel var Mika; av sønerne hans Mika var Samur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Jissia var bror åt Mika; av Jissia-sønerne var Zakarja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merari-sønerne var Mahli og Musi, søner åt Ja’azia hans son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Søner hans Merari gjenom Ja’azia, son hans, var både Soham, Zakkur og Ibri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Son åt Mahli var Eleazar; men han hadde ingi søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Av sønerne åt Kis var høyrde Jerahme’el,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'og sønerne åt Musi var Mahli og Eder og Jerimot. Dette var levitsøner etter ættgreinerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Dei og dro strå liksom frendarne deira, Arons-sønerne, medan kong David og Sadok og Ahimelek og ættarhovdingarne for prestarne og levitarne var til stades, hovdingen for ætti likso vel som dei yngste frendarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Og David og herhovdingarne skilde ut til gudstenesta sønerne åt Asaf og Heman og Jedutun, som med profetisk eldhug spela på cithrar og harpor og cymblar, og dette er lista på dei mennerne som skulde hadde hava dette gjeremålet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Av Asafs-sønerne Zakkur og Josef og Netanja og Asarela, Asafs-sønerne med rettleiding av Asaf, som spela med profetisk eldhug etter tilskiping av kongen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Av Jedutun: Jedutuns-sønerne Gedalja, Seri og Jesaja, Hasabja og Mattitja, seks mann, med rettleiding av Jedutun, far deira, som med profetisk eldhug spela takkesongar og lovsongar åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Av Heman: Hemans-sønerne Bukkia, Mattanja, Uzziel, Sebuel og Jerimot, Hananja, Hanani, Eliata, Giddalti, Romamti-Ezer, Josbekasa, Malloti, Hotir, Mahaziot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Alle desse var søner åt Heman, som var kongens sjåar, etter den lovnaden gud hadde gjeve, at han vilde hevja upp hornet hans; difor gav Gud Heman fjortan søner og tri døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Alle desse, kvar med sin far til rettleidar, greidde med songen i Herrens hus, med cymblar, harpor og cithrar, og gjorde soleis tenesta i Guds hus; kongen, Asaf, Jedutun og Heman rettleide dem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Og talet på deim og frendarne deira, som var upplærde i songen for Herren, alle dei kunnige, det tvo hundrad og åtte og åtteti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Og dei drog strå um kva dei skulde gjera, alle saman, den minste som den største, læraren som læresveinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Og den fyrste luten fall på Asaf, det vil segja på Josef; den andre vart Gedalja, han sjølv med brørne og sønerne sine, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'den tridje vart Zakkur, han og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'den fjorde luten fall på Jisri med sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'den femte vart Netanja med sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'den sette vart Bukkia og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'den sjuande vart Jesarela og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'den åttande vart Jesaja og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'den niande vart Mattanja og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'den tiande vart Sime’i og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'den ellevte vart Azarel og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'den tolvte luten fall på Hasabja med sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'den trettande vart Subael og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'den fjortande vart Mattitja og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'den femtande luten fall på Jeremot med sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'den sekstande vart Hananja og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'den syttande vart Josbekasa og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'den attande vart Hanani og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'den nittande vart Malloti og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'den tjugande vart Eliata og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'den ein og tjugande vart Hotir og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'den tvo og tjugande vart Giddalti og sønerne og brørne hans, tolv i talet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'den tri og tjugande vart Mahaziot og sønerne og brørne hans, tolv i talet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'den fire og tjugande vart Romamti-Ezer og sønerne og brørne hans, tolv i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Um skifti som dørvaktarar var skifte i, er å segja: Av korahitarne var Meselemja, son åt Kore, av Asafs-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Og Mesemlja hadde søner: Zakarja var den eldste, Jediael den andre, Zebadja den tridje, Jatniel den fjorde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam den femte, Johanan den sette, Eljoenai den sjuande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Og Obed-Edom hadde søner: Semaja var den eldste, Jozabad den andre, Joah den tridje, Sakar den fjorde, Netanel den femte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel den sette, Issakar den sjuande, Pe’ulletai den åttande; for Gud hadde velsigna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Og Semaja, son hans, fekk og søner, som vart styrarar i ætti si; for dei var duglege menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Sønerne hans Semaja heitte Otni og Refael og Obed, Elzabad og brørne hans, dugande menner, Elihu og Semakja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Alle desse var ætta frå Obed-Edom, dei sjølve og sønerne og brørne deira, dugande og sterke menner i tenesta, - tvo og seksti av Obed-Edom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemja hadde og søner og brør, duglege menner, i alt attan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Og Hosa av Merari-sønerne hadde søner: Simri var fyrstemannen - han var vel ikkje den eldste; men far hans sette honom til hovding -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkia var den andre, Tebalja den tridje, Zakarja den fjorde. Alle sønerne og brørne hans Hosa var trettan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Desse dørvaktar-skifti, det vil segja ættarhovdingarne, vart no sette til vakttenesta i Herrens hus, jamsides med frendarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Og um kvar port drog dei strå, den minste som den største, etter ættgreinene sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Romet ved austporten kom på Selemja; og dei drog strå for Zakarja, son hans, ein vitug rådgjevar, og etter strået vart hans rom i nord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'På Obed-Edom fall romet ved sudporten, soleis at sønerne hans fekk budi på sin part.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'For Suppim og Hosa viste strået på romet i vest ved Salleket-porten, der vegen gjeng uppetter, den eine vaktposten attmed den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Mot aust var det seks levitar, mot nord fire for kvar dag, mot sud fire for kvar dag, og ved budi tvo um gongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Ved Parbar mot vest stod fire attmed vegen, og tvo ved sjølve Parbar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Dette var dørvaktar-skifti av korahitsønerne og av Merari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Og av levitarne hadde Ahia-sønerne tilsyn med skattarne i Guds hus og tok vare på dei ting som var vigde åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Sønerne åt Ladan, det vil segja gersonitsønerne av Ladans-ætti, hovdingarne for gersoniten Ladans ættgreinene var jehielitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Jehielit-sønerne Zetam og Joel, bror hans, hadde tilsyn med skattarne i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Um amramitarne, jisharitarne, hebronitarne og ozzielitarne er det å segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Sebuel, son åt Gersom Mosesson, var øvste tilsynsmannen yver skattarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Og frendarne hans av Eliezers-ætti var Rehabja Eliezersson, og son hans heitte Jesaja, og hans son var Joram, og hans son Zikri, og hans son Selomot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Denne Selomot og brørne hans hadde tilsyn med alt det godset som kong David og like eins ættarhovdingarne, yver- og underhovdingar og herhovdingar hadde vigt åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Frå ufreden og av herfanget hadde dei vigt det til å halda Herrens hus i stand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Og like eins alt det som sjåaren Samuel og Saul Kisson og Abner Nersson og Joab Serujason hadde vigt; kvar og ein som vigde noko, let Selomot og brørne hans taka vare på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Av jisharitarne vart Kenanja og sønerne hans sette til dei verdslege gjeremåli i Israel, til å vera tilsynsmenner og domarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Av hebronitarne vart Hasabja og brørne hans, syttan hundrad menner, sette til stjorn i Israel, i landet vest for Jordan, til alle slags gjeremål åt Herren og til kongen tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Til hebronitarne høyrde Jeria, hovdingen for hebronitarne etter deira ættgreiner og huslydar; i det fyrtiande styringsåret åt Davids vart dei yversedde, og det fanst då dugande folk hjå dei i Jazer i Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Brørne hans, duglege menner, var tvo tusund og sju hundrad hovud for huslydar; deim sette kong David yver rubenitarne, gaditarne og den halve Manasse-ætti, til å greida med alle Guds og kongens målemne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Og dette er Israels-sønerne, etter talet deira, med ættarhovdingarne og med herhovdingar yver tusund og hundrad og tilsynsmennerne deira, som tente kongen i alt som vedkom herflokkarne; dei herflokkarne gjekk inn og gjekk ifrå for til skiftes kvar månad i året, og kvar flokk var fire og tjuge tusund mann sterk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Yver den fyrste skiftet, for den fyrste månaden, stod Jasobam Zabdielsson; og i hans skift var det fire og tjuge tusund mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Han var av Peres-sønerne og var hovding for alle hovudsmennerne den fyrste månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Yver det andre månadsskiftet, stod Dodai, ahohiten; der var og fyrsten Miklot. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Tridje herhovdingen, for den tridje månaden, var Benaja, son åt presten Jojada, yverhovding. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Denne Benaja var ei kjempa millom dei tretti, og hovding for dei tretti. Og i hans skift var Ammizabad, son hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Den fjorde, som gjorde tenesta den fjorde månaden, var Asael, bror åt Joab, og etter honom Zebadja, son hans. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Den femte, for den femte månaden, var Samhut, jizrahiten. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Den sette, for den sette månaden, var Ira Ikkesson, frå Tekoa. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Den sjuande, for den sjuande månaden, var peloniten Heles, av Efraims-sønerne. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Den åttande, for den åttande månaden, var husatiten Sibbekai, som høyrde til zerahitarne. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Den niande, for den niande månaden, var Abiezer frå Anatot, av Benjamins-ætti. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Den tiande, for den tiande månaden, var Maharai frå Netofa, som høyrde til zerahitarne. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Den ellevte, for den ellevte månaden, var Benaja frå Piraton, av Efraims-sønerne. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Den tolvte, for den tolvte månaden, var Heldai frå Netofa, av Otniels-ætti. Og i skiftet hans var fire og tjuge tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Og dette er ættarhovdingarne yver Israel: Jarlen for rubenitarne var Eliezer Zikrison, for simeonitarne Sefatja Ma’akason;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'for Levi Hasabja Kemuelsson, for Arons-ætti Sadok,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'hjå Juda Elihu, ein av David brør, for Issakar Omri Mikaelsson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'for Sebulon Jismaja Obadjason, for Naftali Jerimot Azrielsson');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'for Efraims-sønerne Hosea Azazjason, for den halve Manasse-ætti Joel Pedajason,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'for den halve Manasse-ætti i Gilead Jiddo Zakarjason, for Benjamin Ja’asiel Abnersson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'for Dan Azarel Jerohamson. Dette var ættarhovdingarne i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Men David tok ikkje tal på deim som var yngre enn tjuge år; for Herren hadde sagt at han vilde auka Israel so dei vart mange som stjernorne på himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab Serujason tok til å telja, men fullførde det ikkje; for det kom vreide yver Israel for telgjingi skuld, og talet vart ikkje uppsett på nokor lista i kong Davids krønikebok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Azmavet Adielsson hadde tilsyn med skattarne åt kongen, og Jonatan Uzziason med forrådi på marki, i byarne og bygderne og borgerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Og Ezri Kelubsson såg til med onne-arbeidarane, som dreiv med jordbruket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Sime’i frå Rama vart sett yver vinhagarne, og Zabdi, sifmiten, yver vinforrådi i vinhagarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Ba’al-Hanan frå Gedera hadde tilsyn med oljeplantningarne og fiketrei i låglandet, og Joas med oljeforrådi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'og Sitrai frå Saron såg til med det storfeet som beitte i Saron, og Safat Adlaison med storfeet i dalarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'ismaeliten Obil med kamelarne, Jehdeja frå Meronot med asnorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'og hagariten Jaziz med småfeet. Alle desse var tilsynsmenner yver eigorne åt kong David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Men Jonatan, farbror åt David, var rådgjevar; han var ein vitug og skriftlærd mann. Jehiel Hakmonison var hjå kongssønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitofel var rådgjevaren åt kongen, og Husai, arkiten, var kongens ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Etter Ahitofel kom Jojada Benajason og Abjatar. Og Joab var kongens herhovding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Og David kalla i hop alle Israels hovdingar til Jerusalem, ættarhovdingarne, hovdingarne yver herskifti som tente kongen, og hovudsmennerne yver tusund og yver hundrad, og tilsynsmennerne yver all eiga og buskapen åt kongen og sønerne hans, og dertil hirdmennerne og kjemporne og alle djerve hermenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Og kong David reis upp og sagde: «Høyr på meg, brørne mine, og folket mitt! Eg hadde tenkt meg til å byggja eit hus til kvilestad for Herrens sambandskista og for fotskammelen åt vår Gud, og eg hadde rådt meg byggjevyrke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Men Gud sagde til meg: «Du skal ikkje byggja eit hus for namnet mitt; for du er ein hermann og hev rent ut blod.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Men Herren, Israels Gud, valde like vel meg ut or heile farsætti mi til å vera konge yver Israel i all æva; for Juda valde han ut til å vera fyrste, og or Judas hus min fars hus, og millom sønerne åt far min hadde han hugnad i meg, og gjorde meg til konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Og av alle sønerne mine - for Herren hev gjeve meg mange søner - valde han ut Salomo, son min, til å sitja i Herrens kongsstol yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Og han sagde til meg: «Salomo, son din, er den som skal byggja huset mitt og fyregardarne mine; for honom hev eg kåra ut til son min, og eg skal vera far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Og eg skal grunnfesta kongedømet hans for all tid, i fall han er stød til å halda bodi og loverne mine liksom no.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Og no segjer eg framfor heile Israel, Herrens lyd, og for vår Gud, som høyrer det: «Haldt alle bodi frå Herren, dykkar Gud, og spør etter deim, so de kann få hava dette gode landet og lata det ganga i arv åt borni dykkar til æveleg tid!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Og du Salomo, son min, lær å kjenna far din’s Gud, og å tena honom med heilt hjarta og viljug sjæl! For Herren ransakar alle hjarto og skynar alt det som rører seg i tankarne. Um du søkjer Herren, so let han deg finna honom; men vender du deg frå honom, so støyter han deg frå seg for æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'So sjå deg no fyre; for Herren hev kåra deg ut til å byggja eit hus åt heilagdomen. Ver sterk og tak fat på verket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Og David gav Salomo, son sin, eit bilæte av forhalli og tempelbygnaderne og buderne, yversalarne og innromi og romet åt nådestolen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'og eit bilæte av alt det som leika i hugen hans, av tuni åt Herrens hus, og alle kovarne rundt ikring for skattarne som høyrde Guds hus til, og for dei ting som var vigde åt Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'og fyreskrifter um presteskifti og levitskifti og um all tenesta i Herrens hus, og um alle kjeraldi som skulde brukast ved gudstenesta i Herrens hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'og um gullet med uppgåva på den gullvegti som kvart kjerald til gudstenesta heldt, og um all sylvkjerald med uppgåva på vegti som kvart kjerald til tenesta heldt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Og han gav upp vegti på gull-ljosestakarne med gull-lamporne som til høyrde, serskilt for kvar stake og lampa, og vegti på kvar sylvljosestake med lamporne som til høyrde, etter det kvar stake skulde brukast til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'like eins vegti på gullet til skodebrødsbordi, kvart bord for seg, og sylvet til sylvbordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Og han gav honom fyreskrifter um gaflarne og skålerne og kannorne av skirt gull, og um gullstaupi og sylvstaupi, og gav upp vegti på kvart gullstaup og sylv staup,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'og um røykjelsealtaret av reinsa gull etter vegt, og eit bilæte av vogni, gullkerubarne som breidde ut vengjerne og hylde Herrens sambandskista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '«Um alt dette,» sagde David, «som skal gjerast etter bilæte, hev Herren rettleidt meg i ei skrift frå si hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Og David sagde til Salomo, son sin: «Ver sterk og stød og tak fat på verket; du skal ikkje ræddast og ikkje fæla. For Gud Herren, min Gud, skal vera med deg. Han vil ikkje sleppa deg og slå handi av deg, fyrr det er fullført, alt arbeidet som skal gjerast for tenesta i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Og sjå, her er alle skifti av prestar og levitar, som skal gjera allskyns tenesta i Guds hus. Og til alt som skal gjerast, hev du hjå deg alle slag folk som er viljuge og hev fenge visdom til alle slag arbeid; dessutan er hovdingarne og alt folket reiduge til alt det du segjer deim fyre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Og kong David sagde til heile lyden: «Salomo, son min, den einaste Gud hev valt ut, er ung og kløkk, og arbeidet er stort; for denne borgi er ikkje etla til eit menneskje, men til Gud Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Men det meste eg hev kunna, hev eg, åt huset for min Gud, rådt meg gull til det som skal vera av gull, sylv til det som skal vera av sylv, kopar til det som skal vera av kopar, jarn til det som skal vera av jarn, og tre til det som skal vera av tre, dessutan sjohamsteinar og andre innfellingssteinar, svartblanke og brokute steinar, stutt sagt allskyns dyre steinar og marmorstein i mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Og etter di eg tykkjer um Guds hus, gjev eg dessutan det eg eig av gull og sylv til min Guds hus umfram alt det eg hev rådt meg åt det heilage huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'tri tusund talent gull, Ofir-gull, og sju tusund talent reinsa sylv, so dei kann klæda veggjerne i husi med det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'og gjera alle dei ting som skal vera av gull, og deim som skal vera av sylv, ja, all slags arbeid som kunstmenner kann gjera. Vil då nokon annan no i dag godvilljugt fylla handi si med gåvor åt Herren?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Dei kom då friviljugt, hovdingarne for ættgreinerne og Israels ættarhovdingar, og hovdingarne yver tusund og yver hundrad og formennerne yver kongens arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Og dei gav til arbeidet på Guds hus fem tusund talent og femti tusund dalar gull, ti tusund talent sylv, attan tusund talent kopar og eit hundrad tusund talent jarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Og kvar og ein som hadde dyre steinar i sitt eige, gav deim til skatten i Herrens hus, som gersoniten Jehiel hadde i varveitsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Og folket gledde seg yver at dei gav unøydde; for av heile sitt hjarta kom dei friviljugt med gåvorne sine åt Herren; kong David og gledde seg storom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Og David lova Herren framfor heile lyden; David sagde: «Lova vere du, Herre, du Gud åt far vår Israel, frå æva til æva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Deg, Herre, høyrer stordomen til og velde og æra og bragd og herlegdom, ja, alt som i himmelen og på jordi er; ditt er riket, Herre, og du hev hevja deg upp til eit hovud yver alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Rikdom og æra kjem frå deg, du råder yver alt, og i di hand er kraft og velde; det stend i di hand å gjera alt stort og sterkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'So prisar me deg no, vår Gud, og lover ditt herlege namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'For kven er eg, og kva er folket mitt, at me sjølve skulde evla å gjeva slike gåvor friviljugt? Nei, frå deg kjem alt, og or di hand hev me gjeve deg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'For me er framande for di åsyn, og gjester som alle våre feder; som ein skugge er våre dagar på jordi, og utan von.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Herre, vår Gud, all denne midelen som me hev rådt oss, so me kunde byggja deg eit hus for det heilage namnet ditt - frå di hand er han komen, og ditt er alt i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Og eg veit, min Gud, at du ransakar hjarto og hev hugnad i det som rett er. Med ærlegt hjarta hev eg bore fram alle desse gåvorne sjølvviljugt, og no hev eg set med gleda korleis folket ditt, som her stend, hev sjølvviljugt bore fram åt deg gåvorne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herre, Abrahams, Isaks og Israels Gud, fedreguden vår, lat hugen og tankarne hjå folket ditt allstødt vera viljuge til slike ting, og vend hjarto deira til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Og gjev Salomo, son min, eit heilt hjarta til å fylja bodi, loverne og fyreskrifterne dine, og gjera alt dette, og byggja den borgi som eg hev gjort fyrebuingar til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'So sagde David til heile lyden: «Lova Herren, dykkar Gud!» Og heile lyden lova Herren, fedreguden sin, og kasta seg ned å gruve for Herren og for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Og andre dagen slagta dei slagtoffer og ofra brennoffer åt Herren: tusund uksar, tusund verar og tusund lamb med dei drykkofferi som til høyrde, og ei stor mengd med slagtoffer for heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Og dei åt og drakk for Herrens åsyn på den dagen med stor gleda. Og dei gjorde Salomo, son åt David, andre gongen til konge; dei salva honom til ein fyrste for Herren, og Sadok til prest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Og Salomo konge sat då konge i Herrens kongsstol etter David, far sin, og var lukkeleg, og heile Israel lydde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Og alle hovdingarne og kjemporne, og dessutan alle sønerne åt kong David gav seg under kong Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Og Herren gjorde Salomo ovleg stor for augo åt heile Israel og gav honom ein kongeleg herlegdom som ingen konge i Israel fyre honom hadde havt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Men David, son åt Isai, hadde rådt yver heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Den tidi han var konge yver Israel, var fyrti år; i Hebron styrde han i sju år, og i Jerusalem styrde han i tri og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Og han døydde i ein god alderdom, mett av dagar og rikdom og æra. Og Salomo, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Og soga um kong David frå upphavet til enden, ho er uppskrivi i krønikeboki åt sjåaren Samuel, i krønikeboki åt profeten Natan og i krønikeboki åt sjåaren Gad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Der er og fortalt um heile styringi hans, og um storverki hans, og den lagnad som kom yver honom og Israel og alle andre land og rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomo, son åt David, vart grunnfest i kongedømet sitt, og Herren hans Gud, var med honom, og gjorde honom overlag stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Då let Salomo bod fara yver heile Israel, til hovdingarne yver tusund og yver hundrad, til domarane og til alle hovdingarne i Israel, ættarhovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Og Salomo og heile lyden drog til offerhaugen i Gibeon. For der stod Guds møtetjeld, det som Moses, Herrens tenar, hadde gjort i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Men Guds kista hadde David flutt upp ifrå Kirjat-Jearim til den staden han hadde laga til åt henne, for han hadde late reisa eit tjeld åt henne i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Og koparaltaret som Besalel hadde gjort, son åt Uri, son åt Hur, det stod der framanfor Herrens hus, og der søkte Salomo og lyden honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Der ofra Salomo for Herrens åsyn på koparaltaret som høyrde til møtetjeldet, og han ofra tusund brennoffer der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'I den same natti openberra Gud seg for Salomo og sagde til honom: «Seg kva du vil eg skal gjeva deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Salomo svara Gud: «Du hev vist stor miskunn imot David, far min, og du hev gjort meg til konge i hans stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'So lat då, Herre Gud, ordet ditt til David, far min sannast! for du hev gjort meg til konge yver eit folk som er mangment som dusti på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Gjev meg då visdom og kunnskap, so eg kann vera leidar og førar for folket! for kven evlar døma dette store folket ditt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Då sagde Gud til Salomo: «For di hugen din hev stade til dette, og du ikkje hev bede um rikdom, skattar, æra, eller at uvenerne dine skal døy, og heller ikkje hev bede um eit langt liv, men um visdom og kunnskap til å døma folket mitt, som eg hev gjort deg til konge yver,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'so skal du få den visdom og kunnskap, men eg gjev deg rikdom og skattar og æra og, so at ingen konge fyre deg hev ått maken, og ingen skal heller eiga maken etter deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Sidan for Salomo frå offerhaugen i Gibeon, frå staden framanfor møtetjeldet, og til Jerusalem, og han var konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Salomo samla krigsvogner og folk, so at han hadde fjortan hundrad vogner og tolv tusund hestfolk, og dei lagde han, sume i vognbyarne og sume hjå seg sjølv i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Kongen gjorde sylvet og gullet i Jerusalem likso vanlegt som stein, og cedertreet likso vanlegt som morberfiketre i låglandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Hestarne sine fekk Salomo frå Egyptarland, med di kjøpmennerne åt kongen kjøpte deim der mot betaling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Dei førde ut ei vogn frå Egyptarland for seks hundrad sylvdalar og ein hest for hundrad og femti. Og ved deira hjelp førde dei ut slike på same måten til alle hetitarkongarne og til syrarkongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Salomo sette seg fyre at han vilde byggja eit hus for Herrens namn og eit hus for sitt kongedøme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Difor tok han ut sytti tusund berarar og åtteti tusund steinhoggarar på fjelli og tri tusund og seks hundrad til å hava tilsyn med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'So sende han dette bodet til Huram, kongen i Tyrus: «Liksom du gjorde med David, far min, då du sende honom cedertre til å byggja seg eit hus som han kunde bu i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Eg skal no til å byggja eit hus for namnet åt Herren, min Gud, og vil vigja det til honom soleis at ein der kann kveikja finangande røykjelse, leggja fram dei daglege skodebrødi og ofra brennoffer morgon og kveld, på kviledagarne, nymånedagarne og høgtiderne åt Herren vår Gud; for det er skyldnaden åt Israel til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Det huset som eg vil byggja, skal vera stort; for vår Gud er større enn alle gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Kven magtast å byggja honom eit hus? For jamvel himlarne og himle-himlarne kann ikkje røma honom. Og kven er eg, at eg skulde byggja honom eit hus, um det ikkje vore for å kveikja offereld for hans åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'So send meg då ein kunnig mann som er hag til å arbeida i gull og sylv og kopar og jarn og i purpurraudt og karmesinraudt og purpurblått garn, og som kann med utskurd, saman med dei kunnige folk som eg hev her i Judalandet og Jerusalem, og som far min hev tinga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Og send meg cedertre, cypresstre og algummimtre frå Libanon; for eg veit at folki dine er dugelege til å hogga tre på Libanon; og folki mine skal vera med dine folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Lat meg få mykje trevyrke; for huset som eg vil byggja, skal vera stort og underfullt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Til upphelde for dei timberhoggarane som høgg trei, og som er dine folk, vil eg gjeva seksti tusund tunnor kveite, seksti tusund tunnor bygg, tjuge tusund anker vin og tjuge tusund anker olje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Huram, kongen i Tyrus, svara i eit brev som han sende Salomo: «For di Herren elskar folket sitt, hev han sett deg til konge yver deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Og Huram sagde framleides: «Lova vere Herren, Israels Gud, som hev skapt himmelen og jordi, han som hev gjeve kong David ein vis son, som hev vit og skyn til å byggja eit hus for Herren og eit hus for sitt kongedøme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'No sender eg deg ein vis mann med godt skyn, Huram, far min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Han er son åt ei kvinna av Dans-ætti, men far hans var ein mann frå Tyrus; han er hæv til å arbeida i gull og sylv, i kopar og jarn og stein og tre, i purpurraudt og purpurblått og kvitt og karmesinraudt garn, til å skjera allslag utskurd, og skapa alle dei kunstverk som han fær til fyreloga, saman med kunstnarane dine og kunstnarane åt min herre David, far din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Difor kann min herre senda trælarne sine kveiten og bygget, oljen og vinen som du hev tala um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'So vil me hogga so mange tre på Libanon som dei hev bruk for, og senda deim på timberflotar yver havet til Jafo; so fær du sjølv henta deim upp til Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Salomo let då rekna upp alle dei framande mennerne som budde i Israels land, etter den teljingi som David, far hans, hadde gjort; og dei kom til at det var hundrad og tri og femti tusund og seks hundrad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Av deim gjorde han sytti tusund til berarar, åtteti tusund til steinhoggarar på fjelli og tri tusund og seks hundrad til formenner som skulde halda folket i arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'So tok Salomo til å byggja Herrens hus i Jerusalem, på Moriafjellet der Herren hadde openberra seg for David, far hans, på den staden som David hadde laga til på treskjaarvollen åt jebusiten Ornan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Han tok til å byggja på den andre dagen i den andre månaden i sitt fjorde styringsår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Då no Salomo skulde byggja Guds hus, lagde han grunnen soleis: Lengdi var seksti alner etter det gamle målet, og breiddi tjuge alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Forhalli som låg framanfor langhuset, framanfor breidsida, var tjuge alner lang og hundrad og tjuge alner høg, og innvendes klædde han henne med skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Hovudromet klædde han med cypresstre, og han klædde det dessutan med egte gull og prydde det med palmor og kransar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Han klædde romet med dyre steinar til prydnad, og gullet var kome frå Parvajim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Og han klædde huset, bjelkarne, dørstokkarne og veggjerne og dørerne med gull og skar ut kerubar i veggjerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Romet for det høgheilage bygde han soleis at lengdi etter breidsida åt hovudromet var tjuge alner, og breiddi tjuge alner, og han klædde det med egte gull, som vog femtan hundrad våger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Vegti på spikrarne var seksti lodd i gull; dei øvre romi klædde han med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'I det høgheilage romet gjorde han tvo kerubar i bilætskurd, og deim klædde han med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Vengjerne på kerubarne var tjuge alner i lengd; den eine vengen på den eine keruben var fem alner lang og tok veggen i romet, og den andre vengen var og fem alner lang og tok i vengen på den andre keruben;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'og den eine vengen på den andre keruben var fem alner lang og tok veggen i romet, og den andre vengen var og fem alner lang og nådde til vengen på den fyrste keruben.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Vengjerne på desse kerubarne var tjuge alner i si fulle lengd; og dei stod upprette og snudde andliti innetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Og han gjorde forhenget purpurblått og purpurraudt og karmesinraudt og kvitt garn, og han prydde det med kerubar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Og han gjorde tvo sulor til å standa framanfor huset. Dei var fem og tretti alner høge, og hovudet på deim var fem alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Dessutan gjorde han hengjekransar til koren og sette deim på det øvste av sulorne; og på hjengjekransarne sette han hundrad granateple.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Sulorne sette han framanfor templet, ei til høgre og ei til vinstre; den som var høgre, kalla han Jakin, den vinstre Boaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Og han gjorde eit altar av kopar, tjuge alner langt, tjuge alner breidt og ti alner høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Og han gjorde havet i støypt arbeid; det var ti alner frå den eine kanten til den andre, rundt alt ikring, fem alner høgt, og ei mælesnor på tretti alner gjekk ikring det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Under kanten var det sett bilæte av uksar rundt ikring det; det var ti på kvar aln, det var tvo rader av deim rundt heile havet, og dei var støypte saman med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Det stod på tolv uksar; av deim snudde tri mot nord, tri mot vest, tri mot sud, og tri mot aust, soleis at havet var ovanpå deim, og dei snudde bakkropparne innetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Det var ei handbreidd tjukt, og kanten var som på eit staup og laga som ein liljeblom. Det tok tri tusund anker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Framleides gjorde han ti tvåttebaljor, og av deim sette han fem på høgre og fem på vinstre sida; i deim skylde dei det som høyrde til brennofferi, men havet bruka prestarne til tvætte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Og han gjorde ti ljosestakar av gull i samhøve med det som var fyreskrive, og sette deim i tempelbygnaden, fem på høgre og fem på vinstre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Og han gjorde ti bord, som han sette i templet, fem på høgre og fem på vinstre sida. Han gjorde og hundrad skåler av gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Framleides gjorde han prestetunet og den store garden og dører til garden, og dørerne klædde han med kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Havet sette han upp på høgre sida mot sudaust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Huram gjorde oskefati og skuflerne og skålerne, og han fullførde det arbeidet som han gjerde for kong Salomo i Guds hus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'tvo sulor med dei tvo kulorne og hovudi ovanpå deim, dei tvo neti til å klæda dei tvo kulerunde hovudi på sulorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'dei fire hundrad granatepli til dei tvo neti, tvo rader med granateple for kvart net til å klæda dei kulerunde hovudi på sulorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'og fotstykki gjorde han, og baljorne gjorde han på fotstykki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'havet, eitt stykke, med dei tolv uksarne under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Oskefati, skuflerne og gaflarne og alt det som høyrde til, gjorde Huram, far hans, til Herrens hus, for kong Salomo, dei var av blank kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Kongen støypte deim nedi Jordan-kverven, i støypeformar av jord millom Sukkot og Seredata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Alle desse tingi let Salomo gjera i stor mengd, for det vart ikkje røkt etter kva koparen vog.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Framleides gjorde Salomo alle dei tingi som skulde vera i Guds hus: gullaltaret, bordi som skodebrødi var på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'ljosestakarne med lamporne, som skulde kveikjast på fyreskriven måte, framfyre koren, av skirt gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'med blomarne og lamporne og ljossakserne av gull, og det av det aller beste gullet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'knivarne og skålarne og kannorne og glodpannorne av skirt gull, og med umsyn til inngangarne til huset, so var dei indre dørerne til det høgheilage romet, og dørerne i huset, som førde til tempelsalen, av gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Då no heile det arbeidet var ferdigt som Salomo let gjera åt Herrens hus, då førde Salomo inn dit heilaggåvorne åt David, far sin: sylvet og gullet og alle gognerne lagde han ned i skattkammeri i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'So kalla Salomo saman styresmennerne i Israel og alle ættarhovdingarne, formennerne for ættgreinerne åt Israels-sønerne, til Jerusalem for å føra Herrens sambandskista upp ifrå Davidsbyen, det er Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Då samla alle Israels-mennerne seg hjå kongen i helgi; det er den sjuande månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Og alle styresmennerne i Israel kom, og levitarne bar kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Og dei førde kista og møtetjeldet dit upp og alle dei heilaggognerne som var i tjeldet, og prestarne og levitarne bar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Og kong Salomo og heile Israels-lyden, som hadde samla seg hjå honom, dei stod framfyre kista og ofra småfe og storfe, so mange at dei ikkje kunde reknast eller teljast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'So førde prestarne Herrens sambandskista inn på staden sin i koren i huset, i det høgheilage, under vengjerne åt kerubarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Og kerubarne breidde ut vengjerne sine yver den staden der kista stod, og soleis tekte kerubarne yver kista og berestengerne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Berestengerne var so lange at ein såg stongendarne som stod fram frå kista, framanfor koren; men ein såg deim ikkje utanfor. Og dei vart verande der til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Det fanst ikkje anna i kista enn dei tvo tavlorne som Moses hadde lagt ned i henne ved Horeb, då Herren gjorde samband med Israels-borni då dei drog ut or Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Då prestarne so gjekk ut or heilagdomen, for alle dei prestarne som var der, hadde vigt seg, so det var ikkje naudsynlegt å halda seg etter skifti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'og alle dei levitiske songararne, både Asaf, Heman og Jedutun og sønerne og brørne deira, stod i kvite linklæde med cymblar, harpor og cithrar austanfor altaret, og hjå deim hundrad og tjuge prestar som bles i lurar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'og i same augneblinken då lurblåsarane og songarane sette i alle som ein med å lova og prisa Herren, og dei let lurarne og cymblarne og spelgognerne klinga, og lova Herren for han er god, og hans miskunn varer æveleg - då vart huset, Herrens hus, fyllt av ei sky,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'so prestarne kunde ikkje standa og gjera tenesta for skuld skyi; for Herrens herlegdom fyllte Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Då sagde Salomo: «Herren hev sagt at han vil bu i dimma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Men eg hev bygt eit hus til bustad åt deg, og ein stad der du kann dvelja ævelegt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'So snudde kongen seg og velsigna heile Israels-lyden, medan heile Israels-lyden stod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Og han sagde: «Lova vere Herren, Israels Gud, som hev fullenda det med handi si som hans munn tala til David, far min, den gongen han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '«Frå den tid då eg henta folket mitt ut or Egyptarland, hev eg ikkje valt ut nokon by av Israels ætter til å byggja eit hus i som namnet mitt kunde bu i, og eg hev ikkje kåra nokon mann til å vera styrar yver Israel, folket mitt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'men no hev eg valt Jerusalem til at namnet mitt kann bu der, og eg hev kåra David til å styra yver Israel, folket mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Og David, far min, var meint på å byggja eit hus for namnet åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Men Herren sagde til David, far min: «Når du hev vore meint å byggja eit hus for mitt namn, då hev du gjort vel med at du hev slikt i tanken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'like vel skal ikkje du byggja huset, men son din, som gjeng ut or lenderne dine, han skal byggja huset for mitt namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'No hev Herren sett i verk det ordet som han tala; og eg er komen i far min’s stad, og hev sett meg på Israels kongsstol, soleis som Herren hev sagt det, og eg hev bygt huset for namnet åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Og der hev eg sett den kista som gøymer Herrens samband er i, det som han gjorde med Israels-borni.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'So stelte han fram for Herrens altar midt for heile Israels-lyden og breidde ut henderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'For Salomo hadde gjort ein tram av kopar, fem alner lang, fem alner breid og tri alner høg, og hadde sett honom midt i garden; på den stod han; og han fall på kne framfyre heile Israels-lyden og breidde ut henderne mot himmelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'og sagde: «Herre, Israels Gud, det finst ingen Gud som du i himmelen eller på jordi, du som held uppe sambandet og nåden mot tenararne dine når dei ferdast for di åsyn med heile sitt hjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'du som hev halde det du lova tenaren din, David, far min, og som hev fullenda med handi det du tala med munnen, som det syner seg i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'So haldt no og, Herre, Israels Gud, det som du lova tenaren din, David, far min, då du sagde: «Aldri skal den tid koma at det ikkje sit ein mann av di ætt på Israels kongsstol for mi åsyn, når berre sønerne dine vil taka på vegen sin og ferdast i mi lov, liksom du hev ferdast for mi åsyn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'So lat no, Herre, Israels Gud, det ordet sannast som du hev tala til tenaren din, David!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Men kann då Gud i røyndi bu hjå menneski på jordi? Sjå himlarne, ja himle-himlarne kann ikkje røma deg, kor mykje mindre då dette huset som eg hev bygt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Men vend deg like vel til bøni åt tenaren din, og hans påkalling, Herre, min Gud, so du høyrer på det ropet og den bøni som tenaren din bed for di åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'og let augo dine vera opne mot dette huset dag og natt, mot den staden der du hev lova at namnet ditt skal bu, so du høyrer på den bøni som tenaren din vender mot denne staden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'og høyr på den påkalling som tenaren din og Israel, folket ditt, vender imot denne staden; høyr ifrå den staden der du bur, frå himmelen, høyr og tilgjev!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Forsyndar einkvar seg mot næsten sin, og dei legg ein eid på honom, so ein let honom sverja, og han kjem inn og sver framfyre altaret ditt i dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'so må du høyra frå himmelen og setja i verk og døma imillom tenararne dine, med di du gjev den skuldige attergjeld, og let honom lida for si åtferd, og frikjenner den rettferdige og let honom få etter si rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Og um folket ditt, Israel, fær usiger mot fienden for di dei syndar imot deg, og dei so vender um og vedkjennest ditt namn, og bed og påkallar for di åsyn i dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'so må du høyra det frå himmelen og tilgjeva Israel, folket ditt, den syndi dei gjorde, og føra deim heim att til det landet som du hev gjeve deim og federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Når himmelen let seg att, og regnet ikkje kjem, for di dei syndar imot deg, og dei so snur seg imot denne staden med bøn, og dei vedkjennest ditt namn og vender um frå syndi si av di du audmykjer deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'so må du høyra det frå himmelen og tilgjeva tenararne dine og Israel, folket ditt, syndi deira, for du lærer deim den gode vegen dei skal ganga på, og du må gjeva regn yver landet ditt, som du hev gjeve folket ditt til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Når det kjem uår i landet, når det kjem farsott, når det kjem moldaks og rust, eller det kjem engspettor og åmor, eller fiendarne deira trengjer deim i det landet der byarne deira er, eller kva for ei plåga eller sjukdom det er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'kvar gong det då stig upp ei bøn eller audmjuk påkalling frå noko menneskje eller frå heile ditt folk Israel, med di kvar og ein kjenner si plåga og pina og retter ut henderne sine mot dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'so må du høyra frå himmelen, den staden der du bur, og tilgjeva, med di du gjev kvar mann lika for all hans ferd, av di du kjenner hjarta hans - for einast du kjenner mannehjarta -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'so dei må ottast deg og fylgja dine vegar all den tid dei liver på den jordi som du hev gjeve federne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Jamvel den framande, som ikkje høyrer til Israel, folket ditt, men kjem frå eit land langt burte, for ditt store namn, di sterke hand og din strake arm skuld, når dei kjem og vender bønerne sine mot dette huset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'då må du høyra frå himmelen, frå den staden der du bur, og gjera alt som den framande ropar til deg um, so alle folk på jordi må læra å kjenna namnet ditt og ottast deg, liksom Israel, folket ditt, og skyna at dette huset som eg hev bygt, er uppkalla etter ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Når folket ditt fer ut i herferd mot fiendarne sine, på den vegen som du sender deim, og dei so bed til deg med andlitet imot den byen som du hev valt ut, og det huset eg hev bygt åt namnet ditt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'då må du frå himmelen høyra bøni og påkallingi deira, og hjelpa deim til retten sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Og når dei syndar mot deg - for det finst ikkje noko menneskje som ikkje syndar - og du harmast på deim og let fienden få magt yver deim, so han fangar deim og fører deim burt til eit land langt av leid eller nær ved,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'og dei so tenkjer seg um i det landet der dei er fangar, og vender um og bed deg um nåde i det landet der dei er i utlægdi si, og sannar: «Me hev synda, me hev gjort ille og vore ugudlege,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'og dei vender um til deg med heile sitt hjarta og all si sjæl i det landet dei er burtførde til og fangar i, og dei bed med di deg snur seg imot landet sitt, som du hev gjeve federne deira, imot den byen som du hev valt ut, og det huset eg hev bygt for namnet ditt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'so må du høyra på bøni og påkallingi deira frå himmelen der du bur, og hjelpa deim til sin rett og tilgjeva folket ditt det som det hev synda imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'So vere då, min Gud, augo dine opne, og øyro dine agte på bøni på denne staden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'So reis deg då, Herre Gud, og kom til kvilestaden din, du med di velduge kista! Lat prestarne dine, Herre Gud, klæda seg i frelsa, og dine gudlege gleda yver det gode!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herre Gud, vis ikkje ifrå deg åsyni åt den du hev salva, kom i hug nåden mot David, tenaren din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Då Salomo hadde slutta bøni si, for det eld ned frå himmelen og åt upp brennofferet og slagtofferi, og Herrens herlegdom fyllte huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Prestane kunde ikkje ganga inn i Herrens hus, for di Herrens herlegdom fyllte Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Og då alle Israels-borni såg korleis elden for ned og Herrens herlegdom kom yver huset, då kasta dei seg på kne i den steinlagde garden med andlitet mot jordi og tilbad og lova Herren, for han er god, og hans miskunn varer æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Og kongen og heile folket og ofra slagtoffer for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Og kong Salomo ofra tvo og tjuge tusund stykke storfe og hundrad og tjuge tusund stykke småfe til slagtoffer, og soleis vigde kongen og heile folket Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Og prestarne stod på sine postar, og levitarne stod med Herrens spelgogner, som kong David hadde late gjera til å lova Herren for di hans miskunn varer æveleg, og dei førde fram Davids lovprisning, medan prestarne bles i lurarne midt imot deim, og heile Israel stod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Og Salomo vigde den midtre luten av tunet framfyre Herrens hus, for di han laut ofra brennoffer og feittstykki av takkofferi der; for koparaltaret som Salomo hadde gjort, kunde ikkje røma brennofferi, grjonofferi og feittstykki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'På den tid høgtida Salomo helgi i sju dagar saman med heile Israel; det var ein ovstor møtelyd, like frå den staden der vegen gjeng til Hamat og til Egyptarlands-bekken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Og på den åttande dagen heldt dei ei stor samlingshøgtid; for dei høgtida altarvigsla i sju dagar og helgi i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Og på den tri og tjugande dagen i den sjuande månaden let han folket fara heim, glade og velnøgde yver alt det gode som Herren hadde gjort mot David, tenaren sin, og imot Salomo og imot Israel, folket sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'No var Salomo ferdig med å byggja Herrens hus og kongshuset; og alt det han hadde sett seg fyre at han vilde gjera med Herrens hus og sitt hus, det førde han til endes godt og vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Då synte Herren seg for Salomo um natti og sagde til honom: «Eg hev høyrt bøni di og valt meg denne staden til offerstad for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Um eg let att himmelen, so regnet ikkje kjem, eller um eg byd engsprettorne å øyda landet, eller um eg sender farsott imot folket mitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'og folket mitt, som er uppkalla etter namnet mitt, då bøygjer seg og bed og søkjer mi åsyn og vender um frå si vonde ferd, då vil eg høyra frå himmelen og tilgjeva syndi deira og lækja landet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'No skal augo mine vera opne og øyro mine agta på bøni på denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'No hev eg valt ut og helga dette huset til at namnet mitt skal bu der til æveleg tid, og augo mine og hjarta mitt skal vera der alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Um du no ferdast for mi åsyn soleis som David, far din, ferdast, so du gjer alt det som eg hev bode deg, og held lovorne og rettarne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'so vil eg halde uppe kongsstolen din, soleis som eg hev lova David, far din det, då eg sagde: «Aldri skal det vanta deg ein mann til å råda yver Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Men dersom de snur meg ryggen og svik loverne og bodi mine, som eg hev lagt fram for dykk, og gjeng av stad og dyrkar framande gudar og bed til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'då vil eg jaga dykk burt ifrå landet mitt, som eg hev gjeve dykk, og dette huset, som eg hev helga til mitt namn, det vil eg føykja burt ifrå mi åsyn og gjera det til eit ordtøke og ei spott millom alle folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Og yver dette huset, som var so høgreist, skal alle verta forfærde som gjeng framum det, når dei segjer: «Kvifor hev Herren fare soleis åt med dette landet og dette huset?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'då skal dei svara: «For di dei vende seg ifrå Herren, sin fedregud, som førde deim ut or Egyptarland, og heldt seg til andre gudar, og bad til deim og tente deim. Difor hev Herren late alt dette vonde koma yver deim.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Då no dei tjuge åri var ute som Salomo hadde bygt på Herrens hus og sitt hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'bygde Salomo upp dei byarne som Huram hadde late frå seg til honom, og let Israels-sønerne busetja seg i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'So drog Salomo til Hamat-Soba og lagde det under sitt velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Han bygde Tadmor og, i øydemarki, og alle dei forrådsbyarne som han bygde i Hamat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Sameleis bygde han Øvre Bet-Horon og Nedre Bet-Horon til festningar med murar, portar og portbommar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'og Ba’alat og forrådsbyarne som Salomo hadde, alle vognbyarne og hestbyarne og alt det andre som Salomo hadde hug til å byggja i Jerusalem, på Libanon og i heile sitt rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Alt det folket som fanst att av hetitarne, amoritarne, perizitarne, hevitarne og jebusitarne, som ikkje var av Israels-folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'av sønerne åt deim som hadde vorte att etter deim i landet, av di Israels-sønerne ikkje hadde gjort ende på deim, av deim var baud Salomo ut til pliktarbeid, og soleis hev det vore til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Men av Israels-sønerne gjorde Salomo ingen til arbeidstrælar, men dei vart herfolk, hovdingar for kjemporne hans og hovdingar yver stridsvognerne og hestfolket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Av arbeidsfutar hadde kong Salomo tvo hundrad og femti, som rådde yver folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Dotter åt Farao førde kong Salomo frå Davidsbyen til det huset han hadde bygt åt henne; for han sagde: «Ingi kvinna må bu i huset åt David, Israels konge; for desse staderne er heilage, for dit hev Herrens kista kome.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Den gongen ofra Salomo brennoffer til Herren på Herrens altar, som han hadde bygt framfyre forhalli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Kvar dag ofra han dei offer som kravdest på den dagen etter bodet åt Moses, på kviledagarne, nymånedagarne og høgtiderne tri gonger for året: søtebrødhelgi, sjuvikehelgi og lauvhyttehelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Og etter fyresegni åt David, far sin, sette han prestskifti til sine tenestor, og levitarne til sine tenestor, til å lovsyngja og ganga prestarne til handa etter som det turvest for kvar dag, og sameleis dørvaktarflokkarne kvar ved sine portar; for soleis hadde gudsmannen David bode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Og ikkje i nokon måte veik dei ifrå det som kongen hadde bode um frå prestarne og levitarne eller skattkamri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Soleis vart det utført heile Salomos verk, fyrst til den dagen grunnvollen vart lagd til Herrens hus, og sidan til det var fullført. Og so var då Herrens hus ferdigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Den gongen drog Salomo til Esjon-Geber og til Elot ved havstrandi i Edomlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Og Huram sende skip og sjøvant mannskap til honom med folki sine, dei siglde til Ofir saman med folki åt Salomo, og derifrå henta dei elleve hundrad våger gull, som dei førde til kong Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Då dronningi i Saba høyrde gjetordet um Salomo, drog ho til honom i Jerusalem og vilde røyna honom med djupe gåtor. Ho kom med eit ovstort fylgje, med kamelar som var klyvja med kryddor og gull i store mengder og glimesteinar. Og då ho var komi til Salomo, lagde ho fram for honom alt det ho hadde på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Men Salomo gav henne svar på alle spurningarne hennar, og det var ingenting dult for honom, som han ikkje kunde svare på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Då dronningi frå Saba såg kor vis Salomo var, og huset som han hadde bygt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'og retterne på bordet hans, korleis hirdmennerne hans sat der, og korleis tenarane hans varta upp og var klædde, skjenkjarsveinarne hans og deira klæde, og den uppgangen som han hadde til Herrens hus, vart ho reint ifrå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Og ho sagde til kongen: «So var det då sant det som eg høyrde i landet mitt um deg og visdomen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Eg kunde ikkje tru det dei sagde fyrr eg kom og fekk sjå det med eigne augo; og so er det endå ikkje helvti av all visdomen din som de hev fortalt meg um; du er endå større enn det gjetordet eg hev høyrt um deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Sæle er mennerne dine, sæle er desse tenarane dine, som stødt fær standa framfyre deg og høyra visdomen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Lova vere Herren, din Gud, som hadde hugnad i deg og sette deg på sin kongsstol til konge for Herren, din Gud! For di din Gud elskar Israel, og vil halda det ved magt æveleg, difor hev han sett deg til konge yver deim til å gjera rett og rettferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'So gav ho kongen tri hundrad våger gull og kryddor i store mengder og glimesteinar; og aldri hev det funnest slike kryddor som dei dronningi frå Saba gav Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Dessutan kom folki åt Huram og folki åt Salomo, som henta gull frå Ofir, med algummimtre og glimesteinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Og av algummimtreet let kongen gjera tropper til Herrens hus og til huset åt kongen og cithrar og harpor til songarar; og makan til det hadde dei aldri fyrr set i Judalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Og kong Salomo gav dronningi frå Saba alt ho hadde hug på og bad um, umfram gåvor for det som ho gav til kongen. Sidan snudde ho og drog heim att til landet sitt, ho og tenarane hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Vegti på det gullet som kom til Salomo på eitt år, var sekstan hundrad og fem og seksti våger gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'og då var det ikkje medrekna det som kjøpmennerne og kræmarane førde inn, og det som kom frå alle kongarne i Arabia og frå jarlarne i landet, som førde gull og sylv til Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Kong Salomo let gjera tvo hundrad store skjoldar av uthamra gull - til kvar skjold gjekk det seks hundrad lodd uthamra gull -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'og tri hundrad små skjoldar av uthamra gull, og til kvar skjold gjekk det med tri hundrad lodd gull; og kongen sette deim upp i Libanonskoghuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Dessutan let kongen gjera ein stor kongsstol av filsbein og klædde honom med skirt gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Kongsstolen hadde seks stig og ein fotskammel av gull, som var feste til kongsstolen; på båe sidorne åt sætet var det armstyd, og på kvar side åt deim stod det tvo løvor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Det stod og tolv løvor på båe sidorne på dei seks stigi. Det var ikkje laga maken i noko anna rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Alle drykkjestaupi åt kong Salomo var av gull, og alle gognerne i Libanonskoghuset var av skirt gull; sylv rekna dei slett ikkje for noko i kong Salomos dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'For kongen hadde skip som siglde til Tarsis saman med folki åt Huram; ein gong tridje kvart år kom Tarsis-skipi og førde gull og sylv og filsbein og apor og påfuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Kong Salomo vart større enn alle andre kongar på jordi i rikdom og visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Og alle kongarne på jordi kom og vilde sjå honom og høyra visdomen hans, som Gud hadde lagt i hjarta hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Og kvar av deim hadde med seg ei gåva; det var ymse ting av sylv eller gull, klæde, våpn, kryddor, hestar, muldyr, år etter år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomo hadde fire tusund heste-par og stridsvogner og tolv tusund hestfolk, og deim lagde han, sume i vognbyarne og sume hjå seg sjølv i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Han rådde yver alle kongarne frå Eufratelvi til Filistarland og egyptargrensa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Kongen gjorde sylvet so vanlegt i Jerusalem som stein, og cedertre som morberfiketrei i låglandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Hestar førde dei til Salomo frå Egyptarland og frå alle landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Det som elles er å fortelja um Salomo frå fyrst til sist, det er uppskrive i profeten Natans krønika, og i spådomen åt siloniten Ahia og i syni åt sjåaren Jedi um Jeroboam Nebatsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomo var konge i Jerusalem yver heile Israel i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'So lagde Salomo seg til kvile hjå federne sine og vart gravlagd i far sin, Davids, by. Og Rehabeam, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam for til Sikem, for heile Israel var kome til Sikem og vilde taka honom til konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Men då Jeroboam Nebatsson frette det - han var i Egyptarland og hadde rømt dit for kong Salomo - då snudde han heim att frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Då sende dei bod og kalla honom; og Jeroboam og heile Israel kom. Og dei sagde til Rehabeam:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '«Far lagde på oss eit hardt ok; men vil no du letta på det harde strævet og det tunge oket som far din lagde på oss, so skal me tena deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Han svara deim: «Gakk burt og bia tri dagar, og kom so til meg att!» Og folket gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Då rådførte kong Rehabeam seg med dei gamle, som hadde vore i tenesta hjå Salomo, far hans, medan han livde, og spurde deim: «Kva svar råder de til å gjeva dette folket?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Dei svara honom: «Vil du vera venleg mot dette folket i dag og syna deg nådig imot deim og gjeva deim eit venlegt svar, då vil dei vera dine tenarar for alle tider.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Men han brydde seg ikkje um den rådi som dei gamle gav honom, men rådførde seg med dei unge som var uppvaksne i lag med honom og stod i hans tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Han sagde til deim: «Kva råder de meg til å svara dette folket, som hev tala til meg og sagt: «Lat det oket som far din hev lagt på oss verta lettare?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Dei unge kararne som var uppvaksne i lag med honom, svara honom då og sagde: «So skal du segja til dette folket som hev tala til deg og sagt: «Far lagde eit tung ok på oss, men gjer no du det lettare for oss!» - so skal du segja til deim: «Litlefingeren min er tjukkare enn mjødmarne åt far min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Hev difor far min lagt eit tungt ok på dykk, so skal eg gjera oket dykkar endå tyngre; hev far min tukta dykk med svipor, so skal eg tukta dykk med skorpionar!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'So kom Jeroboam med heile folket til Rehabeam tridje dagen, so som kongen hadde sagt: «Kom til meg att tridje dagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Då gav kongen folket eit hardt svar, for han brydde seg ikkje um den rådi dei gamle hadde gjeve honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'etter rådi åt dei unge kararne sagde han til deim: «Hev far min lagt eit tungt åk på dykk, so skal eg gjera det endå tyngre; hev far min tukta dykk med svipor, so skal eg tukta dykk med skorpionar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Kongen høyrde soleis ikkje på folket, for di Gud laga det soleis, so Herrens ord skulde sannast som han hadde tala til Jeroboam Nebatsson ved siloniten Ahia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Då no heile Israel såg at kongen ikkje høyrde på deim, gav folket kongen dette svaret: «Kva deil hev me i David? Ingen lut i Isaisonen! Heim att, Israel, kvar til si hytta! Sjå no sjølv til huset ditt, David!» So gjekk heile Israel kvar til sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Berre yver dei Israels-borni som budde i byarne i Juda, vart Rehabeam konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Og då kong Rehabeam sende i veg Hadoram, som hadde øvste tilsynet med pliktarbeidet til deim, då steina Israels-sønerne honom i hel. Då skunda kong Rehabeam seg upp i vogni si og rømde til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'So reiv då Israel seg laus frå Davids hus, og soleis hev det vore til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Då Rehabeam kom til Jerusalem, samla han heile Judas hus og Benjamin, hundrad og åtteti tusund utvalde stridsmenner, og vilde strida imot Israel og vinna kongedømet att for Rehabeam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Men då kom Herrens ord til gudsmannen Semaja soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '«Seg til Rehabeam Salomoson, kongen i Juda, og til heile Israel i Juda og Benjamin:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '«So segjer Herren: De skal ikkje fara upp og strida imot brørne dykkar; snu heim att kvar til sitt hus! For det som er hendt, er kome frå meg!»» Då lydde dei ordi frå Herren og snudde heim at og drog ikkje imot Jeroboam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Sidan budde Rehabeam i Jerusalem, og han bygde byar um til borger i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Soleis bygde han Betlehem og Etam og Tekoa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'og Bet-Sur og Soko og Adullam');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'og Gat og Maresa og Zif');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'og Adorajim og Lakis og Azeka');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'og Sora og Ajjalon og Hebron, som låg i Juda og i Benjamin. Han gjorde deim til festningsbyar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Og han gjorde borgerne sterke og sette hovdingar i deim, og gav deim forråd av matvaror og olje og vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Og kvar einskild av deim gav han skjoldar og spjot, og soleis gjorde han deim overlag sterke. Juda og Benjamin lydde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Men prestarne og levitarne i heile Israel gjekk yver til honom frå alle bygderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'For levitarne drog ifrå bumarkerne og eigedomen sin og for til Juda og Jerusalem, for di Jeroboam og sønerne hans jaga deim ut or prestetenesta for Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'og han tilsette prestar åt seg for offerhaugarne og bukketrolli og kalvarne som han hadde late gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Og i fylgje med deim kom dei frå alle Israels ættar som lagde hugen sin på å søkja Herren, Israels Gud. Dei kom til Jerusalem og ofra til Herren, sin fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Dei styrkte Judariket og tryggja Rehabeam, son åt Salomo i tri år. For i tri år gjekk dei på vegen åt David og Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Rehabeam tok til kona Mahalat, dotter åt Jerimot, son åt David, og åt Abiha’il, dotter åt Eliab, Isais son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Ho fødde honom sønerne Je’us og Semarja og Zaham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Og etter henne tok han Ma’aka, dotter åt Absalom, til kona; og ho fødde honom Abia og Attai og Ziza og Selomit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Rehabeam elska Ma’aka, dotter åt Absalom, meir enn dei andre konorne og fylgjekonorne sine; for han hadde attan konor og seksti fylgjekonor og vart far til åtte og tjuge søner og seksti døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Difor sette han Abia, son åt Ma’aka, til hovding og fyrste millom brørne sine; for han var tenkt på å gjera honom til konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Og på visleg måte skifte han ut alle landsluterne og dei faste borgerne i Juda og Benjamin til alle sønerne sine, og gav deim flust til å leva av og fekk deim konor i mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Men då Rehabeam hadde grunnfest kongedømet sitt og kjende seg sterk, då vende han seg frå Herrens lov, og heile Israel med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Då drog egyptarkongen Sisak upp mot Jerusalem i femte styringsåret åt Rehabeam, for di dei hadde vore utrue mot Herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'han kom med tolv hundrad krigsvogner, seksti tusund hestfolk, og ingen kunde rekna det folket som drog med honom frå Egyptarland, Libya-menner, sukkitar og ætiopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Og då han hadde teke dei faste borgarne i Juda, drog han mot Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Då kom profeten Semaja til Rehabeam og hovdingarne i Juda, som hadde søkt til Jerusalem for Sisak, og han sagde til deim: «So segjer Herren: «De hev vendt dykk ifrå meg, difor hev eg vendt meg ifrå dykk og gjeve dykk i handi på Sisak.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Men hovdingarne i Israel og kongen audmykte seg og sagde: «Herren er rettferdig.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Og då Herren såg at dei hadde audmykt seg, kom Herrens ord til Semaja soleis: «For di dei hev audmykt seg, vil eg ikkje tyna deim, men gjeva deim ei snaud frelsa, so at vreiden min ikkje strøymer ut yver Jerusalem ved Sisak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Men dei skal verta hans tenarar og læra å kjenna skilnaden på det å tena meg og tena kongeriki i heidningelandi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Då drog Sisak upp imot Jerusalem og tok skattarne i Herrens hus og skattarne i huset åt kongen; alt tok han, og han tok og dei gullskjoldarne som Salomo hadde lata gjere.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'I staden for deim let då kong Rehabeam gjera koparskjoldar og gav deim i varveitsla til hovdingarne for livvakti, som heldt vakt ved inngangen til huset åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Og kvar gong kongen gjekk til Herrens hus, bar vaktmennerne deim, og tok deim so attende til vaktstova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Men då han hadde audmykt seg, snudde Herrens vreide seg ifrå honom, so han vart ikkje reint tynt; det fanst då noko godt og i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Soleis vart kong Rehabeam grunnfest i Jerusalem, og han heldt fram med styringi; for Rehabeam var ein og fyrti år gamall då han vart konge, og han styrde i syttan år i Jerusalem, den byen som Herren hadde valt seg ut av alle ætterne i Israel til å setja namnet sitt der. Mor hans var ei ammonitkvinna som heitte Na’ama.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Han gjorde det som vondt var; for han lagde ikkje hugen sin på å søkja Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Det som er å fortelja um Rehabeam frå fyrste til sist, det er uppskrive i krønikorne åt profeten Semaja og sjåaren Iddo, der som ættartali er upprekna. Millom Rehabeam og Jeroboam var det ufred stødt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Og Rehabeam lagde seg til kvile hjå federne sine, og Abia, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'I det attande styringsåret åt Jeroboam vart Abia konge yver Juda;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'tri år styrde han i Jerusalem. Mor hans heitte Mikaja Urielsdotter og var frå Gibea. Det var ufred millom Abia og Jeroboam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abia byrja striden med ein her av djerve stridsmenner, fire hundrad tusund utvalde menner, men Jeroboam møtte honom med åtte hundrad tusund utvalde menner, som var djerve stridsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Men Abia gjekk upp på Semarajimberget i Efraimsfjelli og sagde: «Høyr meg Jeroboam og heile Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'De veit då vel at Herren, Israels Gud, hev gjeve kongedømet yver Israel for alle tider til David og hans søner ved ei ubrjotande semja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Men Jeroboam Nebatsson, trælen åt Salomo Davidsson, reiste seg og gjorde upprør mot herren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Og kring honom samla det seg lause karar, skamløysor, som tråssa Rehabeam, son åt Salomo, og Rehabeam var ung og veiklyndt og kunde ikkje halda seg imot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Og no trur de at de kann tråssa Herrens kongedøme, som ligg til Davids søner, for di det er ein stor hop av dykk, og det hev hjå dykk dei gullkalvarne som Jeroboam let gjera til gudar for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Hev de ikkje jaga burt Herrens prestar, sønerne åt Aron, og levitarne, og rådt dykk til prestar liksom hedningfolki? Kvar den som kom med ein ung ukse og sju verar til prestevigsla, han vert prest for u-gudarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Men Herren er vår Gud, og me hev ikkje vendt oss frå honom; sønerne åt Aron er prestar for Herren, og levitarne gjer tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Kvar morgon og kvar kveld let dei brennofferi ganga upp i røyk med finangande røykjelse, skodebrødi ligg på gullbordet, og gull-ljosestaken med lamporne kveikjer dei kveld etter kveld; for me agtar på fyresegnerne åt Herren, vår Gud, men de hev vendt dykk frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Sjå, Gud er føraren hjå oss og me hev prestarne hans med alarmlurarne, og dei skal blåsa til strid mot dykk. Israels søner, gjev dykk ikkje i strid med Herren, vår fedregud, for då skal de ikkje hava lukka med dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Men Jeroboam hadde late deim som låg i baklur kringganga deim soleis at Juda-mennerne hadde deim fyre seg og baklur-mennerne i ryggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Då no Juda-mennerne snudde seg rundt, og såg at åtaket truga deim både framantil og attantil, då ropa deim til Herren; men prestarne bles i lurarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Og Juda-mennerne sette i med herrop. Og då Juda-mennerne sette i med herropet, då slo Gud Jeroboam og heile Israel for augo på Abia og Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Israels-sønerne rømde for Juda, og Gud gav deim i deira vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Og Abia og folket hans gjorde stort tjon på deim, so det fall fem hundrad tusund stridsmenner av Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'På den tid vart Israels-sønerne audmjukte, men Juda-mennerne kom til magt, for dei studde seg til Herren, sin fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Og Abia forfylgde Jeroboam og tok ifrå honom nokre byar; det var Betel og grenderne kringum, Jesana og grenderne kringum og Efron og grenderne kringum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jeroboam kom aldri til magt meir so lenge Abia livde, og Herren slo honom, so han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Men Abia vart megtig. Han tok seg fire konor og vart far til tvo og tjugeto søner og sekstan døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Det som elles er å fortelja um Abia, um hans ferd og ord, er uppskrive i utleggjingi åt profeten Iddo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Og Abia lagde seg til kvile hjå federne sine, og dei gravlagde honom i Davidsbyen; Asa, son hans, vart konge i staden hans. I hans dagar hadde landet fred i ti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Asa gjorde det som var godt og rett i augo åt Herren, hans Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Han fekk burt dei framande altari og offerhaugarne, braut sund minnesteinarne og hogg ned Astarte-bilæti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Og han baud Juda-mennerne at dei skulde søkja Herren, deira fedregud, og halda lovi og bodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Og han fekk burt offerhaugarne og solsulorne frå alle byarne i Juda, og riket hadde ro so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Han bygde borgar i Juda; for landet hadde fred, og det kom ikkje til nokon krig imot honom i dei åri, for Herren gav honom ro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Han sagde til Juda: «Lat oss byggja desse byarne og setja murar og tårn ikring deim og portar og portbommar, medan me endå hev landet i vår magt, for di me hev søkt Herren, vår Gud; me hev søkt honom, og han hev gjeve oss fred til alle sidor.» So bygde dei då, og det gjekk godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Asa hadde ein her som var væpna med langskjoldar og spjot, tri hundrad tusund mann av Juda, og dessutan tvo hundrad og åtteti tusund av Benjamin, som bar rundskjoldar og spente boge. Alle desse var djerve stridsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Og ætiopen Zerah drog ut imot deim med ein her på tusund gonger tusund mann og tri hundrad stridsvogner, og han kom til Maresa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Og Asa drog imot honom, og dei fylkte seg til strid i Sefatadalen ved Maresa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Då ropa Asa til Herren, hans Gud: «Herre! det er ingen som du til å hjelpa i strid millom ein som er sterk og ein som er magtlaus. So hjelp oss, Herre, vår Gud! For til deg held me oss, og med ditt namn er me komne hit imot denne hopen. Herre, du er vår Gud; lat ikkje noko menneskje standa seg imot deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Då slo Herren ætioparne for augo på Asa og Juda og ætioparne rømde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Asa og folket som var med honom, forfylgde deim til Gerar, og det fall so mange av ætioparne, at ingen vart i live, for dei vart knustra for Herren og hans her. Folket tok ei uhorveleg mengd med herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Og dei tok alle byarne rundt ikring Gerar, for ein støkk frå Herren hadde kome yver deim, og dei plundra alle byarne, for det var mykje herfang i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Jamvel buskaps-tjeldi tok dei, og dei drog med seg ei mengd med småfe og kamelar, og so snudde dei heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Då kom Guds Ande yver Azarja Odedsson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'og han steig fram for Asa og sagde til honom: «Høyr på meg, Asa og heile Juda og Benjamin! Herren er med dykk når de er med honom, og når de søkjer honom, då let han dykk finna seg; men um de vender dykk frå honom, då vender han seg frå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'I lange tider var Israel utan sann Gud, utan prest som lærde deim, og utan lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Men i trengsla si umvende dei seg til Herren, Israels Gud, og søkte honom, og han let deim finna seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'I dei tider kunde ingen draga uskadd ut eller heim, for det var stor røra millom alle som budde i landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Då vart dei sundstøytte, folk mot folk og by mot by; for Gud skræmde deim med alle slag trengslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Men ver de frihuga og lat ikkje henderne siga; for dykkar verk skal få si løn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Då Asa høyrde desse ordi og den spådomen som Azarja, son åt Oded, sagde fram, då tok han mod til seg og fekk burt dei ufysne styggetingi frå heile Judalandet og Benjaminslandet og frå dei byarne han hadde teke på Efraimsheidi; og han sette i stand Herrens altar framfyre Herrens forhall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'So stemnde han saman heile Juda og Benjamin og deim ifrå Efraim, Manasse og Simeon som budde hjå deim; for ei mengd ifrå Israel hadde gjenge yver til honom då dei såg at Herren, hans Gud, var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Dei samla seg då i Jerusalem i den tridje månaden i det femtande styringsåret åt Asa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Og den dagen slagta dei offer for Herren av det herfanget dei hadde ført med seg, sju hundrad stykke storfe og sju tusund stykke småfe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Og dei gjorde ei pakt um at dei vilde søkja Herren, sin fedregud, av alt sitt hjarta og heile si sjæl,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'og at kvar den som ikkje søkte Herren, Israels Gud, han skulde lata livet, anten han var liten eller stor, mann eller kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Soleis gav dei Herren eiden sin med høg røyst og med fagnadrop og med ljom av lurar og horn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'og heile Juda gledde seg yver den eiden, for dei hadde svore med heile sitt hjarta og søkte honom med all sin vilje; Og Herren let deim finna seg og gav landet fred til alle sidor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Og jamvel Ma’aka, mor si, sette kong Asa av frå hennar dronningrang, av di ho hadde gjort eit styggjelegt bilæte for Astarte; han hogg ned det stygge bilætet, slo det i smulder og brende det i Kidronsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Men offerhaugarne fekk dei ikkje burt ifrå Israel; men like vel var hjarta til Asa heilstøypt so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Heilaggåvorne åt far sin og heilaggåvorne sine eigne flutte han inn i Guds hus, sylv og gull og ymse ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Det vart ingen ufred fyrr i det fem og trettiande styringsåret åt Asa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'I det seks og trettiande styringsåret åt Asa drog kong Baesa i Israel upp imot Juda og bygde ei borg i Rama, av di han ville hindra at nokon drog ut eller inn hjå Asa, kongen i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Då tok Asa sylv og gull ut or skattkammeri i Herrens hus og i huset åt kongen og sende deim til Benhadad, kongen i Syria, som budde i Damaskus, med dei ordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '«Det er eit samband millom meg og deg, sameleis som millom min far og din far, no sender eg deg sylv og gull. Gjer no vel og brjot sambandet ditt med Israels-kongen Baesa, so han lyt draga burt ifrå meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad lydde kong Asa og sende herhovdingarne sine mot byarne i Israel, og dei herja Ijon og Dan og Abel-Majim og alle forrådshusi i Naftali-byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Då Baesa høyrde dette, lagde han ned borgbyggjingi i Rama og slutta arbeidet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Men kong Asa tok heile Juda med seg, og dei førde burt steinarne og trevyrket som Baesa hadde bruka til byggverket i Rama, og han bruka deim til å byggja Geba og Mispa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'På den tid kom sjåaren Hanani til Asa, kongen i Juda, og sagde til honom: «For di du studde deg til Syria-kongen og ikkje til Herren, din Gud, hev heren åt Syria-kongen sloppe or henderne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Var ikkje ætioparne og libyararne ein stor her med ei ovmengd med vogner og hestfolk? Men då du studde deg til Herren, då gav han deim i di magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'For Herrens augo fer utyver all jordi, av di han med kraft vil koma deim til hjelp som hev hjarta sitt heilt med honom. Du hev fare fåvist åt i dette; for heretter kjem du til å hava ufred stødt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Då vart Asa harm på sjåaren og kasta honom i fangehuset, so vond var han for dette. På same tid for Asa hardt fram mot andre av folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Det som er å fortelja um Asa frå fyrst til sist, er uppskrive i boki um kongarne i Juda og Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'I det ni og trettiande styringsåret sitt vart Asa sjuk i føterne, og sjukdomen hans vart svært hard. Men ikkje i sjukdomen sin heller søkte han Herren, men lækjarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Og Asa lagde seg til kvile hjå federne sine og døydde i det eitt og fyrtiande styringsåret sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Dei gravlagde honom i gravi hans, som han hadde late hogga ut i Davidsbyen, og lagde honom på ei lega som dei hadde fyllt med kryddor av ymse slag som var tillaga i salveblanding, og dei kveikte eit ovlagt bål for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Josafat, son hans, vart konge i staden hans. Han synte seg sterk imot Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'og lagde herfolk i alle dei faste byarne i Juda og sette inn vakter i Judalandet og i dei byarne i Efraim som Asa, far hans, hadde herteke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Og Herren var med Josafat, for han fylgde dei fyrste vegarne åt David, far sin, og heldt seg ikkje til Ba’alarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'men søkte til far sin’s Gud og fylgde bodi hans og gjorde ikkje soleis som Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Difor grunnfeste Herren kongedømet i hans hand, og heile Juda gav Josafat gåvor, so at han fekk mykje rikdom og æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Då voks modet hans på Herrens vegar, og han fekk ogso burt offerhaugarne og Astarte-bilæti frå Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'I det tridje styringsåret sitt sende han hovdingarne sine Benha’il og Obadja og Zakarja og Netanel og Mikaja til å læra i Juda-byarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'og saman med deim levitarne Semaja og Netanja og Zebadja og Asael og Semiramot og Jonatan og Adonja og Tobia og Tob-Adonia, levitarne, og med deim prestarne Elisama og Joram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Dei lærde i Juda, for dei hadde Herrens lovbok med seg, og dei drog kringum i alle Juda-byarne og lærde folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Då kom ein støkk frå Herren yver alle riki i dei landi som låg rundt ikring Juda, so dei våga seg ikkje i krig med Josafat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Nokre av filistarane førde gåvor til Josafat, og sylv til skatt, og arabarane og førde småfe til honom, sju tusund og sju hundrad verar og sju tusund sju hundrad bukkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Soleis gjekk Josafat frametter stødt til han vart overlag megtig, og han bygde borger og upplagsbyar i Juda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'og han store forråd i Juda-byarne og stridsdjerve herfolk i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Dette er lista yver deim etter ættgreinerne deira: Yverhovdingarne i Juda var: Hovdingen Adna med tri hundrad tusund djerve stridsmenner;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'jamsides honom hovdingen Johanan med tvo hundrad og åtteti tusund mann;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'jamsides honom Amasja Zikrison, som hadde gjenge i Herrens tenesta friviljugt, og med honom var tvo hundrad tusund djerve stridsmenner;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'framleides var det frå Benjamin den djerve kjempa Eljada med tvo hundrad tusund mann, som bar boge og skjold,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'jamsides honom Jozabad med hundrad og åtteti tusund djerve stridsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Dette var dei som stod i tenesta åt kongen, umfram deim som kongen hadde lagt i borgbyarne i heile Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Då Josafat hadde vunne seg rikdom og æra, gjekk han i mågskap med Ahab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Etter nokre år var lidne, drog han ned til Ahab i Samaria, og Ahab let slagta ei mengd med småfe og storfe for honom og mannskapet han hadde med seg; so lokka han honom til å draga upp mot Ramot i Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'For Israels-kongen Ahab sagde til Juda-kongen Josafat: «Vil du fara med meg til Ramot i Gilead?» Han svara honom: «Eg som du, og mitt folk som ditt folk, me vil vera med deg i striden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Men Josafat sagde til Israels-kongen: «Spør like vel fyrst Herrens ord til råds!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Då stemde Israels-kongen saman profetarne, fire hundrad mann, og spurde deim: «Skal me draga ut og strida mot Ramot i Gilead, eller skal eg lata det vera?» Dei svara: «Drag dit upp! Gud vil gjeva byen i henderne på kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Men Josafat spurde: «Er det ikkje endå ein av Herrens profetar her, so me kunde spyrja gjenom honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Israels-kongen sagde til Josafat: «Det er endå ein mann som ein kann spyrja Herren ved; men eg hatar honom, for di han spår meg aldri noko godt, men berre vondt alle sine dagar; det er Mika Jimlason.» Josafat sagde: «Soleis må ikkje kongen tala!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Då kalla Israels-kongen på ein hirdmann og sagde: «Henta snøgt Mika Jimlason!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Israels-kongen og Juda-kongen Josafat sat klædde i sine skrud kvar på sin kongsstol, dei sat på treskjevollen ved inngangen til byporten i Samaria, og alle profetarne spådde framfyre deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Og Sidkia, son åt Kena’ana, gjorde seg horn av jarn og sagde: «So segjer Herren: «Med slike horn skal du stanga syrarane til du tyner deim.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Og alle profetarne spådde på same måten og sagde: «Drag upp til Ramot i Gilead, so skal du få siger, og Herren vil gjeva byen i henderne på kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Sendemannen som var gjengen og skulde henta Mika, sagde til honom: «Profetarne hev samrøystes lova kongen lukka, lat då ordi dine samstavast med deira, og lova lukka du og!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Men Mika svara: «So sant som Herren liver, vil eg berre tala det som min Gud segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Då han no kom til kongen, sagde kongen til honom: «Mika, skal me draga av stad og strida um Ramot i Gilead, eller skal eg lata det vera?» Då sagde han: «Drag upp, so skal de få siger, og dei skal verta gjevne i dykkar vald.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Men kongen sagde til honom: «Kor mange gonger skal eg taka deg i eid på at du ikkje vil segja meg anna enn sanningi i Herrens namn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Då sagde han: «Eg såg heile Israel spreidt utyver fjelli som ein saueflokk utan hyrding; og Herren sagde: «Dei der hev ingen herre, lat deim snu heim att i fred, kvar til sitt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Israels-kongen sagde til Josafat: «Sagde eg deg ikkje at han aldri varslar meg noko godt, berre vondt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Då sagde han: «So høyr då Herrens ord: Eg såg Herren sitja på sin kongsstol, og heile himmelheren stod på den høgre og den vinstre sida hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Og Herren sagde: Kven vil lokka Israels-kongen Ahab, so han dreg upp og fell ved Ramot i Gilead?» Då sagde ein so og ein annan so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Men då kom anden fram og stelte seg framfor Herren og sagde: «Eg skal lokka honom!» Herren spurde honom: «Korleis?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Han svara: «Eg vil ganga ut og verta ei ljugarånd i munnen på alle profetarne hans.» Og han sagde: «Ja, du skal lokka honom, og du skal og greida det. Gakk av stad, og gjer so!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Sjå no hev Herren lagt ei ljugarånd i munnen på desse profetarne dine, men Herren hev varsla ulukka yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Då kom Sidkia, son åt Kena’ana, fram og slo Mika på kinni og sagde: «Kva veg hev då Herrens ande fare ifrå meg for å tala med deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Men Mika sagde: «Det skal du få sjå den dagen då du rømer frå kove til kove og vil gøyma deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Då sagde Israels-kongen: «Tak Mika og før honom til byhovdingen Amon og kongssonen Joas,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'og seg: «Kongen byd dykk at det skal kasta denne mannen i fangehuset og setja honom på snaud kost, til kongen kjem heim att med heilo!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Men Mika sagde: «Kjem du heim att med heilo, då hev ikkje Herren tala gjenom meg.» Og so sagde han: «Høyr, de folk, alle saman!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'So drog då Israels-kongen og Josafat, Juda-kongen, upp til Ramot i Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Men Israels-kongen sagde til Josafat: «Eg vil klæda meg ut fyrr eg gjeng inn i striden, men hav du dine klæde på deg!» Og Israels-kongen klædde seg ut, og so gjekk dei inn i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Men Syria-kongen hadde gjeve det bodet til hovdingarne for stridsvognerne sine at dei ikkje skulde taka på nokon, korkje liten eller stor, men berre på Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Då no hovdingarne fekk stridsvognerne fekk auga på Josafat, tenkte dei: «Det er visseleg Israels-kongen!» Og dei kringsette honom og vilde strida. Men Josafat sette i eit høgt rop, og Herren frelste honom; for Gud vende dei burt ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Og då hovdingarne for stridsvognerne merka at det ikkje var Israels-kongen, drog dei seg burt ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Men ein mann som spente bogen og skaut på måfå, råka Israels-kongen millom brynjeskøytingarne og brynja. Då baud han vognstyraren sin: «Snu, og før meg ut or heren! for eg er såra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Men striden vart hardare og hardare den dagen, og Israels-kongen vart standande i vogni si imot syrarane like til um kvelden; og ved soleglad døydde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Men Josafat, Juda-kongen, snudde heim att til Jerusalem med heilo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Men då gjekk sjåaren Jehu Hananison ut imot honom og sagde til kong Josafat: «Skal ein hjelpa den gudlause, og elskar du deim som hatar Herren? For dette kviler det vreide på deg ifrå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Like vel er det funne noko godt hjå deg, for du hev øydt ut Astarte-bilæti or landet og hev lagt hugen din på å søkja Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Josafat vart no buande i Jerusalem. Og so drog han ut att bland folket ifrå Be’erseba og til Efraimsheidi, og førde deim attende til Herren, deira fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Og han sette inn domarar i landet i kvar ein av dei faste byarne i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Og han sagde til domarane: «Agta vel på det de gjer; for de feller ikkje dom for menneskje, men for Herren, og han er hjå dykk når det dømer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Difor skal otte for Herren vera yver dykk! Ver varsame med det som de gjer! for hjå Herren, vår Gud, finst det ingen urett, ikkje gjer han skil på folk, og ikkje tek han mutor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'I Jerusalem og sette Josafat nokre av levitarne og prestarne og ættarhovdingarne i Israel til å agta på Herrens saker og rettstrættorne; dei hadde vendt heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Og han baud deim og sagde: «Soleis skal de bera dykk åt med age for Herren, i truskap og med heilt hjarta:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Kvar gong det vert lagt fram for dykk ei rettstrætta frå brørne dykkar, som bur i byarne sine, anten det er dom i ei dråpssak eller eit bod, ei lov eller vedtekter og rettar, då skal de vara deim åt, so dei ikkje syndar imot Herren, og det kjem vreide yver dykk og brørne dykkar. Gjer soleis, so det ikkje skal draga skuld yver dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'I alt det som kjem ved Herren, skal øvstepresten Amarja vera formannen dykkar, og i alt det som kjem ved kongen, skal Zebadja Ismaelsson, hovdingen for Juda-ætti, vera formann; og levitarne skal vera tilsynsmenner under dykk. Tak no hugheilt fat på verket, og Herren skal vere med den som er god.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Sidan hende det, at Moabs-sønerne og Ammons-sønerne og nokre av me’unitarne saman med deim drog i herferd mot Josafat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Og dei kom og melde det til Josafat og sagde: «Det kjem ein stor hop imot deg frå landi på hi sida havet, frå Syria, og dei er i Haseson-Tamar, det er En-Gedi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Då vart Josafat rædd og tok til å søkja Herren, og lyste ut ei fasta yver heile Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Då kom Juda saman og søkte hjelp hjå Herren, og dei kom frå alle Juda-byarne og søkte Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Men Josafat stelte seg i samlingslyden frå Juda og Jerusalem i Herrens hus, framanfor den nye tunet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'og han sagde: «Herre, vår fedregud! Du er då Gud i himmelen, du råder yver alle heidningriki, i di hand er det kraft og velde, og imot deg kann ingen standa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hev ikkje du, vår Gud, jaga burt ibuarane i dette landet for Israel, folket ditt, og gjeve det til ættingarne åt Abraham, venen din, for alder og æva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Og dei busette seg i det og bygde deg ein heilagdom der for ditt namn, med di dei og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '«Um det kjem nokor ulukka yver oss, sverd, straffedom, farsott eller hungersnaud, då vil me stella oss upp framanfor dette huset for di åsyn, for namnet ditt bur i dette huset; og me vil ropa til deg i naudi vår, og so vil du høyra og hjelpa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Sjå no Ammons-sønerne og Moab og folket ifrå Se’irfjelli - du gav ikkje Israel lov til å trengja inn i deira land då dei kom frå Egyptarlandet, difor heldt dei seg burte frå deim og øyde deim ikkje -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'sjå no korleis dei løner oss, med di dei kjem og vil jaga oss burt ifrå eigedomen din, som du hev gjeve oss til eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Vår Gud, vil du då ikkje halda dom yver deim? for hjå oss er det ingi kraft imot denne velduge hopen, som kastar seg yver oss, og me veit ikkje kva me skal gjera, men vender augo våre imot deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Og heile Juda stod framfor Herrens åsyn, ja, småborni og konorne og sønerne deira var med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Då kom Herrens ande yver leviten Jahaziel, son åt Zakarja, son åt Benaja, son åt Je’iel, son åt Mattanja, av Asafs søner, midt i lyden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'og han sagde: «Lyd etter, heile Juda og de Jerusalems-buar og du kong Josafat! So segjer Herren til dykk: «Ottast ikkje og ræddast ikkje for denne megtige hopen! for striden er ikkje dykkar, men Guds sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Drag ned imot deim i morgon, då vil dei stiga upp etter vegen ved Hassis, og de skal råka deim ved enden av dalen imot Jeruel-øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Men dermed er de ikkje dykkar sak å strida, men de skal stella dykk upp og standa stilt og sjå på korleis Herren frelser dykk, de frå Juda og Jerusalem. Ottast ikkje og ræddast ikkje, men drag imot deim i morgon, so skal Herren vera med dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Då bøygde Josafat seg med andlitet til jordi, og heile Juda og alle Jerusalems-buarne fall ned for Herren og tilbad Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Men levitarne av kahatitsønerne og korahitsønerne stod upp og lova Herren, Israels Gud, med overlag høg røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Tidleg um morgonen drog dei so ut til Tekoa-øydemarki; og medan dei drog ut, stod Josafat og sagde: «Høyr meg, Juda, og de Jerusalems-buar! Tru på Herren, dykkar Gud, so stend de traust, og tru på profetarne hans, so skal de verta lukkelege!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Og han gjorde avtale med folket og stelte upp songarar for Herren; dei skulde lova honom i heilagt skrud, medan dei drog ut fyre deim som var herbudde, og dei skulde segja: «Prisa Herren, for æveleg varer hans miskunn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Og straks dei tok til med fagnadropi og lovprisningarne sine, stelte Herren åtakarar som låg i løynlega imot Ammon og Moab og folket frå Se’irfjelli, som drog fram imot Juda, so dei vart slegne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Ammons-sønerne og Moab stelte seg imot folket frå Se’irfjelli og hogg deim ned og øydelagde deim, og då dei var ferdige med deim, hjelptest dei åt med å tyna kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Då Juda kom til utsynshaugen yver øydemarki og snudde seg imot hopen, då såg dei berre lik som låg på jordi, og ingen hadde kome seg undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Då drog Josafat og folket hans dit og plundra deim, og dei fann ei mengd med gods og lik og kostesame ting. Dei tok meir til seg enn dei kunde føra burt, og dei heldt på i tri dagar med å plundra, so stort var herfanget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Den fjorde dagen samla dei seg i Lovprisingsdalen; for der lova dei Herren, og difor kalla dei den staden Lovprisingsdalen, og det heiter han den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'So snudde dei, alle folki frå Juda og Jerusalem, med Josafat i brodden, og drog attende til Jerusalem med gleda, for Herren hadde gjeve deim gleda yver fiendarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Og dei drog inn i Jerusalem med harpor, cithrar og lurar til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Og ein støkk for Gud kom yver alle dei framande riki då dei høyrde at Herren hadde stridt imot Israels fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Soleis fekk Josafats kongedøme fred, for hans Gud gav honom ro til alle sider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'So rådde Josafat yver Juda. Fem og tretti år var han då han vart konge, og fem og tjuge år rådde han i Jerusalem. Mor hans heitte Azuba og var dotter åt Silhi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Han gjekk på vegarne åt Asa, far sin, og veik ikkje ifrå deim, for han gjorde det som rett var i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Men offerhaugarne fekk dei ikkje burt, med di folket ikkje vende hugen sin fast mot sine feders Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Det som elles er å fortelja um Josafat frå fyrst til sist, det finst uppskrivi i krønikeboki åt Jehu Hananison, som er uppteke i boki um Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Sidan gjorde Josafat i Juda samlag med Ahazja, kongen i Israel, endå han for gudlaust fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Og han gjorde samlag med honom um å byggja skip som skulde sigla til Tarsis. Dei bygde skip i Esjon-Geber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Men Eliezer Dodavason frå Maresa spådde mot Josafat og sagde: «For di du hev gjort samlag med Ahazja, vil Herren gjera tiltaket ditt um inkje.» Og nokre skip forliste og kunde ikkje sigla til Tarsis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'So lagde Josafat seg til kvile hjå federne sine, og han vart gravlagd hjå federne sine i Davidsbyen. Og Joram, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Han hadde nokre brør, sønerne åt Josafat; det var Azarja og Jehiel og Zakarja og Azarja og Mikael og Sefatja, som alle var søner åt kong Josafat, Israels-kongen i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Far deira hadde gjeve deim store gåvor utav sylv, gull og kostnadting og faste byar i Juda, men kongedømet gav han til Joram, for han var den eldste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Men då Joram hadde fenge under seg riket åt far sin og hadde styrkt magti si, då let han alle brørne sine drepe med sverdet, og nokre av Israels-hovdingarne ogso.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Tvo og tretti år gamall var Joram då han vart konge, og åtte år rådde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Han gjekk på same vegarne som Israels-kongarne, og soleis som Ahabs hus hadde gjort; for han var gift med ei dotter til Ahab, og han gjorde det som vondt var i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Like vel vilde Herren ikkje tyna Davids hus for den pakti skuld som han hadde gjort med David, og etter det som han hadde lova, at det alltid skulde lysa ei lampa for honom og sønerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'I hans tid reiv edomitarne seg laus ifrå Juda og kåra seg ein konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Då drog Joram ut med hovdingarne sine og alle stridsvognerne sine, og han tok ut um natti og slo edomitarne, som kringsette honom, og hovudsmennerne yver vognheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Soleis kom Edom seg laus ifrå Juda, og er fri den dag i dag. Den gongen reiv Libna seg laus ifrå honom, for di han hadde svike Herren, sin fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Han og bygde upp offerhaugar i Judafjelli og forførde Jerusalems-buarne til utukt og Juda til fråfall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Då kom det eit brev til honom frå profeten Elia, og der stod det: «So segjer Herren, Gud åt far din, David: «For di du ikkje hev gjenge på vegarne åt Josafat, far din, eller åt Juda-kongen Asa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'men hev gjenge på vegarne åt Israels-kongarne, og hev forført Juda og Jerusalems-buarne til utukt, sameleis som Ahabs hus forførde til det, og endå til hev drepe brørne dine, frendarne dine, som var betre enn du er sjølv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'so vil Herren no lata eit veldugt slag råma folket ditt, sønerne dine, konorne dine og alt det som du eig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Og sjølv skal du få ein fæl sjukdom i innvolarne dine, so at um år og dag skal innvolarne dine falla ut for skuld sjukdomen.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Herren øste då upp filistarane imot Joram, og dei arabarane som budde attmed med ætioparne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'so dei drog upp imot Juda, trengde seg inn i det og rana alt det som fanst i huset åt kongen, og dertil sønerne og konorne hans, so han hadde ikkje att nokon son so nær som den yngste av sønerne, Joahaz.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Og etter alt dette slo Herren honom med ein ulækjeleg sjukdom i innvolarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Etter år og dag, då tvo år var lidne, fall innvolarne hans fram for skuld sjukdomen hans, og han døydde med harde lidingar. Folket hans kveikte ikkje noko bål for honom, soleis som for federne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Tvo og tretti år gamall var han då han vart konge; i åtte år rådde han i Jerusalem. Dei gravlagde honom i Davidsbyen, men ikkje i kongegraverne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'So tok Jerusalems-buarne Ahazja, den yngste son hans, til konge i staden hans; for dei eldste hadde røvarflokken drepe som hadde kome til lægret saman med arabarane. Soleis vart Ahazja Joramsson konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Tvo og tjuge år gamall var Ahazja då han vart konge, og eitt år var han konge i Jerusalem. Mor hans heitte Atalja og var dotter åt Omri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Han gjekk på vegarne åt Ahabs hus; for mor hans forførde honom til gudløysa med råderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Han gjorde det som vondt var i Herrens augo, liksom Ahabs hus; for til hans eige tjon vart dei rådgjevarene hans etter far hans var avliden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Etter deira råd for han og i herferd saman med Israels-kongen Joram Ahabsson, imot syrarkongen Hazael ved Ramot i Gilead. Men syrarane særde Joram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Då snudde han attende og vilde få lækt dei såri i Jizre’el som dei hadde gjeve honom ved Rama, då han stridde med syrarkongen Hazael. Og Azarja, kongen i Juda, son åt Joram, drog ned til Jizre’el og vilde sjå um Joram Ahabsson, av di han var sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Men til undergang for Ahazja hadde Gud laga det so, at han skulde koma til Joram, og når han kom, skulde han draga ut med Joram imot Jehu Nimsison, som Herren hadde salva til å øyda ut Ahabs hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'For då Jehu sette i verk domen yver Ahabs hus, då råka han hovdingarne i Juda og brorsønerne åt Ahazja, som gjekk Ahazja til handa, og han drap deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'So leita han etter Ahazja, og dei greip honom då han gøymde seg i Samaria, og leidde honom til Jehu, som let honom drepa. Like vel gravlagde dei honom; for dei kom i hug at han var son åt Josafat, som heldt seg til Herren med heile sitt hjarta. Men det var ingen att av huset åt Ahazja som var sterk nok til å taka kongedømet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Då Atalja, mor åt Ahazja, fekk vita at son hennar var dåen, tok ho seg fyre å tyna heile kongsætti i Judas hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Men Josabat, dotter åt kongen, tok Joas Ahazjason, og fekk honom burt ifrå kongssønerne, som var drepne, og fekk honom og fostermor hans inn i sengkammerset. Soleis gøymde Josabat, dotter åt kong Joram og kona åt presten Jojada - for ho var syster åt Ahazja - honom for Atalja, so ho fekk ikkje drepe honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'So var han hjå deim i Guds hus burtgøymd i seks år, medan Atalja styrde i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Men i det sjuande året tok Jojada mod til seg og gjorde eit samband med hundradhovdingarne Azarja Jerohamsson og Ismael Johanansson og Azarja Obedsson og Ma’aseja Adajason og Elisafat Zikrison.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Dei drog ikring i Juda og samla levitarne i hop frå alle Juda-byarne og ættarhovdingarne i Israel, og so for dei til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'So gjorde heile lyden eit samband i Guds hus med kongen, og han sagde til deim: «Kongssonen der skal vera konge, soleis som Herren hev sagt um Davids søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Og soleis skal det bera dykk åt: Den eine tridjeparten av dykk, dei prestarne og levitarne som tek vakthaldet på kviledagen, dei skal standa vakt ved dørstokkarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'og den andre tridjeparten skal standa i kongsgarden, og den tridje i Grunnporten, men alt folket i tuni ved Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Men ingen må koma inn i Herrens hus so nær som prestarne og dei utav levitarne som gjer tenesta; dei kann ganga inn der; for dei er heilage. Men det andre folket skal halda seg etter Herrens fyresegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'So skal levitarne gjera manngard rundt ikring kongen, kvar mann med våpn i hand. Kvar den som kjem innåt huset, skal hoggast ned; og soleis skal de vera ikring kongen når han gjeng ut, og når han gjeng inn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Levitarne og alle Juda-mennerne gjorde no plent det som presten Jojada baud deim; kvar og ein tok sine folk, både deim som skulde taka ved vakti um kviledagen og deim som skulde ganga frå um kviledagen; for presten Jojada gav ikkje skifti heimlov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Og presten Jojada gav hundradhovdingarne dei spjoti og dei små skjoldarne og store skjoldarne som kong David hadde ått, og som var i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Deretter stelte han upp heile folket, kvar med sitt våpn i hand, ifrå sudsida til nordsida på huset, burt til altaret og derifrå til huset att i manngard kring kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Og dei leidde ut kongssonen, sette kruna på honom og gav honom lovi og gjorde honom til konge; og Jojada og sønerne hans salva honom og ropa: «Live kongen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Men Atalja høyrde ståket ifrå folket, som sprang og hyllte kongen, og ho gjekk av stad til folket i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Og då ho såg kongen stod på tramen sin ved inngangen og hovdingarne og lurblåsarane hjå kongen, og heile landslyden som gledde seg og bles i lurarne, og songarane med speli sine, som leidde fagnadropi, då reiv Atalja sund klædi sine og ropa: «Samansverjing! samansverjing!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Men presten Jojada baud hundradhovdingarne, som var hovudsmenner yver heren, at dei skulde føra henne ut millom rekkjorne og hogga ned kvar den som vilde fylgja henne. «For de må ikkje drepa henne i Herrens hus,» sagde presten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Då tok dei henne og førde henne dit det Hesteporten føre inn til kongsgarden, og der drap dei henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Men Jojada gjorde ei pakt millom seg, heile folket og kongen, at dei skulde vera eit Herrens folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Og alt folket drog til Ba’als-huset og braut det ned; altari og bilæti øydelagde dei reint, og Ba’als-presten Mattan drap dei framanfor altari.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'So sette Jojada tilsyn i Herrens hus og gav det yver til dei levitiske prestarne, som David hadde tiletla Herrens hus, - til å ofra Herrens brennoffer, som det er skrive i Moselovi, med fagnad og song etter skipnad frå David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Og han sette dørvaktarar ved portarne til Herrens hus, so ingen skulde ganga inn i det som var urein på einkvar måten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Og han tok hundradhovdingarne og dei fornæme og dei megtigaste bland folket og heile landslyden og førde kongen ned frå Herrens hus. Og dei gjekk gjenom den øvre porten til huset åt kongen og sette kongen i kongsstolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Då gledde heile landslyden seg, og byen kom til ro; men Atalja hadde dei drepe med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Sju år gamall var Joas då han vart konge, og fyrti år styrde han i Jerusalem. Mor hans heitte Sibja og var frå Be’erseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joas gjorde det som rett var i Herrens augo so lenge presten Jojada livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Jojada tok tvo konor åt honom, og han fekk søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Sidan kom Joas på den tanken at han vilde setja i stand Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Difor stemde han saman prestarne og levitarne og sagde til deim: «Drag ut til Juda-byarne og samla i inn pengar ifrå heile Israel til å vøla på huset åt dykkar Gud, etter som det krevst år etter år. Og skunda dykk med å gjera dette!» Men levitarne skunda seg ikkje med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Då kalla kongen til seg øvstepresten Jojada og sagde til honom: «Kvifor hev du ikkje sytt for at levitarne koma med den skatten frå Juda og Jerusalem som Moses, Herrens tenar, lagde på Israels-lyden til beste for kunngjeringstjeldet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'For sønerne åt denne ugudlege Atalja, dei hev brote seg inn i Guds hus, ja, alt som var vigt til Herrens hus, hev dei bruka på Ba’als-gudarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Kongen baud difor at dei skulde laga ei kista og setja upp utanfor porten til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Og det vart lyst ut i Juda og Jerusalem at dei skulde føra den skatten til Herren som Moses, Guds tenar, hadde lagt på Israels-borni i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Alle hovdingarne og heile folket bar då pengarne fram med gleda, og kasta i kista til dess ho var full.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Og når dei såg at det var mykje sylv i henne, tok levitarne kista og førde henne til det kongelege tilsynet, og då kom den kongelege skrivaren og den tilsynsmannen som øvstepresten hadde sett til, kvar gong og tømde kista; og so tok dei henne og førde hende attende på plassen sin. Soleis gjorde dei gong etter gong, og dei samla ei stor mengd med pengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'So gav kongen og Jojada deim til arbeidsformennerne ved arbeidet på Herrens hus, og dei leigde steinhoggarar og timbremenner til å setja i stand Herrens hus, og jarn- og koparsmedar til å vøla på Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Arbeidsformennerne tok fat på arbeidet, so at verket hadde framgang i deira hand, og dei bygde upp Guds hus soleis som det hadde vore planlagt, og fekk det godt i stand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Då dei var ferdige med det, bar dei resten av pengarne til kongen og Jojada, og han let gjera gogner av det til Herrens hus, gogner til tenesta og offeri, og skåler og kjerald av gull og sylv. Og dei ofra brennoffer i Herrens hus stødt so lenge Jojada livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Men Jojada vart gamall og mett av dagar og døydde; hundrad og tretti år gamall var han då han døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Dei gravlagde honom i Davidsbyen hjå kongarne, for di han hadde gjort vel imot Israel og mot Gud og hans hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Då no Jojada var avliden, kom hovdingarne i Juda og kasta seg ned for kongen; og kongen høyrde viljugt på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Då gjekk dei ifrå huset åt Herren, sin fedregud, og dyrka Astarte-bilæti og dei andre avgudarne. Difor kom det vreide yver Juda og Jerusalem for denne syndi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Og han sende profetar til deim til å føra deim attende til Herren, og dei tala ålvorsamt til deim, men dei høyrde ikkje på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Då tok Guds ande presten Zakarja, son åt Jojada, so han stod fram for folket og sagde til deim: «So segjer Gud: «Kvifor gjer det imot Herrens bod og slepper ifrå dykk lukka! For di de hev gjenge ifrå honom, hev han gjenge frå dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Då svor dei seg saman imot honom, og steina honom i fyregarden til Herrens hus etter bod frå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'For kong Joas gløymde den kjærleiken som Jojada, far hans, hadde synt imot honom, og han drap son hans. Men då han døydde, ropa han: «Herren sjå og straffe!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Då året var ute, drog syrarheren imot honom, og dei kom til Juda og Jerusalem og øydde ut alle hovdingarne i folket og sende heile herfanget sitt til kongen i Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Endå syrarheren var fåment då han kom, so gav Herren ein ovstor her i deira vald, for di dei hadde gjenge ifrå Herren, sin fedregud, og soleis sette dei i verk domen yver Joas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Og då dei drog burt ifrå honom - for dei let honom etter seg i tunge lidingar - då gjorde hirdmennerne hans ei samansverjing imot honom, for di han hadde drepe sønerne åt presten Jojada, og dei drap honom på lega hans. Soleis døydde han, og dei gravlagde honom i Davidsbyen, men ikkje i kongegraverne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Dei som svor seg saman imot honom, var Zabad, son åt ammonitkvinna Simat, og Jozabad, son åt moabitkvinna Simrit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Um sønerne hans og alle profetordi imot honom og grunnleggjingi av Guds hus, det finst uppskrive i utleggjingi til kongeboki. Amasja, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Fem og tjuge år gamall var Amasja då han vart konge, og ni og tjuge år styrde han i Jerusalem. Mor hans heitte Joaddan og var ifrå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Han gjorde det som rett var i Herrens augo, endå det ikkje var med eit heilt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Då han hadde vorte grunnfest i kongedømet, let han drepe dei hirdmennerne som hadde slege i hel kongen, far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Men borni deira let han ikkje drepa, men heldt seg til det som stend skrive i lovi i Moseboki, der Herren hev bode soleis: «Foreldri skal ikkje døy for det borni deira hev gjort, og borni ikkje for det foreldri hev gjort, men kvar og ein skal døy for si eigi synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'So stemnde Amasja Juda-mennerne saman og skipa deim etter ættgreinerne under tusund- og hundradhovdingarne for heile Juda og Benjamin; han mynstra deim ifrå tjugeårsalderen og uppetter, og på den måten fekk han det til tri hundrad tusund utvalde stridsføre hermenner som bar skjold og spjot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Han leigde so hundrad tusund djerve stridsmenner i Israel for hundrad sylvtalent.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Men gudsmannen kom til honom og sagde: «Israels-heren må ikkje draga med deg, konge, for Herren er ikkje med Israel, ikkje med nokon av alle Efraims-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Men drag du av stad, gjer det, ver hugheil til striden! Elles vil Gud føra deg til fall for fienden, for Gud hev kraft til å hjelpa og til å fella.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amasja spurde gudsmannen: «Men kva vert det då av dei hundrad sylvtalenti som eg hev gjeve til flokken ifrå Israel?» Men gudsmannen svara: «Herren er god til å gjeva deg meir enn det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Då skilde Amasja ut den flokken som hadde kome til honom ifrå Efraim, og let dei fara heim. Men yver dette vart dei brennende harme på Juda og snudde heim i storsinne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amasja tok mod til seg og førde herfolket sitt til Saltdalen, og der hogg han ned ti tusund utav Se’irs-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Dessutan tok Juda-mennerne ti tusund krigsfanger og førde deim upp på ein bergtopp og støytte deim ned derifrå, so dei vart knasa alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Men folket av den flokken som Amasja hadde sendt heim, so dei ikkje drog i krigen med honom, dei gjorde innfall i Juda-byarne ifrå Samaria til Bet-Horon, hogg ned tri tusund menneskje og gjorde stort herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Då Amasja var komen att ifrå sigeren yver edomitarne, tok han med seg gudarne åt Se’irs-borni og stelte deim upp til guder åt seg; han kasta seg ned for deim og kveikte offereld for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Då vart Herren brennande harm på Amasja, og han sende ein profet imot honom, som sagde til honom: «Kvifor held du deg til gudarne åt dette folket, dei som ikkje hev fria ut sitt eige folk or di hand?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Men då han tala soleis til honom, sagde han til honom: «Hev me gjort deg til rådgjevar for kongen? Haldt upp, so dei ikkje skal slå deg i hel!» Då heldt profeten upp og sagde: «Eg veit det er Guds råd at han vil ødeleggja deg, av di du hev gjort dette og ikkje høyrt på mi råd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Juda-kongen Amasja heldt råd, og so sende han bod til Israels-kongen Joas, son åt Joahaz, son åt Jehu, og sagde: «Kom, lat oss røyna kvarandre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Men Israels-kongen Joas sende dette svaret til Juda-kongen Amasja: «Tistelen på Libanon sende bod til cederen på Libanon og sagde: «Gjev dotter di til kona åt son min!» Men då flaug villdyri på Libanon yver tistelen og trakka honom ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du tenkjer: Eg hev vunne siger yver Edom!» Og det hev gjort deg ovmodig; vert roleg heime! Kvifor vil du leika med ulukka, til fall for deg sjølv og for Juda?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Men Amasja vilde ikkje høyra; for Gud laga det soleis, av di han vilde gjeva deim i fiendehand for di dei hadde søkt Edom-gudarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Då for Joas, Israels-kongen, upp, og dei fekk røyna kvarandre, han og Amasja, Juda-kongen, ved Bet-Semes, som ligg i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Og Juda-folket tapte for Israels-folket og rømde, kvar til sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Joas, Israels-kongen, tok Amasja, Juda-kongen, son åt Joas, son åt Joahaz, til fange ved Bet-Semes og førde honom til Jerusalem. Deretter reiv han ned eit stykke av muren kring Jerusalem frå Efraimsporten til Hyrneporten, so mykje som fire hundrad alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Og han tok alt gullet og sylvet og alle dei kjerald som fanst i Guds hus hjå Obed-Edom og i skattkamri i kongsgarden, og gislarne, og so snudde han heim att til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Juda-kongen Amasja Joasson livde femtan år etter Israels-kongen Joas Joahazson var dåen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Det som elles er å fortelja um Amasja frå fyrst til sist, det er uppskrive i Judas og Israels kongebok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Men frå den tid då Amasja sveik Herren, skipa dei ei samansverjing imot honom i Jerusalem, og då han rømde til Lakis, sende dei folk etter honom dit, og dei drap honom der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Dei lyfte honom upp på hesteryggen og gravlagde honom hjå federne i Judabyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'So tok heile folket i Juda Uzzia og gjorde honom til konge i staden for Amasja, far hans; han var sekstan år gamall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Det var han som bygde Elot og lagde det under Juda att, då kongen hadde lagt seg til kvile hjå federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sekstan år gamall var Uzzia då han vart konge, og tvo og femti år rådde han i Jerusalem. Mor hans heitte Jekilja og var frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Han gjorde det som rett var i Herrens augo, plent som Amasja, far hans, hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Han heldt ved med å søkja Gud so lenge Zakarja livde, han som skyna Guds syner. Og so lenge som han held seg til Herren, gav Gud honom lukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Han gjorde ei herferd imot filistarane og reiv ned bymurarne i Gat, Jabne og Asdod og bygde byar i Asdodbygderne og i Filistarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Gud hjelpte honom mot filistarane og mot dei arabarane som bur i Gur-Ba’al og mot me’unitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Ammonitarne svara skatt til Uzzia, og gjetordet um honom nådde til Egyptarland; for han vart overlag megtig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Uzzia bygde tårn i Jerusalem ved Hyrneporten, Dalporten og murhyrna og vigfeste deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Framleides bygde han tårn på heidi og hogg ut mange brunnar, for han hadde store buskaper både i låglandet og på høgsletta, og han hadde jordbruks- og vinhage-arbeidarar i fjellbygdi og i fruktlandet, for han var ein ihuga jordbrukar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzzia hadde ein krigsbudd her, som drog i herferd i flokkar etter teljing og mynstring ved riksskrivaren Je’uel og tilsynsmannen Ma’aseja og tilskipning av Hananja, som var ein av hovdingarne åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Det fulle talet av dei ættarhovdingarne som var stridsføre, var tvo tusund og seks hundrad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Under førarskapen deira stod det ein herstyrke på tri hundrad og sju tusund og fem hundrad våpnføre mann i full kraft til å hjelpa kongen mot fienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzzia budde heile heren med skjoldar, spjot, hjelmar, brynjor, bogar og slyngjesteinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'I Jerusalem gjorde han kunstigt uttenkte maskinor; dei vart uppsette på tårni og murtindarne og sende ut piler og store steinar. Soleis nådde gjetordet hans vida ikring, for han vart hjelpt på ein underfull måte til han vart megtig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Men då han var megtig vorten, vart hjarta hans ovmodigt, so han skjemde seg ut og gjorde urett mot Herren, sin Gud; han gjekk inn i Herrens hus og vilde kveikja røykjelse på røykjelsesaltaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Då gjekk presten Azarja etter honom, og med honom åtteti av Herrens prestar, djerve menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Dei steig fram mot kong Uzzia og sagde til honom: «Du hev ingen ting med å brenna røykjelse for Herren, Uzzia, men berre prestarne, sønerne åt Aron, som er vigde til å brenna røykjelse. Gakk ut or heilagdomen, for du hev forbrote deg, og det tener ikkje til æra for deg for Herren Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Uzzia stod med røykjelsesskåli i handi og skulde til å kveikja i røykjelsen, og han vart harm; men då vreiden hans bar laus imot prestarne, då slo spillsykja ut på panna hans, som han stod der framfyre prestarne attmed røykjelsesaltaret i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Og då øvstepresten Azarja og alle prestarne snudde seg imot honom, såg dei at han var spillsjuk på panna. Då førde dei honom straks burt, og sjølv skunda han seg med å ganga ut, då Herren hadde slege honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Soleis vart kong Uzzia spillsjuk til sin døyande dag, og han budde i eit hus for seg sjølv i spillsykja si; for han var utestengd ifrå Herrens hus. Og Jotam, son hans, var drottsete, og heldt rettargang for folket i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Det som elles er å fortelja um Uzzia frå fyrst til sist, hev profeten Jesaja, son åt Amos, skrive upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Og Uzzia lagde seg til kvile hjå federne sine, og dei gravla honom hjå federne hans på den marki der kongegravarne var; for dei kom i hug at han hadde vore spillsjuk. Og Jotam, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Fem og tjuge år gamall var Jotam då han vart konge, og sekstan år styrde han i Jerusalem. Mor hans heitte Jerusa Sadoksdotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Han gjorde det som rett var i Herrens augo, plent som Uzzia, far hans, hadde gjort, so nær som at han ikkje gjekk inn i Herrens hus. Men folket heldt ved og gjorde det som vondt var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Han bygde den øvre porten i Herrens hus, og bygde dessutan mykje på Ofelmuren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Han bygde upp byar i Judafjelli og borger og tårn i skogarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Han hadde krig med kongen yver Ammons-borni og vann yver deim, so at Ammons-borni svara skatt til honom i det året, tvo hundrad og femti våger sylv, tretti tusund tunnar kveite og tretti tusund tunnor bygg; det same svara Ammons-borni honom året etter og det tridje året med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Soleis vart Jotam megtig, av di han stødt førde si livsferd for Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Det som elles er å fortelja um Jotam, um alle krigarne hans og um alle fyretaki hans, er uppskrive i Israels og Judas kongebok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Fem og tjuge år var han då han vart konge, og sekstan år styrde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'So lagde Jotam seg til kvile hjå federne sine, og dei gravlagde honom i Davidsbyen, og Ahaz, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Tjuge år gamall var Ahaz då han vart konge, og sekstan styrde han i Jerusalem. Han gjorde ikkje det som rett var i Herrens augo, soleis som David, far hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'men han gjekk på vegen åt Israels-kongarne, og han laga jamvel støypte bilæte for Ba’als-gudarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Han kveikte offereld i Hinnomssonsdalen og vigde sønerne sine i elden etter den avstyggjelege seden åt dei folki som Herren hadde drive burt for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Han slagta og kveikte offereld på offerhaugarne og bakkarne og under kvart grønt tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Difor gav Herren, hans Gud, honom i henderne på syrarkongen, og dei vann siger yver honom og tok av folket hans ei stor mengd til fangar, som dei førde til Damaskus. Sameleis vart han gjeven i handi på Israels-kongen og leid ein stor usiger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekah, son åt Remalja, drap hundrad og tjuge tusund mann på ein dag i Juda, og det berre stridsføre folk, av di dei hadde svike Herren, sin fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Og Zikri, ein djerv kar frå Efraim, drap kongssonen Ma’aseja, drottseten Azrikam, og Elkana, den andre næst etter kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Israels-sønerne førde burt med seg tvo hundrad tusund fangar, konor, søner og døtter åt landsmennerne sine, og tok ifrå deim eit stort herfang, som dei førde til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Men ein av Herrens profetar som heitte Oded, og som livde der, han gjekk ut imot heren då han kom til Samaria og sagde til deim: «I harmen sin yver Juda hev Herren, dykkar fedregud, gjeve deim i dykkar vald; men de hev drepe deim med eit sinne som når til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Og no tenkjer de på å kua ned under dykk folki ifrå Juda og Jerusalem og gjera deim til trælarne og trælkvinnorne dykkar. Hev de ikkje sjølve skuld nok fyrr imot Herren dykkar Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Høyr difor på meg og send attende dei fangarne de hev teke ifrå brørne dykkar! for Herrens brennande harm er yver dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Då stod nokre av hovdingarne for Efraims-ætti, det var Azarja Johanansson, Berekja Mesillemotsson og Hizkia Sallumsson og Amasa Hadlaison, dei stod fram for deim som kom attende frå herferdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'og sagde til deim: «De må ikkje føra fangarne hit; for de tenkjer på å auka synderne og misgjerdi vår og føra skuld frå Herren yver oss, for me hev ei stor syndeskuld, og det er brennande harm yver Israel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Då slepte herfolki ifrå seg fangarne og herfanget framfor hovdingarne og heile lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Og dei mennerne som er nemnde, tok fangarne, klædde deim som var nakne ibland deim med det dei hadde til herfang, gav deim klæde og skor, gav deim mat og drikka, salva deim og sette deim som var utarma uppå asen og førde deim til Palmebyen, Jeriko, til brørne deira; og deretter snudde dei attende til Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'På den tid sende kong Ahaz bod til assyrarkongen um hjelp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'For attåt alt anna kom edomitarne og slo Juda og førde burt krigsfangar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Og filistarane fall inn i byarne i låglandet og i Sudlandet i Juda og tok Bet-Semes og Ajjalon og Gederot og Soko og bygderne kringum og Timna og bygderne kringum og Gimzo og bygderne kringum, og dei busette seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'For Herren vilde gjera Juda mjukt for Ahaz skuld, Israels-kongen, av di han gjorde Juda agelaust og var utru imot Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Men assyrarkongen, Tilgat-Pilneser, drog imot honom og for fiendsleg fram imot honom i staden for å hjelpa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'For Ahaz plyndra Herrens hus og huset åt kongen og hovdingarne og gav det til assyrarkongen, men det hjelpte honom ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Og den tid han var i naud, heldt han, kong Ahaz, fram med å vera utru imot Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Han ofra til gudarne i Damaskus, som hadde sigra yver honom, og sagde: «Gudarne åt syrarkongarne hev då hjelpt deim; til deim vil eg ofra, so dei kann hjelpa meg.» Men dei vart til fall for honom sjølv og for heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Ahaz samla dei tingi som fanst i Guds hus og slo deim sund; han stengde dørerne til Herrens hus og bygde seg altar ved kvart hyrna i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Og i kvar einaste by i Juda bygde han upp offerhaugar til å kveikja offereld på for framande gudar, og soleis harma han Herren, sin fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Det som elles er å fortelja um honom og heile hans ferd frå fyrst til sist, det er uppskrive i Judas og Israels kongebok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Og Ahaz lagde seg til kvile hjå federne sine, og dei gravla honom i byen, i Jerusalem; for dei vilde ikkje gravleggja honom i graverne åt Israels-kongarne. Og Hizkia, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Hizkia vart konge då han var tjuge år gamall, og ni og tjuge år styrde han i Jerusalem. Mor hans heitte Abia og var dotter åt Zakarja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Han gjorde det som rett var i Herrens augo, nett som David, far hans, hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'I den fyrste månaden i det fyrste styringsåret sitt let han opna dørerne til Herrens hus og sette deim i stand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'So let han prestarne og levitarne koma og stemnde deim saman på den opne plassen mot aust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Og han sagde til deim: «Høyr på meg, de levitar! No skal de helga dykk sjølve, og deretter skal de helga huset åt Herren, dykkar fedregud, og føra ureinskapen ut or heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'For federne våre hev vore utrugne og hev gjort det som vondt var for augo åt Herren, vår Gud; dei hev gjenge burt ifrå honom, hev vendt si åsyn burt ifrå Herrens hus og snutt ryggen til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Dei hev og stengt dørerne til forhalli, hev sløkt lamporne; ikkje kveikt røykjelse eller ofra brennoffer i heilagdomen åt Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Difor kom Herrens harm yver Juda og Jerusalem, og han gjorde deim til eit skræmsel, ei fæla og eit åtløgje, som de ser med eigne augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Til straff for dette er federne våre falne for sverdet, og sønerne og døtterne og konorne våre er hertekne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Difor hev eg no sett meg fyre at eg vil gjera ei pakt med Herren, Israels Gud, so hans brennande harm må venda seg ifrå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Lat det difor ikkje skorta dykk på ihuge, sønerne mine, for dykk hev Herren valt ut til å standa for hans åsyn og tena honom og vera tenarane hans og kveikja røykjelse for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Då reiste levitarne seg: Mahat Amasaison og Joel Azarjason av kahatitsønerne; av Merari-sønerne Kis Abdison, og Azarja Jehallelelsson, og av gersonitarne Joah Zimmason, og Eden Joahsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Av Elisafans-sønerne Simri og Je’uel, og av Asafs-sønerne Zakarja og Mattanja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'og av Hemans-sønerne Jehuel og Sime’i, og av Jedutuns-sønerne Semaja og Uzziel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Dei samla brørne sine, og dei helga seg, og sidan gjekk dei inn for å reinsa Herrens hus, so som kongen hadde bode etter fyresegnerne frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Og prestarne gjekk inn det indre av Herrens hus og reinsa det, og alt det ureine som dei fann i Herrens tempel, førde dei ut i tunet ved Herrens hus; der tok levitarne imot det og førde det ut i Kidronsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Den fyrste dagen i den fyrste månaden tok dei til å helga, og den åttande dagen i månaden gjekk dei inn i Herrens forhall og helga Herrens hus i åtte dagar, og den sekstande dagen i den fyrste månaden var dei ferdige med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'So gjekk dei inn til kong Hizkia og sagde: «No hev me reinsa heile Herrens hus, brennofferaltaret og alt som til høyrer, og skodebrødsbordet og alt som til høyrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Alle dei reidskaparne som kong Ahaz hev vanhelga i sin utruskap medan han var konge, deim hev me sett i stand og helga, og no stend dei framfyre Herrens altar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Tidleg um morgonen samla kong Hizkia dei øvste i byen og gjekk upp til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Og dei førde fram sju uksar, sju verar, sju lamb og sju geitebukkar til syndoffer for kongeriket og heilagdomen og Juda; og han baud Arons-sønerne, prestarne, å ofra deim på Herrens altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Dei slagta då uksane, og prestarne tok imot blodet og skvette det på altaret; so slagta dei verarne og skvette blodet på altaret, so slagta dei lambi og skvette blodet på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Sidan førde dei syndofferbukkarne fram for kongen og lyden, og dei lagde henderne sine på deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'so slagta prestarne dei og hadde blodet deira på altaret til syndoffer, til soning for heile Israel; for kongen hadde sagt at brennofferet og syndofferet skulde vera for heile Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Og han stelte upp levitarne i Herrens hus med cymblar, harpor og cithrar, soleis som David, Gad, sjåaren åt kongen, og profeten Natan hadde bode; for bodet um dette hadde Herren gjeve gjenom profetarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Levitarne stod med Davids spelgogner, og prestarne med lurarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Og Hizkia baud at brennofferet skulde ofrast på altaret, og då ofringi tok til, byrja songen for Herren, og lurarne, medan spelgognerne åt David, Israels konge, styrde songen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Då kasta heile lyden seg til jordi medan songen tona og lurarne let, og alt dette varde til ofringi var til endes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Då dei var ferdige med ofringi, fall kongen på kne og alle dei som var til stades med honom, og dei bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'So baud kong Hizkia og hovdingarne at levitarne skulde syngja Herrens lov med ordi åt David og sjåaren Asaf, og dei song lovsongen med fagnad og bøygde seg og bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Hizkia tok då til ords og sagde: «No hev de vigt dykk til Herren; kom då fram og før slagtofferi og lovofferi til Herrens hus!» Då førde lyden fram slagtoffer og lovoffer, og kvar ein som vart driven til det i hjarta sitt, førde fram brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Dei brennofferi som lyden førde fram, var sytti uksar, hundrad verar og tvo hundrad lamb; alle dei var brennoffer for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Og heilagofferi var seks hundrad uksar og tri tusund sauer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Men det var ikkje mange nok av prestarne til å flå alle brennofferi, og brørne deira, levitarne, hjelpte deim difor med det, til arbeidet var fullgjort, og til dess alle prestarne hadde helga seg; for levitarne synte ein ærlegare vilje til å helga seg enn prestarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Dessutan var det ei mengd med brennoffer og attåt deim feittstykki av takkofferi og dei drykkofferi som høyrde til brennofferi. Soleis fekk dei i stand tenesta i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Og Hizkia og heile folket gledde seg yver det som Gud hadde gjort for folket; for alt dette gjekk fyre seg med eit slag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Sidan sende Hizkia bod til heile Israel og Juda og skreiv ogso brev til Efraim og Manasse um at dei skulde koma til Herrens hus i Jerusalem og halda påskehelg for Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Kongen og hovdingarne hans og heile lyden i Jerusalem hadde halde råd um å høgtida påskehelgi i den andre månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'For dei kunde ikkje halda høgtidi den gongen, av di det ikkje var nok av prestarne som hadde helga seg, og folket ikkje var samla i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Det tykte kongen og heile lyden var rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Difor gjorde dei det vedtaket at dei sende eit upprop ikring i heile Israel ifrå Be’erseba til Dan um at dei skulde koma og halda påskehelgi for Herren, Israels Gud, i Jerusalem; for dei hadde ikkje høgtida henne so mangment som det var fyreskrive.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Det gjekk då snøggbod ut i heile Israel og Juda med brev frå kongen og hovdingarne hans, etter som kongen hadde bode, og sagde: «De Israels-søner, vend um att til Herren, Abrahams og Isaks og Israels Gud, so han må venda seg til den leivningen av dykk som hev kome seg undan or henderne åt assyrarkongarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Ver ikkje de som federne og brørne dykkar, som var utrogne mot Herren, deira fedregud, so han gjorde deim til ei rædsla, som det no ser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Ver no ikkje slike hardnakkar som federne dykkar! Gjev Herren handi og kom til heilagdomen hans, som han hev helga for alle tider, og ten Herren dykkar Gud, so hans brennande harm må venda seg burt ifrå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'For når de vender um til Herren, vil brørne og sønerne dykkar finna miskunn hjå deim som held deim fangar, og koma heim att til dette landet. For Herren, dykkar Gud, er nådig og miskunnsam og vil ikkje venda åsyni si burt ifrå dykk når de vender um til honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Snøggbodi drog ikring frå by til by i Efraims- og Manasselandet og like til Sebulon, men dei log åt deim og hædde deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Like vel var det nokre i Asser og Manasse og Sebulon som audmykte seg og drog til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'I Juda og verka Guds hand til å gjeva deim ein samheldig hug, so dei gjorde det som kongen og hovdingarne hadde bode etter Herrens ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Soleis samla det seg mykje folk i Jerusalem og høgtida søtebrødhelgi i den andre månaden; ein ovleg ålmuge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Dei tok seg fyre å få burt dei altari som fanst i Jerusalem, og tok burt offerstadarne og kasta deim i Kidronsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'So slagta dei påskelambet på den fjortande dagen i den andre månaden. Prestarne og levitarne skjemdest og helga seg og førde brennoffer til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Og dei stelte seg på plassarne sine, so som det var deim fyreskrive, etter lovi åt gudsmannen Moses, og prestarne skvette blodet, som dei fekk av levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'For det var mange i lyden som ikkje hadde vigt seg, og difor greidde levitarne med å slagta påskelambi for alle deim som ikkje var reine, so dei kunde vigja deim til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'For dei fleste av folket, mange ifrå Efraim, Manasse, Issakar og Sebulon, dei hadde ikkje vigt seg, men åt påske på onnor vis enn det var fyreskrive. Men Hizkia gjekk i forbøn for deim og sagde: «Herren, den gode, han tilgjeve');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'kvar den som hev lagt hugen sin på å søkja Gud Herren, sin fedregud, jamvel um han ikkje er rein, so som heilagdomen krev det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Og Herren bønhøyrde Hizkia og sparde folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Soleis høgtida dei Israels-borni som var til stades i Jerusalem søtebrødhelgi med stor fagnad i sju dagar; og kvar dag song levitarne og prestarne lovsonger med kraftige spelgogner for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Og Hizkia tala venleg til alle dei levitarne som hadde vore sers dugande i Herrens tenesta; og dei åt høgtidsofferi dei sju dagarne, og dei ofra takkoffer og lovprisa Herren, sin fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Men sidan samdest heile lyden um å høgtida endå sju dagar, og dei høgtida dei sju dagarne med fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'For Hizkia, kongen i Juda, gav lyden tusund uksar og sju stykke småfe, og hovdingarne gav lyden tusund uksar og ti tusund stykke småfe. Og prestarne helga seg i stor mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Og heile Juda-lyden gledde seg, og prestarne og levitarne og heile den lyden som var komen ifrå Israel og dei framande som var komne ifrå Israelslandet eller budde i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Og det var stor gleda i Jerusalem; for sidan dagarne åt Israels-kongen Salomo Davidsson hadde det ikkje hendt noko slikt i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Og levitprestarne stod upp og velsigna folket, og røysti deira vart høyrd; for bøni deira nådde fram til den heilage bustaden hans, til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Då dei no alt dette var slutt, drog alle dei israelitarne som var til stades ut til byarne i Juda og braut sund minnesteinarne, hogg ned Astarte-bilæti og reiv ned offerhaugarne og altari i heile Juda og Benjamin, og i Efraim og Manasse, til dei reint hadde gjort ende på deim. Og so snudde alle Israels-sønerne heim att, kvar til sin eigedom i byarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'So skipa Hizkia preste- og levitskifti, etter som dei høyrde til i det eine eller det andre skiftet, so at kvar og ein av prestarne og levitarne fekk si tenesta med brennofferi og takkoffer, å gjera tenesta med pris og lov i portarne til Herrens læger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Det som kongen gav av eiga si, vart bruka til å greida brennofferi, morgon- og kvelds-brennofferi og brennofferi på kviledagarne, nymånedagarne og høgtiderne, soleis som skrive stend i Herrens lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Og han baud deim av folket som budde i Jerusalem at dei skulde gjeva det som prestarne og levitarne skulde hava, so dei kunde halda fast ved Herrens lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'So snart dette vart kjent, kom Israels-sønerne med rikleg mengd av fyrstegrøda av korn, druvesaft, olje og honning og alt det andre avgrødet på marki, og sameleis tiend av alt i rikeleg mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Og dei israelitarne og Juda-mennerne som budde i Juda-byarne, kom og med tiend utav storfe og småfe, og dei kom med tiend av dei heilage gåvorne som var vigde til Herren, deira Gud, og lagde deim haug ved haug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'I den tridje månaden tok dei til å hauga i hop, og i den sjuande månaden var dei ferdige med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Hizkia og hovdingarne kom då og såg på haugarne, og dei prisa Herren og Israel, folket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Då so Hizkia spurde prestarne og levitarne um haugarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'svara øvstepresten Azarja av Sadoks hus honom: «Sidan dei tok til å føra offergåva til Herrens hus, hev me ete oss mette og leivt mykje att, for Herren hev velsigna folket sitt, so me hev fenge leivt all denne rikdomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Hizkia gav då det bodet at dei skulde laga til buder i Herrens hus; og då dei hadde laga slike,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'førde dei inn der avgrødet, tiendi og heilaggåvorne, alt på tru og æra. Tilsynet med dette vart gjeve til leviten Konanja og næmast under honom Sime’i, bror hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Og Jehiel, Azazja, Nahat, Asael, Jerimot, Jozabad, Eliel, Jismakja, Mahat og Benaja var tilsynsmenner jamsides med Konanja og Sime’i, bror hans, etter påbodet kong Hizkia og Azazja, den øvste i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Leviten Kore Jimnason, som var dørvaktar på øystre sida, hadde tilsyn med dei friviljuge gåvorne til Gud, og skulde skifta ut Herrens offergåvor og dei høgheilage gåvorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Under honmom vart sett Eden, Minjamin, Jesua, Semaja, Amarja og Sekanja; dei skulde vera i prestebyarne og skifta ut på tru og æra til brørne sine, både til store og små, etter dei skifti dei høyrde til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Her var frårekna dei av mannkyn som var ifrå tri år og uppetter, og som kom til Herrens hus etter som torvi var frå dag til dag og gjorde arbeidet sitt etter som tenesta deira var etter dei skifti dei høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Prestarne vart upptekne i lista etter ættgreinene sine, levitarne ifrå tjugeårsalderen og uppetter etter tenestskyldnaden sin, etter dei skifti dei høyrde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Det vart gjort soleis at dei vart upptekne med alle småborni sine, konorne, sønerne og døtterne sine, so mange dei var; for på tru og æra skulde dei styra med dei heilage tingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'For bymarkarne åt Arons-sønerne, prestarne, var det nokre namngjevne menner i kvar by som skifte til kvar karmann millom prestarne og deim utav levitarne som var upptekne i listorne, det som dei hadde rett til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Soleis gjorde Hizkia i heile Juda, og han gjorde det som godt og rett og sant var for Herren, sin Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Alle dei verki som han tok seg fyre i tenesta for Guds hus, i lovi og i bodet med det fyremål å søkja sin Gud, alle dei gjorde han av heile sitt hjarta, og han hadde lukka med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Etter desse hendingar og denne truskap kom assyrarkongen Sankerib og drog inn i Juda; der lægra han seg kring dei faste borger og tenkte å leggja deim under seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Då no Hizkia vart vis med at Sankerib var komen og hadde tenkt seg til å gjera åtak på Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'rådlagde han med hovdingarne og kjemporne sine um å teppa for vatnet i kjeldorne utanfor byen, og dei hjelpte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Det samla seg då ei mengd med folk som tepte kjeldorne og bekken som renn midt igjenom landet; for dei sagde: «Kvi skulde assyrarkongarne koma og finna mykje vatn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'So tok han mod og mannskap til seg og bygde upp heile den luten av muren som var nedbroten, og bygde radt upp til tårni, og ein annan mur bygde han utanfor; han vigfeste Millo i Davidsbyen og laga ei mengd kastevåpn og skjoldar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Og han sette herførarar yver krigsfolket, og då han hadde stemnt deim saman på plassen ved byporten, tala han til deim og moda deim upp og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '«Ver hugheile og modige, ottast ikkje og ræddast ikkje for assyrarkongen og heile den hopen han hev med seg; for med oss er det ein som er større enn den som er med honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Med honom er det ein arm av kjøt, men med oss er Herren, vår Gud, som vil hjelpa oss og føra krigarne våre.» Då leit folket på talen åt Juda-kongen Hizkia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Assyrarkongen Sanherib kringsette sjølv Lakis med heile hermagti si, men sende tenarane sine til Juda-kongen Hizkia og til alle Juda-mennerne i Jerusalem og let deim segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '«So segjer assyrarkongen Sankerib: «Kva er det de lit på, de som sit innestengde i Jerusalem?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Hizkia lokkar dykk til å døy av hunger og torste når han segjer: «Herren, vår Gud, skal berga oss or handi åt assyrarkongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Hev ikkje den same Hizkia teke burt offerhaugarne og altari hans og bode Juda og Jerusalem at dei berre skal kasta seg ned for eit einaste altar og berre kveikja offereld på det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Veit de då ikkje kva eg og federne mine hev gjort med folki frå alle land? hev vel folkegudarne i landi magta å berga landi sine or mi hand?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kven av alle gudarne hjå desse folki, som federne mine hev bannstøytt, er det som hev kunna berga folket sitt or mi hand, so dykkar Gud skulde kunna berga dykk or mi hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Lat difor ikkje Hizkia narra dykk og dåra dykk på denne måten! Tru honom ikkje! for ingen gud hjå noko folk eller rike hev magta å berga folket sitt ut or mi hand eller or handi på federne mine; kor mykje mindre skulde då dykkar gud kunna berga dykk or mi hand!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Og tenarane hans tala endå fleire ord imot Herren Gud og imot Hizkia, tenaren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Og han skreiv eit brev og til å hæda Herren, Israels Gud, og tala imot honom, og der stod det: «Likso lite som folkegudarne i landi hev berga folki sine or mi hand, likso lite skal Guden åt Hizkia berga sitt folk or mi hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Og dei ropa med høg røyst på jødisk mål til folket i Jerusalem, som stod på muren; dei vilde støkkja og skræma deim, so dei kunde take byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Og dei tala um Jerusalems Gud på same måten som um folkegudar på jordi, dei som er verk av mannehender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Då bad kong Hizkia og profeten Jesaja Amosson for denne saki skuld, og dei ropa til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Og Herren sende ein engel som øydde ut alle stridsmennerne, fyrstarne og hovdingarne i lægret åt assyrarkongen, so han laut snu heim att til landet sitt med spott og spe. Og då han gjekk inn i huset åt guden sin, var det nokre av hans eige avkjøme som hogg honom ned med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Soleis frelste Herren Hizkia og Jerusalems-folket or handi åt assyrarkongen Sanherib og or handi åt alle andre, og han gav deim fred på alle kantar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Og mange førde gåvor til Herren, til Jerusalem, og dyre gåvor til Juda-kongen Hizkia, og han vart høgvyrd hjå alle folki etter dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'I dei dagarne lagdest Hizkia i helsott. Då bad han til Herren, og han svara honom og gav honom eit underteikn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Men Hizkia lønte ikkje den velgjerningi som vart gjord imot honom, men hjarta hans vart ovmodigt, og difor kom det harm yver honom og Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Men han audmykte seg midt i sitt hjartans ovmod, og Jerusalems-folket med honom, då kom Herrens harm ikkje yver deim so lenge Hizkia livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Hizkia hadde ovstor rikdom og æra. Han bygde seg skattkammer for gull og sylv og glimesteinar og finangande kryddor og alle slags dyrverdige ting,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'dessutan forrådshus for avgrødet av korn og druvesaft og olje, fjøs for alle slags bufe, og kvier for buskaparne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Og han fekk seg byar og bufe og småfe i mengd; for Gud gav honom ovmykje gods.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Den same Hizkia tepte det øvre utlaupet av Gihonvatnet, og leidde vatnet ned mot vest til Davidsbyen. I alle tiltaki sine hadde Hizkia lukka med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Soleis og då sendebodi kom frå Babels-fyrstarne, som sende bod til honom og vilde høyra um det underteiknet som hadde hendt i landet, då gjekk Gud frå honom berre soleis, at han sette honom på prøva, so han kunde få fullrøynt huglyndet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Det som elles er å fortelja um Hizkia og godgjerningarne hans, er uppskrive i openberringi åt profeten Jesaja Amosson og i boki um Juda- og Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Og Hizkia lagde seg til kvile hjå federne sine, og dei gravlagde honom der som ein stig upp til graverne åt Davids-sønerne; og alle Juda-mennerne og Jerusalems-buarne synte honom stor æra ved avferdi hans. Og Manasse, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Tolv år gamall var Manasse då han vart konge, og fem og femti år styrde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Han gjorde det som vondt var i Herrens augo, etter den avstyggjelege seden hjå dei folki som Herren hadde rudt ut for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Han bygde upp att offerhaugarne som Hizkia, far hans, hadde rive ned, og sette upp altari for Ba’als-gudarne og gjorde Astarte-bilæte og kasta seg ned for og tente heile himmelheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Og han bygde altar i Herrens hus, endå Herren hadde sagt: «I Jerusalem skal namnet mitt vera æveleg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Og han bygde altar for heile himmelheren i båe tuni kring Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Han vigde sønerne sine i elden i Hinnomssons-dalen og for med spådom og trolldom og runing og fekk seg tinga folk til å mana draugar og spåvette; han gjorde mykje som vondt var i Herrens augo og harma honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Og avgudsbilætet som han hadde gjort, sette han upp i Guds hus, som Gud hadde sagt um til David og Salomo, son hans: «Til dette huset og til Jerusalem, som eg hev valt ut millom alle Israels ætter, vil eg festa namnet mitt i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Og eg vil ikkje meir lata Israel fara burt ifrå det landet som eg etla åt federne dykkar, berre dei agtar på å halda alt det som eg hev bode deim, etter heile lovi og bodi og rettarne som dei fekk ved Moses.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Men Manasse førde Juda og Jerusalems-buarne til å stella seg verre enn dei folki som Herren hadde øydt ut for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Då tala Herren til Manasse og folket hans, men dei agta ikkje på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'So let Herren herførarne åt assyrarkongen koma yver deim, og dei fanga Manasse med krokar, lagde honom i koparlekkjor og førde honom til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Men då han var i naud, bad han Herren, sin Gud, um nåde, og han audmykte seg djupt for fedreguden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Og då han bad til honom, let han seg blidka og høyrde bøni hans og førde honom attende til Jerusalem til kongedømet hans. Då kom Manasse i hug at Herren er Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Sidan bygde han ein ytre mur for Davidsstaden vestanfor Gihon i dalen og burt imot Fiskeporten, so han gjekk ikring Ofel; og gjorde honom svært høg. I alle borgbyarne i Juda sette han herførarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Han førde burt dei framande gudarne og avgudsbilætet ifrå Herrens hus og alle dei altari som han hadde bygt på det berget der Herrens hus stod og i Jerusalem, og han kasta deim utanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Derimot reiste upp att Herrens altar, og han ofra takkoffer og lovoffer på det; og han baud Juda at dei skulde tena Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Men folket heldt ved med å ofra på offerhaugarne, men einast til Herren, deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Det som elles er å fortelja um Manasse, um bøni hans til sin Gud og ordi åt dei sjåarane som tala til honom i namnet åt Herren, Israels Gud, det er uppskrive i krønikeboki åt Israels-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Og um bøni hans, og korleis han vart bønhøyrd, og heile syndi og utruskapen hans og dei staderne der han bygde upp offerhaugar og sette upp Astarte-stolparne og avgudsbilæti fyrr han audmykte seg, det er uppskrive i krønikeboki åt Hozai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Og Manasse lagde seg til kvile hjå federne sine, og dei gravlagde honom ved huset hans, og Amon, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Tvo og tjuge år gamall var Amon då han vart konge, og tvo år styrde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Han gjorde det som vondt var i Herrens augo, liksom Manasse, far hans; og han ofra til alle dei bilæti som Manasse, far hans, hadde gjort, og han tente deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Han audmykte seg ikkje for Herrens åsyn, soleis som Manasse, far hans, gjorde, men han, Amon, leste på seg stor skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Tenarane hans svor seg saman mot honom og drap honom i huset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Men landsfolket drap alle deim som hadde svore seg saman imot kong Amon, og landsfolket tok Josia, son hans, til konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Åtte år gamall var Josia då han vart konge, og eitt og tretti år styrde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Han gjorde det som rett var i Herrens augo, og han fylgde i fotefari åt David, far sin, og tok ikkje or leidi, korkje til høgre eller vinstre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'I det åttande styringsåret sitt, då han endå var ein ungdom, tok han til å søkja Gud åt David, far sin, og i det tolvte året tok han til å reinsa Juda og Jerusalem for offerhaugarne og Astarte-bilæti og dei uthogne og støypte bilæti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Dei reiv ned Ba’als-altari med han såg på det; solstolparne som var ovanpå deim, hogg han ned, og Astarte-bilæti og dei uthogne og støypte bilæti slo han sund og knasa og strøydde deim ut på graverne åt deim som hadde ofra til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Og beini åt prestarne brende han på altari deira. Soleis reinsa han Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Og i byarne i Manasse og Efraim og Simeon og radt til Naftali røkte han etter i husi deira rundt ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'og han braut ned altari, slo sund og krasa Astarte-bilæti og gudebilæti og hogg ned solstolparne i heile Israels land; so snudde han heim att til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'I det attande styringsåret sitt, medan han heldt på å reinsa landet og huset, sende han Safan Asaljason og Ma’aseja, byhovdingen, og kanslaren Joah Joahazson til å setja i stand huset åt Herren, hans Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Då dei kom til øvstepresten Hilkia, gav dei ut det sylvet som var ført til Guds hus; det var det som levitarne, dørstokkvakti, hadde samla inn frå Manasse og Efraim og heile resten av Israel og frå heile Juda og Benjamin og Jerusalems-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Dei gav det til arbeidsformennerne som hadde tilsynet med Herrens hus; og arbeidsformennerne som arbeidde i Herrens hus, bruka det til å vøla på og setja i stand huset;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'for dei gav det til timbremennerne og murarane for at dei skulde kjøpa hoggen stein og timber til bjelkar og timbra upp dei husi som Juda-kongarne hadde øydelagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Mennerne arbeidde trufast, og tilsynet med deim var gjeve til levitarne Jahat og Obadja av meraritarne, og Zakarja og Mesullam av kahatitarne, so dei skulde vera formenner, og alle dei levitar som kunde handsama spelgogner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Dei hadde og tilsynet med berarane og sagde alle arbeidarne fyre ved kvart einskild arbeid. Og nokre av levitarne var skrivarar og formenner og dørvaktarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Men då dei tok fram dei pengarne som var innkomne til Herrens hus, fann presten Hilkia boki med Herrens lov, som var gjevi ved Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Og Hilkia sagde til riksskrivaren Safan: «Eg hev funne lovboki i Herrens hus!» Og han gav boki til Safan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Og Safan bar henne til kongen, og gav dessutan melding til honom og sagde: «Alt det som er pålagt tenarane dine, det gjer dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Dei hev tømt ut det sylvet som fanst i Herrens hus og gjeve det til formennerne og arbeidsfolket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'So melde riksskrivaren Safan til kongen sagde: «Presten Hilkia hev gjeve meg ei bok.» Og Safan las upp av henne for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Men då kongen fekk høyra ordi i lovi, reiv han sund klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Og kongen baud Hilkia og Ahikam Safansson og Abdon Mikason og riksskrivaren Safan og kongstenaren Asaja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '«Gakk og spør Herren for meg og for deim som er att i Juda og Israel um det som stend i denne boki som er funni. Stor er Herrens harm, som er utrend yver oss, av di federne våre ikkje hev lydt Herrens ord og gjort etter alt det som stend skrive i denne boki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'So gjekk Hilkia og dei andre som kongen sagde til, til profetkvinna Hulda, kona åt klædehandlaren Sallum, son åt Tokhat, son åt Hasra; ho budde i ny-byen i Jerusalem, og dei tala med henne um dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ho svara deim: «So segjer Herren, Israels Gud: Seg til den mannen som sende dykk til meg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'So segjer Herren: «Sjå, eg sender ulukka yver denne staden og yver folket her, alle dei forbanningarne som er skrivne i den boki som dei hev lese upp for Juda-kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'til straff for di dei hev vend seg frå meg og kveikt offereld for andre gudar og harma meg med alle sine verk; harmen min skal renna ut yver denne staden og skal ikkje slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Men til Juda-kongen, som sende dykk til å spyrja Herren, skal de segja: So segjer Herren, Israels Gud, um dei ordi som du høyrde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Av di hjarta ditt vart mjukt, og du bøygde deg for Gud då du høyrde ordi hans mot denne staden og folket her, av di du audmykte deg for mi åsyn og reiv sund klædi dine, og gret for mi åsyn, so hev eg og bønhøyrt, segjer Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'So vil eg då samla deg til federne dine, so du kann samlast med deim i gravi di i fred; og augo dine skal sleppa sjå all den ulukka som eg vil føra yver denne staden og folket som bur her.»» Og dei kom att til kongen med dette svaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Då sende kongen bod og stemnde saman alle dei øvste i Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Og kongen gjekk upp til Herrens hus, og alle Juda-mennerne og Jerusalems-buarne fylgde honom, og prestarne og levitarne og heile folket, frå den minste til den største; og han las upp for deim alt det som stod i paktboki som dei hadde funne i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Kongen steig fram på plassen sin og gjorde den pakti for Herrens åsyn at han vilde fylgja Herren og halda bodi og fyresegnerne og loverne hans av alt sitt hjarta og all sin hug og setja i verk dei paktordi som var skrivne i denne boki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Og han let deim ganga inn i pakti, som fanst i Jerusalem og Benjamin, og alle Jerusalems-buarne gjorde etter pakti med Gud, deira fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Og Josia fekk burt all styggedomen frå alle dei landi som høyrde til Israels-sønerne, og han nøydde alle som fanst i Israel til å tena Herren, sin Gud. So lenge som han livde, vende dei seg ikkje burt i frå Herren, deira fedregud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Josia heldt påskehelg for Herren i Jerusalem, og dei slagta påskelambet på den fjortande dagen i fyrste månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Han sette prestarne til det dei skulde taka vare på, og styrkte deim til tenesta i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Og han sagde til levitarne, som lærde heile Israel, og som var vigde til Herren: «Set den heilage kista i det huset som Salomo bygde, son åt David, Israels konge; det tarv ikkje bera henne på herdarne. Ten difor Herren, dykkar Gud, og Israel, folket hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Gjer dykk ferdige etter ættgreinerne dykkar, i skifti dykkar, so som David, Israels konge, hev fyreskrive, og etter fyreskrifti åt Salomo, son hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Og statt i heilagdomen etter flokkarne av ættgreinerne åt brørne dykkar, lækfolket, soleis at det hvert eit skift av ei levit-ættgrein for kvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Og slagta so påskelambi og helga dykk og laga det til for brørne dykkar, so det gjer etter Herrens ord ved Moses!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Josia gav tretti tusund stykke småfe til ålmugen, lamb og kid, alt saman til påskeoffer for alle deim som fanst der, og tri tusund stykke storfe; dette var av eigedomen åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Og hovdingarne hans gav friviljugt til folket, til prestarne og levitarne; Hilkia og Zakarja og Jehiel, som var dei øvste i Guds hus, gav prestarne tvo tusund seks hundrad lamb og kid til påskeoffer, og tri hundrad stykke storfe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Konanja og Semaja og Netanel, brørne hans, og Hasabja og Je’iel og Jozabad, levitfyrstane, gav levitarne fem tusund lamb og kid til påskeoffer og fem hundrad stykke storfe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Soleis fekk dei tenesta i fast skikk, og prestarne stod på sin stad og levitarne etter sine skift, so som kongen hadde bode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Dei slagta påskelambi, og prestarne skvette blodet som dei fekk av deim, og levitarne flådde dyri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'So skilde dei frå brennofferi og gav deim til dei ymse ættgrein-flokkarne av ålmugen, so dei kunde ofra til Herren, som det er fyreskrive i Moseboki; og sameleis med storfeet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Påskelambi steikte dei i elden, som fyreskrive var, og offerstykki koka dei i grytor, kjelar og skålar og skunda seg med deim til ålmugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'So laga dei åt seg sjølve og prestarne; for prestarne, Arons-sønerne, hadde arbeid like til um natti med å ofra brennofferi og feittstykki, og difor laga levitarne til åt seg sjølve og prestarne, Arons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Songarane, Asafs-sønerne, stod på plassen sin, som David, Asaf, Heman og Jedutun, sjåaren åt kongen, hadde bode, og dørvaktarane ved kvar sin port; dei turvte ikkje ganga ifrå tenesta; for levitarne, brørne deira, laga til åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Soleis sette dei heile tenesta for Herren fast skikk på den dagen, med di dei heldt påskehelg og ofra brennoffer på Herrens altar, so som kong Josia hadde bode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Og dei Israels-borni som var tilstades, heldt den gongen påskehelgi og søtebrødhelg i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Ei sovori påskehelg som denne var det ikkje halde i Israel sidan profeten Samuels dagar, og ingen av Israels-kongarne hadde halde ei sovori påskehelg som den Josia og prestarne og levitarne og dei Juda- og Israels-mennerne som var til stades, og Jerusalems-buarne høgtida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Denne påskehelgi vart haldi i det attande styringsåret åt Josia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Etter alt dette, då Josias hadde fenge i stand huset, drog egyptarkongen Neko upp og vilde strida ved Karkemis ved Frat, og Josia drog ut imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Men han skikka sendebod til honom og sagde: «Kva hev eg med deg å gjera, Juda-konge? Det er ikkje imot deg eg kjem i dag, men mot ervefienden min; og Gud hev sagt at eg skal skunda meg. Haldt upp med å tråssa Gud som er med meg, so han ikkje skal tyna deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Men Josia snudde ikkje ifrå honom, men klædde seg ut og vilde gjeva seg i strid med honom, han høyrde ikkje på Nekos ord ifrå Guds munn. Og det kom til strid på Megiddosletta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Då råka bogeskyttarane kong Josia, og kongen sagde til tenarane: «Før meg burt! for eg er hardt såra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Tenarane hans bar honom då burt ifrå vogni og køyrde honom på den andre vogni hans og førde honom til Jerusalem, og der døydde han. Dei gravlagde honom i graverne åt federne hans, og heile Juda og Jerusalem syrgde yver Josia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremia song ein syrgjesong um Josia, og alle songarane og songmøyarne tala i syrgjesongarne sine um Josia, som dei gjer den dag i dag; det vart fast skikk i Israel å syngja desse kvædi, og dei finst uppskrivne millom Syrgjesongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Det som elles er å fortelja um Josia og dei gudlege gjerningarne som han gjorde etter det som er fyreskrive i Herrens lov,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'og soga hans frå fyrst til sist, det er uppskrive i boki um Israels- og Juda-kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Folket i landet tok Joahaz Josiason og gjorde honom til konge i Jerusalem i staden for far hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Tri og tjuge år gamall var Joahaz då han vart konge, og tri månader styrde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Men egyptarkongen sette honom av frå styret i Jerusalem og let landet bøta tvo hundrad og femti våger sylv og tvo og ein halv våg gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Og egyptarkongen gjorde Eljakim, bror hans, til konge yver Juda og Jerusalem, og han brigda namnet hans til Jojakim, Joahaz, bror hans derimot, tok Neko og førde til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Fem og tjuge år gamall var Jojakim då han vart konge, og elleve år styrde han i Jerusalem. Han gjorde det som vondt var for Herren, hans Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Nebukadnessar, kongen i Babel, drog upp imot honom, og batt honom med koparlekkjor og vilde føra honom til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Og Nebukadnessar førde nokre av kjeraldi i Herrens hus til Babel og sette deim upp i templet sitt i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Det som elles er å fortelja um Jojakim og dei styggetingi som han gjorde, og anna vondt som fanst hjå honom, det er uppskrive i boki um Israels- og Juda-kongarne; Jojakin, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Attan år gamall var Jojakin då han vart konge, og tri månader og ti dagar styrde han i Jerusalem. Han gjorde det som vondt var i Herrens augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Ved årsskiftet sende kong Nebukadnessar folk og førde honom til Babel saman med dei dyraste kjeraldi ifrå Herrens hus; og han gjorde Sidkia, bror hans, til konge yver Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Eitt og tjuge år gamall var Sidkia då han vart konge, og elleve år styrde han i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Han gjorde det som var vondt i Herrens, hans Guds, augo; han audmykte seg ikkje for profeten Jeremia som tala ord frå Herrens munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Attpå gjorde han uppreist imot kong Nebukadnessar, som hadde teke honom i eid ved Gud; og han var ein stivnakke og gjorde hjarta sitt hardt, so han umvende seg ikkje til Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Alle hovdingarne bland prestarne og folket gjorde mykjen utruskap og for med same styggedomen som heidningarne og sulka til Herrens hus, som han hadde helga i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Herren, deira fedregud, sende fyretolor til deim seint og tidleg med sendebodi sine, av di han tykte synd i folket sitt og bustaden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Men dei spotta sendebodi for Gud, hædde ordi hans og svivyrde profetarne hans til dess Herrens harm reiste seg soleis imot folket hans, at det ikkje lenger var nokor botevon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Han sende kaldæarkongen imot deim, og han drap deira unge mannskap med sverd i det heilage huset deira og sparde korkje unggut eller ungmøy, gamall eller gråhærd. Alt gav han i hans hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Alle kjeraldi i Guds hus, både store og små, skattarne i Herrens hus og skatterne åt kongen og hovdingarne hans, alt saman førde han til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Dei brende upp Guds hus og reiv ned Jerusalems-muren, brende upp alle slotti der og øydelagde alle dei dyrverdige tingi som fanst der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Deim som sverdet hadde leivt, førde han fangar til Babel, og der vert dei trælar for honom og sønerne hans til dess Persarriket kom til magti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'so Herrens ord i Jeremias munn skulde verta uppfyllt, til dess landet fekk njota si kvild; alt med det låg i øyde, fekk det kvila til dess sytti år var lidne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Men i det fyrste året åt Kyrus, kongen i Persia, vekte Herren hugen i persarkongen Kyrus - for Herrens ord i Jeremias munn skulde nå sitt endemål - og han let ropa ut i alt sitt rike, og sende brev ikring med sovori kunngjering:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '«So segjer Kyrus, kongen i Persia: «Alle kongerike på jordi hev Herren, Gud i himmelen, gjeve meg, og han hev lagt på meg at eg skal byggja honom eit hus i Jerusalem i Juda. Er det nokon millom dykk av alt hans folk, so vere Herren, hans Gud, med honom, og han drage upp dit!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'I det fyrste åt Kyrus, kongen Persia, vekte Herren hugen i perserkongen Kyrus - for Herrens ord i Jeremias munn skulde nå sitt endemål - og han let ropa ut i alt sitt rike og sende brev i kring med sovori kunngjering:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '«So segjer Kyrus, kongen i Persia: «Alle kongerike på jordi hev Herren, Gud i himmelen, gjeve meg, og han hev lagt på meg at eg skal byggja honom eit hus i Jerusalem i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Er det nokon millom dykk av alt hans folk, so vere hans Gud, med honom, og han drage upp til Jerusalem i Juda og byggje hus åt Herren, Israels Gud! Det er den Gud som bur i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Og kvar helst nokon endå er att og bur framand på ein stad, skal folket der hjelpa honom til med sylv og gull, lausøyre og bufe, umfram det som dei godviljugt gjev til gudshuset i Jerusalem.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Då gjorde ættarhovdingarne i Juda og Benjamin seg reiduge til å fara, og det same gjorde prestarne og levitarne, alle dei som Gud vekte hugen i, dei vilde fara upp og byggja Herrens hus i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Og alle grannarne deira hjelpte deim til med gåvor: sylv og gull, lausøyre og bufe og dyrverdige gåvor, umfram alt det som dei sjølve gav godviljugt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Kyrus sjølv, kongen, gav frå seg alle dei kjerald som Nebukadnessar hadde teke burt frå Jerusalem og sett inn i huset åt sin gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Desse gav no Kyrus, persarkongen, frå seg til Mitredat, som var skattmeister, og han talde deim for Sesbassar, som var hovding yver Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Talet på desse kjerald var: Tretti gullfat, tusund sylvfat og ni og tjuge andre offerkjerald,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'tretti gullskålar og fire hundrad og ti sylvskålar av ringare slag og tusund andre kjerald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Kjeraldi av gull og sylv var i alt fem tusund og fire hundrad. Alt dette førde Sesbassar med seg då dei burtførde for upp frå Babel til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Her kjem talet på dei fylkesbuarne som for ut or utlægdi, dei som Babel-kongen Nebukadnessar hadde ført burt til Babel, og som no for heim att til Jerusalem og Juda, kvar til sin by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Dei fylgde Zerubbabel og Jesua, Nehemia og Seraja, Re’elaja og Mordekai, Bilsan og Mispar, Bigvai og Rehum og Ba’ana. - Dette er manntalet yver Israels-lyden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paros-sønerne, tvo tusund eit hundrad og tvo og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sefatja-sønerne, tri hundrad og tvo og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Arahs-sønerne, sju hundrad og fem og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Pahat-Moabs-sønerne, av Jesua- og Joabs-sønerne, tvo tusund åtte hundrad og tolv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elams-sønerne, eit tusund tvo hundrad og fire og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Zattu-sønerne, ni hundrad og fem og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Zakkai-sønerne, sju hundrad og seksti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Bani-sønerne, seks hundrad og tvo og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebai-sønerne, seks hundrad og tri og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Azgads-sønerne, eit tusund tvo hundrad og tvo og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikams-sønerne, seks hundrad og seks og seksti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvai-sønerne, tvo tusund og seks og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adins-sønerne, fire hundrad og fire og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Aters-sønerne av Hizkia-ætti, åtte og nitti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Besai-sønerne, tri hundrad og tri og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jora-sønerne, hundrad og tolv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hasums-sønerne, tvo hundrad og tri og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbars-sønerne, fem og nitti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Betlehems-sønerne, hundrad og tri og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'mennerne frå Netofa, seks og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'mennerne frå Anatot, hundrad og åtte og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Azmavets-sønerne, tvo og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Kirjat-Arims- og Kefira- og Be’erots-sønerne, sju hundrad og tri og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Rama- og Geba-sønerne, seks hundrad og ein og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'mennerne frå Mikmas, hundrad og tvo og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'mennerne frå Betel og Aj, tvo hundrad og tri og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Nebo-sønerne, tvo og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Magbis-sønerne, hundrad og seks og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'den andre Elams søner, eit tusund tvo hundrad og fire og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Harims-sønerne, tri hundrad og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Lods- og Hadids- og Ono-sønerne, sju hundrad og fem og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Jeriko-sønerne, tri hundrad og fem og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Sena’a-sønerne, tri tusund seks hundrad og tretti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Av prestarne: Jedaja-sønerne av Jesua-ætti, ni hundrad og tri og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immers-sønerne, eit tusund og tvo og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashurs-sønerne, eit tusund tvo hundrad og sju og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Harims-sønerne, tusund og syttan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Av levitarne: Jesua- og Kadmiels-sønerne av Hodavja-sønerne, fire og sytti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Av songararne: Asafs-sønerne, hundrad og åtte og tjuge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Av dørvaktar-sønerne: Sallums-sønerne, Aters-sønerne, Talmons-sønerne, Akkubs-sønerne, Hatita-sønerne, Sobai-sønerne, i alt hundrad og ni og tretti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Av tempelsveinarne: Siha-sønerne, Hasufa-sønerne, Tabbaots-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Keros-sønerne, Siaha-sønerne, Padons-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebana-sønerne, Hagaba-sønerne, Akkubs-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hagabs-sønerne, Samlai-sønerne, Hanans-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddels-sønerne, Gahars-sønerne, Reaja-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Resins-sønerne, Nekoda-sønerne, Gazzams-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Uzza-sønerne, Paseahs-sønerne, Besai-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asna-sønerne, Me’unims-sønerne, Nefisims-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbuks-sønerne, Hakufa-sønerne, Harhurs-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Basluts-sønerne, Mehida-sønerne, Harsa-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkos-sønerne, Sisera-sønerne, Tamahs-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Nesiahs-sønerne, Hatifa-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Av sønerne åt Salomo-sveinarne: Sotai-sønerne, Hassoferets-sønerne, Peruda-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Ja’ala-sønerne, Darkons-sønerne, Giddels-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sefatja-sønerne, Hattils-sønerne, Pokeret-Hassebajims-sønerne, Ami-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Alle tempelsveinarne og sønerne åt Salomo-sveinarne var i alt tri hundrad og tvo og nitti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Frå Tel-Melah og Tel-Harsa, Kerub og Addan og Immer for dei ut dei som her skal nemnast; men dei kunde ingi greida gjeva um federne sine og ætti, um dei i det heile høyrde Israels-folket til; det var;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delaja-sønerne, Tobia-sønerne og Nekoda-sønerne, seks hundrad og tvo og femti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'og av prestesønerne: Habaja-sønerne, Hakkos-sønerne, sønerne åt Barzillai, han som hadde teke ei av døtterne åt Gileads-mannen Barzillai til kona og fekk namn etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Desse leita etter ættetavlorne sine, men kunde ikkje finna deim; difor vart dei kjende uverdige til å vera prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Jarlen dømde at dei ikkje måtte eta av det høgheilage fyrr det stod fram ein prest som hadde urim og tummim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Heile lyden til var i alt tvo og fyrti tusund tri hundrad og seksti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'umfram trælarne og trælkvinnorne; talet på deim var sju tusund tri hundrad og sju og tretti. Dertil kom tvo hundrad songarar, karar og kvende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Dei hadde sju hundrad og seks og tretti hestar, tvo hundrad og fem og fyrti muldyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'fire hundrad og fem og tretti kamelar og seks tusund sju hundrad og tjuge asen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Då dei kom fram til Herrens hus i Jerusalem, gav nokre av ættarhovdingarne godviljugt ei gåva til gudshuset, so det kunde verta uppbygt att på den gamle staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Kvar av deim lagde i byggjekassa, etter som han hadde råd til, og det kom inn tri hundrad tusund dalar i gull og fem og tjuge tusund dalar i sylv, dertil eit hundrad prestekjolar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Prestarne og levitarne og nokre av lyden, songarane, dørvaktarane og tempelsveinarne, sette då bu i sine byar, og heile Israel elles busette seg kvar i sin by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Då den sjuande månaden kom, og Israels-sønerne budde i sine byar, samla dei seg i Jerusalem alle som ein mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Og Jesua Josadaksson og prestarne, brørne hans, og Zerubbabel Sealtielsson og hans brør tok til å byggja altaret åt Israels Gud, so dei kunde få ofra brennoffer på det, soleis som det er fyreskrive i lovi åt gudsmannen Moses.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Dei sette altaret på den staden det fyrr hadde vore; for dei hadde fenge rædsla i seg for folki som budde i landet. Og dei ofra brennoffer til Herren på alteret, brennoffer morgon og kveld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'So heldt dei lauvhyttehelg etter som det er fyreskrive, og bar fram brennoffer dag for dag etter sitt tal, so mange som det var fastsett for kvar dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Sidan ofra dei det dagvisse brennofferet og dei offer som høyrde til nymånaderne og alle Herrens heilage høgtider; sameleis kvar gong nokon kom godviljugt og bar fram offer til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Frå fyrste dagen i sjuande månaden tok dei til å ofra brennoffer til Herren; fyrr dei endå hadde lagt grunnen til Herrens tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Sidan gav dei steinhoggarane og timbremennerne pengar, og til Sidons-sønerne og Tyrus-mennerne gav dei matvaror og drikkevaror og olje, for dei skulde føra cedertre frå Libanon sjøvegen til Jafo, etter ei fullmagt som dei hadde fenge hjå Kyrus, persarkongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'I andre månaden i Året etter dei var komne heim til Guds hus i Jerusalem, tok dei til med verket. Zerubbabel Sealtielsson og Jesua Josadaksson og dei andre prestarne og levitarne, brørne deira, og elles alle dei som var komne til Jerusalem frå utlægdi, sette levitar som var tjuge år gamle og deryver, til å hava tilsyn med arbeidet på Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Og Jesua med sønerne og brørne sine, og Kadmiel med sine søner, Juda-sønerne, alle som var sette til å hava uppsyn med deim som bygde på Guds hus, sameleis Henadads-sønerne med sine søner og brør, levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Bygningsmennerne lagde grunnvollen til Herrens hus, og imedan stod prestarne uppyver med lurar og fullt skrud, og levitarne, Asafs-sønerne, stod med cymblar; dei vilde prisa Herren soleis som David, Israels-kongen, hadde lært deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Dei song lov og takk til Herren, av di han er god og hans miskunn mot Israel varer æveleg. Og alt folket sette i med høge fagnadrop, og prisa Herren av di grunnvollen var lagd til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Men mange av prestarne og levitarne og ættarhovdingarne, dei gamle som hadde set det fyrre huset, gret høgt då dei såg på at grunnvollen til dette huset vart lagd; men mange var so glade at dei ropa høgt av fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Det var rådlaust for folket å skilja frå kvartanna fagnadropi og folkegråten; for folket sette i med velduge fagnadrop, og omen av dette lyddest langan leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Uvenerne til Juda og Benjamin fekk høyra at dei som var komne heim or utlægdi, heldt på å byggja eit tempel åt Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Då gjekk dei til Zerubbabel og til ættarhovdingarne og sagde: «Lat oss få vera med dykk og byggja; me held oss til dykkar Gud likso vel som de, og til honom hev me ofra alt sidan den tid Asarhaddon var konge i Assyria og førde oss hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Men Zerubbabel og Jesua og dei andre ættarhovdingarne for Israel sagde til deim: «Det sømer seg ikkje at de skal vera med oss og byggja eit hus åt vår Gud; me vil sjølve hjelpast åt og byggja hus åt Herren, Israels Gud, soleis som Kyrus, persarkongen, hev sagt oss fyre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Folket i landet skræmde då Juda-folket av og gjorde deim huglause, so dei slutta med byggjingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Dei leigde folk til å leggja meinråder mot deim, og tiltaket vart stogga i all den tid som Kyrus var konge, alt til Darius hadde teke til å styra i Persia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Då Ahasveros hadde vorte konge, i den fyrste tid han styrde, då skreiv dei brev og klaga på ibuarane i Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'I Artahsastas tid skreiv Bislam og Mitredat og Tabe’el og dei andre embætsbrørne hans til Artahsasta, konge i Persia. Brevet var skrive med syrisk skrift og umsett på syrisk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rådsherren Rehum og skrivaren Simsai skreiv eit brev mot Jerusalem til kong Artahsasta, og innholdet var dette:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Dengong: Rådsherren Rehum og skrivaren Simsai og dei andre embetsbrørne deira, dei frå Dina og Afarsatka, Tarpela og Persia, Erek og Babel, Susan, Deha og Elam');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'og dei andre folki som den store og velduge Asnappar hadde ført burt og late bu i Samaria-byen og det andre landet på hi sida elvi, og so burtetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Dette er avskrift av det brevet dei sende til kong Artahsasta: «Tenarane dine, mennerne på hi sida elvi og so burtetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Det skal kongen vita at dei jødarne som for ifrå deg og hit til oss, er no komne til Jerusalem, og der held dei på å byggja upp denne vonde uprørsbyen og setja murarne i stand og stella på grunnvollarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'No vil me gjera det kunnigt for kongen, at skal denne byen verta uppatt-bygd og murarne fullførde, so vil folket der korkje leggja skattar eller gjeva toll eller vegpengar, og det vil verta til meins for innkomorne åt kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Sidan no me et salt frå kongsgarden, so sømer det seg ikkje at me skal sjå på den skaden som her vert lagd for kongen, difor sender me brev bod og let kongen vita dette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'so det kann verta etterset i sogeboki åt federne dine; der vil du sjå og læra at denne byen hev vore ein upprørsby frå gamalt, til stort mein for kongar og land, og at der hev vore skapt mykje uro; difor er og byen lagd i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Det let me kongen vita, at vert denne byen bygd upp og murane fullførde, då er det ute med landeigni di på andre sida elvi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Kongen sende brev attende til rådsherren Rehum og skrivaren Simsai og dei andre embætsbrørne deira som budde i Samaria og andre herad på hi sida elvi, og i brevet stod det: «Heil og sæl! og so burtetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Det brevet som de sende oss, hev vorte greinleg lese for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Eg let folk sjå etter, og dei fann ut at den byen alt frå dei eldste tider hev sett seg upp mot kongarne, og at uppreist og uro hev vore der rett som det var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Velduge kongar hev butt i Jerusalem, og dei rådde yver alt landet på hi sida elvi, og dei tok imot skatt og toll og vegpengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'No lyt de skipa det so at desse folki ikkje fær halda på med arbeidet, og at byen ikkje skal verta uppbygd att, utan det skulde koma løyve frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Og det lyt sjå vel til at ingenting vert gløymd eller forsømt i denne saki, so skaden ikkje skal verta verre og kongarne lida tap.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'So snart som dette brevet frå kong Artahsasta hadde vorte lese for Rehum og skrivaren Simsai og embætsbrørne deira, for dei snøgt til jødarne i Jerusalem og hindra dei med vald og magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Då vart det stans med byggjingi på Guds hus i Jerusalem. Det vart ingenting gjort med dette fyrr Darius hadde vorte konge i Persia, det andre året han styrde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Profeten Haggai og Zakarja Iddoson, profetarne, profetera for dei jødarne som var i Juda og Jerusalem; dei tala i namnet åt Israels Gud, som var nemnt yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Då gjorde Zerubbabel Sealtielsson og Jesua Josadaksson seg reiduge og tok atter til å byggja på Guds hus i Jerusalem, og Guds profetar studde uppunder og hjelpte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Då kom Tatnai, som var jarl på hi sida elvi, og Setar-Boznai og embætsbrørne deira og dei sagde: «Kven er det som hev gjeve dykk lov til å byggja dette huset og fullføra denne muren?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Me sagde då kva dei mennerne heite som stod fyre bygnaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Men yver styresmennerne åt jødarne vakte auga åt deira Gud, og mennerne lova at dei ikkje skulde leggja noko vondt i vegen for strævet deira, so lenge Darius hadde set på saki og det var kome brev frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Avskrift av det brevet som Tatnai, jarlen på hi sida elvi, og Setar-Boznai og embætsbrørne hans, afarsakitarne, som budde på hi sida elvi, sende til kong Darius;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'for dei sende han ei melding til honom, og i den stod det: «Heil og sæl vere kong Darius!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Vita skal kongen at me hev fare til fylket Juda, til huset åt den store Gud. Dette huset heldt dei no på og byggjer av store steinar, og legg bjelkar inn i murveggjerne. Arbeidet vert gjort med umhug og gjeng godt fram under henderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Me spurde styresmennerne: «Kven hev gjeve dykk lov til å byggja dette huset og fullføra denne muren?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Me spurde og kva dei heitte, so me skulde kunna nemna namni til deg, og skriva upp namni på dei mennerne som stod yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Då svara dei oss soleis: «Me er tenarane hans som er Gud i himmelen og på jordi, og me set upp att det huset som ein stor konge i Israel bygde og fullførde for mange år siden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Men federne våre gjorde Gud i himmelen harm; difor gav han deim i henderne på Babels-kongen, kaldæaren Nebukadnessar; han lagde huset i øyde og tok folket med til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Men kong Kyrus, i det fyrste året han styrde i Babylon, gav lov til å byggja upp att dette gudshuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Kong Kyrus let og taka ut or templet i Babel dei kjerald av gull og sylv som Nebukadnessar hadde teke burt frå templet i Jerusalem og sidan sett inn i templet i Babel. Han gav deim til ein mann som heitte Sesbassar, som han hadde sett til jarl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Og til honom sagde han: «Tak desse kjerald og far av stad og set deim inn i templet i Jerusalem! for Guds hus skal byggjast upp att på den fyrre staden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'So kom då den same Sesbassar og lagde grunnen til Guds hus i Jerusalem. Dei hev bygt på det til denne tid, men endå er det ikkje ferdigt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Soframt no kongen so tykkjer, skulde det vore leita etter i skattkammeret der i Babel, um det er so at kong Kyrus hev gjeve lov til å byggja dette gudshuset i Jerusalem. Sidan lyt kongen lata oss vita kva som er hans vilje i denne saki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Etter dette let kong Darius folk leita etter i arkivet der skattarne vart gløymde i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Då fann dei i borgi Ahmeta i jarleriket Media ei bokrulla, og i den stod det skrive: «Til minne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'I det fyrste året kong Kyrus styrde, gav kong Kyrus denne fyresegni: «Guds hus i Jerusalem, det huset skal no verta uppbygt upp att, so det vert ein stad som folk kann bera fram offer. Det skal setjast på fast grunn, og skal vera seksti alner høgt og seksti alner breidt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'med tri umkverv store steinar og eitt umkverv av nytt timber. Kostnaden skal greidast ut frå kongsgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'So skal og alle kjerald av gull og sylv gjevast attende, dei som Nebukadnessar tok ut or templet i Jerusalem og førde med seg til Babel; dei skal koma til templet i Jerusalem, til sin rette stad, dei skal setjast inn i Guds hus.» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '«Og no, du Tatnai, jarl i landi på hi sida elvi, og du Setar-Boznai, og embætsbrørne dykkar, mennerne frå Afarsak på hi sida elvi, haldt dykk burte derifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'De skal alle lata arbeidet på dette gudshuset i fred. Jarlen og styresmennerne hjå jødarne må byggja dette gudshuset den staden det skal vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Og no skal eg segja fyre korleis de skal fara åt med desse styresmennerne hjå jødarne, so dei kann få halda på med byggjingi. Det som dei treng til bygnaden, skal dei rett og reideleg få av dei innkomor som kongen hev av skatten frå landet på hi sida elvi, so arbeidet ikkje vert hindra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Og det som dei treng av ungnaut og verar og lamb til brennoffer åt Gud i himmelen, kveite og salt, vin og olje, det skal dei få utan skort til kvar dag, etter uppgåva frå prestarne i Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'so dei kann bera fram offer til ein god ange for Gud i himmelen, og beda for kongen og kongssønerne sitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Og no skal det høyra kva eg meir segjer fyre, at um nokon gjer imot dette bodet, då skal det brjotast ut ein bjelke or huset hans, og på den bjelken skal dei hengja mannen upp og negla honom fast, og huset hans skal verta gjort til ein møkdunge, av di han hev bore seg soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Måtte so den Gud som hev late namnet sitt bu der, slå ned alle dei kongar og folk som retter handi si ut til å gjera imot dette bodet og vil gjera noko til meins for dette gudshuset i Jerusalem. Eg, Darius, hev sagt fyre alt dette. Lat det so ganga fullt etter fyresegni!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tatnai, jarl yver landi på hi sida elvi, og Setar-Boznai og embætsbrørne deira gjorde fullt og heilt etter som det stod i fyreskrifterne frå kong Dairus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Styresmennerne hjå jødarne heldt på med byggjingi, og arbeidet gjekk godt fram etter talarne åt profetarne Haggai og Zakarja Iddoson. Dei bygde og fullførde arbeidet etter fyresegn frå Israels Gud og etter fyreskrifterne frå Kyrus og Darius og Artahsasta, kongen i Persia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'So vart då huset fullt ferdigt til tridje dagen i månaden adar i det sette styringsåret åt kong Dairus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Og Israels-sønerne, prestarne og levitarne og alle dei andre som var komne heim att or utlægdi, heldt då høgtid og vigde dette gudshuset med fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Ved denne vigslingi ofra dei hundrad uksar og tvo hundrad verar og fire hundrad lamb, og til syndoffer for heile Israel tolv bukkar etter talet på ætterne i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Dei tilsette prestarne etter skifti deira, og levitarne etter deira avdeilder til gudstenesta i Jerusalem, soleis som det var fyreskrive i Moseboki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Dei som var komne heim att or utlægdi, heldt påskehelg på fjortande dagen i den fyrste månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Prestarne og levitarne hadde då reinsa seg, kvar ein, so dei alle var reine. Dei slagta påskelamb for alle som var komne heim att or utlægdi, for brørne sine, prestarne, og for seg sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Israels-sønerne som var komne heim att or utlægdi, åt då saman med alle som hadde skilt seg frå ureinskapen åt heidningarne i landet og slege lag med deim, av di dei vilde søkja Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Og dei heldt søtebrødhelgi i sju dagar med fagnad. Herren sjølv hadde gjort deim glade, med di han hadde snutt hjarta åt assyrarkongen til deim, so han var med og studde deim i arbeidet på huset åt Gud, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Då ei tid var lidi, hende det, medan kong Artahsasta styrde i Persia, at Ezra for heim frå Babel. Han var son åt Seraja, som var son åt Azarja, son åt Hilkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'son åt Sallum, son åt Sadok, son åt Ahitub,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'son åt Amarja, son åt Azarja, son åt Merajot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'son åt Zerahja, son åt Uzzi, son åt Bukki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'son åt Abisua, son åt Pinehas, son åt Eleazar, son åt øvstepresten Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Ezra var ein skriftlærd mann, vel kjend i Moselovi, den som Herren, Israels Gud, hadde gjeve. Kongen gav honom alt det han bad um; for Herren hans Gud heldt handi si yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Nokre av Israels-sønerne og av prestarne og levitarne og songarane, dørvaktarane og tempelsveinarne var med honom heim til Jerusalem; det var i det sjuande styringsåret åt kong Artahsasta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Han kom til Jerusalem i femte månaden det same sjuande året åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Den fyrste dagen i fyrste månaden vart det fast avgjort at dei skulde fara frå Babel, og den fyrste dagen i femte månaden kom han til Jerusalem; for hans Gud heldt si gode hand yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'For Ezras hadde vendt hugen sin til å granska Herrens lov og fylgja henne, og til å læra andre i Israel upp i lov og rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Dette er avskrift av eit brev som kong Artahsasta gav den skriftlærde presten Ezra, som var kunnig i Herrens bodord og lover for Israel:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '«Artahsasta, konge yver kongarne, til presten Ezra, den lærde i lovi åt Gud i himmelen. Utferda og so burtetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Med dette segjer eg fyre at kvar ein av Israels-folket i mitt rike og av prestarne og levitarne deira som hev hug til å fara til Jerusalem, må fara med deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'sidan kongen og dei sju rådsmennerne hans hev sendt deg i veg til å sjå etter kor det er med Juda og Jerusalem etter lovi åt din Gud, den som du hev i di hand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'og til å føra fram det sylvet og gullet som kongen og rådsmennerne hans godviljugt hev gjeve til Israels Gud, han som hev bustaden sin i Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'sameleis alt sylv og gull som du fær i heile Babels jarlerike, og dei gåvor som folket og prestarne godviljugt til huset åt sin Gud i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Dette skal du gjera deg vel fyre med og kjøpa for desse pengarne uksar og verar og lamb og alt sovore som trengst til grjonoffer og drykkoffer, og det skal du ofra på altaret som høyrer til huset åt dykkar Gud i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Det du og brørne dine finn det rettast å gjera med det som vert att av sylvet og gullet, det må de gjera soleis som dykkar Gud vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Men dei reidskaper som du fær til tenesta i huset åt din Gud, deim skal du gjeva frå deg åt Gud i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Det som meir trengst til huset åt din Gud, det kann du greida ut or skattkammeret åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Og eg, kong Artahsasta, segjer med dette fyre alle skattmeistrarne i landi på hi sida elvi, at alt det som presten Ezras, vismannen i lovi åt Gud i himmelen, bed dykk um, det skal de gjera og gjeva på fyrste ordet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'um det trengst upp til tvo og eit halvt hundrad våger med sylv, tri hundrad tunnor kveite, hundrad ankar vin og hundrad ankar med olje, dertil salt umælt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Alt det som tarvst etter det Gud i himmelen segjer fyre, det skal verta gjort på fyrste ordet og gjeve til huset åt Gud i himmelen, so ikkje hans vreide skal koma yver riket åt kongen og sønerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Og det let me dykk vita, at ingen skal hava magt til å leggja skattar eller toll eller vegpengar på nokon prest eller levit, songar eller dørvaktar, tempelsvein eller annan som hev tenesta i dette gudshuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Og du, Ezras, må, etter den visdom du hev fenge frå din Gud, setja domarar og lovlærde folk til å døma manna millom hjå alt folket på hi sida elvi, alle dei som kjenner loverne åt din Gud; og den som ikkje det gjer, honom skal du læra å kjenna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Og kvar den som ikkje gjer etter lovi åt din Gud og etter lovi åt kongen, yver honom skal det fellast ein rett dom, anten til daude eller utlægd, til pengebot eller til fangehus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Pris vere Herren, Gud åt federne våre, at han gav kongen slikt i hugen, til å pryda Herrens hus i Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'og at han let meg finna nåde hjå kongen og rådsmennerne hans og hjå alle dei megtige hovdingarne åt kongen! Eg fekk mod då eg såg at Herren, min Gud, heldt handi si yver meg, og eg samla kringum meg nokre ættarhovdingar av Israel; dei skulde vera med meg på heimferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Dette er dei ættarhovdingar som i Artahsasta si styringstid for med meg heim frå Babel, og soleis ser ættartavlorne deira ut:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Av Pinhas-sønerne Gersom; av Itamars-sønerne Daniel; av Davids-sønerne Hattus;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'av Sekanja-sønerne av Paros-sønerne Zakarja, og med honom hundrad og femti karfolk som var uppskrivne i ættartavla;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'av Pahat-Moabs-sønerne Eljoenai Zerahjason og tvo hundrad karfolk med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'av Sekanja-sønerne Jahasiels son og tri hundrad mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'av Adins-sønerne Ebed Jonatansson og femti mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'av Elams-sønerne Jesaja Ataljason og sytti mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'av Sefatja-sønerne Zebadja Mikaelsson og åtteti mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'av Joabs-sønerne Obadja Jehielsson og tvo hundrad og attan mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'av Selomits-sønerne Josifjas son og hundrad og seksti mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'av Bebai-sønerne Zakarja Bebaison og åtte og tjuge mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'av Azgads-sønerne Johanan Hakkatansson og hundrad og ti mann med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'av Adonikams-sønerne, dei som kom seinst og heitte Elifelet, Je’uel og Semaja, og seksti mann med deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'av Bigvai-sønerne Utai og Zabbud og sytti mann med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Eg samla deim attmed den elvi som renn til Ahava; der låg me i læger i tri dagar. Då eg so såg meir på folket og på prestarne, fann eg ingen av Levi-sønerne der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Eg sende då bod etter ættarhovdingarne Eliezer og Ariel, Semaja og Elnatan og Jarib og Elnatan og Natan og Zakarja og Mesullam lærarane Jojarib og Elnatan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Desse sagde eg fyre at dei skulde fara av stad til Iddo, hovudmannen i Kasifja-bygdi, og eg sagde kva ord dei skulde tala til Iddo og bror hans, tempelsveinarne i Kasifja-bygdi, so dei skulde senda oss tenarar til gudshuset vårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Og Gud heldt si gode hand yver oss, so dei sende oss ein vitug mann som heitte Serebja, av sønerne åt Mahli, son åt Levi, son åt Israel; han sjølv med søner og brør var attan i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Sameleis sende dei Hasabja i lag med Jesaja av Merari-sønerne; med brørne hans og sønerne deira var det tjuge mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Dertil tvo hundrad og tjuge tempelsveinar, alle nemde på namn, av dei tempelsveinarne som David og hovdingarne hans hadde sett til tenarar åt levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Der ved Ahava-elvi lyste eg til ei fasta, av di med skulde audmykja oss for vår Gud og beda honom um god ferdalukka for oss sjølve og borni våre og all vår eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Eg skjemdest å beda kongen um herhjelp og ridarar til å verja oss mot uvener på vegen; for me hadde sagt til kongen: «Vår Gud held si hand yver alle deim som heldt seg til honom, og let det ganga vel for deim; men hans magt og vreide fell yver deim som gjeng frå honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Me fasta då og bad Gud um hjelp, og han høyrde bøni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Sidan valde eg ut tolv av prestehovdingarne og Serebja og Hasabja og ti av brørne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Åt desse vog eg upp sylvet og gullet og kjeraldi, det som kongen og rådsmennerne og hovdingarne hans, og alle Israels-mennerne som heldt seg der i landet, hadde gjeve til ei reida åt gudshuset vårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Eg vog upp åt deim sekstan hundrad våger sylv, sylvkoppar som vog i alt tvo hundrad og femti våger, og dertil tvo hundrad og femti våger med gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'og umfram dette tjuge gullskålar, til fem tusund dalar, og tvo kjerald av gullblank kopar, dyr som gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Og eg sagde med deim: «De er vigde til Herren, og kjeraldi er vigde; sylvet og gullet er ei friviljug reida til Herren, Gud åt federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Agta no vel på det og gjæt det, til dess de kann vega det ut att i Jerusalem til dei fremste av prestarne og levitarne og ættarhovdingarne hjå Israel, i kovarne i Herrens hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Dermed tok prestarne og levitarne imot sylvet og gullet og koppar og kjerald som soleis var vege, og skulde føra det fram til Jerusalem til huset åt vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'So for me burt frå Ahava-elvi tolvte dagen i den fyrste månaden, og tok vegen til Jerusalem. Vår Guds hand var yver oss, og han berga oss frå uvener og lurarar på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Me kom til Jerusalem og fekk kvila ut der tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Den fjorde dagen vart sylvet og gullet og koppar og kjerald vege upp gudshuset vårt og gjeve i henderne åt presten Meremot Uriason. Saman med honom var Eleazar Pinhasson og levitarne Jozabad Jesuason og Noadja Binnuison med og tok imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Det vart alt utgjeve etter tal og vegt, og vegti på alt vart uppskrivi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Dei hertekne som var komne heim att or utlægdi, ofra no brennoffer til Israels Gud. Dei ofra tolv uksar for heile Israel og seks og nitti verar, sju og sytti lamb og tolv syndoffer-bukkar, alt til brennoffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'So gav dei frå seg kongsbodet til dei kongelege satraparne og til jarlarne i landi på hi sida elvi. Desse kom då og med hjelp både til lyden og til Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Etter desse hendingarne kom hovdingarne fram for meg og sagde: «Korkje folket i Israel eller prestarne og levitarne hev halde seg skilde frå folki i landi soleis som det helst kunde søma seg etter all den styggedomen som dei hev fare med både kananitarne og hetitarne, perizitarne og jebusitarne, ammonitarne og moabitarne, egyptararne og amoritarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'For dei hev teke døtterne deira til konor både åt seg sjølve og åt sønerne sine. På den måten hev det heilage sædet blanda seg med folki i landet, og hovdingarne og formennerne hev vore dei fyrste til å fara med utruskap i dette stykket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Då eg høyrde dette, reiv eg sund kjolen min og kåpa mi, og eg reiv hår av hovudet og or skjegget og vart sitjande so sorgfull at eg kunde ikkje segja eit ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Då samlast dei kringum meg alle dei som var forstøkte for det som Israels Gud hadde sagt um utruskapen deira som var heimkomne or utlægdi; men eg vart sitjande i djup sorg alt til kveldsofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ved kveldsoffertidi stod eg upp or sorgi mi og reiv sund kjolen og kåpa. So fall eg ned på kne og rette ut henderne mine mot Herren, min Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'og sagde: «Min Gud! eg skjemmest og blygjest for å lyfta andlitet mitt mot deg, min Gud; for misgjerningarne våre hev vakse upp yver hovudet vårt, og skuldi vår når til himmels.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Frå den tid federne våre livde og alt til no hev me vore i stor skuld. For misgjerningarne våre hev me, med kongarne og prestarne våre, vorte gjevne i henderne på framande kongar, til sverd og til utlægd, til plundring og skam, som det syner seg no i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Men no ei ørliti stund hev Herren, vår Gud, miskunna oss, so han hev berga ein leivning av oss og gjeve oss eit fotfeste på den heilage staden sin, so han, vår Gud, kunde lata ljoset skina i augo våre, og me fekk ein liten livskveik i trældomen vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'For trælar det er me; men endå hev Gud ikkje slept oss i trældomen, men hev late oss finna nåde for augo åt persarkongarne, so dei gav oss ein livskveik til å reisa upp att gudshuset vårt og byggja det upp frå røysi; dermed kunde me få ein innhegna bustad i Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Men vår Gud! kva skal me no segja etter dette? For me hev vendt oss frå bodordi dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'deim som du gav ved tenarane dine, profetarne, då du sagde: «Landet som det her kjem til og skal taka til eigedom, er eit tilsulka land for all den sulking og all den styggedom som dei framande folki i sin ureinskap hev fyllt det med frå den eine enden til den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Difor skal de korkje gjeva døtterne dykkar til sønerne deira eller taka døtterne deira til konor åt sønerne dykkar. De skal aldri bry dykk um deira velferd og lukka, so de kann verta sterke og få eta av landsens gode ting og lata landet gå i arv til borni dykkar um alder og æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Du, vår Gud, hev vore miskunnsam meir enn me var verde etter synderne våre, og hev late ein leivning av oss, slik som denne her, verta berga. Skulde me no etter alt som hev kome yver oss ved dei vonde verki våre, og ved den store skuld me hev drege på oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'skulde me då brjota bodordi dine att og hava samgifte med folk som driv sovorne styggedomar? Måtte du ikkje då harmast på oss, so du reint kom til å tyna oss so ingen leivning var att, og ingen berga seg undan?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Herre, Israels Gud! du er rettvis når me her i dag berre er ein leivning som er berga. Sjå no ligg me her i vår skuld framfor deg. Som det no er, kann ingen verta standande for deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Ezra låg på marki framfyre gudshuset og gret og bad og sanna synderne. Då samla det seg kring honom ein ovstor skare av Israels folk, karar og kvinnor og born, og folket gret sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Då tok Sekanja Jehielsson av Olams-sønerne til ords og sagde med Ezra: «Me hev vore utrugne åt mot vår Gud, med di me hev teke framande konor frå dei framande folki her i landet; men endå er ikkje all voni ute for Israel i denne saki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Lat oss no gjera samband med vår Gud, um at me jagar frå oss alle desse konorne, og borni som dei hev fenge, etter kravet frå Vårherre og frå dei mennerne som ræddast for Guds lov, og lat det so verta gjort etter lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Ris upp! for det er du som lyt greida denne saki, og me skal stydja deg. Ver frihuga og set det i verk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Då reis Ezras upp og let prestehovdingarne og levithovdingarne og alle andre hovdingar i Israel gjera eid på at det måtte vera som her det var sagt. Og dei gjorde eiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Ezra stod upp frå den staden framfyre gudshuset, og gjekk inn i romet åt Johanan Eljasibsson. Og då han var komen dit, var han ikkje god til å eta eller drikka, soleis syrgde han yver utruskapen åt deim som var attkomne frå utlægdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'So lyste dei ut yver Juda og Jerusalem til deim som var komen heim or utlægdi, at dei alle skulde samlast i Jerusalem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Var det nokon som ikkje kom innan tridje dagen etter, soleis som hovdingarne og styringsmennerne hadde sett, so skulde all hans eigedom verta bannstøytt, og han sjølv verta jaga ut or samlingi av deim som var komne heim or utlægdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'So samla alle Juda- og Benjamins-mennerne seg i Jerusalem til tridje dagen; det var tjugande dagen i den niande månaden. Alt folket sat på den opne plassen attmed gudshuset og skalv, både for saki skuld og for regnbyorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Då stod presten reis Ezra upp og sagde til deim: «De hev vore utrugne, med di de hev teke framande kvende til konor, og dermed hev de auka skuldi åt Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Gjev no Herren æra, Gud åt federne dykkar, og gjer etter viljen hans; skil dykk frå dei hine folki her i landet og frå dei framande konorne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Då svara heile lyden med høg røyst: «Ja, som du hev sagt, so er me skuldige å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Men folket er mange i tal, og no er det regntidi, so me kann ikkje verta standande her ute. Dette er og ei ærend som ikkje verta avgjord på ein dag eller tvo; for me hev mykje synd på oss i dette stykket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Lat difor hovdingarne våre gjera greida for heile lyden, og lat so alle deim i byarne våre som hev teke framande kvende til konor, møta fram til tider som vert fastsette, saman med styresmennerne og domarane frå den same byen, til dess me kann få vendt av vår Guds brennande harm for denne saki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Einast Jonatan Asaelsson og Jahzeja Tikvason gjorde motmæle mot dette, og Mesullam saman med leviten Sabbetai heldt med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Dei som var attkomne or utlægdi, gjorde som sagt var. Og utvalde vart: Presten Ezras og nokre menner, hovdingar for ættgreinerne sine, alle nemnde på namn. So sette dei rådstemna den fyrste dagen i den tiande månaden til å granska denne saki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Til fyrste dagen i fyrste månaden hadde dei greidt upp saki for dei mennerne som hadde teke seg framande kvende til konor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Millom prestesønerne fann dei desse som hadde teke framande kvende til konor: Av sønerne åt Jesua Josadaksson og brørne hans: Ma’aseja, Eliezer, Jarib og Gedalja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'dei vilde styra frå seg konorne sine og ofra ein ver til syndoffer for den skuld dei hadde drege på seg - det lova dei og rette fram handi si på det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'av Immers-sønerne: Hanani og Zebadja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'av Harims-sønerne: Ma’aseja, Elias, Semaja, Jehiel og Uzzia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'av Pashurs-sønerne: Eljoenai, Ma’aseja, Ismael, Netanel, Jozabad og Elasa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Av levitarne: Jozabad, Sime’i og Kelaja, som og heitte Kelita, Petahja, Juda og Eliezer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'av songarane: Eljasib; av dørvaktarane: Sallum, Telem og Uri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Av Israel elles: Av Paros-sønerne: Ramja, Izza, Malkia, Mijamin, Eleazar, Malkia og Benaja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'av Elams-sønerne: Mattanja, Zakarja, Jehiel, Abdi, Jeremot og Elia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'av Zattu-sønerne: Eljoenai, Eljasib, Mattanja, Jeremot, Sabad og Aziza;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'av Bebai-sønerne: Johanan, Hananja, Zabbai, Atlai;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'av Bani-sønerne: Mesullam, Malluk og Adaja, Jasub, Seal og Jeremot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'av Pahat-Moabs-sønerne: Adna, Kelal, Benaja, Ma’aseja, Mattanja, Besalel, Binnui og Manasse;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'og Harims-sønerne: Eliezer, Issia, Malkia, Semaja, Simeon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluk, Semarja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'av Hasums-sønerne: Mattenai, Mattatta, Sabad, Elifelet, Jeremai, Manasse, Sime’i;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'av Bani-sønerne: Ma’adai, Amram og Uel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedeja, Keluhi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanja, Meremot, Eljasib,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattanja, Mattenai og Ja’asu,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binnui, Sime’i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'og Selemja, Natan og Adaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbai, Sasai, Sarai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarel, Selemja, Semarja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amarja, Josef;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'av Nebo-sønerne: Je’iel, Mattitja, Zabad, Zebina, Jaddu, Joel og Benaja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Alle desse hadde teke framande kvende til konor. Og millom konorne var det sume som hadde fenge born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Fråsegni hans Nehemia, son åt Hakalja. I kislev månad, i det tjugande styringsåret, medan eg var i borg i Susan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'kom Hanani dit, ein av brørne mine, og med honom nokre andre frå Juda. Eg frette deim ut om jødarne, dei av fangarne som hadde sloppe heim att, og um Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Dei svara meg: «Dei av fangarne som hev sloppe heim att og er der i jarleriket, dei lid ulukkeleg skam og skade. Muren kring Jerusalem ligg nedbroten, og portarne er uppbrende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Då eg høyrde denne fretnaden, sette eg meg ned og gret og syrgde dag etter dag. Eg fasta og bad til Gud i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Eg sagde: «Å kjære Herre Gud i himmelen, den store, agelege Gud, som held pakti og held uppe miskunni mot deim som elskar honom, og som held bodi hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Å, lat øyra ditt agta på bøni mi! Lat augo dine vera opne! Høyr tenaren din når eg kjem fram for deg og bed i dag! Dag og natt gjer eg bøner for Israels-borni, tenarane dine. Eg sannar synderne våre, som me Israels-borni hev gjort mot deg. Me hev synda både eg og ætti mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Ille hev me forbrote oss mot deg. Me hev ikkje halde bodi og loverne og retterne som du baud Moses, tenaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Men kom i hug det ordet du gav Moses, tenaren din: «Fer de med svik, so vil eg spreida dykk millom folki;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'men vender de um til meg og held bodi mine og liver etter deim, so vil eg sanka dei spreidde, um dei so var burtstøytte til himmelens ende, og eg vil føra deim til den staden eg hev valt ut til bustad åt namnet mitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Dei er då tenarane dine og folket ditt som du fria ut med di store magt og di sterke hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Å Herre, lat øyra ditt agta på bøni frå tenaren din og bøni frå tenarane dine, dei som gjerne vil ottast ditt namn. Å, lat tenaren din hava lukka med seg i dag; lat meg finna medhug hjå denne mannen!» - Eg var den gongen skjenkjar hjå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'I nisan månad i det tjugande styringsåret åt Artahsasta, då høvde so at vin stod framfyre honom, tok eg vinen og flidde kongen. Og eg hadde ikkje fyrr synt meg sturen for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Då sagde kongen til meg: «Kvi er du so sturen? Du er då ikkje sjuk! Dette kann ikkje vera anna enn hjartesut.» Eg vart fælt rædd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'og eg sagde til kongen: «Må kongen liva æveleg! Kvi skulde ikkje eg stura når byen der federne er gravlagde, ligg i røys, og portarne der er uppbrende?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Kongen sagde til meg: «Kva er det du ynskjer?» Då bad eg ei bøn til Gud i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Og so sagde eg til kongen: «Um det tekkjest kongen, og um du eig godvilje for tenaren din, so ynskjer eg å verta send til Juda, til byen der federne mine er gravlagde, so eg kann byggja honom upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Kongen sagde til meg, medan dronningi sat ved sida: «Kor lenge vil ferdi di vara, og kva tid kjem du att?» Då det soleis tektest Kongen å lata meg fara, gjorde eg avtale med honom um ei viss tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'So sagde eg til kongen: «Um det tekkjes kongen, so lat meg få med brev til jarlarne på hi sida elvi, so dei let meg fara igjenom til dess eg kjem til Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Og lat meg få brev til Asaf, han som hev tilsyn med den kongelege skogen, so han let meg få timber til portbjelkarne i borgi som høyrer til huset, til bymuren og til huset eg skal bu i.» Kongen let meg få det, av di min Gud heldt si gode hand yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Då eg kom til jarlarne på hi sida elvi, flidde eg deim kongebrevi. Kongen sende ogso med meg hovudsmenner og hestfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Men då horoniten Sanballat og den ammonitiske tenestmannen Tobia høyrde gjete dette, tykte dei det var fælt tregelegt, at det var komen ein mann og vilde søkja det som var til bate for Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Då eg kom til Jerusalem, og hadde vore der tri dagar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'reis eg upp um natti, eg og nokre få mann med meg. Eg hadde ikkje nemnt med noko menneskje kva min Gud hadde gjeve meg i hugen å gjera for Jerusalem. Det dyret eg reid på, var det einaste dyret eg hadde med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Eg drog ut um natti gjenom Dalporten og burtimot Drakekjelda og Møkporten. Eg såg på murarne kring Jerusalem; dei var nedbrotne, og portarne var uppbrende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'So drog eg burt til Kjeldeporten og Kongedammen; men der var det ikkje råd for dyret å koma fram med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'So drog eg upp i dalen um natti og såg på muren og kom so attende gjenom Dalporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Formennerne hadde ikkje fenge visst kva veg eg hadde fare, eller kva eg emna på. Eg hadde ikkje endå nemnt noko med jødarne eller prestarne eller dei adelborne eller formennerne eller nokon annan som skulde hava med arbeidet å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Men no sagde eg til deim: «De ser sjølve kor ille me er stelte. Jerusalem ligg i øyde, portarne er uppbrende. Kom, lat oss byggja upp att muren kring Jerusalem, so me ikkje skal hava den skammi på oss lenger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Eg tala med deim um handi åt min Gud, kor ho hadde synt seg nådig mot meg. Like eins fortalde eg kva kongen hadde sagt med meg. Då sagde dei: «Me vil ganga i veg og byggja.» Og dei styrkte seg til det gode verket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Men då horoniten Sanballat og den ammonitiske tenestmannen Tobia og arabaren Gesem spurde dette, spotta dei oss og svivyrde oss: «Kva er det de gjer på?» sagde dei. «Vil de gjera upprør mot kongen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Då gav eg deim dette svaret: «Gud i himmelen vil gjeva oss lukka. Og me, hans tenarar, vil ganga i veg og byggja. Men de hev ikkje anten lut eller rett eller minne i Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Øvstepresten Eljasib og dei andre prestarne, frendarne hans, gjekk i veg og bygde Saueporten. Dei vigde honom, og sette inn dørerne. So bygde dei fram til Meatårnet, som dei vigde, og fram til Hananeltårnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Attmed deim bygde folk frå Jeriko. Og attmed deim bygde Zakkur Imrison.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Fiskeporten bygde Sena’a-borni; dei timbra honom upp og sette inn dører og lås og slåer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Attmed deim arbeidde Meremot, son åt Uria Hakkosson, med å vøla muren. Attmed han Mesullam, son åt Berekja Mesezabelsson. Attmed honom arbeidde Sadok Ba’anason.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Og attmed honom arbeidde folket frå Tekoa; men storfolket deira bøygde ikkje nakken sin under arbeidet for Herren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Gamleporten vølte Jojada Paseahsson og Mesullam Besodjason; dei timbra honom og sette inn dører og lås og slåer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Attmed deim arbeidde gibeoniten Melatja og merononiten Jadon med folk frå Gibeon og Mispa, som låg under domsmagti åt jarlen på hi sida elvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Attmed deim arbeidde Uzziel Harhajason med gullsmedarne, og attmed honom Hananja, ein salvehandlar. Det næste stykket av Jerusalem let dei vera, burt til Breidemuren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Attmed deim arbeidde Refaja Hursson, hovdingen yver halve heradet kring Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Attmed honom arbeidde Jedaja Harumafsson utanfor sitt eige hus. Og attmed honom Hattuh Hasabnejason.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Eit anna stykke vølte Malkia Harimsson og Hassub Pahat-Moabsson; burt til Omnstårnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Attmed deim arbeidde hovdingen yver det andre halve heradet kring Jerusalem, Sallum Hallohesson, saman med døtterne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Dalporten vølte Hanun og folk frå Zanoah; dei bygde honom og sette inn dører og lås og slåer. Dei bygde og tusund alner av muren burt til Møkporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Og Møkporten vølte Malkia Rekabsson, hovdingen yver heradet Bet-Hakkerem; han bygde honom og sette inn dører og lås og slåer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Kjeldeporten vølte Sallun Kol-Hozesson, hovding yver Mispaheradet; han bygde honom, tekte honom, sette inn dører og lås og slåer. Dessutan bygde han muren ved Selahdammen ved kongshagen burt åt dei tropperne som gjeng ned frå Davidsbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Etter honom arbeidde Nehemia Azbuksson, hovding yver halve Betsurheradet, burt til midt fyre Davids-graverne, til den gravne dammen og til huset for kjemporne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Etter honom arbeidde levitarne, under Rehum Banison. Attmed deim arbeidde, for sitt herad, Hasabja, hovding yver halve Ke’ilaheradet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Etter honom arbeidde frendarne deira under, Bavvai Henadadsson, hovding yver den andre helvti av Ke’ilaheradet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Attmed honom vølte Ezer Jesuason, hovding yver Mispa, eit anna stykke midt fyre uppgangen til våpnhuset i murkråi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Etter honom vølte Baruk Zabbaison trottigt eit anna stykke frå murkråi heilt fram til husdøri åt øvstepresten Eljasib.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Etter honom vølte Meremot, son åt Uria Hakkosson, eit anna stykke frå husdøri åt Eljasib til enden av huset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Og etter honom arbeidde prestarne, folk frå Jordan-kverven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Etter deim arbeidde Benjamin og Hassub utanfor husi sine; etter deim Azarja, son åt Ma’aseja Ananjason, attmed sitt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Etter honom vølte Binnui Henadadsson eit anna stykke frå huset hans Azarja til murkråi og til hyrna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal Uzaison vølte stykket midt fyre murkråi og det øvre tårnet, som skyt fram frå kongshuset og høyrer til fangegarden. So kom Pedaja Parosson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '- Tempelsveinarne budde på Ofel, heilt fram til midt imot Vatsporten mot aust og Framskotstårnet, -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'So vølte Tekoa-folket eit anna stykke frå midt imot det store framskotstårnet og til Ofelmuren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Ovanfor Hesteporten arbeidde prestarne, kvar og ein midt imot sitt eige hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Etter deim arbeidde Sadok Immersson midt imot sitt hus; og etter honom Semaja Sekanjason, som hadde vakthaldet ved Austporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Etter honom vølte Hananja Selemjason og Hanun, sette son åt Salaf, eit anna stykke. Etter deim arbeidde Mesullam Berekjason midt fyre koven sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Etter honom arbeidde Malkia, ein av gullsmedarne, heilt fram til huset for tempelsveinarne og kræmarane, midt imot Mynstringsporten og fram til Hyrnesalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Og millom Hyrnesalen og Saueporten arbeidde gullsmedarne og kræmarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Då no Sanballat høyrde gjete at me dreiv på og bygde på muren, vart han brennande harm og fælt sinna. Han spotta jødarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'og tala soleis til brørne sine og til stridsfolket i Samaria: «Kva er det desse visne jødarne driv på med? Skal dei hava lov til sovore? Skal dei få ofra? Kann henda dei vil få arbeidet ferdigt i dag! Kann henda dei vil blåsa liv i steinarne frå dei forbrende røysarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Ammoniten Tobia, som stod jamsides med honom, sagde: «Lat deim byggja so mykje dei vil. Berre ein rev hoppar uppå, kjem han til å riva ned heile steinmuren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, '«Høyr, vår Gud, kor me er til spott og spe! Lat hædingi deira koma attende på deira eige hovud og gjev deim til plundring i eit land der dei lyt vera fangar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Løyn ikkje misgjerningi deira! Lat ikkje syndi deira verta utstroki for di åsyn, av di dei hev krenkt deg medan byggjarane høyrde på det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Me bygde på muren, og heile muren vart gjort ferdig upp til halve høgdi. Og folket hadde godt mod på arbeidet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Men då Sanballat og Tobia og arabararne og ammonitarne og asdoditarne høyrde at murarne i Jerusalem heldt på å heilna og rivnorne tok til å teppast, då vart dei brennande harme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Dei lagde seg i hop alle saman um å koma og strida mot Jerusalem og gjera ugreida for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Då bad me til vår Gud. Og me sette vaktpostar natt og dag til vern mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Men jødarne sagde: «Magti tryt hjå arbeidsfolket, og grushaugane er for store; me orkar ikkje byggja på muren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Og fiendarne våre sagde: «Inkje skal dei gå og inkje skal dei sjå fyrr me kjem midt uppi flokken og høgg deim ned og soleis gjer ende på arbeidet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Og jødarne som budde nær deim, kom frå alle kantar og sagde med oss vel ti gonger: «De lyt koma attende til oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Då fylkte eg folket i lægderne bak muren, på dei opne plassarne; fylkte deim kvar ættgrein for seg med sine sverd og med spjot og med bogar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Eg mynstra deim, gjekk so fram og tala til dei adelborne og formennerne og til hitt folket: «Ver ikkje rædde deim! Tenk på Herren, den store og skræmelege, og strid for brørne dykkar, for sønerne og døtterne dykkar, for konorne dykkar og for heimarne dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Då fiendarne våre fekk spurt at me hadde full greida på det, og at Gud soleis hadde gjort rådi deira um inkje, so kunde me alle ganga attende til muren kvar til sitt arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Men frå den dagen dreiv berre helvti av drengjarne mine på med arbeidet; andre helvti stod væpna med spjot, med skjoldar, bogar og brynjor. Hovdingarne stod attanfor heile Judas hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Dei som bygde på muren og dei som leste på seg og bar byrdor, med eine handi gjorde dei arbeidet, med hi heldt dei verja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Kvar byggjar spente sverd um seg, og dei bygde medan hornblåsaren stod jamsides med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Og eg sagde til dei adelborne og formennerne og til hitt folket: «Arbeidet er stort og vidsveimt; og me er spreidde på muren langt frå kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Der de høyrer hornet ljoda, dit skal de samla dykk til oss. Vår Gud vil strida for oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'So dreiv me då på med arbeidet, medan helvti av folket heldt spjoti, frå morgonroden rann til stjernorne synte seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Samstundes baud eg folket: «Kvar og ein med sin dreng skal vera med natti inne i Jerusalem, so me kann hava deim til vakt um natti og til arbeid um dagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Korkje eg eller frendarne mine eller drengjerne eller vaktmennerne mine, kom or klædi. Våpni var for kvar og ein likso umissande som vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Men so reiste det seg eit stort skrik frå folket og frå konorne deira mot dei jødiske brørne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Sume sagde: «Me og sønerne og døtterne våre er mange, so lat oss få korn, so me kann eta og berga livet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Og sume sagde: «Åkrarne og vinhagarne og husi våre lyt me setja i pant for å få korn i dyrtidi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Og andre sagde: «Me hev lote låne pengar på åkrarne og vinhagarne våre til å greida skatten til kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'No er då våre kroppar likso gode som kropparne åt brørne våre, og våre born er jamgode med deira born. Like vel lyt me gjera sønerne og døtterne våre til trælar. Ja, sume av døtterne våre er alt trælka; og me hev ikkje magt til å hindra det; for åkrarne og vinhagarne våre høyrer dei hine til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Eg vart brennande harm då eg høyrde skriket deira og desse ordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Då eg hadde samrådt meg med meg sjølv, skjemde eg på dei adelborne og formennerne og sagde til deim: «Oker er det de driv med brørne dykkar!» So stemde eg saman til eit stort folkemøte mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Og eg sagde til deim: «Etter evna hev me kjøpt frie dei jødiske brørne våre som var selde til heidningarne. Og so gjeng det burt og sel brørne dykkar, so dei lyt selja seg til oss!» Då tagde dei og fann inkje ord for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Og eg sagde: «Det er ikkje fint å fara åt soleis som det hev gjort. De burde då ferdast i otte for vår Gud, so ikkje heidningarne, fiendarne våre, skulde få grunn til å spotta oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Eg og frendarne mine og drengjerne mine hev og pengar og korn å krevja av deim. Lat oss strukja den skuldi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Og de - kjære væne, gjev attende i dag åkrane og vinhagarne og oljeplantingarne og husi deira, og gjev deim etter rentorne det kunde krevja av deim av pengarne og kornet og druvesafti og oljen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Dei svara: «Me gjev det attende og gjev upp kravi på deim. So som du hev sagt, vil me gjera.» Eg tok deim i eid, etter eg hadde kalla prestarne til, at dei skulde halda dette vedtaket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Og eg skok kappelumma mi med dei ordi: «Soleis skal Gud skaka frå hus og eiga kvar ein som ikkje held dette vedtaket; ja, soleis skal han verta skjeken og tom.» Og heile lyden sagde: «Ja, ja!» Og dei lova Herren, og heile folket gjorde etter dette vedtaket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Dessutan lyt eg nemna: Frå den dagen eg vart utnemnd til jarl yver Jødeland, frå det tjugande til det tvo og trettiande styringsåret åt kong Artahsasta, i tolv år, hev korkje eg eller frendarne mine ete av jarlekosten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Dei fyrre jarlarne, fyre min tid, tyngde på folket, og tok brød og vin av deim til yver fyrti lodd sylv. Jamvel drengjerne deira spela meister yver folket. Av age for Gud for ikkje eg åt soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Dessutan var eg med og bygde på muren. Og ingen åker hev me kjøpt oss. Endå alle drengjerne mine hev vore samla til byggjearbeidet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Og jødarne og formennerne, eit hundrad og femti mann, åt ved mitt bord, umfram deim som kom til oss frå heidningfolki rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Og det vart tillaga på min kostnad kvar dag ein ukse og seks utvalde sauer, umfram fuglar, og tiande kvar dag mykje vin av alle slag; like vel kravde eg ikkje jarlekosten, for arbeidet låg tungt på dette folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Kom meg i hug, min Gud, og rekna meg til godes alt det eg hev gjort for dette folket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Då no Sanballat og Tobia og arabaren Gesem og dei hine fiendarne våre fekk spurt at eg hadde bygt upp muren, og at det ikkje fanst nokon rivna att i honom - endå hadde eg ikkje sett inn dører i portarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'då sende Sanballat og Gesem bod til meg med dei ordi: «Kom, lat oss setja stemna med kvarandre i ein av landsbyarne i Onodalen!» Dei tenkte å gjera meg eitkvart ilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Eg sende bod attende og svara deim: «Eg driv på med eit stort arbeid, so eg kann ikkje koma ned. Kvi skulde arbeidet kvila, når eg gjekk frå det og kom ned til dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Fire gonger sende dei same bodet til meg; kvar gong gav eg deim same svaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Femte gongen sende Sanballat same bodet, og det med drengjen sin med ope brev i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Der stod skrive: «Det ordet gjeng millom grannefolki, og Gasmu segjer det same, at du og jødarne tenkjer på upprør mot kongen, og det er difor du byggjer upp att muren; ja, at du etlar deg verta kongen deira, so segjer dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Og at du jamvel hev tinga deg profetar til å ropa ut i Jerusalem at du er konge i Juda. No vil kongen få høyra um dette. Kom då, lat oss samrådast!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Då sende eg dette svaret: «Ingen ting hev hendt av det du nemner; det er noko du sjølv hev funne på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Dei tekte alle dei skulde skræma oss, so henderne våre skulde valna og arbeidet verta ugjort. Men styrk du henderne mine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Eg kom inn i huset åt Semaja, son åt Delaja, soneson åt Mehetabel, medan han heldt seg inne. Han sagde: «Lat oss ganga saman til Guds hus, inn i templet, og stengja dørerne til templet; for dei kjem og vil drepa deg, ja, dei kjem um natti og vil drepa deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Men eg svara: «Skulde ein mann som eg røma sin veg? Eller kann ein mann som eg ganga inn i heilagdomen og endå få liva? Eg gjeng ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Eg skyna greidt at ikkje Gud hadde sendt honom, han tala dette profetordet yver meg berre av di Tobia og Sanballat hadde leigt honom til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Meiningi med dette var at han skulde skræma meg til å gjera so og dermed forsynda meg. Det vilde gjenge på æra mi, so dei kunde ført spott og skam yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Min Gud, kom i hug Tobia og Sanballat for desse verki hans, og like eins profetkvinna Noadja og dei hine profetarne som vilde skræma meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Muren vart fullt ferdig på tvo og femti dagar, den fem og tjugande dagen i månaden elul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Då alle fiendarne våre spurde dette, då ottast alle grannefolki, og dei minka mykje i sine eigne augo. Dei skyna at dette arbeidet var eit verk av vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'I dei dagarne skreiv dei jødiske adelsmennerne mange brev som gjekk til Tobia, og frå Tobia kom det brev attende til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Mange jødar var i svorne vener av honom; han var måg til Sekanja Arahsson; og Johanan, son hans, var gift med dotter åt Mesullam Berekjason.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Gong på gong tala dei med meg um dygderne hans, og mine ord bar dei fram til honom. Tobia sende ogso brev til å skræma meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Då no muren var uppbygd, sette eg inn dørerne. Og portvakti tilsett; like eins songarane og levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Og eg sette yver Jerusalem Hanani, bror min, og Hananja, borghovdingen; han vart halden for ein framifrå truverdig og gudleg mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Og eg sagde til deim: «Portarne i Jerusalem må ikkje verta opna fyrr soli tek til å hita. Og medan vakti endå stend på post, skal dørerne verta stengde og læste, og nye vaktfolk skal stella seg upp av borgararne i Jerusalem, kvar på post, kvar utanfor sitt hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Byen var vid og stor, men folket i honom var fåment, og husi var ikkje uppbygde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Eg fekk då den inngivnad av min Gud at eg skulde stemna i hop dei adelborne og formennerne og heile folket til uppskriving i ættarlista. Då fann eg ættarlista yver deim som fyrst hadde fare heim. Og der fann eg skrive:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Her kjem talet på dei fylkesbuarne som for heim or utlægdi, dei som Nebukadnessar, kongen i Babel, hadde ført burt, og som no for heim att til Jerusalem og Juda, kvar til sin by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Dei fylgde Zerubbabel og Jesua, Nehemia og Azarja, Ra’amja og Nahamani, Mordokai og Bilsan, Misperet og Bigvai, Nehum og Ba’ana. - Dette er manntalet yver alle mennerne i Israels-lyden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paros-sønerne, tvo tusund eit hundrad og tvo og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sefatja-sønerne, tri hundrad og tvo og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Arahs-sønerne, seks hundrad og tvo og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahat-Moabs-sønerne, av Jesua- og Joabs-sønerne, tvo tusund åtte hundrad og attan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elams-sønerne, eit tusund tvo hundrad og fire og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Zattu-sønerne, åtte hundrad og fem og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Zakkai-sønerne, sju hundrad og seksti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnui-sønerne, seks hundrad og åtte og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bebai-sønerne, seks hundrad og åtte og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Azgads-sønerne, tvo tusund tri hundrad og tvo og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikams-sønerne, seks hundrad og sju og seksti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvai-sønerne, tvo tusund og sju og seksti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adins-sønerne, seks hundrad og fem og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aters-sønerne av Hizkia-ætti, åtte og nitti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hasums-sønerne, tri hundrad og åtte og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Besai-sønerne, tri hundrad og fire og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Harifs-sønerne, hundrad og tolv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeons-sønerne, fem og nitti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'mennerne frå Betlehem og Netofa, hundrad og åtte og åtteti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'mennerne frå Anatot, hundrad og åtte og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'mennerne frå Bet-Azmavet, tvo og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'mennerne frå Kirjat-Jearim, Kefira og Be’erot, sju hundrad og tri og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'mennerne frå Rama og Geba, seks hundrad og ein og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'mennerne frå Mikmas, hundrad og tvo og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'mennerne frå Betel og Aj, hundrad og tri og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'mennerne frå det andre Nebo, tvo og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'den andre Elam søner, eit tusund tvo hundrad og fire og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harims-sønerne, tri hundrad og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jeriko-sønerne, tri hundrad og fem og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Lods-, Hadids- og Ono-sønerne, sju hundrad og ein og tjuge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Sena’a-sønerne, tri tusund ni hundrad og tretti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Av prestarne: Jedaja-sønerne av Jesua-ætti, ni hundrad og tri og sytti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immers-sønerne, eit tusund og tvo og femti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashurs-sønerne, eit tusund tvo hundrad og sju og fyrti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harims-sønerne, eit tusund og syttan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Av levitarne: Jesua-sønerne av Kadmiels-ætti, av Hodeva-sønerne, fire og sytti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Av songarane: Asafs-sønerne, hundrad og åtte og fyrti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Av dørvaktarane: Sallums-sønerne, Aters-sønerne, Talmons-sønerne, Akkubs-sønerne, Hatita-sønerne, Sobai-sønerne, hundrad og åtte og tretti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Av tempelsveinarne: Siha-sønerne, Hasufa-sønerne, Tabbaots-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Keros-sønerne, Sia-sønerne, Padons-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebana-sønerne, Hagaba-sønerne, Salmai-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Hanans-sønerne, Giddels-sønerne, Gahars-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reaja-sønerne, Resins-sønerne, Nekoda-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gazzams-sønerne, Uzza-sønerne, Paseahs-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Besai-sønerne, Me’unims-sønerne, Nefussims-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbuks-sønerne, Hakufa-sønerne, Harhurs-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Basluts-sønerne, Mehida-sønerne, Harsa-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkos-sønerne, Sisera-sønerne, Tamahs-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Nesiahs-sønerne, Hatifa-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Av sønerne åt Salomo-sveinarne: Sotai-sønerne, Soferets-sønerne, Perida-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Ja’ala-sønerne, Darkons-sønerne, Giddels-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sefatja-sønerne, Hattils-sønerne, Pokeret-Hassebajims-sønerne, Amons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Alle tempelsveinarne og sønerne åt Salomo-sveinarne var i alt tri hundrad og tvo og nitti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Frå Tel-Melah og Tel-Harsa, Kerub og Addon og Immer for dei ut dei som her skal nemnast; men dei kunde ingi greida gjeva um federne sine og ætti, - um dei i det heile høyrde Israels-folket til; det var:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delaja-sønerne, Tobia-sønerne og Nekoda-sønerne, seks hundrad og tvo og fyrti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'og av prestarne: Habaja-sønerne, Hakkos-sønerne, sønerne åt Barzillai, han som hadde teke ei av døtterne åt Gileads-mannen Barzillai til kona og fekk namn etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Desse leita etter ættartavlorne sine, men kunde ikkje finna deim; difor vart dei kjende uverdige til å vera prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Jarlen dømde at dei ikkje måtte eta av det høgheilage fyrr det stod fram ein prest med urim og tummim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Heile lyden var i alt tvo og fyrti tusund tri hundrad og seksti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'umfram trælarne og trælkvinnorne; talet på deim var sju tusund tri hundrad og sju og tretti. Dertil kom tvo hundrad og fem og fyrti songarar, karar og kvende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Dei hadde sju hundrad og seks og tretti hestar, tvo hundrad og fem og fyrti muldyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'fire hundrad og fem og tretti kamelar, og seks tusund sju hundrad og tjuge asen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Nokre av ættehovdingane ytte pengehjelp til arbeidet. Jarlen lagde i kassa fem tusund dalar i gull, femti skåler, og fem hundrad og tretti prestekjolar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Og nokre av ættarhovdingarne lagde i byggjekassa hundrad tusund dalar i gull og seks og seksti tusund dalar i sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Og det som hitt folket gav, var hundrad tusund dalar i gull, seksti tusund dalar i sylv, og sju og seksti prestekjolar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Prestarne og levitarne og dørvaktarane og songarane, og nokre av lyden, og tempelsveinarne og heile Israel elles sette då bu i sine byar. Då den sjuande månaden kom, var Israels-sønerne i sine byar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Då samla heile folket seg, alle som ein mann på torget midt for Vatsporten. Dei bad Ezra, den skriftlærde, henta boki med Moselovi som Herren hadde bode Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Då bar presten Ezra lovi fram for lyden, for menner og kvinnor og alle som kunde skyna det dei høyrde. Det var fyrste dagen i sjuande månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Han las upp or henne frå dagsprett til middag, ved torget framfor Vatsporten, for menner og kvinnor og deim som kunde skyna det; og alt folket lydde på lovboki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Ezras, den skriftlærde, stod på ein tram av tre som dei hadde laga til det. Jamsides med honom stod Mattitja, Sema, Anaja, Uria, Hilkia og Ma’aseja på høgre sida, og på vinstre sida Pedaja, Misael, Malkia, Hasum, Hasbaddana, Zakarja og Mesullam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ezra opna boki so alle såg det; for han stod høgare enn dei alle. Og med same han opna, reis dei alle upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Ezra lova Herren, den store Gud, og heile folket svara: «Ja, ja!» - med di dei rette upp henderne. Dei bøygde seg og kasta seg å gruve på jordi for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Og Jesua, Bani, Serebja, Jamin, Akkub, Sabbetai, Hodia, Ma’aseja, Kelita, Azarja, Jozabad, Hanan, Pelaja og dei hine levitarne tolka lovi for folket, medan folket vart standande kvar på sin stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Dei las tydeleg or boki, or Guds lov; og lagde ut meiningi, so folket kom til å skyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Nehemia, jarlen, og den skriftlærde presten Ezra, og levitarne, som lærde folket, sagde til alt folket: «Denne dagen er heilag for Herren, dykkar Gud. Syrg ikkje og gråt ikkje!» For heile folket gret då dei høyrde dei ordi i lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Og han sagde til deim: «Gakk no og et den beste mat, og drikk den søtaste vin de hev! Og send gåvor til den som inkje hev! For denne dagen er heilag for vår Herre. No skal de ikkje syta. Gleda i Herren er dykkar faste borg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Ogso levitarne hysja på alt folket og sagde: «Ver stille, dagen er heilag, de må ikkje syta!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Då gjekk heile folket burt og åt og drakk og sende gåvor ikring og heldt ei stor gledehøgtid; dei hadde lagt seg på hjarta det som var sagt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Dagen etter, då ættehovdingarne i heile folket og prestarne og levitarne samla hjå den skriftlærde Ezra og vilde få meir greida på ordi i lovi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'då fann dei skrive i lovi, at Herren hadde bode ved Moses at Israels-borni skulde bu i lauvhyttor på høgtidi i sjuande månaden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'og at dei skulde kunngjera og ropa ut i alle byarne sine og i Jerusalem: «Far til fjells og henta lauv av planta oljetre og ville oljetre, myrt og palmor og andre lauvrike tre og bygg lauvhyttor, som fyreskrive er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Då gjekk folket ut og henta, og bygde seg lauvhyttor på tak og på tun, kvar heime hjå seg, og i tuni ved Guds hus og på torgi ved Vatsporten og Efraimsporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Heile lyden, alle som var heimkomne frå utlægdi, bygde seg lauvhyttor og budde i deim. Sidan dei dagarne då Jesua Nunsson livde og like til denne dagen hadde Israels-borni ikkje gjort det. Og der var ovleg stor gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Kvar dag las dei upp or Guds lovbok, frå fyrste dagen til siste; dei heldt høgtig i sju dagar, og på den åttande heldt dei stor samlingshøgtid, etter fastsett skikk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Den fire og tjugande dagen i same månaden kom Israels-borni saman og heldt fasta. Dei hadde klædt seg i sorg og hadde mold på hovudi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Israels-ætti skilde seg ut frå alle framandfolket, steig fram og sanna synderne sine og syndeskuldi åt federne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'So reis dei upp kvar på sin stad medan det vart fyrelese or lovboki åt Herren, deira Gud. Det var ei øykt. Ei onnor øykt sanna dei synderne og kasta seg ned for Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Jesua og Bani, Kadmiel, Sebanja, Bunni, Serebja, Bani og Kenani steig upp på levittramen og ropa med høg røyst til Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Og levitarne Jesua og Kadmiel, Bani, Hasabneja, Serebja, Hodia, Sebanja og Petahja sagde: «Ris upp og lova Herren, dykkar Gud, han som er frå æva og til æva! Ja, lova vere ditt heilage namn, som er upphøgt yver alt lov og pris!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Einast du er Herren. Du hev skapt himmelen, ja, himle-himlarne og all deira her, jordi og alt som på henne er, havi og alt som i deim er. Det er du som held liv i deim alle. Og himmelheren kastar seg ned for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Det var du, Herre Gud, som valde ut Abram og førde honom frå Ur i Kaldæa og gav honom namnet Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Og du fann hjarta hans trufast for di åsyn då du gjorde du den pakti med honom at du vilde gjeva ætti hans landet åt kananiten, hetiten, amoriten, periziten, jebusiten og girgasiten. Og du heldt det du lova. For du er rettferdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Du såg kor vondt federne våre hadde det i Egyptarland, og du høyrde ropet deira ved Raudehavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Du gjorde teikn og under med Farao og alle tenarane hans og heile landslyden hans; for du visste at dei hadde fare ovmodigt åt med deim. Og soleis vann du deg eit namn som vert nemnt heilt til i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Du kløyvde havet for deim, sog dei gjekk turrskodde gjenom havet. Men dei som elte deim, deim let du søkka i djupet som stein i velduge vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Du leidde deim um dagen med ein skystopul, og um natti med ein eldstopul til å lysa for deim på den vegen dei skulde fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Du steig ned på Sinaifjellet og tala med deim frå himmelen. Du gav deim rettferdige rettar, pålitande lover, gode fyreskrifter og bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Du gav deim kunnskap um den heilage kviledagen din, og bod og fyreskrifter og lov ved Moses, tenaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Brød frå himmelen gav du deim når dei var svoltne, og vatn or berget let du fløyma når dei var tyrste. Og du baud deim fara av og leggja under seg landet du med handi i veret hadde svore å gjeva deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Men federne våre, dei var kante og hardnakka, og lydde ikkje bodi dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Dei vilde ikkje lyda. Dei agta ikkje på dei underi du hadde gjort med deim, men gjorde nakken stiv, valde seg ein hovding og vilde tråssuge fara attende til trældomen sin. Men du er ein Gud som tilgjev synd, kjærleg og mild, tolug og full av nåde; du slepte deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Ja, endå dei støypte seg ein kalv og sagde: «Dette er guden din, som fylgde deg ut or Egyptarland,» endå dei spotta deg so gruvelegt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'so vilde du i di store miskunn ikkje sleppa deim der i øydemarki. Skystopulen veik ikkje frå deim um dagen, men leidde deim på veg; ikkje heller veik eldstopulen frå deim um natti, men lyste for deim på den vegen dei skulde fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Din gode ande sende du deim til lærar. Du meinka ikkje munnen deira i å få din manna; og når dei var tyste, gav du deim vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Fyrti år bar du umsut for deim i øydemarki, og ingen ting vanta dei. Klædi deira vart ikkje slitne, og føterne deira trutna ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Kongerike og folkeslag gav du deim i gåva, og skifte ut landsluter åt deim på alle leider. Dei hertok Sihons land, det landet som høyrde til kongen i Hesbon, og landet som høyrde til Og, kongen i Basan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Og du auka ætti deira som stjernorne på himmelen, og du leide deim inn i det landet du lova federne deira til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'So kom då sønerne og hertok landet. Du kua kananitarne for deim; deim som budde i landet, bøygde du under deim og gav i deira hender, både kongarne og folki der i landet, so dei kunde gjera med deim etter eige tykkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Dei hertok borgerne og reiv til seg den feite jordi, eigna til seg hus fulle av alle gode ting, tok gravne brunnar, vinhagar, oljeplantingar og aldetre i mengd. Dei åt og vart mette og feite og gjorde seg glade dagar av din store rikdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Men dei gjorde seg harde og sette upp imot deg, og kasta di lovi bak ryggen sin. Dei drap profetarne dine, som vitna for deim og vilde venda deim um til deg; dei spotta deg gruveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Då gav du deim i fiendevald, og valdsverk fekk dei røyna. Men når dei var i verste vande, ropa dei til deg, og du høyrde på deim frå himmelen. I di store miskunn sende du deim frelsarar som fria deim ut or fiendevald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Kom dei so til ro, gjorde dei atter det som vondt var for di åsyn. Då let du deim i fiendevald, so dei vart trælka. Men når dei so ropa til deg att, so høyrde du på deim frå himmelen og fria deim ut, etter di store miskunn gong på gong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Du vitna for deim um at dei skulde venda um til di lov; men dei var kaute og lydde ikkje bodi dine. Og dei synda mot rettarne dine, dei som det gjeld um, at når menneskja held deim, skal ho få liva ved deim. Tråssuge snudde dei ryggen til, gjorde seg hardnakka og vilde ikkje lyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Mange år tøygde du tolmod med deim, og vitna for deim ved din ande gjenom profetarne dine. Då dei ikkje vilde høyra, gav du deim framande folk i vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Men i di store miskunn gjorde du ikkje heilt ende på deim, og gav deim ikkje upp; for du er ein mild og kjærleg Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Og no, vår Gud, du store, velduge, skræmelege Gud, du som held pakti og held uppe miskunni, no må du ikkje tykkja det er lite alt det vonde me hev lote lida, me og kongarne våre, hovdingarne, prestarne og profetarne våre, federne våre og heile folket ditt, frå assyrarkongarne si tid og alt til i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Du er rettferdig i alt det som hev kome yver oss. Du hev synt deg trufast. Me hev fare ugudleg åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Kongarne våre, hovdingarne våre, prestarne våre, federne våre hev ikkje halde lovi di og hev ikkje agta på bodi dine og dei åtvaringsordi du gav deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Jamvel då dei budde i sitt eige rike og i den store rikdomen som du hadde gjeve deim, og i det vide og feite landet som du hadde lagt ope for deim, tente dei deg ikkje, og vende ikkje um frå si vonde åtferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Sjå no um dagen er me trælar. I det landet du gav federne våre til å njota landsens grøda og rikdom, sjå her er me trælar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Si rike grøda ber det til bate for dei kongar som du sette yver oss for våre synder skuld. Og dei råder og rikjer etter eige tykkje yver kropparne våre og buskapen vår. Me er i stor naud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'På grunn av alt dette gjer me eit fast samband, som me skriv upp; og på det forsigla brevet stend: Hovdingarne, levitarne og prestarne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'På dei forsigla stykki stend: Nehemia, jarlen, son åt Hakalja, og Sidkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Azarja, Jeremia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amarja, Malkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebanja, Malluk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremot, Obadja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginneton, Baruk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abia, Mijjamin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Ma’azja, Bilgai og Semaja; dette er prestarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Og levitarne: Jesua Azanjason, Binnui av Henadads-sønerne og Kadmiel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'og brørne deira: Sebanja, Hodia, Kelita, Pelaja, Hanan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Mika, Rehob, Hasabja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakkur, Serebja, Sebanja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodia, Bani og Beninu.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Folkehovdingarne: Paros, Pahat-Moab, Elam, Zattu, Bani,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Azgad, Bebai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonja, Bigvai, Adin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hizkia, Azzur,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodia, Hasum, Besai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Harif, Anatot, Nobai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Hezir,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesezabel, Sadok, Jaddua,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatja, Hanan, Anaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hosea, Hananja, Hassub,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallohes, Pilha, Sobek,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Ma’aseja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahia, Hanan, Anan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluk, Harim og Ba’ana.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Og folket elles, prestarne, levitarne, portvaktarane, songarane, tempelsveinarne og alle som hev skilt seg frå dei framande folki og vendt seg til Guds lov, like eins konorne deira, sønerne og døtterne deira, alle som kann skyna det -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'dei slær lag med stormennene og gjeng med på eiden og sver at dei vil fylgja Guds lov, som er gjevi ved Guds tenar Moses, og halda og gjera etter alle bodi og rettarne og fyreskrifterne frå Herren, vår Herre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'at me ikkje skal gifta døtterne våre med folki i landet eller taka døtterne deira til konor åt sønerne våre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'og når folki i landet kjem um kviledagen og vil selja handelsvaror og allslags korn, då skal me ikkje kjøpa av deim på kviledag eller helgedag; at me let jordi liggja og kvila kvart sjuande år, og då gjev etter allslags krav;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'att me tek på oss skyldnaden å svara ein tridjepart av ein dalar i årleg reida til tenesta i vår Guds hus -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'til skodebrødi, det faste grjonofferet og det faste brennofferet, til offer på kviledagarne, på nymånedagarne og i høgtiderne, til takkofferet og syndofferet til soning for Israel, og til alle tenester i vår Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Um vedhaldet hev me, prestarne, levitarne og folket, drege strå, um å føra veden til vår Guds hus, etter ættgreinerne våre, kvart år på visse dagar, til brennefang på altaret åt Herren, vår Gud, som fyreskrive er i lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Me vil års årleg føra til Herrens hus det fyrste av grøda på marki vår og dei fyrste mogne frukterne på alle slag tre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'og det som er frumbore av folk og fe, som skrive er i lovi, og føra det frumbore av storfe og småfe til Herrens hus, til prestarne som gjer tenesta i vår Guds hus;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'like eins det fyrste gropet med mel, og reidorne våre, og frukti av alle tre, og druvesaft og olje vil me føra til prestarne, til kovarne i vår Guds hus; like eins tiendi av marki vår til levitarne. Levitarne samlar sjølv inn tiendi i alle jordbruksbyarne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Ein prest, ein av Arons-sønerne, er med levitarne når dei samlar inn tiendi; og sjølve fører levitarne tiendeparten av tienden si upp til vår Guds hus, til kovarne i forrådshuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Både Israels-sønerne og Levi-sønerne føre reidorne av korn og druvesaft og olje til kovarne, der kjeraldi er som høyrer til heilagdomen, og der prestarne som gjer tenesta, og like eins portvaktarane og songarane. - Soleis vil me ikkje gløyma vår Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Hovdingarne budde i Jerusalem. Hitt folket drog strå, soleis at tiande kvar mann skulde bu i Jerusalem, den heilage byen, og ni tiandepartar skulde bu i dei hine byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Folket velsigna alle dei mennerne som friviljugt busette seg i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Dette er dei hovdingarne i jarleriket som budde i Jerusalem; men i Juda-byarne budde kvar i sin by der han hadde sin eigedom, vanlege israelitar, prestar, levitar, tempelsveinarne og søner etter Salomos trælar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'I Jerusalem budde nokre av Juda-sønerne og av Benjamins-sønerne. Av Juda-sønerne: Ataja, son åt Uzzia, son åt Zakarja, son åt Amarja, son åt Sefatja, son åt Mahalalel, av Peres-sønerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'og Ma’aseja, son åt Baruk, son åt Kol-Hoze, son åt Hazaja, son åt Adaja, son åt Jojarib, son åt Zakarja, son åt siloniten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Peres-sønerne i Jerusalem, var i alt fire hundrad og åtte og seksti stridsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Og dette var Benjamins-sønerne: Sallu, son åt Mesullam, son åt Joed, son åt Pedaja, son åt Kolaja, son åt Ma’aseja, son åt Itiel, son åt Jesaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'og etter honom Gabbai-Sallai, i alt ni hundrad og åtte og tjuge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Joel Zikrison var formannen deira, og Juda Hassenuason var den næst øvste i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Av prestarne: Jedaja Jojaribsson, Jakin');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'og Seraja, son åt Hilkia, son åt Mesullam, son åt Sadok, son åt Merajot, son åt Ahitub, den øvste i Guds hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'og brørne deira, som gjorde tenesta i Guds hus, åtte hundrad og tvo og tjuge i alt, og Adaja, son åt Jeroham, son åt Pelalja, son åt Amsi, son åt Zakarja, son åt Pashur, son åt Malkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'og brørne hans, ættehovdingar, tvo hundrad og tvo og fyrti, og Amassai, son åt Azarel, son åt Ahzai, son åt Mesillemot, son åt Immer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'og brørne deira, hundrad og åtte og tjuge dugande menner. Formannen deira var Zabdiel, son åt Haggedolim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Av levitarne: Semaja, son åt Hassub, son åt Azrikam, son åt Hasabja, son åt Bunni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'og Sabbetai og Jozabad, levithøvdingar som styrde med utearbeidet ved Guds hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'og Mattanja, son åt Mika, son åt Zabdi, son åt Asaf, fyresongaren, han som tok i med lovsongen i bøni, og Bakbukja, næst-høgst av brørne hans, og Abda, son åt Sammua, son åt Galal, son åt Jedutun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Levitarne i den heilage byen var i alt tvo hundrad og fire og åtteti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Og portvaktarane: Akkub, Talmon og brørne deira, som heldt vakt ved portarne, i alt hundrad og tvo og sytti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Dei andre israelitarne, prestarne og levitarne budde i alle dei andre byarne i Juda, kvar på sin eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Men tempelsveinarne budde på Ofel, og Siha og Gispa var formennerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Levit-formannen i Jerusalem, ved tenesta i Guds hus, var Uzzi, son åt Bani, son åt Hasabja, son åt Mattanja, son åt Mika, av Asafs-sønerne, songarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Eit kongebod var gjeve um deim, og ein fast skipnad sett åt songarane for kvar dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petahja, son åt Mesezabel, av sønerne åt Zerah Judason, målbar for kongen alle saker som galdt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Og ute på landsbygdi budde og ein part av Juda-ætti: i Kirjat-Arba og bygderne der ikring, i Dibon og bygderne der ikring, og i Jekabse’el med sine grender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'i Jesua og Molada og Bet-Pelet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'i Hasar-Sual, i Be’erseba med sine bygder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'og i Siklag, og i Mekona med sine bygder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'i En-Rimmon og Sora og Jarmut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoah, Adullam og bygderne ikring deim, i Lakis og bumarki som høyrde til, og i Azeka med sine bygder. Dei busette seg frå Be’erseba til Hinnomsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Benjamins-sønerne hadde sine bustader frå Geba: i Mikmas og Ajja, i Betel med sine bygder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'i Anatot, Nob, Ananja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hasor, Rama, Gittajim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Sebojim, Neballat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod og Ono, Handverkardalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Nokre skift av levitarne som høyrde til Juda, busette seg i Benjamin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Dette er dei prestarne og levitarne som for heim med Zerubbabel Sealtielsson og Jesua: Seraja, Jirmeja, Ezra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluk, Hattus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekanja, Rehum, Meremot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnetoi, Abia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijjamin, Ma’adja, Bilga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkia og Jedaja. Dette var hovdingarne for prestarne og for brørne sine på Jesuas tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Og levitarne var: Jesua, Binnui, Kadmiel, Serebja, Juda, Mattanja, som saman med brørne sine styrde med lovsongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'medan Bakbukja og Unno, brørne deira, stod midt fyre deim etter vaktskift.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua fekk sonen Jojakim, Jojakim fekk sonen Eljasib, og Eljasib Jojada.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada fekk sonen Jonatan, og Jonatan Jaddua.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'På Jojakims tid var desse hovdingar for preste-ættarne: For Seraja Meraja, for Jeremia Hananja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'for Ezra Mesullam, for Amarja Johanan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'for Meluki Jonatan, for Sebanja Josef,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'for Harim Adna, for Merajot Helkai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'for Iddo Zakarja, for Ginneton Mesullam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'for Abia Zikri, for Minjamin, for Moadja Piltai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'for Bilga Sammua, for Semaja Jonatan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'for Jojarib Mattenai, for Jedaja Uzzi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'for Sallai Kallai, for Amok Eber,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'for Hilkia Hasabja, for Jedaja Netanel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'I Eljasibs, i Jojada og Johanan og Jaddua si tid, vart hovdingarne for levitættgreinerne uppskrivne; like eins prestarne i styringstidi åt persaren Darius.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Levi-sønerne, ættarhovdingarne, er uppskrivne i krønikeboki heilt fram til dagarne hans Johanan Eljasibsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Levithovdingarne var: Hasabja, Serebja og Jesua Kadmielsson og brørne deira, som stod midt imot deim og song lovsongen og takkesongen, etter som gudsmannen David hadde bode, ein songarflokk attmed hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattanja, Bakbukja, Obadja, Mesullam, Talmon og Akkub var portvaktarar og heldt vakt ved upplagsromi ved portarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Dette var ættarhovdingarne i dagarne hans Jojakim, son åt Jesua Josadaksson, og i jarlen Nehemia og den skriftlærde presten Ezra si tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Då muren kring Jerusalem skulde verta vigd, henta dei levitarne frå alle bustaderne deira og førde deim til Jerusalem, til å halda vigsla og gledehøgtid med lov og song, med cymblar og harpor og cithrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Då samla songar-sønerne seg frå kverven kring Jerusalem og frå netofatitgardarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'frå Bet-Haggilgal og frå landet kring Geba og Azmavet; songarane hadde bygt seg gardar rundt ikring Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Prestarne og levitarne reinsa seg, og dei reinsa folket og portarne og muren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Eg let hovdingarne i Juda stiga upp på muren. So skipa eg tvo store songkorar og festferder. Den eine gjekk til høgre uppå muren fram mot Møkporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Etter dei gjekk Hosaja og den eine helvti av Juda-hovdingarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'og so Azarja, Ezra, Mesullam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Semaja og Jeremia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'like eins nokre av prestesønerne med lurar; dinæst Zakarja, son åt Jonatan, son åt Semaja, son åt Mattanja, son åt Mikaja, son åt Zakkur, son åt Asaf,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'og so brørne hans: Semaja, Azarel, Milalai, Gilalai, Ma’ai, Netanel, Juda, og Hanani med spelgognerne åt gudsmannen David. Den skriftlærde Ezra gjekk fyre deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Dei gjekk yver Kjeldeporten og beint upp tropperne til Davidsbyen, der ein stig upp på muren ovanfor Davidshuset, heilt fram til Vatsporten i aust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Den andre songkoren gjekk til vinstre, og der fylgde eg og den andre helvti av folket uppå muren, yver Omnstårnet burt til den breide muren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'yver Efraimsporten, Gamleporten og Fiskeporten, gjenom Hananeltårnet og Hammeatårnet, heilt fram til Saueporten. Dei stana ved Fengselsporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'So stelte dei seg upp i Guds hus båe songkorarne; like eins eg og helvti av formennerne med meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'og prestarne Eljakim, Ma’aseja, Minjamin, Mikaja, Eljoenai, Zakarja og Hananja med lurar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'og Ma’aseja, Semaja, Eleazar, Uzzi, Johanan, Malkia, Elam og Ezer. Og songarane let songen ljoma, og føraren deira var Jizrahja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Dei ofra den dagen store offer og gledde seg; for Gud hadde kveikt gleda hjå folket; ogso kvinnorne og borni gledde seg. Og gleda frå Jerusalem høyrdest langan leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Samstundes vart det uppnemt menner til å hava tilsyn med upplagsromi for reidorne, fyrstegrøda og tiendi, til å gøyma der det som lovi heimla prestarne og levitarne frå bymarkerne. Dei var fegne i Juda for at prestarne og levitarne gjorde tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Og dei tok vare på det som var til å taka vare på ved gudstenesta og reinsingarne. Like eins gjorde songarane og portvaktarane sine tenestor, soleis som David og Salomo, son hans, hadde bode;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'for alt i gamall tid, i Davids dagar, og songarhovdingen Asafs dagar, ljoda lovsongar og takkesongar til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Og i Zerubbabels og Nehemias dagar gav heile Israel songarane og portvaktarane dei reidorne dei skulde hava frå dag til annan. Levitarne fekk sine heilage gåvor, og dei reidde ut heilage gåvor til Arons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'På den tidi las dei upp for folket or Moseboki, og dei fann det skrive der at ingen ammonit eller moabit nokon sinn måtte vera med i Guds lyd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'for di dei ikkje hadde kome imot Israels-borni med brød og vatn, og for di dei hadde leigt imot deim Bileam til å lysa våbøn yver deim; endå vår Gud vende våbøni um til velsigning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Då dei høyrde lovi, skilde dei ut frå Israel allslag framandfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Men fyrr dette hende, hadde presten Eljasib, som stod i skyldskap til Tobia, fenge tilsynet med kovarne i Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Og han hadde innreidt ein stor kove åt honom der dei fyrr hadde gøymt grjonofferet, røykjelsen, kjeraldi, tiendi, korn, druvesaft og olje, dei lovheimla avgifterne til levitarne og songarane og portvaktarane, og prestereidorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Då alt dette gjekk fyre seg, var ikkje eg i Jerusalem; i det tvo og trettiande styringsåret åt Babel-kongen Artahsasta var eg attkomen til kongen. Men då ei tid var lidi, bad eg kongen um heimlov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Då eg so kom til Jerusalem, gådde eg det vonde Eljasib hadde gjort, med å reida inn åt Tobia ein kove i tuni ved Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Eg tykte fælt ille um det, og eg kasta ut or koven all husbunaden hans Tobia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Eg baud at dei skulde reinsa kovarne. Og so fekk eg inn att gognerne til Guds hus, grjonofferet og røykjelsen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Framleides fekk eg greida på at levitarne ikkje fekk avgifterne sine, og at difor levitarne og songarane hadde flutt ut på landet til kvar sin eigedom, i staden for å gjera tempeltenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Då skjemde eg på formennerne og sagde: «Kvifor hev Guds hus vorte gløymt?» Eg stemnde deim saman og sette deim inn att kvar på sin stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Og heile Juda førde fram til upplagsromi tiendi av korn og druvesaft og olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Tilsynet med upplagsromi gav eg til presten Selemja og den skriftlærde Sadok og ein levit, Pedaja; til hjelpesmann gav eg deim Hanan, son åt Zakkur Mattanjason; for dei vart haldne for pålitande. Til deim låg det no å skifta ut til brørne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Kom meg i hug for dette, min Gud, og lat ikkje dei kjærleiksgjerningar verta gløymde som eg hev gjort for min Guds hus og tenesta der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Samstundes såg eg i Juda kor dei trødde vinpersa um kviledagen, kor dei bar heim kornbandi og klyvja deim på asni, like eins vin, druvor, fikor og allslags varor, og førde til Jerusalem um kviledagen. Eg vara deim åt den dagen dei selde desse matvaror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Tyrus-folk som hadde busett seg der, kom ogso med fisk og allslag varor og selde til jødarne um kviledagen, og det i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Då skjemde eg på adelsmennerne i Juda, og sagde til deim: «Korleis kann de fara so ille og vanhelga kviledagen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Var det ikkje av di federne dykkar for åt like eins, at vår Gud førde all denne ulukka yver oss og yver denne byen? Og no aukar de endå meir harmen hans mot Israel, med å vanhelga kviledagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'So snart det tok til å myrkna i portarne i Jerusalem fyre kviledagen, gav eg bod um å læsa portarne, og ikkje opna deim att fyrr kviledagen var liden. Eg sette nokre av drengjerne mine på vakt ved portarne, so ingen skulde føra inn nokor byrd um kviledagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Kjøpmenner og handlarar med allslags torgvaror natta utanfor Jerusalem både ein og tvo gonger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Men eg vara deim åt og sagde: «Kva skal det vera til at de nattar utanfor muren? Gjer de det ein gong til, so skal de få kjenna neven min.» Frå den tidi kom dei ikkje meir um kviledagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Eg baud levitarne reinsa seg og so koma og halda vakt ved portarne, so kviledagen kunde haldast heilag. Ogso for dette må du koma meg i hug, min Gud, og miskunna meg etter din store nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Samstundes såg eg kor jødarne hadde gift seg med asdoditiske, ammonitiske og moabitiske kvinnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Helvti av borni deira tala Asdod-mål eller tungemålet til dei andre folki, og kunde ikkje tala jødisk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Eg skjemde på deim og banna deim, ja, eg slog og lugga sume av deim. Og eg tok deim i eid ved Gud og sagde: «Ikkje må det gifta døtterne dykkar med sønerne deira og ikkje taka døtterne deira til konor åt sønerne dykkar eller åt dykk sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Var det ikkje for deira skuld at Salomo, Israels konge, synda? Det fanst ikkje makan til konge millom dei mange folki. Hans Gud elska honom, og Gud sette honom til konge yver heile Israel. Jamvel honom fekk dei framande kvinnorne til å synda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Skal det verkeleg verta spurt at de hev gjort all denne store vondskap og vore utrue mot vår Gud og gift dykk med framande kvinnor?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Ein av sønerne åt Jojada, son åt øvstepresten Eljasib, var mågen åt horoniten Sanballat; honom jaga eg burt frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Kom deim i hug, min Gud, for di dei hev sulka til prestedømet og pakti um prestarne og levitarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Soleis reinsa eg deim for alt framandt. Eg fastsette tenestorne for prestarne og levitarne, det kvar skulde ha umsut med i sitt arbeid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'og korleis det skulde vera med vedofferet til visse tider og med fyrstegrøda. Kom meg i hug for dette, min Gud, og rekna meg det til godes!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Det hende seg i styringstidi åt Ahasveros - som rådde frå India alt til \'tiopia yver eit hundrad og sju og tjuge jarlerike -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'i dei dagarne då kong Ahasveros sat på kongsstolen i borgi Susan:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'i det tridje styringsåret hans gjorde han eit gjestebod for alle hovdingarne og tenarane sine, medan heren frå Persia og Media var samla hjå honom, saman med storfolket og jarlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'I mange dagar, eit hundrad og åtteti dagar, synte han deim sin kongelege rikdom og herlegdom og stordom med all dramb og drust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Då dei dagarne var lidne, gjorde kongen eit gjestebod i sju dagar for alt folket som fanst i borgi Susan, frå den høgste til den lægste, i den inngjerde hagen ved kongsborgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Der hekk tjeld av kvitt lin og bomull og purpurblått ty, feste med kvite og purpur-raude snorer til sylvringar på kvite marmorsulor. Der stod benkjer av gull sylv, på eit golv av grønt og kvitt marmor og perlemorstein og svart stein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Drykkjerne vart skjenkte i gullstaup, kvart staup hadde sers skap. Og der var nøgdi av kongeleg vin, på kongevis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Den fyresegni vart sett drikkingi, at ingen skulde nøydast; kongen hadde bode alle hovmeistrarne at dei skulde lata kvar mann få so mykje han sjølv hadde hug på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Dronning Vasti gjorde samstundes eit gjestebod for kvinnorne i det kongelege huset åt kong Ahasveros.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Sjuande dagen då kongen var fjåg av vinen, baud han dei sju hirdmennerne som gjorde tenesta hjå kong Ahasveros: Mehuman, Bizta, Harbona, Bigta, og Abagta, Zetar og Karkas,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'at dei skulde henta dronning Vasti og leida henne fram for kongen, med kongskruna på, so han kunde syna fram vænleiken hennar for folki og for hovdingarne; for ho var fager å sjå til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Men dronning Vasti vilde ikkje koma, tråss i det kongsbodet hirdmennerne bar fram. Då vart kongen veldugt vreid, og harmen loga upp i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Kongen sagde til vismennerne, dei som hadde vit på tiderne - soleis vart alle kongssakar framlagde for deim som hadde vit på lov og rett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'og dei som stod honom næmast, var Karsena, Setar, Admata, Tarsis, Meres, Marsena og Memukan, dei sju hovdingarne i Persia og Media, som stod kongen næmast, og åtte øvste sæti i riket -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '«Kva skal det etter lovi gjerast med dronning Vasti, sidan ho ikkje lyder det bodet kong Ahasveros sende henne med hirdmennerne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Memukan tok til ords for kongen og hovdingarne: «Dronning Vasti hev ikkje berre forbrote seg mot kongen, men mot alle hovdingarne og alle folki i alle jarleriki åt kong Ahasveros.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Åtferdi hennar vil koma ut millom alle konorne, og vil føra til at dei vanvyrdar mennerne sine; for dei vil segja: «Kong Ahasveros baud at dei skulde føra dronning Vasti fram for honom, men ho kom ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Ja, alt i dag vil hovdingfruorne i Persia og Media høyra gjete åtferdi til dronningi og svara alle kongens hovdingar sameleis, og det vil verta nok av vanvyrdnad og harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Tekkjest det kongen, so lat eit kongebod verta utferda, og uppskrive millom loverne i Persia og Media, so det stend uruggeleg fast, at Vasti skal aldri meir koma fram for kong Ahasveros; hennar kongelege stand gjev kongen til ei onnor, som er likare enn ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Når dette kongelege påbodet vert utferda og kunngjort i heile kongens rike, so vida det rekk, då vil alle konor syna mennerne sine æra, frå dei høgste til dei lægste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Dette ordet lika kongen og stormennerne godt, og kongen gjorde som Memukan hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Brev vart sende til alle jarledømi åt kongen, til kvart jarledøme med deira skrift og til kvart folk på deira tungemål: at kvar mann skulde vera herre i sitt hus, og tala sitt eige folkemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Etter ei tid var gjengi og sinne hadde runne av kong Ahasveros, tenkte han på Vasti, og åtferda hennar, og domen yver henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Hirdmennerne som gjorde tenesta hjå kongen, sagde då: «Lat folk leita upp åt kongen fagre ungmøyar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Lat kongen setja folk i alle kongens jarlerike til å samla alle fagre ungmøyar til kvendehuset i borgi Susan under tilsyn av kongens hirdmann Hege, kvendevaktaren, so dei kann få det dei treng til å hama seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Den ungmøyi som kongen likar, ho skal då verta dronning i staden for Vasti.» Dette tykte kongen vel um, og han so gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'I borgi Susan var det ein jøde som heitte Mordokai, son åt Ja’ir, son åt Sime’i, son åt Kis, av Benjamins-ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Han var burtførd frå Jerusalem millom dei fangarne som vart burtførde saman med Juda-kongen Jekonja, dei som Babel-kongen Nebukadnessar førde burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Han var fosterfar åt Hadassa, som og heitte Ester, dotter åt farbror hans; ho åtte korkje far eller mor. Gjenta var velvaksi og væn. Og då foreldri hennar døydde, tok Mordokai henne til seg som si eigi dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Då kongebodet og fyreseigni vart kunngjort, og dei samla saman mange ungmøyar i borgi Susan under tilsyn av Hegai, henta dei ogso Ester til kongshuset under tilsyn av kvendevaktaren Hegai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Han lika gjenta godt og fann hugnad i henne. Difor skunda han seg å gjeva henne alt turvande til å hama seg, like eins gav han henne den maten ho skulde hava, og dei sju ternor ho skulde hava frå kongshuset. Han let henne og ternorne hennar flytja inn i beste romet i kvendehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester gat ikkje eit ord um folket sitt eller ætti si; Mordokai hadde sagt henne fyre å tegja um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Kvar einaste dag gjekk Mordokai att og fram utanfor garden ved kvendehuset, han vilde få vita kor det stod til med Ester, og kor det gjekk henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kvar ungmøy kom inn til kong Ahasveros etter tur. Det gjekk tolv månader til å stella med deim etter påbodet um kvendi: seks månader med myrra-olje, og seks månader med angande salvar og anna som kvende treng til å hama seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Når so ungmøyi gjekk inn til kongen, fekk ho med seg frå kvendehuset til kongshuset alt det ho ynskte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Um kvelden gjekk ho inn; um morgonen gjekk ho attende, men då til eit anna kvendehus, under tilsyn av kongens hirdmann Sa’asgaz, vaktaren yver fylgjekonorne. Ho fekk då ikkje koma inn att til kongen, minder kongen lika henne so godt, at han sende bod etter henne med namns nemning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Då radi kom til Ester, dotter åt Abiha’il, som var farbror åt Mordokai, fosterfar hennar, so kravde ho ikkje anna med seg enn det hirdmannen Hegai, kvendevaktaren, rådde til. Og alle som såg Ester, fann hugnad i henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ester vart henta til kong Ahasveros i kongshuset hans i den tiande månaden, månaden tebet, i sjuande styringsåret hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Kongen vart gladare i Ester enn i alle dei andre kvendi; ho vann meir hugnad og godhug hjå honom enn alle dei andre ungmøyarne. Han sette kongskruna på hovudet hennar og gjorde henne til dronning i staden for Vasti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Og kongen gjorde eit stort gjestebod for alle hovdingarne og tenarane sine, eit Ester-gjestebod, og han gav skattelette i alle jarleriki og gav gåvor med kongeleg raustleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Andre gongen samla dei saman ungmøyar, og Mordokai sat då kongsporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ester hadde ikkje gjete ord um ætti si og folket sitt, etter pålegget frå Mordokai; Ester lydde framleides bodet hans Mordokai, like eins som då ho vart fostra hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Den tid Mordokai sat i kongsporten, vart Bigtan og Teres, tvo konglege hirdmenner som heldt vakt ved dørstokken, harme og freista finne høve til å leggja hand på kong Ahasveros.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Mordokai fekk vita dette, og sagde det med dronning Ester; so nemde Ester det med kongen på Mordokais vegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Saki vart granska, og det viste seg at det var sant, og dei tvo vart hengde i ein galge. Dette vart uppskrive i krønikeboki for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Ei tid etter gjorde kong Ahasveros agagiten Haman Hammedatason stor og gav honom rang og sæte yver alle hovdingarne som var hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Og alle kongens tenarar som var i kongsporten, fall på kne og kasta seg ned for Haman; so hadde kongen sagt fyre om honom. Men Mordokai fall ikkje på kne og kasta seg ikkje ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Kongens tenerar som var i kongsporten spurde Mordokai: «Kvifor gjer du imot kongens påbod?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Dag etter dag kom dei med dette spørsmålet; men han høyrde ikkje på deim. So melde dei det for Haman, dei vilde sjå um den forklåring Mordokai gav, fekk gjelda; for han hadde fortalt deim at han var jøde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Då Haman gådde at Mordokai ikkje fall på kne og ikkje kasta seg ned for honom, då vart han full av harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Men han tykte det var for lite å leggja hand på berre Mordokai. Dei hadde meldt kongen kva folk Mordokai høyrde til. Og so søkte Haman høve til å rydja ut alle jødar i heile riket åt Ahasveros, av di dei var landsmennerne hans Mordokai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Fyrste månaden, månaden nisan, i tolvte styringsåret åt kong Ahasveros, kasta dei pur, det er lut, for Haman um kvar einskild dag og kvar einskild månad, alt til tolvte månaden, månaden adar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Og Haman sagde til kong Ahasveros: «Her finst eit folk som bur spreidt og utskildt millom dei andre folki i alle jarledøme i riket ditt. Loverne deira er ulike loverne åt alle andre folk, og kongens lover held dei ikkje, so kongen kann ikkje lita seg med å lata deim i fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Tekkjest det kongen, so bør det verta utferda eit brev um å gjera ende på deim. Fem og tjuge tusund våger sylv kann eg då vega upp for embætsmennerne åt kongen til å leggja i kongens skattkammer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Kongen drog signetringen av handi si og gav Haman Hammedatason, agagiten, jødefienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, '«Sylvet skal du få,» sagde kongen til Haman, «og med det folket kann du fara som du finn fyre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Då vart skrivarane åt kongen kalla saman, den trettande dagen i fyrste månaden, og dei skreiv i alle måtar soleis som Haman baud, til kongens satrapar, til jarlarne i kvar sitt jarlerike og til hovdingarne yver dei einskilde folki; kvart jarlerike fekk brevet med si skrift og kvart folk med sitt mål. I namnet åt kong Ahasveros ferda dei ut brevet og forsigla det med den kongelege signetringen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'So sende dei brev med snøggbod til alle jarleriki åt kongen, at alle jødar skulde verta utrudde, drepne og tynte, både unge og gamle, born og kvende, alle på ein dag, den trettande dagen i tolvte månaden, det vil segja månaden adar, og deira gods skulde gjevast til plundring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'I brevet stod at det skulde verta utferda ei lov og kunngjord for alle folk i kvart jarlerike, med bod um at dei skulde vera budde til den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Snøggbodi skunda seg av stad på kongens bod, so snart påbodet var gjeve i borgi Susan. Kongen og Haman sette seg til å drikka. Men byen Susan var reint forfjetra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Då Mordokai fekk vita alt som var hendt, reiv han sund klædi sine og klædde seg i sekk og oska, gjekk ut i byen og skreik høgt og sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Og han kom til plassen utanfor kongsporten; for ingen fekk lov til å ganga inn i kongsporten i syrgjebunad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'I kvart jarlerike, dit som kongens ord og påbod nådde, der vart det stor sorg millom jødar; dei fasta og gret og jamra; mange reidde upp under seg med sekk og oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Ternorne og hirdmennerne åt Ester kom og fortalde henne dette, og dronningi vart reint forstøkt. Ho sende klæde til Mordokai som han skulde taka på seg i staden for syrgjebunaden; men han tok ikkje imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Ester kalla då til seg Hatak, ein av kongens hirdmenner, som var sett til å tena henne, og sende honom til Mordokai til å få vita kva som var tids, og kvifor han bar seg soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Hatak gjekk ut til Mordokai på bytorget under kongsporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Og Mordokai fortalde honom um alt det som hadde hendt honom, og nemnde grant den pengesumen som Haman hadde lova å vega upp åt kongskassa for jødarne, når han fekk tynt dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Dessutan gav han honom avskrift av det skrivne påbodet som hadde vorte utferda i Susan um å rydja deim ut; han skulde syna Ester det og melde henne det, og bjoda henne å ganga inn til kongen og beda um miskunn og søkja nåde for folket sitt hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Hatak kom og melde Ester det Mordokai hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Då baud Ester Hatak ganga til Mordokai og segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '«Alle kongstenarane og folket i kongens jarlerike veit at den lovi gjeld for alle, kar eller kvende: gjeng nokon ukalla inn til kongen i den indre garden, so lyt han lata livet; det einaste er um kongen retter ut mot honom gullstaven, då fær han liva. Og eg hev ikkje vore kalla til kongen no på tretti dagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Dei fortalde Mordokai kva Ester hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Då sagde Mordokai dei skulde svara henne: «Du må ikkje tenkja med deg sjølv at du skal sleppa undan millom alle jødar, av di er i huset hjå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Nei, tegjer du verkeleg stilt i dette høvet, so skal nok jødarne få utfriing og frelsa frå ein annan kant; men du og farshuset ditt skal ganga til grunnar. Kven veit um ikkje du hev nått til kongeleg rang just for dette høvet skuld?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Då let Ester Mordokai få dette svaret:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '«Gakk og få saman alle jødar som finst i Susan, og haldt fasta for meg, so de korkje et eller drikk noko på tri døger, natt og dag. Eg og ternorne mine vil og fasta sameleis. Og so vil eg ganga inn til kongen, endå det er ulovlegt. Lyt eg so døy, so lat meg døy!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mordokai gjekk av stad og gjorde i alle måtar so som Ester hadde bode honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Tridje dagen klædde Ester seg i kongelegt skrud og gjekk inn i den indre garden til kongshuset midt fyre kongshuset, og kongen sat på kongsstolen sin i kongshalli, midt imot døri til huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Då kongen såg dronning Ester standa i garden, fann ho nåde i hans augo; og kongen rette ut til Ester gullstaven som han hadde i handi. Ester gjekk då fram og tok i enden av staven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Kongen sagde til henne: «Kva hev du på hjarta, dronning Ester? kva er det du ynskjer? Um det so er helvti av riket, skal du få det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Ester svara: «Tekkjest det kongen, so må kongen saman med Haman koma i dag til det gjestebodet eg hev laga til åt honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Kongen svara: «Skunda dykk, henta Haman, so me kann gjera det Ester bed um.» So kom då kongen og Haman til gjestebodet som Ester hadde laga til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Då dei sat og drakk vin, spurde kongen Ester: «Kva er di bøn? Du skal få det du bed um! Og kva er ditt ynskje? Um det vore helvti av riket, so skal det løyvast deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Ester svara: «Bøni mi og ynskjet mitt er:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Hev eg funne nåde i kongens augo, og det tekkjest kongen å gjeva meg det eg bed um og gjera det eg ynskjer, so må kongen og Haman koma til det gjestebodet eg vil laga til åt deim; so skal eg i morgon gjera som kongen segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Den dagen gjekk Haman derifrå glad og i godlag. Men då Haman fekk sjå Mordokai i kongsporten, og at han korkje reis upp eller synte nokon age for honom, då vart Haman full av harm mot Mordokai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Like vel styrde han seg, til han kom heim. Då sende han bod etter venerne sine og etter Zeres, kona si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Haman fortalde deim um all sin rikdom og herlegdom og um dei mange sønerne sine, og um alt det kongen hadde gjort til å gjera honom stor og setja honom høgre enn hovdingarne og kongens tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, '«Ja, dronning Ester,» sagde han, «let ingen annan enn meg koma med kongen til det gjestebodet ho gjorde; til i morgon og hev ho bede meg saman med kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Men alt dette kann eg ikkje lita meg med, so lenge eg ser jøden Mordokai sitja i kongsporten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Då sagde Zeres, kona hans, og venerne hans til honom: «Lat deim gjera ein galge, femti alner høg, og bed kongen i morgon um å få hengja Mordokai i den! So kann du fara glad til gjestebords med kongen.» Denne rådi lika Haman godt, og han let deim gjera galgen i stand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Den natti flydde svevnen frå kongen. Han baud henta krønikeboki med minnelege hendingar, og ho vart upplesi for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Der fann dei uppskrive at Mordokai hadde meldt Bigtana og Teres, tvo hirdmenner hjå kongen som heldt vakt ved dørstokken, for dei hadde søkt høve til å leggja hand på kong Ahasveros.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'So spurde kongen: «Kva æra og vyrdnad hev Mordokai fenge for dette?» Kongsdrengjerne som tente honom svara: «Han hev ingen ting fenge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'So spurde kongen: «Kven er det som er ute i garden?» I det bilet var Haman komen inn i den ytre garden ved kongshuset, og vilde tala med kongen um å få hengt Mordokai i galgen han hadde reist åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Kongsdrengjerne svara: «Haman stend der ute i garden.» «Lat honom koma inn!» sagde kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Då Haman kom inn, spurde kongen honom: «Korleis skal ein fara åt med den mannen som kongen gjerna vil heidra?» Haman tenkte med seg sjølv: «Kven skulde kongen vilja heidra meir enn meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'So svara han kongen: «Den som kongen gjerne vil heidra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'åt honom skal ein henta ein kongeleg klædnad som kongen sjølv hev bore, og ein hest som kongen sjølv hev ride på, og som hev fenge ei kongeleg kruna på hovudet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'klædnaden og hesten skal gjevast til ein av dei øvste stormennerne åt kongen, og dei skal hava klædnaden på den mannen kongen vil heidra og føra honom ridande på hesten fram på bytorget, og ropa framfyre honom: «Soleis gjer ein med den mannen som kongen vil heidra.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Då sagde kongen med Haman: «Skunda deg, tak klædnaden og hesten, som du hev sagt, og gjer soleis med jøden Mordokai som sit i kongsporten! Gløym ikkje noko av alt det du sagde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Haman tok klædnaden og hesten, hadde klædnaden på Mordokai, let honom rida fram på bytorget og ropa fyre honom: «Soleis gjer ein med den mannen som kongen vil heidra!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Mordokai vende attende til kongsporten; men Haman skunda seg heim, sorgfull og med hovudet innsveipt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Og Haman fortalde Zeres, kona si, og alle venerne sine alt det som hadde hendt honom. Då sagde vismennerne hans og Zeres, kona hans, med honom: «Um so er at Mordokai, som du tek til å liggja under for, er av jødeætt, so magtast du ingen ting mot honom; du kjem til å liggja reint under for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Medan dei endå tala med honom, kom hirdmennerne åt kongen og skulde snøggast henta Haman til gjestebodet som Ester hadde laga til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'So kom då kongen og Haman til drikkelaget hjå dronning Ester.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Då dei sat og drakk vin, spurde kongen Ester sameleis andre dagen: «Kva er di bøn, dronning Ester? Du skal få det du bed um. Kva er ditt ynskje? Um det vore helvti av riket, so skal det løyvast deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Då svara dronning Ester: «Hev eg funne nåde i kongens augo, og det tekkjest kongen soleis, så unn meg mitt liv på mi bøn og mitt folk på mitt ynskje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'For me er selde, eg og folket mitt, til å verta utrudde, drepne og tynte. Hadde me vorte selde til trælar og trælkvinnor, då skulde eg tagt; for den ulukka vilde ikkje vore so stor at det var verdt å bry kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Då spurde kong Ahasveros dronning Ester: «Kven er han, og kvar er han, den som hev våga seg til å gjera sovore?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Ester svara: «Det er ein illtenkt mann, ein fiendesmann, den vonde Haman, som sit der.» Då vart Haman forfærd for kongen og dronningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Kongen reis upp i harm frå drikkelaget og gjekk ut i slottshagen. Haman drygde, vilde tigga dronning Ester um livet; han skyna kongen var fast på å føra honom i ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Kongen kom attende til drikkelaget frå slottshagen og såg Haman liggja yver kvilebenken som Ester sat på. «Vil du,» ropa kongen, «jamvel her inne i mitt nærvære taka dronningi med vald?» Snaudt var ordi slopne utor munnen på kongen fyrr dei sveipte inn andlitet på Haman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Harbona, ein av hirdmennerne som gjorde tenesta hjå kongen, sagde: «Attmed huset åt Haman stend det alt ein galge, femti alner høg; den let Haman reisa åt Mordokai, som med sine ord gjorde kongen gagn.» «Heng honom der!» sagde kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'So hengde dei Haman upp i den galgen han hadde reist åt Mordokai. Og kongens harm gav seg att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Same dagen gav kong Ahasveros dronning Ester huset hans Haman, jødefienden, og Mordokai fekk koma inn til kongen; for Ester hadde fortalt kva han var for henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Kongen drog av seg signetringen som han hadde teke frå Haman, og gav honom til Mordokai. Og Ester sette Mordokai til å styra huset hans Haman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Endå ein gong vende Ester seg til kongen, fall ned for føterne hans, gret og naudbad honom å gjera um inkje den ulukka og den meinrådi som agagiten Haman hadde etla jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Kongen rette gullstaven ut mot Ester. Då reis Ester upp og gjekk fram for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, '«Tekkjest det kongen,» sagde ho, «og hev eg funne nåde i hans augo, tykkjer kongen det er meining i det, og held han meg gjæv, so lat det ferdast ut eit brev til avlysing av brevi med meinrådi åt agagiten Haman Hammedatason, dei som han ferda ut til å tyna jødarne i alle kongens jarlerike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Kor skulda eg orka sjå på den ulukka som kjem yver folket mitt? Kor skulde eg orka sjå på at ætti mi vert tynt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Då sagde kong Ahasveros til dronning Ester og jøden Mordokai: «Sjå, eg hev gjeve Ester huset hans Haman, han sjølv er hengd i galgen, av di han vilde leggja hand på jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Ferda no de ut eit brev til jødarne i kongens namn, soleis som de tykkjer best, og forsigla det med signetringen åt kongen. For eit skriv som er utferda i kongens namn og forsigla med signetringen åt kongen, kann ikkje verta atterkalla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'So vart då skrivarane åt kongen straks kalla saman, den tri og tjugande dagen i tridje månaden, månaden sivan, og dei skreiv i alle måtar soleis som Mordokai baud til jødarne og til satraparne og jarlarne og hovdingarne i jarleriki, frå India til \'tiopia, hundrad og sju og tjuge jarlerike; kvart rike fekk brevet med si skrift, kvart folk på sitt tungemål, og jødarne med si skrift og på sitt tungemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Han skreiv i namnet åt kong Ahasveros og forsigla med signetringen åt kongen. So sende han brev ikring med ridande snøggbod på tråvarar frå kongens eigne stallar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'at kongen gav jødarne i kvar by lov til å slå seg i hop og verja livet sitt, og rydja ut, drepa og tyna alle væpna flokkar i kvart folk og jarlerike som synte deim fiendskap, alt til born og kvende, og so plundra eigedomarne deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'på ein og same dagen i alle jarleriki åt kong Ahasveros, trettande dagen i tolvte månaden, det vil segja månaden adar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'I brevet stod det at det skulde varta utferda ei lov og kunngjord for alle folk i kvart jarlerike: at jødarne skulde vera budde den dagen til å hemna seg på fiendarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Snøggbodi på dei konglege tråvarar reid av stad so fort dei kunde på kongens bod, so snart påbodet var utferda i borgi Susan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mordokai gjekk ut frå kongen i ein kongeleg klædnad av purpurblått og kvitt ty med ei stor gullkruna, og i ei kåpa av kvitt bomull og purpurraudt ty; og byen Susan jubla og gledde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'For jødarne rana no ljos og gleda, fagnad og vyrdnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Og i kvart jarlerike og i kvar ein by som kongens ord og påbod nådde til, der vart det gleda og fagnad på jødarne, med gilde og høgtid. Mange av folki i landet gjekk yver til jødedomen, so stor otte hadde dei fenge for jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Trettande dagen i den tolvte månaden, det vil segja månaden adar, den dagen det var fastsett at kongens ord og påbod skulde setjast i verk, den dagen jødefiendarne hadde vona å få magt yver deim - no hadde det snutt seg soleis, at det var jødarne som fekk magt yver fiendarne sine -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'den dagen slo jødarne seg i hop i byarne sine i alle dei jarleriki åt kong Ahasveros og vilde leggja hand på deim som elta gjera deim mein. Og ingen stod seg imot deim; so stor otte hadde alle folk fenge for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Alle hovdingarne i jarleriki og satraparne og jarlarne og embætsmennerne åt kongen hjelpte jødarne; so stor otte hadde dei fenge for Mordokai;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'for Mordokai var ein stor mann i kongens hus; i alle jarleriki kom gjetord ut om honom, at denne Mordokai auka allstødt i magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Jødarne slo eit slag på alle fiendarne sine, med sverd og dreping og tyning, og dei for som dei vilde med motmennerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'I borgi Susan drap og tynte jødarne fem hundrad mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Og Parsandata og Dalfon og Aspata');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'og Porata og Adalja og Aridata');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'og Parmasta og Arisai og Aridai og Vaizata,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'dei ti sønerne åt Haman Hammedatason, jødefienden, drap dei. Men til plundring rette dei ikkje ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Same dagen høyrde kongen gjete talet på deim som var drepne i borgi Susan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Då sagde kongen til dronning Ester: «I borgi Susan hev jødarne drepe og tynt fem hundrad mann forutan dei ti sønerne åt Haman. Kva hev dei so ikkje gjort i dei andre kongelege jarleriki? Kva er di bøn? Du skal få det du bed um! Og kva ynskje hev du meir? Det skal verta uppfyllt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Ester svara: «Tekkjest det kongen, so lat ogso i morgon jødarne i Susan få lov å gjera etter påbodet for i dag! Og lat dei ti sønerne åt Haman verta upphengde i galgen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Kongen baud at so skulde vera. Påbodet vart utferda i Susan. Alle ti sønerne åt Haman vart upphengde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Jødarne i Susan slo seg i hop den fjortande dagen og i månaden adar og drap tri hundrad mann i Susan. Men til plundring rette dei ikkje ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Dei andre jødarne i jarleriki åt kongen slo seg i hop og varde livet og rådde seg ro for fiendarne sine. Dei drap fem og sytti tusund av motmennerne sine. Men til plundring rette dei ikkje ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Dette hende trettande dagen i månaden adar. Den fjortande kvilde dei ut og dei gjorde den dagen til ein gjestebodsdag og fagnad-dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Jødarne i Susan hadde slege seg i hop både trettande og fjortande dagen; dei kvilde ut den femtande og gjorde den dagen til gjestebodsdag og fagnad-dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Difor høgtidar jødarne på landsbygdi, dei som bur i landsbyarne, den fjortande dagen i månaden adar med fagnad, med gjestebod og festar og dei sender forner til kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mordokai skreiv upp desse hendingarne og sende brev til alle jødarne i alle jarleriki åt kong Ahasveros, nær og fjerr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'og slog fast for deim at dei år etter år skulde høgtida fjortande og femtande dagen i månaden adar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'for dei dagarne hadde jødarne rådt seg ro for fiendarne sine, og i den månaden hadde suti deira snutt seg um til fagnad og sorgi til høgtid. Difor skulde dei gjera desse dagarne til gjestebods-dagar og fagnad-dagar, og senda fornar til kvarandre og gåvor til fatigfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Jødarne lovtok denne skikken, som dei no hadde teke til med, og som Mordokai hadde skrive til deim um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Agagiten Haman Hammedatason, fienden åt alle jødar, hadde lagt upp råder mot jødarne um å tyna deim og hadde kasta pur, det er lut, for å øyda og tyna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Men då kongen frette det, hadde han bode og ferda ut i eit brev um at meinråderne hans, som hin hadde etla åt jødarne, skulde snu attende på hans eige hovud, so han sjølv og sønerne hans vart hengde i galgen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Av den grunn vart desse dagarne heitande purim, etter ordet pur. Og av den grunn - etter alt det som stod i dette brevet, etter det dei sjølve hadde set, og etter det som hadde hendt deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'so gjorde jødarne det til fast skikk og bruk for seg og etterkomarane sine og for alle som gjekk yver til deira tru, at dei skulde år etter år, ubrigdeleg, høgtida desse tvo dagarne etter fyreskrifti um deim, og på den fastsette tidi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'og at desse dagarne skulde haldast i minne og høgtidast i alle aldrar og ætter og jarledøme og byar, og at desse purim-dagar ikkje måtte falla burt millom jødarne, og minnet um deim aldri kverva hjå etterkomarane deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Dronning Ester Abiha’ilsdotter og jøden Mordokai skreiv eit nytt brev med fynd og klemb og gjorde til lov det som stod i dette nye brevet um purim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Og han sende brev til alle jødar i dei hundrad og sju og tjuge jarleriki i kongeriket åt Ahasveros, venlege og truhjarta ord');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'um å halda ved lag desse purim-dagarne på den fastsette tidi, soleis som jøden Mordokai og dronning Ester hadde bode deim, og soleis som dei hadde stadfest det for seg sjølve og etterkomarane sine, med fyresegner um fasta og klagerop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Påbodet frå Ester gjorde desse purim-bodi til lov. Og dei vart uppskrive i ei bok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Kong Ahasveros lagde skatt på upplandet på sjøbygderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Alt det han gjorde i si magt og sitt velde, og ei greinleg melding um den høge rang som kongen lyfte Mordokai upp til, det er uppskrive i krønikeboki åt dei mediske og persiske kongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Jøden Mordokai var den som stod kong Ahasveros næmest, og han var stor millom jødarne og kjær for dei mange brørne sine; han søkte det som godt var for folket sitt, og tala til bate for all si ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'I landet Us budde det ein gong ein mann som heitte Job. Det var ein ærleg og rettvis mann som ottast Gud og heldt seg frå det som vondt var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Han fekk sju søner og tri døtter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'og han åtte sju tusund sauer, tri tusund kamelar, fem hundrad par uksar og fem hundrad asnor, og dertil ei stor mengd tenarar, so han var den megtigaste av alle austerlendingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Sønerne hans hadde for skikk å halda gilde kvar sin dag heime hjå seg; og dei sende bod og bad dei tri systerne sine, at dei og skulde eta og drikka i lag med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Når so ein umgang med gjestebodsdagar var til endes, sende Job bod etter deim og helga deim tidleg um morgonen ofra han brennoffer, eitt for kvar einskild av deim. For Job tenkte: «Kanskje hev sønerne mine synda og banna Gud i hjarto sine.» Soleis gjorde Job kvar gong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Men so hende det ein dag at gudssønerne kom og stelte seg fram for Herren; og millom deim var og Satan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Herren spurde Satan: «Kvar kjem du ifrå?» «Eg hev fare og svive ikring på jordi,» svara Satan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Då spurde Herren Satan: «Hev du gjeve ans på Job, tenaren min? For liken hans finst ikkje på jordi, slik ein ærleg og rettvis mann som han er, og so som han ottast Gud og held seg frå det som vondt er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Men Satan svara Herren: «Skal tru Job ottast Gud for ingen ting?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Du hev då verna um honom og huset hans og alt han eig! Alt hans yrke hev du signa, og buskaparne hans hev breider seg ut i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Men rett ut handi di og rør ved alt det han eig - då skal han so visst banna deg upp i andlitet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Då sagde Herren til Satan: «Alt det han eig, er i di magt; men honom sjølv må du ikkje leggja hand på.» So gjekk Satan burt frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Ein dag sønerne og døtterne hans heldt måltid og drakk vin i huset hjå den eldste broren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'kom det ein til Job og sagde: «Medan uksarne gjekk for plogen og asnorne beitte ved sida av,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'so kom sabæarane og tok deim og hogg ned drengjerne med sverd; berre eg slapp undan, so eg kunde melda det til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Medan han tala, kom ein annan og sagde: «Guds eld slo ned frå himmelen millom småfeet og hyrdingarne og brende deim upp; berre eg slapp undan, so eg kunde melda det til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Medan han tala, kom den tridje og sagde: «Kaldæarane kom i tri fylkingar og kasta seg yver kamelarne og rana deim; sveinarne hogg dei ned med sverd; berre eg slapp undan, so eg kunde melda det til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Medan han tala, kom den fjorde og sagde: Medan sønerne og døtterne dine åt og drakk heime hjå den eldste broren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'so kom det ein sterk storm burtanfrå øydemarki og tok fat i alle fire hyrno på huset, so det seig i hop yver ungdomarne og slo deim i hel; berre eg slapp undan, so eg kunde melda det til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Då stod Job upp og reiv kappa si sund og klypte håret av hovudet og kasta seg å gruve og tilbad');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'og sagde: «Naken kom eg or moderliv; naken fer eg attende. Herren gav, og Herren tok; Herrens namn vere lova!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Tråss i alt dette synda ikkje Job, og klaga ikkje på Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'So hende det ein dag, at gudssønerne kom og stelte seg fram for Herren att, og Satan var millom deim og stelte seg fram for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Og Herren spurde Satan: «Kvar kjem du ifrå?» «Eg hev fare og svive ikring på jordi,» svara Satan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Då spurde Herren honom: «Hev du gjeve ans på Job, tenaren min? For liken hans finst ikkje på jordi, slik ein ærleg og rettvis ein mann som han er, og so som han ottast Gud og held seg frå det som vondt er. Han er endå like ærleg, so du hev eggja meg upp til å tyna honom utan grunn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Då sagde Satan til Herren: «Hud for hud; ein mann gjev gjerne alt han eig når han berre bergar livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Men rett ut handi di og rør ved beini og holdet hans - han skal so visst banna deg upp i andlitet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Då sagde Herren til Satan: «Han er i di magt; men spar livet hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'So gjekk Satan burt frå Herren; og han slo Job med vonde svullar frå hovud til hæl;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'og han tok seg eit skålbrot og skrapa seg med der han sat i oskedungen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Då sagde kona hans til honom: «Er du endå ulasteleg? Banna Gud, so du kann få døy!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Men han svara henne: «Du talar som ei fåvis kvinna. Me tek imot av Gud det gode, skal me’kje taka og det vonde?» Tråss i alt dette synda ikkje Job med lipporne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Tri vener til Job fekk høyra um den ulukka som hadde kome yver honom; dei kom kvar frå sin heimstad, Elifaz frå Teman, Bildad frå Suah, og Sofar frå Na’ama, og dei avtala seg imillom at dei skulde ganga til honom for å syna honom samhug og trøysta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Men alt på langt fråstand såg dei at han var heilt ukjenneleg; og dei sette i og gret og reiv sund kapporne sine og kasta mold yver hovudi upp i lufti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Og dei sat hjå honom på jordi i sju dagar og sju næter; og ingen av deim sagde eit ord til honom, for dei såg at han pintest hardt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Då let Job upp munnen og banna fødedagen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Job tok til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '«Burt med den dag då eg vart fødd, den natt som sa: «Ein svein er avla!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Må denne dag til myrker verta - burtgløymd av Gud i høge himmel - og inkje ljos på honom skina!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Lat svarte myrkret honom eiga og skyer seg kring honom samla! Dagmyrkjingar skal honom skræma');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'og myrkret gløypa denne natt! Burt med den natt frå årsens dagar, ho kome ei i månads tal!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Ja, aud og tom skal natti verta og ingen fagnad i ho klinga;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Dagbannarar skal henne banna, dei som kann mana upp Livjatan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Og morgonstjernor skal’kje skina; fåfengt ho venta skal på ljoset - augbrunerne av morgonroden -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'av di ho ei livsdøri stengde på mor mi, so eg slapp for kval.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Kvi døydd’ eg ei i moders liv? Ell’ slokna då eg rett var fødd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Kvi fanst det kne som mot meg tok; og brjost eg kunde suga ved?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'So låg eg still og kvilde no, eg sov og hadde ro og fred');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'hjå kongar og hjå fyrstar, som til gravstad pyramider bygde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'hjå hovdingar som åtte gull og fyllte sine hus med sylv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'ell’ ufødd var eg ikkje til, lik born som aldri ljoset såg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Der rasar ei dei vonde meir; der kviler dei som trøytte er;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'og fangarne er trygge der; dei høyrer ingen drivar meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Der stor og liten like er, og trælen fri for herren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Kvi gjev han ljos til den som lid, og liv til deim som gremmer seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'som fåfengt stundar etter dauden, og søkjer han som løynde skatt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'som gled seg, ja, som jublar høgt, og fegnast når dei finn ei grav -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'til mannen som ei finn sin veg, som Gud set fast og stengjer inne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Min sukk hev vorte daglegt brød, og klaga mi som vatnet strøymar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Meg råkar det eg ottast fyre; det som eg ræddast, hender meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Snaudt fær eg fred, snaudt fær eg ro, snaudt lindring - so kjem uro att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Då tok Elifaz frå Teman til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '«Vert du vel tykkjen um eg talar? Men kven kann halda ordi inne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'På rette veg du førde mange; dei trøytte hender styrkte du;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'med ord du hjelpte deim som snåva, og gav dei veike knei kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Men når det gjeld deg sjølv, du klagar; når deg det råkar, ræddast du!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Di von du på di gudstru bygde og sette lit til last-laust liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Tenk etter: Når vart skuldlaus tynt? Når gjekk rettvis mann til grunns?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Stødt fann eg: dei som urett pløgde, og sådde naud, dei hausta slikt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'dei stupte for Guds andedrag, gjekk for hans vreidestorm til grunns.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Ja, løva skrik, og villdyr burar; ungløva fær sin tanngard knekt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'og løva døyr av skort på rov; løvinna misser sine ungar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Ein løynleg tale til meg kom; i øyra mitt det stilt vart kviskra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'som tankar i eit nattsyn kjem, når svevnen tung på folki kviler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Det kom ei rædsla yver meg, ei skjelving gjenom alle lemer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'ein gust meg yver panna strauk, og på min kropp seg håri reiste;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'og noko stogga for mi åsyn; eg kunde ikkje klårt skilja; framfor mitt auga stod eit bilæt’, eg høyrde som ei røyst som kviskra:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '«Hev menneskjet vel rett for Gud? Er mannen rein framfor sin skapar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Han sine tenarar ei trur og finn hjå sine englar lyte -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'enn meir hjå folk i hus av leir; hjå deim som hev sin grunn i moldi, ein kann deim krasa, som eit mol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Dei er frå morgon og til kveld; ein krasar deim - kven merkar det? - Og dei vert ikkje funne meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Når deira tjeldsnor vert rykt upp, dei døyr og ingen visdom fær.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Rop berre du; kven svarar deg? Kva engel vil du beda til?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Mismod slær fåvis mann i hel og brennhug den som lite veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Eg såg ein dåre festa rot, og brått eg laut hans bustad banna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Hans søner hjelpelaus var, uhjelpte trakka ned i porten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Hans avling åt dei svoltne upp, dei tok ho tråss i klungergjerde, og snara lurde på hans gods.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Men naudi ei frå dusti kjem; ulukka ei or jordi renn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'nei, mannen vert til møda fødd, som gneistarne lyt fljuga høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Eg vilde venda meg til Gud og leggja saki fram for honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'som storverk gjer som ei me skynar, fleir’ underverk enn me kann telja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'som sender regnet ned på jord og vatnet yver mark og eng,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'som lyfter låg og liten upp og hjelper syrgjande til frelsa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'som spiller planen for dei sløge, so deira hender inkje duger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'som fangar vismann i hans vit, so listig råd forrenner seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Um dagen støyter dei på myrker, trivlar ved middag som ved natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Frå sverd frelser han frelser fatigmann, frå deira munn, frå yvervald,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'so vesalmann fær hava von, men vondskap lata munnen att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Men sæl den mann som Gud mun refsa; vanvyrd ei tukt frå Allvalds-Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Han sårar, men bind og umkring; han slær men lækjer med si hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Seks trengslor bergar han deg or, i sju skal inkje vondt deg nå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'I hunger fri’r han deg frå dauden, i krig du undan sverdet slepp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'for tungesvipa er du berga, og trygg du er i tap og tjon;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'du lær åt tjon og hungersnaud og ottast ikkje ville dyr;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'du samband hev med stein på marki, og fred med villdyr uti heidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Du merkar at ditt tjeld hev fred, og inkje vantar i ditt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Du ser, ditt sæde tallrikt er, ditt avkom rikt som gras på eng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'I mannskraft til di grav du gjeng, lik korn, køyrt inn i rette tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Det hev me granska; so det er; so høyr og merka deg det då!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Då tok Job til ords og svara:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '«Um dei mitt mismod vega vilde og få ulukka mi på vegti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'det tyngjer meir enn havsens sand; difor var ordi mine ville.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'For Allvalds pilar sit i meg, mi ånd lyt suga deira gift; Guds rædslor reiser seg til åtak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Skrik asnet vel i grøne eng? Og rautar uksen ved sitt for?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Kven et det smerne utan salt? Kven finn vel smak i eggjekvite?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Det byd meg mot å røra slikt, det er som min utskjemde mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Å, fekk eg uppfyllt bøni mi! Gav Gud meg det eg vonar på!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Ja, vild’ han berre knusa meg, med hand si min livstråd slita!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Då hadde endå eg mi trøyst; trass pina skulde glad eg hoppa! - Den Heilage sitt ord eg held på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Kva er mi kraft, at eg skuld’ vona? Mi framtid, at eg skulde tola?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Er krafti mi som steinen sterk? Er kanskje kroppen min av kopar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Mi hjelp hev heilt forlate meg; all kvart stydjepunkt er frå meg teke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Ein rådlaus treng av venen kjærleik, um enn han ottast Allvald ei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Som bekken brørne mine sveik, lik bekkjefar som turkar ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Fyrst gruggast dei av bråna is, og snø som blandar seg uti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'men minkar so i sumarsoli, og kverv til slutt burt i sumarhiten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Vegfarande vik av til deim, men kjem til øydemark og døyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Kjøpmenn frå Tema skoda dit, flokkar frå Saba vonar trygt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'men svikne vert dei i si von; dei narra vert når dei kjem fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'So hev de vorte reint til inkjes, de rædsla såg, og rædde vart!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Hev eg då bede dykk um noko? Bad eg dykk løysa meg med gods?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'og frelsa meg frå fiendvald og kjøpa meg frå røvarar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Gjev meg eit svar, so skal eg tegja; seg meg kva eg hev synda med!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Eit rettvis ord er lækjebot; men last frå dykk er inkje verdt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Du lastar meg for ordi mine; men vonlaus mann so mangt kann segja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'De kastar lut um farlaust barn, og handel driv um dykkar ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Vilde de berre sjå på meg! Trur de eg lyg dykk upp i augo?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Vend um, lat ikkje urett skje! Vend um, enn hev eg rett i dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Finst det vel fals på tunga mi? Kann ei min gom ulukka smaka?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Ja, mannen hev ein strid på jordi; hans dagar gjeng som leigedagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Som trælen lengtar etter skugge, og leigekar på løni ventar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'so fekk eg månader av vonbrot og næter fulle utav møda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Eg segjer når eg gjeng til kvile: «Når skal eg atter standa upp?» Og kvelden vert so lang, so lang: Eg ligg uroleg alt til dagsprett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Og makk og sår min likam dekkjer, og hudi skorpnar og bryt upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mi tid fer snøggar’ enn ein skutel, og ho kverv utan nokor von.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Hugs på: mitt liv er som ein pust; mitt auga ser’kje lukka meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Snart er eg løynd for alle augo; du fåfengt stirer etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Som skyi framum fer og kverv, so ingen att frå helheim vender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'snur ei attende til sitt hus; hans heimstad kjenner han’kje meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Difor vil’kje munnen stagga, men tala i min djupe hugverk og klaga i mi sjælenaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Er eg eit hav, er eg ein drake, med di du vaktar so på meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Eg tenkjer: «Lægjet skal meg lindra, og sengi letta suti mi» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'då skræmer du meg upp med draumar, og støkkjer meg med ville syner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'so at eg heller ville kjøvast, ja døy, enn vera slik ei beingrind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'D’er nok! Eg liver ikkje æveleg; Haldt upp! Mitt liv er som ein pust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Kva er ein mann, at du han vyrder og retter tanken din på honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'heimsøkjer honom kvar ein morgon, ransakar honom kvar ei stund?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Når tek du frå meg auga ditt? Meg slepper med eg svelgjar råken?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Hev eg gjort synd, kva gjer eg deg, du som på mannen vaktar stødt? Kvi hev du meg til skiva valt? So eg hev vorte meg ei byrd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Kvi gjev du ikkje syndi til? Kvi ansar du på mine brot? No sig eg snart i moldi ned; og leitar du, so er eg burte.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Då tok Bildad frå Suah til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '«Kor lenge vil du tala so og lata ordi storma fram?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Kann Gud vel rengja det som rett er? Kann Allvalds-Gud vel rengja rettferd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Hev dine søner synda mot han, gav han deim deira synd i vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Um du søkja til din Gud, og beda Allvalds-Gud um nåde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'er du då rein og utan svik, då vil han vakna upp for deg og reisa nytt ditt rettferdshus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Um og di fortid vesall var, so mykje større vert di framtid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Ja, spør deg for hjå farne ætter, agt på kva federne fann ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '- Me inkje veit, er frå i går; vårt liv ein skugge er på jordi -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'dei skal deg læra, gjeva svar med ord ifrå sitt hjartedjup:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, '«Veks sevet vel på turre land? Trivst storren der som vatnet vantar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Enn stend det grønt, vert ikkje skore, då visnar det fyrr anna gras.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'So gjeng det deim som gløymer Gud; og voni glepp for gudlaus mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Hans tillit sunderskori vert, hans tiltru vert til kongurvev;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Det hus han styd seg til, det dett; det som han triv til, stend’kje fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Han saftfull veks, med soli skin; hans greiner yver hagen heng,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'og roti kring steinrøysar smett, og smyg seg inn imillom steinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Men vert han riven frå sin stad, so hugsar staden han ei meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Sjå det er gleda på hans veg; or moldi skyt ein annan fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Men Gud vanvyrder ei den reine; dei vonde tek han ei i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Han enn din munn med lått skal fylla og lipporne med gledesong;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'men skammi klæda skal din fiend’; gudløysetjeld finst ikkje meir.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Då tok Job til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '«Eg veit for visst at det er so; kva rett fær mannen imot Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Um han med honom vilde trætta, han kann’kje svara eitt til tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Vis som han er og sterk i velde - kven kann vel strafflaust tråssa honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'som fjelli flyt, dei veit’kje av det, og velter deim upp i harm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'som ruggar jordi frå sin plass, so pilarne hennar skjelv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'som soli byd so ho ei skin, og set eit segl for stjernorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'som eine spanar himmeln ut og fram på havsens toppar skrid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'hev skapt Karlsvogni og Orion, Sjustjerna og Sørkamri med?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Som storverk gjer, me ei kann fata, og underverk forutan tal?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Han framum gjeng, eg ser han ikkje; um burt han glid, eg går han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Når han tek fat, kven stoggar honom? Kven honom spør: «Kva gjer du der?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Gud stoggar ikkje vreiden sin; for han seg bøygde Rahabs-fylgjet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Kor kann vel eg då svara han? Kor skal for han eg ordi leggja?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Um eg hev rett, eg kann’kje svara, men lyt min domar be um nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Og um han svara når eg ropa, eg trudde ei mi røyst han høyrde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Han som i stormver reiv meg burt og auka grunnlaust såri mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'han let meg ikkje anda fritt, men metta meg med beiske ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Når magt det gjeld, då er han der; men gjeld det rett: kven stemnar honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Um eg hev rett, min munn meg dømer; er skuldlaus, han meg domfeller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Skuldlaus eg er! eg skyner ei meg sjølv, vanvyrder livet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Det er det same, no eg segjer: Han tyner skuldig og uskuldig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Når svipa brått gjev ulivssår, med lått han ser den gode lida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Han jordi gav i nidings hand; på domarar han syni kverver. Er det’kje han, kven er det då?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Mitt liv fer snøggare enn lauparen, dei kverv, men lukka såg det aldri;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Det glid som båtar utav sev, lik ørn som ned på fengdi slær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Når eg mi plåga gløyma vil og jamna panna mi og smila,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'då gruvar eg for pina mi; eg veit du ei frikjenner meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'For når eg lyt straffskuldig vera, kvifor skal eg då fåfengt stræva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Um eg i snø meg vilde tvætta og reinsa henderne med lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Du ned i grefti straks meg dukka, so mine klæde ved meg stygdest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Han ikkje er ein mann som eg, kann ei med meg til retten gå;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'd’er ingen skilsmann millom oss som handi si kann på oss leggja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Når berre han tok riset frå meg og ikkje skræmde meg med rædsla,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'eg skulde tala utan otte; sjølv dømer eg meg annarleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Mi sjæl er leid av livet mitt, eg gjev mi klaga lause taumar, vil tala i min såre hugverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Til Gud eg segjer: «Døm meg ikkje; seg kvifor du imot meg strider!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Finn du det godt å gjera vald, og øyda upp ditt eige verk, men lysa yver gudlaust råd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Er auga ditt av kjøt og blod? Ser du som menneskje plar sjå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Er dine dagar mennesk-dagar? Er dine år lik mannsens år?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Med di mitt brot du leitar upp, og granskar etter syndi mi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'endå du veit eg er uskuldig, og ingen bergar or di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Di hand hev skapt og dana meg fullt ut, og no vil du meg tyna?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Hugs på, du forma meg som leir; no gjer du atter meg til mold!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Som mjølk du let meg renna ut og let meg stivna liksom ost;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Du klædde meg med hud og kjøt, fleitta bein og senar saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Du gav meg både liv og miskunn, og verna um mitt andedrag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Men dette du i hjarta gøymde, eg veit det var i din tanke;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Du vakta på meg um eg synda; du gav meg ikkje til mitt brot;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'um eg var skuldig, usæl eg! Um skuldfri, tord’ eg ei meg briska, av skjemsla mett, med naud for augom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'For då du jaga meg som løva og let meg atter under sjå,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'du førde nye vitne mot meg og harmast endå meir på meg og sende mot meg her på her.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Kvi drog du meg or morsliv fram? Kvi fekk eg ikkje usedd døy,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'lik ein som aldri til hev vore, og vart i grav frå morsliv lagt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Er ikkje mine dagar få? Haldt upp! Slepp meg, so eg litt glad kann verta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'fyrr eg gjeng burt, og kjem’kje att, til myrkre land med daudeskugge,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'eit land so myrkt som svarte natti, med daudeskugge og vanskipnad, der dagsljoset er som myrke natt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Då tok Sofar frå Na’ama til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '«Skal slik ei svalling ei få svar? Skal slik ein storpratar få rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Skal menner for din ordflaum tegja? Skal du få spotta utan skjemsla?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Du segjer: «Rein er læra mi, eg skuldfri er i dine augo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Men dersom berre Gud vil tala og opna munnen sin mot deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'og syna deg sin løynde visdom, kor han eig vit i dobbelt mål! Då skulde du nok skyna at Gud gjev deg noko til av syndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Skal tru Guds tankedjup du kjenner? Hev du nått fram til Allvalds grensa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Høgar’ enn himmelen - kva gjer du? Djupar’ enn helheimen - kva veit du?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Lenger enn jordi strekkjer seg og breidare enn havet sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Når han skrid fram og legg i lekkjor, stemnar til doms, kven stoggar honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Han kjenner deim som talar lygn; han ser den falske utan leiting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Det tome hovud fær forstand, og asenfolen vert til mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Men vil du bu ditt hjarta rett og henderne mot honom breida');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'og halda svik frå handa di og urett burte frå ditt tjeld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'då kann du lyt’laust hovud lyfta, då stend du fast og ræddast ikkje;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'då kann du gløyma all di møda, liksom ei elv som framum rann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Klårar’ enn dagen stend ditt liv, og myrkret vert til morgongråe;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'då er du trygg, då hev du von, du ottelaus til kvile gjeng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Du ligg, og ingen upp deg skræmer, og mange vil deg gjerne tekkjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Men augo veiknar på dei vonde; dei hev’kje nokor tilflugt meir, men ventar på å anda ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Då svara Job og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '«Ja visst, de er dei rette folk, og visdomen døyr ut med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Men eg hev vit so vel som de; eg ei til atters stend for dykk; kven kjenner ikkje dette fyrr?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Til spott for venen min vert eg som bad til Gud og bønhøyrd vart. Til spott vert rettvis mann og ærleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Vanvyrd ulukka! tenkjer trygg mann, vanvyrdnad ventar deim som vinglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Valdsmenn bur roleg i sitt tjeld; trygge er dei som tergar Gud, dei som hev Gud i neven sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Spør bølingen, han skal deg læra, og fugl i luft, han segja skal,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'og tal til jordi, ho skal læra, og fisk i hav, skal melda deg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kven skynar ei på alt i hop, at Herrens hand hev skapa det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Kvar livand’ sjæl han hev i handi og åndi åt kvart menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Vert ordi ei med øyra prøvde, som du med gomen maten smakar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Hjå folk med gråe hår er visdom, og vit hjå deim som liver lenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Hjå honom visdom er og kraft, hjå honom råd og dømekraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Når han riv ned, kven byggjer upp? Når han set fast, kven løyser ut?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Han stengjer vatnet, turkar det, slepper det, so det jordi øyder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Hjå honom kraft og klokskap er; han eig båd’ vegvill og vill-leidar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'rådsherrar fører han som fangar, og domarar han gjer til dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Han løyser konge-styring upp, legg reip kring livet på deim sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Han fører prestar plundra burt og øyder ut eld’-gamle ætter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Han mælet tek frå øvde talar og vitet frå dei gamle menn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'og yver stormenn skam han øys og løyser beltet på dei sterke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Han myrkret driv or holor ut og fører dimma fram i dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Han aukar folk og tynar deim; han spreider folk og fører deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Han vitet tek frå jordheimsfyrstar og let veglaus heid deim vildra;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'dei sviv i myrkret utan ljos, han let dei raga liksom drukne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Ja, allting hev mitt auga set og øyra høyrde og forstod;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'alt det de veit, det veit eg og; for dykk eg ei tilbake stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Men eg til Allvalds Gud vil tala, med Gud eg vil til retten ganga;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Men de vil dekkja til med lygn, er berre ugagnslækjarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Å, gjev de vilde tegja still, so kunde det for visdom gjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Høyr på den skrapa eg vil gjeva, merk når mi lippa åtak gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Vil de forsvara Gud med lygn? Vil de hans sak med urett verja?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Vil de for honom gjera mismun, og spela Guds sakførarar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Gjeng det dykk vel, når han dykk prøver? Kann de han narra som eit mennesk’?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Han skal so visst dykk straffa strengt, um de slik mismunn gjer i løynd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Med høgdi si han skræmar dykk, hans rædsla yver dykk skal falla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Og dykkar kraft-ord vert til oska, og dykkar prov til blaute leir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Teg stilt, lat meg tala ut, so fær det gå meg som det kann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Kvi skuld’ eg ta mitt kjøt i tenner? Og halda livet mitt i handi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Han drep meg, ei eg ventar anna, mi ferd for han lik’vel eg hævdar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Men ogso det skal hjelpa meg; hjå han fær ingen urein møta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'So høyr då det eg segja vil; lat meg for dykkar øyro tala!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Eg saki hev til rettes lagt; eg skal få rett, det veit eg visst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kven er det som med meg kann strida? Eg skulde tegja stilt og døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Tvo ting må du spara meg for; då løyner eg meg ikkje for deg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Di hand lyt burt frå meg du taka, lat ei di rædsla skræma meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Stemn meg so inn! eg stend til svars; eller eg talar og du svarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Kor mange brot og synder hev eg? Seg meg mi misgjerd og mi synd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Kvifor vil du di åsyn løyna og for ein fiend’ halda meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Vil eit burtblåse blad du skræma? Forfylgja du eit visna strå? -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Når du idømer meg slik straff og let meg erva ungdoms synder');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'og legg i stokken mine føter, og vaktar alle mine vegar, slær krins um mine foteblad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Og det mot ein som morkna er, lik klædeplagg som mol et upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Sjå - menneskjet, av kvinna født, det liver stutt, av uro mett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Som blom det sprett og visnar burt, ja, lik ein skugge burt det fer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Men du med honom auga held, og meg du dreg for domen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Skal tru det av ein urein kjem ein som er rein? Nei, ikkje ein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Når dagetalet hans er sett, hans månads-tal sett fast hjå deg, når du for han ei grensa drog som ei han yverskrida kann,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'so snu deg frå, lat han få fred og ha sin dag som leigekaren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'For treet er det endå von; um det vert det hogge, sprett det att, på renningar det vantar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Når røterne i jordi eldest, og stomnen døyr i turre mold,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'ved dåm av vatnet skyt det knupp, fær som ein stikling grøne greiner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Men døyr ein mann, då ligg han der; han andast, og kvar er han då?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Som vatnet renn ut or ein sjø, som elvi minkar, turkast ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'so ligg ein mann, ris ikkje upp; til himmeln kverv, dei vaknar ikkje; ein kann’kje vekkja deim or svevnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Å, gjev du gøymde meg i helheim, løynde meg, til din vreide gav seg, gav meg ein frest, og so meg hugsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Tru mannen døyr og livnar att? I all min strid eg skulde vona og venta til avløysing kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Eg skulde svara, når du ropa og lengta mot dine eige verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Men no du tel kvart stig eg tek og agtar vel på syndi mi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'mi synd er læst i pungen inn, og på mi skuld du gøymer vel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Som fjellet fell og smuldrast burt, og berget frå sin stad vert flutt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Som vatnet holar steinen ut, og flaumen skolar moldi burt, so tek du ifrå mannen voni');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'og tyngjer honom ned for alltid. Han fer av stad; med åsyn rengd du sender honom burt frå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Han veit’kje um hans born vert heidra; han merkar ikkje um dei armast;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Hans eigen kropp hans liding valdar, og sjæli græt for eigi sorg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Då tok Elifaz frå Teman til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '«Kjem svar i vind og ver frå vismann? Fyller han barmen sin med storm?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Vil han med ugangstale lasta? Med ord som nyttelause er?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Otten for Gud den bryt du ned og skjeplar andakt for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'For syndi styrer munnen din; du talar som dei falske talar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Din munn deg dømer, ikkje eg; og dine lippor vitnar mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Vart fyrst av menneskje du fødd? Vert fyre haugarne du avla?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Var du i Guds rådleggjing med? Og fekk du visdom til deg rana?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Kva veit du som me ikkje veit? Kva skynar du som me ei kjenner?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Gråhærd og gamling er hjå oss; han eldre er enn jamvel far din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Er trøyst frå Gud det altfor ring? Vanvyrder du eit rolegt ord?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Kvi let du hugen eggja deg? Kvi let du auga rulla vilt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'For imot Gud din harm du snur og let or munnen ordi strøyma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kor kann vel mannen vera rein? Og kvinnefødde hava rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'På sine heilage han lit ei; for honom er’kje himmeln rein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'langt mindre då ein styggeting, ein mann som urett drikk som med vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Eg vil deg læra; høyr på meg! Det som eg såg, vil eg deg melda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'det som vismenner segja kann, og ei hev dult frå sine feder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'dei som åleine landet åtte, og ingen framand kom bland deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Den vonde stødt i uro liver, for valdsmann gøymt er fåe år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'I øyro rædsletonar ljomar; fyrr han veit av, kjem tynaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Han trur’kje han kann fly frå myrkret; han venta lyt det kvasse sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Han leitar etter brød: Kvar er det? Han veit, ein myrk dag er for hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Naud, trengsla skræmer, tyngjer honom, liksom ein konge budd til strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'For imot Gud han lyfte handi og våga tråssa Allvalds-Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'han storma fram med nakken lyft, med vern utav skjold-ryggjer sterke;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'han dekte andlitet med feitt og gjorde sine lender feite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Han budde i bannstøytte byar, i hus som ingen burde bu i, men til grushaugar etla var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Han vart’kje rik, hans gods kverv burt, hans grøda luter ei mot jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Han kann’kje koma undan myrkret. Hans greiner turkast burt i hiten, og han kjem burt ved hans munns ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Trur han på fåfengd, vert han narra, og berre fåfengd haustar han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Fyrr dagen kjem, då vert det uppfyllt, hans palmegreiner grønkar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Lik vinstokk misser han si druva, spiller sin blom som oljetreet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Ein syndarflokk set ingi frukt, og elden øyder mute- tjeldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Dei avlar møda, føder tjon, og svik i fanget sitt dei nører.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Då svara Job og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '«Eg hev høyrt nok av dette slag; d’er brysam trøyst de alle gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Vert det’kje slutt på tome ord? Kva er det som til svar deg driv?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Eg skulde tala liksom de, i fall de var i staden min; eg sette ord i hop mot dykk, eg riste hovudet mot dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'eg skulde trøysta dykk med munnen og lindra dykk med lippemedynk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Men tale lindrar ei min verk, og ikkje kverv han um eg tegjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Men no hev han meg trøytta ut, du hev øydt ut min heile huslyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Du klemde meg, til vitne vart det, mi liding reiste seg imot meg og vitna mot meg beint i syni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Hans vreide reiv og elte meg; han gnistra tennerne imot meg; fiendar kveste augo på meg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'og opna munnen sin imot meg og slo mi kinn med skjemdarslag og stima saman imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Til farkar Gud meg yverlet og kastar meg i brotsmenns vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Midt i min fred han skræmde meg, treiv meg i nakken, krasa meg, til skiva sette han meg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Hans pilar svirrar kringum meg; bønlaust han kløyver mine nyro, mitt gall han tømer ut på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Han bryt meg sund med brot på brot og stormar mot meg som ei kjempa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Sekk hev eg sytt um hudi mi og stukke hornet mitt i moldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Raudt er mitt andlit utav gråt, og myrkret tyngjer augneloki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'endå mi hand er rein for vald, og bøni mi er fri for svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Løyn ikkje blodet mitt, du jord! Legg ikkje klaga mi til kvile!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Alt no mitt vitne er i himmeln, min målsmann i det høge bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Når mine vener spottar meg; til Gud eg tårut auga vender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Han døme millom Gud og mann og millom mannen og hans ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Og ikkje mange år det vert fyrr eg gjeng burt og kjem’kje att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mi ånd er knekt, mitt liv er sløkt, no hev eg berre gravi att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Eg hæding finn på kvar ein kant, ved deira tråss lyt auga dvelja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Å, set eit pant for meg hjå deg! Kven elles skal meg handslag gjeva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Du stengde deira sjæl for skyn; difor vil du ikkje lyfta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Den som gjev vener burt til plundring, hans søner sloknar augo på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Eg er for folk til ordtak sett, som ein dei sputtar beint i syni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Mitt auga sjukt av sorger er, og mine lemer er ein skugge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Dei rettvise støkk yver slikt, og skuldfri harmast på ugudleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Men rettvis mann sin veg gjeng fram, og magti veks hjå reinhendt mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Men de - kom berre alle att! Eg ingen vismann finn hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Og mine dagar dei kvarv burt; og mine planar slitna sund, dei som mitt hjarta emna på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Men dei gjer natti um til dag, som ljos var næmare enn myrkrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Eit hus i helheim er mi von, i myrkret reider eg mi seng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Til gravi ropar eg: «Min far!» til makken: «Mor mi! Syster mi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kvar vert det då av voni mi? Mi von, kven augnar henne då?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Til helheims bommar fer ho ned, når eg til kvile gjeng i moldi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Då tok Bildad frå Suah til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '«Kor lenge driv de jagt på ord? Gjev gaum, lat oss so talast ved!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Kvi skal me reknast liksom fe, som ureine i dykkar augo?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Å, du som riv deg sund i sinne, skal jordi øydast for di skuld? Skal fjellet flytjast frå sin stad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Men sløkt vert ljoset for den vonde, og hans åre-eld skal ikkje skina.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'I tjeldet hans vert ljoset myrkt, og lampa sloknar yver han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Hans sterke stig vert snævra inn; han snåvar yver sine planar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Hans fot vert fløkt i garnet inn, og upp i netet ferdast han;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'og snara triv um hælen hans, og gildra tek på honom fat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'I jordi løynde gildror lurer, og fellor ventar på hans veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Og rædslor trugar rundt ikring og skræmer han for kvart eit stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Ulukka hungrar etter han, og vondt vil føra han til fall,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'vil eta kvar ein led og lem, ja, det vil daudens eldste son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Hans trygd er rivi frå hans tjeld; du sender han til rædsle-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'I huset hans bur framande, det vert strått svåvel på hans bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Hans rot i grunnen turkar ut; den høge kruna visnar burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Hans minne kverv frå jordi burt, og namnlaus vert han vidt og breidt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Frå ljos til myrker driv dei honom og jagar han frå landi burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Han barnlaus vert i eige folk; i heimen hans slepp ingen undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Og vestmenn støkk for dagen hans, og austmenn vert av rædsla slegne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Just soleis gjeng det nidings hus, den heim der ingen kjenner Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Då svara Job og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '«Kor lenge vil mi sjel de harma og krasa meg med dykkar ord?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Ti gonger hev de no meg spotta; de skjemmest ei å krenkja meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Hev eg i røyndi mistak gjort, dei mistak er mi eigi sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Vil de dykk briska imot meg, som um eg lid mi skam med rette?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Hugs på at Gud hev bøygt meg ned og spana kringum meg sitt garn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Eg ropar: «Vald!» - men eg fær’kje svar; eg ropar: «Hjelp!» men fær’kje rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Han stengjer vegen for min fot, og myrker legg han på min stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Min heidersklædnad drog han av; han frå mitt hovud kransen tok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Mi vern han braut, so eg gjekk under, mi von sleit han lik treet upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Hans vreide logar meg imot, og for ein fiend’ held han meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Hans skarar stemner fram mot meg; dei brøyter seg ein veg mot meg og lægrar seg kring tjeldet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Han dreiv ifrå meg mine frendar, og kjenningar vart framande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Skyldfolki held seg burte frå meg, husvenerne hev gløymt meg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'For hjon og tenar er eg framand; dei held meg for ein ukjend mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Ei svarar drengen på mitt rop. Eg må med munnen tigga honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'min ande byd imot for kona, eg tevjar ilt for mine sambrør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Jamvel smågutar spottar meg, når eg stend upp, dei talar mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Dei styggjest for meg mine vener, og dei eg elska, snur seg mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Min kropp er berre skin og bein, snaudt hev eg endå tannkjøt att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Hav medynk, medynk, mine vener! Gud hev meg råka med si hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Kvifor skal de som Gud meg jaga, og vert ei mette av mitt kjøt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Å, gjev at mine ord vart skrivne, og i ei bok vart rita inn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'ja, vart med jarnmeitel og bly for ævleg tid i berget hogne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Eg veit at min utløysar liver, til sist han yver moldi kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Og når mi hud er øydelagd, ut frå mitt kjøt då ser eg Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'eg honom ser som venen min, mitt auga ser det, ingen framand! Å, nyro lengtar i mitt liv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'De segjer: «Me vil jaga honom!» - som um orsaki låg hjå meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Men de lyt agta dykk for sverdet; for vreide vert ved sverdet straffa. Og de skal vita: domen kjem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Då tok Sofar frå Na’ama til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '«Difor gjev mine tankar svar, og difor stormar det i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Ei skamleg skrapa fær eg høyra, men kloke svar mi ånd gjev meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Veit du’kje at frå ævords tid, frå mannen fyrst på jord vart sett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'ugudlege hev stokkut jubel, vanheilage stuttvarug gleda?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Når modet hans til himmels stig, når hovudet mot sky han lyfter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'han evig gjeng til grunns som skarnet; «Kvar er han?» spør dei, honom såg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Lik draumen glid han burt og kverv, vert jaga som ei nattesyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Han burte er for alle augo, hans stad veit ikkje til han meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Hans born lyt hjelpa fatigfolk; hans hender gjev hans gods attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Hans bein var full’ av ungdomskraft; men den i moldi ligg med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Er i hans munn det vonde søtt, vil han det under tunga gøyma,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'sparer han det og slepper ikkje, held han det under gomen fast,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'so vert i kroppen maten hans til orme-eiter i hans buk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Det gods han gløypte, spyr han ut; Gud driv det ut or magen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Han orme-eiter i seg saug, og ødle-tunga honom drep.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Han fær visst ikkje skoda bekkjer, ei heller flaum av mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Han rikdom vinn, men nyt han ikkje; han samlar gods, men vert’kje glad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Han krasa småfolk, let deim liggja, han rana hus som han ei byggjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Han kjende ikkje ro inni seg, men med sin skatt han slepp’kje undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Hans hækna sparer ingen ting; og difor kverv hans lukka burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'I all si ovnøgd lid han naud; kvar armings-hand kjem yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Og til å fylla buken hans han sender vreiden yver honom, let maten sin på honom regna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Og um han frå jarnvåpen flyr, han såra vert frå koparbogen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'ut gjenom ryggen pili kjem, den blanke odd ut or hans gall, og dauderædslor fell på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Alt myrker gøymt er åt hans skattar, ja, ukveikt eld et honom upp, og øyder all hans eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Himmelen ter hans brotsverk fram, og jordi reiser seg imot han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Hans heime-forråd fer sin veg, renn burt på vreidedagen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Slikt etlar Gud til gudlaus mann; det lovar Gud til arv åt honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Då svara Job og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '«Å høyr då, høyr på mine ord! Gjev i minsto det til trøyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Lat meg få lov å tala ut, so kann du spotta etterpå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Klagar eg vel på menneskje? Og hev eg ikkje grunn til harm?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Vend dykk til meg, og ottast so; legg handi so på dykkar munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Eg støkk, når eg det kjem i hug; ei bivring gjenom kroppen gjeng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Kvifor fær dei gudlause liva, auka i magt som åri gjeng?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Dei ser si ætt stå fast ikring deim, dei hev sitt avkjøme for augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'I fred stend husi deira trygge, Guds svipa råkar ikkje deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'med heppa parast deira fe, og kyrne kastar aldri kalv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Dei slepper borni ut som lamb, og gutarne i leiken hoppar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Dei syng til trumma og til cither og frygdar seg ved fløyteljod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'I lukka liver dei si tid og fer so brått til helheim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Til Gud dei segjer: «Haldt deg burte!» Me vil’kje kjenna dine vegar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kvi skal me tena den Allsterke? Kva gagnar det å be til honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, '«Dei hev’kje lukka si i handi» - Langt burt frå meg med gudlaus råd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Når sloknar lampa for gudlause? Når kjem ulukka yver deim? Gjev han deim straff i vreidesmod?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Fer dei vel burt som strå for vind, lik agner som i stormen fyk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, '«Gud gøymer straffi til hans born.» Nei, sjølv skal mannen straffi kjenna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Lat han få sjå sitt eige fall og drikka harm frå den Allsterke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Kva bryr han seg vel um sitt hus, når månadstalet hans er fullt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Vil nokon hjelpa Gud til kunnskap, han som er domar for dei høgste?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Den eine døyr på velmagts høgd, fullkomleg trygg og fredeleg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'hans fat er fulle utav mjølk, og i hans bein er mergen frisk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'den andre døyr so beisk i hug, hev ingenting av lukka smaka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Dei båe vert i moldi lagde, og deira klednad makkar er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Sjå kor eg kjennar dykkar tankar, og dykkar meinkrokar mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'De spør: «Kvar er vel stormannshuset? Kvar er det tjeld der gudlause bur?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Hev de’kje høyrt av ferdafolk - de trur vel det som dei fortel -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, '«Den vonde frå ulukka slepp; han berga vert på vreidedagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kven lastar honom for hans ferd? Og straffar honom for hans gjerd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Han vert til gravi båren burt, og ved hans gravhaug held dei vakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Søtt søv han under torv i dal, og i hans far all verdi fer, som tallause gjekk fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Det trøystar meg med tome ord; av dykkar svar er sviket att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Då tok Elifaz frå Teman til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '«Er mannen vel til gagn for Gud? Nei, vitug mann seg sjølv mun gagna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Hev Allvald bate av di rettferd? Er det hans vinst, at rett du ferdast?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Er det din gudlegdom han refser, når han med deg held rettargang?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Hev ei din vondskap vore stor og dine syndar utan ende?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Grunnlaust du panta dine brøder; halvnakne drog du klædi av;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'den trøytte gav du ikkje vatn, den svoltne negta du ditt brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Det er den sterke som eig landet, den stolte hev si bustad der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Du jaga enkjor burt tomhendt’ burt, slo armen av på faderlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Difor ligg snaror kringum deg, og rædsla skræmer deg so brått.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ell’ vert du ikkje myrkret var, den flaum som fossar yver deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Bur ikkje Gud i himmelhøgd, sjå øvste stjernor, høgt dei sit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Du segjer so: «Kva veit vel Gud? Kann attum skyerne han døma?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'For skyer dimmer augo hans; han hev sin gang på himmelkvelven.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Seg, vil du fylgja fortids-vegen, den stig som illverksmenner gjekk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Dei som i utid tekne vart - og deira grunn flaut burt i flaum -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'som sagde til Gud: «Haldt du deg burte!» Kva skulde Allvald vel deim gjera?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Endå han signa deira hus - langt burt frå meg med gudlaus råd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Rettvise folk det såg med gleda, og den skuldlause spotta deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '«Fiendarn’ våre gjekk til grunns! Sjå elden øydde det dei leivde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Vert ven med honom, og få fred! So skal og lukka timast deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Og tak so lærdom av hans munn, og legg deg ordi hans på hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Vend um til Allvald, då du byggjest og jagar syndi frå ditt tjeld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Kast gullet ditt i moldi ned - Ofir-gull millom bekkjesteinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Allvald skal vera då ditt gull og haugar utav sylv for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Då skal du frygda deg i Allvald, di åsyn lyfta upp til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Og når du ropar, vil han høyra, so du kann halda det du lovar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Det du deg etlar, skal du vinna, og ljos skal skina på din veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Gjeng vegen ned, du ropar: «Upp!» Han hjelpar den bljug-øygde mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Ja, ikkje-skuldfri mann han bergar, frelst vert han ved di reine hand.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Då svara Job og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '«Endå gjeld klaga mi for tråss, tungt legg eg handi på min sukk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Berre eg kunde finna honom og koma til hans bustad fram!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Då la eg fram for han mi sak og fyllte munnen min med prov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Då høyrde eg kva svar han gav, og merka det han sa til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Vilde med magt han mot meg standa? Nei, lyda på meg vilde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Ein skuldfri stod då for han fram; for alltid slapp eg domar min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Gjeng eg i aust, han er’kje der; mot vest, eg vert han ikkje var;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'i nord han verkar, ei eg ser han, han snur mot sud, eg ser han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'For all den veg eg fer han kjenner; prøvde han meg, eg var som gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Min fot hev fylgt i faret hans; hans veg eg gjeng ubrigdeleg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'veik ei frå det hans lippa baud, meir enn mi lov eg lydde hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Men ein er han, kven hindrar honom? Det han hev hug til, gjer han og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Han um min lagnad avgjerd tek, og hev med meg so mangt i emning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Eg difor ræddast for hans åsyn, når eg det minnest, skjelv eg for han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Ja, Gud hev brote ned mitt mod, og Allvald hev gjort meg fælen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'ei er det myrkret som meg tyner, og ei mi eigi myrke åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Kvi hev’kje Allvald tider set? Kvi ser hans vener ei hans dagar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Dei fører deildesteinar burt, stel fe og sender det på beite,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'tek asnet frå den faderlause; tek kui enkja eig i pant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Driv fatigfolk frå vegen burt; alt landsens småfolk kryp i skjol;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Lik ville asen fer dei ut til øydemarki med sitt stræv; og veidefang på ville heid er maten borni deira fær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Dei haustar mark ved nattetid, og gudlaus manns vinhage plundrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Um natti nakne, utan klæde, dei hev for kulden inkje dekkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Dei våte vert av regn på fjell, held seg i bergufs utan livd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Ein farlaus lyt frå moderbarm ein armings klæde gjeng i pant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Dei nakne gjeng og klædelause, i hunger dei på kornband dreg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Dei kreistar olje innum murar, dei persar vin og tyrster lel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Frå byen høyrest styn av menner, og gjenomstungne skrik um hjelp, men Gud ser ei slik meningsløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Det finst og fiendar åt ljoset; dei kjenner ikkje ljossens vegar og held seg ei på ljossens stigar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Ved dagsprett mordaren stend upp, slær arm og fatig mann i hel, um natti er han so som tjuven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Horkaren spæjar etter skyming; han tenkjer: «Inkje auga ser meg.» Sitt andlit gøymer han med maska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'I myrkret bryt dei inn i hus, dei som ved dag seg inne stengjer dei seg inne; av ljoset vil dei ikkje vita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Myrk natt er morgon for deim alle; for natteskræmslorne dei kjenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Snøgt fer han yver vatnet burt, bannstøytt vert jordi hans i landet; til vinberg gjeng han ikkje meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Som snøvatn kverv for turk og hite, so gløyper helheim deim som synda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Av moderlivet gløymd han er, og makkar mettar seg på honom; det ingen er som minnest han; so brotsverk brest liksom eit tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Han plundra ho som ikkje fødde, som ufør var til barne-eign; mot enkja gjorde han’kje vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Men han styd valdsmann med si kraft, og dei fær atter standa upp som hadde mist all von um livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Han styd deim so dei liver trygt, hans augo vaktar deira vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Høgt stig dei, brått - dei er’kje meir - dei sig og døyr som alle andre, vert skorne av som aks på strå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Er det’kje so? Kven legg imot? Kven gjer no mine ord um inkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Då tok Bildad frå Suah til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '«Hjå honom magt og rædsla finst; han i sin himmel freden skaper.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Kven veit talet på hans herar? Kven yverstrålar ei hans ljos?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kor kann ein mann ha rett mot Gud? Er vel ein kvinnefødd uskuldig?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Sjå, månen er’kje klår ein gong, og stjernon’ er’kje reine for han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Enn mannen då, den vesle krypen? Menneskjebarnet, denne makk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Då svara Job og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Kvar helst hev du den veike hjelpt? Når studde du den trøytte arm?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Kvar gav du uklok mann ei råd? Kor ovleg visdom hev du synt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Kven hev du bore melding til? Kva ånd hev tala gjenom deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Skuggarne i angest skjelva, vatsdjup og dei som deri bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Helheimen open ligg for honom, avgrunnen utan noko dekkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Nordheimen han i audni spana, og hengde jordi yver inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Han vatnet inn i skyer bind; og skyi brest ei under det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Kongsstolen sin han gøymer burt og breider skyer yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Kring vatni han ei grensa set, der som ljos og myrker byta skal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Stolparne under himmelen skjelv, og rædde vert dei for hans trugsmål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Han rører havet upp med velde, og med sit vit han krasar ubeist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Og himmelen klårnar ved hans ande; hans hand den snøgge ormen drap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Sjå her utkanten av hans veg; det berre kviskring er me høyrer. Kven skynar, når hans allmagt torar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Job heldt fram med talen sin og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '«So sant Gud liver, som meg sveik, og Allvalds som meg volde sorg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, '- for endå eg min ande dreg; i nosi mi er guddomspust -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Urett ligg ei på mine lippor; mi tunga talar ikkje svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'D’er langt frå meg å gje’ dykk rett, mi uskyld held eg fast til dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Mi rettferd held eg fast uskjepla, eg ingen dag treng skjemmast ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Min fiend’ skal seg syna gudlaus, min motstandar som urettferdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Kva von hev en gudlaus att, når Gud vil sjæli or han draga?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Vil Gud vel høyra skriket hans, når trengsla bryt innyver honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Kann han i Allvald vel seg gleda? Kann han kvar tid påkalla Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Eg um Guds hand vil læra dykk; kva Allvald vil, det dyl eg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Sjå dette hev det alle set; kvi talar de då tome ord?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Den lut fær gudlause av Gud, den arven valdsmann fær av Allvald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Til sverdet veks hans søner upp; hans avkom mettast ei med brød;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'dei siste legst i grav ved pest, og enkjorne held ingi klaga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Og um han dyngjer sylv som dust og samlar klæde liksom leir:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Den rettvise tek klædi på; skuldlause skifter sylvet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Han byggjer huset sitt som molen, likt hytta vaktmannen set upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Rik legg han seg - men aldri meir; han opnar augo - og er burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Som vatsflaum rædsla honom tek, ved natt riv stormen honom burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Han driv av stad for austanvind, som blæs han frå hans heimstad burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Han utan miskunn på han skyt; frå handi hans han røma må.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Med hender klappar dei åt han og pip han frå hans heimstad burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Sylv hev sin stad, der dei det finn, og gullet, som dei reinsa vinn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'og jarn fram or jordi fær, og kopar ut or steinen bræ’r;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'På natteskuggen gjer dei slutt og myrkheims steinar granskar ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Djupt under by med annsamt liv i gruvor bergmenn kliv og sviv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'På jordi brødkorn fram dei driv, men inni upp som eld dei riv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Safiren sit i steinar der, og der seg og gullklumpar ter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Ei ørnen kjenner denne veg, for haukesyn han løyner seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Ei stolte rovdyr vegen fann, og løva aldri gjeng på han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'På harde steinen dei handi legg; då sturtar mang ein bergevegg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'I berget seg gangar grev og skodar mang ein skatt so gjæv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Dei dytter til for rennand’ å, det løynde fram for ljoset må.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Men visdomen, kvar er han å få? Og kvar skal ein vitet nå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Slett ingen veit hans verd og vinst; i manneheim han ikkje finst;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Avgrunnen dyn: «Her ei han er!» Og havet segjer: «Ikkje her!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Du kann’kje kjøpa han for gull, men sylv ei vega prisen full,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'og ei for gull ifrå Ofir, ei for onyks, ei for safir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Ei gull og glas er nok til kaup, og ei til byte fingull-staup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Korall, krystall gjeld ikkje her. Visdom er meir enn perlor verd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Topas frå Kus er altfor ring, ja, reinast gull vert ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Visdomen, kvar kjem han ifrå? Og kvar skal ein til vitet nå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Det ingen veit på denne jord; ei fugl det fann, kvar helst han for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Avgrunn og daude segjer greidt: «Eit gjetord er alt det me veit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Men Gud han kjenner denne veg; han veit kvar visdom løyner seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Han skodar heilt til heimsens tram, og under himmeln ser han fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Då vinden han med vegti vog og sette mål for vatnet og,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'då han gav regnet lovi si og ljomet veg å ganga i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'då såg han og synte fram og granska honom umhugsam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Til menneskja han sagde so: «I Herrens otte visdom sit, og fly det vonde, det er vit.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Då heldt Job fram med talen sin og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '«Å, var eg som i fordums måna’r, som den gong Gud mi verja var,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'då yver meg hans lampa skein, som lyste meg i myrkret fram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'slik som eg var i mogne manndom, då Gud var ven i huset mitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'då Allvald endå med meg var, og mine born eg kring meg såg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'då eg i fløyte foten tvådde, og olje rann av fjellet nær meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'då eg til porten steig i byen, og sessen min på torget tok!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Ungdomen såg meg, løynde seg; dei gamle reiste seg og stod;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'hovdingar stogga midt i talen og lagde handi på sin munn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'og røysti tagna hjå dei gjæve, og tunga seg til gomen kleimde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'dei som meg høyrde, sælka meg, og dei som såg meg, vitna for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Eg berga arming når han ropa, og farlaus som var utan hjelp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'velsigning fekk eg frå forkomne, og enkjor fekk eg til å jubla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Rettferd var min, eg hennar bunad; rett var mi kappa og mi kruna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Eg for den blinde auga var, og føter var eg for den halte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Ein far eg var for fatigfolk; eg for ukjende saki granska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'På brotsmann tennerne eg knekte, reiv fengdi utor gapet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Eg sagde: «I reiret skal eg døy, med dagar talrike som sand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Til roti mi skal vatnet trengja, dogg bu ved natt på greini mi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'mi æra held seg frisk hjå meg, bogen vert ny handi mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Dei høyrde ventande på meg, og lydde stilt på rådi mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Og ikkje la dei mot mitt ord, min tale draup ned yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'På meg dei bia som på regn, ja, som vårregn opna munnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Eg smilte til mismodige, mitt andlit fekk dei ikkje myrkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Når eg deim vitja, sat eg fremst, sat som ein konge i sin herflokk, lik ein som trøystar syrgjande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Men no er eg til spott for deim som yngre er av år enn eg; eg deira feder ikkje fann verdige plass hjå gjætarhunden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Magtlause er og deira hender, og deira saft og kraft er burte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Dei magre er av naud og svolt, dei gneg i turre øydemarki som alt i går var reine audni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'og plukkar melde millom kjørri og hev til føda einerot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Frå folket vert dei jaga burt, fær tjuvemann slengt etter seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Dei gøymer seg i fæle gil, i holor uti jord og fjell;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'og millom buskor skrålar dei og samlast under netlerunnar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'ei ætt av dårar og namnlause som ein helst piskar ut or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'No er eg slengjestev for deim, eit ordtak hev for deim eg vorte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Dei styggjest ved meg, held seg burte og sparer ei å sputta på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Utan all blygd dei krenkjer meg, hiv av kvart band framfor mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Eit utjo reiser seg til høgre, dei spenner mine føter burt, og legg ulukke-vegar mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Og stigen min den bryt dei upp og hjelper til med mi ulukka, dei som er hjelpelause sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Som gjenom vide murbrot kjem dei, velter seg fram med bråk og brak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Imot meg vender rædslor seg, mi æra elter dei som stormen, mi velferd kvarv som lette sky.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'No jamrar seg mi sjæl i meg; usæle dagar held meg fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Natti gneg mine knokar av meg, min verk, mi pina aldri søv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Ved allmagt vert min klædnad vanstelt, heng tett som skjortekragen kring meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Han kasta meg i skarnet ned; og eg ser ut som mold og oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Eg skrik til deg, du svarar ikkje, eg stend der, og du stirer på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Hard hev du vorte imot meg, du stri’r mot meg med veldug hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du let meg fara burt i stormen, du let meg tynast i hans brus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Eg veit du fører meg til dauden, der alt som liver samlast lyt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Kven kavar ikkje når han søkk? Kven ropar ikkje ut i fåren?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Gret eg’kje sjølv med den fortrykte, og syrgde yver fatigmann?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Eg vona godt, men det kom vondt, eg venta ljos, men myrker kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Det kokar allstødt i mitt indre, ulukkedagen møter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Svart gjeng eg kring, men ikkje solbrend, eg ris i flokken, skrik um hjelp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Bror åt sjakalar hev eg vorte, til strussar eg ein frende er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Mi hud er svart og flaknar av; det brenn i mine bein av hite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Min cither hev eg bytt i sorg, og fløyta mi med gråtar-mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Med augo hev eg gjort ei pakt; eg skal’kje skygna etter møy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Kva gav meg elles Gud der uppe? Kva arv gav Allvald frå det høge?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Kjem ikkje udådsmann i naud? Og illgjersmenn i ulukka?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ser ikkje han på mine vegar? Tel ikkje han kvart stig eg gjeng?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Dersom eg fram med fals hev fare, og foten sprunge etter svik');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, '- Gud vege meg på rettferds vegt, so han kann sjå eg skuldlaus er! -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Veik mine stig frå vegen av, hev hjarta etter augo gjenge, var det ein flekk på mine hender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'so gjev ein annan et mitt såd, og riv mi planting upp med rot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Let eg min hug av kvinna dåra, sneik eg til grannens dør meg fram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'so lat mitt viv åt andre mala, og andre yver ho seg bøygje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'For dette er ei skjemdarferd, eit brot som dom og straff fortener,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'ein eld som eta vil til avgrunns og øydeleggja all mi eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Vanvyrd’ eg retten åt min træl og trælkvinna i trætta med deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, '- Kva gjord’ eg då, når Gud reis upp? Kva svara eg, når han meg klaga?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Dei er som meg i morsliv skapte; ein forma oss i moderfang -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Um eg sagde nei når arming bad, og let enkja gråtande gå burt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'hev eg mitt brød åleine ete, so farlaus inkje fekk ein bit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '- nei, far for han eg var frå yngdi, frå morsliv var eg hennar førar -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Såg eg ein stakar utan klæde, ein fatig utan yverplagg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'og so hans lender ei meg signa, og ei mi saueull han vermde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'hev eg mot farlaus handi lyft, av di eg medhald fekk i retten:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Let herdi mi or led då losna, og armen brotna frå sitt bein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'For eg var ovleg rædd Guds straff, eg magtlaus stod framfor hans velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Um eg mi lit til gullet sette, og voni til det fine gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Gledde eg meg ved auka rikdom, og alt eg vann meg med mi hand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'såg eg på ljoset når det stråla, på månen der han skreid i glans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'vart hjarta mitt i løyndom dåra, so kyss på hand til deim eg sende,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'so var det og straffande brot, då neitta eg min Gud der uppe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Hev eg meg gledt ved uvens uferd, og jubla når han kom i skade,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '- men eg let ikkje munnen synda og banna honom ifrå livet -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'hev ei mitt husfolk stendigt sagt: «Kven gjekk vel svolten frå hans bord?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, '- Eg let’kje framand natta ute; for ferdamann eg opna døri -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'hev eg som Adam dult mi synd, og løynt mi misgjerd i min barm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'di eg var rædd den store hop og ottast spott frå ættefrendar, so stilt eg heldt meg innum dører?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Å, vilde nokon høyra på meg! Sjå her er underskrifti mi, lat berre Allvald svara meg! Fekk eg den skrift min motpart skreiv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'den skulde eg på oksli bera og binda på meg som ein krans');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'eg melde honom kvart mitt stig, og som ein hovding møta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Dersom min åker klagar meg, og um plogforerne lyt gråta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'åt eg hans grøda ubetalt, tok livet eg av eigarmannen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Lat då for kveite klunger gro, og ugras der eg sådde bygg!» Her endar Jobs tale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Dei tri mennerne svara ikkje Job meir, av di han heldt seg sjølv for rettferdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Men då loga harmen upp hjå Elihu, son åt Barak’el, buziten, av Rams-ætti. Han vart harm på Job, av di han heldt seg sjølv rettferdigare enn Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Han harmast og på dei tri venerne, av di dei ikkje kunde finna noko svar, og endå dømde Job skuldig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'For Elihu hadde venta med å tala til Job, av di dei andre var eldre enn han;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'men då Elihu såg at dei tri mennerne ikkje hadde noko å svara, vart han brennande harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Og Elihu, son åt Barak’el, buziten, tok til ords og sagde: «Ung er eg etter år å rekna; de derimot er gamle menn. Difor eg blygdest og var rædd å segja til dykk det eg veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Eg tenkte: «Åri tala lyt og alderen forkynna visdom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Nei, ånd lyt til hjå menneski; og Allvalds ande gjev deim vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Dei gamle er’kje alltid vise, kvithærde veit’kje stødt det rette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Difor eg segjer: Høyr på meg; eg vil og segja det eg veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Eg venta hev på dykkar ord og lydde vel på dykkar lærdom, alt med de leita etter ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Og eg gav nøgje agt på dykk, men ingen sagde Job imot, ingen av dykk gav honom svar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Seg ikkje: «Visdom der me fann; Gud slå han ned, folk kann det ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Han hev’kje tala imot meg, og ei med dykkar ord eg svarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Dei er forstøkte, svarar ikkje, dei vantar ord å føra fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Treng eg vel venta når dei tegjer og stend der reint forutan svar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Eg vil og svara, eg for meg, eg vil og segja det eg veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'For eg er full av ord til svars; i bringa sprengjer åndi på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Mitt indre er som innstengd vin, lik nye vinhit vil det sprengjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Eg tala vil so eg fær luft, vil opna lipporne og svara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Eg ikkje tek parti for nokon og smeikjer ei for nokor mann;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'å smeikja kann eg ikkje med; min skapar elles burt meg reiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Men høyr no, Job, på talen min, lyd vel på alle mine ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Sjå eg hev opna mine lippor, og tunga talar i min munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Frå ærlegt hjarta kjem min tale, rein kunnskap lipporne ber fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Guds ånd er det som meg hev skapt, og Allvalds ande gjev meg liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Um du det kann, so gjev meg svar! Væpna deg mot meg, og stig fram!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Eg er din likemann for Gud, eg og av leiret forma er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Du tarv’kje vera rædd for meg, min trykk skal ikkje tyngja deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Men du hev sagt for øyro mine - eg høyrde ljoden av ditt ord -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '«Eg skuldfri er og utan synd, eg flekkfri er og utan skuld;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'men han fører uvensgrunnar mot meg og held meg for sin fiendsmann;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'han legg i stokken mine føter og vaktar alle mine vegar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Men du hev urett, svarar eg; Gud større er enn menneskja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Men kvifor vil du klaga på han: Han aldri svarar i sin sak?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'På eit vis talar Gud, ja tvo, um enn dei ikkje agtar på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'I draumar og i syn ved natt, når tunge svevnen fell på folk, når dei på lægjet ligg og blundar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'då let han øyro upp på folk, og innsiglar åtvaring til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'for burt frå synd å driva mannen, og rydja ovmod ut or honom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'og berga sjæli hans frå gravi og livet hans frå spjotodd-daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Han tuktast og med sjukelægje, med stendig uro inn til beini,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'hans liv fær mothug imot brød, og sjæli hans mot lostemat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Hans misser holdet, vert usjåleg, og beini morknar, syner ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'og sjæli ned mot gravi lutar, hans liv mot daude-englarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Er det då yver han ein engel, ein millommann, ein utav tusund, som lærer mannen um hans plikt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Han ynkast yver han og segjer: «Frels honom frå i grav å ganga! Eg hev ei løysepening funne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Hans likam skal av helsa bløma, sin ungdom skal han atter få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Han bed til Gud og nåde fær, so han hans åsyn ser med jubel. Og so fær mannen att si rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Han syng for folk og segjer so: «Eg synda hev og krenkt det rette, men hev’kje fenge lika for det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'mi sjæl frå gravi berga han, med gleda fær eg ljoset sjå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Og sjå: alt dette gjerer Gud tvo gonger, ja tri gong’ mot mannen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'og ber hans sjæl frå gravi burt, so livsens ljos kann lysa for han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'So gjev no gaum og høyr meg, Job, ver tagall du, so eg kann tala!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Um du hev ord, so gjev meg svar! Tala, eg gjev deg gjerne rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'I anna fall so høyr på meg, teg medan eg deg visdom lærer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Og Elihu tok til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '«Vismenner, høyr på ordi mine! Kunnige folk, lyd no på meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'For ordi prøver ein med øyro, som ein med gomen maten smakar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'So lat oss no det rette velja og saman finna ut det gode!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'For Job hev sagt: «Eg skuldfri er; min rett hev Gud ifrå meg teke;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'tråss i min rett, stend eg som ljugar, uskuldig fekk eg ulivssår.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Finst det vel nokon mann som Job? som gløyper hædings ord som vatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'som held med illgjerdsmenner lag, hev umgang med gudlause folk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'For han hev sagt: «Kva gagnar det ein mann å vera ven med Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Difor, de menn med vit, høyr meg! D’er langt frå Gud å vera gudlaus, frå Allvalds-Gud å gjera urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Han løner mannen for hans gjerd, fer med han etter all hans ferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Nei, urettferdig er’kje Gud, og Allvald krenkjer ikkje retten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kven let vel honom styra jordi? Og kven hev grunna jordheims-kringen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Um han på seg åleine tenkte og drog sin ande til seg att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'då gjekk alt livande til grunns, og menneskja vart atter mold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Um du er klok, so høyr på dette, og lyd på ljoden av mitt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Kann ein som hatar retten, styra? Fordømer du den allrettvise?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Kann ein til kongen segja: «Niding!» Og til dei megtige: «Du brotsmann?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Til han som ei gjer skil på fyrstar, og ikkje vyrder rik mot fatig. Av di hans hand hev skapt deim alle?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Dei andast brått og midt um natti, eit folk avjagast og kverv burt, stormenn forgjengst i hjelpeløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Hans augo ser til mannsens ferd, han skodar kvart eit stig han tek;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'det finst’kje skugge eller myrker der illgjerdsmenn kann løyna seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Han tarv’kje lenge sjå på mannen fyrr han lyt møta Gud til doms.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Han utan forhøyr storfolk krasar og andre set i deira stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Han kjennar heile deira verk og gjev um natti deim til tyning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Han tuktar deim som illgjerdsmenner, ein stad der alle kann det sjå,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'dei som hev vike burt frå han og ikkje hev hans vegar fylgt -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'so han kann høyra armods klaga og jammerskrik frå undertrykte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Fær han det stilt, kven vil fordøma? Løyner han seg - kven kann då sjå han? - for folkemugen og for mannen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'so ikkje gudlaus mann skal råda og vera snaror yver folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'For segjer ein vel so til Gud: «Ovmodigt hev eg bore meg; eg vil ikkje lenger vera vond.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Vis du meg det eg ikkje ser! hev eg gjort synd, vil eg snu um?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Skal han då straffa som du tykkjer? D’er du som er den misnøgde; so lyt du velja, ikkje eg; og du fær segja det du veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Dei kloke folk vil segja til meg, og kvar ein vismann som meg høyrer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '«Job talar ikkje med forstand hans ord er utan ettertanke.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Gjev Job må allstødt verta prøvd for sine svar på nidings vis!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'For han legg brotsverk til si synd og ber seg vyrdlaust millom oss, og talar mange ord mot Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Og Elihu tok til ords og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '«Seg, trur du vel at slikt er rett, so du meir rettvis er enn Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'når djervt du spør: «Kva gagn hev eg, kva løn um eg frå syndi flyr?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'På dette vil eg svara deg og likeins venerne med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Ditt auga du mot himmelen snu, og sjå på skyerne der uppe!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Di synd, kann ho vel skade honom? Lid han, um dine brot er mange?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Er du rettvis, kva gjev du honom? Kva fær han då utav di hand?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Di synd vedkjem ein mann som deg, di rettferd gjeld eit menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Dei klagar yver urett stor og skrik um hjelp mot valdsmenns arm;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'men spør’kje: «Kvar er Gud, min skapar, som let ved natt lovsongar tona,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'gjev oss meir vit enn dyr på mark og meir forstand enn fugl i luft?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Der ropar dei - han svarar ikkje - um hjelp mot ovmod hjå dei vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Gud høyrer ei på tome ord, slikt agtar Allvald ikkje på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Um enn du segjer du ei ser han, han ser han nok saki, bi på honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Og no, når vreiden hans ei refser, tru han ei kjenner dårskapen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Men Job let upp sin munn til fåfengd, uvitugt talar han so mykje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Og Elihu heldt fram og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '«Vent litt og lat meg tala til deg! For endå hev eg ord for Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'eg hentar kunnskap langan leid, skal hjelpa skaparen til rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'For visst, mitt ord skal ikkje ljuga; framfor deg stend ein full-lærd mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Sjå, Gud er sterk, men vander ingen, han som er veldug i forstandskraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Han let’kje gudlaus mann få liva; men armingarne gjev han rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Han snur’kje augo frå rettvise; hjå kongar på sin konungsstol han let deim ævleg sitja høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Um dei i lekkjor bundne vart og i ulukkesnaror fanga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'so synar han deim deira ferd og brot - at dei ovmoda seg -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'til refsing opnar øyro deira og byd deim venda um frå syndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Um dei då høyrer vil og lyda, so liver dei sitt liv i lukka og sine år i herlegdom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'um ikkje, fær dei styng av spjotet, og i sin dårskap andast dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Men vreiden trivst i vonde hjarto; dei bed’kje, um dei bundne vert;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'i ungdomstidi skal dei døy, forgangast som utukt-sveinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Han frelser arming ved hans naud, opnar hans øyro gjenom trengsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Deg og han lokkar ut or trengsla, fritt fær du det og ikkje trongt, ditt bord er fullt av feite retter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Men fær du straff som syndug mann, i fall hans domsord held deg fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Lat ikkje tukti avla vreide, den tunge bot deg leida vilt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Kann klaga hjelpa deg or naud, kor mykje enn du stræva vil?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Du må’kje lengta etter natti då folk vert rykte frå sin stad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Gjev agt, so ei til synd du vender, for det du heller vil enn lida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Sjå, Gud er upphøgd i sitt velde; kven er ein lærar slik som han?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kven hev vel vegen lagt for honom? Kven sagde vel: «Du hev urett gjort?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Hugs på å prisa høgt hans verk, som menneski hev sunge um!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Kvart menneskje med lyst det ser, mann-ætti ser det langan leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Upphøgd, uskynande er Gud, hans liveår kann ingen telja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'for han dreg vatsdroparne, so det vert regn av skodde-eim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Og ifrå skyerne det fløymer og dryp ned yver mange folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Kven skynar vel skyhoparne og torebraket frå hans hytta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Han breider ljoset sitt ikring seg og let det hylja havsens røter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Soleis han dømer folkeslag og skiftar brød i ovmengd ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Han sveiper henderne i ljos og sender det mot fienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Hans tora meldar um hans koma, ja, feet varslar når han kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'For dette bivrar hjarta mitt og lyfter seg frå staden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Å, høyr på harmen i hans røyst, den dun som dundrar or hans munn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Det fer burt under himmelkvelv, men elden skin til heimsens endar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'So burar røysti etterpå, han torar med sitt stolte mod, og ljoni held han ikkje att når røysti si han ljoma let.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gud torar underfullt med røysti, gjer storverk som me ei kann skyna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Han snøen byd: «Fall ned til jord!» Til regnet og, sitt sterke silregn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Han stengjer av for mannehand, so all hans skapning læra må.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Villdyri gjeng til sine hi og kvilar på sin legestad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Or inste kammer kjem det storm, og kulde ut av vindarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Utav Guds ande gustar frost, dei vide vatni kjem i tvang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Han lastar skyi og med væta og breider sine elding-skyer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'og hit og dit dei hastar fram, og skifter leid som han det vil og set i verk det som han byd, utyver vide jordheims-kringen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'anten til ris, når jordi treng det, ell’ og med nåde lyt dei råka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Job, lyd på dette, statt no still, gjev gaum på undri Gud hev gjort!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Veit du når Gud deim segjer fyre, og let sitt ljos or skyi skina?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Veit du vel korleis skyi sviv, um underi åt den Allvise?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Du som i heite klæde styn, når jordi brenn i sunnanvind?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Gjer du med honom himmelkvelven, som er so fast som støypte spegel?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Lær oss, kva me skal segja honom! Me tegja lyt for berre myrker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Skal han få melding at eg talar? Vil nokon ynskja seg å tynast?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'No kann ein ikkje ljoset sjå, um enn det klårt på himmeln skin, men vinden sopar skyi burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Langt nordanfrå kjem gullet hit, ein fælsleg glans ligg yver Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Til Allvald kann me ikkje nå, til han som er so stor i magt; men rett og rettferd ei han krenkjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Difor ber folket age for han, han ansar ingen sjølvklok mann.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Og Herren svara Job or stormen og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '«Kven er det som gjer rådgjerd myrk med ord som reint er utan skyn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Spenn som ein mann ditt belte på, gjev meg på mine spursmål svar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kvar var du då eg grunna jordi? Seg fram, i fall du greida hev!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kven sette måli - veit du det? - Og spana målsnor yver henne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Kvar vart pelaran’ sette ned? Kven la vel hennar hyrnestein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'med alle morgonstjernor kvad, gudssønerne av gleda song?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Kven stengde havet inn med dører, då det braut ut or moderfang?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Då eg det skyer gav til klæde og myrkeskodd til sveip åt det');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'då eg for det ei grensa sette og trygga ho med port og bom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'og sagde: «Hit og ikkje lenger! Di byrge bylgja stogge her!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Baud du vel dagsprett nokon gong? Gav du morgonroden stad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'so femner kringum ytste jordi, so syndaran’ vart riste av?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Då tek ho form som leir for segl, og all stend greinlegt som ein klædnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Då misser gudlause sitt ljos, den arm som lyfte seg, vert knekt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Kom du til havsens kjeldor fram, hev du på avgrunns-botnen gjenge?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Hev daude-portarn’ vist seg for deg? Ja, såg du daudeskuggens portar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Og hev du vel jordviddi set? Kjenner du alt i hop, seg fram!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Kvar finn ein veg dit ljoset bur? Og kvar hev myrkret heimen sin?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'So du kann henta deim til grensa og vita veg til deira hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Du veit det, du vart fødd den gong, og dagetalet ditt er stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Kom du dit snøen uppspard ligg? Og såg du forrådshus for haglet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'som eg til trengsle-tidi gøymer, til dagarne med kamp og krig?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Kva veg tru ljoset deiler seg, austanvinden spreider seg på jordi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kven laga renna vel for regnet og brøytte veg for torestrålen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'so væta kjem til aude land, til øydemark der ingen bur,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'til kveikjing for den nakne heid, so gras kann gro der fyrr var bert?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Skal tru um regnet hev ein far? Kven avlar vel doggdroparne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Kva moderliv kom isen or? Kven avla rim i himmelrømd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'når vatnet hardnar liksom stein, når havflata stivnar til?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Bind du vel bandet um Sjustjerna? Løyser du lekkjet av Orion?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Set du rett tid for dyreringen? Og driv du Bjørnen og hans ungar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Kjenner du himmelleverne? Gav du han yver jordi magt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Kann røysti di til skyi nå, so vatnet fløymer yver deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Byd du vel ljoni fara ut, so dei deg svarar: «Her er me?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kven la i myrke skyer visdom? Kven gav forstand til hildringi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kven tel med visdom skyerne? Kven tømer himmelfati ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'når turre mold vert samanrend, jordklumpar kleimer seg i hop?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Gjeng du for løva etter rov og gjev ungløvor deira mette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'medan dei gøymer seg i holor og ligg på lur i busk og kjørr?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Kven yter ramnen føda hans, når upp til Gud hans ungar ropar og flakkar kringum utan mat?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Steingeiti, veit du når ho kidar? Vaktar du riderne åt hindi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Tel måna’rne dei gjeng med unge, og kjenner du deira fødetid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Dei bøygjer seg, fø’r sine ungar, so er det slutt med deira rider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'På marki kidi veks seg store, spring burt og kjem’kje att til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Kven let villasnet renna fritt, tok bandet av det skjerre dyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'som eg gav øydemark til heim, den salte steppa til ein bustad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Det lær åt byen med sitt ståk, slepp høyra skjenn frå drivaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Det finn seg beite millom fjell, og leitar upp kvart grøne strå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Skal tru villuksen vil deg tena, og natta yver ved di krubba?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Kann du til fori honom tøyma, horvar han dalar etter deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Lit du på honom for hans styrke? Og yverlet du han ditt arbeid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Trur du han til å føra grøda heim og draga henne inn i løda?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Struss-hoa flaksar kåt med vengen, men viser fjør og veng morskjærleik?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Nei, ho legg sine egg på jordi, og let so sanden verma deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'ho gløymer at ein fot kann treda og villdyr trakka deim i kras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Hardt fer ho åt med sine ungar, som var dei ikkje hennar eigne; for fåfengt stræv ho ikkje ræddast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'For Gud let henne gløyma visdom, han ei tiletla henne vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Men når ho baskar seg i veg, ho lær åt både hest og mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Skal tru um du gjev hesten kraft og klæder halsen hans med mån?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Let du han som grashoppen springa alt med han frøser skræmeleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Glad i si kraft han marki skrapar og fer so fram mot væpna flokk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Han urædd er og lær åt rædsla, for sverdet ei han vender um,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'det skranglar pilhus yver honom, det blenkjer spjot til styng og skot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Med ståk og bråk han slukar jordi, ustyrleg når stridsluren gjeng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Han kneggjar: «Hui!» når luren læt, han verar striden langan leid, med skrik frå hovdingar og herrop!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Flyg hauken upp ved ditt forstand og spilar vengjerne mot sud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Stig ørnen høgt av di du byd, og byggjer reiret sitt i høgdi? Han bur på berg og held seg der, på kvasse tind og høge nut. Derfrå han spæjar etter mat, hans augo yver viddi skodar. Hans ungar gløypar i seg blod; der det finst lik, der er han og.» Og Herren svara Job og sagde: «Vil klandraren med Allvald trætta? Lat han som lastar Gud då svara!» Då svara Job Herren og sagde: «For ring eg er; kva skal eg svara? Eg handi legg på munnen min. Ein gong eg tala, no eg tegjer, tvo gong’ - eg gjer det ikkje meir.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Og Herren svara Job or stormen og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '«Spenn som mann ditt beltet på, gjev meg på mine spursmål svar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Vil du forspille meg min rett, fordøma meg, so du fær rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Hev du vel slik ein arm som Gud? Kann du som han med røysti dundra?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Pryd deg med høgd og herredom, klæd deg i glans og herlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Lat so din vreide strøyma fram, sjå kvar ein stolt og audmyk han!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Så kvar ein stolt og bøyg han ned, og slå til jord dei gudlause!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Og gøym deim alle under jordi, bitt deira andlit fast i løynd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'So skal eg og lovprisa deg, som siger med di høgre vann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Sjå elvhesten! Eg hev skapt han liksom deg; som ein ukse et han gras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Sjå då krafti i hans lender, i bukmusklarne hans styrke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Halen gjer han stiv som ceder, fast bogsenarne er tvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Knokarne er koparrøyrer, beini som jarnstenger er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Av Guds verk er han det fyrste, av sin skapar fekk han sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Bergi ber åt honom for, alle villdyr leikar der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Under lotusbusk han kviler, løyner seg i røyr og sev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Lotusbusk gjev honom skugge, piletre umkransar honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Strid gjeng elvi, ei han ottast; trygg er han um so sjølve Jordan fossar imot hans gap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Kann ein tak han so han ser det, draga snara gjenom snuten?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Kann du fiska krokodillen, binda tunga hans med taum,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Draga snor i gjenom nosi, hogga krok i kjaken hans?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Vil han tigga um nåde, tala mjuke ord til deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Tru han vil gjera samband med deg og din træl for alltid verta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Kann du han som leikfugl halda for smågjentorne i band? Handlar fiskarlag med honom, skiftar ut til kræmarar? Kann hans hud med spjot du fylla, og hans hovud med harpunar? Berre prøv - du skal det minnast; enn ein gong du gjer det ikkje! Kvar og ein vil missa voni, verta feld ved syni av han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Ingen torer eggja honom; kven kann då mot meg reisa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Kven gav meg, so eg gjev att? Under himmeln alt eg eig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Ei eg tegjer um hans lemer, um hans sterke, væne bygnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Kven hev drege brynja av han, Gjenge inn i duble tanngard?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Kven hev opna kjakeporten? Rædsla kring hans tenner ligg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Sterke er hans skjolde-rader, feste med ei fast forsigling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Tett dei ligg innåt kvarandre, ingi luft slepp millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Eine skjolden i den andre heng i hop, skilst ikkje åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Ljos ifrå hans njosing strålar, augo skin som morgonroden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Or hans gap skyt brandar fram, gneistar sprutar derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Or hans nasar stig det røyk, liksom eim or kjel som kokar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Anden hans set eld på kol, logen ut or gapet stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'I hans nakke styrken bur, rædsla spring framfor hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Tette sit kjøtvalkarne, støypte fast urikkelg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Hjarta hans er hardt som stein, fast som understein i kverni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Kjempor ræddast når han ris, misser både mod og hugs;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Sverd vil ikkje bita på, ikkje skot med spjot og pil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Jarn agtar han liksom strå, kopar nett som fauskeved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Ei han vik for bogesonen; stein frå slyngja vert som halm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'og stridsklubba vert som strå, og han lær åt spjot som susar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Under han er kvasse broddar, spor dei set som treskjeslede.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Djupet kokar som ei gryta, sjøen som ein salvekjel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Vegen lyser etter honom, djupet skin som sylverhår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Liken hans på jord ei finst, denne skapning utan ræddhug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Han ser ned på alt som høgt er, konge yver alle kaute.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Då svara Job Herren og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '«Eg skynar at du allting kann; for deg er ingen plan umogleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kven vil uvitug myrkja rådgjerd? Eg tala som ein fåvis mann um under som eg ikkje fata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Å høyr no, lat meg få tala! Eg vil deg spyrja, lær du meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Fyrr høyrd’ eg berre gjete deg, no ser eg deg med eigne augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Difor eg tek det i meg att og tregar djupt i mold og oska.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Då no Herren hadde tala desse ordi til Job, sagde han til Elifaz frå Teman: «Eg er harm på deg og dei tvo venerne dine, av di de hev ikkje tala rett um meg soleis som Job, tenaren min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Tak difor sju uksar og sju verar, og gakk til Job, tenaren min, og ofra brennoffer for dykk; og lat Job, tenaren min, beda for dykk! For berre honom vil eg taka til nåde, so eg ikkje gjer ulukka på dykk, for de ikkje hev tala rett um meg soleis som Job, tenaren min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Og Elifaz frå Teman og Bildad frå Suah og Sofar frå Na’ama gjekk av stad og gjorde so som Herren hadde sagt til deim, og Herren høyrde Jobs bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'No vende Herren lagnaden for Job, då han bad for venerne sine; og alt det Job hadde ått, fekk han tvifald att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Og alle brørne og systerne hans kom til honom, og like eins alle dei kjenningar han fyrr hadde havt, og dei åt og drakk med honom i huset hans. Og synte honom medynk og trøysta honom for all den ulukka som Herren ført yver honom, og kvar av deim gav honom ein gullpening og ein gullring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Og Herren velsigna den siste livetidi åt Job meir enn den fyrste; han fekk fjortan tusund sauer og seks tusund kamelar og tusund par uksar og tusund asnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Og han fekk sju søner og tri døtter;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'den eine av deim kalla han Jemima, den andre Kesia og den tridje Keren-Happuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Det fanst ikkje so væne kvinnor i heile landet som døtterne åt Job, og far deira let deim erva til liks med brørne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Etter dette livde Job hundrad og fyrti år, og såg born og barneborn, fire ættleder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Og Job døydde gamall og mett av dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Sæl er den mann som ikkje gjeng i råd med ugudlege og ikkje stend på veg med syndarar og ikkje sit i sæte med spottarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'men som hev si lyst i Herrens lov og grundar på hans lov dag og natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Han er lik eit tre som er planta ved vatsbekkjer, som gjev si frukt i si tid, og som lauvet ikkje visnar på; og alt det han gjer, hev han lukka med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Ikkje so er det med dei ugudlege; men dei er lik agner, som vinden føykjer burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Difor skal dei ugudlege ikkje standa seg i domen, og syndarar ikkje i samlingi av dei rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'For Herren kjenner vegen dei rettferdige fer, men den vegen dei ugudlege fer, gjeng til grunns.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Kvi ståkar heidningarne, og kvi stilar folki på fåfengt verk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Kongarne på jordi reiser seg, og herremennerne legg råd saman imot Herren og den han hev salva:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '«Lat oss slita sund deira band og kasta deira tog av oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Han som tronar i himmelen, lær: Herren spottar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'So talar han til deim i sin vreide, og i sin harm skræmer han deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '«Og eg hev då sett inn min konge på Sion, mitt heilage fjell.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Eg vil fortelja um ei rådgjerd: Herren sagde til meg: «Du er min son, eg hev født deg i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Krev av meg, so vil eg gjeva deg heidningarne til arv og endarne av jordi til eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Du skal knasa deim med jarnstav; som kruskjerald skal du smuldra deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Og no, de kongar, far visleg fram! Lat dykk segja, de domarar på jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Ten Herren med age, og fagna dykk med otte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Kyss sonen, so han ikkje skal verta vreid, og de skal ganga til grunnar på vegen! For hans vreide kunde lett kveikjast. Sæle er alle dei som set si lit til honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Ein salme av David, då han flydde for Absalom, son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Herre, kor mange mine fiendar er! Mange reiser seg imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Mange segjer til mi sjæl: «Det finst ikkje frelsa for honom hjå Gud.» Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Men du, Herre, er min skjold, mi æra og den som lyfter mitt hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Eg ropar høgt til Herren, og han svarar meg frå sitt heilage fjell. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Eg lagde meg og sovna; eg vakna upp, for Herren held meg uppe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Eg ottast ikkje for ti tusund av folk, som hev lægra seg imot meg rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Statt upp, Herre, frels meg, min Gud! For du hev slege alle mine fiendar på kinni, du hev knasa tennerne på dei ugudlege. Herren høyrer frelsa til. Lat di velsigning vera yver ditt folk! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Til songmeisteren, med strengleik; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Når eg ropar, so svara meg, du Gud som er rettferd! I trengsla hev du gjeve meg rom; ver meg nådig og høyr mi bøn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'De velduge menner Kor lenge skal mi æra vera til skam? Kor lenge vil de elska fåfengd, fara etter lygn? Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Vit då, at Herren fer underleg med den som er etter hans ynde! Herren høyrer, når eg ropar til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Harmast, men synda ikkje! Tenk etter i dykkar hjarta på dykkar lægje, og ver stille! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Ber fram rettferds offer, og set dykkar lit til Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Mange segjer: «Kven vil syna oss noko godt?» Lyft du yver oss ljoset frå di åsyn, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Du hev gjeve meg større gleda i mitt hjarta enn dei hev når deira korn og vin fell rikeleg. I fred vil eg både leggja meg og sovna; for du, Herre, let meg einsaman bu i trygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Til songmeisteren, til Nehilot; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Vend øyra til mine ord, Herre, gjev gaum etter min sukk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Lyd til mitt rop um hjelp, min konge og min Gud! For til deg bed eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Herre, um morgonen vil du høyre mi røyst; um morgonen legg eg mi sak fram for deg og ventar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'For du er ikkje ein Gud som hev hugnad i ugudleg åtferd; den vonde fær ikkje bu hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Dei ovmodige kann ikkje standa seg for dine augo; du hatar alle som gjer urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Du let deim som talar lygn ganga under; den blodgiruge og falske mann styggjest Herren ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Men eg vil ved di store miskunn ganga inn i ditt hus, vil med otte for deg falla ned framfyre ditt heilage tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Herre, leid meg ved di rettferd, for deira skuld som lurar på meg, jamna din veg for meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'For det finst ikkje sanning i deira munn; det indre i deim er ein avgrunn; strupen deira er ei opi grav; tunga si gjer dei hål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Gud, døm dei skuldige! Lat deim falla for sine eigne meinråder, støyt deim ned for deira mange misgjerningar! for dei hev gjort upprør mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Men lat alle deim gleda seg, som set si lid til deg! Lat deim til æveleg tid fagna seg høgt, av di du vil verja deim; og lat deim som elskar ditt namn frygda seg i deg! For du, Herre, velsignar den rettferdige; du vernar honom med nåde som med ein skjold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Til songmeisteren, med strengleik, etter Sjeminit; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Herre, refs meg ikkje i din vreide og tukta meg ikkje i din harm!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Ver meg nådig, Herre, for eg er burtvisna! Læk meg, Herre, for mine bein er skjelvande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Og mi sjæl er storleg skjelvrædd. Og du, Herre, kor lenge?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Vend deg um att, Herre, fri ut mi sjæl, frels meg for di miskunn skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'For i dauden er det ikkje minne um deg; kven vil prisa deg i helheimen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Eg er trøytt av mine sukkar; eg bløyter mi seng kvar natt, med mine tåror væter eg mitt lægje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Mitt auga er upptært av hugverk; det er gamalt vorte for alle deira skuld som trengjer meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Vik ifrå meg, alle de som gjer urett! For Herren hev høyrt mitt gråtmål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Herren hev høyrt mi audmjuke påkalling, Herren, tek imot mi bøn. Alle mine fiendar skal verta skjemde og storleg forfærde; dei skal venda attende, verta skjemde i ein augneblink.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Ein siggajon av David, som han song for Herren på grunn av benjaminiten Kus’ ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Herre, min Gud! Eg flyr til deg; frels meg frå alle mine forfylgjarar og berga meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'so han ikkje som ei løva skal riva ut mi sjæl, riva sund, og ingen som bergar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Herre, min Gud! Dersom eg hev gjort dette, dersom det er urett i mine hender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'dersom eg hev gjort vondt imot den som heldt fred med meg, og plundra den som trengde meg utan orsak:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'so lat fienden forfylgja mi sjæl og nå henne og trøda ned mitt liv til jordi og leggja mi æra i moldi! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Statt upp, Herre, i din vreide! reis deg upp imot ofsen hjå deim som trengjer meg, og vakna upp til hjelp for meg, du som hev påbode dom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Og lat ei samling av folkeslag standa rundt ikring deg, og far upp att yver deim til det høge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Herren held dom yver folki. Døm meg, Herre, etter mi rettferd og etter den uskyld som er hjå meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Lat då vondskapen hjå dei ugudlege få ende, og styrk den rettferdige! For du er den som prøver hjarto og nyro, ein rettferdig Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Min skjold er hjå Gud, han frelser deim som er trugne i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Gud er ein rettferdig domar, og ein Gud som harmast kvar dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'So framt ein ikkje vender um, so kvesser han sitt sverd; sin boge hev han spent og gjort ferdig');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'og stelt til banevåpn til rettes imot honom; sine piler gjer han brennande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Sjå, han skal til å føda misgjerning; han gjeng med ulukka og føder lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Ei grav hev han grave og hola ut; men han fell i den greft som han gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Den ulukka han gjer, kjem att yver hans hovud, og yver hans kvervel fell hans valdsverk ned. Eg vil prisa Herren etter hans rettferd og lovsyngja namnet åt Herren den Høgste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Til songmeisteren, etter Gittit; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Herre, vår Herre, kor herlegt ditt namn er yver all jordi! du som hev sett din prydnad på himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Av munnen på småborn og sogborn hev du grunnfest ei magt for dine motstandarar skuld, so du kann tagga fienden og den hemngiruge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Når eg ser din himmel, det verk av dine fingrar, månen og stjernorne, som du hev sett i stand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'kva er då eit menneskje, at du kjem det i hug, og ein menneskjeson, at du ser til honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Du gjorde honom lite lægre enn Gud; med herlegdom og æra krynte du honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Du sette honom til herre yver dei verk dine hender gjorde, allting lagde du under hans føter:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Småfe og storfe, alle saman, og jamvel dei ville dyr i marki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'fuglen under himmelen og fisken i havet, alt det som fer på havsens stigar. Herre, vår Herre, kor herlegt ditt namn er yver all jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Til songmeisteren, etter Mut-labben; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Eg vil lova Herren av alt mitt hjarta, eg vil fortelja um alle dine under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Eg vil gleda og fagna meg i deg, eg vil lovsyngja ditt namn, du Høgste!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'av di mine fiendar vik attende, dei snåvar og gjeng til grunnar for ditt andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'For du hev ført fram min rett og mi sak, du hev sett deg på domstolen som rettferdig domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Du hev aga heidningarne, øydt ut dei ugudlege, stroke ut deira namn æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Fienden er all lagd i øyde til æveleg tid, byarne hev du støytt ned til grunns, deira minne, det hev døytt ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Men Herren sit som konge til æveleg tid, han hev sett upp sin stol til doms,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'og han dømer jordriket med rettferd, segjer dom yver folkeslag med rettvisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Og Herren er ei borg for den nedtyngde, ei borg i dei tider han er i trengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Og dei som kjenner ditt namn, set si lit til deg; for du forlet ikkje deim som søkjer deg, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Syng lovsong til Herren som bur på Sion! forkynn millom folki hans store gjerningar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'For han som hemner blod, kjem deim i hug, han gløymer ikkje ropet frå dei arme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Ver meg nådig, Herre! Sjå kva eg må lida av deim som meg hatar, du som lyfter meg upp frå daudens portar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'so eg kann forkynna all din pris, i portarne åt Sions dotter fagna meg i di frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Heidningarne er sokne i den grav som dei grov; deira fot er fanga i det garnet dei løynde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Herren hev gjort seg kjend, han hev halde dom; han fangar den ugudlege i det verk hans eigne hender gjorde. Higgajon. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Dei ugudlege skal fara burt til helheimen, alle heidningar som gløymer Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'For den fatige vert ikkje gløymd for alltid, dei arme folks von ikkje spillt i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Statt upp, Herre, lat ikkje menneskje få magt, lat heidningarne verta dømde for di åsyn! Set rædsla i deim, Herre! Lat heidningarne kjenna at dei er menneskje! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Herre, kvi stend du so langt undan, held deg løynd dei tider me er i trengd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Ved ovmodet hjå dei ugudlege illhugast den arme; lat deim vert fanga i dei meinråder dei hev tenkt upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'For den ugudlege rosar det hans sjæl lyster, og den vinnekjære byd farvel og spottar Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Den ugudlege set nosi høgt og segjer: «Han heimsøkjer ikkje. Det er ingen Gud til!» det er alle hans tankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Hans vegar lukkast alle tider; langt burte frå honom i det høge er dine domar; alle sine motstandarar - deim blæs han åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Han segjer i sitt hjarta: «Eg skal ikkje verta rikka, frå ættled til ættled kjem eg ikkje i ulukka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Hans munn er full av forbanning og av svik og vald; under hans tunga er tjon og ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Han ligg på lur ved gardarne, på løynlege stader myrder han den uskuldige, hans augo spæjar etter den verjelause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Han lurer i løyne som løva i si kjørr, han lurer etter å gripa den arme; han grip den arme, med di han dreg honom i sitt garn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Han luter seg, duvar seg ned, og dei verjelause fell for hans sterke klør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Han segjer i sitt hjarta: «Gud hev gløymt det, han hev løynt sitt andlit, han ser det aldri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Statt upp, Herre! Gud, lyft upp di hand, gløym ikkje dei arme!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Kvi skal den ugudlege vanvyrda Gud og segja i sitt hjarta: «Du heimsøkjer ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du hev set det; for du skodar naud og hjartesorg til å leggja deim i di hand; til deg yvergjev den verjelause si sak, du er ein hjelpar for dei farlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Slå armen sund på den ugudlege, og den vonde - heimsøk hans gudløysa, so du ikkje finn honom meir!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Herren er konge æveleg og alltid heidningarne er øydde ut or hans land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Herre, du hev høyrt ynskjet frå dei arme, du styrkjer deira hjarta, du vender øyra ditt til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'so du gjev den farlause og nedtyngde sin rett. Ikkje lenger skal menneskjet som er av jordi halda fram med å skræma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Til songmeisteren; av David. Til Herren flyr eg inn; kor kann de då segja til mi sjæl: «Fly til dykkar fjell som ein fugl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'For sjå, dei ugudlege spenner bogen, dei hev lagt si pil på strengen til å skjota i myrkret på dei trugne i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Når grunnvollarne vert nedrivne, kva kann då ein rettferdig gjera?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Herren er i sitt heilage tempel, Herrens kongsstol er i himmelen, hans augo skodar, ein blink av hans augo prøver menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Herren prøver den rettferdige; men den ugudlege og den som elskar vald, honom hatar hans sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Han skal lata snaror regna ned på dei ugudlege, eld og svåvel og glodheit vind vert deim tilmælt i deira staup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'For Herren er rettferdig, han elskar rettferd, den trugne skal skoda hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Til songmeisteren, etter Sjeminit; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Frels, Herre! For det er ute med den gudlege, dei trufaste er komne burt frå menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Lygn talar dei kvar med sin næste, med smeikjande lippa, med tvihuga hjarta talar dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Herren rydje ut alle smeikjande lippor, den tunga som talar store ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'deim som segjer: «Ved vår tunga skal me sigra; våre lippor er med oss, kven er herre yver oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, '«For valdsverket mot dei arme, for sukken for dei fatige vil eg no reisa meg,» segjer Herren; «eg vil hjelpa den til frelsa, som stundar deretter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Herrens ord er reine ord, eit sylv som er reinsa i verkstaden på jordi, sju gonger skirt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Du, Herre, vil vakta deim, du vil verja dei mot denne ætti for alltid. Rundt um vil dei ugudlege sviva ikring, når nidingskap vert sett høgt hjå menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Kor lenge, Herre, vil du stendigt gløyma meg? Kor lenge vil du løyna ditt andlit for meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Kor lenge skal eg hava sorger i mi sjæl, hugverk i mitt hjarta heile dagen? Kor lenge skal min fiende vera upphøgd yver meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Sjå hit, svara meg, Herre min Gud! Lys upp mine augo, so eg ikkje skal sovna inn i dauden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'so min fiende ikkje skal segja: «Eg hev vunne yver honom,» so mine motstandarar ikkje skal fagna seg yver at eg fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Men eg set mi lit til di miskunn, mitt hjarta skal fagna seg i di frelsa; eg vil lovsyngja Herren, for han hev gjort vel imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Til songmeisteren; av David. Dåren segjer i sitt hjarta: «Det er ingen Gud til.» Vond og styggjeleg er deira gjerning; det er ingen som gjer godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Herren skodar ned frå himmelen på menneskjeborni og vil sjå um der er nokon vitug, nokon som søkjer Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Dei er alle avvikne, dei er utskjemde alle saman; det er ingen som gjer godt, det finst ikkje ein einaste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Veit dei då ikkje, alle dei som gjer urett? Dei et upp mitt folk, liksom dei et brød; på Herren kallar dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Der vert dei storleg rædde; for Gud er hjå den rettferdige ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Den arme manns råd må de gjerne gjera til skammar; for Herren er hans tilhygge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Å, gjev frelsa frå Sion må koma yver Israel! Når Herren vender sitt folks vanlukka, då skal Jakob fagna seg, Israel gleda seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Ein salme av David. Herre, kven skal vera gjest i ditt tjeld? Kven skal bu på ditt heilage fjell?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Den som ferdast ulastande og gjer rettferd og talar sanning i sitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Han baktalar ikkje med si tunga, han gjer ikkje vondt imot sin næste og fører ikkje skam yver den som stend honom nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Svivyrdeleg er i hans augo den gudlause, men han ærar deim som ottast Herren. Sver han til sin eigen skade, so bryt han då aldri sin eid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Han låner ikkje sine pengar ut for renta og tek ikkje mutor imot den saklause. Den som gjer dette, skal i all æva ikkje verta rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ein miktam av David. Vakta meg, Gud! for eg flyr til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Eg segjer til Herren: «Du er min Herre; eg hev inkje godt utan deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Og dei heilage som er i landet, dei er dei herlege som eg hev all min hugnad i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Mange sorger skal dei hava som byter åt seg ein annan; eg vil ikkje renna ut deira drykkoffer av blod og ikkje taka deira namn på mine lippor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Herren er min tilmælte deil og mitt staup; du held min lut i hævd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Ein lut er meg tilfallen som er av dei huglege, ja, ein arv som eg finn fager.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Eg vil lova Herren som gav meg råd; endå um næterne minner mine nyro meg um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Eg set alltid Herren framfyre meg; for han er ved mi høgre hand, eg skal ikkje verta rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Difor gled mitt hjarta seg, og mi æra fagnar seg, ja, ogso mitt kjøt skal kvila i trygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'For du vil ikkje yverlata mi sjæl til helheimen, du vil ikkje lata din heilage sjå undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du vil kunngjera meg livsens veg; ei nøgd med gleda er for di åsyn, fagnad ved di høgre hand til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Ei bøn av David. Herre, høyr på rettvis sak, lyd etter mitt rop, vend øyra til mi bøn frå saklause lippor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Lat min rett ganga ut frå ditt andlit, dine augo skoda kva rett er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Du prøver mitt hjarta, gjestar det um natti, du ransakar meg, du finn ingen ting; min tanke vik ikkje av frå min munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Mot det som menneskje hev gjort meg, hev eg etter ordet frå dine lippor teke meg i vare for valdsmanns stigar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Mine stig heldt seg stødt til dine farvegar, mine føtar snåva ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Eg ropar til deg, for du svarar meg, Gud! Bøyg ditt øyra til meg, høyr mitt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Vis di underfulle miskunn, du som frelsar deim som flyr til deg, frå deim som stend imot di høgre hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Vakta meg som din augnestein! gøym meg i skuggen av dine vengjer');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'for dei ugudlege som øydelegg meg, mine fiendar til dauden, som kringset meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Dei let sitt feite hjarta att, med sin munn talar dei i ovmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Kvar me gjeng, kringgjeng dei oss no; sine augo set dei på å støyta meg ned til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Han er lik ei løva som stundar etter å riva sund, og ei ungløva som ligg i løyne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Statt upp, Herre, stig fram imot honom, støyt honom ned, frels mi sjæl frå den ugudlege med ditt sverd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'frå menner med di hand, Herre, frå menner av denne verdi, som hev sin lut i dette liv, og som du fyller buken på med dine skattar, dei som er rike på søner og let sine avleivor etter seg til sine born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Eg skal i rettferd skoda ditt andlit, eg skal, når eg vaknar, mettast av di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Til songmeisteren; av Herrens tenar David, som førde fram for Herren ordi i denne songen den dag då Herren hadde frelst honom frå alle hans fiendar og frå Saul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Og han sagde: Herre, eg hev deg hjarteleg kjær, min styrke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Herren er min berggrunn og mi festning og min frelsar; min Gud er mitt berg som eg flyr til, min skjold og mitt frelsehorn, mi borg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Eg kallar på Herren som er høglova, og vert frelst frå mine fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Daudsens reip var spente um meg, og bekkjer av vondskap skræmde meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Helheims reip var snørde um meg, daudsens snaror fanga meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'I mi trengsla kalla eg på Herren, og eg ropa til min Gud; han høyrde frå sitt tempel mi røyst, og mitt rop kom for hans andlit, til hans øyro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Og jordi skok og riste seg, og grunnvollarne i fjelli skalv, og dei skok seg, for han var vreid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Røyk steig upp or hans nase, og eld frå hans munn åt um seg; gloande kol loga frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Og han lægde himmelen og steig ned, og det var kolmyrker under hans føter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Og han for fram på kerub, og flaug og sveiv på vengjerne åt vinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Og han gjorde myrker til sitt åklæde rundt ikring seg, til sitt tjeld myrke vatn, tjukke skyer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Frå glansen for hans andlit for hans skyer fram, hagl og gloande kol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Og Herren tora i himmelen, den Høgste let si røyst ljoda: hagl og gloande kol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Og han sende ut sine piler og spreidde deim ikring, og eldingar i mengd og fortulla deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Då kom djupålarne i vatnom til synes, og grunnvollarne i jordi vart berrsynte ved ditt trugsmål, Herre, ved andepusten frå din nase.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Han rette ut handi frå det høge, han greip meg; han drog meg upp or store vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Han frelste meg frå min megtige fiende og frå mine hatarar, for dei var meg for sterke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Dei for imot meg på min motgangs dag; men Herren vart min studnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Han førde meg ut i vidt rom; han frelste meg, for han hadde hugnad i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Herren gjorde med meg etter mi rettferd, han lønte meg etter reinleiken i mine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'For eg tok vare på Herrens vegar og fall ikkje i vondskap frå min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'For alle hans lover hadde eg for auga, hans bodord støytte eg ikkje frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Og eg var ulastande for honom og tok meg i vare for mi synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Og Herren lønte meg etter mi rettferd, etter reinleiken i mine hender for hans augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Mot den godlyndte syner du deg godlyndt, mot ulastande mann syner du deg ulastande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'mot den reine syner du deg rein, mot den rangsnudde gjer du deg rang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'For du frelser arme folk og tvingar høge augo ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'For du let mi lampa lysa klårt, Herren, min Gud, gjer mitt myrker bjart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'For ved deg renner eg mot herflokkar, og ved min Gud spring eg yver murar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Gud, ulastande er hans veg; Herrens ord er skirt, han er ein skjold for alle deim som flyr til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'For kven er Gud forutan Herren, og kven er eit berg utan vår Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Den Gud som gyrder meg med kraft og gjer min veg ulastande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'som gjev meg føter liksom hindarne og set meg upp på mine høgder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'som lærer upp mine hender til strid, so mine armar spenner koparbogen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Og du gav meg di frelsa til skjold, di høgre hand studde meg, og di småminking gjorde meg stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Du gjorde vidt rom åt mine stig under meg, og mine oklo vagga ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Eg forfylgde mine fiendar og nådde deim og vende ikkje um fyrr eg hev gjort av med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Eg slo deim i knas, so dei vann ikkje reisa seg; dei fell under føter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Og du gyrde meg med kraft til striden; du bøygde under meg deim som stod upp imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Du let mine fiendar snu ryggen til meg, og mine hatarar, deim rudde eg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Dei ropa - men der var ingen frelsar - til Herren, men han svarar deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Og eg smuldrar deim som dust for vinden; som søyla på gator slo eg deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Du frelste meg frå folke-ufred; du sette meg til hovud for heidningar; folk som eg ikkje kjende, tente meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Ved gjetordet um meg lydde dei meg; framande folk smeikte for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Framande folk visna av og gjekk skjelvande ut or sine borger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Herren liver, og lova er han, mitt berg, og upphøgd er den Gud som meg frelser,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'den Gud som gjev meg hemn og legg folkeslag under meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'som frelser meg frå mine fiendar; ja - du lyfter meg høgt yver deim som stend imot meg, frå valdsmannen bergar du meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Difor vil eg prisa deg millom heidningarne, Herre, og lovsyngja ditt namn. Han gjer frelsa stor for sin konge, og gjer miskunn mot den som er salva av honom, mot David og hans ætt til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Himlarne fortel Guds æra, og kvelven forkynner kva hans hender hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ein dag let sin tale strøyma ut til den andre, og ei natt forkynner den andre sin kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Der er ikkje tale, der er ikkje ord; deira røyst vert ikkje høyrd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Ut yver all jordi gjeng deira mål, og til heimsens ende deira ord. Åt soli sette han eit tjeld på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Og ho er lik ein brudgdom som gjeng ut or sitt løynrom, gled seg som ei kjempa til å renna sitt skeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Frå enden av himmelen er hennar utgang, og hennar umlaup til andre enden av honom, og ingen ting er duld for hennar hite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Herrens lov er fullkomi, ho kveikjer sjæli; Herrens vitnemål er trufast, det gjer den einfalde vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Herrens fyresegner er rette, dei gled hjarta; Herrens bodord er reint, det lyser upp augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Herrens age er rein, han stend æveleg ved lag; Herrens domar er sanning, dei er rettferdige alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Dei er kostelegare enn gull, ja, fint gull i mengd, og søtare enn honning, ja, honning som dryp frå voks-kakorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Din tenar vert ogso åmint ved deim; når ein held deim, er det stor løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Kven merkar kor tidt han fer vilt? Forlat meg mine løynlege brester!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Haldt og din tenar frå skamløysor, lat deim ikkje få magt yver meg! So vert eg ulastande og utan skuld for stor misgjerning. Lat talen i min munn og tanken i mitt hjarta vera til hugnad for di åsyn, Herre, du mitt berg og min atterløysar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Herren bønhøyre deg på trengselsdagen, namnet åt Jakobs Gud berge deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Gjev han må senda deg hjelp frå heilagdomen og stydja deg frå Sion!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Gjev han må minnast alle dine grjonoffer og finna ditt brennoffer godt! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Han gjeve deg etter ditt hjarta og fullføre alle dine råder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Me vil fagna oss ved di frelsa og i vår Guds namn lyfta sigermerket. Herren uppfylle alle dine bøner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'No veit eg at Herren frelser den han salva; han svarar honom frå sin heilage himmel med frelsande storverk av si høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Desse prisar vogner, og hine prisar hestar, men me prisar namnet åt Herren, vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Dei sig i kne og fell, men me stend og held oss uppe. Herre, frels kongen! Han svare oss den dag me ropar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Herre! Kongen gled seg yver di magt, og kor høgt han fagnar seg yver di frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Det hans hjarta ynskte, hev du gjeve honom og ikkje neitta honom det hans lippor bad um. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'For du kom honom til møtes med velsigning av gode ting; du sette ei kruna av gull på hans hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Han bad deg um liv, du gav honom det, eit langt liv æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Stor er hans æra ved di frelsa; høgd og heider legg du på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'For du set honom til velsigning for alle tider, du hugnar honom med gleda for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'For kongen set si lit til Herren, og ved miskunn frå den Høgste skal han ikkje verta rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Di hand skal finna alle dine fiendar, di høgre hand skal finna deim som hatar deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Du skal gjera deim som ein gloande omn, når du viser di åsyn; Herren skal rydja deim ut i sin vreide, og eld fortæra deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Deira frukt skal du rydja ut av jordi og deira avkoma millom menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'For dei stila på vondt imot deg, dei lagde upp meinråder; dei kann ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'For du skal få deim til å snu ryggen til, med dine bogestrengjer sigtar du på deira andlit. Reis deg, Herre, i di magt! So vil me lovsyngja og prisa ditt velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Til songmeisteren etter «Morgonraudens hind»; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Min Gud, min Gud, kvi hev du forlate meg? Dei ord eg skrik ut, er langt burte frå mi frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Min Gud! eg ropar um dagen, og du svarar meg ikkje, og um natti, og eg fær ikkje tegja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Og du er då heilag, du som bur yver Israels lovsongar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'På deg leit våre feder; dei leit på deg, og du frelste deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Til deg ropa dei og slapp undan; på deg leit dei og vart ikkje til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Men eg er ein makk og ikkje ein mann, ei spott for menneskje og vanvyrd av folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Alle som ser meg, spottar meg, rengjer munnen og rister på hovudet og segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '«Legg det på Herren! han frelse honom, han berge honom, sidan han hev hugnad i honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Ja, du er den som drog meg fram frå morslivet, som let meg kvila trygt ved morsbrjostet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'På deg er eg kasta frå morslivet, frå morsfanget er du min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Ver ikkje langt burte frå meg! for trengsla er nær, for det finst ingen hjelpar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Sterke uksar ringar meg inne, Basans stutar kringset meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Dei spilar upp sitt gap imot meg, som ei flengjande og burande løva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Eg er runnen ut som vatn, og alle mine bein skilst frå kvarandre; mitt hjarta hev vorte voks, smolte inst i mitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Mi kraft er uppturka som eit krusbrot, mi tunga kleimer seg til min gom, og du legg meg ned i daudens dust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'For hundar hev sanka seg um meg, ein hop av illmenne kringsett meg; dei hev gjenombora mine hender og mine føter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Eg kann telja alle mine bein; dei skodar til, dei ser på meg med lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Dei skifte mine klæde millom seg og kasta lut um min kjole.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Men du, Herre, ver ikkje langt burte, du min styrke, skunda deg å hjelpa meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Fria mi sjæl frå sverdet, mi einaste frå hundevald!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Frels meg frå løvegap, og frå villukse-horn - du bønhøyrer meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Eg vil forkynna ditt namn for mine brør, midt i ålmugen vil eg lova deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'De som ottast Herren, lova honom, all Jakobs ætt, æra honom, og hav age for honom, all Israels ætt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'For han hev ikkje vanvyrdt og ikkje stygst ved ein armings armodsdom, og ikkje løynt si åsyn for honom; men då han ropa til honom, høyrde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Frå deg kjem min lovsong i ein stor ålmuge; eg vil avgjera mine lovnader for deira augo som ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Dei audmjuke skal eta og verta mette; dei som søkjer Herren, skal lova honom. Dykkar hjarta live til æveleg tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Alle endarne av jordi skal koma det i hug og venda um til Herren, og alle heidninge-ætter skal tilbeda for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'For riket høyrer Herren til, og han råder yver alle hedningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Alle rikmenner på jordi skal eta og tilbeda; for hans åsyn skal dei bøygja kne, alle dei som stig ned i dusti, og den som ikkje kann halda si sjæl i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Etterkomarar skal tena honom; det skal verta fortalt um Herren til den komande ætt. Dei skal koma og forkynna hans rettferd for det folk som vert født, at han hev gjort det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Ein salme av David. Herren er min hyrding, det vantar meg ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Han fører meg til læger på grøne engjar; han leider meg til vatn der eg finn kvila.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Han kveikjer mi sjæl, han fører meg på rettferds stigar for sitt namn skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Endå um eg gjeng i daudeskuggens dal, so ottast eg ikkje for noko vondt; for du er med meg, din kjepp og din stav dei trøystar meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du dukar bord åt meg framfor augo på mine fiendar, du salvar mitt hovud med olje; det fløder yver mitt staup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Berre lukka og miskunn skal fylgja meg alle mine livdagar, og eg skal bu i Herrens hus i ævelengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Av David, ein salme. Jordi høyrer Herren til - og alt det som fyller henne, jordriket og dei som bur i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'For han hev grunnlagt henne på havi og grunnfest henne på strøymande vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kven skal stiga upp på Herrens fjell, og kven skal standa på hans heilage stad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Den som hev skuldlause hender og reint hjarta, som ikkje hev vendt sin hug til lygn og ikkje svore med svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Han skal bera velsigning med frå Herren og rettferd frå Gud, sin frelsar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Dette er deira ætt som spør etter honom, dei som søkjer di åsyn, Jakobs born. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'De portar, lyft upp dykkar hovud! ja lyft dykk upp, de ævelege dører, so kongen den herlege kann koma inn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kven er kongen den herlege? Herren sterk og veldug, Herren veldug i strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'De portar, lyft upp dykkar hovud! ja lyft dykk upp, de ævelege dører, so kongen den herlege kann koma inn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kven er då kongen den herlege? Herren, allhers drott; han er kongen den herlege. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Av David. Herre, til deg lyfter eg mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Min Gud, til deg hev eg sett mi lit; lat meg ikkje verta til skammar; lat ikkje mine fiendar gilda seg yver meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Ja, ingen av deim som ventar på deg, skal verta til skammar; men dei skal verta til skammar, som utan årsak bryt si tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Herre, lat meg kjenna dine vegar, lær meg dine stigar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Leid meg fram i di sanning og lær meg! for du er Gud, min frelsar, på deg ventar eg all dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Herre, kom i hug di miskunn og din nåde! for dei er frå æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Kom ikkje i hug min ungdoms synder og mine misgjerningar; kom meg i hug etter di miskunn for din godhug skuld, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Herren er god og rettvis; difor lærer han syndarar vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Han leider dei audmjuke i det som rett er, og lærer dei audmjuke sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Alle Herrens stigar er nåde og sanning mot deim som held hans pakt og hans vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'For ditt namn skuld, Herre, forlat meg mi skuld, for ho er stor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kven er den mann som ottast Herren? Honom lærer han den veg han skal velja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Hans sjæl skal stødt bu i sæla, og hans avkjøme skal erva landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Herren hev samlag med deim som ottast honom, og si pakt vil han kunngjera deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mine augo er stendigt vende til Herren, for han dreg mine føter ut or garnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Vend deg til meg og ver meg nådig! for eg er einsleg og arm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Min hjarteverk hev dei gjort stor; før meg ut or mine trengslor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Sjå min armodsdom og mi møda, og forlat meg alle mine synder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Sjå mine fiendar, at dei er mange! og dei hatar meg med rettarlaust hat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Vara mi sjæl og frels meg! Lat meg ikkje verta til skammar! for eg flyr til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Lat uskyld og trurøkna verja meg, for eg ventar på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Å Gud, løys Israel ut or alle sine trengslor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Av David. Søm meg til min rett, Herre! for eg hev fare fram i mi uskyld, og til Herren hev eg sett mi lit uruggeleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Prøv meg, Herre, og freista meg, ransaka mine nyro og mitt hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'For din nåde er for mine augo, og eg ferdast i di sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Eg sit ikkje saman med falske menner og gjeng ikkje inn hjå fule folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Eg hatar samkoma av illmenne, og hjå dei ugudlege sit eg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Eg tvær mine hender i uskyld og vil gjerne ferdast um ditt altar, Herre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'til å kveda lydt med lovsongs røyst og fortelja um alle dine under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Herre, eg elskar di husvist og den stad der din herlegdom bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Rykk ikkje mi sjæl burt med syndarar eller mitt liv med blodgiruge menner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'som hev skamgjerd i sine hender og si høgre hand full av mutor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Men eg fer fram i mi uskyld; løys meg ut og ver meg nådig!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Min fot stend på slettlende. I samlingarne skal eg lova Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Av David. Herren er mitt ljos og mi frelsa, kven skulde eg ottast for? Herren er verni for mitt liv, kven skulde eg ræddast for?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Når illmenne søkjer på meg og vil eta mitt kjøt, mine motstandarar og mine fiendar, so snåvar og fell dei sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Um ein her lægrar seg imot meg, so ottast ikkje mitt hjarta; um ufred reiser seg imot meg, er eg endå hugheil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Eitt hev eg bede Herren um, det stundar eg etter: at eg må bu i Herrens hus alle mine livdagar, so eg kann skoda Herrens ynde og grunda i hans tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'For han gøymer meg i sitt hus på den vonde dag, han løyner meg i løynrom i sitt tjeld; han fører meg upp på eit berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Og no skal mitt hovud vera upphøgd seg yver mine fiendar rundt ikring meg, og eg vil bera fram offer med fagnadljod i hans tjeld, eg vil syngja og leika for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Høyr, Herre, eg ropar høgt; og ver meg nådig og svara meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mitt hjarta ber fram for deg ditt ord: «Søk mi åsyn!» Herre, eg søkjer di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Løyn ikkje di åsyn for meg, vis ikkje din tenar frå deg i vreide! Du hev vore mi hjelp. Støyt meg ikkje burt og forlat meg ikkje, du Gud som er mi frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'For far min og mor mi hev forlate meg, men Herren tek meg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Lær meg, Herre, din veg, og leid meg på den jamne stig for deira skuld som lurer på meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Gjev meg ikkje til deira mordhug som trengjer meg! for falske vitne stend upp imot meg, og folk som frøser av vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Å, dersom eg ikkje trudde at eg skulde få sjå Herrens godhug i livsens land -!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Venta på Herren, ver hugheil, og lat ditt hjarta verta sterkt. Ja, venta på Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Av David. @Til deg, Herre, ropar eg: mitt berg, ver ikkje tagall imot meg, so eg ikkje, når du tegjer til meg, skal verta lik deim som fer ned i gravi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Høyr røysti av mine audmjuke bøner, når eg ropar til deg, når eg lyfter mine hender til din heilage høgkor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Riv meg ikkje burt med dei ugudlege og med ugjerningsmenner, dei som talar um fred med sin næste, men med vondt i sitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Gjev deim etter deira gjerning og etter vondskapen i deira verk! Gjev deim etter det deira hender hev gjort, løn deim som dei hev fortent!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'For dei legg ikkje merke til Herrens gjerningar eller til verket av hans hender; han vil riva deim ned og ikkje byggja deim upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Lova vere Herren, for han hev høyrt røysti av mine audmjuke bøner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Herren er min styrke og min skjold; på honom leit mitt hjarta, og eg fekk hjelp. Difor fagnar mitt hjarta seg høgt, og eg vil prisa honom med min song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Herren er styrke for sitt folk, og ei vern til frelsa for den han hev salva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Frels ditt folk og velsigna din arv, og fød deim og ber deim til æveleg tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Ein salme av David. Gjev Herren, de Guds søner, gjev Herren æra og magt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Gjev Herren hans namns æra, tilbed Herren i heilag prydnad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Herrens røyst ljodar yver vatni, Gud den herlege torar, Herren yver dei store vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Herrens røyst ljodar med velde, Herrens røyst med herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Herrens røyst bryt sund cedertre, ja, Herren bryt sund cedertrei på Libanon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Og han fær deim til å hoppa som ein kalv, Libanon og Sirjon som ein ung villukse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Herrens røyst sprengjer eldslogar fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Herrens røyst fær øydemarki til å skjelva, Herren fær øydemarki ved Kades til å skjelva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Herrens røyst fær hindarne til å kalva og snøyder skogarne, og i hans tempel segjer alt: «\'ra!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Herren sat yver storflodi, og Herren sit konge til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Herren gjeve sitt folk styrke, Herren velsigne sitt folk med fred!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Ein salme, ein song då huset vart vigt av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Høgt vil eg lova deg, Herre, for du hev drege meg upp og ikkje late mine fiendar gleda seg yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Herre, min Gud, eg ropa til deg, og du lækte meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Herre, du hev ført meg upp frå helheimen, du hev vakt meg upp til liv frå deim som fer ned i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Syng lov til Herren, de hans trugne, og prisa hans heilage namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'For ein augneblink varer hans vreide, ei heil levetid hans nåde; um kvelden kjem gråt til gjest, men til morgons vert det gledesong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Men eg sagde i min tryggleik: «Eg skal ikkje verta rikka i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Herre, ved din nåde hadde du grunnfest mitt fjell; du løynde di åsyn, då vart eg forfærd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Til deg, Herre, ropa eg, og til Herren bad eg inderleg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, '«Kva vinning er det i mitt blod, i at eg fer ned i gravi? Kann mold prisa deg, forkynna din truskap?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Herre, høyr og ver meg nådig! Herre, ver min hjelpar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Du vende mi sorg um til dans for meg, du klædde av meg min syrgjebunad og gyrde meg med gleda, so mi æra kann lovsyngja deg og ikkje tagna. Herre, min Gud, eg vil æveleg prisa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Herre, eg flyr til deg; lat meg aldri i æva verta til skammar! Frels meg ved di rettferd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Bøyg ditt øyra til meg, berga meg snart, ver meg eit festningsberg, ei fast borg til å frelsa meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'For du er mitt berg og mi borg, og for ditt namn skuld vil du føra og leida meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Du vil føra meg ut or garnet som dei løynleg hev sett for meg; for du er mi vern.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'I di hand yvergjev eg mi ånd; du løyser meg ut, Herre, du trufaste Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Eg hatar deim som dyrkar tome avgudar, men eg, eg set mi lit til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Eg vil fagna meg og gleda meg yver di miskunn, at du hev set min armodsdom, kjært deg um mi sjælenaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Og du hev ikkje gjeve meg i fiendehand, du hev sett mine føter på romlendt stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Ver meg nådig, Herre, for eg vert trengd! Mitt auga er upptært av hugverk, ja, mi sjæl og min likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'For mitt liv kverv burt med sorg, og mine år med sukk; mi kraft fell av for mi misgjerning skuld, og mine bein er utmødde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'For alle mine motstandarar skuld hev eg vorte til skam, ja, til stor skam for mine grannar, og til skræma for mine kjenningar; dei som ser meg på gata, flyr undan for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Eg er gløymd som ein daud mann, ute or hjarta; eg hev vorte som eit sundbrotnande kjerald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'For eg høyrer baktale av mange, rædsla rundt ikring, med di dei legg råd saman imot meg; dei lurer på å taka mitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Men eg, eg set mi lit til deg Herre; eg segjer: «Du er min Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'I di hand stend mine tider; berga meg or handi på mine fiendar, og frå deim som forfylgjer meg!.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Lat di åsyn lysa yver din tenar, frels meg ved di miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Herre, lat meg ikkje verta til skammar, for eg ropar til deg; lat dei ugudlege verta til skammar og tagna i helheimen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Lat lygn-lippor verta mållause som talar skamdjervt mot den rettferdige, med ovmod og uvyrdnad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Kor stor er din godhug, som du hev gøymt åt deim som ottast deg, som du hev vist mot deim som flyr til deg, for augo på menneskjeborni!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Du løyner deim i løynrom for di åsyn mot samansvorne menner, du gøymer deim i ei bud mot kiv av tungor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Lova vere Herren, for han hev gjort si miskunn underfull imot meg i ein fast by!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Og eg, eg sagde i mi hugsott: «Eg er burtriven frå dine augo!» men endå høyrde du røysti av mine audmjuke bøner, då eg ropa til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Elska Herren, alle hans trugne! Herren vaktar dei trufaste, men gjev rikeleg attergjeld til den som fer med ovmod. Ver hugheile og lat dykkar hjarta vera sterkt, alle de som ventar på Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Av David; ein song til lærdom. Sæl er den som hans misgjerd er forlati og hans synd yverbreidd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Sælt er det menneskje som Herren ikkje tilreknar skuld, og som er utan svik i si ånd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Då eg tagde, morkna mine bein, med di eg stunde heile dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'For dag og natt låg di hand tungt på meg, mi livssaft torna ut som i sumarturken. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Eg kjendest ved mi synd for deg og dulde ikkje mi skuld; eg sagde: «Eg vil sanna mine misgjerningar for Herren.» Og du tok burt mi syndeskuld. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Difor skal kvar som er trugen beda til deg den tid du er finnande; sanneleg, um store vatsfløde kjem, til honom skal dei ikkje nå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du er mi gøymsla, du vaktar meg for trengsla, du let fagnadrop um frelsa ljoda ikring meg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Eg vil læra deg og visa deg den vegen du skal ganga; eg vil gjeva deg råd med mitt auga på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ver ikkje som hest og muldyr som ikkje hev vit: deira prydnad er taum og beisl til å tvinga deim, elles kjem dei ikkje nær til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Den ugudlege hev mange pinor, men den som lit på Herren, honom kransar han med miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Gled dykk i Herren og fegnast, de rettferdige, og syng av fagnad, alle de trurøkne i hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Fagna dykk høgt i Herren, de rettferdige! For de trurøkne sømer seg lovsong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Prisa Herren med strengeleik, lovsyng honom til tistrengja harpa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Syng honom ein ny song, rør strengen fagert med fagnadljod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'For Herrens ord er ærleg meint, og all hans gjerning er trufast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Han elskar rettferd og rett; av Herrens nåde er jordi full.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Himlarne er skapte ved Herrens ord, og all deira her ved hans munns ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Han samlar havsens vatn som ei muga, legg dei djupe vatn i upplagshus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'All jordi må ottast for Herren, for honom ræddast alle som bur i mannheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'For han tala, og so vart det; han baud, og so stod det der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Herren spiller heidningefolks råd, gjer folkeslags tankar til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Herrens råd stend ved lag i all æva, hans hjartans tankar frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Sælt er det folk som hev Herren til sin Gud, det folk som han valde ut til sin arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Frå himmelen skodar Herren ned, han ser alle menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Frå den staden der han bur, ser han ned til alle som bur på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'han som lagar deira hjarto alle saman, han som merkar alle deira gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ein konge vert ikkje frelst ved sin store styrke, ei kjempa ikkje berga ved si store kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Hesten er sviksam hjelp til frelsa, og med sin store styrke bergar han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Sjå, Herrens auga ser til deim som ottast honom, som ventar på hans nåde');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'til å fria deira sjæl frå dauden og halda deim i live i hungersnaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Vår sjæl stundar på Herren; han er vår hjelp og vår skjold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'For i honom gled vårt hjarta seg, for me set vår lit til hans heilage namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Di nåde, Herre, vere yver oss, so som me vonar på deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Av David, då han gjorde seg galen hjå Abimelek, so han jaga honom av, og han gjekk burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Eg vil lova Herren alle tider, hans pris skal stendigt vera i min munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Mi sjæl skal rosa seg av Herren; dei spaklyndte skal høyra det og gleda seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Lova Herren storleg med meg, og lat oss saman upphøgja hans namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Eg søkte Herren, og han svara meg og fria meg frå alle mine rædslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Dei som skoda upp til honom, lyste av gleda, og deira andlit turvte aldri blygjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Her er ein arming som ropa, og Herren høyrde og frelste honom frå alle hans trengslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Herrens englar lægrar seg rundt ikring deim som ottast honom, og han friar deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Smaka og sjå at Herren er god! Sæl er den mann som flyr til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Ottast Herren, de hans heilage, for inkje vantar dei som ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Unge løvor lid naud og svelt, men dei som søkjer Herren, deim vantar det inkje godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kom born, høyr meg! Eg vil læra dykk otte for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Kven er den mann som hev lyst til liv, som ynskjer seg dagar til å sjå lukka?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Vakta di tunga frå det som vondt er, og lippor for svikfull tale!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Vik burt frå det vonde og gjer det gode, søk fred og far etter honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Herrens augo er vende til dei rettferdige, og hans øyro til deira rop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Herrens åsyn er imot deim som gjer vondt, til å rydja ut deira minne frå jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Hine ropar, og Herren høyrer og friar deim ut or alle deira trengslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Herren er nær hjå deim som hev eit sundbrote hjarta, og frelser deim som hev ei hugsprengd ånd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Mange ulukkor kjem yver den rettferdige, men Herren friar honom ut or deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Herren tek vare på alle hans bein, ikkje eitt av deim vert brote.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Ulukka drep den ugudlege, og dei som hatar den rettferdige, vert saka. Herren løyser ut deira sjæl som tener honom, og av dei som flyr til honom, vert ingen saka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Av David. Herre, før mi sak mot deim som hev sak mot meg! Strid mot deim som strider mot meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Grip skjold og verja og reis deg til hjelp for meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Drag spjotet fram og steng vegen for deim som forfylgjer meg! Seg til mi sjæl: «Eg er di frelsa!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Lat deim blygjast og skjemmast, som stend meg etter livet! Lat deim vika attende med skam, som vil meg noko vondt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Lat deim verta som agner for vind, og Herrens engel støyte deim burt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Lat deira veg verta myrk og hål, og Herrens engel forfylgje deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'For utan orsak hev dei løynt si grav med garn åt meg, utan orsak hev dei grave ei grav for mitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Lat tjon koma yver honom, når han ikkje veit det, og det garn han løynde fanga honom; lat honom falla i det til sitt tjon!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Og mi sjæl skal gleda seg i Herren, fagna seg i hans frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Alle mine bein skal segja: «Herre, kven er som du, du som friar den arme frå ein som er honom for sterk, den arme og fatige frå den som plundrar honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Det stend upp mange vitne; dei spør meg um det som eg ikkje veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Dei gjev meg vondt til løn for godt; mi sjæl er lati åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Men eg, eg gjekk i syrgjeklæde, då dei var sjuke; eg pinte mi sjæl med fasta, og mi bøn vende att til min barm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Eg gjekk ikring, som det skulde vore min ven, min bror; eg gjekk bøygd og svartklædd, som ein som syrgjer på mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Men no, då det hallar med meg, no gled dei seg og flokkar seg saman; det flokkast mot meg fantar og folk eg ikkje kjenner; dei riv sund og kviler ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Liksom skamløysor som driv spott for ein brødbite, so skjer dei tenner imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herre, kor lenge vil du sjå på? Drag mi sjæl undan deira herverk, mitt einaste frå unge løvor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Eg vil prisa deg i ei stor samling, lova deg millom mykje folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Lat deim som utan grunn er mine fiendar ikkje gleda seg yver meg! Lat deim som hatar meg utan orsak ikkje blinka med auga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'For dei talar ikkje fred, men tenkjer upp svikande ord mot dei stille i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Og dei riv sin munn vidt upp imot meg, dei segjer: «Ha, ha! Vårt auga hev set det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Du ser det, Herre, teg ikkje! Herre, ver ikkje langt ifrå meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Vakna upp og vert vaken til å gjeva meg rett, min Gud og Herre, til å føra mi sak!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Døm meg etter di rettferd, Herre min Gud, og lat deim ikkje gleda seg yver meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Lat deim ikkje segja i sitt hjarta: «Ha, det er vår lyst!» Lat deim ikkje segja: «Me hev gløypt honom upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Lat deim skjemmast og blygjast alle saman som gled seg i mi ulukka; lat deim klæda seg i skam og skjemsla, dei som høgmodast yver meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Lat deim fagna seg og gleda seg, som unner meg min rett, og lat deim alltid segja: «Høglova vere Herren, som unner sin tenar at det gjeng honom godt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Og mi tunga skal kveda ut di rettferd, heile dagen din pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Til songmeisteren; av Herrens tenar David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Dei ord som syndi gjev den ugudlege inn, kjenner eg i mitt inste hjarta. Ingen ræddhug for Gud er det for hans augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'For ein høler honom i augo ved å finna hans synd, ved å hata honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Ordi i hans munn er urett og svik; han hev halde upp å fara visleg åt, å gjera godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Han tenkjer upp urett på sitt lægje; han stig ut på ein veg som ikkje er god; han styggjest ikkje frå det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Herre, til himmelen når di miskunn, din truskap upp til dei høge skyer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Di rettferd er som Guds fjellhøgder, dine domar er ei stort havdjup; menneskje og dyr frelser du, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Kor dyrverdig er di miskunn, Gud! Og menneskjeborni flyr inn i skuggen av dine vengjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Dei vert mette til fullnad av det feite i ditt hus, og av din yverflødande fagnad gjev du deim å drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'For hjå deg er livsens kjelda, i ditt ljos ser me ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Lat di miskunn vara lenge for deim som kjenner deg, og di rettferd for dei trurøkne i hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Lat ikkje ovmods fot koma yver meg, og hand av ugudlege ikkje jaga meg burt! Der fell dei som gjer urett; dei vert støytte ned og kann ikkje standa upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Av David. Vreidskast ikkje yver illgjerningsmennerne, harmast ikkje yver deim som gjer urett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'For liksom gras vert dei brått avskorne, og som grøne urter visnar dei burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Lit på Herren og gjer det gode, bu i landet og legg vinn på truskap!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Og hugnast i Herren, so skal han gjeva deg det som ditt hjarta ynskjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Gjev Herren din veg i vald, og lit på honom! Han skal gjera det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'og han skal lata di rettferd ganga fram som ljoset, og din rett som middagsklåren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Ver still for Herren og stunda på honom! Vreidast ikkje yver den som hev lukka på sin veg, den mannen som legg upp meinråd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Haldt deg frå vreide, lat harm fara, vreidast ikkje, det er berre til å gjera ilt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'For illgjerningsmenner skal verta utrudde, men dei som ventar på Herren, dei skal erva landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Og um ei liti stund er den ugudlege ikkje til, og legg du merke til hans stad, so er han der ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Men dei spaklyndte skal erva landet og hugnast ved mykjen fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Den ugudlege tenkjer upp vondt imot den rettferdige og skjer tenner imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Herren lær åt honom; for han ser at hans dag kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Dei ugudlege dreg sverdet og spenner sin boge til å fella den arme og fatige og myrda deim som fer ærleg fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Deira sverd skal ganga inn i deira eige hjarta, og deira bogar verta brotne sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Betre er det vesle den rettferdige hev, enn mykje gods hjå mange ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'For armarne vert brotne på dei ugudlege, men Herren styd dei rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Herren kjenner dei dagar dei ulastande skal liva, og deira arv skal vara til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Dei skal ikkje verta til skammar i den vonde tid, og i hungers dagar skal dei verta mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'For dei ugudlege skal ganga til grunnar, og Herrens fiendar som blomeskrud på engjar; dei kverv som røyk, kverv burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Den ugudlege låner og gjev ikkje att, men den rettferdige gjer miskunn og gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'For dei han velsignar, skal erva landet; men dei han forbannar, skal verta utrudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Herren gjer ein manns steg faste, og han hev hugnad i hans veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Når han fell, vert han ikkje støypt til marki; for Herren styd hans hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Eg hev vore ung og vorte gamall, men aldri hev eg set den rettferdige forlaten eller hans born beda um brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Heile dagen gjer han miskunn og låner ut, og hans born vert velsigna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Vik frå det vonde og gjer det gode, so vert du æveleg buande i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'For Herren elskar rett og forlet ikkje sine trugne; til æveleg tid vert dei haldne uppe; men avkjøme av ugudlege vert utrudt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Dei rettferdige skal erva landet og bu i det til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Rettferdig manns munn andar visdom, og hans tunga taler det som rett er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Hans Guds lov er i hans hjarta, hans stig er ikkje ustøde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Dei ugudlege lurer på den rettferdige og søkjer å drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Herren yvergjev honom ikkje i hans hand og fordømer honom ikkje, når han vert dømd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Venta på Herren og haldt deg på hans veg! so skal han upphøgja deg til å erva landet; du skal sjå på at dei ugudlege vert utrudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Eg såg ein ugudleg ovrikjen mann, og han breidde seg ut som eit heimevakse tre med sitt grøne lauv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Men han gjekk burt, og sjå, han var ikkje meir, og eg leita etter honom, men han vart ikkje funnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Merk deg den ulastande mann, og sjå på den rett-tenkte, at freds mann hev ei framtid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Men dei fråfalne vert alle saman utøydde, framtidi vert avskori for dei ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Og frelsa for dei rettferdige kjem frå Herren, deira sterke vern i trengsels tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Og Herren hjelper deim og friar deim ut, han friar deim frå dei ugudlege og frelser deim, for dei flyr til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Ein salme av David; til minnesofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Herre, refs meg ikkje i din vreide, og tukta meg ikkje i din harm!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'For dine piler er farne ned i meg, og di hand hev falle tungt på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Det finst inkje friskt i mitt kjøt for din vreide skuld; det er ikkje fred i mine bein for mi synd skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'For mine misgjerningar stig meg yver hovudet, som ei tung byrd er dei meg for tunge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Det luftar ilt av mine sår, dei renn av verk for min dårskap skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Eg er krøkt, reint samanbøygd, heile dagen gjeng eg svartklædd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'For mine lender er fulle av brand, og det finst inkje frisk i mitt kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Eg er reint valen og sundslegen, eg skrik høgt av hjartestynjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Herre, for di åsyn er alt mitt ynskje, og min sukk er ikkje løynd for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mitt hjarta slær hardt, mi kraft hev forlate meg, og jamvel mine augo hev mist sitt ljos for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Mine vener og frendar held seg undan frå mi plåga, og mine næmaste stend langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Og dei som ligg etter mitt liv, dei legg ut snaror, og dei som søkjer mi ulukka, dei talar um undergang og tenkjer på svik heile dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Og eg er som ein dauv, eg høyrer ikkje, og liksom ein mållaus som ikkje let upp sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Ja, eg er som ein mann som ikkje høyrer, og som ikkje hev motmæle i sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'For til deg, Herre, stend mi von; du vil svara meg, Herre, min Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'For eg segjer: «Dei vil elles gleda seg yver meg; når min fot vaggar, høgmodast dei yver meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'For eg er nær på å falla, og min hugverk er stendigt framfyre meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'For eg må sanna mi skuld, syrgja yver mi synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Og mine fiendar liver, dei er mannsterke, og dei er mange som hatar meg utan orsak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Og dei som løner godt med vondt, stend meg imot, av di eg fer etter det gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Forlat meg ikkje, Herre! Min Gud, ver ikkje langt ifrå meg! Kom meg snart til hjelp, Herre, mi frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Til songmeisteren, til Jedutun; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Eg sagde: «Eg vil vakta mine vegar, so eg ikkje syndar med mi tunga; eg vil leggja taum på min munn, so lenge den ugudlege er meg for augo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Eg tagna og var kurende still; eg tagde utan von um lukka, men mi liding vart rørd upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Mitt hjarta brann i min barm; ved mi grunding kveiktest eld - eg tala med mi tunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Herre, lat meg få vita min ende og målet på mine dagar, kva det er; lat meg vita kor snargjengd eg er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Sjå, som ei lovebreidd hev du sett mine dagar, og mi livstid er som ingen ting for deg; berre som den tome fåfengd er kvart menneskje sett her. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Berre som ein skugge gjeng mannen ikring, berre til fåfengs ståkar dei; han dungar i hop og veit ikkje kven som skal sanka det inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Og no, kva vonar eg, Herre? Mi von stend til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Frels meg frå alle mine misgjerningar, set meg ikkje til spott for dåren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Eg er tagna og let ikkje upp min munn; for du hev gjort det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Tak di plåga burt frå meg! Ved slag av di hand er det ute med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Tuktar du ein mann med refsing for skuld, so fortærer du hans fagerleik som motten. Berre fåfengd er kvart menneskje. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Høyr mi bøn, Herre, og vend øyra til mitt rop; teg ikkje til min gråt! for eg er framand hjå deg, ein gjest som alle mine feder. Sjå burt frå meg, so eg kann kvikna til, fyrr eg fer herifrå og er ikkje meir!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Til songmeisteren, av David; ein salme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Eg venta og venta på Herren, so bøygde han seg til meg og høyrde mitt rop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Og han drog meg upp or den tynande grav, or søkkjedya, og han sette mine føter uppå berggrunn, han gjorde mine stig støde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Og han lagde ein ny song i min munn, ein lovsong til vår Gud. Mange ser det og ottast og lit på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Sæl er den mann som set si lit til Herren og ikkje vender seg til dei ovlåtne og til deim som vik av til lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Herre, min Gud, du hev gjort dine under og dine råder mangfaldige mot oss; ingen ting er liknande med deg; vil eg forkynna og tala um deim, er dei for mange til å telja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Slagtoffer og grjonoffer hev du ikkje hug til - du hev bora øyro på meg - brennoffer og syndoffer krev du ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Då sagde eg: «Sjå, eg kjem; i bokrullen er det skrive for meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'å gjera din vilje, min Gud, det er mi lyst, og di lov er inst i mitt hjarta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Eg bar det gode bod um rettferd i ei stor samling; sjå, eg let ikkje att mine lippor; Herre, du veit det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Eg løynde ikkje di rettferd inne i mitt hjarta, eg tala um din truskap og di frelsa; eg dulde ikkje din nåde og di sanning for ei stor samling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Du, Herre, vil ikkje lata att di miskunn for meg; din nåde og di sanning vil alltid vakta meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'For trengslor utan tal hev umspent meg, mine misgjerningar hev gripe meg, og eg kan ikkje sjå; dei er fleire enn håri på mitt hovud, og mitt mod hev forlate meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Hugnast, Herre, å berga meg! Herre, kom meg snart til hjelp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Lat deim verta til skam og spott alle saman som stend etter mitt liv og vil riva det burt! Lat deim vika attende og skjemnast, som hev hugnad i mi ulukka!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Lat dei verta forfærde yver si skjemd, dei som segjer til meg: «Ha, ha!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Lat deim fegnast og gleda seg i deg alle dei som søkjer deg! Lat deim som elskar di frelsa alltid segja: «Høglova vere Herren!» For eg er arm og fatig; Herren vil tenkja på meg. Du er mi hjelp og min frelsar; min Gud, dryg ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Sæl er den som ser til ein vesallmann; på den vonde dag skal Herren frelsa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Herren skal verja honom og halda honom i live; han skal verta lukkeleg i landet, og du skal visst ikkje yvergjeva honom til hans mordgiruge fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Herren skal stydja han på sotteseng, og vender all hans lega i hans sjukdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Eg segjer: «Herre, ver meg nådig; læk mi sjæl, for eg hev synda mot deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Mine fiendar talar vondt um meg: «Når skal han døy, og hans namn forgangast?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Og um ein kjem og vil sjå til meg, so talar han falske ord; hans hjarta sankar seg vondskap saman, so gjeng han ut og talar um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Alle som hatar meg, kviskrar saman imot meg; dei tenkjer upp imot meg slikt som gjer meg vondt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '«Ei illgjerning heng ved honom, og han som ligg der, skal ikkje meir standa upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Ja, endå den som eg livde i fred med, som eg sette lit til, som åt mitt brød, hev lyft sin hæl imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Men du, Herre, ver meg nådig og hjelp meg upp! So vil eg gjeva deim vederlag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'På dette kjenner eg at du hev hugnad i meg, at min fiende ikkje fær setja i glederop yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Og meg held du uppe i mi uskyld og set meg for di åsyn til æveleg tid. Lova vere Herren, Israels Gud, frå æva og til æva! Amen, amen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Til songmeisteren; ein song til lærdom, av Korahs born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Som ein hjort styn etter vatsbekkjer, so styn mi sjæl etter deg, min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Mi sjæl tyrster etter Gud, etter den livande Gud. Når skal eg koma og syna meg for Guds åsyn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Mine tåror er min mat dag og natt, av di dei all dagen segjer til meg: «Kvar er din Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Dette må eg koma i hug og tøma ut mi sjæl hjå meg: korleis eg drog fram i manntrongen og vandra med deim til Guds hus med fagnadrøyst og lovsong, ein høgtidleg folkestraum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Kvi er du nedbøygd, mi sjæl, og bruser i meg? Venta på Gud, for eg skal endå lova honom for frelsa frå hans andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Min Gud! Mi sjæl er nedbøygd i meg; difor kjem eg deg i hug frå Jordanlandet og Hermonhøgderne, frå det vesle fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Vatsflod ropar til vatsflod ved duren av dine fossar; alle dine brotsjøar og båror slær yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Um dagen sender Herren sin nåde, og um natti er hans song hjå meg, bøn til mitt livs Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Eg må segja til Gud, mitt berg: «Kvi hev du gløymt meg? Kvi skal eg ganga svartklædd under fiende-trykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Det er som knasing i mine bein, at mine fiendar spottar meg, med di dei heile dagen segjer til meg: «Kvar er din Gud?» Kvi er du nedbøygd, mi sjæl, og kvi bruser du i meg? Venta på Gud, for eg skal endå lova honom, mitt andlits frelsa og min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Døm meg, Gud, og før mi sak mot folk utan miskunn, frels meg frå falsk og rettarlaus mann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'For du er den Gud som er mi vern. Kvi hev du støytt meg burt? Kvi skal eg ganga svartklædd under fiende-trykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Send ditt ljos og di sanning, lat deim leida meg, lat deim føra meg til ditt heilage fjell og til dine bustader,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'so eg kann koma til Guds altar, til Gud, min fagnad og mi gleda, og lova deg på cither, Gud, min Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Kvi er du nedbøygd, mi sjæl, og kvi bruser du i meg? Venta på Gud, for eg skal endå lova honom, mitt andlits frelsa og min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Til songmeisteren; av Korahs born; ein salme til lærdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Gud, me hev høyrt med våre øyro, våre feder hev fortalt oss den gjerning du gjorde i deira dagar, i forne dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Du dreiv ut heidningarne med di hand, men deim planta du; du øydelagde folkeslag, men deim breidde du ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'For ikkje med sitt sverd vann dei landet, og deira arm gav deim ikkje siger, men di høgre hand og din arm og ditt andlits ljos; for du hadde hugnad i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Du, Gud, er min konge; byd at Jakob skal verta frelst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Ved deg skal me støyta ned våre fiendar, ved ditt namn skal me treda under føter deim som reiser seg imot oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'For min boge lit eg ikkje på, og mitt sverd gjev meg ikkje siger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Men du gjev oss siger yver våre fiendar, og deim som hatar oss, gjer du til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Av Gud rosar me oss all dagen og lovar ditt namn til æveleg tid. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Og endå hev du støytt oss burt og gjort oss til skam, og du dreg ikkje ut med våre herar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Du let oss vika attende for fienden, og dei som hatar oss, fær seg herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Du gjev oss burt som sauer til å eta upp, og spreider oss ikring millom heidningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Du sel ditt folk for ingen ting, og ikkje set du høg pris på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Du gjer oss til hæding for våre grannar, til spott og spe for deim som bur ikring oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Du gjer oss til eit ordtøke millom heidningarne; dei rister på hovudet åt oss millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Heile dagen stend mi skam for mine augo, og blygsl breider seg yver mitt andlit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'ved røysti av spottaren og hædaren, ved syni av fienden og den hemngiruge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Alt dette er kome yver oss, endå me ikkje hev gløymt deg og ikkje svike di pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Vårt hjarta veik ikkje frå deg, og våre stig sveiv ikkje ut av din veg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'at du skulde slå oss sund der sjakalar bur, og breida oss ned i daudeskugge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Hadde me gløymt vår Guds namn og rett våre hender ut til ein framand gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'skulde Gud då ikkje ransaka det? for han kjenner hjartans løyndomar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Men for di skuld vert me drepne all dagen, me er rekna som slagtesauer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Vakna upp! Kvi søv du, Herre? Vakna då, støyt ikkje burt for alltid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Kvi løyner du di åsyn, gløymer vår armodsdom og vår trengsla?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'For vår sjæl er nedbøygd i moldi, vår likam nedtrykt til jordi. Statt upp til hjelp for oss, og løys oss ut for din nåde skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Til songmeisteren, etter «Liljor»; av Korahs born; ein salme til lærdom, ein song um kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mitt hjarta fløder yver med yndelege ord; eg kved den song eg hev gjort til ein konge; mi tunga er ein snarhendt skrivars penn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Du er den fagraste av menneskjeborni, ynde strøymer yver dine lippor; difor hev Gud velsigna deg til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Gyrd ditt sverd til di lend, du velduge, di høgd og din herlegdom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Og far i din herlegdom fram med siger for sanning og spaklyndt rettferd! Og di høgre hand skal læra deg agelege storverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Din piler er kveste - so folk fell under deg - dei gjeng inn i hjarta på kongens fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Din kongsstol, Gud, stend æveleg og alltid, ein kongsstav med rettvisa er kongsstaven i ditt rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Du elskar rettferd og hatar gudløysa, difor hev Gud, din Gud, salva deg med fagnads olje framfor dine medbrør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Av myrra og aloe og kassia angar alle dine klæde; frå filsbeinshallar fagnar deg strengleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Kongsdøtter er millom dine utvalde; dronningi stend ved di høgre hand i gull frå Ofir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Høyr, dotter, og sjå og bøyg øyra til, og gløym ditt folk og ditt farshus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'og lat kongen hava hugnad i din fagerleik! for han er din herre, og du skal hylla honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Og Tyrus’ dotter skal søkja ditt ynde med gåvor - dei rikaste av folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Ovleg prud er kongsdotteri der inne; hennar klædnad er gjenomvoven med gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'I utsauma bunad vert ho leidd til kongen; møyar, hennar vener, fylgjer etter henne; dei vert førde inn til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Dei vert leidde fram med gleda og fagnad, dei gjeng inn i kongshalli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'I staden for dine feder skal dine søner koma; du skal setja deim til hovdingar utyver heile jordi. Eg vil setja ditt namn eit minne millom alle ætter; difor skal folki lova deg æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Til songmeisteren; av Korahs born, etter Alamot; ein song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Gud er mi hyggja og vår styrke, fullvel røynd i trengslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Difor ottast me ikkje, um so jordi vert umskift, og um fjelli ragar hjarta av storhavet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'um havbårorne dyn og skumar, og fjelli skjelv for deira ofse. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Der er ei å, hennar bekkjer gled Guds by, den heilage stad der den Høgste bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Gud er midt i honom, so han skal ikkje rugga; Gud hjelper honom i morgonlysingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Folkeslag rasa, rike vart rikka, han let si røyst ljoda, jordi bråna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Herren, allhers drott, er med oss; Jakobs Gud er vår faste borg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kom og sjå Herrens storverk, som gjer øydeleggjingar på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Han gjer ende på herferder yver all jordi, bryt bogen sund og høgg spjotet av; stridsvognerne brenner han upp i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '«Haldt upp og kjenn at eg er Gud! Eg er upphøgd millom folki, upphøgd på jordi.» Herren, allhers drott, er med oss; Jakobs Gud er vår faste borg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Til songmeisteren; av Korahs born; ein salme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Klappa i henderne, alle folk! Kved høgt for Gud med fagnadrøyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'For Herren, den Høgste, er ageleg, ein stor konge yver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Han legg folk under oss og folkeslag under våre føter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Han vel ut vår arvlut åt oss, til gilda for Jakob som han elskar. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Gud for upp med fagnadrop, Herren med basunljod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Syng lov for Gud, syng lov! Syng lov for vår konge, syng lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'For Gud er konge yver all jordi; syng til hans lov ein visleg song!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Gud hev teke riket yver folki, Gud hev sett seg på sin heilage kongsstol. Folkedrottarne samlar seg som eit folk til Abrahams Gud; for skjoldarne på jordi høyrer Gud til, han er høgt upphøgd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Ein song, ein salme; av Korahs born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Stor er Herren og høglova i vår Guds by, på hans heilage fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Fager i si høgd, ein fagnad for all jordi er Sions fjell, utkanten av nordheimen, staden til den store kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Gud er i hans hallar kjend som ei fast borg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'For sjå, kongarne kom saman og drog fram i lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Dei såg - so vart dei forfærde, dei vart vitskræmde, flydde i bråhast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Ein skjelv greip deim der, ei bivring som hjå ei barnsjuk kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Med austanvind bryt du sund Tarsis-skip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Liksom me hev høyrt, so hev me no set det i Herren, allhers drotts by, i vår Guds by, Gud gjer honom fast til æveleg tid. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Me grundar på din nåde, Gud, midt i ditt tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Som ditt namn, Gud, so er din pris alt til endarne av jordi; di høgre hand er full av rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Sionsfjellet gled seg, Juda døtter fagnar seg yver dine domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Gakk ikring Sion, far rundt um henne, tel hennar tårn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Legg merke til hennar vollar, gakk igjenom hennar hallar, so de kann fortelja um det til den komande ætt. For denne Gud er vår Gud æveleg og alltid; han skal føra oss ut yver dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Til songmeisteren; av Korahs born; ein salme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Høyr dette, alle folk, vend øyra til, alle de som bur i verdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'både låge og høge, rik og fatig, alle saman!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Min munn skal tala visdom, og det som mitt hjarta tenkjer upp, er vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Eg vil bøygja mitt øyra til fyndord, eg vil lata upp mi gåta til harpeljod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Kvi skal eg ottast i dei vonde dagar, når vondskap av mine forfylgjarar kringset meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'dei som set si lit til sitt gods og rosar seg av sin store rikdom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Ein mann kann ikkje løysa ut ein bror, kann ikkje gjeva Gud løysepengar for honom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, '- utløysingi av deira liv er for dyr, og han let det vera til æveleg tid -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'so han skulde halda ved å liva for alltid og ikkje sjå gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Nei, han må sjå: Vismenner døyr, dåre og fåviting gjeng burt alle saman og let sitt gods etter seg til andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Deira inste tanke er at deira hus skal standa æveleg, deira bustader frå ætt til ætt; dei kallar sin jorder etter sine namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Men eit menneskje i høg vyrdnad vert ikkje verande; han er lik dyri, dei må tagna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'So gjeng det deim som er fulle av tru til seg sjølve, og etter deim fylgjer dei som likar deira tale. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Som sauer vert dei førde ned i helheimen, dauden gjæter deim, og dei trurøkne tred deim ned, når morgonen renn; og deira skapnad vert øydelagd av helheimen, so dei hev ingen heimstad lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Men Gud skal løysa ut mi sjæl or handi på helheimen; for han skal taka meg til seg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Ottast ikkje når ein mann vert rik, når hans hus kjem til stor æra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'For han skal ingen ting taka med seg når han døyr; hans æra skal ikkje fara ned etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Um han og velsignar si sjæl i si livstid, og dei prisar deg for di du gjer deg gode dagar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'so skal du då koma til di fedreætt, dei som ikkje ser ljoset i all æva. Eit menneskje i høg vyrdnad, som ikkje hev vit, vert lik dyri; dei må tagna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein salme av Asaf. Gud, Gud Herren talar og kallar på jordi frå solekoma til soleglad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Frå Sion, fagerleiks kruna, strålar Gud fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Vår Gud kjem og skal ikkje tegja. For hans åsyn gjeng etande eld, og ikring honom stormar det sterkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Han kallar på himmelen ovantil og på jordi til å døma sitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '«Samla til meg mine trugne, som hev gjort pakt med meg um offer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Og himlarne forkynner hans rettferd; for Gud er den som skal halda dom. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '«Høyr, mitt folk, eg vil tala; Israel, eg vil vitna imot deg; Gud, din Gud er eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Ikkje for dine offer vil eg lasta deg; dine brennoffer er alltid framfyre meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Eg vil ikkje taka uksar frå ditt hus eller bukkar frå dine grindar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'For meg høyrer alle dyr i skogen til, fe på fjelli i tusundtal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Eg kjenner alle fuglar på fjelli, og det som rører seg på marki, er meg for augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Um eg var hungrig, vilde eg ikkje segja det til deg; for meg høyrer jordriket til med alt det som fyller det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Skulde eg eta kjøt av stutar og drikka blod av bukkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Ofra lov og takk til Gud og gjev den Høgste det du hev lova,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'og kalla på meg den dag du er i naud, so vil eg frelsa deg ut, og du skal prisa meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Men til den ugudlege segjer Gud: «Kva hev du med å fortelja um mine lover og taka mi pakt i din munn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'etter di du hatar tukt og kastar mine ord attum deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Når du ser ein tjuv, er du gjerne med honom, og med horkarar er du i lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Din munn slepper du laus til vondt, og di tunga spinn i hop svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Du sit og talar imot bror din, set ein skamflekk på son til mor di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Dette gjorde du, og eg tagde; so tenkte du eg var liksom du sjølv; men eg vil yvertyda deg og leggja det fram for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Gjev gaum etter dette, de som gløymer Gud, so eg ikkje skal riva burt, og ingen frelser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Den som ofrar meg takk, han ærar meg, og den som gjeng den rette veg, honom vil eg lata sjå Guds frelsa!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Til songmeisteren; ein salme av David,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'då profeten Natan kom til honom, etter han hadde gjenge inn til Batseba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Gud, ver meg nådig etter di miskunn! Sletta ut mine brot etter din store godhug!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Två meg vel rein frå mi skuld, og reinsa meg frå mi synd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'For mine misgjerningar kjenner eg, og mi synd er alltid framfyre meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Mot deg einast hev eg synda og gjort det som vondt er i dine augo, so du må vera rettferdig når du talar, vera rein når du dømer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Sjå, eg er fødd i misgjerning, og mor mi hev avla meg i synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Sjå, du hev lyst til sanning i innarste; so lær meg då visdom i hjartans løynrom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Reinsa meg frå synd med isop, so eg vert rein! Två meg, so eg vert kvitare enn snø!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Lat meg høyra fagnad og gleda, lat dei bein fagna seg som du hev slege sund!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Løyn di åsyn for mine synder, og sletta ut alle mine misgjerningar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Gud, skap i meg eit reint hjarta, og gjev meg ei ny, stødug ånd inni meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Kasta meg ikkje burt frå di åsyn, og tak ikkje din heilage ande frå meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Gjev meg atter fagnaden av di frelsa, og haldt meg uppe med ei viljug ånd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'So vil eg læra lovbrjotarar dine vegar, og syndarar skal venda um til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Gud, fria meg frå blodskuld, Gud, mine frelsar! So skal mi tunga fagna seg høgt yver di rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Herre, lat upp mine lippor! So skal min munn forkynna din pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'For du hev ikkje lyst til slagtoffer - elles skulde eg gjeva deg det; i brennoffer hev du ikkje hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Offer for Gud er ei sundbroti ånd; eit sundbrote og knust hjarta vil du, Gud, ikkje forsmå. Gjer vel imot Sion etter din nåde, bygg murarne åt Jerusalem! Då skal du hava hugnad i rettferds offer, i brennoffer og heiloffer; då skal dei ofra uksar på ditt altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Til songmeisteren; ein salme til lærdom av David,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'då edomiten Doeg kom og fortalde Saul og sagde til honom: «David er komen i Ahimeleks hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Kvi rosar du deg av vondskap, du velduge? Guds nåde varer all dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'De tunga stilar du på tyning liksom ein kvest rakekniv, du som legg upp svikråd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Du elskar det vonde framfor det gode, lygn framfor å tala sant. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Du elskar alle drepande ord, du svikfulle tunga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'So skal og Gud riva deg ned for alltid; han skal gripa deg og rykkja deg upp frå tjeldet og rydja deg ut or livsens land. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Og dei rettferdige skal sjå det og ottast, og dei skal læ åt honom og segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, '«Sjå der den mann som ikkje heldt Gud for si vern, men sette si lit til sin store rikdom og sette sin styrke i sin vondskap.» Men eg er som eit grønt oljetre i Guds hus; eg set mi lit til Guds nåde æveleg og alltid. Eg vil lova deg til æveleg tid, for du hev gjort det, og eg vil vona på ditt namn, for det er godt, for augo på dine trugne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Til songmeisteren, etter Mahalat; ein salme til lærdom av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Dåren segjer i sitt hjarta: «Det er ingen Gud til.» Vond og styggjeleg er deira misgjerning; det er ingen som gjer godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Gud skodar ned frå himmelen på menneskjeborni og vil sjå um det finst nokon vitug, nokon som søkjer Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Dei er alle avvikne, dei er utskjemde alle saman; det er ingen som gjer godt, det er ikkje ein einaste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Veit dei det då ikkje, dei som gjer urett? Dei et mitt folk som dei et brød; på Gud kallar dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Då vert dei storleg rædde, der ingen ræddhug var; for Gud spreider beini av deim som lægrar seg mot deg; du gjer deim til skammar, for Gud hev støytt deim burt. Å, gjev frelsa frå Sion må koma yver Israel! Når Gud vender sitt folks vanlukka, då skal Jakob fagna seg, Israel gleda seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Til songmeisteren, med strengleik; ein song til lærdom av David,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'då zifitarne kom og sagde til Saul: «David held seg løynd hjå oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Gud, frels meg ved ditt namn, og døm meg til min rett ved di kraft!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Gud, høyr mi bøn, vend øyra til ordi frå min munn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'For framande stend upp imot meg, og valdsmenner stend meg etter livet; dei hev ikkje Gud for augo. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Sjå, Gud hjelper meg, Herren er den som held uppe mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Det vonde skal falla tilbake på deim som lurar på meg; gjer deim til inkjes i din truskap! Med viljugt hjarta vil eg ofra til deg; ditt namn vil eg prisa, Herre, for det er godt. For det friar meg ut or all naud, og på mine fiendar ser mitt auga med lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Til songmeisteren, med strengleik; ein song til lærdom av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Gud, vend øyra til mi bøn, og løyn deg ikkje for mi naudbeding!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Gjev gaum etter meg og svara meg! Eg er uroleg med mine sorgfyllte tankar, og eg må stynja');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'for rop frå fienden, for trykk frå den ugudlege. For dei velter vondt yver meg, og i vreide forfylgjer dei meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mitt hjarta skjelv i meg, og daudens fæle hev falle på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Otte og skjelving kjem yver meg og rædsla legg seg på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Og eg segjer: «Å, hadde eg vengjer som duva, då skulde eg fljuga burt og finna ein bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Sjå, eg vilde fly langt burt, eg vilde finna herbyrge i øydemarki. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Eg vilde skunda meg i livd for den føykjande vinden, for stormen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Sluk deim, Herre, kløyv deira tungemål! For eg ser vald og kiv i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Dag og natt renner dei kringum honom på murarne, ugjerd og møda er midt i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Tjon er midt i honom, og ikkje vik frå gatorne vald og svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'For ikkje min fiende er det som hæder meg - det kunde eg tola; ikkje min uven er det som briskar seg mot meg - då kunde eg gøyma meg for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Men du er det, du som var min likemann, min ven, min kjenning, -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'me som hadde huglegt samråd med kvarandre, som gjekk til Guds hus med den glade hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Lat dauden koma brått på deim! Lat deim fara ned til helheimen livande! For vondskap råder i deira bustad og i deira hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Eg vil ropa til Gud, og Herren skal frelsa meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Kveld og morgon og middag vil eg klaga og sukka, so vil han høyra mi røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Han løyser ut mi sjæl frå strid mot meg og gjev meg fred, for mange er dei mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Gud skal høyra og svara deim - han sit frå fordoms tid, sela - deim som ikkje vil verta annarleis og som ikkje ottast Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Han legg hand på folk som held fred med honom, han bryt si pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Ordi frå hans munn er håle som smør, men hans hjarta er fullt av strid. Hans ord er mjukare enn olje, og dei er då utdregne sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Kasta byrdi di på Herren, og han skal halda deg uppe! han skal ikkje i all æva lata den rettferdige verta rikka. Men du, Gud, skal støyta deim ned i den djupe grav; blodgiruge og falske menner skal ikkje nå til helvti av si livetid; men eg set mi lit til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Til songmeisteren, etter «Den mållause duva langt burte»; av David, ein miktam, då filistarane tok honom i Gat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Ver meg nådig, Gud, for menneskje vil sluka meg; heile dagen trengjer dei meg med strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Dei vil sluka meg dei som lurar på meg, heile dagen; for mange er dei som i stormod strider imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Den dagen då eg ottast, set eg mi lit til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Ved Gud skal eg lova hans ord, til Gud set eg lit, eg ottast ikkje, kva skulde kjøt kunna gjera meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Heile dagen rengjer dei mine ord; alle deira tankar er imot meg til det som vondt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Dei slær seg saman, dei lurer, dei vaktar på mine stig, då dei trår etter livet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Skulde dei med sin vondskap koma seg undan? Gud, støyt folkeslag ned i vreide!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Du hev talt kor ofte eg hev fare på flugt, mine tåror er gøymde i di flaska; stend dei ikkje i di bok?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Då skal mine fiendar venda attende, den dagen eg ropar; det veit eg, at Gud er med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Ved Gud skal eg lova ordet; ved Herren skal eg lova ordet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Til Gud set eg lit, eg ottast ikkje; kva kann menneskje gjera meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Gud, eg hev lovnader på meg til deg; eg vil løysa deim ut med takkoffer til deg. For du hev berga mi sjæl frå dauden, ja mine føter frå fall, so eg kann ferdast for Gud i ljoset åt dei livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Til songmeisteren, etter «tyn ikkje»; av David, ein miktam, då han flydde for Saul inn i helleren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Ver meg nådig, Gud, ver meg nådig! For til deg flyr mi sjæl, og i skuggen av dine vengjer søkjer eg livd, til dess ulukka gjeng yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Eg ropar til Gud, den Høgste, til den Gud som fullfører sitt verk for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Han vil senda frå himmelen og hjelpa meg, når han som vil sluka meg, spottar. Sela. Gud vil senda si miskunn og sin truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Mi sjæl er millom løvor, eg må liggja millom deim som spruter eld, millom menneskjeborn som til tenner hev spjot og piler, og til tunga eit kvast sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Gud, syn deg høg yver himmelen, di æra yver heile jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Dei set garn for mine stig, mi sjæl er nedbøygd; dei grev ei grav for meg, so fell dei midt i henne sjølve. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mitt hjarta er rolegt, Gud, mitt hjarta er rolegt, eg vil syngja og lovsyngja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Vakna, mi æra! Vakna, harpa og cither! Eg vil vekkja morgonroden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Eg vil prisa deg millom folki, Herre, eg vil lovsyngja deg millom folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'For di miskunn er stor til himmelen, og din truskap til dei høge skyer. Gud, syn deg høg yver himmelen, di æra yver heile jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Til songmeisteren; «tyn ikkje»; av David, ein miktam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Tru de verkeleg med dykkar målløysa talar det som er rettferd? Og dømer de rett, de menneskjeborn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Nei, i hjarta lagar de til misgjerningar, i landet veg de ut vald som kjem frå dykkar hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Dei ugudlege gjeng på avveg alt frå morsfang, ljugarane fer vilt alt frå morsliv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Eiter hev dei som orme-eiter, dei er som ein dauv orm, som dytter øyra til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'so han ikkje høyrer på røysti åt tauvrekallen, han som vel kann trolla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Gud, slå inn tennerne i munnen deira, Herre, støyt sund jakslarne på dei unge løvor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Lat deim kverva som burtrennande vatn! Legg nokon sine piler i bogen, so lat deim vera som utan odd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Lat deim vera som ein snigel, som løyser seg upp medan han gjeng, og liksom ei kvinna sitt ufullborne foster som ikkje hev set soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Fyrr dykkar grytor fær kjenna klungerriset, skal han blåsa det burt, både det friske og det som brenn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Den rettferdige skal gleda seg, av di han ser hemn; han skal två sine føter i blodet av den ugudlege. Og folk skal segja: «Det finst då frukt for den rettferdige; der er då ein Gud som dømer på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Til songmeisteren; «tyn ikkje»; av David; ein miktam, då Saul sende folk som gjætte på huset og vilde drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Frels meg frå mine fiendar, min Gud, berga meg frå deim som stend upp imot meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Frels meg frå deim som gjer urett, og berga meg frå blodgiruge menner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'For sjå, dei ligg på lur etter mi sjæl, sterke menner slær seg saman imot meg, Herre, utan mi misgjerd og utan mi synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Utan mi skuld renner dei fram og gjer seg ferdige. Vakna og møt meg, og sjå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ja du, Herre, allhers drott, Israels Gud, vakna til å heimsøkja alle heidningar, ver ikkje nådig mot nokon av dei falske nidingar! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Dei kjem att um kvelden, dei hyler som hundar og renner kring i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Sjå, dei let det gøysa ut or munnen sin, der er sverd i deira lippor, for: «Kven høyrer?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Men du, Herre, lær åt deim, du spottar alle heidningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Mot hans magt vil eg venta på deg, for Gud er mi borg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Min Gud vil møta meg med si nåde, Gud vil lata meg sjå med lyst på deim som lurer på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Drep deim ikkje, at ikkje mitt folk skal gløyma det! Driv deim ikring ved di magt og støyt deim ned, du Herre, vår skjold!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Kvart ord på deira lippor er ei synd i deira munn; lat deim so verta fanga i sitt ovmod og for den banning og lygn som dei talar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Gjer ende på deim i vreide, gjer ende på deim, so dei ikkje meir er til, og lat dei vita at Gud er Herre i Jakob, alt til endarne av jordi! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Og dei kjem att um kvelden, hyler som hundar og renner kring i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Dei flakkar um etter mat, vert dei ikkje mette, nattar dei yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Men eg vil syngja um di magt og um morgonen lovsyngja di miskunn; for du er mi borg og mi livd den dag eg er i naud. Min styrke! for deg vil eg syngja; for Gud er mi borg, min miskunnsame Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Til songmeisteren, etter «Vitnemålslilja»; ein miktam av David til å læra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'då han stridde med syrarar frå Mesopotamia og syrarar frå Soba, og Joab kom att og slo tolv tusund edomitar i Saltdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Gud, du hev støytt oss burt, du hev rive oss sund, du hev vore vreid, kveik oss upp att!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Du hev fenge landet til å skjelva og rivna; bøt du bresterne, for det stend ikkje stødt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Du hev late ditt folk sjå harde ting, du hev skjenkt oss vin so me tumla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Men du hev gjeve deim som ottast deg eit merke til å hevja seg for sanning skuld. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'At dei du elskar må verta frelste, so hjelp oss no med di høgre hand, og bønhøyr oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Gud hev tala i sin heilagdom: «Eg vil gleda meg, eg vil skifta ut Sikem, og Sukkotdalen vil eg mæla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Meg høyrer Gilead til, og meg høyrer Manasse til, og Efraim er verja for mitt hovud, Juda er min førarstav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab er mitt vaskarfat, på Edom kastar eg skoen min; ropa høgt for meg, du Filistarland!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Kven vil føra meg til den faste by? Kven leider meg til Edom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Hev ikkje du, Gud, støytt oss burt? og du, Gud, gjeng ikkje ut med våre herar? Gjev oss hjelp imot fienden, for mannehjelp er fåfengd! Med Guds hjelp skal me gjera storverk, og han skal treda ned våre fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Til songmeisteren, på strengleik; av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Gud, høyr mitt klagerop, merka mi bøn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Frå enden av jordi ropar eg til deg, medan hjarta vanmegtast; på eit fjell som er for høgt for meg, må du føra meg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'For du hev vore mi livd, eit sterkt tårn mot fienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Eg vil æveleg bu i ditt tjeld, finna livd i skuggen av dine vengjer. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'For du, Gud, hev høyrt på mine lovnader, deim som ottast ditt namn, hev du gjeve deira arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Du vil leggja dagar til kongens dagar, hans år skal vera som ætt etter ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Han skal sitja æveleg for Guds åsyn; set miskunn og truskap til å vara honom! So vil eg æveleg lovsyngja ditt namn, at eg kann løysa mine lovnader dag etter dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Til songmeisteren, for Jedutun; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Einast hjå Gud er mi sjæl still, frå honom kjem mi frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Einast han er mitt fjell og mi frelsa, han er mi borg, dei skal ikkje rikka meg mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Kor lenge vil de alle storma inn på ein mann, brjota honom ned som ein hallande mur, ein nedrapa vegg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Dei samråder seg berre um å støypa honom ned frå hans høgd. Dei likar lygn. Med munnen velsignar dei, men i hjarta bannar dei. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Einast hjå Gud ver still, mi sjæl, for frå honom kjem mi von.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Einast han er mitt fjell og mi frelsa, mi borg, dei skal ikkje rikka meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Hjå Gud er mi frelsa og mi æra; mitt sterke fjell, mi livd er i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Lit på honom all tid, folk, renn dykkar hjarta ut for hans åsyn! Gud er livd for oss. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Berre fåfengd er menneskjesøner, lygn er mannesøner. I vegtskåli stig dei upp - lettare enn fåfengd alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Lit ikkje på vald, og set ikkje fåfengd von til ran! Når buet veks, fest ikkje hjarta ved det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Ein gong hev Gud sagt, tvo gonger hev eg høyrt dette, at styrke høyrer Gud til. Og hjå deg, Herre, er miskunn, for du gjev kvar ein etter hans gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Ein salme av David, då han var i Juda øydemark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Gud, du er min Gud, eg søkjer deg tidleg; mi sjæl tyrster etter deg, mitt kjøt lengtar etter deg i eit turt land som ligg i vanmagt utan vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Soleis hev eg set etter deg i heilagdomen til å sjå di kraft og di æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'For di miskunn er betre enn livet, mine lippor skal prisa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Soleis vil eg lova deg so lenge eg liver, i ditt namn vil eg lyfta upp mine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Som av merg og feitt skal mi sjæl verta mett, og med lovsyngjande lippor skal min munn prisa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Når eg kjem deg i hug på mitt lægje, tenkjer eg på deg i nattevakterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'For du hev vore hjelp for meg, i skuggen av dine vengjer kann eg fegnast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Mi sjæl heng fast ved deg; di høgre hand held meg uppe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Men dei som stend meg etter livet og vil tyna det, dei skal koma til dei nedste djup i jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Dei skal verta yvergjevne til sverdmagt, verta til ran for revar. Men kongen skal gleda seg i Gud; kvar den som sver ved honom, skal prisa seg sæl, for ljugararne skal verta målbundne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Gud, høyr mi røyst når eg klagar, vara mitt liv frå fiende-skræmsla!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Gøym meg for løyndelaget av dei vonde, for den bråkande hop av illgjerningsmenner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'som kvesser si tunga som eit sverd, siktar med si pil, det beiske ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'og vil skjota ned den uskuldige i løynd; brått skyt dei honom og ræddast ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Dei styrkjer seg i si vonde råd, dei fortel at dei vil leggja løynde snaror, dei segjer: «Kven ser deim?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Dei tenkjer upp ugjerningar: «Me er ferdige, tanken er tenkt» - og det indste i mannen og hjarta er djupt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Då skyt Gud deim, pili kjem brått og sårar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Dei stupar ned, deira tunge kjem yver deim, alle som ser på deim, rister på hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Og alle menneskje ræddast og forkynner Guds gjerning, og hans verk skynar dei. Den rettferdige gleder seg i Herren og flyr til honom, og alle ærlege av hjarta prise seg sæle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Til songmeisteren; ein salme av David, ein song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Gud, dei er stille for deg og prisar deg på Sion, og dei gjev deg det dei hev lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Du som høyrer bøner, til deg kjem alt kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Når misgjerningar hev vorte for sterke for meg, so forlet du våre forbrot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Sæl er den som du vel ut og let koma nær, so han bur i dine fyregardar; me vil metta oss med det gode i ditt hus, ditt heilage tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Med skræmelege gjerningar bønhøyrer du oss i rettferd, du, vår Frelse-Gud, ei livd for alle heimsens endar og havet langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Han gjer fjelli faste med si kraft, gyrd med velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Han døyver havsens dur, bylgjeduren og bråket av folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Og dei som bur ved endarne av jordi, ræddast for dine teikn, heimen for morgon og kveld fyller du med lovsong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Du hev gjesta jordi og gjeve henne ovnøgd, du hev gjort henne ovleg rik, Guds bekk er full av vatn. Du hev laga til korn for folk, for soleis laga du jordi til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Du vatna hennar plogforer, jamna dei med upp-pløgde åkrar, du bløytte henne med regnskurer, velsigna hennar grøda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Du hev krynt ditt gode år, og dine fotspor dryp av feitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Beiti i øydemarki dryp, og haugarne gyrdar seg med lovsong. Engjarne er klædde med sauer, og dalarne er fyllte med korn; folk fegnast og syng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Til songmeisteren; ein song, ein salme. Ropa fagnadrop for Gud, all jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Syng ut hans namns æra, gjev honom æra til hans pris!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Seg til Gud: «Kor skræmelege dine verk er! For di store magt skuld må dine fiendar gjøla for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'All jordi skal tilbeda deg og syngja deg lov, dei skal syngja um ditt namn.» Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Kom og sjå Guds gjerningar! Skræmeleg er han i gjerning mot menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Han gjorde havet um til turrlende, gjenom elvi gjekk dei til fots; der gledde me oss i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Han råder med sitt velde æveleg, hans augo gjæter heidningarne; dei tråssuge må ikkje upphøgja seg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'De folk, lova vår Gud, og lat røysti av hans lovsong verta høyrd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'han som heldt vår sjæl i live, og ikkje let vår fot vera ustød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'For du prøvde oss, Gud, du reinsa oss, som dei reinsar sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Du førde oss inn i eit garn, du lagde ei tyngjande byrd på våre lender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Du let menneskje fara yver vårt hovud, me kom i eld og vatn - men du førde oss ut til uppkveikjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Eg vil ganga inn i ditt hus med brennoffer; eg vil gjeva deg det eg hev lova,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'det som gjekk yver mine lippor, og som munnen min tala ut då eg var i naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Brennoffer av feite sauer vil eg ofra til deg med eim av verar, eg vil ofra både uksar og bukkar. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Kom og høyr, so vil eg fortelja, alle de som ottast Gud, kva han hev gjort for mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Til honom ropa eg med min munn, og lovsong var på tunga mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Hadde eg stila på urett i mitt hjarta, vilde Herren ikkje høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Men Gud hev høyrt, han lydde på mi bønerøyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Lova vere Gud, som ikkje viste mi bøn ifrå seg og ikkje tok frå meg si miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Til songmeisteren på strengleik; ein salme, ein song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gud vere oss nådig og velsigne oss, han late si åsyn lysa hjå oss - Sela -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'so dei må kjenna din veg på jordi, di frelse hjå alle heidningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Folki skal prisa deg, Gud, folki skal prisa deg alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Folkeslagi skal gledast og fagna seg høgt; for du dømer folki med rett, og folkeslagi på jordi leider du. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Folki skal prisa deg, Gud, folki skal prisa deg alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Landet hev gjeve si grøda; Gud, vår Gud velsignar oss. Gud velsignar oss, og alle heimsens endar skal ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Til songmeisteren; av David; ein salme, ein song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Gud reiser seg, hans fiendar vert spreidde, og dei som hatar honom, flyr for hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Liksom røyk driv burt, so driv du deim burt; liksom voks brånar for eld, so gjeng dei ugudlege til grunnar for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Og dei rettferdige gled seg, dei fagnar seg for Guds åsyn, dei frygdar seg med gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Syng for Gud, syng lov for hans namn! Bygg veg for han som fer fram i øydemarker, Jah er namnet hans, og fegnast for hans åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Far for farlause og domar for enkjor er Gud i sin heilage bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Gud gjev dei einslege hus og heim, han fører fangar ut til lukka; berre dei motstridige bur i turrlende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Gud, då du drog ut framfyre folket ditt, då du skreid fram i øydemarki - Sela -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'då skalv jordi, ja, himmelen draup for Guds åsyn, Sinai der burte skalv for Guds, Israels Guds, åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Rikelegt regn let du falla, Gud, du styrkte arven din då han var utmødd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Ditt folk sette seg ned i landet; Gud, du var god og reidde det til for armingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Herren gjev sigersong; ein stor skare av kvinnor kjem med gledebod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Kongar yver herar flyr, dei flyr, og ho som sit heime, deiler herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Når de ligg millom felæger, er det som sylvlagde duvevengjer, og vengfjører med grøn gullglima.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Når den Allmegtige spreider kongar der, er det som det snøar på Salmon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Eit Guds fjell er Basans fjell, eit fjell med mange kollar er Basans fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Kvifor ser de skakt, de fjell med mange kollar, til det fjellet der Gud tekkjest å bu? Herren skal og bu der for alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Guds vogner er tvo gonger ti tusund, tusund på tusund, Herren er imillom deim, Sinai er i heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Du for upp i det høge, førde fangar burt, tok gåvor millom menneskje, ogso av dei tråssuge, at du kunde bu der, Herre Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Lova vere Herren dag etter dag! Legg dei byrd på oss, er Gud vår frelsa. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Gud er for oss ein Gud til frelsa, og hjå Herren, Herren er det utvegar frå dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Ja, Gud krasar hovudet på sine fiendar, den hærde hovudkruna på honom som ferdast i si syndeskuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Herren segjer: «Frå Basan tek eg deim att, eg vil taka deim att frå havsens djup,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'so foten din må trakka i blod, tunga åt hundarne dine få sin lut av fiendarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Dei ser di sigersferd, Gud, sigersferdi der min Gud, min konge, fer inn i heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Fyre gjeng songarar, etterpå harpespelarar midt imillom møyar som slær på trummor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Lova Gud i samlingarne, lova Herren, de som er av Israels kjelda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Der er Benjamin, den yngste, som er herre yver deim, hovdingarne av Juda - deira hop, hovdingarne av Sebulon, hovdingarne av Naftali.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Din Gud hev bode at du skal vera sterk; Gud, styrk det som du hev gjort for oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'For ditt tempel skuld yver Jerusalem vil kongar føra gåvor til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Skjell på dyret i sevet, på stuteflokken og folkekalvarne, so dei kastar seg ned for deg med sylvstykke! Han spreider folk som er huga på strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Velduge menner skal koma frå Egyptarland, \'tiopia skal skunda seg og retta henderne ut til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'De rike på jordi, syng for Gud, syng lov for Herren! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Han som fer fram i dei eldegamle himle-himlar! Sjå, han let si røyst høyra, ei veldug røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Gjev Gud magt! Yver Israel er hans høgd, og hans magt i dei høge skyer. Skræmeleg er du, Gud, frå dine heilagdomar; Israels Gud, han gjev folket magt og styrke. Lova vere Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Til songmeisteren, etter «Liljor»; av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Frels meg, Gud! for vatni trengjer seg inn på livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Eg er sokken ned i det djupe dike der det inkje fotfeste er, eg er komen ut i ovdjupe vatn, og flodi fløymer yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Eg er trøytt av mi roping, det brenn i min strupe, mine augo er upptærde, med di eg ventar på min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Fleire enn håri på mitt hovud er dei som hatar meg utan orsak, mange er dei som vil meg tyna meg, som utan grunn er mine fiendar; det eg ikkje hev rana, skal eg no gjeva attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Gud, du kjenner min dårskap, og all mi syndeskuld er ikkje løynd for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Lat deim ved meg ikkje verta til skammar, dei som ventar på deg, Herre, Herre, allhers drott! Lat deim ikkje ved meg verta skjemde, dei som søkjer deg, Israels Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'For di skuld ber eg hæding, skjemsla ligg yver mitt andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Eg hev vorte framand hjå brørne mine, og ein utlending hjå borni til mor mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'For brennhug for ditt hus hev ete meg upp, og deira spottord som spottar deg, hev falle på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Då mi sjæl græt medan eg fasta, vart eg spotta for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Då eg laga ein sekk til klædde for meg, vart eg eit ordtøke for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Dei som sit i porten, røder um meg, og drikkarane syng um meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Men eg kjem med mi bøn til deg, Herre, i nådetidi, Gud, for di store miskunn; svara meg med di trufaste hjelp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Fria meg ut or søyla, og lat meg ikkje søkka! Lat meg verta utfria frå deim som hatar meg og frå dei djupe vatni!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Lat ikkje vatsflodi fløyma yver meg, og ikkje djupet svelgja meg, og heller ikkje brunnen lata att sitt gap yver meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Svara meg, Herre, for din nåde er god, etter di store miskunn vend deg til meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Og løyn ikkje di åsyn for tenaren din, for eg er i naud; svara meg snart!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Kom nær til mi sjæl, løys henne ut! Frels meg for mine fiendar skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Du kjenner mi spott og skam og vanæra, for di åsyn stend alle dei som trengjer meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Spottord hev brote mitt hjarta sund, so eg er sjuk; eg venta på medynk, men der var ingi, og på trøystarar, men eg fann ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Og dei gav meg gall å eta, og då eg var tyrst, gav dei meg eddik å drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Lat bordet deira framfyre deim verta ei snara, og ei gildra for deim når dei er trygge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Lat augo deira dimmast so dei ikkje ser, og lat deira lender alltid skjelva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Renn ut yver deim din vreide, og lat din brennande harm nå deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Lat deira bustad verta øydd, lat det ingen vera som bur i deira tjeld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'For dei forfylgjer den som du hev slege, og dei fortel um pinsla åt deim som du hev gjenomstunge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Lat deim leggja syndeskuld til si syndeskuld, og lat deim ikkje koma til di rettferd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Lat deim verta utstrokne or livsens bok, og ikkje verta innskrivne med dei rettferdige!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Men eg er ein arming full av verk, Gud, lat di frelsa berga meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Eg vil lova Guds namn med song og høglova honom med takksegjing,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'og det skal tekkjast Herren betre enn ein ung ukse med horn og klauver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Når spaklyndte ser det, vil dei gleda seg; de som søkjer Gud - må dykkar hjarta liva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'For Herren høyrer på dei fatige, og sine fangar vanvyrder han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Himmel og jord skal lova honom, havet og alt som krek i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'For Gud skal frelsa Sion og byggja byarne i Juda, og dei skal bu der og eiga deim. Og avkjømet til hans tenarar skal erva deim, og dei som elskar hans namn, skal bu der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Til songmeisteren; av David; til minnesofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Gud, ver meg til berging! Herre, kom meg snart til hjelp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Lat deim verta til skam og spott, dei som stend etter mitt liv! Lat deim vika attende og skjemmast, som hev hugnad i mi ulukka!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Lat deim snu for si skjemd dei som segjer: «Ha, ha!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Lat deim fegnast og gleda seg i deg, alle dei som søkjer deg! Lat deim som elskar di frelsa, alltid segja: «Høglova vere Gud!» For eg er arm og fatig; Gud, kom snart til meg! Du er mi hjelp og min frelsar; Herre, dryg ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Til deg, Herre, flyr eg, lat meg aldri verta til skammar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Fria meg ut og berga meg ved di rettferd, bøyg ditt øyra til meg og frels meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Ver meg eit berg til å bu på, der eg alltid kann koma! Du hev påbode frelsa for meg, for du er mitt fjell og mi festning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Min Gud, berga meg frå handi til den ugudlege, frå hans neve som er urettferdig og gjer valdsverk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'For du er den eg vonar på, Herre, Herre, den eg set mi lit til alt frå ungdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'På deg hev eg studt meg alt frå morsfanget; du er den som drog meg ut or morslivet, um deg vil eg alltid syngja min lovsong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Som eit under hev eg vore for mange; men du er mi sterke borg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Min munn er full av ditt lov, av di æra heile dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Kasta meg ikkje burt i min alderdom, forlat meg ikkje når mi kraft vert til inkjes!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'For mine fiendar hev sagt um meg, og dei som lurar på mi sjæl, legg råder i hop,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'og segjer: «Gud hev forlate honom; forfylg honom og tak honom, for det er ingen som bergar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Gud, ver ikkje langt frå meg! Min Gud, kom meg snart til hjelp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Lat deim som stend etter mitt liv, verta til skammar og ganga til grunnar! Lat deim som søkjer mi ulukka, verta klædde i spott og skam!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Men eg vil alltid venta, og stødt vil eg lova deg meir og meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Min munn skal fortelja um di rettferd, um di frelse all dagen, for eg veit ikkje tal på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Eg vil koma fram med Herrens, Herrens velduge verk, eg vil forkynna di rettferd, berre di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Gud, du hev lært meg upp alt frå ungdomen, og til dessa kunngjer eg dine undergjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Forlat meg då ikkje heller når eg vert gamall og grå, du Gud, til dess eg fær forkynna um din arm til ei onnor ætt, um di magt til kvar den som skal koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Og di rettferd, Gud, når upp til det høge, du Gud, som hev gjort store ting, kven er som du?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Du som hev late oss sjå mange trengslor og ulukkor, du vil gjera oss livande att og draga oss upp att or dypterne i jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Du vil lata meg veksa og vil venda um og trøysta meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'So vil eg prisa deg med harpespel, din truskap, min Gud! Eg vil syngja deg lov med cither, du Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Mine lippor skal fegnast når eg syng deg lov, og mi sjæl, som du hev løyst ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Ogso tunga mi skal heile dagen kveda ut di rettferd, for dei hev vorte til skam og spott, dei som søkjer mi ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Av Salomo. Gud, gjev kongen dine domar og kongssonen di rettferd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Han skal døma ditt folk med rettferd og dine armingar med rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Fjelli skal bera fred for folket, og like eins haugarne, ved rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Han skal døma armingarne i folket, han skal frelsa borni åt den fatige og knasa valdsmannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Dei skal ottast deg so lenge soli skin, og so lenge månen lyser frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Han skal koma ned som regn på nyslegen voll, lik ei regnskur som væter jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'I hans dagar skal den rettferdige bløma, og det skal vera mykje fred, alt til det ingen måne er meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Og han skal hava herredom frå hav til hav, og frå elvi til endarne av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Dei som bur i øydemarki, skal bøygja seg for honom, og hans fiendar skal slikka mold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Kongarne frå Tarsis og øyarne skal bera fram gåvor, kongarne frå Sjeba og Seba skal koma med skatt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Alle kongar skal fall ned for honom, alle folkeslag skal tena honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'For han skal frelsa den fatige som ropar, og armingen som ingen hjelpar hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Han skal spara vesalmannen og den fatige, og sjælerne åt dei fatige skal han frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Frå trykk og vald skal han løysa deira sjæl, og dyrt skal blodet deira vera i hans augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Og han skal liva, og Sjeba-gull skal han gjeva honom, og han skal alltid beda for honom, heile dagen skal han lova honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Det skal vera ei mengd med korn i landet, på fjelltopparne, grøda skal susa som Libanonskogen, og folk blømer fram i byarne som gras på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Hans namn skal vara i all æva, so lenge soli skin, skal hans namn setja nye renningar, og ved honom skal dei velsigna seg, alle heidningefolk skal prisa honom sæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Lova vere Gud Herren, Israels Gud, han, den einaste som gjer under!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Og lova vere hans herlege namn i all æva! og all jordi verte full av hans æra! Amen, amen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Ende på bønerne av David, son åt Isai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Ein salme av Asaf. Ja, Gud er god mot Israel, mot deim som hev eit reint hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Men eg - mine føter hadde so nær snåva, det skilde lite at mine stig hadde skride ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'For eg harmast på dei ovmodige, når eg såg at det gjekk dei gudlause godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'For dei er frie frå verk til dei døyr, og deira kropp er feit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Dei veit ikkje av naud som andre folk, og dei vert ikkje plåga som andre menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Difor er ovmod deira halsprydnad, vald sveiper seg um deim som eit klædeplagg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Augo deira glytter ut or feitt, deira hjartans tankar bryt fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Dei spottar og talar i vondskap um valdsverk, frå høgdi talar dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Dei set sin munn til himmelen, og deira tunga fer fram yver jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Difor vendar deira folk seg til, og mykje vatn syg dei inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Og dei segjer: «Korleis skulde Gud vita noko? Finst det vel kunnskap hjå den Høgste?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Sjå desse er ugudlege, og æveleg trygge veks dei i magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Ja, fåfengt hev eg reinsa mitt hjarta og tvege mine hender i uskyld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'eg vart like vel plåga heile dagen, og kvar morgon fekk eg tukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Dersom eg hadde sagt: «Eg vil tala soleis,» då hadde eg vore utru mot ætti av dine born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Og når eg tenkte etter korleis eg skulda skyna dette, vart det for mødesamt var det for meg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, '- til dess eg gjekk inn i Guds heilagdomar og agta på deira ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Ja, på hålka set du deim; du let deim falla radt til grunns.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kor dei vart øydelagde i ein augneblink! Dei gjekk under, fekk ein skræmeleg ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Som ein vanvyrder ein draum når ein vaknar, soleis vanvyrder du, Herre, deira bilæte når du vert vaken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Når mitt hjarta var beiskt, og eg fekk styng i nyro,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'då var eg uvitug og skyna inkje, eit fe var eg imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Men eg er alltid hjå deg, du hev gripe mi høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Du vil leida meg med di råd og sidan tek du meg upp til æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kven hev eg i himmelen? Og når du er min, hev eg ingen hug til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Um mitt kjøt og hjarta vert til inkjes, so er Gud æveleg mitt hjartans berg og min deil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'For sjå, dei som er langt burte frå deg, skal ganga til grunnar; du tyner alle som i hor gjeng frå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Men for meg er det godt å halda meg nær til Gud, eg set mi lit til Herren, Herren, at eg må fortelja alle dine gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Ein song til lærdom av Asaf. Kvifor hev du, Gud, støytt oss burt til æveleg tid? Kvifor ryk din vreide mot den hjord du beiter?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Kom i hug din lyd som du fekk deg i fordoms tid, som du løyste ut til å vera din arvs ætt, Sions fjell der du bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Stig upp til dei ævelege øydehus! Alt hev fienden brote sund i heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Dine motstandarar hev bura midt i ditt samlingshus, dei hev sett sine merke upp til merke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Det såg ut som når ein lyfter øksar og høgg i tettvakse tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Og no, alt som fanst av utskurd, det slo dei sund med øks og hamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Dei hev sett eld på heilagdomen din, reint til grunnen hev dei vanhelga bustaden for ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Dei hev sagt i sitt hjarta: «Lat oss tyna deim alle i hop!» Dei hev brent upp alle Guds samlingshus i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Våre merke ser me ikkje, det finst ingen profet lenger, og ingen hjå oss som veit kor lenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Gud, kor lenge skal motstandaren spotta, fienden vanvyrda ditt namn æveleg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Kvifor dreg du di hand, di høgre hand, attende? Tak henne ut or barmen, og øydelegg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Gud er då min konge frå gamall tid, som skaper frelsa midt på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Du skilde havet ved din styrke, du krasa hovudi til drakarne på vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Du slo sund hovudi til Livjatan, du gjorde honom til føda for folk i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du let kjelda og bekk renna fram, du turka ut årgangs elvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Deg høyrer dagen til, deg høyrer og natti til, du hev laga ljosi og soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du hev sett fast alle grensor på jordi, sumar og vinter - du hev laga deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Kom i hug dette: Fiendar hev spotta Herren, og eit dårlegt folk hev vanvyrdt ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Gjev ikkje turtelduva di til den mordfuse flokken, gløym ikkje æveleg flokken av dine armingar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Sjå til di pakt! for løyndekrokarne i landet er fulle av valds-bøle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Lat ikkje den nedtrykte snu um med skam, lat den arme og fatige lova ditt namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Statt upp, Gud! før di sak! Kom i hug at du vert spotta av dåren heile dagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Gløym ikkje røysti åt dine fiendar, ståket frå dine motstandarar som alltid stig upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Til songmeisteren; «tyn ikkje»; ein salme av Asaf, ein song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Me prisar deg, Gud, me prisar, og nær er ditt namn, dei fortel um dine under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'For «eg vil gripa den fastsette tid, eg, med rettferd vil eg døma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Jordi og alle som bur der, kjem i røra, eg hev sett hennar stolpar fast.» Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Eg segjer til skrøytarane: «Skrøyt ikkje!» og til dei ugudlege: «Reis ikkje horn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Reis ikkje hornet dykkar høgt, gjer ikkje nakke og tala agelaust!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'For ikkje frå aust eller frå vest, og ikkje heller frå fjell-øydemarki -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'men Gud er den som dømer, den eine nedrar han, hin høgrar han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'For eit staup er i Herrens hand med skumande vin, det er fullt av kryddevin, og han skjenkjer av det, ja, bermen skal dei suga til seg og drikka, alle dei ugudlege på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Men eg vil forkynna det æveleg, eg vil lovsyngja Jakobs Gud. Og alle horni på dei ugudlege vil eg hogga av; horni på den rettferdige skal reisa seg høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Til songmeisteren, med strengleik; ein salme av Asaf, ein song.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Gud er kjend i Juda, i Israel er hans namn stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Han bygde si hytta i Salem og sin bustad på Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Der braut han sund ljoni frå bogen, skjold og sverd og ufred. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Strålande er du, herleg framfor rans-bergi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Dei hjarte-sterke menner hev vorte plundra, dei søv sin svevn, og ingen av kjemporne fann sine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ved ditt trugsmål, Jakobs Gud, vart både vogn og hest djupt svævde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du - skræmeleg er du, og kven kann standa for di åsyn når du vert vreid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Frå himmelen let du høyrast dom; jordi ræddast og vart still');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'då Gud stod upp til dom, til å frelsa alle spaklyndte på jordi. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'For manne-harm må prisa deg, med endå større harm gyrder du deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Gjer lovnad og haldt det de lova til Herren, dykkar Gud! Alle kring honom skal føra gåvor til den skræmelege. Han staggar stormodet hjå hovdingar, han er skræmeleg for kongarne på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Til songmeisteren, for Jedutun; ein salme av Asaf.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Eg ropar til Gud, og eg vil skrika; eg ropar til Gud, og han vil venda øyra til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Den Dagen eg er i naud, søkjer eg Herren, um natti retter eg ut handi, og ho vert ikkje trøytt, mi sjæl vil ikkje lata seg trøysta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Eg vil koma Gud i hug og sukka, eg vil tenkja etter, og mi ånd vanmegtast. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Du held augo mine vakande, eg er uroleg og talar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Eg tenkjer på fordoms dagar, på lengst framfarne år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Eg vil koma i hug min strengleik um natti, i mitt hjarta vil eg grunda, og mi ånd vil ransaka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Vil Herren æveleg støyta burt? vil han ikkje lenger visa nåde?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Er det for all tid ute med hans miskunn? Hev hans lovnad vorte upp i inkje frå ætt til ætt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Hev Gud gløymt å vera nådig? Eller hev han i vreide stengt for sin godhug? Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Eg segjer: Dette er mi plåga, det er år frå høgre handi til den Høgste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Eg vil forkynna Herrens gjerningar, for eg vil minnast dine under frå fordoms tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Og eg vil tenkja etter alt ditt verk, og på dine store gjerningar vil eg grunda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Gud, i heilagdom er din veg, kven er ein gud, stor som Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du er den Gud som gjer under; du hev kunngjort din styrke millom folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Du hev løyst ditt folk ut med velde, borni åt Jakob og Josef. Sela');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Vatni såg deg, Gud, vatni såg deg og bivra, ja, djupi skalv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Skyerne gav vatn, himmelen dunde, ja, dine piler flaug ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Di tora dunde i kvervelstormen, eldingar lyste upp jordriket, jordi skalv og riste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'I havet gjekk din veg, og dine stigar gjenom store vatn, og dine fotspor vart ikkje kjende. Du førde ditt folk som ei hjord ved handi åt Moses og Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Ein song til lærdom av Asaf. Lyd, mitt folk, på læra mi, legg øyra til det munnen min talar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Eg vil opna min munn med fyndord, eg vil lata gåtor frå gamall tid strøyma ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Det me hev høyrt og veit, og det våre feder hev fortalt oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'det vil me ikkje dylja for deira born, men fortelja Herrens pris for den komande ætti, og hans styrke og hans under, som han hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Han hev sett upp eit vitnemål i Jakob, og ei lov hev han lagt i Israel, som han baud våre feder, til å kunngjera deim for borni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'so den komande ætti, dei born som skulde verta fødde, kunde kjenna deim, at dei kunde koma fram og fortelja um deim til sine born,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'og setja si von til Gud, og ikkje gløyma Guds verk, men taka vare på hans bodord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'og ikkje vera som deira feder, ei tver og tråssug ætt, ei ætt som ikkje gjorde sitt hjarta fast, og som i si ånd ikkje var trufast mot Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efraims born, dei væpna bogeskyttarar, dei snudde på stridsdagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Dei heldt ikkje Guds pakt og vilde ikkje ferdast i hans lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Og dei gløymde hans storverk og hans under som han hadde synt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'For deira feder hadde han gjort under i Egyptarlandet på Soans mark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Han kløyvde havet og let deim ganga igjenom, og let vatnet standa som ein haug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Og han leidde deim med skyi um dagen, og heile natti ved elds ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Han kløyvde berg i øydemarki og let deim drikka som av store vatsdjup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Og han let bekkjer koma or fjellet og fekk vatn til å renna ned som elvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Men dei heldt endå på og synda imot honom, og var tråssuge mot den Høgste i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Og dei freista Gud i sitt hjarta, so dei kravde mat for si lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Og dei tala imot Gud, dei sagde: «Kann vel Gud duka bord i øydemarki?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Sjå, han slo i berg, so vatn rann ut, og bekkjer fløymde. Tru han og kann gjeva brød, eller koma med kjøt til sitt folk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Difor, då Herren høyrde det, vart han harm, og eld loga upp mot Jakob, og vreide reiste seg mot Israel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'for dei trudde ikkje på Gud og leit ikkje på hans frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Og han gav skyerne ovantil, og himmelportarne let han upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Og han let manna regna yver deim til føda, og himmelkorn gav han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Englebrød fekk menneskje eta, nista sende han deim til mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Han let austanvinden fara ut i himmelen, og han førde sunnanvinden fram ved si magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Og han let kjøt regna yver deim som dust, og fljugande fuglar som havsens sand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'og han let deim falla ned midt i deira læger, kringum deira bustader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Og dei åt og vart ovleg mette, og det dei hadde hug på, let han deim få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Dei var ikkje komne burt frå si lyst, endå hadde dei maten i munnen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'då steig Guds vreide upp imot deim, og han drap deira sterke menner hjå deim, og Israels ungdomar slo han ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Med alt dette synda dei endå, og dei trudde ikkje på hans under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Og han let deira dagar kverva i fåfengd, og deira år i rædsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Når han slo deim ned, då spurde dei etter honom, og vende um og søkte Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'og kom i hug at Gud var deira berg og den høgste Gud var deira atterløysar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Men dei gjølte for honom med sin munn, og laug for honom med si tunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Og deira hjarta hekk ikkje fast ved honom, og dei var ikkje true mot hans pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Men han er miskunnsam, han forlet skuld og tyner ikkje, og mange gonger let han sin vreide venda um, og han vakte ikkje heile sin harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Og han kom i hug at dei var kjøt, ein andepust som kverv og ikkje kjem att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kor ofte dei tråssa honom i øydemarki og gjorde honom sorg i audni!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Og dei freista atter Gud og krenkte Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Dei kom ikkje handi hans i hug, eller den dagen då han fria deim frå fienden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'då han gjorde sine teikn i Egyptarland, og sine undergjerningar på Soans mark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Og han gjorde deira elvar til blod, og sine rennande vatn kunde dei ikkje drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Han sende imot deim flugesvermar som åt deim upp, og froskar som tynte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Og han gav deira grøda til gnagaren og deira arbeid til grashoppen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Han slo deira vintre ned med hagl og deira morbærtre med haglsteinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Og han gav deira fe til haglet og deira hjorder til eldingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Han sende på deim sin brennande vreide, sinne og harm og trengsla, ei sending av uferds-englar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Han braut veg for sin vreide, han sparde ikkje deira sjæl for dauden, og deira liv gav han til sotti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Og han slo alle fyrstefødde i Egyptarland, fyrstegrøda av dei sterke i Khams tjeld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Og han let sitt folk fara av stad som sauer, og førde deim som ei hjord i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Og han leidde deim trygt, og dei ræddast ikkje, men havet løynde deira fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Og han førde deim til sitt heilage landmerke, det fjell som hans høgre hand hadde vunne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Og han dreiv ut heidningar for deim, og let deira land falla til deim som arv, og let Israels ætter bu i deira tjeld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Men dei freista Gud, den Høgste, og tråssa honom, og hans vitnemål agta dei ikkje på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Og dei veik av og var utrugne som deira feder, dei vende um som ein veik boge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Dei harma honom med sine haugar og eggja honom med sine avgudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Gud høyrde det og vart vreid, og han vart svært leid av Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Og han gjekk burt frå sin bustad i Silo, det tjeld han hadde slege upp millom menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Og han let sin styrke verta førd burt som fange, og gav si æra i fiendehand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Og han gav sitt folk til sverdet, og på sin arv harmast han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Eld åt deira unge menner, og deira møyar fekk ingen bruresong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Deira prestar fall for sverdet, og deira enkjor fekk ikkje syrgja');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Då vakna Herren som ein sovande, som ei kjempa frå rus av vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Og han slo sine fiendar attende, og han førde yver deim æveleg skam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Og han støytte burt Josefs tjeld, og Efraims ætt valde han ikkje ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Men han valde Judas ætt, Sions fjell som han elska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Og han bygde sin heilagdom som høge fjell, liksom jordi som han hev grunnfest til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Og han valde ut David, sin tenar, og tok honom frå sauegrindarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Han førde honom frå lambsauerne som han fylgde, til å gjæta Jakob, sitt folk, og Israel, sin arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Og han gjætte deim etter sitt ærlege hjarta, og med si kloke hand leidde han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Ein salme av Asaf. Gud, heidningar er komen inn i arven din, dei hev gjort ditt heilage tempel ureint, dei hev gjort Jerusalem til steinhaugar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Dei hev gjeve liki av dine tenarar til føda for fuglarne under himmelen, kjøtet av dine trugne til landsens villdyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Dei hev rent ut deira blod som vatn kringum Jerusalem, og det var ingen som jorda deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Me hev vorte til spott for våre grannar, til hæding og lått for deim som bur ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Kor lenge, Herre, vil du æveleg vera vreid? Kor lenge skal din brennhug loga som eld?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Renn din harme ut yver heidningarne som ikkje kjenner deg, og yver dei kongerike som ikkje kallar på ditt namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'For dei hev ete upp Jakob, og hans bustad hev dei øydelagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Kom ikkje i hug mot oss synderne åt våre forfeder, lat di miskunn snart koma imot oss, for me er svært utmødde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Hjelp oss, du vår Frelse-Gud, for ditt namns æra skuld! og frels oss og forlat oss våre synder for ditt namn skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Kvifor skal heidningarne segja: «Kvar er deira Gud?» Lat det for våre augo verta kjent millom heidningarne, at det kjem hemn yver det utrende blodet av dine tenarar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Lat sukken frå den bundne koma for di åsyn! So sterk som armen din er, spar daudens born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Gjev våre grannar sjufald att i deira fang den spott som dei hev spotta deg med, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Og me, ditt folk og den hjord du beiter, me vil lova deg æveleg, frå ætt til ætt vil me kunngjera din pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Til songmeisteren, etter «Liljor»; eit vitnemål av Asaf, ein salme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Du Israels hyrding, vend øyra til! du som fører Josef som ei hjord, du som tronar yver kerubarne, syn deg herleg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Vekk upp ditt velde for Efraim og Benjamin og Manasse, og kom oss til hjelp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Gud, reis oss upp att, og lat ditt andlit lysa, so me vert frelste!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Herre Gud, Allhers drott! Kor lenge du frøser av harm, endå folket ditt bed!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du gav deim tårebrød til å eta og tåror til å drikka i fullt mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Du sette oss til eit trættemål for våre grannar, og våre fiendar spottar seg imillom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Gud, allhers drott, reis oss upp att og lat ditt andlit lysa, so me vert frelste!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Eit vintre flutte du frå Egyptarland, du dreiv heidningar ut og planta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Du rudde rom for det, og det feste rot og fyllte landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Fjell vart løynde av skuggen frå det, og Guds cedrar av greinerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Det strekte sine greiner ut til havet, og sine renningar burt imot elvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Kvi hev du rive ned gardarne ikring det, so alle som gjeng framum på vegen, plukkar av det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Svinet frå skogen gneg på det og dyri på marki beitar i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Gud, allhers drott, vend um att! skoda ned frå himmelen og sjå og vitja ditt vintre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'og verna um det som di høgre hand hev planta, og um den son du hev valt deg ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Det er brent med eld, det er avhogge, for trugsl frå ditt andlit gjeng dei til grunnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Haldt di hand yver mannen ved di høgre hand, yver menneskjesonen som du hev valt deg ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'so vil me ikkje vika frå deg! Gjer oss levande att, so vil me kalla på ditt namn! Herre Gud, allhers drott, reis oss upp att, og lat ditt andlit lysa, so me vert frelste!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Til songmeisteren, etter Gittit; av Asaf.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Syng med fagnad for Gud, vår styrke! Ropa med gleda for Jakobs Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Set i med song, og lat trumma høyrast, den væne cither med harpa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Blås i lur ved nymåne, ved fullmåne på vår høgtidsdag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'For det er ei lov for Israel, ein rett for Jakobs Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Han sette det til eit vitnemål i Josef då han drog ut gjenom Egyptarland. - Eit mål som eg ikkje kjende, høyrde eg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '«Eg løyste hans oksl frå byrdi, hans hender vart frie frå berekorgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'I trengsla ropa du, og eg fria deg ut, eg svara deg, løynd i toresky, eg prøvde deg ved Meribavatni. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Høyr, mitt folk, so vil eg vitna for deg! Israel, gjev du vilde høyra på meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Det skal ikkje finnast nokon annan gud hjå deg, og du skal ikkje tilbeda ein framand gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Eg er Herren, din Gud, som førde deg upp frå Egyptarland, lat munnen vidt upp, at eg kann fylla honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Men folket mitt høyrde ikkje på mi røyst, og Israel vilde ikkje lyda meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'So let eg deim fara med sitt harde hjarta, at dei kunde ganga i sine eigne råder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Gjev mitt folk vilde høyra på meg, gjev Israel vilde vandra på mine vegar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Snart skulde eg då bøygja deira fiendar, eg skulde venda mi hand imot deira motstandarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Dei som hatar Herren, skulde høla honom, og deira tid skulde vara æveleg. Og eg skulde føda honom med den beste kveite, og frå berget skulde eg metta deg med honning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Ein salme av Asaf. Gud stend i Guds samling; midt imillom gudar held han dom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '«Kor lenge vil de døma rangt og halda med dei ugudlege? Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Døm den ringe og farlause! Lat armingen og den fatige få sin rett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Berga den ringe og fatige, frels han frå handi åt dei ugudlege!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Dei veit inkje og skynar inkje, dei ferdast i myrker; alle grunnvollar til jordi ruggar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Eg hev sagt: «De er gudar, søner til den Høgste er de alle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Men sanneleg, som menneskje skal de døy, og som ein av hovdingarne skal de falla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Statt upp, Gud, haldt dom yver jordi! For du eig alle heidningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ein song, ein salme av Asaf.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Gud, teg ikkje! haldt deg ikkje still og roleg, Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'For sjå, dine fiendar bråkar, og dei som hatar deg, lyfter hovudet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Mot ditt folk legg dei sløge råder, og dei samråder seg mot deim som du tek vare på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Dei segjer: «Kom, lat oss rydja deim ut, so dei ikkje lenger er eit folk! og Israels namn skal ingen meir koma i hug!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'For dei hev av hjarta samrådt seg, mot deg gjeng dei i pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Edoms tjeld og ismaelitarne, Moab og hagarenarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Gebal og Ammon og Amalek, Filistarland med deim som bur i Tyrus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Ogso Assur hev gjenge i lag med deim, han låner sin arm til Lots søner. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Gjer med deim som med Midjan! som med Sisera, som med Jabin ved Kisons bekk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Dei vart øydelagde ved En-Dor, dei vart til møk på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Far med deim, deira fremste menner, som med Oreb og Ze’eb, og med alle deira hovdingar som med Zebah og Salmunna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'deim som segjer: «Lat oss hertaka Guds bustader!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Min Gud, gjer deim som ein dustkvervel, som agner for vinden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Lik ein eld som brenn ein skog, lik ein loge som set eld på fjell,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'soleis forfylgje du deim med din storm og skræme deim med ditt uver!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Fyll deira andlit med skam, at dei må søkja ditt namn, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Lat deim skjemmast og skræmast æveleg og alltid, lat dei verta skjemde og ganga til grunnar! Og lat deim få vita, at einast du hev namnet Herre, den Høgste yver heile jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Til songmeisteren, etter Gittit; av Korahs born, ein salme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Kor elskelege dine bustader er, Herre, allhers drott!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Mi sjæl lengtar, ja naudstundar etter Herrens fyregardar; mitt hjarta og mitt kjøt ropar av fagnad til den livande Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Sporven hev og funne seg eit hus, og svala eit reir der ho hev lagt sine ungar - dine altar, Herre, allhers drott, min konge og min Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Sæle er dei som bur i ditt hus! dei skal alltid lova deg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Sæl er den mann som hev sin styrke i deg, dei som hev hug til å fara dei jamne vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Når dei fer gjenom tåredalen, gjer dei honom til ein kjeldevang, ja, tidlegt regn legg velsigning yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Dei gjeng frå kraft til kraft, dei stig fram for Gud på Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Herre Gud, allhers drott, høyr mi bøn! Vend øyra til, Jakobs Gud! Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Gud, vår skjold, sjå hit og skoda andlitet til honom du hev salva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'For ein dag i dine fyregardar er betre enn tusund andre; eg vil heller standa ved dørstokken i min Guds hus enn bu i tjeldi til gudløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'For Gud Herren er sol og skjold, nåde og ære gjev Herren, han held ikkje undan noko godt frå deim som ferdast i uskyld. Herre, allhers drott, sæl er den mann som set si lit til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Til songmeisteren; av Korahs born, ein salme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Herre, du hev vore nådig mot landet ditt, du hev gjort vending i Jakobs fangeskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Du hev teke burt ditt folks skuld, du hev breidt yver alle deira synder. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Du hev teke burt all din harm, du hev vendt deg frå din brennande vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Vend um til oss, vår Frelse-Gud, og gjer ende på din uvilje imot oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Vil du æveleg vera vreid på oss? Vil du lata din vreide vara frå ætt til ætt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Vil ikkje du gjera oss livande att, so ditt folk kann gleda seg i deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Herre, lat oss sjå di miskunn, og gjev oss di frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Eg vil høyra kva Gud Herren talar, for han talar fred til sitt folk og til sine trugne - berre dei ikkje vender um att til dårskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Ja, hans frelsa er nær deim som ottast honom, so herlegdom skal bu i vårt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Miskunn og truskap skal møta kvarandre, rettferd og fred kyssa kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Truskap skal renna upp av jordi, og rettferd skoda ned frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Herren skal og gjeva det som gode, og vårt land skal gjeva si grøda. Rettferd skal ganga fyre honom og gjera hans fotspor til sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Ei bøn av David. Herre, bøyg ditt øyra, svara meg! for arm og fatig er eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Tak vare på mi sjæl, for eg er gudleg. Frels din tenar, du min Gud, han som lit på deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Ver meg nådig, Herre! For til deg ropar eg heile dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Gled din tenars sjæl! For til deg, Herre, lyfter eg mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'For du, Herre, er god og viljug til forlating, og rik på miskunn for alle deim som kallar på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Herre, vend øyra til mi bøn, og merka på mi bønerøyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Den dag eg er i naud, ropar eg på deg, for du svarar meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Ingen er som du millom gudarne, Herre, og ingi verk er som dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Alle heidningar som du hev skapt, skal koma og tilbeda for di åsyn, Herre, og dei skal æra ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'For du er stor og gjer undergjerningar, du er Gud og ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Lær meg, Herre, din veg, eg vil ferdast i di sanning; sameina mitt hjarta til å ottast ditt namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Eg vil prisa deg, Herre min Gud, av alt mitt hjarta, og eg vil æra namnet ditt æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'For di miskunn er stor yver meg, og du hev frelst mi sjæl frå den djupe helheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Gud, stormodige hev reist seg imot meg, og ein flokk av valdsmenner stend etter livet mitt, og dei hev ikkje deg for auga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Men du, Herre, er ein miskunnsam og nådig Gud, langmodig og rik på miskunn og truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Vend deg til meg og ver meg nådig, gjev din tenar styrken din, og frels son åt di tenestkvinna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Gjer eit teikn med meg til det gode, at dei som hatar meg, må sjå det og skjemmast, av di du, Herre, hev hjelpt meg og trøysta meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Av Korahs born; ein salme, ein song. Det som han hev grunnfest på dei heilage fjelli,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Sions portar elskar Herren mest av alle Jakobs bustader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Herlege ting er sagde um deg, du Guds by. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '«Eg vil nemna Rahab og Babel millom deim som kjenner meg; sjå Filistaren, Tyrus og Kusj: Denne er fødd der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Og um Sion skal det verta sagt: «Kvar ein er fødd der», og han, den Høgste, gjer det fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Herren skal telja soleis, når folki vert uppskrivne: «Denne er fødd der.» Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Og dei som syng og dei som dansar, skal segja: «Alle mine kjeldor er i deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ein song, ein salme av Korahs born. Til songmeisteren; etter Mahalat leannot; ein song til lærdom av ezrahiten Heman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Herre, min Frelse-Gud! Dag og natt ropar eg framfyre deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Lat mi bøn koma for di åsyn, bøyg ditt øyra til mitt klagerop!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'For mi sjæl er mett av ulukkor, og mitt liv er kome nær til helheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Eg er rekna lik deim som fer ned i gravi, eg er som ein mann utan livskraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Eg er forlaten millom dei daude, som dei ihelslegne som ligg i gravi, som du ikkje meir kjem i hug, då dei er avskorne frå di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Du hev lagt meg i den djupe hola, i myrkrer, i ovdjup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Din harm kvilar tungt på meg, og med alle dine bylgjor trengjer du meg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Du hev drive mine kjenningar langt burt frå meg, du hev gjort meg til ein styggedom for deim, eg er innestengd og kann ikkje koma ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Mitt auga hev vanmegtast av liding, eg hev kalla på deg kvar dag, Herre, eg hev rett ut mine hender til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Gjer du vel under for dei daude? eller vil skuggar stand upp og lova deg? Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Tru dei i gravi fortel um di miskunn, og um di truskap i avgrunnen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Vert dine under kjende i myrkret, og di rettferd i gløymelandet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Men eg ropar til deg, Herre, og um morgonen kjem mi bøn imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Kvifor, Herre, støyter du burt mi sjæl? Kvifor løyner du ditt andlit for meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Arm er eg og døyande frå ungdomen av, eg ber dine rædslor, eg lyt gjeva meg yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Logarne av din harm hev gjenge yver meg, dine skræmor hev gjort meg til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Dei hev ringa seg um meg som vatn all dagen, dei hev i samlag kringsett meg. Du hev drive langt burt frå meg ven og næste, mine kjenningar er myrkret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Ein salme til lærdom av ezrahiten Etan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Um Herrens miskunns verk vil eg æveleg syngja frå ætt til ætt vil eg med min munn forkynna hans truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'For eg segjer: \'veleg vert miskunn uppbygd, i himmelen gjer du din truskap fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '«Eg hev gjort ei pakt med min utvalde, eg hev svore for David, tenaren min:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, '«\'veleg vil eg grunnfesta ditt avkjøme, og eg vil byggja din kongsstol frå ætt til ætt.»» Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Og himmelen prisar di undergjerning, Herre, og din truskap fær pris i samlingi av dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'For kven i dei høge skyer likjest Herren? Kven er lik Herren millom gudesøner?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Ein Gud som er ovskræmeleg i løynderådet til dei heilage, og til rædsla for alle som er ikring honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Herre, allhers drott, kven er sterk som du, Herre? Og din truskap er kringum deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du råder yver havsens ovmod; når bylgjorne i det reiser seg, stiller du deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Du hev slege Rahab sund som ein ihelslegen, med din sterke arm hev du spreidt dine fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Himmelen er din, og jordi er di; jordriket og alt som er i det, hev du grunnlagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Nord og sud hev du skapt; Tabor og Hermon fegnast i ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Du hev ein arm med velde; sterk er di hand, høg er di høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Rettferd og rett er grunnvoll for din kongsstol; miskunn og truskap gjeng fyre di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Sælt er det folk som kjenner til glederop; i ljoset frå ditt andlit skal dei ferdast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'I ditt namn fegnast dei all dagen, og ved di rettferd vert dei upphøgde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'For du er prydnaden i deira styrke, og ved din godhug lyfter du upp vårt horn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'For Herren høyrer vår skjold til, og vår konge til Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Den gong tala du i ei syn til dine trugne og sagde: «Eg hev lagt hjelp i handi på ein veldug, eg hev upphøgt ein ungdom av folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Eg hev funne David, tenaren min, med min heilage olje hev eg salva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Mi hand skal alltid vera med honom, og min arm skal styrkja honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Fienden skal ikkje trengja honom, og den urettferdige skal ikkje kua honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Men eg vil krasa hans motstandarar for hans åsyn, og slå deim som hatar honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Og min truskap og mi miskunn skal vera med honom, og i mitt namn skal hans horn verta upplyft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Eg vil leggja hans hand på havet og hans høgre hand på elvarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Han skal ropa til meg: «Du er min far, min Gud og mitt frelse-fjell!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Og eg vil setja honom til den fyrstefødde, til den høgste av kongarne på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Mi miskunn imot honom vil eg æveleg halda ved lag, og mi pakt skal standa fast for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Og eg vil halda uppe hans avkjøme til æveleg tid, og hans kongsstol so lenge himmelen varer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Dersom hans born forlet mi lov og ikkje vandrar etter mine domar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'dersom dei bryt mine bodord og ikkje held mine fyresegner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'då vil eg heimsøkja deira misgjerd med ris og deira skuld med plågor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Men mi miskunn vil eg ikkje taka frå honom, og ikkje vil eg svika i min truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Eg vil ikkje brjota mi pakt og ikkje brigda ordi frå mine lippor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Eitt hev eg svore ved min heilagdom, sanneleg, for David vil eg ikkje ljuga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Hans avkjøme skal vera til æveleg tid, og hans kongsstol som soli for mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Som månen skal han standa æveleg, og vitnet i skyi er trufast.» Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Og du hev støytt burt og forsmått, du hev vorte harm på den du hev salva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Du hev rist av deg pakti med din tenar, du hev skjemt hans kruna og kasta henne på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Du hev brote ned alle murarne hans, du hev gjort hans festningar til grusdungar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Alle som fer fram på vegen, plundrar honom, han hev vorte til spott for grannarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Du hev upphøgt den høgre hand til hans motstandarar, du hev gjort alle hans fiendar glade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Du hev og late og hans sverdsegg vika, og hev ikkje halde honom uppe i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Du hev gjort ende på hans glans og kasta hans kongsstol til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Du hev korta av hans ungdoms dagar, du hev lagt skam yver honom. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Kor lenge, Herre, vil du løyna deg æveleg? Kor lenge skal din harm brenna som eld?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kom då i hug kor stutt mitt liv er, og kor forgjengelege du hev skapt alle menneskjeborn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kven fær vel liva og ikkje sjå dauden? Kven friar si sjæl frå helheims vald? Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Herre, kvar er dine nådegjerningar frå fordoms tid, som du med eid lova David i din truskap?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Herre, kom i hug den skam som ligg yver dine tenarar, at eg må bera i fanget alle dei mange folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'at dine fiendar spottar, Herre, at dei spottar hans fotspor som du hev salva. Lova vere Herren æveleg! Amen, amen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Ei bøn av gudsmannen Moses. Herre, du hev vore ei livd for oss frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Fyrr fjelli vart til, og du skapte jordi og heimen, ja frå æva og til æva er du Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Du let menneskja venda um til dust og segjer: «Vend um att, de menneskjeborn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'For tusund år er i dine augo som dagen i går når han lid, som ei vakt um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du riv deim burt som i flaum, dei vert som ein svevn, um morgonen er dei som groande graset;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'um morgonen blømer det og gror, um kvelden visnar det burt og turkast upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'For me hev forgjengest ved din vreide, og ved din harm er me burtskræmde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Du hev sett våre misgjerder for augo dine, vår løynde synd i ljoset frå di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'For alle våre dagar er framfarne i din vreide, me hev livt våre år til ende som ein sukk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Vår livstid, ho varer sytti år, og når der er mykje kraft, åtteti år, og jamvel det stoltaste er møda og fåfengd, for snart er det framfare, og me flaug burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Kven kjenner styrken i din vreide og din harm, soleis som ein bør ottast deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Å telja våre dagar, det lære du oss, at me kann få visdom i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Vend um, Herre! Kor lenge? Og lat det gjera deg vondt for tenarane dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Metta oss med di miskunn når morgonen renn, so vil me fegnast og gleda oss alle våre dagar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Gled oss etter dei dagar du hev bøygt oss, etter dei år me hev set ulukka!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Lat di gjerning syna seg for tenarane dine og din herlegdom yver deira born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Og Herren, vår Guds ynde vere yver oss, og det våre hender gjer, gjeve du framgang for oss, ja, det våre hender gjer, det gjeve du framgang!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Den som sit i gøymsla hjå den Høgste, den som bur i skuggen hjå den Allmegtige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'han segjer til Herren: «Mi livd og mi borg, min Gud som eg set mi lit til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'For han frelser deg frå snara til fuglefangaren, frå tynande sott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Med sine fjører løyner han deg, og under hans vengjer finn du livd; skjold og vern er hans truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Du skal ikkje ræddast for skræmsl um natti, for pil som flyg um dagen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'for pest som fer fram i myrker, for sott som tyner um middagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Um tusund fell attmed sida di, og ti tusund attmed di høgre hand, so skal det ikkje nå til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Du skal berre skoda det med augo dine, og sjå korleis dei ugudlege fær si løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, '«For du, Herre, er mi livd,» segjer du. Den Høgste hev du gjort til din bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Inkje vondt skal timast deg, og ingi plåga skal koma nær til ditt tjeld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'For han skal bjoda sine englar um deg, at dei skal vara deg på alle dine vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Dei skal bera deg på hender, so du ikkje skal støyta foten din på nokon stein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'På løva og eiterorm skal du treda, du skal trakka ned ungløvor og drakar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '«Av di han heng fast ved meg, vil eg fria honom ut; eg vil frelsa honom, av di han kjenner mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Han skal kalla på meg, og eg skal svara honom, eg er med honom i naud, eg vil fria honom ut og føra honom til æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Med eit langt liv vil eg metta honom og lata honom sjå mi frelsa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Ein salme, ein song til kviledagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Det er godt å prisa Herren, og å syngja ditt namn lov, du Høgste,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'å kunngjera di miskunn um morgonen og din truskap um næterne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'med tistrengs-cither og med harpa, med tankefullt spel på cither.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'For du hev gledt meg, Herre, med ditt verk, og eg vil fegnast yver det dine hender hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Kor store dine gjerningar er, Herre! Ovdjupe er dine tankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Ein uvitug mann kjenner ikkje til det, og ein dåre skynar det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Når dei ugudlege grønkar som gras, og alle illgjerningsmenner blømer, so er det til deira tyning til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Men du, Herre, er høg i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'For sjå dine fiendar, Herre - for sjå, dine fiendar skal forgangast, alle illgjerningsmenner vert spreidde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Du lyfter upp mitt horn som hornet til villuksen, frisk olje er rent yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Og mitt auga skal sjå med lyst på mine fiendar, og øyro mine høyra um dei vonde som stend upp imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Den rettferdige skal renna upp som palmetreet, som ceder på Libanon skal han veksa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Dei er planta i Herrens hus og skal grønka i Guds fyregardar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Endå i høg alder skyt dei friske renningar, dei er groande og grønkande til å forkynna at Herren er rettvis, han, mitt berg, og at det ingen urett er i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Herren er konge, han hev klædt seg i høgd; Herren hev klædt seg, han hev gyrdt seg med styrke, jordriket stend fast, det let seg ikkje rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Fast er din kongsstol frå fordoms tid, frå æva er du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Straumar hev lyft, Herre, straumar hev lyft si røyst, straumar lyfter upp sin dur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Men meir enn duren av dei store vatn, dei herlege, havbroti, er Herren herleg i det høge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Dine vitnemål er ovleg trufaste; heilagdom høver for huset ditt, Herre, so lenge som dagarne varer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Herre, du hemns Gud, du hemns Gud, syn deg i herlegdom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Statt upp, du domar yver jordi, lat dei ovmodige få lika for si gjerning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Kor lenge skal ugudlege, Herre, kor lenge skal ugudlege fegnast?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Dei gøyser or seg og fører skamlaus tale; dei skrøyter, alle ugjerningsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Ditt folk, Herre, krasar dei, og din arv plågar dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Enkja og den framande slær dei i hel, og dei myrder dei farlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Og dei segjer: «Herren ser ikkje, og Jakobs Gud merkar det ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Merka då, de uvituge i folket! Og de vitlause, når vil de taka til vitet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Han som hev sett inn øyra, skulde han ikkje høyra? Han som hev laga til auga, skulde han ikkje sjå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Han som tuktar heidningar, skulde han ikkje refsa, han som gjev menneski kunnskap?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Herren kjenner mannsens tankar, at dei er fåfengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Sæl er den mann som du, Herre, tuktar, og som du gjev lærdom or lovi di,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'til å gjeve honom ro for vonde dagar, til dess det vert grave ei grav for den ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'For ikkje støyter Herren burt sitt folk, og arven sin forlet han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'For domen skal venda um att til rettferd, og alle ærlege i hjarta skal halda med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kven stend upp for meg imot dei vonde? Kven stig fram for meg mot deim som gjer urett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Dersom ikkje Herren var mi hjelp, so vilde sjæli mi snart bu i stilla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Når eg segjer: «Foten min er ustød, då held di miskunn meg uppe, Herre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Når det kjem mange tunge tankar i mitt hjarta, då huggar dine trøystarord mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Er vel tynings-domstolen i samlag med deg, der dei lagar urett i hop til rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Dei flokkar seg i hop mot sjæli åt den rettferdige, og dei fordømer uskuldigt blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Då vert Herren ei borg for meg, og min Gud vert eit berg som eg flyr til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Og han let deira urett koma attende yver deim, og for deira vondskap skal han gjera ende på deim, ja, Herren, vår Gud, skal gjera ende på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Kom, lat oss fegnast for Herren, lat oss ropa av frygd for vårt frelse-berg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Lat oss stiga fram for hans åsyn med lovsong, lat oss syngja vår fagnad for honom i salmar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'For ein stor Gud er Herren og ein stor konge yver alle gudar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'han som i si hand hev det djupaste av jordi, og som eig topparne av fjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Han eig havet, for han hev skapt det, og turrlendet hev hans hender laga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Kom, lat oss falla ned og bøygja oss, lat oss bøygja kne for Herren, vår skapar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'For han er vår Gud, og me er det folk han føder, og den hjord som handi hans leider. Å, vilde de høyra på hans røyst i dag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Forherd ikkje dykkar hjarta som ved Meriba, som på Massa-dagen i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'der federne dykkar freista meg! Dei prøvde meg, endå dei hadde set mi gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'I fyrti år var eg leid av den ætti, og eg sagde: «Dei er eit folk med villfarande hjarta, og dei kjenner ikkje vegarne mine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'So svor eg i min vreide: «Sanneleg, dei skal ikkje koma inn til mi kvila.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Syng Herren ein ny song, syng for Herren, all jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Syng for Herren, lova hans namn, forkynn frå dag til dag hans frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Fortel millom heidningar hans æra, millom alle folkeslag hans under!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'For Herren er stor og mykje lovsungen, skræmeleg er han framfor alle gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'For alle gudar hjå folki er avgudar; men Herren hev gjort himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Høgd og herlegdom er for hans åsyn, styrke og prydnad i hans heilagdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Gjev Herren, de folke-ætter, gjev Herren æra og magt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Gjev Herren hans namns æra, tak gåvor med og kom i hans fyregardar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Tilbed Herren i heilagt skrud, skjelv for hans åsyn, all jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Seg millom heidningarne: «Herren er konge, og jordriket stend fast, det let seg ikkje rikka; han dømer folki med rettvisa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Himmelen glede seg, og jordi fagne seg, havet dure og alt som i det er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Marki frygde seg og alt det som på marki er! Då fegnast alle tre i skogen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'for Herrens åsyn; for han kjem, for han kjem til å døma jordi; han skal døma jordriket med rettferd og folki i sin truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Herren er konge; jordi fagne seg, mange øyar glede seg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Skyer og myrker er kringum honom, rettferd og rett er grunnvoll for hans kongsstol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Eld gjeng framfyre honom og brenner hans motstandarar rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Hans eldingar lyser upp heimen; jordi ser det og skjelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Bergi brånar som voks for Herren, for Herren yver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Himmelen forkynner hans rettferd, og alle folki hans æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Skjemde vert alle som dyrkar bilæte, som rosar seg av avgudar. Alle gudar tilbed honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sion høyrer det og gled seg, og Judas døtter fagnar seg for dine domar skuld, Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'For du, Herre, er den høgste yver heile jordi, du er høgt upphøgd yver alle gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'De som elskar Herren, hata det vonde! Han tek vare på sjælerne åt sine trugne, frå handi til dei ugudlege frelsar han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Ljos er utsått for den rettferdige, og gleda for dei ærlege i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Gled dykk, de rettferdige, i Herren! Syng lov for hans heilage namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Ein salme. Syng Herren ein ny song! For han hev gjort under, hans høgre hand hev hjelpt honom, og hans heilage arm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Herren hev kunngjort si frelsa, for augo på heidningarne hev han openberra si rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Han hev kome i hug si miskunn og sin truskap mot Israels hus; alle heimsens endar hev set frelsa frå vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Ropa med gleda for Herren, all jordi! Set i med fagnad og lovsong!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Syng lov for Herren med cither, med cither og med lovsongs røyst,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'med lurar og basunklang gjev fagnadrop for kongen, Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Havet dure og alt som i det er, heimen og alle som i heimen bur!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Elvarne klappe i hender, fjelli fagne seg med');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'for Herrens åsyn, for han kjem til å døma jordi, han skal døma jordriket med rettferd og folki med rettvisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Herren er konge, folki skjelv; han sit på kerubar, jordi ruggar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Herren er stor i Sion, og høg er han yver alle folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Dei skal prisa ditt namn, det store og skræmelege, heilag er han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Og i si magt elskar kongen det som rett er; du held rettvisa uppe, du hev gjort rett og rettferd i Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Høglova Herren, vår Gud, og fall ned for hans fotskammel! Heilag er han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moses og Aron var millom hans prestar, og Samuel millom deim som kalla på hans namn; dei ropa til Herren, og han svara deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'I ein skystolpe tala han til deim, dei heldt hans vitnemål og den lov han gav deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Herre vår Gud, du svara deim, du var deim ein Gud som tilgav deim, men og ein hemnar yver deira gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Høglova Herren, vår Gud! Og fall ned for hans heilage fjell! For heilag er Herren, vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein lovsalme. Ropa med frygd for Herren, all jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Ten Herren med gleda, kom fram for hans åsyn med fagnad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Vit at Herren er Gud, han hev skapt oss, og ikkje me, til sitt folk og til den hjord han føder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Kom inn i hans portar med takk, i hans fyregardar med lov, prisa honom, lova hans namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'For Herren er god, hans miskunn varer æveleg, og hans truskap frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Av David; ein salme. Um miskunn og rett vil eg syngja; deg, Herre, vil eg lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Eg vil agta på den ulastande veg - når kjem du til meg? Eg vil vandra i mitt hjartans uskyld i mitt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Ikkje set eg meg for augo nidingsverk, å gjera misgjerd hatar eg, slikt heng ikkje ved meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Eit rangsnutt hjarta skal vika frå meg, vondt vil eg ikkje vita av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Den som løynleg lastar sin næste, han vil eg tyna; deim med stolte augo og ovmodigt hjarta kann eg ikkje tola.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Mine augo ser på dei trugne i landet, for eg vil dei skal bu hjå meg; den som vandrar på ulastande veg, han skal tena meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'I mitt hus skal ingen få bu som fer med svik; den som talar lygn, skal ikkje standa for augo mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Kvar morgon vil eg tyna alle ugudlege i landet, so eg kann rydja ut or Herrens by alle ugjerningsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Bøn av ein arming, når han vanmegtast og let sitt klagemål strøyma fram for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Herre, høyr mi bøn, og lat mitt rop koma fram til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Løyn ikkje ditt andlit for meg den dagen eg er i naud! Bøyg ditt øyra til meg! Den dagen eg ropar, svara meg snart!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'For dagarne mine hev fare burt som ein røyk, og mine bein er som glødde i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mitt hjarta er solstukke og visnar som gras, for eg hev gløymt å eta brødet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'For mi høgmælte stynjing heng beini fast ved kjøtet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Eg likjest pelikanen i øydemarki, eg er som ula på aude stader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Eg lyt vaka og vera som ein einsleg fugl på taket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Heile dagen spottar mine fiendar meg, dei som reint er ville mot meg, sver ved meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'For eg et oska som brød, og drykken min blandar eg med gråt');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'for din vreide og din harm skuld, for du hev teke meg upp og kasta meg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mine dagar er som ein skugge når han lengjest, og eg visnar som gras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Men du, Herre, sit i all æva, og ditt minne varer frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Du vil standa upp, du vil miskunna Sion, for det er tid til å vera nådig mot henne, ja, timen er komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'For dine tenarar hev godhug for steinarne hennar, og dei ynkast yver hennar grus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Og heidningar skal ottast Herrens namn, og alle kongar på jordi di æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'For Herren hev bygt upp att Sion, han hev synt seg i si æra;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'han hev vendt seg til bøni frå dei hjelpelause, og han hev ikkje vanvyrdt deira bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Dette skal verta uppskrive for den komande ætti, og det folket som vert skapt, skal lova Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'for han hev set ned frå si heilage høgd, Herren hev frå himmelen skoda på jordi');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'og vil høyra sukken frå den bundne og løysa ut daudens born,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'so dei i Sion skal forkynna Herrens namn og hans pris i Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'når folkeslag kjem i hop og kongerike til å tena Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Han hev bøygt mi kraft på vegen, han hev korta av mine dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Eg segjer: Min Gud, tak meg ikkje burt midt i mine dagar! Frå ætt til ætt varer dine år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Fordom grunnfeste du jordi, og himmelen er verk av dine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Dei skal forgangast, men du stend; alle skal dei eldast som eit klæde, som ein klædnad skifter du deim, og dei vert umskifte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'men du er den same, og dine år tek aldri ende. Borni åt dine tenarar skal bu i ro, og deira avkjøme skal standa trygt for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Av David. Lova Herren, mi sjæl, og alt som i meg er, love hans heilage hamn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Lova Herren, mi sjæl, og gløym ikkje alle hans velgjerningar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Han som tilgjev all di skuld, han som lækjer alle dine brester,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'han som løyser ditt liv frå gravi, han som kryner deg med nåde og miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'han som mettar din prydnad med godt, so du vert ung att som ørnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Herren gjer rettferdsverk og rett mot alle som er under trykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Han kunngjorde sine vegar for Moses, sine gjerningar for Israels born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Miskunnsam og nådig er Herren, langmodig og rik på miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Han trættar ikkje alltid og gøymer ikkje æveleg på vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Han gjer ikkje med oss etter våre synder og gjev oss ikkje lika for våre misgjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'For so høg som himmelen er yver jordi, so er hans miskunn veldug yver deim som ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'So langt som aust er frå vest, let han våre misgjerningar vera burte frå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Som ein far miskunnar borni, so miskunnar Herren deim som ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'For han veit kva slag skapning me er, han kjem i hug at me er dust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Eit menneskje, som gras er hans dagar, som blomen på marki, soleis blømer han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Når vinden fer yver honom, er han ikkje meir, og staden hans veit ikkje meir av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Men Herrens miskunn er frå æva og til æva yver deim som ottast honom, og hans rettferd er mot barneborn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'mot deim som held hans pakt, og som kjem i hug hans fyresegner og liver etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Herren hev sett sin kongsstol i himmelen, og hans rike råder yver alle ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Lova Herren, de hans englar, de velduge kjempor som set hans ord i verk, med di de lyder på røysti av hans ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Lova Herren, alle hans herar, de hans tenarar som gjer hans vilje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Lova Herren alle hans verk på alle stader i hans rike! Lova Herren mi sjæl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Lova Herren, mi sjæl! Herre min Gud, du er ovleg stor, i høgd og herlegdom er du klædd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Han sveiper seg i ljos som i eit klædeplagg, han spanar ut himmelen som ein tjeldduk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'han som timbrar sine høgsalar i vatni, han som gjer skyerne til si vogn, han som fer fram på vengjerne åt vinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Han gjer vindar til sine englar og logande eld til sine tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Han grunnfeste jordi på stolparne hennar, ho skal ikkje verta rikka i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Djupe vatn lagde du yver henne som eit klæde, yver fjelli stod vatni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'For ditt trugsmål flydde dei, for ditt toremål skunda dei seg burt');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, '- fjell steig, dalar sokk - til den staden som du hadde grunnfest for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Ei grensa sette du, som dei ikkje skulde skrida yver, dei skal ikkje atter skulde leggja seg yver jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Han sender uppkomor fram i dalarne, millom fjelli renn dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Dei vatnar alle villdyr på marki, villasni sløkkjer torsten sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Yver deim bur himmelens fuglar, millom greinerne syng dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Han vatnar fjelli frå sine høge salar, jordi vert metta av den frukt du skaper.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Gras let han gro for feet, og vokstrar til gagn for folk til å få brød fram or jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'og vin som gled menneskjehjarta, til å lata andlitet skina av olje, og avla brød som styrkjer menneskjehjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Herrens tre vert metta, Libanons cedrar som han hev sett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'der fuglane byggjer reir, storken som hev sitt hus i cypressarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Dei høge fjelli er for steinbukkarne, bergskortorne er til livd for fjell-grevlingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Han gjorde månen til tidarmerke; soli kjenner si nedgangstid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Du sender myrker, og det vert natt, då krek alle villdyr i skogen fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Dei unge løvor burar etter ran, og dei krev si føda av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Soli gjeng upp, då dreg dei seg heim og legg seg inn i sine bol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Menneskja gjeng ut til si gjerning, til sitt arbeid alt til kvelds.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Kor mange dine gjerningar er, Herre! Du gjorde deim alle med visdom, jordi er full av det du hev skapt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Sjå havet, det store og vide! Der krek det i uteljande mengd av dyr både små og store.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Der gjeng skipi, Livjatan som du hev laga til å leika seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Alle ventar dei på deg, at du skal gjeva deim føda i si tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Du gjev deim, dei sankar, du let upp handi, dei vert metta med godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Du løyner ditt andlit, dei vert forskræmde, du tek burt deira ande, dei døyr og dei vender attende til dusti si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Du sender ut din ande, dei vert skapte, du nyar upp att skapnaden åt jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Herrens æra vare æveleg, Herren glede seg i sine gjerningar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Han som skodar på jordi og ho skjelv, han som rører fjelli og dei ryk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Eg vil syngja for Herren so lenge eg liver, eg vil lovsyngja min Gud so lenge eg er til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Gjev min tale kunde tekkjast honom! Eg vil gleda meg i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Gjev syndarar måtte kverva burt frå jordi, og ugudlege ikkje lenger finnast! Lova Herren, mi sjæl! Halleluja, lova Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Prisa Herren, kalla på hans namn! Kunngjer millom folkeslagi hans storverk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Syng for honom, syng honom lov! tala um alle hans under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Rosa dykk av hans heilage namn, hjarta glede seg hjå deim som søkjer Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Spør etter Herren og hans magt, søk hans åsyn alltid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Kom i hug hans under som han hev gjort, hans undergjerningar og domsordi frå hans munn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'de, etterkomarar av Abraham, hans tenar, søner åt Jakob, hans utvalde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Han er Herren, vår Gud, yver all jordi gjeng hans domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Han kjem æveleg i hug si pakt, det ord han sette fast for tusund ætter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'den pakt han gjorde med Abraham, og sin eid til Isak;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'og han gjorde det til ein rett for Jakob, for Israel ei æveleg pakt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'med di han sagde: «Deg vil eg gjeva Kana’ans land til arvlut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Då dei var ein liten flokk, få og framande der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'og dei vandra frå folk til folk, frå eitt rike til eit anna folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'let han ingen mann få gjera valdsverk mot deim, og han refste kongar for deira skuld:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '«Rør ikkje dei eg hev salva, og gjer ikkje vondt med mine profetar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Og han kalla hunger inn yver landet, kvar studnad av brød braut han sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Han sende ein mann fyre deim, til træl vart Josef seld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Dei plåga hans føter i lekkjor, i jarn vart han lagd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'til den tid då hans ord slo til, då Herrens ord viste at han var uskuldig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Då sende kongen bod og løyste honom, Herren yver folkeslag gav honom fri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Han sette honom til herre yver sitt hus, til å råda yver all hans eigedom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'so han skulde binda hans hovdingar etter sin vilje og læra hans eldste visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Og Israel kom til Egyptarland, og Jakob budde som gjest i Khams land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Og han let folket sitt aukast mykje og gjorde det sterkare enn fiendarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Deira hjarto vende han um, so dei hata hans folk og lagde løynderåder upp mot hans tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Han sende Moses, sin tenar, Aron som han hadde valt ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Dei gjorde hans teikn imillom deim og under i Khams land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Han sende myrker og gjorde det myrkt, og dei var ikkje ulyduge imot hans ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Han gjorde vatni deira til blod, og han drap deira fiskar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Deira land kom til å kreka av froskar, jamvel i salarne til deira kongar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Han tala, og det kom flugesvermar og my i heile landet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Han gav deim hagl for regn, logande eld i landet deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'og han slo ned deira vintre og fiketre og braut trei sund i landet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Han tala, og det kom engsprettor og grashoppar i uteljande mengd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'og dei åt upp all grode i deira land, og dei åt upp frukti av marki deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Og han slo alt fyrstefødt i landet deira, fyrstegrøda av all deira kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Og han førde deim ut med sylv og gull, og det var ingen i hans ætter som snåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egyptarland gledde seg då dei drog ut; for rædsla for deim hadde falle yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Han breidde ut ei sky til skyggje og eld til å lysa um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Dei kravde, og han let vaktlar koma, og med himmelbrød metta han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Han opna berget og vatn rann ut, det gjekk som ei elv gjenom turrlendet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'For han kom i hug sitt heilage ord, Abraham, sin tenar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'og han førde sitt folk ut med gleda, sine utvalde med fagnadrop,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'og han gav deim landi åt heidningarne, og folkeslags arbeid tok dei til eigedom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'at dei skulde halda hans fyresegner og taka vare på hans lover. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja! Prisa Herren, for han er god, for æveleg varer hans miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kven kann fullt ut nemna Herrens velduge verk, forkynna all hans lov?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Sæle er dei som tek vare på det som rett er, den som gjer rettferd til kvar tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Herre, kom meg i hug med den godhug du hev for ditt folk, gjesta meg med di frelsa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'so eg kann skoda lukka åt dine utvalde, gleda meg med ditt folks gleda, rosa meg med din arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Me hev synda med våre feder, me hev gjort ille, me hev vore ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Våre feder i Egyptarland agta ikkje på dine under, dei kom ikkje i hug dine mange nådegjerningar, men dei var tråssuge ved havet, ved Raudehavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Men endå frelste han deim for sitt namn skuld, av di han vilde kunngjera si magt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'og han truga Raudehavet so det vart turt, og han let deim ganga gjenom djupi som på slette marki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'og han frelste deim frå hans hand som hata deim, og løyste deim ut or fiendehand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'og vatn gøymde deira motstandarar, ikkje ein vart att av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Då trudde dei på ordi hans, då song dei hans lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Men snart gløymde dei hans gjerningar, dei bia ikkje på hans råd;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'men dei fekk ein gir i seg i øydemarki, og dei freista Gud på den ubygde stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Då gav han deim det dei vilde hava, men sende tærande sjukdom yver deira liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Og dei vart ovundsjuke på Moses i lægret, på Aron, Herrens heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Då opna jordi seg og slukte Datan, og ho let seg att yver flokken åt Abiram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'og det kveiktest eld på flokken deira, ein loge brende upp dei ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Dei gjorde ein kalv ved Horeb og tilbad eit støypt bilæte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'og dei bytte burt si æra for bilætet av ein ukse som et gras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Dei gløymde Gud, sin frelsar, som hadde gjort store ting i Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'undergjerningar i Khams land, skræmelege ting ved Raudehavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Og han tenktest til å tyna deim, dersom ikkje Moses, hans utvalde, hadde kasta seg imillom for hans åsyn til å avvenda hans vreide, at han ikkje skulde øydeleggja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Og dei vanvyrde det herlege landet, dei trudde ikkje ordet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'og dei knurra i sine tjeld, høyrde ikkje på Herrens røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Då lyfte han si hand imot deim til å slå deim ned i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'og slå deira etterkomarar ned millom heidningarne og spreida deim kring i landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Og dei batt seg saman med Ba’al-Peor, og dei åt av offer til dei daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'og dei vekte harm ved si åtferd, og ei plåga braut ut millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Då stod Pinehas fram og heldt dom, og plåga stilltest;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'og det vart rekna honom til rettferd frå ætt til ætt æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Og dei vekte vreide ved Meribavatnet, og det gjekk Moses ille for deira skuld;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'for dei var tråssuge mot hans ande, og han tala tankelaust med sine lippor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Dei øydelagde ikkje dei folki som Herren hadde tala med deim um,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'men dei blanda seg med heidningarne og lærde deira gjerningar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'og dei tente deira avgudar, og desse vart deim til ei snara,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'og dei ofra sine søner og døtter til magterne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'og dei rende ut skuldlaust blod, blod av sine søner og døtter som dei ofra til Kana’ans avgudar, og landet vart vanhelga med blodskuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Og dei vart ureine ved sine gjerningar og dreiv hor ved si åtferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Då loga Herrens vreide upp imot hans folk, og han stygdest ved sin arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Og han gav deim i handi på heidningar, og dei som hata deim, vart herrar yver deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'og deira fiendar trengde deim, og dei laut bøygja seg under deira hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Mange gonger fria han deim ut, men dei var tråssuge og sjølvrådige, og dei kom reint i vesaldom for si misgjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Men han såg til deim då dei var i naud, med di han høyrde deira klagerop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Og han kom i hug si pakt for deim, og han ynkast etter si store miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Og han let deim finna miskunn hjå alle som hadde fanga deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Frels oss, Herre vår Gud, og samla oss frå heidningarne, so me kann prisa ditt heilage namn, rosa oss av ditt lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Lova vere Herren, Israels Gud, frå æva og til æva! Og alt folket segje: Amen. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Prisa Herren, for han er god, for æveleg varer hans miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'So segjer Herrens utløyste, som han hev løyst ut or naudi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'som han hev sanka i hop frå landi, frå aust og frå vest, frå nord og frå havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Dei for vilt i øydemarki, i vegløysa, dei fann ingen by til å bu i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Hungrige og tyrste var dei, deira sjæl vanmegtast i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Då ropa dei til Herren i si naud, or deira trengslor fria han deim ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'og han førde deim på rett veg, so dei gjekk til ein by dei kunde bu i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Dei skal prisa Herren for hans miskunn og for hans under mot menneskjeborni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'for han metta den tyrste sjæl, og den hungrige sjæl fyllte han med godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Dei sat i myrker og daudeskugge, bundne i stakarsdom og jarn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'av di dei hadde tråssa mot Guds ord og vanvyrdt råderne frå den Høgste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Og han bøygde deira hjarto med liding, dei snåva, og der var ingen hjelpar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Då ropa dei til Herren i si naud, frå deira trengslor frelste han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Han førde deim ut or myrker og daudeskugge, og deira band reiv han sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Dei skal prisa Herren for hans miskunn og for hans under mot menneskjeborni;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'for han krasa koparportar og hogg sund jarnbommar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Dårar var dei for sin brotsveg, og for sine misgjerningar vart dei plåga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Deira sjæl vart leid av all mat, og dei kom nær til daudens portar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Då ropa dei til Herren i si naud; frå deira trengslor frelste han deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Han sende sitt ord og lækte deim og berga deim frå deira graver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Dei skal prisa Herren for hans miskunn og for hans under mot menneskjeborni');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'og ofra takkoffer og fortelja um hans verk med fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Dei som for ut på havet med skip, og som dreiv handel på dei store vatni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'dei såg Herrens gjerningar og hans underverk på djupet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Han tala og let det koma ein stormvind, og denne reiste havsens bylgjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Dei for upp imot himmelen, dei for ned i djupi, deira sjæl miste modet i ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Dei raga og tumla som drukne, og all deira visdom vart til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Då ropa dei til Herren i si naud, or deira trengslor førde han deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Han let storm verta til stilla, og bylgjorne kringum deim tagna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Og dei vart glade då dei lagde seg, og han førde deim til den hamni dei ynskte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Dei skal prisa Herren for hans miskunn og for hans under mot menneskjeborni');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'og høglova honom i folkesamling og lovsyngja honom der dei gamle sit saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Han gjorde elvar til ei øydemark og vatskjeldor til eit turrlende,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'fruktsamt land til ei saltheid, for deira vondskap skuld, som budde der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Han gjorde øydemark til innsjø og turrlende til vatskjeldor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Og han let hungrige bu der, og dei bygde ein by til å bu i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Og dei sådde åkrar og planta vinhagar, og dei fekk grøda til å hausta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Og han velsigna deim, og dei auka mykje, og av fe gav han deim ikkje lite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'So minka dei att og vart nedbøygde av trykk og trengsla og sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Han som renner ut vanvyrdnad yver hovdingar og let deim villast i veglaus øydemark,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'han lyfte upp den fatige or vesaldomen og auka ætterne som ei hjord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Dei ærlege ser det og gled seg, og all vondskap let att sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Den som er vis, han gjeve gaum etter dette, og dei må merke Herrens nådegjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ein song, ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Mitt hjarta er roleg, Gud, eg vil syngja og lovsyngja, ja, det skal mi æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Vakna, harpa og cither! eg vil vekkja morgonroden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Eg vil prisa deg millom folki, Herre, eg vil lovsyngja deg millom folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'For di miskunn er stor yver himmelen, og din truskap til dei høge skyer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Gud, syn deg høg yver himmelen, og di æra yver heile jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'At dei du elskar må verta frelste, hjelp oss med di høgre hand og bønhøyr oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gud hev tala i sin heilagdom. «Eg vil gleda meg, eg vil skifta ut Sikem, og Sukkotdalen vil eg mæla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Meg høyrer Gilead til, meg høyrer Manasse til, og Efraim er verja for mitt hovud, Juda er min førarstav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab er mitt vaskefat, på Edom kastar eg skoen min, for Filistarland set eg i med fagnadrop.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Kven vil føra meg til den faste by? Kven leider meg til Edom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Hev ikkje du, Gud, støytt oss burt? og du, Gud, gjeng ikkje ut med våre herar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Gjev oss hjelp mot fienden! for mannehjelp er fåfengd. Med Guds hjelp skal me gjera storverk, og han skal treda ned våre fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Til songmeisteren; av David, ein salme. Min lovsongs Gud, teg ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'For dei hev late upp sin ugudlege og falske munn imot meg, dei hev tala imot meg med ljugartunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Med hatfulle ord hev dei kringsett meg og ført strid imot meg utan årsak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Til løn for min kjærleik stod dei imot meg, endå eg berre bed,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'dei hev lagt vondt yver meg til løn for godt og hat til løn for min kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Set ein ugudleg yver honom, og lat ein klagar standa ved hans høgre hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Når han vert dømd, lat honom ganga skuldig ut, og lat hans bøn verta til synd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Lat hans dagar verta få, lat ein annan få hans embætte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Lat hans born verta farlause og kona hans enkja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Lat hans born flakka ikring og beda seg, lat deim ganga som tiggarar frå sin øydelagde heim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Lat okerkallen leggja snara um all hans eigedom, og framande plundra hans avling!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Lat ingen finnast som hyser miskunn imot honom, og ingen som ynkast yver hans farlause born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Lat hans etterkomarar ganga til grunnar og deira namn verta utstroke i næste ættled!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Hans fedra skuld vere i minne hjå Herren, og syndi åt mor hans verte ikkje utstroki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Dei vere alltid for Herrens åsyn, og han rydje deira minne ut av jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'av di han ikkje kom i hug å gjera miskunn, men forfylgde ein arm og fatig mann, og ein hjarteskræmd og vilde drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Han elska forbanning, og denne kom yver honom, han lika ikkje velsigning, og denne kom langt burt frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Han klædde seg i forbanning som sitt klædeplagg, og ho trengde som vatn inn i hans liv, og som olje i hans bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Lat henne verta honom til ei kåpa som han sveiper seg i, og til eit belte som han alltid bind um seg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Dette vere løni frå Herren åt mine motstandarar, og åt deim som talar vondt imot mi sjæl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Og du, Herre, Herre, gjer vel imot meg for ditt namn skuld, etter som di miskunn er god, so berga meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'For arm og fatig er eg, og mitt hjarta er gjenomstunge i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Som ein skugge når han lengjest, kverv eg burt, eg vert jaga burt som ein grashopp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Mine kne er ustøde av fasta, og holdet mitt misser feita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Og eg hev vorte til spott for deim; når dei ser meg, rister dei på hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Hjelp meg, Herre min Gud, frels meg etter di miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'so dei må kjenna, at dette er di hand, at du, Herre, hev gjort det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Dei forbannar, men du velsignar, dei stend upp, men vert skjemde, og din tenar gled seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Mine motstandarar skal klæda seg i skjemsla og sveipa seg i si skam som i ei kåpa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Eg vil takka Herren storleg med min munn, og midt imillom mange vil eg lova honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'For han stend på høgre sida åt den fatige til å frelsa honom frå deim som dømer hans sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Av David, ein salme. Herren sagde til min herre: «Set deg ved mi høgre hand, til dess eg legg dine fiendar til skammel for dine føter!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Ditt veldes kongsstav skal Herren retta ut frå Sion; ver herre midt imillom dine fiendar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Ditt folk møter viljugt fram på ditt veldes dag; i heilagt skrud kjem din ungdom til deg som dogg or fanget på morgonroden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Herren hev svore, og han skal ikkje angra det: «Du er prest til æveleg tid etter Melkisedeks vis.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Herren ved di høgre hand knasar kongar den dag han vreidest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Han dømer millom heidningarne, fyller upp med lik, han knasar hovud utyver den vide jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Or bekken drikk han på vegen, difor lyfter han hovudet høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja! Eg vil prisa Herren av alt mitt hjarta i råd og samling av ærlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Store er Herrens verk, gjenomtenkte etter alle sine fyremål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Høgd og herlegdom er hans gjerning, og hans rettferd stend æveleg fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Han hev sett eit minne for sine under, nådig og miskunnsam er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Mat hev han gjeve deim som ottast honom; han kjem æveleg i hug si pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Krafti av sine verk hev han kunngjort for sitt folk, då han gav deim arven til heidningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Det hans hender gjer, er sanning og rett, alle hans fyresegner er trufaste,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'fast stend dei æveleg og alltid, dei er gjorde i sanning og rettvisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Han hev sendt sitt folk utløysing, han hev skipa si pakt æveleg, hans namn er heilagt og skræmelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Otte for Herren er upphav til visdom, godt vit hev alle som gjer etter det. Hans pris varer æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja! Sæl er den mann som ottast Herren, som hev si store lyst i hans bodord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Hans avkjøme skal vera veldugt på jordi, ætti av dei ærlege skal verta velsigna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Det er velstand og rikdom i hans hus, og hans rettferd stend æveleg fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Det renn upp eit ljos i myrker for dei ærlege, nådig, miskunnsam og rettferdig er han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Vel gjeng det den mann som er miskunnsam og gjev lån, han held uppe si sak i retten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'For dei skal ikkje rikka honom i all æva, den rettferdige skal vera i ævelegt minne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'For vond tidend skal han ikkje ræddast; hans hjarta er fast, det lit på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Hans hjarta er trygt; han ræddast ikkje, til dess han ser med lyst på sine fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Han strår ut, gjev til dei fatige, hans rettferd stend alltid, hans horn skal verta upplyft med æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Den ugudlege skal sjå det og harmast, han skal skjera tenner og tærast upp, det dei ugudlege hev lyst til, vert upp i inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja! Lova, de Herrens tenarar, lova Herrens namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Herrens namn vere lova frå no og til æveleg tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Frå solekoma og til soleglad er Herrens namn høglova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Høg yver alle heidningar er Herren, yver himmelen er hans æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kven er som Herren, vår Gud? han som sit so høgt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'han som ser so djupt i himmelen og på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'han som reiser den ringe or moldi og lyfter den fatige or skarnet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'til å setja honom hjå hovdingar, hjå sitt folks hovdingar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'han som let ufruktsame bu heime som ei glad barnemor. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Då Israel drog ut or Egyptarland, Jakobs hus frå eit folk med framand tunga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'då vart Juda hans heilagdom, Israel hans rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Havet såg det og flydde, Jordan drog seg attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Fjelli hoppa som verar, haugarne som lamb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Kva hev hendt deg, hav, at du flyr? du Jordan, at du dreg deg attende?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'de fjell, at de hoppar som verar, de haugar som lamb?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'For Herrens åsyn må du skjelva, jord, for Jakobs Guds åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Han som gjer berget til ein sjø, harde steinen til ei vatskjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ikkje oss, Herre, ikkje oss, men ditt namn gjeve du æra for di miskunn, for din truskap skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Kvifor skal heidningarne segja: «Kvar er no deira Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Vår Gud er då i himmelen, alt det han vil, gjer han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Deira avgudar er sylv og gull, eit verk av menneskjehender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Dei hev munn, men talar ikkje, dei hev augo, men ser ikkje;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'dei hev øyro, men høyrer ikkje, dei hev nos, men luktar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Med sine hender grip dei ikkje, med sine føter gjeng dei ikkje, dei hev ikkje mål i strupen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Som desse er, vert dei som lagar deim, alle som set si lit til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israel, lit på Herren! Han er deira hjelp og skjold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Arons hus, lit på Herren! Han er deira hjelp og skjold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'De som ottast Herren, lit på Herren! Han er deira hjelp og skjold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Herren kom oss i hug, han skal velsigna, han skal velsigna Israels hus, han skal velsigna Arons hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'han skal velsigna deim som ottast Herren, dei små med dei store.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Herren late dykk auka, dykk og dykkar born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Velsigna er de av Herren, han som skapte himmel og jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Himmelen er himmel for Herren, men jordi hev han gjeve menneskjeborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Dei daude lovar ikkje Herren, ingen av deim som stig ned i stilla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Men me skal lova Herren frå no og til æveleg tid. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Eg elskar Herren, for han høyrer mi røyst, mine bøner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'For han hev bøygt sitt øyra til meg, og alle mine dagar vil eg kalla på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Daude-band hadde spent seg um meg, helheims trengsla hadde funne meg; naud og sorg fann eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Men eg kalla på Herrens namn: «Å Herre, berga mi sjæl!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Herren er nådig og rettferdig, og vår Gud er miskunnsam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Herren varar dei einfalde, eg var ein arming, og han frelste meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Kom attende, mi sjæl, til di ro! for Herren hev gjort vel imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Ja, du fria mi sjæl frå dauden, mitt auga frå tåror, min fot frå fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Eg skal vandra for Herrens åsyn i landi åt dei livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Eg trudde, for eg tala; eg var i stor plåga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Eg sagde i min ræddhug: «Kvar mann er ein ljugar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kva skal eg gjeva Herren att for alle hans velgjerningar imot meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Eg vil lyfta frelse-staupet, og Herrens namn vil eg påkalla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Mine lovnader vil eg halda for Herren, og det for augo på alt hans folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Dyr er i Herrens augo dauden åt hans heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Å Herre, eg er din tenar, veit du, eg er din tenar, son åt di tenestkvinna; du hev løyst mine band.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Til deg vil eg ofra takkoffer, og Herrens namn vil eg påkalla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Mine lovnader vil eg halda for Herren, og det for augo på alt hans folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'i fyregardarne til Herrens hus, midt i deg, Jerusalem. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lova Herren, alle heidningar, prisa honom alle folk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'For megtig er hans miskunn yver oss, og Herrens truskap varer i all æva. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Prisa Herren, for han er god, for æveleg varer hans miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Israel segje: «\'veleg varer hans miskunn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Arons hus segje: «\'veleg varer hans miskunn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Dei som ottast Herren, segje: «\'veleg varer hans miskunn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Ut or trengsla ropa eg på Herren, Herren svara meg og førde meg ut i det frie.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Herren er med meg, eg ræddast inkje, kva kann menneskje gjera meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Herren er med meg og hjelper meg, og eg skal sjå med lyst på deim som hatar meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Det er betre å fly til Herren enn å lita på menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Det er betre å fly til Herren enn å lita på hovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Alle heidningar kringset meg; i Herrens namn skal eg hogga deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Dei kringset, ja, kringrenner meg; i Herrens namn skal eg hogga deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Dei kringset meg som bior; dei sloknar som eld i klunger, i Herrens namn skal eg hogga deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Hardt støytte du meg, at eg skulde falla; men Herren hjelpte meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Min styrke og lovsong er Herren, og han vart meg til frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Rop av fagnad og frelsa er å høyra i tjeldi åt dei rettferdige; Herrens høgre hand gjer storverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Herrens høgre hand upphøgjer, Herrens høgre hand gjer storverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Eg skal ikkje døy, men liva og fortelja Herrens gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Hardt tukta Herren meg, men til dauden gav han meg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Lat upp for meg rettferds portar! Eg vil ganga inn gjenom deim, eg vil prisa Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Dette er Herrens port, dei rettferdige skal ganga der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Eg takkar deg av di du svara meg og vart meg til frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Den steinen som bygningsmennerne skaut ut, hev vorte ein hyrnestein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Frå Herren er det kome, dette, det er underlegt for våre augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dette er dagen som Herren hev gjort, lat oss fegnast og gleda oss no!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Å Herre, frels då! Å Herre, lat det då lukkast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Velsigna vere den som kjem i Herrens namn! Me velsignar dykk frå Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Herren er Gud, og han let det verta ljost for oss. Bitt høgtidsofferet med reip alt inn til horni på altaret!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Min Gud er du, og eg vil prisa deg, min Gud, eg vil upphøgja deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Prisa Herren, for han er god, for æveleg varer hans miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Sæle er dei som gjeng ein ulastande veg, dei som ferdast i Herrens lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Sæle er dei som tek vare på hans vitnemål, som søkjer honom av alt sitt hjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'dei som ikkje gjer urett, men vandrar på hans vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du hev gjeve dine fyresegner, at ein skal halda deim vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Å, kunde vegarne mine verta faste, so eg heldt dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Då skal eg ikkje verta til skammar når eg gjev gaum etter alle dine bodord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Eg vil takka deg av eit ærlegt hjarta når eg lærer dine rettferdsdomar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Dine fyreskrifter vil eg halda, du må ikkje reint forlata meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Korleis skal ein ungdom halda stigen sin rein? Når han held seg etter ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Av alt mitt hjarta hev eg søkt deg, lat meg ikkje villast burt frå dine bodord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'I hjarta mitt hev eg gøymt ditt ord, so eg ikkje skal synda imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Lova vere du, Herre! Lær meg dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Med lipporne mine hev eg forkynt alle rettar frå din munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Eg er glad i vegen etter dine vitnemål som i all rikdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'På dine fyresegner vil eg grunda og skoda på dine stigar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'I dine fyreskrifter vil eg hava hugnad, og ikkje vil eg gløyma ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Gjer vel imot din tenar, at eg må liva! so vil eg halda ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Lat upp augo mine, at eg kann skoda underlege ting i di lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Ein gjest er eg på jordi, løyn ikkje dine bodord for meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mi sjæl er sunderknasa av lengting etter dine rettar all tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Du hev truga dei stormodige, dei forbanna, som fer vilt frå dine bodord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Tak burt frå meg skam og vanvyrdnad! for dine vitnemål hev eg teke vare på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Jamvel hovdingar hev sete i samrøda mot meg; din tenar grundar på dine fyreskrifter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Dine vitnemål er og min hugnad, dei er mine rådgjevarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mi sjæl ligg nedi dusti, haldt meg i live etter ditt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Eg fortalde um mine vegar, og du svara meg; lær meg dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Lat meg få skyna vegen etter dine fyresegner! So vil eg grunda på dine under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mi sjæl græt av sorg; reis meg upp etter ditt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Snu lygnevegen burt frå meg, og unn meg di lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Truskaps veg hev eg valt, dine rettar hev eg sett framfyre meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Eg heng fast ved dine vitnemål, Herre, lat meg ikkje verta til skammar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Vegen etter dine bodord vil eg springa, for du trøystar mitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Herre, vis meg vegen etter dine fyreskrifter! so vil eg fara honom alt til endes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Gjev meg skyn, so vil eg taka vare på di lov og halda henne av alt mitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Leid meg på dine bodords stig, for han er til hugnad for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Bøyg mitt hjarta til dine vitnemål og ikkje til urett vinning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Vend augo mine burt, so dei ikkje ser etter fåfengd, haldt meg i live på din veg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Uppfyll for din tenar ordet ditt, som gjer at ein ottast deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Tak burt ifrå meg mi skjemsla som eg er rædd, for dine rettar er gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Sjå, eg lengtar etter dine fyresegner, haldt meg i live ved di rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Lat di miskunn, Herre, koma yver meg, di frelsa etter ditt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Eg vil gjeva svar til honom som spottar meg; for eg lit på ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Riv ikkje sannings ord so reint or munnen min, for på dine domar ventar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Stødt vil eg halda di lov, æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Lat meg ferdast i det frie, for eg spør etter dine fyresegner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Eg vil tala um dine vitnemål for kongar, og eg skal ikkje verta til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Eg vil frygda meg ved dine bodord, som eg elskar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Eg vil lyfta mine hender til dine bodord som eg elskar, og eg vil grunda på dine fyreskrifter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Kom i hug ditt ord til din tenar, med di du hev gjeve meg von!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Det er mi trøyst i min vesaldom, at ditt ord hev halde meg i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Ovmodige hev spotta meg mykje, frå di lov hev eg ikkje vike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Eg kom i hug, Herre, dine domar frå gamle dagar, og eg vart trøysta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Brennande harm hev eg vorte på dei ugudlege som forlet di lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Dine fyreskrifter hev vorte mine lovsongar i det hus der eg bur som framand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Um natti kom eg ditt namn i hug, Herre, og eg heldt di lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Dette timdest meg, at eg fekk taka vare på dine fyreskrifter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Herren er min lut, sagde eg, med di eg heldt dine ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Eg naudbad deg av alt mitt hjarta: «Ver miskunnsam imot meg etter ditt ord!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Eg tenkte på mine vegar og vende mine føter til dine vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Eg skunda meg og tøvra ikkje med å halda dine bodord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Bandi til dei ugudlege hev snørt meg inn, di lov hev eg ikkje gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Midt på natti stend eg upp og vil takka deg for dine rettferdslover.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Eg held meg til alle deim som ottast deg, og som held dine fyresegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Av di miskunn, Herre, er jordi full; lær meg dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tenaren din hev du gjort vel imot, Herre, etter ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Lær meg god skynsemd og kunnskap! for eg trur på dine bodord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Fyrr eg vart nedbøygd, for eg vilt, men no held eg ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Du er god og gjer godt, lær meg dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Dei ovmodige hev spunne i hop lygn imot meg, av alt mitt hjarta held eg dine fyresegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Deira hjarta er feitt som talg; eg fegnast ved di lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Det var godt for meg at eg vart nedbøygd, so eg kunde læra dine fyreskrifter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Lovi frå din munn er betre for meg enn tusund stykke gull og sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Dine hender hev gjort meg og laga meg til, gjev meg skyn, so eg kann læra dine bodord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Dei som ottast deg, skal sjå meg og gleda seg, for på ditt ord ventar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Eg veit, Herre, at dine domar er rettferd, og at du i truskap hev bøygt meg ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Lat di miskunn vera til trøyst for meg, etter det du hev sagt til din tenar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Lat di miskunn koma yver meg so eg kann liva! for di lov er mi lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Lat dei ovmodige verta skjemde! for dei hev trykt meg utan årsak. Eg grundar på dine fyresegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Lat deim snu seg til meg, dei som ottast deg, og kjenner dine vitnemål!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Lat mitt hjarta vera fullkome i dine fyreskrifter, so eg ikkje skal verta til skammar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Mi sjæl naudstundar etter di frelsa, eg ventar på ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Mine augo naudstundar etter ditt ord, og eg segjer: «Når vil du trøysta meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'For eg er som ei lerflaska i røyk; dine fyreskrifter gløymer eg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Kor mange er vel dagarne for din tenar? Når vil du halda dom yver deim som forfylgjer meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Dei ovmodige hev grave graver for meg, dei som ikkje liver etter di lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Alle dine bodord er trufaste; med lygn forfylgjer dei meg; hjelp meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Dei hadde so nær tynt meg i landet, men eg hev ikkje forlate dine fyresegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Haldt meg i live etter di miskunn! So vil eg taka vare på vitnemålet frå din munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Til æveleg tid, Herre, stend ditt ord fast i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Frå ætt til ætt varer din truskap, du hev grunnfest jordi, og ho stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Til å setja dine domar i verk stend dei der i dag; for alle ting er dine tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Dersom ikkje di lov hadde vore mi lyst, so hadde eg forgjengest i mi djupe naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'I all æva skal eg ikkje gløyma dine fyresegner, for ved deim hev du halde meg i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Din er eg, frels meg! for dine fyresegner hev eg spurt etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'På meg hev dei ugudlege venta og vil tyna meg; på dine vitnemål agtar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'På alt det fullkomne hev eg set ein ende; men dine bodord rekk ovleg vidt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Kor eg hev lovi di kjær! Heile dagen er ho i min tanke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Dine bodord gjer meg visare enn mine fiendar, for æveleg eig eg deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Eg hev vorte klokare enn alle mine lærarar, for eg grundar på dine vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Eg er vitugare enn dei gamle, for dine fyresegner hev eg teke vare på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Frå kvar vond stig hev eg halde mine føter burte, so eg kunde halda ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Frå dine lover hev eg ikkje vike, for du hev lært meg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Kor søt din tale er for gomen min, betre enn honning for munnen min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Av dine fyresegner fær eg vit, difor hatar eg kvar lygnestig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ditt ord er ei lykt for min fot og eit ljos for min stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Eg hev svore og hev halde det, å taka vare på dine rettferdslover.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Eg er ovleg nedbøygd; Herre, haldt meg i live etter ditt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Lat min munns offer tekkjast deg, Herre, og lær meg dine rettar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Eg gjeng alltid med livet i neven, men di lov hev eg ikkje gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Dei ugudlege hev lagt snara for meg; men frå dine fyresegner hev eg ikkje villa meg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Til æveleg eiga hev eg fenge dine vitnemål, for dei er mi hjartans gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Eg hev bøygt mitt hjarta til å gjera etter dine fyreskrifter, æveleg og til endes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Dei tvihuga hatar eg, men di lov elskar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Du er mi livd og min skjold, og på ditt ord ventar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Vik frå meg, de som gjer vondt, at eg kann halda min Guds bodord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Haldt meg uppe etter ditt ord, so eg kann liva, og lat meg ikkje verta til skammar med mi von!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Haldt meg uppe, so eg kann verta frelst! So vil eg alltid sjå med lyst på dine fyreskrifter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Du agtar for inkje alle deim som fer vilt frå dine fyreskrifter; for deira svik er fåfengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Som slagg kastar du burt alle ugudlege på jordi; difor elskar eg dine vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Eg rys i holdet av rædsla for deg, og for dine domar ottast eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Eg hev gjort rett og rettferd, du vil ikkje gjeva meg yver til deim som trykkjer meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Gakk i borg for tenaren din, so det må ganga honom vel! lat ikkje dei ovmodige trykkja meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Augo mine naudstundar etter di frelsa og etter ditt rettferdsord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Gjer med din tenar etter di miskunn og lær meg dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Eg er din tenar; gjev meg vit, so eg kann kjenna dine vitnemål!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Det er tid for Herren til å gripa inn, dei hev brote di lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Difor elskar eg dine bodord meir enn gull, ja, meir enn fint gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Difor held eg alle fyresegner um alle ting for rette; eg hatar kvar lygnestig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Underfulle er dine vitnemål, difor tek mi sjæl vare på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Når ordi dine opnar seg, gjev dei ljos, og dei gjer dei einfalde kloke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Eg let munnen upp og sukka av lengting; for etter dine bodord stunda eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Vend deg til meg og ver meg nådig, som rett er mot deim som elskar ditt namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Gjer mine stig faste ved ditt ord, og lat ingen urett råda yver meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Løys du meg ut or menneskjevald! So vil eg halda dine fyresegner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Lat di åsyn lysa på din tenar, og lær meg dine fyreskrifter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Vatsbekkjer renn or augo mine, av di folk ikkje held di lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Rettferdig er du, Herre, og rette er dine domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Du hev fyreskrive dine vitnemål i rettferd og i stor truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Min brennhug hev tært meg upp, av di mine motstandarar hev gløymt dine ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ditt ord er vel reinsa, og din tenar elskar det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Liten er eg og vanvyrd; dine fyresegner hev eg ikkje gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Di rettferd er ei æveleg rettferd, og di lov er sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Naud og trengsla fann meg; dine bodord er mi lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Rettferdige er dine vitnemål til æveleg tid; gjev meg skyn, so eg kann liva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Eg ropar av alt mitt hjarta, svara meg, Herre! Dine fyreskrifter vil eg taka vare på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Eg ropar til deg, frels meg! so vil eg halda dine vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Tidleg i dagningi var eg uppe og ropa um hjelp; eg venta på ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Mine augo var uppe fyre nattevakterne, so eg kunde grunda på ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Høyr mi røyst etter di miskunn, Herre, haldt meg i live etter dine domar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Dei er nær som renner etter ugjerning; frå di lov er dei langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Du er nær, Herre, og alle dine bodord er sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Longe sidan veit eg av dine vitnemål, at du hev grunnfest deim i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Sjå til mi djupe naud og fria meg ut! For di lov hev eg ikkje gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Før mi sak, og løys meg ut, haldt meg i live etter ditt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Frelsa er langt frå dei ugudlege, for dine fyreskrifter spør dei ikkje etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Di miskunn er stor, Herre; haldt meg i live etter dine domar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mange er dei som forfylgjer meg og stend meg imot; frå dine vitnemål hev eg ikkje vike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Eg såg dei utrue og fekk uhug, av di dei ikkje heldt ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Sjå at eg hev elska dine fyresegner! Herre, haldt meg i live etter di miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Summen av ditt ord er sanning, og æveleg stend all di rettferds lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Hovdingar forfylgde meg utan orsak, men mitt hjarta ottast dine ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Eg gled meg yver ditt ord, som når ein finn mykje herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Lygn hev eg hata og havt stygg til; di lov hev eg elska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sju gonger um dagen hev eg lova deg for dine rettferdige domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Mykje fred hev dei som elskar di lov, og ingen støyt fær deim til fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Eg hev venta på di frelsa, Herre, og dine bodord hev eg halde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mi sjæl hev halde dine vitnemål, og eg elska deim mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Eg hev halde dine fyresegner og dine vitnemål, for alle mine vegar er for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Lat mitt klagerop koma fram for di åsyn, Herre! Gjev meg skyn etter ditt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Lat mi bøn koma for di åsyn! Frels meg etter ditt ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Mine lippor skal fløda yver av lovsong, for du lærer meg dine fyreskrifter;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Mi tunga skal syngja um ditt ord; for alle dine bodord er rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Lat di hand vera meg til hjelp! for dine fyresegner hev eg valt ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Eg lengtar etter di frelsa, Herre, og di lov er mi lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Lat mi sjæl leva og lova deg, og lat dine domar hjelpa meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Eg hev fare vilt; leita upp din tenar som ein burtkomen sau! for dine bodord hev eg ikkje gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ein song til høgtidsferderne. Til Herren ropa eg i mi naud, og han svara meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Herre, frels mi sjæl frå ljugarlippa, frå den falske tunga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Kva skal han gjeva deg, og kva meir skal han gjeva deg, du falske tunga?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Kveste piler til ei kjempa og gløder av einebuska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Usæl eg, som framand er imillom Mesek, og bur ved Kedars tjeld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Lenge nok hev sjæli mi butt hjå deim som hatar fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Eg er berre fred, men når eg talar, er dei ferdige til strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Ein song til høgtidsferderne. Eg lyfter augo mine upp til fjelli, kvar kjem mi hjelp ifrå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Mi hjelp kjem ifrå Herren, han som hev skapa himmelen og jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Han skal ikkje lata foten din vera ustød, han blundar ikkje din vaktar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Sjå, han blundar ikkje og søv ikkje, Israels vaktar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Herren er din vaktar, Herren er din skugge ved di høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Um dagen skal ikkje soli stikka deg, og ikkje månen um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Herren skal vara deg frå alt vondt, han skal vara di sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Herren skal vara din utgang og din inngang frå no og til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Ein song til høgtidsferderne; av David. Glad vart eg då dei sagde til meg: «Me vil ganga til Herrens hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Våre føter fekk standa i dine portar, Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem, du velbygde by, ein by som heng vel i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Der ætterne fer upp, Herrens ætter, etter Israels lov, til å prisa Herrens namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'For der er stolar sette til domstolar for Davids hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Bed um fred for Jerusalem! det gange deim vel som elskar deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Fred vere innanfor dine murar og ro i dine salar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'For mine brør og vener skuld vil eg segja: «Fred vere i deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'For Herrens, vår Guds, hus skuld vil eg søkja det som er godt for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Ein song til høgtidsferderne. Til deg lyfter eg augo mine, du som sit i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Sjå, som augo til tenarar skodar på handi åt herrarne sine, som augo til tenestgjenta på handi åt frua si, soleis skodar våre augo upp til Herren, vår Gud, til dess han vert oss nådig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Ver oss nådig, Herre, ver oss nådig! for me er ovleg metta med vanvyrdnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Ovleg metta er vår sjæl med spott ifrå dei kaute, med vanvyrdnad frå valdsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Ein song til høgtidsferderne; av David. Hadde ikkje Herren vore med oss, - so segje Israel -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'hadde ikkje Herren vore med oss, då menneskje stod upp imot oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'so hadde dei slukt oss livande, då deira vreide loga imot oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'so hadde vatni flødt yver oss, ei elv gjenge yver vår sjæl,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'so hadde dei gjenge yver vår sjæl, dei storlåtne vatni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Lova vere Herren, som ikkje gav oss til åt for deira tenner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Vår sjæl slapp undan som ein fugl or fangarsnara. Snara rivna sund, og me slapp undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Vår hjelp er i Herrens namn, han som gjorde himmel og jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Ein song til høgtidsferderne. Dei som lit på Herren, er som Sionsfjellet, som ikkje vert rikka, men æveleg stend fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jerusalem - fjell er kringum det, og Herren er ikring sitt folk frå no og i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'For ikkje skal ugudleg kongsstav kvila på arvluten åt dei rettferdige, at ikkje dei rettferdige skal retta ut til urett sine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Gjer godt, Herre, mot dei gode, og imot deim som hev eit ærlegt hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Men deim som vender seg burt til sine krokute vegar, skal Herren lata fara med illgjerningsmenner. Fred vere yver Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Ein song til høgtidsferderne. Då Herren førde Sions fangar heim att, då var me som drøymande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Då fylltest vår munn med lått, og vår tunga med fagnadrop. Då sagde dei millom heidningarne: «Store ting hev Herren gjort mot desse.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Store ting hev Herren gjort mot oss, og me vart glade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Herre, før du våre fangar heim att som bekkjer i Sudlandet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Dei som sår med tåror, skal hausta med glederop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Dei gjeng av stad og græt og ber sitt såkorn. So kjem dei att med fagnadrop og ber sine kornband.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Ein song til høgtidsferderne; av Salomo. Dersom Herren ikkje byggjer huset, arbeider dei fåfengt som byggjer på det. Dersom Herren ikkje vaktar byen, so vaker vakti fåfengt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Fåfengt stend de tidleg upp og sit til seint på kvelden og et det mødsame brød; det same gjev han venen sin som søv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Sjå, born er Herrens gåva, livsfrukt er ei løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Som piler i kjempehand, soleis er ungdoms søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Sæl er den mann som hev sitt pilehus fullt av deim! Ikkje skal dei verta til skammar, når dei talar med fiendar i porten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Ein song til høgtidsferderne. Sæl er kvar den som ottast Herren, som ferdast på hans vegar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Det dine hender avlar, skal du njota, sæl er du, og det gjeng deg vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Kona di er som eit fruktrikt vintre inne i ditt hus; borni dine er som oljekvister kringum bordet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Sjå, soleis vert den mann velsigna, som ottast Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Herren signe deg frå Sion! sjå med lyst på Jerusalems lukka alle dine livedagar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Og måtte du sjå born av dine born! Fred vere yver Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Ein song til høgtidsferderne. Mykje hev dei trengt meg alt ifrå min ungdom - so segje Israel -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'mykje hev dei trengt meg alt ifrå min ungdom; men dei hev ikkje fenge bugt med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'På min rygg hev pløgjarar pløgt, dei hev gjort sine forer lange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Herren er rettferdig, han hev hogge av reipi til dei ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Dei skal skjemmast og vika attende alle som hatar Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Dei skal verta som gras på taki, som visnar fyrr det fær veksa;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'slåttaren fær ikkje handi full, og bundelbindaren ikkje eit fang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Og dei som gjeng framum, segjer ikkje: «Herrens velsigning vere yver dykk, me velsignar dykk i Herrens namn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Ein song til høgtidsferderne. Or djupet ropar eg på deg, Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herre, høyr på mi røyst, lat dine øyro merka mi bønerøyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Dersom du, Herre, vil gøyma på misgjerningar, Herre, kven kann då standa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'For hjå deg er forlatingi, at dei skal ottast deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Eg vonar på Herren, mi sjæl vonar, og eg ventar på hans ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mi sjæl ventar på Herren meir enn vaktmenner på morgonen, vaktmenner på morgonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Venta, Israel, på Herren! for hjå Herren er nåden, og stor utløysing er hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Og han skal løysa Israel frå alle deira misgjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Ein song til høgtidsferderne; av David. Herre, ikkje er mitt hjarta stolt og ikkje augo mine storlåtne, og ikkje gjeng eg med tankar som er altfor underlege for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Nei, eg hev fenge sjæli til å vera still og tegja som avvant barn hjå mor si, som avvant barn er sjæli mi hjå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Venta, Israel, på Herren, frå no og i all æva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Ein song til høgtidsferderne. Herre, kom i hug for David all hans møda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Han som svor for Herren, lova Jakobs velduge:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '«Ikkje gjeng eg inn i mitt heimetjeld, ikkje stig eg upp på lega i mi seng,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'ikkje unner eg augo svevn, ikkje augneloki ein blund,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'fyrr eg finn ein stad for Herren, ein bustad for Jakobs velduge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Sjå, me høyrde um henne i Efrata, so fann me henne i skogbygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Lat oss ganga til hans bustad, lat oss tilbeda for hans fotskammel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Statt upp, Herre, og kom til din kvilestad, du og ditt veldes kista!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Prestarne dine klæde seg i rettferd, og dine trugne ropa med fagnad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'For David, din tenars skuld vis ikkje frå deg åsyni åt den du hev salva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Herren hev svore David ein sann eid, den gjeng han ikkje ifrå: «Av di livsfrukt vil eg setja kongar på din stol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Dersom dine søner held mi pakt og mine vitnemål som eg skal læra deim, so skal og deira søner æveleg og alltid sitja på din kongsstol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'For Herren hev valt seg Sion, han ynskte det til sin bustad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '«Dette er min kvilestad for all tid, her vil eg bu, for det hev eg ynskt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Maten her vil eg rikleg signa, dei fatige vil eg metta med brød,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'og prestarne vil eg klæda med frelsa, og dei gudlege skal ropa høgt av fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Der vil eg lata veksa upp eit horn for David, der hev eg stelt til ei lampa for den eg hev salva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Hans fiendar vil eg klæda med skam, men yver honom skal hans kruna stråla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Ein song til høgtidsferderne; av David. Sjå kor godt det er og yndelegt at brør ogso bur i saman!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Det er liksom den gode olje uppå hovudet, som renn ned yver skjegget, Arons skjegg, og som renn ned på saumen av hans klædnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'som dogg frå Hermon, som renn ned på Sions fjell. For der hev Herren laga til velsigningi, liv i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Ein song til høgtidsferderne. Upp, og lova Herren, alle Herrens tenarar, de som stend i Herrens hus um næterne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Lyft dykkar hender upp til heilagdomen og lova Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Herren signe deg frå Sion, han som gjorde himmel og jord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja! Lova Herrens namn, lova, de Herrens tenarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'de som stend i Herrens hus, i fyregardarne til vår Guds hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Lova Herren, for Herren er god! Syng lov for hans namn, for det er yndelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'For Jakob hev Herren valt seg ut, Israel til sin eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'For eg veit at Herren er stor, og vår Herre er meir enn alle gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Herren gjer alt det han vil i himmelen og på jordi, i havi og i alle djup,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'han som let eim stiga upp frå enden av jordi, gjer eldingar til regn, som fører ut or sine gøymslor vind,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'han som slo dei fyrstefødde i Egyptarland både av folk og fe,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'som sende teikn og under midt i deg, Egyptarland, mot Farao og alle hans tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Han som slo mange heidningefolk og drap megtige kongar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihon, amoritarkongen, og Basans konge Og, og alle Kana’ans kongerike,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'og gav deira land til arv, til arv for Israel, sitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Herre, ditt namn varer æveleg, Herre, ditt minne frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'For Herren skal døma sitt folk og ynkast yver sine tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Heidninge-avgudar er sylv og gull, eit verk av menneskjehender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Dei hev munn, men talar ikkje, dei hev augo, men ser ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'dei hev øyro, men høyrer ikkje, og ingen ande er i deira munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Som desse er, vert dei som lagar deim, alle som set si lit til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Israels hus, lova Herren! Arons hus, lova Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Levis hus, lova Herren! De som ottast Herren, lova Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Lova vere Herren frå Sion, han som bur i Jerusalem! Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Prisa Herren, for han er god, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Prisa Guden yver gudar, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Prisa Herren yver herrar, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Han, den einaste som gjer store under, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Han som gjorde himmelen med vit, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Han som strakte jordi yver vatni, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Han som gjorde dei store ljos, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'soli til å råda yver dagen, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'månen og stjernorne til å råda yver natti, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Han som slo egyptarane gjenom deira fyrstefødde, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'og førde Israel ut frå deim, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'med sterk hand og strak arm, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Han som skar i sund Raudehavet, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'og førde Israel midt igjenom, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'og kasta Farao og heren hans i Raudehavet, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Han som førde sitt folk i øydemarki, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Han som felte store kongar, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'og som slo herlege kongar i hel, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, amoritarkongen, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'og kongen yver Basan, Og, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'og gav deira land til arv, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'til arv for sin tenar Israel, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Han som kom oss i hug i vår stakarsdom, for æveleg varer hans miskunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'og reiv oss ut or fiendevald, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Han som gjev alt som liver brød, for æveleg varer hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Prisa Gud i himmelen, for æveleg varer hans miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Ved Babels elvar, der sat me og gret, når me kom Sion i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'På vier-runnarne der i landet hengde me harporne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'For der kravde dei som heldt oss fanga song av oss, og våre plågarar kravde gleda: «Syng åt oss av Sions songar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Korleis kann me syngja Herrens song på framand jord?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Um eg gløymer deg, Jerusalem, so gjev mi høgre hand må gløyma seg burt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Gjev tunga må hanga fast ved gomen min, dersom eg ikkje kjem deg i hug, dersom eg ikkje set Jerusalem yver mi høgste gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Herre, hugsa Edoms søner Jerusalems dag! dei som sagde: «Riv ned, riv ned, radt ned til grunnen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Babels dotter, du øydelagde! sæl er den som gjev deg løn for den gjerning du gjorde imot oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Sæl er den som tek og krasar dine småborn imot berget!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Av David. Eg vil prisa deg av alt mitt hjarta, for augo på gudarne vil eg syngja deg lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Eg vil kasta meg ned framfyre ditt heilage tempel, eg vil takka ditt namn for di miskunn og for din truskap; for du hev gjort ditt ord herlegt yver alt ditt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Den dagen eg ropa, svara du meg, du gjorde meg frihuga, styrkte mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Herre, alle kongar på jordi skal prisa deg, når dei fær høyra ordi av din munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Og dei skal syngja um Herrens vegar; for Herrens æra er stor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'for Herren er høg og ser til den låge, og den stormodige kjenner han langan veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Um eg ferdast midt i naudi, held du meg i live, mot harmen til mine fiendar retter du ut di hand, og ho frelser meg, di høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Herren vil fullføra sitt verk for meg. Herre, di miskunn varer æveleg; det verk dine hender hev gjort, må du ikkje gjeva upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Til songmeisteren; av David; ein salme. Herre, du ransakar meg og kjenner meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Um eg sit eller stend upp, so veit du det, du skynar min tanke langan veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Mi gonga og lega røyner du ut, og alle mine vegar kjenner du grant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'For det er inkje ord på mi tunga - sjå, Herre, du kjenner det alt til fullnads.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Bak og framme held du ikring meg, og du legg di hand på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Slik kunnskap er meg for underleg, han er for høg, eg kann ikkje greida honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kvar skal eg fara frå din ande, og kvar skal eg fly ifrå ditt andlit?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'For eg upp til himmelen, so er du der, og reidde eg seng i helheimen, sjå, der er du og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Tek eg vengjerne til morgonroden, slo eg meg ned ved ytste havet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'di hand vilde leida meg ogso der, og di høgre hand vilde halda meg fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Og sagde eg: «Myrker løyne meg, og ljoset verte natt ikringum meg,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'so vilde ikkje heller myrkret gjera noko myrkt for deg, og natti vilde vera ljos som dagen, myrkret vilde vera som ljoset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'For du hev skapt mine nyro, du hev verka meg i morsliv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Eg takkar deg, av di eg er laga på øgjeleg underfull vis; underfulle er dine verk, og mi sjæl veit det so vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Mine bein var ikkje dulde for deg då eg vart laga i løynd, då eg med kunst vart verka djupt i jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Då eg var eit foster, såg dine augo meg, og i di bok vart dei alle uppskrivne, dei dagar som vart fastsette, då ikkje ein av deim var komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Og kor dyre dine tankar er for meg, du Gud, kor store summarne er av deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Vil eg telja deim, so er dei fleire enn sand; eg vaknar, og endå er eg hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Gud, gjev du vilde drepa den ugudlege! og de, blodfuse menner, vik burt frå meg -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'dei som nemner deg med fulskap, brukar ditt namn til lygn - dine fiendar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Skulde eg ikkje, Herre, hata deim som hatar deg, og styggjast ved deim som stend deg imot?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Med det sterkaste hatet hatar eg deim, fiendar er dei for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Ransaka meg, Gud, og kjenn mitt hjarta! Prøv meg og kjenn mine tankar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Og sjå um eg er på veg til pinsla, og leid meg på æveleg veg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Til songmeisteren; ein salme av David.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Herre, fria meg ut frå vonde folk, vara meg ifrå valdsmenner');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'som tenkjer vondt i hjarta, som kvar dag samlar seg til strid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Dei kvesser tunga si som ein orm, orme-eiter er under lipporne deira. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Vakta meg, Herre, for henderne til dei ugudlege, vara meg ifrå valdsmenner, som tenkjest til å få mine fet til fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Dei ovmodige gøymer snara til meg og reip, dei strekkjer garn ved vegen, gildror set dei snaror for meg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Eg segjer til Herren: «Min Gud er du.» Lyd, Herre, på mi bønerøyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Herre, Herre, du mi sterke frelsa, du vernar mitt hovud på væpningsdagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Herre, lat ikkje den ugudlege få si lyst, lat ikkje hans vonde råd få framgang! Dei vilde elles upphøgja seg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Yver hovudet på deim som kringset meg, skal den ulukka falla som deira lippor valdar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Brennande kol skal ein rista ned yver deim, i elden skal han kasta deim, i djupe vatn, so dei ikkje kann koma upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Ein munnkåt mann skal ikkje trygt på jordi, den vonde valdsmann skal dei jaga til han sturtar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Eg veit at Herren skal greida saki for armingen, og retten for dei fatige. Ja, dei rettferdige skal prisa namnet ditt, dei ærlege skal bu for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Ein salme av David. Herre, eg ropar på deg, skunda deg til meg! Vend øyra til mi røyst når eg ropar til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Lat bøni mi gjelda som røykoffer for ditt andlit, mi hand-upplyfting som kvelds-grjonoffer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Herre, set vakt for munnen min, vara mi lippe-dør!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Bøyg ikkje mitt hjarta til noko vondt til å gjera ugudlege gjerningar saman med menner som gjer urett, og ikkje lat meg eta av deira lostemat!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Lat ein rettferdig slå meg i kjærleik og tukta meg! Slik hovudsalve skal ikkje mitt hovud forsmå! Um det varer, so set eg mi bøn mot deira vondskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Deira domarar vert sturta utfyre fjellveggen, og sjølv skal dei høyra mine ord, at dei er yndelege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Som når ein pløgjer og rotar i jordi, so ligg beini våre spreidde kring ved døri til helheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'For upp til deg, Herre, Herre, ser mine augo, til deg flyr eg, tøm ikkje ut mi sjæl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Vara meg ifrå fella dei hev sett for meg, og snarorne til deim som gjer urett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Lat dei ugudlege falla i sine eigne garn, medan eg gjeng uskadd framum!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Ein salme til lærdom av David då han var i helleren, ei bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Med røysti mi ropar eg til Herren, med røysti bed eg inderleg til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Eg renner ut mi sorg for hans åsyn, for hans åsyn segjer eg fram mi naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Når mi ånd vanmegtast i meg, so kjenner då du min stig; på den veg eg skal ferdast, hev dei løynt snaror for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Skoda til mi høgre sida og sjå! Det er ingen som kjennest ved meg; all livd er burte frå meg, ingen spør etter mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Eg ropar til deg, Herre! Eg segjer: «Du er mi livd, min lut i landet åt dei livande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Agta på mitt klagerop, for eg er ovleg arm! Fria meg frå mine forfylgjarar, for dei er meg for sterke. Før mi sjæl or fengslet, so eg kann lova ditt namn! Kring meg skal dei rettferdige samla seg, når du gjer vel imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Ein salme av David. Herre, høyr mi bøn og vend øyra til mine inderlege bøner! Svara meg i din truskap, i di rettferd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'og gakk ikkje til doms med din tenar; for ingen som liver, er rettferdig for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'For fienden hev forfylgt mi sjæl, han hev krasa mitt liv til jordi, han hev sett meg av i myrkrer som dei æveleg daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Og mi ånd er vanmegtig i meg, mitt hjarta i meg er forskræmt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Fordoms dagar kjem eg i hug, eg tenkjer på alt ditt verk og grundar på det dine hender hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Mine hender retter eg til deg, som turre landet tyrster mi sjæl etter deg. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Herre, svara meg snart, mi ånd forgjengst! Løyn ikkje ditt andlit for meg, so eg skulde likjast deim som fer ned i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Lat meg høyra di miskunn um morgonen, for eg lit på deg! Lær meg den veg eg skal vandra, for eg lyfter mi sjæl til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Fria meg, Herre, frå mine fiendar, eg søkjer livd hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Lær meg å gjera din vilje, for du er min Gud! Din gode ande leide meg på jamne lendet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'For ditt namn skuld, Herre, haldt meg i live! I di rettferd før mi sjæl ut or trengsla!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Og ryd i di miskunn ut mine fiendar, og øydelegg alle som trengjer mi sjæl, for eg er din tenar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Av David. Lova vere Herren, mitt berg, som lærde mine hender strid og mine fingrar ufred,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'mi miskunn og mi festning, mi borg og min bergar, min skjold og den eg flyr til, han som tvingar mitt folk under meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Herre, kva er ein mann, at du kjenner honom, eit menneskjebarn, at du agtar på det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Mannen likjest ein pust, hans dagar er som ein kvervande skugge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Herre, bøyg din himmel, og stig ned, rør du fjelli so dei ryk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Lat ljonet lyna, og spreid deim, send dine piler, og skræm deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Rett henderne ned frå det høge, frels meg og fria meg ut frå dei store vatni, frå handi åt framande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'dei som med munnen talar svik, og deira høgre hand er lygne-hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Gud, ein ny song vil eg syngja deg, til tistrengs-harpa vil eg syngja deg lov,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'du som gjev kongar frelsa, som friar David, tenaren din, frå det vonde sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Frels meg og fria meg ut frå handi åt framande, dei som med munnen talar svik, og deira høgre hand er lygne-hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'So våre søner kann vera i sin ungdom som høgvaksne vokstrar, våre døtter som hyrnestolpar, hogne som til eit slott,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'so våre bur kann vera fulle og gjeva av alle slag, so våre sauer kann auka seg i tusundtal, ja, ti tusundtal på våre marker,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'so våre kyr kann hava kalv, og der ikkje må vera brot og ikkje tap, og inkje klagerop på våre gator.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Sælt er det folk som hev det soleis; sælt er det folk som hev Herren til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ein lovsong av David. Eg vil upphøgja deg, min Gud, du konge, og eg vil lova namnet ditt æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Kvar dag vil eg lova deg, og eg vil prisa namnet ditt æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Stor er Herren og mykje lovsungen, og hans storleik er uransakleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Ei ætt skal lova dine verk for ei onnor, og dine storverk skal dei forkynna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Di høge og herlege æra og dine underverk vil eg grunda på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Um dine sterke, skræmelege gjerningar skal dei tala, og dine storverk vil eg fortelja um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Minne-ord um din store godleik skal dei lata strøyma ut, og di rettferd skal dei lovsyngja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Nådig og miskunnsam er Herren, langmodig og stor i miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Herren er god imot alle, og han miskunnar alle sine verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Alle dine verk skal prisa deg, Herre, og dine trugne lova deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Um herlegdomen i ditt rike skal dei tala, og ditt velde skal dei forkynna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'til å kunngjera dine velduge verk for menneskjeborni, og den strålande herlegdom i ditt rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Ditt rike er eit rike for alle ævor, og ditt herredøme varer gjenom alle ætter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Herren er stydjar alle som fell, og han reiser alle som er nedbøygde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Alle vender augo sine ventande til deg, og du gjev deim deira føda i si tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du let upp handi og mettar alt levande med hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Herren er rettferdig på alle sine vegar og miskunnsam i alle sine verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Herren er nær hjå alle deim som kallar på honom, alle som kallar på honom i sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Han gjer etter deira ynskje som ottast honom, og han høyrer deira rop og frelser deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Herren varar alle deim som elskar honom, men alle ugudlege tyner han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Min munn skal mæla um Herrens pris, og alt kjøt skal lova hans heilage namn i all æva og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! Mi sjæl, lova Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Eg vil lova Herren so lenge eg liver, syngja lov for min Gud medan eg er til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Set ikkje lit til hovdingar, til ein menneskjeson som ikkje kann hjelpa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Fer hans ande ut, so vender han attende til si jord, den dagen er det ute med hans tankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Sæl er den som hev Jakobs Gud til hjelp, som vonar på Herren, sin Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'han som hev skapa himmel og jord, havet og alt som i deim er, han som er trufast til æveleg tid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'han som gjev dei nedtyngde rett, han som gjev dei hungrige brød. Herren løyser dei bundne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Herren opnar augo på dei blinde, Herren reiser dei nedbøygde, Herren elskar dei rettferdige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Herren varar dei framande, farlause og enkjor held han uppe, men han villar vegen for dei ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Herren skal vera konge æveleg, din Gud, Sion, frå ætt til ætt. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Halleluja! For det er godt å lovsyngja vår Gud, for yndelegt er det, og lovsong høver vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Herren byggjer upp Jerusalem, han samlar dei burtdrivne israelitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Han lækjer deim som hev sundbrote hjarta, og bind um deira verkjande sår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Han set tal på stjernorne, han nemner deim alle med namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Stor er vår Herre og veldug i magt, på hans vit er det ikkje mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Herren held dei spaklyndte uppe, dei ugudlege bøygjer han ned til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Syng for Herren med takkesong, syng lov for vår Gud med cither!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'han som tekkjer himmelen med skyer, han som lagar regn for jordi, han som let det veksa gras på fjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Han gjev feet for, ramn-ungarne som ropar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Han hev ikkje hug til hestens styrke, han hev ikkje hugnad i mannsens leggjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Herren hev hugnad i deim som ottast han, deim som ventar på hans miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Jerusalem, prisa Herren, Sion, lova din Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'For stengerne på dine portar hev han gjort faste, han hev velsigna dine born i deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Han gjev dine grensor fred, han mettar deg med den feitaste kveite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Han sender sin tale til jordi, fort spring hans ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Han som gjev snø som ull, han strår ut rim som oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Han kastar sin is som småe stykke; kven kann standa for hans kulde?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Han sender sitt ord og smeltar deim, han let vinden sin blåsa, då renn vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Han hev kunngjort sitt ord for Jakob, sine fyresegner og rettar for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Soleis hev han ikkje gjort med noko folk, og hans rettar - deim kjenner dei ikkje. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja! Lova Herren frå himmelen, lova honom i det høge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lova honom, alle hans englar, lova honom, all hans her!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lova honom, sol og måne, lova honom, alle lysande stjernor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Lova honom, de himle-himlar, og de vatn ovanfor himlarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Dei skal lova Herrens namn, for han baud, og dei vart skapte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'og han stelte deim upp for alltid og æveleg, han gav ei lov som ingen bryt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lova Herren frå jordi, de store sjødyr og alle djup,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Eld og hagl, snø og eim, du storm som set hans ord i verk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'de fjell og alle haugar, aldetre og alle cedrar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'de ville dyr og alt fe, krekande dyr og fljugande fuglar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'de kongar på jordi og alle folk, de hovdingar og alle domarar på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'de unge gutar og gjentor, de gamle med dei unge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Dei skal lova Herrens namn, for berre hans namn er høgt, hans herlegdom er yver jord og himmel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'og han hev lyft upp eit horn for sitt folk, til ein lovsong for alle sine trugne, for Israels born, det folk som er honom nær. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja! Syng Herren ein ny song, hans lov i samlingi av dei gudlege!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Israel glede seg i sin skapar, Sions søner frygde seg for sin konge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Dei skal lova hans namn med dans, syngja for honom til pauka og cither.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'For Herren hev hugnad i sitt folk, han pryder spaklyndte med frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Dei gudlege frygdar seg i herlegdom, dei ropar av fagnad på sine lægje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Lovsong for Gud er i deira munn, og eit tvieggja sverd i deira hand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'til å fullføra hemn yver heidningarne, refsing yver folkeslagi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'til å binda deira kongar med lekkjor og deira storfolk med jarnband,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'til å fullføra fyreskriven dom yver deim. \'ra er dette for alle hans trugne. Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja! Lova Gud i hans heilagdom, lova honom i hans sterke kvelv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lova honom for hans storverk, lova honom etter hans fulle storleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lova honom med lurljom, lova honom med harpa og cither!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lova honom med trumma og dans lova honom med strengleik og fløyta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lova honom med klingande cymblar, lova honom med ljomande cymblar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Alt som hev ande, love Herren! Halleluja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Ordtøke av Salomo, son til David, konge yver Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Av deim kann ein læra visdom og age og skyna vituge ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Og få age so ein vert klok, rettferd og rett og rettvisa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Dei kann gjeva dei urøynde klokskap, ungdomen kunnskap og ettertanke -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'so den vise kann høyra og auka sin lærdom og den vituge verta rådklok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Dei gjev skyn på ordtak og myrke ord, ord frå dei vise og gåtorne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Otte for Herren er upphav til kunnskap, uvitingar vanvyrder visdom og age.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Høyr etter, son min, når far din deg agar, og kasta’kje frå deg det mor di deg lærer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'For det er ein yndeleg krans for ditt hovud, og kjedor kring halsen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Son min, når syndarar lokkar deg, samtykk ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Um dei segjer: «Kom med oss! Me vil lura etter blod, setja fella for den skuldlause utan grunn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Me vil gløypa deim som helheimen livande, og heile som når dei fer i gravi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Me vinna oss alle slag skattar, og fyller husi våre med rov;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'du skal få lutskifte saman med oss, alle skal me ha same pungen.» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Son min, gakk ikkje då på vegen med deim, haldt foten din burte frå deira stig!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'For føterne deira spring til vondt og er snøgge til å renna ut blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Men fåfengt breier dei netet for augo på alle fuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Dei lurer på sitt eige blod og set eit garn for sitt eige liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'So gjeng det kvar som riv til seg med ran, det drep sin eigen herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Vismøyi ropar på gata og lyfter si røyst på torgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'På gatehyrna preikar ho midt i ståket, i porthallar og kring i byen ho talar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '«Kor lenge vil de fåkunnige elska fåkunna, og kor lenge vil spottarar ha hug til spott, og dårar hata kunnskap?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Snu dykk hit når eg refser! So skal åndi mi fløyma for dykk, og eg skal kunngjera dykk mine ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Eg ropa og de vilde ikkje høyra, og ingen agta på at eg rette ut handi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'De brydde dykk ei um all mi råd, og ansa ikkje mitt refsings ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'So skal eg då læ når de ulukka fær, eg skal spotta når det som de ræddast kjem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'når det de ræddast kjem som eit uver, og uferdi dykkar fer hit som ein storm, når trengsla og naud kjem på dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Då vil eg ikkje svara når de ropar på meg, dei skal naudleita etter meg, men ikkje finna meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Av di dei hata kunnskap og forsmådde otte for Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'ikkje lydde på mi råd, vanyrde all mi påminning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'skal dei eta frukt av si åtferd og verta mette av sine råder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'For einvisa drep dei einfaldne, og tryggleiken dårarne tyner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Men den bur trygt, som høyrer på meg, verna um ulukke-rædsla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Son min! tek du imot mine ord og gøymer bodi mine hjå deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'so du vender øyra til visdomen, bøygjer hjarta til vitet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'ja, når du kallar på skynet og ropar høgt på vitet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'leitar du etter det som vore det sylv, og grev som vore det løynde skattar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'då skal du skyna otte for Herren, og Guds-kunnskap skal du finna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'For Herren er den som gjev visdom, frå hans munn kjem kunnskap og vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Han gøymer frelsa for dei ærlege, han er ein skjold for dei som fer ulastande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'med di for han vaktar stigarne åt retten og varar vegen vel for sine trugne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Då skal du skyna rettferd og rett og rettvisa, ja, kvar god veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'For visdom koma skal i hjarta ditt, og kunnskap vera hugleg for di sjæl,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'yver deg skal ettertanke halda vakt, vit skal vara deg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'og fria deg ifrå den vonde åtferd, frå folk som talar fals,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'dei som gjeng frå dei rette stigar og vil vandra på myrke vegar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'dei som gled seg med å gjera vondt, og fegnast yver rangt og vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'dei som gjeng på kroke-stigar og fer på range vegar. -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Han skal fria deg frå annanmanns kona, frå framand kvinna med sleipe ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'som hev svike sin ungdoms ven og si Guds-pakt hev gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'For ho sig ned til dauden med sitt hus, og ned til daudingarne hennar vegar ber.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Ingen som gjeng inn til henne, kjem attende, og dei når ikkje livsens stigar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Han vil du skal ganga den vegen dei gode gjeng, og halda deg på dei stigane der rettferdige ferdast;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'for dei ærlege skal bu i landet, og dei ulastelege der skal verta att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'men dei ugudlege skal rydjast ut or landet, og svikarane skal verta rivne burt frå det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Son min, gløym ikkje læra mi! Lat hjarta varveitsla bodi mine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'For livetid lang og livs-år i mengd og velferd dei gjev deg i rikaste mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Lat ei kjærleik og truskap vika frå deg, men bitt deim um halsen på deg, skriv deim på di hjartetavla!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Då vinn du ynde og fær godt vit for augo på Gud og menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Lit på Herren av heile ditt hjarta men set ikkje lit til ditt vit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Tenk på honom i all di ferd! So jamnar han dine vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ver ikkje vis i eigne augo, ottast Herren og vik frå det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Det vert til helsebot for holdet ditt, og kveik for beini dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, '\'ra Herren med eiga di og med fyrstegrøda av all di avling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Då vert dine lødor rikleg fyllte, og safti renn yver i persorne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Son min, ei du vanvyrde Herrens age, og ver ikkje leid for hans refsing!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'For Herren agar den han elskar, som ein far med den son han hev kjær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Sæl den mann som hev funne visdom, og den mann som vinn seg vit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'For det er betre å kjøpa visdom enn sylv, og den vinning han gjev, er betre enn gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Dyrare er han enn perlor, av alle dine skattar er ingen som han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Langt liv hev han i høgre handi, og i vinstre rikdom og æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Hans vegar er hugnads-vegar, og alle hans stigar er velferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Han er livsens tre for deim som grip han, og dei som held han fast, er sæle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Med visdom hev Herren grunnfest jordi, med vit hev han laga himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Ved hans kunnskap fossa vatnet or djupi, og frå skyerne dryp det dogg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Son min! Slepp ikkje augo av deim, tak vare på visdom og ettertanke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'So skal dei vera liv for sjæli di og prydnad um halsen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Då vandrar du trygt din veg og støyter ikkje din fot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Når du legg deg, so kvekk du’kje upp, men du ligg og søv so godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Du skal ikkje ottast for bråstøkk, eller uver som yver ugudlege kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'For Herren skal vera di tiltru, og han skal vara din fot frå snara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Haldt ei burte det gode frå deim som treng det, når det stend i di magt å gjeva det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Seg ikkje til grannen din: «Gakk og kom att! Eg skal gjeva deg i morgon» - når du hev det no!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Tenk ikkje på vondt mot grannen din, når han bur trygt hjå deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Trætta ikkje med nokon utan grunn, når han ei hev gjort deg vondt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ovunda ikkje ein valdsmann, og vel ikkje nokon av alle hans vegar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'For den falske er ei gruv for Herren, men med ærlege hev han umgang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Herrens forbanning er i huset hjå den gudlause, men heimen åt rettferdige velsignar han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Gjeld det spottarar, so spottar han, men dei audmjuke gjev han nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Vismenner erver æra, men dårer ber med seg skam til løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Høyr etter, born, når far dykkar tuktar, og gjev gaum, so kann de læra å skyna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'For eg gjev dykk ein lærdom god; gakk ikkje frå mi upplæring!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'For eg var og barn for far min, og mor sin einaste veslegut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Då lærde han meg og sagde til meg: «Lat hjarta ditt hanga ved mine ord, tak vare på mine bod, so skal du liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Kjøp deg visdom, kjøp deg vit, Gløym ei, vik ei burt frå ordi eg segjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Gakk ei frå visdomen, so skal han vakta deg, elska han, so skal han vara deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Upphavet til visdom er: Kjøp deg visdom! Og kjøp deg vit for all di eiga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Set han høgt, so skal han upphøgja deg, han fører deg til æra når du tek han i fang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Han set på ditt hovud ein yndeleg krans, ei kruna so fager han gjev deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Høyr, min son, og tak imot mine ord, so vert dine livs-år mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Eg viser deg visdoms veg, eg fører deg fram på beine stigar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Når du gjeng, skal du stiga fritt, når du spring, skal du ikkje snåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Haldt fast på agen, slepp han ikkje, tak vare på han, for han er ditt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'På gudlause-stig må du ikkje koma, ei fara den vegen dei vonde fer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Lat han vera, gakk ikkje på han, vik frå han og kom deg undan!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'For dei søv ikkje, fær dei’kje synda, dei misser svevnen, fær dei ikkje folk til å falla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Gudløysa er det brødet dei et og vald er den vinen dei drikk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Men den stigen rettferdige gjeng, er som morgonglima som ljosnar og ljosnar til dagen renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Den vegen dei ugudlege gjeng, er som kolmyrkret, dei veit ikkje kva dei snåvar i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Son min, agta på ordi mine, vend ditt øyra til det eg segjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Lat dei ikkje vika frå augo dine, vara dei djupt i hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'For det er liv for kvar som finn det, og lækjing for heile hans likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Framfor alt som du vaktar, tak vare på hjarta, for livet gjeng ut frå det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Haldt svik med munnen ifrå deg, og burt med falske lippor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Lat augo dine sjå beint fram, og augnekasti skoda ende fram for deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Jamna stigen for din fot, og lat alle dine vegar vera støde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Vik ei til høgre eller vinstre, vend foten ifrå det vonde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Son min, gjev agt på min visdom, lut øyra ned til mitt vit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'So du kann halda deg gløggtenkt, og lipporne gøyma på kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'For honning dryp av skjøkjelippor, og hennar gom er sleipar’ enn olje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'men til slutt er ho beisk som malurt, kvass som eit tvieggja sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Hennar føter stig ned til dauden, hennar fet fører radt til helheims.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Ho gjeng ikkje livsens stig, gålaus vinglar ho vegvill.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Og no, søner, høyr på meg, og vik ikkje frå det munnen min mæler!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Lat din veg vera langt frå henne, kom’kje nær til husdøri hennar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Annars gjev du din vænleik til andre, åt ein hardstyrar åri dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Av di eiga vil framande mettast, det du samla med stræv, kjem i annanmanns hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'so du lyt stynja til slutt når ditt hold og kjøt er upptært,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'og segja: «Kor kunde eg hata tukt, og hjarta mitt vanvyrda age?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Kvi høyrde eg ikkje på meistrarne mine, og lydde på deim som lærde meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Nær var eg komen ille i det midt i mengdi som sat til tings.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Drikk or din eigen brunn, det som renn or di eigi kjelda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Skulde kjeldorne dine renna på gata, vatsbekkjerne dine ute på torgi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Lat deim vera berre for deg, og ikkje for framande med deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Kjelda di vere velsigna, gled du deg i din ungdoms viv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Elskhugs-hindi, ynde-gasella - barmen hennar alltid deg kveikje, stødt vere du trylt av hennar kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Kvi skulde du, son min, tryllast av onnor kona, og femna barmen på framand kvinna?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'For Herren hev kvar manns vegar for augo, og han jamnar alle hans stigar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Den gudlause vert fanga i misgjerningarne sine, hans synde-band bind honom fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Han døyr av di han ikkje let seg aga, og ved sin store dårskap tumlar han i koll.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Hev du borga for grannen din, son min, hev du handtekest for ein annan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'er du bunden ved ord av din munn, er du fanga i ord av din munn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'gjer då soleis, son min, og berga deg, sidan du er komen i handi på grannen: Gakk og kasta deg ned for grannen, gjer ågang på han,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'unn ikkje dine augo svevn, eller augneloki ein blund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Frels deg som ei gasella or handi hans, som ein fugl or fangarvald!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Gakk til mauren, du leting, sjå hans ferd og vert vis!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Han hev ingen hovding eller fut eller herre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'men lagar um sumaren maten sin til og hev um hausten sanka si føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Kor lenge vil du liggja, du leting? Når ris du upp or di svevn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Endå litt svevn, endå litt blunding, endå litt kvild med henderne i kross,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'so kjem armodi di som ein farande fant og naudi som skjoldvæpna mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Ugagns menneskje, illgjerningsmann, er den som gjeng og rengjer munnen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'som blinkar med augo, skrapar med foten, peikar med fingrarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'med meinspel i hjarta, alltid emnar på ilt, og yppar trættor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Difor kjem hans undergang brått, snøgt vert han ulækjande krasa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Det er seks ting som Herrens hatar, og sju er ei gru for hans sjæl:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Storlåtne augo, ljugartunga, hender som renner ut skuldlaust blod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'hjarta som tenkjer upp vonde råder, føter som renner rapt til vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'den som lyg og vitnar falskt, den som yppar strid millom brør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Son min, tak vare på bodet åt far din, og kasta’kje frå deg læra åt mor di!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Bitt deim alltid til hjarta ditt, knyt deim um halsen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Når du gjeng, skal læra leida deg; når du ligg, skal ho vaka yver deg; når du vaknar, skal ho tala til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'For bodet er ei lykt og lovi er ljos, og påminning med tukt er livsens veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Dei kann vara deg frå den vonde kvinna, frå den sleipe framande tunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ikkje trå i hjarta etter vænleiken hennar, og lat ho’kje fanga deg med augneloki sine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'For skjøkja armar ut til siste brødbit, og gifte kona jagtar etter dyre livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Kann nokon taka eld i fanget og ikkje brenna klædi sine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Ell’ kann ein gå på gløder og ikkje svida føterne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'So vert det med den som gjeng inn til kona åt grannen; ingen kjem urefst frå det, um han rører henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Vert ikkje tjuven vanvyrd, um han stel og vil stilla sin svolt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Vert han teken, lyt han sjufaldt betala, alt han eig i sitt hus, lyt han gjeva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Den som driv hor med ei kona, er vitlaus, den som vil tyna seg sjølv, gjer slikt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Hogg og skjemsla fær han, og ingen utslettar hans skam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'For mannen harmast i åbryskap, på hemnsdagen sparer han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Han bryr seg ikkje um nokor bot og tek’kje imot um du gjev han mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Son min, tak vare på ordi mine, og gøym mine bodord hjå deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Tak vare på bodordi mine, so skal du liva, og på læra mi som din augnestein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Bitt deim på fingrarne dine, skriv deim på hjartetavla!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Seg til visdomen: «Du er mi syster», og kalla vitet din ven,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'so dei kann deg vara frå annanmanns kona, frå ei framand kvinna med sleipe ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'For gjenom vindauga mitt, gjenom rimarne glytte eg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Då såg eg millom dei fåkunnige, eg gådde ein uviting millom dei unge,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'som smaug um hyrna på gata, tok vegen til hennar hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'i skumings-stundi, mot kvelden, i kolmyrke svarte natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Då kom kvinna imot han i skjøkjebunad og innful i hjarta -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'bråkande er ho og vill, heime hev ho’kje ro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Snart på gata, snart på torgi, med kvart hyrna stend ho på lur -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Ho tok fat på han og kysste han, og med ubljug uppsyn sagde ho til han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '«Eg hev på meg eit gilde-offer, og eg held min lovnad i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Difor gjekk eg ut imot deg, vilde leita deg upp, og eg fann deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Mi seng hev eg reidt med tæpe, med egyptiske roselakan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Eg hev skvett utyver mi lega myrra, aloe og kanel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Kom til ein kjærleiks rus alt til morgons, lat oss hyggja oss saman i elskhug!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'For mannen er ikkje heime, han er på ferd langt burte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'pengepungen tok han med seg, ved fullmånetid kjem han heim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Ho fekk lokka han med all si sterke fyreteljing, forførde han med sine sleipe lippor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Han fylgjer henne straks, som ein ukse gjeng til slagt, som i fotjarn til tukt for dåren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'til dess pili kløyver hans livr, som fuglen skundar til snara og veit ikkje at det gjeld livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Og no, søner, høyr på meg, og lyd på det munnen min talar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Ei vende du hjarta til hennar vegar, vimra ikkje på hennar stigar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'For mange med ulivssår hev ho felt, og stort er talet på deim ho hev drepe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Hennar hus er vegar til helheim, dei gjeng ned til daudens kot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Høyr kor visdomsmøyi ropar, og vitet høgmælt talar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Uppe på haugar ved vegen, der stigarne møtest, stend ho,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'attmed portarne ut or byen, ved døra-inngangen ropar ho høgt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '«Godtfolk, eg ropar på dykk, og til mannsborni ljomar mi røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Fåkunnige, lær dykk klokskap, og de dårar, vinn dykk vit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Høyr, eg talar gjæve ord, og ærlegt er det som lipporne segjer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'ja, sanning talar min gom, og lipporne styggjest ved gudløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Alle ord i min munn er rette, det finst ikkje fult eller falskt i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Dei er alle sanne for den kloke og rette for deim som fann kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Tak då min age heller enn sylv og kunnskap framfyre utvalt gull!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'For visdom er betre enn perlor, og av alle skattar er ingen som denne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Eg, visdomen, skyner meg på klokskap, og vit på rådleggjing hev eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Otte for Herren er hat til det vonde; stormod og storlæte, åtferd stygg, og ein munn full av fals eg hatar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Hjå meg er råd og dug, eg er vit, hjå meg er magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Eg gjer at kongar råder, og at hovdingar dømer rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Eg gjer at styrarar styrer og fyrstar - alle domarar på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Eg elskar deim som meg elskar, og dei som leitar meg upp, skal meg finna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Rikdom og æra er hjå meg, gamalt gods og rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mi frukt er betre enn gull, ja skiraste gullet, og den vinning eg gjev, er betre enn utvalt sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Eg gjeng på rettferds veg, midt på rettvise-stigar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'For eg vil gjeva gods åt deim som elskar meg og fylla deira forråd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Herren skapte meg til fyrste verket sitt, fordom fyrr han gjorde noko anna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Alt frå æva er eg innsett, frå upphavet, fyrr jordi vart til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Fyrr djupi var til, vart eg fødd, då det ei fanst kjeldor fulle med vatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'fyrr fjelli var søkkte ned, fyre haugar vart eg fødd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'fyrr han skapte jord og mark og den fyrste moldklump i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Då han laga himmelen, var eg der, då han slo kvelv yver djupet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Då han feste skyerne i det høge, då kjeldorne fossa fram or djupet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'då han sette grensa for havet, so vatnet ei gjekk lenger enn han baud, då han la grunnvollar for jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'då var eg verksmeister hjå han og var til hugnad for han dag etter dag, eg leika meg stødt for hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Eg leika på heile jordkringen hans og hadde min hugnad i manneborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Og no, born, høyr på meg! Sæle er dei som held mine vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Høyr på tukt og vert vise, og slepp ho ikkje ifrå dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Sæl den mann som høyrer på meg, so han dagstødt vaker ved dørerne mine og vaktar dørstokkarne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'For den som finn meg, finn livet og fær velsigning frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Men den som missar meg, skader seg sjølv, og alle som hatar meg, elskar dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Visdomsmøyi hev bygt seg hus, hev hogge til sine stolpar sju.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Ho hev slagta sitt slagt og blanda sin vin og attåt duka sitt bord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Sine ternor hev ho sendt ut, og ropar ovan frå haugarne i byen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '«Den som er fåkunnig, vende seg hit!» Til den vitlause segjer ho:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '«Kom, og et av mitt brød og drikk av den vin eg hev blanda!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Lat fåkunna fara so de kann liva og vandra på vegen til vit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Den som refser ein spottar, fær skam yver seg, den som lastar ein gudlaus, fær seg ein flekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Lasta’kje spottaren, han vil hata deg! Lasta den vise, han vil elska deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Gjev ein vismann, so aukar hans visdom, lær ein rettferdig, so lærar han meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Otte for Herren er upphav til visdom, og vit er å kjenna den Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, '«For ved meg dine dagar skal aukast, og fleire livs-år fær du.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Er du vis, so gagnar det deg sjølv, spottar du, so lyt du bera det åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Fru dårskap fer med ståk, fåkunnig som ho er og ingen ting veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Ho sit attmed husdøri si, på ein stol høgt uppe i byen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'og bed inn dei som ferdast på vegen, som gjeng sine stigar beint fram:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '«Den som er fåkunnig, vende seg hit!» Ja, til den vitlause segjer ho:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '«Stole vatn er søtt, og ljuvlegt er løyn-ete brød.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Og han veit’kje at der bur daudingar, at hennar gjester er i helheims djup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Ordtøke av Salomo. Ein vis son er til gleda for far sin, men ein dårleg son er mor si til sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Ragn-fegne skattar gagnar inkje, men rettferd frelser frå dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Herren let ikkje rettferdig mann hungra, men giren hjå gudlause viser han burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Lat-hand skaper armod, men strevsam hand gjer rik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Ein klok son sankar um sumaren, ein skjemdar-son søv um hausten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Velsigningar kjem yver hovudet på den rettferdige, men munnen åt dei gudlause gøymer vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Minnet um den rettferdige ert til velsigning, men namnet åt dei gudlause morknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Den vise tek imot påbod, men gapen gjeng til grunns,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'den som ferdast i uskyld, ferdast trygt, men den som gjeng krokvegar, skal verta kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Den som blinkar med auga, valdar vondt, men gapkjeften gjeng til grunns.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Rettferdig manns munn er ei livsens kjelda, men munnen åt gudlause gøymar vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Hat yppar trætta, men kjærleik breider yver alle brot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'På vitug manns lippor er visdom å finna, men riset høver åt ryggen på dåren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Dei vise gøymer kunnskapen sin, men or narremunn kann ein venta fåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Rikmanns eiga er hans faste by; fatigfolks ulukka er deira armod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Det den rettferdige tener, gjeng til liv, det den gudlause vinn, gjeng til synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Den som på tukt tek vare, gjeng til livet, men den fer vilt som ikkje agtar age.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Den som løyner hat, hev ljugarlippor, og den som breider ut baktale, er ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Der d’er mange ord, vil synd ikkje vanta, men den som set lås for lipporn’, er klok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Rettferdig manns tunga er utvalt sylv, men gudløysings vit er lite verdt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Rettferdig manns lippor læskar mange, men dårarne døyr for dei vantar vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'D’er Herrens velsigning som gjer rik, og eige stræv legg inkje til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Dåren finn moro i skjemdarverk, men den vituge mannen i visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Det den ugudlege gruar for, kjem yver han, og det rettferdige ynskjer, vert deim gjeve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Der stormen hev fare, er den gudlause burte, men den rettvise stend på æveleg grunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Som edik er for tennerne og røyk for augo, so er letingen for den som sender han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Otte for Herren lengjer livet, men gudløysings år vert stytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Rettferdige kann venta gleda, men voni åt gudlause vert til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Herrens veg er vern for den skuldfri, men øydeleggjing for illgjerningsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Rettferdig mann skal aldri rikkast, men gudlause skal ei få bu i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Rettferdig manns munn ber visdoms frukt, men avskori vert den falske tunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Rettferdig manns lippor søkjer hugnad, men munnen på gudlause berre fals.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Falsk vegt er fæl for Herren, men full vegt likar han godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kjem stormod, so kjem og skam, men smålåtne, dei hev visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Dei ærlege hev si uskyld til førar, men fals slær sin herre på hals.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Gods hjelper ikkje på vreidens dag, men rettferd frelser frå dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, '\'rleg manns rettferd jamnar hans veg, men den gudlause stuper ved gudløysa si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, '\'rlege folk ved si rettferd vert frelste, men dei falske vert fanga i eigen gir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Når ugudleg mann døyr, er det ute med voni; og vondskaps venting til inkjes vert.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Rettferdig vert fria or trengsla, og ugudleg kjem i hans stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Den skamlause tyner sin granne med munnen, men rettferdige friar seg ut med sin kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Gjeng det godt med rettferdige, fegnast byen, vert gudlause tynte, syng folk av gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Med velsigning frå ærlege folk kjem byen seg upp, men gudlause munn bryt han ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Vitlaus er den som vanvyrdar sin granne, men vitug mann tegjer stilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Den som fer med drøs, ber løynråd ut, men den hjarte-trugne løyner saki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Der inkje styre er, lyt folket falla, men der dei rådvise er mange, der er frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Borgar du for framand, er du ille faren, men han er trygg som hatar handtak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Ei yndefull kvinna vinn æra, og valdsmenner vinn seg rikdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Ein godhjarta mann gjer vel mot si sjæl, men ein hardhjarta mann fer vondt med sitt eige kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Den ugudlege vinn seg ei sviksam løn, men den som rettferd sår, fær varig løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Stend du fast i rettferd, vinn du liv, men fer du etter vondt, då fær du daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Dei range i hugen hev Herren ein stygg til, men han likar deim som ulastande ferdast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Det kann du gjeva handi på, den vonde vert’kje urefst, men ætti åt rettferdige slepp undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Som ein gullring i eit grisetryne er ei fager kvinna utan vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Det rettferdige ynskjer, vert berre godt, det som gudlause vonar, vert til vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Ein strår ut og fær endå meir, ein annan vert arm av usømeleg sparing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Den som velsignar, skal trivast, og kveikjer du andre, vert sjølv du kveikt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Ein kornflår, honom bannar folket, men signing kjem yver den som sel korn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Den som strævar etter godt, han søkjer hugnad, men den som leitar etter vondt, han fær det yver seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Den som lit på sin rikdom, han skal stupa, men rettferdige grønkar som lauv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Den som øydar sitt hus, skal erva vind, og narren vert træl åt den kloke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Rettferdig manns frukt er eit livsens tre, og sjæler vinn den vise.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Du ser rettferdig mann fær vederlag på jordi, kor mykje meir då den ugudlege og syndaren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Den som elskar age, elskar kunnskap, men den som hatar refsing, han er fåvis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Den gode vinn seg hugnad hjå Herren, men den meinsløge fordømer han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ingen mann vert stød av gudløysa, men roti åt rettferdige kann ingen rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Ei fagna kona er ein krans for mannen sin, eit skjemda ting er fæl som ròt i beini hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Tankar hjå rettferdige tenkjer er det som rett er, dei råder som ugudlege legg upp, er svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Ordi hjå ugudlege gjeng ut på luring etter blod, men ærlege vert berga ved sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Ugudlege vert kasta i koll, og so er det ute med deim, men rettferdige folks hus stend fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Ein mann fær ros alt etter som vitet hans er, men den ranglyndte kjem i vanvyrdnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Betre småmann med ein tenar enn låst vera storkar og ikkje ha mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Den rettferdige veit korleis buskapen har det, men hardt er hjarta hjå ugudlege folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Den som dyrkar si jord, fær mette av brød, den som fer etter fåfengde ting, er fåvis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Ein gudlaus hev hug til vonde folks garn, men roti åt rettferdige gjev frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Lippe-synd er snara vond, men den rettferdige slepp ut or trengsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Av sin munns frukt fær ein mann sin gode mette, og eit menneskje fær att det han hev gjort med sine hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Uvitingen held sin eigen veg for den rette, men den vise høyrer på råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Når uvitingen er vreid, vert det kjent same dagen, men den kloke løyner skjemsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Den som andar ærlegskap, segjer det som rett er, men det falske vitnet talar svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Mang ein fer med svall som sverdstyng; men tunga åt dei vise, ho er lækjedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Sanningslippa held seg æveleg, men falske tunga berre i ein augneblink.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Svik er i deira hjarta som smider vondt i hop, men dei som rå’r til fred, hev gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Inkje vondt den rettferdige råkar, men gudlause fær ulukka i fullaste mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Ei stygja for Herren er ljugarlippor, men han likar deim som fer fram med truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Ein klok mann løynar kunnskap, men dåre-hjarta ropar ut vitløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Strævsam hand kjem upp til herrevelde, men leta fører til trældom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Sorg i mannens hjarta bøygjer det ned, men eit godt ord gjev det gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Den rettferdige rettleider næsten sin, men vegen åt gudlause fører deim vilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Letingen steikjer ikkje si veidn, men annsemd er rikdom so dyr for menneskja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'På rettferds stig er liv, og gonga på vegen gjeng ikkje til dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Den vise son let seg aga av far sin, men spottaren høyrer ikkje på skjenn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Sjølv fær ein godt av den frukt som munnen ber, men hugen åt svikarar stend etter vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Den som agtar munnen sin, varar si sjæl, men gapen fær seg ei ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Hugen i letingen lyster og fær ikkje noko, hugen i strævsame folk fær rikleg mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Den rettferdige hatar ljugarord, men den gudlause fer stygt og skamleg åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Rettferd varar den som fer ulastande, men gudløysa feller den som gjer synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Mang ein ter seg rik og eig då inkje, ein annan ter seg fatig og eig mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Mannsens rikdom er ein løysepeng for livet hans, men fatigmannen fær inkje trugsmål høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Ljoset åt dei rettferdige brenn lystigt, men lampa åt ugudlege vil slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Med ovmod veld ein berre trætta, men hjå deim som tek mot råd, er visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Lettfengen rikdom minkar, men sankar du smått um senn, fær du meir og meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Langdrøg von gjer hjarta sjukt, men uppfyllt ynskje er eit livsens tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Den som vanvyrder ordet, tyner seg sjølv, men den som ottast bodordet, fær løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Vismanns læra er livsens kjelda, so ein slepp undan frå daudesnaror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Godt vit gjev manntekkje, men hard er vegen som svikarar gjeng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Kvar som er klok, fer fram med vit, men ein dåre briskar seg med dårskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Ein gudlaus sendemann fell i ulukka, men trufast bodberar er lækjedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Armod og skam fær den som viser age ifrå seg, men den som agtar på refsing, vinn æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Uppfyllt ynskje er søtt for sjæli, men å vika frå vondt er ei gruv for dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Gakk saman med dei vise, so vert du vis, men ilag med dårar gjeng det deg ille.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Ulukka forfylgjer syndarar, men rettferdige fær godt til løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Den gode let etter seg arv til barneborn, men det syndaren eig, er gøymt åt den rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Fatigfolks nybrot gjev rikeleg føda, men mang ein vert tynt ved urettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Den som sparer riset sitt, hatar son sin, men den som elskar han, tuktar honom tidleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Rettferdige hev mat til å metta seg på, men gudlause gjeng med magen tom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Kvinnevisdom byggjer huset sitt, men dårskap riv det ned med henderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Den som ottast Herren, fer ærleg fram, men krokvegar gjeng den som vanvyrder honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'I narrens munn er ovmods ris, men dei vise hev lipporne sine til vern.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Utan uksar er krubba tom, men når stuten er sterk, vert innkoma stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Ikkje lyg eit ærlegt vitne, men det falske vitne andar lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Spottaren søkjer visdom, men fåfengt, men lett finn den skynsame kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Gakk burt frå ein dåre, ei fekk du der merka lippor med kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Klok manns visdom er: han skynar vegen sin, men dåre-narreskapen er: dei svik seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Dårar fær spott av sitt eige skuldoffer, men millom ærlege folk er godhug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Hjarta kjenner si eigi sorg, og gleda legg ingen framand seg uppi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Gudlause folk fær sitt hus lagt i øyde, men ærlege folk ser tjeldet sitt bløma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Mang ein veg tykkjer folk er rett, men enden på honom er vegar til dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Jamvel midt i låtten kjenner hjarta vondt, og enden på gleda er sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Av åtferdi si skal den fråfalne mettast, og ein god mann held seg burte frå han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Den einfalde trur kvart ordet, men den kloke agtar på sine stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Den vise ottast og held seg frå vondt, men dåren er brålyndt og trygg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Bråsinna mann gjer narreverk, og meinsløg mann vert hata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Einfalde erver dårskap, men dei kloke fær kunnskap til krans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Vonde skal bøygja seg for dei gode, og gudlause ved portarne til den rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Ein fatig vert hata av venen sin jamvel, men ein rik vert elska av mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Vanvyrder du næsten din, syndar du, men sæl den som ynkast yver armingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Skal ikkje dei fara vilt som finn på vondt, og miskunn og truskap timast deim som finn på godt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Alt stræv fører vinning med seg, men tome ord gjev berre tap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Rikdomen er for dei vise ei krans, men narreskapen hjå dårar er narreskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Eit sanningsvitne bergar liv, men den som andar lygn, er full av svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Den som ottast Herren, hev ei borg so fast, og for hans born det finnast skal ei livd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Otte for Herren er livsens kjelda, so ein slepp undan daudesnaror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Mykje folk er konungs prydnad, men folkemink er hovdings fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Langmodig mann hev mykje vit, men bråhuga mann syner narreskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Spaklyndt hjarta er likamens liv, men ilska er ròt i beini.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Trykkjer du armingen, spottar du skaparen hans, men du ærar skaparen når du er mild mot fatigmann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'I ulukka si lyt den gudlause stupa, men den rettferdige hev trygd når han skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'I hjarta på den vituge held visdomen seg still, men hjå dårar ter han seg fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Rettferd upphøgjer eit folk, men syndi er skam for folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Kongen likar godt den kloke tenar, men harmast på den som skjemmer seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Mildt svar døyver harm, men eit kvast ord vekkjer vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Tunga åt vismenner gjev god kunnskap, men narreskap gøyser or munnen på dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Allstad hev Herren augo sine, dei ser etter vonde og gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Linnmælt tunga er livsens tre, men range tunga gjev hjartesår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Ein uviting vanvyrder far sin’s age, men den som agtar på refsing, vert klok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Rettferdig manns hus eig stor rikdom, men d’er ugreida med ugudleg manns inntekt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Vismanns-lippor strår ut kunnskap, men so er ei med dårehjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Gudløysings offer er ei gruv for Herren, men bøn frå ærlege han likar godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Gudløysings veg er ei gruv for Herren, men han elskar den som renner etter rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Hard refsing fær den som gjeng ut av vegen, den som hatar age, skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Helheim og avgrunn ligg i dagen for Herren, kor mykje meir då menneskje-hjarto.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Spottaren likar ikkje at ein lastar honom, til vismenner gjeng han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Gladværugt hjarta gjer andlitet ljost, men modet vert brote i hjartesorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Vitug manns hjarta søkjer kunnskap, men dåremunn fer berre med narreskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Alle ein armings dagar er vonde, men den glade i hjarta hev gjestebod alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Betre er lite med otte for Herren enn eigedom stor med uro attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Betre ei nista av kål med kjærleik til enn gjødde uksen med hat attåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Brålyndt mann valdar trætta, men den toluge stiller kiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Vegen for letingen er som eit klungergjerde, men stigen er brøytt for dei ærlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Ein vis son gjer far sin gleda, men eit dårlegt menneskje vanvyrder mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Dårskap er gleda for vitlaus mann, men ein vitug mann gjeng beint fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Råder vert til inkjes utan rådleggjing, men med mange rådgjevarar kjem dei i stand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Mannen gled seg når munnen kann svara, og eit ord i rette tid, kor godt det er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Den vituge gjeng livsens veg uppetter, for han vil sleppa burt frå helheimen der nede.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Herren riv huset ned for dei ovmodige, men for enkja let han merkesteinen standa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Vonde tankar er ei gruv for Herren, men milde ord er reine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Den vinnekjære fær sitt hus i ulag, men den som hatar mutor, han skal liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Rettferdig tenkjer i sitt hjarta korleis han skal svara, men gudlause let vondskap gøysa ut or munnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Langt er Herren burte frå dei gudlause, men bøni frå rettferdige han høyrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Ljos i augo hjarta gled, tidend god gjev merg i beini.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Det øyra som høyrer på rettleiding til livet, held seg gjerne med vismenn i lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Den som vandar age, vanvyrder si sjæl, den som høyrer på rettleiding, vinn seg vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Otte for Herren er age til visdom, og fyre æra gjeng andmykt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Hjartans rådleggjing høyrer menneskja til, men tunga fær svaret frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Kvar mann tykkjer at hans eigi ferd er rein, men det er Herren som prøver ånderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Legg verki dine på Herren, so skal tankarne dine få framgang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Herren hev gjort kvar ting til sitt endemål, ogso den ugudlege til uferdsdagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Kvar ovmodig er ei gruv for Herren, du kann vera viss, han skal’kje verta urefst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Med kjærleik og truskap vert misgjerning sona ut, med otte for Herren flyr ein frå det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Når Herren likar ferdi åt ein mann, so let han jamvel fiendarne halda fred med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Betre er lite med rettferd enn innkomor store med urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Mannsens hjarta tenkjer ut sin veg, men Herren styrer hans stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Gudsord er på konungs lippor, i domen skal hans munn ei gjera mistak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Rett vegt og rette vegtskåler høyrer Herren til, hans verk er alle lodd i pungen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Ugudleg åtferd er ein styggedom for kongar, for truna stend trygt ved rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Kongen likar rettferdige lippor, dei elskar den som segjer det som er rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Konungs vreide er daude-bod, men ein vismann stiller vreiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'I ljos frå konungs åsyn er det liv, og hans godhug er som ei regnsky um våren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Å vinna visdom - kor mykje betre er det ei enn gull! Å vinna vit er meire verdt enn sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Den vegen dei ærlege gjeng, er å fly frå vondt, den som agtar på sin veg, han varar si sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Fyre undergang gjeng ovmod, og stormod fyre fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Betre er med armingar å vera audmjuk enn skifta herfang med ovmodige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Den som agtar på ordet, skal finna lukka, den som lit på Herren - sæl er han!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Den vise i hjarta vert kalla vitug, og søtleik på lipporne aukar lærdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Klokskap er livsens kjelda for deim som eig han, men fåvit er refsing for fåvise folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Vismanns hjarta gjer munnen hans vitug og aukar læra på lipporne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Milde ord er honningdropar, søte for sjæli og lækjedom for beini.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Mang ein veg tykkjer folk er rett, men enden på honom er vegar til dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Vinne-kars hunger onnar for honom, for hans eigen munn driv på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Ein låk mann grev ei ulukke-grav, og det logar som eld på lipporne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Ein ranglyndt mann yppar trætta, og den som ber drøs, skil ven frå ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Ein valdsmann lokkar næsten sin, og leider han inn på ein veg som ei er god.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Den som let augo att, vil tenkja range tankar, den som knip lipporne i hop, set vondt i verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Grå hår er fager krans! Han er å vinna på rettferds veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Ein tolug mann er betre enn ei kjempa, og den som styrer hugen sin, stend yver den som tek ein by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Dei kastar terningen i fanget, men all hans avgjerd kjem frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Betre er ein turr brødmole med ro attåt enn huset fullt av høgtidskost med trætta til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Den kloke tenar skal råda yver ein uvisleg son, og millom brøder fær han skifta arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Diglen røyner sylvet og omnen gullet, men den som røyner hjarto, det er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Den vonde lyder på vondskapslippa, ljugaren lyder på tyningstunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Spear du den fatige, so spottar du hans skapar, den som gled seg yver ulukka, skal få si refsing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Ein krans for dei gamle er barneborn, og ei æra for borni er federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Det høver ikkje for ein dåre å tala store ord, enn mindre for ein fagnamann å ljuga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Gåva er ein glimestein for den som fær ho; kvar ho vender seg, der fær ho framgang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Søkjer du kjærleik, skyler du misgjerd, men riv du upp att ei sak, skil ven frå ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Vondord gjer meir på den vituge enn hundrad hogg på dåren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Berre upprør søkjer den vonde, men ein hard bodberar vert send imot han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Møt heller ei binna som hev mist sine ungar enn ein dåre med narreskapen hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Den som løner godt med vondt, frå hans hus skal ikkje det vonde vika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Å taka til med strid er som å sleppa vatn ut, haldt difor upp med trætta fyrr nokon gliser med tennerne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Den som frikjenner ein ugudleg og den som domfeller ein rettferdig, dei er båe tvo ein styggedom for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Kva skal pengar i handi på dåren? Å kjøpa visdom hev han’kje vit til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Venen elskar alltid, og bror vert fødd til hjelp i naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Ein vitlaus mann er den som handtekst, som gjeng i borg hjå grannen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Den som elskar trætta, elskar misgjerning, den som byggjer døri si høg, søkjer fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Den som hev eit rangt hjarta, vinn ikkje lukka, og den som forvender tunga si, fell i ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Den som avlar eit narr, fær sorg, og ikkje gled seg far til ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Gladværugt hjarta gjev lækjedom god, men nedslege mod fær beini te visna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Gudlaus mann tek gåva i løynd til å bøygja rettargangen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Den vituge hev visdom for augo, men dåren hev augo ved heimsens ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Uvitug son er til gremme for far sin, og beisk sorg for henne som fødde’n.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Det er’kje godt at og rettferdige fær refsing, og ei at fagna folk fær slag for det som rett er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Den skynsame sparer på ordi, og den vituge mann er kald i hugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Um dåren tagde, gjekk han og for vismann, og for ein vitug mann når han heldt munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Einstødingen søkjer det han sjølv er huga på, mot alle kloke råder glefser han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Dåren bryr seg ikkje um å vera vitug, men vil berre visa kva som bur i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Kjem ein ugudleg, so kjem og vanvyrdnad, og med skam fylgjer spott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Ordi i ein manns munn er djupe vatn, fløymande bekkjer, visdoms kjelda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'D’er’kje godt når ein gjev den gudlause medhald og rengjer rettferdig manns rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Dåre-lippor kjem uppi trætta, og munnen hans ropar etter slag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Dåre-munn er til ulukka for han sjølv, og lipporne er ei snara for hans sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Baktalar-ord er som lostemat, dei glid so godt ned i livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Den som er lat i arbeidet sitt, han er og bror til øydaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Herrens namn er eit tårn so sterkt, der flyg den rettferdige inn og vert berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Rikmanns eiga er hans faste by, som høge muren i hans eigne tankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Fyre fall er mannsens hjarta stolt, men fyre æra gjeng audmykt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Um nokon svarar fyrr han høyrer, vert det til narreskap og til skam for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Manns mod ber uppe i sjukdom, men brote mod, kven kann bera det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Vitug manns hjarta kjøper kunnskap, og øyra åt vismenner søkjer kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Gåva opnar mannen veg og fører han fram til storfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Den som fyrst legg fram si sak, fær rett, men so kjem motparten og granskar honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Lutkasting endar trettor og skil millom megtige menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Hev ein bror lide urett, er han verre å vinna enn ein festningsby, og trættor er som stengsa for eit slott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Mannen fær magen sin mett av frukti or munnen sin, av grøda frå lipporne vert han mett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Tunga hev daude og liv i sitt vald, dei som elskar henne, skal eta hennar frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Den som hev funne ei kona, hev funne lukka og hev fenge ei nådegåva av Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Den fatige bed og barmar seg, men den rike svarar med harde ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Ein mann med mange vener gjeng det ille, men ven kann vera trugnare enn nokon bror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Betre er ein fatigmann som ferdast lytelaust enn ein mann med range lippor som attpå er ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Den som er tankelaus i hugen, gjeng det gale, og den som stig for fort med føterne, han stig i miss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Mannsens eigi vitløysa fører til fall, men han harmast i sitt hjarta på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Velstand samla mange vener, men fatigmann vert skild frå venen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Det falske vitnet skal’kje verta urefst, og den som andar lygn, skal ikkje sleppa undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Mange smeikjer den gjæve, og kvar mann er ven med den rauste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Fatigmanns brør hatar honom alle, enn meir dreg hans vener seg burt frå honom. Han fer etter ord som er inkjevetta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Den som elskar si sjæl, han vinn seg vit, den som vaktar sitt skyn, skal finna lukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Det falske vitnet skal’kje verta urefst, og den som andar lygn, skal tynast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Det høver ei for dåren å hava gode dagar, enn mindre for ein træl å råda yver hovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Mannsens klokskap gjev honom tol, og det er hans æra å tilgjeva brot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Konungs harm er som når løva burar, men godhugen hans er som dogg i graset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Ein dårleg son er reint ei ulukka for far sin, og kjerringtrætta er som si-drop frå taket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Hus og gods er fedre-arv, men frå Herren kjem ei vitug kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Leta svæver tungt i svevn, og letingen skal svelta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Den som tek vare på bodet, tek vare på sitt liv, den som ei ansar si åtferd, skal missa livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Den som gjer miskunn mot armingen, låner til Herren, og av honom fær han vederlag for si velgjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Aga son din, for endå er det von, men lat deg ikkje driva til å drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Den som er svært sinna, lyt bøta for det, for um du hjelper han, du gjer vondt verre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Høyr på råd og lat deg aga, so du til slutt kann verta vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Mange tankar er i mannsens hjarta, men Herrens råd fær framgang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Mannsens miskunn er hans gode vilje, og fatig man er betre enn ein som lyg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Otte for Herren fører til liv, mett fær ein kvila og vert ikkje heimsøkt med vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Stikk den late si hand i fatet, so idest han ei ta ho upp att til munnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Slær du spottaren, so vert uvitingen klok, og agar du den vituge, so fær han vit på kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Den som er vond med far sin og jagar mor si burt, han er ein son til skam og skjemd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Høyr ikkje soleis på refsing, son min, at du villar deg burt frå kunnskaps ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Eit nidings-vitne spottar det som rett er, og munnen på gudlause gløyper urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Refsingsdomar er ferdige for spottaren og slag for ryggen på dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Vinen er ein spottar, rusdrykken ein ståkar, ingen som tumlar av honom, er vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Den rædsla kongen vekkjer, er som løveburing, den som fær hans vreide på seg, set livet sitt på spel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Mannsens æra er å halda seg frå trætta, men kvar uviting glefser til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Letingen pløgjer ikkje um hausten, i skurdonni leitar han fåfengt etter grøda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Råd i mannsens hjarta er som vatn i djupet, men ein skynsam mann kann draga det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Mest kvar mann råkar ein som elskar honom, men kven finn ein som er å lita på?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Den som ferdast ulastande og er rettferdig, sæle er borni hans etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Ein konge som sit på domarstol, skil ut alt vondt med augo sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kven kann segja: «Eg hev halda hjarta reint og er fri frå syndi mi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Tvo slag vegt og tvo slag mål er båe tvo ein styggedom for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Alt guten syner i si gjerd um ferdi hans vert rein og rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Øyra som høyrer og auga som ser - Herren hev skapt deim båe tvo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Elska ikkje svevn, for då vert du fatig, haldt augo uppe, so fær du brød til mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '«Klent, klent!» segjer kjøparen, men når han gjeng burt, so rosar han seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Vel finst det gull og mange perlor, men dyraste gogni er lippor med kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Tak klædi hans! for han hev borga for ein annan, og panta honom for framande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Søtt er for mannen det brød han hev fenge med fals, men sidan vert munnen hans full av småstein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Råder vert stødige med rådleggjing, få då klok styring når du fører krig!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Den som fer med drøs, ber løynråd ut, og gapen skal du ikkje hava noko med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Den som bannar far og mor, hans lampa skal slokna i kolmyrkret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Ein arv som ein i fyrstundes er for fus på, vert på slutten utan velsigning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Seg ikkje: «Eg vil løna med vondt!» Venta på Herren, han vil hjelpa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Tvo slag vegt er ein styggedom for Herren, og den falske skålvegt er ikkje god.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Frå Herren kjem mannsens stig, og kor kann eit menneskje skyna sin veg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Fårlegt er det for eit menneskje å vigsla eitkvart tankelaust, og fyrst granska lovnaden etterpå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Ein vis konge skil ut dei gudlause og let hjulet ganga yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Menneskjens ånd er Herrens lampa, og ho ransakar alle rom i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Kjærleik og truskap er vakt um kongen, og han styd sin kongsstol på kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Ei æra for ungdomar er deira kraft, og ein prydnad for dei gamle er grått hår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Svidande sår reinser burt det vonde, ja, slag reinsar hjartans inste rom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Konungs hjarta er i Herrens hand som bekkjer, han vender det kvar helst han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Kvar mann tykkjer at hans eigi ferd er rett, men det er Herren som prøver hjarto.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'At folk gjer rett og skil, er meir verdt for Herren enn offer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Ovmods augo og sjølvgodt hjarta - lampa åt gudlause folk er synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Umtanke hjå den annsame er berre til vinning, men hastverk berre til tap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Skattevinning med ljugartunga er ein kvervande pust av deim som søkjer dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Den vald dei gudlause gjer, skal riva deim sjølve burt, for det som er, vil dei ikkje gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Skuldig mann gjeng krokut veg, men den reine - han gjer si gjerning beint fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Betre å bu i ei krå på taket enn å ha sams hus med trettekjær kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Ugudleg manns sjæl hev hug til det vonde, hans næste finn ikkje miskunn hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Refser du spottaren, vert uvitingen vis, og lærer du vismannen, tek han mot kunnskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Ein rettferdig agtar på gudlause-hus, han støyter dei gudlause ned i ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Dytter du øyra til for armings rop, skal sjølv du ropa og ikkje få svar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Gåva i løyndom stiller vreide, og gjeving i barmen stiller største harmen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Det er ei gleda for rettferdig mann å gjera rett, men ei rædsla for illgjerningsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Den som viller seg burt frå klokskaps veg, han skal hamna i skuggeheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Ein fatigmann vert den som elskar moro, ei vert han rik som elskar vin og olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Den gudlause vert løysepeng for den rettferdige, og utru kjem i staden for den ærlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Betre å bu i eit øydeland enn hjå arg og trættekjær kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Vismann hev dyre skattar og olje i huset, men uvitingen øyder det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Den som strævar etter rettferd og miskunn, han skal finna liv og rettferd og æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Ein by med kjempor tek vismannen inn, og han bryt ned den borgi som byen lit på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Den som varar sin munn og si tunga, han varar si sjæl frå trengslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Ein ovmodig og ubljug kallar me spottar, ein som fer fram med ofselegt ovmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Lysti åt letingen drep honom sjølv, for henderne hans vil inkje gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Heile dagen snikjer den snikne, men ein rettferdig gjev og sparer inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Offer frå gudlause er ei gruv, og endå meir når dei samstundes emnar på ilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Eit ljugar-vitne skal ganga til grunns, men ein mann som lyder etter, skal få tala alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Gudlaus mann ter seg skamlaus, men den ærlege gjeng sine vegar stødigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Det finst ingen visdom og inkje vit og ingi råd imot Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Hesten vert budd til herferdsdagen, men sigeren kjem ifrå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Eit godt namn er meir verdt enn rikdom stor, og manntekkje betre enn sylv og gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Rik og fatig råkast, Herren hev skapt deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Den kloke ser fåren og gøymer seg, men fåmingar renner fram og lyt bøta for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Løn for spaklynde og otte for Herren er rikdom og æra og liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Klunger og snaror er på den vegen den falske gjeng, den som agtar si sjæl, held seg burte frå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Lær guten etter som guten er, so vik han ikkje ifrå det, um han vert gamall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Rikmann rå’r yver fatigfolk, og den som fær lån, vert træl for den som gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Den som sår urett, skal hausta vondt, og hans ovmods ris fær ein ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Den godhjarta vert velsigna, for han gjev sitt brød til armingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Jaga spottaren ut, so gjeng trætta med, og for skjemsla og kiv fær du fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Den som elskar hjartans reinleik, den som talar vænt, han hev kongen til ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Herrens augo vaktar kunnskap, men ord frå den utrue støyter han um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Letingen segjer: «Det er ei løva der ute, eg kunde verta drepen midt på gata.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Ei djup grav er skjøkjemunn, den som Herren er harm på, skal falla nedi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Vitløysa heng fast ved hjarta hjå guten, men tukteriset driv henne burt frå han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Trykkjer du armingen, vert det honom til vinning, gjev du den rike, vert det berre til tap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Lut øyra ned og høyr på ord av vismenn vend hjarta til min kunnskap!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'For det er vænt at du deim varar i ditt hjarta; gjev dei må vera reiduge på dine lippor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Av di du skal lita på Herren, lærer eg deg i dag, just deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Hev eg’kje skrive fyndord til deg med råder og kunnskap');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'til å kunngjera deg det som rett er, sannings ord, so du med sannings ord kann svara deim som sender deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Plundra ikkje ein fatigmann av di han er fatig, og tred ikkje armingen ned i porten!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'For Herren skal føra saki deira og taka livet deira som tek ifrå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Gjev deg ikkje i lag med ein som snart vert vreid, og gakk ikkje med ein bråsinna mann,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'at du ikkje skal venja deg til hans vegar og få sett ei snara for livet ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ver ei millom deim som gjev handtak, millom deim som borgar for skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Når du inkje hev å betala med, kvifor skal dei taka sengi di burt under deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Flyt ikkje gamall merkestein som federne dine hev sett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Ser du ein mann som er dugleg i arbeidet, han skal tena hjå kongar og ikkje hjå småfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Når du sit til bords hjå ein hovding, so agta vel på kven du hev fyre deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'og set ein kniv på strupen din, um mathugen din er stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Fys ikkje etter hans lostemat, for det er dårande føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Mød deg ei med å verta rik, lat fara den klokskapen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Lat ei augo fljuga til det som kverv, for det gjer seg vengjer, det er visst, som ein ørn som flyg til himmels.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Et ikkje brød hjå den som misunner deg, og fys ikkje etter hans lostemat!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'For som han reknar ut i sjæli si, soleis er han. «Et og drikk!» han segjer til deg, men hjarta hans er ikkje med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'For biten din som du hev ete, lyt du spy upp att, og du hev spilt dine fagre ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'For øyro på dåren skal du ikkje tala, for han vanvyrder visdommen i dine ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Flyt ikkje gamall merkestein, og kom ei inn på åkrane åt faderlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'For deira målsmann er sterk, han skal føra saki deira imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Vend hjarta ditt til age og øyro dine til kunnskaps ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Lat ikkje guten vera utan age! Slær du han med riset, skal han ikkje døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Du slær han med riset, og sjæli hans bergar du frå helheim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Son min, vert hjarta ditt vist, so gled seg og mitt hjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'og nyro mine fegnast når lipporn’ dine talar det som rett er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Lat ikkje hjarta ditt misunna syndarar, men stræva stødt etter gudlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'For då er du viss på ei framtid, og di von skal ei verta til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Høyr du, son min, og vert vis, og lat hjarta ditt ganga beint fram på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ver ikkje med millom vindrikkarar, millom deim som foret seg på kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'For drikkar og storetar fatig vert, og svevn gjev fillor for klæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Høyr på far din som avla deg, og vanvyrd ei mor di når ho vert gamall!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kjøp sanning og sel henne ikkje, visdom og age og vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Storleg fegnast far til den rettferdige, og den som fær ein vis son, skal få gleda av han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Lat far din og mor di gleda seg, og ho som fødde deg, fegnast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Son min, gjev meg hjarta ditt, og lat dine augo lika vegarne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'For skjøkja er som djupe gravi og den framande kona som tronge brunnen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'ja, ho ligg på lur som ein ransmann, og ho aukar talet på utrue folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kven hev sorg? Kven hev sut? Kven hev dragsmål? Kven hev klagemål? Kven hev sjølvvalde sår? Kven hev dimsynte augo?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Dei som drygjer lenge hjå vinen, dei som kjem og smakar på mjøden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Sjå ikkje på vinen kor han raudnar, kor vænt han smiler i staupet! lett renn han ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Men sidan han sting som ein slange og høgg som ein orm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Då skal augo dine sjå rare syner, og hjarta ditt talar tull og tøv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Du vert som låg du i havsens djup, eller låg i toppen av mastri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '«Dei slo meg, men det gjorde’kje vondt, dei banka meg, men eg kjende det ikkje. Når skal eg vakna? Eg vil få tak i endå meir.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Misunn ikkje vonde menneskje, og hav ikkje hug til å vera med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'For hjarta deira tenkjer på vald, og um ulukka talar lipporne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Med visdom byggjer ein hus, og med vit grunngfester ein det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'og med kunnskap fær ein romi fulle av alle slag dyre og gilde ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Ein vis mann er sterk, og ein kunnig er veldug i kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Klok styring skal du bruka når du fører krig, hev du mange rådvise menn gjeng det godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Visdom heng for høgt for fåmingen, i porten let han ikkje upp sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Den som tenkjer på å gjere vondt, honom kallar me ein fuling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Synd er dårskaps råd, og spottaren er ei gruv for folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Misser du modet når trengsla kjem, då er di kraft for trong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Berga deim som dei fører til dauden, og dei som vinglar til rettarstaden, haldt deim att!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Um du segjer: «Me visste det ikkje, ser du,» tru ikkje han som veg hjarto, skynar det, og han som agtar på sjæli di, veit det, og han løner mannen etter hans gjerning?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Et honning, son min, for den er god, og sjølvrunnen honning er søt for din gom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Lær sameleis visdom for sjæli di! Finn du honom, so hev du ei framtid, og di von skal ikkje verta til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Lur ikkje, du gudlause, på rettferdig manns bustad, legg ikkje heimen hans i øyde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'For sju gonger dett den rettferdige og stend upp att, men dei gudlause stuper når ulukka kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Når din fiend’ fell, so gled deg ikkje, og når han stupar, fegnast ei ditt hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Elles vil Herren sjå det og mislika det og venda frå honom vreiden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Harmast ei yver illgjerdsmenner, misunn ikkje dei gudlause!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'For den vonde hev ingi framtid; lampa åt gudlause sloknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Ottast Herren, son min, og kongen! Gakk ikkje i lag med upprørsmenner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'For brått kjem ulukka yver deim, og kven veit når åri deira fær ein usæl ende?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Desse ordi er og av vismenner. Det er ikkje godt når ein gjer mannemun i domen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Den som segjer til den skuldige: «Du er uskuldig.» Honom vil folkeslag banna og folk forbanna;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'men deim som refsar han, gjeng det vel, og velsigning av godt kjem yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Ein kyss på lipporne er det når einkvan gjev det rette svaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Fullfør yrket ditt ute, og gjer det ferdigt for deg på marki! Sidan kann du byggja deg hus');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'ver ikkje vitne mot næsten din utan grunn, for du vil vel’kje svika med lipporne dine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Seg ikkje: «Som han hev gjort med meg, so vil eg gjera med han. Eg vil løna mannen etter hans gjerning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Eg gjekk framum ein lat manns mark, og vinhagen til eit vitlaust menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'og sjå, han var vaksen full av tistlar, grunnen var yvergrodd med netlor, og steingarden kringom var riven ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Og eg skygnde på det og agta på det, eg såg det, og denne lærdomen tok eg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, '«Endå litt soving, endå litt blunding, endå litt kvild med henderne i kross!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'So kjem armodi di som ein farande fant, og naudi som skjoldvæpna mann.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Dette er og ordtøke av Salomo, og mennerne åt Hizkia, kongen i Juda, hev samla deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Guds æra er å dylja ei sak, og kongars æra å granska ei sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Himmel-høgd og jord-dypt og konge-hjarto kann ingen granska ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Burt med slagget or sylvet! So fær gullsmeden ei skål av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Burt med gudlaus mann frå kongen! So vert hans kongsstol fast ved rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Briska deg ikkje for kongen, og stell deg ikkje på storfolks plass.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'For betre er at dei segjer med deg: «Stig her upp!» Enn at du vert nedflutt for augo på fyrsten. Kva so augo dine hev set.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ver ikkje for snar til å reisa sak; for kva vil du gjera til slutt, når motparten gjer deg til skammar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Før di sak med grannen din, men ber ikkje ut ein annan manns løyndom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'For elles vil den som høyrer det, skjella deg ut, og du vil alltid få låkt ord på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Som eple av gull i skåler av sylv er eit ord som ein talar i rette tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Som ein gullring i øyra og sylgja av gull er ein vismann som refser for høyrande øyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Som svalande snø ein skurdonne-dag er ein tru bodberar for deim som sender han, han kveikjer sjæli åt herren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Som skyer og vind utan regn er ein mann som kyter av gåvor han ikkje gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Tolmod fær domaren yvertald, og den linne tunga bryt bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Finn du honning, so et det du treng, so du ikkje vert ovmett og spyr han ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Set sjeldan din fot i huset åt grannen, so han ikkje vert leid deg og hatar deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Hamar og sverd og kvasse pil er den som vitnar falskt mot sin næste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Som roti tonn og ustød fot, so er lit til utru mann på trengselsdagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Som kastar du klædi ein frostdag, som eddik på natron, so er den som syng visor for sorgfullt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Er din fiend’ svolten, gjev honom mat, er han tyrst, so gjev honom drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'For då hopar du gloande kol på hovudet hans, og Herren skal løna deg att for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Nordanvind føder regn, og ei kviskrande tunga sure andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Betre å bu i ei krå på taket enn ha sams hus med trættekjær kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Som friske vatnet for den trøytte, so er god tidend frå eit land langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Som gruggi kjelda og ein utskjemd brunn, so er rettferdig mann som vinglar medan gudlaus ser det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Eta for mykje honning er ikkje godt, men å granska det vandaste er ei æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Som ein by med murarne brotne og burte er mannen som ikkje kann styra sin hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Som snø um sumaren og regn i skurden, so høver ikkje æra for ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Som sporven flaksar burt og svala flyg, so råkar ikkje grunnlaus forbanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Svipa til hesten, taum til asnet, og ris til ryggen på dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Svar ikkje dåren etter hans dårskap, so du ei skal verta lik han, du og!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Svara dåren etter hans dårskap, so han ei skal tykkja han sjølv er vis!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Føterne høgg han av seg, og vald fær han drikka, han som sender bod med ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Visne heng vanfør manns føter, so og ordtak i munnen på dårar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'som å binda ein stein i slyngja, soleis er det å gjeva ein dåre æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Som klungergrein i handi på drukken mann, so er ordtak i munnen på dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Som ein skyttar som sårar alle, so er den som leiger dåren og kvar som fer framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Som hund som snur seg til si eigi spya, so er ein dåre som kjem att til narreskapen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Ser du ein mann som tykkjer sjølv at han er vis, då er det større von for dåren enn for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Letingen segjer: «D’er villdyr på vegen, ei løva i gatorne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Døri snur seg på gjengi, og letingen snur seg i sengi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Stikk den late si hand i fatet, han evast med å ta ho upp til munnen att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Letingen tykkjest visare vera enn sju som gjev vituge svar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Han triv i øyro på framumfarande hund, han som ryk upp i sinne for trætta som ikkje kjem han ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Som ein galen som skyt med brennende pilar - drepande skot -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'so er ein mann som svik sin næste og segjer: «Eg gjorde det berre på gaman.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Når veden tryt, so sloknar elden, er baktalar burte, stoggar striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Som kol vert til gløder og ved til eld, so kveikjer kranglaren kiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Baktalar-ord er som lostemat, dei glid so godt ned i livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Som sylv-glasering på skålbrot er brennande lippor når hjarta er vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Med lipporne skaper ein uven seg til, men inni seg gøymer han svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Gjer han seg blidmælt, tru honom ei, for sju slag styggedom bur i hans hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Hatet dyl seg i svik, men lyt syna sin vondskap i folkemugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Den som grev ei grav, skal stupa nedi, den som velter ein stein, skal få han yver seg att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Den falske tunga hatar deim som ho hev krasa, og den sleipe munnen fører til fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Rosa deg ikkje av morgondagen, for du veit ikkje kva ein dag ber i fang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Lat ein annan rosa deg; ikkje din eigen munn, ein framand og ei dine eigne lippor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Stein er tung, og sand veg mykje, men tyngre enn båe er dåreharm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Sinne er fælslegt, og vreide ein flaum, men kven kann standa seg mot åbryskap?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Betre er openberrleg refsing enn kjærleik som held seg duld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Trugne er slag av venehand, og mange er uvens kyssar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Den mette trakkar på honning, men den svoltne tykkjer alt beiskt er søtt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Som ein fugl som rømer frå reiret sitt, er ein mann som rømer frå heimen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Olje og røykjelse hjarta gled, og søte venar-ord frå rådvis sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Slepp ikkje frå deg venen din og far din’s ven, so du lyt heim til bror din når du er i naud! Ein granne nær attmed er betre enn ein bror langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Vert vis, min son, og gled mitt hjarta, so eg kann svara den som spottar meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Den kloke ser fåren, gøymer seg; fåmingar renner fram og lyt bøta for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Tak klædi hans, for han hev borga for ein annan, og panta honom for ei framand kvinna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Den som høgmælt signar sin ven um morgonen tidleg, han skal få det tilrekna som ei forbanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Si-drop frå taket ein regndag og ei trættekjær kvinna likjest kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Den som held på henne, held på vind, og handi hans triv i olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Jarn sliper jarn, og den eine mannen sliper den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Den som agtar fiketreet sitt, fær eta frukti av det, den som tek vare på sin herre, skal få æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Som andlit seg speglar mot andlit i vatnet, so menneskjehjarta mot menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Helheim og avgrunn vert ikkje mette, og menneskjeaugo vert ikkje mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Diglen røyner sylvet og omnen gullet, og ein mann vert røynd av sin ros.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Um du støyte uvitingen i mortelen med støytaren i hop med gryn, so vilde ikkje vitløysa vika ifrå han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'God greide lyt du hava på koss sauerne dine ser ut, og agta vel på buskapen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'For velstand varer ikkje æveleg, og ikkje ei kruna frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Men er høyet burte og håi kjem att, og fjellgras vert sanka i hop,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'då hev du lamb til klæde, og bukkar til å kjøpa deg åker for,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'og geitemjølk nok til mat for deg, til mat for huset ditt og til livsupphald for gjentorne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Dei gudlause flyr um ingen deim elter, dei rettferdige er som ungløva trygge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Syndar eit land, fær det mange herrar, men hev folket mykje vit, varer retten lenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Ein fatig herre som trykkjer dei arme, er eit regn som herjar og ikkje gjev brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Dei som gjeng ifrå lovi, prisar dei gudlause, men dei som held lovi, harmast på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Vonde folk skynar ikkje kva rett er, men dei som søkjer Herren, skynar alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Betre er ein fatigmann som ferdast lytelaust, enn ein rikmann som er rang og gjeng tvo vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Den som agtar på rettleiding, er ein vitug son, men den som hev lag med øydarar, fører skam yver far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Den som aukar si eiga med renta og oker, han sankar åt den som er god mot dei arme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Um ein vil venda øyra burt og ikkje høyra lovi, er jamvel bøni hans ein styggedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Den som villar ærlegt folk inn på ein vond veg, han skal stupa i si eigi grav, men dei lytelause skal erva det som godt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Ein rikmann tykkjer han er vis, men ein fatigmann med vit granskar honom ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Held dei rettferdige høgtid, stend det herleg til, men når gudlause kjem seg upp, lyt ein leita etter folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Den som dyl misgjerningarne sine, hev ikkje lukka med seg, men den som sannar deim og vender seg ifrå deim, han finn miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Sæl den mannen som alltid ottast, men den som gjer hjarta sitt hardt, han fell i ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Burande løva og ein grådig bjørn er gudlaus hovding yver fatigt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Du hovding fatig på vit og rik på vald! Dei som hatar urett vinning, skal liva lenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ein mann med blodskuld yver seg er på flugt alt til gravi, ingen må hjelpa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Den som ferdast lytelaust, vert frelst, men den range tvivegs-farar fell på den eine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Den som dyrkar si jord, fær nøgdi av brød, men den som fer etter fåfengt, fær nøgdi av armod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Ein trufast mann fær rik velsigning, men den som renner etter rikdom, vert ei urefst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Det er’kje godt når ein gjer mannemun, men mang ein mann vert brotsmann for ein brødbit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'I bråhast vil den ovundsjuke verta rik, og han veit’kje at vanråd vil koma på han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Den som refser ein mann, vinn seg takk til slutt meir enn den som smeikjer med tunga si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Den som plundrar far sin og mor si og segjer: «Det er ikkje synd,» han er øydelands lagsbror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Den vinnekjære valdar trætta, men den som lit på Herren, fær kveikjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Den som lit på vitet sitt, han er ein dåre, men den som vandrar i visdom, vert frelst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Den som gjev den fatige, vantar inkje, men den som let att augo, fær mykje banning yver seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Når gudlause kjem seg upp, då gøymer folk seg, men når dei gjeng til grunns, då aukar dei rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Ein mann som etter mykje refsing endå er ein stivnakke, vil brått verta broten ulækjeleg sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Når rettferdige aukar i tal, då gled seg folket, men når gudlaus mann kjem til styre, sukkar folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Den som elskar visdom, gled sin far, men den som gjeng i lag med skjøkjor, øyder eiga si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Ein konge held landet sitt uppe med rett, men ein skattekrevjar legg det i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Ein mann som smeikjer for næsten sin, breider ut eit net for føterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Ein vond manns misgjerd er snara for honom, men rettferdig mann fegnast og gled seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Den rettferdige syter for stakarens sak, den gudlause hev ikkje greida på noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Spottarar øser upp ein by, men vismenner stiller vreiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Når vismann fører sak mot dåren, vert dåren sinna og lær, og kann’kje vera still.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Dei blodfuse hatar ein skuldlaus mann, og stend dei ærlege etter livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Alt sitt sinne slepper dåren ut, men vismannen døyver det til slutt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Agtar ein hovding på lygneord, er alle hans tenarar nidingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Fatigmann og valdsmann råkast, Herren gjev deim båe augneljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Ein konge som dømer småfolk rett, hans kongsstol stend æveleg fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Ris og age gjev visdom, men ein agelaus gut fører skam yver mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Når dei gudlause aukar, so aukar syndi, men dei rettferdige skal sjå med lyst på deira fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Aga son din, so vil han vera deg til hugnad og gjeva lostemat til sjæli di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Utan profetsyn vert folket vilt, men sæl er den som held lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Med ord let trælen seg ikkje tukta, for han skynar deim vel, men bryr seg’kje um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Ser du ein mann som er snar til å tala, dåren gjev større von enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Kjæler du trælen upp frå hans ungdom, vil han vanvyrda deg til slutt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Sinna mann valdar trætta, og brålyndt mann gjer mang ei misgjerd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Mannsens ovmod fører til fall, men den audmjuke vinn seg æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Den som helar med tjuven, hatar sitt liv, han høyrer dei tek han i eid, men gjev ingi vitring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Manne-rædsla legg snaror, men den som lit på Herren, vert berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Mange vil te seg fram for ein styrar, men frå Herren fær kvar mann sin rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Ein styggedom for rettferdige er ein urettferdig mann, og ein styggedom for den gudlause er den som fer ærleg fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Ord av Agur, son åt Jake, profetordet. Mannen segjer so til Itiel, til Itiel og Ukal:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'For fåvis er eg til å heita mann, og ikkje hev eg manne-vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Visdom hev eg ikkje lært, til kunnskap um den Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kven hev stige upp til himmelen og stige ned? Kven hev samla vinden inn i nevarne? Kven hev bunde vatnet i eit klædeplagg? Kven hev alle enderne av jordi sett? Kva heiter han, kva heiter son hans - um du veit det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Alt Guds ord er skirt, han er ein skjold for deim som flyr til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Legg ikkje noko til hans ord, elles lyt han refsa deg, og du stend der ein ljugar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Tvo ting hev eg bede deg um, neitta meg deim ikkje, fyrr eg døyr:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Lat fals og lygn vera langt frå meg! Gjev meg ikkje armod og ikkje rikdom! Lat meg få eta mitt tiletla brød!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Elles kunde eg neitta deg når eg var mett, og segja: «Kven er Herren?» Eller um eg vart fatig, kunde eg stela, ja, forgripa meg på min Guds namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Baktala ei ein tenar for hans herre, elles vil han banna deg, og du få bøta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Ei ætt som bannar far sin og ikkje signar mor si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'ei ætt som tykkjer ho er rein, endå ho ei hev tvætta av sitt eige skarn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'ei ætt - kor stolte augo hev ho ikkje, og kor ho lyfter augneloki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'ei ætt som heve sverd til tenner og jakslar reint som knivar, so ho et armingar or landet og fatige or folkesamfund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Blodiglen hev tvo døtter: Gjev! Gjev! Tri finst det som aldri vert mette, fire som ei segjer: «Nok!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Helheim og barnlaust moderfang, jordi som aldri vert mett av vatn, og elden som ei segjer: «Nok!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Eit auga som spottar far og vanvyrder lydnad mot mor, det skal bekkje-ramnarne hakka ut og ørnungar eta upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Tri ting er meg for underlege, og fire finst som eg ikkje skynar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Ørns veg på himmelen, orms veg på berget, skips veg på havet og manns veg til møy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Soleis ber utru kona seg åt: Ho et og turkar seg um munnen og segjer: «Eg hev ikkje gjort noko vondt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Under tri skjelv jordi, under fire kann ho’kje herda:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'under trælen når han vert konge, og dåren når han fær eta seg mett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'under attergløyma når ho vert gift, og trælkvinna når ho erver si frua.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Fire finst det som er små på jordi, og endå hev dei fenge visdom stor:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Mauren er’kje noko sterkt folk, og endå lagar han sin mat um sumaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Fjellgrevlingarne er’kje noko veldugt folk, og endå byggjer dei seg hus i berget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Grashopparne hev ingen konge, og endå fær dei alle ut i fylking.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Fjorføtla kann du ta med henderne, og endå bur ho inni kongeslott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Tri finst det som stig med staute stig, og fire hev ei fager gonga:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Løva ei kjempa millom dyri, og som ikkje snur seg for nokon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'hesten mjå um midja, eller bukken, og ein konge med leidingheren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Gjer du deg stor, anten narr eller klårtenkt, so legg handi på munnen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'For trykk på mjølk gjev smør, og trykk på nase gjev blod, og trykk på vreide gjev strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Ord av kong Lemuel, profetord som mor hans prenta inn i honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Kva skal eg segja, son min, ja kva, du mitt livs son, ja kva, du min lovnads-son?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Gjev ikkje kvende di kraft, og far ikkje vegar som tynar kongar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ei sømer det seg, Lemuel, for kongar, ei kongar sømer det seg å drikka vin, og ei for hovdingar å spyrja etter rusdrykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'For drikk han, vil han gløyma kva som lov er, og venda retten fyre alle arminger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Lat han få rusdrykk som er åt å gå til grunns, og han få vin som gjeng med sorg i sjæli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'At han kann drikka og si armod gløyma, og ikkje lenger minnast møda si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Lat upp din munn for mållaus mann, for alle deira sak som gjeng mot undergang!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Lat upp din munn og rettvist døm, lat armingen og fatigmannen få sin rett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Ei dugande kona, kven finn vel ei slik? Høgre stend ho i pris enn perlor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Mannsens hjarta lit på henne, og vinning vantar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Ho gjer honom godt og inkje vondt alle sine livedagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Ho syter for ull og lin, og henderne strævar med hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Ho er som kaupmanna-skip, langt burtantil fær ho si føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Og uppe er ho i otta, og gjev sin huslyd mat og etlar åt ternone ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Ho stilar på ein åker og fær han, for det ho med henderne tener ho plantar ein vingard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Kraft ho bind seg til belte um livet og gjer sine armar sterke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Ho merkar at hushaldet hennar gjeng godt, då sloknar’kje lampa hennar um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Ho retter henderne ut etter rokken, og fingrarne tek til teinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Ho opnar handi for armingen, retter ho ut til fatigmannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ei ræddast ho snø for huset sitt, for alt hennar hus er klædt i skarlaks-ty.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Ho gjer seg tæpe og klær seg i finaste lin og purpur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Hennar mann er kjend i portarne, der han sit til tings med dei fremste i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Linskjortor gjer ho og sel, og belte gjev ho til kramkaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Kraft og vyrdnad er klædnaden hennar, og ho lær åt dagen som kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Ho let upp munnen med visdom, mild upplæring ho gjev med si tunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Koss det gjeng i huset agtar ho på, og ei et ho brød i letingskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Fram stig hennar søner og prisar ho sæl, og mannen syng henne lov:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '«Mange kvende stod høgt i dugleik, men du gjeng yver deim alle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Vænleik er fals og fagerskap fåfengd; ei kona som ottast Herren, skal prisast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Lat ho få det ho vann med henderne sine, og pris i portarne av sine verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Ord av Preikaren, son åt David, konge i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Fåfengt, fåfengt! segjer Preikaren, fåfengt, fåfengt! Alt er fåfengt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Kva vinning hev mannen av alt si møda som han møder seg med under soli?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, '\'tt gjeng, og ætt kjem, medan jordi æveleg stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Og soli renn, og soli glar, og ho skundar seg att til staden sin der som ho plar renna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Vinden gjeng imot sud og snur seg mot nord, han snur seg og snur seg og kjem attende til kringlaupet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Alle elvar renn ut i havet, men havet vert ikkje fullt, dit som elvarne fyrr hev runne, held dei alltid på å renna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Allting strevar so ingen det ut kann segja, ikkje vert auga mett av å sjå, og ikkje vert øyra fyllt av å høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Det som hev vore, er det som skal vera, og det som hev hendt, er det som skal henda; det finst inkje nytt under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Skulde dei segja um noko: «Sjå, dette er nytt!» - so hev det longe vore til i fordums tider som var fyre oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Me hev inkje minne um deim som fyrr hev livt, og dei som sidan skal koma, vil ikkje heller liva i minnet hjå deim som etterpå kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Eg, Preikaren, var konge yver Israel i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Eg lagde hugen på å granska og å ransaka med visdom alt det som hender under himmelen. Det er ei leid plåga som Gud hev gjeve mannsborni å plågast med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Eg såg på alt det som hender under soli, og so var det fåfengt alt i hop og jag etter vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Det bogne kann ikkje beinkast, og det vantande kann ikkje reknast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Eg tenkte med meg sjølv: «Sjå no hev eg vunne meg større og rikare visdom enn alle dei som hev rådt yver Jerusalem fyre meg, og hjarta mitt hev set visdom og kunnskap i rikt mål.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Eg lagde hugen på å skyna visdomen og skyna vitløysa og dårskap. Men eg skyna at det var jag etter vind det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'For med mykje visdom du mykje gremmest, og aukar du kunnskap, so aukar du kvida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Då sagde eg med meg sjølv: «Kom, so skal eg prøva deg med gleda; njot det som godt er!» Men so var det fåfengt det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Um låtten sagde eg: «Han er vitlaus!» Og um gleda: «Kva gagn gjer ho?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Eg kom på den tanken, at eg skulde kveikja kroppen med vin, medan hjarta dreiv på med visdom, og halda meg til dårskapen, til dess eg fekk sjå kva som var best for mannsborni å gjera under himmelen dei dagarne livet varer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Eg tok på med store verk: Eg bygde meg hus, planta meg vingardar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'gjorde meg hagar og parkar og sette alle slag frukttre i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Eg gjorde meg vatsdammar til å vatna ein lund av tre som voks upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Eg kjøpte trælar og trælgjentor, hadde heimefødde trælar, ja ein buskap fekk eg meg og, kyr og sauer i mengd, meir enn alle dei som hadde vore fyre meg i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Eg samla meg ogso sylv og gull, og alt som kongar og land kann eiga, eg fekk meg songarar og songmøyar, og det som er til lyst for mannsborni: konor i mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'So vart eg reint ovstor, større enn alle dei som hadde vore fyre meg i Jerusalem, og attpå hadde eg visdomen min hjå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Alt det augo ynskte, let eg deim få, eg heldt ikkje hjarta mitt burte frå nokor gleda; for hjarta hadde gleda av all mi møda, og det var min lut av all mi møda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Men so gav eg meg til å sjå på alle mine verk som henderne mine hadde gjort, og den møda dei hadde kosta meg, då synte det seg at alt var fåfengd og jag etter vind. Nei, det finst ingi vinning under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'So gav eg meg til å sjå på visdom og vitløysa og dårskap; for kva vil den mannen gjera som kjem etter kongen? Det som folk fyrr hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Då såg eg at visdomen hev same fyremunen framfor dårskapen som ljoset hev framfor myrkret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Den vise hev augo i hausen, men dåren ferdast i myrkret. Men eg skyna og at same lagnaden råkar den eine som den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Då sagde eg med meg sjølv: «Den lagnad som dåren fær, den fær eg og. Kva gagn hev eg då av det at eg hev vore so ovleg vis?» Eg sagde med meg sjølv: «Det er fåfengt dette og!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'For minnet um den vise varer ikkje meir æveleg enn minnet um dåren. I dei komande dagar vil alt vera gløymt for lenge sidan, og lyt ikkje den vise døy likso vel som dåren?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Då vart eg leid av livet, for det som hender under soli, tyktest meg vera vondt; alt er fåfengd og jag etter vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Og eg vart leid av all mi møda som eg hev mødt meg med under soli, av di eg skulde leiva det til den mannen som kjem etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Kven veit um det vert ein vis mann eller ein dåre? Og endå skal han råda yver alt det som eg hev vunne med møda og med visdom under soli! Det er fåfengt det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Då tok eg reint til å orvonast for all den møda eg hadde mødt meg med under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'For det hender at ein mann hev gjort sitt arbeid med visdom og kunnskap og dug, so lyt han gjeva det frå seg til eiga åt ein mann som ikkje hev havt møda med det. Det og er fåfengd og ei stor ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Ja, kva hev mannen att for all si møda og sine hugmål som han mødest med under soli?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'For heile hans liv er ei pinsla, og hans stræv er leidelse, ja ikkje ein gong um natti fær hjarta hans kvila. Det er fåfengt det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Det er ikkje ei lukka som stend til mannen sjølv at han et og drikk og unner seg gode dagar midt i møda si. Eg såg at det og kjem frå Guds hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'For kven kann eta og kven kann njota noko utan honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'For den mannen som er honom til hugnad, gjev han visdom og kunnskap og gleda. Men den som syndar, gjev han strævet med å samla og draga i hop so den som er til hugnad for Gud kann få det. Det og er fåfengd og jag etter vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Alt hev si stund, og kvart tiltak under himmelen hev si tid:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Fødast hev si tid, og døy hev si tid; planta hev si tid, og riva upp det som er planta hev si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'drepa hev si tid, og lækja hev si tid; riva ned hev si tid, og byggja upp hev si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'gråta hev si tid, og læ hev si tid; syrgja hev si tid, og dansa hev si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'kasta stein hev si tid, og sanka stein hev si tid; fangtak hev si tid, og halda seg frå fangtak hev si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'leita hev si tid, og missa hev si tid; gøyma hev si tid, og kasta burt hev si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'riva sund hev si tid, og sauma i hop hev si tid; tegja hev si tid, og tala hev si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'elska hev si tid, og hata hev si tid; ufred hev si tid, og fred hev si tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Kva vinning fær då den som gjer noko av den møda han hev med det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Eg såg på det strævet som Gud hev gjeve mannsborni å stræva med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Alt hev han laga fagert til si tid, ja, æva hev han lagt i hjarta deira, men so at menneskja ikkje kann finna ut frå upphav til endes det verk som Gud hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Då skyna eg at dei ikkje hev noko betre enn å gleda seg og goda seg so lenge livet varer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Men det å eta og drikka og njota livet midt i all møda, det og ei Guds gåva for kvar mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Eg skyna at alt det Gud gjer, det varer æveleg, ikkje kann ein leggja noko til, og ikkje kann ein taka noko ifrå; og det hev Gud gjort so, av di me skal ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Det som hender, hev vore til fyrr, og det som kjem til å henda, hev og vore til fyrr; Gud leitar upp att det framfarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Framleides såg eg under soli: I domstolen, der sat uretten, og på rettferd-staden, der var uretten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Då sagde eg med meg sjølv: «Den rettferdige og den urettferdige skal Gud døma; for hjå han er det sett ei tid for kvart tiltak og for kvart verk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Eg sagde med meg sjølv: «Det er for mannsborni skuld, for Gud vil prova deim, so dei kann sjå at dei i seg sjølve ikkje er anna enn dyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'For lagnaden åt mannsborni er som lagnaden åt dyri, ja, same lagnaden fær dei; som den eine døyr, so døyr den andre, og ei ånd hev dei alle; menneskja hev ingen fyremun framfor dyri, for alt er fåfengt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Alle gjeng til ein stad, alle er komne av moldi, og alle skal attende til moldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kven veit um åndi åt menneski stig uppetter, og um åndi åt dyri fer ned til jordi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'So skyna eg at ingen ting er betre enn at mannen er glad i arbeidet sitt, for det er hans lut. For kven kann føra honom so langt, at han ser inn i det som skal koma etter honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Framleides såg eg på alle dei valdsverk som vert gjorde under soli. Det rann frå deim som leid, og ingen trøysta deim; valdsmenner bruka magt mot deim, og ingen trøysta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Då laut eg segja at dei avlidne, dei som alt hadde fenge døy, dei var sælare enn dei livande som endå er i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Men sælare enn båe tvo er den som ikkje hev vorte til endå, og som hev sloppe å sjå det vonde verk som folk gjer under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Og eg såg at alt stræv og all dugleik i arbeidet ikkje er anna enn ovund som driv den eine fyre den andre. Det og er fåfengd og jag etter vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Dåren legg henderne i kross og et sitt eige kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Betre ein neve med ro enn båe henderne fulle av møda og jag etter vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Og endå noko såg eg som er fåfengt under soli:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Det hender at ein mann stend åleine og hev ingen annan med seg, korkje son eller bror; og like vel er det ingen ende på alt strævet hans, og augo hans vert ikkje mette av rikdom. Men kven strævar eg for og neittar meg sjølv det som godt er? Det er fåfengt, og ei leid møda er det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Tvo er betre farne enn ein, for dei hev god løn for strævet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Um dei dett, kann den eine reisa upp felagen sin; men usæl er einstødingen som dett og ikkje hev nokon til å reisa seg upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Likeins når tvo ligg i hop, so vert dei varme, men korleis skal ein verta varm åleine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Og um nokon kann vinna yver den som er åleine, so kann tvo standa seg imot honom, og tritvinna tråd slit ein ikkje av so snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Betre er ein fatig og vis ungdom enn ein gamall og fåvitug konge som ikkje lenger veit å lata seg segja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'For ein slik ungdom steig or fangehuset upp til kongedøme, endå han var fødd i fatigdom i den andre sitt rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Eg såg alle livande som ferdast under soli fylgja med ungdomen, han den andre som skulde koma i staden for hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Det var ingen ende på alt folket, alle dei som han var førar for. Like vel er dei ikkje glade i honom, dei som sidan kom. Nei, det og er fåfengd og jag etter vind. Agta foten din når du gjeng til Guds hus! Det er betre at ein held seg nær og høyrer enn at dårar ber fram slagtoffer; for dei gjer vondt av di dei ikkje veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Ver ikkje bråfus med munnen din, og lat ikkje hjarta forhasta seg med å bera fram noko ord for Gud! For Gud er i himmelen og du på jordi, lat difor ordi dine vera få!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'For draumar kjem av mykje mas, og dåresvall av mange ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Lovar du Gud noko, so dryg ikkje med å halda det, for han likar ikkje dårar. Haldt det du lovar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Det er betre at du inkje lovar enn at du lovar og ikkje held det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Lat ikkje munnen føra skuld yver kroppen, og seg ikkje til sendebodet: «Eg forrende meg!» Kvifor skal Gud harmast på det du segjer og tyna det som henderne dine gjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'For med mange draumar fylgjer mykje fåfengd, og like eins med mange ord. Nei, du skal ottast Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Um du ser at fatigmannen ligg under trykk, og at dei ranar rett og rettferd i landet, so undrast ikkje på den ting! For den eine høgsette lurer på den andre, og dei hev høgsette yver seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Det er i alle høve ein fyremun for eit land: Ein konge som fremjar jordbruk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Den som elskar pengar, vert ikkje mett av pengar, og den som elskar rikdom, fær ingi vinning. Det er fåfengd det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Di meir gods, di fleire til å tæra på det. Kva gagn hev eigaren av det anna enn augnesyn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Søt er svevnen for arbeidsmannen, anten han et lite eller mykje; men rikmannen fær ikkje sova for mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Det finst noko syrgjeleg leidt som eg hev set under soli: Rikdom som eigaren hev spart upp til si eigi ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Misser han denne rikdomen i eit uhende, og han hev fenge ein son, so eig han ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Slik som han kom ut or morslivet, skal han ganga burt att, so naken som han kom, og for strævet sitt fær han ingen ting som han kunde taka med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Det og er syrgjeleg leidt: Just slik som han kom, skal han ganga burt; kva vinning hev han då av det at han strævar burt i vind og vær?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Attpå tærer han sitt heile sitt liv i myrker, og stor harm lyt han dragast med, og so hans sjukdom og sinne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Høyr no kva eg hev funne godt og fagert: At ein et og drikk og nyt det som godt er i all den møda som han mødest med under soli alle dei livedagar som Gud gjev honom; for det er hans lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Og so tidt Gud gjev ein mann rikdom og skattar og attpå gjer honom før til å njota godt av det og taka sin lut og gleda seg i møda si, so er det ei gåva frå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'For då tenkjer han ikkje so mykje på livedagarne sine, av di Gud gjev honom nok å gjera med hjartegleda hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Det er ei ulukka som eg hev set under soli, og tung ligg ho på menneskja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Når Gud gjev ein mann rikdom og skattar og æra, so han for sin part ikkje vantar noko av det han ynskjer, men Gud ikkje let honom vera kar til å njota godt av det, men ein framand mann fær njota det, so er det fåfengd og ei vond liding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Um ein mann fær hundrad born og liver mange år, so talet vert stort på dagarne i hans liveår, men sjæli hans ikkje vert mett av det gode, og han so ikkje fær nokor jordferd, då segjer eg: Eit ufullbore foster er betre fare enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'For til fåfengs kom det, og i myrker gjeng det burt, og i myrker fær det namnet sitt løynt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'og soli hev det korkje set eller kjent - det hev meir ro enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Og um han so livde tusund år tvo gonger, men ikkje fekk njota noko godt - fer ikkje alt til ein stad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'All mannsens møda er for munnen hans, og like vel vert hugen aldri nøgd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'For kva fyremun hev vismannen framfor dåren? Kva fyremun hev fatigmannen som veit å vandra for augo på dei livande?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Betre augnesyn enn ein urolig hugen. Det er fåfengd og jag etter vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Det som hender, er alt fyrr nemnt med namn, og det er kjent kva ein mann skal verta, og ikkje kann han saksøkja den som er sterkare enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'For det finst ein ordrikdom som berre aukar fåfengdi, kva gagn hev mannen av det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'For kven veit kva som er godt for mannen i livet, i alle hans fåfengde livedagar som han fer igjenom som ein skugge? Og kven segjer med mannen kva som skal henda under soli etter hans tid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Betre godt namn enn god salve, og betre døyande-dagen enn fødedagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Betre til syrgjehus ganga enn til gjestebodshus, so visst som det er enden for alle menneskje, og den som liver, skal leggja seg det på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Betre gremmelse enn lått, for når andlitet ser ille ut, stend vel til med hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Hjarta åt vismenner er i syrgjehus, men hjarta åt dårar er i gledehus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Betre høyra skjenn av ein vismann enn når nokon høyrer song av dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'For som tyrnerris sprakar under gryta, soleis er det når dåren lær. - Det og er fåfengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'For urett vinning gjer vismann til dåre, og mutor skjemmer ut hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Betre enden på ei sak enn upphavet, betre tolmodig enn ovmodig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ver ikkje for brå i hugen til å gremmast, for gremmelse bur i barmen på dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Seg ikkje: «Korleis hev det seg at dei framfarne dagar var betre enn dei som no er?» For ikkje utav visdom spør du um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Visdom er jamgod med ervegods, og ei vinning for deim som ser soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'For ein sit i skuggen av visdomen som i skuggen av pengar, men fyremunen med kunnskap er at visdomen held eigaren sin i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Sjå på Guds verk! For kven kann beinka det som han hev gjort krokut?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'På ein god dag skal du vera i godlag, og på ein vond dag skal du tenkja på at Gud hev gjort den og likso vel som hin, av di at menneskja ikkje skal finna noko ulivt etter si avferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Alt hev eg set i dei fåfengde dagerne mine: Det hender at ein rettferdig gjeng til grunns tråss i si rettferd, og at ein gudlaus liver lenge tråss i sin vondskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ver ikkje altfor rettferdig, og te deg ikkje for vis! Kvifor vil du tyna deg sjølv?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ver ikkje altfor gudlaus, og ver ikkje ein dåre? Kvifor vil du døy fyre tidi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Det er godt at du held fast på det eine og ikkje heller slepper handi av det andre, for den som ottast Gud, han greider seg or alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Visdomen gjev vismannen ei sterkare vern enn ti magthavarar i ein by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'For det finst ikkje eit rettferdigt menneskje på jordi som berre gjer godt og aldri syndar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Agta ikkje heller på alt det som folk segjer, elles kunde du få høyra din eigen træl banna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'For du veit med deg sjølv, at du og mange gonger hev banna andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Alt dette hev eg røynt ut med visdom. Eg tenkte: «Visdom vil eg vinna!» men han heldt seg langt burte frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Langt burte er det som til er, og so djupt, so djupt; kven kann nå det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Eg gav meg til, og hugen gjekk ut på å kjenna og granska og søkja visdom og ettertanke og få vita at gudløysa er dårskap og narreskapen vitløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Då fann eg at kvinna er beiskare enn dauden, for ho er eit net, og hjarta hennar eit garn, og henderne hennar lekkjor. Den som tekkjest Gud, slepp ifrå henne, men syndaren vert hennar fange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Sjå det fann eg, segjer preikaren, då eg lagde det eine i hop med det andre og vilde koma til ei endelykt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Det som eg stødt hev leita etter, men ikkje funne, det er: Ein mann millom tusund hev eg funne, men ei kvinna hev eg ikkje funne millom alle deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Berre dette hev eg funne ut, skal du vita, at Gud hev skapt menneskja rett, men dei søkjer mange krokar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kven er som vismannen, og kven veit å tyda ein ting? Mannsens visdom gjer hans andlit ljost, og det harde i hans åsyn vert umskift.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Eg segjer: Agta på bod ifrå kongen, og det for den eid skuld som du hev svore ved Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Gakk ikkje for snart burt frå honom, og ver ikkje med på noko vondt! For han gjer alt det han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'For konungs ord er megtigt, og kven torer segja med honom: «Kva gjer du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Den som held bodet, skal ikkje få kjenna noko vondt, og vismanns hjarta skal få kjenna tid og dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'For kvart tiltak hev si tid og sin dom; for mannsens vondskap ligg tungt på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'For han veit ikkje kva som skal henda, og kven kann segja honom korleis det vil verta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Ingen mann hev magt yver vind og ver, so han kann stengja for vinden, og ingen hev heller magt yver døyande-dagen, og ikkje fær ein heimlov i ufred, og ikkje kann gudløysa berga sin mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Alt dette hev eg set, med di eg gav gaum etter alt det som gjeng fyre seg under soli på ei tid då det eine menneskjet rådder yver det andre til ulukka for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Dinæst hev eg set gudlause koma i grav og ganga inn til kvila, men dei som hadde gjort rett, laut fara burt frå den heilage staden og vart gløymde i byen. Det er fåfengd det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Av den grunn at vondskaps verk ikkje straks fær sin dom yver seg, vert hjarta på mannsborni fullt av mod til å gjera vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'sidan syndaren hundrad gonger kann gjera det som vondt er, og like vel liva lenge - endå eg veit at det vil ganga deim vel som ottast Gud, av di dei ottast for hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Men ikkje vil det ganga den gudlause vel, og liksom skuggen skal han ikkje liva lenge, av di han ingen otte hev for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Det er noko fåfengt som hender på jordi, at det finst rettferdige som fær sin lagnad etter gudlause folks gjerning, og det finst gudlause som fær sin lagnad etter rettferdige folks gjerning. Eg sagde at det var fåfengd det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Då prisa eg gleda, for mannen hev ikkje noko anna godt under soli enn å eta og drikka og vera glad, og det fylgjer honom i hans møda i dei livedagarne som Gud hev gjeve honom under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Når eg lagde hugen på å få kjenna visdom og å sjå det strævet som dei stræver med på jordi - for korkje dag eller natt fær dei blund på augo -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'då såg eg at det er so med alt Guds verk, at menneskja ikkje kann grunda ut det som hender under soli. For alt det menneskja strævar med å granska det ut, fær ho ikkje tak i det, ja, um ein vismann tenkjer at han skal skyna det, so kann han ikkje grunda det ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'For alt dette lagde meg på hjarta, og alt dette prøvde eg å granska ut: at dei rettferdige og dei vise og deira verk er i Guds hand. Um kjærleik eller hat veit ingen mann i fyrevegen; alt kann dei venta seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Alt kann hendast alle. Den same lagnaden råkar den rettferdige og den gudlause, den gode og reine og den ureine, den som ofrar og den som ikkje ofrar, det gjeng på same vis med den gode som med syndaren, med den som sver som med den som er rædd å sverja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Det er det som er det leide med alt som hender under soli, at alle fær same lagnaden, so vert og hjarta åt mannsborni fullt av det som vondt er, og dei ber vitløysa i hjarta sitt so lenge dei liver, og sidan lyt dei av til dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'For den som fær vera i lag med alle dei livande, han hev von. For ein livande hund er betre enn ei daud løva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'For dei livande veit at dei skal døy, men dei daude veit ingen ting og fær ikkje lenger nokor løn, for minnet um deim gløymest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Både deira kjærleik og hat og ovmod er det slutt med for lenge sidan, og aldri meir fær dei hava noko med det som hender under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'So et då ditt brød med gleda, og drikk med godt mod din vin! For Gud hev longe godkjent di gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Lat klædi dine stødt vera kvite, og ei vanta olje på hovudet ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Njot livet med ei kona som du elskar, alle dagar i ditt fåfengde liv som han hev gjeve deg under soli, alle dine fåfengde dagar! For det er din lut i livet og i møda di som du mødest med under soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Alt det di hand vinn gjera med di kraft, det skal du gjera, for det finst ikkje arbeid eller utrekning eller kunnskap eller visdom i helheimen som du gjeng til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Framleides såg eg under soli at ikkje dei snøgge råder yver skeidet, og ikkje kjemporne yver i striden, og ikkje heller dei vise yver brød, ikkje heller dei vituge yver rikdom, ikkje heller dei kunnige yver manntekkje; for tid og lagnad møter deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'For menneskja kjenner likso lite si tid som fiskarne som vert fanga i ulukke-garnet, eller fuglarne som vert fanga i snara. Lik eins vert og mannsborni snara i ustundi, når ho brått kjem yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Det og hev eg set var visdom under soli, og stor tykte eg han var:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Det var ein liten by, og få folk hadde han. So kom det ein stor konge mot honom og kringsette honom og bygde store vollar mot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Og det fanst der i byen ein fatig vismann, og han berga byen med visdomen sin; men ikkje eit menneskje kom i hug denne fatige mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Då tenkte eg: «Vel er visdom betre enn styrke, men folk vanvyrder fatigmanns visdom, og dei høyrer ikkje på ordi hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Vismanna-ord som ein høyrer i ro, er betre enn hovdings skrik millom dårar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Visdom er betre enn våpn, men ein syndar kann tyna mykje godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Eiterflugor set illtev og æsing i salven åt salvemakeren; ein grand dårskap veg meir enn visdom, meir enn æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Vismanns-hug til retta gjeng, og dåre-hug til keiva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Og kvar helst dåren gjeng, tryt vitet hans, og han segjer frå til kvar og ein at han er ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Um hovdings vreide reiser seg mot deg, so gakk ikkje frå din post! For roleg åtferd hindrar mange synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Det er ei ulukka som eg hev set under soli liksom eit mistak som kjem frå ein magthavar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Dårskapen er sett i høge sessar, og rikfolk lyt sitja lågt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Eg hev set trælar på hesteryggen og hovdingar ganga på sin fot som trælar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Den som grev ei grav, kann stupa nedi, og den som riv ein mur, kann ormen stinga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Den som bryt stein, kann få mein; den som høgg ved, kann koma ut i fåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Når øksi ikkje bit og han ei slipar eggi, då lyt han bruka dess meir magt. Men visdomen veit å vøla til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Når ormen sting fyrr ein fær mana, hev manaren ingen fyremun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Ord av vismanns munn er gudlege, men lipporne på dåren gløyper honom sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Dei fyrste ordi i hans munn er dårskap, og røda endar reint i arge vitløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Dåren brukar mange ord, endå ingen mann veit kva som henda skal, og kva som etter hans tid henda skal, kven kann segja honom det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Dåren møder seg med maset sitt, han som ikkje ein gong veit å gå til byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Usælt er du land som hev eit barn til konge, og fyrstar som held etarlag um morgonen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Sælt er du land som hev ein adelboren konge, og fyrstar som held sine mål i rette tid på kara-vis og ei med fyll!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Når leta rår, sig bjelkarne ned, og huset lek når henderne heng. -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Til gaman held dei gilde, og vin gjev livet gleda, og pengar greider alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ikkje ein gong i tankarne må du banna ein konge, og ikkje i ditt sengrom banna ein rikmann. For himmelens fuglar ber ljoden burt, og dei fløygde melder din tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Send brødet ditt burt yver vatnet; for lenge etterpå finn du det att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Skift ut til sju, ja til åtte, for du veit ikkje kva ilt som kann koma yver jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Når skyerne av regn vert fulle, so tømer dei det ut på jordi, og um eit tre dett imot sud ell’ nord - der treet dett, der vert det liggjande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Den som agtar på vinden, kjem ei til å så, og den som på skyerne ser, kjem ikkje til å hausta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Liksom du ikkje veit kva veg vinden fer, eller korleis beini vert til i hennar liv som er med barn, soleis kjenner du ikkje heller Gud gjerning, han som gjer alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Så ditt sæde um morgonen, og ei kvile handi i kveldingi! For du veit ikkje kva som vil lukkast av dette og hitt, eller um båe måtar er godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Ljuvlegt er ljoset, og augo hev godt av soli å sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Ja, um ein mann liver mange år, so skal han gleda seg i deim alle, men minnast dei myrke dagar og vert mange. Alt som koma skal, er fåfengt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Gled deg, du ungdom, med du er ung, ver godt i laget i ungdoms-åri, og far dei vegar som hugen vil, og fylg det som lokkar augo. Men det skal du vita at for alt dette vil Gud draga deg til doms.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Få gremmelse ut or hugen din, haldt liding burte frå likamen din! for ungdom og morgonrode er fåfengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Og tenk på din skapar i ungdomsdagarne, fyrr dei vonde dagarne kjem, og det lid til dei åri då du lyt segja: «Eg likar deim ikkje;»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'fyrr soli myrkjest, og ljoset og månen og stjernorne, og skyer kjem att etter regnet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'den tid då hus-vaktmennerne skjelv, og dei kraftige mennerne krøkjest, og håndkvern-gjentorne skoftar for dei er so få, og dei som ser ut gjenom gluggarne dimmest,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'og gatedørerne stengdest med kverne-duren spaknar; då ein ris upp med fyrste fuglekvitring, og alle songmøyar lågmælte vert;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'då ein og er rædd for kvar ein bakke, og skræmslor ventar på vegen, og mandeltreet blømer, og grashoppen karar seg fram, og kapersberet dovnar; for menneskja fer til sitt æve-hus, og gråtarane gjeng ikring på gata; -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'fyrr sylvsnori slitnar, og gullskåli brotnar, og krukka ved kjelda gjeng sund, og hjulet dett brotna i brunnen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'og moldi fer atter til jordi som fyrr ho var, og åndi gjeng atter til Gud som ho gav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Fåfengt, fåfengt! segjer Preikaren, alt er fåfengt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Umfram det at Preikaren var ein vismann, lærde han og folket kunnskap, og grunda og granska, han sette i hop mange ordtøke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Preikaren freista å finna vænleiks-ord, ærleg uppskrivne, sanningsord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Ord av vismenner er som broddar, og i samling er dei som islegne spikrar; dei er gåva frå ein og same hyrdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Men elles, son min, lat deg vara åt. Det er ingen ende på all bokskrivingi, men mykje gransking armar ut kroppen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Endelykti er dette, når du hev høyrt alt: Ottast Gud og haldt hans bodord! Det er målet for alle menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'For kvar gjerning vil Gud føra fram for domen yver alt det som løynt er, anten det so er godt eller vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Høgsongen av Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, '«Han meg kysse med kyssar av sin munn. For din elsk han er betre enn vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Dine salvar angar so ljuvt, ein utrend salve er ditt namn. Difor held møyar dei elskar deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, '«Drag meg etter deg. Og me spring. Kongen hev ført meg til sitt hus.» «Me vil fagnast og frygdast i deg. Me vil lova din kjærleik meir enn vin.» Med rette elskar dei deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '«Eg er brun, men like vel væn, de Jerusalems døtter, som Kedars tjeld, som Salomos dørtjeld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Sjå ikkje på at eg er so brun, at soli hev brent meg so. Mor sine søner harmast på meg, og meg sette til vingardsvakt. Eg hev ikkje vakta eigen gard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Seg, du som leikar i min hug, kvar gjæter du no? Kvar held du middagskvild? Må eg sleppa på villa å ganga i hjordi til felagarn’ dine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '«Um du ikkje det veit, du fagraste dros, du fylgje i drifti sitt spor og gjæt dine killingar fram der som hyrdingarn’ buderne hev.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, '«Med folarn’ for Faraos vogn deg, min hugnad, eg liknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Di lekkjeprydde kinn er so væn, og din hals med perlor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Lekkjor av gull skal du få med sylv-prikkar på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '«Når kongen i laget sit sat, min narde han anga då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Ein myrra-pung er min ven, som eg ber ved min barm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Ein cyper blom-dusk er min ven meg i En-Gedis hagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '«Å, kor du er fager, mi møy, kor du er fager! Dine augo er duvor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '«Å, kor du er fager, min ven, kor du er ljuv. Og vårt lægje er grønt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Cedrar er bjelkarn’ i vårt hus, cypressar er himling.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, '«Ein engblom frå Saron er eg, ei lilja frå dalom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '«Ja, som ei lilja i klunger-holt millom møyar min hugnad er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, '«Liksom ein apall, i skogen stend er venen min millom sveinar. Eg sitje so ljuvt i skuggen hans, og søt er frukti i munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Inn i vinhuset hev han meg ført, og hans merke yver meg det er kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Å, styrk meg med druvekakor, med eple meg kveik! For eg er sjuk av kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Hans vinstre hand er under mitt hovud, med den høgre femner han meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Eg hjarteleg bed dykk, Jerusalems døtter, ved gasellor og hindar i skog, at ikkje de vekkje eller eggje kjærleik, fyrr sjølv han so vil!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '«Høyr! Min ven! Sjå der, han kjem! Yver fjelli, sjå, han sprett, yver haugarne han renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Min ven ei gasella er lik eller som ungan hjort. Sjå der! No han stend attum vår vegg. Gjenom glyttom ser han inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Han tek til min ven å tala til meg: «Du, min hugnad, statt upp, du, mi fagre, kom ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'For sjå, no er vinteren slutt, regnet hev kvorve burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Du ser blomarne sprett utpå voll. D’er det bilet dei vintrei skjer, og turtelduva ho syng i vårt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Fiketreet skyt frukt, vintrei stend alt i blom med angande dåm, du, min hugnad, statt upp, du, mi fagre, kom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Du, mi duva, i bergeskard, som i fjellveggen sit, lat ditt andlit meg sjå, lat meg høyra ditt mål, for ditt mål er so ljuvt, og ditt andlit so vænt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, '«Fare av og revarne slå, dei revarne små, som i hagom mun gå, for hagarne no, dei tek til å gro.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Min ven er min, og eg er hans, han som gjæter millom liljor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, '«Skrid du, min ven, til dagen vert sval, og skuggarne flyr, ei gasella lik eller ungan hjort uppi skardefjellom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, '«Eg leita på kvila um natt etter honom som leikar i min hug. Eg leita, men honom ikkje fann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Eg vil upp og sviva gjenom by, fara i gator, yver torg, og søkja han som leikar i min hug. Eg leita, men honom ikkje fann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Eg vaktar møtte, som i byen sveiv. «Hev de set han som leikar i min hug?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Snaudt hadd’ eg kome framum deim, då eg fann han som leikar i min hug. Eg heldt han og eg slepte han’kje laus, fyrr eg fekk han i huset hennar mor, inn i kleven hennar som meg åtte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Eg hjarteleg bed dykk, Jerusalems døtter, ved gasellor og hindar i skog, at ikkje de vekkje eller eggje kjærleik, fyrr sjølv han so vil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, '«Kven er ho, som frå heidi stig upp, lik kvervlande røyk, umfløymd av angande myrra, av røykje og dåm-urter alle?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Sjå Salomos båra det er med seksti kjempor ikring, dei av Israels herkjempor er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Dei alle er væpna med sverd og er røynde i strid. Kvar ein ber sverdet ved lend imot rædslor um natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Kong Salomo berestol fekk seg av Libanons tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Han av sylv heve stolparne gjort og karmen av gull, der er purpurlagd sess. Inni prydd - ei kjærleiksgåva frå Jerusalems døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Gakk ut og sjå, de Sions døtter, på kong Salomo, med kruna han fekk av si mor på sin brudlaupsdag, på sin hjarte-fagnads dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, '«Å, kor du er fager, min hugnad, kor du er fager! Dine augo er duvor, glytter fram attum slør. Ditt hår er ein geiteflokk likt, ned Gilead renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Dine tenner som nyklypte sauer, nett komne frå laug. Tvillingar alle dei hev, og utan lamb er ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Dine lippor ei purpursnor er, og so ljuv er din munn. Som eit granateple-brot er din tinning glytter fram attum slør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Som Davids-tårnet din hals, for stridsfolk bygt; tusund skjoldar på det heng, alle skjoldar åt kjemporne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Eit killingpar barmen, tvillingar til ei gasella som beiter millom liljor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Til dess dagen vert sval, og skuggarne flyr, til Myrra-berg skrid eg min veg og til røykjelse-haugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Alt ved deg er fagert, min hugnad, du lytelaus er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, '«Med meg frå Libanon, brur, med meg frå Libanon kom! Stig fram frå Amanas tind, frå Senir og Hermons topp, frå løveheimar og panterfjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hev trylt meg, mi syster, mi brur, du trylt meg med eit einaste augnekast, med ei einaste lekk i din halsring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kor fager er din elskhug, mi syster, mi brur, kor tjuvleg din elskhug framum vin, kor dei angar dine salvar framum balsam all.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Av honning dryp dine lippor, mi brur, tunga di gøymer honning og mjølk, dine klæde hev ein dåm som frå Libanon sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ein avstengd hage er mi syster, mi brur, ei avstengd olla, ei attsigla kjelda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'som ein granattre-park skyt du upp med gildaste frukt, med cyper og nardeblom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'med narde, safran, kalmus, kanel og dåmurt av alle slag, myrra og aloe og dei beste av alle slag kryddor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'som ei hagekjelda, ein brunn med rennande vatn, med tilsig frå Libanon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '«Vakna, nordanvind, kom, du sunnanvind, gjenom hagen min blås, so angen fær strøyma, og venen til hagen sin kjem og et si kostelege frukt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, '«Ja, eg kjem til min hage, mi syster, mi brur, min myrra og balsam eg plukkar, mitt brød og min honning eg et og drikk min vin og mi mjølk. Ete lagsbrør, drikk dykkar nøgd, vener.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, '«Eg låg og sov. Men mitt hjarta vakte, høyr! Der bankar min ven: Mi syster, min hugnad, lat upp, du mi duva, mi frægd! Mitt hovud er vått, av nattedogg lokkarne dryp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '«Eg hev teke av meg kjolen, skal eg klæda på meg att? Eg hev tvege mine føter, skal eg sulka deim til att?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Min ven rette handi gjenom loka inn, då kløkktest mitt hjarta for hans skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'So reis eg upp, vilde opna for min ven, av handi mi myrra det draup, av fingrarne rennande myrra det flaut og på dørlåset rann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'So opna eg døri for min ven - då venen var kvorven burt. Og hugsprengd eg tenkte på hans ord. Eg søkte, men ikkje honom fann. Eg ropa på han, men ikkje gav han svar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Meg vaktaran’ møtte som i byen sveiv, dei meg slo, gav meg sår, og sløret ifrå meg dei tok, vaktaran’ på murom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Eg hjarteleg bed dykk, Jerusalems døtter, um de skulde finna min ven, - ja, kva skal de honom segja? - At sjuk av kjærleik eg er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '«Kva er din ven framom andre vener, du fagraste dros? Kva er din ven framum andre, når du naudbed oss so?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, '«Min ven er ljosleitt og raud, utmerkt framum ti tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hovudet skiraste gull, palmegreiner er lokkarn’, svarte som ein ramn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Augo som duvor ved rennande å, dei som laugar seg i mjølk ved braddfull sjø.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Kinni som balsam-sengjer, som dåmurt-skrin. Lipporne liljor, som dryp av rennande myrra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Henderne teiner av gull med krysolitar sette, midja av filsbein med safirar prydd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Føterne marmor-stolpar på fine gull-stettar. Som Libanon er han å sjå, som ein ceder traust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Hans munn er søt, hugnad er han all. Slik er venen og felagen min, de Jerusalems døtter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '«Kvar helst er han gjengen, din ven, du fagraste dros? Kvar helst hev din ven svive av, so me kann leita med deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, '«Min ven gjekk til hagen sin ned, til balsam-sengjer, til å gjæta i hagom og liljor sanka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, '«Min ven er min og eg er hans, han som gjæter millom liljor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, '«Du er fager, du min hugnad, som Tirsa, som Jerusalem er du frid, som herfylgje ageleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Snu augo dine ifrå meg, for dei magtstel meg. Ditt hår er ein geiteflokk likt, ned Gilead renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Dine tenner ein flokk med sauer, komne upp or laug, med tvillingar alle, utan lamb er ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Som eit granateple-brot din tinning glytter fram attum slør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Seksti dronningar, åtteti fylgjekvende, av møyar ein endelaus lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Men ei einast’ mi duva, mi frægd, einaste barnet til mor, brikna hennar som henne åtte. Ho vert sælka av møyar, henne ser, av dronningar og fylgjekvende lova.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '«Kven er ho som lik morgonroden gloser, som fullmånen fager, brikjeleg som sol, som herfylgje ageleg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, '«Eg gjekk ned i natahagen, vilde sjå kor det grønkast i dale, vilde sjå um vintreet spratt, um granateple-treet bar blom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Eg visste’kje av, fyrr hugen meg drog og meg sette på mitt gjæve folks vogn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '«Å, snu deg, snu deg, Sulammit! Snu deg, snu deg, so me deg ser.» «Kva er det å sjå på Sulammit?» «Ein dans som i Mahanajim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '«Kor fagert din fot stig på skoen, du gjævings møy. Dine lender er bogne som ei sylgja, smidd av ei kunstnarhand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Fanget som skåli rund, ho aldri vante vin. Livet ein kveitehaug med liljor ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Eit killingpar barmen, tvillingar til ei gasella.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Din hals som eit filsbeinstårn, augo som Hesbons tjørner ved Bat-rabbims port. Nasen som Libanons tårn, som vender imot Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Ditt hovudet som Karmel ris upp, og lokkarne purpur er, ein konge i flettom er fanga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, '«Å, kor fager, kor frid du er, du kjærleik so hugnadrik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Som ei palma er du i vokster, som druvor din barm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Eg meiner upp i palmen eg stig, i stylkerne tek eg tak, din barm skal vera som druvor, din ande er som dåm av eple.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Og munnen som ljuvaste vin.» «Som lett glid ned for min ven og kveikjer sovandes lippor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Til min ven høyrer eg, og til meg stend hans trå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, '«Kom so min ven, ut på marki lat oss gå og i byom oss kvara!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Og i otta inni vingardom sjå, um vintreet sprett, um knupparne spring, um granattreet blømer! Der vil eg gjeva min elsk til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Frå kjærleiks-epli strøymer ein fræn, alle slag frukt er ved dørom. Nye og gamle, min ven, hev eg gøymt til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Å, gjev at du var som ein bror for meg, hadde soge mor sitt brjost. Um eg då fann deg der ute, eg deg kysste, og ingen meg neiste for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Eg leidde deg, førde deg til mor sitt hus, og du lærde meg, eg kryddevin gav deg, saft frå mitt granattre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hans vinstre er under mitt hovud, med den høgre femner han meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Eg hjarteleg bed dykk, Jerusalems døtter, at de ikkje vekkje eller eggje kjærleik, fyrr sjølv han so vil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, '«Kven er ho som frå heidi stig upp, studd til sin ven?» «Under apallen vekte eg deg. Der åtte ho deg di mor, der fekk ho deg ho som deg fødde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, '«Ved hjarta meg hav som eit segl, som eit segl på din arm. Kjærleik som dauden er sterk, som helheimen strid i si trå. Ho logar som logande eld, gneisten frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Kor store vatni so er, dei aldri fær kjærleik sløkt, ingi elvar kann fløyma han burt. Um du alt som du åtte for kjærleik baud, so vart du berre til narr.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, '«Ei liti syster me eig, ho hev ingen barm. Kva skal me med syster gjera, den tidi når belarar kjem?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, '«Er ho ein mur, me byggjer på den ein murkrans av sylv. Men er ho ei dør, me stengjer ho att med eit cederspjeld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, '«Eg er ein mur, og min barm som tårni på den. Då vart eg i augo hans ei som finn fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'I Ba’al-Hamon ein vingard hev Salomo ått. Han garden til vaktarar gav. Kvar mann for dråtten fekk dei tusund sekel sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Min vingard den hev eg sjølv, dine tusund du Salomo tak, tvo hundrad på vaktaran’ fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Du som bur inni hagom, felager lyder, lat meg høyra ditt mål!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '«Å fly, du min ven, ei gasella lik eller ungan hjort på dei angande fjellom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Dette er dei syner som Jesaja, son åt Amos, fekk um Juda og Jerusalem i dei dagarne då Uzzia, Jotam, Ahaz og Hizkia var kongar i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Høyr, de himlar, og lyd etter, du jord! for Herren talar: Eg hev fostra born og født deim upp, men dei hev falle frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Ein ukse kjenner eigarmannen sin, og eit asen krubba åt herren sin; men Israel kjenner inkje, mitt folk sansar inkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Usæl er den synduge slegti, det skuldtyngde folket, eit ætt av illgjerdsmenner, rangsnudde born! Dei hev vraka Herren, vanvyrdt den Heilage og vendt honom ryggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Tolar de meir tukt, sidan de held ved med fråfall? Hovudet er som eit einaste sår, og hjarta er gjenomsjukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Frå hovud til fot finst det ikkje noko heilt, berre flengjor, flerror og nyhogne sår, som korkje er reinsa eller umbundne eller mykte med olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Ei øydemark er landet dykkar, brandtufter byarne dykkar, årsgrøda et framande upp framfor augo på dykk; alt vert lagt i øyde, soleis som berre framandfolk kann herja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Berre dotteri Sion er att, liksom ei hytta i ein vinhage, eit natteskjol på ei agurkmark, som ein kringsett by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Hadde ikkje Herren, allhers drott, unnt oss ein liten leivning, då hadde me vorte som Sodoma, me hadde set ut som Gomorra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Høyr Herrens ord, de Sodoma-fyrstar, lyd etter vår Guds lov, du Gomorra-folk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Kva skal eg med alle slagtofferi dykkar? segjer Herren. Eg leidest ved brennoffer av verar og ved feitt av gjødkalvar; og blod av uksar og lamb og bukkar hugar meg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Når de kjem og vil visa dykk for mi åsyn - kven hev kravt slikt av dykk, at de skal trakka ned mine fyregardar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ber ikkje fram fleire falske grjonoffer; angen av deim styggjest eg ved. Nymåne og kviledag og tillyst møte, høgtidsferd og fanteferd hand i hand - eg toler det ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Dykkar nymånar og høgtider hatar mi sjæl, dei hev vorte meg ei byrd, som eg ikkje orkar bera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Kor mykje de retter ut henderne dykkar, so let eg att augo, og kor mykje de bed, so høyrer eg ikkje; for henderne dykkar er fulle av blod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Tvætta dykk, reinsa dykk! Slutta med dykkar vonde åtferd for augo mine, haldt upp med å gjera det som vondt er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lær å gjera godt, legg vinn på det som rett er, vis valdsmannen på betre vegar, hjelp den farlause til retten sin, før saki åt enkja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Kom og lat oss føra sak med einannan, segjer Herren. Um synderne dykkar er som purpur, so skal dei verta kvite som snø. Um dei er raude som skarlak, so skal dei verta som ull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Berre de er viljuge og lyder, so skal de få njota det gode i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Men er de motviljuge og tråssuge, so skal sverdet øyda dykk ut. For Herrens munn hev tala!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Kor ho hev vorte ei skjøkja, den trufaste borgi! Fyrr full av rett, rettferd budde derinne, og no - mordarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Sylvet ditt hev vorte til slagg, med vatn er vinen din blanda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Dine styresmenner er upprørsmenner, dei held lag med tjuvar. Alle so elskar dei mutor og jagar etter vinning. Den farlause hjelper dei ikkje til retten sin, og saki åt enkja kjem ikkje deim ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Difor segjer Herren, Herren, allhers drott, Israels Velduge: Ja, eg vil sløkkja harmen min på mine uvener, og taka hemn yver fiendarne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Og eg vil retta mi hand imot deg og reinsa ut ditt slagg som med lut, og skilja ut alt ditt bly.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Og atter vil eg gjeva deg slike domarar som du hadde fyrr, og slike rådsmenner som du ein gong åtte. Og då skal du heita «rettferdsby», «den trufaste borgi».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Ved rett skal Sion verta utløyst og ved rettferd dei som umvender seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Men undergang skal råka alle illgjerdsmenner og syndarar; og dei som vender seg frå Herren, skal ganga til grunnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Ja, de skal få skam av dei eiker som var dykkar hugnad; og de skal blygjast av dei hagar som var dykkar lyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'For de skal verta som ei eik med visnande lauv og som ein hage utan vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Og den sterke skal verta til stry og hans verk til ein gneiste, og dei brenn båe til saman, og ingen sløkkjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Det ordet som Jesaja, son åt Amos, såg um Juda og Jerusalem:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Og det skal verta soleis i dei siste dagar, at det fjellet der Herrens hus stend, skal vera grunnfest på toppen av fjelli, og høgt yver haugarne, og alle folki skal strøyma burt til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Og mange folk skal bu seg til ferd og segja: «Kom, lat oss fara upp til Herrens fjell, til huset åt Jakobs Gud, at han må læra oss um sine vegar, so at me kann ganga på hans stigar!» For lovlæra skal ganga ut frå Sion, og Herrens ord frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Og han skal døma imillom folki og skipa rett åt mange folkeslag. Då skal dei smida plogjarn av sverdi sine, og hagesigdar av spjoti sine. Folk skal ikkje lenger lyfta sverd mot folk, og ikkje lenger temja seg upp til krigsferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Jakobs ætt, kom, lat oss ferdast i Herrens ljos!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Du hev støytt frå deg folket ditt Jakobs ætt, for di dei er fulle av trolldom frå Austerland og driv med spådomskunster som filistarane, og gjer samband med framande folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Landet deira er fullt av sylv og gull, og eignaluterne tryt ikkje. Landet deira er fullt av hestar, og vognerne deira er uteljande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Landet deira er fullt av avgudar, dei fell på kne for verk av sine eigne hender, for det som deira eigne fingrar hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Difor vert menneskja bøygd og mannen mykt, du kann ikkje tilgjeva deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Fly inn i fjellet, gøym deg i jordi for Herrens rædsla, for hans høgvelde og herlegdom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Menneskja skal slå ned sine stolte augo, og mannsens stormod skal bøygjast, og einast Herren standa høg på den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'For ein dag hev Herren, allhers drott, sett, som skal koma yver alt det kaute og keike, og yver alt det som ris i veret, so det skal verta lite og lågt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Yver alle cedrar på Libanon, dei høge og stolte, og yver alle Basaneikerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'yver alle høge fjell og stolte høgder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'yver alle høge tårn og alle faste murar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'yver alle Tarsis-skip og yver alt som er fagert å skoda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Då skal ovmodet i menneskja knekkjast og mannsens stormod bøygjast, og einast Herren skal standa høg på den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Med avgudarne er det ute for ollo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Og folk skal fly inn i hellerar og jordholor for Herrens rædsla og for hans høgvelde og herlegdom, når han reiser seg og skræmer jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'På den dag skal menneskja kasta for moldvarpar og skinnvengjor avgudarne sine av sylv og gull, som dei hev gjort seg til å falla på kne for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Og dei skal fly inn i fjellskortor og skard for Herrens rædsla og for hans høgvelde og herlegdom, når han reiser seg og skræmer jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'So set ikkje lenger dykkar lit til menneskja, som berre eig ein liten livspust i nosi si! Kva er ho å bry seg um?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'For sjå Herren, Allhers-Herren, skal taka burt frå Jerusalem og Juda kvar studnad og stav, kvar studnad av mat, og kvar studnad av vatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'kjempa og stridsmann, domar og profet, spåmann og styresmann,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'femtimanns-førar og vyrdingsmann, rådsherre og handverksmeister og trollkunnig mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Og eg skal gjeva deim unggutar til styrarar, og gutehått skal råda yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Og folket - den eine skal plåga den andre, kvar ein sin granne. Guten skal setja seg upp imot den gamle, fanten imot fagnamannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Når det då hender, at ein fær tak i ein annan i huset åt far hans, og segjer: «Du eig då ein klædnad, ver du styraren vår! Tak då rådvelde yver dette fallande riket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'då skal han svara og segja: «Eg er ingen sårlækjar, i mitt hus er korkje brød eller klæde; gjer ikkje meg til styrar yver folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'For Jerusalem snåvar og Juda fell, av di dei i ord og gjerd stend Herren imot, og er tråssuge framfor hans herlegdoms åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Sjølve andlitssvipen deira vitnar imot deim, og liksom i Sodoma talar dei utan dulsmål um syndi si. Ve deira sjæl! For dei valdar seg sjølv ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Seg um den rettferdige at det skal ganga honom godt; frukti av si gjerning skal han njota.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Men usæl den ugudlege! honom skal det ganga ille; hans eigne gjerningar hemnar seg på honom sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Styraren yver mitt folk er eit barn, og kvinnor råder yver det. Mitt folk, førarane dine fører deg vilt, og gjer vegen du skal fara til villstig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Herren hev stige fram, han vil føra sak, han stend og vil døma folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Herren held rettargang med sitt folks styresmenner og hovdingar: «De hev plundra vinhagen! Ran frå fatigmannen er i husi dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Korleis kann de soleis skamfara mitt folk og trakka dei fatige under fot?» segjer Herren, Allhers-Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Og Herren segjer: «Av di Sions døtter briskar seg og gjeng med bratt nakke og spelar med augo, og gjeng og trippar og ringlar med fotringarne sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'so skal Herren gjera kruna skurvut på Sions døtter, og Herren skal nækja deira blygsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'På den dagen tek Herren frå deim all stasen deira: Fotringar, panneband, halssylgjor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'øyredobbor, armband, slør,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'hovudpryda, fotkjedor, belte, lukteflaskor, amulettar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'fingergull, naseringar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'høgtidsbunader, kåpor, kasteplagg, pungar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'speglar, serkjer, huvor, flor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Og det skal verta illtev i staden for godange, reip i staden for belte, fleinskalle i staden for flettor, sekkjety i staden for høgtidstidsbunad og svidmerke i staden for vænleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Mennerne dine skal falla for sverd og kjemporne dine i krig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Og portarne hennar skal gråta og låta, og einsleg sit ho att i gruset.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Og på den dagen skal sju kvinnor triva i ein og same mann og segja: «Me vil sjølve både føda og klæda oss, berre me fær bera namnet ditt! Fri oss frå vanæra vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'På den dagen skal Herrens renning vera til pryda og herlegdom, og landsens frukt gild og fager for leivningen av Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Og det skal vera soleis, at den som er att i Sion og etterleivd i Jerusalem, han skal kallast heilag, kvar og ein som er innskriven til liv i Jerusalem -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'når Herren fær tvætta av ureinskapen hjå Sions døtter og reinsa blodskuldi ut or Jerusalem med doms-ande og reinsings-ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Og yver alt Sions-fjell og møtelydarne der skal Herren skapa ei sky og ein røyk um dagen og skinet av ein logande eld um natti; for yver all herlegdomen skal det vera ein kvelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Og ei hytta skal vera til livd mot dagsens hite og til vern og berging mot uver og regn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Eg vil syngja um min ven, songen åt min ven um hans vinhage, min ven hadde ein vinhage på ein grøderik haug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Han hakka honom upp, han reinsa honom for stein og sette gode vintre der; han bygde eit vakttårn og hogg attpå ei vinpersa. So venta han seg ein haust av egte druvor, men fekk berre villbær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Og no, de Jerusalems-buar og de Juda-menner, døm no millom meg og min vinhage!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Kva meir var det å gjera med min vinhage enn eg hev gjort? Kvi bar han villbær, når eg venta meg egte druvor?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'So vil eg då kunngjera dykk kva eg etlar meg til å gjera med vinhagen min: Eg vil riva ned gjerdet, so han vert avbeitt, brjota ned muren, so han vert nedtrakka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Eg vil gjera honom til ei øydemark; han skal aldri verta kvista eller graven, men han skal gro full av torn og tistel, og skyerne vil eg bjoda dei skal ikkje senda regn yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'For vinhagen åt Herren, allhers drott, er Israels hus, og Juda-folket er hans kjæraste plantning; men når han venta lov, fann han rov, og når han venta rettferd, fann han uferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Usæle dei som legg hus til hus og åker til åker, til dess det inkje meir rom finst, so de bur åleine midt i landet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Frå Herren, allhers drott, kling det i øyro mine: Sanneleg, dei mange husi skal leggjast i øyde, kor store og gode dei er, skal ingen bu der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'For ein vinhage på ti plogland skal berre gjeva av seg eitt anker, og tri tunnor utsæde berre ei skjeppa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Usæle dei som årle hastar til sterk drykk og sit utetter natti eldraude av vin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Cither og harpa og trumma og fløyta og vin hev dei i drikkelagi sine, men Herrens gjerningar ansar dei ikkje, og verket av hans hender ser dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Difor lyt folket mitt fara i utlægd fyrr det varast, storkararne lida hunger, og dei skrålande skarar ormegtast av torste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Difor vert helheimen dess meir grådig og spilar upp sitt gap umåteleg, og ned sturtar dei som er store i byen, dei som ståkar og bråkar, og dei som hev gaman der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Då må menneskja bogna og mannen bøygjast, og dei stolte augo sjå ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Men Herren, allhers drott, vert høg ved domen, og den heilage Gud syner seg heilag ved rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Og lamb gjeng der på beite som på si eigi mark, og aude tufter etter rikmennerne beiter framande av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Usæle dei som dreg fram syndestraff med lygnetog og syndebot liksom med vognreip,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'dei som segjer: «Lat honom hasta og skunda seg med verket sitt, so me kann få sjå det! Lat Israels Heilage fullføra si rådgjerd, so me kann få kjenna henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Usæle dei som kallar det vonde godt og det gode vondt, dei som gjer myrker til ljos og ljos til myrker, dei som gjer beiskt til søtt og søtt til beiskt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Usæle dei som er vise i sine eigne augo og kloke i sine eigne tankar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Usæle dei som er kjempor til å drikka vin, og djerve karar til å blanda sterk drykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'dei som gjev den skuldige rett for gåvor skuld, og tek retten frå den rettferdige!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Difor, liksom eldslogen øyder strå, og halm skrøkk saman på bålet, soleis skal roti deira rotna og blomen føykjast burt som dust, for di dei vraka lovi åt Herren, allhers drott, og vanvyrde ordet åt Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Difor hev Herrens vreide loga upp imot folket hans, og han retter handi ut imot det og slær det, so fjelli skjelv, og lik ligg som sorp og saur på gatorne. Men med alt dette hev ikkje vreiden hans vendt seg; og endå retter han ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Og han reiser eit hermerke for heidningfolki langt burte og blistrar honom hit frå enden av jordi, og sjå, snart og snøgt kjem han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Det finst ingen der som er trøytt eller snåvar, ingen som blundar eller søv; på ingen losnar beltet um livet, ikkje ei skoreim slitnar på nokon av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Pilerne hans er kvasse, og bogarne hans er alle spente. Hovarne på hestarne er som flint, og vognhjuli hans likjest kvervelstorm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Han burar som løva, han murrar som ungløvorne; burande grip han sitt rov og ber det burt, og det er ingen som bergar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Det durar inn yver honom på den dagen som duren av havet; og skodar han på jordi, so er det myrker og naud, ljoset vert dimt under dei tunge skyer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Det året då kong Uzzia døydde, såg eg Herren sitja på ein høg og hæv kongsstol, og slæpet på klædnaden hans fyllte templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafar stod ikring honom. Kvar av deim hadde seks vengjer: med tvo gøymde dei andliti sine, med tvo gøymde dei føterne sine, og med tvo flaug dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Og den eine ropa til den andre og sagde: «Heilag, heilag, heilag er Herren Sebaot, all jordi er full av hans æra!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Grunnen under dørstokkarne riste når ropet ljoma, og huset vart fyllt med røyk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Då sagde eg: «Usæl er eg, no er ute med meg! for eg er ein mann med ureine lippor, og eg bur millom eit folk med ureine lippor, og augo mine hev set kongen, Herren, allhers drott!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Men ein av serafarne flaug fram til meg, han hadde i handi ein glod som han med ei tong hadde teke på altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Med den rørde han ved munnen min, og so sagde han: «Sjå, denne hev rørt ved lipporne dine, no er di misgjerd burte, og di synd er sona.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Og eg høyrde Herren tala og sagde: «Kven skal eg senda, og kven vil vera vår bodberar?» Då sagde eg: «Sjå her er eg, send meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Og han sagde: «Gakk av stad og seg til dette folket: «Høyr og høyr, men håtta ikkje! Sjå og sjå, men skyna ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Gjer hjarta hardt på dette folket, gjer øyro dauvhøyrt og gjer augo blinde, so dei ikkje ser med augo eller høyrer med øyro eller skynar med hjarta, og vender um og vert lækte.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Men eg sagde: «Kor lenge, Herre?» Han sagde: «Til dess byarne ligg aude og tome, og husi stend utan folk, og landet ligg att som ei øydemark,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'til dess Herren hev sendt folket langt burt, og øydestaderne hev vorte mange i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Og finst det endå att ein tiandepart, so skal den og øydast ut liksom ei terebinta eller ei eik, som berre rotstuven er att av, når dei vert nedhogne. Denne stuven skal vera eit heilagt sæde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Og det bar til i dei dagarne då Ahaz, son åt Jotam, soneson åt Uzzia, var konge i Juda, at den syriske kongen, Resin, og Israels-kongen Pekah, son åt Remalja, drog upp mot Jerusalem og vilde hertaka byen, men dei greide det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Og då det vart meldt til Davids hus at syrarane hadde lægra seg i Efraim, so skalv hjarta hans og hjarta åt folket hans, liksom tre i skogen skjelv i vinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Men Herren sagde til Jesaja: «Gakk ut med son din Sjear-Jasjub og møt Ahaz ved enden av vatsleidingi i den øvre dammen, på vegen til Bleikjevollen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'og seg til honom: Tak deg vel i vare og haldt deg i ro! Ottast ikkje og ver ikkje hugfallen for desse tvo rjukande brandarne, for blodsinnet åt Resin og Syria og Remaljasonen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Etter di Syria med Efraim og Remaljasonen hev lagt upp vonde råder mot deg og sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '«Me vil fara upp imot Juda og skjota det støkk i bringa og hertaka det og setja inn ein konge der, Tab’al-sonen,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'difor segjer Herren, Herren: Det skal ikkje lukkast, det skal ikkje henda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'For hovudet åt Syria er Damaskus, og hovudet åt Damaskus er Resin, og um fem og seksti år skal Efraim vera lagt i øyde, so det ikkje meir er eit folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Og Efraims hovud er Samaria, og hovudet åt Samaria er Remaljasonen. Vil de ikkje tru, skal de ikkje trygt få bu.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Og Herren heldt ved og tala til Ahaz og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '«Krev deg eit teikn av Herren, din Gud, anten nedan or helheimsdjupet, eller ovan ifrå høgdi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Men Ahaz svara: «Eg vil ikkje krevja noko, eg vil ikkje freista Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Då sagde han: «So høyr då, du Davids hus: Er det dykk ikkje nok, at de set tolmodet åt menneskje på prøva? Vil de og prøva Guds tolmod?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'So skal då Herren sjølv gjeva dykk eit teikn: Sjå, møyi vert med barn og føder ein son, og ho gjev honom namnet Immanuel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Sur mjølk og honning skal vera maten hans ved det leitet då han skynar å vanda det vonde og velja det gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'For innan sveinen hev skyn på å vanda det vonde og velja det gode, so skal det verta audt for folk i landi åt dei tvo kongarne som no fær deg til å fæla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Og yver deg og yver folket ditt og yver farshuset ditt skal Herren lata dagar koma som det ikkje hev vore maken til alt ifrå den tid då Efraim skilde seg frå Juda: assyrarkongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'For på den tidi skal Herren blistra på fluga langt burte ved elvarne i Egyptarland og på bia i Assyrialandet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'og dei skal koma og slå seg ned alle saman i dei aude dalarne og bergklufterne, i alle klungerrunnar og ved alle brynne-stader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'På den dagen skal Herren med ein rakekniv, som er tinga på hi sida av elvi, med assyrarkongen, raka av alt hår både ovantil og nedantil, jamvel skjegget vert avskrapa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'På den tidi skal ein mann føda ei kviga og tvo sauer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Men han skal få so mykje mjølk, at han kann leva av surmjølk; ja, alle som finst att i landet, skal liva av sur mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Og det skal verta soleis på den tidi, at der det no stend tusund vintre som er tusund sylvdalar verde, der skal det berre veksa torn og tistel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Med piler og bogar skal ein ganga dit; for alt landet ber torn og tistel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Og alle dei berg der dei no onnar med hakka, skal ingen meir setja sin fot på av otte for torn og tistel; dei skal verta hamnegangar åt uksar, og utmark som vert nedtrakka av sauer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Og Herren sagde til meg: «Tak deg ei stor tavla og skriv med menneskjeskrift: Brå-herfang Snøgg-ran!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Og eg vil taka meg pålitande vitne: presten Uria og Zakarja Jeberekjason.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Og eg gjekk inn til profetkona, og ho vart umhender og fekk ein son. Og Herren sagde til meg: «Gjev han namnet: Brå-herfang, Snøgg-ran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'For fyrr guten kann segja «far» og «mor», skal rikdomarne i Damaskus og herfanget frå Samaria berast fram for kongen i Assyria.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Og Herren tala framleides til meg og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '«Av di dette folket vanvyrder Siloahvatnet som renn so stilt, og hev sin hugnad i Resin og Remaljasonen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'sjå, difor let Herren koma yver deim det stride og velduge vatnet frå Storelvi - assyrarkongen og all hans herlegdom - og ho skal stiga yver alle trømarne og fløyma yver alle strenderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Ho skal trengja seg fram i Juda, fløda yver og breida seg og nå folk under hoka, og med sine velduge vengjer skal ho fylla ditt land, vidt og breidt, Immanuel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Bråka berre, de folkeslag, de skal brotna. Lyd etter, alle land langt burte! Bu dykk til strid! de skal brotna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Legg upp råd! ho skal verta til inkjes. Gjer avtale! han skal ikkje få framgang. For med oss er Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'For so sagde Herren til meg, då handi hans greip meg med magt, og han vara meg imot å ganga same vegen som dette folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'De skal ikkje kalla samansverjing alt det som dette folket kallar samansverjing, og ikkje ottast det som det ottast, og de skal ikkje skjelva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Nei, Herren, allhers drott, skal de halda heilag, honom skal de ottast, og for honom skal de skjelva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Han skal verta ein heilagdom og ein støytestein og ein bergstabbe til fall for båe Israels hus, ei snare og ei gildra for Jerusalems-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Og mange skal snåva og falla og skamslå seg, sitja fast i fella og verta fanga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Legg vitnemålet umbunde og læra forsigla i hjarta åt læresveinarne mine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Eg ventar på Herren, han som løyner si åsyn for Jakobs hus; på honom vonar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Sjå, eg og borni som Herren hev gjeve meg, me er teikn og varsel i Israel frå Herren, allhers drott, som bur på Sionsfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Men når dei segjer til dykk: «Søk til draugemanarar og spåvette, som kviskrar og mullar,» so svara: «Skal ikkje eit folk søkja til sin Gud? Skal dei frega ut dei daude for dei livande?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '«Til læra, til vitnemålet!» Segjer dei ikkje soleis, skal dei vera utan morgonrode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Dei skal flakka umkring i landet plåga og hungrande, og i sin hunger skal dei harmast og banna sin konge og sin Gud. Og dei skal skoda upp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'og dei skal skoda ned på jordi; men sjå, der er naud og natt og myrker og angest. Ut i svarte natti er dei drivne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Men myrker skal ikkje verta verande i det landet som no er i våde. I den tidi som gjekk, hev han late landet åt Sebulon og Naftali vera lite vyrdt, men i framtidi skal han lata vegen attmed havet koma til æra, landet på hi sida åt Jordan, heidningkrinsen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Det folket som ferdast i myrkret, skal sjå eit stort ljos; yver deim som bur i daudskugge-landet, skal ljoset stråla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Du aukar folket som du fyrr ikkje gav stor gleda; dei gled seg for di åsyn som ein gled seg i kornskurden, som ein frygdar seg når herfang vert utskift.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'For det tunge oket, kjeppen til ryggen deira, staven åt drivaren deira, hev du brote sund, liksom på Midjans-dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'For kvar ein styvel som stauka i stridsgny, og kvar blodsulka klædnad skal brennast og verta mat åt elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'For eit barn er oss født, ein son er oss gjeven, og herreveldet kviler på hans herdar, og han heiter Underfull, Rådgjevar, Veldug Gud, \'veleg Fader, Fredsfyrste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'So skal herredømet verta stort og freden utan ende yver Davids kongsstol og yver riket hans; det skal reisast og stydjast med rett og rettferd frå no og til æveleg tid. Brennhugen i Herren, allhers drott, skal gjera dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Eit ord sender Herren mot Jakob, det slær ned i Israel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'og heile folket skal merka det, Efraim og Samaria-buarne, som i hjartans storlæte og ovmod segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '«Tiglmurar hev rundt saman, men me skal byggja upp att med hoggen stein; morbertre er felte, men me skal setja cedertre i staden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Difor reiser Herren Resins uvener mot deim og eggjar fiendarne deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'syrarane frå den eine sida og filistarane frå den andre, og dei skal eta upp Israel med gløypande gap. Med alt dette hev ikkje vreiden hans vendt seg, og endå retter han ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Men folket vende ikkje um til honom som slær det, Herren, allhers drott, søkjer dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Difor høgg Herren både hovud og hale av Israel, palmegrein og sev, alt på ein dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Styresmann og storkar er hovudet, og ein profet som lærer lygn, er halen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'For dei som fører folket, fører vilt, og dei som let seg leida, gjeng til grunnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Difor kann ikkje Herren gleda seg yver ungdomarne deira og ikkje heller hava medynk med dei farlause og enkjorne; for alle saman so er dei gudlause og gjer det vonde, og kvar munn talar dårskap. Med alt dette hev ikkje vreiden hans vendt seg, og endå retter han ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'For gudløysa brenn som eld, øyder torn og tistel og kveikjer i den tjukke skogen, so han gjeng upp i høge kvervlar av røyk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Ved harmen til Herren, allhers drott, stend landet i loge, og folket vert til føda for elden; den eine sparer ikkje den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Dei høgg til høgre og hungrar endå, dei glefser til vinstre og vert ikkje mette; kvar og ein et holdet av sin eigen arm:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasse et Efraim og Efraim Manasse; og båe tvo til saman kastar seg yver Juda. Men med alt dette hev ikkje vreiden hans vendt seg, og endå retter han ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Usæle dei som gjev urettferdige lover, og som med all si skriving berre bokfører urett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'so dei kann trengja småfolk burt ifrå retten og rana frå armingarne i folket mitt det som deira er og gjera enkjor til sitt herfang og plundra farlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Kva vil de gjera på heimsøkjingsdagen, når undergangen kjem langt burtan ifrå? Kven vil de fly til etter hjelp, og kvar vil de gøyma skattarne dykkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Er det noko anna for enn å bøygja kne millom fangar eller å falla millom drepne? Med alt dette hev ikkje vreiden hans vendt seg, og endå retter han ut handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Usæl Assur, mitt vreideris! Min harm er staven i handi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Mot eit gudlaust folk sender eg honom, eg byd honom fara imot eit folk som eg er harm på, at han skal plundra og rana og trakka det ned som saur på gatorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Men soleis meiner ikkje han, og hjarta hans tenkjer ikkje soleis. Nei, hans hug stend til å øyda og rydja ut folk i mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Han segjer: «Er ikkje hovdingarne mine kongar alle i hop?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Hev det ikkje gjenge Kalno liksom Karkemis og Hamat liksom Arpad og Samaria liksom Damaskus?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Liksom mi hand hev nått kongeriki åt dei andre gudarne, endå gudebilæti var meir tallrike enn i Jerusalem og i Samaria,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'skulde eg ikkje då magta å gjera det same med Jerusalem og gudebilæti der som eg hev gjort med Samaria og gudarne der?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Men når Herren hev fullført alt sitt verk på Sionsfjellet og i Jerusalem, skal eg heimsøkja assyrarkongen for hans hjartans ovmodsfrukt og for hans høglyfte, stolte augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'For han segjer: «Med mi velduge hand hev eg gjort dette og med min visdom, for eg er gløgg. Eg flutte folkegrensorne, og rana eignaluterne deira, og i mitt velde støytte eg ned deim som sat i kongsstolarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'og handi mi greip etter skattarne åt folki liksom fuglereir, og liksom dei samlar egg som fuglarne er flogne av, soleis samla eg saman alle land på jordi, det fanst ingen som rørde vengen eller opna nebben til minste pip.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Skal då øksi briska seg imot honom som høgg med henne? eller sagi skrøyta mot den som sagar? Rett liksom kjeppen skulde svinga den som lyfter honom! eller staven honom som ikkje er av tre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Difor skal Herren, Allhers-Herren, senda tærande sott i den feite kroppen hans, og under hans herlegdom skal ein eld loga upp som eit brennande bål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Israels ljos skal verta ein eld, og den Heilage i Israel til ein loge, og dei skal brenna upp og øyda hans tornar og tistlar, alt på ein dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Og han skal gjera ende på dei gilde skogarne og aldehagarne hans med rubb og stubb; han skal verta liksom ein sjukling som visnar burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Dei tre som vert att i skogen hans, skal vera lett teljande, eit barn kann skriva deim upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'På den tid skal leivningen av Israel og det som er att av Jakobs hus ikkje lenger stydja seg til honom som slo deim, men trufast stydja seg til Herren, Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Ein leivning skal venda um, ein leivning av Jakob, til Gud den velduge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'For um so ditt folk, Israel, var som sanden ved havet, so skal berre ein leivning av det venda um. Undergang er fastsett, og fløymer fram med rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'For øyding og fastsett straffedom skal Herren, Allhers-Herren, lata koma yver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Difor segjer Herren, Allhers-Herren, so: Folket mitt, du som bur på Sion, ottast ikkje Assur, når han slær deg med ris og lyfter staven sin imot deg, soleis som dei gjorde i Egyptarland!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'For um ei liti stund er harmen min slokna, og min vreide vender seg til deira undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Og Herren, allhers drott, svingar svipa si yver honom, liksom då han slo Midjan ved Ramneberget; og staven hans er utrett yver havet, og han skal lyfta honom som i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'PÅ den dag skal byrdi hans falla av herdarne dine og oket hans av halsen din, oket skal brotna for ditt aukande hold.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Han kjem mot Ajjat, fer framum Migron; han let etter seg trænet i Mikmas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Dei fer yver skardet. «I Geba heldt me nattekvild!» Rama skjelv; Sauls Gibea flyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Skrik høgt, du dotter Gallim! Lyd etter, Laisa! Arme Anatot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena flyr, Gebim-buarne bergar sitt bu.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Endå same dagen stend han i Nob, han lyfter handi mot fjellet åt dotteri Sion, mot Jerusalems-haugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Sjå, Herren, Allhers-Herren, høgg kruna av med gruveleg kraft; dei rake stomnar er felte; dei røslege tre ligg brotne i bakken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Den tjukke skogen vert nedhoggen med øksi. Libanon fell for den herlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Men ein kvist skal renna or Isaistuven, og ein renning frå hans røter skal bera frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Og Herrens Ande skal kvila yver honom, anden med visdom og vit, anden med råd og styrke, anden med Herrens kunnskap og otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Han skal hava sin hugnad i Herrens otte, og han skal ikkje døma etter det augo ser, og ikkje skipa rett etter det øyro høyrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Han skal døma armingar med rettferd, og skipa rett med rettvisa for dei smålåtne i landet, og han skal slå jordi med riset i sin munn og drepa den gudlause med anden frå lipporne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Rettferd skal vera beltet um lenderne og truskap beltet um mjødmarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Då skal ulven bu saman med lambet, og panteren liggja i lag med kidlingen; og kalven og ungløva og gjødfeet skal semjast saman, og ein smågut skal gjæta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Kui og bjørnen skal beita saman, ungarne deira skal liggja i lag, og løva skal eta halm som ein ukse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Sogbarnet skal leika seg innved bolet til hoggormen, og barnet som nyst er avvant, skal retta handi inn i hola åt basilisken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ingen skal gjera det som vondt eller skadelegt er, på heile mitt heilage fjell; for landet er fyllt av kunnskap um Herren, liksom vatnet fyller havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'På den dagen skal heidningfolki søkja til rotrenningen av Isai, som stend til fana for folki; og bustaden hans skal vera herleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Og på den dagen skal Herren endå ein gong retta ut handi og vinna leivningen av folket sitt, det som er att frå Assyria og Egyptarland og Patros og \'tiopia og Elam og Sinear og Hamat og havstrenderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Og han skal reisa ei fana for folki og samla dei burtdrivne menner av Israel og sanka saman dei spreidde kvinnor av Juda frå heimsens fire hyrno.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Då skal Efraims ovund kverva, og uvenskapen hjå Juda vika; Efraim skal ikkje hysa ovund mot Juda og Juda ikkje visa uvenskap mot Efraim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Som rovfuglar skal dei slå ned på herdarne åt filistarane i vest, og sameinte skal dei taka herfang av austerlendingarne. På Edom og Moab skal dei leggja hand, og Ammons-borni skal lyda deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Og Herren skal turka upp viki av Egyptarhavet, og i brennande harm svinga handi yver elvi, og han skal kløyva henne i sju bekkjer, so ein kann ganga turrskodd yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'So skal det verta ein brøytt veg for leivningen av folket hans, som er att frå Assyria, liksom det var for Israel den dagen dei drog upp frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'På den dagen skal du segja: «Eg takkar deg, Herre, for du var vreid på meg, men vreiden din kvarv, og du trøysta meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Sjå, Gud er mi frelsa, eg er trygg og ottast ikkje; for Herren, Herren er min styrke og min lovsong, og han vart meg til frelsa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Og med fagnad skal de ausa vatn or frelse-kjeldorne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Og de skal segja på den dagen: «Takka Herren, kalla på hans namn, kunngjer bland folki hans verk, fortel at hans namn er høgt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Syng lov for Herren, for storverk hev han gjort! Lat heile verdi få vita det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Ropa av frygd og fagnad, de som bur på Sion! For stor er Israels Heilage hjå dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Framsegn um Babel, som Jesaja, son åt Amos, skoda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Reis eit merke på skoglaust fjell, ropa høgt til deim, veifta med handi, at dei må koma og draga inn gjenom portarne åt valdsherrarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Eg hev bode ut dei vigde mennerne mine, ja, til å føra fram min vreide hev eg kalla kjemporne mine, dei sigerbyrge, jublande skarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Høyr, bråk på fjelli som av eit stort folk! Høyr gnyen av kongerike, av folk som strøymer i hop! Herren, allhers drott, mynstrar stridsheren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Ifrå land langt burte kjem dei, frå himmelens ende, Herren og hans vreide-verkty, og vil herja heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Jamra dykk! for Herrens dag er nær; han kjem som vald frå Allvald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Difor sig alle hender, og alle mannshjarto brånar i barmen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Dei skjelv, verk og ve tek deim, dei vrid seg som ei fødande kvinna. Vitskræmde stirer dei på kvarandre, raude som eldslogar er dei i andlitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Sjå, Herrens dag kjem gruveleg, full av vreide og brennande harm, og skal gjera jordi til ei øydemark, og rydja ut syndarane hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'For stjernorne og stjernebilæti på himmelen let ikkje ljoset sitt skina, myrk er soli når ho renn, og månen let ikkje ljoset sitt stråla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Eg vil heimsøkja jordi for vondskapen og dei gudlause for deira misgjerningar, eg vil gjera ende på storlætet åt dei ovmodige og døyva byrgskapen hjå valdsherrarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Eg skal gjera folk meir sjeldsynte enn fint gull, menneskje meir sjeldsynte enn gull frå Ofir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Difor vil eg skaka himmelen, og jordi skal fara bivrande upp frå sin stad ved harmen åt Herren, allhers drott, på den dagen vreiden hans brenn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Som skræmde gasellor, som sauer som ingen sankar, skal dei snu heim, kvar til sitt folk, og fly kvar til sitt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Kvar den som vert funnen, vert gjenomstungen, og kvar den som vert gripen, skal falla for sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Småborni deira skal krasast framfor augo deira; husi deira skal verta herja og kvinnorne deira valdtekne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Sjå, eg eggjar mot deim medarane, som ikkje bryr seg um sylv eller trår etter gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Bogarne deira skal fella gutarne; med livsfrukt hev dei ingen medynk, borni sparer dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Og med Babel, kruna millom riki, den stolte kaldæar-pryda, skal det ganga som då Gud lagde Sodoma og Gomorra i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Aldri meir skal det byggjast att; frå ætt til ætt skal ingen bu der; ingen arab skal slå upp sitt tjeld, og ingen hyrding lægra seg der med si hjord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Men villdyr skal liggja der, og husi fyllast av hubro; strutsar skal bu der, og raggetroll hoppa ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Ulvar skal yla i borgerne og sjakalar i vellyst-slotti. Snart stundar timen til, og dagarne skal ikkje drygast ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'For Herren skal miskunna Jakob og endå ein gong velja ut Israel og lata deim koma til ro i landet deira; og utlendingar skal sameina seg med deim og halda seg til Jakobs hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Og folkeslag skal taka deim og føra deim heim att; men Israels hus skal leggja deim under seg som ein arvlut i Herrens land, og skal gjera deim til trælar og trælkvinnor. Dei skal få fangevaktarane sine til fangar og råda yver valdsherrarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'På den dagen, då Herren gjev deg kvild for di møda og din angest og frå den harde trældomen din, som vart lagd på deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'då skal du syngja denne spottevisa um kongen i Babel og kveda: «Kor hev ikkje valdsherren vorte still og pinestaden tagall!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Herren hev brote sund staven åt dei gudlause, kongsstaven åt hardstyrarane,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'som slo folkeslag i harm med slag på slag og bøygde folk under seg i vreide og trælka deim utan nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'All jordi nyt no kvild og ro; dei bryt ut i fagnadrop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Jamvel cypressarne gled seg yver deg, cedrarne på Libanon: «Sidan du no ligg der, stig ingen hitupp og høgg oss ned.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Helheim der nede vert uroa for di skuld, når han skal taka imot deg. Han vekkjer skuggarne for di skuld, alle fyrstar på jordi; alle folkekongarne reisar seg frå sine kongsstolar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Alle so tek dei til ords og segjer til deg: «So er du og vorten magtlaus som me, no er du vår like!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Ned til helheimen hev din herlegdom sokke med brusen frå dine harpor; du ligg på ei roti lega, hev makkar til yverbreidsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kor er du’kje fallen frå himmelen, du strålande morgonstjerna, kor er du ikkje felt til jordi, du som slo ned folkeslag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Det var du som sagde i hjarta ditt: «Eg vil stiga til himmels, høgt yver Guds stjernor vil eg reisa kongsstolen min. Eg vil setja meg på Tingfjellet lengst uppe i nord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'eg vil stiga upp um skyborgi og gjera meg lik den Høgste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Ja, til helheimen laut du fara, lengst ned i svartaste hola.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Dei som ser deg, stirer på deg, undrast og segjer: «Er dette den mannen som skok jordi og fekk kongerike til å skjelva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'han som gjorde jordkringen til ei øydemark, jamna byarne med jordi, og som aldri gav fangarne heimlov?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Folkekongarne dei ligg alle vyrdeleg gravlagde kvar i sitt kvilerom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Men du er slengd ut, langt frå gravi di, som ei vanvyrd grein; du ligg yverbreidd med drepne, av sverdslegne menner - som vert kasta ned i ei steingrav - som ein nedtrakka daudskrott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nei, du fær ikkje vera saman med deim i gravi; for landet ditt hev du øydt og drepe ditt folk, og aldri meir skal nemnast det nidingseldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Gjev sønerne hans til dreping for misgjerdi åt deira feder! Ikkje skal dei få reisa seg og eigna til seg jordi og fylla verdi med byar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Eg vil reisa meg imot deim, segjer Herren, allhers drott, og eg skal rydja ut or Babel både namn og leivning, både born og barneborn, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Eg gjer det til heim for bustyvelen, og vil fylla det med søkkjemyrar, eg skal sopa det burt med tynings-sopa, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Herren, allhers drott, hev svore og sagt: I sanning som eg hev tenkt, soleis skal det verta, og det eg hev sett meg fyre, det skal hava framgang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Eg vil krasa Assur i landet mitt og trakka honom under fot på fjelli mine. So skal oket hans verta burtteke, og byrdi hans lyft av herdarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Dette er den råd som Herren hev teke mot all jordi; og dette er den hand som er utrett mot alle folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'For Herren, allhers drott, hev avgjort det; kven kann gjera det um inkje? Hans hand er det som er utrett; kven kann venda henne burt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Det året kong Ahaz døydde, kom denne framsegni:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Gled deg ikkje, alt Filistarland, for di staven som slo deg er sundbroten! for or roti åt hoggormen skal det koma fram ein basilisk, og hans frukt skal verta ein fljugande eiterorm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Dei armaste av dei arme skal finna rikeleg føda, og dei fatige få kvila i trygd! men di rot skal eg døyda med hunger, og leivningen av deg skal drepast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Jamra deg, du port! øya deg, du by! Miss modet, alt Filistarland! For nordan ifrå kjem ein røyk! i fiendeskararne dreg ingen seg att-or.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Kva skal ein då svara sendemennerne frå heidningfolki? At Herren hev grunnfest Sion, og at der finn armingarne i folket hans livd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Framsegn um Moab. Ja, på ei natt vert Ar-Moab øydelagt og gjort ende på! ja, på ei natt vert Kir-Moab øydelagt og gjort ende på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Dei stig upp til huset og til Dibon på haugarne og vil gråta; Moab jamrar seg på Nebo og Medeba. Kvart hovud er snaudt, kvart skjegg avraka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'På gatorne sveiper dei sekk um seg, på tak og på torg jamrar deim alle, tårorne fløymer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon og El’ale klagar høgmælt, so det høyrest radt til Jahas. Difor jamrar og hermennerne åt Moab seg! hans sjæl skjelv i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Hjarta mitt klagar yver Moab, for rømingarne hans flyr radt til Soar, til Triårs-kviga; gråtande gjeng dei upp stigen til Luhit, og på vegen til Horonajim jamrar dei høgt yver øydeleggjingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Ja, Nimrimsvatni vert øydemarker, graset turkast upp, brodden visnar, eit grønt strå er ikkje meir å sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Difor ber dei det som dei hev drege saman, sitt uppsparde gods, yver Vierbekken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Ja, klageropi gjeng yver alt Moabs land; til Eglajim når deira våling, og til Be’er-Elim når deira våling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'For Dimonsvatnet er fullt av blod. Og endå meir let eg koma yver Dimon: ei løva yver deim som er berga av Moab, yver leivningen i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, '«Send landsherren dei lamb han skal hava frå Sela gjenom øydemarki til fjellet åt dotteri Sion!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Liksom flaksande fuglar, som skræmde fuglungar, skal Moabs døtter koma til vadi yver Arnon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '«Gjev råd, finn utveg åt oss! Lat skuggen din vera som natti, no midt i dagsljoset! Gjev livd åt dei burtdrivne! svik ikkje den som flyr!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Lat mine burtdrivne finna tilhald hjå deg, ver ein verneskjold åt Moab imot mordaren! For det er ute med valdsmannen, øydeleggjingi fær ende, og trælkaren hev fare or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'So vert kongsstolen grunnfest ved mildskap, og det skal trygt sitja der ein fyrste i Davids tjeld, ein domar som fer etter det som rett er, og som fremjar rettferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Me hev høyrt um Moabs ovmod, det store og stolte, um hans ofse, byrgskap og ovlæte, um hans tome skryt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Difor skal Moab jamrar yver Moab, alt landet skal jamra seg. Yver druvekakorne i Kir-Hareset skal dei sukka i djup ørvæna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'For Hesbons vinmarker hev visna, Sibma-vintrei. Soldruvorne slo folkehovdingarne til jordi. Dei nådde radt til Jazer, og vildra seg ut i øydemarki; greinerne breidde seg ut, for yver havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Difor græt eg med Jaser yver Sibma-vintrei; med tårorne mine vil eg vatna deg, Hesbon, og deg, El’ale; for yver din frukthaust og vinhaust hev vinpersarropet slege ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Gleda og fagnad er kvorve or aldehagarne, og frå vinhagarne høyrest ikkje gledesongar eller fagnadrop; ingen trakkar druvor i persorne. Eg hev late vinpersarropet deira tagna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Difor bivrar mitt brjost for Moab som citherstrengjer, og mitt hjarta for Kir-Heres.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Og når Moab viser seg på offerhaugen og stræver der, og han kjem til heilagdomen sin og bed, so vinn han inkje med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Dette er det ordet som Herren fordom hev tala til Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Men no talar Herren so: Innan tri år - so som ein leigekar reknar åri - skal Moabs herlegdom og all hans store folkesverm vera lite vyrd, og leivningen som er att, skal vera liten og vesall, ikkje mykje verd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Framsegn um Damaskus. Damaskus skal ikkje lenger vera ein by, det skal verta ein grushaug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Aroer-byarne skal verta folketome; hjorder skal få deim til heim, dei skal liggja der, og ingen skræmer deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Og det skal vera slutt med borgi i Efraim og med kongedømet i Damaskus, med leivningen av Syria. Det skal ganga med deim som med herlegdomen åt Israels-borni, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'På den tid vert Jakobs herlegdom vesall, og holdet hans minkar burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Det skal ganga honom liksom når skurdmannen grip i åkeren og armen hans skjer aksi. Det skal ganga liksom når dei sankar aks i Refa’imsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Berre ein etterhaust skal verta att, liksom når ein slær ned ber av oljetreet, tvo, tri ber uppi toppen, ei fire, fem på greinerne åt frukttreet, segjer Herren, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'På den tid skal mannen venda seg til skaparen sin og augo hans sjå upp til Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Og han skal ikkje lenger venda si syn til dei altar hans hender hev gjort, og ikkje sjå på det fingrarne hans hev verka, korkje på Astarte-bilæti eller solstolparne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'På den tidi skal dei faste byarne deira verta liksom dei aude tufter i skogarne og på høgderne, dei som dei drog burt ifrå for Israels-borni skuld, og landet skal verta ei øydemark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'For du hev gløymt Gud, frelsaren din, og minnest ikkje ditt sterke fjell. Difor plantar du yndelege hagar og set utlendske vintre i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Den dagen du plantar, set du gjerde kringum, og um morgonen fær du plantningen til å bløma: avlen kverv på dagen med sjukdom og ulækjeleg pinsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Høyr brusen av mange folk! det bruser som havet bruser. Høyr dynen av folkeslag, det dyn som velduge vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Ja, det dyn av folkeslag som når store vatn dynja. Men han trugar deim, og dei flyr langt burt; dei vert føykte som agner for vind på fjelli, dei kverv som fjom i storm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Um kvelden, sjå då er det rædsla, og innan morgonen lyser, er han ikkje meir til. Soleis gjeng det deim som plundrar oss, dette er luten åt deim som ranar hjå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Høyr, du land med dei surrande vengjer, du land burtanfor elvarne i \'tiopia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'du som hev sendt bodberarar yver havet, og i røyrbåtar yver vatnet! Gakk av stad, de snøgge sendemenner, til det røslege folket med glansande hud, til folket som dei ottast vida ikring, det sterke og sigersæle folket i det landet som vert gjenomskore av elvar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Alle de som i heimsringen byggjer og på jordi bur: Når dei reiser merke på fjelli, so sjå til, og når luren ljomar, so høyr etter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'For so hev Herren sagt til meg: Logn vil eg skoda ned frå min bustad, liksom soli gløder ned um sumaren, og liksom skyi sender dogg i den heite skurdtidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'For fyrr hausten er inne, just då blømingi er til ende, og blomen fer til å mognast til druva, då skal han skjera av rankorne med hagesigden og hogga renningarne burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Dei skal alle saman verta gjevne åt rovfuglarne på fjelli og åt dyri i marki; rovfuglarne skal der hava reiri sine um sumaren, og alle dyr på marki skal hava sitt tilhald der um vinteren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'På den tidi skal det berast gåvor fram til Herren, allhers drott, frå det røslege folket med glansande hud, frå folket som dei ottast vida ikring, det sterke og sigersæle folket i det landet som vert gjenomskore av elvar - til den staden der namnet åt Herren, allhers drott, bur, til Sionsfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Framsegn um Egyptarland. Sjå, Herren fer fram på lette sky og kjem til Egyptarland. Då skjelv avgudarne i Egyptarland for honom, og hjarta åt egyptarane brånar i brjostet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Og eg vil eggja upp egyptar mot egyptar, so bror skal strida mot bror, og ven mot ven, by mot by og rike mot rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Og vitet åt egyptarane skal kverva or hjarta deira, og eg vil gjera deira råd til inkjes; dei skal fretta ut avgudarne og trollmennerne sine, og deim som manar fram draugar og spåvette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Men eg skal gjeva egyptarane i handi på ein hard herre, og ein illrådig konge skal rikja yver deim, segjer Herren, Allhers-Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Og vatnet i sjøen skal kverva, og elvi grunnast og turkast ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Elvarne skal tevja, kanalarne minka og turkast ut, røyr og sev visna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Engjarne frammed Nilen på åbakken og alt åkerland langs åi skal turkast upp, øydast og kverva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Fiskarane klagar, og alle dei som kastar krok i Nilen syrgjer, og dei som set ut garn i vatnet, stend handfalne av sut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Dei som yrkjer med hekla lin, vert til skammar, og dei som vev fint kvitt ty.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Landsens grunnpilarar er nedbrotne, og lønnsarbeidarane gripne av otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Hovdingarne i Soan er som fåmar; dei visaste millom rådsmennerne åt Farao gjev berre fåvise råd. Korleis kann de då segja til Farao: «Eg er ein son åt vismenner, ein son åt kongarne frå gamle dagar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Ja, kvar er då vismennerne dine, at dei kann vitra deg um og skyna kva Herren, allhers drott, hev etla seg til å gjera med Egyptarland?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Nei, hovdingarne i Soan hev vorte dårar, fyrstarne i Nof hev vorte til narr, dei som var hyrnesteinar for ætterne i Egyptarland, hev ført det på villstig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Herren hev gjeve deim ei svimrings-ånd, so at dei hev ført Egyptarland vilt i alle tiltak, liksom ein drukken mann ragar um i spyet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Egyptarland skal ikkje hava framgang med noko av sine tiltak, anten det so er hovud eller hale, palmegrein eller sev som tek seg det fyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'På den tidi skal Egyptarland vera som kvinnor; det skal bivra og ræddast for den lyfte handi åt Herren, allhers drott, som han lyftar imot det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Og Judalandet vert ei rædsla for egyptarane; so ofte nokon nemner det for deim, skal dei skjelva for den rådgjerd Herren, allhers drott, hev tek imot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'På den dagen skal det vera fem byar i Egyptarland som talar Kana’ans tungemål og sver ved Herren, allhers drott, ein av deim skal heita Ir-Haheres.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'På den dagen skal det vera eit altar for Herren midt i Egyptarlandet, og ein merkestein for Herren ved landskilet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Det skal vera til merke og til vitnemål i Egyptarlandet um Herren, allhers drott; når dei ropar til Herren um hjelp mot trælkarar, skal han senda deim ein frelsar og verjar og løysa deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Og Herren skal gjera seg kjend for Egyptarland, og egyptarane skal kjenna Herren på den dagen, og dei skal tena honom med slagtoffer og grjonoffer, og gjera lovnader til Herren og halda deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'So skal då Herren skal slå Egyptarland, slå, men og lækja; og når dei vender um til Herren, skal han bønhøyra deim og lækja deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'På den dagen skal det vera ein brøytt veg frå Egyptarland til Assyria, og assyrarane skal koma til Egyptarland og egyptarane til Assyria, og egyptarane skal tena Herren saman med assyrarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'På den dagen skal Israel vera tridjemann i sambandet med Egyptarland og Assyria, ei velsigning midt på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'for di Herren, allhers drott, signar deim og segjer: Signa vere du Egypt, mitt folk, og du Assyria, verket av mine hender, og du Israel, min arv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Det året då Tartan kom til Asdod, den gongen Sargon, kongen i Assyria, sende honom, og han stridde mot Asdod og hertok det -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'på den tidi tala Herren gjenom Jesaja, son åt Amos, soleis: «Upp, løys din klædnad av sekkjety av lenderne dine og drag skorne av føterne dine!» Og han gjorde soleis og gjekk naken og berrføtt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Og Herren sagde: «Liksom tenaren min, Jesaja, hev gjenge naken og berrføtt, og no i tri år hev vore eit teikn og eit varsel um Egyptarland og \'tiopia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'soleis skal kongen i Assyria lata fangarne frå Egyptarland, dei burtførde frå \'tiopia, både unge og gamle, fara av stad nakne og berrføtte og med berr bak, til skjemsla for Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Då skal dei verta forfælte og skjemmast yver \'tiopia, som var voni deira, og yver Egyptarland, som dei rosa seg av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Og dei som bur på denne strandi, skal segja på den dagen: «Soleis gjekk det med deim me studde oss til, med deim me flydde til i von um hjelp imot assyrarkongen. Korleis kann då me koma undan?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Framsegn um Hav-øydemarki. Som ein framfarande storm i Sudlandet kjem det frå øydemarki, frå det øgjelege landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Ei hard syn er meg kunngjord: «Ransmenner ranar, hermenner herjar. Drag upp, du Elam! Treng på, du Media! På kvar ein sukk vil eg gjera ende på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Difor skjelv mine lender, eg fær rider liksom ei kvinna som skal føda. Eg er fortumla so eg ikkje kann høyra, eg er forfælt so eg ikkje kann sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Hjarta mitt er forvildra, rædsla vil kjøva meg. Kveldstundi som eg trådde etter, fyller meg med gruv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Dei dukar bord, dei breider tæpet, dei et og drikk. «Statt upp, hovdingar, salva skjoldarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'For so sagde Herren til meg: Gakk og set ut vaktmannen; det han fær sjå, skal han melda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Og um han ser ei skreid, ridarar par um par, ei skreid av asen, ei skreid av kamelar, so skal han merka seg det, grant merka seg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Og han ropa som ei løva: «Her stend eg på vakt so lang dagen er, og vert verande på min post natt etter natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Og sjå, no kjem her ei skreid av menner, ridarar par um par!» Og han tok til ords og sagde: «Falle, falle hev Babel! Alle avgudsbilæti deira hev han krasa og kasta til jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Å, du mitt treskte folk, du offer for treskjarvollen! Det eg hev høyrt av Herren, allhers drott, Israels Gud, det hev eg meldt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Framsegn um Duma. Dei ropar til meg frå Se’ir: «Vaktmann, kva lid det med natti? Vaktmann, kva lid det med natti?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Vaktmannen svarar: «Morgonen kjem, men natti og. Vil de spyrja meir, so spør; kom att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Framsegn mot Arabia. I skogen i Arabia skal de natta, de ferdafylgje av dedanitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Kom dei tyrstande i møte med vatn, de folk frå Temalandet, kom dei rømande til hjelp med brød!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'For dei flyr undan sverd, drege sverd, og undan spend boge og undan den tunge ufreden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'For soleis hev Herren sagt til meg: Um eit år, so som leigekaren reknar året, skal det vera ute med all herlegdomen åt Kedar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Og lite skal det då vera att av bogarne åt kjemporne i Kedar. For Herren, Israels Gud, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Framsegn um Synedalen. Kva er på ferd, sidan alt folket ditt stig upp på taki?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Du bråkande, du ståkande by, du jublande borg! Dine falne menner er ikkje slegne med sverd, ikkje drepne i strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Hovdingarne dine tok alle saman til rømings, utan bogeskot let dei seg taka til fanga. Dei som fanst i deg, hev vorte fanga alle saman, langt burt hev det rømt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Difor segjer eg: Sjå burt ifrå meg, lat meg gråta sårt! truga ikkje trøyst på meg for at dotteri, folket mitt, hev vorte herja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'For ein upprivande dag med nedtrakking og forfjetring kjem frå Herren, Allhers-Herren, i Synedalen; murar vert nedbrotne, naudropet stig mot fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Elam tok pilehuset, han drog fram med vogn-stridsmenner og med hestfolk; Kir nækte skjoldarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Dei fagraste dalarne dine vart fyllt med stridsvogner, og hestfolk tok post framfor porten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Han tok vern frå Juda. Då såg du deg um etter herbunad - i skoghuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Og de såg at Davidsbyen hadde mange rivnor, og de samlar upp vatnet i Nedredammen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'de talde husi i Jerusalem, og de reiv ned husi og vilde gjera muren traust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Og imillom båe murarne gjorde de ein kulp for vatnet frå Gamledammen. Men på honom som hadde sett dette i verk, gav det ikkje gaum; til honom som longe sidan hadde laga dette til, såg de ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Herren, Allhers-Herren, kalla på den dagen til gråt og øying, til å raka hovudet og sveipa seg i syrgjeklæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Men her er gleda og gaman, ukseslagting og saueslagting, kjøteting og vindrikking. «Lat oss eta og drikka; for i morgon døyr me!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Difor ljomar openberringi frå Herren, allhers drott, i øyro mine: Den syndi fer de ikkje sona til dess de døyr, segjer Herren, Allhers-Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'So sagde Herren, Allhers-Herren: «Gakk til denne drottseten Sebna, han som stend fyre huset, og seg til honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Kva hev du her å gjera, og kven tenkjer du å leggja her, sidan du her høgg deg ut ei grav? Du som høgg gravi di ut på so høg ein stad og holar deg bustad i berget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'du skal vita at Herren skal slengja deg langt av leid, du mann! Han skal rulla deg saman til ein klump;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'han skal vinda deg saman til eit nysta og kasta deg som ein ball ut på vidvangen. Der skal du døy, og dit skal dei gilde vognerne dine koma, du skamflekk for huset åt herren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Eg vil støyta deg ned frå romet ditt, og frå posten din skal du verta avjaga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Og på den dagen vil eg kalla på tenaren min, Eljakim, son åt Hilkia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'og eg vil klæda honom i din bunad, og beltet ditt vil eg binda um honom, og ditt rådvelde vil eg gjeva i hans hender. Han skal vera ein far for deim som bur i Jerusalem og for Juda-huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Og eg vil leggja lykelen til Davids hus på herdi hans, og når han let upp, skal ingen læsa att, og når han læser att, skal ingen lata upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Eg set honom som ein spikar på ein fast stad, og han skal verta eit æresete for farshuset sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Men so framt heile tyngdi av farshuset hengjer seg på honom med alle sine ætlingar og frendar - alle småkjerald, frå fati til leirkrukkorne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'På den dagen, segjer Herren, allhers drott, skal spikaren i den faste veggen losna, han skal ganga av og detta ned, og byrdi som hekk på honom, skal krasast. For Herren hev tala.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Framsegn um Tyrus. Jamra dykk, de Tarsis-skip! For de er lagt i øyde, utan hus og utan heimkoma. Frå Kittims land fær dei fretnad um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Sit tagalle, de som bur på havstrandi! Kjøpmenner frå Sidon, sjøfarande menner, fyllte deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'av sædet i Sihor og kornet ved Nilen gjorde du deg vinning, med di du for yver store vatn og dreiv handel millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Men statt no der med skam, du Sidon; for so segjer havet, havborgi: «Eg hev ikkje vore barnsjuk og hev ikkje født born, ikkje ale unge menner eller fostra ungmøyar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Når dei fær høyra dette i Egyptarland, so bivrar dei ved fretnaden um Tyrus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Far yver til Tarsis og jamra dykk, de som bur på havstrandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Er dette dykkar glade by, som rekna upphavet sitt frå eldegamle dagar, og som av føterne sine vert boren til land langt burte til å vera gjest der?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kven hev tenkt ut dette mot Tyrus, mot henne som deilte ut kongekrunor - der som kjøpmennerne var fyrstar og kræmarane høyrde med til stormennerne på jordi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Herren, allhers drott, er den som hev tenkt det ut, han vilde vanhelga all skrøytande herlegdomen og vanæra alle desse stormennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Flød yver landet ditt, liksom Nilelvi, du dotter Tarsis! Du hev ingi demming meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Han rette ut handi si yver havet, han fekk kongeriki til å skjelva. Herren baud at borgerne i Kana’ans-landet skulde øydeleggjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Han sagde: «Du skal ikkje meir få gama deg, du valdtekne møy, dotter Sidon. Tak ut og far yver til Kittim, ikkje heller der skal du finna kvild.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Sjå landet åt kaldæarane, eit folk som ikkje var til, Assur gjorde grenderne deira til bustad for villdyri. Dei reiser no upp hertårni sine, dei riv ned slotti i byen og gjer honom til ein grushaug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Jamra dykk, de Tarsis-skip, for borgi dykkar er lagd i øyde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'På den dagen skal Tyrus gløymast i sytti år, ein kongealder; men når sytti år er lidne, skal det ganga med Tyrus som det heiter i visa um skjøkja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '«Tak din cither og gakk umkring i byen, du gløymde skjøkja! Spel fagert, og syng trottugt, so dei kann koma deg i hug!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Når dei sytti åri er lidne, skal Herren gjesta Tyrus, og ho skal atter få fara til å taka imot skjøkjeløn og driva utukt med alle kongeriki på den vide jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Men handelsvinsten hennar og skjøkjeløni skal verta helga åt Herren. Det skal ikkje leggjast upp eller gøymast, men dei som bur for Herrens åsyn, skal av denne vinsten hava rikeleg føda og prydelege klæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Sjå, Herren tømer jordi og øyder henne, han brigder hennar skapnad, og spreider deim som bur på henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Då gjeng det presten som folket, trælen som herren hans, trælkvinna som frua hennar, kjøparen som seljaren, utlånaren som lånaren, okraren som skuldmannen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Tømd, ja uttømd skal jordi verta og plundra, ja plundra. For Herren hev tala dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Jordi fauskast og folnar, jordheimen ormegtast og armast. Storingarne på jordi ormegtast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Og jordi er vanhelga under deira føter som bur der. For dei hev brote loverne, rengt retten, brote den ævelege pakti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Difor øyder forbanning jordi, og bøta lyt ibuarane. Difor vert jordbuarne brende burt, so få folk vert leivde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Druvesafti tek skade, vintreet visnar; sukka lyt alle hjarteglade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Det er slutt med den glade ljod av trummor og slutt med ståket av deim som jublar. Det er slutt med gleda ved klangen av cither.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Syngjande tømer dei ikkje vinstaupet meir; beisk er drykken for deim som drikk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Nedbroten er den aude byen; stengt er kvart hus, so ingen kann ganga inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Dei skrik på gatorne yver vinen, all gleda er burte, landlyst er gaman or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Berre øyding er leivd i byen, og porten ligg krasa i røys.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'For soleis skal det ganga til midt millom folki på jord, liksom når oljeber vert nedslegne, som ved etterhaustingi, når det er slutt med vinbergingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Dei, dei skal lyfte røysti si og ropa med fagnad; yver Herrens herlegdom skal dei frå havet fegnast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, '«\'ra difor Herren, de i Austerland, namnet åt Herren, Israels Gud, de på havsens øyar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Frå ytste jaren åt jordi høyrer me lovsong: «\'ra vere den rettferdige!» Men eg segjer: Eg gjeng til, eg gjeng til, usæl eg! Ransmenner ranar, ja ransmenner gjer ran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Gruv og grav og gildra yver deg, du som bur på jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Og det skal henda at den som flyr for det gruvelege bråket, skal falla i gravi, og den som kjem upp or gravi, skal verte fanga i gildra. For himmelslusorne er opna, og grunnvollarne åt jordi skjelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Jordi brest og knest, jordi rivnar og klovnar, jordi skjek og skjelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Skjangla skal jordi som drukken mann, svaga som eit gjætarskjol, misgjerdi hennar skal tyngja henne ned, og ho skal falla og ikkje reisa seg meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Og det skal henda på den dagen at Herren skal heimsøkja høgheimsheren i høgdom og jordkongarne nedpå jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'og dei skal sankast som fangar i hola og setjast fast i fangehuset, og etter mange dagar skal dei få si straff.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Og månen skal blygjast og soli skjemmast. For Herren, allhers drott, råder på Sionsfjellet og i Jerusalem, og framfor augo på hans styresmenner er det herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Herre, du er min Gud; eg vill upphøgja deg, eg vil prisa namnet ditt. For du hev gjort underverk. Dine råd frå forntidi er sanne og trufaste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'For du hev gjort ein by til ei steinrøys, ein fast by til ein grusdunge, framande slott, so dei ikkje meir er ein by. Aldri meir skal dei verta uppbygde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Difor skal eit vilt folk æra deg, den illharde heidningbyen ottast deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'For du hev vore ei vern for vesalmannen, ei vern for fatigmannen i naud, eit skjol mot skolregn, ein skugge for hiten. For valdsmenns frøsing er som skolregn mot veggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Og som hiten i ovturken, soleis døyver du bråket åt dei framande; ja, liksom hiten i skuggen av ei sky, soleis døyver du songen av valdsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Og Herren, allhers drott, skal på dette fjellet bu til eit gjestebod for alle folk, eit gjestebod med feite retter, eit gjestebod med gamall vin, med feite mergfulle retter, med gamall avklåra vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Og han skal på dette fjellet riva sund sløret som sveiper seg ikring alle folki, og det sveipet som ligg yver heidningfolki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Han skal gjera dauden til inkjes for all æva, og Herren, Herren skal turka tårorne av alle andlit, og sitt folks vanæra skal han taka burt frå all jordi. For Herren hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Og den dagen skal dei segja: «Sjå der er vår Gud! Me vona på honom, at han skulde frelsa, dette er Herren som me vona på. Lat oss frygda oss og fegnast i frelsa hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'For handi åt Herren skal kvila yver dette fjellet. Moab skal verta nedtrakka der han er, liksom halm vert trakka ned i mykjavatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Og han skal breida ut henderne i det liksom ein symjar breider deim ut og vil symja. Men han skal stagga storlætet hans til tråss for sløgdi av hans hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Og dei høgmura borgerne dine skal han riva ned, grunnsturta, jamna med jordi so dei ligg i dusti.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'På den dagen skal dei syngja denne songen i Judalandet: «Ein sterk by hev me. Frelsa set han til mur og vern.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Lat upp portarne, so der må få ganga inn eit rettferdigt folk, som varar truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Åt den som er hugfast, varar du stendig fred; for på deg lit han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Lit då på Herren allstødt! For Herren, Herren er eit æveleg berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'For han gjer deim ringe som hev fest bu i høgddom, støyter ned den grunnfeste byen, sturtar han til jordi, heilt ned i moldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Føter trakka honom ned, føter av vesalmenn, fet av armingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Men vegen åt den rettferdige er jamn. Veg åt den rettferdige jamnar du.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'På dine domars veg ventar me deg, Herre. Namnet ditt og minnet ditt dreg vår sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Mi sjæl kjenner seg dregi til deg um natti; og åndi i meg leitar etter deg. For straks domarane dine råkar jordi, lærer jordbuarne rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Fær den gudlause nåde, so lærer han ikkje rettferd. Då gjer han urett i det rettvisaste landet, og Herrens høgd ser han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Herre, høgt er handi di lyft, men dei ser det ikkje. Lat deim sjå brennhugen din for folket og skjemmast. Ja, eld øydde uvenerne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Herre, du skal hjelpa oss til fred. For alle verki våre hev du verka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Herre, vår Gud! Andre herrar enn du hev rådt yver oss. Einast ved deg prisar me namnet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Daude livnar ikkje, skuggar stend ikkje upp. Difor heimsøkjer og øydelegg du deim og gjer til inkjes minnet um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Du auka folket, Herre! Du auka folket, og synte deg herleg. Du hev flytt alle grensesteinarne åt landet langt ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Herre, i naudi leita dei etter deg. Dei sende upp stille bøner, då refsingi kom yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Liksom ei kvinna som er med barn, vrid seg og skrik i riderne når ho skal føda, soleis gjekk det oss for din vreide skuld, Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Me var med barn, me hadde rider; då me fødde, var det vind. Berging har me ikkje til landet, og jordbuar vart ikkje fødde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Dine daude skal verta livande, mine lik skal standa upp. Vakna og fegnast, de som bur i moldi. For ei ljossens dogg er di dogg; og jordi føder daudingar av seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Gakk då, mitt folk, inn i kovarne dine, og lat att dørerne etter deg! Gøym deg ein augneblink, til dess vreiden gjeng yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'For sjå, Herren gjeng ut frå bustaden sin og vil heimsøkja jordbuarne for deira misgjerder skuld, og jordi skal syna fram sitt utrende blod og ikkje meir dylja sine drepne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'På den dagen skal Herren med sverdet sitt, det harde og store og sterke, heimsøkja Livjatan, den flogsnare ormen, og Livjatan, den krøkjande ormen, og han skal drepa sjøormen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'På den dagen skal de finnast ein yndeleg vingard, syng um honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '«Eg, Herren, er vaktaren hans. Kvar augneblink vatnar eg honom, at ikkje nokon skal heimsøkja honom, vaktar eg honom dag og natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Vreide hev eg ikkje; men vilde tornar og tistlar reisa seg til krig, skulde eg gå laus på deim, brenna deim heilt upp -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'utan so dei vilde fly til mi vern, gjera fred med meg, ja gjera fred med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'I komande dagar skal Jakob røta seg, Israel bløma og få renningar og fylla jordheimen med si frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Hev han slege honom liksom han slo plågaren hans? Eller vart han myrd liksom mordarane hans vart det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Med måte refste du henne, med du sende henne burt. Han dreiv henne burt med sitt harde ver, den dagen austanvinden bles.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Difor vert og misgjerdi åt Jakob utsona, og det at syndi vert burtteki, fær gjeva fullmogi frukt, når alle altarsteinarne vert krasa som kalksteinar, og Astarte-bilæti og solstolparne ikkje reiser seg meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'For den faste byen ligg i øyde, ein folketom bustad, aud som øydemarki. Kalvar beiter der og hev der si lega og et av kvisterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Når greinerne hev vorte turre, bryt dei deim av, kvinnfolki nører upp eld med deim. For dette er ikkje noko vitugt folk. Difor miskunnar deira skapar deim ikkje, og han som laga deim, er deim ikkje nådig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Og det skal henda på den dagen, at Herren skal halda ei frukthausting alt frå Storelvi til Egyptarlands-bekken, og de, Israels born, skal verte sanka, ein for ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Og det skal henda på den dagen at dei skal blåsa i ein stor lur, og då skal dei koma dei burtkomne i Assurs land og dei burtdrivne i Egyptarlandet, og dei skal tilbeda Herren på det heilage fjellet i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Usæl den stolte kruna åt dei drukne i Efraim og den folnande blomen, den fagre prydnad som brikjer yver den feite dalen, der dei ligg dauddrukne av vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Sjå, ein sterk og veldug sender Herren, lik ein hagleling, ein øydande storm, lik eit fløde av velduge, yverfløymande vatn, som slær alt til jordi med magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Med føter skal ho verta nedtrakka, den stolte kruna åt dei drukne i Efraim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Og den folnande blomen, den fagre prydnaden, som brikjer yver den feite dalen, skal verta som den tidlege fika, fyrr sumaren er komen - so snart ein ser henne, so set ein henne til livs medan ein endå held henne i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'På den dagen vert Herren, allhers drott, ei fager krune og ein storgild krans for leivningen av sitt folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'og ei doms ande for deim som sit til doms, og styrke for deim som driv krigen attende til porten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Men ogso desse ragar av vin og skjanglar av sterk drykk. Prest og profet ragar av sterk drykk, er dauddrukne av vin, skjanglar av sterk drykk. Dei ragar i syni, dei skjanglar i domen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'for alle bordi er fulle av ufyselegt spy, det finst ikkje ein rein flekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, '«Kven er det han vil læra, og kven er det han vil få til å høyra på seg? Er det born som nett er avvande, tekne frå brjostet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'For gnag og gnag, gnag og gnag, gnål og gnål, gnål og gnål, noko her og noko der fer han med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Ja vel, med stamande lippor og i eit framandt tungemål skal han tala til dette folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'han som sagde til deim: «Dette er ro, lat den trøytte få kvila, og dette er kvila.» Men dei vilde’kje høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'So skal då Herrens ord verta deim gnag og gnag, gnag og gnag, gnål og gnål, gnål og gnål, noko her, noko der, so dei skal ganga og detta baklenges og verta sundbrotne og bundne og fanga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Difor, høyr Herrens ord, de spottarar, de herrar yver dette folket som er i Jerusalem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'For de segjer: «Me hev gjort ein avtale med dauden og eit samband med helheimen; når den susande svipa fer fram, skal ho ikkje nå oss; for me hev gjort lygni til livd og svikråd til skjol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Difor, so segjer Herren, Herren: Sjå, eg er den som hev grunna i Sion ein stein, ein prøvd stein, ein dyrverdig fast grunna hyrnestein; den som trur, tek det med ro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Eg gjer rett til mælesnor og rettferd til lodd, og hagl skal riva burt lygnlivdi, og skylet skal vatnet skylja burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Og dykkar avtale med dauden skal verta stroken, og dykkar samband med helheimen skal ikkje standa fast. Når den susande svipa fer fram, skal de verta nedslegne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Kvar gong ho fer fram, skal ho riva dykk burt. For kvar morgon skal ho fara fram, um dagen og um natti, og den reine skræma vert det når de lyt agta på bodskapen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'For sengi er for stutt til å strekkja seg i, og åklædet er for smalt til å sveipa seg i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'For Herren skal reisa seg liksom ved fjellet Perasim, han skal harmast liksom i dalen ved Gibeon; han skal gjera sitt verk, eit underlegt verk, han skal gjera sitt arbeid, eit sjeldsynt arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Og no, lat vera med å spotta, so bandi dykkar ikkje må verta stramare! For um øyding og fastsett straffedom hev eg høyrt frå Herren, Allhers-Herren, yver heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Vend øyra til og høyr mi røyst, gjev gaum og høyr kva eg segjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Når plogmannen vil så, held han då stødt på med å pløgja og fora og horva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Når han hev jamna åkeren, spreier han ikkje då svartkarve og sår kryddekarve og set kveite i rader og bygg på avmerkte stader og spelt i kantarne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Hans Gud hev synt honom den rette måten, han lærde honom det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'For ein treskjer ikkje svartkarve med treskjeslede, rullar ikkje vognhjul yver kryddekarve; men med stav bankar ein svartkarve, og kryddekarve med kjepp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Vert brødkorn krasa? Nei, ein treskjer det ikkje stødt, og når ein driv sine vogn og hestar yver det, so knusar ein det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Ogso dette kjem frå Herren, allhers drott. Han er underfull i råd, stor i visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Usæl, Ariel, Ariel, du by der David slo læger! Legg år til år, lat høgtiderne ganga sin rundgang!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Då vil eg gjera det trongt for Ariel, og der skal vera sorg og jammer. Men då skal det verta meg eit verkelegt Ariel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Eg vil slå læger rundt ikring deg, og eg vil ringa deg inne med vaktpostar og kasta upp vollar imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Då skal du tala lågmælt frå jordi, og frå moldi skal du mulla fram ordi dine, og røysti di skal høyrast frå jordi liksom frå ein som manar draugar, og frå moldi skal talen din kviskra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Men so skal mengdi av fiendarne dine verta som dumba, og mengdi av valdsmennerne som fjukande agner, og det skal henda i ein augneblink, dåtteleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Frå Herren, allhers drott, skal heimsøkjing koma med bulder og bråk og med veldug dyn, vindkast og storm og øydande eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Og mengdi av alle dei heidningfolki som strider mot Ariel, skal verta som ein draum, ei syn um natti, alle dei som strider mot det og borgi i det, og som trengjer seg inn på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Og det skal ganga liksom når den svoltne drøymer og tykkjer han et, men når han vaknar, då er han tom, og liksom når den tyrste drøymer og tykkjer at han drikk, men når han vaknar, sjå, då er han magtlaus, og sjæli hans ormegtast; soleis skal det ganga alle dei mange heidningfolki som strider mot Sionsfjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Stir på kvarandre og vert øre! Gjer dykk blinde og vert blinde! De er drukne, men ikkje av vin; de ragar, men ikkje av sterk drykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'For Herren hev rent ut yver dykk ein djup svevns ande, og han hev late att dykkar augo, profetarne, og sveipt yver dykkar hovud, sjåarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Og soleis hev syni av alt i hop vorte dykk som ordi i ei forsigla bok; rettar ein henne til ein som er lesekunnig og segjer: «Les dette!» so segjer han: «Eg kann ikkje, for ho er forsigla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Eller ein retter boki til ein som ikkje skynar skrift og segjer: «Les dette!» so segjer han: «Eg skynar ikkje skrift.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Og Herren segjer: Etter di dette folket held seg nær til meg med munnen og ærar meg med lipporne sine, men held hjarta sitt langt burte frå meg, og deira otte for meg er eit menneskjebod som dei hev lært,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'sjå, difor vil eg halda ved med å fara underleg åt med dette folket, underleg og ovunderleg, og visdomen åt deira vise skal forgangast, og vitet åt deira vituge menner skal løyna seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Usæle dei som vil løyna i dypti for Herren det som dei hev fyre seg, og som gjer i myrkret gjerningarne sine, og som segjer: «Kven ser oss, og kven kjenner oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Å, kor bakvendt! Er pottemakaren å rekna lik med leiret hans, so det han hev gjort, kunde segja um honom som gjorde det: «Han hev ikkje gjort meg,» og det som er laga, segja um honom som laga det: «Han hev ikkje vit på det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Er det ikkje endå ei liti stund, so skal Libanon verta til ein frukthage og frukthagen verta rekna som skog?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Og på den dagen skal dei daude høyra ordi i boki, og ut frå dimma og myrker skal augo åt dei blinde sjå,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Og dei spaklyndte skal gleda seg dess meir i Herren, og dei fatigaste millom menneskjom fegnast i Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'For burte er valdsmannen, og ute er det med spottaren, og utrudde er alle som er årvake til å gjera urett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'dei som gjer folk til syndarar for eit ord skuld, og legg snaror for den som skipar rett på tinget, og som med uppdikt rengjer retten for den rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Difor, so segjer Herren so til Jakobs hus, han som løyste ut Abraham: No skal Jakob ikkje verta til skammar, og no skal han sleppa verta bleik i andlitet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'For når han og borni hans ser det mine hender hev gjort midt ibland deim, då skal dei helga namnet mitt, og dei skal helga Jakobs Heilage, og Israels Gud skal dei ottast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Og dei som for vilt i si ånd, skal læra vit, og dei som knurrar, skal taka mot lærdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Usæle dei tråssuge born, segjer Herren, som fullfører råd som ikkje er frå meg, og gjer samband utan min ande, so dei legg synd til synd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'som fer av stad til Egyptarland, og hev ikkje spurt etter mitt ord - dei vil verna seg med Faraos vern og finna livd i skuggen av Egyptarland!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Men Faraos vern skal verta dykk til skam, og livdi i skuggen av Egyptarland til skjemd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'For fyrstarne deira er komne til Soan, og sendebodi hans når til Hanes;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'alle vert dei til skammar ved eit folk som ikkje gagnar deim, ikkje er til hjelp og til bate, men både til skam og skjemd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Framsegn um udyret i Sudlandet. Gjenom eit land med naud og trengsla, der løvemor og løva, hoggorm og fljugande eiterorm hev heimen sin, fører dei eigedomen sin på asenrygg og på kamelrugg skattarne sine til eit folk som ikkje gagnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Slett ikkje og aldri vil Egyptarland hjelpa; difor kallar eg det: «Storskrytaren som sit still».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Gakk no inn, skriv det på ei tavla medan dei ser på, og teikna det inn i ei bok, so det kann vera for komande dagar, for alltid, til æveleg tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'For det er eit tråssugt folk, ljugarborn, born som ikkje vil høyra Herrens lov,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'som segjer til sjåarane: «De skal ikkje sjå,» og til deim som skodar: «De skal ikkje skoda for oss det som rett er. Tala smeikjande til oss, skoda synkvervingar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'vik burt frå vegen, bøyg av frå råsi, få Israels Heilage burt frå augo våre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Difor, so segjer Israels Heilage: «Etter di de vandar dette ordet, og lit på vald og krokvegar og styd dykk på det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'difor skal denne misgjerdi verta dykk som ein falleferdig mole, som hev rivna ut or ein høg mur, og som brått kann verta nedbroten i ein augneblink.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Han vert krasa, liksom ein krasar krusty, som ein utan skonsel slær sund, so det millom molarne ikkje finst eit brot til å henta eld med frå gruva eller ausa vatn med av brunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'For so segjer Herren, Herren, Israels Heilage: Dersom de vender um og held dykk stille, skal de verta frelste, i stilla og i tillit skal dykkar styrke vera. Men de vilde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'De sagde: Nei, men på hestar vil me fljuga» - difor skal de fly - «og på snøggføtte vil me rida» - difor skal forfylgjararne dykkar verta snøgge -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Eit tusund skal røma for trugsmål frå ein; og for trugsmål frå fem skal de røma, til dess dykkar leivning er lik ei flaggstong på toppen av eit fjell og eit merke på ein haug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Og difor biar Herren med å vera dykk nådig, og difor held han seg langt burte i det høge med si miskunn mot dykk; for Herren er doms Gud, sæle er alle dei som biar på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'For du folk som bur på Sion, i Jerusalem, du må ikkje gråta meir; han vil vera deg nådig når du ropar um hjelp; når han høyrer det, svarar han deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Herren skal gjeva dykk trengsels-brød og fengsels-vatn, og då skal lærarane dine ikkje meir løyna seg, men augo dine skal sjå lærarane dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'og øyro dine skal høyra eit bak deg, soleis: «Dette er vegen, gakk på den!» - når det vik av til høgre, og når de vik av til vinstre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Og du skal halda for ureint sylvplatorne på dine utskorne bilæte og gyllingi på ditt støypte bilæte, du skal kasta deim burt som skarn. «Ut med deg!» skal du segja til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Då skal han gjeva regn for ditt sæde, som du sår i jordi, og brød av grøda på jordi, og det skal vera både kraftigt og saftigt; den dagen skal bufeet ditt beita på ei vid eng.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Og uksarne og asni, som arbeider jordi, skal eta salta blandingsfôr, som vert kasta med skufl og kastegreip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Og på kvart høgt fjell og på kvar høg bakke skal det vera bekkjer, straumar av vatn, på den store slagtedagen, når tårn fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Og måneljoset skal verta som solljoset, og solljoset skal verta sjufaldt, som ljoset for sju dagar, den dagen då Herren bind um bråtet som folket hans hev fenge, og lækjer såret av slaget det fekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Sjå, Herrens namn kjem langt burtanfrå, brennande er vreiden hans, og svær er røyken som stig upp; lipporne hans svell av harm, og tunga hans er som øydande eld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'og vreidepusten hans er som ei yverfløymande bekk, som når til halsen; han vil sælda heidningfolki i tyningssåldet og leggja eit vildringsbeisl i munnen åt folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Dykkar song skal ljoda som i den natti då høgtidi vert innvigd, og det skal vera hjartans gleda, som når dei gjeng med fløytespel upp til Herrens fjell, til Israels berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Og Herren skal lata si velduge røyst ljoda og syna sin nedfarande arm i vreid harm og øydande eldsloge, støytregn og sturtregn og hagl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'For røysti åt Herren skal Assur verta forfærd, han som slær honom med staven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Og kvar gong straffestaven som Herren let falla på honom, fer ned, skal det ganga fyre seg med klang av trummor og cithrar, og i stridar mot det med svingande arm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'For ei brandtuft er tilbudd longe; ogso for kongen er ho tilbudd, djup og vid; bålet hennar hev eld og ved i mengd; anden åt Herren, lik ein svåvelstraum, set det i brand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Usæle dei som fer ned til Egyptarland etter hjelp og stolar på hestar og lit på vogner, for di dei er so mange, og på hestfolk, for di dei er so mannsterke, men ikkje skodar etter Israels Heilage og ikkje søkjer Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Men han og er vis og let ulukka koma, og ordi sine tek han ikkje i seg att, men han reiser seg mot huset åt dei vonde og mot deim som er hjelp for illgjerdsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Og egyptarane er menneskje og ikkje Gud, og deira hestar er kjøt og ikkje ånd, og Herren skal retta ut handi si, og hjelparen skal snåva, og den som hev fenge hjelp, falla, og dei skal alle saman ganga til grunns.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'For so sagde Herren til meg: Liksom ei løva og ei ungløva burar yver rovet sitt, når ein flokk hyrdingar sankar seg imot henne, og ho skræmest ikkje av skriket deira og vert ikkje rædd for ståket, soleis skal Herren, allhers drott, fara ned og strida mot Sions fjell og mot høgdi der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Liksom flaksande fuglar, soleis skal Herren, allhers drott, verja Jerusalem, verja og frelsa, ganga framum og berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Vend um til honom som de er so djupt falne frå, de Israels-born!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'For på den dagen skal dei kasta frå seg kvar sine sylvgudar og gullgudar, som dykkar hender hev gjort dykk til synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Og Assur skal falla for eit sverd som ikkje høyrer ein mann til, og eit sverd som ikkje høyrer eit menneskje til, skal øyda honom, og han skal røma for sverdet, og hans unge menner skal verta trælar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Og berget hans skal røma for rædsla, og fyrstarne hans skal skræmast burt ifrå fana si, segjer Herren, som hev elden sin i Sion og omnen sin i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Sjå, med rettferd skal kongen råda, og hovdingarne skal styra etter rett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'og kvar ein av deim skal vera som eit skyle for veret og ei livd mot sturtregn, som vatsbekkjer på ein turr stad, som skuggen av eit veldugt berg i eit uppturka land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Då skal augo åt deim som ser ikkje vera blinde, og øyro åt deim som høyrer, skal vera grannhøyrde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'hjarto åt dei tankelause skal evla skyna, og tunga åt dei stame skal hava lett for å tala klårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Dåren skal ein ikkje meir kalla gjæv, og den innfule skal ein ikkje kalla hugstor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'For dåren talar dårskap, og hjarta hans finn på vondt; han gjer vanheilag gjerd, og talar forvende ting um Herren, han let den hungrige svelta og let den tyrste vanta drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Og våpni åt den innfule er vonde; han tenkjer ut meinråder, til å føra dei spaklyndte i ulukka med falske ord, og det når den fatige talar det som rett er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Men gjævingen hev gjæve tankar, og han stend fast ved det som gjævt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'De sorglause kvinnor, statt upp og høyr det eg segjer! De trygge døtter, vend øyra dykkar til min tale!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Um år og dag skal de skjelva, de trygge! For det er ute med vinhausten, frukhausten kjem ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Vert forfærde, de sorglause; skjelv, de trygge! Klæd dykk og næk dykk, og umgyrd dykkar lender!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Dei slær seg for bringa yver dei fagre marker, yver det fruktrike vintreet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'yver jordi åt mitt folk, der tornar og tistlar skyt upp, ja, yver alle gledehus, den morogalne byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'For borgi er tom, mugen i byen er burte. Haug og vakttårn hev vorte til holor for ævelege tider, til frygd for villasen, til beite for bølingar -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'til dess åndi vert utrend yver oss frå det høge, og øydemarki vert til ein frukthage, og frukthagen vert rekna som skog.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Og rett skal bu i øydemarki, og rettferd skal hava sin heim i frukthagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Og rettferds verk skal vera fred, og rettferds frukt ro og tryggleik til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Og folket mitt skal bu i freds bustad og i tryggleiks tjeld og på sorgfrie kvilestader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Men det skal hagla når skogen fell, og djupt skal byen søkka ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Sæle er de som sår attved alle vatn, som let uksen og asnet vera på frifot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Usæl du tynar som ikkje sjølv hev vorte tynt, og du ransmann som ingen hev rana ifrå! Når du er ferdig med å tyna, skal du sjølv verta tynt; når du hev slutta med å rana, skal andre rana frå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Herre, ver oss nådig! Etter deg biar me; ver armen vår kvar morgon, ja vår frelsa i nauds tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'For torerøysti rømer folki; når du reiser deg, vert heidningarne spreidde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Fengdi dykkar vert sanka, liksom skavaren sankar; liksom engsprettorne spring, spring dei etter det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Upphøgd er Herren, for han bur i det høge; han fyller Sion med rett og rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Trygge tider skal koma for deg, ein fullnad av frelsa, av visdom og kunnskap; otte for Herren skal vera skatten åt det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Høyr kjemporne deira skrik der ute, fredsbodi græt sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Ålmannvegarne er aude, ferdafolk er der’kje meir - han hev brote pakti, vanvyrdt byarne, ikkje vyrdt noko menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Landet folnar, visnar; Libanon stend skjemd, folnar burt; Saron er som den aude mark; og Basan og Karmel rister lauvet av seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'No vil eg standa upp, segjer Herren, no vil eg reisa meg, no vil eg gjera meg høg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'De skal ganga umhender med strå og føda halm; dykkar frøsing er ein eld som skal øyda dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Og folkeslag skal verta brende til kalk - avskoren klunger som vert uppbrend med eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Høyr, de som er langt undan, kva eg hev gjort, og de som er nær, kjenn min styrke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Syndarar skjelv på Sion, skjelte hev teke dei vanheilage: «Kven kann bu ved ein øydande eld? Kven kann bu ved ævelege bål?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Den som ferdast i rettferd og talar det som rett er, som ikkje vyrder urettferdig vinning, som held sine hender frå å taka mutor, stappar øyro att og vil ikkje høyra blodråd, og som let augo att og vil ikkje sjå på vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'han skal bu på høge stader, fjellborger er hans vern; brødet vert gjeve honom, vatnet tryt ikkje for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Augo dine skal skoda kongen i hans fagerdom, dei skal sjå eit vidsveimt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Hjarta ditt skal minnast rædsla: «Kvar er han som skreiv upp? Kvar er han som vog pengarne? Kvar er han som talde tårni?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Det ville folket skal du ikkje meir sjå, folket med det vande målet som ein ikkje kann skyna, med den stamande tunga som ein ikkje kann tyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Sjå på Sion, byen for våre høgtidsstemnor! Augo dine skal i Jerusalem sjå ein trygg bustad, eit fjell som ikkje vert flutt; pålarne vert æveleg ikkje upprykte, og ikkje ei av snorerne vert sundslitne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Men der skal me hava ein veldug, Herren - i staden for breide åer og elvar; ingi rorskuta skal fara der, og ikkje noko veldugt langskip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'For Herren er domaren vår, Herren er vår lovgjerar, Herren er kongen vår, han skal frelsa oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Slakke heng togi dine, dei evlar ikkje stydja mastri, dei held ikkje seglet utspent - då vert herfang bytt i mengd, jamvel dei lame ranar ran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Og ingen ibuar skal segja: «Eg er sjuk.» Folket som bur der, hev fenge si misgjerd forlati.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Kom hit, de folk, og høyr, og de folkeslag, gjev gaum! Jordi høyre og det som fyller henne, jordheimen og alt som veks der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'For Herrens vreide er yver alle folki, og harmen hans yver all deira her. Han bannstøyter deim, gjev deim til slagting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Og deira ihelslegne skal verta burtslengde, og teven av liki deira skal stiga upp, og fjelli skal fljota av blodet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Og heile himmelheren skal kverva, og himlarne verta ihoprulla som ei boki, og all heren deira skal visna burt, som bladet fell av vintreet og det visne lauvet av fiketreet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'For sverdet mitt hev vorte drukke i himmelen. Sjå, yver Edom skal det fara ned og yver mitt bannstøytte folk til dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Sverdet åt Herren er fullt av blod, gjødt med feitt, med blod av lamb og bukkar og med nyrefeitt av verar. For ei offerslagting held Herren i Bosra og ei stor nedslagting i Edomlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Og villuksar skal sturta saman med deim, og stutar saman med sterke uksar, og landet deira skal verta drukke av blod, og jordi deira hævda med feitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'For Herren held ein hemnardag og eit attergjeldsår for Sions sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Og bekkjerne i det skal verta til bik, og moldi til svåvel, og markerne i det skal verta til brennande bik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Korkje natt eller dag skal det slokna, i all æva skal røyken frå det stiga upp; frå ætt til ætt skal det liggja i øyde, i all æva er det ingen som fer igjenom det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Og pelikan og bustyvel skal eiga det, og kattula og ramn skal bu i det, og ein skal spana ut yver det mælesnøre til øyding, og bruka lodd til å gjera det tomt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Det er ingi gjævingar der som kann ropa nokon ut til konge, det er slutt med alle hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Og klunger skal renna i slotti der, og netla og tistlar i borgerne, og det skal vera ein bustad for sjakalar og ein stad for strussar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Og ulven og andre villdyr skal møtast, og raggetroll ropa til kvarandre; ja, der uner Lilit og finn seg ein kvilestad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Der byggjer pilormen reir og legg egg og klekkjer ut ungar og sankar deim og gjev deim livd. Ja, der sankar gribbarne seg, den eine hjå den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Leita etter i Herrens bok og les! Ikkje eitt av deim vantar, det eine saknar ikkje det andre. For hans munn byd det, og hans ånd sankar deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'og han kastar lut for deim, og handi hans ætlar deim det med mælesnøre. Til æveleg tid skal dei eiga det, frå ætt til ætt skal dei bu i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Øydemarki og turrlendet skal gleda seg, og den aude heidi skal fegnast og bløma som ei lilja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Ho skal bløma og fegnast, og fegnast og syngja med frygd. Herlegdomen åt Libanon hev ho fenge, Karmels og Sarons pryda; dei skal sjå Herrens herlegdom, vår Guds pryda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Styrk dei valne hender og gjer dei skjelvande kne sterke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Seg til dei urolege hjarto: «Ver frihuga, ottast ikkje! Sjå, der er dykkar Gud! Hemnen kjem, vederlag frå Gud, han kjem sjølv og frelser dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Då skal augo åt dei blinde verta opna, og øyro åt dei dauve verta upplatne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'då skal den lame springa som ein hjort, og tunga åt den mållause jubla. For vatn bryt fram i øydemark, og bekkjer på den aude heidi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'og det gloande sandhavet skal verta til ein sjø, og det tyrste landet til vatskjeldor; i bustaden åt sjakalar, der dei hadde sin kvilestad, er voksterstad for røyr og sev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Og der skal det vera braut og veg, og han skal kallast den heilage vegen. Ingen urein skal ganga på honom, men han skal vera berre for deim; ingen vegfarande, ikkje dåren eingong, skal fara vilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Der skal det ingi løva vera, og inkje villdyr skal koma inn på honom, dei skal ikkje finnast der; men utløyste skal ferdast der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Og Herrens frikjøpte skal snu heim att og koma til Sion med fagnadrop, og æveleg gleda er det yver hovudet deira; frygd og gleda skal dei nå, og sorg og sukk skal røma.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Og det hende seg i det fjortande styringsåret åt kong Hizkia, at assyrarkongen Sanherib drog upp imot alle faste borgar i Juda og hertok deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Og assyrarkongen sende Rabsake frå Lakis til Jerusalem mot kong Hizkia med ein stor her; og han stogga attmed vatsleidingi frå Øvredammen på allfarvegen til vaskarvollen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Då gjekk drottseten Eljakim Hilkiason og riksskrivaren Sebna og kanslaren Joah Asafsson ut til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Og Rabsake sagde til deim: «Meld til Hizkia: «So segjer storkongen, assyrarkongen: «Kva er det for tru som gjer deg so traust?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Du tenkjer at berre eit ord gjer råd og dåd i krig! Kven lit du på, sidan du sette upp imot meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Ja, det er sant, du lit på Egyptarland, den brotne røyrstaven som sting hol i handi på kvar som styd seg til honom! Soleis er Farao, egyptarkongen, for alle deim som lit på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Og svarar du meg: «Me lit på Herren, vår Gud!» var det då ikkje hans offerhaugar og hans altar Hizkia fekk burt då han baud Juda og Jerusalem: «Framfor dette altaret skal de bøygja kne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Gjer då eit veddemål med Herren min, assyrarkongen: Eg gjev deg tvo tusund hestar um du kann skaffa folk til å rida på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Korleis vil du slå attende ein einaste jarl, ein av dei ringaste tenarane åt herren min? Og so lit du på egyptarane, på vognerne og ridarane deira!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Trur du det er Herren uvitande når eg kjem hit og øydelegg dette landet? Nei, det var Herren som baud meg: «Drag upp til dette landet og legg det i øyde!»»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Då sagde Eljakim og Sebna og Joah til Rabsake: «Tala syrisk til tenarane dine! me skynar det nok; tala ikkje jødisk til oss! folket på muren høyrer på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, '«Nei,» svara Rabsake, «det er til herren din og til deg herren min hev sendt meg å tala desse ordi, men nettupp til det folket som sit på muren og saman med dykk lyt eta sitt eige skarn og drikka sitt eige vatn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'So steig Rabsake fram og ropa høgmælt desse ordi på jødisk mål: «Høyr det storkongen, assyrarkongen, talar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'So segjer kongen: «Lat ikkje Hizkia narra dykk; han er ikkje i stand til å berga dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Lat ikkje Hizkia få dykk til å lita på Herren, med di han segjer: «Herren hjelper oss for visst, han gjev ikkje denne byen i henderne på assyrarkongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Høyr ikkje på Hizkia! So segjer kongen i Assyria: Gjer fred med meg! gjev dykk yver til meg! So skal de få eta kvar av sitt eige vintre og sitt eige fiketre og drikka vatn kvar or sin eigen brunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'til dess eg kjem og hentar dykk til eit land som er likt dykkar eige, eit land med korn og druvesaft, eit land med brød og vinhagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Lat ikkje Hizkia narra dykk og segja: «Herren bergar oss!» Tru nokon av folkegudarne hev berga sitt land for assyrarkongen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kvar er gudarne i Hamat og Arpad? Kvar er gudarne i Sefarvajim? Eller hev dei berga Samaria ut or mi hand?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kven av alle gudarne i desse landi hev berga sitt land ut or mi hand, so Herren skulde berga Jerusalem ut or mi hand?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Og dei tagde og svara honom ikkje eit ord; for so var kongens bod: «Ikkje svara honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Eljakim Hilkiason, drottseten, og Sebna, riksskrivaren, og Joah Asafsson, kanslaren, kom då attende til Hizkia med sundrivne klæde og melde honom ordi hans Rabsake.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Då kong Hizkia høyrde det, reiv han sund klædi sine, og sveipte syrgjebunad kring seg og gjekk inn i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'So sende han drottseten Eljakim og riksskrivaren Sebna og dei eldste av prestarne syrgjeklædde til profeten Jesaja Amosson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Og dei sagde til han: «So segjer Hizkia: «Dette er ein dag full av naud og straff og skjemsla; fosteri hev nått fødsli, men det finst ikkje kraft til å føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Kann henda høyrer Herren, din Gud, det Rabsake hev sagt, han som er send av assyrarkongen, herren sin, til å svivyrda den livande Gud, so han straffar honom for dei ordi som Herren, din Gud, hev høyrt. Ber då fram ei bøn for den leivning som endå er att.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Då hirdmennerne frå kong Hizkia kom til Jesaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'sagde Jesaja til deim: «So skal de svara herren dykkar: «So segjer Herren: Ver ikkje rædd for dei ordi du høyrde, då trælarne åt assyrarkongen spotta meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Eit hugskot skyt eg i hugen hans; han høyrer ei tiend, og heim att snur han; der let eg honom falla for sverd i sitt land.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Då Rabsake for burt att, fann han assyrarkongen i strid mot Libna; for han hadde høyrt at han hadde fare burt frå Lakis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Då han so fekk tiend at ætiopkongen Tirhaka hadde drege ut i herferd mot honom, sende han eit nytt bod til Hizkia med dei ordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '«Seg med Juda-kongen Hizkia: «Ikkje lat din Gud, som du lit på, narra deg til å tenkja at ikkje Jerusalem skal falla i henderne på assyrarkongen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Du hev nok høyrt gjete sjølv kor assyrarkongarne hev fare åt med mot alle landi: at dei bannstøytte deim. Og so skulde du berga deg undan?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Kunde vel folkegudarne berga sine folk, som federne mine øydde ut: Gozan og Haran og Resef og Edens-sønerne som er i Telassar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kvar er Hamat-kongen eller Arpad-kongen eller kongen i Sefarvajim-byen, yver Hena og Ivva?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Hizkia tok brevet frå sendemennerne og las det; og so gjekk han upp i Herrens hus, og Hizkia breidde det ut for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Og Hizkia bad til Herren og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '«Herre, allhers drott, Israels Gud, du som tronar yver kerubarne! Einast du er Gud yver alle rike på jordi; du hev gjort himmelen og jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Herre, legg øyra til og lyd! Herre, lat augo upp og sjå! Høyr dei ordi Sanherib sende og svivyrde den livande Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Herre, det er sant: assyrarkongarne hev øydt ut folki og deira land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'og dei hev kasta gudarne deira på elden; for dei er ikkje gudar, berre manneverk utav stokk og stein, og dei hev tynt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Men no må du, Herre, vår Gud, frelsa oss frå hans magt, so alle rike på jordi må røyna at einast du er Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Då sende Jesaja Amosson bod til Hizkia med dei ordi: «So segjer Herren, Israels Gud: «Med umsyn på bøni di til meg um Sanherib, assyrarkongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'då er dette det ordet som Herren hev tala imot honom: Ho vanvyrder deg, ho spottar deg, ungmøyi, Sions dotter, ho rister på hovudet åt deg, Jerusalems dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Kven hev du svivyrdt? kven hev du spotta? Kven hev røysti di ropa imot? Augo lyfte du høgt, mot Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Ved tenarane hædde du Herren og sagde: «Med dei mange vognerne mine for eg upp på dei høgste fjelli, ja, langt burti Libanons utmark, der høgg eg ned hennar høge cedrar og dei hæve cypressorne hennar; eg tek meg fram i dei øvste heimar, inn i den tettaste hagen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'eg hev grave og drukke vatn; med fotsolen min eg turkar ut alle Egyptarlands elvar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hev du’kje høyrt at eg hev longe laga det so? Frå ævordsleg tid hev eg fyreåt fastsett dette! Og no let eg det koma i verk! Du fekk magt til å øyda sterke borgar til steinrøysar aude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Folki deira vart veike og valne, skalv og stod til skammar. Det gjekk deim som graset på marki og grøne urtar, som vokstrar på taket, som kornåker fyrr han hev skote.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Eg veit når du sit, gjeng ut og gjeng inn, kor du slær deg vill imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Av di du er vill imot meg, og eg høyrer kor kaut du er, eg hektar min krok i nosi di, legg min taum i munnen din og vikjer deg heim att den vegen du kom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Og dette skal du hava til merke: I år skal de eta sjølvsått korn, næste år sjølvrunne. Men tridje året skal de så og hausta og planta vinhagar og eta frukti av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Og leivningen som er att av Juda hus, skyt djupare røter nedantil, og ovantil ber han si frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'For ein leivning kjem frå Jerusalem, og ein rest frå Sionsfjellet. Brennhugen åt Herren, allhers drott, skal gjera dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Difor segjer Herren so um assyrarkongen: Ikkje skal han koma inn i denne byen, og ikkje skjota nokor pil der inn; ikkje skal han storma fram mot han med skjold, og ikkje byggja skansar upp imot han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Den vegen han kjem, den skal han heim att fara, i denne byen slepp han ikkje inn, so segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Eg vernar denne by og bergar honom, for mi skuld og for Davids skuld, min tenar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Og Herrens engel gjekk ut og slo hundrad og fem og åtteti tusund mann i assyrarlægret. Tidleg næste morgon fann dei deim alle liggjande lik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Då tok assyrarkongen Sanherib ut og drog burt og snudde heim att, og heldt seg sidan i Nineve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Ein gong han heldt bøn i huset åt Nisrok, guden sin, hogg sønerne hans, Adrammelek og Sareser, honom ned med sverd. Dei kom seg undan til Araratlandet, og Asarhaddon, son hans, vart konge i staden hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'I dei dagarne lagdes Hizkia i helsott; då kom profeten Jesaja Amosson til honom og sagde med honom: «So segjer Herren: «Skila for deg! for du skal døy; du vert ikkje god att.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Då snudde Hizkia seg mot veggen og bad til Herren:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, '«Å Herre! kom i hug kor eg hev ferdast ærleg og heilhjarta di åsyn og gjort det som godt var i dine augo!» Og Hizkia sette i og storgret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Då kom Herrens ord til Jesaja soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '«Gakk og seg til Hizkia: «So segjer Herren, Gud åt David, far din: Eg hev høyrt bøni di og set tårorne dine. Sjå, eg aukar alderen din med femtan år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Or handi på assyrarkongen bergar eg deg og denne byen; ja, eg vernar denne byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Og dette gjev Herren deg til merke på at Herren heldt det han hev lova:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Sjå, eg let skuggen på solskiva, som med soli hev gjenge ned på solskiva åt Ahaz, ganga ti strik attende.»» Og soli gjekk attende ti av dei striki ho hadde gjenge ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Ein skrift av Hizkia, kongen i Juda, då han hadde vore sjuk, men hadde kome seg av sjukdomen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '«Eg sagde: I mine beste år lyt eg fara igjenom helheimsportarne; eg lyt bøta med resten av åri mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Eg sagde: Eg fær ikkje sjå Herren, Herren i landet åt dei livande; eg fær ikkje skoda menneskje meir millom deim som bur i stilla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Min bustad vert upprykt og burtførd frå meg som eit hyrdingtjeld. Eg hev rulla mitt liv i hop som ein vevar; frå varpet skjer han meg av; fyrr dag vert natt, er du ferdig med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Eg roa meg alt til morgons; som ei løva, so bryt han alle mine bein; fyrr dag vert natt, er du ferdig med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Som ei svala, ei trana, so sutra eg, eg kurra som ei duva; dimt såg mine augo mot høgdi: Eg er kvidefull, Herre, borga for meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Kva skal eg segja? Han hev meg sagt det, og han hev gjort det. Stilt vil eg ferdast alle mine år for all mi sjælekvida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herre, dei er til liv, og dei held uppe alt liv i mi ånd. So gjer meg då frisk og lat meg liva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Det beiske, det beiske vart meg til fred, og du drog kjærleg mi sjæl or tyningsgravi; for du kasta bak din rygg alle synderne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'For ikkje prisar helheimen deg, ikkje lovar dauden deg; ikkje vonar dei som fer ned i gravi på truskapen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Den livande, den livande, han prisar deg liksom eg i dag; ein far lærer borni sine um truskapen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Herren vil frelsa meg, og på strengleikar vil me leika alle våre livedagar i Herrens hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Jesaja sagde dei skulde taka ei fikekaka og leggja til plåster på svullen, so han skulde friskna til att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Hizkia sagde: «Kva skal eg hava til merke på at eg skal ganga upp til Herrens hus?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Kring den tid sende Babel-kongen Merodak Baladan Baladansson brev og gåva til Hizkia, då han høyrde at han hadde vore sjuk og vorte frisk att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Hizkia var glad for dei kom, og han synte deim skattkammeret sitt, sylvet og gullet og kryddorne og den kostelege oljen, og heile våpnhuset sitt og alt som fanst i skattkammeri hans; det fanst ikkje den ting i hans hus og i heile hans rike som ikkje Hizkia synte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Då kom profeten Jesaja til kong Hizkia og spurde honom: «Kva hev desse mennerne sagt, og kvar helst kom dei frå til deg?» Og Hizkia svara: «Frå eit land langt burte, frå Babel kom dei til meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, '«Kva hev dei set i huset ditt?» spurde han. «Alt som i huset mitt finst hev dei set,» svara Hizkia; «det fanst ikkje den ting i skattkammeri mine som eg ikkje synte deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Då sagde Jesaja til Hizkia: «Høyr ordet frå Herren, allhers drott:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Sjå, dagar kjem då alt som finst i huset ditt, det federne dine hev samla alt til i dag, det skal verta ført til Babel; aldri ein grand skal verta att, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Og sume av sønerne dine, ætta frå deg, utstokne frå deg, skal takast, og dei skal verta hirdmenner i slottet åt Babel-kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Då sagde Hizkia til Jesaja: «Godt er Herrens ord som du hev tala.» Og han sagde framleides: «Det vert då fred og trygd so lenge eg liver.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Trøysta, trøysta mitt folk! Segjer dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Tala mildt til Jerusalem, og ropa til henne, at striden hennar er enda, at skuldi hennar er kvitta, at ho hev fenge av Herren tvifelt for alle sine synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Høyr, det ropar: «Brøyt i heidi veg for Herren! Jamna til i øydemarki gata for vår Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Kvar ein dal skal hevjast, kvart eit berg og bakke jamnast, haugarne verta ei sletta, og hamrarne verta til flatland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Herrens herlegdom skal te seg, alt kjøt skal det få sjå. For Herrens munn hev tala.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Høyr, det segjer: «Preika!» Svarar ein: «Kva skal eg preika?» «Alt kjøt er gras, og alt dess ynde som blom på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Graset visnar, blomen folnar, når Herrens ande blæs på deim. Ja, i sanning, folk er gras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Graset visnar, blomen folnar, men ordet frå vår Gud stend æveleg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Stig upp på høge fjellet, du Sion, fagnadbod! Lat røysti ljoma sterkt, Jerusalem, du gledebod! Lat ljoma, ræddast ei! Seg det til Judas byar: «Sjå der er dykkar Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Sjå, Herren, Herren kjem, den sterke, og med sin arm han ter si magt. Si løn han fører med seg, og fyre gjeng dei han hev vunne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Som hyrding gjæter buskap sin, han sankar deim i armen, smålambi ber ved barmen, og leider møderne vart og lint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kven hev vatnet mælt i sin love, og yver himmelen spanna, og jordmoldi mælt i kanna, og vege fjell på bismar, og haugarne lagt på skålvegt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kven hev rettleidt Herrens ande? Kven gjev honom råd og lærdom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Kven tok han på råd til å gjeve seg skyn, til å lære seg rette vegen, og læra seg kunnskap og visa seg vegen til vit?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Nei, folki er som ein drope på vatsspann, som dust i skålvegt dei reknast, og øylandi føykjer han som fjom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Libanon hev ikkje nok av ved, og ikkje offerdyr nok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Som inkje er alle folki for honom, han reknar deim for tome inkjevetta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Kven vil de då likna Gud med? Kva bilæte setja ved sida?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Bilætet, det støyper meisteren, og gullsmeden gyller det, og støyper sylvkjedor til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Er ein for arm til slik ei gåva, vel han seg tre som ikkje morknar, og leitar upp ein dugleg meister, som set eit stødigt bilæt’ upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Skynar de ikkje? Høyrer de ikkje? Er det’kje meldt dykk frå fyrste stund? Greider de ikkje jorderiks grunnar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Han sit høgt yver jordheims-kringen, dei som der bur, er som grashoppesverm. Himmelen breidde han ut som ein florduk, spana han ut som eit tjeld til å bu i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Hovdingar gjer han til ingen ting, domarar på jordi til inkjevetta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Knapt er dei planta, knapt er dei sådde, knapt hev dei rotfest i jordi sin stomn, fyrr han andar på deim, og dei visnar, stormen føykjer deim burt som strå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Kven vil de likna meg med, so eg honom liktest? den Heilage segjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Lyft dykkar augo mot høgdi, og sjå kven hev som desse hev skapt! Han som mynstrer heren deira, nemner deim alle på namn. Stor i velde og sterk i kraft ikkje han saknar ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Kvi vil du segja, Jakob, og tala so, Israel: «Min veg er løynd for Herren, og min rett kjem burt for min Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Hev du’kje skyna det? Hev du’kje høyrt det? Herren han er ein æveleg Gud, han hev skapt den vide verdi. Han vert ikkje trøytt, han vert ikkje mod, hans vit kann ingen grunda ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Han gjev den trøytte kraft og aukar styrken for magtlaus mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Gutar vert trøytte og mode, og unge karar lyt snåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Men dei som vonar på Herren, fær atter kraft, dei fær nye vengjefjører som ørnar. Dei spring og trøytnar ikkje, dei gjeng og mødest ei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Høyr stilt på meg, de strender, lat folki få seg ny kraft! Lat deim so koma hit og tala! Til doms me fylgjast åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kven vekte frå auster honom som siger fylgjer for fot? Kven gjev honom folk til eiga og kongar til rådevelde? Kven gjer deira sverd til dust, deira boge til fjukande bos?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Han elter deim, fer i fred ein veg som han aldri hev gjenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kven hev gjort og fullført dette? - Han som upphavleg kalla ætterne fram. Eg, Herren, eg er den fyrste og enn hjå dei siste med same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Strender såg det og ræddast, jordheims utbygder skalv, dei kom og stima i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Den eine hjelpte den andre og sa til bror sin: «Ver sterk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Snikkaren gullsmeden mana, og platemakaren smeden; han sa um loddingi: «Ho er god!» So feste han guden med spikar so stødt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Men du, min tenar Israel, du Jakob, som eg ut hev valt, du ætt av Abraham, min ven,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'du som eg tok frå heimsens endar og kalla deg frå ytste utkant og sa til deg: Min tenar er du, eg hev deg valt og ei forsmått,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'ver ikkje rædd, for eg er med deg, ver hugheil, for eg er din Gud! Eg styrkjer deg, og hjelper deg, eg styd deg med mi rettferds hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Sjå, dei vert til spott og skam, dei som harmast på deg; dei vert til inkjes, gjeng til grunns, dei som trættar med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Leitar du, finn du deim ikkje, dei som stridar mot deg; dei vert til null og ingen ting dei som krigar mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'For eg er Herren, din Gud, som held deg i høgre handi og segjer til deg: Ver ikkje rædd! Eg hjelper deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ver urædd, Jakob, arme krek, du vesle flokk av Israel! «Eg hjelper deg», er Herrens ord, og Israels Heilage deg løyser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Eg gjer deg til ei treskjeslede, ein ny og kvass med mange tenner, so du skal treskja, krasa fjell og gjera haugar um til agner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Du kastar deim, og vinden tek deim, og stormen spreidar deim ikring; men du skal frygda deg i Herren og rosa deg av Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Dei arme fatigfolk, dei leitar fåfengt etter vatn, med tunga sårt av torste brenn; men deim vil eg bønhøyra, Herren, Israels Gud, vil ikkje svika deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'På haugar let eg elvar renna, og midt i dalar ollor springa, eg heidi gjer til klåre sjø og turre landet til kjeldevang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'I heidi let eg cedrar veksa, akasja, myrt og oljetre, på snaudheid eg cypressa set i lag med alm og edelgran,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'so folk kann sjå og vita vel og merka seg og skyna grant, at Herrens hand hev dette gjort, og Israels Heilage det skapt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Kom hit med saki dykkar! segjer Herren, gjev dykkar grunnar! segjer Jakobs konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Lat deim då koma, melda oss kva som skal henda. So meld oss kva de fyrr hev spått, at me kann agta på det og sjå um det vert uppfyllt. Ell’ lat oss høyra kva som kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Seg frå kva sidan koma skal, so me kann skyna de er gudar. Ja, gjer då noko godt ell’ vondt, so me kann sjå det alt med undring!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Men de er ingen ting, og dykkar verk er inkjevetta. Ufysleg den som vel seg dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Frå nord eg vakte honom, og han kom frå auster han som på mitt namn skal kalla, han trakka skal på hovdingar som leir, som pottemakar som trør i leira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kven hev frå fyrst det kunngjort so me skyna det, frå fyrste stund so me kann segja: «Han fekk rett?» Nei, ingen hev det meldt, og ingen hev sagt frå, og ingen høyrde at de ymta noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Eg sagde fyrst til Sion: Sjå der er det! Og gav Jerusalem eit gledebod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Eg ser meg um, men der er ingen, imillom deim kann ingen gjeva greida, so eg deim kunde spyrja, og dei svara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Sjå, alle er dei ingen ting, og deira verk er inkjevetta, og deira bilæte er luft og vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Sjå min tenar som eg styd, min utvalde som eg elskar! Honom gjev eg anden min, rett han førar ut til folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Ikkje mun han ropa, skrika, ei på gata bruka mælet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Brostne røyrstrå ei han bryt, sløkkjer ei den veik som gløder, trufast ber han retten ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Ei han veiknar, ei han brotnar fyrr han rett på jord fær setja, øyer ventar på hans lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Soleis talar Herren Gud, som hev himmeln skapt og utspent, jordi lagt med vokstrar på, gjeve folk på henne ande, andedrag åt deim der ferdast:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Eg, Herren, hev deg i rettferd kalla, eg tok deg i handi, eg varar deg og gjer deg til folkepakt og til ljos for heidningar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'til å opna blinde augo, føra fangar ut or fengsel deim som sit i myrker, or fangehus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Eg er Herren, det er mitt namn, ingen annan fær mi æra, ikkje bilæti min pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Sjå, dei fyrste ting er komne, og eg meldar nye ting; endå fyrr dei upp hev runne, eg forkynner dykker deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Syng ny song for Herren, lova han til heimsens endar! Sjøfolk og du havsens myrja, øyland og dei folk der bur!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Heidi syng med sine byar, hytteby der Kedar bur. Dei som bur på berget, jublar, ropar ned frå høgste nut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Dei skal gjeva Herren æra og hans pris til øyland bera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Ut gjeng Herren som ei kjempa, eggjar harmen som ein stridsmann, herrop lyfter han og skrik, ter si magt mot sine motmenn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Stilt eg heve tagt so lenge, mållaus hev eg halde meg. No eg styn som viv i barnsnaud, etter anden syp og pæsar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Berg og haug eg legg i øyde, svider av alt grønt på deim, elvar gjer eg um til øyer, sjøar let eg turkast upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Blinde ukjend veg eg fører, so dei fer ukjende stigar, myrkt gjer eg til ljost for deim, bakkeland til flate sletta. Dette er det eg vil gjera og slett ikkje lata vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Vika lyt storleg skjemmast dei som lit på bilæt-gud, og til støypte bilæt segjer: «De er våre gudar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Dauve, høyr! Blinde, upp med augo! Sjå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kven er blind, um ei min tenar, dauv som sendebodet mitt? Kven er blind som venen min? Kven er blind som Herrens tenar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Mangt du såg, men gøymer ikkje, han fekk øyra upp, men høyrer ei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'For si rettferd skuld vil Herren gjera lovi stor og herleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Men det er eit plundra folk, herja folk, alle bundne sit i hol og i fangehusi løynde. Herfang er dei, og hev ingen frelsar, ran, og ingen segjer: «Gjev det att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kven av dykk gjev gaum på dette, lyder på og høyrer sidan?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kven gav Jakob burt til ran og til ransmenn Israel utan Herren som me synda mot, som hans vegar dei ei fara vilde og ei høyra på hans lov?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'So rende han yver deim sin heite harm og ein veldug krig. Det ikring deim loga, men dei skyna inkje, brende deim, men dei la ikkje det på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Og no segjer Herren so, han som skapte deg, Jakob, og laga deg, Israel: Ver urædd! for eg hev løyst deg ut, eg hev ropa deg på namn, du er min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Fer du gjenom vatn, so er eg med deg, gjenom elvar, so skal dei’kje riva deg burt. Gjeng du i eld, du svidar deg ei, og logen skal ikkje brenna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'For eg, Herren, er din Gud, Israels Heilage er din frelsar. Egyptarland gjev eg til løysepeng for deg, \'tiopia og Seba til vederlag for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'For di du er dyr for meg, du er mykje verd, og eg elskar deg, difor gjev eg menneskje burt for deg og folkeslag for ditt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ver ikkje rædd! for eg er med deg; austanfrå vil eg føra di ætt, og vestanfrå vil eg samla deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Eg segjer til nordheimen: «Kom med deim!» Og til sudheimen: «Haldt deim’kje att! Kom med sønerne mine langt burtanfrå og døtterne mine frå verdsens ende,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'kvar den som heiter etter mitt namn, og som eg hev skapt til mi æra, og som eg hev laga og gjort.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Før fram det blinde folk som hev augo, og dei dauve som lel hev øyro!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Lat alle folki samla seg og alle folkeslag møta. Kven av deim kann forkynna slikt? Lat deim melda kva dei fyrr hev spått. Lat deim møta med vitne og få rett, lat deim høyra og segja: «Det er sant!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'De er mine vitne, segjer Herren, og min tenar som eg hev valt ut, so de skal kjenna og tru meg og skyna at det er eg. Fyre meg vart ingen gud til, og etter meg kjem ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Eg, ja eg er Herren, og utan meg finst det ingen frelsar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Eg hev kunngjort og frelst, eg, og ingen framand gud millom dykk hev forkynt det. De er mine vitne, segjer Herren, og eg er Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Enn i dag er eg den same, og ingen kann berga or mi hand. Det som eg gjer, kven kann gjera det ugjort?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'So segjer Herren, dykkar utløysar, Israels Heilage: For dykkar skuld eg utbod mot Babel og alle saman driv eg på flukt, kaldæarane på sine lystskip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Eg, Herren, er dykkar Heilage, Israels skapar er dykkar konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'So segjer Herren, som gjorde veg i havet, ein stig i dei stride straumar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'som let vogner og hestar draga ut, både her og hovding - dei låg der og reiste seg ikkje, dei er sløkte, dei slokna som lampeveik -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Tenk ikkje på det som fyrr hev vore, og på det framfarne gjev ikkje agt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Sjå, eg gjer noko nytt, no renn det, går de det ikkje? Ja, eg vil gjera veg i heidi, elvar i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Dyri på marki skal æra meg, sjakalar og strussar, for eg gjev vatn i heidi, elvar i øydemarki, so mitt utvalde folk kann få drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Det folk eg hev skapt meg, dei skal forkynna min pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Men på meg hev du ikkje kalla, Jakob, so du gjorde deg bry for meg, Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Ikkje hev du gjeve meg dine brennofferlamb, og ikkje meg æra med dine slagtoffer, ikkje hev eg brytt deg med grjonoffer, og ikkje med røykjelse plåga deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Ikkje hev du for pengar kjøpt meg krydderøyr, og ikkje kveikt meg med feittet av dine slagtoffer. Nei, du hev trøytta meg med dine synder og brytt meg med dine misgjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Eg, ja eg er den som slettar ut misgjerningarne dine for mi skuld, og eg kjem ikkje synderne dine i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Minn meg, so gjeng me saman til doms, fortel du, so du kann få rett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Den fyrste far din synda, og dine målsmenn var utrue mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'So laut eg vanhelga heilage hovdingar, lysa Jakob i bann og Israel gjeva til spott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Men høyr no, Jakob, tenaren min, du Israel som eg hev valt ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'So segjer Herren som skapte deg, som laga deg frå morsliv og hjelper deg: Ver ikkje rædd, du min tenar Jakob, Jesurun som eg hev valt ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'For eg vil renna vatn yver det tyrste, og straumar yver det turre. Eg vil renna min ande ut yver di ætt, og yver ditt avkjøme mi velsigning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Dei skal veksa upp millom graset som pilar ved bekkjefar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Ein segjer: «Eg høyrer Herren til,» ein annan kallar seg med Jakob-namnet, ein skriv med si hand: «For Herren,» og brukar til ærenamn Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'So segjer Herren, Israels konge, og hans utløysar Herren, allhers drott: Eg er den fyrste og eg er den siste, og utan meg finst det ingen Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Kven forkynte jamt og samt som eg - lat han melda og leggja det fram for meg! - frå den tid eg skapte fornalder-folket? Og lat deim melda det som i framtidi kjem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ver ikkje forstøkte og rædde! Hev eg ikkje for lenge sidan forkynt og meldt deg det? De er mine vitne; finst det nokon Gud utan meg? Nei, eg veit ikkje um noko anna berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Dei som lagar gudebilæte er alle inkjevetta, og deira kjære gudar kann ikkje hjelpa; deira vitne ser inkje og skynar inkje, difor vert dei til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Um nokon lagar ein gud og støyper eit bilæte, er det til unyttes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Alle som held seg til det, skal verta til skammar, og meistrarne er berre menneskje, lat deim samla seg og stiga fram alle, dei skal ræddast og verta til skammar alle i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Smeden kvesser ei øks og lagar henne til i koleld og formar henne med sleggjor, og han gjer henne ferdig med sin sterke arm. Vert han so svolten, minkar magti, og fær han ikkje drikka vatn, vert han veik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Snikkaren spanar snori og ritar med gravstikka, han slettar med hyvelen og dreg ringar med passaren; so lagar han dei som eit mannslike, som ein fager mann som fær bu i eit hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Ein gjev seg til å hogga cedrar, og han tek steineik og eik og vel seg ut eit millom skogstrei. Han plantar ei fura, og regnet fær henne til å veksa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Mannen brukar treet til å brenna, han tek av det og vermer seg, ja, han kveikjer på og bakar brød. So gjer han og ein gud som han bed til, han formar eit gudebilæte som han bøygjer kne for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Helvti av det brenner han upp i elden, ved den helvti et han kjøt, steikjer ei steik og mettar seg. Han vermer seg og, og segjer: «Hå, eg vert varm, eg merkar eld!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Resten av det gjer han til ein gud, til sin avgud som han bøygjer seg for og bed til, og han bed soleis: «Frels meg, for du er min gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Dei er utan vit og skyn, for attklistra er augo deira, so dei ikkje ser, og hjarto deira so dei ikkje skynar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Ingen tenkjer seg um, ingen hev klokskap og skyn nok til å segja med seg: «Helvti hev eg brent upp i elden, i gløderne hev eg baka brød og steikt kjøt og ete, og so skulde eg laga resten til eit ufyselegt bilæte og bøygja kne for ein trekubbe!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Den som agtar på oska, honom hev eit forvilla hjarta dåra, so han ikkje kjem til å frelsa si sjæl og segja: «Det er lygn det eg held i mi høgre hand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Kom dette i hug, du Jakob, du Israel, min tenar! Eg hev skapt deg, du er min tenar, Israel, eg gløymer deg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Eg hev stroke burt dine brot som ei skodda, og synderne dine som ei sky; vend um til meg, for eg hev løyst deg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Jubla, himlar! For Herren hev sett det i verk. Ropa med frygd, de dypter i jordi! Set i med jubel, de fjell! Du skog med kvart eit tre! For Herren hev løyst ut Jakob, og syner seg herleg på Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'So segjer Herren, utløysaren din, skaparen din frå moderliv: Eg er Herren som allting gjer, himmelen spana eg ut åleine, jordi breidde eg ut utan medhjelp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Eg gjer juglarteikni um inkje, og spåmenner gjer eg til fåmingar; eg let vismenner koma til kort og gjer deira vitskap til dårskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Eg stadfester ordet åt tenaren min og fullfører rådi åt sendebodi mine. Eg segjer um Jerusalem: «Der skal bu folk!» Og um Juda-byarne: «Dei skal byggjast!» Ruinarne der vil eg reisa att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Eg segjer til djupet: «Torna, dine straumar turkar eg ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Eg segjer til Kyrus: «Min hyrding!» Han skal fullføra all min vilje og til Jerusalem segja: «Vert bygd! Og templet verta grunnlagt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'So segjer Herren til sin salvevigde, til Kyrus som eg held i hans høgre hand, for å kasta folk til jordi for honom og løysa beltet av kongar, for å opna dører for honom, so ingen portar vert stengde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Sjølv gjeng eg fyre deg og jamnar hindringar; kopardører sprengjer eg, og jarnslåer slær eg sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Og eg gjev deg dulde skattar og burtgøymde rikdomar, so du skal vita at det var eg, Herren, som kalla deg på namn, eg, Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'For min tenar Jakobs skuld og Israel, min utvalde, kalla eg deg med namnet ditt, gav deg tilnamn då du ikkje kjende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Eg er Herren, og ingen annan, utan meg finst det ingen Gud. Eg væpna deg fyrr du kjende meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'so dei skal vita frå aust til vest at det finst ingen annan enn eg. Eg er Herren, og ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Skapar åt ljoset og upphav til myrkret, skapar åt velferd og upphav til uferd; eg, Herren, gjer alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Lat det drjupa, de himlar, ovanfrå, og skyerne renne med rettferd! Jordi late seg upp, so frelsa kann bløma og rettferd renna med same! Eg, Herren, skaper det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Ve den som trættar med skaparen sin! Eit skålbrot millom dei andre av jord. Kann leiret til formaren segja: «Kva gjer du?» Eller verket ditt segja: «Han hev ikkje hender?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ve den som segjer til far sin: «Kva avlar du?» Og til kvinna: «Kva føder du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'So segjer Herren, Israels Heilage og skapar: Spør meg um det som kjem! Lat meg syta for mine søner, og det verk mine hender hev gjort!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Det var eg som gjorde jordi, og folket der hev eg skapt; mine hender spana ut himmelen, og all hans her baud eg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Det er eg som honom hev vekt i rettferd, og alle hans vegar jamnar eg. Han skal byggja min by og senda mine landlyste heim, og det utan vederlag, utan betaling, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'So segjer Herren: «Rikdomen frå Egypt og vinningi frå \'tiopia, og Saba-mennerne, røslege karar, skal koma til deg og høyra til deg; dei skal fylgja deg og ganga i lekkjor; for deg skal dei kasta seg ned, til deg skal dei venda si bøn: Berre hjå deg er Gud og elles ingen, ingen Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'I sanning, du er ein løyndomsfull Gud, du Israels Gud, du frelsar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Til spott og skam vert dei alle saman, gude-makaran’ gjeng med blygsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israel vert frelst ved Herren med æveleg frelsa, de vert ikkje til spott og skam i alle ævor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'For so segjer Herren, himmelskaparen, han som er Gud, han som hev gjort og laga jordi, han som hev grunnfest henne; ikkje til ei audn skapte han henne, men til folkebustad laga han henne! - Eg er Herren, og ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Ikkje i løyndom hev eg tala, ein stad i myrke-land; ikkje hev eg sagt til Jakobs-ætti: Leita etter meg fåfengt! Eg, Herren, talar rettferd, forkynner det som er rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Samle dykk og kome, kome saman hit, de som er att av heidningfolki! Uvituge er dei som ber på sitt trebilæte og bed til ein gud som ikkje kann frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Forkynn og seg frå! Ja, lat deim berre samrådast! Kven hev kunngjort slikt frå fordom, meldt det for lenge sidan? Tru det ikkje er eg, Herren? Og utan meg er det ingen Gud. Ein rettferdig og frelsande Gud finst ikkje utanum meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Vend dykk til meg, lat dykk frelsa, alle utbygder av jordi! For eg er Gud, og ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Ved meg sjølv hev eg svore, or min munn er det gjenge sanning, eit ord som eg ikkje tek i meg att: For meg skal bøygja seg kvart eit kne, til meg skal kvar ei tunge sverja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Berre hjå Herren, skal dei segja um meg, er rettferd og magt. Til honom skal dei koma og skjemmast alle som harmast på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'I Herren vinn dei rettferd og rosar seg alle som er av Israels ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel stuper, Nebo sig. Deira bilæte kjem til dyr og fe. De bar deim i høgtid, no legg de deim på dyr som ber seg trøytte av byrdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Dei sig og stupar alle saman, dei kann ikkje berga byrdi, og sjølv lyt dei fara or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Høyr på meg, du Jakobs hus, og heile du leivning av Israels hus! De som er borne frå moderliv og lyfte på hender frå moderfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Til dykkar alderdom er eg den same, og til dei gråe hår skal eg bera dykk. Eg hev gjort det, og eg skal lyfta, eg skal bera og berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Kven vil de likna meg med og setja meg jamsides med? Kven set de upp til jamliken min?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Dei rister gull utor pungen, veg upp sylv på vegti, leiger ein gullsmed til å laga ein gud, som dei bøygjer seg for og bed til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Dei tek han på nakken og ber honom burt og set honom på sin plass, so stend han der og flyt seg ikkje av flekken. Ropar ein til han, so svarar han ikkje, or naudi bergar han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Tenk på det, og vert støde, de fråfalne, tak det til hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Tenk på det fyrste frå fordoms tid, at eg er Gud og ingen annan, ein Gud som ei hev sin like,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'eg som frå upphavet enden varslar, og frå fordom det som ikkje endå hev hendt, eg som segjer: «Mi rådgjerd skal standa, og alt det eg vil, det gjer eg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Eg som kallar ørnen frå aust, langt burtanfrå mannen som fullfører mi råd. Som eg hev sagt det, so let eg det koma, som eg hev tenkt det, eg set det i verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Høyr på meg, de stridlyndte, som er langt burte frå rettferd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Eg fører hit mi rettferd, ho er ikkje langt burte, og mi frelsa skal ikkje drygja. Eg gjev frelsa i Sion og til Israel min herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Stig ned og set deg i moldi, du møy Babel-dotter! Set deg på jordi utan kongsstol, du kaldæar-dotter! For ei skal du lenger kallast den kløkke og kjælne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Tak handkverni og mal mjøl, legg sløret burt! lyft slæpet upp, næk leggen, vad yver elvar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Lat skammi di syna seg, lat deim sjå di skjemsla! Hemn tek eg og sparer ikkje eit menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Vår utløysar, Allhers-Herren han heiter, Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Set deg stilt og gøym deg i myrkret, du kaldæar-dotter! For ei skal du lenger kallast dronning yver riki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Eg var harm på mitt folk, vanhelga min arvlut og gav deim i dine hender. Men du viste ikkje medynk. Jamvel på gamlingar la du ditt tunge ok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Du sagde: «Eg skal alltid vera \'ve-dronning,» du la ikkje det på hjarta, tenkte ikkje på endelykti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'So høyr no det, du kjælne, som trunar so trygt, du som segjer i ditt hjarta: «Eg og ingen annan! Eg skal ikkje sitja enkja, og aldri sjå meg barnlaus!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Båe desse ulukkor skal brått koma yver deg på ein einaste dag, barnløysa og enkjestand kjem på deg i fullaste mål, tråss i dine mange trollingar og dine sterke bannlysingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Du var trygg i vondskapen din og sa: «Det er ingen som ser meg!» Visdomen din og vitskapen din hev dåra deg, so du sa i ditt hjarta: «Eg og ingen annan!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'So skal det då vondt koma yver deg, som du veit’kje å venda av, ei ulukka skal falla yver deg, som du ikkje kann sona burt, og brått skal det koma yver deg tjon når du ikkje varast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Kom no med dine bannlysingar, dine mange trollingar, som du hev stræva med ifrå ungdomen! Kanskje kunde du finna hjelp, kanskje skræma ulukka burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Du hev trøytta deg med dine mange råder, lat deim so møta, lat dei himmelkunnige hjelpa deg, stjernekikaran’, dei som kvar månad forkynner kva som skal hendast deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Men dei hev vorte som halm, elden brenner deim upp, dei kann ikkje berga sitt eige livet or loge-vald. Det er ikkje glod til å verma seg med, ikkje bål til å sitja attved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'So gjeng det deg med deim du hev stræva for, handelsvenerne dine frå ungdomen din. Dei vildrar kvar sin veg, ingen som hjelper deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Høyr dette, de av Jakobs hus, de som er nemnde med Israels-namnet og hev runne or Judas kjelda, de som sver ved Herrens namn og ærar Israels Gud - men ikkje med sanning og rett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'For dei kallar seg etter den heilage byen og lit på Israels Gud som heiter Allhers-Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Dei fyrste hendingar hev eg forkynt for lenge sidan, or min munn gjekk dei ut, og eg kunngjorde deim; brått hev eg sett deim i verk, og dei kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'For eg visste at du er hard, at nakken din er som ei jarnspong og panna di som kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'So forkynte eg deg det for lenge sidan, kunngjorde deg det fyrr det kom, so du ei skulde segja: «Bilætet mitt hev gjort det, mitt skorne eller støypte bilæt’ hev skipa det til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Du hev høyrt det, sjå det no alt i hop! Og de, må de ikkje sanna det? Men no eg forkynner deg nytt, dulde ting som du ikkje veit um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'No vert det skapt og ikkje fyrr, og du hev’kje høyrt um det fyrr i dag, so du ikkje skulde segja: «Det visste eg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Du hev korkje høyrt eller visst det eller fyrr fenge øyra upp for det, for eg visste at du er falsk, og «utru» du heiter frå moderliv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'For mitt namn skuld døyver eg min harm, og for mi æra skuld ber eg yver med deg, so eg ikkje tynar deg reint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Eg hev smelta deg - men vann ikkje sylv, eg hev prøvt deg i lidingsomnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'For mi skuld, for mi skuld gjer eg det, for skulde eg tola at namnet mitt vert krenkt? Mi æra gjev eg ingen annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Høyr på meg, Jakob, og du Israel som eg hev kalla! Eg er det, eg, den fyrste, og eg er den siste med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Mi hand hev og grunnfest jordi, og mi høgre hand spana himmelen ut. So snart eg kallar på deim, stend dei der båe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Kom saman alle og høyr: Kven av deim hev kunngjort dette? Han som Herren elskar, skal gjera hans vilje mot Babel og vera hans arm mot kaldæarfolket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Eg, eg hev tala, ja hev kalla honom, eg hev late han koma og få lukka på ferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Kom hit til meg, høyr dette! Frå upphavet tala eg ei i løyndom. Frå den tid det kom, då var eg der. Og no hev Herren, Herren sendt meg og sin ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'So segjer Herren, utløysaren din, Israels Heilage: Eg er Herren, din Gud, som lærer deg det som gagnar, som leider deg på vegen du skal fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Å, vilde du lyda på mine bod! Då vart din fred som elvi og di rettferd som havsens bylgjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Då vart di ætt som sanden og di livsfrukt som sandkorn; ættarnamnet vart aldri øydt eller utsletta for mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Drag ut or Babel, fly frå kaldæarland! Med fagnadrop forkynn og fortel det, spreid det ut til verdsens ende! Seg at Herren hev løyst ut sin tenar Jakob!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Dei tyrste ikkje; i øydemark førde han deim, vatn or berget let han sildra åt deim, han kløyvde berget, og vatnet renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Dei gudlause hev ingen fred, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'De øyland, høyre på meg, og lyde, de folk langt burte! Meg hev Herren kalla frå moderliv og nemnt meg på namn frå moderfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Min munn hev han gjort til eit sverd so kvast, i skuggen av handi si hev han meg gøymt, og meg hev han gjort til ei pil so blank og hev gøymt meg i pilehuset sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Og han sa til meg: «Min tenar, er du Israel, som meg æra skal gjeva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Men eg sagde: «Eg hev stræva til fåfengs, til unyttes reint hev eg øydt mi kraft. Men like vel er min rett hjå Herren, og løni mi er hjå min Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, '«Men no,» segjer Herren, som hev gjort meg til tenar frå moderliv til å føra Jakob attende til han, so Israel kann samlast til han - og eg vann æra for Herrens augo, og min Gud, han vart min styrke -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'han segjer: «D’er for lite at du er min tenar til å attreisa Jakobs ætter og Israels leivningar føra til meg. So vil eg gjera deg til heidningljos, at mi frelsa kann nå til enden av jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'So segjer Herren, Israels løysar og Heilage, til den djupt vanvyrde som folk hev stygg for, til trælen under tyranner: Kongar skal sjå det og reisa seg upp, hovdingar med, og kasta seg ned for Herrens skuld som trufast er, Israels Heilage som valde deg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'So segjer Herren: I nådestundi eg bønhøyrer deg, og på frelsedagen hjelper eg deg, og eg varar deg og gjer deg til folkepakt, til å attreisa landet og utskifta øydelagd odelsgrunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Du skal segja til fangar: «Gakk ut!» Til deim i myrkret: «Kom fram!» Attmed vegarne skal dei få beita og hava kvar snaudheid til beite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Dei skal ikkje svelta, skal ikkje tyrsta, og ikkje skal sandglod og solsteik deim skada, for deira miskunnar skal føra deim og leida deim lint til uppkomevatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'og alle mine fjell vil eg gjera til veg, og mine stigar skal byggjast høge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Sjå, dei kjem langt burtanfrå! sume frå nord og sume frå vest og sume frå sinesar-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Jubla himmel, og fegnast jord, de berg set i med glederop! For Herren trøystar sitt folk og miskunnar armingarn’ sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Men Sion segjer: «Herren hev forlate meg, Herren hev gløymt meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Gløymer vel ei kvinna sogbarnet sitt, so ho ikkje miskunnar den ho bar under hjarta? Um endå dei kunde gløyma, so gløymer eg ikkje deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Sjå her, eg hev teikna deg på henderne mine, murarne dine hev eg alltid for augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Sønerne dine skundar seg hit, dei som braut deg i grus, fer burt frå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Upp med augo og sjå deg ikring! Alle samlar seg hit til deg. So sant eg liver, segjer Herren, du skal hava deim alle på deg til prydnad og binda deim um deg til brurebelte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'For ruinarne dine og grushaugarne og ditt herja land - jau, no vert du for trong for borgarane, og burte er dei som gløypte deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Endå skal du få høyra borni frå barnløyse segja: «Romet er meg for trongt. Flyt deg, so eg kann få bu!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Då tenkjer du med deg sjølv: «Kven hev født meg desse borni? For eg var barnlaus og ufør til føding, utlæg og heimlaus, kven hev fostra desse? Eg sat eismall att, kvar var då dei?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'So segjer Herren, Herren: Sjå, eg lyftar mi hand for heidningarne, og reisar mitt merke for folkeslagi, so kjem dei med sønerne dine i fanget, og døtterne dine ber dei på herdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Kongar vert fosterfeder for deg og deira dronningar ammor åt deg. Dei kastar seg ned på jordi for deg og slikkar moldi av føterne dine. Då fær du røyna at eg er Herren, at dei ikkje vert svikne som vonar på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Kann ein taka herfanget frå ei kjempa? Eller fangarne sleppa frå den som hev siger-retten?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Ja! for so segjer Herren: Både skal dei taka fangar frå kjempa, og valdsmanns herfang skal sleppa undan, og eg vil strida med motparten din og frelsa sønerne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Eg let dine trælkarar eta sitt eige kjøt og drikka sitt blod som druvesaft. Og alt kjøt skal kjenna at det er eg, Herren, som frelsar deg, og at Jakobs Velduge løyser deg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'So segjer Herren: Kvar er skilsmålsbrevet åt dykkar mor som eg hev sendt henne burt med? Eller hev eg nokon kravsmann som eg hev selt dykk til? Nei, for synderne dykkar er de selde, og for dykkar brot er mor dykkar burtsend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Kvifor fann eg ingen då eg kom? Kvifor svara ingen då eg ropa? Er mi hand for stutt til utløysing, hev eg ingi kraft til å hjelpa? Med mitt trugsmål legg eg havet turt, elvarne gjer eg til øydemark, so fiskarne rotnar for vatnet er burte, og dei daudar av torste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Eg klæder himmelen i svart og sveiper honom i syrgjebunad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Herren, Herren hev gjeve meg ei læresveins-tunga, so eg kann vita å kveikja den trøytte med ord. Han vekkjer kvar morgon, han vekkjer mitt øyra til å høyra på læresveins vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Herren, Herren hev opna mitt øyra, eg var ikkje strid og drog meg’kje undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Min rygg baud eg fram åt deim som slo, og kinni åt deim som i skjegget reiv. Eg løynde ikkje mitt andlit for hæding og sputt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Men Herren, Herren, han hjelpar, di turvte eg ikkje skjemmast. Difor gjorde eg andlitet hardt som stein, og eg veit eg vert ei til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Min målsmann er nær, kven strider mot meg? Kom, lat oss berre møtast! Er nokon motparten min, so lat honom koma hit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Sjå, Herren, Herren, han hjelpar meg, kven er det som domfeller meg? Sjå, alle skal morkna som klædeplagg, mol skal eta deim upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kven er det av dykk som ottast Herren, og høyrer på røysti åt tenaren hans? Um han ferdast i myrker, og ikkje ser minste ljos, skal han lita lel på Herrens namn og stydja seg på sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Men alle de som kveikjer eld, som væpnar dykk med brennande piler! Inn med dykk i logen av elden dykkar, og under dei brandpiler de hev kveikt! Frå mi hand skal det koma yver dykk, i pinsla skal de få liggja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Høyr på meg, de som jagar etter rettferd, de som søkjer Herren! Sjå på det fjell de er hogne utor, brunnen som de er gravne utor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Sjå på Abraham, dykkar far, og på Sara som fødde dykk! Ein han var då eg kalla honom, og eg signa honom so han vart mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'For trøyst vil Herren gjeva til Sion, trøyst til alle ruinarne hennar. Audheidi hennar gjer han til Eden, og øydemarki til Herrens hage. Gleda og frygd skal finnast der, lovsong og jubeltonar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Høyr på meg, du mitt folk, og lyd på meg, du min lyd! For lov gjeng ut ifrå meg, og min rett eg set til ljos for folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Nær er alt mi rettferd, til synes kjem mi frelsa, og mine armar hjelpar folki til rett. Øyland ventar på meg, og på min arm dei stundar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Lyft augo upp til himmelen, og sjå på jordi her nede! For himmelen skal kverva som røyk, og jordi skal morkna som klædeplagg, dei som bur der, døy som my. Men æveleg varer mi frelsa, og aldri tryt mi rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Høyr på meg, de som kjenner rettferd, du folk med mi lov i ditt hjarta! Ottast ikkje for menneskjespott, og ræddast ikkje deira hæding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'For mol skal deim eta som klæde, og åt skal deim eta som ull. Men æveleg varer mi rettferd, og mi frelsa frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Vakna, vakna, klæd deg i kraft, du Herrens arm! Vakna upp som i fordoms tid, som i gamle dagar! Var det’kje du som ubeistet hogg, og sjøormen stakk i hel?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Var det ikkje du som turrlagde havet, vatnet i store-djupet, havbotnen gjorde til veg, so dei utløyste der kunde fara?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Dei som Herren hev frikjøpt, skal snu heim og koma til Sion med jubelsong, med æveleg gleda til hovudkrans. Gleda og frygd skal dei nå, og sorg og sukk skal fly.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ja, eg er dykkar trøystar. Kven er då du som ræddast for menneskje som skal døy, for mannsborn som kverv som gras?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Og du gløymer Herren, din skapar, himmel-utspanaren, jord-grunnfestaren, og ræddast stødt all dagen for valdsmanns vreide! Når han siktar på øydeleggjing, kvar er då valdsmanns vreide?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Snart skal han verta løyst, han som ligg bøygd i band, og han skal ikkje døy og ganga i gravi, og ikkje skal han vanta brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Og eg er Herren, din Gud, som rører upp havet so bylgjorne bruser. Allhers-Herren er namnet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Og eg lagde ordi mine i munnen din og løynde deg i skuggen av handi mi, so eg kunde planta ein himmel og grunna ei jord og segja til Sion: Du er mitt folk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Råd or, råd or, reis deg, Jerusalem! Du drakk av Herrens hand hans vreide-staup! Tumleskåli laut du tøma til botnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Det er ingen som leider henne av alle dei borni ho fødde, og ingen tek henne i handi av alle dei borni ho fostra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Tvo ting var det som hendest deg - kven ynkar deg? - vald og våde, svolt og sverd - kven trøystar deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Sønerne dine seig ned og låg på alle gatehyrno som ein hjort i garnet, dei var metta med Herrens brennande harm, med refsingsord frå din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Difor høyr då dette, du arming, du som er full, um ikkje av vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'So segjer herren din, Herren, din Gud som forsvarer sitt folk: No tek eg tumleskåli or handi på deg, mitt vreide-staup skal du ikkje tøma meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Og eg gjev det i handi på plagaran’ dine, dei som sagde til deg: «Legg deg ned, so me kann få trøda på deg!» og du gjorde din rygg lik flate marki, som ei gata for ferdafolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Vakna, vakna! klæd deg i di kraft, du Sion! Klæd deg i ditt høgtidsskrud, Jerusalem, du heilage by! For aldri meir skal det koma i deg ein u-umskoren eller urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Rist av deg dusti og reis deg, og kom deg til sætes, Jerusalem! Løys deg frå lekkjorne um din hals, du fanga Sions-dotter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'For so segjer Herren: For inkje vart de selde, og utan pengar skal de verta utløyste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'For so segjer Herren, Herren: Fyrr drog folket mitt ned til Egyptarland og vilde vera gjester der, og Assur var hard imot det utan grunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Og no, kva skal eg vel gjera her? segjer Herren, då folket mitt er burtrive for inkje, valdsherrarne uler, segjer Herren, og alltid, heile dagen, vert namnet mitt spotta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Difor skal folket mitt læra å kjenna namnet mitt; difor skal de merka den dagen at det er eg som taler: ja, her er eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Kor fagre er på fjelli hans føter som ber gledebod, som forkynner fred, som ber godt bod, som forkynner frelsa, som segjer til Sion: «Din Gud er no konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Høyr, dine vaktmenn ropar! Dei jublar alle i hop. For dei ser med eigne augo at Herren kjem heim att til Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Set alle i med jubelrop, de grushaugar i Jerusalem! For Herren trøystar sitt folk, løyser ut Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Herren syner sin heilage arm for augo på alle folk, og alle utbygder på jordi ser frelsa frå vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Burt, burt, drag ut derifrå! Ikkje rør noko ureint! Drag ut derifrå og reinsa dykk, de som ber Herrens kjerald!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'For de skal ikkje fara hovudstup, ikkje heller renna i flog. For Herren gjeng fyre dykk, og Israels Gud fer sist i ferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Sjå, vist ber min tenar seg åt, han stig og veks, vert umåteleg stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Som dei fælte av deg mange - so umenneskjeleg skamførd såg han ut og ei som mannsborn hans skapnad var -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'so fær han mange folkeslag til å furda, yver honom skal kongar tagna; for dei ser det som ei var fortalt deim, og dei ansar på det som dei aldri hev høyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kven trudde det bodet me høyrde? Og kven synte Herrens arm seg for?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Han rann som ein renning for augo hans, som ein teinung or turre jordi. Uskapleg var han og lite sjåleg. Me såg han, men ei såg han hugnadleg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Vanvyrd var han, so folk heldt seg undan, ein mann i pinslor og velkjend med sjukdom, som ein som ingen vil sjå på, vanvyrd, og me honom rekna for inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Men våre sjukdomar var det han bar, og våre pinslor som han tok på seg, medan me trudde Gud hadde råka og slege og plåga honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Ja, han vart såra for våre brot og sundbroten for våre synder. Refsing til fred for oss låg på honom, og ved hans sår fann me lækjedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Alle for me vilt som sauer, vende oss kvar sin veg; men Herren let råka honom det som me hadde skuld i alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Skamfaren vart han, men leid so viljug og let ikkje upp sin munn, som lambet dei fører til slagting, og sauen som tegjer når han vert klypt - han let ikkje upp sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Med vald og dom vart han teken burt, men kven i hans samtid tenkte då: «Burtriven vart han or livandelandet, for mitt folks brot fekk han ulivssår?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Millom gudlause gav dei han grav, men hjå rikmann var han i dauden; for ingen urett hadde han gjort, og det fanst ikkje svik i hans munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Men Herren vilde med sott honom krasa. Når hans sjæl eit skuldoffer bar, skulde han avkjøme sjå og langt liv, og Herrens vilje ved honom lukkast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'For si sjæle-møda skal han sjå det og mettast, ved sin kunnskap gjev han rettferd, min rettvise tenar, til mange, med di han ber deira skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Difor gjev eg honom mange til lut, og sterke fær han til herfang, for han tømde si sjæl til dauden og vart millom brotsmenner rekna, medan han bar syndi åt mange, og han for brotsmenner bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Fagna deg, du barnlause, du som ikkje fødde! Set i med fagnadrop og jubla, du som ei hadde rider! For den einslege hev fleire born enn den gifte kona, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Vida ut tjeldromet ditt, lat deim spana ut tjeldet du bur i, hindra det ikkje! Tøyg tjeldsnorerne dine, og slå pålarne fast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'For du skal breida deg til høgre og vinstre, og di ætt skal taka heidningfolk til eiga og folka upp att øydelagde byar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ottast ikkje, for du skal ikkje turva skjemmast, ver ikkje skamfull, for du skal ikkje turva raudna. Nei, skammi frå ungdomen skal du gløyma, og spotti frå enkjestandet skal du’kje minnast meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'For mannen din er skaparen din, Allhers-Herren er namnet hans, og Israels Heilage er din utløysar. Han heitar Gud for all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Då du var ei burtstøytt kvinna med hjartesorg, kalla Herren deg. Kor kann ein forsmå sitt ungdomsviv? Segjer din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Ei liti stund gjekk eg frå deg, men i miskunn stor vil eg samla deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'I ei harmflaga løynde eg mi åsyn for deg ei stund, men med æveleg nåde miskunnar eg deg, segjer Herren, utløysaren din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'For som Noah-flaumen er dette for meg. Som eg svor at Noah-flaumen ikkje meir skal koma yver jordi, so hev eg svore at eg ikkje meir vil harmast på deg eller skjenna på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Ja, um fjelli vik og haugarne svigtar, so skal ikkje nåden min vika frå deg, og mi fredspakt skal ikkje svigta, segjer Herren som miskunnar deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Du arme stormdrivne, trøystarlause, sjå, eg legg dine steinar i antimon, byggjer grunnmuren din med safirar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Eg gjer dine murtindar av rubinar og portarne av karfunkel og heile din ringmur av dyre steinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Og alle dine søner skal vera upplærde av Herren, og stor fred skal sønerne dine hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Ved rettferd skal du standa fast, ver trygg for vald, du hev inkje å ottast, og for rædsla, ho når deg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Yppar nokon til strid, kjem det ikkje frå meg, den som tek på deg, skal falla i striden mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Sjå, eg hev skapt smeden som blæs i kolelden og lagar våpn til sitt bruk, og eg hev skapt tynaren til å øyda det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Alle våpn dei smider mot deg, skal vanheppast; og kvar tunga som yppar strider med deg, skal du få domfelt. Det er den arv som Herrens tenarar fær, og deira rettferd frå meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Å, alle de tyrste, kom til vatnet! Og de som ikkje hev pengar, kom, kjøp korn og et! Ja, kom og kjøp korn utan pengar, og utan betaling vin og mjølk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Kvi gjev de pengar ut for det som ikkje er brød? Og dykkar vinning for det som ikkje kann metta? Å, høyr på meg og et det som godt er, og dykkar sjæl skal njota feitemat!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Vend øyra hit og kom til meg! Høyr, so skal dykkar sjæl få liva! So gjer eg med dykk ei æveleg pakt, og gjev dykk Davids usviklege nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Sjå, eg hev sett han til vitne for folki, til hovding og styrar for folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Ja, du skal kalla på eit folk som du ikkje kjenner, og folk som ikkje kjenner deg, skal skunda seg til deg, for Herrens skuld, din Gud, for Israels Heilage skuld, for han hev herleggjort deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Søk Herren medan han er å finna, kalla på honom den stund han er nær!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Den gudlause vende seg frå sin veg, og den urettferdige frå sine tankar, og vende seg um til Herren, so skal han miskunna honom, og til vår Gud, for han skal rikleg forlata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'For mine tankar er ikkje dykkar tankar, og dykkar vegar er ikkje mine vegar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Nei, so høg som himmelen er yver jordi, so er mine vegar høgre enn dykkar vegar og mine tankar høgre enn dykkar tankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'For liksom regnet og snøen fell ifrå himmelen og ikkje fer upp att dit fyrr det hev vatna jordi og gjeve henne grokraft og grøda, ja, gjeve såkorn og brødkorn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'so skal det vera med ordet mitt som gjeng ut or munnen min, det skal ikkje koma att til meg tomt, men verka det som eg vil, og fullføra det som eg sende det til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Ja, med gleda skal de draga ut og verta førde i fred. Fjell og haugar skal setja i med fagnadrop fyre dykk, og alle tre på marki skal klappa i hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'I staden for tornar skal det veksa cypressor, i staden for tistlar veksa myrt. Dermed fær Herren eit ærenamn, eit ævemerke, som aldri vert øydt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'So segjer Herren: Tak vare på rett og gjer rettferd! For mi frelsa er alt i kjømdi, og mi rettferd skal syna seg snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Sæl er den mann som gjerer dette, den menneskja som held fast på det, som held kviledagen utan vanhelging og varar si hand frå vonde verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Den framande må ikkje segja, han som held seg til Herren: «Herren vil skilja meg frå sitt folk!» Og gjeldingen må ikkje segja: «Sjå, eg er eit turka tre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'For so segjer Herren: Dei gjeldingar som held mine kviledagar, som vel det som er min vilje, og som held fast på mi pakt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'åt deim skal eg i mitt hus og innanfor mine murar gjeva eit namn og eit minne som er betre enn søner og døtter; eit æveleg namn gjev eg deim, eit namn som aldri øydest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Og dei framandfødde som held seg til Herren og vil tena honom og elska Herrens namn, og vil vera hans tenarar, kvar som held kviledagen utan vanhelging, og held fast på mi pakt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'deim vil eg føra til mitt heilage berg og gleda deim i mitt bønehus, deira brennoffer og slagtoffer skal vera til hugnad på altaret mitt! For mitt hus skal kallast eit bønehus for alle folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'So segjer Herren, Herren, som samlar dei spreidde av Israel: Endå fleire samlar eg til han attåt deim som er samla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Alle villdyr i marki, kom og et, ja, alle villdyr i skogen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Vaktmennerne her er alle blinde, dei skyner ingen ting. Alle er dei mållause hundar som ikkje kann gøy, dei ligg og drøymer, likar å sova;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'dei er hækne hundar, vert aldri mette, og slike folk er hyrdingar, som ikkje veit å gjeva gaum! Dei vender seg alle sin eigen veg, kvar til si eigi vinning, alle som ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '«Kom, eg skal henta vin, so vil me drikka rusdrykk; som i dag skal morgondagen vera, me skal hava det herlegt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Den rettferdige set livet til, og ingen legg seg det på hjarta, og hjartevarme menneskje vert rivne burt, men ingen ansar det. For den rettferdige vert riven burt av ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Han gjeng inn til fred; dei kvila på sine lægje dei som hev ferdast beint fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Men de, kom her hit, de trollkjerringsøner, du ætt av horkar og skjøkja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Kven hev de til låtteløgje? Kven geipar de åt, og retter ut tunga? Er ikkje de brots-ungar, ei ljugar-ætt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'De som brenn av lystnad ved eikarne, under kvart eit lauvrikt tre, de som slagtar born i dalarne, i skortor og skard!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Håle steinar i dalen held du deg til, dei, ja dei er din lut. For deim hev du og rent drykkoffer ut og bore grjonoffer fram. Skulde eg vera nøgd med det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'På kvart eit høgrise fjell reidde du lega di; der og steig du upp og ofra slagtoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Og bakum døri og dørskia sette du ditt minnesmerke, du snudde ryggen til meg, klædde av deg og steig upp og laga di lega til, du tinga med deim, lika å liggja med deim, såg deira skam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Du drog til kongen med olje, med mykje kryddesalve, du sende dine bod langt burt, steig ned til helheim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Um du enn vart trøytt på den lange ferdi, so sagde du ikkje: «Eg gjev meg yver!» Du samla atter di kraft, difor vart du ikkje veik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Kven var du rædd og ottast, sidan du var so utru og ikkje tenkte på meg og ikkje brydde deg um meg? Er det ikkje so: Eg hev tagt i lange tider, difor ottast du ikkje meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Eg vil forkynna di rettferd og dine verk, dei kann ikkje hjelpa deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Når du skrik, so lat avgudsflokken din berga deg! Nei, ein vind skal føykja deim alle burt, ei vindgufs taka deim med seg. Men den som flyr til meg, skal erva landet og få til eiga mitt heilage berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Og det skal verta sagt: «Brøyt, brøyt, jamna veg, tak kvar støytestein burt frå vegen åt mitt folk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'For so segjer han som er høgt upphøgd, han som trunar æveleg og heiter «Heilag»: I det høge og heilage bur eg, og hjå den som er broten og nedbøygd i åndi, for eg vil vekkja åndi til liv hjå dei bøygde, og hjarta til liv hjå dei brotne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'For eg trættar ikkje til æveleg tid, og er ikkje stødt og stendigt harm, for då laut åndi ormegtast for meg, dei sjæler som eg hev skapt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Eg harmast for hans girugsskapssynd, eg slo han og løynde meg i min harm, han fylgde i fråfall sin hjartans veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Hans vegar hev eg sett, men no vil eg lækja honom, eg vil leida honom og gjeva honom og hans syrgjande trøyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Herren skaper frukt av lippor fred, fred for fjerr og nær, segjer Herren, og eg vil lækja honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Men dei gudlause er som det bårande havet, det kann ikkje halda seg stilt, og bylgjorne rotar upp søyla og skarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Dei gudlause hev ingen fred, segjer min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Ropa av full hals, ikkje spar! Lyft di røyst som ein lur! Forkynn mitt folk deira brot, og Jakobs hus deira synder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Meg spør dei dag for dag, mine vegar vil dei vita, som eit folk som hev livt i rettferd og ei vendt seg frå sin Guds rett, krev dei av meg rettferdige domar, dei vil at Gud skal koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '«Kvi fastar me, og du ser det ikkje? Kvi spekjer me oss, og du agtar’kje på det?» - Jau, på fastedagen finn de forretning og driv til arbeid alle dykkar folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Sjå, de fastar med kiv og strid, med hogg og slag av gudlause nevar, ikkje fastar de i dag, so røysti dykkar kann høyrast i det høge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Er det ei faste eg likar, ein dag då menneskja spekjer seg? Å bøygja hovudet som eit sev, å reider seg seng i sekk og oska - kallar du det ei faste, og ein dag som er Herren til hugnad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Er ikkje det ei faste eg likar, urettferdige lekkjor løysa, sprengja bandi på oket, gjeva dei nedtyngde fridom, og knekkja kvart eit ok?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Ja, at du bryt ditt brød åt den svoltne, tek heimlause stakarar til deg, at du klæder den nakne du ser, og ei dreg deg burt frå ditt kjøt og blod?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Då skal ljoset ditt renna som morgonroden, og din lækjedom koma brått, og di rettferd skal ganga fyre deg, og Herrens herlegdom sist i ferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Då svarar Herren når du kallar, når du ropar, segjer han: «Sjå, her er eg!» Fær du burt ifrå deg tyngjing med ok, sluttar å peika med fingen’ og tala vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'og gjev den hungrige etter din hug og mettar ei nedbøygd sjæl, då skal ljoset ditt stråla i myrkret, og di natt skal verta som middag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Då skal Herren leida deg alltid, han skal metta di sjæl i øydemarker, han skal styrkja beini dine, og du vert som ein velvatna hage, som ei rennande kjelda der vatnet aldri tryt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Og dine søner skal byggja gamle grushaugar upp att, du skal reisa upp tufter som lenge låg i øyde, og dei skal kalla deg «Murbrot-bøtar», «vegnybyggjar til busetjing».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Held du foten din att frå kviledagen, so du ei driv ditt yrke på min heilagdag, kallar du kviledagen «ei lyst», Herrens heilagdag «høgvyrd», ærar du honom og held deg frå dine tiltak, ikkje driv med ditt yrke eller prat -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'då skal du frygda deg i Herren, yver haugarne i landet let eg deg fara og let deg njota arven åt Jakob, far din; for Herrens munn hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Sjå, Herrens hand er ikkje so stutt, at han ikkje kann frelsa, og øyra hans er ikkje so tunghøyrt, at det ikkje kann høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Men skuldi dykkar er det som skil millom dykk og dykkar Gud, og synderne dykkar hev dult hans åsyn for dykk, so han ikkje høyrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'For henderne dykkar er sulka med blod, og fingrarne dykkar med misgjerd; lipporne dykkar talar lygn, tunga mullar på vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Ingen ropar til doms for rettferd, ingen hev ærleg rettargang. Dei lit på fåfengd og talar fals, umhender med ulukka føder dei tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Orme-egg klekkjer dei ut, og kongurvev vev dei; den som et deira egg, lyt døy, og krasar du eit, kjem det fram ein orm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Deira vevnad vert aldri til klæde, ein kann ikkje hylja seg i deira verk; deira verk er vondskaps verk, og valdsverk er i deira hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Deira føter er snare til vondt og snøgge til å renna ut skuldlaust blod, deira tankar er vondskaps tankar, det er vald og uferd kvar dei fer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Fredsveg kjenner dei ikkje, det finst ingen rett i deira spor. Dei fer på krokute stigar, kvar som fer soleis, veit ikkje av fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Difor er retten langt burte frå oss, og rettferd vil ikkje koma til oss; me ventar på ljos, og so finn me myrker - på solskin, men ferdast i skugge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Me trivlar som blinde langs vegen, me trivlar som folk utan augo; midt på dagen me snåvar som i skumingi, millom friske er me som døyande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Me gryler alle som bjørnar, og som duvor me sukkar; me ventar på retten, men ikkje han kjem, på frelsa, men ho er langt burte frå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'For synderne våre mot deg er mange, og våre misgjerningar vitnar imot oss; ja, synderne våre hev me i minne, og våre misgjerningar veit me um:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Me hev falle ifrå og neitta Herren, me hev gjenge burt frå vår Gud; me hev tala um trælking og fråfall, hev teke upp og sagt ut or hjarta ljugarord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Retten vert undantrengd, og rettferdi stend langt burte; for sanning hev snåva på tinget, og det rette vinn ikkje fram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'og sanningi vart burte, den som held seg frå vondt, vert plundra. Og Herren såg det og harmast for det ikkje fanst nokon rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Han såg at det ingen fanst, og han undrast at ingen greip inn. Då hjelpte honom hans arm, og hans rettferd var honom til studnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Han tok rettferd på seg til brynja og frelse-hjelm på sitt hovud, hemn-klæde tok han til klædnad, sveipte um seg brennhug til kåpa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Han gjev deim att etter gjerningar, harm yver sine motmenner, attergjeld for sine fiendar, ja, øylandi skal få det att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Og i vesterland skal dei ottast Herrens namn og i austerland hans herlegdom, for han kjem som ein innestengd foss som Herrens storm driv fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Og han kjem som utløysar for Sion, og for deim som snur seg frå synd i Jakob, so er Herrens ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Og dette er den pakt som eg på mi sida gjer med deim, segjer Herren: Min ande som er yver deg, og mine ord som eg hev lagt deg i munnen, dei skal ikkje vika frå din munn, og ikkje frå munnen åt borni dine, og ikkje heller frå munnen åt barneborni dine, segjer Herren, frå no og i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Statt upp, vert ljos! for ljoset ditt kjem, og Herrens herlegdom renn upp yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Sjå, myrker ligg yver jordi, og skydimma yver folki, men yver deg renn Herren upp, yver deg hans herlegdom syner seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Og folkeslag fer til ditt ljos, og kongar til din strålande glans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Lyft augo upp, og sjå deg ikring! Dei samlar seg alle, dei kjem til deg. Dine søner kjem langt burtanfrå, dine døtter vert borne på armen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Då skal du sjå det og stråla av gleda, og hjarta skal bivra og vida seg ut; for havsens rikdom skal venda seg til deg, folke-midelen koma til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Mengdi av kamelar skal dekkja deg, kamelfolar frå Midjan og Efa; alle skal dei koma frå Saba; gull og røykjelse skal dei bera, og forkynna Herrens pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Alle sauer frå Kedar skal samlast til deg, verar frå Nebajot tena deg, dei stig som eg vil på mitt altar, og mitt herlege hus vil eg herleggjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kven er det som flyg som skyer, som duvor til sine hus?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'For øyland ventar på meg, og fremst gjeng Tarsis-skipi med borni dine langt burtanfrå, deira sylv og gull kjem med deim, for namnet åt Herren din Gud, for Israels Heilage, for han vil gjera deg herleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Utlendingar skal dine murar byggja, deira kongar skal tena deg; for i min harm hev eg slege deg, men i min nåde miskunnar eg deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Dine portar skal stødt standa opne, korkje dag eller natt skal dei stengjast, so eiga åt folki kann førast til deg, og kongarne deira i sigerferdi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'For det folk og det rike som ikkje vil tena deg, skal ganga til grunns, og folki verta reint tynte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Libanons herlegdom skal koma til deg, cypressa, alm og gran i saman, til å pryda min heilagdoms stad, eg vil heilaggjera min fotstad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Bøygde kjem til deg borni åt trælkaran’ dine, dei som vanvyrde deg, skal kasta seg ned for føterne dine, og dei skal kalla deg «Herrens by», «Sion åt Israels Heilage».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Medan du fyrr var forlati og hata, og ingi ferdsla hadde, vil eg gjera deg æveleg gild, til ei gleda frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Du skal suga mjølk ifrå folki, ja, kongebrjost skal du suga, du skal merka at Herren, eg, er din frelsar, og Jakobs Velduge din utløysar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Gull let eg koma i staden for kopar, sylv let eg koma i staden for jarn, kopar i staden for tre, og jarn i staden for steinar, fred set eg til styremagt yver deg, og rettferd til futar åt deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Ikkje meir skal ein høyra um vald i ditt land, avøyding og snøyding innum grensorne dine. Du skal kalla frelsa murarne dine, og lovsong portarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Ikkje skal soli lenger vera deg til ljos um dagen, og ikkje skal månen skina og lysa for deg; men Herren skal vera deg ævelegt ljos, og din Gud vera din herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ikkje lenger skal soli di glada, og ikkje månen din missa sin glans; for Herren skal vera deg ævelegt ljos, dine syrgjedagar er enda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Og ditt folk, dei er alle rettferdige, æveleg skal dei landet eiga, dei er renningen av mi planting, verket av mine hender til mi æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Den minste skal verta til tusund, den ringaste til eit veldugt folk. Eg er Herren, i si tid set eg det brått i verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Herrens, Herrens ande er yver meg, for Herren hev salva meg til å bera fagnadbod til dei smålåtne, han hev sendt meg til å binda um dei hugbrotne, til å ropa ut fridom for fangar, og for dei bundne utløysing,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'ropa ut eit nåde-år for Herren og ein hemnedag frå vår Gud, til å trøysta alle dei syrgjande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'til å gjeva dei syrgjande i Sion høgtidskruna for syrgjebunad, gledeolje i staden for sorg, lovsongs-klæde for vanmoda ånd, og dei skal heita rettferds eiker, Herrens plantning til herleggjering.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Dei skal byggja upp att gamle grushaugar, reisa upp att ruinar frå federne, nya upp att nedbrotne byar, øydegarder frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Framande skal gjæta smalen dykkar, utlendingar dyrka åt dykk både åker og vingard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Men de skal heita Guds prestar, tenarar åt vår Gud skal dei kalla dykk; folke-eiga skal de njota, og deira herlegdom skal de få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'For dykkar skam fær de dobbelt att, dei som leid skjemsla, skal prisa sin lut. Difor fær dei dobbel lut i sitt land, æveleg gleda skal dei få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'For eg, Herren, elskar retten, eg hatar urett ran, og trufast gjev eg deim løni deira og gjer med deim ei æveleg pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Namngjeti vert deira ætt millom folki og avkjømet deira bland tjoderne; alle som ser deim, skal kjenna deim, at dei er ei ætt som Herren hev signa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Eg gled meg storleg i Herren, sjæli mi fegnast i min Gud. For han hev klædt meg i frelse-klæde, sveipt meg i rettferds-kåpa, som ein brudgom seg pryder med prestehuva og ei brur tek på seg sin prydnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'For som jordi sin grode let renna, og hagen sitt sæde let veksa, so let Herren, Herren rettferd renna og lovsong for alle folks åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'For Sions skuld vil eg ikkje tegja; for Jerusalems skuld vil eg ei vera still, fyrr hennar rettferd kjem fram som solskin og hennar frelsa som brennande kyndel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Og folki skal sjå di rettferd og alle kongar din herlegdom, dei skal kalla deg med eit nytt namn, som Herrens munn skal nemna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Du skal vera ei herleg krans i handi åt Herren, ei kongekruna i handi åt din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Du skal ikkje heita «den forlatne» lenger, og ditt land ikkje heita «øydeland», men du skal heita «ho eg hev huglagt», og landet ditt «egtevivet»; for Herren hev hugnad i deg, og landet ditt skal verta egtevigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Som ein ungdom giftar ei gjenta, so skal dine søner deg gifta, og som brudgomen gled seg i bruri, skal din Gud gleda seg i deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'På murarne dine, Jerusalem, hev eg vaktmenner sett; heile dagen og heile natti skal dei aldri tegja. De som maner på Herren, unn dykk ingi ro!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Og gjev ikkje honom ro fyrr han grunnar Jerusalem og let det verta til emne for lovsong på jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Herren hev svore ved si høgre hand og ved sin velduge arm: Eg skal ikkje lenger gjeva ditt korn til føda for fiendarn’ dine, og ei skal utlendingar drikka di saft, som du hev havt møda med;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'nei, dei som hausta, skal eta og prisa Herren, og dei som sankar druvorne, skal drikka i mine heilage tun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Drag ut, drag ut gjenom portarne, ryd vegen for folket, brøyt, brøyt brauti, reinsa burt steinen, lyft eit merke upp yver folki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Høyr, Herren let det ljoma til heimsens ende: Seg til Sions dotter: Sjå, di frelsa kjem! Sjå, si løn hev han med seg, og hans vederlag gjeng fyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Og dei skal kallast «det heilage folket», «Herrens løyste»; og du sjølv skal heita «den søkte», «byen som ikkje er aud».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kven er dette som kjem frå Edom, frå Bosra i raude klæde, so brikjen i bunaden sin, so staut i si store kraft? «Det er eg, eg som talar rettferd, som er megtig til å frelsa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Kvifor er bunaden din so raud, og klædi som trødde du vinpersa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '«Eg trødde persa åleine, og ingen av folki var med meg. So trødde eg på deim i vreide og trakka deim sund i min harm. Då skvatt deira blod på klædi mine, og eg sulka heile min klædnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'For ein hemnedag var i min hug, og mitt utløysingsår var kome.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Eg såg meg um, det var ingen som hjelpte, og eg undrast på at ingen meg studde, då hjelpte meg min arm, og min harm var meg til studnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'og eg trakka ned folkeslag i min vreide og gjorde deim drukne i min harm, deira blod let eg renna på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Herrens miskunn vil eg prisa, Herrens storverk, etter alt det Herren hev gjort oss og hans store godleik mot Israels hus, som han viste deim i si miskunn og sin store nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Han sagde: «Dei er mitt folk, trufaste borni.» Og han vart deira frelsar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'I all deira trengsla var ingi trengsla, hans åsyns engel frelste deim; i sin kjærleik og si milda han løyste deim ut, han tok deim upp, og han bar deim alle fordoms dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Men dei var stride og harma hans heilage ande, då gjordest han um til fiend’, sjølv stridde han mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Då fordoms dagar då tenkte hans folk på Moses: Kvar er han som deim førde or havet med sin buskaps hyrding? Kvar er han som gav deim i barmen sin heilage ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'som let fara ved Mose sida sin herlege arm, som kløyvde vatnet framfor deim, so han skapte seg eit æveleg namn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'han som førde deim gjenom djupet som ein hest yver heidi, so ikkje dei snåva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Liksom buskapen gjeng ned i dalen, førde Herrens ande deim til ro; ja, so hev du ført ditt folk og skapt deg eit herleg namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Skoda ned frå himmelen, sjå, frå din heilage, herlege bustad! Kvar er din brennhug, di kraft? Di rørsla i barmen, di miskunn held seg att imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'For du er vår fader, for Abraham veit ikkje um oss, og Israel kjenner oss ikkje. Men du, Herre, er vår fader, «Vår utløysar» du heiter frå gamalt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Kvi let du oss vildra, Herre, frå dine vegar? Kvi gjer du vårt hjarta hardt, so me ikkje ottast deg? Vend att for dine tenarar skuld, for ætterne i din arvlut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Eit lite bil hev ditt heilage folk havt si eiga, so trakka våre uvener ned din heilagdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Det hev vorte med oss som du aldri hadde rådt yver oss, som ditt namn hadde ei vore nemnt yver oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Gjev du reiv himmelen sund og steig ned, so fjelli skalv for di åsyn, som elden fatar i risved, elden set vatnet i kok, - til å kunngjera namnet ditt for dine motmenn, so folki laut skjelva for di åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'når du gjorde skræmeverk, som me ikkje venta - å, steig du ned, so fjelli skalv for di åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Aldri hev nokon spurt eller høyrt, aldri hev auga set nokon annan gud enn du gjera soleis med deim som ventar på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Du kjem imot dei som gjer rettferd med gleda, dei som kjem deg i hug på vegarne dine. Sjå, du vart harm, og me synda; so var det med oss frå gamalt, kann me verta frelste?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Me vart alle i hop som ein urein, og all vår rettferd som eit tilsulka plagg, som lauvet visna me alle saman, og våre skuld bles oss burt som vinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Det var ingen som kallar på namnet ditt, som manna seg upp til å gripa deg; for du hadde løynt di åsyn for oss og late oss skjelva under vår skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Men no, Herre, er du vår fader; me er leiret og du vår formar, eit verk av di hand er me alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Herre, ver ikkje so ovleg harm, og tenk ikkje ævleg på skuldi. Sjå no på me alle er ditt folk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Dine heilage byar vart øydemark, Sion vart til ei øydemark, Jerusalem til ei audn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Vårt heilage hus, det herlege, der federne våre deg lova, hev vorte uppbrent med eld, og all vår hugnad hev vorte grushaugar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Kann du halda deg att med alt dette, Herre? Vil du tegja og trykkja oss so tungt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Eg baud meg fram der ingen spurde, eg var å finna der ingen søkte meg; eg sagde: «Her er eg, her er eg!» Til eit folk som ei bar mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Eg rette all dagen ut mine hender til eit tråssugt folk, som fer den vonde vegen etter sine eigne tankar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'til eit folk som sårar meg alltid midt i syni, som ofrar i hagarne, kveikjer offereld på tiglstein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'som set seg ned i graver, og nattar i løyndarhol, som et svinekjøt, hev ufyseleg mat i skålerne sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'som segjer: «Haldt deg undan! Ikkje rør meg, for eg er heilag for deg!» Dei folk er som røyk i nasen min, ein eld som logar all dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Sjå, det stend skrive for augo mine: Eg vil ikkje tegja fyrr eg gjev att, ja gjev deim att i fanget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'både for dykkar eigne brot, segjer Herren, og broti åt federne dykkar, at dei offereld kveikte på bergi og svivyrde meg på haugarne; fyrst vil eg mæla upp løni deira og gjeva deim upp i fanget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'So segjer Herren: Liksom dei segjer når det finst saft i druva: «Skamfar ho ikkje, for det er signing i henne!» So gjer eg for mine tenarar skuld, eg skal ikkje tyna alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Men let avkjøme koma frå Jakob, frå Juda ein erving til fjelli mine, mine utvalde skal erva landet, og der skal mine tenarar bu.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Og Saron skal verta til saue-beite og Akorsdalen til læger for fe, til gagn for mitt folk som søkjer meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Men de som gjeng burt ifrå Herren, de som gløymer mitt heilage fjell, de som dukar bord for Gad og blandar drykk for Meni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'dykkar lagnad skal vera sverdet, de skal alle dykk bøygja til slagting, for de svara ei då eg ropa, og høyrde ei då eg tala, men gjorde det vonde i mine augo, og valde det som eg ikkje lika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Difor segjer Herren, Herren so: Sjå, tenaran’ mine skal eta, men de skal svelta; sjå, tenaran’ mine skal drikka, men de skal tyrsta; sjå, tenaran’ mine skal fegnast, men de skal skjemmast;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'sjå, tenaran’ mine skal jubla av hjartans lyst, men de skal skrika av hjarteverk, og hugbrotne skal de hyla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Dykkar namn skal de lata etter til ein eid for mine utvalde. «So drepe deg Herren, Herren!» Men tenaran sine skal han gjeva eit anna namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Den som signar seg i landet, skal signa seg med truskaps Gud, og den som sver i landet, skal sverja ved truskaps Gud, for dei fyrre trengslor er gløymde og løynde for augo mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'For sjå, eg skaper ein ny himmel og ei ny jord, det gamle skal ikkje hugsast meir og ikkje renna nokon i hugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Nei, fegnast og frygdast til æveleg tid for det som eg skaper! For Jerusalem skaper eg um til frygd og folket til fagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Og eg vil frygda meg yver Jerusalem og fegnast yver mitt folk, ingen gråt skal meir høyrast der eller klagerop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Det skal ikkje lenger finnast der eit barn som berre liver nokre dagar, eller ein gamall mann som ikkje fyller dagetalet sitt. Nei, den som døyr ung, skal døy hundrad år gamall, og den som ikkje når hundrad år, skal gjelda for å vera forbanna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Dei husi dei byggjar, skal dei sjølv få bu i, og dei vinhagarne dei plantar, skal dei sjølv eta frukti av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ikkje skal dei byggja og ein annan bu, ikkje skal dei planta og ein annan eta; for folket mitt skal nå same alder som treet, og mine utvalde skal få njota det dei sjølv hev verka med sine eigne hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Dei skal ikkje stræva til fåfengs og ikkje få born som brått skal døy; for dei er Herrens velsigna ætt, og sitt avkjøme hev dei hjå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Og det skal vera so, at fyrr dei ropar, vil eg svara, og medan dei endå talar, vil eg høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Ulv og lamb skal beita i saman, og løva skal eta halm som uksen, og ormen skal hava mold til mat. Ingen skal gjera vondt eller ugagn på heile mitt heilage fjell, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'So segjer Herren: Himmelen er min stol, og jordi mi fotskor. Kva hus vil de då byggja åt meg, og kvar skulde vera min kvilestad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Alt dette skapte eg med mi hand, og soleis vart alt dette til, segjer Herren. Den som eg vil sjå til, er den arme og hugbrotne, og den som skjelv for mitt ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Slagta ein stut er som drep ein mann, ofra eit lamb som å tyna ein hund, ofra grjonoffer som ofra svineblod, brenna røykjelse som hylla ein avgud. Som dei hev valt sine eigne vegar, og dei likar si ufysna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'so vil eg og velja deira vanlukka og føra yver deim det som dei ræddast, for di ingen svara då eg ropa, og dei høyrde ikkje då eg tala, men gjorde det vonde i mine augo og valde det som eg ikkje lika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Høyr då Herrens ord, de som skjelv for hans ord! Dykkar brøder som hatar dykk, segjer, dei som støyter dykk burt for mitt namn skuld: «Lat Herren syna seg herleg, so me kan sjå dykkar gleda!» Men dei skal verta til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Høyr gnyen frå byen! Høyr omen frå templet! Høyr, Herren gjev sine fiendar lika for deira verk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Fyrr ho vert barnsjuk, hev ho født, fyrr riderne kjem, hev ho fenge ein gut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kven hev høyrt um slikt? Kven hev sovore set? Kjem eit land til verdi på ein einaste dag? Kann eit folk verta født med ein einaste gong? For Sion vart barnsjuk og fødde med same sønerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Skuld’ eg opna morsliv og ei gjeva føding? segjer Herren. Eller gjeva føding, og so halda fosteret att? segjer din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Gled dykk med Jerusalem og jubla yver henne, alle som hev henne kjær! Fegnast storleg med henne, alle de som ber sorg for henne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'So kann de suga og mettast av hennar hugsvalande barm, so de kann drikka og kveikjast av hennar herlege rikdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'For so segjer Herren: Sjå, eg leider fred til henne som ei elv, og herlegdomen hjå folki som ein fløymande bekk, og de skal få suga; dei skal bera dykk på armen, setja dykk på fanget og kjæla med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Som mori trøystar sin son, soleis skal eg trøysta dykk, ja, i Jerusalem skal de få trøyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'De skal sjå det, og hjarta dykkar skal fegnast, og beini dykkar skal friskna som graset, og merkast skal Herrens hand hjå hans tenarar, men hans harm er yver hans fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'For sjå, Herren kjem i eld, og hans vogner er som ein storm, hans vreide skal råka med brennande harm, hans trugsmål med logande eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'For Herren held dom med eld, og med sverdet sitt yver alt kjøt, og mange vert dei som Herren hev drepe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Dei som helgar og reinsar seg for hagarne etter ein som er midt millom deim, dei som svinekjøt et og ufysne dyr, ja myser, dei skal tynast alle i hop, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Eg kjenner deira gjerningar og deira tankar. Den tid kjem då eg samlar alle folk og tungemål, og dei skal koma og sjå min herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Eg vil gjera eit teikn imillom deim, og nokre av deim som vert berga, vil eg senda til heidningfolki, til Tarsis og Pul og Lud, bogeskyttarane, til Tubal og Javan, til øylandi langt burte, som ikkje hev høyrt gjetordet um meg og ikkje hev set min herlegdom, og dei skal kunngjera min herlegdom millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Og dei skal koma med alle brørne dykkar frå alle folkeslagi til offergåva åt Herren, på hesteryggen, på vogner, i berestolar, på muldyr og på kamelar, upp til mitt heilage fjell i Jerusalem, segjer Herren, liksom Israels-borni kjem med offergåva i reine skåler til Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Og jamvel av deim vil eg taka ut levitiske prestar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'For liksom den nye himmelen og den nye jordi som eg skaper, skal standa for mi åsyn, segjer Herren, so skal og dykkar ætt og dykkar namn standa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Kvar månad på nymånedagen og kvar vika på kviledagen skal alt kjøt koma og kasta seg ned for mi åsyn, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Og dei skal ganga ut og sjå på liki åt dei menner som hev falle frå meg; for makken deira skal ikkje dauda, og elden deira skal ikkje slokna, og dei skal vera ei gruv for alt kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Ord av Jeremia Hilkiason, ein av prestarne i Anatot i Benjaminslandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Til honom kom Herrens ord i dei dagarne då Josia Amonsson var konge i Juda, i det trettande styringsåret hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'likeins i dei dagarne då Jojakim Josiason var konge i Juda alt til slutten av det ellevte styringsåret åt Sidkia Josiason, Juda-kongen, alt til burtføringi av Jerusalems-buarne i den femte månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Herrens ord kom då til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Fyrr eg skapte deg i morsliv, kjende eg deg, og fyrr du kom ut or moderfang, helga eg deg; til profet åt folki sette eg deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Men eg sagde: «Å, Herre, Herre! Sjå, eg kann ikkje med å tala, for eg er so ung.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Då sagde Herren med meg: Seg ikkje: «Eg er so ung,» men til alle som eg sender deg til, skal du ganga, og alt det eg byd deg, skal du tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ikkje ottast deim! For eg er med deg til å berga deg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Og Herren rette ut si hand og tok på munnen min. So sagde Herren med meg: Sjå, eg hev lagt ordi mine i din munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Sjå, eg hev i dag sett deg yver folki og yver kongeriki til å ryskja upp og riva ned, til å tyna og brjota ned, til å byggja og til å planta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Og Herrens ord kom til meg; han sagde: Kva ser du, Jeremia? Og eg svara: «Ein stav av vake-treet ser eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Og Herren sagde med meg: Gløgt såg du no, for vaka vil eg yver mitt ord til å fullføra det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'So kom Herrens ord til meg andre gongen; han sagde: Kva ser du? Og eg svara: «Ei sjodande gryta ser eg, og nordantil snur ho seg hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Då sagde Herren med meg: Frå nord kjem ulukka sendande yver alle som bur i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'For sjå, eg kallar på kvar ei ætt i riki der nord, segjer Herren. Og dei skal koma og setja kvar sin stol attmed inngangen til portarne i Jerusalem og mot alle murarne um det rundt ikring og mot alle byarne i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Og eg vil segja mine domar yver deim for alt deira illverk, at dei vende seg frå meg og brende røykjelse åt andre gudar og tilbad dei verk deira hender gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Men du - gyrd dine lender og statt upp og tala til deim alt det som eg byd deg. Ikkje ræddast for deim, so ikkje eg skal gjera deg rædd deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Og eg, sjå eg hev i dag gjort deg til ei fast borg og til ein jarnstolpe og til ein koparmur mot alt landet: mot kongarne i Juda, mot hovdingarne, mot prestarne og mot lyden i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Dei skal strida mot deg og ikkje vinna på deg. For eg er med deg, segjer Herren, og skal berga deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Gakk av stad og ropa ut for Jerusalems øyro: So segjer Herren: Eg kjem deg i hug for din elskhug i din ungdom, din kjærleik i dine festarmålsdagar, kor du fylgde meg i øydemarki, i eit land der dei inkje sår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Heilagt var Israel for Herren, hans fyrstegrøda. Alle som vilde eta det, laut bøta, ulukka kom på deim, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Høyr Herrens ord, Jakobs hus, og alle ætter i Israels hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'So segjer Herren: Kva hev federne dykkar funne rangt hjå meg, sidan dei hadde seg undan meg og ferdast etter fåfenglege gudar og vart fåfenglege?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Og dei sagde ikkje: «Kvar er Herren som førde oss ut or Egyptarlandet, som leidde oss i øydemarki, i eit land med heidar og klufter, i eit land med turk og daudeskuggar, i eit land der ingen mann hev fare, og der inkje menneskje hev butt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Og eg let dykk koma inn i eit grøderikt land, so de fekk eta frukti og dei gode ting der. Men då de kom dit inn, sulka de landet mitt og gjorde odelen min til ein styggedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Prestane sagde ikkje: «Kvar er Herren?» Og dei som handsama lovi, kjende meg ikkje, og hyrdingarne fall ifrå meg. Og profetarne spådde ved Ba’al, og etter gagnlause gudar gjekk dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Difor vil eg framleides trætta med dykk, segjer Herren; og med barneborni dykkar vil eg trætta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'For far yver til Kittim-øyarne og sjå, og send bod til Kedar og høyr vel etter, og sjå um slikt er hendt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Hev noko folk bytt burt gudar, endå dei ikkje er gudar? Men mitt folk hev bytt sin herlegdom burt i gagnløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Vert forstøkte, de himlar, yver slikt, og tak fæla og stivna, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'For tvo illverk hev mitt folk gjort: dei vende seg frå meg, kjelda med livande vatn, og grov seg brunnar, leke brunnar som ikkje held vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Er Israel ein træl? Er han ein træleson? Kvi er han vorten eit herfang?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Ungløvor bura imot honom, let ljoma si røyst. Og dei gjorde hans land til ei audn, hans byar vart brende, ingen bur der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Jamvel Nofs-sønerne og Tahpanhes hev gjort deg snaud i kruna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Hev du ikkje sjølv valda deg dette, med di du vende deg frå Herren, din Gud, då han vilde leida deg på vegen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Og no, kva hev du med Egyptarvegen å gjera for å drikka vatn or Sihor? Og kva hev du med Assur-vegen å gjera for å drikka vatn or Elvi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Din vondskap agar deg, og dine fråfall refser deg: Kjenn då og sjå at det er vondt og beiskt at du vende deg frå Herren, din Gud, og at du ikkje hev otte for meg, segjer Herren, Allhers-Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'For alt longe sidan braut du sund ditt ok, sleit sund dine band og sagde: «Eg vil ikkje tena.» For på kvar ein høg haug og under kvart eit grønt tre lagde du deg ned og dreiv hor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Og eg hadde då planta deg eit godt vintre, alt igjenom av egte sæde; kor kunde du då verta umskapt for meg til villvin av framandt slag?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'For um du so vilde två deg i lut og bruka mykje såpa, so vilde di misgjerning endå vera urein for mi åsyn, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kor kann du segja: «Utsulka er eg ikkje, etter Ba’alarne hev eg ikkje gjenge?» Sjå på vegen din i dalen! Skyna kva du hev gjort, du lettføtte kamelfylja som løyp til og frå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Som ei vill-asna, van med øydemarki, syp ho etter anden i si trå. Brund-giren hennar - kven kann døyva den? Dei som leitar etter henne, tarv ikkje renna seg trøytte; i hennar månad finn dei henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Vara foten din so han ikkje vert berr, og strupen din so du ikkje vert tyrst! Men du segjer: «Rådlaust! Nei, for eg elskar framande,» og etter deim vil eg ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Liksom tjuven må skjemmast når han vert teken, soleis må Israels hus skjemmast, dei sjølve, kongarne deira, hovdingarne deira og prestarne deira og profetarne deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'dei som segjer til treet: «Du er min far,» og til steinen: «Du hev født meg;» for dei hev snutt ryggen til meg og ikkje andlitet. Men når dei er i naud, då ropar dei: «Ris upp og hjelp oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Kvar er då gudarne dine som du gjorde deg? Lat deim risa upp um dei kann hjelpa deg når du er i naud! For gudarne dine, Juda, er vortne likso mange som byarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Kvi trætter de med meg? Alle er de falne frå meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Til fånyttes slo eg borni dykkar; age tok dei ikkje. Som ei herjande løva gløypte dykkar sverd profetarne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Du ætt, gjev gaum etter Herrens ord! Hev eg vore ei øydemark for Israel eller eit stum-myrkt land? Kvi segjer då lyden min: «Me gjeng lause, me vil aldri meir koma til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Gløymer ei møy sin prydnad, ei brur sitt belte? Men lyden min hev gløymt meg i uteljande dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Kor vel du veit å leggja vegen din til å leita etter elskhug! Difor vandest du og på dine vegar til det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Ja, på kjolesnipparne finst det blod av skuldlause armingar: ikkje kom du på deim i innbrot; men av di at alt dette er funne hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Endå segjer du: «Eg er skuldlaus; visseleg hev vreiden hans vendt seg frå meg.» Sjå, eg vil ganga til doms med deg av di at du segjer: «Eg hev ikkje synda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Kvi fer du so langt burt i ei onnor leid? Med Egyptarland og skal du verta til skammar, likeins som du vart til skammar med Assyria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Derifrå med skal du ganga ut med henderne yver ditt hovud. For Herren hev støytt burt deim du leit, og du fær ingi lukka med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Dei segjer: Når ein mann sender frå seg kona si, og ho fer frå honom og gifter seg med ein annan mann, kann han då atter koma tilbake til henne? Vilde ikkje det landet verta vanhelga? Med du hev drive hor med mange vener - og so skulde du koma tilbake til meg! segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Lyft upp augo dine til snaudfjellkollarne og sjå: kvar var det du ikkje vart skjemd? Frammed vegarne sat du og stunda etter deim likeins som ein arab i øydemark, og du vanhelga landet med din horelivnad og vondskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'So vart då regnskurerne haldne att; og vårregn kom det ikkje. Men di panna var som på ei horkona: det beid ikkje skam i deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Hev du ikkje nett no kalla på meg og sagt: «Min fader!» «Min ungdomsven er du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, '«Kann han vilja gøyma på vreide æveleg og harmast for ævelengdi?» Sjå, det tala du, men gjorde det vonde og kunde det med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Og Herren sagde med meg i kong Josias dagar: Hev du set kva ho hev gjort, den utrue kvinna Israel? Ho gjekk upp på kvart eit høgt fjell og inn under kvart eit grønt tre og dreiv hor der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Og eg sagde: Etter ho hev gjort alt dette, vil ho snu attende til meg, men ho snudde ikkje. Og det såg den utrue kvinna, hennar syster Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Og eg såg at endå eg hadde sendt frå meg Israel, den fråfalne, og gjeve henne hennar skilsmålsbrev av di ho hadde drive hor, so ottast ikkje hennar utrue syster Juda like vel, men gjekk av stad og dreiv hor ho med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Og med sin ubljuge lauslivnad vanhelga ho landet, og ho dreiv hor med stein og med tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Og med alt dette hev hennar utrue syster Juda ikkje snutt um til meg av alt sitt hjarta, men berre læst gjera det, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Og Herren sagde med meg: Den fråfalne, Israel, tedde seg rettferdigare enn den utrue, Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Gakk av stad og ropa ut desse ordi mot nord og seg: Snu då um, du frå falne, Israel, segjer Herren. Eg vil ikkje møta deg med harmfullt andlit, for eg er miskunnsam, segjer Herren, og gøymer ikkje æveleg på vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Berre kannast ved di misgjerning, at du fall ifrå Herren, din Gud, og på ymse leider for etter framande gudar inn under kvart eit grønt tre, men på mi røyst hev de ikkje lydt, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Snu um, de fråfalne born, segjer Herren, for eg er herren dykkar. Og eg vil taka dykk, ein or ein by og tvo av ei ætt, og lata dykk koma til Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Og eg vil gjeva dykk hyrdingar etter mitt hjarta, og dei skal gjæta dykk med vit og skynsemd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Og når de aukar og veks i landet i dei dagarne, segjer Herren, då skal dei aldri meir tala um Herrens sambandskista, ja, ikkje koma henne i hug di heller og ikkje minnast henne og ikkje sakna henne, og dei skal ikkje heller meir gjera seg ei slik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'I den tidi skal dei kalla Jerusalem Herrens kongsstol, og alle folk skal samlast dit til Herrens namn, til Jerusalem. Og aldri meir skal dei ferdast etter sitt vonde, harde hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'I dei dagarne skal Juda-huset ganga til Israelshuset, og dei skal koma saman frå Norderlandet til det landet som eg gav federne dykkar til odel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Eg sagde då: «Å, kor høgt eg vilde sessa deg millom borni og gjeva deg eit hugnadlegt land, den herlegaste odel millom folki.» Og eg sagde: «De vil ropa til meg: «Min fader!» og ikkje meir skilja lag med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Men liksom ei kvinna er utru mot venen sin, soleis hev de vore utrue mot meg, du Israels hus, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Ei røyst høyrest på dei snaudfjelli, gråt og bøner frå Israels-borni; for dei hev gjenge på range vegar, dei hev gløymt Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Snu um, de fråfalne born, so skal eg lækja dykk etter dykkar fråfall. Sjå her, me kjem til deg, for du er Herren, vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Sanneleg, til fåfengs var voni til haugarne, ståket på heidarne. Sanneleg, i Herren, vår Gud, er Israels frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Og skjemdar-tinget hev ete upp det federne våre stræva i hop alt frå vår ungdom, deira sauer og kyr, deira søner og døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Lat oss då liggja i vår skjemd, og lat skammi vår breida seg yver oss! For mot Herren, vår Gud, hev me synda, me og federne våre, alt frå ungdom og til denne dag, og me hev ikkje lydt Herren, vår Guds, røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Um du vender um, Israel, segjer Herren, då skal du få venda attende til meg, og um du hev dine styggjor burt frå mi åsyn, skal du ikkje ljota liva i fredløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Og um du sver: «So sant som Herren liver,» i sanning, med rett og rettferd, då skal heidningfolk velsigna seg i honom og rosa seg i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'For so segjer Herren med Juda-mennerne og med Jerusalem: Brjot dykk nybrot, og så ikkje millom klunger!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Umskjer dykk for Herren, og tak burt dykkar hjartans fyrehud, de Juda-menner og Jerusalems-buar, so at harmen min ikkje skal fara ut som eld og brenna so ingen kann sløkkja, for dykkar vonde verk skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Kunngjer i Juda og send bod til Jerusalem og seg: «Blås i lur i landet!» Ropa alt med de vinn, og seg: «Samla dykk og lat oss ganga inn i dei faste borger!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Set upp hermerke burtåt Sion! Fly undan, stana ikkje! For eg let ulukka koma frå nord med stort tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Ei løva hev rise upp or kjørri si, og ein folke-tynar hev teke ut, er faren heimanfrå og vil gjera landet ditt til ei audn; byarne dine vert lagde i øyde so ingen bur der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Gyrd dykk difor i sekk, barma dykk og øya dykk! For Herrens brennande vreide hev ikkje vendt seg frå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Og den dagen, segjer Herren, skal kongen og hovdingarne standa rådlause, prestarne skal ræddast og profetarne verta vitskræmde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Då sagde eg: «Å, Herre, Herre! Ille hev du svike dette folk og Jerusalem då du sagde: «Fred skal de hava» - og no gjeng sverd inn til sjæli.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'I den tidi skal det verta sagt med dette folk og med Jerusalem: Ein glodheit vind frå snaudkollarne i øydemarki kjem imot mitt folks dotter, ikkje til å kasta korn med og ikkje til å dryfta med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Ein vind, sterkare enn til slikt, vil eg lata koma; no vil eg og segja domen mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Sjå, lik skyer kjem han upp farande, og lik eit stormver er hans vogner, fljotare enn ørnar er hans hestar: Usæle me! Det er ute med oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Två vondskapen av ditt hjarta, Jerusalem, so du kann verta frelst. Kor lenge skal dine synduge tankar bu i ditt brjost?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'For ei røyst kjem med tiend frå Dan og med usæle-bod frå Efraimsheidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Lat folki få vita det, sjå til og lat Jerusalem få høyra det; umlægringsmenner kjem frå eit land langt undan og set i og ropar mot byarne i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Likeins som markevaktarar sit dei og gjæter på henne rundt ikring; for mot meg hev ho vore tråssug, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Di åtferd og dine gjerningar hev valda deg dette; dette hev du for vondskapen din, at det er beiskt, at det gjeng alt inn til ditt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Å bringa mi, bringa mi! Eg skjelv av verk, hjarteverk. Mitt hjarta bankar i meg, eg kann ikkje tegja. For lurljom, herrop hev du høyrt, mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Tjon på tjon vert det ropa, for alt landet er i øyde lagt; dåtteleg er tjeldi mine øydelagde, i ein augneblink tjelddukarne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Kor lenge skal eg sjå hermerke, høyra lurljom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'For lyden min er fåvis, meg kjenner dei ikkje; uvituge born er dei, og dei er utan skyn; vise er dei til å gjera vondt, men dei hev ikkje vit på å gjera godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Eg såg jordi, og sjå, ho var aud og øydi, og til himmelen såg eg, og ljoset hans var kvorve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Eg såg fjelli, og sjå, dei bivra, og alle haugarne rugla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Eg såg, og sjå, det fanst ikkje eit menneskje, og alle himmelens fuglar hadde floge burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Eg såg, og sjå, det grøderike landet var ei øydemark, og alle byarne var nedrivne av Herren, av hans brennande harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'For so segjer Herren: Ei audn skal heile landet verta, men reint audt vil eg ikkje gjera det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Difor skal landet syrgja og himmelen der uppe klæda seg i svart, av di eg hev sagt det, tenkt det so, og eg angrar det ikkje og gjer det ikkje um att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'For gnyen av ridarar og bogeskyttarar flyr kvar ein by; dei gjeng inn i skogarne og stig upp på hamrarne. Alle byar er folketome, ingen bur i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Og du, når du vert øydelagd, kva vil du då gjera? Endå um du klæder deg i purpur og pryder deg med gull-prydnad og gjer augo dine store med sminka, so er det fåfengt at du gjer deg fager; dine elskarar vanvyrdar deg, dei stend deg etter livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'For eg høyrer rop nett som av ei kvinna i barnsnaud, naudrop som av kvinna når ho fær fyrste barnet, rop av dotteri Sion. Ho styn, ho retter ut henderne sine: Eie meg! Sjæli mi sig vanmegtig i mordar-vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Gakk kringum i gatorne i Jerusalem, og sjå etter og få vita og leita på torgi um de finn einkvar, um det er nokon som gjer rett, som legg vinn på ærlegdom, so vil eg tilgjeva byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Og endå um dei segjer: «So sant som Herren liver,» so gjer dei rang eid like vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Herre, ser ikkje augo dine etter ærlegdom? Du slo deim, men dei anka seg ikkje, du tynte deim, men dei let seg ikkje aga. Dei gjorde andlitet hardare enn stein, dei vilde ikkje venda um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Då sagde eg: «Dette er berre småfolk; dei er fåvituge, for dei veit ikkje Herrens veg, sin Guds rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'No vil eg ganga til storfolket og tala med deim, for dei veit Herrens veg, sin Guds rett.» Men nettupp dei, alle saman, hev brote sund oket, slite av seg bandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Difor skal løva frå skogen slå deim, vargen frå villmarkerne tyna deim. Panteren ligg og gjæter attmed byarne deira; kvar den som gjeng ut or deim, vert sundriven. For mange er deira forbrot, mangfaldige deira fråfall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kvi skulde då eg gjeva deg til? Borni dine hev vendt seg frå meg og svore ved slikt som ikkje er gud. Og eg metta deim, men dei dreiv hor og flokka seg i skjøkjehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Som velfødde hestar er dei tidleg ute; kvar ein kneggjar dei åt grannekona si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Skulde eg ikkje heimsøkja slikt, segjer Herren, eller skulde mi sjæl ikkje harma seg på eit sovore folk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Stig upp på hennar murar og øydelegg, men gjer ikkje reint audt. Riv av hennar vinrankor, dei høyrer ikkje Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'For dei hev ille svike meg, både Israels hus og Judas hus, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Dei hev neitta Herren og sagt: «Det er ikkje han, og nokor ulukka skal ikkje koma yver oss, og sverd og svolt skal me ikkje sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Og profetarne skal verta til vind, for det er ingen som talar i deim. Soleis skal det ganga med deim sjølve.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Difor, so segjer Herren, allhers drott: Sidan de talar slike ord, sjå, so gjera eg mine ord i din munn til ein eld og dette folket til ved, og han skal øyda deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Sjå, eg let eit folk frå eit land langt burte koma yver dykk, Israels hus, segjer Herren, eit sterkt folk er det, eit eldegamalt folk er det, eit folk med eit mål du ikkje kjenner, og ikkje skynar du kva dei segjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Deira pilehus er som ei opi grav, alle saman er dei kjempor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Og dei skal eta upp din avle og ditt brød, dei skal tyna dine søner og dine døtter, dei skal eta upp dine sauer og dine naut, dei skal øydeleggja dine vintre og fiketre, dine faste byar, som du lit på, skal dei brjota ned med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Men jamvel i dei dagarne, segjer Herren, vil eg ikkje heiltupp øyda dykk ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Og når de då segjer: «Kvi hev Herren, vår Gud, gjort alt dette imot oss?» då skal du segja med deim: «Likeins som de sveik meg og tente framande gudar i dykkar land, so skal de tena framande i eit land som ikkje er dykkar land!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Kunngjer dette i Jakobs hus og lat deim få høyra det i Juda og seg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Høyr dette, du fåvise og vitlause lyd, som hev augo, men ikkje ser, som hev øyro, men ikkje høyrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Vil de ikkje ottast meg, segjer Herren, eller skjelva for mi åsyn? eg som sette fjøresanden til demma for havet, til eit ævelegt stengje som det ikkje kann fløda yver, som bårorne kjem dynjande imot, men ikkje vinn på, og marmar imot, men ikkje kann fløda yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Men denne lyden hev eit stridigt og tråssugt hjarta, dei hev vike undan og er burtgjengne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Og dei hev ikkje sagt i sitt hjarta: «Lat oss ottast Herren, vår Gud, som gjev regn, både haustregn og vårregn, i rett tid, som tek vare på dei visse haustonne-vikorne for oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Dykkar misgjerningar hev avlaga alt dette, og dykkar synder hev halde det gode burte frå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'For det finst ugudlege i lyden min, dei legg seg på lur liksom fuglefangarar huker, dei set ut gildra, menneskje veider dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Nett som eit bur fullt av fuglar, so er husi deira fulle av svik; difor er dei store og rike vortne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Dei er feite vortne so det skin av deim; dei er breiddfulle med vondt; dei dømer ikkje i nokor sak, hjelpar ikkje den farlause til sin rett, og i fatigmanns sak dømer dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Skulde eg ikkje heimsøkja for slikt, segjer Herren, eller skulde mi sjæl ikkje hemna seg på eit sovore folk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Grysjelege og gruelege ting gjeng fyre seg i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Profetarne spår lygn, og prestarne er strenge herrar etter deira råd, og lyden min likar det. Men kva vil de gjera når enden på dette kjem?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Fly, de Benjamins-søner, ut or Jerusalem, og blås i herlur i Tekoa, og reis upp eit merke yver Bet-Hakkerem! for ei ulukka trugar nordantil med stor øydeleggjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Den fagre og kjælne, Sions dotter, henne tyner eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Til henne skal hyrdingar koma med hjorderne sine; dei slær upp tjeld rundt kringum henne, dei beiter av kvar sitt stykke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Vigsla dykk til strid mot henne! Statt upp og lat oss draga upp høgst å dag! Usæle me! For det lid på dagen, og kveldskuggarne lengjest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Statt upp og lat oss draga upp um natti, og lat oss leggja hennar borghaller øyde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'For so segjer Herren, allhers drott: Hogg tre og kasta upp ein voll mot Jerusalem! Det er byen som skal verta heimsøkt; han er fullsett med vondskap all igjenom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Likeins som brunnen let vatn vella fram, soleis let han sin vondskap vella fram. Valdsverk og tjon høyrest der, sår og slag er stødt framfor mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Lat deg segja, Jerusalem, so mi sjæl ikkje skal venda seg frå deg, so eg ikkje skal gjera deg til ei audn, til eit ubygt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'So segjer Herren, allhers drott: Ei attpå-sanking, liksom på eit vintre, skal dei gjera på leivningen av Israel..');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Kven skal eg tala til og vitna for, so dei høyrer? Sjå, øyra deira er u-umskore so dei ikkje kann gjeva gaum; sjå, Herrens ord er vorte til spott bland deim, dei likar det ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Men eg er full av Herrens harm, eg er utmødd av å halda honom inne..');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Og husi deira skal koma i annan manns eige, deira jorder og konor like eins. For eg vil retta ut mi hand mot deim som bur i landet, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'For både små og store, alle saman søkjer dei låk vinning; både profet og prest, kvar ein fer med svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Og dei fer lettvint åt med å lækja mitt folks skade, med di dei segjer: «Fred, fred!» endå det ingen fred er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Dei skal standa til skammar; for dei hev gjort skjemdarverk. Men dei korkje skjemmest eller veit kva det er å blygjast. Difor skal dei falla med deim som fell, den tid eg heimsøkjer deim, skal dei snåva, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'So sagde Herren: Statt på vegarne og sjå etter og spør etter dei gamle stigarne, kvar vegen til det gode er, og ferdast so på den, so skal de finna kvild for sjælerne dykkar. Men dei sagde: «Me vil ikkje ferdast på honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Og eg sette vaktmenner yver dykk og sagde: «Lyd vel etter lurljomen!» Men dei sagde: «Me vil ikkje lyda etter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Difor høyr, de folk, og få vit på, du lyd, kva som i deim bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Høyr det, du jord: sjå, eg fører ulukka yver dette folk - den grøda deira løynderåder hev bore - for dei hev ikkje gjeve gaum etter mine ord, og loverne mine mismætte dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Kva skal eg med røykjelse som kjem frå Sjeba, og med den beste kalmus frå eit land langt burte? Brennofferi dykkar er ikkje til hugnad, og slagtofferi hev eg ikkje hug på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Difor, so segjer Herren: Sjå, eg legg støytesteinar for dette folket, og feder og søner saman skal snåva på deim, granne med granne skal verta tynt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'So segjer Herren: Sjå, eit folk kjem frå Norderlandet, ei stor tjod ris upp frå utkanten av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Um boge og spjot held dei traust, illharde er dei og syner ikkje miskunn. Røysti deira marmar som havet, og på hestar kjem dei ridande, budde som menner til strid mot deg, du dotter Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Me hev fenge fretnader um deim, magtstolne seig våre hender; me tok fæla, fekk flagor som kvinna i føderider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Gakk ikkje ut på marki og ferdast ikkje på vegen! For fienden hev sverd; rædsla rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Du dotter, mitt folk, gyrd deg med sekk og velt deg i oska, set i syrgjelæte som yver ein einberning, øya deg sårt! For brått kjem tynaren yver oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Eg hev sett deg til ransakar hjå mitt folk - til ei borg - so du skal kjenna og ransaka deira veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Alle saman er dei fråfalne og stridige; dei gjeng og baktalar, dei er kopar og jarn; alle saman fer dei med tyning og tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Smidjebelgen hev blåse, men av elden kjem berre bly; til fåfengs var den reinsande smelting, og dei vonde vart ikkje utskilde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, '«Sylv som er vanda» kallar dei deim, for Herren hev vanda deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Det ordet som kom til Jeremia frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Gakk og statt i porten til Herrens hus og ropa der ut dette ordet, og seg: Høyr Herrens ord, alt Juda, de som gjeng inn gjenom desse portarne og vil tilbeda Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So segjer Herren, allhers drott, Israels Gud: Lat dykkar vegar og dykkar gjerningar betrast, so skal eg lata dykk bu på denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Lit ikkje på ljugarord, når dei segjer: «Dette er Herrens tempel, Herrens tempel, Herrens tempel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Men um de let dykkar vegar og gjerningar betrast, um de skifter rett millom mann og mann,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'ikkje er harde mot den framande, den farlause og enkja, og ikkje renner ut skuldlaust blod på denne staden, og ikkje ferdast etter andre gudar til ulukka for dykk sjølve,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'då vil eg lata dykk bu på denne staden, i landet som eg gav federne dykkar, frå æva og til æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Sjå, de lit på ljugarord som det ikkje er gagn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Er det ikkje so: de stel, myrder og driv hor og gjer rang eid og brenner røykjelse for Ba’al og fer etter andre gudar som de ikkje kjenner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'og so kjem de og stend framfor mi åsyn i dette huset som er uppkalla etter mitt namn, og segjer: «No er me berga» - so de sidan kann gjera all denne styggedomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Er då dette huset som er uppkalla etter mitt namn vorte eit røvarbol i dykkar augo? Eg med, sjå eg ser på det soleis, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'For gakk til bustaden min i Silo, der som eg i fyrstningi let namnet mitt bu, og sjå kva eg hev gjort med det for vondskapen skuld i mitt folk Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Og no, etter di de gjer alle desse gjerningarne, segjer Herren, og eg tala jamt og samt, men de lydde ikkje, eg kalla på dykk, men de svara ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'so vil eg gjera med det huset som er uppkalla etter mitt namn, og som de lit på, og med den staden eg gav dykk og federne dykkar, likeins som eg hev gjort med Silo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Og eg vil støyta dykk burt frå mi åsyn, likeins som eg støytte frå meg alle brørne dykkar, all Efraims ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Men du, du skal ikkje beda for dette folket og ikkje koma med klagerop eller bøn for deim og ikkje naudbeda meg, for eg høyrer deg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ser du ikkje kva dei gjer i Juda-byarne og på Jerusalems-gatorne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Borni sankar i hop ved, og federne kveikjer elden, og kvinnorne knodar deig til å laga kakor åt himmeldronningi, og drykkoffer renner dei ut for andre gudar, til å gjera det leidt for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Gjer dei då meg noko leidt? segjer Herren, er det ikkje seg sjølve, so skammi må liggja utanpå deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Difor, so segjer Herren, Herren: Sjå, min vreide og min harm vert utrend yver denne staden, yver menneskja og yver dyri og yver trei på marki og yver grøda på jordi, og han skal brenna og ikkje slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'So segjer Herren, allhers drott, Israels Gud: Legg brennofferi dykkar attåt slagtofferi og et kjøt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'For den dagen eg førde federne dykkar ut or Egyptarlandet, tala eg ikkje med deim um eller gav deim noko bod um brennoffer og slagtoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Men dette baud eg deim og sagde: «Lyd mi røyst, so skal eg vera dykkar Gud, og de skal vera mitt folk, og gakk allstødt på den vegen som eg byd dykk, so det kann ganga dykk vel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Men dei lydde ikkje og lagde ikkje øyra sitt til, men ferdast etter sine eigne råder, sitt harde vonde hjarta, og dei snudde ryggen til meg og ikkje andlitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Alt ifrå den dagen då federne dykkar for ut or Egyptarlandet og heilt til denne dag hev eg dagstødt, jamt og samt, sendt alle mine tenarar, profetarne, til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Men dei lydde ikkje på meg og lagde ikkje øyra sitt til, men dei var hardnakka og for enn verre fram enn federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Og du skal tala alle desse ordi til deim, men dei vil ikkje lyda på deg, og du skal ropa åt deim, men dei vil ikkje svara deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Seg då med deim: «Dette er folket som ikkje lydde på Herren, sin Guds, røyst og ikkje let seg aga; truskapen er burt kvorven og ut-øydd or deira munn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Klypp av håret ditt og kasta det burt og set i med eit syrgjekvæde på dei snaude haugar! For Herren hev vanda og støytt frå seg denne ætti som han er harm på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'For Juda-sønerne hev gjort det som vondt er i mine augo, segjer Herren. Dei hev sett sine styggeting i det huset som er uppkalla etter mitt namn, og sulka det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Og dei hev bygt Tofet-haugar, dei som er i Hinnomssons-dalen, til å brenna sine søner og døtter i eld på - som eg ikkje hev bode, og som ikkje var kome meg i hugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Difor, sjå, dei dagar skal koma, segjer Herren, då ein ikkje lenger skal segja «Tofet» eller «Hinnomssons-dalen», men «Dråpsdalen», og dei skal gravleggja i Tofet, av di dei vantar rom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Og liki av dette folket skal verta til mat åt fuglarne under himmelen og dyri på jord, og ingen skal skræma deim burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Då vil eg lata kverva burt or byarne i Juda og frå gatorne i Jerusalem fagnadrøyst og glederøyst, røyst av brudgom og røyst av brur, for landet skal verta lagt i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'I den tidi, segjer Herren, skal dei taka beini åt Juda-kongarne og beini åt hovdingarne og beini åt prestarne og beini åt profetarne og beini åt Jerusalems-buarne ut or graverne deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'og breida deim ut for soli og for månen og heile himmelheren, som dei elska og tente, og som dei for etter, og som dei søkte, og som dei tilbad. Dei vert ikkje samla og ikkje gravlagde; til møk utyver marki skal dei verta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Og all leivningen som vert leivd av denne vonde ætti, på alle stader der dei leivde, der som eg driv deim burt, skal velja dauden heller enn livet, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Og du skal segja med deim: So segjer Herren: Dett ein og stend ikkje upp att? eller gjeng ein burt og snur ikkje um att?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Kvi hev då denne Jerusalems-lyden falle frå med eit ævelegt fråfall? Dei held fast på sitt svik og vil ikkje snu um att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Eg gav gaum og lydde: dei talar det som ikkje er rett, det finst ikkje den mann som angrar sin vondskap og segjer: «Kva hev eg gjort!» Alle saman hev dei snutt seg burt i laupet, likeins som ein hest som renner av stad i strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Jamvel storken under himmelen veit sine tider, og turtelduva og svala og trana ansar på tidi når dei skal koma, men mitt folk kjenner ikkje Herrens rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Korleis kann de segja: «Me er Sise, og Herrens lov er hjå oss?» vanneleg, sjå, lygn-pennen åt dei skriftlærde hev gjort henne til lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Dei vise vert til skammar, dei vert tekne av ræddhug og rådløysa. Sjå, Herrens ord hev dei vanda; kvar skulde dei då hava visdom ifrå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Difor vil eg gjeva konorne deira til andre, jorderne deira åt landvinnarar. For både små og store, alle saman søkjer dei låk vinning, både profet og prest, alle saman fer dei med svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Og dei fer lettvint åt med å lækja skaden åt dotteri, folket mitt, med di dei segjer: «Fred, fred!» endå det ingen fred er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Dei skal standa til skammar, for dei hev gjort skjemdarverk. Dei korkje skjemmest eller veit kva det er å blygjast. Difor skal dei falla med deim som fell; i si heimsøkjingstid skal dei snåva, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Eg vil gjera av med deim, segjer Herren. Det bid ikkje druvor på vintreet og ikkje fikor på fiketreet, og lauvet er visna. Og eg sender deim slike som skal koma yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Kvifor sit me i ro? Samla dykk og lat oss ganga inn i dei faste byarne og tynast der! for Herren, vår Gud, vil lata oss tynast og gjeva oss eitervatn å drikka, av di me hev synda imot Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Me ventar på fred, men det kjem ikkje noko godt, på ei tid med lækjedom, og sjå - fælske.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Frå Dan høyrer ein frøsing av øykjerne hans, og for kneggjingi av dei spræke hestarne hans skjelv alt landet. Og dei kjem og et upp landet og det som i det er, byen og deim som i honom bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'For sjå, eg sender imot dykk ormar, basiliskar, som ikkje let seg mana burt, og dei skal bita dykk, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Å, kva kan hugsvala meg i sorgi! Hjarta er sjukt i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Sjå, naudropi frå dotteri, folket mitt, ljomar frå eit land langt burte: «Er då ikkje Herren i Sion? eller er ikkje kongen hennar der?» - Kvi hev dei harma meg med gudebilæti sine, med fåfenglege framande gudar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Skurdonni er lidi, fruktonni er ende, men me er ikkje frelste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Eg er tynt for tjonet på dotteri, folket mitt, eg gjeng i syrgjeklæde, fæla hev teke meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Finst det då ikkje balsam i Gilead, eller bid det ingen lækjar der? Eller kvi hev ikkje dotteri, folket mitt, fenge bendsel på?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Å, um hovudet mitt var vatn og auga mitt ei tårekjelda! Då skulde eg gråta dag og natt yver deim som er ihelslegne for dotteri, folket mitt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Å, um eg hadde eit herbyrge i øydemarki! Då skulde eg skiljast med folket mitt og fara burt frå deim. For alle saman er dei horkarar, ein flokk av svikarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Og dei spenner tunga som bogen sin til lygn, og ikkje på ærleg vis er dei megtige vortne i landet, men frå vondt til vondt gjeng dei fram, og meg veit dei ikkje av, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Vara dykk, kvar og ein for sin ven, og lit ikkje på ein bror! for kvar ein bror er ein stor-svikar, og kvar ein ven fer med baktale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Og kvar og ein svik sin ven, og sanning talar dei ikkje. Dei tem si tunge upp til å tala lygn, dei møder seg ut med meinkrokar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Du bur midt i svik: i sitt svik vil dei ikkje vita av meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Difor, so segjer Herren, allhers drott: Sjå, eg vil smelta deim og røyna deim, for kva anna skulde eg gjera med slik ei som dotteri, folket mitt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Tunga deira er ei drepande pil, svik talar ho. Med munnen talar dei venleg med grannen sin, men i hjarta set dei upp gildra for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Skulde eg ikkje heimsøkja deim for slikt? segjer Herren; skulde mi sjæl ikkje hemna seg på slikt eit folk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Yver heidarne vil eg setja i med gråt og låt og yver beitemarkerne i audni med eit syrgjekvæde; for dei er avsvidne, so ingen fer der framum, og fe-rauting er ikkje høyrande der. Både himmelens fuglar og dyri er flydde og burtfarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Og eg vil gjera Jerusalem til steinrøysar, til sjakal-bøle, og byarne i Juda vil eg gjera til ei audn so ingen bur i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kven er so vis ein mann at han skynar dette, og kven hev Herrens munn tala til, so han kann kunngjera dette: Kvifor landet er i øyde lagt, avsvide som ei øydemark der ingen fer framum?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Og Herren sagde: Sidan dei vende seg frå lovi mi, som eg gav deim, og ikkje lydde meg og ikkje ferdast etter henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'men ferdast etter sitt harde hjarta og etter Ba’alarne som federne deira hadde lært deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'difor, so segjer Herren, allhers drott, Israels Gud: Sjå, eg gjev dette folket malurt å eta og eitervatn å drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Og eg vil spreida deim ut millom folkeslag som dei ikkje kjende, korkje dei sjølve eller federne deira, og eg vil senda sverdet etter deim til dess eg fær tynt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'So segjer Herren, allhers drott: Gjev gaum, og kalla på syrgjekvendi, at dei må koma, og send bod til dei kunnige kvinnorne, at dei kann koma!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Og lat deim skunda seg og setja i eit syrgjekvad yver oss, so tåror kann trilla utor augo våre og augneloki våre vatsfljuga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'For frå Sion høyrer ein omen av syrgjesong: «Å, kor øydelagde me er! Me er vortne ovleg til skammar; for landet laut me fly, av di at dei hev brote ned våre bustader.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Ja, høyr, de kvinnor, Herrens ord, og lat øyra dykkar taka imot ordet frå hans munn, og lær døtterne dykkar syrgjesong, og den eine lære hi syrgjekvæde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'For dauden stig upp i vindaugo våre, er komen inn i hallerne våre. Han vil rydja ut borni på gata og ungmenni frå torgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Tala: So segjer Herren: Og manne-liki skal liggja som møk burtyver jordi og som kornband etter skjeraren, og ingen samlar deim upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'So segjer Herren: Den vise rose seg ikkje av visdomen sin, og den sterke rose seg ikkje av styrken sin, den rike rose seg ikkje av rikdomen sin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Men den som vil rosa seg, han rose seg av di han er vitug og kjenner meg: at eg er Herren, som gjer miskunn, rett og rettferd på jordi; for i sovore hev eg hugnad, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Sjå, dei dagar skal koma, segjer Herren, då eg vil heimsøkja alle umskorne som er u-umskorne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egyptarland og Juda, Edom og Ammons-sønerne og Moab og alle med rundklypt hår, som bur i øydemarki. For alle heidningfolki er u-umskorne, og heile Israels hus er u-umskore på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Høyr det ord som Herren talar til dykk, Israels hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'So segjer Herren: Ven dykk ikkje til vegen åt heidningfolki, og ræddast ikkje himmelteikni, endå um heidningarne ræddast deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'For dei seder folkeslagi hev, er fåfengd; for dei høgg eit tre i skogen, og treskjeraren lagar det til med øksi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'med sylv og med gull pryder han det, med naglar og hamar fester han det, so det ikkje skal stupa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Dei er som ei svarva trelurk, og kann ikkje tala. Ein lyt bera deim, for dei kann ikkje ganga. Ikkje ottast deim! for dei kann ikkje skada, og å ganga hev dei heller ikkje magt til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Ingen er din like, Herre! Du er stor, og namnet ditt er stort i velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kven skulde ikkje ottast deg, du folkekonge! For det sømer deg, for millom alle vise hjå folki og i heile deira rike er ingen din like.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'For alle saman er uvituge og vitlause; ei fåfengleg læra! Tre er det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'sylvplator, førde frå Tarsis, gull frå Ufaz, eit verk av ein treskjerar og av gullsmed-hender. Klædnaden deira er av blått og raudt purpur, eit verk av hage kunstmenner er dei alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Men Herren er Gud i sanning; han er ein livande Gud og ein æveleg konge. For hans vreide bivrar jordi, og folkeslagi herder ikkje å standa for hans harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'So skal de segja med deim: Dei gudar som ikkje hev gjort himmel og jord, dei skal kverva burt frå jordi og under himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Han hev gjort jordi med si kraft, skapt heimen med sin visdom og spana ut himmelen med sitt vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Når han let røysti si ljoma, svarar dyn av vatn i himmelen, og han let skodda stiga upp frå enden av jordi, let eldingar laga regn, og sender vind ut or gøymslorne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Klumsa stend kvar ein mann og hev ikkje vit på det, skjemmast lyt kvar ein gullsmed av sitt bilæte; for dei støypte bilæti hans er berre lygn, det er ingi ånd i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Dei er berre fåfengd, eit verk til å hæda; den tid dei vert heimsøkte, er det ute med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Jakobs arvlut er ikkje deim lik, for det er han som hev skapt alt, og Israel er hans odelsætt. Herren, allhers drott, er namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Sanka godset ditt utor landet, du lyd som sit umlægra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'For so segjer Herren: Sjå, eg vil slengja burt deim som bur i landet denne gongen, og trengja deim so dei skal få kjenna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Eie meg, kor sundbroten eg er! Ulækjande er mitt sår. Men eg segjer: «Dette er då ei liding som eg lyt bera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Tjeldet mitt er øydelagt, og alle tjeldtogi mine er avslitne. Borni mine er frå meg farne og er ikkje lenger til, ingen er til som heretter kann reisa tjeldet mitt og festa upp tjelddukarne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'For hyrdingarne var uvituge og søkte ikkje Herren. Difor for dei ikkje viseleg åt, og all hjordi deira vart spreidd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Høyr, ein ljom! sjå, det kjem, og ein stor dyn frå Norderlandet - for å gjera Juda-byarne til ei audn, til sjakal-bøle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Eg veit, Herre, at menneskja ikkje sjølv råder for sin veg, og at gangande mann ikkje hev magt til å styra sine stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Refs meg, Herre, men med måte, ikkje i din vreide, so du ikkje skal gjera meg reint til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Renn harmen din ut yver heidningfolki som ikkje kjenner deg, og yver ætter som ikkje påkallar namnet ditt! For dei hev ete på Jakob, ja, ete honom upp og gjort ende på honom, og bustaden hans hev dei lagt i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Det ordet som kom til Jeremia frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Høyr ordi i denne pakti, og tala til Juda-mennerne og Jerusalems-buarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Og du skal segja med deim: So segjer Herren, Israels Gud: Forbanna vere den mann som ikkje lyder på ordi i denne pakti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'som eg baud federne dykkar den dagen eg let deim koma ut or Egyptarlandet, ut or jarnomnen, og sagde: Høyr på mi røyst og gjer alt dette, so som eg bed dykk, då skal de vera mitt folk, og eg vil vera dykkar Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'so eg kann få halda den eiden som eg svor federne dykkar: å gjeva deim eit land som fløymer med mjølk og honning, so som det er enn i dag. Og eg svara og sagde: «Amen, Herre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Og Herren sagde med meg: Ropa ut alle desse ordi i Juda-byarne og på Jerusalems-gatorne og seg: Lyd på ordi i denne pakti og gjer etter deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'For eg hev ålvorleg vara federne dykkar, då eg let deim koma ut or Egyptarlandet, og alt til denne dag, jamt og samt, og sagt: «Høyr på mi røyst!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Men dei lydde ikkje og lagde ikkje øyra sitt til, men kvar og ein ferdast etter sitt vonde, harde hjarta. So let eg då koma yver deim alt det eg hadde sagt i denne pakti, som eg baud deim å halda, men som dei ikkje heldt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Og Herren sagde med meg: Det er kome upp at Juda-mennerne og Jerusalems-buarne hev vore med kvarandre i ei samansverjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Dei hev snutt tilbake til misgjerningarne åt forfederne sine, som ikkje vilde høyra på ordi mine, og dei fer etter andre gudar, for å tena deim. Israels hus og Judas hus hev brote pakti mi, som eg gjorde med federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Difor, so segjer Herren: Sjå, eg let koma yver deim ei ulukka som dei ikkje kann koma seg undan. Då skal dei ropa på meg, men eg vil ikkje høyra på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'So skal Juda-byarne og Jerusalems-buarne ganga og ropa på gudarne som dei plar brenna røykjelse for; men dei skal ikkje frelsa deim i deira trengsletid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'For gudarne dine, Juda, er vortne like mange som byarne dine, og du hev reist like mange altar for skjemdi, altar til å brenna røykjelse på for Ba’al, som det er gator i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Og du, ikkje skal du beda for dette folket og ikkje koma med klagerop eller bøn for deim. For eg vil ikkje høyra når dei ropar til meg i si naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Kva hev ho som eg elskar å gjera i mitt hus, ho som med mange gjer skjemdarverk? Kann heilagt offerkjøt fria deg? Når du gjer vondt, då fagnar du deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, '«Eit sigrønt oljetre, prydt med fager frukt,» so kalla Herren deg; medan eit veldugt glam ljomar, kveikjer han eld på det, og greinerne brotnar av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Og Herren, allhers drott, som planta deg, hev sagt illsegn imot deg for illgjerningi som Israels hus og Judas hus hev gjort til å harma meg upp, med å brenna røykjelse for Ba’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Og Herren let meg få vita det, so no veit eg det; då synte du meg deira framferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Men eg var som eit spakt lamb, som vert leidt til slagting, og eg visste ikkje at dei lagde løynderåder mot meg: «Lat oss øydeleggja treet og frukti og rydja honom ut or landet åt dei livande, so ein ikkje lenger kjem namnet hans i hug!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Men Herren, allhers drott, er ein rettferdig domar, han ransakar nyro og hjarta. Eg fær sjå at du hemner deg på deim, for eg hev lagt saki mi fram for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Difor, so segjer Herren um mennerne i Anatot, dei som ligg deg etter livet og segjer: «Du skal ikkje tala profetord i Herrens namn, annars skal du døy for vår hand,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, '- difor, so segjer Herren, allhers drott: Sjå, eg vil heimsøkja deim dei unge menner skal falla for sverd, deira søner og døtter skal døy av svolt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Og ikkje noko skal verta leivt åt deim; for eg sender ulukka på mennerne i Anatot det året dei vert heimsøkte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Rettferdig er du, Herre, når eg andordast med deg, endå lyt eg tala med deg um retten. Kvi gjeng det dei ugudlege vel? Kvi er dei sutlause alle dei sviksame?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du hev planta deim, dei hev røtt seg og; dei veks, dei ber frukt og; nær er du i deira munn, men langt burte frå deira nyro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Men du, Herre, kjenner meg, du ser meg og røyner mitt hjartelag mot deg; skil deim frå likeins som sauer til slagting, og vigsla deim til ein dråpsdag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Kor lenge skal landet syrgja og grøda på jordi alle stader torna burt? For deira vondskap skuld som der bur, er dyr og fuglar burtrivne; for dei segjer: «Han ser ikkje endelykti vår.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Um du vert utmødd når du løyp med gangande mann, korleis kann du då kapprenna med hestar? I eit fredt land er du trygg, men kva vil du gjera i tjukkskogen burtmed Jordan?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'For jamvel brørne dine og farshuset ditt, jamvel dei er utrue mot deg, jamvel dei set i illskrik attum din rygg. Tru deim ikkje, endå dei talar vænt til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Eg hev gjenge frå huset mitt, eg hev vanda odelen min, eg hev gjeve den som mi sjæl elska i henderne på hennar fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Odelen min er vorten for meg som løva i skog: han hev sett i eit læte imot meg; difor hatar eg honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Er odelen min som ein spreklut rovfugl? Rovfugl er det då rundt ikring honom. Gakk av stad, samla alle dyr i skogen, lat deim koma hit og eta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Hyrdingar i mengd øydelegg vinhagen min, trakkar ned odelsjordi mi; dei gjer den hugnadlege odelsjordi mi til ei øgjeleg audn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Til ei øydemark gjer dei henne; syrgjande og audsleg ligg ho framfyre meg. Alt landet er i øyde lagt, for ingen legg det på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Yver alle snaud-heidar i øydemarki kjem herjande hopar; for Herren hev eit sverd som øyder frå eine enden av landet til hin; alt kjøt er fredlaust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Dei sår kveite og haustar inn klunger; dei møder seg ut, men reint til fånyttes. So vert då til skammar med grøda dykkar for Herrens brennande vreide!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'So segjer Herren um alle dei vonde grannarne, som rører den odelseiga som eg hev gjeve mitt folk Israel: Sjå, eg rykkjer deim upp or landet deira, og Judas hus vil eg rykkja upp undan deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Men etter eg hev rykt deim upp, vil eg atter miskunna deim og lata dei koma tilbake til kvar sin odel og kvar til kvar sitt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Um dei då lærer seg mitt folks vegar, so dei sver ved mitt namn: «So sant som Herren liver» - liksom dei lærde mitt folk å sverja ved Ba’al, då skal dei verta uppatt-bygde midt ibland mitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Men um dei ikkje lyder, då vil eg rykkja upp det folket, rykkja det upp og tyna det, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'So sagde Herren med meg: Gakk og kjøp deg eit linbelte, og spenn det um lenderne dine, men lat det ikkje koma i vatn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Og eg kjøpte beltet etter Herrens ord og spente det um lenderne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Då kom Herrens ord til meg andre gongen; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Tak beltet som du kjøpte, som er um lenderne dine, og statt upp og gakk til Eufrat, og gøym det der i ei bergriva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Og eg gjekk og gøymde det attmed Eufrat, so som Herren hadde bode meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'So hende det mange dager etterpå, at Herren sagde med meg: Statt upp og gakk til Eufrat, og tak derifrå det beltet som eg baud deg å gøyma der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Og eg gjekk til Eufrat, og eg grov og tok beltet frå den staden der som eg hadde gøymt det. Og sjå, beltet var øydelagt, det var inkje gagn i det meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Då kom Herrens ord til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'So segjer Herren: Soleis vil eg gjera ende på det store ovmodet i Juda og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Denne vonde lyden, som ikkje vil høyra mine ord, som ferdast etter sitt harde hjarta og fer etter andre gudar, og tener deim og tilbed deim, han skal verta som dette beltet, som det ikkje er gagn i meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'For likeins som beltet er fastgjort um mannsens lender, soleis feste eg til meg alt Israels hus og alt Judas hus, segjer Herren, so dei skulde vera mitt folk og vera meg til frægd, til fagnad og pryda; men dei høyrde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Og du skal segja med deim dette ordet: So segjer Herren, Israels Gud: Kvar ei vinkrukka er til å fylla vin på. Då skal dei segja med deg: «Veit me ikkje det då, at kvar ei vinkrukka er til å fylla vin på?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Seg då med deim: So segjer Herren: Sjå, eg fyller alle som bur i dette landet, og kongarne som sit på Davids kongsstol, og prestarne og profetarne og alle som bur i Jerusalem, so dei vert drukne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Og eg vil krasa deim, kvar mot annan, både federne og borni, alle saman, segjer Herren. Eg vil ikkje spara og ikkje miskunna, og ikkje tykkja synd i deim, men tyna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Høyr og gjev gaum! Ver ikkje ovmodige! for Herren talar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Gjev Herren, dykkar Gud, æra, fyrr han let det myrkna, og fyrr føterne dykkar støyter seg på dei dimme heidar! De stundar på ljos, men han skal gjera det til daudeskugge, og lata det verta stumende myrkt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Men vil de ikkje høyra på det, då lyt mi sjæl syrgja i løynd yver slikt eit ovmod, og mitt auga må gråta so tårorne trillar, av di Herrens hjord vert burtførd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Seg med kongen og til kongsmori: Set dykk lågt ned! for den prydelege kruna er falli av dykkar hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Byarne i Sudlandet er stengde, og ingen opnar deim. Alt Juda er ført burt i utlægd, ført burt til siste mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Lat upp augo dykkar og sjå kor dei kjem nordanfrå! Kvar er no hjordi som du hadde fenge, dei væne sauerne dine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Kva vil du segja, når han set til hovdingar yver deg deim som du sjølv hev vant på deg og havt til vener? Skulde du ikkje få flagor, som ei kvinna fær føderider?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Og um du då segjer i ditt hjarta: «Kvi lyt eg taka imot dette?» - for di store misgjerning er din kjolefald lyft upp, dine hælar nækte med vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kann ein blåmann skifta si hud eller ein pantar sine flekkjer? Då skulde de og kunna gjera det gode, de som hev vanst til å gjera vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'So vil eg då spreida deim liksom halm som fyk for vind utor øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Dette er luten din, den deilen eg hev etla åt deg, segjer Herren, av di du hev gløymt meg og lit på lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'So vil då eg og lyfta upp din kjolefald yver ditt andlit, so di skam vert synberr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Hordomen din og kneggjingi di, den skamlause ulivnaden din uppå haugar på marki, all skjemdarferdi di hev eg set. Usæle Jerusalem! Kor lenge kjem det ikkje endå til å vara fyrr du vert rein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Herrens ord som kom til Jeremia um turketidi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Syrgjande ligg Juda, portarne ormegtast; syrgjeklædde luter dei mot jord, og naudropi stig upp frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Storfolket deira sender sine undergjevne etter vatn; dei kjem til brunnarne, men finn inkje vatn; deira kjerald kjem tome attende. Dei kjenner seg skjemde og vonbrotne og sveiper inn sine hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'For jordi skuld, som er forfærd vorti av di det ikkje vert regn i landet, kjenner bønderne seg skjemde, sveiper inn sine hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'For jamvel hindi i marki ber kalven, men gjeng ifrå honom, for di det ikkje finst gras.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Og villasni stend på snaude haugar, dei syp etter anden som sjakalar; augo deira kjenast upp, for di det ikkje finst urter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Um våre misgjerningar vitnar mot oss, so gjer då miskunn for ditt namn skuld! For mange er våre fråfall, mot deg hev me synda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Du Israels von, du frelsar i trengsletid! Kvi er du som ein framand i landet, og som ein ferdamann som tjeldar berre for natti?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Kvi er du lik ein forstøkt mann, lik ei kjempa som ikkje vinn å hjelpa? Du er då midt ibland oss, Herre, og me er uppkalla etter ditt namn; slepp oss ikkje frå deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'So segjer Herren um dette folket: Soleis likar dei å reika um; dei sparer ikkje føterne sine. So hev då Herren ikkje hugnad i deim; no vil han minnast misgjerningarne deira og heimsøkja synderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Og Herren sagde med meg: Du skal ikkje beda um velgang for dette folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Når dei fastar, lyder eg ikkje på deira rop, og når dei ofrar brennoffer og grjonoffer, hev eg ikkje hugnad i deim, men med sverd, svolt og sott vil eg tyna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Då sagde eg: «Å, Herre, Herre, sjå profetarne segjer med deim: «De skal ikkje sjå sverd, og de ikkje verta ute for svolt, men fred med tryggje vil eg gjeva dykk på denne staden.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Då sagde Herren med meg: Lygn spår profetarne i mitt namn; ikkje hev eg sendt deim og ikkje bede deim og ikkje tala til deim; lygn-syner og runing og fåfengd og sitt hjartans svik, det er det dei spår åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Difor, so segjer Herren um dei profetarne som spår i midt namn, endå eg ikkje hev sendt deim, og som segjer at sverd og svolt ikkje skal koma i dette landet: For sverd og svolt skal dei enda sine dagar, desse profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Og folket som dei spår åt, skal liggja slengt på gatorne i Jerusalem, tynt av svolten og sverdet, og ingen skal jorda deim - dei sjølve, konorne deira og sønerne deira og døtterne deira - og eg vil renna vondska deira ut yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Men du skal segja med deim dette ordet: Tårorne trillar or augo mine natt og dag og fær ikkje stogga; for møyi, dotteri, folket mitt, er ovleg sundbroti, hev fenge eit stort ulækjande sår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Gjeng eg ut på marki, sjå, då ligg der dei som med sverd er slegne, og kjem eg inn i byen, sjå, der talmast dei av svolt. Ja, både prest og profet lyt flakka um, til eit land som dei ikkje kjenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hev du då reint støytt Juda frå deg, eller styggjest di sjæl ved Sion? Kvi hev du slege oss so, at det ikkje bid helsebot for oss? Me ventar på fred, men det kjem ikkje noko godt, og på ei tid med helsebot, og sjå - fælske.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Herre, me kjennest ved vår ugudlege åtferd, misgjerningi åt federne våre, at me hev synda mot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'For ditt namn skuld støyt oss ikkje frå deg, lat ikkje din herlegdoms kongsstol verta svivyrd! Kom i hug, brjot ikkje di pakt med oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Finst det nokon av dei fåfenglege gudarne åt heidningfolki som kann gjeva regn? Eller sender himmelen regnskurer av seg sjølv? Er det ikkje du, Herre, vår Gud? Me stundar på deg, for du hev gjort alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Då sagde Herren med meg: Um so Moses og Samuel stod fram for mi åsyn, skulde mi sjæl ikkje venda seg til dette folket. Driv deim burt frå mi åsyn, og lat deim fara!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Og når dei segjer med deg: «Kvar skal me då fara?» so skal du segja med deim: So segjer Herren: Til dauden den som åt dauden er etla, og til sverdet den som åt sverdet er etla, og til svolten den som åt svolten er etla, og til utlægd den som åt utlægd er etla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Fire slag heimsøkjingar byd eg då ut imot deg: Sverdet til å drepa, og hundarne til å draga deim burt, og fuglarne under himmelen og dyri på marki til å eta deim og øyda deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Og eg vil gjera deim til ei skræma for alle kongeriki på jord, for det som Manasse Hizkiason, Juda-kongen, gjorde i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'For kven vil tykkja synd i deg, Jerusalem, og kven vil syna deg medkjensla, og kven vil gjera seg ærend og spyrja um det stend vel til med deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Du støytte meg ifrå deg, segjer Herren, du gjekk din veg. Difor retter eg handi ut imot deg og tyner deg; eg er trøytt av å ynkast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Og eg kastar deim med kasteskovl attmed landsens portar, eg gjer folket mitt barnlaust, eg tyner det - frå sine vegar snudde dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Enkjorne deira vert fleire enn havsens sand; yver møderne til deira unge menner let eg ein tynar koma høgstedags leite, let rædsla og fælske dåtteleg koma yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Ho som fødde sju søner, talmast burt og andast, hennar sol gjeng ned medan det enn er dag; ho vert skjemd og til skammar. Og det som vert att av deim, gjev eg åt sverdet framfor deira fiendar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Eie meg, mor mi, at du skulde føda meg, meg som alle folk i landet strider og trættar med! Ikkje hev eg lånt deim og ikkje hev dei lånt meg, og endå bannar dei meg alle i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Herren sagde: Visseleg, eg vil fria deg, so det gjeng deg godt. Visseleg, eg vil lata fienden naudbeda deg når ulukka og naudi kjem på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Kann ein brjota sund jarn, jarn frå Norderland, og kopar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Godset ditt og skattarne dine vil eg gjeva til ran - utan betaling, og det for alle synderne dine, og innan alle dine landskil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Og eg vil lata fiendarne dine føra det burt, inn i eit land som du ikkje kjenner. For ein eld er kveikt i min vreide, mot dykk skal han loga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Du veit det, Herre, kom meg i hug og vitja meg, og hemn meg på deim som forfylgjer meg! Tak meg ikkje burt, langmodig som du er! Hugsa at eg tek imot svivyrda for di skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Eg fann dine ord, og eg åt deim, og dine ord vart til frygd for meg og til fagnad for mitt hjarta; for eg er uppkalla etter ditt namn, Herre, allhers Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Eg hev ikkje sete i lag med skjemtande menner og gama meg; gripen av di hand hev eg sete einsleg, for du fyllte meg med harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Kvi er mi liding æveleg, og kvi vil såret mitt batna? Det vil ikkje gro. Du er vorten som ein svikal bekk åt meg, som vatn ein ikkje kann lita på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Difor, so segjer Herren: Um du vender um, vil eg atter lata deg standa framfor mi åsyn, og um du skil det dyre frå det verdlause, då skal eg hava deg som min munn. Dei skal då venda seg til deg, men du skal ikkje venda deg til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Og eg vil gjera deg til ein fast koparmur mot dette folket; og dei skal strida imot deg, men ikkje vinna på deg, for eg er med deg og vil frelsa og berga deg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Eg vil berga deg utor henderne på dei vonde og fria deg utor nevarne på valdsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Du skal ikkje taka deg kona og ikkje få deg søner og døtter på denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'For so segjer Herren um dei sønerne og døtterne som vert fødde på denne staden, og um deira møder som føder deim, og um deira feder som fær deim i dette landet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Ein pinefull daude skal dei lida, ingen skal gråta yver deim, og ingen skal jorda deim; til møk utyver marki skal dei verta, og av sverd og svolt skal dei verta tynte, og liki deira skal verta til mat åt fuglarne under himmelen og dyri på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'For so segjer Herren: Du skal ikkje koma i gravøl og ikkje ganga og barma deg med deim og ikkje ynkast yver deim. For eg hev teke freden min burt frå dette folket, segjer Herren, min nåde og mi miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Og dei skal døy, store og små, i dette landet, ingen skal jorda deim; og dei skal ikkje barma seg yver deim og rispa seg i holdet eller raka seg snaude i kruna for deira skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Og dei skal ikkje brjota brød åt nokon til trøyst i sorgi etter ein avliden og ikkje gjeva nokon trøystestaupet å drikka yver far han eller mor hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'I gjestebod skal du ikkje heller ganga og sitja der og eta og drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'For so segjer Herren, allhers drott, Israels Gud: Sjå, framfor dykkar augo og i dykkar dagar let eg på denne staden kverva burt fagnadrøyst og glederøyst, røyst av brudgom og røyst av brur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Når du då kunngjer for dette folket alle desse ordi, og dei segjer med deg: «Kvi hev Herren varsla all denne store ulukka yver oss, og kva er misgjerningi vår og kva er syndi vår som me hev forsynda oss med mot Herren, vår Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'då skal du segja med deim: «For di federne dykkar vende seg frå meg, segjer Herren, og gjekk etter andre gudar og tente deim og tilbad deim, men meg vende dei seg ifrå, og lovi mi heldt dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Og de for verre åt enn federne dykkar; for sjå, kvar einaste av dykk ferdast etter dykkar vonde harde hjarta og høyrde ikkje på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Difor vil eg kasta dykk ut or dette landet til eit land som de ikkje kjenner, korkje de eller federne dykkar. Og der skal de tena andre gudar dag og natt, for eg vil ikkje gjera miskunn med dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Difor, sjå, dei dagar skal koma, segjer Herren, då ein ikkje lenger skal segja: «So visst som Herren liver, han som leidde Israels-borni ut or Egyptarlandet,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'men: «So sant som Herren liver, han som leidde Israels-borni ut or Norderlandet og ut or alle dei landi som han hadde drive deim burt til.» For eg vil leida deim attende til landet deira, det som eg gav federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Sjå, eg sender bod etter mange fiskarar, segjer Herren, og dei skal fiska deim. Og sidan sender eg bod etter mange veidemenner, og dei skal veida deim burt frå kvart eit fjell på kvar ein haug og i bergskortorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'For eg held auga med alle vegarne deira; dei er ikkje løynde for mi åsyn, og misgjerningarne deira er ikkje dulde for mine augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Og fyrst vil eg lata deim bøta tvifelt for deira misgjerning og synd, av di dei vanhelga landet mitt med dei daude skrottarne av styggetingi sine og fyllte odelsjordi mi med ufyseskapen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Herre, min styrke og mi vern og mi livd på naudar-dagen! Til deg skal heidningfolk koma frå endarne av jordi. Og dei skal segja: «Berre lygn fekk federne våre fenge i arv, fåfenglege avgudar, gagnløysor alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Kann mannen gjera seg gudar? - slikt er då ikkje gudar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Difor, sjå, eg vil lata deim kjenna det, denne gongen vil eg lata deim kjenna mi hand og mitt velde, so dei skal få vita at namnet mitt er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Judas synd er skrivi med jarngriffel, med demant-odd; ho er innrita på deira hjartans tavlor og på deira altarhorn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'likeins som borni deira kjem i hug altari deira og Astarte-bilæti deira attmed dei grøne tre på dei høge haugarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Du fjellet mitt på vollen! Godset ditt, alle skattarne dine vil eg gjeva til herfang, likeins offerhaugarne dine, for synderne innan alle dine landskil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Då lyt du - og det er di eigi skuld - lata frå deg odelen din, som eg gav deg, og eg vil lata deg træla for fiendarne dine i eit land du ikkje kjenner. For ein eld hev de kveikt i min vreide, æveleg skal han loga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'So segjer Herren: Forbanna er den mann som lit på menneskja og gjer kjøt til sin arm og med sitt hjarta vik frå Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Han skal verta som ein einekrake i heidi og ikkje få sjå at det kjem noko godt; men han skal bu på avsvidne stader i øydemarki, i eit saltlende der ingen annan bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Velsigna er den mann som lit på Herren, og hev Herren å lita på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Han er lik eit tre som er planta attmed vatn, og som tøygjer røterne sine burt åt ein bekk, og som ikkje ræddast når hiten kjem, men hev sigrønt lauv, og som i turkår ikkje syrgjer og ikkje held upp med å bera frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Svikfullt er hjarta framfor alt anna, og låkt, kven kjenner det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Eg, Herren, ransakar hjarta og røyner nyro, og gjev so kvar og ein etter hans veg, etter frukti av hans gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Lik ei rapphøna som ligg på egg ho ikkje sjølv hev vorpe, er den som samlar rikdom som ikkje er rettkomen; midt i sine dagar skal han lata honom frå seg, og når han ligg på sitt siste, er han ein dåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Eit herlegdomssæte, høgreist frå gamalt, er staden åt heilagdomen vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Herre, du Israels von! Alle som vender seg frå deg, skal verta til skammar. Ja, dei som hev vike frå meg, skal verta skrivne i moldi, for dei hev vendt seg frå Herren, kjelda med det livande vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Læk meg, Herre, so vert eg lækt! Frels meg, so vert eg frelst! for du er min lovsong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Sjå, dei segjer med meg: «Kvar vart det av Herrens ord? Lat det koma!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Eg hev då ikkje drege meg undan, men fylgt deg og vore hyrding, og nokon ubøtande ulukke-dag ynskte eg ikkje, du veit det; det som gjekk ut frå lipporne mine, er synbert for di åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ver ikkje til fælske for meg! Du er mi livd på ulukkedagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Lat deim verta til skammar som forfylgjer meg, og lat ikkje meg verta til skammar! Lat deim fæla, og lat ikkje meg fæla! Lat ein ulukke-dag koma yver deim, og med ei tvifelt sundkrasing krase du deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'So sagde Herren med meg: Gakk og statt i Folkeporten, der som Juda-kongarne gjeng inn og der dei gjeng ut, og i alle portarne i Jerusalem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Og du skal segja med deim: Høyr Herrens ord, de Juda-kongar og alt Juda og alle Jerusalems-buar som gjeng inn gjenom desse portarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'So segjer Herren: Vara dykk for dykkar sjæler skuld, so de ikkje um kviledagen ber nokor byrd og kjem inn med gjenom Jerusalems-portarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Og de skal ikkje bera nokor byrd ut or husi dykkar på kviledagen og ikkje gjera noko slag arbeid; men de skal halda kviledagen heilag, so som eg baud federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Men dei høyrde ikkje og lagde ikkje øyra til, men gjorde seg hardnakka, so dei høyrde ikkje og tok ikkje age.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Men um de høyrer på meg, segjer Herren, so de ikkje um kviledagen ber nokor byrd inn gjenom portarne i denne byen, og held kviledagen heilag, so det ikkje gjer noko arbeid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'då skal kongar og hovdingar som sit i Davids kongsstol, koma inn gjenom portarne i denne byen på vogner og hestar, dei sjølve og deira hovdingar, Juda-mennerne og Jerusalems-buarne, og det skal æveleg bu folk i denne byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Og frå Juda-byarne og frå umkverven kring Jerusalem og frå Benjaminslandet og frå låglandet og frå heiderne og frå Sudlandet, skal dei koma og bera fram brennoffer og slagtoffer og grjonoffer og røykjelse, og bera fram takkoffer i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Men um de ikkje høyrer på meg, so de held kviledagen heilag og ikkje kjem med nokor byrd og ber inn gjenom Jerusalems-portarne på kviledagen, då vil eg kveikja eld på portarne, og han skal øyda slotti i Jerusalem og ikkje slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Det ordet som kom til Jeremia frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Statt upp og gakk ned til krusmakar-huset, og der skal eg lata deg høyra ordi mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Eg gjekk då ned til huset åt krusmakaren, og sjå, han gjorde arbeidet sitt på svarveskiva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Vart det då ubrukande, kjeraldet som krusmakaren heldt på å gjera, so som det kann verta med leiret i handi på krusmakaren, so gjorde han det um att til eit anna kjerald, soleis som krusmakeren tykte det høvelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Då kom Herrens ord til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Skulde eg ikkje kunna gjera med dykk, Israels hus, likeins som denne krusmakaren? segjer Herren. Sjå, likeins som leiret er i krusmakar-handi, so er de i mi hand, Israels hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Stundom talar eg um eit folk og um eit rike, at eg vil ryskja upp og riva ned og leggja i øyde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'men um det folket som eg tala um, vender um frå sin vondskap, då angrar eg det vonde som eg hadde tenkt å gjera det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Men stundom talar eg um eit folk og um eit rike, at eg vil byggja og planta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'So gjer dei kann henda det som vondt er i mine augo, og høyrer ikkje på mi røyst: då angrar eg det gode som eg hadde sagt eg vilde gjera vel imot deim med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Seg no då dette til Juda-mennerne og Jerusalems-buarne: So segjer Herren: Sjå, eg emnar på ei ulukka åt dykk og tenkjer ut meinråder mot dykk. Vend då um, kvar og ein frå sin vonde veg, og retta på vegarne dykkar og verki dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Men dei segjer: «Fåfengt! for me vil fylgja våre eigne tankar, og kvar og ein vil gjera etter sitt harde vonde hjarta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Difor, so segjer Herren: Spør millom heidningfolki um nokon hev høyrt slikt. Ovleg grysjelege ting hev møyi Israel gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Bråner då Libanon-snøen brånar burt frå Markartinden, eller minkar den vellande uppkoma burt, den svale, rennande?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Men mitt folk hev gløymt meg, dei brenner røykjelse åt fåfengdi; og dei fekk deim til å snåva på vegarne sine, dei gamle vegarne, so dei gjekk på stigar, på ujamne vegar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'so dei gjer landet sitt til ei skræma, ei æveleg spott; alle som fer der framum, vert forstøkte og rister hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Likeins som austanvinden vil eg spreida deim for fienden. Ryggen og ikkje andlitet skal eg syna deim på deira ulukke-dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Då sagde dei: «Kom og lat oss leggja upp råder mot Jeremia! for det tryt ikkje på lov for presten, eller på råd for den vise, eller på ord for profeten. Kom, lat oss fella honom med våre tungor og ikkje bry oss det minste um det han segjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Gjev gaum etter meg, Herre, og høyr på kor dei trættar med meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Skal ein løna godt med vondt? For dei hev grave ei grav for mitt liv. Kom i hug at eg stod for di åsyn og tala godt for deim, til å venda harmen din burt ifrå deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Difor, gjev borni deira til svolten og lat sverdet få handsama deim, og gjer konorne deira barnlause og til enkjor, og lat mennerne deira verta drepne av sotti, og ungmenni deira slegne med sverd i striden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Lat naudrop høyrast or husi deira når du let mordflokkar brått koma yver deim! For dei hev grave ei grav til å fanga meg i og lurt upp snaror for føterne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Men du, Herre, kjenner alle deira råder imot meg til å drepa meg; gjev deim ikkje til deira misgjerning, og lat ikkje deira synd verta utstroki for di åsyn! Lat deim stupa for di åsyn; i di vreide-tid gjere du upp med deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'So sagde Herren: Gakk og kjøp deg ei krukka av krusmakaren! Tak so med deg nokre av dei øvste av folket og nokre av dei øvste av prestarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'og gakk ut til Hinnomssons-dalen, som er frammed Krusbrot-porten, og ropa ut der dei ord som eg vil tala til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Du skal segja: «Høyr Herrens ord, de Juda-kongar og Jerusalems-buar! So segjer Herren, allhers drott, Israels Gud: Sjå, eg sender ei ulukka yver denne staden, so det skal ringja for øyro på kvar den som høyrer det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'sidan dei vende seg frå meg og mismætte denne staden og brende røykjelse der for andre gudar, som dei ikkje kjende, korkje dei sjølve eller federne deira eller Juda-kongarne, og fyllte denne staden med skuldlaust blod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'og bygde Ba’als-haugar til å brenna sønerne sine i eld på, til brennoffer åt Ba’al, slikt som eg korkje hev skipa eller tala um, og som aldri kom meg i hugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Difor, sjå, det kjem det dagar, segjer Herren, då denne staden ikkje lenger skal kallast «Tofet» eller «Hinnomssons-dalen», men «Dråpsdalen».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Og Juda og Jerusalem gjer eg rådlause på denne staden, og let deim falla for sverd for deira fiendar og ved deira hand som ligg deim etter livet; og liki deira vil eg gjeva til mat åt fuglarne under himmelen og dyri på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Og eg vil gjera denne byen til ei skræma og til ei spott; alle som fer framum honom, skal verta forstøkte og hæda yver alle plågorne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Og eg vil lata deim eta kjøtet av sønerne sine og kjøtet av døtterne sine, og dei skal eta kjøtet av kvarandre i den naud og trengsla som deira fiendar og dei som ligg deim etter livet, skal trengja deim med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Og du skal krasa krukka framanfor augo på dei menner som gjeng med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Og du skal segja med deim: «So segjer Herren, allhers drott: Soleis vil eg krasa dette folket og denne byen som ein krasar krusty som ikkje let seg bøta, og i Tofet skal dei gravleggja med di det ikkje bid andre stader til å jorda i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Soleis vil eg fara åt med denne staden, segjer Herren, og med deim som her bur, so eg gjer denne byen lik Tofet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Og husi i Jerusalem og husi åt Juda-kongarne skal verta som Tofetstaden, ureine som dei er, alle dei husi der dei uppå taki hev brent røykjelse åt heile himmelheren og rent ut drykkoffer åt framande gudar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Og Jeremia kom frå Tofet, dit som Herren hadde sendt honom til å spå, og han stod i fyregarden til Herrens hus og sagde med alt folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '«So segjer Herren, allhers drott, Israels Gud: Sjå, yver denne byen og yver alle dei byarne som høyrer honom til, let eg koma all den ulukka som eg hev tala imot deim; for dei gjeng der hardnakka og høyrer ikkje mine ord.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Og Pashur Immersson, presten, som var yver-tilsynsmann i Herrens hus, høyrde Jeremia spå dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Då slo Pashur profeten Jeremia og sette honom i stokken i den øvre Benjaminsporten i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Men dagen etter slepte Pashur Jeremia laus or stokken. Då sagde Jeremia med honom: «Herren kallar deg ikkje Pashur, men Magor Missabib.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'For so segjer Herren: Sjå, eg gjer deg til ei rædsla for deg sjølv og for alle venerne dine, og dei skal falla for fiendesverd midt framfor dine augo. Og alt Juda vil eg gjeva i Babel-kongens hand, og han skal føra deim i utlægd til Babel og slå deim med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Og eg vil gjeva alt godset i denne byen og alt dei hev stræva i hop og alle deira eignaluter og alle skattarne åt Juda-kongarne - det vil eg gjeva i henderne på deira fiendar. Og dei skal rana deim og taka deim og føra deim til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Og du, Pashur, og alle som bur i ditt hus skal verta fangar. Og til Babel skal du koma, og der skal du døy, og der skal du verta gravlagd, du og alle venerne dine, som du spådde lygn for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Du lokka meg, Herre, og eg let meg lokka, du bruka magti på meg og vann. Eg hev vorte til låtteløgje all dagen, alle so spottar dei meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'For so ofte som eg talar, lyt eg skrika, um vald og tjon lyt eg ropa, for Herrens ord hev vorte meg til håd og spott all dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Difor sagde eg: «Eg vil ikkje koma honom i hug og ikkje lenger tala i hans namn.» Men då vart det i hjarta mitt som ein logande eld, innestengd i mine bein, og eg møddest med å tola det, men kunde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'For eg høyrde mange baktala - rædsla rundt i kring: «Klaga honom, lat oss ganga og klaga honom!» Alle dei menner eg livde i fred med, gjætte på um eg ikkje skulde falla: «Kann henda let han seg lokka, so me kann vinna på honom og hemna oss på honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Men Herren er med meg lik ei veldug kjempa, difor skal forfylgjarane mine snåva og ikkje vinna. Dei vert ovleg til skammar for di dei ikkje for visleg åt - ei æveleg, ugløymande skjemsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Og Herren, allhers drott, røyner med rettferd, han ser nyro og hjarta. Eg skal få sjå din hemn på deim; for eg hev lagt saki mi fram for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Syng for Herren, lova Herren! For han hev fria sjæli åt armingen ut or henderne på illgjerningsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Forbanna vere den dagen då eg vart fødd! Den dagen mor mi fødde meg, vere ikkje velsigna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Forbanna vere den mann som kom med det gledebodet til far min: «Du hev fenge ein son,» og soleis gledde honom storleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Med den mannen verte det likeins som med dei byarne Herren støytte i koll utan trege, og han høyre naudrop um morgonen og hergny ved høgstdags leite,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'for di han ikkje drap meg alt i moderlivet, so mor mi vart mi grav, og livet hennar æveleg fremmelegt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Kvi kom eg då ut or moderlivet til å sjå møda og sorg og enda mine dagar i skam?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Det ordet som kom til Jeremia frå Herren, då kong Sidkia sende honom Pashur Malkiason og presten Sefanja Ma’asejason og let segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '«Spør Herren for oss, for Nebukadressar, Babel-kongen, strider mot oss. Kann henda Herren kunde gjera med oss etter alle sine underverk, so han fer burt ifrå oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Då sagde Jeremia med deim: So skal de segja med Sidkia:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'So segjer Herren, Israels Gud: Sjå, eg snur attende dei stridsvåpn som er i henderne dykkar, og som de strider med utanfor muren mot Babel-kongen og kaldæarane, som kringset dykk, og eg vil samla deim midt i denne byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Og eg vil sjølv strida mot dykk med utrett hand og med sterk arm og med vreide og med harm og med stor gram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Og eg vil slå deim som bur i denne byen, både folk og fe; i ei stor sott skal dei døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Og sidan, segjer Herren, vil eg gjeva Sidkia, Juda-kongen, og tenarane hans og folket og deim som er leivde i denne byen etter sotti, sverdet og svolten, i henderne på Nebukadressar, Babel-kongen, og i henderne på fiendarne deira og i henderne på deim som ligg deim etter livet. Og han skal slå deim med sverd-egg, han skal ikkje miskunna deim og ikkje vårkunna og ikkje tykkja synd i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Og til dette folket skal du segja: So segjer Herren: Sjå, eg legg fram for dykk vegen til livet og vegen til dauden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Den som vert verande i denne byen, skal døy for sverd og av svolt og i sott, men den som gjeng ut og gjev seg til kaldæarane som kringset dykk, han skal liva, og han skal njota sitt liv til eit herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'For eg hev sett mi åsyn imot denne byen til det vonde og ikkje til det gode, segjer Herren; i henderne på Babel-kongen vert han gjeven, og han skal brenna honom upp i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Og med Juda-kongens hus skal du segja: Høyr Herrens ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'du Davids hus! So segjer Herren: Set retten kvar morgon, og berga utor valdsmanns hand den som er utplundra, so ikkje harmen min skal fara ut som eld, og brenna so ingen kann sløkkja! - for illgjerningarne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Sjå, eg skal finna deg, du som bur i dalen, uppå berget på sletta, segjer Herren - de som segjer: «Kven kann koma ned yver oss, kven kann koma inn i bustaderne våre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Og eg vil heimsøkja dykk etter den frukti dykkar verk hev bore, segjer Herren, og setja eld i skogen deira, og han skal øyda alt der rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'So sagde Herren: Gakk ned til Juda-kongens hus og tala der dette ordet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'og seg: Høyr Herrens ord, du Juda-konge som sit på Davids kongsstol, du sjølv og tenarane dine og folket ditt, de som gjeng inn um desse portar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'So segjer Herren: Gjer rett og rettferd og berga ut or valdsmanns hand den som er utplundra, og far ikkje fram med urett og vald mot den framande, den farlause og enkja, og renn ikkje ut skuldlaust blod på denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'For um de gjer etter dette ordet, då skal kongar som sit på Davids kongsstol koma inn um portarne til dette huset på vogner og hestar - han sjølv og tenarane hans og folket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Men um de ikkje høyrer desse ordi, då sver eg ved meg sjølv, segjer Herren, at dette huset skal verta i øyde lagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'For so segjer Herren um Juda-kongens hus: Eit Gilead er du for meg, ein tind på Libanon; men i sanning, eg vil gjera deg til ei øydemark med byar der ingen bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Og eg vil vigja tynarar mot deg, kvar med sine våpn, og dei skal hogga dei gilde cedertrei dine og kasta deim på elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Og mange heidningfolk skal ganga framum denne byen, og dei skal segja med kvarandre: «Kvi hev Herren fare soleis åt med denne store byen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Og dei skal svara: «For di dei vende seg frå Herren, sin Guds pakt, og tilbad andre gudar og tente deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Gråt ikkje yver ein avliden og barma dykk ikkje for honom; men gråt yver den som burt er faren! for han skal ikkje meir koma att og sjå sitt fødeland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'For so segjer Herren um Sallum Josiason, Juda-kongen, som vart konge etter Josia, far sin, og som burt er faren frå denne staden: Han skal ikkje meir koma hit att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'men på den staden som dei førde honom fange til, der skal han døy, og dette landet skal han ikkje meir få sjå att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Usæl han som byggjer sitt hus med urett og sine salar med rangt, som let sin næste træla for inkje og ikkje gjev honom løni hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'som segjer: «Eg vil byggja meg eit stort hus og rome salar,» og høgg seg ut vindaugo på det og klæder det med cedertre og målar det med raudmåling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Er du konge for di du kann kappbyggja i cedertre? Far din - åt ikkje han og drakk og gjorde rett og rettferd? Då gjekk det honom vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Han hjelpte armingen og fatigmannen til sin rett, då gjekk det vel. Er ikkje slikt å kjenna meg? segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Men augo dine og hjarta ditt stend ikkje etter anna enn etter vinningi di og etter å renna ut skuldlaust blod og etter å fara med valdsverk og trælking.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Difor, so segjer Herren um Jojakim Josiason, Juda-kongen: Dei skal ikkje barma seg for honom: «Ai, bror min! Ai, syster mi!» Dei skal ikkje barma seg for honom: «Ai, Herre! Ai, hans herlegdom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Liksom ein jordar eit asen, skal han verta jorda; dei skal dragsa honom ut og kasta honom burt langt utanfor Jerusalems-portarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Stig upp på Libanon og ropa, og lat røysti di ljoma i Basan, og ropa frå Abarim! For alle elskarane dine er sundkrasa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Eg tala til deg medan det gjekk deg vel, men du sagde: «Eg vil ikkje høyra.» Det var vegen din alt frå din ungdom, at du ikkje høyrde mi røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Alle hyrdingarne dine skal få ein storm til hyrding, og elskarane dine skal verta fangar; ja, då skal du verta skjemd og til skammar for all vondskapen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Du som bur på Libanon, som hev reiret ditt i cedertrei, å, kor du skal stynja når du fær rider, flagor som kvinna i barnsnaud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'So sant som eg liver, segjer Herren, um so du Konja Jojakimsson, Juda-konge, var ein signetring på høgre handi mi, vilde eg riva deg der ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Og eg vil gjeva deg i henderne på deim som ligg deg etter livet, og i henderne på deim som du ræddast, i henderne på Nebukadressar, Babel-kongen, og i henderne på kaldæarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Og eg vil slengja deg og mor di, som fødde deg, burt i eit anna land, der som de ikkje er fødde, og der skal de døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Men til det landet som dei stundar å koma attende til, dit-att skal dei aldri koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Er då denne mannen Konja eit vanvyrdt, sundbrote fat, eller eit kjerald som ingen hev hugnad i? Kvi er dei burtkasta, han og avkjømet hans, og slengde burt til det landet som dei ikkje kjende?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Land, land, land, høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'So segjer Herren: Skriv upp denne mannen barnlaus, ein uheppen mann all sin dag. For ingen av hans avkjøme skal få lukka til å sitja i Davids kongsstol og heretter rikja yver Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Usæle dei hyrdingar som tyner og spreider gjætsle-hjordi mi, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Difor, so segjer Herren, Israels Gud, um hyrdingarne som gjæter folket mitt: De hev spreidt sauerne mine og jaga deim burt og ikkje set etter deim. Sjå, eg heimsøkjer dykk for den vonde åtferdi dykkar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Men sjølv vil eg samla det som er att av sauerne mine or alle dei landi som eg hev drive deim til, og venda deim attende til si eigi beitemark, og dei skal veksa og aukast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Og eg vil setja hyrdingar yver deim, og dei skal gjæta deim. Og dei skal ikkje lenger ræddast eller taka fæla, og ingen av deim skal verta sakna, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Sjå, dei dagar skal koma, segjer Herren, då eg vil lata ein rettferdig renning standa fram åt David, og han skal vera konge og fara visleg åt og gjera rett og rettferd i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'I hans dagar skal Juda verta frelst og Israel bu trygt, og dette er namnet hans, det dei kallar honom: «Herren, vår rettferd».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Difor, sjå, dei dagar skal koma, segjer Herren, då dei ikkje lenger skal segja: «So sant som Herren liver, som leidde Israels-borni ut or Egyptarlandet,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'men: «So sant som Herren liver, som leidde avkjømet åt Israels hus ut og let deim koma frå Norderland og frå alle landi som eg hadde drive deim til, so dei fær bu i landet sitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Um profetarne. Hjarta i mitt brjost er sundkrasa, alle beini mine skjelv. Eg er lik ein drukken mann, ein mann som vinen hev magtstole, for Herren skuld, for hans heilage ord skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'For landet er fullt av horkarar - ja, under forbanning syrgjer landet, og beitelandi i øydemarki er turrbrende - og dei skundar seg til det som vondt er og er velduge i urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'For både profet og prest er gudlause, jamvel i huset mitt hev eg funne vondskapen deira, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Difor skal vegen deira verta åt deim som sleip-flekkjer i myrkret; dei skal støyta seg so dei dett på honom. For eg vil lata ulukka koma yver deim det året heimsøkjingi kjem, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Hjå profetarne i Samaria hev eg set dårskap; dei spådde ved Ba’al og førde mitt folk Israel på villstig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Men hjå profetarne i Jerusalem hev eg set gruvelege ting; dei driv hor og fer med lygn og styrkjer henderne på illgjerningsmenner, so ingen av deim vender um frå sin vondskap. Dei er alle vortne liksom Sodoma åt meg, og hine ibuarane liksom Gomorra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Difor, so segjer Herren, allhers drott, um profetarne: Sjå, eg gjev deim malurt å eta og eitervatn å drikka. For ifrå profetarne i Jerusalem er gudløysa gjengi ut yver alt landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'So segjer Herren, allhers drott: Lyd ikkje på ordi åt dei profetar som spår åt dykk; dei kjem berre med tomt svall åt dykk; si eigi hjartesyn taler dei, ikkje noko frå Herrens munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Jamt og samt segjer dei med deim som svivyrder meg: «Herren hev tala: Det skal ganga dykk vel.» Og med kvar og ein som ferdast etter sitt harde hjarta, segjer dei: «Nokor ulukka skal det ikkje koma yver dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'For kven av deim hev stade i Herrens råd, so han såg og høyrde hans ord? Kven hev gjeve gaum etter mitt ord og høyrt det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Sjå, ein storm frå Herren - vreide bryt fram - ein kvervelstorm; ned på hovudet åt dei ugudlege kjem han i kvervlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Herrens vreide skal ikkje halda upp fyrr enn han hev gjort og sett i verk sitt hjartans tankar; i dagarn som kjem skal de greinleg skyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Eg sende ikkje profetarne, men dei sprang av stad; eg tala ikkje til deim, men dei spådde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Og hadde dei stade i mitt råd, då vilde dei lata mitt folk høyra mine ord, og snu deim frå deira vonde veg og frå deira vonde verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Er eg ein Gud berre nær ved, segjer Herren, og ikkje ein Gud langt burte?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Eller kann nokon løyna seg i slike løyne, so eg ikkje kann sjå honom? segjer Herren. Fyller eg ikkje himmelen og jordi? segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Eg hev høyrt kva profetarne hev sagt, dei som spår lygn i mitt namn og segjer: «Eg drøymde, eg drøymde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Kor lenge skal dette vera so? Hev dei eitkvart på hjarta, desse profetarne som spår lygn med di dei spår sitt hjartans svik -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'tenkjer dei kann henda å få mitt folk til å gløyma mitt namn med draumarne sine, som dei fortel kvarandre, likeins som federne deira gløymde mitt namn for Ba’al?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Den profet som hev ein draum, han kann fortelja ein draum, men den som hev mitt ord, han skal tala mitt ord i sanning. Kva hev halmen med kornet å gjera? segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Er ikkje mitt ord som ein eld, segjer Herren, og som ein hamar som krasar berg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Difor, sjå, eg skal finna profetarne, segjer Herren, dei som stel ordi mine ein frå hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Sjå, eg skal finna profetarne, segjer Herren, dei som tek sitt eige på tunga, men segjer: «So segjer Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Sjå, eg skal finna deim som spår lygn-draumar, segjer Herren, og fortel deim og fører mitt folk på villstig med lygnerne sine og kytet sitt, endå eg ikkje hev sendt deim eller gjeve deim noko påbod, og dei ikkje er til minste gagn for dette folket, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Og når dette folket eller ein profet eller prest spør deg og segjer: «Kva er Herrens byrd?» då skal du segja med deim: «De er byrdi, og eg vil kasta dykk av, segjer Herren».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Og den profet og den prest og det folk som segjer: «Herrens byrd» - slik ein mann og hans hus vil eg heimsøkja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'So skal de segja kvar med sin granne og kvar med sin bror: «Kva hev Herren svara?» eller: «Kva hev Herren tala?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Men «Herrens byrd» skal de ikkje nemna lenger. For åt kvar mann skal hans eige ord verta «byrdi», for di de hev rengt ordi frå den livande Gud, Herren, allhers drott, vår Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'So skal du segja med profeten: «Kva hev Herren svara deg?» eller: «Kva hev Herren tala?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Men segjer de: «Herrens byrd», då segjer Herren so: Av di de segjer dette ordet: «Herrens byrd», endå at eg gjorde denne bodsendingi åt dykk: «De skal ikkje segja «Herrens byrd,»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'difor, sjå, so vil eg reint gløyma dykk og kasta dykk og byen som eg gav dykk og federne dykkar, burt frå mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Og eg vil leggja på dykk ei æveleg skjemd og ei æveleg skam, som aldri skal gløymast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Herren let meg sjå: Tvo korger med fikor var sette framfor Herrens tempel, då Nebukadressar, Babel-kongen, hadde fanga Jekonja Jojakimsson, Juda-kongen, og Juda-hovdingarne, og timbremennerne og smedarne, og ført deim frå Jerusalem til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'I den eine korgi var det fikor av beste slag, like dei fyrst mogne fikorne, men i den andre korgi fikor av låkaste slag, so låke at dei ikkje var etande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Då sagde Herren med meg: Kva ser du, Jeremia? Og eg svara: «Fikor; dei gode fikorne er av beste slag, men dei låke er av låkaste slag, so låke at dei ikkje er etande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Då kom Herrens ord til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'So segjer Herren, Israels Gud: Likeins som med desse gode fikorne, soleis vil eg sjå på dei burtførde av Juda som eg hev sendt frå denne staden til Kaldæarlandet, til deira bate.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Eg vil retta augo mine på deim til deira bate og lata dei venda attende til dette landet. Og eg vil byggja deim upp og ikkje riva deim ned att, og planta deim og ikkje rykkja deim upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Og eg vil gjeva deim hjarta til å kjenna meg, at eg er Herren. Og dei skal vera mitt folk, og eg vil vera deira Gud; for dei skal venda um til meg av alt sitt hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Og likeins som med låke fikor som er so låke at dei ikkje er etande, - ja so segjer Herren - soleis vil eg gjera med Sidkia, Juda-kongen, og hovdingarne hans og leivningen av Jerusalem, dei som er att i dette landet, og dei som bur i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Og eg vil gjera deim til ei skræma og ein stygg for alle riki på jordi, til ei hæding og eit ordtøke, til ei spott og ei våbøn på alle dei stader som eg driv deim burt til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Og eg vil senda imot deim sverdet og svolten og sotti, til dei vert reint utrudde or landet som eg gav deim og federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Det ordet som kom til Jeremia um all Juda-lyden i det fjorde styringsåret åt Jojakim Josiason, Juda-kongen, det er fyrste styringsåret åt Nebukadressar, Babel-kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'og som profeten Jeremia tala til heile Juda-folket og til alle Jerusalems-buarne; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Frå det trettande styringsåret åt Josia Amonsson, Juda-kongen, og alt til denne dag, no i tri og tjuge år, hev Herrens ord kome til meg, og eg hev tala til dykk jamt og samt, men de vilde ikkje høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Og Herren sende til dykk alle tenararne sine, profetarne, jamt og samt, men de vilde ikkje høyra og lagde ikkje øyra til, so de kunde høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Han sagde: Vend um, kvar og ein frå sin vonde veg og frå dykkar vonde åtferd! so skal de få bu i det landet som Herren gav dykk og federne dykkar frå æva og til æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Og ferdast ikkje etter andre gudar, so de tener og tilbed deim, og gjer meg ikkje harm med slikt som henderne dykkar hev gjort! so eg ikkje skal gjera dykk noko ilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Men de lydde ikkje på meg, segjer Herren, men de vilde harma meg med slikt som henderne dykkar hev gjort dykk sjølve til tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Difor, so segjer Herren, allhers drott: Av di de ikkje lydde på mine ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'sjå, so sender eg bod etter alle ætterne i Nordheimen og fær deim hit, segjer Herren, og etter Nebukadressar, tenaren min, og eg let deim koma yver dette landet og yver deim som bur her, og yver alle desse folki rundt ikring. Og eg bannstøyter deim og gjer deim til ein fælske og ei spott og til ævelege audner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Og eg vil gjera det audt hjå deim for fagnadrøyst og glederøyst, røyst av brudgom og røyst av brur, handkvern-dur og lampeljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Og alt dette landet skal verta til audn og øyda, og desse folki skal tena Babel-kongen i sytti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Og når sytti år er lidne, vil eg heimsøkja Babel-kongen og dette folket for deira misgjerningar, segjer Herren, og Kaldæarlandet vil eg heimsøkja og gjera det til ævelege øydemarker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Og eg vil lata koma yver det landet alle ordi mine som eg hev tala um det, alt som er skrive i denne boki, det som Jeremia hev spått um alle folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'For velduge folk og store kongar skal trælka deim og, og eg vil gjeva deim lika for deira verk og for det henderne deira hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'For so sagde Herren, Israels Gud, med meg: Tak dette staupet med vreide-vin or mi hand og lat alle folkeslagi som eg sender deg til, drikka av det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Og dei skal drikka og raga og rasa for det sverdet som eg sender ibland deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Eg tok då staupet or Herrens hand og let alle dei folki drikka som han sende meg til:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalem og byarne i Juda og kongarne og hovdingarne der, for å gjera deim til audn og øyda, til ei spott og til ei våbøn - so som det er den dag i dag -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Farao, egyptarkongen, og hans tenarar og hovdingar og all landslyden hans');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'og alt blandingsfolket hans og alle kongarne i Us-landet og alle kongarne i Filistarlandet og Askalon og Gaza og Ekron og det som er att av Asdod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edom og Moab og Ammons-sønerne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'og alle kongarne i Tyrus og alle kongarne i Sidon og kongarne på havstrenderne, burtanfor havet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedan og Tema og Buz og alle med rundklypt hår');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'og alle kongarne i Arabia og alle kongarne yver blandingsfolket som bur i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'og alle kongarne i Zimri og alle kongarne i Elam og alle kongarne i Media');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'og alle kongarne i Nordheimen, dei nærbuande og dei burtlengste, ein med hin, ja, alle riki i verdi utyver jordflata. Og Sesak-kongen skal drikka etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Og du skal segja med deim: So segjer Herren, allhers drott, Israels Gud: Drikk til de vert drukne og spyr, og dett so de ikkje kann standa upp att - for sverdet som eg sender ibland dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Men vil dei ikkje taka staupet or di hand og drikka, då skal du segja med deim: So segjer Herren, allhers drott: Drikka skal de.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'For sjå, eg let ulukka fyrst råka den byen som er uppkalla etter mitt namn - og so skulde de sleppa å umgjelda! De skal ikkje sleppa å umgjelda, for sverd byd eg ut imot alle som bur på jordi, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Og du skal kunngjera for deim alle desse profetordi. Og du skal segja med deim: Herren skal bura frå høgdi og lata si røyst ljoma frå sin heilage bustad, ja, han skal stor-bura yver sitt beiteland, setja i med eit rop, liksom når dei trøder vinpersa, imot alle som bur på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Det omar av ein dyn alt til enden av jordi, for Herren hev ei trætta med folki, han gjeng til doms med alt kjøt; han let sverdet få dei ugudlege, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'So segjer Herren, allhers drott: Sjå, ei ulukka gjeng ut frå folk til folk, og eit brotver kjem frå dei ytste endarne av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Og dei som Herren hev slege den dagen, skal liggja daude frå eine enden av jordi til hin; ingen skal gråta yver deim eller samla deim i hop og jorda deim; til møk utyver marki skal dei verta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Barma dykk, de hyrdingar, og ropa, og velt dykk i moldi, de gjævingar i hjordi! for tidi til å slagta dykk er komi. Og eg vil spreida dykk, og de skal detta ned liksom eit dyrverdigt kjerald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Då vert det ingi livd for hyrdingarne og ingi undankoma for gjævingarne i hjordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Høyr kor hyrdingarne ropar, kor gjævingarne i hjordi øyar seg! For Herren øyder ut beitemarki deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'og dei fredfulle engjarne vert aude for Herrens brennande vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Fram stig han som ei ungløva ut or si kjørr; ja, landet deira vert til ei audn for det herjande sverdet og for hans brennande vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'I den fyrste tidi som Jojakim Josiason, Juda-kongen, styrde, kom dette ordet frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'So segjer Herren: Gakk i fyregarden til Herrens hus og tala mot Juda-byarne som kjem og tilbed i Herrens hus, tala alle dei ordi som eg hev bode deg å tala til deim! Tak ikkje undan eit einaste ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Må henda dei kunde høyra og snu seg, kvar og ein frå sin vonde veg; då vil eg angra det vonde som eg tenkjer å gjera mot deim for den vonde framferdi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Og du skal segja med deim: So segjer Herren: Um de ikkje høyrer på meg og ferdast i den lovi som eg hev lagt fram for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'so høyrer ordi åt tenarane mine, profetarne, som eg sender dykk jamt og samt, endå de ikkje vil høyra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'då vil eg fara åt med dette huset likeins som med Silo, og alle folkeslag på jord bruka denne byen til ei våbøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Og prestarne og profetarne og alt folket høyrde Jeremia tala desse ordi i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Og då Jeremia hadde tala til endes alt det som Herren hadde bode honom å tala til heile folket, då tok prestarne og profetarne og alt folket honom og sagde: «No skal du døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Kvi hev du spått i Herrens namn og sagt: «Det skal ganga med dette huset likeins som med Silo, og denne byen skal verta øydelagd so ingen bur her?»» Og alt folket samla seg imot Jeremia i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Og då Juda-hovdingarne frette dette, gjekk dei frå kongsgarden upp til Herrens hus og sette seg i inngangen til Herrens port, den nye.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Då sagde prestarne og profetarne med hovdingarne og med alt folket: «Denne mannen er skuldig til å døy; for han hev spått mot denne byen, so som de hev høyrt med dykkar eigne øyro.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Då sagde Jeremia med alle hovdingarne og med alt folket: «Herren hev sendt meg til å spå imot dette huset og denne byen alt det som de hev høyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Lat då dykkar vegar og gjerningar betrast, og høyr på Herren, dykkar Guds røyst! So vil Herren angra det vonde som han hev tala imot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Men eg, sjå, eg er i dykkar hand: gjer med meg det de tykkjer godt og rett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Men det skal de vita, at um de drep meg, so let de skuldlaust blod koma yver dykk og yver denne byen og yver deim som her bur. For Herren hev i sanning sendt meg til dykk å tala for øyro dykkar alle desse ordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Då sagde hovdingarne og alt folket til prestarne og profetarne: «Denne mannen er ikkje skuldig til å døy, for i Herrens, vår Guds, namn hev han tala til oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Og nokre av dei øvste i landet stod upp og sagde til heile folkehopen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '«Mika frå Moreset spådde i dei dagarne då Hizkia var konge i Juda, og sagde til alt folket i Juda: «So segjer Herren, allhers drott: Sion skal verta pløgt til åker, og Jerusalem skal verta til steinrøysar og tempelberget til skograbbar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Tok då Hizkia, Juda-kongen, og alt Juda og drap honom? Ottast han ikkje Herren og blidka Herren, so han angra på det vonde han hadde tala imot deim? Men me held på å koma oss i den største ulukka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Det var og ein annan mann som spådde i Herrens namn, Uria Semajason frå Kirjat-Jearim. Og han spådde mot denne byen og dette landet nett på same måten som Jeremia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Men då kong Jojakim og alle hans kjempor og alle hans hovdingar høyrde ordi hans, so vilde kongen drepa honom. Men då Uria frette det, vart han rædd og flydde burt kom til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Då sende kong Jojakim nokre menner til Egyptarland, Elnatan Akborsson og menner med honom inn i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Og dei tok Uria ut or Egyptarlandet og for med honom til kong Jojakim, og han let drepa honom med sverd og kasta liket hans millom ålmuge-graverne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Men Ahikam Safansson heldt si hand yver Jeremia, so han ikkje vart gjeven i henderne på folket og miste livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'I den fyrste tidi som Sidkia Josiason, Juda-kongen, styrde, kom dette ordet til Jeremia frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'So sagde Herren med meg: Gjer deg band og ok, og hav det um halsen din!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Send dei so til kongen i Edom og til kongen i Moab og til kongen yver Ammons-sønerne og til kongen i Tyrus og til kongen i Sidon med dei sendemennerne som kjem til Jerusalem til Sidkia, Juda-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Og bed deim segja med herrarne sine: So segjer Herren, allhers drott, Israels Gud: So skal de segja med herrarne dykkar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Eg hev gjort jordi, menneskja og dyri på jordi med mi store magt og min strake arm, og eg gjev dette til den eg tykkjer er den rette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Og no hev eg gjeve alle desse landi i henderne på Nebukadnessar, Babel-kongen, tenaren min; jamvel dyri på marki hev eg gjeve honom, so dei kann tena honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Og alle folki skal tena honom og sonen hans og sonesonen hans, til dess tidi for hans land og er komi; då skal velduge folk og store kongar gjera honom til træl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Og det folket og det riket som ikkje vil tena honom, Nebukadnessar, Babel-kongen, og som ikkje vil bøygja halsen sin under Babel-kongens ok, det folket vil eg heimsøkja med sverd og svolt og sott, segjer Herren, til eg hev gjort ende på deim ved hans hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Og de no - lyd ikkje på profetarne dykkar og spåmennerne dykkar og på draumarne dykkar og på runekallarne og tauvrekallarne dykkar, som segjer med dykk: «De kjem ikkje til å tena Babel-kongen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'For lygn er det dei spår åt dykk, for at eg skal føra dykk langt burt frå landet dykkar og driva dykk burt, so de vert tynte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Men det folket som bøygjer halsen sin under Babel-kongens ok og tener honom, det vil eg lata vera i fred i landet sitt, segjer Herren, so dei kann dyrka det og bu i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Og til Sidkia, Juda-kongen, tala eg alle desse ordi og sagde: Bøyg halsen dykkar under Babel-kongens ok, og ten honom og folket hans! då skal de få liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Kvi vil de døy, du og folket ditt, for sverd, av svolt og i sott, so som Herren hev tala um det folket som ikkje vil tena Babel-kongen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Lyd ikkje på ordi åt dei profetarne som segjer med dykk: «De kjem ikkje til å tena Babel-kongen!» For lygn er det dei spår åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'For eg hev ikkje sendt deim, segjer Herren, men dei spår lygn i mitt namn, for at eg skal driva dykk burt, so de vert tynte, de og dei profetarne som spår åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Og til prestarne og heile dette folket tala eg og sagde: So segjer Herren: Lyd ikkje på ordi åt profetarne dykkar når dei spår åt dykk og segjer: «Sjå, kjeraldi or Herrens hus vert no snart flutte heim att frå Babel!» for lygn er det dei spår åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Lyd ikkje på deim, men ten Babel-kongen! So skal de få liva. Kvi skal denne byen verta til ei audn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Men um dei er profetar og hev Herrens ord, so kann dei beda Herren, allhers drott, at ikkje dei kjeraldi som er att i Herrens hus og i Juda-kongens hus og i Jerusalem, vert førde til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'For so segjer Herren, allhers drott, um sulorne og um havet og understelli og alle hine ting som endå er att i denne byen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'som Nebukadnessar, Babel-kongen, ikkje tok då han førde Jekonja Jojakimsson, Juda-kongen, i utlægd frå Jerusalem til Babel i lag med alt storfolket i Juda og Jerusalem -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'ja, so segjer Herren, allhers drott, Israels Gud, um dei kjeraldi som er att i Herrens hus og i Juda-kongens hus og i Jerusalem:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Til Babel skal dei verta flutte, og der skal dei vera alt til den dagen eg ser etter deim, segjer Herren, og fører deim upp og attende til denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'So hende det same året, i den fyrste tidi Sidkia Josiason, Juda-kongen, styrde, i det fjorde året, i den femte månaden, at Hananja Azzursson, profeten frå Gibeon, sagde med meg i Herrens hus beint upp i augo på prestarne og alt folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'So segjer Herren, allhers drott, Israels Gud: Eg hev brote sund Babel-kongens ok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Um tvo år vil eg føra attende til denne staden alle dei kjeraldi som Nebukadnessar, Babel-kongen, hev teke or Herrens hus og førd frå denne staden til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Og Jekonja Jojakimsson, Juda-kongen, og alle hine burtførde frå Juda som er komne til Babel, let eg koma attende til denne staden, segjer Herren; for eg bryt sund Babel-kongens ok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Då svara profeten Jeremia profeten Hananja beint uppi augo på prestarne og alt folket som stod i Herrens hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'og profeten Jeremia sagde: «Amen! Det gjere Herren! Herren setje i verk det som du hev spått so han fører attende frå Babel til denne staden kjeraldi or Herrens hus og alle dei burtførde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Men høyr no på dette ordet som eg talar i opne øyro på deg og alt folket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Dei profetarne som hev vore fyre meg og deg frå ævordsleg tid, dei spådde mot velduge land og store rike um ufred og ulukka og sott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Den profeten som spår um fred - når ordi åt den profeten sannar seg, då er det skynande at Herren i sanning hev sendt den profeten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Då tok profeten Hananja oket av halsen på profeten Jeremia og braut det sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Og Hananja sagde beint uppi augo på alt folket: «So segjer Herren: Soleis vil eg, fyrr tvo år er lidne, brjota sund Nebukadnessars, Babel-kongens, ok av halsen på alle folki.» Då gjekk profeten Jeremia sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Men Herrens ord kom til Jeremia etter profeten Hananja hadde brote sund oket av halsen på profeten Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '«Gakk og seg med Hananja: So segjer Herren: Eit tre-ok hev du brote sund, men att-istaden hev du laga eit jarn-ok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'For so segjer Herren, allhers drott, Israels Gud: Eit jarn-ok hev eg lagt på halsen åt alle desse folki, for at dei skal tena Nebukadnessar, Babel-kongen, so dei lyt tena honom; ja, jamvel dyri på marki hev eg gjeve honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Då sagde profeten Jeremia med profeten Hananja: «Høyr, du Hananja! Herren hev ikkje sendt deg, men du hev fenge dette folket til å lita på lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Difor, so segjer Herren so: Sjå, eg tek deg burt frå jordi; i dette året skal du døy, for du hev preika fråfall frå Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Og profeten Hananja døydde same året i den sjuande månaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Og dette er ordi i det brevet som profeten Jeremia sende frå Jerusalem til deim som endå livde att av dei øvste millom dei burtførde, og til prestarne og profetarne og alt det folket som Nebukadnessar hadde ført burt frå Jerusalem til Babel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'då kong Jekonja og kongsmori og hirdmennerne, dei høgste i Juda og Jerusalem og timbremennerne og smedarne var farne burt or Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Brevet sende han med El’asa Safansson og Gemarja Hilkiason, som Sidkia, Juda-kongen, sende til Nebukadnessar, Babel-kongen, til Babel; det lydde so:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'So segjer Herren, allhers drott, Israels Gud, til alle dei burtførde som eg hev ført burt frå Jerusalem til Babel:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bygg hus og bu i deim, planta hagar og et frukti av deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Tak dykk konor og avla søner og døtter, og tak konor åt sønerne dykkar, og gift burt døtterne dykkar, so dei kann få søner og døtter, so de kann fjølgast der og ikkje minka i tal!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Og stræva etter det, at det må ganga den byen vel som eg hev ført dykk burt til, og bed for honom til Herren! For når det gjeng honom vel, so gjeng det dykk vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'For so segjer Herren, allhers drott, Israels Gud: Lat dykk ikkje dåra av dei profetarne som er hjå dykk og av spåmennerne dykkar, og gjev ikkje gaum etter draumarne dykkar som de drøymer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'For lygn er det som dei spår åt dykk i mitt namn, og eg hev ikkje sendt deim, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'For so segjer Herren: Når sytti år er lidne for Babel, vil eg vitja dykk og gjera sannrøynt på dykk det gode ordet mitt um å lata dykk koma tilbake til denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'For eg veit kva tankar eg hev med dykk, segjer Herren, tankar til fred og ikkje til tjon, å gjeva dykk framtid og von.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Og de skal påkalla meg og ganga og beda til meg, og eg vil høyra på dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Og de skal søkja meg og finna meg, når de spør etter meg av alt dykkar hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Eg vil då lata dykk finna meg, segjer Herren, og eg vil gjera ende på utlægdi dykkar og samla dykk frå alle dei folki og or alle dei staderne som eg hev drive dykk burt til, segjer Herren, og lata dykk venda tilbake til den staden som eg førde dykk burt ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'For de segjer: «Herren hev reist upp profetar åt oss i Babel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'For so segjer Herren um kongen som sit på Davids kongsstol og um alt folket som bur i denne byen, brørne dykkar som ikkje vart burtførde saman med dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'so segjer Herren, allhers drott: Sjå, eg sender imot deim sverd og svolt og sott og gjer med deim som ein gjer med dei utskjemde fikorne som er so låke at dei ikkje er etande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Og eg elter deim med sverd, med svolt og med sott, og eg vil gjera deim til ei skræma for alle riki på jord, til ei våbøn og ein støkk, og til ei spott og ei hæding millom alle dei folki som eg driv deim til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'for di at dei lydde ikkje på mine ord, segjer Herren, då eg sende tenarane mine, profetarne, til deim, jamt og samt, men de høyrde ikkje, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Men høyr no de Herrens ord, alle de burtførde som eg hev sendt frå Jerusalem til Babel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'So segjer Herren, allhers drott, Israels Gud, um Ahab Kolajason og um Sidkia Ma’asejason som spår lygn åt dykk i mitt namn: Sjå, eg gjev deim i handi på Nebukadressar, Babel-kongen, og han skal drepa deim framfor dykkar augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Og etter deim skal dei laga ei våbøn, alle dei burtførde or Juda som er i Babel, og segja: «Herren gjere med deg likeins som med Sidkia og Ahab, som Babel-kongen steikte i elden!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'For dei for med skjemdarverk i Israel og dreiv hor med grannekonorne sine og for med lygne-rødor i mitt namn, slikt som eg ikkje hadde sett deim til; eg veit det då og kann vitna um det, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Og dette skal du segja med Semaja, nehelamiten:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'So segjer Herren, allhers drott, Israels Gud: Du hev sendt brev i ditt namn til alt folket i Jerusalem og til presten Sefanja Ma’asejason og til alle prestarne, og sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '«Herren hev sett deg til prest i staden for presten Jojada, so det skal vera tilsynsmenner i Herrens hus yver alle som er frå vitet gjengne og driv på og spår, so du kann setja deim i stokk og halsjarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Kvi hev du då ikkje refst Jeremia frå Anatot som driv og spår åt dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'For på denne måten hev han kunna gjera ordsending til oss i Babel og sagt: «Dette vert ei lang-æva; bygg hus og bu i deim, planta hagar og et frukti or deim!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Og presten Sefanja hadde lese dette brevet upp for profeten Jeremia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Då kom Herrens ord til Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Gjer ordsending til alle dei burtførde og seg: So segjer Herren um Semaja, nehelamiten: Sidan Semaja hev spått åt dykk, endå eg ikkje hev sendt honom, og fenge dykk til å lita på lygn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'difor, so segjer Herren: Sjå, eg heimsøkjer Semaja, nehelamiten, og avkjømet hans; ingen av deim skal få bu millom dette folket, og han skal ikkje få sjå det gode som eg gjer med folket mitt, segjer Herren, for han hev preika fråfall frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Det ordet som kom til Jeremia frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'So segjer Herren, Israels Gud: Skriv deg upp i ei bok alle dei ordi eg hev tala til deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'For sjå, dagar skal koma, segjer Herren, då eg endar utlægdi åt folket mitt, Israel og Juda, og let deim koma heim att til det landet som eg gav federne deira, so dei kann taka det til eign.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Og dette er dei ordi som Herren hev tala um Israel og um Juda:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'So segjer Herren: Eit rædslerop hev me høyrt; otte og ingen fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Spør og sjå etter um ein karmann føder barn! Kvi ser eg då alle mann med henderne på lenderne liksom kvinna i barnsnaud, og kvi er alle andliti vortne nåbleike?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Å! Stor er den dagen, han hev ikkje sin like. Ja, ei trengsletid er det for Jakob, men han skal verta frelst derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Og det skal henda den dagen, segjer Herren, allhers drott, at eg vil brjota oket hans av halsen din, og bandi dine vil eg riva sund. Ja, framande skal ikkje trælka honom lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Men dei skal tena Herren, sin Gud, og David, sin konge, som eg vil reisa upp åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'So ottast ikkje, du min tenar Jakob, segjer Herren, og ræddast ikkje, Israel! For sjå, eg frelser deg frå det burtlengste land og avkjømet ditt frå det landet som dei var burtførde til. Og Jakob skal snu heim att og vera i ro og trygd, og ingen skal skræma honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'For eg er med deg, segjer Herren, til å frelsa deg. For eg vil gjera ende på alle dei folki som eg hev spreidt deg imillom, det er berre deg eg ikkje vil gjera ende på, men eg vil aga deg med måte, men reint utan refsing kann eg ikkje lata deg vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'For so segjer Herren: Ubøtande er skaden din, ulækjande såret ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Ingen tek saki di på seg og kreistar verken ut; det bid ikkje helsebot, ikkje plåster for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Alle elskarane dine hev gløymt deg, dei spør ikkje etter deg. For eg hev slege deg likeins som ein fiende slær, eg hev aga deg som den miskunnlause, for di at misgjerningi di er stor og synderne dine mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Kvi eiar du deg yver skaden din, yver at plåga di er ulækjande? For di at misgjerningi di er stor og synderne dine mange, hev eg gjort deg dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Difor skal alle som et på deg, verta upp-etne, og alle som er trengjer deg, verta burtførde, alle saman, og dei som herjar deg, skal verta herja, og alle som ranar frå deg, vil eg gjeva til ran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'For eg vil grøda såri dine og lækja deg etter slagi du hev fenge, segjer Herren, av di dei kallar deg «den burtdrivne», «Sion som ingen spør etter».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'So segjer Herren: Sjå, eg endar utlægdi for Jakobs tjeld og miskunnar bustaderne hans, og byen skal atter verta bygd på haugen sin, og slottet skal standa på sin rette stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Og det skal ljoma av lovsangar og leikstemne-ljod frå deim. Og eg vil lata deim aukast og ikkje minka, og eg vil æra deim, og dei skal ikkje verta mismætte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Og sønerne hans skal vera som fordom, og lyden hans skal standa grunnfest framfor mi åsyn, og eg vil heimsøkja alle som trengjer honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Og hans herlege skal vera utstokken frå honom sjølv, og drotten hans skal ganga fram or hans eigen flokk. Og eg vil lata honom nærra seg åt meg, so han fær koma til meg; for kven kunde elles vera so hjartug, at han kom meg nær? segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Og de skal vera mitt folk, og eg skal vera dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Sjå, ein storm frå Herren - vreide bryt fram - ein rjukande storm: ned på hovudet åt dei ugudlege kjem han i kvervlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Herrens brennande vreide skal ikkje halda upp fyrr han hev gjort og sett i verk sitt hjartans tankar. I dagarne som kjem, skal de skyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'I den tidi, segjer Herren, skal eg vera Gud for alle ættgreinerne i Israel, og dei skal vera mitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'So segjer Herren: Det folket som slapp undan sverdet, hev funne nåde i øydemarki; eg vil av og få honom, Israel, til å roa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Langt burtanfrå hev Herren openberra seg for meg: Ja, med æveleg kjærleik hev eg elska deg, difor hev eg late mi miskunn mot deg halda ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Enn skal eg byggja deg, so du vert uppatt-bygd, du møy Israel; enn skal du pryda deg med handtrummorne og ganga ut i dansen med dei leikande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Enn skal du planta vinhagar på Samaria-heidarne; dei som plantar, skal hausta og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'For det kjem ein dag då vaktmenner skal ropa på Efraimsfjellet: «Statt upp, og lat oss draga upp til Sion, til Herren, vår Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'For so segjer Herren: Fagna dykk yver Jakob med gleda og set i med fagnadrop yver den fremste av folki! Gjer kunnigt, prisa og seg: «Herre, frels ditt folk, leivningen av Israel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Sjå, eg let deim koma frå Norderlandet og samlar deim frå utkantarne av jordi. Ibland deim er blinde og halte, fremmelege kvende og fødande i lag; i ein stor flokk skal dei koma hit tilbake.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Gråtande skal dei koma og audmjukleg bedande; eg vil fylgja dei; eg vil leida deim til vatsbekkjer på ein jamn veg, der dei ikkje skal snåva. For eg er vorten far åt Israel, og Efraim er min fyrstefødde son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Høyr Herrens ord, de folk, gjer det kunnigt på øyarne langt burte og seg: Han som spreidde Israel, vil samla det og gjæta det likeins som ein hyrding hjordi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'For Herren hev fria Jakob ut og løyst honom ut or henderne på den som var sterkare enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Og dei skal koma og fagna seg på Sionshøgdi, og dei skal strøyma til dei gode ting frå Herren, til korn og til druvesaft og til olje, til unge sauer og naut. Og sjæli deira skal vera lik ein vatsrik hage, og dei skal ikkje ormegtast lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Då skal møyar fegnast i dans, og gutar og gamlingar saman. Og eg skal venda sorgi deira til gleda og hugga deim og gleda deim etter deira sut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Og eg skal kvika prestarne med feite retter, og lyden min skal mettast med mine gode ting, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'So segjer Herren: Ei røyst er høyrd i Rama, ynk, sår gråt; Rakel græt for borni sine. Ho vil ikkje lata seg trøysta for borni sine, for dei er ikkje lenger til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'So segjer Herren: Haldt røysti di frå gråt og augo dine frå tåror! For verket ditt skal få si løn, segjer Herren, og dei skal snu heim att frå fiendeland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Ja, det er von um di framtid, segjer Herren, og borni skal snu heim att innum sine landskil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Eg hev greinleg høyrt kor Efraim barmar seg: «Du hev aga meg, ja, eg er aga som ein utamd kalv. Vend du meg um, so vil eg venda um, for du er Herren, min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'For sidan eg vende meg burt, angrar eg, og sidan eg vitrast, slær eg meg på lendi. Eg blygjest, ja, eg skjemmest, for eg lyt bera skammi frå ungdomstidi mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Er då Efraim meg so kjær ein son eller slikt eit eigna-barn, sidan eg stødt må minnast honom, endå eg ofte hev truga honom? Difor bankar hjarta mitt for hans skuld, eg lyt miskunna honom, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Reis deg vardar, set deg vegvisarar, gjev gaum etter kongsvegen, vegen du gjekk! Snu heim att, du møy Israel, snu heim att til desse byarne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Kor lenge vil du reika der att og fram, du fråfalne dotter? For Herren skaper nytt i landet: Kvinna vernar mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'So segjer Herren, allhers drott, Israels Gud: Enn skal dei segja dette ordet i Judalandet og byarne der, når eg gjer ende på utlægdi deira: «Herren signe deg, du rettferds bustad, du heilage fjell!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Og Juda med alle sine byar skal bu der i lag; bønder og kringfarande hyrdingfolk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'For eg vil kveikja den utmødde sjæl, og alle ormegta sjæler vil eg metta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Ved dette vakna eg og såg meg um, og svevnen min hadde vore blid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Sjå, dei dagar skal koma, segjer Herren, då eg vil så Israelslandet og Judalandet med sæde av menneskje og sæde av dyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Og likeins som eg vakte yver deim til å ryskja upp og riva ned og brjota ned og øyda og plåga deim, soleis vil eg og vaka yver deim til å byggja og planta, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'I dei dagarne skal dei ikkje lenger segja: «Federne åt sure druvor, og borni vart sårtente.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Men kvar og ein skal døy for si eigi misgjerd; kvar den mann som et sure druvor, skal sjølv verta sårtent.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Sjå, det skal koma dagar, segjer Herren, då eg vil gjera ei ny pakt med Israels hus og med Judas hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'ikkje slik ei pakt som den eg gjorde med federne deira den dagen eg tok deim i handi og leidde deim ut or Egyptarlandet, den pakti med meg som dei braut, endå eg var deira rette herre, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Men dette er den pakti som eg vil gjera med Israels hus etter dei dagarne, segjer Herren: Eg vil leggja lovi mi inni deim, og skriva henne i hjarta deira, og eg skal vera deira Gud, og dei skal vera mitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Då skal dei ikkje lenger læra kvar sin granne og kvar sin bror, og segja: «Kjenn Herren!» For dei skal alle kjenna meg, både små og store, segjer Herren; for eg skal forlata deira misgjerning og ikkje lenger minnast deira synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'So segjer Herren som sette soli til å lysa um dagen, månen og stjernorne til å lysa um natti, etter ei fast lov, han som reiser upp havet so bårorne bruser - Herren, allhers drott, er namnet hans:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Dersom desse loverne vik for mi åsyn, segjer Herren, då skal og Israels ætt halda upp med å vera eit folk framfor mi åsyn alle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'So segjer Herren: Dersom himlarne let seg mæla der uppe og grunnvollarne åt jordi let seg ransaka der nede, då skal eg og støyta frå meg all Israels ætt for alt det dei hev gjort, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Sjå, det skal koma dagar, segjer Herren, då byen skal verta bygd åt Herren frå Hananeltårnet alt til Hyrneporten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'og mælesnori skal ganga derifrå beint på yver Garebhaugen, og so bøygja til Goa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Og heile Daudskrott- og Oskedalen og alle markerne burtåt Kidronsbekken alt aust til Hesteport-hyrna, skal vera helga åt Herren. Nokor øyding eller nedrivning skal det ikkje meir vera der i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Det ordet som kom til Jeremia frå Herren i det tiande styringsåret åt Sidkia, Juda-kongen, det er det attande året Nebukadressar var konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Det var ved det leitet at Babel-kongens her kringsette Jerusalem, og profeten Jeremia var innestengd i vaktgarden som høyrde til Juda-kongens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Der hadde Sidkia, Juda-kongen, stengt honom inne med so falne ord: «Kvi spår du og segjer: «So segjer Herren: Sjå, eg gjev denne byen i henderne på Babel-kongen, og han skal taka honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'og Sidkia, Juda-kongen, skal ikkje sleppa or henderne på kaldæarane, men han skal til vissa verta gjeven i henderne på Babel-kongen, og tala med honom, munn mot munn, og sjå honom, auga mot auga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'og til Babel skal han føra Sidkia, og der skal han vera til eg vitjar honom, segjer Herren; når de strider mot kaldæarane, skal lukka ikkje fylgja dykk.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Og Jeremia sagde: «Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Sjå, Hanamel, son åt Sallum, farbror din, kjem til deg og segjer: «Kjøp deg jordi mi i Anatot! For du hev odelsretten til å løysa henne.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Og Hanamel, son åt farbror min, kom etter Herrens ord til meg i vaktgarden og sagde med meg: «Kjøp jordi mi som er i Anatot i Benjaminslandet! For du hev odelsretten, og du hev skyldnaden til å løysa. Kjøp då!» Då skyna eg at det var ord frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Og eg kjøpte jordi av Hanamel, son åt farbror min, i Anatot, og vog sylvet åt honom, syttan sylvdalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'So skreiv eg det i eit kjøpebrev og sette innsigle på og tok vitne og vog sylvet på ei skålvegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Sidan tok eg kjøpebrevet, det innsigla, med avtalen og skilordi, og det opne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'og eg gav kjøpebrevet til Baruk, son åt Neria Mahsejason, for augo på Hanamel, frenden min, og for augo på vitni som hadde skrive under på kjøpebrevet, og alle dei jødarne som sat i vaktgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Og eg bad Baruk for augo på deim og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '«So segjer Herren, allhers drott, Israels Gud: Tak desse brevi, både kjøpebrevet med innsigle og det opne brevet, og legg deim i ei leirkrukka, so dei kann standa seg i lang tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'For so segjer Herren, allhers drott, Israels Gud: Enn skal det verta kjøpt hus og jorder og vinhagar i dette landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Då eg so hadde gjeve Baruk Neriason kjøpebrevet, bad eg til Herren og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Å Herre, Herre! Sjå, du hev gjort himmelen og jordi med di store magt og med din strake arm; ingen ting er for vand for deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'du som gjer miskunn mot tusund på tusund, og for misgjerdi åt federne gjev du borni deira etter deim att uppi fanget, du store, velduge Gud - Herren, allhers drott, er namnet ditt -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'stor i råd og megtig i verk, du som hev augo dine opne yver alle vegarne åt mannsborni, so du kann gjeva kvar mann etter hans veg og etter den grøda hans verk hev bore,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'du som gjorde teikn og under i Egyptarlandet alt til denne dag, både i Israel og med andre menneskje, og gjorde deg namnfræg, so som du er enno i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Og du førde ditt folk ut or Egyptarlandet med teikn og med under og med sterk hand og strak arm og med stor fælska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Og du gav deim dette landet som du hadde svore federne deira å gjeva deim, eit land som fløymer med mjølk og honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Og dei kom og tok det til eiga, men dei høyrde ikkje på di røyst og ferdast ikkje etter loverne dine. Dei gjorde ikkje noko av det du hadde bode deim å gjera. Då let du all denne ulukka koma på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Sjå, umlægringsvollarne er alt komne innåt byen, so dei kann taka honom, og ved sverd og svolt og sott er byen gjeven i henderne på kaldæarane, som strider imot honom. So no er det kome det du truga med, og sjå, du ser det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Og like vel hev du, Herre, Herre, sagt med meg: «Kjøp deg jordi for sylv og tak vitne på det!» - endå byen er gjeven i henderne på kaldæarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Då kom Herrens ord til Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Sjå, eg er Herren, all kjøts Gud: skulde nokon ting vera for vand for meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Difor, so segjer Herren: Sjå, eg gjev denne byen i henderne på kaldæarane og i henderne på Nebukadressar, Babel-kongen, og han skal taka honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Og kaldæarane, som strider mot denne byen, skal koma og setja eld på denne byen og brenna honom med dei husi der dei uppå taki hev brent røykjelse åt Ba’al og rent ut drykkoffer for andre gudar til å harma meg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'For Israels born og Judas born hev berre gjort det som vondt er framfor augo mine, alt frå si ungdomstid, ja, Israels born hev berre harma meg med dei verk deira hender hev gjort, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'For denne byen hev vore til å gjera meg vreid og harm ifrå den dagen dei bygde honom, og alt fram til denne dag, so eg lyt taka honom burt frå mi åsyn');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'for all vondskapen som Israels born og Judas born hev gjort til å harma meg med, dei sjølve, deira kongar, deira hovdingar, deira prestar og deira profetar, Juda-menner og Jerusalems-buar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Og dei snudde ryggen til meg og ikkje andlitet, og endå eg lærde dei jamt og samt, so høyrde dei ikkje, so dei tok age.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Men dei sette sine styggeting i det huset som er uppkalla etter mitt namn, so dei sulka det ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Og dei bygde dei Ba’al-haugarne som er i Hinnomssons-dalen, for dei vilde lata sønerne og døtterne sine ganga gjenom elden for Molek - slikt hadde eg då ikkje påbode, og aldri var det kome meg i hugen at dei skulde gjera slikt eit skjemdarverk og soleis få Juda til å synda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Og no, difor, segjer Herren, Israels Gud, um denne byen som de segjer sofalne ord um: «Han er gjeven i henderne på Babel-kongen ved sverd og svolt og sott»:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Sjå, eg samlar deim ut or alle dei landi som eg hev drive deim til i min vreide og harm og store gram, og eg vil lata deim snu attende til denne staden og bu her trygge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Då skal dei vera mitt folk, og eg skal vera deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Og eg vil gjeva deim eitt hjarta og ein veg, so dei ottast meg alle dagar, til bate for deim sjølve og sønerne deira etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Og eg vil gjera ei ævepakt med deim, at eg aldri skal snu ifrå deim med mine velgjerningar mot deim, og eg vil leggja otte for meg i deira hjarta, so dei ikkje skal vika frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Og eg vil fagna meg yver deim og gjera vel imot deim, og eg vil planta deim i dette landet med truskap, av alt mitt hjarta og av all mi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'For so segjer Herren: Liksom eg hev late all denne store ulukka koma yver dette folket, soleis vil eg og lata alt det gode koma yver deim, som eg hev lova deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Og jorder skal verta kjøpte i dette landet som de kallar «ei audn utan folk og fe, gjevi i henderne på kaldæarane».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Jorder skal dei kjøpa for sylv og skriva kjøpebrev med innsigle på og vitne til i Benjaminslandet og i umkverven kring Jerusalem og i Juda-byarne, både i fjellbyarne og i byarne på flatlendet og i Sudlandet. For eg vil gjera ende på deira utlægd, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Og Herrens ord kom til Jeremia andre gongen medan han endå sat innestengd i vaktgarden; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'So segjer Herren som gjer det, Herren som emnar det til og fullfører det - Herren er namnet hans -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Ropa til meg, so skal eg svara deg og kunngjera for deg store og uskynande ting, som du ikkje hev vit på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'For so segjer Herren, Israels Gud, um husi i denne byen og um husi åt Juda-kongen, som er nedrivne til motråd mot umlægringsvollarne og sverdet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Dei er komne og vil strida mot kaldæarane, men det vert til å fylla husi med liki av dei menner som eg hev slege i min vreide og harm, og som med sin store vondskap hev valda at eg hev løynt mi åsyn for denne byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Sjå, eg vil koma med helsebot og lækjedom og lækja deim, og eg vil syna deim ei ovnøgd med fred og trygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Og eg vil gjera ende på Judas utlægd, og Israels utlægd, og eg vil byggja deim som i fyrstningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Og eg vil reinsa deim for all misgjerningi deira, som dei hev synda mot meg med, og eg vil tilgjeva alle misgjerningarne deira, som dei hev synda mot meg med, og som dei hev forbrote seg mot meg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Og byen skal vera meg til eit fagnad-namn, til pris og til pryda hjå alle folk på jordi som frettar alt det gode som eg gjer deim, og dei skal skjelva og titra for alt det gode og all den freden som eg der lagar til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'So segjer Herren: På denne staden som de kallar «ein øydestad, utan folk og fe», i Juda-byarne og på Jerusalems-gatorne, som ligg i øyde utan folk og utan ibuarar og utan fe, her skal ein få høyra');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'fagnadljod og gledeljod, røyst av brudgom og røyst av brur og røysti av deim som segjer: «Prisa Herren, allhers drott, for Herren er god, for æveleg varar hans miskunn,» slike som ber fram takkoffer i Herrens hus. For eg endar utlægdi for landsens lyd, so han vert som i fyrstningi, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'So segjer Herren, allhers drott: Enn skal på denne staden, som no er aud, utan folk og fe, og i alle byarne her ikring vera hagelende for hyrdingar som der let sauerne roa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'I fjellbyarne, i flatlandsbyarne og i Sudlands-byarne og i Benjaminslandet og i umkverven kring Jerusalem og i Juda-byarne, skal sauerne enn renna framum den som tel deim, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Sjå, det skal koma dagar, segjer Herren, då eg vil gjera sannrøynt det gode ordet som eg hev tala um Israels hus og um Judas hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'I dei dagarne og i den tidi vil eg lata ein rettferdig renning renna upp for David, og han skal gjera rett og rettferd i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'I dei dagarne skal Juda verta frelst og Jerusalem bu trygt, og dei skal kalla det soleis: «Herren er vår rettferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'For so segjer Herren: David skal ikkje vanta ein ettermann som kann sitja på kongsstolen åt Israels hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Og levitprestarne skal aldri vanta ein ettermann framfor mi åsyn som kann ofra brennoffer og grjonoffer og bera fram slagtoffer alle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Og Herrens ord kom til Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'So segjer Herren: Kann de brjota mi pakt med dagen og mi pakt med natti, so det ikkje vert dag og natt i si rette tid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'då skal og mi pakt med min tenar David verta broti, so han ikkje skal hava ein son til konge på sin stol, og med levitprestarne som tener meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Liksom himmelheren ikkje let seg telja, og sanden i havet ikkje let seg mæla, soleis vil eg gjera min tenar Davids ætt til ei ovmengd, og likeins levitarne som tener meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Og Herrens ord kom til Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Hev du ikkje gjeve gaum etter kva dette folket hev tala og sagt: «Båe ættgreinerne som Herren hadde utvalt, hev han støytt frå seg?» Soleis vanvyrder dei folket mitt, som det ikkje lenger var eit folk i deira augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'So segjer Herren: Hev eg ikkje gjort mi pakt med dag og natt, ikkje gjeve lover for himmel og jord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'då vil eg støyta frå meg ætti åt Jakob og åt min tenar David, so eg ikkje av ætti hans tek styresmenner yver ætti åt Abraham og Isak og Jakob. For eg vil enda utlægdi deira og miskunna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Det ordet som kom til Jeremia frå Herren då Nebukadnessar, Babel-kongen, og heile heren hans og alle riki på jordi som han rådde yver, og alle folkeslagi stridde imot Jerusalem og i mot alle hennar byar; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'So segjer Herren, Israels Gud: Gakk og tala til Sidkia, Juda-kongen, og seg med honom: So segjer Herren: Sjå, eg gjev denne byen i henderne på Babel-kongen, og han skal brenna honom upp i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Og du, du skal ikkje sleppa undan honom, men teken skal du verta, og du skal verta gjeven i hans hand, og augo dine skal sjå Babel-kongens augo, og hans munn skal tala med din munn, og til Babel skal du koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Men høyr på Herrens ord, Sidkia, Juda-konge! So segjer Herren um deg: Du skal ikkje døy for sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'I fred skal du døy, og likeins som det var likferd-brenning for federne dine, dei fyrre kongarne, dei som hev vore fyre deg, so skal dei og brenna for deg, og dei skal øya seg for deg: «Å, herre!» for det ordet hev eg tala, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Og profeten Jeremia tala til Sidkia, Juda-kongen, alle desse ordi i Jerusalem');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'då heren åt Babel-kongen stridde imot Jerusalem og imot alle Juda-byarne som endå var att, imot Lakis og Azeka; for desse var dei faste byarne som då var att av Juda-byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Det ordet som kom til Jeremia frå Herren etter kong Sidkia hadde gjort ei semja med alt folket i Jerusalem um å lysa ut fridom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'at kvar mann skulde gjeva trælen sin og trælkvinna si fri, um dei var hebræarar, so ingen jøde skulde halda sin jødiske bror i trældom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Då lydde alle hovdingarne og alt folket som hadde gjort den semja, at kvar mann skulde gjeva trælen sin og trælkvinna si frie, so dei ikkje lenger heldt deim i trældom; dei lydde og gav deim frie.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Men sidan gjorde dei det um-att og tok tilbake dei trælar og trælkvinnor som dei hadde slept frie, og truga deim til å vera trælar og trælkvinnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Då kom Herrens ord til Jeremia frå Herren; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'So segjer Herren, Israels Gud: Eg gjorde ei pakt med federne dykkar den dagen eg førde dei ut or Egyptarlandet, or trælehuset, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '«Når sju år er lidne, skal de gjeva kvar sin bror fri, um han er hebræar, som hev selt seg til deg. I seks år skal han tena deg, men sidan skal du lata honom fri frå deg fara. Men federne dykkar høyrde ikkje på meg og lagde ikkje øyra sitt til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Men no hadde de snutt og gjort det som rett var i mine augo, med di de hadde lyst ut fridom, kvar og ein for bror sin, og de hadde gjort ei semja framfor mi åsyn i det huset som er uppkalla etter mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Men so snudde de um-att og vanhelga namnet mitt og tok tilbake kvar sin træl og kvar si trælkvinna som de hadde slept frie til å fara kvar dei vilde, og de truga deim til å vera trælar og trælkvende åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Difor, so segjer Herren: De hev ikkje høyrt på meg og ropa ut fridom, kvar og ein for sin bror og sin næste; sjå, eg ropar ut fridom for dykk, segjer Herren, so de vert gjevne åt sverdet, åt sotti og åt svolten, og eg vil gjera dykk til ei skræma for alle riki på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'og eg gjev dei menner som braut pakti mi, som ikkje heldt ordi i den pakti dei gjorde framfor mi åsyn, pakti ved den kalven som dei skar i tvo og gjekk millom luterne av,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, '- hovdingarne i Juda og hovdingarne i Jerusalem, hirdmennerne og prestarne og all landslyden som gjekk millom luterne av kalven -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'eg gjev deim i henderne på fiendarne deira og i henderne på deim som ligg deim etter livet, og liki deira skal verta til mat åt fuglarne under himmelen og dyri på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Og Sidkia, Juda-kongen, og hovdingarne hans gjev eg i henderne på deira fiendar og i henderne på deim som ligg deim etter livet, og i henderne på Babel-kongens her, som no er faren burt frå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Sjå, eg gjev deim det påbodet, segjer Herren, at dei skal snu tilbake til denne byen, og dei skal strida imot honom og taka honom og brenna honom upp i eld. Og byarne i Juda gjer eg til ei audn, der ingen bur.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Det ordet som kom til Jeremia frå Herren i Jojakim Josiasons, Juda-kongens, dagar; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Gakk til Rekabs-ætti og tala til deim og kom med deim til Herrens hus, inn i ein av kovarne, og gjev deim vin å drikka!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Då tok eg Ja’azanja, son åt Jeremia Habassinjason, og brørne hans og alle sønerne hans og all Rekabs-ætti');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'og hadde deim med til Herrens hus, inn i koven åt sønerne til gudsmannen Hanan Jigdaljason, den som låg jamsides med hovdingkoven, uppe yver koven åt dørstokkvaktaren Ma’aseja Sallumsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Og eg sette fram for sønerne til Rekabs-ætti skåler, fulle av vin, og staup. So sagde eg med deim: «Drikk vin!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Men dei sagde: «Me drikk ikkje vin, for Jonadab Rekabsson, ættfaren vår, hev bode oss og sagt: «De skal ikkje i all æva drikka vin, korkje de eller borni dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'De skal ikkje heller byggja hus og ikkje så sæde og ikkje planta vinhage eller eiga noko slikt, men i tjeldbuder skal de bu alle dykkar dagar, so de må liva lenge i det landet der de bur som utlendingar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Og me lydde påbodet frå vår ættfar, Jonadab Rekabsson, i alt det han bad oss um, so me aldri drikk vin, korkje me sjølve, konorne våre, sønerne våre eller døtterne våre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'og byggjer oss ikkje hus til å bu i og hev oss ikkje vinhagar eller åkrar eller utsæde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'men me hev butt i tjeldbuder, so me hev lydt og gjort alt det som vår ættfar, Jonadab, baud oss um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Men då Nebukadressar, Babel-kongen, kom farande upp i landet, då sagde me: «Kom, lat oss fara til Jerusalem undan kaldæarheren og undan syrarheren!» So sette me då bu i Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Då kom Herrens ord til Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'So segjer Herren, allhers drott, Israels Gud: Gakk og seg til Juda-mennerne og Jerusalems-buarne: Vil de ikkje taka age so de lyder mine ord? segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Ordi hans Jonadab Rekabsson er haldne, han baud sønerne sine at dei ikkje skulde drikka vin, og dei hev ikkje drukke vin alt til denne dag, men lydt påbodet frå ættfar sin. Og eg hev tala til dykk jamt og samt, men de hev ikkje lydt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Og jamt og samt hev eg sendt til dykk alle mine tenarar, profetarne, og sagt: «Vend um, kvar frå sin vonde veg, og lat verki dykkar betrast, og ferdast ikkje etter andre gudar til å tena deim! då skal de få bu i dette landet som eg hev gjeve dykk og federne dykkar.» Men de lagde ikkje øyra til og lydde ikkje på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Ja, Jonadab Rekabssons born hev halde det bodet som ættfaren deira gav deim, men dette folket hev ikkje lydt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Difor, so segjer Herren, allhers drott, Israels Gud: Sjå, eg let koma yver Juda og yver alle som bur i Jerusalem, all den ulukka som eg hev truga dei med, av di at dei ikkje høyrde når eg tala til deim, og ikkje svara når eg kalla på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Men til Rekabs-ætti sagde Jeremia: So segjer Herren, allhers drott, Israels Gud: Av di at de hev lydt påbodet frå Jonadab, ættfaren dykkar, og halde alle bodi hans og gjort stødt som han baud dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'difor, so segjer Herren, allhers drott, Israels Gud: Jonadab Rekabssons skal aldri vanta ein mann som kann standa framfor mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'So hende det i det fjorde styringsåret åt Juda-kongen Jojakim Josiason at dette ordet til Jeremia frå Herren:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Tak deg ein bokrull og skriv på honom alle dei ordi eg hev tala til deg um Israel og um Juda og um alle heidningefolki frå den dagen eg tala til deg, frå den tidi Josia rådde, og alt til denne dag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Kann henda Judas hus vil lyda på all den ulukka som eg tenkjer å gjera deim, so dei kann venda um, kvar og ein frå sin vonde veg, og eg kann få tilgjeva deim deira misgjerning og synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Då kalla Jeremia til seg Baruk Neriason, og Baruk skreiv i bokrullen etter Jeremias munn alle Herrens ord som han hadde tala til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Og Jeremia bad Baruk og sagde: «Eg sjølv er meinka, eg kann ikkje koma i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Men gakk du dit og les or rullen som du hev skrive etter min munn, Herrens ord for folket i Herrens hus på ein fastedag! Du skal lesa deim for alt Juda, deim som er komne frå byarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Må henda dei kunde leggja si bøn fram for Herrens åsyn og venda seg, kvar og ein frå sin vonde veg. For stor er den vreiden og harmen som Herren hev truga dette folket med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Og Baruk Neriason gjorde plent so som profeten Jeremia hadde bede honom, og las or boki Herrens ord i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'So hende det i det femte styringsåret åt Jojakim Josiason, kongen i Juda, i den niande månaden, at dei lyste på at alt folket i Jerusalem og alt det folk som var kome frå Juda-byarne til Jerusalem, skulde fasta framfor Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Då las Baruk upp or boki Jeremias ord i Herrens hus, i koven åt Gemarja, son åt riksskrivaren Safan, i øvre fyregarden, attmed inngangen til den nye porten på Herrens hus, so alt folket høyrde på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Men då Mikaja, son åt Gemarja Safansson, høyrde alle Herrens ord or boki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'gjekk han ned i kongsgarden, inn i riksskrivarkoven, og sjå, der sat alle hovdingarne: riksskrivaren Elisama og Delaja Sjemajason og Elnatan Akborsson og Gemarja Safansson og Sidkia Hananjason og alle hine hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Og Mikaja kunngjorde for deim alle dei ordi han hadde høyrt, då Baruk las upp or boki medan folket høyrde på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Då sende alle hovdingarne Jehudi, son åt Netanja, son åt Selemja Kusison, til Baruk med denne ordsegni: «Tak med deg den rullen som du las upp for folket, og kom hit!» Og Baruk Neriason tok rullen med seg og kom til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Då sagde dei med honom: «Set deg og les honom for oss!» Og Baruk las for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Men då dei hadde høyrt alle ordi, såg dei forfærde på kvarandre og sagde til Baruk: «Me lyt melda dette til kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'So spurde dei Baruk og sagde: «Seg oss korleis du skreiv alle desse ordi etter hans munn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Og Baruk svara deim: «Med sin munn sagde han meg alle desse ordi fyre, og eg skreiv det i boki med blekk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Då sagde hovdingarne til Baruk: «Gakk og gøym deg og Jeremia med deg, so ingen veit kvar de er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Sidan gjekk dei til kongen i fyregarden - men rullen let dei etter seg i koven åt riksskrivaren Elisama - og melde alt dette for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Då sende kongen Jehudi av stad etter rullen, og han tok honom ut or koven åt riksskrivaren Elisama. Sidan las Jehudi honom upp for kongen og for hovdingarne som stod hjå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Men kongen sat i vinterhalli - det var i den niande månaden - og det brann eld i ei glodpanna framfyre honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Og kvar gong Jehudi hadde lese tri eller fire teigar, skar kongen av rullen med ein pennekniv og kasta stykket på elden i glodpanna, til heile rullen var uppbrend i elden i glodpanna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Og dei ræddast ikkje og reiv ikkje sund klædi sine, korkje kongen eller nokon av tenarane hans som høyrde alle desse ordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Og endå Elnatan og Delaja og Gemarja naudbad kongen, at han ikkje måtte brenna upp rullen, høyrde han ikkje på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Og kongen bad Jerahme’el, kongssonen, og Seraja Azrielsson og Selemja Abde’elsson å taka skrivaren Baruk og profeten Jeremia, men Herren løynde deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Då kom Herrens ord til Jeremia, etter kongen hadde brent upp rullen med dei ordi som Baruk hadde skrive etter Jeremias munn; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Tak deg atter ein annan rull og skriv på honom alle dei fyrre ordi som stod på den fyrre rullen, den som Jojakim, Juda-kongen, brende upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Men um Jojakim, Juda-kongen, skal du segja: «So segjer Herren: Du brende denne rullen og sagde: «Kvi skreiv du på honom dette: Babel-kongen skal koma og øydeleggja dette landet og rydja ut or det folk og fe?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Difor, so segjer Herren um Jojakim, Juda-kongen: Han skal ingen hava som kann sitja på Davids kongsstol, og liket hans skal liggja utkasta i hiten um dagen og i kulden um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Og eg vil heimsøkja honom og avkjømet hans og tenarane hans for deira misgjerning, og eg vil lata koma yver deim og yver Jerusalems-buarne og Juda-mennerne alle dei ulukkor som eg hev truga dei med utan at dei høyrde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Då tok Jeremia ein annan rull og gav honom til skrivaren Baruk Neriason, og han skreiv på honom etter Jeremias munn alle dei ordi som hadde stade i den boki som Jojakim, Juda-kongen, hadde brent upp i eld. Og til deim var det endå lagt mykje av same slaget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Og Sidkia Josiason vart konge etter Konja Jojakimsson, som Nebukadressar, Babel-kongen, hadde gjort til konge i Judalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Men korkje han eller tenarane hans eller landslyden høyrde på Herrens ord, som han tala ved profeten Jeremia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Og kong Sidkia sende Jehukal Selemjason og presten Sefanja Ma’asejason til profeten Jeremia med denne ordsendingi: «Bed for oss til Herren, vår Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jeremia gjekk den-tid ut og inn millom folket, for dei hadde endå ikkje sett honom i fangehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Og Faraos her var då faren ut frå Egyptarland. Og då kaldæarane, som kringsette Jerusalem, frette det, for dei burt frå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Då kom Herrens ord til profeten Jeremia; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'So segjer Herren, Israels Gud: So skal de segja til Juda-kongen, som sende dykk av stad til å spyrja meg: Sjå, Faraos her, som er faren ut til å hjelpa dykk, vil snu um att til landet sitt, til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Og kaldæarane skal og koma att og strida mot denne byen. Og dei skal taka honom og brenna honom upp i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'So segjer Herren: Dåra ikkje dykk sjølve med sofalne ord: «Kaldæarane fer no burt frå oss for ollo!» for dei fer ikkje burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'For um de so slo i hel heile kaldæarheren som strider imot dykk, so det berre var att hjå dei nokre særde menner, då skulde dei risa upp i kvar si tjeldbud og brenna upp denne byen i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'So hende det då kaldæarheren for burt frå Jerusalem for Faraos her,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'at Jeremia gjekk ut or Jerusalem og vilde til Benjaminslandet. Der skulde han taka imot ein arvlut midt ibland folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Men då han kom til Benjaminsporten, so var der ein vaktmann, og han heitte Jeria, son åt Selemja Hananjason. Han treiv i profeten Jeremia og sagde: «Du vil laupa burt til kaldæarane.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Men Jeremia sagde: «Det er lygn, eg vil ikkje laupa burt til kaldæarane!» Men han høyrde ikkje på honom, og Jeria treiv i Jeremia og for med honom til hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Og hovdingarne harmast på Jeremia og slo honom. So sette dei honom i fengsel i huset åt riksskrivaren Jonatan, for det hadde dei gjort til fangehus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Då Jeremia var komen i fangeholet, i kjellaren, og hadde sete der ei lang tid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'sende kong Sidkia bod og let henta honom, og kongen spurde honom i huset sitt i løynd og sagde: «Er det kome noko ord frå Herren?» Jeremia svara: «Ja,» og so sagde han: «Du skal verta gjeven i henderne på Babel-kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Dinæst sagde Jeremia med kong Sidkia: «Kva hev eg synda mot deg og mot tenarane dine og mot dette folket, sidan de hev sett meg i fangehuset?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Og kvar er no profetarne dykkar, som spådde åt dykk og sagde: «Babel-kongen skal ikkje koma yver dykk og yver dette landet?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Og høyr no, herre konge! Å, lat mi bøn koma fram for di åsyn og send meg ikkje attende til huset åt riksskrivaren Jonatan, so eg ikkje skal døy der!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Sidkia gav då påbod, og so sette dei Jeremia i varveitsla i vaktgarden og gav honom ein brødleiv um dagen frå Bakargata, til alt brødet var ende i byen. Jeremia vart då verande i vaktgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Men Sefatja Mattansson og Gedalja Pashursson og Jukal Selemjason og Pashur Malkiason høyrde dei ordi som Jeremia tala til alt folket då han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '«So segjer Herren: Den som vert verande i denne byen, skal døy for sverd og av svolt og i sott, men den som gjeng ut til kaldæarane, skal liva, han skal njota sitt liv til herfang og liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'So segjer Herren: Denne byen skal visseleg verta gjeven i henderne på heren åt Babel-kongen, og han skal taka honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Då sagde hovdingarne med kongen: «Lat deim drepa denne mannen, etter di han gjer folket modlaust, både hermennerne som er att i denne byen og alt det andre folket, med di han talar slike ord til deim. For denne mannen søker ikkje å gagna dette folket, men å skade det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Då sagde Sidkia: «Sjå, han er i dykkar hender, for kongen magtast ikkje noko imot dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Då tok dei Jeremia og kasta honom i brunnen åt kongssonen Malkia, den som var i vaktgarden; dei fira Jeremia ned med tog. Men i brunnen var det ikkje vatn, berre dy, og Jeremia sokk ned i dyet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Men ætiopen Ebed-Melek, ein hirdmann som var i kongsgarden, frette at dei hadde kasta Jeremia i brunnen - kongen sat då i Benjaminsporten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'So gjekk Ebed-Melek ut or kongsgarden og tala til kongen og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '«Herre konge! Illverk hev desse menner fremja med alt det dei hev gjort mot profeten Jeremia som dei hev kasta i brunnen, og der lyt han døy av svolt, for det finst ikkje meir brød i byen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Då bad kongen ætiopen Ebed-Melek og sagde: «Tak med deg herifrå tretti mann og drag profeten Jeremia upp or brunnen, fyrr han døyr.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Og Ebed-Melek tok mennerne med seg og gjekk inn i kongsgarden, i romet under skattkammeret, og tok der fillor av sundrivne og utslitne klæde og fira deim med tog ned i brunnen til Jeremia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Sidan sagde ætiopen Ebed-Melek med Jeremia: «Legg fillorne av dei sundrivne og utslitne klædi under armarne dine, under togi!» Og Jeremia gjorde so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Dei drog då Jeremia upp med togi og fekk honom upp or brunnen. Og no sat Jeremia i vaktgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Sidan sende kong Sidkia bod og let henta profeten Jeremia til seg i den tridje inngangen til Herrens hus. Og kongen sagde med Jeremia: «Eg vil spyrja deg um noko; løyn ikkje noko for meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremia sagde med Sidkia: «Um eg segjer deg det, vil du då ikkje drepa meg? Og um eg gjev deg ei råd, so lyder du ikkje på meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Då gjorde kong Sedekias eiden sin til Jeremia i dulsmål og sagde: «So sant som Herren liver, han som hev skapt oss i dette vårt liv, vil eg ikkje drepa deg og ikkje gjeva deg i henderne på desse menner som ligg deg etter livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Då sagde Jeremia med Sidkia: «So segjer Herren, allhers drott, Israels Gud: Gjeng du ut til Babel-kongens hovdingar, skal du få liva, og denne byen skal ikkje verta uppbrend i eld, men du skal få liva, du og ditt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Men gjeng du ikkje ut til Babel-kongens hovdingar, so skal denne byen verta gjeven i henderne på kaldæarane, og dei skal brenna honom upp i eld, og du sjølv skal ikkje koma deg undan deira hender.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Då sagde kong Sidkia med Jeremia: «Eg ottast dei jødarne som hev gjeve seg yver til kaldæarane, at eg kunde verta gjeven i deira hender, og dei skulde fara stygt åt med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Men Jeremia sagde: «Dei skal ikkje gjera det. Høyr du på Herrens røyst i det eg talar til deg, då skal det ganga deg vel, og du skal få liva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Men dreg du deg undan og ikkje gjeng ut, då er dette det ordet Herren hev synt meg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Sjå, alle dei kvende som er att i Juda-kongens hus, skal verta førde ut til Babel-kongens hovdingar, og sjå, dei skal segja til deg: «Dine eigne vener hev lokka deg og vunne på deg; då føterne dine sokk ned i dya, drog dei seg undan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Og alle konorne dine og borni dine skal dei leida ut til kaldæarane, og du sjølv skal ikkje sleppa undan deira hender, men Babel-kongen skal taka deg med si hand, og for di skuld skal denne byen verta uppbrend i eld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Då sagde Sidkia til Jeremia: «Lat ingen få vita av denne samrøda, elles vert det din bane!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Men når hovdingarne fær høyra at eg hev tala med deg, og dei so kjem til deg og segjer med deg: «Seg oss kva du hev tala med kongen! Løyn det ikkje for oss, elles drep me deg! Kva hev kongen tala til deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'då skal du segja med deim: «Eg bar mi audmjuke bøn fram for kongens åsyn, at han ikkje måtte lata meg fara tilbake til Jonatans hus og døy der.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Og alle hovdingarne kom til Jeremia og spurde honom, han svara deim med kvart det ord som kongen hadde bede honom um. Då let dei honom vera i fred, for saki hadde ikkje vorte kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Og Jeremia sat i vaktgarden alt til den dagen då Jerusalem vart teke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Men dette hende då Jerusalem var teke: I det niande styringsåret åt Juda-kongen Sidkia, i den tiande månaden, kom Nebukadnessar, Babel-kongen, og all hans her til Jerusalem og kringsette det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'I det ellevte styringsåret åt Sidkia, i den fjorde månaden, den niande dagen i månaden, braut dei inn i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Og alle hovdingarne åt Babel-kongen kom og sette seg i Midporten: Nergal-Sareser, Samgar-Nebu, Sarsekim, den øvste hirdmannen, Nergal-Sareser, den øvste av vismennerne, og alle dei hine hovdingarne åt Babel-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Men då Sidkia, Juda-kongen, og alle hermennerne såg deim, flydde dei og for um natti ut or byen på vegen til kongshagen gjenom porten millom båe murarne, og heldt leidi til øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Men kaldæarheren sette etter deim og nådde Sidkia på Jerikomoarne. Og dei tok honom og førde honom upp til Nebukadnessar, Babel-kongen, i Ribla i Hamat-bygdi, og han sagde domen yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Og Babel-kongen let sønerne åt Sidkia drepa i Ribla framfor augo på honom. Sameleis let Babel-kongen alle stormennerne i Juda drepa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Men Sidkia let han blinda og binda med tvo koparlekkjor og føra honom til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Og kaldæarane brende upp i eld både kongsgarden og folkehuset, og murarne kring Jerusalem reiv dei ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Og Nebuzaradan, hovdingen for livvakti, førde burt til Babel den leivningen av folket som var etter i byen, og rømingarne som hadde gjeve seg med honom, og den leivningen av folket som dessforutan var att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Men av ålmugefolk som inkje åtte, let Nebuzaradan, hovdingen for livvakti, nokre etter i Judalandet, og gav deim samstundes vinhagar og åkrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Og Nebukadressar, Babel-kongen, gav Nebuzaradan, hovdingen for livvakti, påbod um Jeremia og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Tak honom og sjå til med honom og gjer honom ikkje noko ilt, men gjer med honom so som han segjer med deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Då sende Nebuzaradan, hovdingen for livvakti, og Nebusazban, den øvste hirdmannen, og Nergal-Sareser, den øvste av vismennerne, og alle hine Babel-kongens hovdingar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, '- dei sende bod og let henta Jeremia frå vaktgarden og gav honom til Gedalja, son åt Ahikam Safansson, at han skulde taka honom med seg heim; soleis vart han då verande hjå folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Men til Jeremia hadde Herrens ord kome medan han sat innestengd i vaktgarden; han hadde sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Gakk og seg til ætiopen Ebed-Melek: So segjer Herren, allhers drott, Israels Gud: Sjå, eg let koma det eg hev tala mot denne byen, til ulukka og ikkje til lukka, og det skal henda framfor augo dine den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Men deg vil eg berga den dagen, segjer Herren, og du skal ikkje verta gjeven i henderne på dei menner som du ræddast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'For eg vil lata deg sleppa undan, og du skal ikkje falla for sverd, men vinna ditt liv til herfang, av di du leit på meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Det ordet som kom til Jeremia frå Herren etter at Nebuzaradan, hovdingen for livvakti, hadde slept honom laus frå Rama, med di han henta honom, då han var bunden med lekkjor i lag med alle hine burtførde frå Jerusalem og Juda som vart burtførde til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Hovdingen for livvakti henta då Jeremia. Og han sagde med honom: «Herren, din Gud, hev truga denne staden med denne ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Og Herren let det koma, og gjorde so som han hadde truga. For de synda mot Herren og lydde ikkje hans røyst, og so råka dette dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Og sjå, no hev eg løyst lekkjorne av henderne dine i dag. Um du er huga på å koma med meg til Babel, so kom, og eg skal sjå til med deg; men um du er uhuga på å koma med meg til Babel, so lat vera. Sjå, alt landet ligg ope for deg; kvar du synest godt og rett å ganga, dit kann du ganga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Men då han drygde med heimferdi, sagde han: «Du må gjerne fara til Gedalja, son åt Ahikam Safansson, som Babel-kongen hev sett yver Juda-byarne, og ver med honom millom folket, eller gakk kvar du synest det er rett å ganga!» Og hovdingen for livvakti gav honom nistemat og gåvor og let honom fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Og Jeremia for til Gedalja Ahikamsson i Mispa og var med honom millom det folket som var etter i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Då so alle herhovdingarne som var ute i bygderne, dei og mennerne deira, frette at Babel-kongen hadde sett Gedalja Ahikamsson yver landet, og at han hadde bede honom sjå til med menner og kvende og born og deim av ålmugen i landet som ikkje var burtførde til Babel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'so for dei til Gedalja i Mispa, både Ismael Netanjason og Johanan og Jonatan Kareahs-søner og Seraja Tanhumetsson og sønerne åt Efai frå Netofa og Jezanja, ma’akatitsonen, og mennerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Og Gedalja, son åt Ahikam Safansson, gjorde deim og mennerne deira eiden sin og sagde: «Det tarv ikkje ottast lydskyldnaden under kaldæarane. Ver i landet og ten Babel-kongen! so skal det ganga dykk vel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Og eg, sjå, eg buar i Mispa, so eg kann taka imot dei kaldæarar som kjem til oss. Men de lyt samla vin og frukt og olje og leggja det i kjeraldi dykkar og vera i byarne dykkar, som de hev teke til eiga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Og alle jødarne som var i Moab og hjå Ammons-sønerne og i Edom og i alle andre land, dei frette og at Babel-kongen hadde late nokre av jødarne vera att, og at han hadde sett yver deim Gedalja, son åt Ahikam Safansson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Alle dei jødarne vende då heim att frå alle staderne som dei var drivne burt til, og kom til Judalandet, til Gedalja i Mispa, og dei samla vin og frukt i store mengder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Men Johanan Kareahsson og alle herhovdingarne som var ute i bygderne, for til Gedalja i Mispa');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'og sagde med han: «Veit du at Ba’alis, kongen yver Ammons-sønerne, hev sendt Ismael Netanjason til å slå deg i hel?» Men Gedalja Ahikamsson trudde deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Og Johanan Kareahsson sagde i løynd med Gedalja i Mispa: «Lat meg ganga og drepa Ismael Netanjason! og ingen skal få vita det. Kvi skal han slå deg i hel, og alt Juda spreidast, dei som hev samla seg til deg, og leivningen av Juda tyntast?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Men Gedalja Ahikamsson sagde med Johanan Kareahsson: «Gjer ikkje det! For det er lygn det du melder um Ismael.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'So hende det i den sjuande månaden, at Ismael, son åt Netanja Elisamason, av kongsætti, ein av kongens stormenner, og ti mann med honom, kom til Gedalja Ahikamsson i Mispa, og dei fekk seg mat saman der i Mispa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Då stod Ismael Netanjason upp, og dei ti mann som var med honom, og dei slo Gedalja, son åt Ahikam Safansson, i hel med sverd, og drap honom som Babel-kongen hadde sett yver landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Ismael slo og i hel alle dei jødarne som var med Gedalja i Mispa, og dei kaldæarane, stridsmennerne som var der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Men andre dagen etter han hadde drepe Gedalja, fyrr nokon visste det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'kom det menner frå Sikem, frå Silo og Samaria, åtteti i alt, med avraka skjegg og sundrivne klæde og med merke rispa i holdet, og dei hadde med seg grjonoffer og røykjelse til å bera fram i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Og Ismael Netanjason gjekk ut imot deim frå Mispa, gråtande alt med han gjekk. Og då han møtte deim, sagde han med deim: «Kom til Gedalja Ahikamsson!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Men då dei var komne midt inn i byen, tok Ismael Netanjason og dei mennerne som var med honom og drap deim og kasta deim i brunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Men millom deim var det ti menner som sagde med Ismael: «Drep oss ikkje! for me hev forråd gøymde ute på marki: kveite og bygg og olje og honning.» Då let han deim vera og drap deim ikkje med brørne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Og brunnen som Ismael kasta liki i av alle dei menner som han hadde drepe umfram Gedalja, var den som kong Asa hadde gjort til vern mot Baesa, Israels-kongen; den fyllte Ismael Netanjason med drepne menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Og Ismael førde burt all leivningen av folket i Mispa: Kongsdøtterne og alt folket som var att i Mispa, som Nebuzaradan, hovdingen for livvakti, hadde sett Gedalja Ahikamsson yver - deim førde Ismael Netanjason burt fangar og gjekk av stad og vilde fara yver til Ammons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Men då Johanan Kareahsson og alle herhovdingarne som var med honom, frette alle dei illverki som Ismael Netanjason hadde gjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'tok dei alle mennerne og gjekk av stad og vilde strida mot Ismael Netanjason. Og dei fann honom attmed det store vatnet som er i Gibeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Men då alt folket som var med Ismael, såg Johanan Kareahsson og alle herhovdingarne som var med honom, gleddest dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Dei snudde då, alt folket som Ismael hadde ført fangar frå Mispa, og gjekk tilbake til Johanan Kareahsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Men Ismael Netanjason slapp undan frå Johanan med åtte mann og for til Ammons-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Og Johanan Kareahsson og alle herhovdingarne som var med honom, tok med seg alle som var att av folket, deim or Mispa som han hadde vunne att frå Ismael Netanjason, etter han hadde drepe Gedalja Ahikamsson: stridsmenner og kvende og born og hirdmenner, som han hadde ført tilbake frå Gibeon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Dei for då av stad, men stana i Kimham-herbyrget, som er attmed Betlehem, og vilde halda fram med ferdi til Egyptarland');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, '- for kaldæarane skuld, for dei ottast deim av di Ismael Netanjason hadde drepe Gedalja Ahikamsson, som Babel-kongen hadde sett yver landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Då kom alle herhovdingarne fram, likeins Johanan Kareahsson og Jesanja Hosajason, og alt folket, både små og store,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'og sagde til profeten Jeremia: «Unn oss å leggja bøni vår fram for di åsyn, at du må beda for oss til Herren, din Gud, for all denne leivningen - for berre nokre få er me att av mange, so som du sjølv ser på oss -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'at Herren, din Gud, vil kunngjera for oss kva veg me skal ganga, og kva me skal gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Profeten Jeremia sagde til deim: «Godt og vel! Sjå, eg vil beda til Herren, dykkar Gud, so som de segjer, og alt det Herren svarar dykk, det skal eg segja dykk. Eg vil ikkje halda noko løynt for dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Då sagde dei med Jeremia: «Herren vere eit sant og trufast vitne mot oss, um me ikkje gjer etter kvart det ordet som Herren, din Gud, sender deg med til oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Anten det er godt eller vondt, so vil me lyda røysti åt Herren, vår Gud, som me sender deg til, so det må ganga oss vel når me lyder røysti åt Herren, vår Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'So hende det ti dagar etterpå, at Herrens ord kom til Jeremia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Og han kalla på Johanan Kareahsson og alle herhovdingarne som var med honom og alt folket, både små og store,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'og sagde med deim: So segjer Herren, Israels Gud, som de sende meg til, so eg skulde leggja bøni dykkar fram for hans åsyn:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Um de vert buande i dette landet, so vil eg byggja dykk upp og ikkje riva ned, og planta dykk og ikkje rykkja upp. For eg angrar det vonde som eg hev gjort dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ottast ikkje Babel-kongen, som de no ottast, ottast ikkje honom! segjer Herren; for eg er med dykk og til å frelsa dykk ut av hans hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Og eg vil lata dykk få miskunn, so han miskunnar dykk og snu heim att til landet dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Men um de segjer: «Me vil ikkje vera i dette landet,» lyder de ikkje røysti åt Herren, dykkar Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'men segjer: «Nei, men me vil fara til Egyptarlandet, der me slepp å sjå herstrid og høyra omen av stridslur og hungra etter brød, og der vil me bu» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'so høyr no difor Herrens ord, du Juda-leivning! So segjer Herren, allhers drott, Israels Gud: Um de til røyndar held stemneleidi til Egyptarland, og fer dit og vil bu der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'då skal sverdet som de ottast nå dykk der i Egyptarlandet, og svolten som de no ræddast, skal elta dykk til Egyptarland, og der skal de døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Og alle dei menner som held stemneleidi til Egyptarland og vil bu der, dei skal døy for sverd, av svolt og i sott, og ingen av deim skal sleppa frå eller komast undan den ulukka som eg let ganga yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'For so segjer Herren, allhers drott, Israels Gud: Likeins som min vreide og harm var utrend yver Jerusalems, so skal min harm og verta utrend yver dykk når de fer til Egyptarland, so de vert til ein eid og til ei skræma og til ei våbøn og til ei hæding, og de skal aldri meir sjå denne staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Herren hev tala til dykk, du Juda-leivning: Far ikkje til Egyptarland! Vita skal de at eg hev vara dykk i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'For de dårar dykk - og her stend det um livet - for de sende meg til Herren, dykkar Gud, og sagde: «Bed for oss til Herren, vår Gud, og kunngjer oss alt det som Herren, vår Gud, segjer oss, so vil me gjera det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Og eg hev kunngjort dykk det i dag, men de hev ikkje lydt på røysti åt Herren, dykkar Gud, i noko av det som han hev sendt meg med til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Og vita skal de no, at de lyt døy for sverd, av svolt og i sott på den staden som de stundar etter å koma til so de kunde bu der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Men då Jeremia hadde tala til folket alle Herrens, deira Guds, ord, som Herren, deira Gud, hadde sendt honom med til deim - alle desse ordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'då sagde Azarja Hosajason og Johanan Kareahsson og alle dei ovmodige mennerne - dei sagde med Jeremia: «Det er lygn det du segjer; Herren, vår Gud, hev ikkje sendt deg og sagt: «De skal ikkje fara til Egyptarland og bu der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Men Baruk Neriason eggjar deg upp imot oss, so me skal verta gjevne i henderne på kaldæarane, og dei skal drepa oss eller føra oss burt til Babel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Og Johanan Kareahsson og alle herhovdingarne og alt folket vilde ikkje høyra på Herrens røyst og vera i Judalandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Men Johanan Kareahsson og alle herhovdingarne tok alle som var leivde etter av Juda, som var komne tilbake frå alle folki som dei hadde vore burtdrivne til, og vilde bu i Judalandet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'mennerne og kvinnorne og småborni og kongsdøtterne og kvart eit liv som Nebuzaradan, hovdingen for livvakti, hadde late vera att hjå Gedalja, son åt Ahikam Safansson, so og profeten Jeremia og Baruk Neriason,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'og for til Egyptarland, for dei høyrde ikkje på Herrens røyst. Og dei for til Tahpanhes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Og Herrens ord kom til Jeremia i Tahpanhes; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Tak deg nokre store steinar i handi og gøym deim i leiret i tiglsteinsleggjingi som er i inngangen til Faraos hus i Tahpanhes, framfor augo på menner frå Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Og du skal segja med deim: So segjer Herren, allhers drott, Israels Gud: Sjå, eg sender og hentar tenaren min Nebukadressar, Babel-kongen, og set kongsstolen hans uppå desse steinarne som eg hev gøymt, og han skal breida sitt glimande tæpe utyver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Og han skal koma og slå Egyptarlandet; den som er etla åt dauden, lyt døy, den som er etla til fange, vert fange, og den som er etla åt sverdet, vert sverdslegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Og eg vil kveikja eld på gudehusi i Egyptarland, og han skal brenna deim upp og føra gudarne burt. Og han skal sveipa Egyptarlandet um seg, likeins som hyrdingen sveiper kappa si um seg. Og sidan skal han fara derifrå i fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Og han skal brjota sund sulorne i Bet-Semes, som er i Egyptarlandet, og gudehusi i Egyptarland skal han brenna upp med eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Det ordet som kom til Jeremia åt alle dei jødarne som budde i Egyptarlandet, dei som budde i Migdol og i Tahpanhes og i Nof og i Patroslandet; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'So segjer Herren, allhers drott, Israels Gud: De hev set all den ulukka som eg hev late koma yver Jerusalem og yver alle Juda-byarne - og sjå, no er dei øydestader, og ingen bur i deim -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'for vondskapen deira so dei for med til å harma meg med, med di dei gjekk og brende røykjelse og tente andre gudar som dei ikkje kjende, korkje dei eller de eller federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Og eg sende til dykk alle tenarane mine, profetarne, både jamt og samt, og sagde: Gjer då ikkje desse skræmelege ting som eg hatar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Men dei høyrde ikkje og lagde ikkje øyra til, so dei snudde frå sin vondskap og heldt upp med å brenna røykjelse åt andre gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Då vart min harm og min vreide utrend, og han brann i Juda-byarne og på Jerusalems-gatorne, so dei vart til ei audn, til ei øyda, so som dei er enn i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Og no, so segjer Herren, allhers drott, Israels Gud: Kvi gjer de so stort eit tjon på dykk sjølve, so mann og kvinna, barn og brjostbarn vert utrudde for dykk midt ut or Juda, so de ikkje vert att ein leivning av dykk -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'og harmar meg med dei verk dykkar hender gjer, med di de brenner røykjelse åt andre gudar i Egyptarlandet som de er komne til og vil bu i - so dei skal verta utrudde for dykk, og de verta til ei våbøn og ei hæding hjå alle folk på jordi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Hev de gløymt det vonde som federne dykkar gjorde, og det vonde Juda-kongarne gjorde, og det vonde kvendi deira gjorde, og det vonde de sjølve gjorde, og det vonde kvendi dykkar gjorde i Judalandet og på Jerusalems-gatorne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Endå hev dei ikkje audmykt seg, og ikkje hev dei ottast og ikkje hev dei ferdast etter mi lov og etter mine bodord, som eg lagde fram for dykk og for federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Difor, so segjer Herren, allhers drott, Israels Gud: Sjå, eg snur andlitet mitt mot dykk til ulukka og eg vil rydja ut alt Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Og eg vil taka deim som er leivde etter Juda, deim som heldt stemneleidi til Egyptarlandet og for dit og vilde bu der. Og dei skal alle setja til, i Egyptarlandet skal dei falla; for sverd, av svolt skal dei setja til, både små og store; for sverd og av svolt skal dei døy. Og dei skal verta til ein eid, til ei skræma og til ei våbøn og til ei hæding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Og eg vil heimsøkja deim som bur i Egyptarlandet, likeins som eg heimsøkte Jerusalem, med sverd, med svolt og med sott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Og av Juda-leivningen, av deim som er komne og vil bu der i Egyptarlandet, skal ingen sleppa undan og verta att so han kann snu heim att til Judalandet som dei stundar å koma attende til, so dei kann bu der. For ingen skal koma dit att so nær som nokre få undanslopne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Då svara dei Jeremia, alle dei menner som visste at konorne deira brende røykjelse åt andre gudar, og alle kvinnorne som stod der i ein stor hop, og alt folket som budde i Egyptarlandet, i Patros, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '«Me vil ikkje lyda på deg i det som du hev tala til oss i Herrens namn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'men me vil gjera etter alt det som me hev lova med vår munn; å brenna røykjelse åt himmeldronningi og renna ut drykkoffer åt henne, so som me fyrr hev gjort, me og federne våre og kongarne våre og hovdingarne våre, i Juda-byarne og på Jerusalems-gatorne. Då hadde me nøgdi av brød, og det gjekk oss vel, og me såg ingi ulukka kom yver oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Men sidan me heldt upp med å brenna røykjelse åt himmeldronningi og renna ut drykkoffer åt henne, hev me vanta alt, og av sverd og svolt er me tynte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Og når me brenner røykjelse åt himmeldronningi og renner ut drykkoffer åt henne, er det då mennerne våre uviljande at me hev laga henne kakor og dyrka henne og rent ut drykkoffer åt henne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Då sagde Jeremia med all lyden, med mennerne og med kvinnorne og med all lyden som svara honom, han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '«Den offer-røykjingi som de hev gjort i Juda-byarne og på Jerusalems-gatorne, de og federne dykkar og kongarne dykkar og hovdingarne dykkar og landslyden - skulde Herren ikkje minnast henne og koma henne i hug?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Og Herren kunde ikkje lenger tola det for den vonde åtferdi dykkar, for alle dei styggjorne som de hev gjort. Og soleis vart landet dykkar til ei audn og ei øyda og til ei våbøn, folketomt so som det er enn i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'For di de brende røykjelse og synda mot Herren og ikkje lydde på Herrens røyst og ikkje ferdast i hans lov, i hans bodord og vitnemål, difor kom denne ulukka yver dykk, so som det er enn i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Og Jeremia sagde til alt folket og til alle kvinnorne: «Høyr Herrens ord, alle de Juda-menner som er i Egyptarlandet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'So segjer Herren, allhers drott, Israels Gud: De og konorne dykkar tala det med munnen dykkar og fullførde det med henderne dykkar med di de sagde: «Me vil halda lovnaderne våre som me hev gjort: å brenna røykjelse åt himmeldronningi og renna ut drykkoffer åt henne.» So berre haldt lovnaderne dykkar, og fullfør lovnaderne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Difor, høyr Herrens ord, alle de Juda-menner som bur i Egyptarlandet: Sjå, eg hev svore ved mitt store namn, segjer Herren: Sanneleg, ikkje ein einaste Juda-mann skal taka namnet mitt på tunga si i alt Egyptarlandet so han segjer: «So sant som Herren, Herren liver!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Sjå, eg vil vaka yver deim til deira ulukka, og ikkje til deira lukka, og alle Juda-menner som er i Egyptarlandet, skal verta tynte av sverd og svolt til det er gjort ende på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Men dei som kjem seg undan sverdet, skal snu heim att frå Egyptarlandet og til Judalandet, berre ein liten flokk. Og all Juda-leivningen, dei som er komne til Egyptarlandet og vil bu der, skal få vita kva ord som stend ved lag, mitt eller deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Og dette skal vera teiknet for dykk, segjer Herren, at eg vil heimsøkja dykk på denne staden, so de skal få vita at mine ord til dykk um ulukka stend ved lag:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'So segjer Herren: Sjå, eg gjev Farao Hofra, egyptarkongen, i fiendehender og i henderne på deim som ligg honom etter livet, likeins som eg hev gjeve Sidkia, Juda-kongen, i henderne på Nebukadressar, Babel-kongen, som var fienden hans og låg honom etter livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Det ordet som profeten Jeremia tala til Baruk Neriason då han skreiv desse ordi i ei bok etter Jeremias munn i det fjorde styringsåret åt Juda-kongen Jojakim Josiason; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'So segjer Herren, Israels Gud, um deg, Baruk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Du sagde: «Eie meg! For Herren hev lagt sorg til min hugverk. Eg er trøytt av sukkarne mine og finn ingi kvild.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'So skal du segja med honom: So segjer Herren: Sjå, det eg hev bygt upp, det riv eg ned, og det eg hev planta, det rykkjer eg upp, og dette gjeld heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Og du, du trår etter store ting åt deg: ikkje trå etter deim! For sjå, eg let ulukka koma yver alt kjøt, segjer Herren. Men eg vil gjeva deg livet ditt til herfang på kvar den stad du ferdast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Herrens ord som kom til profeten Jeremia um heidningefolki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Um Egyptarland. Um heren til Farao Neko, Egyptarlands-kongen, som stod burtmed Fratelvi, attmed Karkemis, og som Nebukadressar, Babel-kongen, vann på i det fjorde styringsåret åt Jojakim Josiason, kongen i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Bu til skjoldarne, dei små og dei store, og far ut i striden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Beit hestarne fyre og set dykk upp, ridarar, og fylk dykk hjelmbune! Kvet spjoti blanke, tak brynja på!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Kvi ser eg slikt: hugbrotne hopar dei undan, kjemporne deira vert krasa, dei flyr og ser ikkje attende; rædsla rundt ikring, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Den lettføygde kann ikkje fly ifrå, og kjempa slepp ikkje undan. Der nord, attmed Fratelvi, snåvar dei og fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kven er det som stig upp likeins som Nilelvi med bårande vatn som i ei å?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egyptarland stig upp likeins som Nilelvi med bårande vatn som i ei å. Det segjer: «Eg vil stiga upp og breida meg utyver landi, i øyde vil eg leggja byar og dei som i deim bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Kom uppetter, de hestar, og far rasande fram, de vogner! Kjemporne skal leggja av stad: \'tiopar og putarar som ber skjoldar, og ludarar som hev bogar å spenna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'For dette er ein dag åt Herren, Herren, allhers drott, ein hemndag til å hemna seg på uvenerne sine. Då skal sverdet eta og verta mett og drikka seg drukke av blodet deira. For ei offerslagting held Herren, Herren, allhers drott, i Norderlandet attmed Fratelvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Far upp til Gilead og få deg balsam, du møy, Egyptarlands dotter! Til inkjes brukar du lækjeråder i mengd; det bid ikkje plåster for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Folkeslag frettar skammi di, og jordi er full av naudropi dine. For ei kjempa snåvar i ei onnor, dei fell båe saman.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Det ordet som Herren tala til profeten Jeremia um det, at Nebukadressar, Babel-kongen, skulde koma og slå Egyptarlandet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Kunngjer det i Egyptarland og lat det frettast i Migdol, og lat det frettast i Nof og Tahpanhes! Seg: «Gakk fram og bu deg til! For sverdet hev ete alt ikring deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Kvi er din sterke støypt ned? Han kunde ikkje standa seg, for Herren støytt burti honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Han fekk mange til å snåva, so den eine dett uppå den andre, og dei sagde: «Upp og lat oss snu attende til folket vårt, og til fødelandet vårt, undan det herjande sverdet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Då ropar dei: «Farao, Egyptarlands-kongen, er berre ståket; han let den høvelege tidi fara frå seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'So sant som eg liver, segjer kongen - Herren, allhers drott, er namnet hans -: Lik Tabor millom fjelli og lik Karmel burtmed havet skal han koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Få deg bunad til langferd, du busitjande Egyptarlands dotter! For Nof skal verta ei audn, so ingen kann bu der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Ei ovgild kviga er Egyptarland - ein klegg kjem nordanfrå, kjem gjer han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Leigde hermenner, som gjødkalvar hjå henne, dei og snur og flyr alle i hop, stanar ikkje; for ulukkedagen er komen yver deim, den tidi dei vert heimsøkte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Røysti hennar er liksom av skridande ormen. For med ein her skrid dei fram, og med øksar kjem dei mot henne likeins som vedhoggarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Dei høgg ned hennar skog, segjer Herren; for han er ikkje til å finna seg fram igjenom; for dei er fleire enn engsprettor, det er ikkje tal på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Egyptarlands dotter vert til skammar; ho vert gjevi i henderne på eit norderlendskt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Herren, allhers drott, Israels Gud, segjer: Sjå eg heimsøkjer Amon frå No og Farao og Egyptarland og gudarne og kongarne der, både Farao og dei som lit på honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Og eg gjev deim i henderne på deim som ligg deim etter livet, i henderne på Nebukadressar, Babel-kongen, og i henderne på tenarane hans. Men etter det skal landet vera byggt i fred liksom i gamle dagar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Men ottast ikkje, du min tenar Jakob, og ræddast ikkje, Israel! For sjå, eg frelser deg ut or burtlengste land, og avkjømet ut or utlægdi. Og Jakob skal koma tilbake og liva i ro og fred, og ingen skal skræma honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ottast ikkje, du min tenar Jakob, segjer Herren; for eg er med deg. For eg vil gjera ende på alle dei folki som eg hev drive deg til. Men deg vil eg ikkje gjera ende på, men aga deg med måte, men reint utan refsing kann eg ikkje lata deg vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Herrens ord som kom til profeten Jeremia um filistarane, fyrr Farao vann Gaza.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'So segjer Herren: Sjå, vatn kjem upp-strøymande nordantil og vert til ei elv som fløder yver. Og dei fløder yver land og det som i deim er, yver byar og deim som i deim bur, so folket ropar høgt, og alle som bur i landet barmar seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Når det dyn av hovslagi av hans sterke hestar, når hans vogner skaldrar, når hans hjul skjell, då ser ikkje federne seg um etter borni, so hugstolne er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Det veld den dagen som kjem og tyner alle filistarane og ryd ut for Tyrus og Sidon alle undankomne som kunde hjelpa. For Herren tyner filistarane, leivningen frå Kaftorøyi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Fleinskalla er Gaza vorte, i øyde lagt er Askalon, det som er att av dalen deira; - kor lenge vil du rispa deg i holdet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ai, ei, du Herrens sverd! Kor lenge skal du hava det so annvint? Drag deg atter inn i slira di, haldt deg i ro og ver still!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Kor kunde du få kvila deg, sidan Herren hev gjeve deg påbod? Til Askalon og til Havstrandi, dit hev han etla deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Um Moab. So segjer Herren, allhers drott, Israels Gud: Usæla yver Nebo, for det er øydt, Kirjatajim er vorti til skammar, er teke, borgi er vorti til skammar og er livskræmd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Med Moabs frægd er det ute. I Hesbon bryggjar dei på meinråder imot det: «Kom, lat oss rydja det ut, so det ikkje lenger er eit folk!» Du og, Madmen, skal tagna, sverdet elter deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Naudrop høyrest frå Horonajim, herjing og stort tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab er i øyde lagt; dei let naudropi høyrast alt til Soar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'For gråtande gjeng dei upp stigen til Luhit, på vegen ned til Horonajim høyrer dei naudropi yver tjonet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fly, berga livet dykkar, og vert som hjelpelause i øydemarki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'For av di du leit på dine verk og dine skattar, skal du og verta teken. Og Kamos lyt fara i utlægd, hans prestar og hans hovdingar i lag med kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Og ein tynar skal koma yver kvar ein by, og ingen skal sleppa undan. Dalen skal forgangast og slettlendet øydeleggjast, so som Herren hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Gjev Moab vengjer! for fljugande lyt han fara burt, og hans byar skal verta ei audn, so ingen bur i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Forbanna vere den som er seinfør til å gjera Herrens verk, og forbanna vere den som held sverdet sitt att ifrå blod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab hev livt i fred frå sin ungdom; han hev lege still på bermen sin og er ikkje tømd or eit kjer i anna, og aldri hev han fare i utlægd; difor sit dåmen hans i honom endå, og angen av honom hev ikkje brigdast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Difor, sjå, dei dagar skal koma, segjer Herren, då eg sender honom vintapparar, og dei skal halla på kjeri hans og tøma deim og krasa krukkorne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Då skal Moab skjemmast av Kamos, likeins som Israels hus skjemdest av Betel, som dei leit på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kor kann de segja: «Me er kjempor og velduge hermenner?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moab er øydelagd, og dei stig upp i byarne hans, og hans druste drengjer stig ned til å verta slagta, segjer kongen - Herren, allhers drott, er namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Tjonet på Moab er kome nær, og ulukka hans hev bråhast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Hav medynk med honom, alle de som bur kringum honom, og alle de som kjenner namnet hans! Seg: «Korleis brotna teinen den sterke, staven den prydelege?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Stig ned or ditt æresæte og set deg på turre jordi, du busitjande Dibons dotter! For Moabs tynar stig upp imot deg, han legg borgerne dine i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Gakk ut på vegen og skygn utyver, du som bur i Aroer! Spør honom som flyr, og henne som kjem seg undan, seg: «Kva er hendt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab var til skammar, for han er krasa; barma dykk og ropa! Kunngjer hjå Arnon at Moab er øydelagd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Ja, domen er komen yver slettelandet, yver Holon og yver Jahsa og yver Mofa’at');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'og yver Dibon og yver Nebo og yver Bet-Diblatajim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'og yver Kirjatajim og yver Bet-Gamul og yver Bet-Meon');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'og yver Kerijot og yver Bosra og yver alle byarne i Moablandet, fjerr og nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Avhogge er Moabs horn, og armen hans er broten, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Gjer honom drukken, for han hev ovmoda seg mot Herren. Ja, Moab skal baska seg i spya si og verta til åtløgje, han og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Eller hadde du ikkje Israel til åtløgje? Eller var han gripen millom tjuvar, sidan du rister på hovudet kvar gong du talar um honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Gakk burt ifrå byarne og set bu på bergknausar, de Moabs ibuarar, og ver like duva som lagar seg reir burtum gil- gapet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Me hev høyrt um Moabs ovmod - storleg ovmoda han seg - um hans storlæte og ovmod og byrgskap og hjartans ovlæte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Eg kjenner, segjer Herren, hans ageløysa, det fåfengelege kytet hans, fåfengd hev han fare med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Difor lyt eg barma meg yver Moab, yver heile Moab lyt eg ropa, yver mennerne i Kir-Heres lyt ein sukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Meir enn Jazer græt, lyt eg gråta yver deg, du vintre frå Sibma: kvisterne dine gjekk yver havet, dei nådde alt til Jazerhavet; midt i fruktonni di og vinonni di hev ein tynar søkt på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Gleda og fagnad er kvorve or aldehagen og or Moablandet, og vinen let eg trjota i vinpersorne. Dei trøder vinpersa med fagnadrop; fagnadropi som ikkje er slike fagnadrop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Frå det jamrande Hesbon alt til El’ale, alt til Jahas let dei røysti si ljoma, frå Soar til Horonajim, til Eglat-Selisa; for jamvel Nimrim-vatni vert til øydemarker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Og eg vil rydja ut or Moab, segjer Herren, kvar og ein som stig upp på ein haug og brenner røykjelse åt gudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Difor læt hjarta mitt som ei fløyta yver Moab, yver mennerne i Kir-Heres læt hjarta mitt som ei fløyta; difor misser dei det dei hev mugga i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'For kvart eit hovud er fleinskalla, og alt skjegg er avraka, på alle hender er det rispa i holdet, og um lenderne sekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Uppå alle taki i Moab og på torgi høyrest berre usælerop; for eg hev krasa Moab som eit kjerald ingen hev hugnad i, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Å, kor forfærd han er! kor dei eiar seg! Å, kor Moab snur ryggen til skjemsla! Ja, Moab skal verta til eit åtløgje og ei skræma for alle som bur der kringum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'For so segjer Herren: Sjå, det kjem ein fljugande som ein ørn og breider vengjerne sine ut yver Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Byarne vert tekne, borgerne vunne, og hjarta til kjemporne i Moab vert den dagen som hjarta til kvinna i barnsnaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Og Moab skal verta øydelagd so han ikkje lenger er eit folk, for mot Herren hev han ovmoda seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Gruv og grav og gildra åt deg som bur i Moab, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Den som flyr undan gruvi, fell i gravi, og den som kjem seg upp or gravi, vert fanga i gildra. For eg let koma yver honom, yver Moab, eit år med heimsøkjing yver deim, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'I Hesbons skugge stend magtstolne rømingar; for eld fer ut or Hesbon og ein loge midt ut or Sihon, og han øydde Moabs tunnvange og kruna til stridsgny-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Usæl du Moab! Det er ute med folket åt Kamos; for sønerne dine vert tekne til fangar og døtterne dine til herfang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Men eg gjera ende på Moabs utlægd når tider er lidne, segjer Herren. So langt domen yver Moab.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Um Ammons-sønerne. So segjer Herren: Eig Israel ingi søner, eller hev han ingen erving? Kvi hev Malkam ervt Gad og hans folk sett seg ned i byarne hans?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Difor, sjå, dei dagar skal koma, segjer Herren, då eg let herrop høyrast til Rabba hjå Ammons-sønerne, og det skal verta til aude steinrøysar, og døtterne skal verta brende upp med eld, og då skal Israel erva sine ervingar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Øya deg, Hesbon! For Aj er i øyde lagt; ropa, de Rabba-døtter! Sveip dykk i sekk, barma dykk, og renn att og fram millom kvierne! for Malkam lyt fara i utlægd, prestarne hans og hovdingarne i lag med kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Kvi gildar du deg av dalarne, av din grøderike dal, du fråfalne dotter, som lit på skattarne dine og segjer: «Kven kann nå meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Sjå, eg let fælske nå deg, segjer Herren, Herren, allhers drott, frå alle stader rundt ikring deg. Og de skal verta drivne burt, kvar til sin kant, og ingen skal samla i hop deim som flyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Men sidan vil eg gjera ende på utlægdi åt Ammons-sønerne, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Um Edom. So segjer Herren, allhers drott: Bid det ikkje visdom lenger i Teman? Tryt det på råder for dei vituge? Er visdomen deira spillt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fly, snu dykk, gøym dykk djupt nede, de som bur i Dedan! For Esaus ulukka let eg koma yver honom den tid eg heimsøkjer honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Um druvehentarar kjem yver deg, so leiver dei ikkje noko til attpåhenting. Um tjuvar kjem med natti, vil dei tyna til dei hev fengje sitt nøgje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'For eg vil sjølv draga hamen av Esau, eg legg gøymslorne hans i berrsyni, so han ikkje kann løyna seg. Avkjømet hans og brørne hans og grannarne hans vert tynte, og det er ute med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Bry deg ikkje um dine faderlause! eg vil halda liv i deim, og enkjorne dine kann lita på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'For so segjer Herren: Sjå, dei som med rette ikkje skulde ha drukke or staupet, dei lyt drikka, og so skulde du sleppa urefst! Du skal ikkje sleppa urefst, men drikka skal du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'For eg hev svore ved meg sjølv, segjer Herren, at Bosra skal verta til ei fælska, til ei hæding, til ei audn og til ei våbøn, og alle byarne som høyrer til, skal æveleg liggja i røysar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Ei tidend hev eg høyrt frå Herren, og ein bodberar er send millom folkeslagi: «Sanka dykk og far imot honom, bu dykk til bardage!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'For sjå, eg gjer deg liten millom folki, svivyrd millom menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Rædsla kome yver deg! Ditt hjartans ovmod hev dåra deg, du som bur i bergklypor, som klengjer deg fast til fjelltinden. Um du bygde reiret ditt so høgt som ørnen, so skulde eg støypa deg ned derifrå, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Og Edom skal verta til ei skræma; alle som fer der framum, skal ræddast og spotta yver alle plågorne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Liksom då Sodoma og Gomorra med grannebyar vart lagde i øyde, segjer Herren, so skal ingen mann bu der, og ikkje noko mannsbarn halda til der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Sjå, det kjem ein upp stigande, som løva ut or tjukkskogen attmed Jordan, og inn på den sigrøne eng; for i ein augneblink vil eg jaga det burt derifrå, og den som er utvald, vil eg setja yver det. For kven er min like, og kven vil stemna meg? Og kven er den hyrdingen som stend seg for meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Difor, høyr den rådgjerdi Herren hev teke um Edom, og dei tankarne han hev tenkt um Teman-buarne: Sanneleg, dei skal dragsa deim burt, dei små lambi, sanneleg, hagelendet deira skal taka fæla av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Av dynen av deira fall bivrar jordi, naudropet - omen av det høyrer ein radt til Raudehavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Sjå, ein lik ein ørn stig upp og flyg fram og breider ut vengjerne sine yver Bosra. Og hjarta til Edom-kjemporne vert den dagen som hjarta til kvinna i barnsnaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Um Damaskus. Hamat og Arpad er skjemde, for dei hev spurt ei låk tidend, dei er reint vitskræmde; i havet er uro, det kann ikkje vera stilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damaskus er hugfalle, det snur seg og flyr, otte hev gripe det; angest og rider hev gripe det liksom kvinna med fødeflagor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kvi fekk han ikkje vera, byen den namnfræge, fagnad-byen min?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Difor skal hans sveinar falla på gatorne hans og alle hermennerne verta tynte den dagen, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Og eg vil kveikja eld i Damaskus-murarne, og han skal øyda Benhadad-slotti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Um Kedar og Hasor-riki, som Nebukadressar, Babel-kongen, vann. So segjer Herren: Statt upp, far mot Kedar og tyn Austheims-sønerne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Tjeldi deira og sauerne deira skal dei taka, tjelddukarne deira og all bunaden deira og kamelarne deira skal dei føra burt med seg, og dei skal ropa til dei: «Rædsla rundt ikring!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, '«Fly, røm undan mest de vinn, gøym dykk djupt nede, de Hasor-buar, segjer Herren; for Nebukadressar, Babel-kongen, hev teke ei rådgjerd mot dykk og tenkt ut løynråd imot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Statt upp, far upp imot eit fredleg folk som bur trygt, segjer Herren; portar og bommar vantar dei, for seg sjølve bur dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Og kamelarne deira skal verta til ran, og dei store bølingarne deira til herfang; og eg vil spreida deim for alle vindar, mennerne med rundklypt hår; og frå alle leider let eg ulukka koma yver deim, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Og Hasor skal verta til sjakal-bøle, ei audn um alder og æva; ingen mann skal bu der, og inkje mannsbarn skal halda til der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Herrens ord som kom til profeten Jeremia um Elam i den fyrste tidi Sidkia, Juda-kongen, styrde; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'So segjer Herren, allhers drott: Sjå, eg bryt sund for Elam hans boge, den likaste magti deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Og eg sender mot Elam fire vindar frå dei fire himmelætterne og spreider deim for alle desse vindarne. Og det skal ikkje finnast det folket som ikkje burtdrivne frå Elam skal koma til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Og eg vil gjera Elam forfærd for uvenerne sine og for deim som ligg deim etter livet, og eg vil lata ulukka koma yver deim, min brennande harm, segjer Herren, og eg vil senda sverd etter deim, til eg fær gjort ende på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Og eg vil setja kongsstolen min i Elam, og eg vil tyna der både konge og hovdingar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Men når tider er lidne, vil eg gjera ende på Elams utlægd, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Det ordet som Herren tala um Babel, um Kaldæarlandet, ved profeten Jeremia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Kunngjer det millom folki, og lat det frettast og set upp hermerke! Lat det frettast, dyl det ikkje! Seg: Babel er teki, Bel hev vorte til skammar, Merodak er livskræmd, hennar gudebilæte er vortne til skammar, hennar ufysne avgudar er livskræmde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'For eit folk kjem imot det nordantil, det gjer hennar land til ei øydemark, so ingen bur i det: både folk og fe er flydde, er burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'I dei dagarne og i den tidi, segjer Herren, skal Israels-borni koma, dei og Juda-borni i lag med einannan; gråtande skal dei ganga og søkja Herren, sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Etter Sion skal dei spyrja, den vegen stemner dei: «Kom, lat oss halda oss til Herren med ei ævepakt som ikkje skal gløymast!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Burtkomne sauer var mitt folk. Hyrdingarne deira hadde ført deim på villstig, snutt deim upp i fjelli; frå hamar til haug gjekk dei, gløymde legebolet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Alle som fann deim, åt på deim, og uvenerne deira sagde: «Me fær ikkje skuld på oss for det,» - for di dei hadde synda mot Herren, bustaden åt rettferdi, og voni åt federne deira, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fly ut or Babel, far burt or Kaldæarlandet, og ver som bukkar framfyre hjordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'For sjå, eg vekkjer upp frå Norderlandet ein skare av store folk og let deim fara mot Babel, og dei skal fylkja seg imot henne; derifrå vert ho teki. Pilerne deira er som frå ei viss-høv kjempa, dei vender ikkje attende med ugjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Og Kaldæa skal verta til herfang; alle som ranar henne, skal få sitt nøgje, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Gled dykk berre, fagna dykk berre, de som ranar odelen min! Berre hoppa i veret som kviga når ho treskjer, og kneggja som velduge hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Mor dykkar vert ovleg til skammar, ho som fødde dykk, skal blygjast; sjå, den siste millom folki vert ho, ei øydemark, eit turt land og ei vill heid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Ubygd skal ho verta, ei audn all med seg, av di Herren er vreid; alle som fer framum Babel, skal ræddast og spotta yver alle hennar plågor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Fylk dykk mot Babel, rundt ikring, alle de bogeskyttarar! Skjot på henne, spar ikkje på pilerne! For mot Herren hev ho synda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Set i herrop mot henne, rundt ikring: «Ho laut gjeva seg; falne er hennar pilarar, nedrivne hennar murar.» For det er Herrens hemn. Hemn dykk på henne! Gjer med henne likeins som ho hev gjort!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Ryd ut or Babel både såmannen og den som brukar sigden i skurdonni! For det herjande sverdet skal kvar og ein snu attende til sitt folk, og kvar og ein fly til sitt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel er ein buvill sau; løva hev jaga honom av; Assur-kongen åt fyrst på honom, og no sist hev Nebukadnessar, Babel-kongen, togge hans bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Difor, so segjer Herren, allhers drott, Israels Gud: Sjå, eg heimsøkjer Babel-kongen og landet hans, likeins som eg heimsøkte Assur-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Og eg vil snu Israel attende til hans beitemark, og han skal ganga og beita på Karmel og i Basan; og på Efraimsfjelli og i Gilead skal han få eta sitt nøgje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'I dei dagarne og i den tidi, segjer Herren, vert det leita etter Israels misgjerning, men ho skal ikkje lenger vera til, og etter Judas synder, men dei skal ikkje finnast; for deim som eg let vera att, gjev eg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Mot Meratajim-landet - far upp mot det og mot deim som bur i Pekod! Øyd deim og bannstøyt deim, når du set etter deim, segjer Herren, og gjer i heilt upp som eg hev bode deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Det er stridsgny i landet og stort tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kor er hamaren som slo all jordi sundbroten og sundknasa! Kor er Babel vorti ei skræma millom folki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Eg sette snara for deg, og du gjekk deg fast, Babel, og visste ikkje av det. Du vart funni, og gripi med; for du hadde gjeve deg i strid med Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Herren hev late upp våpnhuset sitt og teke ut sine vreidevåpn; for Herren, Herren, allhers drott, hev eit arbeid å gjera i Kaldæarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Kom imot det frå alle leider! Lat upp forrådshusi, kasta det i ein dunge likeins som kornband, og bannstøyt det! Lat ikkje noko verta leivt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Tyn alle uksarne, før deim ned til slagting! Usæla yver deim! for dagen deira er komen, den tid dei skal verta heimsøkte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Høyr omen av deim som flyr og kjem seg undan frå Babellandet til å forkynna i Sion at Herren, vår Gud hemner, hemner for templet sitt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Bjod skyttarar ut mot Babel, alle deim som boge kann spenna! Slå læger rundt ikring henne, lat ingen koma seg undan! Lat henne få lika for sine gjerningar, gjer med henne heiltupp som ho sjølv hev gjort! For ho hev ovmoda seg mot Herren, mot Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Difor skal hennar drengjer falla på hennar gator og alle hennar hermenner verta tynte den dagen, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Sjå, eg kjem yver deg, Ovmod, segjer Herren, Herren, allhers drott; for dagen din er komen, tidi då eg vil heimsøkja deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Og Ovmodet skal snåva og falla, og ingen skal reisa det upp att. Og eg vil kveikja eld på byarne, og han skal øyda alt kringum det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'So segjer Herren, allhers drott: Trælka er Israels-sønerne og Juda-sønerne i lag med kvarandre; og alle som hertok deim, held deim faste, vil ikkje sleppa deim lause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Utløysaren deira er sterk, Herren, allhers drott, er namnet hans. Han skal føra saki deira med fynd so han roar jordi, men uroar Babel-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Sverd yver Kaldæa, segjer Herren, yver Babel-buarne og yver hennar hovdingar og vismenner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Sverd yver pjåtre-kallarne, so dei stend der som dårar! Sverd yver hennar kjempor, so dei vert hugbrotne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Sverd yver hennar hestar og vogner og yver alt blandingsfolket hjå henne, so dei vert kvende! Sverd yver hennar skattar so dei vert rana!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Turk yver hennar vatn so dei turkast upp! For det er eit land med avgudsbilæte, og dei ber seg som galne med dei skræmelege gudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Difor skal røysekatter med sjakaler halda til der, og strutsar skal hava sitt tilhelde der. Og der skal aldri meir verta bygt, men audt frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Likeins som då Gud lagde i øyde Sodoma og Gomorra med grannebyar, segjer Herren, so skal ingen mann bu der, og ikkje noko mannsbarn halda til der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Sjå, eit folk kjem nordanfrå, eit stort folk og velduge kongar ris upp frå utkantarne på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Boge og spjot ber dei, meinharde er dei og miskunnlause; dunen av deim er som havmarm, og på hestar rid dei, budde som ein mann til bardage mot deg, Babels dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Babel-kongen hev fenge fretnad av deim, og hans hender er magtstolne; angest hev gripe honom, rider liksom kvinna med fødeflagor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Sjå det kjem ein upp stigande, som løva ut or tjukkskogen attmed Jordan, og inn på den sigrøne eng; for i ein augneblink vil eg jaga deim burt derifrå, og den som er utvald, vil eg setja yver henne. For kven er min like, og kven vil stemna meg? Og kven er den hyrdingen som stend seg for meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Difor, høyr den rådgjerdi Herren hev teke um Babel, og dei tankarne han hev tenkt um Kaldæarlandet: Sanneleg, dei skal dragsa deim burt, dei små lambi, sanneleg, beitemarki deira skal taka fæla av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Av ropet: «Babel er teki!» bivrar jordi, og millom folki skrik dei ende yver seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'So segjer Herren: Sjå, eg vekkjer eit skadever imot Babel og imot ibuarane i Leb-Kamai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Og eg sender framande mot Babel, og dei skal dryfta henne og dei skal tøma landet hennar. For dei skal setja på henne frå alle leider på ulukkedagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Lat bogeskyttaren spenna boge mot den som boge spenner og mot den som briskar seg i brynja, og spar ikkje hennar drengjer, bannstøyt all hennar her!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Då skal daudslegne menner falla i Kaldæarlandet og stungne menner på gatorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'For Israel og Juda er ikkje enkjor, gløymde av sin Gud, av Herren, allhers drott, endå landet deira var fullt av skuld mot Israels Heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fly ut or Babel, og kvar og ein berge sitt liv so de ikkje tynest ved hennar misgjerning! For dette er ei hemne-tid for Herren; han vil gjeva henne lika for det ho hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Eit gullstaup i Herrens hand var Babel, som gjorde all jordi drukki; av vinen hennar drakk folki, difor vart folki reint rasande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Dåtteleg datt Babel og vart krasa. Barma dykk yver henne! Henta balsam for hennar plåga! Kann henda det kunde verta lækt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '«Me etla å lækja Babel, men ho var ulækjande. Lat oss skilja lag med henne, so me kann fara kvar til sitt land! For domen yver henne rekk upp til himmelen og når radt upp i skyerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Herren hev late vår rettvise sak koma upp i ljoset; kom, lat oss fortelja i Sion Herrens, vår Guds verk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Kvet pilerne blanke, grip skjoldarne! Herren hev vekt upp åndi til kongen i Media; for mot Babel hev han vendt sine tankar til å øydeleggja henne; for det er Herrens hemn, hemnen for templet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Reis hermerke mot Babel-murarne, haldt sterk vakt, set ut vaktmenner, skipa til umsåtmenner! For Herren hev både tenkt ut og sett i verk det han hev tala mot Babel-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Du som bur attmed mykje vatn, rik på skattar, komen er din ende, di låke vinning hev nått sitt mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Herren, allhers drott, hev svore ved seg sjølv: Endå eg hadde fyllt deg med menneskje som engsprettor i mengd, skal det like vel lyftast sigerrop yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Han hev gjort jordi med si kraft, skapt heimen med sin visdom, spana ut himlarne med sitt vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Når han let røysti si ljoma, svarar dyn av vatn i himmelen, og han let skodda stiga upp frå utkantarne på jordi, let eldingar laga regn og sender vind ut or gøymslorne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Kvar ein mann stend klumsa og hev ikkje vit på det, kvar ein gullsmed lyt skjemmast av bilæti sine; for dei støypte bilæti hans er berre lygn, og det er ingi ånd i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Dei er berre fåfengd, eit verk til å hæda; den tid dei vert heimsøkte, er det ute med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Jakobs arvlut er ikkje deim lik, for det er han som hev skapt alt og fenge seg si odelsrætt. Herren, allhers drott, er namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Du var hamaren min, stridsvåpnet, so eg med deg krasa folkeslag og med deg øyda kongerike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Og med deg krasa eg hest og ridar, og med deg krasa eg vogn og køyrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Og med deg krasa eg mann og kvinna, og med deg krasa eg gamall og ung, og med deg krasa eg svein og møy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Og med deg krasa eg hyrding og hjordi hans, og med deg krasa eg pløgjar og pløgje-uksarne hans, og med deg krasa eg jarlar og landshovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Men no gjev eg Babel og alle som bur i Kaldæa lika for alt vondt som dei hev gjort Sion, framfor augo dykkar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Sjå, eg kjem yver deg, du Tynefjell, segjer Herren, du som tyner all jordi; og eg vil retta ut handi ut imot deg og velta deg ned frå hamrarne og gjera deg til eit forbrent fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Av deg kann ein då korkje taka hyrnestein eller grunnstein, men til ævelege audner skal du verta, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Reis hermerke i landet, blås i lur millom folki, vig folkeslag til strid imot henne, kalla imot det kongeriki Ararat, Minni og Askenaz, set inn herhovdingar imot henne, før fram hestar som bustute engsprettor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Vig folkeslag til strid imot henne, kongarne or Media, jarlarne og landshovdingarne der, og alt det land dei råder yver!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Då dirrar jordi og bivrar, for no vert Herrens tankar mot Babel sette i verk: å gjera Babellandet til ei øydemark, so ingen bur der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Kjemporne i Babel hev halde upp med striden, dei sit i ro i borgerne. Deira kraft er kvorvi, kvende er dei vortne. Det er kveikt eld på hennar bustader, hennar bommar er brotne sunder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Lauparsvein løyp mot lauparsvein og sendebod mot sendebod, med bod til Babel-kongen at byen hans er teken frå ende til annan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'at vadi er hersette, vatsdemmorne turrbrende med eld og hermennerne forfærde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'For so segjer Herren, allhers drott, Israels Gud: Babels dotter likjest ein treskjevoll når han vert tiltrakka; endå ei liti rid, og skurdonni vil koma for henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, '«Nebukadressar, Babel-kongen, hev ete oss, hev øydt oss, hev sett oss burt som eit tomt kjerald, hev gløypt oss som ein hav-drake, hev fyllt buken sin med forkunnmaten min, burt hev han drive oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Valdsverki mot meg, ja, mot mitt kjøt, koma yver Babel!» segje Sion-buarne, «og mitt blod yver Kaldæa-folket! segje Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Difor, so segjer Herren: Sjå, eg fører saki og hemnar meg for deg, og eg let hennar hav turkast upp og hennar kjelda torna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Og Babel skal verta til steinrøysar, eit sjakal-bøle, ei skræma og ei hæding; ingen skal bu der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Alle burar dei som ungløvor, gnaldrar som løve-kvelpar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Når dei då er upp-øste, vil eg gjera eit drykkjelag åt deim og gjera deim drukne, so dei fagnar seg og sovnar i ein æveleg svevn og ikkje vaknar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Eg vil føra deim ned til slagting som lamb, som verar og bukkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kor er Sesak vorte teke, og «fagnaden for all jordi» herteken! Kor er Babel hev vorte til ei skræma millom folki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Havet gjekk yver Babel, ho vart løynt av dei marmande båror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Byarne hennar er vorte til ei audn, eit turt land og ei øydemark, eit land som ingen mann bur i, og som inkje mannsbarn fer framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Og eg heimsøkjer Bel i Babel, og tek det han hev gløypt i seg ut or munnen hans, og folkeslag skal ikkje lenger strøyma til honom. Babel-murarne skal rynja, dei og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Far ut derifrå, mitt folk, so dei kann berga kvar sitt liv for Herrens brennande vreide!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Og ver ikkje hugfalne og rædde for dei tiender som spørst i landet! For det vil koma ei tiend eitt året og ei onnor eit anna år, og urett vil råda på jordi, drott vil risa mot drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Difor, sjå, dei dagar skal koma då eg heimsøkjer gudebilæti hjå Babel, og alt landet hennar skal verta til skammar; og alle skal falla daudslegne hjå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Då skal himmel og jord fagna seg yver Babel, for nordanfrå skal tynaren koma yver henne, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Babel skal og falla, dei slegne menner av Israel, liksom det og for Babel hev falle slegne menner på heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'De som slapp undan frå sverdet, far av stad, stana ikkje! Minnest Herren frå burtlengste land, og kom Jerusalem i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Me vart til skammar, for me laut høyra på svivyrding; skammi breidde seg yver våre andlit, for framande hadde kome seg inn yver heilagdomarne i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Difor, sjå, dei dagar skal koma, segjer Herren, då eg vil heimsøkja gudebilæti hennar, og i alt hennar land skal slegne menner stynja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Um so Babel vil hevja seg til himmelen, og um ho gjer si høge festning u-klivande, so skal frå meg tynarar koma yver henne, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Naudrop er høyrande frå Babel og stort tjon frå Kaldæarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'For Herren tyner Babel og stoggar det store ståket hjå henne. Og bårorne deira skal dynja som store vatn, si dunande røyst skal dei lata ljoma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'For ein tynar kjem yver henne, yver Babel, og kjemporne hennar vert fanga, bogarne deira sundbrotne. For Herren er ein Gud som gjev attergjeld, han gjev full løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Og eg gjer deim drukne, hennar hovdingar og vismenner, hennar jarlar og landshovdingar og kjempor, og dei skal sovna av i ein æveleg svevn og ikkje vakna, segjer kongen - Herren, allhers drott, er namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'So segjer Herren, allhers drott: Babel-muren, den breide, skal verta nedriven til grunnen, og portarne, dei høge, brende med eld, so folk skal ha mødt seg for inkje og folkeslag for elden, og stræva seg trøytte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Den fyresegni som profeten Jeremia gav Seraja, son åt Neria Mahsejason, då han for til Babel med Sidkia, Juda-kongen, i det fjorde året han var konge. Men Seraja var kvartermeister.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Og Jeremia skreiv i ei bok, all den ulukka som skulde koma yver Babel - alle desse ordi som er skrivne um Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Og Jeremia sagde med Seraja: «Når du kjem til Babel, då sjå til at du les alle desse ordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Og du skal segja: «Herre, du hev sjølv tala um denne staden at du vil rydja honom ut, so ingen skal bu der meir, korkje folk eller fe, for til ævelege audner skal han verta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Og når du hev lese upp denne boki til endes, skal du binda ein stein til henne og kasta henne midt ut i Frat');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'og segja: «Soleis skal Babel søkka og ikkje koma upp att,» for den ulukka som eg let koma yver byen, og trøytte skal dei verta.» Hit når Jeremia-ordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Eitt og tjuge år gamall var Sidkia då vart konge, og elleve år rådde han i Jerusalem. Mor hans heitte Hamital Jeremiadotter, frå Libna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Han gjorde det som vondt var i Herrens augo, plent som Jojakim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Det var for Herrens harm skuld det gjekk so med Jerusalem og Juda, til dess han støytte deim burt frå si åsyn. Sidkia fall ifrå Babel-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'I det niande styringsåret hans, den tiande dagen i den tiande månaden, kom Nebukadressar, Babel-kongen, med heile heren sin til Jerusalem, lægra seg utanfor byen og bygde skansar rundt ikring honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Byen vart kringsett til kong Sidkias ellevte styringsår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'I den fjorde månaden, den niande dagen i månaden, røynde svolten hardt på i byen, og landsfolket hadde inkje mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Då vart bymuren gjenombroten, og alt stridsfolket rømde og for ut or byen um natti gjenom porten i dubbelmuren ved kongshagen, medan kaldæarane låg rundt ikring byen. Dei tok leidi til Moarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Men kaldæarheren sette etter kongen og nådde Sidkia att på Moarne ved Jeriko. Alt herfolket sprang frå honom og spreiddest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Dei fanga då kongen og førde honom upp til Babel-kongen, til Ribla i Hamatlandet, og han sagde upp domen yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Og Babel-kongen drap sønerne åt Sidkia medan han såg på det; sameleis drap han alle hovdingarne i Juda der i Ribla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'So stakk han ut augo på Sidkia, batt honom med tvo koparlekkjor og førde honom til Babel og sette honom i fangehus, der var han til sin døyande dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Og i den femte månaden, den tiande dagen i månaden, i det nittande styringsåret åt Babel-kongen Nebukadressar, kom livvakthovdingen Nebuzaradan, som stod for Babel-kongens åsyn, til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Han brende upp Herrens hus og kongsgarden, ja, alle husi i Jerusalem og alle storfolk-hus sette han eld på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Og heile kaldæarheren som var med livvakthovdingen, reiv ned alle murarne ikring Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Og sume av ålmugen og resten av folket som var att i byen, og rømingarne som hadde gjenge yver til Babel-kongen, og den flokken som var att dessforutan, førde livvakthovdingen Nebuzaradan burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Nokre av fatigfolket let livvakthovdingen Nebuzaradan vera att til å arbeida i vinhagarne og på åkrarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Koparsulorne som høyrde til Herrens hus, og fotstykki og koparhavet som var i Herrens hus, braut kaldæarane sund, og førde all koparen av deim til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Og dei tok oskefati og eldskuflerne og ljossakserne og blodbollarne og skålerne og alle kopargognere som dei hadde til gudstenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Og livvakthovdingen tok fati og glodpannorne og blodbollarne og oskefati og ljosestakarne og fati og bollarne, alt som var av gull og sylv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Tvo sulor og eit hav og dei tolv koparuksarne som var under fotstykki, som kong Salomo hadde laga åt Herrens hus - koparen i alle desse gognerne var ikkje vegande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Um sulorne er å segja: Den eine sula var attan alner høg, og ein tråd på tolv alner gjekk ikring henne, og ho var fire fingrar tjukk og innhol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Og det var eit sulehovud på henne av kopar, og det eine sulehovudet var fem alner høgt, og det var krot og granateple rundt ikring på sulehovudet, alt av kopar. Og likeins var det på den andre sula og granateple.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Og granatepli var seks og nitti utetter; alle granatepli på krotverket var eit hundrad rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Livvakthovdingen tok øvstepresten Seraja og den næst øvste presten Sefanja og dei tri dørstokkvaktarane,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'og frå byen tok han ein hirdmann som var uppsynsmann yver herfolket, og sju mann som han råka på i byen av næmaste lagsfolket hjå kongen, dessutan skrivaren til herhovdingen, han som skreiv ut landsfolket til hertenesta, og seksti mann av landsfolket som han råka på i byen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'deim tok livvakthovdingen Nebuzaradan og førde deim til Babel-kongen i Ribla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Og Babel-kongen slo deim i hel der i Ribla i Hamatlandet. Soleis vart Juda burtført frå landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Dette er det folket som Nebukadressar førde burt: I det sjuande året tri tusund og tri og tjuge jødar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'i Nebukadressars attande år åtte hundrad og tvo og tretti sjæler frå Jerusalem;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'i Nebukadressars tri og tjugande år førde Nebuzaradan, livvakthovdingen, burt av jødarne sju hundrad og fem og fyrti sjæler; fire tusund og seks hundrad sjæler i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'I det sju og trettiande året etter Juda-kongen Jojakin var burtførd, den fem og tjugande dagen i den tolvte månaden, gav Evil-Merodak, Babel-kongen - same året som han vart konge - Jojakin, Juda-kongen, uppreisnad og tok honom ut or fangehuset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Han helsa honom venleg og gav honom fremste sessen millom dei kongarne som var hjå honom i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Han fekk leggja av seg fangebunaden, og gjekk kvar dag til kongens bord, so lenge han livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Kost og tæring naut han dagvisst på kongens kostnad til kvar dag det han trong for dagen, alt til sin døyande dag, heile si livetid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kor sit ho då so einsleg, borgi den folkerike! Ho er vorti som ei enkja. Ho den velduge millom folki, fyrstinna millom byarne er trælkvinna vorti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Ho græt so sårt um natti, og hennar tåror trillar på kinn. Ho hev ingen trøystar millom alle sine elskarar. Alle hennar vener hev svike henne, dei er vortne hennar fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Land laut Juda fly, utor trengsla og stor træling. Ho bur millom folki, finn ingen kvildarstad. Alle hennar forfylgjarar nådde henne på trongstigarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Vegarne til Sion syrgjer av di ingen kjem til høgtiderne. Alle hennar portar er aude, hennar prestar sukkar. Hennar ungmøyar er sorgtyngde, og for henne sjølv er det beiskt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Hennar uvener er vortne dei fremste, hennar fiendar er velnøgde. For Herren hev lagt sorgi på henne for hennar mange misgjerningar skuld. Hennar småborn for fangar burt framfor fiendens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'So hev kvorve for Sions dotter all hennar pryda. Hennar hovdingar vart som hjortar som ikkje finn beite, og magtstolne gjekk dei der for forfylgjarens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Og i sin vesaldoms dagar, med ho flakkar ikring, kjem Jerusalem i hug sine hugnads-ting, som ho hadde i forne dagar. Då hennar folk fall i fiendehand, og ingen hjelpte henne, då såg fiendarne henne; dei log åt hennar tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Storleg hev Jerusalem synda, difor hev ho vorte eit styggje. Alle dei som æra henne, vanvyrder henne, for dei såg hennar skam. Ja, ho sjølv sukka og snudde seg ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Utsulka er hennar klæde av hennar ureinska; ho tenkte ikkje på endelykti. Hennar fall var reint som eit under; ingen trøysta henne. Sjå, Herre, min stakarsdom, for fienden gjer seg stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Si hand rette fienden ut etter alle hennar hugnads-ting; ja, ho såg heidningar koma inn i hennar heilagdom, dei som var forbodne å koma i di samling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Alt hennar folk sukkar med dei vil finna seg brød; dei gjev sine hugnads-ting for mat til å kveikja sjæli. Sjå, Herre, og skoda etter! for eg hev vorti svivyrd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Tek det dykk ikkje, alle de som fer vegen framum? Skoda etter og sjå, um ein lagnad var so tung som min - den sorgi Herren hev etla meg på sin brennande vreide-dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Frå høgdi sende han eld i mine bein og trakka deim sund. Han breidde ut eit garn for mine føter, han støytte meg undan, han gjorde meg aud, sjuk all dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Mitt synde-ok batt han saman med si hand; ihopknytt er det lagt på min hals - tok magti ifrå meg. Herren hev gjeve meg i henderne på deim eg ikkje kann standa meg for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Herren agta for inkje alle dei velduge hjå meg; han hev kalla i hop ei samling mot meg til å krasa mine gutar. Herren trødde vinpersa for møyi dotteri Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Yver dette græt eg; mitt auga, mitt auga let tårorne renna; langt burte frå meg er trøystaren som skulde kveikja mi sjæl. Mine born er tynte, for fienden vart den sterkaste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sion retter ut sine hender; ingen trøystar hev ho. Herren baud ut imot Jakob hans fiendar rundt ikring; Jerusalem byd deim imot som eitkvart ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Rettferdig er han, Herren; for eg gjorde meg hard mot hans munns ord. Høyr no, alle folk, og sjå min tunge lagnad; mine møyar og gutar for fangar burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Eg kalla på mine elskarar; dei sveik meg. Mine prestar og styresmenner let livet i byen, med dei leita etter mat til å metta seg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Sjå, Herre, eg er i trengsla! Det syd inni bringa og barm, hjarta snur seg i mitt brjost, for eg var so tråssug. Ute hev sverdet gjort meg barnlaus, inne er det som dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Dei høyrde kor eg sukka, eg; åt meg var der ingen trøystar. Alle mine fiendar høyrde um mi ulukka; dei gledde seg yver at du hadde gjort det. Men du let koma ein dag du hev forkynt; og då skal dei verta som eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Lat all deira vondskap koma for di åsyn, og gjer mot deim som du hev gjort mot meg for alle mine synder skuld. For mine sukkar er mange, og hjarta mitt er sjukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kor hev Herren i sin vreide sveipt Sions dotter i myrkeskodda! Han kasta frå himmelen ned til jordi Israels herlegdom, og han kom ikkje i hug sin fotskammel på sin vreide-dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Utan nåde lagde Herren i øyde alle Jakobs bustader. I sin vreide reiv han ned for dotteri Juda hennar sterke borger og kasta deim til jordi. Han vanhelga riket og hovdingarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'I sin brennande vreide hogg han av alle Israels horn; han drog si høgre hand attende, endå fienden var der. Han brende Jakob lik ein eldsloge som øyder rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Han spente sin boge som ein fiend’, med si høgre hand stod han fram som ein motstandar og drap alt våre augo hadde hugnad i. I tjeldet åt Sions dotter auste han ut sin vreide som ein eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Herren er vorten som ein fiend’, han hev lagt Israel i øyde, lagt alle hennar slott i øyde, gjort tjon på hennar borgar; so hev han dunga i hop på dotteri Juda sorg og sut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Og han hev brote ned som av ein hage sin gard, øydelagt sin samlingsstad. Herren hev late både høgtid og kviledag verta avgløymde i Sion, og støytt ifrå seg konge og prest i sin harmfulle vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Herren forsmådde sitt altar, stygdest ved sin heilagdom. Murarne kring hennar slott gav han i fiendevald. Dei let si røysti ljoma i Herrens hus som på ein høgtidsdag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Herren etla øydeleggja muren for Sions dotter. Han strekte ut si mælesnor og heldt ikkje handi si att frå herjing. Og han let voll og mur syrgja; ormegta ligg dei der i lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Dei er sokne i jord, hennar portar, han hev brote og krasa hennar stengslor; hennar kongar og hovdingar er hjå heidningfolki, det bid ikkje meir nokor lov. Hennar profetar hev ikkje heller fenge nokor syn frå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Dei sit på jordi tegjande, styresmennerne åt Sions dotter; dust hev dei drust uppi kruna, gyrdt seg med sekk. Dei luter mot jord sine hovud Jerusalems-møyarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Mine augo talmast av tåror, det syd inni bringa og barm, og livri hev runne til jordi - for tjonet på mitt folks dotter; for born, jamvel sogborn vanmegtast på gatorne i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Dei ropa til møderne sine: «Kvar er korn og vin?» vanmegtast som gjenomstungne på gatorne i byen då dei andast ved modersbarm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kva skal eg vitna for deg, kva skal eg likna deg attåt, du Jerusalems dotter? kva likning skal eg finna fram åt deg til å trøysta deg med, du møy, Sions dotter? For stor som eit hav er din skade, kven kann lækja deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Dine profetar såg deg syner med fåfengd og dårskap; dei hev ikkje synt deg di misgjerning, so dine fangar kunde koma attende, men dei såg deg syner, fulle med fåfengd og forføringar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Dei slær henderne i hop yver deg, alle som gjeng vegen framum. Dei blistrar og rister på hovudet yver Jerusalems dotter: «Er dette byen som dei kalla «den storfagre», «ei frygd for all jordi»?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Dei spilar upp i mot deg sitt gap alle dine fiendar, blistrar og bit i hop tenner; dei segjer: «Me hev gløypt henne. Ja, dette er den dagen me stunda på; me fekk då liva og sjå den dagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Herren hev gjort det han hadde tenkt, hev fullført sitt ord, den rådgjerdi han tok alt i forne dagar; han hev rive ned utan nåde, og han let fienden frygda seg yver deg, let dine uvener bera hornet høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Hjarto deira ropar til Herren. Du mur kring Sions dotter, du strigråte dag og natt! Unn deg ikkje kvild! Gjev ikkje din augnestein ro!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Statt upp, ropa høgt um natti, når nattevaktene tek til! Renn ut som vatn ditt hjarta framfor Herrens åsyn! Lyft upp til honom dine hender til livsens frelsa for dine born, som vanmegtast av svolt på kvart gatemot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Sjå, Herre, og skoda etter! Kven annan for du åt soleis? Skal kvende sitt avkjøme eta, småborn, som på armar dei ber? Skal ein slå i Herrens heilagdom prest og profet i hel?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'På jordi i gatorne ligg ung og gamall. Mine møyar og gutar er falne for sverd. Du slo i hel på din vreide-dag, du slagta utan nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Du kalla som på ein høgtidsdag rædslor mot meg alle stader ifrå; og på Herrens vreide-dag fanst det ingen som vart berga og slapp undan. Deim eg hev bore på armar og ale upp, hev min fiende tynt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Eg er mannen som naudi såg under hans vreide-ris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Meg hev han ført og late ferdast i myrker og ikkje i ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Berre mot meg vender han si hand upp att og upp att heile dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Han hev late meg eldast i hold og hud, han hev krasa mine bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Han bygde att for meg og ringa meg inn med beiska og møda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'I myrkret hev han set meg, lik deim som longe er daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Han mura att for meg, so eg kjem meg ikkje ut; tunge gjorde han mine lekkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Endå eg kallar og ropar, let han att for mi bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Han mura fyre mine vegar med tilhoggen stein, gjorde det uført på min stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ein lurande bjørn var han mot meg, ei løva i løyne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Til villstig gjorde han min veg; han reiv meg sund og lagde meg i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Han spente sin boge og sette meg til skotmål for si pil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Han let renna inni mine nyro pilehus-sønerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Eg vart til lått for alt mitt folk, deira nidvisa heile dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Han metta meg med beiske urter, han gav meg malurt å drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Han let meg knasa mine tenner på småstein, han grov meg ned i oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Og du støytte burt frå fred mi sjæl; eg gløymde kor det var å hava det godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Og eg sagde: «Det er ute med mi kraft og med mi von til Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Kom i hug mi naud og mi utlægd - malurt og beiska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Ho minnest det, sjæli mi, og er nedbøygd i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Dette vil eg leggja meg på hjarta, og difor vil eg vona:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Herrens nåde det er, at det ikkje er ute med oss, for hans miskunn er enn ikkje all.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Kvar morgon er ho ny, å, stor er din truskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Min lut er Herren, segjer mi sjæl; difor vonar vil eg vona på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Herren er god med deim som ventar på honom, med den sjæl som søkjer honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Det er godt å vera still for Herren og venta på hans frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Det er godt for mannen at han ber ok i sin ungdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'at han sit einsleg og tegjande, når han legg det på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'at han luter seg med munnen mot moldi - kann henda det enn er von -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'at han held fram si kinn til slag, let seg metta med svivyrda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'For Herren støyter ikkje æveleg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'For um han legg på sorg, so miskunnar han endå etter sin store nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'For det er ikkje av hjarta han legg møda og sorg på mannsborni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'At dei krasar under fot alle fangar i landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'at dei rengjer retten for mannen framfor åsyni til den Høgste,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'at ein gjer urett mot ein mann i hans sak - ser ikkje Herren slikt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kven tala, og det vart, um Herren ikkje baud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Kjem ikkje frå munnen til den Høgste både vondt og godt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Kvi skal eit livande menneskje klaga? Kvar syrgje yver si synd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Lat oss ransaka våre vegar og røyna deim og venda oss til Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Lat oss lyfta våre hjarto likeins som våre hender til Gud i himmelen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Me hev synda og vore ulyduge, du hev ikkje tilgjeve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Du sveipte deg i vreide og elte oss, du slo i hel utan nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'I skyer sveipte du deg, so ingi bøn rakk fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Til skarn og styggje hev du gjort oss midt imillom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Dei spila upp sitt gap imot oss, alle våre fiendar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Gruv og grav det vart vår lut, øyding og tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Tårebekkjer strøymer or mitt auga for tjonet på mitt folks dotter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mitt auga sirenn, roar seg ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'fyrr Herrens skodar etter og ser frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mitt auga gjer meg hjarte-ilt for kvar ei av døtterne i min by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Dei jaga og elte meg som ein fugl, dei som var mine fiendar utan orsak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Dei vilde taka livet av meg nede i brunnen, dei kasta stein på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Vatnet flødde yver mitt hovud, eg sagde: «Det er ute med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Eg påkalla ditt namn, Herre, utor den djupe hola.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Mi røyst høyrde du; haldt deg ikkje for øyro når eg ropar um lindring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Du var nær den dagen eg kalla på deg; du sagde: «Ikkje ottast!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Du, Herre, hev ført saki for mi sjæl, du hev løyst ut mitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Du, Herre, hev set kva urett eg leid; å, døm i mi sak!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Du hev set all deira hemnhug, alle deira løynderåder mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Du hev høyrt deira svivyrdingar, alle deira løynderåder mot meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'det mine motstandarar sagde og tenkte imot meg dagen lang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Ansa på deim, når dei sit og når dei stend! um meg gjer dei nidvisor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Du, Herre, vil gjeva deim av same slag som deira hender hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Du vil leggja eit sveip yver deira hjarta, du vil bannstøyta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Du vil elta deim i vreide, og tyna deim so dei ikkje bid meir under Herrens himmel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kor vert då gullet skjemt, det finaste gullet brigda, dei heilage steinarne strådde på kvart eit gatemot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Sions søner, dei dyrverdige, gjæve som skire gullet, kor er dei då haldne jamgode med leirkrukkor, med eit verk av krusmakar-hender!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Jamvel sjakalarne held fram juret, so ungarne fær suga - Sions dotter heldt seg hard; ho likjest på strussen i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Sogbarns-tunga kleimer seg til gomarne av torste; småborni bed um brød, men ingen etlar deim noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Dei som fyrr åt forkunnmat, ormegtast no på gatorne; dei som vart borne på skarlak, lyt no liggja i møk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Større vart soleis syndeskuldi til mitt folks dotter større enn syndi til Sodoma, som vart søkkt i jordi ein augneblink, utan at hender hjelpte til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Hovdingarne hennar var reinare enn snø, kvitare enn mjølk, raudare i holdet enn korallar; som safir såg dei ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Myrkare enn svart er dei vortne å sjå til, ein kann ikkje kjenna deim att på gata; dei er vortne berre skinn og bein, hudi deira skrukkast som næver på tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Det var betre for deim som fall for sverd, enn for deim som fall for svolten, deim som talmast av og var tynte av brødløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Hjartemilde kvende koka sjølve sine eigne born; dei hadde deim til mat, då mitt folks dotter vart tynt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Herren tømde ut sin harm, auste ut sin brennande vreide; i Sion kveikte han eld og snøydde til grunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Ingen konge på jord kunde tru, ingen i all verdi kunde tenkja at motstandar og fiend’ skulde koma inn i Jerusalems portar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Men det hende like vel, for hennar profetar hadde synda, hennar prestar var illgjerningsmenner, dei rende ut blod av rettferdige hjå henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Dei for og vildra i gatorne som blinde, sulka med blod, so ein ikkje kunde taka i klædi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '«Hav dykk undan! Urein!» ropa folket framfyre deim; «hav dykk undan, hav dykk undan! kom ikkje burti!» Når dei flydde og vadra ikring, vart det sagt millom folki: «Her fær dei ikkje vera lenger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Herrens åsyn hev spreidt deim ikring, han ser ikkje lenger til deim. Prestar vyrder dei ikkje, gamle miskunnar dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Endå stirer våre augo etter hjelp, men til fåfengs. Frå vårt vakttårn einstirde me etter eit folk som ikkje kann hjelpa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Dei lurer på våre stig, so me ikkje kann ganga på våre gator. Det er nær innpå enden med oss, våre dager er ute, ja, vår ende er komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Våre forfylgjarar var snarare enn himmelens ørnar; burtetter fjelli elte dei oss, i øydemarki lurde dei på oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Vår livsande, den Herren salva, vart fanga i deira løyngraver, han som me sagde dette um: «I hans livd skal me leva millom folki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Fagna og gled deg, du Edoms dotter, du som bur i Us-landet! Du og skal drikka same skåli, du skal verta drukki og nækja deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Di misgjerd er ende, Sions dotter. Han vil ikkje gjera deg utlæg att. Di misgjerd vil han heimsøkja, Edoms dotter, gjera synberre dine synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Kom i hug, Herre, kor det er med oss! Skoda etter og sjå, kor me er svivyrde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Vår arv er komen åt framande, våre hus åt utlendske menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Farlause er me vortne, hev ikkje far. Møderne våre er som enkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Me lyt kjøpa det vatnet me drikk, vår ved lyt me betala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Våre forfylgjarar hev me på halsen; me er trøytte, fær ikkje kvild.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Til Egyptarland rette me hand, til Assyria, vilde mettast med brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Våre feder synda, dei er burte, me lyt bera deira misgjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Trælar er våre herrar, og ingen riv oss ut or deira hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Me søkjer vårt brød med livsens fåre for sverdet i øydemark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Vår hud er glodheit som omnen, for svolten som gneg og brenn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Kvende hev i Sion dei skjemt, møyar i byarne i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Hovdingar hengde dei med si hand, gamle viste dei ikkje vyrdnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Ungmenne laut bera kverni, og gutar seig ned med vedbyrdi på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Dei gamle sit ikkje lenger i porten, dei unge ikkje meir med sitt strengespel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Det er slutt med vår hjartans gleda, vår dans er umsnudd til sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Kransen er fallen av vårt hovud; usæle me, at me hev synda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Difor er hjarta vårt sjukt, di so er augo våre dimme -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'for Sions fjell som ligg audt, der renner no revar ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Du, Herre, sit æveleg konge, frå ætt til ætt stend din kongsstol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Kvi vil du oss æveleg gløyma, ganga frå oss dagarne lange?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Vend oss, Herre, til deg, so kjem me; nya upp att våre dagar frå gamalt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'For du kann vel ikkje reint ha støytt oss burt, vera so ovleg harm på oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Det hende i det trettiande året, den femte dagen i den fjorde månaden, då eg var millom dei bortførde attmed Kebarelvi, at himmelen opna seg og eg såg syner frå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Den femte dagen i månaden - det var endå det femte året etter kong Jojakin vart burtførd -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'då kom Herrens ord til Ezekiel Buzison, presten, i Kaldæarlandet attmed Kebarelvi. Herrens hand kom der yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Og eg såg, og sjå, ei stormflaga kom nordanfrå, ei stor sky og eld som kvervla seg i hop, med eit skin rundt ikring, og ut or honom, midt utor elden, tedde det seg eitkvart nett som sylvblanda gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Og midt der-utor kom det noko som liktest på fire livende. Og soleis var dei på skap: Dei hadde manneskapnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Og fire andlit var det på kvart eitt av deim og fire vengjer på kvart eitt av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Og føterne deira, dei var beine, og fotbladi deira var som kalveklauver, og dei glima som skinande kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Og dei hadde mannehender under vengjerne på alle fire sidorne. Og med andliti deira og vengjerne deira var det soleis på alle fire:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Vengjerne deira nådde i hop, den eine med hin. Dei snudde seg ikkje når dei gjekk; kvart eitt gjekk beint fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Og deira andlit var som eit mannsandlit på skap, og alle fire hadde løve-andlit på høgresida, og alle fire hadde ukse-andlit på vinstresida, og alle fire hadde ørne-andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Det var no andliti deira. Og vengjerne deira breidde seg ut ovantil. Med tvo av vengjerne sine nådde eitt livende i hop med hitt, og med tvo løynde det likamen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Og kvart eitt av deim gjekk beint fram. Kvar åndi vilde ganga, dit gjekk dei; dei snudde seg ikkje når dei gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Og livendi såg ut som gløder i eld, brennende, som kyndlar å sjå til; elden for att og fram millom livendi, og det skein av honom, og ut or elden gjekk det ljon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Og livendi for att og fram, nett som eldingar å sjå til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Og eg såg livendi, og sjå, det var eit hjul på jordi innmed kvart eitt livende, og dei viste ut mot fire sidor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Og hjuli såg ut nett som dei skulde vera gjorde av eitkvart som liktest på krysolit, og alle fire var eins på skapnad, og det såg ut som dei var gjorde so at eitt hjul var inni hitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Til alle fire sidorne kunde dei ganga; dei snudde seg ikkje når dei gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Og hjulfalli var høge og skræmelege, og so var dei fullsette med augo rundt ikring på alle fire.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Og når livendi gjekk, so gjekk hjuli attmed deim, og når livendi lyfte seg frå jordi, so lyfte hjuli seg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kvar åndi vilde ganga, gjekk dei, nett dit som åndi vilde ganga. Og hjuli lyfte seg med deim, for åndi åt livendi var i hjuli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Når livendi gjekk, so gjekk dei, og når dei stod, so stod dei, og når dei lyfte seg frå jordi, so lyfte hjuli seg med, for åndi åt livendi var i hjuli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Og uppyver hovudi på livendi var det noko på skap som ein kvelv, som underfull krystall å sjå til, utspana uppyver hovudi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Og uppunder kvelven rette vengjerne deira seg beint ut, kvar mot annan. Kvart einskilt av deim hadde tvo vengjer som dei løynde likamen sin med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Og eg høyrde ljomen av vengjerne deira, som ljomen av store vatn, som røysti åt den Allmegtige, når dei gjekk, ein ljomande gny som gnyen frå eit herlæger. Når dei stod stilt, let dei vengjerne siga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Og det ljoma ei røyst uppyver kvelven som var yver hovudi deira. Når dei då stod stilt, let dei vengjerne siga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Og uppyver kvelven som var yver hovudi deira, var det noko som såg ut som safirstein, på skap som ein kongsstol. Og uppå kongsstol-skapnaden sat det ein som liktest på eit menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Og eg såg noko liksom sylvblanda gull, sjåande til liksom eld med ein ljosgard ikring, frå det som var sjåande til å vera lenderne hans og so uppetter. Og frå det som var sjåande til å vera lenderne hans og nedetter såg eg noko liksom eld å sjå til, med eit skin rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Liksom syni av bogen i skyi på ein regndag, soleis var syni av skinet rundt ikring. Soleis var openberringi av Herrens herlegdom å sjå til. Og då eg fekk sjå det, fall eg ned på mitt andlit, og eg høyrde røysti av ein som tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Og han sagde med meg: «Menneskjeson! Statt upp på føterne dine so eg kann få tala med deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Og det kom ånd i meg med det same han tala med meg, og reiste meg upp på mine føter, og eg lydde på honom som tala til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Og han sagde til meg: «Menneskjeson! Eg sender deg til Israels-borni, dei upprørske heidningar som hev gjort upprør imot meg. Dei sjølve og deira feder hev forbrote seg mot meg alt til den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Og til borni med dei harde andliti og stive hjarto - eg sender deg til deim. Og du skal segja med deim: «So segjer Herren, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Og dei, anten dei lyder på eller ikkje - for ei tråssug ætt er dei - so skal dei få vita at ein profet hev vore midt imillom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Og du, menneskjeson! Ikkje ottast deim! og ordi deira ottast du ikkje! For tistlar og klunger er hjå deg, og med skorpionar bur du. For ordi deira ottast du ikkje, og for deira åsyn vere du ikkje forfærd! For ei tråssug ætt er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Og du skal tala ordi mine til deim, anten dei lyder på eller ikkje, for tråssuge, det er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Men du, menneskjeson, lyd på det som eg vil tala til deg! Ver ikkje tråssug som den tråssuge ætti! Lat upp munnen din og et det som eg gjev deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Og som eg såg, og sjå, ei hand var rett ut til meg. Og sjå, i den var ein bokrull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Og han rulla honom upp framfor mi åsyn, og han var fullskriven inni og utanpå. Og skrive var det på honom syrgjesongar, sukkar og verop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Og han sagde med meg: «Menneskjeson! Et det du finn! Et denne bokrullen, og gakk, tala til Israels-lyden!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Og eg let upp min munn, og han gav meg denne bokrullen å eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Og han sagde med meg: «Menneskjeson! Din buk skal du metta, og dine innvolar skal du fylla med denne bokrullen som eg gjev deg.» Og eg åt, og han var i munnen min søt som honning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Og han sagde med meg: «Menneskjeson! Gakk av stad til Israels hus og tala til deim med mine ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'For du vert ikkje send til eit folk med ugreidt mål og tungmælt tunga, men til Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Ikkje til mange folkeslag med ugreidt mål og tungmælt tunga, so du ikkje skynar ordi deira, i sanning, um eg sende deg til deim, so skulde dei høyra på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Men Israels-lyden skal ikkje vilja lyda på deg, for dei vil ikkje lyda på meg. For all Israels-lyden - harde skallar og stinne hjarto hev dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Sjå, eg gjer di åsyn hard mot deira åsyn og di panna hard mot deira pannor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Som demant, hardare enn stein, gjer eg di panna. Du skal ikkje ottast deim og ikkje vera forfærd framfor deira åsyn, for ei tråssug ætt er dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Og han sagde med meg: «Menneskjeson! Alle mine ord som eg talar til deg, tak deim inn i ditt hjarta og høyr deim med dine øyro!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Og gakk av stad til dei burtførde, til ditt folks born, og tala til deim og seg med deim: So segjer Herren, Herren - anten dei vil lyda på eller ei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Då lyfte åndi meg upp, og eg høyrde attanfor meg ein dynjande sterk ljom: «Lova vere Herrens herlegdom frå den staden der han er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'likeins ljomen av dei fire livende, når vengjerne deira møttest, og ljomen av hjuli attmed deim, ein dynjande sterk ljom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Åndi lyfte meg då upp og tok meg med, og eg for av stad, hugsår og uppøst i mi ånd, og Herrens hand var sterk yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Og eg kom til dei burtførde i Tel-Abib som budde attmed Kebarelvi, til den staden der dei budde, og der sat eg hjå deim i tri dagar, hugstolen og reint ifrå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'So hende det etter sju dagar at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '«Menneskjeson! Til vaktar hev eg sett deg for Israels-lyden; når du då høyrer eit ord frå min munn, skal du vara deim åt frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Når eg segjer til den ugudlege: «Du skal døy,» og du ikkje varar honom åt, og ikkje talar og varar den ugudlege åt for hans ugudlege veg, til frelsa for hans liv, då skal han, den ugudlege, døy for si misgjerning, men hans blod vil eg krevja av di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Og når du varar den ugudlege, men han vender ikkje um frå si gudløysa og frå sin ugudlege veg, då skal han døy for si misgjerning, men du hev berga di sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Og når ein rettferdig vender seg frå si rettferd og gjer urett, so vil eg leggja støyt framfor hans åsyn; - han skal døy. Um du ikkje hev vara honom åt, skal han døy i si synd, og den rettferdi som han gjorde, skal ikkje verta ansa, men hans blod vil eg krevja av di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Men um du hev vara den rettferdige, at rettferdig mann skal ikkje synda, og han då ikkje syndar, då skal han liva, sidan han let seg vara, og du hev berga di sjæl.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Og Herrens hand kom der yver meg, og han sagde med meg: «Statt upp og gakk ut i dalen, der vil eg tala med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Og eg stod upp og gjekk ut i dalen. Og sjå, der stod Herrens herlegdom lik den herlegdomen eg såg attmed elvi Kebar. Og eg fall ned på mitt andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Men åndi kom i meg og reiste meg upp på føterne. Og han tala med meg og sagde til meg: «Gakk og steng deg inne i huset ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Og du, menneskjeson. Sjå, dei skal binda deg med tog og setja deg fast med deim, so du ikkje kjem deg ut til å vera i lag med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Og tunga di let eg hanga fast ved gomerne dine, so du vert mållaus og ikkje vert deim ein refsingsmann. For ei tråssug ætt er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Men når eg talar med deg, vil eg opna munnen din; då skal du segja til deim: So segjer Herren, Herren: Den som vil lyda på, han lyde, og den som ikkje vil gjeva gaum, han late vera! For ei tråssug ætt er dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Og du, menneskjeson! Tak deg ein tiglstein og rita av på honom ein by, Jerusalem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Og laga til umlægringsverk mot byen, og bygg åtaksmurar mot honom, og kasta upp ein voll mot honom, og slå læger mot honom, og set upp murstangarar mot honom rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Og du, tak deg so ei jarnpanna og set henne til ein jarnvegg millom deg og byen; snu deg med andlitet mot honom, so han vert kringsett, og du skal kringsetja honom: eit teikn er det åt Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Og du, legg deg på vinstre sida og legg på henne syndeskuldi åt Israels-lyden; like mange dagar som du ligg på henne, skal du bera deira syndeskuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Og eg let syndeskulds-åri deira vera som talet på dagarne for deg, tri hundrad og nitti dagar, so lenge skal du bera syndeskuldi åt Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Og når du hev gjort dette frå deg, skal du andre gongen leggja deg på høgre sida og bera syndeskuldi åt Juda-lyden; i fyrti dagar - ein dag for kvart år - let eg deg bera henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Og mot Jerusalem, til å kringsetja det, skal du snu deg med andlitet og med berr arm, og du skal spå imot det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Og sjå, eg bind deg med tog, so du ikkje skal snu deg frå den eine sida til hi fyrr du hev gjort frå deg kringsetjingsdagarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Og du, tak deg kveite og bygg og baunor og linsor og hirsa og spelt, og hav det i eit trog, og laga det til brød åt deg! I like mange dagar som du ligg på sida, i tri hundrad og nitti dagar, skal du eta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Og maten din skal eta etter vegt, tjuge lodd um dag. Frå tid til tid skal du eta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Og vatn skal du drikka etter mål, ein pott. Frå tid til tid skal du drikka det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Og som ei byggkake skal du eta det, og med mannsskarn til brennefang skal du steikja det for deira åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Og Herren sagde: «Soleis skal Israels-borni eta sitt brød ureint hjå dei folki som eg vil driva deim burt til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Og eg sagde: «Ai, ei! Herre, Herre! Sjå, aldri vart sjæli mi sulka, og noko sjølvdaudt og ihelrive hev eg aldri ete frå min ungdom alt til no, og det hev ikkje kome ureint kjøt i min munn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Og han sagde med meg: «Sjå, eg gjev deg kumøk i staden for mannsskarn, so du kann steikja brødet ditt yver den.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Og han sagde med meg: «Du menneskjeson! Sjå, eg bryt sund brødstaven for Jerusalem, og dei skal eta brød etter vegt og med otte og drikka vatn etter mål og med fælske,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'so dei skal vanta brød og vatn og verta forstøkte både ein og hin, og vanmegtast for si misgjerning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Og du, menneskjeson! Tak deg eit kvast sverd! Til rakekniv skal du bruka det, og du skal føra det yver ditt hovud og skjegg; tak deg so ei skålvegt og skift det du hev raka av!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Ein tridjepart skal du brenna upp i eld midt i byen når kringsetjingsdagarne er lidne, og ein tridjepart skal du taka og slå med sverdet vida ikring, og ein tridjepart skal du spreida ut i vinden, og sverd vil draga ut etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Men du skal taka undan nokre få av deim og binda deim i kjolesnipparne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Og av deim att skal du enn taka nokre og kasta deim midt inn i elden og brenna deim upp i eld. Derifrå skal koma eld yver all Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'So segjer Herren, Herren: Dette Jerusalem, midt imillom folki sette eg det, og land var det rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Men det hev sett seg upp mot mine lover, so det vart ugudlegare enn folki, og mot mine bodord, so dei vart verre enn landi rundt ikring; for mine lover vanvyrde dei, og i mine bodord ferdast dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Difor, so segjer Herren, Herren: Av di at de hev rasa verre enn heidningfolki rundt ikring dykk, ikkje ferdast i mine bodord og ikkje gjort etter mine lover, og jamvel ikkje gjort etter loverne åt heidningfolki som er rundt ikring dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'difor, so segjer Herren, Herren: Sjå, eg vil koma yver deg, eg og, og eg vil halda dom hjå deg midt framfor augo på heidningfolki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Og eg skal gjera med deg det som eg ikkje fyrr hev gjort og aldri meir vil gjera, for all styggedomen din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Difor skal foreldre eta borni sine hjå deg, og born eta foreldri sine. Og eg vil halda dom hjå deg, og strå alt som vert att av deg for alle vindar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Difor, so sant som eg liver, segjer Herren, Herren, sanneleg, etter di du hev sulka min heilagdom med all din styggjedom og alle dine styggjor, so vil eg og snu meg frå, og mitt auga skal ikkje ynkast, og ikkje eg heller vil spara deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Tridjeparten av deg skal døy av sott og verta tynt av svolt midt i deg, og tridjeparten skal falla for sverd rundt kringum deg, og tridjeparten vil eg spreida for alle vindar, og sverd vil eg draga ut etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Og all min vreide skal verta uthelt, og eg vil svala min harm på deim og hemna meg. Då skal dei sanna at eg, Herren, hev tala i min brennhug når eg heller ut all min harm på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Og eg vil gjera deg til audn og til spott millom folki som er rundt kringum deg, framfor augo på kvar ein som fer framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Du skal verta til spott og håd, ei åtvaring og ei skræma for folki som er rundt kringum deg, når eg held dom yver deg med vreide og med harm og med harmfulle refsingar - eg, Herren hev tala -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'når eg sender ibland deim dei vonde hunger-pilerne som er etla til tynarverk, deim eg sender til å tyna dykk med, når eg let svolten herja dykk og bryt sund brødstaven for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Eg vil senda yver dykk hunger og udyr, og dei skal gjera deg barnlaus, og sott og blod skal ganga yver deg, og sverd vil eg lata koma yver deg. Eg Herren, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Og Herrens ord kom til meg; han sagde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Menneskjeson! Vend di åsyn mot Israelsfjelli og spå mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Og du skal segja: De Israelsfjell, høyr ordi frå Herren, Herren! So segjer Herren, Herren til fjelli og til haugarne, til gili og til dalarne: Sjå, eg let sverd koma yver dykk og øyder dykkar offerhaugar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Og dykkar altar skal verta lagde i øyde og dykkar solstolpar sundkrasa, og eg vil lata dykkar gjennomstungne falla framfor augo på dykkar ufysne avgudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Og eg vil leggja liki av Israels-borni framfor augo på dykkar ufysne avgudar og strå beini dykkar rundt kringum dykkar altar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'På kvar einaste stad der de bur, skal byarne verta lagde i øyde og offerhaugarne verta aude, so altari dykkar kann verta øydelagde og aude og dykkar ufysne avgudar sundkrasa og upp i inkje og solstolparne dykkar nedhogne og dykkar verk utstrokne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'og gjennomstungne skal falla midt ibland dykk. Og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Men nokre vil eg leiva, med di sume av dykk slepp undan sverdet millom folkeslagi, når de vert spreidde kringum i landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Og dei av dykk som slepp undan, skal minnast meg millom folki som dei er burtførde til, når eg hev knasa deira utrue hjarta som veik ifrå meg, og deira augo som i utruskap søkte etter deira ufysne avgudar. Og dei skal styggjast ved seg sjølve for det vonde dei hev gjort, med alle sine styggjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Og dei skal sanna at eg er Herren. Ikkje fåfengt hev eg tala um å senda denne ulukka på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'So segjer Herren, Herren: Slå i hop handlovarne dine og trappa med foten og ropa: «Ai, ei!» yver alle dei vonde styggjorne i Israels-lyden; for dei skal falla for sverd, svolt og sott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Den som er langt burte, skal døy av sotti, og den som er nær, skal falla for sverdet, og den som er leivd og berga, skal døy av svolten, og eg vil tøma min harm yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Og de skal sanna et eg er Herren, når deira gjenomstungne ligg midt imillom deira ufysne avgudar, rundt kringum altari deira, på kvar ein høg haug, på alle fjelltoppar og under kvart eit grønt tre og under kvar ei lauvrik eik, på den staden der dei ofra godange åt dei ufysne avgudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Og eg vil retta ut handi mi mot deim og gjera landet til audn og øyda - verre enn Dibla-øydemarki - kvar dei so bur, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Og du, menneskjeson! So segjer Herren, Herren med Israels land: Ende! Komen er enden yver landsens fire hyrno.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'No er enden komen yver deg, og eg vil senda vreiden min mot deg og døma deg etter åtferdi di, og eg vil leggja på deg alle dine styggjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Og mitt auga skal ikkje spara deg, og miskunn gjer eg ikkje; men åtferdi di vil eg leggja på deg, og dine styggjor skal vera midt i deg, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'So segjer Herren, Herren: Ulukka, ei ulukka ein gong for alle, sjå, ho kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Ein ende kjem, ja, enden kjem, han vaknar imot deg, sjå, ho kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'No er det din tur, du som i landet bur. Tidi er komi, nær er dagen med ståkande rådløysa og ikkje med fagnadrop på fjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'No, um eit lite bil, vil eg renna ut min harm yver deg og tøma ut all min vreide på deg og døma deg etter åtferdi di, og eg vil leggja på deg alle dine styggjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Og mitt auga skal ikkje spara deg, og miskunn gjer eg ikkje; som di åtferd hev vore, let eg deg få det, og dine styggjor skal midt i deg vera. Og de skal sanna at eg, Herren, slær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Sjå, dagen! sjå, det kjem! Lagnadsstundi tek til; riset blømer, ovmodet grønkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Valdsgiren reiser seg til eit ris yver gudløysa. Ikkje noko av deim, inkje av deira ståkande hop, inkje av deira bråk, inkje av deira herlegdom vert att hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Tidi er komi, dagen er nær. Kjøparen fagne seg ikkje, og seljaren syrgje ikkje! For vreide logar mot heile deira hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'For seljaren skal ikkje få att det han selde, um han enn er i live, for syni mot heile hopen skal ikkje snu attende, og i si misgjerning skal ingen kunna verja sitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Dei blæs i stridslur og bur seg vel i alt, men ingen fer ut til striden; for min harm er imot heile deira hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Sverdet ute, sotti og svolten inne; den som er på marki, skal døy for sverd, og den som er i byen, honom skal svolt og sott tyna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Og slepp det undan einkvar utav deim, skal dei vera på fjelli som duvor i dalarne, alle med klagelæte, kvar og ein for si misgjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Alle hender skal siga, og alle kne skal verta veike som vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Og dei skal gyrda seg med sekk, og skjelving skal hylja deim, og kvart eit andlit skal blygjast av skam, og kvart hovud skal vera fleinskalla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Sylvet sitt skal dei kasta på gatorne, og gullet sitt skal dei vyrda som saur. Deira sylv og gull skal ikkje kunna berga deim på Herrens vreide-dag; dei skal ikkje kunna metta si sjæl eller fylla sin mage med det, for det hev vorte ein støytestein til misgjerning;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'og den glimande prydnadsting av det hev dei bruka til storlæte, og dei hev gjort sine styggjelege bilæte av det, sine ufyselege avgudar; difor gjer eg det til saur for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Og eg vil lata framande hender rana det og gudlause på jordi gjera det til herfang, og dei skal vanhelga det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Og eg vil snu mi åsyn frå deim. Og ransmenner skal vanhelga min skatt; dei skal brjota seg inn åt honom og vanhelga honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Gjer lekkja i stand! for landet er fullt av blod-domar, og byen er full av valdsverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Og eg vil lata dei verste av heidningarne koma, og dei skal eigna til seg husi deira. Og eg vil gjera ende på ovmodet hjå dei hardsette, og heilagdomarne deira skal verta vanhelga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Rædsla kjem, og dei skal søkja fred, men ingen finna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Ulukka på ulukka skal koma, fretnad på fretnad fær ein høyra; og dei skal søkja etter syn hjå profeten, lov skal kverva for presten, og råder for dei gamle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Kongen skal syrgja, og fyrsten skal klæda seg i fælske, og henderne på landslyden skal skjelva. Etter åtferdi deira vil eg gjera med deim, og med deira domar vil eg døma deim, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Og det hende i det sette året, den femte dagen i sette månaden, medan eg sat i huset mitt, og styresmennerne i Juda sat framfor mi åsyn, at Herrens, Herrens hand fall på meg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Og eg såg, og sjå, ein skapnad, sjåande til som eld; frå det som var sjåande av lenderne hans og nedetter som eld, og frå hans lender og uppetter var det som ei glima, som sylvblanda gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Og han rette ut eitkvart som liktest på ei hand, og tok meg i ein lokk av hovudhåret, og åndi lyfte meg upp millom jord og himmel og førde meg til Jerusalem i syner frå Gud, dit der ein gjeng inn til den indre fyregarden gjenom den porten som snur mot nord, der som harmings-bilætet stod, det som valda harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Og sjå, der var herlegdomen åt Israels Gud, liksom den syni eg hadde set i dalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Og han sagde med meg: «Menneskjeson! Lyft augo dine nordetter!» Og eg lyfte augo nordetter, og sjå, nordanfor altarporten var dette harmings-bilætet attmed inngangen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Og han sagde med meg: «Menneskjeson! Ser du kva dei gjer? Store styggjor er det som Israels-lyden gjer her, so eg lyt fara langt burt ifrå heilagdomen min. Men du skal få sjå store styggjor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Og han let meg koma til inngangen åt fyregarden. Og eg såg, å sjå, det var eit hol i veggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Og han sagde med meg: «Menneskjeson! Brjot igjenom veggen!» Og eg braut meg igjenom veggen, og sjå, der var ei dør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Og han sagde med meg: «Gakk inn og sjå dei vonde styggjor som dei gjer der!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Og eg gjekk inn og såg, og sjå, der var alle slag bilæte av krek og firføtingar, styggedom, og alle dei ufysne avgudarne åt Israels-lyden, innrita på veggjerne rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Og framfyre deim stod sytti mann, styresmennerne i Israels-lyden, og Ja’azanja Safansson stod midt imillom deim, og kvar og ein hadde eit røykjelseskjerald i handi, og det steig upp ange av røykjelseskyi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Og han sagde med meg: «Hev du set, menneskjeson, kva styresmennerne i Israels-lyden fer med i myrkret, kvar i sitt bilæt-rom? For dei segjer: «Herren ser oss ikkje; Herren hev vendt seg burt frå landet.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Og han sagde med meg: «Du skal enn få sjå store styggjor som dei fer med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Og han let meg koma åt inngangen til porten på Herrens hus, den som snur mot nord. Og sjå, der sat kvinnorne og gret for Tammus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Og han sagde med meg: «Hev du set, menneskjeson? Du skal enn få sjå styggjor, større enn desse.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Og han let meg koma i den indre fyregarden til Herrens hus. Og sjå, attmed inngangen til Herrens tempel, millom forhalli og altaret, var det ikring fem og tjuge menner; dei snudde ryggen til Herrens tempel og andliti i aust, og dei lutte seg austetter og bad til soli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Og han sagde med meg: «Hev du set det, menneskjeson? Kunde ikkje Juda-lyden nøgja seg med å gjera dei styggjor dei her hev gjort, men måtte fylla landet med vald og atter harma meg upp? Og sjå kor dei no held kvisten upp for nosi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'So vil då eg og fara fram i vreide; mitt auga skal ikkje spara, og miskunn gjer eg ikkje. Og um dei ropar for mine øyro med sterkt mål, so vil eg ikkje høyra deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Og han ropa med sterk røyst og sagde: «Kom hit med heimsøkjingar yver byen, kvar med si tynar-ambod i hand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Og sjå, seks menner på vegen gjenom Øvreporten, som snur mot nord, kvar med si krasar-ambod i handi, og ein av deim hadde ein linklædnad på og eit skrivestell ved lendi. Og dei kom inn og vart standande attmed koparaltaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Og herlegdomen åt Israels Gud lyfte seg upp frå keruben som han var yver, og flutte seg til dørstokken på huset. Og han ropa åt mannen i linklædnaden, som hadde skrivestellet ved lendi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Og Herren sagde med han: «Gakk midt igjenom byen, midt igjenom Jerusalem, og set eit merke i panna på dei menner som sukkar og styn yver alle dei styggjor som vert gjorde der inne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Og han sagde med hine, so eg høyrde på: «Gakk igjenom byen etter honom og slå ned! Lat ikkje dykkar augo spara, og gjer ikkje miskunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Gamle og sveinar og møyar og småborn og kvinnor skal de drepa og tyna; men rør ikkje nokon av deim som hev merke på, og frå min heilagdom skal de taka til.» Og dei tok til med dei gamle menner som var framfor huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Og han sagde med deim: «Gjer huset ureint og fyll fyregarden med drepne menner! Far ut!» Og dei for ut og slo ned i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Og då dei slo ned, og eg vart verande der, fall eg å gruve på mitt andlit og ropa og sagde: «Å, å! Herre, Herre! Vil du tyna alt som er leivt i Israel, når du renner ut din harm yver Jerusalem?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Då sagde han med meg: «Misgjerningi åt Israels-lyden og Juda er stor, ovstor, og landet er fullt av blod, og byen er full av rengjing av retten. For dei segjer: «Herren hev vendt seg ifrå landet, og Herren ser det ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'So vil då ikkje heller eg lata mitt auga spara, og miskunn gjer eg ikkje; deira åtferd vil eg leggja på deira hovud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Og sjå, mannen i linklædnaden som hadde skrivestellet ved lendi, kom tilbake med svar og sagde: «Eg hev gjort som du baud meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Og eg såg, og sjå, på den kvelven som var yver hovudi på kerubarne, var det som ein safirstein, sjåande til på skapnad som ein kongsstol. Ein kunde sjå honom yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Og han sagde med mannen i linklædnaden: «Gakk inn millom hjuli, inn under keruben, og tak nevarne dine fulle med gløder av deim som er millom kerubarne, og strå deim yver byen!» Og han gjekk medan eg såg på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Og kerubarne stod på høgre sida åt huset då mannen gjekk inn, og skyi fyllte den indre fyregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Og Herrens herlegdom lyfte seg frå keruben og burt til dørstokken i huset. Og skyi fyllte huset, og glansen av Herrens herlegdom fyllte fyregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Og ljomen av kerubvengjerne høyrdest alt til den ytre fyregarden, som røysti åt Gud den allmegtige, når han talar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Og det hende, då han baud mannen i linklædnaden og sagde: «Tak eld av den som er millom hjuli, millom kerubarne,» at han gjekk og stana attmed hjulet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Og keruben rette ut handi si, millom kerubarne, burtåt elden som var millom kerubarne, og tok og lagde i nevarne på honom i linklædnaden. Og han tok imot og gjekk ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Og under vengjerne på kerubarne kunde ein sjå eitkvart på skap som ei mannshand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Og eg såg, og sjå, det var fire hjul på kerubarne, eitt hjul hjå kvar kerub. Og hjuli var sjåande til som krysolit-stein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Alle fire såg likeins ut, og det var nett som eitt hjul skulde vera inni hitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Når dei gjekk, gjekk dei til alle fire sidorne; dei snudde seg ikkje når dei gjekk, for til den staden som hovudet snudde, dit gjekk dei; dei snudde seg ikkje når dei gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Og heile deira likam og deira rygg og deira hender og deira vengjer og hjuli var fullsette med augo rundt ikring - dei fire hadde kvar sitt hjul.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Hjuli, dei vart kalla «kvervel» so eg høyrde på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Og det var fire andlit på kvar; det fyrste hadde kerub-andlit, og det andre eit mannsandlit, og det tridje eit løve-andlit, og det fjorde eit ørne-andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Og kerubarne lyfte seg; det var dei livendi som eg hadde set attmed elvi Kebar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Og når kerubarne gjekk, so gjekk hjuli innmed deim, og når kerubarne lyfte vengjerne sine til å hevja seg upp frå jordi, skilde heller ikkje hjuli seg frå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Når livendi stod, so stod dei, og når dei lyfte seg, so lyfte dei seg med deim, for åndi åt livendi var i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Og Herrens herlegdom gjekk ut frå dørstokken på huset og stod yver kerubarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Og kerubarne lyfte vengjerne sine og steig upp frå jordi medan eg såg på, då dei gjekk ut, og hjuli innmed deim. Og dei stana attmed inngangen åt Øystreporten på Herrens hus. Og herlegdomen åt Israels Gud var uppe yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Det var dei same livendi som eg hadde set under Israels Gud burtmed elvi Kebar, og eg skyna at det var kerubar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Og det var fire andlit på kvart eitt av dei fire, og fire vengjer på kvart eit, og eitkvart på skap som mannehender under vengjerne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Og skapnaden på andliti deira det var dei andliti som eg hadde set attmed elvi Kebar; soleis såg dei ut, og dei var det. Og kvart eitt av deim gjekk beint fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Og åndi lyfte meg og flutte meg åt Øystreporten på Herrens hus, den som snur mot aust. Og sjå, frammed inngangen åt porten var det fem og tjuge mann. Og eg såg midt ibland deim Ja’azanja Azzursson og Pelatja Benajason, hovdingarne for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Og han sagde til meg: «Menneskjeson! Det er desse menner som tenkjer upp urett og legg meinråder i denne byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Det er dei som segjer: Det ber ikkje snart til med husbyggjing; dette er gryta, og me er kjøtet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Difor, spå imot deim! spå, du menneskjeson!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Og Herrens ande fall på meg, og han sagde med meg: «Seg: So segjer Herren: Soleis hev de sagt, Israels-menner, og kva som leikar dykk i hugen, veit eg vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Mykje folk hev de drepe i denne byen, og de hev fyllt gatorne med drepne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Difor, so segjer Herren, Herren: Dei de hev drepe og lagt ned der, dei er kjøtet, og byen er gryta, men dykk skal dei føra ut or honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Sverd ottast de, og sverd vil eg lata koma yver dykk, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Og eg vil føra dykk ut derifrå og gjeva dykk i henderne på framande, og eg vil halda dom yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'For sverd skal de falla; burtmed Israels landskil vil eg døma dykk. Og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Han skal ikkje vera gryta åt dykk, og de skal ikkje vera kjøtet i den; burtmed Israels landskil vil eg døma dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Og de skal sanna at eg er Herren, de som ikkje hev ferdast i mine bod og ikkje gjort etter mine lover; men etter loverne åt heidningfolki som bur rundt ikring dykk, hev de gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Og det hende medan eg heldt på å spå, at Pelatja Benajason døydde. Då fall eg å gruve på mitt andlit og ropa med sterk røyst: «Å, å! Herre, Herre! Vil du tyna alt som er leivt i Israel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Menneskjeson! Dine brør, dine brør, dine frendar og all Israels-lyden, alle saman, til deim er det Jerusalems-buarne segjer: «Haldt dykk langt burte frå Herren! Me hev fenge landet til eiga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Difor, seg: So segjer Herren, Herren: Då eg førde deim langt burt imillom heidningarne og spreidde deim i landi, då vart eg eit lite bil ein heilagdom åt deim i dei landi der dei kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Difor, seg: So segjer Herren, Herren: Eg vil samla dykk frå folki og henta dykk utor landi som de er kringspreidde i, og eg vil gjeva dykk Israels land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Ja, dit skal dei koma, og dei skal hava burt utor det all ufysna og all styggedomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Og eg vil gjeva deim eitt hjarta, og ei ny ånd vil eg gjeva inn i deim. Og eg vil taka burt steinhjarta or deira kjøt, og eg vil gjeva deim eit kjøthjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'so dei skal ferdast i mine bod og halda mine lover og gjera etter deim. So skal dei vera mitt folk, og eg skal vera deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Men dei som let hjarta sitt ferdast etter hjarta åt dei ufyselege og styggjelege avgudarne sine, deira åtferd vil eg leggja på deira hovud, segjer Herren, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Då lyfte kerubarne vengjerne sine, og hjuli fylgde med deim. Og herlegdomen åt Israels Gud var uppe yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Og Herrens herlegdom steig upp midt utor byen og stana yver fjellet som er austanfor byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Og åndi lyfte meg og førde meg til Kaldæa, til dei burtførde - i syni, ved Guds Ande, hende det. Og upp ifrå meg for syni som eg hadde set.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Og eg tala til dei burtførde alle dei Herrens ord som han hadde synt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Menneskjeson! Midt ibland den tråssuge ætti bur du, millom slike som hev augo å sjå med, men ikkje ser, og øyro å høyra med, men ikkje høyrer; for ei tråssug ætt er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Og du, menneskjeson! Bu deg til som du skal fara i utlægd, og far burt um dagen framfor augo på deim, og du skal fara frå der du bur til ein annan stad framfor augo på deim. Kann henda dei kunde koma til å sjå; for ei tråssug ætt er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Og du skal føra ut bunaden din som ferdabunad høgstedags framfor deira augo, og sjølv skal du fara ut um kvelden framfor deira augo, sameleis som når dei fer i utlægd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Brjot deg eit hol i veggen framfor deira augo, og før bunaden din ut gjenom det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Framfor augo på deim skal du lyfta honom upp på herdi; når det er stumende myrkt, skal du føra honom ut, og du skal sveipa inn andlitet ditt, so du ikkje ser landet. For eg hev gjort deg til eit teikn for Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Og eg gjorde so som han baud meg; eg budde meg som til å fara i utlægd ved høgste-dagsleite, og um kvelden braut eg meg ut gjenom veggen med handi. Og då det var stumende myrkt vorte, førde eg bunaden min ut; på herdi bar eg honom framfor deira augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Og Herrens ord kom til meg um morgonen; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Menneskjeson! Hev ikkje Israels-lyden, den tråssuge ætti, sagt med deg: «Kva gjer du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Seg med deim: So segjer Herren, Herren: Denne beringi gjeld fyrsten i Jerusalem og all Israels-lyden som derinne er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Seg: Eg er eit teikn åt dykk; likeins som eg hev gjort, so skal det gjerast med deim; dei skal verta fangar og fara i utlægd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Og fyrsten som er hjå deim skal taka si byrd på herdi og fara ut med det er stumende myrkt. Dei skal brjota hol i muren og føra ut gjenom det. Sitt andlit skal han sveipa inn, so han ikkje skal sjå landet med sine augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Og eg vil breida ut garnet mitt yver honom, og han skal verta fanga i mitt veide-net. So vil eg føra honom til Babel, til Kaldæarlandet - men det skal han ikkje sjå - og der skal han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Og alt som ikring honom er til hjelp og alle hans herflokkar vil eg spreida for alle vindar. Og sverd vil eg draga ut etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Og dei skal sanna at eg er Herren, når eg spreider deim millom folki og strår deim ut i landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Men nokre få av deim vil eg leiva etter sverd og svolt og sott, so dei kann fortelja um alle sine styggjor millom folki som dei kjem til, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Menneskjeson! Et brødet ditt bivrande, og drikk vatnet ditt skjelvande og med hugsott!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Og du skal segja til landslyden: So segjer Herren, Herren um deim som bur i Jerusalem, um Israels land: Brødet sitt skal dei eta med hugsott, og vatnet sitt skal dei drikka med fælske, for di deira land skal verta audt og snaudt, av di alle ibuarane for med valdsverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Og folkerike byar skal verta lagde i øyde, og landet skal verta ei øydemark, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Menneskjeson! Kva er det for eit ordtøke de hev i Israels land, at de segjer: «Dagarne gjeng, og kvar ei syn vert upp i inkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Seg difor med deim: So segjer Herren, Herren: Eg vil få burt dette ordtøket, og dei skal aldri meir taka det på si tunga i Israel, men seg med deim: Nær er dagarne komne og sannsegni i kvar ei syn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'For no heretter skal det ikkje finnast fåfengd syn og falsk spådom hjå Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'For eg, Herren, talar det ord eg talar, og det skal setjast i verk, det skal ikkje drygjast lenger ut. For i dykkar dagar, du tråssuge ætt, talar eg eit ord og set det i verk, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Menneskjeson! Sjå, Israels-lyden segjer: «Syni han ser, gjeld dagar langt undan, og um ukomne tider spår han.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Seg difor med deim: So segjer Herren, Herren: No heretter skal ikkje noko av mine ord drygjast ut lenger, det ord som eg talar, skal setjast i verk, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Menneskjeson! Spå mot profetarne i Israel, som spår, og seg med deim som spår utav eige hjarta: Høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'So segjer Herren, Herren: Usæla yver profetarne, dei dårar, som gjeng etter si eiga ånd og etter det dei ikkje hev set!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Som revar i røysar er dine profetar, Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'De er ikkje stigne upp i murrivorne og hev ikkje mura upp verjemur kring Israels-lyden, so han kunde standa seg i striden på Herrens dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Deira syner var fåfengd og deira spådomar lygn, dei som segjer: So segjer Herren, endå Herren ikkje hev sendt deim. Like vel vonar dei å vera sannspådde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Er det ikkje fåfengd syn de hev set, og ljugar-spåing de hev fare med, når de segjer: «So segjer Herren,» enda eg ikkje hadde tala?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Difor, so segjer Herren, Herren: Med di at de talar fåfengd og ser lygn, difor, sjå, so vil eg finna dykk, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Og mi hand skal vera mot dei profetarne som ser fåfengd og fer med ljugar-spåing; i mitt folks råd skal dei ikkje vera, og i boki åt Israels-lyden skal dei ikkje verta skrivne, og til Israels land skal dei ikkje koma; og de skal sanna at eg er Herren, Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'for di, ja, for di de hev villa mitt folk og sagt: «Fred,» og der er ikkje fred - og når det byggjer ein murvegg, sjå, so stryk dei berre kalkrøra på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Seg til kalk-strjukarane, at han vil ramla ned, det kjem eit skvalande støyteregn, og de, haglsteinar, skal falla, og ei stormflaga skal koma kastande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Og sjå, når veggen er nedramla, vil det då ikkje verta sagt med dykk: «Kvar vart det av kalken som de strauk på?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Difor, so segjer Herren, Herren: I min harm let eg ei stormflaga koma kastande, og i min vreide let eg eit skvalande støytregn koma, og i min harm haglsteinar til å øydeleggja alt i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Og eg vil riva ned veggen som de strauk med kalk, og velta honom til jordi, og hans grunnvollar skal verta berrlagde. Når det då ramlar i røys, skal de verta tynte i fallet, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Og eg vil tøma ut all mi vreide yver veggen, og yver deim som strauk honom med kalk. Då vil eg segja med dykk: Burte er både veggen og dei som strauk på honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'profetarne i Israel som spådde um Jerusalem og såg fredssyner åt det, endå det ikkje var fred, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Og du, menneskjeson! Vend di åsyn mot ditt folks døtter, som spår ut av sitt eige hjarta, og spå imot deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Og du skal segja: So segjer Herren, Herren: Usæla yver dei kvende som saumar bindsl åt alle handleder og lagar hovudsveip åt alle, både store og små, so dei kann fanga sjæler! De fangar sjæler for folket mitt, og andre sjæler held de i live, dykk til vinning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Og de vanhelgar meg for mitt folk for nokre korn-nevar og brødmolar - til å drepa sjæler som ikkje skulde døy, og til å halda liv i sjæler som ikkje skulde liva, med di de lyg for lyden min som lyder på lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Difor, so segjer Herren, Herren: Sjå, eg vil få tak i bindsli dykkar, som de fangar sjælerne med likeins som fuglar, og vil riva deim av armarne dykkar. Og eg vil fria sjælerne som de hev fanga, sjæler likeins som fuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Og eg vil riva sund dykkar hovudsveip og berga mitt folk utor dykkar hender, so dei aldri meir skal vera veidefang i dykkar hender, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'For di de ved lygn fær rettferdig manns hjarta til å vanmodast, endå eg ikkje hev gjort honom vanmoda, og de hev gjort gudlaus manns hender sterke, for at han ikkje skulde venda um frå sin vonde veg so eg kunde få halda honom i live,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'difor skal de ikkje hava fåfengde syner, og rune-kunster fær det ikkje fara med lenger; og eg vil berga mitt folk ut or dykkar hender, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Og det kom til meg nokre av styresmennerne i Israel og sette seg for mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Og Herrens ord til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Menneskjeson! Desse mennerne hev teke dei ufysne avgudarne sine upp i sitt hjarta, og det som er støytestein og fører deim til misgjerning, hev dei sett framfor si åsyn: skulde eg lata deim spyrja meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Difor, tala til deim og seg med deim: So segjer Herren, Herren: Ein og kvar av Israels-lyden som tek dei ufysne avgudarne sine upp i sitt hjarta, og set framfor si åsyn det som er støytestein til misgjerning, og so kjem til profeten, honom vil eg, Herren, gjeva svar som høver honom med dei mange ufysne avgudarne hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'so eg kann gripa Israels-lyden i deira hjarta, for di dei alle saman hev vendt seg frå meg med dei ufysne avgudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Difor, seg med Israels-lyden: So segjer Herren, Herren: Vend um og vend dykk burt frå dei ufysne avgudarne dykkar, og vend dykkar åsyn burt frå alle styggjorne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'For kvar og ein av Israels-lyden - eller av framande som bur i Israel - som skil seg frå meg og tek dei ufysne avgudarne sine upp i sitt hjarta, og set framfor si åsyn det som er støytestein til misgjerning, og so kjem til profeten og ved honom vil spyrja meg, honom vil eg, Herren, sjølv svara;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'og eg vil setja mi åsyn mot den mannen og tyna honom og gjera honom til eit teikn og eit ordtøke og rydja honom ut or mitt folk. Og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Og når profeten let seg lokka og talar eit ord, so hev eg, Herren, lokka den profeten, og eg vil retta ut handi mi mot honom og øyda honom ut or mitt folk Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Og dei skal bera si misgjerning; likeins som med misgjerningi åt spyrjaren skal det vera med misgjerningi åt profeten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'so Israels-lyden ikkje meir skal villast burt frå meg og ikkje meir sulka seg med alle sine misgjerningar. Men dei skal vera mitt folk, og eg skal vera deira Gud, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Menneskjeson! Når eit land syndar mot meg og fer med svik, og eg retter ut mi hand imot det og bryt sund brødstaven for det og sender svolt i det og ryd ut or det folk og fe,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'og desse tri menner vøre der: Noah og Daniel og Job, då skulde dei med si rettferd berre berga si eigi sjæl, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Og um eg let udyr fara gjenom landet og gjera det folketomt, so det vart likt ei øydemark, at ingen kunde ferdast der berre for udyri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'då skulde, so sant som eg liver, segjer Herren, Herren, desse tri mennerne, um dei vøre der, korkje berga søner eller døtter; dei åleine skulde verta berga, men landet verta ei øydemark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Eller um eg let sverd koma yver det landet og sagde: «Sverd skal fara gjenom landet,» og eg rudde ut or det folk og fe,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'og desse tri mennerne vøre der - so sant som eg liver, segjer Herren, Herren - dei skulde ikkje berga søner og døtter, berre dei åleine skulde verta berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Eller um eg sende sott i det landet og rende ut harmen min yver det med blod til å rydja ut or det folk og fe,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'og Noah og Daniel og Job vøre der - so sant som eg liver, segjer Herren, Herren - dei skulde ikkje berga son eller dotter; dei skulde, ved si rettferd, berga berre si eigi sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'For so segjer Herren, Herren: Enn når eg då sender dei fire øgjelege straffedomarne mine: sverd og svolt og udyr og sott yver Jerusalem til å rydja ut or det både folk og fe!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Men sjå, det vert leivt nokre undankomne, som vert burtførde, søner og døtter - sjå, dei skal fara til dykk, og de skal sjå deira åtferd og gjerningar; då skal de trøysta dykk etter ulukka som eg førde yver Jerusalem, alt som eg let koma yver det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Og dei skal trøysta dykk, når de ser deira åtferd og gjerningar. Då skal de skyna at eg ikkje utan grunn hev gjort alt det eg hev gjort imot det, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Menneskjeson! Kva fyremun hev vintreet framfor alle andre tre, den vintre-renningen som er millom trei i skogen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Brukar ein det til noko slag gagnved? eller lagar ein av det ein nabb til å hengja noko slag bunad på?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Sjå, ein nører elden med det, og elden brenner båe endarne, og midluten vert sviden. Kann det då duga til noko yrke?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Sjå, medan det var heilt, var det ikkje brukande til noko yrke: kor mykje minder når elden hev brent på det, og det er svide! Skulde det då vera brukande til yrke?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Difor, so segjer Herren, Herren: Likeins som med veden av vintreet millom trei i skogen, som eg nører elden med, soleis gjer eg og med Jerusalems-buarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Og eg vil setja mi åsyn mot deim; utor elden gjekk dei, men elden skal endå øyda deim ut. Og de skal sanna at eg er Herren, når eg set mi åsyn mot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Og eg vil gjera landet til ei øydemark, for di dei hev svike meg, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Menneskjeson! Lat Jerusalem få vita um sin styggedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Og du skal segja: So segjer Herren, Herren til Jerusalem: Ditt upphav og di ætt er frå Kananitarlandet; far din var ein amorit og mor di ei hetitkvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Då du kom til, den dagen du vart fødd, skar dei ikkje navlestrengen din, og ikkje vart du reintvegi med vatn og ikkje gnidi inn med salt og ikkje reiva med reivar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Ikkje eit auga ynka deg, so dei gjorde noko av dette med deg av miskunn imot deg, men du vart kasta på berre marki, av di dei fekk stygg til deg den dagen du vart fødd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Då gjekk eg framum deg og såg deg, der du låg og sprala i ditt blod. Og eg sagde med deg: «Du som ligg der i blodet ditt, liv!» Ja, eg sagde med deg: «Du som ligg der i blodet ditt, liv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Til mange tusund, som blomar i eng, gjer eg deg. Og du voks og vart stor og nådde den høgste vænleik. Brjosti vart faste, og håret ditt voks. Men du var berr og naki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Då gjekk eg framum deg og såg deg, og sjå, di tid var komi, elskhugstidi. Og eg breidde eg kappa mi yver deg og løynde blygsli di. Og eg svor deg truskapseid og gjorde pakt med deg, segjer Herren, Herren, og du vart mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Og eg tvo deg i vatn og skylde blodet av deg, og salva deg med olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Og eg klædde deg i rosesauma ty og hadde på deg skor av markuskinn og batt på deg eit fint hovudlin og sveipte deg i silke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Og eg prydde deg med prydnadsting, og gav deg armband på henderne og kjeda um halsen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Og eg sette ein ring i nosi di og øyreringar i øyro dine og ei fager kruna på hovudet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Og du prydde deg med gull og sylv, og klædnaden din var fint linty og silke og rosesauma ty. Fint mjøl og honning og olje fekk du til mat. Du vart ovende fager, so du vart ei høveleg dronning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Og du vart namngjeti millom folki for din vænleik, for han var fullkomen ved mi pryda som eg hadde butt deg til med, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Men du leit på din vænleik og dreiv hor i kraft av di namnfrægd, og du auste ut din hordom yver kvar og ein som gjekk framum - han skal få det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Og av klædi dine tok du og gjorde deg spreklute offerhaugar og dreiv hor på deim - slikt må ikkje koma på, ikkje henda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Og du tok dine prydnadsting av gullet mitt og sylvet mitt som eg hadde gjeve deg, og gjorde deg mannsbilæte, og du dreiv hor med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Og du tok dine rosesauma klæde og hadde på deim, og min olje og min røykjelse sette du fram åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Og brødet mitt som eg gav deg, finmjølet og oljen og honningen som eg hadde gjeve deg til mat, det sette du fram åt deim til godange; soleis gjekk det, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Og du tok dine søner og døtter, som du hadde født åt meg, og ofra deim til mat åt deim. Var det då ikkje nok at du dreiv hor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'sidan du jamvel slagta borni mine og gav deim burt, med di du let deim ganga gjenom elden for deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Og i alle dine styggjor og din hordom kom du ikkje i hug dine ungdomsdagar, då du var berr og naki og låg og sprala i ditt blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'So hende etter all din vondskap - usæl, usæl vere du! segjer Herren, Herren -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'at du bygde deg ein kvelving og gjorde deg ein offerhaug på alle torg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Attmed kvart eit vegemot bygde du din haug og skjemde din vænleik og breidde føterne ut for kvar og ein som gjekk framum, ja, du dreiv mykjen hordom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Og du dreiv hor med Egyptarlands-sønerne, grannarne dine, som hev stort kjøt, og du dreiv mykjen hordom til å harma meg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Og sjå, eg rette ut mi hand og minka på det eg hadde etla åt deg, og eg let deim som hata deg fara åt med deg som dei vilde, filistardøtterne, som blygdest yver di skjemdaråtferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Og du dreiv hor med Assurs-sønerne, av di du ikkje hadde fenge ditt nøgje, og du dreiv hor med deim, men endå fekk du ikkje ditt nøgje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Og du for verre fram med din hordom, alt til kræmarlandet Kaldæa, men endå fekk du ikkje ditt nøgje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Å, kor hjarta ditt brann av gir! - segjer Herren, Herren - at du kunde gjera alt dette, og fara åt som den skamlausaste skjøkja');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'og byggja din kvelving attmed kvart eit vegemot og gjera dine haugar på kvart eit torg! Men du var ikkje som ei onnor skjøkja, med di du vanvyrde skjøkjeløn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Du horkona! I staden for med mannen din held du deg med framande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Alle skjøkjor gjev dei gåvor; men du gav alle dine elskarar gåvorne dine og kjøpte deim til å koma til deg frå alle leider og driva hor med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Og du vart reint umsnudd imot andre kvende, i din ukjurskap; etter deg laup ingen, men du gav horeløn, du fekk ikkje, so rangsnudd var du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Difor, du skjøkja, høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'So segjer Herren, Herren: For di du auste ut dine pengar og nækte di skam i din ulivnad med dine elskarar og med alle dine ufysne avgudar, og du spillte blod av dine born, som du gav deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'difor, sjå, so samlar eg alle dine elskarar, som du tektest, og alle som du elska med alle som du hata, og eg vil samla deim imot deg frå alle leider og nækja di skam framfyre deim, og dei skal få sjå all di skam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Og eg vil lata same domen ganga yver deg som yver horkonor og slike som spiller blod, og eg vil gjera deg til eit blodigt offer for brennande harm og åbry.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Og eg vil gjeva deg i deira hand, og dei skal riva ned din kvelving, og brjota ned dine haugar, og hava av deg klædi dine, og taka dine dyrverdige prydnadsting, og lata deg liggja der naki og berr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Og dei skal gjera manngard um deg og steina deg i hel og hogga deg sund med sverdi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Og dei skal brenna upp dine hus med eld og halda dom yver deg framfor augo på mange kvinnor. Og eg vil gjera ende på din hordom, og heller ikkje skjøkjeløn skal du heretter gjeva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Og eg vil svala min heite harm på deg, og mitt åbry mot deg skal kverva. So vil eg halda meg i ro og ikkje lenger vera vreid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Av di at du ikkje mintest ungdomsdagarne dine, men harma meg med alt dette, sjå, so vil eg og lata di åtferd koma på ditt hovud, segjer Herren, Herren; for hev du ikkje lagt skamløysa attåt alle styggjorne dine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Sjå, alle som brukar ordtøke, skal hava dette til ordtak um deg: «Som mori, so dotteri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Du er dotter åt mor di, som stygdest ved mannen sin og borni sine, og du er syster åt systerne dine, som stygdest ved mennerne og borni sine: ei hetitkvinna er mor dykkar og ein amorit far dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Og den store syster di er Samaria, og hennar døtter, som bur på vinstre handi åt deg, og den litle syster di, som bur på høgre handi, er Sodoma og hennar døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Fulla gjekk du ikkje på deira vegar og gjorde ikkje styggjor som dei; men berre eit lite bil - so for du verre åt enn dei på alle dine vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'So sant som eg liver, segjer Herren, Herren: Sodoma, syster di, ho og hennar døtter, hev ikkje gjort som du, og dine døtter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Sjå, dette er misgjerningi åt Sodoma, syster di: ovmod; nøgdi med brød og sutlaus ro hadde ho og døtterne hennar; men handi åt armingen og fatigmannen styrkte ho ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Og med storlæte for dei, og dei gjorde skjemdarverk framfor mi åsyn; då rudde eg deim burt, fyrst eg såg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Og Samaria hev ikkje synda halvt so mykje som du, og du hev gjort dine styggjor fleire enn deira, so du gjorde systerne dine rettferdige med alle styggjor som du for med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Ber då du og di skam, du som hev dømt dine syster orsakande; i dine synder hev du vore skamlausare enn dei, og soleis vart dei rettferdigare enn du. So skulde du blygjast, du og, og bera di skam, med di du gjer systerne dine rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Men eg vil enda deira utlægd, utlægdi for Sodoma og hennar døtter og utlægdi for Samaria og hennar døtter og utlægdi for dine eigne utlæge midt imillom deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'for at du skal bera di skam og skjemmast av alt det du hev gjort med di du trøystar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Og systerne dine, Sodoma og hennar døtter, skal atter verta det dei fordom var, og Samaria og hennar døtter skal atter verta det dei fordom var, og du og dine døtterne skal atter verta det dei fordom var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Var ikkje syster di, Sodoma, eit uord i munnen din i ovmods-dagarne dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'fyrr vondskapen din vart synberr - liksom i den tidi då dei hædde deg, Arams-døtterne og alle der kringum, og filistardøtterne som svivyrde deg rundt ikring?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Di skjemd og dine styggjor skal du bera, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'For so segjer Herren, Herren: Eg vil fara åt med deg etter di eigi åtferd, du som vanvyrde eiden med di du braut pakti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Men eg vil minnast mi pakt med deg i ungdomsdagarne dine, og eg vil gjera ei ævepakt med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Og du skal minnast dine vegar og blygjast, når du tek imot systerne dine, dei som er større enn du, og dei som er mindre enn du, og eg gjev deg deim til døtter, endå at dei ikkje var med i di pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Og eg vil gjera mi pakt med deg, og du skal sanna at eg er Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'for at du skal minnast og blygjast og ikkje lata upp munnen din berre for blygsl, når eg tilgjev deg alt det du hev gjort, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Menneskjeson! Legg upp ei gåta og set fram ein liknad åt Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Og du skal segja: So segjer Herren, Herren: Den store ørnen med dei store vengjerne, dei lange slagfjørerne, og fjørhamen fullsett med spriklute fjører, kom til Libanon og tok toppen av cedertreet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Øvste kvisten braut han av og førde honom til eit kræmarland og sette honom ned i ein kjøpmannsby.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Sidan tok han ein renning der i landet og sette honom i dyrka jord; han tok og sette honom som ein seljetein der det var nøgdi med vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Og han voks og vart til eit vintre, vidt og lågvakse, so hans rankar skulde venda seg til ørnen og røterne hans skulde vera under honom. Han vart soleis til eit vintre som fekk greiner og skaut renningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'So var det ein annan stor ørn med store vengjer og yven fjørham. Og sjå, dette vintreet krøkte røterne sine burtåt honom, og frå den sengi der det var planta, tøygde det rankorne sine mot honom for at han skulde vatna det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'endå at det var planta i god jord og attmed mykje vatn, so det kunde skjota greiner og bera frukt og verta eit gildt vintre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Seg: So segjer Herren, Herren: Skal det trivast? Vil ikkje hin ørnen slita upp røterne og riva frukti av det so det tornar? Kvart eit sprettande blad skal torna, so ein tarv ikkje stor magt og mykje folk til å riva det upp mot rotom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Sjå, det er planta; skal det trivast? Vil det ikkje torna, verta knas-turt, når austanvinden kjem burti det? I sengi der det veks, skal det torna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Seg til den tråssuge lyden: Skynar de ikkje kva dette er? Seg: Sjå, Babel-kongen kom til Jerusalem, og han tok kongen og hovdingarne og førde deim med seg til Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Og han tok ein utav kongsætti og gjorde pakt med honom og let honom gjera eiden, og dei megtige i landet tok han burt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'for at det skulde vera eit litevore kongerike og ikkje hevja seg upp, so det skulde halda pakti med honom og standa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Men han sette seg upp imot honom, med di han let sine sendemenner fara til Egyptarland, for at dei skulde gjeva honom hestar og mykje folk. Skal det ganga honom vel? Skal han sleppa undan, den som gjer slikt? Skal han få brjota pakt og sleppa frå det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'So sant som eg liver, segjer Herren, Herren, sanneleg, på den staden der han er, den kongen som gjorde honom til konge - eiden hans svivyrde han, og pakti med honom braut han - hjå honom, midt i Babel, skal han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Og Farao skal ikkje hjelpa honom i striden med stor her og mykje folk, når dei kastar upp ein voll og byggjer åtaksmurar til å tyna mange liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Han svivyrde eiden då han braut pakti, og sjå, han hadde gjeve handtak på det, og alt dette hev han gjort; sleppa undan skal han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Difor, so segjer Herren, Herren: So sant som eg liver, sanneleg, eiden min som han svivyrde, og pakti mi som han braut, vil eg leggja på hans hovud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Og eg vil breida ut garnet mitt yver honom, og han skal verta fanga i mitt net. Og eg vil føra honom til Babel og ganga til doms med honom der for sviket han sette upp imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Og alle som vil røma undan ut or alle hans fylkingar, for sverd skal dei falla, og dei som vert leivde, skal verta spreidde for alle vindar, og de skal sanna at eg, Herren, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'So segjer Herren, Herren: Då vil eg taka av toppen på det høge cedertreet og setja; av dei øvste kvisterne vil eg brjota ein grann teinung, og eg vil planta honom på eit høgt og rise fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'På Israels høge fjell vil eg planta honom, og han skal få greiner og bera frukt og verta eit gildt cedertre. Og alle fuglar, alt fljugande, skal bu under det, i skuggen av greinerne på det skal dei bu.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Og alle trei på marki skal skyna at eg, Herren, hev gjort eit høgt tre lågt og eit lågt tre høgt, hev late eit grønt tre torna og eit turt tre grønka. Eg, Herren, hev tala, og eg set det i verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Korleis kann de bruka dette ordtøket i Israels land og segja: «Federne åt sure druvor, og borni vart sårtennte.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'So sant som eg liver, segjer Herren, Herren, de skal ikkje få bruka dette ordtøket meir i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Sjå, alle sjælerne er mine, både sjæli åt faren og sjæli åt sonen; mine er dei; den sjæl som syndar, ho skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Og når ein mann er rettferdig og gjer rett og rettferd:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'ikkje et offermat på fjelli og ikkje kaster augo sine på dei ufysne avgudarne åt Israels-lyden og ikkje skjemmer kona åt grannen sin og ikkje kjem nær ei kvinna medan ho er urein,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'og ikkje er hard imot nokon, let skuldmannen få pantet sitt att, ikkje fer med ransverk, gjev den hungrige sitt brød og klæder den nakne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'ikkje låner ut for renta og ikkje tek yvermål, held si hand burte frå det som rangt er, dømer rett dom mann og mann imillom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'ferdast i mine bod og held mine lover, so han gjer det som rett er - han er rettferdig, liva skal han, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Men han fær kann henda ein son som tek til med valdsverk, renner ut blod eller gjer eitkvart sovore');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, '- endå han ikkje gjorde noko slikt - for han et ogso offermat på fjelli, skjemmer kona åt grannen sin,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'er hard imot armingen og fatigmannen, fer med ransverk, gjev ikkje pant tilbake, kaster augo sine på dei ufysne avgudar, fer med styggedom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'låner ut for rente og tek yvermål - og so skulde han liva! Han skal ikkje liva. Alle desse styggjor gjorde han; banen hans skal det verta, blodet hans skal koma yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Men sjå, so fær han ein son, og han ser alle synderne åt far sin som han gjorde, han ottast og gjer ikkje etter deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'han et ikkje offermat på fjelli og kastar ikkje augo sine dei ufysne avgudarne åt Israels-lyden, skjemmer ikkje kona åt grannen sin');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'og er ikkje hard mot nokon, tek ikkje pant og fer ikkje med ransverk, gjev den hungrige sitt brød og klæder den nakne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'held handi si tilbake frå armingen, tek ikkje renta og yvermål, gjer etter mine lover og ferdast i mine bod. Han skal ikkje døy for misgjerningi åt far sin, liva skal han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Far hans som for med valdsverk og rana frå bror og gjorde det som ikkje er godt midt i lyden sin, sjå han laut døy for si misgjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Men de segjer: «Kvi skal ikkje sonen bera syndeskuldi åt far sin?» Sonen hev då gjort rett og rettferd alle mine bod hev han halde og gjort etter deim; liva skal han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Den sjæli som syndar, ho skal døy. Son skal ikkje bera syndeskuldi åt far sin, og far skal ikkje bera syndeskuldi åt son sin. Yver den rettferdige skal hans rettferd vera, og yver den gudlause skal hans gudløysa vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Men når den ugudlege vender um frå alle sine synder som han hev gjort, og held alle mine bod og gjer rett og rettferd, då skal han liva og ikkje døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Alle hans misgjerningar som han hev gjort, skal vera gløymde; ved si rettferd som han gjorde, skal han liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Skulde eg hava hugnad i det, at den ugudlege døyr? segjer Herren, Herren. Måtte ikkje det fegna meg, at han vendar um frå sin veg og liver?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Men når ein rettferdig vender um frå si rettferd og gjer urett, alle slike styggjor som den ugudlege gjer, skulde han gjera det og liva? All hans rettferd som han gjorde, skal verta gløymd. For den truløysa han for med, for det skal han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Og de segjer: «Herrens åtferd er ikkje rett.» Høyr då, du Israels-lyd! Er ikkje mi åtferd rett? Er det ikkje dykkar åtferd som ikkje er rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Når ein rettferdig vender um frå si rettferd og gjer urett, so skal han difor døy; for sin urett som han gjorde, skal han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Og når ein ugudleg vender um frå si gudløysa, som han hev gjort, og gjer rett og rettferd, so skal han halda si sjæl i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'For han såg alle sine misgjerningar som han hadde gjort, og vende um frå deim; liva skal han, han skal ikkje døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Men Israels-lyden segjer: «Herrens åtferd er ikkje rett.» Er ikkje mi åtferd rett, du Israels lyd? Er det ikkje dykkar åtferd som ikkje er rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Difor vil eg døma dykk, du Israels lyd, ein og kvar etter hans åtferd, segjer Herren, Herren. Vend um og vend dykk burt frå alle dykkar misgjerningar, so ikkje skuld skal føra dykk til fall!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Kasta frå dykk alle dykkar misgjerningar som de hev misfare dykk med, og få dykk eit nytt hjarta og ei ny ånd! For kvi vil de døy, du Israels lyd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'For eg hev ikkje hugnad i dauden åt den som døyr, segjer Herren, Herren. So vend då um, so skal de liva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Og du, set i med ein syrgjesong um Israels fyrstar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'og seg: «Kvar er mor di? Ei løvemor. Millom løvor ho låg, i ungløve-lag sine ungar ho ol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Og ho tamde upp ungen den eine, han vart ungløva, han, og han lærde å riva til seg ran; menner han åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Og folkeslag høyrde um honom; han vart fanga i deira grav, og med naseringar på vart han førd til Egypt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Og ho såg det - for ho stunda -: Hennar von var spilt. So tok ho ein til av sine ungar, honom sette ho til løva å vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Og han sveiv ikring millom løvor, ei ungløva sjølv. Og han lærde å røva til seg ran; menner åt han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Og han skjemde enkjorne deira, og han lagde deira byar øyde. Og landet med alt som var i det tok fæla av buringi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Då gjekk dei imot honom, folki frå fylki rundt ikring, og breidde sitt garn yver honom. Han vart fanga i deira grav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Og dei sette honom i bur, med naseringar på, og førde honom til kongen i Babel. So sette dei honom i tjukkmura borger, for at ein aldri meir skulde høyra hans røyst burtpå Israelsfjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Medan du fekk vera i ro, var di mor som eit vintre, planta attmed vatn, rikt på frukt og på greiner av alt det vatnet det hadde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Og det fekk sterke greiner til hovdingestavar, og høgt voks det upp millom skyer, og det var audsynt for si høgd og for rankorne mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Då vart det rive upp i harm og kasta på jordi, og austanvinden forturka frukti. Greinerne dei sterke vart rivne av og torna, elden øydde deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Og no er det planta i audni, i eit land so turt og tyrst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Og eld gjekk ut frå den kvistute grein, han øydde frukti. Og det hev ikkje meir nokor sterk grein til hovdingstav.» - Ein syrgjesong er det, og til ein syrgjesong vart det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Og det hende i det sjuande året, den tiande dagen i den femte månaden, at det kom nokre av Israels styresmenner og vilde spyrja Herren. Og dei sette seg framfor mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Menneskjeson! Tala til Israels styresmenner og seg med deim: So segjer Herren, Herren: Er det komne og vil spyrja meg? So sant som eg liver, so let eg ikkje dykk få spyrja meg, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Vil du døma deim, vil du døma, menneskjeson? Lat deim få vita styggedomen åt sine feder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Og du skal segja med deim: So segjer Herren, Herren: Den dagen eg valde ut Israel, og rette handi mi i veret for avkjømet i Jakobs hus og let deim verta kjende med meg i Egyptarlandet, då eg rette upp handi mi for deim og sagde: «Eg er Herren, dykkar Gud» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'den dagen rette eg upp handi på det, at eg vilde føra deim ut or Egyptarlandet og til eit land som eg hadde set ut åt deim, som fløymer med mjølk og honning; det er det fagraste av alle land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Og eg sagde med deim: «Kvar og ein av dykk kaste burt dei styggetingi han hev framfor augo, og gjer dykk ikkje ureine med Egyptarlands ufysne avgudar! Eg er Herren, dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Men dei var tråssuge mot meg og vilde ikkje høyra på meg; styggetingi dei hadde framfor augo, kasta dei ikkje burt, og Egyptarlands ufysne avgudar vende dei seg ikkje ifrå. Då sagde eg at eg vilde renna ut yver deim min harm og tøma ut min vreide på deim midt i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Og eg gjorde det for mitt namn skuld, so det ikkje skulde verta vanhelga framfor augo på dei folki som dei budde ibland, og som såg på at eg let deim verta kjende med meg og vilde føra deim ut or Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Og eg førde deim ut or Egyptarland og let deim koma inn i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Og eg gav deim bodi mine og kunngjorde deim mine lover, som menneskja skal helda og so liva ved deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Og eg gav deim og kviledagarne mine, so dei skulde vera til eit teikn millom meg og deim, so dei skulde vita at eg er Herren som helgar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Men Israels-lyden var tråssug imot meg i øydemarki; i mine bod ferdast dei ikkje, og dei svivyrde loverne mine, som menneskja skal halda og so liva ved deim, og kviledagarne mine vanhelga dei ovleg. Då sagde eg at eg vilde renna utyver deim min harm og tyna deim i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Men det vilde eg gjera for mitt namn skuld, so det ikkje skulde verta vanhelga framfor augo på dei folki som såg på at eg førde deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'So rette eg og upp handi i øydemarki på det, at eg ikkje vilde lata deim koma inn i det landet som eg hadde gjeve, som fløymer med mjølk og honning, det som er det fagraste av alle land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'for di dei svivyrde loverne mine og ikkje ferdast i bodi mine og vanhelga kviledagarne mine. For etter deira ufysne avgudar for deira hjarto.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Men mitt auga sparde deim, so eg ikkje tynte deim, og eg gjorde ikkje reint ende på deim i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Og eg sagde til borni deira i øydemarki: «I bodi åt federne dykkar må de ikkje ferdast, og loverne deira må det ikkje halda, og med deira ufysne avgudar må de ikkje gjera dykk ureine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Eg er Herren, dykkar Gud; i bodi mine skal det ferdast, og loverne mine skal det halda, og etter deim skal det gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Og kviledagarne mine skal de helga, og dei skal vera eit teikn millom meg og dykk, so de skal vita at eg, Herren, er dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Men dei var tråssuge mot meg, borni; i bodi mine ferdast dei ikkje, og loverne mine heldt dei ikkje, so dei gjorde etter deim, dei som menneskja skal gjera etter og so liva ved deim; kviledagerne mine vanhelga dei. Då sagde eg at eg vilde renna utyver deim min harm og tøma ut min vreide på deim i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Men eg tok handi mi tilbake og gjorde det for mitt namn skuld, so det ikkje skulde verta vanhelga framfor augo på dei folki som hadde set på at eg førde deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'So rette eg og upp handi i øydemarki på det, at eg vilde spreida deim millom heidningfolki og strå deim i landi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'for di dei ikkje heldt loverne mine, men svivyrde bodi mine og vanhelga kviledagarne mine, og deira augo for etter dei ufysne avgudarne åt federne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'So gav eg deim og bod som ikkje var gode, og lover som dei ikkje kunde liva ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Og eg let deim verta ureine med offergåvorne sine, med di dei let ganga gjenom elden alt som opnar morsliv, so eg kunde tyna deim, for at dei skulde skyna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Difor, tala til Israels-lyden, du menneskjeson! og du skal segja med deim: So segjer Herren, Herren: Med det og hædde dykkar feder meg, at dei for med svik imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'For eg førde deim inn i landet som eg med upprett hand hadde lova deim; men fyrst dei såg ein høg haug eller eit lauva tre, so ofra dei der sine slagtoffer, og der bar dei fram gåvor til å harmast av, og dit kom dei med godangen sin, og der rende dei ut sine drykkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Då sagde eg med deim: «Kva er det med haugen, sidan de kjem dit?» Og han fekk namnet «haug» alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Difor, seg med Israels-lyden: so segjer Herren, Herren: Vil de sulka dykk likeins som federne dykkar og i hordom renna etter deira styggedom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Ved gåvorne det kjem med og ved borni dykkar, som det let ganga gjenom elden, sulkar de dykk med alle dykkar ufysne avgudar alt til denne dag - og so skulde eg lata dykk spyrja meg, du Israels-lyd! So visst som eg liver, segjer Herren, Herren, dykk let eg ikkje spyrja meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Og det som leikar dykk i hugen, skal ikkje henda - når de segjer: «Me vil vera som heidningfolki, som hitt folket i landi; me vil tena tre og stein.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'So sant som eg liver, segjer Herren, Herren: med sterk hand og med strak arm og med utrend harm vil eg rikja yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Og eg vil føra dykk ut frå folki og samla dykk ut or landi, der som de var spreidde, med sterk hand og med strak arm og med utrend harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Og eg vil føra dykk til folkeheidi, og der vil eg ganga til doms med dykk, andlit til andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Likeins som eg gjekk til doms med federne dykkar i øydemarki attmed Egyptarlandet, so vil eg ganga til doms med dykk, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Og eg vil lata dykk ganga framum under hyrdingstaven, og eg vil leida dykk inn i pakt-bandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Og eg vil skilja ut ifrå dykk deim som sette seg upp imot meg og fall frå meg. Ut or landi der dei bur i utlægd, vil eg føra deim, men inn i Israels land skal dei ikkje koma. Og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Og du, Israels-lyd! So segjer Herren, Herren: Berre gakk, kvar ein av dykk, og ten dykkar ufysne avgudar! Men sidan skal de, sant og visst, høyra på meg og aldri meir vanhelga mitt heilage namn med gåvorne dykkar og med dei ufysne avgudarne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'For på mitt heilage fjell, på Israels høge fjell, segjer Herren, Herren, der skal de tena meg, all Israels lyd, alle som i landet er. Der vil eg hava hugnad i deim, og der vil eg spyrja etter offergåvorne dykkar og etter fyrstegrøda som de kjem med av alt det de helgar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'For den gode angen skuld vil eg hava hugnad i dykk, når eg fører dykk ut frå folki og samlar dykk ut or landi der som de var spreidde, og helgar dykk framfor augo på folkeslagi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Og de skal sanna at eg er Herren, når eg fører dykk til Israels land, det landet som eg med upprett hand hadde lova federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Der skal de minnast dykkar vegar og alle dei gjerningar som de hev sulka dykk med, og de skal styggjast ved dykk sjølve for alt det vonde som de hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Og de skal sanna at eg er Herren, når eg fer so åt med dykk for mitt namn skuld, ikkje etter dykkar vonde vegar og dykkar illgjerningar, du Israels-lyd, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Menneskjeson! Snu di åsyn mot sud og preika mot sud og spå imot skogen på marki i sud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Og du skal segja til skogen i sud: Høyr Herrens ord! so segjer Herren, Herren: Sjå, eg set eld på deg, og han skal svida av kvart eit grønt tre og kvart eit turt tre i deg. Den logande elden skal ikkje slokna, men han skal skambrenna kvart eit andlit frå sud til nord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Og alt kjøt skal sjå at eg, Herren, hev kveikt honom; slokna skal han ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Då sagde eg: «Å, Herre, Herre! Dei segjer um meg: «Er det ikkje berre i likningar han talar?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Då kom Herrens ord til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Menneskjeson! Snu di åsyn mot Jerusalem og preika mot heilagdomarne og spå mot Israelslandet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Og du skal segja til Israelslandet: So segjer Herren: Sjå, eg skal finna deg og draga sverdet utor slira og rydja ut or deg rettferdige og ugudleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Sidan eg vil rydja ut or deg rettferdig og ugudleg, so skal sverdet mitt fara utor slira mot alt kjøt frå sud til nord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Og alt kjøt skal sanna at eg, Herren, hev drege sverdet mitt or slira, det vert innatt-stunge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Og du, menneskjeson, sukka! Du skal sukka framfor augo deira so det knakar i dine lender - i såran sut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Og når dei då segjer med deg: «Kvifor sukkar du?» då skal du segja: «For ei fretnad; for han kjem. Då vil kvart eit hjarta bråna og alle hender siga, og kvar ei ånd dovna og alle kne verta som vatn. Sjå, det kjem, og det hender, segjer Herren, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Menneskjeson! Spå og seg: So segjer Herren: Seg: Eit sverd, eit sverd, kvest, ja, blenkt og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Til å halda slagting med er det kvest, og til å blikta som eldingen er det blenkt. Eller skulde me fegnast, du min sons ætt, som vanvyrder alt tre?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Og han let det blenkjast til eit handyvle; dette sverdet er kvest og blenkt, med det er etla åt dråpsmanns hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Ropa og barma deg, menneskjeson! For det er åt mitt folk, det er åt alle fyrstar i Israel; etla åt sverdet er dei med mitt folk. Difor, slå deg på lendi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'For prøva er komi, og kven skulde ho råka, um ikkje den ætti som vanvyrder tukt? segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Og du, menneskjeson! Spå og slå i hop henderne! Tvifelt, ja trifelt kjem sverdet: sverdet til å stinga menner, sverd til å stinga den store, det møter deim alle stader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Til eit bliktande sverd sette eg det imot alle portarne deira, so hjarto skal bråna og støytesteinarne verta mange. Å, det er gjort til å ljona, kvest til å slagta med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Tak deg på tak, sverd, hogg til høgre! Snu deg, hogg til vinstre! Kvar so eggi di snur!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Då skal eg og slå i hop henderne mine og svala min harm. Eg, Herren, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Og du, menneskjeson! Gjer deg tvo vegar som sverdet åt Babel-kongen kann fara fram på! Frå eitt land skal dei ganga ut båe. Laga so til ein vegvisar, laga honom til der vegarne tek av til kvar ein by!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Du skal gjera ein veg som sverdet kann fara fram på til Rabba åt Ammons-sønerne, og ein til Juda, inn i Jerusalem, borgbyen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'For Babel-kongen stend attmed vegemotet, der som båe vegarne tek til, og driv på med spaning; han rister pilerne, spør husgudarne, skodar på livri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'I høgre handi fær han luten «Jerusalem», at han skal setja upp murstangarar, lata upp munnen med tynar-rop, lata herrop ljoma, setja upp murstangarar mot portarne, kasta upp umlægringsvoll, byggja åtaksmurar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Men dei tykkjer det er berre fåfengd spådom; dei hev då lovnadseidar i mengd. Men han minner um misgjerning, so dei skal verta tekne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Difor, so segjer Herren, Herren: Etter di de hev drege dykkar misgjerning fram or gløymsla, med di dykkar brot vert openberra, so dykkar syndar vert synberre i alle dykkar verk - etter di de kjem fram or gløymsla, skal de verta tekne med handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Og du vanheilage gudløysing, Israels fyrste, din dag er komen når misgjerningi ein gong lyt enda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'So segjer Herren, Herren: Tak huva av, lyft kruna ned! Det som er, skal ikkje vera; det låge skal upp, det høge skal ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'I koll, i koll, i koll vil eg støyta det; det skal ikkje vera gjort med det heller - til dess han kjem som retten hev, han som eg vil gjeva det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Og, du menneskjeson, spå og seg: So segjer Herren, Herren um Ammons-sønerne og um deira svivyrding: Og du skal segja: Eit sverd, eit sverd er drege, blenkt til å slagta med, til å tyna, til å ljona,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'medan dei ser fåfengde syner og spår deg lygn, so du kann verta lagd attmed halsarne åt daudedømde gudløysingar som dagen er komen åt, når misgjerningi ein gong lyt enda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Stikk i slira ditt sverd! På den staden der du er skapt, i det landet du er ætta ifrå, vil eg døma deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Eg vil renna utyver deg min harm, min vreideloge vil eg blåsa imot deg og gjeva deg i henderne på villmenner, meistrar i tynarverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Elden skal øyda deg, ditt blod skal verta utrent midt i landet, ingen skal koma deg i meir hug; for eg, Herren, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Og du, menneskjeson! Vil du døma, vil du døma blodbyen? So lat honom få vita um all sin styggedom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Og du skal segja: So segjer Herren, Herren: Å, for ein by! som renner ut blod midt inni seg, so tidi hans må koma, og som gjer seg ufysne avgudar til å sulka seg med!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Med blodet som du hev rent ut, hev du ført skuld yver deg, og med dei ufysne avgudarne dine som du gjorde, hev du sulka deg, og du hev fenge dagarne dine til å nærma seg, og åri hev du nått. Difor gjer eg deg til spe åt folki og til spott for alle land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Dei som er nær og dei som er langt ifrå deg, skal hæda deg, du med ditt utskjemde namn og di vimande villa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Sjå, Israels fyrstar hjå deg leit kvar på sin arm - til å renna ut blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Far og mor vanvyrde dei hjå deg, mot den framande for dei fram med vald hjå deg, den farlause og enkja var dei harde med hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Heilagdomarne mine svivyrde du, og kviledagarne mine vanhelga du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Baktalarar var det hjå deg til å renna ut blod, på fjelli åt dei offermat hjå deg, skjemdarverk for dei med hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Hjå deg nækte dei fars blygsl, hjå deg skjemde dei kvende som var ureine i sine månadstider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Ein for med skjæmdarverk med grannekona si, ein annan skjemde ut sonekona si i skamlaus ulivnad, og endå ein annan skjemde syster si, dotter åt far sin, hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Mutor tok dei hjå deg for å renna ut blod. Renta og yvermål tok du, og mot grannen din gjorde du uskil med vald, og meg gløymde du, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Og sjå, eg hev slege henderne mine i hop yver syndepengarne du hev samla, og yver blodspillet som var hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Kann hjarta ditt standa seg eller henderne dine vera fullsterke i dei dagarne då du fær med meg å gjera? Eg, Herren, hev tala og vil setja det i verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Og eg vil spreida deg millom folki og strå deg i landi, og eg skal få ureinska di av deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Og du skal varta vanhelga ved deg sjølv framfor augo på folki. Då skal du sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Menneskjeson! Israels-lyden vart berre til slagg for meg; alle i hop er dei kopar og tin og jarn og bly inni ein omn, dei er sylvslagg vortne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Difor, so segjer Herren, Herren: Etter di de er vortne til slagg alle saman, sjå, so vil eg samla dykk i hop midt i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Likeins som ein samlar i hop sylv og kopar og jarn og bly og tin midt i ein omn og blæs upp eld på det og smelter det, soleis vil eg samla dykk i hop - i min vreide og harm - og eg vil hava dykk nedi og smelta dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Ja, eg vil sanka dykk saman og blåsa min vreide-eld på dykk, og der skal de smelta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Likeins som sylv smelter i ein omn, soleis skal de smelta der. Og de skal sanna at eg, Herren, hev rent ut min harm yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Menneskjeson! seg til det: Du er eit land som ikkje er reinsa, som ikkje hev fenge regn på ein vreide-dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Eit samansvore lag er deira profetar der, dei er som ei burande løva, ranande ran; sjæler et dei upp, eignaluter og dyrverdige ting tek dei, mange gjer dei der til enkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Prestane deira gjer vald på mi lov og vanhelgar heilagdomarne mine. Heilagt frå vanheilagt skil dei ikkje, millom ureint og reint lærer dei ikkje nokon å skilja, og for kviledagarne mine let dei att sine augo, og eg vert vanhelga midt ibland deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Fyrstarne deira er som vargar, ranande ran - med å renna ut blod, med å tyna sjæler, so dei kann auka syndepengarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Profetarne stryk på kalk åt deim, med di dei skodar fåfengd og spår lygn åt deim; dei segjer: «So segjer Herren, Herren,» endå Herren ikkje hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Landslyden fer med valdsverk, med flåing og ran, og med arming og fatigmann er dei harde, og mot den framande gjer dei vald og urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Og eg leita etter ein mann millom deim som vilde mura mur og standa i gapet framfor mi åsyn til vern for landet, so eg ikkje skulde leggja det i øyde, men eg fann ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'So vil eg då renna ut min vreide, i min brennande harm gjer eg ende på deim. Åtferdi deira legg eg på deira eige hovud, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Menneskjeson! Det var tvo kvinnor, døtter åt ei mor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Og dei dreiv hor i Egyptarland, i sin ungdom dreiv dei hor; der tukla dei med brjosti deira og klemde på deira møyarbarm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Og namni deira var: Åhåla, den største, og Åhåliba, syster hennar. Og dei vart mine og fødde søner og døtter. Og um namni deira er å segja: Samaria er Åhåla, og Jerusalem Åhåliba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Men Åhåla gav seg frå meg og dreiv hor, og ho tok til å lysta etter elskarane sine, etter assyrarane, dei våpndjerve,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'som var klædde i blått purpur, jarlar og landshovdingar, fagre sveinar alle saman, ridarar, ridande på hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Og med deim heldt ho seg i hordom, med alle dei gildaste av Assurs-sønerne. Og ho sulka seg med alle ho lyste etter, og med alle deira ufysne avgudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Og ho heldt seg ikkje frå sin hordom frå Egyptarland. For dei hadde lege med henne i hennar ungdom, og dei hadde klemt på hennar møyarbarm og helt ut yver henne sin hordom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Difor gav eg henne i henderne på hennar elskarar, i henderne på Assurs-sønerne, som ho hadde lysta etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Dei nækte blygsli hennar. Hennar søner og døtter tok dei, og henne sjølv drap dei med sverd. Og ho vart namnspurd ibland kvinnor, og dom heldt dei yver henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Og endå hennar syster Åhåliba såg det, vart ho skamlausare i sine lyster enn ho, og verre i sin hordom enn syster si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Ho lysta etter Assurs-sønerne, jarlar og landshovdingar, våpndjerve karar, gildt klædde, ridarar, ridande på sine hestar, fagre sveinar alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Og eg såg at ho vart sulka; ein og same veg gjekk dei båe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Og ho for endå lenger med sin hordom; då ho såg menner rita på veggen, bilæte av kaldæarar, måla med raude liter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'gyrde med belte um lenderne, med breide huvor på hovudet, sjåande til som vognkjempor alle saman, på skap Babels-sønerne som hev Kaldæa til heimland');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, '- då lysta ho etter deim fyrst ho såg deim for sine augo, og ho sende bod til deim i Kaldæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Og Babels-sønerne kom til henne og låg med henne i elskhug og sulka henne med sin hordom. Men då ho var utsulka med deim, vende hennar sjæl seg frå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Og ho for berrsynt fram med sin hordom og nækte blygsli. Då vende mi sjæl seg ifrå henne likeins som mi sjæl hadde vendt seg frå syster hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Men ho gjekk endå lenger i sin hordom, med di ho kom i hug ungdomsdagarne sine, då ho dreiv hor i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'So tok ho til å lysta etter horkallarne deira, som hadde kjøt nett som asen og fløde som hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Og du trådde etter ulivnaden i din ungdom, då egyptarane klemde på barmen din medan du hadde møyarbrjost.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Difor, Åhåliba, so segjer Herren, Herren: Sjå, eg vekkjer upp elskarane dine imot deg, deim som sjæli di hev vendt seg frå, og let deim koma yver deg frå alle stader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babels-sønerne og alle kaldæarar, Pekod og Sjoa og Koa, og alle Assurs-sønerne med deim, fagre sveinar, jarlar og hovdingar alle saman, vognkjempor, namnfræge menner, ridande på hestar alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Og dei skal koma yver deg med stridsmagt, vogner og hjul, og med ein flokk med folkeslag. Store skjoldar og små-skjoldar og hjelmar skal dei setja upp imot deg rundt ikring. Og eg vil setja deim til domarar, og dei skal døma deg med domarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Og min brennhug skal finna deg, og dei skal fara ått med deg i vreide; nosi di og øyro dine skal dei skjera av, og det som endå er att av deg, skal falla for sverd. Dei skal taka dine søner og døtter, og dei som endå vert att av deg, skal øydast i eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Og dei skal draga av deg klædi dine, og dei skal taka dine prydeting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'So vil eg gjera ende på di skjemdarferd og på din hordom frå Egyptarland, og du skal ikkje lyfta augo dine til deim, og Egyptarland skal du ikkje minnast meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'For so segjer Herren, Herren: Sjå, eg gjev deg i henderne på deim som du hatar, og i henderne på deim som di sjæl hev vendt seg frå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Og dei skal fara åt med deg i hat og taka alt det du hev stræva i hop og lata deg etter seg naki og berr, horeblygsli di skal verta nækt, og di skjemdarferd og din hordom skal verta synberr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Dette skal dei gjera med deg, av di du for etter heidningfolk i hordom, for di du sulka deg med deira ufysne avgudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'På vegen åt syster di hev du gjenge; so gjev eg deg hennar staup i di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'So segjer Herren, Herren: Staupet åt syster di skal du drikka, det djupe og vide - til lått og til spott skal du verta - det tek mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Av rus og sorg skal du verta full, eit øgjelegt tynar-staup er staupet åt di syster Samaria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Og du skal drikka det ut og suga utor det, og på broti av det skal du gnaga, og flengje brjosti dine sund, for eg hev tala, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Difor, so segjer Herren, Herren: Etter di du gløymde meg og kasta meg attum din rygg, so ber då du med di skjemd og din hordom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Og Herren sagde med meg: Menneskjeson! Vil du døma Åhåla og Åhåliba? Lat deim få vita sin styggedomen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'For dei hev drive hor, og det er blod på henderne deira og med sine ufysne avgudar hev dei drive hor, ja, jamvel borni sine, som dei hadde født åt meg, hev dei lata ganga gjenom elden, so dei skulde eta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Dessforutan gjorde dei dette mot meg: Dei sulka min heilagdomen same dagen og vanhelga mine kviledagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Når dei hadde slagta borni sine åt sine ufysne avgudar, so kom dei inn i min heilagdom, den same dagen, og vanhelga honom; og sjå, soleis for dei åt midt i mitt hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Ja, dei sende jamvel bod etter menner som skulde koma langt burtanfrå, ein sendemann gjekk til deim, og sjå, dei kom: for deim hadde du lauga deg, sminka deg i augo og prydt deg med prydeting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Og du sat på ein røseleg legebenk, og framanfor honom var duka eit bord, og min røykjelse og min olje hadde du sett uppå det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Og ståket av ein velnøgd folkehop kunde ein høyra der inne, og attåt menner som var med utav ålmugen, fekk dei seg drykkjebrør frå øydemarki. So gav dei kvendi armband på henderne og ei prydeleg kruna på hovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Då sagde eg um den utlivde skjøkja: «No fyrst driv dei ukjurskapen i det store med henne - ja, rett med henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Dei gjekk inn til henne nett som dei gjeng inn til ei skjøkja; soleis gjekk dei inn til Åhåla og Åhåliba, horkonorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'So skal då rettferdige menner døma deim etter lovi um horkonor, og um kvende som renner ut blod; for horkonor er dei, og det er blod på henderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'For so segjer Herren, Herren: Eg vil føra fram ein mannefjølde mot deim, og eg vil gjera deim til ei skræma og eit ran.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Mannfjølden skal steina deim i hel og hogga deim sund med sverdi sine. Deira søner og døtter skal dei drepa, og husi deira skal dei brenna upp med eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Soleis vil eg gjera ende på skjemdarferdi i landet, og alle kvinnor skal læra å vara seg, so dei ikkje fer med slik ei skjemdarferd som dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Og dei skal leggja dykkar skjemdarferd på dykk, og dykkar synder med dei ufysne avgudarne dykkar skal de bera, og de skal sanna at eg er Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Og Herrens ord kom til meg i det niande året, den tiande dagen i tiande månaden; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Menneskjeson! Skriv deg upp namnet på dagen - nett denne dagen! Babel-kongen er nådd til Jerusalem nett i denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Og tala i ein liknad til den tråssuge lyden og seg med deim: So segjer Herren, Herren: Set på gryta, set henne på, og slå vatn uppi henne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Hav kjøtstykki nedi henne, gode stykke alle, lår og bog! Fyll henne med dei likaste mergbein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Tak av det likaste av småfenaden! Gjer so eit eldsmål uppunder henne for beini skuld! Lat det fosskoka! Beini nedi henne kokar alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Difor, so segjer Herren, Herren: Usæl vere blodbyen: ei gryta med gravrust i, og hennar gravrust gjekk ikkje av henne! Tak utor henne stykke for stykke! det vert ikkje lutkasting um radi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'For blodet ho hev rent ut, er der endå; på eit bert svadberg hev ho helt det ut, ho hev ikkje rent det ut på jordi, so moldi kunde løyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'For at harm kunde hevjast og hemnen nå, hev eg late blodet koma på berre svadet, so det ikkje skulde verta løynt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Difor, so segjer Herren, Herren: Usæl vere blodbyen! Eg og vil gjera eldsmålet stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Legg på dugeleg med ved, kveik upp elden! Koka krafti or kjøtet, og lat sodet verta innkoka, so beini vert brende!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Og lat henne standa tom på gløderne, so ho vert heit og koparen glodheit, so ureinska kann smelta utor henne og gravrusti tærast burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Eg møddest so sårt med henne, men av gjekk ho ikkje, denne tjukke rusti. I elden då med henne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Di ureinska er vorti ei skjemd; etter di eg freista å reinsa deg, men du ikkje vart rein, so skal du ikkje verta rein heretter, fyrr eg fær døyva min harm på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Eg, Herren, hev tala; det kjem, og eg vil setja det i verk. Eg let det ikkje ugjort, og ikkje vil eg spara og ikkje angra. Etter dine vegar og dine gjerningar skal dei døma deg, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Og Herren ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Menneskjeson! Sjå, eg tek frå deg den dine augo hev hugnad i, ved eit slag. Men du skal ikkje barma deg og ikkje gråta, og ikkje ei tåra må renna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Sukka i løynd! men syrgjelag yver den daude må du ikkje gjera. Bitt huva di på deg, og tak skorne på føterne dine, og breid ikkje noko utyver skjegget, og et ikkje folks brød!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Og eg tala til folket um morgonen, og kona mi døydde um kvelden. Og morgonen etter gjorde eg som eg var fyresagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Då sagde folket med meg: «Vil du ikkje segja oss kva det skal tyda åt oss, det du gjer?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Og eg sagde med deim: Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Seg med Israels-lyden: So segjer Herren, Herren: Sjå, eg vanhelgar min heilagdom, som de lit på i ovmod, som dykkar augo hev hugnad i, og dykkar sjæl trår etter. Og dykkar søner og døtter, som de hev leivt etter dykk, skal falla for sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Då skal de gjera likeins som eg hev gjort; de skal ikkje breida noko yver skjegget og ikkje eta folks brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Og huvorne dykkar skal de hava på hovudi og skorne dykkar på føterne, og de skal ikkje barma dykk og ikkje gråta. Og de skal talmast av i dykkar misgjerningar og stynja kvar med annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Og Ezekiel skal vera eit teikn åt dykk; heiltupp som han hev gjort, skal de gjera. Når det kjem, då skal de sanna at eg er Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Og du, menneskjeson! Skal det ikkje henda den dagen når eg tek frå deim deira trygd, deira herlege frygd, det som deira augo hadde hugnad i og deira sjæl trådde etter, deira søner og døtter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'at den dagen skal dei som slepp undan koma til deg og gjera det kunnigt, so folk høyrer på?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Den same dagen skal du få lata upp munnen, når dei undansloppne er komne, og du skal tala og ikkje lenger vera mållaus, og du skal vera eit teikn åt deim, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Menneskjeson! Vend di åsyn mot Ammons-sønerne og spå imot deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Og du skal segja med Ammons-sønerne: Høyr Herrens, Herrens ord! So segjer Herren, Herren: Etter di du sagde: «Hå, hå!» yver heilagdomen min, for di han vart vanhelga, og yver Israels land, for di det er i øyde lagt, og yver Juda-lyden, for di han laut fara i utlægd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'difor, sjå, so skal austmennerne få deg til eiga, og dei skal slå sine tjeldlæger i deg og finna seg bustader i deg. Dei skal eta frukti di, og dei skal drikka mjølki di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Og eg vil gjera Rabba til beitemark åt kamelar og Ammonlandet til felæger. Og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'For so segjer Herren, Herren: Av di du klappa med henderne og trappa med føterne og med all vanvyrdnaden i di sjæl fagna deg yver Israels land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'difor, sjå, so retter eg handi mi imot deg og gjev deg til herfang åt folki og ryd deg ut or folkeslagi og let deg tynast ut or landi. Eg vil øyda deg ut, so du skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'So segjer Herren, Herren: Av di Moab og Se’ir segjer: «Sjå, det gjekk med Juda-lyden likeins som med alle hine folki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'difor, sjå, so vil eg gjera eit op i sida åt Moab frå der byarne ligg, frå byarne hans alle stader, landepryda Bet-Jesjimot, Ba’al-Meon og alt til Kirjatajim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'so Austheims-sønerne kann koma seg inn, likeins som eg vil gjera med Ammons-sønerne, som eg gjev deim til eiga, so ein ikkje meir skal minnast Ammons-sønerne millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Og yver Moab vil eg halda dom, so dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'So segjer Herren, Herren: Av di Edom var so hemnfus mot Juda-lyden og førde skuld yver seg, med di dei hemnde seg på deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'difor - segjer Herren, Herren - so vil eg retta ut handi mi mot Edom og øyda for honom folk og fe, og eg vil gjera det til ei audn frå Teman, og heilt burt til Dedan skal dei falla for sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Og min hemn mot Edom vil eg leggja i henderne på mitt folk Israel, og dei skal fara åt med Edom etter min vreide og harm, og dei skal få kjenna min hemn, segjer Herren, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'So segjer Herren, Herren: Av di filistarane for hemnfuse fram, av di dei med all vanvyrdnaden i si sjæl hemnde seg med tynarverk, av eit ævelegt hat,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'difor, so segjer Herren, Herren: Sjå, eg rettar ut handi mi mot filistarane og ryd ut kretarane og tyner det som vert leivt attmed havstrandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Og eg vil lata stor hemn råma deim vreide-refsingar, og dei skal sanna at eg er Herren, når eg let hemnen min nå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'So hende det i det ellevte året, den fyrste dagen i månaden, at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Menneskjeson! Av di Tyrus segjer um Jerusalem: «Hå, hå! I sund er folkeporten broten, til meg er han no flutt; eg vert fyllt sidan han er øydelagd,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'difor, so segjer Herren, Herren: Sjå, eg skal finna deg, Tyrus, og let mange folkeslag koma veltande upp yver deg, likeins som havet kjem veltande med bårorne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Og dei skal brjota ned murarne kring Tyrus og riva ned tårni, og eg vil sopa dusti av tufterne, og gjera byen til eit snaudt svadberg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Ein stad til å greida garn på skal det verta der uti havet, for eg hev tala, segjer Herren, Herren. Og det skal verta til herfang åt folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Og døtterne som er på innlandet, skal verta drepne med sverd. Og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'For so segjer Herren, Herren: Sjå, eg sender mot Tyrus Nebukadressar, Babel-kongen, frå Norderlandi, kongen yver kongarne, med hestar og med vogner og med hestfolk og med ein her og mykje folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Døtterne dine på innlandet skal han drepa med sverd. Og han skal gjera ein åtaksmur deg og kasta upp ein voll imot deg og reisa upp eit skjoldtak imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Og murstangaren sin skal han setja mot murarne dine, og tårni dine skal han brotja ned med jarni sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Hans hestar i mengd skal hylja deg i dumba. Gnyen av hestfolk og hjul og vogner fær murarne dine til å dirra, når han fer inn gjenom portarne dine, sameleis som når ein fer inn i herteken by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Med hovarne sine skal hestarne hans trakka ned alle gatorne dine. Lyden din skal han slå i hel med sverd, og dei sterke stolparne dine skal stupa til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Og dei skal rana din rikdom og gjera dine varor til herfang og brjota ned dine murar, og dine hugnadlege hus skal dei riva ned. Og steinarne dine og treverket ditt og dusti etter deg skal dei kasta beint på sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Og ljoden av songarane dine let eg tagna, og ljomen av cithrarne dine skal ein aldri meir høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Og eg vil gjera deg til ei bert svadberg, ein stad til å greida garni på skal du verta; du skal aldri verta uppatt-bygd. For eg, Herren, hev tala, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'So segjer Herren, Herren med Tyrus: Skal ikkje havstrenderne bivra for omen av ditt fall, når gjenomstungne styn, når dei drep og myrder midt inni deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Då skal dei stiga ned av sine høgsæte alle fyrstarne på havet, og dei skal leggja av seg kåporne sine og taka av seg sine rosesauma klæde. I skjelte skal dei klæda seg, på jordi skal dei sitja og skjelva kvar augneblink og ræddast yver lagnaden deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Og dei skal setja i med ein syrgjesong og segja til deg: «Korleis er du lagd i øyde, du som sjømanna bustad, byen den fræge, som hadde magti på havet, både du og dine ibuarar, som skaut skjelk i bringa på alle som budde der?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'No skjelv dei, øyarne, den dagen du fell, og utøyarne i havet tek fæla av di endelykt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'For so segjer Herren, Herren: Når eg gjer deg til ein øydestad, lik byar der ingen bur, når eg sender dragsudi uppetter deg og let storhavet gøyma deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'då støyper eg deg ned med deim som i gravi fer ned, til folket frå fordom, og let deg bu i nedheimen, i audner frå æva, med deim som fer ned i gravi, so ingen skal bu i deg; men eg vil gjeva pryda i landet åt dei livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Til ei skræma vil eg gjera deg, og so er du upp i inkje, og ein skal leita etter deg, men ikkje finna deg i all æva, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Og du, menneskjeson! Set i med ein syrgjesong yver Tyrus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Og du skal segja til Tyrus som bur attmed innlaupet frå havet, som handlar med folkeslagi på mange havstrender: So segjer Herren, Herren: Tyrus, du segjer: «Storfager er eg og frid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'I havsens hjarta er dine landskil, dei som bygde deg, gjorde deg storfager.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Av cypresstre frå Senir bygde dei alt plankeverket på deg. Cedertre frå Libanon tok dei og gjorde til mastr på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Av eik frå Basan gjorde dei årarne dine. Dekket ditt gjorde dei av filsbein, innlagt i buskbom frå Kittim-øyarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Manglita linty frå Egyptarland hadde du til segl, til å vera ditt merke, blått og purpurraudt ty frå Elisa-øyarne var ditt soltjeld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Folk frå Sidon og Arvad var roarar åt deg, dei kunnige av dine eigne, Tyrus, dei vart hovudsmennerne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Dei øvste og visaste frå Gebal hadde du til å bøta lekarne dine. Alle havskip og deira sjømenner var i deg og handla med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Menner frå Persia, Lud og Put var i din her, dine stridsmenner. Skjoldar og hjelmar hengde dei upp i deg, dei gav deg pryda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvads søner og din eigen her var på dine murar rundt ikring, og gammaditar var i dine tårn. Sine skjoldar hengde dei på murarne dine rundt ikring; dei gjorde deg fulleleg fager.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis handla med deg, av di du hadde so mykje gods. Sylv, jarn, tin og bly gav dei deg for varorne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal og Mesek, deim hadde du til kræmarar; menneskje og koparkjerald gav dei deg i varebyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Frå Togarma-lyden fekk du vognhestar og ridehestar og muldyr for varorne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Dedans søner var kræmarane dine. Mange havstrender kjøpte av di hand; filsbein og ibenholt gav dei deg i skatt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Syria handla med deg, av di du hadde mang ein eignalut; karfunkelstein, purpur og manglita ty og fint linty og korallar og rubinar gav dei deg i varebyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda og Israelslandet, dei var kræmarane dine; kveite frå Minnit og søt-kakor og honning og olje og balsam gav dei deg i varebyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus handla med deg, av di du hadde mang ein eignalut, ein ovmengd med allslags gods. Dei gav deg vin frå Hebron og kvit ull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan og Javan frå Uzal gav att for varorne dine; jarnsmide, kassia og kalmus fekk du i varebyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan handla med deg med salklæde til å rida på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabia og alle fyrstarne i Kedar kjøpte av di hand; lamb og verar og bukkar selde dei deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Kræmarane i Sjeba og Rama, dei var dine kræmarar; krydda av aller gjævaste slag og allslags dyreverdige steinar og gull gav dei for varorne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Kharan og Kanne og Eden, kræmarane i Sjeba, Assur, Kilmad handla med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Dei var dine kræmarar med prydelege eignating, med kåpor av purpurblått og manglita ty og med spriklute tæpe med tvinna sterke snøre på din marknad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Med Tarsis-skip gjorde du kjøpstemnorne dine. Du vart fyllt og ovende rik - midt i havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Utpå storhavet førde dine roarar deg - austanvinden bryt deg sund midt i havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Ditt gods, dine salsvaror og bytevaror, dine sjøfolk, dine skiprar, dei som bøter lekarne dine, og dei som driv din handel, og kvar ein stridsmann som i deg er, med heile ditt mannskap som er um bord, skal stupa midt i havet den dagen du fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'For naudropi frå skiprarne dine skal markerne bivra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Og dei skal stiga utor sine skip alle som med årarne sit, mannskapet og kvar skiper på havet, til land skal dei søkja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Dei skal barma seg yver deg og anka seg sårt. Og dei skal kasta mold på sine hovud, i oska skal dei velta seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Og dei skal raka seg snaude i kruna for di skuld og gyrda seg med sekk. Og dei skal gråta yver deg med sjælekvida og øya seg sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Og med dei barmar seg, skal dei setja i med ein syrgjesong yver deg og syrgjande kveda um deg: «Kven er lik Tyrus, som no er tagna midt uti havet?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Medan varorne dine kom frå havet, metta du mange folkeslag. Med ovmengdi av ditt gods og med dine bytevaror gjorde du kongarne på jordi rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'No då du er skipbroten og burtkomen på sjøen og ligg på havsens botn, no er dine bytevaror og alt ditt mannskap søkkt i kav med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Alle som bur på havstrenderne, tek fæla av din lagnad; det rys deira kongar i holdet, deira andlit bivra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kjøpmennerne ibland folkeslagi hæder deg; Ei skræma er du vorten, du er ikkje til - i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Menneskjeson! Seg med fyrsten i Tyrus: So segjer Herren, Herren: Av di at ditt hjarta ovmodar seg, og du segjer: «Eg er ein gud, i Guds høgsæte sit eg midt i havet,» og du er menneskje og ingen gud, endå du set ditt hjarta jamgodt med Guds hjarta');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, '- sjå, visare enn Daniel er du; ingen løyndom kann dei dylja for deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'med din visdom og ditt vit hev du vunne deg rikdom og samla gull og sylv i dine skattkammer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'med din store klokskap i handel hev du auka rikdomen din, og ditt hjarta ovmoda seg av din rikdom -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'difor, so segjer Herren, Herren: Av di du sette ditt hjarta jamgodt med Guds hjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'sjå, difor let eg framande koma yver deg, valdsmennerne millom folki, og dei skal draga ut sverdi sine mot din høgprude visdom og vanhelga di pryd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'I gravi skal dei støypa deg ned, og du skal døy ihelslegen manns daude midt uti havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Skal tru du då vil segja: «Eg er ein gud,» beint uppi syni på din banemann, endå du er eit menneskje og ingen gud i handi på din dråpsmann?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Som u-umskorne døyr, so skal du døy for framandmanns hand; for eg hev tala, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Menneskjeson! Set i med ein syrgjesong yver Tyrus-kongen! Og du skal segja med honom; so segjer Herren, Herren: Du som var innsigle på den vel tilmåta bygnaden, full av visdom og fullkomen vænleik:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'I Eden, Guds hage, var, yverstrådd med dyre steinar av alle slag: Karneol, topas og demant, krysolit, onyks og jaspis, safir, karfunkel, smaragd og gull. Arbeid i drive metall og utskurd prydde deg. Det var laga den dagen du vart skapt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Du var ein veldug kerub som gav livd, og eg sette deg til å vera på Guds heilage fjell, millom logande steinar ferdast du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Ulastande var du på dine vegar frå den dagen du vart skapt, til dess urettvisa fanst hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Den store handelen din valda at du vart full av urett og tok til å synda. Då vanhelga eg deg, so du laut burt frå Guds fjell, og eg tynte deg, du livd-gjevande kerub, so du ikkje lenger fekk vera millom dei logande steinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Ditt hjarta ovmoda seg av din vænleik, og du spillte din visdom for ditt glim. Til jordi kasta eg deg, framfor augo på kongar lagde eg deg, so dei kunde skoda deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Med dine mange misgjerningar, med din urettferdige handel vanhelga du heilagdomarne dine. So let eg eld loga midt utor deg, han skal øyda deg, og eg gjer deg til oska på jordi framfor augo på alle som ser deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Alle som kjende deg millom folkeslagi, er forfærde yver deg; ei skræma er du vorten, og du er ikkje til - i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Menneskjeson! Vend di åsyn mot Sidon og spå imot det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Og du skal segja: So segjer Herren, Herren: Sjå, eg finna deg, Sidon, og eg vil syna meg herleg i deg. Og dei skal sanna at eg er Herren, når eg held dom yver det og helgar meg på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Og eg vil senda inn i det sott og blod på gatorne. Og iheldslegne skal falla midt i det for sverd som kjem yver deim rundt ikring, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Og det skal aldri meir vera for Israels-lyden ein stingande klunger eller svidande tistel av alle deira grannar som svivyrder deim. Og dei skal sanna at eg er Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'So segjer Herren, Herren: Når eg samlar Israels-lyden ifrå folki der som dei er spreidde, då vil eg helga meg på deim framfor augo på folkeslag, og dei skal bu i sitt land som eg gav min tenar Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Og dei skal bu der i trygd og byggja hus og planta vinhagar, ja, dei skal bu i trygd, medan eg held dom yver alle deira grannar som vanvyrde deim. Og dei skal sanna at eg, Herren, er deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'I det tiande året, den tolvte dagen i tiande månaden, kom Herrens ord til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Menneskjeson! Vend di åsyn mot Farao, kongen i Egyptarland, og spå mot honom og imot alt Egyptarland!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Tala og seg: So segjer Herren, Herren: Sjå, eg skal finna deg, Farao, egyptarkonge, du, den store draken som ligg midt uti elvarne sine, og som segjer: «Eg eig mi elv, og sjølv hev eg gjort henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Og eg vil setja krokar i kjakarne dine, og fiskarne i elvarne dine vil eg festa i reisti dine, so dreg eg deg upp utor elvarne dine med alle fiskarne i elvarne dine, dei som er feste i reisti dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Og eg skal kasta deg ut i øydemarki, deg og kvar ein fisk i elvarne dine. På berre marki skal du falla; du skal ikkje verta uppteken, ikkje uppsamla, dyri på jordi og fuglarne under himmelen skal få deg til mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Og alle som bur i Egyptarland, skal sanna at eg er Herren, for di at dei vart ein røyrstav åt Israels-lyden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'når dei grip um deg med handi, brotnar du og flengjer deim alle i herdi, og når dei styd seg på deg, ryk du i sund og fær deim alle til å sviga i lenderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Difor, so segjer Herren, Herren: Sjå, eg let sverd koma yver deg, og eg vil rydja ut or deg folk og fe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Og Egyptarlandet skal verta til audn og øyda - og dei skal sanna at eg er Herren - for di han sagde: «Elvi er mi, og eg sjølv hev gjort henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Difor, sjå, eg vil finna deg og elvarne dine, og eg vil gjera Egyptarlandet til øydemarker, ei audn lagd i øyde, frå Midgol til Syene og alt til landskilet mot \'tiopia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Igjenom det skal ikkje mannefot ganga, og fefot skal ikkje ganga gjenom det, og det skal vera ubygt i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Og eg vil leggja Egyptarlandet i øyde midt ibland øydeland, og i byarne - midt ibland øydestader - skal det vera audt i fyrti år. Og eg vil spreida egyptarane millom folki og strå deim kringum i landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'For so segjer Herren, Herren: Når fyrti år er lidne, vil eg samla egyptarane frå dei folkeslag som dei var spreidde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Og eg vil venda Egyptarlands lagnad og føra deim attende til Patroslandet, til det landet som dei er ætta ifrå, og der skal dei vera eit vesalt kongerike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Det skal vera lægre enn andre kongerike og aldri meir hevja seg yver folki, og eg vil lata deim smogna i hop, so dei ikkje skal rikja yver folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Og aldri meir skal Israels-lyden der søkja seg livd og soleis minna meg um deira misgjerning, med di dei snur seg etter deim. Og dei skal sanna at eg er Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'So hende det i det sju og tjugande året, den fyrste dagen i fyrste månaden, at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Menneskjeson! Nebukadressar, Babel-kongen, hev late heren sin stræva hardt mot Tyrus; kvart eit hovud er fleinskalla, og kvar ei herd avgnura. Men løn hev han og heren hans ikkje fenge av Tyrus for alt sitt stræv imot det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Difor, so segjer Herren, Herren: Sjå, eg gjev Nebukadressar, Babel-kongen, Egyptarland, og han skal taka rikdomen der og rana ranet og hertaka herfanget, og det skal vera løn åt heren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Til løn åt honom for strævet gjev eg honom Egyptarland; for dei hev arbeidt for meg, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Den same dagen vil eg lata eit horn veksa upp åt Israels-lyden; og du skal få lata upp din munn midt ibland deim, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Og Herrens ord kom til meg, han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Menneskjeson! Spå og seg: So segjer Herren, Herren: Barma dykk: «Å! for ein dag!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'For nær er ein dag, ein dag for Herren; ein myrkskya dag, ei uppgjerdstid for folkeslagi skal det vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Og sverd skal koma mot Egyptarland, og \'tiopia skal få skjelve-rider når ihelstungne fell i Egyptarland. Og dei skal taka landsens rikdom, og grunnvollarne skal verta nedrivne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, '\'tiopar og folk frå Put og Lud og alt blandingsfolket og Kub og sønerne åt sambandslandet skal falla for sverd i lag med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'So segjer Herren: Dei som styd Egyptarland, skal falla, og ovmodet og magti skal kverva; frå Migdol til Syene skal folket falla for sverd, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Og i øyde skal dei liggja millom øydeland, og byarne skal vera millom øydestader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Og dei skal sanna at eg er Herren, når eg kveikjer eld på Egyptarland, og alle deira hjelparar vert krasa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Den dagen skal det fara sendemenner frå mi åsyn på skip til å setja støkk i det ottelause \'tiopia, og det skal få skjelve-rider som på Egyptarlands dag. For sjå, det kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'So segjer Herren, Herren: Eg vil hava Nebukadressar, Babel-kongen, til å gjera ende på den ståkande mengdi i Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Han og lyden hans med honom, valdsmennerne millom folki, skal verta henta til å herja landet. Og dei skal draga sine sverd mot Egyptarland og fylla landet med drepne menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Eg vil lata elvarne torna og selja landet i henderne på illmenne. Og eg vil hava framande til å øyda landet og alt som i det er; eg, Herren, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'So segjer Herren, Herren: Eg vil tyna dei ufysne gudarne og rydja ut avgudarne or Nof, og aldri meir skal der vera ein fyrste or Egyptarland, og eg vil leggja rædsla på Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Og eg vil leggja Patros i øyde og setja eld på Soan, og halda dom yver No.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Eg vil renna ut min harm yver Sin, den sterke verni åt Egyptarland, og rydja ut den ståkande mengdi i No.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Og eg vil setja eld på Egyptarland, Sin skal bivrande skjelva, og i No bryt dei seg inn, og inn i Nof kjem fiendar ljose dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Dei unge menner i Aven og Pibeset skal falla for sverd, og sjølve skal dei fara i utlægd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'I Tehafnehes skal dagen myrkna når eg der bryt sund egyptaroket, og ovmodet og magti skal endast. Sjølv vert det sveipt i skyer, og døtterne lyt fara i utlægd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Og eg vil halda dom yver Egyptarland, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'So hende det i det ellevte året, den sjuande dagen i fyrste månaden, at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Menneskjeson! Armen åt Farao, egyptarkongen, hev eg brote forderva. Og sjå, han er ikkje vorten umbunden til helsebot, og linda til å bera i fatle, so han kunde sterkna til å gripa sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Difor, so segjer Herren, Herren: Sjå, eg skal finna Farao, Egyptarlands-kongen, og eg skal brjota armarne hans sund, både den heile og den sundbrotne, og lata sverdet falla or handi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Eg vil spreida egyptarane ibland folki og strå deim ut i landi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Og Babel-kongens armar skal eg styrkja og gjeva honom sverdet mitt i hand. Men Faraos armar vil eg brjota, og han skal stynja for hans åsyn som ein stungen mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Ja, Babel-kongens armar vil eg styrkja, men Faraos armar skal siga ned. Og dei skal sanna at eg er Herren, når eg gjev Babel-kongen sverdet mitt i hand, og han retter det ut mot Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Og eg vil spreida egyptarane ibland folki og strå deim ut i landi, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'So hende det i det ellevte året, den fyrste dagen i den tridje månaden, at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Menneskjeson! Seg med Farao, egyptarkongen, og hans ståkande mengd: Kven likjest du på i di storvyrda?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Sjå, Assur var eit cedertre på Libanon med fagre greiner, ein skuggerik skog og høg på vokster, millom skyerne var hans kruna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vatnet gjorde honom stor, vatsdjupet gjorde honom høg. Med åerne sine gjekk det kringum hans plantehage og sende vatsveiterne sine burtåt alle trei på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Difor vart han høgre på vokster enn alle trei på marki. Og mange var hans greiner og lange hans kvister, av all den vatningi, når han rette deim ut i veret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'På kvistarne hans laga dei seg reir, alle himmelens fuglar, under greinerne hans fødde alle dyr på marki sine ungar, og hans skugge gav livd åt alle dei mange folkeslagi som budde der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Og han var fager i sin vyrdelege storleik med sine lange greiner, for innmed roti hans var det nøgdi av vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Inkje var cedertre i Guds hage hans jamlike; cypressor kunde ikkje liknast med hans kvister, og løntre var ikkje som hans greiner; det beid ikkje tre i Guds hage jamfagert med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Eg hadde prydt honom med greiner i mengd, og dei ovunda honom alle Eden-trei som var i Guds hage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Difor, so segjer Herren, Herren: Sidan han er vorten so høg på vokster og hev tøygt kruna si upp imillom skyerne, og hjarta hans ovmodar seg av denne store høgdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'so gjev eg honom i henderne på ein hovding yver folki; med honom fær han å gjera; det er for gudløysa hans eg hev drive honom ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Og framande, valdsmennerne millom folki, hev hogge honom ned og late honom liggja. På fjelli og i kvar ein dal fall hans kvister, og greinerne hans ligg sundbrotne nedi kvart eit gil i landet. Og alle folk på jord er stigne ned utor skuggen hans som gav deim livd, og hev late honom liggja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'På den falne stomnen hans held alle himmelens fuglar til, og yver greinerne hans fer kvart dyr i skog');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, '- for at ikkje noko velvatna tre skal ovmoda seg av sin vokster og tøygja kruna si upp imillom skyerne, og dei velduge av deim, dei som syg vatn i mengd, ikkje skal standa der høgreiste. For alle er dei gjevne dauden i vald, so dei lyt fara ned til nedheimen, midt imillom mannsborni, til deim som er stigne ned i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'So segjer Herren, Herren: Den dagen han for ned til helheimen, let eg syrgja på honom; vatsdjupet breidde eg yver for hans skuld, og åerne derifrå stemde eg, og dei store vatn laut stana. Og eg klædde Libanon i svart for hans skuld, og kvart tre på marki ormegtast for hans skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Med dunen av hans fall fekk eg folkeslag til å skjelva, då eg støypte honom ned i helheimen med deim som fer ned i gravi. Då huggast dei i nedheimen, alle Eden-trei, dei likaste og beste på Libanon, alle som drikk vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Dei og for ned i helheimen til deim som var slegne i hel med sverd. For dei hadde vore hans arm medan dei sat i livd i hans skugge midt imillom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Kven likjest du soleis på i herlegdom og storvyrda ibland Eden-trei? - So skal du då verta støypt med Eden-trei ned i nedheimen; midt imillom u-umskorne skal du liggja med deim som er slegne i hel med sverd. Dette er Farao og heile hans ståkande mengd, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'So hende i det tolvte året, den fyrste dagen i tolvte månaden, at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Menneskjeson! Set i med ein syrgjesong yver Farao, egyptarkongen, og seg til honom: Ei ungløva millom folki vilde du vera lik, og so var du som draken i havet, og du for fram i elvarne dine, og grugga upp vatnet med føterne dine og rota upp straumarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'So segjer Herren, Herren: Eg vil då breida ut garnet mitt yver deg i ei samling av mange folkeslag, og dei skal draga deg upp med noti mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Eg vil kasta deg upp på land og burt på marki vil eg slengja deg, og eg vil gjeva alle himmelens fuglar tilhelde på deg og lata dyri på heile jordi metta seg med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Eg vil kasta kjøtet ditt upp på fjelli og fylla dalarne med den store skrotten din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Og eg vil vatna landet som du sym i med blodet ditt, heilt upp til fjelli, og bekkjefari skal verta fulle av deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Og når let deg slokna, vil eg breida yver himmelen og klæda hans stjernor i svart, yver soli vil eg breida skyer, og månen skal ikkje skina med sitt skin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Alle skinande himmelljos vil eg klæda i svart for di skuld, og eg vil leggja myrker på landet ditt, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Og eg vil lata mange folkeslag gremmast i hjarta, når eg gjer tjonet på deg kunnigt millom folki i land som du ikkje kjenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Eg vil gjera mange folkeslag forfærde yver deg, og deira kongar skal rysja i holdet yver deg, når eg svingar mitt sverd framfor augo deira, og dei skal bivra kvar augneblink, kvar og ein for sitt liv, den dagen du fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'For so segjer Herren, Herren: Sverdet åt Babel-kongen skal koma yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Di ståkande hop vil eg lata falla for sverdi at kjempor, valdsmenner millom folki alle saman. Og dei skal tyna Egyptarlands ovmod, og all den ståkande hopen skal verta øydd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Og eg vil rydja ut alt feet frå dei mange vatni, og ingen manns fot skal heretter grugga deim, og ingi ku-klauv skal grugga deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Då vil eg lata vatni deira minka og løkjerne deira renna som olje, segjer Herren, Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'når eg legg Egyptarlandet i øyde og audn - eit tomt land, av di eg slær ned alle som i det bur. Og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Ein syrgjesong er dette, og syngja honom skal dei, folke-døtterne skal syngja honom; um Egyptarland med si ståkande mengd skal dei kveda det, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'So hende det i det tolvte året, den femtande dagen i månaden, at Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Menneskjeson! Barma deg yver Egyptarlands ståkande mengd og send henne ned, henne og døtterne åt herlege folkeslag, til nedheimen med deim som fer i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Kven gjeng du no framum i vænleik? Far ned og få deg læger millom u-umskorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Ibland sverdslegne menner skal dei falla. Sverdet er gjeve; drag henne burt og heile hennar ståkande mengd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Velduge millom kjempor skal tala um honom og hans hjelpesmenner midt utor helheimen: «Ned er dei farne, der ligg dei, dei u-umskorne, slegne i hel med sverd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Der er Assur og heile hans lyd, rundt kringum honom er hans graver; alle er dei slegne i hel, falne for sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Han fekk sine graver inst inni hola, og hans lyd er rundt kringum hans graver; alle er dei slegne i hel, falne for sverd, dei som breidde ut skræmsla i landet åt dei livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Der er Elam og heile hans ståkande mengd, rundt kringum hans graver; alle er dei slegne i hel, falne for sverd, dei som u-umskorne for ned til nedheimen, dei som breidde ut skræmsla i landet åt dei livande, og bar si skam med deim som fer ned i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Midt imillom drepne menner gav dei honom læger med heile hans ståkande mengd, rundt ikringum honom er hans graver. Alle er dei u-umskorne, slegne i hel med sverd, di at dei breidde ut skræmsla i landet åt dei livande, og dei bar si skam med deim som for ned i gravi; midt imillom drepne menner vart han lagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Der er Mesek-Tubal og heile hans ståkande mengd, rundt kringum honom er hans graver. Alle er dei u-umskorne, slegne i hel med sverd, di at dei breidde ut skræmsla i landet åt dei livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Skulde dei då ikkje liggja hjå kjempor, hjå dei falne av dei u-umskorne, som for ned i helheimen med sin stridsbunad og fekk sverdi sine lagde under sine hovud, og misgjerningarne sine yver sine bein, for dei hadde vore ei skræmsla for kjempor i landet åt dei livande?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Og du, midt ibland u-umskorne skal du verta krasa, og du skal liggja hjå deim som er slegne i hel med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Der er Edom med sine kongar og alle sine fyrstar, som, med alt sitt velde, er lagde hjå deim som er slegne i hel med sverd. Dei skal liggja hjå dei u-umskorne, og hjå deim som fer ned i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Der er fyrstarne frå Norderland alle saman, og alle Sidon-buarne som for ned med drepne menner og vart til skammar, endå dei i sitt velde hadde vore til skræmsla, og u-umskorne fekk dei læger hjå dei som var slegne i hel med sverd. Og dei bar si skam med deim som fer ned i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Deim skal Farao sjå, og huggast yver all si ståkande mengd. Slegne i hel med sverd er Farao og heile hans her, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'For eg breidde ut rædsla for honom i landet åt dei livande. Og han skal verta lagd hjå dei u-umskorne, med deim som er slegne i hel med sverd, Farao og all hans ståkande mengd, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Menneskjeson! Tala til landslyden din og seg med deim: Når eg let sverd koma yver eit land, og dei tek utav folket i landet og set honom til vaktmann åt seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'og han ser sverdet koma yver landet og blæs i luren og varar folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'og einkvan høyrer ljomen av luren, men ikkje let seg vara, og sverdet kjem og tek honom burt, då skal blodet hans vera på hans eige hovud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'ljomen av luren høyrde han, men let seg ikkje vara, blodet hans skal kome yver honom sjølv; for hadde han late seg vara, so hadde han berga livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Men um vaktmannen ser sverdet koma og ikkje blæs i luren, og folket ikkje vert vara, og sverdet kjem og tek burt einkvan av deim, då er han burtteken for si misgjerning, men blodet hans vil eg krevja av handi åt vaktmannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Og, du menneskjeson! Til vaktmann hev eg sett deg åt Israels-lyden. Når du då høyrer eit ord frå min munn, so skal du vara deim åt frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Um eg då segjer med den ugudlege: «Du ugudlege, du skal døy,» og du ikkje talar og varar den ugudlege for hans åtferd, då skal han, den ugudlege, døy for si misgjerning, men blodet hans vil eg krevja av di hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Men um du hev vara den ugudlege for hans åtferd, at han måtte venda um frå henne, men han vender ikkje um frå si åtferd, då skal han døy for si misgjerning, men du hev berga di sjæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Og du, menneskjeson! Seg til Israels-lyden: So segjer det: «Våre brot og våre synder tyngjer på oss, og for deim talmast me reint burt; kor kann me då liva?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Seg med deim: So sant som eg liver, segjer Herren, Herren, eg hev ikkje hugnad i det at den ugudlege døyr, men i det at den ugudlege vender um frå si åtferd og liver. Vend um, vend um frå dei vonde vegarne dykkar! For kvi vil de døy, du Israels-lyd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Og du, menneskjeson! Seg med ditt folks born: Rettferdig manns rettferd skal ikkje frelsa honom på hans misgjerds-dag, og ugudleg manns gudløysa skal ikkje fella honom den dagen han vender um frå si gudløysa, og ein rettferdig skal ikkje kunna liva ved si rettferd den dagen han syndar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Når eg segjer med den rettferdige at han skal liva, men han lit på si rettferd og gjer urett, då skal alle hans rettferdige verk verta gløymde, og for sin urett som han gjorde, skal han døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Og når eg segjer til den ugudlege: «Du skal døy,» og han vender um frå si synd og gjer rett og rettferd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'so han, den gudlause, gjev pant attende, kjem att med rana gods, ferdast i livsens bod, so han ikkje gjer urett, då skal han liva, han skal ikkje døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Alle synderne som han hev gjort, skal vera gløymde. Rett og rettferd hev han gjort, liva skal han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Mitt folks born segjer: «Herrens åtferd er ikkje rett,» endå at det er deira eigi åtferd som ikkje er rett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Når ein rettferdig vender um frå si rettferd og gjer urett, so skal han døy for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Og når den gudlause vender um frå si gudløyse og gjer rett og rettferd, so skal han få liva for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Endå segjer de: «Herrens åtferd er ikkje rett.» Eg vil døma dykk kvar etter si åtferd, du Israels-lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'So hende det i det tolvte året etter me var burtførde, den femte dagen i den tiande månaden, at dei undanslopne frå Jerusalem kom til meg og sagde: «Byen er teken.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Men Herrens hand var komi yver meg um kvelden, fyrr dei undanslopne kom; og han let upp munnen min innan dei kom til meg um morgonen. So var då munnen min upplaten, og eg var ikkje mållaus meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Menneskjeson! Dei som bur millom desse røysarne i Israelslandet, dei segjer: «Abraham var berre ein, og han fekk landet til eiga, men me er mange, oss er landet gjeve til eiga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Seg difor med deim: So segjer Herren, Herren: De et kjøtet med blodet i og retter augo dykkar etter dei ufysne avgudarne dykkar, og renner ut blod - og de skulde eiga landet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'De lit på dykkar sverd, de fer med skjemdarverk, og skjemmer konorne åt kvarandre - og de skulde eiga landet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'So skal du segja med deim: So segjer Herren, Herren: So sant som eg liver, skal dei som bur millom røysarne falla for sverd, og den som er på marki, gjev eg til mat åt udyri, og dei som held på knausar og i hellerar, skal døy av sott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Og eg vil leggja landet i audn og øyde, og det skal vera ute med ovmodet og magti hjå det, og Israels heidar skal liggja i øyda, so ingen ferdast der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Og dei skal sanna at eg er Herren, når eg legg landet i audn og øyde for alle deira skjemdarverk, som dei hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Og du, menneskjeson! Ditt folks born talar seg imillom um deg frammed veggjerne og i husdørerne, og segjer med kvarandre, den eine med den andre: «Kom, lat oss høyra kva for eit ord det er som no gjeng ut frå Herren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Og dei kjem åt deg, nett som eit heilt folk kjem, og set seg framfor di åsyn og læst vera mitt folk og lyder på ordi dine; men dei gjer ikkje etter deim. For det munnen deira likar, det gjer dei, og etter vinning fer deira hjarte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Og sjå, du er som eit elskhugskvæde åt deim, som ein songar med vænt mål og ljuvlegt spel. Og dei lyder på ordi dine, men gjer ikkje etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Men når det kjem - og koma skal det - då skal dei sanna at ein profet hev vore millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Menneskjeson! Spå mot Israels hyrdingar! Spå og seg med deim, med hyrdingarne: So segjer Herren, Herren: Usæle Israels hyrdingar som røktar seg sjølve! Er det ikkje hjordi hyrdingen skal røkta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Feita et de, og med ulli klæder de dykk, og det gjødde slagtar de; hjordi gjæter de ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Det veike hev de ikkje styrkt, og det sjuke hev de ikkje lækt, det beinbrotne hev de ikkje bunde um, og det burtdrivne hev de ikkje sanka, og det burtkomne hev de ikkje leita upp, men de hev fare hardt fram mot deim og med vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Og dei vart spreidde, av di dei var hyrdinglause, og dei vart til føda åt kvart villdyr på marki, og spreidde vart dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Forvilla fer sauerne mine på alle fjell og på alle høge hamrar, og utyver alt landet er sauerne mine spreidde, og ingen spør etter deim, og ingen leitar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Difor, de hyrdingar, høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'So sant som eg liver, segjer Herren, sanneleg, etter di sauerne mine er vorte til eit ran, ja, sauerne mine er vortne til føda for åt kvart villdyr på marki, og hyrdingarne mine ikkje spurde etter sauerne mine, men hyrdingarne røkta seg sjølve og ikkje røkta sauerne mine -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'difor, de hyrdingar, høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'So segjer Herren, Herren: Sjå, eg vil finna hyrdingarne og krevja sauerne mine av deira hand og taka frå deim gjætsla, so hyrdingarne ikkje lenger skal røkta seg sjølve. Og eg vil berga sauerne mine frå deira munn, so dei ikkje skal verta til føda åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'For so segjer Herren, Herren: Sjå, her er eg sjølv, og eg vil spyrja etter sauerne mine og sjå til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Likeins som ein hyrding ser til si hjord den dagen han er millom dei spreidde sauerne sine, soleis vil eg sjå til sauerne mine. Og eg vil berga deim frå alle stader der dei er spreidde på ein dag med skyer og myrkeskodda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Og eg vil føra deim ut ifrå folkeslagi og sanka deim ut or landi, og føra deim til deira eige land; og eg vil gjæta deim i Israelsfjelli, i dalarne og på alle bustader i landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'I ei god gjætslemark vil eg gjæta deim, og i Israels høge fjell skal deira hamning vera. Der skal dei roa seg i ei god hamning og ganga i feit beitemark i Israelsfjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Eg sjølv vil gjæta sauerne mine, og eg vil få deim til å roa seg, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Det burtkomne vil eg leita upp, og det burtdrivne vil eg sanka, og det beinbrotne vil eg binda um, og det sjuke vil eg styrkja. Men det feite og det sterke vil eg tyna; rett vil eg røkta deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Og de, sauerne mine - so segjer Herren, Herren -: Sjå, eg dømer millom sauer og sauer, millom verar og bukkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Er det ikkje nok åt dykk å ganga i det beste beite, sidan de trakkar ned med føterne det som stend att på beitet dykkar? Er det ikkje nok at de drikk det klåraste vatnet, sidan de rotar upp med føterne det som er att?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Og sauerne mine, dei lyt eta det som de hev trakka med føterne, og drikka det de hev rota upp med føterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Difor, so segjer Herren, Herren med deim: Sjå, her er eg sjølv, og eg vil døma millom dei feite sauerne og dei magre sauerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Etter di de trengjer alle dei veike undan med sida og bog og stangar deim med horni dykkar, til de fær spreidt deim og jaga deim av,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'so vil eg berga sauerne mine, og dei skal ikkje lenger vera til ran, og eg vil døma millom sauer og sauer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Og eg vil reisa upp ein einaste hyrding yver deim, og han skal gjæta deim, min tenar David. Han skal gjæta deim, og han skal vera deira hyrding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Eg, Herren, skal vera deira Gud, og min tenar David skal vera fyrste millom deim. Eg, Herren, hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Og eg vil gjera ei fredspakt med deim og rydja ut udyr or landet, so dei trygt kann bu i øydemarki og sova i skogarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Og til ei velsigning vil eg gjera deim og landet rundt ikring min haug, eg vil lata det regna i rett tid, eit regn til velsigning skal det vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Og trei på marki skal gjeva si frukt, og jordi skal gjeva si grøda, og dei skal hava det trygt i landet sitt. Og dei skal sanna at eg er Herren, når eg bryt sund stengerne i oket deira, og frelsar deim frå deira hender som trælka deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Og dei skal ikkje lenger vera eit ran for folki, og villdyri i landet skal ikkje eta deim upp. Men trygt skal dei bu, og ingen skal skræma deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Og eg vil laga til ein namngjeten plantehage åt deim, og dei skal aldri meir verta burtrykte av hunger i landet, og aldri meir skal dei tola hæding frå heidningfolki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Og dei skal sanna at eg, Herren, deira Gud, er med deim, og at dei, Israels-lyden, er mitt folk, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Og de, sauerne mine, sauerne som eg beiter, menneskje er de. Eg er dykkar Gud segjer, Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Menneskjeson! Vend di åsyn mot Se’irfjellet og spå imot det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Og du skal segja med det: So segjer Herren, Herren: Sjå, eg vil finna deg, Se’irfjell, og eg vil retta ut mi hand imot deg og leggja deg i audn og øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Byarne dine vil eg gjera til steinrøysar, og du sjølv skal verta ei audn. Og du skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Etter di du ber på ein æveleg fiendskap og let Israels-borni koma under sverds-egg i deira usæletid, den tidi då misgjerningi laut enda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'difor, so sant eg liver, segjer Herren, Herren, til blod vil eg gjera deg, og blod skal søkja på deg. Sidan du ikkje hev hata blod, so skal blod søkja på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'So vil eg då leggja Se’irfjellet i audn og øyde, og eg vil rydja ut or det både komande og farande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Og eg vil fylla fjelli med slegne menner. På dine haugar og i dine dalar og i alle dine gil skal menner falla, slegne med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Til ævelege audner vil eg gjera deg, og byarne dine skal ikkje atter verta bustader, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'For di du sagde: «Båe folki og båe landi skal verta mine, og eg vil taka deim til eiga,» endå Herren hev vore der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'difor, so sant eg liver, segjer Herren, Herren, vil eg gjera med deg etter den vreiden og ovundi som du hev synt i ditt hat imot deim, og eg skal verta kjend hjå deim når eg dømer deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Og du skal sanna at eg Herren. Eg hev høyrt alle hæde-ordi dine, som du hev tala mot Israelsfjelli, då du sagde: «Dei er i øyde lagde! dei er gjevne åt oss til mat.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Og de hev bruka munnen mot meg i ovmod og var ordrame mot meg; eg hev nok høyrt det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'So segjer Herren, Herren: Medan all jordi fagnar seg, vil eg leggja deg i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Likeins som du fagna deg yver arvluten åt Israels-lyden, at han vart avøyd, so vil eg gjera med deg; til audn skal du verta, du Se’irfjell, og alt Edom - alt i hop, og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Og du menneskjeson! Spå um Israelsfjelli! Og du skal segja: Det Israelsfjell, høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'So segjer Herren, Herren: For di fienden sagde: «Hå, hå!» yver dykk, og: «Dei ævelege haugar hev vorte vår eiga,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'difor spå og seg: So segjer Herren, Herren: Etter di, ja, etter di dei avøyder dykk og glefser etter dykk frå alle leider, so hine folki kann eigna dykk til seg, og etter di de er komne på folketunga og hev fenge eit låkt ord på dykk ibland folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'difor, de Israelsfjell, høyr Herrens, Herrens ord! So segjer Herren, Herren, med fjelli og med haugarne, med gili og dalarne og med røysarne på dei aude tufterne og med øydebyarne som hev vorte til ran og spott for hine folki som er der ikring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'difor, so segjer Herren, Herren: Sanneleg, i min brennande harm hev eg tala mot hine folki og mot Edom, som hev etla seg landet mitt til eiga - med heile si hjartans gleda, med vanvyrdnad i si sjæl - so dei kunde driva ut deim som budde der og so rana det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Difor, spå um Israels land og seg med fjelli og med haugarne, med gili og med dalarne: So segjer Herren, Herren: Sjå, i mitt åbry og i min harm hev eg tala, etter di de hev lote tolt skjemsla frå folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Difor, so segjer Herren, Herren: Eg rette handi mi i veret på det: Sanneleg, folki som bur kringum dykk, skal sjølv ljota bera si skjemsla!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Men de, Israelsfjell, skal skjota dykkar greiner og bera dykkar frukt åt mitt folk Israel; for snart skal dei koma heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'For sjå, eg vil finna dykk, eg vil snu meg åt dykk, og de skal verta dyrka og sådde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Og eg vil føra ei mengd med menneskje upp på dykk, all Israels-lyden, og byarne skal atter få folk, og øydestaderne verta bygde å nyo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Og eg vil gjera dykk rike på folk og fe, og dei skal aukast og verta rike på avkjøme. Og eg vil gjeva dykk folkerike bygder som fyrr i tidi, og eg vil gjera dykk endå meir godt enn i dykkar fyrste tider, og de skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Og eg vil lata menneskje, mitt folk Israel, ferdast på dykk, dei skal taka deg til eiga, og du skal vera deira odel. Og du skal aldri meir gjera deim barnlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'So segjer Herren, Herren: Etter di dei segjer um deg: «Ein mann-etar er du, og barnlaus hev du gjort dine folk,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'difor skal du aldri meir eta menneskje og aldri meir gjera folki dine barnlause, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Og aldri meir let eg deg høyra skjemsla frå folki, og vanvyrdnad frå folkeslagi skal du aldri meir turva tola, og folki dine skal du aldri meir få til å snåva, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Menneskjeson! Israels-lyden budde i landet sitt, og dei sulka det med si åtferd og sine verk; som ureinskapen hjå kvinna når ho hev sine tider, so var deira åtferd for mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Då rende eg ut min harm yver deim for det blod som dei hadde rent ut yver landet, og for di dei hadde sulka det med dei ufysne avgudarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Og eg spreidde deim millom folki, og dei vart strådde i landi; etter deira åtferd og verk dømde eg dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Då dei kom til dei folki som dei for til, då vanhelga dei mitt heilage namn, med di det vart sagt um deim: «Dette er Herrens folk, men ut or landet hans laut dei fara.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Då gjorde det meg ilt for mitt heilage namn som Israels-lyden hadde vanhelga millom dei folki som dei var komne til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Seg difor med Israels-lyden: so segjer Herren, Herren: Ikkje for dykkar skuld, du Israels-lyd, gjer eg det, men for mitt heilage namn skuld, som de hev vanhelga millom dei folki som de er komne til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Og eg vil helga mitt store namn som vart vanhelga millom folki med di de vanhelga det ibland deim. Og folki skal sanna at eg er Herren, segjer Herren, Herren, når eg helgar meg på dykk for augo deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Og eg vil henta dykk frå folki og sanka dykk ut or alle landi og flytja dykk til dykkar eige land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Og eg vil skvetta reint vatn på dykk, so de vert reine; frå all dykkar ureinska og frå alle dykkar ufysne avgudar vil eg reinsa dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Og eg vil gjeva dykk eit nytt hjarta, og ei ny ånd vil eg gjeva inni dykk, og eg vil taka burt steinhjarta or dykkar kjøt og gjeva dykk eit kjøthjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Og min ande vil eg gjeva inni dykk, og eg vil få dykk til å ferdast i mine bod og til å halda loverne mine og gjera etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Og de skal bu i det landet som eg gav federne dykkar. Og de skal vera mitt folk, og eg skal vera dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Og eg vil fria dykk frå all dykkar ureinska. Og eg vil kalla på kornet og gjera det follrikt og ikkje senda svolt på dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Og eg vil mangfalda frukti på trei og grøda på marki, so de ikkje lenger skal taka mot skjemsla frå folki for svolt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Då skal de minnast dykkar vonde åtferd og dykkar verk, som ikkje var gode. Og de skal styggjast ved dykk sjølve for dykkar misgjerningar og styggjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Ikkje for dykkar skuld gjer eg det, segjer Herren, Herren, det vere dykk kunnigt! De må blygjast og skjemmast av åtferdi dykkar, du Israels-lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'So segjer Herren, Herren: Den dagen eg reinsar dykk frå alle dykkar misgjerningar, vil eg gjeva byarne folk, og husi som ligg i røysar, skal verta uppatt-bygde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Og øydeland skal verta dyrka, i staden for at det var ei audn for augo på kvar mann som gjekk framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Då skal dei segja: «Dette land som var i øyde lagt, er vorte som Eden-hagen, og byarne som låg i røyser og var øydelagde og nedrivne, er no kringmura og hev sine ibuarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Og dei skal sanna, dei folki som vert att rundt ikring dykk, at eg, Herren, hev bygt upp att det nedrivne, hev planta i det aude landet. Eg, Herren, hev tala, og eg set det i verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'So segjer Herren, Herren: I dette og vil eg lata Israels born finna meg, so eg gjer det for deim: Eg let menneskje aukast som ein saueflokk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Som ein heilag saueflokk, som Jerusalems-sauer i høgtiderne, soleis skal dei aude byarne verta: fulle med manneflokkar. Og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Herrens hand kom yver meg, og han førde meg i Herrens ande og sette meg ned midt i dalen, som no var full av bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Og han let meg ganga framum deim rundt ikring, og sjå, det var ei ovmengd av deim utyver dalen, og sjå, dei var ovleg turre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Og han sagde med meg: «Menneskjeson! Skal tru dei vil livna upp att, desse beini?» Og eg sagde: «Herre, Herre, du veit det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Og han sagde med meg: «Spå yver desse beini! Og seg med deim: De turre bein, høyr Herrens ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'So segjer Herren, Herren, med desse beini: Sjå, eg let ånd koma i dykk, og de skal livna upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Og eg vil setja senar på dykk og lata det koma kjøt på dykk og draga hud yver utanpå dykk og gjeva ånd i dykk, og de skal livna upp att. Og de skal sanna at eg er Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Og eg spådde so som eg var fyresagd. Då vart det ei skråving medan eg spådde, og sjå, det tok til å braka, og beini drog seg imot kvarandre, bein til bein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Og eg såg, og sjå, det kom senar og kjøt på deim, og det drog seg hud utanpå deim. Men ånd var det ikkje i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Og han sagde med meg: «Spå til anden! Spå, menneskjeson, og seg med anden: So segjer Herren, Herren: Kom, du ande, frå dei fire vindar og anda på desse drepne menner, so dei kann livna upp att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Og eg spådde so som han sette meg til. Og anden kom i deim, og dei livna, og dei stod på føterne sine, ein ovleg, ovleg stor her.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Og han sagde med meg: «Menneskjeson! Desse beini, dei er heile Israels-lyden. Sjå, dei segjer: «Turre er våre bein; vår von vart um inkje, det er ute med oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Spå difor og seg med deim: So segjer Herren, Herren: Sjå, eg opnar graverne dykkar og let dykk, lyden min, risa upp or graverne dykkar, og eg vil føra dykk til Israels land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Og de skal sanna at eg er Herren når eg opnar graverne dykkar og let dykk, folket mitt, risa upp or graverne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Og eg vil senda min ande i dykk, og de skal livna upp att, og eg vil lata dykk få bu i landet dykkar. Og de skal sanna at eg er Herren; eg hev tala og vil setja det i verk, segjer Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Og du, Menneskjeson! Tak deg ein trestav og skriv på honom: «For Juda og dei Israels-born som er med honom.» Og tak deg ein annan stav og skriv på honom: «For Josef, ein stav for Efraim og all Israels-lyden som er med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Legg deim so i hop, ein attåt hin, so du fær deim til ein stav, og dei vert til eitt i handi di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Og når landsmennerne dine segjer til deg: «Vil du ikkje lata oss få vita kva du meiner med dette?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'tala då til deim: «So segjer Herren, Herren: Sjå, eg tek Josefs stav, som er i Efraims hand, og Israels ætter som er med honom, og eg legg deim attåt Judas stav og gjer deim til ein stav, so dei vert til eitt i handi mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Og stavarne som du skriv på, skal du halda i handi di framfor augo på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Og du skal tala til deim: «So segjer Herren, Herren: Sjå, eg tek Israels-borni burt frå dei folki som dei for til, og eg vil samla deim frå alle stader og føra deim inn i landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Og eg vil gjera deim til eitt folk i landet, på Israelsfjelli, og ein konge skal vera konge yver deim alle, og dei skal aldri meir vera tvo folk, og aldri meir vera sundbytte i tvo rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Og dei skal aldri meir sulka seg med dei ufysne avgudarne sine og med styggjorne sine eller med nokor av alle misgjerningarne sine. Og eg vil fri deim ut frå alle sine bustader, der dei hev synda, og eg vil reinsa deim, og dei skal vera mitt folk, og eg vil vera deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Og min tenar David skal vera konge yver deim, og ein hyrding skal vera åt deim alle. Og i mine lover skal dei ferdast, og mine bod skal dei halda og gjera etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Og dei skal bu i det landet som eg gav min tenar Jakob, der som federne dykkar budde. Dei skal bu i det, dei sjølve og borni deira og barneborni deira, æveleg, og David, min tenar, skal vera deira fyrste, æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Og eg vil gjera ei fredspakt med deim, ei ævepakt med deim skal det vera. Og eg vil busetja deim og lata deim aukast og setja min heilagdom midt ibland deim æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Og min bustad skal vera yver deim, og eg skal vera deira Gud, og dei skal vera mitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Og folki skal sanna at eg er Herren som helgar Israel, når min heilagdom vert verande millom deim æveleg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Og Herrens ord kom til meg; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Menneskjeson! Vend di åsyn mot Gog i Magoglandet, fyrste yver Ros, Mesek og Tubal, og spå mot honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Og du skal segja: So segjer Herren, Herren: Sjå, eg vil finna deg, Gog, fyrste yver Ros, Mesek og Tubal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Og eg vil snu deg um og krøkja krokar i munnvikarne dine og føra deg ut med all din her, hestar og ridarar, i full herbunad alle saman, ein heil mannfjølde med store skjoldar og små, med sverd i hand alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persar og ætiopar og putæar er med deim, alle saman med skjold og hjelm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer og alle hans herskarar, Togarma-lyden, lengst or Norderland og alle hans herskarar; mange folkeslag hev du med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Herbu deg og gjer deg reidug, du og alle herflokkarne dine, som hev samla seg til deg, og du må varda deim vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Etter mange dagar kjem turen til deg, når åri renn ut, skal du koma til eit land som er berga undan for sverd, sanka frå mange folkeslag, uppå Israelsfjelli, som stødt låg i øyde. Men no er det ført ut frå folkeslagi, og trygt bur dei alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Og du skal draga dit upp; som ei stormflaga skal du koma, som ei sky skal du vera til å skyla landet, du og alle herskararne dine og mange folkeslag med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'So segjer Herren, Herren: Og det skal henda den dagen, at ord skal koma upp i ditt hjarta, og du skal tenkja ein illrådig tanke');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'og segja: «Eg vil fara upp mot eit land utan verjevollar, eg vil koma på desse som er i ro, som bur trygt: alle saman bur dei utan verjemur, og bommar og portar vantar dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Til å rana ran og gjera herfang er du komen, og til å leggja di hand på uppatt-bygde øydestader, mot eit folk som er sanka frå folkeslag, og som el seg til bufe og gods, som er busett på jord-navlen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Sjeba og Dedan og kjøpmenner frå Tarsis og alle deira ungløvor skal segja med deg: «Kjem du hit og vil rana ran? Hev du drege i hop dine herskarar til å gjera herfang, til å føra burt sylv og gull, til å taka bufe og gods, til å rana ran i det store?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Difor, spå, menneskjeson, og seg med Gog: So segjer Herren, Herren: Den dagen då mitt folk Israel bur trygt, skal du då ikkje få vita det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Og du skal koma frå din stad langt nord i heimen, du og mange folkeslag med deg, ridande på hestar alle saman, ein stor skare og veldug her.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Og du skal fara upp mot mitt folk Israel og skyla landet med ei sky. I dei siste dagarne skal det henda, då let eg deg koma yver landet mitt, so folkeslagi skal læra å kjenna meg, når eg syner min heilagdom på deg, Gog, framfor augo på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'So segjer Herren, Herren: Er det du som eg tala um i forne dagar gjenom mine tenarar, profetarne i Israel, som spådde i dei dagarne, år for år, at eg vilde lata deg koma yver deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Og det skal henda den same dagen, den dagen Gog kjem yver Israelslandet, segjer Herren, Herren, då skal harmen min koma upp i mi nos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Og i min brennhug, i min logande vreide talar eg: Sanneleg, den dagen skal det vera ein stor jordskjelv yver Israelslandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Og skjelva for mi åsyn skal fiskarne i havet og fuglarne under himmelen og dyri på marki og alt kreket som krek på jordi og kvart eit menneskje som er på jord-yta. Og rivna skal fjelli, og rynja skal hamrarne, og kvar ein mur skal falla til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Og eg vil kalla sverd imot honom på alle mine fjell, segjer Herren, Herren; sverd skal dei svinga mot kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Og eg vil halda dom yver honom med sott og med blod. Og hyljande regn og haglande steinar, eld og svåvel vil eg lata regna yver honom og yver hans herskarar og yver dei mange folkeslag som er med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Og eg vil syna meg stor og heilag og gjera meg kjend for augo på mange folkeslag. Og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Og du, menneskjeson! Spå mot Gog og seg: So segjer Herren, Herren: Sjå, eg vil finna deg, Gog, fyrste yver Ros, Mesek og Tubal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Og eg vil snu deg um og jaga deg fram og få deg til å koma upp, lengst or Norderland, og lata deg koma upp på Israelsfjelli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Og eg vil slå bogen din utor vinstre handi og lata pilerne dine detta utor høgre handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'På Israelsfjelli skal du falle, du og all herskararne dine og folkeslagi som er med deg. Til rovfuglar av alle slag og til villdyri på marki gjev eg deg til mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Utyver marki skal du falla; for eg hev tala, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Og eg vil senda eld på Magog og på dei som bur trygt i øylandi. Og dei skal sanna at eg er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Og mitt heilage namn vil eg gjera kunnigt midt ibland mitt folk Israel, og aldri meir vil eg lata mitt heilage namn verta vanhelga, og folkeslagi skal sanna at eg er Herren, heilag i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Sjå, det kjem, og det hender, segjer Herren, Herren; det er dagen som eg hev tala um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Då skal dei som bur i Israels-byarne ganga ut og gjera upp eld og kveikja upp med herbunader; både med store skjoldar og med små, med bogar og med piler og med stavar og mot spjot. Og med dette til brennefang skal dei elda i sju år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Dei skal ikkje henta ved or marki og ikkje hogga i skogarne, for dei skal elda med herbunaderne. Og dei skal rana sine ransmenner og herja sine herjarar, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Og det skal henda same dagen, at eg vil gjeva Gog ein gravstad i Israel, Ferdamannsdalen austum havet, og han skal stengja vegen for ferdafolket. Der skal dei gravleggja Gog og heile mannemugen hans, og dei skal kalla det Gogs-muge-dalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'I sju månader skal Israels-lyden jorda deim, det skal vera til å reinsa landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'All landslyden skal jorda deim, og det skal gjera deim namnfræge den dagen eg syner meg herleg, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Og dei skal velja ut menner som stødt skal fara um i landet og jorda deim som der hadde fare fram, deim som hadde vorte liggjande etter utyver jordi; det skal vera til å reinsa det. Når sju månader er lidne, skal dei taka til med leitingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Når då yverfararane fer um i landet og fær sjå eit mannebein, skal dei setja upp et merke attmed det til gravarane fær grave det ned i Gogs-muge-dalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Ogso eit bynamn skal vera Hamona. Soleis skal dei reinsa landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Og du, menneskjeson! So segjer Herren, Herren: Seg med kvar fljugande fuglen og kvart eit udyr på marki: Samla dykk saman og kom! Sanka dykk frå alle stader til slagtofferet mitt, som eg hev slagta åt dykk, eit stort slagtoffer på Israelsfjelli. Og de skal eta kjøt og drikka blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Kjøt av kjempor skal de få eta, og blod frå fyrstar på jord skal de få drikka; verar, lamb og bukkar og uksar, gjødde i Basan alle i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'De skal få eta feitt til de vert mette, og drikka blod til det vert drukne, av slagtofferet mitt som eg slagtar åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Og de skal verta mette ved mitt bord med ridehestar og vognhestar, med kjempor og hermenner av alle slag, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Og eg vil syna mitt storvelde millom folki, og alle folki skal sjå min dom, som eg hev halde, og mi hand, som eg hev lagt på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Og Israels-lyden skal sanna at eg er Herren, deira Gud, frå den dagen og framleides.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Og folkeslagi skal skyna at det var for sine misgjerningar Israels-lyden vart burtførd, for di dei for med svik imot meg, so eg laut løyna mi åsyn for deim og gjeva deim i fiendehand, so dei fall for sverd alle saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Etter deira ureinskap og misgjerningar for eg fram imot deim og løynde mi åsyn for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Difor, so segjer Herren, Herren: No vil eg enda Jakobs fangetid og miskunna all Israels-lyden, og eg vil vera ihuga for mitt heilage namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Og dei skal bera si skjemsla og all si utrue framferd mot meg, når dei bur trygt i landet sitt, og ingen skræmer deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Når eg fører deim tilbake frå folkeslagi og sankar deim or fiendelandi og helgar meg på deim for augo på dei mange folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'då skal dei sanna at eg er Herren, deira Gud, med di at eg førde deim burt til folkeslagi, men samlar deim no inn i deira eige land og ikkje leiver ein einaste av deim etter meg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'So vil eg aldri meir løyna mi åsyn for deim, for eg hev rent ut min ande yver Israels-lyden, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'I det fem og tjugande året etter me vart burtførde, ved nyårsleite, den tiande dagen i månaden, i det fjortande året etter byen vart teken - nett den dagen kom Herrens hand yver meg, og han førde meg dit burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'I syner frå Gud førde han meg til Israelsland. Og han sette meg ned på eit ovhøgt fjell, og uppå det var det liksom ein uppbygd by i sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Og han førde meg dit burt. Og sjå, der var det ein mann, og han var sjåande til mest som kopar, og han heldt eit linsnøre i handi og ei mælestong. Og han stod i porten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Og mannen tala til meg: «Menneskjeson! Sjå med augo dine og lyd etter med øyro dine og hugfest alt det eg syner deg! For du er førd hit so eg kann få syna deg det. Kunngjer for Israels-lyden alt det du ser!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Og sjå, det var ein mur utanum huset rundt ikring. Og mannen heldt mælestongi i handi, ho var seks alner lang, kvar aln ei handbreidd lenger enn ei vanleg aln. Og han mælte breiddi på muren: ei stong, og høgdi: ei stong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'So kom han åt ein port som snudde i aust, og han steig uppetter troppestigi. Og han mælte ein dørstokk i porten: ei stong breid, og so ein dørstokk til: ei stong breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Og kvart vaktrom var ei stong langt og ei stong breidt. Og millom vaktromi var det fem alner. Og dørstokken i porten innmed forhalli i porten innvendes var ei stong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Han mælte forhalli i porten innvendes; ei stong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Og han mælte forhalli i porten: åtte alner, og stolparne hans: tvo alner. Og forhalli i porten låg på innsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Og vaktromi i porten mot aust var tri på kvar sida, alle tri like store. Og stolparne på båe sidorne var like store.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'So mælte han dørviddi på porten: ti alner, og lengdi på porten: trettan alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Og det var ei sval på ein aln framfor vaktromi, og ei sval på ei aln på hi sida. Og kvart vaktrom var seks alner på den eine sida og seks alner på hi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'So mælte han porten frå taket på det eine vaktromet til taket på hitt. Breiddi var fem og tjuge alner. Dør var mot dør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Og han gjorde stolparne seksti alner. Og burtåt stolparne rakk fyregarden, med porten rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Og frå framsida på inngangsporten til framsida på forhalli i den indre porten var det femti alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Og det var vindaugo med fast grind fyre på vaktromi og på stolparne deira innantil imot porten rundt ikring, og likeins på hallerne. Og soleis var det vindaugo rundt ikring innantil, og på stolparne var det palmor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'So let han meg koma til den ytre fyregarden, og sjå, der var kovar og eit steinlagt golv i fyregarden rundt ikring. Det var tretti kovar på steingolvet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Og steingolvet var frammed sideveggjerne på portarne, jamlangt med portlengderne; det var det lægre steingolvet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Han mælte breiddi frå framsida åt den nedre porten til den ytre framsida åt den indre fyregarden: eit hundrad alner austetter og nordetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'So mælte han lengdi og breiddi på den porten som snudde i nord, på den ytre fyregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Den og hadde tri vaktrom på kvar sida, og likeins stolpar og haller like store som i den fyrste porten; femti alner lang og fem og tjuge alner breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Og vindaugo og hallerne og palmorne her var like stor som i den porten som vende i aust. Og dei steig upp i porten på sju troppestig, og hallerne låg framanfor deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Og ein port til den indre fyregarden var der midt imot porten i nord og i aust, og han mælte eit hundrad alner frå ein port til hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'So let han meg ganga sudetter, og sjå, der var ein port som snudde i sud. Og han mælte stolparne og hallerne der og; dei heldt same mål som hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Det var vindaugo på honom og på hallerne rundt ikring, likeins som dei andre vindaugo. Han var femti alner lang og fem og tjuge alner breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Og troppi der hadde sju stig, og hallerne var framanfor deim, og på stolparne var det palmor, ein på kvar sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Og det var ein port til den indre fyregarden på sudsida. Og han mælte frå denne porten til sudporten: eit hundrad alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'So let han meg koma til den indre fyregarden gjenom sudporten. Og han mælte sudporten: han heldt same mål som hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Og vaktromi og stolparne og hallerne der heldt same mål som hine. Og det var vindaugo på honom og på hallerne rundt ikring. Han var femti alner lang og fem og tjuge alner breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Og det var haller rundt ikring: fem og tjuge alner lange og fem alner breide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Og hallerne der låg utåt den ytre fyregarden. Og på stolparne var det palmor. Og troppi hadde åtte stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'So let han meg koma til din indre fyregarden på austsida. Og han mælte porten: han heldt same mål som hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Vaktromi og stolparne og hallerne der heldt same mål som hine. Og det var vindaugo på honom og på hallerne rundt ikring. Han var femti alner lang og fem og tjuge alner breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Og hallerne der låg ut åt den ytre fyregarden. Og det var palmor på stolparne på båe sidor. Og troppi hadde åtte stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'So let han meg koma til nordporten. Og han mælte honom: han heldt same mål som hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Likeins vaktromi, stolparne og hallerne der. Og det var vindaugo rundt ikring. Han var femti alner lang og fem og tjuge alner breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Og stolparne der stod innmed den ytre fyregarden, og det var palmor på stolparne på båe sidor. Og troppi hadde åtte stig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Og det var ein kove med dørgap i portstolparne. Der skulde dei skylja brennofferet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Og i forhalli åt porten var det tvo bord på kvar sida til å slagta brennofferet og syndofferet og skuldofferet på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Og innmed den ytre sideveggen som snudde i nord, når ein steig upp i port-inngangen, var det tvo bord, og innmed hin sideveggen på forhalli åt porten stod det og tvo bord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Det vart då fire bord innmed kvar sidevegg på porten, soleis åtte i alt. På deim skulde dei slagta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Og til brennofferet var det fire bord av tilhoggen stein, ei og ei halv aln lange, og ei og ei halv aln breide og ei aln høge. På deim skulde dei leggja ambodi til å slagta brennofferet og slagtofferet med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Og tvigreina nabbar, ei tver hand breide, var feste på huset rundt ikring, men på bordi skulde offerkjøtet leggjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Og utanfor indreporten var det kovar åt songarane i den indre fyregarden, innmed sideveggen på nordporten, og framsida deira snudde i sud. Ei koverad låg innmed sideveggen på austporten, med framsida mot nord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Og han sagde med meg: Denne koveradi som snur i sud med framsida si, er åt dei prestarne som hev umsut med det som skal gjerast i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Men den koveradi som snur i nord med framsida si, er åt dei prestarne som hev umsut med altartenesta; dei er Sadoks-søner, dei av Levi-sønerne som kjem nær til Herren og tener honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'So mælte han fyregarden: eit hundrad alner lang og eit hundrad alner breid i firkant. Og altaret var framfyre huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'So let han meg koma til forhalli i huset. Og han mælte stolparne i forhalli: fem alner på den eine sida og fem alner på hi, og breiddi på porten: tri alner på den eine sida og tri alner på hi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Forhalli var tjuge alner lang og elleve alner breid, og ho hadde troppestig som dei steig upp til henne på. Og det var sulor innmed stolparne, ei på kvar sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'So let han meg koma til tempelsalen. Og han mælte stolparne: seks alner breide på den eine sida og seks alner på hi; det er breiddi på tjeldbudi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Og dørgapet var ti alner breidt, og sideveggjerne innmed døri var fem alner på kvar sida. So mælte han lengdi på det: fyrti alner, og breiddi: tjuge alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Sidan gjekk han inn i det inste romet. Og han mælte dørstolparne: tvo alner kvar, og døri: seks alner, og breiddi på døri: sju alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Og han mælte lengdi på det: tjuge alner, og breiddi: tjuge alner, beint innåt templet! So sagde han med meg: «Dette er det høgheilage.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'So mælte han husveggen: seks alner, og breiddi på sidekovarne: fire alner, rundt ikring heile huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Og sidekovarne låg, kove attmed kove, i tri høgder, tretti i rad, og dei rakk inni den muren som huset hadde mot sidekovarne rundt ikring, so dei hadde studnad. Men dei studde seg ikkje i sjølve husveggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Og viddi rundt ikring auka på for sidekovarne uppetter og uppetter; for hussvali gjekk uppetter og uppetter rundt kringum huset. Difor vidkast huset uppetter, og soleis steig ein upp frå nedste høgdi gjenom den millomste til den høgste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Og eg såg at huset låg på ein pall som nådde rundt ikring, og grunnvollarne åt sidekovarne var ei full stong, seks alner til kanten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Tjukkleiken på utveggen åt sidekovarne var fem alner. Og romet millom sidekovarne på huset');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'og hine kovarne hadde ei vidd på tjuge alner kringum huset, rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Og inngangarne til sidekovarne låg ut åt dette romet, ein inngang i nord og ein i sud. Og breiddi på romet som var att, var fem alner breidt rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Og den bygnaden som låg innmed det fråskilde tunet på vestsida, var sytti alner breid, og veggen på bygnaden var fem alner tjukk, rundt ikring, og nitti alner lang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Og han mælte huset: hundrad alner langt, og det fråskilde tunet og bygnaden med vegg: hundrad alner lange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Og framsida på huset og det fråskilde tunet mot aust var hundrad alner på breidd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'So mælte han lengdi på den bygnaden som låg på baksida innmed det fråskilde tunet, og svalerne på båe sidor åt bygnaden: hundrad alner. Likeins det indre templet og hallerne i fyregarden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'dørstokkarne og vindaugo med dei faste grindar og svalerne rundt ikring i deira tri høgder, romi innmed dørstokken, som var klædde med tre, rundt ikring, likeins høgdi frå jordi upp åt vindaugo. Og attfyre vindaugo var det lemmar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Uppyver døri, både inn imot det indre romet og utetter, og elles utyver heile veggen, innan og utan, var det utmælte bolkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Og der var det gjort kerubar og palmor, so at det var ei palma millom tvo kerubar, kvar kerub hadde tvo andlit;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'eit mannsandlit mot palma på den eine sida og eit ungløve-andlit mot palma på hi. So var gjort på heile huset rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Frå jordi til uppyver døri var kerubar og palmor gjorde, slik var tempelveggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Templet hadde firkanta dørskier, og framsida på heilagdomen såg like eins ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Og altaret var av tre, tri alner høgt og tvo alner langt, og det hadde hyrno sine, og langsida og veggjerne var av tre. Og han tala til meg: «Dette er bordet som stend framfor Herrens åsyn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Og templet og heilagdomen hadde tvo dører.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Og dørerne var tvihurda, kvar hurd med gangjarn; tvihurda var den eine og tvihurda var den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Og på deim, på tempeldørerne, var det gjort kerubar og palmor likeins som på veggjerne. Og det var eit vartak av tre på framsida åt forhalli utantil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Og det var vindaugo med fast grind og palmor på sideveggjerne åt forhalli, på båe sidor, likeins på sidekovarne i huset og på vartaki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'So let han meg ganga ut i den ytre fyregarden den vegen som gjekk nordetter. Og han let meg koma til den kovebygnaden som låg midt framfor det fråskilde tunet og beint imot bygnaden i nord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'til langsida som var på hundrad alner, med inngang i nord, men breiddi var femti alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Beint imot eit stykke på tjuge alner av den indre fyregarden og midt framfor steingolvet i den ytre fyregarden, var det sval mot sval i tri høgder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Og framanfor kovarne var det ein ti alner breid gang innetter, ein veg på ei aln; og dørerne deira snudde i nord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Og dei øvste kovarne var dei minste, for svalerne tok burt meir rom frå deim enn frå dei nedste og dei millomste i bygnaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'For dei låg i tri høgder, men hadde ikkje stolpar so som dei i fyregarden; difor smalkast det meir for dei øvste kovarne enn for dei nedste og millomste, frå jordi og uppetter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Og ein mur som var utanfor, frammed kovarne, imot den ytre fyregarden, gjekk framanfor kovarne. Han var femti alner lang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'For lengdi på dei kovarne som låg imot den ytre fyregarden, var femti alner, men sjå, mot templet: hundrad alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Og nedunder desse kovarne var inngangen mot aust, når ein gjekk inn i deim frå den ytre fyregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Der fyregardsmuren imot aust var på det tjukkaste, framanfor det fråskilde tunet og framanfor bygnaden, var det kovar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Og ein veg gjekk framanfor deim. Dei såg ut som dei kovarne som låg mot nord, like lange og like breide; likeins alle utgangar og tilskipnader elles og dørgap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Og likeins dørerne på dei kovarne som låg mot sud; det var ei dør der som vegen tok til, vegen frammed den muren som høyrde til, vegen austetter når ein gjekk inn i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'So sagde han med meg: «Kovarne mot nord og kovarne mot sud, som ligg innmed det fråskilde tunet, dei er heilage kovar, der prestarne som er nær Herren skal eta det høgheilage. Der skal dei leggja det høgheilage, både grjonofferet og syndofferet og skuldofferet, for staden er heilag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Når prestarne gjeng inn, so skal dei ikkje ganga ut att or heilagdomen og ut i den ytre fyregarden, men der skal dei leggja av seg klædi som dei hev gjort tenesta i, for dei er heilage. Dei skal taka på seg andre klæde og so ganga dit der folket må vera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Og då han hadde gjort mælingi frå seg i det indre huset, fylgde han meg ut gjenom den porten som hadde framsida mot aust, og der mælte han rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Han mælte austsida med mælestongi: fem hundrad stenger etter mælestongi rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Han mælte nordsida: fem hundrad stenger etter mælestongi rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Sudsida mælte han: fem hundrad stenger etter mælestong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Han snudde og gjekk mot vestsida; han mælte fem hundrad stenger etter mælestong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'På dei fire sidorne mælte han det. Det hadde ein mur rundt ikring: fem hundrad stenger lang og fem hundrad breid, til å skilja det heilage frå det som var uhelga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'So let han meg ganga til porten, den porten som snudde i aust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Og sjå, herlegdomen åt Israels Gud kom austan-ifrå, og ljomen av honom var som ljomen av store vatn, og jordi skein av herlegdomen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Og den syni som eg såg, var likeins som den syni eg hadde set då eg kom og skulde leggja byen i øyde, og som den syni eg hadde set burtmed Kebarelvi, soleis var synerne. Og eg fall å gruve på mitt andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Og Herrens herlegdom for inn i huset gjenom den porten som snudde i aust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Og anden lyfte meg upp og førde meg inn i den indre fyregarden. Og sjå, Herrens herlegdom fyllte huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Og eg høyrde einkvan tala til meg utor huset, og ein mann stod attmed meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Og han sagde med meg: «Menneskjeson! Dette er den staden der kongsstolen min og fotskammelen min skal standa, og der eg vil bu hjå Israels-borni æveleg. Og Israels-borni skal aldri meir vanhelga mitt heilage namn, korkje dei eller kongarne deira, med hordomen sin og med liki av kongarne sine og med offerhaugarne sine -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'dei som sette dørstokken sin attmed dørstokk min og dørskierne sine attmed dørskierne mine, so det berre var veggen millom meg og deim. Og på den måten gjorde dei mitt heilage namn ureint med styggedomen sin som dei for med, so eg laut tyna deim i min vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'No skal dei hava sin hordom og liki av kongarne sine langt burt ifrå meg, so eg vil bu hjå deim æveleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Du menneskjeson! Kunngjer for Israels-lyden um dette huset, so dei må blygjast for misgjerningarne sine, og mæla den vel tilmåta bygnaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Og når dei blygjest for alt det dei hev gjort, so skal du kunngjera for deim skapnaden på huset og skipnaden i det: utgangar og inngangar og skapnader på alt og alle fyresegnerne um alt, ja, all skapnaden og alle loverne um det; og rit det av framfor deira augo, so dei kann koma i hug heile skapnaden på huset og fyresegnerne um det, og gjera etter deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Dette er lovi um huset: På toppen av fjellet skal heile umkverven kringum det vera høgheilag. Sjå, dette er lovi um huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Og dette er måli på altaret i alnetal, kvar aln ei handbreidd lengre enn ei vanleg aln: det skal vera eit fotstykke, ei aln høgt og ei aln breidt, og kantlisti på kanten av det ei spann breid rundt ikring. Dette er underlaget åt altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Og frå fotstykket på jordi uppåt den nedste skori skal det vera tvo alner, og breiddi skal vera ei aln, og frå den litle skori uppåt den store skori skal det vera fire alner, og breiddi skal vera ei aln.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Og «Guds-fjellet» skal vera fire alner, og frå «Guds-åren» skal dei fire horni stinga upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Og Guds-åren skal vera tolv alner lang og tolv alner breid, firkanta med fire jamlange sidor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Og skori skal vera fjortan alner lang og fjortan alner breid, med fire jamlange sidor, og kantlisti kringum henne ei halv aln tjukk, og fotstykket ei aln rundt ikring, og tropperne skal snu i aust.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Og han sagde med meg: «Menneskjeson! So segjer Herren, Herren: Dette er fyresegnerne um altaret den dagen det vert gjort, so ein kann ofra brennoffer og skvetta blod på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Du skal gjeva dei levitiske prestarne, dei som er av Sadoks-ætti, og som stig nær meg og tener meg, segjer Herren, Herren, ein ungukse til syndoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Og du skal taka noko av blodet hans og strjuka på dei fire altarhorni og på dei fire skorhyrno og på kantlisti rundt ikring; soleis skal du reinsa det frå synd og gjera soning for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Og du skal taka syndofferuksen, og honom skal dei brenna på mynstringsplassen åt huset, utanfor heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Og andre dagen skal du ofra ein lytelaus bukk til syndoffer, og dei skal reinsa altaret frå synd likeins som dei reinsa det med uksen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Når du då hev gjort frå deg reinsingi, skal du leida fram ein lytelaus ungukse og ein lytelaus ver or saueflokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Du skal leida deim fram for Herrens åsyn, og prestarne skal strå salt på deim og ofra deim til brennoffer åt Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'I sju dagar skal du ofra ein bukk til syndoffer kvar dag; og ein ungukse og ein ver or saueflokken, båe lytelause, skal du ofra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'I sju dagar skal dei gjera soning for altaret og reinsa det og vigja det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Og når dei hev fullenda dei dagarne, skal prestarne åttande dagen og fremetter ofra brennofferet dykkar og takkofferi dykkar på altaret, og eg vil hava hugnad i dykk, segjer Herren, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'So let han meg koma tilbake til den ytre porten åt heilagdomen, den som snudde i aust, og han var attlaten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Og Herren sagde med meg: «Denne porten skal vera attlaten og ikkje verta opna, og ingen skal ganga inn igjenom honom; for Herren, Israels Gud, hev gjenge inn igjenom honom, difor skal han vera attlaten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Men fyrsten, han er fyrste, han kann sitja der og eta brød framfor Herrens åsyn. Han skal ganga inn vegen til forhalli i porten, og same vegen skal han ganga ut att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'So let han meg koma gjenom nordporten og fram for huset. Og eg såg, og sjå, Herrens herlegdom fyllte Herrens hus. Og eg fall å gruve på mitt andlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Då sagde Herren med meg: «Menneskjeson! Legg deg på hjarta og sjå med augo dine og lyd etter med øyro dine alt det som eg segjer med deg um alle fyresegnerne og loverne um Herrens hus. Og du må hugfesta inngangen til huset og alle utgangarne frå heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Og du skal segja med dei tråssuge, med Israels-lyden: So segjer Herren, Herren: No lyt det vera nok med all styggedomen dykkar, du Israels-lyd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'at de let framande, u-umskore på hjarta og u-umskore på kjøt koma inn i heilagdomen min, og vera der til å vanhelga huset mitt, når de ofra brødet mitt, feita og blod. Soleis braut dei pakti mi, attåt alle hine styggjorne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Og de hev ikkje sjølve greidt med tenesta i heilagdomarne mine, men de sette andre i staden for dykk til å gjera tenesta i heilagdomen min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'So segjer Herren, Herren: Ingen framand med u-umskore hjarta og u-umskore kjøt skal koma inn i min heilagdom, ingen av alle dei framande som bur millom Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Men dei levitarne som gjekk burt ifrå meg, då Israel for vilt, og villa seg burt ifrå meg etter dei ufysne avgudarne sine, skal bera si misgjerning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'og i heilagdomen min skal dei gjera vakttenesta ved portarne og likeins tenesta i huset; dei skal slagta brennofferet og slagtofferet åt folket, og dei skal standa framfor deira åsyn og tena deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Etter di dei tente deim framfor dei ufysne avgudarne deira og var støytestein til misgjerning for Israels-lyden, difor hev eg lyft mi hand imot deim, segjer Herren, Herren, og dei skal bera si misgjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Og dei skal ikkje koma meg nær til å gjera prestetenesta framfyre meg og ikkje koma nær noko av alle mine heilage ting, dei høgheilage tingi; men dei skal bera skammi si og skjemdarverki som dei hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Og eg vil setja deim til å greida med tenesta i huset, med alt tenar-arbeidet i det og alt som der er å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Men dei levitiske prestarne, Sadoks-sønerne, som greidde med tenesta i heilagdomen min då Israels-borni villa seg burt ifrå meg, dei skal koma nær til meg og tena meg, og dei skal standa framfor mi åsyn og ofra åt meg feita og blod, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Dei skal ganga inn i min heilagdom, og dei skal koma inn åt mitt bord og tena meg, og dei skal greida med mi tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Når dei då kjem inn i portarne åt den indre fyregarden, skal dei klæda seg i linklæde, det må ikkje koma ullan på deim når dei tener i portarne åt den indre fyregarden og inni huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Linhuvor skal dei hava på hovudet og linbrøker um mjødmarne sine; dei skal vera umgyrde med noko som veld sveite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Og når dei gjeng ut i den ytre fyregarden, til folket i den ytre fyregarden, skal dei hava av seg dei klædi som dei hev gjort tenesta i, og leggja deim i dei heilage kovarne, og dei skal taka på seg andre klæde, so dei ikkje skal helga folket med klædi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Og dei skal ikkje raka hovudet, men ikkje heller lata håret veksa som det vil; dei skal klyppa håret sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Og vin skal ingen av prestarne drikka, når dei gjeng inn i den indre fyregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Enkja eller fråskild kvinna skal dei ikkje taka til kona, men møyar, ætta frå Israels-lyden. Men ei enkja som er enkja etter prest, kann det taka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Og dei skal læra folket mitt å skilja millom heilagt og vanheilagt, og kunngjera deim skilnaden på ureint og reint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Og i rettssaker skal dei standa fram og døma; etter mine fyresegner skal dei døma i deim. Og mine lover og fyresegner skal dei halda på alle mine høgtider, og kviledagarne mine skal dei halda heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Og til eit lik skal ingen av deim ganga inn, so han vert urein; einast for far og for mor og for son og for dotter, for bror, og for syster som ikkje hev havt mann, kann dei gjera seg ureine soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Og etter reinsingi hans, skal dei telja sju dagar for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Og den dagen han gjeng inn i heilagdomen, i den indre fyregarden, og tener i heilagdomen, skal han ofra syndofferet sitt, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Og det skal vera arvluten deira: Eg vil vera arvluten deira. Og nokor eiga skal de ikkje gjeva deim i Israel; eg er deira eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Grjonofferet og syndofferet og skuldofferet, deim skal dei eta, og alt som er bannlyst i Israel, skal høyra deim til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Det aller fyrste av allslags grøda og alle offergåvor av alle slag skal vera åt prestarne. Og det fyrste gropet de mel, skal de gjeva presten, so velsigning må koma yver huset ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Noko sjølvdaudt eller ihelrive av fugl eller fe må ikkje prestarne eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Og når de lutar ut landet til odel, so skal de gjeva ei gåva åt Herren, ein heilag-lut av landet, fem og tjuge tusund på lengdi og ti tusund på breiddi. Det skal vera heilagt i all si vidd rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Av dette skal det vera åt heilagdomen fem hundrad på lengd og fem hundrad på breidd, i ein firkant rundt ikring. Og til utmark rundt kringum det femti alner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Soleis skal du etter dette målet mæla fem og tjuge tusund på lengdi og ti tusund på breiddi, og i det skal heilagdomen, det høgheilage, vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Det er ein heilag-lut av landet. Han skal vera åt prestarne som gjer tenesta i heilagdomen, dei som fær koma nær til Herren og tena honom. Det skal vera til hustufter åt deim og til heilag-tufter åt heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Og fem og tjuge tusund på lengdi og ti tusund på breiddi skal vera åt levitarne, tenarane i huset. Til eiga skal dei hava tjuge gardar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Og til eiga åt byen skal de gjeva fem tusund på breiddi og fem og tjuge tusund på lengdi, jamsides med luten åt heilagdomen; det skal vera åt Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Og fyrsten skal hava sin lut på båe sidorne åt heilagdoms-luten og by-eigedomen, frammed heilagdoms-luten og by-eigedomen, på vestsida vestetter, og på austsida, austetter, og han skal vera jamlang med ein arvlut åt ei ætt, frå grensa åt havet til austgrensa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Dette skal han hava til land, til eiga i Israel. Og fyrstarne mine skal aldri meir tyngja folket mitt, men lata Israels-lyden hava landet som det vert etla åt ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'So segjer Herren, Herren: No lyt det vera nok, de fyrstar i Israel! Få burt vald og trælking, og gjer rett og rettferd! Haldt upp med å driva folket mitt frå gard og grunn! segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Rett vegt og rett efa og rett bat skal de hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Ein efa og ein bat skal vera like store, so ein bat er tiandeparten av ein homer og ein efa tiandeparten av ein homer; etter homeren skal deira mål vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Ein sekel skal vera tjuge gera. Tjuge seklar, fem og tjuge seklar, femtan seklar, det skal vera ei mina hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Dette er den reida de skal gjeva: setteparten av ein efa av kvar homer kveite, og likeins skal de gjeva setteparten av ein efa av kvar homer bygg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Og den visse reida av olje, rekna i bat: tiandeparten av ein bat av kvar kor - som er ti bat eller ein homer, for ein homer er ti bat -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'og av småfeet eitt lamb av tvo hundrad frå det vatsrike beitelandet i Israel til grjonoffer og til brennoffer og takkoffer, til å gjera soning for deim, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'All landslyden skal vera skuldig til denne reida åt fyrsten i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Men fyrsten skal hava den skyldnaden: å leggja til brennofferi og grjonofferet og drykkofferet i helgarne og på nymånedagarne og på kviledagarne, på alle høgtiderne hjå Israels-lyden. Han skal greida med syndofferet og grjonofferet og takkofferi til å gjera soning for Israels-lyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'So segjer Herren, Herren: Den fyrste dagen i fyrste månaden skal du taka ein lytelaus ungukse og reinsa heilagdomen frå synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Og presten skal taka noko av syndofferblodet og strjuka på dørskierne i huset og på dei fire hyrno på altarskori og på dørskierne i porten åt den indre fyregarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Og likeins skal du gjera den sjuande dagen i månaden for den som hev synda uviljande eller av fåkunna. Og de skal gjera soning for huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Den fjortande dagen i fyrste månaden skal de halda påskehelg. I høgtidi, i sju dagar, skal de eta usyrt brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Den same dagen skal fyrsten ofra ein ukse til syndoffer for seg og for all landslyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Og dei sju høgtidsdagarne skal han ofra åt Herren eit brennoffer: sju lytelause uksar og sju lytelause verar kvar dag i dei sju dagarne, og til syndoffer ein bukk kvar dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Og til grjonoffer skal han ofra ein efa med kvar ukse og ein efa med kvar ver og ein åttung olje med kvar efa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Den femtande dagen i sjuande månaden, på høgtidi, skal han gjera likeins både syndofferet og med brennofferet og med grjonofferet og oljen i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'So segjer Herren, Herren: Porten åt den indre fyregarden, den som snur i aust, skal vera attlaten dei seks vyrkedagarne, men kviledagen skal han vera open, og nymånedagen skal han vera open.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Og fyrsten skal ganga inn vegen til port-forhalli utanfrå og stana attmed port-dørskii. Og prestarne skal ofra brennofferet hans og takkofferi hans, og han skal tilbeda på portdørstokken og sidan ganga ut att. Men porten skal ikkje stengjast fyrr det kveldar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Og um kviledagarne og nymånarne skal landslyden tilbeda attmed inngangen til den same porten for Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Og brennofferet som fyrsten skal føra fram for Herren på kviledagen, skal vera seks lytelause lamb og ein lytelaus ver,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'og til grjonoffer ein efa med veren, men med lambi slikt grjonoffer som han sjølv vil gjeva, og ein åttung olje med kvar efa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Og um nymånedagen ein lytelaus ungukse og seks lamb og ein ver; lytelause skal dei vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Og til grjonoffer skal han ofra ein efa med uksen og ein efa med veren, men med lambi so mykje som han hev råd til, og ein åttung olje med kvar efa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Og når fyrsten gjeng inn, skal han ganga inn vegen til port-forhalli, og same vegen skal han ganga ut att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Og når landslyden gjeng inn for Herrens åsyn på høgtiderne, då skal den som gjeng inn gjenom nordporten og skal tilbeda, ganga ut att gjenom sudporten, og den som gjeng inn gjenom sudporten, skal ganga ut gjenom nordporten; ingen skal snu og ganga ut att gjenom den porten han kom inn, men dei skal ganga ut beint fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Og fyrsten skal ganga inn midt ibland deim når dei gjeng inn, og når dei gjeng ut, skal dei ganga ut saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Og i helgarne og høgtiderne skal grjonofferet vera ein efa med kvar ukse og ein efa med kvar ver, men med lambi slikt som kvar sjølv vil gjeva, og ein åttung olje med kvar efa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Og når fyrsten vil ofra eit friviljugt offer, anten brennoffer eller takkoffer til friviljugt offer åt Herren, då skal dei lata upp åt honom den porten som snur i aust, og han skal ofra brennofferet sitt og takkofferi sine like eins som han gjer på kviledagen. So skal han ganga ut att, og ein skal lata att porten etter han er utgjengen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Og eit årsgamalt lytelaust lamb skal du dagstødt ofra til brennoffer åt Herren; kvar morgon skal du ofra det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Og til grjonoffer skal du kvar morgon ofra setteparten av ein efa og tvo pottar olje til å lata uppi mjølet. Det er eit grjonoffer åt Herren - ævelege fyresegner, stødt og stendig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Og dei skal ofra lambet og grjonofferet og oljen kvar morgon til eit stendigt brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'So segjer Herren, Israels Gud: Um fyrsten gjev einkvan av sønerne sine noko av odelen sin til gåva, so vert det hans odelen; åt sønerne hans skal det vera, dei fær det til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Men gjev han einkvan av tenarane sine noko av odelen sin til gåva, då skal det vera hans til fridomsåret, men då skal fyrsten få det att. Odelen hans er det, åt sønerne hans skal det vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Og fyrsten må ikkje taka odelsjord frå folket og på den måten trengja deim burt frå deira eiga - av si eigi eiga skal han lata sønerne sine erva - so ikkje folket mitt vert spreidt, kvar burt frå si eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'So let han meg koma gjenom den inngangen som var attmed porten, til dei heilage kovarne som var etla prestarne, og som snudde i nord. Og sjå, der var det eit rom lengst burte mot vest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Og han sagde med meg: «Dette er den staden der prestarne skal koka skuldofferet og syndofferet, og der dei skal baka grjonofferet, so dei ikkje skal turva bera det ut i den ytre fyregarden og på den måten helga lyden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'So let han meg stiga ut i den ytre fyregarden og let meg ganga kringum dei fire hyrno på fyregarden. Og sjå, i kvart hyrna på fyregarden var det eit tun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'I dei fire hyrno på fyregarden var dei inngjerde, desse tuni; fyrti alner lange og tretti alner breide, desse fire tuni i hyrno hadde same målet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Og det gjekk ein murgard rundt ikring inni deim, rundt ikring i alle fire. So var det gjort gruvor til å koka i nedantil med murgarden rundt ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Og han sagde med meg: «Dette er kokehusi der tenarane i huset skal koka slagtofferi åt folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'So let han meg tilbake til inngangen åt huset. Og sjå, det kom vatn ut under dørstokken på huset mot aust, for framsida på huset snudde i aust. Og vatnet rann ned frå høgre sida på huset sunnanfor altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Sidan let han meg ganga ut gjenom nordporten og fylgde meg ikring utanfor til ytreporten, den porten som snur austetter. Og sjå, det kom vatn vellande fram undan høgresida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Mannen gjekk no austetter med mælesnor i handi og mælte tusund alner. Og han hadde meg til å vada yver vatnet, vatn til okleleden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'So mælte han endå tusund alner til og hadde meg til å vada yver vatnet, vatn til knes. So mælte han endå tusund alner og hadde meg til å vada yver vatnet; det gjekk då upp til lenderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'So mælte han endå tusund alner, og no var det ei å som eg ikkje kunde vada. For vatnet hadde vakse, vatn til å symja i, ei å som ikkje let seg vada.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Og han sagde med meg: «Hev du set det, menneskjeson?» Og han let meg ganga tilbake uppå å-breiddi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Då eg kom dit att, stod det på å-breiddi ei mengd med tre på den sida og hi sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Og han sagde med meg: «Dette vatnet renn ut til austbygderne og fløymar ned i øydemarki. So fell det ut i havet. Når det er flødt ut i havet, vert vatnet der friskt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Og det skal henda at alt kvikjende som liver og yr alle stader der den tviflaumande åi renn, skal livna, og det skal verta ei ovmengd med fisk. For når dette vatnet kjem dit, so vert det helsebot og liv alle stader der åi renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Og det skal henda at fiskarar skal standa frammed vatnet frå En-Gedi til En-Eglajim; fiskestøde for garnbruk skal det og vera. Fisken der skal vera i ovende mengd, kvar etter sitt slag, som i Storhavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Men myrarne og deplarne der skal ikkje verta friske; dei er etla åt saltet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Og frammed åi, på båe å-breidderne, skal det veksa upp frukttre av alle slag. Lauvet på deim skal ikkje visna og frukti ikkje trjota. Kvar månad skal dei bera ny frukt, for vatnet åt deim renn ut frå heilagdomen. Og frukti på deim skal vera til mat, og lauvet til lækjedom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'So segjer Herren, Herren: Dette er landskilet, og innan det skal de taka dykk landet til odel etter Israels tolv ætter. Åt Josef skal det vera tvo luter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Og de skal taka det til odel, den eine som den andre, for di eg hev rett upp handi mi på at eg vilde gjeva federne dykkar det; so skal då dette landet verta utskift til odel og eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Dette er då landskilet: På nordsida: frå Storhavet langs med Hetlonvegen til ein kjem til Sedad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamat, Berota, Sibrajim, som ligg millom Damaskus-skilet og Hamat-skilet, det millomste Haser, som ligg innmed Havran-skilet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Soleis er då landskilet frå havet til Hasar-Enon attmed Damaskus-skilet og framleides endå lenger nordetter upp til Hamat-skilet. Dette er nordsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Austsida - millom Havran og Damaskus og millom Gilead og Israelsland - er Jordan: frå nordskilet til Austhavet skal de mæla. Dette er austsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'På sudsida, mot sud; frå Tamar til Meribotvatnet attmed Kades, til bekken, alt til Storhavet. Dette er sudsida, mot sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'På vestsida er Storhavet frå dette skilet til dit der ein gjeng til Hamat. Dette er vestsida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Og de skal byta landet millom dykk etter Israels ætter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Og soleis skal det vera: De skal skifta det ut til odel åt dykk sjølve og dei framande som bur hjå dykk og hev fenge born ibland dykk. Og dei skal vera for dykk som dei som er fødde og borne i sjølve Israel; odelsjord skal dei hava med dykk ibland ætterne i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Og so skal det vera: I den ætti der den framande bur, der skal de gjeva honom odelsjordi si, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Og dette er namni på ætterne: Frå nordenden - vest ved Storhavet - langs med Hetlonvegen til dit som ein gjeng til Hamat, Hasar-Enan attmed Damaskus-skilet, der skal dei eiga frå austsida til havet: Dan, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Frammed Dan-skilet, frå austsida til vestsida: Asser, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Frammed Asser-skilet, frå austsida til vestsida: Naftali, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Frammed Naftali-skilet, frå austsida til vestsida: Manasse, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Frammed Manasse-skilet, frå austsida til vestsida: Efraim, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Frammed Efraim-skilet, frå austsida til vestsida: Ruben, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Frammed Ruben-skilet, frå austsida til vestsida: Juda, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Frammed Juda-skilet, frå austsida til vestsida, skal vera den gåva som de skal gjeva, fem og tjuge tusund breid og so langt som ein av luterne åt ætterne frå austsida til vestsida, og midt der inni skal heilagdomen vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Den gåva som de skal gjeva Herren, skal vera fem og tjuge tusund lang og ti tusund breid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Og åt desse skal den heilage gåva vera: Åt prestarne: i nord fem og tjuge tusund og i vest ti tusund på breiddi, og i aust ti tusund på breiddi, og i sud fem og tjuge tusund på lengdi. Og midt der inni skal Herrens heilagdom vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Åt prestarne som er helga utav Sadoks-sønerne, dei som tok vare på tenesta mi og ikkje for vilt då Israels-borni villa seg burt, soleis som levitarne villa seg burt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'åt deim skal gåva vera utav jordgåva, eit høgheilagt stykke frammed skilet mot levitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Og levitarne skal hava, frammed skilet mot prestarne, fem og tjuge tusund på lengdi og ti tusund på breiddi; all lengdi skal vera fem og tjuge tusund og breiddi ti tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Og dei skal ikkje selja noko av det, og ikkje skal noko bytast burt, og landsens fyrstegrøda må ikkje ganga yver i annan manns eiga, for ho er vigd Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Og dei fem tusund som er att av breiddi, frammed dei fem og tjuge tusund, skal vera uvigd, åt byen, til bustader og til utmark, og byen skal liggja der i midten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Dette er då målet på honom, nordsida fire tusund og fem hundrad og sudsida fire tusund og fem hundrad, austsida fire tusund og fem hundrad, og vestsida fire tusund og fem hundrad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Og det skal vera utmark åt byen: nordetter tvo hundrad og femti, og sudetter tvo hundrad og femti, og austetter tvo hundrad og femti, og vestetter tvo hundrad og femti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Og det som vert att på lengdi frammed den heilage gåva: ti tusund austetter og ti tusund vestetter - for det skal vera frammed den heilage gåva - grøda av det skal vera til brød åt arbeidsfolket i byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Og arbeidsfolket i byen, av alle ætterne i Israel, dei skal bruka det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Heile gåva skal vera fem og tjuge tusund på lengdi og fem og tjuge tusund på breiddi; som ein firkant skal de gjeva den heilage gåva med by-eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Og det som vert att, skal vera åt fyrsten, på båe sidorne av den heilage gåva og by-eiga, frammed luten på fem og tjuge tusund, alt burtåt austskilet og vestetter frammed dei fem og tjuge tusund, alt burtåt vestskilet jamsides med luterne åt ætterne; det skal vera åt fyrsten. Og den heilage gåva og husens heilagdom skal liggja midt imillom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Det som då ligg millom Juda-skilet og Benjamin-skilet - med levit-eiga og by-eiga i midten - det skal vera åt fyrsten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'So kjem hine ætterne: Frå austsida til vestsida: Benjamin, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Og frammed Benjamin-skilet, frå austsida til vestsida: Simeon, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Og frammed Simeon-skilet, frå austsida til vestsida: Issakar, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Frammed Issakar-skilet, frå austsida til vestsida: Sebulon, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Frammed Sebulon-skilet, frå austsida til vestsida: Gad, ein lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Frammed Gad-skilet, på sudsida, i sud: der skal skilet ganga frå Tamar, yver Meribavatni attmed Kades, til bekken, alt burtåt Storhavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Dette er det landet som de skal skifta ut av odelen åt ætterne i Israel, og dette er luterne deira, segjer Herren, Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Og dette er utgrensa åt byen: På nordsida fire tusund og fem hundrad på mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Og byportarne, uppkalla etter ætterne i Israel: Tri portar i nord: Ruben-porten, ein; Juda-porten, ein; Levi-porten, ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Og på austsida: fire tusund og fem hundrad, og tri portar: Josef-porten, ein; Benjamin-porten, ein; Dan-porten, ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Og sudsida: fire tusund og fem hundrad på mål, og tri portar: Simeon-porten, ein; Issakar-porten ein; Sebulon-porten, ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Vestsida: fire tusund og fem hundrad; dei tri portarne der: Gad-porten, ein; Asser-porten, ein; Naftali-porten, ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Rundt ikring: attan tusund. Og namnet på byen skal vera frå den dagen: «Herren er der».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'I det tridje styringsåret åt Jojakim, kongen i Juda, kom Nebukadnessar, kongen i Babel, til Jerusalem og kringsette byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Og Herren gav Juda-kongen Jojakim i hans vald, og likeins sume av kjeraldi i Guds hus; han førde deim til Sinearlandet, til gudshuset sitt. Og kjeraldi flutte han inn i skattkammeret åt guden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Og kongen baud Aspenaz, den øvste hirdmannen sin, at han av Israel skulde velja ut nokre sveinar, av kongsætt og av adelsætt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'sveinar som var lytelause og fagre å sjå til og vituge til å leggja seg etter alt slags visdom, evnerike og lærehuga ungsveinar, som kunde verta føre til å tena i kongsgarden; og han skulde gjeva deim upplæring i kaldæisk skrift og tungemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Kongen etla til åt deim det dei skulde hava kvar dag av forkunnmaten åt kongen og av vinen som han drakk, og baud at dei skulde fostra deim upp i tri år; når den tidi var lidi, skulde dei få gjera tenesta hjå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Millom deim var Daniel, Hananja, Misael og Azarja av Juda-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Men den øvste hirdmannen gav deim nye namn: Daniel kalla han Beltsassar, Hananja Sadrak, Misael Mesak og Azarja Abed-Nego.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Men Daniel sette seg fyre at han ikkje vilde gjera seg urein med kongsmaten, eller med den vinen som han drakk; og han bad den øvste hirdmannen um å sleppa å gjera seg urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Og Gud let Daniel finna nåde og miskunn hjå den øvste hirdmannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Men den øvste hirdmannen sagde til Daniel: «Eg ottast at herren min, kongen, som hev teke avgjerd um maten og drykken dykkar, skal tykkja at de er meir skrinnleitte enn dei andre sveinarne på dykkar alder, og so kjem de til å føra skuld yver hovudet mitt hjå kongen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Då sagde Daniel til hovmeisteren som den øvste hirdmannen hadde sett yver Daniel, Hananja, Misael og Azarja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '«Gjer ein freistnad med tenarane dine i ti dagar, og gjev oss grønt å eta og vatn å drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'So kann du sidan likna vår utsjånad i hop med utsjånaden på dei som et av kongsmaten; og so kann du gjera med tenarane dine etter det du då ser.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Han laga seg etter deim i dette og gjorde ein freistnad med deim i ti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Då dei ti dagarne var lidne røyndest det at dei var fagrare å sjå til og betre i hold enn alle dei sveinar som hadde ete av kongsmaten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Då let hovmeisteren deim sleppa den maten som kongen hadde etla åt deim, og den vinen som dei skulde ha drukke, og gav deim grønt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Til desse fire sveinarne gav no Gud kunnskap og vit på alt slag skrift og visdom; og Daniel skyna seg på alle syner og draumar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Og då den tidi kom då kongen hadde bode at dei skulde førast fram for honom, førde den øvste hirdmannen deim fram for Nebukadnessar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Og då kongen tala med deim, fanst det ingen millom deim alle som kunde mæla seg med Daniel, Hananja, Misael og Azarja; so vart dei då tenarar hjå kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Og stødt når kongen spurde deim til i ei sak som det skulde visdom til å skyna seg på, fann han at dei var ti gonger visare enn alle runemeistrar og manarar som fanst i heile hans rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Og Daniel heldt fram soleis til det fyrste styringsåret åt kong Kyrus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'I det andre styringsåret åt Nebukadnessar hadde Nebukadnessar draumar som sette uro i hugen hans, so han ikkje fekk sova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Då let kongen senda bod etter runemeistrarne og manararne og trollmennerne og kaldæarane, og vilde at dei skulde fortelja kongen kva han hadde drøymt. Og dei kom og gjekk fram for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Og kongen sagde til deim: «Eg hev havt ein draum, og hev slik uro i hugen etter å få vita kva eg hev drøymt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Då tala kaldæarane til kongen på aramæisk: «Kongen live æveleg! Fortel tenarane dine draumen, so skal me segja deg kva han tyder.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Kongen svara kaldæarane: «Nei, min vilje stend uruggeleg fast, at dersom de ikkje segjer meg draumen og uttydingi på honom, so skal de verta hoggne i sund, og husi dykkar gjorde til sorphaugar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Men dersom de fortel meg draumen og uttydingi på honom, so skal de få rike gåvor og stor æra av meg. Seg meg difor draumen og uttydingi på honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Dei svara og sagde andre gongen: «Kongen må fortelja draumen til tenarane sine, so skal me segja kva han tyder.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Kongen svara og sagde: «Eg merkar grant at de vil vinna tid, sidan de ser at min vilje er uruggeleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Dersom de ikkje segjer meg draumen, kann domen yver dykk ikkje verta anna enn ein. Ja, de er vorte samde um å fara med lygn og skjemdarsvall for meg, i von um at tiderne skal snu seg. Seg meg no difor kva eg hev drøymt, so skynar eg at de og kann uttydingi på det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Då svara kaldæarane kongen og sagde: «Det finst ikkje eit menneskje på jordi som kann segja kongen det som han vil vita; aldri hev då heller nokon konge, kor stor og megtig han so hev vore, kravt noko slikt av nokon runemeister eller manar eller kaldæar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'For det som kongen krev, er so altfor vandt, og det finst ingen som kann fortelja kongen det, utan gudarne, og dei bur ikkje millom døyelege menneskje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Då vreidest kongen og harmast mykje, og baud at dei skulde tyna alle dei vise i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Då so påbodet var utferda, og dei skulde drepa dei vise, leita dei og etter Daniel og fosterbrørne hans og vilde drepa deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Daniel vende seg då med kloke og vituge ord til Arjok, hovdingen yver livvakti åt kongen, som hadde drege ut og skulde drepa dei vise i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Han tok til ords og spurde Arjok, hovudsmannen åt kongen: «Kvi hev kongen ferda ut dette strenge påbodet?» Då fortalde Arjok Daniel kva som var tids.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Og Daniel gjekk inn og bad kongen gjeva honom frest, so skulde han kunngjera kongen uttydingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Sidan gjekk Daniel heim og fortalde Hananja, Misael og Azarja, fosterbrørne sine, kva som var tids,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'og han baud deim at dei skulde beda Gud i himmelen um miskunn, so at denne løyndomen måtte verta openberra, so ikkje Daniel og fosterbrørne hans skulde lata livet tilliks med dei andre vise i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Då fekk Daniel vita løyndomen i ei syn um natti. Og Daniel lova Gud i himmelen for dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel tok til ords og sagde: «Lova vere Guds namn frå æva og til æva! For visdom og magt høyrer honom til!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Han let tider og stunder verta umskifte, set kongar av og set kongar inn, han gjev dei vise visdom og dei vituge vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Han openberrar det djupe og det dulde, han veit kva som i myrkret er, og hjå han bur ljoset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Deg, min fedregud, takkar og prisar eg for di du hev gjeve meg visdom og dugleik, og no hev kunngjort meg det me bad deg um. For det som kongen vilde vita, hev du kunngjort oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Daniel gjekk so inn til Arjok, som av kongen hadde fenge påbod um å drepa dei vise i Babel; han gjekk av stad og sagde soleis til honom: «Dei vise i Babel må du ikkje tyna. Før meg inn til kongen, so skal eg kunngjera kongen uttydingi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Då skunda Arjok seg og førde Daniel inn til kongen og sagde soleis til honom: Eg hev funne ein mann millom dei jødiske fangarne som kann segja kongen uttydingi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Kongen svara og sagde til Daniel, som hadde fenge namnet Beltsassar: «Kann du segja meg den draumen eg hev havt, og uttydingi på honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel svara kongen og sagde: «Den løyndomen som kongen hev hug til å vita, er det ingen vismann eller manar eller runemeister eller stjernetydar som kann kunngjera for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Men det er ein Gud i himmelen, som openberrar løyndomar, og han hev late kong Nebukadnessar vita kva som skal henda i dagar som kjem. Dette var draumen din og den syni du hadde på lægjet ditt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Då du, konge, låg på lægjet ditt, steig det tankar upp hjå deg um kva som skal henda i framtidi. Og han som openberrar løyndomar, let deg vita kva som skal henda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Og for meg hev denne løyndomen vorte openberra, ikkje av di eg eig nokon visdom framfor alle andre som liver, men for at uttydingi kann verta kunngjord for kongen, so du kann få vita ditt hjartans tankar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du, konge, såg i syni di ei stor bilætstytte standa framfyre deg, og den stytta var høg, og glansen hennar var overlag stor, ho var skræmeleg å sjå til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Hovudet på bilætet var av skirt gull, brjostet og armarne av sylv, buken og lenderne av kopar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'leggjerne av jarn, føterne var noko av jarn og noko av leir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Medan du stod og såg på bilætet, vart det lausrive ein stein, men ikkje med mannehender, og den steinen råka bilætet på føterne, som var av jarn og leire, og krasa deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Då vart det krasa alt på ein gong, jarnet, leiret, koparen, sylvet og gullet, og det vart som agner på ein treskjarvoll um sumaren, og vinden føykte det burt, so ein ingen stad kunna finna det att. Men av steinen som hadde råka bilætet, vart det eit stort fjell, som fylde upp heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Dette var draumen, og no vil me segja kongen uttydingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du, konge, kongen yver kongarne, som Gud i himmelen hev gjeve rike, velde, magt og æra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'du, som hev gjeve mannsborni, dyri på marki og fuglarne under himmelen i henderne på, so langt som liv bur, og som han hev sett til herre yver det alt saman, du er dette gullhovudet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Men etter deg skal det koma upp eit anna rike, ringare enn ditt, og etter det endå eit rike, det tridje, som er av kopar, og det skal råda yver heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Det fjorde riket skal og koma upp og vera sterkt som jarn; for jarnet knusar og krasar alt, og som jarnet øyder alt anna, so skal og dette riket krasa og øyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Men når du såg at føterne og tærne var noko av krusmakarleir og noko av jarn, so tyder det at det skal vera eit sundra rike: det skal hava noko av det faste jarnet, for du såg det var jarn blanda med leira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Og det at tærne på føterne var noko av jarn og noko av leir, det tyder at riket i sume måtar skal vera sterkt, i andre måtar veikt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Og at du såg jarnet var blanda med leir, det tyder at det fulle skal verta ei blanding ved menneskjesæde, men at luterne like vel ikkje skal halda i hop med kvarandre, like lite som jarn kann binda seg saman med leir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Men i dei dagarne dei kongarne liver, skal Gud i himmelen reisa eit rike som aldri i æva skal øydast, og magti yver det skal ikkje latast til noko anna folk. Det skal krasa og gjera ein ende på alle hine riki; men sjølv skal det æveleg standa;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'for du såg då at det vart lausrive ein stein or fjellet, men ikkje med mannehender, og krasa jarnet, koparen, leiret, sylvet og gullet. So hev den store Gud openberra for kongen kva som skal henda i framtidi. Draumen er sann og uttydinga sætande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Då kasta kong Nebukadnessar seg å gruve og tilbad framfor Daniel, og han baud at dei skulde ofra grjonoffer og røykjelse til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Og kongen svara Daniel og sagde: «I sanning, dykkar Gud er Gud yver gudar og herre yver kongar og ein som openberrar løynde ting, sidan du hev kunna openberra denne løyndomen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Etter dette gjorde kongen Daniel til ein stor mann, og gav honom mange dyre gåvor og sette honom til herre yver alt Babelsfylket, og til forstandar for alle dei vise i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Og Daniel bad kongen, og han sette Sadrak og Mesak og Abed-Nego til å styra Babelsfylket, men Daniel sjølv stana i kongsgarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Kong Nebukadnessar let gjera eit bilæte av gull, seksti alner høgt og seks alner breidt; det fekk han sett upp på Durasletta i Babelsfylket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Og kong Nebukadnessar sende ut menner som skulde stemna saman satraparne og jarlarne og landshovdingarne og rådsmennerne og skattmeistrarne og dei lovkunnige og domarane og alle andre embætsmenner i fylki, at dei skulde koma til vigsla av det bilætet som kong Nebukadnessar hadde fenge reist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Då samla dei seg, satraparne og jarlarne og landshovdingarne og rådsmennerne og skattmeistrarne og dei lovkunnige og domararne og alle andre embetsmenner i fylki og skulde vigsla det bilætet som Nebukadnessar hadde fenge reist; og då dei so stod framfor det bilætet som Nebukadnessar hadde fenge reist,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'ropa ein herold med høg røyst: «Det vere dykk sagt, de folk og ætter og tungemål:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Når de høyrer ljoden av horn, fløyta, cither, harpa, psalter, sekkjepipa og alle slags andre spel, då skal de falla ned og tilbeda det gull-bilætet som kong Nebukadnessar hev fenge reist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Men den som ikkje fell ned og tilbed, skal i same stundi verta kasta i ein brennande omn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'So snart alt folket no høyrde ljoden av horn, fløyta, cither, harpa, psalter og alle andre slags spel, fall dei difor ned, alle folk og ættar og tungemål, og tilbed det gull-bilætet som kong Nebukadnessar hadde fenge reist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Men straks etter stod nokre kaldæiske menner fram og klaga jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Dei tok til ords og sagde til kong Nebukadnessar: «Kongen live æveleg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Konge, du hev gjeve bod um at alle menneskje skulde falla ned og tilbeda gull-bilætet når dei høyrde ljoden av horn, fløyta, cither, harpa, psalter, sekkjepipa og alle andre spel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'og at kvar og ein som ikkje fell ned og tilbed, skal verta kasta i ein brennande omn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Men no er her nokre jødiske menner, Sadrak, Mesak og Abed-Nego, som du sette til å styra Babelsfylket. Desse mennerne hev ikkje agta på deg, konge. Dei dyrkar ikkje dine gudar, og ikkje tilbed dei gull-bilætet som du hev fenge reist.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Då baud Nebukadnessar i vreide og harm at dei skulde føra fram Sadrak, Mesak og Abed-Nego. Og dei førde mennerne fram for kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebukadnessar tala til deim og sagde: «Er det med vilje at de, Sadrak, Mesak og Abed-Nego, ikkje dyrkar mine gudar og ikkje tilbed det gull-bilætet som eg hev fenge reist?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Ja, ja, alt skal verta godt att, so framt de er viljuge til å falla ned og tilbeda det bilætet som eg hev fenge gjort, når de høyrer ljoden av horn, fløyta, cither, harpa, psalter og sekkjepipa og alle slag andre spel. Men dersom de ikkje tilbed, so skal de i same stundi verta kasta i den brennande omn; og kven er den gud som då kann frelsa dykk or mi hand?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Då svara Sadrak, Mesak og Abed-Nego og sagde til kongen: «Nebukadnessar, me tarv ikkje gjeva deg noko svar på dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Um vår Gud, han som me dyrkar, magtar å frelsa oss, so skal han og frelsa oss or den brennande omnen og or di hand, konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Men um han ikkje det vil, so skal du vita, konge, at me dyrkar ikkje dine gudar kor som er, og at me ikkje vil tilbeda det gull-bilætet som du hev fenge reist.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Då rann det slikt sinne i Nebukadnessar mot Sadrak, Mesak og Abed-Nego, at han skifte liter i andlitet. Og han tok til ords og baud at dei skulde gjera omnen sju gonger so heit som elles var turvande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Og nokre handfaste karar i heren hans fekk fyresegn um å binda Sadrak, Mesak og Abed-Nego og kasta deim i den brennande omnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'So vart mennerne bundne i underklædi, kjolarne, kapporne og dei andre klædi sine og kasta i den brennande omnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Men etter di bodet åt kongen hadde vore so strengt, og omnen difor var vorten so uhorveleg upphita, vart dei mennerne som førde Sadrak, Mesak og Abed-Nego upp dit, sjølv drepne av eldslogarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Men dei tri mennerne, Sadrak, Mesak og Abed-Nego, vart kasta bundne ned i den brennande omnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Då stokk kong Nebukadnessar og stod svint upp og spurde rådsherrarne sine og sagde: «Var det ikkje tri menner me batt og kasta i elden?» Dei svara og sagde til kongen: «Jau visst, konge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Han heldt fram og sagde: «Og endå ser eg no fire menner som gjeng lause og leduge inne i elden, og inkje mein hev dei fenge; og den fjorde ser ut som ein gudeson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Dermed steig Nebukadnessar fram til døri på den brennande omnen, tok til ords og sagde: Sadrak, Mesak og Abed-Nego, de tenarar åt den høgste Gud, kom ut her!» Då gjekk Sadrak, Mesak og Abed-Nego ut or elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Og satraparne og jarlarne og landshovdingarne og rådsherrarne åt kongen samla seg saman der, og fekk sjå at elden ikkje hadde havt nokor magt yver likamen til desse mennerne, og at håret på hovudi deira ikkje var svidt, og at klædi deira ikkje var skadde; ja, ein kunde ikkje ein gong kjenna lukti av noko brent på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Då tok Nebukadnessar til ords og sagde: «Lova vere Gud åt Sadrak, Mesak og Abed-Nego, som sende engelen sin og frelsa tenararne sine, som trøysta seg so fast til honom at dei braut ordi åt kongen og våga livet sitt, so dei ikkje skulde nøydast til å dyrka og tilbeda nokon annan gud enn sin eigen Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'So gjev eg no det bodet at kven det so er av alle folk og ætter og tungemål som segjer noko usømelegt um Sadrak, Mesak og Abed-Negos Gud, han skal hoggast i sund, og huset hans skal gjerast til ein sorphaug; for det finst ingen gud som kann hjelpa so som han.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'So let kongen Sadrak, Mesak og Abed-Nego koma til stor æra og magt i Babelsfylket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Kong Nebukadnessar til alle folk og ætter og tungemål som bur på heile jordi: Heil og sæl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Eg hev funne for godt å kunngjera dei teikn og under som den høgste Gud hev gjort mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Kor store er ikkje teikni hans, og megtige hans under! Riket hans er eit æveleg rike, og veldet hans varer frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Eg, Nebukadnessar, sat i god ro i huset mitt og livde lukkeleg i kongsgarden mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Då hadde eg ein draum som skræmde meg; eg tok fæla av draumsviv i mi seng og av ei syn som eg såg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Difor gav eg ut bod um at dei skulde henta alle dei vise i Babel til meg, so dei kunde segja meg uttydingi på draumen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'So kom då runemeistrarne, manararne, kaldæarane og stjernetydarane, og eg fortalde deim draumen; men dei kunde ikkje segja meg uttydingi på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Til slutt kom Daniel og inn for meg, han som hadde fenge namnet Beltsassar etter namnet på guden min, og som anden åt heilage gudar er i; og eg fortalde honom draumen soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '«Beltsassar, du som er den øvste millom runemeistrarne, um deg veit eg at anden åt heilage gudar er i deg, og at ingen løyndom er for svær for deg; so seg meg kva eg såg i draumen min, og kva det tyder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Dette var den syni eg hadde på lægjet mitt: Eg såg i syni mi eit tre standa midt på jordi, og det treet var ovleg høgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Ja, stort og veldugt var treet, og so høgt at det rakk til himmels og var synlegt alt til enderne av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Det hadde fager lauvklænad, og det bar mykje frukt, so det hadde føde åt alle. Dyri på marki fann skugge under det, og fuglarne under himmelen budde i greinerne på det, og alt kjøt fekk si føda frå det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'So såg eg i den syni som eg hadde på lægjet mitt, korleis ein heilag vaktar steig ned frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Han ropa med høg røyst og sagde: «Hogg ned treet, og skjer greinerne av det, riv lauvklædnaden av, og spreid frukti, so dyri som ligg under det, lyt fara sin veg, og fuglarne flyg burt ifrå greinerne på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Men lat stuven med røterne standa att i jordi, men bunden med lekkjor av jarn og kopar, midt i grøne graslendet; av doggi frå himmelen skal han vætast, og hava sin lut med dyri millom urterne på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Hjarta hans skal skapast um, so det ikkje er eit mannehjarta meir; eit dyrehjarta skal han få, og sju tider skal skrida fram yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'So er det skipa ved rådgjerd av vaktarane, og so hev dei heilage sagt i saki, so mykje dei levande skal sanna at det er den Høgste som råder yver manneriket og gjev det til kven han vil, ja, set den ringaste millom menneskje yver det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Soleis var draumen som eg, kong Nebukadnessar, hadde. Og no må du, Beltsassar, segja kva han tyder; for ingen av dei vise i riket mitt kann segja meg uttydingi; men du kann det vel, for anden åt heilage gudar er i deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Då stod Daniel, han som dei og kalla Beltsassar, ei stund forfærd og full av urolege tankar. Men kongen tok atter til ords og sagde: «Beltsassar, lat ikkje draumen og det som han tyder, skræma deg!» Beltsassar svara og sagde: «Herre min, gjev draumen måtte gjelda deim som hatar deg, og tydingi på honom fiendarne dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Treet du såg, som var so stort og so veldugt, og so høgt at det rakk til himmels og var synlegt yver all jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'og som hadde so fager lauvklædnad, og bar so mykje frukt at det gav føda åt alle, treet som dyri på marki budde under, og som fuglarne under himmelen hadde reiri sine i greinerne på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'det er du sjølv, konge, du som er so stor og veldug; stordomen din hev vakse so han når til himmels, og veldet ditt strekkjer seg til endarne av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Men at kongen såg ein heilag vaktar stiga ned frå himmelen, som sagde: «Hogg ned treet og øydelegg det, men lat stuven med røterne standa att i jordi, bunden med lekkjer av jarn og kopar, midt i grøne graslendet! av doggi frå himmelen skal han vætast, og hava sin lut millom dyri på marki, til dess sju tider hev skride fram yver honom -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'det tyder, konge, og dette er rådgjerdi åt den Høgste som råkar herren min, konge:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Du skal verta utstøytt frå menneski og ljota bu millom dyri på marki og eta gras som uksarne og verta vætt av doggi frå himmelen, og sju tider skal skrida fram yver deg til dess du sannar at det er den Høgste som råder yver mannariket og gjev det til kven han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Men at det vart bode at trestuven og røterne skulde standa att, det tyder at du skal få hava riket ditt, når du hev sannkjent at himmelen hev magti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Difor må du, konge, lata mitt råd tekkjast deg, og gjera deg fri frå synderne dine med di du gjer godt, og frå misgjerningarne dine med di du gjer sælebot mot dei fatige, um lukka di då kann henda kunde verta varande.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Alt dette kom yver kong Nebukadnessar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Tolv månader etter gjekk kongen ein gong ikring på taket av kongsslottet i Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Då tok kongen til ords og sagde: «Sjå, dette er det store Babel, som eg hev bygt til kongssæte med mi velduge magt, min herlegdom til æra!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Fyrr ordet endå var or munnen på kongen, kom det ei røyst frå himmelen: «Deg, kong Nebukadnessar, vere det sagt: Kongedømmet hev vike frå deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'du skal verta utstøytt frå menneski og ljota bu millom dyri på marki og eta gras som uksarne, og sju tider skal skrida fram yver deg, til dess du sannar at den Høgste råder yver manneriket og gjev det til kven han vil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'I same stundi slo dette ordet til på Nebukadnessar; han vart utstøytt frå menneski og laut eta gras som uksarne, og kroppen hans vart vætt av doggi frå himmelen, til dess at håret hans voks og vart som ørnefjører, og til dess neglerne hans vart som fugleklør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Men då tidi var lidi, lyfte eg, Nebukadnessar, augo mine upp til himmelen og fekk vitet mitt att. Då lova eg den Høgste, eg prisa og æra honom som liver æveleg, han som hev eit velde som er eit ævelegt velde, og eit rike som varer frå ætt til ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Alle som på jordi bur, er som inkje å agta imot honom, for han gjer kva han vil, både med himmelheren og med deim som bur på jordi, og ingen kann standa seg imot hans hand eller segja til honom: «Kva gjer du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'So fekk eg då på den tidi vitet mitt att, og eg fekk att min herlegdom og glans, mitt kongedøme til æra, og rådsherrarne og stormennerne mine leita meg upp. Og eg vart innsett i kongedømet mitt att, og endå større magt vart meg gjevi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Difor prisar no eg, Nebukadnessar, og høglovar og ærar kongen i himmelen; for alle hans gjerningar er sanning, og vegarne hans er rette, og han kann bøygja deim ned som ferdast i ovmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Kong Belsassar gjorde eit stort gjestebod for dei tusund stormennerne sine og heldt drykkjelag med dei tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Då dei hadde fenge smak på vinen, baud Belsassar at dei skulde bera fram dei gullkjeraldi og sylvkjeraldi som Nebukadnessar, far hans, hadde teke or templet i Jerusalem; or deim skulde so kongen og stormennerne hans, konorne og fylgjekonorne hans drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Dei bar då fram dei gullkjeraldi som var tekne or templet i Guds hus i Jerusalem; og kongen og stormennerne hans, konorne og fylgjekonorne hans, drakk or deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Dei drakk vin og prisa gudarne sine av gull og sylv, av kopar og jarn og tre og stein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Då synte det seg i same stundi fingrar som av ei mannehand, som skreiv på den kvitkalka veggen i kongshalli, midt imot ljosestaken; og kongen såg handi som skreiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Då skifte kongen liter, og tankarne skræmde honom, og han veikna i mjødmarne, og knei hans slo imot einannan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Og kongen ropa med høg røyst, og baud at dei skulde henta manarane og kaldæarane og stjernetydarane. Og kongen sagde so til dei vise i Babel: «Kven det er som kann lesa denne skrifti og gjeva meg uttydingi på henne, han skal verta klædd i purpur, ei gullkjeda skal han få um halsen, og verta den tridje mannen i riket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Då kom alle kongens vismenner til stades, men dei kunde ikkje lesa skrifti eller segja kongen kva ho tydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Då vart kong Belsassar øgjeleg forfærd, og skifte liter, og stormennerne hans stod forstøkte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Men då talen åt kongen og stormennerne hans kom for øyro åt dronningi, gjekk ho til gildehalli; der tok dronningi til ords og sagde: «Kongen live æveleg! Lat ikkje tankarne skræma deg, og ikkje skal du skifta liter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'I riket ditt finst ein mann som anden åt heilage gudar er i. I dagarne åt far din synte det seg at han åtte både upplysning og klokskap og visdom som visdom hjå gudar; og far din, kong Nebukadnessar, sette honom til hovding yver runemeistrarne, manararne, kaldæarane og stjernetydarane; ja, dette gjorde far din, kongen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'etter di det hjå honom var ei makelaus ånd og kunnskap og skyn, og dugleik til å tyda draumar og gjeta gåter og greida vande flokar, hjå denne Daniel, som kongen hadde gjeve namnet Beltsassar. Send difor bod etter Daniel! So gjev nok han deg uttydingi».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Då so Daniel var henta til kongen, tok kongen til ords og sagde til Daniel: «Du er fulla Daniel, ein av dei jødiske fangarne som far min, kongen, førde hit frå Juda?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Eg hev høyrt folk segja um deg at anden åt gudar er i deg, og at det hev synt seg at du eig upplysning og skyn og makelaus visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'No er det so at dei vise og manararne hev vorte henta hit til meg til å lesa denne skrifti og segja meg uttydingi på henne; men dei kunde ikkje gjeva meg nokor uttyding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Men um deg hev eg høyrt at du kann gjeva uttydingar og greida vande flokar. Kann du no lesa denne skrifti og segja meg uttydingi på henne, so skal du verta klædd i purpur, og få ei gullkjeda um halsen din, og du skal verta tridje mannen i riket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Då svara Daniel og sagde til kongen: «Gåvorne dine kann du sjølv hava eller gjeva deim til ein annan; deim forutan skal eg lesa skrifti for kongen og segja honom uttydingi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Til Nebukadnessar, far din, konge, gav Gud den høgste kongemagt, stordom, æra og herlegdom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'og for den stordomen skuld som han hadde gjeve honom, skalv alle folk og ætter og tungemål for honom og ræddast. Kven han vilde, drap han, og kven han vilde, let han liva; kven han vilde, gjorde han stor, og kven han vilde, gjorde han liten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Men då han ovmoda seg i hjarta sitt, og åndi hans vart stolt og stormodig, vart han støytt ifrå kongsstolen sin, og æra hans vart frå honom teki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Han vart utstøytt frå menneski, og hjarta hans vart som hjarta hjå eit dyr, og han laut bu millom villasen og eta gras som uksarne, og av doggi frå himmelen vart kroppen hans vætt, til dess han sanna at Gud den høgste råder yver mannariket og set yver det kven han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Men du, Belsassar, son hans, som hev visst alt dette, hev endå ikkje gjort hjarta ditt audmjukt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'men ovmoda deg mot Herren i himmelen og late folk bera fram for deg kjeraldi frå huset hans; og du og stormennerne dine, konorne og fylgjekonorne dine, hev drukke vin or deim, og du hev prisa dine gudar av sylv og gull, av kopar, jarn, tre og stein, som korkje ser eller høyrer eller veit noko. Men den Gud som hev åndi di og alle dine vegar i sitt vald, honom hev du ikkje æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Difor hev no denne handi vorte send frå honom, og denne skrifti rita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Og so lyder den skrifti som her er rita: Mené, mené, tekél, ufarsin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Og dette er uttydingi på ordi: Mené, det tyder: Gud hev talt dagarne åt riket ditt og gjort ende på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekél, det tyder: du er vegen på ei vegt og funnen for lett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Perés, det tyder: riket ditt er sundbytt og gjeve åt medarar og persarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Då baud Belsassar, og dei klædde Daniel i purpur, og hengde ei gullkjeda um halsen hans, og ropa ut um honom at han skulde vera tridje mannen i riket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Same natti vart Belsassar, kaldæarkongen, drepen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Og Darius frå Media tok imot riket då han var tvo og seksti år gamall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Og Darius fann for godt å setja eit hundrad og tjuge satrapar yver riket, so det alle stadar i riket skulde vera slike å finna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Og yver deim sette han tri riksrådar, og av deim var Daniel den eine; for deim skulde satraparne gjera rekneskap, so kongen ingen skade leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Men Daniel merkte seg ut framfor hine riksrådarne og satraparne, for det var ei makelaus ånd i honom, og kongen tenkte på å setja honom yver heile riket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Då søkte dei andre riksrådarne og satraparne å finna ei sak imot Daniel i det som kom riksstyringi ved. Men dei kunde ingi sovore sak finna, eller noko som var rangt, med di han var trugen i tenesta si; ingi misferd og inkje rangt var å finna hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Då sagde mennerne: «Me finn ikkje nokor sak imot denne Daniel, minder det skulde lata seg gjera å finna noko i gudsdyrkingi hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Etter dette styrmde desse riksrådarne og satraparne inn til kongen og sagde soleis til honom: «Kong Darius live æveleg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Alle riksrådarne og jarlarne og satraparne, rådsherrarne og landshovdingarne i riket hev samrådt seg um at eit kongelegt påbod burde verta gjeve, og eit forbod ferda ut, at kven det er som i tretti dagar heldt si bøn til nokon annan, det vere gud eller menneskje, enn til deg, konge, han skal verta kasta i løvegropi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'So lat det no, konge, verta ferda ut eit forbod, og lat det setja upp skriftleg, so det ikkje kann takast attende, etter ubrigdeleg lov hjå medarar og persarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'I samhøve med dette let kong Darius eit skriv setja upp og eit forbod ferda ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Men so snart Daniel hadde fenge visst at skrivet var uppsett, gjekk han inn i huset sitt; der hadde han på den øvre salen sin vindaugo som var opne mot Jerusalem. Der fall han tri gonger um dagen på kne og bad og takka Gud, soleis som han fyrr hadde vore van til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Då styrmde mennerne inn, og dei fann Daniel, som bad og kalla på sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Sidan gjekk dei til kongen og spurde honom um det kongelege forbodet: «Hev du ikkje late setja upp eit forbod, at kven det er som i tretti dagar held si bøn til nokon annan, det vere gud eller menneskje, enn til deg, konge, han skal verta kasta i løvegropi?» Kongen svara: «Jau, og det ordet stend fast etter ubrigdeleg lov hjå medarar og persarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Då svara dei og sagde til kongen: «Daniel, ein av dei jødiske fangarne, agtar korkje på deg eller på det forbodet som du hev late setja upp, men held si bøn tri gonger um dagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Då kongen høyrde dette, vart han svært sorgfull, og gjorde seg sut for korleis han skulde kunna berga Daniel; alt til soleglad mødde han seg med å leita etter ein utveg til å hjelpa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Då styrmde mennerne inn til kongen og sagde til honom: «Kongen må vita at det er ei lov hjå medararne og persararne, at ikkje noko forbod eller påbod som kongen ferdar ut, kann brigdast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Då baud kongen at dei skulde henta Daniel og kasta honom i løvegropi; og kongen tala til Daniel og sagde: «Guden din, som du so ideleg dyrkar, han frelsa deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Og dei fann fram ein stein og lagde den yver gropsmunnen, og kongen innsigla honom med sitt eige innsigle og innsiglet åt stormennerne sine, so det ikkje skulde verta gjort noko um att i det som hadde hendt med Daniel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Etter dette gjekk kongen heim til slottet sitt, og han fasta heile natti og let ingi kvinnor koma inn til seg; og han fekk ikkje blund på augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Sidan um morgonen, i lysingi, reis kongen upp og skunda seg til løvegropi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Og då han var nær burt åt gropi komen, ropa han på Daniel med sorgfull røyst. Kongen tok til ords og sagde til Daniel: «Daniel, du tenar åt den levande Gud, må tru Guden din, den som du so ideleg dyrkar, hev kunna berga deg frå løvorne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Då svara Daniel kongen: «Kongen live æveleg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Min Gud hev sendt engelen sin til å lata att løvemunnarne, so dei ingen skade hev gjort meg. For eg er funnen saklaus for honom; og ikkje heller hev eg forbrote meg mot deg, konge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Då vart kongen ovleg glad, og baud at dei skulde taka Daniel upp or gropi. Og då Daniel var teken upp or gropi, kunde dei ingen skade finna på honom; for han hadde trutt på sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Sida baud kongen, og dei henta dei mennerne som hadde klaga Daniel, og kasta deim og borni og konorne deira i løvegropi; og endå fyrr dei var til botnar komne, rauk løvorne på deim og krasa kvart beinet i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Etter dette skreiv kong Darius til alle folk og ætter og tungemål som fanst på heile jordi: «Heil og sæl!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Hermed gjev eg det bodet at i heile mitt rike skal folk skjelva og ottast for Daniels Gud. For han er den livande Gud, som skal vera i all æva; og riket hans er eit som ikkje kann øydast, og veldet hans varer alt til enden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Han frelsar og friar ut, han gjer teikn og under i himmelen og på jordi, han som hev frelst Daniel or løve-vald.» Og denne Daniel steig i æra og magt i styringstidi åt Darius og persaren Kyrus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'I det fyrste styringsåret åt den babyloniske kongen Belsassar hadde Daniel ein draum og såg ei syn i hovudet på lægjet sitt. Sidan skreiv han upp draumen og fortalde hovudsummen av innhaldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel tok til ords og sagde: Eg hadde ei syn um natti, og i den syni såg eg korleis dei fire himmelvindarne storma fram yver det store havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Og fire store dyr steig upp or havet, det eine ulikt det andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Det fyrste liktest ei løva, men det hadde vengjer som ein ørn. Medan eg såg på det, vart vengjerne rivne av dyret, og det vart lyft upp frå marki og sett på tvo føter som eit menneskje, og eit mannehjarta fekk det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'So fekk eg sjå eit dyr til, det andre i rekkja; det var likt ein bjørn, og det lette seg upp på den eine sida, og det hadde tri sidebein i gapet millom tennerne. Og til dyret vart det sagt: «Statt upp, og et mykje kjøt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Etter det fekk eg sjå eit anna dyr, som liktest ein pantar, men på sidorne hadde det fire fuglevengjer; og dyret hadde fire hovud, og velde vart det gjeve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Etter det fekk eg i syni mi um natti sjå det fjorde dyret, øgjelegt og skræmelegt og uhorveleg sterkt; det hadde store tenner av jarn, det åt og krasa, og leivningarne trakka det sund med føterne: det var ulikt alle hine dyri og hadde ti horn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Medan eg skoda på horni, fekk eg sjå korleis det skaut upp millom deim eit anna horn, eit lite, som skuva undan seg tri av hine horni; og sjå, det hornet hadde augo lik manneaugo, og ein munn som tala store ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Medan eg heldt på og såg på dette, vart det sett fram stolar, og ein som gamall var, sette seg ned. Klædnaden hans var snøkvit, og håret på hovudet hans som rein ull; stolen hans var av eldslogar, og hjuli under var av brennande eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ei elv av eld strøymde ut frå honom; tusund gonger tusund var tenarane hans, og ti tusund gonger ti tusund stod til tenesta for honom. So vart retten sett, og bøker vart opna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Medan eg heldt på og såg på dette, hende det, for dei store ord skuld som hornet tala, at medan eg heldt på og såg på dette, vart dyret drepe, og kroppen åt dyret vart tynt og kasta i elden til å brennast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Veldet åt dei andre dyri vart frå deim teke; for livetidi var fastsett til tid og stund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Sidan fekk eg sjå i nattsynerne korleis ein som liktest ein menneskjeson, kom med himmelskyerne; han gjekk burt til den gamle og vart ført fram for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Og han fekk velde og æra og rike, og alle folk og ætter og tungemål skulde tena honom. Hans velde er eit ævelegt velde, som ikkje skal verta frå honom teke, og riket hans skal ikkje rikkast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Då kjende eg, Daniel, åndi mi uroast i meg, og synerne i hovudet mitt skræmde meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Eg gjekk fram til ein av deim som stod der, og bad honom um ei pålitande uttyding på alt dette. Og han svara meg og sagde meg uttydingi på det:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '«Desse fire store dyri tyder at det skal koma upp fire kongar av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Men sidan skal dei heilage åt den Høgste taka imot riket og hava det i eiga alt til æva, ja, til ævordoms æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Etter dette vilde eg hava pålitande uttyding um det fjorde dyret som var ulikt alle hine, det som var so oversleg øgjelegt og hadde tenner av jarn og klør av kopar, det som åt og krasa og sidan trakka under føterne det som det leivde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'so og um dei ti horni på hovudet åt det og um det nye hornet, det som sidan skaut upp, og som dei tri andre fall av for, det hornet som hadde augo og ein munn som tala store ord, det som var større å sjå til enn alle hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Eg hadde set hornet føra krig mot dei heilage og sigra yver deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'til dess han kom, han som gamall var, og retten vart gjeven til dei heilage åt den Høgste, og tidi var komi då dei heilage fekk riket i eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Då svara han og sagde: «Det fjorde dyret tyder at eit fjorde rike skal koma upp på jordi og vera ulikt alle hine riki. Det skal gløypa heile jordi og trakka henne sund og krasa henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Og dei ti horni tyder at det skal koma upp ti kongar i det riket; og etter deim skal det koma upp ein annan, som skal vera dei fyrre ulik, og som skal slå ned tri kongar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Og han skal tala ord mot den Høgste, og dei heilage åt den Høgste skal han øyda; han skal setja seg fyre å skifta um tider og lov; og dei skal gjevast i hans hand ei tid og tider og ei halv tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Men so vert retten sett, og veldet hans skal verta frå honom teke, spillt og avøydt alt til endes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Men herredøme og veldet og stordom yver alle rike under himmelen skal verta gjeve til lyden av dei heilage åt den Høgste. Hans rike skal vera eit ævelegt rike, og alle herrevelde skal tena og lyda det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Her sluttar fråsegni. Men eg, Daniel, vart full av mange urolege tankar, og eg skifte liter i andlitet; men eg gøymde i hjarta mitt det som hadde hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'I det tridje styringsåret åt Belsassar såg eg, Daniel, ei syn, ei som kom etter den eg fyrr hadde set.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Då eg no i denne syni skulde til å sjå, syntest det meg at eg var i Susanborgi i Elamfylket; og då eg såg meir til i syni, fann eg at eg var ved elvi Ulai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Og då eg såg upp, fekk eg sjå ein ver framved elvi, og han hadde tvo horn; og båe horni var høge; men det eine var høgre enn hitt, og det som var høgre, skaut sist upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Eg såg veren stanga med horni vestetter og nordetter og sudetter, og inkje dyr kunde standa honom imot, og ingen kunde berga or hans vald; han for fram som han vilde, og tok seg store ting til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Og då eg gav meir gaum, fekk eg sjå ein bukk koma vestantil og fara fram yver all jordi, men han kom ikkje nær marki; og bukken hadde eit drustelegt horn i skallen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Og han kom burt til veren med dei tvo horni, den som eg hadde set standa framved elvi, og for imot honom i veldug vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Eg såg honom koma radt inn på veren og drusa til honom i illska, og han stanga til veren og braut sund båe horni hans, so at veren ingi magt hadde til å standa imot honom; og han kasta honom til jordi og trakka på honom, og det beid ingen som kunde berga veren or hans vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Og bukken briska seg storleg. Men då han stod i si beste magt, brotna det store hornet hans, og fire andre drustelege horn skaut upp i staden, ut mot dei fire himmelætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Frå eitt av deim gjekk det ut eit nytt horn, lite i fyrstningi, og det voks oversleg sudetter og austetter og mot det herlege landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Og det voks ende upp til himmelheren og kasta nokre av denne heren, av stjernorne, ned til jordi og trakka på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ja, jamvel mot hovdingen yver heren briska det seg; han tok burt det daglege offeret, og hans heilagdoms bustad vart nedriven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Saman med det daglege offeret vart og ein herskare gjeven til pris for brot skuld. Og det slo sanningi ned til jordi, og det lukkast vel, alt det tok seg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Sidan høyrde eg ein heilag som tala, og ein annan heilag spurde honom som tala: «Kor lang tid sigtar ho på, syni um det daglege offeret og um brotet som valdar øyding, og um nedtrakkingi av både heilagdom og her?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Då svara han meg: «Tvo tusund og tri hundrad kveldar og morgnar; etter det skal heilagdomen koma til retten sin att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Då eg, Daniel, no hadde set denne syni og freista skyna henne, fekk eg sjå at det stod noko framfyre meg, som liktest ein mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Og midt yver Ulai høyrde eg ei mannerøyst, som ropa og sagde: «Gabriel, tyd syni for denne mannen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Då kom han innåt staden der eg stod; men eg vart rædd då han kom, og kasta meg å gruve. Og han sagde til meg: «Gjev gaum på dette, du menneskjeson; for syni sigtar på endetidi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Medan han soleis tala med meg, seig eg i uvit med andlitet mot jordi; men han rørde ved meg og reiste meg upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'So sagde han: «Sjå, eg vil kunngjera deg kva som skal henda når det lid til endes med vreiden; for på endetidi sigtar dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Den tvihyrnte veren som du såg, tyder kongarne i Media og Persia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Men den raggute bukken er Javan-kongen, og det store hornet i skallen hans er den fyrste kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Men at det brotna, og at det kom fire andre att i staden, det tyder at folket hans skal verta fire rike, men ikkje med hans kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Og ved slutten på veldet deira, når illgjerdsmennerne hev fyllt sitt mål, skal det koma upp ein konge, ubljug og meinsløg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Veldet hans skal verta stort, men ikkje med hans kraft; og han skal gjera utruleg stor skade og hava heppa med seg i verket sitt; megtige skal han tyna, og eit folk av heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Med di han er so klok, skal han hava slik heppa med seg i svikarferdi si; han skal setja seg store ting fyre, og uventande skal han tyna mange. Ja, mot hovdingen yver hovdingarne skal han setja seg upp; men utan manns hand skal han då verta krasa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Og sanning er syni um kveldarne og morgnarne, som no er umtala. Men gøym du denne syni, for ho peikar langt fram i tidi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Men eg, Daniel, vart reint utav det og låg sjuk ei tid. Sidan kom eg meg på føterne att og gjorde mi tenesta hjå kongen; og eg var forstøkt yver syni; men det var ingen som merka det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'I det fyrste styringsåret åt Darius, son åt Ahasverus - han som var av medisk ætt, og var sett til konge yver Kaldæar-riket -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'i det fyrste styringsåret hans kom eg, Daniel, i bøkerne til å gjeva ans på det åretalet som Herren hadde nemnt for profeten Jeremia, då han sagde at han vilde lata sytti år lida til endes, medan Jerusalem låg i røys.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Då vende eg andlitet mot Herren Gud med inderleg bøn og påkalling, og attåt det fasta eg i sekk og oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Eg bad til Herren, min Gud, og skrifta og sagde: «Å, Herre, du store og skræmelege Gud, du som held uppe samband og nåde mot deim som elskar deg og held bodi dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Me hev synda og gjort ille og vore gudlause og tråssuge; me hev vike av ifrå bodi dine og loverne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Me hev ikkje høyrt på tenarane dine, profetarne, som tala i ditt namn til kongarne våre og hovdingarne og federne og heile landslyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Du, Herre, er rettferdig, men me lyt blygjast, som me og gjer no, me Juda-menner og Jerusalems-buar og alt Israel, både dei som er nær og som bur langt burte i framande land, dit du hev drive deim burt, av di dei var utrue imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ja, Herre, me må blygjast med kongarne og hovdingarne og federne våre, av di me hev synda imot deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Men hjå Herren, vår Gud, er miskunn og forlating. For me var tråssuge imot honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'og høyrde ikkje på røysti åt Herren, vår Gud, um å leva etter loverne hans, som han lagde fram for oss ved tenarane sine, profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Nei, alt Israel braut di lov og veik av og høyrde ikkje på di røyst. Difor vart ho og utrend yver oss, den forbanningi som han hadde svore å senda, og som stend skrivi i lovi åt Guds tenar Moses; for me hadde synda imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Han heldt ordi sine, som han hadde tala imot oss og imot domarane som dømde oss; og han let so stor ei ulukka koma yver oss, at det ingen stad under himmelen hev hendt noko slikt som hev hendt i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Etter det som stend skrive i Moselovi, kom all denne ulukka yver oss; men endå gjorde me inkje til å blidka Herren, vår Gud, med å vende um ifrå misgjerningarne våre og agta på sanningi di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Difor vakte og Herren yver ulukka og let henne koma yver oss; for Herren, vår Gud, er rettferdig i alle dei gjerningar han gjer; men me høyrde ikkje på røysti hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Og no, Herre, vår Gud, du som førde folket ditt ut or Egyptarland med sterk hand og soleis gjorde deg eit namn som er det same endå i dag! Me hev synda, me hev vore gudlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Men Herre, for all di rettferd skuld, lat vreiden og harmen din venda seg ifrå Jerusalem, ditt heilage fjell! for ved synderne våre og misgjerningarne åt federne våre hev Jerusalem og folket ditt vorte til spott for alle som bur ikring oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Og høyr no, vår Gud, bøni og påkallingi åt tenaren din, og lat di åsyn lysa yver den øydelagde heilagdomen din, for Herrens skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Bøyg, min Gud, øyra ditt hit og høyr! Lat upp augo dine og sjå røysarne våre og byen som er uppkalla etter ditt namn! For me lit ikkje på våre rettferdsverk når me ber fram våre påkallingar for di åsyn, men me lit på di store miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Herre, høyr! Herre, forlat! Herre, gjev gaum, gjer ditt verk, og dryg ikkje - for di skuld, min Gud! for byen din og folket ditt er då uppkalla etter ditt namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Endå medan eg tala soleis og bad og sanna mi eigi synd og syndi åt Israel, folket mitt, og for Herren, min Gud, bar fram mi forbøn for min Guds heilage fjell,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'endå medan eg tala soleis i bøn, kom Gabriel til meg, den mannen som eg fyrr hadde set i syni, den gongen eg seig i uvit; og det var ved det bilet då kveldsofferet vart frambore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Han greidde ut for meg og tala til meg og sagde: «Daniel, eg er no utgjengen og skal læra deg å skyna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Då du tok til å beda, gjekk det ut eit ord, og eg er komen og vil gjeva deg melding, for du er sers gjæv. So gjev då agt på ordet, og agta på syni!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sytti vikor er fastsette for folket ditt og for den heilage byen din, innan brotet vert fullenda, og synderne tek slutt, og misgjerningarne vert sona, og ei æveleg rettferd førd fram, og innan syn og profetord vert stadfeste, og ein høgheilag heilagdom vert salva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Og du skal vita og skyna: Frå den tidi då ordet gjekk ut um atterreising av Jerusalem, til dess det kjem ein som er salva, ein fyrste, skal sju vikor lida av, og i tvo og seksti vikor byen skal det verta atterreist med gator og vollgraver, endå um tiderne er tronge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Men etter dei tvo og seksti vikorne skal ein som er salva, verta utrudd og inkje hava. Og byen og heilagdomen skal verta øydde av folket åt ein fyrste som kjem, og han skal enda i ein storflaum; Og alt til enden skal det vera strid. Øyding er urikkeleg avgjord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Og han skal gjera eit sterkt samband med mange for ei vika, og ved honom skal slagtoffer og grjonoffer vera avteke for ei halv vika; og på styggedoms veng skal øydaren koma. Detta skal ganga fyre seg, til dess øyding og urikkeleg avgjord straffedom strøymer ut yver øydaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'I det tridje styringsåret åt persarkongen Kyrus fekk Daniel, som dei og kalla Beltsassar, ei openberring; den openberringi er sanning og spår mykje trengsla. Og han merkte openberringi og gav agt på syni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Eg, Daniel, hadde då gjenge og syrgt ei tri vikor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Eg åt ikkje noko slag forkunnmat, kjøt og vin kom ikkje i min munn, ikkje heller salva eg meg med olje, fyrr dei tri vikorne var avlidne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Den fire og tjugande dagen i fyrste månaden, då eg var ved strandi åt den store elvi Hiddekel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'såg eg upp, og då fekk eg sjå ein mann som stod der klædd i linklæde og gyrd kring lenderne med eit belte av Ufaz-gull.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Likamen hans var som krysolit, andlitet hans liktest ljoneld, augo hans var som eldslogar, armarne og føterne hans som skinande kopar; og ljomen av talen hans var som ein veldug dun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Og eg, Daniel, var den einaste som såg syni; dei mennerne som var med meg, dei såg ikkje syni; men ei stor rædsla kom yver deim, so dei flaug av og gøymde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'So vart eg åleine etter, og då eg såg denne store syni, vart eg reint magtstolen; skifte liter i andlitet so eg vart nåbleik, og eg åtte ingi magt meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Då høyrde eg ljomen av talen hans; og då eg høyrde ljomen av talen hans, seig eg i uvit å gruve med andlitet mot jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Sjå, då var det ei hand som tok i meg, so mykje eg skjelvande vann meg uppå kne og hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Sidan sagde han til meg: «Daniel, du gjæve mann, gjev agt på dei ordi som eg vil tala til deg, og ris upp og statt; for no er eg send til deg.» Då han sagde dette til meg, reis eg skjelvande upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Og han sagde til meg: «Ottast ikkje, Daniel, for alt frå den fyrste dagen då vende hjarta ditt til å vinna skyn og å audmykja deg for Gud, hev ordi dine vore høyrde; og for ordi dine skuld er eg komen no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Hovdingen yver persarriket stod meg imot i ein og tjuge dagar; men då kom Mikael, ein av dei fremste hovdingarne, og hjelpte meg, medan eg fyrr hadde stade der åleine mot persarkongarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Og no er eg komen og vil segja deg kva som skal hendast folket ditt i endetidi; for dette er og ei syn som sigtar på framtidi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Medan han soleis tala til meg, vende eg andlitet mitt mot jordi og tagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Men sjå, ein som var lik eit menneskje, tok på lipporne mine. Då let eg upp munnen min og tala og sagde til honom som stod framfyre meg: «Herre min, ved den syni eg hev set, hev det kome slik verk yver meg, at eg eig ingi magt meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Kor skulde og tenaren til herren min, ein sovoren som eg, kunna tala med ein slik ein som herren min er? Og ingi magt er det i meg meir, eg evlar no ikkje å anda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Han som såg ut som eit menneskje, tok då atter i meg og styrkte meg. Han sagde: «Ottast ikkje, du gjæve mann! Fred vere med deg! Ver sterk, ja, ver sterk!» Då han tala med meg soleis, kjende eg kor eg styrktest, og eg sagde: «Tala, herre min, for no hev du styrkt meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Då sagde han: «Kann du skyna kvifor eg er komen til deg? Men eg lyt straks venda attende og strida mot hovdingen yver Persia, og når eg dreg ut, kjem Javan-hovdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Like vel vil eg kunngjera deg kva som er skrive i sanningsboki. Og det er ikkje ein som hjelper meg mot desse utan Mikael, hovdingen dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Og eg stod og ved hans sida til hjelp og til vern det fyrste styringsåret åt medaren Darius.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Og no skal eg kunngjera deg det som visst er. Sjå, endå skal tri kongar standa fram i Persia, og den fjorde skal vinna seg større rikdom enn nokon av dei andre, og når han er vorten sterk ved rikdomen sin, skal han bjoda ut alt mot Javanriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Sidan skal det standa fram ein veldug konge, og han skal rikja med stor magt og gjera som han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Men han skal ikkje for vel vera komen, fyrr riket hans skal rivna og verta sundbytt etter dei fire himmelætterne; og det skal ikkje falla hans ætt til eller verta so megtigt som det var då han rådde; for riket hans skal rivast og falla andre til enn deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Og kongen i Sudlandet skal verta veldug, og ein av hovdingarne hans og; ja, denne hovdingen skal verta ein endå veldugare hovding enn han sjølv er, og veldet hans skal verta stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Og um nokre år skal dei gjera ei semja seg imillom, og dotter åt Sudlands-kongen skal draga avstad til kongen i Norderlandet og freista å få deim forlikte. Men magti ho vinn, skal ho ikkje eiga lenge, ikkje heller skal han og hans magt verta varande; men ho skal verta gjevi til pris, ho tilliks med deim som let henne draga dit, både far hennar og den mannen som i si tid tok henne til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Men av renningar frå hennar rot skal ein stiga upp i hans stad. Han skal fara fram imot heren åt kongen i Norderlandet og brotja inn i festningarne hans og gjera med deim som han vil, og han fær yvermagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Gudarne deira og bilæti og dei dyrverdige kjeraldi deira, både sylv og gull, skal han føra til herfang til Egyptarland. Sidan skal han i nokre år lata kongen i Norderlandet vera i fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Men han skal trengja inn i riket åt Sudlands-kongen; men han skal venda heim att til landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Og sønerne hans skal bu seg til strid og samla velduge herar; og ein av deim skal fara fram og fløyma yver og breida seg ut; og han skal koma att, og striden skal dei føra fram alt til festingi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Då skal kongen i Sudlandet reisa seg i harm og draga ut og strida mot kongen i Norderlandet, og han skal fylkja ein stor her; men den heren skal verta gjeven i hans hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Når so heren er sprengd, aukar ovmodet hans; men um han so hev felt titusund, fær han då ikkje magti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Kongen i Norderlandet skal fylkja ein ny her, større enn hin; og um nokre års tid skal han koma med ein stor krigsher og stort træn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'På same tid skal mange reisa seg mot kongen i Sudlandet; og valdsmenner av ditt eige folk skal og reisa seg, so syni skal sanna seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Og kongen i Norderlandet skal fara fram og setja upp vollar og taka ein borgby, og Sudlands-magti skal ikkje kunna standa seg, og det utvalde herfolket hans skal ikkje eiga magt til motstand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Han som fer imot honom, skal fara åt som han vil, og ingen skal kunna standa seg imot honom; han skal setja seg fast i det herlege landet, og øyding skal handi hans valda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Og han skal etla seg til å koma med heile magti i riket sitt; like vel er han huga på semja, og det skal han og få til. Ei av døtterne sine skal han gjeva honom til kona, til tjon for landet. Men det skal ikkje koma i stand og ikkje verta av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Etterpå skal han snu seg mot øylandi og taka mange; men ein herførar skal gjera ende på svivyrdingi hans, ja, lata svivyrdingi hans koma yver honom sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Då skal han snu seg mot borgerne i sitt eige land; men han skal snåva og falla og sidan ikkje verta funnen att meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Og i hans stad skal det standa fram ein annan, og han skal lata ein skattefut fara gjenom riksens prydnad, men um nokre dagar skal han verta tynt, men ikkje i vreide, ei heller i krig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Og i hans stad skal det standa fram ein stakar, som det ikkje var etla kongedøme åt; uventande skal han koma og eigna til seg riket med meinråder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Og yverfløymde herar skal skolast burt framfyre honom og krasast, og sambandsfyrsten sameleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Frå den stund dei gjer samband med honom, skal han fara med svik. Og han skal fara fram og få yvermagti med lite folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Uventande skal han koma inn i dei grøderikaste bygder av landet og gjera ting som korkje far hans eller forfederne hans hev gjort; herfang og rov og gods skal han strå ut til folket sitt; og mot borgerne skal han hava rådgjerder fyre, til ei viss tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'All si magt og alt sitt mod skal han bruka mot Sudlands-kongen og koma med ein stor her; men Sudlands-kongen skal og bu seg til strid med ein ovleg stor og mannsterk her; like vel skal han ikkje kunna standa seg, for det vert lagt meinråder mot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Dei som er i bordsamlag med honom, skal fella honom. Og heren hans skal fløyma utyver, og mange skal verta slegne og falla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Båe kongarne skal vera meinte på vondt; der dei sit ved same bord, skal dei tala lygn; men det skal ingen framgang hava; for endå dryger det med enden, til den fastsette tidi kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Han skal venda heim att til landet sitt med stort herfang, og han skal leggja upp råder mot det heilage sambandet; og når han hev fullført deim, skal han snu heim att til landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Til fastsett tid skal han fara imot Sudlandet; men det skal ikkje ganga denne gongen som det gjekk gongen fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'For skip frå Kittim skal koma imot honom, og modet skal han missa. Då skal han snu um og venda vreiden sin mot det heilage sambandet og sleppa sinnet sitt laust. Og når han er heimkomen, skal han merka seg deim som vender seg ifrå det heilage sambandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Og herar som han sender ut, skal koma og skamfara heilagdomsborgi og taka burt det daglege offeret, og den øydande styggedomen skal dei setja upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Og deim som hev krenkt sambandet, skal han med håle ord få gjort heilt ut til heidningar; men dei av folket som kjenner sin Gud, skal standa støduge og halda ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Og dei vituge millom folket skal læra mange; men ei tid skal dei verta heimsøkte med sverd og bål, med fangekår og herjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Like vel skal dei i si heimsøkjing få ei liti hjelp, og mange skal då fylkja seg til flokken deira på skrymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Heimsøkjingi skal råma sume av dei vituge, so det kann verta ei skiring millom deim, so dei vert reinsa og tvegne til endetidi; for endå drygjer det med den til den fastsette tidi kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Og kongen skal fara åt som han vil, hevja og briska seg mot alt som Gud er; ja, mot Gud yver gudarne skal han tala utruleg kaute ord. Og alt skal lukkast honom vel, til dess vreidetidi er ute, då det hev hendt som er urikkeleg avgjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'På fedregudarne sine skal han ikkje agta, ikkje heller skal han agta grumguden åt kvinnorne, ikkje heller på nokon annan gud; men han skal ovmoda seg imot deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Men borgguden skal han æra i staden; ein gud som federne hans ikkje hev kjent, skal han heidra med gull og sylv og dyrverdige steinar og andre kostnadting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Og mot sterke borger skal han med ein framand guds hjelp gjera som han lyster; deim som kannar denne guden, skal han syna stor æra; han skal setja deim til å råda yver mange, og han skal skifta ut jord åt deim til løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Men i endetidi skal kongen i Sudlandet til å stangast med honom; og kongen i Norderlandet skal storma fram mot honom med vogner og hestfolk og mange skip og falla inn i landi og fløyma yver og breida seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Han skal og draga inn i det herlege landet, og mange andre land skal verta heimsøkte; men desse skal koma seg undan henderne hans: Edom og Moab og storluten av ammonitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Ja, han skal retta handi ut mot framande land, og Egyptarland skal sleppa undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Han skal eigna til seg skattar av gull og sylv og alle slag kostnadting i Egyptarlandet; og libyarar og ætiopar skal fylgja i hans far.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Då skal han frå aust og nord høyra tidender som støkkjer honom; og han skal draga ut i stor vreide til å øyda og tyna mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Og slottstjeldi sine skal han setja upp millom havet og det herlege heilagdoms-fjellet. Men so ber det til enden med honom, og ingen skal hjelpa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, '«På den tidi skal Mikael stiga fram, den store hovdingen som stend verja for borni åt folket ditt; og det kjem ei trengsletid som det ikkje hev vore makan til alt frå den dagen då det vart folk til, og like til den tidi. Men på den tidi skal alle dei av folket ditt verta frelste som finst skrivne i boki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Og mange av deim som søv i moldi, skal vakna upp, sume til æveleg liv sume til skam og æveleg stygg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Då skal dei vituge skina som himmelkvelven skin, og dei som hev ført mange til rettferd, som stjernor æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Men du, Daniel, må gøyma ordi og forsigla boki alt til endetidi; mange skal granska henne, og kunnskapen skal auka.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Då eg, Daniel, no såg til, fekk eg sjå tvo andre som stod der, ein på den eine elvebakken og ein på den andre elvebakken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Og ein av deim sagde til mannen som var klædd i linklæde, og som stod ovanfor vatnet i elvi: «Kor lenge drygjer det fyrr enden kjem med desse underfulle hende?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Og eg høyrde på mannen som var klædd i linklæde, og som stod ovanfor vatnet i elvi; han lyfte høgre handi si og vinstre handi si upp imot himmelen og svor ved honom som liver æveleg: «Ei tid og tider og ei halv tid; og når magti åt det heilage folket er krasa, då skal alt dette fullendast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Og eg høyrde det, men eg skyna det ikkje, og eg spurde: «Herre min, kva er endelykti på dette?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Då sagde han: «Gakk du, Daniel; for desse ordi er løynde og forsigla alt til endetidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Mange skal verta reinsa og tvegne og skirde; men dei gudlause skal driva på med si gudløysa, og ingen gudlaus skal skyna det; men dei vituge skal skyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Og frå den tid då det daglege offeret vert avteke og den øydande styggedomen sett upp, skal det ganga eit tusund tvo hundrad og nitti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Sæl er den som biar og når fram til eit tusund tvo hundrad og fem og tretti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Men gakk du av stad til endelykti! Når du hev kvilt, skal du standa upp og få din lut, når dagarne fær ende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Herrens ord som kom til Hosea, son åt Be’eri, i dei dagarne då Uzzia, Jotam, Ahaz og Hizkia var kongar i Juda, og då Jeroboam, son åt Joas, var konge i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Herrens fyrste ord til Hosea var at han sagde til honom: «Gakk stad og få deg ei horkona og horeborn! For landet driv på med hor og fer soleis burt ifrå Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Då gjekk han stad og gifte seg med Gomer dotter, hans Diblajim. Og ho vart med barn og fødde honom ein son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Og Herren sagde til honom: «Lat honom heita Jizre’el! For um ein stakkut stund vil eg lata huset hans Jehu lida for Jizre’els blodskuld og gjera ende på kongedømet i Israels hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Den dagen skal det bera so til at eg bryt sund Israels boge i Jizre’els dal.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Og ho vart med barn att og fekk ei dotter. Då sagde han til honom: «Lat henne heita Lo-Ruhama! For eg kjem ikkje lenger til å miskunna Israels hus, so eg tilgjev deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Men Judas hus miskunnar eg og let deim verta frelste av Herren, deira Gud. Men med boge og sverd og krig, med hestar og ridarar frelser eg deim ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Då ho hadde vant av Lo-Ruhama, vart ho med barn att og fekk ein son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Då sagde han: «Lat honom heita Lo-Ammi! For de er ikkje mitt folk, ikkje heller skal eg høyra dykk til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Men talet på Israels born skal vera som sanden på havsens strand, den som ikkje kann mælast eller teljast. Og det skal verta so, at der ein fyrr sagde til deim: «De er ikkje mitt folk,» der skal ein segja til deim: «Borni åt den livande Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Og Juda-borni og Israels-borni skal fylkja seg saman og velja seg ein konge og fara upp or landet. For stor er Jizre’els dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Seg då til brørne dykkar: «Ammi»! og til systerne dykkar: «Ru-hama»!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Skjem på mor dykkar, skjem! For ho er ikkje kona mi, og eg er ikkje mannen hennar. Lat henne få burt horebragderne or andlitet sitt og lauslynde-merket frå barmen sin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Elles skal eg klæda av henne, so ho ligg naki: Eg skal te henne fram som den dagen ho vart fødd. Eg skal gjera henne lik ei øydemark og ei turr-audn, og lata henne døy av torste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Og borni hennar, ikkje vil eg miskunna deim; for horeborn er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'For mor deira var ei horkvinna, ho som fekk deim, for skamleg åt, med di ho sagde: «Eg vil fara etter elskarane mine. For dei gjev meg maten min og drykken min, ulli mi og linet mitt, oljen min og vinen min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Sjå, difor stengjer vil eg stengja vegen din med tornar. Ja, ein mur skal eg setja upp framfyre henne, so ho ikkje skal finna stigarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Når ho då renner etter elskarane sine, skal ho ikkje nå i deim, når ho leitar etter deim, skal ho ikkje finna deim. Då skal ho segja: «Eg vil attende til den fyrste mannen min. For betre hadde eg det då enn no.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Og ho, ikkje skyna ho at det var eg som gav henne kornet og druvesafti og oljen, og som var storgjæv imot henne med sylv og med gull, som dei nytta ut for Ba’al.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Difor skal eg taka att kornet mitt når korntidi kjem, og druvesafti mi i rette stundi, og taka burt ulli mi og linet mitt, det som ho skulde løyna blygsli si med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Ja, no skal eg nækja blygsli hennar beint for augo på elskarane hennar, og ingen skal berga henne or mi hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Og eg skal gjera ende på all kjæta hennar, på gildi hennar, nymånarne og kviledagarne og alle høgtiderne hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Eg skal øyda vintrei og fiketrei hennar, som ho sagde um: «Dei er meg ei løn som elskarane mine gav meg.» Og eg skal gjera deim til villkjør som villdyri skal eta av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Soleis skal eg refsa henne for Ba’als-dagarne hennar, då ho brende røykjelse for deim og prydde seg med nasering og bringespenne og for etter elskarane sine, men gløymde meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Difor skal de vita at eg vil lokka henne burt og leida henne ut i villmarki, so eg kan få tala hjarteord med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'So vil eg derifrå gjeva henne att vinhagarne hennar, og gjera Akordalen til eit vonarled. Der skal ho syngja som i ungdomsdagarne sine, og som då ho for upp frå Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Og den dagen, segjer Herren, kjem det til å verta so at du ropar til meg: «Mannen min!» Og du skal ikkje meir ropa til meg: «Ba’al min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Ja, Ba’als-namni vil eg taka reint ut or munnen hennar, so dei aldri skal nemnast meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Den dagen gjer eg for deim ei pakt med dyri på marki, med fuglarne under himmelen og med kreket på jordi. Og boge og sverd og krig bryt eg sund. Eg skal få det reint ut or landet, og lata deim bu trygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Og eg vil trulova meg med deg til æveleg tid. Eg vil trulova meg med deg i rettferd og rett, i nåde og miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Ja, i truskap vil eg trulova meg med deg, og du skal kjenna Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Og den dagen kjem det til å verta so at eg bønhøyrer, segjer Herren, eg bønhøyrer himmelen, og han bønhøyrer jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Og jordi skal bønhøyra kornet og druvesafti og oljen, og dei skal bønhøyra Jizre’el.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Og plantar meg henne i landet og miskunnar Lo-Ruhama, og eg segjer til Lo-Ammi: «Folket mitt er du!» og ho, ho skal segja: «Min Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Og Herren sagde til meg: «Gakk ein gong til stad og elska ei kvinna som hev ein elskar og er ei lauslyndt kvinna, liksom Herren elskar Israels-borni, endå dei vender seg til andre gudar og elskar druvekakor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Og eg kjøpte meg ei slik kvinna og gav for henne femtan sylvdalar og tri tunnor bygg og attpå halvonnor tunna bygg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'So sagde eg til henne: «I mange dagar vert du no sitjande for meg og fær ikkje gjera hor eller hava med nokon annan mann å gjera. So skal eg og taka det sameleis med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'For i mange dagar skal Israels-borni sitja utan konge og hovding, utan ofring og bilætsulor, utan messehakel og husgudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'So skal Israels-borni venda um og søkja Herren, sin Gud, og David, kongen sin. Og bivrande skal dei koma til Herren og til hans velsigning i dei seinste dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Høyr Herrens ord, de Israels-born! For Herren hev sak med deim som bur i landet, av di det ingen truskap finst i landet, og ingen kjærleik og ingen kjennskap til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Dei sver og lyg, dei drep og stel og driv hor. Dei fer med vald, og blodverk fylgjer på blodverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Difor ligg landet i sorg, og alt som bur i det, sjuknar burt, både dyri på marki og fuglarne under himmelen. Jamvel fiskarne i havet set til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Like vel skal ingen skjella og ingen refsa; for folket ditt er liksom dei som trettar med ein prest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Ja, du skal falla um dagen, og profeten skal falla med deg um natti, og mor di tynar eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Det er ute med folket mitt, av di det vantar kunnskap. Etter di du hev vanda kunnskap, so skal eg og vanda deg, so du ikkje vert min prest. Og etter di hev gløymt lovi åt din Gud, so skal eg og gløyma borni dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Di fleire dei vart, di meir synda dei mot meg. Men deira heider skal eg snu um til vanheider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Av mitt folks synd nærer dei seg, og til misgjerningi deira stend deira hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Men no skal det ganga med presten som folket. Eg skal straffa deim for deira ferd, og gjeva deim att for deira gjerd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Og eta skal dei og ikkje mettast, hora og ikkje meirast, av di dei hev slutta med å agta på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Horeliv og vin og mjød tek vitet burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Folket mitt spør stokken sin til råds, og hentar seg rettleiding av sin stav. For ei hordoms ånd hev villa deim, so dei med hor dreg seg burt ifrå sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Øvst uppå åsarne ofrar dei, og på kollarne brenner dei røykjelse, under eik og poppel og terebinta, av di skuggen der er god. So vert døtterne dykkar skjøkjor og sonekonorne dykkar horkonor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Likevel refsar eg ikkje døtterne dykkar for at dei er skjøkjor eller sonekonorne dykkar for at dei er horkonor. For mennerne sjølve løyner seg av med horkonor og ofrar med tempelskjøkjor. Soleis fer eit fåvitugt folk til sin undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Um no du Israel vil halda på med ditt horeliv, so må då ikkje Juda skuldbinda seg soleis. Kom då ikkje til Gilgal, og far ikkje upp til Bet-Aven, og sver ikkje: «So sant som Herren liver.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Um Israel stritar imot som ei balstyri ku, so skal Herren på hyrdingvis no føra deim som lamb på vidåtta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Bunden til avgudsbilæte er Efraim. So fær han då fara!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Drikkinga deira er måtelaus. Hegdelaust driv dei sitt horeliv. Skjoldarne hennar elskar det som skamlegt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Med eit stormver skal gripa deim med vengjerne sine, og dei skal verta til skammar med ofringarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Høyr dette, de prestar, og gjev gaum, du Israels hus, og du kongehus, legg øyra til! For dykk gjeld domen. For det hev vore ei snara åt Mispa, og eit utspila net på Tabor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Med ei offerslagting hev dei sokke berre djupare ned i villa. Men eg skal verta eit tukteris åt deim alle i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Eg kjenner Efraim, og Israel er ikkje løynt burt ifrå meg. For du Efraim hev drive hor, og Israel hev sulka seg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Gjerningarne deira let deim ikkje få venda um til deira Gud, av di dei hev ei hordoms ånd i bringa si, og Herren, honom kjenner dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Men Israels storlæte vitnar imot honom, og Israel og Efraim skal stupa for si misgjerning. Juda skal og falla med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Um dei fer av stad med sitt småfe og sitt storfe og skal søkja Herren, so finn dei honom ikkje. Han hev drege seg ifrå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Mot Herren hev dei vore utrue. For dei hev født born som ikkje er hans. Difor skal no ein nymåne eta deim upp med alt det dei eig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Blås i lur i Gibea, i trompet i Rama! Blås alarm i Bet-Aven! Etter deg, Benjamin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim skal øydast på refsingsdagen. Mot Israelsfylki varslar eg det visse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Juda hovdingar hev vorte liksom dei som flyt deilder. Yver deim skal eg ausa ut vreiden min som vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim vert nedkua, retten hans rana. For han hev teke på med å fara etter menneskjebod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Og eg - som mol er eg no for Efraim og som beinåt for Judas hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Og Efraim hev gått sjukdomen sin og Juda såret sitt. Difor hev Efraim fare til Assur og sendt bod til kong Jareb. Men han kann ikkje gjera dykk gode att, og såret dykkar vert ikkje lækt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'For eg, som ei løva er eg mot Efraim og som ei ungløva mot Juda hus. Og eg, ja eg riv sund og fer min veg med det, og ikkje finst den som kann berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Eg gjeng min veg attende til min stad, til dess dei hev lide det dei hev fortent, og so fer til å søkja mi åsyn. I si naud skal dei leita etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '«Kom, lat oss venda um til Herren! For det er han som hev såra, og han vil lækja oss. Han slo, men vil og fetla oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Han skal gjera oss livande um tvo dagar, den tridje dagen skal han reisa oss upp att, og me skal liva framfor hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'So lat oss læra å kjenna, ja, lat oss strida for å læra kjenna Herren! Han renn upp so visst som morgonroden. Og han kjem nedyver oss som regnet, som eit vårregn som væter jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Kva skal eg gjera med deg, Efraim? Kva skal eg gjera med deg, Juda? For kjærleiken dykkar er som ei morgonsky, liksom doggi som tidleg kverv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Difor hev eg gjeve hogg ved profetarne. Eg hev drepe deim med min munns ord, og domarane dine for ut som ljoset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'For eg hev hug til kjærleik og ikkje til slagtoffer, og til Guds-kunnskap meir enn til brennoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Men dei hev brote pakti som Adam. Der hev dei vore utrue mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead er ein by for illgjerningsmenner, full av blodfar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Og som ein røvarflokk som ligg på lur etter folk, er heile prestehopen; dei drep på vegen til Sikem. Ja, skamlaust fer dei åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'I Israels hus hev eg set gruvelege ting. Der driv Efraim på med hor, sulkar Israel seg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Ogso for deg, Juda, er tiletla ei skurdonn, når eg vender mitt folks lagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Når eg vil lækja Israel, då kjem misgjerningi åt Efraim og vondskapen åt Samaria til synes. For dei driv med fals, og tjuv bryt seg inn, og rekarfant plundrar på vegarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Og dei segjer ikkje med seg sjølve seg at eg minnast all deira vondskap. No er dei ringa inne av sine eigne gjerningar, dei er komne framfyre mi åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Med vondskapen sin fegnar dei kongen, og hovdingarne med lygnerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Alle i hop er dei horkarar. Dei likjest ein omn som bakaren hitar upp. Han held upp med eldingi frå di han knodar deigen til dess ho er syrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'På dagen åt kongen vår drikk hovdingarne seg sjuke på heit vin. Sjølv tek han spottarar i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Når dei med meinråderne sine hev elda hugen sin som ein omn, søv bakaren deira heile natti. Um morgonen brenn han som logande eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Alle i hop er dei heite som ein omn og brenner upp domarane sine. Alle kongarne deira fell, og det er ingen av deim som kallar på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim, med folki mengjer han seg. Efraim hev vorte som ei kaka som ikkje er vend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Framande hev tært upp krafti hans, og han skyner inkje. Um håret hans hev vorte gråsprengt, so skynar han inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Men Israels ovmod vitnar imot honom midt uppi syni. Dei vender ikkje um til Herren, sin Gud, og ikkje søkjer dei honom, tråss i alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efraim hev vorte som ei fåvis duva som inkje veit. Egyptarland ropar dei på, til Assur fer dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Men best som dei fer av stad, breider eg netet mitt utyver deim og dreg deim ned, liksom ein gjer med fuglarne i lufti. Eg skal tukta deim, som lyden deira alt hev høyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Usæle dei, at dei flaug ifrå meg! Øyding yver deim, av di dei hev svike meg! Og eg, utløysa deim vilde eg. Men dei, ljugartale hev dei fare med imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Og ikkje ropar dei til meg av hjarta; dei berre jamrar seg på sengjerne sine. For korn og druvesaft samlar dei seg, medan dei vender seg frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Det var eg som lærde deim upp, og som styrkte armarne deira. Men imot meg hev dei ilt i hugen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Dei vender um, men ikkje uppetter. Dei er liksom ein sviksam boge. Falla for sverd skal hovdingarne deira for si hatige tunga skuld. For det vert dei hædde i Egyptarlandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Til munnen din med luren! Som ein ørn yver Herrens hus! av di dei hev brote mi pakt og falle frå mi lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Dei ropar til meg: «Min Gud! Me, Israel, kjenner deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Men av di Israel hev støytt frå seg det som godt er, skal fienden elta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Dei, kongar valde seg som ikkje var ifrå meg. Hovdingar tok dei seg, og eg fekk ikkje vita um det. Av sylvet sitt og gullet sitt gjorde dei seg gudebilæte, so dei skulde verta utrudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Ufyseleg er kalven din, Samaria! Harmen min logar imot deim. Kor lenge skal det vara at dei ikkje kann tola reinleik?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'For frå Israel er kalven komen. Ein meister hev laga honom, og nokon gud er han ikkje. Difor skal Samariakalven smuldrast i smått.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'For vind sår dei, og storm skal dei hausta. Avling skal dei ikkje få, grøda skal ikkje gjeva føda, og um ho det gjer, skal framande eta det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Gløypt vert Israel. Millom folki er dei alt som ein verdlaus ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'For dei hev fare upp til Assur liksom eit villasen som gjeng sin eigen veg. Efraim tingar um elsk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Men kor so dei tingar millom folki, so skal no eg like vel klemba deim i hop og lata deim få ei låk tid under storkongens trælking.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Av di Efraim hev gjort seg so mange altar til synd, so skal og altari hans verta honom til synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Um eg skriv lover åt han i titusundtal, so reknar han deim berre som framande lover.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Til slagtoffergåvor åt meg ofrar dei kjøt som dei et - Herren hev ikkje hugnad i deim. No kjem han i hug misgjerningarne deira og heimsøkjer deira synder. Dei skal fara attende til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Og etter di Israel hev gløymt skaparen sin og bygt seg borgar, og Juda hev sett seg upp mange borgfaste byar, so skal eg senda eld mot byarne hans, og han skal øyda borgerne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Gled deg ikkje, Israel, med fagnad liksom folki, av di du hev drive på med hor og dermed kome burt ifrå din Gud, du som hev havt din hugnad i skjøkjeløn på alle korn-treskjarstader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Treskjestaden og vinpersa skal ikkje kunna næra deim, og druvesafti skal mislukkast for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ikkje skal dei få bu i Herrens land. Men Efraim skal attende til Egyptarland, og i Assur skal dei eta det som ureint er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Dei skal ikkje renna ut vin til drykkoffer for Herren, og ikkje skal slagtofferi deira vera hugsame for honom; som syrgjebrød for deim. Alle som et av det, skal verta ureine. For brødet sitt hev dei berre for seg sjølve, det kjem ikkje i Herrens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Kva skal de so gjera på helgedagen, på Herrens høgtidsdag?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'For de skal vita at um dei slepp undan avøydingi, so vert det Egyptarlandet som samlar deim, Mof som fær å jorda deim. Sylvet deira, det dyre, skal netlor eiga, tistel veksa i tjeldbuderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Dei kjem, heimsøkjingsdagarne, dei kjem, attergjeldsdagarne. Det fær nok Israel vita. Ein dåre er profeten, vitlaus er åndsmannen, for di store misgjerning skuld, og for din sterke fiendskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Ein lurar er Efraim imot min Gud. Profeten - fuglefangarsnara på alle hans vegar, fiendskap i gudshuset hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Djupt i used hev dei sokke som i Gibea-dagarne. Men han hugsar misgjerningi deira, han heimsøkjer deira synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Liksom druvor i villmarki fann eg Israel. Som frumsefrukt på fiketre i den fyrste bering såg eg federne dykkar. Men dei kom til Ba’al-Peor, og vigde seg til skjemdarguden, og dei vart til styggedom liksom han som dei elska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraim - som ein fugl skal herlegdomen hans fljuga burt. Ingen skal få born meir, ingen vera med barn, og ingen verta umhender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'For um dei el upp borni sine, so gjer eg deim barnlause, so det ikkje finst menneskje att. Ja, usæle er og dei sjølve når eg gjeng ifrå deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim, som eg ser honom alt burt til Tyrus, er planta på ein eng. Men Efraim skal verta nøydd til å føra borni sine ut til rettarmannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Gjev deim, Herre! Kva skal du gjeva deim? Gjev deim moderfang som føder i utid, og brjost som turkast upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'All deira vondskap er samla i Gilgal. Ja, der fekk eg hat til deim. For deira vonde åtferd skuld vil eg driva deim ut or mitt hus. Ikkje skal eg elska deim lenger. Alle deira førarar er upprørarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Stungen er Efraim, roti deira turka, frukt skal dei ikkje bera. Og um dei fær born, drep eg den dyre livsfrukti deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Min Gud skal støyta deim burt; for ikkje lydde deim på honom, og dei skal flakka heimlause ikring millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Eit rikt vintre er Israel og ber frukt. Men di meir frukt han fekk, di meir auka han talet altari sine. Di betre det gjekk for landet hans, di betre gjorde han minnesteinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Hjarto deira var falske, no skal dei få bøta. Han skal brjota ned altari deira og slå sund deira minnesteinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Ja, no skal dei segja: «Ingen konge hev me, for me hev ikkje ottast Herren. Og kongen, kva kann vel han gjera for oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Tala tome ord, sverja falskt, gjera semja! Og domen renn upp som beiskt ugras på åkerforerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'For kalven i Bet-Aven er Samaria-buarne ottefulle. Ja, folket hans syrgjer yver honom, og prestarne hans skjelv for honom, for herlegdomen hans, av di han er førd burt ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Han sjølv skal førast til Assur, ei gåva til kong Jareb. Skam skal Efraim henta seg, skjemmast skal Israel for rådgjerdi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Ute er det med Samaria-kongen, som ei treflis på vatnet rek han av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Øydast skal Avens offerhaugar, Israels synd. Torn og tistel skal renna upp på altari deira. Og dei skal segja til fjelli: «Gøym oss!» og til haugarne: «Velt dykk yver oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Radt ifrå Gibea-dagarne hev du synda, Israel! Der hev du stade. Skulde han ikkje nå deim i Gibea, krigen mot nidingarne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Når eg hev hug til det, tuktar eg deim. Og folki samlar seg imot deim og bind deim fast til tvifalds-syndi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Og Efraim er ei tamd kviga som likar å treskja. Og eg hev spart den fagre halsen hennar. No vil eg leggja oket på Efraim. Juda skal pløgja, Jakob skal horva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Så åt dykk som rettferd krev, hausta etter kjærleiks lov! Brjot dykk nybrot! For det er tid til å søkja Herren, so han kann koma og lata rettferd regna yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'De hev pløgt gudløysa, rettløysa hev de hausta. De hev ete lygjefrukt, med di du hev sett lit til vegen din, til mengdi av kjemporne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Med det reiser seg ein stridsdun millom fylki dine, og alle borgfesti dine skal falla, liksom Bet-Arbel vart lagt i øyde av Salman den stridsdagen då dei krasa både mor og barn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Slikt skal Betel føra yver dykk for dykkar store vondskap. Når morgonen rodar, er det ute, ute med Israels-kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Då Israel var ung, hadde eg honom kjær, og ut or Egyptarland kalla eg son min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Di meir dei kalla på deim, di meir gjekk dei burt ifrå deim. Åt Ba’alarne ofrer dei, åt bilæti brenner dei røykjelse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Og det var då eg som lærde Efraim å ganga, tok deim på armarne mine. Og ikkje skyna dei at eg lækte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Med menneskjesnorer drog eg deim, med kjærleiksband. Og eg var deim som dei som lettar oket yver kjakarne deira, og eg bøygde meg ned til honom og let honom få mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Han skal ikkje fara attende til Egyptarland; men Assur, han skal vera kongen hans, for dei vilde ikkje venda um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Og sverd skal rasa i byarne hans og brjota bommarne hans og eta ikring seg - for deira uråder skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Og folket mitt er huga på fråfall frå meg. Og um ein kallar deim til det høge, so er det ingen som lettar på seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Korleis skal eg nenna gjeva deg upp, Efraim? Korleis skal eg lata deg fara, Israel? Kann eg nenna gjeva deg upp som Adma, gjera med deg som med Sebojim? Hjarta mitt vrid seg i meg, all mi vårkunn vaknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Eg vil ikkje lata deg kjenna min brennande harm. Ikkje vil eg atter tyna Efraim. For Gud er eg og ikkje eit menneskje. Heilag er eg midt i deg, og med vreide vil eg ikkje koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Etter Herren skal dei då fylgja, som ei løva skal han bura. Ja, han skal bura, og bivrande skal born koma frå havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Bivrande skal dei koma som fuglar frå Egyptarland og som duvor frå Assurs land. Og eg vil lata deim bu i husi sine, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim hev ringa meg inn med lygn, og Israels hus med svik. Og Juda er alljamt agelaus imot Gud, mot den Heilage, den Trufaste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Efraim stundar etter vind, og jagtar etter austanver. All dagen aukar det på med lygn og vald. Samband med Assur gjer dei, og olje fører dei til Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Men Herren fører sak med Juda, og vil heimsøkja Jakob for åtferdi hans, betala honom etter gjerningarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'I morslivet heldt han bror sin i hælen, og i si manndomskraft drogst han med Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Ja, han drogst med engelen og vann, han gret og bad honom um nåde. I Betel fann han honom, og der tala han med oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Og Herren, allhers Gud - «Herren» er hans ærenamn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Og du, til din Gud skal du venda um. Hald fast på kjærleik og rett! Og bia stødt på din Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Kana’an, i handi hans er falsk vegt. Å gjera urett likar han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'So segjer og Efraim: «Eg hev då vorte rik, eg hev vunne meg midel. Kva eg so strævar med, so skal dei då ikkje finna hjå meg nokon urett som er synd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Men eg er Herren din Gud, alt ifrå Egyptarland, eg vil endå lata deg bu i tjeldbuder liksom i høgtidsdagarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Og eg hev tala til profetarne, og eg, syner i mengd hev late deim sjå, og gjenom profetarne hev eg tala i liknader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Er no Gilead eit illgjerdsreir, so skal dei verta berre fåfengd. Ofrar dei uksar i Gilgal, so skal og altari deira verta som steinrøysar innmed forerne på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Og Jakob rømde til Aramsletta, og Israel træla for ei kona - og for ei kona gjætte han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Men ved ein profet førde Herren Israel frå Egyptarland, og ved ein profet gjætte han honom. Sår harm hev Efraim valde. Difor skal Herren hans lata blodskuldi hans koma yver honom, og han skal venda hans skjemdarferd mot honom sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Når Efraim tala, vart dei fælne. Høg var han i Israel. Men han vart saka med Ba’al og døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Og no held dei på med si synd. Og dei gjer seg støypte bilæte av sylvet sitt, avgudar etter sitt eige vit, handverksarbeid alt saman. Til slike talar dei. Menneskjeslagtarar kysser kalvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Difor skal dei verta som morgonskyi, som doggi som tidleg kverv, liksom agner som vinden fyk burt ifrå treskjarstaden, og liksom røyk or ein ljore.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Men eg er Herren, din Gud, alt frå Egyptarland. Nokon annan Gud enn meg veit du ikkje av. Og nokon annan frelsar enn eg finst ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Det var eg som kjendest ved deg i øydemarki, i det turre landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Etter som beitet deira var, vart dei mette. Då dei var mette, vart dei høge i sin hug. Difor gløymde dei meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Då vart eg deim liksom ei løva. Som ein pantar lurer eg innmed vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Eg kjem yver deim som ei binna som dei hev teke ungarne ifrå, og riv sund bringa deira. Eg gløypar deim som ei løvemor. Villdyr skal slita deim sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Du hev tynt deg, Israel, med di du er imot meg, di hjelp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Kvar er no kongen din, at han kann syta for frelsing åt deg i alle byarne dine? Og kvar hev du domarane dine, som du sagde um: «Lat meg få konge og hovdingar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Ja, ein konge skal eg gjeva deg i min vreide, og so tek eg honom burt i min harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Samanbundi er misgjerningi hans Efraim, og syndi hans gøymd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Rider som hjå ei fødande kvinna skal koma yver honom. Han er ein son som ikkje er vis. For når stundi er der, kjem han ikkje fram i fødsli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Or helheims vald vil eg fria deim, frå dauden vil eg løysa deim ut. Kvar er di sott, du daude? Kvar er di tyning, du helheim? Anger er løynd for augo mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'For han, millom brørne sine stend han lavande av frukt; det kjem ein austanvind, eit Herrens ver, farande upp ifrå øydemarki. Då turkar brunnen hans upp, og kjelda hans tryt. Han ranar skatten, alle slag kostnadting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Bøta skal Samaria, av di det hev vore tråssugt imot sin Gud. For sverd skal dei falla, småborni deira skal verta krasa, og dei kvinnor som er med barn, skal ristast upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Vend um, du Israel, til Herren, din Gud! For med di misgjerning hev du ført deg i fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Tak med dykk ord, og vend um til Herren! Seg til honom: «Forlat all misgjerning og tak imot det som godt er, lat oss betala med uksar - med våre lippor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Assur skal ikkje frelsa oss. På hestar skal me ikkje rida. Og ikkje meir skal me segja: «Vår Gud!» til det som henderne våre hev gjort. For hjå deg er det at den faderlause fær miskunn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Ja, deira fråfall vil eg lækja. Eg vil elska deim av fri hug, av di vreiden min hev vendt seg ifrå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Eg skal vera som dogg for Israel. Bløma skal han som ei lilja, og røtast skal han som Libanon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Renningarne hans skal spreida seg, og skal vera som eit oljetre i fagerleik, og anga som Libanon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Dei som bur i skuggen hans, skal atter avla korn og bløma som vintreet. Minnet um honom skal vera som vin ifrå Libanon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Men du, Efraim! Kva skal eg med avgudarne meir? Eg bønhøyrer og ser til honom. Eg er som eit grønt cypresstre. Frå meg skal di frukt vera å finna. Den som er vis, han agte på dette, den som er vitug, merke seg det! For Herrens vegar er rette, og rettvise ferdast på deim, men illgjerdsmenner stuper på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Herrens ord som kom til Joel Petuelsson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Gjev gaum åt dette, de som gamle er. Og lyd på det kvar som bur i landet! Hev sovore hendt i dykkar tid, eller i dykkar fedra-tid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Fortel det til dykkar born, og dykkar born til sine born, og deira born til ei ætt som kjem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Det som gnagaren leivde, åt grashoppen upp. Det som grashoppen leivde, åt bitaren upp. Det som bitaren leivde, åt etaren upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Vakna, de drukne, og gråte, jamra, vindrikkarar alle! For druvesafti er rivi dykk frå munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Eit folk hev fare yver landet mitt, veldugt og utan tal, med tenner som løvetenner, dei jakslar som løvor hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Vintrei mine er tynte og fiketre brotne ned, dei hev flekt deim reint og hivt deim, det heng kvite greiner på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Klaga som ei møy som syrgjeklædd gjeng yver sin ungdoms brudgom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Grjon- og drykkoffer er kvorvne frå Herrens hus, prestarne syrgjer, Herrens tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Åkrar er øydde, jordi jamrar. For øydt er kornet, vinsafti magtlaus, oljen er kvorven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Bonden er magtstolen, vindyrkar rådlaus for kveite og bygg, grøda på marki er tynt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Vintre er mergstolne, fiketre folna. Granattre og palma og apall, alle tre hev turka burt. Ja, fagnaden er stolen frå mannaheim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Syrgjeklædde klage, de prestar! Jamra dykk, de som tener ved altaret! Gakk inn og vake syrgjeklædde, de min Guds tenarar! For burte frå dykkar Guds hus er grjon- og drykkoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Lys ut fasta og heilag samling, få dei gamle i hop, ja alle som bur i landet, til Herren, dykkar Guds hus! Til Herren de ropa må.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Å hå for ein dag! Nær er Herrens dag. Som vald ifrå Allvald han kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Strauk ikkje maten burt med me såg på, frå Guds hus gleda og frygd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Kornet turkar burt under jordskorpa. Tome er buri, lødorne øydest. Ja, kornet turkar burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Kor buskapen rautar! Rådlaus er kvar bøling; for ikkje beite dei finn, sauerne jamvel lyt bøta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Til deg, Herre, ropar eg. For elden han åt hamni på heidi, og logen leika i ved og i tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Jamvel dyri i marki etter deg mun stynja, for turre er bekkjefari. Og elden han åt hamni på heidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Lat luren ljoma på Sion! Skrik høgt på mitt heilage fjell! Skjelve, alle i mannaheimen! Koma skal Herrens dag, ja, han er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Ein dag med myrker og dimma, ein dag med skodda og sky, som ein morgongråe er eit tallaust folk breidt yver fjelli. Du liken aldri ser frå æva som var, og aldri i åri til komande ætter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Framfyre et elden upp; og etter kjem brennande logen. Som Edenshagen var landet framfyre og etterpå snaudaste heidi. Å berga noko nyttar ikkje her.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Som øykjer er dei å sjå til, som stridshestar tråvar dei fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Liksom glamrande vogner fer dei yver alle fjell. Det susar og brusar, som når eld sleikjer strå, som ei veldug herfylking samla til strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Støkken tek folk ved syni, alle andlit skiftar lit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Som kjempor rusar dei i veg, liksom stridsmenner stormar dei murar. Kvar ein på si leid sturtar fram, og aldri dei krøkjer sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Ingen trengjer den andre burt, kvar hev si eigi braut, tvert gjenom våpni, og ho brest ikkje rekkja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Inn i byen dei stormar, stig upp på muren, gjeng inn i husi, og inn gjenom vindaugo bryt dei seg som tjuvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Jordi fyre deim skjelv, himlarne bivrar, sol og måne dei svartnar, medan stjernorne løyner sin glans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Og Herren let høyra sitt mål framfyre si fylking, for ovstor er hans herlæger, veldug hans ærendsvein er. Ja, stor er Herrens dag og skræmeleg, kven held honom ut?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Men no og det gjeld, so mæler Herren, vend um til meg med heile dykkar hjarta, med fasta og gråt og med klaga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Riv sund dykkar hjarta og ei dykkar klæde, vend um til Herren dykkar Gud! For han er nådig og hugmild er han, hev tolugt sinn, er rik på miskunn, han angrar det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Ja, kven veit? Han snur og angrar, og han legg etter seg velsigning, grjon- og drykkoffer for Herren, dykkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Blås i luren på Sion, haldt fastehelg, lys heilag samling!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Samla folket! Vigsle lyden! Få i hop dei gamle, samla dei små, ja, borni på fanget! Brudgomen gange or sitt hus og bruri frå stova si!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Millom forhall og altar skal dei gråta prestarne, Herrens tenarar, og segja: «Spar, Herre, folket ditt, og ikkje du gjere din eigen lyd til eit spottord, til eit ordtak millom folki! Kvi skal dei segja millom folki: «Kvar er deira Gud?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Då gløddest Herren upp for sitt land, og han sparde sitt folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Herren svara og tala til sitt folk: Sjå, eg vil senda til dykk både korn og saft og olje, so de kann mettast av det. Og ikkje vil eg gjera dykk meir til spott millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Norderheren driv eg langt burt ifrå dykk. Eg skal støyta honom ut i eit turt og øyde land, hans fortropp til havet i aust, hans baktropp til havet i vest. Og vondt skal det dåma, ja ilt skal det tevja. For storverk hev han gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ikkje ottast, du land, men gled deg og ver sæl! For storverk hev Herren gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ikkje ottast, du fe på marki, for no grønast graset på heidi. Og trei ber frukt, fiketre, vintre gjev no si kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Og Sions søner, fagna og frygda dykk i Herren, dykkar Gud! For han gjev åt dykk læraren til rettferd; so sender han dykk haustregn og vårregn som fyrr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Og fyllast skal låvarne med korn, og persorne fløyma med vinsaft og olje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Og skadebot gjev eg for grøda som tyntest av grashoppen, bitaren, etaren, gnagaren, min store her, som eg sende imot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Og de skal få nøgdi eta og mettast. Og då skal de lova namnet åt Herren dykkar Gud, han som hev underleg stelt med dykk, og ikkje skal folket mitt æveleg skjemmast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Og de skal merka at eg bur midt i Israel, og at eg er Herren, dykkar Gud, og ingen annan, og ikkje skal folket mitt æveleg skjemmast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Og sidan henda det skal: Eg renner min ande yver alt kjøt. Dykkar søner og døtter skal tala profetord; dei gamle hjå dykk skal draumar drøyma, gutarne dykkar skal syner sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Ja, og yver trælar og trælekvende eg renner min ande i dagarne dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Under eg gjer på himmel og på jord, blod og eld og kvervlande røyk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Soli skal verta til myrker og månen til blod, fyrr han kjem, Herrens dag, den store og skræmelege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Men kvar ein som kallar på Herrens namn, bergast skal han. For på Sions fjell og i Jerusalem skal finnast ein flokk av frelste som Herren hev sagt, og til den utfria flokken høyrer dei som Herren kallar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'For sjå, i dei dagarne og det bilet, då eg vender lagnaden for Juda og Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'då vil eg samla alle folki og føra deim ned i Josafatsdalen og der halda dom yver deim for mitt folk og min eignalut Israel skuld, som dei spreidde millom folki, og mitt land hev dei bytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Um mitt folk drog dei strå, gav ein gut for ei skjøkja, og ei gjenta selde dei for vin, og so drakk dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Og kva vil det meg, Tyrus og Sidon og Filistar-bygder alle? Er det attergjeld mot meg det vil, eller vil de gjera meg eitkvart? Ovleg brått dykkar verk eg vender imot dykk sjølve,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'De som sylvet og gullet mitt tok, og eignaluter mine so fagre til dykkar tempel førde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Og Judas og Jerusalems søner de selde til Javans søner, til å førast so langt burt ifrå sitt land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Eg ropar deim fram att frå den staden der de hev selt deim. Dykkar verk eg vendar imot dykk sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Eg skal dykkar søner og døtter til Juda-sønerne selja; derifrå skal dei til sabæarane gå, eit folk so langt undan. For Herren hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Lat heidningar det høyra! Til herferd vigje dykk! Lat kjemporne koma! Gange fram! Stige fram alle herføre hausar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Smide plogarne til sverd og hage-knivarne til spjot! Vesaling segje: «Eg er kjempekar eg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Skunda dykk og kome, heidningar alle ikring! Samle dykk i hop! Dit late du, Herre, dine kjempor stiga ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Lat folki vakna og samlast i Josafatsdalen! For der eg domar sit yver alle folki ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Fram med sigden! No mognast kornet. Kome, trakke! No er persa full. Kjeraldi fløymer. Ovstor er vondska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Flokk på flokk i domsdalen. For Herrens dag er nær i domsdalen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Sol og måne dei svartnar, og stjernorne løyner sin glans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Og Herren burar frå Sion, frå Jerusalem gjallar hans mål. Og det bivrar både himmel og jord. Men Herren er ei livd for sitt folk og ei borg for Israels søner. Ja, kjenna skal de at eg er Herren, dykkar Gud, som bur på Sion, mitt heilage berg. Og Jerusalem skal ein heilagdom vera, frammandfolk der aldri meir stiga inn. Då skal på den dagen druvesafti drjupa av fjelli og mjølk frå haugarne strøyma, og alle bekkjer i Juda fløyma med vatn. Ei kjelda spring ut frå Herrens hus og vatnar Akaziedalen. Men Egypt skal øydeland verta, og Edom som ville heidi, for valdsverk mot Judas born. Dei hev øydt skuldlaust blod i sitt land. Men Juda skal sitja æveleg trygt, og Jerusalem frå ætt til ætt. Og eg vil hemner deira blod, som eg ikkje hemnde fyrr. Og Herren skal bu på Sion.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Ord av Amos, ein av hyrdingarne frå Tekoa, som han såg i sine syner um Israel i dei dagarne då Uzzia var konge i Juda og Jeroboam Joasson konge i Israel, tvo år fyre jordskjelven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Han sagde: Herren burar frå Sion, frå Jerusalem gjallar hans mål. Då sturer dei hyrding-lider, og Karmels hovud vert svidd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So segjer Herren: For trifald misgjerd av Damask og for firfald eg ikkje meg attrar. For di dei Gilead treskte med sledar av jarn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'so sender eg eld mot Hazaels hus, han skal øyda Benhadads borger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'So bryt eg bommen til Damask og tyner Bikat-Avens folk og kongsstavmannen i Bet-Eden, og Aram skal drivast burt til Kir, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So segjer Herren: For trifald misgjerning av Gaza og for firfald eg ikkje meg attrar. For di dei heile grender dreiv ut og gav deim i Edoms vald,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'So sender eg eld mot Gazas mur, han skal øyda deira borger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'so tyner eg Asdods folk og Askalons kongsstavs-mann. Mot Ekron eg retter mi hand, slær filistarn’ til siste mann, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'So segjer Herren: For trifald misgjerd av Tyrus, for firfald eg ikkje meg attrar. For di heile grender til Edom dei dreiv og ikkje på brødrabandet gav gaum,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'so sender eg eld mot Tyrus-muren, han skal øyda deira borgar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'So segjer Herren: For trifald misgjerd av Edom, for firfald eg ikkje meg attrar. For di han elte bror sin med sverd og kjøvde sin samhug, men vreiden jamt i han øydde, og han æveleg gøymde sin harm,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'so sender eg eld imot Teman, han skal øyda Bosras borger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So segjer Herren: For trifald misgjerd av Ammons-borni og for firfald eg ikkje meg attrar. For di dei i Gilead konor med barn skar upp, då dei vilde auka sitt land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'So kveikjer eg eld i Rabbas mur, han skal øyda deira borger, medan herropet dunar i striden, og eit hardver på stormdagen blæs,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'og i landlysing kongen skal gå, han sjølv med hovdingarn’ saman, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So segjer Herren: For trifald misgjerd av Moab, for firfald eg ikkje meg attrar. For di dei brende beini åt Edom-kongen til kalk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'so sender eg eld imot Moab, han skal øyda Kerijots borgar. Og i ståket Moab skal døy, med hergny og luraljod skrell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Domaren deira eg tynar, alle hovdingarn’ likeins eg drep, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So segjer Herren: For trifald misgjerd av Juda, for firfald eg ikkje meg attrar. Då dei vanvyrde Herrens lov og heldt ikkje bodordi hans, men let seg av lygn-gudar dåra, som federne fyrr hadde fylgt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'so sender eg eld imot Juda, han skal øyda Jerusalems borger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So segjer Herren: For trifald misgjerd av Israel og for firfald eg ikkje meg attrar. For sylv dei sel ein skuldlaus og ein arming for eit par skor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'dei som helst ser mold på ein stakkars hovud, og rengjer småfolks rett. Til same gjenta gjeng far og son til vanhelging for mitt heilage namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Og på pantsette klæde ved kvart eit altar dei ligg, og skadebots-vin dei drikk i huset til sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Det var då eg som dreiv amoritarne frå deim, som høge som cedertre var, og sterke som eiker, men eg tynte alda i topp og roti i jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Det var eg som dykk førde frå Egyptarland og dykk leidde i villmarki fram gjenom fyrti år til å vinna Amorit-landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Eg vekte profetar av dykkar søner, naziræarar bland dykkar ungdomar. Er det’kje so, de Israels-born? Segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Men de gav naziræaran’ vin, og baud profetarn’ og sagde: «Profetera ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Sjå no skal eg lata det dynja under dykk som under ei full-lest kornvogn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Og den rappe kjem ingen stad av, og den sterke fær’kje bruka si magt, og kjempa skal’kje berga sitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Mannen med bogen er magtlaus, og lett på fot kann’kje berga seg, og mannen på hest skal’kje berga sitt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Hugdjervaste kjempa ho lyt naken røma på dagen den, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Høyre dette ordet som Herren hev tala imot dykk, de Israels søner, mot heile den ætti som eg hev ført upp frå Egyptarland:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Dykk einast kannast ved av alle ætter på jordi. Difor eg heimsøkjer dykk for alt det vonde de hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Gjeng tvo-eine saman tru, utan dei samstelte vart?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Tru løva burar i skogen utan eit rov det gjeld? Let ungløva høyra sitt mål, når i hola ho ligg, utan ho fengdi fekk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Tru fuglen i snara på jordi fell, utan at snara er uppsett? Tru vel at glefsa sprett att, utan at noko sit fast?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Eller ljomar luren i by, utan at folket fær støkk? Eller hender ulukka i by, utan at Herren hev gjort det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'For ikkje gjer Herren, Herren nokon ting, utan han tenarom sine, profetom, forkynner si løynråd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Når løva mun bura, kven må ikkje ræddast? Når han talar Herren, Herren, kven vert ikkje då profet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Rope ut yver Asdod borger og yver borger i Egyptarland: «Dykk samle på Samariafjelli og sjå kor fælt eit ståk der er, og valdsverk som der råder!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Dei hev ikkje vit på framferd rett, segjer Herren, dei som haugar valdsverk og tjon i borgerne sine i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Difor, so segjer Herren, Herren: Fiendar herset ditt land. Di magt skal støytast i knas, dine borger plundrast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So segjer Herren: Som hyrdingen friar frå løvegap eit par bein ell’ ein øyrelapp, so bergast dei skal, dei Israels-søner, som i Samaria sit i sofa-krå, på putebenk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Høyr og vitna mot Jakobs hus! segjer Herren, Herren, allhers Gud:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Den dagen eg straffar Israel brot, då straffar eg Betels altar, og altarhorni vert hogne, og dei skal falla til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Eg vinterstova hogg ned, sumarstova med. Filsbeinssalar skal falla, og mange hus skal verta øydde, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Det skal høyra på dette ordet, de Basans kyr, som er på Samariafjellet, de som piner dei små og dei arme mun slå, som segjer til dykkar herrar: «Lat oss få so me kann drikka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Herren, Herren, svor ved sin heilagdom: Sjå, dagar det koma skal yver dykk då med hakar dei hentar dykk fram og resten med krokar dreg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Gjenom sprunger i muren fer det, ei um senn, og kastar gudarne burt, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Kom til Betel og gjer synd, til Gilgal og synda enn meir; kvar morgon slagtoffer ber fram, kvar tridje dagen tiend,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Til takkoffer syra brød brenn, lys ut at de fri-offer gjer. For slikt mun de lika, de Israels born, segjer Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Det var eg som let dykk i kvar ein by vanta maten i munn, brødløysa gav eg i kvar ein heim. Og De vende’kje um til meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Det var eg som heldt regnet attende tri månader fyre skurden. Eg gav regn til den eine byen, den andre byen fekk ingen ting. Den eine åkren fekk regn, og den åkren som ikkje fekk regn, han turka burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Og tvo, tri byar gjekk til ein by til ein vatsdrykk å få, og dei fekk ikkje nok. Men de vende’kje um til meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Kornet eg slo med sotbrand og rust, og hagarne mange og vinbergi og fike- og oljetrei. Deim åt grashoppen upp. Men de vende’kje um til meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Eg sende sotti på dykk liksom i Egypt. Eg drap dykkar gutar med sverd. Hestarn’ vart herfang. Eg let dykk illtev frå valen i nasarne få. Men de vende’kje um til meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Eg gjorde ein omstøyt ibland dykk, som då Gud støytte ned Sodoma og Gomorra. Og de vart som ein brand berga or eld. Men de vende’kje um til meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Difor gjer eg med deg, Israel, so. Sidan eg gjerne vil gjera so med deg, bu deg til å møta din Gud, Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'For sjå: Han som lagar fjelli og skaper vinden, og ein mann sine tankar fortel, og myrker bryt til morgonljos, han som stig på jordheims haugar - Herren, allhers drott, er namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Høyr dette ordet som eg syng yver dykk, ein syrgjesong yver Israels hus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, '«Ho falli er, ris aldri upp meir, den møy Israel; slengd til jord i sit eige land. Ingen reiser ho upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'For so segjer Herren, Herren: Ein by sender tusund ut, fær hundrad att, sender ho hundrad ut, fær tie att til Israels hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'For so segjer Herren til Israels hus: Søk meg, so skal de liva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Men aldri de søkje til Betel, til Gilgal aldri kom, og gakk ikkje til Be’erseba! For Gilgal burt skal førast, og Betel vert upp i tjon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Søk Herren, so skal de liva! Elles kjem han som eld yver Josefs hus; det brenn, og ingen sløkkjer for Betel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'De som vender retten til malurt, og kastar rettferd til jord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Han som skapte Sjustjerna og Orion, og gjer kolmyrkret til morgon, gjer dagen til svarte natt, han som kallar på vatnet i havet og auser det ut yver jordi - Herren er hans namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Han øyder dei sterke med sitt ljon, han øyder borgi den faste!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Dei hatar den som refser for retten, styggjest ved den som talar sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Difor, då småfolk de trakkar ned og kornleiga driv av deim ut - vel hev de hogt stein og bygt hus, men de skal ikkje sjølv der bu. De hev fagre vinhagar stelt, men de skal ikkje drikka deira vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'For eg veit um synderne dykkar so mange og misgjerder utan tal; de trykkjer den skuldlause, tek imot mutor, ein arming for retten de svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Difor tegjer den kloke i denne tid, for ei vond tid er det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Legg vinn på godt og ikkje på vondt, so de kann liva. Då vera med dykk Herren, allhers Gud, som de hev sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hata vondt og elska godt, haldt retten uppe på tinget! Kann henda Herren, allhers Gud, då er nådig mot Josefs leivning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Difor, so segjer Herren, allhers Gud, Herren: Det er liksong på alle torg, og på alle gator dei ropar: «Ai, ai!» Bonden dei bed til gravøl, og til liksong deim som kann kveda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Frå kvar vinhage liksongar stig; for eg vil millom dykk ganga, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Ai dykk som trår etter Herrens dag! Kva er han for dykk, Herrens dag? Han er myrker og ikkje ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Som når du undan ei løva spring og møter ein bjørn, du kjem heim og styd handi mot veggen, og so bit deg ein orm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Ja, ja, myrker er Herrens dag og ikkje ljos, dimleitt, han hev ingen glans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Eg hatar og vanvyrder dykkar høgtider, eg hev ingen hugnad i dykkar stemnor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'ja, um de meg brennoffer gjev og grjonoffer, det hugar ikkje meg. Eg gjev ikkje på gjødkalve-offer gaum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Lat meg vera i fred for din buldrande song, ditt harpespel lyder eg’kje på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Men lat rett velta fram som vatn, og rettferd som rennande bekk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Bar De slagtoffer, grjonoffer til meg dei fyrti åri i øydemarki, du Israels hus?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Og bar det då Sukkot, dykkar konge, og Kijun, dykkar bilæte, dykkar gudestjerna, som de hadde gjort dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Eg vil føra dykk av burtanfor Damaskus, segjer han som heiter Herren, allhers Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Ai dykk som sit trygge på Sion, utan sut på Samarias berg, dei fremste i det gjævaste folk, som fær vitjing av Israels hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Drag burt til Kalne og sjå, og endå lenger, til Stor-Hamat fram, og stig ned til Gat i Filistarland! Er dei betre enn desse riki? Er deira land større enn dykkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'De som vond-dagen set på dør og valdsmannen sessar på stol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'På filsbeins-sæte dei ligg, og late på pallen dei heng. Av fenaden lambi dei et, og gjødkalv-bingen gjev steik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Dei sullar til harpe-slått liksom David dei lagar seg spel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Av bollar drikk dei vin, og med dyraste olje seg salvar, dei sturar ikkje for Josefs skade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Difor skal desse vera fremst i den landlyste flokken, og letings-sullen vert slutt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Herren, Herren hev svore ved seg sjølv, segjer Herren, allhers Gud: Jakobs høgferd mislikar eg, eg hatar hans slott, og by og bol gjev eg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Og um det so berre var tie mann att i eitt einaste hus, dei skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Og frenden og brennaren kjem til å bera beini or huset. Spør han so den som er inst inni huset: «Er det nokon att hjå deg?» Han svarar: «Nei,» so segjer han: «Hyss!» For ikkje må nemnast Herrens namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'For sjå, Herren byd: det store huset skal skakast i knas, og det vesle til dess at det brest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Tru hestarne spring i brattberg ikring, tru uksen på sjøen dreg plogen, sidan de til forgift brigdar retten og vender rettferd til malurt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'I heimløyser hev dei si frygd, dei kved: «Var me ikkje hæve, at me hev vunne oss velde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'For sjå, eg reiser imot dykk, Israels hus, eit folk, segjer Herren, allhers Gud. Og det skal dykk slå, frå Hamats grensa til øydemarks å.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Soleis let Herren, Herren meg sjå: Det var ein som skapa grashoppar då håi for til og spratt, det var håi etter kongens slått.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Og då dei var ferdige reint med å eta upp grøda i landet, då sagde eg: «Herre, Herre, tilgjev! Kor gjeng det no med Jakob som liten er?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Då angra Herren det. «Det skal ikkje henda,» sagde Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Soleis let Herren, Herren, meg sjå: Til straffar kalla han elden fram, Herren, Herren, og han åt det store djupet han nærpå åt åkerlandet med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Då sagde eg: «Herre, Herre, haldt upp! Kor gjeng det med Jakob som liten er?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Då angra Herren det. «Ikkje dette heller skal henda», sagde Herren, Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Soleis let han meg sjå: Eg såg Herren standa på ein loddmur med blylodd i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Og Herren sagde til meg: «Kva er det, Amos, du ser?» Og eg svara: «Eit blylodd.» Og Herren sagde: «Ja, eg skal loddet bruka millom mitt folk Israel. Ikkje vil eg meir spara det no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Isaks haugar skal tynast, og Israels heilagdomar herjast, mot Jeroboams hus eg ris upp med sverd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Men Amasja, presten i Betel, sende bod til Jeroboam, Israels-kongen, med sovorne ord: «Amos emnar på uppreist imot deg midt i Israels hus. Landet kann ikkje greida all røda hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'For soleis talar Amos: «Jeroboam skal døy for sverd, og Israel førast burt frå sitt land.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Og Amasja sagde til Amos: «Du sjåar, burt med deg! Far din veg til Judalandet! Der kann du tena ditt brød, og der kann du vera profet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'I Betel skal du ikkje driva lenger som profet, for det er kongeleg heilagdom og rikstempel her.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Då svara Amos Amasja so: «Ikkje er eg profet, og ikkje profetsvein, ein hyrding er eg, og steller med morbærtre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Men Herren tok meg burt frå hjordi, og Herren sagde til meg: «Gakk og ver profet for mitt folk Israel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Og no skal du høyra ordet frå Herren. So segjer du: «Ver ikkje profet for Israel. Og ikkje du preike mot Isaks hus!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Difor so talar Herren: Di kona vert skjøkja i byen, dine søner og døtter skal falla for sverd, med mælesnor vert gjordet ditt bytt, du sjølv i eit ureint land skal døy, og Israel førast burt frå sitt land.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Soleis let Herren, Herren meg sjå: Der stod ei korg med mogi frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Og han sagde: «Kva er det du ser, Amos?» Eg svara: «Ei korg med mogi frukt.» Og Herren sagde: «Haust-moge er mitt folk Israel. Eg vil’kje bera yver med det meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Og slotts-songarn’ yling vert på dagen den,» segjer Herren, Herren. Lik er i mengd kvar ein stad stilt slengde av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Høyr dette, de som snikjer etter fatigmann, de som tynar småfolk i landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'De som segjer: «Når er nymåne-helgi slutt, so me kann få kornet vårt selja, og sabbaten, so me inn i kornburet slepp og kann minka vårt mål og auka vår pris og driva fusk med vegti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Og armingen kjøpa for gull og stakaren for eit par skor, og so lata deim lettkornet få?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Ved Jakobs byrgskap Herren svor: Aldri skal alt dykkar verk verta gløymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Skulde’kje for slikt då skjelva jordi og heile mannheimen syrgja, og reint gå i flaum som Nilen, stiga og falla som Egyptarelvi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Og det hender på dagen den, segjer Herren, Herren, ved høgstdags bil let eg sol gå ned, og jordi skal myrkna på ljosan dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Dykkar helgar eg vendar til sorg, alle visor til syrgjesongar. Og sekk eg sveipar um kvar ei lend, gjer fleinskallut kvar ein haus, veld sorg som for einaste barn, gjer enden til ein uheils dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Sjå, dagar det koma skal, segjer Herren, Herren, då eg sender hunger i landet, ikkje hunger etter brød, ikkje torste etter vatn, men etter å høyra Herrens ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Og dei fer ifrå hav til hav, og dei sviv ifrå nord til aust, og dei leitar etter Herrens ord, men dei finn det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'På den dagen skal fagre møyar og unge menn av torsten tynast,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Dei som sver ved Samarias synd, og som segjer: «So sant din Gud liver, Dan, og so sant Be’ersebas vis liver.» Dei sig ned og ris aldri upp meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Ved alteret såg eg at Herren stod. Han sagde: Støyt til stolpen, so gåtterne skrell, lat det ramla nedyver kvar ein haus. Eg let deim som att er falla for sverd, ingen skal koma seg av, berga seg skal ikkje ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Bryt dei seg inn i helheim, mi hand tek deim derifrå ut, stig dei til himmelen upp, derifrå driv eg deim ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Um dei gøymer seg burt på Karmels topp, eg finn deim og hentar deim heim. Um frå augo mine dei løyner seg av på havsens botn, derifrå byd eg ormen fram, og han skal deim bita.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Um dei ver burtførde fangar under fiendehand, der skal eg bjoda sverd at det skal deim slå og augo mitt på deim skal sjå ilt og aldri mildt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Herren, Allhers-Herren, han rører jordi so ho brånar, og heile mannheimen syrgjer, når all jordi stig som Nilen og fell som Egyptarelvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Han hev i himlom sine høgsalar bygt, yver jordi reist sin kvelv. Han kallar vatnet or hav og auser det ned yver jord. Herren er hans namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Er de meir for meg enn kusitarne, de Israels born? segjer Herren. Hev eg ikkje ført Israel frå Egypt, filistaran’ frå Kaftor, og syraran’ frå Kir?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Sjå augo til Herren, Herren ser ned på dette syndsens rike: Eg øyder deim burt frå mannaheim; men ikkje heilt eg øydar Jakobs hus, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'For sjå, eg sender ut bod: Eg Israels hus millom folki skjek, liksom du ristar eit såld, og ikkje eit korn på bakken fell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Men for sverd skal døy kvar syndarar i mitt folk som kved: «Aldri oss skal ulukka koma og slå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'På dagen den vil eg reisa upp att Davids nedfalne hytta og sprungorne tetta og att-stødor lyfta, byggja upp som i fordoms tid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'for at dei skal erva det som av Edom er att, og alle dei folk som kallast med mitt namn, segjer Herren som fullfører dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Ja, dagar dei koma skal, segjer Herren, då pløgjaren skurdmannen når; den som vindruvor tred, ser mannen som sår, på fjellom dryp det med saft, etter bakkom bekkjerne renn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Og eg lagnaden snur for mitt folk Israel. Dei skal øydegardar byggja og bu der sjølv, dei skal vinberg planta og drikka deira vin, de skal stella seg hagar og eta deira frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Eg let deim bu i sitt land, og dei skal ikkje meir rivast upp frå sin heim, som eg deim gav, segjer Herren, din Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Syni hans Obadja. So segjer Herren, Herren til Edom: Fretnad hev me fengje frå Herren, og bod er bore ut millom folki: «Kom! Lat oss fara til strid imot det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Ja, liten gjer eg deg millom folki, og ovleg vanvyrd vert du.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Ditt hjartans ovmod hev dåra deg, du som i bergrivor byggjar, og bur i den høge heimen og segjer i ditt hjarta: «Kven kastar meg ned?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Um du enn byggjer høgt som ørnen, og reiret ditt ligg millom stjernorne, eg kastar deg ned derifrå, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Um tjuvar kom til deg eller ransmenn um natti - kor du vert reint til inkjes! - Vilde dei’kje stela det dei trong? Og kom dei og hausta ditt vinberg, vilde dei’kje leiva etter seg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Å, kor dei ransakar Esau, kor dei granskar hans skattar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Radt til landskilet driv dei deg alle dine sambandsbrøder; dei svik deg og vinn på deg dine gode vener. I staden for brød legg dei snara for deg som ikkje hev vit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Skal eg ikkje den dagen, segjer Herren, øyda ut dei vise or Edom, og vitet or Esaufjelli?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Dei fæler kjemporne, Teman, so kvar mann or Esaufjelli vert utrudd og drepen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'For vald imot Jakob, bror din, skal du sveipast i skjemsla, ja, øydast til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Den dagen du stod der og såg på, då framande rana hans eiga, og utlendingar kom i hans port og kasta lut um Jerusalem, då var du og som ein av dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Sjå ikkje med hugnad på bror din’s dag, på hans motgangsdag, og gled deg ei yver Juda-borni, på øydingsdagen, og bruk ikkje bause ord på trengsledagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Drag ikkje inn igjenom mitt folks port på uferdsdagen! Sjå ikkje du og med lyst på hans naud på uferdsdagen! Rett ikkje handi etter hans eiga på uferdsdagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Og ikkje du stande ved vegemot til å rydja ut deim som rømar! Og fli ikkje ut deim som bergar seg på trengsledagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'For Herrens dag er nær yver alle folki. Som du hev gjort, skal det gjerast med deg, di åtferd kjem att yver hovudet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Som de hev drukke på mitt heilage fjell, skal alle folki drikka stødt, ja, drikka og slurpa og verta som aldri dei vore til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Men på Sionsfjellet skal det vera ein flokk av frelste, og det skal vera ein heilagdom, og Jakobs hus skal få att si odelseiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Og Jakobs hus vert eld og Josefs hus ein loge, og Esaus hus vert til halm og eld set dei på det og øyder det ut, og ingen vert att av Esaus hus, for Herren hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Og Sudlands-folket skal taka Esaufjellet og Låglands-folket filistarane, dei skal taka Efraims-bygdi og Samaria-bygdi, og Benjamin skal taka Gilead.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Og dei burtførte av denne fylking av Israels-borni skal taka det som finst av kananitar alt til Sarefat, og dei burtførde frå Jerusalem som er i Sefarad, skal taka Sudlands-byarne i eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Og frelsarar skal draga upp på Sionsfjellet og døma Esaufjellet, og kongsveldet skal høyra Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Herrens ord kom til Jona, son åt Amittai; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '«Statt upp og gakk til den store byen Nineve, og ropa ut yver honom at vondskapen hans er stigen upp for mi åsyn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Men Jona stod upp og vilde fly til Tarsis, burt frå Herrens åsyn; og han for ned til Joppe, og fann eit skip som skulde ganga til Tarsis, og han betala ferdapengarne og gjekk um bord og vilde fara med til Tarsis, burt frå Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Men Herren sende ein sterk vind ut yver havet, og reiste slik ein storm på havet at skipet so nær hadde gjenge under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Då vart skipsfolki rædde og ropa kvar til sin gud; og til å letta skipet kasta dei på sjøen alt tarvende som fanst um bord. Men Jona hadde gjenge ned i skipsromet; der låg han og sov fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Då gjekk skiperen til honom og sagde: «Korleis kann du sova so fast? Statt upp og ropa til guden din! Kann henda vil den guden tenkja på oss, so me ikkje gjeng under.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Og dei sagde til kvarandre: «Kom, lat oss kasta lut, so me fær vita kven som er skuld i at denne ulukka er komi yver oss!» So kasta dei lut, og luten fall på Jona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Då sagde dei til honom: «Seg kven som er skuld i at denne naudi er komi yver oss! Kva er di ærend, kvar kjem du ifrå? Kva land er du frå, og kva folk er du av?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Han svara deim: «Hebræar er eg, Herren, himmelens Gud, ottast eg, han som hev skapt havet og det turre land.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Då vart mennerne ovleg rædde, og dei sagde til honom: «Kor kunde du gjera dette?» For dei skyna av det han fortalde deim at han flydde frå Herrens åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Og dei sagde til han: «Kva skal me gjera med deg, so havet kann leggja seg for oss?» For det vart meir og meir upprørt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Han svara: «Tak meg og kasta meg i havet! so skal det stilna for dykk. For eg veit det er for mi skuld denne store stormen er komen yver dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Mennerne freista no å ro tilbake til lands, men dei magta det ikkje; for sjøen bar meir og meir imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Då ropa dei til Herren og sagde: «Å Herre, lat oss ikkje ganga under, for di denne mannen skal døy, og lat ikkje skuldlaust blod koma yver oss! for du, Herre, hev gjort som du vilde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Og dei tok Jona og kasta honom i havet, og straks heldt havet upp å rasa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Då fekk mennerne fekk stor age for Herren, og dei ofra slagtoffer til honom og gjorde lovnader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Men Herren sende ein stor fisk, som gløypte Jona; og Jona var i buken åt fisken i tri dagar og tri næter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Og Jona bad til Herren, sin Gud, frå buken åt fisken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'han sagde: «Eg ropa til Herren i mi naud, og han svara meg. Frå helheims buk ropa eg, og du høyrde mi røyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Du kasta meg i djupet, midt i havet, og straumar kringsette meg, alle dine bylgjor og brot gjekk yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Eg tenkte då: «Burt frå dine augo er eg støytt. Like vel, ditt heilage tempel skal eg atter få sjå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Vatni kringa seg um meg like til sjæli. Djupet kringsette meg; tang sveipte seg um hovudet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Like til bergbotnarne sokk eg ned. Slåerne til jordi stengdest bak meg for alltid. Men du førde mitt liv upp or gravi, Herre, min Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Då mi sjæl ormegtast i meg, kom eg Herren i hug, og mi bøn kom til deg i ditt heilage tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Dei som tek vare på tome avgudar, gjeng frå si miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Men med lovsongs tonar vil eg ofra til deg, det eg lova, vil eg halda. Hjå Herren er frelsa!» Då baud Herren fisken, og han spydde Jona upp på land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Då kom Herrens ord til Jonas andre gongen; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '«Statt upp og gakk til Nineve, den store byen, og ropa ut yver honom dei ordi eg vil tala til deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Og Jona stod upp og gjekk til Nineve, som Herren hadde sagt. Nineve var ein stor by for Gud, tri dagsleider lang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Og Jona gjekk ei dagslei inn i byen og ropa og sagde: «Um fyrti dagar skal Nineve verta lagd i grus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Då trudde ninevitarne på Gud, lyste ut ei fasta og klædde seg i sekk både store og små.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Då saki kom for kongen i Nineve, reiste han seg frå sin kongsstol, lagde kappa av seg og sveipte seg i sekk og sette seg i oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Han let ropa ut i Nineve og segja: «Etter bod frå kongen og hans stormenner må korkje menneskje eller dyr, storfe eller småfe, smaka noko, beita eller drikka vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Men dei skal sveipa seg i sekk, menneski med dyri, og ropa til Gud av all kraft og umvenda seg, kvar frå sin vonde veg og frå den urett som er i deira hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kven veit? Gud kunde då venda um og angra det, venda um frå den brennande vreide sin, so me ikkje gjeng under.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Då no Gud såg det dei gjorde, at dei vende um frå sin vonde veg, angra han det vonde han hadde sagt han vilde gjera mot deim, og han gjorde det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Dette gjorde Jona ovleg vondt, og han vart brennande harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Han bad då til Herren og sagde: «Å Herre, var det ikkje dette eg tenkte, då eg endå var i mitt land? Difor flydde eg so snøgt til Tarsis; for eg visste du er ein nådig og miskunnsam Gud, langmodig og rik på miskunn, og angrar det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'So tak no, Herre, livet mitt ifrå meg! For eg vil heller døy enn liva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Då sagde Herren: «Hev du grunn til å harmast?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Og Jona gjekk ut or byen og sette seg austanfor byen. Der gjorde han seg ei hytta og sette seg der i skuggen, og vilde sjå korleis det gjekk med byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Då let Herren Gud ein kikajon veksa upp yver Jona, til å skyggja yver hovudet hans og fria honom ifrå hans mismod; og Jona fann stor gleda i kikajonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Men næste dag, då morgonroden rann, sende Gud ein makk, som stakk kikajonen so han visna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Då soli rann, sende Gud ein brennande austanvind, og soli stakk Jona på hovudet so han ormegtast. Han ynskte då å få døy og sagde: «Eg vil heller døy enn liva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Men Gud sagde til Jona: «Hev du grunn til å harmast for kikajonen skuld?» Han svara: «Eg hev grunn til å harmast til dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Då sagde Herren: «Du ynkast yver kikajonen, som du ikkje hev havt møda med og ikkje hev ale upp, som kom til på ei natt og gjekk til grunns etter ei natt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'og so skulde ikkje eg ynkast yver Nineve, den store byen, der det finst meir enn eit hundrad og tjuge tusund menneskje som ikkje kann skilja millom høgre og vinstre, og mange dyr!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Herrens ord, som kom til Mika frå Moreset i dei dagarne då Jotam og Ahaz og Hizkia var kongar i Juda, det som han såg um Samaria og Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Høyr, de folk, alle i hop! Lyd etter, du jord og alle som på deg bur! No vil Herren, Herren vitna imot dykk, Herren frå sitt heilage tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'For sjå, Herren gjeng ut frå bustaden sin; han stig ned og trøder på haugarne på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Og fjelli brånar under føterne hans, og dalarne rivnar - som vokset for elden, som vatnet når det støyper seg utfyre ein hamar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Og alt dette fær me for Jakobs fråfall, for dei synder som Israels hus hev gjort. Kven er so skuld i Jakobs fråfall? Er det ikkje Samaria? Og kven er skuld i Judas offerhaugar? Er det ikkje Jerusalem?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'So vil eg då gjera Samaria til ei steinrøys på marki, til ein vinplantingsstad. Eg vil velta steinarne hennar ned i dalen og leggja grunnvollarne hennar berre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Alle dei utskorne bilæti hennar vil eg krasa; alle horegåvorne hennar vil eg brenna upp med eld; og alle gudebilæti hennar vil eg øyda; for av horeløn hev ho samla deim i hop, og til horeløn skal dei atter verta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'For dette vil eg øya og jamra, vil eg ganga berrføtt og naken ikring; eg vil øya som sjakalarne og gjeva syrgjelåt som strussarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'For såri hennar let seg ikkje lækja, for det kjem radt til Juda, det når til porten åt folket mitt, radt til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Kunngjer det ikkje i Gat! Gråt ikkje so sårt! I Bet-Leafra velter eg meg i moldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Burt med dykk, de som bur i Sjafir, nækte og skjemde! Folket i Sa’anan vågar seg ikkje ut. Jamringi i Bet-ha-Esel gjer det rådlaust for dykk å stogga der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'For dei som bur i Marot, lengtar etter lukka; for ulukka hev fare ned frå Herren til porten i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Beit tråvaren for vogni, de som bur i Lakis! de var upphavet til syndi for dotteri Sions; for hjå dykk vart Israels fråfall fyrst funne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Difor lyt du gjeva Moreset-Gat skilsmålsbrev. Husi i Akzib vert ein svikal bekk for Israels kongar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Endå ein gong let eg landvinnaren koma yver dykk som bur i de Maresa. Radt til Adullam skal Israels herlegdom koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Raka deg og klypp deg, i sorg yver kjæleborni dine! Gjer deg snaud til gagns som gribben; for dei vert førde burt ifrå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Usæle dei som tenkjer ut urett og fyrebur vondt, med dei ligg på lega si. Straks det lyser av dag, set dei det i verk! for di det stend i deira magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Og dei lystar etter annan manns åkrar og ranar deim, etter hus og tek deim. Dei gjer vald både mot mannen og huset hans, både mot bonden og eigedomen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Difor taler Herren soleis: Sjå, eg vil tenkja ut det som vondt er imot denne ætti, og de skal ikkje få til å smetta halsarne dykkar utor eller ganga so bratte i nakken heretter. For det vert ei vond tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Den dagen skal sume kveda ei nidvisa um dykk og sume syngja ein syrgjesong, og dei skal segja: «No er det slutt,» segjer dei, «reint til avgrunns me gjekk. No skifter han arven ut som folket mitt fekk. Sjå, kor han tek han ifrå meg! Gardarne våre no eiga skal folk som burt ifrå Herren fall.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'So skal du ingen hava som strekkjer mæletråd kring jord i Herrens lyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '«Haldt upp med denne preikingi!» So preikar dei. «Um slikt skal dei ikkje preika! Det er då ikkje måte på hædingsord!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Er dette sømeleg tale, du Jakobs hus? Er Herren kanskje brålyndt? Hev gjerningarne hans synt noko slikt? Er ikkje mykje heller ordi mine gode imot den som fer reideleg åt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Men alt lenge hev no folket mitt reist seg imot meg som uvenerne mine: De dreg kåpa av klædi på folk som fredsame gjeng vegen sin framum, og ikkje vil vita av strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Kvinnorne i folket mitt driv de ut ifrå heimarne deira, som var gleda deira; frå borni deira tek de for alle tider prydnaden min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Upp med dykk og gakk dykkar veg! For dette er ikkje nokon kvilestad, for den sulking skuld som valdar tyning, ja, skræmeleg tyning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Kom ein med vind og svik og laug og sagde: «Eg vil preika for deg um vin og sterk drykk,» sjå det vilde vera ein preikar for dette folket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Samla, ja, samla vil eg deg, Jakob, so mange du er; sanka, ja, sanka eg leivningen av Israel. Eg vil føra deim saman som sauer til ei kvi, som ein buskap til sitt beite, so det vert dyn av menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Vegbrøytaren fer fyre deim; dei bryt seg igjenom og stimar fram gjenom grindi og slepp ut; kongen deira fer fyre deim, og Herren er i brodden for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Og eg sagde: Høyr, de Jakobs hovdingar, og de fyrstar for Israels hus! Høyrer det ikkje dykk til å vita kva som er rett?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'De som hatar det gode og elskar det vonde, de som flår skinnet av folk og kjøtet av beini deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'de som et mitt folks kjøt og riv hudi av deim, og beini deira bryt de sund, og breider deim ut liksom i ei gryta, liksom kjøtet ein legg i panna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Då skal dei ropa til Herren; men han skal ikkje svara deim; dylja skal han si åsyn for deim på den tidi, av di dei gjorde det som vondt var i si åtferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Soleis talar Herren mot dei profetarne som vildrar folket mitt, mot deim som ropar: «Fred!» når dei fær noko å bruka tennerne sine på, men som eggjar til heilag strid mot deim som ikkje stikk dei noko i munnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Difor skal natt koma yver dykk utan syn, og myrker utan spådom. Ja, soli skal ganga ned yver profetarne, og dagen skal verta myrk yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Og sjåarane skal skjemmast, og spåmennerne blygjast; dei alle skal hylja skjegget sitt, sidan det ikkje kjem noko svar frå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Men eg, eg er full av kraft ved Herrens ande og av rettskjensla og mannsmod, so eg kann vitna for Jakob um hans fråfall og for Israel um hans synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Høyr dette, de hovdingar for Jakobs hus, og de fyrstar for Israels hus, de som styggjest ved det som er rett og krøkjer alt som er beint,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'de som byggjer upp Sion med blod og Jerusalem med urett -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'hovdingarne der dømer for mutor, prestarne lærer for løn, og profetarne spår for pengar, alt medan dei styd seg på Herren og segjer: «Er ikkje Herren midt imillom oss? Det kjem ingi ulukka yver oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Difor skal for dykkar skuld Sion verta pløgd som ein åker og Jerusalem skal verta til steinrøysar, og tempelberget til skoghaugar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Men det skal ganga so i dei siste dagarne, at det fjellet der Herrens hus stend, skal vera fast tufta på toppen av dei andre fjelli, og lyfta seg skal det upp yver høgderne; og folkeslagi skal strøyma upp på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Og mange heidningefolk skal ganga av stad og segja: «Kom, lat oss fara upp til Herrens fjell og til huset åt Jakobs Gud, so han kann læra oss um vegarne sine, og me kann ferdast på stigerne hans.» For ifrå Sion skal lovlæra ganga ut, og Herrens ord ifrå Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Og han skal døma millom mange folkeslag og skifta rett for megtige heidningfolk, jamvel um dei bur langt burte. Då skal dei smida sverdi sine um til hakkor og spjoti sine til hageknivar. Folki skal ikkje lenger lyfta sverd mot kvarandre, og ikkje meir læra seg til å føra krig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Men kvar og ein skal sitja under sitt vintre og sitt fiketre; og ingen skal skræma deim, for Herrens, allhers drotts, munn hev tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Alle folkeslagi ferdast, kvart i sin guds namn; men me ferdast i Herrens, vår Guds, namn æveleg og alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'På den dagen, segjer Herren, skal eg samla dei haltande og sanka i hop dei burtdrivne og deim som eg hev fare vondt med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Og eg vil gjera dei haltande til ein leivning, og deim som var drivne langt burt, til eit mangment folk. Og Herren skal vera konge yver deim på Sions fjell frå no og til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Og du hyrding-tårn, du dotter Sions haug! Til deg skal det koma nå, ja, koma, det forne veldet, kongeveldet til dotteri Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Men kvifor skrik du no so høgt? Finst det då ingen konge i deg? Eller er rådgjevaren din komen burt, etter di rider hev gripe deg, som ei fødande kvinna?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Vrid deg og anka deg, du dotter Sion, som ei kvinna som føder! For no lyt du ut or byen og bu ute på marki, og koma heilt til Babel! Der skal du verta frelst; der skal Herren løysa deg ut or handi på fiendarne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'No hev mange heidningfolk samla seg imot deg, og dei segjer: «Ho skal verta vanhelga, so augo våre kann få sjå på Sion med lyst!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Men dei kjenner ikkje Herrens tankar og skynar ikkje hans rådgjerd; for han hev samla deim som kornband på treskjarstaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'So reis deg då og tresk, du dotter Sion! for eg vil gjeva deg horn av jarn og klauver av kopar, so du kann knustra mange folk; og herfanget deira skal du bannlysa åt Herren, og skattar deira til allheims drott. No flokkar du deg saman, du dotter «flokk». Skansar hev dei kasta upp imot oss. Med staven slær dei Israels domar på kinnbeinet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Men du Betlehem, Efrata, som er so liten til å vera millom bygderne i Juda, frå deg skal eg få meg ein mann som skal vera herre yver Israel. Hans upphav er frå fordom, frå ævordoms dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Difor gjev han deim yver i ulukka til den tid då ho som skal føda, hev født. Då skal leivningen av brørne hans snu heim att til Israels søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Og han skal standa og gjæta i Herrens kraft, i Herrens, sin Guds, høge namn; og dei skal sitja trygt; for no skal han vera stor, til endarne av jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Og han skal vera fred. Kjem Assur inn i landet vårt, stig han inn i borgerne våre, so reiser me imot honom sju hyrdingar, ja, åtte menneskje-hovdingar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Og dei skal herja Assurs land med sverd, og Nimrods land alt inn i portarne; og han skal frelsa frå Assur når han kjem inn i landet vårt, og når han stig yver landskilet vårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Og leivningen av Jakob skal vera midt millom mange folkeslag liksom dogg frå Herren, liksom regnskurer på gras, som ikkje biar på mann eller ventar på menneskjeborn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Og leivningen av Jakob skal vera millom heidningarne, midt imillom mange folk, liksom ei løva millom dyr i skogen, liksom ei ungløva inne i saueflokkar. Ho slær ned når ho fer fram, og riv sund, og det er ingen som bergar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Høg vere di hand yver uvenerne dine! Må alle fiendarne dine ryddjast ut!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Og det skal ganga soleis på den dagen, segjer Herren, då vil eg rydja ut alle hestarne du hev hjå deg, og øyda vognerne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Og eg vil rydja ut byarne i landet ditt og riva ned alle borgerne dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Og eg vil rydja alle trolldomskunster utor henderne på deg; og spåmenner skal ikkje lenger finnast hjå deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Eg vil rydja ut dei utskorne gudebilæti dine og minnesteinarne dine, som du hev hjå deg, so du ikkje meir skal bøygja kne for det som henderne dine hev laga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Og eg vil riva upp Astarte-stolparne dine or landet ditt, og byarne dine vil eg øyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Og i vreide og harm tek eg hemn yver dei heidningfolk som ikkje vilde høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Høyr kva Herren segjer: Reis deg! Før di sak for fjelli! Lat haugarne høyra di røyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Ja, høyr Herrens sak, de fjell og de ævelege grunnvollar under jordi! For Herren fører sak med folket sitt, og med Israel vil han ganga til doms.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Mitt folk, kva hev eg gjort deg? Kva hev eg trøytta deg med? Svara meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Eg førde deg då ut or Egyptarlandet, og frå trælehuset løyste eg deg ut; og Moses og Aron og Mirjam sette eg i brodden for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mitt folk! Kom i hug det Balak, kongen i Moab, var meint på, og det Bileam Beorsson svara honom! Kom i hug ferdi frå Sittim til Gilgal, so du kann skyna Herrens rettferdsverk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Kva skal eg stiga fram for Herren med, bøygja meg med for Gud i det høge? Skal eg stiga fram for honom med brennoffer, med årsgamle kalvar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Vil Herren hava hugnad i tusund verar, i ti tusund oljebekkjer? Skal eg ofra min fyrstefødde for mitt brot, mi livsfrukt til syndoffer for mi sjæl?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Nei, han hev sagt deg, menneskje, kva som godt er; for kva krev Herren av deg anna enn at du skal gjera det som rett er, leggja vinn på kjærleik og ferdast audmjukt med din Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Høyr kor Herren ropar til byen - og det er visdom å ottast namnet ditt -. Høyr straffi, og kven det er som hev fastsett henne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Finst det endå i huset åt den gudlause rangfenge skattar og undermåls skjeppemål, som er bannstøytt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Kunde eg vera rein dersom eg bruka svikefulle vegtar og hadde falske lodd i pungen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Du by med rikfolk, fulle av urett, og dei som bur der, talar lygn og hev ei falsk tunga i munnen sin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'So vil då eg og slå deg so det gjer vondt, leggja deg i øyde for dine synder skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Du skal eta, men ikkje verta mett, og tom skal du alltid kjenna deg. Du kann flytja, men du skal ikkje berga. Og det du bergar, skal eg gjeva åt sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Du skal så, men ikkje få hausta. Du skal pressa olivor, men ikkje få salva deg med olje. Du skal pressa druvesaft, men ikkje få drikka vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'For fyreskrifterne åt Omri agtar dei vel på, og all gjerning av Ahabs hus, og etter deira råder er det de ferdast, for eg skal gjera deg til ei skræma og ibuarane dine til spott, og vanæra yver folket mitt skal de bera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Usæl eg! For meg hev det gjenge som når sumarfrukti er innhausta, som når ettersankingi etter vinhausten er slutt; det finst ikkje ei einaste druva til å eta, ikkje ei einaste tidlegfika, som eg kunde havt hug på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Den gudlege er burtkomen or landet, og det finst ingen ærleg mann millom menneski. Alle i hop ligg dei på lur etter blod; kvar og ein vil fanga den andre i garnet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Med båe hender arbeider dei på å gjera det vonde godt. Fyrsten kjem med krav, og domaren er til fals for pengar, og storkaren taler ope ut um det som han hev hug på. Soleis snur dei det til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Den beste av deim er som ein klunger, den ærlegaste verre enn eit klungergjerde. Dagen åt vaktmennerne dine, di heimsøkjing kjem. No vert dei forfjetra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Tru ikkje på nokon ven! Lit ikkje på nokon kjenning! For henne som ligg i famnen din, må du vakta din munns dører!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'For sonen vanvyrder far sin, dotteri set seg upp imot mor si, sonekona imot vermor si, ein manns husfolk er fiendarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Men eg vil skoda etter Herren, eg vil venta på Gud som frelser meg. Min Gud vil høyra meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Gled dykk ikkje yver meg, du min fiende! Er eg falli, so reiser eg meg upp att. Sit eg i myrkret, so er Herren ljoset mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Herrens vreide vil eg bera, for eg hev synda mot honom, til han tek saki mi upp og hjelper meg til retten min. For han skal leida meg ut i ljoset. Med gleda skal eg sjå på hans rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Måtte ho få sjå det, ho som er uvenen min, og skammi sveipa seg kringum henne som segjer til meg: «Kvar er han, Herren, din Gud?» Augo mine skal sjå på henne med fysnad. No skal ho verta nedtrakka som skarn på gata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Det kjem ein dag då dei skal reisa murarne dine upp att. Den dagen skal grensorne dine verta vide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Den dagen skal dei koma til deg heilt frå Assur og frå byarne i Egyptarland, ja, frå Egyptarland og alt til Storelvi, og frå hav til hav og frå fjell til fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Men jordi skal verta ei øydemark for deira skuld som bur på henne, for slik frukt ber gjerningarne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Gjæt folket ditt med staven din, den buskapen som du hev ervt, han som bur for seg sjølv i skogen på Karmel! Lat deim beita i Basan og Gilead liksom i forne tider!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Ja, liksom i dei dagarne då du gjekk ut or Egyptarlandet, skal de få sjå underlege ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Heidningarne skal få sjå det og skjemmast ved alt sitt velde. Dei skal verta nøydde til å leggja handi på munnen. Øyro deira skal verta dauve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Dei skal slikka mold liksom ormen, liksom makkarne som aular på jordi, skal dei koma skjelvande fram or borgerne sine. Med rædsla skal dei koma fram til Herren, vår Gud; og dei skal ottast deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kven er ein Gud som du? Han tek burt synd og tilgjev brot for deim som er att av hans arv. Han held ikkje fast på vreiden sin til æveleg tid. For han hev hug til miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Atter skal han miskunna oss og trakka ned vår skuld. Du skal kasta alle synderne deira i havsens djup.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Du skal syna Jakob truskap og Abraham miskunn, soleis som du hev svore åt federne våre i gamle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Framsegn um Nineve. Boki um syni hans Nahum, elkositen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Herren er ein streng Gud og ein hemnar, ja, ein hemnar er Herren, og full av harm; Herren hemner seg på motmennerne sine og held på vreiden mot uvenerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Herren er sein til vreide, men han er stor i kraft, og slett ikkje let han nokon vera ustraffa. I uver og storm hev Herren sin veg, og skyerne er dumba um føterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Han trugar havet og turkar det ut, alle elvarne let han torna. Då folnar Basan og Karmel, og groren på Libanon folnar burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Bergi bivrar for honom, og haugarne brånar. Jordi lyftar seg for hans åsyn, jordriket med alle som i det bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kven kann standa for hans trugsmål, og kven kann halda ut hans brennande harm? Vreiden hans gøyser fram som eld, og bergi brest i sund for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Herren er god, ei vern på trengsledagen. Han kjenner deim som trøystar seg til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Men ved ei sturtflod gjer han ende på staden der den byen stend, og uvenerne hans skal myrkret elta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Ja, på dykkar uråder mot Herren gjer han ende. Ikkje tvo gonger tarv trengsla koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'For um dei og er ihopfløkte som klungerbuska og so fulle av livssaft som deira drykk av vin, so skal dei like fullt verta uppbrende som fullturr halm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Frå deg gjekk det ut ein mann som hadde ilt i hugen mot Herren. Nidingskap var det han etla seg til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'So segjer Herren: Kor sterke og mange dei og mun vera, so skal dei like vel verta avskorne og kverva burt. Og um eg fyrr hev plåga deg, so skal eg ikkje gjera det no meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'For no vil eg brjota det oket han lagde på deg, og slita bandi dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Men um deg byd Herren so: Inkje avkjøme skal heretter koma frå namnet ditt. Or huset åt guden din vil eg rydja ut både skorne og støypte bilæte. Ei grav vil eg bu til åt deg. For du er funnen for lett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Sjå, yver fjelli føterne åt honom som ber fagnadbod, han som forkynner fred! Haldt dine høgtider, Juda, fullgjer dine lovnader! For aldri meir skal nidingen draga imot deg - mot rot han uppriven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Ein folkeøydar fer upp imot deg. Vakta vollarne! Haldt utkik på vegen! Umgyrd lenderne, samla all di kraft!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'For Herren vil reisa upp att stordomen åt Jakob liksom stordomen åt Israel, sidan ransmenner so hev øydt deim og tynt vintrei deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Skjoldarne åt kjemporne hans er raudlita, stridsmennerne er klædde i skarlak, vognerne i eld og stål når han herbur deim, og spjot vert svinga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'På vegarne rasar vognerne fram. Dei andferst på torgi. Dei er å sjå til som logar, som eldingar fer dei fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Han kjem i hug storfolket sitt, dei snåvar der dei gjeng, dei styrmer til bymuren, men skjoldtaket er reist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Elve-portarne vert opna, og kongsgarden sig saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Ja, domen stend fast: ho vert nækt, dragsa burt. Ternorne hennar græt som duvor, dei slær seg for bringa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'I all si tid var Nineve lik ein dam, rik av vatn, men no flyr dei burt. Stogga! Stogga! - Nei, ingen snur seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Rana no sylv, rana no gull! Her tryt det ikkje på skattar, på nøgdi av allskyns dyrverdige ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Tomt, tomleik, tøming! - Hjartestøkk, kneskjelv og verk i alle mjødmar, og alle andlit skifter liter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Kvar er no løvehiet, etar-staden åt ungløvorne, der løva og løvemori gjekk, og løve-ungen, og ingen skræmde deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Kvar er løva som rana so mykje som ungarne vilde hava, og drap åt løvemøderne, ja, fyllte upp holorne sine med ran og hii sine med det sundrivne? Sjå, eg skal venda mot deg, segjer Herren, allhers drott. Vognerne dine skal eg lata ganga upp i røyk, og dine unge løvor skal sverdet øyda. Eg skal rydja ditt rov ut frå jordi. Og ingen skal meir høyra røysti åt dine sendemenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Usæl du blod-by, som all igjenom er full av lygn og vald, du som aldri held upp med å rana.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Høyr svepesmell og ramling av hjul og hestar i flog og hoppande vogner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Ridar i tvisprang og logande sverd og blinkande spjot! Drepne i mengd og dungar av daude kroppar. Ingen ende er det på daude. Ein snåvar i lik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Alt dette for den mangfelte hordomen som ho dreiv, ho, den fagre og trollkunnige skjøkja, som selde folkeslag ved hordomen sin og folke-ætter ved trolldomskunsterne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Sjå, eg skal venda meg mot deg, segjer Herren, allhers drott. Eg skal lyfta kjolefalden din upp yver andlitet ditt og syna folkeslagi blygsli di og kongeriki skammi di.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Eg skal kasta saur på deg og svivyrda deg. Ja, til eit skodespel skal eg gjera deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Og kvar og ein som ser deg, skal fly frå deg og segja: «Nineve er lagt i øyde. Men kven kann tykkja synd i henne? Kvar skal eg søkja trøystarar åt deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Er du betre enn No-Amon, som låg ved Nilelvi, umringa av vatn, med hav til vern, hav til mur?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, '\'tiopar i mengd og uteljande egyptarar; Put-menner og Libya-menner var hjelpeheren hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Ho og laut ganga ut i utlægd, sitja fange. Småborni hennar vart krasa på alle gatehyrno. Um alle gjævingarne hennar kasta dei lut, og alle hennar stormenner vart sette i jarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Du skal og drikka og verta sanselaus. Du og skal søkja ei livd imot fienden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Alle dine borger likjest på fiketre med snar-mogne fikor; ved minste skaking dett dei i munnen på den som vil eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Sjå, ditt mannskap er kvinnfolk midt i deg. Portarne til landet ditt stend vidopne for dine fiendar. Elden hev øydt upp dine portslåer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Aus deg vatn til kringsetjingi! Vøl um dine skansar! Gakk ut gyrma og stampa leira! Triv tiglsteinsformi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Der skal elden eta deg, sverdet øyda deg ut, ja, øyda deg som engspettor, um du og sjølv samlar skarar so tallause som engspettor, ei ovmengd som grashoppar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Um du og hev kræmarar fleire enn stjernor på himmelen, so skal du vita: engspettor skyt hamen og flyg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Ja, fyrstarne dine er som grashoppar og hovdingarne dine som svermar av engtytor; dei slær læger i hegni med det er svalt. Men når soli kjem fram, flyg dei burt, og ingen veit kvar det vert av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Hyrdingarne dine blundar, du Assur-konge, gjævingarne dine søv. Folket ditt sundsprengt på fjelli, og ingen samlar det saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Ditt mein er ulækjande, ditt sår er til ulivs. Ved tiendi um deg klappar alle i handi. For kven hev ikkje din vondskap råka stødt og stendigt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Framsegni som profeten Habakuk skoda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Kor lenge, Herre, skal eg ropa, og du høyrer ikkje? Eg skrik til deg um vald, og du hjelper ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Kvi let du meg skoda urett, og du ser på møda? Øyding og valdsverk hev eg for augo, kiv yppast, trettor kjem upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Difor valnar lovi, og retten når aldri fram. Den gudlause ringar inne den rettferdige, difor kjem retten fram rengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Sjå ut millom folki, skoda og undrast, ja undrast! For eg gjer eit verk i dykkar dagar - de vilde ikkje tru det når det vart fortalt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Sjå, eg vekkjer kaldæarane, det kvasse og bråe folket, som fer fram so vida som jordi når, og eignar til seg framande bustader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Fælslege, skræmelege er dei, rett og velde råder dei seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Hestarne deira er rappare enn panterar og ramare enn ulvar um kvelden, og hestfolket deira kjem i rennande fart, hestfolket deira kjem langt burtanfrå, flyg som ørnen som fer etter åta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'På veg til vald er dei alle, samlyndt snur dei andlitet fram, og dei sankar fangar som sand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Dei hev kongar til spott og hovdingar til lått, dei lær åt kvar ei borg, dei dungar i hop mold og tek borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'So stryk dei sin veg som ein vind, og dei fer fram og fører skuld yver seg, for dei hev si eigi kraft til sin Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Er ikkje du frå fordoms tid, Herren, min Gud, min Heilage? Me skal ikkje døy. Herre, til dom hev du honom sett. Du fjell, til refsing hev du laga honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Augo dine er for reine til å sjå på det som vondt er, og du orkar ikkje skoda på møda. Kvi ser du då på svikarar? Tegjer stilt når den ugudlege gløypar den som er meir rettferdig enn han?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Du gjer menneskje like med havsens fiskar, med kreket som ingen herre hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Deim alle dreg han upp med krok, samlar deim i sitt garn, og sankar deim i si not. Difor gled han seg og jublar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Difor ofrar han til garnet sitt, brenner røykjelse for noti si, for dei gjev honom hans feite lut og mergfull mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Skal han difor få tøma garnet sitt og stødt og stendigt drepa folkeslag utan skonsel?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'På vaktposten min vil eg stiga upp og standa på varden, og eg vil skygna og sjå kva han vil tala med meg, og kva svar eg fær på mitt ankemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Og Herren svara meg og sagde: Skriv upp syni og rita henne tydeleg på tavlorne, so kvar og ein kann lesa det lett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'For endå lyt syni venta på si tid, men ho stundar etter målet og skal ikkje svika. Um ho drygjer, so bia på henne, for ho kjem nok, ho skal ikkje verta burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Sjå kor hjartans kaut og krokut han er! Men den rettferdige, ved si tru skal han liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'For liksom vinen ikkje er å lita på, so skal den kaute karen ikkje få bu i ro, um han so gaper som helheimen og er som dauden umettande, og um han hev sanka til seg alle folk og henta til seg alle folkeslag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Alle dei skal i sanning setja i med spottesong um honom og sneida etter honom i gåtor; dei skal segja: «Usæl den som dungar i hop det han ikkje eig - kor lenge? - Og som lesser på seg pant!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Brått skal dei reisa seg dei som skal pina deg, og vakna dei som skal ruska i deg, so du vert til ran for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Av di du hev plundra mange folk, so skal alt det som vert att er av folki, plundra deg, for manneblod skuld og for valdsverk mot jordi, mot byen og alle som bur der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Usæl den som dreg ihop låk vinning til huset sitt, av di han vil byggja reiret sitt i høgdi og sleppa frå ulukke-hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Du hev rådlagt til skam for ditt hus, rådlagt um å øyda mange folk, og soleis synda mot deg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'For steinen skrik utor muren, og frå treverket svarar bjelken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Usæl den som byggjer by med blod og reiser borg med urett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Er ikkje det av Herren, allhers drott: «Folki arbeider for elden, og folkeslagi møder seg ut for inkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, '«For jordi skal fyllast med kunnskap um Herrens herlegdom liksom vatnet fyller havet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Usæl den som skjenkjer andre med harm iblanda, ja, drikk deim drukne, so han kann skoda blygsli deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Du vert metta med skam for æra. Drikk du, og syn di fyrehud! Staupet i Herrens hand kjem til deg, og skjemsla skyler di æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'For valdsferdi mot Libanon skal velta yver deg, og øydingi av dyri som skræmde dei, for manneblod skuld og for valdsverk mot jordi, mot byen og alle som bur der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Kva gagnar eit utskore bilæte, sidan treskjeraren hev skore det? Eller eit støypt bilæte, ein ljugarlærar, sidan støyparen lit so på det, at han lagar mållause avgudar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Usæl den som segjer til stokken: «Vakna!» Og: «Reis deg!» til mållause steinen. Skulde den vera lærar? Visst er han slegen med gull og sylv, men det finst ikkje ånd i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Men Herren er i sitt heilage tempel; ver still for honom, all jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Ei bøn av profeten Habakuk. Etter Sjigjonot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Herre, eg hev høyrt tidendi um deg, eg er forfærd. Herre, ditt verk - kveik det upp att i desse åri! Kunngjer det i desse åri! Midt i harm kom miskunn i hug!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gud kjem frå Teman, og den Heilage frå Paranfjellet. Sela. Hans herlegdom tekkjer himmelen, og jordi er full av hans pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Det vert ein glans som av soli, geislar gjeng frå hans sida; der løyner seg hans magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Fyre honom gjeng sott, og sykja fylgjer hans fotfar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Han stoggar, og jordi ristar, han ser, og folki skjelv; dei gamle fjelli sprekk, og ævordoms-haugarne sig i hop. Han fer på vegar frå fordom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Kusans tjeldbuder ser eg i vande, tjeldi i Midjanslandet skjelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Logar din harm mot elvar, Herre? Din vreide mot elvarne? Harmast du på havet, sidan du ferast med hestarne dine, med sigervognerne dine?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Berr, ja berr er bogen din. Svorne er refsingsris i ordet. Sela. Til elvar kløyver du jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Fjelli ser deg og skjelv, støyteregn sturtar ned, djupet dyn og styn, det lyfter henderne mot høgheim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Sol og måne gjeng inn i sitt hus for skinet frå dine farande piler, for glansen av ditt ljonande spjot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'I harm skrid du fram yver jordi, i vreide trøder du folk under fot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du dreg ut til frelsa for folket ditt, til frelsa for honom som du salva. Du krasar hovudet på huset åt den gudlause, du gjer grunnen berr alt til halsen. Sela.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Med hans eigne spjot sting du gjenom hovudet på hovdingarne hans som stormar fram, vil spreida meg, som gleder seg som det galdt i løynd å eta ein arming upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Du fer yver havet med hestarne dine, det velduge brusande vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Eg hev høyrt det, og hjarta skalv. Ved ljoden bivrar lipporne mine, beini morknar i meg, og eg skjelv der eg stend. For eg lyt tolug bia på trengsledagen, til han dreg upp som trengjer folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'For fiketreet blømer ikkje, og vintreet ber ikkje frukt, olje-avlen mislukkast. Og markene ber ikkje mat; sauerne kverv or kvii, og det finst ikkje fe i fjøset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Men eg vil frygda meg i Herren, vil gleda meg i Gud som frelser meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Herren, Herren er min styrke, han gjev meg føter som ei hind og let meg skrida yver mine haugar. Til songmeisteren, med min strengleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Herrens ord som kom til Sefanja, son åt Kusi, son åt Gedalja, son åt Amarja, son åt Hizkia, i dei dagar då Josia Amonsson var konge i Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Burt, ja burt vil eg taka alt frå jordi, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Eg vil taka burt menneskje og dyr, taka burt fuglarne under himmelen og fiskarne i havet og støytesteinarne i lag med dei gudlause, og eg vil rydja menneski ut av jordi, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Og eg vil retta ut handi mi mot Juda og alle deim som bur i Jerusalem, og eg vil rydja ut frå denne staden den siste leivning av Ba’al, namnet åt avgudsprestarne i lag med prestarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'deim som på taki bed til himmelheren, deim som bed til og sver ved Herren og attpå sver ved Milkom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'og deim som hev vendt seg burt frå Herren, og deim som ikkje hev søkt Herren og ikkje spurt etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Ver stille for Herren, Herren! For Herrens dag er nær, Herren hev laga til eit slagtoffer, han hev vigt sine gjester.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Og på Herrens slagtofferdag vil eg heimsøkja hovdingarne og kongssønerne og alle som klæder seg i utanlands-klæde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Og eg vil på den dagen heimsøkja alle deim som hoppar yver dørstokken, dei som fyller sin Herres hus med vald og svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'På den dagen, segjer Herren, skal det høyrast skrik frå Fiskeporten, jammer frå Nybyen og stort brak frå høgderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Jamra, de som bur i Mortelen, for heile kræmerfolket er gjort til inkjes, og alle kjøpmenner utrudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Og på den same tidi vil eg ransaka Jerusalem med lykter og heimsøkja dei menneskje som ligg i ro på sin berm og segjer i sitt hjarta: «Herren gjer korkje godt eller vondt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Og eigedomen deira skal verta til herfang og husi deira til tjon. Hus skal dei byggja, men ikkje bu i deim, vinhagar skal dei planta, men ikkje drikka deira vin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Nær er Herrens dag, den store. Han er nær og kjem med stor hast. Høyr! Det er Herrens dag! Sårt skrik då kjempa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ein vreide-dag er den dagen, ein dag med naud og trengsla, ein dag med øyding og audner, ein dag med myrker og dimma, ein dag med skyer og skodda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'ein dag med lurblåster og herrop mot dei faste byar og mot dei høge murtindar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Då vil eg setja folk i slik angest, at dei gjeng der som blinde, for di dei hev synda mot Herren. Blodet deira skal verta burtslengt som mold, og kjøtet deira som møk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Korkje sylvet eller gullet deira skal kunde berga deim på Herrens vreide-dag, når elden frå hans brennhug øyder all jordi; for han vil gjera ende, ja, ein brå ende på alle deim som bur på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Samla dykk og sansa dykk, du folk som ikkje blygjest!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'fyrr rådgjerdi føder - som agner fer dagen fram - fyrr Herrens brennande vreide kjem yver dykk, fyrr Herrens vreide-dag kjem yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Søk Herren alle de audmjuke i landet, som held lovi hans! Søk rettferd, søk audmykt! Kann henda vert de då livde på Herrens vreide-dag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'For Gaza skal verta folketomt, Askalon til ei øydemark, Asdod-folket skal jagast ut midt på ljose dagen og Ekron rykkjast upp med rot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Usæle dei som bur i bygdi utmed havet, kretarfolket. Herrens ord er yver deg, Kana’an, Filistarland. Ja, eg vil leggja deg i øyde, so ingen skal bu i deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Og bygdi utmed havet skal liggja til hamnegang med gjætarbrunnar og sauegardar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Og leivningen av Judas hus skal få bygdi til sin lut, der skal dei hava beite. I Askalon-husi skal dei liggja um kvelden, når Herren, deira Gud, ser til deim, og vender deira lagnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Eg hev høyrt svivyrdingi frå Moab og spottordi frå Ammons-borni, som dei hev svivyrdt mitt folk med og briska seg mot landet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Difor, so visst som eg lever, segjer Herren, allhers drott, Israels Gud, skal det ganga Moab som Sodoma og Ammons-sønerne som Gomorra: Dei skal verta til netlemark, saltgruva og øydemark til æveleg tid. Resten av folket mitt skal plundra deim, leivningen av lyden min skal få deim til eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Dette skal henda deim for deira storlæte, for di dei svivyrde og briska seg mot folket åt Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Fæl skal Herren vera mot deim, for han skal øyda ut alle gudarne på jordi. Alle heidninglandi skal kasta seg ned for honom, kvar frå sin stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'De og, ætiopar - gjenomstungne av sverdet mitt er dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Han retter ut handi mot nord og tyner Assur og gjer Nineve til ei øydemark, til turre heidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Hjorder skal lægra seg der inne, alle slag villdyr i flokk. Pelikan og bustyvel skal natta på sulehovudi der, fuglelåt høyrast i vindaugo, øyda bu på dørstokken, for cederpanelet hev han rive.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Dette er den jublande byen, som sat so trygt og sagde i sitt hjarta: «Eg og ingen annan!» Kor aud han er vorten, eit læger for villdyr! Kvar den som framum fer, blistrar og vinkar med handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Usæl han, den tråssuge og ureine, valdsbyen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Han høyrer ikkje på røysti åt nokon, tek ikkje tukt. På Herren lit han ikkje, til sin Gud vil han ikkje koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Hovdingarne der inne er burande løver, domarane hans er som ulvar um kvelden; dei sparar inkje til morgondagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Profetarne hans er skrythalsar, trulause menner, prestarne vanhelgar det heilage, gjer vald mot lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Herren er rettferdig der inne, gjer ikkje urett. Kvar morgon let han sin dom koma fram i ljoset, det glepp ikkje. Men den urettferdige kjenner ikkje skam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Eg hev øydt ut folkeslag, deira murtindar vart nedbrotne. Eg gjorde gatorne deira aude, so ingen ferdast på deim; byarne deira vart herja, so dei er utan folk, utan ibuar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Eg sagde: Berre du vil ottast meg, taka tukt, so skal bustaden din ikkje verta øydelagd med alt det som eg hev gjeve deg i varetekt. Like vel var dei uppsette på å lata alle sine gjerningar vera illverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Difor, bia på meg, segjer Herren, til den dagen eg ris upp til herfang. For det er min dom at eg samlar folki og stemner saman kongeriki, renner ut harmen min yver deim, all min brennande vreide; for elden av min brennhug skal øyda heile jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'For då vil eg gjeva folki nye, reine lippor, so dei kann kalla på Herrens namn og samheldigt tena honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Frå landet burtanfor elvarne i \'tiopia skal dei føra mine tilbedarar, mitt spreidde folk bera fram offer til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'På den dagen tarv du ikkje skjemmast ved alle gjerningarne dine, som du synda imot meg med; for då vil eg rydja burt frå deg deim som jublar so stolt i deg, og du skal ikkje meir gjera deg stor på mitt heilage fjell.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Men eg vil leiva i deg eit audmjukt og armt folk, og dei skal lita på Herrens namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Israels leivning skal ikkje gjera urett, dei skal ikkje tala lygn, og det skal ikkje finnast svikfull tunga i deira munn. Ja, dei skal beita og liggja i ro, utan at nokon skræmer deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Jubla, dotter Sion! Lyft upp fagnadrop, Israel! Gled deg og frygda deg av alt ditt hjarta, dotter Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Herren hev vend straffedomarne ifrå deg, rudt fienden din or vegen. Herren, Israels konge, er hjå deg. Du tarv ikkje meir ottast noko vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'På den dagen skal det segjast til Jerusalem: «Ottast ikkje, Sion, lat ikkje henderne siga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Herren din Gud er hjå deg, ei kjempa som kann frelsa. Han gled seg yver deg med fagnad, han tegjer i sin kjærleik; han jublar i frygd yver deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Eg samlar deim som med sorg hev vore utestengde frå høgtidsstemnorne; dei er frå deg. Vanæra tyngjer på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Sjå, på den tidi vil eg taka på trælkarane dine, og eg vil frelsa dei halte og sanka saman dei burtdrivne og gjera deim til æra og gjetord yver heile jordi, der dei fyrr var vanæra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'På den tid let eg dykk koma heim att, på den tid sankar eg dykk, og eg vil gjera dykk til gjetord og æra millom alle folki på jordi, når eg vender lagnaden dykkar for augo på dykk, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'I andre styringsåret åt kong Darius, fyrste dagen i sette månaden, kom Herrens ord ved profeten Haggai til Zerubbabel Sealtielsson, jarl yver Juda, og til øvstepresten Josva Josadaksson:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'So segjer Herren, allhers drott: Dette folket segjer: «Det er ikkje enno tid til å koma, tid til å byggja Herrens hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Men so kom Herrens ord ved profeten Haggai:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Er det då tid for dykk sjølve å bu i dykkar bordklædde hus, medan dette huset ligg i øyde?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Og no segjer Herren, allhers drott, so: Agta på korleis det gjeng dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'De sår mykje, og haustar lite; de et og vert ikkje mette; de drikk og sløkkjer ikkje torsten; de klæder dykk og vert ikkje varme; leigetenaren fær si løn i ein botnelaus pung.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So segjer Herren, allhers drott: «Agta på korleis det gjeng dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Far til fjells og henta timber og bygg upp templet, so eg kann hava hugnad i det og syna meg herleg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'De vona mykje og vann lite; de førde heim og eg bles det burt. Kvifor? segjer Herren, allhers drott. Jau, for mitt hus skuld, av di det ligg i øyde, medan de sjølve hev det annsamt kvar med sitt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Difor hev himmelen meinka dykk dogg og jordi meinka dykk grøda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Eg hev kalla turk yver land og fjell, yver korn og druvesaft og olje og alt som gror på marki, yver folk og fe og all dykkar arbeidsvinning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Zerubbabel Sealtielsson og øvstepresten Josva Josadaksson og alt det som var att av folket lydde på Herren, sin Gud, og ordi frå profeten Haggai, av di Herren, deira Gud, hadde sendt honom; og folket bar age for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Og Herrens sendebod Haggai bar fram Herrens bod til folket: Eg er med dykk, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Og Herren kveikte hugen hjå Zerubbabel Sealtielsson, jarlen yver Juda, og hjå øvstepresten Josva Josadaksson og hjå alle deim som var att av folket, so dei lagde i veg og arbeidde på huset åt Herren, allhers drott, deira Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'den fire og tjugande dagen i sette månaden i andre styringsåret åt kong Darius.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Den ein og tjugande dagen i sjuande månaden kom Herrens ord ved profeten Haggai:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Tala til Zerubbabel Sealtielsson, jarlen i Juda, og til øvstepresten Josva Josadaksson og til det som er att av folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Finst det endå nokon attlivande millom dykk som hev set dette huset i sin fyrre herlegdom? Kva tykkjer de um det no? Er det ikkje for augo dykkar som inkjevetta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Men ver hugheil no, Zerubbabel! segjer Herren, ver hugheil, øvsteprest Josva Josadaksson! ver hugheilt, alt folket i landet! segjer Herren, og arbeid! For eg er med dykk, segjer Herren, allhers drott;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'den avtalen eg gjorde med dykk ved utferdi frå Egyptarland, skal standa ved lag, og min ande skal bu millom dykk. Ver ikkje rædde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'For so segjer Herren, allhers drott: Enno ein gong um eit lite bil skal eg skaka himmel og jord og hav og land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Eg skal skaka alle folki, so dei dyraste eignaluterne frå alle folki skal koma hit, og eg skal fylla dette huset med herlegdom, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Sylvet er mitt, og gullet er mitt, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Den komande herlegdom i dette siste huset skal verta større enn det fyrre, segjer Herren, allhers drott; og på denne staden vil eg gjeva fred, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Den fire og tjugande dagen i niande månaden i andre styringsåret åt kong Darius kom Herrens ord ved profeten Haggai.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'So segjer Herren, allhers drott: Spør kva prestarne lærer um dette:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Um ein mann ber heilagt kjøt i klædesnippen og so med snippen kjem nær noko brød eller kokemat eller vin eller olje eller anna etande, vert då det heilagt? Prestane svara nei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'So spurde Haggai: «Men um ein hev vorte urein av eit lik og so kjem nær noko av alt dette, vert det då ureint?» Prestarne svara ja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Då tok Haggai til ords og sagde: Soleis er det med denne lyden, og soleis er det med dette folket i mine augo, segjer Herren, og like eins med alt det deira hender gjer, og det dei ofrar der, det er ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Gjev no gaum frå i dag og attende. Fyrr de tok til og lagde stein på stein i Herrens tempel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'når einkvan i den tid gjekk til ein korndunge på tjuge skjeppor, so fann han berre ti; når einkvan gjekk til ei vinpersa og vilde ausa upp femti mål, so fekk han ikkje meir enn tjuge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Eg søkte dykk med sotbrand og rust og haglver yver alt dykkar arbeid, og endå vende de ikkje um til meg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Men gjev gaum no frå i dag og attende, frå fire og tjugande dagen i niande månaden alt til den dagen då Herrens tempel vart tufta. Gjev gaum!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Finst det enno att noko sæde i kornburet? Og korkje vintreet eller fiketreet eller granatapallen eller oljetreet hev bore noko! Frå i dag skal eg velsigna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Andre gongen kom Herrens ord til Haggai den fire og tjugande dagen i månaden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Seg til Zerubbabel, jarlen yver Juda: Eg skal skaka himmel og jord;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'eg skal velta i koll kongsstolarne og tyna veldet åt dei heidne kongeriki; eg skal velta stridsvognerne og deim som stend på deim, og hestarne skal stupa og ridarene med, den eine for sverdet åt hin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Den dagen, segjer Herren, allhers drott, tek eg deg, Zerubbabel Sealtielsson, du min tenar, og gjer deg til ein seglring; for deg hev eg valt ut, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'I den åttande månaden i andre styringsåret åt Darius kom Herrens ord til profeten Zakarja, son til Berekja, son til Iddo; han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Ofseleg harm var Herren på federne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Seg difor no til deim: So segjer Herren, allhers drott: Vend um til meg, segjer Herren, allhers drott, so skal eg venda um til dykk, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ver ikkje like federne dykkar som dei fyrre profetarne varsla med desse ordi: «So segjer Herren, allhers drott: Vend då um frå dei vonde vegarne dykkar og dei vonde gjerningarne dykkar! Men dei høyrde ikkje og vyrde meg ikkje, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Federne dykkar, kvar er dei? Og profetarne, kann dei liva til æveleg tid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Men mine ord og mine rådgjerder, som eg baud mine tenarar, profetarne, å forkynna, råka dei ikkje federne dykkar, so dei venda um og sagde: «Som Herren, allhers drott, hadde sett seg fyre å gjera med oss etter våre vegar og våre gjerningar, so hev han gjort med oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'På den fire og tjugande dagen i ellevte månaden - det er månaden sebat - i andre styringsåret åt Darius, kom Herrens ord til profeten Zakarja, son til Berekja, son til Iddo, soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Ei syn hadde eg um natti: Ein mann ridande på ein raud hest; han stod still millom myrtetrei i dalbotnen, og attanfor han stod raude, brune og kvite hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Då spurde eg: «Kva er dette, herre?» Og engelen som tala med meg, svara: «Eg skal syna deg kva dette er.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Mannen millom myrtetrei tok då til ords og sagde: Dette er dei som Herren hev sendt ut til å fara ikring på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Og dei tok til ords og svara Herrens engel som stod millom myrtetrei: «Me hev fare ikring på jordi, og me hev set at heile jordi kviler i fred og ro.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Då tok Herrens engel til ords og sagde: «Herre, allhers drott! Kor lenge vil du drygja fyrr du gjer miskunn mot Jerusalem og byarne i Juda, som du hev harmast på no i sytti år?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Herren svara då engelen som tala med meg, med gode og trøystande ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Og engelen som tala med meg, sagde til meg: «Dette skal du forkynna: So segjer Herren, allhers drott: Eg er brennande ihuga for Jerusalem og Sion,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'og gruveleg vreid er eg på dei sjølv-trygge heidningfolki; for eg var berre litegrand vreid; men dei auka ulukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Difor segjer Herren so: Eg vil atter venda meg til Jerusalem med miskunn. Huset mitt skal verta bygt der, segjer Herren, allhers drott, og mælesnor skal verta spana ut yver Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Framleides skal du forkynna: So segjer Herren, allhers drott: Endå ein gong skal byarne mine fløyma yver av det som godt er, endå skal Herren trøysta Sion, endå ein gong velja ut Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'So lyfte eg upp augo mine og fekk sjå fire horn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Då spurde eg engelen som tala med meg: «Kva er dette?» Og han sagde til meg: «Dette er dei horni som hev spreidt Juda, Israel og Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'So let Herren meg sjå fire smedar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'og eg spurde: «Kva skal desse gjera?» Han svara: «Det var horni som spreidde Juda so at ingen lyfte hovudet sitt. Desse er no komne og skal skræma deim og slå av horni på dei heidningfolki som lyfte horn mot Judalandet til å spreida det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Og eg lyfte upp augo mine og fekk sjå ein mann med ei mælesnor i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Då spurde eg: «Kvar gjeng du?» Han svara: «Eg skal mæla Jerusalem og sjå kor breidt og kor langt det skal verta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Då kom han fram den engelen som tala med meg, og ein annan engel kom imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Og han sagde til honom: «Spring og seg til denne unge mannen: «Fritt og ope skal Jerusalem liggja; slik ei mengd med folk og fe skal finnast der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Men eg skal sjølv vera ein eldmur rundt ikring, segjer Herren, og eg skal syna meg herleg der inne.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Ai, ai! Skunda dykk burt frå Norderlandet, segjer Herren; for eg hev då spreidt dykk for alle heimsens fire vindar, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Ai! Sion! Røm undan, du som bur hjå dotteri Babel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'For so segjer Herren, drott: For sin herlegdom skuld hev Herren sendt meg til heidningfolki som plundra dykk; for den som rører dykk, rører ved augnesteinen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Sjå, eg lyfter handi mi mot deim, og dei skal verta til herfang for trælarne sine, og de skal få kjenna at Herren, allhers drott, hev sendt meg. Ropa høgt av frygd og gleda, du dotter Sion! For sjå, eg kjem og vil bu hjå deg, segjer Herren. Og mange heidningfolk skal venda seg til Herren på den dagen og verta mitt folk; ja, eg vil bu hjå deg, og du skal få kjenna at Herren, allhers drott, hev sendt meg til deg. Og til sin eigedom og arvlut skal Herren taka Juda i det heilage landet og endå ein gong velja ut Jerusalem. Ver stilt, alt kjøt, for Herren! For han hev rise upp og gjenge ut or sin heilage bustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'So let han meg sjå Josva, øvstepresten. Han stod framfor Herrens engel, og ved høgre sida hans stod Satan og vilde klaga honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Men Herren sagde til Satan: «Herren skal skjella deg ut, Satan! Herren skal skjella deg ut, han som hev valt ut Jerusalem! Er ikkje denne ein brand som er berga ut or elden?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Men Josva var klædd i skitne klæde der han stod framfor engelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Då tok engelen til ords og sagde til deim som stod framfor honom: «Tak av honom dei skitne klædi!» Og til honom sjølv sagde han: «Sjå, eg hev teke burt syndeskuldi di, og no skal du klædast i høgtidsbunad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Då sagde eg: «Å, set ei rein huva på hovudet hans!» Og dei sette den reine huva på hovudet hans og hadde på honom klædi, medan Herrens engel stod der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Og Herrens engel vitna for Josva og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '«So segjer Herren, allhers drott: Dersom du gjeng på mine vegar og held mine fyresegner, so skal du både få styra mitt hus og vakta mine fyregardar, og eg skal gjeva deg lov til å ferdast millom desse som her stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Høyr no, Josva, du øvsteprest! Du og dine felager som sit her framfyre deg, skal vera teikn og fyrebod; for sjå, eg vil lata tenaren min, Renning koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'For sjå, den steinen som eg hev lagt framfor Josva - på denne eine steinen vaker sju augo - på denne steinen ritar eg innskrifti som høyrer til, segjer Herren, allhers drott, og eg taka burt syndeskuldi åt dette landet på ein einaste dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'På den dagen, segjer Herren, allhers drott, skal kvar og ein av dykk kunna beda venen sin til gjestebod under vintreet og fiketreet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Sidan kom engelen som tala med meg, og vekte meg att liksom ein mann vert vekt or svevnen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'og han sagde til meg: «Kva ser du?» Eg svara: «Eg ser ein ljosestake som er heilt av gull, med oljeskåli si på toppen og sine sju lampor, og med sju røyrer som gjeng til lamporne der ovantil,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'og tvo oljetre stend attved, eitt på høgre sida av oljeskåli og eitt på vinstre sida.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Og eg tok til ords og spurde engelen som tala med meg: «Kva skal desse ting tyda, herre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Engelen som tala med meg, svara og sagde til meg: «Skynar du ikkje kva dette tyder?» Eg svara: «Nei, herre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Då tok han til ords og sagde til meg: «Dette er Herrens ord til Zerubbabel: Ikkje med magt og ikkje med kraft, men med min ande, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Kven er du, du store fjell som reiser deg mot Zerubbabel? Jamna deg ut til ei sletta! Han skal føra fram toppsteinen medan dei ropar: «Nåde, nåde vere med honom!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Og Herrens ord kom til meg soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Zerubbabels hender hev tufta dette huset; hans hender skal ogso fullenda det, og du skal få kjenna at Herren, allhers drott, hev sendt meg til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'For kven vil vanvyrda dagen som tok til i det små, når desse sju med gleda ser blyloddet i Zerubbabels hand, desse Herrens augo som fer ikring yver heile jordi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Då tok eg til ords og sagde til honom: «Kva skal dei tyda desse tvo oljetrei på høgre og vinstre sida av ljosestaken?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Og eg tok atter til ords og spurde honom: «Kva skal dei tyda desse tvo oljegreinerne tett attved dei tvo gullrøyrerne som det renn gull ned ifrå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Då sagde han til meg: «Kva? Veit du ikkje kva desse skal tyda?» Eg svara: «Nei, herre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Då sagde han: «Det er dei tvo olje-sønerne som stend hjå herren yver all jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Sidan lyfte eg atter upp augo mine og fekk sjå ein fjukande bokrull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'og han sagde til meg: «Kva ser du?» Eg svara: «Eg ser ein fjukande bokrull, som er tjuge alner lang og ti alner breid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Då sagde han til meg: «Dette er forbanningi som gjeng ut yver heile landet; for i samhøve med henne skal kvar den som stel verta reinska burt her ifrå, og i samhøve med henne skal kvar den som sver verta reinska burt her ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Eg hev sendt henne ut, segjer Herren, allhers drott, og ho skal ganga inn i huset til tjuven og inn i huset til den som gjer rang eid ved mitt namn, og ho skal setja seg fast der i huset og øydeleggja det, både tre og stein.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Sidan kom han fram den engelen som tala med meg, og sagde til meg: «Lyft upp augo dine og sjå kva det er som kjem fram der!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Eg spurde: «Kva er det?» Han svara: «Det er skjeppa som kjem fram.» Og han sagde: «Soleis ser det ut med deim i heile landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Sjå, då vart eit rundt blylok lyft upp, og der var ei kvinna som sat i skjeppa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Då sagde han: «Dette er gudløysa.» Og so tok han og slengde henne ned i skjeppa og slo blyloket yver opningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Då eg sidan lyfte upp augo mine, fekk eg sjå tvo kvinnor som kom fram, og vinden fyllte vengjerne deira - for dei hadde vengjer som storkevenger - og dei tok og lyfte skjeppa upp millom himmel og jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Då spurde eg engelen som tala med meg: «Kvar skal dei av med skjeppa?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Han svara: «Dei skal byggja eit hus åt henne i Sinearlandet, og når det er ferdigt, skal ho setjast ned der på sin stad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Då eg atter lyfte upp augo mine, fekk eg sjå fire vogner som kom fram millom tvo fjell, og fjelli var av kopar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'For den fyrste vogni var det raude hestar, for den andre vogni svarte hestar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'for den tridje vogni kvite hestar, og for den fjorde vogni var det flekkute sterke hestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Då tok eg til ords og sagde til engelen som tala med meg: «Kva skal dette tyda, Herre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Og engelen svara og sagde til meg: «Det er dei fire himmelvindarne. Dei hev vore kalla inn for Herren yver all jordi og fer no av stad att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Vogni med dei svarte hestarne fer ut mot Norderlandet, dei kvite fylgjer etter deim, og dei flekkute fer utimot Sudlandet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Men då dei sterkaste skulde fara ut, var dei fysne etter å få fara ikring på jordi, og han sagde: «Gakk, far ikring på jordi!» Og dei for ikring på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'So ropa han høgt på meg og sagde til meg: «Sjå, dei som fer ut imot Norderlandet, hev svala min harm på Norderlandet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Og Herrens ord kom til meg soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Tak imot av Heldai, Tobia og Jedaja gåvorne frå dei landlyste, ja, gakk sjølv på denne dagen av stad til huset åt Josias Sefanjason; for dit er dei komne frå Babel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'og tak imot sylv og gull! Få so gjort ei kruna og set henne på hovudet åt øvstepresten Josva Jesadaksson!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Og seg til honom: «So segjer Herren, allhers drott: Sjå der er ein mann som heiter Renning. Frå roti si skal han renna upp, og han skal byggja Herrens tempel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ja, han skal byggja Herrens tempel, og han skal vinna herlegdom og sitja og styra på kongsstolen sin, og han skal vera prest på kongsstolen sin, og freds samråd skal det vera millom deim båe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Men kruna skal vera i Herrens tempel til minne um Helem, Tobia og Jedaja og Hen Sefanjason.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Og langt burtanfrå skal dei koma og byggja på Herrens tempel, og de skal få kjenna at Herren, allhers drott, hev sendt meg til dykk. Og dette skal henda dersom de høyrer vel på røysti åt Herren, dykkar Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'I det fjorde styringsåret åt kong Darius kom Herrens ord til Zakarja, på den fjorde dagen i den niande månaden, i månaden kislev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Då sende Betel Sareser og Regem-Melek og mennerne hans av stad til å blidka Herren');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'og spyrja prestarne i huset åt Herren, allhers drott, og profetarne: «Skal eg gråta og fasta i den femte månaden som me hev gjort no i mange, mange år?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Då kom ordet frå Herren, allhers drott, til meg soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Seg du til alt folket i landet og til prestarne: Når de no i sytti år hev halde faste- og gråtedagar i femte og sjuande månaden, er det då for meg de hev fasta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Og når de et, og når de drikk, er det då ikkje de sjølve som et og drikk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Var det ikkje dei ordi Herren kunngjorde gjenom dei fyrre profetarne, då folk budde i fred og tryggleik i Jerusalem og i landsbyarne rundt ikring, og i Sudlandet og Låglandet like eins?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Og Herrens ord kom til Zakarja soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Soleis tala Herren, allhers drott: Seg rettvise domar og ver kjærlege og miskunnsame mot kvarandre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Enkjor og farlause, framandfolk og fatige må de ikkje vera harde med, og ikkje tenkja ut vondt mot kvarandre i hjarta dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Men dei vilde ikkje høyra, og dei sette ein stiv nakke imot; dei gjorde øyro sine dauve, so dei skulde sleppa å høyra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'ja, hjarto sine gjorde dei harde som demant, so dei skulde sleppa å høyra lovi og dei ordi som Herren, allhers drott, sende ved sin ande gjenom dei fyrre profetarne. Då kom det ein stor vreide frå Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Og av di dei ikkje vilde høyra når han ropa, so sagde no Herren, allhers drott: Eg vil ikkje høyra når dei ropar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'men eg skal føykja deim burt millom alle heidningfolki som dei ikkje kjenner, og landet skal liggja audt etter deim, so ingen fer att og fram. Soleis gjorde dei det herlege landet til ei øydemark.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Og Herren, allhers drott, sende ordet sitt soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'So segjer Herren, allhers drott: Eg er mykje, mykje ihuga for Sion, ja, med brennande harm er eg ihuga for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'So segjer Herren: Eg vil venda attende til Sion og taka bustad i Jerusalem, og Jerusalem skal heita «Truskapsbyen» og fjellet åt Herren, allhers drott, «Heilagfjellet».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'So segjer Herren, allhers drott: Atter skal gamle menner og gamle kvinnor sitja på torgi i Jerusalem, alle med stav i hand for deira alderdom skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'og torgi i byen skal vera fulle av gutar og gjentor som leikar seg der på torgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'So segjer Herren, allhers drott: Um dette kjem til å synast umogelegt for leivningen av dette folket i dei dagar, skulde det då og synast umogelegt for meg? segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'So segjer Herren, allhers drott: Sjå, eg skal frelsa folket mitt frå Austerheimen og Vesterheimen');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'og føra deim heim, og dei skal bu i Jerusalem og vera mitt folk, og eg skal vera deira Gud i truskap og rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'So segjer Herren, allhers drott: Lat dykkar hender vera sterke, de som i denne tid høyrer desse ordi av dei same profetarne som tala på den dagen då grunnsteinen vart lagd til huset åt Herren, allhers drott, templet, som skulde byggjast upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Fyre desse dagarne hadde korkje folk eller fe løn for strævet sitt, og korkje den som gjekk ut eller den som gjekk inn var trygg for fienden; for eg slepte alle menneskje laus på kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Men no vil eg ikkje vera som i dei framfarne tider mot leivningen av dette folket, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Nei, trygt skal sædet vera: Vintreet skal gjeva si frukt og jordi si grøda, himmelen skal gjeva si dogg, og eg skal gjeva leivningen av dette folket alt dette til eiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Då skal det henda: liksom de hev vore ei forbanning millom folki, både Judas hus og Israels hus, so vil eg no frelsa dykk, og de skal verta ei velsigning. Ottast ikkje! Lat dykkar hender vera sterke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'For so segjer Herren, allhers drott: Liksom eg sette meg fyre å gjera vondt imot dykk, då federne dykkar gjorde meg harm, og eg ikkje angra på det, segjer Herren, allhers drott,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'soleis hev eg no i desse dagarne sett meg fyre å gjera vel imot Jerusalem og Judas hus. Ottast ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Dette er det de skal gjera: Tala sanning med kvarandre! Seg rette og fredsæle domar i portarne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Tenk ikkje på vondt mot kvarandre i hjarta dykkar, og hav ikkje hug til rang eid! For alt slikt hatar eg, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Og ordet frå Herren, allhers drott, kom til meg soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'So segjer Herren: Fasta i den fjorde, femte, sjuande og tiande månaden skal verta Judas hus til frygd og gleda og gilde høgtider. Men elska sanningi og freden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'So segjer Herren, allhers drott: Endå skal det verta so at folkeslag skal koma, ja, folk frå mange byar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'og folket i den eine byen skal fara til den andre og segja: «Kom, lat oss ganga av stad og blidka Herren og søkja Herren, allhers drott!» «Eg vil ganga, eg og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Og då skal det koma mange folkeslag og mannsterke heidningfolk og søkja Herren, allhers drott, i Jerusalem, og blidka Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'So segjer Herren, allhers drott: I dei dagarne skal det henda at ti mann av alle dei tungemål som vert tala millom heidningfolk, tek fat i kjolesnippen åt ein mann frå Juda og segjer: «Me vil ganga med dykk; for me hev høyrt at Herren er med dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Ei framsegn, Herrens ord mot Hadraks land, og i Damaskus skal det slå seg ned; for Herren hev auga med manneætti og med alle Israels ætter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'ja, ogso Hamat som ligg attved, Tyrus og Sidon, so kloke dei er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tyrus bygde seg ei borg, dunga i hop sylv som mold og gull som gateskarn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Sjå, Herren vil arma henne ut, kasta ringmuren hennar i havet, og ho sjølv skal verta til føda for elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askalon skal sjå det og ottast, og Gaza vrida seg i stor rædsla; likeins Ekron, av di hennar von hev vorte til skammar, Gaza skal missa kongen sin, Askalon skal verta folketom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Og Asdod skal hysa berre herk; ja, eg vil gjøra enda på storlætet åt filistarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Eg vil taka blodet ut av munnen deira og styggedomen burt frå tennerne deira; og då skal dei og verta ein leivning for vår Gud. Då skal dei verta liksom ættehovdingar i Juda, og Ekron skal vera som ein jebusitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Og eg skal lægra meg og verja huset mitt mot herar som kjem og gjeng, og ikkje meir skal nokon valdsherre velta seg inn yver deim; for no hev eg set med eigne augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Gled deg storleg, du dotter Sion! Ropa av frygd, du dotter Jerusalem! Sjå, kongen din kjem til deg; rettferdig og frelst er han. Smålåten kjem han ridande på eit asen, på ein ung asenfole.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Eg vil rydja burt stridsvognerne frå Efraim og hestarne frå Jerusalem, og alle stridsbogarne skal rydjast burt; han skal tala fred til folki, og hans herrevelde skal nå frå hav til hav og frå Storelvi til verdsens endar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'For ditt paktblod skuld vil eg og fria dine fangar ut or brunnen der det ikkje finst vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Vend attende til den faste borgi, de fangar som hev von! Ogso i dag gjer eg kunnigt: Eg skal gjeva deg tvifelt att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'For eg spenner Juda som ein boge, fyller Efraim som eit pilehus, og dine søner, du Sion, eggjar eg mot dine søner, du Javan, og eg gjer deg lik med sverdet åt ei kjempa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Ja, Herren skal syna seg yver deim, og pili hans fer ut som ein elding, Herren, Herren skal blåsa i luren og fara fram i sunnanstormarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Herren, allhers drott, skal halda skjolden sin yver deim, og dei skal gløypa, med di dei trakkar slyngjesteinar under føter; dei skal drikka og ståka som av vin og verta fulle som offerskåler og altarhyrno.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Ja, Herren, deira Gud, skal gjeva deim siger på denne dag; for dei er då det folket han hev teke til si hjord, og liksom glimesteinar i ei kruna strålar yver landet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Å, kor gildt og kor fagert det er! Kornet gjev ungguten merg i bein, og druvesafti fostrar upp fagre møyar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Herren må de beda um regn i tidi for vårregnet, Herren er det som skaper torever, og han sender fossande flod-skurer, gjev grøda på marki for kvar ein mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Men husgudarne talar fåfengd, og spåmennerne ser falske syner. Tome draumar talar dei, og svikfull er deira trøyst. Difor laut dei reika ikring som ein saueflokk og lida vondt av di det ikkje er nokon hyrding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Mot hyrdingarne er harmen min kveikt, og bukkarne vil eg heimsøkja, ja, Herren, allhers drott, ser til si hjord, Judas hus, og gjera henne til stashesten sin i striden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Frå det skal koma hyrnestein, frå det skal koma nagle, frå det skal koma stridsboge, frå det skal kvar einaste styresmann koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Og dei skal vera lik kjempor som gjeng fram i striden nett som dei trakka i gateskarn; ja, strida skal dei; for Herren er med deim, og dei som rid på hestar, skal verta til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Og eg vil gjera Judas hus sterkt, og Josefs hus skal eg frelsa; ja, eg fører deim atter heim; for eg vil miskunna deim, og dei skal vera liksom eg aldri hadde støytt deim burt. For eg er Herren, deira Gud, og eg skal bønhøyra deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efraims menner skal verta lik velduge kjempor, og hjarto deira skal gleda seg liksom av vin. Sønerne deira skal sjå det med fagnad; deira hjarto skal frygda seg i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Eg vil blistra på deim og samla deim; for eg hev løyst deim ut, og dei skal verta likso mangmente som dei fordom var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Eg vil så deim ut millom folki; men på dei framande stader skal dei minnast meg, og dei skal liva med borni sine og venda heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Ja, eg let deim koma heim frå Egyptarland, og frå Assur skal eg samla deim; til Gileadlandet og til Libanon fører eg deim, og der skal det skorta på rom åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Han skal draga fram gjenom havet i trengsla; bylgjorne skal slå ned i havet, og alle djupi i Nilen skal turkast ut; Assurs byrgskap skal støytast ned, og kongsstaven skal vika frå Egyptarland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Men deim skal eg gjera sterke i Herren, og i hans namn skal dei ferdast, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Lat upp portarne dine, Libanon, so elden kann øyda cedertrei dine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Jamra deg, du cypressa, for cederen er fallen, dei herlege trei avøydde! Jamra dykk, de Basan-eiker: for tjukkaste skogen er sokken!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Høyr, kor hyrdingarne jamrar; for di deira herlegdom er lagd i øyde! Høyr, kor dei unge løvorne burar; for Jordans prydnad er herja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'So sagde Herren min Gud: Røkta slagtesauerne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'For dei som kjøper deim, slagtar deim utan å bøta for det, og dei som sel deim segjer: «Lova vere Herren! Eg vert då rik!» Og hyrdingarne deira sparer deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'For no vil eg ikkje meir spara folket i landet, segjer Herren; men eg vil lata menneski falla i henderne på kvarandre og i henderne på kongen sin, og dei skal øyda landet, og eg vil ikkje fria frå deira vald.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'So tok eg til å røkta slagtesauerne, ja, dei ringaste av sauerne, og eg tok meg tvo stavar, den eine kalla eg Godvilje, og den andre kalla eg Sameining. Eg gjætte då sauerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'og eg gjorde dei tri hyrdingarne til inkjes på ein månad. Då leiddest eg ved deim, og dei stygdest og ved meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'og so sagde eg: «Eg vil ikkje lenger vera hyrdingen dykkar. Lat dei døy som vil døy, og lat det øydast som vil øydast, og dei som vert att, fær eta kvarandre upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'So tok eg staven min Godvilje og braut honom sund til å løysa upp pakti som eg hadde gjort med alle folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Og ho vart gjord til inkjes same dagen, og då fekk dei sanna dei arme sauerne som ansa på meg, at det var Herrens ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Dinæst sagde eg til deim: «Um de so synest, so gjev meg løni mi, og synest de ikkje det er verdt, so lat det vera!» Då vog dei upp tretti sylvdalar til løn åt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Då sagde Herren til meg: Sleng honom burt til pottemakaren, den herlege prisen som dei hev verdsett meg til! Og eg tok dei tretti sylvdalarne og kasta deim inn i Herrens hus, burt til pottemakaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'So braut eg sund den andre staven min, Sameining, til å løysa upp brorskapen millom Juda og Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Og Herren sagde til meg: Tak deg no atter hyrdingreidskap, som ein skarvehyrding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'For sjå, eg let ein hyrding risa upp i landet, ein som ikkje bryr seg um dei burtkomne, ikkje leitar etter dei villfarne, ikkje heilar dei brotne og ikkje syter for dei friske; men kjøtet av dei feite et han, og klauverne deira riv han av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Usæl den skarvehyrdingen som svik sauerne! Sverd yver armen hans og yver høgre auga hans! Visna, ja, visna skal armen hans, og høgre auga hans verta blindt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Ei framsegn, Herrens ord um Israel. So segjer Herren som spana ut himmelen, grunnfeste jordi og skaper ånd i mannebarm:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Sjå, eg gjer Jerusalem til ei tumleskål for alle folki rundt ikring, og jamvel yver Juda skal det koma når Jerusalem vert kringsett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'På den dagen skal eg gjera Jerusalem til ein lyftestein for alle folki; alle dei som lyfter på honom, skal riva seg sund, og alle folki på jordi skal flokka seg imot det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'På den dagen, segjer Herren, skal eg slå alle hestarne med villska og hestfolki med vitløysa; men yver Judas hus skal eg vaka, og alle hestarne åt folki slær eg med blindskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Då skal ættehovdingane i Juda segja med seg sjølve: «Vår styrke er dei som bur i Jerusalem, ved Herren, allhers drott, deira Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'På den dagen skal eg lata ættehovdingarne i Juda verta liksom ei glodpanna i ein vedhaug og ein brennande kyndel midt i ein halmdunge, og dei skal brenna upp alle folki rundt ikring; men Jerusalem skal framleides bu trygt på sin stad, i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Og fyrst skal Herren frelsa tjeldi åt Juda, so ikkje Davids hus og dei som bur i Jerusalem, skal få større heider enn Juda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'På den dagen skal Herren halda skjolden sin yver deim som bur i Jerusalem, og den veikaste stakkaren millom deim skal på den dagen vera som David, og Davids hus som Gud, som Herrens engel framfyre deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Og på den dagen skal eg trå etter å tyna alle heidningfolki som fer imot Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Men yver Davids hus og yver deim som bor i Jerusalem, skal eg renna ut nåde-anden og bøne-anden, so dei ser upp til meg som dei hev gjenomstunge, og dei skal syrgja på honom som ein syrgjer på den einborne, og klaga sårt som ein klagar yver fyrstefødde sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'På den dagen skal jammeren verta stor i Jerusalem liksom jammeren ved Hadadrimmon på Megiddosletta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Og landet skal syrgja, kvar ættgrein for seg: ættgreini frå Davids hus for seg og deira kvinnor for seg, ættgreini frå Natans hus for seg og deira kvinnor for seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'ættgreini frå Levis hus for seg og deira kvinnor for seg, Sime’is ættgrein for seg og deira kvinnor for seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'like eins alle dei andre ættgreinerne for seg og kvinnorne deira for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'På den dagen skal det vera ei opi kjelda for Davids hus og for deim som bor i Jerusalem til å tvætta av synd og ureinskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Og på den dagen, segjer Herren, allhers drott, skal eg rydja ut namni på avgudsbilæti or landet, so ingen meir skal minnast deim, ja, ogso profetarne og den ureine åndi skal eg senda ut or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Og um nokon sidan gjev seg til å spå, so skal far hans og mor hans, hans eigne foreldre, segja til honom: «Du kann ikkje få liva; for du hev tala lygn i Herrens namn.» Og far hans og mor hans, hans eigne foreldre, skal stinga honom ned når han gjev seg til å spå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'På den dagen skal alle profetarne skjemmast ved synerne sine når dei spår, og dei skal ikkje klæda på seg ein hårkyrtel for å ljuga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Men kvar og ein av dei skal segja: «Eg er ikkje nokon profet. Ein jorddyrkar er eg. Ein mann som kjøpte meg til træl då eg var berre ungguten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Og um ein spør honom: «Kva er det for nokre sår du hev der på bringa di?» so kjem han til å svara: «Deim hev eg fenge i huset hjå venerne mine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Vakna upp, du sverd, mot hyrdingen min, mot den mannen som stend meg so nær, segjer Herren, allhers drott. Slå hyrdingen, og lat sauerne spreidast, og eg skal hava handi mi mot dei små.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Og i heile landet, segjer Herren, skal tvo tridjepartar øydast og andast; men ein tridjepart skal leivast der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'og denne tridjeparten let eg ganga gjenom elden og skirer honom som ein skirer sylv, og prøver honom som ein prøver gull. Dei skal kalla på mitt namn, og eg skal svara deim; eg skal segja: «Dette er mitt folk;» og dei skal svara: «Herren er min Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Sjå, det kjem ein Herrens dag då dei skal skifta ut ditt herfang inne i deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Då skal eg samla alle folkeslagi til strid imot Jerusalem, og byen skal verta herteken, husi skal verta herja, og kvinnorne skal verta valdtekne. Og halve byen skal førast burt i utlægd; men leivningen av folket skal ikkje rydjast ut or byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Og Herren skal fara ut og strida mot desse folki som han stridde fyrr på slagdagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'På den dagen skal han standa med føterne på Oljeberget, som ligg beint imot Jerusalem på austsida, og Oljeberget skal klovna midt i tvo frå aust til vest, so det vert ein ovleg stor dal, av di eine helvti av fjellet vik undan mot nord og andre helvti mot sud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Og de skal røma til dalen millom fjelli mine; for dalen millom fjelli skal nå heilt til Asel; ja, de skal røma som de rømde for jordskjelven i dei dagarne då Uzzia var konge i Juda. Då skal han koma, Herren, min Gud - alle heilage med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'På den dagen skal det ikkje vera noko ljos; stjernorne skal kverva burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Og det skal koma ein viss dag - han er kjend av Herren - ein dag då det korkje er dag eller natt; men når det lid til kvelds, då skal det verta ljost.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Og på den dagen skal det strøyma livande vatn ut frå Jerusalem, den eine helvti av det til Austerhavet og den andre helvti til Vesterhavet; både sumar og vinter skal det renna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Då skal Herren vera konge yver heile jordi; på den dagen skal Herren vera ein og namnet hans eitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Heile landet skal verta som Jordan-kverven, frå Geba til Rimmon sunnanfor Jerusalem; og byen sjølv skal lyfta seg høgt og liggja på sin stad, radt ifrå Benjamins-porten og til den staden der Gamleporten var, til Hyrneporten, og frå Hananeltårnet og til vinpersorne åt kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Og folket skal bu der, og det skal ingi bannlysing vera meir, og Jerusalem skal liggja der trygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Men denne refsingi skal Herren senda yver alle dei folki som drog i herferd mot Jerusalem: Kjøtet deira skal han lata rotna, medan dei stend på sine føter, augo deira skal rotna i holorne sine, og tunga skal rotna i munnen på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'På den dagen skal ei stor rædsla frå Herren koma yver deim, so dei grip fat i kvarandre og lyfter hand mot kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Ogso Juda skal strida i Jerusalem, og då skal han samlast, rikdomen frå alle heidningfolki rundt ikring, gull og sylv og klæde i stor mengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Den same refsingi skal og koma yver hestarne og muldyri og kamelarne og asni og alle dei andre dyr som finst der i lægri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Og alle dei som vert att av alle heidningfolki som gjorde åtak på Jerusalem, dei skal år etter år fara dit upp og beda til kongen, Herren, allhers drott, og høgtida lauvhyttehelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Og um nokre av ætterne på jordi ikkje fer upp til Jerusalem og bed til kongen, Herren, allhers drott, so skal det ikkje koma regn hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Dersom egyptarfolket ikkje gjeng upp og ikkje møter fram, so skal den same refsingi koma yver deim som Herren let koma yver dei heidningfolki som ikkje fer upp og høgtidar lauvhyttehelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Dette er syndestraffi for Egyptarland og for alle heidningfolki som ikkje fer upp og høgtidar lauvhyttehelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'På den dagen skal det standa på bjøllerne åt hestarne: «Vigd åt Herren,» og grytorne i Herrens hus skal vera som offerskålerne framfor altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Og kvar einaste gryta i Jerusalem og Juda skal vera vigd åt Herren, allhers drott, so alle dei som ofrar, kann koma og taka av deim og koka i deim, og det skal ikkje meir finnast nokon kræmer i huset åt Herren, allhers drott, på den dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Ei framsegn. Herrens ord til Israel ved Malaki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Eg hev elska dykk, segjer Herren. Og de spør: «Korleis hev du elska oss?» Er ikkje Esau bror åt Jakob? segjer Herren. Og eg elska Jakob,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'men Esau hata eg, og eg hev gjort hans fjell til ei øydemark og odelen hans til ein heidebustad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Når Edom segjer: «Me ligg i røys, men me skal byggja røyserne upp att,» då svarar Herren, allhers drott: Dei byggjer, men eg riv ned; dei skal heita Gudløyselandet og folket som Herren er æveleg harm på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'De skal sjå det med eigne augo, og de skal segja: «Herrens velde når ut yver Israels grensa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Ein son ærar far sin og ein tenar herren sin. Er no eg far, kvar er då mi æra, og er eg herre, kvar er då otten for meg? segjer Herren, allhers drott, til dykk, de prestar som vanvyrder namnet mitt. Og de spør: «Korleis hev me vanvyrdt namnet ditt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Jau, de ber fram sulka mat på altaret mitt. Og de spør: «Kva hev me sulka deg med?» Jau, de segjer: «Herrens bord er ikkje vyrdande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Um de kjem med eit blindt dyr til offer, so er ikkje det noko gale, og kjem de med eit halt og eit sjukt, so er det ikkje noko gale.» Kom med sovorne gåvor til jarlen din! Skal tru han vert blid på deg eller tek vel imot deg? segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'So blidka no Gud, at han må vera oss nådig! Med eigne hender hev de gjort slikt, kann han då taka vel mot dykk? segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Å, um det fanst nokon millom dykk som vilde stengja dørerne, so de slapp å gjera upp eld til fåfengs på altaret mitt! Eg hev ingen hugnad i dykk, segjer Herren, allhers drott, og offergåva frå dykkar hand likar eg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'For frå solekoma til soleglad er mitt namn stort millom folki, og på kvar ein stad vert det frembore røykoffer åt namnet mitt og rein offergåva; for namnet mitt er stort millom folkeslagi, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Men de vanhelgar det med di de segjer: «Herrens bord er sulka, og maten som fell av frå det, er ikkje vyrdande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, '«Å, for ei møda!» segjer de, og de blæs åt det, segjer Herren, allhers drott; og når de ber fram offergåvor, kjem de med det som de hev rana, det som er halt og sjukt. Skulde eg hava hugnad i slike gåvor frå dykkar hand? segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Nei, forbanna vere den som fer med svik, som eig handyr i buskapen og hev gjort ein lovnad, men so ofrar til Herren eit gjelddyr. Ein stor konge er eg, segjer Herren, allhers Gud, og namnet mitt er skræmeleg millom folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Og no kjem dette bodet til dykk prestar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Vil de ikkje høyra og ikkje leggja dykk på hjarta å gjeva mitt namn æra, segjer Herren, allhers drott, so sender eg forbanningi yver dykk, og eg forbannar velsigningarne dykkar; ja, eg hev alt forbanna deim, av di de ikkje legg det på hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Sjå, eg bannar avkjømet dykkar og kastar møk i andlitet på dykk, møk av dykkar høgtidsoffer, og dei skal bera dykk burti møki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Då skal de sanna at eg hev sendt dykk dette bodet, av di det skal vera mi pakt med Levi, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mi pakt med honom var liv og fred. Eg gav honom deim til otte, og han ottast meg og skalv for mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Sannings læra var i hans munn, og det fanst ikkje svik på lipporne hans; fredsamt og ærleg gjekk han på min veg, og han vende mange burt ifrå misgjerd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'For prestelippor skal gøyma på kunnskap, upplæring ventar me av munnen hans, for han er sendebod frå Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Men de hev vike av frå vegen, læra dykkar hev ført mange til fall; de hev skjemt ut Levi-pakti, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Difor hev eg og gjort dykk vanvyrde og nedsedde for alt folket, av di de ikkje agtar på mine vegar, men gjer skil på folk i lovlæra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Hev ikkje me ein far alle saman? Hev ikkje ein Gud skapt oss? Kvi fer me då med svik mot kvarandre og vanhelgar fedrepakti?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Svik hev Juda fare med, og styggedom hev gjenge for seg i Israel og i Jerusalem; for Juda hev vanhelga Herrens heilagdom, som han elskar, og hev gift seg med dotter til ein framand gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Hjå den mannen som gjer slikt - måtte Herren rydja ut kvar livande sjæl or Jakobs hyttor, og den som ber fram offergåva til Herren, allhers drott!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Og endå ein ting til gjer de: Yver Herrens altar legg de tåror og gråt og sukkar, so han vil venda seg til offergåva meir eller med hugnad tek imot noko av dykkar hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'De spør: «Korleis då?» Jau, Herren hev vore vitne millom deg og ditt ungdomsviv, henne som du hev svike, endå ho var festarmøyi di og egtemaken din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Hev ikkje den eine og same skapt henne, med di han hadde endå meir ånd att? Og kva stila han på, den eine? Guddomleg ætt. Tak då vare på dykkar liv og svik ikkje ditt ungdomsviv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Eg hatar skilsmål, segjer Herren, Israels Gud; med det sveiper ein vald um klædi sine, segjer Herren, allhers drott. So tak då vare på dykkar liv og far ikkje med svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'De trøyttar Herren med dykkar ord. De spør: «Korleis trøytta me?» Jau, de segjer: «Kvar den som gjer vondt, er god i Herrens augo, og han hev hugnad i deim. Kvar er elles Gud som held dom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Sjå, eg sender mitt bod, og han skal brøyta veg for meg. Og brått kjem han til sitt tempel, Herren som de leitar etter, og paktengelen som de stundar på, sjå, han kjem, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Men kven kann herda den dagen han kjem? Og kven kann standa når han syner seg? For han er som smeltar-eld og tvættar-lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Han sit og smeltar og reinsar sylvet, han reinsar Levi-sønerne og skirar deim som gull og sylv, so dei kann bera fram for Herren offergåvor i rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Då vert offergåvorne i Juda og Jerusalem til hugnad for Herren som i gamle dagar og i framfarne år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Eg kjem til dykk og held dom og vert eit snøgt vitne mot deim som fer med trolldom, som bryt egteskapet, som gjer rang eid, som held att løni for leigekaren, som er harde med enkja og den faderlause, som rengjer retten for utlendingen og ikkje ottast meg, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'For eg, Herren, er ikkje umskift, og de, Jakobs-born, er ikkje til ende komne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Alt ifrå fedre-dagarne hev de vike av frå loverne mine og ikkje halde deim. Vend um til meg, so skal eg venda um til dykk, segjer Herren, allhers drott. De spør: «Kva skal me venda um ifrå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Skal eit menneskje rana frå Gud, sidan de hev rana frå meg? Og de spør: «Kva hev me rana frå deg?» Jau, tiendi og reidorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Forbanningi hev råka dykk, og frå meg ranar de, ja, heile folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Kom med heile tiendi til forrådshuset mitt, so det kann finnast mat i huset mitt, og prøv meg so på den måten, segjer Herren, allhers drott, um eg ikkje let upp himmellukorne åt dykk og renner yver dykk velsigning i rikt mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Eg skal truga etaren for dykk, so han ikkje tyner grøda på jordi for dykk, og ikkje heller skal de hava vanheppa med vintreet på marki, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Alle folki skal prisa dykk sæle, for det vert eit herlegt land, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'De hev bruka sterke ord imot meg, segjer Herren. Og de spør: «Kva hev me tala med kvarandre imot deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Jau, de segjer: «Det er fåfengt å tena Gud. Kva bate hev me av at me agtar på hans krav og gjeng syrgjeklædde for Herren, allhers drott?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Nei, no prisar me dei ovmodige sæle; dei hev medgang når dei liver i gudløysa, dei freistar Gud og slepp vel ifrå det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Då tala dei med kvarandre, dei som ottast Herren, og Herren lydde og høyrde på, og det vart skrive ei minnebok for hans åsyn um deim som ottast Herren og tenkjer på hans namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Og dei skal vera min eigedom, segjer Herren, allhers drott, på den dagen som eg skaper, og eg skal spara deim liksom ein mann sparer son sin som tener honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Då skal de atter sjå skil på den rettferdige og den gudlause, den som tener Gud og den som ikkje tener honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'For sjå, dagen kjem, brennande som ein omn; då skal alle ovmodige og kvar den som fer med gudløysa, verta halm, og dagen som kjem, skal brenna deim upp, segjer Herren, allhers drott, so det ikkje vert att av deim anten rot eller grein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Men for dykk som ottast mitt namn, skal rettferds-soli renna upp med lækjedom i vengjerne sine; og de skal ganga ut og hoppa som kalvar når dei slepp or fjøset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Og de skal trakka ned dei gudlause, for dei skal verta som oska under føterne dykkar på den dagen som eg skaper, segjer Herren, allhers drott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Kom i hug lovi åt Moses, tenaren min, som eg gav honom på Horeb for heile Israel med bod og rettar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Sjå, eg sender dykk profeten Elia fyrr Herrens store og skræmelege dag kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Han skal venda fedrehjarto til borni og barnehjarto til federne, so eg ikkje skal koma og slå landet med bann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Soga um Jesus Kristus. Davids son og Abrahams son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham fekk sonen Isak, og Isak fekk sonen Jakob, og Jakob fekk Juda og brørne hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'og Juda fekk sønerne Peres og Zerah med Tamar, og Peres fekk sonen Hesron, og Hesron fekk sonen Ram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'og Ram fekk sonen Amminadab, og Amminadab fekk sonen Nahson, og Nahson fekk sonen Salmon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'og Salmon fekk sonen Boaz med Rahab, og Boaz fekk sonen Obed med Rut, og Obed fekk sonen Isai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'og Isai var far åt David, kongen. David fekk sonen Salomo med kona åt Uria,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'og Salomo fekk sonen Rehabeam, og Rehabeam fekk sonen Abia, og Abia fekk sonen Asa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'og Asa fekk sonen Josafat, og Josafat fekk sonen Joram, og Joram fekk sonen Uzzia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'og Uzzia fekk sonen Jotam, og Jotam fekk sonen Ahaz, og Ahaz fekk sonen Hizkia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'og Hizkia fekk sonen Manasse, og Manasse fekk sonen Amon, og Amon fekk sonen Josia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'og Josia fekk Jekonja og brørne hans; dei livde i den tidi då folket vart ført til Babylon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Etter dei vart førde til Babylon, fekk Jekonja sonen Sealtiel, og Sealtiel fekk sonen Zerubbabel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'og Zerubbabel fekk sonen Abiud, og Abiud fekk sonen Eljakim, og Eljakim fekk sonen Asor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'og Asor fekk sonen Sadok, og Sadok fekk sonen Akim, og Akim fekk sonen Eliud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'og Eliud fekk sonen Eleazar, og Eleazar fekk sonen Mattan, og Mattan fekk sonen Jakob,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'og Jakob var far åt Josef, mannen hennar Maria som fødde Jesus til verdi, han me kallar Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Soleis er det i alt fjortan ættleder frå Abraham til David, og fjortan ættleder frå David til Babylon-ferdi, og fjortan ættleder frå Babylon-ferdi til Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Då Kristus vart fødd, gjekk det soleis til: Medan mor hans, Maria, var trulova med Josef, og fyrr dei kom i hop, synte det seg at ho var med barn av den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Josef, festarmannen hennar, var ein rett-tenkt mann, og vilde ikkje føra skam yver henne; han sette seg fyre å skiljast med henne so stilt han kunde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Men best som han hadde rådt seg til det, synte Herren engel seg for honom i draume og sagde: «Josef, Davids son, ver ikkje rædd å taka Maria, festarmøyi di, heim til deg; for det ho ber under beltet, er av den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Ho skal eiga ein son, og honom skal du kalla Jesus; for han skal frelsa folket sitt frå synderne deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Men alt dette hev hendt av di det laut sannast det som Herren hev tala gjenom profeten, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '«Ei møy mun barnsvon bera: Ein son ho eiga skal, og namnet han skal nemnast med, er Immanuel» - det er det same som: «Gud er med oss».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Då Josef vakna or svevnen, gjorde han som Herrens engel hadde sagt med honom, og flutte bruri si heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Men han kom ikkje nær henne fyrr ho hadde fenge sonen sin; honom kalla han Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Det var i Betlehem i Judalandet Jesus kom til verdi, i kong Herodes’ dagar. Då kom det nokre vismenner frå Austerlandi til Jerusalem og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '«Kvar er den jødekongen som nyst er fødd? Me såg stjerna hans i Austerland, og no er me komne og vil hylla honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Då kongen, Herodes, høyrde det, vart han forfærd, og heile Jerusalem med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Han kalla i hop alle dei øvste prestarne og alle skriftlærde i landet, og spurde deim kvar Messias skulde koma til verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, '«I Betlehem i Judalandet,» svara dei, «for so stend det skrive hjå profeten:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '«Du Betlehem, du Juda-bygd, av Juda-jarlarne er du visst ikkje ringaste i rang: Or deg ein fyrste skal gå fram som Israel, mitt eige folk, liksom ein hyrding gjæta skal.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Då kalla Herodes vismennerne til seg i løynd, og spurde deim ut um tidi då stjerna hadde synt seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'So styrde han deim i veg til Betlehem og sagde: «Far no dit, og høyr dykk vel fyre um barnet, og når de hev funne det, so seg meg til, so eg og kann koma og hylla det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Då dei hadde høyrt på kongen, tok dei i vegen, og best det var, fekk dei sjå den same stjerna som dei hadde set i Austerland; ho for fyre deim, til ho kom uppyver der som barnet var; der vart ho standande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Då vismennerne såg stjerna, vart dei so glade at dei aldri hadde vore so glade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Dei gjekk inn i huset, og fann barnet hjå mori, Maria. Då fall dei på kne, og hyllte barnet. Og dei let upp skrini, sine og bar fram for det gåvor: gull og røykjelse og myrra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Og Gud varsla deim i draume, at dei ikkje måtte fara attende til Herodes, og so tok dei ein annan veg heim att til landet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Vel dei var farne, so syner Herrens engel seg for Josef i draume og segjer: «Statt upp! Tak barnet og mori, og røm til Egyptarland, og ver der til eg segjer deg til! For Herodes kjem til å leita etter barnet og vil gjera ende på det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Då stod han upp, og same natti tok han barnet og mori og for til Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'og der vart han verande til Herodes var avliden, so det skulde sannast det som Herren hev tala gjenom profeten, når han segjer: «Or Egyptarland kalla eg min son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Då Herodes såg at vismennerne hadde havt honom til narr, vart han brennande harm. Han sende ut folk og let dei drepa alle guteborn i Betlehem og heile grannelaget på tvo år og derunder, etter den tidi han hadde fenge vita av vismennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Då vart det sanna det som Jeremia, profeten, hev tala, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '«Dei høyrde ei røyst i Rama - gråt og øying stor: Rakel ho gret for borni sine, og ansa’kje trøystarord; for burte er dei, burte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Då Herodes var avliden, syner Herrens engel seg i draume for Josef i Egyptarland og segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, '«Statt upp! Tak barnet og mori, og far til Israelslandet! For no er dei burte dei som leita etter barnet og vilde taka livet av det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'So stod han upp, og tok barnet og mori og for til Israelslandet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Men då han fekk spurt at Arkelaus hadde vorte konge i Judariket etter far sin, Herodes, torde han ikkje koma dit. Han gjorde som Gud sagde til honom i draume, og for burt til Galilæa-bygderne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'og då han kom til ein by som heiter Nasaret, vart han buande der. Soleis skulde det koma til å sannast det som er sagt gjenom profetarne, at han skulde kallast Nasaræar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'I den tidi steig Johannes, døyparen, fram og tala i Judaheidi');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'og sagde: «Vend um! For himmelriket er nær.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Det er honom Jesaja, profeten, talar um, når han segjer: «Høyr han som ropar i heidi: Rydje vegen åt Herren, jamne stigarne hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Johannes gjekk med ein kjole av kamelhår, og hadde eit lerbelte kring livet, og maten hans var grashoppar og villhonning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Då kom dei ut til honom frå Jerusalem og frå heile Judalandet og Jordan-kverven,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'og han døypte deim i Jordanåi, med dei sanna synderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Mange av farisæarane og sadducæarane kom og til dåpen hans. Då han såg deim, sagde han: «Kven lærde dykk å røma frå den vreiden som koma skal, de orme-ungar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Ber då frukt som svarar til umvendingi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'og tru ikkje de kann tenkja som so: «Me hev Abraham til far!» for eg segjer dykk at Gud kann vekkja upp born åt Abraham av desse steinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Øksi ligg alt innmed roti på treet; kvart tre som ikkje ber god frukt, vert hogge ned og kasta på elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Eg døyper dykk med vatn til umvending; men han som kjem etter meg, er sterkare enn eg; eg er ikkje verd å bera skorne hans - han skal døypa dykk med den Heilage Ande og eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Han hev kasteskovlen i handi, og skal gjera av låven sin; kornet skal han samla i stabburet, men agnerne skal han brenna i ein eld som aldri sloknar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'So kom Jesus frå Galilæa åt Jordan, til Johannes, og vilde få honom til å døypa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Men Johannes bar seg undan og sagde: «Eg treng dåp av deg, og so kjem du til meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, '«Lat det no vera so like vel!» svara Jesus. «For soleis lyt me i eitt og alt gjera det som er rett.» Då gjorde han som Jesus vilde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Med det same Jesus var døypt, steig han upp or vatnet. Då opna himmelen seg for honom, og han såg Guds Ande koma dalande nedyver seg som ei duva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'og ei røyst frå himmelen sagde: «Dette er Son min, han som eg elskar, han som eg hev hugnad i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Sidan førde Anden Jesus ut i øydemarki, so djevelen skulde freista honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Han fasta i fyrti dagar og fyrti næter, og vart hungrig då so langt leid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Og freistaren kom og sagde til honom: «Er du Guds Son, so seg at desse steinarne skal verta til brød!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Men han svara: «Det stend skrive: «Menneskja liver ikkje berre av brød, men av kvart ord som kjem frå Guds munn.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Då tok djevelen honom med seg til den heilage byen og sette honom ytst på tempeltaket, og sagde til honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, '«Er du Guds Son, so kasta deg utfyre! For det stend skrive: «Han englarn’ sine bjoda skal at dei på henderne deg ber, so aldri du på nokon stein skal turva støyta foten din.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jesus svara: «Det stend og skrive: «Du skal ikkje freista Herren, din Gud.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'So tok djevelen honom med seg upp på eit ovhøgt fjell, og synte honom alle verdsens rike og deira herlegdom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, '«Alt dette gjev eg deg, dersom du fell på kne og tilbed meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Då sagde Jesus til honom: «Gakk frå meg, Satan! For det stend skrive: «Herren, din Gud, skal du tilbeda; honom og ingen annan skal du tena.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'So for djevelen ifrå honom, og med det same kom englarne og tente honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Då Jesus fekk høyra at Johannes var gjeven i henderne på uvenerne sine, drog han seg undan og for til Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Sidan flutte han frå Nasaret og busette seg i Kapernaum, som ligg nedmed sjøen, på Sebulons og Naftalis grunn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'so det skulde sannast det som er tala gjenom Jesaja, profeten, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '«Sebulons og Naftalis land, som langs med sjøen ligg, og dei som burtum Jordan bur, og heidne bygdekrins -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'det folket som i myrker sat, so stort eit ljos fekk sjå; dei sat i daudens skoddeland, då rann for deim eit ljos.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Frå den tidi tok Jesus til å tala til folket og sagde: «Vend um! Himmelriket er nær!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Som han no ein gong gjekk frammed Galilæasjøen, fekk han sjå tvo brør, Simon, han som kallast Peter, og Andreas, bror hans; dei heldt på og kasta ei not i sjøen; for dei var fiskarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Han segjer til dei: «Kom og fylg meg! Eg vil gjera dykk til menneskje-fiskarar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Då gjekk dei beint frå garni sine og fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Då han kom lenger fram, såg han tvo andre brør, Jakob, son åt Sebedæus, og Johannes, bror hans: dei sat i båten hjå Sebedæus, far sin, og greidde garni sine. Han kalla deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'og med ein gong gjekk dei burt frå båten og frå far sin, og fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Sidan for han ikring i heile Galilæa og lærde folket i synagogorne deira, og forkynte evangeliet um riket, og lækte all sjukdom og vanhelsa hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Det gjekk gjetord um honom yver heile Syria, og dei kom til honom med alle som hadde vondt og drogst med eikor sott eller plåga, forgjorde og nedfall-sjuke og lamne, og han gjorde deim gode att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Og det fylgde honom ein stor folkehop frå Galilæa og Dekapolis og Jerusalem og Judalandet og bygderne på hi sida Jordan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Då Jesus såg folkehopen, gjekk han upp i fjellet; der sette han seg ned, og læresveinarne hans kom burt til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Då tok han til ords og lærde deim og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '«Sæle dei som er fatige i åndi! Himmelriket er deira!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Sæle dei som syrgjer! Dei skal verta trøysta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Sæle dei tolsame! Dei skal erva jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Sæle dei som hungrar og tyrster etter rettferd! Dei skal verta metta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Sæle dei miskunnsame! Dei skal få miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Sæle dei som er reine i hjarta! Dei skal sjå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Sæle dei fredkjære! Dei skal kallast Guds born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Sæle dei som vert forfylgde for rettferdi si! Himmelriket er deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Sæle er de når dei spottar dykk og forfylgjer dykk og talar berre vondt um dykk for mi skuld, og lyg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Ver glade og fegne! Stor er løni dykkar i himmelen. For soleis forfylgde dei dei profetarne som var til fyre dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'De er saltet på jordi! Vert saltet dove, kva skal so det saltast med? Det duger då ikkje til anna enn til å kastast ut og trakkast på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'De er ljoset i verdi. Den byen som ligg på eit fjell, kann ikkje dyljast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Ingen kveikjer eit ljos og set det under skjeppa, men i staken; då lyser det for alle som er i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Soleis skal de lata ljoset dykkar lysa for folk, so dei kann sjå dei gode gjerningarne dykkar og prisa Far dykkar i himmelen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'De må ikkje tru eg er komen for å avlysa lovi eller profetarne. Eg er ikkje komen for å avlysa, men for å fullføra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'For det segjer eg dykk for sant: Fyrr himmelen og jordi forgjengst, skal ikkje den minste bokstav, ikkje ein einaste prikk i lovi forgangast, fyrr alt saman er fullgjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Um då nokon bryt eit einaste av desse minste bodi, og lærer folk soleis, so skal han kallast den minste i himmelriket; men den som held deim og lærer deim ifrå seg, han skal kallast stor i himmelriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'For det segjer eg dykk, at er ikkje dykkar rettferd mykje større enn rettferdi åt dei skriftlærde og farisæarane, so kjem de aldri inn i himmelriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'De hev høyrt det er sagt til dei gamle: «Du skal ikkje drepa! Den som drep, skal koma for retten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Men eg segjer dykk at den som er vond på bror sin forutan grunn, han skal koma for retten; og den som segjer til bror sin: «Din stakar!» han skal koma for rådet; og den som segjer: «Din dåre!» han skal koma i helviteselden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Når du då gjeng fram til altaret med offeret ditt, og du der kjem i hug at bror din hev noko imot deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'so lat offeret ditt liggja der framfor altaret - gakk fyrst burt og gjer det godt at med bror din, og kom so og ber fram offeret ditt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Ver snar til å laga deg etter motparten din den stundi du er med honom på vegen! Elles stemner han deg for domaren, og domaren sender deg yver til futen, og du vert kasta i fengsel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'det segjer eg deg for visst: Du slepp ikkje ut att fyrr du hev greidt siste kvitten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'De hev høyrt det er sagt: «Du skal ikkje gjera hor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Men eg segjer dykk at den som ser på ei kvinna og lyster etter henne, han hev alt gjort hor med henne i hjarta sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Um det høgre auga ditt freistar deg, so riv det ut og kasta det frå deg! Du er betre faren du misser ein av lemerne dine, enn at heile likamen vert kasta i helvite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Og um den høgre handi freistar deg, so hogg henne av og kasta henne frå deg! Du er betre faren du misser ein lem enn at heile likamen din kjem i helvite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Det er sagt: «Den som skil seg frå kona si, skal gjeve henne skilsmålsbrev.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Men eg segjer dykk at den som skil seg frå kona si for anna enn utruskap, han valdar at ho gjer hor, og den som gifter seg med ei fråskild kona, han gjer hor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Sameleis hev de høyrt det er sagt til dei gamle: «Du skal ikkje gjera rang eid, men svara Herren for eidarne dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Men eg segjer dykk at de aldri skal sverja, korkje ved himmelen, for det er Guds høgsæte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'eller ved jordi, for det er fotbenken hans, eller ved Jerusalem, for det er staden åt den store kongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ikkje skal du heller sverja ved hovudet ditt; for du kann ikkje gjera eit hår kvitt eller svart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Når de talar, so lat det vera «Ja, ja!» og «Nei, nei!» Alt som gjeng yver det, kjem av det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'De hev høyrt det er sagt: «Auga for auga og tonn for tonn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Men eg segjer dykk at de ikkje skal setja dykk imot den som gjer vondt. Um ein slær deg på den høgre kinni, so snu den vinstre og til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Og vil nokon trætta til seg trøya di, so lat honom få kjolen med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Og trugar nokon deg til å fylgja honom ei mil, so fylg du honom tvo mil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Gjev den som bed deg, og snu deg ikkje frå den som vil låna av deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'De hev høyrt det er sagt: «Du skal elska næsten din og hata fienden din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Men eg segjer dykk: Elska fiendarne dykkar, velsigna deim som bannar dykk, gjer vel mot deim som hatar dykk, og bed for deim som forfylgjer dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'då er de rette borni åt far dykkar i himmelen; for han let soli si skina yver vonde og gode, og let det regna yver rettferdige og urettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'For um de elskar deim som elskar dykk, kva løn kann de venta for det? Gjer ikkje tollmennerne like eins?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Og um de helsar «Guds fred» berre til brørne dykkar, kva stort gjer de då? Gjer ikkje heidningarne det same?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Ver då de fullkomne, som far dykkar i himmelen er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Agta dykk at de ikkje gjer dei gode gjerningarne dykkar for augo på folk, so dei skal sjå kor gjæve de er! For då hev de ingi løn i vente hjå far dykkar i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Vil du gjeva ei sælebotsgåva, so blås ikkje fyrst i luren um det, som hyklarane gjer i synagogorne og på gatorne, so folk skal rosa deim; det segjer eg dykk for sant: Dei hev alt fenge si løn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Men når du gjev ei sælebotsgåva, so lat’kje den vinstre handi di vita kva den høgre handi di gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Lat gåva di vera duld, og far din som ser det som dult er, han skal løna deg upp i dagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Når de bed, so far ikkje åt som hyklarane! For dei vil helst standa i synagogorne og på gatehyrno og halda bøn, so dei kann få syna seg fram for folk; det segjer eg dykk for sant: Dei hev alt fenge si løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Men når du vil beda, då gakk inn i kammerset ditt, og lat att døri, og bed til far din som er i det dulde, og far din som ser i det dulde, skal løna deg upp i dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Remsa ikkje upp mange ord når de bed! So gjer heidningarne - dei trur bønerne deira skal høyrast for dei mange ordi skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Gjer då ikkje som dei! Far dykkar veit kva de treng, fyrr de bed honom um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Soleis skal de beda: Fader vår, du som er i himmelen! Lat namnet ditt helgast;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'lat riket ditt koma; lat viljen din råda på jordi so som i himmelen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'gjev oss i dag vårt daglege brød;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'og forlat oss vår skuld, som me og forlet våre skuldmenn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'og før oss ikkje ut i freisting; men frels oss frå det vonde. For riket er ditt, og magti og æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'For um de forlet andre misgjerningarne deira, so skal far dykkar i himmelen forlata dykk og;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'men forlet de ikkje andre, so skal ikkje far dykkar heller forlata dykkar misgjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Når de fastar, skal de ikkje laga dykk sturne som hyklarane; for dei skaper seg til i andlitet, so folk skal sjå at dei fastar; det segjer eg dykk for sant: Dei hev alt fenge si løn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Men når du fastar, då salva hovudet og två andlitet ditt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'so ikkje folk, men far din i det dulde, kann sjå at du fastar, og far din som ser i det dulde, skal løna deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Samla dykk ikkje skattar på jordi, der mol og makk et og øyder, og tjuvar bryt seg inn og stel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'men samla dykk skattar i himmelen, der korkje mol eller makk øydelegg, og tjuvar aldri bryt seg inn og stel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'For der skatten din er, der vil hjarta ditt og vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Auga er ljoset i likamen; er auga ditt klårt, so vert heile likamen ljos;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'er auga ditt dimt, so vert heile likamen myrk. Når då ljoset inni deg er myrkt, kor stort vert ikkje myrkret då!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Ingen kann tena tvo herrar; for anten vil han hata den eine og halda utav den andre, eller halda seg til den eine og vanvyrda hin; de kann ikkje tena både Gud og Mammon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Difor segjer eg dykk: Syt ikkje for livet dykkar, kva de skal eta og kva de skal drikka, eller for likamen dykkar, kva de skal klæda dykk med! Er ikkje livet meir enn maten og likamen meir enn klædi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Sjå på fuglarne i lufti: Dei sår ikkje, og haustar ikkje, og samlar ikkje i hus, og far dykkar i himmelen føder deim like vel. Er ikkje de mykje meir enn dei?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Og kven av dykk kann leggja ei einaste aln til livsvegen sin, um han syter aldri so mykje?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Og kvi syter de for klædi? Sjå liljorne på marki, korleis dei veks! Dei arbeider ikkje, dei spinn ikkje;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'men eg segjer dykk at ikkje sjølve Salomo i all sin herlegdom var so klædd som ei av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Klæder no Gud soleis graset på marki, det som stend i dag og vert kasta i omnen i morgon, skulde han då’kje mykje heller klæda dykk, de fåtruande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'So må de då ikkje syta og segja: «Kva skal me eta?» eller: «Kva skal me drikka?» eller: «Kva skal me klæda oss med?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'For alt det spør heidningarne etter; men far dykkar i himmelen veit at alt sovore treng de um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Søk fyrst Guds rike og hans rettferd, so skal de få alt dette attpå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'So syt då ikkje for morgondagen! Morgondagen lyt syta for seg. Kvar dag hev nok med si møda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Døm ikkje, elles vert de dømde! For den domen de dømer, skal de dømast etter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'og det målet de mæler med, skal dei mæla åt dykk i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Kvi ser du flisi i auga åt bror din, men bjelken i ditt eige auga, den vert du ikkje var?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Eller korleis kann du segja til bror din: Kom, lat meg taka flisi ut or auga ditt! og sjå, det sit ein bjelke i ditt eige auga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Din hyklar! Drag fyrst bjelken ut or ditt auga - då kann du sjå å taka flisi ut or auga åt bror din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Gjev ikkje hundarne det som heilagt er, og kasta ikkje perlorne dykkar for svini! Dei kjem berre til å trøda deim under føterne, og snu seg og riva dykk sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Bed, so skal de få, leita, so skal de finna, banka på, so skal det verta upplate for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'For kvar den som bed, han fær, og den som leitar, han finn, og den som bankar på, vert det upplate for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Eller er det nokon av dykk som gjev son sin ein stein når han bed honom um brød,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'eller ein orm når han bed um ein fisk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Når no de veit å gjeva borni dykkar gode gåvor, de som er vonde, kor mykje meir vil so’kje far dykkar i himmelen gjeva noko godt til deim som bed honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Alt som de då vil at andre skal gjera mot dykk, det skal de og gjera mot deim; for so er lovi og profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Gakk inn igjenom den tronge porten! For vid er den porten, og breid er den vegen som fører til fortaping, og mange er dei som gjeng inn der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Men trong er den porten, og smal er den vegen som fører til livet, og få er dei som finn honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Tak dykk i vare for dei falske profetarne! Dei kjem til dykk i saueham, men innvertes er dei gråduge ulvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'På frukterne deira skal de kjenna deim; kann ein hausta druvor av klunger eller fikor av tistlar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Soleis ber alle gode tre god frukt; men låke tre ber vond frukt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'eit godt tre kann ikkje bera vond frukt, og eit låkt tre kann ikkje bera god frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Men kvart tre som ikkje gjev god frukt, vert hogge ned og kasta på elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'So skal de då kjenna deim på frukterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ikkje alle som segjer til meg: «Herre, herre!» skal koma inn i himmelriket, men dei som gjer det far min i himmelen vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'På den dagen skal mange segja til meg: «Herre, herre, hev me ikkje tala profetord i ditt namn, og drive ut djevlar i ditt namn, og gjort mange under i ditt namn?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Då skal eg segja deim beint ut: «Eg hev aldri kjent dykk. Gakk ifrå meg, de illgjerdsmenner!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Den som no høyrer desse ordi mine og gjer etter deim, honom vil eg likna med ein vitug mann, som bygde huset sitt på berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Og regnet sila, og elvarne fløymde, og vindarne bles og sette mot huset; men det stod; for det var tufta på berg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Og den som høyrer desse ordi mine og ikkje gjer etter deim, han kann liknast med ein fåvis mann, som bygde huset sitt på sand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Og regnet sila, og elvarne fløymde, og vindarne bles og sette mot huset; då fall det, og fallet vart stort.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Då Jesus hadde tala desse ordi, då var folket reint upp i under yver læra hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'For han lærde deim som ein som hev velde, og ikkje som deira skriftlærde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Då han gjekk ned av fjellet, fylgde det mykje folk med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Best det var, kom ein som hadde spillsykja, og fall på kne for honom og sagde: «Herre, dersom du vil, so kann du gjera meg rein.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jesus rette ut handi, og tok burt på honom og sagde: «Eg vil; vert rein!» Då vart han med ein gong fri spillsykja, og rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Og Jesus sagde til honom: «Sjå til at du ikkje segjer dette med nokon, men gakk burt og te deg for presten, og ber fram det offeret som Moses hev sagt fyre, so du kann vitna for deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Då han so gjekk inn i Kapernaum, kom ein hovudsmann og tala til honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, '«Herre, drengen min ligg lam heime, og lid hardt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, '«Skal eg koma og lækja honom?» segjer Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, '«Herre,» svara hovudsmannen, «eg er ikkje verd at du stig inn under mitt tak. Men seg berre eit ord, so vert drengen min god att!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'For eg er ein mann som må lyda deim som større er, og sjølv hev eg og hersveinar under meg, og segjer eg til ein av deim: «Gakk!» so gjeng han, og til ein annan: «Kom!» so kjem han, og til tenaren min: «Gjer no det!» so gjer han det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Då Jesus høyrde det, undra han seg, og sagde til deim som var med honom: «Det segjer eg dykk for sant: So stor ei tru hev eg ikkje funne hjå nokon i Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Og det skal de vita, at mange skal koma både frå aust og frå vest og setja seg til bords med Abraham og Isak og Jakob i himmelriket;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'men dei som riket var etla åt, skal ut i myrkret utanfor, der dei græt og skjer tenner.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'So sagde han til hovudsmannen: «Gakk heim att! Det skal verta som du trudde.» Og drengen vart god att i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Då Jesus kom heim til Peter, såg han at vermor hans låg sjuk og hadde hiteflagor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'So tok han henne i handi; då kvarv hiteflagorne burt, og ho stod upp og stelte for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Um kvelden kom dei til honom med mange som var forgjorde og hadde vonde ånder i seg, og han dreiv ut ånderne med eit einaste ord, og alle som hadde vondt, gjorde han gode att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Soleis skulde det sannast det som Jesaja, profeten, hev tala, når han segjer: «Han våre sotter på seg tok, og våre sykjor bar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Då Jesus såg at det hadde samla seg mykje folk ikring honom, sagde han til læresveinarne: «Lat oss fara yver til hi sida!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'I det same kom ein skriftlærd mann til honom og sagde: «Meister, eg vil fylgja deg kvar du fer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Då svara Jesus: «Revarne hev hi, og fuglarne i lufti hev reir, men Menneskjesonen hev ingen stad han kann leggja sitt hovud nedpå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Ein annan - ein av læresveinarne hans - sagde med honom: «Herre, lat meg fyrst få ganga heim og jorda far min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Men Jesus svara: «Fylg du meg, og lat dei daude jorda sine daude!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'So gjekk han ut i båten, og læresveinarne var med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Um eit bil vart det so hard sjø at bårorne slo yver båten; men han låg og sov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Då gjekk dei burt til honom og vekte honom og sagde: «Herre, hjelp! Me gjeng under!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, '«Kvi er de so rædde?» sagde han; «kor lite tru de hev!» So stod han upp og truga vinden og sjøen, og det vart blikende stilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Og folk undra seg og sagde: «Kva mann er dette, at både vind og sjø må lyda honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Då han kom yver på hi sida, til Gadarenarlandet, møtte han tvo forgjorde, som kom ut or gravholorne; dei var so ville og vonde at ingen kunde koma fram den vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Og best det var, sette dei i og ropa: «Kva vil du oss, du Guds Son? Er du komen hit for å plåga oss fyre tidi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Eit godt stykke ifrå gjekk ein stor svineflokk på beite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'So bad ånderne: «Driv du oss ut, so lat oss fara i svineflokken!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, '«Gjer so då!» svara han. Då for dei ut og for inn i svini. Og brått sette heile flokken utyver stupet og ned i sjøen og druknast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Gjætarane rømde, og då dei kom til byen, fortalde dei alt saman, og sagde korleis det hadde gjenge med dei forgjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Då gjekk alt byfolket ut imot Jesus, og då dei fekk sjå honom, bad dei at han vilde fara burt ifrå bygderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'So gjekk han ut i båten og for yver og kom til sin eigen by.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Då kom dei til honom med ein lam mann, som låg i ei seng. Då Jesus såg trui deira, sagde han til den lame: «Ver hugheil, son! Syndene dine er tilgjevne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Då var det nokre av dei skriftlærde som tenkte med seg: «Denne spottar Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Men Jesus såg tankarne deira og sagde: «Kvi hyser de so vonde tankar i hjarta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Kva er lettast å segja: «Synderne dine er tilgjevne,» eller: «Statt upp og gakk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Men so de skal vita at Menneskjesonen hev magt til å tilgjeva synder på jordi» - so segjer han til den lame: «Statt upp, tak sengi og gakk heim att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Då stod han upp og gjekk heim til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Og då folket såg det, vart dei ottefulle, og lova Gud som hadde gjeve menneskje slik magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Då Jesus gjekk lenger fram, fekk han sjå ein mann som sat på tollbudi - Mattæus heitte han - og sagde til honom: «Fylg meg!» Og han stod upp og fylgde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Då han so heldt måltid heime i huset sitt, kom mange tollmenner og syndarar og sette seg til bords med Jesus og læresveinarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Farisæarane såg det og sagde til læresveinarne: «Kvifor et meisteren dykkar i lag med tollmenner og syndarar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Då Jesus høyrde det, sagde han: «Det er ikkje dei friske som treng lækjar, men dei som hev vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Gakk burt og lær kva som ligg i det ordet: «D’er miskunn, ikkje offer, eg hev hugnad i.» For eg er ikkje komen for å kalla rettferdige, men syndarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Då kom læresveinarne åt Johannes til honom og sagde: «Korleis hev det seg at me og farisæarane fastar so mykje, men dine læresveinar fastar ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jesus svara: «Kann bryllaupsfolket syrgja medan dei hev brudgomen hjå seg? Men det kjem ei tid då brudgomen vert teken ifrå deim; då skal dei fasta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Ingen set ein lapp av ustampa ty på eit gamalt klædeplagg; for boti riv med seg noko av sjølve plagget, og rifti vert større.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Og ikkje hev dei ny vin i gamle lerflaskor; for då rivnar flaskorne, so vinen renn ned, og flaskorne forferst; ny vin hev dei i nye lerflaskor; då held dei seg båe.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Med han tala soleis til deim, kom ein synagoge-forstandar og fall på kne for honom og sagde: «Rett no hev dotter mi slokna; men kom og legg handi di på henne, so livnar ho att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Jesus gjorde seg reidug og gjekk med honom, og læresveinarne og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Då kom det ei kvinna, som hadde havt blodflod i tolv år; ho gjekk innåt honom attantil og tok i ein av duskarne på kjolen hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'for ho tenkte med seg: «Kann eg berre få taka i kjolen hans, so er eg berga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'I det same snudde han seg og såg henne. Då sagde han: «Ver hugheil, dotter! Trui di hev hjelpt deg.» Og kvinna vart god att i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Då Jesus kom heim til synagoge-forstandaren og såg fløytelåtarane og hopen som ståka og våla, sagde han til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, '«Gakk burt! Gjenta er ikkje slokna; ho søv.» Men dei berre log åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Då hopen var driven ut, gjekk han inn, og tok henne i handi, og gjenta stod upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Og gjetordet um dette kom ut yver alle bygderne der ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Då Jesus gjekk burt att, fylgde tvo blinde etter honom og ropa: «Gjer sælebot på oss, du Davids son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Og då han var komen heim, gjekk dei etter han inn. Jesus sagde til deim: «Trur de at eg kann gjera det?» «Ja, herre,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Då tok han burtpå augo deira og sagde: «Det skal verta som de trur.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Og med ein gong kunde dei sjå. Jesus tala strengt til deim og sagde: «Sjå til at ingen fær vita det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Men dei var’kje fyrr komne ut, fyrr dei bar gjetordet hans ut yver alle bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Med same dei gjekk ut, kom det nokre folk til honom med ein mållaus mann som hadde ei vond ånd i seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Då so den vonde åndi var drivi ut, tala den mållause. Og folk undra seg og sagde: «Aldri hev slikt vore set fyrr i Israel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Men farisæarane sagde: «Det er djevlehovdingen sjølv som hjelper honom til å driva djevlarne ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Sidan gjekk Jesus kring i alle byar og bygder og lærde folket i synagogorne deira, og lyste ut evangeliet um Gudsriket, og lækte all sjukdom og vanhelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Og då han såg folkehopen, tykte han hjarteleg synd um deim; for dei var ille medfarne og nedforkomne, som ein saueflokk utan hyrding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Då sagde han til læresveinarne sine: «Grøda er stor, men onnefolki er få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Bed då honom som eig grøda at han vil senda arbeidsfolk til å hausta inn grøda si!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'So kalla han til seg dei tolv læresveinarne sine, og gav deim magt yver ureine ånder, so dei kunde driva deim ut, og kraft til å lækja all sjukdom og vanhelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'So er namni på dei tolv apostlarne: Fyrst Simon, han som kallast Peter, so Andreas, bror hans, og Jakob, son åt Sebedæus, og Johannes, bror hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filip og Bartolomæus, Tomas og Mattæus, tollmannen, Jakob, son åt Alfæus, og Lebbæus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon Kananæus og Judas Iskariot, den same som sveik honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Desse tolv var det Jesus sende ut, og han rettleidde deim og sagde: «Tak ikkje vegen til heidningarne, og gakk ikkje inn i nokon av samaritan-byarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Gakk heller til dei forkomne lambi av Israelshuset!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Og kvar de kjem, so gjer kunnigt at himmelriket er nær!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Læk helselause, vekk upp daude, gjer spillsjuke reine, driv ut djevlar! For inkje hev de fenge det, for inkje skal de gjeva det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Tak ikkje med dykk gull eller sylv eller kopar i belti dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ikkje ferdaskreppa, ikkje tvo trøyor, ikkje skor, ikkje stav! For ein arbeidsmann er kosten sin verd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Kvar gong de kjem til ein by eller ei grend, so høyr etter kven der er som er verd å taka imot dykk, og hjå honom skal de vera til de tek ut att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Når de kjem inn i eit hus, so lys velsigning yver det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'og er huset verdt det, so skal det få den velsigningi de hev lyst, men er det ikkje verdt det, so skal velsigningi koma attende til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Og er det nokon stad dei ikkje vil taka imot dykk og ikkje vil høyra på ordi dykkar, so gakk ut att or det huset eller den byen, og rist dusti av føterne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'det segjer eg dykk for visst: På domedag skal det ganga Sodoma- og Gomorralandet likare enn den byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Sjå no eg sender dykk liksom sauer inn i ulveflokken; ver då kloke som ormen og godtrugne som duva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Tak dykk i vare for folk! For dei kjem til å gjeva dykk yver til domstolarne og hudfletta dykk i synagogorne sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'og for kongar og landshovdingar skal dei føra dykk fram for mi skuld, so de skal vitna for deim og for heidningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Men når dei dreg dykk for retten, so syt ikkje for korleis eller kva de skal tala! Ordi de skal tala, skal de få i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'For det er ikkje de som talar; det er åndi åt far dykkar som talar i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Bror skal senda bror i dauden, og faren barnet sitt, og born skal standa fram mot foreldri sine, og valda at dei lyt døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Og alle skal hata dykk for mitt namn skuld: men den som held ut til endes, han skal verta frelst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Når dei då søkjer etter dykk i ein by, so røm til ein annan! For det segjer eg dykk for visst: De vinn ikkje vitja alle byarne i Israel fyrr Menneskjesonen kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Læresveinen er ikkje yver meisteren, og tenaren er ikkje yver husbonden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Det lyt vera nok for læresveinen at han vert som meisteren sin, og for tenaren at han vert som husbonden. Hev dei kalla husbonden Be’elsebul, kann so husfolket venta det betre?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ver då ikkje rædde deim! For ingen ting er løynt anna det ein gong kjem upp, og ingen ting dult anna det ein gong vert kjent.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Det som eg segjer dykk i myrkret, skal de tala i ljoset, og det som vert kviskra i øyra på dykk, skal de ropa ut på taki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Ottast ikkje dei som drep likamen, men ikkje kann drepa sjæli! Ottast heller honom som kann tyna både sjæl og likam i helvite!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Sel dei ikkje tvo sporvar for ein skilling? Og ikkje ein av deim fell ned på jordi utan Far dykkar vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Og jamvel alle håri på hovudet dykkar er talde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'So ver ikkje rædde! De er meir enn mange sporvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Den som då kjennest ved meg for folk, honom skal eg og kjennast ved for far min i himmelen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Men den som avneittar meg for folk, honom skal eg og avneitta for far min i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'De må’kje tru eg er komen for å føra fred ned på jordi! Eg er’kje komen med fred, men med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Eg er komen for å setja ufred millom far og son, og millom mor og dotter, og millom vermor og sonekona,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'og mannen skal få sin eigen huslyd til uven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Den som hev far eller mor kjærare enn meg, er ikkje verd meg, og den som hev son eller dotter kjærare enn meg, er ikkje verd meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'og den som ikkje tek krossen sin og fylgjer etter meg, er ikkje verd meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Den som vinn livet sitt, skal missa det, og den som misser livet for mi skuld, skal vinna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Den som tek imot dykk, tek imot meg, og den som tek imot meg, tek imot honom som sende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Den som tek imot ein profet for di han er ein profet, skal få same løni som ein profet, og den som tek imot ein rettferdig for di han er rettferdig, skal få same løni som ein rettferdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Og den som gjev ein av desse små um det er’kje anna enn ei skål med kaldt vatn, for di han er min læresvein, han skal på ingen måte missa løna si, det segjer eg dykk for visst.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Då Jesus hadde sagt alt det han vilde leggja dei tolv læresveinarne på minne, for han burt att, og tok til å læra folk og tala for dei kring i byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Johannes fekk høyra i fengslet um gjerningarne åt Kristus. Då sende han bod med læresveinarne sine, og spurde honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, '«Er du den som skal koma, eller lyt me venta ein annan?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jesus svara: «Gakk og seg Johannes kva de høyrer og ser:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Blinde fær syni si, og halte gjeng ikring, spillsjuke vert reine, og dauve høyrer, daude stend upp att, og fatige fær høyra evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'og sæl er den som ikkje styggjest ved meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Då dei gjekk burt, tok Jesus til å tala til folket um Johannes: «Kvi gjekk de ut i øydemarki? Vilde de sjå ei røyr som svagar att og fram i vinden?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Kvi gjekk de då der ut? Vilde de sjå ein mann med fine klæde? Nei, dei som gjeng i fine klæde, held til i kongsgardarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Men kvi gjekk de då der ut? Vilde de sjå ein profet? Ja, segjer eg dykk, og det ein som er meir enn profet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Det er um honom det er skrive: «Framfyre deg min ærendsvein eg sender; der du vil fara, skal han vegen rydja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Det segjer eg dykk for sant: Aldri hev det stige fram nokon større millom menneskjeborni enn Johannes døyparen; og endå er den minste i himmelriket større enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Men frå Johannes døyparens tid og til denne stund bryt folk seg med magt inn i himmelriket, og dei som bryt seg inn, riv det til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'For alle profetarne og lovi spådde alt til Johannes kom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'og vil de tru det, so er han Elia som skulde koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Høyr etter, kvar som høyra kann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Kven skal eg likna denne ætti med? Dei likjest born som sit på torget og ropar til andre born:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, '«Me let i fløyta for dykk, og de dansa ikkje; me song eit syrgjekvæde, og de øya ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'For fyrst kom Johannes, og korkje åt eller drakk; då sagde dei: «Han må vera forgjord!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'So kom Menneskjesonen; han et og drikk, og so segjer dei: «Sjå for ein etar og drikkar! Han er godvener med tollmenner og syndarar!» Men visdomen hev prova si rettferd med sine gjerningar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'So tok han til å lasta dei byarne som han hadde gjort flest under i, for di dei ikkje vende um:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '«Ve yver deg, Korasin! Ve yver deg, Betsaida! Hadde dei underi som eg gjorde i dykk, vore gjorde i Tyrus og Sidon, so hadde dei longe angra og havt på seg sekk og oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Men det segjer eg dykk: På domedag skal det ganga Tyrus og Sidon likare enn dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Og du, Kapernaum, som hev vore lyft upp til himmelen, til helheimen skal du støytast ned! For hadde dei underi som er gjorde i deg, vore gjorde i Sodoma, so hadde han stade til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Men det segjer eg dykk: På domedag skal det ganga Sodomalandet likare enn dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'I den same tidi tok Jesus til ords og sagde: «Eg lovar deg, Fader, du som råder yver himmelen og jordi, at du hev løynt dette for dei lærde og kloke, og openberra det for dei ulærde og barnslege!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja, Fader, for soleis tykte du det best!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Alt hev far min gjeve i mine hender. Og ingen kjenner Sonen utan Faderen, og ingen kjenner Faderen utan Sonen og dei som Sonen vil openberra det for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kom til meg, alle de som slit og hev tungt å bera! hjå meg skal de få kvila dykk ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Tak mitt ok på dykk, og lær av meg! for eg er mild og mjuk i hjarta, og de skal finna kvild for sjælerne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'For mitt ok er godt, og mi byrd er lett.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'I den tidi gjekk Jesus på ein kviledag yver åkrarne. Læresveinarne hans var svoltne og tok til å riva av aks og eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Då farisæarane såg det, sagde dei til honom: «Sjå læresveinarne dine! - no gjer dei noko som ingen hev lov til å gjera på ein kviledag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Han svara: «Hev de’kje lese kva David gjorde då han var svolten, han og dei som var med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'at han gjekk inn i Guds hus, og åt skodebrødi, og dei hadde han ikkje lov til å eta, korkje han eller fylgjesmennerne hans, men berre prestarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Eller hev de’kje lese i lovi at prestarne bryt helgi i templet på kviledagen, og er endå skuldlause?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Men eg segjer dykk, at her er det som er større enn templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Og hadde de visst kva som ligg i det ordet: «D’er miskunn, ikkje offer, eg hev hugnad i,» so hadde de ikkje fordømt desse uskyldige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'For Menneskjesonen råder yver kviledagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'So gjekk han burt derifrå og til synagoga deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Der var det ein mann som hadde ei nomi hand. So spurde dei honom: «Tru det er rett å lækja folk på ein kviledag?» For dei vilde få noko å klaga honom for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Då sagde han til deim: «Kven av dykk dreg ikkje upp att ein sau som hev dotte ned i eit dike for honom på ein kviledag?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Og kor mykje meir er’kje eit menneskje enn ein sau! So må det då vera rett å gjera vel på kviledagen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'So segjer han til mannen: «Rett fram handi!» Då rette han henne fram, og ho vart frisk liksom hi handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Men farisæarane gjekk ut og lagde råd um korleis dei skulde få gjort ende på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Då Jesus vart vis med det, for han burt, og det fylgde mange med honom. Han lækte deim alle,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'men forbaud deim strengt å gjera honom kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Soleis skulde det sannast det som er tala gjenom Jesaja, profeten, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '«Sjå sveinen unge som eg ut meg såg, han som eg elskar, han, min hjartehugnad! På honom vil eg leggja åndi mi, og rett skal for folki lysa ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Han trættar ikkje, ropar ikkje høgt. I gatorn’ ingen høyra fær hans røyst:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Den brotne røyri krys han ikkje sund, rjukande skaren sløkkjer han’kje ut, fyrr retten han til siger fram hev ført.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Til han skal folket setja voni si.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Sidan kom dei til honom med ein forgjord som var både mållaus og blind, og han gjorde honom god att, so den mållause tala og såg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Då vart alt folket reint upp i under og sagde: «Dette skulde vel ikkje vera Davidssonen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Då farisæarane høyrde det, sagde dei: «Denne kunde ikkje driva ut djevlarne, fekk han ikkje hjelp av Be’elsebul, hovdingen deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Men Jesus visste kva dei tenkte, og sagde til deim: «Eit rike som ligg i strid med seg sjølv, kjem snart til å øydast, og ein by eller eit hus som er kome i strid med seg sjølv, stend ikkje lenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Er det no so at Satan driv ut Satan, so er han komen i strid med seg sjølv, og korleis kann då riket hans standa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Og hjelper Be’elsebul meg til å driva ut dei djevlarne, kven hjelper då dykkar eigne folk til å driva deim ut? Difor skal dei vera domarane dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Men er det Guds Ande som hjelper meg til å driva ut djevlarne, so er då Gudsriket kome til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Eller kven kann ganga inn i huset til ei kjempa og rana eignaluterne hans, hev han ikkje fyrst lagt kjempa i band? då kann han plundra huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Den som ikkje er med meg, er imot meg, og den som ikkje sankar med meg, han spreider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Difor segjer eg dykk: All synd og spotting skal tilgjevast menneskja, men spott imot Anden skal ikkje tilgjevast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Og den som lastar Menneskjesonen, skal få tilgjeving for det; men den som lastar den Heilage Ande, fær aldri tilgjeving, korkje i dette livet eller i det som skal koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Anten lyt de segja: «Treet er godt, og frukti på det er god,» eller og: «Treet er låkt, og frukti på det er låk.» For på frukti kjenner ein treet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'De orme-ungar, korleis kann de tala noko godt, de som er vonde? for frå munnen kjem det som hjarta er fullt av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Ein god mann ber fram gode ting av det gode han gøymer hjå seg, og ein vond mann ber fram vonde ting av det vonde han gøymer på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Men det segjer eg dykk: Kvart gagnlaust ord som folk hev tala, skal dei svara for på domedag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'for etter ordi dine vert du frikjend, og etter ordi dine vert du felt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Då tok nokre skriftlærde og farisæarar til ords og sagde: «Meister, me vil gjerne sjå eit teikn av deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Han svara: «Ei vond og utru ætt krev etter teikn, men dei skal’kje få anna teikn enn det som hende Jonas, profeten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'For liksom Jona var tri dagar og tri næter i fiskebuken, soleis skal Menneskjesonen vera tri jamdøger under jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Nineve-mennerne skal møta for domen saman med denne ætti og fella deim; for dei vende um då Jona tala for deim, og her er meir enn Jona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Sudlands-dronningi skal standa fram for domen i hop med denne ætti og fella deim; for ho kom frå verdsens ende og vilde høyra Salomos visdom, og her er meir enn Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Når den ureine åndi fer ut or eit menneskje, flakkar ho yver vatslause vidder og leitar etter ein kvilestad, men finn ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'So segjer ho: «Eg vil fara attende til huset mitt, som eg flutte utor,» og når ho kjem der, finn ho det tomt, og feia og fjelga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Då fer ho av stad og tek med seg sju andre ånder som er argare enn ho er sjølv, og dei gjeng inn og vert buande der, og hev det vore ille med det menneskjet fyrr, so vert det endå verre sidan. Soleis kjem det og til å ganga med denne vonde ætti.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Med han heldt på å tala til folket, var mor hans og brørne hans komne, og no stod dei utanfor og vilde finna honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Då so ein kom inn og sagde det med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'svara han: «Kven er mor mi, og kven er brørne mine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'So rette han handi ut mot læresveinarne sine og sagde: «Sjå der er mor mi og brørne mine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'for den som gjer det far min i himmelen vil, han er bror min og syster mi og mor mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Same dagen gjekk Jesus ut og sette seg nedmed sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Då samla det seg so mykje folk ikring honom, at han laut ganga ut på eit skip og setja seg der, og heile folkemengdi stod burtetter strandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Då sagde han deim mangt og mykje i likningar og tok so til ords: «Ein såmann gjekk ut og skulde så,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'og då han sådde, fall noko av kornet frammed vegen, og fuglarne kom og åt det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Noko fall på steingrunn; der hadde det ikkje mykje jord, og det rann snøgt upp, av di der var so grunt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'men då soli steig, skein det av; for det hadde ikkje rot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Noko fall millom klunger, og klungeren voks upp og kjøvde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Noko fall i god jord og gav grøda, sumt hundrad foll, og sumt seksti foll, og sumt tretti foll.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Høyr etter, kvar som høyra kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Læresveinarne kom og sagde til honom: «Kvi talar du til deim i likningar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Då svara han: «De fær vita løyndomarne i himmelriket, men det gjer ikkje dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'For den som hev, han skal få, so han hev nøgdi; men den som inkje hev, skal missa endå det som han hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Difor talar eg til deim i likningar; for um dei ser, so ser dei ikkje, og um dei høyrer, so høyrer dei ikkje og skynar ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'På deim vert det sanna det som Jesaja spådde: «Ja, høyra skal de nok, men ikkje håtta, sjå skal de nok, men de skal ikkje skilja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'For dette folket hev so hard ein hug; tungt høyrer dei med øyro, og augo let dei att, so dei med augo inkje sjå, med øyro inkje høyra skal, og aldri med sitt hjarta skyna, og snu, so eg deim lækja fær.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Men sæle dykkar augo som ser, og dykkar øyro som høyrer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'For det segjer eg dykk for sant: Mange profetar og rettferdige stunda etter å sjå det som de ser, og fekk ikkje sjå det, og høyra det som de høyrer, og fekk ikkje høyra det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'So høyr no de likningi um såmannen:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Kvar gong nokon høyrer ordet um Gudsriket, og ikkje skynar det, so kjem den vonde og stel burt det som er sått i hjarta hans; det er det kornet som var sått frammed vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Det som var sått på steingrunn, det er den som høyrer ordet og straks tek imot det med gleda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'men han hev ikkje rot i seg, og held ikkje ut langt bilet; kjem han i naud eller fåre for ordet skuld, so leidest han snart og fell ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Det som var sått millom klunger, det er den som høyrer ordet, men suti for det timelege og den svikalle rikdomen kjøver ordet, so det ikkje ber frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Det som var sått i god jord, det er dei som høyrer ordet og skynar det; dei er det som gjev grøda; ein gjev hundrad foll, og ein seksti foll, og ein tretti foll.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'So sette han fram ei onnor likning og sagde: «Himmelriket kann liknast med ein mann som hadde sått godt frø i åkeren sin;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'men medan folket sov, kom uvenen hans og sådde svimling millom kveiten, og gjekk sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Då no åkeren voks upp og skaut aks, so kom svimlingen og til synes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Då gjekk sveinarne til husbonden og sagde: «Herre, sådde du’kje godt frø i åkeren din? Kvar kjem då ugraset frå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, '«Det hev ein uven gjort,» svara han. «Vil du me skal ganga og rykkja det upp?» segjer dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, '«Nei,» sagde han, «for då kunde de koma til å riva upp kveiten og med det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Lat båe veksa med einannan til hausten, og når skurdonni kjem, vil eg segja til skjerarane: «Sanka fyrst svimlingen saman og bunta honom i hop til å brennast, men hav kveiten inn i løda mi!»»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'So sette han fram ei likning til og sagde: «Himmelriket er likt eit senapskorn som ein mann tok og sette i hagen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Det er mindre enn alle andre frøkorn; men når det hev vakse upp, er det større enn alle hagevokstrar og vert eit heilt tre, so fuglane i lufti kjem og byggjer reir i greinerne på det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'So sagde han deim ei onnor likning: «Himmelriket er likt ein surdeig som ei kona tok og gøymde i tri skjeppor mjøl, til alt mjølet var syrt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Alt dette tala Jesus til folket i likningar, og utan likningar tala han aldri til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'so det skulde sannast det som er tala gjenom profeten, når han segjer: «Med likningar so vil eg lata upp min munn, og segja fram det som var løynt frå verdi vart.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'So bad han farvel med folket og gjekk inn att. Då kom læresveinarne til honom og sagde: «Tyd ut for oss likningi um svimlingen i åkeren!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Han svara: Den som sår det gode frøet, er Menneskjesonen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'åkeren er verdi; det gode frøet er dei som eig heime i Gudsriket, og svimlingen dei som høyrer under den vonde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'uvenen som sådde svimlingen, er djevelen; hausten er endelykti på verdi, og skurdfolket er englarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Liksom no svimlingen vert sanka i hop og uppbrend, soleis skal det ganga til når det vert ende på verdi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Menneskjesonen skal senda ut englarne sine, og dei skal sanka ut or riket hans alt som skjemmer ut, og alle som gjer urett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'og kasta deim i den gloande omnen, der dei græt og skjer tenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Då skal dei rettferdige skina som soli i riket åt far sin. Høyr etter, kvar som høyra kann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Himmelriket er likt ein skatt som var nedgraven i ein åker. Den skatten var det ein mann som fann; han grov honom ned att, og glad som han var, gjekk han burt og selde alt det han hadde, og kjøpte åkeren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Sameleis er himmelriket likt ein kjøpmann som leita etter væne perlor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Då han so fann ei som var ovgild, gjekk han av og gjorde alt han åtte i pengar, og kjøpte den perla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Sameleis er himmelriket likt ei not som dei kastar i sjøen og fangar alle slag fisk i;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'når ho er full, dreg dei henne upp på strandi, og so set dei seg ned og sankar den gode fisken i koppar, men den som ikkje duger, kastar dei ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Soleis skal det ganga til når det vert ende på verdi. Då skal englarne fara ut og skilja dei vonde frå dei gode');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'og kasta dei vonde i den gloande omnen, der dei græt og skjer tenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '«Skyna de alt dette?» «Ja,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, '«Det er godt,» sagde han; «for ein lærar som hev gjenge himmelriks-skulen, er lik ein husbond som tek fram både nytt og gamalt av det han hev gøymt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Då Jesus hadde sagt deim alle desse likningarne, for han burt att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'So kom han til fødesheimen sin og lærde deim i synagoga deira, so dei vart reint upp i under og sagde: «Kvar hev han fenge slik visdom frå og slike underfulle krafter?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Er’kje dette timbremanns-sonen? Heiter ikkje mor hans Maria, og brørne hans Jakob og Josef og Simon og Judas?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Og systerne hans, bur dei’kje alle her i grendi? Kvar hev so han fenge alt det frå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Og dei støyttest ved honom. Men Jesus sagde til deim: «Ein profet er ikkje vanvyrd utan i si eige grend og i si eigi ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Og han gjorde ikkje mange under der, for di dei var so vantrune.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Ved det leitet fekk Herodes, fylkeskongen, høyra gjetordet um Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Då sagde han til mennerne sine: «Det er Johannes, døyparen! No hev han stade upp frå dei daude; difor ter det seg so underfulle krafter i honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Herodes hadde teke Johannes og lagt honom i bolt og jarn for Herodias skuld, kona åt Filip, bror hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'For Johannes hadde sagde til honom: «Du må ikkje hava henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Og Herodes vilde helst ha slege honom i hel, men han torde ikkje for folket; for dei heldt honom for ein profet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'So var det årmålsdagen åt Herodes; og dotter åt Herodias dansa for deim, og Herodes tykte so godt um henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'at han lova og svor ho skulde få kva ho bad um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Då fekk mori henne til å segja: «Gjev meg hovudet åt Johannes døyparen, her, på eit fat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Kongen vart ille ved, men for di han hadde svore, og for gjesterne skuld, sagde han at dei skulde lata henne få det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'og han sende ut folk og let dei hogga hovudet av Johannes i fengslet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'So kom dei med hovudet hans på eit fat og gav det til gjenta, og ho gjekk til mor si med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Og læresveinarne hans kom og tok liket og bar honom til gravi; sidan gjekk dei til Jesus med bod um det som var hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Då Jesus høyrde det, for han i ein båt burt til ein øydestad, so han kunde få vera åleine; men folket fekk spurt det og fylgde etter honom landveges frå byarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Då han steig i land, fekk han sjå ein stor folkehop, og han tykte hjarteleg synd i deim, og lækte deim som var sjuke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Då det leid til kvelds, gjekk læresveinarne burt til honom og sagde: «Det er audt her, og dagen lid; send folket frå deg, so dei kann ganga burt i grenderne og kjøpa seg mat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, '«Dei treng ikkje ganga burt,» sagde Jesus; «gjev de deim mat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, '«Me hev’kje her anna fem brødleivar og tvo fiskar,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, '«Kom hit til meg med det!» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'So bad han folket setja seg i graset, og tok dei fem brødleivarne og dei tvo fiskarne, og såg upp imot himmelen og velsigna deim, og so braut han brødet og gav det til læresveinarne, og læresveinarne gav det til folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Alle åt og vart mette, og då dei samla upp dei stykki som att var, so vart det tolv fulle korger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Og det var um lag fem tusund mann som hadde ete, umfram kvinnor og born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Med same dette var gjort, nøydde han læresveinarne til å ganga i båten og fara fyre seg yver sjøen, med han bad farvel med folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Då han so hadde sendt folket frå seg, gjekk han upp i fjellet, so han kunde vera for seg sjølv og beda, og etter det var avdaga, var han der einsleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Båten var alt midt utpå sjøen og tevla hardt i bylgjorne; for vinden var imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Då, i den fjorde nattevakti, kom han gangande burtimot deim yver sjøen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'og då læresveinarne såg han ganga på sjøen, vart dei forfærde og sagde: «Det er eit skrymt!» og dei var so rædde at dei skreik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Men i det same tala han til deim og sagde: «Ver hugheile! Det er eg. Ver ikkje rædde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Då tok Peter til ords og sagde: «Herre, er det du, so seg at eg skal koma til deg på vatnet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, '«Kom du!» svara han. So steig Peter ut or båten og gjekk burtyver vatnet og vilde møta Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Men då han såg det harde veret, vart han rædd, og tok til å søkka. Då ropa han: «Herre, frels meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Og med det same rette Jesus ut handi og greip honom og sagde: «Kor lite tru du hev! Kvi tvila du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'So steig dei upp i båten, og vinden lagde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Og dei som var i båten, fall på kne for honom og sagde: «Ja, sanneleg er du Guds Son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Då dei var komne yver, lagde dei til lands i Gennesaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Folket der i bygdi kjende honom att, og sende bod kringum i heile grannelaget. Då kom dei til honom med alle som hadde vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'og dei bad um dei berre måtte få taka i falden på kjolen hans, og alle som kom nær honom, vart gode att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'So kom det nokre farisæarar og skriftlærde til Jesus frå Jerusalem og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '«Kvi bryt læresveinarne dine dei skikkarne me hev etter dei gamle? dei tvær ikkje henderne fyrr dei gjeng til bords!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, '«Og de,» svara han, «kvi bryt de Guds bod for skikkarne dykkar skuld?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Gud hev sagt: «Du skal æra far din og mor di!» og: «Den som bannar far sin eller mor si, skal døy!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Men de segjer: «Når ein talar so til far sin eller mor si: «Det som eg kunde ha hjelpt deg med, lyt eg gjeva til templet,» so tarv han ikkje æra foreldri sine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Soleis hev de gjort Guds bod um inkje for dykkar eigi læra skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'De hyklarar! Jesaja spådde sant um dykk då han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '«Med lipporn’ lovar dei meg, denne lyden, men hugen deira er langt ifrå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'D’er liten mun i at dei meg vil æra, når dei lærer folk det som er mannebod.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'So kalla han folket hitåt seg og sagde til deim: «Høyr etter, og tenk på det eg segjer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Det er’kje det som kjem inn i munnen som gjer menneskja urein, men det som gjeng ut or munnen, det er det som gjer menneskja urein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Då gjekk læresveinarne fram og sagde til honom: «Veit du at farisæarane vart arge då dei høyrde det du sagde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Han svara: «Kvar plante som ikkje far min i himmelen hev sett, skal rivast upp med rot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Bry dykk ikkje um deim! Dei er blinde vegleidarar for blinde; og når ein blind leider ein blind, so dett dei båe i grefti.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Då tok Peter til ords og sagde til honom: «Tyd oss den likningi di!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, '«Hev de endå ikkje betre vit, de heller?» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, '«Skynar de ikkje at alt det som kjem inn i munnen, gjeng ned i magen, og fer ut der det skal?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Men det som gjeng ut or munnen, kjem frå hjarta, og det gjer menneskja urein;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'for frå hjarta kjem vonde tankar: manndråp, egteskapsbrot, lauslivnad, tjuvskap, range vitnemål, gudsspotting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Det er det som gjer menneskja urein; men å eta med utvegne hender gjer ikkje menneskja urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'So for Jesus derifrå, og tok vegen burt til bygderne kring Tyrus og Sidon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Då kom det ei kananæisk kona ut frå dei grenderne og ropa: «Herre, Davids son, gjer sælebot på meg! Dotter mi er so ille plåga av ei vond ånd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Men han svara henne ikkje eit ord. Då gjekk læresveinarne fram og bad honom: «Kjære, få henne frå deg! Ho ropar so etter oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, '«Det er berre dei forkomne sauerne av Israelshuset eg er send til,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'So kom ho og fall på kne for honom og sagde: «Herre, hjelp meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Men han svara: «Det er’kje vænt å taka brødet frå borni og kasta det for hund-ungarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, '«Det er sant, Herre,» sagde ho, «men hund-ungarne et då av dei molarne som fell frå bordet åt herrarne deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Då svara Jesus: «Stor er trui di, kona! Du skal få det som du vil.» Og dotter hennar vart god att i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'So for Jesus burt derifrå og kom til Galilæasjøen, og han gjekk upp i fjellet og sette seg der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Då kom dei til honom i store flokkar, og hadde med seg halte og blinde og mållause og kryplingar og mange andre, og lagde deim ned for føterne hans, og han gjorde dei gode att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'so folket undra seg då dei såg at mållause tala, og kryplingar vart friske og føre, og halte gjekk ikring, og blinde såg; og dei lova Israels Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Då kalla Jesus læresveinarne til seg og sagde: Eg tykkjer hjarteleg synd i folket; for no hev dei alt vore hjå meg i tri dagar, og dei hev’kje noko å eta; og ikkje vil eg senda deim fastande frå meg; for då kunde dei ormegtast på vegen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Læresveinarne svara: «Kor skal me her i øydemarki få brød nok til å metta so stor ein hop?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, '«Kor mykje brød hev de?» spurde Jesus. «Sju leivar,» sagde dei, «og nokre få småfiskar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Då let han folket setja seg ned på marki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'og han tok dei sju leivarne og fiskarne, og takka, og bytte deim sund og gav det til læresveinarne, og læresveinarne gav det til folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Då alle hadde ete og var mette, samla dei upp dei stykki som att var; det var sju fulle korger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Og det var fire tusund mann som hadde ete, umfram kvinnor og born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Sidan bad Jesus farvel med folket, og steig ut i båten og for til Magadanbygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Då kom farisæarane og sadducæarane og freista honom, og bad at han vilde lata deim få sjå eit teikn frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Han svara: «Um kvelden segjer de: «Det vert godt ver; for himmelen er raud,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'og um morgonen: «I dag vert det uver; for himmelen er raud og myrk.» Himmelsbragdi veit de å døma um, men tidarteikni kann de ikkje tyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Ei vond og utru ætt krev etter teikn, men dei skal’kje få anna teikn enn Jona-teiknet.» Dermed snudde han seg ifrå deim og gjekk burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Då dei so for yver til hi sida, gløymde læresveinarne å taka brød med seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'So sagde Jesus til deim: «Sjå til at de tek dykk i vare for farisæar- og sadducæar-surdeigen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Då sagde dei seg imillom: «Det er av di me ikkje tok brød med oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jesus gådde det og sagde: «Kvi talar de dykk imillom um det at de ikkje hev brød med, de fåtruande?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Hev de endå so lite vit? Kjem de ikkje i hug dei fem brødleivarne til dei fem tusund mann, og kor mange korger de fekk att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'og ikkje dei sju leivarne til dei fire tusund, og kor mange korger de då fekk att?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Kann de då’kje skyna at det ikkje var brød eg tala til dykk um? Men agta dykk for farisæar- og sadducæar-surdeigen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Då skyna dei at det ikkje var surdeigen i brødet han hadde meint, men læra åt farisæarane og sadducæarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Då Jesus var komen til bygderne kring Cæsarea Filippi, spurde han læresveinarne sine: «Kven segjer folk at Menneskjesonen er?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Dei svara: «Sume segjer: «Johannes døyparen,» andre: «Elia», endå andre: «Jeremia eller ein annan av profetarne.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, '«Kven segjer då de at eg er?» spurde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Då tok Simon Peter til ords og sagde: «Du er Messias, den livande Guds Son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Og Jesus sagde til honom: «Sæl er du, Simon Jonason! for det er ikkje kjøt og blod som hev lært deg det, men far min i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Og no segjer eg deg at du er Peter; yver den steinen vil eg byggja mi kyrkja, og helheimsportarne skal ikkje vinna yver henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Eg vil gjeva deg lyklarne til himmelriket; det som du bind på jordi, skal vera bunde i himmelen, og det som du løyser på jordi, skal vera løyst i himmelen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'So forbaud han læresveinarne å segja det med nokon at han var Messias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Frå den tidi tok Jesus til å syna læresveinarne at han laut fara til Jerusalem og tola mykje vondt av styresmennerne og dei øvste prestarne og dei skriftlærde, og at dei kom til å drepa honom, men tridje dagen skulde han standa upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Peter tok honom til sides og for til å telja for honom og sagde: «Hjelpe deg Gud, Herre! Slikt må aldri henda deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Då snudde han seg imot Peter og sagde: «Gakk utor augo mine, Satan! Du er meg eit styggje, for du hev’kje ans for det som er Guds vilje, men berre for det som er menneskjevilje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Same gongen sagde Jesus til læresveinarne sine: «Vil nokon vera i lag med meg, so lyt han gløyma seg sjølv, og taka krossen sin upp og fylgja etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'For den som vil berga livet sitt, skal missa det; men den som misser livet for mi skuld, skal finna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Kva batar det eit menneskje, um han vinn heile verdi, men taper sjæli si? Eller kva hev menneskjet å gjeva i byte for sjæli si?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'For Menneskjesonen skal koma i herlegdomen åt far sin med englarne sine, og då skal han gjeva kvar og ein lika for det dei hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Det segjer eg dykk for visst: Sume av dei som stend her, skal ikkje smaka dauden fyrr dei hev set Menneskjesonen koma i sitt kongelege velde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Seks dagar etter tok Jesus Peter og Jakob og Johannes, bror hans, med seg upp på eit høgt fjell, og der var dei åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Då vart han forklåra for augo deira: andlitet hans skein som soli, og klædi var kvite som ljoset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Og best det var, fekk dei sjå Moses og Elia; dei stod og tala med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Då tok Peter til ords og sagde til Jesus: «Herre, det er godt at me er her! Vil du, so skal eg gjera tri hyttor her, ei åt deg, og ei åt Moses, og ei åt Elia.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Fyrr han hadde tala ut, kom det ei ljos sky og skygde yver deim, og or skyi kom det ei røyst som sagde: «Dette er son min, han som eg elskar, han som eg hev hugnad i. Høyr på honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Då læresveinarne høyrde det, kasta dei seg å gruve og var ovleg rædde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jesus gjekk burt åt deim og tok i deim og sagde: «Reis dykk upp, og ver ikkje rædde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Men då dei såg upp, vart dei’kje vare nokon utan Jesus åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'So gjekk dei ned av fjellet, og Jesus sagde til deim: «Tala ikkje til nokon um den syni de hev havt, fyrr Menneskjesonen hev stade upp frå dei daude!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Då spurde læresveinarne: «Kvi segjer då dei skriftlærde at fyrst lyt Elia koma?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Han svara: «Elia kjem nok, og skal setja alt i rett lag att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'men eg segjer dykk: Elia er alt komen, og dei kjendest ikkje ved honom, men for åt med honom som dei vilde; like eins kjem dei til å fara med Menneskjesonen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Då skyna dei at det var Johannes døyparen han tala til deim um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Då dei hadde nått fram til folket, kom det ein mann og fall på kne for honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, '«Herre, gjer sælebot på son min! Han hev nedfallsotti og lid mykje vondt; tidt fell han i elden, og tidt i vatnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Eg hev vore til læresveinarne dine med honom, men dei kunde ikkje gjera honom god att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Då tok Jesus til ords og sagde: «Å, du vantrune og rangsnudde ætt! Kor lenge skal eg vera hjå dykk? Kor lenge skal eg tola dykk? Kom hit til meg med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'So tala Jesus strengt til honom; då for den vonde åndi utor guten, og han vart god att i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Då Jesus hadde vorte åleine, kom læresveinarne til honom og sagde: «Kvi kunde ikkje me driva den åndi ut?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, '«Av di de er so vantrune,» svara han; «for det segjer eg dykk for sant: Hev de tru, um ho ikkje er større enn eit senapskorn, so kann de segja til dette fjellet: «Flyt deg herifrå og dit!» - då skal det flytja seg, og ingen ting skal vera umogeleg for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Men dette slaget gjeng ikkje ut, utan med bøn og fasta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Med dei ferdast kring i Galilæa, sagde Jesus til deim: «Menneskjesonen skal gjevast yver i menneskjehender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'og dei skal drepa honom, men tridje dagen skal han standa upp att.» Då vart dei ovleg sorgfulle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Då dei var komne til Kapernaum, kom dei som kravde inn tempelskatten, til Peter og sagde: «Legg ikkje meisteren dykkar skatt til templet?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, '«Jau,» segjer han. So gjekk han inn i huset, og fyrr han fekk sagt noko, spurde Jesus: «Kva meiner du, Simon? Kven tek kongarne på jordi toll eller skatt av - av borni sine eller av framande?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, '«Av framande,» svara Peter. «So er borni skattefrie då,» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, '«Men me vil ikkje arga deim - gakk ned til sjøen og kasta ut kroken, og grip den fyrste fisken som kjem upp! Når du so opnar gapet på honom, skal du finna ein stater; tak den og gjev deim for meg og deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'I same bilet kom læresveinarne til Jesus og spurde: «Kven er no den største i himmelriket?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Då kalla han til seg eit lite barn, og sette det midt imillom deim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'og sagde: «Det segjer eg dykk for sant: Vender de’kje um, og vert som borni, so kjem de aldri inn i himmelriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Den som gjer seg sjølv liten som dette barnet, han er den største i himmelriket;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'og den som tek imot eitt sovore barn i mitt namn, han tek imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Men den som freistar nokon av desse små som trur på meg, han var betre faren dei hadde hengt ein kvernstein um halsen på honom og søkkt honom ned i djupaste havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Ve yver verdi for freistingarne hennar! Freistingar lyt det koma, men ve yver den som freistingi kjem frå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Um handi di eller foten din freistar deg, so hogg deim av og kasta deim frå deg! Det er betre for deg å ganga einhendt eller halt inn til livet enn å hava tvo hender og tvo føter og kastast i den ævelege elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Og um auga ditt freistar deg, so riv det ut og kasta det frå deg! Det er betre for deg å ganga einøygd inn til livet enn å hava tvo augo og kastast i helveteselden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Agta dykk at de ikkje vanvyrder nokon av desse små! for eg segjer dykk at englarne deira i himmelen allstødt fær sjå åsyni åt far min i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'For Menneskjesonen er komen for å frelsa det som var fortapt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Kva trur de? - Um ein mann hev hundrad sauer, og ein av deim villar seg burt, let han’kje då dei ni og nitti ganga lause i fjellet og tek ut og leitar etter den som fer vilt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'og hender det at han finn honom, då segjer eg dykk for visst: Han gleder seg meir yver honom enn yver dei ni og nitti som ikkje hev villa seg burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Soleis vil ikkje heller far dykkar i himmelen at ein einaste av desse små skal fortapast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Hev bror din synda imot deg, so gakk til honom og tala honom til rettes på tvomannshand! Høyrer han på deg, so hev du vunne bror din;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'men vil han ikkje høyra, so tak med deg endå ein eller tvo, so kvar ting kann provast med tvo eller tri manns vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Høyrer han ikkje på deim, so seg det til kyrkjelyden! Og høyrer han ikkje på kyrkjelyden heller, då skal han vera som ein heidning og tollmann for deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Det segjer eg dykk for sant: Alt det de bind på jordi, skal vera bunde i himmelen, og alt det de løyser på jordi, skal vera løyst i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Sameleis segjer eg dykk: Alt det som tvo av dykk her på jordi er samde um å beda um, det skal dei få av far min i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'For der som tvo eller tri er samla i mitt namn, der er eg midt imillom deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Då gjekk Peter fram og sagde: «Herre, kor mange gonger skal eg tilgjeva bror min når han hev synda imot meg - so mykje som sju gonger?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jesus svara: «Ikkje sju gonger, segjer eg deg, men sytti gonger sju gonger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'For himmelriket kann liknast med ein konge som vilde gjera upp rekneskapen med tenarane sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Då han no tok til med uppgjerdi, førde dei fram for honom ein som var skuldig ti millionar dalar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Men han hadde’kje noko å greida det med. So sagde herren hans at han skulde seljast, både han og kona hans og borni og alt det han åtte, so gjelda kunde greidast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Då fall tenaren på kne for honom og sagde: «Ver tolug med meg, so skal du få det alt saman!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Og herren tykte synd i tenaren sin og gav honom fri, og ettergav honom skuldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Då den same tenaren kom ut att, møtte han ein av dei andre tenarane, som var skuldig honom tjuge dalar, og han greip honom og vilde strøypa honom, og sagde: «Kom med det du er skuldig!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Då fall den andre på kne og bad for seg og sagde: «Ver tolug med meg, so skal du få det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Men han vilde ikkje; han tok og sette medtenaren sin i fengsel; der skulde han sitja til skuldi var greidd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Då dei andre tenarane såg kva som gjekk fyre seg, vart dei ille ved; og dei gjekk til herren sin, og fortalde honom alt det som var hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Då kalla herren honom fyre seg og sagde til honom: «Du vonde tenar! Heile den store skuldi di gav eg deg etter då du bad meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Skulde so’kje du og ha vore mild imot medtenaren din, som eg var imot deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Og herren hans vart harm og gav honom yver til fangevaktarane, so dei skulde pina honom til han hadde greidt all skuldi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'So skal og far min i himmelen gjera med dykk, når de ikkje av hjarta tilgjev kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Då Jesus hadde tala desse ordi, bar det so til at han tok ut frå Galilæa og for til Juda-bygderne. Han lagde vegen gjenom landet på hi sida Jordan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'mykje folk fylgde honom der, og han lækte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Då kom farisæarane til honom, og vilde freista honom og sagde: «Tru ein mann hev lov til å skilja seg frå kona si, kva orsak han tykkjest hava?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Han svara: «Hev de’kje lese at skaparen alt ifrå det fyrste skapte deim mann og kvinna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'og sagde: «Difor skal mannen skiljast med far sin og mor si og halda seg hjå kona si, og dei tvo skal vera eitt kjøt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'So er dei då ikkje lenger tvo, men eitt kjøt, og det som Gud hev bunde i hop, det skal ikkje menneskja skilja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Segjer dei til honom: «Kvi sagde då Moses at mannen skulde gjeva kona skilsmålsbrev og senda henne frå seg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, '«For dykkar harde hjarto skuld gav Moses dykk lov til å skiljast frå konorne dykkar,» svara han, «men frå det fyrste hev det ikkje vore so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Og det segjer eg dykk, at den som skil seg frå kona si for anna enn utruskap, og gifter seg med ei onnor, han gjer hor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Då sagde læresveinarne til honom: «Er det den retten som gjeld millom mann og kona, då er det ikkje godt å gifta seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Han svara: «Det er noko som ikkje alle kann læra, men berre dei som hev fenge gåva til det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'for det finst gjeldingar som er fødde so av morsliv, og det finst gjeldingar som folk hev gjeldt, og det finst gjeldingar som hev gjeldt seg sjølve for himmelriket skuld. Lat deim skyna det dei som kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'So bar dei småborn til honom, og bad han vilde leggja henderne på deim og beda for deim. Læresveinarne truga deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'men Jesus sagde: «Lat småborni vera, og hindra deim ikkje å koma til meg! For himmelriket høyrer sovorne til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Og han lagde henderne på deim, og for so derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Då kom det ein til honom og sagde: «Meister, kva godt skal eg gjera so eg kann få eit æveleg liv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, '«Kvi spør du meg um det som er godt?» svara han. «Det er berre ein som er god. Men vil du ganga inn til livet, so haldt bodi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, '«Kva for bod?» spurde han. «Desse,» svara Jesus: «Du skal ikkje drepa! Du skal ikkje gjera hor! Du skal ikkje stela! Du skal ikkje vitna rangt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Du skal æra far din og mor di! Du skal elska grannen din som deg sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, '«Alt det hev eg halde,» segjer den unge mannen; «kva er det då som vantar meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jesus svara: «Vil du vera fullkomen, so tak og sel det du eig, og gjev det til dei fatige! då skal du få ein skatt i himmelen; og kom so og fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Då den unge mannen høyrde det, vart han ille ved, og gjekk burt; for han hadde mykje gods.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Då sagde Jesus til læresveinarne sine: «Det segjer eg dykk for sant: Det er vandt for ein rik å koma inn i himmelriket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Ja, eg segjer dykk: Ein kamel kjem lettare gjenom eit nålauga enn ein rik kjem inn i Guds rike.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Då læresveinarne høyrde det, vart dei reint forfærde og sagde: «Kven kann då verta frelst?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jesus såg på deim og sagde: «For menneskje er det umogelegt, men for Gud er alt mogelegt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Då tok Peter til ords og sagde til honom: «Sjå, me hev gjeve ifrå oss alt og fylgt deg; kva skal då me få?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Og Jesus svara: «Det segjer eg dykk for sant: Når alt vert nytt, og Menneskjesonen sit i sin glimande kongsstol, då skal de og, som hev fylgt meg, sitja i tolv høgsete og styra dei tolv Israels-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Og kvar som hev skilt seg med hus eller brør eller syster eller far eller mor eller born eller gardar for mitt namn skuld, han skal få det att mange gonger og erva eit ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Men mange av dei fyrste skal vera dei siste, og mange av dei siste dei fyrste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'For himmelriket kann liknast med ein husbond som gjekk ut tidleg um morgonen og vilde leiga arbeidsfolk til vingarden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Han vart samd med arbeidsfolki um ei mark for dagen, og sende deim burt i vingarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'So gjekk han ut ikring den tridje timen, og fekk sjå nokre andre som stod gjerandslause på torget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Han sagde til deim: «Gakk de og burt i vingarden, og det som rett er, skal de få.» So gjekk dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Sidan gjekk han ut ikring den sette og niande timen og gjorde like eins.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Då det leid til den ellevte timen, gjekk han ut att, og fann endå nokre som stod der. Han segjer til dei: «Kvi stend de her arbeidslause heile dagen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, '«Av di ingen hev leigt oss,» svara dei. «Gakk de og burt i vingarden!» sagde han då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Um kvelden sagde vingardseigaren til hushaldaren sin: «Ropa inn arbeidsfolket, og lat deim få løni si! Tak til med dei siste, og haldt fram til dei fyrste!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'So kom dei som var leigde kring den ellevte timen, og fekk ei mark kvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Då dei fyrste kom, tenkte dei at dei skulde få meir; men dei fekk og kvar si mark;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'då dei fekk den, mukka dei mot husbonden og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, '«Desse siste hev’kje arbeidt meir enn ein time, og so gjev du deim likt med oss, som hev slite og sveitta heile dagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Då svara han ein av deim: «Eg gjer deg ikkje urett, venen min. Var me’kje samde um ei mark?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Tak du ditt og gakk! Men eg hev hug til å gjeva denne siste likso mykje som deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Hev eg’kje lov til å gjera med mitt som eg vil? Eller ser du ilt til det at eg gjer vel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Soleis skal dei siste vera dei fyrste, og dei fyrste dei siste; for mange er kalla, men få utvalde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Med Jesus var på vegen til Jerusalem, tok han dei tolv læresveinarne til sides og sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '«No fer me upp til Jerusalem, og Menneskjesonen skal gjevast i henderne på dei øvste prestarne og dei skriftlærde, og dei kjem til å døma honom frå livet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'og gjeva honom yver til heidningarne, so dei skal spotta og hudfletta og krossfesta honom; men tridje dagen skal han standa upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Då kom mor åt Sebedæus-sønerne til honom med sønerne sine, og fall på kne og bad honom um noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, '«Kva er det du vil?» spurde han. Ho svara: «Seg at desse tvo sønerne mine skal få sitja innmed deg i riket ditt, den eine på di høgre og den andre på di vinstre sida!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, '«De veit ikkje kva de bed um,» sagde Jesus. «Kann de drikka den skåli som eg lyt drikka?» «Ja, det kann me,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Då sagde han: «Mi skål skal de nok drikka, men sæte ved mi høgre og vinstre sida kann ikkje eg gjeva nokon; det lyt dei få som far min hev etla det åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Då dei ti høyrde det, vart dei harme på dei tvo brørne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Då kalla Jesus deim kring seg og sagde: «De veit at fyrstarne råder yver folki sine, og dei store hev velde yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Men so skal det ikkje vera hjå dykk; den som vil verta stor millom dykk, lyt tena dei andre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'og den som vil vera den fyrste av dykk, lyt vera træl for dei andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Menneskjesonen er’kje heller komen for å tenast, men for å tena og gjeva livet sitt til løysepening for mange.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Då dei tok ut frå Jeriko, fylgde det mykje folk med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Attmed vegen sat det tvo blinde, og då dei høyrde at Jesus for framum, ropa dei: «Gjer sælebot på oss, Herre, du Davids son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Folket truga deim, og sagde dei skulde tegja; men dei ropa endå meir: «Herre, gjer sælebot på oss, du som er Davids son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Då stana Jesus og ropa på deim og sagde: «Kva vil de eg skal gjera for dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, '«Herre, lat oss få att syni!» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Jesus tykte synd i deim og tok burtpå augo deira; og med ein gong kunde dei sjå, og dei fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Då dei var komne til Betfage, til Oljeberget, og ikkje hadde langt att til Jerusalem, då sende Jesus tvo læresveinar i veg og sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, '«Gakk inn i den grendi som ligg beint framfor dykk! Der finn de straks ei asna som stend bundi, og ein fole attmed henne; dei skal de løysa og leida hit til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Og er det nokon som talar til dykk, so seg: «Herren treng um deim;» då sender han deim hit med ein gong.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Dette hende av di det laut sannast det som er tala gjenom profeten, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '«Seg til Sions dotter: Sjå, her kjem din konge til deg. Mjuk i åndi rid han på eit asen, folen åt eit klyvdyr.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Læresveinarne gjekk og gjorde som Jesus hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Dei henta asna og folen, og lagde kjolarne sine på deim, og so sette han seg uppå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Og størsteparten av folket breidde klædi sine på vegen; andre braut kvister av trei og strådde på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Og folkehoparne som gjekk fyre og fylgde etter, ropa: «Hosianna Davids son! Velsigna vere han som kjem i Herrens namn! Hosianna i det høgste!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Då han so drog inn i Jerusalem, vart det eit heilt oppstyr i byen; dei spurde: «Kven er dette?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Og folkehoparne svara: «Det er profeten, Jesus frå Nasaret i Galilæa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'So gjekk Jesus inn i Guds tempel og dreiv ut alle som handla i heilagdomen; han velte bordi åt pengevekslarane og krakkarne åt deim som selde duvor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'og sagde til deim: «Det stend skrive: «Mitt hus skal kallast eit bønehus,» men de gjer det til eit røvarbol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'I templet kom det blinde og halte til honom, og han gjorde deim gode att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Men då dei øvste prestarne og dei skriftlærde såg underi han gjorde, og høyrde borni som ropa i templet: «Hosianna Davids son!» so vart dei arge og sagde til honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, '«Høyrer du kva desse segjer?» «Ja!» svara han. «Hev de aldri lese: «Av småsveins mål og sogbarns låt hev du ein lovsong laga deg?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'So gjekk han frå deim og ut or byen, til Betania, og var der med natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Då han gjekk inn til byen att um morgonen, vart han svolten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Då fekk han sjå eit einsleg fiketre attmed vegen. Han gjekk der burt, men fann’kje anna på treet enn lauv. Då sagde han til det: «Aldri i verdi skal det koma frukt på deg meir.» Og straks turka fiketreet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Då læresveinarne såg det, undra dei seg og sagde: «Korleis kunde det hava seg at fiketreet turka so brått?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jesus svara: «Det segjer eg dykk for sant: Dersom de trur og ikkje tvilar, so skal de gjera større ting enn det med fiketreet, ja, um de so segjer til dette fjellet: «Lyft deg upp og kasta deg ut i havet!» so skal det verta so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Og alt de bed um, skal de få, so sant de trur.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'So gjekk han inn i templet, og med han lærde folket, kom dei øvste prestarne og styresmennerne for lyden burt til honom og sagde: «Kva rett hev du til å gjera dette, og kven gav deg den retten?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, '«No vil eg og spyrja dykk um ein ting,» sagde Jesus; «svarar de meg på det, so skal eg segja dykk kva rett eg hev til å gjera dette:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Kvar var dåpen åt Johannes ifrå - frå himmelen eller frå menneskje?» Då sagde dei seg imillom: «Svarar me: «Frå himmelen,» so segjer han: «Kvi trudde de honom då ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Og svarar me: «Frå menneskje,» då må me ræddast folket; for alle held Johannes for ein profet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'So svara dei: «Det veit me ikkje.» «Då vil ikkje eg heller segja dykk kva rett eg hev til å gjera dette,» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, '«Men kva meiner de um det: Det var ein mann som hadde tvo søner. Han kom til den eine og sagde: «Gakk burt i vingarden, og arbeid der i dag, son min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, '«Nei, eg vil ikkje,» svara han, men sidan angra han på det og gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'So kom faren til den andre, og sagde det same med honom. «Ja, herre, det skal eg,» svara han, men han gjekk ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Kven av dei tvo gjorde no det faren vilde?» «Den fyrste,» svara dei. Då sagde Jesus til deim: «Det segjer eg dykk for sant: Tollmenner og skjøkjor kjem fyrr inn i Gudsrike enn de.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'For Johannes kom til dykk på rettferdsvegen, men de trudde honom ikkje. Tollmennerne og skjøkjorne dei trudde honom; men endå de såg det, kom de ikkje på andre tankar, og trudde honom ikkje då heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Høyr no ei onnor likning: Det var ein gong ein husbonde, som laga ein vingard, og sette gjerde kringum, og stelte til ei vinpersa, og bygde eit tårn; so leigde han hagen burt til brukarar og for ut or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Då det no leid til at dei skulde hausta av hagen, sende han sveinarne sine til brukarane etter avlingi han skulde hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Men brukarane greip sveinarne hans: ein skamslo dei, og ein drap dei, og ein steina dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'So sende han andre sveinar, fleire enn fyrste gongen; men dei gjorde like eins med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Sist so sende han son sin til deim og sagde: «Dei hev no vel age for son min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Men då brukarane såg sonen, sagde dei seg imillom: «Sjå der er ervingen! Kom, lat oss slå honom i hel og eigna til oss arven hans!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'So tok dei honom og støytte honom ut or vingarden og slo honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Når no vingardseigaren kjem, kva skal han då gjera med desse brukarane?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, '«Med vondt skal han løna desse vonde mennerne,» svara dei; «han skal gjera ende på deim, og vingarden skal han leiga burt til andre brukarar, som gjev han avlingi i rette tid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Då sagde Jesus til dei: «Hev de aldri lese i skrifterne: «Den steinen som byggjarane vanda, den var det som vart hyrnestein; D’er Herren sjølv som so hev gjort det; for oss er det eit under stort?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Difor segjer eg dykk at Gudsriket skal takast ifrå dykk og gjevast til eit folk som ber dei frukterne som høyrer til der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Og den som fell på steinen, han skal slå seg sund, men den som steinen fell på, skal han smuldra til dust.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Då dei øvste prestarne og farisæarane høyrde likningarne hans, skyna dei at det var deim han tala um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Og dei tenkte på å gripa honom, men torde ikkje for folket; for dei heldt honom for ein profet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'So tok Jesus til ords att og sagde dei ei onnor likning:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '«Himmelriket kann liknast med ein konge som gjorde bryllaup åt son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Han sende ut sveinarne sine, og kalla deim som var bedne til bryllaups; men dei vilde ikkje koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'So sende han andre sveinar og sagde: «Seg til deim som er bedne: «No hev eg stelt til bryllaupsmaten; uksane mine og gjødfeet er slagta, og alt er ferdigt. Kom no til bryllaups!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Men dei brydde seg ikkje um det; ein gjekk ut på åkeren sin og ein annan til krambudi si;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'og dei hine greip sveinarne hans, og skamførde deim og drap deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Då vart kongen harm. Han sende ut herarne sine og gjorde ende på dråpsmennerne og brende upp byen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'So sagde han til sveinarne sine: «Alt er ferdigt til bryllaupet, men dei bedne var ikkje verde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Gakk no ut på vegar og vegskil og bed til bryllaups alle deim de finn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'So gjekk sveinarne ut på vegarne og bad i hop alle dei fann, både vonde og gode, og bryllaups-stova vart full av gjester.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Då so kongen kom inn og vilde sjå gjesterne, vart han var ein som ikkje var bryllaupsklædd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Han segjer til honom: «Kjære, korleis hev du kome inn her og er ikkje bryllaupsklædd?» Men han kunde ingen ting svara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Då sagde kongen til bordsveinarne: «Bitt hender og føter på honom, og kasta honom ut i myrkret utanfor, der dei græt og skjer tenner!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'For mange er kalla, men få er utvalde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Då gjekk farisæarane burt og lagde råd um korleis dei skulde få fanga honom i ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Dei sende læresveinarne sine til honom i lag med Herodes-mennerne og let deim segja: «Meister, me veit du er ærleg, og det er sanning det du lærer oss um Guds veg, og du bryr deg ikkje um nokon; for du gjer ikkje skil på folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Seg oss no: Kva meiner du? Er det rett å svara skatt til keisaren, eller er det ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Men Jesus skyna den vonde meiningi deira og sagde: «Kvi freistar de meg, hyklarar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Lat meg sjå skattemynti!» So flidde dei honom ein sylvpening.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, '«Kva er dette for eit bilæte og namn?» spurde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, '«Det er keisarens,» svara dei. Då sagde han til deim: «So gjev keisaren det som keisarens er, og Gud det som Guds er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Då dei høyrde det, undra dei seg og gjekk burt ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Same dagen kom det nokre sadducæarar til honom - det er dei som segjer at det ikkje er nokor uppstoda - dei sette fram eit spursmål for honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '«Meister, Moses hev sagt: «Når ein mann døyr barnlaus, so skal bror hans gifta seg med enkja og halda uppe ætti åt bror sin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'No var det sju brør hjå oss. Den eine gifte seg, og døydde; han hadde ikkje born, og let etter seg kona si til broren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Like eins den andre og den tridje, radt til den sjuande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Etter deim alle døydde kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Kven av dei sju skal no ho høyra til i eit anna liv? For dei hev havt henne alle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus svara: «De fer vilt, av di de ikkje kjenner skrifterne og ikkje Guds magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'For i eit anna liv er det ingen som gifter seg eller vert burtgift; dei er som Guds englar i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Men at dei avlidne skal standa upp att, hev de’kje lese kva Gud hev tala til dykk um det, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '«Eg er Abrahams Gud og Isaks Gud og Jakobs Gud?» Og han er ikkje Gud for dei daude, men for dei livande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Då folket høyrde det, vart dei reint upp i under yver læra hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'So snøgt som farisæarane fekk høyra at han hadde målbunde sadducæarane, samla dei seg kringum honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'og ein av deim, som var kunnig i lovi, vilde freista honom og spurde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '«Meister, kva bod er det største i lovi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Han svara: «»Du skal elska Herren, din Gud, av alt ditt hjarta og av all din hug og av alt ditt vit!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Det er det største og fyrste bodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Men det er eit anna som likjest det, og det er: «Du skal elska næsten din som deg sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'På desse tvo bodi kviler heile lovi og profetarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Med farisæarane var samla, spurde Jesus deim åt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '«Kva trur de um Messias? Kven er han son åt?» «Åt David,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Då sagde han: «Korleis kann då David i Anden kalla honom herre, når han segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '«Herren sagde til herren min: «Sit ved høgre handi mi, til eg dine fiendar fær for dine føter lagt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Kallar no David honom herre, korleis kann han då vera son hans?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Men ingen kunde svara honom eit ord. Og ingen torde etter den dag koma med fleire spursmål til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Sidan tala Jesus til folket og til læresveinarne sine og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '«På Moses’ stol sit dei skriftlærde og farisæarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Alt det dei segjer til dykk, lyt de gjera og halda, men etter gjerningarne deira skal de ikkje fara! For dei segjer det, men dei gjer det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Dei bind i hop tunge byrder og legg på herdarne åt folk, men sjølve vil dei ikkje leda deim med ein finger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Alt det dei gjer, gjer dei so folk skal sjå kor gjæve dei er. Dei gjer sine bøneband breide og duskarne på kjolen sin store.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Dei trår etter dei høgste sæti i gjestebodi og dei fremste sessarne i synagogorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'og vil at folk skal helsa deim på torget og kalla dei rabbi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Men de skal ikkje lata nokon kalla dykk rabbi; for det er ein som er meisteren dykkar, og de er alle brør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Og far skal de ikkje kalla nokon på jordi; for de hev ein far, han i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Ikkje skal de heller lata nokon kalla dykk lærar; for de hev ein lærar, Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Den største av dykk skal vera den som tener dei andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'For den som gjer seg sjølv stor, han skal gjerast liten, og den som gjer seg sjølv liten, han skal gjerast stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Men ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de stengjer himmelriket for folk; sjølve gjeng de ikkje inn, og deim som gjerne vilde, let de ikkje få koma inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de et upp husi for enkjor og gjer lange bøner for ei syn skuld; for dette skal de få strengare dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de fer land og strand og leitar etter ein fylgjesvein, og finn de ein, so gjer de honom til eit helvitesbarn, tvo gonger verre enn de er sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Ve yver dykk, blinde vegleidarar! de som segjer: «Um ein sver ved templet, so er det’kje noko, men sver han ved gullet i templet, då er han bunden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Dårar og blinde! Kva er størst, gullet, eller templet som gav gullet si vigsla?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'og: «Um ein sver ved altaret, so er det’kje noko, men sver han ved offeret som er på det, då er han bunden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Blindingar! Kva er då størst, offeret, eller altaret som vigslar offeret?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'For den som då sver ved altaret, sver både ved det og alt som er på det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'og den som sver ved templet, sver både ved det og ved honom som bur i det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'og den som sver ved himmelen, sver ved Guds høgsæte og ved honom som sit der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de gjev tiend av mynta og anis og karve, men ansar ikkje det som veg meir i lovi, rettferd og miskunn og truskap. Det skulde ein gjera, og ikkje lata vera hitt heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Blinde vegleidarar, som silar av myhanken, men svelgjer kamelen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de reinskar skåler og fat utanpå, men inni er dei fulle av ran og måteløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Blinde farisæarar! Gjer fyrst skåli og fatet reine inni, so vert ho rein utanpå og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de likjest kalka graver; utanpå er dei væne å sjå til, men inni er dei fulle av daudingbein og allslags ureinskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Soleis er de og utanpå rettferdige å sjå til for folk, men inni dykk er de fulle av hyklarskap og urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Ve yver dykk skriftlærde og farisæarar, hyklarar som de er! de byggjer minnesmerke yver profetarne og pryder graverne åt dei rettferdige og segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, '«Hadde me vore til då federne våre livde, so hadde me ikkje vore med deim og drepe profetarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'So vitnar de då um dykk sjølve at de er born åt deim som slo profetarne i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Haldt no fram på same vis som federne dykkar, til målet er fullt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'De eiterormar, de slange-ungar, korleis kann de sleppa undan helvitesdomen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Sjå, difor sender eg til dykk profetar og vismenner og skriftlærde; sume av dei kjem de til å drepa og krossfesta, og sume til å hudfletta i synagogorne dykkar og jaga frå by til by,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'so det skal koma yver dykk alt det skuldlause blodet som hev runne på jordi, frå den skuldlause Abel og til Zakarja, son åt Barakias, han som de drap millom templet og altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Det segjer eg dykk for visst: Yver denne ætti skal det koma alt saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, du som slær i hel profetarne, og steinar deim som er sende til deg, kor tidt hev eg’kje vilja samla borni dine kring meg, liksom ein fugl samlar ungarne sine under vengjerne! Men de vilde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Sjå no skal de få hava huset dykkar audt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'For eg segjer dykk: De fær aldri sjå meg meir fyrr de ropar: «Velsigna vere han som kjem i Herrens namn!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Då Jesus steig ut or templet og tok til å ganga burtetter vegen, gjekk læresveinarne fram og vilde syna honom tempelbygningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, '«Ja, ser de’kje alt dette!» svara han. «Det segjer eg dykk for sant: Her ligg ikkje stein på stein som ikkje skal rivast ned.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Sidan, då han sat på Oljeberget, og ingen annan var med, gjekk læresveinarne fram til honom og sagde: «Seg oss: Når skal alt dette henda, og kva merke skal me hava på koma di og enden på verdi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Då svara Jesus: «Sjå dykk fyre, so ingen forvillar dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'For mange skal taka mitt namn og segja: «Eg er Messias», og føra mange på avveg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'De skal få høyra ufred og gjetord um ufred; sjå til at de ikkje vert skræmde! For dette lyt henda; men endå er ikkje enden komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Folk skal reisa seg imot folk, og rike mot rike, og det skal vera uår og jordskjelv kring i landi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'men alt det er berre upptaket til føderiderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Då skal dei driva dykk ut i naud og fåre og slå dykk i hel, og alle folk skal hata dykk for mitt namn skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Mange skal då falla ifrå, og svika og hata kvarandre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'og mange falske profetar skal stiga fram og føra mange på avveg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'og av di uretten hev vorte so stor, skal kjærleiken kolna hjå mengdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Men den som held ut til endes, han skal verta frelst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Og dette evangeliet um Gudsriket skal kunngjerast yver heile mannaheimen, so alle folkeslag fær vita um det, og då skal enden koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Når de då ser at den øydande styggedomen som Daniel, profeten, hev tala um, stend på den heilage staden» - agta vel på dette du som les! -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'då lyt dei som er i Judalandet røma til fjells,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'og den som er uppå taket, må ikkje stiga ned og henta noko i huset sitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'og den som er utpå marki, må ikkje ganga heim att etter kjolen sin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Stakars deim som gjeng med barn eller gjev brjost i dei dagarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Men bed at det ikkje må vera um vinteren eller på ein kviledag de lyt røma!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'For då skal det vera slik hard naud at det aldri hev vore slik naud frå verdi vart til og til no, og vert ikkje sidan heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Og vart ikkje den tidi stutt, so fanst det’kje liv som vart berga; men for dei utvalde skuld skal den tidi vera stutt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Um nokon då segjer til dykk: «Sjå her er Messias,» eller «der,» so må de ikkje tru det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'For det skal standa fram falske Messias’ar og falske profetar og gjera store teikn og under, so jamvel dei utvalde kunde forvillast, um det var råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Kom i hug: Eg hev sagt dykk det fyreåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Segjer dei no med dykk: «Han er ute i øydemarki,» so gakk ikkje der ut! eller: «Han er inni koven,» so tru det ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'For liksom ljonet gjeng ut ifrå aust og skin radt til vest, so skal det vera når Menneskjesonen kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Der åta er, vil ørnarne sankast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Men straks etter dei dagarne og trengslorne deira skal soli myrkjast, og månen missa sitt ljos; stjernorne skal falla ned frå himmelen, og himmelkrafterne skakast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Då skal teiknet åt Menneskjesonen syna seg på himmelen, og alle ætter på jordi skal øya og gråta, og dei skal sjå Menneskjesonen koma i himmelskyerne med velde og stor herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Med luren ljomar, skal han senda ut englarne sine, og dei skal sanka i hop dei han hev valt seg ut, frå heimsens fire hyrno, frå himmelbrun til himmelbrun.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Lær ei likning av fiketreet: Når sevja hev kome i greinerne, og lauvet tek til å spretta, då veit de at sumaren er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Like eins når de ser alt dette; då veit de at han er utfor døri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Det segjer eg dykk for visst: Denne ætti skal ikkje forgangast fyrr alt dette hev hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Himmel og jord skal forgangast, men mine ord skal aldri forgangast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Men den dagen og timen veit ingen, ikkje englarne i himmelen - ingen utan Faderen åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'For som det var i Noahs dagar, so skal det vera når Menneskjesonen kjem:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'liksom dei i dagarne fyre storflodi åt og drakk, og gifte seg og vart burtgifte, alt til den dagen då Noah gjekk inn i arki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'og ingen visste ordet av fyrr storflodi kom og tok deim alle burt, so skal det vera når Menneskjesonen kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Då er tvo menner ute på marki; den eine vert henta, og den andre vert att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Tvo kvinnor mel på kverni; den eine vert henta, og den andre vert att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'So vak då! For de veit ikkje kva dag herren dykkar kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Men det skynar de, at dersom husbonden visste kva tid på natti tjuven kom, so vakte han og let ingen brjota seg inn i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Difor lyt de og vera ferdige! Menneskjesonen kjem på ei tid de ikkje ventar honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kvar er no den trugne og vituge drengen som husbonden hev sett yver tenestfolket, so han skal gjeva deim mat i rett tid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Sæl er den drengen som husbonden ser gjera so når han kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Det segjer eg dykk for visst: Han skal setja honom yver alt det han eig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Men er drengen ein skarv, og segjer med seg: «Husbonden min vert lenge burte,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'og han so tek til å slå dei hine tenarane, og et og drikk i lag med drikkarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'då skal husbonden hans koma på ein dag han ikkje ventar det, og i ein time han ikkje veit av,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'og skjera honom midt i tvo, og lata honom få sin lut med hyklarane, der dei græt og skjer tenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Då kann himmelriket liknast med ti brurmøyar som tok lamporne sine og gjekk til møtes med brudgomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Fem av dei var dårlege og fem vituge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Då dei dårlege tok lamporne sine, tok dei ikkje olje med seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'men dei vituge tok olje med seg i krukkor attåt lamporne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Då det no drygde fyrr brudgomen kom, vart dei alle trøytte og sovna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Men midt på natti høyrdest eit rop: No kjem brudgomen! Gakk ut og tak imot honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Då vakna alle brurmøyarne og stelte lamporne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Og dei dårlege sagde til dei vituge: «Lat oss få noko olje hjå dykk! Lamporne våre sloknar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, '«Nei,» svara dei vituge, «det rekk ikkje til både åt oss og dykk. De lyt heller ganga til kræmaren og kjøpa dykk noko.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Med dei då var burte og vilde kjøpa, kom brudgomen. Dei som var ferdige, gjekk med honom inn til bryllaupet, og døri vart stengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Då det leid um eit bil, kom dei hine møyarne og, og sagde: «Herre, herre, lat upp for oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Men han svara: «Det segjer eg dykk for sant: Eg kjenner dykk ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'So vak då! For de veit korkje dag eller time.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Det er liksom med ein mann som vilde fara utanlands. Han kalla tenarane sine inn, og flidde deim midelen sin:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'ein gav han fem tusund dalar, ein annan tvo tusund, og den tridje eitt tusund, etter som kvar dugde til, og so for han or landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Den som fekk fem tusund dalar, tok straks til å handla med deim, og vann seg fem tusund til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Sameleis den som fekk tvo tusund; han og vann tvo tusund til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Men den som fekk eitt tusund, gjekk burt og grov eit hol i jordi og gøymde pengarne åt husbonden sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'So leid det ei lang tid, då kom husbonden heim att og kravde rekneskap av tenarane sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Og han som hadde fenge fem tusund dalar, gjekk fram og hadde med seg fem tusund til og sagde: «Herre, du gav meg fem tusund dalar; sjå her, eg hev vunne fem tusund til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Då sagde husbonden til honom: «Det var rett gjort, du gode og trugne tenar! Du hev vore tru i det som var lite; eg vil setja deg yver mykje. Gakk inn og gled deg med husbonden din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'So gjekk han fram han som hadde fenge tvo tusund dalar, og sagde: «Herre, du gav meg tvo tusund dalar. Sjå her, eg hev vunne tvo tusund til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, '«Det var rett gjort, du gode og trugne tenar!» svara husbonden. «Du hev vore tru i det som var lite; eg vil setja deg yver mykje. Gakk inn og gled deg med husbonden din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Sidan kom han som hadde fenge eitt tusund dalar, og sagde: «Herre, eg kjende deg for ein streng mann, som haustar der du ikkje sådde, og sankar der du ikkje strådde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Difor vart eg rædd, og so gjekk eg burt og gøymde pengarne dine i jordi. Sjå her hev du ditt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Då svara husbonden: «Du låke og late tenar! Du visste at eg haustar der eg ikkje sådde, og sankar der eg ikkje strådde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Skulde du’kje då ha sett pengarne mine i banken! so hadde eg fenge mine att med rentor når eg kom heim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Tak ifrå honom dei tusund dalarne, og gjev deim til den som hev ti tusund!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'For kvar den som hev, han skal få, so han hev nøgdi; men den som ikkje hev, skal missa endå det som han hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Og kasta den duglause tenaren ut i myrkret utanfor, der dei græt og skjer tenner!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Men når Menneskjesonen kjem i sin herlegdom, og alle englarne med honom, då skal han sitja i den glimande kongsstolen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'alle folkeslag skal samlast framfyre honom, og han skal skilja deim åt, liksom hyrdingen skil sauerne frå geiterne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'og setja sauerne på si høgre sida, og geiterne på den vinstre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'So skal kongen segja til deim på høgre sida: «Kom hit, de velsigna borni åt far min, og tak det riket i eige som var etla åt dykk alt ifrå verdi var skapt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'For eg var svolten, og de gav meg mat; eg var tyrst, og de gav meg drikka; eg var heimlaus, og de hyste meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'eg var naken, og de klædde meg; eg var sjuk, og de såg um meg; eg var i fengsel, og de lydde til meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Då tek dei rettferdige til ords og segjer til honom: «Herre, når hev me set deg svolten, og metta deg, eller tyrst, og kveikt deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Når hev me set deg heimlaus, og hyst deg, eller naken, og klædt deg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Når hev me set deg sjuk eller i fengsel, og lydt til deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Og kongen svarar: «Det segjer eg dykk for sant: Alt det de hev gjort mot ein av desse minste brørne mine, det hev de gjort imot meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'So segjer han til deim på vinstre sida: «Gakk burt frå meg, de bannstøytte, til den ævelege elden, som er tilbudd åt djevelen og englarne hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'For eg var svolten, og de gav meg ikkje mat; eg var tyrst, og de gav meg ikkje drikka;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'eg var heimlaus, og de hyste meg ikkje; eg var naken, og de klædde meg ikkje; eg var sjuk, og i fengsel, og de såg ikkje um meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Då tek dei og til ords og segjer: «Herre, når hev me set deg svolten, eller tyrst, eller heimlaus, eller naken, eller sjuk, eller i fengsel, og hev ikkje tent deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Og han svarar: «Det segjer eg dykk for sant: Alt det de ikkje hev gjort mot ein av desse minste, det hev de’kje gjort mot meg heller.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'So skal dei ganga burt til æveleg straff, men dei rettferdige til eit ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Då Jesus hadde tala alle desse ordi, sagde han til læresveinarne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '«De veit at um tvo dagar er det påske; då skal Menneskjesonen gjevast i henderne på uvenerne sine, og dei skal krossfesta honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Då var det dei øvste prestarne og styresmennerne for folket kom saman i garden åt øvstepresten - han heitte Kajafas -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'og lagde yver at dei vilde gripa Jesus med list og slå honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, '«Men ikkje med helgi!» sagde dei; «elles kunde det verta upplaup millom folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Medan Jesus var i Betania, hjå Spilte-Simon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'kom det ei kvinna burt til honom med ei alabaster-krukka full av kosteleg salve; den helte ho ut på hovudet hans då han sat til bords.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Då læresveinarne såg det, vart dei harme og sagde: «Kva skal slik øyding vera til?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Dette kunde vore selt for mange pengar og gjeve til dei fatige.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Jesus gådde det og sagde til deim: «Kvi er de leide med henne? Ho hev då gjort ei god gjerning mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Dei fatige hev de alltid hjå dykk, men meg hev de ikkje alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Då ho slo denne salven ut yver likamen min, då vilde ho bu meg til jordferdi mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Det segjer eg dykk for visst: Kvar i verdi dette evangeliet vert kunngjort, der skal dei og tala um det ho hev gjort, so alle skal minnast henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Då gjekk ein av dei tolv, han som heitte Judas Iskariot, til dei øvste prestarne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'og sagde: «Kva vil de gjeva meg, so skal eg laga det so at de fær honom i dykkar magt?» Då talde dei upp tretti sylvdalar til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Og frå den stundi søkte han eit høve til å gjeva Jesus i henderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Den fyrste dagen i søtebrødhelgi kom læresveinarne til Jesus og sagde: «Kvar vil du me skal laga til påskemålet åt deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Han svara: «Gakk inn i byen til den mannen de veit, og seg med honom: «Meisteren segjer: Det lid innpå tidi for meg; eg vil halda påske hjå deg med læresveinarne mine.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Og læresveinarne gjorde som Jesus sagde, og laga til påskemålet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Då det vart kveld, sette han seg til bords med dei tolv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Og med dei sat og åt, sagde han: «Det segjer eg dykk for sant: Ein av dykk kjem til å svika meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Då vart dei reint ille ved, og tok til å spyrja honom, kvar for seg: «Det er då vel ikkje eg, Herre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, '«Den som duppa med meg i fatet, han er det som vil svika meg,» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, '«Menneskjesonen gjeng fulla burt, soleis som det er skrive um honom, men ve yver den mannen som svik Menneskjesonen! Det var betre for den mannen um han aldri var fødd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Då tok Judas, svikaren, til ords og sagde: «Det er då vel ikkje eg, rabbi?» «No sagde du det sjølv,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Med dei sat til bords, tok Jesus brødet, og signa det og braut det, og gav læresveinarne og sagde: «Tak, og et! Dette er likamen min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Og han tok kalken, og takka, og gav deim og sagde: «Drikk av det alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Dette er blodet mitt, paktblodet, som renn for mange til forlating for synderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Eg segjer dykk, at heretter skal eg’kje drikka av denne druvesafti, fyrr den dagen eg drikk henne ny med dykk i riket åt far min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Då dei so hadde sunge lovsongen, gjekk dei ut til Oljeberget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Då segjer Jesus til deim: «I denne natti kjem de alle til å styggjast ved meg og forlata meg. For det stend skrive: «Hyrdingen slær eg i hel, og saueflokken skal spreidast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Men når eg hev stade upp att, skal eg fara fyre dykk til Galilæa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Då tok Peter til ords og sagde: «Um alle styggjest ved deg, so skal eg aldri styggjast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, '«Det segjer eg deg for sant,» svara Jesus: «Fyrr hanen gjel i natt, kjem du til å avneitta meg tri gonger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Men Peter sagde: «Um eg so lyt døy med deg, skal eg aldri avneitta deg.» Like eins sagde alle læresveinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'So kom Jesus med læresveinarne til ein stad som heiter Getsemane. Då sagde han til deim: «Sit her med eg gjeng der burt og bed!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Og han tok med seg Peter og båe Sebedæus-sønerne, og tok til å syrgja og kvidast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'So segjer han til deim: «Hjarta mitt er so fullt av sorg - det er som det vilde bresta. Ver her og vak med meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Og han gjekk eit lite stykke fram, og lagde seg ned på kne og bad: «Far, er det råd, so lat denne skåli takast ifrå meg! Men ikkje som eg vil, berre som du vil!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Då han kom attende til læresveinarne, såg han at dei sov. Då sagde han til Peter: «So var de’kje god til å vaka ein time med meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Vak og bed, so de ikkje skal koma i freisting! Åndi er viljug, men kjøtet er veikt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'So gjekk han burt att andre gongen og bad: «Far, kann ikkje dette takast ifrå meg, og lyt eg tøma skåli, so lat det vera som du vil!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Då han kom attende, såg han at dei hadde sovna til att; for augo deira var tunge av svevn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Då let han dei vera og gjekk burt att og bad tridje gongen same bøni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'So kom han att og sagde til læresveinarne: «De søv og kviler, de! Sjå no er stundi komi, og Menneskjesonen skal gjevast yver i syndarhender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Statt upp, og lat oss ganga! Svikaren er ikkje langt undan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Fyrr han hadde tala ut, kom Judas, ein av dei tolv, og med honom ein stor flokk med sverd og stavar; dei kom frå dei øvste prestarne og styresmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Svikaren hadde avtala eit teikn med deim og sagt: «Han som eg kysser, han er det; honom skal de taka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Og med det same gjekk han fram til Jesus og sagde: «Heil og sæl, rabbi!» og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jesus sagde til honom: «Kvi er du her, venen min?» So gjekk dei innåt og lagde hand på Jesus og greip honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Men ein av deim som var med honom, tok og drog sverdet sitt, og hogg av øyra på tenaren åt øvstepresten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Då sagde Jesus til honom: «Stikk sverdet ditt i slira! for alle som grip til sverdet, skal falla for sverdet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Eller trur du’kje eg kunde beda far min, og han i denne stundi vilde senda meg meir enn tolv herar med englar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Men korleis skulde då skrifterne sannast, dei som segjer at dette lyt henda?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'I same stundi sagde Jesus til flokken: «De kjem med sverd og stavar og grip meg, som eg skulde vera ein røvar. Dag etter dag sat eg i templet og lærde folket; då tok de meg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Men alt dette hev hendt av di det laut sannast det som profetarne hev skrive.» Då tok alle læresveinarne ut, og rømde ifrå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Dei som hadde gripe Jesus, førde honom til Kajafas, øvstepresten; der var dei skriftlærde og styresmennerne samla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Peter fylgde eit langt stykke etter, og då han kom til garden åt øvstepresten, gjekk han inn og sette seg hjå tenarane - han vilde sjå korleis det gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Dei øvste prestarne og heile det Store Rådet leita etter range vitnemål mot Jesus, so dei kunde få dømt honom frå livet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'men endå mange falske vitne stod fram, fekk dei ikkje noko på honom. Endeleg kom det tvo som sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, '«Denne mannen hev sagt: «Eg kann riva ned Guds tempel og byggja det upp att på tri dagar.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Og øvstepresten reiste seg og sagde til honom: «Svarar du inkje? Kva er det desse vitnar imot deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Men Jesus tagde. Då tok øvstepresten til ords og sagde: «Ved den livande Gud - seg oss: Er du Messias, Guds Son?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Og Jesus svara: «Du hev sjølv sagt det. Men det segjer eg dykk: Frå denne stundi skal de sjå Menneskjesonen sitja ved høgre handi åt Allmagti og koma i himmelskyerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Då reiv øvstepresten sund klædi sine og sagde: «Han hev spotta Gud! Kva skal me med fleire vitne? No høyrde de gudsspottingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Kva meiner no de?» «Han er skuldig til å døy,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'So sputta dei honom i andlitet og slo honom, sume med nevarne og sume med stavar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'og sagde: «Seg oss, Messias: Kven var det som slo deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Medan sat Peter utanfor, i gardsromet. Då kom det ei tenestgjenta burt til honom og sagde: «Du var og med Jesus, galilæaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Men han neitta so alle høyrde det, og sagde: «Eg veit ikkje kva du talar um.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'So gjekk han ut i portromet. Der fekk ei onnor gjenta sjå honom, og sagde til deim som var der: «Han var og med Jesus, nasaræaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Då neitta han atter, og sagde med ein eid: «Eg kjenner ikkje den mannen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Eit lite bil etter kom dei som stod der innåt, og sagde til Peter: «Ja menn er du og ein av deim! Det kann ein høyra på målet ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Då sette han i og banna og svor: «Eg kjenner ikkje den mannen!» Og med det same gol hanen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Då kom Peter i hug dei ordi Jesus hadde sagt til honom: «Fyrr hanen gjel, skal du hava avneitta meg tri gonger.» Og han gjekk ut og gret sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Det var morgon vorte då alle dei øvste prestarne og styresmennerne sagde daudedomen yver Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'So batt dei honom og førde honom burt og gav honom yver til Pilatus, landshovdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Då Judas, svikaren, såg at dei hadde dømt Jesus frå livet, angra han på det han hadde gjort. Han bar dei tretti sylvdalarne attende til dei øvste prestarne og styresmennerne og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, '«Eg hev synda! Det var skuldlaust blod eg gav yver til dykk.» «Kva skil det oss? Det vert di eigi sak,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Då kasta han pengarne frå seg i templet og tok ut; og sidan gjekk han burt og hengde seg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Dei øvste prestarne tok pengarne og sagde: «Det er’kje rett å leggja deim i tempelkista; for det er blodpengar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'So tok dei den rådi at dei for desse pengarne kjøpte Pottemakaråkeren til gravstad for framande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Difor hev den åkeren vore kalla Blodåkeren alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Då vart det sanna det som Jeremia, profeten, hev tala, når han segjer: «So tok dei desse tretti sylvdalarn’ - det var det verd dei hadde sett han i, han som dei verdsette for Israel -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'for Pottemakargården dei det gav, soleis som Herren hadde sagt meg til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'So vart då Jesus førd fram for landshovdingen. Og landshovdingen spurde honom: «Er det du som er konge yver jødarne?» «Du segjer det sjølv,» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Men då dei øvste prestarne og styresmennerne kom med klagemåli sine, svara han ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Då sagde Pilatus til honom: «Høyrer du ikkje alt det dei skuldar deg for?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Men han svara honom ikkje på eit einaste ord, so landshovdingen undra seg storleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Kvar høgtid hadde landshovdingen for vis å gjeva folket ein fange fri, kven dei vilde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Den gongen hadde dei ein ordgjeten fange som heitte Barabbas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Då dei no hadde samla seg, sagde Pilatus til deim: «Kven vil de eg skal gjeva dykk fri, Barabbas eller Jesus, han som dei kallar Messias?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'For han visste at det var av ovund dei hadde gjeve Jesus yver til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Og med han sat i domarsætet, sende kona hans bod til honom og sagde: «Du skal ikkje hava noko med saki mot denne rettferdige mannen! Eg hev drøymt so vondt i natt for hans skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Men dei øvste prestarne og styresmennerne talde folket til å beda Barabbas fri og lata Jesus drepast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Og då landshovdingen tok til ords att og spurde: «Kven av desse tvo vil de eg skal gjeva dykk fri?» svara dei: «Barabbas!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, '«Kva skal eg då gjera med Jesus, han som dei kallar Messias?» sagde han. Då svara deim alle: «Lat honom verta krossfest!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, '«Kva vondt hev han då gjort?» sagde Pilatus. Men dei ropa berre sterkare og sterkare: «Lat honom verta krossfest!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Då Pilatus såg at han ingen ting kunde gjera, men ståket heller vart verre, tok han vatn og tvo henderne sine midt for augo på folkehopen og sagde: «Eg hev ingi skuld i blodet åt denne rettferdige mannen. Dette lyt de svara for!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Då svara heile folket: «Blodet hans må koma yver oss og yver borni våre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'So gav han deim Barabbas fri, men Jesus let han piska, og gav honom yver til hermennerne sine, so dei skulde krossfesta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Hermennerne åt landshovdingen tok Jesus med seg inn i borgi og samla heile vakti kringum honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'So klædde dei av honom, og hengde på honom ei skarlakskåpa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'og dei fletta ein krans av klunger og sette på hovudet hans, og gav honom ein røyrstav i høgre handi. Med so gjort, fall dei på kne for honom spotta honom og sagde: «Heil deg, jødekonge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'So sputta dei på honom, og tok røyrstaven og slo honom i hovudet med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'og då dei hadde spotta honom det dei vilde, tok dei av honom kåpa og hadde på honom hans eigne klæde, og so førde dei honom burt og skulde krossfesta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'På vegen møtte dei ein mann frå Kyrene som heitte Simon. Honom nøydde dei til å bera krossen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Då dei so kom til ein stad som heiter Golgata - det er det same som Skallestaden -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'gav dei honom vin blanda med gall; men då han hadde smaka på det, vilde han ikkje drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'So feste dei honom til krossen. Klædi hans bytte dei millom seg, og drog strå um deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'og so vart dei sitjande der og heldt vakt yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Og uppyver hovudet hans hadde dei skrive klagemålet mot honom; det lydde so: Dette er Jesus, kongen yver jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Saman med honom vart tvo røvarar krossfeste, ein på høgre og ein på vinstre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Dei som gjekk framum, hædde honom og riste på hovudet og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, '«Du som riv ned templet og byggjer det upp att på tri dagar, hjelp deg no sjølv! Er du Guds Son, so stig ned av krossen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Sameleis spotta dei honom, både dei øvste prestarne og dei skriftlærde og styresmennerne, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '«Andre hev han hjelpt, seg sjølv kann han ikkje hjelpa! Han er konge i Israel! Lat honom no stiga ned av krossen, so skal me tru på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Han leit på Gud; lat no Gud berga honom, dersom han bryr seg um honom! Han hev då sagt: «Eg er Guds Son!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Jamvel røvarane som var krossfeste saman med honom, spotta på same visi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Frå den sette timen vart det myrkt yver heile landet, alt til den niande timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Og kring den niande timen ropa Jesus med høg røyst og sagde: «Eli, Eli, lama sabaktani!» Det er det same som: «Min Gud, min Gud, kvi hev du forlate meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Då sagde nokre av deim som stod der og høyrde det: «Han ropar på Elia.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Og med det same sprang ein av deim fram og tok ein svamp og fyllte med vineddik og sette på ein tein, og let honom få drikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Men dei hine sagde: «Venta! Lat oss sjå um Elia kjem og hjelper honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Og Jesus ropa endå ein gong med høg røyst, og gav ut åndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Då rivna forhenget i templet midt i tvo, ovantil og heilt ned, og jordi skalv og bergi brast,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'og graverne opna seg, og mange avlidne heilagmenne stod livs livande upp');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'og dei gjekk fram or graverne, og etter Jesus hadde stade upp att, kom dei inn i den heilage staden og synte seg for mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Då hovudsmannen og dei som var med honom og heldt vakt yver Jesus, såg jordskjelven og alt det som hende, vart dei fulle av otte og sagde: «Dette var sanneleg Guds Son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Det var og mange kvinnor der, som stod eit stykke undan og såg på; dei hadde fylgt Jesus frå Galilæa og tent honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Millom deim var Maria Magdalena, og Maria, mor åt Jakob og Josef, og mor åt Sebedæus-sønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Um kvelden kom det ein rik mann som heitte Josef, og var frå Arimatæa; han hadde og vorte ein læresvein åt Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Han gjekk til Pilatus og bad um han måtte få likamen åt Jesus; og Pilatus sende bod at dei skulde lata honom få han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Då tok Josef likamen og sveipte honom inn i eit reint linty,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'og lagde honom i den nye gravi som han hadde hogge ut åt seg i berget. So velte han ein stor stein attfor gravopningi og gjekk burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Maria Magdalena og den andre Maria var der og; dei sat midt fyre gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Den andre dagen - det var den som kjem etter fyrebuingsdagen - gjekk dei øvste prestarne og farisæarane saman til Pilatus');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'og sagde: «Herre, me kjem i hug at denne folkedåraren sagde med han livde: «Tri dagar etter stend eg upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Set no folk til å vakta vel på gravi til tridje dagen! Elles kunde læresveinarne hans koma og stela honom burt, og segja til folket: «Han hev stade upp frå dei daude,» og då vert den siste dåringi verre enn den fyrste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Då sagde Pilatus: «Her hev de vakt! Gakk no og tak vare på gravi som de best kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'So gjekk dei og sette vakti til å varveitsla gravi, etter dei hadde forsigla steinen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Då kviledagen var liden, og det tok til å ljosna den fyrste dagen i vika, kom Maria Magdalena og den andre Maria og vilde sjå til gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Då vart det brått ein sterk jordskjelv; for ein Herrens engel for ned frå himmelen, og gjekk innåt og velte steinen ifrå og sette seg på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Han var som ein elding å sjå til, og klædi hans var kvite som snø.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Vaktarane skalv av rædsla for honom, og vart liggjande som dei var daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Og engelen tala til kvinnorne og sagde: «Ver ikkje rædde! Eg veit at de leitar etter Jesus, han som vart krossfest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Han er ikkje her; han hev stade upp, som han sagde. Kom og sjå staden der han låg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Og skunda dykk so av stad, og seg med læresveinarne hans: «Han hev stade upp frå dei daude, og no gjeng han fyre dykk til Galilæa; der skal de få sjå honom!» Sjå no hev eg sagt dykk det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Då skunda dei seg burt ifrå gravi med otte og stor gleda, og sprang av stad, vilde bera bod um det til læresveinarne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Men best det var, fekk dei sjå Jesus; han kom imot deim og sagde: «Guds fred!» Då gjekk dei innåt og fall på kne for honom og tok kringum føterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Og Jesus sagde til deim: «Ver ikkje rædde! Gakk og seg med brørne mine at dei skal fara til Galilæa! Der skal dei sjå meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Med dei var på vegen, kom nokre av vaktarane inn til byen, og fortalde dei øvste prestarne alt det som hadde hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Då kom dei og styresmennerne i hop og samrådde seg; og dei gav hermennerne nok av pengar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'og sagde: «Seg at læresveinarne hans kom um natti og stal honom burt medan de sov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Og skulde det koma att for landshovdingen, so skal me tala vel med honom, og laga det so at de kann vera trygge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'So tok dei mot pengarne og gjorde som dei var fyresagde. Soleis kom det ordet ut millom jødarne, og hev halde seg alt til denne dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Dei elleve læresveinarne for til Galilæa, til det fjellet der Jesus hadde sagt deim til å møtast med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Då dei fekk sjå honom, fall dei på kne for honom, men sume tvila.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Og Jesus steig fram og tala til deim og sagde: «Eg hev fenge all magt i himmelen og på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Gakk då ut, og gjer alle folki til læresveinar, med di de døyper deim til namnet åt Faderen og Sonen og den Heilage Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'og lærer deim å halda alt det som eg hev bode dykk. Og sjå, eg er med dykk alle dagar so lenge verdi stend!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Upphavet til evangeliet um Jesus Kristus, Guds Son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Hjå Jesaja, profeten, stend det skrive: «Framfyre deg min ærendsvein eg sender; Der du vil fara, skal han vegen rydja» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '«Høyr han som ropar i heidi: «Rydje vegen åt Herren, jamna stigarne hans!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Soleis stod Johannes, døyparen, fram i øydemarki, og ropa ut umvendingsdåp til forlating for synderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Og heile Judaland kom ut til honom, og alt Jerusalems-folket, og han døypte deim i Jordanåi, med dei sanna synderne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Johannes var klædd i kamelhår og hadde eit lerbelte kring livet, og det han åt, var grashoppar og villhonning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Og han tala til folket og sagde: «Det kjem ein etter meg som er sterkare enn eg; eg er’kje verdig å bøygja meg ned og løysa skobandet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Eg hev døypt dykk med vatn, men han skal døypa dykk med den Heilage Ande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'I dei dagarne hende det, at Jesus kom frå Nasaret i Galilæa og vart døypt i Jordan av Johannes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Og med det same han steig upp or vatnet, såg han korleis himmelen opna seg, og Anden dala ned til honom som ei duva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Og frå himmelen kom det ei røyst: «Du er Son min, som eg elskar! Deg hev eg hugnad i!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Og straks dreiv Anden honom ut i øydemarki;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'og han var i øydemarki i fyrti dagar og vart freista av Satan, og heldt til millom villdyri, og englarne tente han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Då Johannes var sett i fengsel, kom Jesus til Galilæa og kunngjorde evangeliet frå Gud');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'og sagde: «Tidi er fullkomi, og Guds rike er nær! Vend um og tru på evangeliet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Då han ein gong for frammed Galilæasjøen, fekk han sjå Simon og Andreas, bror hans; dei var åt og sette garn i sjøen, for dei var fiskarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Han sagde til deim: «Kom og fylg meg, so skal eg setja dykk til å vera menneskje-fiskarar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Då gjekk dei beint frå garni sine og fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Då han kom litt lenger fram, såg han Jakob, son åt Sebædeus, og Johannes, bror hans; dei var og i båten sin og greidde garni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Og med ein gong kalla han deim, og dei gav seg med honom, og let far sin, Sebedæus, vera att i båten med leigefolket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'So kom dei til Kapernaum, og fyrste kviledag gjekk han inn i synagoga og lærde folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Og dei var reint upp i under yver læra hans; for han lærde deim som ein som hev velde, og ikkje som dei skriftlærde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Den gongen var det der i lyden ein mann med ei urein ånd; han sette i og ropa:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '«Kva vil du oss, Jesus frå Nasaret? Er du komen for å gjera ende oss? Eg veit kven du er - den Heilage frå Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Jesus truga den ureine åndi og sagde: «Teg still, og far ut or honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Då reiv ho og sleit i honom og ill-hua, og for ut or honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Og alle vart forfærde og spurde seg imillom: «Kva er dette? Ei ny og ageleg læra! Jamvel dei ureine ånderne lyt lystra, når han talar til deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Og gjetordet um honom for straks yver alle Galilæa-bygderne derikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Frå synagoga gjekk dei beint heim til Simon og Andreas, i lag med Jakob og Johannes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Vermor åt Simon låg sjuk og hadde hiteflagor, og dei tala straks til Jesus um henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Han gjekk burt til henne og tok henne i handi og reiste henne upp. Då slepte sotti henne, og ho tok til å stella for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Då det vart kveld, og soli var gladd, kom dei til honom med alle som hadde vondt eller var forgjorde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'og heile byen hadde samla seg utfor døri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Og han lækte mange som drogst med ymse sjukdomar, og dreiv ut mange vonde ånder, men han let’kje ånderne få lov til å tala, av di dei kjende honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'I otta, fyrr det vart dag, reis han upp og gjekk ut og burt til ein øydestad; der heldt han bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon og dei som var med honom, skunda seg etter honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'og då dei fann honom, sagde dei til honom: «Alle leitar etter deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Men Jesus svara: «Lat oss fara til ein annan stad, til grenderne her innmed, so eg kann få tala for folket der og; for det var det eg gjekk ut for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'So gjekk han kring i heile Galilæa og tala i synagogorne deira og dreiv dei vonde ånderne ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Ein som hadde spillsykja kom og fall på kne for honom og bad: «Dersom du vil, kann du gjera meg rein!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Jesus tykte vondt um honom, og rette ut handi og tok burtpå honom og sagde: «Eg vil; vert rein!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Og med ein gong gjekk spillsykja av honom, og han vart rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Jesus tala strengt til honom, og bad honom ganga sin veg straks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, '«Agta deg at du ikkje segjer dette med nokon,» sagde han, «men gakk burt og te deg for presten, og ber fram det offeret for reinsingi di som Moses hev sagt, so du kann vitna for deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Men mannen var’kje fyrr komen ut, fyrr han tok til å tala mykje um det og bera det utyver, so Jesus ikkje lenger kunde ganga berrsynt inn i nokon by; han heldt seg utanfor, på øydestader, og der kom dei til honom frå alle kantar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Då det leid um nokre dagar, kom han til Kapernaum att, og det spurdest at han var heime.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Då samla der seg so mykje folk at det ikkje var rom åt fleire, ikkje ein gong framfor døri, og han tala Guds ord til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Best det var, kom fire mann berande med ein som var lam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'og då dei ikkje kunde koma fram til Jesus for folkestimen, tok dei burt taksteinarne der som han var og braut hol i taket og fira ned sengi som den lame låg i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Og då Jesus såg trui deira, sagde han til den lame: «Son, synderne dine er tilgjevne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'No var det nokre skriftlærde som sat der; dei tenkte med seg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '«Kvi talar den mannen so? Han spottar Gud! Kven kann tilgjeva synder utan ein - Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Jesus kjende straks i hugen sin at dei tenkte so, og han sagde: «Kvi hyser de slike tankar i hjarta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Kva er lettast å segja til den lame: «Synderne dine er tilgjevne!» eller å segja: «Statt upp, tak sengi di og gakk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Men so de skal vita at Menneskjesonen hev magt til å tilgjeva synder på jordi, so segjer eg deg» - sagde han til den lame -:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '«Statt upp, tak sengi di og gakk heim att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Då stod han upp, tok sengi si i same stund og gjekk ut for alle manns augo, so dei alle vart mest frå seg av undring, og lova Gud og sagde: «Slikt hev me aldri set fyrr!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'So gjekk han ut til sjøen att. Då kom alt folket til honom, og han lærde deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Som han no gjekk frammed der, fekk han sjå Levi Alfæusson - han sat på tollbudi - og Jesus sagde til honom: «Fylg meg!» Då reiste han seg og fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'So hende det at Jesus var til bords i huset hans, og mange tollmenner og syndarar sat saman med honom og læresveinarne hans; for dei var mange, og dei fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Og då dei skriftlærde millom farisæarane såg at han åt i lag med syndarar og tollmenner, sagde dei til læresveinarne hans: «Et han i lag med tollmenner og syndarar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Jesus høyrde det og sagde til deim: «Det er’kje dei friske som treng lækjar, men dei som hev vondt. Eg er ikkje komen for å kalla rettferdige, men syndarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Både læresveinarne åt Johannes og læresveinarne åt farisæarane heldt fasta. Og folk kom og spurde Jesus: «Korleis hev det seg at læresveinarne åt Johannes og åt farisæarane fastar, men dine læresveinar fastar ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, '«Kann brudlaupsfolket fasta med brudgomen er hjå deim?» svara Jesus; «so lenge dei hev brudgomen hjå seg, kann dei då ikkje fasta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Men skal kjem ei tid då brudgomen vert teken ifrå deim; då, når den dagen kjem, skal dei fasta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Ingen saumar ein lapp av ustampa ty på eit gamalt klædeplagg; elles riv boti burt noko av plagget - det nye tyet av det gamle - og rifti vert større.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Og ingen hev ny vin på gamle lerflaskor; elles sprengjer vinen flaskorne og vinen øydest, og flaskorne med: Nei - ny vin på nye lerflaskor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Ein gong bar det so til at han gjekk yver åkrarne på kviledagen, og læresveinarne tok til å riva av aks, med dei gjekk etter vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Då sagde farisæarane med honom: «Sjå kva dei gjer på kviledagen! det som ingen hev lov til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Han svara: «Hev de aldri lese kva David gjorde då han leid naud og svalt, han og dei som var med honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'korleis han gjekk inn i Guds hus den tid Abjatar var øvsteprest, og åt skodebrødi - dei som ingen utan prestarne hev lov til å eta - og gav fylgjet sitt med seg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'So sagde han til deim: «Kviledagen vart til for menneskja skuld, og ikkje menneskja for kviledagen skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Difor råder Menneskjesonen yver kviledagen og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Då Jesus ein annan gong gjekk inn i ei synagoga, var der ein mann som hadde ei nomi hand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'og dei gjætte på honom um han vilde lækja mannen på kviledagen, so dei kunde få noko å klaga honom for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Då sagde han til mannen med den nomne handi: «Reis deg upp og kom fram!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Og til dei andre sagde han: «Er det rett å gjera godt på kviledagen eller å gjera vondt - berga eit liv eller drepa?» Dei tagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Då såg han rundt ikring på deim, både harm og sorgfull for di dei var so harde og stride. So sagde han til mannen: «Rett fram handi!» Då rette han henne fram, og handi hans vart like god att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Men farisæarane gjekk ut og tok straks til å samråda seg med Herodes-mennerne korleis dei skulde få gjort ende på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'So for Jesus med læresveinarne sine burt til sjøen, og ein stor folkehop frå Galilæa fylgde med; og frå Judaland');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'og Jerusalem og Idumea og bygderne på hi sida Jordan og kring Tyrus og Sidon kom dei til honom i flokketal, då dei høyrde um alt det han gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Då sagde han til læresveinarne at det skulde liggja ein båt ferdig til honom for folkemengdi skuld, so dei ikkje skulde trengja honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'for han lækte mange, so alle som hadde eikor plåga, trengde seg innpå honom, og vilde få taka i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Og kvar gong dei ureine ånderne såg honom, kasta dei seg ned for føterne hans og ropa: «Du er Guds Son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Men han forbaud deim både tidt og strengt å gjera honom kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'So gjekk han upp i fjellet, og kalla til seg deim han sjølv vilde, og dei kom til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Og han valde ut tolv som skulde vera med honom, og som han vilde senda ut til å tala for folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'og vilde gjeva magt til å driva ut djevlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Det var Simon - honom kalla han Peter -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'og Jakob, son åt Sebedæus, og Johannes, bror hans Jakob - deim kalla han Boanerges, det er Toresveinarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'og Andreas og Filip og Bartolomæus og Mattæus og Tomas og Jakob, son åt Alfæus, og Taddæus og Simon Kananæus');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'og Judas Iskariot, han som sidan sveik honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Med det same han kom heim, samla folket seg i hop att, so dei kunde ikkje ein gong få seg mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Då hans eige folk fekk høyra det, for dei heimantil og vilde få tak i honom; «han må vera frå vitet!» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Men dei skriftlærde som var komne ned frå Jerusalem, sagde: «Be’elsebul hev fare i honom! og: «Det er djevlehovdingen sjølv som hjelper honom til å driva ut djevlar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Då kalla han deim til seg og tala til deim i likningar: «Korleis kann Satan driva ut Satan?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Kjem eit rike i strid med seg sjølv, so kann det riket ikkje standa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'og kjem eit hus i strid med seg sjølv, so stend det huset ikkje med lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Set no Satan seg upp mot seg sjølv og kjem i strid med seg sjølv, so kann han ikkje standa seg; då er det ute med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Men ingen kann ganga inn i huset til ei kjempa og rana eignaluterne hans, hev han ikkje fyrst lagt kjempa i band; då kann han plundra huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Det segjer eg dykk for sant: Alt skal tilgjevast menneskjeborni, både synder og spottord, kor mykje dei spottar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'men den som spottar den Heilage Ande, fær i all æva ikkje tilgjeving; han er saka i ei æveleg synd» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'det var for di dei sagde: «Han hev ei urein ånd i seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'So kom mor hans og brørne hans; dei vart standande utanfor, og sende bod til honom um han vilde koma ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Det sat ein stor flokk kringum honom, og dei sagde til honom: «Sjå, mor di og brørne dine stend utanfor og spør etter deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Kven er mor mi og brørne mine? svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'So såg han rundt på deim som sat i ein ring kringum honom, og sagde: «Sjå det er mor mi og brørne mine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Den som gjer det Gud vil, han er bror min og syster mi og mor mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'So tok han til å læra folket att ved sjøen; og det samla det seg ei uhorveleg mengd ikring honom, so han laut ganga ut i ein båt; den sat han i utpå vatnet, og heile folkehopen stod innpå land nedmed sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Då lærde han deim mangt og mykje i likningar, og med han soleis lærde deim, sagde han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Høyr her! Det var ein såmann som gjekk ut og vilde så.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Då bar det seg so til med han sådde, at noko av kornet fall frammed vegen, og fuglarne kom og åt det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Noko fall på steingrunn; der hadde det ikkje mykje jord, og det rann snøgt upp, av di der var so grunt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'men då soli steig, skein det av, for det hadde ikkje rot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Noko fall millom klunger, og klungeren voks upp og kjøvde det, og det gav ikkje grøda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Noko fall i god jord; det rann upp og voks og gav grøda og bar upp til tretti og seksti og hundrad foll.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Høyr etter, kvar som høyra kann! sagde han då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Då han vart åleine, kom dei tolv og dei andre som var med honom, og spurde honom um likningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Han svara: «De fær vita løyndomen i Gudsriket, men til dei andre, som er utanfor, kjem allting i likningar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'so dei skal sjå, men ikkje skilja, og høyra, men ikkje skyna; elles kunde dei venda um og få tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Men skynar de’kje denne likningi, sagde han, korleis kann de då greida alle dei andre likningarne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Såmannen, det er den som sår Guds ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Dei frammed vegen, det er dei som Guds ord vert sått i, men med same dei hev høyrt det, kjem Satan, og tek burt ordet som var sått i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Sameleis dei som var sådde på steingrunn; det er dei som straks dei fær høyra Guds ord, tek imot det med gleda;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'men dei hev ikkje rot i seg, og held ikkje ut langt bilet; kjem dei so i naud eller fåre for ordet skuld, leidest dei straks og fell ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Andre var sådde millom klunger; det er dei som hev høyrt Guds ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'men suterne for det timelege og den svikfulle rikdomen og fysna etter alle andre ting, trengjer seg inn og kjøver ordet, so det vert grødelaust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Men dei som var sådde i god jord, det er dei som høyrer Guds ord og tek imot det, og gjev grøda i tretti og seksti og hundrad foll.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Sidan sagde han til deim: «Når dei kjem inn med eit ljos, set dei det då under skjeppa eller sengi? set dei det’kje i staken?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'For ingen ting er dult utan det vert openberra, og ingen ting vart løynt utan det laut fram i ljoset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Høyr etter, kvar som høyra kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'So sagde han til deim: «Sjå dykk fyre kva de høyrer på! Det målet de mæler med, skal dei mæla åt dykk med, og endå skal de få noko attpå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'For den som hev, han skal få, men den som ikkje hev, skal missa endå det som han hev.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Sidan sagde han: «Med Guds rike er det so som når ein mann hev sått kornet i jordi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Han søv og ris upp, natt etter natt og dag etter dag, og frøet renn upp og veks - han veit ikkje korleis det gjeng til;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'av seg sjølv ber jordi si grøda, fyrst strå, so aks, so fulle korn i kvart aks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Men so snart som åkeren er skjær, tek han fram sigden; for hausten er komen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'So sagde han: «Kva skal me likna Guds rike i hop med? kva bilæte skal me teikna det med?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Det er liksom senapskornet; når det vert lagt i jordi, er det mindre enn alle frøkorn i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Men etter det er sått, renn det upp og vert større enn alle hagevokstrar og fær store greiner, so fuglarne i lufti kann byggja reir i skuggen av det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'I mange sovore likningar tala han Guds ord til deim, etter som dei var god til å skyna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Forutan likningar tala han ikkje til folket; men når han var åleine med læresveinarne sine, lagde han det ut alt saman for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Då det leid til kvelds same dagen, sagde han til deim: «Lat oss fara yver til hi sida!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'So skildest dei med folket og tok honom med i båten, som han var. Og andre båtar fylgde og med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Då vart det so hardt eit ver, at bårorne slo inn i båten, og han var nær på å fyllast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Men Jesus låg og sov på høgjendet i bakskuten. Dei vekte honom og sagde: «Meister, er du like sæl um me gjeng under?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'So stod han upp og truga vinden og sagde til sjøen: «Teg, og ver still!» Då logna vinden, og det vart blikende stilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Og han sagde til deim: «Kvi er de rædde? Hev de endå ingi tru?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Men dei var fulle av otte og sagde seg imillom: «Kva er då dette for ein, som både vinden og sjøen lyder?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'So kom dei yver til hi sida av sjøen, til Gerasenarbygdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'og med det same han steig utor båten, kom ein mann med ei urein ånd imot honom frå gravholorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Mannen hadde tilhald i graverne, og ingen kunde lenger få bunde honom, ikkje ein gong med lekkjor;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'for han hadde ofte vore bunden med fotjarn og lekkjor, men slite lekkjorne og brote sund fotjarni, og ingen var god til å døyva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Allstødt både natt og dag var han i graverne og på fjelli og hua og slo seg sjølv med steinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Då han no såg Jesus langt burte, kom han springande og kasta seg ned for føterne hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'og ropa høgt: «Kva vil du meg, Jesus, son åt den høgste Gud? For Guds skuld: pin meg ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'For Jesus sagde til honom: «Far ut or mannen, du ureine ånd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, '«Kva er namnet ditt?» spurde Jesus. «Legion er namnet mitt,» svara han; «for me er mange.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Og han naudbad Jesus, at han ikkje vilde driva deim ut or bygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'No var det ein stor svineflokk som gjekk på beite der innmed fjellet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'so bad dei honom: «Send oss burt i svineflokken, og lat oss få fara inn i deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Det gav han deim lov til. So for dei ureine åndene ut og for i svini. Og heile flokken, um lag tvo tusund svin, sette utyver stupet ned i sjøen og druknast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Dei som gjætte svini, rømde og sagde frå um det i byen og på gardarne, og folk tok ut og vilde sjå kva det var som hadde hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Då dei so kom til Jesus, fekk dei sjå at den forgjorde sat der klædd, og med sitt fulle vit, han som hadde havt djevleheren i seg. Og dei vart ottefulle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Og då dei som hadde set det, fortalde korleis det hadde gjenge med den forgjorde, og um svini,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'tok dei til å beda Jesus at han vilde fara burt frå grensorne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Då Jesus gjekk i båten, bad den forgjorde um han måtte vera med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Men Jesus let honom ikkje få lov, og sagde: «Gakk heim til folket ditt, og seg med deim kor mykje Herren hev gjort for deg, og kor god han hev vore med deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'So gjekk mannen og tok til å gjera kunnigt kring i Dekapolis kor mykje Jesus hadde gjort for honom. Og alle undra seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Då Jesus hadde fare yver til hi sida att med båten, og endå var nedmed sjøen, samla det seg ein stor folkehop kringum honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Då kom ein av synagoge-forstandarane, som heitte Jairus, og med det same han såg Jesus, kasta han seg ned for føterne hans');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'og bad honom mykje og sagde: «Vesle dotter mi ligg på det siste - um du vilde koma og leggja henderne på henne, so ho kann bergast og liva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Jesus gjekk med honom, og ein stor folkehop fylgde etter, og trengde seg um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Millom deim var ei kvinna som hadde havt blodflod i tolv år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Ho hadde søkt mange lækjarar, og prøvt mange råder, og kosta ut alt ho åtte; men det hadde ikkje muna; ho var heller vorti verre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Ho hadde høyrt ordet um Jesus, og no kom ho midt i folkehopen og tok attantil i kjolen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, '«Kann eg få taka um so berre i klædi hans, vert eg god att,» tenkte ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Og med ein gong stana blodflodi, og ho kjende det i likamen at ho var lækt for sjukdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Jesus kjende straks på seg at det for ei kraft ut ifrå honom; han snudde seg um i hopen og spurde: «Kven var det som tok i klædi mine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, '«Du ser folket trengjer deg på alle kantar,» svara læresveinarne, «og so spør du kven det var som tok i deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Då såg han seg ikring etter den som hadde gjort det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Og kvinna, som var so rædd at ho skalv, av di ho visste kva som hadde hendt henne, ho kom og kasta seg ned for føterne hans, og sagde honom alt som det var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Då sagde han til henne: «Trui di hev hjelpt deg, dotter mi. Gakk heim og hav det godt, og ver fri sjukdomen din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Fyrr han hadde tala ut, kom det folk frå huset åt synagoge-forstandaren og sagde: «Dotter di hev slokna. Umaka ikkje meisteren lenger!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Jesus høyrde kva dei tala um, og sagde til synagoge-forstandaren: «Ottast ikkje! Berre tru!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Han let ingen fylgja seg utan Peter og Jakob og Johannes, bror åt Jakob.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Og då dei kom heim til synagoge-forstandaren, og han såg for eit ståk der var, og høyrde folk gret og våla,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'gjekk han inn og sagde: «Kva ståkar og græt de for? Barnet hev ikkje slokna; det søv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Då log dei åt honom. Men han dreiv deim ut alle saman, og sjølv tok han med seg far og mor åt barnet, og fylgjesveinarne sine, og gjekk inn der barnet låg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Og han tok barnet i handi og sagde: «Talita kumi!» det er det same som: «Vesle gjenta, eg segjer deg: Ris upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Og straks reis veslegjenta upp og gjekk ikring; for ho var tolv år. Då vart dei straks reint som dei var frå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Men han forbaud deim strengt å lata nokon få vita det, og sagde dei skulde gjeva henne mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'So for han burt derifrå og kom til fødesheimen sin, og læresveinarne var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Då kviledagen kom, tok han til å læra folket i synagoga, og dei mange som høyrde på honom, var reint upp i under og sagde: «Kvar hev han dette frå? Kva er det for visdom han hev fenge? Og slike underverk som han gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Er’kje dette timbremannen, son åt Maria og bror åt Jakob og Joses og Judas og Simon? Og bur’kje systerne hans her i grendi?» Og dei stygdest ved honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Men Jesus sagde til deim: «Ein profet er ikkje vanvyrd utan i si eige grend og hjå sitt eige folk og i sin eigen heim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Han kunde ikkje gjera noko under der, so nær som at han lagde henderne på nokre få helselause og lækte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Og han undra seg yver vantrui deira. Sidan gjekk han frå grend til grend og lærde folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Og han kalla dei tolv til seg, og tok til å senda deim ut, tvo og tvo, og gav dei magt yver dei ureine ånderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Han sagde til deim at dei skulde’kje hava anna med seg på ferdi enn ein stav, ikkje brød, ikkje skreppa, ikkje kopar i beltet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'sandalar kunde dei ganga med, men dei måtte’kje hava på seg meir enn ei trøya.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, '«Kvar gong de kjem inn i eit hus,» sagde han, «so ver der til de fer burt frå den bygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Men er det nokon stad dei ikkje vil taka imot dykk og ikkje vil høyra på dykk, so gakk dykkar veg og rist moldi av føterne dykkar! det skal vera eit vitnemål mot deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'So tok dei i vegen og tala for folket og mana deim til å venda um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Og dei dreiv ut mange djevlar, og salva mange helselause med olje og lækte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Kong Herodes fekk og høyra um dette; for Jesus hadde vorte namnspurd, og folk sagde: «Det er Johannes, døyparen! Han hev stade upp frå dei daude; difor ter det seg so underfulle krafter i honom;»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'andre sagde: «Det er Elia;» endå andre: «Det er ein profet, som ein av dei gamle profetarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Men då Herodes høyrde det, sagde han: «Det er Johannes, han som eg let deim hogga hovudet av; no hev han stade upp att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'For Herodes hadde sjølv sendt ut folk til å gripa Johannes og lagt honom i band og lekkjor, og det valda Herodias, kona åt Filip, bror hans. For henne hadde Herodes gift seg med;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'men Johannes sagde til honom: «Du må ikkje hava brorkona di!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Difor bar Herodias hat til honom, og vilde at han skulde drepast, men fekk det’kje fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'For Herodes hadde age for Johannes, av di han visste han var ein rettferdig og heilag mann, og han heldt handi yver honom; når han høyrde honom, kom han i tvil um mangt og mykje, og han høyrde honom gjerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Men so kom det ei lagleg tid: det var då Herodes på årmålsdagen sin gjorde eit gjestebod for stormennerne sine og herhovdingarne og dei gjævaste i Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Då kom dotter åt Herodias inn og dansa. Herodes og gjesterne hans tykte gildt i dansen hennar, og kongen sagde til henne: «Bed meg um kva du vil, so skal eg gjeva deg det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Og han svor at ho skulde få det ho bad um - um det so var halve riket hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'So gjekk ho ut og spurde mor si: «Kva skal eg beda um?» «Hovudet åt Johannes døyparen!» svara mori.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Då skunda ho seg straks inn til kongen og bar fram ynskjet sitt. «Eg vil at du no med det same skal gjeva meg hovudet åt Johannes døyparen på eit fat,» sagde ho.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Kongen vart reint ille ved; men for di han hadde svore, og for gjesterne skuld vilde han ikkje svara nei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Han sende straks ein av livvakti av stad og bad honom henta hovudet åt Johannes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Mannen gjekk til fengslet og hogg hovudet av Johannes, kom med det på eit fat og gav det til gjenta, og ho gav det til mor si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Då læresveinarne åt Johannes fekk høyra det, kom dei og tok liket hans og lagde det i ei grav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Apostlarne samla seg atter hjå Jesus, og sagde frå um alt dei hadde gjort, og alt dei hadde lært folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Då sagde han til deim: «Kom no de åleine med meg til ein øydestad og kvil dykk litt!» For det var mange som kom og gjekk, og dei fekk ikkje ein gong matro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'So for dei åleine i båten til ein øydestad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Men folk såg deim fara burt, og mange kjende deim att, og sprang landveges dit frå alle byarne og kom fyre deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'og då Jesus steig i land, fekk han sjå ein stor folkehop. Han tykte hjarteleg synd i deim; for dei var som ein saueflokk utan hyrding; og han tok til å læra deim mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Då dagen tok til å lida, kom læresveinarne til honom og sagde: «Det er audt her, og dagen lid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Send deim frå deg, so dei kann ganga burt i gardarne og grenderne her kringum og kjøpa seg mat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, '«Gjev de dei mat!» svara han. «Skal me ganga av og kjøpa brød for eit halvt hundrad dalar, og gjeva deim?» sagde dei då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, '«Kor mykje brød hev de?» spurde han; «gakk og sjå etter!» Då dei so hadde fenge greida på det, sagde dei: «Fem leivar og tvo fiskar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Då sagde han at dei skulde lata alle setja seg i det grøne graset, bordlag og bordlag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'So let dei seg ned i flokkar, sume på hundrad og sume på femti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Og han tok dei fem brødleivarne og dei tvo fiskarne og såg upp imot himmelen og velsigna deim; so braut han brødet og gav det til læresveinarne, so dei skulde setja det fram for deim, og dei tvo fiskarne skifte han og ut åt deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Då alle hadde ete og var mette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'samla dei upp tolv korger fulle med brødstykke og noko fisk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Og det var fem tusund mann som hadde fenge mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Med same dette var gjort, nøydde han læresveinarne til å ganga i båten og fara fyre yver sjøen, til Betsaida, medan han sjølv bad farvel med folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Og då han hadde skilst med deim, gjekk han upp i fjellet og vilde beda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Då det leid på kvelden, var båten midt utpå sjøen, og sjølv var han åleine på land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Då såg han at det gjekk tungt for deim med roren; for dei hadde vinden imot seg. Og ikring den fjorde nattevakti kom han gangande burtimot deim på sjøen, og vilde ganga framum deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Då dei såg at han gjekk på sjøen, tenkte dei at det var eit skrymt, og dei sette i et skrik;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'for dei såg honom alle og vart fælne. Men i det same tala han til deim og sagde: «Ver hugheile! Det er eg! Ver’kje rædde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'So steig han upp i båten til deim, og vinden stilna. Men dei var so forstøkte at dei var reint ifrå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'For dei hadde ikkje vitrast av det som var hendt med brødet; so seige og tungnæme var dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Då dei hadde fare yver til hitt landet, kom dei til Gennesaret og lagde til der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Med det same han steig utor båten, kjende folk honom att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'og dei sprang rundt i heile grannelaget og tok til å bera dei sjuke kring i sengjerne sine dit som dei høyrde han var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Og kvar han kom, til grender eller byar eller gardar, lagde dei sine sjuke på tunet, og bad um dei måtte få taka um so berre i falden på kjolen hans, og alle som kom nær honom, vart gode att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Farisæarane og nokre skriftlærde som var komne frå Jerusalem, samla seg ein gong kring Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'For dei hadde set at nokre av læresveinarne hans åt maten sin med ureine - dei meinte: utvegne hender;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'og farisæarane og alle jødar tvær alltid henderne vel fyrr dei et; det er ein skikk dei hev frå dei gamle, og den held dei seg etter;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'og når dei kjem frå torget, et dei ikkje fyrr dei hev skvett vatn yver seg; og mykje anna er det som hev vorte sed og skikk hjå deim, som å skylja koppar og krus og koparkjelar og benkjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'So kom då farisæarane og dei skriftlærde og spurde honom: «Kvi fylgjer ikkje læresveinarne dine dei skikkarne me hev frå dei gamle, men et maten sin med ureine hender?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Han svara: «Jesaja spådde sant um dykk, de hyklarar, som det stend skrive: «Med lipporn’ lovar dei meg, denne lyden, Men hugen deira han er langt ifrå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'D’er liten mun i at dei meg vil æra, Når det dei lærer folk er mannebod.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'De ansar ikkje Guds bod, men held dykk etter menneskjelærdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Å jau, det er rett fint åtfare,» sagde han, «at de gjer Guds bod um inkje, so de kann fylgja skikkarne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Moses hev sagt: «Du skal æra far din og mor di!» og: «Den som bannar far sin eller mor si, skal døy!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Men de segjer: «Når ein mann talar so til far sin eller mor si: «Det som eg kunde ha hjelpt deg med, skal vera ein korban» - det er: ei tempelgåva -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'so let de honom ikkje lenger få lov til å gjera noko for foreldri sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Soleis gjer de Guds ord um inkje med skikkarne dykkar, som de hev lært folk. Og slikt gjer de mykje av.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'So kalla han folket til seg att og sagde med deim: «Høyr på meg alle, og tenk på det eg segjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Det finst ingen ting utanfor menneskjet som kann gjera honom urein um det kjem inn i honom; men det som kjem ut or menneskjet, det er det som gjer honom urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Høyr etter, kvar som høyra kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Då han var komen inn og hadde skilst ifrå folket, spurde læresveinarne honom um dette ordtøket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, '«Er de og so uvituge?» svara han. «Skynar de’kje at det som kjem inn i menneskjet utantil, kann aldri gjera honom urein?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'For det kjem ikkje inn i hjarta hans, men i buken, og fer ut der det skal; soleis vert all føda rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Men det som gjeng ut or menneskjet,» sagde han, «det gjer honom urein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'For innantil, or menneskjehjarta, kjem dei vonde tankarne: lauslivnad, tjuvskap, manndråp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'egteskapsbrot, girugskap, vondskap, svik, ukjurskap, ovund, gudsspotting, ovmod, vitløysa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Alt dette vonde kjem innantil, og gjer menneskjet ureint.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'So tok han ut derifrå, og for burt til Tyrus-bygderne. Der gjekk han inn ein stad, og vilde ikkje nokon skulde vita det; men det kunde ikkje dyljast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Ei kona hadde ei liti dotter som det var ei urein ånd i; då ho fekk høyra um honom, kom ho straks og kasta seg ned for føterne hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'det var ei heidningkona, av syro-fønikisk ætt. Og ho bad at han vilde driva den vonde åndi ut or dotter hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, '«Lat fyrst borni få eta seg mette!» svara han; «det er’kje vænt å taka brødet frå borni og kasta det for hund-ungarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, '«Jau, Herre,» svara ho; «små-hundarne et då og under bordet av smularne etter borni.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Då sagde Jesus: «For det ordet skuld kann du ganga heim att; den vonde åndi hev fare ut or dotter di.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Då ho so kom heim, fann ho barnet liggjande på sengi, og åndi hadde fare ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Då han tok ut att frå Tyrus-bygderne, for han um Sidon til Galilæasjøen, midt igjenom Dekapolis-bygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Då kom dei til honom med ein som var dauv og godtsom mållaus, og bad han vilde leggja henderne på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Jesus tok honom til sides, burt ifrå folkehopen, stakk fingrarne sine i øyro hans, og vætte tunga hans med råke av munnen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'So såg han upp imot himmelen og sukka, og sagde til honom: «Effata!» - det er: «Lat deg upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Då vart øyro hans upplatne, bandet losna av tunga, og han tala klårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Jesus forbaud deim å segja det med nokon. Men di meir han forbaud det, di meir bar dei det utyver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Dei var reint tekne og sagde: «Han hev gjort alt vel! dei dauve gjev han høyrsel, og dei mållause mæle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Ein gong ved det leitet var det atter mykje folk samla, og dei hadde ingen ting å eta. Då kalla Jesus læresveinarne til seg og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '«Eg ynkast yver folket! No hev dei alt vore hjå meg i tri dagar, og hev ingen ting å eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Let eg deim fara fastande heim att, so kjem dei til å ormegtast på vegen; og sume av dei hev kome lange vegar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, '«Kvar kann ein få brød frå til å metta alle desse, her i øydemarki?» svara læresveinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, '«Kor mykje brød hev de?» spurde Jesus. «Sju leivar,» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Då let han folket setja seg ned på marki, og han tok dei sju leivarne og takka og braut dei sund og gav deim til læresveinarne, so dei skulde setja deim fram; og dei sette deim fram for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Og dei hadde nokre få små fiskar; deim velsigna han og, og sagde at dei skulde setja deim fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Då dei hadde ete og var mette, samla dei upp dei stykki som låg att; det vart sju korger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Og der var um lag fire tusund mann. So bad han farvel med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Straks etter gjekk han i båten med læresveinarne sine og for til Dalmanuta-bygdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Dit kom farisæarane og, og dei tok til å ordkastast med honom, og kravde eit teikn frå himmelen av honom; for dei vilde freista honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Då sukka han av hjartans grunn og sagde: «Kvi krev denne ætti eit teikn? Det segjer eg dykk for sant: Aldri skal denne ætti få noko teikn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Dermed gjekk han ifrå deim og steig ut i båten att, og for yver sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Dei hadde gløymt å taka brød med seg; ein leiv var alt dei hadde med seg i båten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'So vara han deim åt og sagde: «Sjå dykk fyre, og agta dykk for surdeigen åt farisæarane og surdeigen åt Herodes!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Då tala dei med kvarandre um at dei hadde’kje brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Jesus gådde det og sagde til deim: «Kvi talar de um at de ikkje hev brød? Ser og skynar de endå ingen ting? Er de so tungnæme?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'De hev augo, og ser ikkje! De hev øyro og høyrer ikkje! Kjem de då ikkje i hug');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'den gongen eg bytte sund dei fem brødleivarne åt dei fem tusund - kor mange korger fulle av brødstykke sanka de i hop?» «Tolv,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '«Og då eg bytte ut dei sju leivarne åt dei fire tusund, kor mange fulle brødkorger samla de då upp?» - «Sju,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Skynar de endå ingen ting? sagde han då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'So kom dei til Betsaida. Der leidde dei ein blind mann fram til honom, og bad at han vilde leggja henderne på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Då tok han den blinde i handi, og leidde honom ut or grendi. So vætte han augo hans med råke av munnen sin, og lagde henderne på honom og spurde: «Ser du noko?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Mannen såg upp og sagde: «Eg augnar folk som gjeng ikring; dei ser ut for meg som trestuvar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'So lagde Jesus endå ein gong henderne på augo hans. Då braut syni hans fram; han vart god att og kunde skilja allting klårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Jesus sende honom heim att og sagde: «Gakk ikkje inn i grendi, og seg det ikkje til nokon i grendi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Sidan for Jesus og læresveinarne hans burt til grenderne kring Cæsarea Filippi. Og på vegen spurde han deim: «Kven segjer folk at eg er?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, '«Johannes døyparen,» svara dei; og sume segjer: «Elia», andre: «Ein av profetarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, '«Kven segjer då de at eg er?» spurde han. Då tok Peter til ords og sagde: «Du er Messias!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Men det forbaud han deim strengt å segja med nokon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'So tok han til å læra deim at Menneskjesonen laut lida mykje, og at styresmennerne og dei øvsteprestarne og dei skriftlærde skulde skjota honom ifrå seg, og at han laut lata livet, men tri dagar etter skulde han standa upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Og det sagde han med reine ord. Då tok Peter honom til sides og tok til å telja for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Men han snudde seg, og då han såg læresveinarne sine, tala han strengt til Peter og sagde: «Burt frå augo mine, Satan! Du hev ingen tanke for det som er Guds vilje, men berre for det som er menneskjevilje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'So kalla han folket til seg saman med læresveinarne sine og sagde: «Vil nokon vera i lag med meg, so lyt han gløyma seg sjølv, og taka krossen sin upp og fylgja etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'For den som vil berga livet sitt, skal missa det; men den som misser livet for mi og evangeliet skuld, han skal berga det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Kva gagnar det eit menneskje å vinna heile verdi, men tapa sjæli si?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'For kva kann menneskjet gjeva i byte for sjæli si?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'For den som skjemmest ved meg og ordi mine i denne utrue og synduge ætti, honom skal og Menneskjesonen skjemmast ved når han kjem i herlegdomen åt Far sin med dei heilage englarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Det segjer eg dykk for sant,» sagde han: «Sume av deim som her stend, skal ikkje smaka dauden fyrr dei ser at Guds rike hev kome med velde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Seks dagar etter tok Jesus Peter og Jakob og Johannes med seg upp på eit høgt fjell; der var dei åleine for seg sjølve. Då vart han forklåra for augo deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'og klædi hans vart skinande kvite, so ingen bleikjar i verdi kunde ha gjort deim so kvite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Og Elia synte seg for deim saman med Moses; dei stod og tala med Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Då tok Peter til ords og sagde til Jesus: «Meister, det er godt me er her! Lat oss gjera tri hytter, ei åt deg, og ei åt Moses, og ei åt Elia!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Han visste ikkje kva han skulde segja; for dei var fulle av otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'So kom det ei sky og skygde yver deim, og or skyi kom det ei røyst: «Dette er Son min, han som eg elskar. Høyr på honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Men best dei skoda ikring seg, såg dei ingen meir utan Jesus - han var åleine hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Då dei gjekk ned av fjellet, sagde han med deim at dei ikkje måtte tala til nokon um det dei hadde set, fyrr Menneskjesonen var staden upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Det ordet merka dei seg, men undrast seg imillom kva det skulde tyda: «standa upp frå dei daude».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'So spurde dei honom: «Segjer ikkje dei skriftlærde at fyrst lyt Elia koma?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Ja, fyrst kjem Elia og set alt i rett lag att, svara han; «og kva er det som stend skrive um Menneskjesonen? At han skal lida mykje og agtast for inkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Men eg segjer dykk at Elia og er komen, og dei gjorde med honom slikt dei vilde, som skrive er um honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Då dei kom til læresveinarne, såg dei ein stor folkehop kringum deim, og nokre skriftlærde som var i ordkast med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Og med same folkemengdi fekk sjå honom, vart dei reint forstøkte, og sprang imot honom og helsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, '«Kva er det de dregst med deim um?» spurde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Då svara ein av folket: «Meister, eg er komen til deg med son min. Han hev ei mållaus ånd i seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'når ho tek honom, riv ho og slit i honom, so fraudi stend utor munnen, og han skjer tenner og visnar burt. Eg bad læresveinarne dine at dei vilde driva henne ut, men dei var’kje god til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Då tok Jesus til ords og sagde: «Å, du vantrune ætt! Kor lenge skal eg vera hjå dykk? Kor lenge skal eg tola dykk? Kom hit til meg med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'So leidde dei guten burt til honom, og med same han såg Jesus, reiv åndi i honom, so han stupte i marki og velte seg og togg fraud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, '«Kor lenge hev han havt det so?» spurde Jesus. «Frå han var eit lite barn,» svara faren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, '«og ofte hev åndi kasta honom både i elden og i vatnet, og vilja gjort ende på honom. Men er det mogelegt for deg, so gjer sælebot på oss og hjelp oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, '«Um det er mogelegt for meg -?» svara Jesus. «Alt er mogelegt for den som trur!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Og straks ropa far åt barnet: «Eg trur! Hjelp mi vantru!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Då Jesus såg at folket strøymde til, truga han den ureine åndi og sagde: «Du mållause og dauve ånd, far utor honom, segjer eg, og far aldri i honom meir!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Då hua ho og reiv hardt i guten og for ut. Og han vart som eit lik, so dei fleste sagde: «Han hev slokna!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Men Jesus tok honom i handi og vekte honom; då reiste han seg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Då Jesus var komen i hus, og læresveinarne var åleine med honom, spurde dei: «Kvi kunde ikkje me driva ut åndi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Han svara: «Dette slaget kann ikkje drivast ut på anna vis enn med bøn og fasta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'So tok dei ut derifrå og for gjenom Galilæa. Men han vilde ikkje nokon skulde vita det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'for han lærde sveinarne sine og sagde: Menneskjesonen skal gjevast yver i menneskjehender, og dei skal drepa honom; og tri dagar etter han er drepen, skal han standa upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Men dei skyna’kje det ordet, og torde ikkje spyrja honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'So kom dei til Kapernaum, og då han var heime att, spurde han deim: «Kva var det de tala um på vegen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Dei tagde; for på vegen hadde dei tala med einannan um kven som var størst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Då sette han seg og kalla til seg dei tolv, og sagde med deim: «Vil nokon vera den fyrste, so skal han vera den siste av alle og tenar for alle!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'So tok han eit lite barn og sette midt imillom deim og tok det i fang og sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '«Den som tek imot eit sovore barn for mitt namn skuld, han tek imot meg; og den som tek imot meg, tek ikkje imot meg, men den som sende meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johannes sagde til honom: «Meister, me såg at ein som ikkje er i fylgje med oss, dreiv ut vonde ånder i ditt namn, og me forbaud honom det, for di han ikkje var i fylgje med oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, '«De skal ikkje forbjoda honom det,» sagde Jesus, «for den som gjer eit under i mitt namn, kann ikkje so snart tala vondt um meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'den som ikkje er imot oss, held med oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'For den som gjev dykk ei skål med vatn for di de høyrer Kristus til, han skal ikkje missa si løn, det segjer eg dykk for visst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Men den som legg ei snara for ein av desse små som trur, for honom var det mykje betre um det var lagt ein kvernstein um halsen hans, og han var kasta i havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Dersom handi di freistar deg, so hogg henne av! Det er betre du gjeng vanfør inn til livet, enn at du hev båe henderne dine og kjem i helvite, i den usløkkjande elden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'der ormen deira ikkje døyr, og elden ikkje sloknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Og dersom foten din freistar deg, so hogg honom av! Det er betre du gjeng einføtt inn til livet, enn at du hev båe føterne dine og vert kasta i helvite,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'der ormen deira ikkje døyr, og elden ikkje sloknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Og dersom auga ditt freistar deg, so riv det ut! Det er betre du gjeng einøygd inn i Guds rike, enn at du hev tvo augo og vert kasta i helvite,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'der ormen deira ikkje døyr og elden ikkje sloknar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'For kvart menneskje skal saltast med eld, liksom kvart offer vert salta med salt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Salt er ein godt; men vert saltet saltlaust, kva vil de då salta det med? Hav salt i dykk sjølve, og haldt fred med kvarandre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'So tok han ut derifrå, og for til Juda-bygderne og bygderne på hi sida Jordan. Og folket samla seg att ikring honom, og han lærde deim, som han var van med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Då kom det nokre farisæarar og spurde honom: «Tru ein mann hev lov til å skilja seg frå kona si?» Det var for å freista honom dei spurde um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, '«Kva hev Moses sagt dykk fyre?» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, '«Moses gav lov til å skriva eit skilsmålsbrev og senda henne frå seg,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Då sagde han til deim: «Av di de er so hardhjarta, skreiv Moses den lovi for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Men alt ifrå fyrste skapingstidi gjorde Gud deim til mann og kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Difor skal mannen skiljast med far sin og mor si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'og dei tvo skal vera eitt kjøt. So er dei då ikkje lenger tvo, men eitt kjøt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'og det som Gud hev bunde i hop, det skal ikkje menneskja skilja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Heime spurde læresveinarne honom att um det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Då sagde han til deim: «Den som skil seg frå kona si og gifter seg med ei onnor, bryt egteskapet med henne, og gjer hor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Og dersom ho skil seg frå mannen sin, og gifter seg med ein annan, gjer ho hor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Og dei bar småborn til honom, so han skulde røra ved deim, men læresveinarne truga deim som bar deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Då Jesus såg det, vart han harm og sagde til deim: «Lat småborni koma til meg; hindra deim ikkje! for Guds rike høyrer slike til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Det segjer eg dykk for sant: Den som ikkje tek imot Guds rike som eit lite barn, han skal på ingen måte koma inn i det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'So tok han deim i fanget og lagde henderne på deim og velsigna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Då han kom ut på vegen, sprang det ein fram og fall på kne for honom og spurde: «Gode meister, kva skal eg gjera so eg kann vinna eit æveleg liv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, '«Kvi kallar du meg god?» sagde Jesus. «Ingen er god utan ein - Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Bodi kjenner du: «Du skal ikkje drepa! Du skal ikkje gjera hor! Du skal ikkje stela! Du skal ikkje vitna rangt! Du skal ikkje slå under deg annan manns eigedom! Du skal æra far din og mor di!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, '«Meister,» svara han, «alt det hev eg halde frå eg var ung.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Då såg Jesus på honom og fekk honom kjær. So sagde han: «Eitt vantar deg: Gakk burt og sel alt det du hev, og gjev det til dei fatige, so fær du ein skatt i himmelen; og kom so og fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Ved det ordet for det ein skugge yver andlitet hans, og han gjekk sturen burt; for han åtte mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Då såg Jesus kringum seg og sagde til læresveinarne sine: «Kor vandt det er for den som eig mykje å koma inn i Guds rike!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Læresveinarne stokk yver ordi hans. Men Jesus tok til ords att og sagde: «Kor vandt det er, borni mine, å koma inn i Guds rike for deim som set si lit til rikdom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Det er lettare for ein kamel å ganga gjenom eit nålauga enn for ein rik å koma inn i Guds rike!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Då vart dei endå meir forfærde. «Kven kann då verta frelst?» ropa dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jesus såg på deim og sagde: «For menneskje er det umogelegt, men ikkje for Gud; for alt er mogelegt for Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Då tok Peter til ords og sagde til honom: «Enn me som hev skilt oss med alt og fylgt deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Og Jesus svara: «Det segjer eg dykk for sant: Det er ingen hev skilt seg med heim eller brør eller syster eller mor eller far eller born eller gardar for mi og evangeliet skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'utan han skal få det att hundrad gonger - no i denne tidi heim og brør og syster og møder og born og gardar, alt um han jamt er i fåre, og i den verdi som kjem eit æveleg liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Men mange som no er med dei fyrste, skal då vera millom dei siste, og dei siste millom dei fyrste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'No var dei på vegen upp til Jerusalem. Jesus gjekk fyre deim, og dei undrast, og dei som fylgde, var fulle av otte. Då samla han atter dei tolv ikring seg, og tok til å tala til deim um det som skulde henda honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'No fer me upp til Jerusalem, og Menneskjesonen skal gjevast i henderne på dei øvste prestarne og dei skriftlærde, og dei skal døma honom frå livet og gjeva honom yver til heidningarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'og dei skal spotta honom og sputta på honom og hudfletta honom og drepa honom; men tri dagar etter skal han standa upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Jakob og Johannes, sønerne åt Sebedæus, kom til honom og sagde: «Meister, det er noko me vil beda deg um! Vil du gjera det for oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, '«Kva vil de eg skal gjera for dykk?» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, '«Lova oss at me skal få sitja innmed deg i din herlegdom, ein på di høgre og ein på di vinstre sida!» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, '«De veit ikkje kva de bed um,» sagde Jesus. Kann de drikka den skåli som eg drikk, eller taka den dåpen som eg tek?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, '«Ja, det kann me,» sagde dei. Då sagde Jesus til deim: «Den skåli eg drikk, skal de drikka, den dåpen eg fær, skal de få;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'men sætet ved mi høgre eller vinstre sida er det ikkje mi sak å gjeva burt; det lyt dei få som det er etla åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Då dei ti høyrde det, tok dei til å harmast på Jakob og Johannes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Då kalla Jesus deim til seg og sagde: «De veit at dei som gjeld for fyrstar, råder yver folki sine, og stormennerne deira heldt deim i age.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Men so er det ikkje hjå dykk; den som vil vera stor millom dykk, lyt tena dei andre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'og den som vil vera den fyrste av dykk, lyt vera træl for dykk alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'For Menneskjesonen er’kje heller komen for å tenast, men for å tena og gjeva sitt liv til løysepening for mange.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'So kom dei til Jeriko. Då Jesus tok ut att frå Jeriko med læresveinarne sine og ein svær folkehop, sat son åt Timæus, Bartimæus, ein blind tiggar, attmed vegen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'og då han høyrde det var Jesus frå Nasaret, tok han på å ropa: «Jesus, Davids son, gjer sælebot på meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Mange truga honom, og sagde han skulde tegja; men han ropa berre endå meir: «Davids son, gjer sælebot på meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Jesus stana og sagde: «Ropa honom hit!» Då ropa dei på den blinde og sagde til honom: «Ver hugheil! Reis deg upp! Han ropar på deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'So kasta han av seg kjolen og spratt upp og kom burt til Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Og Jesus sagde til honom: «Kva vil du eg skal gjera for deg?» «Meister, lat meg få att syni!» svara den blinde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Då sagde Jesus til honom: «Gakk heim att! Trui di hev hjelpt deg.» Og med ein gong fekk han att syni, og fylgde Jesus på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Då dei kom burtimot Jerusalem, til Betfage og Betania ved Oljeberget, sende Jesus tvo av læresveinarne sine i veg og sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, '«Gakk burt i den grendi som ligg beint framfor dykk! Med det same de kjem der, finn de ein fole som stend bunden, og som det endå aldri hev sete noko menneskje på; den skal de løysa og koma hit med!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Og dersom nokon segjer med dykk: «Kvi gjer de det?» so skal de svara: «Herren treng um honom, og sender honom straks attende.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'So gjekk dei og fann folen; han stod bunden uti gata attmed ei dør, og dei løyste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Nokre folk som stod der, sagde til deim: «Kva gjer de? løyser de folen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Dei svara so som Jesus hadde sagt; då let folket deim ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'So kom dei til Jesus med folen og lagde kjolarne sine på honom, og Jesus sette seg uppå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Og mange breidde klædi sine på vegen, andre strådde lauv, som dei hadde henta frå marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Og dei som gjekk fyre, og dei som fylgde etter, ropa: «Hosianna! Velsigna vere han som kjem i Herrens namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Velsigna vere vår fader Davids rike som kjem! Hosianna i det høgste!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'So kom han til Jerusalem og gjekk inn i templet. Der såg han seg ikring allstad; men då det tok til å kvelda, gjekk han ut til Betania med dei tolv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Dagen etter, då dei gjekk frå Betania, kjende han seg svolten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Langt burte såg han eit fiketre med lauv på; han gjekk burtåt, og vilde sjå um han kunde finna noko på det; men då han kom dit, fann han’kje anna enn lauv; for det var ikkje tidi for fikor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Då tala han til treet og sagde: «Gjev aldri i verdi nokon må koma til å eta frukt av deg meir!» Og det høyrde læresveinarne på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Då dei kom til Jerusalem, gjekk han inn i templet og tok til å driva ut deim som handla i heilagdomen; han velte bordi åt pengevekslarane og krakkarne åt deim som selde duvor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'og let ingen få lov til å bera nokon reidskap gjenom templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Og han lærde deim og sagde: «Stend det’kje skrive: «Mitt hus skal kallast eit bønehus for alle folk?» Men de hev gjort det til eit røvarbol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Dei øvste prestarne og dei skriftlærde fekk høyra det, og lurde på korleis dei skulde få teke livet av honom; dei var rædde honom; for alle folk var hugtekne av læra hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Men når det leid til kvelds, gjekk han alltid ut or byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Då dei tidleg um morgonen gjekk framum fiketreet, såg dei at det hadde turka radt ifrå roti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Peter kom i hug dei ordi Jesus hadde lyst, og sagde: «Meister, sjå fiketreet som du banna, hev turka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Då tok Jesus til ords og sagde: «Hav tru til Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Det segjer eg dykk for sant: Um nokon segjer til dette fjellet: Lyft deg upp og kasta deg ut i havet! og ikkje hev tvil i hjarta, men trur at det vil ganga som han segjer, so skal det ganga som han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Difor segjer eg dykk: Kva de bed um og ynskjer etter, so tru visst at de alt hev fenge det - då fær de det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Og når de stend og bed, og hev noko imot einkvan, so tilgjev honom det! Då skal og far dykkar i himmelen tilgjeva dykk for misgjerningarne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Men um de ikkje tilgjev, skal ikkje heller far dykkar i himmelen tilgjeva dykkar misgjerningar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'So kom dei til Jerusalem att. Og med han gjekk ikring i templet, kom dei øvste prestarne og dei skriftlærde og styresmennerne burt til honom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'og sagde: «Kva rett hev du til å gjera dette, eller kven gav deg retten til å gjera det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, '«Eg vil spyrja dykk um ein ting,» sagde Jesus. «Svara meg, so skal eg segja dykk kva rett eg hev til å gjera dette:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Var dåpen åt Johannes frå himmelen eller frå menneskje? Svara meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Då lagde dei yver med kvarandre og sagde: «Svarar me: «Frå himmelen,» so segjer han: «Kvi trudde de honom då ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Lat oss heller svara: «Frå menneskje!»» men det torde dei ikkje for folket; for alle trudde at Johannes var retteleg ein profet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'So svara dei honom: «Det veit me ikkje.» «Då segjer ikkje eg dykk heller kva rett eg hev til å gjera dette,» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'So tok han til å tala til deim i likningar: «Det var ein mann som laga seg ein vingard, og sette gjerde kringum, og grov ei vinpersa, og bygde eit tårn; so leigde han hagen burt til brukarar og for utanlands.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Då tidi kom, sende han ein svein til brukarane, og vilde få noko av det som var avla i vingarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Men brukarane greip sveinen og dengde honom, og sende honom burt med tome hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'So sende han ein annan svein til deim; den slo dei i hovudet og hædde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Og han sende ein til; honom slo dei i hel. Og mange fleire: sume skamslo dei, og sume drap dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'No hadde han berre ein att, ein son, som han heldt hjarteleg av. Til slutt sende han honom og til brukarane; «Dei hev no vel age for son min!» tenkte han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Men brukarane sagde seg imillom: «Der er ervingen! Kom, lat oss slå honom i hel, so fær me arven!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'So tok dei honom og slo honom i hel og kasta honom ut or vingarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Kva skal han no gjera, han som eig vinhagen? Han skal koma og gjera ende på brukarane og lata andre få vingarden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Hev de’kje lese dette skriftordet heller: «Den steinen byggjarane vanda, Den var det som vart hyrnestein;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'D’er Herren sjølv som so hev gjort det; For oss er det eit under stort?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Då vilde dei ha gripe honom, for dei skyna at det var deim han hadde meint med likningi si. Men dei torde ikkje for folket. So let dei honom vera og gjekk sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Sidan sende dei nokre av farisæarane og Herodes-mennerne, som skulde fanga honom i ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Dei kom og sagde til honom: «Meister, me veit du er ærleg og ikkje bryr deg um nokon; for du gjer ikkje skil på folk, men lærer oss sanningi um Guds veg - er det rett å svara skatt til keisaren, eller ikkje? Skal me gjera det, eller skal me lata vera?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Men skyna vel hyklingi deira og sagde: «Kvi freistar de meg? Kom med ei sylvmynt, og lat meg få sjå henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'So kom dei med ei, og han spurde: «Kva er dette for eit bilæte og namn?» «Det er keisarens,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Då sagde han til deim: Gjev keisaren det som keisarens er, og Gud det som Guds er!» Og dei undrast mykje yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'So kom det nokre sadducæarar til honom - det er dei som segjer at det ikkje er noko uppstoda - dei tok til å spyrja honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '«Meister, Moses hev skrive den lovi for oss at når bror åt ein mann døyr barnlaus, og kona liver etter, då skal broren taka enkja og halda uppe ætti åt bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'No var det var ein gong sju brør. Den fyrste tok seg ei kona; han døydde, og det var’kje born etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'So tok den andre enkja; han og døydde barnlaus. Like eins den tridje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'og alle sju; ingen av deim hadde born etter seg. Sist av alle døydde kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Kven av deim skal ho vera kona åt i eit anna liv, når dei hev stade upp att? For alle sju hev havt henne til kona.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, '«Syner’kje dette at de fer vilt, og ikkje kjenner skrifterne og ikkje Guds magt?» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, '«Når dei hev stade upp frå dei daude, gifter dei seg ikkje, og vert ikkje burtgifte; dei er som englarne i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Men um dei avlidne - at dei skal standa upp att - hev de’kje lese i boki åt Moses, i soga um klungeren, korleis Gud sagde til honom: «Eg er Abrahams Gud og Isaks Gud og Jakobs Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Og han er ikkje Gud for dei daude, men for dei livande. De tek storleg i mist.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Ein skriftlærd, som lydde på ordskiftet deira, og skyna at Jesus hadde svara deim godt, kom og spurde honom: «Kva for eit bod er det fyrste av alle?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jesus svara: «Det fyrste er: «Høyr, Israel! Herren vår Gud, Herren er ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Og du skal elska Herren, din Gud, av alt ditt hjarta og av all din hug og av alt ditt vit og av all di magt! Det er det fyrste bodet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Det andre er dette: Du skal elska grannen din som deg sjølv! Det finst ikkje noko anna bod som er større enn desse.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, '«Vel tala du, meister,» sagde den skriftlærde, «og sant er det som du sagde, at han er ein og det finst ingen annan Gud enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Å elska honom av alt sitt hjarta og av alt sitt vit og av all si magt, og elska grannen sin som seg sjølv, det er meir enn alle brennoffer og slagtoffer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Då Jesus høyrde kor visleg han svara, sagde han til honom: «Du er ikkje langt frå Guds rike.» Sidan torde ingen spyrja honom meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Medan Jesus lærde folket i heilagdomen, tok han ein gong soleis til ords: «Korleis kann dei skriftlærde segja at Messias er Davids son?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Sjølv sagde David - han fekk det frå den Heilage Ande -: «Herren sa til herren min: «Sit ved høgre handi mi, Til eg dine fiendar Fær for dine føter lagt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David kallar honom sjølv herre; korleis kann han då vera son hans?» Ålmugen høyrde gjerne på Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Millom anna som han lærde deim, sagde han: «Tak dykk i vare for dei skriftlærde, som likar å ganga i lange kjolar, og vil helsast på torgi');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'og hava dei fremste sessarne i synagogorne og høgste sæti i gjestebod;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'dei som et upp huset for enkjor og held lange bøner for syns skuld. Dei skal få so mykje strengare dom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Ein gong sette han seg midt imot tempelkista, og såg på med folk lagde pengar i kista; og mange rike lagde mykje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'So kom det ei fatig enkja og lagde tvo skjervar, det er so mykje som ein øyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Då kalla han læresveinarne til seg og sagde: «Det segjer eg dykk for sant: Denne fatige enkja hev lagt meir enn alle dei som lagde i kista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'For dei gav alle av nøgdi si; men ho gav av si fatige råd alt det ho åtte, alt ho hadde til å livberga seg med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Då han gjekk ut or templet, sagde ein av læresveinarne til honom: «Meister, sjå for steinar og for bygningar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, '«Ja, ser du desse store bygningarne!» svara Jesus. «Her ligg ikkje stein på stein som ikkje skal rivast laus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Sidan, då han sat på Oljeberget midt imot templet, og det ikkje var nokon innmed, kom Peter og Jakob og Johannes og Andreas og spurde honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '«Seg oss: Når skal dette henda, og kva er teiknet me fær når alt dette er åt og skal koma?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Då tok Jesus soleis til ords: «Sjå dykk fyre, so ingen forvillar dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Mange skal taka mitt namn og segja: «Det er eg!» og føra mange på avveg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Men når de høyrer um ufred og tidend um ufred, so vert ikkje rædde! Dette lyt henda; men enden kjem ikkje endå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Folk skal reisa seg imot folk, og rike mot rike; det skal vera jordskjelv kring i landi, det skal vera uår og upprør. Det er det fyrste av føderiderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Men sjå dykk fyre! Dei kjem til å draga dykk for domstolarne og piska dykk i synagogorne, og for landshovdingar og kongar skal de førast fram for mi skuld, so de kann vitna for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Og fyrst lyt evangeliet berast ut til alle folkeslag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Men når dei fører dykk burt og gjev dykk yver til retten, so syt ikkje for kva de skal tala! Det som vert gjeve dykk i same stundi, det skal de tala; for det er ikkje de som talar, men den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Bror skal senda bror i dauden, og faren barnet sitt, og born skal standa fram mot foreldri sine, og valda at dei lyt døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Og alle skal hata dykk for mitt namn skuld; men den som held ut til endes, han skal verta frelst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Men når de ser at den øydande styggedomen stend der han ikkje skulde» - agte vel på dette, du som les! - «då lyt dei som er i Judaland røma til fjells;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'den som er uppå taket, må ikkje stiga ned, og ikkje ganga inn og henta noko i huset sitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'og den som er utpå marki, må ikkje ganga heim etter kjolen sin!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Stakkars deim som gjeng med barn eller gjev brjost i dei dagarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Men bed at dette ikkje må henda um vinteren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'For den tidi skal vera so hard at det aldri hev vore so hard ei tid frå upphavet åt skaparverket som Gud hev gjort, og til no, og vert ikkje sidan heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Og gjorde’kje Herren den tidi stutt, so vart’kje eit liv berga; men for deira skuld som han valde seg ut, hev han gjort den tidi stutt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Um nokon då segjer med dykk: «Sjå her er Messias - Sjå der!» so må de ikkje tru det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'For falske Messias’ar skal standa fram, og falske profetar, og gjera teikn og under for å forvilla dei utvalde, um det er råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'So sjå dykk fyre! Eg hev sagt dykk alt fyreåt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Men i dei dagarne, etter denne harde tidi, skal soli myrkjast, og månen missa sitt ljos;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'stjernorne skal falla ned frå himmelen, og himmelkrafterne skakast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Då skal dei sjå Menneskjesonen koma i skyi med stort velde og herlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'og då skal han senda ut englarne, og samla dei utvalde frå heimsens fire hyrno, frå ytste enden av jordi til ytste enden av himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Lær ei likning av fiketreet: Når sevja hev kome i greinerne, og lauvet sprett, då veit de at sumaren er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Like eins når de ser dette hender, då veit de at han er utfor døri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Det segjer eg dykk for visst: Denne ætti skal ikkje forgangast fyrr alt dette hev hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Himmel og jord skal forgangast; men mine ord skal ikkje forgangast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Men den dagen og timen veit ingen, ikkje englarne i himmelen, og ikkje Sonen - ingen utan Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Sjå dykk fyre, og vak! For de veit ikkje når tidi kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Det er liksom med ein mann som drog utanlands. Då han for heimantil, sette han sveinarne sine til å styra for seg. Kvar fekk sitt å gjera, og til portnaren sagde han at han laut vaka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'So vak då! For de veit’kje når husbonden kjem - um kvelden, eller midnattsbil, eller i otta, eller i dagrenningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Lat honom ikkje finna dykk sovande, um han skulde koma uventande på dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Men det eg segjer dykk, det segjer eg alle: Ver vakne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'No var det berre tvo dagar att til påske- og søtebrødhelgi. Og dei øvste prestarne og dei skriftlærde leita etter ei råd til å gripa Jesus med list og slå honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, '«For på høgtidi torer me ikkje gjera det,» sagde dei; «elles kunde det verta upplaup blant folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Med Jesus var i Betania, hjå Spilte-Simon, og sat til bords, kom det inn ei kvinna med ei alabaster-krukka full av egte, dyr nardesalve. Ho braut sund krukka og helte salven ut yver hovudet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Då var det nokre som vart harme og sagde seg imillom: «Kva skulde den salve-øydingi vera til?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Salven kunde vore seld for yver femti dalar og gjeven til dei fatige.» Og dei tala kvast til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Då sagde Jesus: «Lat henne vera i fred! Kvi er de so leide med henne? Det var vænt gjort det ho gjorde med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Dei fatige hev de alltid hjå dykk, og når de vil, kann de gjera vel imot deim; men meg hev de ikkje alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ho gjorde det ho kunde; med denne salven budde ho likamen min fyre jordferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Og det segjer eg dykk for visst: Kvar i verdi evangeliet vert kunngjort, der skal dei og nemna det ho hev gjort, til minne um henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Judas Iskariot, den eine av dei tolv, gjekk til dei øvste prestarne og baud seg til å gjeva Jesus i henderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Då dei høyrde det, vart dei glade, og lova dei skulde gjeva honom pengar, og sidan lurde han korleis han med tid og høve skulde få gjeve Jesus yver til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Den fyrste dagen i søtebrødhelgi - då påskelambet vart slagta - sagde læresveinarne med Jesus: «Kvar vil du me skal ganga av og laga til påskemålet for deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Då sende han tvo av læresveinarne i veg, og sagde til deim: «Gakk inn i byen! Der møter de ein mann som ber ei krukka med vatn; honom skal de fylgja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'og der han gjeng inn, skal de segja med husbonden: «Meisteren helsar: Kvar er romet mitt, der eg kann eta påskemålet med læresveinarne mine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Då syner han dykk ein stor sal, som stend ferdig med duka bord; der skal de stella til måltidi for oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'So gjekk læresveinarne av stad, og då dei kom inn i byen, fann dei det so som han hadde sagt, og dei laga til påskelambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Då det leid mot kvelden, kom Jesus med dei tolv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'og då dei hadde sett seg til bords, sagde han: «Det segjer eg dykk for sant: Ein av dykk kjem til å svika meg, ein som et i lag med meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Då tok dei til å stura, og spurde honom, ein for ein: «Det er vel’kje eg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, '«Det er ein av dykk tolv, svara han, «den som duppar med meg i fatet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Menneskjesonen gjeng fulla burt, soleis som det er skrive um honom, men ve yver den mannen som veld at Menneskjesonen vert gjeven i fiendehand! Best for den mannen um han aldri var fødd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Med dei sat til bords, tok han brødet, signa det og braut det, og gav deim og sagde: «Tak det! Dette er likamen min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'So tok han ein kalk, takka og gav deim, og dei drakk alle av kalken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Og han sagde med deim: Dette er blodet mitt, paktblodet, som renn for mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Det segjer eg dykk for sant: Eg skal ikkje oftare drikka av druvesafti, fyrr den dagen kjem då eg drikk henne ny i Guds rike.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Då dei hadde sunge lovsongen, gjekk dei ut til Oljeberget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Og Jesus sagde: «De kjem alle til å styggjast ved meg. For det stend skrive: «Hyrdingen slær eg i hel, og sauern’ skal spreidast ikring.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Men når eg hev stade upp att, skal eg ganga fyre dykk til Galilæa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Då sagde Peter: «Um so alle styggjest, so skal ikkje eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, '«Det segjer eg deg for sant,» svara Jesus: «No i denne natt, fyrr hanen hev gale tvo gonger, skal du avneitta meg tri gonger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Men han tok endå sterkare i og sagde: «Um eg so lyt døy med deg, skal eg ikkje avneitta deg!» Det same sagde dei alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'So kom dei til ein stad som heiter Getsemane. Då segjer han til læresveinarne sine: «Sit her med eg bed!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Og han tok med seg Peter og Jakob og Johannes, og tok til å ottast og kvida seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Og han sagde til deim: «Hjarta mitt er so fullt av sorg - det er som det vilde bresta. Ver her og vak!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'So gjekk han eit lite stykke fram og kasta seg ned på jordi, og bad at denne stundi måtte skrida framum honom, um det var råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, '«Abba» - Fader - sagde han, «alt er mogelegt for deg; tak denne skåli frå meg! Men ikkje som eg vil, berre som du vil!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Då han kom attende, såg han at dei hadde sovna. Då sagde han til Peter: «Simon, søv du? Var du’kje god til å vaka ein time?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Vak og bed, so de ikkje skal koma i freisting! Åndi er viljug, men kjøtet er veikt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'So gjekk han burt att og bad den same bøni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Då han kom attende, såg han at dei hadde sovna til att, for augo deira var tunge av svevn. Og dei visste ikkje kva dei skulde svara honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'So kom han tridje gongen, og sagde til deim: «De søv og kviler, de! Det er nok! Timen er komen. No skal Menneskjesonen gjevast i henderne på syndarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Statt upp og lat oss ganga! Svikaren er’kje langt undan!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Og straks - fyrr han hadde tala ut, kjem Judas, ein av dei tolv, og med honom ein flokk med sverd og stavar; dei kom frå dei øvste prestarne og dei skriftlærde og styresmennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Svikaren hadde avtala eit teikn med deim og sagt: «Den som eg kysser, han er det: tak honom, og før honom trygt burt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Og med det same han kom, gjekk han fram til honom og sagde: «Rabbi!» og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Då lagde dei hand på honom og tok honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Men ein av deim som stod innmed, drog sverdet sitt og hogg øyra av tenaren åt øvstepresten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Og Jesus tok til ords og sagde: «De kjem med sverd og stavar og tek meg, som eg skulde vera ein røvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Dag etter dag var eg hjå dykk i templet og lærde folket; då tok de meg ikkje. Men soleis laut skrifterne sannast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Då tok dei alle ut ifrå honom og rømde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Ein ung mann fylgde etter honom, og hadde sveipt eit linklæde kring berre kroppen; dei vilde taka honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'men han slepte linklædet og rømde naken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Dei førde Jesus til øvstepresten, og der samla dei seg alle dei øvste prestarne og styresmennerne og dei skriftlærde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Peter fylgde eit langt stykke etter, til han kom inn i garden åt øvstepresten; der vart han sitjande hjå tenarane og vermde seg ved elden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Dei øvste prestarne og heile det Høge Rådet leita etter vitnemål mot Jesus, so dei kunde få dømt honom frå livet; men dei fekk’kje noko på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Det var mange som vitna rangt imot honom, men vitnemåli høvde ikkje i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Då stod det fram nokre som og vitna rangt imot honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '«Me høyrde honom segja: «Eg skal riva ned dette templet som er gjort med hender, og på tri dagar skal eg byggja eit anna som ikkje er gjort med hender.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Men endå høvde’kje vitnemåli deira i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Og øvstepresten reiste seg og steig fram ibland deim og sagde til Jesus: «Svarar du inkje på det som desse vitnar imot deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Men Jesus tagde og svara ikkje eit ord. Då tok øvstepresten til ords att og spurde honom: «Er du Messias, son åt den Høglova?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, '«Ja, det er eg,» svara Jesus, «og de skal sjå Menneskjesonen sitja ved høgre handi åt Allmagti og koma med himmelskyerne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Då reiv øvstepresten sund klædi sine og sagde: «Kva skal me med fleire vitne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'No høyrde de gudsspottingi! Kva tykkjer de?» Dei dømde alle at han var skuldig til å døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Og sume tok til å sputta på honom, og lagde eit plagg yver andlitet hans og slo honom med nevarne og sagde: «Seg kven det var!» Og tenarane tok imot honom med hogg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Med Peter var nedi gardsromet, kjem ei av tenestgjentorne hjå øvstepresten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'og då ho såg Peter, som sat og vermde seg, stirde ho på honom og sagde: «Du var og med denne nasaræaren, Jesus!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Men han neitta og sagde: «Eg veit ikkje og skynar ikkje kva du talar um.» So gjekk han ut i fyregarden. Då gol hanen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Sidan fekk gjenta sjå honom att, og tok til å segja med deim som stod innmed: «Han der er ein av deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Men han neitta på nytt lag. Eit lite bel etter sagde dei som stod der på nytt til Peter: «Ja menn er du ein av deim! Du er då ein galilæar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Då tok han til å banna og sverja: «Eg kjenner ikkje den mannen de talar um.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Og i det same gol hanen andre gongen. Då kom Peter i hug det ordet som Jesus hadde sagt til honom: Fyrr hanen hev gale tvo gonger, skal du avneitta meg tri gonger. Og han tok det til hjarta og gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Det tok alt til å dagast då dei øvste prestarne med styresmennerne og dei skriftlærde - heile den Høgste Retten - var ferdige med rådleggjingi si. Då batt dei Jesus og førde honom burt og gav honom yver til Pilatus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilatus spurde honom: «Er du kongen yver jødarne?» - «Det er dine ord,» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Dei øvste prestarne kom med mange klagemål mot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Då spurde Pilatus honom att: «Svarar du ingen ting? Høyr alt det dei klagar deg for!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Men Jesus svara ikkje eit ord meir, so Pilatus tok til å undrast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Kvar høgtid gav Pilatus deim ein fange fri, den som dei sjølve bad um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Og ein som heitte Barabbas sat då fengsla i hop med nokre ufredsmenner; dei hadde gjort eit upplaup og drepe nokon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'So kom folket upp og tok til å beda um det som Pilatus var van med å gjera for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Då svara han deim: «Vil de eg skal gjeva dykk jødekongen fri?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'for han skyna det var av ovund dei øvste prestarne hadde gjeve Jesus yver til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Men dei øvste prestarne fekk eggja upp folket, so dei bad at han heller skulde gjeva deim Barabbas fri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Då tok Pilatus til ords att og sagde: «Kva vil de då eg skal gjera med honom som de kallar kongen yver jødarne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Dei svara med å ropa: «Krossfest honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, '«Kva vondt hev han då gjort?» sagde Pilatus. Men dei ropa berre endå sterkare: «Krossfest honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilatus vilde gjerne gjera folket til lags. Han gav deim Barabbas fri, men Jesus let han piskast, og gav honom yver til hermennerne sine, so dei skulde krossfesta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Hermennerne førde Jesus inn i garden, i borgi, og kalla i hop heile vakti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Dei klædde honom i ei purpurkåpa, og sette på honom ein klungerkrans som dei hadde fletta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'og tok til å helsa honom: «Heil deg, jødekonge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'So slo dei honom i hovudet med ei røyr, og sputta på honom, og lagde seg på kne og hyllte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Då dei hadde spotta honom som dei vilde, klædde dei av honom purpurkåpa, og hadde på honom hans eigne klæde, og so leidde dei honom ut og skulde krossfesta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Då gjekk det ein mann framum, som kom frå marki; det var Simon frå Kyrene, far åt Aleksander og Rufus; honom nøydde dei til å bera krossen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Dei førde honom til den staden som heiter Golgata - det er det same som Skallestaden -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Der baud dei honom vin med myrra i; men han vilde ikkje hava det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'So feste dei honom til krossen. Klædi hans skifte dei millom seg, og drog strå um kva kvar skulde hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Det var i den tridje timen dei krossfeste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'På krossen var det sett ei innskrift som nemnde skuldi hans; ho lydde so: Kongen yver jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Saman med honom krossfeste dei tvo røvarar, ein på hans høgre og ein på hans vinstre sida;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'og då sannast det skriftordet som segjer: «Og han vart rekna millom brotsmenner.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Dei som gjekk framum, hædde honom og riste på hovudet og sagde: «Å, du som riv ned templet og byggjer det upp att på tri dagar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Hjelp deg no sjølv, og stig ned av krossen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Sameleis spotta dei øvste prestarne og, både dei og dei skriftlærde, og sagde seg imillom: «Andre hev han hjelpt, seg sjølv kann han ikkje hjelpa!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Lat no Messias, Israels konge, stiga ned av krossen, so me kann sjå det og tru!» Dei som var krossfeste med honom, gav seg og til å skjella honom ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Då den sette timen var komen, vart det myrkt yver heile landet, alt til den niande timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Og i den niande timen ropa Jesus med høg røyst: «Elo’i, Elo’i, lama sabaktani?» det er: «Min Gud, min Gud, kvi hev du forlate meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Nokre av deim som stod der sagde, då dei høyrde det: «No ropar han på Elia!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Då sprang det ein fram, duppa ein svamp i vineddik, sette honom på ei tein og let Jesus få drikka og sagde: «Venta! Lat oss sjå um Elia kjem og vil taka honom ned!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Og Jesus gav ifrå seg eit høgt rop, og andast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Då rivna forhenget i templet midt i tvo, ovantil og radt ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Og då hovudsmannen som stod der midt framfyre honom, såg korleis han andast, sagde han: «Den mannen var visst og sant Guds Son!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Det var og nokre kvinnor der, som stod eit stykke undan og såg på. Millom deim var både Maria Magdalena, og Maria mor åt Jakob den yngre og Joses, og Salome,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'som alle hadde fylgt honom med han var i Galilæa, og tent honom, og mange andre kvinnor, som hadde vore med honom upp til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Det var då fyrebuingsdagen eller dagen fyre kviledagen, og då det alt leid mot kvelden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'kom Josef frå Arimatæa, ein gjæv rådsherre, som og venta på Guds rike; han våga seg til å ganga inn til Pilatus og beda um likamen åt Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatus undrast på um han alt var slokna;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'han kalla hovudsmannen til seg, og spurde um Jesus nyst var slokna, og då han hadde fenge vissa um det av hovudsmannen, let han Josef få liket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'So kjøpte Josef linty og tok honom ned, sveipte honom i lintyet og lagde honom i ei grav som var hoggi ut i berget, og so velte han ein stein attfor gravopningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Og Maria Magdalena og Joses-Maria såg staden der han vart lagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Då kviledagen var ende, kjøpte Maria Magdalena og Jakobs-Maria og Salome angande kryddor; for dei vilde ganga av stad og salva honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Ovtidleg den fyrste dagen i vika - det var so vidt soli hadde runne - kom dei til gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Då sagde dei seg imillom: «Kven skal me få til å velta steinen frå gravopningi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Men då dei såg upp, vart dei vare at steinen var fråvelt, og han var ovstor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Då dei kom inn i gravi, såg dei ein ung mann, som sat på høgre sida, klædd i ein lang kvit kjole. Dei vart forfærde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'men han sagde: «Ver ikkje forfærde! De leitar etter Jesus frå Nasaret, han som vart krossfest! Han hev stade upp att; han er ikkje her. Sjå her er staden der dei lagde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Men gakk no av stad og seg med læresveinarne hans og med Peter at han gjeng fyre dykk til Galilæa; der skal de sjå honom, som han hev sagt dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Då gjekk dei ut att og rømde frå gravi; for fælska hadde teke deim, so dei skalv og var mest ifrå seg. Og dei tala’kje eit ord til nokon, so rædde var dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Då Jesus hadde stade upp att, tidleg den fyrste dagen i vika, synte han seg fyrst for Maria Magdalena, som han hadde drive sju vonde ånder utor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ho gjekk av stad og sagde det til deim som hadde vore med honom, og som no syrgde og gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Men då dei fekk høyra at han livde, og at ho hadde set honom, vilde dei ikkje tru det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Sidan synte han seg i ein annan skapnad for tvo av dei, som gjekk etter vegen og skulde ut på landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Dei og kom og sagde det med dei andre, men dei trudde ikkje deim heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Seinare synte han seg for dei elleve sjølve, med dei sat til bords; og han lasta deim for vantrui og tråskapen deira, at dei ikkje trudde deim som hadde set honom etter han var staden upp att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Og han sagde til deim: «Gakk ut i all verdi og kunngjer evangeliet for all skapningen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Den som trur og vert døypt, skal verta frelst, men den som ikkje trur, skal verta fordømd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Og desse teikni skal fylgja deim som trur: I mitt namn skal dei driva ut vonde ånder; dei skal tala med nye tungor;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'dei skal taka ormar i henderne, og um dei drikk noko som det er gift i, so skal det ikkje skada deim; legg dei henderne på sjuke, so skal dei få att helsa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Etter Herren Jesus hadde tala til deim, vart han teken upp til himmels og sette seg ved Guds høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Og dei gjekk ut og tala Guds ord alle stader, og Herren var med deim og stadfeste ordet med dei teikni som fylgde med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Det er alt mange som hev teke seg til å setja upp ei fråsegn um dei hendingarne som hev gjenge fyre seg hjå oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'so som dei hev bore det fram dei som frå fyrsten var augvitne og ærendsveinar åt ordet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Difor hev eg og sett meg fyre at eg vilde granska alt vel frå grunnen og so skriva det upp åt deg, gjævaste Teofilus - stykke for stykke, soleis som det heng saman,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'so du kann sjå kor truverdig ho er den soga som du hev høyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'I den tidi då Herodes var konge i Jødeland, var det ein prest som heitte Zakarja; han høyrde til det prestelaget som hev namn etter Abia. Kona hans var ætta frå Aron, og heitte Elisabet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Båe var dei rettferdige for Gud; dei fylgde alle Herrens bod og fyresegner, og ingen kunde finna noko å lasta deim for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Men dei hadde ikkje born; for Elisabet var’kje barnkjømd, og dei var båe fram i åri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'So var det ein dag Zakarja gjorde prestetenesta for Gud; for turen var komen til hans lag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'og då dei drog strå, som visi er millom prestarne, fall det på honom å ganga inn i Herrens tempel og bera fram røykofferet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'med heile folkemengdi stod utanfor og bad i røykoffertimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Då fekk han med ein gong sjå ein Herrens engel, som stod på høgre sida åt røykofferaltaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Då Zakarja såg engelen, stokk han, og det kom ein otte yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Men engelen sagde til honom: «Ver ikkje rædd, Zakarja! Gud hev høyrt bøni di; du og Elisabet, kona di, skal få ein son, og du skal kalla honom Johannes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Då vert du både glad og fegen, og mange skal gleda seg av di han er fødd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'For han skal vera stor i Herrens augo; han skal ikkje drikka vin eller sterke drykkjer, og alt ifrå morsliv skal han fyllast av den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Mange av Israels-sønerne skal han venda um til Herren, deira Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'og sjølv skal han ganga fyre honom i Elias ånd og kraft, og venda hjarto åt federne um til borni, og dei ulyduge til den hug som bur i rettferdige menner, so han kann vinna Herren eit vel fyrebutt folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, '«Korleis kann eg vita um dette er sant?» sagde Zakarja til engelen; «eg er då ein gamall mann, og kona mi er og fram i åri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Då svara engelen: «Eg er Gabriel, som stend for Guds åsyn. Eg er send hit og skal tala med deg og bera dette gledebodet til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Og no skal du ljota tegja, og ikkje kunna tala, alt til den dagen dette hender, for di du ikkje trudde meg; men det eg hev sagt, skal sannast når tidi er komi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Medan stod folket og venta på Zakarja, og undra seg yver at han drygde so lenge i templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Men då han kom ut, og ikkje kunde tala med deim, skyna dei at han hadde set ei syn i templet; sjølv nikka han og gjorde teikn til deim, men var og vart mållaus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'og då tidi for tempeltenesta hans var ute, for han heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Eit bil etter hende det at Elisabet, kona hans, vart med barn. Då heldt ho seg heime i fem månader, og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '«Soleis hev Herren laga det for meg då tidi var komi at han i nåde vilde taka burt skammi mi millom folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Då det leid på sette månaden, vart engelen Gabriel send frå Gud til ein by i Galilæa som dei kallar Nasaret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'åt ei møy som var trulova med ein mann som heitte Josef, av Davids-ætti, og møyi heitte Maria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Då engelen kom inn til henne, sagde han: «Guds fred, du som hev fenge slik nåde! Herren er med deg! Velsigna er du millom kvinnor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ved desse ordi stokk ho, og tenkte med seg: «Kva er dette for ei helsing?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Men engelen sagde til henne: «Ver ikkje rædd, Maria! Du hev funne nåde hjå Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Du skal verta med barn og få ein son, og kalla honom Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Han skal vera stor og kallast son åt den Høgste, og Herren Gud skal gjeva honom kongsstolen åt David, ættfaren hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'han skal vera konge yver Jakobs-ætti i all æva, og det skal ikkje vera ende på kongedømet hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, '«Korleis skal det ganga til, når eg ikkje hev mann?» sagde Maria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, '«Den Heilage Ande skal koma yver deg, og krafti åt Den Høgste skal skyggja yver deg,» svara engelen; «difor skal og det heilage som vert født, kallast Guds Son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Og høyr: Elisabet, som er skyld deg, skal og hava ein son på sine gamle dagar; dei sagde ho var ikkje barnkjømd, men no er ho alt i sette månaden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'for ingen ting er umogeleg for Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Då sagde Maria: «Her stend eg - eg er Herrens tenestkvinna! Lat det ganga meg som du hev sagt!» So for engelen burt att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Straks etter tok Maria av stad, og for so fort ho kunde upp i fjellbygderne, til ein by i Judaland;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'der gjekk ho inn i huset åt Zakarja og helsa på Elisabet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Då hende det at med same Elisabet høyrde helsingi hennar Maria, hoppa fostret i livet hennar; og ho vart fyllt av den Heilage Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'og kvad med høg røyst: «Velsigna vere du i kvendeflokk, velsigna det du under beltet ber!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Kvi skal det timast meg so store ting at mor åt Herren min kjem hit til meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'For då di helsing nådde øyra mitt, då hoppa fostret i mitt liv av frygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Ja, sæl er ho som leit på Herrens ord, at det han hadde lova, laut gå fram!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Og Maria svara: «Mi sjæl høglovar Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'mitt hjarta gleder seg i Gud, min frelsar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Han tenkte på si ringe tenestkvinna! For ifrå denne stund skal alle ætter kalla meg for sæl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Stort er det han for meg hev gjort den Megtige, og heilagt er hans namn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'frå ætt til ætt hans miskunn når mot deim som ottast honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Velduge verk so gjer hans sterke arm; storlåtne spreider han for ver og vind med deira høgferds-hug;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'han støyter hovdingar frå høgsæte og lyfter låge upp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Hungrige mettar han med gode gåvor, og rikingar rek han tomhendte burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Han sytte vel for Israel, sin svein; til evig tid han minnast vil -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'So var hans ord til federn’ våre - si miskunn mot Abraham og hans ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Maria vart verande hjå henne um lag tri månader; sidan for ho heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'So kom tidi at Elisabet skulde eiga barn, og ho åtte ein son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Og då grannarne og skyldfolket høyrde kor stor ein nåde Herren hadde vist henne, vart dei glade og ynskte henne til lukka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Åtte dagar etter kom dei og skulde umskjera guten; men då dei vilde kalla honom Zakarja etter faren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'tok mor hans til ords og sagde: «Nei, han skal heita Johannes!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, '«Det er ingen i ætti som heiter so,» svara dei,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'og dei gjorde teikn til faren, kva han vilde guten skulde kallast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Då bad han um ei tavla og skreiv: «Johannes er namnet hans!» Alle undra seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'men i det same fekk han att mål og mæle, og han tala og prisa Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Då kom der ein otte på alle dei som budde der ikring; i heile Judaheidi vart alt dette mykje umtala,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'og kvar den som høyrde det, tok det til minnes og sagde: «Kva tru den guten er etla til?» For Herren heldt si hand yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Men Zakarja, far hans, vart fyllt av den Heilage Ande, og han tala profetord og kvad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '«Velsigna vere Herren, Israels eigen Gud! Til lyden sin han lydde, og løyste deim or band;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'ei frelsarmagt vekt’ han oss upp, ei veldug, uti Davids ætt, som var hans trugne svein -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Som han frå fordom gjenom Heilag profetmunn sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Frå fiendarne frelsa, frå kvar ei hatarhand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Han vil federn’ våre vel, og kom i hug den heilage og støde pakti si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'den eid han hadde svore vår ættfar, Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Han vilde ut oss fria or fiendsmagt og fiendsvald, so me han utan rædsl’ og rygd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'i rettferd og med heilag hug kann tena all vår tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Du og, min son, skal kallast Allhøge Guds profet, skal fyre Herren fara, og rydja vel hans veg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'og læra lyden hans å sjå frelsa, dei finna skal når han all deira synd forlet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'For miskunnsam av hjarta er han, vår gode Gud, ei stjerna let han skina for oss frå himmelhøgd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Lysa for deim som sit i myrkr og daudsens skodd, og styra inn på velferds-veg vår fot.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Og guten voks og vart sterk i åndi; han heldt seg i øydemarkerne til tidi kom då han skulde førast fram for Israel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'I dei dagarne let keisar Augustus lysa ut at det skulde takast manntal yver heile verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Dette var fyrste gongen dei tok manntal med Kvirinius var landshovding i Syria.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Då for alle heim, kvar til sin eigen by, og skulde skriva seg i manntalet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Josef og for frå Galilæa, frå den byen som heiter Nasaret, upp til Judæa, til Davidsbyen, den som dei kallar Betlehem - for han høyrde til Davids hus og ætt -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'og vilde skriva seg der. Maria, festarmøyi hans, var med honom; ho gjekk då med barn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'og med dei var der, bar det so til at tidi hennar kom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'og ho åtte den fyrste sonen sin; ho sveipte honom og lagde honom i ei krubba, for det var ikkje rom åt dei i herbyrget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Det var nokre hyrdingar der i bygdi som låg ute og vakta buskapen sin um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Best det var, stod ein engel frå Herren innmed deim, og Herrens herlegdom lyste kringum deim. Då vart dei fælande rædde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'men engelen sagde til deim: «Ver ikkje rædde! Eg kjem med bod til dykk um ei stor gleda som skal timast alt folket:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'I dag er det fødd dykk ein frelsar i Davids by; han er Kristus, Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Og det skal de hava til merke: de skal finna eit lite barn som er sveipt og ligg i ei krubba.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Og brått var det ein stor her av himmelånder med engelen; dei lova Gud og kvad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '«\'ra vere Gud i det høgste, og fred på jordi, og hugnad med menneskje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Då englarne hadde fare burt att og upp til himmelen, sagde hyrdingarne seg imillom: «Lat oss no ganga radt til Betlehem og sjå dette som hev hendt, og som Herren hev vitra oss um!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'So skunda dei seg dit, og fann Maria og Josef, og det vesle barnet som låg i krubba.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Og då dei hadde set det, fortalde dei alt som hadde vorte sagt deim um dette barnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Alle som høyrde på hyrdingarne, undra seg yver det dei fortalde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'men Maria gøymde alle desse ordi i hjarta, og gruna på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Og hyrdingarne for heim att, og lova og prisa Gud for alt det dei hadde høyrt og set, og som høvde so vel med det som var sagt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Då åtte dagar var lidne, og han skulde umskjerast, kalla dei honom Jesus; det var det namnet engelen hadde nemnt, fyrr han var komen i morsliv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'So snart reinsingstidi som er fyreskrivi i Moselovi, var til endes for deim, tok dei honom med seg upp til Jerusalem; dei vilde te honom fram for Herren');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '- soleis som det stend skrive i Herrens lov: «Alt mannkyn som kjem fyrst frå morsliv, skal kallast heilagt åt Herren» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'og vilde bera fram offer, etter det som er sagt i Herrens lov: «eit par turtelduvor eller tvo duveungar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'I Jerusalem var det då ein mann som heitte Simeon, ein rettferdig og gudleg mann, som venta på Israels trøyst; den Heilage Ande var yver honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'og hadde vitra honom um at han ikkje skulde fara or verdi, fyrr han hadde set Herrens Messias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'No kom han til templet - det var Anden som dreiv honom - og då foreldri kom berande inn med Jesus-barnet, og vilde fara med det som visi var etter lovi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'tok han det og på armarne, og lova Gud og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '«Herre, no gjev du din tenar heimlov, som ordet ditt lydde, og let han fara i fred!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'For no fekk auga mitt skoda di frelsa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'som du hev skipa til for åsyni åt alle folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'eit ljos som for heidningarn’ lyser, ein herlegdom og ei æra for Israel, folket ditt eige.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Far hans og mor hans undra seg yver det som vart sagt um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Og Simeon velsigna deim og sagde til Maria, mor hans: «Dette barnet er sett til fall og uppreising for mange i Israel og til eit motsegjingsteikn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'men deg og skal sverdet stinga gjenom hjarta; då kjem det upp kva tankar mange gøymde i hugen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Det var og ei profetkvinna der, Anna Fanuelsdotter av Assers-ætti. Ho var langt ut i åri; etter ho vart gift, hadde ho butt i hop med mannen sin i sju år,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'og sidan sete enkja i heile fire og åtteti år. Ho kom aldri frå templet, og tente Gud i bøn og fasta natt og dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'I denne stundi gjekk ho fram og takka og prisa Gud, og tala um barnet til alle som venta på frelsa for Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Då dei hadde gjort alt som er fyreskrive i Herrens lov, for dei attende til heimstaden sin, Nasaret i Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Og barnet voks, og vart sterkt og fullt av visdom, og Guds nåde var yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'År um anna for foreldri hans til Jerusalem i påskehelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Då han var tolv år, drog dei og dit upp, som skikk og bruk var på høgtidi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'men då dei hadde vore der høgtidsdagarne til endes, og skulde taka på heimvegen, vart Jesus-barnet att i Jerusalem, og foreldri hans gådde det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Dei tenkte han var med i ferdafylgjet, og for ei dagsleid fram, og leita etter honom millom skyldfolk og kjenningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Som dei no ikkje fann honom, for dei attende til Jerusalem, og leita etter honom der;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'og då tri dagar var lidne, fann dei honom i templet; der sat han midt ibland lærarane og lydde på deim og spurde deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'og alle som høyrde på honom, var reint upp i under kor vitug han var, og for svar han gav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Då dei fekk sjå honom, vart dei mest frå seg av undring, og mor hans sagde: «Kvi for du soleis åt mot oss, barn? Far din og eg hev leita so sårt etter deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, '«Kvifor leita de etter meg?» svara han; «visste de ikkje at eg lyt vera i huset åt far min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Men dei skyna ikkje kva han meinte med det ordet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'So fylgde han deim heim til Nasaret, og var lydug mot deim. Men mor hans gøymde alt dette i hjarta sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Og Jesus gjekk fram i visdom og vokster og velvilje hjå Gud og menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'I det femtande styringsåret åt keisar Tiberius, med Pontius Pilatus var landshovding i Judæa, og Herodes fylkeskonge i Galilæa, og Filip, bror hans, fylkeskonge i Ituræa- og Trakonitis-landet, og Lysanias fylkeskonge i Abilene,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'og med Annas og Kajafas var øvsteprestar, kom Guds ord til Johannes, son åt Zakarja, i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Då for han kring i heile Jordan-kverven, og ropa ut umvendingsdåp til forlating for synderne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'som skrive stend i spådomsboki åt Jesaja, profeten: «Høyr han som ropar i heidi: «Rydje vegen for Herren, jamne stigarne hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Kvart djuv skal fyllast, kvart fjell skal lægjast, og kvar ein haug; beint skal det verta det som krokut var, staupute vegen han skal verta slett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'og kvart eit liv Guds frelsa skoda skal.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Som no folket kom ut og vilde få honom til å døypa seg, sagde han til deim: «Orme-ungar, kven lærde dykk å røma frå vreiden som skal koma?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Ber då frukter som høver med umvendingi, og gjev dykk ikkje til å tenkja som so: «Me hev Abraham til far!» for eg segjer dykk at Gud kann vekkja upp born åt Abraham av desse steinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Øksi ligg alt innmed roti på treet; kvart tre som ikkje ber god frukt, vert hogge ned og kasta på elden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, '«Kva skal me då gjera?» spurde folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Han svara deim: «Den som hev tvo trøyor, skal skifta med den som ingi hev, og den som hev mat, skal gjera sameleis.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Det kom og nokre tollmenner som vilde døypast, og sagde: «Meister, kva skal me gjera?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, '«Krev ikkje meir enn de er fyresagde!» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Like eins var det nokre hermenner som spurde honom: «Kva skal då me gjera?» Då svara han: «De skal ikkje plåga folk eller truga pengar utav deim! De skal nøgja dykk med løni dykkar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Men folket gjekk i venting, og alle tenkte um Johannes: «Tru han er Messias?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Då tok han til ords og sagde til alle: «Eg døyper dykk med vatn; men det kjem ein som er sterkare enn eg - eg er ikkje verdig å løysa skobandet hans; han skal døypa dykk med den Heilage Ande og eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Han hev kasteskovli i handi, og skal gjera av låven sin, og samla kornet i stabburet sitt; men agnerne skal han brenna i ein eld som aldri sloknar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Dette og mykje anna lagde han folket på hjarta, og kunngjorde evangeliet åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Men då han tala til Herodes, fylkeskongen, for giftarmålet med Herodias, brorkona hans, og for alt det vonde han hadde gjort,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'so gjorde Herodes det og attpå alt, at han sette Johannes i fengsel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Då no alt folket vart døypt, og Jesus og var døypt, då hende det, med han bad, at himmelen opna seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'og den Heilage Ande dala ned yver honom i duveham, og det kom ei røyst frå himmelen: «Du er son min, som eg elskar; deg hev eg hugnad i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Jesus var um lag tretti år då han stod fram, og var, etter som dei meinte, son åt Josef, son åt Eli,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'son åt Mattat, son åt Levi, son åt Melki, son åt Jannai, son åt Josef,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'son åt Mattatias, son åt Amos, son åt Nahum, son åt Esli, son åt Naggai,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'son åt Ma’at, son åt Mattatias, son åt Sime’i, son åt Josek, son åt Joda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'son åt Johanan, son åt Resa, son åt Zerubbabel, son åt Salatiel, son åt Neri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'son åt Melki, son åt Addi, son åt Kosam, son åt Elmadam, son åt Er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'son åt Josva, son åt Eliezer, son åt Jorim, son åt Mattat, son åt Levi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'son åt Simeon, son åt Juda, son åt Josef, son åt Jonam, son åt Eljakim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'son åt Melea, son åt Menna, son åt Mattata, son åt Natan, son åt David,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'son åt Isai, son åt Obed, son åt Boaz, son åt Salmon, son åt Nahson,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'son åt Amminadab, son åt Ram, son åt Hesron, son åt Peres, son åt Juda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'son åt Jakob, son åt Isak, son åt Abraham, son åt Tarah, son åt Nahor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'son åt Serug, son åt Re’u, son åt Peleg, son åt Eber, son åt Salah,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'son åt Kenan, son åt Arpaksad, son åt Sem, son åt Noah, son åt Lamek,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'son åt Metusalah, son åt Enok, son åt Jared, son åt Malalael, son åt Kenan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'son åt Enos, son åt Set, son åt Adam, Guds son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Full av den Heilage Ande vende Jesus att ifrå Jordan, og Anden dreiv honom kring i øydemarki');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'i fyrti dagar, alt med han vart freista av djevelen. I dei dagarne åt han ingen ting, og då dei var lidne, kjende han seg svolten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Då sagde djevelen til honom: «Er du Guds Son, so seg til denne steinen at han skal verta brød.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Jesus svara honom so: «Det stend skrive: «Menneskja liver ikkje berre av brød, men av kvart eit Guds ord.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'So førde djevelen honom upp på eit høgt fjell, og synte honom alle heimsens rike i ein augneblink,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'og sagde til honom: «Deg vil eg gjeva magt yver alt dette og alt gjævt og gildt som finst i desse riki; for det er lagt i mi hand, og eg gjev det åt kven eg vil;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'fell du no på kne og tilbed meg, so skal det vera ditt alt saman.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Men Jesus svara: «Det stend skrive: «Herren, din Gud, skal du tilbeda; honom og ingen annan skal du tena!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'So førde djevelen honom til Jerusalem, og sette honom ytst på tempeltaket og sagde til honom: «Er du Guds son, so kasta deg ned herifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'For det stend skrive: «Han englarne sine bjoda skal at dei tek vare på deg vel,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'og: «På hender dei deg bera skal, so aldri du på nokon stein skal turva støyta foten din.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Då svara Jesus: «Det er sagt: «Du skal ikkje freista Herren, din Gud.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Då djevelen soleis hadde freista honom på alle vis, gjekk han ifrå honom, og let honom vera i fred ei tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'So for Jesus attende til Galilæa, fyllt av den krafti som Anden gav honom, og ordet um honom kom ut yver alle bygderne der ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Han lærde i synagogorne deira, og alle rosa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Soleis kom han og ein gong til Nasaret, der han var uppalen, og gjekk inn i synagoga på kviledagen, som han var van med; han reiste seg og vilde lesa åt deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'og dei gav honom boki åt profeten Jesaja. Då han slo henne upp, fann han den staden der det stend:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '«Ja, Herrens Ånd er yver meg, for han hev salva meg te bera ut eit fagnadbod åt fatige; sendt hev han meg te ropa ut for fangar fridoms dag og lova blinde augneljoset klårt, te løysa deim som trælka er, or tvang,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Te lysa ut eit hugnads-år frå Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Då han hadde late att boki og gjeve henne til tenaren, sette han seg, og alle som i synagoga var, heldt augo sine feste på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'So tok han til ords og byrja soleis: «I dag hev dette skriftordet sannast, som de sjølve kann høyra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Og alle let vel um honom, og undra seg yver dei ovfagre ordi som kom frå hans munn. «Er’kje dette son åt Josef?» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Då sagde han til deim: «De vil visst segja med meg som det stend i ordtøket: «Lækjar, læk deg sjølv! Me hev høyrt um alt det som er gjort i Kapernaum - gjer no like eins her i fødesheimen din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Men eg segjer dykk for sant,» heldt han fram: «Ingen profet er velkomen i heimbygdi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Og det segjer eg dykk med sannom: Det var mange enkjor i Israel i Elias’ dagar, då himmelen var stengd i tri år og seks månader, so det vart stor svolt og naud i heile landet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'og endå vart’kje Elias send til nokor av deim, men berre til Sarepta i Sidonarlandet, til ei enkja der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Og det var mange spilte i Israel den tid profeten Elisa livde, og endå vart ingen av deim rein att, men berre Na’aman, syraren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Då dei i synagoga høyrde det, vart dei alle brennande harme.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Dei for upp og dreiv honom ut or byen og førde honom burt på bruni av det fjellet som byen deira var bygd på; der vilde dei støyta honom utyver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Men han gjekk midt igjenom flokken og for sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'So kom han ned til Kapernaum, ein by i Galilæa. Der lærde han folket på kviledagen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'og dei var reint tekne av det han lærde deim, for det var magt i talen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'I synagoga var det ein mann som hadde ei urein ånd i seg. Han sette i og ropa so høgt han kunde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '«Hu! Kva vil du oss, Jesus frå Nasaret? Er du komen for å gjera ende på oss? Eg veit kven du er - den Heilage frå Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Jesus truga den vonde åndi og sagde: «Teg still, og far ut or honom!» So kasta åndi honom ned på jordi midt ibland deim og for ut or honom, men skadde honom ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Då kom det ein otte yver alle, og dei sagde seg imillom: «Kva er dette for ord? Med mynd og magt talar han til dei ureine ånderne, og dei fer ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Og det gjekk gjetordet av honom utyver alle bygderne der ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'So tok han ut frå synagoga, og gjekk heim til Simon. Vermor åt Simon låg sjuk og hadde sterke hiteflagor, og dei bad han vilde hjelpa henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Han gjekk innåt, og stod uppyver henne og truga sotti; då slepte sotti henne, og straks reis ho upp og stelte for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Då soli gladde, kom alle til honom med sine sjuke, kva sjukdom dei so drogst med, og han lagde henderne på kvar ein av deim og lækte deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Mange for det og vonde ånder utor, og dei hua og ropa: «Du er Guds son!» Men han truga deim og gav deim ikkje lov til å tala, av di dei visste han var Messias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Då det vart dag, drog han ut og for til ein øydestad. Folket leita etter honom, og då dei kom dit han var, freista dei å halda honom att, so han ikkje skulde ganga frå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Då sagde han til deim: «Eg lyt bera ut fagnadbodet um Guds rike til dei andre byarne og; for det vart eg send for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Og han heldt ved og tala ordet i synagogorne i Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Ein gong stod han nedmed Gennesaretsjøen, og folket trengde seg um honom og lydde på Guds ord;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'då vart han var tvo båtar som låg ved strandi; fiskarane hadde gjenge utor deim og stod og skylde garni sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Han steig ut i ein av båtarne, som høyrde Simon til, og bad honom leggja eit lite stykke frå land; so sette han seg og lærde folket frå båten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Då han hadde halde upp å tala, sagde han til Simon: «Legg ut på djupet og set ut garni dykkar, so de kann få fisk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, '«Meister, me hev stræva i heile natt og ingen ting fenge,» svara Simon; «men på ditt ord vil eg setja ut garni.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'So gjorde dei det, og då stengde dei slik ein brote med fisk at garni heldt på og skulde rivna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Då vitta dei til lagsmennerne sine i hin båten, at dei skulde koma og taka i med deim, og då dei kom, fyllte dei båe båtarne, so det var nære på dei sokk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Då Simon Peter såg det, kasta han seg ned for Jesu føter og sagde: «Gakk burt frå meg, Herre! Eg er ein syndug mann.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'For det kom ein støkk på honom og alle deim som var med honom, for skuld all fisken dei hadde sanka;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'og like eins var det med Jakob og Johannes, sønerne åt Sebedæus, som var lagsbrørne åt Simon. Men Jesus sagde til Simon: «Ver ikkje rædd! Heretter skal du fanga menneskje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'So rodde dei båtarne til lands og gjekk ifrå alt og fylgde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Ein gong som han var i ein av byarne, var det der ein mann som var full av spillsykja; med same han såg Jesus, kasta han seg å gruve og bad: «Herre, dersom du vil, kann du gjera meg rein!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Jesus rette ut handi og tok burtpå honom og sagde: «Eg vil; ver rein!» Og med ein gong gjekk spillsykja av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Jesus sagde til honom at han ikkje måtte segja det med nokon: «Men gakk og te deg for presten, og ber fram offer for reinsingi di, etter det som Moses hev sagt, so du kann vitna for deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Men ordet um honom for berre so mykje vidare utyver, og folk kom i flokk og fylgje og vilde høyra på honom og lækjast for sjukdomarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Sjølv heldt han seg avsides i øydemarkerne og bad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Ein dag heldt han på og lærde folket, og der sat det farisæarar og lovlærarar, som var komne frå kvar grend i Galilæa og Judæa og frå Jerusalem, og Herrens kraft var yver honom og gav honom magt til å lækja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Då kom nokre menner berande med ein som låg i ei seng og var lam; dei vilde bera honom inn og setja honom ned framfyre Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'men såg seg ingi råd til å koma inn med honom for folkestimen. So gjekk dei upp på taket og fira honom med sengi ned millom taksteinarne, midt framfyre Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Då Jesus såg trui deira, sagde han: «Synderne dine er tilgjevne, mann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Då tok dei skriftlærde og farisæarane til å tenkja med seg: «Kva er dette for ein, som talar spottarord mot Gud? Kven kann tilgjeva synder utan ein - Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Men Jesus skyna kva dei tenkte; han tok til ords og sagde til deim: «Kva er det for tankar de hyser i hjarta?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Kva er lettast: å segja: «Synderne dine er tilgjevne!» eller å segja: «Statt upp og gakk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Men so de skal vita at Menneskjesonen hev magt til å tilgjeva synder på jordi, so segjer eg deg» - sagde han til den lame -: «Statt upp, tak sengi di og gakk heim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Og med ein gong stod han upp, midt for augo deira, tok lega si og gjekk heim att, alt med han lova Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Då vart dei alle so tekne at dei var reint frå seg; dei lova Gud og vart fulle av otte og sagde: «I dag hev me set utrulege ting.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'So gjekk han ut att. Då fekk han sjå ein tollmann som heitte Levi; han sat på tollbudi. Jesus sagde til honom: «Fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Då let han alle ting vera og stod upp og fylgde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Levi gjorde eit stort gjestebod for honom i huset sitt; der var det ein heil flokk med tollmenner og andre, som sat til bords med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Og farisæarane og dei skriftlærde som fylgdest med deim, murra og sagde til læresveinarne hans: «Kvifor et og drikk de i lag med tollmenner og syndarar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Då tok Jesus til ords og sagde til deim: «Dei friske treng ikkje lækjar, men det gjer dei som sjuke er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Eg er ikkje komen for å kalla rettferdige, men syndarar til umvending.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'So sagde dei til honom: «Læresveinarne åt Johannes fastar tidt og ofte og held bøn, og det same gjer læresveinarne åt farisæarane, men dine læresveinar et og drikk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Jesus svara: «Kann de få brudlaupsfolket til å fasta med dei hev brudgomen hjå seg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Men det kjem ei tid då brudgomen vert teken ifrå deim; når den tidi kjem, då skal dei fasta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Han sagde deim og ei likning: «Ingen riv eit stykke av ein ny kjole og hev det til bot på ein gamall; for då riv han ikkje berre den nye kjolen sund, men boti som han tok av den nye kjolen, høver ikkje på den gamle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Og ingen hev ny vin på gamle lerflaskor; for då sprengjer den nye vinen flaskorne, og vinen renn ut, og flaskorne forferst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Ny vin lyt ein hava på nye lerflaskor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Og ingen som hev drukke gamall vin, hev hug på ny vin. «Den gamle er best!» segjer han.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Den næstfyrste kviledagen bar det so til at han gjekk gjenom ein åker, og læresveinarne hans reiv av aks og gnudde deim millom henderne og åt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Då sagde nokre av farisæarane: «Kvi gjer de slikt som ingen hev lov til å gjera på kviledagen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Men Jesus tok til ords og sagde til deim: «Hev de då’kje lese kva David gjorde då han og mennerne hans var svoltne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'korleis han gjekk inn i Guds hus og tok skodebrødi og åt, og gav mennerne sine! Og dei brødi hev ingen lov til å eta utan berre prestarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'So sagde han til deim: «Menneskjesonen råder yver kviledagen og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Ein annan kviledag bar det so til at han gjekk inn i synagoga og lærde. Der var det ein mann som den høgre handi hans var nomi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'og dei skriftlærde og farisæarane gjætte på honom, um han vilde lækja på kviledagen, so dei kunde finna noko å klaga honom for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Men han kjende tankarne deira, og sagde til mannen som hadde den nomne handi: «Reis deg upp, og kom fram!» Då reiste han seg upp og gjekk fram,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'og Jesus sagde til deim: «Eg spør dykk: Er det rett å gjera godt på kviledagen eller å gjera vondt, berga liv eller øyda liv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'So såg han rundt ikring på deim alle og sagde til mannen: «Rett fram handi di!» Han so gjorde, og handi hans vart god att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Men dei vart so vonde at dei var reint frå vitet, og tala med kvarandre um kva dei skulde gjera med Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'I dei dagarne hende det, at han gjekk upp i fjellet og vilde beda, og han var der heile natti i bøn til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Då det vart dag, kalla han til seg læresveinarne sine og valde ut tolv; deim kalla han apostlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Det var Simon - honom kalla han og Peter - og Andreas, bror hans, og Jakob, og Johannes, og Filip, og Bartolomæus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'og Mattæus, og Tomas, og Jakob, son åt Alfæus, og Simon, som dei kalla Zelotes,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'og Judas, son åt Jakob, og Judas Iskariot, han som vart svikar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'So gjekk han nedyver i lag med deim, og vart standande på ei sletta. Der var ein heil flokk av læresveinarne hans, og ei stor mengd med folk frå heile Jødeland og Jerusalem og frå sjøbygderne ved Tyrus og Sidon,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'som var komne for å høyra på honom og lækjast for sjukdomarne sine. Då vart dei gode att dei som var plåga av ureine ånder;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'og alt folket freista å koma nær honom, for det gjekk ei kraft ut ifrå honom og lækte alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Då lyfte han upp augo og såg på læresveinarne sine og sagde: «Sæle de som fatige er! Guds rike er dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Sæle de som no svelt! De skal mettast! Sæle de som no græt! De skal koma til å læ!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Sæle er de når folk hatar dykk, og når dei stengjer dykk ute og spottar dykk, og bannlyser namnet dykkar som noko vondt for Menneskjesonen skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Den dagen må de gleda dykk, ja, de må hoppa av gleda; stor er løni som ventar dykk i himmelen; for på same vis for federne deira åt mot profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Men ve yver dykk, de som rike er! De hev alt fenge hugnaden dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ve yver dykk, de som no er mette! De skal koma til å svelta! Ve yver dykk som no lær! De skal syrgja og gråta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Ve, når alle folk talar vel um dykk! For på same vis for federne deira åt med dei falske profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Men åt dykk segjer eg, de som høyrer: «Elska fiendarne dykkar! Gjer vel mot deim som hatar dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Velsigna deim som bannar dykk! Bed for deim som talar ille um dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Slær nokon deg på den eine kinni, so bjod den andre og fram! Tek nokon kjolen din frå deg, so neitta honom ikkje trøya heller!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Gjev kvar som bed deg, og tek nokon det som ditt er, so krev det ikkje att!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Gjer mot anna folk som de vil at dei skal gjera mot dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Um de elskar deim som elskar dykk, kva er det å takka dykk for? syndarane elskar då og deim som deim elskar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Og um de gjer vel mot deim som gjer vel mot dykk, kva er det å takka dykk for? so gjer syndarane og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Og um de låner til deim som de ventar å få att av, kva er det å takka dykk for? syndarane låner og til syndarar på den måten at dei skal få like mykje att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Nei, elska fiendarne dykkar, gjer vel og lån burt, og venta ikkje å få noko att! Då skal løni de fær vera stor, og de skal vera borni åt den Høgste; for han er god mot dei utakksame og vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Ver miskunnsame, som Far dykkar er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Døm ikkje, so skal de ikkje dømast! Fordøm ingen, so skal ingen fordøma dykk! Tilgjev, so skal de få tilgjeving!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Gjev, so skal dei gjeva dykk! Eit godt, stappa, sikka og yverfullt mål skal dei gjeva dykk i fanget. For det målet de mæler med, skal dei mæla att åt dykk med.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Han sagde deim og ei likning: «Kann ein blind leida ein blind? kjem dei’kje båe til å falla i grefti?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Læresveinen er ikkje yver meisteren; men er han heilt utlært, so vert han lik meisteren sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Kvi ser du flisi i auga åt bror din, men bjelken i ditt eige auga vert du ikkje var?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Korleis kann du segja med bror din: «Bror, lat meg taka ut flisi som sit i auga ditt!» du som ikkje ser bjelken i ditt eige auga? Hyklar! Tak fyrst bjelken ut or ditt auga, då kann du sjå å taka flisi ut or auga åt bror din.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'For det finst ikkje noko godt tre som ber låk frukt, ikkje heller noko låkt tre som ber god frukt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'for treet kjenner me på den frukti det ber; ingen kann sanka fikor av tistlar eller plukka druvor av klunger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Ein god mann ber fram berre godt av det gode han gøymer i hjarta sitt, og ein vond mann ber fram berre vondt av det vonde han gøymer på. For frå munnen hans kjem det som hjarta er fullt av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Men kvi kallar de meg «Herre, Herre,» og gjer ikkje det som eg segjer?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Eg skal syna dykk kven han er lik, den som kjem til meg og høyrer ordi mine, og gjer etter deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'han er lik ein mann som vilde byggja seg eit hus, og som grov djupt i tufti og lagde grunnsteinarne på berget. Då det so kom ein flaum, og straumen braut imot huset, vann han ikkje å rikka det, av di det var godt bygt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Men den som høyrer, og ikkje gjer etter det han høyrer, han er lik ein mann som bygde seg eit hus på berre marki, forutan grunnsteinar. Då so straumen braut imot huset, datt det i hop med ein gong, og det vart eit stort fall då det huset datt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'So tala Jesus, og folket lydde på honom; då han hadde tala til endes, gjekk han inn i Kapernaum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Ein hovudsmann hadde ein dreng som låg so sjuk at det leid åt med honom, og den drengen heldt han svært gjæv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Han hadde høyrt um Jesus, og no sende han nokre av rådsmennerne åt jødarne til honom, og bad at vilde koma og berga livet åt drengen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Då dei kom til Jesus, bad dei honom so mykje at han skulde gjera det. «Han er verd at du gjer dette for honom,» sagde dei;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, '«for han elskar folket vårt, og det er han som hev bygt synagoga åt oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jesus gjekk med deim; men då han ikkje hadde langt att til huset, sende hovudsmannen nokre vener til honom med det bodet: «Herre, du skal’kje umaka deg! Eg er for ring til at du skulde stiga inn under taket mitt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'difor heldt eg meg heller ikkje verdig til å koma til deg. Men seg eit ord, so guten min vert god att!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'For eg er og ein mann som må lyda deim som større er, og sjølv hev eg hersveinar under meg, og segjer eg til ein av deim: «Gakk!» so gjeng han, og til ein annan: «Kom!» so kjem han, og til tenaren min: «Gjer det!» so gjer han det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Då Jesus høyrde det, undra han seg yver mannen; han snudde seg, og sagde til folket som fylgde honom: «Det segjer eg dykk: Ikkje ein gong i Israel hev eg funne so stor ei tru.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Då dei som hovudsmannen hadde sendt, kom attende til huset hans, fekk dei sjå at drengen var god att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Snart etter bar det so til at Jesus for til ein by som heiter Nain, og læresveinarne hans og ein stor folkehop var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Då han kom nær innåt byporten, såg han at liket av ein ung mann vart bore ut; det var einaste sonen åt ei enkja; og mykje folk frå byen var med henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Då Herren vart var enkja, tykte han hjarteleg synd um henne og sagde til henne: «Gråt ikkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Han gjekk innåt og tok i båri, og dei som bar, stana. So sagde han: «Unge mann, eg segjer deg: Statt upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Og med ein gong reiste den daude seg upp og tok til å tala, og han gav honom åt mori.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Då vart alle tekne av otte; dei lova Gud og sagde: «Ein stor profet hev stade fram millom oss!» og: «Gud hev vitja sitt folk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Og det ordet um honom kom ut yver heile Jødeland og bygderne ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Alt dette fekk Johannes bod um av læresveinarne sine. Då kalla han tvo av deim til seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'og sende deim til Herren med dei ordi: «Er du den som skal koma, eller lyt me venta ein annan?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Då mennerne kom til Jesus, sagde dei: «Johannes, døyparen, sender oss til deg og spør: «Er du den som skal koma, eller lyt me venta ein annan?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'I same bilet lækte han mange for sjukdomar og plågor og vonde ånder, og mange blinde gav han syni;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'so svara han deim: «Gakk og ber bod til Johannes um det de hev set og høyrt: Blinde fær att syni si, halte gjeng ikring, spilte vert reine, dauve høyrer, daude stend upp att, og fatige fær høyra fagnadbodet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'og sæl er den som ikkje styggjest ved meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Då ærendsveinarne åt Johannes var gjengne, tok Jesus til å tala til folket um Johannes: «Kvi gjekk de ut i øydemarki? Vilde de sjå på ei røyr som svagar att og fram i vinden?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Kvi gjekk de då der ut? Vilde de sjå ein mann som er klædd i fine klæde? Nei, dei som er gildt klædde og liver sine dagar i ovlivnad, dei held til i kongeslotti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Men kvi gjekk de då der ut? Vilde de sjå ein profet? Ja, segjer eg dykk, og det ein som er meir enn profet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Det er um honom det er skrive: «Framfyre deg min ærendsvein eg sender; der du vil fara, skal han vegen rydja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Eg segjer dykk: Det finst ingen større profet millom menneskjeborni enn Johannes; og endå er den minste i Guds rike større enn han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Og alt folket som høyrde honom, tollmennerne med, gav Gud rett og tok imot dåpen åt Johannes;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'men farisæarane og dei lovkunnige gjorde Guds råd til inkjes for seg, og tok ikkje imot dåpen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Kven skal eg då likna folki i denne mannsalderen med? kven er det dei likjest?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Dei likjest borni som sit på torget og ropar til kvarandre: «Me let i fløyta åt dykk, og de dansa ikkje; me song eit syrgjekvæde, og de gret ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'For Johannes døyparen er komen; han et ikkje brød og drikk ikkje vin, og so segjer de: «Han er forgjord!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Menneskjesonen er komen; han et og drikk, og so segjer de: «Sjå for ein etar og drikkar! Han er godvener med tollmenner og syndarar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Men at visdomen hev rett, det hev alle sveinarne hans sanna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Ein av farisæarane bad honom eta hjå seg, og Jesus gjekk heim til honom og sette seg til bords.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'No var det der i byen ei kvinna som hadde livt eit syndefullt liv; då ho fekk vita at han sat til bords hjå farisæaren, kom ho med ei alabaster-krukka full av myrrasalve');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'og sette seg gråtande nedmed føterne hans; so tok ho til å væta føterne hans med tårorne sine, og turka deim med håret sitt; og ho kysste føterne hans og smurde deim med myrrasalven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Då farisæaren som hadde bede honom til seg såg det, tenkte han med seg: «Var denne mannen ein profet, so visste han kva det er for ei kvinna som tek i honom, og kva slag menneskje ho er, at ho er ei syndefull kvinna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Då tok Jesus til ords og sagde til honom: «Simon, det er noko eg vil segja deg!» - «Tala, meister!» sagde han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '«Det var tvo som stod i skuld til ein utlånar; den eine var skuldig hundrad dalar, den andre ti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Men dei hadde ikkje noko å greida for seg med, og so ettergav han deim båe skuldi. Kven av deim vil no elska honom mest?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, '«Eg tenkjer, den som han ettergav mest,» svara Simon. «Du dømde rett,» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'So snudde han seg mot kvinna og sagde til Simon: «Du ser denne kvinna! Eg kom inn i ditt hus - du gav meg ikkje vatn til føterne mine, men ho vætte føterne mine med tåror, og turka deim med håret sitt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'du gav meg ingen kyss, men ho hev halde ved og kysst føterne mine frå den stund eg kom inn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'du salva ikkje hovudet mitt med olje, men ho smurde føterne mine med myrrasalve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'For den skuld segjer eg deg: Tilgjevne er dei mange synderne hennar; difor er det ho elskar so mykje; men den som lite vert tilgjeve, elskar lite.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'So sagde han til henne: «Tilgjevne er synderne dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Dei som sat med til bords, tok til å tenkja med seg: «Kven er han, som jamvel tilgjev synder?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Men han sagde til kvinna: «Trui di hev frelst deg! Gakk heim, og liv sæl.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'I den tidi som no fylgde på, for han kring i landet, frå by til by og frå grend til grend, og tala for folket og bar ut fagnadbodet um Gudsriket. Dei tolv var med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'og like eins nokre kvinnor som hadde vorte lækte for vonde ånder og sjukdomar; det var Maria, Magdalena dei kalla, som sju djevlar hadde fare utor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'og Johanna, kona åt Kuzas, ein av futarne åt Herodes, og Susanna, og mange andre, som var deim til hjelp med det dei hadde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Som det no samla seg mykje folk, og dei kom til honom frå byarne rundt ikring, sagde han i ei likning:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '«Ein såmann gjekk ut og skulde så sædet sitt. Og då han sådde, fall noko frammed vegen og vart nedtrakka, og fuglarne i lufti åt det upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Sumt fall på berg, og då det voks upp, skein det burt, av di det ikkje hadde væta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Sumt fall millom klunger, og klungeren voks med og kjøvde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Sumt fall i god jord, og då det voks upp, gav det grøda i hundrad foll.» Som han sagde det, ropa han: «Høyr etter, kvar som høyra kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Læresveinarne spurde honom kva den likningi skulde tyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Då sagde han: «De fer vita løyndomarne i Guds rike, men dei andre fær høyra deim i likningar, so um dei ser, skal dei’kje sjå, og um dei høyrer, skal dei ikkje håtta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Men likningi er so å tyda: Sædet er Guds ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Dei frammed vegen er dei som høyrer ordet; so kjem djevelen og tek det burt or hjarta deira, so dei ikkje skal tru og verta frelste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Dei på berget er dei som tek imot ordet med gleda når dei høyrer det; men dei hev ikkje rot; dei trur for eit bil, men i freistingsstundi fell dei frå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Det som fall millom klungeren, det er dei som høyrer det, men so gjeng burt og vert kjøvde i suter og rikdom og verdsleg lyst, so dei ikkje ber fullmogi grøda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Men det i den gode jordi, det er dei som høyrer ordet og gøymer det i eit vænt og godt hjarta, og ber grøda i tolmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Ingen kveikjer eit ljos og gøymer det under eit kjer eller set det under ei seng; alle set det i ein stake, so dei som kjem inn, kann sjå ljosken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'For det finst ingen ting som er løynt og ikkje ein gong vert berrsynt, og ingen ting som er dult og ikkje ein gong vert kunnigt og kjem fram i dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Sjå då til korleis de høyrer! For den som hev, han skal få, og den som ikkje hev, skal missa endå det som han tykkjest hava.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Mor hans og brørne hans kom ein gong og vilde finna honom, men kunde ikkje koma innåt honom for folkestimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Då fekk han det bodet: «Mor di og brørne dine stend utanfor og vil sjå deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Han svara: «Mor mi og brørne mine, det er dei som høyrer Guds ord og gjer etter det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Ein dag bar det so til at han steig ut i ein båt. Læresveinarne var med, og han sagde til deim: «Lat oss fara yver til hi sida av vatnet!» So lagde dei utpå,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'og med dei siglde, sovna han. Og det for ein kvervelvind ned på vatnet, so båten gjekk full, og dei var i fåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Då gjekk dei burt til honom og vekte honom og sagde: «Meister, meister, me gjeng under!» Jesus reis upp og aga vinden og bårorne, so dei lagde seg, og det vart blikende stilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'So sagde han til deim: «Kvar er trui dykkar?» Men dei var fulle av otte og undring, og sagde seg imillom: «Kven tru han er, denne mannen som jamvel vindarne og vatnet lyder når han talar til deim?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'So sigla dei fram til Gerasenar-bygdi, som ligg midt imot Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Då han steig i land, kom ein mann frå byen imot honom. Mannen var forgjord; det var vonde ånder i honom. Han hadde ikkje på lenge havt klæde på seg, og bia ikkje i hus, men heldt seg i gravholorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Då han såg Jesus, sette han i og hua; so kasta han seg ned for føterne hans og sagde med høg røyst: «Kva vil du meg, Jesus, son åt den høgste Gud? Eg bed deg at du ikkje vil pina meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'For Jesus sagde til den ureine åndi at ho skulde fara ut or mannen; for ho hadde gripe honom mange vendor - då batt dei honom med lekkjor og fotjarn, og heldt vakt yver honom; men han reiv sund bandi, og den vonde åndi dreiv honom ut i øydemarkerne -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, '«Kva er namnet ditt?» spurde Jesus. «Legion,» svara han; for det hadde fare mange ånder i honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'og dei bad at han ikkje vilde lata deim fara ned i avgrunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'No var det der ein stor flokk med svin som gjekk og beitte i fjellet; so bad ånderne at han vilde gjeva deim lov til å fara inn i svini, og det gav han deim lov til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Då for dei ut or mannen, og for i svini; og heile flokken sette utyver stupet ned i vatnet og druknast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Då gjætarane såg kva som hende, rømde dei, og sagde frå um det i byen og på gardarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Då gjekk folk ut og vilde sjå kva som hendt var. Då dei so kom til Jesus, fekk dei sjå at mannen som dei vonde ånderne hadde fare ut or, sat klædd nedmed føterne hans, og var med sitt fulle vit. Då vart dei forfærde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'og då dei som hadde set det, fortalde korleis den forgjorde hadde vorte berga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'kom heile ålmugen frå bygderne der ikring, Gerasenar-bygderne, og bad at han vilde fara burt ifrå deim; for dei var so tekne av otte. So gjekk han i båten og for attende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Mannen som ånderne hadde fare ut or, bad um han måtte vera hjå honom; men Jesus sende honom frå seg og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '«Gakk heim att, og fortel kor mykje Gud hev gjort for deg.» So gjekk mannen og tala kring i heile byen um alt det Jesus hadde gjort for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Då Jesus kom att, bad folket honom vera velkomen; for alle venta på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Best det var, kom det ein mann som heitte Jairus, og var forstandar for synagoga; han kasta seg ned for Jesu føter og bad honom koma heim til seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'for han hadde ei dotter som var um lag tolv år; ho var einaste barnet hans, og no låg ho og drogst med dauden. Som no Jesus gjekk i veg, trengde folket seg um honom på alle kanter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Millom deim var det ei kvinna som hadde havt blodflod i tolv år; ho hadde øydt heile midelen sin på lækjarar, men ingen hadde vore god til å gjera henne frisk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'ho gjekk innåt honom attantil og tok i ein av duskarne på kjolen hans, og med ein gong stana blodflodi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, '«Kven var det som tok i meg?» spurde Jesus. Alle neitta, og Peter og felagarne hans sagde: «Meister, det er folket som trykkjer og trengjer deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, '«Det var ein som tok i meg,» sagde Jesus; «for eg kjende at det for ei kraft ut ifrå meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Då kvinna såg at det ikkje var dult det ho hadde gjort, kom ho skjelvande og kasta seg ned for honom og fortalde, so heile folket høyrde det, kvifor ho hadde teke i honom, og korleis ho hadde vorte god att med ein einaste gong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Då sagde han til henne: «Trui di hev hjelpt deg, dotter mi. Gakk heim, og liv sæl!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Fyrr han hadde tala ut, kjem det ein frå heimen åt synagoge-forstandaren og segjer: «Dotter di hev slokna. Umaka ikkje meisteren lenger!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Då Jesus høyrde det, tok han til ords og sagde til honom: «Ottast ikkje! Berre tru, so skal ho verta berga!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Då han so kom til huset, let han ingen få ganga inn med seg utan Peter og Johannes og Jakob og far og mor åt barnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Alle gret og jamra yver henne; men han sagde: «Gråt ikkje! Ho hev ikkje slokna; ho søv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Men dei berre log åt honom; for dei visste at ho var slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'So tok han henne i handi og ropa: «Ris upp, barn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Då kom åndi hennar att, og ho reis upp med ein gong; og han sagde med deim at dei skulde gjeva henne mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Foreldri hennar var reint frå seg av gleda. Men han forbaud deim å tala til nokon um det som var hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Jesus kalla i hop dei tolv, og gav deim magt og velde yver alle vonde ånder, og til å lækja sjukdomar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'So sende han deim ut, so dei skulde forkynna Guds rike og gjera sjuke gode att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'og han sagde til deim: «Tak ingen ting med dykk på vegen, ikkje stav, ikkje skreppa, ikkje brød, ikkje pengar! Ikkje heller skal de hava tvo trøyor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Når de kjem inn i eit hus, so ver der, og flytt ikkje ifrå att, fyrr de fer lenger!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Men er det nokon stad dei ikkje vil taka imot dykk, so far burt frå den bygdi, og rist dusti av føterne dykkar! Det skal vera eit vitnemål mot deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'So tok dei ut og for ikring frå grend til grend og forkynte evangeliet, og lækte folk kvar dei kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Herodes, fylkeskongen, fekk høyra um alt det som hende; då visste han ikkje kva han skulde tru; for sume sagde: «Johannes er vekt upp frå dei daude!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'sume: «Elia hev synt seg!» andre: «Ein av dei gamle profetarne hev stade upp att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, '«Johannes hev eg hogge hovudet av,» sagde Herodes; «kva er so dette for ein, som eg høyrer sovore um?» Og han freista å få sjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Då apostlarne kom att, fortalde dei Jesus alt dei hadde gjort. Då tok han deim med seg burt til ein by som heiter Betsaida, og vilde vera åleine med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Men folket fekk vita det og fylgde etter honom; og han tok vel imot deim og tala til deim um Guds rike, og lækte deim som lækjedom trong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Då dagen tok til å halla, gjekk dei tolv fram til honom og sagde: «Send folket frå deg, so dei kann ganga til grenderne og gardarne her ikring og koma i hus og få seg noko til å liva av! For her er me på ein øydestad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, '«Gjev de deim mat!» svara han. «Me hev’kje meir enn fem brødleivar og tvo fiskar,» sagde dei; «eller skal me ganga’stad og kjøpa mat åt alt dette folket?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, '- det var um lag fem tusund mann. Då sagde han til læresveinarne: «Lat deim setja seg ned i bordlag på ikring femti mann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Dei so gjorde, og let alle setja seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'So tok han dei fem brødleivarne og dei tvo fiskarne, og såg upp imot himmelen og velsigna deim, og han braut deim i molar og gav det til læresveinarne, so dei skulde setja det fram for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'So åt dei; og alle vart mette; og då det vart samla upp det som vart att etter deim, var det tolv korger fulle med molar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Ein gong som han var åleine og bad, og læresveinarne var med honom, spurde han deim: «Kven segjer folk at eg er?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, '«Johannes døyparen,» svara dei; «men sume segjer: «Elia,» og sume at ein av dei gamle profetarne hev stade upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, '«Kven segjer då de at eg er?» spurde han. Då tok Peter til ords og sagde: «Guds Messias!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Men det forbaud han deim strengt å tala til nokon um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Og han sagde: «Menneskjesonen lyt lida mykje; styresmennerne og øvsteprestarne og dei skriftlærde kjem til å vanda honom, og han lyt lata livet; men tridje dagen skal han vekkjast upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'So sagde han til alle: «Vil nokon vera i lag med meg, so lyt han gløyma seg sjølv og dag for dag taka krossen sin upp og fylgja etter meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'For den som vil berga livet sitt, skal missa det; men den som misser livet for mi skuld, han skal berga det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Kva gagnar det ein mann, um han vinn heile verdi, men øyder eller taper seg sjølv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, '«For den som skjemmest ved meg og ordi mine, han skal Menneskjesonen skjemmast ved når han kjem i herlegdomen som skin kring honom og Faderen og dei heilage englarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Men det segjer eg dykk med sannom: Det er sume av deim som her stend som ikkje skal smaka dauden fyrr dei fær sjå Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Um lag åtte dagar etter han hadde tala desse ordi, hende det at han tok Peter og Johannes og Jakob med seg og gjekk upp i fjellet og vilde beda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Og medan han bad, fekk andlitet hans ein annan dåm, og klædnaden hans vart kvit og blenkte som ljonet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Og best det var, stod det tvo menner og tala med honom; det var Moses og Elia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'dei synte seg i herlegdom, og tala um hans burtgang, som han skulde fullføra i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Peter og felagarne hans var tunge av svevn; men då dei vakna, såg dei herlegdomen som lyste frå Jesus, og såg dei tvo mennerne som stod innmed honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Då so dei skulde skiljast med honom, sagde Peter til Jesus: «Meister, det er godt me er her! Lat oss gjera tri hyttor, ei åt deg, og ei åt Moses, og ei åt Elia!» - han visste ikkje kva han sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Med han tala soleis, kom det ei sky og skygde yver deim, og dei vart rædde då dei kom inn i skyi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Då kom det ei røyst utor skyi: «Dette er son min, han som eg hev kåra meg ut! Honom skal de høyra på!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Men då røysti kom, var det ingen å sjå utan Jesus. Dei tagde med dette og tala ikkje den gongen til nokon um noko av det dei hadde set.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Dagen etter, då dei var komne ned av fjellet, kom ein stor folkehop imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Best det var, ropa ein mann utor hopen: «Meister, eg bed deg: Sjå til son min; han er einaste barnet mitt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Rett som det er, grip ei ånd honom, og brått set han i og huar; og åndi slit honom til fraudi stend kring munnen på honom; det er med naudi ho vil sleppa guten, og då gjer ho mest ende på honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'eg bad læresveinarne dine at dei vilde driva henne ut; men dei kunde ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Då tok Jesus til ords og sagde: «Å, du vantrune og vrange ætt! Kor lenge skal eg vera hjå dykk og tola dykk? Kom hit med son din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Fyrr guten kunde nå fram til Jesus, reiv åndi og sleit i honom. Men Jesus truga den ureine åndi og gjorde guten god att, og gav honom att åt faren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Og alle var tekne av age og undring yver Guds velde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Med alle var upp i under yver alt det han gjorde, sagde han til læresveinarne sine: «Høyr vel etter desse ordi, og legg deim på minne: Menneskjesonen skal gjevast yver i menneskjehender!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Men dei skyna ikkje det ordet; det var dult for deim, so dei ikkje fekk tak på det, og dei torde ikkje spyrja honom um det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Det kom ein tanke upp i deim um kven av deim som var størst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Men Jesus visste kva tankar dei bar i hjarta; han tok eit lite barn og sette innmed seg');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'og sagde til deim: «Den som tek imot dette barnet for mitt namn skuld, han tek imot meg, og den som tek imot meg, tek imot den som sende meg. For den som er minst av dykk alle, han er stor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Då tok Johannes til ords og sagde: «Meister, me såg ein som dreiv ut vonde ånder i ditt namn, og me forbaud honom det, for di han ikkje er i fylgje med oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, '«De skal ikkje forbjoda det,» svara Jesus; «for den som ikkje er imot dykk, er med dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Då det leid mot den tidi at han skulde takast upp til Gud, vende han augo sine stødt mot Jerusalem; for dit etla han seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Han sende bod fyre seg; men då ærendsveinarne hans kom til ei samaritanar-grend og skulde tinga hus åt honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'vilde folket ikkje taka imot honom, for di han var på veg til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Då Jakob og Johannes, læresveinarne hans, såg det, sagde dei: «Herre, vil du me skal segja at det skal fara eld ned frå himmelen og øyda deim, soleis som Elia gjorde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Då snudde han seg og tala strengt til deim og sagde: «Veit det’kje kva ånd de er av?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Menneskjesonen er ikkje komen for å øyda menneskjeliv, men for å frelsa.» So gjekk dei til ei onnor grend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Med dei for etter vegen, var det ein som sagde til honom: «Eg vil fylgja deg, kvar du so fer!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Jesus svara: Revarne hev hi, og fuglarne i lufti hev reir, men Menneskjesonen hev ingen stad han kann halla sitt hovud nedpå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Til ein annan sagde han: «Fylg meg!» «Herre,» svara han, «lat meg fyrst få ganga heim og jorda far min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, '«Lat dei daude jorda sine daude,» sagde Jesus, «men gakk du i veg og forkynn Guds rike!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Det var ein annan og som sagde: «Eg vil fylgja deg, Herre, men lat meg fyrst få beda farvel med deim som heime er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jesus svara: «Ingen som hev lagt handi på plogen, og so ser attum seg, høver for Guds rike.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Sidan tok Herren ut endå sytti læresveinar og sende deim fyre seg, tvo og tvo til kvar by og bygd som han sjølv skulde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Og han sagde til deim: «Grøda er stor, men onnefolki er få. Bed då honom som eig grøda at han vil senda ut arbeidsfolk til å hausta inn grøda si!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Far no i veg! Eg sender dykk liksom lamb inn i ulveflokken!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ber ikkje med dykk pung eller skreppa eller skor, og gjev dykk ikkje i svall med nokon på vegen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Kvar gong de kjem inn i eit hus, so seg fyrst: «Fred vere med dette huset!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Og dersom det er nokon der som er verd fred, so skal freden dykkar bia hjå honom: dersom ikkje, so skal han venda att til dykk sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Gjev dykk til der i huset, og et og drikk det dei byd dykk! For ein arbeidsmann er verd løni si. Flytt ikkje frå hus til hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Kvar gong de kjem til ein by, og dei tek imot dykk, so et det dei set fram!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Læk dei sjuke der er, og seg til deim: «Guds rike er kome nær dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Men når de kjem til ein by der dei ikkje vil taka imot dykk, so gakk ut på gatorne og seg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '«Jamvel dusti som vart hangande ved føterne våre i byen dykkar, stryk me av oss; her hev de henne att! Men det skal de vita, at Guds rike er kome nær!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Eg segjer dykk: På den siste dag skal det ganga Sodoma likare enn den byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Ve yver deg, Korasin! Ve yver deg, Betsaida! Hadde dei underi som er gjorde i dykk vore gjorde i Tyrus og Sidon, so hadde dei longe vendt um og sete i sekk og oska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Men det skal ganga Tyrus og Sidon likare i domen enn dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Og du, Kapernaum - skal du kann henda lyftast upp til himmelen? nei, til helheimen skal du støytast ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Den som høyrer på dykk, høyrer på meg, og den som vandar dykk, vandar meg; men den som vandar meg, vandar den som sende meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Dei sytti kom glade attende og sagde: «Herre, jamvel dei vonde ånderne lyder oss når me nemner ditt namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Då sagde han til deim: «Eg såg Satan falla ned frå himmelen som eit ljon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Kom i hug: Eg hev gjeve dykk magt til å trøda på ormar og skorpionar og yver alt fiendens velde; og ingen ting skal gjera dykk den minste skade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Men gled dykk ikkje yver det at ånderne lyder dykk, gled dykk heller for di namni dykkar er uppskrivne i himmelen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'I same stundi sagde han, sæl i den Heilage Ande: «Eg lovar deg, Fader, du som råder yver himmel og jord, for di du hev dult dette for dei lærde og kloke, og openberra det åt dei ulærde og barnslege! Ja, Fader; for soleis tykte du det best.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Alt hev far min gjeve i mine hender; og ingen veit kven Sonen er, utan Faderen, og kven Faderen er, utan Sonen og dei som Sonen vil openberra det åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'So vende han seg til læresveinarne sine i ser og sagde: «Sæle dei augo som ser det de ser!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'For eg segjer dykk at mange profetar og kongar var huga til å sjå det de ser, og fekk ikkje sjå det, og høyra det de høyrer, og fekk ikkje høyra det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Då gjekk det fram ein som var kunnig i lovi; han vilde freista Jesus og sagde: «Meister, kva skal eg gjera for å vinna eit æveleg liv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, '«Kva stend det i lovi?» sagde Jesus; «korleis les du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, '«Du skal elska Herren, din Gud, av alt ditt hjarta og med all din hug og med all di magt og med alt ditt vit, og elska grannen din som deg sjølv!» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Då sagde Jesus til honom: «Du svara rett. Gjer det, so skal du liva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Men han vilde orsaka seg og sagde til Jesus: «Kven er då grannen min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jesus tok upp spursmålet og sagde: «Det var ein mann som for frå Jerusalem ned til Jeriko, og fall i henderne på røvarar. Dei klædde honom naken og skamslo honom; so gjekk dei sin veg og let honom liggja der halvdaud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Det høvde so til at ein prest for same vegen; han såg mannen, men for radt framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Like eins ein levit; han kom til same staden og såg honom, men for radt framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Ein samaritan som var ute og ferdast, kom og dit han låg, og såg honom og tykte synd um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Han gjekk burt til honom og fetla såri hans, og helte olje og vin på, lyfte honom so upp på sitt eige asen og førde honom til eit herbyrge, og sytte vel for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Andre morgonen tok han fram tvo mark og gav til gjestgjevaren og sagde: «Syt vel for honom, og det meir du legg ut, skal du få att av meg når eg kjem attende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kven av desse tri tykkjer no du for åt som ein granne mot honom som fall i henderne på røvarane!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, '«Den som gjorde sælebot på honom,» svara den lovkunnige. Då sagde Jesus til honom: «Gakk du av og gjer like eins!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Med dei var på ferdavegen, kom han til ein liten by; der var det ei kvinna som tok imot honom i huset sitt; namnet hennar var Marta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Ho hadde ei syster som heitte Maria, og ho sette seg nedmed Herrens føter og lydde på ordi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Marta hadde det so annsamt med å stella til mykje for honom, at ho ikkje hadde tankar for anna. Ho gjekk fram og sagde: «Herre, bryr du deg ikkje um at syster mi let meg vera åleine um å stella for deg? Seg då med henne at ho skal hjelpa meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Då svara Herren: «Marta, Marta, du gjer deg hugsott og uro med mange ting;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'men det er eitt som trengst! Maria hev valt seg den gode luten, og den skal ikkje takast ifrå henne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Ein gong var han ein stad og bad; då han heldt upp, sagde ein av læresveinarne til honom: «Herre, lær oss å beda! Det lærde Johannes og sveinarne sine.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Han svara: «Når de bed, skal de segja: Fader vår, du som er i himmelen! Lat namnet ditt helgast; lat riket ditt koma; lat viljen din råda på jordi so som i himmelen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'gjev oss kvar dag vårt daglege brød;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'og forlat oss våre synder, for me og forlet kvar den som er oss skuldig; og før oss ikkje ut i freisting; men frels oss frå det vonde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'So sagde han til deim: «Um nokon av dykk hev ein ven, og gjeng til han midt på natti og segjer: «Kjære, lån meg tri brødleivar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'for ein ven hev kome innum meg på ei ferd, og eg hev’kje noko å setja fram åt honom -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'skulde so han der inne svara: «Gjer meg ikkje slikt bry! Døri er longe stengd, og småborni mine er i seng med meg; eg kann ikkje standa upp og gjeva deg det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Eg segjer dykk: Um han ikkje stend upp og gjev honom det for di det er hans ven, so ris han upp og gjev honom alt han treng for di han er so tråsøkjen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Og eg segjer dykk: Bed, so skal de få! Leita, so skal de finna! Banka på, so skal det verta upplate for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'For kvar den som bed, han fær, og den som leitar, han finn, og den som bankar på, vert det upplate for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Finst det nokon far ibland dykk som vilde gjeva son sin ein stein når han bad um brød, eller når han bad um fisk, vilde gjeva honom ein orm i staden for ein fisk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'eller når han bad um eit egg, vilde gjeva honom ein skorpion?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Når då de som er vonde, veit å gjeva borni dykkar gode gåvor, kor mykje meir vil so’kje Faderen frå himmelen gjeva den Heilage Ande åt deim som bed honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Ein gong dreiv han ut ei vond ånd, som var mållaus, og då åndi var utfari, tala den mållause. Folket undra seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'men sume av deim sagde: Det er Be’elsebul, djevelhovdingen, som hjelper honom til å driva ut djevlar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Andre vilde freista honom, og bad honom syna deim eit teikn frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Men Jesus visste kva dei hadde i tankar, og sagde til deim: «Eit rike som ligg i strid med seg sjølv, kjem snart til å øydast, og eitt hus dett yver hitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Er no Satan og komen i strid med seg sjølv, korleis kann då riket hans standa? - sidan de segjer at det er Be’elsebul som hjelper meg til å driva ut djevlar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Og hjelper Be’elsebul meg til å driva ut djevlar, kven fær då dykkar eigne folk hjelp av til å driva deim ut? Difor skal dei vera domarane dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Men er det med Guds finger eg driv djevlarne ut, so er då Guds rike kome til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Når ei kjempa væpna vaktar sin gard, fær han hava alt sitt i fred;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'men kjem det ein sterkare og vinn yver honom, so tek han våpni hans, som han sette si lit til, og skifter ut alt han drog av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Den som ikkje er med meg, er imot meg, og den som ikkje sankar med meg, han spreider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Når den ureine åndi fer ut or eit menneskje, flakkar ho gjenom vatslause vidder og leitar etter ein kvilestad, og når ho ingen kvilestad finn, segjer ho: «Eg vil fara attende til huset mitt, som eg flutte ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Når ho so kjem dit, finn ho huset feia og fjelga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Då fer ho av stad og tek med seg sju andre ånder, som er argare enn ho er sjølv, og dei gjeng inn og vert buande der, og hev det vore ille med det menneskjet fyrr, so vert det endå verre sidan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Medan han tala soleis, var det ei kvinna bland folket som sette i og ropa: «Sælt det livet som bar deg, og det brjostet du saug!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Då sagde han: «Sæle er heller dei som høyrer Guds ord og tek vare på det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Som no folket flokka seg kring honom, tok han til ords og sagde: «Denne ætti er ei vond ætt; dei krev etter teikn, men dei skal’kje få anna teikn enn Jona-teiknet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'For liksom Jona vart eit teikn for Nineve-folket, soleis skal og Menneskjesonen vera det for denne ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Sudlands-dronningi skal standa fram for domen i hop med mennerne av denne ætti og fordøma deim. For ho kom frå verdsens ende og vilde høyra Salomos visdom, og her er meir enn Salomo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Nineve-mennerne skal møta for domen i hop med denne ætti og fordøma deim; for dei vende um då Jona tala for deim, og her er meir enn Jona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Den som kveikjer eit ljos, set det ikkje i kjellaren eller under skjeppa, men i staken, so dei som kjem inn, kann sjå ljosken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Ljoset i likamen, det er auga ditt; når ditt auga er klårt, so er heile din likam og ljos; men er det dimt, so er likamen og myrk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Sjå då til at ikkje ljoset inni deg er myrker!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Er so heile likamen ljos, og ingen lut av honom myrk, då vert han upplyst all igjenom, som når ljoset skin på deg med sine strålar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Då han hadde tala ut, bad ein farisæar honom eta dagverd hjå seg. So gjekk han inn der og sette seg til bords.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Men farisæaren vart forundra då han såg at han ikkje tvo seg fyrst fyre målet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Då sagde Herren til honom: «Ja, de farisæarar, de reinskar skåler og fat utvendes, men innvendes er de fulle av ran og vondskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Dårar! Han som gjorde det som er utvendes, gjorde han’kje det som er innvendes og?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Men gjer ei sælebotsgåva av det som inni er; då skal de sjå at alt er reint for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Men ve yver dykk farisæarar! De gjev tiend av mynta og ruta og allslags urter, men legg ikkje vinn på rettferd og gudselsk! Det skulde ein gjera og ikkje lata vera hitt heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Ve yver dykk farisæarar! De trår etter å sitja fremst i synagogorne, og vil at folk skal helsa dykk på torgi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Ve yver dykk! De er som ukjennelege graver, folk gjeng på deim og veit ikkje av det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Då tok ein av dei lovkunnige til ords og sagde: «Meister, når du segjer slikt, gjeng du oss og for nær!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Jesus svara: «Ve yver dykk lovkunnige og! De lesser svære byrer på folk, og sjølve rører de’kje byrderne med ein einaste finger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Ve yver dykk! De byggjer minnesmerke yver profetarne, og det var federne dykkar som slo deim i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'So vitnar de då um det som federne dykkar gjorde, og samtykkjer det; for dei slo profetarne i hel, og de byggjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Difor sagde og Guds visdom: Eg vil senda profetar og apostlar til deim, og sume av deim skal dei slå i hel, og sume skal dei forfylgja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'so alt profetblod som hev runne frå verdi vart grunnlagd, skal hemnast på denne ætti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'frå Abels blod til Zakarjas’ blod, han som let livet millom altaret og gudshuset. Ja, segjer eg dykk, det skal hemnast på denne ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Ve yver dykk lovkunnige! De hev teke burt kunnskapslykelen! Sjølve gjekk de ikkje inn, og dei som vilde inn, fekk de hindra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Då han gjekk ut att, tok dei skriftlærde og farisæarane til å verta fælt nærsøkne og frega honom um mangt og mykje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'alt med dei lurde på honom og vilde få tak i eitkvart ordet frå hans munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Medan hadde folket samla seg kring han i tusundtal, so dei heldt på å trøda kvarandre ned; då tok han til ords og sagde til læresveinarne sine: «Framum alt; tak dykk i vare for surdeigen åt farisæarane - hyklarskapen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Det finst ingen ting som er duld og ikkje ein gong kjem fram i dagen, og ingen ting som er løynd og ikkje ein gong vert kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Difor skal alt de talar i myrkret, høyrast i ljoset, og det de kviskrar i kammerset, skal ropast ut på taket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Men til dykk som er venerne mine, segjer eg: Ottast ikkje deim som drep likamen, og sidan ikkje hev magt til å gjera meir!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Eg skal syna dykk kven de skal ottast; de skal ottast honom som hev magt til å drepa og sidan kasta i helvite. Ja, segjer eg dykk, honom skal de ottast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Sel dei ikkje fem sporvar for tvo skilling? og ikkje ein av deim er gløymd hjå Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'og jamvel alle håri på hovudet dykkar er talde. Ver ikkje ottefulle! De er meir enn mange sporvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Og det segjer eg dykk: Kvar den som kjennest ved meg for menneski, honom skal og Menneskjesonen kjennast ved for Guds englar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'men den som avneittar meg for menneski, han skal avneittast for Guds englar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Og den som talar mot Menneskjesonen, skal få tilgjeving for det; men den som spottar den Heilage Ande, fær aldri tilgjeving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Når dei no fører dykk fram for synagogorne og deim som styrer og råder i landet, so syt ikkje for korleis de skal svara for dykk, eller kva de skal segja!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'For den Heilage Ande skal læra dykk dei rette ordi i same stundi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Ein utor folkehopen sagde til honom: «Meister, seg til bror min at han skal skifta arven med meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, '«Kven sette meg til domar eller skiftemeister for dykk, mann?» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'So sagde han til deim: «Sjå og tak dykk i vare for all havesykja! For ingen kann tryggja livet sitt med det han eig, um han er aldri so rik.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Og han fortalde deim ei likning: «Det var ein gong ein rik mann; jordi hans hadde bore godt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'og so sagde han med seg: «Kva skal eg gjera? eg hev ikkje husrom til grøda mi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Jau, so vil eg gjera,» sagde han: «eg vil taka ned lødorne mine og byggja deim større, og der vil eg samla heile avlingi og alt godset mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Og so vil eg segja åt meg sjølv: «Du, no hev du mykje godt liggjande for mange år; unn deg no ro, et og drikk, og ver glad!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Men Gud sagde til honom: «Du dåre, i denne natt krev dei sjæli di av deg! Kven skal so hava det du hev sanka i hop?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'So gjeng det den som samlar seg gods og gull, og ikkje er rik i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Difor segjer eg dykk,» sagde han til læresveinarne sine: «Syt ikkje for livet, kva de skal eta, eller for likamen, kva de skal klæda dykk med!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Livet er meir enn maten, og likamen meir enn klædi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Agta på ramnarne! dei sår ikkje og haustar ikkje, dei hev ikkje stabbur og ikkje løda - Gud føder deim. Kor mykje meir er’kje de enn fuglarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Og kven av dykk kann leggja ei aln til si livslengd, um han syter aldri so mykje?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Kann de no ikkje ein gong gjera so mykje, kvi syter de då for det hitt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Agta på liljorne, korleis dei veks! dei korkje spinn eller vev; men eg segjer dykk: Ikkje ein gong Salomo i all sin herlegdom var so klædd som ei av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Klæder no Gud soleis graset på marki, det som stend i dag og vert kasta i omnen i morgon, kor mykje heller vil han då’kje klæda dykk, de fåtruande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'So tenk no’kje de heller allstødt på kva de skal eta, og kva de skal drikka, og lat’kje hugen vanka for vidt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Det er heidningarne kring i verdi som spør etter alt dette; men far dykkar veit at de treng desse ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Søk heller hans rike, so skal de få dette attpå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ottast ikkje, du vesle hjord! Det er far dykkar’s vilje å gjeva dykk riket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Sel det de hev, og gjev sælebotsgåvor! Gjer dykk pungar som ikkje vert utslitne, ein skatt som aldri tryt, i himmelen, der ingen tjuv kjem innåt, og ingen mol øyder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'For der skatten dykkar er, der vil og hjarta dykkar vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Bind livgjordi um dykk, og lat lykterne brenna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Ver de som folk som ventar på herren sin til han bryt upp frå brudlaupet, so dei kann lata upp for honom med same han kjem og bankar på!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Sæle dei tenarar som herren finn vakande når han kjem! Det segjer eg dykk for visst: Han skal binda livgjordi um seg og føra deim til bords, og koma og setja fram for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Anten han kjem midt på natti eller når det lid ut i otta - sæle er dei når han finn det so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Men det skynar de nok, at dersom husbonden visste kva tid og time tjuven kom, so vakte han og let ingen brjota seg inn i huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'So ver reiduge de og! For Menneskjesonen kjem på ei tid de ikkje tenkjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Peter spurde: «Herre, er det åt oss du segjer denne likningi, eller åt alle andre med?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Då sagde Herren: «Ja, kvar er han, den trugne hushaldaren, den vituge som husbonden vil setja yver tenestfolket sitt, so han skal lata deim få kosten sin i rett tid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Sæl den tenar som husbonden finn so gjerande, når han kjem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Det segjer eg dykk for visst: Han skal setja honom yver alt det han eig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Men dersom tenaren segjer med seg: «Herren min drygjer nok endå ei stund,» og han so tek til å slå drengjerne og gjentorne og eta og drikka og fylla seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'då skal herren hans koma ein dag han ikkje ventar, og ein time han ikkje veit av, og hogga honom sund, og lata honom få sin lut i lag med dei utrue.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Den tenaren som veit kva herren hans vil, og ingen ting steller i stand eller gjer av det som han vil, skal få mykje hogg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'men den som ikkje veit det, og gjer det som hogg er verdt, skal få mindre. Av den som mykje hev fenge, ventar ein mykje, og den dei hev trutt mykje til, krev dei so mykje meir av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Eg er komen for å kasta eld utyver jordi, og kor gjerne eg vilde at det alt hadde fata!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Men eg lyt ganga igjenom ein dåp, og kor eg gruvar meg til det er gjort!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Trur de eg er komen for å skapa fred på jordi! Nei, segjer eg dykk, men strid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Heretter skal fem i same huset liggja i strid med kvarandre, tri mot tvo, og tvo mot tri,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'far mot son, og son mot far, mor mot dotter, og dotter mot mor, vermor mot sonekona, og sonekona mot vermor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Til folket og sagde han: «Når de ser det stig sky upp i vest, segjer de straks: «Det kjem regn,» og det vert so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Og ser de vinden blæs ifrå sud, segjer de: «Det vert heitt,» og so vert det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hyklarar! Jord- og himmels-bragdi veit de å granska; korleis hev det seg då at de ikkje veit å granska denne tidi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Og kvi dømer de ikkje frå dykk sjølve kva rett er?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Soleis når du gjeng for retten med motparten din, gjer deg då fyre, so du kann koma tilliks med honom på vegen! Elles dreg han deg gjerne for domaren, og domaren sender deg yver til futen, og futen set deg i fengsel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'du slepp ikkje ut att, segjer eg deg, fyrr du hev greidt alt, til siste skjerv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'På same tidi kom det nokre og fortalde honom dei galilæarane som Pilatus drap med dei bar fram offeret sitt, so blodet deira blanda seg med offerblodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Då tok han til ords og sagde til deim: «Trur de desse galilæarane var større syndarar enn alle andre galilæarar, sidan det gjekk deim soleis?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Nei, segjer eg dykk, men vender de ikkje um, skal de alle umkomast på sovori vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Eller dei attan som Siloatårnet datt nedyver og slo i hel, trur de dei var verre brotsmenner enn alt hitt folket som bur i Jerusalem?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Nei, segjer eg dykk, men vender de ikkje um, skal de alle umkomast på same vis.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'So sagde han denne likningi: «Ein mann hadde eit fiketre, som stod i vingarden hans. Han kom og leita etter frukt på det, men fann ingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Då sagde han til vingardsmannen: «No er det tridje året eg kjem og leitar etter frukt på dette fiketreet og finn ingi. Hogg det ned! Kvi skal det og binda burt jordi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, '«Herre, lat det få standa i år og!» svara vingardsmannen, «til eg fær grave kring det og lagt hævd innåt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'kann henda det ber eit anna år; gjer det’kje det, so fær du hogga det ned!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Ein kviledag lærde Jesus i ei av synagogorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Der var det ei kvinna som hadde havt ei vond ånd i seg i attan år, og den hadde gjort henne so magtlaus at ho var tvikrokut og ikkje på nokor vis kunde halda seg upprett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Då Jesus fekk sjå henne, kalla han henne til seg. «No er du løyst frå vanmagti di, kvinna!» sagde han');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'og lagde henderne på henne; og med ein gong rette ho seg upp, og lova Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Då tok synagoge-forstandaren til ords - han var harm for di Jesus hadde lækt på kviledagen - og sagde til folket: «Det er seks dagar ein lyt arbeida; på deim kann de koma og lata dykk lækja, og ikkje på kviledagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, '«Hyklarar!» svara Herren honom då, «løyser ikkje kvar ein av dykk uksen og asnet sitt av båsen um kviledagen, og leider deim av og vatnar deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Og denne kvinna, som er Abrahams dotter, og som Satan hev halde bundi, tenkje seg til, i attan år, skulde ikkje ho løysast or det bandet, for di um det er kviledag?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Då han sagde det, skjemdest alle dei som stod honom imot, og heile folket gledde seg yver alt det underfulle han gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'So sagde han då: «Kva er Guds rike likt? kva skal eg likna det med?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Det er likt eit senapskorn som ein mann tok og sådde i hagen sin, og det voks og vart til eit tre, og fuglarne i lufti bygde reir i greinerne på det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'So sagde han atter: «Kva skal eg likna Guds rike med?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Det er likt ein surdeig som ei kvinna tok og gøymde i tri skjeppor mjøl til alt saman var syrt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'So for han kring frå by til by og frå grend til grend og lærde folket, alt med han var på veg til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Det var ein som sagde til honom: «Herre, er det få som vert frelste?» Då sagde han til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '«Stræva alt de kann for å koma inn igjenom den tronge døri! Mange, segjer eg dykk, skal freista å koma inn, men er ikkje god til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Når husbonden fyrst hev reist seg og stengt døri, og de so gjev dykk til å standa utanfor og banka på døri og segja: «Herre, lat upp åt oss!» då skal han svara dykk so: «Eg veit ikkje kvar de er ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tek de då på å segja som so: «Me hev ete og drukke i lag med deg, og du lærde i gatorne våre,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'so skal han svara: «Eg segjer dykk: Eg veit ikkje kvar de er ifrå. Hav dykk burt frå meg, alle de som gjorde urett!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Der skal det vera gråt og tanngnistring, når de fær sjå Abraham og Isak og Jakob og alle profetarne i Guds rike, men de sjølve vert kasta ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Og det skal koma folk frå aust og frå vest og frå nord og frå sud og setja seg til bords i Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Men kom i hug at det finst dei som er millom dei siste, og skal vera millom dei fyrste, og det finst dei som er millom dei fyrste og skal vera millom dei siste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'I same bilet kom det nokre farisæarar og sagde med honom: «Tak ut og far herifrå! Herodes tenkjer på å drepa deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Han svara: «Gakk og seg den reven: «I dag og i morgon driv eg ut djevlar og gjer sjuke friske att; tridje dagen er eg til endes komen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'men i dag og i morgon og dagen etter lyt eg ferdast; for det ber aldri til at ein profet let livet annanstad enn i Jerusalem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, du som slær i hel profetarne og steinar deim som er sende til deg, kor ofte vilde eg’kje ha samla borni dine kring meg, liksom fuglemori samlar ungeflokken under vengjerne! Men de vilde ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Sjå no skal de få hava huset dykkar sjølve. Eg segjer dykk: De fær aldri sjå meg fyrr den tidi kjem då de ropar: «Velsigna vere han som kjem i Herrens namn!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Ein kviledag hende det, at Jesus kom heim til ein av dei øvste farisæarane og skulde halda måltid der, og dei gjætte på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Best det var, såg han framfor seg ein mann som hadde vatssotti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Då tok han til ords og spurde dei lovkunnige og farisæarane: «Er det rett å lækja um kviledagen, eller er det ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Dei tagde. Då tok han burt på mannen og lækte honom, og let honom ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Og til dei andre sagde han: «Kven av dykk dreg ikkje straks upp att son sin eller uksen sin, dersom dei dett nedi ein brunn på ein kviledag?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Men dei var’kje god til å svara honom noko på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Då han gådde korleis gjesterne valde seg ut dei øvste sæti, sagde han deim denne likningi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '«Når nokon hev bede deg til brudlaups, so set deg ikkje øvst ved bordet! For det kunde henda at ein gjævare enn du var beden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'og at den som hadde bede dykk båe, kom og sagde til deg: «Gjev rom åt denne mannen!» og då fekk du den skammi at du laut setja deg nedst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Nei, når du er beden ein stad, so gakk og set deg på det nedste romet! Når han so kjem han som hev bede deg, segjer han til deg: «Flytt deg høgre upp, venen min! Då fær du æra hjå alle deim som sit til bords med deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'For kvar den som set seg sjølv høgt, skal gjerast låg, men den som set seg sjølv lågt, skal gjerast høg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'So sagde han og til den som hadde bede honom åt seg: «Når du vil gjera eit middags- eller kveldslag, so bed ikkje venerne eller brørne eller skyldfolket ditt eller rike grannar! For dei kjem til å beda deg att, so du fær lika for det du hev gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Nei, når du gjer gjestebod, so bed fatige, kryplingar, halte, blinde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Då vert du sæl; for dei hev ingen ting å gjeva deg att, men du fær lika for det når dei rettferdige stend upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Ein av dei andre bordgjesterne sagde då han høyrde det: «Sæl den som fær sitja til bords i Guds rike!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Då svara han: «Det var ein gong ein mann som vilde gjera eit stort gjestebod, og bad mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Då tidi kom at gjestebodet skulde vera, sende han sveinen sin i veg for å segja til dei bedne: «Kom! No er det ferdigt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Då tok dei til å beda seg undan, alle som ein. Den fyrste sagde: «Eg hev kjøpt ein jordveg, og er nøydd til å ganga ut og sjå på honom. Du lyt gjera so vel og orsaka meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Ein annan sagde: «Eg hev kjøpt fem par uksar, og no skal eg av og prøva deim. Du lyt gjera so vel og orsaka meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Endå ein annan mann sagde: Eg hev teke meg ei kona; difor kann eg ikkje koma.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Sveinen kom og sagde det med herren sin. Då vart husbonden harm og sagde til sveinen: «Gakk snøgt ut på gatorne og stræti i byen, og før hit alle tiggarar og kryplingar og blinde og halte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Sveinen sagde: «Herre, det er gjort som du sagde, og det er endå rom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, '«Gakk ut på vegarne og ved gjerdi,» svara herren, «og nøyd deim til å koma inn, so huset mitt vert fullt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'For eg segjer dykk at ingen av dei mennerne som vart bedne, skal smaka min gjestebodskost.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Det fylgde mykje folk med honom, og han snudde seg og sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '«Um nokon kjem til meg og hatar ikkje far og mor og kona og born og brør og syster, ja, endå sitt eige liv, so kann han ikkje vera min læresvein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Den som ikkje ber krossen sin og kjem etter meg, kann ikkje vera min læresvein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Vil nokon av dykk byggja eit tårn, tur han’kje då fyrst set seg ned og reknar etter kva det vil kosta, um han hev nok til å fullføra det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'For hev han lagt grunnsteinarne, og ikkje er god til å gjera det ferdigt, so tek alle som ser det til å gjera narr av honom og segja:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '«Den mannen tok til å byggja, og var’kje god til å gjera det ferdigt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Eller um ein konge vil draga ut i strid mot ein annan konge, tru han’kje då fyrst set seg ned og slær yver um han med ti tusund mann kann møta ein som kjem imot han med tjuge tusund?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Og kann han ikkje, so gjer han av ei sendeferd og tingar um fred, med hin endå er langt burte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Soleis kann ingen av dykk vera min læresvein, utan han segjer frå seg alt det han hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Salt er ein god ting; men vert saltet og dove, kva skal so det kryddast med?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Det duger korkje i mold eller møk; dei kastar det ut. Høyr etter, kvar som høyra kann!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Alle tollmenner og syndarar heldt seg nær innåt Jesus og lydde på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Men farisæarane og dei skriftlærde murra og sagde seg imillom: «Den mannen tek imot syndarar, og et i lag med deim!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Då sagde han deim denne likningi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Um ein av dykk hev hundrad sauer og misser ein av deim, let han’kje då dei ni og nitti vera att i beitemarki, og gjeng av og leitar etter den han hev mist, til han finn honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Og når han hev funne honom, er han glad og tek honom på herdarne sine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'og med same han kjem heim, kallar han i hop vener og grannar, og segjer til deim: «Gled dykk med meg! Eg hev funne sauen eg hadde mist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Eg segjer dykk: Soleis er det gleda i himmelen yver ein syndar som vender um, meir enn yver ni og nitti rettferdige som ikkje treng umvending.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Eller um ei kvinna hev ti sylvpeningar, og misser ein av deim, kveikjer ho’kje då ljos og sopar huset og leitar trottugt, til dess ho finn honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Og når ho hev funne honom, kallar ho i hop vener og grannkonor og segjer: «Gled dykk med meg! Eg hev funne peningen eg hadde mist.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Soleis, segjer eg dykk, vert det gleda på Guds englar yver ein syndar som vender um.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'So sagde han: «Det var ein gong ein mann som hadde tvo søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Den yngste av deim sagde til faren: «Far, lat meg få den luten av buet som fell på meg!» So skifte han midelen millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Det var’kje mange dagarne lidne, so samla den yngste sonen alt sitt og for langt burt til eit anna land. Der gav han seg i ulivnad, og øydde upp det han åtte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Då han hadde sett til alt, vart det uår og svolt der i landet, og han tok til å lida naud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'So tydde han seg til ein av mennerne i landet, og han sende honom ut på markerne sine; der skulde han gjæta svin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Og han var huga til å fylla buken sin med skolmerne som svini åt av, og ingen gav honom noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Då gjekk han i seg sjølv og sagde: «Kor mange leigekarar heime hjå far min hev ikkje fullt upp av mat, med eg held på å svelta i hel her!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Eg vil taka i veg og ganga heim til far min og segja til honom: «Far, eg hev synda mot himmelen og mot deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Eg er’kje verd å kallast son din lenger; lat meg få vera som ein av leigekararne dine!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'So tok han i vegen og gjekk heim til far sin. Med han endå var langt burte, vart far hans var honom, og ynkast inderleg; han sprang imot honom og kasta seg um halsen på honom og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Og sonen sagde: «Far, eg hev synda mot himmelen og mot deg; eg er ikkje verd å kallast son din lenger!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Men faren sagde til tenararne sine: «Kom snøgt med ein klædning, den gildaste her er, og hav på honom, og lat han få ring på fingeren og skor på føterne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Henta so den gjødde kalven, og slagta honom, so vil me halda måltid og vera glade!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'For denne sonen min var daud og hev livna upp att, var burtkomen og er attfunnen.» So tok dei til å halda gaman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Den eldste sonen var utpå marki. Då han gjekk heimetter og kom burtimot huset, høyrde han spel og dans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Han ropa på ein av drengjerne, og spurde kva det skulde tyda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, '«Bror din er komen,» svara drengen, «og far din hev slagta den gjødde kalven, for di han fekk honom frisk heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Då vart han harm og vilde ikkje ganga inn. Far hans kom ut og tala blidt til honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'men han svara far sin so: «No hev eg tent deg so mange år og aldri gjort imot ditt ord, og meg hev du aldri gjeve so mykje som eit kid, so eg kunde gleda meg i hop med venerne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Men når han kjem denne son din, som hev ete upp midelen din i lag med skjøkjor, då slagtar du gjødkalven åt honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, '«Du er allstødt hjå meg, barnet mitt,» svara faren, «og alt som mitt er, er ditt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Men no skulde me vera glade og fegne; for denne bror din var daud og hev livna, var burtkomen og er attfunnen!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Han sagde og til læresveinarne: «Det var ein gong ein rik mann som hadde ein hushaldar. Og folk kom til honom og klaga på hushaldaren, og sagde at han øydde burt midelen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Då kalla han hushaldaren fyre seg og sagde til honom: «Kva er det no eg høyrer um deg? Gjer rekneskap for styringi di, for du kann ikkje standa fyre huset mitt lenger!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Hushaldaren tenkte med seg: «Kva skal eg gjera, sidan herren min segjer meg ut or tenesta? Eg orkar ikkje å grava, eg skjemmest ved å tigga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Jau, no veit eg kva eg vil gjera, so dei skal taka meg til seg når eg vert avsett!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'So kalla han skuldmennerne åt herren sin til seg, ein for ein, og sagde til den fyrste: «Kor mykje er du skuldig husbonden min?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, '«Hundrad anker olje,» svara han. «Her hev du skuldbrevet ditt,» sagde hushaldaren; «set deg ned og skriv snøgt: femti!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'So spurde han ein annan: «Enn du, kor mykje er du skuldig?» - «Hundrad tunnor kveite,» svara han. «Her hev du skuldbrevet ditt; skriv: åtteti!» sagde hushaldaren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Og Herren rosa uærlege hushaldaren for di han hadde fare klokt åt. For denne verdsens born er klokare til å stella seg med sine jamlikar enn ljossens born er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Og eg segjer dykk: Vinn dykk vener med den urettferdige Mammon, so dei kann taka imot dykk i dei ævelege heimarne når han tryt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Den som er tru i smått, er og tru i stort, og den som er uærleg i smått, er og uærleg i stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Hev de no ikkje vore true med den urettferdige Mammon, kven vil då tru den rette rikdomen åt dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Og hev de ikkje vore true med det som høyrer andre til, kven vil då gjeva dykk noko de sjølve kann eiga?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Ingen tenar kann tena tvo herrar; for anten vil han hata den eine og elska den andre, eller halda seg til den eine og vanvyrda hin. De kann ikkje tena både Gud og Mammon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Alt dette høyrde farisæarane på, og pengekjære som dei var, frynte dei åt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Då sagde han til deim: «De er dei som fær folk til å tru at de er rettferdige; men Gud kjenner hjarta dykkar; for det som er høgt i folkeaugo, er ein styggedom for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Lovi og profetarne rådde alt til Johannes kom; frå den tid hev fagnadbodet um Guds rike vore kunngjort, og kvar og ein bryt seg inn i det med magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Men det vil lettare henda at himmelen og jordi forgjengst enn at ein einaste prikk i lovi fell burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Kvar den som skil seg frå kona si og giftar seg med ei onnor, gjer hor, og den som gifter seg med ei fråskild, gjer hor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Det var ein gong ein rik mann; han klædde seg i purpur og fint lin, og heldt gaman og fest dag etter dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Og ein fatig mann som heitte Lasarus, låg utmed porten hans, full av verkjesår,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'og stunda etter å få metta seg med det som fall frå bordet åt rikingen; men jamvel hundarne kom og sleikte såri hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'So hende det at den fatige døydde, og englarne bar honom av stad og lagde honom ved Abrahams barm. Den rike døydde og, og vart gravlagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Som han no slo upp augo sine i helheimen, der han låg og pintest, ser han Abraham langt burte, og Lasarus innmed barmen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Då ropa han: «Fader Abraham, gjer sælebot på meg! Send Lasarus so han kann duppa fingertuppen sin i vatn og svala tunga mi! For eg lid fælt i den logen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, '«Kom i hug, min son,» svara Abraham, «at du fekk det gode du ynskte deg i di livetid, og Lasarus like eins det som vondt var. Men no vert han trøysta her, og du lid vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Og attåt alt det er det lagt ein stor avgrunn millom oss og dykk, so dei som vil fara herifrå yver til dykk, dei kann ikkje; ikkje heller kann nokon koma derifrå yver til oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, '«So bed eg deg, fader,» sagde den rike, «at du vil senda han til farshuset mitt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Eg hev fem brør, lat honom vitna for deim, so ikkje dei og skal koma til denne pinslestaden!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, '«Dei hev Moses og profetarne,» svara Abraham; «dei kann høyra på deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, '«Å nei, fader Abraham!» sagde han; «men kjem nokon til deim frå dei daude, so gjer dei bot.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Då sagde Abraham: «Høyrer dei ikkje på Moses og profetarne, so trur dei ikkje heller um nokon stend upp frå dei daude.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Sidan sagde han til læresveinarne sine: «Det er uråd anna enn det lyt koma freistingar, men ve yver den som dei kjem ifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Han var betre faren det låg ein kvernstein um halsen hans og han var kasta i havet, enn at han skulde freista ein av desse små.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Tak dykk i vare! Syndar bror din, so tala til honom, og angrar han, so tilgjev honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Um han syndar mot deg sju gonger um dagen, og sju gonger kjem attende til deg og segjer: «Eg angrar!» so skal du tilgjeva honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Apostlarne sagde til Herren: «Gjev oss meir tru!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, '«Hev de tru som eit senapskorn,» svara Herren, «so kunde de segja til dette morbærtreet: «Rykk deg upp og røt deg i havet!» og det skulde lyda dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Um nokon av dykk hev ein dreng som pløgjer eller gjæter, segjer han då til honom når han kjem heim frå marki: «Kom straks og set deg til bords?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Segjer han’kje heller: «Stell til kveldsmaten åt meg, bind livgjordi um deg, og gakk meg til handa med eg et og drikk! Sidan kann du eta og drikka?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Takkar han vel drengen for di han gjorde som han var fyresagd? Eg trur ikkje det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Soleis de og; når de hev gjort alt som var sagt dykk, so seg: «Me er uturvande tenarar! Me hev’kje gjort anna enn det som var skyldnaden vår.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Med han var på vegen til Jerusalem og for midt imillom Samaria og Galilæa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'bar det so til at han gjekk inn i ein liten by, og der kom det imot han ti menner som hadde spillsykja; dei vart standande eit langt stykke undan,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'og ropa høgt: «Jesus, meister, gjer sælebot på oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Då Jesus vart var deim, sagde han til deim: «Gakk og te dykk fram for prestarne!» Og med dei var på vegen, hende det at dei vart reine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Ein av deim kom attende då han såg han var lækt; han lova Gud med høg røyst,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'og kasta seg å gruve framfor føterne hans og takka honom; det var ein samaritan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Då tok Jesus til ords og sagde: «Vart dei’kje reine alle ti? Kvar er då dei ni?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Var det ingen utan denne framande som kom attende og vilde gjeva Gud æra?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'So sagde han til mannen: «Statt upp og gakk heim att! Trui di hev hjelpt deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Farisæarane spurde honom ein gong når Guds rike skulde koma. Då svara han deim so: «Guds rike kjem ikkje so at ein kann sjå det for augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Ein kann ikkje heller segja: «Sjå her er det!» eller: «Der er det!» For Guds rike, det er inni dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Sidan sagde han til læresveinarne: «Det kjem ei tid då de skal stunda etter å sjå ein av dei dagarne då Menneskjesonen råder, men de skal ikkje få sjå det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Dei kjem til å segja til dykk: «Sjå der er han! Sjå her!» Gakk ikkje der burt, og fylg ikkje etter deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'For liksom ljonet, når det kjem, skin frå himmelbrun til himmelbrun, soleis skal det vera med Menneskjesonen den dagen han kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Men fyrst lyt han lida mykje, og denne ætti skal skjota honom ifrå seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Og som det var i Noahs dagar, so skal det og vera den tidi då Menneskjesonen kjem:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'dei åt, dei drakk, dei gifte seg, dei vart burtgifte, alt til den dagen då Noah gjekk inn i arki; då kom storflodi og tynte alle i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Eller som det var i Lots dagar: dei åt, dei drakk, dei kjøpte, dei selde, dei planta, dei bygde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'men den dagen då Lot tok ut frå Sodoma, regnde det eld og svåvel frå himmelen og tynte deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'På same vis skal det vera den dagen Menneskjesonen syner seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Er nokon den dagen uppå taket og hev sine ting nedi huset, so må han ikkje ganga ned og henta deim; og er nokon utpå marki, so må han ikkje venda um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Kom i hug kona hans Lot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Den som freister å berga livet sitt, skal missa det, og den som misser det, skal vinna det att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Eg segjer dykk: Den natti skal det liggja tvo i ei seng; den eine skal hentast, og hin setjast att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Tvo kvinnor skal mala på same kverni; den eine skal hentast, og hi setjast att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Tvo skal vera utpå marki; den eine skal hentast, og hin setjast att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Då tok læresveinarne til ords og sagde: «Kvar, Herre?» Han svara: «Der liket er, der vil ørnane sankast innåt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Då sagde han deim ei likning um at dei stødt skulde beda og ikkje trøytna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, '«I ein by,» sagde han, «var det ein gong ein domar, som ikkje ottast Gud og ikkje hadde age for noko menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'I same byen var det ei enkja; ho kom jamleg til domaren og sagde: «Hjelp meg, so eg fær rett på motparten min!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Lenge vilde han ikkje, men då det leid på, sagde han med seg: «Endå eg ikkje ottast Gud og ikkje hev age for noko menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'so vil eg like vel hjelpa denne enkja til retten sin, av di ho plågar meg so; elles kjem ho vel til slutt og legg til meg midt i syni!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Høyr kva den urettferdige domaren segjer,» sagde Herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, '«skulde so’kje Gud hjelpa sine utvalde til retten sin, dei som ropar til honom dag og natt, um han so drygjer det ut for deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Eg segjer dykk: Han skal hjelpa deim til retten sin, og det fort. Men når Menneskjesonen kjem, skal han då finna trui på jordi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Til nokre som trudde um seg sjølve at dei var rettferdige, og som vanvyrde alle andre, sagde han denne likningi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '«Det var ein gong tvo menner som gjekk upp i templet og vilde beda; den eine var ein farisæar, og den andre ein tollmann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Farisæaren stelte seg upp for seg sjølv og bad soleis: «Eg takkar deg, Gud, for di eg ikkje er som anna folk, ein røvar, svikar, horkar, eller og som den tollmannen der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Eg fastar tvo gonger i vika, og gjev tiend av alt eg tek inn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Tollmannen stod langt undan; han vilde ikkje ein gong lyfta augo mot himmelen, men slo seg for bringa og sagde: Å Gud, ver meg syndaren nådig!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Eg segjer dykk: Han var rettferdiggjord då han gjekk heim til sitt hus, men hin ikkje; for kvar den som set seg sjølv høgt, skal gjerast låg, men den som set seg sjølv lågt, skal gjerast høg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Dei bar og småborni sine til honom, so han skulde røra ved deim. Då læresveinarne såg det, truga dei deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'men Jesus kalla deim til seg og sagde: «Lat småborni koma til meg, og hindra deim ikkje! For Guds rike høyrer slike til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Det segjer eg dykk for sant: Den som ikkje tek imot Guds rike som eit lite barn, skal på ingen måte koma inn i det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Ein synagoge-forstandar spurde honom: «Gode meister, kva skal eg gjera so eg kann vinna eit ævelegt liv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, '«Kvi kallar du meg god?» sagde Jesus. «Ingen er god utan ein - Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Du kjenner bodi: «Du skal ikkje gjera hor! Du skal ikkje drepa! Du skal ikkje stela! Du skal ikkje vitna rangt! Du skal æra far din og mor di!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, '«Alt det hev eg halde frå eg var ung,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Då Jesus høyrde det sagde han: «Eitt vantar deg endå: sel alt det du hev, og byt det ut åt dei fatige, so fær du ein skatt i himmelen! Og kom so og fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mannen vart sturen då han høyrde dei ordi; for han var svært rik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Jesus såg det på honom og sagde: «Kor vandt det er for dei som hev gods og gull å koma inn i Guds rike!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Ja, ein kamel kjem lettare gjenom eit nålauga enn ein rik kjem inn i Guds rike.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, '«Kven kann då verta frelst?» sagde dei som høyrde på det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Han svara: «Det som er umogelegt for menneskje, er mogelegt for Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, '«Enn me som hev skilt oss med alt som var vårt og fylgt deg!» sagde Peter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Då sagde han til deim: «Det segjer eg dykk for sant: Det er ingen som hev skilt seg med hus eller kona eller brør eller foreldre eller born for Gudsriket skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'utan han skal få det att mangdubbelt i denne tidi, og i den verdi som kjem eit ævelegt liv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'So kalla han dei tolv innåt seg og sagde til deim: «No fer me upp til Jerusalem, og alt det som profetarne hev skrive um Menneskjesonen, skal ganga fram:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Han gjevast yver til heidningarne og spottast, og farast ille med og sputtast på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'og dei skal hudfletta honom og slå honom i hel, og tridje dagen skal han standa upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Men dei forstod ikkje noko av dette; det var dult for deim kva som låg i det ordet, og dei skyna ikkje det han sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Då han no kom burtimot Jeriko, sat ein blind mann attmed vegen og bad seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Då han høyrde det for so mykje folk fram igjenom, spurde han kva var tids.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Dei fortalde honom at Jesus frå Nasaret for framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Då ropa han: «Jesus, Davids son, gjer sælebot på meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Dei som gjekk fyre, skjente på honom og sagde han skulde tegja; men han ropa berre endå meir: «Davids son, gjer sælebot på meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Då stana Jesus og sagde at dei skulde leida den blinde hit til honom, og då han kom innåt, spurde han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '«Kva vil du eg skal gjera for deg?» - «Herre, lat meg få att syni mi!» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, '«No fær du att syni! Trui di hev hjelpt deg,» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Og straks fekk han att syni si og fylgde honom alt med han lova Gud; og alt folket som såg det, gav Gud æra og pris.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'So kom han til Jeriko, og for fram igjenom byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Der var det ein mann som heitte Sakkæus; han var ein høg tollmann og rik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Han hadde slik hug til å sjå Jesus, kven han var, men kunde ikkje koma til for folkemengdi; for han var liten på vokster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'So sprang han i fyrevegen og kleiv upp i eit sykomortre, so han kunde få sjå honom; for der laut han koma framum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Då Jesus kom dit, såg han upp og sagde til honom: «Sakkæus, skunda deg og kom ned! I dag lyt eg vera hjå deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Då skunda han seg ned, og tok imot Jesus med gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Alle som såg det, murra og sagde seg imillom: «Han gjeng inn til ein syndig mann og tek herbyrge der.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Men Sakkæus steig fram og sagde til Herren: «Herre, helvti av alt det eg eig, gjev eg dei fatige, og hev eg truga pengar frå nokon, gjev eg det att firdubbelt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Og Jesus sagde um honom: «I dag hev det timst dette huset å få frelsa, etter di han og er Abrahams son;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'for Menneskjesonen er komen for å leita etter det som var fortapt, og frelsa det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Med dei lydde på det, heldt han ved og fortalde ei likning, av di han var so nær Jerusalem, og dei tenkte at Guds rike skulde koma til synes straks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Han sagde: «Det var ein gong ein høgætta mann, som for langt burt til eit anna land og vilde få seg kongedøme og so venda heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Då kalla han åt seg ti av tenarane sine og gav deim ti pund og sagde: «Driv no handel med dette med eg er burte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Men landsmennerne hans hata honom og skikka sendemenner av stad etter honom, som skulde segja: «Me vil ikkje at den mannen skal vera kongen vår!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Då han no kom att og hadde fenge kongedømet, sagde han at dei tenarane han hadde gjeve pengarne til, skulde ropast inn til honom, so han kunde få vita kor mykje dei hadde tent.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Då gjekk den fyrste fram og sagde: «Herre, pundet ditt hev gjeve av seg ti pund.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, '«Det var rett, du gode tenar!» svara herren; «for di du hev vore tru med det som lite var, skal du hava velde yver ti byar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'So kom den andre og sagde: «Pundet ditt, herre, hev lagt inn fem pund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Til honom sagde herren: «Du skal råda yver fem byar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'So kom det ein annan og sagde: «Herre, sjå her er pundet ditt! Eg hev havt det liggjande i eit knyte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'for eg var rædd deg, av di du er ein streng mann: du tek inn det du ikkje lagde ut, og haustar det du ikkje sådde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Då sagde herren: «Etter dine eigne ord dømer eg deg, du låke tenar! Du visste at eg er ein streng mann, som tek inn det eg ikkje lagde ut, og haustar det eg ikkje sådde?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Kvi sette du då ikkje pengarne mine i banken? so hadde eg fenge deim att med rentor når eg kom heim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Tak pundet frå honom!» sagde han til deim som stod innmed, og gjev det til den som hev ti pund!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '«Herre, han hev då ti pund!» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '«Eg segjer dykk at kvar den som hev, skal få, og den som ikkje hev, skal missa endå det som han hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Men desse uvenerne mine, som ikkje vilde at eg skulde vera kongen deira, deim skal de føra hit og hogga deim ned for augo mine!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Då han hadde sagt det, gjekk han fyre på ferdi upp til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Som han no kom burtimot Betfage og Betania, til det berget dei kallar Oljeberget, sende han tvo av læresveinarne i veg og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, '«Gakk burt i den grendi som ligg midt imot oss! Når de kjem der, finn de ein fole som stend bunden, og som det aldri hev sete menneskje på; den skal de løysa og leida hit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Og dersom nokon spør dykk kvi de løyser honom, skal de svara so: «Herren treng um honom.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Dei som var sende, gjekk, og fann det so som han hadde sagt med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Då dei so løyste folen, sagde dei som åtte honom: «Kvi løyser de folen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, '«Herren treng um honom,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'So leidde dei folen fram til Jesus, og lagde kjolarne sine på honom, og let Jesus setja seg uppå;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'og med han for frametter, breidde dei klædi sine under på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Som han no var tett burtmed der det ber ned frå Oljeberget, tok læresveinarne, heile flokken, glade som dei var, til å lova Gud med høg røyst for alle dei underi dei hadde set, og kvad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, '«Velsigna vere kongen som kjem i Herrens namn! Fred i himmelen og æra i det høgste!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Nokre farisæarar som var med i folkehopen, sagde til han: «Meister, tala til læresveinarne dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Då svara han: «Eg segjer dykk: Dersom desse tegjer, so skal steinarne ropa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Då han kom næmare og såg byen, gret han yver honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '«Hadde du berre visst, um ikkje fyrr enn i dag, kva som tener til di velferd! Men no er det dult for augo dine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'For det skal koma ei tid for deg då fiendarne kastar upp ein voll um deg og kringset deg og trengjer deg frå alle kantar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'og støyter deg ned i grunnen, og borni dine med deg, og ikkje let det liggja att stein på stein i deg, for di du ikkje skyna di gjestings tid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Då han kom inn i templet, tok han til å driva ut deim som handla der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'og sagde til deim: «Det stend skrive: «Mitt hus skal vera eit bønehus,» men de hev gjort det til eit røvarbol.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Sidan lærde han dagstødt i templet. Øvsteprestarne og dei skriftlærde var trådde etter å få rudt honom or vegen, og so gjorde dei fyrste mennerne i folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'men dei kunde ikkje finna ut korleis dei skulde bera seg åt med det; for heile folket hekk ved honom og lydde på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Som han no ein dag lærde folket i templet og bar fram fagnadbodet, steig øvsteprestarne og dei skriftlærde upp, i hop med styresmennerne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'og dei tala soleis til honom: «Seg oss: Kva rett hev du til å gjera dette, eller kven var det som gav deg retten?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, '«Eg vil og spyrja dykk um ein ting,» svara han: «Seg de meg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Var dåpen åt Johannes frå himmelen, eller var det menneskjeverk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Då slo dei yver med seg sjølve og sagde: «Svarar me: «Frå himmelen,» so segjer han: «Kvi trudde de honom ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'og svarar me: «Det var menneskjeverk,» so kjem heile folket til å steina oss i hel; for dei trur fullt og fast at Johannes var ein profet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'So svara dei at dei visste ikkje kvar Johannes-dåpen var ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, '«Då segjer ikkje eg dykk heller kva rett eg hev til å gjera dette,» sagde Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'So tok han til å tala til folket og sagde deim ei likning: «Det var ein gong ein mann som stelte til ein vingard; den leigde han burt til brukarar, og so for han utanlands og vart burte i lang æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Då rette tidi kom, sende han ein av sveinarne sine til brukarane, og kravde at dei skulde gjeva honom noko av det som var avla i vingarden. Men brukarane slo sveinen og sende honom burt att med tome hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'So sende han atter ein annan svein; den slo dei og, og hædde honom og sende honom burt att med henderne tome.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Og endå ein tridje sende han; den for dei like eins med, slo honom til blods og kasta honom ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, '«Kva skal eg no gjera?» sagde han som åtte vingarden. «Eg vil senda son min, han som eg elskar so høgt; kann henda dei hev age for honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Men då brukarane fekk sjå honom, lagde dei yver med kvarandre og sagde: «Dette er ervingen! Lat oss slå han i hel, so me kann få arven!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'So kasta dei honom ut or vingarden og slo honom i hel. Kva skal no vingardseigaren gjera med deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Han skal koma og gjera ende på desse brukarane og lata andre få vingarden.» Då dei høyrde det, sagde dei: «Slikt må aldri henda!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Då såg han på deim og sagde: «Kva tyder då dette ordet i skrifti: «Den steinen byggjarane vanda, den var det som vart hyrnestein?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Kvar den som fell på den steinen, skal slå seg sund; men den som steinen fell på, skal han smuldra til dust.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Dei skriftlærde og øvsteprestarne vilde ha lagt hand på honom i same stund, men dei torde ikkje for folket; dei skyna at det var deim han meinte med likningi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'So gjætte dei på honom og sende folk ut som skulde lura på honom og låst vera lovlydige, so dei kunde fanga honom i ord, og so gjeva honom yver til styremagti og i henderne på landshovdingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Dei sette fram eit spursmål for honom og sagde: «Meister, me veit at du talar og lærer rett og ikkje gjer skil på folk, men lærer Guds veg etter sanningi -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'er det rett at me legg skatt til keisaren, eller er det ikkje?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Men han gådde listi deira og sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '«Syn meg ein sylvmynt! Kva bilæte og namn er det han hev?» «Det er keisarens,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, '«Vel,» sagde han til deim, «gjev so keisaren det som keisarens er, og Gud det som Guds er!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Soleis kunde dei ikkje fanga honom i noko ord so folket var vitne på det; dei undra seg berre yver svaret hans og tagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'So kom det nokre sadducæarar - det er dei som neittar at dei daude skal standa upp att - dei og sette fram eit spursmål for honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '«Meister, Moses hev skrive den lovi åt oss, at når ein gift mann døyr barnlaus, so skal bror hans gifta seg med enkja og halda uppe ætti åt bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'No var det ein gong sju brør. Den fyrste tok seg ei kona, men døydde barnlaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'So gifte den andre seg med henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'og so den tridje, og sameleis alle sju; dei døydde og hadde ikkje born etter seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Til slutt døydde kona og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Kven av deim skal no den kona høyra til i eit anna liv? For alle sju hev havt henne til kona.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Jesus svara: «Dei som liver her i verdi, dei gifter seg og vert burtgifte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'men dei som vert haldne verdige til å nå hi verdi og standa upp att frå dei daude, dei korkje gifter seg eller vert burtgifte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'dei kann heller ikkje døy meir; for dei er liksom englarne og er Guds born, av di dei hev stade upp att til eit nytt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Men at dei avlidne skal vekkjast upp att, det hev Moses og synt i soga um klungeren, der han kallar Herren Abrahams Gud og Isaks Gud og Jakobs Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Og han er ikkje Gud for dei daude, men for dei livande; for alle er livande for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Då tok nokre skriftlærde til ords og sagde: «No tala du vel, meister.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Og dei torde ikkje oftare spyrja honom um noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'So sagde han til deim: «Korleis kann dei segja at Messias er Davids son?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'David segjer då sjølv i Salmeboki: «Herren sagde til herren min: «Sit ved høgre handi mi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'til eg dine fiendar fær til fotbenk for deg lagt!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'So kallar no David honom herre; korleis kann han då vera son hans?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Sidan tala han til læresveinarne og sagde so heile folket høyrde det:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '«Agta dykk for dei skriftlærde som likar å ganga ikring i side kjolar og gjerne vil helsast torgi og hava dei fremste sessarne i synagogorne og dei høgste sæti i gjestebod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'dei som et upp huset for enkjor og for ei syn skuld held lange bøner. Dei skal få so mykje strengare dom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Då han såg upp, vart han var at dei rike lagde gåvorne sine i templekista;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'og han vart var ei armodsleg enkja, som lagde tvo skjervar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Då sagde han: «Det segjer eg dykk for sant: Denne fatige enkja hev lagt meir enn dei alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'For det som desse gav, det gav dei alle av nøgdi si; men ho gav av si fatige råd - gav alt ho hadde til å livberga seg med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Det var nokre som tala um templet, at det var prydt med fagre steinar og vigde gåvor. Då sagde han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '«Dette som de skodar, um det skal de vita at det vil koma ei tid då her ikkje vert liggjande stein på stein, som ikkje skal rivast laus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, '«Når skal då dette ganga fyre seg, meister,» spurde dei, «og kva er merket på at den tidi lid nær?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Då svara han: Sjå dykk fyre, so ingen fær ført dykk på villstig! For mange skal taka mitt namn og segja: «Det er eg!» og: «Det lid innpå tidi. Fylg ikkje etter deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Og når de høyrer um ufred og upprør, so vert ikkje fælne! For fyrst lyt det henda; men enden kjem ikkje straks.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'So sagde han til deim: «Folk skal reisa seg imot folk, og rike mot rike;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'store jordskjelvar skal koma, og uår og sott kring i landi; og det skal syna seg skræmor og store teikn frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Men fyrr alt dette hender, skal dei leggja hand på dykk og forfylgja dykk og draga dykk inn i synagogor og fangehus; og de skal førast fram for kongar og landshovdingar for mitt namn skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Då skal de koma til å vitna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Legg dykk då på minne at de ikkje fyreåt tarv tenkja på korleis de skal svara for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Eg skal gjeva dykk munn og visdom, som ingen av motmennerne dykkar skal kunna standa seg for eller segja imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Jamvel foreldre og brør og skyldfolk og vener skal svika dykk og valda sume av dykk dauden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'og alle skal hata dykk for mitt namn skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Men ikkje eit hår på hovudet dykkar skal forkomast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Haldt ut, so skal de vinna sjælerne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Når de ser at stridsherar kringset Jerusalem, då skal de vita at det ikkje er lenge fyrr han vert lagd i øyde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Då lyt dei som er i Judaland røma til fjells; dei som er inni byen, lyt flytja ut, og dei som er utpå landet, må ikkje koma inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'For dette er hemnardagarne; då skal det ganga fram alt det som stend skrive.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Stakkars deim som gjeng med barn eller gjev brjost, i dei dagarne! For det skal vera stor naud i landet og vreide yver dette folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Dei skal falla for sverdseggi og førast hertekne burt til alle heidningfolk, og Jerusalem skal heidningarne trøda under fot, til heidningtidi er ute.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Det skal syna seg teikn i sol og måne og stjernor, og på jordi skal folki fælast i vonløysa, når havet og brotsjøarne dyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Folk skal uvita av rædsla og gru for det som kjem yver mannaheimen; for himmelkrafterne skal skakast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Då skal dei sjå Menneskjesonen koma i skyi med velde og stor herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Men når dette tek til å henda, då rett dykk upp, og lyft hovudet! for det lid mot utløysingi dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'So sagde han deim ei likning: «Sjå på fiketreet og alle andre tre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'So snart de ser dei hev sprotte, då veit de av dykk sjølve at no er sumaren nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Soleis når de ser dette hender, då veit de at Guds rike er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Det segjer eg dykk for visst: Denne ætti skal ikkje forgangast fyrr alt saman hev hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Himmel og jord skal forgangast, men mine ord skal aldri forgangast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Gjev agt på dykk sjølve, at de aldri let hjarta tyngjast av rus og ovdrykk og verdsleg sut, so den dagen kjem uventande på dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'For som eit fuglenet skal han skal koma yver alle som bur kring i vidande verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Vak kvar tid og stund, og bed at de kann få styrk til å røma undan alt dette som koma skal, og standa dykk framfor Menneskjesonen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Um dagarne lærde han i templet; men um kveldarne gjekk han ut or byen og var natti yver på den åsen dei kallar Oljeberget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Og alt folket kom tidleg um morgonen til honom i templet og lydde på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'No leid det nær innåt søtebrødhelgi, som dei kallar påske.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Og øvsteprestarne og dei skriftlærde grunda på korleis dei skulde bera seg åt for å få rudt honom or vegen; for dei var rædde folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Då for Satan i Judas, han som dei kalla Iskariot, og som var ein av dei tolv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'han gjekk av stad og tala med øvsteprestarne og hovdingarne for tempelvakti um korleis han skulde få gjeve Jesus yver til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Dei vart glade og lova honom pengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Han slo til, og sidan leita han etter eit laglegt høve til å gjeva han yver til deim utan uppstyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'So kom søtebrødsdagen, den dagen då påskelambet skulde slagtast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Då sende han Peter og Johannes i veg og sagde: «Gakk av stad og stell til påskemålet åt oss, so me kann halda måltid!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, '«Kvar vil du me skal stella det til?» spurde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, '«Høyr her!» svara han; «når de kjem inn i byen, møter de ein mann som ber ei krukka med vatn. Honom skal de fylgja til han gjeng inn i eit hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'og so skal de segja til huseigaren: «Meisteren helsar: Kvar er romet der eg kann halda påskemåltid med læresveinarne mine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Då syner han dykk ein stor sal med duka bord. Der skal de stella til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'So gjekk dei, og fann det so som han hadde sagt, og dei stelte til påskemålet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Då tidi kom, sette han seg til bords, og apostlarne med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Og han sagde til deim: Eg hev lengta so etter å eta dette påskemålet i lag med dykk, fyrr eg skal lida;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'for eg segjer dykk: Eg kjem aldri til å eta det meir, fyrr det hev fenge fullnaden sin i Guds rike.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'So tok han ein kalk i handi, og takka og sagde: «Tak dette og skift det imillom dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'For eg segjer dykk: Heretter skal eg aldri drikka av druvesafti fyrr Guds rike er kome.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Og han tok brødet, takka, og braut det, og gav deim og sagde: «Dette er likamen min, som vert gjeven for dykk! Gjer dette til minne um meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Like eins kalken etter dei hadde ete kveldverden, og sagde: «Denne kalken er den nye pakt i blodet mitt, det som renn for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Men sjå: svikaren held handi si framyver bordet med meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Menneskjesonen gjeng fulla burt; for so er det laga. Men ve yver den mannen som veld at han vert gjeven i fiendehand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Då tok dei til å dryfta seg imillom kven av deim det kunde vera som skulde koma til å gjera dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Det vart og ein ordstrid millom deim um kven av deim som skulde gjelda for den største.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Då sagde han til deim: «Kongarne råder yver folki sine, og dei som held deim i age, vert kalla velgjerdsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'So må det ikkje vera med dykk; men den som er største ibland dykk, skal vera som han var yngst, og styraren som han var tenar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'For kven er størst, den som sit til bords, eller den som ber på bordet? Er det’kje den som sit til bords? Men eg er berre som ein bordsvein ibland dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'De er dei som heldt ut hjå meg i røyningarne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'og eg eignar dykk kongedøme, liksom far min eigna meg det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'de skal eta og drikka ved bordet mitt i mitt rike, og sitja i kvar sitt høgsæte og styra dei tolv Israels-ætterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simon, Simon, høyr kva eg segjer: Satan kravde å få sælda dykk liksom korn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Men eg hev bede for deg at trui di ikkje må trjota, og når du ein gong vender um, so styrk brørne dine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, '«Herre,» sagde Peter, «med deg gjeng eg gjerne både i fangehus og i dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, '«Eg segjer deg, Peter,» svara Herren: «Hanen gjel ikkje i natt, fyrr du tri gonger hev neitta at du kjenner meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'So sagde han til deim: «Då eg sende dykk i veg forutan pung og skreppa og skor, vanta de då nokon ting?» «Ingen ting,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, '«Men no lyt den som hev pung taka honom med,» sagde han, «og like eins den som hev skreppa, og den som ikkje hev noko sverd, lyt selja kjolen sin og kjøpa seg eit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'For eg segjer dykk at på meg lyt det sannast det ordet som stend skrive: «Og han vart rekna millom brotsmenner.» For med meg lid det mot enden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, '«Herre,» sagde dei, «sjå her er tvo sverd.» «Det er nok,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'So gjekk han ut og tok vegen til Oljeberget, som han var van ved; og læresveinarne fylgde og med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Då han var komen dit, sagde han til deim: «Bed at de ikkje må koma i freisting!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Han drog seg ifrå deim so langt som eit steinkast og lagde seg på kne og bad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, '«Fader, um du vilde taka denne skåli ifrå meg! Men lat det ikkje vera som eg vil, berre som du vil!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Ein engel frå himmelen synte seg for honom og styrkte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Og i si såre hjartekvida bad han endå heitare, og sveiten hans vart som blodsdråpar, som fall ned på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'So reiste han seg frå bøni. Då han kom til læresveinarne, såg han at dei hadde sovna av sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Då sagde han til deim: «Kvi søv de? Statt upp, og bed at de ikkje må koma i freisting!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Fyrr han hadde tala ut, fekk han sjå ein flokk som kom; han som heitte Judas - ein av dei tolv - gjekk fyre deim og kom burtåt Jesus, vilde kyssa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Då sagde Jesus til honom: «Judas, svik du Menneskjesonen med ein kyss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Då dei som var ikring honom såg korleis det bar i veg, sagde dei: «Herre, skal me slå til med sverdet?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Og ein av deim hogg til tenaren åt øvstepresten, og sneidde av honom det høgre øyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Då tok Jesus til ords og sagde: «Lat det vera nok med det!» Og han tok burtpå øyra hans og lækte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'So sagde han til deim som var komne og skulde taka honom, øvsteprestarne og tempelhovdingarne og styresmennerne: «De kjem med sverd og stavar som eg skulde vera ein røvar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Den tid eg var saman med dykk i templet dag etter dag, då baud de’kje til å gripa meg. Men no er det dykkar time, no er det myrkret som råder.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'So tok dei honom og førde honom burt og inn i garden åt øvstepresten; og Peter fylgde eit langt stykke etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Dei hadde gjort upp ein eld midt i gardsromet og sett seg ikring, og Peter sette seg midt ibland deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Med han sat der i ljoset, vart ei tenestgjenta var honom; ho stirde på honom og sagde: «Denne var og med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Men han neitta og sagde: «Eg kjenner honom ikkje, kvinna!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Eit lite bil etter vart ein annan var honom og sagde: «Du er og ein av deim!» «Nei, mann, det er eg ikkje!» svara Peter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Då um lag ein time var liden, var det ein til som sanna det og sagde: «Jau visst var denne og med honom; han er då ein galilæar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, '«Eg veit’kje kva du talar um, mann!» sagde Peter. Og straks, fyrr han hadde tala ut, gol hanen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Då vende Herren seg og såg på Peter; og Peter kom i hug det ordet Herren hadde sagt til honom: «Fyrr hanen gjel i natt, hev du avneitta meg tri gonger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Og han gjekk ut og gret sårt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Dei mennerne som heldt Jesus, spotta honom og slo honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Dei kasta eit klæde yver honom og spurde: «Kven var det som slo deg? Seg oss det, du som er ein profet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Og mange andre hædingsord tala dei til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Då det vart dag, kom styresmennerne åt folket i hop, og øvsteprestarne og dei skriftlærde; dei førde honom fram i rådsmøtet sitt');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'og sagde: «Er du Messias, so seg oss det!» «Um eg segjer det åt dykk, trur de det ikkje,» svara han,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, '«og um eg spør, svarar de ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Men heretter skal Menneskjesonen sitja ved høgre handi åt Guds allmagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Då spurde dei alle: «Er du då Guds Son?» Han svara: «De segjer det, og eg er det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, '«Kva skal me med fleire vitnemål?» sagde dei då; «no høyrde me det av hans eigen munn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Då reiste dei seg, heile hopen, og førde honom til Pilatus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'og bar fram klagemålet sitt mot honom. «Me hev kome etter at denne mannen forvillar folket vårt,» sagde dei; «han forbyd deim å gjeva keisaren skatt, og segjer at han er Messias, ein konge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Då tok Pilatus til ords og spurde honom: «Er du kongen yver jødarne?» «Det er som du segjer,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilatus sagde til øvsteprestarne og folket: «Eg finn ingi skuld hjå denne mannen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Då tok dei sterkare i og sagde: «Han øser upp folket med læra si i heile Jødeland; han tok til med det i Galilæa, og no hev han kome alt hit.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Då Pilatus høyrde det, spurde han um mannen var frå Galilæa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'og so snart han vart vis med at han lydde under Herodes’ velde, sende han honom åt Herodes; for han var og i Jerusalem i dei dagarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Herodes vart svært glad då han såg Jesus; han hadde lenge ynskt at han måtte få sjå honom; for han hadde høyrt mykje um honom og gjorde seg von um å få sjå eit teikn av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Han spurde honom um mangt og mykje, men Jesus svara ikkje eit ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Øvsteprestarne og dei skriftlærde stod der og klaga på honom so sterkt dei kunde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Og Herodes med hermennerne sine svivyrde og hædde honom, kasta ei brikjeleg kåpa um honom og sende honom so attende til Pilatus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Den dagen vart Herodes og Pilatus vener; fyrr hadde det vore fiendskap millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'So kalla Pilatus i hop øvsteprestarne og rådsherrarne og folket');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'og dei sagde til deim: «De hev ført denne mannen fram for meg og skulda honom for at han leider folket på avveg. No hev eg lydt honom ut, so de hev høyrt på det, men eg hev’kje funne honom saka i noko av det de klagar honom for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Og det hev ikkje Herodes heller; for eg sende dykk til honom. So kann de sjå, at han hev ikkje gjort noko, som han skulde lata livet for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Difor vil eg refsa honom og so gjeva honom fri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Men han laut gjeva deim ein fange fri i høgtidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Då ropa dei alle som ein; «Burt med honom! Gjev oss Barabbas fri!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '- so heitte ein som var sett i fengsel for eitt upprør som hadde brote ut i byen, og for manndråp -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'På nytt tala Pilatus til deim; for han vilde gjerne gjeva Jesus fri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Men dei ropa imot: «Krossfest honom, krossfest honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'So tala han til deim tridje gongen og sagde: «Kva vondt hev han då gjort, denne mannen? Eg hev’kje funne honom saka i noko som han kann dømast frå livet for. Difor vil eg refsa honom og so gjeva honom fri.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Men dei braut på, og kravde med høge rop at han skulde krossfestast, og ropi deira fekk yvertaket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Då dømde Pilatus so at det skulde vera som dei kravde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Han løyste den som sat fengsla for upprør og manndråp, den som dei bad um, men gav Jesus yver til deim, so dei kunde gjera med honom som dei vilde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Då dei førde honom burt, tok dei fat på ein mann som kom frå marki; han heitte Simon, og var frå Kyrene; honom lagde dei krossen på, so han skulde bera honom etter Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Ein stor folkehop fylgde honom; bland deim var det mange kvinnor, som øya og gret for hans skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Jesus snudde seg åt deim og sagde: «Jerusalems døtter, gråt ikkje yver meg! Gråt heller yver dykk sjølve og borni dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'For det kjem dagar då dei skal segja: «Sæle dei som aldri bar barn under beltet! Sælt det livet som aldri hev født, og det brjostet som aldri hev fostra!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Då kjem dei til å segja til fjelli: «Fall yver oss!» og til haugarne: «Gøym oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'For fer dei so med det grøne treet, korleis skal det då ganga med det turre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Tvo andre, tvo illgjerningsmenn, vart og førde av stad saman med honom og skulde lata livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Då dei kom til den staden som kallast Skallen, krossfeste dei honom der, og like eins illgjerningsmennerne, den eine på høgre og den andre på vinstre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Men Jesus sagde: «Fader, forlat deim, for dei veit ikkje kva dei gjer!» So skifte dei klædi hans millom seg og drog strå um deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Folket stod og såg på; og rådsherrarne spotta og sagde: «Han hev hjelpt andre, no kann han hjelpa seg sjølv, dersom han er Guds Messias, den utvalde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Hermennerne gjorde narr av honom; dei gjekk fram og rette honom eddik og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, '«Er du kongen yver jødarne, so hjelp deg sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Og uppyver honom var det ei innskrift: «Dette er kongen yver jødarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Ein av illgjerningsmennerne som hekk der, hædde honom og sagde: «Er’kje du Messias? - hjelp deg sjølv og oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Då tok den andre til ords, og skjemde på honom og sagde: «Ottast ikkje du heller Gud, du som er under same domen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Og det er me med rette; for me fær berre lika for det me hev gjort. Men han hev ikkje gjort noko urett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Jesus,» sagde han, «kom meg i hug når du kjem i ditt rike!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, '«Det segjer eg deg for visst,» svara Jesus: «I dag skal du vera med meg i paradis.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Det var no kring den sette timen; då vart det myrkt yver heile landet, alt til den niande timen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'og soli svartna. Forhenget i templet rivna midt i tvo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Og Jesus ropa med høg røyst: «Fader, i dine hender gjev eg mi ånd!» Då han hadde sagt det, andast han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Då hovudsmannen såg det som hende, lova han Gud og sagde: «Den mannen var sanneleg skuldlaus!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Og heile folkemengdi som hadde samla seg for å sjå på dette, øya seg og gjekk burt att då dei såg kva som hende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Men alle venerne hans, og dei kvinnorne som hadde fylgt honom frå Galilæa, stod langt undan og såg på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Det var ein mann som heitte Josef, ein god og rettvis mann; han høyrde til det Høge Rådet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'men hadde ikkje vore med på rådi og gjerningarne deira; han åtte heime i Arimatæa, ein by i Jødeland, og var ein av deim som venta på Guds rike -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'den mannen gjekk til Pilatus og bad um likamen åt Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'tok honom ned, sveipte honom i lin og lagde honom i ei grav som var hoggi i berget, og som det endå ikkje var lagd nokon i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Det var då fyrebuingsdagen, og kviledagen var i kjømdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Nokre av dei kvinnorne som hadde vore med han frå Galilæa, fylgde etter; dei skoda gravi og såg korleis likamen hans vart lagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'So gjekk dei heim att og laga til angande kryddor og salvar. Kviledagen heldt dei seg i ro etter lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Men den fyrste dagen i vika, tidleg i otta, kom dei til gravi, og hadde med seg kryddorne som dei hadde laga til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Då fekk dei sjå at steinen var velt ifrå gravi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'dei gjekk inn, men fann ikkje likamen åt Herren Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Dei visste ikkje kva dei skulde tenkja um dette; då stod det med ein gong tvo menner i skinande klæde innmed deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'og med dei fulle av otte stirde nedfyre seg, sagde mennerne til deim: «Kvi leitar de etter den livande millom dei daude?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Han er ikkje her; han hev stade upp att. Kom i hug kva han sagde med dykk då han endå var i Galilæa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'at Menneskjesonen skulde gjevast i henderne på synduge menneskje og krossfestast, og standa upp att tridje dagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Då kom dei i hug ordi hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'og dei gjekk burt att frå gravi, og fortalde alt dette til dei elleve og alle dei andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Det var Maria Magdalena og Johanna og Jakobs-Maria og dei hine kvinnorne i fylgjet deira - dei sagde dette med apostlarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'men dei tenkte det var noko vas dei for med, og trudde deim ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Peter sprang like vel av stad til gravi, og då han lutte seg ned, såg han ikkje anna enn likklædi; so gjekk han burt att, og undrast med seg yver det som var hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Same dagen gjekk tvo av deim utetter til ein liten by som heiter Emmaus, og ligg ei mil frå Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'og på vegen tala dei med einannan um alt det som nyst hadde hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Med dei no gjekk og tala og dryfte det med kvarandre, kom Jesus sjølv innåt og slo fylgje med deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'men augo deira var fjetra, so dei kjende honom ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, '«Kva er det for ting de røder so um, med de gjeng etter vegen?» spurde han. Då stana dei, og det var sjåande til at dei sturde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Og den eine av deim - han heitte Kleopas - tok til ords og sagde til honom: «Du må visst vera den einaste som held til i Jerusalem og ikkje veit kva som hev hendt der desse dagarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, '«Kva for noko?» spurde han. «Det med Jesus frå Nasaret,» svara dei, «han som var ein profet, megtig i gjerning og ord for Gud og alt folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'korleis øvsteprestarne og rådsherrarne våre fekk dømt honom frå livet og krossfeste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Og me vona at han var den som skulde løysa ut Israel. Og med alt det so er det no på tridje dagen sidan dette gjekk fyre seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Men so hev og nokre kvinnor i flokken vår sett oss i uro og undring; dei var i otta ved gravi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'og fann ikkje likamen hans, men kom og fortalde at dei hadde set ei syn av englar, og at englarne hadde sagt at han liver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Nokre av felagerne våre gjekk då ut til gravi, og fann det heiltupp so som kvinnorne hadde sagt, men honom såg dei ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, '«Å, for uvituge de er,» svara han, «og for seinhuga til å tru alt det som profetarne hev tale!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Laut ikkje Messias lida dette, fyrr han kunde ganga inn til sin herlegdom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'So tok han til frå Moses og alle profetarne, og i alle skrifterne lagde han ut for deim det som er sagt um honom der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Då dei var tett innmed den byen dei skulde til, lest han vilja ganga lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Men dei nøydde honom og sagde: «Ver hjå oss! Det lid til kvelds, og dagen hallar.» So gjekk han inn og var hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Som han no sat til bords med deim, tok han brødet og velsigna det, og braut det og gav deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Då vart augo deira upplatne, so dei kjende honom att; men i det same kvarv han burt for augo deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Då sagde dei med einannan: «Brann ikkje hjarta i oss då han tala med oss på vegen, då han lagde ut skrifterne åt oss?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Og dei tok ut i same stund, og gjekk attende til Jerusalem. Dei fann dei elleve og felagarne deira samla, og dei sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, '«Herren hev sanneleg stade upp att, og hev synt seg for Simon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Og sjølve fortalde dei um det som hadde hendt på vegen, og korleis dei hadde kjent honom då han braut brødet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Best dei tala um dette, stod han sjølv midt ibland deim og sagde: «Fred vere med dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Dei kvakk og vart rædde, og trudde det var ei ånd dei såg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Då sagde han til deim: «Kvi er de so forstøkte, og kvifor vaknar det tvil i hjarta dykkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Sjå henderne og føterne mine, at det er eg sjølv! Kjenn på meg og sjå! Ei ånd hev då’kje kjøt og bein, som de ser eg hev.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Då han hadde sagt det, synte han deim henderne og føterne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Då dei endå ikkje kunde tru for gleda, men berre undra seg, sagde han: «Hev de noko etande her?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Dei gav han eit stykke steikt fisk og noko av ei honningkaka,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'og han tok det og åt det for augo deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'So sagde han til deim: «Dette var det eg tala til dykk um då eg endå var i lag med dykk, at alt som er skrive um meg i Moselovi og profetarne og salmarne, laut sannast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'So let han upp for tankarne deira, so dei kunde skyna skrifterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, '«So stend skrive,» sagde han, «at Messias skal lida og standa upp frå dei daude tridje dagen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'og i hans namn skal umvending og syndeforlating ropast ut for alle folkeslag; frå Jerusalem skal det ganga ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'De skal sjølve vitna um dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Og no vil eg senda yver dykk det som far min hev lova; men de skal halda dykk rolege i byen, til de vert budde med kraft frå det høge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Sidan tok han deim med seg ut or byen, til burt imot Betania, og han lyfte upp henderne og velsigna deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Og med han lyste velsigningi, skildest han frå deim og for upp til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Og dei kasta seg på kne og tilbad honom. So gjekk dei attende til Jerusalem i stor gleda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'og sidan var dei allstødt i templet og lova og prisa Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'I upphavet var ordet, og ordet var hjå Gud, og ordet var Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Han var i upphavet hjå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'All ting vart til ved honom, og utan honom vart ikkje ein einaste ting til av det som hev vorte til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'I honom var liv, og livet var ljoset åt menneski.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Og ljoset skin i myrkret, og myrkret fekk ikkje magt med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Det stod fram ein mann, send ifrå Gud; Johannes er namnet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Den mannen kom til vitnemål, at han skulde vitna um ljoset, so alle kunde tru ved honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Det var ikkje han som var ljoset, men han skulde vitna um ljoset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Det sanne ljoset, som lyser upp kvart menneskje, var den gongen på veg til verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Han var i verdi, og verdi hev vorte til ved honom, og verdi kjende honom ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Han kom til sitt eige, og hans eigne tok ikkje imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Men alle som tok imot honom, deim gav han rett til å verta Guds born, deim som trur på namnet hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'som ikkje er fødde av blod, og ikkje av kjøts vilje, og ikkje av manns vilje, men av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Og Ordet vart kjøt og feste bu hjå oss, og me skoda herlegdomen hans, ein sovoren herlegdom som ein einboren Son hev frå Far sin, full av nåde og sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes vitnar um honom og ropar ut: «Han var det eg sagde soleis um: Den som kjem etter meg, hev vorte fyre meg; for han var til fyrr enn eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Ja, av hans fullnad hev me alle fenge, og det nåde på nåde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'for lovi vart gjevi gjenom Moses, nåden og sanningi vart til ved Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Aldri hev nokon set Gud; den einborne Sonen, som er i fanget åt Faderen, han hev gjort honom kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'So var vitnemålet Johannes gav då jødarne sende prestar og levitar frå Jerusalem, som skulde spyrja honom: «Kven er du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Då sagde han beint ut, og dulde ikkje fyre det; han sagde beint ut: «Eg er ikkje Messias.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, '«Kva er du då?» spurde dei. «Er du Elia?» «Nei, det er eg ikkje,» sagde han. «Er du profeten?» «Nei,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, '«Kven er du?» sagde dei då - «so me hev eit svar å gjeva deim som hev sendt oss! Kva segjer du um deg sjølv?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Han sagde: «Eg er røysti som ropar i heidi: «Beinka vegen åt Herren!» som profeten Jesaja segjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Dei som var sende, høyrde til farisæarflokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'So spurde dei honom: «Kvi døyper du då, når du ikkje er Messias, og ikkje Elia, og ikkje profeten?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, '«Eg døyper med vatn,» svara Johannes; «midt ibland dykk stend ein som de ikkje kjenner:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'han som kjem etter meg, og som eg ikkje er verdig til å løysa skobandet åt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Dette gjekk fyre seg i Betania, på hi sida åt Jordan, der Johannes var og døypte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Dagen etter ser han Jesus koma burt imot seg, og segjer: «Sjå der er Guds lamb, som tek burt verdsens synd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Det er han eg sagde det um: Etter meg kjem ein mann som hev vorte fyre meg; for han var til fyrr enn eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Eg kjende honom ikkje, men for di han skulde openberrast åt Israel, difor er det eg er komen og døyper med vatn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Og Johannes vitna: «Eg hev set Anden dala ned som ei duva frå himmelen, og han stana yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Eg kjende honom ikkje, men han som sende meg til å døypa med vatn, han sagde til meg: «Den du ser Anden dalar ned imot og stanar yver, han er den som døyper med den Heilage Ande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Og eg hev set det, og hev vitna at han er Guds Son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Andre dagen stod Johannes der atter med tvo av læresveinarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Då ser han Jesus, som kom gangande, og segjer: «Sjå der er Guds lamb!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Dei tvo læresveinarne høyrde kva han sagde, og fylgde etter Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Då snudde Jesus seg, og då han såg dei fylgde etter honom, sagde han til deim: [Stu21: 39] «Kva vil de?» «Kvar bur du, rabbi?» spurde dei - rabbi tyder meister -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, '[Stu21: 40] «Kom, so skal de sjå!» svara han. So gjekk dei med honom, og såg kvar han budde, og dei vart verande hjå honom den dagen. Det var ikring tiande timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, '[Stu21: 41] Andreas, bror åt Simon Peter, var ein av dei tvo som hadde høyrt ordi hans Johannes og fylgt etter Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, '[Stu21: 42] Han finn fyrst bror sin, Simon, og segjer til honom: «Me hev funne Messias!» - Messias er det same som Kristus -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, '[Stu21: 43] Han tok honom med seg til Jesus. Jesus såg på honom og sagde: «Du er Simon Johannesson; du skal kallast Kefas!» - Kefas er det same som Peter -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, '[Stu21: 44] Dagen etter vilde Jesus taka ut og fara til Galilæa. Han møter Filip, og segjer til honom: «Fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, '[Stu21: 45] Filip var frå Betsaida, same byen som Andreas og Peter var ifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, '[Stu21: 46] Filip møter Natanael, og segjer til honom: «Me hev funne den som Moses hev skrive um i lovi, og som profetarne hev skrive um; det er Jesus Josefsson frå Nasaret.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, '[Stu21: 47] «Kann det koma noko godt frå Nasaret?» sagde Natanael. «Kom og sjå!» svara Filip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, '[Stu21: 48] Jesus såg Natanael koma burt imot seg, og sagde um honom: «Sjå der er ein egte israelit, ein som det ikkje finst svik i!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, '[Stu21: 49] Natanael segjer til honom: «Kvar kjenner du meg ifrå?» «Eg såg deg då du var under fiketreet, fyrr Filip ropa på deg,» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, '[Stu21: 50] Då tok Natanael til ords og sagde til honom: «Rabbi, du er Guds Son, du er Israels konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, '[Stu21: 51] «Trur du for di eg sagde deg at eg hadde set deg innunder fiketreet?» svara Jesus; «du skal få sjå større ting enn det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, '[Stu21: 52] Det segjer eg dykk for visst og sant,» sagde han med honom: «De skal sjå himmelen open og Guds englar stiga upp og stiga ned yver Menneskjesonen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Tridje dagen stod det eit brudlaup i Kana i Galilæa. Mor åt Jesus var der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'og Jesus og læresveinarne hans vart og bedne til brudlaupet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Då vinen traut, segjer mor åt Jesus til honom: «Dei hev ikkje vin!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, '«Kva vil du meg, kvinna?» svara Jesus; «mi tid er ikkje endå komi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, '«Gjer alt han segjer til dykk!» sagde mor hans til bordsveinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Etter di no jødarne hev for vis å två seg fyre måli, stod det der seks vats-kjer av stein; kvart av deim tok tvo eller tri anker.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, '«Fyll kjeri med vatn!» segjer Jesus til bordsveinarne. Då fyllte dei kjeri heilt uppåt barden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'So sagde han til deim: «Aus no upp, og ber det til kjøkemeisteren!» Dei so gjorde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'men då kjøkemeisteren hadde smaka på vatnet som var vorte til vin, og ikkje visste kvar den vinen kom ifrå - men bordsveinarne visste det, dei som hadde aust upp vatnet - so ropa han på brudgomen, og sagde til honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, '«Kvar mann set fyrst fram den gode vinen, og når folk hev vorte drukne, den ringare; du hev gøymt den gode vinen til no!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Dette fyrste teiknet sitt gjorde Jesus i Kana i Galilæa, og let sin herlegdom skina fram; og læresveinarne hans trudde på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Sidan for han ned til Kapernaum med mor si og brørne og læresveinarne sine, og der vart dei verande nokre få dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Det leid til påskehelgi åt jødarne, og Jesus for upp til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'I templet fann han folk som selde uksar og sauer og duvor, og andre som sat og veksla pengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Då gjorde han seg ei svepa av reimar og dreiv deim alle ut or templet, og sauerne og uksarne med; småpengarne åt vekslarane kasta han utyver, og velte bordi deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'og til duvekræmarane sagde han: «Burt med dette! Gjer ikkje huset åt Far min til ei krambud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Og læresveinarne kom i hug at det stend skrive: «Brennhug for ditt hus kjem til å eta meg upp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Då tok jødarne til ords og sagde til honom: «Kva teikn syner du oss, sidan du gjer dette?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus svara: «Riv dette templet ned, og eg skal reisa det upp att på tri dagar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, '«I seks og fyrti år hev det vore bygt på dette templet,» sagde dei då, «og du vil reisa det upp att på tri dagar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Men det var likams-templet sitt han tala um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Då han no hadde stade upp frå dei daude, kom læresveinarne hans i hug at han hadde sagt dette, og dei trudde Skrifti og det ordet Jesus hadde sagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Medan han var i Jerusalem i påskehelgi, på høgtidi, trudde mange på namnet hans då dei såg dei teikni han gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Men sjølv trudde Jesus seg ikkje til deim, av di han kjende alle,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'og ikkje trong at nokon skulde vitna um noko menneskje; for han visste sjølv kva som budde i det menneskjet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Det var ein mann av farisæarflokken som heitte Nikodemus, ein av rådsherrarne åt jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Han kom ein gong til Jesus um natti og sagde: «Rabbi, me veit at du er ein lærar som er komen frå Gud; for ingen kann gjera desse teikni som du gjer, utan Gud er med honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus svara: «Det segjer eg deg for sant og visst: Ingen kann sjå Guds rike utan han vert fødd på nytt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodemus segjer til honom: «Korleis kann ein som er gamall verta fødd? han kann då vel ikkje koma inn i livet åt mor si andre gongen, og fødast til verdi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesus svara: «Det segjer eg deg for sant og visst: Utan ein vert fødd av vatn og ånd, kann han ikkje koma inn i Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Det som er født av kjøtet, er kjøt, og det som er født av åndi, er ånd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Undrast ikkje på at eg sagde med deg: De lyt fødast på nytt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Vinden blæs kvar han vil, og du høyrer han tyt, men du veit ikkje kvar han kjem ifrå eller kvar han fer av. So er det med kvar som er fødd av åndi».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, '«Korleis kann det ganga til?» spurde Nikodemus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, '«Du er Israels lærar, og veit ikkje det!» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, '«Det segjer eg deg for visst og sant: Me talar um det me veit, og vitnar um det me hev set, men de tek ikkje imot vitnemålet vårt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Når eg hev tala til dykk um det som høyrer jordi til, og de ikkje trur, korleis skal de då tru når eg talar til dykk um det som høyrer himmelen til?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Og ingen hev stige upp til himmelen utan han som steig ned frå himmelen, Menneskjesonen, som var i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Og liksom Moses lyfte upp ormen i øydemarki, soleis lyt Menneskjesonen lyftast upp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'so kvar den som trur, skal hava æveleg liv i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'For so elska Gud verdi at han gav Son sin, den einborne, so kvar den som trur på honom, ikkje skal verta fortapt, men hava ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'For Gud sende ikkje Son sin til verdi so han skulde døma verdi, men so verdi skulde verta frelst ved honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Den som trur på honom, vert ikkje dømd; den som ikkje trur, er alt dømd, for di han ikkje hev trutt på namnet åt Guds einborne Son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Og dette er domen: Ljoset hev kome til verdi, og menneski lika myrkret betre enn ljoset, for gjerningarne deira var vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'For kvar den som driv på med det som låkt er, hatar ljoset, og kjem ikkje til ljoset; for han vil ikkje at gjerningarne hans skal koma upp i dagen, slike dei er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Men den som gjer etter sanningi, kjem til ljoset, so gjerningarne hans kann verta synberre; for dei er gjorde i Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Sidan kom Jesus og læresveinarne hans til Juda-bygderne, og der var han ei tid med deim, og døypte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Johannes døypte og då; det var i \'non, tett med Salim, han døypte; for det var mykje vatn der; og folk kom dit og let seg døypa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Den tid var Johannes endå ikkje sett i fengsel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'So vart det eit ordskifte millom læresveinarne åt Johannes og ein Juda-mann um reinsingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Og dei kom til Johannes og sagde: «Rabbi, han som var i hop med deg på hi sida åt Jordan, han som du hev vitna for, han døyper, og alle kjem til honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes svara: «Eit menneskje kann ikkje få noko, utan det er gjeve honom frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'De er sjølve vitni mine at eg sagde: «Eg er ikkje Messias,» men: «Eg er send fyre honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Det er brudgomen som hev bruri; men belesveinen, som stend innmed og lyder på brudgomen, gleder seg hjarteleg når han høyrer målet hans. Slik gleda hev eg no fenge, og det i fullt mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Han lyt veksa, eg lyt minka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Den som kjem ovantil, er yver alle; den som er frå jordi, er av jordi, og det han talar, er av jordi. Den som kjem frå himmelen, er yver alle;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'det han hev set og høyrt, det vitnar han um, men ingen tek imot vitnemålet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Den som hev teke imot hans vitnemål, hev stadfest at Gud er sannordig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'For den som Gud sende, talar Guds ord; for Gud gjev honom Anden umælt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Faderen elskar Sonen, og hev gjeve alt i hans hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Den som trur på Sonen, hev æveleg liv; men den som ikkje lyder Sonen, fær ikkje sjå livet, men Guds vreide vert verande yver honom».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Då no Jesus fekk vita at farisæarane hadde høyrt han vann fleire læresveinar og døypte fleire enn Johannes');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '- endå det var ikkje Jesus sjølv som døypte, men læresveinarne hans -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'so tok han ut frå Judæa og for til Galilæa att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Han laut fara gjenom Samaria,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'og kom då til ein by i Samaria som heiter Sykar og ligg tett ved den marki som Jakob gav Josef, son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Der var Jakobs-kjelda. Jesus var trøytt etter ferdi, og sette seg beint ned der innmed kjelda; det var ikring den sette timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Då kjem det ei kvinna frå Samaria og vil draga upp vatn. Jesus segjer til henne: «Lat meg få drikka!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'For læresveinarne hans hadde gjenge inn til byen og skulde kjøpa mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, '«Korleis hev det seg,» segjer den samaritanske kvinna, «at du, som er jøde, bed meg, ei samaritansk kvinna, um drikka?» - for jødarne hev ikkje nokoslag samlag med samaritanarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus svara: «Dersom du kjende Guds gåva, og visste kven han er, han som bed deg um drikka, so bad du honom, og han gav deg livande vatn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, '«Herre,» segjer kvinna, «du hev ingen ting å draga upp med, og brunnen er djup! Kvar hev du då det livande vatnet frå?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Er då du større enn Jakob, ættfaren vår, som hev gjeve oss brunnen? han hev sjølv drukke av honom, og sønerne og feet hans med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus svara: «Kvar den som drikk av dette vatnet, vert tyrst att,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'men den som drikk av det vatnet eg vil gjeva honom, vert aldri tyrst meir; for det vatnet eg gjev honom, vert i honom til ei kjelda med vatn som vell upp til ævelegt liv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, '«Herre,» sagde kvinna, «gjev meg det vatnet, so eg ikkje vert tyrst meir, og ikkje treng koma alt hit og draga upp vatn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Han segjer til henne: «Gakk og henta mannen din, og kom hit att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, '«Eg hev ingen mann,» svara kvinna. «Det er rett som du segjer, at du ikkje hev nokon mann,» sagde Jesus;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, '«for du hev havt fem menner, og den du hev no, er ikkje din mann. No sagde du sant.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, '«Herre, eg ser at du er ein profet!» sagde kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, '«Federne våre tilbad Gud på dette fjellet, og de segjer at det er i Jerusalem ein skal tilbeda honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jesus segjer til henne: «Tru meg, kvinna; det kjem ei tid då de ikkje skal tilbeda Faderen på dette fjellet og ikkje i Jerusalem heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'De tilbed det de ikkje kjenner, me tilbed det me kjenner; for frelsa kjem frå jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Men det kjem ei tid, og ho hev alt kome, då dei rette tilbedarane skal tilbeda Faderen i ånd og sanning; for slike tilbedarar er det Faderen vil hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Gud er ånd, og dei som tilbed honom, lyt tilbeda i ånd og sanning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Kvinna segjer til honom: «Eg veit at Messias kjem» - Messias er det same som Kristus -; «når han kjem, skal han læra oss alt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jesus segjer til henne: «Det er eg - eg som talar med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'I det same kom læresveinarne hans. Dei undra seg yver at han tala med ei kvinna; like vel var det ingen som sagde: «Kva vil du henne?» eller: «Kvi talar du med henne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'So let kvinna vatskrukka si standa, og gjekk av stad til byen og sagde til folki:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '«Kom, so skal de sjå ein mann som hev sagt meg alt eg hev gjort! Skal tru han er Messias?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Då gjekk dei ut or byen. Med dei var på vegen til honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'bad læresveinarne honom: «Et, rabbi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Han svara: «Eg hev ein mat som ikkje de veit um.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Då sagde læresveinarne seg imillom: «Tru nokon hev bore mat til honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesus segjer til deim: «Min mat er at eg gjer det han vil som sende meg, og fullfører hans verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Segjer ikkje de: «Det er endå fire månader fyrr hausten kjem?» Men høyr kva eg segjer dykk: Lyft upp augo dykkar og skoda åkrane, korleis dei alt gulnar mot hausten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Den som haustar fær løn, og samlar grøda til ævelegt liv, so dei skal få gleda seg saman både den som sår og den som haustar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'For her høver det ordet: «Det er ein som sår og ein annan som haustar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Eg hev sendt dykk ut til å hausta det som de ikkje hev havt noko arbeidt med; andre hev havt arbeidet, og de hev gjenge inn i arbeidet deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Det var mange av samaritanarne frå den byen som trudde på honom for det som kvinna hadde sagt då ho vitna: «Han hev sagt meg alt eg hev gjort!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Då no samaritanarne kom til honom, bad dei at han vilde vera hjå deim, og han vart verande der tvo dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Og mange fleire trudde for skuld ordet han tala,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'og dei sagde til kvinna: «No trur me’kje lenger for skuld det du hev tala; for me hev sjølve høyrt honom og veit no for visst at han er den som skal frelsa verdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Då dei tvo dagarne var lidne, tok han ut derifrå og for til Galilæa;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'for Jesus vitna sjølv at ein profet vert ikkje æra i sitt eige fedreland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Då han no kom til Galilæa, tok galilæarane vel imot honom; dei hadde set alt det han gjorde i Jerusalem på høgtidi; for dei var sjølve komne til høgtidi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'So kom han då atter til Kana i Galilæa, der han hadde gjort vatn til vin. I Kapernaum var det ein kongsmann som hadde ein sjuk son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Då han fekk høyra at Jesus hadde teke ut frå Judæa og var komen til Galilæa, gjekk han til honom og bad at han vilde koma ned og lækja son hans; for han låg på det siste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jesus svara: «Ser de’kje teikn og under, so trur de ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Kongsmannen segjer til honom: «Herre, kom ned innan barnet mitt døyr!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jesus segjer til honom: «Gakk heim att! Son din liver.» Mannen trudde det Jesus sagde til honom og gjekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Då han alt var på heimvegen, kom tenarane hans imot honom og sagde at guten hans livde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'So spurde han deim kva tid det hadde vorte betre med honom. «I går den sjuande timen slepte sotti honom,» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Då skyna faren at det var i den same timen som Jesus hadde sagt til honom: «Son din liver,» og han trudde, både han og heile hans hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Dette var det andre teiknet Jesus gjorde då han no atter kom frå Judæa til Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Ei tid etterpå var det ei av høgtiderne åt jødarne, og Jesus for upp til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Ved Saueporten i Jerusalem er det ein dam som dei på hebraisk kallar Betesda, med fem sulehallar kringum;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'i deim låg det ei heil mengd med sjuke - blinde, halte, nomne - som venta på at vatnet skulle rørast upp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'for ein engel for frå tid til tid ned i dammen og rørde upp vatnet, og den fyrste som då steig uti, etter at vatnet var upprørt, han vart frisk, kva sjukdom han so leid av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'No var det der ein mann som hadde dregest med sjukdomen sin i åtte og tretti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Då Jesus såg honom liggja der, og fekk vita at han hadde vore sjuk i lang tid, sagde han til honom: «Vil du verta frisk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, '«Herre,» svara den sjuke, «eg hev ingen som kann bera meg ned i dammen når vatnet tek til å rørast, og med eg er på vegen, stig ein annan ned fyre meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesus segjer til honom: «Statt upp, tak sengi di og gakk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Og straks vart mannen frisk, og tok sengi si og gjekk. Det var ein kviledag dette hende;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'difor sagde jødarne til den som hadde vorte lækt: «Det er kviledag! Du hev ikkje lov til å bera sengi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Han svara: «Den som gjorde meg frisk, han sagde til meg: «Tak sengi di og gakk!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Dei spurde honom: «Kva var det for ein mann som sagde til deg: «Tak sengi di og gakk?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Men den som hadde vorte lækt, visste ikkje kven det var, for Jesus hadde drege seg undan av di det var so mykje folk der på staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Sidan fekk Jesus sjå honom i templet og sagde til honom: «No hev du fenge att helsa di. Synda no ikkje meir! elles kunde det henda deg noko verre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Mannen gjekk av stad og sagde med jødarne at det var Jesus som hadde gjort honom frisk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Og difor forfylgde jødarne Jesus, sidan han gjorde slikt på ein kviledag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Han svara deim: «Far min arbeider til no; eg arbeider og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Difor var jødarne endå meir huga på å drepa honom, sidan han ikkje berre braut helgi, men jamvel kalla Gud Far sin, og gjorde seg sjølv lik med Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'So tok Jesus til ords og sagde til deim: «Det segjer eg dykk for visst og sant: Sonen kann ingen ting gjera av seg sjølv, anna enn det han ser Faderen gjer; for det han gjer, det gjer Sonen og like eins.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'For Faderen Sonen kjær, og syner honom alt det han gjer sjølv, og han skal syna honom større verk enn desse, so de skal koma til å undrast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'For liksom Faderen vekkjer upp dei daude og gjev deim liv, soleis gjev Sonen og liv åt kven han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'For Faderen dømer ikkje heller nokon, men hev gjeve heile domen yver til Sonen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'so alle skal æra Sonen som dei ærar Faderen. Den som ikkje ærar Sonen, ærar ikkje Faderen, som hev sendt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Det segjer eg dykk for visst og sant: Den som høyrer mitt ord og trur den som sende meg, han hev ævelegt liv, og kjem ikkje for domen, men hev gjenge yver frå dauden til livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Det segjer eg dykk for visst og sant: Det kjem ei tid, ja, ho hev alt kome, då dei daude skal høyra røysti åt Guds Son, og dei som lyder på henne, skal liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'For liksom Faderen hev liv i seg sjølv, so gav han og Sonen den gåva at han hev liv i seg sjølv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'og han gav honom fullmagt til å halda dom, av di han er ein menneskjeson.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'De må ikkje undrast på det! For det kjem ein time då alle dei som ligg i graverne skal høyra hans røyst,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'og dei skal koma ut; dei som hev gjort godt, skal standa upp til liv, og dei som hev gjort vondt, skal standa upp til dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Eg kann ikkje gjera noko av meg sjølv; eg dømer etter det eg høyrer, og domen min er rettferdig; for eg gjeng ikkje etter min eigen vilje, men etter hans vilje som sende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Dersom eg vitnar um meg sjølv, so sæter ikkje vitnemålet mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Det er ein annan som vitnar um meg, og eg veit at det vitnemålet han gjev meg, er sant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'De hev sendt bod til Johannes, og han hev vitna for sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Men eg tek ikkje mot vitnemål av noko menneskje; dette nemner eg berre av di eg gjerne vil de skal frelsast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Han var lampa som brann og skein, og de hadde hug til å gleda dykk eit bil i ljoset hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Men eg hev eit vitnemål som er større enn det frå Johannes; for dei verki som Far min hev gjeve meg, og vil eg fullføra, sjølve dei verki eg gjer, vitnar um meg at Faderen hev sendt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Og Faderen, som sende meg, hev sjølv vitna um meg. Hans røyst hev de aldri høyrt, og hans skapnad hev de aldri set,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'og hans ord ber de ikkje i hjarta dykkar; for den han sende, honom trur de ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'De granskar skrifterne av di de tenkjer at de hev eit ævelegt liv i deim, og dei er det som vitnar um meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Og endå vil de ikkje koma til meg, so de kann hava liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Eg tek ikkje mot æra av menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'men eg kjenner dykk og for at de ikkje hev kjærleiken til Gud i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Eg er komen i far min’s namn, og de tek ikkje imot meg; kjem ein annan i sitt eige namn - honom tek de imot!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Korleis kann de tru, de som tek imot æra av kvarandre, men ikkje søkjer den æra som kjem frå den einaste Gud?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'De må’kje tenkja eg vil klaga dykk for far min! Det er ein som klagar dykk, Moses, han som de hev sett dykkar von til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'For trudde de Moses, so trudde de meg; for det er meg han hev skrive um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Men når de ikkje trur hans skrifter, korleis skal de då tru mine ord?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Sidan for Jesus burt til hi sida av Galilæa- eller Tiberias-sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Og det fylgde honom mykje folk, av di dei såg dei teikni han gjorde på dei sjuke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Men Jesus gjekk upp i fjellet, og der sette han seg med læresveinarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Det leid då mot påskehelgi åt jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Som no Jesus såg upp og vart var at det kom mykje folk til honom, segjer han til Filip: «Kvar skal me kjøpa brød, so desse folki kann få noko å eta?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Det sagde han av di han vilde røyna honom; for han visste sjølv kva han vilde gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, '«Brød for eit halvt hundrad dalar rekk ikkje til, so kvar av deim kann få eit lite stykke,» svara Filip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Ein av læresveinarne hans - det var Andreas, bror åt Simon Peter - segjer til honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '«Her er ein liten gut som hev fem byggbrød og tvo fiskar, men kva er det åt so mange?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, '«Lat folket setja seg!» sagde Jesus. Det var mykje gras på den staden; so sette mennerne seg; dei var um lag fem tusund i talet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Då tok Jesus brødi, og takka, og skifte deim ut til deim som sat der, og like eins av fiskarne, so mykje dei vilde hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Då dei var mette, segjer han til læresveinarne: «Sanka i hop dei molarne som att er, so ingen ting vert spillt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'So gjorde dei det, og dei fyllte tolv korger med molarne som var att av dei fem byggbrødi etter deim som hadde ete.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Då no folket såg det teiknet han hadde gjort, sagde dei: «Dette er visst og sant profeten som skal koma til verdi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Då skyna Jesus at dei vilde koma og taka honom med magt og gjera honom til konge; difor drog han seg undan og gjekk upp i fjellet att, han åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Då det vart kveld, gjekk læresveinarne ned til sjøen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'dei steig ut i båten og vilde fara yver sjøen, til Kapernaum. Det var alt myrkt vorte, og Jesus var endå ikkje komen til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Bårorne gjekk høgt; for det bles ein hard vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Då dei so hadde rott umlag ei halv mil eller halvtridje fjordung, ser dei at Jesus kjem gangande på sjøen og kjem næmare og næmare innåt båten. Dei vart rædde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'men han sagde: «Det er eg; ver ikkje rædde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Då vilde dei taka honom upp i båten, og straks var båten ved det landet dei skulde til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Dagen etter stod det endå ein folkehop på hi sida av sjøen; dei hadde set at det ikkje var meir enn ein båt der, og at Jesus ikkje gjekk i båten med læresveinarne sine, men læresveinarne tok av stad åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Men det kom båtar frå Tiberias, tett innmed den staden dei hadde halde måltid etterpå Herrens takkebøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Då no folket såg at Jesus ikkje var der, og ikkje læresveinarne hans heller, steig dei sjølve i båtarne og for til Kapernaum og leita etter Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'og då dei fann han der, på hi sida av sjøen, sagde dei til honom: «Når kom du hit, meister?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesus svara deim: «Det segjer eg dykk for visst og sant: Det er’kje for di de såg teikn at de leitar etter meg, men for di de åt av brødi og vart mette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Vinn dykk ikkje føda som forgjengst, men føda som varer og gjev eit ævelegt liv! Den skal Menneskjesonen gjeva dykk; for honom hev Faderen, Gud, sett sitt innsigle på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Då sagde dei til honom: «Korleis skal me fara åt, so me kann gjera Guds gjerningar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jesus svara: «Det er Guds gjerning, at de skal tru på den som han sende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Då sagde dei til honom: «Kva teikn gjer då du, so me kann sjå det og tru deg? kva for verk gjer du?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Federne våre åt manna i øydemarki, som skrive stend: «Han gav dei brød frå himmelen å eta.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Då sagde Jesus til deim: «Det segjer eg dykk for visst og sant: Moses gav dykk ikkje brødet frå himmelen, men Far min gjev dykk det rette brødet frå himmelen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'for Guds-brødet er det brødet som kjem ned frå himmelen og gjev verdi liv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Då sagde dei til honom: «Herre, gjev oss alltid det brødet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesus svara: «Eg er livsens brød; den som kjem til meg, skal ikkje hungra, og den som trur på meg, skal aldri tyrsta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Men eg sagde dykk at de hev set meg og endå ikkje trur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Alle som Far min gjev meg, kjem til meg, og den som kjem til meg, skal eg so visst ikkje visa burt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'for eg hev kome ned frå himmelen, ikkje til å gjera det eg sjølv vil, men det han vil som sende meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'og det er hans vilje som sende meg, at eg ikkje skal missa nokon av deim han hev gjeve meg, men vekkja deim upp att på den siste dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'For so vil Far min, at kvar den som ser Sonen og trur på honom, skal hava ævelegt liv, og at eg skal vekkja honom upp att på den siste dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Då murra jødarne og fann åt honom, for di han sagde: «Eg er brødet som kom ned frå himmelen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, '«Er’kje dette Jesus Josefsson? sagde dei; «me kjenner då både far hans og mor hans; korleis hev det seg at han no segjer: «Eg hev kome ned frå himmelen?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Då tok Jesus til ords og sagde til deim: «Haldt ikkje på å murra dykk imillom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Ingen kann koma til meg utan Faderen, som sende meg, hev drege honom, og eg skal vekkja honom upp att på den siste dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Det stend skrive hjå profetarne: «Og alle skal dei vera upplærde av Gud.» Kvar som hev lydt på Faderen og lært, han kjem til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ikkje so at nokon hev set Faderen utan han som er frå Gud, han hev set Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Det segjer eg dykk for visst og sant: Den som trur, hev ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Eg er livsens brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Federne dykkar åt manna i øydemarki og døydde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'her er det brødet som kjem ned frå himmelen, so den som et av det ikkje skal døy.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Eg er det livande brødet som kom ned frå himmelen; dersom nokon et av det brødet, skal liva i all æva; og brødet eg vil gjeva, er kjøtet mitt, som eg gjev til liv for verdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Då trætta jødarne med kvarandre og sagde: «Korleis kann han gjeva oss kjøtet sitt å eta?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Då sagde Jesus til deim: Det segjer eg dykk for visst og sant: Et de ikkje kjøtet åt Menneskjesonen, og drikk blodet hans, so hev de ikkje liv i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Den som et mitt kjøt og drikk mitt blod, hev eit ævelegt liv, og eg skal vekkja honom upp att på den siste dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'For kjøtet mitt er retteleg mat, og blodet mitt er retteleg drykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Den som et mitt kjøt og drikk mitt blod, han vert verande i meg, og eg i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Som den livande Faderen sende meg, og eg liver ved Faderen, so skal og den som et meg liva ved meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Det er brødet som kom ned frå himmelen; det er’kje som det federne dykkar åt, og so døydde: den som et dette brødet, skal liva i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Dette sagde han i eit synagogemøte, med han lærde i Kapernaum.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Mange av læresveinarne hans sagde då dei høyrde det: «Dette er stride ord, kven kann lyda på honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Jesus visste med seg at læresveinarne hans murra um dette, og han sagde til deim: «Støyter de dykk på dette?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Enn um de no fær sjå Menneskjesonen fara upp dit han var fyrr!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Det er åndi som gjev liv; kjøtet gjer ikkje noko gagn. Dei ordi eg hev tala til dykk, er ånd, og er liv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'men det er nokre av dykk som ikkje trur.» For Jesus visste frå fyrste stund kven det var som ikkje trudde, og kven det var som skulde svika honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Og han sagde: «Difor var det eg sagde dykk at ingen kann koma til meg utan det er gjeve honom av Faderen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'For dette var det mange av læresveinarne hans som drog seg undan og ikkje gjekk ikring med honom lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Då sagde Jesus til dei tolv: «Vil de og ganga dykkar veg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Peter svara: «Herre, kven skulde me ganga til? Du hev det ævelege livs ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'og me trur og veit at du er den Heilage frå Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, '«Hev eg ikkje sjølv valt dykk ut, alle tolv?» svara Jesus, «og ein av dykk er ein djevel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Han meinte Judas, son åt Simon Iskariot; for det var han som sidan skulde svika honom - han, ein av dei tolv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Sidan for Jesus kringum i Galilæa; han vilde ikkje ferdast kring i Judæa; for jødarne sat um og vilde drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'So leid det fram til den jødiske høgtidi dei kallar lauvhyttehelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Då sagde brørne hans til honom: «Flytt herifrå, og far til Judæa, so læresveinarne dine og kann få sjå dei verki du gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'For ingen som vil vera namnspurd, gjer noko i løynd. Når du gjer slike ting, so syn deg fram for verdi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'For brørne hans trudde ikkje på honom, dei heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jesus svara: «Mi tid er endå ikkje komi; men for dykk er det allstødt lagleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Verdi kann ikkje hata dykk; men meg hatar ho, for di eg vitnar um henne, at gjerningarne hennar er vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Far de upp til høgtidi! Eg fer ikkje upp til denne høgtidi; for mi tid er endå ikkje fullkomi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Dette sagde han med deim, og vart verande i Galilæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Men då brørne hans var farne upp til høgtidi, då for han og dit, ikkje berrsynt, men som i løynd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Jødarne leita no etter honom på høgtidi og sagde: «Kvar er han, denne mannen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Og det vart mykje mulling um honom millom folket; sume sagde: «Det er ein god mann!» andre sagde: «Nei, han forvillar folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Men ingen tala fritt ut um honom; for dei var rædde jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Då det alt leid midt uti høgtidi, gjekk Jesus upp i templet og lærde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Jødarne undra seg og sagde: «Kvar hev han lærdomen sin frå, som ikkje hev gjenge på nokon skule?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Då tok Jesus til ords og sagde til deim: «Mi læra er’kje mi, men hans som sende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Vil nokon gjera etter hans vilje, skal han få røyna um læra er frå Gud, eller um eg talar av meg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Den som talar av seg sjølv, søkjer si eigi æra; men den som søkjer æra åt den som hev sendt honom, er sannordig, og det finst ikkje urett i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Hev’kje Moses gjeve dykk lovi? og ingen av dykk held lovi. Kvi tenkjer de på å drepa meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, '«Du er forgjord!» svara folket, «kven tenkjer på å drepa deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus svara deim: «Eg gjorde eitt verk, som de alle undrar dykk yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moses hev gjeve dykk umskjeringi - ja, ho er no ikkje frå Moses, men frå federne - og de umskjer eit menneskje på kviledagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Når no eit menneskje fær umskjeringi på kviledagen, so ikkje lovi åt Moses skal brjotast, er de då harme på meg for di eg gjorde eit heilt menneskje godt att på ein kviledag?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Døm ikkje etter det som er utvendes, men lat domen dykkar vera rettferdig!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Det var nokre av Jerusalems-buarne som sagde: «Er’kje dette den mannen som dei tenkjer på å drepa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'og no talar han fritt ut, og dei segjer ikkje eit ord til honom! Skulde dei styrande retteleg ha skyna at han er Messias?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Men um denne mannen veit me kvar han er ifrå, og når Messias kjem, veit ingen kvar han er ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Difor ropa Jesus, med han lærde i templet: «Ja, de kjenner meg, og de veit og kvar eg er ifrå; og endå er eg ikkje komen av meg sjølv, men det er i røyndi ein som hev sendt meg, ein som de ikkje kjenner;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'eg kjenner honom, for eg kjem ifrå honom, og det var han som sende meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Då vilde dei gripa honom; men ingen lagde hand på honom; for endå var’kje tidi hans komi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Men mange av folket trudde på honom og sagde: «Når Messias kjem, tru han då gjer fleire teikn enn denne mannen hev gjort?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Farisæarane høyrde at folket mulla soleis um honom, og øvsteprestarne og farisæarane sende tenarar som skulde gripa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Då sagde Jesus: «Endå eit lite bil er eg hjå dykk, so gjeng eg til honom som hev sendt meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'de skal leita etter meg og ikkje finna meg, og der eg er, kann ikkje de koma.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'So sagde jødarne seg imillom: «Kvar vil han fara av, sidan me ikkje skal finna honom? Tru han vil fara til deim som bur rundt ikring millom grækarane, og læra grækarane?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Kva meinte han med dei ordi han sagde: «De skal leita etter meg og ikkje finna meg, og der eg er, kann ikkje de koma?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Den siste dagen, den største i høgtidi, stod Jesus og ropa ut: «Er det nokon som er tyrst, so lat honom koma til meg og drikka!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Den som trur på meg, frå hans liv skal det, som Skrifti segjer, renna elvar med livande vatn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Det sagde han um Anden som dei skulde få, dei som trudde på honom; for endå var ikkje Anden komen, av di Jesus endå ikkje var herleggjord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Sume bland folket sagde då dei høyrde dei ordi: «Dette er visst og sant profeten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Andre sagde: «Det er Messias.» Men sume sagde: «Messias kjem då vel ikkje frå Galilæa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Hev ikkje Skrifti sagt at Messias er av Davids ætt, og kjem frå Betlehem, den grendi som David åtte heime i?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Soleis kløyvde folket seg i flokkar for hans skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'og sume av deim var huga til å gripa honom, men ingen lagde hand på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Då tenararne kom attende, sagde øvsteprestarne og farisæarane til deim: «Kvi tok de honom ikkje med dykk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Tenarane svara: «Aldri hev noko menneskje tala som honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Då sagde farisæarane: «Hev de og vorte dåra?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Er det nokon av dei styrande som trur på honom, eller av farisæarane?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Men denne mugen, som ikkje kjenner lovi, er forbanna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Segjer Nikodemus, han som fyrr ein gong var komen til Jesus, og som høyrde til flokken deira:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '«Dømer lovi vår nokon mann, fyrr dei hev høyrt på honom og fenge vita kva han gjer?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, '«Er du og frå Galilæa, kann henda?» svara dei. «Granska etter, so fær du sjå at det aldri kjem nokon profet frå Galilæa!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'So gjekk kvar heim til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jesus gjekk til Oljeberget.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Andre morgonen var han atter i templet; alt folket kom til honom, og han sette seg og lærde deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Då kjem dei skriftlærde og farisæarane med ei kona som var teki i egteskapsbrot; dei stelte henne midt framfyre honom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'og sagde: «Meister, denne kona hev dei kome yver med ho gjorde hor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Moses hev sagt oss fyre i lovi at slike kvinnor skal steinast; kva segjer no du?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Det sagde dei av di dei vilde freista honom, so dei kunde hava noko å klaga honom for. Jesus lutte seg ned og skreiv med fingeren på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Då dei heldt på og spurde, rette han seg upp og sagde: «Lat den av dykk som er syndelaus kasta den fyrste steinen på henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'So lutte han seg ned att, og skreiv på marki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Men då dei høyrde det, gjekk dei burt, ein etter ein - dei eldste fyrst - so Jesus vart åleine att med kona som stod der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Då rette han seg upp og sagde til henne: «Kvar er dei, kona? Hev ingen felt domen yver deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, '«Ingen, Herre,» svara ho. «So dømer ikkje eg deg heller,» sagde Jesus: «Gakk heim, og synda ikkje meir!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'So tala Jesus atter til deim og sagde: «Eg er ljoset åt verdi. Den som fylgjer meg, skal ikkje ganga i myrkret, men hava livsens ljos.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Då sagde farisæarane til honom: «Du vitnar um deg sjølv; vitnemålet ditt sæter ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus svara deim so: «Um eg so vitnar um meg sjølv, so er vitnemålet mitt sant; for eg veit kvar eg er komen ifrå og kvar eg fer av, men de veit ikkje kvar eg kjem ifrå eller kvar eg fer av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'De dømer etter kjøtet, eg dømer ingen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'men endå um eg dømer, so er domen min rett, for eg er ikkje einsleg, men eg og han som sende meg, er saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Og i dykkar eigi lov stend skrive at tvo manns vitnemål sæter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Her er det eg som vitnar um meg sjølv, og Faderen, som sende meg, vitnar um meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, '«Kvar er far din?» sagde dei då. Jesus svara: «De kjenner korkje meg eller far min; kjende de meg, so kjende de far min og.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Desse ordi tala Jesus innmed tempelkista, med han lærde i heilagdomen, og ingen lagde hand på honom; for tidi hans var endå ikkje komi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Ein annan gong sagde han til deim: «Eg gjeng burt, og de kjem til å leita etter meg, og de skal døy i syndi dykkar; dit som eg gjeng, kann ikkje de koma.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, '«Tru han vil drepa seg sjølv?» sagde jødarne, «sidan han segjer: «Dit som eg gjeng, kann ikkje de koma?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Då sagde han til deim: «De er nedantil, eg er ovantil; de er frå denne verdi, eg er ikkje frå denne verdi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'difor sagde eg dykk at de skal døy i synderne dykkar; når de ikkje trur at eg er den eg er, so skal de døy i synderne dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, '«Kven er du?» sagde dei då. «Kvi let eg’kje heller reint vera å tala til dykk?» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, '«Mykje hev eg å segja og døma um dykk; men han som sende meg, er sannordig, og eg talar ikkje anna til verdi enn det eg hev høyrt av honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Dei skyna ikkje at det var Faderen han tala til deim um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Difor sagde Jesus: «Når de fær lyft Menneskjesonen upp i høgdi, då skal de skyna at eg er den eg er, og at eg ikkje gjer noko av meg sjølv, men talar dette soleis som Far min lærde meg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Og han som sende meg, er med meg; han let meg ikkje vera åleine; for eg gjer allstødt det som tekkjest honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Då han tala so, trudde mange på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'So sagde Jesus til dei jødarne som trudde på honom: «Vert de verande i mitt ord, so er de rette læresveinarne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'og de skal læra å kjenna sanningi, og sanningi skal gjera dykk frie.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, '«Me er Abrahams ætt,» lagde dei imot, «og hev aldri vore trælar for nokon; korleis hev det seg at du segjer: «De skal verta frie?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jesus svara: «Det segjer eg dykk for visst og sant: Kvar den som gjer synd, er træl åt syndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Men trælen vert ikkje verande i huset for all tid - sonen vert verande der for all tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Fær no Sonen frigjort dykk, so vert de retteleg frie.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Eg veit at de er Abrahams ætt; men de tenkjer på å drepa meg, av di ordet mitt ikkje fær rom hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Eg talar um det eg hev set hjå far min, og soleis gjer de det som de hev høyrt av far dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, '«Vår far er Abraham,» svara dei. Jesus segjer: «Var de Abrahams born, so gjorde de som Abraham gjorde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'men no sit de um og vil drepe meg, ein mann som hev tala til dykk um sanningi, som eg hev høyrt av Gud. Slikt gjorde ikkje Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'De gjer som far dykkar gjorde.» «Me er ikkje fødde i hor,» sagde dei; «me hev ein far, Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesus sagde til deim: Var Gud far dykkar, so hadde de meg kjær; for eg hev gjenge ut frå Gud, og er komen frå honom; ikkje heller er eg komen av meg sjølv; det er han som hev sendt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, '«Kvi skynar de ikkje min tale? Av di de ikkje toler å høyra ordi mine!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'De hev djevelen til far, og det de vil, er å gjera det far dykkar hugast; han var ein manndråpar frå fyrste tid, og hev’kje sitt støde i sanningi; for det finst ikkje sanning i honom. Når han talar lygn, talar han av sitt eige; for han er ein ljugar og far åt lygni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Men av eg talar sanningi, trur det meg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kven av dykk kann segja meg saka i nokor synd? Men når eg talar sanning, kvi trur de meg ikkje?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Den som er av Gud, høyrer Guds ord; de er ikkje av Gud, difor er det de ikkje høyrer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Då tok jødarne til ords og sagde til honom: «Er det’kje sant som me segjer at du er ein samaritan, og er forgjord?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesus svara: «Eg er ikkje forgjord; eg ærar Far min, og de vanærar meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Men eg søkjer ikkje mi eigi æra, det er ein som søkjer henne, og dømer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Det segjer eg dykk for visst og sant: Den som held seg etter mine ord, skal ikkje i all æva sjå dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, '«No veit me at du er forgjord,» sagde jødarne. «Abraham hev døytt, og profetarne og, og du segjer: «Den som held seg etter mine ord, skal ikkje i all æva smaka dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Er då du større enn Abraham, ættfaren vår? han døydde, og profetarne døydde! Kven gjer du deg sjølv til?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus svara: «Dersom eg ærar meg sjølv, so er æra mi ingen ting; det er Far min som ærar meg; de segjer han er dykkar Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'men de hev ikkje kjent honom, men eg kjenner honom; sagde eg at eg ikkje kjenner honom, so var eg ein ljugar som de! Men eg kjenner honom og held meg etter hans ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, ættfaren dykkar, gledde seg hjarteleg til å sjå min dag; og han såg honom og var fegen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, '«Du er endå ikkje femti år,» sagde jødarne, «og so hev du set Abraham!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus sagde til deim: «Det segjer eg dykk for visst og sant: Fyrr Abraham vart til, er eg til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Då tok dei upp steinar og vilde kasta på honom; men Jesus løynde seg og gjekk ut or templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Då han gjekk frametter, fekk han sjå ein mann som hadde vore blind frå han var fødd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Læresveinarne spurde honom: «Rabbi, kven er det som hev synda, han eller foreldri hans, sidan han laut koma til verdi blind?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, '«Dei hev ikkje synda, korkje han eller foreldri hans,» svara Jesus, «men det var for di Guds verk skulde syna seg på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'So lenge det er dag, lyt me gjera hans verk som hev sendt meg; det kjem ei natt då ingen kann gjera noko verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Medan eg er i verdi, er eg ljoset åt verdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Med so sagt sputta han på jordi og laga ei gyrma av sputtet; den gyrma smurde han på augo hans');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'og sagde til honom: «Gakk og två deg i Siloadammen!» - Siloa tyder sendemann -. So gjekk han’stad og tvo seg, og då han kom att, kunde han sjå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Då sagde grannarne og dei som jamleg hadde set honom fyrr - for han var ein tiggar: «Er’kje det han som sat og bad seg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, '«Jau, det er han,» sagde andre. Endå andre sagde: «Nei, men han er lik honom.» Sjølv sagde han: «Det er eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, '«Korleis vart augo dine opna?» sagde dei då.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Han svara: «Den mannen som dei kallar Jesus, laga ei gyrma og smurde på augo mine og sagde til meg: «Gakk til Siloa og två deg!» So gjekk eg’stad og tvo meg, og då fekk eg syni mi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, '«Kvar er han, den mannen?» spurde dei. «Eg veit ikkje,» segjer han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Dei fører honom til farisæarane, han som hadde vore blind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Det var på ein kviledag Jesus laga gyrma og opna augo hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'So spurde dei honom att, farisæarane og, korleis han hadde fenge syni si. «Han lagde ei gyrma på augo mine,» svara han; «so tvo eg meg, og no ser eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Då sagde nokre av farisæarane: «Den mannen er ikkje frå Gud, sidan han ikkje held kviledagen.» Andre sagde: «Korleis kann ein syndug mann gjera slike teikn?» Og dei var usams um dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'So segjer dei til den blinde att: «Kva segjer du um honom, sidan han hev opna augo dine?» «Han er ein profet,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Då vilde ikkje jødarne tru det um honom at han hadde vore blind og fenge syni si, fyrr dei hadde henta foreldri åt honom som hadde fenge syni si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Dei spurde deim: «Er dette son dykkar som de segjer er fødd blind? Korleis hev det seg då at han no ser?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, '«Me veit at dette er vår son, og at han er fødd blind,» svara foreldri hans;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, '«men korleis det hev seg at han no ser, det veit me ikkje, og kven som hev opna augo hans, veit me’kje heller. Spør honom sjølv! Han er gamall nok; han kann sjølv svara for seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Det sagde foreldri hans av di dei var rædde jødarne; for jødarne var alt samrådde um at den som kanna honom for Messias, skulde støytast ut or synagoga;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'difor var det foreldri hans sagde: «Han er gamall nok; spør honom sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'So henta dei andre gongen til seg den mannen som hadde vore blind, og sagde til honom: «Gjev Gud æra! Me veit at denne mannen er ein syndar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, '«Um han er ein syndar, veit eg ikkje,» svara han; «eitt veit eg: eg var blind, og no ser eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, '«Kva gjorde han med deg?» sagde dei då; «korleis gjekk det til at han opna augo dine?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, '«Eg hev alt sagt dykk det,» svara han, «og de agta ikkje på det; kvi vil de høyra det upp att? Kann henda de og vil verta læresveinarne hans?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Då skjelte dei honom ut og sagde: «Du er hans læresvein, men me er Moses’ læresveinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Me veit at Gud hev tala til Moses, men um denne veit me ikkje kvar han er ifrå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, '«Då er det underlegt at de ikkje veit kvar han er ifrå,» svara mannen; «han hev då opna mine augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Me veit at Gud ikkje høyrer på syndarar; men den som ottast honom og gjer etter hans vilje, den høyrer han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Frå ævords tid hev det ikkje vore spurt at nokon hev opna augo på ein blindfødd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Var’kje denne mannen komen frå Gud, kunde han ingen ting gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Då ropa dei imot honom: «I synder er du fødd og boren, og du vil læra oss!» og kasta honom ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesus fekk høyra at dei hadde kasta honom ut, og då han møtte honom, sagde han til honom: «Trur du på Guds Son?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, '«Kven er det då, Herre, so eg kann tru på honom?» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Du hev set honom, sagde Jesus; «det er den som no talar med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, '«Eg trur, Herre!» sagde mannen og kasta seg på kne for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Og Jesus sagde: «Til doms er eg komen til denne verdi, so dei som ikkje ser, skal sjå, og dei som ser, skal verta blinde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Nokre farisæarar som var innmed honom, høyrde det og sagde: «Kann henda me og er blinde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Då sagde Jesus: «Var de blinde, so hadde de ikkje synd; men no segjer de: «Me ser» - og syndi dykkar vert verande der ho var.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '«Det segjer eg dykk for visst og sant: Den som ikkje gjeng inn i sauekvii gjenom døri, men stig yver ein annan stad, han er ein tjuv og ein røvar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Men den som gjeng inn gjenom døri, er hyrding åt sauerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Honom let dørvaktaren upp åt, og sauerne høyrer målet hans, og han kallar sine sauer på namn, og leider deim ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Når han hev fenge ut alle sauerne sine, gjeng han fyre deim, og sauerne fylgjer honom; for dei kjenner målet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Ein framand vilde dei aldri fylgja; dei vilde røma for honom, av di dei ikkje kjenner målet åt dei framande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Denne likningi fortalde Jesus deim, men dei skyna ikkje kva det var han tala til deim um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'So tala Jesus atter til deim og sagde: «Det segjer eg dykk for visst og sant: Eg er døri som ber inn til sauerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle dei som er komne fyre meg, er tjuvar og røvarar; men sauerne høyrde ikkje på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Eg er døri; den som gjeng inn gjenom meg, skal verta berga, og skal ganga inn og ganga ut og finna beite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Tjuven kjem ikkje for anna enn for di han vilde stela og slagta og øyda; eg er komen for dei skal hava liv og hava nøgdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Eg er den gode hyrdingen; den gode hyrdingen set livet sitt til for sauerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Leigekaren, som ikkje er hyrding, og som sauerne ikkje høyrer til, ser ulven koma, men let sauerne vera der dei er, og rømer, og ulven røvar deim og jagar deim frå einannan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'so gjer leigekaren av di han er ein leigekar, og ikkje hev umsut for sauerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Eg er den gode hyrdingen, og eg kjenner mine, og mine kjenner meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'liksom Faderen kjenner meg, og eg kjenner Faderen; og eg set livet til for sauerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Eg hev andre sauer og, som ikkje høyrer til denne kvii; deim og lyt eg leida, og dei skal lyda røysti mi, og det skal vera ei hjord og ein hyrding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Difor er det Far min elskar meg, for di eg set livet mitt til so eg kann taka det att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Ingen tek det frå meg, eg set det til av meg sjølv. Eg hev magt til å setja det til, og eg hev magt til å taka det att; det bodet fekk eg av far min.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Um desse ordi var det på nytt skilde meiningar millom jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Mange av deim sagde: «Han er forgjord, han er frå vitet! Kvi lyder de på honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Andre sagde: «Dette er ikkje forgjord manns tale! Kann ei vond ånd opna augo på blinde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'So høgtida dei tempelvigsle-helgi i Jerusalem. Det var vinter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'og Jesus gjekk ikring i templet i Salomons-halli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Då flokka jødarne seg rundt ikring honom og sagde til honom: «Kor lenge vil du halda oss i uvissa? Er du Messias, so seg oss det beint ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesus svara: «Eg hev sagt dykk det, og de trur ikkje. Dei verki eg gjer i far min’s namn, dei vitnar um meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'men de trur ikkje, for de høyrer ikkje til mine sauer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Mine sauer lyder røysti mi, og eg kjenner deim, og dei fylgjer meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'og eg gjev deim eit ævelegt liv; dei skal ikkje i all æve forkomast, og ingen skal riva dei ut or handi mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Far min, som hev gjeve meg deim, er større enn alle, og ingen kann riva deim ut or handi åt Far min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Eg og Faderen er eitt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'På nytt lag tok jødarne upp steinar og vilde steina honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Då tok Jesus til ords og sagde: «Mange gilde verk hev eg synt dykk frå far min; - kva for eitt av deim er det de steinar meg for?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, '«For eit gildt verk steinar me deg ikkje,» svara jødarne, «men for gudsspotting, for di du som er eit menneskje, gjer deg sjølv til Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesus svara: «Stend det’kje skrive i lovi dykkar: «Eg hev sagt: «De er gudar?»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Når no lovi kallar deim som Guds ord kom til, for gudar - og Skrifti kann ikkje gjerast um inkje -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'segjer då de til den som Faderen hev helga og sendt til verdi: «Du spottar Gud,» for di eg sagde: «Eg er Guds son?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Gjer eg ikkje verki åt Far min, so tru meg ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Men gjer eg det, so tru verki, um de ikkje trur meg; so skal de skyna og sjå at Faderen er i meg, og eg i honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Då freista dei atter å gripa honom, men han slapp utor henderne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'So for han attende til hi sida av Jordan, til den staden der Johannes fyrst hadde vore og døypt, og der vart han verande ei tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Og kom mange til honom, og dei sagde: «Johannes gjorde fulla ikkje noko teikn, men alt det Johannes sagde um denne mannen, var sant.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Og mange trudde på honom der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Det var ein som låg sjuk, Lasarus frå Betania, den vesle byen som Maria og Marta, syster hennar, budde i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Maria var den som salva Herren med myrrasalve, og turka føterne hans med håret sitt; og det var bror hennar, Lasarus, som låg sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Systerne sende då bod til honom med dei ordi: «Herre, han som du hev so kjær, ligg sjuk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Då Jesus høyrde det, sagde han: «Den sotti er’kje nokor helsott, men ho er til Guds æra; Guds son skal få æra av det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus heldt mykje av Marta og syster hennar og Lasarus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Då han no høyrde at Lasarus låg sjuk, drygde han endå tvo dagar på den staden han var;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'då fyrst sagde han til læresveinarne sine: «Kom, lat oss fara til Judæa att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, '«Rabbi,» sagde læresveinarne, «nyst vilde jødarne steina deg, og so fer du dit att!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, '«Er det’kje tolv timar i dagen?» svara Jesus; «den som gjeng um dagen, snåvar ikkje; for han ser ljoset åt denne verdi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'men den som gjeng um natti, han snåvar, av di han ikkje hev ljoset i seg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'So tala han, og um eit bil segjer han til deim: «Lasarus, venen vår, hev sovna; men no gjeng eg av og vekkjer honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, '«Herre, hev han sovna, so vert han nok god att,» sagde læresveinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesus hadde meint at han var slokna; men dei tenkte han tala um vanleg svevn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Då sagde Jesus reint ut: «Lasarus hev slokna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Og for dykkar skuld er eg glad at eg ikkje var der, so de kann koma til å tru. Men kom, lat oss ganga til honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tomas - han som me kallar Didymus - sagde då til dei andre læresveinarne: «Lat oss ganga med, so me kann døy med honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Då Jesus kom fram, fekk han vita at Lasarus alt hadde lege fire dagar i gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Betania låg ikkje langt frå Jerusalem, berre ein fjordung på lag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'og mange jødar var komne til Marta og Maria, og vilde trøysta dei i sorgi yver broren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Då no Marta høyrde at Jesus kom, gjekk ho til møtes med honom; men Maria sat heime.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Då sagde Marta til Jesus: «Herre, hadde du vore her, so hadde ikkje bror min døytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Men eg veit kor som er, at alt det du bed Gud um, det vil Gud gjeva deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jesus segjer til henne: «Bror din skal standa upp att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, '«Eg veit at han skal standa upp att når alle stend upp, på den siste dag,» svara Marta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Då sagde Jesus til henne: «Eg er uppstoda og livet! Den som trur på meg, skal liva, um han so døyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'og kvar den som liver og trur på meg, skal i all æva ikkje døy. Trur du det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, '«Ja, Herre,» svara ho, «eg hev trutt, og trur, at du er Messias, Guds son, han som skulde koma til verdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Med so sagt gjekk ho av’stad og kalla på Maria, syster si, og sagde til henne i løynd: «Meisteren er her og spør etter deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Då ho høyrde det, reiste ho seg snøgt og gjekk ut til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jesus hadde endå ikkje kome inn i byen; han var endå på den staden der Marta hadde møtt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Då jødarne som var heime hjå Maria og trøysta henne, såg at ho brått reiste seg og gjekk ut, fylgde dei etter henne; dei tenkte ho gjekk ut til gravi og vilde gråta der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Som no Maria kom dit som Jesus var og fekk sjå honom, kasta ho seg ned for føterne hans og sagde: «Herre, hadde du vore her, so hadde ikkje bror min døytt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Då Jesus såg at ho gret, og at jødarne som hadde fylgt henne gret, vart han harm i hugen og øste seg upp og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, '«Kvar hev de lagt honom?» - «Kom og sjå, Herre!» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jesus gret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Då sagde jødarne: «Sjå kor kjær han hadde honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Og sume av deim sagde: «Kunde ikkje han som opna augo på den blinde, ha gjort det so at denne mannen ikkje hadde døytt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Då vart Jesus på nytt harm inni seg og gjekk burt til gravi; det var ein heller, og det låg ein stein attfyre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, '«Tak steinen ifrå!» segjer Jesus. Då segjer Marta, syster åt den avlidne: «Herre, det tevjar alt av honom, for han hev lege der på fjorde dagen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesus segjer til henne: «Sagde eg deg ikkje at dersom du trur, skal du få sjå Guds herlegdom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'So tok dei steinen ifrå. Og Jesus lyfte augo mot himmelen og sagde: «Fader! eg takkar deg for di du hev høyrt meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Eg visste nok at du alltid høyrer meg; men for folket skuld som stend her kringum, segjer eg dette, so dei skal tru at det er du som hev sendt meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Då han det hadde sagt, ropa han med høg røyst: «Lasarus, kom ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Ut kom den daude, med føterne og henderne sveipte i lindar, og med ein sveiteduk bunden kring andlitet. «Løys honom, so han fær ganga!» sagde Jesus til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Mange av jødarne, alle dei som var komne til Maria og hadde set det han gjorde, trudde då på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Nokre av deim gjekk til farisæarane og sagde deim kva Jesus hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Då kalla øvsteprestarne og farisæarane det Høge Rådet i hop til eit møte og sagde: «Kva skal me gjera? Denne mannen gjer mange teikn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Let me honom få halda på soleis, kjem alle til å tru på honom, og då kjem romarane og tek både landet og folket vårt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Og ein av deim, Kajafas - han var øvsteprest det året - sagde til deim:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, '«De veit ingen ting! Ikkje heller tenkjer de på at det er til bate for dykk at ein mann døyr for landslyden, so ikkje heile folket gjeng til grunns.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Det sagde han ikkje av seg sjølv, men av di han var øvsteprest det året, var ordi hans ein spådom um at Jesus skulde døy for folket,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'og ikkje berre for folket, men at han og skulde samla i hop til eitt Guds born som er spreidde ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Frå den dagen lagde dei upp råd um å drepa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Difor gjekk ikkje Jesus lenger fritt ikring millom jødarne, men for derifrå til dei bygderne som ligg tett med øydemarki, til ein by som heiter Efraim; der heldt han til eit bil med læresveinarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'No leid det nær til påskehelgi åt jødarne, og mange for frå bygderne upp til Jerusalem fyre påske og skulde helga seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Då leita dei etter Jesus, og sagde seg imillom med dei stod i templet: «Kva tenkjer de? Kjem han slett ikkje til høgtidi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Men øvsteprestarne og farisæarane hadde gjeve påbod um at dersom nokon fekk vita kvar han var, skulde han segja frå, so dei kunde gripa honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Seks dagar fyre påske kom Jesus til Betania, der Lasarus budde, han som Jesus hadde vekt upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Der gjorde dei eit gjestebod for honom; Marta stelte for deim, og Lasarus var ein av deim som sat til bords med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Då tok Maria eit pund egte, dyr nardesalve og salva føterne åt Jesus, og turka føterne hans med håret sitt; og huset vart fullt av salveangen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'So segjer Judas Iskariot, ein av læresveinarne hans, han som sidan sveik honom:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '«Kvi vart ikkje denne salven seld for eit halvt hundrad dalar, og gjeven til fatigfolk?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Det sagde han ikkje av umsut for dei fatige, men av di han var ein tjuv; det var han som hadde kassa, og han tok jamleg av det som vart lagt ned der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Då sagde Jesus: «Lat henne vera i fred! Det er som ho skulde ha gøymt det til jordferdsdagen min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'For dei fatige hev de alltid hjå dykk, men meg hev de ikkje alltid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'No fekk ei stor mengd av jødarne vita at han var der, og dei kom, ikkje berre for Jesu skuld, men og for å sjå Lasarus, som han hadde vekt upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Då lagde øvsteprestarne upp råd um å drepa Lasarus og;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'for mange av jødarne gjekk for hans skuld dit og kom til å tru på Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Dagen etter spurdest det bland den store folkehopen som var komen til høgtidi, at Jesus var på veg til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Då tok dei palmekvister og gjekk til møtes med honom og ropa: «Hosianna! Velsigna vere han som kjem i Herrens namn, Israels konge!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Jesus fann seg eit ungt asen og sette seg på det, so som skrive stend:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '«Ottast ikkje, Sions dotter! Sjå, her kjem din konung ridand’ sit uppå ein asenfole.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'I fyrstninga skyna ikkje læresveinarne dette; men då Jesus var herleggjord, då kom dei i hug at dette var skrive um honom, og at dei hadde gjort det so for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Folkehopen som var med honom, vitna at han hadde ropa Lasarus ut or gravi og vekt honom upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Difor var det og folket kom imot honom; for dei hadde høyrt at han hadde gjort det teiknet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Då sagde farisæarane seg imillom: «Der ser de: det nyttar dykk inkje; heile verdi flyg etter honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Det var nokre grækarar der, av deim som jamleg for upp og tilbad på høgtidi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'dei kom til Filip, han frå Betsaida i Galilæa, og bad honom: «Gode herre, me vilde so gjerne få sjå Jesus!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filip gjeng og segjer det med Andreas, og Andreas og Filip kjem og segjer det med Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jesus svara deim so: «Timen er komen då Menneskjesonen skal herleggjerast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Det segjer eg dykk for visst og sant: Fell ikkje kveitekornet i jordi og døyr, so er det og vert det berre eitt korn; men døyr det, gjev det stor grøda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Den som elskar livet sitt, misser det, og den som hatar livet sitt i denne verdi, skal berga det til eit ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Um nokon tener meg, so lyt han fylgja meg, og der som eg er, der skal tenaren min og vera; den som tener meg, honom skal Faderen æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'No er sjæli mi full av uro, og kva skal eg segja? «Fader, frels meg frå denne stundi!» Men nei, difor er det eg hev nått til denne stundi -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Fader, herleggjer namnet ditt!» Då kom det ei røyst frå himmelen: «Både hev eg herleggjort det og skal eg på nytt herleggjera det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Folket som stod der og høyrde det, sagde at tora hadde slege. Andre sagde: «Det var ein engel som tala til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Då tok Jesus til ords og sagde: «Det var’kje for mi skuld denne røysti kom, men for dykkar skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'No gjeng det dom yver denne verdi; no skal hovdingen yver denne verdi kastast ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Og når eg vert lyft upp frå jordi, skal eg draga alle åt meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Det sagde han for å syna kva slag avferd han skulde få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Folket svara: «Me hev høyrt av lovi at Messias liver æveleg; korleis hev det seg då at du segjer Menneskjesonen skal lyftast upp? Kven er denne Menneskjesonen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Då sagde Jesus til deim: Endå ei liti stund er ljoset ibland dykk. Gakk so lenge de hev ljoset, so ikkje myrkret skal koma yver dykk! Den som gjeng i myrkret, veit ikkje kvar han kjem av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'So lenge de hev ljoset, so tru på ljoset, so de kann verta born åt ljoset!» Soleis tala Jesus; so gjekk han burt og løynde seg for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Men endå han hadde gjort so mange teikn for augo deira, trudde dei ikkje på honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'det skulde sannast det ordet som profeten Jesaja hev tala: «Herre, kven trudde det bodet me høyrde? Og kven synte Herrens arm seg for?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Difor kunde dei ikkje tru; for ein annan stad hev Jesaja sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '«Han hev gjort augo deira blinde, og hev gjort hugen deira hard, so dei med augo inkje sjå med hjarta inkje skyna skal, og snu so eg deim lækja fær.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'So sagde Jesaja då han såg hans herlegdom og tala um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Like vel var det då mange, jamvel av styresmennerne, som trudde på honom; men dei vilde ikkje kjennast ved det for farisæarane skuld; dei var rædde dei kunde verta utstøytte or synagoga;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'for dei heldt æra hjå menneski gjævare enn æra hjå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Men Jesus ropa ut: «Den som trur på meg, trur ikkje på meg, men på honom som sende meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'og den som ser meg, ser honom som sende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Eg er komen til verdi - eit ljos, so ingen som trur på meg, skal verta verande i myrkret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Um nokon høyrer ordi mine og ikkje tek vare på deim, so dømer ikkje eg honom; for eg er’kje komen på den måten at eg skal døma verdi, men at eg skal frelsa verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Den som vandar meg og ikkje tek imot ordi mine, hev den som dømer honom: det ordet eg hev tala, det skal døma honom på den siste dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'For eg hev ikkje tala av meg sjølv; men Faderen, som sende meg, han hev sagt meg fyre kva eg skal segja og kva eg skal tala;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'og eg veit at hans fyresegn er eit ævelegt liv. So talar eg då det som eg talar heiltupp so som Faderen hev sagt meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Det var straks fyre påskehøgtidi: Jesus visste at hans time var komen då han skulde fara burt frå denne verdi og heim til Faderen, og som han hadde elska sine eigne, som var i verdi, so elska han deim til enden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Då dei heldt kveldverd, og djevelen alt hadde skote det i hugen på Judas Simonsson Iskariot at han skulde svika honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'og då Jesus visste at Faderen hadde gjeve alt i hans hender, og at han var komen frå Gud og gjekk til Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'so reiser han seg frå bordet og legg av seg kjolen sin, og tek eit handklæde og batt um seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'so slær han vatn i vaskarfatet og tok til å två føterne åt læresveinarne og turka dei med handklædet som han hadde bunde kring livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Han kjem då til Simon Peter, og han segjer til honom: «Herre, tvær du mine føter?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus svara honom so: «Kva det er eg gjer, veit du ikkje no, men du skal skyna det sidan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, '«Aldri i verdi skal du två mine føter,» segjer Peter. «Dersom eg ikkje tvær deg, hev du ingen ting i hop med meg,» svara Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Peter segjer til honom: «Herre, ikkje berre føterne, men henderne og hovudet med!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, '«Den som hev lauga seg, treng ikkje två anna enn føterne; elles er han heiltupp rein,» segjer Jesus; «og de er reine, men ikkje alle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Han visste kven som skulde svika honom; difor var det han sagde: «De er’kje reine alle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Då han no hadde tvege føterne deira og teke på seg kjolen sin og sett seg til bords att, sagde han til deim: «Skynar de kva det er eg hev gjort med dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'De kallar meg «Meister» og «Herre,» og det segjer sant; for det er eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Hev no eg, herren og meisteren, tvege føterne dykkar, so lyt de og två føterne åt kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Det er eit mynster eg hev synt dykk; som eg gjorde med dykk, so skal de og gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Det segjer eg dykk for visst og sant: Ein tenar er ikkje større enn herren sin, og ein ærendsvein er ikkje større enn den som hev sendt honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Veit de det, so er de sæle, so sant de gjer etter det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Eg talar ikkje um dykk alle; eg veit kven eg valde ut; men det var so Skrifti skulde sannast: «Den som et mitt brød, hev lyft sin hæl imot meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Eg segjer dykk det alt no, fyrr det hev hendt, so de, når det hender, skal tru at eg er den eg er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Det segjer eg dykk for visst og sant: Den som tek imot ein eg sender, tek imot meg, og den som tek imot meg, tek imot den som sende meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Då Jesus hadde sagt det, vart han uppøst i åndi, og sagde sterkt og ålvorsamt: «Det segjer eg dykk for visst og sant: Ein av dykk kjem til å svika meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Læresveinarne såg på kvarandre og kunde ikkje skyna kven det var han meinte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Ein av læresveinarne - den som Jesus elska - sat ved hans høgre sida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Honom gjer Simon Peter eit teikn til, og segjer til honom: «Seg kven det er han meiner!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Han bøygde seg då næmare innåt Jesus, og segjer til honom: «Herre, kven er det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, '«Det er han som eg gjev den biten eg no duppar i fatet,» svara Jesus. So duppar han biten, og tek og gjev honom til Judas Simonsson Iskariot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Og då han hadde fenge biten, då for Satan i honom. So segjer Jesus til honom: «Gjer det snart, det du vil gjera!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Men ingen av deim som sat med til bords, skyna kva han meinte med det han sagde til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Sidan det var Judas som hadde kassa, tenkte sume at Jesus vilde segja som so: «Kjøp det me treng til høgtidi!» eller at han skulde gjeva noko til dei fatige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Med det same Judas hadde teke mot biten, gjekk han ut. Det var natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Då han var gjengen, sagde Jesus: «No er Menneskjesonen herleggjord, og Gud er herleggjord i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Er Gud herleggjord i honom, so skal Gud og herleggjera honom i seg sjølv, og han skal herleggjera honom snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Berre ei liti stund er eg endå hjå dykk, borni mine. De kjem til å leita etter meg, og som eg sagde til jødarne: «Dit eg gjeng, kann ikkje de koma,» so segjer eg no til dykk og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Eit nytt bod gjev eg dykk: at de skal elska kvarandre; liksom eg hev elska dykk, so skal de og elska kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'På det skal alle skyna at de er mine læresveinar - på det at de hev kjærleik til kvarandre.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Peter segjer til honom: «Herre, kvar gjeng du av?» Jesus svara: «Dit eg gjeng, kann du ikkje fylgja meg no, men du skal fylgja meg sidan.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, '«Kvi kann eg ikkje fylgja deg straks, Herre?» segjer Peter; «eg vil gjeva mitt liv for deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, '«Vil du gjeva ditt liv for meg?» svara Jesus; «det segjer eg deg for visst og sant: Hanen skal ikkje gala fyrr du hev avneitta meg tri gonger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '«Lat ikkje hjarta dykkar uroast! Tru på Gud, og tru på meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'I huset åt Far min er det mange rom; var det’kje so, vilde eg vel då sagt dykk det; for eg gjeng burt og vil stella til ein verestad åt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Og når eg hev gjenge burt og stelt til ein verestad åt dykk, kjem eg att og tek dykk til meg, so de og skal vera der eg er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Og vegen dit eg gjeng, den veit de.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Tomas segjer til honom: «Herre, me veit’kje kvar du gjeng av; korleis kann me då vita vegen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus svarar: «Eg er vegen og sanningi og livet. Ingen kjem til Faderen utan gjenom meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'hadde de kjent meg, so hadde de kjent far min og, og frå denne stund kjenner de honom, og hev set honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filip segjer til honom: «Herre, lat oss få sjå Faderen, so hev me nok!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jesus svarar: «No hev eg vore so lang ei tid i hop med dykk, og du kjenner meg ikkje, Filip? Den som hev set meg, hev set Faderen; korleis kann du då segja: «Lat oss få sjå Faderen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Trur du ikkje at eg er i Faderen, og Faderen er i meg? Dei ordi eg talar til dykk, talar eg ikkje av meg sjølv; men Faderen, som bur i meg, han er det som gjer sine verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Tru meg, når eg segjer at eg er i Faderen, og Faderen i meg! Um ikkje det, so tru meg for sjølve verki skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Det segjer eg dykk for visst og sant: Den som trur på meg, han skal gjera dei same verki som eg gjer, og han skal gjera større verk enn dei. For eg gjeng til Faderen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'og alt de bed um i mitt namn, det vil eg gjera, so Faderen kann verta herleggjord i Sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Bed de meg um noko i mitt namn, so skal eg gjera det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Elskar de meg, so held de bodi mine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'då skal eg beda Faderen, so gjev han dykk ein annan målsmann, som skal vera hjå dykk i all æva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Sannings-Anden, som verdi ikkje kann få, for ho ser honom ikkje og kjenner honom ikkje. De kjenner honom; for han bur hjå dykk og skal vera inni dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Eg vil’kje lata dykk vera att åleine som foreldrelause born; eg kjem til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Um ei liti stund ser verdi meg ikkje lenger; men de ser meg; for eg liver, og de skal liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Den dagen skal de skyna at eg er i far min, og de er i meg, og eg i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Den som hev bodi mine og held deim, han er den som elskar meg, og den som elskar meg, honom skal far min elska, og eg skal elska honom og openberra meg for honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Judas - ikkje Iskariot - segjer til honom: «Herre, kva hev hendt, sidan du vil syna deg for oss og ikkje for verdi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesus svara so: «Um nokon elskar meg, held han seg etter ordet mitt, og far min skal elska honom; og me skal koma til honom og taka vår bustad hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Den som ikkje elskar meg, held seg ikkje etter ordi mine; og ordet de høyrer, er ikkje mitt, men far min’s, som sende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Dette hev eg tala til dykk medan eg endå er hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Men målsmannen, den Heilage Ande, som Faderen skal senda i mitt namn, han skal læra dykk alt og minna dykk på alt det eg hev sagt dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Fred leiver eg åt dykk, min fred gjev eg dykk; eg gjev dykk ikkje fred på den måten som verdi gjer det. Lat ikkje hjarta dykkar uroast og ikkje ræddast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'De høyrde eg sagde til dykk: «Eg gjeng burt og kjem til dykk att;» elska de meg, so gledde de dykk for di eg gjeng til Faderen, for Faderen er større enn eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Og no hev eg sagt dykk det fyrr det hev hendt, so de skal tru når det hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Heretter kjem eg ikkje til å tala mykje med dykk; for no kjem hovdingen yver verdi. I meg eig han ingen ting,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'men eg vil verdi skal sjå at eg elskar Faderen, og gjer so som Faderen hev sagt til meg! Reis dykk, og lat oss ganga ifrå her!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '«Eg er det sanne vintreet, og Far min er vingardsmannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Kvar grein på meg som ikkje ber frukt, tek han burt, og kvar som ber frukt, reinskar han, so ho skal bera meir frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'De er alt reine for skuld ordet som eg hev tala til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Ver i meg, so er eg i dykk! Som greini ikkje kann bera frukt av seg sjølv, men berre når ho er på vintreet, so kann ikkje de heller, utan de er i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Eg er vintreet, de er greinerne. Den som er i meg og eg i honom, han ber mykje frukt; for utan meg kann de ingen ting gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Um nokon ikkje vert verande i meg, vert han kasta ut som ei grein, og visnar; folk sankar deim i hop og kastar deim på elden, og dei brenn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Vert de verande i meg, og vert ordi mine verande i dykk, so bed um kva de vil, og de skal få det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'På den måten vert far min herleggjord, at de ber mykje frukt, og de vert mine læresveinar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Som Faderen hev elska meg, so hev eg elska dykk; ver i min kjærleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Held de bodi mine, so er de i min kjærleik, liksom eg hev halde bodi åt far min, og er i hans kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Dette hev eg tala til dykk so mi gleda kann vera i dykk, og dykkar gleda kann verta fullkomi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Det er bodet mitt, at de skal elska kvarandre, som eg hev elska dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Ingen hev større kjærleik enn at han gjev livet sitt for venerne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'De er venerne mine, so sant de gjer det eg segjer til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Eg kallar dykk ikkje tenarar lenger; for tenaren veit ikkje kva herren hans gjer, men dykk kallar eg vener, for alt eg hev høyrt av far min, hev eg sagt med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'De hev ikkje valt ut meg, men eg hev valt ut dykk, og sett dykk til å ganga ut og bera frukt - frukt som varer ved, so Faderen kann gjeva dykk alt de bed um i mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Det er det eg legg dykk på hjarta, at de skal elska kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Um verdi hatar dykk, so må de vita at ho hev hata meg fyre dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Var de av verdi, so vilde verdi elska sitt eige. Men for di de ikkje er av verdi, men eg hev valt dykk ut or verdi, difor hatar verdi dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Kom i hug det ordet eg sagde dykk: Ein tenar er ikkje større enn herren sin; hev dei forfylgt meg, vil dei forfylgja dykk og; hev dei halde seg etter mitt ord, vil dei halda seg etter dykkar ord og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Men alt dette kjem dei til å gjera mot dykk for mitt namn skuld, av di dei ikkje kjenner den som sende meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Var eg ikkje komen og hadde tala til deim, so hadde dei ikkje synd; men no hev dei ingen ting å orsaka syndi si med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Den som hatar meg, hatar og far min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Hadde eg’kje gjort slike verk bland deim som ingen annan hev gjort, so hadde dei ikkje synd; men no hev dei set deim, og like vel hatar dei både meg og far min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Men det er av di det laut sannast det ordet som er skrive i lovi deira: «Utan orsak hata dei meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Når målsmannen kjem, han som eg vilde senda dykk frå Faderen, Sannings-Anden, som gjeng ut frå Faderen, so skal han vitna um meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Men de og skal vitna; for de hev vore med meg frå det fyrste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '«Dette hev eg tala til dykk, av di eg vil at de ikkje skal koma til å styggjast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Dei kjem til å støyta dykk ut or synagogorne; ja, det kjem ei tid då kvar den som drep dykk, trur at han tener Gud med det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'og det gjer dei av di dei ikkje kjenner Faderen og ikkje meg heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Men dette hev eg tala til dykk, so de, når den tidi kjem, skal koma i hug eg hev sagt dykk det; eg sagde det ikkje med dykk frå det fyrste, av di eg var hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Men no gjeng eg til den som hev sendt meg, og ingen av dykk spør meg: «Kvar gjeng du av?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'men for di eg hev tala dette til dykk, er hjarta dykkar fullt av sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Men eg segjer dykk som sant er: Det er til bate for dykk at eg gjeng burt. For gjeng eg ikkje burt, kjem målsmannen ikkje til dykk; men gjeng eg burt, so skal eg senda honom til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Og når han kjem, skal han yvertyda verdi um synd og um rettferd og um dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Um synd av di dei ikkje trur på meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'um rettferd av di eg gjeng til Faderen, og de ikkje ser meg meir;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'um dom av di hovdingen yver denne verdi er dømd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Endå hev eg mykje å segja dykk, men de kann ikkje bera det no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Men når han kjem, Sannings-Anden, skal han leida dykk fram til heile sanningi; for han skal ikkje tala av seg sjølv, men alt det han høyrer, skal han tala, og det som skal koma, skal han gjera kunnigt for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Han skal herleggjera meg; for det er av mitt han tek og lærer dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Alt det Faderen hev, er mitt; difor sagde eg, at han tek av mitt og lærer dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Um ei lita stund ser de meg ikkje, og um ei liti stund att skal de få sjå meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Då sagde nokre av læresveinarne seg imillom: «Kva meiner han med dette som han segjer til oss: «Um ei liti stund ser de meg ikkje, og um ei liti stund att skal de få sjå meg,» og: «Eg gjeng til Faderen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Kva meiner han med det: ei liti stund,» sagde dei; «me veit ikkje kva han talar um.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jesus skyna at dei vilde spyrja honom, og han sagde til deim: «Er det det de dryfter med kvarandre, at eg sagde: «Um ei liti stund ser de meg ikkje, og um ei liti stund att skal de få sjå meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Det segjer eg dykk for visst og sant: De skal gråta og øya, men verdi skal gleda seg. De skal syrgja, men sorgi dykkar skal vendast til gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Når ei kona skal eiga barn, er ho sutfull av di timen hennar er komen; men når ho hev fenge barnet, kjem ho ikkje lenger i hug kor vondt ho hev lide, so glad er ho for di eit menneskje er født til verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Soleis er de og sutfulle no; men eg skal sjå dykk att; då vert de hjarteglade, og ingen tek gleda dykkar frå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Den dagen skal de ikkje spyrja meg um noko. Det segjer eg dykk for visst og sant: Bed de Faderen um noko, so skal han gjeva dykk det i mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Til dessa hev de ikkje bede um noko i mitt namn - bed, so skal de få, so gleda dykkar kann vera fullkomi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Dette hev eg tala til dykk i likningar. Det kjem ei tid då eg ikkje skal tala til dykk i likningar lenger, men fortelja dykk ope og endefram um Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Den dagen skal de beda i mitt namn, og eg segjer dykk ikkje at eg vil beda Faderen for dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'for Faderen sjølv elskar dykk for di de hev elska meg og trutt at eg hev gjenge ut frå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Eg hev gjenge ut frå Faderen og er komen hit til verdi; no fer eg burt frå verdi att og gjeng til Faderen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Segjer so læresveinarne: «Sjå, no talar du endefram, og segjer ingi likning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'No veit me at du veit alt, og ikkje treng at nokon skal spyrja deg; difor trur me at du er komen frå Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, '«No trur de!» svara Jesus;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, '«sjå, det kjem ei stund - ja, ho er alt komi - då de skal spreidast, kvar til sin heim, og lata meg vera att åleine. Men eg er ikkje åleine; far min er med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Dette hev eg tala til dykk, so de skal hava fred i meg. I verdi hev de trengsel; men ver hugheile! eg hev vunne yver verdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Soleis tala Jesus; so lyfte han augo mot himmelen og sagde: «Fader, timen er komen! Herleggjer son din, so son din kann herleggjera deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'etter di du gav honom magt yver alt kjøt, so han kann lata alle deim du hev gjeve honom få ævelegt liv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'og det er det ævelege livet at dei kjenner deg, den einaste sanne Gud, og den du sende, Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Eg hev herleggjort deg på jordi, og fullført det verket du gav meg å gjera;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'herleggjer no du meg, Fader, hjå deg med den herlegdomen eg hadde hjå deg fyrr verdi var til!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Eg hev openberra ditt namn for dei menneski du gav meg av verdi. Dei var dine, og du gav meg deim, og dei hev halde seg etter ordet ditt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'No veit dei at alt det du hev gjeve meg, er frå deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'for dei ordi du gav meg, hev eg gjeve deim, og dei hev teke imot deim og sanna fullt ut at eg er komen frå deg, og dei trur at du hev sendt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Eg bed for deim; eg bed ikkje for verdi, men for deim som du hev gjeve meg; for dei er dine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'og alt som mitt er, er ditt, og det som ditt er, er mitt, og eg er herleggjord i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Og eg er ikkje lenger i verdi, men dei er i verdi, og eg kjem til deg. Heilage Fader, haldt deim fast i ditt namn, som du hev gjeve meg, so dei kann vera eitt liksom me!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Då eg var hjå deim, heldt eg deim fast i ditt namn, som du hev gjeve meg, og vara deim, og ingen av deim gjekk til grunns so nær som den eine som laut ganga til grunns, so skrifti skulde sannast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Men no kjem eg til deg, og dette talar eg med eg er i verdi, so dei skal hava mi gleda i seg i fullt mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Eg hev gjeve deim ditt ord, og verdi hev lagt deim for hat, for di dei ikkje er av verdi, som eg ikkje er av verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Eg bed ikkje at du skal taka deim burt or verdi, men at du skal vara deim for det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Av verdi er dei ikkje, som eg ikkje er av verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Helga dei i sanningi! Ditt ord er sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Som du hev sendt meg til verdi, so hev eg og sendt deim til verdi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'og eg helgar meg for deim, so dei og skal vera helga i sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Og eg bed ikkje einast for desse men og for deim som kjem til å tru på meg for deira ord skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'at dei alle må vera eitt, som du, Fader, er i meg, og eg er i deg - at dei og må vera i oss - so verdi kann tru at du hev sendt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Eg hev gjeve deim den herlegdomen som du hev gjeve meg, so dei skal vera eitt, liksom me er eitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'eg i deim og du i meg, so dei skal vera fullkomeleg eitt - so verdi kann skyna at du hev sendt meg og elska deim som du hev elska meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Fader, eg vil at dei du hev gjeve meg, dei skal og vera der eg er, vera hjå meg, so dei fær skoda min herlegdom, som du hev gjeve meg av di du hev elska meg fyrr verdi vart grunnlagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Rettferdige Fader, verdi kjenner deg ikkje, men eg kjenner deg, og desse hev kanna at du hev sendt meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'eg hev gjort namnet ditt kunnigt for deim og skal gjera det kunnigt, so den kjærleiken du hev havt til meg, kann vera i deim, og eg sjølv kann vera i deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Då Jesus hadde tala desse ordi, gjekk han ut med læresveinarne sine og yver til hi sida av Kedronsbekken. Der var det ein hage; den gjekk han og læresveinarne inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Men Judas, svikaren, kjende og den staden; for der kom Jesus ofte saman med læresveinarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas hadde fenge med seg vaktmannskapet og nokre av sveinarne åt øvsteprestarne og farisæarane, og no kom han dit med kyndlar og lampor og våpn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Som no Jesus visste alt som skulde koma yver honom, gjekk han fram og sagde til deim: «Kven leitar de etter?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, '«Jesus frå Nasaret,» svara dei. «Det er eg,» segjer han. Judas, svikaren, stod der og saman med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Då han no sagde til deim: «Det er eg», for dei attende og fall til jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'So spurde han deim endå ein gong: «Kven leitar de etter?» - «Jesus frå Nasaret,» sagde dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, '«Eg hev alt sagt dykk at det er eg,» svara Jesus; «er det då meg de leitar etter, so lat desse få ganga!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Soleis skulde det sannast det ordet som han hadde sagt: «Eg hev ikkje mist nokon av deim du gav meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Peter hadde eit sverd; han drog det og hogg til tenaren åt øvstepresten, og sneidde av honom det høgre øyra. Tenaren heitte Malkus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Då sagde Jesus til Peter: «Stikk sverdet ditt i slira! Lyt eg’kje drikka den skåli som Far min hev gjeve meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'So tok dei og batt Jesus - det var vaktmannskapet og hovdingen deira og sveinarne åt jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Dei førde honom fyrst til Annas; for han var verfar åt Kajafas, som var øvsteprest det året.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Det var Kajafas som hadde gjeve jødarne den rådi, at det var best ein mann døydde for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Peter og ein annan læresvein fylgde etter Jesus. Den læresveinen var kjend med øvstepresten, og kom med Jesus inn i garden åt øvstepresten;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'men Peter vart standande utanfor, ved døri. Den andre læresveinen, han som var kjend med øvstepresten, gjekk då ut og tala med gjenta som vakta porten, og fekk Peter inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'So segjer portnargjenta til Peter: «Du skulde vel ikkje og vera ein av læresveinarne åt denne mannen?» «Nei,» svara han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Huskararne og sveinarne hadde gjort upp ein koleld og stod og vermde seg; for det var kaldt. Og Peter stod og hjå deim og vermde seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Øvstepresten spurde no Jesus um læresveinarne hans og um læra hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus svara: «Eg hev tala fritt og ope for all verdi; eg lærde allstødt i synagoga og i templet, der alle jødarne kjem saman, og eg hev aldri tala i løynd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Kvi spør du meg? Spør deim som hev høyrt meg, kva det er eg hev tala til deim! Dei veit kva eg hev sagt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Då han sagde det, gav ein av sveinarne som stod innmed, Jesus eit slag i andlitet og sagde: «Svarar du øvstepresten so?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, '«Hev eg sagt noko urett,» svara Jesus, «so prova at det er urett; men var det rett det eg sagde, kvi slær du meg då?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'So sende Annas han bunden av stad til Kajafas, øvstepresten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Medan stod Simon Peter og vermde seg. Då sagde dei til honom: «Du skulde vel ikkje vera ein av læresveinarne hans, du og?» Han neitta det og sagde: «Nei, det er eg ikkje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'So segjer ein av huskararne åt øvstepresten - han var skyld den som Peter hadde hogge øyra av -: «Såg eg deg ikkje sjølv i lag med honom i hagen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Då neitta Peter att. Og med det same gol hanen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Frå Kajafas fører dei Jesus til borgi. Det var tidleg på morgonen. Sjølve gjekk dei ikkje inn i borgi; for dei vilde ikkje gjera seg ureine, so dei ikkje kunde eta påskematen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'So gjekk Pilatus ut til deim og sagde: «Kva er det for klagemål de fører mot denne mannen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, '«Var han ikkje ein illgjerdsmann, so hadde me ikkje gjeve honom yver til deg,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Då sagde Pilatus til deim: «Tak de honom og døm honom etter lovi dykkar!» «Me hev ikkje lov til å taka livet av nokon,» svara jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Soleis skulde det sannast det ordet Jesus hadde sagt då han vitra um kva slag avferd han skulde få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'So gjekk Pilatus inn i borgi att; han kalla Jesus fyre seg og sagde til honom: «Er du kongen yver jødarne?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus svara: «Segjer du det av deg sjølv, eller hev andre tala soleis til deg um meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, '«Er då eg ein jøde?» svara Pilatus; «folket ditt og øvsteprestarne hev gjeve deg yver til meg. Kva hev du gjort?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus svara: «Mitt rike er ikkje av denne verdi; var riket mitt av denne verdi, so vilde sveinarne mine strida for meg, so eg ikkje skulde koma i henderne på jødarne. Men no er’kje riket mitt av denne verdi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, '«Men so er du då ein konge?» sagde Pilatus. Jesus svara: «Det er som du segjer; eg er ein konge. Til det er eg fødd, og til det er eg komen til verdi, at eg skal vitna for sanningi. Kvar den som er av sanningi, lyder på mi røyst.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, '«Kva er sanning?» svara Pilatus, og med so sagt gjekk han ut att til jødarne og sagde til deim: «Eg finn ingi skuld hjå honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'men de er vane med at eg gjev dykk ein fri på påskehøgtidi - vil de då at eg skal gjeva dykk kongen yver jødarne fri?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Men dei ropa alle på nytt: «Ikkje han, men Barabbas!» Barabbas, det var ein røvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Då tok Pilatus og let deim hudfletta Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Og hermennerne fletta ein krans av klunger og sette på hovudet hans og kasta ei purpurkåpe um honom, og gjekk fram for honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, '«Heil, konge yver jødarne!» og slo til honom i andlitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilatus gjekk ut att og sagde til deim: «Her kjem eg ut til dykk med honom, so de skal vita at eg ikkje finn nokor skuld hjå honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'So kom Jesus ut med klungerkransen på og purpurkåpa, og Pilatus segjer til deim: «Sjå det menneskjet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Med det same dei fekk sjå honom, øvsteprestarne og sveinarne deira, skreik dei: «Krossfest, krossfest!» Pilatus segjer til deim: «Tak de og krossfest honom! Eg finn ingi skuld hjå honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Jødarne svara: «Me hev ei lov; etter den lyt han døy, for di han hev gjeve seg ut for Guds Son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Då Pilatus høyrde det ordet, vart han endå ræddare;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'han gjekk inn att i borgi og spurde Jesus: «Kvar er du ifrå?» Men Jesus gav han ikkje noko svar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilatus segjer til honom: «Svarar du meg ikkje? Veit du’kje at eg hev magt til å gjeva deg fri og hev magt til å krossfesta deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus svara: «Du hadde ingi magt yver meg, var det’kje gjeve deg ovantil. Difor hev han større synd den som gav meg yver til deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Frå den stundi vilde Pilatus gjerne gjeva honom fri. Men jødarne ropa: «Gjev du honom fri, er du ikkje ven med keisaren. Kvar den som gjer seg sjølv til konge, set seg upp imot keisaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Då Pilatus høyrde dei ordi, førde han Jesus ut og sette seg i domarsætet, på den staden dei kallar Tavletilet - på hebraisk heiter det Gabbata -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Det var då fyrebuingsdagen i påskehelgi, og var um lag den sette timen. So segjer han til jødarne: «Sjå her er kongen dykkar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Då ropa dei: «Burt, burt med honom! Krossfest han!» «Skal eg krossfesta kongen dykkar?» segjer Pilatus. «Me hev ingen konge utan keisaren,» svara øvsteprestarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Då gav han Jesus yver til deim, so han skulde krossfestast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'So tok dei Jesus med seg. Han bar sjølv krossen sin, og gjekk ut til Skallestaden dei kallar - på hebraisk kallast det Golgata -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Der feste dei honom til krossen, og saman med honom tvo andre, ein på kvar sida, og Jesus midt imillom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatus skreiv og ei innskrift og sette på krossen; ho lydde so: Jesus frå Nasaret, kongen yver jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Den innskrifti las då mange av jødarne; for staden der Jesus vart krossfest, var tett utmed byen, og det var skrive på hebraisk og latin og gresk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Då sagde øvsteprestarne åt jødarne til Pilatus: «Skriv ikkje: Kongen yver jødarne, men: Han sagde: «Eg er konge yver jødarne!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, '«Det eg hev skrive, hev eg skrive,» svara Pilatus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Då hermennerne hadde fest Jesus til krossen, tok dei klædi hans og skifte i fire luter, ein for kvar hermann. Kjolen tok dei og. Kjolen var usauma og heilvoven alt ovantil;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'difor sagde dei seg imillom: «Lat oss ikkje riva honom sund, men draga strå um kven som skal hava honom!» Soleis skulde skrifti sannast: «Dei skifte klædi mine millom seg, og kasta lut um kjolen min.» So gjorde no hermennerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Men innmed krossen åt Jesus stod mor hans og morsyster hans, Maria, kona hans Klopas, og Maria Magdalena.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Og då Jesus såg mor si, og såg at den læresveinen som han elska, stod der innmed, segjer han til mori: «Kvinna, der er son din!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'So segjer han til læresveinen: «Der er mor di!» Og frå den stundi tok læresveinen henne heim til seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Då visste Jesus at no var alt fullført, so skrifti skulde sannast; so segjer han: «Eg er tyrst.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Det stod eit kjer der som var fullt av vineddik; so fyllte dei ein svamp med den ediken, og sette honom på ein bergmynte-stylk og heldt honom upp til munnen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Då Jesus hadde fenge ediken, sagde han: «Det er fullført!» og han bøygde hovudet og gav andi si yver til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Etter di det no var fyrebuingsdagen, og liki ikkje måtte verta hangande på krossen um kviledagen - for den kviledagen var storheilag - so bad jødarne Pilatus at beini måtte brjotast sund på deim, og at dei måtte takast ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Då kom hermennerne og braut sund beini, både på den fyrste og den andre som hadde vorte krossfeste i hop med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Då dei kom til Jesus, og såg at han alt var slokna, braut dei ikkje hans bein sund;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'men ein av hermennerne stakk honom i sida med eit spjot, og straks kom det ut blod og vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Dette vitnar ein som hev set det, og vitnemålet hans er sætande; han veit sjølv at han segjer sant, so de og må tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'For dette hende av di Skrifti laut sannast: «Det skal’kje brjotast sund eit bein på honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Og eit anna skriftord att lyder so: «Dei skal sjå burt på honom som dei hev gjenomstunge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Sidan kom Josef frå Arimatæa, som var ein av læresveinarne åt Jesus, men dulde for det, av di han var rædd jødarne; han bad Pilatus um han måtte få taka likamen åt Jesus, og Pilatus gav honom lov til det. So kom han og henta likamen hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Nikodemus, han som fyrst var komen til honom um natti, kom og, og hadde med seg ei blanding av myrra og aloe, um lag hundrad pund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'So tok dei likamen åt Jesus og sveipte honom med lindar og lagde dei angande kryddorne imillom, soleis som jødarne hev for vis når dei bur ein til likferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'På den staden han vart krossfest var det ein hage, og i hagen ei ny grav, som det endå aldri hadde vorte sett ned nokon i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Der lagde dei då Jesus, av di det var fyrebuingsdagen åt jødarne, og gravi var nær innmed.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Tidleg den fyrste dagen i vika, medan det endå var myrkt, kjem Maria Magdalena til gravi, og ser at steinen er teken burt frå gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Ho spring av stad, og kjem til Simon Peter og den andre læresveinen, han som Jesus elska, og segjer til deim: «Dei hev teke Herren ut or gravi, og me veit ikkje kvar dei hev lagt honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Då tok dei ut, både Peter og den andre læresveinen, og gav seg på vegen til gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Dei sprang båe saman; so sprang den andre læresveinen fyre, forare enn Peter, og kom fyrst til gravi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Han lutte seg ned og glytte inn; då såg han at lindarne låg der; men han gjekk ikkje inn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'So kjem Simon Peter etter, og gjekk inn i gravi. Han ser lindarne liggja der;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'men sveiteduken, som Jesus hadde havt kring hovudet, låg ikkje saman med lindarne, men på ein stad for seg sjølv, og var balla i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Då gjekk den andre læresveinen og inn, han som var komen fyrst til gravi, og han såg og trudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'For dei skyna endå ikkje skrifti, at han skulde standa upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'So gjekk læresveinarne heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Men Maria stod utanfor ved gravi og gret. Som ho no gråtande lutte seg ned og glytte inn i gravi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'fær ho sjå tvo kvitklædde englar sitja der, ein ved hovudet og ein ved føterne, der likamen åt Jesu hadde lege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Dei segjer til henne: «Kvi græt du, kvinna?» Ho svarar: «For di dei hev teke Herren min burt, og eg veit ikkje kvar dei hev lagt honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Med so sagt snudde ho seg, og då ser ho Jesus stend der, men ho visste ikkje at det var han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jesus segjer til henne: «Kvi græt du, kvinna? Kven leitar du etter?» Ho tenkte det var hagemeisteren, og segjer til honom: «Herre, er det du som hev bore han burt, so seg meg kvar du hev lagt honom; då vil eg henta honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, '«Maria!» segjer Jesus. Då snur ho seg, og segjer til honom på hebraisk: «Rabbuni!» det er på vårt mål: «Meister!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, '«Kom ikkje nær meg!» segjer Jesus; «for endå hev eg ikkje fare upp til far min. Men gakk til brørne mine, og seg deim frå meg: No fer eg upp til honom som er min Fader og dykkar Fader, og min Gud og dykkar Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdalena kjem og segjer til læresveinarne: «Eg hev set Herren,» og at han hadde sagt dette til henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Då det vart kveld same dagen - den fyrste i vika - og dørerne var stengde der læresveinarne var, av di dei var rædde jødarne, kom Jesus og stod midt ibland deim og segjer: «Fred vere med dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'og då han hadde sagt det, synte han deim henderne sine og sida si. Læresveinarne vart glade då dei såg Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Og han sagde endå ein gong: «Fred vere med dykk! Som Faderen hev sendt meg, so sender eg dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Med desse ordi anda han på deim og sagde til deim: «Tak imot den Heilage Ande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Tilgjev de nokon synderne deira, so er dei tilgjevne; held de dei att for nokon, so er dei atthaldne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Tomas, ein av dei tolv, han som me kallar Didymus, var ikkje saman med deim då Jesus kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'So sagde dei andre læresveinarne med honom: «Me hev set Herren.» Han svara: «Det trur eg ikkje fyrr eg fær sjå naglemerket i henderne hans og fær stinga fingeren min i nagleholet og fær stinga handi mi i sida hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Åtte dagar etter var læresveinarne hans inne att, og Tomas var med deim. Dørerne var stengde. Då kom Jesus og stod midt ibland deim og sagde: «Fred vere med dykk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'So segjer han til Tomas: «Kom hit med fingeren din, og sjå på henderne mine, og kom hit med handi di og stikk henne i sida mi, og ver ikkje vantruen, men truande!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, '«Min Herre og min Gud!» svara Tomas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jesus segjer til honom: «Sidan du hev set meg, trur du! Sæle dei som ikkje ser og endå trur!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Endå mange andre teikn gjorde Jesus for augo åt læresveinarne sine, teikn som ikkje er skrive i denne boki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Men desse er skrivne so de skal tru at Jesus er Messias, Guds Son, og so de som trur skal hava liv i hans namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Sidan openberra Jesus seg endå ein gong for læresveinarne ved Tiberiassjøen. Med det gjekk det soleis til:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Peter og Tomas - han som me kallar Didymus - og Natanael - han frå Kana i Galilæa - og Sebedæus-sønerne og tvo andre av læresveinarne var der i hop.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Då segjer Simon Peter til deim: «Eg gjeng’stad å fiska.» «Me vil og med,» segjer dei. So tok dei ut og steig i båten; men den natti fekk dei’kje noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'I det bilet det tok til å dagast, stod Jesus med ein gong på strandi; men læresveinarne visste ikkje at det var han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jesus segjer til deim: «De hev vel ikkje noko å eta, born?» «Nei,» svara dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, '«Kasta garnet på høgre sida av båten, so fær de fisk,» sagde han. Dei so gjorde, og då var dei ikkje god til å draga garnet, so mykje fisk var der i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Då segjer den læresveinen som Jesus elska, til Peter: «Det er Herren!» Med det same Simon Peter fekk høyra at det var Herren, tok han kjolen sin på seg - for han hadde lagt honom av - og kasta seg i sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Og dei andre læresveinarne kom med båten, og slæpte garnet med fiskarne etter seg; for dei var ikkje langt ifrå land, berre tvo hundrad alner på lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Då dei steig i land, ser dei ein glohaug som ligg der med fisk på og brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, '«Kom hit med noko av den fisken de fekk!» segjer Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Då steig Simon Peter ut i båten og drog garnet på land; det var fullt av store fiskar, hundrad og tri og femti; men endå det var so mange, gjekk ikkje garnet sund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, '«Kom hit og få dykk ein morgonbite!» segjer Jesus. Ingen av læresveinarne våga å spyrja honom: «Kven er du?» dei visste at det var Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Då kom Jesus, og tok brødet og gav deim, og like eins fisken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Dette var no tridje gongen Jesus openberra seg for læresveinarne etter at han hadde stade upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Som dei no hadde ete morgonverden, segjer Jesus til Simon Peter: «Simon Johannesson, elskar du meg meir enn desse?» «Ja, Herre,» svarar han; «du veit at eg held av deg.» «Fød lambi mine!» segjer Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'So segjer han til honom att, andre gongen: «Simon Johannesson, elskar du meg?» Han svarar: «Ja, Herre, du veit eg held av deg.» «Gjæt sauerne mine» segjer Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'So segjer han til honom tridje gongen: «Simon Johannesson, held du av meg?» Peter tykte det leidt at han spurde honom tridje gongen: «Held du av meg?» Han svara: «Herre, du veit alt, du veit at eg held av deg.» Jesus segjer til han: «Fød sauerne mine!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, '«Det segjer eg deg for visst og sant: Då du var yngre, batt du sjølv livgjordi um deg og gjekk dit du vilde; men når du vert gamall, skal du retta ut henderne dine, og ein annan skal binda livgjordi um deg og føra deg dit du ikkje vil.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Det sagde han for å vitra um kvaslags daude han skulde koma til å æra Gud med. Då han hadde sagt det, segjer han til honom: «Fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Då Peter snudde seg, ser han at den læresveinen som Jesus elska, fylgde med, han som hadde sete tett innmed honom då dei heldt nattverd, og spurt: «Herre, kven er den som svik deg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Då Peter såg honom, segjer han til Jesus: «Herre, korleis skal det so ganga honom?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jesus svarar: «Um eg vil at han skal liva til eg kjem, kva hev so du med det? Fylg du meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Soleis kom det ordet ut bland brørne: «Den læresveinen døyr ikkje.» Men Jesus sagde ikkje til honom at han ikkje skulde døy; det han sagde var: «Um eg vil at han skal liva til eg kjem, kva hev so du med det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Det er den læresveinen som vitnar um desse ting og hev skrive dette, og me veit at vitnemålet hans er sant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Det er endå mykje anna som Jesus hev gjort. Skulde det skrivast upp, kvar ting for seg, trur eg ikkje heile verdi vilde røma dei bøkerne som då laut skrivast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Den fyrste boki skreiv eg, Teofilus, um alt det som Jesus tok til med både å gjera og læra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'alt til den dagen då han vart uppteken, etter at han ved den Heilage Ande hadde gjeve sine bod til apostlarne som han hadde valt seg ut,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'deim som han og steig livande fram for med mange yvertydande teikn, etter han hadde lide, med di han i fyrti dagar synte seg for deim og tala um det som høyrer til Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Og då han var saman med deim, baud han deim at dei ikkje skulde vika frå Jerusalem, men venta på det som Faderen hadde lova, «som de,» sagde han, «hev høyrt av meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'For Johannes døypte med vatn, men de skal verta døypte med den Heilage Ande um ikkje mange dagar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Då dei no var saman, spurde dei honom og sagde: «Herre, reiser du på den tidi riket upp att for Israel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Han sagde til deim: «Det er ikkje dykkar sak å vita tid eller stund som Faderen hev sett i si eigi magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Men de skal få kraft når den Heilage Ande kjem yver dykk; og de skal vera mine vitne i Jerusalem og i heile Judæa og Samaria og til ytste enden av jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Og då han hadde sagt dette, for han upp so dei såg på; og ei sky tok honom burt for augo deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Og som dei no stod og stirde mot himmelen då han for burt, sjå, då stod det tvo menner hjå deim i kvite klæde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'og dei sagde: «Menner frå Galilæa, kvi stend de og ser upp mot himmelen? Denne Jesus som er teken upp frå dykk til himmelen, han skal koma att på same måten som de såg honom fara til himmels.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Då vende dei um til Jerusalem frå det berget som er kalla Oljeberget, og som er nær Jerusalem, ein kviledagsveg derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Og då dei kom inn der, gjekk dei upp på salen der dei heldt til - både Peter og Johannes og Jakob og Andreas, Filip og Tomas, Bartolomæus og Mattæus, Jakob, Alfæus’ son, og Simon Selotes og Judas, Jakobs bror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Alle desse heldt samstendige ved i bøn saman med nokre kvinnor og Maria, Jesu mor, og brørne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Og i dei dagarne stod Peter upp midt imillom læresveinarne - og der var ein hop saman på umkring hundrad og tjuge - og han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '«Brør! Det laut verta uppfyllt det skriftordet som den Heilage Ande fyreåt tala gjenom Davids munn um Judas, som vart vegvisar for deim som greip Jesus;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'for han var rekna med millom oss og fekk lut i denne tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Han kjøpte seg då ein åker av løni for si ugjerning, og då han stupte ned, og sprakk han midt i tvo, og all innvolen i honom valt ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Og det vart kunnigt for alle deim som bur i Jerusalem, so at den åkeren på deira mål fekk namnet Hakeldama, det er: Blodåkeren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'for det stend skrive i Salmeboki: «Hans bustad verte øydd, og ingen mann bu der,» og: «Ein annan take hans embætte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Difor må ein av dei menner som hev vore med oss heile tidi då Herren Jesus gjekk inn og ut millom oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'alt frå Johannes-dåpen til den dagen han vart uppteken frå oss - ein av desse må verta vitne saman med oss um hans uppstoda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Og dei stelte fram tvo: Josef som vart kalla Barsabbas med tilnamnet Justus, og Mattias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Og dei bad og sagde: «Herre, du som kjenner hjarto i alle, syn oss den som du hev valt ut av desse tvo');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'til å få lut i denne tenesta og apostelgjerning som Judas gjekk burt ifrå til å fara til sin egen stad!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Og dei kasta lut millom deim, og luten fall på Mattias, og han vart rekna saman med dei elleve apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Og då kvitsunndagen var komen, var dei alle samla på same staden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Då kom det brått frå himmelen ein ljod som av ein framstormande sterk vind og fyllte heile huset der dei sat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Og det synte seg for deim tungor liksom av eld, som skilde seg og sette seg på kvar ein av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Då vart dei alle fyllte med den Heilage Ande, og dei tok til å tala med andre tungor, etter som Anden gav deim å tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'No budde det i Jerusalem jødar, gudlege menner frå alle folk under himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Då so denne ljoden vart høyrd, kom mengdi saman og vart forfjamsa; for kvar mann høyrde deim tala på hans eige mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Og dei vart forfærde og undra seg og sagde: «Høyr her, er ikkje alle desse som talar, galilæarar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'og korleis kann me då høyra deim tala kvar på vårt eige mål, som me er fødde i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'folk frå Partia og Media og Elam, og me som bur i Mesopotamia og i Judæa og Kappadokia, Pontus og Asia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frygia og Pamfylia, Egyptarland og Libyalandet ved Kyrene, og me tilreisande frå Rom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'både jødar og jødetruande, me frå Kreta og Arabia: me høyrer deim tala um Guds store verk på våre tungemål!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Men dei vart alle forfærde og rådville og sagde den eine til den andre: «Kva skal då dette vera?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Men andre sagde spottande: «Dei er fulle av søt vin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Då stod Peter fram med dei elleve, lyfte røysti og tala til deim: «De jødiske menner og alle de som bur i Jerusalem! dette vere dykk kunnigt, og merk mine ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'For desse er ikkje drukne, so som de trur - det er då den tridje timen på dagen -.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Men dette er det som er sagt gjenom profeten Joel:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '«Og det skal vera so i dei siste dagar, segjer Gud, då vil eg renna min Ande ut yver alt kjøt, og sønerne dykkar og døtterne dykkar skal tala profetord, og dei unge gutarne dykkar skal sjå syner, og dei gamle mennerne dykkar skal drøyma draumar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Ja, endå på trælarne mine og trælkvinnorne mine vil eg renna ut av min Ande i dei dagarne, og dei skal tala profetord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Og eg vil syna under på himmelen i det høge og teikn på jordi i det låge: blod og eld og røykdimma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Soli skal verta til myrker og månen til blod, fyrr Herrens dag kjem, den store og herlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Og det skal vera so at kvar den som kallar på Herrens namn, han skal verta frelst.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Israelitiske menner, høyr desse ordi: Jesus frå Nasaret, ein mann som av Gud var stadfest for dykk ved velduge gjerningar og under og teikn, som Gud gjorde ved honom midt imillom dykk, so som de og sjølve veit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'han som vart yvergjeven etter Guds fastsette rådgjerd og fyrevitende, honom tok de og krossfeste med urettferdigt folks hender og slo honom i hel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'men Gud uppreiste honom med di han løyste daudens rider, av di det ikkje var mogelegt at han kunde verta halden fast av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'For David segjer um honom: «Eg hadde alltid Herren framfor augo mine; for han er ved mi høgre hand, so eg ikkje skal verta rikka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Difor gledde mitt hjarta seg, og mi tunga fagna seg; ja endå mitt kjøt skal kvila trygt i von;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'for du skal ikkje yverlata mi sjæl i helheimen og ikkje lata din heilage sjå undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du hev kunngjort meg livsens vegar; du skal fylla meg med fagnad for di åsyn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Brør! lat meg tala beint ut til dykk um patriarken David, at han både døydde og vart gravlagd, og hans grav er hjå oss den dag i dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Då han no var ein profet, og visste det som Gud hadde svore ved ein eid, at han av frukti utav hans lend vilde setja ein på hans kongsstol,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'so tala han framsynt um Messias’ uppstoda det ordet at han ikkje vart yverlaten i helheimen, og ikkje heller hans kjøt såg undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Denne Jesus reiste Gud upp, som me alle er vitne um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Då han no er upphøgd ved Guds høgre hand og av Faderen hev fenge den Heilage Ande som var lova, so hev han rent dette ut, som de både ser og høyrer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'For David for ikkje upp til himmelen; men han segjer: «Herren sagde til min Herre: «Set deg ved mi høgre hand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'til dess eg fær lagt dine fiendar til skammel under dine føter!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'So skal då heile Israels hus vita for visst, at Gud hev gjort honom både til Herre og til Messias, denne Jesus som de krossfeste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Men då dei høyrde det, gav det som ein styng i hjarta deira, og dei sagde til Peter og dei andre apostlarne: «Brør, kva skal me gjera?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Men Peter sagde til deim: «Vend um, og kvar av dykk late seg døypa på Jesu Kristi namn til forlating for synderne, og de skal få den Heilage Ande til gåva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'For lovnaden høyrer dykk til og dykkar born og alle deim som er langt burte, so mange som Herren, vår Gud, kallar til.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Og med mange andre ord vitna han og lagde deim det på hjarta og sagde: «Lat dykk frelsa frå denne rangsnudde ætti!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Dei som no tok imot hans ord, dei vart døypte, og den dagen vart det lagt til umkring tri tusund sjæler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Og dei heldt trutt fast ved læra åt apostlarne og samfundet og brødbrjotingi og bønerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Og der kom otte på kvar sjæl, og det vart gjort mange under og teikn ved apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Og alle dei truande heldt seg saman og hadde allting til sameiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Og eigedomarne sine og godset selde dei og skifte det ut til alle, etter som nokon hadde trong til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Og kvar dag søkte dei samheldigt templet og braut brødet heime og fekk seg føda med fagnad og hjartans einfelde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'medan dei lova Gud og hadde ynde hjå alt folket. Men kvar dag lagde Herren til kyrkjelyden deim som let seg frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Men Peter og Johannes gjekk saman upp i templet i bønetimen, den niande timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Og ein mann som var vanfør frå mors liv, vart boren fram; og dei sette honom kvar dag ved den tempeldøri som er kalla den fagre, so han kunde beda um sælebotsgåva av deim som gjekk inn i templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Då han såg Peter og Johannes, som vilde ganga inn i templet, bad han um å få ei sælebotsgåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Men Peter feste augo på honom, saman med Johannes, og sagde: «Sjå på oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Han stirde på deim og venta å få noko av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Men Peter sagde: «Sylv og gull hev eg ikkje; men det eg hev, det gjev eg deg: i nasaræaren Jesu Kristi namn statt upp og gakk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'So greip han honom ved høgre handi og reiste honom upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Men straks vart føterne hans og oklo sterke, og han sprang upp og stod og gjekk ikring; og han gjekk med deim inn i templet, gjekk ikring der og sprang og lova Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Og alt folket såg honom ganga ikring og lova Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Og dei kjende honom, at det var han som hadde sete etter sælebotsgåva ved den fagre tempeldøri. Og dei vart fulle av undring og rædsla yver det som hadde hendt med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Med han heldt seg til Peter og Johannes, strøymde alt folket saman um deim i den sulehalli som er kalla Salomons, og dei var forstøkte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Då Peter det såg, svara han folket: «Israelitiske menner, kvi undrast de på dette, eller kvi stirer de so på oss, som um me av vår eigi magt eller gudlegdom hadde gjort at han kann ganga?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Abrahams og Isaks og Jakobs Gud, vår fedregud, hev herleggjort sin tenar Jesus, han som de sveik og forneitta for Pilatus, då han dømde at han skulde verta fri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Men de forneitta den heilage og rettferdige, og bad um at ein mordar måtte verta dykk unnt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Men livsens hovding slo de i hel, han som Gud reiste upp frå dei daude, som me er vitne til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Og ved trui på hans namn hev hans namn styrkt denne mannen, som de ser og kjenner; og trui som er verka ved honom, gav denne mannen hans fulle helsa for augo på dykk alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Og no, brør, eg veit at de hev gjort det i vankunna, liksom og rådsherrarne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Men Gud uppfylte soleis det som han fyreåt sagde gjenom munnen til alle sine profetar, at hans Messias skulde lida.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'So gjer då bot og vend um, so synderne dykkar må verta utstrokne, so at hugsvalings tider kann koma frå Herrens åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'og han kann senda den Messias som er utkåra åt dykk, Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'han som himmelen skal hysa til tidi for atterreisingi av alle ting, som Gud hev tala um gjenom munnen til sine heilage profetar frå gamle dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'For Moses hev sagt: «Herren, dykkar Gud, skal reisa upp åt dykk ein profet av dykkar brør liksom eg; honom skal de høyra i alt det som han talar til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Og det skal bera so til, at kvar den sjæl som ikkje høyrer den profeten, skal verta utrudd or folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Men ogso alle profetarne frå Samuel og sidan, so mange som hev tala, dei hev og forkynt um desse dagarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'De er born åt profetarne og åt den pakti som Gud gjorde med våre feder, då han sagde til Abraham: «Og i di ætt skal alle ætter på jordi velsignast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'De var dei fyrste som Gud sende tenaren sin til, då han let honom koma fram for at han skulde velsigna dykk, med di kvar av dykk vender seg frå sin vondskap.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Men medan dei tala til folket, kom prestarne og hovudsmannen for tempelvakti og sadducæarane yver deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'då dei harma seg yver at dei lærde folket og forkynte i Jesus uppstoda frå dei daude;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'og dei lagde hand på deim og sette deim i fengsel til næste dagen; for det var alt kveld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Men mange av deim som hadde høyrt ordet, kom til tru, og talet på mennerne vart umkring fem tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'So hende det seg dagen etter, at deira rådsherrar og styresmenner og skriftlærde kom saman i Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'og med deim øvstepresten Annas og Kajafas og Johannes og Aleksander, og so mange som var av øvstepresteleg ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Og dei stelte deim fram for seg og spurde: «Kva kraft eller kva namn gjorde de dette ved?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Då sagde Peter til deim, fyllt av den Heilage Ande: «De rådsherrar for folket og Israels styresmenner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Når me i dag vert forhøyrde um ei velgjerning mot ein vanfør mann, kva han er lækt ved,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'so skal det vera kunnigt for dykk alle og heile Israels folk, at ved nasaræaren Jesu Kristi namn, han som de krossfeste, men som Gud reiste upp frå dei daude, ved honom stend denne frisk for dykkar augo.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Han er den steinen som vart forsmådd av dykk, bygningsmenner, men som vart til hyrnestein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Og ikkje er det frelsa i nokon annan; for ikkje er der heller noko anna namn under himmelen, gjeve millom menneskje, som me skal verta frelste ved.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Men då dei såg slikt frimod hjå Peter og Johannes, og fekk vita at dei var ulærde lækfolk, undra dei seg; og dei kjende deim, at dei hadde vore med Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Men då dei såg den mannen som hadde vorte lækt, standande hjå deim, hadde dei ikkje noko å segja imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Men dei baud deim ganga ut ifrå rådet, og dei samrådde seg med kvarandre og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, '«Kva skal me gjera med desse menneskje? for at eit audkjent teikn er gjort ved deim, det er synbert for alle deim som bur i Jerusalem, og me kann ikkje neitta det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Men for at det ikkje skal verta bore vidare utyver til folket, so lat oss strengt påleggja deim at dei ikkje meir må tala til noko menneskje i dette namnet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'So kalla dei deim inn og baud deim at dei slett ikkje måtte tala eller læra i Jesu namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Men Peter og Johannes svara og sagde til deim: «Døm sjølve, um det er rett for Guds åsyn å lyda dykk meir enn Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'for me kann ikkje anna enn tala um det som me hev set og høyrt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Dei truga deim då endå meir og let deim ganga, då dei ikkje kunde finna nokor råd til å refsa deim for folket skuld; for alle lova Gud for det som hendt var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'For han var meir enn fyrti år gamall den mannen som dette lækjedoms-teiknet hadde hendt med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Då dei so slapp lause, kom dei til sine eigne og fortalde det som øvsteprestarne og styresmennerne hadde sagt til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Då dei høyrde det, lyfte dei samlyndt si røyst til Gud og sagde: «Herre, du som gjorde himmelen og jordi og havet og alt det som i deim er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'du som sagde gjenom din tenar Davids munn: «Kvifor rasa heidningarne og lagde folki fåfengde råd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Kongarne på jordi reiste seg, og hovdingarne samla seg saman imot Herren og imot den han salva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Ja, i sanning, i denne byen slo dei seg saman mot din heilage tenar Jesus, som du salva, både Herodes og Pontius Pilatus med heidningarne og Israels folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'til å gjera det som di hand og di råd fyreåt hadde fastsett skulde hendast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Og no, Herre! sjå til deira trugsmål, og gjev dine tenarar å tala ditt ord med alt frimod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'med di du retter ut di hand til lækjing og teikn og under ved din heilage tenar Jesu namn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Og då dei hadde bede, skalv romet der dei var samankomne, og alle vart fyllte med den Heilage Ande, og dei tala Guds ord med frimod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Men heile mengdi av dei truande hadde eitt hjarta og ei sjæl. Og ikkje ein sagde at noko av hans gods var hans eige; men dei hadde alle ting til sameiga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Og med stor kraft bar apostlarne vitne um Herren Jesu uppstoda, og stor nåde var yver deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'For det var ikkje heller nokon trengande millom deim; for so mange som åtte jord eller hus, selde deim og bar fram pengeverdet for det som dei hadde selt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'og lagde det for føterne på apostlarne; og det vart utskift til kvar, etter som nokon hadde trong til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Men Josef, som apostlarne hadde kalla med tilnamn Barnabas, det tyder: påminnaren, ein levit, ætta frå Kypern,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'som åtte ein åker, selde honom og bar pengarne fram og lagde deim for føterne på apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Men ein mann med namnet Ananias med kona si Saffira selde ein eigedom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'og han gøymde undan noko av pengeverdet, so kona hans visste det, og bar fram ein deil og lagde det for føterne på apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Men Peter sagde: «Ananias, kvifor hev Satan fyllt hjarta ditt, so du skulde ljuga for den Heilage Ande og gøyma undan av pengeverdet for jordstykket?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Var det ikkje ditt medan du åtte det? og var det ikkje i di magt då det vart selt? Kvi hev du då sett deg denne gjerning fyre i hjarta ditt? Du hev ikkje loge for menneskje, men for Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Men då Ananias høyrde desse ordi, seig han ned og gav upp åndi. Og det kom stor otte på alle deim som høyrde dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Men dei unge mennerne stod upp og budde liket til og bar honom ut og jorda honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Og det hende seg umkring tri timar seinare, då kom kona hans inn og visste ikkje um det som hadde hendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Peter sagde då til henne: «Seg du meg, selde de jordstykket for den pris?» Ho svara: «Ja, for den pris.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Då sagde Peter til henne: «Kvi hev de vorte samtykte um å freista Herrens Ande! Sjå, deira føter som jorda mannen din, er utfyre døri, og dei skal bera deg ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Og ho seig straks ned for føterne hans og gav upp åndi. Men dei unge mennerne kom inn og fann henne daud og bar henne ut og jorda henne attved mannen hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Og det kom stor otte på heile kyrkjelyden og på alle deim som høyrde dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Men ved henderne til apostlarne vart det gjort mange teikn og under millom folket, og dei var alle samstendige i Salomons sulehall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Men av dei andre våga ingen å slå lag med deim; men folket høgvyrde deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'og enn fleire som trudde, vart lagde til Herren, ei mengd både av menner og kvinnor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'so dei jamvel bar dei sjuke ut på gatorne og lagde deim på sengjer og benkjer, so i det minste skuggen av Peter kunde yverskyggja nokon av deim, når han kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Ja, endå frå byarne der i kring kom ei mengd saman til Jerusalem og førde sjuke med, og folk som var plåga av ureine ånder; og dei vart alle lækte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Men øvstepresten stod upp og alle dei som heldt med honom, det var sadducæarflokken, og dei vart fulle av brennhug,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'og dei lagde hand på apostlarne og kasta deim i det ålmenne fengslet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Men Herren engel opna um natti dørerne til fengslet og førde deim ut og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '«Gakk og stig fram og tala i templet alle dette livs ord til folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Då dei høyrde det, gjekk dei i dagningi inn i templet og lærde. Då so øvstepresten kom og dei som var med honom, kalla dei saman rådet og alle styresmennerne for Israels born, og dei sende bod til fengslet, at dei skulde føra deim fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Men då tenarane kom der, fann dei deim ikkje i fengslet, og so vende dei um att og fortalde det og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '«Fengslet fann me stengt med all umsyn, og vakterne stod ved dørerne. Men då me let upp, fann me ingen der inne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Då hovudsmannen for tempelvakti og øvsteprestarne høyrde dei ordi, vart dei rådville um deim, kva dette skulde verta til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'So kom det ein og fortalde deim og sagde: «Sjå, dei mennerne som de kasta i fengsel, dei stend i templet og lærer folket.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Då gjekk hovudsmannen dit med tenarane og henta deim, men ikkje med magt; for dei var rædde for folket, at dei skulde verta steina.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Men då dei hadde henta deim, stelte dei deim for rådet. Og øvstepresten spurde deim og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '«Baud me dykk ikkje strengt, at de ikkje skulde læra i dette namnet? og sjå, de hev fyllt Jerusalem med læra dykkar, og de vil føra yver oss denne manns blod.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Då svara Peter og apostlarne og sagde: «Ein skal lyda Gud meir enn menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Vår fedregud reiste upp Jesus som de tok livet av då de hengde honom på eit tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Denne hev Gud lyft upp ved si høgre hand til ein fyrste og frelsar til å gjeva Israel umvending og forlating for synderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Og me er hans vitne um desse ting liksom og den Heilage Ande, som Gud hev gjeve deim som lyder honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Då dei høyrde dette, skar det deim i hjarta, og dei rådlagde um å slå deim i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Men det reiste seg ein farisæar i rådet med namnet Gamaliel, ein lovlærar som var høgvyrd av heile folket, og han baud deim føra apostlarne ut ei liti stund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Og han sagde til deim: «Israelitiske menner! Sjå dykk vel fyre, kva de gjer med desse menneskje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'For fyre desse dagar stod Teudas fram og sagde seg sjølv å vera noko, og ein flokk på umkring fire hundrad menner slo lag med honom; han vart slegen i hel, og alle dei som lydde honom, drivne frå kvarandre og vart til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Etter honom stod galilæaren Judas fram, den tid skatte-utskrivingi var, og eggja upp folket med seg. Han let og livet, og alle dei som lydde honom, vart spreidde frå kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Og no segjer eg dykk: Haldt dykk ifrå desse mennerne og lat deim fara! For er denne rådi eller dette verket av menneskje, skal det verta til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Men er det av Gud, so kann de ikkje gjera det til inkjes! Sjå til at de ikkje må verta funne stridande mot Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Dei lydde honom, og kalla apostlarne inn att og let deim verta hudfletta, og baud deim at dei ikkje skulde tala i Jesu namn, og let deim so ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'So gjekk dei då burt frå rådet, glade yver at dei var haldne verdige til å lida vanæra for hans namn skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Og dei heldt ikkje upp med å læra kvar dag i templet og heime og forkynna evangeliet um Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'I desse dagarne, då talet på læresveinarne voks, murra dei græsktalande jøderne imot hebræarane, at deira enkjor vart mishaldne ved den daglege forsyting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Då kalla dei tolv heile mengdi av læresveinarne saman og sagde: «Det er ikkje høvelegt at me skal forlata Guds ord og tena ved bordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Difor, brør, sjå dykk um etter sju menner millom dykk, som hev godt lov og er fulle av den Heilage Ande og visdom, so me kann setja deim til dette umbodet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Men me vil halda trutt ved i bøni og i tenesta med ordet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Dette ordet lika heile mengdi vel, og dei valde Stefanus, ein mann full av tru og den Heilage Ande, og Filip og Prokorus og Nikanor og Timon og Parmenas og Nikolaus, ein jødetruande frå Antiokia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'og stelte deim fram for apostlarne, og dei bad og lagde henderne på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Og Guds ord hadde framgang, og talet på læresveinarne voks mykje i Jerusalem, og ein stor hop av prestarne vart lyduge mot trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Men Stefanus var full av tru og kraft og gjorde under og store teikn millom folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Men der stod upp nokre av den synagoga som er kalla synagoga åt dei frigjevne og kyrenæarane og alexandrinarne, og av deim frå Kilikia og Asia, og dei gav seg i ordskifte med Stefanus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Og dei kunde ikkje standa seg mot den visdom og ånd han tala utav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Då tinga dei løynleg nokre menner som sagde: «Me hev høyrt honom tala spottande ord imot Moses og Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Og dei øste upp folket og styresmennerne og dei skriftlærde, og dei sette på honom og reiv honom med og førde honom for rådet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Og dei stelte fram falske vitne, som sagde: «Denne mannen held ikkje upp med å tala mot denne heilage staden og mot lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'For me hev høyrt honom segja at denne Jesus frå Nasaret skal riva ned denne staden og brigda dei sedvanar som Moses gav oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Og då alle deim som sat i rådet, stirde på honom, såg dei åsyni hans som ein engels åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Då sagde øvstepresten: «Hev dette seg so?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Han svara: «Brør og feder, høyr på meg! Herlegdomens Gud openberra seg for far vår, Abraham, då han var i Mesopotamia, fyrr han feste bu i Kharan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'og han sagde til honom: «Gakk ut frå landet ditt og frå ætti di, og far til det landet som eg skal syna deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Då gjekk han ut or Kaldæarland og feste bu i Kharan; og då far hans var dåen, let han honom flytja derifrå til dette landet, der de no bur;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'men han gav honom ikkje arvlut der, ikkje ei fotbreidd eingong. Og han lova å gjeva honom det til eiga og hans ætt etter honom, endå han ikkje hadde barn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Og Gud tala soleis: «Hans ætt skal bu som utlendingar i framandt land, og dei skal gjera deim til trælar og fara ille med deim i fire hundrad år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Og det folket som dei trælar under, vil eg døma,» sagde Gud. «Og so skal dei draga ut og tena meg på denne staden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Og han gav honom umskjeringspakti; og so avla han Isak og umskar honom den åttande dagen, og Isak Jakob, og Jakob dei tolv patriarkarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Og patriarkarne ovundast på Josef og selde honom til Egyptarland. Og Gud var med honom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'og fria honom ut or alle hans trengslor og gav honom nåde og visdom for Farao, egyptarkongen, og han sette honom til hovding yver Egyptarland og heile sitt hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'So kom det hunger yver heile Egyptarland og Kana’an, og stor trengsla; og federne våre fann ikkje føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Men då Jakob høyrde at der var korn i Egyptarland, sende han federne våre dit fyrste gongen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Og den andre gongen vart Josef attkjend av brørne sine, og Farao lærde å kjenna Josefs ætt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Men Josef sende bod og kalla Jakob, far sin, og alt folket sitt dit, fem og sytti sjæler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Og Jakob drog ned til Egyptarland, og han døydde, han og federne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Og dei vart flutte yver til Sikem og lagde i den gravi som Abraham kjøpte for sylv av borni åt Hemor i Sikem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Etter som det leid til tidi for den lovnaden som Gud tilsvor Abraham, auka folket seg og vart mannsterkt i Egyptarland,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'alt til det kom ein annan konge yver Egyptarland, som ikkje visste noko um Josef.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Han for med svikråd mot folket vårt og for ille med federne våre, til dess dei laut setja småborni sine ut, so dei ikkje skulde få liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'I den tidi vart Moses fødd, og han var yndeleg for Gud. Og han vart fostra i huset åt far sin i tri månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Men då han vart utsett, tok Faraos dotter honom og fostra honom upp som sin eigen son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Og Moses vart upplærd i all egyptar-visdomen; og han var megtig i ord og gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Men då han hadde fyllt fyrti år, fekk han hug til å sjå um brørne sine, Israels-borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Og då han såg at ein leid urett, kom han honom til hjelp og tok hemn for honom som leid yvervald, og slo egyptaren i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Han tenkte at brørne hans skulde skyna at Gud gav deim frelsa ved hans hand. Men dei skyna det ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Dagen etter kom han til deim då dei trætta, og han talde deim til å halda fred og sagde: «Menner, de er brør; kvi gjer de urett mot kvarandre?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Men han som gjorde grannen sin urett, støytte honom ifrå seg og sagde: «Kven hev sett deg til hovding og domar yver oss?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Vil du kanskje slå meg i hel, liksom du slo egyptaren i hel i går?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Men Moses flydde for dette ordet skuld og vart ein utlending i Midjans land, og han fekk tvo søner der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Og då fyrti år var lidne, synte ein engel seg for honom i øydemarki ved Sinaifjellet i eldslogen i ein klunger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Då Moses såg det, undra han seg yver syni. Men då han gjekk burtåt og vilde sjå, kom ei røyst frå Herren:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '«Eg er din fedregud, Abrahams Gud og Isaks Gud og Jakobs Gud.» Men Moses vart skjelvande rædd og torde ikkje sjå på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Og Herren sagde til honom: «Løys skorne av føterne dine! for staden du stend på, er heilag jord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Eg hev grant set illgjerdi mot mitt folk i Egyptarland og høyrt deira sukk, og eg hev stige ned og vil fria deim ut. Og no, kom! lat meg senda deg til Egyptarland!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Denne Moses som dei forneitta og sagde: «Kven hev sett deg til hovding og domar?» honom sende Gud til hovding og utløysar ved den engels hand som synte seg for honom i klungeren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Han førde deim ut medan han gjorde under og teikn i Egyptarland og i Raudehavet og i øydemarki i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Han er den Moses som sagde til Israels-borni: «Ein profet liksom eg skal Herren, dykkar Gud, reisa upp åt dykk av dykkar brør.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Han er den som i lyden i øydemarki var med engelen som tala til honom på Sinaifjellet, og med federne våre, han som tok imot livande ord til å gjeva oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Honom vilde federne dykkar ikkje lyda, men dei støytte honom ifrå seg og vende seg i sitt hjarta til Egyptarland, då dei sagde til Aron:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, '«Gjer oss gudar, som kann ganga fyre oss! for denne Moses som førde oss ut or Egyptarland - me veit ikkje kva som hev hendt honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Og dei gjorde ein kalv i dei same dagarne bar offer fram til den avguden, og gledde seg yver det som deira eigne hender hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Men Gud vende seg burt og yvergav deim til å tena himmelheren, so som det stend skrive i profetboki: «Hev vel de, Israels hus, gjeve meg slagtoffer og andre offer i fyrti år i øydemarki?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Og de bar med dykk Moloks tjeld og guden Remfans stjerna, dei bilæti som de gjorde for å tilbeda deim. Og eg vil flytja dykk burt på hi sida åt Babylon.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Vitnemålstjeldet var hjå federne våre i øydemarki; so som han som tala til Moses, hadde bode å gjera det etter det bilætet han hadde set.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Dette tok federne våre i arv og førde det inn med Josva i eigedomslandet til dei heidningfolki som Gud dreiv undan for federne våre alt til Davids dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Han fann nåde for Guds åsyn og bad um at han måtte finna ein bustad åt Jakobs Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Men Salomo bygde honom eit hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Men den Høgste bur ikkje i hus som er gjorde med hender, som profeten segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '«Himmelen er min kongsstol, og jordi skammel under mine føter. Kva hus vil de byggja meg? segjer Herren, eller kva stad er min kvilestad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Hev ikkje mi hand gjort alt dette?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'De harde halsar og u-umskorne på hjarta og øyro! De stend alltid imot den Heilage Ande, som dykkar feder, so de og!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Kven av profetarne forfylgde ikkje federne dykkar? og dei slo deim i hel, som fyreåt forkynte at den Rettferdige skulde koma, han som de no hev svike og drepe,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'de som fekk lovi gjenom englar og hev ikkje halde henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Men då dei høyrde dette, skar det deim i hjarta, og dei beit tennerne saman imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Men han var full av den Heilage Ande og såg upp mot himmelen, og han såg Guds herlegdom, og Jesus standa ved Guds høgre hand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Og han sagde: «Sjå, eg ser himlarne opne og Menneskjesonen standa ved Guds høgre hand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Då skreik dei med høg røyst og heldt for øyro sine og styrmde samlyndt inn på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Og dei dreiv honom ut utanfor byen og steina honom. Og vitni lagde klædi sine av ved føterne til ein ung mann som heitte Saulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Og dei steina Stefanus, medan han bad og sagde: «Herre Jesus, tak imot mi ånd!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Men han fall på kne og ropa med høg røyst: «Herre, tilrekna deim ikkje denne syndi!» Og då han hadde sagt dette, sovna han av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Og Saulus samtykte i at dei drap honom. Men den dagen tok det til ei stor forfylgjing mot kyrkjelyden i Jerusalem, og dei vart spreidde ut yver Judæalandet og Samarialandet, alle so nær som apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Men nokre gudlege menner jorda Stefanus, og dei gret og jamra sårt etter honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Men Saulus herja kyrkjelyden og gjekk inn i hus etter hus og drog fram menner og kvinnor og yvergav deim til fangehus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Men dei som var spreidde utyver, gjekk ikring og bar ut evangelie-ordet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Filip kom då ned til ein by i Samaria og forkynte Kristus for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Og folket gav samlyndt gaum etter det som vart sagt av Filip, med di dei høyrde og såg dei teikni som han gjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'For or mange som hadde ureine ånder, for dei ut ropande med høg røyst, og mange lame og vanføre vart lækte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Og det vart stor gleda i den byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Men det var ein mann med namnet Simon, som fyrr hadde fare med trolldom i byen og fjetra folket i Samaria, med di han sagde seg vera noko stort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Og alle heldt seg til honom, både små og store, og sagde: «Han er Guds kraft som heiter stor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Men dei heldt seg til honom, av di han i lang tid hadde fjetra deim med trollkunster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Men då dei no trudde Filip, som forkynte evangeliet um Guds rike og Jesu Kristi namn, so let dei seg døypa både menner og kvinnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Og Simon tok ved trui han og, og då han var døypt, heldt han seg til Filip, og då han såg dei teikn og store kraftige gjerningar som vart gjorde, vart han mest frå seg av undring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Då apostlarne i Jerusalem fekk høyra at Samaria hadde teke imot Guds ord, sende dei til deim Peter og Johannes;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'dei kom ned og bad for deim, at dei måtte få den Heilage Ande;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'for endå var han ikkje fallen på nokon av deim, men dei var berre døypte til Herren Jesu namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Då lagde dei henderne på deim, og dei fekk den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Men då Simon såg at den Heilage Ande vart gjeven ved handpåleggjing av apostlarne, kom han til deim med pengar og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, '«Gjev meg og denne magt, at den som eg legg henderne på, må få den Heilage Ande!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Men Peter sagde til honom: «Forbanna vere sylvet ditt saman med deg sjølv, for di du tenkte å kjøpa Guds gåva for pengar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Du hev ikkje deil eller lut i dette ordet; for hjarta ditt er ikkje rett for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Vend difor um frå denne vondskapen din, og bed til Gud, um den tanken i hjarta ditt kunde verta deg forlaten!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'For eg ser at du ligg i illskaps gall og urettferds band.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Då svara Simon: «Bed de for meg til Herren, at ikkje noko må koma yver meg av det som de hev sagt!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Då dei so hadde vitna og tala Herrens ord, vende dei um att til Jerusalem, og dei forkynte evangeliet i mange samaritanbyar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Men ein Herrens engel tala til Filip og sagde: «Statt upp og gakk mot sud på den vegen som gjeng ned frå Jerusalem til Gaza!» Det er ein øydeveg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Og han stod upp og gjekk; og sjå, der var ein mann frå \'tiopia, ein hirdmann, ein megtig herre hjå dronning Kandake i \'tiopia, ein som var sett yver heile skatten hennar; han var komen til Jerusalem for å tilbeda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'og han var no på heimvegen og sat på vogni si og las profeten Jesaja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Men Anden sagde til Filip: «Gakk burtåt og haldt deg ved denne vogni!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Men Filip sprang til og høyrde at han las profeten Jesaja, og han sagde: «Skynar du det du les?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Men han sagde: «Korleis skulde eg kunna det, utan at nokon rettleider meg?» Og han bad Filip stiga upp og setja seg hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Men det stykket av skrifti som han las, var dette: «Som ein sau vart han førd til slagting, og liksom eit lamb som er tagalt for den som klypper det, soleis let han ikkje upp sin munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'I hans fornedring vart domen yver honom burtteken, og kven kann fortelja um hans ætt? for hans liv vert teke burt frå jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Men hirdmannen tok til ords og sagde til Filip: «Eg bed deg: kven segjer profeten dette um? um seg sjølv eller um nokon annan?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Men Filip let upp munnen og gjekk ut ifrå dette skriftordet og forkynte honom evangeliet um Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Og som dei for frametter vegen, kom dei til ein stad der det var vatn. Og hirdmannen sagde: «Sjå her er vatn, kva hindrar meg frå å verta døypt?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Og Filip sagde: «Trur du av heile ditt hjarta, so er det tillate.» Men han svara og sagde: «Eg trur at Jesus Kristus er Guds Son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Og han let vogni stana; og dei steig båe tvo ned i vatnet, både Filip og hirdmannen, og han døypte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Men då dei steig upp or vatnet, rykte Herrens Ande Filip burt, og hirdmannen såg honom ikkje meir; for han for glad sin veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Men Filip vart funnen i Asdod. Og han gjekk ikring og forkynte evangeliet i alle byarne, til han kom til Cæsaræa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Men Saulus frøste endå av trugsmål og mord mot Herrens læresveinar, og han gjekk til øvstepresten');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'og bad honom um brev til Damaskus, til synagogorne der, at um han fann nokre som høyrde «den vegen» til, både menner og kvinnor, han då kunde føra deim bundne til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Men då han drog fram og kom nær til Damaskus, lyste det brått eit ljos frå himmelen um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Og han fall ned på jordi og høyrde ei røyst som sagde til honom: «Saul, Saul, kvi forfylgjer du meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Han sagde: «Kven er du, Herre?» Og han svara: «Eg er Jesus, han som du forfylgjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Men statt upp og gakk inn i byen, so skal det verta sagt deg kva du hev å gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Men dei menner som var i ferdalag med honom, stod forstøkte då dei høyrde røysti, men såg ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saulus reiste seg då upp frå jordi; men då han opna augo, såg han ingen ting. Dei leidde honom då ved handi og førde honom inn i Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Og i tri dagar såg han ikkje, og ikkje åt eller drakk han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Men det var ein læresvein i Damaskus med namnet Ananias, og til honom sagde Herren i ei syn: «Ananias!» Han svara: «Her er eg, Herre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Og Herren sagde til honom: «Statt upp og gakk til den gata, som er kalla den beine, og spør i Judas’ hus etter ein mann frå Tarsus, med namnet Saulus; for sjå, han bed,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'og han hev i ei syn set ein mann med namnet Ananias, som kom og lagde handi på honom, so han skulde få syni att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Men Ananias svara: «Herre, eg hev høyrt av mange um denne mannen, kor mykje vondt han hev gjort mot dine heilage i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Og her hev han fullmagt frå øvsteprestarne til å binda alle deim som kallar på ditt namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Men Herren sagde til honom: «Gakk du! for han er meg ein utvald reidskap til å bera mitt namn fram for heidningar og kongar og Israels born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'For eg vil syna honom kor mykje han skal lida for mitt namn skuld.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'So gjekk Ananias burt og kom inn i huset og lagde henderne på honom og sagde: «Saul, bror! Herren hev sendt meg, Jesus, han som synte seg for deg på vegen der du kom, so du skal få syni att og verta fyllt med den Heilage Ande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Og straks fall det liksom flas frå augo hans, og han fekk syni att med det same, og han stod upp og vart døypt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'og han tok føda og styrkte seg. So vart han verande nokre dagar hjå læresveinarne i Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Og straks forkynte han Jesus i synagogorne, at han er Guds Son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Og alle dei som høyrde det, vart reint frå seg av undring og sagde: «Er ikkje dette han som i Jerusalem rudde ut deim som påkallar dette namnet? og han var komen hit til å føra deim bundne til øvsteprestarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Men Saulus vart enn sterkare, og han målbatt jødarne som budde i Damaskus, med di han synte at denne er Messias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Men då mange dagar var lidne, samrådde jødarne seg um å slå honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Men rådgjerdi deira vart kunnig for Saulus. Dei vakta og portarne både dag og natt for å slå honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Men læresveinarne tok honom um natti og slepte honom ut igjenom muren, med di dei let honom ned i ei korg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Då han no kom til Jerusalem, prøvde han å halda seg til læresveinarne, og alle var rædde honom, av di dei ikkje trudde at han var ein læresvein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Men Barnabas tok og førde honom til apostlarne, og han fortalde deim korleis han såg Herren på vegen, og at han tala til honom, og korleis han i Damaskus lærde frimodig i Jesu namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'So gjekk han då inn og ut med deim i Jerusalem og lærde frimodig i Herrens namn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'og han tala med dei græsktalande jødarne og gav seg i ordskifte med deim. Dei lagde seg då etter å slå honom i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Men då brørne fekk vita det, førde dei honom ned til Cæsarea og sende honom derifrå til Tarsus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'So hadde då kyrkjelyden fred yver heile Judæa og Galilæa og Samaria, og han uppbygde seg og ferdast i otte for Herren og voks ved tilstyrkjing av den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Og det hende seg, då Peter for ikring alle stader, at han og kom til dei heilage som budde i Lydda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Men der fann han ein mann med namnet \'neas, som i åtte år hadde lege sengfast og var lam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Og Peter sagde til honom: «\'neas! Jesus Kristus lækjar deg; statt upp og reid upp sengi di sjølv!» Og straks stod han upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Og dei såg honom, alle dei som budde i Lydda og Saron; og dei vende um til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'I Joppe var det ei læresyster med namnet Tabita, som er utlagt: Dorkas. Ho var rik på gode gjerningar og sælebotsgåvor som ho gav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Men det hende seg i dei dagarne, at ho vart sjuk og døydde. Dei vaska henne då og lagde henne på ein sal.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Og då Lydda ligg nær ved Joppe, og læresveinarne hadde høyrt at Peter var der, sende dei tvo menner til honom og bad: «Ver ikkje leid um du lyt fara hit til oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Peter stod upp og vart med deim; og då han kom dit, førde dei honom uppå salen. Og alle enkjorne stod ikring honom og gret og synte fram dei kjolar og klædningar som Tabita hadde gjort medan ho var hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Men Peter let deim alle ganga ut, og fall på kne og bad; og han vende seg til liket og sagde: «Tabita, statt upp!» Og ho opna augo sine, og då ho såg Peter, sette ho seg upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Og han gav henne handi og reiste henne upp og ropa på dei heilage og enkjorne og stelte henne fram livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Dette vart kunnigt yver heile Joppe, og mange kom til tru på Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'So vart det til det at han vart verande mange dagar i Joppe hjå ein som heitte Simon, ein garvar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Det var ein mann i Cæsaræa med namnet Kornelius, ein hovudsmann ved den herflokken som vart kalla den italiske;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'han var ein gudleg mann, som med heile sitt hus ottast Gud og gav mange sælebotsgåvor til folket og bad alltid til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Han såg klårt i ei syn ved den niande timen på dagen ein Guds engel som kom inn til honom og sagde til honom: «Kornelius!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Men han stirde på honom og vart rædd og sagde: «Kva er det, Herre?» Han svara honom: «Dine bøner og sælebotsgåvor hev stige upp til ei minning for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Og no, send folk til Joppe og henta hit Simon, som vert kalla med tilnamnet Peter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Han bur hjå ein som heiter Simon, ein garvar, som hev eit hus ved havet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Då engelen som tala til Kornelius, gjekk burt, kalla han til seg tvo av tenarane sine og ein gudleg hermann av deim som alltid var hjå honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'og han fortalde deim alt saman og sende deim av til Joppe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Andre dagen, då dei var på vegen og kom nær til byen, steig Peter uppå taket og vilde beda - umkring den sette timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Han vart då hungrig og vilde få seg mat. Medan dei laga maten til, kom der på honom ei burtrykning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'og han ser himmelen opna, og det for eitkvart ned til honom, liksom ein stor linduk, som vart laten ned på jordi etter dei fire hyrno;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'og der var det alle slag firføtte dyr på jordi og krjupande dyr og himmelens fuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Og det kom ei røyst til honom: «Statt upp, Peter, slagta og et!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Men Peter sagde: «På ingen måte, Herre! for aldri hev eg ete noko vanheilagt eller ureint!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Og røysti kom på nytt andre gongen til honom: «Det som Gud hev reinsa, må ikkje du halda for ureint!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Dette hende tri gonger; og straks vart det teke upp att til himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Medan Peter var reint rådvill um kva den syni skulde tyda som han hadde set, sjå, då stod dei utanfor porten, dei mennerne som var utsende frå Kornelius og hadde spurt upp Simons hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'og dei ropa inn og spurde um Simon som var kalla med tilnamnet Peter, budde der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Medan so Peter grunda på syni, sagde Anden til honom: «Sjå, tri menner leitar etter deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Statt upp, gakk ned og fylg med deim utan tviking! for eg hev sendt deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Peter gjekk ned til mennerne som var sende til honom frå Kornelius, og sagde: «Sjå, eg er den som de leitar etter; kva ærend hev de her?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Dei sagde: «Kornelius, ein hovudsmann, ein rettferdig og gudleg mann, som hev godt lov av heile jødefolket, hev fenge det bodet ved ein heilag engel, at han skulde henta deg til sitt hus og høyra kva du hev å segja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Han bad deim då inn og gav deim herbyrge. Og dagen etter stod han upp og gjekk av stad saman med deim, og nokre av brørne frå Joppe fylgde med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Dagen etter kom dei til Cæsarea og Kornelius venta deim og hadde bede saman sine frendar og næmaste vener.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Då det no bar til at Peter gjekk inn, kom Kornelius imot honom, fall ned for føterne hans og tilbad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Men Peter reiste honom upp og sagde: «Statt upp! eg er og eit menneskje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Og med di han samtala med honom, gjekk han inn og fann mange som var komne saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Og han sagde til deim: «De veit kor uløyvelegt det er for ein jøde å hava samlag med nokon av eit anna folk eller å ganga inn til honom. Men meg hev Gud vist at eg ikkje må kalla noko menneskje vanheilagt eller ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Difor kom eg og utan motmæle då eg fekk bod. Eg spør då kvifor de hev sendt bod etter meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Då sagde Kornelius: «For fire dagar sidan, det var som no ved den niande timen, bad eg i mitt hus, og sjå, ein mann stod framfyre meg i skinande klædnad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'og han sagde: «Kornelius, di bøn er høyrd, og dine sælebotsgåvor er ihugkomne for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Send difor bod til Joppe og kalla til deg Simon, som vert kalla med tilnamnet Peter! han bur i huset hjå Simon garvar ved havet; han skal tala til deg når han kjem.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Difor sende eg straks bod til deg; og du gjorde vel at du kom. No er me då alle til stadar for Guds åsyn for å høyra alt det som er pålagt deg av Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Men Peter let upp sin munn og sagde: «Eg skynar i sanning at Gud ikkje gjer skil på folk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'men millom alle folk tek han imot den som ottast honom og gjer rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Det ordet han sende ut til Israels-borni, då han forkynte evangeliet um fred ved Jesus Kristus - han er Herre yver alle - det kjenner de,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'det ordet som gjekk ut yver heile Judæa, med upphav frå Galilæa etter den dåp som Johannes forkynte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'det um Jesus frå Nasaret, korleis Gud salva honom med den Heilage Ande og kraft, han som gjekk ikring og gjorde vel og lækte alle deim som var yvervalda av djevelen; for Gud var med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Og me er vitne um alt det han gjorde både i Jødeland og i Jerusalem, han som dei slo i hel, med di dei hengde honom på eit tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Honom reiste Gud upp den tridje dagen og let honom få syna seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'ikkje for alt folket, men for dei vitne som fyrr var utvalde av Gud, for oss som åt og drakk med honom, etter han var uppstaden frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Og han baud oss å forkynna for folket og vitna at han er den som Gud hev sett til domar yver livande og daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Um honom vitnar alle profetarne, at kvar den som trur på honom, skal få forlating for synderne ved hans namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Medan Peter endå tala desse ordi, fall den Heilage Ande på alle deim som høyrde ordet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Og alle dei truande av umskjeringi som var komne med Peter, vart forfærde yver at den Heilage Ande vart gjeven og utrend ogso yver heidningarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'for dei høyrde deim tala med tungor og storleg lova Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Då svara Peter: «Kann vel nokon meinka vatnet, at ikkje desse må verta døypte, som hev fenge den Heilage Ande liksom me?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Og han baud at dei skulde verta døypte i Jesu Kristi namn. Og dei bad honom drygja der nokre dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Apostlarne og brørne som var i Judæa, høyrde at heidningarne og hadde teke imot Guds ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Og då Peter kom upp til Jerusalem, klandra dei av umskjeringi på honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, '«Du gjekk inn til menner som ikkje er umskorne, og åt i lag med deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Men Peter tok til og greidde det ut for deim i samanheng og sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '«Eg var i byen Joppe og bad; då såg eg i burtrykning ei syn: det dala ned eitkvart, liksom ein stor linduk, som vart laten ned frå himmelen etter dei fire hyrno og kom like til meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Då eg stirde på det, vart eg var og såg dei firføtte dyr på jordi og ville dyr og krjupande dyr og himmelens fuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Og eg høyrde ei røyst som sagde til meg: «Statt upp, Peter, slagta og et!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Men eg sagde: «På ingen måte, Herre! for noko vanheilagt eller ureint kom aldri i min munn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Men røysti svara meg andre gongen frå himmelen: «Det som Gud hev reinsa, må ikkje du halda for ureint!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Dette hende seg tri gonger, og det vart alt saman drege upp i himmelen att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Og sjå, i same stundi stod det utanfor huset der eg var, tri menner, som var sende til meg frå Cæsarea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Og Anden sagde til meg at eg skulde fylgja med deim utan tviking. Men desse seks brørne gjekk og med meg, og me kom inn huset til mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Og han fortalde han oss korleis han hadde set engelen som stod i hans hus og sagde til honom: «Send bod til Joppe og henta Simon, som vert kalla med tilnamnet Peter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'han skal tala ord til deg som du skal verta frelst ved, du og heile ditt hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Men då eg tok til å tala, fall den Heilage Ande på deim, liksom på oss i fyrstningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Då kom eg Herrens ord i hug, at han sagde: «Johannes døypte med vatn; men de skal verta døypte med den Heilage Ande.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Når då Gud hev gjeve deim same gåva som oss, då dei kom til trui på Herren Jesus Kristus, kven var då eg, at eg skulde vera megtig til å hindra Gud?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Men då dei høyrde dette, gav dei seg til ro og lova Gud og sagde: «So hev då Gud ogso gjeve heidningarne umvendingi til livet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Dei som no var spreidde ved den trengsla som kom upp for Stefanus skuld, dei gjekk ikring radt til Fønikia og Kypern og Antiokia, men tala ikkje ordet til nokon utan berre til jødar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Men det var millom deim nokre menner frå Kypern og Kyrene, som kom til Antiokia og tala til grækarane og forkynte evangeliet um Herren Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Og Herrens hand var med deim, og eit stort tal kom til trui og umvende seg til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Denne tidend kom då kyrkjelyden i Jerusalem for øyro, og dei sende Barnabas ut til å fara til Antiokia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Då han kom dit og såg Guds nåde, gledde han seg og tilstyrkte deim alle til å halda fast ved Herren med hjartans fyreset;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'for han var ein god mann og full av den Heilage Ande og tru. Og mykje folk vart ført til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Han for då ut til Tarsus for å leita etter Saulus; og då han fann honom, førde han honom med til Antiokia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Men det hende seg, at dei var saman eit heilt år hjå kyrkjelyden og lærde mykje folk, og i Antiokia vart læresveinarne fyrst kalla kristne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'I dei dagarne kom det nokre profetar ned frå Jerusalem til Antiokia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Og ein av deim med namnet Agabus stod fram og kunngjorde ved Anden, at det skulde koma ein stor hunger yver heile mannheimen, og han kom ogso under keisar Klaudius.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Læresveinarne sette seg då fyre å senda noko, etter som kvar av deim hadde råd, til hjelp for dei brørne som budde i Judæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Det gjorde dei ogso, og dei sende det til dei eldste gjenom Barnabas og Saulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Ved denne tidi lagde kong Herodes hand på nokre av kyrkjelyden og for ille med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Jakob, bror til Johannes, tok han livet av med sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Og då han såg at det var jødarne til lags, heldt han fram og greip ogso Peter - det var i søtebrødhelgi -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'og då han hadde gripe honom, sette han honom i fengsel og yvergav til fire vaktskifte, på fire mann kvart, å vakta på honom, då han etter påske vilde føra honom fram for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Peter vart då vakta i fengslet. Men av kyrkjelyden vart det halde inderleg bøn til Gud for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Då so Herodes skulde til å føra honom fram, sov Peter den same natti millom tvo hermenner, bunden med tvo lekkjor, og vaktmenner utanfor døri vakta på fengslet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Og sjå, Herrens engel stod der, og eit ljos skein i fangeromet. Og han støytte Peter i sida, vekte honom og sagde: «Skunda deg og statt upp!» og lekkjorne fall av henderne på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Men engelen sagde til honom: «Bitt livgjordi um deg, og knyt på deg skorne dine!» Han so gjorde. Og han sagde til honom: «Kasta kjolen um deg, og fylg meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Og han gjekk ut og fylgde honom, og visste ikkje at det som engelen gjorde, var verkelegt, men trudde at han såg ei syn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Då dei var komne igjenom den fyrste og den andre vakti, kom dei til den jarnporten som ber ut til byen, og han opna seg for deim av seg sjølv. Og dei gjekk ut og gjekk ei gata frametter, og straks skildest engelen frå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Og Peter kom til seg sjølv att og sagde: «No veit eg i sanning at Herren sende engelen sin og fria meg ut or Herodes’ hand og frå alt det som jødefolket trår etter.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Og då han no hådde seg, gjekk han til huset hennar Maria, mor til Johannes som var kalla med tilnamnet Markus; der var mange komne saman og heldt bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Men då Peter banka på porten, kom det ut ei tenestgjenta, som heitte Rode, og skulde høyra etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Og då ho kjende Peters røyst, vart ho so glad, at ho ikkje let upp porten, men sprang inn og fortalde at Peter stod utanfor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Men dei sagde til henne: «Du er frå vitet.» Men ho vissa at det var so. Då sagde dei: «Det er engelen hans.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Men Peter heldt på og banka; då let dei upp og såg honom, og dei vart forfærde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Men han gjorde teikn til dem med handi, at dei skulde tegja, og fortalde deim korleis Herren førde honom ut or fengslet. Og han sagde: «Fortel Jakob og brørne dette!» So gjekk han burt og for til ein annan stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Då det so vart dag, var det ikkje liti røra millom hermennerne um kvar det då kunde ha vorte av Peter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Herodes let leita etter honom, men fann honom ikkje. Og han forhøyrde vaktmennerne og baud at dei skulde førast burt. Og han drog ned frå Judæa til Cæsarea og vart verande der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Han var storleg vreid på folket i Tyrus og Sidon. Men dei steig samrådde fram for honom, og då dei hadde vunne Blastus, ein hirdmann hjå kongen, bad dei um fred, av di landet deira hadde si næring frå kongens land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'På ein fastsett dag klædde so Herodes seg i kongelegt skrud og sette seg på kongsstolen og heldt ein tale til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Og folket ropa til honom: «Det er Guds røyst og ikkje menneskjerøyst!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Straks slo Herrens engel honom, for di han ikkje gav Gud æra; og han vart uppeten av makk og anda ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Men Guds ord hadde framgang og vann mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Og Barnabas og Saulus for atter frå Jerusalem då dei hadde fullført si tenesta, og tok og med seg Johannes som var kalla med tilnamnet Markus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'I Antiokia, hjå kyrkjelyden der, var det nokre profetar og lærarar: Barnabas og Simeon, som vart kalla Niger, og Lukius frå Kyrene og Manaen, fosterbror til fylkeskongen Herodes, og Saulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Medan dei heldt gudstenesta og fasta, sagde den Heilage Ande: «Tak ut Barnabas og Saulus åt meg til den gjerning som eg hev kalla deim til!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Då fasta dei og bad og lagde henderne på deim og let deim fara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Då dei no soleis var utsende av den Heilage Ande, for dei ned til Seleukia og siglde derifrå yver til Kypern.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Og då dei var komne til Salamis, forkynte dei Guds ord i synagogorne til jødarne, og dei hadde ogso Johannes med til medhjelp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Då dei so hadde fare gjenom øyi radt til Pafus, fann dei ein trollmann, ein falsk profet, ein jøde, som hadde namnet Barjesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Han var hjå landshovdingen Sergius Paulus, ein klok mann. Denne kalla til seg Barnabas og Saulus og ynskte å høyra Guds ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Men Elymas, trollmannen - for so er namnet hans utlagt - stod deim imot og søkte å venda landshovdingen av frå trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Men Saulus, som og vert kalla Paulus, vart fyllt med den Heilage Ande og såg kvast på honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, '«Å du som er full av all svik og all vondskap, du djevels barn, du fiende til all rettferd! vil du ikkje halda upp med å forvenda Herrens beine vegar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Og no, sjå Herrens hand er yver deg, og du skal verta blind og ikkje sjå soli ei tid.» Og straks fall skodda og myrker på honom, og han trivla ikring og leita etter nokon som kunde leida honom ved handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Då tok landshovdingen ved trui, då han såg det som hadde hendt, og han var full av undring yver Herrens læra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Paulus og fylgjet hans siglde so frå Pafus og kom til Perge i Pamfylia. Men Johannes skilde seg frå deim og vende um til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Men dei for lenger frå Perge og kom til Antiokia i Pisidia og gjekk inn i synagoga på kviledagen og sette seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Etter lesnaden av lovi og profetarne sende forstandarane for synagoga bod til deim og sagde: «Brør, dersom de hev noko ord til påminning for folket, so tala!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'So stod Paulus upp og slo til ljod med handi og sagde: «Israelitiske menner og de som ottast Gud, høyr!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Dette folks, Israels, Gud valde ut federne våre, og han upphøgde folket i utlendingskapen i Egyptarland og førde deim ut derifrå med høglyft arm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Og umkring fyrti år bar han deim på faderarm i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'og han øydde ut sju folkeslag i Kana’ans-landet og skifte landet deira ut til arv åt deim, i fire hundrad og femti år på lag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'So gav han deim domarar alt til profeten Samuel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Sidan kravde dei ein konge, og Gud gav deim Saul, Kis’ son, ein mann av Benjamins ætt, i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Og då han hadde sett honom av, uppreiste han deim David til konge, han som han vitna um og sagde; «Eg fann David, Isais son, ein mann etter mitt hjarta; han skal gjera all min vilje.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Av hans ætt førde han etter lovnaden fram ein frelsar for Israel, Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'etter at Johannes fyreåt for hans koma hadde forkynt umvendingsdåp for heile Israels folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Men då Johannes fullførde sitt livnadslaup, sagde han: «Den de held meg for å vera, er eg ikkje; men sjå, det kjem ein etter meg, som eg ikkje er verdig til å løysa skorne av føterne på.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Brør, søner av Abrahams ætt, og dei millom dykk som ottast Gud! til dykk vart ordet um denne frelsa sendt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'For dei som bur i Jerusalem og deira rådsherrar kjende honom ikkje, og med di dei dømde honom, uppfyllte dei og profetordi, som vert fyrelesne kvar kviledag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Og endå dei ikkje fann nokor daudskyld, bad dei Pilatus at han måtte verta ihelslegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Men då dei hadde fullført alt det som stend skrive um honom, tok dei honom ned av treet og lagde honom i ei grav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Men Gud vekte honom upp frå dei daude;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'og han synte seg i fleire dagar for deim som hadde gjenge med honom frå Galilæa upp til Jerusalem, dei som no er hans vitne for folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Og me forkynner dykk evangeliet um den lovnaden som vart federne gjeven, at Gud hev uppfyllt denne for oss, deira born, då han reiste upp Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'so som det og stend skrive i den andre salmen: «Du er min son; eg hev født deg i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Men at han reiste honom upp frå dei daude, so han aldri meir skal venda tilbake til undergang, det hev han sagt so: «Eg vil gjeva dykk dei heilage lovnader til David, dei trufaste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Difor segjer han og ein annan stad: «Du skal ikkje lata din heilage sjå undergang.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'For David sovna av, etter han i si livetid hadde tent Guds rådgjerd, og vart samla med sine feder og såg undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Men han som Gud vekte upp, han såg ikkje undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Det vere då kunnigt for dykk, brør, at i honom vert forlating for synderne forkynt dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'og frå alt det som de ikkje kann verta rettferdiggjorde frå ved Mose lov, vert kvar den som trur rettferdiggjord i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Sjå difor til at det som er sagt hjå profetarne, ikkje skal koma yver dykk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '«Sjå, de vanvyrdarar, og undra dykk og vert til inkjes! for eit verk gjer eg i dykkar dagar, eit verk som de ikkje vil tru, um nokon fortel dykk det.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Men då dei gjekk ut, bad dei um at desse ordi måtte verta tala til deim den næste kviledagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Og då synagogetenesta var enda, fylgde det med Paulus og Barnabas mange av jødarne og av dei jødetruande som dyrka Gud; og dei tala til deim og talde deim til å halda fast ved Guds nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Den næste kviledagen kom mest heile byen saman og vilde høyra Guds ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Men då jødarne såg folkehoparne, vart dei fulle av brennhug, og dei sagde imot det som vart sagt av Paulus, ja, sagde imot og spotta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Då tok Paulus og Barnabas til ords og sagde beint ut: «Det var naudsynlegt at Guds ord vart tala fyrst til dykk; men sidan de støyter det burt og ikkje dømer dykk sjølve verdige til det ævelege liv, sjå, so vender me oss til heidningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'For so hev Herren bode oss: «Eg hev sett deg til ljos for heidningar, at du skal vera til frelsa alt til ytste enden av jordi.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Då heidningarne høyrde det, gledde dei seg og prisa Herrens ord, og dei tok ved trui, so mange som var etla til ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Og Herrens ord breidde seg ut yver heile landet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Men jødarne øste upp dei fornæme kvinnor som dyrka Gud, og dei fyrste menner i byen, og dei fekk i gang ei forfylgjing mot Paulus og Barnabas, og dei jaga deim ut frå sine landemerke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Dei riste dusti av føterne sine mot deim og kom til Ikonium.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Men læresveinarne vart fyllte med gleda og den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'So hende det seg i Ikonium, at dei gjekk saman inn i synagoga til jødarne, og tala soleis at ein stor mengd både med jødar og grækarar trudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Men dei jødar som ikkje trudde, øste upp og sette vondt i hugen åt heidningarne imot brørne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Dei drygde då der ei lang tid og tala frimodigt i Herren, som vitna for sitt nådeord, med di han let teikn og under verta gjorde ved deira hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Og mengdi i byen sundra seg: nokre heldt med jødarne, andre med apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Men då det vart stor ågang både av heidningarne og jødarne med deira styresmenner, med di dei vilde gjera vondt med deim og steina deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'og då dei merka det, flydde dei til byarne i Lykaonia: Lystra og Derbe, og landet der ikring;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'og der forkynte dei evangeliet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Og i Lystra sat det ein mann som var magtlaus i føterne og hadde vore vanfør frå mors liv og aldri hadde gjenge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Han høyrde Paulus tala, og då han stirde på honom og såg at han hadde tru på å verta lækt, sagde han med høg røyst:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, '«Statt rett upp på føterne dine!» Og han sprang upp og gjekk ikring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Men då folket såg det som Paulus hadde gjort, lyfte dei røysti og sagde på lykaonisk: «Gudarne hev teke menneskjeskapnad på og er komne ned til oss.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Og dei kalla Barnabas Zeus og Paulus Hermes, av di han var den som førde ordet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Og presten for det Zeus-templet som var utanfor byen deira, kom til porten med uksar og kransar og vilde ofra saman med folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Men då apostlarne Barnabas og Paulus høyrde det, reiv dei klædi sine sund og sprang inn i flokken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'og ropa og sagde: «Menner, kva er det de gjer? Me er og menneskje under same kår som de, og me forkynner dykk evangeliet, at de skal venda dykk burt frå desse fåfengde gudar til den livande Gud, som gjorde himmelen og jordi og havet og alt som i deim er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'han som i dei framfarne tiderne let alle heidningfolk ganga sine eigne vegar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'endå han ikkje let seg utan vitnemål, men di han gjorde godt og gav dykk regn og grøderike tider frå himmelen, og metta hjarto dykkar med føda og fagnad.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Og ved å segja dette var det med naudi dei heldt folket frå å ofra til deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Men det kom jødar dit frå Antiokia og Ikonium og eggja upp mengdi, og dei steina Paulus og drog honom ut or byen i den tru at han var slokna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Men medan læresveinarne stod um honom, reiste han seg upp og gjekk inn til byen. Og dagen etter gjekk han med Barnabas ut til Derbe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Og då dei hadde forkynt evangeliet der i byen og gjort mange til læresveinar, vende dei um att til Lystra og Ikonium og Antiokia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'og dei styrkte sjælerne hjå læresveinarne og talde deim til å halda fast ved trui og sagde: «Me lyt ganga inn i Guds rike gjenom mange trengslor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Og då dei hadde valt eldste åt deim for kvar kyrkjelyd, heldt dei bøn og fasta, og yvergav deim til den Herre som dei trudde på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Og dei drog gjenom Pisidia og kom til Pamfylia;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'og då dei hadde tala ordet i Perge, for dei ned til Attalia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Derifrå siglde dei til Antiokia, der som dei hadde vorte yvergjevne til Guds nåde til den gjerning som dei hadde fullført.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Då dei kom dit, samla dei kyrkjelyden og fortalde kor store ting Gud hadde gjort ved deim, og at han hadde opna døri til tru for heidningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Og dei drygde der ikkje so kort tid saman med læresveinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Og det kom nokre ned frå Judæa og lærde brørne: «Dersom de ikkje vert umskorne etter Mose sedvane, so kann de ikkje verta frelste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Då der no vart strid, og Paulus og Barnabas kom i ikkje so lite ordskifte med deim, tok dei den råd at Paulus og Barnabas og nokre andre av deim skulde fara upp til apostlarne og dei eldste i Jerusalem for dette spursmålet skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Kyrkjelyden fylgde deim eit stykke på veg, og so drog dei gjenom Fønikia og Samaria og fortalde um korleis heidningarne hadde vendt um; og dei gjorde alle brørne stor gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Og då dei nådde fram til Jerusalem, vart dei fagna av kyrkjelyden og apostlarne og dei eldste, og dei fortalde kor store ting Gud hadde gjort ved deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Men det reiste seg nokre av farisæarflokken som hadde teke ved trui, og sagde: «Ein må umskjera deim og påleggja deim å halda Mose lov.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Apostlarne og dei eldste kom då saman og skulde rådleggja um denne saki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Då det so vart eit kvast ordskifte, stod Peter upp og sagde til deim: «Brør! de veit at Gud for lenge sidan gjorde det utval millom dykk, at ved min munn skulde heidningarne få høyra ordet um evangeliet og koma til trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Og Gud, som kjenner hjarto, han vitna for deim, då han gav deim den Heilage Ande liksom oss;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'og inkje skil gjorde han på oss og deim, med di han ved trui reinsa hjarto deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Kvi freistar de då Gud no med å leggja på nakken til læresveinarne eit ok som korkje federne våre eller me orka å bera?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Men ved Herren Jesu nåde trur me at me vert frelste, på same måten som dei.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Då tagde heile mengdi, og dei høyrde på Barnabas og Paulus, som fortalde kor store teikn og under Gud hadde gjort millom heidningarne ved deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Og då dei hadde slutta å tala, tok Jakob til ords og sagde: «Brør, høyr på meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simeon hev fortalt korleis Gud frå det fyrste såg til å få seg eit folk av heidningar for sitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Og med dette samstavast profetordi, so som det stend skrive:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '«Deretter vil eg venda tilbake og byggja upp att Davids nedfalne hytta, og det som er nedrive av henne, vil eg byggja upp att, og nyreisa det,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'so dei andre menneskje skal søkja Herren, ja, alle heidningfolki som mitt namn er nemnt yver,» segjer Herren, som gjer dette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'som han veit um frå æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Difor dømer eg at ein ikkje skal tyngja deim av heidningarne som umvender seg til Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'men skriva til deim at dei skal halda seg frå ureinskap ved avgudar og frå hor og frå det som er strøypt og frå blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'For Moses hev frå gamle dagar i kvar by deim som forkynner honom, då han vert upplesen i synagogorne kvar kviledag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Då vedtok apostlarne og dei eldste saman med heile kyrkjelyden å velja ut menner millom seg og senda deim til Antiokia med Paulus og Barnabas: det var Judas, med tilnamnet Barsabbas, og Silas, som var høgvyrde menner millom brørne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Og dei skreiv dette med deim: «Apostlarne og dei eldste og brørne helsar brørne av heidningarne i Antiokia og Syria og Kilikia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Etter di me hev høyrt at nokre som er komne frå oss, hev skræmt dykk upp ved sin tale og uroa sjælerne dykkar - me hev ikkje gjeve deim noko pålegg -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'so hev me samrådde vedteke å velja ut nokre menner og senda deim til dykk saman med våre kjære brør Barnabas og Paulus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'menner som hev våga livet sitt for vår Herre Jesu Kristi namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Me hev då sendt Judas og Silas, som og munnleg skal kunngjera det same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'For den Heilage Ande og me hev vedteke at me ikkje vil leggja nokor byrd på dykk utyver desse naudturvelege ting:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'at de held dykk frå avgudsoffer og blod og det strøypte og hor; og de vil finna dykk vel ved å vara dykk for desse ting. Liv vel!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Då no desse var sende av stad, kom dei til Antiokia, og dei kalla heile kyrkjelyden saman og gav deim brevet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Då dei hadde lese det, vart dei glade yver den trøysti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas og Silas, som sjølv var profetar, trøysta brørne med mange ord og styrkte deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'og då dei hadde vore der ei tid, let brørne deim fara med fred til deim som hadde sendt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Silas rådde seg til å vera der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Men Paulus og Barnabas drygde i Antiokia og lærde og forkynte Herrens ord ved evangeliet saman med mange andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Men etter nokre dagar sagde Paulus til Barnabas: «Lat oss gjera ferdi upp att og sjå til våre brør i kvar by der me forkynte Herrens ord, korleis dei hev det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas rådde til å taka Johannes med, som var kalla Markus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Men Paulus tykte ikkje dei skulde taka honom med, som hadde skilt seg frå deim i Pamfylia og ikkje gjenge med deim til deira gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Det kom då til ein kvass strid, so dei skildest frå kvarandre, og Barnabas tok Markus med seg og siglde av til Kypern.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Men Paulus valde Silas til fylgjesvein og drog ut etter at brørne hadde gjeve honom yver til Herrens nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Og han for gjenom Syria og Kilikia og styrkte kyrkjelydarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Og han kom til Derbe og Lystra. Og sjå, der var det ein læresvein med namnet Timoteus, son åt ei truande jødisk kvinna og ein græsk far.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Han hadde godt lov av brørne i Lystra og Ikonium.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Honom vilde Paulus hava i fylgje med seg på ferdi, og han tok og umskar honom for dei jødar skuld som var på dei staderne, for dei visste alle at far hans var grækar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Som dei då drog gjenom byarne, pålagde dei deim å halda dei bodi som var vedtekne av apostlarne og dei eldste i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'So vart då kyrkjelydarne styrkte i trui og voks i tal med kvar dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'So for dei gjenom Frygia og det galatiske land, for den Heilage Ande hindra deim frå å tala ordet i Asia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'og då dei kom burtimot Mysia, freista dei å fara til Bitynia; og Jesu Ande gav deim ikkje lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'So for dei utanum Mysia og drog ned til Troas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Og um natti viste det seg ei syn for Paulus; det stod ein mann frå Makedonia og bad honom og sagde: «Kom yver til Makedonia og hjelp oss!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Då han hadde set syni, søkte me straks å koma yver til Makedonia, sidan me kunde skyna at Herren hadde kalla oss til å forkynna evangeliet for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Me lagde so ut frå Troas og siglde beint yver til Samotrake og dagen etter til Neapolis,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'og derifrå til Filippi, som er den fyrste byen i den luten av Makedonia og ein romersk koloni. I den byen drygde me nokre dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'På kviledagen gjekk me utanfor porten til ei elv, der dei hadde for vis å samlast til bøn, og me sette oss der og tala til dei kvinnor som der var komne saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Og ei kvinna med namnet Lydia, som dreiv purpurhandel, frå byen Tyatira, ei som dyrka Gud etter jødetrui, ho høyrde på, og Herren let upp hjarta hennar, so ho gav gaum etter det som Paulus tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Då ho og hennar hus var døypte, bad ho oss og sagde: «So sant de held meg for å vera ei som trur på Herren, so kom inn i mitt hus og ver der!» Og ho nøydde oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Men det hende seg, ein gong då me drog ut til bønestaden, at det møtte oss ei trælkvinna som hadde ei spådomsånd og var herrarne sine til stor vinning med å spå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ho fylgde etter Paulus og oss og ropa og sagde: «Desse menneski er den høgste Guds tenarar, som forkynner dykk frelsevegen!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Dette gjorde ho mange dagar. Men Paulus vart harm og vende seg og sagde til åndi: «Eg byd deg i Jesu Kristi namn å fara ut or henne!» Og ho for ut or henne i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Men då herrarne hennar såg at deira von um vinning var spillt, tok dei fat på Paulus og Silas og drog deim med på torget til rettartinget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'og dei førde deim fram for styresmennerne og sagde: «Desse mennerne rører reint upp byen vår; dei er jødar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'og forkynner seder som me ikkje hev lov til å taka imot eller liva etter, me som er romarar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Folket reiste seg og imot deim, og styresmennerne reiv klædi av deim, og let deim hudflengjast,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Og då dei hadde slege deim mange slag, kasta dei deim i fengsel og pålagde fangevaktaren å taka vel vare på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Då han hadde fengje det pålegget, kasta han deim i det inste fangeromet og sette føterne deira fast i stokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Men umkring midnatt heldt Paulus og Silas bøn og song lovsongar til Gud, og fangarne lydde på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Då kom det brått ein stor jordskjelv, so at grunnvollen i fengslet skalv, og straks sprang alle dører upp, og lekkjorne losna av deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Fangevaktaren for upp or svevnen, og då han såg dørerne i fengslet opna, drog han sverdet og vilde drepa seg, for han trudde at fangarne hadde rømt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Men Paulus ropa med høg røyst: «Gjer deg ikkje noko vondt! me er her alle saman.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Han bad då um ljos og sprang inn, og han fall skjelvande ned for Paulus og Silas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Og han førde deim ut og sagde: «Herrar, kva skal eg gjera for å verta frelst?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Dei svara: «Tru på Herren Jesus, so skal du verta frelst, du og ditt hus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Og dei tala Herrens ord til honom og til alle i hans hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'So tok han deim til seg i same timen um natti og vaska deim etter slagi, og han vart straks døypt, han sjølv og alle hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Og han førde deim upp i huset sitt, sette fram brød åt deim, og gledde seg for di han med heile sitt hus var komen til trui på Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Då det so vart dag, sende styresmennerne sveinarne og sagde: «Lat mennerne lause!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Fangevaktaren fortalde Paulus desse ordi: «Styresmennerne hev sendt bod at de skal sleppa lause; so gakk no ut og far i fred!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Men Paulus sagde til deim: «Dei hev hudflengt oss openberrleg utan lov og dom, me som er romerske borgarar; og so hev dei kasta oss i fengsel, og no vil dei jaga oss burt i løyndom. Men nei; lat deim koma sjølve og føra oss ut!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Sveinarne fortalde styresmennerne desse ordi. Og dei vart rædde, då dei høyrde at dei var romarar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'dei kom og tala vel med deim og førde deim ut og bad deim fara frå byen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'So gjekk dei ut or fengslet og gjekk inn til Lydia; og då dei hadde set brørne og gjeve deim påminningar, drog dei burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Då dei hadde fare gjenom Amfipolis og Apollonia, kom dei til Tessalonika, der jødarne hadde synagoga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Som Paulus’ sedvane var, gjekk han inn til deim, og tri kviledagar tala han med deim ut or skrifterne');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'og tydde og greidde ut, at Messias skulde lida og standa upp frå dei daude, og sagde: «Dette er Messias, den Jesus som eg forkynner dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Og nokre av deim vart yvertydde og heldt seg til Paulus og Silas, og like eins ein stor mengd av dei grækarar som dyrka Gud, og ikkje få av dei fremste kvinnorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Men jødarne vart fulle av brennhug og tok med seg nokre låke menneskje av deim som rak på torget, og gjorde eit upplaup og sette byen i røra. Og dei trengde seg fram imot Jasons hus og søkte å få deim ut til folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Men då dei ikkje fann deim, drog dei Jason og nokre av brørne fram for byretten og ropa: «Desse som hev sett heile mannheimen i upprør, dei er og komne hit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'og Jason hev teke imot deim. Og alle desse gjer beint imot keisarens lovbod, og segjer at ein annan er konge, og det er Jesus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Og dei fekk skræmt upp folket og byretten, då dei høyrde dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Og då dei hadde late Jason og dei andre ganga i borg for deim, let dei deim lause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Men brørne sende straks um natti både Paulus og Silas av stad til Berøa, og då dei kom dit, gjekk dei burt i synagoga til jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Men desse var gjævare enn dei i Tessalonika, og dei tok imot ordet med all godvilje og ransaka dag etter dag i skrifterne um dette hadde seg soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Mange av dei kom då til trui, og ikkje få av dei fornæme græske kvinnor og menner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Men då jødarne i Tessalonika fekk vita at Paulus forkynte Guds ord i Berøa og, kom dei og dit og eggja upp folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Straks sende då brørne Paulus burt på vegen til havet; men både Silas og Timoteus vart att der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Dei som fylgde Paulus, førde honom til Aten og drog so derifrå med det bodet til Silas og Timoteus, at dei skulde koma til honom so snart som råd var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Medan no Paulus venta på deim i Aten, harmast hans ånd i honom, då han såg at byen var full av avgudsbilæte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Han samtala då i synagoga med jødarne og deim som dyrka Gud, og på torget kvar dag med deim han råka på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Nokre av dei epikureiske og stoiske vismennerne gav seg i ordskifte med honom, og sume sagde: «Kva er det denne ordgytaren vil segja?» Men andre sagde: «Han synest vera talsmann for framande guddomar;» - for han forkynte deim evangeliet um Jesus og uppstoda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'So tok dei honom i handi og førde honom upp til Areopagus og sagde: «Kann me få vita kva det er for ei ny læra, dette som du talar um?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'For det er underlege ting du fører oss for øyro. Difor vil me få vita kva dette skal tyda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Men alle atenarar og dei framande som budde der, gav seg ikkje stunder til anna enn å fortelja eller høyra nytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'So stod då Paulus fram midt på Areopagus og sagde: «De ateniske menner! Eg ser at de i alle måtar er mykje annsame i dykkar gudsdyrking;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'for då eg gjekk ikring og såg på heilagdomarne dykkar, fann eg og eit altar med den innskrifti: «For ein ukjend Gud.» Det som de då dyrkar utan å kjenna det, dette forkynner eg dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Gud, han som gjorde verdi og alt det som i henne er, han som er herre yver himmel og jord, han bur ikkje i tempel som er gjorde med hender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'ikkje heller tek han tenesta av menneskjehender, som um han hadde trong til nokon ting, for han sjølv gjev alle liv og ande og alle ting;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'og han hev late alle folkeslag av eitt blod bu yver heile jordkringen og fastsett deim visse tider og landemerke for deira bustad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'for at dei skulde leita etter Gud, um dei då kunde kjenna og finna honom, endå han ikkje er langt burte frå nokon einaste av oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'For i honom er det me liver og rører oss og er til, som og nokre av skaldarne dykkar hev sagt: «For me er ogso hans ætt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Når me då er Guds ætt, må me ikkje tru at guddomen er lik gull eller sylv eller stein, eit bilæte av menneskjeleg kunst og tanke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Etter at Gud då hev havt tol med dei tidar då vankunna rådde, so byd han no alle menneskje alle stader at dei skal umvenda seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'etter som han hev fastsett ein dag då han vil døma mannheimen med rettferd ved ein mann som han fyreskipa til det, etter at han hadde gjeve jarteigner for alle med å reisa honom upp frå dei daude.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Men då dei høyrde um uppstoda av daude, spotta nokre, men andre sagde: «Me vil høyra deg ein gong til um dette.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'So gjekk då Paulus burt ifrå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Men nokre menner heldt seg til honom og kom til tru, millom deim ogso Dionysius, ein av domarane på Areopagus, og ei kvinna med namnet Damaris og andre med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'So drog han frå Aten og kom til Korint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Der fann han ein jøde med namnet Akvilas, som var fødd i Pontus og nyst var komen frå Italia, og Priskilla, kona hans; for Klaudius hadde påbode at alle jødar skulde hava seg burt frå Rom; og han gjekk til deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'og då han dreiv same handverket, budde han hjå deim og arbeidde der; for dei var tjeldmakarar av handverk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Men han heldt samtalar i synagoga kvar kviledag og yvertydde jødar og grækarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Då so Silas og Timoteus kom ned frå Makedonia, var Paulus fullt uppteken med å læra, med di han vitna for jødarne, at Jesus er Messias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Men då dei stod imot og spotta, riste han dusti av klædi sine og sagde til deim: «Dykkar blod kome yver dykkar hovud! Eg er rein; frå denne stundi gjeng eg til heidningarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'So gjekk han burt derifrå og kom i huset til ein mann med namnet Justus, som dyrka Gud, og hans hus låg vegg i vegg med synagoga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Men Krispus, synagoge-forstandaren, kom til tru på Herren med heile sitt hus; og mange av folket i Korint kom til tru då dei høyrde honom, og let seg døypa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Og Herren sagde til Paulus i ei syn um natti: «Ottast ikkje, men tala, og teg ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'For eg er med deg, og ingen skal leggja hand på deg og gjera deg vondt; for eg hev mykje folk i denne byen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Og han vart buande der eit år og seks månader, og lærde Guds ord millom deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Men då Gallio var landshovding yver Akaia, reiste jødarne seg alle som ein mot Paulus og førde ham fram for domstolen og sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, '«Denne set folk upp til å dyrka Gud imot lovi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Då Paulus vilde opna munnen, sagde Gallio til jødarne: «Var det nokor illgjerning eller noko vondt ustykke, de jødar, då hadde eg med god grunn høyrt på dykk med tolmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Men er det stridsspursmål um ei læra og um namn og um dykkar lov, so stell med det sjølve! for i dei ting vil ikkje eg vera domar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Og so dreiv han deim burt frå domstolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Men då tok dei alle fat på Sostenes, synagoge-forstandaren, og slo honom midt for domstolen. Og Gallio brydde seg ikkje noko um alt dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Paulus vart der endå ei lang tid; so bad han velfar med brørne og siglde burt til Syria, og Priskilla og Akvilas i fylgje med honom, etter at han fyrst i Kenkreæ hadde klypt håret sitt, for han hadde ein lovnad på seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'So kom dei til Efesus; der let han dei andre vera att, og sjølv gjekk han inn i synagoga og gav seg i samtale med jødarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Då dei bad honom vera der lenger, samtykte han ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'men baud deim velfar og sagde: «Eg skal koma til dykk att, um Gud so vil.» So siglde han frå Efesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'og han kom til Cæsarea, og han drog upp og helsa på kyrkjelyden og drog so ned til Antiokia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Då han hadde vore der ei tid, drog han ut og for gjenom Galatarlandet og Frygia frå ende til ende og styrkte alle læresveinarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Men ein jøde med namnet Apollos, fødd i Aleksandria, ein ordhag mann, kom til Efesus; han var sterk i skrifterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Han var upplærd um Herrens veg, og brennande i åndi tala og lærde han grannleg um Herren, endå han kjende berre Johannes-dåpen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Og han tok til å tala frimodigt i synagoga. Då Priskilla og Akvilas høyrde honom, tok dei honom til seg og greidde Guds veg grannare ut for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Då han so vilde draga derifrå til Akaia, talde brørne honom til og skreiv til læresveinarne um å taka imot honom. Og då han kom dit, var han ved Guds nåde til stor hjelp for dei truande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'For med kraft målbatt han jødarne openberrleg for alle, med di han synte ut or skrifterne at Jesus er Messias.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Medan Apollos var i Korint, hende det at Paulus kom til Efesus, etter han hadde fare gjenom dei øvre bygder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Der fann han nokre læresveinar og sagde til deim: «Fekk de den Heilage Ande då de vart truande?» Dei svara honom: «Me hev ikkje ein gong høyrt um den Heilage Ande er komen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Han sagde til deim: «Kva dåp er de då døypte med?» Dei sagde: «Med Johannes’ dåp.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Då sagde Paulus: «Johannes, han døypte med umvendings dåp, med di han sagde til folket, at dei skulde tru på den som kom etter honom, det er på Jesus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Då dei høyrde det, let dei seg døypa til Herren Jesu namn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'og då Paulus lagde henderne på deim, kom den Heilage Ande yver deim, og dei tala med tungor og profetiske ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Desse mennerne var umkring tolv i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Han gjekk då inn i synagoga og tala frimodigt i tri månader, med di han samtala med deim og yvertydde deim um det som høyrer til Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Men då nokre forherde seg og ikkje vilde tru, og tala ille for mengdi um denne vegen, braut han lag med deim og skilde læresveinarne ut og heldt dagleg samtalar i skulen åt Tyrannus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Dette varde i tvo år, so at alle dei som budde i Asia, fekk høyra Herrens ord, både jødar og grækarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Og uvanlege kraftverk gjorde Gud ved Paulus’ hender,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'so at folk endå tok sveitedukar eller fangskinn som han hadde havt på seg, og gjekk med deim til dei sjuke, og dei vart fri for sjukdomarne, og dei vonde ånderne for ut or deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Men nokre av dei jødar som for ikring og mana ånder, tok til å nemna Herren Jesus namn yver deim som hadde dei vonde ånderne, med di dei sagde: «Eg manar dykk ved den Jesus som Paulus forkynner.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Det var nokre søner til Skevas, ein jødisk øvsteprest, sju i talet, dei som gjorde dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Men den vonde åndi svara og sagde: «Jesus kjenner eg, og Paulus veit eg um; men de, kven er de?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Og mannen som den vonde åndi var i, sprang innpå deim og vann på deim og fekk yvermagt yver deim, so at dei laut fly nakne og såra ut or huset.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Dette vart kunnigt for alle som budde i Efesus, både jødar og grækarar, og der kom ræddhug på deim alle, og Herren Jesu namn vart høglova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Og mange av deim som hadde teke ved trui, kom og vitna og fortalde um sine gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Og ein stor hop av deim som hadde fare med fåfengde kunster, bar bøkerne sine i hop og brende deim upp so alle folk såg det. Og dei rekna saman deira verde og fann at det var femti tusund sylvpengar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Soleis hadde Herrens ord veldug framgang og fekk magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Då dette var fullført, sette Paulus seg fyre å draga gjenom Makedonia og Akaia og fara til Jerusalem, med di han sagde: «Når eg hev vore der, lyt eg og sjå Rom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'So sende han tvo av hjelpesmennerne sine, Timoteus og Erastus, til Makedonia; sjølv vart han endå verande ei tid i Asia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Men ved den tid vart der ikkje lite uppstyr um Guds veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'For det var ein mann med namnet Demetrius, ein sylvsmed, som gjorde Artemis-tempel av sylv og gav kunstsmedarne ikkje liti vinning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Han kalla saman desse og dei arbeidarar som sysla med det same, og sagde: «Menner, de veit at det er av dette arbeidet me hev vårt velstand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Og de ser og høyrer at ikkje berre i Efesus, men yver mest heile Asia hev denne Paulus ved yverteljing avvendt ein stor hop, med di han segjer at dei ikkje er gudar, dei som vert gjorde med henderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'No er det ikkje berre den fåren at dette vårt handverk skal få eit uord, men ogso at den store gudinna Artemis’ tempel skal verta rekna for ingen ting, og hennar storvelde verta øydelagt, ho som heile Asia og mannheimen dyrkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Då dei høyrde dette, vart dei fulle av harm og ropa: «Stor er den efesiske Artemis!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Og heile byen kom i fullt upprør, og dei styrmde alle som ein til teatret og reiv med seg makedonarane Gaius og Aristarkus, fylgjesmennerne åt Paulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Då Paulus vilde ganga inn til folket, let ikkje læresveinarne honom få lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Nokre av asiarådarne, som var hans vener, sende og bod til honom og bad honom at han ikkje måtte ganga inn i teatret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Nokre ropa då eitt, andre noko anna; for folkehopen var reint fortulla, og dei fleste visste ikkje kva dei var komne saman for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Men nokre av flokken sette Aleksander inn i saki, då jødarne skuva honom fram. Men Alexander slo til ljod med handi og vilde halda ein forsvarstale til folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Men då dei fekk vita at han var ein jøde, vart det eit einaste rop frå deim alle, so dei mest i tvo timar ropa: «Stor er den efisiske Artemis!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Men byskrivaren fekk då stagga hopen og sagde: «Menner frå Efesus? Kva menneskje er det vel som ikkje veit at efesar-byen er tempelvaktar for den store gudinna Artemis og hennar himmelfalne bilæte?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Då no ingen segjer imot dette, so må de styra dykk og ikkje gjera noko for framfust.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'For de hev ført hit desse mennerne, som korkje er tempelranarar eller spottar dykkar gudinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Hev no Demetrius og kunstsmedarne med honom nokor klaga på nokon, so vert det då halde rettarmøte, og her er landshovdingar; lat deim so føra klaga på kvarandre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Men dersom det er noko anna de søkjer, so skal det verta avgjort på det lovlege ålmannating.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'For det er jamvel fåre for at me skal verta klaga for upprør etter dette i dag, då det ingen grunn finst, som me kann bruka til å gjera greida for dette upplaupet.» [Stu21: 41] Og med å segja dette fekk han hopen til å skiljast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Då so uppstyret hadde stilna, kalla Paulus læresveinarne til seg og gav deim påminningar og bad farvel med deim; so drog han ut og vilde fara til Makedonia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Då han hadde fare gjenom desse landi og påminnt deim med mange ord, kom han til Grækland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Der vart han verande tri månader; og då jøderne lagde upp meinråd imot honom medan han skulde til å sigla til Syria, tok han den råd å leggja attervegen gjenom Makedonia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Til Asia fylgde honom Sopater, son åt Pyrrus, frå Berøa, og av deim frå Tessalonika Aristarkus og Sekundus, og Gaius frå Derbe og Timoteus, og av deim frå Asia Tykikus og Trofimus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Desse drog i fyrevegen og venta på oss i Troas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Men me siglde ut frå Filippi etter søtebrødhelgi, og kom fem dagar etter til deim i Troas, der me so drygde i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Den fyrste dagen i vika var me saman og braut brødet; då heldt Paulus samtalar med deim, av di han vilde draga burt dagen etter, og han tøygde talen ut like til midnatt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Det var mange lampor i salen der me var samla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Men ein ung mann med namnet Eutykus sat i vindauga og var fallen i djup svevn, då Paulus drog samtalen so lenge ut, og i svevnen datt han ut og sturta ned frå tridje høgdi og vart teken upp livlaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Men Paulus gjekk ned og kasta seg yver honom og tok honom i famnen og sagde: «Ståka ikkje! for sjæli hans er i honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'So gjekk han upp att og braut brødet og åt av det; og då han hadde tala med deim ei lang stund heilt til dagsprett, drog han av stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Dei førde guten livande burt og vart storleg trøysta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Me hadde då gjenge um bord i skipet og siglde av til Assus og skulde taka Paulus um bord der; for so hadde han påbode, då han sjølv vilde ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Då han so kom til oss i Assus, tok me honom um bord og kom til Mitylene;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'og derifrå siglde me og kom dagen etter beint utfor Kios; andre dagen kom me til Samos, og då me hadde drygt ei stund i Trogillium, kom me dagen etter til Milet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'For Paulus hadde sett seg fyre å sigla utanum Efesus, so han ikkje skulde spilla tid i Asia; for han trøytte seg etter å nå Jerusalem til kvitsundagen, um det var mogelegt for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Frå Milet sende han so bod til Efesus og kalla til seg dei eldste for kyrkjelyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Då dei var komne til honom, sagde han til deim: «De veit korleis mi ferd hjå dykk hev vore heile tidi, alt frå fyrste dagen eg kom til Asia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'at eg tente Herren med all audmykt og med tåror og i freistingar, som meinråderne frå jødarne førde yver meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'korleis eg ikkje heldt att noko av det som kunde vera dykk til gagn, men forkynte dykk det og lærde dykk det for ålmenta og heime i husi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'med di eg vitna både for jødar og grækarar um umvendingi til Gud og trui på vår Herre Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Og no, sjå, bunden av Anden dreg eg til Jerusalem, og veit ikkje kva som der skal møta meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'utan det at den Heilage Ande i by etter by vitnar for meg og segjer at band og trengslor ventar meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Men for meg sjølv agtar eg ikkje mitt liv eit ord verdt, når eg berre kann fullføra mitt laup og den tenesta som eg fekk av Herren Jesus: å vitna um evangeliet um Guds nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Og no, sjå, eg veit at de ikkje meir skal sjå mi åsyn, alle de som eg gjekk um imillom og forkynte Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Difor vitnar eg for dykk på denne dagen at eg er rein for alle manns blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'For ikkje heldt eg noko undan, men eg forkynte dykk heile Guds råd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Gjev då agt på dykk sjølve og på heile den hjord som den Heilage Ande sette dykk til tilsynsmenner i til å vakta Guds kyrkjelyd, som han vann seg med sitt eige blod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Eg veit at etter min burtgang skal det koma inn millom dykk ville vargar, som ikkje sparer hjordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Ja, frå dykk sjølve skal det koma fram folk som fer med forvend tale og vil lokka læresveinarne etter seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Vak difor, og kom i hug at eg tri år natt og dag ikkje heldt upp med å påminna kvar ein med tåror!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Og no legg eg dykk yver på Gud og hans nådeord, han som hev magt til å uppbyggja dykk og gjeva dykk arvlut bland alle deim som hev vorte helga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Ingen manns sylv eller gull eller klædnad hev eg kravt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'De veit sjølve at det som eg sjølv trong, og dei som var med meg, det hev desse henderne arbeidt for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'I alle måtar synte eg dykk, at soleis skal me med strævsamt arbeid vera til hjelp for dei veike og hugsa på Herren Jesu ord, som han sjølv hev sagt: «Det er sælare å gjeva enn å taka.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Då han hadde sagt dette, fall han på kne og bad saman med deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Då brast dei alle i sterk gråt og fall Paulus um halsen og kysste honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Og mest vondt gjorde deim det ordet han hadde sagt, at dei ikkje meir skulde få sjå hans åsyn. So fylgde dei honom til skipet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Då me hadde rive oss frå deim og siglt av stad, kom me beinleides til Kos, næste dagen til Rodus og derifrå til Patara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Der fann me eit skip som skulde fara yver til Fønikia, og me gjekk då um bord og siglde av stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Då me fekk Kypern i syne og hadde late henne etter oss på vinstre handi, siglde me til Syria og lagde åt ved Tyrus; for der skulde skipet lossa farmen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Me leita då upp læresveinarne og vart verande der sju dagar; dei sagde ved Anden til Paulus, at han ikkje skulde fara upp til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Då me hadde vore der dei dagarne ut, drog me derifrå og for lenger, og dei fylgde oss alle med kvinnor og born radt utanfor byen. So fall me på kne på strandi og bad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'og då me hadde sagt kvarandre farvel, gjekk me um bord på skipet; men dei andre vende heim att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Me fullenda no sjøferdi og kom frå Tyrus til Ptolemais; der helsa me på brørne og vart ein dag yver hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Dagen etter drog me derifrå og kom til Cæsarea; der tok me inn til evangelisten Filip, som var ein av dei sju, og vart verande hjå honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Han hadde fire ugifte døtter som hadde profetgåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Då me vart der fleire dagar, kom det ned frå Judæa ein profet med namnet Agabus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Han kom til oss og tok Paulus’ belte og batt seg sjølv på hender og føter og sagde: «So segjer den Heilage Ande: «Den mannen som eig dette beltet, skal jødarne binda soleis i Jerusalem og gjeva honom yver i henderne på heidningarne.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Då me høyrde dette, bad både me og dei som der budde, at han ikkje måtte fara upp til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Men Paulus svara: «Kvifor græt de og slit hjarta mitt sund? Eg er reidbuen ikkje berre til å verta bunden, men og til å døy i Jerusalem for Herren Jesu namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Men då han ikkje var til å få yvertald, vart me stille og sagde: «Herrens vilje råde!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Då desse dagarne var lidne, gjorde me oss ferdige og for upp til Jerusalem,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'og nokre av læresveinarne i Cæsarea fylgde og med oss, og dei førde oss til ein som me skulde bu hjå, Mnason frå Kypern, ein gamall læresvein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Då me kom til Jerusalem, fagna brørne oss med gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Andre dagen gjekk Paulus med oss til Jakob, og alle dei eldste kom dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Og då han hadde helsa på deim, fortalde han det eine etter det andre av det som Gud hadde gjort hjå heidningarne ved hans tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Då dei høyrde det, lova dei Gud; og so sagde dei til honom: «Du ser, bror, kor mange tusund det er av jødar som hev teke ved trui, og alle hev dei stor ihuge for lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Men dei hev spurt um deg, at du ute millom hedningarne lærer alle jødar fråfall frå Moses, med di du segjer at dei ikkje skal umskjera borni sine eller liva etter dei gamle sedvanarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Kva er då å gjera? Det vil i vissa koma ei stor mengd saman; for dei vil få høyra at du er komen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Gjer no difor som me segjer deg! Der er millom oss fire menner som hev ein lovnad på seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Tak deim med deg og lat deg reinsa saman med deim, og ber du kostnaden for deim, so dei må kunna raka hovudet; so kann alle skyna at det er ingen ting i det som dei hev høyrt um deg, men at du og ferdast so at du held lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Men um dei heidningarne som hev teke trui, hev me sendt brev og avgjort at dei ikkje skal halda noko slikt, men berre vara seg for avgudsoffer og blod og det strøypte og hor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Då tok Paulus mennerne med seg og let seg dagen etter reinsa saman med deim og gjekk inn i templet og vilde melda utgangen av reinsingsdagarne, då offeret skulde verta framført for kvar av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Då det so leid mot enden av dei sju dagarne, fekk jødarne frå Asia sjå honom i templet, og dei øste upp heile hopen og lagde hand på honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'medan dei skreik: «Israelitiske menner, kom til hjelp! Dette er det menneskjet som alle stader lærer alle imot folket og lovi og denne staden, og han hev jamvel ført grækarar inn i templet og vanhelga denne heilage staden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'For dei hadde fyrr set Trofimus frå Efesus saman med honom ute i byen, og so tenkte dei at Paulus hadde ført honom inn i templet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Og det vart røra i heile byen og samanstrøyming av folket, og dei tok fat på Paulus og drog honom utanfor templet, og straks vart dørerne stengde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Medan dei heldt på og vilde slå honom i hel, gjekk det melding upp til den øvste hovudsmannen for vakti, at heile Jerusalem var i ei røra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Han tok straks hermenner og hovudsmenner og skunda seg ned til deim. Men då dei såg den øvste hovudsmannen og hermennerne, heldt dei upp med å slå Paulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Då kom den øvste hovudsmannen burt til honom og let deim gripa honom, og baud at han skulde verta bunden med tvo lekkjor; og han spurde kven han var, og kva han hadde gjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Men den eine i hopen ropa det, og den andre det; og då han ikkje retteleg kunde få vissa for ståket skuld, baud han at han skulde førast inn i borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Då han kom upp til troppestigi, vart det so at hermennerne laut bera honom, so ustyrleg var hopen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'for folkehopen fylgde med og skreik: «Drep honom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Då Paulus skulde førast inn i borgi, sagde han til den øvste hovudsmannen: «Må eg få segja noko til deg?» Han svara: «Kann du græsk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'So er du då ikkje den egyptaren som gjorde upprør for ei tid sidan og førde dei fire tusund mordarar ut i øydemarki?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Då sagde Paulus: «Eg er ein jøde frå Tarsus, borgar av ein ikkje ukjend by i Kilikia. Men eg bed deg: Gjev meg lov å tala til folket!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Då han gav honom lov, stelte Paulus seg i troppi og slo til ljod åt folket med handi. Då det vart reint stilt, tala han til deim på det hebraiske målet og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '«Brør og feder! høyr det som eg no vil segja dykk til mitt forsvar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Då dei høyrde at han tala til deim på det hebraiske målet, vart dei endå meir stille. So segjer han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '«Eg er ein jøde, fødd i Tarsus i Kilikia, men uppfostra i denne byen ved Gamaliels føter, upplærd i dei strenge krav etter fedrelovi, og eg var ihuga for Gud, so som alle de er i dag;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'eg forfylgde Guds veg til dauden, lagde i lekkjor og yvergav til fangehus både menner og kvinnor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'so som og øvstepresten og heile eldsterådet kann vitna med meg; av deim fekk eg jamvel brev med til brørne i Damaskus og for dit og vilde føra ogso deim som der var, bundne til Jerusalem, so dei skulde verta refste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Men det hende, då eg var på vegen og kom nær til Damaskus, då lyste det brått ved middagsleite eit sterkt ljos frå himmelen ikring meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Og eg fall til jordi og høyrde ei røyst som sagde til meg: «Saul, Saul, kvi forfylgjer du meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Eg svara: «Kven er du, Herre?» Og han sagde til meg: «Eg er Jesus frå Nasaret, han som du forfylgjer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Dei som var med meg, såg ljoset, men røysti av honom som tala til meg, høyrde dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Då sagde eg: «Kva skal eg gjera, Herre?» Og Herren svara meg: «Statt upp og gakk inn i Damaskus; der skal det verta tala til deg um alt det som det er fyresett deg å gjera.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Då eg no ikkje kunde sjå for glima av det ljoset, vart eg leidd ved handi av fylgjesmennerne mine og kom inn i Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Og ein som heitte Ananias, ein gudleg mann etter lovi, med godt lov av alle dei jødar som budde der,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'han kom til meg og stod framfyre meg og sagde: «Saul, bror, sjå upp!» og eg såg upp på honom i same stundi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Og han sagde: «Vår fedregud hev valt deg ut til å vita hans vilje og sjå den Rettferdige og høyra røysti av hans munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'For du skal vera honom eit vitne for alle menneskje um det du hev set og høyrt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Og no, kva drygjer du etter? statt upp og lat deg døypa og få dine synder avtvegne, og kalla på Herrens namn!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Og det hende meg, då eg var komen att til Jerusalem og bad i templet, at det kom ei burtrykning på meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'og eg såg honom, og høyrde han sagde til meg: «Skunda deg og gakk i hast ut frå Jerusalem! for dei kjem ikkje til å taka imot vitnemålet ditt um meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Då sagde eg: «Herre, dei veit sjølve at eg sette fast og hudflengde ikring i synagogorne deim som trudde på deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Og då blodet av Stefanus, ditt vitne, vart utrent, då stod eg og attved og samtykte i det og vakta klædi deira som slo honom i hel.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Og han sagde til meg: «Gakk! for eg vil senda deg ut til heidningfolk langt burte.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Dei høyrde på honom til dette ordet; men då lyfte dei røysti og sagde: «Tak denne burt ifrå jordi! han burde ikkje få liva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Då dei no skreik og reiv klædi av seg og kasta dust upp i veret,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'baud den øvste hovudsmannen at han skulle førast inn i borgi, og sagde at han skulde verta forhøyrd med hudflengjing, so han kunde få vita kvifor dei ropa soleis imot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Men då dei hadde bunde honom til slag med reimarne, sagde Paulus til hovudsmannen som stod der: «Hev de lov til å hudflengja ein romersk borgar, og det udømd?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Då hovudsmannen høyrde det, gjekk han til den øvste hovudsmannen og melde det og sagde: «Sjå til kva du vil gjera? for denne mannen er romersk borgar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Den øvste hovudsmannen gjekk då burt til honom og sagde: «Seg meg: Er du romersk borgar?» Han svara: «Ja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Den øvste hovudsmannen svara: «Eg hev kjøpt meg denne borgarretten for mange pengar.» Men Paulus sagde: «Men eg er endå fødd til honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Då gjekk dei straks frå honom, dei som skulde forhøyra honom; men ogso den øvste hovudsmannen vart rædd, då han fekk vita at han var romersk borgar, for di han hadde bunde honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Men dagen etter, då han no vilde få full greida på det som jødarne klaga honom for, løyste han honom or lekkjorne og baud at øvsteprestarne og heile rådet skulde koma saman. Og han førde Paulus ned og stelte honom fram for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Då feste Paulus augo på rådet og sagde: «Brør! Eg hev med alt godt samvit fare mi ferd for Gud til denne dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Øvstepresten Ananias baud deim som stod der, å slå honom på munnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Då sagde Paulus til honom: «Gud skal slå deg, du kalka vegg! Og du sit her og skal døma meg etter lovi, og imot lovi byd du at dei skal slå meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Dei som stod der, sagde: «Skjeller du ut Guds øvsteprest?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Og Paulus sagde: «Eg visste ikkje, brør, at det var øvstepresten; for det stend skrive: «Ein hovding for ditt folk skal du ikkje skjella!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Då no Paulus visste at den eine parten av deim var sadducæarar, og den andre farisæarar, ropa han i rådet: «Brør! Eg er ein farisæar, son åt farisæarar; det er for von og for uppstoda av daude at eg stend her for retten.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Då han hadde sagt dette, vart det strid millom farisæarane og sadducæarane, og flokken vart usamd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'For sadducæarane segjer at det ikkje er nokor uppstoda og ingen engel eller ånd heller. Men farisæarane vedkjenner seg båe dei ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'No vart det eit stort skrik, og skriftlærde av farisæarflokken stod upp og stridde hardt og sagde: «Me finn inkje vondt hjå dette menneskjet; um det no var ei ånd som tala til honom, eller ein engel?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Då det vart stor strid, og den øvste hovudsmannen vart rædd for at dei skulde slita Paulus sund, baud han hermennerne ganga ned og riva honom ifrå deim og føra honom inn i borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Men natti etter stod Herren framfyre honom og sagde: «Ver hugheil! liksom du vitna um meg i Jerusalem, so skal du og vitna i Rom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Men då det vart dag, slo jødarne seg saman og forbanna seg på at dei korkje skulde eta eller drikka fyrr dei hadde drepe Paulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Det var meir enn fyrti som soleis hadde samansvore seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'og dei gjekk til øvsteprestarne og dei eldste og sagde: «Me hev forbanna oss på at me ikkje skal smaka nokon ting fyrr me hev drepe Paulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'No må de då saman med rådet lata den øvste hovudsmannen vita, at han skal føra honom ned til dykk, liksom de vilde ransaka grannare um honom. So held me oss ferdige til å drepa honom fyrr han når fram.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Men systerson til Paulus fekk høyra um den løynrådi, og han kom og gjekk inn i borgi og fortalde Paulus det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Paulus kalla då ein av hovudsmennerne til seg og sagde: «Før denne unge mannen til den øvste hovudsmannen, for han hev noko å melda honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Han tok honom då med seg og førde honom til den øvste hovudsmannen og sagde: «Den bundne Paulus kalla på meg og bad meg føra denne unge mannen til deg, då han hadde noko å segja deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Den øvste hovdingen tok honom ved handi og gjekk i einrom med honom og spurde: «Kva er det du hev å melda meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Han sagde: «Jødarne er samrådde um å beda deg at du i morgon skal føra Paulus ned til rådet, liksom dei vilde spyrja noko grannare um honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Du må ikkje gjera deim til viljes, for meir enn fyrti menner av deim lurer i løynd på honom, og dei hev forbanna seg på at dei korkje skal eta eller drikka fyrr dei hev drepe honom; og no er dei ferdige og ventar på ja-minne frå deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Den øvste hovudsmannen let då den unge mannen ganga og baud honom: «Du må ikkje fortelja nokon at du hev late meg vita dette!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Og han kalla til seg eit par av hovudsmennerne og sagde: «Lat tvo hundrad hermenner helda seg ferdige til å fara til Cæsarea, og sytti hestfolk og tvo hundrad skyttarar, frå den tridje timen på natti!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Og han baud at dei skulde halda øyk i stand, so dei kunde lata Paulus rida på deim og føra honom trygt fram til landshovdingen Feliks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Og han skreiv eit brev med dette innhaldet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '«Klaudius Lysias helsar den megtige landshovdingen Feliks.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Denne mannen, som var gripen av jødarne og so nær hadde vorte drepen av deim, honom kom eg og fria ut med herfolket, då eg fekk vita at han var romersk borgar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'og då eg vilde vita kva sak det var dei klaga honom for, førde eg honom ned for rådet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Eg fann honom då klaga for nokre spursmål i deira lov, men utan noko klagemål som gjorde honom skuldig til daude eller lekkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Men då det no er meldt meg at ei meinråd mot mannen er i gjerdom, sender eg honom straks til deg, etter at eg hev bode klagarane hans å bera fram for deg det dei hev å segja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'So tok då hermennerne Paulus, so som det var deim pålagt, og førde honom um natti til Antipatris,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'og dagen etter let dei hestfolket draga med honom og vende so um att til borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Hine kom då til Cæsarea og gav landshovdingen brevet, og dei førde og Paulus fram for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Då han hadde lese det og spurt kva land han var ifrå, og hadde fenge vita at han var frå Kilikia, sagde han:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, '«Eg skal taka deg i forhøyr når klagarane dine kjem.» Og han baud at han skulde haldast i varetekt i Herodes-borgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Fem dagar etter kom øvstepresten Ananias ned med nokre av styresmennerne og ein talar, Tertullus; dei bar fram for landshovdingen klaga mot Paulus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Han vart då kalla fram, og Tertullus tok til å klaga honom og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '«Då me kann takka deg for mykjen fred, og det ved di umsut er gjort rettarbøter for dette folket i alle måtar og alle stader, so skynar me på dette, megtigaste Feliks, med all takksemd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Men at eg ikkje skal hefta deg for lenge, so bed eg at du med ditt godlynde vil høyra på oss som stuttast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'For me hev funne at denne mannen er ein pest og ein uppøsar millom alle jødarne yver heile mannheimen og ein hovudmann for serflokken nasaræarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Han hev endå søkt å vanhelga templet; og me greip honom då og vilde døma honom etter vår lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Men Lysias, den øvste hovudsmannen, kom og førde honom burt frå våre hender med stort valdsverk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'og han baud klagarane hans å koma til deg; og av honom kann du sjølv, når du ransakar det, få kunnskap um alt det som me klagar honom for.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Men jødarne sanna med og sagde at dette hadde seg soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Men då landshovdingen nikka til honom, at han kunde få tala, so svara Paulus: «Då eg veit at du hev vore domar for dette folket i mange år, fører eg mitt forsvar med fritt mod;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'for du kann vissa deg um at det ikkje er meir enn tolv dagar sidan eg gjekk upp til Jerusalem og vilde tilbeda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Og korkje i templet eller i synagogorne eller ikring i byen fann dei meg talande med nokon eller eggjande folk til upprør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Og dei kann ikkje heller prova for deg dette som dei klagar meg for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Men det sannar eg for deg, at etter den vegen som dei kallar ein serflokk, tener eg so min fedregud, at eg trur alt som er skrive i lovi og profetarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'og hev den voni til Gud som desse og sjølve ventar, at det skal koma ei uppstoda av daude, både av rettferdige og urettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Difor legg eg sjølv vinn på alltid å hava eit uskadt samvit for Gud og menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Då mange år var lidne, kom eg hit og skulde gjeva mitt folk milde gåvor og ofra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'og dermed fann dei meg i templet, då eg hadde reinsa meg utan folkestim og utan uppstyr; men det var nokre jødar frå Asia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'og dei skulde koma fram for deg og klaga, um dei hadde noko å bera på meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Eller lat desse sjølve segja kva skuld dei fann hjå meg, då eg stod framfor rådet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'utan det skulde vera for dette eine ordet som eg ropa ut, då eg stod millom deim: «For uppstoda av daude stend eg i dag for retten millom dykk!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Men Feliks sette ut saki, då han visste betre um Guds veg, og han sagde: «Når Lysias, hovudsmannen, kjem her ned, skal eg prøva saki dykkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Og han baud hovudsmannen halda honom i varetekt og lata honom hava ro og ikkje hindra nokon av hans eigne frå å vera honom til tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Då nokre dagar var farne, kom Feliks med Drusilla, kona si, som var ei jødisk kvinna, og sende bod etter Paulus og høyrde honom um trui på Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Men då han tala um rettferd og fråhald og den komande dom, vart Feliks rædd og svara: «Gakk burt denne gongen! når eg fær gode stunder, skal eg kalla deg til meg att.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Han hadde og den voni, at han skulde få pengar av Paulus; difor sende han og oftare bod etter honom og tala med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Då tvo år var lidne, fekk Feliks til ettermann Porcius Festus; og då Feliks vilde vinna seg takk av jødarne, let han Paulus bunden etter seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Då no Festus var komen til landshovding-embættet sitt, for han tri dagar etter upp til Jerusalem frå Cæsarea.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Øvsteprestarne og dei fyrste menner av jødarne bar då fram for honom klaga mot Paulus og kom med ei bøn til honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'med di dei mot honom bad um det som ein nåde, at han skulde henta honom til Jerusalem; for dei lagde den løynrådi å slå honom i hel på vegen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Men Festus svara då at Paulus var i varetekt i Cæsarea, og at han sjølv vilde fara dit snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '«So kann dei av dykk,» sagde han, «som hev umbod til det fara ned saman med meg, um det er noko gale med denne mannen, og klaga på honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Då han so hadde drygt hjå deim berre åtte eller ti dagar, for han ned til Cæsarea; dagen etter sette han seg på domstolen og baud at Paulus skulde førast fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Då han var komen, stelte dei jødarne som var komne ned frå Jerusalem, seg ikring honom og bar fram imot honom mange og tunge klagemål; men dei kunde ikkje prova deim,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'for Paulus forsvara seg og sagde: «Korkje mot den jødiske lov eller mot templet eller mot keisaren hev eg synda noko.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Men då Festus vilde vinna seg takk av jødarne, svara han Paulus og sagde: «Er du viljug til å fara upp til Jerusalem og der få dom av meg i denne sak?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Då sagde Paulus: «For keisarens domstol stend eg, og der hev eg rett til å verta dømd. Mot jødarne hev eg ingen urett gjort, so som du og vel veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Hev eg urett, og hev gjort noko som gjer meg skuldig til dauden, so bed eg meg ikkje fri for å døy. Men er det ikkje noko i det som desse klagar meg for, då kann ingen yvergjeva meg til deim berre for å gjera deim til lags. Eg skyt saki inn for keisaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Då tala Festus med rådet sitt, og so sagde han: «For keisaren hev du skote saki inn; til keisaren skal du fara.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Men då nokre dagar var lidne, kom kong Agrippa og Berenike til Cæsarea og vilde helsa på Festus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Då dei hadde vore der i fleire dagar, fortalde Festus kongen um Paulus og sagde: «Her er ein mann som Feliks let bunden etter seg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'då eg kom til Jerusalem, kom øvsteprestarne og styresmennerne for jødarne fram med ei klaga mot honom og kravde straff yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Eg svara deim at det ikkje er sedvane hjå romarane at dei for å gjera folk til lags yvergjev noko menneskje til dauden; men den som klaga gjeld, lyt fyrst standa åsyn til åsyn med klagarane sine og få høve til å forsvara seg mot klagemålet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Då dei so var komne saman her, drygde eg ikkje ut saki, men sette meg dagen etter på domstolen og baud at mannen skulde førast fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Då no klagarane stod ikring honom, bar dei ikkje fram noko klagemål slikt som eg hadde tenkt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Men dei hadde nokre kivsmål med honom um deira eigi gudsdyrking og um ein Jesus som var daud, men som Paulus sagde var livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Då eg stod rådlaus med ransakingi av dette, spurde eg um han vilde fara til Jerusalem og der få dom i saki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Men då Paulus innanka saki og vilde vera i varetekt til keisaren felte domen, baud eg at han skulde verta halden i varetekt til dess eg fær sendt honom til keisaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa sagde til Festus: «Eg vilde og gjerne høyra den mannen.» Han svara: «I morgon skal du få høyra honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Dagen etter kom so Agrippa og Berenike med stor stas og gjekk inn i salen saman med dei øvste hovudsmennerne og dei gjævastee menner i byen, og etter påbod av Festus vart Paulus førd fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Då segjer Festus: «Kong Agrippa og alle de menner som her er saman med oss, her ser de honom som heile hopen av jødarne både i Jerusalem og her bad meg um, og ropa at han ikkje lenger måtte få liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Men då eg fann at han ikkje hadde gjort noko som gjorde honom skuldig til dauden, og han sjølv og skaut saki inn for keisaren, so tok eg den avgjerdi å senda honom dit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Noko visst hev eg ikkje å skriva til herren um honom; difor førde eg honom fram for dykk og serleg for deg, kong Agrippa, so eg, når forhøyr er halde, kann hava noko å skriva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'For eg tykkjer det er meiningslaust når eg sender ein fange, at eg ikkje kann segja frå um klagemåli mot honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Då sagde Agrippa til Paulus: «Du fær lov til å tala um deg sjølv.» Då rette Paulus handi ut og forsvara seg soleis:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '«Imot alt det som jødarne klagar meg for, prisar eg meg lukkeleg, kong Agrippa, at eg i dag skal forsvara meg for deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'for du kjenner best til alle sedvanar og spursmål hjå jødarne; difor bed eg deg å høyra på meg med tolmod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Min livnad like frå ungdomen, som eg frå fyrste stund hev ført millom folket mitt og i Jerusalem, kjenner alle jødarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'då dei fyreåt veit um meg alt frå det fyrste, um dei vil vitna, at eg livde etter det strengaste serlaget i vår gudsdyrking, som farisæar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Og no stend eg her og skal verta dømd for von um lovnaden som Gud gav federne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'den som vårt tolvgreina folk med vedhaldande gudsdyrking natt og dag vonar å nå fram til; for denne von skuld, kong Agrippa, klagar jødar meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Kvi vert det halde for utrulegt millom dykk, at Gud vekkjer upp daude?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Eg for min part trudde at eg måtte gjera mykje imot nasaræaren Jesu namn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'det gjorde eg og i Jerusalem, og eg kasta mange av dei heilage i fangehus, då eg hadde fenge fullmagt frå øvsteprestarne, og når dei skulde verta ihelslegne, røysta eg med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'og ikring i alle synagogorne tvinga eg deim tidt med refsing til å spotta, og eg rasa endå meir imot deim og forfylgde deim endå til byarne utanlands.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Dermed for eg då og til Damaskus med fullmagt og umbod frå øvsteprestarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'og midt på dagen, konge, såg eg på vegen eit ljos, som klårare enn soli stråla frå himmelen ikring meg og fylgjesmennerne mine;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'og då me alle fall til jordi, høyrde eg ei røyst som tala til meg og sagde på hebraisk mål: «Saul, Saul, kvi forfylgjer du meg? Det vert hardt for deg å spenna mot brodden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Då sagde eg: «Kven er du, Herre?» Og Herren sagde: «Eg er Jesus, han som du forfylgjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Men reis deg upp og statt på føterne dine! For difor synte eg meg for deg, for å kåra deg ut til tenar og vitne både um det som du hev set, og um det som eg vil syna meg med for deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'med di eg friar deg ut frå folket og frå heidningarne som eg sender deg til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'at du skal opna augo deira, so dei kann venda seg frå myrker til ljos og frå Satans magt til Gud, for at dei skal få forlating for synderne og arvlut millom deim som er helga ved trui på meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Difor, kong Agrippa, var eg ikkje ulydug mot den himmelske syni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'men forkynte fyrst for folket i Damaskus og so i Jerusalem og i heile Judæaland og for heidningarne, at dei skulde gjera bot og venda um til Gud og gjera gjerningar som høver med umvendingi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'For desse ting skuld greip nokre jødar meg i templet og freista å taka livet av meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'So hev eg då fenge hjelp av Gud og stend alt til denne dagen og vitnar både for liten og stor, med di eg ikkje segjer anna enn det som profetarne og Moses hev sagt skulde koma:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'at Messias skulde lida, at han som fyrstemannen utav uppstoda av daude skulde forkynna ljos for folket og for heidningarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Men då han forsvara seg so, segjer Festus med høg røyst: «Du er frå vitet, Paulus. Din store lærdom driv deg til vitløysa.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Men han segjer: «Eg er ikkje frå vitet, megtigaste Festus, men talar sanne og umtenkte ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'For kongen veit um dette, og til honom talar eg og frimodig; for eg trur ikkje at noko av dette er ukjent for honom; for dette hev ikkje hendt i nokon avkrok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Trur du profetarne, kong Agrippa? Eg veit at du trur!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Men Agrippa sagde til Paulus: «Det skil lite på at du fær meg yvertald til å verta ein kristen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Då sagde Paulus: «Anten det er lite eller mykje som skal til, vilde eg ynskja til Gud, at ikkje berre du, men og alle dei som høyrer meg i dag, måtte verta slike som eg er, berre utan desse lekkjorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Då reiste kongen seg og landshovdingen og Berenike og dei som sat der med deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'og dei gjekk i einrom og tala med kvarandre og sagde: «Denne mannen gjer ingen ting som skulde gjera honom skuldig til daude eller lekkjor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Og Agrippa sagde til Festus: Denne mannen kunde vera laten laus, um han ikkje hadde skote saki si inn for keisaren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Då det no var avgjort at me skulde sigla av stad til Italia, gav dei både Paulus og nokre andre fangar yver til ein hovudsmann med namnet Julius ved den keisarlege herflokken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Me gjekk då um bord på eit skip frå Adramyttium, som skulde sigla frammed Asialandet, og so lagde me ut; Aristarkus, ein makedonar frå Tessalonika, var med oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Og den andre dagen for me inn til Sidon, og Julius, som var menneskjekjærleg mot Paulus, let honom få ganga til venerne sine og njota godt av deira omsut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Derifrå for me ut og siglde inn under Kypern, av di det var motvind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Og då me hadde siglt yver havet ved Kilikia og Pamfylia, kom me til Myra i Lykia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Der fann hovudsmannen eit skip frå Aleksandria, som skulde til Italia, og han sette oss um bord i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'I mange dagar gjekk det no seint med siglingi, og det var med naud me vann fram imot Knidus; då vinden var imot, heldt me inn under Kreta ved Salmone,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'og det var med naud me vann framum der og kom til ein stad som vert kalla Godhamn, nær ved ein by Lasæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Då lang tid var lidi, og det alt var fårleg å ferdast på sjøen, etter som jamvel fastetidi var ute, vara Paulus deim og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '«Menner, eg ser at sjøferdi vil vera eit våverk og til stor skade ikkje berre farm og skip, men og for vårt eige liv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Men hovudsmannen hadde betre tru til styrmannen og skiperen enn til det som Paulus sagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Og då hamni var ulagleg til vinterlægje, tok dei fleste den rådi å leggja ut ogso derifrå, um dei skulde kunna vinna fram og taka vinterlægje i Føniks, ei hamn på Kreta, som vender mot sudvest og nordvest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Då det no bles ein linn sunnanvind, tenkte dei at dei kunde fullføra si rådgjerd. Dei letta då og heldt tett frammed Kreta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Men ikkje lenge etter kom det ein kvervelstorm som vert kalla eurakylon, og kasta seg mot øyi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'då skipet kom på rek og ikkje kunde halda seg upp mot vinden, gav me det upp og let oss driva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Me gjekk då inn under ei liti øy, som vert kalla Klauda, og det var med naud me fekk berga inn båten;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'då dei hadde fenge honom inn, tok dei til naudhjelp og surra skipet med tog. Og då dei var rædde for å driva ned på Syrten, strika dei seglet og dreiv på den måten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Då me leid mykje vondt av veret, kasta dei den andre dagen farmen yver bord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'og tridje dagen kasta me ut skipsreidskapen med eigne hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Sidan korkje sol eller stjernor synte seg på fleire dagar, og veret stod stridt på, var det no reint ute med all von um å verta berga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Og då dei ikkje hadde fenge mat på lenge, steig Paulus fram midt imillom deim og sagde: «Menner, de skulde ha fylgt mi råd og ikkje fare frå Kreta og so sloppe for dette våverket og denne skaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Og no manar eg dykk til å vera ved godt mod; for ikkje ei sjæl av dykk skal forgangast, men berre skipet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'For i natt stod det framfyre meg ein engel frå den Gud som eg tilhøyrer, og som eg tener, og han sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, '«Ver ikkje rædd, Paulus! du skal stella deg fram for keisaren; og sjå, Gud hev gjeve deg alle deim som siglar med deg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Difor, menner, ver ved godt mod, for eg lit på Gud, at det skal verta so som det er sagt meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Men på ei øy skal me stranda.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Då den fjortande natti kom, og me dreiv ikring i Adriatarhavet, merka sjøfolki ved midnatt at det bar nær til land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Og då dei lodda, fann dei tjuge famnar. Men då dei var komne ei lite stykke derifrå og lodda på nytt, fann dei femtan famnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Og då dei var rædde for at dei skulde støyta på skjer nokon stad, kasta dei fire anker frå bakstamnen; og dei stunda på at det måtte verta dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Men sjømennerne freista å røma burt frå skipet og sette båten på sjøen og lest vilja føra anker ut frå framstamnen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'då sagde Paulus til hovudsmannen og hermennerne: «Dersom ikkje desse der vert verande um bord på skipet, so kann de ikkje verta berga.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Då hogg hermennerne togi til båten av, og slepte honom ned.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Då det so leid mot dag, bad Paulus alle å taka føda, og han sagde: «I dag er det den fjortande dagen som de ventar fastande, og ikkje fær dykk mat.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Difor bed eg dykk å taka føda; dette høyrer med til dykkar berging; for det skal ikkje forkomast eit hår av hovudet på nokon av dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Då han hadde sagt dette, tok han eit brød og takka Gud for augo på alle, og han braut det og tok til å eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Då vart dei alle ved godt mod og tok føda, dei og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Me var i det heile tvo hundrad og seks og sytti sjæler um bord på skipet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Og då dei hadde ete seg mette, letta dei skipet med å kasta matvarorne i sjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Då det no vart dag, kjende dei ikkje landet, men dei vart vare ei vik som hadde ei flat strand; der vilde dei setja skipet på land, um det var mogelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Og dei slepte ankeri og let deim etter i havet, medan dei og løyste togi som dei hadde bunde styri med, og då dei hadde vunde seglet upp for vinden, heldt dei inn imot strandi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Men dei dreiv inn på ein grunne med djup sjø på båe sidor, og skipet støytte på; og framstamnen, som sette seg fast, vart standande urørleg, men bakstamnen vart sundslegen av det sterke bårebrotet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'No vilde hermennerne drepa fangarne, so ingen skulde symja burt og røma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Men hovudsmannen, som vilde berga Paulus, hindra deim i denne rådi og gav det påbodet at dei som kunde symja, fyrst skulde kasta seg ut og koma i land,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'og so dei andre, sume på bordstubbar, andre på stykke av skipet. Og soleis hende det seg at alle vart berga i land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Då me no var berga, fekk me vita at øyi heitte Malta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Dei innfødde synte oss uvanleg mannemilda; dei kveikte ein eld og tok seg av oss alle saman, då det tok til å regna og var kaldt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Men då Paulus tok saman ein haug med turrkvist og lagde på elden, kom det for varmen skuld ein orm ut og beit seg fast i handi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Då dei innfødde såg dyret hanga ved handi hans, sagde dei til kvarandre: «Dette menneskjet er i all vissa ein mordar, som den hemnande rettferd ikkje gjev lov til å liva, endå han er berga frå havet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Han riste dyret av seg inn i elden og hadde ikkje noko mein av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Men dei venta at han skulde trutna upp eller brått siga daud ned. Men då dei hadde venta ei lang stund og såg at det ikkje hende honom noko ilt, slo dei um og sagde at han var ein gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Men ikkje langt frå den staden hadde den fyrste mannen på øyi ein gard; mannen heitte Publius, og han tok imot oss og synte oss venleg gjestmildskap i tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Og det råka so til, at far åt Publius låg hardt sjuk av feber og blodgang. Paulus gjekk inn til honom og bad og lagde henderne på honom og lækte honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Og då dette hadde hendt seg, kom og dei andre på øyi som hadde sjukdomar, og dei vart lækte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Dei gjorde og stor æra på oss, og då me for derifrå, førde dei um bord slikt som me kunde trenga til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Då tri månader var lidne, for me derifrå på eit skip frå Aleksandria, som hadde lege vinteren yver ved øyi og hadde Tvillingarne til merke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Og me kom inn til Syrakus og vart verande der i tri dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Derifrå siglde me ikring og kom til Regium; og då det vart sunnanvind dagen etter, kom me på tvo dagar til Puteoli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Der fann me brør og vart bedne um å drygja sju dagar hjå deim. Og so kom me til Rom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Og då brørne der fekk høyra um oss, gjekk dei ut imot oss til Forum Appii og Tres Tabernæ; då Paulus såg deim, takka han Gud og fekk mod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Då me so var komne til Rom, gav hovudsmannen fangarne yver til hovdingen for livvakti. Men Paulus fekk lov til å bu for seg sjølv saman med den hermannen som vakta honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Og då tri dagar var gjengne, hende det seg at Paulus kalla saman dei fyrste menner av jødarne der i byen, og då dei var komne saman, sagde han til deim: «Brør! Eg, som ingen ting hev gjort imot vårt folk eller våre fedre-seder, eg er frå Jerusalem yvergjeven som fange i henderne på romarane.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Då dei hadde forhøyrt meg, vilde dei lata meg laus, av di det ikkje var nokor daudssak imot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Men då jødarne sette seg imot det, vart eg nøydd til å skjota saki inn for keisaren, men ikkje som um eg hadde noko klaga mitt folk for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'For den sak skuld hev eg då kalla dykk hit, so eg kunde få sjå dykk og tala med dykk; for det er for Israels von skuld eg ligg i denne lekkja.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Dei sagde til honom: «Me hev ikkje fenge noko brev um deg frå Judæa, og ikkje hev nokon av brørne heller kome hit og fortalt eller sagt noko vondt um deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Men me finn det rett at du let oss høyra dine tankar; for um denne serflokken er det oss kunnigt at han vert motsagd alle stader.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Då dei hadde fastsett ein dag for honom, kom det ein større flokk til honom der han budde; og han lagde då ut for deim og vitna um Guds rike og søkte å yvertyda deim um Jesus ut av Mose lov og profetarne, frå tidleg um morgonen til seint på kvelden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Og nokre vart yvertydde ved det han sagde, men andre var vantruande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Dei gjekk frå kvarandre i usemja då Paulus hadde sagt det eine ordet: «Retteleg tala den Heilage Ande til dykkar feder ved profeten Jesaja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'då han sagde: «Gakk til dette folket og seg: «De skal høyra og høyra og ikkje skyna, og sjå og sjå og ikkje skilja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'for hjarta i dette folket hev vorte hardt, og dei er tunghøyrde på øyro, og dei let att augo sine, so dei ikkje skal sjå med augo og høyra med øyro og skyna med hjarta og venda um, so eg kunde få lækja deim.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'So vere det då kunnigt for dykk, at denne Guds frelsa er send til heidningarne; hjå deim skal ho og finna øyra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Og då han hadde sagt dette, gjekk jødarne burt og hadde eit kvast ordskifte seg imillom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Han vart då verande heile tvo år i det herbyrget som han hadde leigt seg, og tok imot alle som kom til honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'og han forkynte Guds rike og lærde um Herren Jesus med alt frimod og utan hinder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulus, Jesu Kristi tenar, kalla til apostel, utkåra til å forkynna Guds evangelium,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'som han lova fyreåt gjenom profetarne sine i heilage skrifter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'um Son hans, som etter kjøtet er komen av Davids ætt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'som etter heilagdoms ånd er sannsynt å vera Guds velduge Son ved uppstoda frå dei daude, Jesus Kristus, vår Herre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'som me fekk nåde ved og apostel-embætte til å verka lydnad i tru millom alle heidningfolki for hans namn skuld');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, '- millom deim er de og kalla til Jesus Kristus -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'til alle deim i Rom som Gud elskar, de kalla, heilage: Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Fyrst takkar eg min Gud ved Jesus Kristus for dykk alle, av di trui dykkar er namngjeti i heile verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'For Gud som eg tener i mi ånd i hans Sons evangelium, han er mitt vitne um kor uavlatande eg kjem dykk i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'I bønerne mine bed eg alltid um at eg då endeleg eingong med Guds vilje kunde få lukka til å koma til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'For eg stundar etter å sjå dykk, so eg kunde få gjeva dykk av eikor åndeleg nådegåva med meg til dykkar styrkjing,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'det vil segja at eg hjå dykk kunde hyggjast saman med dykk ved vår sams tru, dykkar og mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Og eg vil ikkje, brør, at de skal vera uvitande um at eg ofte hev etla meg til å koma til dykk - men eg vart hindra alt til no - so eg kunde hava eikor frukt hjå dykk og, liksom hjå hine heidningfolki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Eg stend i skuld både til grækarar og barbarar, både til vise og uvise.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Soleis er eg på mi sida viljug til å preika evangeliet for dykk og som er i Rom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'For eg skjemmest ikkje ved evangeliet, for det er ei Guds kraft til frelsa for kvar den som trur, både for jøde fyrst og so for grækar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'For i det vert Guds rettferd openberra av tru til tru, som skrive stend: «Den rettferdige, av tru skal han liva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'For Guds vreide vert openberra frå himmelen yver all gudløysa og urettferdi hjå folk som held att sanningi i urettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'For det som ein kann vita um Gud, ligg i dagen for deim, for Gud hev openberra deim det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'For hans usynlege grunnhått, både hans ævelege kraft og guddom, er synleg sidan han skapte verdi, då ein kann skyna honom av gjerningarne - so folk skal vera utan orsaking');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'når dei, endå dei kjende Gud, like vel ikkje æra eller takka honom som Gud, men vart fåfengde i tankarne sine, og deira uvituge hjarta myrktest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Medan dei briska seg med at dei var vise, vart dei dårar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'og dei bytte den uforgjengelege Guds herlegdom burt for eit bilæte som likjest eit forgjengelegt menneskje og fuglar og firføtte dyr og krjupdyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Difor gav Gud deim yver i deira hjartans lyster til ureinskap, so dei skjemde sine likamar seg imillom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'dei som bytte burt Guds sanning for lygn, og æra og dyrka skapningen framfor skaparen, han som er velsigna i all æva. Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Difor gav Gud deim yver til skamlege lyster, for både kvinnorne deira forvende det naturlege bruket til det unaturlige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'og like eins gjekk mennerne og burt frå det naturlege bruket av kvinna og kveiktest upp i lyst til kvarandre, so menner dreiv skjemdarverk med menner, og fekk på seg sjølve det vederlag for si villferd som rett var.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Og liksom dei ikkje brydde seg um å eiga Gud i kunnskap, so gav Gud deim yver til ein hug som inkje duger, so dei gjorde det usømelege:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'fulle av all urettferd, vanart, vinnesykja, vondskap, fulle av ovund, mord, trætta, svik, fulkynde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'øyretutarar, baktalarar, gudhata, valdsmenner, stormodige, storordige, uppfinnsame på vondt, ulyduge mot foreldre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'uvituge, usætande, ukjærlege, miskunnlause;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'slike som vel kjenner Guds dom, at dei som gjer slikt, er verde dauden, og endå ikkje berre gjer det, men og gjev deim medhald som gjer det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Difor er du, menneskje, ikkje orsakande, kven du so er som dømer. For med di du dømer den andre, fordømer du deg sjølv, for du som dømer, gjer sjølv det same;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'men me veit at Guds dom, som sanning krev, er yver deim som gjer slikt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Men trur du det, du menneskje som dømer deim som gjer slikt og sjølv gjer det same, at du skal sleppa undan Guds dom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Eller vanvyrder du hans rikdom på godleik og tolmod og langmod, og veit ikkje at Guds godleik driv deg til umvending?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Men med ditt hardlynde og ditt utbotferdige hjarta hopar du vreide yver deg på vreidens dag då Guds rettferdige dom vert openberr;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'for han skal gjeva kvar etter gjerningarne hans:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'deim som med trott i god gjerning søkjer herlegdom og æra og uforgjengelegdom, skal han gjeva ævelegt liv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'men deim som er stridsame og ikkje lyder sanningi, men lyder urettferdi, skal timast vreide og harm.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Naud og trengsla skal koma yver kvar menneskjesjæl som gjer det vonde, både jøde fyrst og so grækar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Men herlegdom og æra og fred skal timast kvar den som gjer det gode, både jøde fyrst og so grækar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'For Gud gjer ikkje skil på folk:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Alle som synda utan lovi, dei skal og verta fortapte utan lovi, og alle som synda under lovi, dei skal og verta dømde ved lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'For ikkje dei som høyrer lovi, er rettferdige for Gud, men dei som gjer etter lovi, skal verta rettferdiggjorde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'For når heidningarne som ikkje hev lovi, gjer av naturi det som lovi byd, so er dei seg sjølve ei lov, endå dei ikkje hev lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Dei syner at lovgjerningi er skrivi i hjarto deira, med de samvitet deira gjev sitt vitnemål, og tankarne seg imillom sakar eller orsakar deim');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, '- på den dagen då Gud skal døma det dulde hjå menneski, etter mitt evangelium ved Jesu Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Men um du heiter jøde og lit på lovi og rosar deg av Gud');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'og veit hans vilje og dømer um dei ymse ting med di du lærer av lovi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'og trøyster deg til å vera vegvisar for blinde, ljos for deim som er i myrker,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'uppsedar for dårar, lærar for umynduge, då du hev den rette form for kunnskap og sanning i lovi:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Du som soleis lærer ein annan, lærer du ikkje deg sjølv? Du som preikar at ein ikkje skal stela, stel du?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Du som segjer at ein ikkje skal driva hor, driv du hor? Du som styggjest ved avgudar, ranar du avgudstempel?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Du som rosar deg av lovi, du vanærar Gud med di du bryt lovi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'For «Guds namn vert spotta millom heidningarne for dykkar skuld,» som skrive stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'For umskjeringi gjer vel gagn um du held lovi; men bryt du lovi, då hev di umskjering vorte til fyrehud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Um då ein u-umskoren liver etter lovbodi, skal ikkje då hans fyrehud verta rekna for umskjering?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Og den som hev den naturlege fyrehud, men uppfyller lovi, skal døma deg som med bokstav og umskjering bryt lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'For ikkje den er jøde som er det i synom, og ikkje heller er det umskjering som er det i synom, på kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Men den som er jøde i løyndom, han er jøde, og umskjering er hjarteumskjering i ånd, ikkje i bokstav. Ein slik hev ros, ikkje av menneskje, men av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Kva fyremun hev so jøden? eller kva gagn er det i umskjeringi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Mykje i alle måtar! fyrst og fremst det at Guds ord vart gjeve deim til i vareign.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'For korleis er det? um sume var utrue, skulde då deira utruskap gjera Guds truskap til inkjes?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nei, langt ifrå! Lat det standa fast at Gud er sannordig, men kvart menneskje ein ljugar, som skrive stend: «At du må finnast rettferdig i dine ord, og vinna når du fører di sak.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Men um vår urettferd syner Guds rettferd, kva skal me då segja? Er vel Gud urettferdig når han fører vreiden sin yver oss? Eg talar på menneskjevis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nei, langt ifrå! Korleis kunde då Gud døma verdi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Ja, men um no Guds sannleik ved mi lygn synte seg ovstor til hans æra, kvi vert då eg endå dømd som ein syndar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Og skal me ikkje då - som me vert spotta for, og som sume segjer at me lærer - gjera det vonde, so det gode kann koma utav det? Rettferdig er den domen som slike fær yver seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Kva då? Hev me nokon fyremun? Nei, slett ikkje; for me hev fyrr klaga både jødar og grækarar for at dei er under synd alle saman,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'so som skrive stend: «Det finst ingen rettferdig, ikkje ein heller;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'det finst ikkje den som er vitug, det finst ikkje den som søkjer Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Alle er avvikne, dei er udugande vortne alle saman; det finst ikkje nokon som gjer godt, det finst ikkje ein einaste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Ei opna grav er strupen deira, med tungorne sine gjorde dei svik, orme-eiter er under lipporne deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Deira munn er full av bannskap og beiska.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Deira føter er snare til å spilla blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Øyding og usæla hev deira vegar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'og freds veg kjenner dei ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Ingen age for Gud dei heve for augo.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Men me veit at alt det som lovi segjer, det talar ho til deim som hev lovi, so kvar munn skal tagna og all verdi verta saka for Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'sidan inkje kjøt kann verta rettferdiggjort for honom med lovgjerningar; for ved lovi kjem ein til å kjenna synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Men no er Guds rettferd, som lovi og profetarne vitnar um, openberra utan lovi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'det vil segja Guds rettferd ved tru på Jesus Kristus for alle og yver alle som trur. For det finst inkje skil;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'alle hev synda og vantar æra for Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'med di dei vert rettferdiggjorde ufortent av hans nåde ved utløysingi i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Honom synte Gud fram i blodet hans, som ein nådestol ved trui, til å visa si rettferd, av di han i sitt langmod hadde havt tol med dei synder som fyrr var gjorde -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'til å visa si rettferd i den tid som no er, so han kunde vera rettferdig og gjera den rettferdig som hev trui på Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kvar er so vår ros? Ho er utestengd. Kva lov er det ved? Gjerningslovi? Nei, ved tru-lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'For me held fyre at menneskja vert rettferdiggjord ved tru utan lovgjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Eller er Gud berre Gud for jødar? Er han ikkje Gud for heidningar og? Jau, for heidningar og,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'so sant Gud er ein, og han rettferdiggjer dei umskorne av tru, og dei u-umskorne ved tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Gjer me då lovi um inkje med trui? Nei, langt ifrå; me stadfester lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Kva skal me då segja at Abraham, far vår, hev vunne etter kjøtet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'For vart Abraham rettferdiggjord av gjerningar, so hev han noko å rosa seg av. Men det hev han ikkje for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'For kva segjer Skrifti? «Abraham trudde Gud, og det vart rekna honom til rettferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Men den som held seg til gjerningar, honom vert løni ikkje tilrekna av nåde, men etter skyldnad;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'men den som ikkje held seg til gjerningar, men trur på han som gjer den ugudlege rettferdig, honom vert trui hans rekna til rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Soleis prisar og David det menneskjet sælt som Gud tilreknar rettferd utan gjerningar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '«Sæle er dei som hev misgjerderne sine forlatne og synderne sine yverbreidde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Sæl er den mann som Herren ikkje tilreknar synd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Gjeld no denne sælkingi dei umskorne, eller dei u-umskorne og? For me segjer at trui vart rekna Abraham til rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Korleis vart ho då tilrekna honom? då han var umskoren, eller då han hadde fyrehud? Ikkje då han var umskoren, men då han hadde fyrehud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'og han fekk umskjeringsteiknet til innsigle på rettferdi ved den trui som han hadde då han var u-umskoren, av di han skulde vera far til alle dei u-umskorne som trur, so rettferdi kunde verta tilrekna deim og,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'og far til dei umskorne, dei som ikkje berre hev umskjering, men og gjeng i fotfaret av den trui som Abraham, far vår, hadde då han var u-umskoren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'For ikkje ved lovi fekk Abraham eller ætti hans den lovnaden at han skulde vera erving til verdi, men ved tru-rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'For er dei som held seg til lovi ervingar, so hev trui vorte gagnlaus og lovnaden til inkjes;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'for lovi verkar vreide, men der det ingi lov er, der er ikkje heller lovbrot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Difor fekk han lovnaden ved trui, so det kunde vera som ein nåde, so lovnaden kunde standa fast for all ætti, ikkje berre for den som hev lovi, men og for den som hev Abrahams tru; han som er far til oss alle -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'som skrive stend: «Til fader åt mange folk hev eg sett deg» - for Guds åsyn som han trudde på, han som gjer dei daude livande og kallar det som ikkje er til, som um det vore til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Mot von trudde han med von, so han skulde verta far til mange folk, etter det som sagt var: «So skal ætti di verta.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Og utan veikskap i trui såg han på sin eigen likam, som var utlivd, han var nære på hundrad år, og på det utdøydde morslivet hennar Sara;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'men på Guds lovnad tvila han ikkje med vantru, men vart sterk i trui, med di han gav Gud æra');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'og var fullviss på at det han hadde lova, var han og megtig til å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Difor vart det og rekna honom til rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Men ikkje berre for hans skuld er det skrive at det vart honom tilrekna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'men og for vår skuld som det skal verta tilrekna, me som trur på honom som vekte upp Jesus, vår Herre, frå dei daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'han som vart gjeven for våre brot og uppvekt til vår rettferdiggjering.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Etter di me no er rettferdiggjorde av trui, hev me fred med Gud ved vår Herre Jesus Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'som me ved trui og hev fenge tilgjenge ved til denne nåden som me stend i, og me rosar oss av von um Guds herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Ja, ikkje berre det, men me rosar oss og av trengslorne våre, med di me veit at trengsla verkar tolmod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'og tolmodet verkar røynsla, og røynsla verkar von,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'og voni gjer ikkje til skammar, av di Guds kjærleik er utrend i hjarto våre ved den Heilage Ande som er oss gjeven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'For medan me endå var veike, døydde Kristus til fastsett tid for ugudlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'For det vil vandt nokon døy for ein rettferdig - for ein som er god kunde kanskje einkvan taka på seg å døy -;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'men Gud syner sin kjærleik til oss med di at Kristus døydde for oss medan me endå var syndarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'So mykje heller skal me då, no me er rettferdiggjorde ved hans blod, verta frelste ved honom frå vreiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'For so sant me vart forlikte med Gud ved hans sons daude då me var fiendar, so skal me so mykje heller verta frelste ved hans liv no då me er forlikte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Ja, ikkje berre det, men me rosar oss og av Gud ved vår Herre Jesus Kristus, som me no hev fenge forlik ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Difor, liksom syndi kom inn i verdi ved eitt menneskje og dauden ved syndi, og dauden soleis trengde igjenom til alle menneskje av di dei synda alle -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'For vel var det synd i verdi fyre lovi, men syndi vert ikkje tilrekna der det ingi lov er;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'men endå rådde dauden frå Adam til Moses ogso yver deim som ikkje hadde synda i likning med Adams brot, han som er eit fyrebilæte på den som skulde koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Men ikkje er det med nådegåva soleis som med fallet; for hev dei mange døytt med di at den eine fall, so hev mykje meir Guds nåde og gåva vorte ovrik for dei mange i det eine menneskje Jesu Kristi nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Og ikkje er det med gåva soleis som det vart då ein synda; for domen vart til fordøming for ein skuld, men nådegåva vart til fridøming for mange fall skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'For dersom dauden kom til å råda på grunn av den eine manns fall, so skal mykje meir dei som fær den ovrike nåde og rettferds-gåva, liva og råda ved den eine, Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Difor, liksom ein manns fall vart til fordøming for alle menneskje, so vart og ein manns rettferdige gjerning til livsens rettferdiggjering for alle menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'For liksom dei mange vart syndarar ved ulydnaden åt det eine menneskjet, so skal og dei mange verta rettferdige ved lydnaden åt den eine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Men lovi kom attåt, so fallet skulde verta stort; men der syndi vart stor, vart nåden endå større,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'so liksom syndi rådde ved dauden, skulde nåden og råda ved rettferd til ævelegt liv ved Jesus Kristus, vår Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Kva skal me då segja? Skal me halda fram i syndi, so nåden kann verta dess større?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nei, langt ifrå! Me som er avdøyde frå syndi, kor skulde me endå liva i henne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Eller veit de ikkje at alle me som vart døypte til Kristus Jesus, me vart døypte til hans daude?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Me vart soleis gravlagde med honom ved dåpen til hans daude, for liksom Kristus vart uppvekt frå dei daude ved Faderens herlegdom, so skal me og ferdast i ein ny livnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'For hev me vorte sameina med honom i likskapen med dauden hans, so skal me og verta det i likskapen med uppstoda hans,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'då me veit dette, at vårt gamle menneskje vart krossfest med honom av so synd-likamen skulde verta til inkjes, so me ikkje lenger skal tena syndi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'for den som er daud, han er rettferdiggjort frå syndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Men døydde me med Kristus, so trur me at me og skal liva med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'av di me veit at Kristus ikkje døyr meir sidan han er uppvekt frå dei daude; dauden hev ikkje lenger vald yver honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'For dauden sin, den døydde han ein gong for syndi, men livet sitt, det liver han for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Soleis skal de og rekna dykk daude for syndi, men livande for Gud i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Lat difor ikkje syndi råda i dykkar døyelege likam, so de lyder lysterne hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Og bjod ikkje heller fram lemerne dykkar åt syndi til våpn for urettferd, men bjod dykk sjølve fram åt Gud som upplivna frå daude, og lemerne dykkar åt Gud til våpn for rettferd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'For syndi skal ikkje råda yver dykk; de er ikkje under lovi, men under nåden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Kva då? Skal me synda, sidan me ikkje er under lovi, men under nåden? Nei, langt ifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Veit de ikkje at når de byd dykk fram åt einkvan til tenarar so de lyder, so er de tenarar under den som de lyder, anten det so er under syndi til daude eller under lydnaden til rettferd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Men Gud vere takk, at de vel hev vore tenarar under syndi, men no av hjarta hev vorte lyduge mot den lærdomsform som de er yvergjeven til!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Men sidan de er frigjorde frå syndi, hev de vorte tenarar for rettferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Eg talar på menneskjevis for dykkar kjøts vesaldom. For liksom de baud lemerne dykkar fram til tenarar for ureinskapen og urettferdi til urettferd, so bjod no fram lemerne dykkar til tenarar for rettferdi til helging.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'For då de var tenarar for syndi, var de frie frå rettferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Kva frukt hadde de so den tid? Slikt som de no skjemmest ved. For endelykti på deim er dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Men no då de er frigjorde frå syndi og hev vorte Guds tenarar, hev de dykkar frukt til helging, og endelykti er ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'For den løn som syndi gjev, er dauden, men Guds nådegåva er ævelegt liv i Kristus Jesus, vår Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Eller veit de ikkje, brør - for eg talar til slike som kjenner lovi - at lovi råder yver menneskjet so lenge det liver?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'For den gifte kvinna er med lovi bundi til mannen sin so lenge han liver; men døyr mannen, er ho løyst frå lovi um mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Difor skal ho kallast horkona, um ho gifter seg med ein annan mann medan mannen hennar liver; men døyr mannen, so er ho fri frå lovi, so ho ikkje vert horkona um ho vert gift med ein annan mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Soleis, mine brør, døydde de og frå lovi ved Kristi likam, av di de skulde høyra til ein annan, det er han som er uppstaden frå dei daude, so me kann bera frukt for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'For då me var i kjøtet, verka dei syndige lysterne, som vart vekte ved lovi, soleis i lemerne våre, at me bar frukt for dauden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'men no er me løyste frå lovi, med di me hev døytt frå det som me var fangar under, so me tener i Andens nye art og ikkje i bokstavens gamle art.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Kva skal me då segja? Er lovi synd? Nei, langt ifrå! men eg kjende ikkje syndi utan gjenom lovi; for eg kjende ikkje lysti, um ikkje lovi hadde sagt: «Du skal ikkje lysta!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Men syndi tok tilføre av bodet og verka allslags lyst i meg; for utan lov er syndi daud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Eg livde ei tid utan lov; men då bodet kom, livna syndi upp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'men eg døydde; og bodet som var til liv, vart funne å vera meg til daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'for syndi tok tilføre av bodet og dåra og drap meg ved det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'So er då lovi heilag, og bodet heilagt og rettferdigt og godt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Hev då det som er godt vorte meg til daude? Nei, langt ifrå! men det var syndi, at ho skulde visa seg å vera synd, med di ho volde meg dauden med det som er godt - so syndi skulde verta storleg syndig ved bodet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'For me veit at lovi er åndeleg, men eg er kjøtleg, seld under syndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Det eg gjer, det skynar eg ikkje; for eg gjer ikkje det som eg vil, men det som eg hatar, det gjer eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Men gjer eg det som eg ikkje vil, so vitnar eg med lovi at ho er god.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Men no er det ikkje lenger eg som gjer det, men syndi som bur i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'For eg veit, at i meg, det vil segja i kjøtet mitt, bur inkje godt; for viljen hev eg, men gjera det gode vinn eg ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'For eg gjer ikkje det gode som eg vil, men det vonde som eg ikkje vil, det gjer eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Men gjer eg det som eg ikkje vil, so er det ikkje lenger eg som gjer det, men syndi som bur i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'So finn eg då den lov for meg, eg som vil gjera det gode, at det vonde ligg meg for handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'For eg hev hug til Guds lov etter mitt indre menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'men eg ser ei onnor lov i lemerne mine, som strider imot lovi i hugen min, og fangar meg under syndelovi som er i lemerne mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Eg arme menneskje! kven skal frelsa meg frå denne daudens likam?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Gud vere takk ved Jesus Kristus, vår Herre! - So tener då eg i meg sjølv Guds lov med hugen, men syndelovi med kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'So er det då ingi fordøming for deim som er i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'For i Kristus Jesus hev livsens ånds-lov gjort meg fri frå synde- og daude-lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'For det som var umogelegt for lovi, av di ho var magtlaus ved kjøtet, det gjorde Gud, då han sende sin eigen son i syndigt kjøts likning og for syndi skuld og fordømde syndi i kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'So skulde lovkravet verta fullnøgt i oss som ikkje ferdast etter kjøtet, men etter Anden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'For dei som er etter kjøtet, trår etter det som høyrer kjøtet til, men dei som er etter Anden, trår etter det som høyrer Anden til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'For kjøtsens trå er daude, men Andens trå er liv og fred,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'etter di kjøtsens trå er fiendskap mot Gud - for det er ikkje Guds lov lydugt, ja, kann ikkje vera det heller -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'og dei som er i kjøtet, kann ikkje tekkjast Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Men de er ikkje i kjøtet, men i Anden, so framt Guds Ande bur i dykk; men hev ein ikkje hev Kristi Ande, so høyrer han ikkje honom til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Men er Kristus i dykk, so er vel likamen daud for synd skuld, men åndi er liv for rettferd skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Men dersom Anden hans som vekte Jesus upp frå dei daude, bur i dykk, so skal han som vekte Kristus upp frå dei daude, ogso gjera dykkar døyelege likamar livande for sin Ande skuld, som bur i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'So stend me då, brør, ikkje i skuld til kjøtet, so me skulde liva etter kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'For liver de etter kjøtet, skal de døy; men døyder de likamens gjerningar ved Anden, då skal de liva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'For so mange som vert drivne av Guds Ande, dei er Guds born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'For de fekk ikkje ein trældoms-ande, so de atter skulde ræddast, men de fekk ei barnekårs-ande, som gjer at me ropar: «Abba, Fader!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Anden sjølv vitnar med vår ånd at me er Guds born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Men er me born, so er me ervingar og, det er Guds ervingar, og Kristi medervingar, so framt me lid med honom, for at me skal verta herleggjorde med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'For eg held so fyre, at lidingarne i den nærverande tidi er ikkje vyrdande mot den herlegdomen som skal openberrast på oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'For skapningen lengtar og stundar etter Guds borns openberring;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'for skapningen vart lagd under vesaldomen - ikkje godviljugt, men etter hans vilje som lagde honom derunder -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'i von um at skapningen og skal verta frigjord frå trældomen under forgjengelegdom til fridomen i Guds borns herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'For me veit at all skapningen sukkar saman og lid sår verk saman alt til no;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'ja, ikkje berre det, men me og, som hev Anden til fyrstegrøda, jamvel me sukkar med oss sjølve, med di me stundar etter barnekåret, vår likams utløysing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'For i voni er me frelste; men ei von som ein ser, er ingi von; kvifor skulde ein vona det ein ser?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Men vonar me det me ikkje ser, so stundar me etter det med tolmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Men like eins kjem Anden og vår vanmagt til hjelp; for me veit ikkje kva me skal beda um, so som me treng det, men Anden sjølv gjeng i bøn for oss med usegjelege sukkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'og han som ransakar hjarto, veit kva Anden trår etter; for etter Guds vilje gjeng han i bøn for dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Og me veit at alle ting tener deim til gode som elskar Gud, dei som er kalla etter hans rådgjerd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'For dei som han kjende fyreåt, dei hev han og kåra fyreåt til å likjast bilætet av Son hans, so han skulde vera den fyrstefødde millom mange brør;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'og dei som han kåra fyreåt, deim hev han og kalla, og dei som han kalla, deim hev han og rettferdiggjort, og dei som han rettferdiggjorde, deim hev han og herleggjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Kva skal me då segja um dette? Er Gud med oss, kven er då imot oss?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Han som ikkje sparde sin eigen son, men gav honom for oss alle, kor skulde han ikkje og gjeva oss alle ting med honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kven vil klaga Guds utvalde? Gud er den som rettferdiggjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kven er den som fordømer? Kristus er den som hev døytt, ja, endå meir, som er uppvekt, som og er ved Guds høgre hand, som og gjeng i bøn for oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kven skal skilja oss frå Kristi kjærleik? Trengsla eller hugverk eller forfylgjing eller hunger eller klædeløysa eller fåre eller sverd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'som skrive stend: «For di skuld vert me drepne all dagen; me er rekna som slagtesauer.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Men i alt dette vinn me meir enn siger ved honom som elska oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'For eg er viss på at korkje daude eller liv, korkje englar eller herrar, korkje det som no er eller det som koma skal eller nokor magt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'korkje høgd eller dypt eller noko annan skapning skal kunna skilja oss frå Guds kjærleik i Kristus Jesus, vår Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Eg segjer sanning i Kristus, eg lyg ikkje, samvitet mitt vitnar med meg i den Heilage Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'at eg hev ei stor sorg og en stendig verk i hjarta mitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'For eg skulde ynskja at eg sjølv var bannstøytt burt frå Kristus for brørne mine, samættingarne mine etter kjøtet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'dei som er israelitar, som hev barnekåret og herlegdomen og pakterne og lovgjevingi og gudstenesta og lovnaderne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'dei som federne høyrer til og som Kristus er ætta frå etter kjøtet, han som er Gud yver alle ting, velsigna i all æva. Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Men det er ikkje so at Guds ord hev vorte til inkjes; for ikkje alle dei som er ætta frå Israel, er Israel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'og ikkje heller er alle Abrahams born for di um dei er hans ætt; men: «Etter Isak som skal ætta di heita,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'det vil segja: ikkje borni etter kjøtet er Guds born, men borni etter lovnaden vert rekna til ætti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'For dette er eit lovnadsord: «Ved dette bilet kjem eg att, og då skal Sara hava ein son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Og ikkje berre det, men so var det og med Rebekka, ho som var med born ved ein, det er Isak, far vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'For då dei endå var ufødde, og ikkje endå hadde gjort korkje godt eller vondt - for at Guds rådgjerd etter hans utveljing skulde standa ved lag, ikkje ved gjerningar, men ved honom som kallar -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'då vart det sagt til henne: «Den eldste skal tena den yngste,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'som skrive stend: «Jakob elska eg, men Esau hata eg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Kva skal me då segja? Skulde det finnast urettferd hjå Gud? Langt ifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'For han segjer til Moses: «Eg vil miskunna den som eg miskunnar, og ynka den som eg ynkar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'So stend det då ikkje til den som vil, og ikkje heller til den som renner, men til Gud som gjer miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'For Skrifti segjer til Farao: «Just til dette reiste eg deg upp, at eg kunde syna magti mi på deg, og at namnet mitt kunde verta kunngjort yver all jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'So miskunnar han då kven han vil, og gjer kven han vil hard.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'So vil du vel segja til meg: «Kva hev han so endå å klaga for? For kven stend vel imot viljen hans?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Men kven er då du, menneskje, som trættar imot Gud? Skal då verket segja til verkaren: «Kvi gjorde du meg so?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Eller hev ikkje krusmakaren vald yver leiret, so han av same deigi kann gjera det eine kjerald til æra og det andre til vanæra?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Men um no Gud, endå han vilde syna vreiden sin og kunngjera si magt, like vel med stort langmod tolde dei vreide-kjerald som var laga til undergang,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'so han og kunde gjera sin herlegdoms rikdom yver miskunnskjeraldi som han fyreåt hadde laga til herlegdom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Og til slike kalla han oss og, ikkje berre av jødar, men og av heidningar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'som han og segjer hjå Hosea: «Det som ei er mitt folk, vil eg kalla mitt folk, og kalla henne elska som ei var elska;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'og det skal ganga so, at på den staden det vart sagt til deim: «De er ikkje mitt folk,» der skal dei kallast den livande Guds born.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Og som Jesaja ropar ut yver Israel: «Um talet på Israels born er som havsens sand, so skal då berre leivningen frelsast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'For ordet sitt skal Herren setja i verk og snøgt fullføra på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Og som Jesaja fyrr hev sagt: «Hadde ikkje Herren Sebaot leivt oss eit sæde, so hadde me vorte som Sodoma og vorte like Gomorra.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Kva skal me då segja? At heidningarne som ikkje søkte rettferd, dei vann rettferd, men det var rettferdi av tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Men Israel, som søkte rettferdslov, dei vann ikkje fram til denne lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Kvifor so? For di dei ikkje søkte henne med tru, men med gjerningar, for dei støytte seg på støytesteinen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'som skrive stend: «Sjå, eg legg i Sion ein stein til støyt og eit berg til stygg; den som trur på honom, skal ikkje verta til skammar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Brør! mitt hjartans ynskje og mi bøn til Gud for deim er at dei må verta frelste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'For eg gjev deim det vitnemålet at dei hev ihuge for Gud, men ikkje med skynsemd;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'for då dei ikkje kjende Guds rettferd, men stræva etter å grunna si eigi rettferd, so gav dei seg ikkje inn under Guds rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'For Kristus er enden på lovi til rettferd for kvar den som trur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'For Moses skriv um den rettferd som er av lovi: «Det menneskjet som gjer desse ting, skal liva ved deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Men den rettferdi som er av tru, segjer so: «Seg ikkje i ditt hjarta: «Kven skal fara upp til himmelen» - det vil segja til å henta Kristus ned -?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'eller: «Kven skal fara ned i avgrunnen» - det vil segja til å henta Kristus upp frå dei daude -?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Men kva segjer ho? «Ordet er deg nær i munnen din og i hjarta ditt;» det er ordet um tru, det som me forkynner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'for dersom du sannar med munnen din at Jesus er herre, og trur du i hjarta ditt at Gud vekte honom upp frå dei daude, so skal du verta frelst;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'for med hjarta trur ein til rettferd, og med munnen sannar ein til frelsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'For Skrifti segjer: «Kvar den som trur på honom, skal ikkje verta til skammar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'For det er inkje skil på jøde og grækar; alle hev dei same Herre, som er rik nok for alle som kallar på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'For kvar den som kallar på Herrens namn, skal verta frelst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Korleis skal dei då kalla på den som dei ikkje trur på? og korleis skal dei tru der dei ikkje hev høyrt? og korleis skal dei høyra utan det er nokon som forkynner?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Og korleis skal dei forkynna utan dei vert utsende? som skrive stend: «Kor fagre føterne deira er, som forkynner fred, som ber godt bod!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Men ikkje alle lydde fagnadbodet. For Jesaja segjer: «Herre, kven trudde det bodet me høyrde?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'So kjem då trui av høyring, men høyringi ved Kristi ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Men eg segjer: Hev dei då ikkje høyrt det? Jau, til vissa; «røysti deira gjekk yver all jordi, og ordi deira til heimsens endar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Men eg segjer: Skyna ikkje Israel det då? Fyrst segjer Moses: «Eg vil gjera dykk åbruige på det som ikkje er eit folk, på eit uvitugt folk vil eg gjera dykk harme.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Og Jesaja vågar seg til å segja: «Eg vart funnen av deim som ikkje søkte meg; eg synte meg for deim som ikkje spurde etter meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Men um Israel segjer han: «All dagen rette eg ut henderne mine til eit ulydugt og motstridigt folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Difor segjer eg: Hev då Gud støytt frå seg folket sitt? Nei, langt ifrå; for eg er og ein israelit, av Abrahams ætt, av Benjamins ættgrein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Gud hev ikkje støytt frå seg folket sitt som han kjende fyreåt. Eller veit de ikkje kva Skrifti segjer der ho talar um Elia, korleis han stig fram for Gud imot Israel og segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '«Herre! Profetarne dine drap dei, altari dine reiv dei ned, og eg vart åleine att, og dei stend meg etter livet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Men kva segjer Guds svar til honom? «Eg leivde meg sju tusund mann som ikkje bøygde kne for Ba’al.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Soleis hev det då og i denne tid vorte att ein leivning etter nådens utveljing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Men er det av nåde, so er det ikkje lenger av gjerningar, elles vert nåden ikkje nåde lenger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Kva so? Det som Israel trår etter, det hev det ikkje nått, men dei utvalde hev nått det, dei hine hev vorte forherde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'som skrive stend: «Gud gav deim ei dauvskapsånd, augo til å ikkje sjå og øyro til å ikkje høyra, alt til den dag i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Og David segjer: «Lat bordet deira verta deim ei snara og ei gildra ei fella og ei attergjeld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Lat augo deira dimmast, so dei ikkje ser, og bøyg alltid ryggen deira!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Difor segjer eg: Hev dei då snåva for di at dei skulde falla? Nei, langt ifrå! men ved deira fall er frelsa komi til heidningarne, so det skal vekkja deim til kapphug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Men er deira fall ein rikdom for verdi, og deira skade ein rikdom for heidningar, kor mykje meir då deira fullending!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'For til dykk talar eg, de heidningar. So sant som eg er heidningapostel, ærar eg embættet mitt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'um eg då kunde vekkja samættingarne mine til kapphug og få frelst nokre av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'For hev verdi vorte forlikt med Gud med då dei var burtkasta, kva anna vert det då enn liv av daude, når dei vert mottekne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Men er fyrstegrøda heilag, so er deigi det og, og er roti heilag, so er greinerne det og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Um no like vel sume av greinerne vart avbrotne, og du, som var ein vill oljekvist, vart innpota imillom deim og vart samhavande med deim i roti og feita på oljetreet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'so rosa deg ikkje imot greinerne! men um du rosar deg, so er det då ikkje du som ber roti, men roti som ber deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'So vil du vel segja: «Greinerne vart avbrotne for di at eg skulde verta innpota.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Ja vel! ved si vantru vart dei avbrotne, men du stend ved trui; ovmodast ikkje, men ottast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'For sparde ikkje Gud dei naturlege greinerne, so vil han ikkje spara deg heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Sjå då Guds godleik og strengleik: Strengleik imot deim som er falne, men godleik imot deg, so framt du held deg til godleiken, elles skal du og verta avhoggen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Men hine skal og verta innpota, dersom dei ikkje held fram i vantrui; for Gud er megtig til å pota deim inn att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'For dersom du vart avhoggen av det oljetreet som er vilt av naturi, og imot naturi innpota i eit godt oljetre, kor mykje heller skal dei då verta innpota i sitt eige oljetre, dei som av naturi høyrer til der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'For eg vil ikkje, brør, at de skal vera uvitande um denne løyndomen - so de ikkje skal tykkjast dykk sjølve kloke - at forherding til deils er komi yver Israel, til dess at fullnaden av heidningarne er komen inn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'og so skal heile Israel verta frelst, som skrive stend: «Frå Sion skal frelsaren koma, rydja gudløysa burt frå Jakob,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'og når eg tek burt deira synder, er dette mi pakti med deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Etter evangeliet er dei fiendar for dykkar skuld, men etter utveljingi er dei elska for federne skuld;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'for Gud tregar ikkje på nådegåvorne sine og kallet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'For liksom de fyrr var ulyduge mot Gud, men no hev fenge miskunn ved deira ulydnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'so hev dei og no vore ulyduge for at dei og skal få miskunn med den miskunn som de hev fenge;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'for Gud hev gjeve deim alle yver til ulydnad, so han skulde kunna miskunna deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Å, for djup av rikdom og visdom hjå Gud! Kor uransakelege domarne hans er, og kor urekkjande vegarne hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'For kven kjende Herrens hug? eller kven var rådgjevaren hans?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Eller kven gav honom noko fyreåt, so han skulde få vederlag att?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'For av honom og ved honom og til honom er alle ting. Han skal hava æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'So legg eg dykk då på hjarta, brør, ved Guds miskunn, at de må bjoda fram likamarne dykkar til eit offer som er livande og heilagt og hugnadlegt for Gud - det er dykkar åndelege gudstenesta -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'og skikka dykk ikkje likt med denne verdi, men umlagast med uppatnying av hugen dykkar, so de kann prøva kva som er Guds vilje: det gode og hugnadlege og fullkomne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'For ved den nåde som eg hev fenge, segjer eg til kvar og ein millom dykk, at han ikkje skal tenkja høgre um seg enn han bør tenkja, men tenkja visleg, alt etter som Gud hev tiletla kvar sitt mål av tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'For liksom me hev mange lemer på ein likam, men ikkje alle lemerne hev den same gjerning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'soleis er me mange ein likam i Kristus, men kvar for seg er me kvarannans lemer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Og sidan me hev ulike nådegåvor alt etter den nåde som me hev fenge, so lat oss, um me hev profetgåva, bruka henne etter som me hev tru til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'eller um me hev ei tenesta, taka vare på tenesta, eller um ein er lærar, på lærdomen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'eller um ein skal påminna, på påminningi; den som etlar ut, gjere det i god tru; den som er styrar, vere det med ihuge; den som gjer miskunn, gjere det med gleda!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Lat kjærleiken utan fals; styggjest ved det vonde, haldt fast ved det gode!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Ver varmhjarta mot kvarandre i broderkjærleik; kappast um å visa kvarandre vyrdnad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Ver ikkje lunka i dykkar ihuge; ver brennande i åndi; ten Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Ver glade i voni, toluge i trengsla, trottuge i bøni!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Syn samhug med dei heilage i deira trong, legg vinn på gjestmildskap!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Velsigna deim som forfylgjer dykk; velsigna, og banna ikkje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Gled dykk med dei glade og gråt med dei gråtande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Ver samlyndte med kvarandre; trå ikkje etter det høge; men haldt dykk gjerne til det låge; ver ikkje sjølvkloke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Gjev ikkje nokon att vondt for vondt; legg vinn på det som godt er, for alle manns åsyn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'So framt det er mogelegt, so haldt de på dykkar sida fred med alle menneskje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Hemn dykk ikkje sjølve, mine kjære, men gjev vreiden umrøme! For det stend skrive: «Meg høyrer hemnen til, eg skal gjeva attgjeld, segjer Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Um då fienden din er hungrig, so gjev honom mat; er han tyrst, so gjev honom drikka! for når du gjer det, sankar du gloande kol på hovudet hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Lat ikkje det vonde vinna yver deg, men vinn du yver det vonde med det gode!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Kvar mann skal vera lydug mot dei fyresette styremagter. For det finst ikkje styremagt utan av Gud, men dei som finst, deim hev Gud skipa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'so den som set seg imot styremagti, han stend imot Guds skipnad; men den som stend imot, skal få sin dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'For dei styrande er ikkje til rædsla for den gode gjerning, men for den vonde. Vil du sleppa å ræddast styremagti? Gjer det som godt er, so skal du få ros av henne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'for ho er Guds tenar, deg til gode. Men gjer du det som vondt er, so ræddast! for ho ber ikkje sverdet for inkje; ho er Guds tenar, ein hemnar til refsing yver den som gjer det som vondt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Difor er det naudsynleg å vera lydug, ikkje berre for refsingi skuld, men og for samvitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Difor legg de og skatt, for dei er Guds tenarar, som just tek vare på dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Gjev då alle det de er deim skuldige: skatt til den som skatt skal hava, toll til den som toll skal hava, age til den som age skal hava, æra til den som æra skal hava.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Ver ingen noko skuldige, utan det å elska kvarandre! for den som elskar den andre, hev uppfyllt lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'For ordi: «Du skal ikkje gjera hor, du skal ikkje slå i hel, du skal ikkje stela, du skal ikkje lysta,» og kva anna bodord det kann vera, det samlar seg til eitt i dette: «Du skal elska næsten din som deg sjølv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Kjærleiken gjer ikkje næsten noko vondt; difor er kjærleiken uppfylling av lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Og dette lyt me gjera, sidan me kjenner tidi, at timen er komen då me skal vakna or svevnen; for frelsa er oss næmare no enn då me tok ved trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Det lid med natti, og det stundar mot dag; lat oss då leggja verki frå myrkret av, og taka våpni til ljoset på!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Lat oss ferdasta sømeleg som um dagen, ikkje i svir og drykk, ikkje i utukt og lauslivnad, ikkje i kiv og ovund,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'men iklæd dykk Herren Jesus Kristus, og hav ikkje soleis umsut for kjøtet, at det vekkjer lyster!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Tak dykk av den som er veik i trui, utan å setja dykk til doms yver tankarne hans!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Den eine hev tru til å eta alle slag, men den veike et berre urter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Den som et, vanvyrde ikkje den som ikkje et; og den som ikkje et, døme ikkje den som et! For Gud hev teke seg av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Kven er du som dømer ein framand dreng? Han stend eller fell for sin eigen herre; men han skal verta standande, for Gud hev magt til å halda honom uppe.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Den eine gjer skil på dagarne, den andre held alle dagar like; kvar vere fullviss i sin eigen hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Den som agtar på dagen, gjer det for Herren, og den som ikkje agtar på dagen, gjer det for Herren. Og den som et, gjer det for Herren, for han takkar Gud; og den som ikkje et, gjer det for Herren og takkar Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'For ingen av oss liver for seg sjølv, og ingen døyr for seg sjølv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'for um me liver, so liver me for Herren, og me døyr, so døyr me for Herren, so anten me liver eller døyr, høyrer me Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'For Kristus døydde og vart livande att, for di at han skulde vera herre både yver livande og yver daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Men du, kvi dømer du bror din? eller du, kvi vanvyrder du bror din? me skal då alle fram for Guds domstol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'For det stend skrive: «So sant eg liver, segjer Herren, for meg skal kvart kne seg bøygja, og kvar tunga skal prisa Gud.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'So skal då kvar og ein av oss gjera Gud rekneskap for seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Lat oss difor ikkje lenger døma kvarandre, men døm heller so, at de ikkje skal leggja støyt eller fella for bror dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Eg veit og er viss på det i Herren Jesus, at ingen ting er urein i seg sjølv; men dersom nokon held noko for ureint, so er det ureint for honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Fær bror din sorg for din mat skuld, so fer du ikkje lenger fram i kjærleik; før ikkje med din mat honom i fortaping som Kristus døydde for!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Lat då ikkje det gode de hev, verta til spott!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'For Guds rike er ikkje eting og drikking, men rettferd og fred og gleda i den Heilage Ande;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'for den som tener Kristus i det, han er hugnadleg for Gud og tekkjeleg for menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Lat oss difor trå etter det som tener til fred og til uppbyggjing innbyrdes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Riv ikkje ned Guds verk for mat skuld! Alt er vel reint, men det er vondt for det menneskje som et med samvitsagg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Det er godt å ikkje eta kjøt eller drikka vin eller gjera noko som bror din støyter seg på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Du hev tru; hav henne hjå deg sjølv for Gud! Sæl er den som ikkje dømer seg sjølv i det han valet han gjer;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'men den som tvilar - et han, so er han dømd, av di det ikkje er gjort av tru; alt som ikkje er av tru, det er synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Me som er sterke, me er skuldige til å bera vanstyrken hjå dei veike og ikkje vera oss sjølve til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Kvar av oss vere næsten sin til hugnad, til hans gagn, til uppbyggjing!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'For Kristus levde ikkje heller seg sjølv til hugnad, men som skrive stend: «Deira hædingar som hædde deg, dei fall på meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'For alt det som fyrr er skrive, det er skrive oss til lærdom, so me skal hava von ved det tolmodet og den trøysti som skrifterne gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Men Gud som gjev tolmod og trøyst, han gjeve at de må vera samlyndte med kvarandre etter Kristi Jesu fyredøme,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'so de samheldige, med ein munn, kann prisa Gud og vår Herre Jesu Kristi Fader!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Difor, tak dykk av kvarandre, liksom Kristus og tok seg av dykk til Guds æra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Eg meiner: Kristus hev vorte tenar for dei umskorne for Guds sannleik skuld, for å stadfesta lovnaderne til federne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'men heidningarne skal prisa Gud for miskunn, som skrive stend: «Difor vil eg prisa deg millom heidningar og lovsyngja ditt namn.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Og atter segjer Skrifti: «Fagna dykk, heidningar, saman med hans folk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Og atter: «Lova Herren, alle heidningar, og prisa honom, alle folk!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Og atter segjer Jesaja: «Koma skal Isais rotrenning, han som reiser seg til herre yver heidningar, på honom skal heidningarne vona.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Men den Gud som gjev voni, fylle dykk med all gleda og fred i trui, so de kann vera rike på von ved krafti frå den Heilage Ande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Men eg og, mine brør, hev den visse trui um dykk, at de av dykk sjølve er fulle av godleik, fyllte med all kunnskap, duglege ogso til å påminna kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Men endå hev eg sume stader skrive heller djervt til dykk, med di eg atter vilde gjeva dykk påminning etter den nåde som Gud hev gjeve meg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'at eg skal vera Jesu Kristi offerprest for heidningarne og gjera prestetenesta med evangeliet, so heidningarne kann verta eit huglegt offer, helga ved den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Difor hev eg mi ros i Kristus Jesus, i mi tenesta for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'For eg vil ikkje våga meg til å tala um anna enn det som Kristus hev verka ved meg til å føra heidningar til lydnad, med ord og gjerning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'med kraft av teikn og under, med kraft av Guds Ande, so eg fullt hev kunngjort Kristi evangelium frå Jerusalem og rundt ikring alt til Illyria,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'men då so, at eg sette mi æra i å forkynna evangeliet, ikkje der som Kristus alt var nemnd, at eg ikkje skulde byggja på framand grunnvoll,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'men, som skrive stend: «Dei som ingi kunngjering hev fenge um honom, skal sjå, og dei som ikkje hev høyrt, skal skyna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Det er mest dette som hev hindra meg frå å koma til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Men no, då eg ikkje lenger hev rom i desse landi, og i mange år hev lengta etter å koma til dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'no vonar eg å få sjå dykk på gjenomferdi, når eg fer til Spania, og få fylgjeskap av dykk dit, når eg fyrst i nokon mun hev fenge hugnad hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Men no fer eg til Jerusalem i tenesta for dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'For Makedonia og Akaia hev av si godvild gjort eit samanskot til dei fatige millom dei heilage i Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Dei hev gjort det av si godvild, dei stend og i skuld til deim; for hev heidningarne fenge av deira åndelege gode ting, so er dei og skuldige til å tena deim med dei timelege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Når eg då hev fullført dette og lagt denne frukt i deira hender, so vil eg fara derifrå gjenom dykkar by til Spania,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'og eg veit at når eg kjem til dykk, so skal eg koma med ei fylla av Kristi velsigning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Men eg legg dykk på hjarta, brør, for vår Herre Jesu Kristi og Andens kjærleik, at de må strida med meg i dykkar bøner for meg til Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'at eg må ganga fri for dei vantruande i Judæa, og mi ærend til Jerusalem må tekkjast dei heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'so eg kann koma til dykk med gleda, um Gud so vil, og kveikjast upp i samvære med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Fredsens Gud vere med dykk alle! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Eg legg eit godt ord inn for Føbe, syster vår, som er tenar for kyrkjelyden i Kenkreæ,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'at de tek imot henne i Herren, som det sømer dei heilage, og hjelper henne med alt som ho treng av dykk; for ho hev vore til hjelp for mange, ja for meg sjølv og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Helsa Priska og Akvilas, mine medarbeidarar i Kristus Jesus -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'dei hev våga sitt eige liv for meg, og ikkje berre eg takkar deim, men og alle kyrkjelydar av heidningarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'og helsa kyrkjelyden i deira hus. Helsa Epænetus, min kjære, som er fyrstegrøda av Asia for Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Helsa Maria, som hev arbeidt mykje for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Helsa Andronikus og Junias, mine skyldfolk og medfangar, dei er namngjetne millom apostlarne, og dei kom og til Kristus fyre meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Helsa Amplias, min kjære bror i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Helsa Urbanus, vår medarbeidar i Kristus, og min kjære Stakys.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Helsa Apelles, den velrøynde i Kristus. Helsa deim som høyrer til Aristobulus’ hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Helsa Herodion, skyldingen min. Helsa deim frå Narkissus’ hus, som er i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Helsa Tryfæna og Tryfosa, som hev arbeidt i Herren. Helsa Persis, den kjære, ho hev arbeidt mykje i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Helsa Rufus, den utvalde i Herren, og hans og mi mor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Helsa Asynkritus, Flegon, Hermes, Patrobas, Hermas og brørne hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Helsa Filologus og Julia, Nereus og syster hans og Olympas og alle dei heilage som er hjå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Helsa kvarandre med ein heilag kyss! Alle Kristi kyrkjelydar helsar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Men eg legg dykk på hjarta, brør, at de hev augo med deim som veld usemja og støytarne mot den læra som de hev lært, og haldt dykk ifrå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'For slike folk tener ikkje vår Herre Jesus Kristus, men sin eigen buk, og med sine fagre ord og sin smeikjande tale dårar dei hjarto på dei godtrugne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'For ordet um dykkar lydnad er kome utyver til alle; difor gled eg meg yver dykk, men eg ynskjer at de skal vera vise til det gode og reine for det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Men fredsens Gud skal brått krasa Satan under føterne dykkar! Vår Herre Jesu Kristi nåde vere med dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timoteus, min medarbeidar, og Lukius og Jason og Sosipater, skyldingarne mine, helsar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Eg, Tertius, som skriv brevet, helsar dykk i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaius helsar dykk, han som er vert for meg og heile kyrkjelyden. Erastus, rekneskapsføraren i byen, helsar dykk, og broderen Kvartus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Vår Herre Jesu Kristi nåde vere med dykk alle! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Men han som er megtig til å styrkja dykk etter mitt evangelium og Jesu Kristi forkynning, etter openberringi av den løyndomen som hev vore duld i ævelege tider,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'men no er komen til synes, og i profetiske skrifter etter den ævelege Guds fyresegn kunngjord for alle folk til å verka lydnad i tru,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'han, den eine vise Gud ved Jesus Kristus, skal hava æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulus, ved Guds vilje kalla til Kristi Jesu apostel, og broderen Sostenes');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'til Guds kyrkjelyd som er i Korint, deim som er helga i Kristus Jesus, som er kalla, heilage, med alle deim som på kvar stad påkallar vår Herre Jesu Kristi namn, både deira og vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Eg takkar alltid min Gud for dykk, for den Guds nåde som er dykk gjeven i Kristus Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'at de i honom er gjorde rike i alt, på all læra og i all kunnskap,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'liksom Kristi vitnemål er stadfest hjå dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'so at det ikkje vantar dykk på nokor nådegåva, medan de ventar på vår Herre Jesu Kristi openberring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'han som og skal stadfesta dykk til enden, so de må vera ulastande på vår Herre Jesu Kristi dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Gud er trufast, han som de vart kalla ved til samfund med hans Son Jesus Kristus, vår Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Men eg legg dykk på hjarta, brør, i vår Herre Jesu Kristi namn, at de alle må vera samtykte i dykkar tale, og at de ikkje må vera usamtykkje millom dykk, men at de må vera fullt sameina i same hugen og i same tanken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'For av huslyden hennar Kloe er det fortalt meg um dykk, mine brør, at det er kivsmål millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Det er dette eg meiner, at kvar av dykk segjer: «Eg held meg til Paulus,» «eg til Apollos,» «eg til Kefas,» «eg til Kristus.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Er Kristus sundskift? Er Paulus krossfest for dykk? Eller er det døypte til Paulus’ namn?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Eg takkar Gud, at eg ikkje hev døypt nokon av dykk utan Krispus og Gaius,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'so ikkje nokon skal segja, at de vart døypte til mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Men det er sant, eg døypte og Stefanas’ hus. Elles veit eg ikkje, at eg hev døypt nokon annan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'For Kristus sende meg ikkje ut til å døypa, men til å forkynna evangeliet, ikkje med vise ord, so Kristi kross ikkje skulde missa si kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'For ordet um krossen er vel dårskap for deim som vert fortapte, men for oss som vert frelste, er det ei Guds kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'For det stend skrive: «Eg vil tyna visdomen hjå dei vise og spilla vitet hjå dei vituge.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kvar er ein vismann? Kvar er ein skriftlærd? Kvar er ein granskar av denne verdi? Hev ikkje Gud gjort visdomen i verdi til dårskap?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'For då verdi ved sin visdom ikkje kjende Gud i Guds visdom, so fann Gud for godt ved forkynnings dårskap å frelsa deim som trur,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'etter som både jødar krev teikn, og grækarar søkjer visdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'men me forkynner Kristus krossfest, som er ei avstyggjing for jødar og ein dårskap for grækarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'men for deim som er kalla, både jødar og grækarar, forkynner me Kristus, Guds kraft og Guds visdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'For Guds dårskap er visare enn menneski, og Guds vanmagt er sterkare enn menneski.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Sjå då på dykkar kall, brør! at ikkje mange vise etter kjøtet vart kalla, ikkje mange megtige, ikkje mange høgætta;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'men det som er dårlegt i verdi, det hev Gud valt seg ut, so han kunde gjera dei vise til skammar, og det som er veikt i verdi, det hev Gud valt seg ut, so han kunde gjera det sterke til skammar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Og det som er lågt i verdi og vanvyrdt, det hev Gud valt seg ut, og det som er ingen ting, so han kunde gjera det til inkjes som er noko,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'so ikkje noko kjøt skal rosa seg for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Men av honom er de i Kristus Jesus, som for oss hev vorte visdom frå Gud og rettferd og helging og utløysing,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'so at, som det stend skrive, den som rosar seg, skal rosa seg i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Og eg, då eg kom til dykk brør, kom eg ikkje med meisterskap i ord eller i visdom og forkynte dykk Guds vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'For eg vilde ikkje vita noko imillom dykk, utan Jesus Kristus og honom krossfest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Og eg var hjå dykk med vanstyrke og med otte og med mykje hjartebiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Og mitt ord og mi forkynning var ikkje med visdoms yvertalande ord, men med framsyning av ande og kraft,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'so trui dykkar ikkje skulde vera grunna på menneskje-visdom, men på Guds kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Men me talar visdom hjå dei fullkomne, men ein visdom som ikkje høyrer denne verdi til eller herrarne i denne verdi, dei som forgjengst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Men som ein løyndom talar me Guds visdom, den dulde, som Gud frå ævelege tider hev etla til vår herlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Den ingen av herrarne i denne verdi kjende; for hadde dei kjent honom, so hadde dei ikkje krossfest herlegdoms-herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'men som skrive stend: «Det som auga ikkje såg og øyra ikkje høyrde, og som ikkje kom upp i menneskjehjarta, det som Gud etla dei som elskar honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Men for oss hev Gud openberra det ved sin Ande; for Anden ransakar alle ting, jamvel dypterne i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'For kva menneskje veit kva som bur i menneskjet, utan menneskjeåndi, som er i det? So veit heller ingen, utan Guds Ande, kva som bur i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Men me hev ikkje fenge den ande som høyrer verdi til, men den Ande som er av Gud, so me skal kjenna det som er oss gjeve av Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'det som me talar um, ikkje med ord som er lærde av menneskjeleg visdom, men med ord som er lærde av den heilage Ande, med di me tyder åndelege ting med åndelege ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Men eit naturleg menneskje tek ikkje mot det som høyrer Guds Ande til; for det er honom ein dårskap, og han kann ikkje kjenna det, for det vert dømt åndeleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Men den åndelege dømer alt, men sjølv vert han dømd av ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'For kven kjende Herrens hug, so han kunde læra honom? Men me hev Kristi hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Og eg, brør, kunde ikkje tala til dykk som til åndelege, men berre som til kjøtlege, som til nyfødingar i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Eg gav dykk mjølk å drikka og ikkje fast føda; for de tolde det ikkje endå. Ja, de toler det ikkje enno,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'for de er enno kjøtlege; for når det er ovund og trætta millom dykk, er de då ikkje kjøtlege og ferdast på menneskjevis?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'For når ein segjer: «Eg held meg til Paulus,» og ein annan: «Eg til Apollos», er de ikkje då menneskje?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kva er då Apollos, og kva er Paulus? Tenarar som de kom til trui ved, og det etter som Herren gav kvar for seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Eg planta, Apollos vatna; men Gud gav vokster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'So er no korkje den noko som planter, eller den som vatnar, men Gud som gjev vokster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Den som plantar, og den som vatnar, er eitt, men kvar skal få si eigi løn etter sitt eige arbeid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'For me er Guds medarbeidarar, de er Guds åkerland, Guds bygnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Etter den Guds nåde som er meg gjeven, hev eg lagt grunnvoll som ein vis byggmeister, men ein annan byggjer uppå; men kvar sjå til, korleis han byggjer uppå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'For annan grunnvoll kann ingen leggja enn den som er lagd, det er Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Men um nokon byggjer på denne grunnvollen med gull, sylv, dyre steinar, tre, høy, strå,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'då skal kvar manns verk verta synbert; for dagen skal syna det, for han vert openberra med eld; og korleis kvar manns verk er, det skal elden prøva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Um nokon manns verk som han bygde, stend seg, so skal han få løn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'um nokon manns verk brenn upp, so skal han missa henne; sjølv skal han då verta frelst, men so som gjenom eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Veit de ikkje at de er Guds tempel, og Guds Ande bur i dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Tyner nokon Guds tempel, honom skal Gud tyna; for heilagt er Guds tempeler, og det er de.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Ingen dåre seg sjølv! Um nokon millom dykk tykkjest vera vis i denne verdi, lat honom verta ei dåre, so han kann verta vis!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'For visdomen som høyrer denne verdi til, er dårskap for Gud. For det stend skrive: «Han fangar dei vise i deira sløgd,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'og atter: «Herren kjenner tankarne hjå dei vise, at dei er fåfengde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Difor skal ingen rosa seg av menneskje; for alt høyrer dykk til,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'anten det er Paulus eller Apollos eller Kefas, anten det er verdi eller liv eller daude, anten det er det som no er, eller det som koma skal: alt høyrer dykk til;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'men de høyrer Kristus til, og Kristus høyrer Gud til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Soleis halde folk oss for Kristi tenarar og hushaldarar yver Guds løyndomar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Elles vert det kravt av hushaldarar, at dei må verta funne true.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Men for meg hev det lite på seg å verta dømd for dykk eller av ein menneskjeleg domstol; ja, eg dømer ikkje meg sjølv di heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'For vel veit eg ingen ting med meg sjølv, men med det er eg ikkje rettferdiggjord; men den som dømer meg, er Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Døm difor ikkje nokon fyre tidi, fyrr Herren kjem, han som og skal føra fram i ljoset det som er dult i myrkret, og openberra råderne i hjarto; og då skal kvar og ein få si ros av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Dette, brør, hev eg yverført på meg sjølv og Apollos for dykkar skuld, so de må læra av oss at ein ikkje skal ganga lenger enn det som skrive stend, so ingen av dykk skal blåsa seg upp for den eine i mot den andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'For kven gjev vel deg fyremun? Og kva hev du, som du ikkje hev fenge? Men um du no og hev fenge noko, kvi rosar du deg då, som um du ikkje hadde fenge det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'De hev alt vorte mette, de hev alt vorte rike, utan oss hev de vorte herrar; ja, gjev de hadde vorte herrar, so me og kunde vera herrar saman med dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'For eg tykkjer at Gud hev synt oss apostlar fram som dei ringaste, som dømde til dauden; for me hev vorte til ei bisn for verdi, både for englar og for menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Me er dårar for Kristi skuld, men de er kloke i Kristus; me er veike, men de er sterke; de er heidra, men me ærelause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Til denne stund er me både hungrige og tyrste og nakne og slegne og heimlause,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'og mødde, med di me arbeider med våre eigne hender; me vert utskjelte, og me velsignar; me vert forfylgde, og me tek det med tol;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'me vert spotta, og me påminner; me hev vorte som avrak i verdi, utskot for alle til denne stund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Eg skriv ikkje dette til vanæra for dykk, men av di de er mine kjære born, påminner eg dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'For um de hev ti tusund læremeistrar i Kristus, so hev de då ikkje mange feder; for i Kristus Jesus hev eg avla dykk ved evangeliet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Eg legg dykk difor på hjarta: Vert mine etterfylgjarar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Difor sende eg dykk Timoteus, som er min kjære og trufaste son i Herren, at han skulde minna dykk um mine vegar i Kristus, soleis som eg lærer alle stader hjå kvar kyrkjelyd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Men sume hev blåse seg upp i von um, at eg ikkje skulde koma til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Men eg kjem til dykk snart, um Herren vil, og fær då læra å kjenna ikkje ordi, men krafti hjå dei uppblåsne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'For Guds rike stend ikkje i ord, men kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Kva vil de? Skal eg koma til dykk med ris eller med kjærleik og ei smålåti ånd?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Der gjeng allfares ord um hor hjå dykk, og det slikt hor, som ikkje ein gong vert nemnt hjå heidningarne, at ein held seg med kona åt far sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Og de blæs dykk upp, endå de langt heller skulde syrgja, so den som hev gjort denne gjerningi, kunde verta støytt ifrå dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'For eg, som vel er fråverande med likamen, men nærverande med åndi, eg hev alt dømt, som eg var nærverande, at den som hev gjort dette,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'han skal i vår Herre Jesu Kristi namn, med di de og mi ånd kjem saman i vår Herre Jesu Kristi kraft,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'verta yvergjeven til Satan til tyning av kjøtet, so åndi kann verta frelst på Herren Jesu dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Det er ikkje fagert det som de rosar dykk av. Veit de ikkje, at ein liten surdeig syrer heile deigen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Reinsa difor ut den gamle surdeigen, so de kann vera ny deig, liksom de er usyrde; for ogso vårt påskelamb er slagta: Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Lat oss so halda helg, ikkje med gamall surdeig, ikkje med vondskap og argskaps surdeig, men med reinleiks og sannings usyrde brød!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Eg skriv til dykk i brevet, at de ikkje skulde hava umgjenge med horkarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'og då meinte eg ikkje horkararne av denne verdi i det heile, eller giruge eller røvarar eller avgudsdyrkarar, for elles laut de ganga ut or verdi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'men eg skreiv til dykk at de ikkje skal hava umgjenge med nokon, som er kalla bror og er ein horkar eller girug eller avgudsdyrkar eller baktalar eller drikkar eller røvar, so de ikkje ein gong et i saman med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'For kva hev vel eg med å døma deim som er utanfor? Dømer ikkje de og berre dei som er innanfor?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'men Gud skal døma deim som er utanfor. So støyt då ut den vonde frå dykk sjølve!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Vågar nokon av dykk, når han hev sak mot ein annan, å søkja dom hjå dei urettferdige og ikkje hjå dei heilage?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Eller veit de ikkje, at dei heilage skal døma verdi? Og dersom verdi vert dømd av dykk, er de då uverdige til å døma i dei minste saker?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Veit de ikkje, at me skal døma englar, og då vel mykje meir i timelege ting?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Når de då hev saker um timelege ting, so set de deim til domarar som er vanvyrde i kyrkjelyden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Til skam for dykk segjer eg dette. So finst der då ingen vis mann hjå dykk, ikkje ein einaste som kann skilja trætta for bror sin?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Men bror fører sak mot bror, og det endå for vantruande domarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Det er no i det heile eit tap for dykk at de hev sak med kvarandre. Kvi lid de ikkje heller urett? Kvi toler de ikkje heller uskil?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Men de gjer urett og uskil, og det endå mot brør!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Eller veit de ikkje, at dei urettferdige ikkje skal erva Guds rike? Lat dykk ikkje dåra! Korkje lauslevande eller avgudsdyrkarar eller horkarar eller blautfengne eller slike som syndar mot naturi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'eller tjuvar eller giruge eller drikkarar eller baktalarar eller røvarar skal erva Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Og slike var sume av dykk; men de er avtvegne, men de er helga, de er rettferdiggjorde ved Herren Jesu namn og i vår Guds Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Alt hev eg lov til, men ikkje alt gagnar; alt hev eg lov til, men eg skal ikkje lata noko få vald yver meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Maten er for magen, og magen for maten; og Gud skal gjera ende både på den eine og den andre. Men likamen er ikkje for hor, men for Herren, og Herren for likamen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Og Gud vekte upp Herren og skal og vekkja oss upp ved si kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Veit de ikkje, at dykkar likamar er Kristi lemer? Skal eg då taka Kristi lemer og gjera deim til lemer åt ei skjøkja? Langt ifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Eller veit de ikkje, at den som held seg til skjøkja, er ein likam med henne? For det er sagt: «Dei tvo skal vera eitt kjøt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Men den som held seg til Herren, er ein ande med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fly hor! All synd som eit menneskje kann gjera, er utanfor likamen; men den som gjer hor, syndar imot sin eigen likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Eller veit de ikkje, at likamen dykkar er eit tempel for den Heilage Ande som bur i dykk, han som de hev frå Gud, og at de ikkje er dykkar eigne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'For de er dyrt kjøpte. \'ra då Gud i dykkar likam!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Men vedkomande det som de skreiv um, so er det godt for ein mann at han ikkje rører ei kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Men for hor skuld skal kvar mann hava si eigi kona, og kvar kvinna sin eigen mann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Mannen skal gjera sin skyldnad mot kona, og like eins kona imot mannen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Kona råder ikkje yver sin eigen likam, men mannen; like eins råder ikkje heller mannen yver sin eigen likam, men kona.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Haldt dykk ikkje frå einannan, utan etter samråd, til ei tid, so de kann liva berre for bøn, og kom so atter saman, so Satan ikkje skal freista dykk, av di de ikkje kann vera fråhaldande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Men dette segjer eg som eit løyve, ikkje til påbod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'For eg vilde at alle menneskje var liksom eg; men kvar hev si eigi nådegåva av Gud, den eine so, den andre so.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Til dei ugifte og til enkjorne segjer eg: Det er godt for deim um dei vert verande som eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Men kann dei ikkje halda seg frå, so fær dei gifta seg, for det er betre å gifta seg enn å lida brune.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Men deim som er gifte, byd ikkje eg, men Herren, at kona ikkje må skiljast frå mannen -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'men er ho skild frå honom, skal ho verta verande ugift eller semjast med mannen - og at ein mann ikkje må skilja seg frå kona si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Til dei andre segjer eg, ikkje Herren: Um ein bror hev ei vantruande kona, og ho samtykkjer i å bu hjå honom, so skal han ikkje skilja seg frå henne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'og ei kona som hev ein vantruande mann, og han samtykkjer å bu hjå henne, ho skal ikkje skilja seg frå mannen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'For den vantruande mannen er helga ved kona, og den vantruande kona er helga ved broren; for elles var borni dykkar ureine, men no er dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Men skil den vantruande seg ifrå, so lat honom skilja seg; for broren eller systeri er ikkje trælbundne i slike ting, men Gud hev kalla oss til fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'For kva veit du, kona, um du kann frelsa mannen? Eller kva veit du, mann, um du kann frelsa kona?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Berre at kvar må ferdast so som Herren hev gjeva honom, som Gud hev kalla honom. Og soleis segjer eg fyre i alle kyrkjelydarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Er nokon kalla då han var nokon umskoren, so drage han ikkje fyrehud yver; er nokon kalla då han var u-umskoren, so late han seg ikkje umskjera!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Umskjering er ingen ting, og fyrehud er ingen ting, men det å halda Guds bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Kvar og ein verte verande i det kall som han er kalla i!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Er du kalla som træl, so syt ikkje for det! Men kann du og verta fri, so gjer heller bruk av det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'For den træl som er kalla i Herren, han er Herrens frigjevne; like eins og den frie som er kalla, han er Kristi træl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'De er dyrt kjøpte; vert ikkje trælar for menneskje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'I det stand som kvar er kalla i, brør, i det verte han verande hjå Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Men um møyarne hev eg ikkje noko bod frå Herren, men eg segjer mi meining, sidan eg av Herren hev fenge miskunn til å vera truverdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Eg meiner då det, at det for den noverande naud skuld er godt for eit menneskje å vera soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Er du bunden til ei kona, so søk ikkje skilsmål! Er du ubunden av ei kona, so søk ikkje ei kona!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Men um du og gifter deg, syndar du ikkje; og um ei møy gifter seg, syndar ho ikkje; men slike kjem til å få trengsla for kjøtet, men eg vilde gjerne spara dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Men det segjer eg, brør: Tidi er stutt, so at dei som hev konor, skal heretter vera som dei som ikkje hev,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'og dei gråtande som ikkje gråtande, og dei glade som ikkje glade, og dei kjøpande som ikkje eigande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'og dei som brukar denne verdi, som dei som ikkje brukar henne; for skapnaden åt denne verdi forgjengst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Eg vil helst at de skal vera utan umsut. Den ugifte hev umsut for det som høyrer Herren til, korleis han kann vera Herren til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Men den gifte hev umsut for det som høyrer verdi til, korleis han skal vera kona til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Det er skilnad på kona og møy. Den ugifte kvinna hev umsut for det som høyrer Herren til, at ho kann vera heilag både på likam og ånd; men den gifte hev umsut for det som høyrer verdi til, korleis ho kann vera mannen til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Dette segjer eg til dykkar eige gagn, ikkje til å setja ei snara for dykk, men til å fremja sømd og stødt vedhald for Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Men um nokon trur at det er urett for hans ugifte dotter, når ho er utyver ungdomsalderen, og det må so vera, han gjere då som han vill, han syndar ikkje; lat deim gifta seg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Men den som stend fast i hjarta og ikkje er nøydd, men hev vald yver sin eigen vilja og hev sett seg det fyre i sitt hjarta at han vil halda dotter si ugift, han gjer vel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'so at både den som gifter burt, gjer vel, og den som ikkje gifter burt, gjer betre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Ei kona er bundi so lenge mannen hennar liver; men når mannen hennar er avsovna, er ho fri, so ho kann gifta seg med kven ho vil, berre det vert gjort i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Men sælare er ho, um ho vert verande som ho er, etter mi meining. Men eg trur og at eg hev Guds Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Men vedkomande avgudsoffer, so veit me at me alle hev kunnskap. - Kunnskapen blæs upp, men kjærleiken byggjer upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Um nokon tykkjest kjenna noko, han hev aldri kjent noko soleis som ein skal kjenna det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Men um nokon elskar Gud, so er han kjend av honom. -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Vedkomande eting av avgudsoffer, so veit me at ingen avgud i verdi er til, og at det finst ingen annan Gud enn ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'For um det og er dei som vert kalla gudar anten i himmelen eller på jordi - som det er mange gudar og mange herrar -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'so finst det då for oss berre ein Gud, Faderen, som alle ting er av, og me til honom, og ein Herre, Jesus Kristus, som alle ting er til ved, og me ved honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Men den kunnskap er ikkje hjå alle; men sume gjer seg endå samvit for avguden skuld og et det som avgudsoffer, og då samvitet deira er veikt, vert det ureint.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Men mat gjev oss ikkje verd for Gud; korkje vinn me noko um me et, eller taper noko um me ikkje et.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Men sjå til at ikkje denne fridomen dykkar vert til støyt for dei veike!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'For um nokon ser deg som hev kunnskap sitja til bords i avgudshuset, vert då ikkje samvitet hjå honom som er veik, tilstyrkt til å eta avgudsoffer?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Og den veike bror, som Kristus døydde for, vert då fortapt for din kunnskap skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Men når de soleis syndar imot brørne og sårar deira veike samvit, so syndar de mot Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Difor, dersom mat valdar støyt for bror min, so vil eg i all æva ikkje eta kjøt, so eg ikkje skal valda støyt for bror min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Er eg ikkje fri? Er eg ikkje apostel? Hev eg ikkje set Jesus, vår Herre? Er ikkje de mitt verk i Herren?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Er eg ikkje apostel for andre, so er eg det då for dykk; for de er innsiglet på mitt apostel-embætte i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Dette er mitt forsvar mot deim som dømer meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Hev me ikkje rett til å eta og drikka?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Hev me ikkje rett til å føra med oss ei syster som kona liksom og dei andre apostlar og Herrens brør og Kefas?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Eller er det berre eg og Barnabas som ikkje hev rett til å sleppa å arbeida?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kven gjer vel nokon gong hertenesta på eigen kostnad? Kven plantar ein vinhage og et ikkje av frukti hans? Eller kven føder ei hjord og et ikkje av mjølki frå hjordi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Talar eg dette berre etter menneskjevis, eller segjer ikkje lovi og dette?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'For i Mose lov stend det skrive: «Du skal ikkje setja muleband på ein ukse når han treskjer.» Er det uksane Gud hev umsut for,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'eller segjer han det berre for vår skuld? For det er for vår skuld det er skrive, at den som pløgjer, skal pløgja med von, og den som treskjer, skal gjera det med von um å få sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Hev me sått for dykk dei åndelege ting, er det då noko stort um me haustar dykkar timelege ting?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Hev andre rett yver dykk, skulde då ikkje me mykje meir hava det? Men me hev ikkje bruka denne retten, me toler alt, so me ikkje skal leggja noko hinder for Kristi evangelium.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Veit de ikkje, at dei som gjer tenesta med det heilage, fær føda av heilagdomen? dei som gjer tenesta ved altaret, fær lut med altaret?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Soleis hev og Herren skipa det so for deim som forkynner evangeliet, at dei skal liva av evangeliet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Men eg hev ikkje gjort bruk av noko av dette. Eg skriv ikkje dette difor, at det skal verta so med meg; for det var betre for meg å døy, enn at nokon skulde gjera mi ros til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'For um eg forkynner evangeliet, so er det ikkje noko å rosa meg av, for det ligg naudsynt på meg; ja, usæl eg, um eg ikkje forkynner evangeliet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'For um eg gjer dette godviljugt, hev eg løn; men gjer eg det uviljugt, so er det då eit hushald som er meg yverlate.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Kva er då mi løn? At eg, når eg forkynner evangeliet, gjer det for inkje, so eg ikkje brukar min rett i evangeliet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'For endå eg er fri for alle, hev eg då gjort meg sjølv til tenar for alle, so eg kann vinna dei fleste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Og eg hev vorte som ein jøde for jødarne, so eg kann vinna jødar; for deim under lovi, som eg var under lovi - endå eg ikkje er under lovi - so eg kann vinna deim som er under lovi;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'for deim som er utan lov, som om eg var utan lov - endå eg ikkje er lovlaus for Gud, men lovbunden for Kristus - so eg kann vinna dei som er utan lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'For dei veike hev eg vorte veik, so eg kann vinna dei veike; for dei alle hev eg vorte alt, for at eg i alle høve skal kunna frelsa nokre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Men alt gjer eg for evangeliet skuld, for at eg skal få lut i det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Veit de ikkje, at dei som kapprenner på skeidvollen, dei renner vel alle, men ein tek sigersprisen? Renn då soleis, so de kann få honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Kvar den som er med i tevling, er fråhaldande i alt, hine so dei kann få ein forgjengeleg krans, men me ein uforgjengeleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'So renner eg då soleis, ikkje som på det uvisse; eg fiktar ikkje som den som slær ut i veret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Men eg tvingar min likam og trælkar honom, so ikkje eg som preikar for andre, skal sjølv verta funnen uverdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Men eg vil ikkje, brør, at de skal vera uvitande um at federne våre var alle under skyi og gjekk alle gjenom havet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'og vart alle døypte til Moses i skyi og havet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'og dei åt alle den same åndelege maten');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'og drakk alle den same åndelege drykken; for dei drakk av det åndelege berget som fylgde deim; og berget var Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Men like vel hadde Gud ikkje hugnad i dei fleste av deim; for dei vart nedslegne i øydemarki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Men desse ting hev vorte fyredøme for oss, so ikkje me skal trå etter det vonde liksom dei trådde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Vert ikkje heller avgudsdyrkarar liksom nokre av deim! som skrive stend: «Folket sette seg ned til å eta og drikka og stod upp til å leika.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Lat oss ikkje heller driva hor, liksom nokre av deim dreiv hor og fall på ein dag tri og tjuge tusund!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Lat oss ikkje heller freista Kristus, liksom nokre av deim freista honom og vart tynte av hoggormar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Murra ikkje heller, liksom nokre av deim murra og vart tynte av tynaren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Men dette hende deim som fyredøme, men det er skrive til påminning for oss som dei siste tider er komne til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Difor, den som tykkjer han stend, han sjå til at han ikkje fell!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Dykk hev ingi freisting råka som menneskje ikkje kann bera; men Gud er trufast, som ikkje skal lata dykk verta freista utyver det de toler, men skal gjera både freistingi og utgangen slik at de kann halda det ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Difor, mine kjære, fly frå avgudsdyrkingi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Eg talar som til skynsame folk. Døm sjølv um det eg segjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Velsigningskalken som me velsignar, er han ikkje samfund med Kristi blod? Brødet som me bryt, er det ikkje samfund med Kristi likam?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Av di der er eitt brød, er me ein likam, endå me er mange; for me er alle samhavande i det eine brødet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Sjå til Israel etter kjøtet! Hev ikkje dei som et offeri, samfund med altaret?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Kva meiner eg so? At avgudsoffer til? eller at ein avgud er til?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Nei, men at det dei ofrar, det ofrar dei til vonde ånder og ikkje til Gud; men eg vil ikkje at de skal koma i samfund med dei vonde ånder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'De kann ikkje drikka kalken til Herren og kalken til vonde ånder; de kann ikkje hava bordsamlag med Herren og bordsamlag med vonde ånder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Eller torer me eggja Herren til harm? Me er då vel ikkje sterkare enn han?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Alt hev eg lov til, men ikkje alt gagnar. Alt hev eg lov til, men ikkje alt uppbyggjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Ingen søkje bate for seg sjølv, men det som batar den andre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Et alt som vert selt i slagtarbudi, og spør ikkje meir um det for samvitet skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'For jordi og alt det som fyller henne, høyrer Herren til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Og um nokon av dei vantruande bed dykk til gjest, og de vil ganga dit, so et alt som vert framsett for dykk, og spør ikkje meir um det for samvitet skuld!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Men um nokon segjer til dykk: «Dette er avgudsoffer,» so et ikkje, for hans skuld som fortalde det, og for samvitet skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Samvitet, segjer eg, ikkje eins eige, men samvitet hjå den andre. For kvi skal min fridom dømast av annan manns samvit?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Um eg et med takk, kvi skal eg då verta spotta for det som eg takkar for?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Anten de so et eller drikk, eller kva de gjer, so gjer alt til Guds æra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ver ikkje til meinstøyt korkje for jødar eller grækarar eller for Guds kyrkja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'liksom eg og i alt strævar å tekkjast alle, då eg ikkje søkjer det som er gagnlegt for meg sjølv, men for dei mange, at dei må verta frelste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Vert mine etterfylgjarar, liksom eg fylgjer etter Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Eg rosar dykk, brør, at de minnest meg i alle ting, og at de held fast på mine fyreskrifter, so som eg gav dykk deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Men eg vil de skal vita, at hovudet for kvar mann er Kristus, og hovudet for kvinna er mannen, og hovudet for Kristus er Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Kvar mann som bed eller talar profetord og då hev noko på hovudet, han vanærar hovudet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Men kvar kvinna som bed eller talar profetord utan hovudbunad, ho vanærar hovudet sitt; for det er eitt og det same som ho var raka.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'For dersom ei kvinna ikkje brukar hovudbunad, so lat henne og klyppa av seg håret; men er det usømelegt for ei kvinna å klyppa eller raka av seg håret, so lat henne bruka hovudbunad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'For ein mann skal ikkje hava noko på hovudet, då han er Guds bilæte og æra; men kvinna er mannsens æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'For mannen er ikkje av kvinna, men kvinna av mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'For mannen vart ikkje heller skapt for kvinna skuld, men kvinna for mannen skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Difor skal kvinna hava lydskyldnads-merke på hovudet for englarne skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Men i Herren er korkje kvinna noko framfor mannen eller mannen noko framfor kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'For liksom kvinna er av mannen, so er og mannen ved kvinna; og alt er av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Døm hjå dykk sjølve! Er det sømelegt at ei kvinna bed til Gud utan hovudbunad?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Lærer ikkje sjølve naturi dykk, at um ein mann let håret veksa langt, er det honom til vanæra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'men um ei kvinna let håret veksa langt, er det henne til æra? for det lange håret er gjeve henne til sveip.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Men dersom nokon vil vera trættekjær, so hev ikkje me den sedvane, og ikkje Guds kyrkjelydar heller.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Men når eg fyreskriv dette, rosar eg ikkje at de kjem saman, ikkje til det betre, men til det verre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'For fyrst so høyrer eg, at når de kjem saman i kyrkjelyden, so er der usamnad hjå dykk, og eg trur det for ein deil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'For det lyt vera serflokkar hjå dykk, so dei velrøynde kann verta openberre millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Når de so kjem saman, vert det ikkje Herrens nattverd det et.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'For når de et, so tek kvar fyrst sin eigen mat, og den eine hungrar, men den andre fyller seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Hev de ikkje hus til å eta og drikka i? Eller vanvyrder de Guds kyrkja og vanærar deim som ingen ting hev? Kva skal eg segja dykk? Skal eg rosa dykk? I dette rosar eg dykk ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'For eg hev fenge frå Herren det som eg og hev yvergjeve dykk, at Herren Jesus, den natti han vart sviken, tok han eit brød,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'og takka og braut det og sagde: «Dette er min likam som er for dykk. Gjer dette til minne um meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Like eins tok han og kalken etter kveldverden og sagde: «Denne kalk er den nye pakt i mitt blod. So ofte som de drikk av han, so gjer dette til minne um meg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'For so ofte som de et dette brødet og drikk denne kalken, so forkynner de Herrens daude, til dess han kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Difor, den som et brødet og drikk Herrens kalk uverdigt, han vert skuldig i Herrens likam og blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Men kvart menneskje prøve seg sjølv, og so ete han av brødet og drikke av kalken!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'For den som et og drikk, han et og drikk seg sjølv til dom, når han ikkje gjer skil på Herrens likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Difor er det mange veike og sjuke hjå dykk, og mange sovnar av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Men dersom me dømde oss sjølve, vart me ikkje dømde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Men når me vert dømde, vert me refste av Herren, so me ikkje skal verta fordømde saman med verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Difor, mine brør, når de kjem saman til å eta, so skift med kvarandre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Men dersom nokon hungrar, so ete han heime, so de ikkje skal koma saman til dom. Det andre skal eg fyreskriva når eg kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Men um dei åndelege gåvor vil eg ikkje at de skal vera uvitande, brør!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'De veit at då de var heidningar, let de dykk draga til dei mållause avgudarne, etter som de vart dregne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Difor kunngjer eg dykk, at ingen som talar i Guds Ande, segjer: «Forbanna er Jesus,» og ingen kann segja: «Jesus er Herre,» utan i den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Det er skil på nådegåvor, men Anden er den same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Og det er skil på tenestor, men Herren er den same.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Og det er skil på kraftige verknader, men Gud er den same, som verkar alt i alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Men openberringi av Anden fær kvar og ein til det som er gagnlegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'For ein fær visdoms tale ved Anden, men ein annan kunnskaps tale ved den same Ande;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'ein annan tru ved den same Ande, ein annan nådegåvor til å lækja ved den same Ande;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'ein annan kraft til å gjera under, ein annan profetgåva, ein annan gåva til å prøva ånder, ein annan ymse tungor, ein annan tyding av tungor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Men alt dette verkar ein og den same Ande, som skifter ut til kvar for seg, etter som han vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'For liksom likamen er ein og hev mange lemer, men alle lemerne på likamen er ein likam, endå dei er mange, soleis er det og med Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'For i ein Ande er me alle døypte til å vera ein likam - anten me er jødar eller grækarar eller trælar eller frie - og alle hev me fenge drikka ein Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'For likamen er ikkje heller ein lem, men mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Um foten vilde segja: «Då eg ikkje er hand, so høyrer eg ikkje med til likamen,» so høyrer han då like fullt med til likamen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Og um øyra vilde segja: «Då eg ikkje er auga, so høyrer eg ikkje med til likamen,» so høyrer det då like fullt med til likamen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Dersom heile likamen var auga, kvar vart det då av høyrsla? Dersom det heile var høyrsla, kvar vart det då av lukti?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Men no hev Gud sett lemerne, kvar ein av dei på likamen, so som han vilde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Men dersom dei alle var ein lem, kvar vart det då av likamen?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Men no er det mange lemer, men ein likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Auga kann ikkje segja til handi: «Eg treng ikkje til deg,» eller hovudet til føterne: «Eg treng ikkje til dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Men tvert imot: dei lemerne på likamen som synest vera veikast, dei er naudsynlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Og dei lemerne på likamen som syntest oss mindre æra verde, deim klæder me med større æra; og dei lemerne våre som me blygjest ved, deim klæder me med større blygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Men dei lemerne våre som er oss til sømd, dei treng ikkje til det. Men Gud hev sett likamen soleis saman, at han gav det ringaste størst æra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'so det ikkje skal vera tvidrag i likamen, men at lemerne skal hava same umsut for kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Og um ein lem lid, so lid alle lemerne med, eller um ein lem vert heidra, so gled alle lemerne seg med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Men de er Kristi likam og lemer, kvar etter sin lut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Og Gud sette i kyrkja fyrst nokre til apostlar, for det andre profetar, for det tridje lærarar, so kraftige verk, so nådegåvor til å lækja, til å hjelpa, til å styra, so ymse tungor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Er vel alle apostlar? Er alle profetar? Er alle lærarar? Gjer alle kraftige verk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Hev alle nådegåvor til lækja? Kann alle tala med tungor? Kann alle tyda deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Men streva etter dei største nådegåvor! Og eg skal visa dykk ein endå betre veg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Um eg talar med menneskjetungor og engletungor, men hev ikkje kjærleik, då er eg ein ljomande malm eller ei klingande bjølla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Og um eg hev profetgåva og kjenner alle løyndomar og all kunnskap, og um eg hev all tru, so at eg kann flytja fjell, men hev ikkje kjærleik, då er eg ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Og um eg gjev til føda for fatige alt det eg eig, og um eg gjev min likam til å verta brend, men hev ikkje kjærleik, då gagnar det meg ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Kjærleiken er langmodig, er velviljug; kjærleiken ovundast ikkje; kjærleiken briskar seg ikkje, blæs seg ikkje upp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'han gjer inkje usømelegt, søkjer ikkje sitt eige, illskast ikkje, gøymer ikkje på det vonde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'han gled seg ikkje ved urettferd, men gled seg ved sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Alt lid han, alt trur han, alt vonar han, alt toler han.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Kjærleiken fell aldri burt; men anten det er profetgåvor, so skal dei få ende, eller tungor, so skal dei tagna, eller kunnskap, so skal han få ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'For me skynar i stykkjevis og talar profetisk i stykkjevis;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'men når det fullkomne kjem, då skal det som er i stykkjevis, få ende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Då eg var barn, tala eg som eit barn, tenkte eg som eit barn, dømde eg som eit barn; men då eg vart mann, lagde eg av det barnslege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'For no ser me i ein spegel, i ei gåta, men då skal me sjå åsyn til åsyn; no kjenner eg i stykkjevis, men då skal eg kjenna fullt ut, liksom eg og fullt ut er kjend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Men no vert dei verande desse tri: Tru, von, kjærleik, og størst av deim er kjærleiken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Trå etter kjærleiken, stræva etter dei åndelege gåvor, men mest etter å tala profetisk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'For den som talar med tunga, talar ikkje for menneskje, men for Gud; for ingen skynar det, men han talar løyndomar i Anden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Men den som talar profetisk, han talar for menneskje til uppbyggjing og påminning og trøyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Den som talar med tunga, uppbyggjer seg sjølv; men den som talar profetisk, uppbyggjer kyrkjelyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Endå vilde eg at de alle kunde tala med tungor, men heller at de kunde tala profetisk; for den som talar profetisk, er større enn den som talar med tungor, utan so er at han uttyder det, so kyrkjelyden kann få uppbyggjing av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Og no, brør, um eg kjem til dykk og talar med tungor, kva kann eg då gagna dykk, um eg ikkje talar til dykk anten med openberring eller med kunnskap anten med profetord eller med læra?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Dersom dei livlause ting som gjev ljod, anten det er ei fløyta eller ei harpa, ikkje gjer skilnad på tonar, korleis kann ein då skyna det som vert spela på fløyta eller på harpa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Og um ein stridslur gjev uklår ljod, kven lagar seg då til strid?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Soleis og med dykk: um de med tunga ikkje talar tydelege ord, korleis kann ein då skyna det som vert tala? De talar då burt i veret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'So mange slag mål er der no visst i verdi, og ikkje noko av deim er utan meining.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Um eg då ikkje kjenner meiningi i målet, vert eg ein framand for den talande, og den talande ein framand for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Soleis og med dykk: når de strevar etter dei åndelege gåvor, so søk å få deim i rikt mål til uppbyggjing for kyrkjelyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Difor skal den som talar med tunga, beda um at han må kunna tyda det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'For um eg bed med tunga, so bed mi ånd; men mitt vit er utan frukt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Korleis er det då? Eg vil beda med åndi, men eg vil og beda med vitet; eg vil lovsyngja med åndi, men eg vil og lovsyngja med vitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'For dersom du lovar Gud med åndi, kor kann då nokon millom dei ukunnige segja amen til di takkebøn? Han veit ikkje kva du segjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'For du held vel ei fager takkebøn, men den andre vert ikkje uppbygd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Eg takkar Gud: eg talar meir med tunga enn de alle;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'men i ein kyrkjelyd vil eg heller tala fem ord med vitet mitt, so eg kann læra andre, enn ti tusund ord med tunga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Brør, ver ikkje born i vit! ver derimot born i vondskap; men ver fullvaksne i vit!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Det stend skrive i lovi: «Ved folk som hev framand tunga, og ved framande lippor vil eg tala til dette folket, og endå skal dei ikkje høyra på meg, segjer Herren.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'So er då tungorne til eit teikn, ikkje for deim som trur, men for dei vantruande; men profettalen er ikkje for dei vantruande, men for deim som trur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Um då heile kyrkjelyden kjem saman, og alle talar med tungor, men det kjem inn ukunnige eller vantruande, vil dei ikkje då segja at de er frå vitet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Men um alle talar profetisk, og det kjem inn ein vantruande eller ukunnig, so vert han refst av alle, dømd av alle,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'det løynde i hans hjarta vert openberra, og so vil han falla på sitt andlit og tilbeda Gud og vitna at Gud er sanneleg millom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Korleis er det då, brør? Når de kjem saman, hev kvar av dykk ein salme, ein lærdom, ei openberring, ei tunga, ei tyding; lat alt vera til uppbyggjing!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Talar nokon med tunga, so lat det vera tvo eller i det høgste tri kvar gong, og ein i senn, og ein må tyda det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Men er det ingen som kann tyda, so tegje han i kyrkjelyden, men for seg sjølv og for Gud tale han!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Men av profetar tale tvo eller tri; men dei andre må døma um det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Men um ein annan fær ei openberring medan han sit der, so skal den fyrste tegja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'For de kann alle tala profetisk, ein i senn, so alle kann få lærdom, alle få påminning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Og profetånder er profetar lyduge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'For Gud er ikkje ustyrs Gud, men freds Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Liksom i alle kyrkjelydarne hjå dei heilage, so skal kvinnorne dykkar tegja i kyrkjesamlingarne; for dei hev ikkje lov til å tala, men må vera undergjevne, so som og lovi segjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Men vil dei læra noko, so lyt dei spyrja sine eigne menner heime; for det er usømelegt for ei kvinna å tala i kyrkjesamling.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Eller er Guds ord utgjenge frå dykk? Eller er det kome berre til dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Trur nokon at han er profet eller åndeleg, so må han skyna at det eg skriv til dykk, er Herrens bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Men um nokon ikkje skynar det, so fær han lata det uskyna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Difor, brør, stræva etter å kunna tala profetisk, og hindra ingen i å tala i tungor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Men lat alt ganga sømeleg og skipeleg til!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Eg kunngjer dykk, brør, det evangelium som eg forkynte dykk, som de og tok imot, som de og stend faste i,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'som de og vert frelste ved, dersom de held fast ved det ordet som eg forkynte dykk det med, so framt de ikkje til unyttes hev teke ved trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'For eg yvergav dykk millom dei fyrste ting det som eg sjølv tok imot, at Kristus døydde for synderne våre etter skrifterne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'og at han vart gravlagd, og at han stod upp att tridje dagen etter skrifterne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'og at han vart sedd av Kefas, og so av dei tolv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'so vart han sedd av meir enn fem hundrad brør på ein gong - av deim er dei fleste endå i live, men nokre er avsovna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'So vart han sedd av Jakob, so av alle apostlarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Men aller sist vart han og sedd av meg som av det ufullbore foster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'For eg er den ringaste av apostlarne, og er ikkje verdig til å heita apostel, av di eg forfylgde Guds kyrkja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Men av Guds nåde er eg det som eg er, og hans nåde mot meg hev ikkje vore til fåfengs; men meir enn dei alle hev eg verka, då ikkje eg, men Guds nåde som er med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Anten det då er eg eller dei andre, soleis forkynner me, og soleis kom de til trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Men når det er forkynt um Kristus at han er uppstaden frå dei daude, kor kann då sume millom dykk segja at det er ingi uppstoda av daude?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Men er det ingi uppstode av daude, so er ikkje Kristus heller uppstaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Men er ikkje Kristus uppstaden, so er vår forkynning fåfengd, so er og dykkar tru fåfengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Me vert då og funne som falske vitne um Gud, då me hev vitna imot Gud, at han hev vekt upp Kristus, som han då ikkje hev vekt upp, det vil segja, so framt dei daude ikkje stend upp.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'For stend ikkje dei daude upp, so er ikkje Kristus heller uppstaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Men er ikkje Kristus uppstaden, so er trui dykkar gagnlaus; so er de endå i synderne dykkar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'so er og dei fortapte som er avsovna i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Hev me berre i dette liv sett von til Kristus, so er me ynkelegare enn alle menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Men no er Kristus uppstaden frå dei daude og hev vorte fyrstegrøda av deim som er avsovna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'For av di dauden kom ved eit menneskje, so er og uppstoda av daude komi ved eit menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'For liksom alle døyr i Adam, so skal og alle verta livandegjorde i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Men kvar i sin stad: Kristus er fyrstegrøda, so skal dei som høyrer Kristus til, verta livandegjorde i hans koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'So kjem enden, når han gjev riket til Gud og Faderen, når han fær gjort magt og all yverråd og alt velde til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'For han skal vera konge, til dess han fær lagt alle sine fiendar under sine føter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Den siste fienden som vert tynt, er dauden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'for han hev lagt alle ting under hans føter. Men når han segjer at alt er honom underlagt, so er det klårt at han som hev lagt alt under honom, er undanteken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Men når alt er honom underlagt, so skal og Sonen sjølv gjeva seg under honom som hev lagt alt under honom, so Gud skal vera alt i alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Kva gjer då dei som let seg døypa for dei daude? Dersom dei daude i det heile ikkje stend upp, kvi let dei seg då døypa for deim?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Kvi set og me oss i fåre kvar time?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Eg døyr kvar dag, so visst som eg kann rosa meg av dykk, brør, i Kristus Jesus, vår Herre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Var det på menneskjeleg vis eg stridde med villdyr i Efesus, kva gagna det meg då? Dersom dei daude ikkje stend upp, «so lat oss eta og drikka, for i morgon døyr me!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Far ikkje vilt! Låkt samlag spiller gode seder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Vakna retteleg upp og synda ikkje! for sume hev ikkje kunnskap um Gud; til dykkar skam segjer eg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Men ein kunde segja: «Korleis stend dei daude upp? og kva slag likam kjem dei fram med?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Du uvituge! det som du sår, vert ikkje livandegjort, utan det døyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Og når du sår, sår du ikkje den likamen som skal koma, men eit nake korn, anten det er av kveite eller av anna såkorn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Men Gud gjev det ein likam so som han hev vilja, og kvart slag sæde sin eigen likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ikkje alt kjøt er det same kjøt; men eitt er kjøt i menneskje, eit anna kjøt i fe, eit anna i fugl, eit anna i fisk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Og det finst himmelske likamar og jordiske likamar; men ein herlegdom hev dei himmelske, ein annan dei jordiske.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Ein glans hev soli, og ein annan månen, og ein annan stjernorne; for den eine stjerna skil seg frå den andre i glans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Soleis er det og med uppstoda av dei daude. Det vert sått i forgjengelegdom, det stend upp i uforgjengelegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Det vert sått i vanæra, det stend upp i herlegdom; det vert sått i vanmagt, det stend upp i kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Det vert sått ein naturleg likam, det stend upp ein åndeleg likam. So visst som det finst ein naturleg likam, so finst det og ein åndeleg likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Soleis stend det og skrive: «Det fyrste menneskje Adam vart til ei livande sjæl;» den siste Adam hev vorte til ei livgjevande Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Men det åndelege er ikkje det fyrste, men det naturlege, so det åndelege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Det fyrste menneskje var frå jordi, jordisk; det andre menneskje er frå himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Slik som den jordiske var, so er og dei jordiske, og slik som den himmelske er, so skal og dei himmelske vera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Og liksom me hev bore bilætet av den jordiske, so skal me og bera bilætet av den himmelske.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Men det segjer eg, brør, at kjøt og blod kann ikkje erva Guds rike, ikkje heller erver forgjengelegdom uforgjengelegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Sjå, eg segjer dykk ein løyndom: Me skal ikkje alle sovna av, men me skal alle verta umskapa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'i hast, i ein augneblink, ved den siste luren; for luren skal ljoda, og dei daude skal standa upp uforgjengelege, og me skal verta umskapa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'For dette forgjengelege må verta iklædt uforgjengelegdom, og dette døyelege iklædt udøyelegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Men når dette forgjengelege er iklædt uforgjengelegdom, og dette døyelege er iklædt udøyelegdom, då vert det ordet uppfyllt som stend skrive: «Dauden er gløypt til siger.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '«Daude, kvar er din brodd? Daude, kvar er din siger?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Men brodden i dauden er syndi; men krafti i syndi er lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Men Gud vere takk, som gjev oss siger ved vår Herre Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Difor, mine kjære brør, ver faste og uruggelege, alltid rike i Herrens gjerning, då de veit at dykkar arbeid er ikkje fåfengt i Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Men med samanskotet til dei heilage, so gjer de og soleis som eg hev skipa det for kyrkjelydarne i Galatia!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'På den fyrste dagen i vika leggje kvar av dykk til sida hjå seg sjølv det han måtte få lukka til, so samanskotet ikkje skal verta gjort fyrst då når eg kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Men når eg kjem, skal eg senda deim som de vil velja til det, med brev til å føra kjærleiksgåva dykkar til Jerusalem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Men er det verdt at eg og reiser, so kann dei reisa saman med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Eg kjem til dykk når eg hev fare gjenom Makedonia; for eg gjeng igjenom Makedonia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Men hjå dykk kann henda eg drygjer ei tid eller endå vert vinteren yver, so de kann fylgja meg dit som eg sidan reiser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'For eg vil ikkje få sjå dykk no på vegen, for eg hev ei von um å få drygja ei tid hjå dykk um Herren gjev lov til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Men eg drygjer i Efesus til kvitsunnhelgi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'For ei stor og verksam dør er upplati for meg, og der er mange motstandarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Når Timoteus kjem, so sjå til at han kann vera hjå dykk utan otte! for han gjer Herrens gjerning liksom eg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Difor må ingen vanvyrda honom. Og fylg honom på vegen i fred, at han kann koma til meg; for eg ventar honom med brørne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Vedkomande broren Apollos, so bad eg honom mykje at han måtte fara til dykk med brørne; han var slett ikkje viljug til å koma no, men han vil koma når han fær tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Vak, statt faste i trui, ver mannelege, ver sterke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Lat alt hjå dykk ganga fyre seg i kjærleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Eg legg dykk på hjarta, brør: de kjenner huset til Stefanas, at dei er fyrstegrøda av Akaia, og at dei hev rådt seg til å tena dei heilage -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'so vis de og vyrdnad mot deim, og like eins mot kvar den som hjelper til og gjer seg umak!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Eg gled meg yver at Stefanas, Fortunatus og Akaikus er her; for saknaden av dykk hev dei avhjelpt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'For dei hev kveikt upp mi og dykkar ånd. Skyna difor på slike!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Kyrkjelydarne i Asia helsar dykk. Akvilas og Priska helsar dykk mykje i Herren saman med kyrkjelyden i deira hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Alle brørne helsar dykk. Helsa kvarandre med ein heilag kyss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Helsing med mi, Paulus’, hand:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Um nokon ikkje elskar Herren, han vere bannstøytt! Maran ata.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Herren Jesu nåde vere med dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Min kjærleik er med dykk alle i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulus, Jesu Kristi apostel ved Guds vilje, og broderen Timoteus til Guds kyrkjelyd som er i Korint, med alle dei heilage i heile Akaia:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Lova vere Gud og vår Herre Jesu Kristi Fader, miskunns Fader og all trøystings Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'han som trøystar oss i all vår trengsla, so me kann trøysta deim som er i allslags trengsla, med den trøyst som me sjølve vert trøysta med av Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'For liksom Kristi lidingar kjem rikleg yver oss, so er og vår trøyst rikleg ved Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Men um me lid trengsla, so er det til dykkar trøyst og frelsa; vert me trøysta, so er det dykk til ei trøyst som viser seg verksam i tolmod i dei same lidingar som me lid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'og vår von um dykk er fast, av di me veit at liksom de hev lut i lidingarne, so skal de og hava lut i trøysti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'For me vil ikkje, brør, at de skal vera uvitande um den trengsla som kom yver oss i Asia, at me vart ovleg hardt nedtyngde, meir enn me kunde bera, so at me jamvel mistvila um livet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'ja, me hadde med oss sjølve gjort upp at me laut døy, so me ikkje skulde lita på oss sjølve, men på Gud, som vekkjer upp dei daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'han som fria og friar oss frå slik daude, som me vonar og vil fria oss heretter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'med di de og kjem oss til hjelp med bøn, so det frå mange munnar må koma rikleg takk for oss, for den nåde som er oss gjeven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'For vår ros er dette: Vitnemålet i vårt samvit um at me i Guds heilagdom og reinleik, ikkje i kjøtleg visdom, men i Guds nåde hev ferdast i verdi, og serleg hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'For me skriv ikkje anna til dykk enn det som de les eller skynar, og eg vonar at de og skal skyna det til enden');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, '- liksom de og til deils hev skyna oss - at me er dykkar ros, liksom de og er vår på Herren Jesu dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Og i denne tillit rådde eg meg til å koma til dykk fyrst, so de kunde få endå ein nåde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'og fara frå dykk til Makedonia, og so koma frå Makedonia til dykk att og få fylgje av dykk til Judæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Då eg no tok denne rådi, for eg då kann henda fram med lauslynde, eller er det etter kjøtet eg tek dei råder som eg tek, so det hjå meg skulde vera både ja, ja og nei, nei?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'So visst som Gud er trufast, so er vårt ord til dykk ikkje ja og nei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'For Guds Son, Kristus Jesus, som vart forkynt hjå dykk ved oss, ved meg og Silvanus og Timoteus, han var ikkje ja og nei, men ja hev det vorte i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'For so mange som Guds lovnader er, so hev dei i honom sitt ja og fær og i honom sitt amen, Gud til æra ved oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Men den som held oss faste saman med dykk i Kristus og salva oss, det er Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'han som sette sitt innsigle på oss og gav Anden til pant i våre hjarto.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Men eg kallar Gud til vitne for mi sjæl, at det var for di eg vilde spara dykk at eg ikkje endå er komen til Korint;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'ikkje at me er herrar yver dykkar tru, men me er medverkande til dykkar gleda; for de stend i trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Men eg sette meg fyre for mi eigi skuld, at eg ikkje atter vilde koma til dykk med sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'For um eg gjer dykk sorg, kven er det då som gjer meg glad, utan den som eg gjer sorg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Og eg skreiv til dykk just difor, at eg ikkje, når eg kom, skulde få sorg av deim som eg skulde hava gleda av, då eg hev den tiltru til dykk alle, at mi gleda er gleda for dykk alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'For i myki trengsla og hjartans tyngsla skreiv eg dykk til med mange tåror, ikkje for di at de skulde få sorg, men at de skulde kjenna den kjærleiken som eg serleg hev til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Men um nokon hev gjort sorg, so er det ikkje meg han hev gjort sorg, men til deils - at eg ikkje skal vera for hard - dykk alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Det er nok for honom med den refsingi han hev fenge av dei fleste,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'so at de heller må tilgjeva og trøysta honom, so han ikkje skal ganga under i endå tyngre sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Difor bed eg dykk at de må lata kjærleik råda mot honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'For difor var det og eg skreiv, at eg skulde få vita um de held prøva, um de er lyduge i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Men den som de tilgjev, honom tilgjev eg og. For det eg hev tilgjeve - um eg hev havt noko å tilgjeva - det hev eg gjort for dykkar skuld, for Kristi åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'so me ikkje skal verta dåra av Satan; for me er ikkje uvitande um hans råder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Då eg kom til Troas for Kristi evangelium skuld, og ei dør var opna for meg i Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'hadde eg ikkje ro i mi ånd, av di eg ikkje fann Titus, bror min, men eg skildest frå deim og for til Makedonia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Men Gud vere takk, som alltid fører oss fram på sigerferd i Kristus og ved oss openberrar angen av kunnskapen um honom på kvar stad!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'For me er Kristi huglege ange for Gud millom deim som vert frelste, og millom deim som vert fortapte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'for desse ein ange av daude til daude, for hine ein ange av liv til liv. Og kven er vel dugleg til dette?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'For me er ikkje slike som dei mange, at me falskar Guds ord til eigi vinning, men som i reinleik, ja, som av Gud talar me for Guds åsyn i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Byrjar me å gjeva oss sjølve lovord att? eller treng me då, liksom sume folk, til å hava lovords brev til dykk eller frå dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'De er vårt brev, innskrive i våre hjarto, kjent og lese av alle menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'med di det er kunnigt at de er Kristi brev, tilkome ved vår tenesta, innskrive ikkje med blekk, men med den livande Guds Ande, ikkje på steintavlor, men på hjartans kjøttavlor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Men ei slik tiltru hev me til Gud ved Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'ikkje at me av oss sjølve duger til å tenkja ut noko som av oss sjølve, men dugleiken vår er av Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'han som og gjorde oss duglege til å vera tenarar for ei ny pakt, ikkje for bokstav, men for ande; for bokstaven slær i hel, men Anden gjer livande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Når då daudens tenesta, som var innhoggi med bokstavar på steinar, kom med herlegdom, so Israels-borni ikkje greidde å sjå på Mose åsyn på grunn av herlegdomen i hans åsyn, endå det var ein som kvarv burt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'kor skal ikkje då Andens tenesta endå meir vera i herlegdom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'For er fordømings-tenesta herlegdom, so er rettferds-tenesta endå mykje meir rik på herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'For endå det herlege er i dette stykke ikkje herlegt mot den ovrike herlegdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'For når det burtkvervande var i herlegdom, so skal det vedvarande so mykje meir vera i herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Sidan me då hev slik ei von, so gjeng me fram med stort frimod');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'og gjer ikkje som Moses, som lagde eit sveip yver si åsyn, so Israels-borni ikkje skulde skoda enden av det som kvarv burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Men deira hug vart forherd; for like til denne dag ligg det same sveipet der når dei les den gamle pakti, og det vert ikkje openberra at ho vert avlyst i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Men til denne dag ligg det eit sveip yver hjarta deira når Moses vert lesen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Men når det vender um til Herren, då vert sveipet burtteke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Men Herren er Anden; men der Herrens Ande er, der er fridom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Men me som med usveipt åsyn ser Herrens herlegdom som i ein spegel, me vert alle umlaga til det same bilæte frå herlegdom til herlegdom, liksom av Herrens Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Difor, då me hev denne tenesta, etter som me hev fenge miskunn, so misser me ikkje modet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'men me hev avsagt dei skamlege løynvegar og gjeng ikkje fram med svikråd eller forfalskar Guds ord, men ved å kunngjera sanningi steller me oss fram for alle manns samvit for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Er då enn vårt evangelium dult, so er det dult millom deim som vert fortapte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'dei som guden til denne verdi hev blinda den vantruande hugen på, so ljoset frå evangeliet um Kristi herlegdom, han som er Guds bilæte, ikkje skal skina for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'For ikkje oss sjølve forkynnar me, men Kristus Jesus som Herre, men oss sjølve som dykkar tenarar for Jesu skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'For Gud, som sagde at ljos skulde skina fram or myrkret, han er den som og let det skina i våre hjarto, so kunnskapen um Guds herlegdom i Jesu Kristi åsyn skulde lysa fram frå oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Men me hev denne skatten i leirkjerald, so den rike krafti skal vera av Gud og ikkje av oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'med di me stødt er i trengsla, men ikkje i stengsla, tvilande, men ikkje mistvilande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'forfylgde, men ikkje uppgjevne, nedslegne, men ikkje tynte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'alltid berande Jesu daude med oss i likamen, at og Jesu liv må verta openberra i vår likam;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'for endå medan me liver, vert me alltid yvergjevne til dauden for Jesu skuld, at og Jesu liv må verta openberra i vårt døyelege kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Soleis er då dauden verksam i oss, men livet i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Men då me hev den same Ande med trui - etter det som stend skrive: «Eg trudde, difor tala eg» - so trur me og, difor talar me og,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'då me veit, at han som vekte upp Herren Jesus, skal og vekkja oss upp med Jesus og stella oss fram med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'For det hender alt for dykkar skuld, so nåden kann vinna so mange fleire og verka rikleg takk til Guds æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Difor misser me ikkje modet, men um og vårt ytre menneskje gjeng til grunns, so vert då det indre uppnya dag etter dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'For vår kortvarande og lette trengsla verkar for oss ei æveleg nøgd av herlegdom i yvermål på yvermål,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'med di me ikkje fester oss ved det synlege, men ved det usynlege; for det synlege er timelegt, men det usynlege ævelegt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'For me veit, at um vår likams jordiske hus vert nedrive, so hev me ein bygnad av Gud, eit hus som ikkje er gjort med hender, ævelegt i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'For ogso medan me er i dette huset, sukkar me, av di me stundar etter å verta yverklædde med vårt hus frå himmelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'so sant me skal verta funne påklædde, ikkje nakne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'For me som er i denne hytta, sukkar under byrdi, av di me ikkje vil verta avklædde, men yverklædde, so det døyelege kann verta gløypt av livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Men den som laga oss just til dette, er Gud, som og gav oss Anden til pant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Difor er me alltid frimodige, og veit, at so lenge me er heime i likamen, er me burte frå Herren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'for me ferdast i tru, men ikkje i syn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Me er då frimodige og hyggjer oss meir til å koma burt frå likamen og koma heim til Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Difor, anten me er heime eller burte, set me vår æra i å vera honom til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'For me skal alle verta openberra for Kristi domstol, so kvar kann få att det som er verka ved likamen, etter det han hev gjort, anten godt eller vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Då me soleis kjenner otten for Herren, prøver me å vinna menneskje, men for Gud er me openberre; eg vonar og å vera openberr for dykkar samvit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Ikkje rosar me oss sjølve atter for dykk, men me gjev dykk høve til å rosa dykk av oss, so de kann hava noko å setja imot deim som rosar seg av det dei er i det ytre og ikkje i hjarta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'For um me er frå vitet, so er det for Gud, og um me er med sans og samling, so er det for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'For Kristi kjærleik tvingar oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'då me hev gjort upp med oss sjølve at ein døydde for alle, difor hev dei alle døytt. Og han døydde for alle, so dei som liver, ikkje lenger skal liva for seg sjølve, men for honom som døydde og stod upp att for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Difor kjenner me heretter ikkje nokon etter kjøtet; um me og hev kjent Kristus etter kjøtet, so kjenner me honom no ikkje lenger soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Difor, um nokon er i Kristus, so er han ein ny skapning; det gamle hev forgjengest, sjå, alt hev vorte nytt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Men alt dette er av Gud, som forlikte oss med seg sjølv ved Kristus og gav oss forlikstenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'For i Kristus forlikte Gud verdi med seg sjølv, so han ikkje tilreknar deim misgjerningarne deira, og hev lagt forliksordet ned i oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'So er me då sendebod i staden for Kristus, liksom Gud sjølv gav fyreteljing gjenom oss. Me bed i staden for Kristus: Lat dykk forlika med Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Den som ikkje visste av synd, hev han gjort til synd for oss, so me skal verta rettferdige for Gud i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Men som medarbeidarar legg me dykk og på hjarta, at de ikkje til unyttes må taka imot Guds nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'For han segjer: «I den tid som meg tektest, bønhøyrde eg deg, og på frelse-dagen hjelpte eg deg.» Sjå, no er det tid som tekkjest vel, sjå, no er det frelse-dagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Og me gjev ikkje meinstøyt i nokon ting, so ikkje tenesta skal verta lasta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'men i alt viser me oss som Guds tenarar: ved stort tolmod, i trengslor, i naud, i hugverk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'under slag, i fengsel, i upprør, i træling, i vaking, i fasta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'ved reinleik, ved skynsemd, ved langmod, ved godleik, ved den Heilage Ande, ved uskrymta kjærleik,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'med sannings ord, med Guds kraft, med rettferds våpn på høgre og vinstre sida;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'i æra og vanæra, med lastord og lovord, som villførande og endå sannferdige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'som ukjende og endå velkjende, som døyande, og sjå, me liver! som dei som vert refste, men ikkje ihelslegne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'som syrgjande, men alltid glade, som fatige, men som endå gjer mange rike, som inkje havande og endå eigande alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Vår munn er upplaten mot dykk, korintarar, vårt hjarta hev vidga seg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'De hev ikkje trongt rom hjå oss, men det er trongt i dykkar hjarto.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Men til likt vederlag - eg talar som til born -: vidga de og ut dykkar hjarto!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Gakk ikkje i framandt ok med vantruande! For kva samlag hev rettferd med urett? eller kva samfund hev ljos med myrker?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Og kva samklang er det millom Kristus og Belial? eller kva lut hev ein truande med ein vantruande?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Og kva semja hev Guds tempel med avgudar? For me er den livande Guds tempel, som Gud sagde: «Eg vil bu og ferdast millom deim, og eg vil vera deira Gud, og dei skal vera mitt folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, '«Difor, gakk ut frå deim, og skil dykk frå deim, segjer Herren, og rør ikkje ved ureint, so skal eg taka imot dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'og eg skal vera dykk ein fader, og de skal vera meg søner og døtter, segjer Herren, den allmegtige.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Sidan me då hev desse lovnaderne, mine kjære, so lat oss reinsa oss frå all ureinskap på kjøt og ånd og fullføra vår helging i Guds age!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Gjev oss rom! Ingen hev me gjort urett, ingen hev me skadt, ingen hev me gjenge for nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Ikkje til fordøming for dykk segjer eg dette; for eg hev sagt det fyrr, at de er i våre hjarto til å døy med oss og liva med oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Stor er mi tiltru til dykk, stor er mi ros yver dykk, eg er fyllt med trøyst, eg er ovrik på gleda i all vår trengsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'For då me kom til Makedonia, hadde vårt kjøt ikkje heller ro, men me vart trengde på alle måtar; utantil var strid, innantil otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Men Gud, som trøystar det nedtrykte, han trøysta oss ved Titus’ koma,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'men ikkje berre ved koma hans, men og ved den trøyst han var trøysta med yver dykk, med di han fortalde oss um dykkar lengting, dykkar gråt, dykkar ihuge for meg, so eg vart endå meir glad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'For um eg og i brevet gjorde dykk sorg, so angrar eg det ikkje, um eg og fyrr angra det; for eg ser at det brevet gjorde dykk sorg, um og berre ei stund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'No gled eg meg, ikkje for di de fekk sorg, men for di de fekk sorg til umvending; for de fekk sorg etter Gud, so de på ingen måte skulde hava skade av oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'For sorgi etter Gud verkar umvending til frelsa, som ingen angrar; men sorgi til verdi verkar daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'For sjå, dette same at de fekk sorg etter Gud, kor stor ihuge verka ikkje det hjå dykk, ja forsvar, ja harm, ja otte, ja lengting, ja brennhug, ja refsing! I alt viste de at de var reine i denne saki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Um eg då og skreiv til dykk, so var det ikkje for hans skuld som gjorde urett, eller for hans skuld som leid urett, men for di at dykkar umhug for oss skulde verta openberra hjå dykk for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Difor er me trøysta. Og attåt vår trøyst kom den langt større gleda yver Titus’ gleda; for hans ånd er uppkveikt av dykk alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'For um eg til honom hev uttala meg med ros yver dykk, hev eg ikkje vorte til skammar; men liksom me hev tala alt til dykk med sanning, so hev og vår ros til Titus vorte sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Og hans kjærleik til dykk er endå sterkare, når han minnest lydnaden hjå dykk alle, korleis de tok imot honom med age og otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Eg gled meg yver at eg i alt kann lita på dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Me kunngjer dykk, brør, den Guds nåde som er gjeven i kyrkjelydarne i Makedonia,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'at endå dei var hardt røynde med trengsla, so hev deira rike gleda og deira djupe fatigdom i yverfullt mål verka hjå deim ein rikdom på ærleg kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'For dei var viljuge etter si råd, det vitnar eg, ja yver si råd, av eigen hug,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'so dei inderleg bad oss um lov til å få vera med i hjelpi til dei heilage;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'og dei gav ikkje berre soleis som me vona, men seg sjølve gav dei fyrst til Herren og so til oss ved Guds vilje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'so at me bad Titus, at liksom han fyrr hadde byrja, so skulde han og fullenda hjå dykk ogso dette kjærleiksverket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Men liksom de er rike i alle måtar, på tru og tale og kunnskap og all umhug og på kjærleik som de hev vekt hjå oss, so vert no og rike i dette kjærleiksverket!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ikkje som eit påbod segjer eg dette, men ved ihugen hjå dei andre vil eg og røyna sanningi av dykkar kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'For de kjenner vår Herre Jesu Kristi nåde, at han for dykkar skuld vart fatig, då han var rik, so de ved hans fatigdom skulde verta rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Og eg segjer mi meining um dette; for det er til gagn for dykk, som fyreåt, alt frå i fjor, byrja ikkje berre å verka, men og å vilja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Men fullfør no og verket, so liksom hugen var til å vilja, soleis og fullføringi kann verta etter utkoma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'For er hugen der, so er han vellika etter det som han hev, ikkje etter det som han ikkje hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'For det er ikkje for di at det skal vera lette for andre og trengsla for dykk, men at det skal vera jamnad:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'dykkar yvermål vert til hjelp for deira trong i den noverande tid, at og deira yvermål kann verta til hjelp for dykkar trong, so det vert jamnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'som de stend skrive: «Den som sanka mykje, fekk ikkje yverfyllt, og den som sanka lite, leid ingen skort.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Men Gud vere takk, som inngav den same umhug for dykk i Titus’ hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'for han tok gjerne imot mi påminning, ja, han er endå so ihuga at han fer sjølvminnt ut til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Og me sender og med honom den broren som hev ros hjå alle kyrkjelydarne for sitt arbeid i evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'ja, ikkje berre det, men han er og av kyrkjelydarne utvald til vår fylgjesmann med denne kjærleiksgåva, som er framkomi ved vår tenesta, til å fremja Herrens eigi æra og vårt framtak,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'då me vil vara oss for at nokon skal lasta oss for noko som vedkjem denne rike gåva, som er framkomi ved vår tenesta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'og me legg vinn på det som godt er, ikkje berre for Herren, men og for menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Og me sender med deim vår bror, som me ofte på mange måtar hev funne ihuga, men no mykje meir ihuga ved si store tiltru til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Anten det då er tale um Titus, so er han min lagsmann og medarbeidar hjå dykk, eller um våre brør, so er dei sendemenner frå kyrkjelydarne, Kristi æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Syn deim då sanningi av dykkar kjærleik og av vår ros yver dykk, og det for augo på kyrkjelydarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'For å skriva til dykk um hjelpi til dei heilage, det treng eg ikkje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'for eg kjenner dykkar viljuge hug, som eg rosar dykk for hjå makedonarane, med di eg segjer: «Akaia var ferdigt alt frå i fjor;» og ihugen dykkar tilskunda dei mange.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Men eg sender brørne, so ikkje vår ros yver dykk skal verta til inkjes i dette stykke, men at de, som eg sagde, skal vera ferdige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'so me - um eg ikkje skal segja de sjølve - ikkje skal få skam av denne tiltru, um det kjem makedonarar med meg og finn dykk uferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Difor fann eg det naudsynlegt å telja brørne til å ganga i fyrevegen til dykk og fyreåt tilskipa gåva dykkar som fyrr var lova, so at ho kann vera ferdig som ei velsigning og ikkje som ei karg gåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Men det segjer eg: Den som sparleg sår, skal og sparleg hausta; og den som sår med velsigningar, skal og hausta med velsigningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Kvar gjeve som han set seg fyre i hjarta, ikkje med sut eller av tvang! For Gud elskar ein glad gjevar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Og Gud er megtig til å gjeva dykk all nåde i rikt mål, so de i alle ting alltid kann hava all nøgd og vera rike til all god gjerning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'som skrive stend: «Han strøydde ut, han gav dei fatige, hans rettferd vert verande i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Og han som gjev såmannen såkorn og brød til å eta, han skal og gjeva dykk sæde og gjera det rikelegt og gjeva vokster til frukterne av dykkar rettferd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'med di de i alt vert rike til all einfald kjærleik, som ved oss verkar takk til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'For tenesta med denne hjelp utfyller ikkje berre det som vantar hjå dei heilage, men ber og rik frukt med takk til Gud ifrå mange,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'då dei ved det sannrøynde hjartelag som denne hjelp syner, må prisa Gud for dykkar lydnad til å sanna Kristi evangelium, og for den einfalde truskapen i samfundet med deim og med alle,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'med di dei og i bøn for dykk lengtar etter dykk for den Guds nåde som er so ovrik yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Gud vere takk for si usegjelege gåva!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Men eg, Paulus, legg dykk på hjarta ved Kristi spaklynde og godlynde, eg som framfor augo på dykk er audmjuk hjå dykk, men djerv mot dykk når eg er fråverande;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'men eg bed um, at eg ved mitt nærvære må sleppa å vera djerv med det frimod som eg tenkjer hugheilt å fara fram med imot sume, som dømer oss som um me ferdast etter kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'For um me ferdast i kjøtet, strider me då ikkje etter kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'For våre stridsvåpn er ikkje kjøtlege, men megtige for Gud til å støyta ned festningar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'med di me støyter ned tankebygningar og all høgd som reiser seg imot kunnskapen um Gud, og tek all tanke til fange under lydnaden mot Kristus');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'og er ferdige til å refsa all ulydnad, når dykkar lydnad fyrst er fullkomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'De ser på det som ligg dykk for augo. Um nokon er viss med seg sjølv at han høyrer Kristus til, han døme då atter ifrå seg sjølv, at liksom han høyrer Kristus til, soleis me og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'For um eg og vil rosa meg noko meir av vår magt, som Herren gav oss til å uppbyggja dykk og ikkje til å riva ned, so vilde eg ikkje verta til skammar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'so ikkje eg skal synast liksom å vilde skræma dykk med brevi mine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'For brevi, segjer dei, er myndige og djerve, men det likamlege nærværet er veikt, og talen ikkje vyrd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Den som segjer slikt, han tenkje då, at slike som me fråverande er i ord i brevi, slike er me og nærverande i gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'For me vågar ikkje å rekna oss til eller likna oss med sume som rosar seg sjølve; men når desse mæler seg med seg sjølve og liknar seg med seg sjølve, er dei fåvituge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Men me vil ikkje rosa oss til umåte, men etter målet av det umkverve som Gud hev sett oss til mål: at me skulde nå radt fram til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'For me tøygjer oss ikkje utyver vårt mål, som um me ikkje hadde nått fram til dykk - for me er då komne fram til dykk med Kristi evangelium -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'med di me ikkje rosar oss til umåte, av framandt arbeid, men hev von um, at når dykkar tru veks, skal me verta ovleg store hjå dykk etter vårt mål,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'so me kann forkynna evangeliet på hi sida åt dykk, og ikkje i eit framandt umkverve rosa oss av det som alt er fullført.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Men den som rosar seg, rose seg i Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'For ikkje den som prisar seg sjølv, held prøva, men den som Herren prisar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Gjev de vilde tola ein grand dårskap av meg! Jau, de skal tola meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'For eg er åbryen på dykk med Guds åbryskap. For eg trulova dykk med ein mann, so eg kunde framstella ei rein møy for Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Men eg ottast for, at liksom ormen dåra Eva med si svikråd, soleis skal og dykkar tankar verta skadde og snudde burt frå den einfalde truskapen mot Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'For um det kjem ein og forkynner ein annan Jesus, som me ikkje hev forkynt, eller de fær ein framand ande, som de ikkje fyrr hev fenge, eller eit framandt evangelium, som de ikkje fyrr hev motteke, so vil de tola det godt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'For eg tenkjer at eg ikkje i nokon ting er mindre mann enn dei ovstore apostlarne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'men um eg enn er ulærd i talen, er eg det då ikkje i kunnskapen; me hev tvert imot alltid synt dykk honom i alle stykke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Eller gjorde eg synd, då eg audmykte meg sjølv so de kunde verta upphøgde, med di eg forkynte dykk Guds evangelium for inkje?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Andre kyrkjelydar hev eg skattlagt, med di eg tok løn til dykkar tenesta, og då eg var hjå dykk og noko vanta meg, var eg ingen til tyngsla;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'for når eg vanta noko, hjelpte brørne som kom frå Makedonia, og i alt vara eg meg for å falla dykk til tyngsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'So visst som Kristi sanning er i meg, so skal denne ros ikkje takast frå meg i Akaia-bygderne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Kvifor då? av di eg ikkje elskar dykk? Det veit Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Men det eg gjer, det vil eg og gjera sidan, so eg kann avskjera deim tilhøve, som søkjer tilhøve, so dei må verta funne liksom me i det som dei rosar seg av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'For desse er falske apostlar, svikfulle arbeidarar, som skaper seg til liksom dei var Kristi apostlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Og det er ikkje underlegt, for Satan sjølv skaper seg um til ein ljosengel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'difor er det ikkje noko stort um hans tenarar og skaper seg um til rettferds tenarar; men deira ende skal høva til deira verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Atter segjer eg: Ingen halde meg for å vera uvitug, men um de gjer det, so tak då imot meg, um og som ein uvitug, so eg og må kunna rosa meg ein grand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Det eg her talar, talar eg ikkje etter Herrens vilje, men liksom i dårskap i denne tillitsame ros.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Sidan mange rosar etter kjøtet, so vil eg og rosa meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'For de toler gjerne uvitingarne, de som er so kloke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'For de toler det, um nokon gjer dykk til trælar, um nokon et dykk upp, um nokon fangar dykk, um nokon upphøgjer seg yver dykk, um nokon slær dykk i andlitet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Med skam segjer eg det, av di me hev vore veike; men det som nokon er djerv i - eg talar i dårskap - det er eg og djerv i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Er dei hebræarar? eg og. Er dei israelitar? eg og. Er dei Abrahams ætt? eg og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Er dei Kristi tenarar? - eg talar som ein galen mann -: eg er det endå meir. Eg hev havt større stræv, fenge fleire slag, vore oftare i fengsel, ofte i livsfåre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Av jødarne hev eg fem gonger fenge fyrti slag so nær som eitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Tri gonger vart eg hudflengd, ein gong steina, tri gonger leid eg skipbrot; eg hev vore eit døger i djupet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Ofte var eg på ferder, i fårar i elvar, i fårar millom røvarar, i fårar millom landsmenner, i fårar millom heidningar, i fårar i by, i fårar i øydemark, i fårar på hav, i fårar millom falske brør,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'i strev og møda, ofte i nattevoka, i svolt og torste, ofte fastande, frosen og naken;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'umfram alt det andre hev eg endå det daglege tillaup, umsuti for alle kyrkjelydarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kven er veik utan at eg vert veik? Kven vert avstygd utan at det brenn i meg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Um eg endeleg skal rosa meg, so vil eg rosa meg av det som høyrer mi vanmagt til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Gud og vår Herre Jesu Kristi Fader, som er velsigna i all æva, han veit at eg ikkje lyg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'I Damaskus let kong Aretas’ landshovding vakta damaskenarbyen, då han vilde gripa meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'og gjenom ein glugg i muren vart eg fira ned i ei korg og slapp ut or hans hender.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Eg lyt rosa meg, endå det ikkje er gagnlegt, men eg kjem no til syner og openberringar av Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Eg kjenner eit menneskje i Kristus - um han var i likamen, det veit eg ikkje, eller utanfor likamen, det veit eg ikkje, Gud veit det - ein som for fjortan år sidan vart rykt inn i den tridje himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Og eg kjenner dette menneskjet, - um han var i likamen eller utanfor likamen, det veit eg ikkje, Gud veit det -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'han vart rykt inn i Paradis og høyrde usegjelege ord, som det ikkje er unnt eit menneskje å tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Av dette vil eg rosa meg, men av meg sjølv vil eg ikkje rosa meg, utan av mi vanmagt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'For um eg vil rosa meg, vert eg ikkje uvitug, for sanning kjem eg til å segja; men eg let det vera, so ingen skal tenkja større um meg, enn som han ser meg eller høyrer av meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Og for at eg ikkje skal ovmoda meg av dei høge openberringar, so er det gjeve meg ein tagg i kjøtet, ein Satans engel, at han skal slå meg, so eg ikkje skal ovmoda meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Um denne bad eg Herren tri gonger, at han måtte vika frå meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Og han sagde til meg: «Min nåde er nok åt deg; for mi kraft vert fullenda i vanmagt.» Helst vil eg difor rosa meg av mi vanmagt, so Kristi kraft kann bu i meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Difor er eg vel til mods midt i vanmagt, i valdsverk, i naud, i forfylgjing, i trengslor for Kristi skuld. For når eg er vanmegtig, då er eg sterk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Eg hev vorte uvitug; de hev tvinga meg til det; for eg skulde havt lovord av dykk; eg var ikkje i noko mindre mann enn dei ovstore apostlar, endå eg er ingen ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Ein apostels teikn vart gjorde hjå dykk i alt tolmod, med teikn og under og kraftige verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'For kva er det som de vart haldne ringare i enn dei andre kyrkjelydar, utan at eg sjølv ikkje var dykk til tyngsla? tilgjev meg denne uretten!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Sjå, tridje gongen er eg buen til å koma til dykk og skal ikkje vera dykk til tyngsla. For eg søkjer ikkje dykkar gods, men dykk sjølve; for borni skal ikkje sanka skattar til foreldri, men foreldri til borni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Men eg vil gjerne ofra, ja, verta ofra for sjælerne dykkar, um eg enn vert mindre elska di meir eg elskar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Men lat so vera at eg ikkje var dykk til tyngsla, men kann henda eg var svikfull og tok dykk med list?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Søkte eg vel vinning av dykk ved nokon av deim som eg sende til dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Eg talde Titus til og sende med honom bror vår. Hev Titus søkt vinning av dykk? For me ikkje fram i den same ånd? ikkje i dei same fotfar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Longe hev de tenkt at det er for dykk me forsvarar oss. Nei, det er for Guds åsyn me talar i Kristus. Men alt til dykkar uppbyggjing, mine kjære!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'For eg ottast for, at når eg kjem, skal eg ikkje finna dykk slike som eg vil, og at eg skal verta funnen av dykk slik som de ikkje vil - at der skal vera kiv, ovund, vreide, stridssykja, baktale, drøsor, ovmod, utstyr,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'at når eg kjem, skal min Gud atter audmykja meg hjå dykk, og eg skal syrgja yver mange av deim som fyrr synda og ikkje hev umvendt seg frå den ureinskap og lauslivnad og used som dei dreiv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Det er no tridje gongen eg kjem til dykk. Ved tvo og tri vitnemål skal kvar sak standa fast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Eg hev sagt det fyreåt og segjer det fyreåt, liksom då eg var nærverande andre gongen, soleis og no då eg er fråverande, til deim som fyrr synda og til alle dei andre, at når eg no kjem att, vil eg ikkje spara,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'sidan de krev eit prov på at Kristus talar i meg, han som ikkje er vanmegtig hjå dykk, men er sterk imillom dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'For um han og vart krossfest i vanmagt, so lever han i Guds kraft; for me og er vanmegtige i honom, men me skal liva med honom i Guds kraft hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Ransaka dykk sjølve, um de er i trui! prøv dykk sjølve! eller kjenner de ikkje dykk sjølve, at Jesus Kristus er i dykk, utan so er at de ikkje held prøva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Men eg vonar at de skal kjenna, at me ikkje er dei som ikkje held prøva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Men me bed til Gud, at de ikkje må gjera noko vondt, ikkje for di at me skal visa oss å halda prøva, men at de skal gjera det gode, men me vera som dei som ikkje held prøva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'For me kann ikkje noko imot sanningi, men berre for sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'For me gled oss når me er vanmegtige, men de sterke; men dette bed me og um, at de må verta fullkomne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Difor skriv eg dette fråverande, so eg, når eg er nærverande, ikkje skal trenga til å vera streng etter den magt som Herren hev gjeve meg til uppbyggjing, ikkje til nedriving.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Elles, brør, gled dykk, vert fullkomne, lat dykk påminna, ver samlyndte, ver fredsame, so skal kjærleiks og freds Gud vera med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Helsa kvarandre med ein heilag kyss! Alle dei heilage helsar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Herren Jesu Kristi nåde og Guds kjærleik og den Heilage Andens samfund vere med dykk alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulus, apostel, ikkje av menneskje og ikkje ved noko menneskje, men ved Jesus Kristus og Gud Fader, som vekte honom upp frå dei daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'og alle brørne som er hjå meg - til kyrkjelydarne i Galatia:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Nåde vere med dykk og fred frå Gud Fader og vår Herre Jesus Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'som gav seg sjølv for våre synder, so han kunde fria oss ut or den noverande vonde verdi etter vår Gud og Faders vilje;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'honom vere æra i all æve! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Eg undrast på at de so snøgt vender dykk frå honom som kalla dykk ved Kristi nåde, til eit anna evangelium,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'endå det ikkje finst noko anna, det er berre sume som forviller dykk og vil forvenda Kristi evangelium.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Men um so me eller ein engel frå himmelen forkynner dykk eit anna evangelium enn det som me hev forkynt dykk, han vere bannstøytt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Som me hev sagt fyrr, so segjer eg no på nytt: Um nokon forkynner dykk eit anna evangelium enn det som de tok imot, han vere bannstøytt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Talar eg no menneskje eller Gud til viljes, eller søkjer eg å gjera menneskje til lags? Vilde eg enno gjera menneskje til lags, var eg ikkje Kristi tenar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Eg kunngjer dykk, brør, at det evangelium som eg hev forkynt, er ikkje menneskjeverk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'for ikkje eg heller fekk det eller lærde det av noko menneskje, men ved Jesu Kristi openberring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'For de hev høyrt mi framferd fyrr, medan eg var jøde, at eg forfylgde Guds kyrkja ovleg hardt og tynte henne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'og i jødedomen gjekk eg lenger enn mange av jamaldringarne mine i mitt folk, med di eg var endå meir ihuga for mine fedre-lærdomar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Men då det tektest honom som valde meg ut alt frå mors liv og kalla meg ved sin nåde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'å openberra sin Son i meg, at eg skulde forkynna evangeliet um honom millom heidningarne, då samrådde eg meg ikkje med kjøt og blod');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'og drog ikkje heller upp til Jerusalem til deim som var apostlar fyre meg; men eg for straks burt til Arabia og vende um att til Damaskus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Sidan, tri år etter, for eg upp til Jerusalem og vilde verta kjend med Kefas, og hjå honom vart eg verande femtan dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Men nokon annan av apostlarne såg eg ikkje, utan Jakob, Herrens bror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Det som eg skriv til dykk - sjå, Gud veit at eg ikkje lyg det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'So kom eg til bygderne i Syria og Kilikia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Men av åsyn var eg ukjend for dei kristne kyrkjelydarne i Judæa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Dei hadde berre høyrt gjete: «Han som fyrr forfylgde oss, han forkynner no den trui som han fyrr øydde ut.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Og dei lova Gud for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Fjortan år etter drog eg upp til Jerusalem att med Barnabas og tok Titus og med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Men eg gjekk upp ei openberring. Og eg lagde fram for deim, serleg for deim som galdt mest, det evangeliet som eg forkynner for heidningarne, um eg vel laupte eller hadde laupe til fåfengs.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Men ikkje Titus jamvel, som var med meg, vart nøydd til å lata seg umskjera, enda han var grækar -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'og det for dei falske brørne skuld, som hadde snikt seg inn og var komne dit til å lura på den fridomen som me hev i Kristus Jesus, so dei kunde få oss under trældom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Men for dei veik me ikkje ein augneblink i nokor etterlæta, for at sanningi i evangeliet skulde standa fast hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Men dei som galdt for å vera noko - kor store dei var, kjem ikkje meg ved; Gud gjer ikkje skil på folk - dei som galdt mest, lagde ikkje på meg noko meir,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'men tvert imot, då dei såg at evangeliet for dei u-umskorne var yverlate til meg, liksom for dei umskorne til Peter');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '- for han som gav Peter kraft til aposteltenesta millom dei umskorne, han gav og meg kraft til det millom heidningarne -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'og då dei lærde å kjenna den nåde som var meg gjeven, so gav Jakob og Kefas og Johannes, som galdt for å vera hovudstolpar, meg og Barnabas si høgre hand til samfund, at me skulde ganga til heidningarne, men dei til dei umskorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'berre at me skulde hugsa på dei fatige, og det hev eg lagt vinn på å gjera.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Men då Kefas kom til Antiokia, sagde eg honom imot beint upp i opne augo, av di det var klaga på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'For fyrr det kom nokre frå Jakob, åt han i lag med heidningarne; men då dei kom, heldt han seg undan og skilde seg ifrå, av di han var rædd for dei umskorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Og med honom hykla dei andre jødarne og, so jamvel Barnabas vart dregen med inn i hyklingi deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Men då eg såg at dei ikkje gjekk beint fram etter sanningi i evangeliet, då sagde eg til Kefas so alle høyrde på: «Når du som er jøde, liver som heidning og ikkje som jøde, kvi nøydar du so heidningarne til å liva som jødar?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Me er fødde jødar og ikkje syndarar, fødde heidningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Men då me skyna at eit menneskje ikkje vert rettferdiggjort ved lovgjerningar, men ved tru på Kristus Jesus, so trudde me og på Kristus Jesus, so me kunde verta rettferdiggjorde av tru på Kristus og ikkje av lovgjerningar; for ved lovgjerningar vert inkje kjøt rettferdiggjort.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Men dersom me, då me freista å verta rettferdiggjorde i Kristus, ogso sjølve vart funne som syndarar - skulde so Kristus vera ein tenar for synd? Nei, langt ifrå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'For dersom eg byggjer upp att det same som eg reiv ned, so syner eg meg sjølv som ein lovbrjotar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'For eg er ved lovi daud for lovi, so eg kann liva for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Eg er krossfest med Kristus, eg liver ikkje sjølv meir, men Kristus liver i meg, og det livet eg no liver i kjøtet, det liver eg i trui på Guds son, som elska meg og gav seg sjølv for meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Eg mismæter ikkje Guds nåde; for dersom rettferd er å vinna ved lovi, so døydde Kristus utan grunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Å, de uvituge galatarar! kven hev trylt dykk, de som hev fenge Jesus Kristus måla for augo som krossfest?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Berre det vil eg få vita av dykk: Fekk det Anden ved lovgjerningar eller ved å høyra trui forkynt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Er de so uvituge? De tok til i ånd; vil de no fullenda i kjøt?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'So mykje hev de røynt til unyttes? - um det då elles er til unyttes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Og han som gjev dykk Anden og gjer kraftverk millom dykk, gjer han det ved lovgjerningar eller ved å forkynna trui?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Liksom Abraham trudde Gud, og det vart rekna honom til rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Difor skal de vita, at dei som hev tru, dei er Abrahams born.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Men Skrifti såg fyreåt at Gud vilde gjera heidningarne rettferdige ved tru, og gav so Abraham fyreåt det fagnadbodet: «I deg skal alle folkeslag verta velsigna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'So vert då dei som hev tru, velsigna med den truande Abraham.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'For so mange som held seg til lovgjerningar, dei er under forbanning; for det stend skrive: «Forbanna er kvar den som ikkje held ved i alt det som stend skrive i lovboki, so han gjer etter det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Men at ingen vert rettferdiggjord for Gud ved lovi, det er audsynlegt; for «den rettferdige, ved tru skal han liva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Men lovi hev ingen ting med trui å gjera, men «den som gjer so, skal liva ved det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristus kjøpte oss frie frå forbanningi av lovi, då han vart ei forbanning for oss - for det er skrive: «Forbanna er kvar den som heng på eit tre» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'so velsigningi åt Abraham kunde koma yver heidningarne i Kristus Jesus, so me ved trui kunde få Anden, som var oss lova.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Brør! eg talar på menneskjevis. Ingen gjer då ei pakt av eit menneskje ugild eller legg noko til etter ho er stadfest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Men lovnaderne vart gjevne til Abraham og hans ætt; han segjer ikkje: «Og ættingarne» liksom um mange, men som um ein: «Og di ætt», og det er Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Det eg vil segja, er dette: Ei pakt som fyreåt er stadfest av Gud, henne kann lovi, som vart gjevi fire hundrad og tretti år seinare, ikkje gjera ugild, so ho skulde gjera lovnaden til inkjes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'For er arven av lov, so er han ikkje meir av lovnad; men Gud gav Abraham honom ved lovnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Kva skulde so lovi til? Ho vart sett attåt for misgjerderne skuld, til dess den ætti kom som lovnaden galdt um - tilskipa av englar, ved ein millommanns hand;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'men ein millommann er ikkje berre for ein; men Gud er ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Er so lovi imot Guds lovnader? Langt ifrå! for var det gjeve ei lov som hadde magt til å gjera livande, so kom rettferdi verkeleg av lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Men Skrifti hev stengt alt inn under synd, so det som var lova, skulde ved tru på Jesus Kristus verta gjeve deim som trur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Men fyrr trui kom, vart me haldne innestengde i varetekt under lovi til den tru som skulde openberrast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'So hev då lovi vorte vår tuktemeister til Kristus, so me skulde verta rettferdiggjorde av tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Men no, då trui er komi, er me ikkje lenger under tuktemeisteren;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'for de er alle Guds born ved trui på Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'For de, so mange som er døypte til Kristus, de hev iklædt dykk Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Her er ikkje jøde eller grækar, her er ikkje træl eller fri mann, her er ikkje mann og kvinna; for de er alle ein i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Men høyrer de Kristus til, so er de og Abrahams ætt, ervingar etter lovnaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Men eg segjer: So lenge ervingen er barn, er det ingen skilnad på honom og trælen, endå han er herre yver alt saman;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'men han er under uppsynsmenner og rådsmenner til den tidi faren fyreåt hev fastsett.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Soleis var me og, so lenge me var born, trælbundne under barnelærdomen til verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Men då tidi var fullkomi, sende Gud Son sin, fødd av ei kvinna, fødd under lovi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'so han kunde kjøpa deim frie, som var under lovi, so me kunde få barneretten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Men av di de er søner, hev Gud sendt inn i hjarto våre sin sons Ande, som ropar: «Abba, Fader!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'So er du då ikkje lenger træl, men son. Men er du son, so er du og erving ved Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Men den tid de ikkje kjende Gud, træla de under dei gudar som i røyndi ikkje er gudar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Men no, då de kjenner Gud og - det som meir er - er kjende av Gud, kor kann de då venda atter til den veike og fatige barnelærdomen? Vil de atter å nyo træla under honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'De tek vare på dagar og månader og tider og år;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'eg ottast for dykk, at eg kann henda fåfengt hev gjort meg møda med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Vert liksom eg, for eg er liksom de; brør! eg bed dykk; de hev ingen urett gjort meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Men de veit at det var på grunn av ei vanhelsa i kjøtet, at eg fyrste gongen kom til å forkynna dykk evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'og endå mitt kjøt kunde freista dykk til det, vanvyrde de meg ikkje og støytte meg ikkje burt; men de fagna meg som ein Guds engel, ja, som Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Kor de prisa dykk sæle den gongen! for det vitnar eg um dykk, at um det hadde vore mogelegt, so hadde de rive ut augo dykkar og gjeve meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Og so hev eg vorte dykkar fiende ved å segja dykk sanningi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Dei syner ein ihuge for dykk som ikkje er god; men dei vil stengja dykk ute, so de skal vera ihuga for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Men det er godt å vera ihuga for det gode alltid, og ikkje berre når eg er hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mine born, som eg atter føder med sår verk, til dess Kristus fær skapnad i dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Eg skulde ynskja eg var hjå dykk no og kunde brigda mi røyst; for eg er i vanråd med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Seg meg, de som vil vera under lovi, høyrer de ikkje lovi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'For det stend skrive at Abraham hadde tvo søner, ein med trælkvinna og ein med den frie kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Men son åt trælkvinna er fødd etter kjøtet, men son åt den frie kvinna etter lovnaden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'I dette ligg det ei djupare meining under; for desse kvinnorne er tvo pakter: den eine frå Sinaifjellet, som føder til trældom, dette er Hagar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'for «Hagar» er Sinaifjellet i Arabia og svarar til det Jerusalem som no er; for det er i trældom med borni sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Men det Jerusalem som er der uppe, er fritt, og det er mor vår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'For det stend skrive: «Ver glad, du barnlause, som ikkje føder; kved i og ropa, du som ikkje hev barnerider! for borni hennar som er einsleg, er mange fleire enn hennar som hev mannen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Men me, brør, er born etter lovnaden, liksom Isak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Men liksom den gongen han som var fødd etter kjøtet, forfylgde honom som var fødd etter åndi, soleis er det no og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Men kva segjer Skrifti? «Driv ut trælkvinna og son hennar; for son åt trælkvinna skal slett ikkje taka arv med son åt den frie kvinna.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'So er me då, brør, ikkje born åt trælkvinna, men åt den frie kvinna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Til fridom hev Kristus frigjort oss; statt difor faste og lat deim ikkje få dykk inn att under trældoms ok!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Sjå, eg, Paulus, segjer dykk, at um de let dykk umskjera, so vil Kristus inkje gagna dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Atter vitnar eg for kvart menneskje som let seg umskjera, at han er skuldig til å halda heile lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'De som vil verta rettferdiggjorde ved lovi, de er skilde frå Kristus, de er falne ut or nåden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'For i trui ventar me i Anden på det som rettferdi gjev oss von um;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'for i Kristus Jesus gjeld korkje umskjering eller fyrehud noko, men berre tru som er verksam i kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'De heldt godt fram; kven hindra dykk frå å lyda sanningi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Denne yverteljingi er ikkje frå honom som kalla dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Ein liten surdeig syrer heile deigen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Eg hev den tiltru til dykk i Herren, at de inkje anna vil tenkja. Men den som forviller dykk, han skal få sin dom, kven han so er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Men eg, brør, um eg enno forkynner umskjering, kvi vert eg endå forfylgd? då er vel krossens støytestein burtteken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Gjev dei måtte skjera seg sjølve sund, dei som eggjar dykk upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'For de, brør, er kalla til fridom. Bruk berre ikkje fridomen til høve for kjøtet; men ten kvarandre i kjærleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'for heile lovi er uppfyllt i eitt bod, i dette: «Du skal elska næsten din som deg sjølv!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Men dersom de bit og et kvarandre, so sjå til at de ikkje et kvarandre upp!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Men eg segjer: Ferdast i Anden, so skal de ikkje fullføra kjøtsens lyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'For kjøtet er huga tvert imot Anden, men Anden imot kjøtet; for desse stend imot kvarandre, so de ikkje skal gjera det som de vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Men dersom de vert drivne av Anden, då er de ikkje under lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Men kjøtsens gjerningar er openberre, slike som: Utukt, ureinskap, lauslivnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'avgudsdyrking, trolldom, fiendskap, kiv, ovund, vreide, stridssykja, tvidrag, sundringar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'misunning, mord, drykk, svir og meir slikt; um dette segjer eg dykk fyreåt, likesom eg fyrr hev sagt, at dei som fer med slikt, skal ikkje erva Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Men Andens frukt er kjærleik, gleda, fred, langmod, mildskap, godleik, truskap,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, '[Stu21: 22] spaklynde, fråhald. [Stu21: 23] Mot slike er ikkje lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Men dei som høyrer Kristus Jesus til, dei hev krossfest kjøtet med fysnorne og lysterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Liver me i Anden, so lat oss og ferdast i Anden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Lat oss ikkje søkja fåfengd æra, so me eggjar kvarandre og ovundar kvarandre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Brør! um og eit menneskje vert fanga av nokor synd, so må de som er åndelege, retta på honom med spaklyndes ånd; men sjå deg sjølv fyre, at ikkje du og skal vert freista!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Ber byrderne for kvarandre, og uppfyll soleis Kristi lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'For dersom nokon tykkjest vera noko og er då ingen ting, so dårar han seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Men kvar skal prøva si eigi gjerning, og so skal han hava ros etter det han sjølv er, og ikkje etter likning med den andre;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'for kvar skal bera si eigi byrd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Den som vert upplærd i ordet, skal gjeva den som lærer honom alt godt saman med seg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Far ikkje vilt! Gud let seg ikkje spotta; for det som eit menneskje sår; det skal han og hausta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'For den som sår i sitt kjød, skal hausta tjon av kjøtet; men den som sår i Anden, han skal hausta ævelegt liv av Anden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Men lat oss ikkje verta trøytte av å gjera det gode! for i si tid skal me hausta, berre me ikkje trøytnar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Lat oss då, medan me hev høve til det, gjera det gode mot alle, men mest mot brørne i trui!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Sjå kor store bokstavar eg skriv med til dykk med mi eigi hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'So mange som vil synast gode etter kjøtet, dei nøyder dykk til å verta umskorne, berre for di at dei ikkje skal verta forfylgde for Kristi kross.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'For ikkje ein gong dei som vert umskorne, held lovi sjølve; men dei vil at de skal verta umskorne, so dei kann rosa seg av dykkar kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Men det vere langt ifrå meg å rosa meg av anna enn av vår Herre Jesu Kristi kross; for honom er verdi krossfest for meg, og eg for verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'For korkje umskjering eller fyrehud er noko, men berre ein ny skapning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Og so mange som gjeng fram etter denne rettesnor, fred og miskunn vere yver deim og yver Guds Israel!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Heretter må ingen gjera meg bry! for eg ber Jesu merke på min likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Vår Herre Jesu Kristi nåde vere med dykkar ånd, brør! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, Jesu Kristi apostel ved Guds vilje, til dei heilage i Efesus som trur på Kristus Jesus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Lova vere Gud og vår Herre Jesu Kristi Fader, som hev velsigna oss med all åndeleg velsigning i himmelen i Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'liksom han valde oss ut i honom, fyrr verdi vart grunnlagd, at me skulde vera heilage og ulastelege for hans åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'med di han i kjærleik fyreåt etla oss til barnekår hjå seg sjølv ved Jesus Kristus etter si frie vilje-rådgjerd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'til lov for sin herlege nåde, som han gav oss i honom som han elskar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'I honom hev me utløysingi ved hans blod, forlating for synderne, etter rikdomen av hans nåde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'som han gav oss rikleg i all visdom og vitsemd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'då han kunngjorde oss løyndomen um sin vilje etter si frie rådgjerd, som han fyresette seg med seg sjølv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'um eit hushald han vilde skipa når tiderne var fullkomne, nemleg at han atter vilde sameina alt til eitt i Kristus, både det som er i himmelen, og det som er på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Og i honom hev me og fenge arvlut, etter at me fyreåt var etla dertil etter hans fyresetning som verkar alt etter si vilje-rådgjerd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'so me skulde vera hans herlegdom til lov, me som fyreåt hadde vona på Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Og i honom hev de og, då de hadde høyrt sannings-ordet, evangeliet um dykkar frelsa - i honom hev de og, då de hadde teke ved trui, fenge til innsigle den Heilage Ande, som var oss lova,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'han som er pantet på vår arv til hans eigedomsfolks utløysing, hans herlegdom til lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Difor, sidan eg høyrde um dykkar tru på Herren Jesus og um dykkar kjærleik til alle dei heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'so held eg ikkje upp med å takka for dykk når eg kjem dykk i hug i mine bøner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'at vår Herre Jesu Kristi Gud, herlegdomens Fader, må gjeva dykk visdoms og openberrings Ande til kunnskap um seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'og gjeva dykkar hug upplyste augo, so de kann kjenna kva von det er han hev kalla dykk til, og kor rik på herlegdom hans arv er ibland dei heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'og kor yvervættes stor hans magt er for oss som trur, etter verknaden av hans velduge kraft,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'som han synte på Kristus, då han vekte honom upp frå dei daude og sette honom ved si høgre hand i himmelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'høgt yver all magt og yverråd og alt velde og herredøme og yver kvart namn som vert nemnt, ikkje berre i denne verdi, men og i den tilkomande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'og han lagde alt under hans føter og gav honom som hovud yver alle ting åt kyrkja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'som er hans likam, fyllt av honom som fyller alt i alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Ogso dykk hev han gjort livande, de som var daude i dykkar misgjerningar og synder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'som de fordom ferdast i etter tidarfaret i denne verdi, etter hovdingen yver hermagti i lufti, den åndi som no verkar i borni til vantrui,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'og millom deim ferdast og me alle fordom i vårt kjøts lyster, då me gjorde det som kjøtet og tankarne vilde, og var av naturi vreidens born liksom dei andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Men Gud, som er rik på miskunn, hev for sin store kjærleik skuld, som han elska oss med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'gjort oss livande med Kristus, endå me var daude i våre misgjerningar - av nåde er de frelste! -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'og vekt oss upp med honom og sett oss med honom i himmelen, i Kristus Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'so han i dei komande tider kunde visa den ovstore rikdomen av sin nåde ved godleik imot oss i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'For av nåde er de frelste, ved tru, og det ikkje av dykk, det er Guds gåva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ikkje av gjerningar, so ikkje nokon skal rosa seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'For me er hans verk, skapte i Kristus Jesus til gode gjerningar, som Gud fyreåt emna til, so me skulde ferdast i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Kom difor i hug, at de som fordom var heidningar i kjøtet og var kalla fyrehud av det dei kallar umskjering, den på kjøtet, som vert gjord med handi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'at de på den tid var utan Kristus, utestengde frå Israels borgarskap og framande for pakterne med deira lovnad, utan von og utan Gud i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Men no, i Kristus Jesus er de som fordom var langt burte, komne nær til ved Kristi blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'For han er vår fred, han som gjorde dei tvo til eitt og braut ned det gjerdet som var skilveggen, fiendskapen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'då han ved sitt kjøt avlyste den lovi som kom med bod og fyresegner, so han ved seg sjølv kunde skapa dei tvo til eitt nytt menneskje, med di han gjorde fred,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'og forlika deim båe tvo i ein likam med Gud ved krossen, då han på denne slo fiendskapen i hel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Og han kom og forkynte fred for dykk som var langt burte, og fred for deim som var nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'For ved han hev me båe tvo i ein Ande tilgjenge til Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'So er de no ikkje lenger framande og utlendingar, men medborgarar med dei heilage og Guds husfolk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'uppbygde på apostel- og profetgrunnvollen, men Jesus Kristus er sjølv hyrnesteinen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'som kvar bygning vert samanbunden ved og veks upp til eit heilagt tempel i Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'og i honom vert de og uppbygde med dei andre til ein Guds bustad i Anden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'For den skuld bøygjer eg mine kne, eg, Paulus, Kristi Jesu fange for dykk heidningar -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'um de elles hev høyrt um hushaldet med den Guds nåde som eg hev fenge for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'at han ved openberring kunngjorde meg den løyndomen so som eg ovanfor hev skrive med få ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'so de av det, når de les det, kann sjå mitt skyn på Kristi løyndom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'som i forne tidebolkar ikkje hev vorte kunngjord for menneskjeborni, so som han no er openberra for hans heilage apostlar og profetar ved Anden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'at heidningarne er medervingar og høyrer med til likamen og hev lut med i lovnaden i Kristus Jesus ved evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'det som eg vart tenar for etter den Guds nådegåva som eg hev fenge ved verknaden av hans magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Eg, den aller ringaste av alle dei heilage, fekk denne nåden, å forkynna heidningarne evangeliet um Kristi uransakelege rikdom');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'og upplysa alle um korleis hushaldet er med den løyndomen som frå ævelege tider hev vore løynd i Gud, som hev skapt alle ting,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'for di at Guds mangfaldige visdom no gjenom kyrkja skulde verta kunngjord for magterne og herredømi i himmelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'etter den fyresetning frå ævelege tider som han fullførde i Kristus Jesus, vår Herre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'han som me hev fenge fritt mod ved og tilgjenge med tillit ved trui på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Difor bed eg at de ikkje må tapa modet ved dei trengslor eg lid for dykk, og som er dykkar æra. -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'For den skuld bøygjer eg mine kne for Faderen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'som er den rette fader for alt som heiter barn i himmelen og på jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'at han etter rikdomen av sin herlegdom må gjeva dykk å verta styrkte med kraft ved hans Ande i dykkar indre menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'at Kristus må bu ved trui i dykkar hjarto, [Stu21: 18] so de, rotfeste og grunnfeste i kjærleik,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'må magtast å fata med alle dei heilage, kva breidd og lengd og dypt og høgd det er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'og kjenna Kristi kjærleik, som gjeng yver all kunnskap, so de kann verta fyllte til all Guds fylla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Men honom som er megtig til å gjera yver alle ting, ovlangt yver det som me bed um eller skynar, etter den kraft som er verksam i oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'honom vera æra i kyrkja og i Kristus Jesus gjenom alle ætter i alle ævor! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Eg legg dykk då på hjarta, eg den bundne i Herren, at de må ferdast so som verdigt er for det kallet som de vart kalla med,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'med all audmykt og spaklynde, med langmod, so de toler kvarandre i kjærleik');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'og legg vinn på å halda Andens einskap i fredsens samband:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Ein likam og ein Ande, liksom de og er kalla med ei von i dykkar kall,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'ein Herre, ei tru, ein dåp,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'ein Gud og Fader til alle, han som er yver alle og gjenom alle og i alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Men kvar og ein av oss hev fenge nåden etter det målet som Kristi gåva vert mælt med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Difor segjer Skrifti: «Han for upp i det høge og førde burt fangar og gav menneski gåvor.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Men det at han for upp, kva er det, utan at han og fyrst for ned til lægderne på jordi?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Han som for ned, han er den same som for upp yver alle himlar, for at han skulde fylla alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Og det er han som gav oss sume til apostlar, sume til profetar, sume til evangelistar, sume til hyrdingar og lærarar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'so dei heilage kunde verta fullt tilbudde til å gjera tenesta, til å byggja upp Kristi likam,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'til dess me alle saman når fram til einskapen i trui og i kjennskapen til Guds Son, til mogen manndom, til aldersmålet for Kristi fylla,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'so me ikkje lenger skal vera umynduge og lata oss kasta og driva um av kvar lærdoms vind ved meinspel av menneski, ved sløgd i illråder som dei villfarande finn på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'men at me, true mot sanningi i kjærleik, i alle måtar skal veksa upp til honom som er hovudet, Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'so heile likamen, samanknytt og samanfest ved kvart band som han gjev, veks sin vokster som likam ut ifrå honom til si uppbyggjing i kjærleik, alt etter den verksemd som er tilmælt kvar lem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Dette segjer eg då og vitnar i Herren, at de ikkje lenger må ferdast som heidningarne ferdast i sin hugs fåfengd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'formyrkte i sin tanke, framande vortne for Guds liv ved den vankunna som er i deim for deira forherde hjarto skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'med di dei hev vorte tykkjelause og hev gjeve seg til ulivnad, til all ureinskaps gjerd med havesykja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Men de hev ikkje lært soleis um Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'um de elles hev høyrt um honom og er upplærde i honom, so som sanning er i Jesus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'at de etter dykkar fyrre livsferd skal leggja av det gamle menneskje, som vert tynt ved dei dårande lyster,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'men verta uppnya ved Anden i dykkar hug');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'og klæda dykk i det nye menneskje, som er skapt etter Gud med den rettferd og heilagdom som sanningi verkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Legg difor av lygni og tala sanning kvar med sin næste, av di me er kvarannans lemer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Vert de vreide, so synda ikkje! Lat ikkje soli ganga ned yver dykkar harm!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Og gjev ikkje djevelen rom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Den som stal, stele ikkje lenger, men arbeide heller og gjere noko godt med sine hender, so han kann hava noko å gjeva til dei trengande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Ingen roten tale koma ut or dykkar munn, men slik tale som er god til naudsynleg uppbyggjing, so det må vera til gagn for deim som høyrer på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'og gjer ikkje Guds Heilage Ande sorg, han som de hev fenge til innsigle til utløysingsdagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'All illska og villska og vreide og skriking og spotting vere langt ifrå dykk liksom all vondskap!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Men ver gode mot kvarandre, miskunnsame, so de tilgjev kvarandre, liksom og Gud hev tilgjeve dykk i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Vert difor Guds etterfylgjarar som hans kjære born,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'og ferdast i kjærleik, liksom Kristus elska oss og gav seg sjølv for oss til ei gåva og eit offer, Gud til ein hugleg ange!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Men utukt og all ureinskap eller havesykja må ikkje eingong verta nemnde millom dykk, so som det sømer seg for heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'og skjemdarferd og dårlegt svall og lauslyndt skjemt, som alt saman er usømelegt, men heller takksegjing!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'For dette veit de og skynar, at ingen horkar eller urein eller girug - som er ein avgudsdyrkar - hev arv i Kristi og Guds rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Lat ingen dåra dykk med tome ord! for av slike ting kjem Guds vreide yver dei vantruande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Hav difor ingen ting saman med deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'For de var fordom myrker, men no er de ljos i Herren; ferdast som born av ljoset');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '- for frukti av ljoset syner seg i all godleik og rettferd og sanning -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'so de prøver kva som er Herren til hugnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'og hav inkje samlag med dei fruktlause gjerningar av myrkret; men refs deim heller!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'For det som løynlegt vert gjort av deim, er det skamlegt endå berre å tala um;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'men når det vert refst, vert det alt saman openberra av ljoset; for alt som vert openberra, er ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Difor segjer skrifti: «Vakna, du som søv, og statt upp frå dei daude, og Kristus skal lysa for deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Sjå difor til korleis de kann ferdast varleg, ikkje som uvise, men som vise,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'so de kjøper den laglege tid; for dagarne er vonde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Ver difor ikkje uvituge, men skyna kva Herrens vilje er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Og fyll dykk ikkje med vin, som det er skamløysa i, men vert fyllte med Anden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'so de talar til kvarandre med salmar og lovsongar og åndelege visor og syng og leikar i dykkar hjarto for Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'og alltid takkar Gud og Faderen for alle ting i vår Herre Jesu Kristi namn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'og er kvarandre undergjevne i age for Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'De konor, ver dykkar eigne menn undergjevne som Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'For mannen er hovudet for kona, liksom Kristus er hovudet for kyrkja, han som er frelsaren for sin likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Men liksom kyrkja er Kristus undergjevi, so skal og konorne vera sine eigne menner undergjevne i alle ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'De menner, elska konorne dykkar, liksom Kristus elska kyrkja og gav seg sjølv for henne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'so han kunde helga henne, med di han reinsa henne ved vatsbadet i ordet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'so han kunde framstella kyrkja for seg i herlegdom, utan flekk eller rukka eller noko slikt, men so ho kunde vera heilag og ulasteleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Soleis er mennerne skuldige til å elska konorne sine som sine eigne likamar. Den som elskar si kona, elskar seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'For aldri hev nokon hata sitt eige kjøt, men han føder og fjelgar det, liksom Kristus gjer med kyrkja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'for me er lemer på hans likam.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Difor skal mannen skiljast med far og mor og halda seg hjå kona si, og dei tvo skal vera eitt kjøt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Denne løyndomen er stor - men eg tenkjer på Kristus og kyrkja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Men de og skal elska kvar si kona som seg sjølv, og kona hava age for mannen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'De born, lyd dykkar foreldre i Herren, for det er rett!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '«Heidra far din og mor di» - dette er det fyrste bodet med lovnad -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '«at det må ganga deg vel, og du må leva lenge i landet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Og de feder, arga ikkje dykkar born, men fostra deim upp i Herrens tukt og påminning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'De tenarar, ver lyduge mot dykkar herrar etter kjøtet med age og otte i dykkar hjartans einfelde som mot Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ikkje med augnetenesta, liksom dei som vil tekkjast menneskje, men som Kristi tenarar, so de gjer Guds vilje av hjarta');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'og godviljugt tener som for Herren og ikkje som for menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'då de veit, at kva godt kvar gjer, det skal han få att av Herren, anten han so er tenar eller fri mann.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Og de herrar, gjer det same mot deim, so de let vera å truga; for de veit at både deira og dykkar Herre er i himmelen, og han gjer ikkje skil på folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Elles, vert sterke i Herren og i hans veldes kraft!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Klæd dykk i Guds fulle herbunad, so de kann standa dykk imot djevelens svikråder!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'For me hev ikkje strid mot blod og kjøt, men mot herrevelde, mot magter, mot heimsens herrar, som råder i myrkret i denne tid, mot vondskaps åndeher i himmelrømdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Tak difor Guds fulle herbunad på, so de kann standa imot på den vonde dag og verta standande når de hev vunne yver alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'So statt då umgyrde um dykkar lend med sanning og klædde i rettferds-brynja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'og umbundne på føterne med den tilbunad som evangeliet um freden gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Og tak attåt alt dette tru-skjolden, so de dermed kann sløkkja alle gloande piler frå den vonde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'og tak frelse-hjelmen, og Andens sverd, som er Guds ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'medan de alltid bed i Anden med all bøn og påkalling og er årvakne deri med all trott og bøn for alle dei heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'og for meg med, at det må verta gjeve meg ord når eg opnar min munn, til å forkynna fritt mod løyndomen i evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'den som eg er sendebod for i lekkjor, at eg må tala med frimod um det, soleis som eg bør tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Men at de og kann få vita um mitt tilstand, korleis det gjeng meg, skal Tykikus kunngjera dykk alt, han den kjære bror og true tenar i Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'som eg just difor sender til dykk at de skal få vita korleis det er med oss, og at han kann trøysta dykkar hjarto.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Fred vere med brørne og kjærleik med tru frå Gud Fader og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Nåde vere med alle som elskar vår Herre Jesus Kristus med uforgjengeleg kjærleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus og Timoteus, Kristi Jesu tenarar, til alle dei heilage i Kristus Jesus, som er i Filippi, med tilsynsmenner og tenarar for kyrkjelyden:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Eg takkar min Gud so tidt eg tenkjer på dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'med di eg alltid, kvar gong eg bed, gjer mi bøn for dykk alle med gleda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'på grunn av dykkar samfund med meg i arbeidet for evangeliet frå fyrste dagen og alt til no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Og eg er fullvis um dette, at han som tok til med ei god gjerning i dykk, skal fullføra henne alt til Jesu Kristi dag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'liksom det er rett av meg å tenkja so um dykk alle, etter di eg ber dykk i hjarta både i mine lekkjor, og når eg forsvarar og stadfester evangeliet, sidan de alle er luthavande med meg i nåden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'For Gud er mitt vitne, kor eg lengtar etter dykk alle med Kristi Jesu hjartelag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Og dette bed eg um, at dykkar kjærleik endå må verta alt rikare og rikare på kunnskap og skynsemd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'at de må kunna døma um dei ymse ting, so de kann vera reine og ikkje til meinstøyt til Kristi dag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'fyllte med rettferds frukt, som er verka ved Jesus Kristus, Gud til æra og lov.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Eg vil at de skal vita, brør, at min lagnad heller hev vore til framgang for evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'so det hev vorte kunnigt for heile livvakti og for alle andre, at eg er i lekkjor for Kristi skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'og dei fleste av brørne i Herren hev fenge tiltru til mine lekkjor og dermed fenge endå meir mod til å tala ordet utan otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Sume forkynner vel og Kristus av ovund og kivslyst, men sume og av godvilje;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'desse forkynner Kristus av kjærleik, med di dei veit at eg er sett til å forsvara evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'men hine gjer det av stridssykja, ikkje med rein hug, for dei tenkjer å leggja trengsla til mine lekkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Kva so? Kristus vert då forkynt på kvar måten, anten det no vert gjort for syn skuld eller i sanning, og yver dette gled eg meg, ja, eg skal og heretter få gleda meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'For eg veit at dette skal verta til frelsa for meg ved dykkar bøn og hjelp av Jesu Kristi Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'etter mi lengting og von, at eg ikkje i nokon ting skal verta til skammar, men at Kristus, som alltid, so og no, med alt frimod skal verta herleggjord ved min likam, anten det vert ved liv eller ved daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'For livet det er for meg Kristus, og dauden ei vinning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Men dersom det å liva i kjøtet gjev meg frukt for mi gjerning, so veit eg ikkje kva eg skal velja;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'for eg stend rådvill millom dei tvo ting, med di eg hev hug til å fara herifrå og vera med Kristus, for det er so ovleg mykje betre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Men å verta verande i kjøtet er naudsynlegare for dykkar skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Og då eg er viss på det, so veit eg at eg skal verta i liva og vera hjå dykk alle til dykkar framgang og gleda i trui,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'so dykkar ros kann verta rik i Kristus Jesus ved meg når eg kjem til dykk att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Berre far dykkar livsferd so som verdigt er for Kristi evangelium, so eg, anten eg kjem og ser dykk eller er fråverande, kann høyra um dykk at de stend faste i ein Ande, og med ei sjæl strider med meg for trui på evangeliet');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'og ikkje i nokon ting let dykk skræma av deim som stend i mot; det er for deim ei varsling um undergang, men for dykk um frelsa, og det frå Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'For dykk vart det unnt, for Kristi skuld, ikkje berre å tru på honom, men og å lida for hans skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'med di de hev den same strid som de såg på meg og no høyrer um meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Er det då nokor trøyst i Kristus, er det nokor hugsvaling i kjærleik, er det noko samfund i Anden, er det nokor medkjensla og miskunn:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'so gjer mi gleda fullkomi, so de hev same hug, med di de hev same kjærleiken og samlyndte hev den eine hugen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'ikkje gjer noko av stridssykja eller lyst til tom æra, men i audmykt vyrder kvarandre høgre enn dykk sjølve.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Sjå ikkje kvar på sin eigen bate, men kvar på baten til dei andre og!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Lat dette huglaget vera i dykk, som og var i Kristus Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'han som, då han var i Guds skapnad, ikkje heldt det for eit ran å vera Gud lik,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'men gav sjølv avkall på det og tok ein tenars skapnad på seg, med di han kom i likning med menneskje, og då han i åtferd var funnen som eit menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'nedra han seg sjølv, so han vart lydug alt til dauden, ja til dauden på krossen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Difor hev og Gud storleg upphøgt honom og gjeve honom det namn som er yver kvart eit namn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'so i Jesu namn skal kvart kne bøygja seg, deira som er i himmelen og på jordi og under jordi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'og kvar tunga skal sanna at Jesus Kristus er Herre, til Gud Faders æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Difor, mine kjære, liksom de alltid hev vore lyduge, so arbeid, ikkje berre som i mitt nærvære, men no endå meir i mitt fråvære, på dykkar frelse med age og otte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'For Gud er den som verkar i dykk både å vilja og verka for sin gode vilje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Gjer alt utan murring og tvilsmål,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'so de kann vera lastelause og reine, Guds ulastande born midt i ei ukyndt og rangsnudd ætt, der de syner dykk som ljos i verdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'med di de held fram livsens ord, meg til ros på Kristi dag, at eg ikkje hev laupe til unyttes eller arbeidt til unyttes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Men um eg og vert ofra, medan eg gjer altartenesta og ber dykkar tru fram til offer, so gled eg meg og gled meg saman med dykk alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Gled og de dykk like eins, og gled dykk saman med meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Eg hev den voni i Herren Jesus, at eg snart kann senda Timoteus til dykk, so eg og kann verta glad i hug, når eg fær vita korleis det er med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'For eg hev ingen med slikt eit lynde, som so ærleg kann hava umsut for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'For dei søkjer alle sitt eige, ikkje det som høyrer Jesus Kristus til;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'men hans prøvde truskap kjenner de, at liksom ein son tenar far sin, so hev han tent med meg for evangeliet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Honom vonar eg då å kunna senda straks når eg ser utgangen på saki mi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Men eg hev den tillit i Herren at eg og sjølv skal koma snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Eg fann det naudsynleg å senda til dykk Epafroditus, min bror og medarbeidar og medstridsmann og dykkar sendemann og tenar til hjelp for mi trong,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'av di han lengta etter dykk alle, og var ottefull for di de hadde høyrt at han var sjuk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'For han var verkeleg sjuk og dauden nær; men Gud gjorde miskunn mot honom, ja, ikkje berre mot honom, men mot meg og, so eg ikkje skulde hava sorg på sorg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Difor sender eg honom so mykje snarare, at de kann gleda dykk ved å sjå honom att, og eg vera meir sutlaus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Tak då imot han i Herren med all gleda, og haldt slike i æra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'For for Kristi gjerning skuld kom han dauden nær, då han ikkje vyrde sitt liv, so han kunde bøta på saknaden av dykk ved tenesta mot meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Elles, mine brør, gled dykk i Herren! Å skriva det same til dykk er meg ikkje til møda, men dykk til styrkjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Sjå hundarne, sjå dei vonde arbeidarar, sjå dei sundskorne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'For me er dei umskorne, me som tener Gud i hans Ande og rosar oss av Kristus Jesus og ikkje lit på kjøt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'endå eg hev det som eg kunde lita på ogso i kjøt. Um ein annan tykkjer at han kann lita på kjøt, so kann eg det endå meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Eg er umskoren den åttande dagen, er av Israels folk, av Benjamins ætt, ein hebræar av hebræarar, i syn på lovi ein farisæar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'i ihuge ein forfylgjar av kyrkjelyden, i rettferd etter lovi ulasteleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Men det som var meg ei vinning, det hev eg for Kristi skuld halde for tap,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'ja, eg held og i sanning alt for tap mot det som er so mykje meir verdt: kunnskapen um Kristus Jesus, min Herre; for hans skuld hev eg tapt det alt saman, og eg held det for skarn, berre eg kann vinna Kristus');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'og verta funnen i honom, ikkje med mi rettferd, den som er av lovi, men med den ved trui på Kristus, rettferdi av Gud på grunn av trui,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'so eg må kjenna honom og krafti av hans uppstoda og samlaget i hans lidingar, med di eg vert lik med honom i hans daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'um eg då kann nå fram til uppstoda frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ikkje so at eg alt hev gripe det eller alt er fullkomen! men eg jagar etter det, um eg og kann gripa det, etter som eg og er gripen av Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Brør, eg trur ikkje um meg sjølv at eg hev gripe det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Men eitt gjer eg: Eg gløymer det som er attanfyre, og tøygjer meg etter det som er framanfyre, og jagar mot målet, til den sigerspris Gud hev kalla oss til der ovan i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'So mange då som er fullkomne, lat oss hava denne tenkjemåte! og um de i noko tenkjer annarleis, so skal Gud og openberra dykk dette;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'berre at me, so langt me er komne, held fram i same faret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Vert mine etterfylgjarar, de og, brør, og sjå på deim som ferdast soleis som de hev oss til fyredøme!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'For det ferdast mange, som eg tidt hev sagt dykk og no endå segjer med tåror, at dei er fiendar av Kristi kross,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'dei som endar med fortaping, som hev buken til sin Gud, og som set si æra i si skjemd, dei som trår etter dei jordiske ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'For vårt borgarsamfund er i himmelen, der me og ventar Herren Jesus Kristus ifrå som frelsar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'han som skal umskapa vår nedrings-likam, so han vert lik hans herlegdoms-likam etter hans kraft til å leggja alle ting under seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Difor, mine brør, som eg elskar og lengtar etter, mi gleda og min krans, statt soleis faste i Herren, de kjære!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Evodia påminner eg, og Syntyke påminner eg um å vera samlyndte i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, eg bed og deg, du som med rette heiter Synzygus, ver deim til hjelp! for dei hev stridt med meg i evangeliet saman med Klemens og mine andre medarbeidarar - deira namn stend i livsens bok.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Gled dykk i Herren alltid! atter vil eg segja det: Gled dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Lat dykkar godlynde verta kjent for alle menneskje! Herren er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Gjer dykk ingi sut for noko ting; men lat i alle ting dykkar ynskje koma fram for Gud i påkalling og bøn med takksegjing!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Og Guds fred, som gjeng yver alt vit, skal vara dykkar hjarto og dykkar tankar i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Elles, brør, alt det som er sant, alt det som er æva verdt, alt det som er rettferdigt, alt det som er reint, alt det som er elskelegt, alt det som hev eit godt namn, kvar ei dygd og alt som priseleg er, det gjeve de gaum etter!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Det som de og hev lært og motteke og høyrt og set hjå meg, gjer det! Og fredsens Gud skal vera med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Eg vart storleg glad i Herren, av di de endeleg ein gong er komne so vidt til velmagt att, at de kunde tenkja på min bate, som de og fyrr tenkte på, men de hadde ikkje høve til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ikkje so at eg segjer dette av trong, for eg hev lært å vera nøgd med det eg hev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Eg veit å liva i ringe kår, eg veit og å liva i nøgd; i alt og i alle ting er eg innvigd, både å verta mett og vera svolten, både å hava nøgdi og hava vanråd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Alt magtast eg i honom som gjer meg sterk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Men endå gjorde de rett i å vera med meg i mi trong.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Men de veit og, de filipparar, at i den fyrste tid evangeliet kom til dykk, då eg for frå Makedonia, kom ingen kyrkjelyd i rekneskap med meg yver gjeve og motteke utan de åleine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'For ogso i Tessalonika sende de meg både ein gong og tvo gonger det eg turvte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ikkje so at eg trår etter gåva; men eg trår etter den frukt som rikleg kjem dykk til gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Men no hev eg fenge alt og hev nøgd, eg hev fullt upp, sidan eg med Epafroditus fekk sendingi frå dykk, ein yndeleg ange, eit offer til fagnad og hugnad for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Og min Gud skal etter sin rikdom fullt upp bøta på all dykkar trong i herlegdom i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Men vår Gud og Fader vere æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Helsa kvar heilag i Kristus Jesus! Brørne hjå meg helsar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Alle dei heilage helsar dykk, mest dei som høyrer til keisarens hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Herren Jesu Kristi nåde vere med dykkar ånd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, Kristi Jesu apostel ved Guds vilje, og broderen Timoteus');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'til dei heilage og truande brør i Kristus i Kolossæ: Nåde vere med dykk og fred frå Gud vår Fader!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Me takkar alltid Gud og vår Herre Jesu Kristi Fader, når me bed for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'sidan me høyrde um dykkar tru på Kristus Jesus og den kjærleik de hev til alle dei heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'for den von skuld som er gøymd åt dykk i himmelen, den som de fyrr hev høyrt um gjenom sannings-ordet i evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'som er kome til dykk, liksom det og er i heile verdi og ber frukt og veks som hjå dykk frå den dag då de høyrde det og lærde å kjenna Guds nåde i sanning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'so som de hev lært av Epafras, vår kjære medtenar, som er ein tru Kristi tenar for dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'som og hev fortalt oss um dykkar kjærleik i Anden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Difor held me, frå den dag me høyrde det, ikkje heller upp med å gjera bøn for dykk og beda um at de må verta fyllte med kunnskap um hans vilje i all åndeleg visdom og skynsemd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'so de må ferdast verdigt for Herren til all hugnad, so de ber frukt og veks i all god gjerning ved kunnskapen um Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'so de vert styrkte med all styrke etter hans herlegdoms kraft til alt tolmod og langmod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'so de med gleda takkar Faderen som gjorde oss duglege til å få arvlut med dei heilage i ljoset,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'han som fria oss ut frå myrkers magt og sette oss yver sin kjære Sons rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'I honom hev me utløysingi, forlating for synderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Og han er eit bilæte av Gud den usynlege, den fyrstefødde framfor all skapning;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'for i honom er alle ting skapte, dei i himmelen og dei på jordi, dei synlege og dei usynlege, anten det so er kongssæte eller herredøme eller magter eller yverråder; alle saman er dei skapte ved honom, og til honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'og han er fyrr enn alle ting, og alle ting stend ved lag i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Og han er hovudet for likamen, som er kyrkja, han som er upphavet, den fyrstefødde av dei daude, for at han i alle måtar skulde vera den fremste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'For i honom tektest det Gud, at heile hans fylla skulde bu,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'og ved honom å forlika alle ting med seg, med di han gjorde fred med blodet på krossen hans - ved honom, anten det so er dei på jordi eller dei i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Ogso dykk som fordom var framande vortne og fiendar ved dykkar huglag, i dei vonde gjerningar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'dykk hev han no forlikt i hans kjøts likam ved dauden, for å stella dykk fram heilage og ulastande og uklandrande for si åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'so framt de vert verande i trui, grunnfeste og trauste, og ikkje let dykk rikka frå den voni evangeliet gjev, det som de hev høyrt, som er forkynt for kvar skapning under himmelen, og som eg, Paulus, vart tenar for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'No gleder eg meg yver mine lidingar for dykk og utfyller i mitt kjøt det som endå vantar i Kristi trengslor, for hans likam som er kyrkja,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'som eg hev vorte tenar til etter det Guds hushald som eg hev fenge millom dykk, det vil segja å fullføra Guds ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'den løyndomen som var duld frå alle tider og ætter vart til, men no er openberra for hans heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'som Gud vilde kunngjera, kor rik på herlegdom denne løyndomen er millom heidningarne, det er Kristus millom dykk, voni um herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Og honom forkynner me, med di me påminner kvart menneskje og lærer kvart menneskje med all visdom, so me kann framstella kvart menneskje fullkome i Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'For dette arbeider eg og, med di eg strider med hans kraft som verkar i meg med styrke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'For eg vil at de skal vita kor stor strid eg hev for dykk og deim i Laodikea og so mange som ikkje hev set mitt andlit i kjøtet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'so deira hjarta må verta trøysta, med di dei vert samanknytte i kjærleik og vinn fram til heile rikdomen av det fullvisse skyn, til kunnskap um Guds løyndom, det er Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'han som alle skattar av visdom og kunnskap er løynde i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Dette segjer eg for at ingen skal dåra dykk med lokkande tale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'For um eg enn i kjøtet er fråverande, er eg like vel i åndi saman med dykk, og ser med gleda dykkar gode skipnad og den faste grunn i dykkar tru på Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Liksom de då tok imot Kristus Jesus som Herren; so ferdast i honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'so at de er rotfeste og vert uppbygde i honom og stadfeste i trui, so som de lærde, rike på henne med takksegjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Sjå til at det ikkje må vera nokon som gjer dykk til herfang med verdsleg visdom og tom dåring etter fråsegner av menneskje, etter barnelærdomen til verdi og ikkje etter Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'For i honom bur heile guddomsfylla likamleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Og de er fyllte i honom, som er hovudet yver all magt og yverråd;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'i honom vart de og umskorne med ei umskjering som ikkje er gjord med hender, ved avklæding av kjøtslikamen, ved Kristi umskjering,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'då de vart gravlagde med honom i dåpen; der vart de og uppvekte med honom ved trui på Guds kraft, han som vekte honom upp frå dei daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Ogso dykk, som var daude i dykkar misgjerningar og dykkar kjøts fyrehud, gjorde han livande med honom, med di han tilgav oss alle våre misgjerningar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'og strauk ut skuldbrevet mot oss, som var skrive med bodord, det som vitna imot oss, og han rudde det undan med di han nagla det til krossen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Han avvæpna magterne og yverråderne og synte deim openberrleg fram då han vann siger yver deim på krossen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Lat difor ingen døma dykk i mat eller drykk eller i saker um høgtid eller nymåne eller kviledag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'desse ting er berre ein skugge av det som skulde koma; men likamen høyrer Kristus til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Lat ingen røva sigersprisen frå dykk, um nokon freistar på det med audmykt og engledyrking, med det han fer med syner, vert ovmodig utan grunn av sin kjøtlege hug');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'og ikkje held fast ved hovudet, han som heile likamen veks Guds vokster ut ifrå, tilhjelpt og samanfest ved sine ledmot og band.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Er de avdøyde med Kristus frå barnelærdomen til verdi, kvi gjev dei dykk då, som um de skulde liva i verdi, slike bod:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '«Du skal ikkje taka, ikkje smaka, ikkje røra»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '- det vil segja slikt som då alt saman er etla til øyding ved bruk - etter bod og lærdomar av menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'som vel hev ord for visdom ved sjølvgjord dyrking og audmykt og vyrdløysa mot likamen, men ikkje ved noko som er æra verdt, berre til mette for kjøtet?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Er de då uppreiste med Kristus, so søk det som er der uppe, der Kristus sit ved Guds høgre hand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Hav hug til det som er der uppe, ikkje til det som er på jordi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'For de er daude, og dykkar liv er løynt med Kristus i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Når Kristus, vårt liv, vert openberra, då skal de og verta openberra med honom i herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'So døyd då dykkar jordiske lemer: Utukt, ureinskap, ovhug, vond lyst og havesykje, som er avgudsdyrking!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'for desse ting kjem Guds vreide yver dei vantruande;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'millom deim ferdast de og fordom, den tid de livde i desse ting;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'men no skal de og leggja deim alle av: Vreide, illska, vondskap, spotting, skamleg tale av dykkar munn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ljug ikkje mot kvarandre, de som hev klædt av dykk det gamle menneskje med dei gjerningar det gjer,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'og iklædt dykk det nye, som vert uppnya til kunnskap etter sin skapars bilæte;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'her er ikkje grækar og jøde, umskjering og fyrehud, barbar, skyte, træl, fri mann, men Kristus er alt og i alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Klæd dykk då, som er Guds utvalde, heilage og kjære i hjarteleg miskunn, godleik, audmykt, spaklynde, langmod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'so de toler kvarandre og tilgjev kvarandre, um nokon hev kjæremål imot nokon! som Kristus tilgav dykk, soleis de og!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Men attåt alt dette klæd dykk i kjærleiken, som er bandet um fullkomenskapen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Og Kristi fred råde i dykkar hjarto, den som de vart kalla til i ein likam, og ver takksame!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Lat Kristi ord bu rikleg hjå dykk, so de lærer og påminner kvarandre i all visdom med salmar og lovsongar og åndelege visor, og syng yndeleg i dykkar hjarto for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Og alt som de gjer i ord eller gjerning, gjer det alt i Herren Jesu namn, med takk til Gud Fader ved honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'De konor, ver mennerne dykkar undergjevne, so som det sømer seg i Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'De menner, elska konorne dykkar og ver ikkje beiske imot deim!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'De born, lyd foreldri dykkar i alle ting! for det er Herren til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'De feder, arga ikkje dykkar born, so dei ikkje skal missa modet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'De tenarar, ver lyduge i alle ting mot herrarne dykkar etter kjøtet, ikkje med augnetenesta, liksom dei som strævar etter å tekkjast menneskje, men i hjartans einfelde, med di de ottast Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Det de gjer, gjer det av hjarta, so som for Herren og ikkje for menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'då de veit at de skal få arven til løn av Herren. Ten Herren Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Men den som gjer urett, skal få den urett att som han gjorde, og det vert ikkje gjort skil på folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'De herrar, gjer imot dykkar tenarar det som rett og rimelegt er, då de veit at de og hev ein Herre i himmelen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Ver trottige i bøni, so de vaker i henne med takksegjing!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Og bed for oss med, at Gud må opna oss ei dør for ordet til å forkynna Kristi løyndom, den som eg og er i lekkjor for,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'so eg kann openberra honom so som eg bør tala.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Ferdast visleg med deim som er utanfor, so de kjøper den laglege tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Dykkar tale vere alltid tekkjeleg, krydda med salt, so de veit korleis de skal svara kvar og ein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Kor det gjeng meg, det skal Tykikus kunngjera dykk alt saman, han min kjære bror og true medhjelpar og medtenar i Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'som eg sender til dykk just for dette, at de skal få vita korleis det er med oss, og han skal trøysta dykkar hjarto,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'saman med Onesimus, den trune og kjære bror, som er ifrå dykk. Korleis det er her, det skal dei kunngjera dykk alt saman.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarkus, min medfange, helsar dykk, og Markus, Barnabas’ systkinbarn, som de fekk påbod um - når han kjem til dykk, so tak imot honom! -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'og Jesus som og er kalla Justus; desse er av dei umskorne dei einaste medarbeidarar for Guds rike som hev vorte meg til hugge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Epafras helsar dykk, han som er ifrå dykk, ein Kristi Jesu tenar som alltid strider for dykk i sine bøner, at de må standa fullkomne og fullvisse i all Guds vilje;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'for eg gjev honom det vitnemål, at han hev mykje stræv for dykk og deim i Laodikea og deim i Hierapolis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Lukas helsar dykk, den kjære lækjaren, og Demas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Helsa brørne i Laodikea, og Nymfas og kyrkjelyden i hans hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Og når dette brevet er lese hjå dykk, so syt for at det og vert lese i kyrkjelyden hjå laodikearane, og at de fær lesa brevet frå Laodikea!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Og seg til Arkippus: «Tak vare på den tenesta som du hev motteke i Herren, so du fullfører henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Helsing med mi, Paulus’, hand: Kom i hug mine lekkjor! Nåden vere med dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus og Silvanus og Timoteus - til kyrkjelyden åt tessalonikarane i Gud Fader og Herren Jesus Kristus: Nåde vere med dykk og fred!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Me takkar alltid Gud for dykk alle, når me kjem dykk i hug i bønerne våre,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'med di me uavlatande minnest dykkar verksemd i trui og arbeid i kjærleiken og tolmod i voni på vår Herre Jesus Kristus for vår Gud og Faders åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'då me er visse på at de er utvalde, brør, de som er elska av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'For vårt evangelium kom ikkje til dykk berre i ord, men og i kraft og i den Heilage Ande og i stor fullvissa, liksom de veit korleis me var millom dykk for dykkar skuld;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'og de vart etterfylgjarar til oss og til Herren då de tok imot ordet i myki trengsla med gleda i den Heilage Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'so de vart eit fyredøme for alle dei truande i Makedonia og Akaia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'For ifrå dykk hev Herrens ord ljoda ut, ikkje berre i Makedonia og Akaia, men alle stader er dykkar tru på Gud komi ut, so me ikkje treng til å tala noko um det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'for dei fortel sjølve um oss, kva inngang me fann hjå dykk, og korleis de vende dykk til Gud frå avgudarne, til å tena den livande og sanne Gud');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'og venta på hans son frå himmelen, honom som han vekte upp frå dei daude, Jesus, som frelsar oss frå den komande vreiden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'For de veit sjølve, brør, um vår inngang hjå dykk, at han ikkje hev vore til fåfengs.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Men endå me fyreåt hadde lide og vorte ille medfarne i Filippi, som de veit, fekk me då frimod i vår Gud til å tala Guds evangelium til dykk i stor strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'For vår forkynning kjem ikkje av villfaring eller av urein hug eller med svik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Men liksom me er haldne verdige av Gud til å få evangeliet yverlate, soleis talar me, ikkje som dei som vil tekkjast menneskje, men Gud, han som prøver hjarto våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'For korkje kom me noko sinn med smeikjande ord, som de veit, eller med fyrebering for havesykja, Gud er vitne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'og ikkje heller søkte me æra av menneskje, korkje av dykk eller av andre, endå me kunde ha kravt vyrdnad som Kristi apostlar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Men me var milde millom dykk: Som ei mor vermer borni ved barmen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'soleis var me i inderleg kjærleik til dykk viljuge til å gjeva dykk ikkje berre Guds evangelium, men og vårt eige liv med, av di de vart oss kjære.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'For de minnest då, brør, vårt stræv og vår møda: Medan me arbeidde natt og dag, so me ikkje skulde vera nokon av dykk til tyngsla, forkynte me Guds evangelium for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'De er vitne, og Gud med, kor heilagt og rettferdigt og ulastande me ferdast hjå dykk, de truande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'liksom de veit kor me påminte kvar og ein av dykk, som ein far borni sine, og lagde dykk på hjarta');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'og bad dykk inderleg at de skulde ferdast so som verdigt er for Gud, som hev kalla dykk til sitt rike og sin herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Difor takkar me og uavlatande Gud for, at då de fekk det Guds ord me forkynte, so tok de imot det, ikkje som eit menneskje-ord, men - som det i sanning er - som eit Guds ord, som og ter seg verksamt i dykk som trur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'For de, brør, hev vorte etterfylgjarar til dei Guds kyrkjelydar som er i Kristus Jesus i Judæa; for de hev og lide det same av dykkar eigne samættingar som dei hev lide av jødarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'som og slo Herren Jesus og profetarne i hel og forfylgde oss og ikkje er Gud til hugnad og stend alle menneskje imot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'då dei meinkar oss i å tala til heidningarne, at dei kann verta frelste - so dei alltid må fylla sitt syndemål. Men vreiden hev endeleg nått deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Men då me, brør, ei liti stund hadde vore skilde frå dykk med åsyn, ikkje med hjarta, so hev me i vår store lengting gjort oss so mykje større umak for å få sjå dykkar åsyn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'for me hev vilja koma til dykk - eg, Paulus, både ein gong og tvo gonger - men Satan hindra oss derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'For kven er vel vår von eller gleda eller heiderskrans? Er ikkje de det og for vår Herre Jesu Kristi åsyn i hans tilkoma?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'For de er vår æra og gleda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Difor, då me ikkje lenger kunde halda det ut, rådde me oss til å verta åleine att i Aten,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'og me sende Timoteus, vår bror og Guds tenar i Kristi evangelium, til å styrkja dykk og påminna dykk um dykkar tru,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'at ikkje nokon skulde verta ustød i desse trengslor. De veit sjølve at me er sette til det;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'for då me var hjå dykk, sagde me dykk fyreåt at me skulde lida trengslor, so som det og gjekk, og som de veit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Difor sende eg og bod, då eg ikkje lenger kunde halda det ut, so eg kunde få vita um dykkar tru, um freistaren skulde ha freista dykk, og vårt arbeid skulde verta til unyttes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Men no, då Timoteus er komen til oss frå dykk og hev bore oss godt bod um dykkar tru og kjærleik, og at de alltid hev oss i venlegt minne og lengtar etter å sjå oss, liksom me etter dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'so er me dermed trøysta yver dykk, brør, i all vår trengsla og naud, ved dykkar tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'For no liver me, so framt de stend faste i Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'For kva takk kann me gjeva Gud att for dykk, for all den gleda som me kjenner yver dykk for vår Guds åsyn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'medan me natt og dag naudbed um å få sjå dykkar åsyn og bøta på det som endå vantar i dykkar tru?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Men han, vår Gud og Fader, og vår Herre Jesus styre vår veg til dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Og dykk gjere Herren fullrådde og ovrike på kjærleik til kvarandre og til alle, liksom me er det mot dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'for at han kann styrkja hjarto dykkar, so de vert ulastelege i heilagdom for vår Gud og Faders åsyn, når vår Herre Jesus kjem med alle sine heilage!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Elles no, brør, bed og påminner me dykk i Herren Jesus, at liksom de hev lært av oss korleis de skal ferdast og tekkjast Gud, som de og gjer, so må de alt meir fremdast deri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'For de veit kva bod me gav dykk ved Herren Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Dette er Guds vilje, dykkar helging: at de skal halda dykk frå utukt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'at kvar og ein av dykk veit å vinna seg sin eigen make i helging og æra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'ikkje med ovhug i lyst, so som heidningarne som ikkje kjenner Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'at ingen skal gjera bror sin uskil eller svik i det som han hev å gjera med honom; for Herren er hemnar for alt slikt, som me og fyrr hev sagt og vitna for dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'For Gud kalla oss ikkje til ureinskap, men til helging.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Den som då mismæter dette, han mismæter ikkje eit menneskje, men Gud, som og gjev sin Heilage Ande i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Men um broderkjærleiken treng de ikkje til at nokon skriv til dykk; for de er sjølve lærde av Gud til å elska kvarandre;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'for de gjer det og mot alle brørne i heile Makedonia. Men me legg dykk på hjarta, brør, at de alt meir må fremdast deri');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'og setja dykkar æra i å liva stilt og taka vare på dykkar eigne saker og arbeida med henderne, som me hev bode dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'so de må ferdast sømeleg med deim som er utanfor, og ikkje trenga til nokon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Men eg vil ikkje, brør, at de skal vera uvitande um deim som er avsovna, so de ikkje skal syrgja liksom dei andre, som ikkje hev nokor von.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'So sant som me trur at Jesus døydde og stod upp, so skal og Gud ved Jesus føra deim som er avsovna saman med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'For dette segjer me dykk med eit ord av Herren, at me som liver, som vert att til dess Herren kjem, ikkje skal koma i fyrevegen for deim som er avsovna;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'for Herren sjølv skal koma ned frå himmelen med bjodande rop, med yverengels røyst og med Guds basun, for dei som er avlidne i Kristus, skal fyrst standa upp;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'so skal me som liver, som vert att, saman med deim verta rykte i skyer upp i lufti til å møta Herren, og so skal me alltid vera med Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'So trøysta då kvarandre med desse ord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Men um tiderne og stunderne treng de, brør, ikkje til at me skriv til dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'for de veit sjølve grant at Herrens dag kjem som ein tjuv um natti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Når dei segjer: «Fred og ingen f re!» då kjem ein brå undergang yver deim, liksom føderidi yver den som er med barn, og dei skal slett ikkje sleppa undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Men de, brør, er ikkje i myrkret, so dagen skulde koma på dykk som ein tjuv;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'for de er alle born av ljoset og born av dagen; me høyrer ikkje natti eller myrkret til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Lat oss difor ikkje sova som dei andre, men lat oss vaka og vera ædrue!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'For dei som søv, dei søv um natti, og dei som drikk seg drukne, dei er drukne um natti;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'men me som høyrer dagen til, lat oss vera ædrue, klædde med den brynja som er tru og kjærleik, og med voni um frelsa som ein hjelm!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'For Gud etla oss ikkje til vreide, men til å vinna frelsa ved vår Herre Jesus Kristus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'han som døydde for oss, so me, anten me vaker eller søv, skal liva saman med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Påminn difor kvarandre, og uppbygg einannan innbyrdes, so som de og gjer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Men me bed dykk, brør, at de skynar på deim som arbeider ibland dykk og er dykkar forstandarar i Herren og påminner dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'og at de vyrder deim storleg høgt i kjærleik for deira gjerning skuld! Haldt fred med kvarandre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Og me legg dykk på hjarta, brør: Påminn dei uskipelege, trøysta dei vanmodige, hjelp dei veike, ver langmodige mot alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Sjå til at ingen gjev nokon vondt att for vondt, men stræva alltid etter det som godt er, både mot kvarandre og mot alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Ver alltid glade!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Bed uavlatande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Takka for alle ting! for dette er Guds vilje i Kristus Jesus til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Sløkk ikkje ut Anden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Mismæt ikkje profetord!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'men prøv alt, hald fast på det gode!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Haldt dykk frå vondt av alle slag!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Men han sjølv, fredsens Gud, helga dykk heilt ut, og gjev at dykkar ånd og sjæl og likam må verta haldne fullkomne, ulastande når vår Herre Jesus Kristus kjem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Han som hev kalla dykk, er trufast, han skal og gjera det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Brør, bed for oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Helsa alle brørne med ein heilag kyss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Eg manar dykk ved Herren, at de let brevet verta lese for alle dei heilage brørne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Vår Herre Jesu Kristi nåde vere med dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus og Silvanus og Timoteus til kyrkjelyden åt tessalonikarane i Gud, vår Fader, og Herren Jesus Kristus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Me er skuldige til å takka Gud alltid for dykk, brør, som sømelegt er, for di dykkar tru veks rikleg, og kjærleiken til kvarandre vert større hjå kvar og ein av dykk alle,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'so at me sjølve rosar oss av dykk i Guds kyrkjelydar for dykkar tolmod og tru i alle dykkar forfylgjingar og dei trengslor som de held ut -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'eit fyrebod um Guds rettferdige dom - for at de skal verta funne verdige til Guds rike, det som de og lid for,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'so sant som det er rettferdigt for Gud å gjeva deim trengsla att som trengjer dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'og gjeva dykk som vert trengde, ro med oss når vår Herre Jesus openberrar seg frå himmelen med sitt veldes englar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'med logande eld, når han tek hemn yver deim som ikkje kjenner Gud, og deim som ikkje lyder vår Herre Jesu evangelium,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'dei som skal lida refsing, ei æveleg fortaping burt frå Herrens åsyn og frå hans veldes herlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'når han kjem på den dagen for å syna seg herleg i sine heilage og underleg i alle dei truande - for vårt vitnemål til dykk vart motteke med tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Difor bed me og alltid for dykk, at vår Gud må finna dykk verdige til kallet og kraftigt fylla dykk med all hug til det gode og verksemd i trui,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'so vår Herre Jesu namn må verta herleggjort i dykk, og de i honom, etter vår Guds og Herren Jesu Kristi nåde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Me bed dykk, brør, vedkomande vår Herre Jesu Kristi tilkoma og vår sameining med honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'at de ikkje so snart må lata dykk villa burt frå vitet eller skræma, korkje ved nokor ånd eller ved nokon tale eller ved noko brev, liksom det skulde vera frå oss, som um Herrens dag alt stod for døri.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Lat ingen dåra dykk på nokon måte! for fyrst lyt fråfallet koma og syndmenneskjet verta openberra, fortapingssonen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'han som set seg imot og upphøgjer seg yver alt som heiter Gud eller heilagdom, so han set seg i Guds tempel og gjev seg sjølv ut for å vera Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Minnest de ikkje at eg sagde dykk dette medan eg endå var hjå dykk?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Og no veit de kva som held att, so han fyrst skal verta openberra i si tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'For løyndomen i lovløysa er alt verksam, berre at den som no held att, vert rudd undan;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'og då skal den lovlause verta openberra, han som Herren Jesus skal tyna med sin munns ande og gjera til inkjes ved openberringi i si tilkoma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Og hans tilkoma gjeng fyre seg etter Satans kraftige verknad med all kraft og teikn og under av lygni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'og med all dåring av urettferdi for deim som vert fortapte, av di dei ikkje tok imot kjærleik til sanningi, so dei kunde verta frelste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Og difor sender Gud deim kraftig villfaring, so dei trur lygni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'so alle dei skal verta dømde, som ikkje hev havt tru til sanningi, men havt hugnad i urettferdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Men me er skuldige til å takka Gud alltid for dykk, brør, som er elska av Herren, for di Gud frå upphavet tok dykk ut til frelsa ved helging av Anden og tru på sanningi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'som han kalla dykk til ved vårt evangelium, til å vinna vår Herre Jesu Kristi herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Difor, brør, stat traust og hald fast ved dei lærdomar som de hev lært anten ved vår tale eller ved brev frå oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Men han vår Herre Jesus Kristus, og Gud, vår Fader, som elska oss og gav oss ei æveleg trøyst og ei god von i nåde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'han trøyste dykkar hjarto og styrkje dykk i all god gjerning og tale!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Elles, brør, bed for oss at Herrens ord må hava framgang og syna seg herlegt liksom hjå dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'og at me må verta utfria frå dei uliklege og vonde menneskje; for trui er ikkje kvar manns sak.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Men Herren er trufast, han skal styrkja dykk og vara dykk frå det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Me hev den tiltru til dykk i Herren, at de både gjer og kjem til å gjera det som me byd dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Men Herren styre dykkar hjarto til å elska Gud og til å venta på Kristus med tolmod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Men me byd dykk, brør, i vår Herre Jesu Kristi namn, at de held dykk frå kvar ein bror som ferdast uskipeleg og ikkje etter den lærdom som de fekk av oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'For de veit sjølve korleis de skal etterfylgja oss; for me livde ikkje uskipeleg millom dykk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'og me åt ikkje heller brød hjå nokon for inkje, men i strev og møda arbeidde me natt og dag, for at me ikkje skulde vera nokon av dykk til tyngsla,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'ikkje for det at me ikkje hev rett til det, men at me kunde gjeva dykk eit fyredøme i oss sjølve, so de skulde etterfylgja oss;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'for då me var hjå dykk, baud me dykk og dette, at um nokon ikkje vil arbeida, skal han heller ikkje eta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Me høyrer nemleg at sume ferdast uskipeleg millom dykk, so dei ikkje arbeider, men fer med slikt som ikkje kjem deim ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Men slike byd og påminner me i Herren Jesus Kristus, at dei skal arbeida i stilla og eta sitt eige brød.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Men de, brør, vert ikkje trøytte av å gjera det som godt er!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Men um nokon ikkje lyder vårt ord her i brevet, so merk dykk honom; hav ikkje samkv me med honom, so han må blygjast!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'og haldt honom ikkje for ein fiende, men påminn honom som ein bror!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Men han, fredsens Herre, gjeve dykk fred alltid i alle måtar! Herren vere med dykk alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Helsing med mi, Paulus’ hand, som er eit merke i kvart brev. Soleis skriv eg:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Vår Herre Jesu Kristi nåde vere med dykk alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, Kristi Jesu apostel etter påbod frå Gud, vår frelsar, og Kristus Jesus, vår von,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'til Timoteus, min egtefødde son i trui: Nåde, miskunn, fred frå Gud Fader og Kristus Jesus, vår Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Som eg bad deg vera att i Efesus, då eg for til Makedonia, for at du skulde bjoda sume folk at dei ikkje skal fara med framand læra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'og ikkje ansa eventyr og endelause ættartal, som heller fører til stridsspursmål enn til å vera Guds hushaldarar i trui: so gjer no det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Men endemålet med bodet er kjærleik av eit reint hjarta og eit godt samvit og ei uskrymta tru,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'som sume hev fare vilt ifrå og vendt seg burt til tomt svall,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'dei som vil vera lovlærarar, endå dei korkje skynar det dei sjølve segjer eller kva det er dei talar so fullvist um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Men me veit at lovi er god, dersom nokon brukar henne på lovleg vis,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'so han veit dette, at lovi ikkje er sett for ein rettferdig, men for lovlause og agelause, ugudlege og syndarar, vanheilage og ureine, fadermordarar og modermordarar, manndråparar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'horkarar, syndarar mot naturi, menneskjerøvarar, ljugarar, meineidarar, og um det elles er noko som er imot den heilsame læra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'etter evangeliet um den sæle Guds herlegdom, det som er meg yverlate.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Eg takkar honom som gjorde meg sterk, Kristus Jesus, vår Herre, at han heldt meg for tru, med di han sette meg til tenesta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'meg som fyrr var ein spottar og forfylgjar og valdsmann, men eg fekk miskunn, av di eg gjorde det uvitande, i vantru,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'og nåden hjå vår Herre viste seg ovleg stor i tru og kjærleik i Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Sant er det ordet og vel verdt å taka imot, at Kristus Jesus kom til verdi for å frelsa syndarar, og millom deim er eg den største;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'men difor fekk eg miskunn, at Jesus Kristus kunde syna alt sitt langmod på meg fyrst, til eit fyredøme for deim som skulde tru på honom til ævelegt liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Men den ævelege konge, den uforgjengelege, usynlege, einaste Gud vere pris og æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Dette bod legg eg deg på hjarta, min son Timoteus, etter dei spådomar som fyrr er sagde um deg, so du i deim skal strida den gode striden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'med di du hev tru og eit godt samvit, som sume hev støytt ifrå seg og lide skipbrot på trui;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'imillom deim er Hymenæus og Aleksander, som eg hev gjeve yver til Satan, so dei skal verta tukta til å lata vera å spotta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Eg påminner framfor alle ting um at det vert gjort bøner, påkallingar, forbøner, takksegjingar for alle menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'for kongar og alle dei som er i yverrådande stand, at me kann liva eit stilt og rolegt liv i all gudleg age og søma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'For dette er godt og tekkjelegt for Gud, vår frelsar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'han som vil at alle menneskje skal verta frelste og koma til å kjenna sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'For ein Gud er det, ein millommann er det og millom Gud og menneskje, det menneskjet Kristus Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'han som gav seg sjølv til løysepening for alle, eit vitnemål i si tid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'og for dette vart eg sett til forkynnar og apostel - eg segjer sanning, eg lyg ikkje - til lærar for heidningarne i tru og sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Eg vil då at mennerne på kvar stad skal beda so, at dei lyfter heilage hender utan vreide og ordstrid,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'like eins og at kvinnorne skal pryda seg med sømeleg klædnad i blygd og æra, ikkje med flettingar og gull eller perlor eller dyr klædebunad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'men som det sømer seg kvinnor som vedkjenner seg gudlegdom, med gode gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Ei kvinna skal lata seg læra i stilla med all lydnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Men eg gjev ikkje ei kvinna lov til å læra eller å bjoda yver mannen, men å vera i stilla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'For Adam vart skapt fyrst, og so Eva;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'og Adam vart ikkje dåra; men kvinna vart dåra og fall i misgjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Men ho skal verta frelst gjenom si barneign, um dei vert standande i tru og kjærleik og helging med æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Det er eit sant ord: Um nokon trår etter eit tilsynsembætte, so hev han lyst til ei gjæv gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Difor skal ein tilsynsmann vera ulastande, mann til ei kvinna, ædrueleg, visleg, verdig, gjestmild, dugleg til å læra frå seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ikkje drikkekjær, ikkje hardhendt, men godlyndt, ikkje stridsam, ikkje pengekjær,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'ein som styrer vel sitt eige hus, og hev lyduge born med all søma');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '- um nokon ikkje veit å styra sitt eige hus, kor kann han då hava umsut for Guds kyrkja? -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'ikkje ein ny-umvend, so han ikkje skal ovmoda seg og falla i djevelens dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Men han skal og hava godt vitnemål av deim som er utanfor, so han ikkje skal få lastord og falla i djevelens snara.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Like eins skal tenarane for kyrkjelyden vera vyrdelege, ikkje tvitunga, ikkje kjære etter mykje vin, ikkje lystne etter låk vinning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'slike som hev løyndomen i trui i eit godt samvit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Dei og skal fyrst verta prøvde; sidan skal dei tena kyrkjelyden, um dei er ulastelege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Like eins skal kvinnorne vera vyrdelege, ikkje baktalande, men ædruelege, true i alle ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Tenarane for kyrkjelyden skal kvar vera mann til ei kona og styra vel sine born og sine eigne hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'For dei som hev tent kyrkjelyden vel, dei vinn seg eit godt støde og stort frimod i trui på Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Dette skriv eg til deg, endå eg vonar å koma snart til deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'men um eg drygjer, at du so skal vita korleis ein skal ferdast i Guds hus, som er kyrkja åt den livande Gud, pilaren og grunnvollen til sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Og som kvar må sanna, stor er den løyndom i gudlegdomen: Han som vart openberra i kjøt, rettferdiggjord i ånd, sedd av englar, forkynt millom folkeslag, trudd i verdi, uppteken i herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Men Anden segjer klårleg, at i dei komande tider skal sume falla frå trui og halda seg til dårande ånder og lærdomar av djevlar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'ved hykling av falske lærarar, som er brennemerkte i sitt eige samvit,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'som forbyd å gifta seg og påbyd å halda seg frå mat, som Gud hev skapt til å verta motteken med takk av deim som trur og hev lært sanningi å kjenna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'For all Guds skapning er god, og inkje er til å vanda, når det vert motteke med takk;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'for det vert helga med Guds ord og bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Når du lærer brørne dette, so er du ein god Jesu Kristi tenar, med di du vert uppfødd med ordi av trui og den gode lærdomen som du hev fylgt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Men haldt deg frå dei vanheilage og kjerringslege eventyr, men tem deg derimot upp i gudlegdom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'For den likamlege tamen er gagnleg til lite, men gudlegdom er gagnleg til alt; med di han hev lovnad for det livet som no er og for det som kjem.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Det ord er sant og all fagning verdt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'For difor både arbeider me og lid hæding, for di me hev sett vår von til den livande Gud, som er frelsar for alle menneskje, mest dei truande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Dette skal du bjoda og læra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Lat ingen vanvyrda deg for din ungdom, men ver eit fyredøme for dei truande i tale, i ferd, i kjærleik, i tru, i reinleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Til dess eg kjem, so legg vinn på fyrelesnaden, på påminningi, på læra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Vanskøyt ikkje den nådegåva som er i deg, som vart gjevi deg ved profetord med handpåleggjing av dei eldste!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Tenk på dette, liv i dette, so din framgang kann vera kunnig for alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Gjev agt på deg sjølv og på læra, haldt ved med det! for når du det gjer, skal du frelsa både deg sjølv og deim som høyrer deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Tala ikkje hardt til ein gamall mann, men påminn honom som ein far, unge menner som brør,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'gamle kvinnor som møder, unge som syster i all reinleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Heidra enkjor som verkeleg er enkjor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Men um ei enkja hev born eller barneborn, so lat deim fyrst læra å visa eit gudlegt huglag imot sitt eige hus og gjeva sine foreldre vederlag, for det er tekkjelegt for Guds åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Men den som verkeleg er enkja og einsleg vorti, ho hev sett si von til Gud og held ved i bøn og påkalling natt og dag;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'men den som liver etter lysterne sine, er livande daud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Og dette skal du bjoda, so dei må vera ulastelege!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Men um nokon ikkje hev umsut for sine eigne og mest for sine husfolk, han hev forneitta trui og er verre enn ein vantruande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Ei enkja kann verta vald, når ho ikkje er yngre enn seksti år, um ho hev vore ein manns kona,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'hev vitnemål for gode gjerningar, hev fostra upp born, hev vist gjestmilda, hev tvætta føterne til dei heilage, hev vore dei naudtrengde til hjelp, hev lagt vinn på all god gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Men vis dei unge enkjor frå deg! for når dei av kjøtleg hug svik Kristus, so vil dei gifta seg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'og hev dermed den dom at dei hev brote si fyrste tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Men attåt dette lærer dei og å ganga yrkjelause og fare ikring i husi, og ikkje berre yrkjelause, men og med drøsor og gagnløysa, med di dei fer med ulikleg tale.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Eg vil difor at unge enkjor skal gifta seg, føda born, styra huset, ikkje gjeva motstandaren tilhøve til lastord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'For sume hev alt vendt seg burt etter Satan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Dersom nokon truande mann eller kvinna hev enkjor, so syta dei for deim, og lata ikkje kyrkjelyden verta tyngd, so han kann syta for dei verkelege enkjor!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Dei eldste som er gode forstandarar, skal ein halda tvifald æra verde, mest deim som arbeider i tale og læra;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'for Skrifti segjer: «Du skal ikkje leggja muleband på ein ukse som treskjer!» og «Ein arbeidsmann er si løn verd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Tak ikkje imot noko klagemål mot ein eldste utan etter tvo eller tri vitne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Deim som syndar, skal du refsa so alle høyrer på, so at og dei andre kann hava otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Eg vitnar for Gud og Kristus Jesus og dei utvalde englar, at du skal taka vare på dette utan fordom, so du ikkje gjer noko av godtykkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Ver ikkje snar til å leggja henderne på nokon, gjer deg ikkje medskuldig i framande synder! Haldt deg sjølv rein!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Drikk ikkje lenger berre vatn, men nøyt lite grand vin for magen din og dine jamlege sjukdomar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Hjå nokre menneskje er synderne openberre og kjem i fyrevegen for deim til dom; men hjå andre fylgjer dei etter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Like eins er dei gode gjerningarne openberre; og dei som det ikkje er so med, kann ikkje verta dulde like vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'So mange som er trælar under oket, skal halda herrarne sine all æra verde, so ikkje Guds namn og læra skal verta spotta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Men dei som hev truande herrar, skal ikkje vanmæta deim for di dei er brør, men skal so mykje heller gjera si tenesta, av di dei som tek imot velgjerningi av deim, er truande og elska. Dette skal du læra og påminna um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Dersom nokon lærer framand læra og ikkje held seg til vår Herre Jesu Kristi heilsame ord og den læra som høver til gudlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'so er han ovmodig, endå han ingen ting skynar, men er sjuk for stridsspursmål og ordkivsmål, som det kjem ovund av og trætta, spotting, vond mistru,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'stendig krangling millom menneskje som er øydelagde i hugen og skilde med sanningi, dei som held gudlegdomen for ein veg til vinning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Ja, gudlegdom saman med nøgsemd er ei stor vinning;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'for me hev ikkje havt noko med oss til verdi, det er då audsynt at me ikkje heller kann føra noko med oss derifrå;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'men når me hev føda og klæde, skal me vera nøgde med det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Men dei som vil verta rike, fell i freisting og snara og mange dårlege og skadelege lyster, som søkkjer menneski ned i undergang og fortaping.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'For pengehugen er ei rot til alt vondt; av trådom deretter hev sume fare vilt frå trui og hev gjenomstunge seg sjølve med mange pinslor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Men du, Guds menneskje, fly frå desse ting! Men trå etter rettferd, gudlegdom, tru, kjærleik, tolmod, spaklynde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Strid den gode striden i trui! grip det ævelege liv, som du vart kalla til og bar fram den gode vedkjenningi for mange vitne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Eg byd deg for Gud, som gjev alle ting liv, og for Kristus Jesus, som vitna den gode vedkjenning for Pontius Pilatus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'at du skal halda bodet uflekka og ulastelegt til vår Herre Jesu Kristi openberring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'som den sæle og einaste megtige Herre skal visa oss i si tid, han som er kongen yver kongarne og herren yver herrarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'han som åleine hev udøyelegdom, som bur i eit ljos som ingen kann koma til, som inkje menneskje hev set eller kann sjå; han hev æra og æveleg magt! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bjod deim som er rike i den noverande verdi, at dei ikkje skal ovmoda seg eller setja si von til den uvisse rikdomen, men til Gud, som gjev oss rikleg alle ting å njota;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'at dei skal gjera godt, vera rike på gode gjerningar, gjevmilde, velgjerdsame,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'so dei legg seg upp ein god grunnvoll for den komande tid, so dei kann gripa det sanne liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Du, Timoteus, tak vare på det som er nedlagt hjå deg, og vend deg frå det vanheilage tome svall og dei motsegner av den kunnskap, som falskeleg vert kalla so,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'som sume vedkjenner seg og hev fare vilt i trui! Nåden vere med deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, ved Guds vilje Kristi Jesu apostel til å forkynna lovnaden um livet i Kristus Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'til Timoteus, min kjære son: Nåde, miskunn, fred frå Gud Fader og Kristus Jesus, vår Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Eg takkar Gud, som eg alt frå forfederne tener i eit reint samvit, liksom eg uavlatande kjem deg i hug i mine bøner natt og dag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'og når eg hugsar dine tåror, lengtar eg etter å sjå deg, so eg kann verta fyllt med gleda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'då eg er mint um den skrymtlause trui som er i deg, den som fyrst budde i Lois, mormor di, og i Eunike, mor di, og som eg er viss på bur i deg og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Difor minner eg deg um å kveikja upp att den Guds nådegåva som er i deg ved mi handpåleggjing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'For Gud gav oss ikkje ei ande som verkar modløysa, men ein som verkar kraft og kjærleik og umtanke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Skjemmast difor ikkje ved vår Herres vitnemål eller ved meg, hans fange, men lid vondt med meg for evangeliet i Guds kraft!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'han som frelste oss og kalla oss med eit heilagt kall, ikkje etter våre gjerningar, men etter si eigi rådgjerd og den nåden som er oss gjeven i Kristus Jesus frå ævelege tider,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'men no er openberra ved vår frelsar Jesu Kristi openberring, han som gjorde dauden til inkjes og førde liv og uforgjengelegdom fram for ljoset ved evangeliet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'og for det vart eg sett til forkynnar og apostel og lærar for heidningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Difor lid eg og dette, men eg skjemmest ikkje ved det; for eg veit kven eg hev sett mi tru til, og eg er viss på at han er megtig til å taka vare på det som er yvergjeve til meg, til hin dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Hav til fyredøme dei heilsame ordi som du høyrde av meg, i tru og kjærleik i Kristus Jesus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Tak vare på den fagre skatt som er yvergjeven til deg, ved den Heilage Ande, som bur i oss!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Du veit dette, at alle dei i Asia vende seg frå meg, og millom dei er Fygelus og Hermogenes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Herren vise miskunn mot Onesiforus’ hus! for han hugga meg ofte og skjemdest ikkje ved mine lekkjor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Men då han var komen til Rom, leita han med stor umak etter meg og fann meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Herren gjeve at han må finna miskunn hjå Herren på hin dagen! Og kor mykje han tente meg i Efesus, det veit du best.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'So vert då du, son min, sterk ved nåden i Kristus Jesus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Og det som du hev høyrt av meg i nærvære av mange vitne, gjev det yver til trufaste menneskje, som er duglege til ogso å læra andre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Lid vondt med meg som ein god Kristi Jesu stridsmann!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Ingen som gjer hertenesta, fløkjer seg inn i livsens syslor, so han kann tekkjast herføraren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Men um ein og strider i tevling, so fær han då ikkje kransen dersom han ikkje strider retteleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Den bonde som arbeider, skal fyrst njota frukterne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Skyna det som eg segjer! for Herren skal gjeva deg skyn på alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Kom Jesus Kristus i hug, som er uppvekt frå dei daude, av Davids ætt, etter mitt evangelium,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'det som eg lid vondt for like til dette å vera bunden som ein illgjerdsmann; men Guds ord er ikkje bunde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Difor toler eg alt for dei utvalde skuld, for at dei og skal vinna frelsa i Kristus Jesus med æveleg herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Det er eit sant ord; for er me daude med honom, skal me og leva med honom;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'held me ut, skal me og styra med honom; forneittar me, skal han og forneitta oss;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'er me trulause, so er han trufast; seg sjølv kann han ikkje forneitta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Minn um dette, med di du vitnar for Herrens åsyn, at dei ikkje må liggja i ordstrid, som ikkje er til noko gagn, men til undergang for dei som høyrer på!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Legg vinn på å framstella deg sjølv som sannrøynd for Gud, ein arbeidar som ikkje tarv skjemmast, med di du lærer sannings-ordet retteleg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Men haldt deg frå det vanheilage tome svall! for dei gjeng alltid lenger i gudløysa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'og ordi deira kjem til å eta um seg som daudkjøt; millom deim er Hymenæus og Filetus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'som hev fare vilt frå sanningi, med di dei segjer at uppstoda alt hev vore, og dei riv ned trui hjå sume.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Men Guds faste grunnvoll stend og hev dette innsigle: «Herren kjenner sine,» og: «Kvar den som nemner Herrens namn, skal vika frå urettferd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Men i eit stort hus er det ikkje berre kjerald av gull og sylv, men og av tre og leir, og nokre til æra, andre til vanæra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Um nokon då held seg rein frå desse, so skal han vera eit kjerald til æra, helga og nytlegt for husbonden, tilreidt til all god gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Men fly frå dei ungdomslege lyster, og trå etter rettferd, tru, kjærleik, fred med deim som påkallar Herren av eit reint hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Og vis ifrå deg dei dårlege og fåvise stridsspursmål, då du veit at dei føder strid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Men ein Herrens tenar må ikkje strida, men vera mild imot alle, dugleg til å læra frå seg, viljug til å tola vondt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'so han med spaklynde tuktar dei som segjer imot, um Gud då ein gong vilde gjeva deim umvending, so dei kunde kjenna sanningi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'og vakna or ruset i djevelens snara, han som dei er fanga av til å gjera hans vilje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Men dette skal du vita, at i dei siste dagar skal det koma vande tider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'For folk skal vera sjølvkjære, pengekjære, storordige, stormodige, spottsame, ulyduge mot foreldre, utakksame, vanheilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'ukjærlege, upålitande, baktalande, umåtelege, umilde, utan kjærleik til det gode,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'svikefulle, framfuse, ovmodige, slike som elskar lysterne sine meir enn Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'som hev skin av gudlegdom, men forneittar hans kraft. Vend deg frå desse!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'For til deim høyrer dei som snikjer seg inn i husi og fangar kvinnfolk som er tyngde med synder og vert drivne av mangeslag lyster');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'og alltid lærer og aldri kann koma til å kjenna sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Som Jannes og Jambres stod imot Moses, so stend dei og imot sanningi, menneskje som er øydelagde i hugen, duglause i trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Men dei skal ikkje koma lenger; for deira fåvit skal verta audsynt for alle, liksom det og vart med hine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Men du hev fylgt etter mi læra, mi ferd, mitt forset, mi tru, mitt langmod, min kjærleik, mitt tolmod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'mine forfylgjingar, mine lidingar, slike som møtte meg i Antiokia, i Ikonium, i Lystra; slike forfylgjingar hev eg halde ut, og Herren hev fria meg ut or deim alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Og alle som vil liva gudleg i Kristus Jesus, skal verta forfylgde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Men vonde menneskje og slike som kverver syni på folk, gjeng fram til det som er verre, med di dei fører vilt og fer vilt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Men du, vert du standande i det som du hev lært, og som du er yvertydd um, då du veit kven du hev lært det av,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'og då du alt frå barndomen kjenner dei heilage skrifter som kann gjera deg vis til frelsa ved trui på Kristus Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Heile skrifti er innanda av Gud og er dugleg til lærdom, til yvertyding, til rettleiding, til uppseding i rettferd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'so gudsmannen kann verta fullkomen, dugleg til all god gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Eg vitnar for Gud og Kristus Jesus, som skal døma livande og daude, og ved hans openberring og hans rike:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Forkynn ordet, statt nær med det i tid og i utid, yvertyd, refs, påminn med alt langmod og all læra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'For det skal koma ei tid då dei ikkje skal tola den heilsame læra, men etter sine eigne lyster taka seg sjølve lærarar i flokketal, med di dei klæjar dei i øyra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'og dei skal venda øyra frå sanningi og venda seg til eventyr.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Men ver du edru i alle ting, lid vondt, gjer ein evangeli-forkynnars gjerning, fullfør di tenesta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'For eg vert alt ofra, og tidi til mi avferd stundar til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Eg hev stridt den gode striden, eg hev fullenda laupet, eg hev halde trui.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'So ligg då rettferdskransen reidug til meg, den som Herren, den rettferdige domar, skal gjeva meg på hin dagen, då ikkje berre meg, men alle som hev elska hans openberring.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Gjer deg umak med å koma snart til meg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'For Demas forlet meg av kjærleik til den noverande verdi og for til Tessalonika, Kreskens til Galatia, Titus til Dalmatia.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lukas er åleine hjå meg. Tak Markus og før honom med deg, for han er meg nyttug til tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tykikus hev eg sendt til Efesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Når du kjem, so tak med deg den kåpa som eg let att i Troas hjå Karpus, og bøkerne, serleg skinnbøkerne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Koparsmeden Aleksander gjorde meg mykje vondt. Herren kjem til å løna han etter hans gjerningar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Agta deg for honom du og! for han stod hardt imot våre ord.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Ved mitt fyrste forsvar møtte ingen med meg, men alle forlet meg. Gjev det ikkje må verta deim tilrekna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Men Herren stod med meg og styrkte meg, so forkynningi ved meg skulde verta fullførd, og alle folkeslag få høyra henne; og eg vart utfria or løvegapet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Herren skal fria meg frå all vond gjerning og frelsa meg inn i sitt himmelske rike. Honom vere æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Helsa Priska og Akvilas og Onesiforus’ hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus vart att i Korint. Trofimus let eg etter meg sjuk i Milet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Gjer deg umak med å koma fyre vinteren! Eubulus og Pudens og Linus og Klaudia og alle brørne helsar deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Herren Jesus vere med di ånd! Nåden vere med dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, Guds tenar og Jesu Kristi apostel til å føra Guds utvalde til tru og til å kjenna den sanning som høyrer til gudlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'i von um ævelegt liv, som Gud, han som ikkje lyg, hev lova frå ævelege tider,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'men no i si tid hev han openberra sitt ord ved den forkynning som vart meg yvergjevi etter Guds, vår frelsars, fyresegn -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'til Titus, min egtefødde son i den sams trui: Nåde og fred frå Gud Fader og Kristus Jesus, vår frelsar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'For den skuld let eg deg etter på Kreta, at du skulde skipa til det som vanta, og setja inn eldste i kvar by, so som eg pålagde deg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'um det er nokon som er ulastande, mann til ei kvinna, hev truande born som ikkje hev vondt ord for skamløysa eller er ulyduge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'For ein tilsynsmann skal vera ulastande som ein Guds hushaldar, ikkje sjølvgod, ikkje vondlyndt, ikkje drikkekjær, ikkje hardhendt, ikkje lysten etter låk vinning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'men gjestmild, glad i det gode, visleg, rettferdig, heilag, fråhalden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'ein som held seg til det truverdige ord etter læra, so han kann vera før både til å påminna med den heilsame læra og til å tala deim til rettes som segjer imot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'For det er mange agelause, som fer med fåfengd tale og dårar hugen, mest dei av umskjeringi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Desse skal ein målbinda; for dei riv ned heile hus, med di dei lærer slikt som ikkje sømer seg, for skamleg vinning skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Ein av deim, deira eigen profet, hev sagt: «Kretarar er alltid ljugarar, vonde dyr, late bukar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Dette vitnemålet er sant; difor skal du refsa deim strengt, so dei må verta heile i trui');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'og ikkje ansa jødiske eventyr og bod av menneskje som vender seg frå sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Alt er reint for dei reine; men for dei ureine og vantruande er ingen ting rein; men både deira hug og samvit er ureine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Dei segjer at dei kjenner Gud; men i sine gjerningar forneittar dei honom, med di dei er styggjelege og ulyduge og duglause til all god gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Men du skal tala slikt som høver til den heilsame læra:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'at gamle menn skal vera ædrue, vyrdelege, vislege, heile i trui, i kjærleiken, i tolmodet;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'like eins at gamle kvinnor i si åtferd skal te seg som det sømer dei heilage, ikkje vera baktalende, ikkje trælar under drykk, men vegleidarar i det gode,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'so dei kann læra dei unge kvinnorne å elska mennerne sine og borni sine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'til å vera vislege, reine, huslege, gode, sine menner undergjevne, so Guds ord ikkje skal verta spotta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Dei unge menner skal du like eins påminna um å vera vislege,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'og vis deg sjølv i alle ting som eit fyredøme i gode gjerningar, og vis i di læra reinleik, vyrdnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'heilsam, ulasteleg tale, so motstandaren må verta skjemd, når han inkje vondt hev å segja um oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Tenarar skal du påminna um å vera sine eigne herrar undergjevne, å tekkjast deim i alle ting, ikkje segja imot,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'ikkje vera utrue, men visa all god truskap, so dei i alle ting kann vera til pryda for Guds, vår frelsars, læra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'For Guds nåde er openberra til frelsa for alle menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'med di han uppsedar oss til å segja frå oss gudløysa og dei verdslege lyster og liva viseleg og rettferdigt og gudleg i den verdi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'medan me ventar på den sæle von og openberringi av den store Guds og vår frelsar Jesu Kristi herlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'han som gav seg sjølv for oss, so han kunde løysa oss ut frå all urettferd og reinsa seg eit eigedomsfolk som er ihuga til gode gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Dette skal du tala og påminna og refsa med all fyresegn. Lat ingen vanvyrda deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Minn deim um å vera styremagter og yverråder undergjevne, vera lyduge, reidebune til all god gjerning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'ikkje spotta nokon, vera fredlege, godlyndte, visa all spaklynde mot alle menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'For me var og eingong uvituge, ulyduge, villfarande, trælande under mangeslag lyster og fysnor, livande i vondskap og ovund, hata og hatande kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Men då Guds, vår frelsars, godleik og mannemilde vart openberra,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'frelste han oss - ikkje for rettferdige gjerningar skuld, som me hadde gjort, men etter si miskunn - ved badet til atterføding og uppnying ved den Heilage Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'som han rikleg hev rent ut yver oss ved Jesus Kristus, vår frelsar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'so me, rettferdiggjorde ved hans nåde, i voni skulde verta ervingar til det ævelege liv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Dette er eit sant ord! Og dette vil eg at du skal prenta inn, so dei som trur på Gud, må leggja vinn på å gjera gode gjerningar. Dette er godt og gagnlegt for menneski;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'men dårlege stridsspursmål og ættartal og kivsmål og trettor um lovi skal du halda deg ifrå, for dei er gagnlause og fåfengde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Eit ranglærande menneskje skal du visa frå deg, når du hev påminnt honom ein gong og tvo gonger,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'då du veit at ein slik er rangsnudd og syndar, fordømd av seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Når eg sender Artemas til deg eller Tykikus, so gjer deg umak med å koma til meg i Nikopolis; for der hev eg tenkt å vera vinteren yver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenas, den lovlærde, og Apollos skal du med umhug hjelpa i vegen, so dei ikkje skal vanta noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Men lat og våre læra å driva på gode gjerningar, etter som torv er til, so dei ikkje skal vera fruktlause.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Alle som er hjå meg, helsar deg. Helsa deim som elskar oss i trui! Nåden vere med dykk alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulus, Kristi Jesu fange, og broderen Timoteus til Filemon, vår kjære ven og medarbeidar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'og til Apfia, vår syster, og til Arkippus, vår medstridsmann, og til kyrkjelyden i ditt hus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Eg takkar alltid min Gud, når eg kjem deg i hug i bønerne mine,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'då eg høyrer um din kjærleik og den tru som du hev til Herren Jesus og til alle dei heilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'at deira samfund med deg i trui må verta verksamt for Kristus i kjennskapen til alt det gode som er i dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'For eg fekk stor gleda og trøyst ved din kjærleik, av di dei heilage er hugga i hjarta ved deg, bror!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Difor, endå eg hev stort frimod i Kristus til å påleggja deg det som sømelegt er,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'so bed eg då heller for kjærleiken skuld. Slik som eg er, den gamle Paulus, men no og Kristi Jesu fange,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'bed eg deg for son min, som eg hev avla i mine lekkjor, Onesimus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'som fyrr var unyttug for deg, men no er nyttug for deg og for meg, han som eg sender attende til deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Tak du imot honom, det er mitt eiga hjarta!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Eg hadde hug til å få hava honom hjå meg, so han i din stad kunde tena meg i mine lekkjor for evangeliet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'men utan ditt samtykkje vilde eg ingen ting gjera, so din godleik ikkje skulde vera liksom av tvang, men av fri vilje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'For kann henda han difor vart skild frå deg for ei stund, at du kunde få honom att til æveleg eiga,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'ikkje lenger som træl, men meir enn ein træl, som ein kjær bror, serleg for meg, men kor mykje meir for deg, både i kjøtet og i Herren!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'So sant du då held meg for din medbror, so tak imot honom som meg sjølv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Og hev han gjort deg nokon urett, eller er han deg noko skuldig, so før det på mi rekning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Eg, Paulus, skriv med mi eigi hand: Eg skal betala det - at eg ikkje skal segja deg, at du skyldar meg endå deg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Ja, bror, lat meg då hava gagn av deg i Herren, hugga mitt hjarta i Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'I tiltru til din lydnad skriv eg dette til deg, eg er viss på at du vil gjera endå meir enn eg segjer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Stell so og til herbyrge åt meg; for eg vonar at eg ved dykkar bøner skal verta dykk gjeven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Epafras, min medfange i Kristus Jesus, helsar deg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'like eins Markus, Aristarkus, Demas, Lukas, mine medarbeidarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Vår Herre Jesu Kristi nåde vere med dykkar ånd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Etter at Gud fordom hadde tala mange gonger og på mange måtar til federne gjenom profetarne, so hev han i desse siste dagar tala til oss gjenom Sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Honom hev han sett til erving yver alle ting, og ved honom hev han og gjort verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Han er avglansen av hans herlegdom og avbilætet av hans grunn-hått, og ber alle ting ved sitt veldes ord, og då han hadde gjort reinsing for synderne våre, sette han seg difor ved høgre handi åt Majestæten i det høge,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'og han hev vorte so mykje hævare enn englarne som han hev ervt eit herlegare namn framfor deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'For kven av englarne hev han noko sinn sagt det til: «Du er son min, eg hev født deg i dag?» og atter: «Eg vil vera honom ein far, og han skal vera meg ein son.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Men når han atter fører den fyrstefødde inn i verdi, segjer han: «Og alle Guds englar skal tilbeda honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Og um englarne segjer han: «Han som gjer englarne sine til vindar og tenarane sine til eldsloge;»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'men um Sonen: «Din kongsstol, Gud, stend i all æva; ein kongsstav med rettvisa er kongsstaven i ditt rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Du elska rettferd og hata urett; difor hev Gud, din Gud, salva deg med fagnads olje framfor dine medbrør.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Og: «Du, Herre, grunnfeste jordi frå upphavet, og himlarne er verk av dine hender;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'dei skal forgangast, men du vert verande, og dei skal alle eldast som ein klædnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'og som ei kåpa skal du rulla deim saman, og dei skal verta umskifte, men du er den same, og dine år skal ikkje få ende.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Men kven av englarne hev han noko sinn sagt det til: «Set deg ved mi høgre hand, til dess eg legg dine fiendar til skammel under dine føter?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Er dei ikkje alle saman tenande ånder, som vert utsende til tenesta for deira skuld som skal erva frelsa?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Difor skal me so mykje meir agta på det me hev høyrt, so me ikkje skal driva undan.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'For dersom det ord som var tala ved englar, stod fast, og kvar misgjerd og ulydnad mot det fekk si rettferdige løn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'kor skal då me sleppa undan, um me ikkje vyrder so stor ei frelsa? den som fyrst vart forkynt ved Herren og er komi vitnefast til oss ved deim som høyrde honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'med di Gud vitna med både ved teikn og under og ymse kraftverk og tildeiling av den Heilage Ande etter sin vilje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'For det var ikkje under englar, han lagde den komande verdi som me talar um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Men ein hev vitna ein stad og sagt: «Kva er eit menneskje, at du kjem det i hug, eller ein menneskjeson, at du ser til honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'du gjorde honom lite lægre enn englarne; med herlegdom og æra krynte du honom og sette honom yver dei verk dine hender gjorde;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'alle ting lagde du under hans føter.» For då han lagde alle ting under honom, so tok han ingen ting undan som ikkje er honom underlagd; men no ser me endå ikkje at alle ting er honom underlagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Men den som var gjord lite lægre enn englarne, Jesus, honom ser me, av di han leid dauden, krynt med herlegdom og æra, so han ved Guds nåde skulde smaka dauden for alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'For det sømde seg honom som alt er til for, og som alt er til ved, då han førde mange born til herlegdom, ved lidingar å fullenda frelse-hovdingen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'For både den som helgar, og dei som vert helga, er alle av ein; difor skjemmest han ikkje ved å kalla deim brør,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'når han segjer: «Eg vil forkynna ditt namn for mine brør, eg vil lovsyngja deg midt i lyden;»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'og atter: «Eg vil setja mi tru til honom;» og atter: «Sjå, her er eg og dei born Gud hev gjeve meg.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Då no borni hev kjøt og blod saman, so vart han og på dilik måte samhavande deri, for at han ved dauden skulde gjera den til inkjes som hadde daudens velde, det er djevelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'og fria ut alle deim som av rædsla for dauden var i trældom all si livstid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'For englar han tek seg då vel ikkje av, men Abrahams ætt tek han seg av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Difor laut han verta brørne sine lik i alle ting, so han kunde verta ein miskunnsam og trufast øvsteprest for Gud til å gjera soning for synderne åt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'For av di han sjølv hev lide og vore freista, so kann han koma deim til hjelp som vert freista.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Difor, heilage brør, som er luthavande i eit himmelsk kall! sjå på den apostel og øvsteprest som me kjennest ved, Jesus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'han som var tru mot den som gjorde honom dertil, liksom og Moses var i heile hans hus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'For denne er halden so mykje større æra verd enn Moses, som den som hev bygt huset, hev større æra enn huset sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Kvart hus er det einkvan som byggjer, men den som hev bygt alt, det er Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Og Moses var vel tru i heile hans hus som ein tenar til å vitna um det som skulde verta tala,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'men Kristus stend som son yver huset hans; og hans hus er me, so framt me held vårt frimod og den voni me rosar oss av, fast alt til enden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Difor, som den Heilage Ande segjer: «I dag, um de høyrer hans røyst,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'so forherd ikkje dykkar hjarto som på argingsstaden på freistingsdagen i øydemarki,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'der federne dykkar freista meg; dei prøvde meg, endå dei såg mine gjerningar i fyrti år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Difor harmast eg på denne ætti og sagde: «Dei fer alltid vilt i hjarta;» men dei kjende ikkje mine vegar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'so eg svor i min vreide: «Sanneleg, dei skal ikkje koma inn til mi kvila!»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Sjå til, brør, at det ikkje i nokon av dykk skal vera eit vondt, vantruande hjarta, so han fell frå den livande Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Men påminn kvarandre kvar dag, so lenge som det heiter: «i dag», so ikkje nokon av dykk skal verta forherd ved dåring av syndi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'For me hev fenge lut med Kristus, so framt me held vår fyrste fulle vissa fast til enden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Når det vert sagt: «I dag, um de høyrer hans røyst, so forherd ikkje dykkar hjarto som på argingsstaden,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'kven var då dei som høyrde og arga honom? Var det ikkje alle dei som gjekk ut or Egyptarland ved Moses?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Men kven var det han harmast på i fyrti år? var det ikkje på deim som hadde synda, so deira kroppar fall i øydemarki?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Og kven var det han svor um, at dei ikkje skulde koma inn til hans kvila, utan um deim som var vantruande?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'So ser me då at dei ikkje kunde koma inn for vantru skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Lat oss difor taka oss i vare for at nokon av dykk skal synast å verta standande etter, då ein lovnad um å koma inn til hans kvila endå stend att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'For fagnadbodet er og forkynt oss liksom hine; men deim gagna ikkje det ordet som dei høyrde, av di det ikkje ved trui var sameina med deim som høyrde det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'For me som er komne til trui, me gjeng inn til kvila etter det som han hev sagt: «So eg svor i min vreide: «Sanneleg, dei skal ikkje koma inn til mi kvila,»» endå gjerningarne var fullførde alt sidan verdi var grunnlagd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'For han hev ein stad sagt so um den sjuande dagen: «Og Gud kvilde den sjuande dagen frå alle sine gjerningar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Og atter på denne staden: «Sanneleg, dei skal ikkje koma inn til mi kvila.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Då det soleis stend att, at nokre skal koma inn til henne, og dei som fyrst fekk fagnadbodet, ikkje kom inn for vantru skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'so set han atter ein dag: «i dag,» med di han segjer ved David etter so lang tid, som sagt er: «I dag, um de høyrer hans røyst, so forherd ikkje dykkar hjarto!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'For dersom Josva hadde ført deim til kvila, so hadde han ikkje tala um ein annan dag deretter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'So stend det då att ei kviledagshelg for Guds folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'For den som er komen inn til hans kvila, han hev og fenge kvila frå sine gjerningar liksom Gud frå sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Lat oss difor leggja vinn på å koma inn til den kvila, so ikkje nokon skal falla etter det same fyredøme på vantru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'For Guds ord er livande og kraftigt og kvassare enn noko tvieggja sverd, og trengjer seg igjenom til dess det kløyver sjæl og ånd, ledmot og merg, og dømer hjartans tankar og råder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'og ingen skapning er løynd for hans åsyn, men alt er nake og bert for hans augo som me hev å gjera med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Sidan me då hev ein stor øvsteprest, som hev gjenge gjenom himlarne, Jesus, Guds Son, so lat oss halda fast på vedkjenningi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'For me hev ikkje ein øvsteprest som ikkje kann hava medynk med vår vesaldom, men ein som er røynd i alle ting i likning med oss, då utan synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Lat oss difor med frimod ganga fram for nådens kongsstol, so me kann få miskunn og finna nåde til hjelp i rette tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'For kvar øvsteprest vert teken bland menneskje og vert innsett for menneskje til tenesta for Gud, til å bera fram gåvor og slagtoffer for synder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'som ein sovoren som kann vera linnhjarta mot dei vankunnige og villfarande, av di han og sjølv ligg under vesaldom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'og for den skuld lyt han bera fram syndoffer, liksom for folket, so og for seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Og ingen tek seg sjølv den æra til, men den som vert kalla av Gud liksom Aron.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'So hev ikkje Kristus heller tillagt seg den æra å verta øvsteprest, men han som sagde til honom: «Du er min son, eg hev født deg i dag.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Liksom han og segjer ein annan stad: «Du er prest til æveleg tid etter Melkisedeks vis.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Og han hev i sitt kjøts dagar med sterkt rop og tåror bore fram bøner og naudbeding til honom som kunde frelsa honom frå dauden, og vart bønhøyrd for sin gudlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'og soleis lærde han, endå han var son, lydnad av det han leid;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'og då han var fullenda, vart han upphav til æveleg frelsa for alle deim som lyder honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'med di Gud kalla honom øvsteprest etter Melkisedeks vis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Um dette hev me mykje å segja, som og er vandt å leggja ut, då de hev vorte seinføre til å høyra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'For de som etter tidi skulde vore lærarar, de treng atter til at ein lærer dykk dei fyrste grunnar i Guds ord; og de hev vorte slike som treng til mjølk og ikkje fast føda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'For kvar den som fær mjølk, er urøynd i rettferds ord; for han er eit barn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Men fast føda er for vaksne, for deim som ved tame hev tilvande sansar til å skilja millom godt og vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Difor vil me springa yver barnelærdomen um Kristus og skrida fram til det fullkomne, og ikkje atter leggja grunnvollen med umvending frå daude gjerningar og tru på Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'med læra um dåp og handpåleggjing og uppstoda av daude og æveleg dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Og dette vil me gjera, um Gud gjev lov til det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'For det er umogelegt at dei som ein gong er upplyste og hev smaka den himmelske gåva og fenge lut i den Heilage Ande');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'og smaka Guds gode ord og krafterne av den komande verdi');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'og so fell frå, atter kann uppnyast til umvending, sidan dei på nytt krossfester Guds son for seg og gjer honom til spott.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'For den jordi som drikk regnet som ofte fell på henne, og ber gagnleg grøda åt deim som ho vert dyrka for, ho fær velsigning av Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'men ber ho tornar og tistlar, so er ho udugleg og forbanning nær, og enden med henne er å verta brend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Men um dykk, kjære vener, er me visse på det som betre er, og som høyrer til frelsa, um me og talar soleis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'For Gud er ikkje urettferdig, so han skulde gløyma dykkar verk og den kjærleiken som de hev synt for hans namn, med di de hev tent og endå tener dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Men me ynskjer at kvar ein av dykk må syna den same ihuge for den fulle vissa i voni alt til enden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'so de ikkje skal verta seinføre, men fylgja etter deim som ved tru og tolmod erver lovnaderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'For då Gud gav Abraham lovnaden, og han ingen større hadde å sverja ved, so svor han ved seg sjølv');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'og sagde: «Sanneleg, eg vil rikleg velsigna deg og gjera deg storleg mangfaldig.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Og soleis vann han lovnaden, då han hadde venta med tolmod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'For menneskje sver ved ein større, og eiden er deim ein ende på all motsegn til stadfesting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Difor lagde Gud ein eid til, då han enn meir vilde syna ervingarne til lovnaden kor ubrigdeleg hans vilje var,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'so me ved tvo ubrigdelege ting, som Gud umogeleg kunde svika i, skulde hava ei sterk trøyst, me som flydde til å gripa den voni som ventar oss,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'den me hev som eit anker for sjæli, eit som er trygt og fast og når inn um forhenget,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'der Jesus gjekk inn som fyregangsmann for oss, med di han vart øvsteprest etter Melkisedeks vis til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'For denne Melkisedek, konge i Salem og den høgste Guds prest, han som gjekk Abraham til møtes då han kom att frå sin siger yver kongarne, og som velsigna honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'som Abraham og gav tiend av alt; han som er, når hans namn vert utlagt, fyrst rettferds konge, dinæst og Salems konge, det er freds konge,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'som er utan far, utan mor, utan ættartal, og som korkje hev dagars byrjing eller livs ende, men er gjord lik med Guds son: han vert prest for alltid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Og sjå kor stor han er, som Abraham, patriarken, endå gav tiend av herfanget!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Og dei av Levi søner som fær prestedømet, hev påbod um å taka tiend etter lovi av folket, det er av sine brør, endå desse er komne or Abrahams lend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Men denne, som ikkje reknar si ætt frå deim, han tok tiend av Abraham og velsigna den som hadde lovnaderne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Men utan all motsegn er det den ringare som vert velsigna av den høgre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Og her er det døyelege menneskje som tek tiend, men der ein som det vert vitna um at han liver.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Og um eg so må segja: Gjenom Abraham hev endå Levi, som tek tiend, sjølv gjeve tiend;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'for han var endå i sin fars lend då Melkisedek gjekk honom til møtes.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Var det då fullkomenskap å vinna ved det levitiske prestedømet - for det var folket bunde til ved lovi - kvi turvest det då at ein annan prest skulde verta uppstelt etter Melkisedeks vis og ikkje verta nemnd etter Arons vis?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'For når prestedømet vert umskift, vert det naudsynleg og eit umskifte med lovi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'For han som dette vert sagt um, høyrde til ei onnor ætt, og ingen av henne hev tent for altaret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Det er kjent nok at vår Herre er upprunnen av Juda, og til den ætti hev ikkje Moses tala noko um prestar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Og det er endå meir openbert, når ein annan prest vert uppstelt i likning med Melkisedek,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'ein som ikkje hev vorte det etter eit kjøtlegt bods lov, men etter eit uforgjengelegt livs kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'For han vitnar: «Du er prest til æveleg tid etter Melkisedeks vis.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'For eit bod som fyrr galdt, vert avlyst, av di det var magtlaust og gagnlaust');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '- for lovi førde ingen ting fram til fullkomenskap - og ei betre von vert innførd, som me nærmar oss til Gud med.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Og so visst som det ikkje vart gjort utan eid');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '- for hine hev vorte prestar utan eid, men denne med eid ved den som segjer til honom: «Herren hev svore, og han skal ikkje angra det: «Du er prest til æveleg tid etter Melkisedeks vis»» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'so visst er det ei hævare pakt som Jesus hev vorte borgsmann for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Og hine prestarne hev vore fleire, då dei ved dauden vart hindra i å halda ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Men denne hev eit uforgjengelegt prestedøme, av di han vert verande til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Difor kann han og fullkomleg frelsa deim som kjem til Gud ved honom, med di han liver alltid til å ganga i bøn for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'For me laut og hava ein sovoren øvsteprest som er heilag, uskuldig, rein, skild frå syndarar og upphøgd yver himlarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'ein som ikkje dagleg treng til, som øvsteprestarne, å bera fram offer fyrst for sine eigne synder og so for synderne åt folket; for det gjorde han ein gong for alle då han ofra seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'For lovi set til øvsteprestar menneskje som hev vesaldom; men den eids ord som kom etter lovi, set Sonen inn, han som er fullenda for all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Men ei hovudsak i det som her vert sagt, er: Me hev ein sovoren øvsteprest som hev sett seg ved høgre sida åt kongsstolen til Majestæten i himlarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'med presteleg tenesta i heilagdomen, det sanne tjeldet, som Herren hev reist og ikkje eit menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'For kvar ein øvsteprest vert innsett til å bera fram både gåvor og slagtoffer; difor er det naudsynlegt at denne og hev noko som han kann bera fram.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'For var han no på jordi, so var han ikkje ein gong prest; for det finst prestar som ber fram gåvorne etter lovi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'dei som tener ei likning og ein skugge av det himmelske, etter den fyreskrift Moses fekk då han skulde laga tjeldet; for han segjer: «Sjå til at du fær gjort alt etter det fyrebilætet som vart synt deg på fjellet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Men no hev han fenge so mykje betre prestetenesta, som det og er ei hævare pakt han er millommann for, med di ho er grunnlagd på hævare lovnader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'For hadde den fyrste vore ulastande, so var det ikkje søkt rom åt ei onnor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'For det er lastord han talar til deim når han segjer: «Sjå, det kjem dagar, segjer Herren, då eg vil gjera ei ny pakt med Israels hus og Judas hus,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'ikkje etter den pakti som eg gjorde med federne deira den dagen då eg tok deim i handi og leide deim ut or Egyptarland; for dei vart ikkje standande i mi pakt, og so brydde eg meg ikkje um deim, segjer Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'For dette er den pakti som eg vil gjera med Israels hus etter dei dagarne, segjer Herren: Eg vil gjeva loverne mine i hugen deira og skriva deim inn i hjarto deira, og eg vil vera deira Gud, og dei skal vera mitt folk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'og dei skal ikkje læra kvar sin landsmann og kvar sin bror og segja: «Kjenn Herren!» for dei skal alle saman kjenna meg, frå den minste til den største av deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'For eg vil vera nådig mot misgjerderne deira, og synderne deira vil eg ikkje lenger koma i hug.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Med di han segjer: «ei ny», hev han dømt den fyrste som gamall; men det som vert gamalt og foraldra, er nær ved å kverva burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'No hadde vel og den fyrste pakti sine fyreskrifter um gudstenesta og den jordiske heilagdomen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'For det vart laga eit tjeld, det fremste, og i det var både ljosestaken og bordet og skodebrødi; dette er kalla det heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Og attanfor det andre forhenget var det tjeldet som er kalla det høgheilage,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'det som hadde eit røykjelse-altar av gull og sambandskista, som var klædd heilt kringum med gull; og i henne var ei gullkrukka med manna og Arons stav, som hadde blømt, og sambandstavlorne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'og ovan yver henne herlegdoms kerubar, som skygde yver nådestolen; men um desse ting skal me ikkje no tala stykke for stykke.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Men då no dette er laga soleis, so gjeng prestarne alltid inn i det fremste tjeldet når dei gjer si tenesta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Men i det andre gjeng berre øvstepresten inn ein gong um året, ikkje utan blod, som han ber fram for seg sjølv og for misferderne åt folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Dermed syner den Heilage Ande dette, at vegen til heilagdomen endå ikkje er openberra, so lenge det fremste tjeldet stend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'For dette er eit bilæte på den noverande tid, og i samhøve dermed vert både gåvor og slagtoffer framborne, som ikkje kann gjera den fullkomen etter samvitet, som tenar Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'men som berre er kjøtlege fyreskrifter, saman med mat og drykk og alle slag tvættingar, pålagde til dess tidi til rettarboti kom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Men då Kristus kom som øvsteprest for det tilkomande gode, gjekk han gjenom det større og fullkomnare tjeldet, som ikkje er gjort med hender, det er: som ikkje er av denne skapning,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'og ikkje med blod av bukkar eller kalvar, men med sitt eige blod, ein gong inn i heilagdomen og fann ei æveleg utløysing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'For dersom blodet av bukkar og uksar og oska av ei kviga, når det vert skvett ut yver dei ureine, helgar til reinleik på kjøtet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'kor mykje meir skal då blodet av Kristus, som ved ei æveleg ånd bar seg sjølv fram som eit ulastelegt offer for Gud, reinsa dykkar samvit frå daude gjerningar til å tena den livande Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Og difor er han millommann for ei ny pakt, for at dei som er kalla, skal få den ævelege arven som var lova, dermed at ein døydde til utløysing frå misgjerningarne i den fyrste pakt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'For der det finst eit testament, der er det naudsynlegt, at dauden hans som hev gjort testamentet, vert stadfest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'For eit testament vert fyrst gjeldande etter dauden, og det hev aldri kraft so lenge han liver som gjorde testamentet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Difor vart heller ikkje den fyrste pakt innvigd utan blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'For då kvart bod etter lovi var forkynt av Moses for alt folket, so tok han blod av kalvar og bukkar, saman med vatn, og skarlakraud ull og isop, og skvette både på boki sjølv og på alt folket');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'og sagde: «Dette er blodet til den pakt som Gud hev gjeve bod um til dykk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Men ogso tjeldet og all reidskapen som høyrde til gudstenesta, skvette han like eins blodet på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Og næstan alt vert etter lovi reinsa med blod, og utan at blods utrenning vert det ingi forlating.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'So er det då naudsynlegt at avbilæti av dei himmelske ting vert reinsa med slikt, men dei himmelske ting sjølve med betre offer enn desse.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'For Kristus gjekk ikkje inn i ein heilagdom som var gjord med hender, eit avbilæte av den sanne, men inn i sjølve himmelen til å syna seg no for Guds åsyn for vår skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'og ikkje heller so, at han fleire gonger skulde ofra seg sjølv, liksom øvstepresten kvart år gjeng inn i heilagdomen med framandt blod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'for då hadde han ofte lote lida frå verdi vart grunnlagd; men no er han ein gong ved enden av tiderne openberra til å taka burt syndi ved sitt offer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Og liksom det er so laga at menneski lyt døy EIN gong, og sidan kjem dom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'soleis er og Kristus ofra EIN gong for å taka burt synderne frå dei mange; og andre gongen skal han, utan synd, syna seg til frelsa for deim som ventar på honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'For sidan lovi berre hev ein skugge av dei tilkomande gode ting, men ikkje sjølve bilætet av tingi, so kann ho aldri ved dei same årlege offer som dei stødt ber fram, gjera deim fullkomne som kjem fram med deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Elles hadde dei vel halde upp med å bera deim fram, då dei ofrande ikkje lenger vilde havt synder på samvitet når dei ein gong var reinsa.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Men ved deim kjem årlegårs minning um synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'For det er umogelegt at blod av uksar og bukkar kann taka burt synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Difor segjer han, då han stig inn i verdi: «Offer og gåva vilde du ikkje hava, men ein likam laga du åt meg;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'brennoffer og syndoffer hadde du ikkje hug på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Då sagde eg: «Sjå, eg kjem - i bokrullen er det skrive um meg - og vil gjera, Gud, din vilje.»»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Fyrst segjer han: «Offer og gåva og brennoffer og syndoffer vilde du ikkje hava, og du hadde ikkje hug på deim» - endå dei vert framborne etter lovi -;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'so segjer han: «Sjå, eg kjem og vil gjera din vilje.» Han tek burt det fyrste, for at han kann setja inn det andre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Med denne vilje er me helga ved ofringi av Jesu Kristi likam ein gong for alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Og kvar prest stend der og gjer dagstødt tenesta og ber fram mange gonger dei same offer, som aldri kann taka burt synder;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'men han hev bore fram eit einaste offer for synder og hev so for alltid sett seg ved Guds høgre hand');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'og ventar sidan berre på at hans fiendar skal verta lagde til skammel for føterne hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'For med eit einaste offer hev han for alltid gjort deim fullkomne som vert helga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Men det vitnar og den Heilage Ande for oss; for etter han hev sagt:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '«Dette er den pakti som eg vil gjera med deim etter dei dagarne,» so segjer Herren: «Eg vil gjeva loverne mine i hjarto deira, og skriva deim inn i hugen deira,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'og synderne deira og misgjerderne deira vil eg ikkje lenger koma i hug.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Men der det er forlating for deim, der trengst det ikkje lenger noko offer for synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'So hev me då, brør, i Jesu blod frimod til å ganga inn i heilagdomen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'som han hev vigt oss ein ny og livande veg til, gjenom forhenget, det er hans kjøt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'og me hev ein stor prest yver Guds hus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Difor, lat oss stiga fram med eit sannferdelegt hjarta, med full vissa i trui, reinsa i hjarto frå eit vondt samvit og tvegne på likamen med reint vatn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Lat oss halda uruggeleg fast på å vedkjennast voni, for han er trufast som gav lovnaden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'og lat oss agta på kvarandre, so me kveikjer kvarandre til kjærleik og gode gjerningar');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'og ikkje skil oss frå vår eigi samling som sume hev for skikk, men påminner kvarandre, og det so mykje meir som de ser kor det lid mot dagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'For syndar me med vilje når me hev lært å kjenna sanningi, då er det ikkje att meir noko offer for synder,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'men berre ei fælande gruv for dom og ein logande brennhug som skal eta upp dei motstridige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Når nokon hev brote Mose lov, so døyr han utan miskunn etter ord av tvo eller tri vitne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'kor mykje verre refsing trur de då den skal verta kjend verd, som hev trødt Guds Son under føter og vanvyrdt paktblodet som han vart helga med, og svivyrdt nådens Ande!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'For me kjenner honom som hev sagt: «Hemnen høyrer meg til, eg skal gjeva attgjeld, segjer Herren.» Og atter: «Herren skal døma sitt folk.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Det er gruelegt å falla i henderne på den livande Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Men kom i hug dei framfarne dagar, då de, etter de var upplyste, tolde mykjen strid i lidingar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'med di de snart sjølve ved hædingar og trengslor vart til ei bisn, snart var samlidande med deim som var so farne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'For de hadde og samhug med fangarne, og de bar det med gleda at dykkar gods vart rana, då de visste at de sjølve hadde ein betre og varande eigedom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Kasta difor ikkje burt dykkar frimod, som hev stor løn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'For de treng til tolmod, so de kann nå lovnaden når de hev gjort Guds vilje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'For endå er det berre so stutt ei stund, so kjem han som koma skal, og han skal ikkje drygja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, '«Men den rettferdige, ved tru skal han liva;» og: «Um nokon dreg seg undan, so hev mi sjæl ikkje hugnad i honom.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Men me er ikkje av deim som dreg seg undan til fortaping, men av deim som trur til frelsa for sjæli.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Men tru er full vissa um det som ein vonar, yvertyding um ting som ein ikkje ser.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'For på grunn av henne fekk dei gamle godt vitnemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Ved tru skynar me at verdi er fullførd ved Guds ord, so det som vert set, ikkje vart til av det synlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Ved tru bar Abel fram for Gud eit betre offer enn Kain; ved henne fekk han det vitnemål at han var rettferdig, med di Gud vitna um gåvorne hans, og ved henne talar han enno, etter han er daud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Ved tru vart Enok burtrykt, so han ikkje skulde sjå dauden, «og han vart ikkje funnen, av di Gud hadde rykt honom burt.» For fyrr han vart burtrykt, fekk han det vitnemål at han tektest Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'men utan tru er det umogelegt å tekkjast Gud; for den som vil koma til Gud, må tru at han er til, og at han løner deim som søkjer honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Ved tru var det Noah, då Gud varsla honom um det som ein ikkje såg endå, med heilag otte bygde ei ark til frelsa for sitt hus; ved henne fordømde han verdi og vart erving til den rettferd som er av tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Ved tru var Abraham lydug då han vart kalla, so han gjekk til den staden han skulde få til arv; og han tok ut, endå han ikkje visste kvar han skulde koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Ved tru busette han seg som utlending i det landet som var honom lova, liksom i eit framandt land, og budde i tjeld saman med Isak og Jakob, som var medervingar til den same lovnaden;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'for han venta på byen med dei faste grunnvollarne, som Gud er byggmeister og skapar til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Ved tru fekk og Sara kraft til å grunnleggja ei ætt, og det trass i alderen sin, for ho heldt honom for trufast som hadde lova det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Difor vart det og av ein, og det ein utlivd, avla so mange som stjernorne på himmelen og som sanden på havsens strand, som ingen kann telja.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'I tru døydde alle desse, utan dei hadde nått det som var lova; men dei såg det langt burte, og helsa det og sanna at dei var framande og utlendingar på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'For dei som segjer slikt, dei syner at dei søkjer eit fedreland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Og dersom dei hadde tenkt på det som dei kom ifrå, so hadde dei havt tid til å fara dit att;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'men no stundar dei etter eit betre, det er eit himmelsk; difor skjemmest ikkje Gud ved deim, ved å kallast deira Gud; for han hev bygt ein by ferdig åt deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Ved tru ofra Abraham Isak, då han vart freista, ja, sin einborne ofra han som hadde fenge lovnaderne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'han som det var sagt til: «Etter Isak skal ætti di heita.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'For han tenkte at Gud var megtig endå til å vekkja upp ifrå dei daude, og han fekk honom liksom att derifrå.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Ved tru velsigna Isak Jakob og Esau med syn på det som skulde koma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Ved tru velsigna Jakob døyande kvar ein av Josefs søner og tilbad, bøygd yver knappen på staven sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Ved tru tala Josef på sitt siste um at Israels born skulde ganga ut, og gav påbod um beini sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Ved tru vart Moses, då han var fødd, gøymd av foreldri sine i tri månader, av di dei såg at det var so vænt eit barn, og dei var ikkje rædde for kongens bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Ved tru vilde Moses, då han vart stor, ikkje kallast dotterson til Farao,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'og valde heller å lida vondt saman med Guds folk, enn å hava ei stuttvarug njoting av syndi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'då han heldt Kristi vanære for større rikdom enn Egyptarlands skattar; for han såg fram til løni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Ved tru forlet han Egyptarland, urædd for kongens vreide; for han heldt ut som um han såg den usynlege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Ved tru heldt han påsken med utrenning av blodet, so tynaren ikkje skulde røra deira fyrstefødde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Ved tru gjekk dei gjenom Raudehavet liksom yver turt land; men då egyptarane freista på det same, drukna dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Ved tru fall Jerikos murar, då dei hadde gjenge kring deim i sju dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Ved tru slapp skjøkja Rahab å ganga under med dei vantruande, då ho hadde teke imot spæjarane med fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Og kvi talar eg meir? Tidi vilde verta meg for stutt, um eg skulde fortelja um Gideon og Barak og Samson og Jefta, um David og Samuel og profetarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'som ved tru sigra yver kongerike, heldt uppe rettferd, vann lovnader, tepte gapet på løvor,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'sløkte elds magt, slapp undan sverds egg, vart sterke att etter sjukdom, vart velduge i strid, fekk fiendeherar til å vika.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Kvinnor fekk sine daude att med di dei stod upp; andre vart utspana til pinsla med di dei ikkje vilde taka imot utløysing, so dei kunde vinna ei herlegare uppstoda;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'andre fekk røyna spotting og hudflengjing, ja endå til band og fengsel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Dei vart steina, gjenomsaga, freista, dei vart drepne med sverd, dei flakka ikring i sauskinn og geitskinn, leid naud og trengsla og hard medferd -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'dei som verdi ikkje var verd, drivande um i øydemarker og fjell og holor og jordklufter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Og endå alle desse fekk vitnemål for si tru, nådde dei ikkje lovnaden,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'etter di Gud fyreåt hadde set ut noko betre for oss, so dei ikkje skulde verta fullkomne utan oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'So lat no og oss, då me hev so stor ei sky av vitne ikring oss, leggja av alt som tyngjer, og syndi som heng so fast ved oss, og med tolmod renna i den kappstrid som er oss fyresett,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'med di me ser på upphavsmannen og fullendaren til trui, Jesus, han som for den gleda som var honom fyresett, bar krossen med tol, utan å vyrda skjemsla, og no sit på høgre sida åt Guds kongsstol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Ja, tenk på honom som tolde slik motsegn av syndarar imot seg, so de ikkje skal trøytna og verta modlause i hugen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Endå hev de ikkje gjort motstand til blods i striden mot syndi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'og de hev gløymt den påminning som talar til dykk som born: «Min son, vanmæt ikkje Herrens tukt, og vanmodast ikkje når han refser deg!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'for den Herren elskar, den tuktar han, og han hudflengjer kvar son som han tek seg av.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Det er for tukti skuld at de toler lidingar; Gud fer med dykk som med søner. For kven er den son som faren ikkje tuktar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Men er de utan tukt, som alle hev fenge sin lut i, då er de lausingar og ikkje søner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Dessutan: våre feder etter kjøtet hadde me til tuktarar og hadde age for deim; skal me då ikkje mykje meir vera faderen til ånderne undergjevne og få liva?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'For hine tukta oss nokre få dagar etter sitt tykkje, men han tuktar til vårt gagn, for at me skal verta luthavande i hans heilagskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Men all tukt synest vel, medan ho stend på, ikkje å vera til gleda, men til sorg; men sidan gjev ho deim som derved er upptamde, ei fred-rik frukt som er rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Difor, rett dei hangande hender og dei veike kne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Og gjer rette farvegar for føterne dykkar, so det halte ikkje skal skeiva ut, men heller vert lækt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Trå etter fred med alle og etter helging! for utan henne skal ingen sjå Herren.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Og sjå til at ingen dreg seg undan frå Guds nåde, at ingi beisk rot skal renna upp og gjera mein, og mange verta smitta ved henne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'at ingen må vera ein horkar eller ein vanheilag liksom Esau, som for ein einaste rett mat selde odelsretten sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'For de veit, at han og sidan, då han vilde erva velsigningi, vart burtvist - for han fann ikkje rom for bot - endå han søkte henne med tåror.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'For de er ikkje komne til eit fjell som ein kann taka på, og til brennande eld og til skydimma og myrker og uver');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'og til ljom av lur og til ljod av ord, som dei høyrande bad seg undan, at det ikkje måtte verta tala meir til deim;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'for dei kunde ikkje bera det ordet som baud: «Um det so berre er eit dyr som kjem innåt fjellet, skal det steinast.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Og so gruveleg var syni, at Moses sagde: «Eg er forfærd og skjelvande rædd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Men de er komne til Sions fjell og den livande Guds by, til det himmelske Jerusalem og til dei mange tusund englar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'til høgtidstemna og lyden av dei fyrstefødde, som er uppskrivne i himmelen, og til domaren som er Gud for alle, og til ånderne av dei fullenda rettferdige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'og til millommannen for ei ny pakt, Jesus, og til skvettings-blodet, som talar betre enn Abels blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Sjå til at de ikkje viser ifrå dykk honom som talar! For når hine ikkje slapp undan, som viste ifrå seg honom som tala på jordi, kor mykje mindre skal me då sleppa undan, um me vender oss ifrå honom som talar frå himmelen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Hans røyst riste den gong jordi; men no hev han lova og sagt: «Endå ein gong rister eg ikkje berre jordi, men himmelen med.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Men dette: «Endå ein gong» syner, at dei ting som vert riste, skal umskiftast, då det er skapte ting, so dei som ikkje vert riste, skal vara ved.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Lat difor oss som fær eit uruggelegt rike, vera takksame og dermed tena Gud til hans hugnad med blygd og otte!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'For vår Gud er ein øydande eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Lat broderkjærleiken vara ved!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Gløym ikkje gjestmilda! for ved den hev nokre havt englar til gjester, utan dei visste det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Kom i hug deim som er fangar, som var de deira medfangar, deim som lid vondt, sidan de og sjølve er i likamen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Egteskapet vere i agt og æra hjå alle, og egtesengi usmitta! for lauslivande og horkarar skal Gud døma.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Lat dykkar ferd vera utan pengehug, og ver nøgde med det de hev! for han hev sagt: «Eg skal so visst ikkje sleppa deg og ikkje slå handi av deg,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'so me hugheilt kann segja: «Herren er min hjelpar, eg vil ikkje ottast; kva kann eit menneskje gjera meg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Kom i hug dykkar forstandarar som hev tala Guds ord til dykk! sjå utgangen på deira ferd, og fylg so etter deira tru!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Kristus er i går og i dag den same, ja til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Lat dykk ikkje føra vilt av mangfaldige og framande lærdomar! for det er godt at hjarta vert styrkt ved nåden, ikkje ved mat, som ikkje hev gagna deim som for dermed.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Me hev eit altar som dei ikkje hev lov til å eta av, som tener ved tjeldet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'For dei dyr som blodet vert teke av og bore til soning for synd inn i heilagdomen ved øvstepresten, deira kroppar vert uppbrende utanfor lægret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Difor leid og Jesus utanfor porten, so han ved sitt eige blod kunde helga folket.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Lat oss då ganga ut til honom utanfor lægret, so me ber hans vanæra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'For me hev ikkje her ein varande by, men søkjer den komande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Lat oss då ved honom alltid bera fram til Gud lovoffer, det er: frukt av lippor som lovar hans namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Men gløym ikkje å gjera godt og gjeva andre med dykk! for slike offer hev Gud hugnad i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Fylg dykkar forstandarar og lyd deim! for dei vaker yver sjælerne dykkar som dei som skal gjera rekneskap, so dei kann gjera det med gleda og ikkje sukkande, for det er dykk ikkje til gagn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Bed for oss! for me trur at me hev eit godt samvit, og me vil gjerne fara rett åt i alle måtar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Og eg bed dykk so mykje meir um å gjera dette, so eg snarare kann verta gjeven dykk att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Men fredsens Gud, han som i kraft av æveleg pakts blod førde den store hyrding for sauerne, vår Herre Jesus, upp frå dei daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'han gjere dykk full-dugande i all god gjerning, so de gjer hans vilje, med di han verkar i dykk det som er til hugnad for honom, ved Jesus Kristus! Honom vere æra i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Eg bed dykk, brør, tak dette påminningsordet vel upp, for eg hev skrive stutt til dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Vit, at bror vår Timoteus er gjeven fri; saman med honom vil eg sjå dykk, um han kjem snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Helsa alle dykkar forstandarar og alle dei heilage! Dei frå Italia helsar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Nåden vere med dykk alle!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakob, Guds og Herren Jesu Kristi tenar, helsar dei tolv ætterne som er spreidde i framande land.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Haldt det for berre gleda, mine brør, når de kjem ut i ymse freistingar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'etter di de veit at prøvingi av dykkar tru verkar tolmod!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Men tolmodet må føra til fullkome verk, so de kann vera fullkomne og heile og ikkje vanta noko.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Men dersom nokon av dykk vantar visdom, so bede han Gud, han som gjev alle viljugt og utan vondord, og han skal få.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Men han må beda med tru og ikkje tvilande; for den som tvilar, er liksom havbåra, som vert rørd og rugga av vinden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'For ikkje må det menneskjet tru at han skal få noko av Herren,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'slik ein tvihuga mann, ustød på alle sine vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Men den låge broren rose seg av sin høgleik,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'og den rike av sin lågleik; for han skal kverva burt som blomen på graset:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Soli gjekk upp med sin hite og gjorde graset turt, og blomen på det fall av, og hans fagre åsyn vart øydelagd. Soleis skal og den rike visna på sine vegar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Sæl den mannen som held ut i freisting! for når han er prøvd, skal han få livsens kruna, som Gud hev lova deim som elskar honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ingen må segja når han vert freista: «Eg vert freista av Gud;» for Gud er ikkje freista av det vonde, og sjølv freistar han ingen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Men kvar ein vert freista når han vert dregen og lokka av si eigi lyst!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'sidan, når lysti vert med barn, ber ho synd; men når syndi er fullmogna, føder ho daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Far ikkje vilt, mine kjære brør!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'All god gåva og all fullkomi gåva kjem ovantil frå faderen til ljosi, han som det ikkje er umbrøyte ved eller skiftande skugge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Etter sin vilje hev han født oss ved sannings ord, so me skulde vera ei fyrstegrøde av hans skapningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Det veit de, kjære brør! Men kvart menneskje vere snar til å høyra, sein til å tala, sein til vreide,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'for ein manns vreide verkar ikkje det som er rett for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Legg difor av all ureinskap og alt som er att av vondskap, og tak med spaklynde imot ordet som er innplanta i dykk, og som er megtigt til å frelsa sjælerne dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Men vert slike som gjer etter ordet og ikkje berre høyrer det og dermed dårar dykk sjølve!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'For dersom nokon høyrer ordet og ikkje gjer etter det, då er han lik ein mann som skodar sitt naturlege andlit i ein spegel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'han skoda seg sjølv og gjekk burt og gløymde straks korleis han såg ut.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Men den som ser inn i fridomens fullkomne lov og held ved med det, so han ikkje vert ein gløymsam tilhøyrar, men ein som gjer gjerningi, han skal vera sæl i si gjerning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Dersom nokon meiner at han er ein gudsdyrkar, og ikkje tøymer tunga si, men dårar sitt eige hjarta, hans gudsdyrking er fåfengd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Ei rein og lytelaus gudsdyrking for Gud og Faderen er dette: å sjå til faderlause og enkjor i deira trengsla, å halda seg sjølv uflekka av verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mine brør! Lat ikkje dykkar tru på vår Herre Jesus Kristus, den herleggjorde, hava det med seg, at de gjer skil på folk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'For um det kjem ein mann inn i dykkar samling med gullring på fingeren og i skinande klæde, men det og kjem ein fatigmann i skitne klæde,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'og de ser på honom som hev den skinande klædnaden, og segjer til honom: «Set du deg her i god sess!» og de segjer til den fatige: «Statt du der, eller set deg nedfor fotskammelen min!» -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'gjer de ikkje då skilnad hjå dykk sjølve og dømer etter vonde tankar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Høyr no, mine kjære brør! Hev ikkje Gud valt ut dei fatige i denne verdi til å vera rike i tru og ervingar til det riket han hev lova deim som honom elskar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Men de hev vanæra den fatige. Er det ikkje dei rike som trælkar dykk, og som dreg dykk fram for domstolarne?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Spottar ikkje dei det gode namnet som de er kalla med?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'I sanning, um de uppfyller den kongelege lov etter skrifti: «Du skal elska din næste som deg sjølv,» so gjer de vel;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'men gjer de skil på folk, so gjer de synd, og lovi refser dykk som lovbrjotarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'For den som held heile lovi, men snåvar i ein ting, han hev vorte saka i alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'For han som sagde: «Du skal ikkje driva hor,» han sagde og: «Du skal ikkje slå i hel.» Um du då ikkje driv hor, men slær i hel, so hev du vorte ein lovbrjotar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tala so og gjer so som dei som skal verta dømde etter fridoms lov!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'For domen skal vera miskunnlaus yver den som ikkje hev gjort miskunn; men miskunn rosar seg mot domen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Kva gagnar det, mine brør, um nokon segjer at han hev tru, når han ikkje hev gjerningar? Kann vel trui frelsa honom?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Um ein bror eller ei syster er nakne og vantar føda for dagen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'og ein av dykk segjer til deim: «Gakk i fred, verm dykk og et dykk mette!» men de ikkje gjev deim det som likamen treng, kva gagnar so det?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Soleis og med trui: hev ho ikkje gjerningar, so er ho daud i seg sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Men ein kann segja: «Du hev tru, og eg hev gjerningar. Syn meg di tru utan gjerningar, og eg skal syna deg mi tru av mine gjerningar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du trur at Gud er ein; du gjer rett. Djevlarne trur og det og skjelv.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Og vil du vita det, du dårlege menneskje, at trui er nyttelaus utan gjerningar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham, vår far, vart ikkje han rettferdiggjord ved gjerningar, då han ofra Isak, son sin, på altaret?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Du ser at trui verka saman med hans gjerningar, og at trui vart fullkomi ved gjerningarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'og skrifti vart uppfyllt, som segjer: «Men Abraham trudde Gud, og det vart rekna honom til rettferd,» og han vart kalla Guds ven.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'De ser då, at eit menneskje vert rettferdiggjort ved gjerningar og ikkje berre ved tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Like eins og med skjøkja Rahab: vart ho ikkje rettferdiggjord ved gjerningar, då ho tok imot sendemennerne og slepte deim ut ein annan veg?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'For liksom likamen er daud utan ånd, so er og trui daud utan gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mine brør, ikkje mange av dykk verte lærarar! etter di de veit at me skal få dess tyngre dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'For alle snåvar me i mangt. Den som ikkje snåvar i tale, han er ein fullkomen mann, som er før til å tøyma heile likamen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Når me legg beisl i munnen på hestarne, so dei skal lystra oss, so styrer me og heile likamen deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Sjå og skipi: endå dei er so store og vert drivne av sterk vind, so vert dei då med ein liten ror styrde dit som styremannen vil hava deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'So er og tunga ein liten lem, og talar då store ord. Sjå ein liten eld: kor stor ein skog han set i brand!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Tunga er og ein eld; ei verd full av urettferd, soleis stend tunga millom lemerne våre; ho smittar heile likamen og set livsens hjul i loge, og vert sjølv sett i loge frå helvite.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'For all natur, både i dyr og fuglar, både i ormar og sjødyr, vert tamd og hev vorte tamd av den menneskjelege natur;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'men tunga kann inkje menneskje temja; ho er ein ustyrleg vond ting, full av døyande eiter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Med henne velsignar me Herren og Faderen, og med henne bannar me menneski som er skapte etter Guds bilæte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Or same munnen kjem det velsigning og banning. Dette må ikkje vera so, mine brør!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Kann då kjelda gjeva søtt og beiskt vatn ut or same uppkoma?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Mine brør, kann då eit fiketre bera oljebær, eller eit vintre fikor? So kann ikkje heller ei salt kjelde gjeva søtt vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kven er vis og vitug imillom dykk? Han må ved god ferd syna sine gjerningar i visdoms spaklynde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Men hev de beisk ovund og stridssykja i hjarto dykkar, so rosa dykk ikkje og ljug ikkje imot sanningi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Den visdomen kjem ikkje ovantil, men er jordisk, sanseleg, djevelsk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'For der det er ovund og stridssykja, der er ugreida og alt det som vondt er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Men visdomen ovantil, han er fyrst og fremst rein, og dinæst fredsam, rimeleg, ettergjevande, full av miskunn og gode frukter, fri for tvil og fri for skrymt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Men rettferds frukt vert sådd i fred for deim som held fred.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Kva kjem all ufred og strid av millom dykk? Er det ikkje av dykkar lyster, som strider i lemerne dykkar?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'De lystar og hev ikkje; de slær i hel og ovundast og kann ikkje få; de ligg i strid og ufred. De hev ikkje, av di de ikkje bed;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'de bed og fær ikkje, av di de bed ille, um slikt som de kann øyda upp i dykkar lyster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'De utrugne! veit de ikkje at venskap med verdi er fiendskap imot Gud? Den som då vil vera ven med verdi, han vert Guds fiende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Eller trur de at skrifti talar fåfengt? Med brennhug trår han etter Anden som han hev late bu i oss. Men di større er den nåde som han gjev.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Difor heiter det: «Gud stend dei stolte imot, men dei audmjuke gjev han nåde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Ver difor Gud undergjevne! Men statt djevelen imot, so skal han fly frå dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Haldt dykk nær til Gud, so skal han halda seg nær til dykk! Reinsa henderne, de syndarar, og gjer hjarto reine, de tvihuga!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Kjenn dykkar naud og syrg og gråt! Lat låtten dykkar vendast til sorg, og gleda til trege.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Audmyk dykk for Herren, so skal han upphøgja dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Baktala ikkje kvarandre, brør! Den som baktalar ein bror eller dømer bror sin, han baktalar lovi og dømer lovi; men dømer du lovi, so er du ikkje ein som gjer etter lovi, men hennar domar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Ein er lovgjevaren og domaren, han som er megtig til å frelsa og til å tyna. Men du, kven er du som dømer din næste?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Og no, de som segjer: «I dag eller i morgon vil me fara til den byen og vera der eit år og handla og hava vinning,»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'de som ikkje veit kva som skal henda i morgon! For kva er livet dykkar? De er ein eim som ei liti stund er synleg og so kverv burt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'I staden for at de skulde segja: «Um Herren vil, so kjem me til å liva, og so skal me gjera det eller det!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Men no rosar de dykk sjølve i dykkar storlæte. All slik ros er vond.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Den som då veit å gjera godt, men ikkje gjer det, han hev synd for det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Og no, de rike, gråt og barma dykk for den ulukka som skal koma på dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Rikdomen dykkar er rotna, og klædi dykkar er mol-etne;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'gullet og sylvet dykkar er burtrusta, og rusti på det skal vera til vitne imot dykk og eta dykkar kjøt som ein eld. De hev sanka skattar i dei siste dagarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Sjå, den løni de hev halde att for dei arbeidarar som hev skore åkrane dykkar, ho ropar, og ropet frå skurdfolket er kome inn for Herren Sebaots øyro.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'De hev livt på jordi i kjæla og etter lysterne dykkar; de hev gjødt hjarto dykkar på slagtardagen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'De hev domfelt og drepe den rettferdige; ingen gjer motstand imot dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Ver då tolmodige, brør, til Herren kjem! Sjå, bonden ventar på den dyre avlingi av jordi og stundar tolmodeleg på henne, til ho fær haustregn og vårregn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'So ver de og tolmodige og styrk dykkar hjarto! for Herrens tilkoma er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Sukka ikkje mot kvarandre, brør, so de ikkje skal verta dømde! Sjå, domaren stend for døri!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Mine brør! tak profetarne, som tala i Herrens namn, til fyredøme på å lida vondt og vera tolmodige!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Sjå, me prisar deim sæle som lid tolmodeleg. De hev høyrt um Jobs tolmod og set endelykti frå Herren; for Herren er inderleg miskunnsam og mild.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Men framfor alt, brør, sver ikkje, korkje ved himmelen eller ved jordi eller nokon annan eid! Lat dykkar ja vera ja og dykkar nei vera nei, so de ikkje skal falla inn under domen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Lid nokon av dykk vondt, han bede! er nokon ved godt mod, han lovsyngje!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Er nokon av dykk sjuk, han kalle til seg dei eldste i kyrkjelyden, og dei skal beda yver honom og salva honom med olje i Herrens namn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'og den bøni av tru skal hjelpa den sjuke, og Herren skal reisa honom upp; og hev han gjort synder, skal dei verta honom forlatne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Sanna då synderne dykkar for kvarandre, og bed for kvarandre, so de kann verta lækte! Rettferdig manns bøn hev stor magt i sin verknad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elia var ein mann under same vilkår som me; og han bad at det ikkje skulde regna, og det regnde ikkje på jordi på tri år og seks månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Og han bad på nytt, og himmelen gav regn, og jordi bar si grøda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Mine brør! Um nokon av dykk hev fare vilt frå sanningi, og nokon umvender honom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'han skal vita, at den som umvender ein syndar frå hans ville veg, han frelser ei sjæl frå dauden og løyner ei mengd med synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Peter, Jesu Kristi apostel, til dei utlendingar som er spreidde i Pontus, Galatia, Kappadokia, Asia og Bitynia, utvalde');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'etter Gud Faders fyrevitende ved Andens helging til lydnad og yverskvetting med Jesu Kristi blod: Nåde og fred vere med dykk i rikt mål!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Lova vere Gud og vår Herre Jesu Kristi Fader, han som etter si store miskunn hev atterfødt oss til ei livande von ved Jesu Kristi uppstoda frå dei daude,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'til ein uforgjengeleg og flekklaus og uvisneleg arv, som er gøymd i himmelen åt dykk,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'de som ved Guds magt vert upphaldne ved trui til den frelsa som er ferdig til å verta openberra i den siste tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Det gled de dykk yver, um de og no ei lita stund - når so skal vera - er sorgtyngde i ymse freistingar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'so dykkar prøvde tru, som er mykje kostelegare enn det forgjengelege gull, som de veit vert prøvt i eld, må verta funni til lov og pris og æra i Jesu Kristi openberring,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'han som de ikkje hev kjent, men endå elskar, han som de no ikkje ser, men endå trur på og gled dykk med usegjeleg og herleggjord gleda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'når de vinn fram til målet for trui, frelsa for sjælerne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Um denne frelsa var det profetarne granska og grunda, dei som spådde um den nåde de skulde få,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'med di dei grunda på kva tid eller kva slag tid Kristi Ande som var i deim, viste fram til, når han vitna fyreåt um Kristi lidingar og um herlegdomen deretter;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'for det var deim openberra, at dei tente ikkje seg sjølve, men oss med dette som no er kunngjort dykk ved deim som hev forkynt dykk evangeliet ved den Heilage Ande, som vart send frå himmelen - dette som englarne hev hug til å skoda inn i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Difor, umgyrd dykkar hugs lender, ver ædrue og set dykkar von fullt og fast til den nåde som de fær tilførd ved Jesu Kristi openberring!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Som lyduge born skal de ikkje skikka dykk etter dei fyrre lysterne i dykkar vankunna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'men ver, etter den Heilage som kalla dykk, ogso de heilage i all dykkar ferd!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'for det stend skrive: «De skal vera heilage, for eg er heilag!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Og når de påkallar honom som Fader, som dømer utan å gjera skilnad, etter kvar manns gjerning, so ferdast med otte den tid de liver i utlendingskapen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'for de veit at de ikkje med forgjengelege ting, sylv eller gull, vart frikjøpte frå dykkar fåfengde ferd, som de hadde ervt ifrå federne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'men med Kristi dyre blod, som blodet av eit ulastelegt og lytelaust lamb.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Han var kjend fyreåt, fyrr verdi vart grunnlagd, men vart openberra i dei siste tider for dykkar skuld,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'de som ved honom trur på Gud, som vekte honom upp frå dei daude og gav honom herlegdom, so trui dykkar og er von til Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Reinsa sjælerne dykkar i lydnad mot sanningi til uskrymta broderkjærleik, og elska kvarandre inderleg av hjarta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'de som er atterfødde, ikkje av forgjengelegt, men uforgjengelegt sæde, ved Guds ord, som liver og varer!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'For alt kjøt er som gras, og all herlegdomen hjå det som blom på gras. Graset visna, og blomen på det fall av.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Men Herrens ord varer i all æva. Dette er det ordet som er forkynt for dykk ved evangeliet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Legg difor av all vondskap og alt svik og hyklarskap og ovund og all baktale,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'og lengta liksom nyfødde born etter den åndelege, ufalska mjølk, so de kann veksa ved henne til frelsa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'so framt de då hev smaka at Herren er god!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Kom til honom, den livande steinen, som vel vart vanda av menneskje, men er utvald og dyrverdig for Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'og vert de sjølve, som livande steinar, uppbygde til eit åndelegt hus, eit heilagt presteskap, til å bera fram åndelege offer til hugnad for Gud ved Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'For det heiter i skrifti: «Sjå, eg legg i Sion ein hyrnestein, som er utvald og dyrverdig, og den som trur på honom, skal slett ikkje verta til skammar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Dykk då som trur, høyrer æra til; men for dei vantruande hev den steinen som bygningsmennerne vanda, vorte til hyrnestein og snåvestein og støyteberg,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'dei som støyter seg med di dei ikkje trur ordet, som dei og var etla til.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Men de er ei utvald ætt, eit kongelegt presteskap, eit heilagt folk, eit folk til eigedom, so de skal forkynna hans dygder som kalla dykk ut or myrker til sitt underfulle ljos,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'de som fyrr ikkje var eit folk, men no er Guds folk, de som ikkje hadde funne miskunn, men no hev fenge miskunn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Kjære, eg legg dykk på hjarta som framande og utledningar, at de skal halda dykk ifrå dei kjøtlege lyster, som strider imot sjæli,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'og lata dykkar ferd millom heidningarne vera god, so dei, medan dei baktalar dykk som illgjerdsmenner, må sjå dykkar gode gjerningar og for deira skuld prisa Gud på tilsynsdagen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Ver difor all menneskjeleg skipnad undergjevne for Herrens skuld, anten det er kongen som den høgste,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'eller landshovdingar som utsendingar frå honom til refsing for deim som gjer vondt, men til ros for deim som gjer godt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'For soleis er det Guds vilje, at de med å gjera det gode skal målbinda vankunna hjå uvituge menneskje,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'so som frie, og ikkje slike som hev fridomen til vondskaps skyle, men som Guds tenarar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, '\'ra alle, elska broderlaget, ottast Gud, æra kongen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'De tenarar, ver dykkar herrar undergjevne i all age, ikkje berre dei gode og milde, men og dei rangvise!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'For det finn nåde, um nokon av samvit for Gud toler harmingar som han lid uretteleg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'For kva er det for ei ros, um de tek det med tolmod når de syndar og fær refsing for det? Men um de tek det med tolmod når de gjer godt og endå lyt lida, det finn nåde hjå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'For til det vart de kalla, av di Kristus og leid for dykk og let etter for dykk eit fyredøme, so de skal fylgja hans fotfar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Han gjorde ikkje synd, og det fanst ikkje heller svik i hans munn;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'han skjelte ikkje att når han vart utskjelt, ikkje truga ham når han leid, men gav det yver til honom som dømer rettferdigt;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'han bar synderne våre på likamen sin upp på treet, so me skal døy av frå synderne våre og liva for rettferdi, då de er lækte ved hans sår.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'For de var villfarande som sauer, men hev no vendt um til hyrdingen og tilsynsmannen for sjælerne dykkar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Like eins de konor: De skal vera dykkar eigne menner undergjevne, so endå slike som ikkje trur ordet, må verta vunne utan ord ved den ferd konorne deira syner,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'når dei ser for augo dykkar reine ferd i otte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Deira prydnad skal ikkje vera utanpå, med hårflettingar eller påhengt gull eller klædebunad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'men hjartans løynde menneskje i den uforgjengelege prydnad med den mjuke og stille ånd, som er gjæv for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'For soleis prydde fordom dei heilage kvinnorne seg, dei som sette si von til Gud og var sine eigne menner undergjevne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'liksom Sara lydde Abraham og kalla honom herre; hennar døtter hev de vorte når de gjer godt og ikkje ottast for nokor skræmsla.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Like eins de menner: De skal liva vitugt saman med konorne som det veikare kjerald, og visa deim æra, sidan dei og er medervingar til livsens nåde, so dykkar bøner ikkje skal verta hindra!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Og til slutt: Ver alle samhuga, medlidande, kjærlege mot brørne, miskunnsame, audmjuke!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Løn ikkje vondt med vondt eller skjelling med skjelling, men tvertimot velsigna! for det vart de kalla til, at de skal erva velsigning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'For «den som vil elska livet og sjå gode dagar, han skal halda tunga frå det som vondt er og lipporne frå svikfull tale;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'han vike frå vondt og gjere godt, han søkje fred og trå etter honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'For Herrens augo er yver dei rettferdige, og hans øyro vende til deira bøn; men Herrens åsyn er yver deim som gjer vondt.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Og kven er det som kann gjera dykk vondt når de stræver etter det gode?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Men um de og skulde lida for rettferds skuld, so er de sæle. Men ottast ikkje for deim og ræddast ikkje; men helga Kristus til herre i hjarto dykkar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Og ver alltid ferdige til å forsvara dykk for kvar ein som krev rekneskap av dykk for den voni som bur i dykk, men med spaklynde og age!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Og hav eit godt samvit, so dei som lastar dykkar gode ferd i Kristus, må verta til skammar i det som dei baktalar dykk for som illgjerdsmenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'For det er betre, um so er Guds vilje, å lida når ein gjer godt, enn når ein gjer vondt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'For Kristus leid og ein gong for synder, ein rettferdig for urettferdige, for å føra oss fram til Gud, han som leid dauden i kjøtet, men vart livandegjord i åndi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'og i denne gjekk han og burt og preika for ånderne som var i varetekt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'dei som fordom hadde vore stride, den gong Guds langmod venta i Noahs dagar, då arki vart bygd, der nokre få, det er åtte sjæler, vart frelste gjenom vatn,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'det som no og frelser oss i motbilætet dåpen, som ikkje er avleggjing av ureinskap på kroppen, men eit godt samvits pakt med Gud ved Jesu Kristi uppstoda,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'han som er uppfaren til himmelen og er ved Guds høgre hand, der englar og magter og krafter er honom underlagde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Sidan no Kristus hev lide i kjøtet, so væpna og de dykk med den same tanken, at den som hev lide i kjøtet, er ferdig med syndi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'so de ikkje lenger skal liva etter menneskje-lyster, men etter Guds vilje, den tid de endå skal vera i kjøtet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'For det er nok at de i den framfarne livstid hev gjort det som heidningarne vil, med di de ferdast i used, lyster, fullskap, svir, drykk og usømeleg avgudsdyrking;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'difor undrast dei når de ikkje renner med deim ut i den same straum av skamløysa, og dei spottar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Men dei skal gjera rekneskap for honom som held seg ferdig til å døma livande og daude.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'For dertil vart evangeliet forkynt ogso for daude, at dei vel skulde verta dømde som menneskje i kjøt, men liva so som Gud i ånd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Men enden på alle ting er komen nær. Ver difor vislege og ædrue til bøner!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Og hav framfor alt inderleg kjærleik til kvarandre! for kjærleiken løyner ei mengd med synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Ver gjestmilde mot kvarandre utan murring!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Etter som kvar hev fenge ei nådegåva, so ten kvarandre med henne som gode hushaldarar yver Guds mangfaldige nåde!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Um nokon talar, han tale som Guds ord, um nokon tener i kyrkjelyden, han tene som av den kraft Gud gjev, so Gud må verta æra i alle ting ved Jesus Kristus, som æra og magti høyrer til i all æva. Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'De kjære! Undra dykk ikkje yver den elden som kjem yver dykk til prøving, som um det hende dykk noko underlegt!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Men i same mun som de hev lut i Kristi lidingar, skal de gleda dykk, so de og kann gleda dykk med fagnad når hans herlegdom vert openberra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Dersom de vert hædde for Kristi namn skuld, er de sæle; for Herlegdoms-Anden og Guds Ande kviler yver dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'For ingen av dykk må lida av di han er mordar eller tjuv eller illgjerningsmann, eller av di han blandar seg i framande målemne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Men lid han av di han er ein kristen, so skal han ikkje skjemmast, men prisa Gud for dette namnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'For det er no den tid då domen skal taka til med Guds hus; men tek det til med oss, kva vert då enden for deim som ikkje vil tru Guds evangelium?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Og dersom den rettferdige vandt vert frelst, kvar skal det då verta av den ugudlege og syndaren?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Difor skal og dei som lid etter Guds vilje, gjeva yver sjælerne sine til den trufaste skaparen, med di dei gjer det gode.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Dei eldste millom dykk legg eg på hjarta, eg som sjølv er med-eldste og vitne um Kristi lidingar, som og hev lut i den herlegdomen som skal openberrast:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Gjæt den Guds hjord som er hjå dykk, og hav tilsyn med henne, ikkje av tvang, men sjølvminnt, ikkje for ei skamleg vinning, men med hug,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'ikkje heller so at de vil vera herrar yver kyrkjelydarne, men so at de vert fyredøme for hjordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Når yverhyrdingen openberrast, då skal de få den uvisnelege ærekransen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Like eins skal de yngre vera dei eldre undergjevne, og alle skal de klæda dykk i audmykt mot kvarandre; for Gud stend dei stolte imot, men dei audmjuke gjev han nåde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'So audmyk dykk då under Guds velduge hand, so han kann upphøgja dykk i si tid!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Kasta all dykkar sut på honom; for han hev umsut for dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Ver ædrue, vak! Dykkar motstandar djevelen gjeng ikring som ei burande løva og søkjer kven han kann gløypa;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'statt honom imot, trauste i trui, sidan de veit at dei same lidingar er lagde på brørne dykkar i verdi!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Men all nådes Gud, som kalla dykk til sin ævelege herlegdom i Kristus Jesus etter ei stuttvarug liding, han skal gjera dykk full-dugande, stadfesta, styrkja, grunnfesta dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Honom høyrer magti til i all æva. Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Med Silvanus, den trufaste broren - det meiner eg han er - skriv eg stutt til dykk og påminner og vitnar at dette er Guds sanne nåde, som de stend i.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Den medutvalde kyrkjelyden i Babylon helsar dykk, like eins Markus, son min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Helsa kvarandre med kjærleiks kyss! Fred vere med alle dykk som er i Kristus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simeon Peter, Jesu Kristi tenar og apostel, til deim som hev fenge same dyre tru som me ved vår Gud og frelsar Jesu Kristi rettferd:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Nåde og fred vere med dykk i rikt mål, med di de kjenner Gud og Jesus, vår Herre!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Etter som hans guddomlege magt hev gjeve oss alt som høyrer til liv og gudlegdom, ved kunnskapen um honom som kalla oss ved sin eigen herlegdom og si kraft,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'og dermed hev gjeve oss dei største og dyraste lovnader, for at de ved deim skulde verta luthavande i guddomleg natur, med di de flyr frå den tyning i verdi som kjem av lysti:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'so gjer dykk og just difor all umak, og vis i trui dykkar dygd, og i dygdi skynsemd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'og i skynsemdi fråhald, og i fråhaldet tolmod, og i tolmodet gudlegdom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'og i gudlegdomen broderkjærleik, og i broderkjærleiken kjærleik til alle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'For når desse ting finst hjå dykk og fær veksa, då viser dei at de ikkje er yrkjelause eller fruktlause i kunnskapen um vår Herre Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'For den som ikkje hev desse ting, han er blind, dimsynt og hev gløymt reinsingi frå sine fyrre synder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Difor, brør, legg so mykje meir vinn på å gjera dykkar kall og utveljing fast; for når de gjer desse ting, skal de ikkje nokon gong snåva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'For soleis skal det rikleg verta gjeve dykk inngang i vår Herre og frelsar Jesu Kristi ævelege rike.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Difor kjem eg alltid til å minna dykk um dette, endå de veit det og er grunnfeste i den sanning som er hjå dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Like vel held eg det for rett å vekkja dykk ved påminning, so lenge eg er i denne hytta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'sidan eg veit at eg brått skal leggja ned hytta mi, so som og vår Herre Jesus Kristus hev varsla meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Men eg vil og leggja vinn på at de alltid etter min burtgang kann minnast dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'For det var ikkje klokt uttenkte eventyr me fylgde, då me kunngjorde dykk vår Herre Jesu Kristi magt og tilkoma, men me hadde vore augvitne til hans storvelde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'For han fekk æra og herlegdom av Gud Fader, ei slik røyst kom til honom frå den høgste herlegdomen: «Dette er son min, som eg elskar, som eg hev hugnad i.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Og denne røysti høyrde me koma frå himmelen, då me var saman med honom på det heilage fjellet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Og dess fastare hev me det profetiske ordet, og de gjer vel i å agta på det som på eit ljos som skin på ein myrk stad, til dess dagen lyser fram, og morgonstjerna renn upp i hjarto dykkar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'men di de fyrst og fremst veit dette, at inkje profetord i skrifti er gjeve til eigi tyding.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'For aldri er noko profetord framkome av mannevilje; men dei heilage Guds menner tala, drivne av den Heilage Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Men det stod og falske profetar fram hjå folket, liksom det og hjå dykk skal koma falske lærarar, som skal lura inn ranglæror som fører til fortaping, med di dei jamvel neittar den Herre som kjøpte deim, og fører yver seg sjølve ei brå fortaping.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Og mange skal fylgja deim i deira used, og for deira skuld skal sanningsvegen verta spotta,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'og av havesykja skal dei med uppdikta ord nytta dykk ut til vinning. Men domen er frå gamall tid ikkje yrkjelaus mot deim, og deira fortaping søv ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'For so visst som Gud ikkje sparde englar då dei synda, men støytte deim ned i avgrunnen og gav deim yver til myrke holor i varetekt til dom,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'og ikkje sparde den gamle verdi, men heldt uppe rettferds-forkynnaren Noah sjølv-åttande, då han førde storflodi yver ei verd av ugudlege,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'og lagde byarne Sodoma og Gomorra i oska og fordømde deim til undergang og dermed sette deim til fyredøme på dei ugudlege i framtidi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'og fria ut den rettferdige Lot, som leid under den skamlause åtferdi av dei ugudlege');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '- for den rettferdige som budde imillom deim, leid dagstødt pinsla i si rettferdige sjæl ved dei lovlause gjerningar som han såg og høyrde -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'so veit Herren å fria dei gudlege ut or freisting, men halda dei urettferdige i varetekt med refsing til domedag,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'mest deim som fer etter kjøtet i urein lyst og vanvyrder herredøme. Dei sjølvgode vågehalsar! Dei skjelv ikkje ved å spotta høge magter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'medan då englar, som er større i styrke og magt, ikkje ber fram for Herren nokon spottande dom imot deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Men desse, liksom vitlause dyr, av naturi fødde til fanging og undergang, dei skal, av di dei spottar det dei ikkje kjenner, gagna under ved si eigi uferd');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'og få urettferds løn. Dei set si lyst i å bruka dagen til kjæla; dei utskjemmor og skamflekkjer; dei kræser seg ved sitt svik når dei held gilde med dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Augo hev dei som er fyllte av skjøkja og umetteleg i synd; dei forlokkar ustøde sjæler; dei hev eit hjarta som er upptamt i havesykja, dei forbanningsborn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Dei hev vike av frå den beine vegen og fare vilt, med di dei hev fylgt Bileam Beorssons veg, han som elska urettferds løn');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'og fekk refsing for sitt eige brot: eit umælande klyvdyr tala med mannemæle til honom og hindra profeten i hans uvitingskap.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Desse er vatslause kjeldor, skodda som vert drivi av stormvind; til deim er kolmyrket ferdigt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'For med di dei talar skrøytande, tome ord, forlokkar dei i kjøtslyster ved ukjurskap deim som nett hev flytt ifrå deim som fer i villa,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'med di dei lovar deim fridom, dei som sjølve er trælar under tjon; for det som ein ligg under for, det hev han og vorte træl for.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'For um dei hev flytt ifrå ureinskapen i verdi med di dei hev lært å kjenna vår Herre og frelsar Jesus Kristus, og so atter vert innfløkte i henne og ligg under, då hev det siste vorte verre med deim enn det fyrste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'For det var betre for deim at dei ikkje hadde kjent rettferds veg, enn at dei kjende honom og so vende seg burt att frå det heilage bodet som var yvergjeve deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Det hev gjenge deim etter det sanne ordtøket: «Ein hund vendar atter til si eigi spya,» og: «Ei lauga su velter seg i søyla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Dette er no alt det andre brevet eg skriv til dykk, de kjære, og i deim ved påminning vekkjer dykkar reine hug');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'til å minnast dei ord som fyrr er tala av dei heilage profetar, og bodet frå Herren og frelsaren som apostlarne dykkar hev forkynt,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'med di de fyrst og fremst veit dette, at i dei siste dagar skal det koma spottarar med spott, som gjeng etter sine eigne lyster');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'og segjer: «Kvar er lovnaden um hans tilkoma? For ifrå den tid då federne sovna av, stend alt so som frå upphavet av skapningen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'For dei som segjer so, gløymer at himlar var det frå gamall tid og ei jord som hadde vorte til ut av vatn og gjenom vatn ved Guds ord,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'og dermed gjekk og den dåverande verdi under i vatsflaumen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Men dei noverande himlar og jordi er ved det same ordet sparde til elden, og upphaldne til den dagen då dei ugudlege menneskje skal verta dømde og fortapte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Men dette eine må de ikkje sleppa or syne, mine kjære, at ein dag er for Herren som tusund år, og tusund år som ein dag.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Herren er ikkje langdrygjen med lovnaden, so som sume held det for ei drygjing; men han er langmodig med dykk, då han ikkje vil at nokon skal verta fortapt, men at alle skal koma til umvending.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Men Herrens dag skal koma som ein tjuv; då skal himlarne forgangast med dundrane ljom, og himmelklotarne skal koma i brand og verta uppløyste, og jordi og alle verk på henne verta uppbrende.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Då no alt dette vert uppløyst, kor må ikkje de då stræva etter heilag ferd og gudlegt liv,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'medan de ventar og skundar på at Guds dag skal koma, som skal gjera at himlarne vert uppløyste i eld, og himmelklotarne kjem i brand og brånar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Men me ventar etter hans lovnad nye himlar og ei ny jord, der rettferd bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Difor, mine kjære, då de ventar dette, so legg vinn på at de kann verta funne utan flekk og lyte for hans åsyn i fred!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Og agta det langmod vår Herre viser, som ei frelsa, som og vår kjære bror Paulus hev skrive til dykk etter den visdom som han hev fenge,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'liksom og i alle sine brev når han i deim talar um desse ting; i deim er det noko som er vandt å skynda, som ulærde og ustøde mistyder, liksom dei og gjer med dei andre skrifterne, til sin eigen undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'So må då de, mine kjære, som fyreåt veit dette, vara dykk, so de ikkje skal verta dregne med i villa av dei ugudlege og falla frå dykkar eigen faste grunn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Men veks i nåde og kjennskap til vår Herre og frelsar Jesus Kristus! Honom vere æra både no og til æveleg tid! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Det som var ifrå upphavet, det som me hev høyrt, det som me hev set med augo våre, det som me skoda, og henderne våre tok på, um livsens ord');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '- og livet vart openberra, og me hev set det og vitnar og forkynner dykk livet, det ævelege, som var hjå Faderen og vart openberra for oss -');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'det som me hev set og høyrt, det forkynner me dykk og, so de kann hava samfund med oss. Men vårt samfund er med Faderen og med hans son Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Og dette skriv me, so dykkar gleda kann vera fullkomi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Og dette er den bodskapen me hev høyrt av honom og forkynner dykk, at Gud er ljos, og det finst inkje myrker i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Dersom me segjer at me hev samfund med honom, og me ferdast i myrkret, so lyg me og gjer ikkje sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Men dersom me ferdast i ljoset, liksom han er i ljoset, so hev me samfund med kvarandre, og Jesu, hans sons, blod reinsar oss frå all synd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Dersom me segjer at me ikkje hev synd, so dårar me oss sjølve, og sanningi er ikkje i oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Dersom me sannar synderne våre, so er han trufast og rettferdig, so han forlet oss synderne og reinsar oss frå all urettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Dersom me segjer at me ikkje hev synda, so gjer me honom til ljugar, og hans ord er ikkje i oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mine born! Dette skriv eg til dykk so de ikkje skal synda, og um nokon syndar, so hev me hjå Faderen ein målsmann, Jesus Kristus, den rettferdige,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'og han er ei soning for synderne våre, og ikkje berre for våre, men og for alle i heile verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Og på dette veit me at me kjenner honom: um me held bodi hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Den som segjer: «Eg kjenner honom», og ikkje held bodi hans, han er ein ljugar, og i honom er ikkje sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Men den som held ordet hans, i honom er i sanning kjærleiken til Gud fullkomen. På dette kjenner me at me er i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Den som segjer at han er i honom, han er og skuldig til å ferdast so som han hev ferdast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'De kjære! det er ikkje eit nytt bod eg skriv åt dykk, men eit gamalt bod, som de hev havt ifrå upphavet. Det gamle bodet er det ordet de hev høyrt ifrå upphavet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Og like vel er det eit nytt bod eg skriv åt dykk, og det er sant i honom og i dykk; for myrkret kverv burt, og det sanne ljoset skin alt no.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Den som segjer at han er i ljoset, og som hatar bror sin, han er endå i myrkret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Den som elskar bror sin, han er i ljoset, og i honom finst det ikkje noko som fører til fall.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Men den som hatar bror sin, han er i myrkret og ferdast i myrkret, og han veit ikkje kvar han gjeng; for myrkret hev blinda augo hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Eg skriv til dykk, born, for synderne er dykk forlatne for hans namn skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Eg skriv til dykk, feder, for de kjenner honom som er frå upphavet. Eg skriv til dykk, ungdomar, for de hev sigra yver den vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Eg hev skrive til dykk, born, for de kjenner Faderen. Eg hev skrive til dykk, feder, for de kjenner honom som er frå upphavet. Eg hev skrive til dykk, ungdomar, for de er sterke, og Guds ord vert verande i dykk, og de hev sigra yver den vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Elska ikkje verdi, og ikkje dei ting som er i verdi! Um nokon elskar verdi, so er ikkje kjærleiken til Faderen i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'For alt det som er i verdi: kjøtslyst og augnelyst og storlæte i livnad, det er ikkje av Faderen, men av verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Og verdi og hennar lyst forgjengst; men den som gjer Guds vilje, han vert verande til æveleg tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Born! Det er den siste timen; og som de hev høyrt at Antikrist kjem, so er no mange anti-kristar komne, og på det skynar me at det er den siste timen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Dei er gjengne ut ifrå oss, men dei var ikkje av oss; for hadde dei vore av oss, so hadde dei vorte verande hjå oss; men det skulde verta synbert at ikkje alle er av oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Og de hev salving av den Heilage og veit alt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Eg skreiv ikkje til dykk av di de ikkje kjenner sanningi, men av di de kjenner henne, og veit at all lygn ikkje er av sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kven er ljugaren, utan han som neittar at Jesus er Kristus? Han er Antikrist, han som neittar Faderen og Sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Kvar den som neittar Sonen, han hev ikkje Faderen heller; den som vedkjennest Sonen, han hev og Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Lat det då verta verande i dykk, det som de høyrde frå upphavet; dersom det de høyrde frå upphavet, vert verande i dykk, so vert de og verande i Sonen og i Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Og dette er den lovnaden som han lova oss: det ævelege livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Dette hev eg skrive til dykk um deim som dårar dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Og den salving de fekk av honom, ho vert verande i dykk, og de treng ikkje til at nokon skal læra dykk noko; men liksom salvingi hans lærer dykk alt, so er det og sant og slett ikkje lygn; og vert verande i honom, so som ho lærde dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Og no, born, ver i honom, so me kann hava frimod når han vert openberra, og ikkje verta til skammar for honom i hans tilkoma!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Veit de at han er rettferdig, so skynar de at kvar den som gjer rettferd, er fødd av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Sjå, kor stor kjærleik Faderen hev synt oss, at me skal kallast Guds born; og det er me. Difor kjenner ikkje verdi oss, av di ho ikkje kjenner honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Mine kjære! No er me Guds born, og det er ikkje endå openberra kva me skal verta; me veit at når han vert openberra, då skal me verta honom like; for me skal sjå honom som han er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Og kvar den som hev denne voni til honom, han reinsar seg sjølv, liksom han er rein.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Kvar den som gjer synd, han gjer og lovbrot, og syndi er lovbrot.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Og de veit at han er openberra til å taka burt synderne, og det finst ikkje synd i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Kvar den som vert verande i honom, syndar ikkje; kvar den som syndar, han hev ikkje set honom og ikkje kjent honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Born, lat ingen dåra dykk! den som gjer rettferd, er rettferdig, liksom han er rettferdig.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Den som gjer synd, er av djevelen; for djevelen syndar frå upphavet. Til det er Guds son openberra, at han skal gjera ende på djevelens verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Kvar den som er fødd av Gud, gjer ikkje synd; for hans sæde vert verande i honom, og han kann ikkje synda; for han er fødd av Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'På det kann ein kjenna Guds born og djevelens born: kvar den som ikkje gjer rettferd, er ikkje av Gud, og ikkje den heller som ikkje elskar bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'For dette er den bodskapen som de høyrde frå upphavet, at me skal elska kvarandre;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'ikkje som Kain, som var av den vonde og drap bror sin. Og kvi drap han honom? Av di hans gjerningar var vonde, men hans brors gjerningar rettferdige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Undra dykk ikkje, mine brør, um verdi hatar dykk!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Me veit at me er gjengne yver frå dauden til livet, for me elskar brørne; den som ikkje elskar, vert verande i dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Kvar den som hatar bror sin, er ein manndråpar; og de veit at ingen manndråpar hev ævelegt liv verande i seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'På det hev me lært å kjenna kjærleiken, at han sette livet til for oss; me er og skuldige til å setja livet til for brørne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Men den som hev gods i denne verdi og ser bror sin hava trong og let hjarta sitt att for honom, kor kann då kjærleiken til Gud vera i honom!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Mine born, lat oss ikkje elska med ord eller med tunga, men i gjerning og sanning!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Og på dette skal me skyna at me er av sanningi, og so skal me roa hjarto våre for hans åsyn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'For um enn hjarta fordømer oss, so er Gud større enn hjarta vårt og kjenner alle ting.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mine kjære! dersom hjarta ikkje fordømer oss, so hev me fritt mod for Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'og det som me bed um, fær me av honom; for me held hans bod og gjer det som er honom til hugnad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Og dette er hans bod, at me skal tru på hans son Jesus Kristi namn og elska kvarandre, so som han baud oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Og den som held hans bod, han vert verande i honom og han i honom; og på dette veit me at han vert verande i oss, av den Ande som han hev gjeve oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mine kjære! tru ikkje på kvar ei ånd, men prøv ånderne, um dei er av Gud! for det er mange falske profetar gjengne ut i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'På det kjenner de Guds Ande: kvar ei ånd som sannar at Jesus Kristus er komen i kjøt, er av Gud;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'og kvar ei ånd som ikkje sannar at Jesus Kristus er komen i kjøt, er ikkje av Gud; og dette er åndi til Antikrist, som de hev høyrt um at ho kjem, og ho er alt no i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Born, de er av Gud og hev sigra yver deim; for han som er i dykk, er større enn han som er i verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Dei er av verdi; difor talar dei av verdi, og verdi høyrer deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Me er av Gud; den som kjenner Gud, høyrer oss; den som ikkje er av Gud, høyrer oss ikkje. På dette kjenner me sannings-åndi og villfarings-åndi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Mine kjære, lat oss elska kvarandre! for kjærleiken er av Gud, og kvar den som elskar, er fødd av Gud og kjenner Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Den som ikkje elskar, kjenner ikkje Gud; for Gud er kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'I det er Guds kjærleik openberra millom oss, at Gud hev sendt son sin, den einborne, til verdi, so me skal liva ved honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'I dette er kjærleiken, ikkje at me hev elska Gud, men at han hev elska oss og sendt son sin til soning for synderne våre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Mine kjære! hev Gud elska oss soleis, so er me og skuldige til å elska kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Ingen hev noko sinn set Gud; elskar me kvarandre, so vert Gud verande i oss, og kjærleiken til honom hev vorte fullkomen i oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'På dette kjenner me at me er i honom og han i oss, at han hev gjeve oss av sin Ande.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Og me hev set og vitnar at Faderen hev sendt son sin til frelsar for verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Den som sannar at Jesus er Guds Son, i honom vert Gud verande, og han i Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Og me hev lært å kjenna og trutt på den kjærleiken Gud hev til oss. Gud er kjærleik, og den som vert verande i kjærleiken, vert verande i Gud, og Gud i honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'I dette hev kjærleiken vorte fullkomen hjå oss, at me hev fritt mod på domedag; for liksom han er, so er me og i denne verdi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Otte er ikkje i kjærleiken, men den fullkomne kjærleiken driv otten ut; for otten hev straffi i seg; men den som ottast, er ikkje fullkomen i kjærleiken.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Me elskar av di han elska oss fyrst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Dersom nokon segjer: «Eg elskar Gud», og han hatar bror sin, han er ein ljugar; for den som ikkje elskar bror sin som han hev set, kor kann han elska Gud, som han ikkje hev set?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Og dette bodet hev me frå honom, at den som elskar Gud, han skal og elska bror sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Kvar den som trur at Jesus er Kristus, han er fødd av Gud; og kvar den som elskar Faderen, han elskar og den som er fødd av honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'På dette kjenner me at me elskar Guds born, når me elskar Gud og held hans bod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'For dette er kjærleiken til Gud, at me held hans bod; og hans bod er ikkje tunge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'For alt som er født av Gud, det sigrar yver verdi; og dette er den siger som hev sigra yver verdi: vår tru.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kven er det som sigrar yver verdi, utan den som trur at Jesus er Guds son?');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Han er den som kom med vatn og blod, Jesus Kristus, ikkje berre med vatnet, men med vatnet og blodet. Og Anden er den som vitnar, for Anden er sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'For dei er tri som vitnar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Anden og vatnet og blodet, og desse tri gjeng ut på eitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Dersom me tek imot vitnemål av menneski, so er Guds vitnemål større; for dette er Guds vitnemål, at han hev vitna um son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Den som trur på Guds son, hev vitnemålet i seg sjølv; den som ikkje trur Gud, han hev gjort honom til ein ljugar, med di han ikkje hev trutt på det vitnemålet som Gud hev vitna um son sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Og dette er vitnemålet, at Gud hev gjeve oss ævelegt liv, og dette livet er i son hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Den som hev Sonen, han hev livet; den som ikkje hev Guds son, han hev ikkje livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Dette hev eg skrive til dykk, so de skal vita at de hev ævelegt liv, de som trur på Guds sons namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Og dette er den frimodige tiltru me hev til honom, at dersom me bed um noko etter hans vilje, so høyrer han oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Og dersom me veit at han høyrer oss, kva me so bed um, so veit me at me hev dei ting som me hev bede honom um.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Dersom nokon ser bror sin gjera ei synd som ikkje er til dauden, so skal han beda, og han skal gjeva honom liv, ja deim då, som ikkje syndar til dauden. Det finst synd til dauden; for henne segjer eg ikkje at han skal gjera bøn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'All urettferd er synd, og det finst synd som ikkje er til dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Me veit at kvar den som er fødd av Gud, han syndar ikkje; men den som er fødd av Gud, varar seg, og den vonde rører honom ikkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Me veit at me er av Gud, og all verdi ligg i det vonde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Men me veit at Guds son er komen og hev gjeve oss skyn til å kjenna den Sanne; og me er i den Sanne, i hans son Jesus Kristus. Han er den sanne Gud og det ævelege livet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Born, vara dykk for avgudarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Den eldste til den utvalde fru og borni hennar, som eg elskar i sanning, og ikkje berre eg, men alle dei med som hev lært å kjenna sanningi,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'for den sanning skuld som vert verande i oss og skal vera med oss til æveleg tid:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Nåde, miskunn, fred skal vera med oss frå Gud Fader og frå Jesus Kristus, Faderens son, i sanning og kjærleik!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Eg hev gledt meg storleg yver at eg hev funne nokre av borni dine som ferdast i sanning, so som me fekk bod av Faderen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Og no bed eg deg, fru, ikkje som um eg skreiv deg eit nytt bod, men det som me hadde frå upphavet: at me skal elska kvarandre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Og dette er kjærleiken, at me ferdast etter hans bod. Dette er bodet, so som de høyrde det frå upphavet, at de skal ferdast etter det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'For mange forførarar hev gjenge ut i verdi, som ikkje sannar at Jesus er Kristus komen i kjøt. Dette er forføraren og Antikrist.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Vara dykk at de ikkje skal missa det de hev arbeidt dykk til, men må få full løn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Den som gjeng på avveg og ikkje held ved i Kristi læra, han hev ikkje Gud; den som held ved i læra, han hev både Faderen og Sonen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Dersom det kjem nokon til dykk og ikkje fører denne læra, so tak honom ikkje inn i huset, og bjod honom ikkje velkomen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'For den som byd honom velkomen, vert medskuldig med honom i hans vonde verk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Endå eg hev mykje å skriva til dykk, vil eg ikkje gjera det med papir og blekk; men eg vonar å koma til dykk og tala munnleg med dykk, so vår gleda kann verta fullkomi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Borni til di utvalde syster helsar deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Den eldste til den kjære Gaius, som eg elskar i sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Kjære ven! Eg ynskjer at du i alle måtar må liva vel og hava helsa, liksom di sjæl liver vel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'For eg vart mykje glad då det kom nokre brør og vitna um di sanning, korleis du ferdast i sanning.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Eg hev ingi større gleda enn det, at eg høyrer mine born ferdast i sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Kjære ven, du gjer ei trufast gjerning med det du gjer mot brørne, og det jamvel mot dei framande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'og dei hev vitna for kyrkjelyden um din kjærleik. Du gjer vel um du hjelper deim i veg, som det er sømelegt for Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'For det er for hans namn skuld dei er gjengne ut, og dei tek ikkje imot noko av heidningarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Me er då skuldige til å taka imot slike, so me kann verta medarbeidarar for sanningi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Eg hev skrive til kyrkjelyden; men Diotrefes, som gjerne vil vera fyrstemannen millom deim, tek ikkje imot oss.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Difor vil eg, når eg kjem, minna um dei gjerningar som han gjer, med di han baktalar oss med vonde ord; og ikkje nøgd med det, tek han ikkje sjølv imot brørne, og deim som det vil, hindrar han og støyter deim ut or kyrkjelyden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Kjære, gjer ikkje etter det vonde, men etter det gode! den som gjer godt, er av Gud; den som gjer vondt, hev ikkje set Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrius hev godt lov av alle og av sjølve sanningi; ogso me gjev honom godt vitnemål, og du veit at vårt vitnemål er sant.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Eg hadde mangt å skriva til deg, men eg vil ikkje skriva til deg med blekk og penn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Men eg vonar å få sjå deg snart, og då skal me talast ved munn til munn. Fred vere med deg! Venerne helsar deg. Helsa venerne med namn!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, Jesu Kristi tenar og Jakobs bror, til deim som er kalla, som er elska i Gud Fader og berga åt Jesus Kristus:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Miskunn og fred og kjærleik vere med dykk i rikt mål!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Kjære vener! Medan eg gjorde meg all umak for å skriva til dykk um vår sams frelsa, såg eg meg nøydd til å skriva til dykk med påminning um å strida for den trui som ein gong er yvergjevi til dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'For nokre menneskje hev snikt seg inn, som denne domen er uppskriven for alt for lenge sidan: Ugudlege, som misbrukar vår Guds nåde til ukjurskap og neittar vår einaste husbond og Herre, Jesus Kristus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Men sidan de no ein gong veit alt, vil eg minna dykk um at Herren, då han hadde frelst folket ut or Egyptarland, sidan tynte deim som ikkje trudde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Og dei englar som ikkje heldt fast ved sitt høge stand, men gjekk ifrå sin eigen heim, deim held han i varetekt i ævelege lekkjor under myrkret til domen på den store dagen;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'liksom Sodoma og Gomorra og byarne der ikring, då dei på same vis som desse dreiv hor og for etter framandt kjøt, ligg der til eit fyredøme, lidande ein æveleg elds refsing.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Og like vel gjer desse like eins: med di dei gjeng i draumar, gjer dei kjøtet ureint, vanvyrder herredøme og spottar høge magter.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Men då yverengelen Mikael trætta med djevelen um Mose likam, våga han ikkje å segja ein spottande dom, men sagde: «Herren refse deg!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Men desse spottar det dei ikkje kjenner; men det dei av naturi skynar liksom dei vitlause dyr, med det tyner dei seg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Usæle dei! for dei hev gjenge Kains veg og kasta seg inn i Bileams villa for vinning skuld og er tynte ved Korahs upprør.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Desse er skamflekkjer ved dykkar kjærleiks-måltider, når dei utan blygsla sit i gilde med dykk og forar seg sjølve, vatslause skyer, som vert umdrivne av vindar, avlauva, fruktlause tre, tvo gonger utdøydde, upprykte med roti,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'ville havbåror som skumar ut si eigi skam, villfarande stjernor, som kolmyrkret er etla åt i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Desse var det og Enok, den sjuande frå Adam, spådde um då han sagde: «Sjå, Herren kjem med sine mange tusund heilage');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'for å halda dom yver alle og refsa alle ugudlege for alle deira ugudlege gjerningar som dei gjorde, og for alle dei harde ord som dei tala imot honom, dei ugudlege syndarar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Desse er folk som murrar og klagar yver lagnaden, endå dei fer etter sine lyster, og deira munn talar skrøytande ord, endå dei gjøler for folk for vinning skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Men de, kjære, kom i hug dei ord som fyrr er tala av vår Herre Jesu Kristi apostlar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'For dei sagde dykk, at i den siste tidi skal det koma spottarar, som fer etter sine ugudlege lyster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Desse er dei som skil seg ut, naturlege menneskje som ikkje hev ånd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Men de, kjære, uppbygg dykk sjølve på dykkar høgheilage tru! Bed i den Heilage Ande,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'og haldt dykk soleis i Guds kjærleik, medan de ventar på vår Herre Jesu Kristi miskunn til ævelegt liv!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Og sume skal de tala til rettes av di dei tvilar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'andre skal de frelsa med di de riv deim ut or elden, andre skal de miskunna med otte, so de hatar jamvel den kjolen som hev vorte urein av kjøtet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Men honom som er megtig til å halda dykk uppe so de ikkje snåvar, og føra dykk lytelause fram for sin herlegdom i fagnad,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'den einaste Gud, vår frelsar ved Jesus Kristus, vår Herre, honom høyrer herlegdom til og majestæt og velde og magt fyre all tid og no og i all æva. Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Jesu Kristi openberring, som Gud gav honom til å visa tenarane sine det som snart skal hendast; og han sende bod ved engelen sin og synte det i teikn for tenaren sin Johannes,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'som hev vitna um Guds ord og Jesu Kristi vitnemål, alt det han såg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Sæl er den som les og dei som høyrer det profetiske ord og gøymer det som stend skrive der; for tidi er nær!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes til dei sju kyrkjelydarne i Asia: Nåde vere med dykk og fred frå honom som er og som var og som kjem, og frå dei sju ånder som er framfor hans kongsstol,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'og frå Jesus Kristus, det truverdige vitnet, den fyrstefødde av dei daude og herren yver kongarne på jordi! Honom som elskar oss og hev fria oss frå synderne våre med sitt blod,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'og som hev gjort oss til eit kongerike, til prestar for Gud og sin Fader, honom tilhøyrer æra og magti i all æva! Amen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Sjå, han kjem med skyerne, og kvart auga skal sjå honom, ogso dei som hev gjenomstunge honom, og alle ætter på jordi skal gråta sårt for honom. Ja, Amen!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Eg er A og Å, segjer Herren Gud, han som er og som var og som kjem, den Allmegtige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Eg, Johannes, som er dykkar bror og luthavande i trengsla og i riket og i tolmodet i Jesus, eg var på den øyi som heiter Patmos, for Guds ord og Jesu vitnemål skuld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Eg var burtrykt i Anden på Herrens dag, og eg høyrde attanfor meg ei sterk røyst som av ein basun, som sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, '«Det du ser, skriv det upp i ei bok og send det til dei sju kyrkjelydarne, til Efesus og til Smyrna og til Pergamum og til Tyatira og til Sardes og til Filadelfia og til Laodikea!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Og eg snudde meg, so eg kunde sjå røysti som tala med meg, og då eg snudde meg, såg eg sju ljosestakar av gull,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'og midt imillom dei sju ljosestakarne ein som var lik ein menneskjeson, klædd i ein fotsid kjole og umbunden under bringa med eit gullbelte,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'og hovudet og håret hans var kvitt som kvit ull, som snø, og augo hans som eldsloge,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'og føterne hans var liksom skinande kopar, som dei var glødde i ein omn, og røysti hans var som ljod av mange vatn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Og han hadde sju stjernor i si høgre hand, og eit tvieggja kvast sverd gjekk ut or munnen hans, og hans åsyn var som soli når ho skin i si kraft.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Og då eg såg honom, fall eg ned for føterne hans som ein daud; og han lagde si høgre hand på meg og sagde:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, '«Ottast ikkje! eg er den fyrste og den siste og den livande; og eg var daud, og sjå, eg er livande i all æva! Og eg hev lyklarne til dauden og til helheimen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Skriv då det du såg, både det som er, og det som skal henda heretter,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'løyndomen med dei sju stjernorne som du såg i mi høgre hand, og dei sju gull-ljosestakarne! Dei sju stjernorne er englar for dei sju kyrkjelydarne, og dei sju ljosestakarne er dei sju kyrkjelydarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '«Skriv til engelen for kyrkjelyden i Efesus: Dette segjer han som held dei sju stjernorne i si høgre hand, han som gjeng midt imillom dei sju gull-ljosestakarne:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Eg veit um gjerningarne dine, og arbeidet ditt, og tolmodet ditt, og at du ikkje kann lida dei vonde, og du hev prøvt deim som segjer dei er apostlar, og ikkje er det, og hev funne at dei er ljugarar;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'og du hev tolmod og hev havt mykje å bera for mitt namn skuld, og du hev ikkje vorte trøytt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Men eg hev imot deg at du hev uppgjeve din fyrste kjærleik.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Kom difor i hug kvar du er fallen ifrå, og vend um og gjer dei fyrste gjerningarne! elles kjem eg snart yver deg og vil flytja ljosestaken din frå sin stad, um du ikkje umvender deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Men dette hev du, at du hatar gjerningarne åt nikolaitarne, som eg og hatar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne: Den som sigrar, honom vil eg gjeva å eta av livsens tre, som er i Guds Paradis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Og skriv til engelen for kyrkjelyden i Smyrna: Dette segjer den fyrste og den siste, han som var daud, og vart livande:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Eg veit um trengsla di og fatigdomen din - men du er rik - og spotti frå deim som segjer at dei er jødar, og ikkje er det, men er Satans synagoga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ottast ikkje for det du skal lida! Sjå, djevelen skal kasta nokre av dykk i fengsel, so de skal verta freista, og de skal hava trengsla i ti dagar. Ver tru til dauden, so skal eg gjeva deg livsens kruna!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne: Den som sigrar, han skal slett ikkje lida mein av den andre dauden!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Og skriv til engelen for kyrkjelyden i Pergamum: Dette segjer han som hev det tvieggja kvasse sverdet:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Eg veit kvar du bur: der som Satans kongsstol er, og du held fast ved mitt namn, og du forneitta ikkje mi tru, endå i dei dagar då Antipas var mitt true vitne, han som vart ihelslegen hjå dykk, der Satan bur.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Men eg hev nokre få ting imot deg: at du hev sume der som held fast ved Bileams læra, han som lærde Balak å leggja støyt for Israels born, å eta avgudsoffer og gjera hor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Soleis hev du og sume som held fast ved læra åt nikolaitarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Vend um! men um du ikkje det gjer, kjem eg snart yver deg og vil strida mot deim ved min munns sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne: Den som sigrar, honom vil eg gjeva å eta av det løynde manna, og eg vil gjeva honom ein kvit stein og eit nytt namn skrive på steinen, som ingen kjenner, utan den som fær det!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Og skriv til engelen for kyrkjelyden i Tyatira: Dette segjer Guds son, han som hev augo som eldsloge og føter som skinande kopar:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Eg veit um dine gjerningar og din kjærleik og di tenesta og di tru og tolmodet ditt og dei siste gjerningarne dine, som er fleire enn dei fyrste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Men eg hev imot deg at du let kvinna Jezabel råda, ho som segjer at ho er ei profetkvinna, og ho lærer og dårar mine tenarar til å driva hor og eta avgudsoffer.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Og eg gav henne tid til å venda um, men ho vil ikkje venda um frå sin hordom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Sjå, eg kastar henne på sjukelægje, og deim som driv hor med henne, i stor trengsla, dersom dei ikkje vender um frå sine gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Og borni hennar vil eg rykkja burt ved daude, og alle kyrkjelydarne skal sanna at eg er den som ransakar nyro og hjarto, og eg vil gjeva dykk kvar etter dykkar gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Men eg segjer dykk andre i Tyatira, alle som ikkje hev denne læra, og som ikkje kjenner Satans dypter - som dei segjer -: Eg vil ikkje leggja nokor onnor byrd på dykk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Berre haldt fast ved det de hev, til dess eg kjem!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Og den som sigrar og tek vare på mine gjerningar alt til enden, honom vil eg gjeva magt yver heidningarne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'og han skal styra deim med jarnstav, liksom ein knasar kruskjerald, so som eg og hev fenge det av min Fader;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'og eg vil gjeva honom morgonstjerna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '«Og skriv til engelen for kyrkjelyden i Sardes: Dette segjer han som hev dei sju Guds ånder og dei sju stjernorne: Eg veit um gjerningarne dine, at du hev namn av å liva, og du er daud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Vert vaken og styrk det andre, som var på veg til å døy! for eg hev ikkje funne gjerningarne dine fullkomne for min Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Kom difor i hug korleis du hev lært og høyrt, og tak vare på det og vend um! Dersom du då ikkje vaker, skal eg koma som ein tjuv, og du skal ikkje vita kva stund eg kjem yver deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Men du hev nokre få namn i Sardes som ikkje hev flekka klædi sine, og dei skal ganga med meg i kvite klæde; for dei er det verde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Den som sigrar, han skal verta klædd soleis i kvite klæde, og eg skal ikkje strjuka hans namn ut or livsens bok, og eg vil kjennast ved hans namn for min Fader og for hans englar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Og skriv til engelen for kyrkjelyden i Filadelfia: Dette segjer den Heilage, den Sannordige, han som hev Davids lykel, han som let upp, og ingen let att, og let att, og ingen let upp:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Eg veit um dine gjerningar. Sjå, eg hev sett framfyre deg ei opna dør, og ingen kann lata henne att; for du hev liti kraft, og hev like vel halde mitt ord og ikkje forneitta mitt namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Sjå, eg let nokre av Satans synagoga koma, som segjer dei er jødar, og ikkje er det, men lyg; sjå, eg vil gjera so at dei skal koma og falla ned for føterne dine og kjenna at eg hev elska deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Sidan du hev teke vare på mitt ord um tolmod, so vil eg og halda deg fri frå den freistings stund som skal koma yver all heimen til å freista deim som bur på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Eg kjem snart; haldt fast på det du hev, so ingen skal taka kruna di!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Den som sigrar, honom vil eg gjera til ein pilar i min Guds tempel, og han skal aldri meir ganga ut derifrå, og eg vil skriva på honom min Guds namn og namnet på min Guds by, det nye Jerusalem, det som kjem ned frå himmelen frå min Gud, og mitt namn det nye.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Og skriv til engelen for kyrkjelyden i Laodikea: Dette segjer han som er amen, det truverdige og sannordige vitnet, upphavet til Guds skapning:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Eg veit um dine gjerningar, at du er korkje kald eller varm. Gjev du var kald eller varm!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Men so, då du er lunka og korkje kald eller varm, vil eg spy deg ut or munnen min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Sidan du segjer: «Eg er rik og hev ovnøgd og treng ingen ting», og du veit ikkje at du er arm og ynkeleg og fatig og blind og naken,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'so råder eg deg til å kjøpa av meg gull som er glødt i eld, so du kann verta rik, og kvite klæde, so du kann klæda deg med deim, og skammi av din nakenskap ikkje skal verta synberr, og salva augo dine med augnesalve, so du kann sjå!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Alle deim som eg elskar, deim refser og tuktar eg. Ver difor ihuga og vend um!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Sjå, eg stend for døri og bankar på; dersom nokon høyrer mi røyst og let upp døri, so vil eg ganga inn til honom og halda nattverd med honom, og han med meg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Den som sigrar, honom vil eg gjeva å sitja med meg på min kongsstol, liksom og eg hev sigra og sett meg med min Fader på hans kongsstol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Den som hev øyra, han høyre kva Anden segjer til kyrkjelydarne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Deretter såg eg, og sjå, det var ei dør opna i himmelen, og den fyrste røysti som eg hadde høyrt liksom ein basun som tala med meg, sagde: «Stig upp her, so skal eg syna deg det som skal hendast heretter!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Straks var eg burtrykt i Anden, og sjå, ein kongsstol stod i himmelen, og det sat ein på stolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Og han som sat der, var sjåande til liksom jaspis og sarderstein, og det var ein regnboge rundt um stolen, å sjå til liksom smaragd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Og rundt ikring stolen var det fire og tjuge stolar, og på stolarne såg eg fire og tjuge eldste sitjande, klædde i kvite klæde, og dei hadde gullkrunor på hovudi sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Og frå stolen for det ut ljoneldar og røyster og toredunar, og framfor stolen brann sju eldkyndlar, som er dei sju Guds ånder.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Og framfor stolen var det eit glashav likt krystall, og midt fyre stolen og rundt um stolen er det fire livende, uppfyllte med augo framantil og attantil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Og den fyrste livendet er likt ei løva, og det andre livendet er likt ein ukse, og det tridje livendet hev åsyn som eit menneskje, og det fjorde livendet er likt ei fljugande ørn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Og dei fire livendi hadde, kvart for seg, seks vengjer; rundt ikring og innantil var dei uppfyllte med augo, og dei held ikkje upp dag eller natt med å segja: «Heilag, heilag, heilag er Herren, Gud den allmegtige, han som var og som er og som kjem!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Og når dei fire livendi gjev æra og pris og takk åt honom som sit på stolen, og som liver i all æva,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'so fell dei fire og tjuge eldste ned for honom som sit på stolen, og tilbed honom som liver i all æva, og kastar krunorne sine ned for stolen og segjer:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '«Verdig er du, Herre, til å få æra og pris og magt! for du skapte alle ting, og for din vilje skuld var dei til og vart dei skapte!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Og eg såg i den høgre handi hans som sat på stolen ei bok med skrift på innsida og utsida og forsigla med sju innsigle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Og eg såg ein veldug engel, som ropa ut med høg røyst: «Kven er verdig til å opna boki og brjota hennar innsigle?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Og ingen i himmelen eller på jordi eller under jordi kunde opna boki eller sjå i henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Då gret eg sårt, av di ingen vart funnen verdig til å opna boki eller sjå i henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Og ein av dei eldste segjer til meg: «Gråt ikkje! sjå, løva som er av Juda ætt, Davids rotrenning, hev sigra og kann opna boki og brjota hennar sju innsigle.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Og eg såg at midt imillom stolen og dei fire livendi og midt imillom dei eldste stod eit lamb, liksom slagta, og det hadde sju horn og sju augo, det er dei sju Guds ånder som er utsende yver all jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Og det kom og tok boki or den høgre handi hans som sat på stolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Og då det tok boki, fall dei fire livendi og dei fire og tjuge eldste ned for Lambet, og dei hadde kvar si harpa og gullskåler fulle med røykjelse, som er bønerne frå dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Og dei syng ein ny song og segjer: «Du er verdig til å taka boki og opna hennar innsigle, av di du vart slagta og med ditt blod kjøpte oss åt Gud av alle ætter og tungemål og folk og landslydar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Og du gjorde deim til eit kongerike og til prestar for vår Gud, og dei skal vera kongar på jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Og eg såg, og eg høyrde ei røyst av mange englar ikring stolen og dei fire livendi og dei eldste; og talet på deim var ti tusund gonger ti tusund og tusund gonger tusund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Og dei sagde med høg røyst: «Lambet som er slagta, er verdigt til å få magt og rikdom og visdom og styrke og pris og æra og velsigning!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Og kvar skapning som er i himmelen og på jordi og under jordi og på havet, og alt det som er i deim, høyrde eg segja: «Honom som sit på stolen, og Lambet tilhøyrer velsigning og pris og æra og magt i all æva!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Og dei fire livendi sagde: «Amen!» Og dei fire og tjuge eldste fall ned og tilbad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Og eg såg då Lambet opna eit av dei sju innsigli, og eg høyrde eit av dei fire livendi segja som med torerøyst: «Kom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Og eg såg, og sjå, ein kvit hest; og han som sat på honom, hadde ein boge, og det vart gjeve honom ei kruna, og han drog ut med siger og til siger.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Og då det opna det andre innsiglet, høyrde eg det andre livendet segja: «Kom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Og det kom ut ein annan hest, som var raud, og honom som sat på honom, vart det gjeve å taka freden burt frå jordi, og at dei skulde slagta kvarandre; og det var gjeve honom eit stort sverd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Og då det opna det tridje innsiglet, høyrde eg det tridje livendet segja; «Kom!» Og eg såg, og sjå, ein svart hest; og han som sat på honom, hadde ei vegt i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Og eg høyrde liksom ei røyst midt imillom dei fire livendi, som sagde: «Eit mål kveite for ein pening, og tri mål bygg for ein pening; men oljen og vinen skal du ikkje skada.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Og då det opna det fjorde innsiglet, høyrde eg røysti av det fjorde livendet, som sagde: «Kom!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Og eg såg, og sjå, ein gul hest; og han som sat på honom, hans namn var Dauden, og helheimen fylgde med honom: og det vart gjeve deim magt yver fjordeparten av jordi til å drepa med sverd og med svolt og med sott og ved villdyri på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Og då det opna det femte innsiglet, såg eg under altaret deira sjæler som var myrde for Guds ord og det vitnemål skuld som dei hadde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Og dei ropa med høg røyst og sagde: «Herre, du heilage og sannordige, kor lenge drygjer du fyrr du held dom og hemner blodet vårt på deim som bur på jordi?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Og det vart gjeve deim kvar ein lang, kvit kjole, og det vart sagt deim at dei skulde slå seg til ro endå ei liti stund, til dess talet vart fullt på deira medtenarar og brør som skulde verta ihelslegne liksom dei.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Og eg såg då det opna det sette innsiglet, og sjå, det vart ein stor jordskjelv, og soli vart svart som ein hårsekk, og månen vart som blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Og stjernorne på himmelen fall ned på jordi, liksom eit fiketre kastar sine umogne fikor ned når det vert rist av sterk vind.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Og himmelen kvarv i hop som ein bokrull som vert samanrulla, og kvart fjell og kvar øy vart flutt frå sin stad.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Og kongarne på jordi og stormennerne og herhovdingarne og dei rike og dei velduge og kvar træl og kvar fri mann gøymde seg i holor og i berghamrar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Og dei segjer til fjelli og hamrarne: «Fall yver oss og gøym oss for hans åsyn som sit på kongsstolen og for vreiden til Lambet!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'For deira store vreide-dag er komen, og kven kann standa seg?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Deretter såg eg fire englar som stod på dei fire hyrno av jordi og heldt dei fire vindarne på jordi, so ingen vind skulde blåsa yver jordi eller yver havet eller på noko tre.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Og eg såg ein annan engel, som steig upp frå solovringi og hadde den livande Guds innsigle; og han ropa med høg røyst til dei fire englar som det var gjeve å skada jordi og havet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'og sagde: «Skad ikkje jordi eller havet eller trei, fyrr me fær sett innsigle på vår Guds tenarar i deira pannor!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Og eg høyrde talet på deim som hadde fenge innsigle: eit hundrad og fire og fyrti tusund med innsigle utav alle ætter av Israels born:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'av Juda-ætti tolv tusund med innsigle, av Ruben-ætti tolv tusund, av Gads-ætti tolv tusund,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'av Assers-ætti tolv tusund, av Naftali-ætti tolv tusund, av Manasse-ætti tolv tusund,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'av Simeons-ætti tolv tusund, av Levi-ætti tolv tusund, av Issakars-ætti tolv tusund,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'av Sebulons-ætti tolv tusund, av Josefs-ætti tolv tusund, og av Benjamins-ætti tolv tusund med innsigle.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Deretter såg eg, og sjå: ein stor skare som ingen kunde telja, av alle folk og ætter og landslydar og tungemål, som stod framfor kongsstolen og Lambet, klædde i lange kvite klæde og med palmegreiner i henderne,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'og dei ropa med høg røyst og sagde: «Frelsa høyrer til vår Gud, som sit på kongsstolen, og Lambet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Og alle englarne stod rundt um stolen og um dei eldste og dei fire livendi, og dei fall ned for stolen på sitt andlit og tilbad Gud');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'og sagde: «Amen! Velsigning og æra og visdom og takk og pris og magt og styrke høyrer til vår Gud i all æva! Amen.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Og ein av dei eldste tok til ords og sagde til meg: «Desse som er klædde i dei lange kvite kjolarne, kven er dei, og kvar er dei komne ifrå?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Eg sagde til honom: «Herre, du veit det.» Og han sagde til meg: «Dette er dei som kjem ut or den store trengsla, og dei hev tvege kjolarne sine og gjort deim kvite i blodet av Lambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Difor er dei for Guds kongsstol og tener honom dag og natt i hans tempel; og han som sit på stolen, skal reisa sin bustad yver deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Dei skal ikkje lenger hungra og ikkje lenger tyrsta; ikkje heller skal soli falla på deim eller nokon hite;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'for Lambet som er midt framfor kongsstolen, skal vakta deim og leida deim til livsens vatskjeldor, og Gud skal turka kvar tåra frå augo deira.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Og då det opna det sjuande innsiglet, vart det stilt i himmelen umkring ein halv time.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Og eg såg dei sju englarne som stend for Guds åsyn, og det vart gjeve deim sju basunar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Og ein annan engel kom og stod ved altaret, og han hadde eit røykjefat av gull, og det vart gjeve honom mykje røykjelse, som han skulde leggja til bønerne frå alle dei heilage på det gullaltaret som var framfor stolen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Og røyken av røykjelsen steig frå engelens hand upp for Gud med bønerne frå dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Og engelen tok røykjefatet og fyllte det med eld frå altaret og kasta det på jordi; og det kom toredunar og røyster og ljoneldar og jordskjelv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Og dei sju englarne som hadde dei sju basunarne, gjorde seg ferdige til å blåsa i deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Og den fyrste engelen bles. Og det kom hagl og eld, blanda med blod, og vart kasta ned på jordi; og tridjeparten av jordi vart uppbrend, og tridjeparten av trei vart uppbrend, og alt grønt gras vart uppbrend.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Og den andre engelen bles. Og det vart liksom eit stort fjell, brennande i eld, kasta i havet; og tridjeparten av havet vart til blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Og so døydde tridjeparten av dei skapningar i havet som hadde liv, og tridjeparten av skipi gjekk under.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Og den tridje engelen bles. Og frå himmelen fall ei stor stjerna, brennande som ein kyndel, og ho fall på tridjeparten av elvarne og på vatskjeldorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Og namnet på stjerna var malurt, og tridjeparten av vatnet vart til malurt, og mange menneskje døydde av vatnet, då det hadde vorte beiskt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Og den fjorde engelen bles. Og tridjeparten av soli vart slegen, og tridjeparten av månen og tridjeparten av stjernorne, so tridjeparten av deim skulde verta formyrkt, og tridjeparten av dagen missa ljoset sitt, og natti like eins.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Og eg såg, og eg høyrde ein ørn som flaug under det høgste av himmelen og sagde med høg røyst: «Usæle, usæle, usæle dei som bur på jordi, for dei andre basunrøyster av dei tri englar som endå skal blåsa!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Og den femte engelen bles. Og eg såg eg ei stjerna som hadde falle frå himmelen ned på jordi, og ho fekk lykelen til avgrunnsbrunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Og ho opna avgrunnsbrunnen, og ein røyk steig upp or brunnen, lik røyken av ein stor omn, og soli og lufti vart myrkte av røyken frå brunnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Og or røyken kom grashoppar ut på jordi, og det vart gjeve deim magt, slik som skorpionarne på jordi hev,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'og det vart sagt deim at dei ikkje måtte skada graset på jordi eller noko grønt eller noko tre, men berre dei menneskje som ikkje hadde Guds innsigle på pannorne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Og det vart gjeve deim at dei ikkje skulde drepa deim, men pina deim i fem månader; og pinsla av deim var som pinsla av ein skorpion når han sting eit menneskje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Og i dei dagar skal folk søkja dauden og ikkje finna honom, og stunda etter å døy, og dauden skal fly frå deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Og grashopparne såg ut som hestar, tilbudde til strid; og på hovudi deira var det liksom krunor av gull, og andliti deira var som menneskjeandlit.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Og dei hadde hår som kvendehår, og tennerne deira var som løvetenner.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Og dei hadde brynjor liksom jarnbrynjor, og ljoden av vengjerne deira var som ljod av vogner når mange hestar renner til strid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Og dei hadde stertar liksom skorpionar, og det var broddar i stertarne deira, og dei hadde magt til å skada menneski fem månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Til konge yver seg hev dei avgrunnsengelen, hans namn er på hebraisk Abaddon, og på gresk hev han namnet Apollyon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Det fyrste usæle er yverstade; sjå, det kjem tvo usæle etter dette!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Og den sette engelen bles. Og eg høyrde ei røyst frå dei fire horni på det gullaltaret som stod framfor Gud,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'og ho sagde til den sette engelen, som hadde basunen: «Løys dei fire englarne som er bundne ved den store elvi Eufrat!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Og dei fire englarne vart løyste, dei som hadde vore ferdige på timen og dagen og månaden og året til å drepa tridjeparten av menneski.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Og talet på herarne av hestfolk var tvo gonger ti tusund gonger ti tusund; eg høyrde talet på deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Og soleis såg eg i syni hestarne og deim som sat på deim: dei hadde eldraude og myrkraude og svåvelgule brynjor; og hovudi på hestarne var som løvehovud, og or munnarne deira fer det ut eld og røyk og svåvel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Av desse tri: elden og røyken og svåvelet, som for ut or munnarne deira, vart tridjeparten av menneski drepen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'For magti åt hestarne ligg i munnen deira og halen deira, for halarne deira er som ormar og hev hovud, og med deim gjer dei skade.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Og dei andre menneskje, som ikkje vart drepne i desse plågorne, vende ikkje um frå dei verki deira hender hadde gjort, so dei heldt upp med å tilbeda dei vonde ånder og avgudarne av gull og av sylv og av kopar og av stein og av tre, som korkje kann sjå eller høyra eller ganga.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Og dei vende ikkje um frå mordgjerningarne sine eller frå trolldomskunsterne sine eller frå hordomen sin eller frå tjuvskapen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Og eg såg ein annan veldug engel stiga ned frå himmelen, sveipt i ei sky, og regnbogen var yver hovudet hans, og hans åsyn var som soli, og føterne hans som eldstolpar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Og han hadde i handi ei liti opna bok, og han sette sin høgre fot på havet og den vinstre på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Og han ropa med høg røyst, som ei løva burar, og då han hadde ropa, tala dei sju toredunar med sine røyster.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Og då dei sju toredunar hadde tala med sine røyster, vilde eg til å skriva; og eg høyrde ei røyst frå himmelen som sagde til meg: «Set innsigle for det som dei sju toredunar tala, og skriv det ikkje upp!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Og engelen, som eg såg standa på havet og på jordi, lyfte handi upp mot himmelen,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'og svor ved honom som liver i all æva, som skapte himmelen og det som er i honom, og jordi og det som er på henne, og havet og det som er i det, at det ikkje lenger skal vera nokor tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Men i dei dagar då røysti av den sjuande engelen vert høyrd, når han skal blåsa, då skal og Guds løyndom vera fullenda, so som han forkynte for tenarane sine, profetarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Og den røysti som eg hadde høyrt frå himmelen, tala atter med meg og sagde: «Gakk og tak den litle opne boki i handi på den engelen som stend på havet og på jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Og eg gjekk burt til engelen og sagde til honom: «Gjev meg den litle boki!» Og han sagde til meg: «Tak og et henne, og ho skal svida i magen din; men i munnen din skal ho vera søt som honning.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Og eg tok den litle boki or handi på engelen og åt henne, og ho var søt som honning i munnen min, men då eg hadde ete henne, sveid det i magen min.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Og dei segjer til meg: «Du skal atter spå um mange landslydar og folk og tungemål og kongar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Og det vart gjeve meg ei røyr liksom ein stav, med dei ordi: «Statt upp og mæl Guds tempel og altaret og deim som tilbed der!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Men fyregarden utanfor templet, lat honom vera og mæl honom ikkje! for han er gjeven åt heidningarne, og dei skal trøda ned den heilage byen i tvo og fyrti månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Og eg vil gjeva mine tvo vitne, at dei skal vera profetar i tusund og tvo hundrad og seksti dagar, klædde i sekk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Dette er dei tvo oljetrei og dei tvo ljosestakarne som stend framfor Herren yver jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Og dersom nokon vil gjera deim skade, so gjeng det eld ut or munnen deira og fortærer fiendarne deira; ja, dersom nokon vil gjera deim skade, skal han soleis verta drepen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Desse hev magt til å lata att himmelen, so de ikkje skal falla regn i dei dagar dei er profetar; og dei hev magt yver vatni til å umskapa deim til blod og til å slå jordi med allslag plåga, so ofte dei vil.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Og når dei hev fullført sitt vitnemål, skal det dyret som stig upp or avgrunnen, føra strid med deim og vinna på deim og drepa deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Og liki deira skal liggja på gatorne i den store byen, den som i åndeleg tyding vert kalla Sodoma og Egyptarland, der som og deira herre vart krossfest.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Og nokre av landslydarne og ætterne og tungemåli og folki skal sjå liki deira tri dagar og ein halv og ikkje lata liki deira verta lagde i grav.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Og dei som bur på jordi, skal gleda seg yver deim og fagna seg og senda kvarandre gåvor, av di desse tvo profetarne var til plåga for deim som bur på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Og etter dei tri dagar og ein halv kom det livs-ande frå Gud i deim, og dei stod på føterne, og ein stor otte fall på deim som såg deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Og dei høyrde ei høg røyst frå himmelen som sagde til deim: «Stig upp her!» Og dei steig upp til himmelen i skyi, og fiendarne deira såg deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Og i same stundi kom det ein stor jordskjelv, og tiandeparten av byen fall, og sju tusund mann vart drepne i jordskjelven; og dei andre vart forfærde og gav Gud i himmelen æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Det andre usæle er yverstade; sjå, det tridje usæle kjem snart.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Og den sjuande engelen bles. Og det vart høyrt høge røyster i himmelen, som sagde: «Kongedømet yver verdi er tilfalle vår Herre og den han salva, og han skal vera konge i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Og dei fire og tjuge eldste, som sit framfor Gud på stolarne sine, fall ned på sitt andlit og tilbad Gud');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'og sagde: «Me takkar deg, Herre Gud, du allmegtige, du som er og som var, at du hev teke di store magt og vorte konge.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Og heidningarne hev vorte vreide, og din vreide er komen, og den tid då dei daude skal dømast, og då du skal løna dine tenarar, profetarne og dei heilage og deim som ottast ditt namn, dei små og dei store, og då du skal øyda deim som øyder jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Og Guds tempel i himmelen vart upplate, og hans sambandskista vart sedd i templet hans; og det kom ljoneldar og røyster og toredunar og jordskjelv og stort hagl.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Og eit stort teikn vart set i himmelen: ei kvinna klædd med soli, og med månen under føterne, og på hovudet hadde ho ei kruna av tolv stjernor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Og ho var med barn og skreik i barnsnaud og i harde føderider.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Og eit anna teikn vart set i himmelen, og sjå: ein stor eldraud drake, som hadde sju hovud og ti horn og på hovudi sine sju krunor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Og sterten hans drog tridjeparten av stjernorne på himmelen med seg og kasta deim ned på jordi; og draken stod framfor kvinna som skulde føda, so han kunde gløypa barnet hennar når ho hadde født det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Og ho fødde eit gutebarn, som skal styra alle heidningarne med jarnstav, og barnet hennar vart upprykt til Gud og til hans kongsstol.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Og kvinna flydde ut i øydemarki, der ho hev ein stad som Gud hev laga til åt henne, for at dei skal næra henne der i tusund tvo hundrad og seksti dagar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Og det vart ein strid i himmelen: Mikael og hans englar stridde med draken, og draken stridde, og hans englar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Og dei vann ikkje, og deira stad vart ikkje heller meir funnen i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Og den store draken vart kasta ned, den gamle ormen, han som vert kalla djevelen og Satan, han som dårar heile verdi; han vart kasta ned på jordi, og englarne hans vart kasta ned med honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Og eg høyrde ei høg røyst i himmelen, som sagde: «Frå no eig vår Gud frelsa og krafti og riket, og den han salva, hev magti; for klagaren mot brørne våre er kasta ned, han som klaga deim for vår Gud dag og natt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Og dei hev vunne yver honom i kraft av blodet av Lambet og det ordet dei vitna; og dei hadde ikkje livet sitt kjært, alt til dauden.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Difor fagna dykk, de himlar, og de som bur i deim! Usæle jordi og havet! for djevelen hev fare ned til dykk i stor vreide, då han veit at han berre hev ei liti tid.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Og då draken såg at han var nedkasta til jordi, forfylgde han kvinna som hadde født guten.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Og dei tvo vengjerne på den store ørnen vart gjevne til kvinna, so ho skulde fljuga ut i øydemarki til sin stad, der ho fær si føda ei tid og tider og ei halv tid, langt ifrå augo på ormen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Og ormen spruta or gapet sitt vatn som ei elv etter kvinna, for å riva henne burt med elvi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Men jordi kom kvinna til hjelp, og jordi opna sin munn og svelgde elvi som draken spruta ut or gapet sitt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Og draken vart arg på kvinna og gjekk burt og skulde strida med dei andre av hennar ætt, dei som held Guds bod og hev Jesu vitnemål. Og eg stod på sanden ved havet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Og eg såg eit dyr stiga upp or havet, det hadde ti horn og sju hovud, og på horni sine ti krunor, og på hovudi sine spottings namn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Og dyret som eg såg, var likt ein leopard, og føterne på det var som på ein bjørn, og gapet som eit løvegap. Og draken gav det si kraft og sin kongsstol og stor magt.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Og eg såg eit av hovudi på det liksom såra til ulivs; og ulivssåret vart lækt, og all jordi undrast og fylgde etter dyret;');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'og dei tilbad draken for di han hadde gjeve dyret magt, og dei tilbad dyret og sagde: «Kven er lik dyret, og kven kann strida mot det?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Og det vart gjeve det ein munn som tala store og spottande ord, og det vart gjeve det magt til å halda på i tvo og fyrti månader.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Og det opna munnen sin til spottingar mot Gud, til å spotta hans namn og hans bustad, deim som bur i himmelen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Og det vart det gjeve å føra strid mot dei heilage og vinna på deim, og det vart gjeve det magt yver kvar ætt og kvar landslyd og kvart tungemål og kvart folk.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Og alle som bur på jordi, skal tilbeda det, kvar den som ikkje frå verdi vart grunnlagd, hev fenge namnet sitt skrive i livsens bok hjå Lambet som er slagta.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Dersom nokon hev øyra, so høyre han!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Um nokon fører i fengsel, han skal i fengsel. Um nokon drep med sverd, han skal drepast med sverd. Her er tolmodet og trui til dei heilage.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Og eg såg eit anna dyr stiga upp or jordi, og det hadde tvo horn liksom eit lamb, og tala liksom ein drake.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Og det brukar heile magti åt det fyrste dyret for augo på det, og gjer at jordi og dei som bur på henne, tilbed det fyrste dyret, som ulivssåret vart lækt på.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Og det gjer store teikn, so det endå fær eld til å falla ned frå himmelen på jordi for augo på menneski.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Og det dårar deim som bur på jordi, for dei teikn skuld som det hev fenge magt til å gjera for augo på dyret, med di det segjer til deim som bur på jordi, at dei skal gjera eit bilæte åt det dyret som hev såret av sverdet og vart i live.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Og det fekk magt til å gjeva dyrebilætet livs-ande, so dyrebilætet jamvel kunde tala, og gjera so, at alle dei som ikkje vilde tilbeda dyrebilætet, skulde drepast.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Og det gjer at alle, både små og store, rike og fatige, frie og trælar, fær eit merke på si høgre hand eller på panna si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'og at ingen kann kjøpa eller selja, utan den som hev merket, namnet på dyret eller talet for dette namnet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Her er det visdomen! Den som hev vit, han rekne ut talet til dyret; for det er talet for eit menneskje, og talet for det er seks hundrad og seks og seksti.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Og eg såg, og sjå: Lambet stod på Sionsfjellet og med det hundrad og fire og fyrti tusund, som hadde dess namn og dess Faders namn skrive på panna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Og eg høyrde ei røyst frå himmelen liksom ljoden av mange vatn og som ljoden av sterk tora, og eg høyrde ljod av harpespelarar som spela på harporne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Og dei song ein ny song framfor kongsstolen og for dei fire livendi og dei eldste; og ingen kunde læra songen, utan dei hundrad og fire og fyrti tusund, dei som er kjøpte frå jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Desse er dei som ikkje hev gjort seg ureine med kvende; for dei er som møyar. Desse er dei som fylgjer Lambet kvar helst det gjeng. Desse er kjøpte frå menneski til ei fyrstegrøda for Gud og Lambet,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'og i deira munn er ikkje funne svik; for dei er utan lyte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Og eg såg ein annan engel fljuga under det høgste av himmelen; han hadde eit ævelegt evangelium å forkynna deim som bur på jordi og alle folk og ætter og tungemål og landslydar,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'og han sagde med høg røyst: «Ottast Gud og gjev honom æra! for timen til hans dom er komen; og tilbed honom som gjorde himmelen og jordi og havet og vatskjeldorne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Og endå ein annan engel fylgde etter og sagde: «Falli, falli er Babylon, den store, ho som hev skjenkt alle folki av sin hordoms vreide-vin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Og endå ein tridje engel fylgde etter deim og sagde med høg røyst: «Dersom nokon tilbed dyret og bilætet av det og tek merket på panna si eller på handi si,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'so skal han og drikka av Guds vreide-vin, som er skjenkt ublanda i hans harms skål, og han skal verta pint med eld og svåvel for augo på dei heilage englar og Lambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Og røyken av pinsla deira stig upp i all æva, og dei hev ikkje kvila dag eller natt, dei som tilbed dyret og bilætet av det, og kvar ein som tek namnemerket til det.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Her er tolmodet til dei heilage, dei som held Guds bod og trui på Jesus.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Og eg høyrde ei røyst frå himmelen som sagde: «Skriv: Sæle er dei daude som døyr i Herren heretter! Ja, segjer Anden, dei skal kvila frå arbeidet sitt, for gjerningarne deira fylgjer med deim.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Og eg såg, og sjå: ei kvit sky, og på skyi sat ein som var lik ein menneskjeson, og han hadde ei gullkruna på hovudet og ein kvass sigd i handi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Og ein annan engel kom ut or templet og ropa med høg røyst til honom som sat på skyi: «Send ut sigden din og skjer! for timen til skurden er komen; for jordi er mogi til skurd.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Og han som sat på skyi, let sigden sin fara yver jordi, og jordi vart skori.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Og ein annan engel kom ut or templet i himmelen, og han hadde ein kvass sigd, han og.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Og endå ein annan engel kom ut frå altaret, og han hadde magt yver elden og ropa med høg røyst til honom som hadde den kvasse sigden: «Send ut den kvasse sigden din og skjer druvorne av vintreet på jordi; for beri på det er mogne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Og engelen let sigden sin fara yver jordi og skar frukti av vintreet på jordi og kasta henne i den store vinpersa til Guds vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Og vinpersa vart trødd utanfor byen, og det gjekk blod ut frå persa heilt upp til beisli på hestarne, so langt som tusund og seks hundrad stadier.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Og eg såg eit anna teikn i himmelen, stort og underlegt: sju englar, som hadde dei sju siste plågorne; for med deim er Guds vreide fullenda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Og eg såg liksom eit glashav, blanda med eld, og deim som hadde vunne siger yver dyret og yver bilætet av det og yver namnetalet på det, såg eg standa ved glashavet og halda Guds harpor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Og dei song songen åt Moses, Guds tenar, og songen åt Lambet og sagde: «Store og underlege er dine gjerningar, Herre Gud, du allmegtige! Rettferdige og sanne er dine vegar, du konge yver folki!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kven skulde ikkje ottast, Herre, og æra ditt namn? for einast du er heilag; for alle folki skal koma og tilbeda for di åsyn, for dine rettferdige domar hev vorte openberre!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Og deretter såg eg, og sjå: Templet med vitnemålstjeldet i himmelen vart opna,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'og dei sju englarne som hadde dei sju plågorne, kom ut or templet, klædde i reint og skinande linty og umbundne um bringa med gullbelte.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Og eit av dei fire livendi gav dei sju englarne sju gullskåler, fyllte med Guds vreide, hans som liver i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Og templet var fyllt med røyk av Guds herlegdom og av hans magt, og ingen kunde ganga inn i templet fyrr dei sju plågorne frå dei sju englarne var fullenda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Og eg høyrde ei høg røyst frå templet, som sagde til dei sju englarne: «Gakk og tøm dei sju skålerne med Guds vreide ut på jordi!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Og den fyrste gjekk og tømde si skål på jordi; og det kom ein vond og våleg svoll på dei menneskje som hadde merket åt dyret, og som tilbad bilætet av det.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Og den andre engelen tømde si skål i havet, og det vart til blod som av ein daud mann, og kvar livande sjæl i havet døydde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Og den tridje engelen tømde si skål i elvarne og vatskjeldorne, og det vart til blod.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Og eg høyrde engelen yver vatni segja: «Rettferdig er du som er og som var, du heilage, at du hev halde slik dom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'For blod av heilage og av profetar rende dei ut, og blod gav du deim å drikka; for dei er det verde.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Og eg høyrde altaret segja: «Ja, Herre Gud, du allmegtige! Sanne og rettferdige er dine domar!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Og den fjorde engelen tømde si skål på soli, og ho fekk magt til å brenna menneski med eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Og menneski vart brende av stor hite, og dei spotta Guds namn, hans som hev magt yver desse plågorne, og dei vende ikkje um, so dei gav honom æra.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Og den femte engelen tømde si skål yver kongsstolen til dyret; og riket til det vart formyrkt, og dei togg tungorne sine av pinsla,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'og dei spotta Gud i himmelen for pinslorne sine og svollarne sine, og vende ikkje um frå sine gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Og den sette engelen tømde si skål i den store elvi Eufrat, og vatnet hennar turka upp, so vegen skulde verta rudd for kongarne frå Austerland.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Og eg såg at det or munnen på draken og or munnen på dyret og or munnen på den falske profeten kom ut tri ureine ånder liksom paddor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'For dei er djevle-ånder som gjer teikn, og dei gjeng ut til kongarne i heile mannheimen til å sanka deim saman til striden på den store dagen åt Gud den allmegtige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Sjå, eg kjem som ein tjuv! Sæl er den som vaker og vaktar klædi sine, so han ikkje skal ganga naken, og dei skal sjå hans skam!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Og han førde deim saman til den stad som heiter på hebraisk Harmageddon.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Og den sjuande engelen tømde si skål i lufti, og ei høg røyst kom ut frå templet i himmelen, frå kongsstolen, og sagde: «Det er gjort!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Og der kom ljoneldar og røyster og toredunar, og det vart ein stor jordskjelv, ein slik at det, alt sidan menneskja vart til på jordi, ikkje hev vore ein sovoren jordskjelv, so stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Og den store byen vart kløyvd i tri partar, og byarne åt folki fall, og Babylon, den store, vart ihugkomi for Gud, at han skulde gjeva henne skåli med vinen av sin strenge vreide.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Og kvar øy kvarv burt, og fjell vart ikkje funne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Og stort hagl, som hundrad pund tungt, fall ned frå himmelen på menneski, og menneski spotta Gud for plåga av haglet; for den plåga var ovleg stor.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Og ein av dei sju englarne som hadde dei sju skålerne, kom og tala med meg og sagde: «Kom, eg skal visa deg domen yver den store skjøkja, som sit ved dei mange vatni,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'henne som kongarne på jordi hev hora med, og dei som bur på jordi, vart drukne av hennar hordoms vin.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Og han førde meg i åndi burt i ei øydemark, og eg såg ei kvinna sitja på eit skarlakraudt dyr, som var fullt med spottings namn og hadde sju hovud og ti horn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Og kvinna var klædd i purpur og skarlak og lyste av gull og dyre steinar og perlor; ho hadde i handi ei gullskål full med styggedom og med ureinska av hordomen hennar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Og på panna hennar var skrive eit namn, ein løyndom: Babylon, den store, mor åt skjøkjorne og styggedomarne på jordi.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Og eg såg kvinna fullskjenkt med blodet av dei heilage og med blodet av Jesu vitne, og eg undra meg storleg då eg såg henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Og engelen sagde til meg: «Kvi undra du deg? Eg vil segja deg løyndomen med kvinna og med dyret som ber henne, og som hev dei sju hovudi og ti horni.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Det dyret du såg, det var og er ikkje, og det skal stiga upp or avgrunnen og fara burt til undergang; og dei som bur på jordi, som ikkje hev namni sine skrivne i livsens bok frå verdi vart grunnlagd, dei skal undra seg når dei ser at dyret var og ikkje er og skal koma att.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Her spørst det um vitet som hev visdom! Dei sju hovudi er sju fjell, som kvinna sit på,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'og dei er sju kongar; dei fem er falne, den eine er til, den andre er ikkje komen endå; og når han kjem, skal han berre halda seg ei stutt tid.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Og dyret som var og ikkje er, det er sjølv den åttande og er og ein av dei sju og fer burt til undergang.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Og dei ti horni som du såg, er ti kongar som ikkje endå hev fenge rike, men dei fær magt som kongar ein time saman med dyret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Desse hev same tanken, og si kraft og magt gjev dei til dyret.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Desse skal strida mot Lambet, og Lambet skal vinna yver deim, for det er herren yver herrar og kongen yver kongar, og dei som er med det, dei som er kalla og utvalde og trufaste.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Og han sagde til meg: «Dei vatni som du såg der skjøkja sit, er landslydar og flokkar og folk og tungemål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Og dei ti horni som du såg, og dyret, desse skal hata skjøkja og gjera henne aud og naki, og kjøtet hennar skal dei eta, og henne sjølv skal dei brenna upp med eld.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'For Gud gav deim i hjarta å fullføra hans tanke og fullføra den eine og same tanken og gjeva dyret sitt rike, til dess Guds ord er fullførde.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Og kvinna som du såg, er den store byen som hev kongeveldet yver kongarne på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Deretter såg eg ein annan engel stiga ned frå himmelen; han hadde stor magt, og jordi vart upplyst av hans herlegdom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Og han ropa med sterk røyst og sagde: «Falli, falli er Babylon, den store, og ho hev vorte bustad for vonde ånder, eit fangebol for alle ureine ånder, og eit fangebol for alle ureine og styggjelege fuglar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'For av hennar hordoms vreide-vin hev alle folki drukke, og kongarne på jordi hev drive hor med henne, og kjøpmennerne på jordi hev vorte rike av hennar ovlivnads fylla.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Og eg høyrde ei onnor røyst frå himmelen, som sagde: «Gakk ut frå henne, de mitt folk, so de ikkje skal verta medskuldige i synderne hennar og ikkje få noko av plågorne hennar!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'For synderne hennar når heilt upp til himmelen, og Gud hev kome hennar urettferdige gjerningar i hug.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Gjev henne att som ho hev gjeve, og gjev henne tvifaldt etter hennar gjerningar! Skjenk henne tvifaldt i den skåli som ho hev skjenkt i!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'So mykje som ho hev æra seg sjølv og livt i ovlivnad, so mykje pinsla og sorg gjeve de henne! For ho segjer i sitt hjarta: «Eg sit som dronning og er ikkje enkja, og sorg skal eg ikkje sjå.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Difor skal plågorne hennar koma på ein dag: daude og sorg og svolt, og ho skal verta uppbrend med eld; for sterk er Herren Gud, som dømde henne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Og kongarne på jordi som hev drive hor og ovlivnad med henne, skal gråta og barma seg yver henne, når dei ser røyken av hennar brand,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'medan dei stend langt undan av otte for pinsla hennar og segjer: «Usæl, usæl du store by Babylon, du sterke by! at domen din er komen i ein time!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Og kjøpmennerne på jordi græt og syrgjer yver henne, av di ingen lenger kjøper varorne deira:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'varor av gull og sylv og dyre steinar og perlor og kostelegt linty og purpur og silke og skarlak og allslag angande tre og allslag kjerald av filsbein og allslag kjerald av dyrverdigt tre og kopar og jarn og marmor');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'og kanel og hårsalve og røykjelse og myrra og røykjeverk og vin og olje og fint mjøl og kveite og storfe og sauer og hestar og vogner og trælar og menneskje-sjæler.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Og den frukt som di sjæl hadde lyst til, er komi burt frå deg, og alt det feite og glimande er kome burt frå deg, og aldri skal nokon finna det meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Dei som handlar med desse ting, som hev vorte rike ved henne, skal standa langt undan av otte for pinsla hennar og gråta og syrgja');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'og segja: «Usæl, usæl den store byen, som var klædd i kostelegt linty og purpur og skarlak, og lyste av gull og dyre steinar og perlor; at so stor ein rikdom er øydd i ein time!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Og kvar styremann og kvar skipsførar og alle sjøfolk og alle dei som fer på havet, stod langt undan');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'og ropa då dei såg røyken av hennar brand, og sagde: «Kven er lik den store byen?»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Og dei kasta dust på hovudi sine og ropa med gråt og sorg og sagde: «Usæl, usæl den store byen, der alle som hadde skip på havet, vart rike av hennar eignaluter, at ho vart lagd i øyde i ein time!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Fagna deg yver henne, du himmel, og de apostlar og profetar, av di Gud hev halde dom for dykk yver henne!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Og ein veldug engel lyfte ein stein som ein stor kvernstein og kasta honom i havet og sagde: «So skal Babylon, den store byen, med hast verta nedkasta og ikkje meir verta funnen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Og ingen ljod av harpespelarar og songarar og fløytelåtarar og lurblåsarar skal lenger verta høyrd i deg, og ingen som driv nokor kunst, skal lenger verta funnen i deg, og ingen ljod av kvern lenger verta høyrd i deg.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Og ljos av lampa skal ikkje lenger skina i deg, og røyst av brudgom og brur ikkje lenger verta høyrd i deg; for dine kjøpmenner var storkararne på jordi, av di alle folk vart dåra ved din trolldom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Og i henne vart det funne blod av profetar og heilage og av alle deim som er myrde på jordi.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Deretter høyrde eg liksom ei høg røyst av ein stor skare i himmelen, som sagde: «Halleluja! Frelsa og æra og magti tilhøyrer vår Gud!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'For sanne og rettferdige er hans domar; for han hev dømt den store skjøkja, ho som øydelagde jordi med sin hordom, og han hev kravt blodet av sine tenarar ut or hennar hand!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Og dei sagde ein gong til: «Halleluja! Og røyken av henne stig upp i all æva.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Og dei fire og tjuge eldste og dei fire livendi fall ned og tilbad Gud, som sat på kongsstolen, og sagde: «Amen! halleluja!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Og det kom ei røyst ut frå kongsstolen og sagde: «Lova vår Gud, alle hans tenarar, og de som ottast honom, både små og store!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Og eg høyrde liksom ei røyst av ein stor skare, og som ein ljod av mange vatn, og som ein ljod av sterke toredunar, som sagde: «Halleluja! for Herren, Gud den allmegtige, hev vorte konge!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Lat oss gleda og fagna oss og gjeva honom æra, for brudlaupet åt Lambet er kome, og bruri hans hev butt seg til!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Og det er henne gjeve å klæda seg i reint og skinande fint linty; for det fine lintyet er dei rettferdige gjerningar av dei heilage.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Og han segjer til meg: «Skriv: Sæle er dei som er bedne til brudlaups-nattverden åt Lambet!» Og han segjer til meg: «Dette er Guds sanne ord.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Og eg fall ned for føterne hans og vilde tilbeda honom, og han segjer til meg: «Sjå til du ikkje gjer det! eg er medtenar til deg og brørne dine, som hev Jesu vitnemål. Tilbed Gud! For Jesus vitnemål er anden med profetordet.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Og eg såg himmelen opna, og sjå: ein kvit hest; og den som sat på honom, heiter «Trufast og sannordig», og han dømer og strider med rettferd.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Augo hans er som eldsloge, og på hovudet hans er det mange krunor; han hev eit namn skrive som ingen kjenner, utan han sjølv.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Og han er klædd i ein klædnad, duppa i blod, og hans namn er kalla: «Guds ord».');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Og herarne i himmelen fylgde honom på kvite hestar og klædde i kvitt og reint fint linty.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Og or munnen hans gjeng det ut eit kvast sverd til å slå heidningarne med, og han skal styra deim med jarnstav, og han trøder persa med den strenge vreide-vin frå Gud, den allmegtige.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Og han hev på sin klædnad og på si lend eit namn skrive: «Kongen yver kongar og herren yver herrar.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Og eg såg ein engel som stod i soli, og han ropa med høg røyst og sagde til alle fuglar som flyg under det høgste av himmelen: «Kom og sanka dykk til Guds store matmål:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'til å eta kjøt av kongar og kjøt av herhovdingar og kjøt av velduge og kjøt av hestar og kjøt av deim som sat på deim, og kjøt av alle, frie og trælar, små og store!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Og eg såg dyret og kongarne på jordi og herarne deira samankomne til å føra strid mot honom som sat på hesten, og mot hans her.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Og dyret vart gripe, og saman med det den falske profeten, han som for augo på det hadde gjort dei teikni han hadde dåra deim med som tok merket åt dyret og tilbad bilætet av det. Desse tvo vart kasta livande i eldsjøen som brenn med svåvel.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Og dei andre vart drepne med sverdet hans som sat på hesten, det som gjekk ut or munnen hans. Og alle fuglarne vart metta av kjøtet deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Og eg såg ein engel stige ned frå himmelen, som hadde lykelen til avgrunnen og ei stor lekkja i handi si.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Og han greip draken, den gamle ormen, som er djevelen og Satan, og batt honom for tusund år');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'og kasta honom i avgrunnen og læste honom inne og sette innsigle yver honom, so han ikkje lenger skulde dåra folki, til dess dei tusund år var fullenda. Og etter den tid skal han verta løyst ei liti stund.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Og eg såg stolar, og dei sette seg på deim, og det vart gjeve deim magt til å halda dom; og eg såg deira sjæler som var halshogne for Jesu vitnemål og Guds ord skuld, og deim som ikkje hadde tilbede dyret eller bilætet av det, og ikkje teke merket på panna si og på handi si; og dei vart livande og rådde saman med Kristus i tusund år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Men dei andre daude vart ikkje livande att, fyrr dei tusund år var fullenda. Dette er den fyrste uppstoda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Sæl og heilag er den som hev lut i den fyrste uppstoda; yver deim hev den andre dauden ingi magt, men dei skal vera Guds og Kristi prestar og råda saman med honom i tusund år.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Og når dei tusund åri er fullenda, skal Satan verta løyst ut or sitt fengsel,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'og han skal ganga ut og dåra folki ved dei fire jordhyrno, Gog og Magog, og føra deim saman til strid, og talet på deim er som havsens sand.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Og dei drog upp på den vide jordflata og kringsette lægret åt dei heilage og den byen som Gud elska. Og det fall eld ned ifrå himmelen frå Gud og øydde deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Og djevelen, som hadde dåra deim, vart kasta i sjøen med eld og svåvel, der dyret og den falske profeten var; og dei skal verta pinte dag og natt i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Og eg såg ein stor kvit kongsstol, og honom som sat derpå; og jordi og himmelen flydde frå hans åsyn, og det fanst ikkje nokon stad for deim.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Og eg såg dei daude, små og store, standa framfor Gud, og bøker vart opna, og ei onnor bok vart opna, det er livsens bok. Og dei daude vart dømde etter det som var skrive i bøkerne, etter gjerningarne sine.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Og havet gav att dei daude som var i det, og dauden og helheimen gav att dei daude som var i deim, og dei vart dømde kvar etter sine gjerningar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Og dauden og helheimen vart kasta i eldsjøen. Dette er den andre dauden: eldsjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Og dersom nokon ikkje vart funnen uppskriven i livsens bok, so vart han kasta i eldsjøen.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Og eg såg ein ny himmel og ei ny jord; for den fyrste himmelen og den fyrste jordi hadde kvorve burt, og havet er ikkje meir.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Og eg såg den heilage byen, det nye Jerusalem, stiga ned ifrå himmelen frå Gud, budd som ei brur som er prydd for brudgomen sin.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Og eg høyrde ei høg røyst frå kongsstolen, som sagde: «Sjå, Guds bustad er hjå menneski, og han skal bu hjå deim; og dei skal vera hans folk, og Gud sjølv skal vera hjå deim og vera deira Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Og han skal turka kvar tåra av augo deira, og dauden skal ikkje meir vera til, og ikkje sorg og ikkje skrik og ikkje pinsla skal meir vera til; for dei fyrste ting er burtfarne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Og han som sat på kongsstolen, sagde: «Sjå, eg gjer alle ting nye!» Og han segjer til meg: «Skriv! for desse ordi er truverdige og sanne.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Og han sagde til meg: «Det er gjort. Eg er A og Å, upphavet og enden. Eg vil gjeva den tyrste av kjelda med livsens vatn for inkje.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Den som sigrar, skal erva alle ting, og eg vil vera hans Gud, og han skal vera min son.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Men dei som er ræddhuga og vantruande og styggjelege og manndråparar og horkarar og trollmenner og avgudsdyrkarar og alle ljugarar, deira lut skal vera i sjøen som brenn med eld og svåvel; det er den andre dauden.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Og ein av dei sju englarne som hadde dei sju skålerne, fyllte med dei sju siste plågorne, kom til meg og tala med meg og sagde: «Kom, eg skal visa deg bruri, vivet til Lambet!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Og han førde meg i åndi burt på eit stort og høgt fjell og viste meg den heilage byen Jerusalem, som steig ned frå himmelen frå Gud.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Han hadde Guds herlegdom, og hans ljos var som av den kostelegaste stein, som krystallblank jaspis.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Og han hadde ein stor og høg mur, han hadde tolv portar, og på portarne tolv englar og innskrivne namn, som er namni på dei tolv ætter av Israels born:');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'mot aust tri portar, mot nord tri portar, mot sud tri portar, mot vest tri portar.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Og muren um byen hadde tolv grunnsteinar, og på deim namni på dei tolv apostlar åt Lambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Og han som tala med meg, hadde ei gullrøyr til å mæla byen og portarne og muren hans.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Og byen ligg i ein firkant, og lengdi på honom er so stor som breiddi. Og han mælte byen med røyri: tolv tusund stadier; lengd og breidd og høgd på honom er like.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Og han mælte muren um honom: eit hundrad og fire og fyrti alner, etter eit menneskjemål, som og er engle-mål.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Og muren var bygd av jaspis, og byen var av reint gull, lik reint glas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Og grunnsteinarne i bymuren var prydde med allslag dyre steinar: den fyrste grunnsteinen var jaspis, den andre safir, den tridje kalcedon, den fjorde smaragd,');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'den femte sardonyx, den sette sarder, den sjuande krysolit, den åttande beryll, den niande topas, den tiande krysopras, den ellevte hyacint, den tolvte ametyst.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Og dei tolv portarne var tolv perlor; kvar ein av portarne var av ei perla, og gata i byen var reint gull som klårt glas.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Og eg såg ikkje noko tempel i honom; for hans tempel er Herren, Gud den allmegtige, og Lambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Og byen treng ikkje soli eller månen til å skina åt seg; for Guds herlegdom upplyser honom, og Lambet er hans ljos.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Og folki skal ferdast i hans ljos, og kongarne på jordi ber sin herlegdom til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Og hans portar skal aldri verta stengde um dagen; for natt skal ikkje vera der.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Og dei skal bera herlegdomen og æra frå folki til honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Og inkje ureint skal koma inn i honom, og ingen som fer med styggedom og lygn; berre dei som er innskrivne i livsens bok hjå Lambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Og han viste meg ei elv med livsens vatn, som rann klår som krystall ut frå kongsstolen åt Gud og Lambet.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Midt imillom bygata og elvi, på båe sidor, stod livsens tre, som bar tolv gonger frukt og gav kvar månad si frukt. Og lauvet på treet var til helsebot for folki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Og ingi bannstøyting skal vera meir, og kongsstolen åt Gud og Lambet skal vera der, og hans tenarar skal tena honom.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Og dei skal sjå hans åsyn, og hans namn skal vera på panna deira.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Og natt skal det ikkje vera meir, og dei treng ikkje til ljos av lampa og ljos av sol, for Gud Herren skal lysa yver deim; og dei skal råda i all æva.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Og han sagde til meg: «Desse ord er truverdige og sanne; og Herren, den Gud som skifter ut sin Ande til profetarne, hev sendt sin engel til å syna tenarane sine det som snart skal henda.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Sjå, eg kjem snart! Sæl er den som tek vare på dei profetiske ord i denne boki.»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Og eg, Johannes, er den som såg og høyrde dette. Og då eg hadde høyrt og set, fall eg ned og vilde tilbeda for føterne til den engelen som synte meg dette.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Og han segjer til meg: «Sjå til du ikkje gjer det; for eg er medtenar til deg og brørne dine, profetarne, og til deim som tek vare på ordi i denne boki. Tilbed Gud!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Og han segjer til meg: «Du skal ikkje setja innsigle på dei profetiske ord i denne boki! for tidi er nær.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Lat den som gjer urett gjera urett framleides, og den ureine verta urein framleides, og den rettferdige gjera rettferd framleides, og den heilage verta helga framleides!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Sjå, eg kjem snart, og mi løn er med meg, til å gjeva kvar attergjeld, etter som hans gjerning er.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Eg er A og Å, upphavet og enden, den fyrste og den siste.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Sæle er dei som tvær kjolarne sine, so dei må få rett til livsens tre og koma inn i byen gjenom portarne.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Men utanfor er hundarne og trollmennerne og horkararne og manndråparane og avgudsdyrkarane og kvar som elskar og talar lygn.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Eg, Jesus, hev sendt min engel til å vitna dette for dykk um kyrkjelydarne. Eg er Davids rotrenning og ætt, den klåre morgonstjerna.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Og Anden og bruri segjer: «Kom!» Og den som høyrer det, segje: «Kom!» Og den som er tyrst, han kome, og den som vil, han take livsens vatn for inkje!»');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Eg vitnar for kvar som høyrer dei profetiske ordi i denne boki: Dersom nokon legg noko til dette, so skal Gud leggja på honom dei plågor som er skrivne i denne boki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Og dersom nokon tek noko burt frå ordi i denne profetiske boki, so skal Gud taka hans lut burt frå livsens tre og frå den heilage byen som det stend skrive um i denne boki.');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Han som vitnar dette, segjer: «Ja, eg kjem snart.» Amen, ja kom, Herre Jesus!');
INSERT INTO `NorSMB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Vår Herre Jesu Kristi nåde vere med dykk alle! Amen.');
